INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('AD', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"AD","iso3":"AND","nameEn":"Andorra","nameNative":"Andorra","region":"europe_central_asia","languages":["ca","es","fr","pt"],"currency":{"code":"EUR","symbol":"€","decimals":2,"compact":"intl","usdRate":{"value":0.8951,"status":"sourced","sourceName":"European Central Bank, euro reference exchange rate (USD)","sourceUrl":"https://www.ecb.europa.eu/stats/policy_and_exchange_rates/euro_reference_exchange_rates/html/eurofxref-graph-usd.en.html","asOf":"2026-10-30","note":"USD 1.1172 per EUR, so EUR 0.8951 per US dollar; World Bank 2025 average 0.887. Andorra uses the euro under a monetary agreement with the EU."}},"instruments":{"savings_account":{"available":true,"localName":"Compte d''estalvi","localNameEn":"Savings account","note":"No published rates found."},"fdr_3m":{"available":true,"localName":"Dipòsit a termini de 3 mesos","localNameEn":"3-month term deposit","note":"No published rates found."},"fdr_1y":{"available":true,"localName":"Dipòsit a termini d''1 any","localNameEn":"1-year term deposit","note":"No published rates found."},"dps":{"available":false,"localName":null,"note":"No monthly recurring deposit product found."},"sanchayapatra_5y":{"available":false,"localName":null,"note":"No government savings certificate or retail savings bond for individuals."},"tbill_91d":{"available":false,"localName":null,"note":"No treasury bill market for individuals was found."},"tbond_5y":{"available":false,"localName":"Deute públic","localNameEn":"Government bonds","note":"Government debt is placed with banks and institutional investors; no retail market or published yield was found."},"tbond_10y":{"available":false,"localName":"Deute públic","localNameEn":"Government bonds","note":"No retail market or published yield was found."},"equity_fund":{"available":true,"localName":"Organisme d''inversió col·lectiva","localNameEn":"Collective investment fund","note":"Funds supervised by the AFA; no local stock exchange, so equity funds invest abroad.","sourceUrl":"https://www.afa.ad/"},"gold":{"available":true,"localName":"Or físic","localNameEn":"Gold bars and coins","note":"No restriction on buying physical gold was found."}},"institutions":{"centralBank":{"name":"Andorran Financial Authority (Autoritat Financera Andorrana)","url":"https://www.afa.ad/","note":"Andorra has no central bank; it uses the euro (ECB policy) and the AFA supervises banks."},"insuranceRegulator":{"name":"Andorran Financial Authority (AFA) – insurance supervision","url":"https://www.afa.ad/ca/entitats-supervisades/assegurances"},"insuranceComplaints":{"name":"Andorran Financial Authority (AFA) – complaints","url":"https://www.afa.ad/ca/consumidors/reclamacions"},"pensionScheme":{"name":"Caixa Andorrana de Seguretat Social (CASS) – retirement pension","url":"https://www.cass.ad/prestacio-economica-jubilacio"},"oldAgeAllowance":{"name":"Solidarity pension for the elderly (Govern d''Andorra)","url":"https://www.govern.ad/ca/tematiques/ajuts-i-subvencions/gent-gran"},"publicHealthCover":{"name":"Caixa Andorrana de Seguretat Social (CASS) – health cover","url":"https://www.cass.ad/"},"depositInsurance":{"name":"Fons andorrà de garantia de dipòsits (FAGADI)","url":"https://www.afa.ad/ca/fons-de-garantia"},"statistics":{"name":"Departament d''Estadística, Govern d''Andorra","url":"https://www.estadistica.ad/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
