INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AD', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No monthly recurring deposit product with a published rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AD', 1, 'equity_return_base', 0.06, NULL, 'assumption', 'ECB deposit facility 2.50% less 10% savings tax = 2.25%; global equity in euro terms', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.en.html', '2026-10-31', 'Andorra has no stock market, so the base case is a global index in euros, kept within 4 points of the after-tax euro safe rate of about 2.25%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AD', 1, 'equity_return_high', 0.08, NULL, 'assumption', 'Global equity long-run record in euro terms', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.en.html', '2026-10-31', 'High case near long-run global equity returns in euros.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AD', 1, 'equity_return_low', 0.03, NULL, 'assumption', 'No local stock exchange; global equity in euro terms; ECB deposit rate 2.50%', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.en.html', '2026-10-31', 'Low case for a global index fund in euros if world shares are weak; Andorra has no stock market.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AD', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published 1-year term deposit rates for Andorran banks were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AD', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published 3-month term deposit rates for Andorran banks were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AD', 1, 'fixed_income_return_base', 0.02, NULL, 'assumption', 'ECB deposit facility 2.50% less 10% savings tax = 2.25%', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.en.html', '2026-10-31', 'Base case: euro term deposits a little below the ECB rate, after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AD', 1, 'fixed_income_return_high', 0.028, NULL, 'assumption', 'ECB main refinancing rate 2.65%; euro government bonds', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.en.html', '2026-10-31', 'High case: longer euro government bonds held to maturity after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AD', 1, 'fixed_income_return_low', 0.01, NULL, 'assumption', 'ECB deposit facility 2.50%; Andorran bank deposit rates not published', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.en.html', '2026-10-31', 'Low case: bank deposits paying well below the ECB rate, after 10% tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AD', 1, 'goal_inflation_education', 0.035, NULL, 'assumption', 'IMF WEO Andorra CPI; 2.5% planning inflation', 'https://www.imf.org/external/datamapper/PCPIPCH@WEO/AND', '2026-10-31', 'No Andorran education price index could be read, so we plan with the 2.5% projection plus one point for fees.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AD', 1, 'goal_inflation_health', 0.035, NULL, 'assumption', 'IMF WEO Andorra CPI; 2.5% planning inflation', 'https://www.imf.org/external/datamapper/PCPIPCH@WEO/AND', '2026-10-31', 'No Andorran medical price index could be read, so we plan with the 2.5% projection plus one point for medical costs.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AD', 1, 'gold_return_base', 0.045, NULL, 'assumption', 'ECB euro reference rate USD 1.1172 per EUR (30 Oct 2026)', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/euro_reference_exchange_rates/html/eurofxref-graph-usd.en.html', '2026-10-31', 'Long-run dollar gold trend of about 4-5% with no expected euro trend against the dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AD', 1, 'gold_return_high', 0.08, NULL, 'assumption', 'ECB euro reference rate USD 1.1172 per EUR (30 Oct 2026)', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/euro_reference_exchange_rates/html/eurofxref-graph-usd.en.html', '2026-10-31', 'High case with strong dollar gold and a weaker euro.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AD', 1, 'gold_return_low', 0.01, NULL, 'assumption', 'ECB euro reference rate USD 1.1172 per EUR (30 Oct 2026)', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/euro_reference_exchange_rates/html/eurofxref-graph-usd.en.html', '2026-10-31', 'Low case: weak dollar gold and a stronger euro.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AD', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No statutory end-of-service gratuity for private employees was found in Andorra; severance applies only to dismissal.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AD', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical out-of-pocket cost of a major hospital stay was found; CASS reimburses most of hospital costs.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AD', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private (complementary) health insurance premiums by age band were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AD', 1, 'inflation_cpi', 0.024, NULL, 'sourced', 'IMF World Economic Outlook (DataMapper), Andorra inflation, average consumer prices', 'https://www.imf.org/external/datamapper/PCPIPCH@WEO/AND', '2025-12-31', '2025 average 2.4% (end-2025 2.7%); the IMF projects 4.0% for 2026. Secondary source because the Andorra statistics portal (estadistica.ad) is a script-only map application that could not be read; the World Bank has no CPI series for Andorra. Checked against the IMF DataMapper API (PCPIPCH, AND).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AD', 1, 'inflation_projection', 0.025, NULL, 'assumption', 'ECB 2% euro area target; IMF WEO Andorra CPI 2.4% (2025), 4.0% (2026 proj.), 2.0% from 2029', 'https://www.imf.org/external/datamapper/PCPIPCH@WEO/AND', '2026-10-31', 'Andorra uses the euro, so the ECB 2% target anchors inflation, but Andorran prices have run above the euro area, so 2.5% is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AD', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published term life premium rates by age were found for Andorra.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AD', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No industry-wide life claim settlement ratio was found from the AFA.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AD', 1, 'life_expectancy', 84.19, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=AD', '2024-12-31', 'Men 82.3, women 86.2. 2024 figure, the latest World Bank value (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AD', 1, 'life_table_remaining', NULL, NULL, 'missing', '', '', '2026-10-31', 'populationpyramid.net (UN WPP) has no Andorra page and the Andorra statistics portal could not be read; no life table at ages 60-80 was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AD', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'The eligibility age and means test of the solidarity pension for the elderly could not be read (BOPA decree page did not render).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AD', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'Andorra has a means-tested solidarity pension for the elderly (Decree of 7-10-2020) and a non-contributory old-age pension law of 1988, but the amount could not be read on the Government or BOPA pages.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AD', 1, 'oop_health_share', 0.1115, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=AD', '2023-12-31', '2023 figure, the latest World Bank value (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AD', 1, 'policy_rate', 0.025, NULL, 'sourced', 'European Central Bank, key ECB interest rates (deposit facility)', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.en.html', '2026-09-16', 'Andorra uses the euro under a monetary agreement with the EU and has no own policy rate; ECB deposit facility 2.50%, main refinancing 2.65% from 16 September 2026 (raised from 2.25% on 17 June 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AD', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":65,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'CASS (Caixa Andorrana de Seguretat Social), retirement pension', 'https://www.cass.ad/prestacio-economica-jubilacio', '2026-10-31', 'Compulsory points-based CASS pension from 65 (early from 61), at least 180 months of contributions; 5-15 years gives a lump-sum capital updated by CPI. No automatic yearly indexation of pensions was stated, so it is treated as not inflation-linked.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AD', 1, 'retirement_accumulation_return_base', 0.04, NULL, 'assumption', 'ECB deposit facility 2.50%; global equity base 6% in euros', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.en.html', '2026-10-31', 'Base case: about half global equity at 6% and half euro fixed income at about 2.5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AD', 1, 'retirement_accumulation_return_high', 0.055, NULL, 'assumption', 'Global equity high case 8% in euros', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.en.html', '2026-10-31', 'High case for a growth-leaning balanced mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AD', 1, 'retirement_accumulation_return_low', 0.025, NULL, 'assumption', 'ECB deposit facility 2.50%; global equity in euros', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.en.html', '2026-10-31', 'Low case for a balanced mix if shares lag.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AD', 1, 'retirement_age_default', 65, NULL, 'sourced', 'CASS (Caixa Andorrana de Seguretat Social), retirement pension', 'https://www.cass.ad/prestacio-economica-jubilacio', '2026-10-31', 'Ordinary retirement age 65 for men and women; early retirement from 61 with more than 480 months of contributions (7% reduction per year early); 180 months minimum.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AD', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'The retirement age for Andorran public servants under the civil service law could not be confirmed; they draw the CASS pension from 65.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AD', 1, 'retirement_return_base', 0.02, NULL, 'assumption', 'ECB deposit facility 2.50% less 10% savings tax = 2.25%', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.en.html', '2026-10-31', 'Base case kept below the after-tax euro safe rate because Andorran 1-year deposit rates are not published.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AD', 1, 'retirement_return_high', 0.028, NULL, 'assumption', 'ECB main refinancing 2.65%; euro government bonds', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.en.html', '2026-10-31', 'High case: a ladder of euro government bonds after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AD', 1, 'retirement_return_low', 0.01, NULL, 'assumption', 'ECB deposit facility 2.50%; Andorran deposit rates not published', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.en.html', '2026-10-31', 'Low case: bank deposits after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AD', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate or retail savings bond for individuals was found in Andorra.', 0);
