INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AD', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":4.34}]}', 'sourced', 'World Bank WDI SP.POP.DPND.OL', 'https://data.worldbank.org/indicator/SP.POP.DPND.OL?locations=AD', '2025-12-31', '100 / old-age dependency ratio of 23.1 (2025). UN WPP projections for 2040 and 2065 could not be read for Andorra.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AD', 1, 'tax_bank_interest', 0.1, NULL, 'sourced', 'Wikipedia, Taxation in Andorra (personal income tax on savings income)', 'https://en.wikipedia.org/wiki/Taxation_in_Andorra', '2026-10-31', 'The first EUR 3,000 of savings/investment income a year is exempt and the rest is taxed at 10%; secondary source because the Government tax pages could not be read.', 0);
