INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('AE', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"AE","iso3":"ARE","nameEn":"United Arab Emirates","nameNative":"الإمارات العربية المتحدة","region":"middle_east_north_africa","languages":["ar","en","ml","ps","fa"],"currency":{"code":"AED","symbol":"د.إ","decimals":2,"compact":"intl","usdRate":{"value":3.6725,"status":"sourced","sourceName":"World Bank WDI, official exchange rate (PA.NUS.FCRF), United Arab Emirates","sourceUrl":"https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=AE","asOf":"2025-12-31","note":"The dirham is pegged at 3.6725 per US dollar."}},"instruments":{"savings_account":{"available":true,"localName":"حساب توفير","localNameEn":"Savings account"},"fdr_3m":{"available":true,"localName":"وديعة لأجل (3 أشهر)","localNameEn":"Fixed deposit (3 months)"},"fdr_1y":{"available":true,"localName":"وديعة لأجل (سنة)","localNameEn":"Fixed deposit (1 year)"},"dps":{"available":true,"localName":"حساب ادخار شهري","localNameEn":"Monthly savings plan","note":"Some banks offer monthly instalment savings accounts; no standard product."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate or retail savings bond for individuals was confirmed."},"tbill_91d":{"available":false,"localName":null,"localNameEn":"Monetary bills (M-Bills)","note":"Issued by the Central Bank of the UAE to banks, not sold directly to individuals."},"tbond_5y":{"available":true,"localName":"سندات الخزينة الاتحادية","localNameEn":"Federal treasury bonds and sukuk (T-Bonds, T-Sukuk)","note":"Dirham bonds auctioned by the Ministry of Finance through primary dealer banks since 2022; retail access is through banks."},"tbond_10y":{"available":true,"localName":"سندات الخزينة الاتحادية (10 سنوات)","localNameEn":"Federal treasury bonds (10 years)","note":"Longer dirham maturities are auctioned in smaller amounts (availability not confirmed for every year); retail access is through banks."},"equity_fund":{"available":true,"localName":"صناديق الاستثمار","localNameEn":"Investment funds","note":"Funds are regulated by the Securities and Commodities Authority."},"gold":{"available":true,"localName":"الذهب","localNameEn":"Gold","note":"Gold bars, coins and jewellery are widely sold."}},"institutions":{"centralBank":{"name":"Central Bank of the UAE (CBUAE)","url":"https://www.centralbank.ae/"},"insuranceRegulator":{"name":"Central Bank of the UAE, insurance supervision","url":"https://www.centralbank.ae/"},"insuranceComplaints":{"name":"Sanadak, UAE financial ombudsman for banking and insurance","url":"https://www.sanadak.gov.ae/"},"pensionScheme":{"name":"General Pension and Social Security Authority (GPSSA), for UAE and GCC nationals","url":"https://gpssa.gov.ae/","note":"Abu Dhabi nationals are covered by the Abu Dhabi Pension Fund; expatriates receive an end-of-service gratuity instead."},"oldAgeAllowance":{"name":"Social welfare programmes, Ministry of Community Empowerment (means-tested, UAE nationals)","url":"https://u.ae/en/information-and-services/social-affairs/social-welfare/social-welfare-programmes"},"publicHealthCover":{"name":"Mandatory health insurance by emirate; Thiqa and Enaya for nationals","url":"https://u.ae/en/information-and-services/health-and-fitness/Healthcare-access-and-insurance/getting-a-health-insurance"},"depositInsurance":null,"statistics":{"name":"Federal Competitiveness and Statistics Centre (FCSC)","url":"https://fcsc.gov.ae/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AE', 1, 'bank_deposit_avg_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Central Bank of the UAE publishes average deposit rates in its statistical bulletin, but its site refused requests; the World Bank has no recent deposit rate for the UAE.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AE', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap or published typical credit card rate could be read from the Central Bank of the UAE.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AE', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No explicit deposit insurance scheme or cover amount was confirmed for UAE banks; the Central Bank of the UAE site refused requests.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AE', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No industry-wide rate for monthly recurring savings plans was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AE', 1, 'equity_return_base', 0.075, NULL, 'assumption', 'ADX General index record (Trading Economics); EIBOR 4.34% and untaxed interest', 'https://tradingeconomics.com/united-arab-emirates/stock-market', '2026-10-31', 'Base case: about 3.5 points over the untaxed 3-month EIBOR of about 4.3%, within the 4-point cap; the ADX roughly doubled since 2016 with dividends of about 4%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AE', 1, 'equity_return_high', 0.11, NULL, 'assumption', 'ADX General index record (Trading Economics)', 'https://tradingeconomics.com/united-arab-emirates/stock-market', '2026-10-31', 'High case: price growth like 2016-2026 plus dividends.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AE', 1, 'equity_return_low', 0.04, NULL, 'assumption', 'ADX General index 9,466 on 30 October 2026, down 6% in a year and 12% below its February 2026 peak (Trading Economics)', 'https://tradingeconomics.com/united-arab-emirates/stock-market', '2026-10-31', 'Low case: equities earn about the deposit rate, as in the past year''s decline.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AE', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published industry-wide 1-year fixed deposit rate could be read from the Central Bank of the UAE.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AE', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published industry-wide 3-month fixed deposit rate could be read; for reference, 3-month EIBOR was 4.34% on 30 October 2026 (Trading Economics).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AE', 1, 'fixed_income_return_base', 0.035, NULL, 'assumption', 'Base rate 3.9%; 3-month EIBOR 4.34% (October 2026); no income tax (PwC)', 'https://tradingeconomics.com/united-arab-emirates/interbank-rate', '2026-10-31', 'Base case: fixed deposits a little below interbank rates over a full rate cycle, untaxed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AE', 1, 'fixed_income_return_high', 0.045, NULL, 'assumption', '3-month EIBOR 4.34% (October 2026)', 'https://tradingeconomics.com/united-arab-emirates/interbank-rate', '2026-10-31', 'High case: rates stay near today''s level and savers use longer fixed deposits or government sukuk.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AE', 1, 'fixed_income_return_low', 0.025, NULL, 'assumption', 'Central Bank of the UAE base rate 3.9% (October 2026); no income tax (PwC)', 'https://tradingeconomics.com/united-arab-emirates/interest-rate', '2026-10-31', 'Low case: US and UAE rates fall back and savings balances earn less than fixed deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AE', 1, 'goal_inflation_education', 0.035, NULL, 'assumption', 'FCSC education CPI index 104.5 (June 2026, Trading Economics); inflation assumption 2%', 'https://tradingeconomics.com/united-arab-emirates/inflation-cpi', '2026-10-31', 'Private school fees, regulated by emirate authorities, rise in yearly steps above general inflation, so education goals use 3.5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AE', 1, 'goal_inflation_health', 0.04, NULL, 'assumption', 'FCSC health CPI index 103.4 (June 2026, Trading Economics); inflation assumption 2%', 'https://tradingeconomics.com/united-arab-emirates/inflation-cpi', '2026-10-31', 'The health CPI has risen slowly, but private medical costs and insurance premiums have grown faster than general prices, so health goals are planned 2 points above the general assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AE', 1, 'gold_return_base', 0.04, NULL, 'assumption', 'Dirham pegged at 3.6725 per US dollar; long-run dollar gold trend about 4%', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=AE', '2026-10-31', 'Base case: the long-run dollar gold trend, since the peg means no currency effect.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AE', 1, 'gold_return_high', 0.08, NULL, 'assumption', 'Dirham pegged at 3.6725 per US dollar; dollar gold history', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=AE', '2026-10-31', 'High case: a strong decade for dollar gold.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AE', 1, 'gold_return_low', 0, NULL, 'assumption', 'Dirham pegged at 3.6725 per US dollar', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=AE', '2026-10-31', 'Low case: flat dollar gold; the peg adds no currency gain.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AE', 1, 'gratuity_rule', NULL, '{"daysPerYear":21,"daysPerYearAfter":30,"afterYears":5,"daysPerMonth":30}', 'sourced', 'UAE Government portal, End of service benefits for workers in the private sector (updated 15 October 2026)', 'https://u.ae/en/information-and-services/jobs/Sector-of-employment/employment-in-the-private-sector/end-of-service-benefits-for-employees-in-the-private-sector', '2026-10-15', 'Workers with at least one year of continuous service get 21 days of last basic wage per year for the first 5 years and 30 days per year after, capped at 2 years'' wage (applies to non-national private-sector workers; nationals are in the GPSSA pension). The page gives no daily-wage divisor; 30 days a month is used as the planning convention and is not confirmed. Employers may opt into an approved savings scheme instead.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AE', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a major private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AE', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'The federal basic health plan for private-sector and domestic workers costs AED 320 a year for ages 1 to 64 (u.ae, updated 8 September 2026), but its annual cover limit and premiums for wider plans by age were not published, so a per-AED-100,000 table could not be built.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AE', 1, 'inflation_cpi', 0.0204, NULL, 'sourced', 'Federal Competitiveness and Statistics Centre (FCSC) CPI, December 2025, via Trading Economics', 'https://tradingeconomics.com/united-arab-emirates/inflation-cpi', '2025-12-31', '2.04% year on year in December 2025 (1.61% in November), the latest headline rate shown; secondary source because the FCSC site refused requests. World Bank 2025 average 1.25%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AE', 1, 'inflation_projection', 0.02, NULL, 'assumption', 'Dirham pegged to the US dollar; FCSC CPI 2.0% (December 2025); World Bank CPI 1.25% (2025)', 'https://tradingeconomics.com/united-arab-emirates/inflation-cpi', '2026-10-31', 'With the dirham pegged to the dollar, inflation tracks the US 2% target and averaged about 2% over 2021 to 2025, so 2% is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AE', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life is sold, but no published premium rates per AED 1,000 by age were found from the regulator or another public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AE', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No industry-wide life claim settlement ratio could be read from the Central Bank of the UAE, the insurance supervisor.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AE', 1, 'life_expectancy', 83.069, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN), United Arab Emirates', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=AE', '2024-12-31', '83.1 years in 2024 (men 82.2, women 84.3); the resident population is mostly working-age migrants.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AE', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":25.2,"men":24.5,"women":25.8},{"age":65,"total":20.5,"men":20,"women":21.1},{"age":70,"total":16.2,"men":15.6,"women":16.7},{"age":80,"total":8.5,"men":8,"women":9}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/united-arab-emirates/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026; the 65 total is published there, the other totals are the mean of men and women.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AE', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'Social welfare for nationals is means-tested by family situation and income; no separate age-based eligibility rule for older people was found on the government portal.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AE', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'Federal and emirate social welfare programmes give means-tested support to low-income UAE nationals (Ministry of Community Empowerment), but no age-based monthly amount for older people is published on the government portal (updated 8 July 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AE', 1, 'oop_health_share', 0.0967, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), United Arab Emirates', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=AE', '2023-12-31', '9.7% in 2023 (WHO Global Health Expenditure Database via the World Bank); older than 2025, the latest available.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AE', 1, 'policy_rate', 0.039, NULL, 'sourced', 'Central Bank of the UAE base rate (overnight deposit facility), decision of 28 October 2026, via Trading Economics', 'https://tradingeconomics.com/united-arab-emirates/interest-rate', '2026-10-28', 'Held at 3.90% on 28 October 2026 after a 25 basis point rise in September 2026, following the US Federal Reserve. Secondary source because the central bank site refused requests.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AE', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":18,"entryAgeMax":60,"pensionFromAge":60,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":true}', 'sourced', 'UAE Government portal, Pensions and social security for UAE citizens (updated 14 October 2026)', 'https://u.ae/en/information-and-services/jobs/Sector-of-employment/working-in-uae-government-sector/pensions-and-social-security-for-uae-citizens', '2026-10-14', 'GPSSA covers UAE and GCC nationals only (Abu Dhabi nationals: Abu Dhabi Pension Fund); expatriates get an end-of-service gratuity instead. Registration at 18 to 60; pension at 60 with 15 years for those registered before 31 October 2023 (Federal Law 7 of 1999), or from 55 with 30 years for first-time workers since then (Decree-Law 57 of 2023); contributions 26% (employee 11%, employer 15%). The page mentions no automatic indexation, so inflationLinked is set false (not confirmed); pensions are untaxed because there is no personal income tax (PwC Worldwide Tax Summaries).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AE', 1, 'retirement_accumulation_return_base', 0.055, NULL, 'assumption', 'Fixed income base 3.5%; equity base 7.5%; gold base 4%', 'https://tradingeconomics.com/united-arab-emirates/stock-market', '2026-10-31', 'Base case: a balanced mix of deposits, UAE or global equities and gold.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AE', 1, 'retirement_accumulation_return_high', 0.075, NULL, 'assumption', 'Equity high 11%; gold high 8%', 'https://tradingeconomics.com/united-arab-emirates/stock-market', '2026-10-31', 'High case: a growth-leaning mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AE', 1, 'retirement_accumulation_return_low', 0.035, NULL, 'assumption', 'Fixed income low 2.5%; equity low 4%', 'https://tradingeconomics.com/united-arab-emirates/stock-market', '2026-10-31', 'Low case: a balanced mix earning about the deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AE', 1, 'retirement_age_default', 60, NULL, 'sourced', 'UAE Government portal, Pensions and social security for UAE citizens (updated 14 October 2026)', 'https://u.ae/en/information-and-services/jobs/Sector-of-employment/working-in-uae-government-sector/pensions-and-social-security-for-uae-citizens', '2026-10-14', 'Applies to UAE and GCC nationals only: 60 with 15 years of insured service for those registered before 31 October 2023 (most people born after 1975); first-time workers since then may retire from 55 with at least 30 years. Expatriates have no public pension and receive an end-of-service gratuity instead.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AE', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'The mandatory retirement age for federal government employees under the federal human resources law could not be read; the GPSSA pension rules above apply to nationals in both sectors.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AE', 1, 'retirement_return_base', 0.035, NULL, 'assumption', '3-month EIBOR 4.34%; no income tax (PwC)', 'https://tradingeconomics.com/united-arab-emirates/interbank-rate', '2026-10-31', 'Base case: fixed deposits below today''s interbank rate, untaxed, so not above the after-tax safe rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AE', 1, 'retirement_return_high', 0.045, NULL, 'assumption', '3-month EIBOR 4.34% (October 2026)', 'https://tradingeconomics.com/united-arab-emirates/interbank-rate', '2026-10-31', 'High case: rates stay near today''s level.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AE', 1, 'retirement_return_low', 0.025, NULL, 'assumption', 'Base rate 3.9% (October 2026); no income tax (PwC)', 'https://tradingeconomics.com/united-arab-emirates/interest-rate', '2026-10-31', 'Low case: rates fall back over retirement.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AE', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate sold to individuals was confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AE', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No industry-wide savings account rate could be read; the Central Bank of the UAE site refused requests and web search was unavailable.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AE', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":45.9},{"year":2040,"value":29.4},{"year":2065,"value":14.7}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/united-arab-emirates/2065/', '2025-12-31', '100 / old-age dependency ratio: 2.18 (2025, World Bank), about 3.4 (2040, from 2.7% aged 65+ and 17.9% under 15 on populationpyramid.net/united-arab-emirates/2040/) and 6.8 (2065). Migrant workers keep the ratio high.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AE', 1, 'tax_bank_interest', 0, NULL, 'sourced', 'PwC Worldwide Tax Summaries, United Arab Emirates, taxes on personal income (last reviewed 9 September 2026)', 'https://taxsummaries.pwc.com/united-arab-emirates/individual/taxes-on-personal-income', '2026-09-09', 'There is no personal income tax in the UAE, so interest earned by individuals is untaxed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AE', 1, 'tax_sanchayapatra_profit', 0, NULL, 'sourced', 'PwC Worldwide Tax Summaries, United Arab Emirates, taxes on personal income (last reviewed 9 September 2026)', 'https://taxsummaries.pwc.com/united-arab-emirates/individual/taxes-on-personal-income', '2026-09-09', 'No personal income tax, so returns on any government security held by an individual are untaxed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AE', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Central Bank of the UAE issues monetary bills to banks, but no current 3-month yield could be read; its site refused requests.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AE', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No current 10-year dirham government bond yield could be read from an official or secondary source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AE', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Ministry of Finance auctions dirham treasury bonds and sukuk through primary dealer banks, but no current 5-year yield could be read.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('AF', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"AF","iso3":"AFG","nameEn":"Afghanistan","nameNative":"افغانستان","region":"south_asia","languages":["fa","ps","uz","tk"],"currency":{"code":"AFN","symbol":"؋","decimals":2,"compact":"intl","usdRate":{"value":65.01,"status":"sourced","sourceName":"Da Afghanistan Bank (transfer buy/sell mid rate)","sourceUrl":"https://www.dab.gov.af/exchange-rates","asOf":"2026-10-31","note":"Transfer buy 64.96, sell 65.06 AFN per USD."}},"instruments":{"savings_account":{"available":true,"localName":"حساب پس‌انداز","localNameEn":"Savings account","note":"Interest-free; banks follow Islamic banking rules and publish no profit rates.","sourceUrl":"https://afintl.com/en/202412295022"},"fdr_3m":{"available":false,"localName":null,"note":"Interest-bearing term deposits ended with the interest ban.","sourceUrl":"https://afintl.com/en/202412295022"},"fdr_1y":{"available":false,"localName":null,"note":"Interest-bearing term deposits ended with the interest ban.","sourceUrl":"https://afintl.com/en/202412295022"},"dps":{"available":false,"localName":null,"note":"No recurring deposit schemes with a stated return."},"sanchayapatra_5y":{"available":false,"localName":null,"note":"No government savings certificate for individuals."},"tbill_91d":{"available":false,"localName":null,"note":"No treasury bills; DAB capital notes were for banks only and are no longer auctioned."},"tbond_5y":{"available":false,"localName":null,"note":"No government bonds."},"tbond_10y":{"available":false,"localName":null,"note":"No government bonds."},"equity_fund":{"available":false,"localName":null,"note":"No stock exchange or retail mutual funds."},"gold":{"available":true,"localName":"طلا","localNameEn":"Gold","note":"Physical gold is widely bought and held."}},"institutions":{"centralBank":{"name":"Da Afghanistan Bank","url":"https://www.dab.gov.af/"},"insuranceRegulator":{"name":"General Directorate of Takaful and Insurance, Ministry of Finance","url":"https://mof.gov.af/en/node/2390"},"insuranceComplaints":null,"pensionScheme":null,"oldAgeAllowance":null,"publicHealthCover":{"name":"Ministry of Public Health (free care at public hospitals)","url":"https://moph.gov.af/en","note":"Public hospitals report free surgery; no national health insurance."},"depositInsurance":{"name":"Afghanistan Deposits Protection Fund (Da Afghanistan Bank)","url":"https://www.dab.gov.af/","note":"The fund''s own page blocks automated access; linked through the central bank."},"statistics":{"name":"National Statistics and Information Authority","url":"https://nsia.gov.af/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AF', 1, 'bank_deposit_avg_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Da Afghanistan Bank ended interest-based banking (all bank business is conducted without interest under Hanafi jurisprudence); no published deposit or profit rates found. World Bank FR.INR.DPST has no value for Afghanistan.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AF', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No credit card interest cap or typical rate found; interest-based lending is banned.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AF', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Afghanistan Deposits Protection Fund (a DAB department) exists, but no per-depositor cover amount could be found; DAB pages returned 403.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AF', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Da Afghanistan Bank ended interest-based banking (all bank business is conducted without interest under Hanafi jurisprudence); no published deposit or profit rates found. Searched DAB, bank sites, news.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AF', 1, 'equity_return_base', 0.04, NULL, 'assumption', 'Global equity index in afghani terms (no local stock market)', 'https://www.dab.gov.af/exchange-rates', '2026-10-31', 'With no safe local interest rate (0%), the base is capped at 4 points above it; hard access to global funds and afghani swings justify a low figure.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AF', 1, 'equity_return_high', 0.08, NULL, 'assumption', 'Global equity index in afghani terms (no local stock market)', 'https://www.dab.gov.af/exchange-rates', '2026-10-31', 'Roughly the long-run nominal dollar return of global equities with a stable afghani.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AF', 1, 'equity_return_low', 0, NULL, 'assumption', 'Global equity index in afghani terms (no local stock market)', 'https://www.dab.gov.af/exchange-rates', '2026-10-31', 'Afghanistan has no stock exchange or retail funds, so equity means a global index held in afghani terms, which can lose value when the afghani strengthens (it rose from about 89 to 65 per dollar since 2022).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AF', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Da Afghanistan Bank ended interest-based banking (all bank business is conducted without interest under Hanafi jurisprudence); no published deposit or profit rates found. Searched DAB, bank sites, news.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AF', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Da Afghanistan Bank ended interest-based banking (all bank business is conducted without interest under Hanafi jurisprudence); no published deposit or profit rates found. Searched DAB, bank sites, news.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AF', 1, 'fixed_income_return_base', 0, NULL, 'assumption', 'Interest ban on bank deposits', 'https://afintl.com/en/202412295022', '2026-10-31', 'No interest-bearing deposits or government securities exist for individuals; we assume cash-like safe savings earn 0%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AF', 1, 'fixed_income_return_high', 0.02, NULL, 'assumption', 'Interest ban on bank deposits', 'https://afintl.com/en/202412295022', '2026-10-31', 'Allows for modest profit shares on Islamic investment deposits if banks begin publishing them.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AF', 1, 'fixed_income_return_low', 0, NULL, 'assumption', 'Interest ban on bank deposits', 'https://afintl.com/en/202412295022', '2026-10-31', 'Banks pay no interest and no government securities are sold, so safe money earns nothing.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AF', 1, 'goal_inflation_education', 0.07, NULL, 'assumption', 'NSIA CPI via Trading Economics', 'https://tradingeconomics.com/afghanistan/inflation-cpi', '2026-10-31', 'No education CPI series found; we use the 5% inflation assumption plus 2 points for private schooling costs.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AF', 1, 'goal_inflation_health', 0.07, NULL, 'assumption', 'NSIA CPI via Trading Economics', 'https://tradingeconomics.com/afghanistan/inflation-cpi', '2026-10-31', 'No medical CPI series found; we use the 5% inflation assumption plus 2 points for import-dependent medical costs.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AF', 1, 'gold_return_base', 0.05, NULL, 'assumption', 'Da Afghanistan Bank exchange rates; dollar gold trend', 'https://www.dab.gov.af/exchange-rates', '2026-10-31', 'Dollar gold trend of about 4-5% a year with little expected afghani depreciation, roughly matching the 5% inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AF', 1, 'gold_return_high', 0.1, NULL, 'assumption', 'Da Afghanistan Bank exchange rates; dollar gold trend', 'https://www.dab.gov.af/exchange-rates', '2026-10-31', 'Dollar gold strength plus renewed afghani depreciation (it averaged about 5% a year in 2010-2020).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AF', 1, 'gold_return_low', 0, NULL, 'assumption', 'Da Afghanistan Bank exchange rates; dollar gold trend', 'https://www.dab.gov.af/exchange-rates', '2026-10-31', 'A strengthening afghani can offset dollar gold gains for years, as in 2022-2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AF', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No days-per-year gratuity found. Private employers reportedly pay 10 months of last monthly earnings as a lump sum when a worker retires at 65 (US SSA, May 2024; page could not be re-read), which does not fit the per-year shape.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AF', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No typical private hospital stay cost published; one news anecdote cites AFN 150,000 for a lung surgery at a Kabul private hospital (8am.media), too thin to use.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AF', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No retail private health insurance market with published premiums found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AF', 1, 'inflation_cpi', 0.078, NULL, 'sourced', 'Trading Economics (NSIA CPI)', 'https://tradingeconomics.com/afghanistan/inflation-cpi', '2026-08-31', 'August 2026 year on year; secondary source because the NSIA site could not be reached. CPI was -6.6% in 2024 (World Bank).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AF', 1, 'inflation_projection', 0.05, NULL, 'assumption', 'NSIA CPI via Trading Economics; World Bank FP.CPI.TOTL.ZG', 'https://tradingeconomics.com/afghanistan/inflation-cpi', '2026-10-31', 'Da Afghanistan Bank publishes no inflation target and CPI swung from -6.6% (2024) to 7.8% (Aug 2026), so we plan with a rounded 5% long-run rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AF', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No retail term life premium quotes found; life cover is offered only in rare special cases. Not marked absent because no official source confirming the absence was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AF', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No industry claim settlement ratio published by the General Directorate of Takaful and Insurance (Ministry of Finance); life insurance is barely sold.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AF', 1, 'life_expectancy', 66.289, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=AF', '2024-12-31', 'Men 64.7, women 67.8 (World Bank 2024; older than 2025, latest available).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AF', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":16.8,"men":15.9,"women":17.6},{"age":65,"total":13.4,"men":12.6,"women":14},{"age":70,"total":10.4,"men":9.8,"women":10.8},{"age":80,"total":5.7,"men":5.4,"women":5.9}]}', 'sourced', 'georank.org (UN World Population Prospects)', 'https://georank.org/life-expectancy/afghanistan', '2026-07-08', 'Remaining years = expected age at death by current age minus that age; explainer only.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AF', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension found (the US SSA May 2024 update that reportedly says so could not be read), so no eligibility rules.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AF', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension found. The researcher cited a US SSA International Update (May 2024) saying none exists, but the page returns 403 and could not be read, so absence is not confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AF', 1, 'oop_health_share', 0.771, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=AF', '2023-12-31', 'Latest World Bank value is for 2023 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AF', 1, 'policy_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Da Afghanistan Bank sets no policy rate: interest-based instruments (including capital-note auctions) ended with the move to interest-free banking. Searched DAB site, news, Central Banking.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AF', 1, 'public_pension_scheme', NULL, NULL, 'missing', '', '', '2026-10-31', 'The public-sector pension scheme (8% employee, 8% state, age 65) was reportedly suspended in 2021 and closed to new members in 2024, with payments to existing retirees resumed in 2025 (news reports, not re-verified); private workers have never had a public pension. Not marked absent because no official source was read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AF', 1, 'retirement_accumulation_return_base', 0.03, NULL, 'assumption', 'Mix of cash, gold and global equity (assumption)', 'https://www.dab.gov.af/exchange-rates', '2026-10-31', 'Balanced mix of 0% cash, 5% gold and 4% global equity in afghani terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AF', 1, 'retirement_accumulation_return_high', 0.07, NULL, 'assumption', 'Mix of cash, gold and global equity (assumption)', 'https://www.dab.gov.af/exchange-rates', '2026-10-31', 'Gold and global equity high cases with a stable afghani.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AF', 1, 'retirement_accumulation_return_low', 0, NULL, 'assumption', 'Mix of cash, gold and global equity (assumption)', 'https://www.dab.gov.af/exchange-rates', '2026-10-31', 'A cash-heavy mix earns nothing in a weak case.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AF', 1, 'retirement_age_default', 65, NULL, 'sourced', 'Pajhwok (Labour Law, Article 138)', 'https://pajhwok.com/?p=411494', '2021-07-29', 'Labour Law Article 138: mandatory retirement age 65 for employees; private workers get a lump sum rather than a pension. Source article is from 2021 (older than 2025); no later change found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AF', 1, 'retirement_age_government', 65, NULL, 'sourced', 'Pajhwok (Labour Law, Article 138; civil service commission)', 'https://pajhwok.com/?p=411494', '2021-07-29', 'Civil servants retire at 65 (Labour Law Article 138, upheld by the civil service commission). Source article is from 2021 (older than 2025); a later decree reportedly extended service by two years in some institutions.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AF', 1, 'retirement_return_base', 0, NULL, 'assumption', 'Interest ban on bank deposits', 'https://afintl.com/en/202412295022', '2026-10-31', 'Kept at the after-tax safe rate, which is 0% because banks pay no interest and no government securities are sold.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AF', 1, 'retirement_return_high', 0.02, NULL, 'assumption', 'Interest ban on bank deposits', 'https://afintl.com/en/202412295022', '2026-10-31', 'Allows for a small gold share or Islamic deposit profit.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AF', 1, 'retirement_return_low', 0, NULL, 'assumption', 'Interest ban on bank deposits', 'https://afintl.com/en/202412295022', '2026-10-31', 'Safe money earns nothing without interest-bearing deposits or bills.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AF', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate or retail savings bond is sold to individuals in Afghanistan.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AF', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Da Afghanistan Bank ended interest-based banking (all bank business is conducted without interest under Hanafi jurisprudence); no published deposit or profit rates found. Searched DAB, bank sites, news.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AF', 1, 'support_ratio', NULL, '{"points":[{"year":2026,"value":22.7},{"year":2040,"value":18.9},{"year":2065,"value":10.1}]}', 'sourced', 'PopulationPyramid.net (UN WPP 2024, medium variant)', 'https://www.populationpyramid.net/afghanistan/2040/', '2026-10-31', '100 / old-age dependency ratio shown on PopulationPyramid.net (UN WPP 2024): 4.4 in 2026, 5.3 in 2040 (this page), 9.9 in 2065.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AF', 1, 'tax_bank_interest', 0.2, NULL, 'sourced', 'Income Tax Law 2009, Article 46 (ARD unofficial translation)', 'https://www.acbar.org/upload/1493209950200.pdf', '2009-03-18', 'Article 46(1)(2): legal persons withhold 20% from interest. Law text dated 2009 (older than 2025); no later change to the rate found. In practice banks now pay no interest under the interest ban.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AF', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate exists; the Income Tax Law 2009 excludes interest on State bonds from gross income, but no such bonds are issued.', 0);
