INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AF', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government bonds are issued in Afghanistan.', 0);
