INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('AG', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"AG","iso3":"ATG","nameEn":"Antigua and Barbuda","nameNative":"Antigua and Barbuda","region":"latin_america_caribbean","languages":["en","aig"],"currency":{"code":"XCD","symbol":"$","decimals":2,"compact":"intl","usdRate":{"value":2.7,"status":"sourced","sourceName":"World Bank WDI PA.NUS.FCRF","sourceUrl":"https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=AG","asOf":"2025-12-31","note":"The Eastern Caribbean dollar has been fixed at EC$2.70 per US dollar by the ECCB since 1976."}},"instruments":{"savings_account":{"available":true,"localName":"Savings account","sourceUrl":"https://www.eccb-centralbank.org/statistics-category/mfs-interest-rates/interest-rates-and-weighted-averages-rates-on-deposits-and-loans/q"},"fdr_3m":{"available":true,"localName":"Fixed deposit","localNameEn":"3-month fixed (time) deposit","sourceUrl":"https://www.eccb-centralbank.org/statistics-category/mfs-interest-rates/interest-rates-on-deposits-and-loans/m"},"fdr_1y":{"available":true,"localName":"Fixed deposit","localNameEn":"12-month fixed (time) deposit","sourceUrl":"https://www.eccb-centralbank.org/statistics-category/mfs-interest-rates/interest-rates-on-deposits-and-loans/m"},"dps":{"available":false,"localName":null,"note":"No standard monthly recurring deposit product rate published for Antigua and Barbuda."},"sanchayapatra_5y":{"available":false,"localName":null,"note":"No government savings certificate or retail savings bond for individuals found."},"tbill_91d":{"available":true,"localName":"Treasury bill","localNameEn":"Government of Antigua and Barbuda Treasury bill (180 or 365 days)","note":"Sold by auction on the Regional Government Securities Market through licensed intermediaries; recent issues are 180-day and 365-day bills, not 91-day.","sourceUrl":"https://www.eccb-centralbank.org/statistics-category/regional-government-securities-market/weighted-average-interest-rates-on-the-rgsm/m"},"tbond_5y":{"available":false,"localName":null,"note":"No 5-year government bond auctioned on the RGSM in 2025-2026; only 2- and 3-year bonds."},"tbond_10y":{"available":false,"localName":null,"note":"No 10-year government bond auctioned on the RGSM in 2025-2026."},"equity_fund":{"available":false,"localName":null,"note":"No locally registered retail mutual or index fund market found; the regional securities exchange lists only a few thinly traded shares."},"gold":{"available":true,"localName":"Gold","note":"No legal restriction on buying gold; mainly sold as jewellery."}},"institutions":{"centralBank":{"name":"Eastern Caribbean Central Bank (ECCB)","url":"https://www.eccb-centralbank.org/"},"insuranceRegulator":{"name":"Financial Services Regulatory Commission (FSRC)","url":"https://www.fsrc.gov.ag/"},"insuranceComplaints":{"name":"Financial Services Regulatory Commission (FSRC)","url":"https://www.fsrc.gov.ag/","note":"No separate insurance ombudsman found; complaints go to the insurer, then the FSRC."},"pensionScheme":{"name":"Antigua and Barbuda Social Security Board (age benefit)","url":"https://socialsecurity.gov.ag/age-benefits/"},"oldAgeAllowance":null,"publicHealthCover":{"name":"Medical Benefits Scheme","url":"https://www.mbs.gov.ag/v2/","note":"Payroll-funded scheme covering treatment for listed conditions; public hospital care is subsidised."},"depositInsurance":null,"statistics":{"name":"Statistics Division, Ministry of Finance","url":"https://statistics.gov.ag/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AG', 1, 'bank_deposit_avg_rate', 0.0132, NULL, 'sourced', 'Eastern Caribbean Central Bank, interest rates and weighted average rates on deposits and loans (ECCB table, country Antigua and Barbuda)', 'https://www.eccb-centralbank.org/statistics-category/mfs-interest-rates/interest-rates-and-weighted-averages-rates-on-deposits-and-loans/q', '2026-06-30', 'Weighted average rate on all EC-dollar deposits 1.32% in June 2026 (1.17% including foreign-currency deposits).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AG', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap or published typical credit card rate found; ECCB tables give only ''other lending rates'' of 4-24% for Antigua and Barbuda.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AG', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Eastern Caribbean Deposit Insurance Corporation Agreement (signed 2025) is being enacted by ECCU members, but no operating scheme or coverage limit for Antigua and Barbuda could be confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AG', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched ECCB interest rate tables: no monthly recurring deposit product rate is published for Antigua and Barbuda.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AG', 1, 'equity_return_base', 0.065, NULL, 'assumption', 'No liquid local equity index; global equities in EC-dollar terms; 365-day T-bill 4.50% (Sep 2026)', 'https://www.eccb-centralbank.org/statistics-category/regional-government-securities-market/weighted-average-interest-rates-on-the-rgsm/m', '2026-10-31', 'The regional exchange lists only a handful of thinly traded shares, so equity is a global index fund in EC-dollar terms at about 6.5%, within 4 points of the untaxed 4.5% 1-year government bill rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AG', 1, 'equity_return_high', 0.09, NULL, 'assumption', 'Global equities in EC-dollar (US-dollar-pegged) terms', 'https://www.eccb-centralbank.org/statistics-category/regional-government-securities-market/weighted-average-interest-rates-on-the-rgsm/m', '2026-10-31', 'High case if global equities repeat their long-run record of about 9% a year in US dollars.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AG', 1, 'equity_return_low', 0.03, NULL, 'assumption', 'No liquid local equity index; global equities in EC-dollar (US-dollar-pegged) terms', 'https://www.eccb-centralbank.org/statistics-category/regional-government-securities-market/weighted-average-interest-rates-on-the-rgsm/m', '2026-10-31', 'Low case close to the 3-4.5% government bill yields, for a weak decade in global markets.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AG', 1, 'fdr_1y_rate', 0.02, NULL, 'sourced', 'Eastern Caribbean Central Bank, interest rates on deposits and loans (ECCB table, country Antigua and Barbuda)', 'https://www.eccb-centralbank.org/statistics-category/mfs-interest-rates/interest-rates-on-deposits-and-loans/m', '2026-08-31', '12-month EC-dollar time deposits quoted from 0.10% to 2.50% (August 2026); the weighted average on all EC-dollar time deposits was 1.87% (June 2026), so 2.0% is used as typical.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AG', 1, 'fdr_3m_rate', 0.02, NULL, 'sourced', 'Eastern Caribbean Central Bank, interest rates on deposits and loans (ECCB table, country Antigua and Barbuda)', 'https://www.eccb-centralbank.org/statistics-category/mfs-interest-rates/interest-rates-on-deposits-and-loans/m', '2026-08-31', '3-month EC-dollar time deposits quoted at 2.00% (minimum and maximum).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AG', 1, 'fixed_income_return_base', 0.03, NULL, 'assumption', 'ECCB: 12-month deposits up to 2.5%; 180-day T-bills 3.00% and 365-day 4.50% (ECCB table, country Antigua and Barbuda)', 'https://www.eccb-centralbank.org/statistics-category/regional-government-securities-market/weighted-average-interest-rates-on-the-rgsm/m', '2026-10-31', 'Base case mixing 1-year deposits and government bills, untaxed for residents.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AG', 1, 'fixed_income_return_high', 0.045, NULL, 'assumption', 'ECCB RGSM: 365-day T-bill 4.50% (Sep 2026); 2-year bond 4.00%', 'https://www.eccb-centralbank.org/statistics-category/regional-government-securities-market/weighted-average-interest-rates-on-the-rgsm/m', '2026-10-31', 'High case: holding 1-year government bills and short bonds at about 4-4.5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AG', 1, 'fixed_income_return_low', 0.02, NULL, 'assumption', 'ECCB: savings and 3-month deposits about 2.0% (ECCB table, country Antigua and Barbuda)', 'https://www.eccb-centralbank.org/statistics-category/mfs-interest-rates/interest-rates-on-deposits-and-loans/m', '2026-10-31', 'Low case: savings and short deposits at the 2% minimum savings rate; no tax on resident interest.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AG', 1, 'goal_inflation_education', 0.035, NULL, 'assumption', 'ECCB CPI table, Antigua and Barbuda education sub-index (2018 100.0, 2025 114.9)', 'https://www.eccb-centralbank.org/statistics-category/other-real-sector/consumer-price-index-antigua-and-barbuda/m', '2026-10-31', 'The education index averaged about 2% a year over 2018-2025 but jumped 13% in 2025, so we plan with the headline projection plus half a point.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AG', 1, 'goal_inflation_health', 0.04, NULL, 'assumption', 'ECCB CPI table, Antigua and Barbuda health sub-index (2018 100.1, 2025 114.3)', 'https://www.eccb-centralbank.org/statistics-category/other-real-sector/consumer-price-index-antigua-and-barbuda/m', '2026-10-31', 'The health index rose about 2% a year over 2018-2025 but swings widely, so we plan with the 3% headline projection plus one point for imported medical costs.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AG', 1, 'gold_return_base', 0.05, NULL, 'assumption', 'EC dollar fixed at 2.70 per US dollar (World Bank PA.NUS.FCRF)', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=AG', '2026-10-31', 'Long-run dollar gold trend of about 4-5% with no expected EC-dollar depreciation under the peg.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AG', 1, 'gold_return_high', 0.08, NULL, 'assumption', 'EC dollar fixed at 2.70 per US dollar (World Bank PA.NUS.FCRF)', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=AG', '2026-10-31', 'High case with strong dollar gold prices.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AG', 1, 'gold_return_low', 0.02, NULL, 'assumption', 'EC dollar fixed at 2.70 per US dollar (World Bank PA.NUS.FCRF)', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=AG', '2026-10-31', 'Low case: weak dollar gold prices with no currency depreciation under the peg.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AG', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No statutory retirement gratuity found; the Labour Code''s severance pay applies only on redundancy or dismissal after a year of service, and the official text of the Code could not be read to confirm the scale.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AG', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a major private hospital stay found for Antigua and Barbuda.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AG', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No regulator or other non-company source publishing private health insurance premiums by age found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AG', 1, 'inflation_cpi', 0.07, NULL, 'sourced', 'Statistics Division, Ministry of Finance and Corporate Governance: Consumer Price Index for September 2026 (release of 2 October 2026)', 'https://statistics.gov.ag/consumer-price-index-cpi-for-july-2026-increased-by-7-0/', '2026-09-30', 'CPI rose 7.0% in the twelve months to September 2026 (1.1% in the month); the year-on-year rate climbed from 3.7% in June 2026, and was 3.1% in December 2025 (Statistics Division monthly inflation table).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AG', 1, 'inflation_projection', 0.03, NULL, 'assumption', 'Statistics Division monthly year-on-year CPI rates (2019-2026); EC dollar pegged to the US dollar at 2.70', 'https://statistics.gov.ag/subjects/consumer-price-index/monthly-consumer-price-inflation-rates/', '2026-10-31', 'The ECCB has no inflation target but the fixed US-dollar peg anchors prices; year-on-year inflation swung between about -1% and 7% in 2025-2026 and averaged about 3% over the longer run, so we plan with 3% despite the September 2026 spike.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AG', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life cover is sold in Antigua and Barbuda, but no regulator or other non-company source publishes premium rates by age.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AG', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched the Financial Services Regulatory Commission''s material: no industry-wide life claim settlement ratio published.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AG', 1, 'life_expectancy', 77.766, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=AG', '2024-12-31', 'UN WPP 2024 (via populationpyramid.net) gives 78.1 for 2026 (men 75.1, women 80.7).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AG', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":22.3,"men":19.9,"women":24.6},{"age":65,"total":18.6,"men":16.3,"women":20.4},{"age":70,"total":14.7,"men":12.9,"women":16.4},{"age":80,"total":8.4,"men":7,"women":9.8}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/antigua-and-barbuda/', '2026-12-31', 'Secondary source of UN WPP 2024 medium variant for 2026; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AG', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'No old-age assistance open to new claimants: the Old-age Assistance Programme covers only people who were 65 or older in 1993 (UN ECLAC non-contributory programmes database, https://dds.cepal.org/bpsnc/programme?id=145).', 1);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AG', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'The only non-contributory old-age pension, the Old-age Assistance Programme (EC$255 a month), is limited to people who were 65 or older in 1993 (or blind or disabled), so no one planning today can receive it (UN ECLAC non-contributory programmes database, https://dds.cepal.org/bpsnc/programme?id=145).', 1);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AG', 1, 'oop_health_share', 0.2081, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=AG', '2023-12-31', 'Latest year available (2023), older than 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AG', 1, 'policy_rate', 0.03, NULL, 'sourced', 'Eastern Caribbean Central Bank, interest rates on deposits and loans (ECCB table, country Antigua and Barbuda)', 'https://www.eccb-centralbank.org/statistics-category/mfs-interest-rates/interest-rates-on-deposits-and-loans/m', '2026-08-31', 'ECCB discount rate for short-term credit 3.0%, unchanged through August 2026 in the ECCB table (Antigua and Barbuda selected).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AG', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":65,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":true}', 'sourced', 'Antigua and Barbuda Social Security Board: Age Benefit', 'https://socialsecurity.gov.ag/age-benefits/', '2026-10-31', 'Compulsory social security for employees and the self-employed: age pension from 65 of 25% of average insurable earnings (best 5 of the last 10 years) for the minimum contributions plus 1% per 50 further weekly contributions, up to 50%; minimum EC$350 a month; a lump-sum age grant if fewer contributions; early claims cut 0.5% a month. No automatic indexation found; pensions are untaxed since personal income tax was abolished.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AG', 1, 'retirement_accumulation_return_base', 0.05, NULL, 'assumption', 'Mix of EC-dollar deposits/bills (2-4.5%) and global equities (6.5% base)', 'https://www.eccb-centralbank.org/statistics-category/regional-government-securities-market/weighted-average-interest-rates-on-the-rgsm/m', '2026-10-31', 'Base case for a roughly half-and-half mix of safe EC-dollar assets and global equities.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AG', 1, 'retirement_accumulation_return_high', 0.07, NULL, 'assumption', 'Mix of EC-dollar bills and global equities (9% high case)', 'https://www.eccb-centralbank.org/statistics-category/regional-government-securities-market/weighted-average-interest-rates-on-the-rgsm/m', '2026-10-31', 'High case with a strong equity decade.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AG', 1, 'retirement_accumulation_return_low', 0.035, NULL, 'assumption', 'Mix of EC-dollar deposits/bills (2-4.5%) and global equities', 'https://www.eccb-centralbank.org/statistics-category/regional-government-securities-market/weighted-average-interest-rates-on-the-rgsm/m', '2026-10-31', 'Low case for a balanced mix in a weak decade.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AG', 1, 'retirement_age_default', 65, NULL, 'sourced', 'Antigua and Barbuda Social Security Board: media release on pension and contribution rate adjustments', 'https://socialsecurity.gov.ag/media-release-pension-contribution-rate-adjustments/', '2025-01-01', 'Social security pensionable age moved to 65 on 1 January 2025 (Statutory Instrument 2016 No. 61), the end of the phased rise from 60; there is no separate statutory private-sector retirement age.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AG', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'Public officers historically retired at 60; a 2019-2020 bill to raise the public service retirement age to 65 was reported, but its enactment could not be confirmed from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AG', 1, 'retirement_return_base', 0.03, NULL, 'assumption', 'ECCB: 12-month deposits up to 2.5%; 365-day T-bill 4.50% (ECCB table, country Antigua and Barbuda)', 'https://www.eccb-centralbank.org/statistics-category/regional-government-securities-market/weighted-average-interest-rates-on-the-rgsm/m', '2026-10-31', 'Base case below the 4.5% 1-year government bill rate, mixing deposits and bills.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AG', 1, 'retirement_return_high', 0.04, NULL, 'assumption', 'ECCB RGSM: 365-day T-bill 4.50%; 2-year bond 4.00%', 'https://www.eccb-centralbank.org/statistics-category/regional-government-securities-market/weighted-average-interest-rates-on-the-rgsm/m', '2026-10-31', 'High case: mostly 1-year government bills and short bonds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AG', 1, 'retirement_return_low', 0.02, NULL, 'assumption', 'ECCB: savings and 3-month deposits about 2.0% (ECCB table, country Antigua and Barbuda)', 'https://www.eccb-centralbank.org/statistics-category/mfs-interest-rates/interest-rates-on-deposits-and-loans/m', '2026-10-31', 'Low case: savings and short deposits, untaxed for residents.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AG', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate or retail savings bond for individuals found for Antigua and Barbuda; government securities are sold by auction on the Regional Government Securities Market.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AG', 1, 'savings_account_rate', 0.0205, NULL, 'sourced', 'Eastern Caribbean Central Bank, interest rates and weighted average rates on deposits and loans (ECCB table, country Antigua and Barbuda)', 'https://www.eccb-centralbank.org/statistics-category/mfs-interest-rates/interest-rates-and-weighted-averages-rates-on-deposits-and-loans/q', '2026-06-30', 'Weighted average EC-dollar savings deposit rate 2.05%; quoted savings rates range 2.00-2.25%, and the ECCB minimum savings rate is 2%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AG', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":5.7},{"year":2040,"value":3.1},{"year":2065,"value":1.9}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/antigua-and-barbuda/2040/', '2025-12-31', '100 / old-age dependency ratio: 17.6 (2025, World Bank), 32.4 (2040) and 53.5 (2065, populationpyramid.net/antigua-and-barbuda/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AG', 1, 'tax_bank_interest', 0, NULL, 'sourced', 'Caribbean Journal (news): Antigua and Barbuda abolishes personal income tax', 'https://www.caribjournal.com/2016/01/21/antigua-and-barbuda-is-abolishing-its-personal-income-tax/', '2016-04-01', 'Personal income tax was abolished from April 2016, so resident individuals pay no tax on bank interest (a withholding tax applies to non-residents). Secondary source from 2016 (older than 2025); the Inland Revenue Department''s list of taxes (October 2026) still shows no personal income tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AG', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate for individuals exists to tax; resident individuals pay no income tax on investment income since 2016.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AG', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Government of Antigua and Barbuda issued no 91-day bills in 2025-2026; its latest bills were 180-day at 3.00% (July 2026) and 365-day at 4.50% (September 2026), per the ECCB RGSM weighted average rates table.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AG', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 10-year Antigua and Barbuda bond auctioned on the RGSM in 2025-2026 per the ECCB RGSM weighted average rates table.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AG', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 5-year Antigua and Barbuda bond auctioned on the RGSM in 2025-2026; the ECCB RGSM table shows only a 2-year bond at 4.00% (May 2026) and a 3-year bond at 5.80% (September 2025).', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('AL', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"AL","iso3":"ALB","nameEn":"Albania","nameNative":"Shqipëria","region":"europe_central_asia","languages":["sq","en","it","el"],"currency":{"code":"ALL","symbol":"L","decimals":2,"compact":"intl","usdRate":{"value":81.16,"status":"sourced","sourceName":"Bank of Albania, official exchange rate","sourceUrl":"https://www.bankofalbania.org/Markets/Official_exchange_rate/","asOf":"2026-10-30","note":"ALL 81.16 per USD (ALL 90.90 per EUR) on 30 Oct 2026; 81.12 on 2 Nov 2026. World Bank 2025 average 86.80. Prices are written with ''L'' or ''Lekë''."}},"instruments":{"savings_account":{"available":true,"localName":"Llogari kursimi","localNameEn":"Savings account","sourceUrl":"https://www.bankofalbania.org/Mbikeqyrja/Sistemi_financiar_normat_e_interesit_dhe_komisionet/Normat_e_interesit_te_depozitave/"},"fdr_3m":{"available":true,"localName":"Depozitë me afat 3-mujore","localNameEn":"3-month time deposit","sourceUrl":"https://www.bankofalbania.org/Mbikeqyrja/Sistemi_financiar_normat_e_interesit_dhe_komisionet/Normat_e_interesit_te_depozitave/"},"fdr_1y":{"available":true,"localName":"Depozitë me afat 12-mujore","localNameEn":"12-month time deposit","sourceUrl":"https://www.bankofalbania.org/Mbikeqyrja/Sistemi_financiar_normat_e_interesit_dhe_komisionet/Normat_e_interesit_te_depozitave/"},"dps":{"available":false,"localName":null,"note":"No standard monthly recurring deposit product with a published rate was found."},"sanchayapatra_5y":{"available":true,"localName":"Obligacione qeveritare 5-vjeçare","localNameEn":"5-year government bonds bought by individuals","note":"No separate savings certificate; individuals buy treasury bills and bonds at Bank of Albania desks or licensed institutions.","sourceUrl":"https://www.bankofalbania.org/Markets/Government_securities/Treasury_bills/"},"tbill_91d":{"available":true,"localName":"Bono thesari 3-mujore","localNameEn":"3-month treasury bill","note":"Individuals may bid at the auctions.","sourceUrl":"https://www.bankofalbania.org/Markets/Government_securities/Treasury_bills/Results_of_auctions/"},"tbond_5y":{"available":true,"localName":"Obligacion 5-vjeçar","localNameEn":"5-year government bond","sourceUrl":"https://www.bankofalbania.org/Markets/Government_securities/Benchmark_Securities/Benchmark_rates_fixing/"},"tbond_10y":{"available":true,"localName":"Obligacion 10-vjeçar","localNameEn":"10-year government bond","note":"Issued occasionally; no recent auction found.","sourceUrl":"https://www.bankofalbania.org/Markets/Government_securities/Bonds/"},"equity_fund":{"available":true,"localName":"Fond investimi","localNameEn":"Investment fund","note":"Retail investment funds supervised by the Financial Supervisory Authority exist but mostly hold bonds; there is no liquid local stock market, so diversified equity exposure is mainly through foreign funds."},"gold":{"available":true,"localName":"Ar fizik","localNameEn":"Gold bars and coins","note":"No restriction on buying physical gold was found."}},"institutions":{"centralBank":{"name":"Bank of Albania (Banka e Shqipërisë)","url":"https://www.bankofalbania.org/"},"insuranceRegulator":{"name":"Financial Supervisory Authority (Autoriteti i Mbikëqyrjes Financiare)","url":"https://amf.gov.al/"},"insuranceComplaints":{"name":"Financial Supervisory Authority (AMF) complaints","url":"https://amf.gov.al/","note":"Complaints about insurers go to the AMF; its site refused automated access, so the exact page was not checked."},"pensionScheme":{"name":"Social Insurance Institute (Instituti i Sigurimeve Shoqërore) – old-age pension","url":"https://www.issh.gov.al/pensioni-i-pleqerise/"},"oldAgeAllowance":{"name":"Social pension (Pensioni social), ISSH","url":"https://www.issh.gov.al/te-tjera/"},"publicHealthCover":{"name":"Compulsory Health Care Insurance Fund (FSDKSH)","url":"https://www.fsdksh.gov.al/"},"depositInsurance":{"name":"Deposit Insurance Agency (Agjencia e Sigurimit të Depozitave)","url":"https://www.asd.gov.al/"},"statistics":{"name":"Institute of Statistics (INSTAT)","url":"https://www.instat.gov.al/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AL', 1, 'bank_deposit_avg_rate', 0.0177, NULL, 'sourced', 'Bank of Albania, interest rate statistics (new lek time deposits of households)', 'https://www.bankofalbania.org/Statistikat/Statistikat_e_normave_te_interesit/Statistikat_e_normave_te_interesit_te_institucioneve_monetare_financiare_IMF/', '2026-09-30', 'Weighted average rate on new household lek time deposits, September 2026 (preliminary; time-series file ''Statistikat e normave te interesit, Seri kohore, Shtator 2026'', Table 3.1); up to 1 year 1.40%. Outstanding household lek overnight deposits paid 0.05%. World Bank FR.INR.DPST 1.86% (2024).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AL', 1, 'credit_card_rate_cap', 0.2791, NULL, 'sourced', 'Bank of Albania, maximum APR for consumer credit', 'https://www.bankofalbania.org/Mbikeqyrja/NEI_Maksimal_per_kredite_konsumatore/', '2026-07-17', 'Legal maximum APR for lek credit cards (0-200,000 lek) from 17 July 2026; 24.46% for euro cards.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AL', 1, 'deposit_insurance_limit', 2500000, NULL, 'sourced', 'Deposit Insurance Agency (ASD), compensation amount', 'https://asd.gov.al/faqja-kryesore/sigurimi-i-depozitave/sa/', '2026-10-31', 'ALL 2,500,000 per depositor per bank, regardless of number of deposits or currency.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AL', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No standard monthly recurring deposit product with a published rate was found in the Bank of Albania deposit rate comparison.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AL', 1, 'equity_return_base', 0.06, NULL, 'assumption', '12-month T-bill 3.06% less 15% tax = 2.6%; global equity in lek terms', 'https://www.bankofalbania.org/Markets/Government_securities/Treasury_bills/Results_of_auctions/', '2026-10-31', 'Albania has no liquid local equity market, so the base case is a global index in lek terms, kept within 4 points of the 2.6% after-tax safe rate because the lek has appreciated.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AL', 1, 'equity_return_high', 0.085, NULL, 'assumption', 'Global equity long-run record; World Bank PA.NUS.FCRF', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=AL', '2026-10-31', 'High case near long-run global equity returns with a stable lek.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AL', 1, 'equity_return_low', 0.03, NULL, 'assumption', 'World Bank PA.NUS.FCRF (ALL per USD 86.8 in 2025); Bank of Albania rate 81.16 on 30 Oct 2026', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=AL', '2026-10-31', 'Low case for a global index fund in lek terms if world shares are weak and the lek keeps appreciating; there is no meaningful local stock market.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AL', 1, 'fdr_1y_rate', 0.012, NULL, 'sourced', 'Bank of Albania, lek deposit rates offered by banks (comparison table)', 'https://www.bankofalbania.org/Mbikeqyrja/Sistemi_financiar_normat_e_interesit_dhe_komisionet/Normat_e_interesit_te_depozitave/', '2026-07-31', '12-month lek time deposits typically 1.0-1.4% for standard tiers in the July 2026 comparison; the central bank average on new household lek deposits up to 1 year was 1.40% in September 2026 (interest rate statistics, Table 3.1).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AL', 1, 'fdr_3m_rate', 0.005, NULL, 'sourced', 'Bank of Albania, lek deposit rates offered by banks (comparison table)', 'https://www.bankofalbania.org/Mbikeqyrja/Sistemi_financiar_normat_e_interesit_dhe_komisionet/Normat_e_interesit_te_depozitave/', '2026-07-31', '3-month lek time deposits typically 0.3-0.7% for standard tiers; midpoint used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AL', 1, 'fixed_income_return_base', 0.025, NULL, 'assumption', '12-month T-bill 3.06% (27 Oct 2026) less 15% tax = 2.6%', 'https://www.bankofalbania.org/Markets/Government_securities/Treasury_bills/Results_of_auctions/', '2026-10-31', 'Base case: rolling 12-month treasury bills bought by individuals, after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AL', 1, 'fixed_income_return_high', 0.04, NULL, 'assumption', '5-year government bond 5.10% (30 Oct 2026) less 15% tax = 4.3%', 'https://www.bankofalbania.org/Markets/Government_securities/Benchmark_Securities/Benchmark_rates_fixing/', '2026-10-31', 'High case: 5-year government bonds held to maturity after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AL', 1, 'fixed_income_return_low', 0.01, NULL, 'assumption', 'Bank of Albania deposit rate table: 12-month lek deposits 1.0-1.4%, less 15% tax', 'https://www.bankofalbania.org/Mbikeqyrja/Sistemi_financiar_normat_e_interesit_dhe_komisionet/Normat_e_interesit_te_depozitave/', '2026-10-31', 'Low case: bank term deposits after 15% tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AL', 1, 'goal_inflation_education', 0.04, NULL, 'assumption', 'INSTAT CPI September 2026 (education services +1.2% in the month); 3% target', 'https://www.instat.gov.al/media/cvkbetti/cpi_september_2026.pdf', '2026-10-31', 'Education prices rise in steps each school year, so we plan with the 3% projection plus one point.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AL', 1, 'goal_inflation_health', 0.04, NULL, 'assumption', 'INSTAT CPI September 2026 (health group contributed +0.06 points); 3% target', 'https://www.instat.gov.al/media/cvkbetti/cpi_september_2026.pdf', '2026-10-31', 'INSTAT does not publish the health group''s annual rate in the release, so we plan with the 3% projection plus one point for private medical costs.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AL', 1, 'gold_return_base', 0.04, NULL, 'assumption', 'World Bank PA.NUS.FCRF (ALL per USD 86.8 in 2025, 81.2 in Oct 2026)', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=AL', '2026-10-31', 'Long-run dollar gold trend of about 4-5% less a slight lek appreciation trend against the dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AL', 1, 'gold_return_high', 0.08, NULL, 'assumption', 'World Bank PA.NUS.FCRF (ALL per USD 86.8 in 2025, 81.2 in Oct 2026)', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=AL', '2026-10-31', 'High case with strong dollar gold and a stable or weaker lek.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AL', 1, 'gold_return_low', 0, NULL, 'assumption', 'World Bank PA.NUS.FCRF (ALL per USD 86.8 in 2025, 81.2 in Oct 2026)', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=AL', '2026-10-31', 'Low case: flat dollar gold and a further stronger lek.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AL', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Albanian Labour Code provides a seniority payment when employment ends, but its text could not be read (ILO NATLEX and EPLex refused automated access, and web search was unavailable to the verifier), so the days per year of service and the conditions are not confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AL', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical out-of-pocket cost of a major private hospital stay in Albania was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AL', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premiums by age band were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AL', 1, 'inflation_cpi', 0.029, NULL, 'sourced', 'INSTAT, Consumer Price Index September 2026', 'https://www.instat.gov.al/media/cvkbetti/cpi_september_2026.pdf', '2026-09-30', 'Annual CPI 2.9% in September 2026 (2.4% a year earlier); published 8 October 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AL', 1, 'inflation_projection', 0.03, NULL, 'assumption', 'Bank of Albania 3% inflation target; CPI 2.9% (Sep 2026), 2.1% (2025, World Bank)', 'https://www.instat.gov.al/media/cvkbetti/cpi_september_2026.pdf', '2026-10-31', 'The Bank of Albania targets 3% CPI inflation and recent inflation has run close to it, so the target is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AL', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life cover is sold mainly with bank loans; no published per-1,000 premium rates by age were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AL', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Financial Supervisory Authority (AMF) site refused automated access and no industry-wide life claim settlement ratio was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AL', 1, 'life_expectancy', 79.78, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=AL', '2024-12-31', 'Men 77.9, women 81.6. 2024 figure, the latest World Bank value (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AL', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":23.3,"men":22.2,"women":24.3},{"age":65,"total":19.1,"men":18.2,"women":19.9},{"age":70,"total":15,"men":14.4,"women":15.6},{"age":80,"total":8.5,"men":8,"women":8.9}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/albania/', '2026-12-31', 'Secondary source of UN WPP 2024 medium variant for 2026; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AL', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":70,"womenAge":70,"over90Monthly":null,"meansTested":true}', 'sourced', 'Social Insurance Institute (ISSH), social pension', 'https://www.issh.gov.al/te-tjera/', '2026-07-01', 'Age 70, resident in Albania for the last 5 years, not entitled to a contributory pension, and no income or income below the social pension.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AL', 1, 'old_age_allowance_monthly', 10222, NULL, 'sourced', 'Social Insurance Institute (ISSH), social pension', 'https://www.issh.gov.al/te-tjera/', '2026-07-01', 'Social pension ALL 10,222 a month from 1 July 2026 (Council of Ministers Decision No. 497 of 26.06.2026); reduced by any other income.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AL', 1, 'oop_health_share', 0.4827, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=AL', '2023-12-31', '2023 figure, the latest World Bank value (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AL', 1, 'policy_rate', 0.025, NULL, 'sourced', 'Bank of Albania, interest rates (base rate, one-week repo)', 'https://www.bankofalbania.org/Statistics/Interest_rates/', '2026-10-07', 'Base rate 2.50% since 9 July 2025, kept unchanged at the 7 October 2026 meeting (Trading Economics).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AL', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":67,"nomineeUntilAge":null,"inflationLinked":true,"taxFree":true}', 'sourced', 'Law 7703 on Social Insurance (ISSH consolidated text 2023), Art. 31, 61, 92', 'https://www.issh.gov.al/wp-content/uploads/2023/09/LIGJ-Nr.-7703-date-11.05.1993_i-perditesuar_2023.pdf', '2026-01-01', 'Compulsory pay-as-you-go social insurance pension (ISSH): pension age 65 for men and 62 for women in 2026, rising to 67 for both by 2056 (Art. 92), so 67 for someone born after 1975; minimum 15 years of insurance; pensions are indexed every year for price changes (Art. 61); social insurance income is exempt from personal income tax (PwC).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AL', 1, 'retirement_accumulation_return_base', 0.045, NULL, 'assumption', '12-month T-bill after tax 2.6%; 5-year bond 5.1%; global equity base 6%', 'https://www.bankofalbania.org/Markets/Government_securities/Benchmark_Securities/Benchmark_rates_fixing/', '2026-10-31', 'Base case: about half global equity at 6% and half lek government bonds at about 3.5-4% after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AL', 1, 'retirement_accumulation_return_high', 0.06, NULL, 'assumption', '5-year bond 5.1%; global equity high case 8.5%', 'https://www.bankofalbania.org/Markets/Government_securities/Benchmark_Securities/Benchmark_rates_fixing/', '2026-10-31', 'High case for a growth-leaning balanced mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AL', 1, 'retirement_accumulation_return_low', 0.025, NULL, 'assumption', '12-month T-bill after tax 2.6%; global equity in lek terms', 'https://www.bankofalbania.org/Markets/Government_securities/Treasury_bills/Results_of_auctions/', '2026-10-31', 'Low case for a balanced mix if shares lag and the lek keeps rising.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AL', 1, 'retirement_age_default', 67, NULL, 'sourced', 'Law 7703 on Social Insurance (ISSH consolidated text 2023), Art. 92', 'https://www.issh.gov.al/wp-content/uploads/2023/09/LIGJ-Nr.-7703-date-11.05.1993_i-perditesuar_2023.pdf', '2026-01-01', 'Under Law 7703 Art. 92 (as amended by Law 104/2014) the pension age is 65 for men in 2026 (women 62), rising by one month a year from 2033 for men (two months a year for women) until both reach 67 in 2056. Anyone born after 1975 retires at between 65 years 9 months (born 1976) and 67 (born 1989 or later), so 67 is used for planning. 40 years of insurance for a full pension from 2029, 15 years minimum.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AL', 1, 'retirement_age_government', 67, NULL, 'sourced', 'Law 7703 on Social Insurance (ISSH consolidated text 2023), Art. 92', 'https://www.issh.gov.al/wp-content/uploads/2023/09/LIGJ-Nr.-7703-date-11.05.1993_i-perditesuar_2023.pdf', '2026-01-01', 'Civil servants follow the same social insurance pension age (no separate general retirement age for government employees was found): 65 for men in 2026, rising to 67 by 2056; 67 applies to anyone born from 1989 and is used for planning.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AL', 1, 'retirement_return_base', 0.025, NULL, 'assumption', '12-month T-bill 3.06% less 15% tax = 2.6%', 'https://www.bankofalbania.org/Markets/Government_securities/Treasury_bills/Results_of_auctions/', '2026-10-31', 'Base case capped at the after-tax 12-month treasury bill rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AL', 1, 'retirement_return_high', 0.035, NULL, 'assumption', '3-5-year government bonds 4.5-5.1% less 15% tax', 'https://www.bankofalbania.org/Markets/Government_securities/Benchmark_Securities/Benchmark_rates_fixing/', '2026-10-31', 'High case: a ladder of 3- to 5-year government bonds after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AL', 1, 'retirement_return_low', 0.01, NULL, 'assumption', '12-month lek deposits 1.0-1.4% less 15% tax', 'https://www.bankofalbania.org/Mbikeqyrja/Sistemi_financiar_normat_e_interesit_dhe_komisionet/Normat_e_interesit_te_depozitave/', '2026-10-31', 'Low case: bank term deposits after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AL', 1, 'sanchayapatra_5y_rate', 0.051, NULL, 'sourced', 'Bank of Albania, 5-year benchmark yield fixing and bond auction results', 'https://www.bankofalbania.org/Markets/Government_securities/Benchmark_Securities/Benchmark_rates_fixing/', '2026-10-30', 'Individuals can buy government securities at Bank of Albania desks or licensed institutions; the 5-year fixed-coupon bond fixed at 5.10% on 30 Oct 2026 and the 20 Oct 2026 auction accepted 5.10-5.45%. There is no separate savings certificate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AL', 1, 'savings_account_rate', 0.003, NULL, 'sourced', 'Bank of Albania, lek deposit rates offered by banks (comparison table)', 'https://www.bankofalbania.org/Mbikeqyrja/Sistemi_financiar_normat_e_interesit_dhe_komisionet/Normat_e_interesit_te_depozitave/', '2026-07-31', 'Demand/savings deposits in lek pay typically 0.1-0.7% at banks (range 0.03-3%); the central bank average on household overnight lek deposits was only 0.05% in September 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AL', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":3.73},{"year":2040,"value":2.48},{"year":2065,"value":1.3}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/albania/2040/', '2025-12-31', '100 / old-age dependency ratio: 26.8 (2025, World Bank), 40.4 (2040) and 77.2 (2065, populationpyramid.net/albania/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AL', 1, 'tax_bank_interest', 0.15, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Albania, taxes on personal income', 'https://taxsummaries.pwc.com/albania/individual/taxes-on-personal-income', '2026-07-22', 'Investment income other than dividends (8%) is taxed at 15%, withheld at source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AL', 1, 'tax_sanchayapatra_profit', 0.15, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Albania, taxes on personal income', 'https://taxsummaries.pwc.com/albania/individual/taxes-on-personal-income', '2026-07-22', 'Government securities interest falls under other investment income at 15%; no exemption is listed for it.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AL', 1, 'tbill_91d_rate', 0.0246, NULL, 'sourced', 'Bank of Albania, treasury bill auction results', 'https://www.bankofalbania.org/Markets/Government_securities/Treasury_bills/Results_of_auctions/', '2026-10-06', 'Weighted average yield of the 3-month T-bill auction no. 2102 on 6 October 2026; the 12-month bill yielded 3.06% on 27 October 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AL', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Bank of Albania auction pages showed only the latest 3-, 5- and 7-year auctions (7-year 5.25% on 12 Oct 2026); no recent 10-year yield was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AL', 1, 'tbond_5y_rate', 0.051, NULL, 'sourced', 'Bank of Albania, daily benchmark yield fixing (5Y)', 'https://www.bankofalbania.org/Markets/Government_securities/Benchmark_Securities/Benchmark_rates_fixing/', '2026-10-30', '5-year benchmark fixing 5.10% (3-year 4.51%, 4-year 4.66% the same day); unchanged on 2 Nov 2026. The 20 Oct 2026 5-year auction accepted 5.10-5.45%.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('AM', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"AM","iso3":"ARM","nameEn":"Armenia","nameNative":"Հայաստան","region":"europe_central_asia","languages":["hy","ru","en"],"currency":{"code":"AMD","symbol":"֏","decimals":2,"compact":"intl","usdRate":{"value":360.14,"status":"sourced","sourceName":"Central Bank of Armenia, exchange rates archive (USD)","sourceUrl":"https://www.cba.am/en/exchange-rates-archive/","asOf":"2026-10-30","note":"AMD 360.14 per USD on 30 Oct 2026 (360.50 on 2 Nov 2026); World Bank 2025 average 387.01."}},"instruments":{"savings_account":{"available":true,"localName":"Խնայողական հաշիվ","localNameEn":"Savings account","note":"No published typical rate."},"fdr_3m":{"available":true,"localName":"Ժամկետային ավանդ","localNameEn":"3-month term deposit","sourceUrl":"https://www.cba.am/en/statistics/financial-market-interest-rates-monthly/221"},"fdr_1y":{"available":true,"localName":"Ժամկետային ավանդ","localNameEn":"1-year term deposit","sourceUrl":"https://www.cba.am/en/statistics/financial-market-interest-rates-monthly/221"},"dps":{"available":false,"localName":null,"note":"No monthly recurring deposit product with a published rate was found."},"sanchayapatra_5y":{"available":true,"localName":"Խնայողական պարտատոմսեր","localNameEn":"Saving coupon bonds","note":"Sold only to individuals through Treasury Direct, 3 months to 25 years, tax-exempt; none were on sale when checked.","sourceUrl":"https://minfin.am/en/page/treasury_direct_/"},"tbill_91d":{"available":true,"localName":"Կարճաժամկետ պետական պարտատոմսեր","localNameEn":"Treasury bills","note":"Individuals can buy through Treasury Direct; income tax-exempt.","sourceUrl":"https://www.cba.am/en/yield-curves-of-gb/"},"tbond_5y":{"available":true,"localName":"Միջնաժամկետ պետական պարտատոմսեր","localNameEn":"Medium-term government coupon bonds","note":"Up to 10% of each issue is offered through Treasury Direct.","sourceUrl":"https://www.cba.am/en/yield-curves-of-gb/"},"tbond_10y":{"available":true,"localName":"Երկարաժամկետ պետական պարտատոմսեր","localNameEn":"Long-term government coupon bonds","sourceUrl":"https://www.cba.am/en/yield-curves-of-gb/"},"equity_fund":{"available":true,"localName":"Կամավոր կենսաթոշակային ֆոնդ","localNameEn":"Voluntary pension fund","note":"There is no liquid local stock market; diversified equity exposure is mainly through pension funds or foreign funds."},"gold":{"available":true,"localName":"Ոսկե ձուլակտոր","localNameEn":"Gold bars","note":"No restriction on buying physical gold was found."}},"institutions":{"centralBank":{"name":"Central Bank of Armenia","url":"https://www.cba.am/en/"},"insuranceRegulator":{"name":"Central Bank of Armenia (insurance supervision)","url":"https://www.cba.am/en/financial-system-regulation-and-supervision/"},"insuranceComplaints":{"name":"Financial System Mediator","url":"https://fsm.am/"},"pensionScheme":{"name":"Ministry of Labour and Social Affairs – pensions","url":"https://welfare.gov.am/en/pensions-1"},"oldAgeAllowance":{"name":"Old-age social pension (Ministry of Labour and Social Affairs)","url":"https://welfare.gov.am/en/pensions-1"},"publicHealthCover":{"name":"Ministry of Health – state-guaranteed basic benefits package","url":"https://www.moh.am/"},"depositInsurance":{"name":"Deposit Guarantee Fund of Armenia","url":"https://www.adgf.am/en"},"statistics":{"name":"Statistical Committee of the Republic of Armenia (Armstat)","url":"https://www.armstat.am/en/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AM', 1, 'bank_deposit_avg_rate', 0.0778, NULL, 'sourced', 'Central Bank of Armenia, average interest rate on attracted AMD deposits (up to 1 year and more)', 'https://www.cba.am/en/statistics/financial-market-interest-rates-monthly/221', '2026-09-30', 'September 2026 weighted average for new AMD deposits; World Bank FR.INR.DPST 8.03% (2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AM', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap or typical credit card rate could be read from CBA sources.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AM', 1, 'deposit_insurance_limit', 16000000, NULL, 'sourced', 'Deposit Guarantee Fund of Armenia, FAQ', 'https://www.adgf.am/en/faq', '2026-10-31', 'AMD 16,000,000 for dram deposits; AMD 7,000,000 for foreign-currency deposits, per depositor per bank.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AM', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published rate for a monthly recurring deposit product was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AM', 1, 'equity_return_base', 0.09, NULL, 'assumption', '1-year government bond 7.21% (tax-free) and 1-year deposit 8.64% less 20% tax = 6.9%; global equity in AMD', 'https://www.cba.am/en/yield-curves-of-gb/', '2026-10-31', 'Armenia has no meaningful local equity market, so the base case is a global index in dram terms, about 2 points over the tax-free 1-year government yield and within the 4-point cap.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AM', 1, 'equity_return_high', 0.12, NULL, 'assumption', 'Global equity long-run record plus dram depreciation', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=AM', '2026-10-31', 'High case with strong global shares and a weaker dram.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AM', 1, 'equity_return_low', 0.05, NULL, 'assumption', 'World Bank PA.NUS.FCRF (AMD per USD 387 in 2025); CBA rate 360.14 on 30 Oct 2026', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=AM', '2026-10-31', 'Low case for a global index fund in dram terms if shares are weak and the dram keeps appreciating; the local exchange is too small for a diversified fund.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AM', 1, 'fdr_1y_rate', 0.0864, NULL, 'sourced', 'Central Bank of Armenia, interest rates on attracted deposits (181 days-1 year, AMD)', 'https://www.cba.am/en/statistics/financial-market-interest-rates-monthly/221', '2026-09-30', 'Weighted average rate on new AMD deposits (households and firms) of 181 days to 1 year in September 2026 (file 11_Deposit_rates_eng.xlsx); over 1 year 9.43%. USD deposits pay about 3.3%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AM', 1, 'fdr_3m_rate', 0.0813, NULL, 'sourced', 'Central Bank of Armenia, interest rates on attracted deposits (61-90 days, AMD)', 'https://www.cba.am/en/statistics/financial-market-interest-rates-monthly/221', '2026-09-30', 'Weighted average rate on new AMD deposits of 61-90 days in September 2026 (file 11_Deposit_rates_eng.xlsx); 91-180 days 7.71%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AM', 1, 'fixed_income_return_base', 0.068, NULL, 'assumption', '1-year deposit 8.64% less 20% tax = 6.9%; 1-year government yield 7.21% tax-free', 'https://www.cba.am/en/statistics/financial-market-interest-rates-monthly/221', '2026-10-31', 'Base case: 1-year deposits after tax or 1-year government securities.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AM', 1, 'fixed_income_return_high', 0.08, NULL, 'assumption', '5-year government yield 8.15% (tax-free through Treasury Direct)', 'https://www.cba.am/en/yield-curves-of-gb/', '2026-10-31', 'High case: 5-year government bonds held to maturity.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AM', 1, 'fixed_income_return_low', 0.06, NULL, 'assumption', '3-month T-bill 6.77% (tax-free); 61-90 day deposits 8.13% less 20% tax = 6.5%', 'https://www.cba.am/en/yield-curves-of-gb/', '2026-10-31', 'Low case: rolling short bills or deposits after tax, allowing for policy rate cuts.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AM', 1, 'goal_inflation_education', 0.045, NULL, 'assumption', 'Armstat CPI 4.4% (Aug 2026); 3.5% planning inflation', 'https://www.armstat.am/en/?nid=12&id=07001', '2026-10-31', 'No Armenian education price index was read, so we plan with the 3.5% projection plus one point for fees.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AM', 1, 'goal_inflation_health', 0.045, NULL, 'assumption', 'Armstat CPI 4.4% (Aug 2026); 3.5% planning inflation', 'https://www.armstat.am/en/?nid=12&id=07001', '2026-10-31', 'No Armenian medical price index was read, so we plan with the 3.5% projection plus one point; most health costs are paid out of pocket.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AM', 1, 'gold_return_base', 0.06, NULL, 'assumption', 'World Bank PA.NUS.FCRF (AMD per USD 387 in 2025, 360 in Oct 2026)', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=AM', '2026-10-31', 'Dollar gold trend of about 4-5% plus about 1% a year of dram weakness over the long run.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AM', 1, 'gold_return_high', 0.1, NULL, 'assumption', 'World Bank PA.NUS.FCRF (AMD per USD 387 in 2025, 360 in Oct 2026)', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=AM', '2026-10-31', 'High case with strong dollar gold and a weaker dram.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AM', 1, 'gold_return_low', 0.02, NULL, 'assumption', 'World Bank PA.NUS.FCRF (AMD per USD 387 in 2025, 360 in Oct 2026)', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=AM', '2026-10-31', 'Low case: flat dollar gold and a stronger dram.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AM', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No statutory end-of-service gratuity for private employees was found in the Armenian Labour Code; severance applies only to dismissal.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AM', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a major private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AM', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premiums by age band were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AM', 1, 'inflation_cpi', 0.044, NULL, 'sourced', 'Statistical Committee of Armenia (Armstat), Consumer Price Index', 'https://www.armstat.am/en/?nid=12&id=07001', '2026-08-31', 'CPI August 2026 was 104.4% of August 2025 (4.4% a year). The Central Bank of Armenia reports 4.3% for September 2026 on its home page, but no page with only that figure was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AM', 1, 'inflation_projection', 0.035, NULL, 'assumption', 'CBA 3% inflation target; CPI 4.3% (Sep 2026); IMF WEO 4.6% (2026), 3.0% from 2029', 'https://www.imf.org/external/datamapper/PCPIPCH@WEO/ARM', '2026-10-31', 'The 3% target is credible over time but inflation is above it now, so 3.5% is used for planning.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AM', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published term life premium rates by age were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AM', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No industry-wide life claim settlement ratio was found; the life insurance market in Armenia is very small.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AM', 1, 'life_expectancy', 78.32, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=AM', '2024-12-31', 'Men 75.1, women 81.7. 2024 figure, the latest World Bank value (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AM', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":20.1,"men":17.8,"women":22.4},{"age":65,"total":16.6,"men":14.3,"women":18.2},{"age":70,"total":12.8,"men":11.3,"women":14.3},{"age":80,"total":7.1,"men":6.4,"women":7.8}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/armenia/', '2026-12-31', 'Secondary source of UN WPP 2024 medium variant for 2026; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AM', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'The eligibility age of the old-age social pension could not be confirmed from an official source (Wikipedia says 63, which matches the labour pension age).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AM', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'Armenia pays an old-age social pension to people without enough insurance record, but its current amount could not be read on the Ministry of Labour and Social Affairs site (pages render without text).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AM', 1, 'oop_health_share', 0.8047, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=AM', '2023-12-31', '2023 figure, the latest World Bank value (older than 2025); one of the highest out-of-pocket shares in Europe.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AM', 1, 'policy_rate', 0.0675, NULL, 'sourced', 'Central Bank of Armenia, press release on the policy rate decision of 15 September 2026', 'https://www.cba.am/en/press-releases/10606/', '2026-09-15', 'Raised by 25 bp to 6.75% at the 15 September 2026 meeting (from 6.50%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AM', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":63,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'Wikipedia, Pensions in Armenia; Wikipedia, Retirement age', 'https://en.wikipedia.org/wiki/Pensions_in_Armenia', '2026-10-31', 'State labour pension from 63 plus a mandatory funded pension for employees born after 1973 (5% of pay below AMD 500,000 a month, or 10% minus AMD 25,000 above it, with state co-financing). No automatic inflation indexation rule was found; amounts change by government decision. Secondary source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AM', 1, 'retirement_accumulation_return_base', 0.075, NULL, 'assumption', '5-year government yield 8.15%; global equity base 9% in AMD', 'https://www.cba.am/en/yield-curves-of-gb/', '2026-10-31', 'Base case: about half global equity at 9% and half dram government bonds at about 7%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AM', 1, 'retirement_accumulation_return_high', 0.09, NULL, 'assumption', '10-year government yield 8.70%; global equity high case 12%', 'https://www.cba.am/en/yield-curves-of-gb/', '2026-10-31', 'High case for a growth-leaning balanced mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AM', 1, 'retirement_accumulation_return_low', 0.06, NULL, 'assumption', '1-year government yield 7.21%; global equity low case 5%', 'https://www.cba.am/en/yield-curves-of-gb/', '2026-10-31', 'Low case for a balanced mix if shares lag and the dram strengthens.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AM', 1, 'retirement_age_default', 63, NULL, 'sourced', 'Wikipedia, Retirement age (Armenia)', 'https://en.wikipedia.org/wiki/Retirement_age', '2026-10-31', 'Old-age pension age 63 for men and women, with no legislated increase found, so it also applies to someone born after 1975; secondary source because the Ministry of Labour and Social Affairs pension pages render without text.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AM', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'The age limit for civil servants could not be confirmed from an official or secondary source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AM', 1, 'retirement_return_base', 0.065, NULL, 'assumption', '1-year deposit 8.64% less 20% tax = 6.9%; 1-year government yield 7.21%', 'https://www.cba.am/en/statistics/financial-market-interest-rates-monthly/221', '2026-10-31', 'Base case kept below the after-tax 1-year deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AM', 1, 'retirement_return_high', 0.08, NULL, 'assumption', '5-year government yield 8.15% (tax-free)', 'https://www.cba.am/en/yield-curves-of-gb/', '2026-10-31', 'High case: a ladder of government bonds up to 5 years.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AM', 1, 'retirement_return_low', 0.06, NULL, 'assumption', '3-month T-bill 6.77% (tax-free)', 'https://www.cba.am/en/yield-curves-of-gb/', '2026-10-31', 'Low case: rolling short government bills if rates fall.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AM', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Saving coupon bonds (3 months to 25 years, tax-exempt) are sold only to individuals through Treasury Direct, but the sales system listed no bonds on sale and no current coupon rate was published; the 5-year government yield curve point was 8.15% on 30 Oct 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AM', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The CBA deposit rate series covers term deposits only; no typical rate on ordinary savings/demand accounts was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AM', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":4.61},{"year":2040,"value":3.23},{"year":2065,"value":1.87}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/armenia/2040/', '2025-12-31', '100 / old-age dependency ratio: 21.7 (2025, World Bank), 31.0 (2040) and 53.5 (2065, populationpyramid.net/armenia/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AM', 1, 'tax_bank_interest', 0.2, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Armenia, taxes on personal income', 'https://taxsummaries.pwc.com/armenia/individual/taxes-on-personal-income', '2026-06-30', 'Interest, if not exempt, is taxed at 20% from 1 January 2023, withheld by the bank.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AM', 1, 'tax_sanchayapatra_profit', 0, NULL, 'sourced', 'Ministry of Finance of Armenia, Treasury Direct (saving bonds)', 'https://minfin.am/en/page/treasury_direct_/', '2026-10-31', 'Income from government securities bought through Treasury Direct, including saving bonds, is exempt from any taxation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AM', 1, 'tbill_91d_rate', 0.0677, NULL, 'sourced', 'Central Bank of Armenia, treasury bill yield curve (90 days, ACT/360)', 'https://www.cba.am/en/yield-curves-of-gb/', '2026-10-30', 'From YC_ENG.xlsx (treasury bill curve, ACT/360) for 30 Oct 2026; the 2 Nov 2026 curve shows 6.76%. The 364-day bill sold at a 6.75% weighted average in September 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AM', 1, 'tbond_10y_rate', 0.087, NULL, 'sourced', 'Central Bank of Armenia, treasury bond yield curve (10-year yield to maturity)', 'https://www.cba.am/en/yield-curves-of-gb/', '2026-10-30', '30 Oct 2026 (spot 8.92%); 8.76% on the 2 Nov 2026 curve.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AM', 1, 'tbond_5y_rate', 0.0815, NULL, 'sourced', 'Central Bank of Armenia, treasury bond yield curve (5-year yield to maturity)', 'https://www.cba.am/en/yield-curves-of-gb/', '2026-10-30', 'Nelson-Siegel curve built from government bond quotes, 30 Oct 2026 (spot 8.23%); 8.25% on the 2 Nov 2026 curve.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('AO', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"AO","iso3":"AGO","nameEn":"Angola","nameNative":"Angola","region":"sub_saharan_africa","languages":["pt","umb","kmb","kg"],"currency":{"code":"AOA","symbol":"Kz","decimals":2,"compact":"intl","usdRate":{"value":913,"status":"sourced","sourceName":"Banco Nacional de Angola, reference exchange rate (taxa de referência, venda) USD","sourceUrl":"https://www.bna.ao/service/rest/taxas/get/taxa/referencia?moeda=usd&tipocambio=b","asOf":"2026-10-30","note":"BNA reference selling rate AOA 913 per US dollar on 30 October 2026 (the BNA website''s exchange-rate feed); World Bank 2025 average AOA 912 (PA.NUS.FCRF)."}},"instruments":{"savings_account":{"available":true,"localName":"Conta poupança","localNameEn":"Savings account","note":"Offered by banks; no published average rate was found."},"fdr_3m":{"available":true,"localName":"Depósito a prazo","localNameEn":"Term deposit (3 months)","note":"No published average rate was found."},"fdr_1y":{"available":true,"localName":"Depósito a prazo","localNameEn":"Term deposit (1 year)","note":"The World Bank average deposit rate was 7.98% in 2025.","sourceUrl":"https://data.worldbank.org/indicator/FR.INR.DPST?locations=AO"},"dps":{"available":false,"localName":null,"note":"No monthly recurring-deposit product was found."},"sanchayapatra_5y":{"available":false,"localName":null,"note":"No government savings certificate or retail savings bond for individuals was found."},"tbill_91d":{"available":true,"localName":"Bilhetes do Tesouro","localNameEn":"Treasury bills","note":"Issued by the Ministry of Finance; individuals buy them through banks or exchange members. No current yield could be read."},"tbond_5y":{"available":true,"localName":"Obrigações do Tesouro","localNameEn":"Treasury bonds","note":"Treasury bonds are traded on the Angolan securities exchange. No current yield could be read."},"tbond_10y":{"available":false,"localName":"Obrigações do Tesouro","localNameEn":"Treasury bonds (10 years)","note":"A 10-year benchmark yield could not be confirmed."},"equity_fund":{"available":false,"localName":null,"note":"No diversified equity mutual or index fund for retail investors was found; the Angolan securities exchange lists only a few shares."},"gold":{"available":false,"localName":null,"note":"No retail market for investment gold bars or coins was found."}},"institutions":{"centralBank":{"name":"Banco Nacional de Angola (BNA)","url":"https://www.bna.ao/"},"insuranceRegulator":{"name":"Agência Angolana de Regulação e Supervisão de Seguros (ARSEG)","url":"https://www.arseg.ao/"},"insuranceComplaints":{"name":"ARSEG, apresentar reclamação","url":"https://www.arseg.ao/consumidor/gestao-de-reclamacoes/apresentar-reclamacao/","note":"Complain to the insurer (or its customer ombudsman) first; ARSEG also takes complaints by e-mail and phone."},"pensionScheme":{"name":"Instituto Nacional de Segurança Social (INSS)","url":"https://www.inss.gov.ao/","note":"Contributory social security: employees pay 3% and employers 8% of gross pay."},"oldAgeAllowance":null,"publicHealthCover":{"name":"Ministério da Saúde, Serviço Nacional de Saúde","url":"https://minsa.gov.ao/","note":"Runs the public National Health Service facilities."},"depositInsurance":{"name":"Fundo de Garantia de Depósitos (FGD)","url":"https://www.fgd.ao/"},"statistics":{"name":"Instituto Nacional de Estatística (INE)","url":"https://www.ine.gov.ao/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AO', 1, 'bank_deposit_avg_rate', 0.0798, NULL, 'sourced', 'World Bank WDI FR.INR.DPST (deposit interest rate)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=AO', '2025-12-31', '2025 average deposit rate 7.98% (7.40% in 2024), also shown by Trading Economics. The BNA policy rate has since been cut three times, to 14.75% in September 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AO', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap or published typical credit card interest rate was found; the World Bank lending rate was 19.4% in 2025 and Trading Economics shows 15.75% in September 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AO', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'Angola has a deposit guarantee fund (Fundo de Garantia de Depósitos), but its site could not be read (certificate error) and no other official page with the per-depositor limit was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AO', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No monthly recurring-deposit product or rate was found for Angola.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AO', 1, 'equity_return_base', 0.105, NULL, 'assumption', 'Global equity index in kwanza terms (S&P 500 via Trading Economics); after-tax safe rate about 6.8% (World Bank deposit rate 7.98% less up to 15% Investment Income Tax)', 'https://tradingeconomics.com/united-states/stock-market', '2026-10-31', 'Angola has no diversified local equity index, so this is a global equity index in kwanza terms, capped at about 4 points over the after-tax average deposit rate (6.8% after 15% tax).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AO', 1, 'equity_return_high', 0.15, NULL, 'assumption', 'Global equity index (Trading Economics); long-run kwanza depreciation against the dollar (World Bank PA.NUS.FCRF)', 'https://tradingeconomics.com/united-states/stock-market', '2026-10-31', 'High case: global shares do well and the kwanza resumes faster depreciation, lifting returns in kwanza.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AO', 1, 'equity_return_low', 0.06, NULL, 'assumption', 'No local stock index (the Angolan securities exchange lists only a few shares); S&P 500 as a global proxy (Trading Economics); World Bank deposit rate 7.98% (2025)', 'https://tradingeconomics.com/united-states/stock-market', '2026-10-31', 'Low case: global shares earn well below their record in dollars and the kwanza stays near AOA 913 per dollar, so returns trail deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AO', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published 1-year term deposit rate was found. Searched the Banco Nacional de Angola site (a script-rendered app that could not be read), the Treasury debt office (UGD) portal and the securities exchange statistics pages, which showed no rendered figures. The World Bank average deposit rate was 7.98% in 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AO', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published 3-month term deposit (depósito a prazo) rate was found. Searched the Banco Nacional de Angola site (a script-rendered app that could not be read), the Treasury debt office (UGD) portal and the securities exchange statistics pages, which showed no rendered figures.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AO', 1, 'fixed_income_return_base', 0.07, NULL, 'assumption', 'World Bank average deposit rate 7.98% (2025) less about 10% tax = 7.2%', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=AO', '2026-10-31', 'Base case: term deposits at about today''s average rate after Investment Income Tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AO', 1, 'fixed_income_return_high', 0.09, NULL, 'assumption', 'BNA policy rate 14.75% (Trading Economics); World Bank deposit rate 7.98%', 'https://tradingeconomics.com/angola/interest-rate', '2026-10-31', 'High case: savers lock in longer term deposits or Treasury bonds, which pay well above the average deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AO', 1, 'fixed_income_return_low', 0.05, NULL, 'assumption', 'World Bank average deposit rate 7.98% (2025); BNA policy rate 14.75% and falling', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=AO', '2026-10-31', 'Low case: deposit rates fall with the policy rate and Investment Income Tax of about 10-15% is withheld.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AO', 1, 'goal_inflation_education', 0.15, NULL, 'assumption', 'INE CPI September 2026: education +18.53% year on year (via Trading Economics)', 'https://tradingeconomics.com/angola/inflation-cpi', '2026-10-31', 'Education prices are rising more than twice as fast as headline inflation, so 15% is used for education goals.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AO', 1, 'goal_inflation_health', 0.12, NULL, 'assumption', 'INE CPI 8.43% (Sep 2026, via Trading Economics); 5-year CPI average about 20%', 'https://tradingeconomics.com/angola/inflation-cpi', '2026-10-31', 'No health CPI figure could be read, so health goals use the long-run planning inflation rate of 12%, since private care is priced partly in imported goods and dollars.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AO', 1, 'gold_return_base', 0.1, NULL, 'assumption', 'Gold price history (Trading Economics); expected kwanza depreciation', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Base case: dollar gold rises about 3% a year plus about 7% a year of kwanza depreciation, consistent with planning inflation of 12% against about 2.5% US inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AO', 1, 'gold_return_high', 0.16, NULL, 'assumption', 'Gold price history (Trading Economics); kwanza depreciation history (World Bank PA.NUS.FCRF)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'High case: strong dollar gold and faster kwanza depreciation, as in the 2016-2024 devaluation episodes.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AO', 1, 'gold_return_low', 0.04, NULL, 'assumption', 'Gold USD 3,876/oz on 30 Oct 2026 (Trading Economics); kwanza stable at AOA 912-913 per dollar in 2025-26 (BNA, World Bank)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Low case: dollar gold drifts after the 2025-26 spike and the kwanza holds its value.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AO', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No readable source for an end-of-service payment on retirement or resignation under the General Labour Law (Lei Geral do Trabalho, Law 12/23) was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AO', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No official figure for the out-of-pocket cost of a major private hospital stay in Angola was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AO', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No official or regulator data on private health insurance premiums by age in Angola was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AO', 1, 'inflation_cpi', 0.0843, NULL, 'sourced', 'Trading Economics, Angola inflation rate (from INE Angola, national CPI)', 'https://tradingeconomics.com/angola/inflation-cpi', '2026-09-30', 'Secondary source: 8.43% year on year in September 2026 (8.78% in August), the lowest since April 2015; the INE Angola home page indicator panel shows the same 8.43% but its release page could not be read. World Bank 2025 average 20.2%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AO', 1, 'inflation_projection', 0.12, NULL, 'assumption', 'INE CPI 8.43% (Sep 2026, via Trading Economics); World Bank CPI 20.2% in 2025; BNA governor expects 8.6% at end-2026', 'https://tradingeconomics.com/angola/inflation-cpi', '2026-10-31', 'Angola has no formal inflation target and averaged roughly 20% a year over 2021-2025, but inflation has fallen fast to about 8.5%, so 12% is used as a long-run planning rate between the two.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AO', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No regulator or government source with indicative term life premiums for Angola was found; ARSEG lists life insurance among voluntary insurance types but publishes no premium data.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AO', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The insurance regulator ARSEG publishes market statistics and complaint reports, but no industry-wide life insurance claim settlement ratio was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AO', 1, 'life_expectancy', 65.2, NULL, 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/angola', '2026-07-01', 'Men 62.6, women 67.7 (UN WPP estimate for 2026). World Bank 2024: 64.8 (men 62.3, women 67.3).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AO', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":16.8,"men":15.7,"women":17.9},{"age":65,"total":13.5,"men":12.5,"women":14.4},{"age":70,"total":10.6,"men":9.8,"women":11.2},{"age":80,"total":6,"men":5.6,"women":6.3}]}', 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/angola', '2026-07-01', 'Remaining years from georank''s expected age at death by current age (UN WPP 2026 estimate).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AO', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension eligibility rules were found (INSS and ILO pages could not be read).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AO', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age (social) pension amount was found; the INSS and ministry pages could not be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AO', 1, 'oop_health_share', 0.3255, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=AO', '2023-12-31', '2023 figure (older than 2025; latest available).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AO', 1, 'policy_rate', 0.1475, NULL, 'sourced', 'Trading Economics, Angola interest rate (Banco Nacional de Angola, Taxa BNA)', 'https://tradingeconomics.com/angola/interest-rate', '2026-09-15', 'Secondary source; the BNA site could not be read. The BNA cut its policy rate by 100 basis points to 14.75% on 15 September 2026, its third straight cut; next meeting 17 November 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AO', 1, 'public_pension_scheme', NULL, NULL, 'missing', '', '', '2026-10-31', 'Angola has a contributory social security system run by INSS (PwC Tax Summaries: employees pay 3% and employers 8% of gross pay, https://taxsummaries.pwc.com/angola/individual/other-taxes), but no readable source for its pension age, qualifying period or indexation was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AO', 1, 'retirement_accumulation_return_base', 0.085, NULL, 'assumption', 'Fixed income base 7%; equity base 11% (global index in kwanza)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=AO', '2026-10-31', 'Base case: mostly kwanza deposits and bonds with some global equity, given the very small local stock market.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AO', 1, 'retirement_accumulation_return_high', 0.11, NULL, 'assumption', 'Fixed income high 9%; equity high 15%', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=AO', '2026-10-31', 'High case for a growth-leaning mix if the kwanza depreciates faster.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AO', 1, 'retirement_accumulation_return_low', 0.055, NULL, 'assumption', 'Fixed income low 5%; equity low 6%', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=AO', '2026-10-31', 'Low case for a balanced mix of deposits and foreign equity in kwanza terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AO', 1, 'retirement_age_default', NULL, NULL, 'missing', '', '', '2026-10-31', 'The social security institute (INSS) site could not be read (certificate error), and the ISSA and ILO country profiles returned 403; no readable official source for the old-age pension age was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AO', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'No readable official source for the retirement age of civil servants was found (INSS and public administration pages could not be read).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AO', 1, 'retirement_return_base', 0.065, NULL, 'assumption', 'World Bank average deposit rate 7.98% (2025) less about 10-15% Investment Income Tax = 6.8-7.2%', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=AO', '2026-10-31', 'Base case kept just below the after-tax average deposit rate, the only safe-rate figure that could be sourced.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AO', 1, 'retirement_return_high', 0.08, NULL, 'assumption', 'BNA policy rate 14.75% (Trading Economics); World Bank deposit rate 7.98%', 'https://tradingeconomics.com/angola/interest-rate', '2026-10-31', 'High case: a retiree holds longer term deposits or Treasury bonds at rates above the average deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AO', 1, 'retirement_return_low', 0.045, NULL, 'assumption', 'World Bank average deposit rate 7.98% (2025); BNA policy rate falling (Trading Economics)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=AO', '2026-10-31', 'Low case: deposit rates fall further as the BNA keeps cutting.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AO', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate or retail savings bond for individuals was found; individuals can buy Treasury bills and bonds through banks and the securities exchange.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AO', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical savings account rate was found. Searched the Banco Nacional de Angola site (a script-rendered app that could not be read), the Treasury debt office (UGD) portal and the securities exchange statistics pages, which showed no rendered figures.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AO', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":18.31},{"year":2040,"value":16.39},{"year":2065,"value":12.5}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/angola/2040/', '2025-12-31', '100 / old-age dependency ratio: 5.46 (2025, World Bank), 6.1 (2040) and 8.0 (2065, populationpyramid.net/angola/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AO', 1, 'tax_bank_interest', NULL, NULL, 'missing', '', '', '2026-10-31', 'PwC Worldwide Tax Summaries states that Angola''s Investment Income Tax (Imposto sobre a Aplicação de Capitais) is generally 15%, or 10% for listed income including bond interest, and exempts interest on government-approved savings products up to AOA 500,000; it does not state the rate on bank deposit interest, and the tax authority (AGT) site did not respond.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AO', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'There is no government savings certificate for individuals; PwC Tax Summaries lists bond interest at the 10% Investment Income Tax rate (https://taxsummaries.pwc.com/angola/corporate/taxes-on-corporate-income), but no retail savings-certificate product exists to apply it to.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AO', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No current 91-day Treasury bill (Bilhetes do Tesouro) auction yield could be read. Searched the Banco Nacional de Angola site (a script-rendered app that could not be read), the Treasury debt office (UGD) portal and the securities exchange statistics pages, which showed no rendered figures.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AO', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No current 10-year Treasury bond yield could be read. Searched the Banco Nacional de Angola site (a script-rendered app that could not be read), the Treasury debt office (UGD) portal and the securities exchange statistics pages, which showed no rendered figures.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AO', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No current 5-year Treasury bond (Obrigações do Tesouro) yield could be read. Searched the Banco Nacional de Angola site (a script-rendered app that could not be read), the Treasury debt office (UGD) portal and the securities exchange statistics pages, which showed no rendered figures.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('AR', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"AR","iso3":"ARG","nameEn":"Argentina","nameNative":"Argentina","region":"latin_america_caribbean","languages":["es","en"],"currency":{"code":"ARS","symbol":"$","decimals":2,"compact":"intl","usdRate":{"value":1537.3487,"status":"sourced","sourceName":"BCRA wholesale reference exchange rate (Communication A 3500), series 5","sourceUrl":"https://api.bcra.gob.ar/estadisticas/v4.0/monetarias/5","asOf":"2026-10-30","note":"Pesos per US dollar, official wholesale reference rate; World Bank PA.NUS.FCRF gives a 2025 average of 1,240.85."}},"instruments":{"savings_account":{"available":true,"localName":"Caja de ahorro","localNameEn":"Savings account","sourceUrl":"https://www.bcra.gob.ar/archivos/Pdfs/PublicacionesEstadisticas/diar_pas.xls"},"fdr_3m":{"available":true,"localName":"Plazo fijo","localNameEn":"Fixed-term deposit (60 days or more)","sourceUrl":"https://www.bcra.gob.ar/archivos/Pdfs/PublicacionesEstadisticas/diar_pas.xls"},"fdr_1y":{"available":true,"localName":"Plazo fijo a 365 días","localNameEn":"1-year fixed-term deposit","note":"Offered by banks, but the BCRA publishes no separate 1-year rate.","sourceUrl":"https://www.bcra.gob.ar/archivos/Pdfs/PublicacionesEstadisticas/diar_pas.xls"},"dps":{"available":false,"localName":null,"note":"No standard monthly recurring deposit product found."},"sanchayapatra_5y":{"available":false,"localName":null,"note":"No government savings certificate or retail savings bond sold directly to individuals found."},"tbill_91d":{"available":true,"localName":"Letra del Tesoro Nacional Capitalizable en pesos (LECAP)","localNameEn":"Fixed-rate capitalising Treasury letter","note":"Short fixed-rate Treasury letters sold at fortnightly auctions and traded on the market; recent new issues run about 4 months.","sourceUrl":"https://www.argentina.gob.ar/noticias/resultado-de-la-licitacion-por-efectivo-de-instrumentos-del-tesoro-nacional-denominados-16"},"tbond_5y":{"available":true,"localName":"Bono del Tesoro Nacional en pesos","localNameEn":"Peso Treasury bond (fixed-rate, CER-linked or TAMAR-linked)","note":"Peso bonds trade on the local market; no official 5-year fixed-rate yield found.","sourceUrl":"https://www.argentina.gob.ar/noticias/resultado-de-la-licitacion-por-efectivo-de-instrumentos-del-tesoro-nacional-denominados-16"},"tbond_10y":{"available":false,"localName":null,"note":"No 10-year peso government bond is issued."},"equity_fund":{"available":true,"localName":"Fondo común de inversión de renta variable","localNameEn":"Equity mutual fund","note":"Mutual funds are regulated by the Comisión Nacional de Valores.","sourceUrl":"https://www.argentina.gob.ar/cnv"},"gold":{"available":true,"localName":"Oro","localNameEn":"Gold bars and coins","note":"Physical gold can be bought legally."}},"institutions":{"centralBank":{"name":"Banco Central de la República Argentina (BCRA)","url":"https://www.bcra.gob.ar/"},"insuranceRegulator":{"name":"Superintendencia de Seguros de la Nación (SSN)","url":"https://www.argentina.gob.ar/superintendencia-de-seguros"},"insuranceComplaints":{"name":"Superintendencia de Seguros de la Nación: consultas y denuncias","url":"https://www.argentina.gob.ar/servicio/realizar-una-consulta-o-denuncia-ante-la-superintendencia-de-seguros-de-la-nacion"},"pensionScheme":{"name":"ANSES: Sistema Integrado Previsional Argentino (SIPA)","url":"https://www.argentina.gob.ar/anses"},"oldAgeAllowance":{"name":"Pensión Universal para el Adulto Mayor (PUAM), paid by ANSES","url":"https://www.argentina.gob.ar/justicia/derechofacil/leysimple/pension-universal-para-el-adulto-mayor"},"publicHealthCover":{"name":"Ministerio de Salud (free public hospitals; PAMI for retirees)","url":"https://www.argentina.gob.ar/salud"},"depositInsurance":{"name":"Sistema de Seguro de Garantía de los Depósitos (administered by SEDESA)","url":"https://www.sedesa.com.ar/en/deposit-guarantee-system/"},"statistics":{"name":"Instituto Nacional de Estadística y Censos (INDEC)","url":"https://www.indec.gob.ar/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AR', 1, 'bank_deposit_avg_rate', 0.2313, NULL, 'sourced', 'BCRA daily series of deposit interest rates (table IX-2-1-1, peso time deposits, all terms)', 'https://www.bcra.gob.ar/archivos/Pdfs/PublicacionesEstadisticas/diar_pas.xls', '2026-10-29', 'Weighted average rate on new peso time deposits of all terms 23.13% nominal a year; peso savings accounts averaged 4.55%. World Bank FR.INR.DPST gives 34.9% for 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AR', 1, 'credit_card_rate_cap', 0.7914, NULL, 'sourced', 'BCRA monthly series of lending rates to individuals (credit card system, total)', 'https://www.bcra.gob.ar/archivos/Pdfs/PublicacionesEstadisticas/preser_tas.xls', '2026-09-30', 'Typical (weighted average) annual nominal rate on peso credit card balances of individuals 79.1% in September 2026; personal loans averaged 60.6% (October 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AR', 1, 'deposit_insurance_limit', 50000000, NULL, 'sourced', 'SEDESA (statutory deposit guarantee fund administrator): Deposit Guarantee System', 'https://www.sedesa.com.ar/en/deposit-guarantee-system/', '2026-10-31', 'The deposit guarantee covers up to ARS 50,000,000 per person across accounts and deposits at a participating institution; joint accounts share one limit.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AR', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No monthly recurring deposit product found in the BCRA deposit rate series for Argentina.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AR', 1, 'equity_return_base', 0.23, NULL, 'assumption', 'BCRA: peso time deposits 21-23% (October 2026); LECAP 28.3% effective', 'https://www.argentina.gob.ar/noticias/resultado-de-la-licitacion-por-efectivo-de-instrumentos-del-tesoro-nacional-denominados-16', '2026-10-31', 'Base case only about 1-2 points above untaxed peso deposits, because the local index''s 10-year record in dollar terms is weak and erratic; within 4 points of the safe rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AR', 1, 'equity_return_high', 0.32, NULL, 'assumption', 'BCRA wholesale exchange rate series 5; inflation expectation 21% (REM)', 'https://api.bcra.gob.ar/estadisticas/v4.0/monetarias/5', '2026-10-31', 'High case: 20% inflation plus a strong real equity return of about 10%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AR', 1, 'equity_return_low', 0.15, NULL, 'assumption', 'BCRA: peso deposits 21-23%, LECAP 28% effective; peso depreciation about 58% a year 2016-2026 (BCRA series 5)', 'https://api.bcra.gob.ar/estadisticas/v4.0/monetarias/5', '2026-10-31', 'Low case below deposit rates, reflecting the main index''s very volatile record and periods of large losses in dollar terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AR', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The BCRA publishes deposit rates only up to the bucket ''60 days and more'' (about 21-23% nominal for individuals in October 2026); no 1-year time deposit average found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AR', 1, 'fdr_3m_rate', 0.21, NULL, 'sourced', 'BCRA daily series of deposit interest rates (table IX-2-1-2-4-1, individuals'' peso time deposits of 60 days and more)', 'https://www.bcra.gob.ar/archivos/Pdfs/PublicacionesEstadisticas/diar_pas.xls', '2026-10-29', 'Individuals'' peso time deposits of 60 days or more paid 20.9-21.5% nominal a year (balances up to ARS 1 million); 30-day deposits system-wide 22.39% (BCRA series 12). No separate 90-day series is published.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AR', 1, 'fixed_income_return_base', 0.21, NULL, 'assumption', 'BCRA: individuals'' peso time deposits of 60 days and more about 21%; interest on peso deposits largely untaxed', 'https://www.bcra.gob.ar/archivos/Pdfs/PublicacionesEstadisticas/diar_pas.xls', '2026-10-31', 'Base case at current 60-day-plus deposit rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AR', 1, 'fixed_income_return_high', 0.26, NULL, 'assumption', 'Treasury auction 28 October 2026: LECAP 28.3% effective annual', 'https://www.argentina.gob.ar/noticias/resultado-de-la-licitacion-por-efectivo-de-instrumentos-del-tesoro-nacional-denominados-16', '2026-10-31', 'High case mixing short Treasury letters and deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AR', 1, 'fixed_income_return_low', 0.18, NULL, 'assumption', 'BCRA: individuals'' 30-day peso time deposits about 19.7% nominal', 'https://www.bcra.gob.ar/archivos/Pdfs/PublicacionesEstadisticas/diar_pas.xls', '2026-10-31', 'Low case: rolling short peso deposits if rates keep falling with inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AR', 1, 'goal_inflation_education', 0.22, NULL, 'assumption', 'INDEC CPI via BCRA series 28 (education among the September 2026 leaders)', 'https://api.bcra.gob.ar/estadisticas/v4.0/monetarias/28', '2026-10-31', 'Education led price rises in September 2026, so we plan with the 20% projection plus two points.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AR', 1, 'goal_inflation_health', 0.22, NULL, 'assumption', 'INDEC CPI via BCRA series 28; REM 12-month expectation 21.1%', 'https://api.bcra.gob.ar/estadisticas/v4.0/monetarias/29', '2026-10-31', 'No long health CPI series was read, so we plan with the 20% projection plus two points, as private health plan fees have tended to rise faster than prices.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AR', 1, 'gold_return_base', 0.2, NULL, 'assumption', 'BCRA wholesale exchange rate series 5; REM inflation expectation 21%', 'https://api.bcra.gob.ar/estadisticas/v4.0/monetarias/5', '2026-10-31', 'Dollar gold trend of about 4% plus peso depreciation of about 15% a year, close to the expected inflation gap with the US.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AR', 1, 'gold_return_high', 0.3, NULL, 'assumption', 'BCRA wholesale exchange rate series 5', 'https://api.bcra.gob.ar/estadisticas/v4.0/monetarias/5', '2026-10-31', 'High case: strong dollar gold and a faster peso slide.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AR', 1, 'gold_return_low', 0.12, NULL, 'assumption', 'BCRA wholesale exchange rate (ARS 15.85 per USD end-2016, 1,537 on 30 October 2026)', 'https://api.bcra.gob.ar/estadisticas/v4.0/monetarias/5', '2026-10-31', 'Low case: weak dollar gold and slower peso depreciation than inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AR', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'Argentina has no statutory gratuity on retirement or resignation: Labour Contract Law 20.744 art. 252 lets the employer end the contract once the worker is 70 and qualifies for the pension, without paying the seniority indemnity; the only statutory payment is the art. 245 dismissal indemnity of one month''s best pay per year of service on dismissal without just cause (InfoLEG consolidated text, https://servicios.infoleg.gob.ar/infolegInternet/anexos/25000-29999/25552/texact.htm).', 1);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AR', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a major private hospital stay found for Argentina; public hospitals are free at the point of use.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AR', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Private prepaid health plan prices are set by each company; no regulator table of premiums by age per 100,000 of cover found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AR', 1, 'inflation_cpi', 0.334, NULL, 'sourced', 'INDEC consumer price index (national), as published in BCRA statistics series 28', 'https://api.bcra.gob.ar/estadisticas/v4.0/monetarias/28', '2026-09-30', 'Year-on-year CPI inflation 33.4% in September 2026 (1.9% in the month); 31.5% in December 2025 and 117.8% in December 2024.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AR', 1, 'inflation_projection', 0.2, NULL, 'assumption', 'BCRA market expectations survey (REM): median expected inflation for the next 12 months 21.1% (September 2026)', 'https://api.bcra.gob.ar/estadisticas/v4.0/monetarias/29', '2026-10-31', 'The central bank has no inflation target and the 5-year average is far above 50%, so we plan with 20%, near the market''s 12-month expectation, which assumes disinflation continues; review yearly.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AR', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life cover is sold in Argentina, but no regulator or other non-company source publishing premium rates by age was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AR', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched the Superintendencia de Seguros de la Nación material: no industry-wide life claim settlement ratio published.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AR', 1, 'life_expectancy', 77.543, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=AR', '2024-12-31', 'UN WPP 2024 (via populationpyramid.net) gives 77.8 for 2026 (men 75.3, women 80.3).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AR', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":22.2,"men":20.3,"women":24},{"age":65,"total":18.4,"men":16.6,"women":20},{"age":70,"total":14.7,"men":13.3,"women":16.1},{"age":80,"total":8.6,"men":7.8,"women":9.4}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/argentina/', '2026-12-31', 'Secondary source of UN WPP 2024 medium variant for 2026; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AR', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":65,"womenAge":65,"over90Monthly":null,"meansTested":true}', 'sourced', 'Ministry of Justice, Derecho Fácil: Pensión universal para el adulto mayor (Law 27.260)', 'https://www.argentina.gob.ar/justicia/derechofacil/leysimple/pension-universal-para-el-adulto-mayor', '2026-10-31', 'Non-contributory pension from 65 for citizens (naturalised after 10 years'' residence, foreigners after 20); ANSES runs a socio-economic and asset assessment, and claimants must not receive or be entitled to any other pension. It rises with the minimum pension and includes PAMI health cover.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AR', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Universal Old-Age Pension (PUAM, Law 27.260) exists and pays 80% of the minimum retirement pension (argentina.gob.ar Derecho Fácil), but no official figure for the current minimum pension could be read: ANSES pages returned errors or empty content, and the only October 2026 figure found was a commercial news headline whose article did not state the minimum pension or the PUAM amount.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AR', 1, 'oop_health_share', 0.2447, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=AR', '2023-12-31', 'Latest year available (2023), older than 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AR', 1, 'policy_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The BCRA stopped setting a monetary policy rate in July 2025 (last value 29% nominal on 10 July 2025, BCRA series 160) and now targets monetary aggregates; the overnight repo rate between third parties was 20.7% on 29 October 2026 (series 150).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AR', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":65,"nomineeUntilAge":null,"inflationLinked":true,"taxFree":null}', 'sourced', 'Law 24.241 (Integrated Pension System), articles 19 and 32, consolidated text on InfoLEG', 'https://servicios.infoleg.gob.ar/infolegInternet/anexos/0-4999/639/texact.htm', '2026-10-31', 'Compulsory pay-as-you-go SIPA run by ANSES: pension at 65 for men and 60 for women with 30 years of contributions; benefits are adjusted every month by the INDEC CPI since July 2024 (art. 32 as replaced by Decree 274/2024).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AR', 1, 'retirement_accumulation_return_base', 0.22, NULL, 'assumption', 'Mix of peso deposits (about 21%) and equities (23% base)', 'https://www.bcra.gob.ar/archivos/Pdfs/PublicacionesEstadisticas/diar_pas.xls', '2026-10-31', 'Base case for a roughly half-and-half mix, about 2 points above expected inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AR', 1, 'retirement_accumulation_return_high', 0.28, NULL, 'assumption', 'Mix of Treasury letters (28% effective) and equities (32% high case)', 'https://www.argentina.gob.ar/noticias/resultado-de-la-licitacion-por-efectivo-de-instrumentos-del-tesoro-nacional-denominados-16', '2026-10-31', 'High case with strong equities and high peso yields.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AR', 1, 'retirement_accumulation_return_low', 0.17, NULL, 'assumption', 'Mix of peso deposits (about 21%) and local equities', 'https://www.bcra.gob.ar/archivos/Pdfs/PublicacionesEstadisticas/diar_pas.xls', '2026-10-31', 'Low case for a balanced peso mix in a bad decade.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AR', 1, 'retirement_age_default', 65, NULL, 'sourced', 'Law 24.241 (Integrated Pension System), article 19, consolidated text on InfoLEG', 'https://servicios.infoleg.gob.ar/infolegInternet/anexos/0-4999/639/texact.htm', '2026-10-31', 'Men qualify for the basic universal pension at 65 and women at 60 (women may keep working to 65), with 30 years of contributions.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AR', 1, 'retirement_age_government', 65, NULL, 'sourced', 'Law 24.241 (Integrated Pension System), article 19, consolidated text on InfoLEG', 'https://servicios.infoleg.gob.ar/infolegInternet/anexos/0-4999/639/texact.htm', '2026-10-31', 'National public employees are covered by the same SIPA rules (men 65, women 60); provinces and some professions run their own schemes with different ages.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AR', 1, 'retirement_return_base', 0.2, NULL, 'assumption', 'BCRA: individuals'' peso time deposits of 60 days and more about 21%', 'https://www.bcra.gob.ar/archivos/Pdfs/PublicacionesEstadisticas/diar_pas.xls', '2026-10-31', 'Base case just below the current 60-day-plus deposit rate, untaxed for savings interest.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AR', 1, 'retirement_return_high', 0.24, NULL, 'assumption', 'Treasury auction 28 October 2026: LECAP 28.3% effective annual', 'https://www.argentina.gob.ar/noticias/resultado-de-la-licitacion-por-efectivo-de-instrumentos-del-tesoro-nacional-denominados-16', '2026-10-31', 'High case mixing Treasury letters and deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AR', 1, 'retirement_return_low', 0.17, NULL, 'assumption', 'BCRA: individuals'' 30-day peso deposits about 19.7% nominal', 'https://www.bcra.gob.ar/archivos/Pdfs/PublicacionesEstadisticas/diar_pas.xls', '2026-10-31', 'Low case if peso deposit rates keep falling.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AR', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate or retail savings bond sold directly to individuals found; Treasury securities are sold by auction and traded through brokers.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AR', 1, 'savings_account_rate', 0.034, NULL, 'sourced', 'BCRA daily series of deposit interest rates (table IX-2-1-2-4-1, individuals'' peso savings accounts)', 'https://www.bcra.gob.ar/archivos/Pdfs/PublicacionesEstadisticas/diar_pas.xls', '2026-10-29', 'Individuals'' ordinary peso savings accounts paid 3.4-3.6% nominal a year for balances up to ARS 500,000 (3.1% for ARS 500,000-999,999); the all-depositor average was 4.6%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AR', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":5.3},{"year":2040,"value":4.2},{"year":2065,"value":2.3}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/argentina/2040/', '2025-12-31', '100 / old-age dependency ratio: 19.0 (2025, World Bank), 23.7 (2040) and 43.3 (2065, populationpyramid.net/argentina/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AR', 1, 'tax_bank_interest', 0, NULL, 'sourced', 'PwC Worldwide Tax Summaries: Argentina, individual income determination (last reviewed 16 June 2026)', 'https://taxsummaries.pwc.com/argentina/individual/income-determination', '2026-06-16', 'PwC: interest on savings accounts in Argentine banks is exempt from personal income tax, and the exemption for individuals'' term deposits was extended to foreign-currency deposits from fiscal years starting 1 January 2026; other interest income is taxable at the progressive rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AR', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate for individuals exists; PwC notes capital gains on Argentine government bonds are exempt from income tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AR', 1, 'tbill_91d_rate', 0.2832, NULL, 'sourced', 'Ministry of Economy, Secretariat of Finance: Treasury auction results of 28 October 2026', 'https://www.argentina.gob.ar/noticias/resultado-de-la-licitacion-por-efectivo-de-instrumentos-del-tesoro-nacional-denominados-16', '2026-10-28', 'New fixed-rate capitalising Treasury letter (LECAP) maturing 26 February 2027 (about 4 months) cut at 2.10% a month effective, 28.32% effective annual yield (about 25.2% nominal). No 91-day letter was offered.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AR', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 10-year peso government bond is issued; recent official auctions go out to 2028.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AR', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 5-year fixed-rate peso bond yield found in official auction results; recent long peso issues are CER-linked (real yields about 6%) or TAMAR-linked.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('AT', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"AT","iso3":"AUT","nameEn":"Austria","nameNative":"Österreich","region":"europe_central_asia","languages":["de","en","fr","it","hr"],"currency":{"code":"EUR","symbol":"€","decimals":2,"compact":"intl","usdRate":{"value":0.8951,"status":"sourced","sourceName":"European Central Bank euro reference rate (USD)","sourceUrl":"https://www.ecb.europa.eu/stats/policy_and_exchange_rates/euro_reference_exchange_rates/html/eurofxref-graph-usd.en.html","asOf":"2026-10-30","note":"EUR 1 = USD 1.1172, so about EUR 0.895 per US dollar; World Bank 2025 average 0.885."}},"instruments":{"savings_account":{"available":true,"localName":"Sparkonto","localNameEn":"Savings account","sourceUrl":"https://data-api.ecb.europa.eu/service/data/MIR/M.AT.B.L21.A.R.A.2250.EUR.N"},"fdr_3m":{"available":true,"localName":"Festgeld","localNameEn":"Fixed-term deposit (3 months)","note":"Also sold as a term savings book (Kapitalsparbuch)."},"fdr_1y":{"available":true,"localName":"Festgeld","localNameEn":"Fixed-term deposit (1 year)","sourceUrl":"https://data-api.ecb.europa.eu/service/data/MIR/M.AT.B.L22.F.R.A.2250.EUR.N"},"dps":{"available":true,"localName":"Bausparvertrag","localNameEn":"Building-society savings contract","note":"Regular monthly saving over 6 years with a small state premium; offered by building societies."},"sanchayapatra_5y":{"available":true,"localName":"Bundesschatz","localNameEn":"Federal savings product of the Republic of Austria","note":"Sold online directly by the Austrian Treasury to individuals, fixed terms from 1 month to 10 years; 27.5% KESt withheld.","sourceUrl":"https://www.bundesschatz.at/haeufige-fragen"},"tbill_91d":{"available":true,"localName":"Austrian Treasury Bills","localNameEn":"Austrian Treasury Bills (ATB)","note":"Auctioned by the Austrian Treasury mainly to institutions."},"tbond_5y":{"available":true,"localName":"Bundesanleihe","localNameEn":"Republic of Austria Government Bond"},"tbond_10y":{"available":true,"localName":"Bundesanleihe","localNameEn":"Republic of Austria Government Bond","sourceUrl":"https://data-api.ecb.europa.eu/service/data/IRS/M.AT.L.L40.CI.0000.EUR.N.Z"},"equity_fund":{"available":true,"localName":"Investmentfonds","localNameEn":"Investment fund / index fund (ETF)","note":"Retail mutual and index funds are widely available; gains taxed at 27.5%."},"gold":{"available":true,"localName":"Goldbarren und Goldmünzen","localNameEn":"Gold bars and coins","note":"No restriction on buying physical gold."}},"institutions":{"centralBank":{"name":"Oesterreichische Nationalbank","url":"https://www.oenb.at/","note":"Part of the Eurosystem; monetary policy set by the European Central Bank."},"insuranceRegulator":{"name":"Finanzmarktaufsicht (FMA)","url":"https://www.fma.gv.at/"},"insuranceComplaints":{"name":"Finanzmarktaufsicht (FMA), consumer information and complaints","url":"https://www.fma.gv.at/","note":"The FMA takes complaints about supervised insurers; disputes go to the civil courts."},"pensionScheme":{"name":"Pensionsversicherungsanstalt (statutory pension insurance)","url":"https://www.pv.at/"},"oldAgeAllowance":null,"publicHealthCover":{"name":"Österreichische Gesundheitskasse (statutory health insurance)","url":"https://www.gesundheitskasse.at/"},"depositInsurance":{"name":"Einlagensicherung AUSTRIA","url":"https://www.einlagensicherung.at/en/prot-deposits.php"},"statistics":{"name":"Statistik Austria","url":"https://www.statistik.at/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AT', 1, 'bank_deposit_avg_rate', 0.0155, NULL, 'sourced', 'ECB MFI interest rate statistics: Austrian banks, household deposits with agreed maturity (outstanding amounts)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.AT.B.L22.A.R.A.2250.EUR.O', '2026-09-30', 'Average rate on all outstanding household term deposits, September 2026 (1.52% in August); household overnight deposits paid 0.46%. World Bank FR.INR.DPST has no Austria figure.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AT', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap; the ECB/OeNB series for extended credit card credit to Austrian households is empty and no typical card rate source was reachable (revolving loans and overdrafts averaged 5.92% in August 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AT', 1, 'deposit_insurance_limit', 100000, NULL, 'sourced', 'Einlagensicherung AUSTRIA, deposit protection', 'https://www.einlagensicherung.at/en/prot-deposits.php', '2026-10-31', 'EUR 100,000 per depositor per bank; up to EUR 500,000 in special cases set out in the scheme rules.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AT', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Austria''s monthly-deposit savings contract is the Bausparvertrag (building-society savings with a state premium); no current average rate was found from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AT', 1, 'equity_return_base', 0.055, NULL, 'assumption', 'ATX price index (Trading Economics); 1-year deposit 2.18% less 25% KESt = 1.6%', 'https://tradingeconomics.com/austria/stock-market', '2026-10-31', 'The ATX has done well over 10 years, but the base is capped at the after-tax safe rate plus about 4 points because the index is small and bank- and energy-heavy.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AT', 1, 'equity_return_high', 0.075, NULL, 'assumption', 'ATX price index (Trading Economics); global equity long-run returns', 'https://tradingeconomics.com/austria/stock-market', '2026-10-31', 'High case: a diversified euro equity fund matching long-run global equity returns of about 7-8% in euros.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AT', 1, 'equity_return_low', 0.035, NULL, 'assumption', 'ATX 6,420 on 30 Oct 2026, up 33.5% in a year; after-tax 1-year deposit 1.6%', 'https://tradingeconomics.com/austria/stock-market', '2026-10-31', 'Low case: Austrian shares deliver little more than safe deposits over a long period, as in the 2007-2016 decade.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AT', 1, 'fdr_1y_rate', 0.0218, NULL, 'sourced', 'ECB MFI interest rate statistics: Austrian banks, household deposits with agreed maturity up to 1 year (new business)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.AT.B.L22.F.R.A.2250.EUR.N', '2026-09-30', 'September 2026 new business (2.15% in August); the bucket covers all fixed terms up to one year.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AT', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'ECB/OeNB MFI statistics only publish deposits with agreed maturity up to 1 year as one bucket (2.15% in August 2026); no 3-month term deposit rate found; OeNB tables and comparison sites were not reachable.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AT', 1, 'fixed_income_return_base', 0.016, NULL, 'assumption', 'Household deposits up to 1 year 2.18% (Sep 2026) less 25% KESt = 1.6%', 'https://data-api.ecb.europa.eu/service/data/MIR/M.AT.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Base case: after-tax 1-year term deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AT', 1, 'fixed_income_return_high', 0.026, NULL, 'assumption', 'Austria 10-year government bond 3.69% (ECB, Sep 2026) less 27.5% KESt = 2.7%', 'https://data-api.ecb.europa.eu/service/data/IRS/M.AT.L.L40.CI.0000.EUR.N.Z', '2026-10-31', 'High case: holding long government bonds or long Bundesschatz terms after tax, a little below the current after-tax 10-year yield.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AT', 1, 'fixed_income_return_low', 0.012, NULL, 'assumption', 'Household notice deposits 2.05% (Sep 2026) less 25% KESt = 1.5% (ECB MFI statistics)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.AT.B.L23.D.R.A.2250.EUR.N', '2026-10-31', 'Low case: easy-access savings after tax (about 1.5%), with rates drifting lower over time.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AT', 1, 'goal_inflation_education', 0.04, NULL, 'assumption', 'Eurostat/ECB HICP Austria, education: 5.2% year on year in December 2025', 'https://data-api.ecb.europa.eu/service/data/ICP/M.AT.N.100000.4.ANR', '2026-10-31', 'Education prices (mainly private schooling and courses; public education is free) have risen faster than headline inflation; 4% is used for planning.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AT', 1, 'goal_inflation_health', 0.04, NULL, 'assumption', 'Eurostat/ECB HICP Austria, health: 5.3% year on year in December 2025', 'https://data-api.ecb.europa.eu/service/data/ICP/M.AT.N.060000.4.ANR', '2026-10-31', 'Health prices have run above headline inflation; 4% is used as a long-run planning figure.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AT', 1, 'gold_return_base', 0.04, NULL, 'assumption', 'Gold price history (Trading Economics); ECB 2% inflation target', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Base case: dollar gold rises roughly with world inflation plus a little, and the euro is assumed stable against the dollar over the long run.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AT', 1, 'gold_return_high', 0.07, NULL, 'assumption', 'Gold price history (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'High case: a repeat of gold''s strong 2005-2025 trend in euro terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AT', 1, 'gold_return_low', 0.01, NULL, 'assumption', 'Gold USD 3,876/oz on 30 Oct 2026, 31% below the January 2026 high', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Low case: gold barely keeps up after the 2025-26 spike, with no help from the euro.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AT', 1, 'gratuity_rule', NULL, '{"daysPerYear":6.4,"daysPerYearAfter":null,"afterYears":null,"daysPerMonth":30}', 'sourced', 'PwC Worldwide Tax Summaries, Austria other taxes (employee provision fund 1.53%)', 'https://taxsummaries.pwc.com/austria/corporate/other-taxes', '2026-07-23', 'Severance pay (Abfertigung neu): employers pay 1.53% of monthly gross pay, including the 13th and 14th salaries, into an employee provision fund (PwC calls it the mandatory employee pension fund); 1.53% x 14 monthly salaries = about 6.4 days of pay per year of service, plus fund returns, paid out on termination after 3 contribution years.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AT', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'Public hospital care is covered by statutory health insurance with a small daily patient contribution; no official figure for a typical out-of-pocket cost of a major private or mid-range hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AT', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Private supplementary hospital insurance (Sonderklasse) is sold, but no published premium table per EUR 100,000 of cover was found; premiums are not quoted per sum insured.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AT', 1, 'inflation_cpi', 0.036, NULL, 'sourced', 'Trading Economics (Statistik Austria CPI, September 2026 final)', 'https://tradingeconomics.com/austria/inflation-cpi', '2026-09-30', 'CPI 3.6% year on year in September 2026 (3.2% in August), final figure published 16 October 2026; secondary source because statistik.at was not read directly. World Bank 2025 average 3.5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AT', 1, 'inflation_projection', 0.025, NULL, 'assumption', 'ECB 2% medium-term target; Austrian CPI 3.6% (Sep 2026), 3.5% in 2025 (World Bank)', 'https://tradingeconomics.com/austria/inflation-cpi', '2026-10-31', 'The ECB 2% target is credible over the long run but Austrian inflation has run well above the euro-area average for several years, so 2.5% is used for planning.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AT', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life (Risikolebensversicherung) is widely sold, but comparison sites refused automated access and no published premium table was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AT', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The FMA and the Austrian insurance association do not publish an industry life claim settlement ratio that could be found; fma.gv.at refused automated access.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AT', 1, 'life_expectancy', 82.5, NULL, 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/austria', '2026-07-01', 'Men 80.2, women 84.7 (UN WPP estimate for 2026, mid-year date used); World Bank 2024 figure 82.0.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AT', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":24.7,"men":22.9,"women":26.4},{"age":65,"total":20.5,"men":18.9,"women":22},{"age":70,"total":16.6,"men":15.3,"women":17.8},{"age":80,"total":9.4,"men":8.6,"women":10}]}', 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/austria', '2026-07-01', 'Remaining years computed from georank''s expected age at death by current age (UN WPP 2026 estimate).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AT', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension exists; the Ausgleichszulage requires drawing a statutory pension, lawful residence and income below the reference rate (Pensionsversicherungsanstalt, https://www.pv.at/web/pension/in-der-pension/ausgleichszulage-ausgleichszulagenbonus-und-pensionsbonus).', 1);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AT', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'Austria has no non-contributory old-age (social) pension: the Ausgleichszulage is only paid to people who already draw a statutory pension and tops their total income up to a reference rate (EUR 1,308.39 a month for a single person in 2026), which is a means-test threshold, not an amount a person without a pension could receive (Pensionsversicherungsanstalt, https://www.pv.at/web/pension/in-der-pension/ausgleichszulage-ausgleichszulagenbonus-und-pensionsbonus). Social assistance (Sozialhilfe) is general, not an old-age pension.', 1);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AT', 1, 'oop_health_share', 0.1646, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=AT', '2024-12-31', '2024 is the latest year in the World Bank series (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AT', 1, 'policy_rate', 0.025, NULL, 'sourced', 'European Central Bank, key ECB interest rates (deposit facility)', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.en.html', '2026-09-16', 'Austria uses the euro; ECB deposit facility rate 2.50% (main refinancing 2.65%) since 16 September 2026, held on 29 October 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AT', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":65,"nomineeUntilAge":null,"inflationLinked":true,"taxFree":false}', 'sourced', 'Pensionsversicherungsanstalt (Alterspension; Pensionsanpassung)', 'https://www.pv.at/web/pension/in-der-pension/pensionsanpassung-und-pensionserhoehung', '2026-10-31', 'Compulsory statutory pension insurance (employee 10.25%, employer 12.55% of gross pay, PwC); pensions are adjusted every 1 January by consumer-price inflation from August to July (2.95% for 2027 up to EUR 6,930 a month, Pensionsversicherungsanstalt) and taxed as income.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AT', 1, 'retirement_accumulation_return_base', 0.035, NULL, 'assumption', 'After-tax 1-year deposit 1.6%; equity base 5.5%', 'https://data-api.ecb.europa.eu/service/data/MIR/M.AT.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Base case: roughly half shares at 5.5% and half safe fixed income at about 1.6-2.6% after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AT', 1, 'retirement_accumulation_return_high', 0.05, NULL, 'assumption', 'After-tax 10-year bond 2.7% (ECB, Sep 2026); equity high 7.5%', 'https://data-api.ecb.europa.eu/service/data/IRS/M.AT.L.L40.CI.0000.EUR.N.Z', '2026-10-31', 'High case for a growth-leaning balanced mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AT', 1, 'retirement_accumulation_return_low', 0.025, NULL, 'assumption', 'After-tax 1-year deposit 1.6%; ATX record (Trading Economics)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.AT.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Low case for a balanced mix if shares lag.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AT', 1, 'retirement_age_default', 65, NULL, 'sourced', 'Pensionsversicherungsanstalt, Alterspension', 'https://www.pv.at/web/pension/pensionsarten/alterspension', '2026-10-31', 'Regular pension age 65 for anyone born after 1975 (men and women); the women''s age is rising by half a year every 6 months from 2024 and reaches 65 for women born from 1 July 1968. Minimum 15 insurance years.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AT', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'Federal civil servants retire under the Civil Service Act (BDG 1979 s.13(1), which sets retirement at the end of the month of the 65th birthday in the statute text read), but the official RIS legal database was unavailable (HTTP 503) so no official page could be cited.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AT', 1, 'retirement_return_base', 0.016, NULL, 'assumption', 'Household deposits up to 1 year 2.18% (Sep 2026) less 25% KESt = 1.6%', 'https://data-api.ecb.europa.eu/service/data/MIR/M.AT.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Base case capped at the after-tax 1-year term deposit rate (1.64%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AT', 1, 'retirement_return_high', 0.024, NULL, 'assumption', 'Austria 10-year government bond 3.69% (ECB, Sep 2026) less 27.5% KESt = 2.7%', 'https://data-api.ecb.europa.eu/service/data/IRS/M.AT.L.L40.CI.0000.EUR.N.Z', '2026-10-31', 'High case: a ladder of longer government bonds and Bundesschatz terms after tax, slightly below the 10-year yield.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AT', 1, 'retirement_return_low', 0.012, NULL, 'assumption', 'Household notice deposits 2.05% (Sep 2026) less 25% KESt = 1.5%', 'https://data-api.ecb.europa.eu/service/data/MIR/M.AT.B.L23.D.R.A.2250.EUR.N', '2026-10-31', 'Low case: easy-access savings after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AT', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Bundesschatz (retail federal savings product sold online by the Austrian Treasury, terms 1 month to 10 years) exists, but bundesschatz.at loads its rates by script and no figure could be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AT', 1, 'savings_account_rate', 0.0046, NULL, 'sourced', 'ECB MFI interest rate statistics: Austrian banks, overnight deposits from households (new business)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.AT.B.L21.A.R.A.2250.EUR.N', '2026-09-30', 'Average rate on household overnight deposits in Austria, September 2026 (0.45% in August); notice deposits up to 3 months (typical online savings accounts) paid 2.05%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AT', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":3.07},{"year":2040,"value":2.07},{"year":2065,"value":1.7}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/austria/2040/', '2025-12-31', '100 / old-age dependency ratio: 32.6 (2025, World Bank), 48.3 (2040) and 58.9 (2065, populationpyramid.net/austria/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AT', 1, 'tax_bank_interest', 0.25, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Austria income determination', 'https://taxsummaries.pwc.com/austria/individual/income-determination', '2026-07-23', 'Final withholding tax (KESt) of 25% on bank deposit interest; 27.5% on publicly placed bonds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AT', 1, 'tax_sanchayapatra_profit', 0.275, NULL, 'sourced', 'Bundesschatz (Austrian Treasury / Republic of Austria), frequently asked questions', 'https://www.bundesschatz.at/haeufige-fragen', '2026-10-31', '27.5% KESt under s.27a EStG is withheld automatically on Bundesschatz interest for Austrian residents, because Bundesschatz claims count as securities; savings-account interest is taxed at 25%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AT', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Austrian Treasury Bills are auctioned by OeBFA (latest auction 27 October 2026) but the result pages read did not show yields.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AT', 1, 'tbond_10y_rate', 0.0369, NULL, 'sourced', 'European Central Bank, long-term interest rate for convergence purposes (10-year government bond yield), Austria', 'https://data-api.ecb.europa.eu/service/data/IRS/M.AT.L.L40.CI.0000.EUR.N.Z', '2026-09-30', 'Monthly average 3.69% in September 2026 (3.41% in August); official ECB series used instead of a market quote. Market yield was about 3.6% in late October 2026 (Trading Economics).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AT', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 5-year Austrian government bond yield found: Trading Economics and worldgovernmentbonds.com pages read showed no 5-year figure and OeNB publishes only a weighted average (3.59% at 13.98 years residual maturity, 23 Oct 2026).', 0);
