":{"available":true,"localName":null,"localNameEn":"Gold bullion"}},"institutions":{"centralBank":{"name":"Reserve Bank of Australia","url":"https://www.rba.gov.au/"},"insuranceRegulator":{"name":"Australian Prudential Regulation Authority","url":"https://www.apra.gov.au/"},"insuranceComplaints":{"name":"Australian Financial Complaints Authority","url":"https://www.afca.org.au/"},"pensionScheme":{"name":"Superannuation (Australian Taxation Office)","url":"https://www.ato.gov.au/individuals-and-families/super-for-individuals-and-families"},"oldAgeAllowance":{"name":"Age Pension (Services Australia)","url":"https://www.servicesaustralia.gov.au/age-pension"},"publicHealthCover":{"name":"Medicare","url":"https://www.servicesaustralia.gov.au/medicare"},"depositInsurance":{"name":"Financial Claims Scheme","url":"https://www.apra.gov.au/financial-claims-scheme"},"statistics":{"name":"Australian Bureau of Statistics","url":"https://www.abs.gov.au/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
