INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AU', 1, 'retirement_age_default', 67, NULL, 'sourced', 'Wikipedia, Age Pension (Australia) and Retirement age', 'https://en.wikipedia.org/wiki/Age_Pension_(Australia)', '2023-07-01', 'Age Pension age 67 from 1 July 2023 for men and women, so it applies to anyone born after 1975; source page dated 2023 (older than 2025) but the age is unchanged; super can be accessed from preservation age 60', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AU', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'Australian public servants have no compulsory retirement age; no single figure to report.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AU', 1, 'retirement_return_base', 0.034, NULL, 'assumption', '1-year term deposit 5.0% less 32% tax', 'https://www.rba.gov.au/statistics/tables/xls/f04hist.xlsx', '2026-10-31', 'Kept at the after-tax 1-year term deposit rate; super in pension phase is tax-free, so many retirees may do better.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AU', 1, 'retirement_return_high', 0.045, NULL, 'assumption', 'Term deposits and bonds held in a tax-free super pension account', 'https://en.wikipedia.org/wiki/Superannuation_in_Australia', '2026-10-31', 'High case for a retiree paying no tax on earnings.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AU', 1, 'retirement_return_low', 0.025, NULL, 'assumption', 'Online savings after tax', 'https://www.rba.gov.au/statistics/tables/xls/f04hist.xlsx', '2026-10-31', 'Low case: cash only.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AU', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Australia has no government savings certificate for individuals; exchange-traded Treasury Bonds trade at market yields (see tbond rates).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AU', 1, 'savings_account_rate', 0.031, NULL, 'sourced', 'Reserve Bank of Australia, Statistical Table F4 Retail Deposit and Investment Rates', 'https://www.rba.gov.au/statistics/tables/xls/f04hist.xlsx', '2026-09-30', 'Online savings accounts ($10,000); bonus saver accounts 4.80% if conditions met; transaction accounts 0%', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AU', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":3.6},{"year":2040,"value":2.8},{"year":2065,"value":2.3}]}', 'sourced', 'UN World Population Prospects 2024 old-age dependency ratio (via Our World in Data)', 'https://ourworldindata.org/grapher/age-dependency-ratio-old?country=~AUS', '2025-07-01', '100 / old-age dependency ratio (28.1 in 2025, 36.0 in 2040, 44.0 in 2065, medium variant)', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AU', 1, 'tax_bank_interest', 0.32, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Australia, Taxes on personal income', 'https://taxsummaries.pwc.com/australia/individual/taxes-on-personal-income', '2026-10-12', 'No final withholding for residents who quote a tax file number; interest is taxed at marginal rates. 30% band (A$45,001-135,000) plus 2% Medicare levy for a middle earner', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AU', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate exists; Treasury Bond interest is taxed at marginal rates like bank interest.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AU', 1, 'tbill_91d_rate', 0.0492, NULL, 'sourced', 'Reserve Bank of Australia, Statistical Table F1 (3-month bank accepted bills/NCDs)', 'https://www.rba.gov.au/statistics/tables/xls/f01d.xlsx', '2026-10-29', '3-month bank accepted bill rate (4.918% on 29 October 2026) used as the bill benchmark; RBA stopped publishing 3-month Treasury Note yields in 2013 and Treasury Notes are issued to institutions only', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AU', 1, 'tbond_10y_rate', 0.0521, NULL, 'sourced', 'Reserve Bank of Australia, Statistical Table F2 Capital Market Yields', 'https://www.rba.gov.au/statistics/tables/xls/f02d.xlsx', '2026-10-28', 'Australian Government 10-year bond, 5.208% on 28 October 2026', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AU', 1, 'tbond_5y_rate', 0.0495, NULL, 'sourced', 'Reserve Bank of Australia, Statistical Table F2 Capital Market Yields', 'https://www.rba.gov.au/statistics/tables/xls/f02d.xlsx', '2026-10-28', 'Australian Government 5-year bond, 4.946% on 28 October 2026', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('AZ', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"AZ","iso3":"AZE","nameEn":"Azerbaijan","nameNative":"Azərbaycan","region":"europe_central_asia","languages":["az","ru"],"currency":{"code":"AZN","symbol":"₼","decimals":2,"compact":"intl","usdRate":{"value":1.7,"status":"sourced","sourceName":"Trading Economics, USD/AZN (central bank official rate)","sourceUrl":"https://tradingeconomics.com/azerbaijan/currency","asOf":"2026-10-30","note":"The manat has been held at 1.70 per US dollar since 2017; World Bank 2025 average 1.70."}},"instruments":{"savings_account":{"available":true,"localName":"Tələbli əmanət","localNameEn":"Demand (savings) deposit"},"fdr_3m":{"available":true,"localName":"Müddətli əmanət","localNameEn":"Term deposit (3 months)"},"fdr_1y":{"available":true,"localName":"Müddətli əmanət","localNameEn":"Term deposit (1 year)","sourceUrl":"https://api.imf.org/external/sdmx/2.1/data/IMF.STA,MFS_IR/AZE..M"},"dps":{"available":false,"localName":null,"note":"No standard monthly recurring deposit scheme was found; some term deposits allow top-ups."},"sanchayapatra_5y":{"available":false,"localName":null,"note":"No government savings certificate or retail savings bond for individuals."},"tbill_91d":{"available":true,"localName":"Qısamüddətli dövlət istiqrazları","localNameEn":"Short-term government bonds (Ministry of Finance)","note":"Auctioned on the Baku Stock Exchange, mainly to banks."},"tbond_5y":{"available":true,"localName":"Dövlət istiqrazları","localNameEn":"Government bonds (Ministry of Finance)","note":"Issued in manat and US dollars, mostly bought by institutions."},"tbond_10y":{"available":false,"localName":null,"note":"No regular 10-year manat government bond found."},"equity_fund":{"available":false,"localName":null,"localNameEn":"Investment fund","note":"The local stock market is very small and no widely available diversified retail fund was found; residents can buy foreign index funds through brokers."},"gold":{"available":true,"localName":"Qızıl külçə","localNameEn":"Gold bars","note":"Physical gold bars and coins can be bought legally."}},"institutions":{"centralBank":{"name":"Central Bank of the Republic of Azerbaijan","url":"https://www.cbar.az/"},"insuranceRegulator":{"name":"Central Bank of the Republic of Azerbaijan (insurance supervision)","url":"https://www.cbar.az/","note":"The central bank supervises insurers since 2020."},"insuranceComplaints":{"name":"Central Bank of the Republic of Azerbaijan, consumer complaints","url":"https://www.cbar.az/"},"pensionScheme":{"name":"State Social Protection Fund","url":"https://dsmf.gov.az/"},"oldAgeAllowance":{"name":"Social benefit for age (Ministry of Labour and Social Protection of Population)","url":"https://sosial.gov.az/en/services/key-activities/pensions-and-social-insurance-based-benefits/pension/old-age-labor-pension"},"publicHealthCover":{"name":"State Agency on Mandatory Health Insurance","url":"https://its.gov.az/"},"depositInsurance":{"name":"Azerbaijan Deposit Insurance Fund","url":"https://adif.az/"},"statistics":{"name":"State Statistical Committee of the Republic of Azerbaijan","url":"https://www.stat.gov.az/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AZ', 1, 'bank_deposit_avg_rate', 0.0858, NULL, 'sourced', 'IMF International Financial Statistics (MFS_IR), Azerbaijan deposit rate, national currency', 'https://api.imf.org/external/sdmx/2.1/data/IMF.STA,MFS_IR/AZE..M', '2026-08-31', 'Average rate on manat deposits, August 2026 (9.33% in January 2026); foreign-currency deposits 2.86%. World Bank 2025 annual value 9.36%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AZ', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap or published typical credit card rate found; the average lending rate in manats was 15.9% in August 2026 (IMF IFS).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AZ', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Azerbaijan Deposit Insurance Fund (adif.az) and cbar.az refused connections and no other source read stated the current cover per depositor.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AZ', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No data on monthly recurring deposit products found; cbar.az unreachable.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AZ', 1, 'equity_return_base', 0.08, NULL, 'assumption', 'Global equity long-run return in USD; after-tax average manat deposit 8.58% x 0.9 = 7.7%', 'https://api.imf.org/external/sdmx/2.1/data/IMF.STA,MFS_IR/AZE..M', '2026-10-31', 'Base on a global index in manat terms (about 7% in dollars plus about 1% expected manat depreciation), kept close to the after-tax deposit rate because manat deposits already pay well.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AZ', 1, 'equity_return_high', 0.1, NULL, 'assumption', 'Global equity long-run return in USD plus manat depreciation risk', 'https://api.imf.org/external/sdmx/2.1/data/IMF.STA,MFS_IR/AZE..M', '2026-10-31', 'High case: strong world shares plus some manat weakening, as in 2015-2016.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AZ', 1, 'equity_return_low', 0.05, NULL, 'assumption', 'Global equity index in US dollar terms; manat pegged at 1.70 per USD (Trading Economics)', 'https://tradingeconomics.com/azerbaijan/currency', '2026-10-31', 'Azerbaijan has no liquid local stock market, so equity is a global index fund in manat terms; low case is a weak decade for world shares.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AZ', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 1-year term deposit rate found: the central bank''s statistical bulletin (cbar.az) was unreachable; the average rate on manat deposits was 8.58% in August 2026 (IMF IFS).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AZ', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 3-month term deposit rate found: the central bank''s statistical bulletin (cbar.az) was unreachable.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AZ', 1, 'fixed_income_return_base', 0.077, NULL, 'assumption', 'Average manat deposit rate 8.58% less 10% withholding = 7.7%', 'https://api.imf.org/external/sdmx/2.1/data/IMF.STA,MFS_IR/AZE..M', '2026-10-31', 'Base case: the after-tax average deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AZ', 1, 'fixed_income_return_high', 0.085, NULL, 'assumption', 'Average manat deposit rate 8.58% (IMF IFS), tax-exempt case', 'https://api.imf.org/external/sdmx/2.1/data/IMF.STA,MFS_IR/AZE..M', '2026-10-31', 'High case: longer manat deposits at or above the average, with interest exempt from tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AZ', 1, 'fixed_income_return_low', 0.06, NULL, 'assumption', 'Average manat deposit rate 8.58% (Aug 2026), falling about 0.75 points in 2026', 'https://api.imf.org/external/sdmx/2.1/data/IMF.STA,MFS_IR/AZE..M', '2026-10-31', 'Low case: deposit rates keep falling with the policy rate and 10% tax applies.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AZ', 1, 'goal_inflation_education', 0.07, NULL, 'assumption', 'AzStat price index of paid services: +6.5% in 2025; September 2026 release notes higher-education and course fee rises', 'https://www.stat.gov.az/news/index.php?lang=en&id=6974', '2026-10-31', 'No separate education CPI was found; tuition fees rose again in September 2026, so 7% is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AZ', 1, 'goal_inflation_health', 0.07, NULL, 'assumption', 'AzStat price index of paid services: +6.5% in 2025, +8.2% in 2023', 'https://www.stat.gov.az/source/price_tarif/en/001_1en.xlsx', '2026-10-31', 'No separate medical CPI was found; paid services have risen faster than headline CPI, so 7% is used for health costs.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AZ', 1, 'gold_return_base', 0.05, NULL, 'assumption', 'Gold price history (Trading Economics); manat pegged at 1.70 since 2017', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Base case: dollar gold rises with world inflation plus a little, plus about 1% a year expected manat depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AZ', 1, 'gold_return_high', 0.08, NULL, 'assumption', 'Gold price history (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'High case: gold''s strong 2005-2025 trend continues or the manat is devalued again.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AZ', 1, 'gold_return_low', 0.01, NULL, 'assumption', 'Gold USD 3,876/oz on 30 Oct 2026, 31% below the January 2026 high; manat pegged', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Low case: gold flat in dollars after its 2025-26 spike with a stable manat.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AZ', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Labour Code provides severance pay on dismissal by the employer but no statutory gratuity on retirement or resignation was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AZ', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a major private hospital stay found; mandatory health insurance covers a basic package in public facilities.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AZ', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premium table found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AZ', 1, 'inflation_cpi', 0.055, NULL, 'sourced', 'State Statistical Committee of Azerbaijan, Changes in consumer prices (September 2026)', 'https://www.stat.gov.az/news/index.php?lang=en&id=6974', '2026-09-30', 'Consumer prices up 5.5% on September 2025 (food 6.9%, non-food 3.6%, services 5.1%); January-September average 5.7%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AZ', 1, 'inflation_projection', 0.055, NULL, 'assumption', 'CBAR target 4% +/- 2 points; CPI 2021-2025: 6.7%, 13.9%, 8.8%, 2.2%, 5.6% (AzStat)', 'https://www.stat.gov.az/source/price_tarif/en/001_1en.xlsx', '2026-10-31', 'The 5-year average is about 7.4% but inflation has been inside the central bank''s 2-6% band since 2024, so 5.5% (upper half of the band) is used for planning.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AZ', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Life insurance is a small market in Azerbaijan; no published term-life premium quotes were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AZ', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The central bank (insurance supervisor since 2020) site was unreachable; no industry life claim settlement ratio found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AZ', 1, 'life_expectancy', 77.1, NULL, 'sourced', 'State Statistical Committee of Azerbaijan, life expectancy at birth', 'https://www.stat.gov.az/source/demoqraphy/en/002_4en.xls', '2025-12-31', 'Men 74.9, women 79.3 in 2025 (national figure); UN WPP estimates 74.9 for 2026 and the World Bank 74.6 for 2024.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AZ', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":19.6,"men":17.8,"women":21.1},{"age":65,"total":15.8,"men":14.3,"women":17},{"age":70,"total":12.3,"men":11.1,"women":13.2},{"age":80,"total":6.8,"men":6.2,"women":7.2}]}', 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/azerbaijan', '2026-07-01', 'Remaining years computed from georank''s expected age at death by current age (UN WPP 2026 estimate, mid-year date used); national tables give longer lives.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AZ', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":65,"womenAge":65,"over90Monthly":null,"meansTested":false}', 'sourced', 'Ministry of Labour and Social Protection of Population, Old-age Labor Pension', 'https://sosial.gov.az/en/services/key-activities/pensions-and-social-insurance-based-benefits/pension/old-age-labor-pension', '2026-07-01', 'Paid from the retirement age (65 for men and, from 1 July 2026, women) to people with no right to a labour pension who are not working and are incapable of working; not income-tested as such. Benefit amount last stated for 1 January 2023 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AZ', 1, 'old_age_allowance_monthly', 220, NULL, 'sourced', 'Ministry of Labour and Social Protection of Population, Old-age Labor Pension (social benefit for age)', 'https://sosial.gov.az/en/services/key-activities/pensions-and-social-insurance-based-benefits/pension/old-age-labor-pension', '2023-01-01', 'Social benefit for age (non-contributory, for people at retirement age with no labour pension who are not working): 220 manats a month as of 1 January 2023, the latest amount the ministry states. Flag: figure older than 2025 and may since have been raised. Minimum labour pension is 320 manats.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AZ', 1, 'oop_health_share', 0.6463, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=AZ', '2023-12-31', '2023 is the latest year in the World Bank series (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AZ', 1, 'policy_rate', 0.065, NULL, 'sourced', 'Trading Economics (Central Bank of Azerbaijan discount rate decision)', 'https://tradingeconomics.com/azerbaijan/interest-rate', '2026-09-23', 'Discount (refinancing) rate held at 6.5% on 23 September 2026; corridor 5-7.5%. Secondary source because cbar.az refused connections; IMF IFS also shows 6.5% for August 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AZ', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":65,"nomineeUntilAge":null,"inflationLinked":true,"taxFree":null}', 'sourced', 'Ministry of Labour and Social Protection of Population, Labour pensions', 'https://sosial.gov.az/en/services/key-activities/pensions-and-social-insurance-based-benefits/pension/old-age-labor-pension', '2026-07-01', 'Compulsory labour pension: pension = insurance capital / expected payment months, minimum 320 manats, payable from 65 (sosial.gov.az). Pensions are raised each January (average assigned pension up 10.5% to 594.4 manats by July 2026, AzStat), above recent CPI, but the legal indexation basis and the tax treatment were not confirmed from a source read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AZ', 1, 'retirement_accumulation_return_base', 0.075, NULL, 'assumption', 'After-tax deposit 7.7%; global equity base 8%', 'https://api.imf.org/external/sdmx/2.1/data/IMF.STA,MFS_IR/AZE..M', '2026-10-31', 'Base case: roughly half manat deposits and half global shares in manat terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AZ', 1, 'retirement_accumulation_return_high', 0.09, NULL, 'assumption', 'After-tax deposit 8.5%; global equity high 10%', 'https://api.imf.org/external/sdmx/2.1/data/IMF.STA,MFS_IR/AZE..M', '2026-10-31', 'High case for a growth-leaning mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AZ', 1, 'retirement_accumulation_return_low', 0.06, NULL, 'assumption', 'After-tax deposit 7.7%; global equity low case 5%', 'https://api.imf.org/external/sdmx/2.1/data/IMF.STA,MFS_IR/AZE..M', '2026-10-31', 'Low case for a balanced mix of manat deposits and a global equity fund.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AZ', 1, 'retirement_age_default', 65, NULL, 'sourced', 'Ministry of Labour and Social Protection of Population, Old-age Labor Pension', 'https://sosial.gov.az/en/services/key-activities/pensions-and-social-insurance-based-benefits/pension/old-age-labor-pension', '2026-07-01', 'Retirement age 65 for men (since July 2021) and for women from 1 July 2026; 25 insurance years needed unless pension capital covers the minimum pension.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AZ', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'No source read states a separate retirement or age limit for civil servants.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AZ', 1, 'retirement_return_base', 0.075, NULL, 'assumption', 'Average manat deposit rate 8.58% less 10% withholding = 7.7%', 'https://api.imf.org/external/sdmx/2.1/data/IMF.STA,MFS_IR/AZE..M', '2026-10-31', 'Base case kept just under the after-tax average deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AZ', 1, 'retirement_return_high', 0.085, NULL, 'assumption', 'Average manat deposit rate 8.58% (IMF IFS)', 'https://api.imf.org/external/sdmx/2.1/data/IMF.STA,MFS_IR/AZE..M', '2026-10-31', 'High case: longer manat deposits with interest exempt from tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AZ', 1, 'retirement_return_low', 0.06, NULL, 'assumption', 'Average manat deposit rate 8.58% (IMF IFS), falling', 'https://api.imf.org/external/sdmx/2.1/data/IMF.STA,MFS_IR/AZE..M', '2026-10-31', 'Low case: deposit rates fall further and 10% tax applies.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AZ', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate or retail savings bond for individuals was found; Ministry of Finance bonds are sold through the Baku Stock Exchange mainly to institutions.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AZ', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'cbar.az (deposit rate statistics) refused connections and no bank-level demand deposit rate was found; IMF only publishes the overall average deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AZ', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":7.59},{"year":2040,"value":4.52},{"year":2065,"value":2.67}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/azerbaijan/2040/', '2025-12-31', '100 / old-age dependency ratio: 13.2 (2025, World Bank), 22.1 (2040) and 37.5 (2065, populationpyramid.net/azerbaijan/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AZ', 1, 'tax_bank_interest', 0.1, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Azerbaijan income determination', 'https://taxsummaries.pwc.com/azerbaijan/individual/income-determination', '2026-09-28', '10% final withholding tax on Azeri-source interest (PwC, last reviewed 28 Sep 2026). PwC also describes a seven-year exemption for individuals'' bank deposit interest from 1 February 2016, which on its own terms ended in 2023; whether a later extension applies to manat deposits could not be confirmed from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AZ', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No retail government savings certificate exists; PwC does not describe the tax treatment of government bond interest.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AZ', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'IMF''s treasury bill series for Azerbaijan ends in 2017 and the Baku Stock Exchange / central bank pages were not reachable.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AZ', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 10-year government bond yield found; Azerbaijan issues few long manat bonds and no market yield is published on the sources read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('AZ', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 5-year government bond yield found; Trading Economics has no Azerbaijan bond yield and bfb.az/cbar.az were not reachable.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('BA', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"BA","iso3":"BIH","nameEn":"Bosnia and Herzegovina","nameNative":"Bosna i Hercegovina","region":"europe_central_asia","languages":["bs","hr","sr","en"],"currency":{"code":"BAM","symbol":"KM","decimals":2,"compact":"intl","usdRate":{"value":1.750653,"status":"sourced","sourceName":"Central Bank of Bosnia and Herzegovina, exchange rate list no. 215","sourceUrl":"https://www.cbbh.ba/CurrencyExchange/?lang=en","asOf":"2026-10-31","note":"Middle rate; the convertible mark is fixed at KM 1.95583 per euro under the currency board."}},"instruments":{"savings_account":{"available":true,"localName":"Štedni račun","localNameEn":"Savings account"},"fdr_3m":{"available":true,"localName":"Oročeni depozit","localNameEn":"3-month term deposit"},"fdr_1y":{"available":true,"localName":"Oročeni depozit","localNameEn":"1-year term deposit"},"dps":{"available":false,"localName":null,"note":"No standard fixed-rate monthly recurring deposit product was found."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":"Government savings certificate","note":"No retail savings bond for individuals at state or entity level."},"tbill_91d":{"available":true,"localName":"Trezorski zapisi","localNameEn":"Entity treasury bills (FBiH, RS)","note":"Sold by stock-exchange auction, mainly to banks."},"tbond_5y":{"available":true,"localName":"Obveznice","localNameEn":"Entity government bonds (FBiH, RS)","note":"Listed on the Sarajevo and Banja Luka stock exchanges; thinly traded."},"tbond_10y":{"available":false,"localName":null,"localNameEn":"10-year government bond","note":"No regular 10-year issuance found."},"equity_fund":{"available":true,"localName":"Otvoreni investicijski fond","localNameEn":"Open-ended investment fund","note":"A few local funds exist; the local stock market is small and illiquid."},"gold":{"available":true,"localName":"Investicijsko zlato","localNameEn":"Gold bars and coins","note":"Physical gold can be bought legally."}},"institutions":{"centralBank":{"name":"Central Bank of Bosnia and Herzegovina","url":"https://www.cbbh.ba/"},"insuranceRegulator":{"name":"Insurance Supervision Agency of the Federation of BiH (Republika Srpska: Insurance Agency of RS)","url":"https://www.ano.ba/","note":"Republika Srpska: https://azors.rs.ba/sr/"},"insuranceComplaints":{"name":"Insurance Ombudsman (Insurance Supervision Agency of FBiH)","url":"https://www.ano.ba/ombudsmen-u-osiguranju/"},"pensionScheme":{"name":"Federal Pension and Disability Insurance Institute (FZ MIO/PIO)","url":"https://www.fzmiopio.ba/","note":"Republika Srpska: PIO Fund, https://www.fondpiors.org/"},"oldAgeAllowance":null,"publicHealthCover":{"name":"Health Insurance and Reinsurance Institute of the Federation of BiH (ZZOR FBiH)","url":"https://zzofbih.ba/","note":"Republika Srpska: Health Insurance Fund of RS."},"depositInsurance":{"name":"Deposit Insurance Agency of Bosnia and Herzegovina","url":"https://aod.ba/"},"statistics":{"name":"Agency for Statistics of Bosnia and Herzegovina (BHAS)","url":"https://bhas.gov.ba/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BA', 1, 'bank_deposit_avg_rate', 0.0189, NULL, 'sourced', 'World Bank WDI FR.INR.DPST (deposit interest rate)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=BA', '2025-12-31', '1.89% in 2025 (1.61% in 2024), per World Bank via Trading Economics as well.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BA', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap and no published average credit card rate were found; CBBH interest-rate statistics are only in its login-only portal.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BA', 1, 'deposit_insurance_limit', 100000, NULL, 'sourced', 'Deposit Insurance Agency of BiH, Decision on the amount of insured deposit', 'https://aod.ba/odluka-o-visini-osiguranog-depozita/', '2026-10-31', 'KM 100,000 per depositor per member bank, set by the decision published in Official Gazette of BiH no. 75/26; effective date not shown on the page.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BA', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published rate for a monthly recurring deposit product was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BA', 1, 'equity_return_base', 0.045, NULL, 'assumption', 'World Bank deposit rate 1.89% (2025); SASX-10 index record', 'https://tradingeconomics.com/bosnia-and-herzegovina/stock-market', '2026-10-31', 'Based on a global index in euro terms (the mark is pegged to the euro), kept about 2.5 points above the deposit rate because the local SASX-10 has lost 85% since 2007.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BA', 1, 'equity_return_high', 0.075, NULL, 'assumption', 'SASX-10 index record; global equity long-run returns in euro terms', 'https://tradingeconomics.com/bosnia-and-herzegovina/stock-market', '2026-10-31', 'High case near long-run global equity returns in euro terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BA', 1, 'equity_return_low', 0.02, NULL, 'assumption', 'SASX-10 index 1,476 (29 Oct 2026), down from 9,854 in April 2007', 'https://tradingeconomics.com/bosnia-and-herzegovina/stock-market', '2026-10-31', 'Low case for global equities in euro terms over a weak decade; the local market is too small and illiquid to plan with.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BA', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No current 1-year term deposit rate was found; CBBH interest-rate statistics are only in its login-only statistics portal.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BA', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No current 3-month term deposit rate was found; CBBH interest-rate statistics are only in its login-only statistics portal.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BA', 1, 'fixed_income_return_base', 0.015, NULL, 'assumption', 'World Bank deposit rate 1.89% (2025)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=BA', '2026-10-31', 'Base case a little under the average deposit rate to allow for any tax on interest.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BA', 1, 'fixed_income_return_high', 0.025, NULL, 'assumption', 'World Bank deposit rate 1.89% (2025)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=BA', '2026-10-31', 'High case: longer term deposits paying above the average rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BA', 1, 'fixed_income_return_low', 0.01, NULL, 'assumption', 'World Bank deposit rate 1.89% (2025)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=BA', '2026-10-31', 'Low case: savings and short deposits paying well under the average deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BA', 1, 'goal_inflation_education', 0.035, NULL, 'assumption', 'BHAS CPI time series: education division up 2.3% (Sep 2026 vs Sep 2025)', 'https://bhas.gov.ba/data/Publikacije/VremenskeSerije/PRI_01.xlsx', '2026-10-31', 'Education prices rose less than headline CPI, so the 3.5% projection is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BA', 1, 'goal_inflation_health', 0.045, NULL, 'assumption', 'BHAS CPI time series: health division up 5.8% (Sep 2026 vs Sep 2025)', 'https://bhas.gov.ba/data/Publikacije/VremenskeSerije/PRI_01.xlsx', '2026-10-31', 'Health prices rose faster than headline CPI in the past year, so the 3.5% projection plus one point is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BA', 1, 'gold_return_base', 0.05, NULL, 'assumption', 'CBBH exchange rate KM 1.750653 per US dollar (KM 1.95583 per euro), 31 Oct 2026', 'https://www.cbbh.ba/CurrencyExchange/?lang=en', '2026-10-31', 'Long-run dollar gold trend of about 4-5% with no expected trend in the euro-pegged mark against the dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BA', 1, 'gold_return_high', 0.085, NULL, 'assumption', 'CBBH exchange rate KM 1.750653 per US dollar (KM 1.95583 per euro), 31 Oct 2026', 'https://www.cbbh.ba/CurrencyExchange/?lang=en', '2026-10-31', 'High case with strong dollar gold and a weaker euro.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BA', 1, 'gold_return_low', 0.015, NULL, 'assumption', 'CBBH exchange rate KM 1.750653 per US dollar (KM 1.95583 per euro), 31 Oct 2026', 'https://www.cbbh.ba/CurrencyExchange/?lang=en', '2026-10-31', 'Low case: weak dollar gold price and a stronger euro (and mark).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BA', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No statutory end-of-service gratuity in days of wages per year of service was found; severance in the entity labour laws applies to dismissal, and retirement payments are set by collective agreements.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BA', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical out-of-pocket cost for one major private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BA', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No age-banded private health insurance premium table was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BA', 1, 'inflation_cpi', 0.06, NULL, 'sourced', 'Agency for Statistics of BiH (BHAS), CPI time series (PRI_01)', 'https://bhas.gov.ba/data/Publikacije/VremenskeSerije/PRI_01.xlsx', '2026-09-30', 'Annual CPI 6.0% in September 2026 (index 138.75 vs 130.93 a year earlier); also shown on the BHAS home page as ''Inflation (CPI) IX-2026/IX-2025: 6.0%''.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BA', 1, 'inflation_projection', 0.035, NULL, 'assumption', 'BHAS CPI time series (5-year average about 6.3% a year, Sep 2021-Sep 2026); convertible mark pegged to the euro (ECB 2% target)', 'https://bhas.gov.ba/data/Publikacije/VremenskeSerije/PRI_01.xlsx', '2026-10-31', 'The euro peg anchors inflation near euro-area rates in the long run, but recent inflation has run well above them, so 3.5% is used for planning.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BA', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published per-1,000 term life premium table by age was found; life insurance in BiH is mostly savings-type policies quoted individually.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BA', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The insurance agencies (BiH, FBiH, RS) publish premium and claims statistics but no life claim settlement ratio that we could find.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BA', 1, 'life_expectancy', 78.04, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=BA', '2024-12-31', 'Men 74.6, women 81.1; UN WPP 2024 (via populationpyramid.net) gives 78.4 for 2026. Latest World Bank year is 2024 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BA', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":21.3,"men":18.8,"women":23.8},{"age":65,"total":17.8,"men":15.3,"women":19.6},{"age":70,"total":13.9,"men":11.9,"women":15.8},{"age":80,"total":8,"men":6.5,"women":9.4}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/bosnia-and-herzegovina/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for the year 2026 (asOf set to mid-year); totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BA', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension was found, so there are no eligibility rules to report.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BA', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory (social) old-age pension was found in either entity; older people without a pension rely on means-tested social assistance.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BA', 1, 'oop_health_share', 0.3096, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=BA', '2023-12-31', 'Out-of-pocket share 31.0% of current health expenditure. Latest World Bank year is 2023 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BA', 1, 'policy_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Central Bank of BiH runs a currency board pegged to the euro and sets no policy interest rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BA', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":65,"nomineeUntilAge":null,"inflationLinked":true,"taxFree":null}', 'sourced', 'Federal Pension and Disability Insurance Institute (FZ MIO/PIO), pensioners', 'https://www.fzmiopio.ba/penzioneri/', '2026-10-31', 'Contributory pay-as-you-go pensions run by each entity (FZ MIO/PIO in FBiH, PIO Fund in RS). In FBiH, pensions are adjusted every 1 January and 1 July by a blend of consumer prices and gross wages (60/40 or 40/60), and are not cut when the blend is negative.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BA', 1, 'retirement_accumulation_return_base', 0.03, NULL, 'assumption', 'World Bank deposit rate 1.89%; equity base 4.5% (global index in euro terms)', 'https://tradingeconomics.com/bosnia-and-herzegovina/stock-market', '2026-10-31', 'Base case: roughly half global shares at 4.5% and half deposits at about 1.5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BA', 1, 'retirement_accumulation_return_high', 0.045, NULL, 'assumption', 'Global equity in euro terms; SASX-10 index', 'https://tradingeconomics.com/bosnia-and-herzegovina/stock-market', '2026-10-31', 'High case for a growth-leaning balanced mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BA', 1, 'retirement_accumulation_return_low', 0.015, NULL, 'assumption', 'World Bank deposit rate 1.89%; SASX-10 index', 'https://tradingeconomics.com/bosnia-and-herzegovina/stock-market', '2026-10-31', 'Low case for a balanced mix if shares lag.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BA', 1, 'retirement_age_default', 65, NULL, 'sourced', 'Federal Pension and Disability Insurance Institute (FZ MIO/PIO), pensioners', 'https://www.fzmiopio.ba/penzioneri/', '2026-10-31', 'FBiH old-age pension at 65 with at least 15 years of insurance (or 20 years of pension service), or at any age after 40 years of insurance; same for men and women and for anyone born after 1975. Republika Srpska also uses 65 (not checked on an official RS page).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BA', 1, 'retirement_age_government', 65, NULL, 'sourced', 'Federal Pension and Disability Insurance Institute (FZ MIO/PIO), pensioners', 'https://www.fzmiopio.ba/penzioneri/', '2026-10-31', 'Civil servants are in the same entity pension systems and retire on the same age-65 rule; no separate public-service pension age was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BA', 1, 'retirement_return_base', 0.015, NULL, 'assumption', 'World Bank deposit rate 1.89% (2025)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=BA', '2026-10-31', 'Base case kept below the average deposit rate, the best available stand-in for the 1-year deposit rate, to allow for tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BA', 1, 'retirement_return_high', 0.025, NULL, 'assumption', 'World Bank deposit rate 1.89% (2025)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=BA', '2026-10-31', 'High case: longer term deposits and entity bonds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BA', 1, 'retirement_return_low', 0.008, NULL, 'assumption', 'World Bank deposit rate 1.89% (2025)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=BA', '2026-10-31', 'Low case: mostly sight and savings deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BA', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate or retail savings bond for individuals exists at state or entity level that we could find.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BA', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'CBBH interest-rate statistics are only in its login-only statistics portal and its bulletins could not be downloaded; no current savings account rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BA', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":2.81},{"year":2040,"value":2.03},{"year":2065,"value":1.49}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/bosnia-and-herzegovina/2040/', '2025-12-31', '100 / old-age dependency ratio: 35.6 (2025, World Bank), 49.2 (2040) and 67.1 (2065, populationpyramid.net/bosnia-and-herzegovina/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BA', 1, 'tax_bank_interest', NULL, NULL, 'missing', '', '', '2026-10-31', 'PwC Tax Summaries (reviewed 23 Sep 2026) give flat income tax of 10% (FBiH) and 8% (RS) but do not say how bank interest is taxed, and no official page on it was readable.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BA', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate exists, and the tax treatment of interest on entity government securities was not found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BA', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Entity governments (FBiH, RS) issue treasury bills by stock-exchange auction, but no current 3-month yield was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BA', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 10-year government bond yield was found; there is no state-level bond market and entity bonds trade thinly.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BA', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No current 5-year entity government bond yield was found.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('BB', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"BB","iso3":"BRB","nameEn":"Barbados","nameNative":"Barbados","region":"latin_america_caribbean","languages":["en","bjs"],"currency":{"code":"BBD","symbol":"$","decimals":2,"compact":"intl","usdRate":{"value":2,"status":"sourced","sourceName":"Central Bank of Barbados: The What, Why and How of Maintaining Barbados'' Exchange Rate","sourceUrl":"https://www.centralbank.org.bb/news/general-press-release/the-what-why-and-how-of-maintaining-barbados-exchange-rate","asOf":"2026-10-31","note":"Fixed peg of BBD 2.00 per US dollar since 1975; the World Bank PA.NUS.FCRF gives 2.0 for 2025."}},"instruments":{"savings_account":{"available":true,"localName":"Savings account","sourceUrl":"https://cdn.centralbank.org.bb/documents/2026-07-09-14-37-44-E1E2InterestRatesApril2026.xlsx"},"fdr_3m":{"available":true,"localName":"Fixed deposit","localNameEn":"3-month fixed (time) deposit","sourceUrl":"https://cdn.centralbank.org.bb/documents/2026-07-09-14-37-44-E1E2InterestRatesApril2026.xlsx"},"fdr_1y":{"available":true,"localName":"Fixed deposit","localNameEn":"12-month fixed (time) deposit","sourceUrl":"https://cdn.centralbank.org.bb/documents/2026-07-09-14-37-44-E1E2InterestRatesApril2026.xlsx"},"dps":{"available":false,"localName":null,"note":"No standard monthly recurring deposit product with a published rate."},"sanchayapatra_5y":{"available":true,"localName":"BOSS+","localNameEn":"Barbados Optional Savings Bonds Plus (5-year government savings bond)","note":"Sold by the Central Bank for the Government at par; 4.50% fixed, interest not subject to withholding tax; minimum BBD 500.","sourceUrl":"https://www.centralbank.org.bb/news/general-press-release/4-50-barbados-optional-savings-bonds-plus-2030-1"},"tbill_91d":{"available":true,"localName":"Treasury bill","localNameEn":"Government of Barbados Treasury bill (91 and 182 days)","note":"Issued by tender through the CBB; mostly bought by banks and institutions.","sourceUrl":"https://www.centralbank.org.bb/news/general-press-release/treasury-bills-issue-1042"},"tbond_5y":{"available":true,"localName":"Treasury note","localNameEn":"Government of Barbados Treasury note","note":"Issued occasionally through the CBB; no market yield published.","sourceUrl":"https://www.centralbank.org.bb/news/general-press-release-treasury"},"tbond_10y":{"available":true,"localName":"Debenture","localNameEn":"Barbados Government Debenture","note":"Long-dated debentures (latest 7.75% 2045) issued through the CBB; interest subject to 15% withholding tax except for pensioners 60+.","sourceUrl":"https://www.centralbank.org.bb/news/general-press-release/7-75-barbados-government-debenture-2045"},"equity_fund":{"available":true,"localName":"Mutual fund","localNameEn":"Mutual fund (regulated by the Financial Services Commission)","note":"Locally sponsored mutual funds invest in local and regional shares and bonds."},"gold":{"available":true,"localName":"Gold","localNameEn":"Gold jewellery, coins and bars","note":"No legal restriction on buying gold; mostly sold as jewellery."}},"institutions":{"centralBank":{"name":"Central Bank of Barbados","url":"https://www.centralbank.org.bb/"},"insuranceRegulator":{"name":"Financial Services Commission (insurance division)","url":"https://www.fsc.gov.bb/regulatory-divisions/insurance"},"insuranceComplaints":{"name":"Financial Services Commission: tips, complaints and referrals","url":"https://www.fsc.gov.bb/tips-complaints-referrals"},"pensionScheme":{"name":"National Insurance and Social Security Service (NIS)","url":"https://www.nis.gov.bb/"},"oldAgeAllowance":{"name":"Non-Contributory Old Age Pension (NIS)","url":"https://www.nis.gov.bb/non-contributory-old-age-pension"},"publicHealthCover":{"name":"Ministry of Health and Wellness (free care at public hospitals and polyclinics)","url":"https://www.health.gov.bb/"},"depositInsurance":{"name":"Barbados Deposit Insurance Corporation","url":"https://bdic.org.bb/"},"statistics":{"name":"Barbados Statistical Service","url":"https://stats.gov.bb/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BB', 1, 'bank_deposit_avg_rate', 0.0017, NULL, 'sourced', 'Central Bank of Barbados Table E1 (weighted average deposit rate), April 2026 release', 'https://cdn.centralbank.org.bb/documents/2026-07-09-14-37-44-E1E2InterestRatesApril2026.xlsx', '2026-04-30', 'Weighted average deposit rate 0.17% (rounded to 0.1% in the CBB review for September 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BB', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched CBB, FSC and government sources: no legal cap on credit card interest exists and no official typical rate is published (only company rate sheets and older news citing rates above 20%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BB', 1, 'deposit_insurance_limit', 25000, NULL, 'sourced', 'Barbados Deposit Insurance Corporation, deposit insurance calculator', 'https://bdic.org.bb/site/index.php/en/resources-docs/deposit-insurance-calculator', '2026-10-31', 'BBD 25,000 per depositor per bank; joint and trust accounts are separate categories. Parliament passed a Protection of Depositors bill in June 2026 extending cover to credit unions at the same limit (not yet verified as in force).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BB', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched CBB interest-rate tables and regulator material: no monthly recurring deposit product rate is published for Barbados banks.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BB', 1, 'equity_return_base', 0.04, NULL, 'assumption', 'CBB Treasury bill 0.67% (Sep 2026); BOSS+ 4.50% tax-free', 'https://www.centralbank.org.bb/news/general-press-release/treasury-bills-issue-1042', '2026-10-31', 'Safe after-tax rate of 0.67% plus a premium kept below 4 points because the local index record is weak; dividends make up most of the return.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BB', 1, 'equity_return_high', 0.08, NULL, 'assumption', 'CBB Treasury bill 0.67% (Sep 2026); BOSS+ 4.50% tax-free', 'https://www.centralbank.org.bb/news/general-press-release/treasury-bills-issue-1042', '2026-10-31', 'High case if local listed companies keep paying solid dividends and prices recover, or if savers hold global funds in US-dollar-pegged terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BB', 1, 'equity_return_low', 0, NULL, 'assumption', 'CBB Treasury bill 0.67% (Sep 2026); BOSS+ 4.50% tax-free', 'https://www.centralbank.org.bb/news/general-press-release/treasury-bills-issue-1042', '2026-10-31', 'Low case of zero: the small, illiquid Barbados Stock Exchange has had a weak 10-year price record.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BB', 1, 'fdr_1y_rate', 0.01, NULL, 'sourced', 'Central Bank of Barbados Table E1 (commercial banks'' selected interest rates), April 2026 release', 'https://cdn.centralbank.org.bb/documents/2026-07-09-14-37-44-E1E2InterestRatesApril2026.xlsx', '2026-04-30', 'Posted 12-month time deposit rates range from 0% to 2%; midpoint used. The weighted average on all deposits is only 0.17%, so most balances earn far less.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BB', 1, 'fdr_3m_rate', 0, NULL, 'sourced', 'Central Bank of Barbados Table E1 (commercial banks'' selected interest rates), April 2026 release', 'https://cdn.centralbank.org.bb/documents/2026-07-09-14-37-44-E1E2InterestRatesApril2026.xlsx', '2026-04-30', 'Posted 3-month time deposit rates are 0% at both the minimum and the maximum of the range reported by banks.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BB', 1, 'fixed_income_return_base', 0.025, NULL, 'assumption', 'BOSS+ 4.50% tax-free; Treasury bill 0.67%; deposits 0-2%', 'https://www.centralbank.org.bb/news/general-press-release/4-50-barbados-optional-savings-bonds-plus-2030-1', '2026-10-31', 'Base case: a mix of tax-free BOSS+ bonds and short-term deposits or bills.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BB', 1, 'fixed_income_return_high', 0.045, NULL, 'assumption', 'BOSS+ 4.50% tax-free', 'https://www.centralbank.org.bb/news/general-press-release/4-50-barbados-optional-savings-bonds-plus-2030-1', '2026-10-31', 'High case: all in tax-free 5-year BOSS+ bonds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BB', 1, 'fixed_income_return_low', 0.002, NULL, 'assumption', 'CBB Table E1 weighted average deposit rate 0.17%', 'https://cdn.centralbank.org.bb/documents/2026-07-09-14-37-44-E1E2InterestRatesApril2026.xlsx', '2026-10-31', 'Low case: ordinary deposits at about 0.2% after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BB', 1, 'goal_inflation_education', 0.035, NULL, 'assumption', 'CBB review Jan-Sep 2026: education among the CPI groups pushing inflation up', 'https://www.centralbank.org.bb/news/economic-reviews/economic-review-january-september-2026', '2026-10-31', 'No long-run education CPI series found; headline projection plus one point.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BB', 1, 'goal_inflation_health', 0.04, NULL, 'assumption', 'CBB review Jan-Sep 2026: health among the CPI groups pushing inflation up', 'https://www.centralbank.org.bb/news/economic-reviews/economic-review-january-september-2026', '2026-10-31', 'No separate long-run medical CPI series found; we plan with headline projection plus 1.5 points for private medical costs.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BB', 1, 'gold_return_base', 0.045, NULL, 'assumption', 'Barbados dollar fixed at BBD 2 = USD 1 (Central Bank of Barbados)', 'https://www.centralbank.org.bb/news/general-press-release/the-what-why-and-how-of-maintaining-barbados-exchange-rate', '2026-10-31', 'Long-run dollar gold trend of about 4-5% a year, with no expected depreciation under the fixed peg.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BB', 1, 'gold_return_high', 0.08, NULL, 'assumption', 'Barbados dollar fixed at BBD 2 = USD 1 (Central Bank of Barbados)', 'https://www.centralbank.org.bb/news/general-press-release/the-what-why-and-how-of-maintaining-barbados-exchange-rate', '2026-10-31', 'High case with strong dollar gold, or a peg under stress.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BB', 1, 'gold_return_low', 0.01, NULL, 'assumption', 'Barbados dollar fixed at BBD 2 = USD 1 (Central Bank of Barbados)', 'https://www.centralbank.org.bb/news/general-press-release/the-what-why-and-how-of-maintaining-barbados-exchange-rate', '2026-10-31', 'Low case: weak dollar gold price; the peg means no currency boost.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BB', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'Barbados has no statutory gratuity on retirement or resignation; the Severance Payments Act pays 2.5 to 3.5 weeks'' wages per year of service only on redundancy after 104 weeks of service (Severance Payments Act, Cap. 355A, as cited by the Barbados courts: https://www.barbadoslawcourts.gov.bb/assets/content/pdfs/2014/09/No.-665-of-1992-Hoyte-Ivor-Winston-v.-The-Transport-Board.pdf). Retirement income runs through the NIS.', 1);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BB', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched Ministry of Health and Wellness and other public sources: care at the Queen Elizabeth Hospital is free for residents, and no official typical private hospital bill is published (only insurer and travel-guide estimates).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BB', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched FSC and public sources: no published private health insurance premiums by age (group plans dominate; individual quotes only).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BB', 1, 'inflation_cpi', 0.015, NULL, 'sourced', 'Central Bank of Barbados, Review of the Economy January-September 2026 (Barbados Statistical Service CPI)', 'https://www.centralbank.org.bb/news/economic-reviews/economic-review-january-september-2026', '2026-07-31', '12-month moving-average inflation 1.5% in July 2026 (latest CPI month); point-to-point 1.5% in July, after 2.0% in May.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BB', 1, 'inflation_projection', 0.025, NULL, 'assumption', 'CBB review Jan-Sep 2026 (inflation expected at 1.5-2% by end-2026); World Bank CPI 2023-2025: 3.2, 1.4, 0.8%', 'https://www.centralbank.org.bb/news/economic-reviews/economic-review-january-september-2026', '2026-10-31', 'Barbados has no inflation target (the dollar is pegged to the US dollar); the CBB expects 1.5-2% for 2026 and recent years averaged about 2-3%, so we plan with 2.5% to allow for imported energy and freight shocks.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BB', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life is sold in Barbados, but no regulator or public source publishes premium rates by age; only individual insurer quotes exist.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BB', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched Financial Services Commission annual and insurance reports: no industry-wide life claim settlement ratio is published.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BB', 1, 'life_expectancy', 76.332, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=BB', '2024-12-31', 'UN WPP 2024 (via populationpyramid.net) gives 76.6 for 2026 (men 74.1, women 79.0).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BB', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":21.3,"men":19.7,"women":22.9},{"age":65,"total":17.4,"men":15.9,"women":18.6},{"age":70,"total":13.5,"men":12.4,"women":14.6},{"age":80,"total":7,"men":6.4,"women":7.6}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/barbados/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BB', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":67,"womenAge":67,"over90Monthly":null,"meansTested":false}', 'sourced', 'National Insurance and Social Security Service, Non-Contributory Old Age Pension', 'https://www.nis.gov.bb/non-contributory-old-age-pension', '2026-10-31', 'Payable from 67 (the pensionable age) to citizens with 12 years'' residence after 40 or 20 years after 18 (15/20 for permanent residents). Not income-tested, but excluded if receiving a public service pension or an NIS pension above this rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BB', 1, 'old_age_allowance_monthly', 997, NULL, 'sourced', 'National Insurance and Social Security Service, Non-Contributory Old Age Pension', 'https://www.nis.gov.bb/non-contributory-old-age-pension', '2026-10-31', 'NIS page says the rate is currently BBD 230 a week (same for all), converted as 230 x 52 / 12; the page gives no effective date for the rate, so asOf is the date it was read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BB', 1, 'oop_health_share', 0.4949, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=BB', '2023-12-31', 'Figure is for 2023 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BB', 1, 'policy_rate', 0.02, NULL, 'sourced', 'Central Bank of Barbados Table E2 (Bank Rate), April 2026 release', 'https://cdn.centralbank.org.bb/documents/2026-07-09-14-37-44-E1E2InterestRatesApril2026.xlsx', '2026-05-31', 'The Bank Rate (discount rate on overnight lending to licensees) has been 2% since April 2020; under the peg it is not actively moved.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BB', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":68,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'NIS reform summary (National Insurance and Social Security (Amendment) Act 2023)', 'https://www.nis.gov.bb/wp-content/uploads/2023/07/NIS2-PDF.pdf', '2023-07-28', 'Compulsory contributory NIS old-age pension for employed and self-employed people. Reform summary (2023, older than 2025): pension age 67 now, 67.5 from 2028 and 68 from 2034; contributions needed rise from 500 to 750 weeks by 2031; best 10 years of earnings; pensions get up to 1.5% a year cost-of-living increases (not full indexation). Minimum entry age not stated in the source read, so left null.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BB', 1, 'retirement_accumulation_return_base', 0.035, NULL, 'assumption', 'BOSS+ 4.50%; Treasury bill 0.67%; weak local equity record', 'https://www.centralbank.org.bb/news/general-press-release/4-50-barbados-optional-savings-bonds-plus-2030-1', '2026-10-31', 'Base case: half equities at 4% and half government savings bonds and deposits around 3%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BB', 1, 'retirement_accumulation_return_high', 0.055, NULL, 'assumption', 'BOSS+ 4.50%; Treasury bill 0.67%; weak local equity record', 'https://www.centralbank.org.bb/news/general-press-release/4-50-barbados-optional-savings-bonds-plus-2030-1', '2026-10-31', 'High case with stronger equity returns, including global funds held in pegged dollars.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BB', 1, 'retirement_accumulation_return_low', 0.02, NULL, 'assumption', 'BOSS+ 4.50%; Treasury bill 0.67%; weak local equity record', 'https://www.centralbank.org.bb/news/general-press-release/4-50-barbados-optional-savings-bonds-plus-2030-1', '2026-10-31', 'Low case for a balanced mix if local shares stagnate and bonds are held to maturity.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BB', 1, 'retirement_age_default', 68, NULL, 'sourced', 'National Insurance Scheme, Embracing changes: Towards a new NIS (2023 reform summary; enacted as the NIS (Amendment) Act 2023)', 'https://www.nis.gov.bb/wp-content/uploads/2023/07/NIS2-PDF.pdf', '2023-07-28', 'NIS pensionable age is 67 now, rises to 67.5 in 2028 and 68 in 2034, so 68 applies to anyone born after 1975. There is no statutory private-sector retirement age. Source dates from 2023 (older than 2025) but the schedule is still the legislated path (Act passed by the Senate 9 August 2023, https://www.barbadosparliament.com/bills/details/722).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BB', 1, 'retirement_age_government', 67, NULL, 'sourced', 'Ministry of the Public Service, Compulsory Age of Retirement', 'https://mps.gov.bb/People_Resourcing/age', '2018-01-01', 'Compulsory retirement age for public officers is 67 from 1 January 2018 (Pensions Act, Cap. 25); voluntary retirement from 60. Figure dates from 2018 but is still in force.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BB', 1, 'retirement_return_base', 0.0067, NULL, 'assumption', 'CBB Treasury Bills Issue 1042 (91-day 0.67%)', 'https://www.centralbank.org.bb/news/general-press-release/treasury-bills-issue-1042', '2026-10-31', 'Base case capped at the Treasury bill rate, the best safe short rate; pensioners 60+ pay no withholding tax on interest.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BB', 1, 'retirement_return_high', 0.035, NULL, 'assumption', 'BOSS+ 4.50% tax-free', 'https://www.centralbank.org.bb/news/general-press-release/4-50-barbados-optional-savings-bonds-plus-2030-1', '2026-10-31', 'High case: a ladder of tax-free BOSS+ bonds with some cash, below the full 4.5% coupon for liquidity.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BB', 1, 'retirement_return_low', 0.0015, NULL, 'assumption', 'CBB Table E1 weighted average deposit rate 0.17%', 'https://cdn.centralbank.org.bb/documents/2026-07-09-14-37-44-E1E2InterestRatesApril2026.xlsx', '2026-10-31', 'Low case: savings deposits after the 15% withholding tax (exempt from 60, but rates are near zero).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BB', 1, 'sanchayapatra_5y_rate', 0.045, NULL, 'sourced', 'Central Bank of Barbados, 4.50% Barbados Optional Savings Bonds Plus (BOSS+) 2030', 'https://www.centralbank.org.bb/news/general-press-release/4-50-barbados-optional-savings-bonds-plus-2030-1', '2026-01-01', 'BOSS+ is a 5-year government savings bond sold at par through the CBB: fixed 4.50% paid twice a year, minimum BBD 500, redeemable at par after 24 months. Latest series issued 1 January 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BB', 1, 'savings_account_rate', 0.0017, NULL, 'sourced', 'Central Bank of Barbados Table E1 (commercial banks'' selected interest rates), April 2026 release', 'https://cdn.centralbank.org.bb/documents/2026-07-09-14-37-44-E1E2InterestRatesApril2026.xlsx', '2026-04-30', 'No single savings rate is published: posted savings rates range from 0% to 2%, and the weighted average rate on all deposits is 0.17%, used here as the typical rate. The CBB stopped setting a minimum savings rate in 2015.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BB', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":3.9},{"year":2040,"value":2.7},{"year":2065,"value":2.2}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/barbados/2040/', '2025-12-31', '100 / old-age dependency ratio: 25.9 (2025, World Bank), 37.0 (2040) and 46.0 (2065, populationpyramid.net/barbados/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BB', 1, 'tax_bank_interest', 0.15, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Barbados: Individual - Income determination', 'https://taxsummaries.pwc.com/barbados/individual/income-determination', '2026-10-09', '15% final withholding tax on local interest over BBD 100 paid to residents; no tax is withheld from interest paid to pensioners aged 60 and over (PwC page last reviewed 9 October 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BB', 1, 'tax_sanchayapatra_profit', 0, NULL, 'sourced', 'Central Bank of Barbados, Government Securities: What You Need to Know About BOSS+ Bonds', 'https://centralbank.org.bb/news/moneysmart-investing/government-securities-what-you-need-to-know-about-boss-bonds', '2024-10-27', 'BOSS+ interest is not subject to withholding tax, unlike the 15% on bank interest (CBB guide from October 2024, still current for the 2026 series).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BB', 1, 'tbill_91d_rate', 0.0067, NULL, 'sourced', 'Central Bank of Barbados, Treasury Bills Issue 1042 notice', 'https://www.centralbank.org.bb/news/general-press-release/treasury-bills-issue-1042', '2026-09-09', 'Last-issue 91-day rate 0.67% (average tender price 99.83) shown in the 9 September 2026 notice; the CBB review gives a 0.7% Treasury bill rate for September 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BB', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched CBB government securities pages: no 10-year benchmark yield is published. The latest long issue is the 7.75% Barbados Government Debenture 2045 (issued 1 January 2026, amortising 2036-2045).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BB', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched CBB government securities pages: no market yield for 5-year government paper is published; the retail 5-year BOSS+ bond pays a fixed 4.50% (see sanchayapatra_5y_rate).', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('BD', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"BD","iso3":"BGD","nameEn":"Bangladesh","nameNative":"বাংলাদেশ","region":"south_asia","languages":["bn","en"],"currency":{"code":"BDT","symbol":"৳","decimals":2,"compact":"lakh_crore","usdRate":{"value":123.99,"status":"sourced","sourceName":"Bangladesh Bank (weighted average rate)","sourceUrl":"https://www.bb.org.bd/en/index.php/econdata/exchangerate","asOf":"2026-10-29"}},"instruments":{"savings_account":{"available":true,"localName":"সঞ্চয়ী হিসাব","localNameEn":"Savings account"},"fdr_3m":{"available":true,"localName":"এফডিআর","localNameEn":"FDR (3-month fixed deposit)"},"fdr_1y":{"available":true,"localName":"এফডিআর","localNameEn":"FDR (1-year fixed deposit)"},"dps":{"available":true,"localName":"ডিপিএস","localNameEn":"DPS (deposit pension scheme)"},"sanchayapatra_5y":{"available":true,"localName":"পাঁচ বছর মেয়াদি বাংলাদেশ সঞ্চয়পত্র","localNameEn":"5-year Bangladesh Sanchayapatra","sourceUrl":"https://nationalsavings.gov.bd/"},"tbill_91d":{"available":true,"localName":"ট্রেজারি বিল","localNameEn":"Treasury bill","sourceUrl":"https://www.bb.org.bd/en/index.php/monetaryactivity/treasury"},"tbond_5y":{"available":true,"localName":"ট্রেজারি বন্ড","localNameEn":"Treasury bond","sourceUrl":"https://www.bb.org.bd/en/index.php/monetaryactivity/treasury"},"tbond_10y":{"available":true,"localName":"ট্রেজারি বন্ড","localNameEn":"Treasury bond","sourceUrl":"https://www.bb.org.bd/en/index.php/monetaryactivity/treasury"},"equity_fund":{"available":true,"localName":"মিউচুয়াল ফান্ড","localNameEn":"Mutual fund","note":"Diversified open-end funds only; no index funds or ETFs trade in Bangladesh."},"gold":{"available":true,"localName":"সোনা","localNameEn":"Gold","note":"Bought as jewellery or bars; priced per bhori by BAJUS."}},"institutions":{"centralBank":{"name":"Bangladesh Bank","url":"https://www.bb.org.bd/"},"insuranceRegulator":{"name":"Insurance Development and Regulatory Authority","url":"https://idra.org.bd/"},"insuranceComplaints":{"name":"Insurance Development and Regulatory Authority (complaints)","url":"https://idra.org.bd/","note":"Complaints about insurers go to IDRA."},"pensionScheme":{"name":"Universal Pension Scheme (National Pension Authority)","url":"https://www.upension.gov.bd/"},"oldAgeAllowance":{"name":"Department of Social Services (old-age allowance)","url":"https://dss.gov.bd/"},"publicHealthCover":{"name":"Directorate General of Health Services (public hospitals)","url":"https://dghs.gov.bd/","note":"No national health insurance; public hospitals charge low fees."},"depositInsurance":{"name":"Deposit protection funds (Bangladesh Bank)","url":"https://www.bb.org.bd/"},"statistics":{"name":"Bangladesh Bureau of Statistics","url":"https://bbs.gov.bd/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BD', 1, 'bank_deposit_avg_rate', 0.0616, NULL, 'sourced', 'Bangladesh Bank', 'https://www.bb.org.bd/en/index.php/econdata/intrate', '2026-08-31', NULL, 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BD', 1, 'credit_card_rate_cap', 0.25, NULL, 'sourced', 'UNB (Bangladesh Bank circular)', 'https://unb.com.bd/category/Business/bangladesh-bank-raises-credit-card-loan-limit-to-tk-40-lakh/181670', '2026-03-15', NULL, 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BD', 1, 'deposit_insurance_limit', 200000, NULL, 'sourced', 'BSS', 'https://www.bssnews.net/js-session/376349', '2026-04-10', 'Deposit Protection Bill 2026, passed 10 Apr 2026, raised cover from Tk 100,000 to Tk 200,000 per depositor; the limit is reviewed every three years.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BD', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Bangladesh Bank''s deposit-rate chart has no DPS column; the only DPS rates found were individual banks'' own rate sheets (about 8.25%-10.5% for 5 years), which cannot be cited.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BD', 1, 'equity_return_base', 0.09, NULL, 'assumption', 'Dhaka Stock Exchange (DSEX); Sanchayapatra and T-bill after tax', 'https://www.dse.com.bd/indices/DSEX', '2026-10-31', 'Weak 10-year DSEX record, so the base is kept below the 10.6% after-tax Sanchayapatra rate and within 4 points of the 7.7% after-tax 91-day T-bill.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BD', 1, 'equity_return_high', 0.14, NULL, 'assumption', 'Dhaka Stock Exchange (DSEX)', 'https://www.dse.com.bd/indices/DSEX', '2026-10-31', 'A recovery case with dividends and earnings growth near nominal GDP growth.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BD', 1, 'equity_return_low', 0.02, NULL, 'assumption', 'Dhaka Stock Exchange (DSEX)', 'https://www.dse.com.bd/indices/DSEX', '2026-10-31', 'DSEX rose only about 1.5% a year (price only) over the last 10 years.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BD', 1, 'fdr_1y_rate', 0.0825, NULL, 'sourced', 'Bangladesh Bank, scheduled banks'' announced deposit rates', 'https://www.bb.org.bd/en/index.php/financialactivity/interestdeposit', '2026-10-01', 'October 2026 chart, fixed deposits of 1 to under 2 years: median about 8.25% across scheduled banks, most between 7% and 10%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BD', 1, 'fdr_3m_rate', 0.075, NULL, 'sourced', 'Bangladesh Bank, scheduled banks'' announced deposit rates', 'https://www.bb.org.bd/en/index.php/financialactivity/interestdeposit', '2026-10-01', 'October 2026 chart, fixed deposits of 3 to under 6 months: median about 7.4% across scheduled banks, most between 7% and 9%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BD', 1, 'fixed_income_return_base', 0.085, NULL, 'assumption', 'Sanchayapatra, DPS and T-bill rates after tax', 'https://thefinancialexpress.com.bd/home/bangladesh-keeps-national-savings-certificate-interest-rates-unchanged-for-jul-dec', '2026-10-31', 'Blend of 1-year fixed deposits (7.4% after tax), 91-day T-bills (7.7%) and 5-year Sanchayapatra (10.6%) after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BD', 1, 'fixed_income_return_high', 0.105, NULL, 'assumption', 'Sanchayapatra rates after tax', 'https://thefinancialexpress.com.bd/home/bangladesh-keeps-national-savings-certificate-interest-rates-unchanged-for-jul-dec', '2026-10-31', '5-year Sanchayapatra 11.83% less 10% tax is about 10.6%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BD', 1, 'fixed_income_return_low', 0.065, NULL, 'assumption', 'Bangladesh Bank deposit-rate chart; 10% tax on interest', 'https://www.bb.org.bd/en/index.php/financialactivity/interestdeposit', '2026-10-31', '1-year fixed deposit about 8.25% less 10% tax is 7.4%; the low case allows for rate cuts.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BD', 1, 'goal_inflation_education', 0.1, NULL, 'assumption', 'BBS CPI via UNB', 'https://unb.com.bd/category/Business/food-inflation-rises-pushes-up-overall-inflation-in-september/197246', '2026-10-31', 'No education CPI series is published; we plan with 10%, about 2 points above general inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BD', 1, 'goal_inflation_health', 0.1, NULL, 'assumption', 'BBS CPI via UNB', 'https://unb.com.bd/category/Business/food-inflation-rises-pushes-up-overall-inflation-in-september/197246', '2026-10-31', 'No medical CPI series is published; we plan with 10%, about 2 points above general inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BD', 1, 'gold_return_base', 0.08, NULL, 'assumption', 'BAJUS gold prices via Financial Express', 'https://thefinancialexpress.com.bd/trade/gold-prices-cut-by-tk-3324-per-bhori-in-bangladesh', '2026-10-31', 'Dollar gold trend plus expected taka depreciation, set equal to the 8% inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BD', 1, 'gold_return_high', 0.12, NULL, 'assumption', 'BAJUS gold prices via Financial Express', 'https://thefinancialexpress.com.bd/trade/gold-prices-cut-by-tk-3324-per-bhori-in-bangladesh', '2026-10-31', 'Strong dollar gold plus faster taka depreciation, as in 2022-2024.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BD', 1, 'gold_return_low', 0.02, NULL, 'assumption', 'BAJUS gold prices via Financial Express', 'https://thefinancialexpress.com.bd/trade/gold-prices-cut-by-tk-3324-per-bhori-in-bangladesh', '2026-10-31', 'Gold can stall in taka terms for years when dollar gold falls and the taka is stable.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BD', 1, 'gratuity_rule', NULL, '{"daysPerYear":30,"daysPerYearAfter":45,"afterYears":10,"daysPerMonth":30}', 'sourced', 'Bangladesh Labour Act 2006, s.2(10) (official English text, Ministry of Law)', 'https://bdlaws.minlaw.gov.bd/upload/act/2022-01-31-10-23-59-49.The-Bangladesh-Labour-Act,-2006.pdf', '2026-10-31', 'At least 30 days'' last wages per completed year of service, or 45 days per year for service over 10 years (clause substituted in 2013); law in force.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BD', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No typical cost of one major private hospital stay published; HIES 2022 analysis gives a yearly average out-of-pocket hospitalisation cost of USD 538 in private facilities (BMC Cost Effectiveness and Resource Allocation, 2025), which is not a major-stay figure. The rates seed carries a placeholder.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BD', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published individual health insurance premium tables found; standalone health cover is sold only by non-life insurers and is thin. The rates seed carries a placeholder table.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BD', 1, 'inflation_cpi', 0.0834, NULL, 'sourced', 'UNB / BBS', 'https://unb.com.bd/category/Business/food-inflation-rises-pushes-up-overall-inflation-in-september/197246', '2026-09-30', 'September 2026 point to point (BBS); food 7.22%, non-food 9.30%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BD', 1, 'inflation_projection', 0.08, NULL, 'assumption', 'BBS CPI via UNB (Sep 2026: 8.34%)', 'https://unb.com.bd/category/Business/food-inflation-rises-pushes-up-overall-inflation-in-september/197246', '2026-10-31', 'CPI has run at 8-10% for three years and Bangladesh Bank''s 5-6% goal is not yet credible, so we plan with 8%, the current rate rounded down.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BD', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published pure-term premium tables found; one 2025 worked example (age 35, non-smoker, 20-year term) gives about Tk 3.9 per Tk 1,000 of cover (insurancenews24.com). The rates seed carries a placeholder table.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BD', 1, 'life_claim_settlement_rate', 0.57, NULL, 'sourced', 'Financial Express (IDRA)', 'https://thefinancialexpress.com.bd/stock/idra-targets-75pc-claim-settlement-rate-amid-tk-70b-backlog', '2026-06-30', '57% of claims settled as of June 2026 (IDRA target 75%), amid a Tk 70 bn backlog of unpaid life claims; the article may mean the whole sector rather than life only.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BD', 1, 'life_expectancy', 72.3, NULL, 'sourced', 'Prothom Alo / BBS SVRS 2023', 'https://en.prothomalo.com/bangladesh/cqjsjk3buz', '2023-12-31', 'BBS Sample Vital Statistics 2023 (published Mar 2024; older than 2025, latest BBS figure found); men 70.8, women 73.8. UN WPP/World Bank give 74.9 for 2024.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BD', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":19.6,"men":18.5,"women":20.7,"projected":21.2,"projectedMen":19.9,"projectedWomen":22.5},{"age":65,"total":16,"men":15.1,"women":16.9,"projected":17.4,"projectedMen":16.3,"projectedWomen":18.5},{"age":70,"total":13,"projected":13.9,"projectedMen":12.9,"projectedWomen":14.9},{"age":80,"total":8.9,"projected":8.1,"projectedMen":7.4,"projectedWomen":8.7}]}', 'sourced', 'BBS SVRS 2020 life table; UN WPP 2026 projection', 'https://georank.org/life-expectancy/bangladesh', '2026-10-30', 'Explainer only; never the plan-to age. total/men/women are the BBS SVRS 2020 life table carried over from the rates seed (older than 2025; not re-verified); projected values are UN WPP 2026 as shown on georank.org (expected age at death minus current age).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BD', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'The rates seed gives men 65, women 62, means-tested, Tk 1,000 over age 90, citing only a district office home page; dss.gov.bd failed TLS checks and no page confirming these rules could be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BD', 1, 'old_age_allowance_monthly', 700, NULL, 'sourced', 'TBS, Jun 2026', 'https://www.tbsnews.net/node/1460791', '2026-07-01', 'Raised by Tk 50 to Tk 700 a month in the FY2026-27 budget (from July 2026), for 6.2 million recipients; means-tested; never counted in the plan.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BD', 1, 'oop_health_share', 0.793, NULL, 'sourced', 'World Bank WDI', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=BD', '2023-12-31', NULL, 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BD', 1, 'policy_rate', 0.095, NULL, 'sourced', 'UNB', 'https://unb.com.bd/category/Business/bb-unveils-first-quarterly-monetary-policy-keeps-policy-rate-unchanged-at-95/196649', '2026-09-30', 'Repo rate held at 9.50% in the Oct-Dec 2026 quarterly statement (SLF 11.00%, SDF 7.50%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BD', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":18,"entryAgeMax":50,"pensionFromAge":60,"nomineeUntilAge":75,"inflationLinked":false,"taxFree":true,"projections":[{"monthlyContribution":1000,"years":10,"monthlyPension":1530},{"monthlyContribution":1000,"years":42,"monthlyPension":34465}]}', 'sourced', 'upension.gov.bd / Prothom Alo, Sep 2026', 'https://www.upension.gov.bd/Public/PensionBriefEn', '2026-09-30', 'No guaranteed rate; fixed amount for life. The official brief says the nominee receives the pension until the member would have turned 75 (the seed had 80). Entry 18-50 pays until 60; over 50 pays 10 years. Projections are from Prothom Alo, Sep 2026 (not re-verified).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BD', 1, 'retirement_accumulation_return_base', 0.09, NULL, 'assumption', 'Sanchayapatra, DSEX and gold assumptions', 'https://thefinancialexpress.com.bd/home/bangladesh-keeps-national-savings-certificate-interest-rates-unchanged-for-jul-dec', '2026-10-31', 'Balanced mix of fixed deposits, T-bills and Sanchayapatra (about 8.5% after tax), equity (9%) and gold (8%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BD', 1, 'retirement_accumulation_return_high', 0.11, NULL, 'assumption', 'Sanchayapatra, DSEX and gold assumptions', 'https://thefinancialexpress.com.bd/home/bangladesh-keeps-national-savings-certificate-interest-rates-unchanged-for-jul-dec', '2026-10-31', 'Equity recovery and full use of Sanchayapatra caps.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BD', 1, 'retirement_accumulation_return_low', 0.06, NULL, 'assumption', 'Sanchayapatra, DSEX and gold assumptions', 'https://thefinancialexpress.com.bd/home/bangladesh-keeps-national-savings-certificate-interest-rates-unchanged-for-jul-dec', '2026-10-31', 'Mostly fixed income with weak equity.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BD', 1, 'retirement_age_default', 60, NULL, 'sourced', 'Bangladesh Labour Act 2006, s.28 (official English text, Ministry of Law)', 'https://bdlaws.minlaw.gov.bd/upload/act/2022-01-31-10-23-59-49.The-Bangladesh-Labour-Act,-2006.pdf', '2026-10-31', 'Workers retire on completing 60 years of age; law in force as amended.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BD', 1, 'retirement_age_government', 59, NULL, 'sourced', 'Daily Observer (Public Servants (Retirement) Act 1974, amended 2011)', 'https://observerbd.com/news/494603', '2024-10-12', 'Public Servants (Retirement) Act 1974, raised from 57 to 59 in 2011. Source article is from 2024 (older than 2025); no later change found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BD', 1, 'retirement_return_base', 0.075, NULL, 'assumption', 'Bangladesh Bank T-bill auctions; 10% withholding on securities interest', 'https://www.bb.org.bd/en/index.php/monetaryactivity/treasury', '2026-10-31', '91-day T-bill 8.56% less the 10% withholding on securities interest is 7.7%, so the base is held at 7.5%; the rates seed uses 10% based on Sanchayapatra.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BD', 1, 'retirement_return_high', 0.105, NULL, 'assumption', 'Sanchayapatra rates after tax', 'https://thefinancialexpress.com.bd/home/bangladesh-keeps-national-savings-certificate-interest-rates-unchanged-for-jul-dec', '2026-10-31', 'A retiree holding Pensioner or 5-year Sanchayapatra within the caps earns about 10.6% after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BD', 1, 'retirement_return_low', 0.065, NULL, 'assumption', 'Bangladesh Bank deposit-rate chart; 10% tax on interest', 'https://www.bb.org.bd/en/index.php/financialactivity/interestdeposit', '2026-10-31', '1-year fixed deposit about 8.25% less 10% tax is 7.4%, rounded down for possible rate cuts.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BD', 1, 'sanchayapatra_5y_rate', 0.1183, NULL, 'sourced', 'Financial Express (DNS Jul–Dec 2026 rates)', 'https://thefinancialexpress.com.bd/home/bangladesh-keeps-national-savings-certificate-interest-rates-unchanged-for-jul-dec', '2026-07-01', '5-year Bangladesh Sanchayapatra, Jul-Dec 2026, holdings up to the tier cap; 11.80% above it.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BD', 1, 'savings_account_rate', 0.0325, NULL, 'sourced', 'Bangladesh Bank, scheduled banks'' announced deposit rates', 'https://www.bb.org.bd/en/index.php/financialactivity/interestdeposit', '2026-10-01', 'October 2026 chart, savings deposits under Tk 1 crore: median about 3.25% across scheduled banks, most between 2.5% and 4.5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BD', 1, 'support_ratio', NULL, '{"points":[{"year":2026,"value":9.6},{"year":2040,"value":6.9},{"year":2065,"value":3.1}]}', 'sourced', 'PopulationPyramid.net (UN WPP 2024, medium variant)', 'https://www.populationpyramid.net/bangladesh/2040/', '2026-10-31', 'People aged 15-64 per person 65+, computed from the UN WPP 2024 age structure; World Bank old-age dependency 10.15 (2025) gives 9.9.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BD', 1, 'tax_bank_interest', 0.1, NULL, 'sourced', 'PwC Tax Summaries, Bangladesh withholding taxes', 'https://taxsummaries.pwc.com/bangladesh/corporate/withholding-taxes', '2026-07-31', '10% on interest from savings and fixed deposits for individuals; 15% (50% more) when the payee cannot show proof of return submission. Secondary source; last reviewed 31 Jul 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BD', 1, 'tax_sanchayapatra_profit', 0.1, NULL, 'sourced', 'Daily Observer', 'https://observerbd.com/news/582881', '2026-07-11', NULL, 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BD', 1, 'tbill_91d_rate', 0.0856, NULL, 'sourced', 'Bangladesh Bank auctions', 'https://www.bb.org.bd/en/index.php/monetaryactivity/treasury', '2026-10-26', 'Auction cut-off 8.56% on 26 Oct 2026; the next auction (2 Nov 2026) cut off at 8.37%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BD', 1, 'tbond_10y_rate', 0.0927, NULL, 'sourced', 'Bangladesh Bank auctions', 'https://www.bb.org.bd/en/index.php/monetaryactivity/treasury', '2026-10-25', 'Auction cut-off 9.27% on 25 Oct 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BD', 1, 'tbond_5y_rate', 0.0847, NULL, 'sourced', 'Bangladesh Bank auctions', 'https://www.bb.org.bd/en/index.php/monetaryactivity/treasury', '2026-10-14', 'Auction cut-off 8.47% on 14 Oct 2026.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('BE', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"BE","iso3":"BEL","nameEn":"Belgium","nameNative":"België","region":"europe_central_asia","languages":["nl","fr","en","de"],"currency":{"code":"EUR","symbol":"€","decimals":2,"compact":"intl","usdRate":{"value":0.8951,"status":"sourced","sourceName":"European Central Bank, euro reference exchange rate (USD)","sourceUrl":"https://www.ecb.europa.eu/stats/policy_and_exchange_rates/euro_reference_exchange_rates/html/eurofxref-graph-usd.en.html","asOf":"2026-10-30","note":"USD 1.1172 per EUR, so EUR 0.8951 per US dollar; World Bank 2025 average 0.885."}},"instruments":{"savings_account":{"available":true,"localName":"Gereglementeerde spaarrekening","localNameEn":"Regulated savings account","note":"Base rate plus loyalty premium; interest tax-free up to EUR 1,050 a year per person (income year 2025), then 15%.","sourceUrl":"https://data.ecb.europa.eu/data/datasets/MIR/MIR.M.BE.B.L23.D.R.A.2250.EUR.N"},"fdr_3m":{"available":true,"localName":"Termijnrekening","localNameEn":"3-month term deposit","sourceUrl":"https://data.ecb.europa.eu/data/datasets/MIR/MIR.M.BE.B.L22.F.R.A.2250.EUR.N"},"fdr_1y":{"available":true,"localName":"Termijnrekening","localNameEn":"1-year term deposit","sourceUrl":"https://data.ecb.europa.eu/data/datasets/MIR/MIR.M.BE.B.L22.F.R.A.2250.EUR.N"},"dps":{"available":false,"localName":null,"note":"No monthly recurring deposit product; regular saving goes into savings accounts or fund savings plans."},"sanchayapatra_5y":{"available":false,"localName":"Staatsbon","localNameEn":"State Note","note":"State Notes were sold to individuals from time to time (2023-2025), but the Debt Agency''s products for individuals now list only OLOs and Treasury Certificates (checked November 2026).","sourceUrl":null},"tbill_91d":{"available":true,"localName":"Schatkistcertificaat","localNameEn":"Treasury Certificate","note":"3, 6 and 12 months; individuals buy them on the secondary market through a bank.","sourceUrl":"https://www.debtagency.be/en/productctinfo"},"tbond_5y":{"available":true,"localName":"Lineaire obligatie (OLO)","localNameEn":"Linear bond (OLO)","sourceUrl":"https://www.debtagency.be/en/productoloinfo"},"tbond_10y":{"available":true,"localName":"Lineaire obligatie (OLO)","localNameEn":"Linear bond (OLO)","sourceUrl":"https://www.debtagency.be/en/productoloinfo"},"equity_fund":{"available":true,"localName":"Beleggingsfonds","localNameEn":"Investment fund / index fund (ETF)","note":"Retail index funds and ETFs are widely available; stock-exchange tax applies to trades."},"gold":{"available":true,"localName":"Beleggingsgoud","localNameEn":"Investment gold (bars and coins)","note":"Investment gold is VAT-exempt and freely bought."}},"institutions":{"centralBank":{"name":"National Bank of Belgium","url":"https://www.nbb.be/en"},"insuranceRegulator":{"name":"Financial Services and Markets Authority (FSMA); National Bank of Belgium (prudential)","url":"https://www.fsma.be/en"},"insuranceComplaints":{"name":"Ombudsman des Assurances / Ombudsman van de Verzekeringen","url":"https://ombudsman-insurance.be/introduire-une-plainte"},"pensionScheme":{"name":"Federal Pension Service","url":"https://www.sfpd.fgov.be/en/"},"oldAgeAllowance":{"name":"Guaranteed Income for Elderly Persons (GIEP / IGO / GRAPA)","url":"https://www.sfpd.fgov.be/en/entitlement-to-a-pension/giep"},"publicHealthCover":{"name":"INAMI / RIZIV (compulsory health insurance)","url":"https://www.inami.fgov.be/fr"},"depositInsurance":{"name":"Guarantee Fund for Financial Services","url":"https://fondsdegarantie.belgium.be/fr"},"statistics":{"name":"Statbel","url":"https://statbel.fgov.be/en"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BE', 1, 'bank_deposit_avg_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'World Bank FR.INR.DPST has no Belgian series and no all-deposit weighted average was found; the ECB MIR series give 0.07% (overnight), 0.74% (savings) and 2.48% (term up to 1 year) for September 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BE', 1, 'credit_card_rate_cap', 0.0528, NULL, 'sourced', 'ECB MIR statistics: Belgian bank rates on revolving loans, overdrafts and credit card credit to households', 'https://data.ecb.europa.eu/data/datasets/MIR/MIR.M.BE.B.A2Z.A.R.A.2250.EUR.N', '2026-09-30', '5.28% in September 2026 (5.00% in August), an average that includes overdrafts; Belgian law sets maximum annual rates for credit openings (FPS Economy), which could not be read (bot check). Card credit itself usually costs more.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BE', 1, 'deposit_insurance_limit', 100000, NULL, 'sourced', 'European Commission, deposit guarantee schemes', 'https://finance.ec.europa.eu/banking/banking-regulation/deposit-guarantee-schemes_en', '2026-10-31', 'EUR 100,000 per depositor per bank under the EU directive, paid by the Belgian Guarantee Fund for Financial Services.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BE', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Belgian banks do not offer a fixed-rate monthly recurring deposit (DPS-style) product; regular saving goes into regulated savings accounts or fund savings plans.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BE', 1, 'equity_return_base', 0.055, NULL, 'assumption', '3-month treasury certificate 2.6% less 30% tax = 1.8%; BEL 20 price index about 5% a year since 1991', 'https://tradingeconomics.com/belgium/stock-market', '2026-10-31', 'After-tax safe rate of 1.8% plus a 3.7-point premium, kept under the 4-point limit; dividends (taxed at 30%) add to the BEL 20''s roughly 5% a year price gain.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BE', 1, 'equity_return_high', 0.08, NULL, 'assumption', 'BEL 20 long-run record (1,000 in 1991 to 5,841 in Oct 2026) plus dividends', 'https://tradingeconomics.com/belgium/stock-market', '2026-10-31', 'High case near the BEL 20''s long-run total return of about 8% a year.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BE', 1, 'equity_return_low', 0.03, NULL, 'assumption', 'BEL 20 index 5,841 on 30 Oct 2026 (base 1,000 in 1991), up 19% in a year', 'https://tradingeconomics.com/belgium/stock-market', '2026-10-31', 'Low case near the after-tax 10-year OLO yield (about 3.1%), for a decade of weak European stock returns.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BE', 1, 'fdr_1y_rate', 0.0248, NULL, 'sourced', 'ECB MIR statistics: Belgian bank rates on household deposits with agreed maturity up to 1 year (new business)', 'https://data.ecb.europa.eu/data/datasets/MIR/MIR.M.BE.B.L22.F.R.A.2250.EUR.N', '2026-09-30', '2.48% in September 2026 (2.14% in August); 1-2 years 3.11%. Read via the ECB data API.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BE', 1, 'fdr_3m_rate', 0.0248, NULL, 'sourced', 'ECB MIR statistics: Belgian bank rates on household deposits with agreed maturity up to 1 year (new business)', 'https://data.ecb.europa.eu/data/datasets/MIR/MIR.M.BE.B.L22.F.R.A.2250.EUR.N', '2026-09-30', 'No separate 3-month series is published; the up-to-1-year bucket (2.48% in September 2026, 2.14% in August) is used. Read via the ECB data API.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BE', 1, 'fixed_income_return_base', 0.018, NULL, 'assumption', '3-month treasury certificate 2.6% and 1-year term deposit 2.48%, less 30% withholding', 'https://tradingeconomics.com/belgium/3-month-bill-yield', '2026-10-31', 'Base case: short treasury certificates and term deposits after 30% withholding tax (about 1.7-1.8%), with some longer deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BE', 1, 'fixed_income_return_high', 0.03, NULL, 'assumption', '10-year OLO 4.38% less 30% withholding = 3.1%', 'https://tradingeconomics.com/belgium/government-bond-yield', '2026-10-31', 'High case: locking in long OLOs after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BE', 1, 'fixed_income_return_low', 0.012, NULL, 'assumption', 'ECB MIR: savings 0.74% (tax-free to EUR 1,050), term deposits up to 1 year 2.48% less 30% (Sep 2026)', 'https://data.ecb.europa.eu/data/datasets/MIR/MIR.M.BE.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Low case: a mix of regulated savings and short term deposits after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BE', 1, 'goal_inflation_education', 0.03, NULL, 'assumption', 'Eurostat HICP education: 2.2% a year to Sep 2026', 'https://ec.europa.eu/eurostat/databrowser/view/prc_hicp_minr/default/table?lang=en', '2026-10-31', 'Education is mostly publicly funded and its prices track headline inflation, so the 2.5% projection plus half a point for private fees is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BE', 1, 'goal_inflation_health', 0.035, NULL, 'assumption', 'Eurostat HICP health: 3.6% a year to Sep 2026, 12-month average 3.1%', 'https://ec.europa.eu/eurostat/databrowser/view/prc_hicp_minr/default/table?lang=en', '2026-10-31', 'Medical prices have run about a point above headline inflation, so 3.5% is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BE', 1, 'gold_return_base', 0.05, NULL, 'assumption', 'ECB reference rate USD 1.1172 per EUR (30 Oct 2026)', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/euro_reference_exchange_rates/html/eurofxref-graph-usd.en.html', '2026-10-31', 'Long-run dollar gold trend of about 4-5% with no expected trend in the euro against the dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BE', 1, 'gold_return_high', 0.085, NULL, 'assumption', 'ECB reference rate USD 1.1172 per EUR (30 Oct 2026)', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/euro_reference_exchange_rates/html/eurofxref-graph-usd.en.html', '2026-10-31', 'High case with strong dollar gold and a weaker euro.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BE', 1, 'gold_return_low', 0.015, NULL, 'assumption', 'ECB reference rate USD 1.1172 per EUR (30 Oct 2026)', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/euro_reference_exchange_rates/html/eurofxref-graph-usd.en.html', '2026-10-31', 'Low case: weak dollar gold price and a stronger euro.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BE', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No statutory gratuity or end-of-service payment for private employees was found (dismissal brings notice or pay in lieu of notice); not marked absent because no official page confirming this was read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BE', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical out-of-pocket cost for one major private hospital stay was found; the patient''s share depends on room type and supplements, and statutory health insurance pays most of the bill.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BE', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Belgian hospitalisation insurance is priced per plan (room type, age) rather than per sum insured, and no age-banded premium table per EUR 100,000 of cover was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BE', 1, 'inflation_cpi', 0.0526, NULL, 'sourced', 'Trading Economics (Statbel national CPI, October 2026)', 'https://tradingeconomics.com/belgium/inflation-cpi', '2026-10-31', 'Annual CPI 5.26% in October 2026 (4.69% in September); EU HICP 5.2%. Secondary source because statbel.fgov.be served a bot check. Eurostat HICP for September 2026 was 4.5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BE', 1, 'inflation_projection', 0.025, NULL, 'assumption', 'ECB 2% target; Belgian CPI 5.26% (Oct 2026); HICP 12-month average 3.0% (Sep 2026, Eurostat)', 'https://ec.europa.eu/eurostat/databrowser/view/prc_hicp_minr/default/table?lang=en', '2026-10-31', 'Belgium shares the ECB''s credible 2% target but automatic wage indexation keeps its inflation above the euro-area average, so 2.5% is used for planning.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BE', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life (temporary death cover, ''schuldsaldoverzekering'' and ''tijdelijke overlijdensverzekering'') is widely sold, but no published per-1,000 premium table by age was found; insurers quote individually.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BE', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Neither the FSMA, the NBB nor Assuralia publishes an industry-wide life claim settlement ratio that we could find.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BE', 1, 'life_expectancy', 82.3, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=BE', '2024-12-31', 'Men 80.3, women 84.4; UN WPP 2024 (via populationpyramid.net) gives 82.6 for 2026. Latest World Bank year is 2024 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BE', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":25,"men":23.3,"women":26.6},{"age":65,"total":20.9,"men":19.3,"women":22.3},{"age":70,"total":16.9,"men":15.6,"women":18.1},{"age":80,"total":9.6,"men":8.8,"women":10.4}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/belgium/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for the year 2026 (asOf set to mid-year); totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BE', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":67,"womenAge":67,"over90Monthly":null,"meansTested":true}', 'sourced', 'Federal Pension Service, Guaranteed Income for Elderly Persons', 'https://www.sfpd.fgov.be/en/entitlement-to-a-pension/giep', '2026-09-01', 'From the statutory retirement age (67 for anyone born from 1964; 66 for those born 1960-1963), subject to a means test covering pensions, other income, property and savings (savings exempt up to EUR 6,200).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BE', 1, 'old_age_allowance_monthly', 1644.28, NULL, 'sourced', 'Federal Pension Service, Guaranteed Income for Elderly Persons (GIEP/IGO/GRAPA)', 'https://www.sfpd.fgov.be/en/entitlement-to-a-pension/giep', '2026-09-01', 'Gross EUR 1,644.28 a month for a single person (increased basic amount) and EUR 1,096.18 for a cohabitant, at index 186.83 from 1 September 2026; means-tested top-up.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BE', 1, 'oop_health_share', 0.2151, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=BE', '2023-12-31', 'Out-of-pocket share 21.5% of current health expenditure. Latest World Bank year is 2023 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BE', 1, 'policy_rate', 0.025, NULL, 'sourced', 'European Central Bank, deposit facility rate', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.en.html', '2026-10-29', 'ECB held rates on 29 October 2026: deposit facility 2.50%, main refinancing 2.65% (read via the ECB data API, series FM.D.U2.EUR.4F.KR.DFR.LEV).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BE', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":67,"nomineeUntilAge":null,"inflationLinked":true,"taxFree":false}', 'sourced', 'Federal Pension Service, How is the retirement date calculated?', 'https://www.sfpd.fgov.be/en/retirement-age/when', '2026-10-31', 'Earnings-related statutory pension from social security contributions, payable from 67 for anyone born from 1964 (66 for 1960-1963); pensions follow the health index and are taxable. A pension reform agreed by the government is still being legislated.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BE', 1, 'retirement_accumulation_return_base', 0.04, NULL, 'assumption', 'After-tax safe rate about 1.8%; equity base 5.5%', 'https://tradingeconomics.com/belgium/stock-market', '2026-10-31', 'Base case: roughly half shares at 5.5% and half fixed income at about 2.5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BE', 1, 'retirement_accumulation_return_high', 0.055, NULL, 'assumption', 'BEL 20 long-run record; 10-year OLO 4.38%', 'https://tradingeconomics.com/belgium/stock-market', '2026-10-31', 'High case for a growth-leaning balanced mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BE', 1, 'retirement_accumulation_return_low', 0.025, NULL, 'assumption', 'After-tax safe rate about 1.8%; BEL 20 index', 'https://tradingeconomics.com/belgium/stock-market', '2026-10-31', 'Low case for a balanced mix if shares lag.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BE', 1, 'retirement_age_default', 67, NULL, 'sourced', 'Federal Pension Service, How is the retirement date calculated?', 'https://www.sfpd.fgov.be/en/retirement-age/when', '2026-10-31', 'Statutory age is 67 for people born on or after 1 January 1964 (66 for those born 1960-1963, who reach it in 2026); same for men and women. A pension reform agreement is still being legislated.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BE', 1, 'retirement_age_government', 67, NULL, 'sourced', 'Federal Pension Service, How is the retirement date calculated?', 'https://www.sfpd.fgov.be/en/retirement-age/when', '2026-10-31', 'Civil servants'' service ends at the same statutory age: 67 for those born from 1964 (66 for 1960-1963); magistrates and soldiers have their own limits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BE', 1, 'retirement_return_base', 0.015, NULL, 'assumption', '1-year term deposit 2.48% less 30% withholding = 1.7% (Sep 2026)', 'https://data.ecb.europa.eu/data/datasets/MIR/MIR.M.BE.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Base case kept just under the after-tax 1-year term deposit rate (1.7%), allowing for months when deposit rates were lower.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BE', 1, 'retirement_return_high', 0.025, NULL, 'assumption', '10-year OLO 4.38% less 30% withholding = 3.1%', 'https://tradingeconomics.com/belgium/government-bond-yield', '2026-10-31', 'High case: a ladder of OLOs and longer deposits after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BE', 1, 'retirement_return_low', 0.01, NULL, 'assumption', 'ECB MIR: regulated savings 0.74%, term deposits up to 1 year 2.48% less 30% (Sep 2026)', 'https://data.ecb.europa.eu/data/datasets/MIR/MIR.M.BE.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Low case: mostly savings accounts and short deposits after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BE', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Belgian Debt Agency''s products for individuals currently list only OLOs and Treasury Certificates; no State Note (Staatsbon) issue with a current rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BE', 1, 'savings_account_rate', 0.0074, NULL, 'sourced', 'ECB MIR statistics: Belgian bank rates on household deposits redeemable at notice up to 3 months (new business)', 'https://data.ecb.europa.eu/data/datasets/MIR/MIR.M.BE.B.L23.D.R.A.2250.EUR.N', '2026-09-30', 'Regulated savings accounts (base rate plus loyalty premium) are reported in this category; 0.74% in September 2026 (0.72% in August). Ordinary overnight (current) accounts pay 0.07%. Read via the ECB data API.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BE', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":3.02},{"year":2040,"value":2.3},{"year":2065,"value":1.98}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/belgium/2040/', '2025-12-31', '100 / old-age dependency ratio: 33.1 (2025, World Bank), 43.4 (2040) and 50.4 (2065, populationpyramid.net/belgium/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BE', 1, 'tax_bank_interest', 0.3, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Belgium income determination', 'https://taxsummaries.pwc.com/belgium/individual/income-determination', '2026-09-10', '30% withholding tax on interest (term deposits, bonds). Regulated savings accounts: first EUR 1,050 a year per person exempt (income year 2025), then 15%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BE', 1, 'tax_sanchayapatra_profit', 0.3, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Belgium income determination', 'https://taxsummaries.pwc.com/belgium/individual/income-determination', '2026-09-10', 'Government bond and treasury certificate interest falls under the general 30% withholding tax on movable income (the September 2023 one-year State Note was a one-off at 15%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BE', 1, 'tbill_91d_rate', 0.026, NULL, 'sourced', 'Trading Economics, Belgium 3-month treasury certificate yield', 'https://tradingeconomics.com/belgium/3-month-bill-yield', '2026-10-30', 'About 2.60% (the page also shows 2.64%); secondary source because the Debt Agency''s auction statistics were not readable.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BE', 1, 'tbond_10y_rate', 0.0438, NULL, 'sourced', 'Trading Economics, Belgium 10-year government bond (OLO) yield', 'https://tradingeconomics.com/belgium/government-bond-yield', '2026-10-30', 'ECB long-term convergence rate for Belgium was 4.12% in September 2026 (IRS.M.BE.L.L40.CI.0000.EUR.N.Z).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BE', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No Belgian 5-year OLO yield was found on readable pages (Trading Economics shows 2-year 3.31% and 10-year 4.38% on 30 October 2026; worldgovernmentbonds.com did not load data).', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('BF', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"BF","iso3":"BFA","nameEn":"Burkina Faso","nameNative":"Burkina Faso","region":"sub_saharan_africa","languages":["mos","dyu","fr","ff"],"currency":{"code":"XOF","symbol":"F CFA","decimals":0,"compact":"intl","usdRate":{"value":589,"status":"sourced","sourceName":"BCEAO, rates of foreign currencies against the CFA franc for transfers, 30 October 2026","sourceUrl":"https://www.bceao.int/fr/cours/cours-des-devises-contre-Franc-CFA-appliquer-aux-transferts","asOf":"2026-10-30","note":"Mid-point of the buying (585.50) and selling (592.50) rates for the US dollar; the CFA franc is pegged at 655.957 per euro. World Bank 2025 average 581.9. The page is updated daily; on 2 November 2026 it showed 582.50 buying and 589.50 selling (mid 586)."}},"instruments":{"savings_account":{"available":true,"localName":"Compte d''épargne","localNameEn":"Savings account"},"fdr_3m":{"available":true,"localName":"Dépôt à terme","localNameEn":"Term deposit (DAT)","note":"Banks declare minimum and maximum term-deposit rates to the BCEAO twice a year.","sourceUrl":"https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf"},"fdr_1y":{"available":true,"localName":"Dépôt à terme","localNameEn":"Term deposit (DAT), 1 year","note":"Banks declare minimum and maximum term-deposit rates to the BCEAO twice a year.","sourceUrl":"https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf"},"dps":{"available":true,"localName":"Épargne contractuelle","localNameEn":"Contractual savings plan","note":"Monthly savings plans (housing or project savings) offered by banks.","sourceUrl":"https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf"},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate for individuals was found."},"tbill_91d":{"available":false,"localName":null,"localNameEn":null,"note":"Burkina''s Treasury issued only 12-month bills (bons assimilables du Trésor) on the regional market in 2026.","sourceUrl":"https://www.umoatitres.org/fr/pays/burkina/"},"tbond_5y":{"available":true,"localName":"Obligations assimilables du Trésor","localNameEn":"Treasury bonds (OAT)","note":"Auctioned every two weeks by UMOA-Titres in 3, 5 and 7-year lines; individuals buy through banks or licensed brokers (SGI).","sourceUrl":"https://www.umoatitres.org/fr/emission/emission-simultanee-de-bons-et-dobligations-du-tresor-du-burkina-du-07-10-2026/"},"tbond_10y":{"available":false,"localName":null,"localNameEn":null,"note":"No bond longer than 7 years has been auctioned since 2022.","sourceUrl":"https://www.umoatitres.org/fr/pays/burkina/"},"equity_fund":{"available":true,"localName":"OPCVM (FCP, SICAV)","localNameEn":"Collective investment funds","note":"Supervised by the regional financial market authority (AMF-UMOA); equity funds invest on the regional exchange (BRVM)."},"gold":{"available":true,"localName":"Or","localNameEn":"Gold","note":"Burkina is a gold producer; gold is mainly bought as jewellery, bars and coins are uncommon for savers."}},"institutions":{"centralBank":{"name":"Banque Centrale des États de l''Afrique de l''Ouest (BCEAO)","url":"https://www.bceao.int/"},"insuranceRegulator":{"name":"Commission Régionale de Contrôle des Assurances (CIMA)","url":"https://cima-afrique.org/","note":"Regional insurance regulator for the CIMA member states; Burkina''s insurance directorate is in the Ministry of Economy and Finance."},"insuranceComplaints":null,"pensionScheme":{"name":"Caisse Nationale de Sécurité Sociale (CNSS), old-age pension","url":"https://cnssbf.org/la-pension-de-retraite-vieillesse/"},"oldAgeAllowance":null,"publicHealthCover":{"name":"Caisse Nationale d''Assurance Maladie Universelle (CNAMU)","url":"https://www.cnamu.bf/"},"depositInsurance":{"name":"Fonds de Garantie des Dépôts et de Résolution dans l''UMOA (FGDR-UMOA)","url":"https://www.fgd-umoa.org/"},"statistics":{"name":"Institut National de la Statistique et de la Démographie (INSD)","url":"https://www.insd.bf/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BF', 1, 'bank_deposit_avg_rate', 0.0515, NULL, 'sourced', 'BCEAO, monthly economic note for UMOA countries, September 2026 (bank deposit rates, July 2026)', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-07-31', 'Average deposit rate across UMOA banks, 5.15% in July 2026 (5.12% in June); Burkina''s rate fell 0.01 points in the month, but the BCEAO does not publish the country level in this note.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BF', 1, 'credit_card_rate_cap', 0.14, NULL, 'sourced', 'BCEAO, conditions débitrices of UMOA credit institutions, first half 2026 (Burkina Faso)', 'https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf', '2026-06-30', 'Maximum lending rate (taux débiteur maximum) declared by most Burkina banks for the first half of 2026 (range 12-14% at banks); it applies to all bank credit, including cards. No card-specific rate is published.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BF', 1, 'deposit_insurance_limit', 1400000, NULL, 'sourced', 'UMOA Council of Ministers, Decision No. 009 of 30 June 2017 on FGDR-UMOA contribution rates and compensation ceilings', 'https://www.fgd-umoa.org/wp-content/uploads/2024/10/Decision-du-CM-relative-aux-taux-de-contribution-et-aux-plafonds-d-indemnistation-2-1.pdf', '2017-06-30', 'Deposits are guaranteed up to 1,400,000 FCFA per depositor per bank (300,000 FCFA at a microfinance institution) by the regional deposit guarantee fund; the decision dates from 2017 (older than 2025) and is still the one the fund publishes.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BF', 1, 'dps_rate', 0.035, NULL, 'sourced', 'BCEAO, conditions créditrices of UMOA credit institutions, first half 2026 (Burkina Faso)', 'https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf', '2026-06-30', 'Median rate on contractual savings plans (épargne contractuelle) declared by Burkina''s banks in the first half of 2026; most declare 3.50% (range 3.5-5.0%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BF', 1, 'equity_return_base', 0.075, NULL, 'assumption', 'BCEAO monthly economic note, September 2026; UMOA-Titres Burkina auction results', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-10-31', 'Base case: about 3.5 points above after-tax term deposits and 1-year Treasury bills (about 4%), within the 4-point cap; the BRVM''s equity capitalisation rose 65.7% in the year to August 2026 but its 10-year record is uneven.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BF', 1, 'equity_return_high', 0.12, NULL, 'assumption', 'BCEAO monthly economic note, September 2026 (BRVM market capitalisation)', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-10-31', 'High case: the BRVM repeats a strong decade like 2023-2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BF', 1, 'equity_return_low', 0.04, NULL, 'assumption', 'BCEAO monthly economic note, September 2026 (regional stock exchange BRVM, deposit rates)', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-10-31', 'Low case: regional (BRVM) equities return about the bank deposit rate, as in their weak 2016-2020 years.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BF', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The BCEAO bank-conditions survey gives only minimum (median 3.5%) and maximum (median 6.5%, range 5.0-7.5%) term-deposit rates per bank in Burkina for the first half of 2026, not a 1-year rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BF', 1, 'fdr_3m_rate', 0.035, NULL, 'sourced', 'BCEAO, conditions créditrices of UMOA credit institutions, first half 2026 (Burkina Faso)', 'https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf', '2026-06-30', 'Median of the minimum term-deposit rates (taux DAT minimum) that Burkina''s banks declare to the BCEAO, range 2.0-4.5%; the minimum usually applies to small, short deposits. Not a tenor-specific average.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BF', 1, 'fixed_income_return_base', 0.045, NULL, 'assumption', 'BCEAO, conditions créditrices of UMOA credit institutions, first half 2026 (Burkina Faso)', 'https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf', '2026-10-31', 'Base case: larger term deposits (median maximum 6.5%) or 1-year Treasury bills (3.7%) through a bank, less tax on interest, rounded down because the tax rate is unconfirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BF', 1, 'fixed_income_return_high', 0.065, NULL, 'assumption', 'UMOA-Titres, Burkina auction of 7 October 2026 (3-year 7.01%, 5-year 7.44%)', 'https://www.umoatitres.org/fr/emission/emission-simultanee-de-bons-et-dobligations-du-tresor-du-burkina-du-07-10-2026/', '2026-10-31', 'High case: 3-5 year Treasury bonds at about 7%, less a possible tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BF', 1, 'fixed_income_return_low', 0.03, NULL, 'assumption', 'BCEAO, conditions créditrices of UMOA credit institutions, first half 2026 (Burkina Faso)', 'https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf', '2026-10-31', 'Low case: small term deposits or contractual savings at the 3.5% floor rate, less a possible tax on interest.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BF', 1, 'goal_inflation_education', 0.04, NULL, 'assumption', 'BCEAO monthly economic note, September 2026; inflation assumption 2%', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-10-31', 'No reliable national education CPI series was read; private school fees usually rise faster than general prices, so 2 points above the 2% inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BF', 1, 'goal_inflation_health', 0.035, NULL, 'assumption', 'BCEAO monthly economic note, September 2026; inflation assumption 2%', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-10-31', 'No reliable national medical CPI series was read; private medical costs usually rise faster than general prices, so 1.5 points above the 2% inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BF', 1, 'gold_return_base', 0.045, NULL, 'assumption', 'BCEAO exchange rates (CFA franc pegged at 655.957 per euro)', 'https://www.bceao.int/fr/cours/cours-des-devises-contre-Franc-CFA-appliquer-aux-transferts', '2026-10-31', 'Base case: the long-run dollar gold trend of about 4% a year plus a small allowance for the euro-pegged franc weakening against the dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BF', 1, 'gold_return_high', 0.08, NULL, 'assumption', 'BCEAO exchange rates', 'https://www.bceao.int/fr/cours/cours-des-devises-contre-Franc-CFA-appliquer-aux-transferts', '2026-10-31', 'High case: strong gold years such as 2024-2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BF', 1, 'gold_return_low', 0, NULL, 'assumption', 'BCEAO exchange rates (CFA franc pegged to the euro)', 'https://www.bceao.int/fr/cours/cours-des-devises-contre-Franc-CFA-appliquer-aux-transferts', '2026-10-31', 'Low case: flat gold in euro terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BF', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No official text on a statutory end-of-service or retirement indemnity for private employees in Burkina Faso could be read (the Labour Code was not reached).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BF', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a major private hospital stay in Burkina Faso was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BF', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premiums by age were found from a public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BF', 1, 'inflation_cpi', 0.03, NULL, 'sourced', 'BCEAO, monthly economic note for UMOA countries, September 2026 (harmonised consumer prices, August 2026)', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-08-31', 'Consumer prices up 3.0% year on year in Burkina in August 2026 after 2.3% in July (INSD data via BCEAO); 2025 average -0.6% (World Bank).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BF', 1, 'inflation_projection', 0.02, NULL, 'assumption', 'BCEAO inflation target (1-3% band, centre 2%); Burkina CPI 3.0% in August 2026', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-10-31', 'Inflation swings with harvests but averages near the BCEAO band and the CFA franc is pegged to the euro, so the 2% centre of the 1-3% target band is used for long-range plans.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BF', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Temporary death cover is sold under the CIMA code, but no published premium rates per 1,000 FCFA of cover by age were found from a public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BF', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'CIMA (the regional insurance regulator) and Burkina''s insurance directorate publish no industry-wide life claim settlement ratio that could be found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BF', 1, 'life_expectancy', 61.292, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN), Burkina Faso', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=BF', '2024-12-31', '61.3 years in 2024 (men 59.1, women 63.4).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BF', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":15.7,"men":14.9,"women":16.5},{"age":65,"total":12.3,"men":11.7,"women":12.9},{"age":70,"total":9.3,"men":8.8,"women":9.7},{"age":80,"total":4.7,"men":4.5,"women":4.9}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/burkina-faso/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026; the page gives men and women only, so totals are the mean of the two.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BF', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension was found (see old_age_allowance_monthly).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BF', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension for Burkina Faso was found; the CNSS and CARFO ''allocation de vieillesse'' is a contributory lump sum for people with under 15 years of contributions, not a social pension.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BF', 1, 'oop_health_share', 0.4382, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), Burkina Faso', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=BF', '2023-12-31', '43.8% in 2023 (WHO Global Health Expenditure Database); older than 2025, the latest available.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BF', 1, 'policy_rate', 0.03, NULL, 'sourced', 'BCEAO, monthly economic note for UMOA countries, September 2026 (Monetary Policy Committee of 9 September 2026)', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-09-09', 'Main policy rate (rate at which the BCEAO refinances banks) 3.00%, left unchanged by the 9 September 2026 committee; the marginal lending facility rate is 5.00%. Common to all eight UMOA countries. The previously cited BCEAO key-rates page now returns 404.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BF', 1, 'public_pension_scheme', NULL, '{"pensionFromAge":58,"entryAgeMin":null,"entryAgeMax":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'CNSS Burkina Faso, old-age pension (pension de vieillesse)', 'https://cnssbf.org/la-pension-de-retraite-vieillesse/', '2026-10-31', 'Compulsory CNSS pension for private employees after at least 15 years of contributions, from 56, 58 or 60 depending on job category (58 used); voluntary insured persons from 56. The page gives no benefit formula or indexation rule, so inflationLinked is false (no automatic indexation found); a lump-sum allocation is paid to those with under 15 years.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BF', 1, 'retirement_accumulation_return_base', 0.06, NULL, 'assumption', 'UMOA-Titres Burkina auction results; equity base 7.5%; gold base 4.5%', 'https://www.umoatitres.org/fr/emission/emission-simultanee-de-bons-et-dobligations-du-tresor-du-burkina-du-07-10-2026/', '2026-10-31', 'Base case: a balanced mix of deposits or Treasury bonds, regional equity funds and some gold.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BF', 1, 'retirement_accumulation_return_high', 0.08, NULL, 'assumption', 'UMOA-Titres Burkina auction results; equity high 12%', 'https://www.umoatitres.org/fr/emission/emission-simultanee-de-bons-et-dobligations-du-tresor-du-burkina-du-07-10-2026/', '2026-10-31', 'High case: a growth-leaning mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BF', 1, 'retirement_accumulation_return_low', 0.035, NULL, 'assumption', 'BCEAO, conditions créditrices of UMOA credit institutions, first half 2026 (Burkina Faso)', 'https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf', '2026-10-31', 'Low case: a mix earning about after-tax deposit rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BF', 1, 'retirement_age_default', 58, NULL, 'sourced', 'CNSS Burkina Faso, old-age pension (pension de vieillesse)', 'https://cnssbf.org/la-pension-de-retraite-vieillesse/', '2026-10-31', 'Pension age is set by decree by job category: 56 for manual workers, 58 for employees, 60 for supervisors and managers, 63 for doctors and university teachers; at least 15 years of contributions. 58 (employees) is used; no newer rule for people born after 1975 was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BF', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'CARFO (the civil-service pension fund) describes the pension as due at the statutory age limit but does not state it, and the public service statute could not be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BF', 1, 'retirement_return_base', 0.035, NULL, 'assumption', 'UMOA-Titres, Burkina auction of 7 October 2026 (12-month bill 3.73%)', 'https://www.umoatitres.org/fr/emission/emission-simultanee-de-bons-et-dobligations-du-tresor-du-burkina-du-07-10-2026/', '2026-10-31', 'Base case: about the 1-year Treasury bill yield (3.73%) and small term-deposit rates; not above the safe rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BF', 1, 'retirement_return_high', 0.055, NULL, 'assumption', 'UMOA-Titres, Burkina auction of 7 October 2026 (3-year bond 7.01%)', 'https://www.umoatitres.org/fr/emission/emission-simultanee-de-bons-et-dobligations-du-tresor-du-burkina-du-07-10-2026/', '2026-10-31', 'High case: part of the money in larger term deposits or short Treasury bonds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BF', 1, 'retirement_return_low', 0.03, NULL, 'assumption', 'BCEAO, conditions créditrices of UMOA credit institutions, first half 2026 (Burkina Faso)', 'https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf', '2026-10-31', 'Low case: small term deposits or contractual savings at about 3.5%, less a possible tax on interest.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BF', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate sold to individuals was found; the Treasury borrows through UMOA-Titres auctions of 12-month bills and 3-7 year bonds, open to individuals through banks and brokers.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BF', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No average rate on ordinary savings accounts in Burkina was found; the BCEAO bank-conditions survey (first half 2026) lists term-deposit and contractual-savings rates only.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BF', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":20.92},{"year":2040,"value":17.86},{"year":2065,"value":9.9}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/burkina-faso/2040/', '2025-12-31', '100 / old-age dependency ratio: 4.78 (2025, World Bank), 5.6 (2040) and 10.1 (2065, populationpyramid.net/burkina-faso/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BF', 1, 'tax_bank_interest', NULL, NULL, 'missing', '', '', '2026-10-31', 'The tax authority site could not be reached and PwC Tax Summaries has no Burkina Faso page, so the withholding rate on bank interest could not be confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BF', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate exists, and the tax treatment of interest on Burkina Treasury securities for individuals could not be confirmed from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BF', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Burkina''s Treasury issued only 12-month bills on the regional market in 2026 (last: 3.73% yield on 7 October 2026); no 3-month bill rate exists.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BF', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Burkina has not auctioned bonds longer than 7 years since 2022 (7-year yield 7.39% on 7 October 2026); the UMOA-Titres curve''s 10-year point (5.9% zero coupon) rests on few trades and is not used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BF', 1, 'tbond_5y_rate', 0.0744, NULL, 'sourced', 'UMOA-Titres, Burkina Treasury auction of 7 October 2026 (5-year bond)', 'https://www.umoatitres.org/fr/emission/emission-simultanee-de-bons-et-dobligations-du-tresor-du-burkina-du-07-10-2026/', '2026-10-07', 'Weighted average yield 7.44% on the 6.20% bond maturing 8 October 2031; the UMOA-Titres zero-coupon curve of 23 October 2026 gives 7.58% at 5 years.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('BG', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"BG","iso3":"BGR","nameEn":"Bulgaria","nameNative":"България","region":"europe_central_asia","languages":["bg","en","ru","tr"],"currency":{"code":"EUR","symbol":"€","decimals":2,"compact":"intl","usdRate":{"value":0.8951,"status":"sourced","sourceName":"European Central Bank, euro reference exchange rate (USD)","sourceUrl":"https://www.ecb.europa.eu/stats/policy_and_exchange_rates/euro_reference_exchange_rates/html/eurofxref-graph-usd.en.html","asOf":"2026-10-30","note":"Bulgaria replaced the lev (BGN) with the euro on 1 January 2026 at BGN 1.95583 per euro (CLDR still lists BGN). USD 1.1172 per EUR, so EUR 0.8951 per US dollar."}},"instruments":{"savings_account":{"available":true,"localName":"Спестовна сметка","localNameEn":"Savings account","sourceUrl":"https://data.ecb.europa.eu/data/datasets/MIR/MIR.M.BG.B.L23.D.R.A.2250.EUR.N"},"fdr_3m":{"available":true,"localName":"Срочен депозит","localNameEn":"3-month term deposit","sourceUrl":"https://data.ecb.europa.eu/data/datasets/MIR/MIR.M.BG.B.L22.F.R.A.2250.EUR.N"},"fdr_1y":{"available":true,"localName":"Срочен депозит","localNameEn":"1-year term deposit","sourceUrl":"https://data.ecb.europa.eu/data/datasets/MIR/MIR.M.BG.B.L22.F.R.A.2250.EUR.N"},"dps":{"available":false,"localName":null,"note":"No standard fixed-rate monthly recurring deposit product was found."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":"Government savings bond","note":"No government savings bond sold to individuals was found."},"tbill_91d":{"available":false,"localName":"Краткосрочни ДЦК","localNameEn":"Short-term government securities","note":"No regular 3-month treasury bill issuance was found."},"tbond_5y":{"available":true,"localName":"Държавни ценни книжа (ДЦК)","localNameEn":"Government bond","note":"Sold at BNB auctions through primary dealers; individuals can buy through banks."},"tbond_10y":{"available":true,"localName":"Държавни ценни книжа (ДЦК)","localNameEn":"Government bond","sourceUrl":"https://data.ecb.europa.eu/data/datasets/IRS/IRS.M.BG.L.L40.CI.0000.EUR.N.Z"},"equity_fund":{"available":true,"localName":"Договорен фонд","localNameEn":"Mutual fund / index fund (ETF)","note":"Local mutual funds and EU-listed index funds are available; capital gains on EU/EEA regulated markets are tax-exempt."},"gold":{"available":true,"localName":"Инвестиционно злато","localNameEn":"Investment gold (bars and coins)","note":"Investment gold is VAT-exempt and freely bought."}},"institutions":{"centralBank":{"name":"Bulgarian National Bank","url":"https://www.bnb.bg/"},"insuranceRegulator":{"name":"Financial Supervision Commission","url":"https://www.fsc.bg/en/"},"insuranceComplaints":{"name":"Financial Supervision Commission (complaints against insurers)","url":"https://www.fsc.bg/en/"},"pensionScheme":{"name":"National Social Security Institute (NOI)","url":"https://nssi.bg/"},"oldAgeAllowance":{"name":"Social old-age pension (NOI)","url":"https://nssi.bg/fizicheski-lica/pensii-bg/nesvyrzani-s-trudovata-deinost/socialna-pensiya-za-starost/"},"publicHealthCover":{"name":"National Health Insurance Fund (NHIF)","url":"https://www.nhif.bg/"},"depositInsurance":{"name":"Bulgarian Deposit Insurance Fund","url":"https://www.dif.bg/en"},"statistics":{"name":"National Statistical Institute","url":"https://www.nsi.bg/en"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BG', 1, 'bank_deposit_avg_rate', 0.0025, NULL, 'sourced', 'World Bank WDI FR.INR.DPST (deposit interest rate)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=BG', '2025-12-31', '0.25% in 2025, weighted towards current accounts; ECB MIR new-business term deposits up to 1 year paid 1.49% in September 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BG', 1, 'credit_card_rate_cap', 0.1351, NULL, 'sourced', 'ECB MIR statistics: Bulgarian bank rates on revolving loans, overdrafts and credit card credit to households', 'https://data.ecb.europa.eu/data/datasets/MIR/MIR.M.BG.B.A2Z.A.R.A.2250.EUR.N', '2026-09-30', '13.51% in September 2026 (13.49% in August), an average that includes overdrafts; no specific legal cap on card rates was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BG', 1, 'deposit_insurance_limit', 100000, NULL, 'sourced', 'Bulgarian Deposit Insurance Fund', 'https://www.dif.bg/en', '2026-10-31', 'EUR 100,000 per depositor per bank; up to EUR 125,000 for three months for certain deposits (home sale proceeds, insurance pay-outs, life events).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BG', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published rate for a monthly recurring deposit product at Bulgarian banks was found; the ECB MIR statistics do not separate such products.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BG', 1, 'equity_return_base', 0.05, NULL, 'assumption', '1-year term deposit 1.49% (tax-free, Sep 2026); SOFIX record since 2000', 'https://tradingeconomics.com/bulgaria/stock-market', '2026-10-31', 'After-tax safe rate of about 1.5% plus a 3.5-point premium, kept modest because SOFIX has a weak record since 2007; diversified euro-area funds give similar euro returns.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BG', 1, 'equity_return_high', 0.08, NULL, 'assumption', 'SOFIX long-run record (100 in 2000 to 1,838 in Oct 2026)', 'https://tradingeconomics.com/bulgaria/stock-market', '2026-10-31', 'High case near long-run euro-area and global equity returns in euro terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BG', 1, 'equity_return_low', 0.025, NULL, 'assumption', 'SOFIX 1,838 on 29 Oct 2026 (base 100 in 2000), still below its October 2007 high of 1,982', 'https://tradingeconomics.com/bulgaria/stock-market', '2026-10-31', 'Low case for a small, illiquid market whose index has made no gain since 2007 despite a 72% rise in the past year.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BG', 1, 'fdr_1y_rate', 0.0149, NULL, 'sourced', 'ECB MIR statistics: Bulgarian bank rates on household deposits with agreed maturity up to 1 year (new business)', 'https://data.ecb.europa.eu/data/datasets/MIR/MIR.M.BG.B.L22.F.R.A.2250.EUR.N', '2026-09-30', '1.49% in September 2026 (1.40% in August); 1-2 years 1.60%, over 2 years 2.86%. Read via the ECB data API.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BG', 1, 'fdr_3m_rate', 0.0149, NULL, 'sourced', 'ECB MIR statistics: Bulgarian bank rates on household deposits with agreed maturity up to 1 year (new business)', 'https://data.ecb.europa.eu/data/datasets/MIR/MIR.M.BG.B.L22.F.R.A.2250.EUR.N', '2026-09-30', 'No separate 3-month series is published; the up-to-1-year bucket (1.49% in September 2026, 1.40% in August) is used. Read via the ECB data API.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BG', 1, 'fixed_income_return_base', 0.018, NULL, 'assumption', 'ECB MIR: term deposits up to 1 year 1.49%, 1-2 years 1.60%, over 2 years 2.86% (tax-free, Sep 2026)', 'https://data.ecb.europa.eu/data/datasets/MIR/MIR.M.BG.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Base case: a mix of 1-year and longer term deposits, with no tax on EU bank interest.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BG', 1, 'fixed_income_return_high', 0.035, NULL, 'assumption', '10-year government bond 4.09% (tax-free)', 'https://data.ecb.europa.eu/data/datasets/IRS/IRS.M.BG.L.L40.CI.0000.EUR.N.Z', '2026-10-31', 'High case: holding long government bonds, whose interest is tax-exempt.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BG', 1, 'fixed_income_return_low', 0.008, NULL, 'assumption', 'ECB MIR: savings 0.43%, term deposits up to 1 year 1.49% (interest tax-free, Sep 2026)', 'https://data.ecb.europa.eu/data/datasets/MIR/MIR.M.BG.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Low case: savings accounts and short deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BG', 1, 'goal_inflation_education', 0.05, NULL, 'assumption', 'Eurostat HICP education: 7.7% a year to Sep 2026, 12-month average 8.7%', 'https://ec.europa.eu/eurostat/databrowser/view/prc_hicp_minr/default/table?lang=en', '2026-10-31', 'Education prices have risen far faster than headline inflation, so 5% is used, between the projection and recent rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BG', 1, 'goal_inflation_health', 0.035, NULL, 'assumption', 'Eurostat HICP health: 3.0% a year to Sep 2026', 'https://ec.europa.eu/eurostat/databrowser/view/prc_hicp_minr/default/table?lang=en', '2026-10-31', 'Medical prices rose 3.0% in the year to September 2026; the 3% projection plus half a point is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BG', 1, 'gold_return_base', 0.05, NULL, 'assumption', 'ECB reference rate USD 1.1172 per EUR (30 Oct 2026)', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/euro_reference_exchange_rates/html/eurofxref-graph-usd.en.html', '2026-10-31', 'Long-run dollar gold trend of about 4-5% with no expected trend in the euro against the dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BG', 1, 'gold_return_high', 0.085, NULL, 'assumption', 'ECB reference rate USD 1.1172 per EUR (30 Oct 2026)', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/euro_reference_exchange_rates/html/eurofxref-graph-usd.en.html', '2026-10-31', 'High case with strong dollar gold and a weaker euro.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BG', 1, 'gold_return_low', 0.015, NULL, 'assumption', 'ECB reference rate USD 1.1172 per EUR (30 Oct 2026)', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/euro_reference_exchange_rates/html/eurofxref-graph-usd.en.html', '2026-10-31', 'Low case: weak dollar gold price and a stronger euro.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BG', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No statutory end-of-service payment expressed in days of wages per year of service was found. The Labour Code is reported to give a lump-sum payment of gross monthly wages when employment ends after the right to a pension is acquired, which does not fit the days-per-year shape, and it could not be read from an official page (lex.bg returned 403).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BG', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical out-of-pocket cost for one major private hospital stay was found; the National Health Insurance Fund pays for covered treatment with patient co-payments and extra fees at private hospitals.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BG', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Voluntary health insurance in Bulgaria is sold as plan packages, and no age-banded premium table per EUR 100,000 of cover was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BG', 1, 'inflation_cpi', 0.057, NULL, 'sourced', 'Trading Economics (NSI national CPI, September 2026)', 'https://tradingeconomics.com/bulgaria/inflation-cpi', '2026-09-30', 'Annual CPI 5.7% in September 2026 (5.1% in August); HICP 5.6% (Eurostat). Secondary source for the NSI release.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BG', 1, 'inflation_projection', 0.03, NULL, 'assumption', 'ECB 2% target (Bulgaria in the euro area since January 2026); HICP 5.6% (Sep 2026), 12-month average 4.2%', 'https://ec.europa.eu/eurostat/databrowser/view/prc_hicp_minr/default/table?lang=en', '2026-10-31', 'The ECB target anchors the long run, but price-level catch-up with richer euro members keeps Bulgarian inflation higher, so 3% is used for planning.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BG', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life cover is sold, but no published per-1,000 premium table by age was found; insurers quote individually.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BG', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Financial Supervision Commission publishes premiums and claims paid but no industry-wide life claim settlement ratio that we could find.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BG', 1, 'life_expectancy', 75.76, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=BG', '2024-12-31', 'Men 72.2, women 79.5; UN WPP 2024 (via populationpyramid.net) gives 76.1 for 2026. Latest World Bank year is 2024 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BG', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":20.3,"men":18,"women":22.6},{"age":65,"total":16.8,"men":14.8,"women":18.5},{"age":70,"total":13.3,"men":11.9,"women":14.6},{"age":80,"total":7.3,"men":6.7,"women":7.8}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/bulgaria/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for the year 2026 (asOf set to mid-year); totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BG', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":70,"womenAge":70,"over90Monthly":null,"meansTested":true}', 'sourced', 'National Social Security Institute (NOI), social old-age pension', 'https://nssi.bg/fizicheski-lica/pensii-bg/nesvyrzani-s-trudovata-deinost/socialna-pensiya-za-starost/', '2026-07-01', 'From age 70; the person''s family income per member over the past year must be below 30% of the poverty line (EUR 390.63 a month in 2026), and the person may not receive any other pension.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BG', 1, 'old_age_allowance_monthly', 183.81, NULL, 'sourced', 'National Social Security Institute (NOI), social old-age pension', 'https://nssi.bg/fizicheski-lica/pensii-bg/nesvyrzani-s-trudovata-deinost/socialna-pensiya-za-starost/', '2026-07-01', 'EUR 183.81 a month from 1 July 2026 (EUR 170.51 from 1 January 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BG', 1, 'oop_health_share', 0.355, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=BG', '2023-12-31', 'Out-of-pocket share 35.5% of current health expenditure. Latest World Bank year is 2023 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BG', 1, 'policy_rate', 0.025, NULL, 'sourced', 'European Central Bank, deposit facility rate', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.en.html', '2026-10-29', 'Bulgaria adopted the euro on 1 January 2026, so ECB rates apply: deposit facility 2.50%, main refinancing 2.65%, held on 29 October 2026 (read via the ECB data API).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BG', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":65,"nomineeUntilAge":null,"inflationLinked":true,"taxFree":null}', 'sourced', 'National Social Security Institute (NOI), pension conditions and calculation', 'https://nssi.bg/fizicheski-lica/pensii-bg/trudova-deinost-pridobivane-pravo/razmer-na-pensiite/', '2026-07-01', 'Pay-as-you-go state pension: average insured income x individual coefficient x 1.35% per year of insurance; pension age 65 for both sexes for anyone born after 1975 (64 y 9 m for men and 62 y 6 m for women in 2026). Minimum pension EUR 322.37 to 30 June 2026 and EUR 347.51 from 1 July 2026. Pensions are raised every 1 July under the Social Insurance Code (the cited page does not describe the indexation formula). Workers born after 1959 also pay into a universal pension fund (second pillar).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BG', 1, 'retirement_accumulation_return_base', 0.035, NULL, 'assumption', '1-year term deposit 1.49%; equity base 5%; 10-year bond 4.09%', 'https://tradingeconomics.com/bulgaria/stock-market', '2026-10-31', 'Base case: roughly half shares at 5% and half fixed income at about 2%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BG', 1, 'retirement_accumulation_return_high', 0.055, NULL, 'assumption', 'SOFIX record; 10-year government bond 4.09%', 'https://tradingeconomics.com/bulgaria/stock-market', '2026-10-31', 'High case for a growth-leaning balanced mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BG', 1, 'retirement_accumulation_return_low', 0.02, NULL, 'assumption', '1-year term deposit 1.49%; SOFIX index', 'https://tradingeconomics.com/bulgaria/stock-market', '2026-10-31', 'Low case for a balanced mix if shares lag.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BG', 1, 'retirement_age_default', 65, NULL, 'sourced', 'National Social Security Institute (NOI), pension for insurance length and age', 'https://nssi.bg/fizicheski-lica/pensii-bg/trudova-deinost-pridobivane-pravo/pensii-za-osig-staj-v-namalen-razmer/', '2026-01-01', 'Rises to 65 for both men and women (men in 2029, women in 2037), so 65 applies to anyone born after 1975; after 2037 it is to be linked to life expectancy. In 2026: men 64 years 9 months with 39 years 10 months of insurance, women 62 years 6 months with 36 years 10 months.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BG', 1, 'retirement_age_government', 65, NULL, 'sourced', 'National Social Security Institute (NOI), pension for insurance length and age', 'https://nssi.bg/fizicheski-lica/pensii-bg/trudova-deinost-pridobivane-pravo/pensii-za-osig-staj-v-namalen-razmer/', '2026-01-01', 'Civil servants retire under the general pension age, 65 for both sexes for anyone born after 1975 (men 64 y 9 m, women 62 y 6 m in 2026); military, police and some other groups have lower ages.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BG', 1, 'retirement_return_base', 0.014, NULL, 'assumption', '1-year term deposit 1.49% (tax-free, Sep 2026)', 'https://data.ecb.europa.eu/data/datasets/MIR/MIR.M.BG.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Base case kept just under the 1-year term deposit rate, which is untaxed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BG', 1, 'retirement_return_high', 0.03, NULL, 'assumption', '10-year government bond 4.09%; deposits over 2 years 2.86% (tax-free)', 'https://data.ecb.europa.eu/data/datasets/IRS/IRS.M.BG.L.L40.CI.0000.EUR.N.Z', '2026-10-31', 'High case: a ladder of government bonds and long deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BG', 1, 'retirement_return_low', 0.008, NULL, 'assumption', 'ECB MIR: savings 0.43%, term deposits up to 1 year 1.49% (tax-free, Sep 2026)', 'https://data.ecb.europa.eu/data/datasets/MIR/MIR.M.BG.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Low case: mostly savings accounts and short deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BG', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings bond for individuals with a current rate was found; the Ministry of Finance site refused automated access.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BG', 1, 'savings_account_rate', 0.0043, NULL, 'sourced', 'ECB MIR statistics: Bulgarian bank rates on household deposits redeemable at notice up to 3 months (new business)', 'https://data.ecb.europa.eu/data/datasets/MIR/MIR.M.BG.B.L23.D.R.A.2250.EUR.N', '2026-09-30', '0.43% in September 2026 (0.41% in August); overnight (current) deposits pay about 0.01%. Read via the ECB data API.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BG', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":2.85},{"year":2040,"value":2.31},{"year":2065,"value":1.85}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/bulgaria/2040/', '2025-12-31', '100 / old-age dependency ratio: 35.1 (2025, World Bank), 43.2 (2040) and 54.1 (2065, populationpyramid.net/bulgaria/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BG', 1, 'tax_bank_interest', 0, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Bulgaria income determination', 'https://taxsummaries.pwc.com/bulgaria/individual/income-determination', '2026-08-02', 'Interest on bank accounts in the EU/EEA is tax-free since 1 April 2022; accounts outside the EU/EEA are taxed at 10%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BG', 1, 'tax_sanchayapatra_profit', 0, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Bulgaria income determination', 'https://taxsummaries.pwc.com/bulgaria/individual/income-determination', '2026-08-02', 'Interest and discounts on bonds are exempt income for individuals (subject to conditions in the law).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BG', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No current 3-month Bulgarian treasury bill yield was found; government securities auctions are mainly for bonds and the Ministry of Finance site refused automated access.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BG', 1, 'tbond_10y_rate', 0.0409, NULL, 'sourced', 'ECB long-term interest rate for convergence purposes, Bulgaria (10-year government bond)', 'https://data.ecb.europa.eu/data/datasets/IRS/IRS.M.BG.L.L40.CI.0000.EUR.N.Z', '2026-09-30', 'Monthly average for September 2026, read via the ECB data API; Trading Economics'' Bulgarian quote was stale (February 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BG', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No Bulgarian 5-year government bond yield was found on readable pages (Trading Economics shows only a stale 10-year quote).', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('BH', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"BH","iso3":"BHR","nameEn":"Bahrain","nameNative":"البحرين","region":"middle_east_north_africa","languages":["ar","en","ml"],"currency":{"code":"BHD","symbol":"BD","decimals":3,"compact":"intl","usdRate":{"value":0.376,"status":"sourced","sourceName":"Central Bank of Bahrain, Monthly Statistical Bulletin, August 2026, Table 6 (BD exchange rates against selected currencies)","sourceUrl":"https://www.cbb.gov.bh/wp-content/uploads/2026/09/Aug-2026.pdf","asOf":"2026-08-31","note":"The dinar is pegged at 0.376 per US dollar, unchanged in every period of the table; World Bank PA.NUS.FCRF 2025 also 0.376. CLDR gives no narrow symbol; ''BD'' is the usual local abbreviation."}},"instruments":{"savings_account":{"available":true,"localName":"حساب توفير","localNameEn":"Savings account","note":"Savings accounts pay very little (0.18% on average in August 2026).","sourceUrl":"https://www.cbb.gov.bh/wp-content/uploads/2026/09/Aug-2026.pdf"},"fdr_3m":{"available":true,"localName":"وديعة لأجل (3 أشهر)","localNameEn":"Time deposit (3 months)","note":"Deposits are protected up to BD 20,000 per person per bank."},"fdr_1y":{"available":true,"localName":"وديعة لأجل (سنة)","localNameEn":"Time deposit (1 year)"},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No standard monthly recurring deposit product was found."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate for individuals was found."},"tbill_91d":{"available":true,"localName":"أذونات الخزانة","localNameEn":"Treasury bills","note":"91-day bills are auctioned weekly by the CBB to eligible institutions; individuals can take part through their retail banks or Bahrain Bourse. Al Salam sukuk are also issued monthly.","sourceUrl":"https://www.cbb.gov.bh/government-securities/"},"tbond_5y":{"available":true,"localName":"سندات التنمية الحكومية","localNameEn":"Government development bonds","note":"Issued in dinars and US dollars, mainly bought by institutions.","sourceUrl":"https://www.cbb.gov.bh/government-securities/"},"tbond_10y":{"available":true,"localName":"سندات التنمية الحكومية","localNameEn":"Government development bonds","note":"Issued in dinars and US dollars, mainly bought by institutions.","sourceUrl":"https://www.cbb.gov.bh/government-securities/"},"equity_fund":{"available":true,"localName":"صناديق الاستثمار","localNameEn":"Mutual funds","note":"The CBB bulletin counts 1,683 mutual funds registered in Bahrain in Q2 2026, with USD 11.5 billion invested.","sourceUrl":"https://www.cbb.gov.bh/wp-content/uploads/2026/09/Aug-2026.pdf"},"gold":{"available":true,"localName":"الذهب","localNameEn":"Gold","note":"Gold bars, coins and jewellery are freely sold."}},"institutions":{"centralBank":{"name":"Central Bank of Bahrain (CBB)","url":"https://www.cbb.gov.bh/"},"insuranceRegulator":{"name":"Central Bank of Bahrain, insurance supervision","url":"https://www.cbb.gov.bh/insurance/"},"insuranceComplaints":{"name":"Central Bank of Bahrain, consumer complaints","url":"https://www.cbb.gov.bh/complaint-form/"},"pensionScheme":{"name":"Social Insurance Organization (SIO)","url":"https://www.sio.gov.bh/"},"oldAgeAllowance":null,"publicHealthCover":{"name":"Ministry of Health (public health care for citizens)","url":"https://www.moh.gov.bh/"},"depositInsurance":{"name":"Deposit & Unrestricted Investment Accounts Protection Scheme, Central Bank of Bahrain","url":"https://www.cbb.gov.bh/consumer-information/"},"statistics":{"name":"Information & eGovernment Authority (iGA)","url":"https://www.iga.gov.bh/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BH', 1, 'bank_deposit_avg_rate', 0.0263, NULL, 'sourced', 'Central Bank of Bahrain, Monthly Statistical Bulletin, August 2026, banking indicators (average interest rate on deposits, 6-12 months)', 'https://www.cbb.gov.bh/wp-content/uploads/2026/09/Aug-2026.pdf', '2026-06-30', 'Quarterly average rate on 6-12 month deposits, 2.63% in Q2 2026 (2.00% in Q1); no weighted average over all deposits is published. World Bank FR.INR.DPST stops in 2015.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BH', 1, 'credit_card_rate_cap', 0.2077, NULL, 'sourced', 'Central Bank of Bahrain, Monthly Statistical Bulletin, August 2026, Table 7 (conventional retail banks, credit cards)', 'https://www.cbb.gov.bh/wp-content/uploads/2026/09/Aug-2026.pdf', '2026-08-31', 'Average interest rate on credit card balances at conventional retail banks, 20.77% in August 2026; no legal cap was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BH', 1, 'deposit_insurance_limit', 20000, NULL, 'sourced', 'Central Bank of Bahrain, Consumer information: Deposit & URIA Protection Scheme', 'https://www.cbb.gov.bh/consumer-information/', '2026-10-31', 'Eligible individual account holders are covered up to BD 20,000 of their total eligible accounts per bank (conventional deposits and Islamic unrestricted investment accounts), replacing the earlier lower of 75% or BD 15,000.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BH', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No industry-wide rate for a monthly recurring deposit product was found in the CBB statistics.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BH', 1, 'equity_return_base', 0.075, NULL, 'assumption', 'CBB 91-day Treasury bill yield 5.28%; 1-year deposit 2.64%', 'https://www.cbb.gov.bh/wp-content/uploads/2026/09/Aug-2026.pdf', '2026-10-31', 'Base case: about 2 points above the Treasury bill yield, within the 4-point cap, because the Bahrain All Share index has had only a moderate, dividend-driven 10-year record.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BH', 1, 'equity_return_high', 0.1, NULL, 'assumption', 'CBB 91-day Treasury bill yield 5.28%', 'https://www.cbb.gov.bh/wp-content/uploads/2026/09/Aug-2026.pdf', '2026-10-31', 'High case: a stronger equity premium similar to other Gulf markets.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BH', 1, 'equity_return_low', 0.04, NULL, 'assumption', 'CBB 91-day Treasury bill yield 5.28% (August 2026)', 'https://www.cbb.gov.bh/wp-content/uploads/2026/09/Aug-2026.pdf', '2026-10-31', 'Low case: the local market, dominated by a few banks, returns less than Treasury bills.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BH', 1, 'fdr_1y_rate', 0.0264, NULL, 'sourced', 'Central Bank of Bahrain, Monthly Statistical Bulletin, August 2026, Table 7 (BD time deposits, 6-12 months)', 'https://www.cbb.gov.bh/wp-content/uploads/2026/09/Aug-2026.pdf', '2026-08-31', 'Average rate on BD time deposits of 6-12 months, 2.64% in August 2026; deposits in the BD 10,000-50,000 range.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BH', 1, 'fdr_3m_rate', 0.0269, NULL, 'sourced', 'Central Bank of Bahrain, Monthly Statistical Bulletin, August 2026, Table 7 (BD time deposits, 3-6 months)', 'https://www.cbb.gov.bh/wp-content/uploads/2026/09/Aug-2026.pdf', '2026-08-31', 'Average rate on BD time deposits of 3-6 months, 2.69% in August 2026 (less than 3 months: 2.67%); deposits in the BD 10,000-50,000 range.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BH', 1, 'fixed_income_return_base', 0.026, NULL, 'assumption', 'Central Bank of Bahrain, Monthly Statistical Bulletin, August 2026 (1-year deposit 2.64%)', 'https://www.cbb.gov.bh/wp-content/uploads/2026/09/Aug-2026.pdf', '2026-10-31', 'Base case: the 6-12 month deposit rate, untaxed; Treasury bills pay more but are bid for by banks and institutions.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BH', 1, 'fixed_income_return_high', 0.045, NULL, 'assumption', 'Central Bank of Bahrain, Monthly Statistical Bulletin, August 2026 (Treasury bills 5.28%, policy rate 4.5%)', 'https://www.cbb.gov.bh/wp-content/uploads/2026/09/Aug-2026.pdf', '2026-10-31', 'High case: savers who reach Treasury bill or sukuk returns through banks or funds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BH', 1, 'fixed_income_return_low', 0.015, NULL, 'assumption', 'Central Bank of Bahrain, Monthly Statistical Bulletin, August 2026 (deposit rates)', 'https://www.cbb.gov.bh/wp-content/uploads/2026/09/Aug-2026.pdf', '2026-10-31', 'Low case: deposit rates fall back toward the 2025 level of about 1.9%, untaxed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BH', 1, 'goal_inflation_education', 0.04, NULL, 'assumption', 'Inflation assumption 2%; latest CPI 3.1%', 'https://data.worldbank.org/indicator/FP.CPI.TOTL.ZG?locations=BH', '2026-10-31', 'No education CPI was read; private school fees usually rise faster than general prices, so 2 points above the inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BH', 1, 'goal_inflation_health', 0.04, NULL, 'assumption', 'Inflation assumption 2%; latest CPI 3.1%', 'https://data.worldbank.org/indicator/FP.CPI.TOTL.ZG?locations=BH', '2026-10-31', 'No medical CPI was read; private medical costs usually rise about 2 points faster than general prices.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BH', 1, 'gold_return_base', 0.04, NULL, 'assumption', 'Dollar peg (0.376 BHD per USD); long-run dollar gold trend', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=BH', '2026-10-31', 'Base case: the long-run dollar gold trend of about 4% a year, with no depreciation gain under the peg.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BH', 1, 'gold_return_high', 0.08, NULL, 'assumption', 'Dollar peg (0.376 BHD per USD); long-run dollar gold trend', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=BH', '2026-10-31', 'High case: strong dollar gold years.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BH', 1, 'gold_return_low', 0, NULL, 'assumption', 'Dollar peg (0.376 BHD per USD); World Bank exchange rate', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=BH', '2026-10-31', 'Low case: flat dollar gold; the peg means no currency boost.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BH', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'The National Portal says the Labour Law gives expatriate employees a statutory end-of-service indemnity (Bahraini nationals are covered by social insurance instead), but the Labour Law text giving the days per year could not be opened (access refused).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BH', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a major private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BH', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premiums by age were found from a public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BH', 1, 'inflation_cpi', 0.031, NULL, 'sourced', 'Trading Economics, citing the Information & eGovernment Authority (iGA), CPI September 2026', 'https://tradingeconomics.com/bahrain/inflation-cpi', '2026-09-30', 'Consumer prices up 3.1% year on year in September 2026 (3.0% in August); secondary source because the iGA release could not be read. World Bank 2025 average -0.1%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BH', 1, 'inflation_projection', 0.02, NULL, 'assumption', 'World Bank CPI inflation 2021-2025 (about 1% average); latest 3.1% (September 2026); dollar peg', 'https://data.worldbank.org/indicator/FP.CPI.TOTL.ZG?locations=BH', '2026-10-31', 'With the dinar pegged to the dollar, inflation has averaged about 1% over 2021-2025 and is 3.1% now, so 2% a year is used for long-range plans.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BH', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life cover is sold, but no published premium rates per BD 1,000 of cover by age were found from the regulator or another public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BH', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The CBB (the insurance regulator) publishes no industry-wide life claim settlement ratio that could be found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BH', 1, 'life_expectancy', 81.423, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN), Bahrain', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=BH', '2024-12-31', '81.4 years in 2024 (men 80.9, women 82.1); the population includes many younger migrant workers.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BH', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":24.3,"men":23.8,"women":24.7},{"age":65,"total":20.1,"men":19.6,"women":20.5},{"age":70,"total":16.3,"men":15.8,"women":16.7},{"age":80,"total":9.7,"men":9.3,"women":10}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/bahrain/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BH', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'Eligibility rules for social assistance to older people could not be read from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BH', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'Means-tested social assistance from the Ministry of Social Development covers some older people, but no current amount of an old-age allowance could be read from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BH', 1, 'oop_health_share', 0.2866, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), Bahrain', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=BH', '2023-12-31', '28.7% in 2023 (WHO Global Health Expenditure Database via the World Bank); older than 2025, the latest available.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BH', 1, 'policy_rate', 0.045, NULL, 'sourced', 'Central Bank of Bahrain press release, 28 October 2026: overnight deposit rate unchanged', 'https://www.cbb.gov.bh/media-center/cbb-maintains-overnight-interest-rate-unchanged-at-4-50/', '2026-10-28', 'The CBB kept its overnight deposit rate, its key policy rate, unchanged at 4.50%. Its August 2026 bulletin shows the average repo rate at 5.25% in Q2 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BH', 1, 'public_pension_scheme', NULL, NULL, 'missing', '', '', '2026-10-31', 'Compulsory social insurance through the Social Insurance Organization covers Bahraini public and private employees (the National Portal says a full pension needs 20 years of insured employment and is based on the last five years'' average pay), but the pension age and indexation rules could not be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BH', 1, 'retirement_accumulation_return_base', 0.05, NULL, 'assumption', 'Central Bank of Bahrain, Monthly Statistical Bulletin, August 2026; equity base 7.5%; gold base 4%', 'https://www.cbb.gov.bh/wp-content/uploads/2026/09/Aug-2026.pdf', '2026-10-31', 'Base case: a balanced mix of deposits or sukuk, equities and some gold.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BH', 1, 'retirement_accumulation_return_high', 0.07, NULL, 'assumption', 'Central Bank of Bahrain, Monthly Statistical Bulletin, August 2026; equity high 10%', 'https://www.cbb.gov.bh/wp-content/uploads/2026/09/Aug-2026.pdf', '2026-10-31', 'High case: a growth-leaning mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BH', 1, 'retirement_accumulation_return_low', 0.03, NULL, 'assumption', 'Central Bank of Bahrain, Monthly Statistical Bulletin, August 2026 (deposits and Treasury bills)', 'https://www.cbb.gov.bh/wp-content/uploads/2026/09/Aug-2026.pdf', '2026-10-31', 'Low case: a mix earning a little above deposit rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BH', 1, 'retirement_age_default', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Social Insurance Organization site and the social insurance law could not be read (access refused), so the current private-sector pension age could not be confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BH', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'The civil-service pension age could not be confirmed; the Social Insurance Organization site could not be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BH', 1, 'retirement_return_base', 0.026, NULL, 'assumption', 'Central Bank of Bahrain, Monthly Statistical Bulletin, August 2026 (1-year deposit 2.64%)', 'https://www.cbb.gov.bh/wp-content/uploads/2026/09/Aug-2026.pdf', '2026-10-31', 'Base case: the untaxed 6-12 month deposit rate; not above the after-tax 1-year deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BH', 1, 'retirement_return_high', 0.04, NULL, 'assumption', 'Central Bank of Bahrain, Monthly Statistical Bulletin, August 2026 (Treasury bills 5.28%)', 'https://www.cbb.gov.bh/wp-content/uploads/2026/09/Aug-2026.pdf', '2026-10-31', 'High case: part of the money earns Treasury bill or sukuk returns.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BH', 1, 'retirement_return_low', 0.015, NULL, 'assumption', 'Central Bank of Bahrain, Monthly Statistical Bulletin, August 2026 (deposit rates)', 'https://www.cbb.gov.bh/wp-content/uploads/2026/09/Aug-2026.pdf', '2026-10-31', 'Low case: deposit rates near their 2025 level, untaxed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BH', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate or retail savings bond for individuals was found; government securities are auctioned to banks and institutions through the CBB.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BH', 1, 'savings_account_rate', 0.0018, NULL, 'sourced', 'Central Bank of Bahrain, Monthly Statistical Bulletin, August 2026, Table 7 (conventional retail banks, BD savings deposits)', 'https://www.cbb.gov.bh/wp-content/uploads/2026/09/Aug-2026.pdf', '2026-08-31', 'Average rate on BD savings deposits at conventional retail banks, 0.18% in August 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BH', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":19.3},{"year":2040,"value":11.5},{"year":2065,"value":6.7}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/bahrain/2040/', '2025-12-31', '100 / old-age dependency ratio: 5.18 (2025, World Bank), 8.7 (2040) and 15.0 (2065, populationpyramid.net/bahrain/2065/); the large migrant workforce keeps the ratio high.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BH', 1, 'tax_bank_interest', 0, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Bahrain, taxes on personal income', 'https://taxsummaries.pwc.com/bahrain/individual/taxes-on-personal-income', '2026-10-31', 'There is no personal income tax in Bahrain, so bank interest is untaxed for individuals.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BH', 1, 'tax_sanchayapatra_profit', 0, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Bahrain, taxes on personal income', 'https://taxsummaries.pwc.com/bahrain/individual/taxes-on-personal-income', '2026-10-31', 'No personal income tax, so returns on government securities are untaxed for individuals (no retail savings certificate exists).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BH', 1, 'tbill_91d_rate', 0.0528, NULL, 'sourced', 'Central Bank of Bahrain, Monthly Statistical Bulletin, August 2026, Table 11 (Government of Bahrain Treasury Bills)', 'https://www.cbb.gov.bh/wp-content/uploads/2026/09/Aug-2026.pdf', '2026-08-26', 'Average rate on the weekly 91-day bills allotted on 26 August 2026 (BD 70 million at a price of 98.684); recent auctions ranged 5.28-5.48%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BH', 1, 'tbond_10y_rate', 0.0669, NULL, 'sourced', 'Central Bank of Bahrain, Monthly Statistical Bulletin, August 2026, banking indicators (average interest rate on local and international long-term government bonds)', 'https://www.cbb.gov.bh/wp-content/uploads/2026/09/Aug-2026.pdf', '2026-06-30', 'Average yield on long-term government development bonds, 6.69% in Q2 2026 (5.96% in Q1); maturities are not split out, so this is used as the long bond yield.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BH', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 5-year government bond yield is published; the CBB bulletin gives only the average yield on long-term development bonds.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('BI', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"BI","iso3":"BDI","nameEn":"Burundi","nameNative":"Uburundi","region":"sub_saharan_africa","languages":["rn","fr","sw","en"],"currency":{"code":"BIF","symbol":"FBu","decimals":0,"compact":"intl","usdRate":{"value":3013.13,"status":"sourced","sourceName":"Banque de la République du Burundi, daily exchange rates, US dollar mid rate, 30 October 2026","sourceUrl":"https://www.brb.bi/Details%20Taux%20de%20Change","asOf":"2026-10-30","note":"Mid rate 3,013.13 francs per dollar (buying 2,989.03, selling 3,037.24); World Bank 2025 average 2,943. CLDR gives ''BIF'' as symbol; ''FBu'' is the local abbreviation used for the franc burundais."}},"instruments":{"savings_account":{"available":true,"localName":"Compte sur livret","localNameEn":"Passbook savings account","note":"Average 4.97% at end-December 2025 (BRB).","sourceUrl":"https://www.brb.bi/sites/default/files/2026-03/Rapport%20de%20Politique%20Mon%C3%A9taire%20du%20quatri%C3%A8me%20trimestre%202025.pdf"},"fdr_3m":{"available":true,"localName":"Dépôt à terme","localNameEn":"Term deposit","note":"The BRB publishes one average for all term deposits (7.44%, end-December 2025).","sourceUrl":"https://www.brb.bi/sites/default/files/2026-03/Rapport%20de%20Politique%20Mon%C3%A9taire%20du%20quatri%C3%A8me%20trimestre%202025.pdf"},"fdr_1y":{"available":true,"localName":"Dépôt à terme (1 an)","localNameEn":"Term deposit, 1 year","note":"The BRB publishes one average for all term deposits (7.44%, end-December 2025).","sourceUrl":"https://www.brb.bi/sites/default/files/2026-03/Rapport%20de%20Politique%20Mon%C3%A9taire%20du%20quatri%C3%A8me%20trimestre%202025.pdf"},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No standard monthly recurring deposit product was found in BRB statistics."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate for individuals was found."},"tbill_91d":{"available":true,"localName":"Bons du Trésor","localNameEn":"Treasury bills","note":"Auctioned weekly by the BRB for the Treasury (13, 26 and 52 weeks); mostly bought by banks.","sourceUrl":"https://www.brb.bi/sites/default/files/2026-10/R%C3%A9sultats%20d%27adjudication%20B.T%20du%2029%2010%202026.pdf"},"tbond_5y":{"available":true,"localName":"Obligations du Trésor","localNameEn":"Treasury bonds","note":"2 to 10-year bonds are auctioned by the BRB; 5-year issues are occasional.","sourceUrl":"https://www.brb.bi/sites/default/files/2026-06/R%C3%A9sultats%20d%27adjudication%20O.T%20du%2029%2006%202026.pdf"},"tbond_10y":{"available":true,"localName":"Obligations du Trésor","localNameEn":"Treasury bonds","note":"10-year bonds are auctioned most weeks by the BRB.","sourceUrl":"https://www.brb.bi/sites/default/files/2026-10/R%C3%A9sultats%20d%27adjudication%20O.T%20du%2028%20%26%20du%2029%2010%202026.pdf"},"equity_fund":{"available":false,"localName":null,"localNameEn":null,"note":"No stock exchange or retail investment funds operating in Burundi were found."},"gold":{"available":false,"localName":null,"localNameEn":null,"note":"No retail market for investment gold bars or coins was found; gold trading and export are regulated by the BRB."}},"institutions":{"centralBank":{"name":"Banque de la République du Burundi (BRB)","url":"https://www.brb.bi/"},"insuranceRegulator":{"name":"Agence de Régulation et de Contrôle des Assurances (ARCA)","url":"https://www.arca.bi/"},"insuranceComplaints":null,"pensionScheme":{"name":"Institut National de Sécurité Sociale (INSS), pensions for private-sector employees","url":"https://www.inss.bi/","note":"Site did not respond when checked on 31 October 2026; civil servants are covered by the Office National des Pensions et Risques Professionnels (ONPR, https://www.onpr.bi/)."},"oldAgeAllowance":null,"publicHealthCover":null,"depositInsurance":null,"statistics":{"name":"Institut National de la Statistique du Burundi (INSBU, formerly ISTEEBU)","url":"https://www.insbu.bi/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BI', 1, 'bank_deposit_avg_rate', 0.0715, NULL, 'sourced', 'BRB, monetary policy report Q4 2025, table 11: overall weighted average deposit rate (taux moyen pondéré créditeur), end-December 2025', 'https://www.brb.bi/sites/default/files/2026-03/Rapport%20de%20Politique%20Mon%C3%A9taire%20du%20quatri%C3%A8me%20trimestre%202025.pdf', '2025-12-31', 'Weighted average on outstanding deposits: 7.15% at end-December 2025 (demand 3.35%, passbook 4.97%, term 7.44%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BI', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap or published card rate was found; the BRB reports average short-term lending rates of 15.75% (end-December 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BI', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published deposit-guarantee cover per depositor was found; the deposit guarantee fund''s site could not be reached.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BI', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No industry-wide rate for a monthly recurring deposit product was found in BRB statistics.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BI', 1, 'equity_return_base', 0.105, NULL, 'assumption', 'BRB term-deposit average 7.44% (Q4 2025), about 6.5% after an assumed withholding tax', 'https://www.brb.bi/sites/default/files/2026-03/Rapport%20de%20Politique%20Mon%C3%A9taire%20du%20quatri%C3%A8me%20trimestre%202025.pdf', '2026-10-31', 'Base case: no local stock exchange operates, so this is a global equity index in Burundian-franc terms, held to 4 points above the after-tax deposit rate (6.5%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BI', 1, 'equity_return_high', 0.16, NULL, 'assumption', 'BRB official exchange rate history; World Bank PA.NUS.FCRF', 'https://www.brb.bi/Details%20Taux%20de%20Change', '2026-10-31', 'High case: global shares near their long-run dollar return plus continued franc depreciation (the official rate moved from about 2,000 to 3,000 per dollar in 2021-2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BI', 1, 'equity_return_low', 0.04, NULL, 'assumption', 'BRB Treasury auctions (364-day bill 11.00%); no local stock exchange', 'https://www.brb.bi/sites/default/files/2026-10/R%C3%A9sultats%20d%27adjudication%20B.T%20du%2029%2010%202026.pdf', '2026-10-31', 'Low case: no local stock market, so a global index held in francs; a weak decade for world shares with a stable official rate gives about 4%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BI', 1, 'fdr_1y_rate', 0.0744, NULL, 'sourced', 'BRB, monetary policy report Q4 2025, table 11: weighted average rate on term deposits (dépôts à terme), end-December 2025', 'https://www.brb.bi/sites/default/files/2026-03/Rapport%20de%20Politique%20Mon%C3%A9taire%20du%20quatri%C3%A8me%20trimestre%202025.pdf', '2025-12-31', 'Average over all term-deposit maturities (not 1 year only), 7.44% at end-December 2025, unchanged from September 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BI', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The BRB publishes one weighted average for all term deposits (7.44% at end-December 2025), not by maturity; no 3-month figure was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BI', 1, 'fixed_income_return_base', 0.07, NULL, 'assumption', 'BRB term deposits 7.44% (Q4 2025); 91-day bill 8.89% (October 2026)', 'https://www.brb.bi/sites/default/files/2026-03/Rapport%20de%20Politique%20Mon%C3%A9taire%20du%20quatri%C3%A8me%20trimestre%202025.pdf', '2026-10-31', 'Base case: slightly below the term-deposit average to allow for withholding tax that could not be confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BI', 1, 'fixed_income_return_high', 0.1, NULL, 'assumption', 'BRB Treasury auctions, 364-day bill 11.00% (October 2026)', 'https://www.brb.bi/sites/default/files/2026-10/R%C3%A9sultats%20d%27adjudication%20B.T%20du%2029%2010%202026.pdf', '2026-10-31', 'High case: one-year Treasury bills at about 11% less some tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BI', 1, 'fixed_income_return_low', 0.05, NULL, 'assumption', 'BRB passbook savings 4.97% (Q4 2025)', 'https://www.brb.bi/sites/default/files/2026-03/Rapport%20de%20Politique%20Mon%C3%A9taire%20du%20quatri%C3%A8me%20trimestre%202025.pdf', '2026-10-31', 'Low case: passbook savings rate, about 5%, with tax uncertain.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BI', 1, 'goal_inflation_education', 0.06, NULL, 'assumption', 'BRB statistics table V.7, consumer price index by function (INSBU data), education and general indices 2018-2026', 'https://www.brb.bi/sites/default/files/2026-09/V.7%20Indice%20des%20prix%20%C3%A0%20la%20consommation.xls', '2026-10-31', 'The education index rose about 7% a year over 2020-2025 against 21% for all items (1.5% in the year to August 2026), so education costs are planned at half the 12% general assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BI', 1, 'goal_inflation_health', 0.1, NULL, 'assumption', 'BRB statistics table V.7, consumer price index by function (INSBU data), health and general indices 2018-2026', 'https://www.brb.bi/sites/default/files/2026-09/V.7%20Indice%20des%20prix%20%C3%A0%20la%20consommation.xls', '2026-10-31', 'The health index rose about 17% a year over 2020-2025 against 21% for all items (13% vs 17% over 2018-2025), so health costs are planned at about 80% of the 12% general assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BI', 1, 'gold_return_base', 0.1, NULL, 'assumption', 'BRB official exchange rate history; World Bank PA.NUS.FCRF', 'https://www.brb.bi/Details%20Taux%20de%20Change', '2026-10-31', 'Base case: dollar gold trend of about 4-5% a year plus expected franc depreciation of about 5% a year.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BI', 1, 'gold_return_high', 0.16, NULL, 'assumption', 'BRB official exchange rate history; World Bank PA.NUS.FCRF', 'https://www.brb.bi/Details%20Taux%20de%20Change', '2026-10-31', 'High case: strong dollar gold and a further devaluation such as the 2023 step from about 2,070 to 2,850 per dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BI', 1, 'gold_return_low', 0.03, NULL, 'assumption', 'BRB official exchange rate, 3,013 BIF per dollar (30 October 2026)', 'https://www.brb.bi/Details%20Taux%20de%20Change', '2026-10-31', 'Low case: flat dollar gold with modest franc depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BI', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Labour Code text on end-of-service or severance benefits could not be read from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BI', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a major private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BI', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premiums per 100,000 BIF of cover were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BI', 1, 'inflation_cpi', 0.074, NULL, 'sourced', 'Trading Economics, citing the national statistics institute (ISTEEBU/INSBU), consumer prices, September 2026', 'https://tradingeconomics.com/burundi/inflation-cpi', '2026-09-30', 'Secondary source: the statistics office site could not be read. Annual inflation 7.4% in September 2026 (8.4% in August), the lowest since May 2021; food inflation 1.7%. The BRB''s CPI table (INSBU data) confirms 8.4% for August 2026. Inflation averaged 34% in 2025 (World Bank) and peaked at 45.5% in April 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BI', 1, 'inflation_projection', 0.12, NULL, 'assumption', 'BRB monetary policy report Q4 2025 (inflation outlook); World Bank CPI inflation 2021-2025', 'https://www.brb.bi/sites/default/files/2026-03/Rapport%20de%20Politique%20Mon%C3%A9taire%20du%20quatri%C3%A8me%20trimestre%202025.pdf', '2026-10-31', 'Inflation averaged about 22% a year over 2021-2025 and has only just fallen to 7.4%, with no formal target and a wide parallel-market exchange premium, so 12% a year is used for long-range plans.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BI', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published term-life premium rates per 1,000 BIF of cover were found from the regulator or another public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BI', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No industry-wide life claim settlement ratio was found; the insurance regulator (ARCA) site was unavailable.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BI', 1, 'life_expectancy', 63.8, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN)', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=BI', '2024-12-31', '63.8 years in 2024 (men 61.8, women 65.9).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BI', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":17.1,"men":16.3,"women":17.8},{"age":65,"total":13.7,"men":13,"women":14.3},{"age":70,"total":10.6,"men":10.1,"women":11.1},{"age":80,"total":5.9,"men":5.6,"women":6.2}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/burundi/', '2026-07-01', 'Secondary source of UN WPP 2024 (medium variant) for 2026; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BI', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'No eligibility rules for a non-contributory old-age pension were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BI', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension amount was found; no official source on such a scheme could be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BI', 1, 'oop_health_share', 0.2449, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=BI', '2023-12-31', '24.5% in 2023 (latest year; older than 2025). External donors finance a large share of health spending.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BI', 1, 'policy_rate', 0.1, NULL, 'sourced', 'Banque de la République du Burundi (BRB), monetary policy report Q4 2025: policy rate cut from 12% to 10%', 'https://www.brb.bi/sites/default/files/2026-03/Rapport%20de%20Politique%20Mon%C3%A9taire%20du%20quatri%C3%A8me%20trimestre%202025.pdf', '2026-02-26', 'Cut by 200 basis points at the 26 February 2026 monetary policy committee; the BRB website still showed 10% ''in effect since 26/02/2026'' on 31 October 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BI', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":60,"inflationLinked":false,"taxFree":null}', 'sourced', 'US Social Security Administration, Social Security Programs Throughout the World: Africa 2019, Burundi (archived copy)', 'https://web.archive.org/web/20260417213804/https://www.ssa.gov/policy/docs/progdesc/ssptw/2018-2019/africa/burundi.html', '2019-12-31', 'Compulsory INSS pension for salaried workers (civil servants have a separate scheme): 30% of average monthly earnings in the last 3 or 5 years plus 2% per 12 months of coverage beyond 180 months, at most 80%; contributions 4% employee and 6% employer. Benefits are adjusted only when the scheme''s finances allow (last adjustment 2010 per the source), so not inflation-linked. Source is from 2019 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BI', 1, 'retirement_accumulation_return_base', 0.09, NULL, 'assumption', 'BRB Treasury auctions (364-day bill 11.00%) and term deposits 7.44%', 'https://www.brb.bi/sites/default/files/2026-10/R%C3%A9sultats%20d%27adjudication%20B.T%20du%2029%2010%202026.pdf', '2026-10-31', 'Base case: a balanced mix of deposits, Treasury bills and global shares, between the safe and equity base cases.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BI', 1, 'retirement_accumulation_return_high', 0.12, NULL, 'assumption', 'BRB Treasury auctions, 364-day bill 11.00% (October 2026)', 'https://www.brb.bi/sites/default/files/2026-10/R%C3%A9sultats%20d%27adjudication%20B.T%20du%2029%2010%202026.pdf', '2026-10-31', 'High case: higher share in Treasury bills and global shares with continued franc depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BI', 1, 'retirement_accumulation_return_low', 0.06, NULL, 'assumption', 'BRB term deposits 7.44% (Q4 2025)', 'https://www.brb.bi/sites/default/files/2026-03/Rapport%20de%20Politique%20Mon%C3%A9taire%20du%20quatri%C3%A8me%20trimestre%202025.pdf', '2026-10-31', 'Low case: mostly deposits with a small share of global shares.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BI', 1, 'retirement_age_default', 60, NULL, 'sourced', 'US Social Security Administration, Social Security Programs Throughout the World: Africa 2019, Burundi (archived copy)', 'https://web.archive.org/web/20260417213804/https://www.ssa.gov/policy/docs/progdesc/ssptw/2018-2019/africa/burundi.html', '2019-12-31', 'INSS old-age pension at 60 for men and women with at least 15 years of coverage (55 if prematurely aged, 45 in arduous work), under the 2002 pension law. Source is from 2019 (older than 2025) because the INSS site did not respond and the live SSA page refused access; no later change was found, but a newer code was not checked.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BI', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'The retirement age of civil servants (ONPR scheme) could not be confirmed from an official text that could be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BI', 1, 'retirement_return_base', 0.065, NULL, 'assumption', 'BRB term deposits 7.44% (Q4 2025)', 'https://www.brb.bi/sites/default/files/2026-03/Rapport%20de%20Politique%20Mon%C3%A9taire%20du%20quatri%C3%A8me%20trimestre%202025.pdf', '2026-10-31', 'Base case: below the term-deposit average to allow for withholding tax, so not above the after-tax safe rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BI', 1, 'retirement_return_high', 0.08, NULL, 'assumption', 'BRB Treasury auctions, 91-day bill 8.89% (October 2026)', 'https://www.brb.bi/sites/default/files/2026-10/R%C3%A9sultats%20d%27adjudication%20B.T%20du%2029%2010%202026.pdf', '2026-10-31', 'High case: rolling short Treasury bills at about 9% less some tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BI', 1, 'retirement_return_low', 0.05, NULL, 'assumption', 'BRB passbook savings 4.97% (Q4 2025)', 'https://www.brb.bi/sites/default/files/2026-03/Rapport%20de%20Politique%20Mon%C3%A9taire%20du%20quatri%C3%A8me%20trimestre%202025.pdf', '2026-10-31', 'Low case: passbook savings rate in retirement.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BI', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate or retail savings bond for individuals was found; Treasury bills and bonds are auctioned by the BRB.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BI', 1, 'savings_account_rate', 0.0497, NULL, 'sourced', 'BRB, monetary policy report Q4 2025, table 11: weighted average rate on passbook savings accounts (comptes sur livrets), end-December 2025', 'https://www.brb.bi/sites/default/files/2026-03/Rapport%20de%20Politique%20Mon%C3%A9taire%20du%20quatri%C3%A8me%20trimestre%202025.pdf', '2025-12-31', 'Weighted average on outstanding passbook savings at banks, 4.97% at end-December 2025 (4.90% end-September). Latest published quarter found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BI', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":21},{"year":2040,"value":19.6},{"year":2065,"value":11.1}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/burundi/2040/', '2025-12-31', '100 / old-age dependency ratio: 4.77 (2025, World Bank), 5.1 (2040) and 9.0 (2065, populationpyramid.net/burundi/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BI', 1, 'tax_bank_interest', NULL, NULL, 'missing', '', '', '2026-10-31', 'The withholding tax on interest (impôt sur les revenus des capitaux mobiliers) could not be confirmed: the revenue authority (OBR) site returned an error and PwC Tax Summaries has no Burundi page.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BI', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No savings certificate exists and the tax on Treasury-security interest for individuals could not be confirmed from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BI', 1, 'tbill_91d_rate', 0.0889, NULL, 'sourced', 'BRB, Treasury bill auction results of 28-29 October 2026, 91 days', 'https://www.brb.bi/sites/default/files/2026-10/R%C3%A9sultats%20d%27adjudication%20B.T%20du%2029%2010%202026.pdf', '2026-10-28', 'Weighted average rate 8.89% on the 91-day bill (182 days 9.40%, 364 days 11.00%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BI', 1, 'tbond_10y_rate', 0.1146, NULL, 'sourced', 'BRB, Treasury bond auction results of 28-29 October 2026, 10 years', 'https://www.brb.bi/sites/default/files/2026-10/R%C3%A9sultats%20d%27adjudication%20O.T%20du%2028%20%26%20du%2029%2010%202026.pdf', '2026-10-28', 'Weighted average 11.46% at the 10-year auction of 28 October 2026 (10.97% on 20 October).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BI', 1, 'tbond_5y_rate', 0.0967, NULL, 'sourced', 'BRB, Treasury bond auction results of 29 June 2026, 5 years', 'https://www.brb.bi/sites/default/files/2026-06/R%C3%A9sultats%20d%27adjudication%20O.T%20du%2029%2006%202026.pdf', '2026-06-26', 'Weighted average 9.67% at the last 5-year auction found (a single bid of 1 billion BIF); the 2-year bond is auctioned weekly at about 14.1%, so the curve is irregular.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('BJ', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"BJ","iso3":"BEN","nameEn":"Benin","nameNative":"Bénin","region":"sub_saharan_africa","languages":["fr","fon","yo"],"currency":{"code":"XOF","symbol":"F CFA","decimals":0,"compact":"intl","usdRate":{"value":589,"status":"sourced","sourceName":"BCEAO, rates of foreign currencies against the CFA franc for transfers, 30 October 2026","sourceUrl":"https://www.bceao.int/fr/cours/cours-des-devises-contre-Franc-CFA-appliquer-aux-transferts","asOf":"2026-10-30","note":"Mid-point of the buying (585.50) and selling (592.50) rates for the US dollar; the CFA franc is pegged at 655.957 per euro. World Bank 2025 average 581.9. The page is updated daily; on 2 November 2026 it showed 582.50 buying and 589.50 selling (mid 586)."}},"instruments":{"savings_account":{"available":true,"localName":"Compte d''épargne","localNameEn":"Savings account"},"fdr_3m":{"available":true,"localName":"Dépôt à terme","localNameEn":"Term deposit (DAT)","note":"Banks declare minimum and maximum term-deposit rates to the BCEAO twice a year.","sourceUrl":"https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf"},"fdr_1y":{"available":true,"localName":"Dépôt à terme","localNameEn":"Term deposit (DAT), 1 year","note":"Banks declare minimum and maximum term-deposit rates to the BCEAO twice a year.","sourceUrl":"https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf"},"dps":{"available":true,"localName":"Épargne contractuelle","localNameEn":"Contractual savings plan","note":"Monthly savings plans (housing or project savings) offered by banks.","sourceUrl":"https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf"},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate for individuals was found."},"tbill_91d":{"available":true,"localName":"Bons assimilables du Trésor","localNameEn":"Treasury bills (BAT)","note":"Auctioned by UMOA-Titres; individuals buy through banks or licensed brokers (SGI).","sourceUrl":"https://www.umoatitres.org/fr/emission/emission-simultanee-de-bons-et-dobligations-du-tresor-du-benin-du-13-08-2026/"},"tbond_5y":{"available":true,"localName":"Obligations assimilables du Trésor","localNameEn":"Treasury bonds (OAT)","note":"Auctioned by UMOA-Titres; individuals buy through banks or licensed brokers (SGI).","sourceUrl":"https://www.umoatitres.org/fr/pays/benin/"},"tbond_10y":{"available":true,"localName":"Obligations assimilables du Trésor","localNameEn":"Treasury bonds (OAT)","note":"Benin has issued 3-7 year bonds on the regional market in 2026; longer bonds are rare.","sourceUrl":"https://www.umoatitres.org/fr/pays/benin/"},"equity_fund":{"available":true,"localName":"OPCVM (FCP, SICAV)","localNameEn":"Collective investment funds","note":"Supervised by the regional financial market authority (AMF-UMOA); equity funds invest on the regional exchange (BRVM)."},"gold":{"available":true,"localName":"Or","localNameEn":"Gold","note":"Gold is mainly bought as jewellery; bars and coins are uncommon."}},"institutions":{"centralBank":{"name":"Banque Centrale des États de l''Afrique de l''Ouest (BCEAO)","url":"https://www.bceao.int/"},"insuranceRegulator":{"name":"Commission Régionale de Contrôle des Assurances (CIMA)","url":"https://cima-afrique.org/","note":"Regional insurance regulator for the CIMA member states; Benin''s insurance directorate is in the Ministry of Economy and Finance."},"insuranceComplaints":null,"pensionScheme":{"name":"Caisse Nationale de Sécurité Sociale (CNSS), old-age pension","url":"https://cnss.bj/"},"oldAgeAllowance":null,"publicHealthCover":{"name":"Assurance pour le Renforcement du Capital Humain (ARCH), Agence Nationale de Protection Sociale (ANPS)","url":"https://anps.bj/"},"depositInsurance":{"name":"Fonds de Garantie des Dépôts et de Résolution dans l''UMOA (FGDR-UMOA)","url":"https://www.fgd-umoa.org/"},"statistics":{"name":"Institut National de la Statistique et de la Démographie (INStaD)","url":"https://instad.bj/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BJ', 1, 'bank_deposit_avg_rate', 0.0515, NULL, 'sourced', 'BCEAO, monthly economic note for UMOA countries, September 2026 (bank deposit rates, July 2026)', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-07-31', 'Average deposit rate across UMOA banks, 5.15% in July 2026 (5.12% in June); Benin''s rate rose 0.20 points in the month, but the BCEAO does not publish the country level in this note.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BJ', 1, 'credit_card_rate_cap', 0.14, NULL, 'sourced', 'BCEAO, conditions débitrices of UMOA credit institutions, first half 2026 (Benin)', 'https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf', '2026-06-30', 'Maximum lending rate (taux débiteur maximum) declared by most Benin banks for the first half of 2026 (range 11-14%); it applies to all bank credit, including cards. No card-specific rate is published.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BJ', 1, 'deposit_insurance_limit', 1400000, NULL, 'sourced', 'UMOA Council of Ministers, Decision No. 009 of 30 June 2017 on FGDR-UMOA contribution rates and compensation ceilings', 'https://www.fgd-umoa.org/wp-content/uploads/2024/10/Decision-du-CM-relative-aux-taux-de-contribution-et-aux-plafonds-d-indemnistation-2-1.pdf', '2017-06-30', 'Deposits are guaranteed up to 1,400,000 FCFA per depositor per bank (300,000 FCFA at a microfinance institution) by the regional deposit guarantee fund; the decision dates from 2017 (older than 2025) and is still the one the fund publishes.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BJ', 1, 'dps_rate', 0.035, NULL, 'sourced', 'BCEAO, conditions créditrices of UMOA credit institutions, first half 2026 (Benin)', 'https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf', '2026-06-30', 'Median rate on contractual savings plans (épargne contractuelle) declared by Benin''s banks in the first half of 2026; most declare 3.50% (range 3.5-5.0%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BJ', 1, 'equity_return_base', 0.08, NULL, 'assumption', 'BCEAO monthly economic note, September 2026; UMOA-Titres Benin yield curve', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-10-31', 'Base case: about 3.5 points above after-tax term deposits and 1-year government bills (about 4.5%), within the 4-point cap; the BRVM''s equity capitalisation rose 65.7% in the year to August 2026 but its 10-year record is uneven.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BJ', 1, 'equity_return_high', 0.12, NULL, 'assumption', 'BCEAO monthly economic note, September 2026 (BRVM market capitalisation)', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-10-31', 'High case: the BRVM repeats a strong decade like 2023-2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BJ', 1, 'equity_return_low', 0.04, NULL, 'assumption', 'BCEAO monthly economic note, September 2026 (regional stock exchange BRVM, deposit rates)', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-10-31', 'Low case: regional (BRVM) equities return about the bank deposit rate, as in their weak 2016-2020 years.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BJ', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The BCEAO bank-conditions survey gives only minimum (median 3.5%) and maximum (median 5.75%, range 5.0-7.0%) term-deposit rates per bank in Benin for the first half of 2026, not a 1-year rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BJ', 1, 'fdr_3m_rate', 0.035, NULL, 'sourced', 'BCEAO, conditions créditrices of UMOA credit institutions, first half 2026 (Benin)', 'https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf', '2026-06-30', 'Median of the minimum term-deposit rates (taux DAT minimum) that Benin''s 15 banks declare to the BCEAO, range 2.0-4.0%; the minimum usually applies to small, short deposits. Not a tenor-specific average.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BJ', 1, 'fixed_income_return_base', 0.045, NULL, 'assumption', 'UMOA-Titres Benin yield curve (1 year 6.3%); BCEAO bank conditions (term deposits 3.5-5.75%)', 'https://www.umoatitres.org/wp-content/uploads/2026/10/COURBES-DE-TAUX.au_.23.10.2026.xlsx', '2026-10-31', 'Base case: larger term deposits (median maximum 5.75%) or 1-year Treasury bills (6.3%) through a bank, less tax on interest, rounded down because the tax rate is unconfirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BJ', 1, 'fixed_income_return_high', 0.06, NULL, 'assumption', 'UMOA-Titres Benin yield curve (5-year 6.7%)', 'https://www.umoatitres.org/wp-content/uploads/2026/10/COURBES-DE-TAUX.au_.23.10.2026.xlsx', '2026-10-31', 'High case: 3-5 year Treasury bonds or regional public bond issues at 6.5-7%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BJ', 1, 'fixed_income_return_low', 0.03, NULL, 'assumption', 'BCEAO, conditions créditrices of UMOA credit institutions, first half 2026 (Benin)', 'https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf', '2026-10-31', 'Low case: small term deposits or contractual savings at the 3.5% floor rate, less a possible tax on interest.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BJ', 1, 'goal_inflation_education', 0.04, NULL, 'assumption', 'BCEAO monthly economic note, September 2026 (UMOA education prices); inflation assumption 2%', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-10-31', 'No reliable national education CPI series was read; private school fees usually rise faster than general prices, so 2 points above the 2% inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BJ', 1, 'goal_inflation_health', 0.035, NULL, 'assumption', 'BCEAO monthly economic note, September 2026 (UMOA health prices); inflation assumption 2%', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-10-31', 'No reliable national medical CPI series was read; private medical costs usually rise faster than general prices, so 1.5 points above the 2% inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BJ', 1, 'gold_return_base', 0.045, NULL, 'assumption', 'BCEAO exchange rates (CFA franc pegged at 655.957 per euro)', 'https://www.bceao.int/fr/cours/cours-des-devises-contre-Franc-CFA-appliquer-aux-transferts', '2026-10-31', 'Base case: the long-run dollar gold trend of about 4% a year plus a small allowance for the euro-pegged franc weakening against the dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BJ', 1, 'gold_return_high', 0.08, NULL, 'assumption', 'BCEAO exchange rates', 'https://www.bceao.int/fr/cours/cours-des-devises-contre-Franc-CFA-appliquer-aux-transferts', '2026-10-31', 'High case: strong gold years such as 2024-2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BJ', 1, 'gold_return_low', 0, NULL, 'assumption', 'BCEAO exchange rates (CFA franc pegged to the euro)', 'https://www.bceao.int/fr/cours/cours-des-devises-contre-Franc-CFA-appliquer-aux-transferts', '2026-10-31', 'Low case: flat gold in euro terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BJ', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No official text on a statutory end-of-service or retirement indemnity for private employees in Benin could be read (the Labour Code and collective agreement were not reached).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BJ', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a major private hospital stay in Benin was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BJ', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premiums by age were found from a public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BJ', 1, 'inflation_cpi', 0.019, NULL, 'sourced', 'Trading Economics, citing INStaD consumer price index, September 2026', 'https://tradingeconomics.com/benin/inflation-cpi', '2026-09-30', 'Consumer prices up 1.9% year on year in September 2026 after 0.1% in August (secondary source); the BCEAO monthly note of October 2026 confirms 0.1% for August (0.0% in July).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BJ', 1, 'inflation_projection', 0.02, NULL, 'assumption', 'BCEAO inflation target (1-3% band, centre 2%); UMOA inflation 1.3% in August 2026', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-10-31', 'Benin''s inflation has stayed low and the CFA franc is pegged to the euro, so the centre of the BCEAO''s 1-3% target band, 2%, is used for long-range plans.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BJ', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Temporary death cover is sold under the CIMA code, but no published premium rates per 1,000 FCFA of cover by age were found from a public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BJ', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'CIMA (the regional insurance regulator) and Benin''s insurance directorate publish no industry-wide life claim settlement ratio that could be found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BJ', 1, 'life_expectancy', 60.961, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN), Benin', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=BJ', '2024-12-31', '61.0 years in 2024 (men 59.5, women 62.4).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BJ', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":16.8,"men":16.2,"women":17.3},{"age":65,"total":13.4,"men":13,"women":13.8},{"age":70,"total":10.5,"men":10.1,"women":10.8},{"age":80,"total":5.8,"men":5.6,"women":6}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/benin/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BJ', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension was found (see old_age_allowance_monthly).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BJ', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension for Benin was found; the CLEISS summary of Benin social security describes none, but no source confirming that none exists was read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BJ', 1, 'oop_health_share', 0.424, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), Benin', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=BJ', '2023-12-31', '42.4% in 2023 (WHO Global Health Expenditure Database); older than 2025, the latest available.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BJ', 1, 'policy_rate', 0.03, NULL, 'sourced', 'BCEAO, monthly economic note for UMOA countries, September 2026 (Monetary Policy Committee of 9 September 2026)', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-09-09', 'Main policy rate (rate at which the BCEAO refinances banks) 3.00%, left unchanged by the 9 September 2026 committee; the marginal lending facility rate is 5.00%. Common to all eight UMOA countries. The previously cited BCEAO key-rates page now returns 404.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BJ', 1, 'public_pension_scheme', NULL, '{"pensionFromAge":60,"entryAgeMin":null,"entryAgeMax":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'CLEISS (French social security liaison body), the Benin social security system for employees: CNSS old-age pension', 'https://www.cleiss.fr/docs/regimes/regime_benin-salaries.html', '2024-12-31', 'Compulsory CNSS pension for private employees: 30% of the average wage of the last 5 years after 180 months of insurance, plus 2% per extra 12 months, at least 60% of the minimum wage and at most 80% of the average wage; a lump sum of one month''s wage per year of insurance if fewer than 180 months. No automatic indexation (one-off 1-20% revaluation in 2023 by Decree 2023-455). Source dated 2024 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BJ', 1, 'retirement_accumulation_return_base', 0.06, NULL, 'assumption', 'UMOA-Titres Benin yield curve; equity base 8%; gold base 4.5%', 'https://www.umoatitres.org/wp-content/uploads/2026/10/COURBES-DE-TAUX.au_.23.10.2026.xlsx', '2026-10-31', 'Base case: a balanced mix of deposits or Treasury bonds, regional equity funds and some gold.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BJ', 1, 'retirement_accumulation_return_high', 0.08, NULL, 'assumption', 'UMOA-Titres Benin yield curve; equity high 12%', 'https://www.umoatitres.org/wp-content/uploads/2026/10/COURBES-DE-TAUX.au_.23.10.2026.xlsx', '2026-10-31', 'High case: a growth-leaning mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BJ', 1, 'retirement_accumulation_return_low', 0.035, NULL, 'assumption', 'BCEAO, conditions créditrices of UMOA credit institutions, first half 2026 (Benin)', 'https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf', '2026-10-31', 'Low case: a mix earning about after-tax deposit rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BJ', 1, 'retirement_age_default', 60, NULL, 'sourced', 'CLEISS (French social security liaison body), the Benin social security system for employees: CNSS old-age pension', 'https://www.cleiss.fr/docs/regimes/regime_benin-salaries.html', '2024-12-31', 'CNSS old-age pension at 60 with 180 months of insurance (55 for premature wear); early pension up to 5 years before, reduced 5% a year. Source is dated 2024 (older than 2025); the CNSS site could not be reached.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BJ', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'No official source for the current retirement age of Benin civil servants could be read (the public service ministry and pension fund sites were not reached).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BJ', 1, 'retirement_return_base', 0.04, NULL, 'assumption', 'BCEAO, conditions créditrices of UMOA credit institutions, first half 2026 (Benin)', 'https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf', '2026-10-31', 'Base case: term deposits at 3.5-5.75% less tax on interest; below the after-tax 1-year deposit and Treasury bill rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BJ', 1, 'retirement_return_high', 0.055, NULL, 'assumption', 'UMOA-Titres Benin yield curve (1-3 years 6.2-6.6%)', 'https://www.umoatitres.org/wp-content/uploads/2026/10/COURBES-DE-TAUX.au_.23.10.2026.xlsx', '2026-10-31', 'High case: part of the money in short Treasury bonds bought through a bank.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BJ', 1, 'retirement_return_low', 0.03, NULL, 'assumption', 'BCEAO, conditions créditrices of UMOA credit institutions, first half 2026 (Benin)', 'https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf', '2026-10-31', 'Low case: small term deposits or contractual savings at about 3.5%, less a possible tax on interest.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BJ', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate sold to individuals was found; the Treasury borrows through UMOA-Titres auctions of bills and bonds, open to individuals only through banks and brokers.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BJ', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No average rate on ordinary savings accounts in Benin was found; the BCEAO bank-conditions survey (first half 2026) lists term-deposit and contractual-savings rates only.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BJ', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":17.63},{"year":2040,"value":15.15},{"year":2065,"value":10}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/benin/2040/', '2025-12-31', '100 / old-age dependency ratio: 5.67 (2025, World Bank), 6.6 (2040) and 10.0 (2065, populationpyramid.net/benin/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BJ', 1, 'tax_bank_interest', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Benin tax authority site (impots.finances.gouv.bj) could not be reached and PwC Tax Summaries has no Benin page, so the withholding rate on bank interest could not be confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BJ', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate exists, and the tax treatment of interest on Benin Treasury securities for individuals could not be confirmed from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BJ', 1, 'tbill_91d_rate', 0.0306, NULL, 'sourced', 'UMOA-Titres, Benin Treasury bill auction of 13 August 2026 (3 months)', 'https://www.umoatitres.org/fr/emission/emission-simultanee-de-bons-et-dobligations-du-tresor-du-benin-du-13-08-2026/', '2026-08-13', 'Weighted average yield 3.06% (weighted average rate 3.0364%) on 3-month bills maturing 12 November 2026; the UMOA-Titres zero-coupon curve of 23 October 2026 gives 3.13% at 3 months.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BJ', 1, 'tbond_10y_rate', 0.073, NULL, 'sourced', 'UMOA-Titres, Benin yield curve (zero coupon) at 23 October 2026', 'https://www.umoatitres.org/wp-content/uploads/2026/10/COURBES-DE-TAUX.au_.23.10.2026.xlsx', '2026-10-23', '10-year zero-coupon rate 7.30% (7.43% after smoothing); Benin has not auctioned a 10-year bond in 2026, so this point is extrapolated from the curve.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BJ', 1, 'tbond_5y_rate', 0.0671, NULL, 'sourced', 'UMOA-Titres, Benin yield curve (zero coupon) at 23 October 2026', 'https://www.umoatitres.org/wp-content/uploads/2026/10/COURBES-DE-TAUX.au_.23.10.2026.xlsx', '2026-10-23', '5-year zero-coupon rate 6.71% (6.57% after smoothing); Benin''s last 5-year auction (22 January 2026) yielded 6.68%.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('BN', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"BN","iso3":"BRN","nameEn":"Brunei","nameNative":"Negara Brunei Darussalam","region":"east_asia_pacific","languages":["ms","zh","en"],"currency":{"code":"BND","symbol":"$","decimals":2,"compact":"intl","usdRate":{"value":1.2772,"status":"sourced","sourceName":"BDCB Statistical Bulletin, table 6.2 Exchange Rates (BND per USD, end of period)","sourceUrl":"https://www.bdcb.gov.bn/docs/home/BDCB%20SB%20-%2022nd%20October%202026%20publication.xlsx","asOf":"2026-09-30","note":"The Brunei dollar is pegged 1:1 to the Singapore dollar."}},"instruments":{"savings_account":{"available":true,"localName":"Akaun Simpanan","localNameEn":"Savings account","sourceUrl":null},"fdr_3m":{"available":true,"localName":"Simpanan Tetap","localNameEn":"Fixed deposit","note":"Islamic banks call it term deposit (Deposit Berjangka).","sourceUrl":"https://www.bdcb.gov.bn/docs/home/BDCB%20SB%20-%2022nd%20October%202026%20publication.xlsx"},"fdr_1y":{"available":true,"localName":"Simpanan Tetap","localNameEn":"Fixed deposit","note":"Banks do not offer BND fixed deposits beyond 12 months.","sourceUrl":"https://www.bdcb.gov.bn/docs/home/BDCB%20SB%20-%2022nd%20October%202026%20publication.xlsx"},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No monthly recurring deposit scheme is offered."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate or retail savings bond exists."},"tbill_91d":{"available":false,"localName":"Sukuk Al-Ijarah Jangka Pendek","localNameEn":"Short-term government Sukuk Al-Ijarah","note":"Auctioned by BDCB; we found no channel for individuals to buy directly.","sourceUrl":"https://www.bdcb.gov.bn/docs/home/BDCB%20SB%20-%2022nd%20October%202026%20publication.xlsx"},"tbond_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government bonds beyond 1 year."},"tbond_10y":{"available":false,"localName":null,"localNameEn":null,"note":"No government bonds beyond 1 year."},"equity_fund":{"available":true,"localName":"Skim Pelaburan Kolektif","localNameEn":"Collective investment scheme (unit trust)","note":"No local stock exchange; retail funds invest in foreign markets."},"gold":{"available":true,"localName":"Emas","localNameEn":"Gold","note":"Physical gold is freely bought from licensed goldsmiths."}},"institutions":{"centralBank":{"name":"Brunei Darussalam Central Bank (BDCB)","url":"https://www.bdcb.gov.bn/"},"insuranceRegulator":{"name":"Brunei Darussalam Central Bank (BDCB), insurance and takaful supervision","url":"https://www.bdcb.gov.bn/"},"insuranceComplaints":{"name":"BDCB Financial Consumer Complaints","url":"https://www.bdcb.gov.bn/consumer/financial-consumer-complaints"},"pensionScheme":{"name":"Tabung Amanah Pekerja (TAP), Skim Persaraan Kebangsaan (SPK)","url":"https://www.tap.com.bn/"},"oldAgeAllowance":{"name":"Department of Community Development (JAPEM), Old Age Pension","url":"https://www.japem.gov.bn/"},"publicHealthCover":{"name":"Ministry of Health (free public healthcare for citizens)","url":"https://www.moh.gov.bn/"},"depositInsurance":{"name":"Brunei Darussalam Deposit Protection Corporation (BDPC)","url":"https://www.bdpc.gov.bn/public/"},"statistics":{"name":"Department of Economic Planning and Statistics (DEPS)","url":"https://www.deps.gov.bn/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BN', 1, 'bank_deposit_avg_rate', 0.0031, NULL, 'sourced', 'World Bank WDI, deposit interest rate (FR.INR.DPST)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=BN', '2025-12-31', '0.31% for 2025; BDCB''s own average 3/6/12-month rates were 0.27%/0.37%/0.54% in June 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BN', 1, 'credit_card_rate_cap', 0.18, NULL, 'sourced', 'BDCB (then AMBD) Notice to Banks BU/N-12/2017/47 on Credit Cards, section 6.1', 'https://cms.bdcb.gov.bn/storage/uploads/regulatories/17111192061105880.pdf', '2017-09-14', 'Interest on credit cards may not exceed 1.5% per month on the outstanding amount (18% a year simple). Notice dates from 2017, older than 2025, and is still the rule BDCB publishes.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BN', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'A deposit protection scheme exists (Deposit Protection Order 2010, Brunei Darussalam Deposit Protection Corporation) and the cover is widely reported as B$50,000 per depositor per member, but the BDPC website was unreachable (connection refused) and only a member bank''s page showed the figure, so it is not cited.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BN', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched bank and BDCB rate pages: no monthly recurring deposit scheme with a published rate is offered in Brunei.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BN', 1, 'equity_return_base', 0.045, NULL, 'assumption', 'Global equity index in BND terms; BDCB 12-month deposit rate 0.54% plus 4 points', 'https://www.bdcb.gov.bn/docs/home/BDCB%20SB%20-%2022nd%20October%202026%20publication.xlsx', '2026-10-31', 'No local stock exchange: based on a global equity index in BND terms, capped at the 12-month deposit rate plus 4 points.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BN', 1, 'equity_return_high', 0.07, NULL, 'assumption', 'Global equity index long-run record; BDCB safe rates', 'https://www.bdcb.gov.bn/docs/home/BDCB%20SB%20-%2022nd%20October%202026%20publication.xlsx', '2026-10-31', 'High case near the long-run nominal return of a global index, less a little for BND strength against the US dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BN', 1, 'equity_return_low', 0.01, NULL, 'assumption', 'Global equity index in BND terms; BDCB safe rates', 'https://www.bdcb.gov.bn/docs/home/BDCB%20SB%20-%2022nd%20October%202026%20publication.xlsx', '2026-10-31', 'Low case for a global index fund held in BND, allowing for a decade of weak returns and a firm BND (pegged to SGD).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BN', 1, 'fdr_1y_rate', 0.00535, NULL, 'sourced', 'BDCB Statistical Bulletin, table 6.1 Average Deposit Rate 12 months', 'https://www.bdcb.gov.bn/docs/home/BDCB%20SB%20-%2022nd%20October%202026%20publication.xlsx', '2026-06-30', 'Average of banking institutions, June 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BN', 1, 'fdr_3m_rate', 0.00265, NULL, 'sourced', 'BDCB Statistical Bulletin, table 6.1 Average Deposit Rate 3 months', 'https://www.bdcb.gov.bn/docs/home/BDCB%20SB%20-%2022nd%20October%202026%20publication.xlsx', '2026-06-30', 'Average of banking institutions, June 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BN', 1, 'fixed_income_return_base', 0.006, NULL, 'assumption', 'BDCB average deposit rates and sukuk yields', 'https://www.bdcb.gov.bn/docs/home/BDCB%20SB%20-%2022nd%20October%202026%20publication.xlsx', '2026-10-31', 'Base case near the 12-month deposit rate (0.54%) that individuals can actually get. Safe BND rates: 12-month deposit 0.535% (BDCB, Jun 2026), 1-year government sukuk 1.16%, 3-month 1.25% (Sep 2026); no personal income tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BN', 1, 'fixed_income_return_high', 0.0125, NULL, 'assumption', 'BDCB average deposit rates and sukuk yields', 'https://www.bdcb.gov.bn/docs/home/BDCB%20SB%20-%2022nd%20October%202026%20publication.xlsx', '2026-10-31', 'High case at the current 3-month government sukuk yield (1.25%). Safe BND rates: 12-month deposit 0.535% (BDCB, Jun 2026), 1-year government sukuk 1.16%, 3-month 1.25% (Sep 2026); no personal income tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BN', 1, 'fixed_income_return_low', 0.003, NULL, 'assumption', 'BDCB average deposit rates and sukuk yields', 'https://www.bdcb.gov.bn/docs/home/BDCB%20SB%20-%2022nd%20October%202026%20publication.xlsx', '2026-10-31', 'Low case near the 3-month deposit rate (0.27%); no tax. Safe BND rates: 12-month deposit 0.535% (BDCB, Jun 2026), 1-year government sukuk 1.16%, 3-month 1.25% (Sep 2026); no personal income tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BN', 1, 'goal_inflation_education', 0.015, NULL, 'assumption', 'DEPS CPI education sub-index (via Trading Economics: +0.3% y/y Sep 2026)', 'https://tradingeconomics.com/brunei/inflation-cpi', '2026-10-31', 'Education CPI is near zero; 1.5% allows for private and overseas tuition rising faster than the subsidised public system.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BN', 1, 'goal_inflation_health', 0.02, NULL, 'assumption', 'DEPS CPI health sub-index (via Trading Economics: +0.8% y/y Sep 2026)', 'https://tradingeconomics.com/brunei/inflation-cpi', '2026-10-31', 'Health CPI runs below 1%, but planning uses 2% to allow for private and overseas care costing more over time.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BN', 1, 'gold_return_base', 0.04, NULL, 'assumption', 'US-dollar gold trend; BND/USD history (BDCB table 6.2)', 'https://www.bdcb.gov.bn/docs/home/BDCB%20SB%20-%2022nd%20October%202026%20publication.xlsx', '2026-10-31', 'Long-run dollar gold trend of about 5% less roughly 1% a year of BND appreciation against the US dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BN', 1, 'gold_return_high', 0.07, NULL, 'assumption', 'US-dollar gold trend; BND/USD history (BDCB table 6.2)', 'https://www.bdcb.gov.bn/docs/home/BDCB%20SB%20-%2022nd%20October%202026%20publication.xlsx', '2026-10-31', 'High case for a strong gold cycle in BND terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BN', 1, 'gold_return_low', 0, NULL, 'assumption', 'US-dollar gold trend; BND/USD history (BDCB table 6.2)', 'https://www.bdcb.gov.bn/docs/home/BDCB%20SB%20-%2022nd%20October%202026%20publication.xlsx', '2026-10-31', 'Gold can go a decade without gains and the BND has tended to firm against the US dollar, so the low case is zero.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BN', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'Brunei''s Employment Order 2009 has no general statutory gratuity or end-of-service payment for private employees; retirement savings run through SPK.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BN', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'Public hospital care is free or nominal for citizens; we found no published typical private hospital stay cost.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BN', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private medical insurance premium rates or guides found for Brunei.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BN', 1, 'inflation_cpi', -0.001, NULL, 'sourced', 'Department of Economic Planning and Statistics (DEPS), CPI media release September 2026', 'https://www.deps.gov.bn/wp-content/uploads/2026/10/CPI_SEP2026_PR.pdf', '2026-09-30', 'CPI fell 0.1% year on year in September 2026 (August +0.5%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BN', 1, 'inflation_projection', 0.01, NULL, 'assumption', '5-year CPI average (DEPS / Trading Economics); no inflation target under the currency board', 'https://tradingeconomics.com/brunei/inflation-cpi', '2026-10-31', 'Brunei has no inflation target (BND pegged 1:1 to SGD) and CPI averaged about 1% over 2021-2025, so we plan with 1%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BN', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term takaful/life cover is sold (sum covered B$10,000 to B$1,000,000) but we found no published premium rates or regulator premium data.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BN', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'BDCB publishes gross insurance/takaful claims and premiums (Statistical Bulletin tables 3.2-3.3) but no claim settlement ratio.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BN', 1, 'life_expectancy', 75.5, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN)', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=BN', '2024-12-31', 'Men 73.5, women 77.7 (2024). Figure refers to 2024, older than 2025; it is the latest available.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BN', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":20.3,"men":18.7,"women":21.9},{"age":65,"total":16.5,"men":15.1,"women":17.9},{"age":70,"total":13,"men":11.8,"women":14.1},{"age":80,"total":7.3,"men":6.7,"women":7.8}]}', 'sourced', 'UN World Population Prospects (via georank.org)', 'https://georank.org/life-expectancy/brunei', '2026-07-08', 'Remaining years derived from expected age at death by current age; secondary source for UN WPP because the WHO GHO API was unavailable.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BN', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":60,"womenAge":60,"over90Monthly":null,"meansTested":false}', 'sourced', 'ISSA country profile Brunei Darussalam 2022; Old Age and Disability Pensions Act amendment 2021', 'https://www.issa.int/sites/default/files/documents/2024-01/Brunei%20Darussalam%202022%20-%20ISSA%20country%20profile.pdf', '2022-12-31', 'Universal, non-contributory, from age 60 for citizens and stateless permanent residents with 10 years'' residence before the claim (30 if born abroad); foreign-citizen PRs excluded since 1 Oct 2021. ISSA profile reflects policies as of 1 Jan 2022, older than 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BN', 1, 'old_age_allowance_monthly', 250, NULL, 'sourced', 'ISSA country profile Brunei Darussalam 2022: Old-age pension (universal)', 'https://www.issa.int/sites/default/files/documents/2024-01/Brunei%20Darussalam%202022%20-%20ISSA%20country%20profile.pdf', '2022-12-31', 'Universal flat B$250 a month from age 60 for citizens and stateless permanent residents with the residency qualification, adjusted ad hoc only (ISSA, policies as of 1 Jan 2022, older than 2025); no increase found for 2025-2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BN', 1, 'oop_health_share', 0.0741, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure, SH.XPD.OOPC.CH.ZS)', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=BN', '2023-12-31', 'Figure refers to 2023, older than 2025; it is the latest available.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BN', 1, 'policy_rate', 0.005, NULL, 'sourced', 'Brunei Darussalam Central Bank (BDCB) Statistical Bulletin, table 6.3 Overnight Standing Facilities Rates', 'https://www.bdcb.gov.bn/docs/home/BDCB%20SB%20-%2022nd%20October%202026%20publication.xlsx', '2026-09-17', 'Brunei runs a currency board (BND = SGD) and has no policy rate; this is the BDCB overnight Standing Facility Deposit Rate (lending rate 1.5%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BN', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":60,"nomineeUntilAge":null,"inflationLinked":true,"taxFree":true}', 'sourced', 'Tabung Amanah Pekerja (TAP), Skim Persaraan Kebangsaan FAQ', 'https://www.tap.com.bn/faq-skim-persaraan-kebangsaan', '2026-10-31', 'SPK (from 2023): employee 8.5% of basic salary to a Member Account, employer to a Retirement Account; lifetime inflation-adjusted annuity from 60, minimum B$250 a month for citizens; untaxed as Brunei has no personal income tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BN', 1, 'retirement_accumulation_return_base', 0.025, NULL, 'assumption', 'Mix of BND deposits and a global equity index', 'https://www.bdcb.gov.bn/docs/home/BDCB%20SB%20-%2022nd%20October%202026%20publication.xlsx', '2026-10-31', 'About half global equity at 4.5% and half deposits at 0.6%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BN', 1, 'retirement_accumulation_return_high', 0.04, NULL, 'assumption', 'Mix of BND deposits and a global equity index', 'https://www.bdcb.gov.bn/docs/home/BDCB%20SB%20-%2022nd%20October%202026%20publication.xlsx', '2026-10-31', 'About 60% global equity at the high case and 40% sukuk/deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BN', 1, 'retirement_accumulation_return_low', 0.01, NULL, 'assumption', 'Mix of BND deposits and a global equity index', 'https://www.bdcb.gov.bn/docs/home/BDCB%20SB%20-%2022nd%20October%202026%20publication.xlsx', '2026-10-31', 'About 40% global equity at the low case and 60% deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BN', 1, 'retirement_age_default', 60, NULL, 'sourced', 'Tabung Amanah Pekerja (TAP), Skim Persaraan Kebangsaan FAQ', 'https://www.tap.com.bn/faq-skim-persaraan-kebangsaan', '2026-10-31', 'SPK annuity starts at 60; the Retirement Age Order 2010 set the minimum retirement age at 60 for men and women.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BN', 1, 'retirement_age_government', 60, NULL, 'sourced', 'Global Voices report on the Sultan''s decree raising the retirement age from 55 to 60', 'https://globalvoices.org/2009/08/07/brunei-retirement-age-now-at-60/', '2009-08-07', 'Secondary source (2009 report of the Sultan''s decree raising the retirement age from 55 to 60); the Retirement Age Order 2010 applies age 60 across employment including the civil service. Figure dates from 2009, older than 2025; no later change found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BN', 1, 'retirement_return_base', 0.006, NULL, 'assumption', 'BDCB average deposit rates', 'https://www.bdcb.gov.bn/docs/home/BDCB%20SB%20-%2022nd%20October%202026%20publication.xlsx', '2026-10-31', 'Base case near the 12-month deposit rate, below the 1-year government sukuk yield. Safe BND rates: 12-month deposit 0.535% (BDCB, Jun 2026), 1-year government sukuk 1.16%, 3-month 1.25% (Sep 2026); no personal income tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BN', 1, 'retirement_return_high', 0.0125, NULL, 'assumption', 'BDCB sukuk yields', 'https://www.bdcb.gov.bn/docs/home/BDCB%20SB%20-%2022nd%20October%202026%20publication.xlsx', '2026-10-31', 'High case at the 3-month government sukuk yield. Safe BND rates: 12-month deposit 0.535% (BDCB, Jun 2026), 1-year government sukuk 1.16%, 3-month 1.25% (Sep 2026); no personal income tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BN', 1, 'retirement_return_low', 0.003, NULL, 'assumption', 'BDCB average deposit rates', 'https://www.bdcb.gov.bn/docs/home/BDCB%20SB%20-%2022nd%20October%202026%20publication.xlsx', '2026-10-31', 'Low case near the 3-month deposit rate. Safe BND rates: 12-month deposit 0.535% (BDCB, Jun 2026), 1-year government sukuk 1.16%, 3-month 1.25% (Sep 2026); no personal income tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BN', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Brunei has no government savings certificate or retail savings bond for individuals; only short-term government sukuk (up to 1 year) are issued.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BN', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'BDCB publishes no average savings rate; the only published savings rates found were individual banks'' own rate pages, which we do not cite (ordinary savings pay roughly 0.1-0.2%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BN', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":10},{"year":2040,"value":5},{"year":2065,"value":2.4}]}', 'sourced', 'UN World Population Prospects 2024, medium variant (via populationpyramid.net); World Bank SP.POP.DPND.OL', 'https://www.populationpyramid.net/brunei-darussalam/2040/', '2024-07-31', '100 / old-age dependency ratio: 10.0 in 2025 (World Bank), 20.2 in 2040 and 42.3 in 2065 (UN WPP 2024). Figure refers to 2024, older than 2025; it is the latest available.', 0);
