INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BN', 1, 'tax_sanchayapatra_profit', 0, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Brunei: taxes on personal income', 'https://taxsummaries.pwc.com/brunei-darussalam/individual/taxes-on-personal-income', '2026-10-31', 'No personal income tax; any government security income of individuals is untaxed (no savings certificate exists).', 0);
