INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('BO', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"BO","iso3":"BOL","nameEn":"Bolivia","nameNative":"Bolivia","region":"latin_america_caribbean","languages":["es","qu","ay","gn"],"currency":{"code":"BOB","symbol":"Bs","decimals":2,"compact":"intl","usdRate":{"value":12.09,"status":"sourced","sourceName":"Banco Central de Bolivia, official exchange rate (tipo de cambio oficial)","sourceUrl":"https://www.bcb.gob.bo/?q=content/tipo-de-cambio-oficial-del-d%C3%B3lar-estadounidense","asOf":"2026-10-31","note":"Official rate (TCO) Bs 12.09 per US dollar for 31 October to 3 November 2026, shown on the BCB site; since June 2026 it is set daily as the weighted average of banks'' dollar purchases from clients (Resolución Ministerial 245/2026, BCB financial stability report, July 2026). It was fixed at 6.96 until 2025."}},"instruments":{"savings_account":{"available":true,"localName":"Caja de ahorro","localNameEn":"Savings account","sourceUrl":"https://www.bcb.gob.bo/webdocs/tasas_interes/28%20AH%20M%202026_0.pdf"},"fdr_3m":{"available":true,"localName":"Depósito a plazo fijo (DPF) a 90 días","localNameEn":"3-month fixed-term deposit","sourceUrl":"https://www.bcb.gob.bo/webdocs/tasas_interes/PUBLICACION%202026%2010%2019%20TASAS%20ACT%20Y%20PAS.xlsx"},"fdr_1y":{"available":true,"localName":"Depósito a plazo fijo (DPF) a 360 días","localNameEn":"1-year fixed-term deposit","sourceUrl":"https://www.bcb.gob.bo/webdocs/tasas_interes/PUBLICACION%202026%2010%2019%20TASAS%20ACT%20Y%20PAS.xlsx"},"dps":{"available":false,"localName":null,"note":"No standard monthly recurring deposit product with a published rate."},"sanchayapatra_5y":{"available":false,"localName":null,"note":"BCB direct sales of securities to individuals ended on 31 December 2025."},"tbill_91d":{"available":true,"localName":"Letras del BCB","localNameEn":"Central Bank of Bolivia letters (91 days)","note":"Auctioned weekly by the BCB; individuals buy through a stockbroker on the exchange.","sourceUrl":"https://www.bcb.gob.bo/webdocs/002_omas/subasta_28.10.26%20web.pdf"},"tbond_5y":{"available":true,"localName":"Bonos del Tesoro","localNameEn":"Treasury bonds (up to 1,820 days)","note":"Auctioned weekly by the BCB for the Treasury.","sourceUrl":"https://www.bcb.gob.bo/webdocs/002_omas/subasta_28.10.26%20web.pdf"},"tbond_10y":{"available":false,"localName":null,"note":"No Treasury bonds longer than 5 years were offered in 2026 auctions."},"equity_fund":{"available":true,"localName":"Fondo de inversión abierto","localNameEn":"Open-ended investment fund","note":"Funds supervised by ASFI invest mostly in term deposits and bonds; the local share market is very small."},"gold":{"available":true,"localName":"Oro","localNameEn":"Gold jewellery and bars","note":"No legal restriction on buying gold."}},"institutions":{"centralBank":{"name":"Banco Central de Bolivia","url":"https://www.bcb.gob.bo/"},"insuranceRegulator":{"name":"Autoridad de Fiscalización y Control de Pensiones y Seguros (APS)","url":"https://www.aps.gob.bo/"},"insuranceComplaints":{"name":"APS: consultas y reclamos","url":"https://www.aps.gob.bo/consultas-y-reclamos/"},"pensionScheme":{"name":"Gestora Pública de la Seguridad Social de Largo Plazo (Sistema Integral de Pensiones)","url":"https://www.gestora.bo/"},"oldAgeAllowance":{"name":"Renta Dignidad (APS statistics)","url":"https://www.aps.gob.bo/estadisticas/estadisticas-de-renta-dignidad/"},"publicHealthCover":{"name":"Sistema Único de Salud (SUS), Ministerio de Salud y Deportes","url":"https://www.minsalud.gob.bo/"},"statistics":{"name":"Instituto Nacional de Estadística (INE)","url":"https://www.ine.gob.bo/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BO', 1, 'bank_deposit_avg_rate', 0.037, NULL, 'sourced', 'Banco Central de Bolivia, Tasa de Referencia (TRe) 2026', 'https://www.bcb.gob.bo/webdocs/tasas_interes/otras_tasas/NUEVA%20TRE%20GESTION-2026_0.pdf', '2026-08-31', 'Reference rate TRe in bolivianos 3.70% (calculated on August 2026 deposits, in force October 2026); US-dollar TRe 0.34%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BO', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched BCB rate tables: consumer loan rates average about 18.5% (September 2026), but no credit card rate or legal cap is published.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BO', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched BCB and ASFI material: no per-depositor deposit insurance limit for Bolivia was found (a depositor protection fund exists for bank resolution, but no cover amount was confirmed). Verifier (2026-11-03) could not fill this either: web search budget exhausted and the APS, Gestora, SSA and ILO pages returned 403/404.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BO', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched BCB rate tables: no monthly recurring deposit product rate is published for Bolivia.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BO', 1, 'equity_return_base', 0.1, NULL, 'assumption', 'BCB weekly DPF 360-day median 7.74% (13% RC-IVA); Treasury 5-year 10.94%', 'https://www.bcb.gob.bo/webdocs/tasas_interes/PUBLICACION%202026%2010%2019%20TASAS%20ACT%20Y%20PAS.xlsx', '2026-10-31', 'Bolivia''s stock market is negligible, so the base case is a global index (about 7% in dollars) plus some boliviano depreciation, capped within 4 points of the 6.7% after-tax 1-year deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BO', 1, 'equity_return_high', 0.14, NULL, 'assumption', 'Global equity index in boliviano terms after the 2026 move to a flexible exchange rate', 'https://www.bcb.gob.bo/webdocs/politicasbcb/IEF%20jul26%20VF.pdf', '2026-10-31', 'High case with strong global shares and further depreciation of the boliviano.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BO', 1, 'equity_return_low', 0.03, NULL, 'assumption', 'No functioning local stock market; global equity index in boliviano terms', 'https://www.bcb.gob.bo/webdocs/politicasbcb/IEF%20jul26%20VF.pdf', '2026-10-31', 'Low case: global shares weak in dollars while the boliviano holds steady under the new flexible regime.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BO', 1, 'fdr_1y_rate', 0.0774, NULL, 'sourced', 'Banco Central de Bolivia, weekly deposit rates (semana 19-25 octubre 2026), DPF 360 days in bolivianos', 'https://www.bcb.gob.bo/webdocs/tasas_interes/PUBLICACION%202026%2010%2019%20TASAS%20ACT%20Y%20PAS.xlsx', '2026-10-25', 'Median 360-day term deposit rate across 11 banks (range 4.6-9.6%); 720-day deposits pay about 9.2%. The BCB financial stability report gives an average effective DPF rate of 6.77% for the first half of 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BO', 1, 'fdr_3m_rate', 0.0668, NULL, 'sourced', 'Banco Central de Bolivia, weekly deposit rates (semana 19-25 octubre 2026), DPF 90 days in bolivianos', 'https://www.bcb.gob.bo/webdocs/tasas_interes/PUBLICACION%202026%2010%2019%20TASAS%20ACT%20Y%20PAS.xlsx', '2026-10-25', 'Median of the 90-day term deposit rates reported that week by banks taking such deposits (5 banks, range 1.2-8.3%). Effective rates, weighted by amount.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BO', 1, 'fixed_income_return_base', 0.065, NULL, 'assumption', 'BCB weekly DPF 360-day median 7.74% (13% RC-IVA); Treasury 5-year 10.94%', 'https://www.bcb.gob.bo/webdocs/tasas_interes/PUBLICACION%202026%2010%2019%20TASAS%20ACT%20Y%20PAS.xlsx', '2026-10-31', 'Base case: 1-year term deposits at about 7.7% less 13% RC-IVA, about 6.7%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BO', 1, 'fixed_income_return_high', 0.09, NULL, 'assumption', 'BCB auction 28 Oct 2026: Treasury bonds 10.45-10.94%; 720-day DPF about 9.2%', 'https://www.bcb.gob.bo/webdocs/002_omas/subasta_28.10.26%20web.pdf', '2026-10-31', 'High case: longer term deposits or Treasury bonds held to maturity after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BO', 1, 'fixed_income_return_low', 0.04, NULL, 'assumption', 'BCB savings rate 1.01%; DPF rates 6.7-7.7%', 'https://www.bcb.gob.bo/webdocs/tasas_interes/PUBLICACION%202026%2010%2019%20TASAS%20ACT%20Y%20PAS.xlsx', '2026-10-31', 'Low case: a mix of savings accounts and shorter term deposits after 13% RC-IVA.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BO', 1, 'goal_inflation_education', 0.08, NULL, 'assumption', 'BCB CPI September 2026 (5.7%); planning inflation 7%', 'https://www.bcb.gob.bo/?q=indicadores_inflacion', '2026-10-31', 'No separate education CPI series was read; headline projection plus one point.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BO', 1, 'goal_inflation_health', 0.085, NULL, 'assumption', 'BCB CPI September 2026 (5.7%); planning inflation 7%', 'https://www.bcb.gob.bo/?q=indicadores_inflacion', '2026-10-31', 'No separate medical CPI series was read; we plan with the 7% projection plus 1.5 points for private medical costs.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BO', 1, 'gold_return_base', 0.085, NULL, 'assumption', 'BCB official exchange rate Bs 12.09 per USD (flexible since June 2026)', 'https://www.bcb.gob.bo/?q=content/tipo-de-cambio-oficial-del-d%C3%B3lar-estadounidense', '2026-10-31', 'Long-run dollar gold trend of about 4.5% plus about 4% a year of expected boliviano depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BO', 1, 'gold_return_high', 0.15, NULL, 'assumption', 'BCB official exchange rate Bs 12.09 per USD (flexible since June 2026)', 'https://www.bcb.gob.bo/?q=content/tipo-de-cambio-oficial-del-d%C3%B3lar-estadounidense', '2026-10-31', 'High case with strong dollar gold and faster depreciation, as in 2025-2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BO', 1, 'gold_return_low', 0.02, NULL, 'assumption', 'BCB official exchange rate Bs 12.09 per USD (flexible since June 2026)', 'https://www.bcb.gob.bo/?q=content/tipo-de-cambio-oficial-del-d%C3%B3lar-estadounidense', '2026-10-31', 'Low case: weak dollar gold and a stable boliviano.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BO', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'Bolivian labour law provides a length-of-service indemnity (Ley General del Trabajo art. 13), but the legal text and its current rules could not be opened from an official source, so the rule was not recorded. Verifier (2026-11-03) could not fill this either: web search budget exhausted and the APS, Gestora, SSA and ILO pages returned 403/404.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BO', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched Ministry of Health and public sources: no official typical private hospital bill is published.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BO', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched APS and public sources: no published private health insurance premiums by age.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BO', 1, 'inflation_cpi', 0.057, NULL, 'sourced', 'Banco Central de Bolivia, indicadores de inflación (INE CPI, base 2016)', 'https://www.bcb.gob.bo/?q=indicadores_inflacion', '2026-09-30', '12-month CPI inflation 5.70% in September 2026 (monthly 0.85%, year to date 3.88%), down from 19.5% for 2025 (World Bank).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BO', 1, 'inflation_projection', 0.07, NULL, 'assumption', 'BCB CPI Sept 2026 (5.7%); World Bank CPI 2021-2025: 0.7, 1.7, 2.6, 5.1, 19.5%', 'https://data.worldbank.org/indicator/FP.CPI.TOTL.ZG?locations=BO', '2026-10-31', 'The 2021-2025 average is 5.9% and the boliviano has just moved to a flexible rate, so we plan with 7%, above the current 5.7% to allow for further pass-through.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BO', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Life insurance is sold in Bolivia, but no regulator or public source publishes term premium rates by age.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BO', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched APS insurance statistics and the BCB financial stability report: no industry-wide life claim settlement ratio is published.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BO', 1, 'life_expectancy', 68.739, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=BO', '2024-12-31', 'UN WPP 2024 (via populationpyramid.net) gives 69.1 for 2026 (men 66.6, women 71.7).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BO', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":18.45,"men":17.3,"women":19.6},{"age":65,"total":15,"men":14.1,"women":15.9},{"age":70,"total":11.9,"men":11.2,"women":12.6},{"age":80,"total":7,"men":6.6,"women":7.4}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/bolivia-plurinational-state-of/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BO', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'Renta Dignidad exists (APS statistics page), but its eligibility rules could not be read from an official page (decree DS 29400 on the APS site did not open). Verifier (2026-11-03) could not fill this either: web search budget exhausted and the APS, Gestora, SSA and ILO pages returned 403/404.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BO', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'Bolivia pays the universal non-contributory Renta Dignidad (the APS publishes its statistics at https://www.aps.gob.bo/estadisticas/estadisticas-de-renta-dignidad/), but the current monthly amount could not be read from an official page. Verifier (2026-11-03) could not fill this either: web search budget exhausted and the APS, Gestora, SSA and ILO pages returned 403/404.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BO', 1, 'oop_health_share', 0.2732, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=BO', '2023-12-31', 'Figure is for 2023 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BO', 1, 'policy_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The BCB has no single policy rate; it steers through open market operations (91-day BCB letters 9.20%, 273-day 10.41% on 28 October 2026) and a 7-day repo base premium of 13.5% (BCB auction results).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BO', 1, 'public_pension_scheme', NULL, NULL, 'missing', '', '', '2026-10-31', 'The contributory Sistema Integral de Pensiones (Ley 065, run by the public Gestora) exists, but its rules could not be read from an official page (APS law PDFs and the Gestora site did not open). Verifier (2026-11-03) could not fill this either: web search budget exhausted and the APS, Gestora, SSA and ILO pages returned 403/404.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BO', 1, 'retirement_accumulation_return_base', 0.08, NULL, 'assumption', 'BCB DPF rates; global equity in boliviano terms', 'https://www.bcb.gob.bo/webdocs/tasas_interes/PUBLICACION%202026%2010%2019%20TASAS%20ACT%20Y%20PAS.xlsx', '2026-10-31', 'Base case: half term deposits or bonds at 7-10% and half global equity, about one point above planned inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BO', 1, 'retirement_accumulation_return_high', 0.11, NULL, 'assumption', 'BCB DPF rates; global equity in boliviano terms', 'https://www.bcb.gob.bo/webdocs/tasas_interes/PUBLICACION%202026%2010%2019%20TASAS%20ACT%20Y%20PAS.xlsx', '2026-10-31', 'High case with strong equity returns and long bonds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BO', 1, 'retirement_accumulation_return_low', 0.05, NULL, 'assumption', 'BCB DPF rates; global equity in boliviano terms', 'https://www.bcb.gob.bo/webdocs/tasas_interes/PUBLICACION%202026%2010%2019%20TASAS%20ACT%20Y%20PAS.xlsx', '2026-10-31', 'Low case for a balanced mix if real deposit rates stay near zero.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BO', 1, 'retirement_age_default', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Sistema Integral de Pensiones (Ley 065 of 2010) sets the old-age pension age, but the law text on the APS site and the Gestora site could not be opened, so the age was not confirmed from a source. Verifier (2026-11-03) could not fill this either: web search budget exhausted and the APS, Gestora, SSA and ILO pages returned 403/404.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BO', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'No source read on a compulsory retirement age for Bolivian public servants; public employees are covered by the same Sistema Integral de Pensiones. Verifier (2026-11-03) could not fill this either: web search budget exhausted and the APS, Gestora, SSA and ILO pages returned 403/404.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BO', 1, 'retirement_return_base', 0.065, NULL, 'assumption', 'BCB weekly DPF 360-day median 7.74% (13% RC-IVA); Treasury 5-year 10.94%', 'https://www.bcb.gob.bo/webdocs/tasas_interes/PUBLICACION%202026%2010%2019%20TASAS%20ACT%20Y%20PAS.xlsx', '2026-10-31', 'Base case capped at the 1-year term deposit rate after 13% RC-IVA (7.74% x 0.87 = 6.7%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BO', 1, 'retirement_return_high', 0.085, NULL, 'assumption', 'BCB auction 28 Oct 2026: Treasury bonds 10.45-10.94%', 'https://www.bcb.gob.bo/webdocs/002_omas/subasta_28.10.26%20web.pdf', '2026-10-31', 'High case: a ladder of Treasury bonds and 2-year deposits after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BO', 1, 'retirement_return_low', 0.04, NULL, 'assumption', 'BCB savings rate 1.01%; DPF rates 6.7-7.7%', 'https://www.bcb.gob.bo/webdocs/tasas_interes/PUBLICACION%202026%2010%2019%20TASAS%20ACT%20Y%20PAS.xlsx', '2026-10-31', 'Low case: mostly savings and short deposits after 13% RC-IVA.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BO', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The BCB ended its retail direct-sale securities for individuals on 31 December 2025 to concentrate operations in open market auctions (BCB home page notice, https://www.bcb.gob.bo/); no other government savings certificate for individuals exists.', 1);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BO', 1, 'savings_account_rate', 0.0101, NULL, 'sourced', 'Banco Central de Bolivia, tasas de interés pasivas del sistema financiero (cajas de ahorro), 2026', 'https://www.bcb.gob.bo/webdocs/tasas_interes/28%20AH%20M%202026_0.pdf', '2026-09-30', 'Nominal savings rate in bolivianos at multiple (commercial) banks 1.01% in September 2026 (system 1.70%; cooperatives 2.25%). Savings in US dollars pay about 0.01%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BO', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":11.3},{"year":2040,"value":8.5},{"year":2065,"value":4.7}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/bolivia-plurinational-state-of/2040/', '2025-12-31', '100 / old-age dependency ratio: 8.86 (2025, World Bank), 11.7 (2040) and 21.1 (2065, populationpyramid.net/bolivia-plurinational-state-of/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BO', 1, 'tax_bank_interest', 0.13, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Bolivia: Individual - Income determination and Taxes on personal income', 'https://taxsummaries.pwc.com/bolivia/individual/income-determination', '2026-07-21', 'Bolivian-source investment income is taxed as ordinary income under RC-IVA, whose rate is 13% (https://taxsummaries.pwc.com/bolivia/individual/taxes-on-personal-income, last reviewed 21 July 2026). PwC does not mention any exemption for term deposits; none was verified.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BO', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No retail government savings certificate exists since BCB direct sales ended on 31 December 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BO', 1, 'tbill_91d_rate', 0.092, NULL, 'sourced', 'Banco Central de Bolivia, results of the securities auction of 28 October 2026', 'https://www.bcb.gob.bo/webdocs/002_omas/subasta_28.10.26%20web.pdf', '2026-10-28', '91-day BCB letter (LB-MN) awarded at 9.20%; the Treasury did not offer bills under one year that week (its shortest bond, 364 days, paid 10.45%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BO', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'BCB auctions of 28 October 2026 offered Treasury bonds only up to 1,820 days (5 years); no 10-year government yield is published.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BO', 1, 'tbond_5y_rate', 0.1094, NULL, 'sourced', 'Banco Central de Bolivia, results of the securities auction of 28 October 2026 (Treasury bonds)', 'https://www.bcb.gob.bo/webdocs/002_omas/subasta_28.10.26%20web.pdf', '2026-10-28', 'Treasury bond BT-MN 1,820 days (5 years) awarded at 10.94%.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('BR', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"BR","iso3":"BRA","nameEn":"Brazil","nameNative":"Brasil","region":"latin_america_caribbean","languages":["pt","en"],"currency":{"code":"BRL","symbol":"R$","decimals":2,"compact":"intl","usdRate":{"value":5.4212,"status":"sourced","sourceName":"Banco Central do Brasil, PTAX US dollar selling rate (SGS series 1)","sourceUrl":"https://api.bcb.gov.br/dados/serie/bcdata.sgs.1/dados/ultimos/12?formato=json","asOf":"2026-10-30","note":"R$5.4212 per US dollar on 30 October 2026; World Bank 2025 average 5.59."}},"instruments":{"savings_account":{"available":true,"localName":"Caderneta de poupança","localNameEn":"Savings account (poupança)","note":"Rate set by law (0.5% a month plus TR while the Selic is above 8.5%); tax-free for individuals and covered by the FGC.","sourceUrl":"https://api.bcb.gov.br/dados/serie/bcdata.sgs.195/dados/ultimos/12?formato=json"},"fdr_3m":{"available":true,"localName":"CDB (Certificado de Depósito Bancário)","localNameEn":"Bank certificate of deposit (CDB), 3 months","note":"Usually priced as a percentage of the CDI; covered by the FGC up to R$250,000.","sourceUrl":"https://investnews.com.br/investimentos/cdbs-marco-pagam-mais-guerra/"},"fdr_1y":{"available":true,"localName":"CDB (Certificado de Depósito Bancário)","localNameEn":"Bank certificate of deposit (CDB), 1 year","sourceUrl":"https://investnews.com.br/investimentos/cdbs-marco-pagam-mais-guerra/"},"dps":{"available":false,"localName":null,"localNameEn":"Recurring deposit","note":"No standard monthly recurring-deposit product; regular saving is done through poupança, CDBs or Tesouro Direto."},"sanchayapatra_5y":{"available":true,"localName":"Tesouro Direto (Tesouro Prefixado, Tesouro IPCA+)","localNameEn":"Tesouro Direto retail government bonds","note":"The National Treasury''s programme selling government bonds to individuals online from about R$30; includes Tesouro Renda+ for retirement income and Tesouro Educa+ for education.","sourceUrl":"https://www.tesourotransparente.gov.br/ckan/dataset/taxas-dos-titulos-ofertados-pelo-tesouro-direto"},"tbill_91d":{"available":true,"localName":"Tesouro Prefixado (LTN)","localNameEn":"Fixed-rate Treasury bill (LTN)","note":"No 91-day bill is issued; the shortest LTN line is used, and Tesouro Selic (LFT) is the floating-rate alternative.","sourceUrl":"https://www.tesourotransparente.gov.br/ckan/dataset/taxas-dos-titulos-ofertados-pelo-tesouro-direto"},"tbond_5y":{"available":true,"localName":"Tesouro Prefixado / Tesouro IPCA+","localNameEn":"Fixed-rate or inflation-linked Treasury bond","sourceUrl":"https://www.tesourotransparente.gov.br/ckan/dataset/taxas-dos-titulos-ofertados-pelo-tesouro-direto"},"tbond_10y":{"available":true,"localName":"Tesouro Prefixado com Juros Semestrais (NTN-F)","localNameEn":"Fixed-rate Treasury bond with semi-annual coupons","sourceUrl":"https://www.tesourotransparente.gov.br/ckan/dataset/taxas-dos-titulos-ofertados-pelo-tesouro-direto"},"equity_fund":{"available":true,"localName":"Fundo de índice (ETF) / fundo de ações","localNameEn":"Index fund (ETF) or equity mutual fund","note":"Ibovespa index funds and equity funds are widely available to retail investors; regulated by the CVM."},"gold":{"available":true,"localName":"Ouro ativo financeiro","localNameEn":"Investment gold (bars)","note":"Gold as a financial asset can be bought legally in bars through authorised dealers; gold is also traded on the stock exchange."}},"institutions":{"centralBank":{"name":"Banco Central do Brasil","url":"https://www.bcb.gov.br/"},"insuranceRegulator":{"name":"Superintendência de Seguros Privados (SUSEP)","url":"https://www.gov.br/susep/pt-br","note":"Health plans are regulated separately by the ANS."},"insuranceComplaints":{"name":"Consumidor.gov.br (federal consumer complaints platform, used for insurers supervised by SUSEP)","url":"https://www.consumidor.gov.br/","note":"Complain to the insurer and its ombudsman first."},"pensionScheme":{"name":"Instituto Nacional do Seguro Social (INSS), General Social Security Regime","url":"https://www.gov.br/inss/pt-br"},"oldAgeAllowance":{"name":"Benefício de Prestação Continuada (BPC) for older people, INSS","url":"https://www.gov.br/inss/pt-br/direitos-e-deveres/beneficios-assistenciais/beneficio-assistencial-a-pessoa-idosa-bpc-loas"},"publicHealthCover":{"name":"Sistema Único de Saúde (SUS), Ministry of Health","url":"https://www.gov.br/saude/pt-br"},"depositInsurance":{"name":"Fundo Garantidor de Créditos (FGC)","url":"https://www.fgc.org.br/"},"statistics":{"name":"Instituto Brasileiro de Geografia e Estatística (IBGE)","url":"https://www.ibge.gov.br/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BR', 1, 'bank_deposit_avg_rate', 0.077, NULL, 'sourced', 'World Bank WDI FR.INR.DPST (deposit interest rate)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=BR', '2024-12-31', '7.70% for 2024 (latest available; older than 2025 and well below today''s CDI of 13.65%); the central bank does not publish a weighted average deposit rate series we could read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BR', 1, 'credit_card_rate_cap', 1.0028, NULL, 'sourced', 'Banco Central do Brasil, average interest rate, individuals, credit card total (SGS series 22024)', 'https://api.bcb.gov.br/dados/serie/bcdata.sgs.22024/dados/ultimos/12?formato=json', '2026-09-30', 'Typical rate, all credit card credit: 100.28% a year in September 2026. Revolving card credit averaged 451.71% a year (SGS 22022) and instalment card credit 193.02% (SGS 22023). Since January 2024 the law caps total interest and charges on revolving and instalment card debt at 100% of the original debt.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BR', 1, 'deposit_insurance_limit', 250000, NULL, 'sourced', 'FGC (Fundo Garantidor de Créditos) regulation, approved by the National Monetary Council, ordinary guarantee', 'https://fgc.org.br/documents/d/asset-library-52554/regulamento-fgc', '2026-01-31', 'Deposits, CDBs, poupança and similar instruments are guaranteed up to R$250,000 per person per institution or financial conglomerate, with a R$1 million overall cap per person in each 4-year period.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BR', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No standard monthly recurring-deposit product with a published rate exists in Brazil; regular saving goes into poupança, CDBs or Tesouro Direto.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BR', 1, 'equity_return_base', 0.11, NULL, 'assumption', 'Ibovespa 10-year record (Trading Economics); Tesouro Selic after 15% tax about 11.6%', 'https://tradingeconomics.com/brazil/stock-market', '2026-10-31', 'Base case kept at about the after-tax safe rate because the Ibovespa, a total-return index, has not clearly beaten the CDI over 10 years; well under the safe rate plus 4 points.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BR', 1, 'equity_return_high', 0.15, NULL, 'assumption', 'Ibovespa record high 209,713 in October 2026 (Trading Economics)', 'https://tradingeconomics.com/brazil/stock-market', '2026-10-31', 'High case: Brazilian shares earn a real equity premium as interest rates fall from today''s high levels.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BR', 1, 'equity_return_low', 0.07, NULL, 'assumption', 'Ibovespa 167,922 on 30 Oct 2026 (Trading Economics), roughly 10% a year in total-return terms over 10 years, below the CDI over most of that period', 'https://tradingeconomics.com/brazil/stock-market', '2026-10-31', 'Low case: Brazilian shares again fail to beat after-tax government bonds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BR', 1, 'fdr_1y_rate', 0.131, NULL, 'sourced', 'InvestNews survey of new CDB issues (large banks paid 95.94% of the CDI at 12 months, March 2026) applied to the CDI of 13.65% (BCB SGS 4389, 30 Oct 2026)', 'https://investnews.com.br/investimentos/cdbs-marco-pagam-mais-guerra/', '2026-10-30', 'Large banks paid on average 95.94% of the CDI on 12-month CDBs in March 2026 (small and medium banks 101.74%; secondary news source, survey from March 2026), about 13.1% a year at today''s CDI. Interest is taxed at source on a sliding scale, 17.5% for a 1-year CDB.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BR', 1, 'fdr_3m_rate', 0.136, NULL, 'sourced', 'InvestNews survey of new CDB issues (large banks paid 99.79% of the CDI at 3 months, March 2026) applied to the CDI of 13.65% (BCB SGS 4389, 30 Oct 2026)', 'https://investnews.com.br/investimentos/cdbs-marco-pagam-mais-guerra/', '2026-10-30', 'Brazilian term deposits (CDB) are mostly priced as a percentage of the CDI overnight rate; large banks paid on average 99.79% of the CDI on 3-month issues in March 2026 (secondary news source; the survey is from March 2026 and no central bank series of CDB rates is published), which at today''s CDI gives about 13.6% a year before tax (22.5% withholding for terms up to 180 days).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BR', 1, 'fixed_income_return_base', 0.105, NULL, 'assumption', 'Tesouro Selic and CDBs at about the CDI of 13.65% less 15-17.5% tax (BCB SGS 4389; PwC)', 'https://api.bcb.gov.br/dados/serie/bcdata.sgs.4389/dados/ultimos/12?formato=json', '2026-10-31', 'Base case: floating-rate government bonds and CDBs after tax, allowing for the Selic to keep falling from 13.75% over the coming years.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BR', 1, 'fixed_income_return_high', 0.13, NULL, 'assumption', 'Tesouro Prefixado 2031 at 15.30% less 15% tax = 13.0% (Tesouro Direto)', 'https://www.tesourotransparente.gov.br/ckan/dataset/taxas-dos-titulos-ofertados-pelo-tesouro-direto', '2026-10-31', 'High case: locking in today''s high fixed rates on 4-10 year government bonds and holding to maturity.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BR', 1, 'fixed_income_return_low', 0.08, NULL, 'assumption', 'Poupança about 8.35% a year, tax-free (BCB SGS 195)', 'https://api.bcb.gov.br/dados/serie/bcdata.sgs.195/dados/ultimos/12?formato=json', '2026-10-31', 'Low case: poupança and short CDBs after tax as the Selic is cut; poupança falls to 70% of the Selic once the Selic is 8.5% or less.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BR', 1, 'goal_inflation_education', 0.06, NULL, 'assumption', 'IBGE IPCA group ''Educação'': 5.95% over 12 months to September 2026 (SIDRA 7060)', 'https://apisidra.ibge.gov.br/values/t/7060/n1/all/v/2265/p/last%201/c315/7169,7660,7766', '2026-10-31', 'Education prices rose 5.95% against 4.58% for all items; planning uses 6%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BR', 1, 'goal_inflation_health', 0.06, NULL, 'assumption', 'IBGE IPCA group ''Saúde e cuidados pessoais'': 5.75% over 12 months to September 2026 (SIDRA 7060)', 'https://apisidra.ibge.gov.br/values/t/7060/n1/all/v/2265/p/last%201/c315/7169,7660,7766', '2026-10-31', 'Health and personal care prices rose 5.75% against 4.58% for all items; planning uses 6%, about 2 points above general inflation, since health plan prices tend to rise faster.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BR', 1, 'gold_return_base', 0.07, NULL, 'assumption', 'Gold USD price history (Trading Economics); inflation target 3% in Brazil vs about 2% in the US', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Base case: gold rises roughly with world inflation plus a little in dollars, and the real loses about 2-3% a year against the dollar over the long run.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BR', 1, 'gold_return_high', 0.12, NULL, 'assumption', 'Gold USD price history (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'High case: a repeat of gold''s strong 2005-2025 trend in reais.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BR', 1, 'gold_return_low', 0.02, NULL, 'assumption', 'Gold USD price history (Trading Economics); BRL 5.42 per USD (BCB PTAX, 30 Oct 2026)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Low case: gold stalls after the 2025-26 rally and the real holds its value.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BR', 1, 'gratuity_rule', NULL, '{"daysPerYear":31,"daysPerYearAfter":null,"afterYears":null,"daysPerMonth":30}', 'sourced', 'Ministério do Trabalho e Emprego, FGTS (employer deposits 8% of pay into the worker''s FGTS account)', 'https://www.gov.br/trabalho-e-emprego/pt-br/servicos/trabalhador/fgts', '2026-10-31', 'No days-per-year gratuity, but every employer must deposit 8% of monthly pay (also on the 13th salary) into the worker''s FGTS account, about 31 days of wages a year, which can be drawn on retirement or dismissal without cause (plus a 40% employer fine on dismissal). The fund earns TR + 3% a year, so actual balances depend on pay history.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BR', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'Hospital care is free in the public SUS; no official figure for the out-of-pocket cost of a major private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BR', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Private health plans are priced per person and age band (regulated by ANS), not per sum insured; no public premium table per R$100,000 of cover exists.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BR', 1, 'inflation_cpi', 0.0458, NULL, 'sourced', 'IBGE, IPCA (SIDRA table 7060), 12-month change to September 2026', 'https://apisidra.ibge.gov.br/values/t/7060/n1/all/v/2265/p/last%201/c315/7169,7660,7766', '2026-09-30', 'IPCA rose 0.82% in September 2026 and 4.58% over 12 months (4.22% in August), above the 4.5% upper tolerance limit; also BCB SGS series 13522. World Bank 2025 average 5.0%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BR', 1, 'inflation_projection', 0.04, NULL, 'assumption', 'BCB/CMN continuous inflation target 3% (tolerance +/-1.5 pts); IPCA 2021-2025 averaged about 6%', 'https://www.bcb.gov.br/controleinflacao/metainflacao', '2026-10-31', 'The 3% target has been missed upward in most recent years (IPCA 4.58% in September 2026), so planning uses 4%, between the target and the 5-year average.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BR', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life insurance (seguro de vida) is widely sold in Brazil, but no regulator or other public table of premiums per R$1,000 of cover by age was found; only company quotes exist.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BR', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'SUSEP publishes market statistics on premiums and claims paid, but no industry-wide share of life claims paid versus claims made was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BR', 1, 'life_expectancy', 76.6, NULL, 'sourced', 'IBGE, Tábua completa de mortalidade para o Brasil 2024', 'https://biblioteca.ibge.gov.br/visualizacao/periodicos/3097/tcmb_2024.pdf', '2024-12-31', 'Life expectancy at birth 76.6 years in 2024 (men 73.3, women 79.9), published November 2025 (latest; older than 2025). UN WPP via georank gives 76.4 for 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BR', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":22.6,"men":20.8,"women":24.2},{"age":65,"total":18.8,"men":17.2,"women":20.1},{"age":70,"total":15.2,"men":14,"women":16.3},{"age":80,"total":9,"men":8.3,"women":9.5}]}', 'sourced', 'IBGE, Tábua completa de mortalidade para o Brasil 2024', 'https://biblioteca.ibge.gov.br/visualizacao/periodicos/3097/tcmb_2024.pdf', '2024-12-31', 'Expectation of remaining life at exact ages from the 2024 IBGE life tables for both sexes, men and women (latest; older than 2025). UN WPP 2026 via georank gives 18.2 years at 65.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BR', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":65,"womenAge":65,"over90Monthly":null,"meansTested":true}', 'sourced', 'INSS, Benefício assistencial à pessoa idosa (BPC-Loas)', 'https://www.gov.br/inss/pt-br/direitos-e-deveres/beneficios-assistenciais/beneficio-assistencial-a-pessoa-idosa-bpc-loas', '2026-10-31', 'Brazilian (or Portuguese) nationals aged 65 or over, men and women, with family income per person of at most 1/4 of the minimum wage (about R$405 in 2026), registered in the CadÚnico.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BR', 1, 'old_age_allowance_monthly', 1621, NULL, 'sourced', 'Banco Central do Brasil, minimum wage series (SGS 1619): R$1,621 in 2026; INSS, Benefício assistencial à pessoa idosa (BPC-Loas) pays one minimum wage', 'https://api.bcb.gov.br/dados/serie/bcdata.sgs.1619/dados/ultimos/12?formato=json', '2026-01-01', 'BPC pays one minimum wage a month (R$1,621 from 1 January 2026, Decree 12.797 of 23 December 2025) to people aged 65+ whose family income is at most a quarter of the minimum wage per person; no contributions needed, no 13th payment.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BR', 1, 'oop_health_share', 0.2623, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=BR', '2023-12-31', 'Out-of-pocket spending was 26.2% of current health expenditure in 2023 (latest available; older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BR', 1, 'policy_rate', 0.1375, NULL, 'sourced', 'Banco Central do Brasil, Selic target (SGS series 432)', 'https://api.bcb.gov.br/dados/serie/bcdata.sgs.432/dados/ultimos/12?formato=json', '2026-09-17', 'Copom cut the Selic target by 0.25 pt to 13.75% at its 15-16 September 2026 meeting (in force from 17 September); there was no October meeting. Cuts in 2026 from 15.00% in March, April, June, August and September.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BR', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":65,"nomineeUntilAge":null,"inflationLinked":true,"taxFree":false}', 'sourced', 'INSS, Aposentadoria por idade urbana (General Social Security Regime, RGPS)', 'https://www.gov.br/inss/pt-br/direitos-e-deveres/aposentadorias/aposentadoria-por-idade-urbana', '2026-10-31', 'Compulsory contributory RGPS pension run by the INSS: 65 for men and 62 for women, minimum 15 years of contributions (20 for men joining after November 2019); the benefit starts at 60% of average earnings plus 2% per extra year, is never below the minimum wage, is adjusted yearly for inflation (INPC) and is taxed as income above the exemption limit.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BR', 1, 'retirement_accumulation_return_base', 0.105, NULL, 'assumption', 'Fixed income base 10.5%; equity base 11%', 'https://tradingeconomics.com/brazil/stock-market', '2026-10-31', 'Base case: roughly half shares at 11% and half safe fixed income at about 10.5% after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BR', 1, 'retirement_accumulation_return_high', 0.135, NULL, 'assumption', 'Equity high 15%; after-tax long government bonds 13%', 'https://www.tesourotransparente.gov.br/ckan/dataset/taxas-dos-titulos-ofertados-pelo-tesouro-direto', '2026-10-31', 'High case for a growth-leaning balanced mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BR', 1, 'retirement_accumulation_return_low', 0.08, NULL, 'assumption', 'After-tax poupança and CDBs; Ibovespa 10-year record (Trading Economics)', 'https://tradingeconomics.com/brazil/stock-market', '2026-10-31', 'Low case for a balanced mix if shares lag and rates fall.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BR', 1, 'retirement_age_default', 65, NULL, 'sourced', 'INSS, Aposentadoria por idade urbana', 'https://www.gov.br/inss/pt-br/direitos-e-deveres/aposentadorias/aposentadoria-por-idade-urbana', '2026-10-31', 'Urban old-age pension at 65 for men and 62 for women (women''s age reached 62 in 2023), with at least 15 years of contributions (20 years for men who joined after 13 November 2019), under Constitutional Amendment 103/2019.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BR', 1, 'retirement_age_government', 65, NULL, 'sourced', 'UFRB (federal university) staff guide ''Aposentadoria Ativa 2026'', rules of Constitutional Amendment 103/2019', 'https://ufrb.edu.br/progep/images/Cartilha%20Aposentadoria%20Ativa%20-%202026.pdf', '2026-01-31', 'Federal civil servants retire voluntarily at 65 (men) or 62 (women) with 25 years of contributions, 10 in public service; retirement is compulsory at 75. State and municipal schemes may differ.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BR', 1, 'retirement_return_base', 0.1, NULL, 'assumption', '1-year CDB 13.1% less 17.5% tax = 10.8%; 2-month LTN 13.48% less 22.5% tax = 10.4% (Tesouro Direto)', 'https://www.tesourotransparente.gov.br/ckan/dataset/taxas-dos-titulos-ofertados-pelo-tesouro-direto', '2026-10-31', 'Base case kept below the after-tax 1-year deposit and short bill rates, allowing for the Selic to keep falling.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BR', 1, 'retirement_return_high', 0.12, NULL, 'assumption', 'Tesouro IPCA+ and Prefixado bonds at 15.2-15.3% (or IPCA + 7.3-7.9%) less 15% tax (Tesouro Direto)', 'https://www.tesourotransparente.gov.br/ckan/dataset/taxas-dos-titulos-ofertados-pelo-tesouro-direto', '2026-10-31', 'High case: a ladder of medium and long government bonds bought at today''s high yields.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BR', 1, 'retirement_return_low', 0.08, NULL, 'assumption', 'Poupança about 8.35% tax-free (BCB SGS 195)', 'https://api.bcb.gov.br/dados/serie/bcdata.sgs.195/dados/ultimos/12?formato=json', '2026-10-31', 'Low case: savings accounts and short deposits as interest rates fall.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BR', 1, 'sanchayapatra_5y_rate', 0.153, NULL, 'sourced', 'Tesouro Nacional, Tesouro Direto rates (Tesouro Transparente dataset), Tesouro Prefixado 01/01/2031, purchase rate', 'https://www.tesourotransparente.gov.br/ckan/dataset/taxas-dos-titulos-ofertados-pelo-tesouro-direto', '2026-10-30', 'Tesouro Direto is the government''s retail bond programme for individuals (minimum about 1% of a bond). The fixed-rate Tesouro Prefixado 2031 (about 4 years) was offered at 15.30% a year on 30 October 2026; inflation-linked Tesouro IPCA+ 2032 paid IPCA + 7.89%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BR', 1, 'savings_account_rate', 0.0835, NULL, 'sourced', 'Banco Central do Brasil, savings account (poupança) monthly yield, SGS series 195', 'https://api.bcb.gov.br/dados/serie/bcdata.sgs.195/dados/ultimos/12?formato=json', '2026-10-28', 'Poupança paid 0.67% a month for deposits made on 28 October 2026 (0.5% a month plus the TR, because the Selic is above 8.5%), about 8.35% a year, exempt from income tax for individuals.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BR', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":6.02},{"year":2040,"value":3.76},{"year":2065,"value":2.07}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/brazil/2040/', '2025-12-31', '100 / old-age dependency ratio: 16.6 (2025, World Bank), 26.6 (2040) and 48.3 (2065, populationpyramid.net/brazil/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BR', 1, 'tax_bank_interest', 0.175, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Brazil income determination (reviewed 23 Sep 2026)', 'https://taxsummaries.pwc.com/brazil/individual/income-determination', '2026-09-23', 'PwC confirms interest on Brazilian investments is withheld at source at 15% to 22.5% depending on the term; the bands (22.5% up to 180 days, 20% to 360, 17.5% to 720, 15% beyond) are set by Law 11.033/2004, so 17.5% applies to a typical 1-year CDB. Poupança interest is exempt for individuals.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BR', 1, 'tax_sanchayapatra_profit', 0.15, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Brazil income determination (reviewed 23 Sep 2026)', 'https://taxsummaries.pwc.com/brazil/individual/income-determination', '2026-09-23', 'Tesouro Direto returns follow the same withholding scale (22.5% to 15% by holding period); a bond held more than 2 years, such as a 5-year Tesouro Prefixado, pays 15%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BR', 1, 'tbill_91d_rate', 0.1348, NULL, 'sourced', 'Tesouro Nacional, Tesouro Direto rates (Tesouro Transparente dataset), Tesouro Prefixado 01/01/2027 (LTN), purchase rate', 'https://www.tesourotransparente.gov.br/ckan/dataset/taxas-dos-titulos-ofertados-pelo-tesouro-direto', '2026-10-30', 'Brazil has no 91-day bill; the shortest zero-coupon Treasury bill (LTN) maturing 1 January 2027 (about 2 months) was offered at 13.48% a year on 30 October 2026. The CDI overnight rate was 13.65% (BCB SGS 4389).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BR', 1, 'tbond_10y_rate', 0.1523, NULL, 'sourced', 'Tesouro Nacional, Tesouro Direto rates (Tesouro Transparente dataset), Tesouro Prefixado com Juros Semestrais 01/01/2037 (NTN-F)', 'https://www.tesourotransparente.gov.br/ckan/dataset/taxas-dos-titulos-ofertados-pelo-tesouro-direto', '2026-10-30', 'The 2037 fixed-rate bond with semi-annual coupons (about 10 years) was offered at 15.23% a year on 30 October 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BR', 1, 'tbond_5y_rate', 0.153, NULL, 'sourced', 'Tesouro Nacional, Tesouro Direto rates (Tesouro Transparente dataset), Tesouro Prefixado 01/01/2031 and Prefixado com Juros Semestrais 2031', 'https://www.tesourotransparente.gov.br/ckan/dataset/taxas-dos-titulos-ofertados-pelo-tesouro-direto', '2026-10-30', 'About 4.2-year fixed-rate Treasury bonds offered at 15.29-15.30% a year on 30 October 2026 (Tesouro Direto purchase rates, which track the secondary market).', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('BS', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"BS","iso3":"BHS","nameEn":"Bahamas","nameNative":"The Bahamas","region":"latin_america_caribbean","languages":["en","bah","ht"],"currency":{"code":"BSD","symbol":"$","decimals":2,"compact":"intl","usdRate":{"value":1,"status":"sourced","sourceName":"Central Bank of The Bahamas: daily spot foreign exchange rates","sourceUrl":"https://www.centralbankbahamas.com/exchange-rate","asOf":"2026-10-31","note":"The Bahamian dollar is pegged at par: the Central Bank buys and sells US dollars at 1.0000."}},"instruments":{"savings_account":{"available":true,"localName":"Savings account","sourceUrl":"https://cdn.centralbankbahamas.com/tenantcbob_prod/assets/documents/CBOB-Quarterly-Digest---August-2026Revised-1792176978-o8JHkd.pdf"},"fdr_3m":{"available":true,"localName":"Fixed deposit","localNameEn":"Fixed deposit up to 3 months","sourceUrl":"https://cdn.centralbankbahamas.com/tenantcbob_prod/assets/documents/CBOB-Quarterly-Digest---August-2026Revised-1792176978-o8JHkd.pdf"},"fdr_1y":{"available":true,"localName":"Fixed deposit","localNameEn":"Fixed deposit of 6-12 months","sourceUrl":"https://cdn.centralbankbahamas.com/tenantcbob_prod/assets/documents/CBOB-Quarterly-Digest---August-2026Revised-1792176978-o8JHkd.pdf"},"dps":{"available":false,"localName":null,"note":"No standard monthly recurring deposit product rate published."},"sanchayapatra_5y":{"available":true,"localName":"Bahamas Savings Bond","localNameEn":"Bahamas Savings Bond (1, 2, 4 and 6 years)","note":"Fixed-coupon government savings bond for individuals, sold in B$100 units through the Central Bank.","sourceUrl":"https://www.centralbankbahamas.com/bahamas-savings-bond"},"tbill_91d":{"available":true,"localName":"Treasury bill","localNameEn":"Government of The Bahamas Treasury bill (91, 182 or 364 days)","note":"Sold at Central Bank tenders; non-competitive bids are accepted.","sourceUrl":"https://www.centralbankbahamas.com/news/t-bill-auction-results"},"tbond_5y":{"available":true,"localName":"Bahamas Registered Stock","localNameEn":"Bahamas Government Registered Stock, 5 years","sourceUrl":"https://www.centralbankbahamas.com/bahamas-registered-stock"},"tbond_10y":{"available":true,"localName":"Bahamas Registered Stock","localNameEn":"Bahamas Government Registered Stock, 10-11 years","sourceUrl":"https://www.centralbankbahamas.com/bahamas-registered-stock"},"equity_fund":{"available":true,"localName":"Mutual fund","localNameEn":"Investment fund","note":"Investment funds are regulated by the Securities Commission of The Bahamas.","sourceUrl":"https://scb.gov.bs/"},"gold":{"available":true,"localName":"Gold","note":"No legal restriction on buying gold; mainly sold as jewellery and coins."}},"institutions":{"centralBank":{"name":"Central Bank of The Bahamas","url":"https://www.centralbankbahamas.com/"},"insuranceRegulator":{"name":"Insurance Commission of The Bahamas","url":"https://www.icb.gov.bs/"},"insuranceComplaints":{"name":"Insurance Commission of The Bahamas: complaints","url":"https://www.icb.gov.bs/consumer-awareness/complaints/"},"pensionScheme":{"name":"National Insurance Board (Retirement Benefit)","url":"https://www.nib-bahamas.com/benefits/long-term"},"oldAgeAllowance":{"name":"National Insurance Board: Old Age Non-Contributory Pension","url":"https://www.nib-bahamas.com/benefits/assistance-payments"},"publicHealthCover":{"name":"National Health Insurance Bahamas (NHI)","url":"https://www.nhibahamas.gov.bs/"},"depositInsurance":{"name":"Deposit Insurance Corporation","url":"https://www.dic.bs/"},"statistics":{"name":"Bahamas National Statistical Institute","url":"https://stats.gov.bs/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BS', 1, 'bank_deposit_avg_rate', 0.0062, NULL, 'sourced', 'Central Bank of The Bahamas: Monthly Economic and Financial Developments, September 2026', 'https://cdn.centralbankbahamas.com/tenantcbob_prod/assets/documents/Monthly-Economic-and-Financial-Developments-September-2026-1793300706-BqgnOF.pdf', '2026-09-30', 'Banks'' weighted average deposit rate narrowed by 10 basis points to 0.62% in September 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BS', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap or published average credit card rate found; the CBOB loan rate table gives consumer loans at 12.0% and overdrafts at 11.1% (June 2026) but no card rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BS', 1, 'deposit_insurance_limit', 50000, NULL, 'sourced', 'Deposit Insurance Corporation of The Bahamas: FAQs', 'https://www.dic.bs/faq.php', '2026-10-31', 'Each eligible deposit at a member bank or credit union is insured up to B$50,000 per depositor, principal and interest included.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BS', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No monthly recurring deposit product rate is published in the Central Bank of The Bahamas deposit rate tables.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BS', 1, 'equity_return_base', 0.07, NULL, 'assumption', 'CBOB QSD table 3.6: BISX index up about 5.4% a year 2016-2025 before dividends; 364-day T-bill 3.87%', 'https://cdn.centralbankbahamas.com/tenantcbob_prod/assets/documents/CBOB-Quarterly-Digest---August-2026Revised-1792176978-o8JHkd.pdf', '2026-10-31', 'Base case: index price gains of about 5% plus dividends, capped near 3 points above the untaxed 1-year bill rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BS', 1, 'equity_return_high', 0.095, NULL, 'assumption', 'CBOB QSD table 3.7: BISX and US equity annual returns', 'https://cdn.centralbankbahamas.com/tenantcbob_prod/assets/documents/CBOB-Quarterly-Digest---August-2026Revised-1792176978-o8JHkd.pdf', '2026-10-31', 'High case if local or US-dollar global equities repeat their long-run record of about 9-10%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BS', 1, 'equity_return_low', 0.04, NULL, 'assumption', 'CBOB QSD table 3.6: BISX All Share index 1,938 (end-2016) to 3,110 (end-2025)', 'https://cdn.centralbankbahamas.com/tenantcbob_prod/assets/documents/CBOB-Quarterly-Digest---August-2026Revised-1792176978-o8JHkd.pdf', '2026-10-31', 'Low case near the 3.4-3.9% Treasury bill yields, for a weak decade in a small, illiquid market.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BS', 1, 'fdr_1y_rate', 0.0036, NULL, 'sourced', 'Central Bank of The Bahamas Quarterly Statistical Digest (August 2026), table 4.3: Deposit Rates of the Banking System', 'https://cdn.centralbankbahamas.com/tenantcbob_prod/assets/documents/CBOB-Quarterly-Digest---August-2026Revised-1792176978-o8JHkd.pdf', '2026-06-30', 'Fixed deposits of 6-12 months averaged 0.36% in June 2026; deposits over 12 months 1.33%. The highest rate offered in September 2026 was 2.25%, on fixed balances over 12 months (CBOB monthly report).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BS', 1, 'fdr_3m_rate', 0.004, NULL, 'sourced', 'Central Bank of The Bahamas Quarterly Statistical Digest (August 2026), table 4.3: Deposit Rates of the Banking System', 'https://cdn.centralbankbahamas.com/tenantcbob_prod/assets/documents/CBOB-Quarterly-Digest---August-2026Revised-1792176978-o8JHkd.pdf', '2026-06-30', 'Fixed deposits up to 3 months averaged 0.40% in June 2026 (0.25-0.34% earlier in 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BS', 1, 'fixed_income_return_base', 0.03, NULL, 'assumption', 'CBOB: 91-day T-bill 3.44%; Bahamas Savings Bond 2.81-3.99%', 'https://cdn.centralbankbahamas.com/tenantcbob_prod/assets/documents/Treasury-Bill-Tender-Results---13-and-14-October-2026-1792073773-TI2L99.pdf', '2026-10-31', 'Base case: savings bonds and Treasury bills, untaxed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BS', 1, 'fixed_income_return_high', 0.045, NULL, 'assumption', 'CBOB: 5-year Bahamas Registered Stock 4.75% (October 2026)', 'https://cdn.centralbankbahamas.com/tenantcbob_prod/assets/documents/Bahamas-Registered-Stock-Reopening-Results---14-and-15-October-2026-1792095495-Wc7wEt.pdf', '2026-10-31', 'High case: holding 5-year registered stock.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BS', 1, 'fixed_income_return_low', 0.01, NULL, 'assumption', 'CBOB QSD table 4.3: bank deposits 0.25-1.33%', 'https://cdn.centralbankbahamas.com/tenantcbob_prod/assets/documents/CBOB-Quarterly-Digest---August-2026Revised-1792176978-o8JHkd.pdf', '2026-10-31', 'Low case: money left in bank deposits, which pay well under 1.5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BS', 1, 'goal_inflation_education', 0.03, NULL, 'assumption', 'CBOB QSD table 8.2: education sub-index 109.5 (2016) to 107.2 (2025)', 'https://cdn.centralbankbahamas.com/tenantcbob_prod/assets/documents/CBOB-Quarterly-Digest---August-2026Revised-1792176978-o8JHkd.pdf', '2026-10-31', 'The education index was flat over 2016-2025, but school fees tend to track wages, so we plan with the 2.5% headline projection plus half a point.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BS', 1, 'goal_inflation_health', 0.04, NULL, 'assumption', 'CBOB QSD table 8.2: health sub-index 119.0 (2016) to 168.3 (2025)', 'https://cdn.centralbankbahamas.com/tenantcbob_prod/assets/documents/CBOB-Quarterly-Digest---August-2026Revised-1792176978-o8JHkd.pdf', '2026-10-31', 'The health price index rose about 3.9% a year over 2016-2025, so we plan with 4%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BS', 1, 'gold_return_base', 0.05, NULL, 'assumption', 'Bahamian dollar fixed at par with the US dollar (World Bank PA.NUS.FCRF)', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=BS', '2026-10-31', 'Long-run dollar gold trend of about 4-5% with no expected depreciation under the peg.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BS', 1, 'gold_return_high', 0.08, NULL, 'assumption', 'Bahamian dollar fixed at par with the US dollar (World Bank PA.NUS.FCRF)', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=BS', '2026-10-31', 'High case with strong dollar gold prices.', 0);
