INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BS', 1, 'inflation_cpi', 0.037, NULL, 'sourced', 'Central Bank of The Bahamas: Monthly Economic and Financial Developments, September 2026 (retail price index from the Bahamas National Statistical Institute)', 'https://cdn.centralbankbahamas.com/tenantcbob_prod/assets/documents/Monthly-Economic-and-Financial-Developments-September-2026-1793300706-BqgnOF.pdf', '2026-07-31', 'Retail price index 127.3 in July 2026 against 122.8 in July 2025, up 3.7% year on year (latest month shown). The end-of-period index in the CBOB Quarterly Statistical Digest rose 2.3% in December 2025 on a year earlier.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BS', 1, 'inflation_projection', 0.025, NULL, 'assumption', 'CBOB QSD table 8.2: retail price index 2016-2025 average about 2.2% a year; Bahamian dollar fixed at par with the US dollar', 'https://cdn.centralbankbahamas.com/tenantcbob_prod/assets/documents/CBOB-Quarterly-Digest---August-2026Revised-1792176978-o8JHkd.pdf', '2026-10-31', 'The one-to-one US-dollar peg anchors prices; the retail price index rose about 2.2% a year over 2016-2025 (2.8% since 2020) and 3.7% in the year to July 2026, so we plan with 2.5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BS', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life cover is sold in The Bahamas, but no regulator or other non-company source publishing premium rates by age was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BS', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched the Insurance Commission of The Bahamas material: no industry-wide life claim settlement ratio published.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BS', 1, 'life_expectancy', 74.71, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=BS', '2024-12-31', 'UN WPP 2024 (via populationpyramid.net) gives 75.0 for 2026 (men 71.4, women 78.6).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BS', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":21.9,"men":19.7,"women":24},{"age":65,"total":18.2,"men":16,"women":20},{"age":70,"total":14.9,"men":13.1,"women":16.6},{"age":80,"total":9.2,"men":7.9,"women":10.5}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/bahamas/', '2026-12-31', 'Secondary source of UN WPP 2024 medium variant for 2026; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BS', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":65,"womenAge":65,"over90Monthly":null,"meansTested":true}', 'sourced', 'National Insurance Board of The Bahamas: assistance payments (Old Age Non-Contributory Pension)', 'https://www.nib-bahamas.com/benefits/assistance-payments', '2026-10-31', 'Monthly pension for needy Bahamian residents aged 65 or older who do not meet the contribution conditions for the NIB Retirement Benefit and pass a test of resources; eligibility is verified twice a year.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BS', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'NIB pays a means-tested Old Age Non-Contributory Pension from 65, but its current monthly amount is not stated on the NIB assistance payments page.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BS', 1, 'oop_health_share', 0.2748, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=BS', '2023-12-31', 'Latest year available (2023), older than 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BS', 1, 'policy_rate', 0.04, NULL, 'sourced', 'Central Bank of The Bahamas Quarterly Statistical Digest (August 2026), table 4.1: Selected Interest Rates', 'https://cdn.centralbankbahamas.com/tenantcbob_prod/assets/documents/CBOB-Quarterly-Digest---August-2026Revised-1792176978-o8JHkd.pdf', '2026-06-30', 'Bank Rate (the rate at which banks borrow from the Central Bank) 4.00%, unchanged since 2016.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BS', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":65,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":true}', 'sourced', 'National Insurance Board of The Bahamas: long-term benefits (Retirement Benefit and Retirement Grant)', 'https://www.nib-bahamas.com/benefits/long-term', '2026-10-31', 'Compulsory National Insurance: monthly Retirement Benefit, payable for life, from 65 (from 60 at a reduced rate) of 30-60% of average insurable wage with at least 500 weekly contributions; a one-off Retirement Grant at 65 with 150-499 contributions. No automatic indexation found; untaxed as there is no personal income tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BS', 1, 'retirement_accumulation_return_base', 0.05, NULL, 'assumption', 'Mix of bills/bonds (3.4-4.75%) and equities (7% base)', 'https://cdn.centralbankbahamas.com/tenantcbob_prod/assets/documents/Bahamas-Registered-Stock-Reopening-Results---14-and-15-October-2026-1792095495-Wc7wEt.pdf', '2026-10-31', 'Base case for a roughly half-and-half mix of government securities and equities.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BS', 1, 'retirement_accumulation_return_high', 0.07, NULL, 'assumption', 'Mix of registered stock (up to 5.5%) and equities (9.5% high case)', 'https://cdn.centralbankbahamas.com/tenantcbob_prod/assets/documents/Bahamas-Registered-Stock-Reopening-Results---14-and-15-October-2026-1792095495-Wc7wEt.pdf', '2026-10-31', 'High case with a strong equity decade.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BS', 1, 'retirement_accumulation_return_low', 0.03, NULL, 'assumption', 'Mix of bills/bonds (3.4-4.75%) and local equities', 'https://cdn.centralbankbahamas.com/tenantcbob_prod/assets/documents/Bahamas-Registered-Stock-Reopening-Results---14-and-15-October-2026-1792095495-Wc7wEt.pdf', '2026-10-31', 'Low case for a balanced mix in a weak decade.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BS', 1, 'retirement_age_default', 65, NULL, 'sourced', 'National Insurance Board of The Bahamas: long-term benefits (Retirement Benefit)', 'https://www.nib-bahamas.com/benefits/long-term', '2026-10-31', 'Full NIB Retirement Benefit from 65 with at least 500 weekly contributions; it can be taken from 60 at a reduced rate. No separate statutory private-sector retirement age found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BS', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched for the public service retirement age under The Bahamas Pensions Act: no reachable official source found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BS', 1, 'retirement_return_base', 0.03, NULL, 'assumption', 'CBOB: 364-day T-bill 3.87% (October 2026); Bahamas Savings Bond 2.81-3.99%', 'https://cdn.centralbankbahamas.com/tenantcbob_prod/assets/documents/Treasury-Bill-Tender-Results---28-and-29-October-2026-1793309070-PypEql.pdf', '2026-10-31', 'Base case below the untaxed 1-year Treasury bill yield, using savings bonds and bills.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BS', 1, 'retirement_return_high', 0.04, NULL, 'assumption', 'CBOB: 5-year Bahamas Registered Stock 4.75%; 6-year savings bond 3.99%', 'https://cdn.centralbankbahamas.com/tenantcbob_prod/assets/documents/Bahamas-Registered-Stock-Reopening-Results---14-and-15-October-2026-1792095495-Wc7wEt.pdf', '2026-10-31', 'High case: a ladder of savings bonds and registered stock.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BS', 1, 'retirement_return_low', 0.01, NULL, 'assumption', 'CBOB QSD table 4.3: bank deposits 0.25-1.33%', 'https://cdn.centralbankbahamas.com/tenantcbob_prod/assets/documents/CBOB-Quarterly-Digest---August-2026Revised-1792176978-o8JHkd.pdf', '2026-10-31', 'Low case: savings left in bank deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BS', 1, 'sanchayapatra_5y_rate', 0.0343, NULL, 'sourced', 'Central Bank of The Bahamas: Bahamas Savings Bond prospectus, November 2024', 'https://cdn.centralbankbahamas.com/tenantcbob_prod/assets/documents/2024-11-15-02-05-14-BSB-November-2024-Prospectus-5MFinal-1778056381-Wchkr5.pdf', '2024-11-25', 'Bahamas Savings Bond 4-year tenor fixed coupon 3.43% (6-year 3.99%, 2-year 3.01%, 1-year 2.81%), paid semi-annually, units of B$100, sold through the Central Bank. Latest prospectus found is from November 2024 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BS', 1, 'savings_account_rate', 0.0025, NULL, 'sourced', 'Central Bank of The Bahamas Quarterly Statistical Digest (August 2026), table 4.3: Deposit Rates of the Banking System', 'https://cdn.centralbankbahamas.com/tenantcbob_prod/assets/documents/CBOB-Quarterly-Digest---August-2026Revised-1792176978-o8JHkd.pdf', '2026-06-30', 'Average rate on savings deposits 0.25% in June 2026 (0.25-0.28% through 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BS', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":5.8},{"year":2040,"value":3.6},{"year":2065,"value":2.4}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/bahamas/2040/', '2025-12-31', '100 / old-age dependency ratio: 17.2 (2025, World Bank), 27.9 (2040) and 42.0 (2065, populationpyramid.net/bahamas/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BS', 1, 'tax_bank_interest', 0, NULL, 'sourced', 'PwC Worldwide Tax Summaries: The Bahamas, individual taxes on personal income (last reviewed 21 July 2026)', 'https://taxsummaries.pwc.com/the-bahamas/individual/taxes-on-personal-income', '2026-07-21', 'There is no personal income tax in The Bahamas, so bank interest is untaxed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BS', 1, 'tax_sanchayapatra_profit', 0, NULL, 'sourced', 'PwC Worldwide Tax Summaries: The Bahamas, individual taxes on personal income (last reviewed 21 July 2026)', 'https://taxsummaries.pwc.com/the-bahamas/individual/taxes-on-personal-income', '2026-07-21', 'No personal income tax, so Bahamas Savings Bond coupons are untaxed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BS', 1, 'tbill_91d_rate', 0.0344, NULL, 'sourced', 'Central Bank of The Bahamas: Treasury bill tender results, 13 and 14 October 2026', 'https://cdn.centralbankbahamas.com/tenantcbob_prod/assets/documents/Treasury-Bill-Tender-Results---13-and-14-October-2026-1792073773-TI2L99.pdf', '2026-10-13', '91-day bills average yield 3.44% (discount rate 3.41%); 182-day 3.66%; 364-day 3.85% (3.87% at the 28-29 October tender).', 0);
