INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BS', 1, 'tbond_5y_rate', 0.0475, NULL, 'sourced', 'Central Bank of The Bahamas (registrar): Bahamas Registered Stock reopening results, 14 and 15 October 2026', 'https://cdn.centralbankbahamas.com/tenantcbob_prod/assets/documents/Bahamas-Registered-Stock-Reopening-Results---14-and-15-October-2026-1792095495-Wc7wEt.pdf', '2026-10-14', '5-year Bahamas Registered Stock due 15 October 2031: average competitive yield 4.75% (3-year 4.25%, 7-year 5.51%).', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('BT', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"BT","iso3":"BTN","nameEn":"Bhutan","nameNative":"འབྲུག་ཡུལ་","region":"south_asia","languages":["dz","ne","en"],"currency":{"code":"BTN","symbol":"Nu.","decimals":2,"compact":"intl","usdRate":{"value":95.03,"status":"sourced","sourceName":"Trading Economics (USD/BTN)","sourceUrl":"https://tradingeconomics.com/bhutan/currency","asOf":"2026-10-30","note":"Ngultrum is pegged at par to the Indian rupee; RMA site unreachable. cldr.json lists INR for BT, corrected to BTN."}},"instruments":{"savings_account":{"available":true,"localName":null,"localNameEn":"Savings account"},"fdr_3m":{"available":true,"localName":null,"localNameEn":"Fixed deposit (3 months)"},"fdr_1y":{"available":true,"localName":null,"localNameEn":"Fixed deposit (1 year)"},"dps":{"available":true,"localName":null,"localNameEn":"Recurring deposit"},"sanchayapatra_5y":{"available":false,"localName":null,"note":"No government savings certificate; citizens can buy RGoB bonds."},"tbill_91d":{"available":true,"localName":null,"localNameEn":"RGoB treasury bill","note":"Auctioned by the RMA; open to Bhutanese persons and entities.","sourceUrl":"https://mof.gov.bt/call-for-tenders-for-government-treasury-bills/"},"tbond_5y":{"available":false,"localName":null,"note":"No 5-year RGoB bond series found."},"tbond_10y":{"available":true,"localName":null,"localNameEn":"RGoB government bond","note":"10-year issues; Bhutanese citizens may subscribe.","sourceUrl":"https://www.bbs.bt/?p=181100"},"equity_fund":{"available":false,"localName":null,"note":"No retail mutual or index fund found; listed shares trade on the Royal Securities Exchange of Bhutan."},"gold":{"available":true,"localName":"གསེར","localNameEn":"Gold","note":"Mostly bought as jewellery."}},"institutions":{"centralBank":{"name":"Royal Monetary Authority of Bhutan","url":"https://www.rma.org.bt/"},"insuranceRegulator":{"name":"Royal Monetary Authority of Bhutan (insurance supervision)","url":"https://www.rma.org.bt/"},"insuranceComplaints":{"name":"Royal Monetary Authority of Bhutan (financial consumer complaints)","url":"https://www.rma.org.bt/"},"pensionScheme":{"name":"National Pension and Provident Fund","url":"https://www.nppf.org.bt/","note":"Covers civil servants, armed forces and state corporations; private employees use provident fund schemes."},"oldAgeAllowance":null,"publicHealthCover":{"name":"Ministry of Health (free public health care)","url":"https://www.moh.gov.bt/"},"depositInsurance":null,"statistics":{"name":"National Statistics Bureau","url":"https://www.nsb.gov.bt/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
