INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BT', 1, 'equity_return_base', 0.07, NULL, 'assumption', 'Royal Securities Exchange of Bhutan; World Bank deposit rate; RGoB bond coupon', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=BT', '2026-10-31', 'Kept well within 4 points of the safe rate (4.5% average deposit, 6.5% 10-year bond) because the local market is thin and its 10-year record weak.', 0);
