INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BT', 1, 'goal_inflation_health', 0.06, NULL, 'assumption', 'NSB CPI via Trading Economics', 'https://tradingeconomics.com/bhutan/inflation-cpi', '2026-10-31', 'No medical CPI found; public care is free, so we add 1 point to the 5% inflation assumption for private and Indian referral costs.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BT', 1, 'gold_return_base', 0.07, NULL, 'assumption', 'Ngultrum per US dollar (pegged to the Indian rupee)', 'https://tradingeconomics.com/bhutan/currency', '2026-10-31', 'Dollar gold trend of about 4-5% plus 2-3% a year of rupee (and so ngultrum) depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BT', 1, 'gold_return_high', 0.11, NULL, 'assumption', 'Ngultrum per US dollar (pegged to the Indian rupee)', 'https://tradingeconomics.com/bhutan/currency', '2026-10-31', 'Strong dollar gold plus faster rupee depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BT', 1, 'gold_return_low', 0.02, NULL, 'assumption', 'Ngultrum per US dollar (pegged to the Indian rupee)', 'https://tradingeconomics.com/bhutan/currency', '2026-10-31', 'Dollar gold can stall for years while the rupee peg stays stable.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BT', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Labour and Employment Act 2007 (s.99-101) entitles retiring employees to gratuity but sets the amount in rules we could not read; the formula is reportedly one month''s last basic pay per year of service (unverified).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BT', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'Public health care is free; no typical private or referral hospital stay cost found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BT', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No private health insurance premium tables found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BT', 1, 'inflation_cpi', 0.0551, NULL, 'sourced', 'Trading Economics (National Statistics Bureau CPI)', 'https://tradingeconomics.com/bhutan/inflation-cpi', '2026-08-31', 'August 2026 year on year, down from 6.83% in July; secondary source because the NSB CPI page could not be reached.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BT', 1, 'inflation_projection', 0.05, NULL, 'assumption', 'NSB CPI via Trading Economics; World Bank FP.CPI.TOTL.ZG', 'https://tradingeconomics.com/bhutan/inflation-cpi', '2026-10-31', 'The ngultrum is pegged to the Indian rupee, so inflation tracks India''s 4% target plus a margin; Bhutan''s CPI averaged about 5% over five years (3.6% in 2025, 5.5% in Aug 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BT', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published pure-term life premium quotes found; web search budget ran out before insurer rate sheets could be checked.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BT', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No industry life claim settlement ratio published by the RMA found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BT', 1, 'life_expectancy', 73.262, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=BT', '2024-12-31', 'Men 71.6, women 75.3 (World Bank 2024).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BT', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":19,"men":17.8,"women":20.3},{"age":65,"total":15.2,"men":14.2,"women":16.3},{"age":70,"total":11.8,"men":11,"women":12.7},{"age":80,"total":6.4,"men":5.9,"women":6.8}]}', 'sourced', 'georank.org (UN World Population Prospects)', 'https://georank.org/life-expectancy/bhutan', '2026-07-08', 'Remaining years = expected age at death by current age minus that age; explainer only.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BT', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BT', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension found; elderly support is through royal kidu grants. Could not confirm a source stating none.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BT', 1, 'oop_health_share', 0.255, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=BT', '2023-12-31', NULL, 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BT', 1, 'policy_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The RMA has no confirmed published policy rate; an interest rate corridor was still being developed with IMF help in 2025. Trading Economics lists a ''policy rate'' of 5.37% (Sep 2026) that we could not confirm with the RMA, whose site failed TLS checks.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BT', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":60,"nomineeUntilAge":null,"inflationLinked":true,"taxFree":null}', 'sourced', 'National Pension and Provident Fund, Annual Report 2024', 'https://www.nppf.org.bt/wp-content/uploads/2025/07/Annual-Report_2024.pdf', '2024-12-31', 'Civil service plan: 40% of last basic pay after at least 23 years; normal retirement age 57-63 by rank; yearly adjustment by CPI capped at 5%; minimum pension Nu 5,510. Covers civil servants, armed forces and state corporations (plus a voluntary provident fund for private and informal workers). 2024 report (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BT', 1, 'retirement_accumulation_return_base', 0.065, NULL, 'assumption', 'Deposits, RSEB equity and gold (assumption)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=BT', '2026-10-31', 'Balanced mix of deposits and bonds (about 5.5%), local equity (7%) and gold (7%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BT', 1, 'retirement_accumulation_return_high', 0.09, NULL, 'assumption', 'Deposits, RSEB equity and gold (assumption)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=BT', '2026-10-31', 'Long deposits and bonds with equity and gold high cases.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BT', 1, 'retirement_accumulation_return_low', 0.045, NULL, 'assumption', 'Deposits, RSEB equity and gold (assumption)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=BT', '2026-10-31', 'Mostly deposits with weak equity.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BT', 1, 'retirement_age_default', NULL, NULL, 'missing', '', '', '2026-10-31', 'No statutory private-sector retirement age found; the Labour and Employment Act 2007 (s.99) gives gratuity and provident fund on retirement but leaves ages to rules. Corporate employees in NPPF follow agency rules.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BT', 1, 'retirement_age_government', 60, NULL, 'sourced', 'National Pension and Provident Fund, Annual Report 2024', 'https://www.nppf.org.bt/wp-content/uploads/2025/07/Annual-Report_2024.pdf', '2024-12-31', 'Civil service normal retirement age is set by rank: 57, 59, 60 or 63 (NPPF Annual Report 2024; older than 2025); 60 shown as the middle case.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BT', 1, 'retirement_return_base', 0.045, NULL, 'assumption', 'World Bank deposit rate (FR.INR.DPST)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=BT', '2026-10-31', 'Kept at the 4.5% average deposit rate, untaxed for most savers, since no 1-year deposit or T-bill rate could be cited.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BT', 1, 'retirement_return_high', 0.065, NULL, 'assumption', 'RGoB bond coupon', 'https://www.bbs.bt/?p=181100', '2026-10-31', 'Laddered long deposits and RGoB bonds at about 6.5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BT', 1, 'retirement_return_low', 0.04, NULL, 'assumption', 'World Bank deposit rate (FR.INR.DPST)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=BT', '2026-10-31', 'Savings and short deposits below the 4.5% average deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BT', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate for individuals; citizens can bid for RGoB bonds instead (see tbond_10y_rate).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BT', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Savings rate of about 4.5% appears only on individual banks'' rate sheets (and a Mar 2026 news report not re-read); the RMA site failed TLS checks.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BT', 1, 'support_ratio', NULL, '{"points":[{"year":2026,"value":10.8},{"year":2040,"value":7.1},{"year":2065,"value":2.3}]}', 'sourced', 'PopulationPyramid.net (UN WPP 2024, medium variant)', 'https://www.populationpyramid.net/bhutan/2040/', '2026-10-31', 'People aged 15-64 per person 65+, computed from the UN WPP 2024 age structure; World Bank old-age dependency 9.08 (2025) gives 11.0.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BT', 1, 'tax_bank_interest', 0.1, NULL, 'sourced', 'The Bhutanese (Income Tax Act of Bhutan 2025)', 'https://thebhutanese.bt/major-changes-in-bhutans-income-tax-from-2026-explained/', '2026-01-01', 'Income Tax Act 2025, from 1 Jan 2026: the first Nu 400,000 of fixed-deposit interest is exempt and the rest taxed at 10%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BT', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate exists; RGoB bond interest is not PIT-taxable but coupons carry 5% TDS (2023 bond offer document).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BT', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'RGoB treasury bills are auctioned by the RMA (open to Bhutanese persons and entities), but no recent 91-day yield was found; RMA site unreachable.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BT', 1, 'tbond_10y_rate', 0.065, NULL, 'sourced', 'Bhutan Broadcasting Service (RGoB bond issue)', 'https://www.bbs.bt/?p=181100', '2025-11-20', 'Coupon of the latest 10-year RGoB bond issue (Nu 1.25bn), open to banks, corporations and individuals; the article is undated on the page (reported Nov 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BT', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 5-year RGoB bond series found; recent issues were 7, 10 and 12 years.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('BW', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"BW","iso3":"BWA","nameEn":"Botswana","nameNative":"Botswana","region":"sub_saharan_africa","languages":["tn","en"],"currency":{"code":"BWP","symbol":"P","decimals":2,"compact":"intl","usdRate":{"value":13.46,"status":"sourced","sourceName":"Bank of Botswana, exchange rates (foreign currency per pula), 30 October 2026","sourceUrl":"https://www.bankofbotswana.bw/content/exchange-rates","asOf":"2026-10-30","note":"USD 0.0743 per pula, i.e. about 13.46 pula per US dollar (1/0.0743); World Bank 2025 average 13.50."}},"instruments":{"savings_account":{"available":true,"localName":null,"localNameEn":"Savings account","sourceUrl":"https://www.bankofbotswana.bw/sites/default/files/publications/Botswana%20Economic%20and%20Financial%20Statistics%20-%20September%202026%20%20.xlsx"},"fdr_3m":{"available":true,"localName":"Fixed deposit","localNameEn":"Fixed deposit","note":"Banks offer fixed deposits of 3 to 12 months; the central bank publishes one average for terms up to 12 months.","sourceUrl":"https://www.bankofbotswana.bw/sites/default/files/publications/Botswana%20Economic%20and%20Financial%20Statistics%20-%20September%202026%20%20.xlsx"},"fdr_1y":{"available":true,"localName":"Fixed deposit","localNameEn":"Fixed deposit, 12 months","sourceUrl":"https://www.bankofbotswana.bw/sites/default/files/publications/Botswana%20Economic%20and%20Financial%20Statistics%20-%20September%202026%20%20.xlsx"},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No standard monthly recurring deposit product was found."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate or retail savings bond for individuals was found."},"tbill_91d":{"available":true,"localName":"Treasury bill","localNameEn":"Treasury bill","note":"3, 6 and 12-month bills auctioned monthly by the Bank of Botswana for the government.","sourceUrl":"https://www.bankofbotswana.bw/sites/default/files/auction-pdf-files/Government%20Bond%20Auction%20%2030%20October%202026.pdf"},"tbond_5y":{"available":true,"localName":"Government bond","localNameEn":"Government bond","note":"Auctioned monthly by the Bank of Botswana and listed on the Botswana Stock Exchange.","sourceUrl":"https://www.bankofbotswana.bw/sites/default/files/auction-pdf-files/Government%20Bond%20Auction%20%2030%20October%202026.pdf"},"tbond_10y":{"available":true,"localName":"Government bond","localNameEn":"Government bond","note":"Lines maturing 2035, 2040, 2043 and 2050 are on issue.","sourceUrl":"https://www.bankofbotswana.bw/sites/default/files/auction-pdf-files/Government%20Bond%20Auction%20%2030%20October%202026.pdf"},"equity_fund":{"available":true,"localName":"Unit trust","localNameEn":"Unit trusts (collective investment undertakings)","note":"Supervised by NBFIRA; local funds invest on the Botswana Stock Exchange and abroad."},"gold":{"available":true,"localName":null,"localNameEn":"Gold","note":"No local bullion product is sold; gold is bought as jewellery or imported coins."}},"institutions":{"centralBank":{"name":"Bank of Botswana","url":"https://www.bankofbotswana.bw/"},"insuranceRegulator":{"name":"Non-Bank Financial Institutions Regulatory Authority (NBFIRA)","url":"https://www.nbfira.org.bw/"},"insuranceComplaints":null,"pensionScheme":null,"oldAgeAllowance":null,"publicHealthCover":{"name":"Ministry of Health (public health facilities)","url":"https://www.moh.gov.bw/"},"depositInsurance":{"name":"Deposit Insurance Scheme of Botswana","url":"https://www.bankofbotswana.bw/content/establishment"},"statistics":{"name":"Statistics Botswana","url":"https://www.statsbots.org.bw/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BW', 1, 'bank_deposit_avg_rate', 0.0235, NULL, 'sourced', 'World Bank WDI, deposit interest rate (FR.INR.DPST), Botswana', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=BW', '2024-12-31', '2.35% average for 2024 (older than 2025); the Bank of Botswana publishes only simple averages by deposit type (fixed up to 12 months 4.21% in August 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BW', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap or published typical credit card rate was found; the Bank of Botswana publishes the prime lending rate (7.19%) and average return on advances (16.2% in August 2026) only.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BW', 1, 'deposit_insurance_limit', 250000, NULL, 'sourced', 'Bank of Botswana, Deposit Insurance Scheme of Botswana: establishment', 'https://www.bankofbotswana.bw/content/establishment', '2023-07-21', 'The scheme guarantees up to P250,000 per depositor per member institution; established under the Bank of Botswana (Amendment) Act 2022, regulations in force since 21 July 2023 (date of the rule, still current).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BW', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No monthly recurring deposit product or rate was found in Bank of Botswana statistics.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BW', 1, 'equity_return_base', 0.08, NULL, 'assumption', 'Bank of Botswana, Botswana Economic and Financial Statistics, September 2026, table 4.5 Botswana Stock Exchange; treasury bill and deposit rates', 'https://www.bankofbotswana.bw/sites/default/files/publications/Botswana%20Economic%20and%20Financial%20Statistics%20-%20September%202026%20%20.xlsx', '2026-10-31', 'Base case: the domestic company index rose only about 1.8% a year from December 2016 (9,401) to September 2026 (11,250) plus dividends of about 5-8%, so equities are put about 2 points above the after-tax 1-year bill yield (about 5.8%), below the 4-point cap.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BW', 1, 'equity_return_high', 0.11, NULL, 'assumption', 'Bank of Botswana, Botswana Economic and Financial Statistics, September 2026, table 4.5 Botswana Stock Exchange', 'https://www.bankofbotswana.bw/sites/default/files/publications/Botswana%20Economic%20and%20Financial%20Statistics%20-%20September%202026%20%20.xlsx', '2026-10-31', 'High case: a strong decade for local shares or a global index fund in pula terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BW', 1, 'equity_return_low', 0.04, NULL, 'assumption', 'Bank of Botswana, Botswana Economic and Financial Statistics, September 2026, table 4.5 Botswana Stock Exchange', 'https://www.bankofbotswana.bw/sites/default/files/publications/Botswana%20Economic%20and%20Financial%20Statistics%20-%20September%202026%20%20.xlsx', '2026-10-31', 'Low case: the domestic company index barely rose over ten years, so equities may return little more than their dividends.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BW', 1, 'fdr_1y_rate', 0.0421, NULL, 'sourced', 'Bank of Botswana, Botswana Economic and Financial Statistics, September 2026, table 4.1 interest rates (fixed deposits up to 12 months)', 'https://www.bankofbotswana.bw/sites/default/files/publications/Botswana%20Economic%20and%20Financial%20Statistics%20-%20September%202026%20%20.xlsx', '2026-08-31', 'Average rate on pula fixed deposits up to 12 months, 4.21% in August 2026 (4.28% in July); fixed deposits over 12 months averaged 3.65%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BW', 1, 'fdr_3m_rate', 0.0421, NULL, 'sourced', 'Bank of Botswana, Botswana Economic and Financial Statistics, September 2026, table 4.1 interest rates (fixed deposits up to 12 months)', 'https://www.bankofbotswana.bw/sites/default/files/publications/Botswana%20Economic%20and%20Financial%20Statistics%20-%20September%202026%20%20.xlsx', '2026-08-31', 'Average rate on pula fixed deposits up to 12 months, 4.21% in August 2026; the Bank of Botswana does not publish a separate 3-month figure (notice deposits 3.79%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BW', 1, 'fixed_income_return_base', 0.04, NULL, 'assumption', 'Bank of Botswana, Botswana Economic and Financial Statistics, September 2026, table 4.1 (fixed deposits up to 12 months 4.21%)', 'https://www.bankofbotswana.bw/sites/default/files/publications/Botswana%20Economic%20and%20Financial%20Statistics%20-%20September%202026%20%20.xlsx', '2026-10-31', 'Base case: 12-month fixed deposits at 4.21%, mostly untaxed for a small saver (P7,800 exemption, 10% above).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BW', 1, 'fixed_income_return_high', 0.06, NULL, 'assumption', 'Bank of Botswana, Government bond and treasury bill auction results, 30 October 2026', 'https://www.bankofbotswana.bw/sites/default/files/auction-pdf-files/Government%20Bond%20Auction%20%2030%20October%202026.pdf', '2026-10-31', 'High case: 12-month treasury bills (6.46%) or 5-year bonds (7.22%) less 10% withholding tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BW', 1, 'fixed_income_return_low', 0.03, NULL, 'assumption', 'Bank of Botswana, Botswana Economic and Financial Statistics, September 2026, table 4.1 (notice deposits 3.79%, savings 2.10%)', 'https://www.bankofbotswana.bw/sites/default/files/publications/Botswana%20Economic%20and%20Financial%20Statistics%20-%20September%202026%20%20.xlsx', '2026-10-31', 'Low case: notice and savings deposits, with the first P7,800 of interest tax free and 10% withholding above it.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BW', 1, 'goal_inflation_education', 0.05, NULL, 'assumption', 'Bank of Botswana, Botswana Economic and Financial Statistics, September 2026, table 2.4 cost of living index by group (education)', 'https://www.bankofbotswana.bw/sites/default/files/publications/Botswana%20Economic%20and%20Financial%20Statistics%20-%20September%202026%20%20.xlsx', '2026-10-31', 'The education price index rose about 3.4% a year from December 2016 to September 2026, below general inflation (4.9%); private school fees are assumed to rise with the 5% inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BW', 1, 'goal_inflation_health', 0.055, NULL, 'assumption', 'Bank of Botswana, Botswana Economic and Financial Statistics, September 2026, table 2.4 cost of living index by group (health)', 'https://www.bankofbotswana.bw/sites/default/files/publications/Botswana%20Economic%20and%20Financial%20Statistics%20-%20September%202026%20%20.xlsx', '2026-10-31', 'The health price index rose only about 2.2% a year from December 2016 to September 2026 because public care is subsidised, but private medical costs rise faster, so 0.5 points above the 5% inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BW', 1, 'gold_return_base', 0.055, NULL, 'assumption', 'Bank of Botswana exchange rates; World Bank official exchange rate history', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=BW', '2026-10-31', 'Base case: the long-run dollar gold trend of about 4% a year plus about 1.5% a year of pula depreciation under the crawling basket peg.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BW', 1, 'gold_return_high', 0.09, NULL, 'assumption', 'Bank of Botswana exchange rates', 'https://www.bankofbotswana.bw/content/exchange-rates', '2026-10-31', 'High case: strong gold years and a weaker pula.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BW', 1, 'gold_return_low', 0.01, NULL, 'assumption', 'Bank of Botswana exchange rates (pula per US dollar)', 'https://www.bankofbotswana.bw/content/exchange-rates', '2026-10-31', 'Low case: flat dollar gold and a small pula depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BW', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Employment Act provides a severance benefit, but its text could not be read from an official source, so the days per year of service are not given.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BW', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a major private hospital stay in Botswana was found; public hospital care is heavily subsidised.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BW', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private medical aid contributions by age were found from a public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BW', 1, 'inflation_cpi', 0.0777, NULL, 'sourced', 'Bank of Botswana, Botswana Economic and Financial Statistics, September 2026, table 2.3 annual inflation (Statistics Botswana CPI)', 'https://www.bankofbotswana.bw/sites/default/files/publications/Botswana%20Economic%20and%20Financial%20Statistics%20-%20September%202026%20%20.xlsx', '2026-09-30', 'Headline CPI up 7.8% year on year in September 2026 after 9.3% in August; above the Bank of Botswana''s 3-6% objective range since early 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BW', 1, 'inflation_projection', 0.05, NULL, 'assumption', 'Bank of Botswana 3-6% inflation objective; CPI averaged about 5.9% a year over 2021-2025 (BEFS table 2.3)', 'https://www.bankofbotswana.bw/sites/default/files/publications/Botswana%20Economic%20and%20Financial%20Statistics%20-%20September%202026%20%20.xlsx', '2026-10-31', 'Inflation has run near the top of the 3-6% objective range over five years (12.2% in 2022, 2.7-2.8% in 2024-2025, 7.8% in September 2026), so 5% a year is used for long-range plans.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BW', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life cover is sold, but no published premium rates per 1,000 pula of cover by age were found from the regulator or another public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BW', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'NBFIRA (the insurance regulator) publishes no industry-wide life claim settlement ratio that could be found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BW', 1, 'life_expectancy', 69.293, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN), Botswana', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=BW', '2024-12-31', '69.3 years in 2024 (men 66.8, women 71.9).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BW', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":18.3,"men":16.8,"women":19.8},{"age":65,"total":14.9,"men":13.6,"women":16.2},{"age":70,"total":11.8,"men":10.7,"women":12.9},{"age":80,"total":7,"men":6.1,"women":7.8}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/botswana/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BW', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Old Age Pension Scheme exists (2026/27 Budget Speech), but its eligibility age and rules could not be read from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BW', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'A universal non-contributory Old Age Pension Scheme exists (named in the 2026/27 Budget Speech), but no official current monthly amount could be read; the government social protection page could not be loaded (expired certificate).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BW', 1, 'oop_health_share', 0.0426, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), Botswana', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=BW', '2023-12-31', '4.3% in 2023 (WHO Global Health Expenditure Database); older than 2025, the latest available.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BW', 1, 'policy_rate', 0.055, NULL, 'sourced', 'Bank of Botswana, Monetary Policy Rate (interest rates page)', 'https://www.bankofbotswana.bw/content/interest-rates', '2026-10-30', 'MoPR 5.50% on 30 October 2026; raised from 3.50% in April 2026 (BEFS table 4.1).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BW', 1, 'public_pension_scheme', NULL, NULL, 'missing', '', '', '2026-10-31', 'Botswana has no public contributory pension: ''There are no social security taxes or contributions in Botswana'' (PwC Tax Summaries, reviewed 9 January 2026). Old age is covered by the universal non-contributory Old Age Pension and employer pension funds; public officers belong to a defined-contribution fund (BPOPF).', 1);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BW', 1, 'retirement_accumulation_return_base', 0.065, NULL, 'assumption', 'Bank of Botswana, Government bond and treasury bill auction results, 30 October 2026; equity base 8%; gold base 5.5%', 'https://www.bankofbotswana.bw/sites/default/files/auction-pdf-files/Government%20Bond%20Auction%20%2030%20October%202026.pdf', '2026-10-31', 'Base case: a balanced mix of government bonds, equity (local and global) funds and some gold.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BW', 1, 'retirement_accumulation_return_high', 0.085, NULL, 'assumption', 'Bank of Botswana, Government bond and treasury bill auction results, 30 October 2026; equity high 11%', 'https://www.bankofbotswana.bw/sites/default/files/auction-pdf-files/Government%20Bond%20Auction%20%2030%20October%202026.pdf', '2026-10-31', 'High case: a growth-leaning mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BW', 1, 'retirement_accumulation_return_low', 0.04, NULL, 'assumption', 'Bank of Botswana, Botswana Economic and Financial Statistics, September 2026, table 4.1', 'https://www.bankofbotswana.bw/sites/default/files/publications/Botswana%20Economic%20and%20Financial%20Statistics%20-%20September%202026%20%20.xlsx', '2026-10-31', 'Low case: a mix earning about after-tax deposit rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BW', 1, 'retirement_age_default', NULL, NULL, 'missing', '', '', '2026-10-31', 'Botswana has no public contributory pension and no statutory pension age for private employees was found; retirement ages are set by employers'' pension fund rules.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BW', 1, 'retirement_age_government', 60, NULL, 'sourced', 'Botswana Public Officers Pension Fund, member information', 'https://www.bpopf.co.bw/MemberInformation.aspx', '2026-10-31', 'Normal and compulsory retirement age for public officers is 60; early retirement from 45. Up to half of the benefit can be taken as a tax-free lump sum, the rest buys an annuity.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BW', 1, 'retirement_return_base', 0.04, NULL, 'assumption', 'Bank of Botswana, Botswana Economic and Financial Statistics, September 2026, table 4.1 (fixed deposits up to 12 months 4.21%)', 'https://www.bankofbotswana.bw/sites/default/files/publications/Botswana%20Economic%20and%20Financial%20Statistics%20-%20September%202026%20%20.xlsx', '2026-10-31', 'Base case: 12-month fixed deposits (4.21%), little taxed for a small saver; below the after-tax 1-year treasury bill yield (about 5.8%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BW', 1, 'retirement_return_high', 0.055, NULL, 'assumption', 'Bank of Botswana, Government bond and treasury bill auction results, 30 October 2026', 'https://www.bankofbotswana.bw/sites/default/files/auction-pdf-files/Government%20Bond%20Auction%20%2030%20October%202026.pdf', '2026-10-31', 'High case: part of the money in treasury bills or short government bonds after 10% tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BW', 1, 'retirement_return_low', 0.03, NULL, 'assumption', 'Bank of Botswana, Botswana Economic and Financial Statistics, September 2026, table 4.1 (notice and savings deposits)', 'https://www.bankofbotswana.bw/sites/default/files/publications/Botswana%20Economic%20and%20Financial%20Statistics%20-%20September%202026%20%20.xlsx', '2026-10-31', 'Low case: notice and savings deposits after the 10% withholding tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BW', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate or retail savings bond for individuals was found; government bonds and treasury bills are auctioned by the Bank of Botswana.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BW', 1, 'savings_account_rate', 0.021, NULL, 'sourced', 'Bank of Botswana, Botswana Economic and Financial Statistics, September 2026, table 4.1 interest rates (commercial bank savings accounts)', 'https://www.bankofbotswana.bw/sites/default/files/publications/Botswana%20Economic%20and%20Financial%20Statistics%20-%20September%202026%20%20.xlsx', '2026-08-31', 'Simple average savings-account rate of commercial and merchant banks, 2.10% in August 2026 (2.09% in July).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BW', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":15.67},{"year":2040,"value":11.49},{"year":2065,"value":4.9}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/botswana/2040/', '2025-12-31', '100 / old-age dependency ratio: 6.38 (2025, World Bank), 8.7 (2040) and 20.4 (2065, populationpyramid.net/botswana/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BW', 1, 'tax_bank_interest', 0.1, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Botswana, individual income determination', 'https://taxsummaries.pwc.com/botswana/individual/income-determination', '2026-01-09', 'Interest paid to residents is subject to 10% withholding tax, which is final; interest from a Botswana bank or building society is exempt up to BWP 7,800 a year.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BW', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate exists, and the tax treatment of government bond interest for individuals is not stated by PwC or another source read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BW', 1, 'tbill_91d_rate', 0.0566, NULL, 'sourced', 'Bank of Botswana, Government bond and treasury bill auction results, 30 October 2026 (3-month bill BOTSTB0227)', 'https://www.bankofbotswana.bw/sites/default/files/auction-pdf-files/Government%20Bond%20Auction%20%2030%20October%202026.pdf', '2026-10-30', 'Weighted average yield of winning bids 5.655% on the 3-month bill maturing 3 February 2027 (stop-out effective yield 5.878%); 5.881% at the 24 September auction.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BW', 1, 'tbond_10y_rate', 0.0902, NULL, 'sourced', 'Bank of Botswana, Government bond and treasury bill auction results, 30 October 2026 (bond BOTSGB0635, maturing June 2035)', 'https://www.bankofbotswana.bw/sites/default/files/auction-pdf-files/Government%20Bond%20Auction%20%2030%20October%202026.pdf', '2026-10-30', 'Weighted average yield 9.02% on the 8.60% bond maturing 6 June 2035 (about 8.6 years), the closest line to 10 years; the 2040 bond yielded 10.88%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BW', 1, 'tbond_5y_rate', 0.0722, NULL, 'sourced', 'Bank of Botswana, Government bond and treasury bill auction results, 30 October 2026 (bond BOTSGB0931, maturing September 2031)', 'https://www.bankofbotswana.bw/sites/default/files/auction-pdf-files/Government%20Bond%20Auction%20%2030%20October%202026.pdf', '2026-10-30', 'Weighted average yield 7.22% on the 7.75% bond maturing 10 September 2031 (about 4.9 years).', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('BY', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"BY","iso3":"BLR","nameEn":"Belarus","nameNative":"Беларусь","region":"europe_central_asia","languages":["ru","be"],"currency":{"code":"BYN","symbol":"Br","decimals":2,"compact":"intl","usdRate":{"value":2.9462,"status":"sourced","sourceName":"National Bank of the Republic of Belarus, official USD rate (API)","sourceUrl":"https://api.nbrb.by/exrates/rates/USD?parammode=2&ondate=2026-10-31","asOf":"2026-10-31","note":"Official rate BYN 2.9462 per US dollar on 31 October 2026; World Bank 2025 average 3.07."}},"instruments":{"savings_account":{"available":true,"localName":"Вклад до востребования","localNameEn":"Demand deposit","note":"Pays close to zero; most saving is done in term deposits."},"fdr_3m":{"available":true,"localName":"Срочный вклад","localNameEn":"Term deposit (3 months)"},"fdr_1y":{"available":true,"localName":"Безотзывный срочный вклад","localNameEn":"Irrevocable term deposit (1 year)"},"dps":{"available":false,"localName":null,"note":"No standard monthly recurring deposit scheme; some term deposits accept top-ups."},"sanchayapatra_5y":{"available":true,"localName":"Облигации Министерства финансов для физических лиц","localNameEn":"Ministry of Finance bonds for individuals","note":"Rates and tax treatment could not be confirmed."},"tbill_91d":{"available":false,"localName":null,"note":"No regular 91-day bill market for individuals was found."},"tbond_5y":{"available":true,"localName":"Государственные облигации","localNameEn":"Government bonds","note":"Traded on the Belarusian Currency and Stock Exchange, mostly by banks."},"tbond_10y":{"available":false,"localName":null,"note":"No regular 10-year BYN government bond found."},"equity_fund":{"available":false,"localName":null,"localNameEn":"Investment fund","note":"The local stock market is very small and no widely available diversified retail fund was found."},"gold":{"available":true,"localName":"Мерные слитки","localNameEn":"Gold bars","note":"Banks sell investment gold bars and coins."}},"institutions":{"centralBank":{"name":"National Bank of the Republic of Belarus","url":"https://www.nbrb.by/"},"insuranceRegulator":{"name":"Ministry of Finance of the Republic of Belarus (insurance supervision)","url":"https://www.minfin.gov.by/"},"insuranceComplaints":{"name":"Ministry of Finance of the Republic of Belarus (insurance supervision)","url":"https://www.minfin.gov.by/"},"pensionScheme":{"name":"Social Protection Fund (labour pensions)","url":"https://ssf.gov.by/"},"oldAgeAllowance":{"name":"Ministry of Labour and Social Protection (social pension)","url":"https://www.mintrud.gov.by/"},"publicHealthCover":{"name":"Ministry of Health (free care in state facilities)","url":"https://minzdrav.gov.by/"},"depositInsurance":{"name":"Agency for Deposit Compensation","url":"https://www.adc.by/"},"statistics":{"name":"National Statistical Committee of the Republic of Belarus","url":"https://www.belstat.gov.by/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BY', 1, 'bank_deposit_avg_rate', 0.0592, NULL, 'sourced', 'IMF International Financial Statistics (MFS_IR), Belarus deposit rate', 'https://api.imf.org/external/sdmx/2.1/data/IMF.STA,MFS_IR/BLR..M', '2026-09-30', 'September 2026; World Bank 2025 annual value 6.76%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BY', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap or typical credit card rate found; the average lending rate was 9.98% in September 2026 (IMF IFS).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BY', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'A general encyclopedia states that the Agency for Deposit Compensation guarantees individuals'' deposits in full with no fixed cap, but adc.by and nbrb.by were unreachable to confirm the current rules, so no figure is given.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BY', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No standard monthly recurring deposit scheme found; some BYN deposits accept top-ups.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BY', 1, 'equity_return_base', 0.1, NULL, 'assumption', 'Global equity long-run return in USD plus about 3% a year expected ruble depreciation; refinancing rate 9.25% (NBRB)', 'https://api.nbrb.by/exrates/rates/USD?parammode=2&ondate=2026-10-31', '2026-10-31', 'Belarus has no liquid local stock market, so the base is a global index in Belarusian ruble terms (about 7% in dollars plus about 3% depreciation), within 4 points of the after-tax safe rate of about 7.5-8%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BY', 1, 'equity_return_high', 0.13, NULL, 'assumption', 'Global equity long-run return in USD plus faster ruble depreciation; BYN 2.95 per USD (NBRB)', 'https://api.nbrb.by/exrates/rates/USD?parammode=2&ondate=2026-10-31', '2026-10-31', 'High case: strong world shares plus faster ruble depreciation, as in 2020-2024.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BY', 1, 'equity_return_low', 0.06, NULL, 'assumption', 'Global equity index in US dollar terms; BYN 2.95 per USD (NBRB)', 'https://api.nbrb.by/exrates/rates/USD?parammode=2&ondate=2026-10-31', '2026-10-31', 'Belarus has no liquid local stock market, so equity is a global index in rubles; low case is a weak decade for world shares with mild ruble depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BY', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The only figure found (about 12% on 12-13 month BYN irrevocable deposits) came from a commercial deposit-comparison site listing individual banks'' offers, which cannot be cited; nbrb.by interest-rate statistics were unreachable. The all-deposit average was 5.92% in September 2026 (IMF) and the refinancing rate 9.25%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BY', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 3-month BYN term deposit rate found: nbrb.by interest-rate statistics were unreachable.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BY', 1, 'fixed_income_return_base', 0.08, NULL, 'assumption', 'NBRB refinancing rate 9.25% (since 1 Jun 2026); IMF average deposit rate 5.92% (Sep 2026)', 'https://api.nbrb.by/refinancingrate?ondate=2026-10-31', '2026-10-31', 'Base case: BYN term deposits pay above the all-deposit average (which includes near-zero demand deposits) and track the refinancing rate, but rates are expected to fall and tax may apply to shorter deposits, so 8% is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BY', 1, 'fixed_income_return_high', 0.1, NULL, 'assumption', 'NBRB refinancing rate 9.25% (since 1 Jun 2026)', 'https://api.nbrb.by/refinancingrate?ondate=2026-10-31', '2026-10-31', 'High case: locking in longer BYN term deposits at or slightly above the refinancing rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BY', 1, 'fixed_income_return_low', 0.06, NULL, 'assumption', 'Average deposit rate 5.92% (IMF IFS, Sep 2026)', 'https://api.imf.org/external/sdmx/2.1/data/IMF.STA,MFS_IR/BLR..M', '2026-10-31', 'Low case: the average across all deposits, including low-paying ones.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BY', 1, 'goal_inflation_education', 0.07, NULL, 'assumption', 'CPI 4.6% (Sep 2026) and 6.6% (2025); no published education CPI read', 'https://www.belstat.gov.by/upload-belstat/upload-belstat-excel/Oficial_statistika/2026/express_info-2609-en.xlsx', '2026-10-31', 'Paid tuition fees tend to rise faster than headline CPI, so 7% is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BY', 1, 'goal_inflation_health', 0.07, NULL, 'assumption', 'CPI 4.6% (Sep 2026) and 6.6% (2025); no published medical CPI read', 'https://www.belstat.gov.by/upload-belstat/upload-belstat-excel/Oficial_statistika/2026/express_info-2609-en.xlsx', '2026-10-31', 'Medical goods and paid services usually rise faster than headline prices held down by price controls, so 7% is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BY', 1, 'gold_return_base', 0.07, NULL, 'assumption', 'Gold price history (Trading Economics); BYN 2.95 per USD', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Base case: dollar gold rises about 4% a year plus about 3% expected ruble depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BY', 1, 'gold_return_high', 0.11, NULL, 'assumption', 'Gold price history (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'High case: gold''s 2005-2025 trend continues and the ruble weakens faster.', 0);
