INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BY', 1, 'inflation_cpi', 0.046, NULL, 'sourced', 'National Statistical Committee of Belarus, main socio-economic indicators January-September 2026', 'https://www.belstat.gov.by/upload-belstat/upload-belstat-excel/Oficial_statistika/2026/express_info-2609-en.xlsx', '2026-09-30', 'CPI September 2026 was 104.6% of September 2025 (103.6% of December 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BY', 1, 'inflation_projection', 0.06, NULL, 'assumption', 'Belstat CPI 4.6% (Sep 2026); World Bank CPI 6.6% in 2025', 'https://www.belstat.gov.by/upload-belstat/upload-belstat-excel/Oficial_statistika/2026/express_info-2609-en.xlsx', '2026-10-31', 'Inflation has recently run at about 5-7% with price controls in place and Belarus has a long record of higher inflation, so 6% is used for planning.', 0);
