INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('BZ', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"BZ","iso3":"BLZ","nameEn":"Belize","nameNative":"Belize","region":"latin_america_caribbean","languages":["en","es","bzj"],"currency":{"code":"BZD","symbol":"$","decimals":2,"compact":"intl","usdRate":{"value":2,"status":"sourced","sourceName":"Central Bank of Belize, Monthly Economic Highlights August 2026 (notes)","sourceUrl":"https://www.centralbank.org.bz/detail-pages/publication/monthly-economic-highlights---august-2026","asOf":"2026-08-31","note":"The Belize dollar has been fixed at BZD 2.00 per US dollar since May 1976; World Bank PA.NUS.FCRF gives 2.0 for 2025."}},"instruments":{"savings_account":{"available":true,"localName":"Savings account","note":"Statutory minimum savings rate 2.5%.","sourceUrl":"https://www.centralbank.org.bz/detail-pages/publication/monthly-economic-highlights---august-2026"},"fdr_3m":{"available":true,"localName":"Time deposit","localNameEn":"3-month time (fixed) deposit","sourceUrl":"https://www.centralbank.org.bz/detail-pages/publication/monthly-economic-highlights---august-2026"},"fdr_1y":{"available":true,"localName":"Time deposit","localNameEn":"1-year time (fixed) deposit","sourceUrl":"https://www.centralbank.org.bz/detail-pages/publication/monthly-economic-highlights---august-2026"},"dps":{"available":false,"localName":null,"note":"No standard monthly recurring deposit product with a published rate."},"sanchayapatra_5y":{"available":false,"localName":null,"note":"No government savings certificate or retail savings bond for individuals was found."},"tbill_91d":{"available":true,"localName":"Treasury bill","localNameEn":"Government of Belize 91-day Treasury bill","note":"Auctioned by the Central Bank; held mainly by banks and the Central Bank.","sourceUrl":"https://www.centralbank.org.bz/detail-pages/news/2026/04/22/treasury-bill-auction-notice--7-of-2026"},"tbond_5y":{"available":true,"localName":"Treasury note","localNameEn":"Government of Belize Treasury note","note":"Fixed-coupon notes issued through the Central Bank; no market yield published.","sourceUrl":"https://www.centralbank.org.bz/detail-pages/publication/monthly-economic-highlights---august-2026"},"tbond_10y":{"available":true,"localName":"Treasury note","localNameEn":"Government of Belize Treasury note (long-dated)","note":"Long-dated notes exist but no 10-year yield is published.","sourceUrl":"https://www.centralbank.org.bz/detail-pages/publication/monthly-economic-highlights---august-2026"},"equity_fund":{"available":false,"localName":null,"note":"Belize has no stock exchange and no retail mutual fund market was found; investing abroad needs exchange control approval."},"gold":{"available":true,"localName":"Gold","localNameEn":"Gold jewellery and coins","note":"No legal restriction on buying gold; mostly sold as jewellery."}},"institutions":{"centralBank":{"name":"Central Bank of Belize","url":"https://www.centralbank.org.bz/"},"insuranceRegulator":{"name":"Office of the Supervisor of Insurance and Private Pensions (OSIPP)","url":"https://www.osipp.gov.bz/"},"insuranceComplaints":{"name":"OSIPP consumer complaints","url":"https://osipp.gov.bz/consumer-complaints/"},"pensionScheme":{"name":"Social Security Board (retirement pension)","url":"https://www.socialsecurity.org.bz/"},"oldAgeAllowance":{"name":"Non-Contributory Pension (Social Security Board)","url":"https://www.socialsecurity.org.bz/"},"publicHealthCover":{"name":"National Health Insurance (NHI), being rolled out district by district","url":"https://www.nhi.bz/"},"depositInsurance":{"name":"Deposit Insurance Act (Central Bank of Belize)","url":"https://www.centralbank.org.bz/about-the-bank/laws-and-regulations/deposit-insurance-act"},"statistics":{"name":"Statistical Institute of Belize","url":"https://sib.org.bz/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BZ', 1, 'bank_deposit_avg_rate', 0.0088, NULL, 'sourced', 'Central Bank of Belize, Monthly Economic Highlights August 2026, Table A.7', 'https://www.centralbank.org.bz/detail-pages/publication/monthly-economic-highlights---august-2026', '2026-08-31', 'Weighted average rate on all deposits 0.88% (demand deposits pay 0.12%); rolling 12-month rate on new deposits 1.78%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BZ', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched CBB and government sources: no legal cap on credit card interest found (the CBB has proposed a cap only for moneylenders); no official typical rate is published.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BZ', 1, 'deposit_insurance_limit', 20000, NULL, 'sourced', 'Central Bank of Belize, Deposit Insurance Act', 'https://www.centralbank.org.bz/about-the-bank/laws-and-regulations/deposit-insurance-act', '2020-01-31', 'Deposit Insurance Act 2020 (signed January 2020): generally BZD 20,000 of an insured deposit is covered. The CBB page describes the fund in the future tense and does not confirm it is operating; the Act dates from 2020 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BZ', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched CBB tables and regulator material: no monthly recurring deposit product rate is published for Belize.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BZ', 1, 'equity_return_base', 0.06, NULL, 'assumption', 'No Belize stock exchange; global equity index in US dollars (BZD is pegged); savings rate 2.60%', 'https://www.centralbank.org.bz/detail-pages/publication/monthly-economic-highlights---august-2026', '2026-10-31', 'Base case on a global index in US-dollar terms, kept within 4 points of the 2.6% safe savings rate since there is no local market.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BZ', 1, 'equity_return_high', 0.09, NULL, 'assumption', 'No Belize stock exchange; global equity index in US dollars (BZD is pegged)', 'https://www.centralbank.org.bz/detail-pages/publication/monthly-economic-highlights---august-2026', '2026-10-31', 'High case near the long-run nominal US-dollar return of global shares.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BZ', 1, 'equity_return_low', 0.02, NULL, 'assumption', 'No Belize stock exchange; global equity index in US dollars (BZD is pegged)', 'https://www.centralbank.org.bz/detail-pages/publication/monthly-economic-highlights---august-2026', '2026-10-31', 'Low case for a global index fund held in pegged dollars over a weak decade; there is no local stock market and buying foreign assets needs exchange control approval.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BZ', 1, 'fdr_1y_rate', 0.0205, NULL, 'sourced', 'Central Bank of Belize, Monthly Economic Highlights August 2026, Table A.7 (weighted average time deposit rate)', 'https://www.centralbank.org.bz/detail-pages/publication/monthly-economic-highlights---august-2026', '2026-08-31', 'Weighted average rate on all time deposits (all terms) 2.05%; new time deposits over the past 12 months averaged 2.54%. No separate 1-year rate is published.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BZ', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'CBB tables give only an all-terms weighted time deposit rate (2.05% in August 2026), not a 3-month rate; no official 3-month figure found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BZ', 1, 'fixed_income_return_base', 0.022, NULL, 'assumption', 'CBB Monthly Economic Highlights Aug 2026: savings 2.60%, time deposits 2.05%', 'https://www.centralbank.org.bz/detail-pages/publication/monthly-economic-highlights---august-2026', '2026-10-31', 'Base case: a mix of savings (statutory minimum 2.5%) and time deposits around 2%; interest tax on deposits removed or minor.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BZ', 1, 'fixed_income_return_high', 0.03, NULL, 'assumption', 'CBB Monthly Economic Highlights Aug 2026: new time deposits 2.54% (12-month rolling)', 'https://www.centralbank.org.bz/detail-pages/publication/monthly-economic-highlights---august-2026', '2026-10-31', 'High case: negotiated longer time deposits at about 3%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BZ', 1, 'fixed_income_return_low', 0.006, NULL, 'assumption', 'CBB Quarterly Review March 2026 (91-day T-bill 0.60%)', 'https://www.centralbank.org.bz/detail-pages/publication/quarterly-review---march-2026', '2026-10-31', 'Low case: Treasury bill yields of about 0.6%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BZ', 1, 'goal_inflation_education', 0.035, NULL, 'assumption', 'CBB Monthly Economic Highlights Aug 2026, Table A.20: education services up 1.0% year to date', 'https://www.centralbank.org.bz/detail-pages/publication/monthly-economic-highlights---august-2026', '2026-10-31', 'Education services rose only 1% in 2026, but fees move in steps, so we plan with the headline projection plus half a point.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BZ', 1, 'goal_inflation_health', 0.045, NULL, 'assumption', 'CBB Monthly Economic Highlights Aug 2026, Table A.20: health sub-index up 5.2% year to date', 'https://www.centralbank.org.bz/detail-pages/publication/monthly-economic-highlights---august-2026', '2026-10-31', 'Health prices are rising faster than the headline CPI (5.2% vs 2.9% year to date), so we plan with the 3% projection plus 1.5 points.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BZ', 1, 'gold_return_base', 0.045, NULL, 'assumption', 'Belize dollar fixed at BZD 2 = USD 1 since 1976 (Central Bank of Belize)', 'https://www.centralbank.org.bz/detail-pages/publication/monthly-economic-highlights---august-2026', '2026-10-31', 'Long-run dollar gold trend of about 4-5% a year, with no expected depreciation under the fixed peg.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BZ', 1, 'gold_return_high', 0.08, NULL, 'assumption', 'Belize dollar fixed at BZD 2 = USD 1 since 1976 (Central Bank of Belize)', 'https://www.centralbank.org.bz/detail-pages/publication/monthly-economic-highlights---august-2026', '2026-10-31', 'High case with strong dollar gold, or a peg under stress.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BZ', 1, 'gold_return_low', 0.01, NULL, 'assumption', 'Belize dollar fixed at BZD 2 = USD 1 since 1976 (Central Bank of Belize)', 'https://www.centralbank.org.bz/detail-pages/publication/monthly-economic-highlights---august-2026', '2026-10-31', 'Low case: weak dollar gold price; the peg means no currency boost.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BZ', 1, 'gratuity_rule', NULL, '{"daysPerYear":6,"daysPerYearAfter":12,"afterYears":10,"daysPerMonth":26}', 'sourced', 'Caribbean Court of Justice, [2025] CCJ 14 (AJ) BZ, quoting Labour Act Cap. 297 s.183', 'https://ccj.org/wp-content/uploads/2025/11/2025_CCJ_14_AJ_BZ.pdf', '2025-11-05', 'Severance on retirement at 60+ (or medical grounds) or termination: one week''s wages per year with 5-10 years'' service; two weeks per year with over 10 years (one week for service before 2012). Resigning after 10 years gives an equal gratuity. A week is modelled as 6 of 26 working days a month. The CCJ held in November 2025 that retirees qualify.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BZ', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched Ministry of Health and Wellness, NHI and public sources: no official typical private hospital bill is published (only expat-guide estimates).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BZ', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched OSIPP and public sources: no published private health insurance premiums by age.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BZ', 1, 'inflation_cpi', 0.047, NULL, 'sourced', 'Statistical Institute of Belize, CPI release for September 2026', 'https://sib.org.bz/consumer-prices-up-4-7-percent-imports-down-3-8-percent-domestic-exports-up-11-5-percent-and-consumer-confidence-index-down-9-6-percent-in-september-2026/', '2026-09-30', 'All-items CPI 126.2 in September 2026 against 120.5 a year earlier (4.7% year on year); January-September 2026 inflation 3.1% against the same period of 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BZ', 1, 'inflation_projection', 0.03, NULL, 'assumption', 'World Bank FP.CPI.TOTL.ZG for Belize: 3.2, 6.3, 4.4, 3.3 and 1.1% in 2021-2025', 'https://data.worldbank.org/indicator/FP.CPI.TOTL.ZG?locations=BZ', '2026-10-31', 'Belize has no inflation target (dollar fixed to the US dollar); the 2021-2025 average is 3.7% but the 10-year average is about 2%, so we plan with 3%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BZ', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life is sold in Belize, but no regulator or public source publishes premium rates by age; only individual insurer quotes exist.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BZ', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched OSIPP insurance statistics and annual reports: no industry-wide life claim settlement ratio is published.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BZ', 1, 'life_expectancy', 73.739, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=BZ', '2024-12-31', 'UN WPP 2024 (via populationpyramid.net) gives 74.1 for 2026 (men 71.4, women 77.0).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BZ', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":19.6,"men":18.1,"women":21.1},{"age":65,"total":16,"men":14.8,"women":17.2},{"age":70,"total":12.8,"men":12,"women":13.6},{"age":80,"total":7.35,"men":7.1,"women":7.6}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/belize/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BZ', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":67,"womenAge":65,"over90Monthly":null,"meansTested":true}', 'sourced', 'Social Security Board, 2025 Actuarial Review (July 2026), section 5.1.5 Non-Contributory Pension', 'https://socialsecurity.org.bz/wp-content/uploads/2026/08/BELIZE-SSB-2025-Actuarial-Review-Final-Report-2026-07-30.pdf', '2025-12-31', 'Women 65+ and men 67+ born or naturalised Belizean with no income or adequate support; only one person per household, and no one else in the home may receive an SSB pension. A single age for both sexes is under consideration.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BZ', 1, 'old_age_allowance_monthly', 100, NULL, 'sourced', 'Social Security Board, 2025 Actuarial Review (July 2026), section 5.1.5 Non-Contributory Pension', 'https://socialsecurity.org.bz/wp-content/uploads/2026/08/BELIZE-SSB-2025-Actuarial-Review-Final-Report-2026-07-30.pdf', '2025-12-31', 'BZD 100 a month, unchanged since 2007; open to new claims (97 awarded in 2022-2024) and paid to just over 800 people in 2025. Means-tested.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BZ', 1, 'oop_health_share', 0.2678, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=BZ', '2023-12-31', 'Figure is for 2023 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BZ', 1, 'policy_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No policy interest rate is published by the Central Bank of Belize; the Belize dollar is fixed at BZD 2.00 = USD 1.00 (CBB Monthly Economic Highlights, August 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BZ', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":14,"entryAgeMax":null,"pensionFromAge":65,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'Social Security Board, 2025 Actuarial Review (July 2026)', 'https://socialsecurity.org.bz/wp-content/uploads/2026/08/BELIZE-SSB-2025-Actuarial-Review-Final-Report-2026-07-30.pdf', '2026-07-30', 'Compulsory social security for employed and self-employed people from 14; 10% contribution (split by wage band). Pension from 65 (60 if not working) with 500 contributions, 30% of best-3-year average insurable earnings plus 2% per 50 weeks from 500 to 750. Pensions are not indexed (adjusted only once, in 2016).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BZ', 1, 'retirement_accumulation_return_base', 0.04, NULL, 'assumption', 'Savings rate 2.60%; global equity in pegged dollars', 'https://www.centralbank.org.bz/detail-pages/publication/monthly-economic-highlights---august-2026', '2026-10-31', 'Base case: a mix of deposits at 2-2.6% and some global equity, limited by exchange controls on foreign investment.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BZ', 1, 'retirement_accumulation_return_high', 0.06, NULL, 'assumption', 'Savings rate 2.60%; global equity in pegged dollars', 'https://www.centralbank.org.bz/detail-pages/publication/monthly-economic-highlights---august-2026', '2026-10-31', 'High case with a larger global equity share.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BZ', 1, 'retirement_accumulation_return_low', 0.025, NULL, 'assumption', 'Savings rate 2.60%; global equity in pegged dollars', 'https://www.centralbank.org.bz/detail-pages/publication/monthly-economic-highlights---august-2026', '2026-10-31', 'Low case for a balanced mix dominated by deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BZ', 1, 'retirement_age_default', 65, NULL, 'sourced', 'Social Security Board, 2025 Actuarial Review (July 2026)', 'https://socialsecurity.org.bz/wp-content/uploads/2026/08/BELIZE-SSB-2025-Actuarial-Review-Final-Report-2026-07-30.pdf', '2026-07-30', 'SSB retirement pension from 65 whether working or not, or from 60 if no longer employed; the review does not recommend raising pension ages now. No statutory private-sector retirement age.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BZ', 1, 'retirement_age_government', 55, NULL, 'sourced', 'Amandala: GoB and the retirement age (editorial on the public service retirement age)', 'https://amandala.com.bz/news/?p=343003', '2023-03-25', 'Public officers retire at 55 under the Pensions Act; the government cited an IMF recommendation to raise it to 65 in the 2023/24 budget, but no enacted change was found (source from 2023, older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BZ', 1, 'retirement_return_base', 0.02, NULL, 'assumption', 'CBB Monthly Economic Highlights Aug 2026: time deposits 2.05%, savings 2.60%', 'https://www.centralbank.org.bz/detail-pages/publication/monthly-economic-highlights---august-2026', '2026-10-31', 'Base case at the weighted 2.05% time deposit rate, the safe 1-year rate available (deposit interest tax removed or minor).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BZ', 1, 'retirement_return_high', 0.03, NULL, 'assumption', 'CBB Monthly Economic Highlights Aug 2026: new time deposits 2.54% (12-month rolling)', 'https://www.centralbank.org.bz/detail-pages/publication/monthly-economic-highlights---august-2026', '2026-10-31', 'High case: negotiated longer time deposits around 3%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BZ', 1, 'retirement_return_low', 0.006, NULL, 'assumption', 'CBB Quarterly Review March 2026 (91-day T-bill 0.60%)', 'https://www.centralbank.org.bz/detail-pages/publication/quarterly-review---march-2026', '2026-10-31', 'Low case: Treasury bills or demand-like deposits around 0.6%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BZ', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched CBB and Ministry of Finance material: no government savings certificate or retail savings bond for individuals was found; government domestic debt is in Treasury bills and Treasury notes held mainly by the Central Bank, banks and institutions.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BZ', 1, 'savings_account_rate', 0.026, NULL, 'sourced', 'Central Bank of Belize, Monthly Economic Highlights August 2026, Table A.7 (domestic banks'' weighted average interest rates)', 'https://www.centralbank.org.bz/detail-pages/publication/monthly-economic-highlights---august-2026', '2026-08-31', 'Weighted average savings deposit rate 2.60% (savings/chequing 2.61%); the statutory minimum rate on savings deposits is 2.5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BZ', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":13.1},{"year":2040,"value":7.6},{"year":2065,"value":3}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/belize/2040/', '2025-12-31', '100 / old-age dependency ratio: 7.6 (2025, World Bank), 13.2 (2040) and 33.8 (2065, populationpyramid.net/belize/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BZ', 1, 'tax_bank_interest', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Income and Business Tax (Amendment) Act 2024 (Act No. 40 of 2024) removed the tax on interest on time deposits, but the Act text could not be opened (National Assembly site suspended) and the treatment of savings interest was not confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BZ', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No retail government savings certificate exists in Belize to tax; interest on Government of Belize notes and bonds is reported as tax-exempt, but no primary source was read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BZ', 1, 'tbill_91d_rate', 0.006, NULL, 'sourced', 'Central Bank of Belize, Quarterly Review March 2026 (open market operations)', 'https://www.centralbank.org.bz/detail-pages/publication/quarterly-review---march-2026', '2026-03-31', 'Weighted average 91-day Treasury bill auction yield 0.595% in Q1 2026 (range 0.590-0.600%); later 2026 auction notices do not state yields.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BZ', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched CBB publications: no 10-year government bond yield is published for Belize.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('BZ', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched CBB publications: Belize Treasury notes are issued at fixed coupons but no 5-year market yield is published.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('CA', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"CA","iso3":"CAN","nameEn":"Canada","nameNative":"Canada","region":"north_america","languages":["en","fr","zh","pa","es"],"currency":{"code":"CAD","symbol":"$","decimals":2,"compact":"intl","usdRate":{"value":1.396,"status":"sourced","sourceName":"Bank of Canada, daily average exchange rate USD/CAD (FXUSDCAD)","sourceUrl":"https://www.bankofcanada.ca/valet/observations/FXUSDCAD/json?recent=5","asOf":"2026-10-30","note":"CAD 1.3960 per US dollar on 30 October 2026; World Bank 2025 average 1.398."}},"instruments":{"savings_account":{"available":true,"localName":"Savings account","note":"Posted rates at large banks are near zero; high-interest savings accounts pay more. A Tax-Free Savings Account (TFSA) shelters interest from tax.","sourceUrl":"https://www.bankofcanada.ca/valet/observations/V80691338/json?recent=5"},"fdr_3m":{"available":true,"localName":"Short-term GIC","localNameEn":"Guaranteed investment certificate / term deposit (3 months)","note":"Short-term GICs and term deposits (30 days to 1 year) are sold by banks and credit unions; no official average rate is published."},"fdr_1y":{"available":true,"localName":"GIC","localNameEn":"Guaranteed investment certificate (1 year)","note":"Covered by CDIC up to CAD 100,000 per category when held at a member institution.","sourceUrl":"https://www.bankofcanada.ca/valet/observations/V80691339/json?recent=5"},"dps":{"available":false,"localName":null,"note":"No standard monthly recurring-deposit product; savers set up automatic transfers into savings accounts, GICs or funds."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":"Canada Savings Bonds (discontinued)","note":"Sales of new Canada Savings Bonds ended in 2017; a few provinces have issued their own savings bonds in some years.","sourceUrl":"https://www.budget.canada.ca/2017/docs/plan/chap-04-en.html"},"tbill_91d":{"available":true,"localName":"Treasury bills","localNameEn":"Government of Canada treasury bills","note":"Sold at Bank of Canada auctions to dealers; individuals buy them through a broker or via money-market funds.","sourceUrl":"https://www.bankofcanada.ca/valet/observations/V80691303/json?recent=5"},"tbond_5y":{"available":true,"localName":"Government of Canada bonds","sourceUrl":"https://www.bankofcanada.ca/valet/observations/BD.CDN.5YR.DQ.YLD/json?recent=5"},"tbond_10y":{"available":true,"localName":"Government of Canada bonds","sourceUrl":"https://www.bankofcanada.ca/valet/observations/BD.CDN.10YR.DQ.YLD/json?recent=5"},"equity_fund":{"available":true,"localName":null,"localNameEn":"Mutual funds and index ETFs","note":"Usually held in a TFSA (tax-free) or RRSP (tax-deferred)."},"gold":{"available":true,"localName":null,"localNameEn":"Gold bars and coins","note":"Legal to buy; investment-grade gold bars and coins of 99.5% purity or more are exempt from GST/HST."}},"institutions":{"centralBank":{"name":"Bank of Canada","url":"https://www.bankofcanada.ca/"},"insuranceRegulator":{"name":"Office of the Superintendent of Financial Institutions (OSFI); provincial insurance regulators (Canadian Council of Insurance Regulators)","url":"https://www.osfi-bsif.gc.ca/en","note":"OSFI supervises federally regulated insurers'' finances; provincial regulators (coordinated through CCIR, https://www.ccir-ccrra.org/) license insurers and oversee market conduct."},"insuranceComplaints":{"name":"OmbudService for Life and Health Insurance (OLHI)","url":"https://www.olhi.ca/","note":"Free, independent ombudsman for life and health insurance complaints after the insurer''s own process."},"pensionScheme":{"name":"Canada Pension Plan (CPP)","url":"https://www.canada.ca/en/services/benefits/publicpensions/cpp.html","note":"Quebec workers are covered by the Quebec Pension Plan (QPP) instead."},"oldAgeAllowance":{"name":"Old Age Security (OAS) pension and Guaranteed Income Supplement","url":"https://www.canada.ca/en/services/benefits/publicpensions/old-age-security.html"},"publicHealthCover":{"name":"Canada''s health care system (provincial and territorial health insurance plans)","url":"https://www.canada.ca/en/health-canada/services/canada-health-care-system.html","note":"Medically necessary hospital and physician services are free for insured residents under the Canada Health Act."},"depositInsurance":{"name":"Canada Deposit Insurance Corporation (CDIC)","url":"https://www.cdic.ca/"},"statistics":{"name":"Statistics Canada","url":"https://www.statcan.gc.ca/en/start"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CA', 1, 'bank_deposit_avg_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No current weighted average deposit rate was found from the Bank of Canada or Statistics Canada; World Bank FR.INR.DPST for Canada stops in 2017 (0.1%, a posted savings rate).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CA', 1, 'credit_card_rate_cap', 0.19, NULL, 'sourced', 'Financial Consumer Agency of Canada, How credit cards work', 'https://www.canada.ca/en/financial-consumer-agency/services/credit-cards/credit-card-work.html', '2026-10-31', 'FCAC''s example rate for regular purchases is 19% (22% for cash advances); specialised and retail cards may charge more. The legal ceiling is the criminal rate of 35% APR (Criminal Code s.347, https://laws-lois.justice.gc.ca/eng/acts/C-46/section-347.html), which does not bind standard cards.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CA', 1, 'deposit_insurance_limit', 100000, NULL, 'sourced', 'Canada Deposit Insurance Corporation (CDIC), what''s covered', 'https://www.cdic.ca/depositors/whats-covered/', '2026-10-31', 'CAD 100,000 (principal and interest) per depositor per member institution in each of nine categories (single name, joint, RRSP, RRIF, TFSA, RDSP, RESP, FHSA, trust). GICs and term deposits are covered.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CA', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Canadian banks do not sell a standard monthly recurring-deposit product with its own rate; savers use pre-authorised transfers into savings accounts or GICs, and the Bank of Canada publishes no such rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CA', 1, 'equity_return_base', 0.06, NULL, 'assumption', 'S&P/TSX Composite (Trading Economics); after-tax safe rate about 2-2.5% (1-year GIC 2.45%, 3-month bill 2.53%, Bank of Canada)', 'https://tradingeconomics.com/canada/stock-market', '2026-10-31', 'Base case: about 3.5-4 points above the after-tax safe rate, in line with the TSX''s long-run total return with dividends, and within the 4-point cap.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CA', 1, 'equity_return_high', 0.08, NULL, 'assumption', 'S&P/TSX Composite (Trading Economics); long-run global equity returns', 'https://tradingeconomics.com/canada/stock-market', '2026-10-31', 'High case: a diversified Canadian and global equity index fund held in a TFSA or RRSP earns long-run equity returns of about 8% in Canadian dollars.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CA', 1, 'equity_return_low', 0.035, NULL, 'assumption', 'S&P/TSX Composite 35,620 on 30 Oct 2026, +17.7% in a year, record 37,069 in Aug 2026 (Trading Economics)', 'https://tradingeconomics.com/canada/stock-market', '2026-10-31', 'Low case: after a strong run from a record high, Canadian shares earn little more than safe GICs for a long stretch.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CA', 1, 'fdr_1y_rate', 0.0245, NULL, 'sourced', 'Bank of Canada, chartered bank posted rates: guaranteed investment certificates, 1-year (V80691339)', 'https://www.bankofcanada.ca/valet/observations/V80691339/json?recent=5', '2026-10-28', 'Weekly posted rate 2.45%; 3-year GIC 3.20% (V80691340), 5-year GIC 2.75% (V80691341), 5-year personal fixed-term deposit 2.65% (V80691336).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CA', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Bank of Canada publishes posted chartered-bank rates only for 1-, 3- and 5-year GICs and 5-year personal term deposits; no 3-month term deposit rate was found from the Bank of Canada or Statistics Canada.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CA', 1, 'fixed_income_return_base', 0.022, NULL, 'assumption', '1-year GIC 2.45%, 3-year GIC 3.20% posted (Bank of Canada); 3-month bill 2.53%', 'https://www.bankofcanada.ca/valet/observations/V80691339/json?recent=5', '2026-10-31', 'Base case: a mix of GICs and bills taxed at about 20%, partly held tax-free in a TFSA.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CA', 1, 'fixed_income_return_high', 0.03, NULL, 'assumption', '5-year Government of Canada bond 3.51%; 3-year GIC 3.20% (Bank of Canada)', 'https://www.bankofcanada.ca/valet/observations/BD.CDN.5YR.DQ.YLD/json?recent=5', '2026-10-31', 'High case: locking in 3-5 year government bonds or GICs inside a TFSA, so little tax is paid.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CA', 1, 'fixed_income_return_low', 0.015, NULL, 'assumption', '1-year GIC 2.45% less about 20% tax = 1.96% (Bank of Canada V80691339)', 'https://www.bankofcanada.ca/valet/observations/V80691339/json?recent=5', '2026-10-31', 'Low case: GIC and bill rates fall back towards 2% and are taxed at about 20-30%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CA', 1, 'goal_inflation_education', 0.035, NULL, 'assumption', 'Statistics Canada: tuition fees rose 2.4% in 2026 (1.7% in 2025)', 'https://www150.statcan.gc.ca/n1/daily-quotidien/261019/dq261019a-eng.htm', '2026-10-31', 'Tuition rises are capped or frozen in several provinces but living and residence costs rise faster, so 3.5% is used for education goals.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CA', 1, 'goal_inflation_health', 0.035, NULL, 'assumption', 'Statistics Canada CPI September 2026 (all items 3.1%)', 'https://www150.statcan.gc.ca/n1/daily-quotidien/261019/dq261019a-eng.htm', '2026-10-31', 'Hospital and doctor care is publicly funded, but prescription drugs, dental care and long-term care costs rise faster than CPI, so 3.5% is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CA', 1, 'gold_return_base', 0.04, NULL, 'assumption', 'Gold price history (Trading Economics); Bank of Canada 2% target', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Base case: dollar gold rises with world inflation plus a little, with no long-run trend in the Canadian dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CA', 1, 'gold_return_high', 0.07, NULL, 'assumption', 'Gold price history (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'High case: a repeat of gold''s strong 2005-2025 trend in Canadian-dollar terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CA', 1, 'gold_return_low', 0.01, NULL, 'assumption', 'Gold USD 3,876/oz on 30 Oct 2026, 31% below the January 2026 high (Trading Economics); USD/CAD 1.396 (Bank of Canada)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Low case: gold drifts after the 2025-26 spike and the Canadian dollar holds against the US dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CA', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'Canadian employment law has no gratuity or end-of-service payment on resignation or retirement. Only employer terminations trigger statutory pay, e.g. federal severance of 2 days'' wages per year of service (minimum 5 days) after 12 months (Canada Labour Code s.235: https://laws-lois.justice.gc.ca/eng/acts/L-2/section-235.html); provinces have similar notice or severance rules.', 1);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CA', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'Medically necessary hospital stays are covered without charge for residents under provincial health insurance plans (Canada Health Act), so the typical out-of-pocket cost is nil; no official figure for a private self-pay stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CA', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Private health insurance in Canada only supplements provincial plans (drugs, dental, vision, private room) and is priced per plan, not per sum insured; no official premium table per CAD 100,000 of cover was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CA', 1, 'inflation_cpi', 0.031, NULL, 'sourced', 'Statistics Canada, The Daily: Consumer Price Index, September 2026', 'https://www150.statcan.gc.ca/n1/daily-quotidien/261019/dq261019a-eng.htm', '2026-09-30', 'CPI rose 3.1% year on year in September 2026 (3.0% in August), driven by gasoline (+27.8%); CPI excluding gasoline 2.2%. World Bank 2025 average 2.1%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CA', 1, 'inflation_projection', 0.022, NULL, 'assumption', 'Bank of Canada 2% inflation target (1-3% band); CPI 3.1% (Sep 2026), 2.1% in 2025 (World Bank)', 'https://www.bankofcanada.ca/core-functions/monetary-policy/inflation/', '2026-10-31', 'The Bank of Canada''s 2% target has been credible over decades and inflation excluding energy is near it, so a small margin above target, 2.2%, is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CA', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life insurance is widely sold in Canada, but no regulator or government body publishes indicative premiums per CAD 1,000 of cover by age; insurer and broker quote tools were not used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CA', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Neither OSFI, the provincial insurance regulators (CCIR) nor the OmbudService for Life and Health Insurance publishes an industry-wide life insurance claim settlement ratio for Canada.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CA', 1, 'life_expectancy', 83.1, NULL, 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/canada', '2026-07-01', 'Men 80.9, women 85.2 (UN WPP estimate for 2026). World Bank 2024: 82.1 (men 80.0, women 84.3).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CA', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":25.8,"men":24.2,"women":27.3},{"age":65,"total":21.6,"men":20.1,"women":22.9},{"age":70,"total":17.6,"men":16.3,"women":18.7},{"age":80,"total":10.4,"men":9.4,"women":11.1}]}', 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/canada', '2026-07-01', 'Remaining years from georank''s expected age at death by current age (UN WPP 2026 estimate).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CA', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":65,"womenAge":65,"over90Monthly":null,"meansTested":false}', 'sourced', 'Government of Canada, Old Age Security eligibility', 'https://www.canada.ca/en/services/benefits/publicpensions/old-age-security/eligibility.html', '2026-10-31', 'Age 65+, 10 years'' residence in Canada after 18 (20 years if living abroad); not based on work history. It is not means-tested, but it is clawed back from high incomes (recovery tax above CAD 93,454 net income in 2025, fully gone above about CAD 152,062 at 65-74). The over-75 amount is 10% higher.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CA', 1, 'old_age_allowance_monthly', 762.5, NULL, 'sourced', 'Government of Canada, Old Age Security payment amounts (October-December 2026)', 'https://www.canada.ca/en/services/benefits/publicpensions/old-age-security/payments.html', '2026-10-01', 'Maximum OAS pension CAD 762.50 a month at 65-74 and CAD 838.75 at 75+, for October-December 2026, with 40 years of residence after 18 (partial from 10 years). Adjusted quarterly for CPI; taxable. Low-income pensioners also get the Guaranteed Income Supplement (up to CAD 1,138.90 a month for a single person).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CA', 1, 'oop_health_share', 0.1528, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=CA', '2024-12-31', '15.3% in 2024, the latest World Bank year.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CA', 1, 'policy_rate', 0.025, NULL, 'sourced', 'Bank of Canada, policy interest rate (target for the overnight rate)', 'https://www.bankofcanada.ca/core-functions/monetary-policy/key-interest-rate/', '2026-10-29', 'Raised 25 basis points to 2.50% on 28 October 2026 (effective 29 October), after holding at 2.25% since October 2025; next decision 9 December 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CA', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":18,"entryAgeMax":70,"pensionFromAge":65,"nomineeUntilAge":null,"inflationLinked":true,"taxFree":false}', 'sourced', 'Government of Canada, CPP retirement pension: how much you could receive', 'https://www.canada.ca/en/services/benefits/publicpensions/cpp/cpp-benefit/amount.html', '2026-10-31', 'Canada Pension Plan (Quebec has the QPP): contributory, earnings-related; contribution rates of 9.9% (base) and 11.9% (with the enhancement) of pensionable earnings, shared equally by employee and employer. Maximum at 65 CAD 1,507.65 a month (January 2026), average CAD 858.34 (July 2026). Start from 60 to 70; benefits are indexed to CPI each January; taxable income.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CA', 1, 'retirement_accumulation_return_base', 0.045, NULL, 'assumption', 'Fixed income base 2.2% (taxed) to 3% (sheltered); equity base 6%', 'https://tradingeconomics.com/canada/stock-market', '2026-10-31', 'Base case: roughly half shares at 6% and half GICs and bonds at about 3%, held in RRSPs and TFSAs.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CA', 1, 'retirement_accumulation_return_high', 0.06, NULL, 'assumption', 'Fixed income high 3%; equity high 8%', 'https://tradingeconomics.com/canada/stock-market', '2026-10-31', 'High case for a growth-leaning balanced mix in tax-sheltered accounts.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CA', 1, 'retirement_accumulation_return_low', 0.03, NULL, 'assumption', 'After-tax safe rate about 2%; TSX record (Trading Economics)', 'https://tradingeconomics.com/canada/stock-market', '2026-10-31', 'Low case for a balanced mix if shares lag, mostly sheltered in an RRSP or TFSA.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CA', 1, 'retirement_age_default', 65, NULL, 'sourced', 'Government of Canada, CPP retirement pension: when to start', 'https://www.canada.ca/en/services/benefits/publicpensions/cpp/cpp-benefit/when-start.html', '2026-10-31', 'The standard CPP age is 65 for men and women; it can start from 60 (0.6% less per month early, up to 36%) to 70 (0.7% more per month, up to 42%). OAS also starts at 65. There is no mandatory retirement age for private employees.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CA', 1, 'retirement_age_government', 65, NULL, 'sourced', 'Public Service Superannuation Act, section 12.1 (Group 2 contributors)', 'https://laws-lois.justice.gc.ca/eng/acts/P-36/section-12.1.html', '2026-10-31', 'Federal public servants who joined from 2013 (Group 2) get an immediate unreduced pension at 65 (s.12.1); those who joined earlier (Group 1) at 60, or 55 with 30 years of service (s.13). There is no compulsory retirement age.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CA', 1, 'retirement_return_base', 0.02, NULL, 'assumption', '1-year GIC 2.45% and 3-month bill 2.53% less about 20% tax = 1.96-2.02% (Bank of Canada)', 'https://www.bankofcanada.ca/valet/observations/V80691339/json?recent=5', '2026-10-31', 'Base case capped at the after-tax 1-year GIC and 3-month bill rate for a modest-income retiree.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CA', 1, 'retirement_return_high', 0.028, NULL, 'assumption', '3-year GIC 3.20% and 5-year Government of Canada bond 3.51% (Bank of Canada)', 'https://www.bankofcanada.ca/valet/observations/BD.CDN.5YR.DQ.YLD/json?recent=5', '2026-10-31', 'High case: a retiree ladders GICs and government bonds, partly inside a TFSA, at about today''s rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CA', 1, 'retirement_return_low', 0.015, NULL, 'assumption', '1-year GIC 2.45% less about 20% tax (Bank of Canada V80691339)', 'https://www.bankofcanada.ca/valet/observations/V80691339/json?recent=5', '2026-10-31', 'Low case: GIC and bill rates fall back after the current rise.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CA', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Government of Canada discontinued sales of new Canada Savings Bonds in 2017 (Budget 2017, chapter 4: https://www.budget.canada.ca/2017/docs/plan/chap-04-en.html); there is no federal retail savings bond today.', 1);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CA', 1, 'savings_account_rate', 0.0001, NULL, 'sourced', 'Bank of Canada, chartered bank posted rates: non-chequable savings deposits (V80691338)', 'https://www.bankofcanada.ca/valet/observations/V80691338/json?recent=5', '2026-10-28', 'Posted rate 0.01% at chartered banks (also 0.01% on daily-interest savings balances over CAD 100,000, V80691337). High-interest savings accounts and promotional rates pay more; interest inside a TFSA is tax-free.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CA', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":3.2},{"year":2040,"value":2.54},{"year":2065,"value":2.07}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/canada/2040/', '2025-12-31', '100 / old-age dependency ratio: 31.3 (2025, World Bank), 39.4 (2040) and 48.4 (2065, populationpyramid.net/canada/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CA', 1, 'tax_bank_interest', 0.2, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Canada: taxes on personal income (2026 federal brackets)', 'https://taxsummaries.pwc.com/canada/individual/taxes-on-personal-income', '2026-10-31', 'No withholding on interest paid to residents; interest is fully taxed at the saver''s marginal rate. The lowest 2026 federal rate is 14% (to CAD 58,523) plus a provincial rate (about 5-10% in the lowest bracket), so about 20% for a modest earner; combined top rates 44.5-54.8%. Interest inside a TFSA is tax-free, and inside an RRSP tax is deferred.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CA', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No federal retail savings bond is sold (Canada Savings Bonds ended in 2017); government bond interest is taxed like bank interest at the marginal rate (PwC Tax Summaries).', 1);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CA', 1, 'tbill_91d_rate', 0.0253, NULL, 'sourced', 'Bank of Canada, Treasury bill auction average yield, 3-month (V80691303)', 'https://www.bankofcanada.ca/valet/observations/V80691303/json?recent=5', '2026-10-20', 'Average yield at the 20 October 2026 auction, before the 28 October policy rate rise; 2.41% on 6 October.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CA', 1, 'tbond_10y_rate', 0.0378, NULL, 'sourced', 'Bank of Canada, Government of Canada 10-year benchmark bond yield (BD.CDN.10YR.DQ.YLD)', 'https://www.bankofcanada.ca/valet/observations/BD.CDN.10YR.DQ.YLD/json?recent=5', '2026-10-30', 'Daily benchmark yield 3.78% on 30 October 2026 (3.84% on 29 October).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CA', 1, 'tbond_5y_rate', 0.0351, NULL, 'sourced', 'Bank of Canada, Government of Canada 5-year benchmark bond yield (BD.CDN.5YR.DQ.YLD)', 'https://www.bankofcanada.ca/valet/observations/BD.CDN.5YR.DQ.YLD/json?recent=5', '2026-10-30', 'Daily benchmark yield 3.51% on 30 October 2026 (3.58% on 29 October).', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('CD', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"CD","iso3":"COD","nameEn":"DR Congo","nameNative":"République démocratique du Congo","region":"sub_saharan_africa","languages":["sw","lua","fr","ln","kg"],"currency":{"code":"CDF","symbol":"FC","decimals":2,"compact":"intl","usdRate":{"value":2270.47,"status":"sourced","sourceName":"Banque Centrale du Congo, indicative exchange rate USD/CDF (weekly statistical bulletin no. 39-2026)","sourceUrl":"https://resources.bcc.cd/publications/condense-informations-statistiques/condense_hebdomadaire_d_informations_statistiques_ndeg_39-2026_4eme_semaine_septembre.pdf","asOf":"2026-09-25","note":"2,270.47 francs per dollar on 25 September 2026; the BCC site shows 2,265.16 at the start of November 2026. World Bank 2025 average 2,693 (the franc appreciated in 2025-2026). CLDR gives no narrow symbol; ''FC'' is the local abbreviation."}},"instruments":{"savings_account":{"available":true,"localName":"Compte d''épargne","localNameEn":"Savings account"},"fdr_3m":{"available":true,"localName":"Dépôt à terme (3 mois)","localNameEn":"Term deposit (3 months)","note":"Offered in francs and US dollars; no published rate by maturity."},"fdr_1y":{"available":true,"localName":"Dépôt à terme (1 an)","localNameEn":"Term deposit (1 year)","note":"Offered in francs and US dollars; no published rate by maturity."},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No standard monthly recurring deposit product was found."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate or retail savings bond for individuals was found."},"tbill_91d":{"available":false,"localName":"Bon du Trésor (3 mois)","localNameEn":"Treasury bill (3 months)","note":"Treasury bills are auctioned to banks only, and 3-month issues have been rare since 2024.","sourceUrl":"https://resources.bcc.cd/publications/condense-informations-statistiques/condense_hebdomadaire_d_informations_statistiques_ndeg_39-2026_4eme_semaine_septembre.pdf"},"tbond_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No 5-year government bond for retail investors was found."},"tbond_10y":{"available":false,"localName":null,"localNameEn":null,"note":"No 10-year government bond for retail investors was found."},"equity_fund":{"available":false,"localName":null,"localNameEn":null,"note":"DR Congo has no stock exchange and no locally sold equity fund was found."},"gold":{"available":true,"localName":"Or","localNameEn":"Gold","note":"Gold is sold mostly as jewellery; artisanal gold trading is regulated."}},"institutions":{"centralBank":{"name":"Central Bank of the Congo (Banque Centrale du Congo, BCC)","url":"https://www.bcc.cd/"},"insuranceRegulator":{"name":"Insurance Regulatory and Control Authority (Autorité de Régulation et de Contrôle des Assurances, ARCA)","url":"https://arca.cd/"},"insuranceComplaints":{"name":"ARCA contact page (insurance supervisor)","url":"https://arca.cd/nous-contacter/","note":"No dedicated complaints desk or ombudsman was found; contact the regulator."},"pensionScheme":{"name":"National Social Security Fund (Caisse Nationale de Sécurité Sociale, CNSS), pension branch","url":"https://cnss.cd/?page_id=1421"},"oldAgeAllowance":null,"publicHealthCover":null,"depositInsurance":null,"statistics":{"name":"Central Bank of the Congo, inflation statistics (INS data)","url":"https://www.bcc.cd/statistiques/secteur-reel/inflation","note":"The National Institute of Statistics (INS) site could not be reached; the BCC republishes its price data."}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CD', 1, 'bank_deposit_avg_rate', 0.0824, NULL, 'sourced', 'Banque Centrale du Congo, average deposit rate of banks in national currency (créditeur dépôts MN)', 'https://www.bcc.cd/statistiques/secteur-monetaire/taux-interet', '2026-09-30', 'Weighted average rate paid on franc deposits, September 2026 (8.59% in August). Dollar deposits average about 4% (BCC weekly bulletin, September 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CD', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap or typical credit card rate was found; the BCC reports an average franc lending rate of 23.3% (September 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CD', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'A deposit guarantee fund (FOGADEC) was created by law, but its cover limit per depositor could not be read from an official source; its site could not be reached.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CD', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No standard monthly recurring deposit product or published rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CD', 1, 'equity_return_base', 0.095, NULL, 'assumption', 'Global equity in US dollars (about 6%) plus assumed franc depreciation; BCC average deposit rate 8.24%', 'https://www.bcc.cd/statistiques/secteur-monetaire/taux-interet', '2026-10-31', 'Base case is a global index fund in franc terms, kept within about 3 points of the assumed after-tax safe rate of 6.5% because there is no local index and access is through foreign funds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CD', 1, 'equity_return_high', 0.13, NULL, 'assumption', 'Global equity in US dollars plus franc depreciation', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=CD', '2026-10-31', 'High case: strong world equity returns plus faster franc depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CD', 1, 'equity_return_low', 0.04, NULL, 'assumption', 'No stock exchange in DR Congo; global equities in franc terms', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=CD', '2026-10-31', 'No local stock market exists, so equity means a global index fund in franc terms; low case is a weak decade for world shares with little currency gain.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CD', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published 1-year term deposit rate by maturity; the BCC publishes only an average deposit rate in francs (8.24% in September 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CD', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published 3-month term deposit rate by maturity; the BCC publishes only an average deposit rate in francs (8.24% in September 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CD', 1, 'fixed_income_return_base', 0.065, NULL, 'assumption', 'BCC average deposit rate in francs 8.24% (September 2026); 20% withholding on interest (PwC)', 'https://www.bcc.cd/statistiques/secteur-monetaire/taux-interet', '2026-10-31', 'Base case: franc term deposits at the published average rate (8.24%) less the 20% withholding tax on interest, about 6.6%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CD', 1, 'fixed_income_return_high', 0.085, NULL, 'assumption', 'BCC average deposit rate in francs and BCC bill yields (12.5% at 84 days)', 'https://www.bcc.cd/statistiques/secteur-monetaire/taux-interet', '2026-10-31', 'High case: longer franc deposits near the policy rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CD', 1, 'fixed_income_return_low', 0.04, NULL, 'assumption', 'BCC average deposit rate in francs 8.24% (September 2026); dollar deposits about 4%', 'https://www.bcc.cd/statistiques/secteur-monetaire/taux-interet', '2026-10-31', 'Low case: ordinary savings or dollar deposits paying about 4%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CD', 1, 'goal_inflation_education', 0.1, NULL, 'assumption', 'Inflation assumption 9%; BCC/INS national CPI', 'https://www.bcc.cd/statistiques/secteur-reel/inflation', '2026-10-31', 'No education CPI series was confirmed; school costs are planned 1 point above general inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CD', 1, 'goal_inflation_health', 0.11, NULL, 'assumption', 'Inflation assumption 9%; BCC/INS national CPI', 'https://www.bcc.cd/statistiques/secteur-reel/inflation', '2026-10-31', 'No medical CPI series was confirmed; medical costs are planned 2 points above general inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CD', 1, 'gold_return_base', 0.08, NULL, 'assumption', 'Long-run dollar gold trend about 4% plus assumed franc depreciation of about 4%', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=CD', '2026-10-31', 'Base case: dollar gold trend plus a franc that loses value against the dollar over time at roughly the inflation gap.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CD', 1, 'gold_return_high', 0.13, NULL, 'assumption', 'Dollar gold plus franc depreciation', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=CD', '2026-10-31', 'High case: strong dollar gold years and a weaker franc.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CD', 1, 'gold_return_low', 0.02, NULL, 'assumption', 'Franc per dollar: BCC indicative rate 2,270 (September 2026) vs about 2,850 in late 2024', 'https://resources.bcc.cd/publications/condense-informations-statistiques/condense_hebdomadaire_d_informations_statistiques_ndeg_39-2026_4eme_semaine_septembre.pdf', '2026-10-31', 'Low case: flat dollar gold and a stable or appreciating franc, as in 2025-2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CD', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Labour Code provisions on end-of-service or retirement indemnity could not be read from an official source; any end-of-career payment is set by collective agreements.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CD', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a major private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CD', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premiums by age were found; health cover is sold mostly to employers.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CD', 1, 'inflation_cpi', 0.0892, NULL, 'sourced', 'Banque Centrale du Congo, national consumer price inflation (INS data), year on year', 'https://www.bcc.cd/statistiques/secteur-reel/inflation', '2026-10-31', 'National CPI up 8.92% year on year in the 5th week of October 2026 (8.87% the week before); the rise partly reflects falling prices in late 2025 when the franc appreciated.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CD', 1, 'inflation_projection', 0.09, NULL, 'assumption', 'BCC condensé statistique: INS end-of-period inflation 2021-2025 (5.3%, 13.1%, 23.8%, 11.7%, 2.3%); latest 8.9%', 'https://resources.bcc.cd/publications/condense-informations-statistiques/condense_hebdomadaire_d_informations_statistiques_ndeg_39-2026_4eme_semaine_septembre.pdf', '2026-10-31', 'The 5-year average is about 11% but has been falling since 2023 and the latest reading is 8.9%, so 9% is a rounded long-run planning rate; no published numeric target was confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CD', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Death-cover contracts exist (ARCA 2024 market report), mostly as group and loan cover, but no published individual term-life premium rates per CDF 1,000 were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CD', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The regulator''s 2024 market report (ARCA, État du marché 2024) gives premiums and claims by branch but no industry claim settlement ratio for life insurance.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CD', 1, 'life_expectancy', 62.074, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN), DR Congo', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=CD', '2024-12-31', '62.1 years in 2024 (men 60.0, women 64.2); older than 2025 but the latest World Bank year. UN WPP 2024 gives 62.4 for 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CD', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":17.1,"men":16.3,"women":17.8},{"age":65,"total":13.6,"men":13,"women":14.2},{"age":70,"total":10.6,"men":10.1,"women":11},{"age":80,"total":5.9,"men":5.6,"women":6.1}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/democratic-republic-of-the-congo/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026; the both-sexes figure at 65 is published, the others are the mean of men and women.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CD', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension rules were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CD', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age (social) pension was found; the CNSS pays only contributory pensions.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CD', 1, 'oop_health_share', 0.38, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), DR Congo', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=CD', '2023-12-31', '38.0% in 2023 (WHO Global Health Expenditure Database via the World Bank); older than 2025 but the latest available.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CD', 1, 'policy_rate', 0.125, NULL, 'sourced', 'Banque Centrale du Congo, taux directeur', 'https://www.bcc.cd/statistiques/secteur-monetaire/taux-interet', '2026-09-30', 'Policy rate 12.5% since July 2026 (25% in December 2024, 17.5% by December 2025, then 15%, 13.5% and 12.5% in 2026); marginal lending facility 16.5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CD', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":60,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'Caisse Nationale de Sécurité Sociale (CNSS), pension branch', 'https://cnss.cd/?page_id=1421', '2026-10-31', 'Compulsory for salaried workers (5% employee and 5% employer contribution, PwC Tax Summaries 2026); pension from 60 with 180 months of insurance, else a single lump sum. The CNSS page says nothing about indexation, so inflationLinked is set to false (no automatic indexation confirmed).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CD', 1, 'retirement_accumulation_return_base', 0.08, NULL, 'assumption', 'Safe rate 6.5%, global equity base 9.5%, gold base 8% (franc terms)', 'https://www.bcc.cd/statistiques/secteur-monetaire/taux-interet', '2026-10-31', 'Base case: a balanced mix of franc deposits, gold and global equity funds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CD', 1, 'retirement_accumulation_return_high', 0.11, NULL, 'assumption', 'Global equity high 13%; gold high 13%', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=CD', '2026-10-31', 'High case: a growth-leaning mix in a weaker-franc decade.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CD', 1, 'retirement_accumulation_return_low', 0.05, NULL, 'assumption', 'Safe rate assumption 6.5%; global equity low 4%', 'https://www.bcc.cd/statistiques/secteur-monetaire/taux-interet', '2026-10-31', 'Low case: mostly deposits with weak equity and gold years.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CD', 1, 'retirement_age_default', 60, NULL, 'sourced', 'Caisse Nationale de Sécurité Sociale (CNSS), pension branch', 'https://cnss.cd/?page_id=1421', '2026-10-31', 'Old-age pension from 60 for men and women with at least 180 months of insurance (same for people born after 1975); early pension from 55 reduced 5% per year; at 65 the insured person is retired automatically.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CD', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'The civil-service retirement age (statute of public servants) could not be confirmed from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CD', 1, 'retirement_return_base', 0.06, NULL, 'assumption', 'BCC average deposit rate in francs 8.24% (September 2026)', 'https://www.bcc.cd/statistiques/secteur-monetaire/taux-interet', '2026-10-31', 'Base case kept below the after-tax franc deposit rate (8.24% less the 20% withholding on interest is about 6.6%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CD', 1, 'retirement_return_high', 0.075, NULL, 'assumption', 'BCC average deposit rate in francs and BCC bill yields', 'https://www.bcc.cd/statistiques/secteur-monetaire/taux-interet', '2026-10-31', 'High case: longer franc deposits at better rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CD', 1, 'retirement_return_low', 0.035, NULL, 'assumption', 'BCC average deposit rates: francs 8.24%, dollars about 4% (2026)', 'https://www.bcc.cd/statistiques/secteur-monetaire/taux-interet', '2026-10-31', 'Low case: mostly dollar or savings deposits after any tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CD', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate or retail savings bond for individuals was found; government securities are auctioned to banks.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CD', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The BCC publishes only an average deposit rate across banks, not a savings-account rate; the economy is largely dollarised (average dollar deposit rate about 4%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CD', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":16.5},{"year":2040,"value":16.9},{"year":2065,"value":13.2}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/democratic-republic-of-the-congo/2040/', '2025-12-31', '100 / old-age dependency ratio: 6.05 (2025, World Bank), 5.9 (2040) and 7.6 (2065, populationpyramid.net/democratic-republic-of-the-congo/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CD', 1, 'tax_bank_interest', 0.2, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Democratic Republic of the Congo, withholding taxes', 'https://taxsummaries.pwc.com/democratic-republic-of-the-congo/corporate/withholding-taxes', '2026-04-21', 'Standard 20% withholding (movable property tax) on interest paid to residents, on the gross amount; the page gives no separate rate for bank deposit interest of individuals (reviewed 21 April 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CD', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate exists for individuals, and no tax rule for one was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CD', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Treasury auctions 3- and 6-month bills (Bons du Trésor) only occasionally and to banks; the BCC weekly bulletin of September 2026 shows no recent 3-month auction rate. The BCC''s own 84-day bills yielded 12.5% in September 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CD', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 10-year government bond yield was found; the domestic bond market is very thin.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CD', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 5-year government bond yield was found; the domestic bond market is very thin.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('CF', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"CF","iso3":"CAF","nameEn":"Central African Republic","nameNative":"Ködörösêse tî Bêafrîka","region":"sub_saharan_africa","languages":["sg","fr"],"currency":{"code":"XAF","symbol":"FCFA","decimals":0,"compact":"intl","usdRate":{"value":581.928,"status":"sourced","sourceName":"World Bank WDI, official exchange rate (PA.NUS.FCRF), Central African Republic","sourceUrl":"https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=CF","asOf":"2025-12-31","note":"2025 average. The franc CFA is fixed at 655.957 per euro, so the dollar rate moves with the euro; the BEAC indicative rate on 30 October 2026 was about 586-591 per dollar (buy/sell)."}},"instruments":{"savings_account":{"available":true,"localName":"Compte d''épargne","localNameEn":"Savings account","note":"Banks must pay at least the BEAC minimum savings rate (2.45%).","sourceUrl":"https://www.beac.int/wp-content/uploads/2018/11/Rapport-sur-La-Politique-Mon%C3%A9taire-de-la-BEAC_Sept-2026_vf_new2_Publiable.pdf"},"fdr_3m":{"available":true,"localName":"Dépôt à terme (3 mois)","localNameEn":"Term deposit (3 months)","note":"Banks take term deposits (the BEAC sets reserve requirements on them), but rates are not published."},"fdr_1y":{"available":true,"localName":"Dépôt à terme (1 an)","localNameEn":"Term deposit (1 year)","note":"Banks take term deposits, but rates are not published."},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No standard monthly recurring deposit product was found."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate for individuals was found; individuals hold only small amounts of Treasury bonds (XAF 6.1 billion in January 2026, BEAC)."},"tbill_91d":{"available":false,"localName":"Bons du Trésor assimilables (BTA)","localNameEn":"Treasury bills","note":"Treasury bills are auctioned to banks and primary dealers; individuals held none in January 2026, and the 2026 programme plans no new bills for the country (BEAC).","sourceUrl":"https://www.beac.int/wp-content/uploads/2021/10/Statistiques-Mensuelles-du-March%C3%A9-des-valeurs-du-Tr%C3%A9sors-de-la-CEMAC-janvier-2026.pdf"},"tbond_5y":{"available":true,"localName":"Obligations du Trésor assimilables (OTA)","localNameEn":"Treasury bonds","note":"Treasury bonds are auctioned or offered to the public; individuals held about XAF 6.1 billion of them in January 2026 (BEAC).","sourceUrl":"https://www.beac.int/wp-content/uploads/2021/10/Statistiques-Mensuelles-du-March%C3%A9-des-valeurs-du-Tr%C3%A9sors-de-la-CEMAC-janvier-2026.pdf"},"tbond_10y":{"available":false,"localName":null,"localNameEn":null,"note":"No 10-year Treasury bond has been issued; maturities run up to about 7 years."},"equity_fund":{"available":false,"localName":null,"localNameEn":null,"note":"No locally sold diversified equity fund was found; the regional exchange (BVMAC) lists very few companies."},"gold":{"available":true,"localName":"Or","localNameEn":"Gold","note":"Gold is sold mainly as jewellery and from artisanal mining; no official bullion or coin scheme was found."}},"institutions":{"centralBank":{"name":"Bank of Central African States (Banque des États de l''Afrique Centrale, BEAC)","url":"https://www.beac.int/"},"insuranceRegulator":{"name":"Inter-African Conference on Insurance Markets (CIMA), regional insurance regulator, with the national insurance directorate","url":"https://cima-afrique.org/"},"insuranceComplaints":{"name":"CIMA policyholder requests and complaints form","url":"https://cima-afrique.org/faites-votre-requetes-ici-2/"},"pensionScheme":{"name":"National Social Security Fund (Caisse Nationale de Sécurité Sociale, CNSS)","url":"https://cnssrca.org/"},"oldAgeAllowance":null,"publicHealthCover":{"name":"Ministry of Health and Population (public health services)","url":"https://www.sante.gouv.cf/"},"depositInsurance":{"name":"Deposit Guarantee Fund of Central Africa (Fonds de Garantie des Dépôts en Afrique Centrale, FOGADAC)","url":"https://www.fogadac.com/"},"statistics":{"name":"Central African Institute of Statistics and Economic and Social Studies (ICASEES)","url":"https://icasees.org/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CF', 1, 'bank_deposit_avg_rate', 0.0245, NULL, 'sourced', 'World Bank WDI, deposit interest rate (FR.INR.DPST), Central African Republic', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=CF', '2016-12-31', '2.45% in 2016, the latest World Bank value (older than 2025); it equals the BEAC minimum savings rate (Taux Créditeur Minimum), which is unchanged at 2.45% in the BEAC September 2026 report.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CF', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap or typical credit card rate was found; the BEAC reports an average effective lending rate (TEG) of 14.36% in the Central African Republic in Q2 2026, but not for cards.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CF', 1, 'deposit_insurance_limit', 8000000, NULL, 'sourced', 'Deposit Guarantee Fund of Central Africa (FOGADAC), FAQ', 'https://www.fogadac.com/faq', '2026-10-31', 'FOGADAC covers deposits up to XAF 8 million for individuals (XAF 15 million for legal persons) per the FAQ read on 31 October 2026; older FOGADAC pages still show the earlier XAF 5 million per depositor per bank. Covers all CEMAC banks.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CF', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No standard monthly recurring deposit product or rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CF', 1, 'equity_return_base', 0.065, NULL, 'assumption', 'BEAC: franc CFA fixed to the euro; CEMAC regional exchange (BVMAC) with very small market capitalisation', 'https://www.beac.int/wp-content/uploads/2021/10/Statistiques-Mensuelles-du-March%C3%A9-des-valeurs-du-Tr%C3%A9sors-de-la-CEMAC-janvier-2026.pdf', '2026-10-31', 'No usable local index record (BVMAC equity capitalisation was only about XAF 295 billion in January 2026), so equity means a global index in euro terms, held about 4 points above an after-tax safe saving rate of about 2.5-3%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CF', 1, 'equity_return_high', 0.1, NULL, 'assumption', 'BEAC: franc CFA fixed to the euro; CEMAC regional exchange (BVMAC) with very small market capitalisation', 'https://www.beac.int/wp-content/uploads/2021/10/Statistiques-Mensuelles-du-March%C3%A9-des-valeurs-du-Tr%C3%A9sors-de-la-CEMAC-janvier-2026.pdf', '2026-10-31', 'High case: global equities repeat their long-run euro-terms record.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CF', 1, 'equity_return_low', 0.02, NULL, 'assumption', 'BEAC: franc CFA fixed to the euro; CEMAC regional exchange (BVMAC) with very small market capitalisation', 'https://www.beac.int/wp-content/uploads/2021/10/Statistiques-Mensuelles-du-March%C3%A9-des-valeurs-du-Tr%C3%A9sors-de-la-CEMAC-janvier-2026.pdf', '2026-10-31', 'Low case: a weak decade for global equities held in euro (franc CFA) terms; the regional exchange is too small and illiquid to serve as a guide.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CF', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published 1-year term deposit rate was found; the BEAC publishes lending rates (TEG) by country but no term deposit rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CF', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published 3-month term deposit rate was found; the BEAC publishes lending rates (TEG) by country but no deposit rates beyond the 2.45% savings floor.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CF', 1, 'fixed_income_return_base', 0.03, NULL, 'assumption', 'BEAC Taux Créditeur Minimum 2.45%; BEAC Treasury market statistics (individuals hold Treasury bonds)', 'https://www.beac.int/wp-content/uploads/2018/11/Rapport-sur-La-Politique-Mon%C3%A9taire-de-la-BEAC_Sept-2026_vf_new2_Publiable.pdf', '2026-10-31', 'Base case: savings and term deposits a little above the 2.45% floor; government bond yields are much higher but mostly bought by banks and institutions.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CF', 1, 'fixed_income_return_high', 0.06, NULL, 'assumption', 'BEAC Taux Créditeur Minimum 2.45%; BEAC Treasury market statistics (individuals hold Treasury bonds)', 'https://www.beac.int/wp-content/uploads/2021/10/Statistiques-Mensuelles-du-March%C3%A9-des-valeurs-du-Tr%C3%A9sors-de-la-CEMAC-janvier-2026.pdf', '2026-10-31', 'High case: part of savings in government bonds offered to the public, whose issue cost averaged 10.44% in January 2026, after some default and liquidity risk.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CF', 1, 'fixed_income_return_low', 0.02, NULL, 'assumption', 'BEAC Taux Créditeur Minimum 2.45%; BEAC Treasury market statistics (individuals hold Treasury bonds)', 'https://www.beac.int/wp-content/uploads/2018/11/Rapport-sur-La-Politique-Mon%C3%A9taire-de-la-BEAC_Sept-2026_vf_new2_Publiable.pdf', '2026-10-31', 'Low case: ordinary savings accounts at the 2.45% minimum rate, less any tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CF', 1, 'goal_inflation_education', 0.04, NULL, 'assumption', 'BEAC note on CEMAC inflation Q2 2026: education prices +0.8% year on year in June 2026', 'https://www.beac.int/wp-content/uploads/2016/10/Note-sur-l%C3%A9volution-r%C3%A9cente-de-linflation-dans-la-CEMAC-2026Q2.pdf', '2026-10-31', 'Education prices in the CEMAC index rose 0.8% in June 2026, but private school fees rise faster, so education goals use 1 point above the 3% planning inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CF', 1, 'goal_inflation_health', 0.045, NULL, 'assumption', 'BEAC note on CEMAC inflation Q2 2026: health prices +1.5% year on year in June 2026', 'https://www.beac.int/wp-content/uploads/2016/10/Note-sur-l%C3%A9volution-r%C3%A9cente-de-linflation-dans-la-CEMAC-2026Q2.pdf', '2026-10-31', 'Health prices in the CEMAC index rose 1.5% in June 2026, but private and imported care costs run faster, so health goals use 1.5 points above the 3% planning inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CF', 1, 'gold_return_base', 0.045, NULL, 'assumption', 'Franc CFA fixed at 655.957 per euro (BEAC); dollar gold trend', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=CF', '2026-10-31', 'Base case: the long-run gold trend of about 4-5% a year in euro terms, which the franc CFA follows.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CF', 1, 'gold_return_high', 0.08, NULL, 'assumption', 'Franc CFA fixed at 655.957 per euro (BEAC); dollar gold trend', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=CF', '2026-10-31', 'High case: strong gold years.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CF', 1, 'gold_return_low', 0, NULL, 'assumption', 'Franc CFA fixed at 655.957 per euro (BEAC); dollar gold trend', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=CF', '2026-10-31', 'Low case: flat gold prices with no currency loss under the euro peg.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CF', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Labour Code (Loi 09.004 of 2009) provisions on dismissal or end-of-service indemnity could not be read from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CF', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical out-of-pocket cost of a major hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CF', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premiums by age were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CF', 1, 'inflation_cpi', 0.031, NULL, 'sourced', 'Bank of Central African States (BEAC), note on CEMAC inflation, Q2 2026 (national CPI, the Central African Republic)', 'https://www.beac.int/wp-content/uploads/2016/10/Note-sur-l%C3%A9volution-r%C3%A9cente-de-linflation-dans-la-CEMAC-2026Q2.pdf', '2026-06-30', 'Consumer prices up 3.1% year on year in June 2026 in the Central African Republic (BEAC table of national CPIs); the annual average was 1.0% in June 2026. ICASEES monthly bulletins were not readable as text.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CF', 1, 'inflation_projection', 0.03, NULL, 'assumption', 'BEAC: CEMAC inflation convergence norm of 3%; franc CFA fixed to the euro', 'https://www.beac.int/wp-content/uploads/2016/10/COMMUNIQUE-DE-PRESSE-CPM-DU-28-SEPTEMBRE-2026.pdf', '2026-10-31', 'The franc CFA is fixed to the euro and the BEAC holds CEMAC inflation under a 3% norm; annual average inflation in the Central African Republic was 1.5% in 2024 and 1.0% in 2025 (BEAC), but year-on-year rates swing up to 5%, so the 3% norm is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CF', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published term life premium rates per XAF 1,000 of cover were found; the life insurance market is very small.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CF', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No life insurance claim settlement ratio was found from CIMA (the regional insurance regulator) or the national insurance directorate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CF', 1, 'life_expectancy', 57.671, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN), Central African Republic', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=CF', '2024-12-31', '57.7 years in 2024 (men 55.5, women 59.6); latest World Bank value, older than 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CF', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":15.7,"men":14.7,"women":16.7},{"age":65,"total":12.9,"men":12,"women":13.7},{"age":70,"total":10.4,"men":9.6,"women":11.2},{"age":80,"total":6.2,"men":5.6,"women":6.8}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/central-african-republic/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026; totals are the mean of men and women where the page gives no both-sexes figure (it gives 65 only).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CF', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension was found; the CNSS old-age allowance (allocation de vieillesse) and guaranteed minimum (ARMIG) are contributory benefits for insured workers.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CF', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension was found; the CNSS old-age allowance (allocation de vieillesse) and guaranteed minimum (ARMIG) are contributory benefits for insured workers.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CF', 1, 'oop_health_share', 0.4502, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), Central African Republic', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=CF', '2023-12-31', '45.0% in 2023 (WHO Global Health Expenditure Database via the World Bank), the latest available; older than 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CF', 1, 'policy_rate', 0.045, NULL, 'sourced', 'BEAC Monetary Policy Committee, press release of 28 September 2026 (Taux d''intérêt des appels d''offres)', 'https://www.beac.int/wp-content/uploads/2016/10/COMMUNIQUE-DE-PRESSE-CPM-DU-28-SEPTEMBRE-2026.pdf', '2026-09-28', 'BEAC tender rate (TIAO) held at 4.50% on 28 September 2026 (marginal lending facility 5.75%, deposit facility 0%); the rate is common to all six CEMAC countries.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CF', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":60,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'Social Security Code of the Central African Republic (Journal Officiel, August 2010), published by the CNSS', 'https://cnssrca.org/wp-content/uploads/2023/11/Code-de-Securite-Sociale.pdf', '2010-08-31', 'Compulsory scheme for salaried workers run by the CNSS: pension at 60 after 15 years of insurance, 40% of average pay of the last 5 or 10 years plus 1% per year beyond 280 months, minimum 60% of the minimum wage (Art. 100, 117). Pensions may be revalued by the CNSS board after large cost-of-living changes (Art. 124), so not automatically indexed. The code dates from 2010 (older than 2025) and is still the text the CNSS publishes.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CF', 1, 'retirement_accumulation_return_base', 0.045, NULL, 'assumption', 'Safe rate about 3%; global equity base 6.5% in euro terms; gold base 4.5%', 'https://www.beac.int/wp-content/uploads/2021/10/Statistiques-Mensuelles-du-March%C3%A9-des-valeurs-du-Tr%C3%A9sors-de-la-CEMAC-janvier-2026.pdf', '2026-10-31', 'Base case: a balanced mix of deposits, public bond offers, gold and foreign equity funds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CF', 1, 'retirement_accumulation_return_high', 0.065, NULL, 'assumption', 'Safe rate about 3%; global equity base 6.5% in euro terms; gold base 4.5%', 'https://www.beac.int/wp-content/uploads/2021/10/Statistiques-Mensuelles-du-March%C3%A9-des-valeurs-du-Tr%C3%A9sors-de-la-CEMAC-janvier-2026.pdf', '2026-10-31', 'High case: a growth-leaning mix with more equity.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CF', 1, 'retirement_accumulation_return_low', 0.025, NULL, 'assumption', 'Safe rate about 3%; global equity base 6.5% in euro terms; gold base 4.5%', 'https://www.beac.int/wp-content/uploads/2018/11/Rapport-sur-La-Politique-Mon%C3%A9taire-de-la-BEAC_Sept-2026_vf_new2_Publiable.pdf', '2026-10-31', 'Low case: mostly bank savings.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CF', 1, 'retirement_age_default', 60, NULL, 'sourced', 'National Social Security Fund (CNSS), old-age, invalidity and death insurance', 'https://cnssrca.org/assurance-vieillesse-invalidite-deces/', '2026-10-31', 'Normal old-age pension at 60 with at least 15 years of insurance (Social Security Code, Art. 100); early pension from 55 with a 5% reduction per year. Same age for men and women.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CF', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'The retirement age of civil servants could not be confirmed from an official source (the public service statute was not reachable).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CF', 1, 'retirement_return_base', 0.03, NULL, 'assumption', 'BEAC Taux Créditeur Minimum 2.45%; BEAC Treasury bill issue cost 6.96% (January 2026)', 'https://www.beac.int/wp-content/uploads/2018/11/Rapport-sur-La-Politique-Mon%C3%A9taire-de-la-BEAC_Sept-2026_vf_new2_Publiable.pdf', '2026-10-31', 'Base case: deposits and some public bond offers; kept below the Treasury bill rate and close to the deposit floor, since term deposit rates are not published.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CF', 1, 'retirement_return_high', 0.045, NULL, 'assumption', 'BEAC Taux Créditeur Minimum 2.45%; BEAC Treasury bill issue cost 6.96% (January 2026)', 'https://www.beac.int/wp-content/uploads/2021/10/Statistiques-Mensuelles-du-March%C3%A9-des-valeurs-du-Tr%C3%A9sors-de-la-CEMAC-janvier-2026.pdf', '2026-10-31', 'High case: a larger share in government bonds offered to the public.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CF', 1, 'retirement_return_low', 0.02, NULL, 'assumption', 'BEAC Taux Créditeur Minimum 2.45%; BEAC Treasury bill issue cost 6.96% (January 2026)', 'https://www.beac.int/wp-content/uploads/2018/11/Rapport-sur-La-Politique-Mon%C3%A9taire-de-la-BEAC_Sept-2026_vf_new2_Publiable.pdf', '2026-10-31', 'Low case: savings accounts at the 2.45% minimum rate, less any tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CF', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate or retail savings bond for individuals was found; the Treasury borrows through BEAC-run auctions and occasional public bond offers.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CF', 1, 'savings_account_rate', 0.0245, NULL, 'sourced', 'BEAC Monetary Policy Report, September 2026, Annex 1 (Taux Créditeur Minimum)', 'https://www.beac.int/wp-content/uploads/2018/11/Rapport-sur-La-Politique-Mon%C3%A9taire-de-la-BEAC_Sept-2026_vf_new2_Publiable.pdf', '2026-09-30', 'Minimum rate banks must pay on savings accounts of individuals (Taux Créditeur Minimum), 2.45% unchanged since 8 July 2014; banks usually pay this floor.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CF', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":22.3},{"year":2040,"value":24.4},{"year":2065,"value":18.5}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://data.worldbank.org/indicator/SP.POP.DPND.OL?locations=CF', '2025-12-31', '100 / old-age dependency ratio: 4.47 (2025, World Bank), 4.1 (2040, populationpyramid.net/central-african-republic/2040/) and 5.4 (2065, populationpyramid.net/central-african-republic/2065/); the ratio rises to 2040 because of the very young population.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CF', 1, 'tax_bank_interest', NULL, NULL, 'missing', '', '', '2026-10-31', 'The tax rate on bank interest for individuals (impôt sur le revenu des capitaux mobiliers) could not be confirmed from an official source; PwC Worldwide Tax Summaries has no Central African Republic page.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CF', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate for individuals exists, and the tax treatment of Treasury security income for individuals could not be confirmed from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CF', 1, 'tbill_91d_rate', 0.0696, NULL, 'sourced', 'BEAC, Statistiques mensuelles du marché des valeurs du Trésor de la CEMAC, January 2026 (coût des ressources, BTA)', 'https://www.beac.int/wp-content/uploads/2021/10/Statistiques-Mensuelles-du-March%C3%A9-des-valeurs-du-Tr%C3%A9sors-de-la-CEMAC-janvier-2026.pdf', '2026-01-31', 'Weighted average cost of Treasury bills (BTA, 13 to 52 weeks) issued by the Central African Republic in January 2026; no separate 13-week yield is published, and the 2026 issuance plan has no new bills for the country.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CF', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Central African Republic has not issued 10-year Treasury bonds; its bonds run up to about 7 years (BEAC Treasury market statistics, January 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CF', 1, 'tbond_5y_rate', 0.1044, NULL, 'sourced', 'BEAC, Statistiques mensuelles du marché des valeurs du Trésor de la CEMAC, January 2026 (coût des ressources, OTA)', 'https://www.beac.int/wp-content/uploads/2021/10/Statistiques-Mensuelles-du-March%C3%A9-des-valeurs-du-Tr%C3%A9sors-de-la-CEMAC-janvier-2026.pdf', '2026-01-31', 'Weighted average cost of Treasury bonds (OTA, 2 to 7 years) issued by the Central African Republic in January 2026; no yield for an exact 5-year maturity is published.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('CG', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"CG","iso3":"COG","nameEn":"Congo","nameNative":"République du Congo","region":"sub_saharan_africa","languages":["fr","ln","ktu"],"currency":{"code":"XAF","symbol":"FCFA","decimals":0,"compact":"intl","usdRate":{"value":587.14,"status":"sourced","sourceName":"BCEAO reference rate of the US dollar against the CFA franc, 30 October 2026","sourceUrl":"https://www.bceao.int/fr/cours/get_all_reference_by_date?dateJour=2026-10-30","asOf":"2026-10-30","note":"587.14 francs per dollar on 30 October 2026 (BCEAO reference rates for that day). The central African franc (XAF) and west African franc (XOF) share the same fixed parity of 655.957 per euro, so the dollar rate is identical; the BEAC site showed buy 585.95 and sell 590.99 for the same date. World Bank 2025 average 581.9."}},"instruments":{"savings_account":{"available":true,"localName":"Compte d''épargne","localNameEn":"Savings account"},"fdr_3m":{"available":true,"localName":"Dépôt à terme (3 mois)","localNameEn":"Term deposit (3 months)"},"fdr_1y":{"available":true,"localName":"Dépôt à terme (1 an)","localNameEn":"Term deposit (1 year)"},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No standard monthly recurring deposit product was found."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No current government savings certificate or retail savings bond for individuals was confirmed."},"tbill_91d":{"available":true,"localName":"Bon du Trésor assimilable (BTA, 13 semaines)","localNameEn":"Treasury bill (13 weeks)","note":"Auctioned on the regional CEMAC market through primary-dealer banks; individuals can only buy through a bank.","sourceUrl":"https://www.beac.int/wp-content/uploads/2016/10/Courbe-des-taux-de-rendement-des-titres-publics-Congolais-juillet-26.pdf"},"tbond_5y":{"available":true,"localName":"Obligation du Trésor assimilable (OTA, 5 ans)","localNameEn":"Treasury bond (5 years)","note":"Auctioned on the regional CEMAC market through primary-dealer banks.","sourceUrl":"https://www.beac.int/wp-content/uploads/2016/10/Courbe-des-taux-de-rendement-des-titres-publics-Congolais-juillet-26.pdf"},"tbond_10y":{"available":false,"localName":null,"localNameEn":null,"note":"The 10-year point is an estimate on the BEAC yield curve; regular 10-year issues were not found."},"equity_fund":{"available":false,"localName":null,"localNameEn":null,"note":"No Congolese company is actively traded on the regional exchange and no locally sold equity fund was found."},"gold":{"available":true,"localName":"Or","localNameEn":"Gold","note":"Gold is sold mostly as jewellery."}},"institutions":{"centralBank":{"name":"Bank of Central African States (Banque des États de l''Afrique Centrale, BEAC)","url":"https://www.beac.int/"},"insuranceRegulator":{"name":"Inter-African Conference on Insurance Markets (CIMA), regional insurance supervisor","url":"https://cima-afrique.org/"},"insuranceComplaints":{"name":"CIMA, policyholder requests and complaints","url":"https://cima-afrique.org/faites-votre-requetes-ici-2/"},"pensionScheme":{"name":"National Social Security Fund (Caisse Nationale de Sécurité Sociale, CNSS)","url":"https://www.cnss.cg/"},"oldAgeAllowance":null,"publicHealthCover":null,"depositInsurance":null,"statistics":{"name":"National Institute of Statistics (Institut National de la Statistique, INS Congo)","url":"https://ins-congo.cg/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CG', 1, 'bank_deposit_avg_rate', 0.0245, NULL, 'sourced', 'World Bank WDI, deposit interest rate (FR.INR.DPST), Republic of Congo', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=CG', '2016-12-31', '2.45% in 2016, the latest year in the World Bank series; far older than 2025. It equals the CEMAC regulated minimum savings rate (TCM), still 2.45% in August 2026 (BEAC dashboard), so it understates term-deposit rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CG', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap or typical credit card rate for Congo was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CG', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'CEMAC has a regional deposit guarantee fund (FOGADAC), but its cover limit per depositor could not be read from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CG', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No standard monthly recurring deposit product or published rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CG', 1, 'equity_return_base', 0.06, NULL, 'assumption', 'Global equities in euro terms; assumed after-tax safe rate 3.5%', 'https://www.bceao.int/fr/cours/get_all_reference_by_date?dateJour=2026-10-30', '2026-10-31', 'Base case for a global index fund in euro terms, kept within 3 points of the assumed safe rate because there is no local index.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CG', 1, 'equity_return_high', 0.09, NULL, 'assumption', 'Global equities in euro terms', 'https://www.bceao.int/fr/cours/get_all_reference_by_date?dateJour=2026-10-30', '2026-10-31', 'High case: global equities match their long-run record.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CG', 1, 'equity_return_low', 0.02, NULL, 'assumption', 'No active local equity market (no Congolese listing found on the regional CEMAC exchange); franc fixed to the euro', 'https://www.bceao.int/fr/cours/get_all_reference_by_date?dateJour=2026-10-30', '2026-10-31', 'Equity means a global index fund in euro terms (equal to franc terms under the peg); low case is a weak decade.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CG', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published 1-year term deposit rate was found for Congo.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CG', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published 3-month term deposit rate was found for Congo.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CG', 1, 'fixed_income_return_base', 0.035, NULL, 'assumption', 'BEAC yield curve for Congo (3 months 6.42%) and bank deposit rates; 20% tax on interest', 'https://www.beac.int/wp-content/uploads/2016/10/Courbe-des-taux-de-rendement-des-titres-publics-Congolais-juillet-26.pdf', '2026-10-31', 'Base case: term deposits after the 20% tax; government bills pay more but carry sovereign risk and are reached only through banks.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CG', 1, 'fixed_income_return_high', 0.06, NULL, 'assumption', 'BEAC yield curve for Congo, 1 year 9.59%, less 20% tax', 'https://www.beac.int/wp-content/uploads/2016/10/Courbe-des-taux-de-rendement-des-titres-publics-Congolais-juillet-26.pdf', '2026-10-31', 'High case: short government bills held through a bank, after tax and allowing for default risk.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CG', 1, 'fixed_income_return_low', 0.02, NULL, 'assumption', 'BEAC regulated minimum savings rate 2.45% (August 2026); 20% tax on interest (PwC)', 'https://www.beac.int/wp-content/uploads/2018/11/Annexe_Rapport-Politique-Monetaire_Tableau-de-bord-du-CPM_Sept_2026.pdf', '2026-10-31', 'Low case: savings deposits at the regulated minimum rate less tax (about 2%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CG', 1, 'goal_inflation_education', 0.045, NULL, 'assumption', 'Inflation assumption 3%; World Bank CPI', 'https://data.worldbank.org/indicator/FP.CPI.TOTL.ZG?locations=CG', '2026-10-31', 'No education CPI was found; school costs are planned 1.5 points above general inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CG', 1, 'goal_inflation_health', 0.05, NULL, 'assumption', 'Inflation assumption 3%; World Bank CPI', 'https://data.worldbank.org/indicator/FP.CPI.TOTL.ZG?locations=CG', '2026-10-31', 'No medical CPI was found; medical costs are planned 2 points above general inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CG', 1, 'gold_return_base', 0.04, NULL, 'assumption', 'Long-run gold trend in euro terms; franc fixed to the euro', 'https://www.bceao.int/fr/cours/get_all_reference_by_date?dateJour=2026-10-30', '2026-10-31', 'Base case: the long-run gold trend of about 4% a year, with no currency gain under the peg.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CG', 1, 'gold_return_high', 0.08, NULL, 'assumption', 'Gold in euro terms', 'https://www.bceao.int/fr/cours/get_all_reference_by_date?dateJour=2026-10-30', '2026-10-31', 'High case: strong gold years.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CG', 1, 'gold_return_low', 0, NULL, 'assumption', 'Franc fixed at 655.957 per euro', 'https://www.bceao.int/fr/cours/get_all_reference_by_date?dateJour=2026-10-30', '2026-10-31', 'Low case: flat gold prices in euro terms.', 0);
