INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CG', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a major private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CG', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premiums by age were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CG', 1, 'inflation_cpi', 0.049, NULL, 'sourced', 'Trading Economics, citing the national statistics office of the Republic of Congo, CPI September 2026', 'https://tradingeconomics.com/republic-of-the-congo/inflation-cpi', '2026-09-30', 'Consumer prices up 4.9% year on year in September 2026 (4.4% in August); secondary source because the INS Congo site loads its indicators by script. World Bank 2025 average 2.4%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CG', 1, 'inflation_projection', 0.03, NULL, 'assumption', 'CEMAC convergence norm of 3% inflation; BEAC forecasts 2.2% average CEMAC inflation for 2026 (CPM, 28 September 2026)', 'https://www.beac.int/wp-content/uploads/2016/10/COMMUNIQUE-DE-PRESSE-CPM-DU-28-SEPTEMBRE-2026.pdf', '2026-10-31', 'The franc is pegged to the euro and BEAC targets the 3% CEMAC ceiling; Congo''s recent average is close to it, so 3% is used for planning.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CG', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published individual term-life premium rates per XAF 1,000 of cover were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CG', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No life insurance claim settlement ratio for Congo was found from the regional supervisor (CIMA) or the national insurance directorate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CG', 1, 'life_expectancy', 66.001, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN), Republic of Congo', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=CG', '2024-12-31', '66.0 years in 2024 (men 64.3, women 67.7); older than 2025 but the latest World Bank year. UN WPP 2024 gives 66.4 for 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CG', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":16.6,"men":15.7,"women":17.4},{"age":65,"total":13.3,"men":12.5,"women":14},{"age":70,"total":10.3,"men":9.8,"women":10.8},{"age":80,"total":5.9,"men":5.7,"women":6}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/congo/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026; the both-sexes figure at 65 is published, the others are the mean of men and women.', 0);
