INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CG', 1, 'oop_health_share', 0.2797, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), Republic of Congo', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=CG', '2023-12-31', '28.0% in 2023 (WHO Global Health Expenditure Database via the World Bank); older than 2025 but the latest available.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CG', 1, 'policy_rate', 0.045, NULL, 'sourced', 'Bank of Central African States (BEAC), Monetary Policy Committee, 28 September 2026: tender rate (TIAO) held', 'https://www.beac.int/wp-content/uploads/2016/10/COMMUNIQUE-DE-PRESSE-CPM-DU-28-SEPTEMBRE-2026.pdf', '2026-09-28', 'TIAO held at 4.50% on 28 September 2026 (cut from 4.75% on 29 June 2026); marginal lending facility 5.75%; deposit facility 0%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CG', 1, 'public_pension_scheme', NULL, NULL, 'missing', '', '', '2026-10-31', 'A contributory pension is run by the Caisse Nationale de Sécurité Sociale (CNSS; employee share 4% of gross salary, PwC Tax Summaries 2026), but its pension age and indexation rules could not be read (pensions page loads by script).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CG', 1, 'retirement_accumulation_return_base', 0.045, NULL, 'assumption', 'Safe rate 3.5%, global equity base 6%, gold base 4%', 'https://www.bceao.int/fr/cours/get_all_reference_by_date?dateJour=2026-10-30', '2026-10-31', 'Base case: a balanced mix of deposits, gold and global equity funds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CG', 1, 'retirement_accumulation_return_high', 0.07, NULL, 'assumption', 'Global equity high 9%; gold high 8%', 'https://www.bceao.int/fr/cours/get_all_reference_by_date?dateJour=2026-10-30', '2026-10-31', 'High case: a growth-leaning mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CG', 1, 'retirement_accumulation_return_low', 0.025, NULL, 'assumption', 'Safe rate assumption; global equity low 2%', 'https://www.bceao.int/fr/cours/get_all_reference_by_date?dateJour=2026-10-30', '2026-10-31', 'Low case: mostly deposits with weak equity and gold years.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CG', 1, 'retirement_age_default', NULL, NULL, 'missing', '', '', '2026-10-31', 'The pension age of the Caisse Nationale de Sécurité Sociale (CNSS) could not be read: its pensions page loads by script and no other official text was reached.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CG', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'The civil-service retirement age could not be confirmed from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CG', 1, 'retirement_return_base', 0.03, NULL, 'assumption', 'Bank deposit rates and BEAC yield curve for Congo, less 20% tax', 'https://www.beac.int/wp-content/uploads/2016/10/Courbe-des-taux-de-rendement-des-titres-publics-Congolais-juillet-26.pdf', '2026-10-31', 'Base case kept at or below the after-tax term-deposit rate, well below after-tax bill yields that carry sovereign risk.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CG', 1, 'retirement_return_high', 0.05, NULL, 'assumption', 'BEAC yield curve for Congo (6 months 7.73%) less 20% tax', 'https://www.beac.int/wp-content/uploads/2016/10/Courbe-des-taux-de-rendement-des-titres-publics-Congolais-juillet-26.pdf', '2026-10-31', 'High case: short government bills through a bank, after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CG', 1, 'retirement_return_low', 0.02, NULL, 'assumption', 'Deposit rates and 20% tax on interest (PwC)', 'https://taxsummaries.pwc.com/republic-of-congo/individual/income-determination', '2026-10-31', 'Low case: savings deposits after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CG', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No current government savings certificate or retail savings bond for individuals was confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CG', 1, 'savings_account_rate', 0.0245, NULL, 'sourced', 'BEAC, monetary policy dashboard (Tableau de bord du CPM), September 2026: minimum creditor rate (TCM)', 'https://www.beac.int/wp-content/uploads/2018/11/Annexe_Rapport-Politique-Monetaire_Tableau-de-bord-du-CPM_Sept_2026.pdf', '2026-08-31', 'Regulated minimum rate on savings deposits in the CEMAC (taux créditeur minimum), 2.45% unchanged through August 2026; banks typically pay this rate on ordinary savings accounts.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CG', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":18.6},{"year":2040,"value":13.3},{"year":2065,"value":10.1}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/congo/2040/', '2025-12-31', '100 / old-age dependency ratio: 5.37 (2025, World Bank), 7.5 (2040) and 9.9 (2065, populationpyramid.net/congo/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CG', 1, 'tax_bank_interest', 0.2, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Republic of Congo, individual income determination', 'https://taxsummaries.pwc.com/republic-of-congo/individual/income-determination', '2026-08-07', 'Interest from most sources is taxable; a Congolese resident payer withholds 20% at payment. The page does not say whether this is final or whether bank deposit interest has a different rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CG', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate for individuals was confirmed, so no tax rule for it was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CG', 1, 'tbill_91d_rate', 0.0642, NULL, 'sourced', 'BEAC, yield curve of Congolese government securities, July 2026 (3 months)', 'https://www.beac.int/wp-content/uploads/2016/10/Courbe-des-taux-de-rendement-des-titres-publics-Congolais-juillet-26.pdf', '2026-07-31', 'BEAC estimated yield curve: 3 months 6.42%, 6 months 7.73%, 1 year 9.59%; bills (BTA) are auctioned through primary-dealer banks on the CEMAC market.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CG', 1, 'tbond_10y_rate', 0.1343, NULL, 'sourced', 'BEAC, yield curve of Congolese government securities, July 2026 (10 years)', 'https://www.beac.int/wp-content/uploads/2016/10/Courbe-des-taux-de-rendement-des-titres-publics-Congolais-juillet-26.pdf', '2026-07-31', 'Estimated 10-year yield 13.43% on the BEAC curve for Congo; few long bonds are actually issued.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CG', 1, 'tbond_5y_rate', 0.1304, NULL, 'sourced', 'BEAC, yield curve of Congolese government securities, July 2026 (5 years)', 'https://www.beac.int/wp-content/uploads/2016/10/Courbe-des-taux-de-rendement-des-titres-publics-Congolais-juillet-26.pdf', '2026-07-31', 'Estimated 5-year yield 13.04% on the BEAC curve for Congo, reflecting high sovereign risk.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('CH', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"CH","iso3":"CHE","nameEn":"Switzerland","nameNative":"Schweiz","region":"europe_central_asia","languages":["de","fr","it","en","rm"],"currency":{"code":"CHF","symbol":"CHF","decimals":2,"compact":"intl","usdRate":{"value":0.8285,"status":"sourced","sourceName":"Swiss National Bank, foreign exchange rates, monthly average (cube devkum)","sourceUrl":"https://data.snb.ch/en/topics/ziredev/cube/devkum","asOf":"2026-10-31","note":"CHF 0.82854 per USD, October 2026 monthly average (September 0.81926); World Bank 2025 average 0.83."}},"instruments":{"savings_account":{"available":true,"localName":"Sparkonto","localNameEn":"Savings account","sourceUrl":"https://data.snb.ch/en/topics/ziredev/cube/zikrepro"},"fdr_3m":{"available":true,"localName":"Festgeld","localNameEn":"Fixed-term deposit (3 months)","sourceUrl":"https://data.snb.ch/en/topics/ziredev/cube/zikrepro"},"fdr_1y":{"available":true,"localName":"Festgeld","localNameEn":"Fixed-term deposit (1 year)","sourceUrl":"https://data.snb.ch/en/topics/ziredev/cube/zikrepro"},"dps":{"available":false,"localName":null,"localNameEn":"Monthly recurring deposit","note":"No standard recurring-deposit product; regular saving goes into savings or tied pillar 3a accounts."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":"Government savings certificate","note":"No retail government savings certificate; bank cash bonds (Kassenobligationen) are bank products."},"tbill_91d":{"available":true,"localName":"Geldmarktbuchforderungen der Eidgenossenschaft","localNameEn":"Confederation money-market debt register claims","note":"Auctioned in large lots, mainly to institutions.","sourceUrl":"https://data.snb.ch/en/topics/ziredev/cube/zimoma"},"tbond_5y":{"available":true,"localName":"Eidgenössische Anleihen","localNameEn":"Confederation bonds","note":"Listed on the Swiss exchange and buyable through a bank."},"tbond_10y":{"available":true,"localName":"Eidgenössische Anleihen","localNameEn":"Confederation bonds","sourceUrl":"https://tradingeconomics.com/switzerland/government-bond-yield"},"equity_fund":{"available":true,"localName":"Anlagefonds / Indexfonds","localNameEn":"Investment funds and index funds (ETF)","note":"Widely available; capital gains for private investors are generally tax-free, dividends taxed as income."},"gold":{"available":true,"localName":"Goldbarren und Goldmünzen","localNameEn":"Gold bars and coins","note":"Freely bought; investment gold is exempt from VAT."}},"institutions":{"centralBank":{"name":"Swiss National Bank (SNB)","url":"https://www.snb.ch/en/"},"insuranceRegulator":{"name":"FINMA (Swiss Financial Market Supervisory Authority)","url":"https://www.finma.ch/en/supervision/insurers/"},"insuranceComplaints":{"name":"Ombudsman of Private Insurance (Swiss insurance ombudsman foundation)","url":"https://ombudsman-assurance.ch/","note":"Health-insurance complaints go to the separate ombudsman for social health insurance."},"pensionScheme":{"name":"Old-age and survivors'' insurance (OASI / AHV / AVS)","url":"https://www.ahv-iv.ch/en/Social-insurances/Old-age-and-survivors-insurance-OASI"},"oldAgeAllowance":{"name":"Supplementary benefits to OASI (Ergänzungsleistungen / prestations complémentaires)","url":"https://www.ahv-iv.ch/en/Social-insurances/Supplementary-benefits-EL","note":"Means-tested top-up, not a flat social pension."},"publicHealthCover":{"name":"Compulsory health insurance (KVG/LAMal), Federal Office of Public Health","url":"https://www.bag.admin.ch/en/premiums-and-costs-answers-to-frequently-asked-questions","note":"Basic insurance is compulsory for all residents and bought from approved insurers; premium subsidies for low incomes."},"depositInsurance":{"name":"esisuisse (Swiss deposit protection)","url":"https://www.esisuisse.ch/en/protection-of-deposits/the-swiss-system"},"statistics":{"name":"Federal Statistical Office (FSO / BFS)","url":"https://www.bfs.admin.ch/en"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CH', 1, 'bank_deposit_avg_rate', 0.0008, NULL, 'sourced', 'World Bank WDI FR.INR.DPST (deposit interest rate)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=CH', '2025-12-31', '0.083% average for 2025; SNB new-business savings deposits averaged 0.07% in August 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CH', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Consumer Credit Ordinance sets maximum interest rates for consumer credit, overdrafts and credit cards, but the Fedlex text could not be read (script-only page), so the current cap is not confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CH', 1, 'deposit_insurance_limit', 100000, NULL, 'sourced', 'esisuisse (Swiss deposit protection scheme), the Swiss system', 'https://www.esisuisse.ch/en/protection-of-deposits/the-swiss-system', '2026-10-31', 'CHF 100,000 per client per bank; tied pension (pillar 3a) and vested-benefits deposits get a separate CHF 100,000.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CH', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Swiss banks do not sell a standard monthly recurring deposit product with a published rate; regular saving goes into savings accounts or tax-favoured tied pension (pillar 3a) accounts.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CH', 1, 'equity_return_base', 0.04, NULL, 'assumption', 'SMI (Trading Economics); 1-year term deposit 0.15% after tax about 0.1% (SNB zikrepro)', 'https://tradingeconomics.com/switzerland/stock-market', '2026-10-31', 'Base capped at the after-tax safe rate plus 4 points; with near-zero Swiss interest rates and a moderate decade for the SMI, 4% in francs is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CH', 1, 'equity_return_high', 0.06, NULL, 'assumption', 'SMI long-run record; long-run global equity returns in francs', 'https://tradingeconomics.com/switzerland/stock-market', '2026-10-31', 'High case: diversified Swiss and global equity funds matching their long-run record in francs, held back by the strong franc.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CH', 1, 'equity_return_low', 0.02, NULL, 'assumption', 'SMI 14,811 on 30 Oct 2026, +21% over the year and at an all-time high (Trading Economics)', 'https://tradingeconomics.com/switzerland/stock-market', '2026-10-31', 'Low case: from record highs, Swiss shares return only about 2% a year.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CH', 1, 'fdr_1y_rate', 0.0015, NULL, 'sourced', 'Swiss National Bank, interest rates on new business (zikrepro): term deposits of CHF 100,000 or more, 12 months, mean', 'https://data.snb.ch/en/topics/ziredev/cube/zikrepro', '2026-09-30', 'Average 0.152% in September 2026 (0.117% in August); bank cash bonds (Kassenobligationen) paid 0.49% for 2 years and 0.70% for 5 years. Series covers deposits of at least CHF 100,000.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CH', 1, 'fdr_3m_rate', 0.0003, NULL, 'sourced', 'Swiss National Bank, interest rates on new business (zikrepro): term deposits of CHF 100,000 or more, 3 months, mean', 'https://data.snb.ch/en/topics/ziredev/cube/zikrepro', '2026-09-30', 'Average 0.029% in September 2026; 1-month term deposits averaged -0.03%. Series covers deposits of at least CHF 100,000.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CH', 1, 'fixed_income_return_base', 0.001, NULL, 'assumption', '12-month term deposits 0.15% less income tax (SNB zikrepro, September 2026)', 'https://data.snb.ch/en/topics/ziredev/cube/zikrepro', '2026-10-31', 'Base case: the after-tax 1-year deposit rate, about 0.1%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CH', 1, 'fixed_income_return_high', 0.004, NULL, 'assumption', '10-year Confederation bond 0.47% and 5-year cash bonds 0.70%, less income tax', 'https://tradingeconomics.com/switzerland/government-bond-yield', '2026-10-31', 'High case: locking in longer Confederation bonds or bank cash bonds, after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CH', 1, 'fixed_income_return_low', 0, NULL, 'assumption', 'Savings deposits 0.07% (SNB zikrepro) less income tax', 'https://data.snb.ch/en/topics/ziredev/cube/zikrepro', '2026-10-31', 'Low case: easy-access savings pay essentially nothing after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CH', 1, 'goal_inflation_education', 0.015, NULL, 'assumption', 'Eurostat HICP Switzerland, education (CP10): -0.1% year on year in September 2026', 'https://ec.europa.eu/eurostat/databrowser/view/prc_hicp_minr/default/table?lang=en', '2026-10-31', 'Public schooling is free and university fees are low; private school and course fees are planned at about 1.5%, slightly above general inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CH', 1, 'goal_inflation_health', 0.04, NULL, 'assumption', 'FOPH: basic health insurance premiums up 5.0% on average for 2027; Eurostat HICP health +0.2% in September 2026', 'https://www.bag.admin.ch/en/premiums-and-costs-answers-to-frequently-asked-questions', '2026-10-31', 'Health prices in the CPI barely move, but premiums and cost sharing, which households actually pay, have risen 4-6% a year, so 4% is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CH', 1, 'gold_return_base', 0.03, NULL, 'assumption', 'Gold price history (Trading Economics); SNB 0-2% price stability', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Base case: dollar gold rises with world inflation, partly offset by a slowly appreciating franc.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CH', 1, 'gold_return_high', 0.06, NULL, 'assumption', 'Gold price history (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'High case: a repeat of gold''s strong 2005-2025 trend in franc terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CH', 1, 'gold_return_low', 0, NULL, 'assumption', 'Gold price history (Trading Economics); franc appreciation against the dollar', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Low case: gold flat in francs as the franc keeps rising against the dollar after the 2025-26 spike.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CH', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No days-per-year gratuity: the Code of Obligations (art. 339b) gives a one-off severance only to employees aged 50+ with 20+ years'' service, largely replaced by occupational pension (BVG) savings, which does not fit a days-per-year rule.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CH', 1, 'health_hospitalisation_cost', 1075, NULL, 'sourced', 'Federal Office of Public Health, premiums and costs FAQ (cost sharing in compulsory health insurance)', 'https://www.bag.admin.ch/en/premiums-and-costs-answers-to-frequently-asked-questions', '2026-10-31', 'Computed for an adult with the standard deductible: CHF 300 deductible plus the 10% co-payment cap of CHF 700 plus CHF 15 a day hospital contribution for 5 nights; with the highest deductible (CHF 2,500) it would be CHF 3,275.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CH', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Compulsory basic health insurance premiums are flat per person by canton, age group and deductible (average CHF 412 a month in 2027, FOPH), not priced per CHF 100,000 of cover; no such premium table exists.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CH', 1, 'inflation_cpi', 0.01, NULL, 'sourced', 'Trading Economics, Switzerland inflation rate (FSO CPI, secondary source)', 'https://tradingeconomics.com/switzerland/inflation-cpi', '2026-09-30', 'CPI up 1.0% year on year in September 2026 (0.8% in August); the Federal Statistical Office pages were being moved and could not be read. Eurostat HICP for Switzerland: 1.2%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CH', 1, 'inflation_projection', 0.01, NULL, 'assumption', 'SNB price stability defined as CPI inflation of 0-2%; CPI 1.0% in September 2026, World Bank 2025 average 0.15%', 'https://tradingeconomics.com/switzerland/inflation-cpi', '2026-10-31', 'Swiss inflation has averaged about 1% over the past five years including the 2022 spike, the middle of the SNB''s 0-2% range, so 1% is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CH', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life cover (Todesfallrisikoversicherung) is sold, but no regulator or official premium table per CHF 1,000 of cover was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CH', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'FINMA does not publish an industry-wide life insurance claim settlement ratio that could be found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CH', 1, 'life_expectancy', 84.2, NULL, 'sourced', 'Eurostat, life expectancy by age and sex (demo_mlexpec), Switzerland', 'https://ec.europa.eu/eurostat/databrowser/view/demo_mlexpec/default/table?lang=en', '2024-12-31', 'Men 82.4, women 85.9 in 2024; World Bank 2024 total 84.41.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CH', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":26.2,"men":24.7,"women":27.5},{"age":65,"total":21.8,"men":20.4,"women":23},{"age":70,"total":17.6,"men":16.4,"women":18.7},{"age":80,"total":10.2,"men":9.3,"women":10.8}]}', 'sourced', 'Eurostat, life expectancy by age and sex (demo_mlexpec), Switzerland 2024', 'https://ec.europa.eu/eurostat/databrowser/view/demo_mlexpec/default/table?lang=en', '2024-12-31', 'Latest year published is 2024 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CH', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'Supplementary benefits (Ergänzungsleistungen) are paid to OASI pensioners whose income does not cover basic needs (means-tested, with residence conditions for foreign nationals), but the ahv-iv.ch page and leaflet with the rules could not be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CH', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'There is no flat non-contributory old-age pension: every resident contributes to OASI (AHV), whose full pension is CHF 1,260-2,520 a month in 2026. Low-income pensioners can claim means-tested supplementary benefits (Ergänzungsleistungen), which top income up to a needs level and have no fixed monthly amount.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CH', 1, 'oop_health_share', 0.2203, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=CH', '2023-12-31', 'Latest year 2023 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CH', 1, 'policy_rate', 0, NULL, 'sourced', 'Swiss National Bank, official interest rates (data portal cube snboffzisa)', 'https://data.snb.ch/en/topics/ziredev/cube/snboffzisa', '2026-09-30', 'SNB policy rate 0% (unchanged since June 2025); Trading Economics also shows 0% at end-October 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CH', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":20,"entryAgeMax":null,"pensionFromAge":65,"nomineeUntilAge":null,"inflationLinked":true,"taxFree":false}', 'sourced', 'Information Centre OASI/DI, leaflet 3.01 Old-age pensions (2026)', 'https://www.ahv-iv.ch/p/3.01.e', '2026-10-31', 'OASI (AHV/AVS), compulsory for all residents: a full pension needs contributions every year from age 20 to the reference age (scale 44). Full pension CHF 1,260-2,520 a month in 2026 plus a 13th monthly payment from December 2026. Adjusted every two years by the mixed index of wages and prices; taxed as income. Occupational pension (BVG) is the compulsory second pillar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CH', 1, 'retirement_accumulation_return_base', 0.02, NULL, 'assumption', 'After-tax deposit rate about 0.1%; equity base 4%', 'https://data.snb.ch/en/topics/ziredev/cube/zikrepro', '2026-10-31', 'Base case: roughly half shares at 4% and half safe fixed income near zero after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CH', 1, 'retirement_accumulation_return_high', 0.035, NULL, 'assumption', '10-year bond 0.47%; equity high 6%', 'https://tradingeconomics.com/switzerland/government-bond-yield', '2026-10-31', 'High case for a growth-leaning balanced mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CH', 1, 'retirement_accumulation_return_low', 0.01, NULL, 'assumption', 'After-tax deposit rate about 0.1%; equity low 2%', 'https://data.snb.ch/en/topics/ziredev/cube/zikrepro', '2026-10-31', 'Low case for a balanced mix if shares lag.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CH', 1, 'retirement_age_default', 65, NULL, 'sourced', 'Information Centre OASI/DI, leaflet 3.01 Old-age pensions (2026)', 'https://www.ahv-iv.ch/p/3.01.e', '2026-10-31', 'Reference age 65 for men; for women it rises from 64 to 65 between 2025 and 2028 (born 1964 or later: 65), so 65 for anyone born after 1975. Pension can be drawn from 63 or deferred up to 5 years.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CH', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'Federal and cantonal staff generally retire at the OASI reference age under their own personnel and pension-fund rules; no single official retirement age for government service could be confirmed from a readable source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CH', 1, 'retirement_return_base', 0.001, NULL, 'assumption', '12-month term deposits 0.15% less tax (SNB zikrepro, September 2026)', 'https://data.snb.ch/en/topics/ziredev/cube/zikrepro', '2026-10-31', 'Base case capped at the after-tax 1-year term deposit rate (about 0.1% after a 25-35% marginal income tax).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CH', 1, 'retirement_return_high', 0.004, NULL, 'assumption', '10-year Confederation bond 0.47% less tax (Trading Economics)', 'https://tradingeconomics.com/switzerland/government-bond-yield', '2026-10-31', 'High case: a ladder of longer Confederation bonds and cash bonds after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CH', 1, 'retirement_return_low', 0, NULL, 'assumption', 'Savings deposits 0.07% less tax (SNB zikrepro)', 'https://data.snb.ch/en/topics/ziredev/cube/zikrepro', '2026-10-31', 'Low case: easy-access savings pay nothing after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CH', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Confederation does not sell a retail savings certificate or savings bond to individuals; Confederation bonds and money-market debt register claims are auctioned to market participants. Bank cash bonds (Kassenobligationen) are bank products.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CH', 1, 'savings_account_rate', 0.0007, NULL, 'sourced', 'Swiss National Bank, interest rates on new business by product (cube zikrepro): private clients'' savings deposits, mean', 'https://data.snb.ch/en/topics/ziredev/cube/zikrepro', '2026-09-30', 'Average 0.069% in September 2026 (0.069% in August); payment accounts without withdrawal restrictions pay about 0%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CH', 1, 'support_ratio', NULL, '{"points":[{"year":2026,"value":3.21},{"year":2040,"value":2.43},{"year":2065,"value":1.92}]}', 'sourced', 'Eurostat EUROPOP2023 projections, old-age dependency ratio (proj_23ndbi, baseline), Switzerland', 'https://ec.europa.eu/eurostat/databrowser/view/proj_23ndbi/default/table?lang=en', '2026-01-01', '100 divided by the projected old-age dependency ratio (65+ per 100 aged 15-64): 31.2 in 2026, 41.1 in 2040, 52.0 in 2065. World Bank 2025: 31.6.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CH', 1, 'tax_bank_interest', 0.35, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Switzerland income determination', 'https://taxsummaries.pwc.com/switzerland/individual/income-determination', '2026-07-01', 'Interest on Swiss bank accounts bears 35% withholding tax, credited or refunded when the interest is declared; it is then taxed with other income at ordinary federal, cantonal and communal rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CH', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No retail government savings certificate exists; interest on Confederation bonds bears the same 35% withholding tax and ordinary income tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CH', 1, 'tbill_91d_rate', -0.0005, NULL, 'sourced', 'Swiss National Bank, money market rates (cube zimoma): 3-month Confederation money-market debt register claims', 'https://data.snb.ch/en/topics/ziredev/cube/zimoma', '2026-09-30', 'Yield -0.047% in September 2026 (monthly average); SARON was -0.07%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CH', 1, 'tbond_10y_rate', 0.0047, NULL, 'sourced', 'Trading Economics, Switzerland 10-year government bond yield', 'https://tradingeconomics.com/switzerland/government-bond-yield', '2026-10-30', 'Secondary source; the SNB''s own yield series ended in July 2025. 2-year yield 0.18%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CH', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The SNB stopped publishing Confederation bond yields by maturity on its data portal after July 2025, and Trading Economics shows only the 2-year (0.18%) and 10-year yields; no current 5-year yield could be read.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('CI', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"CI","iso3":"CIV","nameEn":"Côte d''Ivoire","nameNative":"Côte d''Ivoire","region":"sub_saharan_africa","languages":["fr","dyu","bci"],"currency":{"code":"XOF","symbol":"F CFA","decimals":0,"compact":"intl","usdRate":{"value":587.14,"status":"sourced","sourceName":"BCEAO reference rate of the US dollar against the CFA franc","sourceUrl":"https://www.bceao.int/fr/cours/get_all_reference_by_date?dateJour=2026-10-30","asOf":"2026-10-30","note":"587.14 francs per dollar on 30 October 2026; the franc is fixed at 655.957 per euro. World Bank 2025 average 581.9."}},"instruments":{"savings_account":{"available":true,"localName":"Compte d''épargne","localNameEn":"Savings account"},"fdr_3m":{"available":true,"localName":"Dépôt à terme (3 mois)","localNameEn":"Term deposit (3 months)"},"fdr_1y":{"available":true,"localName":"Dépôt à terme (1 an)","localNameEn":"Term deposit (1 year)"},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No standard monthly recurring deposit product was found."},"sanchayapatra_5y":{"available":true,"localName":"Emprunt obligataire de l''État par appel public à l''épargne","localNameEn":"Government bond sold to the public","note":"The Treasury sells bonds to the public by public offering (appel public à l''épargne), bought through licensed brokers and listed on the regional exchange; income is tax-exempt for individuals. The current issue''s rate could not be confirmed from an official page."},"tbill_91d":{"available":false,"localName":"Bon assimilable du Trésor (BAT)","localNameEn":"Treasury bill","note":"Bills are auctioned to banks on the regional market, and recent Ivorian auctions were 12-month bills only.","sourceUrl":"https://www.umoatitres.org/fr/emission/emission-simultanee-de-bons-et-dobligations-du-tresor-de-la-cote-divoire-du-20-10-2026/"},"tbond_5y":{"available":true,"localName":"Obligation assimilable du Trésor (OAT, 5 ans)","localNameEn":"Treasury bond (5 years)","note":"Auctioned on the regional market; individuals buy through banks or licensed brokers.","sourceUrl":"https://www.umoatitres.org/fr/emission/emission-simultanee-de-bons-et-dobligations-du-tresor-de-la-cote-divoire-du-27-10-2026/"},"tbond_10y":{"available":false,"localName":null,"localNameEn":null,"note":"No recent 10-year auction was found; the longest recent maturity was 7 years."},"equity_fund":{"available":true,"localName":"OPCVM (FCP ou SICAV)","localNameEn":"Mutual fund","note":"Funds regulated by the regional financial markets authority invest in shares listed on the regional exchange in Abidjan."},"gold":{"available":true,"localName":"Or","localNameEn":"Gold","note":"Gold is sold mostly as jewellery."}},"institutions":{"centralBank":{"name":"Central Bank of West African States (Banque Centrale des États de l''Afrique de l''Ouest, BCEAO)","url":"https://www.bceao.int/"},"insuranceRegulator":{"name":"Inter-African Conference on Insurance Markets (CIMA), regional insurance supervisor","url":"https://cima-afrique.org/"},"insuranceComplaints":{"name":"CIMA, policyholder requests and complaints","url":"https://cima-afrique.org/faites-votre-requetes-ici-2/"},"pensionScheme":{"name":"National Social Insurance Fund (Caisse Nationale de Prévoyance Sociale, CNPS)","url":"https://www.cnps.ci/"},"oldAgeAllowance":null,"publicHealthCover":{"name":"National Health Insurance Fund (Caisse Nationale d''Assurance Maladie, CNAM): Universal Health Coverage (CMU)","url":"https://ipscnam.ci/enrolement-cmu/","note":"Contribution of 1,000 francs per person per month."},"depositInsurance":null,"statistics":{"name":"National Institute of Statistics (Institut National de la Statistique, INS)","url":"https://www.ins.ci/","note":"The site''s security certificate was misconfigured when checked."}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CI', 1, 'bank_deposit_avg_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The BCEAO''s September 2026 economic note gives only the Union-wide average deposit rate (5.15% in July 2026) and says Côte d''Ivoire''s fell 16 basis points; the country figure itself was not found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CI', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No current usury cap or typical credit card rate for Côte d''Ivoire was found; the Union-wide average lending rate was 6.70% in July 2026 (BCEAO).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CI', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'The UEMOA deposit guarantee and resolution fund (FGDR-UMOA) covers bank deposits, but its cover limit could not be read from an official source (its site could not be reached).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CI', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No standard monthly recurring deposit rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CI', 1, 'equity_return_base', 0.08, NULL, 'assumption', 'Assumed after-tax safe rate 4.5% (deposits) and tax-free government bonds about 7% (UMOA-Titres, October 2026)', 'https://www.umoatitres.org/fr/emission/emission-simultanee-de-bons-et-dobligations-du-tresor-de-la-cote-divoire-du-27-10-2026/', '2026-10-31', 'Base case for regional equities including dividends, held about 3.5 points above the after-tax deposit rate because the index''s 10-year record is uneven.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CI', 1, 'equity_return_high', 0.11, NULL, 'assumption', 'Regional stock exchange dividend yields and recent recovery', 'https://www.umoatitres.org/fr/emission/emission-simultanee-de-bons-et-dobligations-du-tresor-de-la-cote-divoire-du-27-10-2026/', '2026-10-31', 'High case: high dividend yields plus moderate price growth.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CI', 1, 'equity_return_low', 0.03, NULL, 'assumption', 'BCEAO: UEMOA government bond yields about 7%; regional stock exchange in Abidjan with a volatile 10-year record', 'https://www.umoatitres.org/fr/emission/emission-simultanee-de-bons-et-dobligations-du-tresor-de-la-cote-divoire-du-27-10-2026/', '2026-10-31', 'Low case: a decade like 2016-2020, when the regional index fell sharply.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CI', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published 1-year term deposit rate for Côte d''Ivoire was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CI', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published 3-month term deposit rate for Côte d''Ivoire was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CI', 1, 'fixed_income_return_base', 0.045, NULL, 'assumption', 'UEMOA average deposit rate 5.15% (July 2026) less 13.5% tax', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-10-31', 'Base case: term deposits at the Union average rate after tax (about 4.45%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CI', 1, 'fixed_income_return_high', 0.06, NULL, 'assumption', 'Tax-free Treasury bonds for individuals, about 6-7% (UMOA-Titres, October 2026)', 'https://www.umoatitres.org/fr/emission/emission-simultanee-de-bons-et-dobligations-du-tresor-de-la-cote-divoire-du-27-10-2026/', '2026-10-31', 'High case: government bonds bought by individuals, whose income is tax-exempt, allowing for lower retail coupons.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CI', 1, 'fixed_income_return_low', 0.03, NULL, 'assumption', 'UEMOA average deposit rate 5.15% (July 2026); 13.5% tax on deposit interest', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-10-31', 'Low case: ordinary savings at lower rates after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CI', 1, 'goal_inflation_education', 0.035, NULL, 'assumption', 'Inflation assumption 2%; BCEAO', 'https://www.bceao.int/fr/content/principaux-indicateurs-et-taux-directeurs', '2026-10-31', 'No education CPI series was confirmed; school costs are planned 1.5 points above general inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CI', 1, 'goal_inflation_health', 0.04, NULL, 'assumption', 'Inflation assumption 2%; BCEAO', 'https://www.bceao.int/fr/content/principaux-indicateurs-et-taux-directeurs', '2026-10-31', 'No medical CPI series was confirmed; medical costs are planned 2 points above general inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CI', 1, 'gold_return_base', 0.04, NULL, 'assumption', 'Long-run gold trend in euro terms; franc fixed to the euro', 'https://www.bceao.int/fr/cours/get_all_reference_by_date?dateJour=2026-10-30', '2026-10-31', 'Base case: the long-run gold trend of about 4% a year, with no currency gain under the peg.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CI', 1, 'gold_return_high', 0.08, NULL, 'assumption', 'Gold in euro terms', 'https://www.bceao.int/fr/cours/get_all_reference_by_date?dateJour=2026-10-30', '2026-10-31', 'High case: strong gold years.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CI', 1, 'gold_return_low', 0, NULL, 'assumption', 'Franc fixed at 655.957 per euro (BCEAO reference rates)', 'https://www.bceao.int/fr/cours/get_all_reference_by_date?dateJour=2026-10-30', '2026-10-31', 'Low case: flat gold prices in euro terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CI', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Labour Code provisions on retirement indemnity could not be read from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CI', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a major private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CI', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premiums by age were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CI', 1, 'inflation_cpi', 0.016, NULL, 'sourced', 'Trading Economics, citing the Institut National de la Statistique (INS) of Côte d''Ivoire, CPI September 2026', 'https://tradingeconomics.com/ivory-coast/inflation-cpi', '2026-09-30', 'Consumer prices up 1.6% year on year in September 2026 (1.2% in August, after 1.9%, which the BCEAO''s September 2026 economic note confirms); secondary source because the INS site''s certificate is misconfigured.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CI', 1, 'inflation_projection', 0.02, NULL, 'assumption', 'BCEAO inflation target range of 1-3% (centre 2%); UEMOA inflation 0.0% in 2025, 1.0% expected for 2026 (CPM, 9 September 2026)', 'https://www.bceao.int/fr/communique-presse/communique-de-presse-de-la-reunion-ordinaire-du-comite-de-politique-monetaire-19', '2026-10-31', 'The franc is pegged to the euro and the BCEAO aims at 2% within a 1-3% band; Union inflation was 0.0% in 2025 and is expected at 1.0% in 2026, so 2% is a rounded planning rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CI', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life cover is sold, but no published premium rates per XOF 1,000 of cover were found from the regulator or an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CI', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No life insurance claim settlement ratio for Côte d''Ivoire was found from the regional supervisor (CIMA) or the national insurance directorate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CI', 1, 'life_expectancy', 62.11, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN), Côte d''Ivoire', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=CI', '2024-12-31', '62.1 years in 2024 (men 60.2, women 64.3); older than 2025 but the latest World Bank year. UN WPP 2024 gives 62.4 for 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CI', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":16.3,"men":15.2,"women":17.3},{"age":65,"total":13.2,"men":12.4,"women":14.2},{"age":70,"total":10.6,"men":9.8,"women":11.4},{"age":80,"total":6.3,"men":5.8,"women":6.7}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/c%C3%B4te-divoire/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026; the both-sexes figure at 65 is published, the others are the mean of men and women.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CI', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension rules were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CI', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age (social) pension was found; the CNPS pays contributory pensions only.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CI', 1, 'oop_health_share', 0.3199, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), Côte d''Ivoire', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=CI', '2023-12-31', '32.0% in 2023 (WHO Global Health Expenditure Database via the World Bank); older than 2025 but the latest available.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CI', 1, 'policy_rate', 0.03, NULL, 'sourced', 'BCEAO Monetary Policy Committee, 9 September 2026: main policy rate (minimum bid rate on liquidity tenders)', 'https://www.bceao.int/fr/communique-presse/communique-de-presse-de-la-reunion-ordinaire-du-comite-de-politique-monetaire-19', '2026-09-09', 'Held at 3.00% (in force since 16 March 2026); marginal lending facility 5.00%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CI', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":60,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'Caisse Nationale de Prévoyance Sociale (CNPS), old-age insurance factsheet', 'https://www.cnps.ci/wp-content/uploads/2022/11/ASSURANCE-VIEILLESSE-V2.pdf', '2026-10-31', 'Compulsory for private-sector employees (6.3% employee and 7.7% employer, PwC Tax Summaries 2026); pension from 60 after 15 years, equal to the average of the best 15 years'' salary times 1.33% or 1.70% per year of career, plus 10% per dependent child (up to 3). The 2021 factsheet says nothing about indexation, so inflationLinked is set to false (no automatic indexation confirmed).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CI', 1, 'retirement_accumulation_return_base', 0.06, NULL, 'assumption', 'Safe rate 4.5%, government bonds about 7%, equity base 8%, gold base 4%', 'https://www.umoatitres.org/fr/emission/emission-simultanee-de-bons-et-dobligations-du-tresor-de-la-cote-divoire-du-27-10-2026/', '2026-10-31', 'Base case: a balanced mix of deposits, government bonds, regional equity funds and gold.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CI', 1, 'retirement_accumulation_return_high', 0.085, NULL, 'assumption', 'Equity high 11%; bonds about 7%', 'https://www.umoatitres.org/fr/emission/emission-simultanee-de-bons-et-dobligations-du-tresor-de-la-cote-divoire-du-27-10-2026/', '2026-10-31', 'High case: a growth-leaning mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CI', 1, 'retirement_accumulation_return_low', 0.035, NULL, 'assumption', 'Safe rate 4.5%; equity low 3%', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-10-31', 'Low case: mostly deposits with weak equity and gold years.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CI', 1, 'retirement_age_default', 60, NULL, 'sourced', 'Caisse Nationale de Prévoyance Sociale (CNPS), old-age insurance factsheet', 'https://www.cnps.ci/wp-content/uploads/2022/11/ASSURANCE-VIEILLESSE-V2.pdf', '2026-10-31', 'Pension from 60 with at least 15 years of insured salaried work (applies to people born after 1975); early pension from 55 reduced 5% per year of anticipation. The factsheet dates from 2021 (older than 2025); no later change was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CI', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'The civil-service retirement age could not be confirmed from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CI', 1, 'retirement_return_base', 0.04, NULL, 'assumption', 'UEMOA average deposit rate 5.15% (July 2026) less 13.5% tax = about 4.45%', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-10-31', 'Base case kept below the after-tax deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CI', 1, 'retirement_return_high', 0.055, NULL, 'assumption', 'Tax-free Treasury bonds for individuals, about 6-7% (UMOA-Titres)', 'https://www.umoatitres.org/fr/emission/emission-simultanee-de-bons-et-dobligations-du-tresor-de-la-cote-divoire-du-27-10-2026/', '2026-10-31', 'High case: government bonds held to maturity, tax-exempt for individuals.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CI', 1, 'retirement_return_low', 0.025, NULL, 'assumption', 'UEMOA average deposit rate 5.15% less 13.5% tax', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-10-31', 'Low case: savings and short deposits after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CI', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Treasury sells bonds to the public by public offering (appel public à l''épargne), but the rate of a current issue could not be confirmed from an official page.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CI', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No current savings-account rate for Côte d''Ivoire was found; the BCEAO publishes only an average deposit rate for the Union.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CI', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":21.4},{"year":2040,"value":16.9},{"year":2065,"value":11.9}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/c%C3%B4te-divoire/2040/', '2025-12-31', '100 / old-age dependency ratio: 4.66 (2025, World Bank), 5.9 (2040) and 8.4 (2065, populationpyramid.net).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CI', 1, 'tax_bank_interest', 0.135, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Côte d''Ivoire, withholding taxes (tax on income from debt claims, IRC)', 'https://taxsummaries.pwc.com/ivory-coast/corporate/withholding-taxes', '2026-09-09', 'The general rate on interest is 18%, reduced to 13.5% for individuals on bank deposit interest; 25% on cash certificates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CI', 1, 'tax_sanchayapatra_profit', 0, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Côte d''Ivoire, withholding taxes', 'https://taxsummaries.pwc.com/ivory-coast/corporate/withholding-taxes', '2026-09-09', 'Income realised by individuals on Treasury bonds is exempt from tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CI', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No recent 91-day bill auction for Côte d''Ivoire was found; the latest 12-month bill (20 October 2026) yielded 3.89% on average (UMOA-Titres).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CI', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 10-year bond auction for Côte d''Ivoire was found in October 2026; the longest recent auction was 7 years at 7.11-7.18% (UMOA-Titres).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CI', 1, 'tbond_5y_rate', 0.0704, NULL, 'sourced', 'UMOA-Titres (UEMOA public securities agency), Côte d''Ivoire Treasury bond auction of 27 October 2026, 5-year bond', 'https://www.umoatitres.org/fr/emission/emission-simultanee-de-bons-et-dobligations-du-tresor-de-la-cote-divoire-du-27-10-2026/', '2026-10-27', 'Weighted average yield 7.04% on the 60-month bond (coupon 5.45%); 7.03% at the 20 October auction.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('CL', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"CL","iso3":"CHL","nameEn":"Chile","nameNative":"Chile","region":"latin_america_caribbean","languages":["es","en","arn"],"currency":{"code":"CLP","symbol":"$","decimals":0,"compact":"intl","usdRate":{"value":994.29,"status":"sourced","sourceName":"Servicio de Impuestos Internos, dólar observado (published by the Banco Central de Chile), 27 October 2026","sourceUrl":"https://www.sii.cl/valores_y_fechas/dolar/dolar2026.htm","asOf":"2026-10-27","note":"CLP 994.29 per US dollar on 27 October 2026 (October average to date 981.58); World Bank 2025 average 951.3."}},"instruments":{"savings_account":{"available":true,"localName":"Cuenta de ahorro","localNameEn":"Savings account","note":"Mostly UF-indexed accounts with a small real rate; no published average rate."},"fdr_3m":{"available":true,"localName":"Depósito a plazo","localNameEn":"Term deposit (30-89 days)","sourceUrl":"https://si3.bcentral.cl/Siete/ES/Siete/Cuadro/CAP_TASA_INTERES/MN_TASA_INTERES_09/TSF_34/T531"},"fdr_1y":{"available":true,"localName":"Depósito a plazo","localNameEn":"Term deposit (90 days to 1 year)","note":"Also sold in UF (inflation-indexed) for terms of 90 days or more.","sourceUrl":"https://si3.bcentral.cl/Siete/ES/Siete/Cuadro/CAP_TASA_INTERES/MN_TASA_INTERES_09/TSF_34/T531"},"dps":{"available":false,"localName":null,"localNameEn":"Recurring deposit","note":"No standard monthly recurring-deposit product."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":"Government savings certificate","note":"No retail government savings certificate or savings bond."},"tbill_91d":{"available":false,"localName":null,"localNameEn":"Treasury bill","note":"No Treasury bills; central bank discount notes (PDBC) are sold to institutions only.","sourceUrl":"https://si3.bcentral.cl/estadisticas/Diario1/aplicaciones/Informativo/inf20261030.pdf"},"tbond_5y":{"available":true,"localName":"Bono de la Tesorería en pesos (BTP)","localNameEn":"Treasury peso bond, 5 years","note":"Bought by individuals through brokers or bond funds.","sourceUrl":"https://si3.bcentral.cl/estadisticas/Diario1/aplicaciones/Informativo/inf20261030.pdf"},"tbond_10y":{"available":true,"localName":"Bono de la Tesorería en pesos (BTP)","localNameEn":"Treasury peso bond, 10 years","sourceUrl":"https://si3.bcentral.cl/estadisticas/Diario1/aplicaciones/Informativo/inf20261030.pdf"},"equity_fund":{"available":true,"localName":"Fondo mutuo accionario","localNameEn":"Equity mutual fund or index fund (ETF)","note":"Equity mutual funds and ETFs are widely sold to retail investors; voluntary pension savings (APV) carry tax relief."},"gold":{"available":true,"localName":"Oro físico (lingotes y monedas)","localNameEn":"Physical gold bars and coins","note":"Buying physical gold is legal; there is no specific retail gold scheme."}},"institutions":{"centralBank":{"name":"Banco Central de Chile","url":"https://www.bcentral.cl/"},"insuranceRegulator":{"name":"Comisión para el Mercado Financiero (CMF)","url":"https://www.cmfchile.cl/"},"insuranceComplaints":{"name":"CMF, consultas y reclamos (Presentaciones CMF)","url":"https://www.cmfchile.cl/","note":"Complain to the insurer first; then to the CMF. Health insurers (ISAPRE) are handled by the Superintendencia de Salud."},"pensionScheme":{"name":"Superintendencia de Pensiones (AFP system)","url":"https://www.spensiones.cl/"},"oldAgeAllowance":{"name":"Pensión Garantizada Universal (PGU), Instituto de Previsión Social","url":"https://www.chileatiende.gob.cl/fichas/102077-pension-garantizada-universal-pgu"},"publicHealthCover":{"name":"Fondo Nacional de Salud (FONASA)","url":"https://www.fonasa.cl/"},"depositInsurance":{"name":"State deposit guarantee (Garantía estatal a los depósitos), explained by the CMF","url":"https://www.cmfchile.cl/educa/621/w3-article-27460.html","note":"No separate insurer: the state guarantees term deposits of individuals up to 200 UF per bank per year."},"statistics":{"name":"Instituto Nacional de Estadísticas (INE)","url":"https://www.ine.gob.cl/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CL', 1, 'bank_deposit_avg_rate', 0.0427, NULL, 'sourced', 'Banco Central de Chile, average deposit rates and flows of the financial system, peso operations (weighted by September 2026 flows)', 'https://si3.bcentral.cl/Siete/ES/Siete/Cuadro/CAP_TASA_INTERES/MN_TASA_INTERES_09/TSF_34/T531', '2026-09-30', 'Weighting the four term buckets by their September 2026 flows (CLP 18.3 trillion at 4.12%, 4.3 trillion at 4.53%, 1.5 trillion at 5.26%, 0.02 trillion at 5.95%) gives about 4.27% a year. World Bank FR.INR.DPST 2024: 6.07%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CL', 1, 'credit_card_rate_cap', 0.4102, NULL, 'sourced', 'Comisión para el Mercado Financiero, Certificado 10/2026 (Diario Oficial 15 Oct 2026): maximum conventional interest rate', 'https://www.diariooficial.interior.gob.cl/publicaciones/2026/10/15/44574/01/2885690.pdf', '2026-10-15', 'Legal cap (tasa máxima convencional) for non-indexed peso credit of 90 days or more up to 50 UF, the bracket covering most card balances: 41.02% a year (simple annual rate) from 15 October 2026; 47.73% for under 90 days.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CL', 1, 'deposit_insurance_limit', 8249526, NULL, 'sourced', 'Dirección de Presupuestos (Ministry of Finance), Informe de Pasivos Contingentes 2025: state guarantee on deposits (Ley 21.130); UF value from the SII', 'https://www.dipres.gob.cl/598/articles-400549_doc_pdf.pdf', '2026-10-31', 'The state guarantees 100% of term deposits of individuals up to 200 UF per bank per calendar year (400 UF across the system), set by Ley 21.130 of 2019; 200 UF = CLP 8,249,526 at the UF of 41,247.63 on 31 October 2026 (sii.cl).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CL', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No monthly recurring-deposit product with a published rate exists in Chile; regular saving is done through savings accounts, term deposits, mutual funds or voluntary pension savings (APV).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CL', 1, 'equity_return_base', 0.075, NULL, 'assumption', 'IGPA index history (Trading Economics); after-tax 1-year deposit about 4.3%', 'https://tradingeconomics.com/chile/stock-market', '2026-10-31', 'Base case about 3 points over the after-tax safe rate, kept modest because the local index''s 10-year record is mixed; diversified global funds are also widely held.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CL', 1, 'equity_return_high', 0.1, NULL, 'assumption', 'IGPA record high 58,749 in January 2026 (Trading Economics)', 'https://tradingeconomics.com/chile/stock-market', '2026-10-31', 'High case: Chilean and global shares keep close to their strong 2023-2026 gains.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CL', 1, 'equity_return_low', 0.04, NULL, 'assumption', 'Santiago Stock Exchange IGPA index 51,947 on 30 Oct 2026, up about 9% in a year (Trading Economics)', 'https://tradingeconomics.com/chile/stock-market', '2026-10-31', 'Low case: Chilean shares repeat their flat 2016-2023 decade and earn little more than deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CL', 1, 'fdr_1y_rate', 0.0453, NULL, 'sourced', 'Banco Central de Chile, average deposit rates of the financial system, peso operations, 90 days to 1 year (Base de Datos Estadísticos)', 'https://si3.bcentral.cl/Siete/ES/Siete/Cuadro/CAP_TASA_INTERES/MN_TASA_INTERES_09/TSF_34/T531', '2026-09-30', 'Average rate on new peso term deposits of 90 days to 1 year was 4.53% in September 2026; 1-3 year deposits paid 5.26%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CL', 1, 'fdr_3m_rate', 0.0412, NULL, 'sourced', 'Banco Central de Chile, average deposit rates of the financial system, peso operations, 30 to 89 days (Base de Datos Estadísticos)', 'https://si3.bcentral.cl/Siete/ES/Siete/Cuadro/CAP_TASA_INTERES/MN_TASA_INTERES_09/TSF_34/T531', '2026-09-30', 'Average rate on new non-indexed peso term deposits of 30-89 days was 4.12% a year in September 2026 (4.14% in August); deposits of 90 days to 1 year paid 4.53%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CL', 1, 'fixed_income_return_base', 0.043, NULL, 'assumption', '90-day to 1-year deposits 4.53% (Banco Central de Chile) less tax on the real part', 'https://si3.bcentral.cl/Siete/ES/Siete/Cuadro/CAP_TASA_INTERES/MN_TASA_INTERES_09/TSF_34/T531', '2026-10-31', 'Base case: term deposits after tax; tax applies only to real interest, so the after-tax rate stays close to the nominal one for most savers.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CL', 1, 'fixed_income_return_high', 0.055, NULL, 'assumption', '10-year peso government bond 6.00% (Banco Central de Chile daily bulletin)', 'https://si3.bcentral.cl/estadisticas/Diario1/aplicaciones/Informativo/inf20261030.pdf', '2026-10-31', 'High case: locking in medium and long government bonds (through funds or brokers) at today''s yields.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CL', 1, 'fixed_income_return_low', 0.035, NULL, 'assumption', '30-89 day deposits 4.12% (Banco Central de Chile) less a little tax', 'https://si3.bcentral.cl/Siete/ES/Siete/Cuadro/CAP_TASA_INTERES/MN_TASA_INTERES_09/TSF_34/T531', '2026-10-31', 'Low case: short deposits only, with further rate cuts.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CL', 1, 'goal_inflation_education', 0.05, NULL, 'assumption', 'INE, IPC September 2026 bulletin: Educación division up 5.8% over 12 months', 'https://www.ine.gob.cl/docs/default-source/%C3%ADndice-de-precios-al-consumidor/boletines/espa%C3%B1ol/2026/boletin-%C3%ADndice-de-precios-al-consumidor-septiembre-2026.pdf', '2026-10-31', 'Education prices rose 5.8% in the year to September 2026; planning uses 5%, about 2 points above general inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CL', 1, 'goal_inflation_health', 0.05, NULL, 'assumption', 'INE, IPC September 2026 bulletin: Salud division up 5.1% over 12 months', 'https://www.ine.gob.cl/docs/default-source/%C3%ADndice-de-precios-al-consumidor/boletines/espa%C3%B1ol/2026/boletin-%C3%ADndice-de-precios-al-consumidor-septiembre-2026.pdf', '2026-10-31', 'Health prices rose 5.1% against 4.1% for all items; planning uses 5%, about 2 points above the 3% target, since medical costs rise faster over long periods.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CL', 1, 'gold_return_base', 0.05, NULL, 'assumption', 'Gold USD price history (Trading Economics); Chile 3% vs US 2% inflation targets', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Base case: gold rises roughly with world inflation plus a little in dollars, and the peso loses about 1% a year against the dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CL', 1, 'gold_return_high', 0.09, NULL, 'assumption', 'Gold USD price history (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'High case: a repeat of gold''s strong 2005-2025 trend in pesos.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CL', 1, 'gold_return_low', 0.01, NULL, 'assumption', 'Gold USD price history (Trading Economics); CLP 994 per USD (SII, 27 Oct 2026)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Low case: gold stalls after the 2025-26 rally and the peso firms with copper prices.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CL', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'Chile''s Labour Code gives severance of 30 days'' pay per year of service (capped at 11 years and 90 UF a month) only when the employer dismisses for business needs, not on retirement or resignation, so there is no retirement gratuity; the Labour Directorate page stating the scale could not be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CL', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No official figure for the typical out-of-pocket cost of a major private hospital stay was found; costs depend on FONASA or ISAPRE coverage.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CL', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Private health insurance (ISAPRE plans and complementary policies) is priced per person in UF a month, not per sum insured; no public premium table per CLP 100,000 of cover exists.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CL', 1, 'inflation_cpi', 0.041, NULL, 'sourced', 'Instituto Nacional de Estadísticas (INE), Boletín estadístico IPC septiembre 2026 (edition 335, 8 Oct 2026)', 'https://www.ine.gob.cl/docs/default-source/%C3%ADndice-de-precios-al-consumidor/boletines/espa%C3%B1ol/2026/boletin-%C3%ADndice-de-precios-al-consumidor-septiembre-2026.pdf', '2026-09-30', 'CPI rose 0.4% in September 2026, 4.0% so far in 2026 and 4.1% over 12 months (released 8 October 2026). World Bank 2025 average 4.2%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CL', 1, 'inflation_projection', 0.03, NULL, 'assumption', 'Banco Central de Chile 3% inflation target over a two-year horizon (reported by Rankia, Oct 2026); CPI 4.1% in September 2026', 'https://www.rankia.cl/noticias/bolsa/7528705-tpm-octubre-2026-banco-central-chile-mantiene-tasa-4-5', '2026-10-31', 'The central bank''s 3% target has a long record of credibility and inflation expectations two years ahead stay near it, so planning uses the target despite the current 4.1% rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CL', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life insurance is sold in Chile, but no regulator or other public table of premiums per CLP 1,000 of cover by age was found; only company quotes exist.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CL', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The CMF publishes insurance market statistics, but no industry-wide life claim settlement ratio was found (the CMF site could not be reached).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CL', 1, 'life_expectancy', 81.7, NULL, 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/chile', '2026-07-01', 'Life expectancy at birth 81.7 years in 2026 (men 79.9, women 83.5), UN WPP estimate. World Bank 2024: 81.4.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CL', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":25,"men":23.8,"women":26.1},{"age":65,"total":20.9,"men":19.7,"women":21.9},{"age":70,"total":17,"men":16,"women":17.8},{"age":80,"total":10.4,"men":9.8,"women":10.9}]}', 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/chile', '2026-07-01', 'Remaining years from georank''s expected age at death by current age (UN WPP 2026 estimate).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CL', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":65,"womenAge":65,"over90Monthly":null,"meansTested":true}', 'sourced', 'ChileAtiende (Instituto de Previsión Social), Pensión Garantizada Universal (PGU)', 'https://www.chileatiende.gob.cl/fichas/102077-pension-garantizada-universal-pgu', '2026-09-24', 'Age 65 for men and women; not in the richest 10% of the population (pension targeting score), at least 20 years'' residence since age 20 and 4 of the last 5 years, and a base pension of at most CLP 1,252,602.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CL', 1, 'old_age_allowance_monthly', 231732, NULL, 'sourced', 'ChileAtiende (Instituto de Previsión Social), Pensión Garantizada Universal (PGU)', 'https://www.chileatiende.gob.cl/fichas/102077-pension-garantizada-universal-pgu', '2026-09-24', 'PGU pays CLP 231,732 a month at 65-74 to people with a base pension up to CLP 789,139 (a smaller amount up to CLP 1,252,602); from 75 the maximum is CLP 250,275 under the 2025 pension reform. It is paid on top of other pensions and while still working.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CL', 1, 'oop_health_share', 0.3915, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=CL', '2024-12-31', 'Out-of-pocket spending was 39.1% of current health expenditure in 2024 (latest available; older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CL', 1, 'policy_rate', 0.045, NULL, 'sourced', 'Banco Central de Chile, Informativo diario de operaciones financieras, 30 October 2026 (TPM)', 'https://si3.bcentral.cl/estadisticas/Diario1/aplicaciones/Informativo/inf20261030.pdf', '2026-10-27', 'Monetary policy rate (TPM) 4.50%, held unanimously at the 27 October 2026 meeting and unchanged since December 2025; next meeting 15 December 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CL', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":65,"nomineeUntilAge":null,"inflationLinked":true,"taxFree":false}', 'sourced', 'ChileAtiende, Pensión de vejez del sistema de pensiones (AFP)', 'https://www.chileatiende.gob.cl/fichas/5256-pension-de-vejez-del-sistema-de-pensiones-afp', '2026-03-17', 'Compulsory individual-account system (AFP) for employees, with a new employer-funded social insurance component from the 2025 reform: pension age 65 (men) or 60 (women); the pension depends on the account balance, age and life expectancy, annuities are paid in inflation-indexed UF, and pensions are taxed as income.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CL', 1, 'retirement_accumulation_return_base', 0.058, NULL, 'assumption', 'Fixed income base 4.3%; equity base 7.5%', 'https://tradingeconomics.com/chile/stock-market', '2026-10-31', 'Base case: roughly half shares at 7.5% and half safe fixed income at about 4.3% after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CL', 1, 'retirement_accumulation_return_high', 0.08, NULL, 'assumption', 'Equity high 10%; 10-year peso bond 6.0%', 'https://tradingeconomics.com/chile/stock-market', '2026-10-31', 'High case for a growth-leaning balanced mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CL', 1, 'retirement_accumulation_return_low', 0.035, NULL, 'assumption', 'After-tax deposits 3.5-4.3%; IGPA record (Trading Economics)', 'https://tradingeconomics.com/chile/stock-market', '2026-10-31', 'Low case for a balanced mix if shares lag.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CL', 1, 'retirement_age_default', 65, NULL, 'sourced', 'ChileAtiende, Pensión de vejez del sistema de pensiones (AFP)', 'https://www.chileatiende.gob.cl/fichas/5256-pension-de-vejez-del-sistema-de-pensiones-afp', '2026-03-17', 'Legal pension age 65 for men and 60 for women in the individual-account system (DL 3.500); retiring is optional at that age and early retirement needs a pension of at least 12 UF.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CL', 1, 'retirement_age_government', 65, NULL, 'sourced', 'ChileAtiende, Pensión de vejez del sistema de pensiones (AFP)', 'https://www.chileatiende.gob.cl/fichas/5256-pension-de-vejez-del-sistema-de-pensiones-afp', '2026-03-17', 'Civil servants hired since 1981 contribute to the same AFP system, so the same pension ages of 65 (men) and 60 (women) apply; no separate civil-service pension age was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CL', 1, 'retirement_return_base', 0.042, NULL, 'assumption', '90-day to 1-year deposits 4.53% less tax on real interest (Banco Central de Chile; PwC)', 'https://si3.bcentral.cl/Siete/ES/Siete/Cuadro/CAP_TASA_INTERES/MN_TASA_INTERES_09/TSF_34/T531', '2026-10-31', 'Base case kept just below the after-tax 1-year deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CL', 1, 'retirement_return_high', 0.052, NULL, 'assumption', '5-10 year peso government bonds 5.81-6.00% (Banco Central de Chile daily bulletin)', 'https://si3.bcentral.cl/estadisticas/Diario1/aplicaciones/Informativo/inf20261030.pdf', '2026-10-31', 'High case: a ladder of medium government bonds or UF-indexed annuities bought at today''s yields.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CL', 1, 'retirement_return_low', 0.035, NULL, 'assumption', '30-89 day deposits 4.12% (Banco Central de Chile)', 'https://si3.bcentral.cl/Siete/ES/Siete/Cuadro/CAP_TASA_INTERES/MN_TASA_INTERES_09/TSF_34/T531', '2026-10-31', 'Low case: short deposits after small taxes, with rate cuts.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CL', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Chile has no government savings certificate or retail savings bond sold directly to individuals; Treasury bonds (BTP/BTU) are auctioned to institutions and bought by individuals only through brokers.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CL', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Bank savings accounts (cuentas de ahorro) in Chile are mostly UF-indexed with a small real rate; no published average rate was found in central bank or CMF statistics that could be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CL', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":4.72},{"year":2040,"value":3.02},{"year":2065,"value":1.49}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/chile/2040/', '2025-12-31', '100 / old-age dependency ratio: 21.2 (2025, World Bank), 33.1 (2040) and 66.9 (2065, populationpyramid.net/chile/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CL', 1, 'tax_bank_interest', 0.04, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Chile income determination and taxes on personal income (reviewed 30 Oct 2026)', 'https://taxsummaries.pwc.com/chile/individual/income-determination', '2026-10-30', 'No withholding: only real interest (interest less the rise in the cost of living) is added to income and taxed at the progressive Global Complementary Tax rates (0% to 40%); 4% is the bracket rate for a middle earner (taxable income about 13.5-30 UTA a year). Many small savers pay nothing.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CL', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'There is no government savings certificate in Chile; government bond interest is taxed like other interest (real interest at progressive rates).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CL', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Treasury issues no bills; the central bank''s 30-360 day discount notes (PDBC) are auctioned to banks and institutional investors, and no PDBC 90-day auction was held in late October 2026 (Banco Central de Chile daily bulletin). The 180-day average interbank swap rate was 4.66%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CL', 1, 'tbond_10y_rate', 0.06, NULL, 'sourced', 'Banco Central de Chile, Informativo diario de operaciones financieras, 30 October 2026: peso bond rates, 10 years', 'https://si3.bcentral.cl/estadisticas/Diario1/aplicaciones/Informativo/inf20261030.pdf', '2026-10-28', 'Secondary-market yield on 10-year peso government bonds was 6.00% on 28 October 2026 (Trading Economics: 5.98% on 30 October); 10-year UF bonds yielded 2.62% real.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CL', 1, 'tbond_5y_rate', 0.0581, NULL, 'sourced', 'Banco Central de Chile, Informativo diario de operaciones financieras, 30 October 2026: peso bond rates, 5 years', 'https://si3.bcentral.cl/estadisticas/Diario1/aplicaciones/Informativo/inf20261030.pdf', '2026-10-28', 'Secondary-market yield on 5-year peso government bonds (BTP/BCP) was 5.81% on 28 October 2026; 5-year UF-indexed bonds yielded 2.27% real.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('CM', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"CM","iso3":"CMR","nameEn":"Cameroon","nameNative":"Cameroun","region":"sub_saharan_africa","languages":["fr","en","bum","ff","ewo"],"currency":{"code":"XAF","symbol":"FCFA","decimals":0,"compact":"intl","usdRate":{"value":585.966,"status":"sourced","sourceName":"Trading Economics, USD/XAF market rate, 30 October 2026","sourceUrl":"https://tradingeconomics.com/cameroon/currency","asOf":"2026-10-30","note":"Secondary source: the CFA franc is pegged to the euro at 655.957 and BEAC publishes no daily dollar rate on a page that could be read; World Bank 2025 average 581.9 per dollar."}},"instruments":{"savings_account":{"available":true,"localName":"Compte d''épargne (livret)","localNameEn":"Savings account (passbook)","note":"Banks must pay at least the BEAC minimum savings rate (TCM, 2.45%) on passbook savings up to 5 million FCFA.","sourceUrl":"https://www.beac.int/wp-content/uploads/2018/11/Rapport-sur-La-Politique-Mon%C3%A9taire-de-la-BEAC_Sept-2026_vf_new2_Publiable.pdf"},"fdr_3m":{"available":true,"localName":"Dépôt à terme","localNameEn":"Term deposit","note":"Rates are set freely by banks; no published average was found."},"fdr_1y":{"available":true,"localName":"Dépôt à terme (1 an)","localNameEn":"Term deposit, 1 year","note":"Rates are set freely by banks; no published average was found."},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No standard monthly recurring deposit product was found."},"sanchayapatra_5y":{"available":true,"localName":"Emprunt obligataire de l''État","localNameEn":"Government bond public offering","note":"The State periodically sells bonds to individuals through public offerings listed on the regional stock exchange; no fixed savings certificate exists."},"tbill_91d":{"available":true,"localName":"Bons du Trésor assimilables (BTA)","localNameEn":"Treasury bills","note":"Auctioned through the BEAC to primary dealers; individuals buy through them.","sourceUrl":"https://www.beac.int/wp-content/uploads/2016/10/Courbe-des-taux-de-rendement-des-titres-publics-Camerounais-juillet-26.pdf"},"tbond_5y":{"available":true,"localName":"Obligations du Trésor assimilables (OTA)","localNameEn":"Treasury bonds","note":"Auctioned through the BEAC; 5-year yield 9.65% (July 2026).","sourceUrl":"https://www.beac.int/wp-content/uploads/2016/10/Courbe-des-taux-de-rendement-des-titres-publics-Camerounais-juillet-26.pdf"},"tbond_10y":{"available":true,"localName":"Obligations du Trésor assimilables (OTA)","localNameEn":"Treasury bonds","note":"Auctioned through the BEAC; 10-year yield 9.62% (July 2026).","sourceUrl":"https://www.beac.int/wp-content/uploads/2016/10/Courbe-des-taux-de-rendement-des-titres-publics-Camerounais-juillet-26.pdf"},"equity_fund":{"available":false,"localName":null,"localNameEn":null,"note":"No diversified retail index or mutual fund was confirmed; the regional exchange (BVMAC) lists few shares."},"gold":{"available":false,"localName":null,"localNameEn":null,"note":"No retail market for investment gold bars or coins was found."}},"institutions":{"centralBank":{"name":"Banque des Etats de l''Afrique Centrale (BEAC)","url":"https://www.beac.int/","note":"Regional central bank of the six CEMAC countries."},"insuranceRegulator":{"name":"Conférence Interafricaine des Marchés d''Assurances (CIMA), regional insurance regulator","url":"https://cima-afrique.org/"},"insuranceComplaints":{"name":"CIMA policyholder complaints (requêtes des assurés)","url":"https://cima-afrique.org/processus-de-soumission-de-requetes-2/"},"pensionScheme":{"name":"Caisse Nationale de Prévoyance Sociale (CNPS), old-age pension","url":"https://www.cnps.cm/","note":"Site did not respond when checked on 31 October 2026."},"oldAgeAllowance":null,"publicHealthCover":{"name":"Couverture Santé Universelle (CSU), Ministry of Public Health","url":"https://csu.minsante.cm/"},"depositInsurance":{"name":"Deposit Guarantee Fund of Central Africa (Fonds de Garantie des Dépôts en Afrique Centrale, FOGADAC)","url":"https://www.fogadac.com/"},"statistics":{"name":"Institut National de la Statistique (INS)","url":"https://ins-cameroun.cm/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CM', 1, 'bank_deposit_avg_rate', 0.0245, NULL, 'sourced', 'World Bank WDI, deposit interest rate (FR.INR.DPST), Cameroon', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=CM', '2018-12-31', '2.45% for 2018, the latest year published (older than 2025); in CEMAC this series follows the BEAC minimum savings rate (TCM).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CM', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap or typical credit-card rate was found; BEAC abolished the maximum lending rate in 2008.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CM', 1, 'deposit_insurance_limit', 8000000, NULL, 'sourced', 'Deposit Guarantee Fund of Central Africa (FOGADAC), FAQ', 'https://www.fogadac.com/faq', '2026-10-31', 'FOGADAC repays guaranteed deposits up to 8 million FCFA for individuals (15 million for legal persons); it covers banks in all six CEMAC countries, including Cameroon.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CM', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No industry-wide rate for a monthly recurring deposit was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CM', 1, 'equity_return_base', 0.07, NULL, 'assumption', 'BEAC yield curve, July 2026 (1-year 8.18%, about 6.8% after the 16.5% tax)', 'https://www.beac.int/wp-content/uploads/2016/10/Courbe-des-taux-de-rendement-des-titres-publics-Camerounais-juillet-26.pdf', '2026-10-31', 'Base case: the local market is thin with a weak record, so this blends a few local shares with a global index in euro-pegged CFA terms, below the after-tax one-year bill rate plus 4 points.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CM', 1, 'equity_return_high', 0.11, NULL, 'assumption', 'BEAC yield curve, July 2026 (5-year 9.65%)', 'https://www.beac.int/wp-content/uploads/2016/10/Courbe-des-taux-de-rendement-des-titres-publics-Camerounais-juillet-26.pdf', '2026-10-31', 'High case: about the 5-year Treasury yield plus a modest premium.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CM', 1, 'equity_return_low', 0.02, NULL, 'assumption', 'BEAC yield curve, July 2026; regional exchange (BVMAC) with few listings', 'https://www.beac.int/wp-content/uploads/2016/10/Courbe-des-taux-de-rendement-des-titres-publics-Camerounais-juillet-26.pdf', '2026-10-31', 'Low case: the regional exchange has few listed shares and a short record, so shares may only match deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CM', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical 1-year term-deposit rate for Cameroon was found; BEAC''s credit-cost bulletins stop in 2022.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CM', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical 3-month term-deposit rate for Cameroon was found; deposit rates other than the savings minimum are set freely since 2008 (BEAC).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CM', 1, 'fixed_income_return_base', 0.05, NULL, 'assumption', 'BEAC yield curve, July 2026 (1-year 8.18%); PwC 16.5% tax on investment income', 'https://www.beac.int/wp-content/uploads/2016/10/Courbe-des-taux-de-rendement-des-titres-publics-Camerounais-juillet-26.pdf', '2026-10-31', 'Base case: a mix of savings, term deposits and public bond offerings, below the after-tax one-year bill rate (about 6.8%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CM', 1, 'fixed_income_return_high', 0.07, NULL, 'assumption', 'BEAC yield curve, July 2026 (5-year 9.65%)', 'https://www.beac.int/wp-content/uploads/2016/10/Courbe-des-taux-de-rendement-des-titres-publics-Camerounais-juillet-26.pdf', '2026-10-31', 'High case: government bonds near 9.6% less tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CM', 1, 'fixed_income_return_low', 0.02, NULL, 'assumption', 'BEAC minimum savings rate (TCM) 2.45%, taxed at 16.5% (PwC)', 'https://www.beac.int/wp-content/uploads/2018/11/Rapport-sur-La-Politique-Mon%C3%A9taire-de-la-BEAC_Sept-2026_vf_new2_Publiable.pdf', '2026-10-31', 'Low case: passbook savings at about the regulated minimum, after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CM', 1, 'goal_inflation_education', 0.035, NULL, 'assumption', 'INS consumer price note, July 2026: education index 107.3 (base 2022=100)', 'https://ins-cameroun.cm/wp-content/uploads/2026/08/Note-sur-les-prix-au-Cameroun-en-juillet-2026.pdf', '2026-10-31', 'The education index has risen about 1.8% a year since 2022 (1.0% in the year to July 2026); education costs are planned at the 3.5% general assumption to allow for private fees.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CM', 1, 'goal_inflation_health', 0.04, NULL, 'assumption', 'INS consumer price note, July 2026: health index 102.4 (base 2022=100)', 'https://ins-cameroun.cm/wp-content/uploads/2026/08/Note-sur-les-prix-au-Cameroun-en-juillet-2026.pdf', '2026-10-31', 'The health price index has risen only about 0.6% a year since 2022, but it tracks public tariffs and medicines; private care costs are planned at 4%, a little above the 3.5% general assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CM', 1, 'gold_return_base', 0.045, NULL, 'assumption', 'CFA franc-euro peg; Trading Economics USD/XAF', 'https://tradingeconomics.com/cameroon/currency', '2026-10-31', 'Base case: long-run dollar gold trend of about 4-5% a year with the euro peg holding.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CM', 1, 'gold_return_high', 0.09, NULL, 'assumption', 'CFA franc-euro peg; Trading Economics USD/XAF', 'https://tradingeconomics.com/cameroon/currency', '2026-10-31', 'High case: strong gold prices as in 2019-2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CM', 1, 'gold_return_low', 0, NULL, 'assumption', 'CFA franc-euro peg; Trading Economics USD/XAF', 'https://tradingeconomics.com/cameroon/currency', '2026-10-31', 'Low case: flat gold in euro terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CM', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Labour Code provides a dismissal indemnity, but no official text giving a statutory end-of-service or retirement gratuity for private employees could be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CM', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a major private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CM', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premiums per 100,000 FCFA of cover were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CM', 1, 'inflation_cpi', 0.034, NULL, 'sourced', 'Institut National de la Statistique (INS), monthly consumer price note, July 2026', 'https://ins-cameroun.cm/statistique/inflation-les-prix-repartent-a-la-hausse-en-juillet-2026/', '2026-07-31', 'Consumer prices up 3.4% year on year in July 2026 (3.0% in June, 2.7% in May); 12-month average 2.6%, below the CEMAC 3% convergence norm. Latest INS release found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CM', 1, 'inflation_projection', 0.035, NULL, 'assumption', 'BEAC monetary policy committee, 28 September 2026 (CEMAC inflation norm 3%); World Bank CPI inflation 2021-2025', 'https://www.beac.int/wp-content/uploads/2016/10/COMMUNIQUE-DE-PRESSE-CPM-DU-28-SEPTEMBRE-2026.pdf', '2026-10-31', 'The CFA franc is pegged to the euro and the CEMAC norm is 3% (BEAC forecasts 2.9% for Cameroon in 2026), but inflation averaged about 5% over 2021-2025, so 3.5% a year is used for long-range plans.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CM', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published term-life premium rates per 1,000 FCFA of cover were found from CIMA or another public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CM', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No industry-wide life claim settlement ratio for Cameroon was found in CIMA''s public pages.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CM', 1, 'life_expectancy', 64, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN)', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=CM', '2024-12-31', '64.0 years in 2024 (men 61.8, women 66.2).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CM', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":16.5,"men":15.6,"women":17.4},{"age":65,"total":13.2,"men":12.4,"women":13.8},{"age":70,"total":10.1,"men":9.6,"women":10.6},{"age":80,"total":5.7,"men":5.5,"women":5.8}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/cameroon/', '2026-07-01', 'Secondary source of UN WPP 2024 (medium variant) for 2026; totals at 60, 70 and 80 are the mean of men and women (only the 65 total, 13.2, is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CM', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension eligibility rules were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CM', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension was found; CLEISS describes only the contributory CNPS scheme, including voluntary insurance for informal workers.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CM', 1, 'oop_health_share', 0.6765, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=CM', '2023-12-31', '67.7% in 2023 (latest year; older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CM', 1, 'policy_rate', 0.045, NULL, 'sourced', 'Banque des Etats de l''Afrique Centrale (BEAC), monetary policy committee press release, 28 September 2026', 'https://www.beac.int/wp-content/uploads/2016/10/COMMUNIQUE-DE-PRESSE-CPM-DU-28-SEPTEMBRE-2026.pdf', '2026-09-28', 'Tender rate (taux d''intérêt des appels d''offres) held at 4.50% after a cut from 4.75% on 29 June 2026; marginal lending facility 5.75%, deposit facility 0%. BEAC sets rates for all six CEMAC countries.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CM', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":60,"inflationLinked":false,"taxFree":null}', 'sourced', 'CLEISS (French social security liaison body), the Cameroon social security system: CNPS old-age pension', 'https://www.cleiss.fr/docs/regimes/regime_cameroun.html', '2024-06-30', 'Compulsory CNPS pension for private employees: 30% of average monthly earnings (best of last 3 or 5 years) plus 1% per 12 months beyond 180 months, between 50% of the minimum wage and 80% of earnings; lump sum (allocation de vieillesse) if fewer than 180 months. No automatic indexation is described. Source is 2024 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CM', 1, 'retirement_accumulation_return_base', 0.055, NULL, 'assumption', 'BEAC yield curve, July 2026; equity base 7%', 'https://www.beac.int/wp-content/uploads/2016/10/Courbe-des-taux-de-rendement-des-titres-publics-Camerounais-juillet-26.pdf', '2026-10-31', 'Base case: a balanced mix of fixed income (5%) and shares (7%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CM', 1, 'retirement_accumulation_return_high', 0.08, NULL, 'assumption', 'BEAC yield curve, July 2026 (5-year 9.65%)', 'https://www.beac.int/wp-content/uploads/2016/10/Courbe-des-taux-de-rendement-des-titres-publics-Camerounais-juillet-26.pdf', '2026-10-31', 'High case: more government bonds and shares in a good decade.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CM', 1, 'retirement_accumulation_return_low', 0.03, NULL, 'assumption', 'BEAC yield curve, July 2026', 'https://www.beac.int/wp-content/uploads/2016/10/Courbe-des-taux-de-rendement-des-titres-publics-Camerounais-juillet-26.pdf', '2026-10-31', 'Low case: mostly savings with a small share of shares.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CM', 1, 'retirement_age_default', 60, NULL, 'sourced', 'CLEISS (French social security liaison body), the Cameroon social security system: CNPS old-age pension', 'https://www.cleiss.fr/docs/regimes/regime_cameroun.html', '2024-06-30', 'Pension at 60 with 20 years of registration and 180 months of insurance; early pension from 50 for premature wear or by agreement. Source describes the 2024 rules (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CM', 1, 'retirement_age_government', 60, NULL, 'sourced', 'Presidency of the Republic of Cameroon, news: retirement age of civil servants harmonised', 'https://www.prc.cm/en/news/4826-president-paul-biya-harmonises-retirement-age-of-civil-servants', '2020-12-31', 'Civil servants of categories A and B retire at 60 and categories C and D at 55 under the 2020 harmonisation decree (older than 2025; no later change found).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CM', 1, 'retirement_return_base', 0.05, NULL, 'assumption', 'BEAC yield curve, July 2026 (1-year Treasury bill 8.18%, about 6.8% after the 16.5% tax)', 'https://www.beac.int/wp-content/uploads/2016/10/Courbe-des-taux-de-rendement-des-titres-publics-Camerounais-juillet-26.pdf', '2026-10-31', 'Base case: safe instruments (savings, term deposits, public bond offerings) below the after-tax one-year bill rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CM', 1, 'retirement_return_high', 0.065, NULL, 'assumption', 'BEAC yield curve, July 2026 (1-year Treasury bill 8.18%)', 'https://www.beac.int/wp-content/uploads/2016/10/Courbe-des-taux-de-rendement-des-titres-publics-Camerounais-juillet-26.pdf', '2026-10-31', 'High case: close to the one-year bill rate after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CM', 1, 'retirement_return_low', 0.02, NULL, 'assumption', 'BEAC minimum savings rate (TCM) 2.45%, taxed at 16.5% (PwC)', 'https://www.beac.int/wp-content/uploads/2018/11/Rapport-sur-La-Politique-Mon%C3%A9taire-de-la-BEAC_Sept-2026_vf_new2_Publiable.pdf', '2026-10-31', 'Low case: passbook savings after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CM', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The State sells bonds to the public through public offerings (emprunts obligataires) listed on the regional exchange, but the current coupon could not be read (the exchange''s bond page needs scripts).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CM', 1, 'savings_account_rate', 0.0245, NULL, 'sourced', 'BEAC Monetary Policy Report, September 2026, annex: Taux Créditeur Minimum (TCM)', 'https://www.beac.int/wp-content/uploads/2018/11/Rapport-sur-La-Politique-Mon%C3%A9taire-de-la-BEAC_Sept-2026_vf_new2_Publiable.pdf', '2026-09-30', 'Minimum rate banks in CEMAC must pay on passbook savings of individuals up to 5 million FCFA, 2.45%, unchanged since 8 July 2014; banks usually pay this floor.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CM', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":19.9},{"year":2040,"value":16.7},{"year":2065,"value":9.7}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/cameroon/2040/', '2025-12-31', '100 / old-age dependency ratio: 5.03 (2025, World Bank), 6.0 (2040) and 10.3 (2065, populationpyramid.net/cameroon/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CM', 1, 'tax_bank_interest', 0.165, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Cameroon, individual income determination (income from stocks and shares)', 'https://taxsummaries.pwc.com/republic-of-cameroon/individual/income-determination', '2026-08-14', 'Income from deposits, current accounts and other investment income is taxed at an overall 16.5% (15% plus additional council tax); page last reviewed 14 August 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CM', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'The tax treatment of interest on public bond offerings and Treasury securities for individuals could not be confirmed from an official source; PwC gives the general 16.5% on investment income without mentioning government securities.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CM', 1, 'tbill_91d_rate', 0.0628, NULL, 'sourced', 'BEAC, yield curve of Cameroonian government securities, July 2026, 3 months', 'https://www.beac.int/wp-content/uploads/2016/10/Courbe-des-taux-de-rendement-des-titres-publics-Camerounais-juillet-26.pdf', '2026-07-31', '3-month yield 6.28% (6 months 7.09%, 1 year 8.18%) on Treasury bills (BTA) auctioned through the BEAC.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CM', 1, 'tbond_10y_rate', 0.0962, NULL, 'sourced', 'BEAC, yield curve of Cameroonian government securities, July 2026, 10 years', 'https://www.beac.int/wp-content/uploads/2016/10/Courbe-des-taux-de-rendement-des-titres-publics-Camerounais-juillet-26.pdf', '2026-07-31', '10-year yield 9.62% on Treasury bonds (OTA).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CM', 1, 'tbond_5y_rate', 0.0965, NULL, 'sourced', 'BEAC, yield curve of Cameroonian government securities, July 2026, 5 years', 'https://www.beac.int/wp-content/uploads/2016/10/Courbe-des-taux-de-rendement-des-titres-publics-Camerounais-juillet-26.pdf', '2026-07-31', '5-year yield 9.65% on Treasury bonds (OTA); the curve is flat at about 9.6% from 3 to 15 years.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('CN', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"CN","iso3":"CHN","nameEn":"China","nameNative":"中国","region":"east_asia_pacific","languages":["zh"],"currency":{"code":"CNY","symbol":"¥","decimals":2,"compact":"intl","usdRate":{"value":6.7138,"status":"sourced","sourceName":"State Administration of Foreign Exchange, RMB central parity rate (CFETS)","sourceUrl":"https://www.safe.gov.cn/AppStructured/hlw/RMBQuery.do","asOf":"2026-10-30","note":"Central parity 671.38 yuan per 100 US dollars."}},"instruments":{"savings_account":{"available":true,"localName":"活期存款","localNameEn":"Demand deposit","sourceUrl":null},"fdr_3m":{"available":true,"localName":"整存整取定期存款","localNameEn":"Lump-sum fixed deposit","sourceUrl":null},"fdr_1y":{"available":true,"localName":"整存整取定期存款","localNameEn":"Lump-sum fixed deposit","sourceUrl":null},"dps":{"available":true,"localName":"零存整取","localNameEn":"Installment deposit","sourceUrl":null},"sanchayapatra_5y":{"available":true,"localName":"储蓄国债","localNameEn":"Savings treasury bonds","note":"3- and 5-year savings bonds (certificate and electronic) sold to individuals through banks; not tradable."},"tbill_91d":{"available":true,"localName":"记账式国债","localNameEn":"Book-entry treasury bonds","note":"Short-term government bills can be bought by individuals through bank counters or the stock exchanges."},"tbond_5y":{"available":true,"localName":"记账式国债","localNameEn":"Book-entry treasury bonds","note":"Bought through bank counters or the stock exchanges.","sourceUrl":"https://tradingeconomics.com/china/government-bond-yield"},"tbond_10y":{"available":true,"localName":"记账式国债","localNameEn":"Book-entry treasury bonds","note":"Bought through bank counters or the stock exchanges.","sourceUrl":"https://tradingeconomics.com/china/government-bond-yield"},"equity_fund":{"available":true,"localName":"指数基金","localNameEn":"Index fund","note":"Public mutual funds and index funds tracking broad A-share indices are widely available."},"gold":{"available":true,"localName":"实物黄金","localNameEn":"Physical gold","note":"Gold bars and coins are sold by banks and jewellers."}},"institutions":{"centralBank":{"name":"People''s Bank of China (PBOC)","url":"https://www.pbc.gov.cn/"},"insuranceRegulator":{"name":"National Financial Regulatory Administration (NFRA)","url":"https://www.nfra.gov.cn/"},"insuranceComplaints":{"name":"National Financial Regulatory Administration consumer protection (hotline 12378)","url":"https://www.nfra.gov.cn/"},"pensionScheme":{"name":"Ministry of Human Resources and Social Security, basic pension insurance","url":"https://www.mohrss.gov.cn/"},"oldAgeAllowance":{"name":"Ministry of Human Resources and Social Security, urban and rural residents'' basic pension","url":"https://www.mohrss.gov.cn/","note":"State-funded basic pension from age 60 within the residents'' scheme."},"publicHealthCover":{"name":"National Healthcare Security Administration (basic medical insurance)","url":"https://www.nhsa.gov.cn/"},"depositInsurance":{"name":"Deposit Insurance Fund (Deposit Insurance Regulations, State Council)","url":"https://www.gov.cn/zhengce/content/2015-03/31/content_9562.htm"},"statistics":{"name":"National Bureau of Statistics of China","url":"https://www.stats.gov.cn/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CN', 1, 'bank_deposit_avg_rate', 0.015, NULL, 'sourced', 'World Bank WDI, deposit interest rate (FR.INR.DPST)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=CN', '2024-12-31', 'This series is the PBOC 1-year benchmark deposit rate (unchanged since 2015), not a weighted average; large banks'' listed 1-year rate is about 0.95%. Figure refers to 2024, older than 2025; it is the latest World Bank value.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CN', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'PBOC removed the credit card rate band from 2021 and rates are market-set; we could not read a current source for a cap or typical rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CN', 1, 'deposit_insurance_limit', 500000, NULL, 'sourced', 'Deposit Insurance Regulations (State Council, 2015), Article 5', 'https://www.gov.cn/zhengce/content/2015-03/31/content_9562.htm', '2015-05-01', 'Up to 500,000 yuan per depositor per insured bank, principal and interest combined. The regulations date from 2015 (older than 2025) and the limit is unchanged.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CN', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'PBOC publishes only the 2015 benchmark rates; actual listed rates (large state banks, table of 20 May 2025, still current in Oct 2026: 5-year installment (零存整取) deposits, 0.85%) were found only on banks'' own pages, which we do not cite.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CN', 1, 'equity_return_base', 0.045, NULL, 'assumption', '52-week government bill 1.22% and 1-year deposits about 0.95% plus a capped premium; CSI 300 10-year record', 'https://tradingeconomics.com/china/government-bond-yield', '2026-10-31', 'Base set about 3.3 points above the untaxed 52-week government bill yield, below the 4-point limit, because the local index record is weak.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CN', 1, 'equity_return_high', 0.08, NULL, 'assumption', 'Long-run A-share and global equity returns in CNY', 'https://tradingeconomics.com/china/government-bond-yield', '2026-10-31', 'High case if earnings growth and valuations recover.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CN', 1, 'equity_return_low', 0, NULL, 'assumption', 'CSI 300 10-year record; CNY safe rates', 'https://tradingeconomics.com/china/government-bond-yield', '2026-10-31', 'The main A-share index has had a weak, volatile decade, so the low case is zero.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CN', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'PBOC publishes only the 2015 benchmark rates; actual listed rates (large state banks, table of 20 May 2025, still current in Oct 2026: 1-year lump-sum fixed deposits, 0.95%) were found only on banks'' own pages, which we do not cite.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CN', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'PBOC publishes only the 2015 benchmark rates; actual listed rates (large state banks, table of 20 May 2025, still current in Oct 2026: 3-month lump-sum fixed deposits, 0.65%) were found only on banks'' own pages, which we do not cite.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CN', 1, 'fixed_income_return_base', 0.012, NULL, 'assumption', 'Government bond yields (Trading Economics); large-bank listed deposit rates', 'https://tradingeconomics.com/china/government-bond-yield', '2026-10-31', 'Base case between 1-year deposits (0.95%) and 3-year deposits / 5-year bonds (1.25-1.37%). Safe CNY rates: 52-week government bill 1.22%, 5-year bond 1.37%, 10-year 1.66% (30 Oct 2026); large-bank listed deposit rates about 0.95% (1 year) and 1.25% (3 years); deposit and government bond interest are exempt from income tax (PwC).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CN', 1, 'fixed_income_return_high', 0.0166, NULL, 'assumption', 'Government bond yields (Trading Economics)', 'https://tradingeconomics.com/china/government-bond-yield', '2026-10-31', 'High case at the 10-year government bond yield. Safe CNY rates: 52-week government bill 1.22%, 5-year bond 1.37%, 10-year 1.66% (30 Oct 2026); large-bank listed deposit rates about 0.95% (1 year) and 1.25% (3 years); deposit and government bond interest are exempt from income tax (PwC).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CN', 1, 'fixed_income_return_low', 0.0065, NULL, 'assumption', 'Government bond yields (Trading Economics); large-bank listed deposit rates', 'https://tradingeconomics.com/china/government-bond-yield', '2026-10-31', 'Low case at the 3-month deposit rate. Safe CNY rates: 52-week government bill 1.22%, 5-year bond 1.37%, 10-year 1.66% (30 Oct 2026); large-bank listed deposit rates about 0.95% (1 year) and 1.25% (3 years); deposit and government bond interest are exempt from income tax (PwC).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CN', 1, 'goal_inflation_education', 0.025, NULL, 'assumption', 'NBS CPI education services (+0.4% y/y) and education, culture and recreation (+1.4%), Sep 2026', 'https://www.stats.gov.cn/english/PressRelease/202610/t20261015_1965500.html', '2026-10-31', 'Measured education CPI is low, but private tutoring, higher education and study abroad costs rise faster, so we plan with 2.5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CN', 1, 'goal_inflation_health', 0.03, NULL, 'assumption', 'NBS CPI health care sub-index (+2.7% y/y, Sep 2026)', 'https://www.stats.gov.cn/english/PressRelease/202610/t20261015_1965500.html', '2026-10-31', 'Medical prices run about 2 points above headline CPI, so we plan with 3%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CN', 1, 'gold_return_base', 0.045, NULL, 'assumption', 'US-dollar gold trend; CNY/USD central parity (SAFE)', 'https://www.safe.gov.cn/AppStructured/hlw/RMBQuery.do', '2026-10-31', 'Long-run dollar gold trend of about 5% less a little for yuan appreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CN', 1, 'gold_return_high', 0.08, NULL, 'assumption', 'US-dollar gold trend; CNY/USD central parity (SAFE)', 'https://www.safe.gov.cn/AppStructured/hlw/RMBQuery.do', '2026-10-31', 'High case for a strong gold cycle.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CN', 1, 'gold_return_low', 0, NULL, 'assumption', 'US-dollar gold trend; CNY/USD central parity (SAFE)', 'https://www.safe.gov.cn/AppStructured/hlw/RMBQuery.do', '2026-10-31', 'Gold can stall for a decade and the yuan has been strengthening against the dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CN', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'China has no statutory retirement gratuity; Labour Contract Law severance (one month''s pay per year of service) applies to dismissals and contract ends, not to retirement.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CN', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'NHSA publishes average inpatient costs per stay but not out-of-pocket cost at private or mid-range hospitals; not found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CN', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No regulator or credible guide with private medical insurance premiums per 100,000 yuan found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CN', 1, 'inflation_cpi', 0.009, NULL, 'sourced', 'National Bureau of Statistics of China, Consumer Price Index in September 2026', 'https://www.stats.gov.cn/english/PressRelease/202610/t20261015_1965500.html', '2026-09-30', 'CPI rose 0.9% year on year (health care +2.7%, education services +0.4%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CN', 1, 'inflation_projection', 0.015, NULL, 'assumption', 'Government CPI target of around 2%; 5-year CPI average below 1% (NBS)', 'https://www.stats.gov.cn/english/PressRelease/202610/t20261015_1965500.html', '2026-10-31', 'CPI has run well below the official target of around 2% for several years, so we plan with 1.5%, between the recent average and the target.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CN', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life (定期寿险) is widely sold, but we could not read a credible published premium guide or regulator data in this research run.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CN', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'NFRA publishes insurer complaint and premium data but we found no industry-wide life claim settlement ratio.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CN', 1, 'life_expectancy', 78, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN)', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=CN', '2024-12-31', 'Men 75.2, women 81.0 (2024). Figure refers to 2024, older than 2025; it is the latest available.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CN', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":22.4,"men":20.4,"women":24.3},{"age":65,"total":18.3,"men":16.5,"women":20},{"age":70,"total":14.6,"men":13,"women":15.9},{"age":80,"total":8.1,"men":7.2,"women":8.9}]}', 'sourced', 'UN World Population Prospects (via georank.org)', 'https://georank.org/life-expectancy/china', '2026-07-08', 'Remaining years derived from expected age at death by current age; secondary source because the WHO GHO API was unavailable.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CN', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'Residents'' basic pension is paid from age 60 after 15 years of contributions; we could not read an official source on means testing and current rules.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CN', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'The urban and rural residents'' basic pension pays a state-funded minimum basic pension from age 60, but we could not read an official source for the current national minimum amount.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CN', 1, 'oop_health_share', 0.3217, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure, SH.XPD.OOPC.CH.ZS)', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=CN', '2023-12-31', 'Figure refers to 2023, older than 2025; it is the latest available.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CN', 1, 'policy_rate', 0.014, NULL, 'sourced', 'People''s Bank of China 7-day reverse repo rate (via Trading Economics)', 'https://tradingeconomics.com/china/interest-rate', '2026-09-30', 'The 7-day reverse repo is the PBOC''s main policy rate; 1-year LPR 3.0%, 5-year LPR 3.5% (20 Oct 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CN', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":63,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'NPC Standing Committee decision on gradually raising the statutory retirement age (13 Sep 2024), via Xinhua', 'https://www.news.cn/politics/20240913/d4d0e417c4204f18a6e0173c45373363/c.html', '2024-09-13', 'Urban employees'' basic pension: men''s pension age rising from 60 to 63 (women 50/55 to 55/58); minimum contribution years rise from 15 to 20 from 2030 (6 months a year). Pensions are raised yearly by government decision, not indexed by law. Figure refers to 2024, older than 2025; it is the latest available.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CN', 1, 'retirement_accumulation_return_base', 0.03, NULL, 'assumption', 'Mix of CNY deposits/bonds and equity', 'https://tradingeconomics.com/china/government-bond-yield', '2026-10-31', 'About half equity at 4.5% and half deposits/bonds near 1.2%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CN', 1, 'retirement_accumulation_return_high', 0.05, NULL, 'assumption', 'Mix of CNY deposits/bonds and equity', 'https://tradingeconomics.com/china/government-bond-yield', '2026-10-31', 'About 60% equity at the high case and 40% government bonds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CN', 1, 'retirement_accumulation_return_low', 0.01, NULL, 'assumption', 'Mix of CNY deposits/bonds and equity', 'https://tradingeconomics.com/china/government-bond-yield', '2026-10-31', 'About 40% equity at the low case and 60% deposits and bonds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CN', 1, 'retirement_age_default', 63, NULL, 'sourced', 'NPC Standing Committee decision on gradually raising the statutory retirement age (13 Sep 2024), via Xinhua', 'https://www.news.cn/politics/20240913/d4d0e417c4204f18a6e0173c45373363/c.html', '2024-09-13', 'From 1 Jan 2025 men''s statutory age rises from 60 to 63 over 15 years (1 month every 4 months; full for men born from Sep 1976); women''s from 50/55 to 55/58. Up to 3 years earlier or later is allowed. Figure refers to 2024, older than 2025; it is the latest available.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CN', 1, 'retirement_age_government', 63, NULL, 'sourced', 'NPC Standing Committee decision on gradually raising the statutory retirement age (13 Sep 2024), via Xinhua', 'https://www.news.cn/politics/20240913/d4d0e417c4204f18a6e0173c45373363/c.html', '2024-09-13', 'Same national statutory ages apply to civil servants: men 60 rising to 63, women cadres 55 rising to 58. Figure refers to 2024, older than 2025; it is the latest available.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CN', 1, 'retirement_return_base', 0.0095, NULL, 'assumption', 'Government bond yields (Trading Economics); large-bank listed deposit rates', 'https://tradingeconomics.com/china/government-bond-yield', '2026-10-31', 'Base case at about the untaxed 1-year deposit rate (0.95%), below the 52-week government bill yield (1.22%). Safe CNY rates: 52-week government bill 1.22%, 5-year bond 1.37%, 10-year 1.66% (30 Oct 2026); large-bank listed deposit rates about 0.95% (1 year) and 1.25% (3 years); deposit and government bond interest are exempt from income tax (PwC).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CN', 1, 'retirement_return_high', 0.0166, NULL, 'assumption', 'Government bond yields (Trading Economics)', 'https://tradingeconomics.com/china/government-bond-yield', '2026-10-31', 'High case at the 10-year government bond yield. Safe CNY rates: 52-week government bill 1.22%, 5-year bond 1.37%, 10-year 1.66% (30 Oct 2026); large-bank listed deposit rates about 0.95% (1 year) and 1.25% (3 years); deposit and government bond interest are exempt from income tax (PwC).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CN', 1, 'retirement_return_low', 0.0065, NULL, 'assumption', 'Government bond yields (Trading Economics); large-bank listed deposit rates', 'https://tradingeconomics.com/china/government-bond-yield', '2026-10-31', 'Low case at the 3-month deposit rate. Safe CNY rates: 52-week government bill 1.22%, 5-year bond 1.37%, 10-year 1.66% (30 Oct 2026); large-bank listed deposit rates about 0.95% (1 year) and 1.25% (3 years); deposit and government bond interest are exempt from income tax (PwC).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CN', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Savings treasury bonds (储蓄国债, 3- and 5-year) are sold to individuals, but the Ministry of Finance announcement pages were unreachable and we found no 2026 rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CN', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'PBOC publishes only the 2015 benchmark rates; actual listed rates (large state banks, table of 20 May 2025, still current in Oct 2026: demand (savings) deposits, 0.05%) were found only on banks'' own pages, which we do not cite.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CN', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":4.7},{"year":2040,"value":2.4},{"year":2065,"value":1.4}]}', 'sourced', 'UN World Population Prospects 2024, medium variant (via populationpyramid.net); World Bank SP.POP.DPND.OL', 'https://www.populationpyramid.net/china/2040/', '2024-07-31', '100 / old-age dependency ratio: 21.4 in 2025 (World Bank), 41.6 in 2040 and 72.2 in 2065 (UN WPP 2024). Figure refers to 2024, older than 2025; it is the latest available.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CN', 1, 'tax_bank_interest', 0, NULL, 'sourced', 'PwC Worldwide Tax Summaries, China: other tax credits and incentives', 'https://taxsummaries.pwc.com/peoples-republic-of-china/individual/other-tax-credits-and-incentives', '2026-07-22', 'Bank deposit interest income is currently exempt from individual income tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CN', 1, 'tax_sanchayapatra_profit', 0, NULL, 'sourced', 'PwC Worldwide Tax Summaries, China: other tax credits and incentives', 'https://taxsummaries.pwc.com/peoples-republic-of-china/individual/other-tax-credits-and-incentives', '2026-07-22', 'Interest on government bonds (including savings treasury bonds) is exempt from individual income tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CN', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 3-month government bill yield could be read; the shortest tenor found was the 52-week yield, 1.22% on 30 Oct 2026 (Trading Economics).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CN', 1, 'tbond_10y_rate', 0.0166, NULL, 'sourced', 'China 10-year government bond yield (via Trading Economics)', 'https://tradingeconomics.com/china/government-bond-yield', '2026-10-30', '1.6551% on 30 Oct 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CN', 1, 'tbond_5y_rate', 0.0137, NULL, 'sourced', 'China 5-year government bond yield (via Trading Economics)', 'https://tradingeconomics.com/china/government-bond-yield', '2026-10-30', NULL, 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('CO', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"CO","iso3":"COL","nameEn":"Colombia","nameNative":"Colombia","region":"latin_america_caribbean","languages":["es","en"],"currency":{"code":"COP","symbol":"$","decimals":2,"compact":"intl","usdRate":{"value":3182.99,"status":"sourced","sourceName":"Superintendencia Financiera de Colombia, Tasa Representativa del Mercado (TRM), datos.gov.co dataset 32sa-8pi3","sourceUrl":"https://www.datos.gov.co/resource/32sa-8pi3.json","asOf":"2026-10-31","note":"Official TRM of COP 3,182.99 per US dollar valid from 31 October 2026 (3,166.91 on 30 October); World Bank 2025 average 4,053, so the peso has strengthened sharply in 2026."}},"instruments":{"savings_account":{"available":true,"localName":"Cuenta de ahorros","localNameEn":"Savings account","note":"Pays very little interest; withdrawals above a monthly exempt amount pay the 0.4% financial transactions tax.","sourceUrl":"https://www.datos.gov.co/resource/axk9-g2nh.json"},"fdr_3m":{"available":true,"localName":"CDT (Certificado de Depósito a Término)","localNameEn":"Term deposit certificate (CDT), 90 days","note":"Covered by Fogafín up to COP 50 million.","sourceUrl":"https://www.datos.gov.co/resource/axk9-g2nh.json"},"fdr_1y":{"available":true,"localName":"CDT (Certificado de Depósito a Término)","localNameEn":"Term deposit certificate (CDT), 360 days","sourceUrl":"https://www.datos.gov.co/resource/axk9-g2nh.json"},"dps":{"available":false,"localName":null,"localNameEn":"Recurring deposit","note":"No standard monthly recurring-deposit product with published rates."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":"Government savings certificate","note":"No retail government savings certificate; TES are bought through brokers or funds."},"tbill_91d":{"available":true,"localName":"TES de corto plazo (TCO)","localNameEn":"Short-term Treasury securities (TCO)","note":"Issued for terms up to one year; individuals buy them through brokers. No current yield could be read."},"tbond_5y":{"available":true,"localName":"TES (Títulos de Tesorería)","localNameEn":"Treasury bonds (TES), 5 years","note":"Peso fixed-rate and UVR-indexed TES; bought through brokers or bond funds."},"tbond_10y":{"available":true,"localName":"TES (Títulos de Tesorería)","localNameEn":"Treasury bonds (TES), 10 years","sourceUrl":"https://tradingeconomics.com/colombia/government-bond-yield"},"equity_fund":{"available":true,"localName":"Fondo de inversión colectiva / ETF","localNameEn":"Collective investment fund or index fund (ETF)","note":"Collective investment funds and ETFs on the Colombian and global markets are available to retail investors; voluntary pension funds carry tax relief."},"gold":{"available":true,"localName":"Oro físico (lingotes y monedas)","localNameEn":"Physical gold bars and coins","note":"Buying physical gold is legal."}},"institutions":{"centralBank":{"name":"Banco de la República","url":"https://www.banrep.gov.co/"},"insuranceRegulator":{"name":"Superintendencia Financiera de Colombia","url":"https://www.superfinanciera.gov.co/"},"insuranceComplaints":{"name":"Superintendencia Financiera de Colombia (consumer complaints) and each insurer''s Defensor del Consumidor Financiero","url":"https://www.superfinanciera.gov.co/","note":"Complain to the insurer or its financial consumer ombudsman first, then to the Superintendencia Financiera."},"pensionScheme":{"name":"Colpensiones (public pension administrator)","url":"https://www.colpensiones.gov.co/"},"oldAgeAllowance":{"name":"Colombia Mayor, Departamento Administrativo para la Prosperidad Social","url":"https://prosperidadsocial.gov.co/"},"publicHealthCover":{"name":"Sistema General de Seguridad Social en Salud, Ministerio de Salud y Protección Social","url":"https://www.minsalud.gov.co/"},"depositInsurance":{"name":"Fondo de Garantías de Instituciones Financieras (Fogafín)","url":"https://www.fogafin.gov.co/que-es-el-seguro-de-depositos"},"statistics":{"name":"Departamento Administrativo Nacional de Estadística (DANE)","url":"https://www.dane.gov.co/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CO', 1, 'bank_deposit_avg_rate', 0.0896, NULL, 'sourced', 'World Bank WDI FR.INR.DPST (deposit interest rate)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=CO', '2025-12-31', '8.96% for 2025 (10.17% in 2024); today''s CDT rates are higher (90-day 10.7%, 360-day 12.7%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CO', 1, 'credit_card_rate_cap', 0.2859, NULL, 'sourced', 'Superintendencia Financiera de Colombia, certified bank current interest rate (TIBC) for consumer and ordinary credit, Resolution 1472 of 2026 (datos.gov.co pare-7x5i)', 'https://www.datos.gov.co/resource/pare-7x5i.json?modalidad=CONSUMO%20Y%20ORDINARIO', '2026-10-01', 'The usury cap is 1.5 times the certified current rate: TIBC 19.06% for October 2026, so cards may charge at most about 28.59% effective annual (TIBC 18.89% certified for November 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CO', 1, 'deposit_insurance_limit', 50000000, NULL, 'sourced', 'Fogafín, ¿Qué es el Seguro de Depósitos?', 'https://www.fogafin.gov.co/que-es-el-seguro-de-depositos', '2026-10-31', 'Fogafín''s deposit insurance repays depositors up to COP 50 million per person per failed institution (banks, financial corporations, finance companies and electronic payment companies).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CO', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No standard monthly recurring-deposit product with a published average rate was found for Colombia; programmed-savings accounts exist but their rates are not reported separately to the Superintendencia Financiera.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CO', 1, 'equity_return_base', 0.11, NULL, 'assumption', 'COLCAP history (Trading Economics); 360-day CDT 12.65% less 19% tax = 10.2%', 'https://tradingeconomics.com/colombia/stock-market', '2026-10-31', 'Base case kept close to the after-tax safe rate because the COLCAP''s 10-year record is weak despite the 2025-26 rally; well under the safe rate plus 4 points.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CO', 1, 'equity_return_high', 0.15, NULL, 'assumption', 'COLCAP record high in September 2026 (Trading Economics)', 'https://tradingeconomics.com/colombia/stock-market', '2026-10-31', 'High case: Colombian and global shares earn a real equity premium as interest rates fall.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CO', 1, 'equity_return_low', 0.06, NULL, 'assumption', 'COLCAP index 2,490.92 on 30 Oct 2026, up 25% in a year, record 2,627 in September 2026 (Trading Economics)', 'https://tradingeconomics.com/colombia/stock-market', '2026-10-31', 'Low case: Colombian shares fall back to their weak 2015-2023 record and earn less than CDTs.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CO', 1, 'fdr_1y_rate', 0.1265, NULL, 'sourced', 'Superintendencia Financiera de Colombia, daily deposit rates by entity (datos.gov.co dataset axk9-g2nh): banks, CDT issues at 360 days', 'https://www.datos.gov.co/resource/axk9-g2nh.json', '2026-10-28', 'Amount-weighted average rate on new 360-day CDTs at banks was 12.65% effective annual over 22-28 October 2026 (180 days: 11.34%; over 360 days: 12.86%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CO', 1, 'fdr_3m_rate', 0.1069, NULL, 'sourced', 'Superintendencia Financiera de Colombia, daily deposit rates by entity (datos.gov.co dataset axk9-g2nh): banks, CDT issues at 90 days', 'https://www.datos.gov.co/resource/axk9-g2nh.json', '2026-10-28', 'Amount-weighted average rate on new 90-day CDTs at banks was 10.69% effective annual over 22-28 October 2026 (10.86% on 28 October); computed by us across all reporting banks.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CO', 1, 'fixed_income_return_base', 0.09, NULL, 'assumption', '360-day CDT 12.65% (Superintendencia Financiera) less tax, allowing for lower rates later', 'https://www.datos.gov.co/resource/axk9-g2nh.json', '2026-10-31', 'Base case: 1-year CDTs after tax, allowing for interest rates to fall as inflation returns towards target.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CO', 1, 'fixed_income_return_high', 0.105, NULL, 'assumption', '10-year TES 13.03% less 19% tax = 10.6% (Trading Economics)', 'https://tradingeconomics.com/colombia/government-bond-yield', '2026-10-31', 'High case: locking in today''s long TES yields and holding to maturity.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CO', 1, 'fixed_income_return_low', 0.075, NULL, 'assumption', '90-day CDT 10.69% (Superintendencia Financiera) less tax', 'https://www.datos.gov.co/resource/axk9-g2nh.json', '2026-10-31', 'Low case: short CDTs after tax, with the policy rate cut back towards neutral.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CO', 1, 'goal_inflation_education', 0.065, NULL, 'assumption', 'DANE, IPC September 2026: Educación division up 7.49% over 12 months', 'https://www.dane.gov.co/files/operaciones/IPC/sep2026/bol-IPC-sep2026.pdf', '2026-10-31', 'Education prices rose 7.49% against 6.29% for all items; planning uses 6.5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CO', 1, 'goal_inflation_health', 0.065, NULL, 'assumption', 'DANE, IPC September 2026: Salud division up 7.79% over 12 months', 'https://www.dane.gov.co/files/operaciones/IPC/sep2026/bol-IPC-sep2026.pdf', '2026-10-31', 'Health prices rose 7.79% against 6.29% for all items; planning uses 6.5%, about 1.5 points above general planning inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CO', 1, 'gold_return_base', 0.07, NULL, 'assumption', 'Gold USD price history (Trading Economics); Colombian inflation about 3 points above US inflation', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Base case: gold rises roughly with world inflation plus a little in dollars, and the peso loses about 3% a year against the dollar over the long run.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CO', 1, 'gold_return_high', 0.12, NULL, 'assumption', 'Gold USD price history (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'High case: a repeat of gold''s strong 2005-2025 trend in pesos.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CO', 1, 'gold_return_low', 0.02, NULL, 'assumption', 'Gold USD price history (Trading Economics); COP 3,183 per USD (TRM 31 Oct 2026)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Low case: gold stalls after the 2025-26 rally and the peso keeps its 2026 strength.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CO', 1, 'gratuity_rule', NULL, '{"daysPerYear":30,"daysPerYearAfter":null,"afterYears":null,"daysPerMonth":30}', 'sourced', 'Código Sustantivo del Trabajo, art. 249 (auxilio de cesantía) (Senate legal database)', 'https://www.secretariasenado.gov.co/senado/basedoc/codigo_sustantivo_trabajo_pr008.html', '2026-10-31', 'Employers must pay severance (cesantías) of one month''s salary per year of service, pro rata, when the contract ends; it is deposited each year in a severance fund and earns 12% annual interest paid to the worker. It can also be drawn for housing or education.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CO', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'Hospital care is covered by the mandatory health system (EPS); no official figure for the typical out-of-pocket cost of a major private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CO', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Voluntary private health plans (medicina prepagada, complementary plans) are priced per person, not per sum insured; no public premium table per COP 100,000 of cover was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CO', 1, 'inflation_cpi', 0.0629, NULL, 'sourced', 'DANE, Boletín técnico IPC septiembre 2026', 'https://www.dane.gov.co/files/operaciones/IPC/sep2026/bol-IPC-sep2026.pdf', '2026-09-30', 'Consumer prices rose 6.29% in the 12 months to September 2026 (released 7 October 2026); 6.24% in August. World Bank 2025 average 5.1%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CO', 1, 'inflation_projection', 0.05, NULL, 'assumption', 'Banco de la República 3% target (+/-1 pt); CPI 6.29% in September 2026 (DANE); expectations for December 2026 at 6.9% (Trading Economics)', 'https://www.dane.gov.co/files/operaciones/IPC/sep2026/bol-IPC-sep2026.pdf', '2026-10-31', 'Inflation has stayed well above the 3% target since 2021 (5-year average about 7-8%) and expectations are rising, so planning uses 5%, between the target and recent history.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CO', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life insurance (seguro de vida) is sold in Colombia, but no regulator or other public table of premiums per COP 1,000 of cover by age was found; only company quotes exist.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CO', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Superintendencia Financiera publishes insurance statistics, but no industry-wide life claim settlement ratio was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CO', 1, 'life_expectancy', 78.3, NULL, 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/colombia', '2026-07-01', 'Life expectancy at birth 78.3 years in 2026 (men 75.6, women 80.9), UN WPP estimate. World Bank 2024: 77.9.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CO', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":22.9,"men":21.2,"women":24.3},{"age":65,"total":18.7,"men":17.2,"women":20},{"age":70,"total":14.8,"men":13.4,"women":15.9},{"age":80,"total":8.1,"men":7.1,"women":8.8}]}', 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/colombia', '2026-07-01', 'Remaining years from georank''s expected age at death by current age (UN WPP 2026 estimate).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CO', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'Ley 100 art. 257 sets the original rule (65+, Colombian, 10 years'' residence, lacking income), but the current Colombia Mayor age and targeting rules set by regulation could not be confirmed from an official page.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CO', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'Colombia has a non-contributory old-age subsidy for poor older people (Colombia Mayor; the 2024 reform''s Renta Básica Solidaria is not yet in force), but its current monthly amount could not be read: the administering agency''s sites did not respond.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CO', 1, 'oop_health_share', 0.1474, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=CO', '2024-12-31', 'Out-of-pocket spending was 14.7% of current health expenditure in 2024 (latest available; older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CO', 1, 'policy_rate', 0.1225, NULL, 'sourced', 'Trading Economics, Colombia interest rate (Banco de la República board decision of 30 Oct 2026) (secondary source)', 'https://tradingeconomics.com/colombia/interest-rate', '2026-10-30', 'The board kept the policy rate at 12.25% by majority on 30 October 2026 after a 25 bp rise at its previous meeting. Secondary source: the central bank''s own site blocked automated access, though its home-page headline showed the same decision.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CO', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":62,"nomineeUntilAge":null,"inflationLinked":true,"taxFree":null}', 'sourced', 'Ley 100 de 1993, arts. 14 and 33 (Senate legal database)', 'https://www.secretariasenado.gov.co/senado/basedoc/ley_0100_1993.html', '2026-10-15', 'Compulsory General Pension System: the public defined-benefit scheme run by Colpensiones or private individual accounts. Pension at 62 (men) / 57 (women) with 1,300 weeks; pensions are raised every 1 January by the previous year''s CPI (minimum-wage pensions by the minimum-wage rise). The 2024 reform (Ley 2381) remains suspended.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CO', 1, 'retirement_accumulation_return_base', 0.1, NULL, 'assumption', 'Fixed income base 9%; equity base 11%', 'https://tradingeconomics.com/colombia/stock-market', '2026-10-31', 'Base case: roughly half shares at 11% and half safe fixed income at about 9% after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CO', 1, 'retirement_accumulation_return_high', 0.125, NULL, 'assumption', 'Equity high 15%; after-tax 10-year TES 10.5%', 'https://tradingeconomics.com/colombia/stock-market', '2026-10-31', 'High case for a growth-leaning balanced mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CO', 1, 'retirement_accumulation_return_low', 0.07, NULL, 'assumption', 'After-tax CDTs; COLCAP record (Trading Economics)', 'https://tradingeconomics.com/colombia/stock-market', '2026-10-31', 'Low case for a balanced mix if shares lag and rates fall.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CO', 1, 'retirement_age_default', 62, NULL, 'sourced', 'Ley 100 de 1993, art. 33 as amended by Ley 797 de 2003 (Senate legal database)', 'https://www.secretariasenado.gov.co/senado/basedoc/ley_0100_1993.html', '2026-10-15', 'Pension age 62 for men and 57 for women in the public pay-as-you-go scheme (Colpensiones), with at least 1,300 weeks of contributions (the Constitutional Court ordered fewer weeks for women). The 2024 pension reform (Ley 2381) keeps these ages, but its entry into force is still suspended (database updated 15 October 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CO', 1, 'retirement_age_government', 62, NULL, 'sourced', 'Ley 100 de 1993, art. 33; Ley 1821 de 2016 (Senate legal database)', 'https://www.secretariasenado.gov.co/senado/basedoc/ley_1821_2016.html', '2026-10-15', 'Public servants draw a pension at the same 62 (men) / 57 (women) under the general system; Ley 1821 of 2016 sets 70 as the maximum age for holding public office.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CO', 1, 'retirement_return_base', 0.085, NULL, 'assumption', '360-day CDT 12.65% less 19% tax = 10.2% (Superintendencia Financiera; PwC)', 'https://www.datos.gov.co/resource/axk9-g2nh.json', '2026-10-31', 'Base case kept below the after-tax 1-year CDT rate, allowing for the policy rate to fall from 12.25%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CO', 1, 'retirement_return_high', 0.1, NULL, 'assumption', '10-year TES 13.03% less tax (Trading Economics)', 'https://tradingeconomics.com/colombia/government-bond-yield', '2026-10-31', 'High case: long TES or long CDTs bought at today''s yields and held.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CO', 1, 'retirement_return_low', 0.07, NULL, 'assumption', '90-day CDT 10.69% less tax (Superintendencia Financiera)', 'https://www.datos.gov.co/resource/axk9-g2nh.json', '2026-10-31', 'Low case: short CDTs after tax as interest rates fall.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CO', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate or retail savings bond for individuals was found in Colombia; government TES bonds are bought through brokers or funds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CO', 1, 'savings_account_rate', 0.0084, NULL, 'sourced', 'Superintendencia Financiera de Colombia, daily deposit rates by entity (datos.gov.co dataset axk9-g2nh): banks, active savings deposits of individuals', 'https://www.datos.gov.co/resource/axk9-g2nh.json', '2026-10-28', 'Balance-weighted average rate on active savings accounts of individuals at banks was about 0.84% a year (effective annual) over 22-28 October 2026; computed by us across all reporting banks.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CO', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":6.84},{"year":2040,"value":4.08},{"year":2065,"value":2.02}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/colombia/2040/', '2025-12-31', '100 / old-age dependency ratio: 14.6 (2025, World Bank), 24.5 (2040) and 49.5 (2065, populationpyramid.net/colombia/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CO', 1, 'tax_bank_interest', 0.19, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Colombia taxes on personal income and income determination (reviewed 21 Jul 2026)', 'https://taxsummaries.pwc.com/colombia/individual/taxes-on-personal-income', '2026-07-21', 'Interest is capital income in the general basket, taxed at progressive rates (0% up to 1,090 UVT, then 19%, 28%, 33% and up to 39%); 19% is the first taxed bracket (UVT COP 52,347 in 2026). The inflationary component of financial yields is exempt for individuals, so the effective rate is lower; banks also withhold at source and charge the 0.4% financial transactions tax on withdrawals.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CO', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'There is no government savings certificate in Colombia; TES interest is taxed like other interest.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CO', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Treasury issues short-term TES (TCO) of up to one year, but no current 3-month yield could be read (the central bank site blocked access).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CO', 1, 'tbond_10y_rate', 0.1303, NULL, 'sourced', 'Trading Economics, Colombia 10-year government bond yield (secondary source)', 'https://tradingeconomics.com/colombia/government-bond-yield', '2026-10-30', '10-year peso TES yield 13.03% on 30 October 2026 (secondary source; the central bank''s yield pages blocked automated access).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CO', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No current 5-year TES yield could be read: the central bank''s yield-curve pages blocked automated access and Trading Economics shows only the 10-year yield.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('CR', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"CR","iso3":"CRI","nameEn":"Costa Rica","nameNative":"Costa Rica","region":"latin_america_caribbean","languages":["es","en"],"currency":{"code":"CRC","symbol":"₡","decimals":2,"compact":"intl","usdRate":{"value":455.44,"status":"sourced","sourceName":"Banco Central de Costa Rica, reference exchange rate (selling), US dollar","sourceUrl":"https://sdd.bccr.fi.cr/es/IndicadoresEconomicos/Inicio/Contenedor/125?Cuadro=491","asOf":"2026-10-30","note":"CRC 455.44 per US dollar on 30 October 2026 (456.04 on 31 October); World Bank 2025 average 503.5, so the colón has strengthened about 9% in a year."}},"instruments":{"savings_account":{"available":true,"localName":"Cuenta de ahorro","localNameEn":"Savings account"},"fdr_3m":{"available":true,"localName":"Certificado de depósito a plazo (CDP) a 3 meses","localNameEn":"Term deposit certificate (3 months)","sourceUrl":"https://sdd.bccr.fi.cr/es/IndicadoresEconomicos/Inicio/Contenedor/369?Cuadro=886"},"fdr_1y":{"available":true,"localName":"Certificado de depósito a plazo (CDP) a 1 año","localNameEn":"Term deposit certificate (1 year)","sourceUrl":"https://sdd.bccr.fi.cr/es/IndicadoresEconomicos/Inicio/Contenedor/369?Cuadro=886"},"dps":{"available":true,"localName":"Ahorro programado","localNameEn":"Programmed monthly savings plan","note":"Monthly savings plans are offered by banks and cooperatives; no average rate is published."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":"Government savings certificate","note":"No separate retail savings certificate; individuals can buy ordinary Ministry of Finance securities."},"tbill_91d":{"available":true,"localName":"Títulos cero cupón del Gobierno","localNameEn":"Government zero-coupon bills","sourceUrl":"https://sdd.bccr.fi.cr/es/IndicadoresEconomicos/Inicio/Contenedor/366?Cuadro=369"},"tbond_5y":{"available":true,"localName":"Títulos de propiedad del Gobierno","localNameEn":"Government bonds (títulos de propiedad)","sourceUrl":"https://sdd.bccr.fi.cr/es/IndicadoresEconomicos/Inicio/Contenedor/366?Cuadro=369"},"tbond_10y":{"available":true,"localName":"Títulos de propiedad del Gobierno","localNameEn":"Government bonds (títulos de propiedad)","sourceUrl":"https://sdd.bccr.fi.cr/es/IndicadoresEconomicos/Inicio/Contenedor/366?Cuadro=369"},"equity_fund":{"available":true,"localName":"Fondos de inversión","localNameEn":"Investment funds","note":"Local funds are mostly money-market, bond and real-estate funds; global equity funds and ETFs are bought through securities brokers."},"gold":{"available":true,"localName":"Oro de inversión (lingotes y monedas)","localNameEn":"Investment gold (bars and coins)"}},"institutions":{"centralBank":{"name":"Banco Central de Costa Rica (BCCR)","url":"https://www.bccr.fi.cr/"},"insuranceRegulator":{"name":"Superintendencia General de Seguros (SUGESE)","url":"https://www.sugese.fi.cr/"},"insuranceComplaints":{"name":"SUGESE, consumer queries and complaints","url":"https://www.sugese.fi.cr/cr/es/sobre-sugese/tramites/gestiones-consumidor-financiero.html"},"pensionScheme":{"name":"Caja Costarricense de Seguro Social (CCSS), Seguro de Invalidez, Vejez y Muerte (IVM)","url":"https://www.ccss.sa.cr/"},"oldAgeAllowance":{"name":"CCSS Régimen No Contributivo de Pensiones","url":"https://www.supen.fi.cr/como-obtener-una-pension-si-no-he-realizado-aportes-no-contributivo"},"publicHealthCover":{"name":"Caja Costarricense de Seguro Social (CCSS), Seguro de Salud","url":"https://www.ccss.sa.cr/"},"depositInsurance":{"name":"Fondo de Garantía de Depósitos (administered by the BCCR)","url":"https://www.bccr.fi.cr/cr/es/fondo-garantia-depositos.html"},"statistics":{"name":"Instituto Nacional de Estadística y Censos (INEC)","url":"https://inec.cr/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CR', 1, 'bank_deposit_avg_rate', 0.0453, NULL, 'sourced', 'BCCR, Tasa pasiva negociada (TPN), weighted average of all terms, all deposit-taking institutions, colones', 'https://sdd.bccr.fi.cr/es/IndicadoresEconomicos/Inicio/Contenedor/369?Cuadro=886', '2026-10-27', 'Weighted average of new colón term deposits of all terms, week of 21-27 October 2026. The BCCR''s Tasa Básica Pasiva was 3.56% for early November 2026; World Bank deposit rate 3.44% (2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CR', 1, 'credit_card_rate_cap', 0.3648, NULL, 'sourced', 'BCCR maximum (usury) annual rate for colón credit, second half of 2026, as reported by Delfino.cr', 'https://www.delfino.cr/2026/07/topes-de-usura-tendran-ajustes-mixtos-para-el-segundo-semestre', '2026-07-01', 'Legal cap under the usury law: 36.48% a year in colones (30.11% in dollars) for July-December 2026, applying to credit cards; secondary source reporting the BCCR''s calculation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CR', 1, 'deposit_insurance_limit', 6000000, NULL, 'sourced', 'BCCR, Fondo de Garantía de Depósitos, productos garantizados', 'https://www.bccr.fi.cr/cr/es/fondo-garantia-depositos/productos-garantizados.html', '2026-10-31', 'Up to CRC 6,000,000 per person per entity (Law 9816), principal only, any currency; the amount is to be adjusted for inflation by regulation. State-owned commercial banks also carry an unlimited state guarantee.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CR', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Banks and cooperatives offer programmed monthly savings plans (ahorro programado), but no published average rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CR', 1, 'equity_return_base', 0.075, NULL, 'assumption', 'Global equity index in colón terms; after-tax 1-year deposit 5.68% x 0.85 = 4.8% (BCCR TPN)', 'https://sdd.bccr.fi.cr/es/IndicadoresEconomicos/Inicio/Contenedor/369?Cuadro=886', '2026-10-31', 'Costa Rica''s local exchange lists very few shares, so equity is a global index fund in colones: about 2.7 points over the after-tax safe rate, allowing for long-run colón strength.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CR', 1, 'equity_return_high', 0.11, NULL, 'assumption', 'Global equity long-run record plus modest colón depreciation', 'https://sdd.bccr.fi.cr/es/IndicadoresEconomicos/Inicio/Contenedor/125?Cuadro=491', '2026-10-31', 'High case: global shares repeat their long-run record and the colón gives back part of its recent gains.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CR', 1, 'equity_return_low', 0.03, NULL, 'assumption', 'No meaningful local stock market; global equities in colón terms. Colón rose about 9% against the dollar in the year to October 2026 (BCCR reference rate)', 'https://sdd.bccr.fi.cr/es/IndicadoresEconomicos/Inicio/Contenedor/125?Cuadro=491', '2026-10-31', 'Low case: a strong colón and weak global shares leave equities only a little above after-tax deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CR', 1, 'fdr_1y_rate', 0.0568, NULL, 'sourced', 'BCCR, Tasa pasiva negociada (TPN) por plazo, all deposit-taking institutions, 360-539 days, colones', 'https://sdd.bccr.fi.cr/es/IndicadoresEconomicos/Inicio/Contenedor/369?Cuadro=886', '2026-10-27', 'Weighted average negotiated rate on new colón term deposits of 360-539 days, week of 21-27 October 2026 (public banks 5.31%, private banks 5.54%, cooperatives 6.08%). Gross of tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CR', 1, 'fdr_3m_rate', 0.0379, NULL, 'sourced', 'BCCR, Tasa pasiva negociada (TPN) por plazo, all deposit-taking institutions, 90-119 days, colones', 'https://sdd.bccr.fi.cr/es/IndicadoresEconomicos/Inicio/Contenedor/369?Cuadro=886', '2026-10-27', 'Weighted average negotiated rate on new colón term deposits of 90-119 days, week of 21-27 October 2026 (3.60% the week before); public banks 3.82%. Gross of the 15% withholding tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CR', 1, 'fixed_income_return_base', 0.048, NULL, 'assumption', '1-year term deposit 5.68% less 15% tax = 4.8% (BCCR TPN)', 'https://sdd.bccr.fi.cr/es/IndicadoresEconomicos/Inicio/Contenedor/369?Cuadro=886', '2026-10-31', 'Base case: one-year colón term deposits after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CR', 1, 'fixed_income_return_high', 0.058, NULL, 'assumption', '5-year government bond 5.77% net of tax (BCCR sovereign curve)', 'https://sdd.bccr.fi.cr/es/IndicadoresEconomicos/Inicio/Contenedor/366?Cuadro=369', '2026-10-31', 'High case: locking in five-year government bonds at today''s net yield.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CR', 1, 'fixed_income_return_low', 0.032, NULL, 'assumption', '3-month term deposit 3.79% less 15% tax = 3.2% (BCCR TPN)', 'https://sdd.bccr.fi.cr/es/IndicadoresEconomicos/Inicio/Contenedor/369?Cuadro=886', '2026-10-31', 'Low case: rolling short deposits after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CR', 1, 'goal_inflation_education', 0.04, NULL, 'assumption', 'INEC CPI September 2026: educational services weight 4.30%, -0.01% in the month', 'https://d1qqtien6gys07.cloudfront.net/wp-content/uploads/2026/10/coEconomIPC092026-01.pdf', '2026-10-31', 'Education fees usually rise once a year faster than general prices; planning uses 4%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CR', 1, 'goal_inflation_health', 0.04, NULL, 'assumption', 'INEC CPI September 2026: health division weight 6.65%, +0.04% in the month', 'https://d1qqtien6gys07.cloudfront.net/wp-content/uploads/2026/10/coEconomIPC092026-01.pdf', '2026-10-31', 'Medical prices in Costa Rica have risen faster than the near-zero overall CPI; planning uses 4%, about 1.5 points above general inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CR', 1, 'gold_return_base', 0.045, NULL, 'assumption', 'Gold USD price trend (Trading Economics); BCCR 3% inflation target', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Base case: gold tracks long-run dollar inflation plus a little, with the colón roughly stable to slightly weaker against the dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CR', 1, 'gold_return_high', 0.09, NULL, 'assumption', 'Gold USD price history (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'High case: gold resumes its 2020s uptrend and the colón weakens.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CR', 1, 'gold_return_low', 0, NULL, 'assumption', 'Gold USD 3,876/oz on 30 Oct 2026, 3% lower in a year and well below its January 2026 peak (Trading Economics); colón appreciation', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Low case: gold stays flat in dollars and the colón holds its strength.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CR', 1, 'gratuity_rule', NULL, '{"daysPerYear":19.5,"daysPerYearAfter":22,"afterYears":6,"daysPerMonth":30}', 'sourced', 'Código de Trabajo, article 29 (auxilio de cesantía), text as reproduced by Diario Extra', 'https://www.diarioextra.com/noticia/texto-del-articulo-29-del-codigo-de-trabajo/', '2026-10-31', 'Severance (cesantía) is due on dismissal without just cause and certain other terminations (bill 23.078 proposed excluding people who retire on a pension): 19.5 days'' wages per year after 1 year, rising each year to 22 days in years 7-9 and easing to 20 days from year 13; capped at the last 8 years of service. Daily wage = average monthly wage / 30.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CR', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a private hospital stay was found; most care is provided free at the point of use by the CCSS.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CR', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No regulator or other non-company source of private health insurance premiums by age was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CR', 1, 'inflation_cpi', 0.0034, NULL, 'sourced', 'INEC Costa Rica, Índice de Precios al Consumidor, setiembre 2026', 'https://d1qqtien6gys07.cloudfront.net/wp-content/uploads/2026/10/coEconomIPC092026-01.pdf', '2026-09-30', 'CPI rose 0.34% in the 12 months to September 2026 (published 7 October 2026), the first positive reading after 16 months of year-on-year deflation; World Bank 2025 average -0.07%. October CPI is due in early November.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CR', 1, 'inflation_projection', 0.025, NULL, 'assumption', 'BCCR inflation target 3% ±1 point; CPI well below the target range for 41 straight months', 'https://www.bccr.fi.cr/cr/es/noticias/listado-de-noticias/2026/junta-directiva-del-bccr-acordo-mantener-la-tasa-de-politica-monetaria-en-3,00-por-ciento-anual-24-09-2026.html', '2026-10-31', 'The BCCR targets 3%, but inflation has run below the 2-4% range since 2023 (about 0% in 2024-2026), so planning uses 2.5%, a little under the target.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CR', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life cover is sold in Costa Rica, but no regulator or other non-company source with indicative premiums by age was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CR', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'SUGESE publishes insurance market statistics but no industry-wide life claim settlement ratio was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CR', 1, 'life_expectancy', 80.996, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=CR', '2024-12-31', 'Men 78.4, women 83.6 (2024; latest World Bank figure, older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CR', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":25.2,"men":23.5,"women":26.6},{"age":65,"total":21,"men":19.5,"women":22.3},{"age":70,"total":17,"men":15.6,"women":18.1},{"age":80,"total":9.9,"men":8.8,"women":10.7}]}', 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/costa-rica', '2026-07-01', 'Remaining years derived from the ''life expectancy by current age'' table for 2026 (UN WPP).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CR', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":65,"womenAge":65,"over90Monthly":null,"meansTested":true}', 'sourced', 'SUPEN, how to get a pension without contributions (Régimen No Contributivo)', 'https://www.supen.fi.cr/como-obtener-una-pension-si-no-he-realizado-aportes-no-contributivo', '2026-10-29', 'Age 65 or over, Costa Rican, in poverty or extreme poverty (household income per person not above the pension amount), no other pension, no relatives able to help and no property other than a modest home.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CR', 1, 'old_age_allowance_monthly', 82000, NULL, 'sourced', 'CRHoy.com report on the Régimen No Contributivo bill, 20 August 2026 (secondary source)', 'https://crhoy.com/nacionales/que-propone-el-proyecto-del-gobierno-sobre-las-pensiones-del-regimen-no-contributivo/', '2026-08-20', 'The CCSS non-contributory pension pays about CRC 82,000 a month plus a 13th payment; the amount has not changed since 2019, and about 32,000 eligible people were on a waiting list in August 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CR', 1, 'oop_health_share', 0.2413, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=CR', '2023-12-31', 'Out-of-pocket spending was 24.1% of current health expenditure in 2023 (latest available; older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CR', 1, 'policy_rate', 0.03, NULL, 'sourced', 'Banco Central de Costa Rica (BCCR), Tasa de Política Monetaria, decision of 24 September 2026', 'https://www.bccr.fi.cr/cr/es/noticias/listado-de-noticias/2026/junta-directiva-del-bccr-acordo-mantener-la-tasa-de-politica-monetaria-en-3,00-por-ciento-anual-24-09-2026.html', '2026-09-24', 'Held at 3.00% on 24 September 2026 after a 25-basis-point cut on 23 July 2026; next meeting 26 November 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CR', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":65,"nomineeUntilAge":null,"inflationLinked":true,"taxFree":null}', 'sourced', 'CCSS, Reglamento del Seguro de Invalidez, Vejez y Muerte (SCIJ)', 'https://sinalevi.go.cr/ResultadosNormativa/Informacion?param1=26485&param2=148515&param3=1', '2026-10-31', 'Mandatory for all employees and the self-employed. Pension at 65 with 300 contributions, based on the best 300 monthly wages updated by CPI (art. 24); under art. 28 the CCSS board revalues pensions in payment periodically, in line as far as possible with wages and the cost of living. A mandatory individual account (ROP) adds to it.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CR', 1, 'retirement_accumulation_return_base', 0.06, NULL, 'assumption', 'Fixed income base 4.8%; equity base 7.5%', 'https://sdd.bccr.fi.cr/es/IndicadoresEconomicos/Inicio/Contenedor/366?Cuadro=369', '2026-10-31', 'Base case: roughly half safe colón fixed income and half global equity.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CR', 1, 'retirement_accumulation_return_high', 0.08, NULL, 'assumption', 'Equity high 11%; 5-year government bond 5.8% net', 'https://sdd.bccr.fi.cr/es/IndicadoresEconomicos/Inicio/Contenedor/366?Cuadro=369', '2026-10-31', 'High case: equities do well and bond yields stay high.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CR', 1, 'retirement_accumulation_return_low', 0.04, NULL, 'assumption', 'After-tax deposits 3.2-4.8%; equity low case 3%', 'https://sdd.bccr.fi.cr/es/IndicadoresEconomicos/Inicio/Contenedor/369?Cuadro=886', '2026-10-31', 'Low case for a balanced mix of deposits, government bonds and global equity.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CR', 1, 'retirement_age_default', 65, NULL, 'sourced', 'CCSS, Reglamento del Seguro de Invalidez, Vejez y Muerte, article 5 (SCIJ)', 'https://sinalevi.go.cr/ResultadosNormativa/Informacion?param1=26485&param2=148515&param3=1', '2026-10-31', 'Ordinary old-age pension at 65 with 300 monthly contributions (proportional pension at 65 with fewer, from 180). Article 5 (last amended 23 October 2025) allows early retirement only for women, under its table of ages and contributions, or by drawing on voluntary pension savings (Law 7983, art. 26); 65 applies to people born after 1975.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CR', 1, 'retirement_age_government', 65, NULL, 'sourced', 'CCSS, Reglamento del Seguro de Invalidez, Vejez y Muerte, article 5 (SCIJ)', 'https://sinalevi.go.cr/ResultadosNormativa/Informacion?param1=26485&param2=148515&param3=1', '2026-10-31', 'Most central-government employees have been in the CCSS IVM scheme since the 1992 pension reform, so 65 applies; teachers and judicial staff have separate schemes with similar ages.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CR', 1, 'retirement_return_base', 0.045, NULL, 'assumption', '1-year term deposit 5.68% less 15% tax = 4.8% (BCCR TPN)', 'https://sdd.bccr.fi.cr/es/IndicadoresEconomicos/Inicio/Contenedor/369?Cuadro=886', '2026-10-31', 'Base case: mostly one-year deposits and short government bonds, kept below the 4.8% after-tax one-year deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CR', 1, 'retirement_return_high', 0.055, NULL, 'assumption', '5-year government bond 5.77% net (BCCR sovereign curve)', 'https://sdd.bccr.fi.cr/es/IndicadoresEconomicos/Inicio/Contenedor/366?Cuadro=369', '2026-10-31', 'High case: a ladder of medium-term government bonds at today''s net yields.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CR', 1, 'retirement_return_low', 0.03, NULL, 'assumption', '3-month term deposit 3.79% less 15% tax (BCCR TPN)', 'https://sdd.bccr.fi.cr/es/IndicadoresEconomicos/Inicio/Contenedor/369?Cuadro=886', '2026-10-31', 'Low case: rolling short deposits after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CR', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Costa Rica has no separate government savings certificate for individuals; individuals buy ordinary Ministry of Finance securities (see the bond slots).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CR', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published average rate for ordinary colón savings accounts was found; the BCCR publishes negotiated term-deposit rates only (deposits of 1 to 6 days paid 0.18% in October 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CR', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":5.41},{"year":2040,"value":3.31},{"year":2065,"value":1.64}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP medium variant via populationpyramid.net (2040 and 2065 pages)', 'https://www.populationpyramid.net/costa-rica/2065/', '2025-12-31', '100 / old-age dependency ratio: 18.5 in 2025 (World Bank), 30.2 in 2040 and 61.1 in 2065 (UN WPP medium variant).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CR', 1, 'tax_bank_interest', 0.15, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Costa Rica, income determination', 'https://taxsummaries.pwc.com/costa-rica/individual/income-determination', '2026-06-30', 'Interest is taxed as income from movable capital at 15%, withheld at source (page reviewed 30 June 2026). Savings at some public-law and cooperative entities are on a phase-in that reached 14% in July 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CR', 1, 'tax_sanchayapatra_profit', 0.15, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Costa Rica, income determination', 'https://taxsummaries.pwc.com/costa-rica/individual/income-determination', '2026-06-30', 'No separate savings certificate exists; interest on government securities is capital income taxed at 15% (older issues kept an 8% rate).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CR', 1, 'tbill_91d_rate', 0.0398, NULL, 'sourced', 'BCCR, Curva de rendimiento soberana en colones, 3-month point (net yield)', 'https://sdd.bccr.fi.cr/es/IndicadoresEconomicos/Inicio/Contenedor/366?Cuadro=369', '2026-10-28', 'Sovereign colón curve for the week of 28 October-3 November 2026: 3 months 3.976% (4.041% the week before). The BCCR publishes the curve net of income tax (about 4.7% gross at the 15% rate).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CR', 1, 'tbond_10y_rate', 0.0622, NULL, 'sourced', 'BCCR, Curva de rendimiento soberana en colones, 10-year point (net yield)', 'https://sdd.bccr.fi.cr/es/IndicadoresEconomicos/Inicio/Contenedor/366?Cuadro=369', '2026-10-28', '10-year net yield 6.220% for the week of 28 October-3 November 2026 (about 7.3% gross at 15% tax).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CR', 1, 'tbond_5y_rate', 0.0577, NULL, 'sourced', 'BCCR, Curva de rendimiento soberana en colones, 5-year point (net yield)', 'https://sdd.bccr.fi.cr/es/IndicadoresEconomicos/Inicio/Contenedor/366?Cuadro=369', '2026-10-28', '5-year net yield 5.770% for the week of 28 October-3 November 2026 (about 6.8% gross at 15% tax).', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('CU', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"CU","iso3":"CUB","nameEn":"Cuba","nameNative":"Cuba","region":"latin_america_caribbean","languages":["es"],"currency":{"code":"CUP","symbol":"$","decimals":2,"compact":"intl","usdRate":{"value":768,"status":"sourced","sourceName":"Banco Central de Cuba, official exchange rate, Segment III (households and non-state businesses)","sourceUrl":"https://www.bc.gob.cu/tasas-de-cambio","asOf":"2026-10-31","note":"CUP 768.00 per US dollar in Segment III (the floating official rate used for household currency exchange), the rate in force before the BCC moved it to 775.00 on 3 November 2026; Segment I (state) is fixed at 24 and Segment II at 120."}},"instruments":{"savings_account":{"available":true,"localName":"Cuenta de ahorro","localNameEn":"Savings account"},"fdr_3m":{"available":true,"localName":"Depósito a plazo fijo","localNameEn":"Fixed-term deposit","note":"Offered by state savings banks; rates are not published by the central bank."},"fdr_1y":{"available":true,"localName":"Depósito a plazo fijo","localNameEn":"Fixed-term deposit","note":"Offered by state savings banks; rates are not published by the central bank."},"dps":{"available":false,"localName":null,"localNameEn":"Recurring deposit","note":"No monthly recurring deposit product was confirmed."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":"Government savings certificate","note":"Government bonds are placed with state banks, not sold to individuals."},"tbill_91d":{"available":false,"localName":null,"localNameEn":"Treasury bills"},"tbond_5y":{"available":false,"localName":null,"localNameEn":"Government bonds"},"tbond_10y":{"available":false,"localName":null,"localNameEn":"Government bonds"},"equity_fund":{"available":false,"localName":null,"localNameEn":"Equity funds","note":"Cuba has no stock exchange and no retail investment funds."},"gold":{"available":false,"localName":null,"localNameEn":"Investment gold","note":"No legal retail market for investment gold bars or coins was found."}},"institutions":{"centralBank":{"name":"Banco Central de Cuba (BCC)","url":"https://www.bc.gob.cu/"},"insuranceRegulator":{"name":"Superintendencia de Seguros, Ministerio de Finanzas y Precios","url":"https://www.mfp.gob.cu/nosotros/seguros"},"insuranceComplaints":{"name":"Ministerio de Finanzas y Precios, citizen complaints (Superintendencia de Seguros)","url":"https://www.mfp.gob.cu/nosotros/seguros"},"pensionScheme":{"name":"Seguridad social (Ley 105), Ministerio de Trabajo y Seguridad Social","url":"https://www.mtss.gob.cu/"},"oldAgeAllowance":{"name":"Asistencia social, Ministerio de Trabajo y Seguridad Social","url":"https://www.mtss.gob.cu/","note":"Means-tested social assistance, not a universal pension."},"publicHealthCover":{"name":"Sistema Nacional de Salud, Ministerio de Salud Pública (MINSAP)","url":"https://salud.msp.gob.cu/"},"depositInsurance":null,"statistics":{"name":"Oficina Nacional de Estadística e Información (ONEI)","url":"https://www.onei.gob.cu/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CU', 1, 'bank_deposit_avg_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published average deposit rate; the World Bank has no deposit-rate series for Cuba.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CU', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published legal cap or typical rate for credit card balances was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CU', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No deposit insurance scheme or published cover limit was found; banks are state-owned.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CU', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No monthly recurring deposit product with a published rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CU', 1, 'equity_return_base', 0.07, NULL, 'assumption', 'No local market; capped at the assumed safe rate (3%) plus 4 points', 'https://www.bc.gob.cu/tasas-de-cambio', '2026-10-31', 'A global index in peso terms would track the peso''s fall, but equity is not available to residents, so the base case is capped at 4 points over the assumed safe rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CU', 1, 'equity_return_high', 0.12, NULL, 'assumption', 'Global equity record; peso depreciation (BCC Segment III rate)', 'https://www.bc.gob.cu/tasas-de-cambio', '2026-10-31', 'High case for a resident with access to foreign assets.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CU', 1, 'equity_return_low', 0.02, NULL, 'assumption', 'No stock exchange in Cuba; global equity in peso terms; official Segment III rate 768 pesos per US dollar (BCC, October 2026)', 'https://www.bc.gob.cu/tasas-de-cambio', '2026-10-31', 'There is no local stock market and no legal way for most residents to buy a global index fund; low case kept just under the assumed safe rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CU', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Deposit rates are set by the Banco Central de Cuba for state banks and are not published on its site; only bank pages show them.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CU', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Deposit rates are set by the Banco Central de Cuba for state banks and are not published on its site; only bank pages show them.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CU', 1, 'fixed_income_return_base', 0.03, NULL, 'assumption', 'Banco Central de Cuba, monetary policy regulations: the BCC sets bank deposit and lending rates directly; the rates are not published on its site', 'https://www.bc.gob.cu/normas-y-regulaciones/regulaciones-de-politica-monetaria', '2026-10-31', 'Base case: fixed-term peso deposits at state banks, assumed to pay low single-digit rates far below inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CU', 1, 'fixed_income_return_high', 0.05, NULL, 'assumption', 'Banco Central de Cuba, monetary policy regulations: the BCC sets bank deposit and lending rates directly; the rates are not published on its site', 'https://www.bc.gob.cu/normas-y-regulaciones/regulaciones-de-politica-monetaria', '2026-10-31', 'High case: the longest fixed-term peso deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CU', 1, 'fixed_income_return_low', 0.01, NULL, 'assumption', 'Banco Central de Cuba, monetary policy regulations: the BCC sets bank deposit and lending rates directly; the rates are not published on its site', 'https://www.bc.gob.cu/normas-y-regulaciones/regulaciones-de-politica-monetaria', '2026-10-31', 'Low case: an ordinary peso savings account, which pays very little.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CU', 1, 'goal_inflation_education', 0.25, NULL, 'assumption', 'ONEI CPI 28.4% (September 2026); public education is free', 'https://www.directoriocubano.info/cuba/salario-medio-cuba-inflacion-septiembre-2026/', '2026-10-31', 'No education CPI was found; planning uses the general inflation assumption of 25%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CU', 1, 'goal_inflation_health', 0.25, NULL, 'assumption', 'ONEI CPI 28.4% (September 2026); public care is free but medicines are scarce and bought informally', 'https://www.directoriocubano.info/cuba/salario-medio-cuba-inflacion-septiembre-2026/', '2026-10-31', 'No medical CPI was found; planning uses the general inflation assumption of 25%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CU', 1, 'gold_return_base', 0.2, NULL, 'assumption', 'Gold USD trend (Trading Economics) plus peso depreciation: BCC Segment III rate 768 pesos per dollar (Oct 2026); official CPI inflation 28.4% (Sep 2026)', 'https://www.bc.gob.cu/tasas-de-cambio', '2026-10-31', 'Base case: gold in pesos rises roughly with the peso''s depreciation, which tracks inflation; assumed at about 20% a year, a little under current official inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CU', 1, 'gold_return_high', 0.35, NULL, 'assumption', 'Official CPI inflation 28.4% (Sep 2026) and a weakening Segment III rate (BCC)', 'https://www.bc.gob.cu/tasas-de-cambio', '2026-10-31', 'High case: the peso keeps losing value faster than official inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CU', 1, 'gold_return_low', 0.1, NULL, 'assumption', 'Gold USD 3,876/oz on 30 Oct 2026 (Trading Economics); peso depreciation', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Low case: dollar gold flat while the peso loses value more slowly than today''s inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CU', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No statutory gratuity or end-of-service payment for employees was found in the sources read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CU', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'Hospital care for residents is free in the public national health system; there are no private hospitals for residents and no published cost.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CU', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No private health insurance market for residents was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CU', 1, 'inflation_cpi', 0.2844, NULL, 'sourced', 'ONEI (Oficina Nacional de Estadística e Información) CPI, September 2026, as reported by Directorio Cubano (secondary source)', 'https://www.directoriocubano.info/cuba/salario-medio-cuba-inflacion-septiembre-2026/', '2026-09-30', 'Official year-on-year CPI inflation 28.44% in September 2026 (ONEI data reported on 15 October 2026). ONEI''s own site could not be reached, so this is a secondary source. Independent estimates put real inflation far higher.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CU', 1, 'inflation_projection', 0.25, NULL, 'assumption', 'ONEI CPI 28.4% in September 2026; official inflation about 25-40% a year since the 2021 currency reform; no inflation target', 'https://www.directoriocubano.info/cuba/salario-medio-cuba-inflacion-septiembre-2026/', '2026-10-31', 'With no credible inflation target and official inflation above 25% for most years since 2021, planning uses 25% a year.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CU', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Life insurance is sold by state insurers, but no regulator or non-company source of term premiums by age was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CU', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The insurance supervisor (Superintendencia de Seguros, Ministry of Finance and Prices) publishes no claim settlement statistics.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CU', 1, 'life_expectancy', 78.264, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=CU', '2024-12-31', 'Men 75.9, women 80.7 (2024; latest World Bank figure, older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CU', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":22.3,"men":20.6,"women":23.8},{"age":65,"total":18.5,"men":17,"women":19.8},{"age":70,"total":15,"men":13.7,"women":16.1},{"age":80,"total":9,"men":8.3,"women":9.6}]}', 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/cuba', '2026-07-01', 'Remaining years derived from the ''life expectancy by current age'' table for 2026 (UN WPP).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CU', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":65,"womenAge":60,"over90Monthly":null,"meansTested":true}', 'sourced', 'US SSA, Social Security Programs Throughout the World: The Americas, 2019, Cuba', 'https://www.ssa.gov/policy/docs/progdesc/ssptw/2018-2019/americas/cuba.html', '2019-12-31', 'Social assistance old-age benefit: men 65, women 60 with fewer than 20 years of work, unable to work and with no family members to support them. Source is from 2019, older than 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CU', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'Means-tested social assistance pays older people who cannot work and have no family support, but the amount is set case by case and no current figure was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CU', 1, 'oop_health_share', 0.1658, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=CU', '2023-12-31', 'Out-of-pocket spending was 16.6% of current health expenditure in 2023 (latest available; older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CU', 1, 'policy_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Banco Central de Cuba sets bank interest rates administratively and its monetary policy dashboard shows no published reference rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CU', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":65,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'US SSA, Social Security Programs Throughout the World: The Americas, 2019, Cuba', 'https://www.ssa.gov/policy/docs/progdesc/ssptw/2018-2019/americas/cuba.html', '2019-12-31', 'State social insurance (Law 105 of 2008) covers employees: pension at 65 (men) or 60 (women) with 30 years of work, 60% of best 5 of the last 15 years'' average earnings; benefits are adjusted by government decree, not automatically for inflation. Source is from 2019.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CU', 1, 'retirement_accumulation_return_base', 0.04, NULL, 'assumption', 'Peso deposits; equity assumption capped at safe rate plus 4 points', 'https://www.bc.gob.cu/normas-y-regulaciones/regulaciones-de-politica-monetaria', '2026-10-31', 'Base case for a mix weighted to peso deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CU', 1, 'retirement_accumulation_return_high', 0.07, NULL, 'assumption', 'Equity base 7%; peso deposits 5%', 'https://www.bc.gob.cu/tasas-de-cambio', '2026-10-31', 'High case for someone with some access to real or foreign assets.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CU', 1, 'retirement_accumulation_return_low', 0.02, NULL, 'assumption', 'Peso deposits only; no local stock or bond market for individuals', 'https://www.bc.gob.cu/normas-y-regulaciones/regulaciones-de-politica-monetaria', '2026-10-31', 'Low case: residents can mostly hold only peso deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CU', 1, 'retirement_age_default', 65, NULL, 'sourced', 'US SSA, Social Security Programs Throughout the World: The Americas, 2019, Cuba', 'https://www.ssa.gov/policy/docs/progdesc/ssptw/2018-2019/americas/cuba.html', '2019-12-31', 'Social Security Law 105 of 2008: old-age pension at 65 for men and 60 for women with 30 years of work (partial pension with 20-29 years). Source is from 2019, older than 2025; no later change was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CU', 1, 'retirement_age_government', 65, NULL, 'sourced', 'US SSA, Social Security Programs Throughout the World: The Americas, 2019, Cuba', 'https://www.ssa.gov/policy/docs/progdesc/ssptw/2018-2019/americas/cuba.html', '2019-12-31', 'The same social insurance rules cover public-sector employees: 65 for men, 60 for women. Source is from 2019, older than 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CU', 1, 'retirement_return_base', 0.03, NULL, 'assumption', 'Banco Central de Cuba, monetary policy regulations: the BCC sets bank deposit and lending rates directly; the rates are not published on its site', 'https://www.bc.gob.cu/normas-y-regulaciones/regulaciones-de-politica-monetaria', '2026-10-31', 'Base case: fixed-term peso deposits, assumed low single digits and no higher than the safe rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CU', 1, 'retirement_return_high', 0.05, NULL, 'assumption', 'Banco Central de Cuba, monetary policy regulations: the BCC sets bank deposit and lending rates directly; the rates are not published on its site', 'https://www.bc.gob.cu/normas-y-regulaciones/regulaciones-de-politica-monetaria', '2026-10-31', 'High case: longest fixed-term peso deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CU', 1, 'retirement_return_low', 0.01, NULL, 'assumption', 'Banco Central de Cuba, monetary policy regulations: the BCC sets bank deposit and lending rates directly; the rates are not published on its site', 'https://www.bc.gob.cu/normas-y-regulaciones/regulaciones-de-politica-monetaria', '2026-10-31', 'Low case: savings account in pesos.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CU', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate or retail bond is sold to individuals; government bonds are placed with state banks.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CU', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Deposit rates are set by the Banco Central de Cuba for state banks and are not published on its site; only bank pages show them.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CU', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":3.99},{"year":2040,"value":2.07},{"year":2065,"value":1.61}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/cuba/2040/', '2025-12-31', '100 / old-age dependency ratio: 25.1 in 2025 (World Bank), 48.3 in 2040 and 62.0 in 2065 (UN WPP).', 0);
