INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CU', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Government bonds are placed with state banks only; no market yield is published.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('CV', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"CV","iso3":"CPV","nameEn":"Cabo Verde","nameNative":"Kabu Verdi","region":"sub_saharan_africa","languages":["kea","pt"],"currency":{"code":"CVE","symbol":"CVE","decimals":2,"compact":"intl","usdRate":{"value":98.62,"status":"sourced","sourceName":"Trading Economics, USD/CVE market rate, 29 October 2026","sourceUrl":"https://tradingeconomics.com/cape-verde/currency","asOf":"2026-10-29","note":"Secondary source because the Banco de Cabo Verde site refused connections on 31 October 2026. The escudo is pegged to the euro at 110.265; World Bank 2025 average 97.86 per dollar. Locally amounts are written with the cifrão as decimal mark (1.000$00)."}},"instruments":{"savings_account":{"available":true,"localName":"Conta poupança","localNameEn":"Savings account","note":"Rates not published in a source that could be read."},"fdr_3m":{"available":true,"localName":"Depósito a prazo (3 meses)","localNameEn":"Term deposit, 3 months","note":"Rates not published in a source that could be read."},"fdr_1y":{"available":true,"localName":"Depósito a prazo (1 ano)","localNameEn":"Term deposit, 1 year","note":"Rates not published in a source that could be read."},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No standard monthly recurring deposit product was found."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate for individuals was found."},"tbill_91d":{"available":true,"localName":"Bilhetes do Tesouro","localNameEn":"Treasury bills","note":"Issued by the Treasury and sold mainly to banks; no recent rate could be read."},"tbond_5y":{"available":true,"localName":"Obrigações do Tesouro","localNameEn":"Treasury bonds","note":"Listed on the Cabo Verde stock exchange; interest taxed at 10% for individuals.","sourceUrl":"https://taxsummaries.pwc.com/cabo-verde/individual/income-determination"},"tbond_10y":{"available":true,"localName":"Obrigações do Tesouro","localNameEn":"Treasury bonds","note":"Listed on the Cabo Verde stock exchange; no yield could be read."},"equity_fund":{"available":false,"localName":null,"localNameEn":null,"note":"No diversified retail investment fund was found; the local stock exchange has only a few listed shares."},"gold":{"available":false,"localName":null,"localNameEn":null,"note":"No retail market for investment gold bars or coins was found."}},"institutions":{"centralBank":{"name":"Banco de Cabo Verde (BCV)","url":"https://www.bcv.cv/","note":"Also supervises banks and insurers; site refused connections when checked on 31 October 2026."},"insuranceRegulator":{"name":"Banco de Cabo Verde, insurance supervision","url":"https://www.bcv.cv/"},"insuranceComplaints":null,"pensionScheme":{"name":"Instituto Nacional de Previdência Social (INPS)","url":"https://www.inps.cv/"},"oldAgeAllowance":{"name":"Centro Nacional de Pensões Sociais (CNPS), Pensão Social Básica","url":"https://www.cnps.cv/index.php/pt/programa-de-inclusao-social/pensao-social-basica"},"publicHealthCover":null,"depositInsurance":null,"statistics":{"name":"Instituto Nacional de Estatística (INE)","url":"https://ine.cv/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CV', 1, 'bank_deposit_avg_rate', 0.0153, NULL, 'sourced', 'World Bank WDI, deposit interest rate (FR.INR.DPST), Cabo Verde', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=CV', '2025-12-31', '1.53% average for 2025 (1.67% in 2024); a fresher central bank figure could not be read because the Banco de Cabo Verde site refused connections on 31 October 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CV', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap or typical credit-card rate was found; World Bank average lending rate was 7.75% in 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CV', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No deposit-guarantee cover per depositor could be confirmed; the Banco de Cabo Verde site refused connections on 31 October 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CV', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No industry-wide rate for a monthly recurring deposit was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CV', 1, 'equity_return_base', 0.05, NULL, 'assumption', 'World Bank deposit rate 1.53% (2025), about 1.2% after the 20% tax', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=CV', '2026-10-31', 'Base case: the local stock exchange is very small with few listings and no long index record, so this follows a global index in escudo (euro) terms, capped at 4 points over the after-tax deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CV', 1, 'equity_return_high', 0.08, NULL, 'assumption', 'Escudo-euro peg; World Bank deposit rate 1.53% (2025)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=CV', '2026-10-31', 'High case: world shares near their long-run return in euro terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CV', 1, 'equity_return_low', 0.01, NULL, 'assumption', 'World Bank deposit rate 1.53% (2025), taxed at 20%', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=CV', '2026-10-31', 'Low case: a weak decade for world shares in euro-pegged escudo terms, about the deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CV', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 1-year term-deposit rate could be read; the Banco de Cabo Verde site refused connections on 31 October 2026. The World Bank average deposit rate was 1.53% in 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CV', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 3-month term-deposit rate could be read; the Banco de Cabo Verde site refused connections on 31 October 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CV', 1, 'fixed_income_return_base', 0.012, NULL, 'assumption', 'World Bank deposit rate 1.53% (2025), PwC 20% tax on interest', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=CV', '2026-10-31', 'Base case: the average deposit rate after the 20% interest tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CV', 1, 'fixed_income_return_high', 0.03, NULL, 'assumption', 'PwC: Treasury bond interest taxed at 10%', 'https://taxsummaries.pwc.com/cabo-verde/individual/income-determination', '2026-10-31', 'High case: listed Treasury bonds, taxed at 10%, at a few points above deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CV', 1, 'fixed_income_return_low', 0.008, NULL, 'assumption', 'World Bank deposit rate 1.53% (2025), PwC 20% tax on interest', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=CV', '2026-10-31', 'Low case: deposit rates falling further, below 1% after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CV', 1, 'goal_inflation_education', 0.025, NULL, 'assumption', 'World Bank CPI inflation 2021-2025; Trading Economics CPI September 2026', 'https://tradingeconomics.com/cape-verde/inflation-cpi', '2026-10-31', 'No education CPI could be read, so education costs are planned slightly above the 2% general assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CV', 1, 'goal_inflation_health', 0.03, NULL, 'assumption', 'World Bank CPI inflation 2021-2025; Trading Economics CPI September 2026', 'https://tradingeconomics.com/cape-verde/inflation-cpi', '2026-10-31', 'No medical CPI could be read, so health costs are planned one point above the 2% general assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CV', 1, 'gold_return_base', 0.04, NULL, 'assumption', 'Escudo-euro peg at 110.265 per euro', 'https://tradingeconomics.com/cape-verde/currency', '2026-10-31', 'Base case: long-run dollar gold trend of about 4-5% a year with a stable euro peg.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CV', 1, 'gold_return_high', 0.08, NULL, 'assumption', 'Escudo-euro peg at 110.265 per euro', 'https://tradingeconomics.com/cape-verde/currency', '2026-10-31', 'High case: strong gold prices as in 2019-2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CV', 1, 'gold_return_low', 0, NULL, 'assumption', 'Escudo-euro peg at 110.265 per euro', 'https://tradingeconomics.com/cape-verde/currency', '2026-10-31', 'Low case: flat gold in euro terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CV', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No statutory end-of-service gratuity for private employees could be confirmed from an official source; PwC and CLEISS describe none.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CV', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a major private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CV', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premiums per 100,000 CVE of cover were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CV', 1, 'inflation_cpi', 0.027, NULL, 'sourced', 'Trading Economics, citing the Instituto Nacional de Estatística (INE), consumer prices, September 2026', 'https://tradingeconomics.com/cape-verde/inflation-cpi', '2026-09-30', 'Secondary source: the INE site is a script-only app that could not be read. Annual inflation 2.7% in September 2026 (0.8% in August); World Bank 2025 average 2.3%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CV', 1, 'inflation_projection', 0.02, NULL, 'assumption', 'World Bank CPI inflation 2021-2025 (FP.CPI.TOTL.ZG); escudo pegged to the euro', 'https://data.worldbank.org/indicator/FP.CPI.TOTL.ZG?locations=CV', '2026-10-31', 'The escudo is pegged to the euro (110.265 per euro), and inflation outside the 2022 shock has run near 1-3%, so 2% a year is used for long-range plans.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CV', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published term-life premium rates per 1,000 CVE of cover were found from the supervisor or another public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CV', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No industry-wide life claim settlement ratio was found; the Banco de Cabo Verde site refused connections on 31 October 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CV', 1, 'life_expectancy', 76.2, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN)', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=CV', '2024-12-31', '76.2 years in 2024 (men 73.1, women 79.4); UN WPP 2024 gives 76.6 for 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CV', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":21,"men":19.3,"women":22.7},{"age":65,"total":17,"men":15.4,"women":18.3},{"age":70,"total":13,"men":11.8,"women":14.1},{"age":80,"total":7.1,"men":6.5,"women":7.6}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/cabo-verde/', '2026-07-01', 'Secondary source of UN WPP 2024 (medium variant) for 2026; totals at 60, 70 and 80 are the mean of men and women (only the 65 total, 17.0, is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CV', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":60,"womenAge":60,"over90Monthly":null,"meansTested":true}', 'sourced', 'Centro Nacional de Pensões Sociais (CNPS), Pensão Social Básica: conditions', 'https://www.cnps.cv/index.php/pt/programa-de-inclusao-social/pensao-social-basica', '2020-07-21', 'Residents aged 60 or over whose household income is below the INE extreme-poverty line and who are not covered by any social security scheme; foreigners after 10 years of legal residence. Page last updated 2020 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CV', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'The basic social pension (Pensão Social Básica) exists, but its current monthly amount was not given on the CNPS pages that could be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CV', 1, 'oop_health_share', 0.2574, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=CV', '2023-12-31', '25.7% in 2023 (latest year; older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CV', 1, 'policy_rate', 0.025, NULL, 'sourced', 'Trading Economics, citing the Banco de Cabo Verde reference rate (taxa de referência)', 'https://tradingeconomics.com/cape-verde/interest-rate', '2026-10-31', 'Secondary source because the Banco de Cabo Verde site refused connections on 31 October 2026; reference rate 2.50%, unchanged in the October 2026 reading.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CV', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":65,"inflationLinked":false,"taxFree":null}', 'sourced', 'CLEISS (French social security liaison body), the Cabo Verde social security system: INPS old-age pension', 'https://www.cleiss.fr/docs/regimes/regime_capvert.html', '2024-06-28', 'Compulsory INPS pension for employees and the self-employed: 2% of the reference wage (best 10 of the last 15 years) per insured year, at most 80%, after 15 years of contributions; contributions 8.5% employee and 16% employer (PwC). No automatic indexation is described. Source is 2024 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CV', 1, 'retirement_accumulation_return_base', 0.03, NULL, 'assumption', 'World Bank deposit rate 1.53% (2025); equity base 5%', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=CV', '2026-10-31', 'Base case: a balanced mix of deposits, Treasury bonds and global shares, between the safe and equity base cases.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CV', 1, 'retirement_accumulation_return_high', 0.055, NULL, 'assumption', 'Escudo-euro peg; equity high case 8%', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=CV', '2026-10-31', 'High case: a larger share in global shares in a good decade.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CV', 1, 'retirement_accumulation_return_low', 0.015, NULL, 'assumption', 'World Bank deposit rate 1.53% (2025)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=CV', '2026-10-31', 'Low case: mostly deposits, a little in shares.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CV', 1, 'retirement_age_default', 65, NULL, 'sourced', 'CLEISS (French social security liaison body), the Cabo Verde social security system: INPS old-age pension', 'https://www.cleiss.fr/docs/regimes/regime_capvert.html', '2024-06-28', 'Men 65, women 60, after at least 15 years of contributions. Source describes the 2024 rules (older than 2025); no later change was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CV', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'No official text giving the retirement age of civil servants could be read; civil servants hired since 2006 are covered by the INPS scheme.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CV', 1, 'retirement_return_base', 0.012, NULL, 'assumption', 'World Bank deposit rate 1.53% (2025), PwC 20% tax on interest', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=CV', '2026-10-31', 'Base case: the average deposit rate after the 20% tax, so not above the after-tax safe rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CV', 1, 'retirement_return_high', 0.025, NULL, 'assumption', 'PwC: Treasury bond interest taxed at 10%', 'https://taxsummaries.pwc.com/cabo-verde/individual/income-determination', '2026-10-31', 'High case: part of the money in listed Treasury bonds taxed at 10%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CV', 1, 'retirement_return_low', 0.008, NULL, 'assumption', 'World Bank deposit rate 1.53% (2025), PwC 20% tax on interest', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=CV', '2026-10-31', 'Low case: deposits after tax if rates fall further.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CV', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate or retail savings bond for individuals was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CV', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No typical savings-account rate could be read; the Banco de Cabo Verde site refused connections on 31 October 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CV', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":9.53},{"year":2040,"value":6.06},{"year":2065,"value":2.34}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/cabo-verde/2040/', '2025-12-31', '100 / old-age dependency ratio: 10.50 (2025, World Bank), 16.5 (2040) and 42.7 (2065, populationpyramid.net/cabo-verde/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CV', 1, 'tax_bank_interest', 0.2, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Cabo Verde, individual income determination (Category D, investment income)', 'https://taxsummaries.pwc.com/cabo-verde/individual/income-determination', '2026-05-29', 'Investment income, including interest, is taxed at a flat 20% (page last reviewed 29 May 2026); interest on term deposits of Cabo Verdean emigrants is exempt.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CV', 1, 'tax_sanchayapatra_profit', 0.1, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Cabo Verde, individual income determination (Category D, investment income)', 'https://taxsummaries.pwc.com/cabo-verde/individual/income-determination', '2026-05-29', 'No savings certificate exists; interest on bonds, including Treasury bonds, is taxed at a flat 10% (page last reviewed 29 May 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CV', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No recent Treasury bill (Bilhetes do Tesouro) auction rate could be read; the Banco de Cabo Verde site refused connections on 31 October 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CV', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 10-year Treasury bond yield could be read; the Banco de Cabo Verde site refused connections on 31 October 2026 and Trading Economics has no Cabo Verde bond yield.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CV', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 5-year Treasury bond yield could be read; the Banco de Cabo Verde site refused connections on 31 October 2026 and Trading Economics has no Cabo Verde bond yield.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('CY', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"CY","iso3":"CYP","nameEn":"Cyprus","nameNative":"Κύπρος","region":"europe_central_asia","languages":["el","en","tr"],"currency":{"code":"EUR","symbol":"€","decimals":2,"compact":"intl","usdRate":{"value":0.8951,"status":"sourced","sourceName":"European Central Bank euro reference rate (USD)","sourceUrl":"https://data-api.ecb.europa.eu/service/data/EXR/D.USD.EUR.SP00.A","asOf":"2026-10-30","note":"EUR 1 = USD 1.1172, so about EUR 0.895 per US dollar; World Bank 2025 average 0.885."}},"instruments":{"savings_account":{"available":true,"localName":"Λογαριασμός ταμιευτηρίου","localNameEn":"Savings account","sourceUrl":"https://data-api.ecb.europa.eu/service/data/MIR/M.CY.B.L21.A.R.A.2250.EUR.N"},"fdr_3m":{"available":true,"localName":"Προθεσμιακή κατάθεση","localNameEn":"Fixed-term deposit (3 months)"},"fdr_1y":{"available":true,"localName":"Προθεσμιακή κατάθεση","localNameEn":"Fixed-term deposit (1 year)","sourceUrl":"https://data-api.ecb.europa.eu/service/data/MIR/M.CY.B.L22.F.R.A.2250.EUR.N"},"dps":{"available":false,"localName":null,"localNameEn":"Recurring deposit","note":"No standard monthly recurring deposit scheme with published rates was found."},"sanchayapatra_5y":{"available":true,"localName":"Ομόλογα Λιανικής","localNameEn":"Government retail bonds","note":"Sold to individuals by the Public Debt Management Office; interest bears the reduced 3% Special Defence Contribution. Current rate not found."},"tbill_91d":{"available":true,"localName":"Γραμμάτια Δημοσίου 13 εβδομάδων","localNameEn":"13-week treasury bills","note":"Auctioned mainly to banks and institutions."},"tbond_5y":{"available":true,"localName":"Κυβερνητικά ομόλογα","localNameEn":"Republic of Cyprus government bonds"},"tbond_10y":{"available":true,"localName":"Κυβερνητικά ομόλογα","localNameEn":"Republic of Cyprus government bonds","sourceUrl":"https://data-api.ecb.europa.eu/service/data/IRS/M.CY.L.L40.CI.0000.EUR.N.Z"},"equity_fund":{"available":true,"localName":"Αμοιβαίο κεφάλαιο (ΟΣΕΚΑ)","localNameEn":"Mutual fund (UCITS) / index fund","note":"EU UCITS funds and ETFs are sold to retail investors."},"gold":{"available":true,"localName":"Επενδυτικός χρυσός","localNameEn":"Investment gold bars and coins","note":"No restriction on buying physical gold."}},"institutions":{"centralBank":{"name":"Κεντρική Τράπεζα της Κύπρου (Central Bank of Cyprus)","url":"https://www.centralbank.cy/","note":"Part of the Eurosystem; monetary policy set by the European Central Bank."},"insuranceRegulator":{"name":"Insurance Companies Control Service (Ministry of Finance)","url":"https://www.gov.cy/mof/","note":"The Insurance Companies Control Service is part of the Ministry of Finance; EIOPA lists mof.gov.cy, which now redirects to this gov.cy page. The older mof.gov.cy/iccs address returns 404."},"insuranceComplaints":{"name":"Financial Ombudsman of the Republic of Cyprus","url":"https://financialombudsman.org.cy/"},"pensionScheme":{"name":"Social Insurance Services (Ministry of Labour)","url":"https://www.mlsi.gov.cy/mlsi/sid/sidv2.nsf/index_en/index_en?opendocument"},"oldAgeAllowance":{"name":"Social pension (Social Insurance Services)","url":"https://www.mlsi.gov.cy/mlsi/sid/sidv2.nsf/index_en/index_en?opendocument","note":"Social pension claims go to Social Insurance Services (European Commission guide, July 2026)."},"publicHealthCover":{"name":"General Healthcare System (ΓεΣΥ / GeSY), Health Insurance Organisation","url":"https://www.gesy.org.cy/"},"depositInsurance":{"name":"Deposit Guarantee and Resolution of Credit and Other Institutions Scheme","url":"https://www.centralbank.cy/en/deposit-guarantee-investors-compensation-schemes/deposit-guarantee-and-resolution-of-credit-and-other-institutions-scheme"},"statistics":{"name":"Cyprus Statistical Service (CYSTAT)","url":"https://www.cystat.gov.cy/en/default"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CY', 1, 'bank_deposit_avg_rate', 0.0089, NULL, 'sourced', 'ECB MFI interest rate statistics: Cypriot banks, household deposits with agreed maturity (outstanding amounts)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.CY.B.L22.A.R.A.2250.EUR.O', '2026-09-30', 'Average rate on all outstanding household term deposits, September 2026 (0.86% in August); World Bank FR.INR.DPST has no Cyprus figure.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CY', 1, 'credit_card_rate_cap', 0.116, NULL, 'sourced', 'Central Bank of Cyprus, reference interest rate under article 314A of the Penal Code', 'https://www.centralbank.cy/en/reference-interest-rates', '2026-10-30', 'Charging a borrower interest above this quarterly reference rate is a criminal offence, so it works as a legal ceiling on lending rates including cards (11.32% from 31 July 2026, 11.60% from 30 October 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CY', 1, 'deposit_insurance_limit', 100000, NULL, 'sourced', 'Central Bank of Cyprus, Deposit Guarantee and Resolution of Credit and Other Institutions Scheme', 'https://www.centralbank.cy/en/deposit-guarantee-investors-compensation-schemes/deposit-guarantee-and-resolution-of-credit-and-other-institutions-scheme', '2026-10-31', 'EUR 100,000 per depositor per credit institution, including accrued interest.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CY', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No monthly recurring deposit product with a published average rate was found for Cyprus.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CY', 1, 'equity_return_base', 0.05, NULL, 'assumption', 'CSE General index (Trading Economics); after-tax 1-year deposit 1.3%', 'https://tradingeconomics.com/cyprus/stock-market', '2026-10-31', 'Base case kept within 4 points of the after-tax safe rate because the local index has a very weak long record; most savers would use a diversified euro equity fund.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CY', 1, 'equity_return_high', 0.075, NULL, 'assumption', 'CSE General index (Trading Economics); global equity long-run returns', 'https://tradingeconomics.com/cyprus/stock-market', '2026-10-31', 'High case: a diversified euro equity fund matching long-run global equity returns of about 7-8% in euros.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CY', 1, 'equity_return_low', 0.025, NULL, 'assumption', 'CSE General index 308 on 30 Oct 2026, about 95% below its October 2007 peak of 5,575', 'https://tradingeconomics.com/cyprus/stock-market', '2026-10-31', 'Low case: Cypriot shares, a tiny bank-heavy market that collapsed in 2008-2013, earn little more than deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CY', 1, 'fdr_1y_rate', 0.0162, NULL, 'sourced', 'ECB MFI interest rate statistics: Cypriot banks, household deposits with agreed maturity up to 1 year (new business)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.CY.B.L22.F.R.A.2250.EUR.N', '2026-09-30', 'Bucket covers all fixed terms up to one year; 1.62% in September 2026 (1.35% in August). Re-checked against the ECB data API by the verifier.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CY', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'ECB/CBC MFI statistics publish household deposits with agreed maturity up to 1 year as one bucket (1.62% in September 2026); no separate 3-month rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CY', 1, 'fixed_income_return_base', 0.015, NULL, 'assumption', 'Household deposits up to 1 year 1.62% less 17% SDC = 1.3%; 10-year bond 3.92% less 3% SDC', 'https://data-api.ecb.europa.eu/service/data/MIR/M.CY.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Base case: mostly term deposits at about 1.3% after tax with some government bonds taxed at only 3%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CY', 1, 'fixed_income_return_high', 0.035, NULL, 'assumption', 'Cyprus 10-year government bond 3.92% less 3% SDC = 3.8%', 'https://data-api.ecb.europa.eu/service/data/IRS/M.CY.L.L40.CI.0000.EUR.N.Z', '2026-10-31', 'High case: holding long Cyprus government bonds after the reduced 3% contribution.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CY', 1, 'fixed_income_return_low', 0.008, NULL, 'assumption', 'Household deposits up to 1 year 1.62% (September 2026) less 17% SDC = 1.3%, with rates drifting lower', 'https://data-api.ecb.europa.eu/service/data/MIR/M.CY.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Low case: bank deposits after tax if rates fall further.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CY', 1, 'goal_inflation_education', 0.04, NULL, 'assumption', 'Eurostat/ECB HICP Cyprus, education: 3.3% year on year in December 2025', 'https://data-api.ecb.europa.eu/service/data/ICP/M.CY.N.100000.4.ANR', '2026-10-31', 'Education prices (largely private schools and universities) rise faster than headline inflation; 4% is used for planning.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CY', 1, 'goal_inflation_health', 0.035, NULL, 'assumption', 'Eurostat/ECB HICP Cyprus, health: 0.9% year on year in December 2025', 'https://data-api.ecb.europa.eu/service/data/ICP/M.CY.N.060000.4.ANR', '2026-10-31', 'Health prices are held down by GeSY fixed fees, but medical costs usually outrun headline inflation over decades, so 3.5% is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CY', 1, 'gold_return_base', 0.04, NULL, 'assumption', 'Gold price history (Trading Economics); ECB 2% inflation target', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Base case: dollar gold rises roughly with world inflation plus a little, and the euro is assumed stable against the dollar over the long run.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CY', 1, 'gold_return_high', 0.07, NULL, 'assumption', 'Gold price history (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'High case: a repeat of gold''s strong 2005-2025 trend in euro terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CY', 1, 'gold_return_low', 0.01, NULL, 'assumption', 'Gold USD 3,876/oz on 30 Oct 2026, 31% below the January 2026 high', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Low case: gold barely keeps up after the 2025-26 spike, with no help from the euro.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CY', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'Cyprus pays statutory redundancy compensation from the Redundancy Fund under the Termination of Employment Law, scaled by weeks of wages per year of service, but no official page with the current scale could be read (gov.cy refused automated access); there is no general retirement gratuity.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CY', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'Hospital care is covered by the General Healthcare System (GeSY) with small co-payments; no official figure for a typical out-of-pocket private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CY', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Private health insurance is sold mainly as GeSY top-up cover at flat premiums; no premium table per EUR 100,000 of cover was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CY', 1, 'inflation_cpi', 0.0369, NULL, 'sourced', 'Trading Economics (CYSTAT CPI, September 2026)', 'https://tradingeconomics.com/cyprus/inflation-cpi', '2026-09-30', 'CPI 3.69% year on year in September 2026 (3.52% in August), released 8 October 2026; secondary source because cystat.gov.cy was not read directly. World Bank 2025 average only 0.1%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CY', 1, 'inflation_projection', 0.025, NULL, 'assumption', 'ECB 2% medium-term target; Cyprus CPI 3.69% (Sep 2026) after 0.1% in 2025', 'https://tradingeconomics.com/cyprus/inflation-cpi', '2026-10-31', 'Cyprus inflation has swung between near zero and almost 4% in two years, so 2.5% (slightly above the ECB 2% target) is used for planning.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CY', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life is sold, but no published premium table or regulator data on term premiums per sum insured was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CY', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Insurance Companies Control Service and the Insurance Association of Cyprus do not publish an industry life claim settlement ratio that could be found; gov.cy pages refused automated access.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CY', 1, 'life_expectancy', 82.2, NULL, 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/cyprus', '2026-07-01', 'Men 80.2, women 84.1 (UN WPP estimate for 2026, mid-year); World Bank 2024 figure 81.8.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CY', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":23.9,"men":22.4,"women":25.4},{"age":65,"total":19.6,"men":18.2,"women":21},{"age":70,"total":15.7,"men":14.4,"women":16.8},{"age":80,"total":8.9,"men":8.1,"women":9.6}]}', 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/cyprus', '2026-07-01', 'Remaining years computed from georank''s expected age at death by current age (UN WPP 2026 estimate).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CY', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":65,"womenAge":65,"over90Monthly":null,"meansTested":false}', 'sourced', 'European Commission, Your social security rights in Cyprus (July 2026)', 'https://employment-social-affairs.ec.europa.eu/document/download/788be1e1-a21f-42a7-a201-a90e5e913bea_en', '2026-07-31', 'Residents aged 65+ with at least 20 years'' legal residence in the EU/EEA/Switzerland since age 40 (or 35 years since 18); not income-tested, but reduced by any other pension and not paid if that pension is at least the social pension rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CY', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'The social pension is 81% of the full basic statutory pension (European Commission guide, July 2026), plus a 13th payment in December, but no page stating the 2026 euro amount could be read (gov.cy refused automated access).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CY', 1, 'oop_health_share', 0.1794, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=CY', '2023-12-31', 'Latest World Bank/WHO figure is for 2023 (older than 2025); out-of-pocket spending fell sharply after GeSY started in 2019-2020.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CY', 1, 'policy_rate', 0.025, NULL, 'sourced', 'European Central Bank, deposit facility rate', 'https://data-api.ecb.europa.eu/service/data/FM/B.U2.EUR.4F.KR.DFR.LEV', '2026-09-16', 'Cyprus uses the euro; ECB deposit facility rate 2.50% (main refinancing rate 2.65%) from 16 September 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CY', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":65,"nomineeUntilAge":null,"inflationLinked":true,"taxFree":null}', 'sourced', 'European Commission, Your social security rights in Cyprus (July 2026)', 'https://employment-social-affairs.ec.europa.eu/document/download/788be1e1-a21f-42a7-a201-a90e5e913bea_en', '2026-07-31', 'Compulsory Social Insurance Scheme (employee and employer 8.8% each in 2026, rising every five years to 2039, per PwC); pensions are readjusted every year by insurable-earnings growth and the price index.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CY', 1, 'retirement_accumulation_return_base', 0.035, NULL, 'assumption', 'After-tax deposits 1.3%, government bonds 3.8% after SDC; equity base 5%', 'https://data-api.ecb.europa.eu/service/data/MIR/M.CY.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Base case: roughly half shares at 5% and half deposits and bonds at about 1.5-3.5% after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CY', 1, 'retirement_accumulation_return_high', 0.05, NULL, 'assumption', '10-year bond 3.8% after SDC; equity high 7.5%', 'https://data-api.ecb.europa.eu/service/data/IRS/M.CY.L.L40.CI.0000.EUR.N.Z', '2026-10-31', 'High case for a growth-leaning balanced mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CY', 1, 'retirement_accumulation_return_low', 0.02, NULL, 'assumption', 'After-tax 1-year deposit 1.3%; CSE General record', 'https://data-api.ecb.europa.eu/service/data/MIR/M.CY.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Low case for a balanced mix if shares lag.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CY', 1, 'retirement_age_default', 65, NULL, 'sourced', 'European Commission, Your social security rights in Cyprus (July 2026)', 'https://employment-social-affairs.ec.europa.eu/document/download/788be1e1-a21f-42a7-a201-a90e5e913bea_en', '2026-07-31', 'Pensionable age 65 for men and women; a statutory pension can start at 63 with a 12% lifelong reduction (6% a year early) if insurance conditions are met.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CY', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'Civil servants have their own pension scheme; no official page stating their current retirement age could be read (gov.cy refused automated access).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CY', 1, 'retirement_return_base', 0.013, NULL, 'assumption', 'Household deposits up to 1 year 1.62% (September 2026) less 17% SDC = 1.34%', 'https://data-api.ecb.europa.eu/service/data/MIR/M.CY.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Base case capped at the after-tax 1-year term deposit rate, as no treasury bill yield could be found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CY', 1, 'retirement_return_high', 0.03, NULL, 'assumption', 'Cyprus 10-year government bond 3.92% less 3% SDC = 3.8%', 'https://data-api.ecb.europa.eu/service/data/IRS/M.CY.L.L40.CI.0000.EUR.N.Z', '2026-10-31', 'High case: a ladder of Cyprus government and retail bonds taxed at 3%, below the current 10-year yield.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CY', 1, 'retirement_return_low', 0.008, NULL, 'assumption', 'Household deposits up to 1 year 1.62% (September 2026) less 17% SDC = 1.3%, with rates drifting lower', 'https://data-api.ecb.europa.eu/service/data/MIR/M.CY.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Low case: bank deposits after tax if rates fall further.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CY', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Public Debt Management Office sells retail government bonds to individuals, but its pages on gov.cy refused automated access and no current rate was read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CY', 1, 'savings_account_rate', 0, NULL, 'sourced', 'ECB MFI interest rate statistics: Cypriot banks, household overnight deposits (new business)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.CY.B.L21.A.R.A.2250.EUR.N', '2026-09-30', 'Average 0.00% on household overnight deposits in September 2026 (also 0.00% in August); notice deposits up to 3 months paid 0.03% in August.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CY', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":4.62},{"year":2040,"value":3.25},{"year":2065,"value":1.64}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/cyprus/2040/', '2025-12-31', '100 / old-age dependency ratio: 21.6 (2025, World Bank), 30.8 (2040) and 61.1 (2065, populationpyramid.net/cyprus/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CY', 1, 'tax_bank_interest', 0.17, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Cyprus taxes on personal income (Special Defence Contribution)', 'https://taxsummaries.pwc.com/cyprus/individual/taxes-on-personal-income', '2026-08-04', 'Interest is exempt from income tax but bears 17% Special Defence Contribution for Cyprus-resident, Cyprus-domiciled individuals; non-domiciled residents are exempt.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CY', 1, 'tax_sanchayapatra_profit', 0.03, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Cyprus taxes on personal income (Special Defence Contribution)', 'https://taxsummaries.pwc.com/cyprus/individual/taxes-on-personal-income', '2026-08-04', 'Reduced 3% SDC on interest from Cyprus government bonds (from 2026 also other EU government bonds); PwC does not say expressly that retail savings bonds are included.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CY', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Cyprus auctions 13-week treasury bills, but the Public Debt Management Office pages (gov.cy) refused automated access and no recent auction yield was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CY', 1, 'tbond_10y_rate', 0.0392, NULL, 'sourced', 'ECB long-term interest rate for convergence purposes (10-year government bond), Cyprus', 'https://data-api.ecb.europa.eu/service/data/IRS/M.CY.L.L40.CI.0000.EUR.N.Z', '2026-09-30', 'Monthly average for September 2026 (3.62% in August).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CY', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 5-year Cyprus government bond yield found; Trading Economics shows no Cyprus bond data and only the ECB 10-year convergence yield was available.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('CZ', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"CZ","iso3":"CZE","nameEn":"Czechia","nameNative":"Česko","region":"europe_central_asia","languages":["cs","en","sk","de"],"currency":{"code":"CZK","symbol":"Kč","decimals":2,"compact":"intl","usdRate":{"value":21.814,"status":"sourced","sourceName":"Czech National Bank exchange rate fixing (daily)","sourceUrl":"https://www.cnb.cz/en/financial-markets/foreign-exchange-market/central-bank-exchange-rate-fixing/central-bank-exchange-rate-fixing/daily.txt","asOf":"2026-10-30","note":"CZK 21.814 per US dollar and CZK 24.360 per euro on 30 October 2026; World Bank 2025 average 21.88."}},"instruments":{"savings_account":{"available":true,"localName":"Spořicí účet","localNameEn":"Savings account","sourceUrl":"https://data-api.ecb.europa.eu/service/data/MIR/M.CZ.B.L21.A.R.A.2250.CZK.N"},"fdr_3m":{"available":true,"localName":"Termínovaný vklad","localNameEn":"Fixed-term deposit (3 months)"},"fdr_1y":{"available":true,"localName":"Termínovaný vklad","localNameEn":"Fixed-term deposit (1 year)","sourceUrl":"https://data-api.ecb.europa.eu/service/data/MIR/M.CZ.B.L22.F.R.A.2250.CZK.N"},"dps":{"available":true,"localName":"Stavební spoření","localNameEn":"Building savings","note":"Regular saving with building societies over at least 6 years, with a yearly state contribution."},"sanchayapatra_5y":{"available":true,"localName":"Dluhopis Republiky (Flexi bond)","localNameEn":"Republic savings bond (Flexi bond)","note":"Sold by the Ministry of Finance directly to individuals with no fee via an online asset account; currently a 3-month bill that renews automatically, interest tax-free, early repayment without penalty.","sourceUrl":"https://dluhopisy.gov.cz/cs/o-dluhopisech/flexi-bond-poukazka"},"tbill_91d":{"available":true,"localName":"Státní pokladniční poukázky","localNameEn":"State treasury bills","note":"Retail investors buy them as the Flexi bond; institutional bills are auctioned by the CNB for the Ministry of Finance.","sourceUrl":"https://dluhopisy.gov.cz/cs/o-dluhopisech/urokove-sazby/urokove-sazby-emise-15-10-2026"},"tbond_5y":{"available":true,"localName":"Státní dluhopisy","localNameEn":"Czech government bonds"},"tbond_10y":{"available":true,"localName":"Státní dluhopisy","localNameEn":"Czech government bonds","sourceUrl":"https://tradingeconomics.com/czech-republic/government-bond-yield"},"equity_fund":{"available":true,"localName":"Podílový fond","localNameEn":"Mutual fund / index fund (ETF)","note":"Gains on securities held over 3 years are tax-exempt."},"gold":{"available":true,"localName":"Investiční zlato","localNameEn":"Investment gold bars and coins","note":"No restriction on buying physical gold; investment gold is VAT-exempt in the EU."}},"institutions":{"centralBank":{"name":"Česká národní banka (Czech National Bank)","url":"https://www.cnb.cz/"},"insuranceRegulator":{"name":"Česká národní banka (Czech National Bank), financial market supervision","url":"https://www.cnb.cz/","note":"The CNB supervises insurers as well as banks."},"insuranceComplaints":{"name":"Finanční arbitr (Financial Arbiter)","url":"https://www.finarbitr.cz/","note":"Out-of-court disputes with financial institutions, including life insurance."},"pensionScheme":{"name":"Česká správa sociálního zabezpečení (Czech Social Security Administration)","url":"https://www.cssz.gov.cz/"},"oldAgeAllowance":null,"publicHealthCover":{"name":"Ministerstvo zdravotnictví (Ministry of Health), compulsory public health insurance","url":"https://mzd.gov.cz/","note":"Compulsory public health insurance covers hospital care; it is run by statutory health insurance funds supervised by the Ministry of Health."},"depositInsurance":{"name":"Garanční systém finančního trhu (Financial Market Guarantee System)","url":"https://www.garancnisystem.cz/"},"statistics":{"name":"Český statistický úřad (Czech Statistical Office)","url":"https://csu.gov.cz/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CZ', 1, 'bank_deposit_avg_rate', 0.016, NULL, 'sourced', 'World Bank WDI FR.INR.DPST (deposit interest rate)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=CZ', '2025-12-31', 'Average deposit rate 1.60% in 2025, pulled down by low-rate sight deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CZ', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'Czech law sets no specific cap on credit card rates and no typical card rate was found; the ECB/CNB series for card credit to households returned no data.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CZ', 1, 'deposit_insurance_limit', 2436000, NULL, 'sourced', 'Garanční systém finančního trhu (Financial Market Guarantee System), deposit insurance', 'https://www.garancnisystem.cz/en/about-deposit-insurance', '2026-10-30', 'Cover is the equivalent of EUR 100,000 per depositor per bank (up to EUR 100,000 more in special cases); converted at the CNB rate of CZK 24.360 per euro on 30 October 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CZ', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Czechia''s regular-saving product is building savings (stavební spoření) with a state contribution; no current average rate was found from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CZ', 1, 'equity_return_base', 0.07, NULL, 'assumption', 'PX index (Trading Economics); Flexi bond 3.75% tax-free', 'https://tradingeconomics.com/czech-republic/stock-market', '2026-10-31', 'Base case: about 3 points over the tax-free state bill rate, kept within the 4-point limit despite the PX''s strong recent run.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CZ', 1, 'equity_return_high', 0.09, NULL, 'assumption', 'PX index (Trading Economics); global equity long-run returns', 'https://tradingeconomics.com/czech-republic/stock-market', '2026-10-31', 'High case: a diversified equity fund matching long-run global equity returns plus Czech inflation above the euro area.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CZ', 1, 'equity_return_low', 0.04, NULL, 'assumption', 'PX index 2,648 on 29 Oct 2026, up 11.5% in a year, near its September 2026 all-time high', 'https://tradingeconomics.com/czech-republic/stock-market', '2026-10-31', 'Low case: Czech shares, a small bank- and utility-heavy market, earn only a little more than tax-free state bills.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CZ', 1, 'fdr_1y_rate', 0.034, NULL, 'sourced', 'ECB MFI interest rate statistics: Czech banks, household deposits in CZK with agreed maturity up to 1 year (new business)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.CZ.B.L22.F.R.A.2250.CZK.N', '2026-09-30', 'Bucket covers all fixed terms up to one year; 3.40% in September 2026 (3.38% in August). Re-checked against the ECB data API by the verifier.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CZ', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'ECB/CNB MFI statistics publish household deposits with agreed maturity up to 1 year as one bucket (3.40% in September 2026); no separate 3-month rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CZ', 1, 'fixed_income_return_base', 0.033, NULL, 'assumption', 'Flexi bond 3.75% tax-free; 1-year deposit 2.9% after tax', 'https://dluhopisy.gov.cz/cs/o-dluhopisech/urokove-sazby/urokove-sazby-emise-15-10-2026', '2026-10-31', 'Base case: rolling tax-free retail state bills and term deposits, slightly below the current Flexi bond rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CZ', 1, 'fixed_income_return_high', 0.045, NULL, 'assumption', 'Czech 10-year government bond 5.36% less 15% withholding = 4.6%', 'https://tradingeconomics.com/czech-republic/government-bond-yield', '2026-10-31', 'High case: holding long Czech government bonds after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CZ', 1, 'fixed_income_return_low', 0.025, NULL, 'assumption', 'Household deposits up to 1 year 3.40% (September 2026) less 15% tax = 2.9%, with rates drifting lower', 'https://data-api.ecb.europa.eu/service/data/MIR/M.CZ.B.L22.F.R.A.2250.CZK.N', '2026-10-31', 'Low case: bank term deposits after tax if CNB rates fall.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CZ', 1, 'goal_inflation_education', 0.045, NULL, 'assumption', 'Eurostat/ECB HICP Czechia, education: 4.1% year on year in December 2025', 'https://data-api.ecb.europa.eu/service/data/ICP/M.CZ.N.100000.4.ANR', '2026-10-31', 'Education prices (mainly private schools and courses; public education is free) rise faster than headline inflation; 4.5% is used for planning.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CZ', 1, 'goal_inflation_health', 0.045, NULL, 'assumption', 'Eurostat/ECB HICP Czechia, health: 3.3% year on year in December 2025', 'https://data-api.ecb.europa.eu/service/data/ICP/M.CZ.N.060000.4.ANR', '2026-10-31', 'Health prices have run above headline inflation; 4.5% is used as a long-run planning figure.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CZ', 1, 'gold_return_base', 0.04, NULL, 'assumption', 'Gold price history (Trading Economics); CZK 21.8 per USD (CNB)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Base case: dollar gold rises roughly with world inflation plus a little, and the koruna is assumed stable against the dollar over the long run.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CZ', 1, 'gold_return_high', 0.07, NULL, 'assumption', 'Gold price history (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'High case: a repeat of gold''s strong 2005-2025 trend in koruna terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CZ', 1, 'gold_return_low', 0.01, NULL, 'assumption', 'Gold USD 3,876/oz on 30 Oct 2026, 31% below the January 2026 high', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Low case: gold barely keeps up after the 2025-26 spike while the koruna holds firm against the dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CZ', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Labour Code gives severance pay (odstupné) only on redundancy, as a flat 1-3 months'' average earnings by length of service rather than days per year, and there is no statutory retirement gratuity; the Labour Code text was not read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CZ', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'Hospital care is covered by compulsory public health insurance with no hospital fee for most patients; no official figure for a typical out-of-pocket private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CZ', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Private health insurance is a small market of supplementary policies not priced per sum insured; no premium table per CZK 100,000 of cover was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CZ', 1, 'inflation_cpi', 0.025, NULL, 'sourced', 'Trading Economics (Czech Statistical Office CPI, September 2026 final)', 'https://tradingeconomics.com/czech-republic/inflation-cpi', '2026-09-30', 'CPI 2.5% year on year in September 2026 (1.9% in August), final figure released 13 October 2026; secondary source because csu.gov.cz was not read directly. World Bank 2025 average 2.5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CZ', 1, 'inflation_projection', 0.025, NULL, 'assumption', 'Czech National Bank 2% CPI target with a ±1 point tolerance band; CPI 2.5% (Sep 2026)', 'https://www.cnb.cz/en/monetary-policy/inflation-target/', '2026-10-31', 'The CNB target is credible, but Czech inflation has averaged above 2% in recent years, so 2.5% is used for planning.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CZ', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life (rizikové životní pojištění) is widely sold, but no published premium table or regulator data on term premiums per sum insured was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CZ', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The CNB and the Czech Insurance Association publish premium and claims totals but no industry life claim settlement ratio could be found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CZ', 1, 'life_expectancy', 80.3, NULL, 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/czech-republic', '2026-07-01', 'Men 77.5, women 83.0 (UN WPP estimate for 2026, mid-year); World Bank 2024 figure 80.0.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CZ', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":22.9,"men":20.8,"women":24.8},{"age":65,"total":18.9,"men":17,"women":20.5},{"age":70,"total":15.1,"men":13.6,"women":16.3},{"age":80,"total":8.5,"men":7.7,"women":9}]}', 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/czech-republic', '2026-07-01', 'Remaining years computed from georank''s expected age at death by current age (UN WPP 2026 estimate).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CZ', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'Confirmed absent: no non-contributory old-age pension exists in Czechia (European Commission guide ''Your social security rights in the Czech Republic'', July 2026); low-income older people rely on the means-tested state social assistance benefit.', 1);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CZ', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'Confirmed absent: the European Commission guide ''Your social security rights in the Czech Republic'' (July 2026, employment-social-affairs.ec.europa.eu) lists only the contributory old-age pension (minimum CZK 9,800 a month in 2026 with the insurance record) and, for people without income, the means-tested state social assistance benefit (dávka státní sociální pomoci, since 1 October 2025); there is no non-contributory social pension.', 1);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CZ', 1, 'oop_health_share', 0.1406, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=CZ', '2024-12-31', NULL, 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CZ', 1, 'policy_rate', 0.0375, NULL, 'sourced', 'Czech National Bank, two-week repo rate history', 'https://www.cnb.cz/en/faq/How-has-the-CNB-two-week-repo-rate-changed-over-time/', '2026-06-19', '2W repo rate raised from 3.50% to 3.75% with effect from 19 June 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CZ', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":67,"nomineeUntilAge":null,"inflationLinked":true,"taxFree":null}', 'sourced', 'Czech Social Security Administration (ČSSZ), retirement age', 'https://www.cssz.gov.cz/web/lang/duchodovy-vek', '2026-04-16', 'Compulsory pay-as-you-go pension insurance (social security 7.1% employee and 24.8% employer in 2026, per PwC); pension age rises by birth year to 67 for those born after 1988 (65y11m to 66y11m for those born 1976-1988). Pensions are raised every January by law (price growth plus part of real wage growth); that rule was not confirmed on a page read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CZ', 1, 'retirement_accumulation_return_base', 0.055, NULL, 'assumption', 'Flexi bond 3.75% tax-free; equity base 7%', 'https://dluhopisy.gov.cz/cs/o-dluhopisech/urokove-sazby/urokove-sazby-emise-15-10-2026', '2026-10-31', 'Base case: roughly half shares at 7% and half safe fixed income at about 3.3-4.5% after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CZ', 1, 'retirement_accumulation_return_high', 0.07, NULL, 'assumption', '10-year bond 4.6% after tax; equity high 9%', 'https://tradingeconomics.com/czech-republic/government-bond-yield', '2026-10-31', 'High case for a growth-leaning balanced mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CZ', 1, 'retirement_accumulation_return_low', 0.04, NULL, 'assumption', 'Flexi bond 3.75% tax-free; PX record', 'https://dluhopisy.gov.cz/cs/o-dluhopisech/urokove-sazby/urokove-sazby-emise-15-10-2026', '2026-10-31', 'Low case for a balanced mix if shares lag.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CZ', 1, 'retirement_age_default', 67, NULL, 'sourced', 'Czech Social Security Administration (ČSSZ), retirement age', 'https://www.cssz.gov.cz/web/lang/duchodovy-vek', '2026-04-16', 'ČSSZ table (updated 16 April 2026): people born 1974-1988 retire at 65 years 8 months plus one month per birth year after 1973 (65y11m for 1976, 66y11m for 1988), and everyone born after 1988 at 67. 67 is used as the age for planners born after 1975; people retiring in 2026 do so at about 64-65. 35 insurance years required.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CZ', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'Government employees are in the general pension insurance scheme; no source read stated a separate mandatory retirement age for civil servants.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CZ', 1, 'retirement_return_base', 0.033, NULL, 'assumption', 'Flexi bond 3.75% tax-free (Ministry of Finance)', 'https://dluhopisy.gov.cz/cs/o-dluhopisech/urokove-sazby/urokove-sazby-emise-15-10-2026', '2026-10-31', 'Base case capped below the tax-free retail state bill rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CZ', 1, 'retirement_return_high', 0.042, NULL, 'assumption', 'Czech 10-year government bond 5.36% less 15% withholding = 4.6%', 'https://tradingeconomics.com/czech-republic/government-bond-yield', '2026-10-31', 'High case: a ladder of longer government bonds after tax, below the current 10-year yield.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CZ', 1, 'retirement_return_low', 0.025, NULL, 'assumption', 'Household deposits up to 1 year 3.40% (September 2026) less 15% tax = 2.9%, with rates drifting lower', 'https://data-api.ecb.europa.eu/service/data/MIR/M.CZ.B.L22.F.R.A.2250.CZK.N', '2026-10-31', 'Low case: bank term deposits after tax if CNB rates fall.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CZ', 1, 'sanchayapatra_5y_rate', 0.0375, NULL, 'sourced', 'Ministry of Finance, Dluhopisy Republiky: interest rate of the Flexi bond issued 15 October 2026', 'https://dluhopisy.gov.cz/cs/o-dluhopisech/urokove-sazby/urokove-sazby-emise-15-10-2026', '2026-10-15', 'The retail savings bond now on sale is the Flexi bond, an exchangeable 3-month state treasury bill for individuals that renews automatically; 3.75% a year for 15 Oct 2026 to 15 Jan 2027. No 5-year retail bond is currently offered.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CZ', 1, 'savings_account_rate', 0.0155, NULL, 'sourced', 'ECB MFI interest rate statistics: Czech banks, household overnight deposits in CZK (new business)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.CZ.B.L21.A.R.A.2250.CZK.N', '2026-09-30', 'Average 1.55% on household overnight deposits (current and most savings accounts) in September 2026 (1.54% in August); notice deposits up to 3 months paid 1.94% in August.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CZ', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":3.01},{"year":2040,"value":2.37},{"year":2065,"value":1.95}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/czech-republic/2040/', '2025-12-31', '100 / old-age dependency ratio: 33.2 (2025, World Bank), 42.2 (2040) and 51.3 (2065, populationpyramid.net/czech-republic/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CZ', 1, 'tax_bank_interest', 0.15, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Czech Republic income determination', 'https://taxsummaries.pwc.com/czech-republic/individual/income-determination', '2026-07-27', '15% final withholding tax on interest from deposit accounts for resident individuals.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CZ', 1, 'tax_sanchayapatra_profit', 0, NULL, 'sourced', 'Ministry of Finance, Dluhopisy Republiky: Flexi bond', 'https://dluhopisy.gov.cz/cs/o-dluhopisech/flexi-bond-poukazka', '2026-10-31', 'Yields on the retail Flexi bond are exempt from income tax, unlike term deposit interest.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CZ', 1, 'tbill_91d_rate', 0.0375, NULL, 'sourced', 'Ministry of Finance, Dluhopisy Republiky: Flexi bond (exchangeable state treasury bill) issue of 15 October 2026', 'https://dluhopisy.gov.cz/cs/o-dluhopisech/urokove-sazby/urokove-sazby-emise-15-10-2026', '2026-10-15', 'Retail 3-month state treasury bill rate (15 Oct 2026 to 15 Jan 2027); yields on institutional treasury bill auctions were not found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CZ', 1, 'tbond_10y_rate', 0.0536, NULL, 'sourced', 'Trading Economics, Czech Republic 10-year government bond yield', 'https://tradingeconomics.com/czech-republic/government-bond-yield', '2026-10-30', 'ECB long-term (10-year) convergence yield for Czechia was 5.24% in September 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('CZ', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 5-year Czech government bond yield found: Trading Economics showed only the 10-year yield and worldgovernmentbonds.com did not load data.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('DE', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"DE","iso3":"DEU","nameEn":"Germany","nameNative":"Deutschland","region":"europe_central_asia","languages":["de","en","fr","nl","it"],"currency":{"code":"EUR","symbol":"€","decimals":2,"compact":"intl","usdRate":{"value":0.8951,"status":"sourced","sourceName":"European Central Bank euro reference rate (USD)","sourceUrl":"https://data-api.ecb.europa.eu/service/data/EXR/D.USD.EUR.SP00.A","asOf":"2026-10-30","note":"EUR 1 = USD 1.1172 on 30 October 2026, so about EUR 0.895 per US dollar; World Bank 2025 average 0.885."}},"instruments":{"savings_account":{"available":true,"localName":"Tagesgeldkonto / Sparbuch","localNameEn":"Instant-access savings account / passbook savings","sourceUrl":"https://data-api.ecb.europa.eu/service/data/MIR/M.DE.B.L21.A.R.A.2250.EUR.N"},"fdr_3m":{"available":true,"localName":"Festgeld","localNameEn":"Fixed-term deposit (3 months)"},"fdr_1y":{"available":true,"localName":"Festgeld","localNameEn":"Fixed-term deposit (1 year)","sourceUrl":"https://data-api.ecb.europa.eu/service/data/MIR/M.DE.B.L22.F.R.A.2250.EUR.N"},"dps":{"available":true,"localName":"Banksparplan / Bausparvertrag","localNameEn":"Bank savings plan / building-society savings contract","note":"Regular monthly saving; Bausparverträge can attract state savings premiums for lower incomes."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"Federal savings bonds (Bundesschatzbriefe) were discontinued in 2013."},"tbill_91d":{"available":true,"localName":"Unverzinsliche Schatzanweisungen (Bubills)","localNameEn":"Federal Treasury discount paper","note":"Auctioned by the Finance Agency mainly to institutions; can be bought through a bank or broker.","sourceUrl":"https://tradingeconomics.com/germany/government-bond-yield"},"tbond_5y":{"available":true,"localName":"Bundesobligation","localNameEn":"Five-year federal note"},"tbond_10y":{"available":true,"localName":"Bundesanleihe","localNameEn":"Federal bond (Bund)","sourceUrl":"https://tradingeconomics.com/germany/government-bond-yield"},"equity_fund":{"available":true,"localName":"Investmentfonds / Indexfonds (ETF)","localNameEn":"Mutual funds and index funds (ETF)","note":"Widely available, often through monthly ETF savings plans; gains taxed at 26.375% with partial exemptions for equity funds."},"gold":{"available":true,"localName":"Goldbarren und Goldmünzen","localNameEn":"Gold bars and coins","note":"Investment gold is VAT-free and gains are tax-free after one year of holding."}},"institutions":{"centralBank":{"name":"Deutsche Bundesbank","url":"https://www.bundesbank.de/","note":"Part of the Eurosystem; monetary policy set by the European Central Bank."},"insuranceRegulator":{"name":"Bundesanstalt für Finanzdienstleistungsaufsicht (BaFin)","url":"https://www.bafin.de/"},"insuranceComplaints":{"name":"Versicherungsombudsmann","url":"https://www.versicherungsombudsmann.de/","note":"Free ombudsman for disputes with insurers; complaints can also go to BaFin. Private health insurance has its own PKV ombudsman."},"pensionScheme":{"name":"Deutsche Rentenversicherung (statutory pension insurance)","url":"https://www.deutsche-rentenversicherung.de/"},"oldAgeAllowance":{"name":"Grundsicherung im Alter (means-tested basic income in old age)","url":"https://www.gesetze-im-internet.de/sgb_12/__41.html"},"publicHealthCover":{"name":"Gesetzliche Krankenversicherung (GKV-Spitzenverband)","url":"https://www.gkv-spitzenverband.de/"},"depositInsurance":{"name":"Entschädigungseinrichtung deutscher Banken (EdB)","url":"https://www.edb-banken.de/"},"statistics":{"name":"Statistisches Bundesamt (Destatis)","url":"https://www.destatis.de/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DE', 1, 'bank_deposit_avg_rate', 0.0181, NULL, 'sourced', 'ECB MFI interest rate statistics: German banks, household deposits with agreed maturity (outstanding amounts)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.DE.B.L22.A.R.A.2250.EUR.O', '2026-09-30', 'Average rate on all outstanding household term deposits, September 2026 (1.76% in August); household overnight deposits paid 0.52%. World Bank FR.INR.DPST has no Germany figure.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DE', 1, 'credit_card_rate_cap', 0.0946, NULL, 'sourced', 'ECB MFI interest rate statistics: German banks, revolving loans, overdrafts and credit card credit to households', 'https://data-api.ecb.europa.eu/service/data/MIR/M.DE.B.A2Z.A.R.A.2250.EUR.N', '2026-09-30', 'No legal cap beyond the general ban on usurious interest; figure is the average rate on revolving loans, overdrafts and extended credit card credit combined, September 2026 (no card-only series).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DE', 1, 'deposit_insurance_limit', 100000, NULL, 'sourced', 'Entschädigungseinrichtung deutscher Banken (EdB)', 'https://www.edb-banken.de/fragen-und-antworten', '2026-10-31', 'EUR 100,000 per customer per bank, interest included; up to EUR 500,000 when certain life events (home sale, marriage, divorce, death, retirement, severance) occur within six months of the money being credited. Savings and cooperative banks are covered by their own protection schemes.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DE', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Banks sell monthly savings plans (Banksparplan) and building societies sell Bausparverträge, but no average rate from an official source was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DE', 1, 'equity_return_base', 0.055, NULL, 'assumption', 'DAX performance index (Trading Economics); 3-month Bubill 2.51% less 26.375% = 1.85%', 'https://tradingeconomics.com/germany/stock-market', '2026-10-31', 'The DAX (a total-return index) has a strong 10-year record (about 10,600 in late 2016 to 25,818), but the base is held to the after-tax safe rate plus about 4 points.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DE', 1, 'equity_return_high', 0.075, NULL, 'assumption', 'DAX performance index (Trading Economics); long-run global equity returns', 'https://tradingeconomics.com/germany/stock-market', '2026-10-31', 'High case: a diversified equity fund matching long-run global equity returns of about 7-8% in euros.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DE', 1, 'equity_return_low', 0.03, NULL, 'assumption', 'DAX 25,818 on 30 Oct 2026, up 7.8% in a year (Trading Economics); after-tax safe rate about 1.7%', 'https://tradingeconomics.com/germany/stock-market', '2026-10-31', 'Low case: German shares earn little more than safe savings over a long period, as in 2000-2012.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DE', 1, 'fdr_1y_rate', 0.0239, NULL, 'sourced', 'ECB MFI interest rate statistics: German banks, household deposits with agreed maturity up to 1 year (new business)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.DE.B.L22.F.R.A.2250.EUR.N', '2026-09-30', 'Bucket covers all fixed terms up to one year (new business, September 2026; 2.28% in August).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DE', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'ECB/Bundesbank MFI statistics publish household deposits with agreed maturity up to 1 year as one bucket (2.39% in September 2026); no 3-month Festgeld rate from an official source was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DE', 1, 'fixed_income_return_base', 0.017, NULL, 'assumption', 'Household deposits up to 1 year 2.39% (Sep 2026) less 26.375% = 1.76%', 'https://data-api.ecb.europa.eu/service/data/MIR/M.DE.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Base case: just under the after-tax 1-year term deposit rate (the yearly EUR 1,000 tax-free allowance can lift this for small savers).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DE', 1, 'fixed_income_return_high', 0.024, NULL, 'assumption', 'Germany 10-year Bund 3.32% less 26.375% = 2.4% (Trading Economics)', 'https://tradingeconomics.com/germany/government-bond-yield', '2026-10-31', 'High case: holding long federal bonds after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DE', 1, 'fixed_income_return_low', 0.008, NULL, 'assumption', 'Household savings deposits at notice 0.76% (ECB MFI statistics, Sep 2026); online overnight accounts pay more', 'https://data-api.ecb.europa.eu/service/data/MIR/M.DE.B.L23.D.R.A.2250.EUR.N', '2026-10-31', 'Low case: easy-access savings after tax, with rates drifting lower.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DE', 1, 'goal_inflation_education', 0.04, NULL, 'assumption', 'Eurostat/ECB HICP Germany, education: 5.0% year on year in December 2025', 'https://data-api.ecb.europa.eu/service/data/ICP/M.DE.N.100000.4.ANR', '2026-10-31', 'Public schooling and university tuition are mostly free, but fee-paying education (childcare, private schools, courses) has risen well above headline inflation, so 4% is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DE', 1, 'goal_inflation_health', 0.035, NULL, 'assumption', 'Eurostat/ECB HICP Germany, health: 2.3% year on year in December 2025', 'https://data-api.ecb.europa.eu/service/data/ICP/M.DE.N.060000.4.ANR', '2026-10-31', 'Measured health prices rise close to headline inflation, but health insurance contributions and private care costs rise faster, so 3.5% is used for planning.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DE', 1, 'gold_return_base', 0.04, NULL, 'assumption', 'Gold price history (Trading Economics); ECB 2% inflation target', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Base case: dollar gold rises roughly with world inflation plus a little, and the euro is assumed stable against the dollar; gains are tax-free after one year.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DE', 1, 'gold_return_high', 0.07, NULL, 'assumption', 'Gold price history (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'High case: a repeat of gold''s strong 2005-2025 trend in euro terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DE', 1, 'gold_return_low', 0.01, NULL, 'assumption', 'Gold USD 3,876/oz on 30 Oct 2026, 31% below the January 2026 high (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Low case: gold barely keeps up after the 2025-26 spike, with no help from the euro.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DE', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No general statutory gratuity or end-of-service payment was found; section 1a Kündigungsschutzgesetz gives half a month''s pay per year of service only when the employer dismisses for operational reasons, offers it in the notice and the employee does not sue (gesetze-im-internet.de/kschg/__1a.html); otherwise severance comes only from a settlement or social plan. Not marked absent because no official page stating that no general entitlement exists was read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DE', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'Statutory health insurance covers hospital stays with a patient co-payment of EUR 10 a day (up to 28 days a year); no official figure for a typical out-of-pocket cost of a major private or mid-range hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DE', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Private health insurance (PKV) is priced by age at entry and benefit tariff, not per sum insured, and no published premium table per EUR 100,000 of cover was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DE', 1, 'inflation_cpi', 0.028, NULL, 'sourced', 'Trading Economics (Destatis CPI, October 2026 preliminary)', 'https://tradingeconomics.com/germany/inflation-cpi', '2026-10-31', 'Destatis flash estimate published 30 October 2026: CPI up 2.8% year on year (3.3% in September); final figure due 11 November 2026; secondary source because destatis.de was not read directly. World Bank 2025 average 2.2%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DE', 1, 'inflation_projection', 0.022, NULL, 'assumption', 'ECB 2% medium-term target; German CPI 2.8% (Oct 2026), 2.2% in 2025 (World Bank)', 'https://tradingeconomics.com/germany/inflation-cpi', '2026-10-31', 'The ECB 2% target is credible, but German inflation has run slightly above it since 2021, so 2.2% is used for planning.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DE', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life (Risikolebensversicherung) is widely sold, but no published premium table per EUR 1,000 of cover by age was found; comparison sites were not read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DE', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'BaFin and the German insurance association (GDV) do not publish an industry-wide life claim settlement ratio that could be found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DE', 1, 'life_expectancy', 81.9, NULL, 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/germany', '2026-07-01', 'Men 79.6, women 84.1 (UN WPP estimate for 2026); World Bank 2024 figure 80.8.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DE', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":24.3,"men":22.5,"women":26},{"age":65,"total":20.2,"men":18.7,"women":21.7},{"age":70,"total":16.3,"men":15,"women":17.5},{"age":80,"total":9.2,"men":8.4,"women":9.8}]}', 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/germany', '2026-07-01', 'Remaining years computed from georank''s expected age at death by current age (UN WPP 2026 estimate, mid-year).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DE', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":67,"womenAge":67,"over90Monthly":null,"meansTested":true}', 'sourced', 'Sozialgesetzbuch XII section 41 (gesetze-im-internet.de)', 'https://www.gesetze-im-internet.de/sgb_12/__41.html', '2026-10-31', 'From the standard pension age (67 for people born from 1964, phased in for earlier years), for people habitually resident in Germany who cannot cover their needs from income and assets.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DE', 1, 'old_age_allowance_monthly', 563, NULL, 'sourced', 'Sozialgesetzbuch XII, Anlage zu section 28 (Regelbedarfsstufe 1, from 1 January 2026)', 'https://www.gesetze-im-internet.de/sgb_12/anlage.html', '2026-01-01', 'Grundsicherung im Alter is means-tested: the standard need for a single adult is EUR 563 a month, and reasonable rent and heating costs are paid on top, less the person''s own income and assets.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DE', 1, 'oop_health_share', 0.1071, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=DE', '2024-12-31', 'Latest World Bank figure is for 2024 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DE', 1, 'policy_rate', 0.025, NULL, 'sourced', 'European Central Bank, key ECB interest rates (deposit facility)', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.en.html', '2026-09-16', 'Germany uses the euro; ECB deposit facility rate 2.50% (main refinancing 2.65%) since 16 September 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DE', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":67,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":false}', 'sourced', 'Sozialgesetzbuch VI section 68 (pension value adjustment) and section 35 (gesetze-im-internet.de)', 'https://www.gesetze-im-internet.de/sgb_6/__68.html', '2026-10-31', 'Compulsory statutory pension insurance (Deutsche Rentenversicherung) for employees; the pension value is adjusted each 1 July with gross wages per employee, damped by the contribution-rate and sustainability factors, so it is wage-linked rather than price-indexed; pensions are taxed as income.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DE', 1, 'retirement_accumulation_return_base', 0.035, NULL, 'assumption', 'After-tax 1-year deposit 1.76%; equity base 5.5%', 'https://data-api.ecb.europa.eu/service/data/MIR/M.DE.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Base case: roughly half shares at 5.5% and half safe fixed income at about 1.7-2.4% after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DE', 1, 'retirement_accumulation_return_high', 0.05, NULL, 'assumption', 'After-tax 10-year Bund 2.4%; equity high 7.5%', 'https://tradingeconomics.com/germany/government-bond-yield', '2026-10-31', 'High case for a growth-leaning balanced mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DE', 1, 'retirement_accumulation_return_low', 0.025, NULL, 'assumption', 'After-tax 1-year deposit 1.76%; DAX record (Trading Economics)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.DE.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Low case for a balanced mix if shares lag.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DE', 1, 'retirement_age_default', 67, NULL, 'sourced', 'Sozialgesetzbuch VI, section 35 (standard age 67) and section 235 (transition), gesetze-im-internet.de', 'https://www.gesetze-im-internet.de/sgb_6/__35.html', '2026-10-31', 'Standard pension age (Regelaltersgrenze) 67 under section 35, which applies to everyone born from 1964 (so to anyone born after 1975); section 235 sets transitional ages of 66 years 4 months (born 1960) to 66 y 10 m (1963); same for men and women; minimum 5 insurance years.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DE', 1, 'retirement_age_government', 67, NULL, 'sourced', 'Bundesbeamtengesetz section 51 (gesetze-im-internet.de)', 'https://www.gesetze-im-internet.de/bbg_2009/__51.html', '2026-10-31', 'Federal civil servants (Beamte) reach the regular age limit at 67, phased in by birth year like the statutory pension; state civil servants follow similar state laws.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DE', 1, 'retirement_return_base', 0.017, NULL, 'assumption', 'Household deposits up to 1 year 2.39% (Sep 2026) less 26.375% = 1.76%', 'https://data-api.ecb.europa.eu/service/data/MIR/M.DE.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Base case capped just under the after-tax 1-year term deposit rate (1.76%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DE', 1, 'retirement_return_high', 0.022, NULL, 'assumption', 'Germany 10-year Bund 3.32% less 26.375% = 2.4% (Trading Economics)', 'https://tradingeconomics.com/germany/government-bond-yield', '2026-10-31', 'High case: a ladder of longer federal bonds after tax, slightly below the 10-year yield.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DE', 1, 'retirement_return_low', 0.008, NULL, 'assumption', 'Household savings deposits at notice 0.76% (ECB MFI statistics, Sep 2026); online overnight accounts pay more', 'https://data-api.ecb.europa.eu/service/data/MIR/M.DE.B.L23.D.R.A.2250.EUR.N', '2026-10-31', 'Low case: easy-access savings after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DE', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Germany stopped selling federal savings bonds (Bundesschatzbriefe) and Finanzierungsschätze to individuals in 2013; no retail government savings certificate exists.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DE', 1, 'savings_account_rate', 0.0052, NULL, 'sourced', 'ECB MFI interest rate statistics: German banks, overnight deposits from households (new business)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.DE.B.L21.A.R.A.2250.EUR.N', '2026-09-30', 'Average rate on household overnight deposits (Tagesgeld, current accounts) in Germany, September 2026 (0.51% in August); savings deposits at up to 3 months'' notice (Sparbuch) paid 0.76%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DE', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":2.63},{"year":2040,"value":1.95},{"year":2065,"value":1.86}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/germany/2040/', '2025-12-31', '100 / old-age dependency ratio: 38.0 (2025, World Bank), 51.3 (2040) and 53.9 (2065, populationpyramid.net/germany/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DE', 1, 'tax_bank_interest', 0.26375, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Germany income determination', 'https://taxsummaries.pwc.com/germany/individual/income-determination', '2026-10-31', 'Flat withholding tax (Abgeltungsteuer) of 25% plus 5.5% solidarity surcharge = 26.375%, plus church tax for church members; the first EUR 1,000 of investment income a year (EUR 2,000 for couples) is tax-free.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DE', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate exists for individuals in Germany, so no specific tax rate applies.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DE', 1, 'tbill_91d_rate', 0.0251, NULL, 'sourced', 'Trading Economics, Germany 3-month bill yield', 'https://tradingeconomics.com/germany/government-bond-yield', '2026-10-30', 'Market yield on 3-month federal Treasury discount paper (Bubills); 6-month 2.68%, 52-week 2.89%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DE', 1, 'tbond_10y_rate', 0.0332, NULL, 'sourced', 'Trading Economics, Germany 10-year Bund yield', 'https://tradingeconomics.com/germany/government-bond-yield', '2026-10-30', 'ECB long-term (10-year) convergence yield for Germany was 3.47% in September 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DE', 1, 'tbond_5y_rate', 0.0311, NULL, 'sourced', 'Trading Economics, Germany 5-year federal bond yield', 'https://tradingeconomics.com/germany/government-bond-yield', '2026-10-30', NULL, 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('DJ', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"DJ","iso3":"DJI","nameEn":"Djibouti","nameNative":"Djibouti","region":"middle_east_north_africa","languages":["aa","so","ar","fr"],"currency":{"code":"DJF","symbol":"Fdj","decimals":0,"compact":"intl","usdRate":{"value":177.721,"status":"sourced","sourceName":"World Bank WDI, official exchange rate (PA.NUS.FCRF), Djibouti","sourceUrl":"https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=DJ","asOf":"2025-12-31","note":"The franc has been fixed to the US dollar under a currency board since 1949, and the parity has not changed since 1973. The Banque Centrale de Djibouti currency-board page states the historical 1949 parity, not the current rate, so the World Bank figure of 177.721 is used. CLDR gives no narrow symbol; ''Fdj'' is the local abbreviation."}},"instruments":{"savings_account":{"available":true,"localName":"Compte d''épargne","localNameEn":"Savings account"},"fdr_3m":{"available":true,"localName":"Dépôt à terme (3 mois)","localNameEn":"Term deposit (3 months)"},"fdr_1y":{"available":true,"localName":"Dépôt à terme (1 an)","localNameEn":"Term deposit (1 year)"},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No standard monthly recurring deposit product was found."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate for individuals was found."},"tbill_91d":{"available":false,"localName":null,"localNameEn":null,"note":"No domestic Treasury bill market was found."},"tbond_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No domestic government bond market was found."},"tbond_10y":{"available":false,"localName":null,"localNameEn":null,"note":"No domestic government bond market was found."},"equity_fund":{"available":false,"localName":null,"localNameEn":null,"note":"There is no stock exchange in Djibouti and no locally sold equity fund was found; investors can only use foreign funds."},"gold":{"available":true,"localName":"Or","localNameEn":"Gold","note":"Gold is sold freely, mostly as jewellery."}},"institutions":{"centralBank":{"name":"Central Bank of Djibouti (Banque Centrale de Djibouti)","url":"https://banque-centrale.dj/"},"insuranceRegulator":{"name":"Ministry of Economy and Finance (insurance supervision)","url":"https://www.ministere-finances.dj/"},"insuranceComplaints":null,"pensionScheme":{"name":"National Social Security Fund (Caisse Nationale de Sécurité Sociale, CNSS)","url":"https://cnss.dj/"},"oldAgeAllowance":null,"publicHealthCover":{"name":"Universal Health Insurance (Assurance Maladie Universelle, AMU), run by the CNSS, with the PASS solidarity scheme for people without income","url":"https://cnss.dj/assurance-maladie-universelle/"},"depositInsurance":null,"statistics":{"name":"National Institute of Statistics of Djibouti (INSTAD)","url":"https://www.instad.dj/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DJ', 1, 'bank_deposit_avg_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No deposit rate is published by the Banque Centrale de Djibouti or in the World Bank data; the bank statistics pages of the central bank show no interest rates.', 0);
