INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DJ', 1, 'equity_return_base', 0.055, NULL, 'assumption', 'Banque Centrale de Djibouti: franc fixed to the US dollar; no local stock exchange', 'https://banque-centrale.dj/le-currency-board/', '2026-10-31', 'Global equities in dollar terms, held to about 4 points above an assumed safe rate of about 1.5%, since no local index exists and access is through foreign funds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DJ', 1, 'equity_return_high', 0.09, NULL, 'assumption', 'Banque Centrale de Djibouti: franc fixed to the US dollar', 'https://banque-centrale.dj/le-currency-board/', '2026-10-31', 'High case: global equities match their long-run dollar record.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DJ', 1, 'equity_return_low', 0.02, NULL, 'assumption', 'Banque Centrale de Djibouti: franc fixed to the US dollar; no local stock exchange', 'https://banque-centrale.dj/le-currency-board/', '2026-10-31', 'No local stock market exists, so equity means a global index fund in dollar terms (equal to franc terms under the peg); low case is a weak decade.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DJ', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No deposit rate is published by the Banque Centrale de Djibouti or in the World Bank data for 1-year term deposits.', 0);
