INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DJ', 1, 'fixed_income_return_base', 0.015, NULL, 'assumption', 'No published deposit rates; franc fixed to the US dollar', 'https://banque-centrale.dj/le-currency-board/', '2026-10-31', 'Base case: term deposits at a modest rate; no official deposit rate was found, so this is deliberately cautious.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DJ', 1, 'fixed_income_return_high', 0.03, NULL, 'assumption', 'No published deposit rates; franc fixed to the US dollar', 'https://banque-centrale.dj/le-currency-board/', '2026-10-31', 'High case: longer term deposits nearer dollar money-market rates.', 0);
