INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DJ', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premiums by age were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DJ', 1, 'inflation_cpi', 0.009, NULL, 'sourced', 'Trading Economics, citing the National Institute of Statistics of Djibouti (INSTAD), CPI September 2026', 'https://tradingeconomics.com/djibouti/inflation-cpi', '2026-09-30', 'Consumer prices up 0.9% year on year in September 2026 (1.9% in August). This is a secondary source because the INSTAD site loads its data by script. World Bank 2025 average: -0.3%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DJ', 1, 'inflation_projection', 0.025, NULL, 'assumption', 'World Bank CPI inflation 2021-2025 (about 2% average); dollar peg under a currency board', 'https://data.worldbank.org/indicator/FP.CPI.TOTL.ZG?locations=DJ', '2026-10-31', 'With the franc fixed to the dollar and no inflation target, a rounded 2.5% sits a little above the recent 5-year average to allow for imported food and fuel shocks.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DJ', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published term life premium rates per DJF 1,000 of cover were found; the life insurance market is very small.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DJ', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No life claim settlement ratio was found from the insurance supervisor.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DJ', 1, 'life_expectancy', 66.202, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN), Djibouti', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=DJ', '2024-12-31', '66.2 years in 2024 (men 63.7, women 68.7).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DJ', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":17.9,"men":17,"women":18.8},{"age":65,"total":14.4,"men":13.6,"women":15.1},{"age":70,"total":11.2,"men":10.6,"women":11.8},{"age":80,"total":6.2,"men":5.8,"women":6.5}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/djibouti/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026; totals are the mean of men and women (the page gives no both-sexes figures).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DJ', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension rules were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DJ', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension amount was found; cash transfer programmes target poor households rather than older people.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DJ', 1, 'oop_health_share', 0.2884, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), Djibouti', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=DJ', '2023-12-31', '28.8% in 2023 (WHO Global Health Expenditure Database via the World Bank); older than 2025, the latest available.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DJ', 1, 'policy_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Djibouti runs a currency board (franc fixed to the US dollar), and no central bank policy rate was found on the Banque Centrale de Djibouti site.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DJ', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":60,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'Caisse Nationale de Sécurité Sociale (CNSS), normal retirement pension conditions', 'https://cnss.dj/pensions-de-retraite-normale/', '2026-10-31', 'Compulsory contributory pension for salaried workers, run by the CNSS. It pays from 60 after 25 years of contributions (for people born in 1951 or later). For years from 2007 it accrues 1.5% a year of the last-10-year average capped salary. The CNSS page states no automatic indexation, so inflationLinked is false (conservative); tax treatment unknown.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DJ', 1, 'retirement_accumulation_return_base', 0.03, NULL, 'assumption', 'Assumed safe rate 1.5%; global equity base 5.5%; gold base 4%', 'https://banque-centrale.dj/le-currency-board/', '2026-10-31', 'Base case: deposits with some gold and foreign equity funds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DJ', 1, 'retirement_accumulation_return_high', 0.05, NULL, 'assumption', 'Global equity high 9%; gold high 8%', 'https://banque-centrale.dj/le-currency-board/', '2026-10-31', 'High case: a growth-leaning mix with foreign equity funds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DJ', 1, 'retirement_accumulation_return_low', 0.01, NULL, 'assumption', 'No published deposit rates; no local stock market', 'https://banque-centrale.dj/le-currency-board/', '2026-10-31', 'Low case: mostly bank deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DJ', 1, 'retirement_age_default', 60, NULL, 'sourced', 'Caisse Nationale de Sécurité Sociale (CNSS), normal retirement pension conditions', 'https://cnss.dj/pensions-de-retraite-normale/', '2026-10-31', 'Normal pension at 60 full years. People born in 1951 or later need 25 years of contributions. The pension is based on the average capped salary of the last 10 years and pays 30-81% of declared salary. An early pension from age 50 is paid only for work accidents or unfitness for work.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DJ', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'The civil-service retirement age could not be confirmed from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DJ', 1, 'retirement_return_base', 0.015, NULL, 'assumption', 'No published deposit rates; franc fixed to the US dollar', 'https://banque-centrale.dj/le-currency-board/', '2026-10-31', 'Base case: cautious term-deposit return, kept at the assumed safe rate since no official deposit rate exists.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DJ', 1, 'retirement_return_high', 0.025, NULL, 'assumption', 'No published deposit rates; franc fixed to the US dollar', 'https://banque-centrale.dj/le-currency-board/', '2026-10-31', 'High case: longer term deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DJ', 1, 'retirement_return_low', 0.005, NULL, 'assumption', 'No published deposit rates; franc fixed to the US dollar', 'https://banque-centrale.dj/le-currency-board/', '2026-10-31', 'Low case: savings accounts paying close to nothing.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DJ', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate or retail savings bond for individuals was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DJ', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No deposit rate is published by the Banque Centrale de Djibouti or in the World Bank data for savings accounts.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DJ', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":13.3},{"year":2040,"value":8.5},{"year":2065,"value":5.4}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/djibouti/2040/', '2025-12-31', '100 / old-age dependency ratio: 7.51 (2025, World Bank), 11.8 (2040) and 18.6 (2065, populationpyramid.net/djibouti/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DJ', 1, 'tax_bank_interest', NULL, NULL, 'missing', '', '', '2026-10-31', 'The tax rate on bank interest in the Code Général des Impôts could not be confirmed from a current official source; PwC Worldwide Tax Summaries has no Djibouti page.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DJ', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate exists to tax, and no current rule was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DJ', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No domestic Treasury bill market or yield was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DJ', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No domestic government bond market or yield was found.', 0);
