INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('DK', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"DK","iso3":"DNK","nameEn":"Denmark","nameNative":"Danmark","region":"europe_central_asia","languages":["da","en","de","sv"],"currency":{"code":"DKK","symbol":"kr.","decimals":2,"compact":"intl","usdRate":{"value":6.6895,"status":"sourced","sourceName":"Danmarks Nationalbank daily exchange rates (USD)","sourceUrl":"https://www.nationalbanken.dk/api/currencyratesxml?lang=en","asOf":"2026-10-30","note":"DKK 668.95 per USD 100 on 30 Oct 2026; matches the ECB reference cross rate (DKK 7.4735 and USD 1.1172 per euro). World Bank 2025 average 6.62."}},"instruments":{"savings_account":{"available":true,"localName":"Opsparingskonto","localNameEn":"Savings account","sourceUrl":"https://www.statbank.dk/DNRUIPI"},"fdr_3m":{"available":true,"localName":"Tidsindskud","localNameEn":"Time deposit (3 months)","sourceUrl":"https://www.statbank.dk/DNRNIPI"},"fdr_1y":{"available":true,"localName":"Tidsindskud","localNameEn":"Time deposit (1 year)","sourceUrl":"https://www.statbank.dk/DNRNIPI"},"dps":{"available":false,"localName":null,"localNameEn":"Monthly recurring deposit","note":"No standard recurring-deposit product; regular saving goes into savings accounts or tax-favoured schemes."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":"Government savings certificate","note":"No retail government savings certificate or bond sold directly to individuals."},"tbill_91d":{"available":true,"localName":"Skatkammerbeviser","localNameEn":"Treasury bills","note":"Issued for the state by Danmarks Nationalbank, mainly to institutions."},"tbond_5y":{"available":true,"localName":"Statsobligationer","localNameEn":"Danish government bonds"},"tbond_10y":{"available":true,"localName":"Statsobligationer","localNameEn":"Danish government bonds","sourceUrl":"https://data-api.ecb.europa.eu/service/data/IRS/M.DK.L.L40.CI.0000.DKK.N.Z"},"equity_fund":{"available":true,"localName":"Investeringsforeninger","localNameEn":"Investment funds / index funds (ETF)","note":"Retail investment funds are widely available; gains taxed as share income (27%/42%), or 17% inside an aktiesparekonto."},"gold":{"available":true,"localName":"Guldbarrer og guldmønter","localNameEn":"Gold bars and coins","note":"No restriction on buying physical gold."}},"institutions":{"centralBank":{"name":"Danmarks Nationalbank","url":"https://www.nationalbanken.dk/en"},"insuranceRegulator":{"name":"Finanstilsynet (Danish Financial Supervisory Authority)","url":"https://www.dfsa.dk/"},"insuranceComplaints":{"name":"Ankenævnet for Forsikring (Insurance Complaints Board)","url":"https://www.ankeforsikring.dk/"},"pensionScheme":{"name":"ATP Livslang Pension","url":"https://lifeindenmark.borger.dk/pension/atp-livslang-pension","note":"Compulsory supplementary lifetime pension alongside the folkepension."},"oldAgeAllowance":{"name":"Folkepension (state pension, paid by Udbetaling Danmark)","url":"https://www.borger.dk/pension-og-efterloen/Folkepension-oversigt/foer-du-gaar-paa-folkepension"},"publicHealthCover":{"name":"Public health insurance (sygesikring), regional health services","url":"https://www.sundhed.dk/"},"depositInsurance":{"name":"Garantiformuen, Finansiel Stabilitet","url":"https://fs.dk/en/deposit-guarantee-fund/about-the-danish-deposit-guarantee-scheme"},"statistics":{"name":"Danmarks Statistik (Statistics Denmark)","url":"https://www.dst.dk/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DK', 1, 'bank_deposit_avg_rate', 0.0053, NULL, 'sourced', 'Danmarks Nationalbank MFI statistics (DNRUIPI): all household DKK deposits, outstanding', 'https://www.statbank.dk/DNRUIPI', '2026-09-30', 'Average effective rate on all outstanding household deposits in DKK; World Bank FR.INR.DPST has no Denmark figure.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DK', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'Danish law caps the cost of consumer credit (annual percentage rate ceiling), but the statutory text on retsinformation.dk could not be read; Nationalbanken''s credit-card interest series for households is confidential (''..''). Overdrafts and revolving credit to households averaged 4.62% in September 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DK', 1, 'deposit_insurance_limit', 747350, NULL, 'sourced', 'Finansiel Stabilitet, Garantiformuen (Danish deposit guarantee scheme)', 'https://fs.dk/en/deposit-guarantee-fund/how-are-my-deposits-covered', '2026-10-30', 'Cover is the equivalent of EUR 100,000 per depositor per institution, converted at the ECB rate of DKK 7.4735 per euro (30 Oct 2026); EUR 150,000 for 6 months after life events, pension savings fully covered.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DK', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Danish banks do not offer a standard monthly recurring deposit product with a published rate; regular saving goes into ordinary or notice savings accounts or tax-favoured schemes (aldersopsparing, børneopsparing).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DK', 1, 'equity_return_base', 0.05, NULL, 'assumption', 'Copenhagen index (Trading Economics); 1-year deposit 1.96% less 37% tax = 1.2%', 'https://tradingeconomics.com/denmark/stock-market', '2026-10-31', 'Base capped near the after-tax safe rate plus about 4 points because the index has fallen sharply since 2024 and depends on a handful of companies.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DK', 1, 'equity_return_high', 0.07, NULL, 'assumption', 'Copenhagen index; long-run global equity returns', 'https://tradingeconomics.com/denmark/stock-market', '2026-10-31', 'High case: a diversified equity fund matching long-run global equity returns of about 7% in kroner.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DK', 1, 'equity_return_low', 0.03, NULL, 'assumption', 'Copenhagen 20 index about 1,646 on 2 Nov 2026, 45% below its June 2024 high of 2,967', 'https://tradingeconomics.com/denmark/stock-market', '2026-10-31', 'Low case: Danish shares, concentrated in a few large health-care and shipping companies, return little more than safe deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DK', 1, 'fdr_1y_rate', 0.0196, NULL, 'sourced', 'Danmarks Nationalbank MFI statistics (DNRNIPI): new household time deposits in DKK, over 3 months up to 1 year', 'https://www.statbank.dk/DNRNIPI', '2026-09-30', 'New business effective rate, September 2026; 1-2 years paid 2.23%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DK', 1, 'fdr_3m_rate', 0.0167, NULL, 'sourced', 'Danmarks Nationalbank MFI statistics (DNRNIPI): new household time deposits in DKK, up to 3 months', 'https://www.statbank.dk/DNRNIPI', '2026-09-30', 'New business effective rate, September 2026 (1.48% in August).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DK', 1, 'fixed_income_return_base', 0.012, NULL, 'assumption', 'New household deposits 3-12 months 1.96% less 37% tax = 1.2% (Nationalbanken DNRNIPI)', 'https://www.statbank.dk/DNRNIPI', '2026-10-31', 'Base case: after-tax 1-year term deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DK', 1, 'fixed_income_return_high', 0.02, NULL, 'assumption', 'Denmark 10-year government bond 3.29% (ECB, Sep 2026) less 37% tax = 2.1%', 'https://data-api.ecb.europa.eu/service/data/IRS/M.DK.L.L40.CI.0000.DKK.N.Z', '2026-10-31', 'High case: holding long government or mortgage bonds after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DK', 1, 'fixed_income_return_low', 0.008, NULL, 'assumption', 'Household notice deposits 1.21% less 37% capital income tax (Nationalbanken DNRUIPI)', 'https://www.statbank.dk/DNRUIPI', '2026-10-31', 'Low case: easy-access savings after tax, with rates drifting lower.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DK', 1, 'goal_inflation_education', 0.04, NULL, 'assumption', 'Danmarks Statistik PRIS01, education (COICOP 10): +4.1% year on year in September 2026', 'https://www.statbank.dk/PRIS01', '2026-10-31', 'Public education is free; the fees people do pay (private schools, courses) are rising about 4% a year, which is used for planning.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DK', 1, 'goal_inflation_health', 0.03, NULL, 'assumption', 'Danmarks Statistik PRIS01, health (COICOP 06): +1.4% year on year in September 2026', 'https://www.statbank.dk/PRIS01', '2026-10-31', 'Measured health prices rise slowly because most care is public and free, but private dental, physiotherapy and medicine costs are planned at 3%, a point above headline inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DK', 1, 'gold_return_base', 0.04, NULL, 'assumption', 'Gold price history (Trading Economics); ECB 2% inflation target', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Base case: dollar gold rises roughly with world inflation plus a little, and the krone (pegged to the euro) is assumed stable against the dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DK', 1, 'gold_return_high', 0.07, NULL, 'assumption', 'Gold price history (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'High case: a repeat of gold''s strong 2005-2025 trend in krone terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DK', 1, 'gold_return_low', 0.01, NULL, 'assumption', 'Gold price history (Trading Economics); DKK pegged to the euro', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Low case: gold barely keeps up after the 2025-26 spike, with no help from the krone.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DK', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No per-year gratuity: the Salaried Employees Act (funktionærloven s.2a) gives a lump severance of 1, 2 or 3 months'' pay after 12, 15 or 18 years of service, which does not fit a days-per-year rule; holiday pay is separate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DK', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'Hospital treatment is free at the point of use in the public regional hospitals; no official figure for the out-of-pocket cost of a private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DK', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Private health insurance (sundhedsforsikring) is mostly an employer benefit with flat premiums, not priced per DKK 100,000 of cover; no published premium table was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DK', 1, 'inflation_cpi', 0.022, NULL, 'sourced', 'Danmarks Statistik, PRIS01 consumer price index (annual change)', 'https://www.statbank.dk/PRIS01', '2026-09-30', 'CPI up 2.2% year on year in September 2026 (2.0% in August); World Bank 2025 average 1.9%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DK', 1, 'inflation_projection', 0.02, NULL, 'assumption', 'Krone pegged to the euro (ECB 2% target); Danish CPI 2021-2025 average 3.2%, 1.9% in 2025', 'https://www.statbank.dk/PRIS9', '2026-10-31', 'The fixed-exchange-rate policy ties Danish inflation to the euro area, so the ECB 2% target is used; recent years outside the 2022 spike were close to 2%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DK', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life cover (risikolivsforsikring) is sold, mostly through labour-market pension schemes, but no published premium table per DKK 1,000 of cover was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DK', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Finanstilsynet and Forsikring & Pension do not publish an industry-wide life claim settlement ratio that could be found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DK', 1, 'life_expectancy', 82.25, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=DK', '2024-12-31', 'World Bank figure is for 2024 (older than 2025). Danmarks Statistik life table 2024-2025 (HISB8): men 80.25, women 83.90.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DK', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":24.3,"men":22.85,"women":25.74},{"age":65,"total":20.1,"men":18.72,"women":21.39},{"age":70,"total":16.1,"men":14.98,"women":17.3},{"age":80,"total":9.2,"men":8.45,"women":9.99}]}', 'sourced', 'Danmarks Statistik, life table 2024-2025 (HISB8, middellevetid)', 'https://www.statbank.dk/HISB8', '2025-12-31', 'Official tables are by sex only; total is the simple average of men and women.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DK', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":70,"womenAge":70,"over90Monthly":null,"meansTested":false}', 'sourced', 'borger.dk, folkepension (age, residence and income rules)', 'https://www.borger.dk/pension-og-efterloen/Folkepension-oversigt/foer-du-gaar-paa-folkepension', '2026-10-31', 'Ages are for people born on or after 1 January 1971 (67-69 for older cohorts). Not contributory: generally needs Danish citizenship, permanent residence and at least 3 years'' residence between age 15 and pension age; the full rate needs residence for 9/10 of that period, otherwise it is pro-rated. The basic amount is not reduced by other income; only the supplement is income-tested.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DK', 1, 'old_age_allowance_monthly', 7544, NULL, 'sourced', 'borger.dk, folkepension rates 2026 (grundbeløb)', 'https://www.borger.dk/pension-og-efterloen/Folkepension-oversigt/foer-du-gaar-paa-folkepension', '2026-01-01', 'Basic amount (grundbeløb) of the residence-based folkepension, DKK 7,544 a month before tax in 2026, not reduced by other income; an income-tested pension supplement adds up to DKK 8,729 (single) or 4,467 (married/cohabiting).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DK', 1, 'oop_health_share', 0.1387, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=DK', '2024-12-31', 'Latest World Bank figure is for 2024 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DK', 1, 'policy_rate', 0.021, NULL, 'sourced', 'Danmarks Nationalbank current-account rate (StatBank DNRENTD)', 'https://www.statbank.dk/DNRENTD', '2026-10-29', 'Current-account and certificates-of-deposit rate 2.10%, lending rate 2.25%; raised from 1.85% in mid-September 2026 after the ECB raised its deposit rate on 16 September.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DK', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":16,"entryAgeMax":null,"pensionFromAge":70,"nomineeUntilAge":null,"inflationLinked":true,"taxFree":false}', 'sourced', 'borger.dk (folkepension) and lifeindenmark.borger.dk (ATP Livslang Pension)', 'https://lifeindenmark.borger.dk/pension/atp-livslang-pension', '2026-10-31', 'Two public tiers: the residence-based folkepension and the compulsory ATP lifetime pension (contributions for wage earners aged 16 or more, one-third employee, two-thirds employer, paid automatically from the Danish pension age, which is 70 for people born from 1971). Folkepension is adjusted yearly by the rate-adjustment percentage; both are taxed as income.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DK', 1, 'retirement_accumulation_return_base', 0.03, NULL, 'assumption', 'After-tax 1-year deposit 1.2%; equity base 5%', 'https://www.statbank.dk/DNRNIPI', '2026-10-31', 'Base case: roughly half shares at 5% and half safe fixed income at about 1.2-2% after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DK', 1, 'retirement_accumulation_return_high', 0.045, NULL, 'assumption', 'After-tax 10-year bond 2.1%; equity high 7%', 'https://data-api.ecb.europa.eu/service/data/IRS/M.DK.L.L40.CI.0000.DKK.N.Z', '2026-10-31', 'High case for a growth-leaning balanced mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DK', 1, 'retirement_accumulation_return_low', 0.02, NULL, 'assumption', 'After-tax 1-year deposit 1.2%; Copenhagen index record', 'https://www.statbank.dk/DNRNIPI', '2026-10-31', 'Low case for a balanced mix if shares lag.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DK', 1, 'retirement_age_default', 70, NULL, 'sourced', 'borger.dk, folkepensionsalder', 'https://www.borger.dk/pension-og-efterloen/Folkepension-oversigt/foer-du-gaar-paa-folkepension', '2026-10-31', 'Folkepension age is 70 for everyone born on or after 1 January 1971, so 70 applies to people born after 1975 (and may be raised further with life expectancy); it is 67 for people born 1 July 1955 to 31 December 1962, 68 for 1963-66 and 69 for 1967-70. Same for men and women.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DK', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'Most public employees are on ordinary contracts and follow the folkepension age; the separate retirement rule for tenured civil servants (tjenestemænd) could not be confirmed from a readable official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DK', 1, 'retirement_return_base', 0.012, NULL, 'assumption', 'New household deposits 3-12 months 1.96% less 37% tax = 1.2%', 'https://www.statbank.dk/DNRNIPI', '2026-10-31', 'Base case capped at the after-tax 1-year term deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DK', 1, 'retirement_return_high', 0.018, NULL, 'assumption', 'Denmark 10-year government bond 3.29% (ECB, Sep 2026) less 37% tax = 2.1%', 'https://data-api.ecb.europa.eu/service/data/IRS/M.DK.L.L40.CI.0000.DKK.N.Z', '2026-10-31', 'High case: a ladder of longer government and mortgage bonds after tax, slightly below the 10-year yield.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DK', 1, 'retirement_return_low', 0.008, NULL, 'assumption', 'Household notice deposits 1.21% less 37% tax', 'https://www.statbank.dk/DNRUIPI', '2026-10-31', 'Low case: easy-access savings after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DK', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Denmark has no retail government savings certificate or savings bond sold to individuals; government bonds are bought through banks on the market.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DK', 1, 'savings_account_rate', 0.004, NULL, 'sourced', 'Danmarks Nationalbank MFI statistics (DNRUIPI): household transferable (on-demand) deposits in DKK, outstanding', 'https://www.statbank.dk/DNRUIPI', '2026-09-30', 'Average 0.40% on households'' on-demand DKK deposits; deposits with notice paid 1.21%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DK', 1, 'support_ratio', NULL, '{"points":[{"year":2026,"value":3.01},{"year":2040,"value":2.41},{"year":2065,"value":2.2}]}', 'sourced', 'Danmarks Statistik, population projection 2026 (FRDK126)', 'https://www.statbank.dk/FRDK126', '2026-01-01', 'People aged 15-64 divided by people 65+ in the official 2026 projection; World Bank 2025 old-age dependency 33.4 gives 3.0.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DK', 1, 'tax_bank_interest', 0.37, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Denmark taxes on personal income', 'https://taxsummaries.pwc.com/denmark/individual/taxes-on-personal-income', '2026-06-25', 'No final withholding: interest is positive net capital income, taxed at average municipal tax 25.05% plus bottom tax 12.01% (about 37%), up to 42% for high incomes.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DK', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No retail government savings certificate exists; interest on government bonds is taxed as ordinary capital income (about 37-42%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DK', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Treasury bills (skatkammerbeviser) are issued by Danmarks Nationalbank for the state, but no current 3-month yield could be read; worldgovernmentbonds.com loads yields by script.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DK', 1, 'tbond_10y_rate', 0.0329, NULL, 'sourced', 'ECB long-term interest rate for convergence purposes, Denmark (10-year government bond yield)', 'https://data-api.ecb.europa.eu/service/data/IRS/M.DK.L.L40.CI.0000.DKK.N.Z', '2026-09-30', 'Monthly average for September 2026 (3.01% in August); Trading Economics showed 3.10% on 2 November 2026 and a 2-year yield of 2.79%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DK', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No current 5-year Danish government bond yield was found: Trading Economics shows only 2- and 10-year yields and worldgovernmentbonds.com could not be read.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('DM', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"DM","iso3":"DMA","nameEn":"Dominica","nameNative":"Dominica","region":"latin_america_caribbean","languages":["en","acf"],"currency":{"code":"XCD","symbol":"$","decimals":2,"compact":"intl","usdRate":{"value":2.7,"status":"sourced","sourceName":"Eastern Caribbean Central Bank, exchange rates (US dollar)","sourceUrl":"https://www.eccb-centralbank.org/exchange-rates","asOf":"2026-10-31","note":"The EC dollar has been fixed at XCD 2.70 per US dollar since 1976."}},"instruments":{"savings_account":{"available":true,"localName":"Savings account","localNameEn":null,"sourceUrl":"https://www.eccb-centralbank.org/statistics-category/mfs-interest-rates/interest-rates-and-weighted-averages-rates-on-deposits-and-loans/q?country_code[]=3"},"fdr_3m":{"available":true,"localName":"Fixed deposit (3 months)","localNameEn":null,"note":"Banks take short fixed deposits, but no 3-month rate is reported to the ECCB for Dominica."},"fdr_1y":{"available":true,"localName":"Fixed deposit (1 year)","localNameEn":null,"sourceUrl":"https://www.eccb-centralbank.org/statistics-category/mfs-interest-rates/interest-rates-on-deposits-and-loans/m?country_code[]=3"},"dps":{"available":false,"localName":null,"localNameEn":"Recurring deposit","note":"No monthly recurring deposit product was confirmed."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":"Government savings certificate","note":"No retail savings bond for individuals was found."},"tbill_91d":{"available":true,"localName":"Treasury bills (Regional Government Securities Market)","localNameEn":null,"note":"Individuals can bid through licensed intermediaries of the Eastern Caribbean Securities Exchange.","sourceUrl":"https://www.eccb-centralbank.org/statistics-category/regional-government-securities-market/weighted-average-interest-rates-on-the-rgsm/m?country_code[]=3"},"tbond_5y":{"available":false,"localName":null,"localNameEn":"Government bonds","note":"Dominica has issued 7-year bonds (7.00% in August 2026) but no 5-year bonds since 2021.","sourceUrl":"https://www.eccb-centralbank.org/statistics-category/regional-government-securities-market/weighted-average-interest-rates-on-the-rgsm/m?country_code[]=3"},"tbond_10y":{"available":false,"localName":null,"localNameEn":"Government bonds","note":"No 10-year bonds issued since 2021.","sourceUrl":"https://www.eccb-centralbank.org/statistics-category/regional-government-securities-market/weighted-average-interest-rates-on-the-rgsm/m?country_code[]=3"},"equity_fund":{"available":false,"localName":null,"localNameEn":"Equity funds","note":"No locally regulated diversified retail equity fund was identified; the regional stock exchange lists few companies."},"gold":{"available":false,"localName":null,"localNameEn":"Investment gold","note":"No local market for investment gold bars or coins was identified."}},"institutions":{"centralBank":{"name":"Eastern Caribbean Central Bank (ECCB)","url":"https://www.eccb-centralbank.org/"},"insuranceRegulator":{"name":"Financial Services Unit (FSU), Ministry of Finance","url":"https://www.fsu.gov.dm/"},"insuranceComplaints":null,"pensionScheme":{"name":"Dominica Social Security (DSS), age pension","url":"https://dss.dm/pension/"},"oldAgeAllowance":null,"publicHealthCover":{"name":"Ministry of Health (public hospitals and health centres)","url":"https://health.gov.dm/"},"depositInsurance":null,"statistics":{"name":"Central Statistics Office of Dominica","url":"https://stats.gov.dm/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DM', 1, 'bank_deposit_avg_rate', 0.0152, NULL, 'sourced', 'ECCB, interest rates and weighted average rates on deposits, Dominica: total EC-dollar deposits weighted average', 'https://www.eccb-centralbank.org/statistics-category/mfs-interest-rates/interest-rates-and-weighted-averages-rates-on-deposits-and-loans/q?country_code[]=3', '2026-06-30', 'Weighted average rate on all EC-dollar deposits 1.52% in June 2026 (all currencies 1.49%); World Bank deposit rate 1.54% (2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DM', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap was found; the ECCB publishes only a 3-22% range for ''other lending rates'' in Dominica.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DM', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No deposit insurance scheme covering Dominican banks with a published cover limit was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DM', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No monthly recurring deposit product with a published rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DM', 1, 'equity_return_base', 0.065, NULL, 'assumption', 'Global equity index in EC dollars; after-tax 91-day bill 3.0% (ECCB RGSM)', 'https://www.eccb-centralbank.org/statistics-category/regional-government-securities-market/weighted-average-interest-rates-on-the-rgsm/m?country_code[]=3', '2026-10-31', 'The regional exchange lists few shares, so equity is a global index in US-dollar terms (the EC dollar is pegged), 3.5 points above the after-tax bill rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DM', 1, 'equity_return_high', 0.09, NULL, 'assumption', 'Global equity long-run record in US dollars', 'https://www.eccb-centralbank.org/statistics-category/regional-government-securities-market/weighted-average-interest-rates-on-the-rgsm/m?country_code[]=3', '2026-10-31', 'High case: global shares repeat their long-run record.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DM', 1, 'equity_return_low', 0.03, NULL, 'assumption', 'No meaningful local stock market; global equity in EC dollars (pegged to USD); after-tax 91-day bill 3.5% x 0.85 = 3.0%', 'https://www.eccb-centralbank.org/statistics-category/regional-government-securities-market/weighted-average-interest-rates-on-the-rgsm/m?country_code[]=3', '2026-10-31', 'Low case: global shares earn about the after-tax treasury bill rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DM', 1, 'fdr_1y_rate', 0.015, NULL, 'sourced', 'ECCB, interest rates on deposits and loans, Dominica: 12-month time deposits, maximum posted rate (EC dollars)', 'https://www.eccb-centralbank.org/statistics-category/mfs-interest-rates/interest-rates-on-deposits-and-loans/m?country_code[]=3', '2026-08-31', 'Posted 12-month time-deposit rates ranged 0.25-1.50% in May-August 2026; the weighted average on all EC-dollar time deposits was 2.86% in June 2026, so negotiated or longer deposits pay more.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DM', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The ECCB publishes no 3-month time-deposit rate for Dominica (shown as not available through August 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DM', 1, 'fixed_income_return_base', 0.024, NULL, 'assumption', 'EC-dollar time deposits weighted average 2.86% less 15% tax = 2.4% (ECCB)', 'https://www.eccb-centralbank.org/statistics-category/mfs-interest-rates/interest-rates-and-weighted-averages-rates-on-deposits-and-loans/q?country_code[]=3', '2026-10-31', 'Base case: the average rate actually paid on time deposits, after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DM', 1, 'fixed_income_return_high', 0.03, NULL, 'assumption', '91-day treasury bill 3.50% less 15% tax = 3.0% (ECCB RGSM)', 'https://www.eccb-centralbank.org/statistics-category/regional-government-securities-market/weighted-average-interest-rates-on-the-rgsm/m?country_code[]=3', '2026-10-31', 'High case: rolling government treasury bills.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DM', 1, 'fixed_income_return_low', 0.013, NULL, 'assumption', '12-month time deposit 1.50% less 15% tax = 1.3% (ECCB)', 'https://www.eccb-centralbank.org/statistics-category/mfs-interest-rates/interest-rates-on-deposits-and-loans/m?country_code[]=3', '2026-10-31', 'Low case: posted one-year deposit rates after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DM', 1, 'goal_inflation_education', 0.035, NULL, 'assumption', 'Dominica CPI education index 103.5 (2021) to 118.6 (June 2026), about 3% a year (ECCB)', 'https://www.eccb-centralbank.org/statistics-category/other-real-sector/consumer-price-index-commonwealth-of-dominica/a', '2026-10-31', 'Education prices rose about 3% a year over 2021-2026, mostly in one 2024 jump; planning uses 3.5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DM', 1, 'goal_inflation_health', 0.03, NULL, 'assumption', 'Dominica CPI health index flat at 110.7 from mid-2025 to mid-2026 and lower than in 2022 (ECCB)', 'https://www.eccb-centralbank.org/statistics-category/other-real-sector/consumer-price-index-commonwealth-of-dominica/q', '2026-10-31', 'Measured health prices have barely moved, but imported medical care tends to rise faster than general prices; planning uses 3%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DM', 1, 'gold_return_base', 0.04, NULL, 'assumption', 'Gold USD price trend (Trading Economics); fixed EC dollar peg', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Base case: gold tracks long-run US inflation plus a little.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DM', 1, 'gold_return_high', 0.08, NULL, 'assumption', 'Gold USD price history (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'High case: gold resumes its 2020s uptrend.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DM', 1, 'gold_return_low', 0, NULL, 'assumption', 'Gold USD 3,876/oz on 30 Oct 2026, 3% down in a year (Trading Economics); EC dollar pegged at 2.70', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Low case: gold flat in dollars, and so in EC dollars.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DM', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No general statutory gratuity was found. Severance (redundancy benefit) under the Protection of Employment Act is paid only on redundancy after at least 3 years of service, through the Dominica Social Security Redundancy Fund.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DM', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DM', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No regulator or non-company source of health insurance premiums by age was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DM', 1, 'inflation_cpi', 0.0089, NULL, 'sourced', 'ECCB statistics, Consumer Price Index - Commonwealth of Dominica (Central Statistics Office data)', 'https://www.eccb-centralbank.org/statistics-category/other-real-sector/consumer-price-index-commonwealth-of-dominica/q', '2026-06-30', 'All-items index 121.85 in June 2026 against 120.77 in June 2025, a 0.9% year-on-year rise (computed from the published index); 2025 average inflation 0.91%. Latest published month is June 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DM', 1, 'inflation_projection', 0.025, NULL, 'assumption', 'Dominica CPI: average inflation 3.0% a year over 2021-2025 (ECCB); EC dollar pegged to the US dollar', 'https://www.eccb-centralbank.org/statistics-category/other-real-sector/consumer-price-index-commonwealth-of-dominica/a', '2026-10-31', 'With the EC dollar fixed to the US dollar, long-run inflation should track US inflation plus a little; 2.5% sits between the 2025 rate (0.9%) and the 2021-2025 average (3.0%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DM', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life cover is sold, but no regulator or non-company source of premiums by age was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DM', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Financial Services Unit publishes no claim settlement ratio for life insurers.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DM', 1, 'life_expectancy', 71.294, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=DM', '2024-12-31', 'Men 68.4, women 74.7 (2024; latest World Bank figure, older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DM', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":18,"men":16.3,"women":19.9},{"age":65,"total":14.4,"men":13,"women":15.9},{"age":70,"total":11.1,"men":10,"women":12.2},{"age":80,"total":6.2,"men":5.6,"women":6.6}]}', 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/dominica', '2026-07-01', 'Remaining years derived from the ''life expectancy by current age'' table for 2026 (UN WPP).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DM', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension rules were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DM', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'No current non-contributory old-age pension amount was found; Dominica Social Security pays only contributory age benefits, and needy older people rely on public assistance from the social welfare division.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DM', 1, 'oop_health_share', 0.2933, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=DM', '2023-12-31', 'Out-of-pocket spending was 29.3% of current health expenditure in 2023 (latest available; older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DM', 1, 'policy_rate', 0.03, NULL, 'sourced', 'Eastern Caribbean Central Bank (ECCB), discount rate', 'https://www.eccb-centralbank.org/interest-rates', '2026-10-31', 'The ECCB''s discount rate was 3.00% on 31 October 2026; the EC dollar is pegged at 2.70 per US dollar, so the rate is a backstop rather than an active policy tool.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DM', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":65,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'Dominica Social Security, retirement age and benefits', 'https://dss.dm/pension/retirement-age/', '2026-10-31', 'Compulsory social security for employees and the self-employed: age pension at 65 with at least 500 credits (reduced pension from 60, 0.5% less per month early); 50-499 credits give a lump-sum age grant (DSS benefits page https://dss.dm/benefits/benefits-info/). The DSS pages state no automatic inflation indexation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DM', 1, 'retirement_accumulation_return_base', 0.04, NULL, 'assumption', 'Fixed income base 2.4%; equity base 6.5%', 'https://www.eccb-centralbank.org/statistics-category/regional-government-securities-market/weighted-average-interest-rates-on-the-rgsm/m?country_code[]=3', '2026-10-31', 'Base case: roughly half safe EC-dollar fixed income and half global equity.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DM', 1, 'retirement_accumulation_return_high', 0.06, NULL, 'assumption', 'Equity high 9%; treasury bills 3.0% after tax', 'https://www.eccb-centralbank.org/statistics-category/regional-government-securities-market/weighted-average-interest-rates-on-the-rgsm/m?country_code[]=3', '2026-10-31', 'High case: equities do well.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DM', 1, 'retirement_accumulation_return_low', 0.025, NULL, 'assumption', 'After-tax deposits 1.3-2.4%; equity low case 3%', 'https://www.eccb-centralbank.org/statistics-category/mfs-interest-rates/interest-rates-and-weighted-averages-rates-on-deposits-and-loans/q?country_code[]=3', '2026-10-31', 'Low case for a balanced mix of deposits, bills and global equity.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DM', 1, 'retirement_age_default', 65, NULL, 'sourced', 'Dominica Social Security, retirement age', 'https://dss.dm/pension/retirement-age/', '2026-10-31', 'Pensionable age has been 65 since 2021; an age pension can be taken from 60, reduced by 0.5% for each month before 65.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DM', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'The retirement age for public servants under the Pensions Act was not found; government workers also draw the social security age pension at 65.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DM', 1, 'retirement_return_base', 0.024, NULL, 'assumption', 'EC-dollar time deposits weighted average 2.86% less 15% tax (ECCB)', 'https://www.eccb-centralbank.org/statistics-category/mfs-interest-rates/interest-rates-and-weighted-averages-rates-on-deposits-and-loans/q?country_code[]=3', '2026-10-31', 'Base case: time deposits and treasury bills, no higher than the 3.0% after-tax bill rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DM', 1, 'retirement_return_high', 0.03, NULL, 'assumption', '91-day treasury bill 3.50% less 15% tax (ECCB RGSM)', 'https://www.eccb-centralbank.org/statistics-category/regional-government-securities-market/weighted-average-interest-rates-on-the-rgsm/m?country_code[]=3', '2026-10-31', 'High case: rolling government treasury bills.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DM', 1, 'retirement_return_low', 0.013, NULL, 'assumption', '12-month time deposit 1.50% less 15% tax (ECCB)', 'https://www.eccb-centralbank.org/statistics-category/mfs-interest-rates/interest-rates-on-deposits-and-loans/m?country_code[]=3', '2026-10-31', 'Low case: posted one-year deposits after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DM', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate or retail savings bond for individuals was found; government securities are sold through the regional securities market.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DM', 1, 'savings_account_rate', 0.0205, NULL, 'sourced', 'ECCB, interest rates and weighted average rates on deposits, Dominica: savings deposits weighted average (EC dollars)', 'https://www.eccb-centralbank.org/statistics-category/mfs-interest-rates/interest-rates-and-weighted-averages-rates-on-deposits-and-loans/q?country_code[]=3', '2026-06-30', 'Weighted average rate on EC-dollar savings deposits 2.05% in June 2026; posted savings rates ranged 2.00-3.50% (August 2026), with the ECCB''s 2% minimum savings rate as the floor.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DM', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":5.24}]}', 'sourced', 'World Bank WDI SP.POP.DPND.OL', 'https://data.worldbank.org/indicator/SP.POP.DPND.OL?locations=DM', '2025-12-31', '100 / old-age dependency ratio of 19.1 in 2025. No UN WPP projection for 2040 or 2065 could be read for Dominica.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DM', 1, 'tax_bank_interest', 0.15, NULL, 'sourced', 'Inland Revenue Division, Dominica, current income tax rates', 'https://ird.gov.dm/customer-service/current-income-tax-rates', '2026-10-31', 'The IRD personal income tax page lists interest among taxable income for residents (https://ird.gov.dm/tax-laws/personal-income-tax); chargeable income is taxed at 0% on the first XCD 30,000 (resident allowance), then 15%, 25% and 35%. 15% is the first taxable band, so savers with income under XCD 30,000 pay nothing; 15% withholding applies only to non-residents.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DM', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate exists for individuals.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DM', 1, 'tbill_91d_rate', 0.035, NULL, 'sourced', 'ECCB/ECSE, weighted average interest rates on the Regional Government Securities Market, Dominica 91-day treasury bills', 'https://www.eccb-centralbank.org/statistics-category/regional-government-securities-market/weighted-average-interest-rates-on-the-rgsm/m?country_code[]=3', '2026-07-31', 'Dominica''s July 2026 91-day treasury bill auction cleared at a 3.50% weighted average (2.38% average in 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DM', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Dominica has issued no 10-year bonds on the regional market in 2021-2026; its last bond issues were 7-year bonds at 7.00% (August 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DM', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Dominica has issued no 5-year bonds on the regional market in 2021-2026; its last bond issues were 7-year bonds at 7.00% (August 2026).', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('DO', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"DO","iso3":"DOM","nameEn":"Dominican Republic","nameNative":"República Dominicana","region":"latin_america_caribbean","languages":["es"],"currency":{"code":"DOP","symbol":"RD$","decimals":2,"compact":"intl","usdRate":{"value":60.4156,"status":"sourced","sourceName":"DGII table of BCRD reference exchange rates 2026 (US dollar)","sourceUrl":"https://www.dgii.gov.do/estadisticas/tasaCambio/1Dlar/Dolar2026.pdf","asOf":"2026-10-30","note":"BCRD reference rate, pesos per US dollar, on 30 October 2026 as published by the tax authority (October 2026 average 60.72)."}},"instruments":{"savings_account":{"available":true,"localName":"Cuenta de ahorros","localNameEn":"Savings account","note":"Peso savings accounts pay well under 1% a year on average.","sourceUrl":"https://cdn.bancentral.gov.do/documents/estadisticas/sector-monetario-y-financiero/documents/tbm_pasivad.xlsx"},"fdr_3m":{"available":true,"localName":"Certificado financiero","localNameEn":"Financial certificate (3-month term deposit)","sourceUrl":"https://cdn.bancentral.gov.do/documents/estadisticas/sector-monetario-y-financiero/documents/tbm_pasivad.xlsx"},"fdr_1y":{"available":true,"localName":"Certificado financiero","localNameEn":"Financial certificate (1-year term deposit)","sourceUrl":"https://cdn.bancentral.gov.do/documents/estadisticas/sector-monetario-y-financiero/documents/tbm_pasivad.xlsx"},"dps":{"available":false,"localName":null,"note":"No standard monthly recurring-deposit product with a published rate was found."},"sanchayapatra_5y":{"available":false,"localName":null,"note":"No government savings certificate is sold directly to individuals; Ministry of Finance peso bonds can be bought on the stock market through brokers."},"tbill_91d":{"available":true,"localName":"Letras del Banco Central","localNameEn":"Central bank bills (terms under one year)","note":"Auctioned by the BCRD; terms vary (161-308 days in the October 2026 auction) rather than a fixed 91 days.","sourceUrl":"https://cdn.bancentral.gov.do/documents/instrumentos-de-inversion/instrumentos-operaciones-de-mercado-abierto/documents/Letras_bc_resultados.pdf"},"tbond_5y":{"available":true,"localName":"Bonos del Ministerio de Hacienda","localNameEn":"Ministry of Finance peso bonds","note":"Auctioned by the Dirección General de Crédito Público; individuals buy on the secondary market."},"tbond_10y":{"available":true,"localName":"Bonos del Ministerio de Hacienda","localNameEn":"Ministry of Finance peso bonds","note":"Auctioned by the Dirección General de Crédito Público; individuals buy on the secondary market."},"equity_fund":{"available":false,"localName":null,"note":"Local investment funds supervised by the Superintendencia del Mercado de Valores invest mainly in fixed income; no diversified local equity index fund was found."},"gold":{"available":true,"localName":"Oro","localNameEn":"Gold","note":"Gold can be bought legally from jewellers and dealers."}},"institutions":{"centralBank":{"name":"Banco Central de la República Dominicana","url":"https://www.bancentral.gov.do/"},"insuranceRegulator":{"name":"Superintendencia de Seguros","url":"https://superseguros.gob.do/"},"insuranceComplaints":{"name":"Superintendencia de Seguros (policyholder complaints)","url":"https://superseguros.gob.do/","note":"No separate insurance ombudsman; the Superintendencia handles complaints."},"pensionScheme":{"name":"Sistema Dominicano de Pensiones (Ley 87-01), supervised by the Superintendencia de Pensiones (SIPEN)","url":"https://www.sipen.gob.do/"},"oldAgeAllowance":{"name":"Pensiones solidarias del Régimen Subsidiado, Consejo Nacional de Seguridad Social","url":"https://www.cnss.gob.do/"},"publicHealthCover":{"name":"Seguro Nacional de Salud (SeNaSa)","url":"https://www.arssenasa.gob.do/"},"depositInsurance":{"name":"Fondo de Contingencia, Banco Central de la República Dominicana","url":"https://www.bancentral.gov.do/","note":"Guarantee set by Ley Monetaria y Financiera 183-02, art. 64."},"statistics":{"name":"Oficina Nacional de Estadística (ONE)","url":"https://www.one.gob.do/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DO', 1, 'bank_deposit_avg_rate', 0.0709, NULL, 'sourced', 'Banco Central de la República Dominicana: tasas de interés pasivas de los bancos múltiples (promedio ponderado)', 'https://cdn.bancentral.gov.do/documents/estadisticas/sector-monetario-y-financiero/documents/tbm_pasivad.xlsx', '2026-10-30', 'Weighted average rate on financial certificates and time deposits in pesos at multiple banks, 1-30 October 2026 (preliminary); it fell from about 9.7% in mid-2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DO', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap found (interest rates are freely set under Ley 183-02) and the BCRD lending-rate tables do not report a credit card rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DO', 1, 'deposit_insurance_limit', 1860000, NULL, 'sourced', 'elDinero: Fondo de Contingencia (Ley Monetaria y Financiera 183-02, art. 64)', 'https://eldinero.com.do/381606/fondo-de-contingencia-de-los-depositantes-llego-a-rd35824-millones-al-cierre-de-2025/', '2026-09-21', 'Secondary source: the BCRD contingency fund guarantees each depositor up to RD$1,860,000 if a financial institution is liquidated.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DO', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The BCRD rate tables have no series for monthly recurring (programmed) savings; no official rate found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DO', 1, 'equity_return_base', 0.09, NULL, 'assumption', 'World Bank PA.NUS.FCRF (peso per dollar); BCRD deposit rates (181-360 days 6.49%, 5.8% after 10% tax)', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=DO', '2026-10-31', 'The local stock market trades almost no shares, so we use a global equity index of about 7% a year in dollars plus about 2% yearly peso depreciation, kept under the after-tax 1-year deposit rate plus 4 points.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DO', 1, 'equity_return_high', 0.12, NULL, 'assumption', 'World Bank PA.NUS.FCRF (peso per dollar)', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=DO', '2026-10-31', 'High case: strong global equities and faster peso depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DO', 1, 'equity_return_low', 0.05, NULL, 'assumption', 'World Bank PA.NUS.FCRF (peso per dollar); BCRD deposit rates', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=DO', '2026-10-31', 'Low case: weak global equities in dollars plus little peso depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DO', 1, 'fdr_1y_rate', 0.0649, NULL, 'sourced', 'Banco Central de la República Dominicana: tasas de interés pasivas de los bancos múltiples (promedio ponderado)', 'https://cdn.bancentral.gov.do/documents/estadisticas/sector-monetario-y-financiero/documents/tbm_pasivad.xlsx', '2026-10-30', 'Certificates and time deposits of 181-360 days, weighted average at multiple banks, 1-30 October 2026 (preliminary); 361 days-2 years 6.30%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DO', 1, 'fdr_3m_rate', 0.0743, NULL, 'sourced', 'Banco Central de la República Dominicana: tasas de interés pasivas de los bancos múltiples (promedio ponderado)', 'https://cdn.bancentral.gov.do/documents/estadisticas/sector-monetario-y-financiero/documents/tbm_pasivad.xlsx', '2026-10-30', 'Certificates and time deposits of 61-90 days, weighted average at multiple banks, 1-30 October 2026 (preliminary); 0-30 days 7.69%, 91-180 days 7.36%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DO', 1, 'fixed_income_return_base', 0.06, NULL, 'assumption', 'Banco Central de la República Dominicana: tasas de interés pasivas de los bancos múltiples (promedio ponderado)', 'https://cdn.bancentral.gov.do/documents/estadisticas/sector-monetario-y-financiero/documents/tbm_pasivad.xlsx', '2026-10-31', 'Base case: 1-year deposits at 6.5% (5.8% after tax) and BCRD bills at about 8% (7.5% after tax).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DO', 1, 'fixed_income_return_high', 0.075, NULL, 'assumption', 'BCRD Letras auction 29 October 2026: 161-day yield 8.32%', 'https://cdn.bancentral.gov.do/documents/instrumentos-de-inversion/instrumentos-operaciones-de-mercado-abierto/documents/Letras_bc_resultados.pdf', '2026-10-31', 'High case: central bank and government paper at about 8.3% less the 10% withholding.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DO', 1, 'fixed_income_return_low', 0.05, NULL, 'assumption', 'Banco Central de la República Dominicana: tasas de interés pasivas de los bancos múltiples (promedio ponderado)', 'https://cdn.bancentral.gov.do/documents/estadisticas/sector-monetario-y-financiero/documents/tbm_pasivad.xlsx', '2026-10-31', 'Low case: term deposits at about 5.5-6% less the 10% withholding, allowing for rates falling further.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DO', 1, 'goal_inflation_education', 0.06, NULL, 'assumption', 'elDinero (BCRD CPI release, September 2026): education prices up 1.85% in September alone on private-school fees', 'https://eldinero.com.do/384711/banco-central-informa-inflacion-interanual-a-septiembre-de-2026-es-de-5-12/', '2026-10-31', 'Private school fees push education prices above headline, so we plan with 6%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DO', 1, 'goal_inflation_health', 0.06, NULL, 'assumption', 'elDinero (BCRD CPI release, September 2026)', 'https://eldinero.com.do/384711/banco-central-informa-inflacion-interanual-a-septiembre-de-2026-es-de-5-12/', '2026-10-31', 'Headline CPI runs at about 5%; private clinic and medicine costs usually rise faster, so we plan with 6%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DO', 1, 'gold_return_base', 0.065, NULL, 'assumption', 'World Bank PA.NUS.FCRF (peso per dollar; about 46 in 2015 and 62 in 2025)', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=DO', '2026-10-31', 'Dollar gold trend of about 4.5% a year plus about 2% yearly peso depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DO', 1, 'gold_return_high', 0.1, NULL, 'assumption', 'World Bank PA.NUS.FCRF (peso per dollar)', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=DO', '2026-10-31', 'High case: strong dollar gold and faster peso depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DO', 1, 'gold_return_low', 0.03, NULL, 'assumption', 'World Bank PA.NUS.FCRF (peso per dollar)', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=DO', '2026-10-31', 'Low case: flat dollar gold with slight peso depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DO', 1, 'gratuity_rule', NULL, '{"daysPerYear":21,"daysPerYearAfter":23,"afterYears":5,"daysPerMonth":23.83}', 'sourced', 'Revista Mercado: auxilio de cesantía under art. 80 of the Labour Code (Ley 16-92)', 'https://revistamercado.do/money-invest/republica-dominicana/cesantia-laboral-en-rd-cuanto-te-corresponde-segun-tu-salario-y-antiguedad/', '2026-02-10', 'Secondary source: severance (cesantía) when the employer ends the contract without cause: 21 days'' ordinary wage per year for 1-5 years of service and 23 days per year after more than 5 years (shorter scales under 1 year); daily wage = monthly wage / 23.83. Not paid on resignation. This is severance on dismissal, not a payment on retirement or resignation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DO', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a major private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DO', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No public premium table for private health insurance by age was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DO', 1, 'inflation_cpi', 0.0512, NULL, 'sourced', 'elDinero, reporting the Banco Central de la República Dominicana CPI release', 'https://eldinero.com.do/384711/banco-central-informa-inflacion-interanual-a-septiembre-de-2026-es-de-5-12/', '2026-09-30', 'Secondary source (BCRD press release reported by elDinero, 13 October 2026): CPI rose 5.12% year on year in September 2026 (core 4.61%), down from a 5.67% peak in June.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DO', 1, 'inflation_projection', 0.04, NULL, 'assumption', 'BCRD inflation target 4% plus or minus 1 point; CPI 5.1-5.7% in mid-2026', 'https://eldinero.com.do/383116/banco-central-incrementa-su-tasa-de-politica-monetaria-en-25-puntos-basicos-de-5-25-a-5-50-anual/', '2026-10-31', 'We plan with the central bank''s 4% target, which inflation has mostly been near over the past decade, although 2026 readings run above it.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DO', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life is sold, but no published per-1,000 premium rates by age from the regulator or another public source were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DO', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No industry-wide life claim settlement ratio found from the Superintendencia de Seguros.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DO', 1, 'life_expectancy', 73.868, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=DO', '2024-12-31', '2024 World Bank value (older than 2025); UN WPP 2024 (via populationpyramid.net) gives 74.1 for 2026 (men 70.9, women 77.4).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DO', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":21.4,"men":19.5,"women":23.3},{"age":65,"total":17.7,"men":15.9,"women":19.4},{"age":70,"total":14.3,"men":12.7,"women":15.8},{"age":80,"total":8.7,"men":7.5,"women":9.8}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/dominican-republic/', '2026-07-01', 'Secondary source of UN WPP 2024 medium-variant projections for 2026; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DO', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":60,"womenAge":60,"over90Monthly":null,"meansTested":true}', 'sourced', 'elDinero: CNSS rules for solidarity pensions', 'https://eldinero.com.do/?p=347908', '2025-12-23', 'People over 60 whose income is below half the national minimum wage, after a poverty assessment (SIUBEN); also people with disabilities and some single mothers.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DO', 1, 'old_age_allowance_monthly', 6000, NULL, 'sourced', 'elDinero: solidarity pensions of the subsidised regime (Sistema Dominicano de Seguridad Social)', 'https://eldinero.com.do/?p=347908', '2025-12-23', 'Secondary source (published 23 December 2025): each solidarity pension pays RD$6,000 a month plus a Christmas payment; means-tested and granted by decree in limited batches (57,242 beneficiaries by September 2025), so not every eligible person receives it.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DO', 1, 'oop_health_share', 0.2506, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=DO', '2023-12-31', 'Latest World Bank value is for 2023 (older than 2025; no fresher official figure found).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DO', 1, 'policy_rate', 0.055, NULL, 'sourced', 'elDinero, reporting the BCRD monetary policy decision of September 2026', 'https://eldinero.com.do/383116/banco-central-incrementa-su-tasa-de-politica-monetaria-en-25-puntos-basicos-de-5-25-a-5-50-anual/', '2026-09-30', 'Secondary source: the BCRD raised its policy rate (TPM) by 25 basis points to 5.50% at its September 2026 meeting (1-day repo facility 6.00%, overnight deposits 4.75%); the October 2026 decision could not be confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DO', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":60,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'Superintendencia de Pensiones (SIPEN), Resolución 72-03 (Ley 87-01)', 'https://sipen.gob.do/documentos/norm_resolucion_sipen_72_03.pdf', '2026-10-31', 'Mandatory individual-account (AFP) system under Ley 87-01 for private and public employees: employee 2.87% plus employer 7.10% of salary (PwC Tax Summaries, 2026); old-age pension from 60 with 360 contributions, paid as programmed withdrawal or annuity; no automatic inflation indexing described in the sources read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DO', 1, 'retirement_accumulation_return_base', 0.075, NULL, 'assumption', 'Banco Central de la República Dominicana: tasas de interés pasivas de los bancos múltiples (promedio ponderado)', 'https://cdn.bancentral.gov.do/documents/estadisticas/sector-monetario-y-financiero/documents/tbm_pasivad.xlsx', '2026-10-31', 'Base case: about half global equities at 9% in pesos and half fixed income at 6%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DO', 1, 'retirement_accumulation_return_high', 0.095, NULL, 'assumption', 'Banco Central de la República Dominicana: tasas de interés pasivas de los bancos múltiples (promedio ponderado)', 'https://cdn.bancentral.gov.do/documents/estadisticas/sector-monetario-y-financiero/documents/tbm_pasivad.xlsx', '2026-10-31', 'High case with strong equities and higher local rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DO', 1, 'retirement_accumulation_return_low', 0.055, NULL, 'assumption', 'Banco Central de la República Dominicana: tasas de interés pasivas de los bancos múltiples (promedio ponderado)', 'https://cdn.bancentral.gov.do/documents/estadisticas/sector-monetario-y-financiero/documents/tbm_pasivad.xlsx', '2026-10-31', 'Low case for a balanced mix of deposits and global equities.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DO', 1, 'retirement_age_default', 60, NULL, 'sourced', 'Superintendencia de Pensiones (SIPEN), Resolución 72-03 on contributory pension benefits (Ley 87-01)', 'https://sipen.gob.do/documentos/norm_resolucion_sipen_72_03.pdf', '2026-10-31', 'Old-age pension from age 60 with at least 360 monthly contributions; a pension from 55 is possible if the individual account can fund it. Same for men and women. The resolution dates from 2003 and is still the rule we found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DO', 1, 'retirement_age_government', 60, NULL, 'sourced', 'Superintendencia de Pensiones (SIPEN), Resolución 72-03 (Ley 87-01)', 'https://sipen.gob.do/documentos/norm_resolucion_sipen_72_03.pdf', '2026-10-31', 'Public employees are covered by the same Ley 87-01 contributory system (60 with 360 contributions); members of the old civil-service scheme (Ley 379) aged up to 45 when the system began moved over with a recognition bond. Source dates from 2003.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DO', 1, 'retirement_return_base', 0.055, NULL, 'assumption', 'Banco Central de la República Dominicana: tasas de interés pasivas de los bancos múltiples (promedio ponderado)', 'https://cdn.bancentral.gov.do/documents/estadisticas/sector-monetario-y-financiero/documents/tbm_pasivad.xlsx', '2026-10-31', 'Base case below the after-tax 1-year deposit rate of about 5.8% (6.49% less the 10% withholding).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DO', 1, 'retirement_return_high', 0.07, NULL, 'assumption', 'BCRD Letras auction 29 October 2026: 161-day yield 8.32%', 'https://cdn.bancentral.gov.do/documents/instrumentos-de-inversion/instrumentos-operaciones-de-mercado-abierto/documents/Letras_bc_resultados.pdf', '2026-10-31', 'High case: a ladder of central bank and government paper at about 8% less tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DO', 1, 'retirement_return_low', 0.045, NULL, 'assumption', 'Banco Central de la República Dominicana: tasas de interés pasivas de los bancos múltiples (promedio ponderado)', 'https://cdn.bancentral.gov.do/documents/estadisticas/sector-monetario-y-financiero/documents/tbm_pasivad.xlsx', '2026-10-31', 'Low case: short deposits after the 10% withholding, with rates easing.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DO', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate sold directly to individuals was found; Ministry of Finance peso bonds reach individuals through the stock market after auction.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DO', 1, 'savings_account_rate', 0.0053, NULL, 'sourced', 'Banco Central de la República Dominicana: tasas de interés pasivas de los bancos múltiples (promedio ponderado)', 'https://cdn.bancentral.gov.do/documents/estadisticas/sector-monetario-y-financiero/documents/tbm_pasivad.xlsx', '2026-10-30', 'Weighted average rate on savings deposits at multiple banks, average of 1-30 October 2026 (preliminary).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DO', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":8},{"year":2040,"value":5.3},{"year":2065,"value":3.2}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/dominican-republic/2040/', '2025-12-31', '100 / old-age dependency ratio: 12.48 (2025, World Bank), 18.7 (2040) and 31.1 (2065, populationpyramid.net/dominican-republic/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DO', 1, 'tax_bank_interest', 0.1, NULL, 'sourced', 'Dirección General de Impuestos Internos (DGII), technical consultation on interest withholding (Código Tributario art. 306 bis)', 'https://dgii.gov.do/legislacion/consultas/Consultas%20Tecnicas%202025/Enero/Consulta%2012-Retenci%C3%B3n%20de%20ISR%20pago%20de%20intereses.pdf', '2025-01-23', 'Interest paid to resident individuals is subject to a 10% income-tax withholding, a final payment or an advance depending on the taxpayer''s return. (PwC Tax Summaries describes such interest as exempt; we follow the tax authority.)', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DO', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate for individuals exists to tax; interest on other instruments paid to individuals falls under the 10% withholding of art. 306 bis.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DO', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 91-day treasury bill yield found. The nearest short-term figure: BCRD Letras auction of 29 October 2026 awarded only the 161-day bill, at a weighted average yield of 8.32% (cdn.bancentral.gov.do Letras_bc_resultados.pdf).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DO', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Ministry of Finance (Crédito Público) auction results could not be opened (HTTP 403); no 10-year peso bond yield found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DO', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Ministry of Finance (Crédito Público) auction results could not be opened (HTTP 403); no 5-year peso bond yield found.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('DZ', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"DZ","iso3":"DZA","nameEn":"Algeria","nameNative":"الجزائر","region":"middle_east_north_africa","languages":["ar","arq","fr","kab","en"],"currency":{"code":"DZD","symbol":"DA","decimals":2,"compact":"intl","usdRate":{"value":135.5079,"status":"sourced","sourceName":"Bank of Algeria, daily exchange rate quotation of 30 October 2026","sourceUrl":"https://www.bank-of-algeria.dz/taux-de-change-journalier/","asOf":"2026-10-30","note":"Bank of Algeria quotation of the dinar against the US dollar for 30 October 2026. The verifier could not open the Bank of Algeria page (TLS certificate error), but Trading Economics showed USD/DZD at 135.79 on 3 November 2026, which agrees with it. World Bank 2025 average: 131.61. CLDR gives no narrow symbol; ''DA'' is how prices are written locally."}},"instruments":{"savings_account":{"available":true,"localName":"دفتر التوفير","localNameEn":"Savings book (livret d''épargne)","note":"Savings books are offered by banks and the postal network; rates are low."},"fdr_3m":{"available":true,"localName":"وديعة لأجل (3 أشهر)","localNameEn":"Term deposit (dépôt à terme, 3 months)"},"fdr_1y":{"available":true,"localName":"وديعة لأجل (سنة)","localNameEn":"Term deposit (dépôt à terme, 1 year)","note":"Banks also sell short-term bank bonds (bons de caisse)."},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No standard monthly recurring deposit product was found."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No continuously sold government savings certificate; the Treasury has issued occasional national bonds to the public."},"tbill_91d":{"available":true,"localName":"سندات الخزينة قصيرة الأجل","localNameEn":"Treasury bills (BTC)","note":"Sold at auction mainly to banks and other institutions; access for individuals is limited."},"tbond_5y":{"available":true,"localName":"سندات الخزينة المماثلة","localNameEn":"Treasury bonds (OAT)","note":"Issued at auction, mainly held by banks and insurers."},"tbond_10y":{"available":true,"localName":"سندات الخزينة المماثلة (10 سنوات)","localNameEn":"Treasury bonds (OAT, 10 years)","note":"Issued at auction, mainly held by banks and insurers."},"equity_fund":{"available":false,"localName":null,"localNameEn":null,"note":"No diversified equity or index fund sold to retail investors was found. The Algiers Stock Exchange, supervised by COSOB, lists only a few companies. This was not confirmed by a source saying none exists."},"gold":{"available":true,"localName":"الذهب","localNameEn":"Gold","note":"Gold is bought mostly as jewellery; availability of investment bars and coins was not confirmed."}},"institutions":{"centralBank":{"name":"Bank of Algeria (Banque d''Algérie)","url":"https://www.bank-of-algeria.dz/"},"insuranceRegulator":{"name":"Insurance Supervision Commission (Commission de Supervision des Assurances), Ministry of Finance","url":"https://www.mf.gov.dz/"},"insuranceComplaints":null,"pensionScheme":{"name":"National Pension Fund (Caisse Nationale des Retraites, CNR)","url":"https://www.cnr.dz/"},"oldAgeAllowance":null,"publicHealthCover":{"name":"National Social Insurance Fund for Salaried Workers (CNAS); public hospitals give free care","url":"https://www.cnas.dz/"},"depositInsurance":{"name":"Bank Deposit Guarantee Company (Société de Garantie des Dépôts Bancaires), under the Bank of Algeria","url":"https://www.bank-of-algeria.dz/cadre-reglementaire-2/"},"statistics":{"name":"National Statistics Office (Office National des Statistiques, ONS)","url":"https://www.ons.dz/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DZ', 1, 'bank_deposit_avg_rate', 0.0175, NULL, 'sourced', 'World Bank WDI, deposit interest rate (FR.INR.DPST), Algeria', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=DZ', '2025-12-31', '1.75% for 2025 (IMF IFS series via the World Bank); no fresher Bank of Algeria figure could be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DZ', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap or typical rate for credit card balances was found; card payments are mostly debit (CIB/Edahabia).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DZ', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'A deposit guarantee fund exists (Société de Garantie des Dépôts Bancaires), but the current cover per depositor could not be read from the Bank of Algeria regulations.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DZ', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No monthly recurring deposit scheme or rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DZ', 1, 'equity_return_base', 0.04, NULL, 'assumption', 'World Bank deposit rate 1.75% (2025); inflation assumption 5%', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=DZ', '2026-10-31', 'Kept within 4 points of the after-tax safe rate (about 1.5%) and below that cap, because the local market is tiny and has no long, liquid index record.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DZ', 1, 'equity_return_high', 0.08, NULL, 'assumption', 'World Bank deposit rate 1.75%; inflation assumption 5%', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=DZ', '2026-10-31', 'High case: equities beat inflation by about 3 points a year.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DZ', 1, 'equity_return_low', 0.01, NULL, 'assumption', 'Bank of Algeria / World Bank deposit rate 1.75%; very small Algiers Stock Exchange', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=DZ', '2026-10-31', 'The Algiers Stock Exchange lists only a handful of companies with little trading, so the low case is close to zero in local currency.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DZ', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published rate for 1-year term deposits was found; the Bank of Algeria statistics pages could not be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DZ', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published rate for 3-month term deposits was found; the Bank of Algeria statistics pages could not be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DZ', 1, 'fixed_income_return_base', 0.015, NULL, 'assumption', 'World Bank deposit rate 1.75% (2025)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=DZ', '2026-10-31', 'Base case: the average deposit rate less roughly 10% withholding tax (rate not confirmed), so about 1.5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DZ', 1, 'fixed_income_return_high', 0.03, NULL, 'assumption', 'World Bank deposit rate 1.75%; policy rate 2.5%', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=DZ', '2026-10-31', 'High case: longer term deposits and Treasury paper at around the policy rate or a little above.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DZ', 1, 'fixed_income_return_low', 0.01, NULL, 'assumption', 'World Bank deposit rate 1.75% (2025)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=DZ', '2026-10-31', 'Low case: ordinary savings rates below the average deposit rate, after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DZ', 1, 'goal_inflation_education', 0.05, NULL, 'assumption', 'Trading Economics CPI (8.0% in August 2026); World Bank CPI 2021-2025; inflation assumption 5%', 'https://tradingeconomics.com/algeria/inflation-cpi', '2026-10-31', 'Public education is free and no education CPI series could be read, so education costs are planned at the general 5% inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DZ', 1, 'goal_inflation_health', 0.06, NULL, 'assumption', 'Trading Economics CPI (8.0% in August 2026); World Bank CPI 2021-2025; inflation assumption 5%', 'https://tradingeconomics.com/algeria/inflation-cpi', '2026-10-31', 'Private care costs usually outpace general prices, so 1 point above the 5% inflation assumption is used; no health CPI series could be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DZ', 1, 'gold_return_base', 0.06, NULL, 'assumption', 'Bank of Algeria exchange rate; long-run dollar gold trend of about 4% a year', 'https://www.bank-of-algeria.dz/taux-de-change-journalier/', '2026-10-31', 'Base case: dollar gold trend of about 4% plus about 2% a year of dinar depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DZ', 1, 'gold_return_high', 0.1, NULL, 'assumption', 'Bank of Algeria exchange rate; long-run dollar gold trend', 'https://www.bank-of-algeria.dz/taux-de-change-journalier/', '2026-10-31', 'High case: strong dollar gold and faster dinar depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DZ', 1, 'gold_return_low', 0.02, NULL, 'assumption', 'Bank of Algeria exchange rate (about 4.5% dinar fall against the dollar over the past year)', 'https://www.bank-of-algeria.dz/taux-de-change-journalier/', '2026-10-31', 'Low case: flat dollar gold with slow dinar depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DZ', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No statutory end-of-service or retirement gratuity for private employees was confirmed; Law No. 90-11 on labour relations and collective agreements could not be checked.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DZ', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a major private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DZ', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premiums by age were found from a public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DZ', 1, 'inflation_cpi', 0.0801, NULL, 'sourced', 'Trading Economics, citing the Office National des Statistiques (ONS), national CPI August 2026', 'https://tradingeconomics.com/algeria/inflation-cpi', '2026-08-31', 'Annual inflation rose to 8.01% in August 2026 from 6.73% in July. This is a secondary source because the ONS site could not be opened (TLS certificate error). The verifier replaced an unconfirmed ONS Algiers figure of 8.3%. World Bank 2025 average 1.4%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DZ', 1, 'inflation_projection', 0.05, NULL, 'assumption', 'World Bank CPI inflation 2021-2025 (about 6% average); ONS 12-month average 3.9% to August 2026', 'https://data.worldbank.org/indicator/FP.CPI.TOTL.ZG?locations=DZ', '2026-10-31', 'The Bank of Algeria publishes no numeric inflation target, so a rounded 5% is used: below the 2021-2025 average of about 6% and the 8.0% reading of August 2026, but above the 1.4% of 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DZ', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Death-cover (temporaire décès) insurance is sold, mostly with loans, but no published premium rates per DZD 1,000 of cover by age were found from a public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DZ', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No industry-wide life claim settlement ratio was found from the insurance supervisor (Commission de Supervision des Assurances).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DZ', 1, 'life_expectancy', 76.475, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN), Algeria', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=DZ', '2024-12-31', '76.5 years in 2024 (men 75.1, women 77.9).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DZ', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":21.1,"men":20.1,"women":22.1},{"age":65,"total":17,"men":16.1,"women":17.9},{"age":70,"total":13.3,"men":12.5,"women":14},{"age":80,"total":7.4,"men":6.9,"women":7.8}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/algeria/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DZ', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'Eligibility rules of the solidarity allowance (Allocation forfaitaire de solidarité) could not be read from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DZ', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'A means-tested flat solidarity allowance (Allocation forfaitaire de solidarité) for older people without income exists, but its current amount could not be read from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DZ', 1, 'oop_health_share', 0.45, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), Algeria', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=DZ', '2023-12-31', '45.0% in 2023 (WHO Global Health Expenditure Database via the World Bank); older than 2025, the latest available.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DZ', 1, 'policy_rate', 0.025, NULL, 'sourced', 'Trading Economics, Bank of Algeria benchmark (discount) rate', 'https://tradingeconomics.com/algeria/interest-rate', '2026-09-30', '2.50%, at a record low since January 2026 and unchanged at the latest reading (reference September 2026); secondary source because the Bank of Algeria site loads its rate tables by script.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DZ', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":60,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'Law No. 16-15 of 31 December 2016 amending Law No. 83-12 on retirement', 'https://www.joradp.dz/FTP/jo-francais/2016/F2016078.pdf', '2017-01-01', 'Compulsory pay-as-you-go pension for salaried workers, run by the Caisse Nationale des Retraites (CNR). Under Law 16-15 (Art. 6 of Law 83-12 as amended), the pension starts at 60 after at least 15 years of work; women may retire from 55 at their request. Law 16-15 abolished retirement without an age condition from 2019. The law contains no automatic price-indexation rule, so inflationLinked is false (conservative); tax treatment was not checked. The law is older than 2025 but still in force.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DZ', 1, 'retirement_accumulation_return_base', 0.03, NULL, 'assumption', 'World Bank deposit rate 1.75%; equity base 4%; gold base 6%', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=DZ', '2026-10-31', 'Base case: a balanced mix of deposits, gold and some equity, below inflation-plus because local markets are shallow.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DZ', 1, 'retirement_accumulation_return_high', 0.06, NULL, 'assumption', 'World Bank deposit rate 1.75%; equity high 8%; gold high 10%', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=DZ', '2026-10-31', 'High case: a growth-leaning mix with gold.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DZ', 1, 'retirement_accumulation_return_low', 0.015, NULL, 'assumption', 'World Bank deposit rate 1.75%; tiny local equity market', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=DZ', '2026-10-31', 'Low case: a mix earning about the after-tax deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DZ', 1, 'retirement_age_default', 60, NULL, 'sourced', 'Law No. 16-15 of 31 December 2016 amending Law No. 83-12 on retirement (Journal officiel No. 78, 2016)', 'https://www.joradp.dz/FTP/jo-francais/2016/F2016078.pdf', '2017-01-01', 'Law 16-15 (Art. 6 of Law 83-12 as amended) sets the pension age at 60 with at least 15 years of work; women may retire from 55 at their request. Retirement without an age condition ended on 1 January 2019. The law is older than 2025 but still in force, and it applies to anyone born after 1975.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DZ', 1, 'retirement_age_government', 60, NULL, 'sourced', 'Law No. 16-15 amending Law No. 83-12 on retirement (Journal officiel No. 78, 2016)', 'https://www.joradp.dz/FTP/jo-francais/2016/F2016078.pdf', '2017-01-01', 'Law No. 83-12 covers all salaried workers including public employees, so civil servants also retire at 60 (women from 55 on request); older than 2025 but still in force.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DZ', 1, 'retirement_return_base', 0.015, NULL, 'assumption', 'World Bank deposit rate 1.75% (2025)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=DZ', '2026-10-31', 'Base case: the average deposit rate after roughly 10% withholding tax; not above the after-tax safe rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DZ', 1, 'retirement_return_high', 0.025, NULL, 'assumption', 'World Bank deposit rate 1.75%; policy rate 2.5%', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=DZ', '2026-10-31', 'High case: term deposits and Treasury paper near the policy rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DZ', 1, 'retirement_return_low', 0.01, NULL, 'assumption', 'World Bank deposit rate 1.75% (2025)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=DZ', '2026-10-31', 'Low case: savings-book rates after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DZ', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No current government savings certificate or retail savings bond for individuals was found; the Treasury has run one-off national bond issues in the past.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DZ', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No official or industry-wide rate for ordinary savings books (livret d''épargne) was found; web search was unavailable for part of this research.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DZ', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":9.3},{"year":2040,"value":5.7},{"year":2065,"value":3.2}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/algeria/2040/', '2025-12-31', '100 / old-age dependency ratio: 10.76 (2025, World Bank), 17.5 (2040) and 31.3 (2065, populationpyramid.net/algeria/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DZ', 1, 'tax_bank_interest', NULL, NULL, 'missing', '', '', '2026-10-31', 'The withholding rate on bank and savings interest in the Code des impôts directs could not be read from an official or PwC page (PwC Worldwide Tax Summaries has no Algeria page).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DZ', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate for individuals was found, and the tax rate on Treasury securities income could not be confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DZ', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Treasury bill (BTC) auction results are published by the Ministry of Finance, whose site could not be reached.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DZ', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 10-year Treasury bond yield could be read; the Ministry of Finance site could not be reached.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('DZ', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 5-year Treasury bond (OAT) yield could be read; the Ministry of Finance site could not be reached.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('EC', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"EC","iso3":"ECU","nameEn":"Ecuador","nameNative":"Ecuador","region":"latin_america_caribbean","languages":["es","qu"],"currency":{"code":"USD","symbol":"$","decimals":2,"compact":"intl","usdRate":{"value":1,"status":"sourced","sourceName":"World Bank WDI PA.NUS.FCRF","sourceUrl":"https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=EC","asOf":"2025-12-31","note":"Ecuador has used the US dollar as its official currency since 2000."}},"instruments":{"savings_account":{"available":true,"localName":"Cuenta de ahorros","localNameEn":"Savings account","note":"Savings deposits pay about 1.6% (BCE reference rate); interest is tax-exempt.","sourceUrl":"https://contenido.bce.fin.ec/documentos/Estadisticas/SectorMonFin/TasasInteres/Indice.htm"},"fdr_3m":{"available":true,"localName":"Depósito a plazo fijo","localNameEn":"Fixed-term deposit (3 months)","note":"Also called póliza de acumulación.","sourceUrl":"https://contenido.bce.fin.ec/documentos/Estadisticas/SectorMonFin/TasasInteres/Indice.htm"},"fdr_1y":{"available":true,"localName":"Depósito a plazo fijo","localNameEn":"Fixed-term deposit (1 year)","note":"Interest on deposits of 180 days or more is exempt from income tax.","sourceUrl":"https://contenido.bce.fin.ec/documentos/Estadisticas/SectorMonFin/TasasInteres/Indice.htm"},"dps":{"available":false,"localName":null,"note":"No standard monthly recurring-deposit product with a published rate was found."},"sanchayapatra_5y":{"available":false,"localName":null,"note":"No government savings certificate or retail savings bond is sold directly to individuals."},"tbill_91d":{"available":true,"localName":"Certificados de Tesorería (CETES)","localNameEn":"Treasury certificates","note":"Short-term Treasury paper issued by the Ministry of Economy and Finance."},"tbond_5y":{"available":true,"localName":"Bonos del Estado","localNameEn":"Government bonds","note":"Government dollar bonds issued by the Ministry of Economy and Finance."},"tbond_10y":{"available":true,"localName":"Bonos del Estado","localNameEn":"Government bonds","note":"Long government bonds are mainly international dollar eurobonds.","sourceUrl":"https://ire.finanzas.gob.ec/content/2026/01/2026.01.27_61.pdf"},"equity_fund":{"available":false,"localName":null,"note":"Local investment funds invest mainly in fixed income; no diversified local equity index fund was found."},"gold":{"available":true,"localName":"Oro","localNameEn":"Gold","note":"Gold can be bought legally from jewellers and dealers."}},"institutions":{"centralBank":{"name":"Banco Central del Ecuador","url":"https://www.bce.fin.ec/"},"insuranceRegulator":{"name":"Superintendencia de Compañías, Valores y Seguros","url":"https://www.supercias.gob.ec/"},"insuranceComplaints":{"name":"Superintendencia de Compañías, Valores y Seguros (complaints)","url":"https://www.supercias.gob.ec/","note":"No separate insurance ombudsman; the Superintendencia handles policyholder complaints."},"pensionScheme":{"name":"Instituto Ecuatoriano de Seguridad Social (IESS)","url":"https://www.iess.gob.ec/"},"oldAgeAllowance":{"name":"Pensión para adultos mayores, Ministerio de Inclusión Económica y Social (MIES)","url":"https://www.inclusion.gob.ec/"},"publicHealthCover":{"name":"Ministerio de Salud Pública (free public health care)","url":"https://www.salud.gob.ec/","note":"Formal-sector workers also have IESS health insurance."},"depositInsurance":{"name":"Corporación del Seguro de Depósitos (COSEDE)","url":"https://www.cosede.gob.ec/"},"statistics":{"name":"Instituto Nacional de Estadística y Censos (INEC)","url":"https://www.ecuadorencifras.gob.ec/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EC', 1, 'bank_deposit_avg_rate', 0.0483, NULL, 'sourced', 'Banco Central del Ecuador: tasas de interés (vigentes noviembre 2026)', 'https://contenido.bce.fin.ec/documentos/Estadisticas/SectorMonFin/TasasInteres/Indice.htm', '2026-10-31', 'Tasa pasiva referencial, the BCE''s weighted average deposit rate. Published by the BCE as the reference rates for November 2026, computed from deposits taken in the preceding weeks. World Bank FR.INR.DPST gives 5.3% for 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EC', 1, 'credit_card_rate_cap', 0.1677, NULL, 'sourced', 'Banco Central del Ecuador: tasas de interés (vigentes noviembre 2026)', 'https://contenido.bce.fin.ec/documentos/Estadisticas/SectorMonFin/TasasInteres/Indice.htm', '2026-10-31', 'Maximum effective annual rate for the consumer credit segment, which applies to credit card balances. Published by the BCE as the reference rates for November 2026, computed from deposits taken in the preceding weeks.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EC', 1, 'deposit_insurance_limit', 32000, NULL, 'sourced', 'Primicias: COSEDE deposit insurance coverage', 'https://www.primicias.ec/economia/que-seguro-cosede-bancos-cooperativas-liquidacion-quiebra-requisitos-121025/', '2026-04-22', 'Secondary source (COSEDE site blocked): up to USD 32,000 per depositor in public and private banks and mutualistas; cooperatives USD 1,000-32,000 by segment.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EC', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The BCE rate tables have no series for monthly recurring deposits; no official rate found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EC', 1, 'equity_return_base', 0.075, NULL, 'assumption', 'Banco Central del Ecuador: tasas de interés (vigentes noviembre 2026); 361-day deposits 6.19%, tax-exempt', 'https://contenido.bce.fin.ec/documentos/Estadisticas/SectorMonFin/TasasInteres/Indice.htm', '2026-10-31', 'The local stock market trades few shares, so we use a global equity index of about 7-8% a year in US dollars (Ecuador''s currency), below the tax-free 1-year deposit rate plus 4 points.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EC', 1, 'equity_return_high', 0.1, NULL, 'assumption', 'Banco Central del Ecuador: tasas de interés (vigentes noviembre 2026)', 'https://contenido.bce.fin.ec/documentos/Estadisticas/SectorMonFin/TasasInteres/Indice.htm', '2026-10-31', 'High case: strong global equities in dollars.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EC', 1, 'equity_return_low', 0.04, NULL, 'assumption', 'Banco Central del Ecuador: tasas de interés (vigentes noviembre 2026)', 'https://contenido.bce.fin.ec/documentos/Estadisticas/SectorMonFin/TasasInteres/Indice.htm', '2026-10-31', 'Low case: weak global equities in dollars.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EC', 1, 'fdr_1y_rate', 0.0619, NULL, 'sourced', 'Banco Central del Ecuador: tasas de interés (vigentes noviembre 2026)', 'https://contenido.bce.fin.ec/documentos/Estadisticas/SectorMonFin/TasasInteres/Indice.htm', '2026-10-31', 'Effective reference rate for term deposits of 361 days and more (181-360 days 4.83%). Published by the BCE as the reference rates for November 2026, computed from deposits taken in the preceding weeks.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EC', 1, 'fdr_3m_rate', 0.042, NULL, 'sourced', 'Banco Central del Ecuador: tasas de interés (vigentes noviembre 2026)', 'https://contenido.bce.fin.ec/documentos/Estadisticas/SectorMonFin/TasasInteres/Indice.htm', '2026-10-31', 'Effective reference rate for term deposits of 61-90 days (30-60 days 3.96%, 91-120 days 4.38%). Published by the BCE as the reference rates for November 2026, computed from deposits taken in the preceding weeks.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EC', 1, 'fixed_income_return_base', 0.05, NULL, 'assumption', 'Banco Central del Ecuador: tasas de interés (vigentes noviembre 2026)', 'https://contenido.bce.fin.ec/documentos/Estadisticas/SectorMonFin/TasasInteres/Indice.htm', '2026-10-31', 'Base case: a mix of 6-12 month deposits (4.8%) and 1-year-plus deposits (6.2%), tax-exempt at 180 days or more.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EC', 1, 'fixed_income_return_high', 0.06, NULL, 'assumption', 'Banco Central del Ecuador: tasas de interés (vigentes noviembre 2026)', 'https://contenido.bce.fin.ec/documentos/Estadisticas/SectorMonFin/TasasInteres/Indice.htm', '2026-10-31', 'High case: deposits of 361 days and more at about 6.2%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EC', 1, 'fixed_income_return_low', 0.04, NULL, 'assumption', 'Banco Central del Ecuador: tasas de interés (vigentes noviembre 2026)', 'https://contenido.bce.fin.ec/documentos/Estadisticas/SectorMonFin/TasasInteres/Indice.htm', '2026-10-31', 'Low case: 3-6 month deposits at about 4-4.4%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EC', 1, 'goal_inflation_education', 0.03, NULL, 'assumption', 'Trading Economics (INEC CPI): education index 100.25 in September 2026', 'https://tradingeconomics.com/ecuador/inflation-cpi', '2026-10-31', 'Education prices are near flat in 2026; private tuition usually rises somewhat faster than headline, so we plan with 3%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EC', 1, 'goal_inflation_health', 0.03, NULL, 'assumption', 'Trading Economics (INEC CPI): health index 100.55 in September 2026', 'https://tradingeconomics.com/ecuador/inflation-cpi', '2026-10-31', 'Health prices are rising slowly in 2026, but private medical costs tend to outpace a 2% headline, so we plan with 3%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EC', 1, 'gold_return_base', 0.045, NULL, 'assumption', 'World Bank Commodity Markets (Pink Sheet) gold price', 'https://www.worldbank.org/en/research/commodity-markets', '2026-10-31', 'Long-run dollar gold trend of about 4-5% a year; no currency effect in a dollarised economy.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EC', 1, 'gold_return_high', 0.07, NULL, 'assumption', 'World Bank Commodity Markets (Pink Sheet) gold price', 'https://www.worldbank.org/en/research/commodity-markets', '2026-10-31', 'High case: strong dollar gold.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EC', 1, 'gold_return_low', 0.01, NULL, 'assumption', 'World Bank Commodity Markets (Pink Sheet) gold price', 'https://www.worldbank.org/en/research/commodity-markets', '2026-10-31', 'Low case: flat dollar gold; no currency effect since Ecuador uses the dollar.', 0);
