INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EC', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a major private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EC', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No public premium table for private health insurance by age was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EC', 1, 'inflation_cpi', 0.0134, NULL, 'sourced', 'Trading Economics (INEC consumer price index)', 'https://tradingeconomics.com/ecuador/inflation-cpi', '2026-09-30', 'Secondary source: annual inflation 1.34% in September 2026 (1.12% in August); the INEC release for September could not be reached.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EC', 1, 'inflation_projection', 0.02, NULL, 'assumption', 'World Bank FP.CPI.TOTL.ZG (0.7% in 2025); CPI 1.1-1.7% in 2026', 'https://data.worldbank.org/indicator/FP.CPI.TOTL.ZG?locations=EC', '2026-10-31', 'Ecuador uses the US dollar and has no inflation target; inflation averaged under 2% a year in 2021-2025 (peak 3.5% in 2022), so we plan with 2%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EC', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life is sold, but no published per-1,000 premium rates by age from the regulator or another public source were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EC', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No industry-wide life claim settlement ratio found from the Superintendencia de Compañías, Valores y Seguros.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EC', 1, 'life_expectancy', 77.579, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=EC', '2024-12-31', '2024 World Bank value (older than 2025); UN WPP 2024 (via populationpyramid.net) gives 77.9 for 2026 (men 75.3, women 80.6).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EC', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":22.8,"men":21.3,"women":24.3},{"age":65,"total":18.8,"men":17.4,"women":20.1},{"age":70,"total":14.9,"men":13.6,"women":16.1},{"age":80,"total":8.2,"men":7.3,"women":9}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/ecuador/', '2026-07-01', 'Secondary source of UN WPP 2024 medium-variant projections for 2026; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EC', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'MIES site unreachable; age and means-test rules for the non-contributory pension could not be confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EC', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'A non-contributory pension for older people is paid by the Ministerio de Inclusión Económica y Social (MIES), but its site could not be reached and the 2026 amount could not be confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EC', 1, 'oop_health_share', 0.3089, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=EC', '2023-12-31', 'Latest World Bank value is for 2023 (older than 2025; no fresher official figure found).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EC', 1, 'policy_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Ecuador is officially dollarised and the Banco Central del Ecuador sets no monetary policy rate; it publishes reference and maximum lending rates instead.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EC', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":60,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'Expreso: IESS old-age retirement rules 2026', 'https://www.expreso.ec/tramites-y-servicios/todo-lo-que-debes-saber-sobre-la-jubilacion-del-iess-en-ecuador-este-2026-282288.html', '2026-05-17', 'IESS defined-benefit pension: employee 9.45% plus employer 12.15% of pay (PwC Tax Summaries, July 2026); pension from 60 with 360 contributions (or 65/180, 70/120, any age/480); minimum 50% of the basic wage (USD 241 in 2026), maximum 5.5 times the basic wage. inflationLinked is false only because no indexation rule could be confirmed in the sources read (IESS and Ministry sites were unreachable).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EC', 1, 'retirement_accumulation_return_base', 0.06, NULL, 'assumption', 'Banco Central del Ecuador: tasas de interés (vigentes noviembre 2026)', 'https://contenido.bce.fin.ec/documentos/Estadisticas/SectorMonFin/TasasInteres/Indice.htm', '2026-10-31', 'Base case: about half global equities at 7.5% and half deposits at 5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EC', 1, 'retirement_accumulation_return_high', 0.075, NULL, 'assumption', 'Banco Central del Ecuador: tasas de interés (vigentes noviembre 2026)', 'https://contenido.bce.fin.ec/documentos/Estadisticas/SectorMonFin/TasasInteres/Indice.htm', '2026-10-31', 'High case with strong equities.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EC', 1, 'retirement_accumulation_return_low', 0.045, NULL, 'assumption', 'Banco Central del Ecuador: tasas de interés (vigentes noviembre 2026)', 'https://contenido.bce.fin.ec/documentos/Estadisticas/SectorMonFin/TasasInteres/Indice.htm', '2026-10-31', 'Low case for a balanced mix of deposits and global equities.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EC', 1, 'retirement_age_default', 60, NULL, 'sourced', 'Expreso: IESS old-age retirement rules 2026', 'https://www.expreso.ec/tramites-y-servicios/todo-lo-que-debes-saber-sobre-la-jubilacion-del-iess-en-ecuador-este-2026-282288.html', '2026-05-17', 'Secondary source: IESS old-age pension at 60 with 360 monthly contributions, 65 with 180, 70 with 120, or any age with 480; same for men and women. Many retire at 65 with 15 years.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EC', 1, 'retirement_age_government', 60, NULL, 'sourced', 'Expreso: IESS old-age retirement rules 2026', 'https://www.expreso.ec/tramites-y-servicios/todo-lo-que-debes-saber-sobre-la-jubilacion-del-iess-en-ecuador-este-2026-282288.html', '2026-05-17', 'Public servants are IESS members and retire on the same age and contribution rules.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EC', 1, 'retirement_return_base', 0.045, NULL, 'assumption', 'Banco Central del Ecuador: tasas de interés (vigentes noviembre 2026)', 'https://contenido.bce.fin.ec/documentos/Estadisticas/SectorMonFin/TasasInteres/Indice.htm', '2026-10-31', 'Base case below the tax-exempt 6-12 month deposit rate of 4.8%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EC', 1, 'retirement_return_high', 0.055, NULL, 'assumption', 'Banco Central del Ecuador: tasas de interés (vigentes noviembre 2026)', 'https://contenido.bce.fin.ec/documentos/Estadisticas/SectorMonFin/TasasInteres/Indice.htm', '2026-10-31', 'High case: a ladder of 1-year-plus deposits at about 6%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EC', 1, 'retirement_return_low', 0.035, NULL, 'assumption', 'Banco Central del Ecuador: tasas de interés (vigentes noviembre 2026)', 'https://contenido.bce.fin.ec/documentos/Estadisticas/SectorMonFin/TasasInteres/Indice.htm', '2026-10-31', 'Low case: short deposits at about 4% with some cash held at lower rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EC', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate or retail savings bond sold directly to individuals was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EC', 1, 'savings_account_rate', 0.016, NULL, 'sourced', 'Banco Central del Ecuador: tasas de interés (vigentes noviembre 2026)', 'https://contenido.bce.fin.ec/documentos/Estadisticas/SectorMonFin/TasasInteres/Indice.htm', '2026-10-31', 'Reference rate on savings deposits. Published by the BCE as the reference rates for November 2026, computed from deposits taken in the preceding weeks.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EC', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":7.9},{"year":2040,"value":5.2},{"year":2065,"value":2.5}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/ecuador/2040/', '2025-12-31', '100 / old-age dependency ratio: 12.73 (2025, World Bank), 19.4 (2040) and 39.7 (2065, populationpyramid.net/ecuador/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EC', 1, 'tax_bank_interest', 0, NULL, 'sourced', 'Primicias: SRI raises withholding on financial returns to 3% (March 2026)', 'https://www.primicias.ec/economia/sri-retencion-impuesto-renta-inversiones-polizas-bancos-cooperativas-117479/', '2026-03-01', 'Secondary source: interest on term deposits of 180 days or more is exempt from income tax (Ley de Régimen Tributario Interno art. 9) and savings-account interest is exempt (PwC Tax Summaries, July 2026); shorter deposits have 3% withheld from 1 March 2026 as an advance on income tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EC', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate for individuals was found, so no tax rate applies to report.', 0);
