INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EC', 1, 'tbond_10y_rate', 0.08975, NULL, 'sourced', 'Ministerio de Economía y Finanzas, Bulletin 061 (eurobond issue)', 'https://ire.finanzas.gob.ec/content/2026/01/2026.01.27_61.pdf', '2026-01-26', 'US-dollar eurobonds maturing 2034 (about 8 years) and 2039 (about 13 years) issued on 26 January 2026 at an average yield of 8.975%; used as the closest available figure to a 10-year government yield (issue yield, not a current market yield).', 0);
