INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('EE', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"EE","iso3":"EST","nameEn":"Estonia","nameNative":"Eesti","region":"europe_central_asia","languages":["et","ru","en","fi"],"currency":{"code":"EUR","symbol":"€","decimals":2,"compact":"intl","usdRate":{"value":0.8951,"status":"sourced","sourceName":"European Central Bank euro reference rate (USD)","sourceUrl":"https://www.ecb.europa.eu/stats/policy_and_exchange_rates/euro_reference_exchange_rates/html/eurofxref-graph-usd.en.html","asOf":"2026-10-30","note":"EUR 1 = USD 1.1172, so about EUR 0.895 per US dollar; World Bank 2025 average 0.885."}},"instruments":{"savings_account":{"available":true,"localName":"Hoiuarve","localNameEn":"Savings account","sourceUrl":"https://data-api.ecb.europa.eu/service/data/MIR/M.EE.B.L21.A.R.A.2250.EUR.N"},"fdr_3m":{"available":true,"localName":"Tähtajaline hoius","localNameEn":"Term deposit (3 months)"},"fdr_1y":{"available":true,"localName":"Tähtajaline hoius","localNameEn":"Term deposit (1 year)","sourceUrl":"https://data-api.ecb.europa.eu/service/data/MIR/M.EE.B.L22.F.R.A.2250.EUR.N"},"dps":{"available":true,"localName":"Kogumishoius","localNameEn":"Regular savings deposit","note":"Monthly savings deposits are offered by banks; no average rate published."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":"Government savings bond","note":"No retail government savings bond for individuals was found."},"tbill_91d":{"available":false,"localName":"Riigi lühiajalised võlakirjad","localNameEn":"Treasury bills","note":"Only 6- and 12-month T-bills are issued, sold to institutional investors.","sourceUrl":"https://www.fin.ee/en/news/government-issues-eur-373-million-worth-treasury-bills"},"tbond_5y":{"available":false,"localName":"Riigivõlakirjad","localNameEn":"Estonian government bonds","note":"Few government bonds outstanding; no regular 5-year line."},"tbond_10y":{"available":true,"localName":"Riigivõlakirjad","localNameEn":"Estonian government bonds","note":"Limited long-term issuance; yields indicative.","sourceUrl":"https://data-api.ecb.europa.eu/service/data/IRS/M.EE.L.L40.CI.0000.EUR.N.Z"},"equity_fund":{"available":true,"localName":"Investeerimisfondid","localNameEn":"Investment funds / index funds (ETF)","note":"Retail funds widely available; an investment account (investeerimiskonto) defers the 22% tax on gains."},"gold":{"available":true,"localName":"Kuldkangid ja kuldmündid","localNameEn":"Gold bars and coins","note":"No restriction on buying physical gold."}},"institutions":{"centralBank":{"name":"Eesti Pank","url":"https://www.eestipank.ee/en","note":"Part of the Eurosystem; monetary policy set by the European Central Bank."},"insuranceRegulator":{"name":"Finantsinspektsioon (Financial Supervision and Resolution Authority)","url":"https://www.fi.ee/en"},"insuranceComplaints":{"name":"Finantsinspektsioon, making a complaint","url":"https://www.fi.ee/en/consumer/when-should-i-contact-finantsinspektsioon/making-complaint"},"pensionScheme":{"name":"Sotsiaalkindlustusamet (Social Insurance Board), state pension","url":"https://www.sotsiaalkindlustusamet.ee/en/pension-and-benefits/preparing-retirement/estonian-pension-system"},"oldAgeAllowance":{"name":"Rahvapension (national pension)","url":"https://www.sotsiaalkindlustusamet.ee/en/pension-and-benefits/types-pensions/national-pension"},"publicHealthCover":{"name":"Tervisekassa (Estonian Health Insurance Fund)","url":"https://www.tervisekassa.ee/en"},"depositInsurance":{"name":"Tagatisfond (Estonian Guarantee Fund)","url":"https://www.tf.ee/en/protection-depositors/faq"},"statistics":{"name":"Statistikaamet (Statistics Estonia)","url":"https://www.stat.ee/en"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EE', 1, 'bank_deposit_avg_rate', 0.0236, NULL, 'sourced', 'ECB MFI interest rate statistics: Estonian banks, household deposits with agreed maturity (outstanding amounts)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.EE.B.L22.A.R.A.2250.EUR.O', '2026-09-30', 'Average rate on all outstanding household term deposits, September 2026; household overnight deposits paid 0.32%. World Bank FR.INR.DPST has no Estonia figure.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EE', 1, 'credit_card_rate_cap', 0.1801, NULL, 'sourced', 'ECB MFI interest rate statistics: Estonian banks, revolving loans, overdrafts and credit card credit to households', 'https://data-api.ecb.europa.eu/service/data/MIR/M.EE.B.A2Z.A.R.A.2250.EUR.N', '2026-09-30', 'Typical rate, not a cap: average rate on household revolving loans, overdrafts and credit card credit, September 2026 (17.92% in August).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EE', 1, 'deposit_insurance_limit', 100000, NULL, 'sourced', 'Tagatisfond (Estonian Guarantee Fund), depositor protection FAQ', 'https://www.tf.ee/en/protection-depositors/faq', '2026-10-31', 'EUR 100,000 per depositor per credit institution, plus up to a further EUR 100,000 for six months for funds from property sales, redundancy, retirement and similar events.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EE', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Estonian banks sell regular monthly savings deposits (kogumishoius), but no average or official rate for them was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EE', 1, 'equity_return_base', 0.055, NULL, 'assumption', 'OMX Tallinn (Trading Economics); deposits up to 1 year 2.41% less 22% tax = 1.9%', 'https://tradingeconomics.com/estonia/stock-market', '2026-10-31', 'Base capped near the after-tax safe rate plus about 4 points because the Tallinn exchange is small and concentrated, even though its recent record is strong.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EE', 1, 'equity_return_high', 0.075, NULL, 'assumption', 'OMX Tallinn; long-run global equity returns', 'https://tradingeconomics.com/estonia/stock-market', '2026-10-31', 'High case: a diversified euro equity fund matching long-run global equity returns of about 7-8% in euros.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EE', 1, 'equity_return_low', 0.03, NULL, 'assumption', 'OMX Tallinn index about 2,241 on 2 Nov 2026, up 16.5% in a year', 'https://tradingeconomics.com/estonia/stock-market', '2026-10-31', 'Low case: the small Tallinn market returns little more than safe deposits over a long period.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EE', 1, 'fdr_1y_rate', 0.0241, NULL, 'sourced', 'ECB MFI interest rate statistics: Estonian banks, household deposits with agreed maturity up to 1 year (new business)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.EE.B.L22.F.R.A.2250.EUR.N', '2026-09-30', 'Bucket covers all fixed terms up to one year; September 2026 (2.34% in August); 1-2 years paid 3.24% in September.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EE', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'ECB/Eesti Pank MFI statistics publish household deposits with agreed maturity up to 1 year as one bucket (2.41% in September 2026); no separate 3-month term deposit rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EE', 1, 'fixed_income_return_base', 0.018, NULL, 'assumption', 'Household deposits up to 1 year 2.41% (ECB MFI, Sep 2026) less 22% tax = 1.88%', 'https://data-api.ecb.europa.eu/service/data/MIR/M.EE.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Base case: after-tax 1-year term deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EE', 1, 'fixed_income_return_high', 0.024, NULL, 'assumption', 'Household deposits 1-2 years 3.24% (ECB MFI, Sep 2026) less 22% tax = 2.5%', 'https://data-api.ecb.europa.eu/service/data/MIR/M.EE.B.L22.H.R.A.2250.EUR.N', '2026-10-31', 'High case: locking in longer term deposits after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EE', 1, 'fixed_income_return_low', 0.012, NULL, 'assumption', 'Household deposits up to 1 year 2.41% (ECB MFI, Sep 2026), assuming rates fall, less 22% tax', 'https://data-api.ecb.europa.eu/service/data/MIR/M.EE.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Low case: term deposit rates drift down towards 1.5% before the 22% tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EE', 1, 'goal_inflation_education', 0.04, NULL, 'assumption', 'Statistics Estonia IA002 CPI, education services: -8.3% in the year to Sep 2026, about 3.0% a year since Sep 2021', 'https://andmed.stat.ee/en/stat/majandus__hinnad/IA002', '2026-10-31', 'The latest fall reflects fee changes; over the long run education costs are assumed to rise about a point above general inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EE', 1, 'goal_inflation_health', 0.05, NULL, 'assumption', 'Statistics Estonia IA002 CPI, health: +2.6% in the year to Sep 2026, about 7.8% a year since Sep 2021', 'https://andmed.stat.ee/en/stat/majandus__hinnad/IA002', '2026-10-31', 'Health prices have risen faster than headline prices over five years (7.8% vs 7.7% a year incl. the 2022 spike); 5% is used as a long-run planning figure.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EE', 1, 'gold_return_base', 0.04, NULL, 'assumption', 'Gold price history (Trading Economics); ECB 2% inflation target', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Base case: dollar gold rises roughly with world inflation plus a little, and the euro is assumed stable against the dollar over the long run.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EE', 1, 'gold_return_high', 0.07, NULL, 'assumption', 'Gold price history (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'High case: a repeat of gold''s strong 2005-2025 trend in euro terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EE', 1, 'gold_return_low', 0.01, NULL, 'assumption', 'Gold price history (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Low case: gold barely keeps up after the 2025-26 spike, with no help from the euro.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EE', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No per-year gratuity: under the Employment Contracts Act an employer pays one month''s average wage on redundancy, and the Unemployment Insurance Fund adds one or two months for 5-10 or 10+ years of service, which does not fit a days-per-year rule.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EE', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'Hospital care for insured people is covered by the Estonian Health Insurance Fund (Tervisekassa) with small patient fees; no official figure for the out-of-pocket cost of a major private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EE', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Private health insurance is a small, mostly employer-paid market; no published premium table per EUR 100,000 of cover was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EE', 1, 'inflation_cpi', 0.035, NULL, 'sourced', 'Statistics Estonia, IA021 consumer price index change over same month of previous year', 'https://andmed.stat.ee/en/stat/majandus__hinnad/IA021', '2026-09-30', 'CPI up 3.5% year on year in September 2026 (1.5% in August, 4.1% in December 2025); World Bank 2025 average 4.8%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EE', 1, 'inflation_projection', 0.03, NULL, 'assumption', 'ECB 2% medium-term target; Estonian CPI averaged about 7.7% a year in 2021-2026 and 3.5% in Sep 2026', 'https://andmed.stat.ee/en/stat/majandus__hinnad/IA021', '2026-10-31', 'Estonia shares the ECB 2% target but its prices keep converging towards richer euro members, so 3% is used for long-run planning.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EE', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life cover (riskikindlustus / tähtajaline elukindlustus) is sold, but no published premium table per EUR 1,000 of cover was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EE', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Finantsinspektsioon and the Estonian Insurance Association do not publish an industry life claim settlement ratio that could be found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EE', 1, 'life_expectancy', 79.79, NULL, 'sourced', 'Statistics Estonia, RV045 life expectancy by sex and age', 'https://andmed.stat.ee/en/stat/rahvastik__rahvastikunaitajad-ja-koosseis__demograafilised-pehinaitajad/RV045', '2025-12-31', 'Men 75.60, women 83.57 in 2025; World Bank 2024 figure 79.3.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EE', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":23.17,"men":19.83,"women":25.75},{"age":65,"total":19.31,"men":16.33,"women":21.43},{"age":70,"total":15.73,"men":13.3,"women":17.24},{"age":80,"total":9.4,"men":8.11,"women":9.96}]}', 'sourced', 'Statistics Estonia, RV045 life expectancy by sex and age', 'https://andmed.stat.ee/en/stat/rahvastik__rahvastikunaitajad-ja-koosseis__demograafilised-pehinaitajad/RV045', '2025-12-31', NULL, 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EE', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":65,"womenAge":65,"over90Monthly":null,"meansTested":false}', 'sourced', 'Sotsiaalkindlustusamet, national pension conditions', 'https://www.sotsiaalkindlustusamet.ee/en/pension-and-benefits/types-pensions/national-pension', '2026-10-31', 'Paid from pension age (65 in 2026, then linked to life expectancy) to people who lack the 15 years of pensionable service, have lived in Estonia for at least 5 years immediately before applying, and get no pension from another country; not income-tested.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EE', 1, 'old_age_allowance_monthly', 414.1, NULL, 'sourced', 'Sotsiaalkindlustusamet (Social Insurance Board), national pension (rahvapension)', 'https://www.sotsiaalkindlustusamet.ee/en/pension-and-benefits/types-pensions/national-pension', '2026-04-01', 'National pension EUR 414.10 a month as shown by the Social Insurance Board (rates are indexed each 1 April); paid only to people without the 15 years of service needed for an old-age pension.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EE', 1, 'oop_health_share', 0.2138, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=EE', '2024-12-31', 'Latest World Bank figure is for 2024 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EE', 1, 'policy_rate', 0.025, NULL, 'sourced', 'European Central Bank, key ECB interest rates (deposit facility)', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.en.html', '2026-09-16', 'Estonia uses the euro; ECB deposit facility rate 2.50% since 16 September 2026 (2.25% from 17 June 2026, 2.00% before), per the ECB FM dataset.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EE', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":65,"nomineeUntilAge":null,"inflationLinked":true,"taxFree":false}', 'sourced', 'Sotsiaalkindlustusamet (retirement age; pension indexation)', 'https://www.sotsiaalkindlustusamet.ee/en/pension-and-benefits/pension-amount/pension-indexation', '2026-10-31', 'State pension insurance (first pillar) funded from social tax; pensions are indexed every 1 April by 80% social-tax growth and 20% CPI growth and never cut. Pensions are taxed as income above the basic exemption at retirement age (EUR 776 a month). The funded second pillar is voluntary since 2021.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EE', 1, 'retirement_accumulation_return_base', 0.035, NULL, 'assumption', 'After-tax 1-year deposit 1.9%; equity base 5.5%', 'https://data-api.ecb.europa.eu/service/data/MIR/M.EE.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Base case: roughly half shares at 5.5% and half safe fixed income at about 1.8-2.4% after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EE', 1, 'retirement_accumulation_return_high', 0.05, NULL, 'assumption', 'After-tax 1-2 year deposit 2.5%; equity high 7.5%', 'https://data-api.ecb.europa.eu/service/data/MIR/M.EE.B.L22.H.R.A.2250.EUR.N', '2026-10-31', 'High case for a growth-leaning balanced mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EE', 1, 'retirement_accumulation_return_low', 0.025, NULL, 'assumption', 'After-tax 1-year deposit 1.9%; OMX Tallinn record', 'https://data-api.ecb.europa.eu/service/data/MIR/M.EE.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Low case for a balanced mix if shares lag.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EE', 1, 'retirement_age_default', 65, NULL, 'sourced', 'Sotsiaalkindlustusamet (Social Insurance Board), retirement age', 'https://www.sotsiaalkindlustusamet.ee/en/pension-and-benefits/applying-pension/retirement-age', '2026-10-31', 'Pension age reached 65 in 2026 (people born in 1961), same for men and women. From 2027 it is 65 plus an adjustment for life expectancy at 65 (at most 3 months a year, set two years ahead): 65y1m in 2027, 65y3m in 2028, 65y4m in 2029. People born after 1975 will reach pension age after 2040, so their age will be at least 65 and likely higher, but no official figure for those cohorts exists; 65 is the statutory base. Old-age pension needs 15 years of qualifying service.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EE', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'Estonian civil servants draw the general state pension; no separate statutory retirement age for government employees could be confirmed from a readable official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EE', 1, 'retirement_return_base', 0.018, NULL, 'assumption', 'Household deposits up to 1 year 2.41% (ECB MFI, Sep 2026) less 22% tax = 1.88%', 'https://data-api.ecb.europa.eu/service/data/MIR/M.EE.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Base case capped at the after-tax 1-year term deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EE', 1, 'retirement_return_high', 0.024, NULL, 'assumption', 'Household deposits 1-2 years 3.24% (ECB MFI, Sep 2026) less 22% tax = 2.5%', 'https://data-api.ecb.europa.eu/service/data/MIR/M.EE.B.L22.H.R.A.2250.EUR.N', '2026-10-31', 'High case: a ladder of longer term deposits after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EE', 1, 'retirement_return_low', 0.012, NULL, 'assumption', 'Household deposits up to 1 year 2.41% (ECB MFI, Sep 2026), assuming rates fall, less 22% tax', 'https://data-api.ecb.europa.eu/service/data/MIR/M.EE.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Low case: term deposit rates drift lower.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EE', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No retail government savings bond sold to individuals was found on the Ministry of Finance site; Estonian T-bills and bonds are sold to institutional investors.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EE', 1, 'savings_account_rate', 0.0032, NULL, 'sourced', 'ECB MFI interest rate statistics: Estonian banks, overnight deposits from households (new business)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.EE.B.L21.A.R.A.2250.EUR.N', '2026-09-30', 'Average rate on household overnight deposits in Estonia, September 2026 (0.32% in August).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EE', 1, 'support_ratio', NULL, '{"points":[{"year":2026,"value":3},{"year":2040,"value":2.53},{"year":2065,"value":1.86}]}', 'sourced', 'Statistics Estonia, RV083 population projection to 2085 (baseline scenario)', 'https://andmed.stat.ee/en/stat/rahvastik__rahvastikunaitajad-ja-koosseis__rahvaarv-ja-rahvastiku-koosseis/RV083', '2026-01-01', 'People aged 15-64 divided by people 65+ in the official baseline projection (based on 1 January 2024 population); World Bank 2025 old-age dependency 34.6 gives 2.9.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EE', 1, 'tax_bank_interest', 0.22, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Estonia taxes on personal income', 'https://taxsummaries.pwc.com/estonia/individual/taxes-on-personal-income', '2026-05-29', 'Flat 22% personal income tax on all income of residents in 2026, including interest; resident individuals declare interest in the annual return (no final withholding), or can defer tax through an investment account.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EE', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No retail government savings certificate exists; interest on government bonds is ordinary income taxed at the flat 22%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EE', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Estonia issues 6- and 12-month T-bills only (22 Sep 2026 auction: 6-month 2.910%, 12-month 3.209%, institutional investors only); no 3-month bill. Source: https://www.fin.ee/en/news/government-issues-eur-373-million-worth-treasury-bills', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EE', 1, 'tbond_10y_rate', 0.0409, NULL, 'sourced', 'ECB long-term interest rate for convergence purposes, Estonia', 'https://data-api.ecb.europa.eu/service/data/IRS/M.EE.L.L40.CI.0000.EUR.N.Z', '2026-09-30', 'Monthly average for September 2026 (3.83% in August); Estonia has little long-term debt, so the ECB convergence indicator is based on a basket of long-term loans and is only indicative.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EE', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 5-year Estonian government bond yield was found; Estonia has few bonds outstanding and the Ministry of Finance investor pages showed no yields.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('EG', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"EG","iso3":"EGY","nameEn":"Egypt","nameNative":"مصر","region":"middle_east_north_africa","languages":["ar","arz","en"],"currency":{"code":"EGP","symbol":"E£","decimals":2,"compact":"intl","usdRate":{"value":56,"status":"sourced","sourceName":"Trading Economics, USD/EGP exchange rate","sourceUrl":"https://tradingeconomics.com/egypt/currency","asOf":"2026-10-30","note":"56.00 Egyptian pounds per US dollar on 30 October 2026 as read by the researcher; on re-check the same page showed 55.46 on 3 November 2026 (previous session 55.35), so the figure is within about 1% of the latest. Secondary source because the Central Bank of Egypt exchange-rate page rejected requests. World Bank 2025 average 49.23."}},"instruments":{"savings_account":{"available":true,"localName":"حساب توفير","localNameEn":"Savings account"},"fdr_3m":{"available":true,"localName":"وديعة لأجل (3 أشهر)","localNameEn":"Time deposit (3 months)"},"fdr_1y":{"available":true,"localName":"وديعة لأجل (سنة)","localNameEn":"Time deposit (1 year)","note":"Banks also sell fixed-rate savings certificates (شهادات ادخار), usually for 1 to 3 years; bank interest is tax-free for residents."},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No standard monthly recurring deposit product was confirmed."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate for individuals was confirmed; savings certificates are bank products."},"tbill_91d":{"available":true,"localName":"أذون الخزانة","localNameEn":"Treasury bills","note":"Individuals can buy through banks; interest bears 20% withholding tax.","sourceUrl":"https://taxsummaries.pwc.com/egypt/individual/income-determination"},"tbond_5y":{"available":true,"localName":"سندات الخزانة","localNameEn":"Treasury bonds","note":"Interest bears 20% withholding tax.","sourceUrl":"https://taxsummaries.pwc.com/egypt/individual/income-determination"},"tbond_10y":{"available":true,"localName":"سندات الخزانة (10 سنوات)","localNameEn":"Treasury bonds (10 years)","note":"Interest bears 20% withholding tax.","sourceUrl":"https://taxsummaries.pwc.com/egypt/individual/income-determination"},"equity_fund":{"available":true,"localName":"صناديق الاستثمار","localNameEn":"Mutual funds","note":"Equity and index funds investing on the Egyptian Exchange are supervised by the Financial Regulatory Authority.","sourceUrl":"https://fra.gov.eg/"},"gold":{"available":true,"localName":"الذهب","localNameEn":"Gold","note":"Gold bars, coins and jewellery are widely sold."}},"institutions":{"centralBank":{"name":"Central Bank of Egypt","url":"https://www.cbe.org.eg/en"},"insuranceRegulator":{"name":"Financial Regulatory Authority (FRA)","url":"https://fra.gov.eg/"},"insuranceComplaints":{"name":"Financial Regulatory Authority complaints","url":"https://fra.gov.eg/"},"pensionScheme":{"name":"National Organization for Social Insurance (NOSI)","url":"https://www.nosi.gov.eg/"},"oldAgeAllowance":{"name":"Takaful and Karama programme, Ministry of Social Solidarity","url":"https://www.moss.gov.eg/"},"publicHealthCover":{"name":"Universal Health Insurance Authority (rolling out by governorate)","url":"https://uhia.gov.eg/"},"depositInsurance":null,"statistics":{"name":"Central Agency for Public Mobilization and Statistics (CAPMAS)","url":"https://www.capmas.gov.eg/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EG', 1, 'bank_deposit_avg_rate', 0.148, NULL, 'sourced', 'IMF International Financial Statistics deposit rate, Egypt, via Trading Economics', 'https://tradingeconomics.com/egypt/deposit-interest-rate', '2026-09-30', '14.80% in September 2026 (14.50% in August), IMF series as shown by Trading Economics. World Bank FR.INR.DPST gives 19.16% for 2024.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EG', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap or published typical credit card rate was found; the lending rate was 21% (October 2026) for reference.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EG', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No operating deposit insurance scheme or cover amount could be confirmed from the Central Bank of Egypt, whose site rejected requests.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EG', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No industry-wide rate for monthly recurring savings plans was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EG', 1, 'equity_return_base', 0.17, NULL, 'assumption', 'After-tax average deposit rate 14.8% (September 2026; bank interest untaxed); EGX30 long-run record', 'https://tradingeconomics.com/egypt/stock-market', '2026-10-31', 'Base case: about 2 points over the untaxed deposit rate, within the 4-point cap, since much of the EGX30''s 10-year rise reflects pound devaluation rather than real growth.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EG', 1, 'equity_return_high', 0.22, NULL, 'assumption', 'EGX30 index record; deposit rate 14.8%', 'https://tradingeconomics.com/egypt/stock-market', '2026-10-31', 'High case: equities beat deposits by about 7 points a year, as in periods of devaluation-driven nominal gains.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EG', 1, 'equity_return_low', 0.1, NULL, 'assumption', 'EGX30 index about 49,600 points in October 2026 (Trading Economics); after-tax deposit rate about 14.8%', 'https://tradingeconomics.com/egypt/stock-market', '2026-10-31', 'Low case: equities lag the after-tax deposit rate, as can happen when currency-driven rallies reverse.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EG', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published industry-wide 1-year time deposit or bank certificate rate could be read; the Central Bank of Egypt site rejected requests.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EG', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published industry-wide 3-month time deposit rate could be read; the Central Bank of Egypt site rejected requests.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EG', 1, 'fixed_income_return_base', 0.14, NULL, 'assumption', 'IMF deposit rate 14.8% (September 2026); bank interest untaxed (PwC)', 'https://tradingeconomics.com/egypt/deposit-interest-rate', '2026-10-31', 'Base case: about the average deposit rate, which is tax-free for residents, rounded down.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EG', 1, 'fixed_income_return_high', 0.17, NULL, 'assumption', 'Policy rate 20%; treasury bills taxed at 20% (PwC)', 'https://tradingeconomics.com/egypt/interest-rate', '2026-10-31', 'High case: longer bank certificates or treasury bills at around 21% before the 20% withholding tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EG', 1, 'fixed_income_return_low', 0.1, NULL, 'assumption', 'IMF deposit rate 14.8% (September 2026); policy rate 20%', 'https://tradingeconomics.com/egypt/deposit-interest-rate', '2026-10-31', 'Low case: rates fall as inflation eases toward the central bank target, and savings balances earn less than the average.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EG', 1, 'goal_inflation_education', 0.12, NULL, 'assumption', 'Urban core inflation 14.1% (September 2026); inflation assumption 10%', 'https://tradingeconomics.com/egypt/inflation-cpi', '2026-10-31', 'Private school and university fees have risen faster than general prices, so education goals are planned 2 points above the general assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EG', 1, 'goal_inflation_health', 0.12, NULL, 'assumption', 'Urban core inflation 14.1% (September 2026); inflation assumption 10%', 'https://tradingeconomics.com/egypt/inflation-cpi', '2026-10-31', 'Private medical costs follow imported drugs and equipment priced in dollars, so health goals are planned 2 points above the general assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EG', 1, 'gold_return_base', 0.11, NULL, 'assumption', 'USD/EGP 56.00 (October 2026); inflation assumption 10%; long-run dollar gold trend about 4%', 'https://tradingeconomics.com/egypt/currency', '2026-10-31', 'Base case: about 4% dollar gold trend plus about 7% a year of pound depreciation, the gap between the 10% inflation assumption and US inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EG', 1, 'gold_return_high', 0.18, NULL, 'assumption', 'USD/EGP history (World Bank PA.NUS.FCRF); dollar gold trend', 'https://tradingeconomics.com/egypt/currency', '2026-10-31', 'High case: strong dollar gold and a renewed sharp devaluation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EG', 1, 'gold_return_low', 0.05, NULL, 'assumption', 'USD/EGP 56.00 (October 2026) against a 2025 average of 49.2 (World Bank)', 'https://tradingeconomics.com/egypt/currency', '2026-10-31', 'Low case: flat dollar gold with slow pound depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EG', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No statutory end-of-service gratuity for private employees was confirmed; the Labour Law could not be checked.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EG', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a major private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EG', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premiums by age were found from the regulator or another public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EG', 1, 'inflation_cpi', 0.139, NULL, 'sourced', 'CAPMAS annual urban headline inflation, September 2026, via Trading Economics', 'https://tradingeconomics.com/egypt/inflation-cpi', '2026-09-30', '13.9% in September 2026, down from 14.5% in August; core inflation 14.1%, food 7.2%. Secondary source because the CAPMAS and Central Bank of Egypt sites rejected requests. World Bank 2025 average 14.1%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EG', 1, 'inflation_projection', 0.1, NULL, 'assumption', 'Central Bank of Egypt inflation target (7% plus or minus 2 points for Q4 2026); urban inflation 13.9% in September 2026', 'https://tradingeconomics.com/egypt/inflation-cpi', '2026-10-31', 'Inflation has run well above the central bank''s single-digit targets for years (World Bank 2025 average 14.1%), so a rounded 10% sits between the target and the recent record.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EG', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life is sold, but no published premium rates per EGP 1,000 of cover by age were found from the regulator or another public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EG', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No industry-wide life claim settlement ratio could be read from the Financial Regulatory Authority.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EG', 1, 'life_expectancy', 71.806, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN), Egypt', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=EG', '2024-12-31', '71.8 years in 2024 (men 69.7, women 74.0), the latest World Bank year, older than 2025; UN WPP 2024 gives 72.2 for 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EG', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":17,"men":15.6,"women":18.3},{"age":65,"total":13.5,"men":12.4,"women":14.5},{"age":70,"total":10.3,"men":9.5,"women":11.1},{"age":80,"total":5.5,"men":5.2,"women":5.8}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/egypt/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EG', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'Karama, the means-tested cash transfer of the Takaful and Karama programme (Ministry of Social Solidarity), is described as covering poor people aged 65 and over, but the only page found was Arabic Wikipedia text from 2022-2023, not an official or accepted secondary source, and the rules may have changed since; the ministry site gave no eligibility page.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EG', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'Karama, the means-tested cash transfer of the Takaful and Karama programme, covers poor people aged 65 and over, but its current monthly amount for an elderly person could not be read from the Ministry of Social Solidarity.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EG', 1, 'oop_health_share', 0.572, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), Egypt', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=EG', '2023-12-31', '57.2% in 2023 (WHO Global Health Expenditure Database via the World Bank); older than 2025, the latest available.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EG', 1, 'policy_rate', 0.2, NULL, 'sourced', 'Central Bank of Egypt overnight deposit rate, MPC meeting of 29 October 2026, via Trading Economics', 'https://tradingeconomics.com/egypt/interest-rate', '2026-10-29', 'The MPC raised the overnight deposit rate by 100 basis points to 20.00% (overnight lending rate 21.00%) on 29 October 2026. Secondary source because the Central Bank of Egypt site rejected requests.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EG', 1, 'public_pension_scheme', NULL, NULL, 'missing', '', '', '2026-10-31', 'The National Organization for Social Insurance runs the compulsory pension under Law No. 148 of 2019 (employee 11%, employer 18.75% of insured pay per PwC), but its pension age schedule and indexation rule could not be read from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EG', 1, 'retirement_accumulation_return_base', 0.15, NULL, 'assumption', 'Deposit rate 14.8%; equity base 17%; gold base 11%', 'https://tradingeconomics.com/egypt/deposit-interest-rate', '2026-10-31', 'Base case: a balanced mix of deposits, equities and gold.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EG', 1, 'retirement_accumulation_return_high', 0.2, NULL, 'assumption', 'Equity high 22%; gold high 18%', 'https://tradingeconomics.com/egypt/deposit-interest-rate', '2026-10-31', 'High case: a growth-leaning mix in a high-inflation, devaluing currency.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EG', 1, 'retirement_accumulation_return_low', 0.1, NULL, 'assumption', 'Deposit rate 14.8%; equity low 10%', 'https://tradingeconomics.com/egypt/deposit-interest-rate', '2026-10-31', 'Low case: a balanced mix earning below today''s deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EG', 1, 'retirement_age_default', NULL, NULL, 'missing', '', '', '2026-10-31', 'Social Insurance and Pensions Law No. 148 of 2019 sets the pension age at 60 with a gradual increase toward 65, but the schedule that applies to people born after 1975 could not be read from an official source (the National Organization for Social Insurance and SSA pages refused requests).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EG', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'The retirement age for civil servants (60 under current practice, covered by Law No. 148 of 2019 with its gradual increase) could not be read from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EG', 1, 'retirement_return_base', 0.13, NULL, 'assumption', 'IMF deposit rate 14.8% (September 2026); bank interest untaxed (PwC)', 'https://tradingeconomics.com/egypt/deposit-interest-rate', '2026-10-31', 'Base case: a little below the untaxed average deposit rate, so not above the after-tax safe rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EG', 1, 'retirement_return_high', 0.16, NULL, 'assumption', 'Policy rate 20%; treasury bills taxed at 20% (PwC)', 'https://tradingeconomics.com/egypt/interest-rate', '2026-10-31', 'High case: long bank certificates and treasury bills near current high rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EG', 1, 'retirement_return_low', 0.09, NULL, 'assumption', 'IMF deposit rate 14.8% (September 2026)', 'https://tradingeconomics.com/egypt/deposit-interest-rate', '2026-10-31', 'Low case: deposit rates fall as inflation eases.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EG', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate sold to individuals was confirmed; the widely held savings certificates are issued by banks, not the government.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EG', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No industry-wide savings account rate could be read; the Central Bank of Egypt statistical bulletin site rejected requests and web search was unavailable for this research.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EG', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":12},{"year":2040,"value":8.7},{"year":2065,"value":5}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/egypt/2040/', '2025-12-31', '100 / old-age dependency ratio: 8.34 (2025, World Bank), 11.5 (2040) and 19.9 (2065, populationpyramid.net/egypt/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EG', 1, 'tax_bank_interest', 0, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Egypt, individual income determination (last reviewed 17 August 2026)', 'https://taxsummaries.pwc.com/egypt/individual/income-determination', '2026-08-17', 'Interest income from local banks is not taxable for residents; interest on treasury bills and bonds bears 20% withholding tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EG', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'There is no government savings certificate for individuals to tax; for reference, interest on treasury bills and bonds bears 20% withholding tax (PwC Worldwide Tax Summaries, Egypt).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EG', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No current 91-day treasury bill auction yield could be read; the Ministry of Finance and Central Bank of Egypt auction pages rejected requests and Trading Economics did not show the figure.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EG', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No current 10-year treasury bond yield could be read from an official or secondary source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('EG', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No current 5-year treasury bond yield could be read from an official or secondary source.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('ER', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"ER","iso3":"ERI","nameEn":"Eritrea","nameNative":"ኤርትራ","region":"sub_saharan_africa","languages":["ti","en","tig","ar"],"currency":{"code":"ERN","symbol":"Nfk","decimals":2,"compact":"intl","usdRate":{"value":15.075,"status":"sourced","sourceName":"World Bank WDI, official exchange rate (PA.NUS.FCRF), Eritrea","sourceUrl":"https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=ER","asOf":"2025-12-31","note":"2025 average; the nakfa has been held at about 15 per US dollar for many years. The Bank of Eritrea website was not reachable for a 2026 rate."}},"instruments":{"savings_account":{"available":true,"localName":null,"localNameEn":"Savings account","note":"Banks take savings deposits; rates are not published."},"fdr_3m":{"available":true,"localName":null,"localNameEn":"Time deposit (3 months)","note":"Banks take time deposits, but rates are not published."},"fdr_1y":{"available":true,"localName":null,"localNameEn":"Time deposit (1 year)","note":"Banks take time deposits, but rates are not published."},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No standard monthly recurring deposit product was found."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate for individuals was found."},"tbill_91d":{"available":false,"localName":null,"localNameEn":null,"note":"No treasury bill auctions open to individuals were found."},"tbond_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government bond market was found."},"tbond_10y":{"available":false,"localName":null,"localNameEn":null,"note":"No government bond market was found."},"equity_fund":{"available":false,"localName":null,"localNameEn":null,"note":"There is no stock exchange and no locally sold equity fund."},"gold":{"available":true,"localName":null,"localNameEn":"Gold","note":"Gold is bought mainly as jewellery; no official bullion or coin scheme was found."}},"institutions":{},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ER', 1, 'bank_deposit_avg_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No weighted average deposit rate was found; the World Bank deposit rate series (FR.INR.DPST) has no Eritrea data and the Bank of Eritrea and National Statistics Office websites were not reachable.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ER', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No credit card rate or legal cap was found; card lending is very limited.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ER', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No deposit insurance scheme or cover limit was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ER', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No standard monthly recurring deposit product or rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ER', 1, 'equity_return_base', 0.065, NULL, 'assumption', 'No stock exchange in Eritrea; global equities in US dollar terms (nakfa fixed at about 15 per dollar, World Bank PA.NUS.FCRF)', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=ER', '2026-10-31', 'No local stock market exists, so equity means a global index in dollar (nakfa) terms, kept about 3.5 points above an assumed after-tax safe saving rate of about 3%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ER', 1, 'equity_return_high', 0.1, NULL, 'assumption', 'No stock exchange in Eritrea; global equities in US dollar terms (nakfa fixed at about 15 per dollar, World Bank PA.NUS.FCRF)', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=ER', '2026-10-31', 'High case: global equities repeat their long-run dollar record.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ER', 1, 'equity_return_low', 0.02, NULL, 'assumption', 'No stock exchange in Eritrea; global equities in US dollar terms (nakfa fixed at about 15 per dollar, World Bank PA.NUS.FCRF)', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=ER', '2026-10-31', 'Low case: a weak decade for global equities in dollar terms; foreign investing is also restricted by currency controls.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ER', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published 1-year time deposit rate was found; the World Bank deposit rate series (FR.INR.DPST) has no Eritrea data and the Bank of Eritrea and National Statistics Office websites were not reachable.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ER', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published 3-month time deposit rate was found; the World Bank deposit rate series (FR.INR.DPST) has no Eritrea data and the Bank of Eritrea and National Statistics Office websites were not reachable.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ER', 1, 'fixed_income_return_base', 0.03, NULL, 'assumption', 'No published deposit or government security rates for Eritrea (World Bank FR.INR.DPST has no data); assumption', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=ER', '2026-10-31', 'Base case: bank savings and time deposits at modest administered rates; no rates are published, so a cautious 3% is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ER', 1, 'fixed_income_return_high', 0.045, NULL, 'assumption', 'No published deposit or government security rates for Eritrea (World Bank FR.INR.DPST has no data); assumption', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=ER', '2026-10-31', 'High case: longer time deposits at somewhat higher rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ER', 1, 'fixed_income_return_low', 0.02, NULL, 'assumption', 'No published deposit or government security rates for Eritrea (World Bank FR.INR.DPST has no data); assumption', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=ER', '2026-10-31', 'Low case: ordinary bank savings at low administered rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ER', 1, 'goal_inflation_education', 0.06, NULL, 'assumption', 'Planning inflation of 5% (no published Eritrea CPI after 2019, IMF WEO)', 'https://www.imf.org/external/datamapper/api/v1/PCPIPCH/ERI', '2026-10-31', 'No education price series is published; education goals use 1 point above the 5% planning inflation, mainly for study abroad and private fees.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ER', 1, 'goal_inflation_health', 0.06, NULL, 'assumption', 'Planning inflation of 5% (no published Eritrea CPI after 2019, IMF WEO)', 'https://www.imf.org/external/datamapper/api/v1/PCPIPCH/ERI', '2026-10-31', 'No health price series is published; health goals use 1 point above the 5% planning inflation for imported medicines and private care.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ER', 1, 'gold_return_base', 0.04, NULL, 'assumption', 'Nakfa fixed at about 15 per US dollar (World Bank PA.NUS.FCRF); dollar gold trend', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=ER', '2026-10-31', 'Base case: the long-run dollar gold trend of about 4% a year, with no assumed devaluation of the fixed nakfa.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ER', 1, 'gold_return_high', 0.08, NULL, 'assumption', 'Nakfa fixed at about 15 per US dollar (World Bank PA.NUS.FCRF); dollar gold trend', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=ER', '2026-10-31', 'High case: strong gold years or a devaluation of the nakfa.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ER', 1, 'gold_return_low', 0, NULL, 'assumption', 'Nakfa fixed at about 15 per US dollar (World Bank PA.NUS.FCRF); dollar gold trend', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=ER', '2026-10-31', 'Low case: flat dollar gold prices under the fixed nakfa rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ER', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Labour Proclamation''s severance or end-of-service provisions could not be read from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ER', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a major hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ER', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premiums were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ER', 1, 'inflation_cpi', NULL, NULL, 'missing', '', '', '2026-10-31', 'No current consumer price inflation figure was found: the IMF World Economic Outlook series for Eritrea ends in 2019 (1.3%; imf.org datamapper API, read 2026-11), the World Bank has none, and the Bank of Eritrea and National Statistics Office websites were not reachable.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ER', 1, 'inflation_projection', 0.05, NULL, 'assumption', 'IMF World Economic Outlook (Eritrea CPI series ends in 2019 at 1.3%); nakfa fixed at about 15 per US dollar (World Bank PA.NUS.FCRF)', 'https://www.imf.org/external/datamapper/api/v1/PCPIPCH/ERI', '2026-10-31', 'With no published CPI since 2019 and a nakfa held at 15 per dollar under tight import and currency controls, a cautious 5% (above dollar inflation, near the regional norm) is used for planning.', 0);
