INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('ES', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"ES","iso3":"ESP","nameEn":"Spain","nameNative":"España","region":"europe_central_asia","languages":["es","en","ca","gl","eu"],"currency":{"code":"EUR","symbol":"€","decimals":2,"compact":"intl","usdRate":{"value":0.8951,"status":"sourced","sourceName":"European Central Bank euro reference rate (USD)","sourceUrl":"https://data-api.ecb.europa.eu/service/data/EXR/D.USD.EUR.SP00.A","asOf":"2026-10-30","note":"EUR 1 = USD 1.1172 on 30 October 2026, so about EUR 0.895 per US dollar; World Bank 2025 average 0.885."}},"instruments":{"savings_account":{"available":true,"localName":"Cuenta de ahorro","localNameEn":"Savings account","sourceUrl":"https://data-api.ecb.europa.eu/service/data/MIR/M.ES.B.L21.A.R.A.2250.EUR.N"},"fdr_3m":{"available":true,"localName":"Depósito a plazo fijo","localNameEn":"Fixed-term deposit (3 months)"},"fdr_1y":{"available":true,"localName":"Depósito a plazo fijo","localNameEn":"Fixed-term deposit (1 year)","sourceUrl":"https://data-api.ecb.europa.eu/service/data/MIR/M.ES.B.L22.F.R.A.2250.EUR.N"},"dps":{"available":true,"localName":"Cuenta individual de ahorro a largo plazo (CIALP)","localNameEn":"Long-term savings account","note":"No standard monthly recurring deposit; long-term savings accounts accept regular contributions."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":"Government savings bond for individuals","note":"No retail-only savings bond; individuals can buy ordinary Letras, Bonos and Obligaciones directly from the Treasury (Tesoro Público)."},"tbill_91d":{"available":true,"localName":"Letras del Tesoro","localNameEn":"Treasury bills","note":"Sold at regular auctions; individuals can bid directly through the Treasury or through a bank.","sourceUrl":"https://www.tesoro.es/deuda-publica/subastas/resultado-ultimas-subastas/letras-del-tesoro"},"tbond_5y":{"available":true,"localName":"Bonos del Estado","localNameEn":"Government bonds (2-5 years)","sourceUrl":"https://www.tesoro.es/deuda-publica/subastas/resultado-ultimas-subastas/bonos-del-estado"},"tbond_10y":{"available":true,"localName":"Obligaciones del Estado","localNameEn":"Government bonds (over 5 years)","sourceUrl":"https://www.tesoro.es/deuda-publica/subastas/resultado-ultimas-subastas/obligaciones-del-estado"},"equity_fund":{"available":true,"localName":"Fondo de inversión","localNameEn":"Mutual fund / index fund (ETF)"},"gold":{"available":true,"localName":"Oro de inversión","localNameEn":"Investment gold bars and coins","note":"No restriction on buying physical gold; investment gold is VAT-exempt in the EU."}},"institutions":{"centralBank":{"name":"Banco de España","url":"https://www.bde.es/","note":"Part of the Eurosystem; monetary policy set by the European Central Bank."},"insuranceRegulator":{"name":"Dirección General de Seguros y Fondos de Pensiones (DGSFP)","url":"https://dgsfp.mineco.gob.es/"},"insuranceComplaints":{"name":"DGSFP, Servicio de Reclamaciones","url":"https://dgsfp.mineco.gob.es/es/Consumidor/Reclamaciones/Paginas/InformacionProcedimiento.aspx","note":"Complain to the insurer''s customer service or ombudsman first, then to the DGSFP."},"pensionScheme":{"name":"Seguridad Social (Instituto Nacional de la Seguridad Social)","url":"https://www.seg-social.es/"},"oldAgeAllowance":{"name":"Pensión no contributiva de jubilación (Seguridad Social, revaluation 2026)","url":"https://www.seg-social.es/wps/portal/wss/internet/Pensionistas/Revalorizacion/30431","note":"Managed and paid by the Autonomous Communities; means-tested."},"publicHealthCover":{"name":"Sistema Nacional de Salud (Ministerio de Sanidad)","url":"https://www.sanidad.gob.es/","note":"Universal public health system run by the Autonomous Communities."},"depositInsurance":{"name":"Fondo de Garantía de Depósitos de Entidades de Crédito (FGD)","url":"https://www.fgd.es/"},"statistics":{"name":"Instituto Nacional de Estadística (INE)","url":"https://www.ine.es/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ES', 1, 'bank_deposit_avg_rate', 0.017, NULL, 'sourced', 'ECB MFI interest rate statistics: Spanish banks, household deposits with agreed maturity (outstanding amounts)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.ES.B.L22.A.R.A.2250.EUR.O', '2026-09-30', 'Average rate on all outstanding household term deposits in September 2026; overnight deposits pay 0.16%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ES', 1, 'credit_card_rate_cap', 0.1827, NULL, 'sourced', 'ECB MFI interest rate statistics: Spanish banks, extended credit card credit to households (new business)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.ES.B.A2Z3.A.R.A.2250.EUR.N', '2026-09-30', 'Average 18.27% on extended credit card credit in September 2026; Spain has no fixed legal cap (courts apply the usury law case by case).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ES', 1, 'deposit_insurance_limit', 100000, NULL, 'sourced', 'Fondo de Garantía de Depósitos de Entidades de Crédito (FGD), frequently asked questions', 'https://www.fgd.es/preguntas-frecuentes/', '2026-10-31', 'EUR 100,000 per depositor per institution; some deposits linked to property sales and life events are covered in full for a limited time.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ES', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Spanish banks have no standard monthly recurring deposit; long-term savings accounts (CIALP) accept regular payments, but no official average rate for them was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ES', 1, 'equity_return_base', 0.06, NULL, 'assumption', 'IBEX 35 (Trading Economics); 12-month Letras 3.0% less 19% tax = 2.4%', 'https://tradingeconomics.com/spain/stock-market', '2026-10-31', 'Base case: about 3.5 points over the after-tax safe rate, within the 4-point limit, for a diversified equity fund in euros.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ES', 1, 'equity_return_high', 0.08, NULL, 'assumption', 'IBEX 35 (Trading Economics); long-run global equity returns', 'https://tradingeconomics.com/spain/stock-market', '2026-10-31', 'High case: a diversified equity fund repeating long-run global equity returns in euro terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ES', 1, 'equity_return_low', 0.03, NULL, 'assumption', 'IBEX 35 18,653 on 30 Oct 2026, up 16% in a year (Trading Economics)', 'https://tradingeconomics.com/spain/stock-market', '2026-10-31', 'Low case: Spanish shares only slightly beat after-tax Treasury bills over a long spell.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ES', 1, 'fdr_1y_rate', 0.0229, NULL, 'sourced', 'ECB MFI interest rate statistics: Spanish banks, household deposits with agreed maturity up to 1 year (new business)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.ES.B.L22.F.R.A.2250.EUR.N', '2026-09-30', 'Bucket covers all fixed terms up to one year (2.01% in August, 2.29% in September 2026); deposits of 1-2 years paid 1.91% in September 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ES', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'ECB/Banco de España MFI statistics publish household deposits with agreed maturity up to 1 year as one bucket (2.29% in September 2026); no separate 3-month rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ES', 1, 'fixed_income_return_base', 0.022, NULL, 'assumption', '3-month Letras 2.635% and 12-month Letras 3.0% less 19% tax = 2.1-2.4% (Tesoro Público)', 'https://www.tesoro.es/deuda-publica/subastas/resultado-ultimas-subastas/letras-del-tesoro', '2026-10-31', 'Base case: rolling Treasury bills and term deposits after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ES', 1, 'fixed_income_return_high', 0.033, NULL, 'assumption', '10-year Obligaciones 4.18% less 19% tax = 3.4% (Tesoro Público)', 'https://www.tesoro.es/deuda-publica/subastas/resultado-ultimas-subastas/obligaciones-del-estado', '2026-10-31', 'High case: holding long government bonds after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ES', 1, 'fixed_income_return_low', 0.016, NULL, 'assumption', 'Household deposits up to 1 year 2.29% less 19% tax = 1.9% (ECB MFI statistics, September 2026)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.ES.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Low case: bank term deposits after tax if ECB rates fall.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ES', 1, 'goal_inflation_education', 0.03, NULL, 'assumption', 'Eurostat/ECB HICP Spain, education: 2.6% year on year in December 2025', 'https://data-api.ecb.europa.eu/service/data/ICP/M.ES.N.100000.4.ANR', '2026-10-31', 'Public education is free; paid education rose 2.6% in 2025, so 3% is used for planning.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ES', 1, 'goal_inflation_health', 0.03, NULL, 'assumption', 'Eurostat/ECB HICP Spain, health: 2.2% year on year in December 2025', 'https://data-api.ecb.europa.eu/service/data/ICP/M.ES.N.060000.4.ANR', '2026-10-31', 'Health prices have risen close to headline inflation; 3% (a little above the planning rate) is used for private medical costs.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ES', 1, 'gold_return_base', 0.04, NULL, 'assumption', 'Gold price history (Trading Economics); ECB 2% inflation target', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Base case: dollar gold rises a little faster than world inflation and the euro is assumed stable against the dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ES', 1, 'gold_return_high', 0.07, NULL, 'assumption', 'Gold price history (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'High case: a repeat of gold''s strong 2005-2025 trend in euro terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ES', 1, 'gold_return_low', 0.01, NULL, 'assumption', 'Gold USD 3,876/oz on 30 Oct 2026, 31% below the January 2026 high (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Low case: gold barely keeps its value after the 2025-26 spike while the euro holds steady against the dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ES', 1, 'gratuity_rule', NULL, '{"daysPerYear":20,"daysPerYearAfter":null,"afterYears":null,"daysPerMonth":30}', 'sourced', 'Estatuto de los Trabajadores, article 53.1.b (BOE consolidated text)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11430', '2026-10-21', 'Severance on dismissal for objective reasons: 20 days'' salary per year of service, capped at 12 months'' pay; unfair dismissal pays 33 days per year capped at 24 months (art. 56). There is no statutory payment on normal retirement.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ES', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'Hospital care is free under the National Health System; no official figure for a typical out-of-pocket private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ES', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Private health insurance in Spain is sold at flat premiums per person, not per sum insured; no premium table per EUR 100,000 of cover was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ES', 1, 'inflation_cpi', 0.049, NULL, 'sourced', 'Instituto Nacional de Estadística (INE), Consumer Price Index September 2026', 'https://www.ine.es/dyngs/Prensa/es/IPC0926.htm', '2026-09-30', 'CPI 4.9% year on year in September 2026 (HICP 5.0%), released 14 October 2026; INE''s flash estimate for October 2026 is also 4.9% (Trading Economics). World Bank 2025 average 2.7%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ES', 1, 'inflation_projection', 0.025, NULL, 'assumption', 'ECB 2% medium-term target; Spanish HICP 2021-2025 average 4.1% (ECB ICP); CPI 4.9% in September 2026', 'https://data-api.ecb.europa.eu/service/data/ICP/A.ES.N.000000.4.AVR', '2026-10-31', 'Spain shares the ECB''s 2% target; with inflation now well above it and a 4.1% five-year average, 2.5% is used for long-run planning.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ES', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life cover (seguro de vida riesgo) is widely sold, but no regulator or official premium table per EUR 1,000 of cover was found; insurer quotes cannot be used.', 0);
