INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ES', 1, 'life_expectancy', 84.1, NULL, 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/spain', '2026-07-01', 'Men 81.4, women 86.7 (UN WPP estimate for 2026); World Bank 2024 figure 83.9.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ES', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":26.1,"men":23.9,"women":28.2},{"age":65,"total":21.9,"men":19.8,"women":23.7},{"age":70,"total":17.7,"men":16,"women":19.2},{"age":80,"total":10.2,"men":9.1,"women":11}]}', 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/spain', '2026-07-01', 'Remaining years computed from georank''s expected age at death by current age (UN WPP 2026 estimate).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ES', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":65,"womenAge":65,"over90Monthly":null,"meansTested":true}', 'sourced', 'European Commission, Your social security rights in Spain (July 2026)', 'https://employment-social-affairs.ec.europa.eu/document/download/c4767d73-7286-41ad-bc5a-557aedfff7e1_en', '2026-07-31', 'Age 65 or over, living in Spain for 10 years after age 16 including the 2 years before applying, and yearly income below EUR 8,803.20 (household income counted when living with family). Managed by the Autonomous Communities.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ES', 1, 'old_age_allowance_monthly', 733.6, NULL, 'sourced', 'Seguridad Social, pension revaluation 2026 (non-contributory pensions)', 'https://www.seg-social.es/wps/portal/wss/internet/Pensionistas/Revalorizacion/30431', '2026-01-01', 'Non-contributory retirement pension (PNC) of EUR 8,803.20 a year in 2026, paid as 14 payments of EUR 628.80 (European Commission guide, July 2026); the value shown is the yearly amount divided by 12. Means-tested.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ES', 1, 'oop_health_share', 0.2086, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=ES', '2023-12-31', '2023 is the latest year published (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ES', 1, 'policy_rate', 0.025, NULL, 'sourced', 'European Central Bank, key ECB interest rates (deposit facility)', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.en.html', '2026-09-16', 'Spain uses the euro; ECB deposit facility rate raised from 2.25% to 2.50% with effect from 16 September 2026 (main refinancing rate 2.65%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ES', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":67,"nomineeUntilAge":null,"inflationLinked":true,"taxFree":null}', 'sourced', 'Seguridad Social, ordinary retirement age; pension revaluation 2026', 'https://www.seg-social.es/wps/portal/wss/internet/Trabajadores/PrestacionesPensionesTrabajadores/10963/28393/28396/28472', '2026-10-31', 'Compulsory Social Security pension (Régimen General), minimum 15 years of contributions. Ordinary age 67 from 2027 (65 with 38 years 6 months of contributions). Contributory pensions were raised 2.7% for 2026 (Seguridad Social revaluation page).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ES', 1, 'retirement_accumulation_return_base', 0.04, NULL, 'assumption', 'Fixed income base 2.2%; equity base 6%', 'https://www.tesoro.es/deuda-publica/subastas/resultado-ultimas-subastas/letras-del-tesoro', '2026-10-31', 'Base case: roughly half shares at 6% and half safe fixed income at about 2.2% after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ES', 1, 'retirement_accumulation_return_high', 0.055, NULL, 'assumption', '10-year bond 3.4% after tax; equity high 8%', 'https://www.tesoro.es/deuda-publica/subastas/resultado-ultimas-subastas/obligaciones-del-estado', '2026-10-31', 'High case for a growth-leaning balanced mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ES', 1, 'retirement_accumulation_return_low', 0.025, NULL, 'assumption', 'Letras 2.1-2.4% after tax; IBEX 35 record (Trading Economics)', 'https://www.tesoro.es/deuda-publica/subastas/resultado-ultimas-subastas/letras-del-tesoro', '2026-10-31', 'Low case for a balanced mix if shares lag.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ES', 1, 'retirement_age_default', 67, NULL, 'sourced', 'Seguridad Social, ordinary retirement age', 'https://www.seg-social.es/wps/portal/wss/internet/Trabajadores/PrestacionesPensionesTrabajadores/10963/28393/28396/28472', '2026-10-31', 'From 2027 the ordinary age is 67, or 65 with at least 38 years 6 months of contributions (in 2026: 66 years 10 months, or 65 with 38 years 3 months). Same for men and women.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ES', 1, 'retirement_age_government', 67, NULL, 'sourced', 'Estatuto Básico del Empleado Público, article 67.3-67.4 (BOE consolidated text)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719', '2026-10-03', 'Civil servants in the general Social Security scheme (everyone appointed since 1 January 2011) are compulsorily retired at that scheme''s ordinary age, 67 from 2027 (art. 67.4); those still in the older civil-servant scheme (Clases Pasivas) retire at 65 and may ask to stay until 70 (art. 67.3).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ES', 1, 'retirement_return_base', 0.021, NULL, 'assumption', '3-month Letras 2.635% less 19% tax = 2.1% (Tesoro Público)', 'https://www.tesoro.es/deuda-publica/subastas/resultado-ultimas-subastas/letras-del-tesoro', '2026-10-31', 'Base case set at the after-tax 3-month Treasury bill rate, below the 12-month bill''s 2.4% after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ES', 1, 'retirement_return_high', 0.03, NULL, 'assumption', '10-year Obligaciones 4.18% less 19% tax = 3.4% (Tesoro Público)', 'https://www.tesoro.es/deuda-publica/subastas/resultado-ultimas-subastas/obligaciones-del-estado', '2026-10-31', 'High case: a ladder of government bonds held to maturity, below the current after-tax 10-year yield.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ES', 1, 'retirement_return_low', 0.015, NULL, 'assumption', 'Household deposits up to 1 year 2.29% less 19% tax = 1.9% (ECB MFI statistics, September 2026)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.ES.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Low case: term deposits after tax if ECB rates fall.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ES', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Spain has no savings bond reserved for individuals; individuals buy the ordinary Letras, Bonos and Obligaciones directly from the Treasury (Tesoro Público), recorded under the bill and bond rows.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ES', 1, 'savings_account_rate', 0.0016, NULL, 'sourced', 'ECB MFI interest rate statistics: Spanish banks, household overnight deposits (new business)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.ES.B.L21.A.R.A.2250.EUR.N', '2026-09-30', 'Average 0.16% on household overnight deposits (current and most savings accounts) in September 2026, the same as in August.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ES', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":3.04},{"year":2040,"value":1.86},{"year":2065,"value":1.51}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/spain/2040/', '2025-12-31', '100 / old-age dependency ratio: 32.9 (2025, World Bank), 53.9 (2040) and 66.4 (2065, populationpyramid.net/spain/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ES', 1, 'tax_bank_interest', 0.19, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Spain taxes on personal income', 'https://taxsummaries.pwc.com/spain/individual/taxes-on-personal-income', '2026-06-30', 'Interest is savings income taxed at 19% on the first EUR 6,000, 21% to EUR 50,000, 23% to EUR 200,000, 27% to EUR 300,000 and 30% above; banks withhold 19% on deposit interest (withholding not stated on the page read).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ES', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No retail-only government savings bond exists; returns on Letras del Tesoro are savings income taxed at 19-28% with no withholding, per Tesoro Público (tesoro.es, Tributación de las Letras del Tesoro).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ES', 1, 'tbill_91d_rate', 0.0264, NULL, 'sourced', 'Tesoro Público, latest auction results: Letras del Tesoro', 'https://www.tesoro.es/deuda-publica/subastas/resultado-ultimas-subastas/letras-del-tesoro', '2026-10-13', '3-month Letras auctioned on 13 October 2026 at an average 2.635% (marginal 2.645%); 12-month Letras 2.999% on 6 October 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ES', 1, 'tbond_10y_rate', 0.0418, NULL, 'sourced', 'Tesoro Público, latest auction results: Obligaciones del Estado', 'https://www.tesoro.es/deuda-publica/subastas/resultado-ultimas-subastas/obligaciones-del-estado', '2026-10-01', '10-year bond (coupon 3.40%, maturing 31 October 2036) auctioned on 1 October 2026 at an average 4.176%; the market yield had eased to 3.95% by 30 October 2026 (Trading Economics).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ES', 1, 'tbond_5y_rate', 0.0348, NULL, 'sourced', 'Tesoro Público, latest auction results: Bonos del Estado', 'https://www.tesoro.es/deuda-publica/subastas/resultado-ultimas-subastas/bonos-del-estado', '2026-10-15', '5-year bond (coupon 2.60%, maturing 31 May 2031) auctioned on 15 October 2026 at an average 3.482%; Trading Economics showed 3.45% on 30 October 2026.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('ET', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"ET","iso3":"ETH","nameEn":"Ethiopia","nameNative":"ኢትዮጵያ","region":"sub_saharan_africa","languages":["am","om","ti","so","en"],"currency":{"code":"ETB","symbol":"Br","decimals":2,"compact":"intl","usdRate":{"value":153.2503,"status":"sourced","sourceName":"National Bank of Ethiopia, FX sale auction results (Auction No. 19)","sourceUrl":"https://nbe.gov.et/fx-sale-auction/","asOf":"2026-02-21","note":"Auction rate of Birr 153.25 per US dollar on 21 February 2026, the latest published rate (the daily indicative rate page loads no figures as text); the birr floats since July 2024 and averaged 132.76 in April-June 2025 (NBE Annual Report 2024/25)."}},"instruments":{"savings_account":{"available":true,"localName":"የቁጠባ ሂሳብ","localNameEn":"Savings account","note":"Rates set freely by each bank since January 2026; averaged 8.0% in 2024/25 (NBE).","sourceUrl":"https://nbe.gov.et/wp-content/uploads/2026/07/Annual-Report-2024-2025.pdf"},"fdr_3m":{"available":true,"localName":"የጊዜ ገደብ ተቀማጭ (3 ወር)","localNameEn":"Time deposit (3 months)","note":"Banks take time deposits; only an up-to-1-year average (7.7%) is published.","sourceUrl":"https://nbe.gov.et/wp-content/uploads/2026/07/Annual-Report-2024-2025.pdf"},"fdr_1y":{"available":true,"localName":"የጊዜ ገደብ ተቀማጭ (1 ዓመት)","localNameEn":"Time deposit (1 year)","note":"Weighted average for time deposits up to 1 year was 7.7% in 2024/25 (NBE).","sourceUrl":"https://nbe.gov.et/wp-content/uploads/2026/07/Annual-Report-2024-2025.pdf"},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No standard monthly recurring deposit product with a published rate was found."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate or retail savings bond for individuals was found."},"tbill_91d":{"available":false,"localName":"የግምጃ ቤት ሰነድ","localNameEn":"Treasury bills","note":"Treasury bills of 28-364 days are auctioned by the NBE every two weeks; banks bid electronically and non-banks submit bids on paper, but direct access for individuals was not confirmed.","sourceUrl":"https://nbe.gov.et/treasury-bills/"},"tbond_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No marketable 5-year government bond was found."},"tbond_10y":{"available":false,"localName":null,"localNameEn":null,"note":"No marketable 10-year government bond was found."},"equity_fund":{"available":false,"localName":null,"localNameEn":null,"note":"The Ethiopian Securities Exchange opened in January 2025; no diversified retail equity fund was found."},"gold":{"available":true,"localName":"ወርቅ","localNameEn":"Gold","note":"Gold is bought mainly as jewellery; the NBE publishes a gold purchasing rate for gold sold to it.","sourceUrl":"https://nbe.gov.et/exchange/gold-purchasing-rate/"}},"institutions":{"centralBank":{"name":"National Bank of Ethiopia (NBE)","url":"https://nbe.gov.et/"},"insuranceRegulator":{"name":"National Bank of Ethiopia, insurance supervision","url":"https://nbe.gov.et/financial-institutions/insurers/"},"insuranceComplaints":{"name":"National Bank of Ethiopia, Financial Consumer Protection Directive No. FCP/01/2020 (complaint handling by financial institutions)","url":"https://nbe.gov.et/files/financial-consumer-protection-directive-no-fcp-01-2020/"},"pensionScheme":{"name":"Private Organization Employees'' Social Security Administration (POESSA)","url":"https://www.poessa.gov.et/"},"oldAgeAllowance":null,"publicHealthCover":{"name":"Ethiopian Health Insurance Service (community-based and social health insurance)","url":"https://ehis.gov.et/en"},"depositInsurance":{"name":"Ethiopian Deposit Insurance Fund (EDIF)","url":"https://edif.gov.et/"},"statistics":{"name":"Ethiopian Statistical Service (ESS)","url":"https://ess.gov.et/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ET', 1, 'bank_deposit_avg_rate', 0.077, NULL, 'sourced', 'National Bank of Ethiopia, Annual Report 2024/25, Table 4.4 Interest Rates (time deposits, weighted average)', 'https://nbe.gov.et/wp-content/uploads/2026/07/Annual-Report-2024-2025.pdf', '2025-06-30', 'Weighted average time deposit rate 7.7% in 2024/25 (savings deposits 8.0% simple average; demand deposits 0.1%). The World Bank series (FR.INR.DPST) stops in 2008. Deposit rates have been set freely by each bank since 9 January 2026 (NBE Directive NBE/INT/13/2026, which repealed the 7% minimum), so later rates may differ.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ET', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap on card rates exists since lending rates are set freely by each bank (NBE Directive NBE/INT/13/2026); no typical credit card rate is published. The NBE reports an average lending rate of 15.8% in 2024/25.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ET', 1, 'deposit_insurance_limit', 100000, NULL, 'sourced', 'Ethiopian Deposit Insurance Fund (EDIF), Insurance coverage limit', 'https://edif.gov.et/insurance-coverage-limit/', '2026-10-31', 'Up to Birr 100,000 per depositor per member financial institution (banks and microfinance institutions); the fund began operating in April 2023.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ET', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No standard monthly recurring deposit rate is published by the NBE; banks set their own rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ET', 1, 'equity_return_base', 0.105, NULL, 'assumption', 'After-tax safe rate about 7% (NBE Annual Report 2024/25; PwC 10% interest tax); no 10-year local index record', 'https://nbe.gov.et/wp-content/uploads/2026/07/Annual-Report-2024-2025.pdf', '2026-10-31', 'There is no local index history (the exchange opened in 2025), so equity means a global index in birr terms, capped at about 3.5 points above the after-tax safe rate of about 7% even though birr depreciation could add more.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ET', 1, 'equity_return_high', 0.16, NULL, 'assumption', 'Global equity in birr terms; birr fell from 56 to 119 per dollar on average between 2023/24 and 2024/25 (NBE)', 'https://nbe.gov.et/wp-content/uploads/2026/07/Annual-Report-2024-2025.pdf', '2026-10-31', 'High case: global equity returns plus continued birr depreciation of several points a year.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ET', 1, 'equity_return_low', 0.05, NULL, 'assumption', 'Ethiopian Securities Exchange opened in January 2025 with very few listings; birr depreciation (NBE)', 'https://nbe.gov.et/wp-content/uploads/2026/07/Annual-Report-2024-2025.pdf', '2026-10-31', 'Low case: a weak decade for equities with little currency gain, well below inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ET', 1, 'fdr_1y_rate', 0.077, NULL, 'sourced', 'National Bank of Ethiopia, Annual Report 2024/25, Table 4.4 Interest Rates (time deposit up to 1 year, weighted average)', 'https://nbe.gov.et/wp-content/uploads/2026/07/Annual-Report-2024-2025.pdf', '2025-06-30', 'Weighted average rate on time deposits of up to 1 year, 7.7% in 2024/25. Deposit rates have been set freely by each bank since 9 January 2026 (NBE Directive NBE/INT/13/2026, which repealed the 7% minimum), so later rates may differ.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ET', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published 3-month term deposit rate was found; the NBE reports only a weighted average for time deposits up to 1 year (7.7% in 2024/25).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ET', 1, 'fixed_income_return_base', 0.07, NULL, 'assumption', 'NBE Annual Report 2024/25 (savings 8.0%, time deposits 7.7%); 10% final withholding tax on interest (PwC); NBE T-bill auctions 2026', 'https://nbe.gov.et/wp-content/uploads/2026/07/Annual-Report-2024-2025.pdf', '2026-10-31', 'Base case: 1-year time deposits at about 7.7% less the 10% final withholding tax, about 6.9-7%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ET', 1, 'fixed_income_return_high', 0.09, NULL, 'assumption', 'NBE Annual Report 2024/25 (savings 8.0%, time deposits 7.7%); 10% final withholding tax on interest (PwC); NBE T-bill auctions 2026', 'https://nbe.gov.et/treasury-bills/', '2026-10-31', 'High case: better-paying time deposits or 364-day Treasury bills (6.0-10.0% at the August-October 2026 auctions) where accessible.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ET', 1, 'fixed_income_return_low', 0.06, NULL, 'assumption', 'NBE Annual Report 2024/25 (savings 8.0%, time deposits 7.7%); 10% final withholding tax on interest (PwC); NBE T-bill auctions 2026', 'https://nbe.gov.et/wp-content/uploads/2026/07/Annual-Report-2024-2025.pdf', '2026-10-31', 'Low case: savings and time deposits after deposit rates were freed in 2026 drift down, less 10% tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ET', 1, 'goal_inflation_education', 0.13, NULL, 'assumption', 'Ethiopian Statistical Service CPI September 2026: education prices +17.8% year on year', 'https://ess.gov.et/download/consumer-price-index-septmber-2026/', '2026-10-31', 'Education prices rose 17.8% in the year to September 2026, so education goals use 3 points above the 10% planning inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ET', 1, 'goal_inflation_health', 0.12, NULL, 'assumption', 'Ethiopian Statistical Service CPI September 2026: health prices +10.9% year on year', 'https://ess.gov.et/download/consumer-price-index-septmber-2026/', '2026-10-31', 'Health prices rose 10.9% in the year to September 2026; private and imported care costs run faster, so health goals use 2 points above the 10% planning inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ET', 1, 'gold_return_base', 0.12, NULL, 'assumption', 'Dollar gold trend; NBE exchange rate history (Birr 55.96 in 2023/24, 119.31 in 2024/25, 153.25 at the February 2026 auction)', 'https://nbe.gov.et/fx-sale-auction/', '2026-10-31', 'Base case: dollar gold trend of about 4% a year plus birr depreciation of about 8% a year, in line with the gap between Ethiopian and US inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ET', 1, 'gold_return_high', 0.2, NULL, 'assumption', 'Dollar gold trend; NBE exchange rate history (Birr 55.96 in 2023/24, 119.31 in 2024/25, 153.25 at the February 2026 auction)', 'https://nbe.gov.et/fx-sale-auction/', '2026-10-31', 'High case: strong gold years with faster birr depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ET', 1, 'gold_return_low', 0.04, NULL, 'assumption', 'Dollar gold trend; NBE exchange rate history (Birr 55.96 in 2023/24, 119.31 in 2024/25, 153.25 at the February 2026 auction)', 'https://nbe.gov.et/fx-sale-auction/', '2026-10-31', 'Low case: flat dollar gold with slow birr depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ET', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Labour Proclamation No. 1156/2019 provides severance pay on some terminations, but its official text could not be read (ILO NATLEX and the labour ministry site were not reachable), so the rule is not recorded.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ET', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical out-of-pocket cost of a major hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ET', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premiums by age were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ET', 1, 'inflation_cpi', 0.149, NULL, 'sourced', 'Ethiopian Statistical Service, Consumer Price Index monthly news release, September 2026 (Meskerem EFY2019)', 'https://ess.gov.et/download/consumer-price-index-septmber-2026/', '2026-09-30', 'Year-on-year general inflation 14.9% (food 14.8%, non-food 15.1%), up from a low of 9.4% in March 2026; the Ethiopian month runs 11 September to 10 October 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ET', 1, 'inflation_projection', 0.1, NULL, 'assumption', 'NBE Monetary Policy Committee aim of single-digit inflation in the medium term; ESS CPI 9.4-15.3% in 2025/26', 'https://nbe.gov.et/mpc7/', '2026-10-31', 'The NBE aims for single-digit inflation but inflation was 9.4-15.3% over the last year and above 20% in 2021-2023, so a rounded 10% is used for long-run planning.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ET', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published term life premium rates per Birr 1,000 of cover were found from the regulator or a credible guide.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ET', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No industry-wide life insurance claim settlement ratio was found from the NBE, which supervises insurers.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ET', 1, 'life_expectancy', 67.603, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN), Ethiopia', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=ET', '2024-12-31', '67.6 years in 2024 (men 64.4, women 71.0).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ET', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":18.3,"men":17.1,"women":19.5},{"age":65,"total":14.8,"men":13.7,"women":15.7},{"age":70,"total":11.5,"men":10.7,"women":12.2},{"age":80,"total":6.4,"men":5.9,"women":6.8}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/ethiopia/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026; totals are the mean of men and women except at 65, where the page gives 14.8 for both sexes.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ET', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'No national non-contributory old-age pension was found; the POESSA and public servants'' schemes are contributory.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ET', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'No national non-contributory old-age pension was found; the POESSA and public servants'' schemes are contributory, and safety-net transfers are not old-age pensions.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ET', 1, 'oop_health_share', 0.4627, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), Ethiopia', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=ET', '2023-12-31', '46.3% in 2023 (WHO Global Health Expenditure Database via the World Bank), the latest available; older than 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ET', 1, 'policy_rate', 0.16, NULL, 'sourced', 'National Bank of Ethiopia, MPC meeting No. 7 press release (13 July 2026) and NBE homepage rate panel (NBR 16%)', 'https://nbe.gov.et/mpc7/', '2026-07-13', 'The MPC raised the National Bank Rate by 1 percentage point from 15% to 16% (corridor of plus or minus 3 points); the NBE site shows NBR 16% on 31 October 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ET', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":60,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'Private Organization Employees'' Social Security Administration (POESSA), pension page', 'https://www.poessa.gov.et/?page_id=443', '2026-10-31', 'Compulsory scheme for private-sector employees (Proclamation No. 1268/2022): contributions 7% employee and 11% employer; pension at 60 after 10 years, 30% of the average salary of the last 36 months plus 1.25% for each year beyond 10; under 10 years a lump-sum grant. The page states no automatic indexation; tax treatment was not confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ET', 1, 'retirement_accumulation_return_base', 0.085, NULL, 'assumption', 'After-tax safe rate about 7%; global equity base 10.5% and gold base 12% in birr terms', 'https://nbe.gov.et/wp-content/uploads/2026/07/Annual-Report-2024-2025.pdf', '2026-10-31', 'Base case: a balanced mix of time deposits, gold and some equity.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ET', 1, 'retirement_accumulation_return_high', 0.11, NULL, 'assumption', 'After-tax safe rate about 7%; global equity base 10.5% and gold base 12% in birr terms', 'https://nbe.gov.et/wp-content/uploads/2026/07/Annual-Report-2024-2025.pdf', '2026-10-31', 'High case: a growth-leaning mix with more equity and gold.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ET', 1, 'retirement_accumulation_return_low', 0.065, NULL, 'assumption', 'After-tax safe rate about 7%; global equity base 10.5% and gold base 12% in birr terms', 'https://nbe.gov.et/wp-content/uploads/2026/07/Annual-Report-2024-2025.pdf', '2026-10-31', 'Low case: mostly bank deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ET', 1, 'retirement_age_default', 60, NULL, 'sourced', 'Private Organization Employees'' Social Security Administration (POESSA), pension page', 'https://www.poessa.gov.et/?page_id=443', '2026-10-31', 'Service pension at 60 with at least 10 years of service; voluntary early pension from 55 with 25 years. Same age for men and women (Private Organization Employees'' Pension Proclamation No. 1268/2022).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ET', 1, 'retirement_age_government', 60, NULL, 'sourced', 'Public Servants'' Social Security Administration, Implementation Directive No. 959/2023 of Proclamation No. 1267/2022', 'https://psssa.gov.et/sites/default/files/resource/959_Public_Servants%E2%80%99_Pension_Proclamation_No_12672022_Implementation.pdf', '2022-12-09', 'The directive states the retirement age determined by law is 60 years; early pension from 55 with 25 years of service. The directive dates from 2022 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ET', 1, 'retirement_return_base', 0.065, NULL, 'assumption', 'NBE Annual Report 2024/25 (savings 8.0%, time deposits 7.7%); 10% final withholding tax on interest (PwC); NBE T-bill auctions 2026', 'https://nbe.gov.et/wp-content/uploads/2026/07/Annual-Report-2024-2025.pdf', '2026-10-31', 'Base case: 1-year time deposits at about 7.7% less 10% tax (about 6.9%), kept a little below that after-tax rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ET', 1, 'retirement_return_high', 0.08, NULL, 'assumption', 'NBE Annual Report 2024/25 (savings 8.0%, time deposits 7.7%); 10% final withholding tax on interest (PwC); NBE T-bill auctions 2026', 'https://nbe.gov.et/treasury-bills/', '2026-10-31', 'High case: better time deposit offers or 364-day Treasury bills where accessible.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ET', 1, 'retirement_return_low', 0.055, NULL, 'assumption', 'NBE Annual Report 2024/25 (savings 8.0%, time deposits 7.7%); 10% final withholding tax on interest (PwC); NBE T-bill auctions 2026', 'https://nbe.gov.et/wp-content/uploads/2026/07/Annual-Report-2024-2025.pdf', '2026-10-31', 'Low case: mostly savings accounts after deposit rates fall, less 10% tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ET', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate or retail savings bond for individuals was found on the NBE or Ministry of Finance sites; Treasury bills are auctioned by the NBE.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ET', 1, 'savings_account_rate', 0.08, NULL, 'sourced', 'National Bank of Ethiopia, Annual Report 2024/25, Table 4.4 Interest Rates (savings deposit, simple average)', 'https://nbe.gov.et/wp-content/uploads/2026/07/Annual-Report-2024-2025.pdf', '2025-06-30', 'Average savings deposit rate 8.0% (minimum 7%, maximum 9%) at end June 2025. Deposit rates have been set freely by each bank since 9 January 2026 (NBE Directive NBE/INT/13/2026, which repealed the 7% minimum), so later rates may differ.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ET', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":17.6},{"year":2040,"value":13.9},{"year":2065,"value":8}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://data.worldbank.org/indicator/SP.POP.DPND.OL?locations=ET', '2025-12-31', '100 / old-age dependency ratio: 5.69 (2025, World Bank), 7.2 (2040, populationpyramid.net/ethiopia/2040/) and 12.5 (2065, populationpyramid.net/ethiopia/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ET', 1, 'tax_bank_interest', 0.1, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Ethiopia, Individual - Income determination (last reviewed 15 July 2026)', 'https://taxsummaries.pwc.com/ethiopia/individual/income-determination', '2026-07-15', 'Interest income is subject to a 10% withholding tax, which is the final tax (secondary source; the income tax proclamation itself was not read).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ET', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate exists for individuals and the tax treatment of Treasury bill income for individuals was not confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ET', 1, 'tbill_91d_rate', 0.02016, NULL, 'sourced', 'National Bank of Ethiopia, Treasury bill auction results, Auction No. 1015th/2026 (28 October 2026)', 'https://nbe.gov.et/treasury-bills/', '2026-10-28', '91-day weighted average yield 2.016% (28-day 1.305%, 182-day 3.667%, 364-day 6.016%). Yields have fallen steadily through 2026 (91-day 14.4% in April, 5.5% on 5 August, 3.2% on 16 September) even though the policy rate is 16%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ET', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No marketable 10-year government bond yield was found; the NBE treasury auction page lists only bills of 28 to 364 days.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ET', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No marketable 5-year government bond yield was found; the NBE treasury auction page lists only bills of 28 to 364 days.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('FI', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"FI","iso3":"FIN","nameEn":"Finland","nameNative":"Suomi","region":"europe_central_asia","languages":["fi","en","sv","de"],"currency":{"code":"EUR","symbol":"€","decimals":2,"compact":"intl","usdRate":{"value":0.8951,"status":"sourced","sourceName":"European Central Bank euro reference rate (USD)","sourceUrl":"https://www.ecb.europa.eu/stats/policy_and_exchange_rates/euro_reference_exchange_rates/html/eurofxref-graph-usd.en.html","asOf":"2026-10-30","note":"EUR 1 = USD 1.1172, so about EUR 0.895 per US dollar; World Bank 2025 average 0.885."}},"instruments":{"savings_account":{"available":true,"localName":"Säästötili","localNameEn":"Savings account","sourceUrl":"https://data-api.ecb.europa.eu/service/data/MIR/M.FI.B.L21.A.R.A.2250.EUR.N"},"fdr_3m":{"available":true,"localName":"Määräaikaistalletus","localNameEn":"Fixed-term deposit (3 months)"},"fdr_1y":{"available":true,"localName":"Määräaikaistalletus","localNameEn":"Fixed-term deposit (1 year)","sourceUrl":"https://data-api.ecb.europa.eu/service/data/MIR/M.FI.B.L22.F.R.A.2250.EUR.N"},"dps":{"available":true,"localName":"ASP-tili","localNameEn":"Home-savings (ASP) account","note":"Regular saving towards a first home with state-backed loan benefits; interest set by each bank."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":"Government savings bond","note":"No retail government savings bond for individuals was found."},"tbill_91d":{"available":true,"localName":"Valtion velkasitoumukset","localNameEn":"Treasury bills (RFTB)","note":"Issued by the State Treasury, mainly to institutions."},"tbond_5y":{"available":true,"localName":"Valtion obligaatiot","localNameEn":"Finnish government bonds"},"tbond_10y":{"available":true,"localName":"Valtion obligaatiot","localNameEn":"Finnish government bonds","sourceUrl":"https://data-api.ecb.europa.eu/service/data/IRS/M.FI.L.L40.CI.0000.EUR.N.Z"},"equity_fund":{"available":true,"localName":"Sijoitusrahastot","localNameEn":"Mutual funds / index funds (ETF)","note":"Retail funds widely available; an equity savings account (osakesäästötili) defers tax on gains."},"gold":{"available":true,"localName":"Kultaharkot ja kultakolikot","localNameEn":"Gold bars and coins","note":"No restriction on buying physical gold."}},"institutions":{"centralBank":{"name":"Suomen Pankki (Bank of Finland)","url":"https://www.suomenpankki.fi/en/","note":"Part of the Eurosystem; monetary policy set by the European Central Bank."},"insuranceRegulator":{"name":"Finanssivalvonta (Financial Supervisory Authority, FIN-FSA)","url":"https://www.finanssivalvonta.fi/en/"},"insuranceComplaints":{"name":"FINE Finnish Financial Ombudsman Bureau (Insurance Complaints Board)","url":"https://www.fine.fi/en/"},"pensionScheme":{"name":"Earnings-related pension (työeläke), Finnish Centre for Pensions","url":"https://www.tyoelake.fi/en/"},"oldAgeAllowance":{"name":"Kela national pension and guarantee pension","url":"https://www.kela.fi/old-age-pension"},"publicHealthCover":{"name":"Kela health insurance and public health services of the wellbeing services counties","url":"https://www.kela.fi/main-page"},"depositInsurance":{"name":"Rahoitusvakausvirasto (Financial Stability Authority), deposit guarantee","url":"https://rvv.fi/en/deposit-guarantee/"},"statistics":{"name":"Tilastokeskus (Statistics Finland)","url":"https://stat.fi/en"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FI', 1, 'bank_deposit_avg_rate', 0.0224, NULL, 'sourced', 'ECB MFI interest rate statistics: Finnish banks, household deposits with agreed maturity (outstanding amounts)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.FI.B.L22.A.R.A.2250.EUR.O', '2026-09-30', 'Average rate on all outstanding household term deposits, September 2026; household overnight deposits paid 0.39%. World Bank FR.INR.DPST has no Finland figure.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FI', 1, 'credit_card_rate_cap', 0.0929, NULL, 'sourced', 'ECB MFI interest rate statistics: Finnish banks, revolving loans, overdrafts and credit card credit to households', 'https://data-api.ecb.europa.eu/service/data/MIR/M.FI.B.A2Z.A.R.A.2250.EUR.N', '2026-09-30', 'Typical rate, not a cap: average rate on household revolving loans, overdrafts and credit card credit, September 2026 (9.17% in August); the statutory consumer-credit interest ceiling was not verified from a source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FI', 1, 'deposit_insurance_limit', 100000, NULL, 'sourced', 'Finanssivalvonta (FIN-FSA), security of deposits and investments', 'https://www.finanssivalvonta.fi/en/consumers/security-of-deposits-and-investments/', '2026-10-31', 'EUR 100,000 per customer per bank; the deposit guarantee is run by the Financial Stability Authority (rvv.fi, which refused automated access).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FI', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The regular-saving deposit product in Finland is the home-savings (ASP) account, whose interest is set by each bank; no average or official rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FI', 1, 'equity_return_base', 0.055, NULL, 'assumption', 'OMX Helsinki 25 (Trading Economics); deposits up to 1 year 2.82% less 30% tax = 1.97%', 'https://tradingeconomics.com/finland/stock-market', '2026-10-31', 'Base capped near the after-tax safe rate plus about 4 points because the Helsinki market is small and cyclical.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FI', 1, 'equity_return_high', 0.075, NULL, 'assumption', 'OMX Helsinki 25; long-run global equity returns', 'https://tradingeconomics.com/finland/stock-market', '2026-10-31', 'High case: a diversified euro equity fund matching long-run global equity returns of about 7-8% in euros.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FI', 1, 'equity_return_low', 0.03, NULL, 'assumption', 'OMX Helsinki 25 about 6,214 on 2 Nov 2026, up 13% in a year, near the September 2026 high of 6,663', 'https://tradingeconomics.com/finland/stock-market', '2026-10-31', 'Low case: Finnish shares, heavy in industrials, forestry and banks, return little more than safe deposits over a long period.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FI', 1, 'fdr_1y_rate', 0.0282, NULL, 'sourced', 'ECB MFI interest rate statistics: Finnish banks, household deposits with agreed maturity up to 1 year (new business)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.FI.B.L22.F.R.A.2250.EUR.N', '2026-09-30', 'Bucket covers all fixed terms up to one year; September 2026 (2.53% in August).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FI', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'ECB/Bank of Finland MFI statistics publish household deposits with agreed maturity up to 1 year as one bucket (2.82% in September 2026); no separate 3-month term deposit rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FI', 1, 'fixed_income_return_base', 0.019, NULL, 'assumption', 'Household deposits up to 1 year 2.82% (ECB MFI, Sep 2026) less 30% tax = 1.97%', 'https://data-api.ecb.europa.eu/service/data/MIR/M.FI.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Base case: just under the after-tax 1-year term deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FI', 1, 'fixed_income_return_high', 0.026, NULL, 'assumption', 'Finland 10-year government bond 3.80% (ECB, Sep 2026) less 30% tax = 2.66%', 'https://data-api.ecb.europa.eu/service/data/IRS/M.FI.L.L40.CI.0000.EUR.N.Z', '2026-10-31', 'High case: holding long government bonds after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FI', 1, 'fixed_income_return_low', 0.012, NULL, 'assumption', 'Household deposits up to 1 year 2.82% (ECB MFI, Sep 2026), assuming rates fall, less 30% tax', 'https://data-api.ecb.europa.eu/service/data/MIR/M.FI.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Low case: term deposit rates drift down towards 1.7% before the 30% withholding.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FI', 1, 'goal_inflation_education', 0.04, NULL, 'assumption', 'Statistics Finland CPI 15b5, education services (COICOP 10): +4.2% in the year to Sep 2026, about 4.0% a year since Sep 2021', 'https://pxdata.stat.fi/PxWeb/pxweb/en/StatFin/StatFin__khi/statfin_khi_pxt_15b5.px/', '2026-10-31', 'Education fees have risen about 4% a year over five years, which is used for planning (public schooling and university are free for residents).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FI', 1, 'goal_inflation_health', 0.03, NULL, 'assumption', 'Statistics Finland CPI 15b5, health (COICOP 06): +2.5% in the year to Sep 2026, about 1.7% a year since Sep 2021', 'https://pxdata.stat.fi/PxWeb/pxweb/en/StatFin/StatFin__khi/statfin_khi_pxt_15b5.px/', '2026-10-31', 'Measured health prices have risen slowly, but client fees and private care costs are planned at 3%, a point above the inflation target.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FI', 1, 'gold_return_base', 0.04, NULL, 'assumption', 'Gold price history (Trading Economics); ECB 2% inflation target', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Base case: dollar gold rises roughly with world inflation plus a little, and the euro is assumed stable against the dollar over the long run.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FI', 1, 'gold_return_high', 0.07, NULL, 'assumption', 'Gold price history (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'High case: a repeat of gold''s strong 2005-2025 trend in euro terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FI', 1, 'gold_return_low', 0.01, NULL, 'assumption', 'Gold price history (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Low case: gold barely keeps up after the 2025-26 spike, with no help from the euro.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FI', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'Finnish employment law has no statutory severance or end-of-service gratuity for private employees; none found in the sources read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FI', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'Public hospital care is provided by the wellbeing services counties for capped client fees; no official figure for the out-of-pocket cost of a major private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FI', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Private health insurance is sold, but premiums are not quoted per EUR 100,000 of cover and no published premium table was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FI', 1, 'inflation_cpi', 0.025, NULL, 'sourced', 'Statistics Finland, 122p annual change of the Consumer Price Index', 'https://pxdata.stat.fi/PxWeb/pxweb/en/StatFin/StatFin__khi/statfin_khi_pxt_122p.px/', '2026-09-30', 'CPI up 2.5% year on year in September 2026 (2.2% in August); World Bank 2025 average 0.3%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FI', 1, 'inflation_projection', 0.02, NULL, 'assumption', 'ECB 2% medium-term target; Finnish CPI about 3.4% a year Sep 2021-Sep 2026, 0.3% in 2025, 2.5% in Sep 2026', 'https://pxdata.stat.fi/PxWeb/pxweb/en/StatFin/StatFin__khi/statfin_khi_pxt_122p.px/', '2026-10-31', 'Finnish inflation has swung around the ECB 2% target (high in 2022-23, very low in 2025), so the target itself is used for planning.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FI', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life cover (henkivakuutus / kuolemanvaraturva) is sold, but no published premium table per EUR 1,000 of cover was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FI', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Finanssivalvonta and Finance Finland do not publish an industry-wide life claim settlement ratio that could be found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FI', 1, 'life_expectancy', 82.27, NULL, 'sourced', 'Statistics Finland, 12ap life table by age and sex', 'https://pxdata.stat.fi/PxWeb/pxweb/en/StatFin/StatFin__kuol/statfin_kuol_pxt_12ap.px/', '2025-12-31', 'Men 79.81, women 84.73 in 2025; World Bank 2024 figure 82.3.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FI', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":24.87,"men":22.99,"women":26.62},{"age":65,"total":20.65,"men":18.94,"women":22.19},{"age":70,"total":16.67,"men":15.21,"women":17.92},{"age":80,"total":9.6,"men":8.65,"women":10.28}]}', 'sourced', 'Statistics Finland, 12ap life table by age and sex', 'https://pxdata.stat.fi/PxWeb/pxweb/en/StatFin/StatFin__kuol/statfin_kuol_pxt_12ap.px/', '2025-12-31', NULL, 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FI', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":65,"womenAge":65,"over90Monthly":null,"meansTested":true}', 'sourced', 'Kela, old-age pension and guarantee pension', 'https://www.kela.fi/old-age-pension', '2026-09-10', 'Payable from 65 (for people born 1965 or later the age depends on birth year) to residents who have lived in Finland at least 3 years after age 16; tested against other pension income only (not earnings, capital or assets). Taxable.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FI', 1, 'old_age_allowance_monthly', 787.07, NULL, 'sourced', 'Kela, old-age pension (national pension, kansaneläke)', 'https://www.kela.fi/old-age-pension', '2026-09-10', 'Full national pension for a person living alone, EUR 787.07 a month (EUR 702.69 in a couple), per kela.fi (page last modified 10 Sep 2026); reduced by half of other pensions above EUR 66.54 a month and not paid if the earnings-related pension exceeds EUR 1,624.63 (single). A guarantee pension is available when total pensions are EUR 978.33 a month or less.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FI', 1, 'oop_health_share', 0.1409, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=FI', '2023-12-31', 'Latest World Bank figure is for 2023 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FI', 1, 'policy_rate', 0.025, NULL, 'sourced', 'European Central Bank, key ECB interest rates (deposit facility)', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.en.html', '2026-09-16', 'Finland uses the euro; ECB deposit facility rate 2.50% since 16 September 2026 (2.25% from 17 June 2026, 2.00% before), per the ECB FM dataset.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FI', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":65,"nomineeUntilAge":null,"inflationLinked":true,"taxFree":false}', 'sourced', 'Työeläke.fi (retirement ages; pension indexes) and Kela', 'https://www.tyoelake.fi/en/how-much-pension/indexes-protect-the-pension-amount/', '2026-10-31', 'Compulsory earnings-related pension (työeläke) plus the residence-based Kela national pension; pensions in payment are adjusted every January by the earnings-related pension index (80% prices, 20% wages). Pensions are taxed as earned income. Pension age 65 for the 1962-64 cohorts, linked to life expectancy from the 1965 cohort.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FI', 1, 'retirement_accumulation_return_base', 0.035, NULL, 'assumption', 'After-tax 1-year deposit 1.97%; equity base 5.5%', 'https://data-api.ecb.europa.eu/service/data/MIR/M.FI.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Base case: roughly half shares at 5.5% and half safe fixed income at about 1.9-2.7% after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FI', 1, 'retirement_accumulation_return_high', 0.05, NULL, 'assumption', 'After-tax 10-year bond 2.66%; equity high 7.5%', 'https://data-api.ecb.europa.eu/service/data/IRS/M.FI.L.L40.CI.0000.EUR.N.Z', '2026-10-31', 'High case for a growth-leaning balanced mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FI', 1, 'retirement_accumulation_return_low', 0.025, NULL, 'assumption', 'After-tax 1-year deposit 1.97%; OMX Helsinki 25 record', 'https://data-api.ecb.europa.eu/service/data/MIR/M.FI.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Low case for a balanced mix if shares lag.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FI', 1, 'retirement_age_default', 65, NULL, 'sourced', 'Työeläke.fi (Finnish Centre for Pensions), retirement age by year of birth', 'https://www.tyoelake.fi/en/different-pensions/old-age-pension-your-retirement-age-is-based-on-your-year-of-birth/', '2026-10-31', 'Lowest earnings-related retirement age is 65 for people born 1962-64 (64y9m for 1961). From the 1965 cohort it is set by life expectancy, rising by at most 2 months per birth year, so people born after 1975 will have a higher age (at most about 66y10m for the 1976 cohort) that is not yet fixed; 65 is the latest confirmed age. Same for men and women.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FI', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'Public-sector employees follow the general retirement ages, but some have lower occupational retirement ages (raised by 2 years by 2025) set by Keva; no single figure was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FI', 1, 'retirement_return_base', 0.019, NULL, 'assumption', 'Household deposits up to 1 year 2.82% (ECB MFI, Sep 2026) less 30% tax = 1.97%', 'https://data-api.ecb.europa.eu/service/data/MIR/M.FI.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Base case kept just under the after-tax 1-year term deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FI', 1, 'retirement_return_high', 0.024, NULL, 'assumption', 'Finland 10-year government bond 3.80% (ECB, Sep 2026) less 30% tax = 2.66%', 'https://data-api.ecb.europa.eu/service/data/IRS/M.FI.L.L40.CI.0000.EUR.N.Z', '2026-10-31', 'High case: a ladder of longer government bonds after tax, slightly below the 10-year yield.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FI', 1, 'retirement_return_low', 0.012, NULL, 'assumption', 'Household deposits up to 1 year 2.82% (ECB MFI, Sep 2026), assuming rates fall, less 30% tax', 'https://data-api.ecb.europa.eu/service/data/MIR/M.FI.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Low case: term deposit rates drift lower.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FI', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No retail government savings bond sold to individuals was found; Finnish government bonds and bills are sold through primary dealers to institutions.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FI', 1, 'savings_account_rate', 0.0039, NULL, 'sourced', 'ECB MFI interest rate statistics: Finnish banks, overnight deposits from households (new business)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.FI.B.L21.A.R.A.2250.EUR.N', '2026-09-30', 'Average rate on household overnight deposits in Finland, September 2026 (0.38% in August).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FI', 1, 'support_ratio', NULL, '{"points":[{"year":2026,"value":2.59},{"year":2040,"value":2.52},{"year":2065,"value":2}]}', 'sourced', 'Statistics Finland, population projection 2024 (128t)', 'https://pxdata.stat.fi/PxWeb/pxweb/en/StatFin/StatFin__vaenn/statfin_vaenn_pxt_128t.px/', '2026-12-31', 'People aged 15-64 divided by people 65+ in the official 2024 projection (31 December of each year); the projection assumes high net immigration. World Bank 2025 old-age dependency 39.4 gives 2.54.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FI', 1, 'tax_bank_interest', 0.3, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Finland income determination', 'https://taxsummaries.pwc.com/finland/individual/income-determination', '2026-06-24', 'Interest on deposits in Finnish banks is subject to a final 30% tax withheld at source; other capital income is taxed at 30% up to EUR 30,000 and 34% above.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FI', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No retail government savings certificate exists; interest on government bonds is capital income taxed at 30% (34% above EUR 30,000).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FI', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The State Treasury issues Treasury bills (RFTB), but its website was down when read (treasuryfinland.fi showed a disruption notice) and no 3-month yield was found elsewhere.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FI', 1, 'tbond_10y_rate', 0.038, NULL, 'sourced', 'ECB long-term interest rate for convergence purposes, Finland (10-year government bond yield)', 'https://data-api.ecb.europa.eu/service/data/IRS/M.FI.L.L40.CI.0000.EUR.N.Z', '2026-09-30', 'Monthly average for September 2026 (3.52% in August); Trading Economics showed about 3.74% at the end of October.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FI', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 5-year Finnish government bond yield was found: Trading Economics shows only 2- and 10-year yields and the State Treasury site was down.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('FJ', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"FJ","iso3":"FJI","nameEn":"Fiji","nameNative":"Viti","region":"east_asia_pacific","languages":["fj","hif","en"],"currency":{"code":"FJD","symbol":"$","decimals":2,"compact":"intl","usdRate":{"value":2.2528,"status":"sourced","sourceName":"Reserve Bank of Fiji statistics table 8.8 (daily exchange rates)","sourceUrl":"https://www.rbf.gov.fj/wp-content/uploads/2026/10/8.8-Exchange-Rates-Daily-9.xlsx","asOf":"2026-10-27","note":"FJD 1 = USD 0.4439, so FJD 2.25 per US dollar."}},"instruments":{"savings_account":{"available":true,"localName":"Savings account","sourceUrl":"https://www.rbf.gov.fj/wp-content/uploads/2026/10/2.8-Commercial-Banks-Lending-and-Deposit-Rates.xlsx"},"fdr_3m":{"available":true,"localName":"Term deposit","localNameEn":"3-month term deposit","sourceUrl":"https://www.rbf.gov.fj/wp-content/uploads/2026/10/2.9-Commercial-Banks-Time-Deposit-Rates.xlsx"},"fdr_1y":{"available":true,"localName":"Term deposit","localNameEn":"1-year term deposit","sourceUrl":"https://www.rbf.gov.fj/wp-content/uploads/2026/10/2.9-Commercial-Banks-Time-Deposit-Rates.xlsx"},"dps":{"available":false,"localName":null,"note":"No standard monthly recurring deposit product is published by Fiji banks."},"sanchayapatra_5y":{"available":true,"localName":"Viti Bond","localNameEn":"Viti Bond (government retail bond)","note":"Sold by the RBF for the Government; 5, 7 and 10 years; tax-free interest.","sourceUrl":"https://www.rbf.gov.fj/wp-content/uploads/2026/08/FAQ-Viti-Bond-2026-2027.pdf"},"tbill_91d":{"available":true,"localName":"Treasury bill","localNameEn":"Government Treasury bill","note":"Issued by tender through the RBF; mainly bought by institutions.","sourceUrl":"https://www.rbf.gov.fj/wp-content/uploads/2026/10/4.1-Money-Capital-Markets-Interest-Rates-Yield-Rates.xlsx"},"tbond_5y":{"available":true,"localName":"Fiji Government Bond","localNameEn":"Fiji Infrastructure/Development Bond","sourceUrl":"https://www.rbf.gov.fj/download/720/september/52123/yield-curve-30-september-2026.xlsx"},"tbond_10y":{"available":true,"localName":"Fiji Government Bond","localNameEn":"Fiji Infrastructure/Development Bond","sourceUrl":"https://www.rbf.gov.fj/download/720/september/52123/yield-curve-30-september-2026.xlsx"},"equity_fund":{"available":true,"localName":"Unit trust","localNameEn":"Unit trust (mutual fund)","note":"Locally managed unit trusts invest in shares on the small local exchange and fixed income."},"gold":{"available":true,"localName":"Gold","localNameEn":"Gold jewellery and bullion","note":"No legal restriction on buying gold; mainly sold as jewellery."}},"institutions":{"centralBank":{"name":"Reserve Bank of Fiji","url":"https://www.rbf.gov.fj/"},"insuranceRegulator":{"name":"Reserve Bank of Fiji (insurance supervision)","url":"https://www.rbf.gov.fj/"},"insuranceComplaints":{"name":"Reserve Bank of Fiji complaints management","url":"https://www.rbf.gov.fj/core-functions/financial-system-development/complaints-management-and-market-conduct/"},"pensionScheme":{"name":"Fiji National Provident Fund (FNPF)","url":"https://www.myfnpf.com.fj/"},"oldAgeAllowance":{"name":"Social Pension Scheme, Ministry of Women, Children and Social Protection","url":"https://www.mwcsp.gov.fj/"},"publicHealthCover":{"name":"Ministry of Health and Medical Services (public hospitals)","url":"https://www.health.gov.fj/"},"depositInsurance":null,"statistics":{"name":"Fiji Bureau of Statistics","url":"https://www.statsfiji.gov.fj/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FJ', 1, 'bank_deposit_avg_rate', 0.0171, NULL, 'sourced', 'World Bank WDI FR.INR.DPST (deposit interest rate)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=FJ', '2024-12-31', 'RBF table 2.8 shows the weighted average time deposit rate at 2.01% and savings at 0.31% in August 2026; it has no combined average. Figure is for 2024 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FJ', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap on card interest was found; the only published card rate seen was one commercial bank''s posted rate, which this dataset does not cite (company page). RBF table 2.8 gives no card rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FJ', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched RBF, IMF and World Bank material: no deposit insurance scheme for Fiji was found, and no source stating its absence.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FJ', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched RBF rate tables and bank rate pages: Fiji banks do not publish a monthly recurring deposit (DPS-style) product rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FJ', 1, 'equity_return_base', 0.065, NULL, 'assumption', 'Viti Bond 5-year 3.00% tax-free; 1-year government yield 1.25%', 'https://www.rbf.gov.fj/wp-content/uploads/2026/08/FAQ-Viti-Bond-2026-2027.pdf', '2026-10-31', 'Safe tax-free rate of 3% plus a 3.5-point premium; the local market is thin, so the premium is kept below 4 points.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FJ', 1, 'equity_return_high', 0.09, NULL, 'assumption', 'Viti Bond 5-year 3.00% tax-free; 1-year government yield 1.25%', 'https://www.rbf.gov.fj/wp-content/uploads/2026/08/FAQ-Viti-Bond-2026-2027.pdf', '2026-10-31', 'High case if dividend yields and local listed-company growth hold up as in recent years.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FJ', 1, 'equity_return_low', 0.03, NULL, 'assumption', 'Viti Bond 5-year 3.00% tax-free; 1-year government yield 1.25%', 'https://www.rbf.gov.fj/wp-content/uploads/2026/08/FAQ-Viti-Bond-2026-2027.pdf', '2026-10-31', 'Low case near the tax-free Viti Bond rate, since the local exchange is small and illiquid.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FJ', 1, 'fdr_1y_rate', 0.0015, NULL, 'sourced', 'Reserve Bank of Fiji statistics table 2.9 (carded time deposit rates)', 'https://www.rbf.gov.fj/wp-content/uploads/2026/10/2.9-Commercial-Banks-Time-Deposit-Rates.xlsx', '2026-08-31', 'Carded 12-month rate range across banks 0.05-0.25%; midpoint used. Negotiated rates for large deposits run up to 3.55%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FJ', 1, 'fdr_3m_rate', 0.0015, NULL, 'sourced', 'Reserve Bank of Fiji statistics table 2.9 (carded time deposit rates)', 'https://www.rbf.gov.fj/wp-content/uploads/2026/10/2.9-Commercial-Banks-Time-Deposit-Rates.xlsx', '2026-08-31', 'Carded 3-month rate range across banks 0.05-0.25% in August 2026; midpoint used. Negotiated rates for large deposits run up to 2.69%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FJ', 1, 'fixed_income_return_base', 0.02, NULL, 'assumption', 'Viti Bond 5-year 3.00% tax-free; 1-year government yield 1.25%', 'https://www.rbf.gov.fj/wp-content/uploads/2026/08/FAQ-Viti-Bond-2026-2027.pdf', '2026-10-31', 'Base case: a mix of tax-free Viti Bonds (3%) and short government paper or deposits (0.3-1.25%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FJ', 1, 'fixed_income_return_high', 0.03, NULL, 'assumption', 'Viti Bond 5-year 3.00% tax-free; 1-year government yield 1.25%', 'https://www.rbf.gov.fj/wp-content/uploads/2026/08/FAQ-Viti-Bond-2026-2027.pdf', '2026-10-31', 'High case: all in tax-free 5-year Viti Bonds at 3%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FJ', 1, 'fixed_income_return_low', 0.0014, NULL, 'assumption', 'RBF carded 12-month deposit rate after 10% RIWT', 'https://www.rbf.gov.fj/wp-content/uploads/2026/10/2.9-Commercial-Banks-Time-Deposit-Rates.xlsx', '2026-10-31', 'Low case: carded 1-year deposit of about 0.15% less 10% withholding tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FJ', 1, 'goal_inflation_education', 0.04, NULL, 'assumption', 'RBF CPI table 7.1; headline CPI average', 'https://www.rbf.gov.fj/wp-content/uploads/2026/10/7.1-Consumer-Price-Index.xlsx', '2026-10-31', 'No separate education CPI is published in the RBF table, so we plan with headline projection plus half a point.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FJ', 1, 'goal_inflation_health', 0.045, NULL, 'assumption', 'RBF CPI table 7.1; headline CPI average', 'https://www.rbf.gov.fj/wp-content/uploads/2026/10/7.1-Consumer-Price-Index.xlsx', '2026-10-31', 'No separate medical CPI is published in the RBF table, so we plan with headline projection plus one point for private medical costs.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FJ', 1, 'gold_return_base', 0.05, NULL, 'assumption', 'World Bank PA.NUS.FCRF (FJD per USD broadly stable at 2.1-2.3 for a decade)', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=FJ', '2026-10-31', 'Long-run dollar gold trend of about 4-5% plus little expected FJD depreciation under the basket peg.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FJ', 1, 'gold_return_high', 0.08, NULL, 'assumption', 'World Bank PA.NUS.FCRF (FJD per USD broadly stable at 2.1-2.3 for a decade)', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=FJ', '2026-10-31', 'High case with strong dollar gold and some FJD weakening.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FJ', 1, 'gold_return_low', 0.02, NULL, 'assumption', 'World Bank PA.NUS.FCRF (FJD per USD broadly stable at 2.1-2.3 for a decade)', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=FJ', '2026-10-31', 'Low case for gold in FJD: weak dollar gold price and a stable peg-basket currency.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FJ', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No statutory gratuity or end-of-service payment for private employees was found (retirement savings run through FNPF), but no source read in this pass states its absence, so it is not marked absent.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FJ', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched for private hospital surgery costs in Suva: no published typical bill found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FJ', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'The only premium table found was one insurer''s own brochure, which this dataset does not cite (company source); no regulator or industry-wide premium guide was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FJ', 1, 'inflation_cpi', 0.068, NULL, 'sourced', 'Reserve Bank of Fiji statistics table 7.1 (Fiji Bureau of Statistics CPI)', 'https://www.rbf.gov.fj/wp-content/uploads/2026/10/7.1-Consumer-Price-Index.xlsx', '2026-09-30', 'Year-on-year CPI 6.8% in September 2026 (7.6% in August), driven by fuel prices; Trading Economics reports the same figure.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FJ', 1, 'inflation_projection', 0.035, NULL, 'assumption', 'RBF inflation objective (around 3%); RBF Press Release 23/2026 on elevated supply-driven inflation; CPI average 2022-2026', 'https://www.rbf.gov.fj/?p=51781', '2026-10-31', 'The RBF aims for inflation around 3% and the 2022-2026 average is roughly 3%, so we plan with 3.5% to allow for the import-price shocks seen in 2022 and 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FJ', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life is sold in Fiji, but no published per-1,000 premium rates by age were found; insurers quote individually.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FJ', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched RBF insurance annual reports and news: no industry-wide life claim settlement ratio is published.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FJ', 1, 'life_expectancy', 67.463, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=FJ', '2024-12-31', 'UN WPP 2024 (via populationpyramid.net) gives 67.8 for 2026. World Bank figure is for 2024 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FJ', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":15,"men":13.5,"women":16.4},{"age":65,"total":12,"men":10.8,"women":13.2},{"age":70,"total":9.4,"men":8.4,"women":10.4},{"age":80,"total":5.3,"men":4.7,"women":5.9}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/fiji/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there). Values are the UN WPP 2024 estimates for calendar 2026 (mid-year date used).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FJ', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":65,"womenAge":65,"over90Monthly":null,"meansTested":true}', 'sourced', 'Fijivillage: Social Pension Scheme eligibility clarified by the Ministry', 'https://www.fijivillage.com/news/sayed-khaiyum-raises-concerns-over-social-pension-cuts-kiran-clarifies-eligibility-87075d/', '2026-10-26', 'Ministry (26 October 2026): Fiji citizens aged 65 and over qualify if they do not receive an FNPF pension or other qualifying superannuation (a pension test, recorded as meansTested); the Ministry said asset tests belong to the separate Family Assistance Scheme. Higher rate from 70. 59,918 recipients in 2025-26.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FJ', 1, 'old_age_allowance_monthly', 115, NULL, 'sourced', 'Fiji Times: 2023-2024 Budget social welfare allowance increases', 'https://www.fijitimes.com.fj/?p=663261', '2023-08-01', 'Social Pension Scheme: FJD 115 a month at 65-69 and FJD 125 at 70+, effective August 2023 (announced 30 June 2023). Source is older than 2025: a later increase was reported but its amount could not be confirmed from a source read in this pass.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FJ', 1, 'oop_health_share', 0.0831, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=FJ', '2023-12-31', 'Figure is for 2023 (older than 2025); latest World Bank value.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FJ', 1, 'policy_rate', 0.0025, NULL, 'sourced', 'Reserve Bank of Fiji, Press Release No. 31/2026', 'https://www.rbf.gov.fj/press-release-no-31-rbf-monetary-policy-stance-remains-unchanged/', '2026-10-29', 'Overnight Policy Rate held at 0.25%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FJ', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":55,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'Fiji Sun: FNPF retirement withdrawal age stays at 55', 'https://fijisun.com.fj/news/nation/retirement-withdrawal-age-stays-at-55-dpm-prasad-clarifies', '2025-08-23', 'FNPF is a defined-contribution provident fund, not an indexed pension: lump sum or pension from the entitlement age of 55 (Fiji Sun, 23 August 2025). Members'' balances were credited 9.5% for 2026 (Fiji Sun, 26 June 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FJ', 1, 'retirement_accumulation_return_base', 0.06, NULL, 'assumption', 'FNPF credited 9.5% for 2026 (Fiji Sun, 26 June 2026); safe rates 1-4%', 'https://fijisun.com.fj/news/economy/fnpf-declares-95-interest-payout', '2026-10-31', 'Base case well below the recent 9.5% FNPF credit, allowing for a balanced mix and lower future credits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FJ', 1, 'retirement_accumulation_return_high', 0.08, NULL, 'assumption', 'FNPF credited 9.5% for 2026 (Fiji Sun, 26 June 2026); safe rates 1-4%', 'https://fijisun.com.fj/news/economy/fnpf-declares-95-interest-payout', '2026-10-31', 'High case near recent FNPF credited rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FJ', 1, 'retirement_accumulation_return_low', 0.035, NULL, 'assumption', 'FNPF credited 9.5% for 2026 (Fiji Sun, 26 June 2026); safe rates 1-4%', 'https://fijisun.com.fj/news/economy/fnpf-declares-95-interest-payout', '2026-10-31', 'Low case for a balanced mix if FNPF crediting rates fall back toward bond yields.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FJ', 1, 'retirement_age_default', 55, NULL, 'sourced', 'Fiji Sun: FNPF retirement withdrawal age stays at 55', 'https://fijisun.com.fj/news/nation/retirement-withdrawal-age-stays-at-55-dpm-prasad-clarifies', '2025-08-23', 'FNPF entitlement (full withdrawal) age is 55 for men and women, confirmed by the Finance Minister on 23 August 2025; there is no statutory private-sector retirement age. Applies equally to people born after 1975.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FJ', 1, 'retirement_age_government', 60, NULL, 'sourced', 'Fiji Times: civil service retirement age revised to 60', 'https://www.fijitimes.com.fj/?p=622432', '2023-01-01', 'Civil Service (General) (Amendment) Regulations 2023: retirement at 60, optional at 55; extensions to 62 for scarce-skill posts. Source is from January 2023 (older than 2025); no later change was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FJ', 1, 'retirement_return_base', 0.0125, NULL, 'assumption', 'RBF government yield curve 30 Sep 2026 (1-year 1.25%)', 'https://www.rbf.gov.fj/download/720/september/52123/yield-curve-30-september-2026.xlsx', '2026-10-31', 'Base case capped at the 1-year government yield, the best safe 1-year rate available.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FJ', 1, 'retirement_return_high', 0.03, NULL, 'assumption', 'Viti Bond 5-year 3.00% tax-free; 1-year government yield 1.25%', 'https://www.rbf.gov.fj/wp-content/uploads/2026/08/FAQ-Viti-Bond-2026-2027.pdf', '2026-10-31', 'High case: laddered tax-free Viti Bonds at 3%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FJ', 1, 'retirement_return_low', 0.005, NULL, 'assumption', 'RBF government yield curve 30 Sep 2026 (3-month 0.30%, 1-year 1.25%)', 'https://www.rbf.gov.fj/download/720/september/52123/yield-curve-30-september-2026.xlsx', '2026-10-31', 'Low case: short government paper and deposits after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FJ', 1, 'sanchayapatra_5y_rate', 0.03, NULL, 'sourced', 'Reserve Bank of Fiji, Viti Bond 2026-2027 FAQ', 'https://www.rbf.gov.fj/wp-content/uploads/2026/08/FAQ-Viti-Bond-2026-2027.pdf', '2026-08-10', 'Viti Bond (government retail bond) 5-year coupon 3.00% (7-year 3.50%, 10-year 4.00%); FJD 1,000 to 200,000 per fiscal year; interest paid quarterly.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FJ', 1, 'savings_account_rate', 0.0031, NULL, 'sourced', 'Reserve Bank of Fiji statistics table 2.8 (commercial banks'' savings deposit rate)', 'https://www.rbf.gov.fj/wp-content/uploads/2026/10/2.8-Commercial-Banks-Lending-and-Deposit-Rates.xlsx', '2026-08-31', 'Weighted average savings deposit rate 0.31% in August 2026 (RBF table 2.8).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FJ', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":10},{"year":2040,"value":8.2},{"year":2065,"value":4.9}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/fiji/2040/', '2025-12-31', '100 / old-age dependency ratio: 9.97 (2025, World Bank), 12.2 (2040) and 20.4 (2065, populationpyramid.net/fiji/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FJ', 1, 'tax_bank_interest', 0.1, NULL, 'sourced', 'Fiji Revenue and Customs Service, Resident Interest Withholding Tax', 'https://frcs.org.fj/?p=29315', '2026-04-29', '10% final withholding tax; individuals with gross income up to FJD 30,000 and eligible pensioners can apply for exemption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FJ', 1, 'tax_sanchayapatra_profit', 0, NULL, 'sourced', 'Reserve Bank of Fiji, Viti Bond 2026-2027 FAQ', 'https://www.rbf.gov.fj/wp-content/uploads/2026/08/FAQ-Viti-Bond-2026-2027.pdf', '2026-08-10', 'Interest on Viti Bonds is exempt from income tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FJ', 1, 'tbill_91d_rate', 0.0025, NULL, 'sourced', 'Reserve Bank of Fiji statistics table 4.1 (Treasury bill 91-day rate)', 'https://www.rbf.gov.fj/wp-content/uploads/2026/10/4.1-Money-Capital-Markets-Interest-Rates-Yield-Rates.xlsx', '2026-08-31', '91-day Treasury bill tender rate 0.25% in August 2026; the 30 September 2026 government yield curve shows 0.30% at 3 months.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FJ', 1, 'tbond_10y_rate', 0.039, NULL, 'sourced', 'Reserve Bank of Fiji government yield curve, 30 September 2026', 'https://www.rbf.gov.fj/download/720/september/52123/yield-curve-30-september-2026.xlsx', '2026-09-30', NULL, 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FJ', 1, 'tbond_5y_rate', 0.0206, NULL, 'sourced', 'Reserve Bank of Fiji government yield curve, 30 September 2026', 'https://www.rbf.gov.fj/download/720/september/52123/yield-curve-30-september-2026.xlsx', '2026-09-30', NULL, 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('FM', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"FM","iso3":"FSM","nameEn":"Micronesia","nameNative":"Federated States of Micronesia","region":"east_asia_pacific","languages":["chk","en","pon","kos","yap"],"currency":{"code":"USD","symbol":"$","decimals":2,"compact":"intl","usdRate":{"value":1,"status":"sourced","sourceName":"World Bank WDI, official exchange rate (PA.NUS.FCRF)","sourceUrl":"https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=FM","asOf":"2025-12-31","note":"The US dollar is the official currency of the FSM."}},"instruments":{"savings_account":{"available":true,"localName":null,"localNameEn":"Savings account"},"fdr_3m":{"available":true,"localName":null,"localNameEn":"Time deposit","note":"Offered by banks in the FSM; no published rate found."},"fdr_1y":{"available":true,"localName":null,"localNameEn":"Time deposit","note":"Offered by banks in the FSM; no published rate found."},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No monthly recurring deposit scheme found."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate or retail savings bond."},"tbill_91d":{"available":false,"localName":null,"localNameEn":null,"note":"The FSM government issues no treasury bills."},"tbond_5y":{"available":false,"localName":null,"localNameEn":null,"note":"The FSM government issues no bonds."},"tbond_10y":{"available":false,"localName":null,"localNameEn":null,"note":"The FSM government issues no bonds."},"equity_fund":{"available":false,"localName":null,"localNameEn":null,"note":"No local stock exchange or locally offered retail funds; global funds are only reachable through overseas accounts."},"gold":{"available":true,"localName":null,"localNameEn":"Gold","note":"Legal to hold, but there is no local bullion market; gold is mostly bought abroad."}},"institutions":{"centralBank":null,"insuranceRegulator":null,"insuranceComplaints":null,"pensionScheme":{"name":"FSM Social Security Administration (FSMSSA)","url":"https://www.fsmssa.fm/"},"oldAgeAllowance":null,"publicHealthCover":{"name":"FSM Department of Health and Social Affairs (public hospitals; MiCare plan for public employees)","url":"https://hsa.gov.fm/"},"depositInsurance":{"name":"Federal Deposit Insurance Corporation (FDIC)","url":"https://www.fdic.gov/resources/deposit-insurance","note":"Banks operating in the FSM are FDIC-insured."},"statistics":{"name":"FSM Statistics Office","url":"https://www.fsmstats.fm/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FM', 1, 'bank_deposit_avg_rate', 0.0058, NULL, 'sourced', 'FDIC call report data (Statistics on Depository Institutions), interest on deposits / total deposits of the commercial bank chartered in the FSM', 'https://api.fdic.gov/banks/financials?filters=CERT:26539&fields=REPDTE,DEP,EDEPDOM&sort_by=REPDTE&sort_order=DESC', '2025-12-31', 'US$1.38 million of interest expense on about US$236 million of deposits in 2025 (about 0.58%; 0.74 million on 245 million in the first half of 2026); computed by us from FDIC data. World Bank FR.INR.DPST shows 0.04% for 2021 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FM', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap or published typical credit card rate found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FM', 1, 'deposit_insurance_limit', 250000, NULL, 'sourced', 'FDIC standard deposit insurance amount; FDIC institution data lists the banks operating in the FSM as FDIC-insured', 'https://www.fdic.gov/resources/deposit-insurance', '2026-10-31', 'Both commercial banks with branches in the FSM are FDIC-insured (FDIC BankFind data, state code FM), so deposits are covered up to US$250,000 per depositor per bank per ownership category.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FM', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No monthly recurring deposit product or rate found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FM', 1, 'equity_return_base', 0.045, NULL, 'assumption', 'Average deposit rate (0.58%) plus a 4-point equity premium; global index in US dollars', 'https://api.fdic.gov/banks/financials?filters=CERT:26539&fields=REPDTE,DEP,EDEPDOM&sort_by=REPDTE&sort_order=DESC', '2026-10-31', 'There is no stock market in the FSM, so equity means a global index in US dollars, capped at the safe deposit rate plus 4 points.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FM', 1, 'equity_return_high', 0.08, NULL, 'assumption', 'Long-run global equity returns in US dollars', 'https://api.fdic.gov/banks/financials?filters=CERT:26539&fields=REPDTE,DEP,EDEPDOM&sort_by=REPDTE&sort_order=DESC', '2026-10-31', 'High case close to the long-run nominal return of global equities in dollars.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FM', 1, 'equity_return_low', 0.02, NULL, 'assumption', 'No local stock market; global equity index in US dollars', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=FM', '2026-10-31', 'Low case for a global index fund held in dollars over a weak decade.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FM', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published 1-year time deposit rate found for banks in the FSM.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FM', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published 3-month time deposit rate found for banks in the FSM.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FM', 1, 'fixed_income_return_base', 0.005, NULL, 'assumption', 'Average interest paid on deposits (FDIC call reports)', 'https://api.fdic.gov/banks/financials?filters=CERT:26539&fields=REPDTE,DEP,EDEPDOM&sort_by=REPDTE&sort_order=DESC', '2026-10-31', 'Base case just under the 0.58% average paid on deposits. Safe USD rates in the FSM: no treasury bills or savings bonds are issued; interest paid on deposits at the FSM-chartered bank averaged about 0.58% in 2025 (FDIC call reports); no tax on interest found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FM', 1, 'fixed_income_return_high', 0.01, NULL, 'assumption', 'Average interest paid on deposits (FDIC call reports)', 'https://api.fdic.gov/banks/financials?filters=CERT:26539&fields=REPDTE,DEP,EDEPDOM&sort_by=REPDTE&sort_order=DESC', '2026-10-31', 'High case for longer time deposits on larger balances. Safe USD rates in the FSM: no treasury bills or savings bonds are issued; interest paid on deposits at the FSM-chartered bank averaged about 0.58% in 2025 (FDIC call reports); no tax on interest found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FM', 1, 'fixed_income_return_low', 0.002, NULL, 'assumption', 'Average interest paid on deposits (FDIC call reports)', 'https://api.fdic.gov/banks/financials?filters=CERT:26539&fields=REPDTE,DEP,EDEPDOM&sort_by=REPDTE&sort_order=DESC', '2026-10-31', 'Low case near savings-account rates. Safe USD rates in the FSM: no treasury bills or savings bonds are issued; interest paid on deposits at the FSM-chartered bank averaged about 0.58% in 2025 (FDIC call reports); no tax on interest found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FM', 1, 'goal_inflation_education', 0.04, NULL, 'assumption', 'IMF WEO CPI; no published education CPI', 'https://www.imf.org/external/datamapper/PCPIPCH@WEO/FSM', '2026-10-31', 'No education price index is published, so we plan one point above general inflation, as for US-priced tuition.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FM', 1, 'goal_inflation_health', 0.04, NULL, 'assumption', 'IMF WEO CPI; no published medical CPI', 'https://www.imf.org/external/datamapper/PCPIPCH@WEO/FSM', '2026-10-31', 'No health price index is published, so we plan one point above general inflation for medical costs, including off-island referrals.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FM', 1, 'gold_return_base', 0.04, NULL, 'assumption', 'US-dollar gold price trend; the FSM uses the US dollar', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=FM', '2026-10-31', 'Long-run dollar gold trend of about 4% a year, with no exchange-rate effect because the US dollar is the local currency.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FM', 1, 'gold_return_high', 0.08, NULL, 'assumption', 'US-dollar gold price trend; the FSM uses the US dollar', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=FM', '2026-10-31', 'High case for a strong gold cycle.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FM', 1, 'gold_return_low', 0.01, NULL, 'assumption', 'US-dollar gold price trend; the FSM uses the US dollar', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=FM', '2026-10-31', 'Gold can stall for a decade in dollar terms and there is no currency depreciation to add.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FM', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No statutory gratuity or severance law for private employees found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FM', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a major hospital stay found; serious cases are often referred off-island.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FM', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premiums by age found; the MiCare plan page was not reachable (expired certificate).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FM', 1, 'inflation_cpi', 0.028, NULL, 'sourced', 'IMF World Economic Outlook (October 2026 database), CPI inflation, average', 'https://www.imf.org/external/datamapper/PCPIPCH@WEO/FSM', '2025-12-31', '2.8% for 2025 (5.4% in 2024); IMF forecasts 3.2% for 2026. Annual figure; the national statistics site was not reachable. Also in the IMF DataMapper API (PCPIPCH/FSM).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FM', 1, 'inflation_projection', 0.03, NULL, 'assumption', 'US dollar economy (Federal Reserve 2% target); IMF WEO 5-year CPI average', 'https://www.imf.org/external/datamapper/PCPIPCH@WEO/FSM', '2026-10-31', 'The FSM uses the US dollar; CPI averaged about 4.2% in 2021-2025 because of imported food and fuel, and the IMF expects 2-3% later, so we plan with 3%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FM', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published term life premium rates or premium guides for the FSM found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FM', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No insurance regulator publication with a claim settlement ratio found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FM', 1, 'life_expectancy', 67.4, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN)', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=FM', '2024-12-31', 'Men 63.6, women 71.3 (2024).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FM', 1, 'life_table_remaining', NULL, NULL, 'missing', '', '', '2026-10-31', 'No life table by age found for the FSM (georank.org has no FSM page; the WHO GHO API was unavailable).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FM', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FM', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension found; the Department of Health and Social Affairs lists elderly services but no cash allowance.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FM', 1, 'oop_health_share', 0.0258, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure, SH.XPD.OOPC.CH.ZS)', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=FM', '2023-12-31', '2.6% in 2023; public and donor-funded care covers most costs.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FM', 1, 'policy_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The FSM has no central bank or monetary policy of its own; it uses the US dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FM', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":65,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'FSM Social Security Administration, benefits', 'https://www.fsmssa.fm/benefits', '2026-10-31', 'Compulsory FSM Social Security: 100% of benefits at 65 (subject to an earnings test) or 50% from 60 without it; needs at least 50 quarters of coverage and US$2,500 of contributions; annual benefit 16.5% of the first US$10,000 of cumulative covered earnings, 3% of the next US$30,000, 2% of the next US$262,500 and 1% above, divided by 12; minimum US$100 a month. The benefits page describes no cost-of-living adjustment, so inflationLinked is false.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FM', 1, 'retirement_accumulation_return_base', 0.025, NULL, 'assumption', 'Mix of US-dollar deposits and a global equity index', 'https://api.fdic.gov/banks/financials?filters=CERT:26539&fields=REPDTE,DEP,EDEPDOM&sort_by=REPDTE&sort_order=DESC', '2026-10-31', 'About half global equity at 4.5% and half deposits at 0.5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FM', 1, 'retirement_accumulation_return_high', 0.05, NULL, 'assumption', 'Mix of US-dollar deposits and a global equity index', 'https://api.fdic.gov/banks/financials?filters=CERT:26539&fields=REPDTE,DEP,EDEPDOM&sort_by=REPDTE&sort_order=DESC', '2026-10-31', 'About 60% global equity at the high case and 40% deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FM', 1, 'retirement_accumulation_return_low', 0.01, NULL, 'assumption', 'Mix of US-dollar deposits and a global equity index', 'https://api.fdic.gov/banks/financials?filters=CERT:26539&fields=REPDTE,DEP,EDEPDOM&sort_by=REPDTE&sort_order=DESC', '2026-10-31', 'About 40% global equity at the low case, 60% deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FM', 1, 'retirement_age_default', 65, NULL, 'sourced', 'FSM Social Security Administration, retirement benefits', 'https://www.fsmssa.fm/benefits', '2026-10-31', 'Full old-age benefit at 65; a reduced benefit (50%) can be taken from 60. Same for men and women.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FM', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'No mandatory retirement age for FSM national government employees found; public employees are covered by the same Social Security scheme.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FM', 1, 'retirement_return_base', 0.005, NULL, 'assumption', 'Average interest paid on deposits (FDIC call reports)', 'https://api.fdic.gov/banks/financials?filters=CERT:26539&fields=REPDTE,DEP,EDEPDOM&sort_by=REPDTE&sort_order=DESC', '2026-10-31', 'Base case just under the 0.58% average paid on deposits, the only local safe rate. Safe USD rates in the FSM: no treasury bills or savings bonds are issued; interest paid on deposits at the FSM-chartered bank averaged about 0.58% in 2025 (FDIC call reports); no tax on interest found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FM', 1, 'retirement_return_high', 0.01, NULL, 'assumption', 'Average interest paid on deposits (FDIC call reports)', 'https://api.fdic.gov/banks/financials?filters=CERT:26539&fields=REPDTE,DEP,EDEPDOM&sort_by=REPDTE&sort_order=DESC', '2026-10-31', 'High case for longer time deposits on larger balances. Safe USD rates in the FSM: no treasury bills or savings bonds are issued; interest paid on deposits at the FSM-chartered bank averaged about 0.58% in 2025 (FDIC call reports); no tax on interest found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FM', 1, 'retirement_return_low', 0.002, NULL, 'assumption', 'Average interest paid on deposits (FDIC call reports)', 'https://api.fdic.gov/banks/financials?filters=CERT:26539&fields=REPDTE,DEP,EDEPDOM&sort_by=REPDTE&sort_order=DESC', '2026-10-31', 'Low case near savings-account rates. Safe USD rates in the FSM: no treasury bills or savings bonds are issued; interest paid on deposits at the FSM-chartered bank averaged about 0.58% in 2025 (FDIC call reports); no tax on interest found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FM', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The FSM government sells no savings certificates or retail savings bonds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FM', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Bank deposit rate pages for the FSM were not reachable; see bank_deposit_avg_rate for the average paid on deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FM', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":10.1},{"year":2040,"value":8.6},{"year":2065,"value":5.9}]}', 'sourced', 'UN World Population Prospects 2024, medium variant (via populationpyramid.net); World Bank SP.POP.DPND.OL', 'https://www.populationpyramid.net/micronesia-fed-states-of/2040/', '2024-07-31', '100 / old-age dependency ratio: OADR 9.9 in 2025 (World Bank SP.POP.DPND.OL), 11.6 in 2040 and 16.9 in 2065 (UN WPP 2024 medium variant via populationpyramid.net).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FM', 1, 'tax_bank_interest', NULL, NULL, 'missing', '', '', '2026-10-31', 'FSM national taxes are on wages and business gross revenue; we could not read an official page confirming the treatment of individuals'' interest income (the Department of Finance tax pages give no detail).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FM', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate exists.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FM', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The FSM government issues no treasury bills.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FM', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The FSM government issues no tradable bonds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FM', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The FSM government issues no tradable bonds.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('FR', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"FR","iso3":"FRA","nameEn":"France","nameNative":"France","region":"europe_central_asia","languages":["fr","en","es","de","oc"],"currency":{"code":"EUR","symbol":"€","decimals":2,"compact":"intl","usdRate":{"value":0.8951,"status":"sourced","sourceName":"European Central Bank euro reference rate (USD)","sourceUrl":"https://data-api.ecb.europa.eu/service/data/EXR/D.USD.EUR.SP00.A","asOf":"2026-10-30","note":"EUR 1 = USD 1.1172 on 30 October 2026, so about EUR 0.895 per US dollar; World Bank 2025 average 0.885."}},"instruments":{"savings_account":{"available":true,"localName":"Livret A","localNameEn":"Regulated tax-free savings passbook","note":"Also LDDS and, for low incomes, LEP; ordinary bank savings accounts (livrets bancaires) exist too.","sourceUrl":"https://www.service-public.gouv.fr/particuliers/vosdroits/F2365"},"fdr_3m":{"available":true,"localName":"Compte à terme","localNameEn":"Term deposit (3 months)"},"fdr_1y":{"available":true,"localName":"Compte à terme","localNameEn":"Term deposit (1 year)","sourceUrl":"https://data-api.ecb.europa.eu/service/data/MIR/M.FR.B.L22.F.R.A.2250.EUR.N"},"dps":{"available":true,"localName":"Plan d''épargne logement (PEL)","localNameEn":"Home savings plan","note":"Regular deposits of at least EUR 540 a year for 4-10 years at a rate fixed when opened.","sourceUrl":"https://www.service-public.gouv.fr/particuliers/vosdroits/F16140"},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate or retail savings bond for individuals."},"tbill_91d":{"available":true,"localName":"Bons du Trésor à taux fixe (BTF)","localNameEn":"French Treasury bills","note":"Auctioned by Agence France Trésor mainly to institutions.","sourceUrl":"https://tradingeconomics.com/france/government-bond-yield"},"tbond_5y":{"available":true,"localName":"Obligation assimilable du Trésor (OAT)","localNameEn":"French government bond"},"tbond_10y":{"available":true,"localName":"Obligation assimilable du Trésor (OAT)","localNameEn":"French government bond","sourceUrl":"https://tradingeconomics.com/france/government-bond-yield"},"equity_fund":{"available":true,"localName":"OPCVM et fonds indiciels (ETF)","localNameEn":"Mutual funds and index funds (ETF)","note":"Can be held in a tax-advantaged PEA (plan d''épargne en actions) or in assurance-vie unit-linked contracts."},"gold":{"available":true,"localName":"Lingots et pièces d''or","localNameEn":"Gold bars and coins","note":"Legal to buy; sales are taxed under a flat tax on precious metals or as a capital gain."}},"institutions":{"centralBank":{"name":"Banque de France","url":"https://www.banque-france.fr/","note":"Part of the Eurosystem; monetary policy set by the European Central Bank."},"insuranceRegulator":{"name":"Autorité de contrôle prudentiel et de résolution (ACPR)","url":"https://acpr.banque-france.fr/"},"insuranceComplaints":{"name":"La Médiation de l''Assurance","url":"https://www.mediation-assurance.org/","note":"Free insurance ombudsman once the insurer''s own complaints service has answered."},"pensionScheme":{"name":"L''Assurance retraite (CNAV, basic pension)","url":"https://www.lassuranceretraite.fr/"},"oldAgeAllowance":{"name":"Allocation de solidarité aux personnes âgées (ASPA)","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F16871"},"publicHealthCover":{"name":"Assurance Maladie","url":"https://www.ameli.fr/"},"depositInsurance":{"name":"Fonds de Garantie des Dépôts et de Résolution (FGDR)","url":"https://www.garantiedesdepots.fr/"},"statistics":{"name":"Institut national de la statistique et des études économiques (INSEE)","url":"https://www.insee.fr/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FR', 1, 'bank_deposit_avg_rate', 0.0255, NULL, 'sourced', 'ECB MFI interest rate statistics: French banks, household deposits with agreed maturity (outstanding amounts)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.FR.B.L22.A.R.A.2250.EUR.O', '2026-09-30', 'Average rate on all outstanding household term deposits, September 2026 (2.52% in August); World Bank FR.INR.DPST for France stops in 2017 (0.79%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FR', 1, 'credit_card_rate_cap', 0.0729, NULL, 'sourced', 'ECB MFI interest rate statistics: French banks, revolving loans, overdrafts and credit card credit to households', 'https://data-api.ecb.europa.eu/service/data/MIR/M.FR.B.A2Z.A.R.A.2250.EUR.N', '2026-09-30', 'Average rate on revolving loans, overdrafts and extended credit card credit combined, September 2026 (no card-only series); French law also caps consumer credit at the quarterly usury rate (taux d''usure) set by the Banque de France, which could not be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FR', 1, 'deposit_insurance_limit', 100000, NULL, 'sourced', 'Fonds de Garantie des Dépôts et de Résolution (FGDR)', 'https://www.garantiedesdepots.fr/fr/connaitre-mes-garanties/je-detiens-des-comptes-et-des-livrets-bancaires-quelles-sont-mes-garanties', '2026-10-31', 'EUR 100,000 per client per bank; state-guaranteed regulated passbooks (Livret A, LDDS, LEP) carry a separate EUR 100,000 guarantee; exceptional deposits (e.g. a home sale) raise the limit for three months.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FR', 1, 'dps_rate', 0.02, NULL, 'sourced', 'Service-Public.fr, Plan d''épargne logement (PEL)', 'https://www.service-public.gouv.fr/particuliers/vosdroits/F16140', '2026-01-01', 'PEL opened in 2026: fixed 2.00% gross for the life of the plan, minimum EUR 540 a year in periodic deposits (e.g. EUR 45 a month), at least 4 years, up to 10; Service-Public states PEL interest bears the 30% flat tax (12.8% income tax plus 17.2% social charges).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FR', 1, 'equity_return_base', 0.055, NULL, 'assumption', 'CAC 40 price index (Trading Economics); Livret A 1.7% tax-free; 3-month BTF 2.79% less 31.4% flat tax = 1.9%', 'https://tradingeconomics.com/france/stock-market', '2026-10-31', 'The CAC 40 has a solid 10-year record (about 4,500 in late 2016 to 7,969), but the base is held to the after-tax safe rate plus about 4 points.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FR', 1, 'equity_return_high', 0.075, NULL, 'assumption', 'CAC 40 price index (Trading Economics); long-run global equity returns', 'https://tradingeconomics.com/france/stock-market', '2026-10-31', 'High case: a diversified euro equity fund held in a PEA matching long-run global equity returns of about 7-8% in euros.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FR', 1, 'equity_return_low', 0.03, NULL, 'assumption', 'CAC 40 7,969 on 30 Oct 2026, down 1.9% in a year (Trading Economics); after-tax safe rate about 1.7%', 'https://tradingeconomics.com/france/stock-market', '2026-10-31', 'Low case: French shares earn little more than safe savings over a long period, as in 2000-2015.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FR', 1, 'fdr_1y_rate', 0.0254, NULL, 'sourced', 'ECB MFI interest rate statistics: French banks, household deposits with agreed maturity up to 1 year (new business)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.FR.B.L22.F.R.A.2250.EUR.N', '2026-09-30', 'Bucket covers all fixed terms up to one year (new business, September 2026; 2.36% in August).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FR', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'ECB/Banque de France MFI statistics publish household deposits with agreed maturity up to 1 year as one bucket (2.54% in September 2026); no official 3-month term deposit (compte à terme) rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FR', 1, 'fixed_income_return_base', 0.017, NULL, 'assumption', 'Livret A 1.7% tax-free; 1-year deposits 2.54% (Sep 2026) less 31.4% flat tax = 1.7%', 'https://www.service-public.gouv.fr/particuliers/vosdroits/F2365', '2026-10-31', 'Base case: the tax-free Livret A rate, close to the after-tax 1-year term deposit.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FR', 1, 'fixed_income_return_high', 0.03, NULL, 'assumption', 'France 10-year OAT 4.97% less 31.4% flat tax = 3.4% (Trading Economics)', 'https://tradingeconomics.com/france/government-bond-yield', '2026-10-31', 'High case: holding long government bonds after tax, slightly below today''s unusually high 10-year yield.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FR', 1, 'fixed_income_return_low', 0.014, NULL, 'assumption', 'Livret A 1.7% tax-free (Service-Public.fr); rate set by formula from inflation and short-term rates', 'https://www.service-public.gouv.fr/particuliers/vosdroits/F2365', '2026-10-31', 'Low case: regulated passbook rates drift lower as inflation eases.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FR', 1, 'goal_inflation_education', 0.035, NULL, 'assumption', 'Eurostat/ECB HICP France, education: 3.0% year on year in December 2025', 'https://data-api.ecb.europa.eu/service/data/ICP/M.FR.N.100000.4.ANR', '2026-10-31', 'Public schooling is free; private schooling and higher-education fees have risen faster than headline inflation, so 3.5% is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FR', 1, 'goal_inflation_health', 0.03, NULL, 'assumption', 'Eurostat/ECB HICP France, health: 0.0% year on year in December 2025', 'https://data-api.ecb.europa.eu/service/data/ICP/M.FR.N.060000.4.ANR', '2026-10-31', 'Regulated health prices in France have risen slower than headline inflation, but private fees and mutuelle premiums rise faster, so 3% is used for planning.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FR', 1, 'gold_return_base', 0.04, NULL, 'assumption', 'Gold price history (Trading Economics); ECB 2% inflation target', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Base case: dollar gold rises roughly with world inflation plus a little, and the euro is assumed stable against the dollar over the long run.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FR', 1, 'gold_return_high', 0.07, NULL, 'assumption', 'Gold price history (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'High case: a repeat of gold''s strong 2005-2025 trend in euro terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FR', 1, 'gold_return_low', 0.01, NULL, 'assumption', 'Gold USD 3,876/oz on 30 Oct 2026, 31% below the January 2026 high (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Low case: gold barely keeps up after the 2025-26 spike, with no help from the euro.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FR', 1, 'gratuity_rule', NULL, '{"daysPerYear":7.5,"daysPerYearAfter":10,"afterYears":10,"daysPerMonth":30}', 'sourced', 'Service-Public.fr, indemnité légale de licenciement', 'https://www.service-public.gouv.fr/particuliers/vosdroits/F987', '2026-10-31', 'Statutory severance on dismissal after 8 months'' service: 1/4 of a month''s pay per year for the first 10 years and 1/3 of a month per year beyond; not paid on resignation (a smaller retirement indemnity applies on voluntary retirement). Collective agreements may pay more.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FR', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'Hospital care is largely covered by Assurance Maladie plus a complementary mutuelle; the patient pays a daily hospital charge (forfait journalier) and private-clinic extra fees, but no official figure for a typical out-of-pocket cost of a major stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FR', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Complementary health cover (mutuelle) is priced per person by age and benefit level, not per sum insured, and no published premium table per EUR 100,000 of cover was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FR', 1, 'inflation_cpi', 0.034, NULL, 'sourced', 'Trading Economics (INSEE CPI, October 2026 provisional estimate)', 'https://tradingeconomics.com/france/inflation-cpi', '2026-10-31', 'INSEE flash estimate published 30 October 2026: CPI up 3.4% year on year (3.1% in September); secondary source because insee.fr series pages returned no data. World Bank 2025 average 0.9%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FR', 1, 'inflation_projection', 0.022, NULL, 'assumption', 'ECB 2% medium-term target; French CPI 3.4% (Oct 2026) after 0.9% in 2025 (World Bank)', 'https://tradingeconomics.com/france/inflation-cpi', '2026-10-31', 'The ECB 2% target is credible over the long run and French inflation averaged close to it over five years, but the 2026 rebound argues for a small margin, so 2.2% is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FR', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life (assurance temporaire décès) is widely sold, but no published premium table per EUR 1,000 of cover by age was found; comparison sites were not read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FR', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The ACPR and France Assureurs do not publish an industry-wide life claim settlement ratio that could be found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FR', 1, 'life_expectancy', 83.7, NULL, 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/france', '2026-07-01', 'Men 80.9, women 86.4 (UN WPP estimate for 2026); World Bank 2024 figure 83.0.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FR', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":26.4,"men":24.2,"women":28.4},{"age":65,"total":22.3,"men":20.4,"women":24},{"age":70,"total":18.3,"men":16.6,"women":19.7},{"age":80,"total":10.7,"men":9.5,"women":11.6}]}', 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/france', '2026-07-01', 'Remaining years computed from georank''s expected age at death by current age (UN WPP 2026 estimate, mid-year).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FR', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":65,"womenAge":65,"over90Monthly":null,"meansTested":true}', 'sourced', 'Service-Public.fr, ASPA', 'https://www.service-public.gouv.fr/particuliers/vosdroits/F16871', '2026-01-01', 'From 65 (62 for long-career or disability early retirees); requires stable residence in France and, for most foreign nationals, 10 years of residence permits allowing work.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FR', 1, 'old_age_allowance_monthly', 1043.59, NULL, 'sourced', 'Service-Public.fr, Allocation de solidarité aux personnes âgées (ASPA)', 'https://www.service-public.gouv.fr/particuliers/vosdroits/F16871', '2026-01-01', 'Means-tested minimum old-age income: tops total resources up to EUR 1,043.59 gross a month for a single person (EUR 1,620.18 for a couple both receiving it); may be recovered from estates above a threshold.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FR', 1, 'oop_health_share', 0.0923, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=FR', '2024-12-31', 'Latest World Bank figure is for 2024 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FR', 1, 'policy_rate', 0.025, NULL, 'sourced', 'European Central Bank, key ECB interest rates (deposit facility)', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.en.html', '2026-09-16', 'France uses the euro; ECB deposit facility rate 2.50% (main refinancing 2.65%) since 16 September 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FR', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":64,"nomineeUntilAge":null,"inflationLinked":true,"taxFree":false}', 'sourced', 'Service-Public.fr, calcul de la retraite de base (Assurance retraite)', 'https://www.service-public.gouv.fr/particuliers/vosdroits/F21552', '2026-10-31', 'Compulsory basic pension: 50% of the average of the best 25 years'' pay (capped; EUR 2,002.50 a month maximum in 2026) at full rate, plus the compulsory Agirc-Arrco points scheme; pensions are revalued each 1 January by average CPI excluding tobacco and are taxed as income.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FR', 1, 'retirement_accumulation_return_base', 0.035, NULL, 'assumption', 'Livret A 1.7%; equity base 5.5%', 'https://www.service-public.gouv.fr/particuliers/vosdroits/F2365', '2026-10-31', 'Base case: roughly half shares at 5.5% and half safe fixed income at about 1.7-3% after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FR', 1, 'retirement_accumulation_return_high', 0.05, NULL, 'assumption', 'After-tax 10-year OAT 3.4%; equity high 7.5%', 'https://tradingeconomics.com/france/government-bond-yield', '2026-10-31', 'High case for a growth-leaning balanced mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FR', 1, 'retirement_accumulation_return_low', 0.025, NULL, 'assumption', 'Livret A 1.7%; CAC 40 record (Trading Economics)', 'https://www.service-public.gouv.fr/particuliers/vosdroits/F2365', '2026-10-31', 'Low case for a balanced mix if shares lag.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FR', 1, 'retirement_age_default', 64, NULL, 'sourced', 'Service-Public.fr, âge minimum de départ à la retraite', 'https://www.service-public.gouv.fr/particuliers/vosdroits/F14043', '2026-08-14', 'Minimum pension age 64 for people born from 1969; 62 years 9 months for those born January 1963 to March 1965 (age frozen while the 2023 reform is suspended), 63 to 63 years 9 months for 1965-1968. Full rate is automatic at 67.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FR', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'Sedentary civil servants follow the same minimum pension age as private workers, but no official page stating the civil-service ages (including the age limit) could be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FR', 1, 'retirement_return_base', 0.017, NULL, 'assumption', 'Livret A 1.7% tax-free; 1-year deposits 2.54% (Sep 2026) less 31.4% flat tax = 1.7%', 'https://www.service-public.gouv.fr/particuliers/vosdroits/F2365', '2026-10-31', 'Base case capped at the tax-free Livret A rate, equal to the after-tax 1-year deposit (1.74%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FR', 1, 'retirement_return_high', 0.028, NULL, 'assumption', 'France 10-year OAT 4.97% less 31.4% flat tax = 3.4% (Trading Economics)', 'https://tradingeconomics.com/france/government-bond-yield', '2026-10-31', 'High case: a ladder of longer government bonds or euro-fund life insurance after tax, below the current 10-year yield.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FR', 1, 'retirement_return_low', 0.014, NULL, 'assumption', 'Livret A 1.7% tax-free (Service-Public.fr)', 'https://www.service-public.gouv.fr/particuliers/vosdroits/F2365', '2026-10-31', 'Low case: regulated passbooks and short deposits after a fall in rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FR', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'France sells no government savings certificate or retail savings bond to individuals; state-regulated passbooks (Livret A, LDDS, LEP) fill that role.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FR', 1, 'savings_account_rate', 0.017, NULL, 'sourced', 'Service-Public.fr, Livret A', 'https://www.service-public.gouv.fr/particuliers/vosdroits/F2365', '2026-08-01', 'Livret A (state-regulated passbook offered by every bank, ceiling EUR 22,950) pays 1.7% tax-free from 1 August 2026 to 31 January 2027; ordinary overnight household deposits averaged 0.05% and notice deposits 1.55% in August 2026 (ECB MFI statistics).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FR', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":2.72},{"year":2040,"value":2.15},{"year":2065,"value":2.15}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/france/2040/', '2025-12-31', '100 / old-age dependency ratio: 36.8 (2025, World Bank), 46.5 (2040) and 46.6 (2065, populationpyramid.net/france/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FR', 1, 'tax_bank_interest', 0.314, NULL, 'sourced', 'PwC Worldwide Tax Summaries, France income determination', 'https://taxsummaries.pwc.com/france/individual/income-determination', '2026-01-01', 'Flat tax (PFU) of 31.4% on interest earned from 2026: 12.8% income tax plus 18.6% social charges (17.2% before 2026); progressive income tax can be elected instead. Livret A, LDDS and LEP interest is tax-free; Service-Public still shows 30% for PEL interest.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FR', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate exists for individuals in France, so no specific tax rate applies.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FR', 1, 'tbill_91d_rate', 0.0279, NULL, 'sourced', 'Trading Economics, France 3-month BTF yield', 'https://tradingeconomics.com/france/government-bond-yield', '2026-10-30', 'Market yield on 3-month BTF (Bons du Trésor à taux fixe); 6-month 3.14%, 52-week 3.13%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FR', 1, 'tbond_10y_rate', 0.0497, NULL, 'sourced', 'Trading Economics, France 10-year OAT yield', 'https://tradingeconomics.com/france/government-bond-yield', '2026-10-30', 'ECB long-term (10-year) convergence yield for France was 4.44% in September 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('FR', 1, 'tbond_5y_rate', 0.0434, NULL, 'sourced', 'Trading Economics, France 5-year OAT yield', 'https://tradingeconomics.com/france/government-bond-yield', '2026-10-30', NULL, 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('GA', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"GA","iso3":"GAB","nameEn":"Gabon","nameNative":"Gabon","region":"sub_saharan_africa","languages":["fr","fan","puu"],"currency":{"code":"XAF","symbol":"FCFA","decimals":0,"compact":"intl","usdRate":{"value":581.928,"status":"sourced","sourceName":"World Bank WDI, official exchange rate (PA.NUS.FCRF), Gabon","sourceUrl":"https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=GA","asOf":"2025-12-31","note":"2025 average. The franc CFA is fixed at 655.957 per euro, so the dollar rate moves with the euro."}},"instruments":{"savings_account":{"available":true,"localName":"Compte d''épargne","localNameEn":"Savings account","note":"Banks must pay at least the BEAC minimum savings rate (2.45%).","sourceUrl":"https://www.beac.int/wp-content/uploads/2018/11/Rapport-sur-La-Politique-Mon%C3%A9taire-de-la-BEAC_Sept-2026_vf_new2_Publiable.pdf"},"fdr_3m":{"available":true,"localName":"Dépôt à terme (3 mois)","localNameEn":"Term deposit (3 months)","note":"Banks take term deposits (the BEAC sets reserve requirements on them), but rates are not published."},"fdr_1y":{"available":true,"localName":"Dépôt à terme (1 an)","localNameEn":"Term deposit (1 year)","note":"Banks take term deposits, but rates are not published."},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No standard monthly recurring deposit product was found."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate for individuals was found."},"tbill_91d":{"available":true,"localName":"Bons du Trésor assimilables (BTA)","localNameEn":"Treasury bills","note":"Auctioned through the BEAC mainly to banks; individuals held about XAF 16 billion of Gabonese bills in January 2026 (BEAC).","sourceUrl":"https://www.beac.int/wp-content/uploads/2021/10/Statistiques-Mensuelles-du-March%C3%A9-des-valeurs-du-Tr%C3%A9sors-de-la-CEMAC-janvier-2026.pdf"},"tbond_5y":{"available":true,"localName":"Obligations du Trésor assimilables (OTA)","localNameEn":"Treasury bonds","note":"Auctioned or offered to the public; individuals held about XAF 56 billion of Gabonese Treasury bonds in January 2026 (BEAC).","sourceUrl":"https://www.beac.int/wp-content/uploads/2021/10/Statistiques-Mensuelles-du-March%C3%A9-des-valeurs-du-Tr%C3%A9sors-de-la-CEMAC-janvier-2026.pdf"},"tbond_10y":{"available":false,"localName":null,"localNameEn":null,"note":"No 10-year Gabonese Treasury bond yield is published; bond maturities on the regional market are mostly up to about 7 years."},"equity_fund":{"available":false,"localName":null,"localNameEn":null,"note":"No locally sold diversified equity fund was found; the regional exchange (BVMAC) lists very few companies."},"gold":{"available":true,"localName":"Or","localNameEn":"Gold","note":"Gold is sold mainly as jewellery; no official bullion or coin scheme was found."}},"institutions":{"centralBank":{"name":"Bank of Central African States (Banque des États de l''Afrique Centrale, BEAC)","url":"https://www.beac.int/"},"insuranceRegulator":{"name":"Inter-African Conference on Insurance Markets (CIMA), regional insurance regulator, with the national insurance directorate","url":"https://cima-afrique.org/"},"insuranceComplaints":{"name":"CIMA policyholder requests and complaints form","url":"https://cima-afrique.org/faites-votre-requetes-ici-2/"},"pensionScheme":{"name":"National Social Security Fund (Caisse Nationale de Sécurité Sociale, CNSS)","url":"https://cnss.ga/"},"oldAgeAllowance":null,"publicHealthCover":{"name":"National Health Insurance and Social Guarantee Fund (Caisse Nationale d''Assurance Maladie et de Garantie Sociale, CNAMGS)","url":"https://cnamgs.ga/"},"depositInsurance":{"name":"Deposit Guarantee Fund of Central Africa (Fonds de Garantie des Dépôts en Afrique Centrale, FOGADAC)","url":"https://www.fogadac.com/"},"statistics":{"name":"Direction Générale des Statistiques du Gabon","url":"https://www.stat-gabon.org/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GA', 1, 'bank_deposit_avg_rate', 0.0245, NULL, 'sourced', 'World Bank WDI, deposit interest rate (FR.INR.DPST), Gabon', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=GA', '2017-12-31', '2.45% in 2017, the latest World Bank value (older than 2025); it equals the BEAC minimum savings rate, still 2.45% in the BEAC September 2026 report.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GA', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap or typical credit card rate for Gabon was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GA', 1, 'deposit_insurance_limit', 8000000, NULL, 'sourced', 'Deposit Guarantee Fund of Central Africa (FOGADAC), FAQ', 'https://www.fogadac.com/faq', '2026-10-31', 'FOGADAC covers deposits of individuals up to XAF 8 million (legal persons XAF 15 million), read 31 October 2026; covers banks in all CEMAC countries including Gabon.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GA', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No standard monthly recurring deposit product or rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GA', 1, 'equity_return_base', 0.065, NULL, 'assumption', 'Franc CFA fixed to the euro; regional exchange (BVMAC) with very small capitalisation (BEAC)', 'https://www.beac.int/wp-content/uploads/2021/10/Statistiques-Mensuelles-du-March%C3%A9-des-valeurs-du-Tr%C3%A9sors-de-la-CEMAC-janvier-2026.pdf', '2026-10-31', 'No usable local index record, so equity means a global index in euro terms, held about 3.5-4 points above an after-tax safe saving rate of about 2.5-3%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GA', 1, 'equity_return_high', 0.1, NULL, 'assumption', 'Franc CFA fixed to the euro; regional exchange (BVMAC) with very small capitalisation (BEAC)', 'https://www.beac.int/wp-content/uploads/2021/10/Statistiques-Mensuelles-du-March%C3%A9-des-valeurs-du-Tr%C3%A9sors-de-la-CEMAC-janvier-2026.pdf', '2026-10-31', 'High case: global equities repeat their long-run euro-terms record.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GA', 1, 'equity_return_low', 0.02, NULL, 'assumption', 'Franc CFA fixed to the euro; regional exchange (BVMAC) with very small capitalisation (BEAC)', 'https://www.beac.int/wp-content/uploads/2021/10/Statistiques-Mensuelles-du-March%C3%A9-des-valeurs-du-Tr%C3%A9sors-de-la-CEMAC-janvier-2026.pdf', '2026-10-31', 'Low case: a weak decade for global equities in euro (franc CFA) terms; the regional exchange is too small to serve as a guide.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GA', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published 1-year term deposit rate for Gabon was found; the BEAC publishes lending rates by country but no term deposit rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GA', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published 3-month term deposit rate for Gabon was found; the BEAC publishes lending rates by country but no term deposit rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GA', 1, 'fixed_income_return_base', 0.03, NULL, 'assumption', 'BEAC Taux Créditeur Minimum 2.45%; BEAC Treasury statistics January 2026 (Gabon bills 6.63%, bonds 7.25%)', 'https://www.beac.int/wp-content/uploads/2018/11/Rapport-sur-La-Politique-Mon%C3%A9taire-de-la-BEAC_Sept-2026_vf_new2_Publiable.pdf', '2026-10-31', 'Base case: savings and term deposits a little above the 2.45% floor; Treasury yields are higher but mostly held by banks.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GA', 1, 'fixed_income_return_high', 0.06, NULL, 'assumption', 'BEAC Taux Créditeur Minimum 2.45%; BEAC Treasury statistics January 2026 (Gabon bills 6.63%, bonds 7.25%)', 'https://www.beac.int/wp-content/uploads/2021/10/Statistiques-Mensuelles-du-March%C3%A9-des-valeurs-du-Tr%C3%A9sors-de-la-CEMAC-janvier-2026.pdf', '2026-10-31', 'High case: part of savings in Gabonese Treasury bonds offered to the public (issue cost 7.25% in January 2026), after liquidity risk.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GA', 1, 'fixed_income_return_low', 0.02, NULL, 'assumption', 'BEAC Taux Créditeur Minimum 2.45%; BEAC Treasury statistics January 2026 (Gabon bills 6.63%, bonds 7.25%)', 'https://www.beac.int/wp-content/uploads/2018/11/Rapport-sur-La-Politique-Mon%C3%A9taire-de-la-BEAC_Sept-2026_vf_new2_Publiable.pdf', '2026-10-31', 'Low case: ordinary savings accounts at the 2.45% minimum rate, less any tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GA', 1, 'goal_inflation_education', 0.035, NULL, 'assumption', 'BEAC note on CEMAC inflation: CEMAC education prices +0.4% year on year in September 2026', 'https://www.beac.int/wp-content/uploads/2016/10/Note-sur-l%C3%A9volution-r%C3%A9cente-de-linflation-dans-la-CEMAC-2026Q2.pdf', '2026-10-31', 'CEMAC education prices rose only 0.4% in the year to September 2026, but private school fees rise faster, so education goals use 1 point above the 2.5% planning inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GA', 1, 'goal_inflation_health', 0.04, NULL, 'assumption', 'BEAC note on CEMAC inflation: CEMAC health prices +1.5% year on year in September 2026', 'https://www.beac.int/wp-content/uploads/2016/10/Note-sur-l%C3%A9volution-r%C3%A9cente-de-linflation-dans-la-CEMAC-2026Q2.pdf', '2026-10-31', 'CEMAC health prices rose 1.5% in the year to September 2026, but private and imported care costs rise faster, so health goals use 1.5 points above the 2.5% planning inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GA', 1, 'gold_return_base', 0.045, NULL, 'assumption', 'Franc CFA fixed at 655.957 per euro (BEAC); dollar gold trend', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=GA', '2026-10-31', 'Base case: the long-run gold trend of about 4-5% a year in euro terms, which the franc CFA follows.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GA', 1, 'gold_return_high', 0.08, NULL, 'assumption', 'Franc CFA fixed at 655.957 per euro (BEAC); dollar gold trend', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=GA', '2026-10-31', 'High case: strong gold years.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GA', 1, 'gold_return_low', 0, NULL, 'assumption', 'Franc CFA fixed at 655.957 per euro (BEAC); dollar gold trend', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=GA', '2026-10-31', 'Low case: flat gold prices with no currency loss under the euro peg.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GA', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Labour Code provisions on dismissal or retirement indemnity could not be read from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GA', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical out-of-pocket cost of a major hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GA', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premiums by age were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GA', 1, 'inflation_cpi', 0.013, NULL, 'sourced', 'Bank of Central African States (BEAC), note on CEMAC inflation to June 2026 with prospects, annex table of national CPIs (Gabon)', 'https://www.beac.int/wp-content/uploads/2016/10/Note-sur-l%C3%A9volution-r%C3%A9cente-de-linflation-dans-la-CEMAC-2026Q2.pdf', '2026-09-30', 'Consumer prices in Gabon up 1.3% year on year in September 2026 (annual average 1.1%), per the BEAC annex table of national CPIs; the national statistics office bulletin was not read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GA', 1, 'inflation_projection', 0.025, NULL, 'assumption', 'BEAC: CEMAC inflation norm of 3%; franc CFA fixed to the euro; Gabon CPI 0.2-2.3% year on year in 2025-2026', 'https://www.beac.int/wp-content/uploads/2016/10/Note-sur-l%C3%A9volution-r%C3%A9cente-de-linflation-dans-la-CEMAC-2026Q2.pdf', '2026-10-31', 'Gabon''s inflation has stayed between about 0% and 2.5% since 2024 under the euro peg and the BEAC 3% norm, so 2.5% is used for long-run planning.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GA', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published term life premium rates per XAF 1,000 of cover were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GA', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No life insurance claim settlement ratio for Gabon was found from CIMA or the national insurance directorate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GA', 1, 'life_expectancy', 68.511, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN), Gabon', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=GA', '2024-12-31', '68.5 years in 2024 (men 66.1, women 71.2).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GA', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":18,"men":16.8,"women":19.1},{"age":65,"total":14.6,"men":13.7,"women":15.5},{"age":70,"total":11.6,"men":10.9,"women":12.2},{"age":80,"total":6.7,"men":6.4,"women":7}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/gabon/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026; totals are the mean of men and women except at 65, where the page gives 14.6 for both sexes.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GA', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension was found; the CNSS old-age pension and allowance are contributory.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GA', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension amount was found; the CNSS old-age allowance (allocation de vieillesse) is a contributory benefit, and CNAMGS covers health care for the economically weak rather than paying a pension.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GA', 1, 'oop_health_share', 0.1727, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), Gabon', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=GA', '2023-12-31', '17.3% in 2023 (WHO Global Health Expenditure Database via the World Bank), the latest available; older than 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GA', 1, 'policy_rate', 0.045, NULL, 'sourced', 'BEAC, Monetary Policy Report, September 2026 (decision of the Monetary Policy Committee for the fourth quarter of 2026)', 'https://www.beac.int/wp-content/uploads/2018/11/Rapport-sur-La-Politique-Mon%C3%A9taire-de-la-BEAC_Sept-2026_vf_new2_Publiable.pdf', '2026-09-28', 'The BEAC Monetary Policy Committee kept the tender rate (TIAO) at 4.50% for the fourth quarter of 2026 (marginal lending facility 5.75%, deposit facility 0%), as in the press release of 28 September 2026 (scanned PDF); common to all six CEMAC countries.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GA', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":60,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'National Social Security Fund of Gabon (CNSS), forms for insured persons', 'https://cnss.ga/assures-et-allocataires/', '2026-10-31', 'Compulsory scheme for salaried private-sector workers run by the CNSS: old-age pension or allowance (allocation de vieillesse, for short careers) from 60, early pension from 55 to 59. The benefit formula, revaluation rule and tax treatment were not found on the CNSS site, so no automatic indexation is assumed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GA', 1, 'retirement_accumulation_return_base', 0.045, NULL, 'assumption', 'Safe rate about 3%; global equity base 6.5% in euro terms; gold base 4.5%', 'https://www.beac.int/wp-content/uploads/2021/10/Statistiques-Mensuelles-du-March%C3%A9-des-valeurs-du-Tr%C3%A9sors-de-la-CEMAC-janvier-2026.pdf', '2026-10-31', 'Base case: a balanced mix of deposits, public bond offers, gold and foreign equity funds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GA', 1, 'retirement_accumulation_return_high', 0.065, NULL, 'assumption', 'Safe rate about 3%; global equity base 6.5% in euro terms; gold base 4.5%', 'https://www.beac.int/wp-content/uploads/2021/10/Statistiques-Mensuelles-du-March%C3%A9-des-valeurs-du-Tr%C3%A9sors-de-la-CEMAC-janvier-2026.pdf', '2026-10-31', 'High case: a growth-leaning mix with more equity.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GA', 1, 'retirement_accumulation_return_low', 0.025, NULL, 'assumption', 'Safe rate about 3%; global equity base 6.5% in euro terms; gold base 4.5%', 'https://www.beac.int/wp-content/uploads/2018/11/Rapport-sur-La-Politique-Mon%C3%A9taire-de-la-BEAC_Sept-2026_vf_new2_Publiable.pdf', '2026-10-31', 'Low case: mostly bank savings.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GA', 1, 'retirement_age_default', 60, NULL, 'sourced', 'National Social Security Fund of Gabon (CNSS), forms for insured persons (early pension request)', 'https://cnss.ga/assures-et-allocataires/', '2026-10-31', 'The CNSS offers an early pension (pension anticipée) to insured persons aged 55 to 59, so the normal old-age pension age for private-sector workers is 60; the Social Security Code itself was not read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GA', 1, 'retirement_age_government', 62, NULL, 'sourced', 'Caisse des Pensions et des Prestations Familiales des agents de l''État (CPPF), retirement guide', 'https://cppf.ga/je-demande-ma-retraite-2/', '2026-10-31', 'Since the pension reform in force in 2024 the legal retirement age for civil servants is 62, extendable for some corps up to 65; defence and security forces retire earlier by grade.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GA', 1, 'retirement_return_base', 0.03, NULL, 'assumption', 'BEAC Taux Créditeur Minimum 2.45%; BEAC Treasury statistics January 2026 (Gabon bills 6.63%, bonds 7.25%)', 'https://www.beac.int/wp-content/uploads/2018/11/Rapport-sur-La-Politique-Mon%C3%A9taire-de-la-BEAC_Sept-2026_vf_new2_Publiable.pdf', '2026-10-31', 'Base case: deposits and some public bond offers, kept close to the deposit floor and well below the 6.63% Treasury bill rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GA', 1, 'retirement_return_high', 0.045, NULL, 'assumption', 'BEAC Taux Créditeur Minimum 2.45%; BEAC Treasury statistics January 2026 (Gabon bills 6.63%, bonds 7.25%)', 'https://www.beac.int/wp-content/uploads/2021/10/Statistiques-Mensuelles-du-March%C3%A9-des-valeurs-du-Tr%C3%A9sors-de-la-CEMAC-janvier-2026.pdf', '2026-10-31', 'High case: a larger share in Gabonese Treasury bonds offered to the public.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GA', 1, 'retirement_return_low', 0.02, NULL, 'assumption', 'BEAC Taux Créditeur Minimum 2.45%; BEAC Treasury statistics January 2026 (Gabon bills 6.63%, bonds 7.25%)', 'https://www.beac.int/wp-content/uploads/2018/11/Rapport-sur-La-Politique-Mon%C3%A9taire-de-la-BEAC_Sept-2026_vf_new2_Publiable.pdf', '2026-10-31', 'Low case: savings accounts at the 2.45% minimum rate, less any tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GA', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate for individuals was found; the Treasury borrows through BEAC-run auctions and public bond offers (appels publics à l''épargne).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GA', 1, 'savings_account_rate', 0.0245, NULL, 'sourced', 'BEAC Monetary Policy Report, September 2026, Annex 1 (Taux Créditeur Minimum)', 'https://www.beac.int/wp-content/uploads/2018/11/Rapport-sur-La-Politique-Mon%C3%A9taire-de-la-BEAC_Sept-2026_vf_new2_Publiable.pdf', '2026-09-30', 'Minimum rate banks must pay on savings accounts of individuals in CEMAC (Taux Créditeur Minimum), 2.45%, unchanged since July 2014.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GA', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":14.4},{"year":2040,"value":11.4},{"year":2065,"value":7.5}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://data.worldbank.org/indicator/SP.POP.DPND.OL?locations=GA', '2025-12-31', '100 / old-age dependency ratio: 6.93 (2025, World Bank), 8.8 (2040, populationpyramid.net/gabon/2040/) and 13.3 (2065, populationpyramid.net/gabon/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GA', 1, 'tax_bank_interest', NULL, NULL, 'missing', '', '', '2026-10-31', 'The tax on bank interest for individuals (IRCM) could not be confirmed: PwC Worldwide Tax Summaries (reviewed 6 August 2026) gives the 20% IRCM only for payments to legal entities.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GA', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate exists for individuals and the tax on Treasury security income for individuals was not confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GA', 1, 'tbill_91d_rate', 0.0663, NULL, 'sourced', 'BEAC, Statistiques mensuelles du marché des valeurs du Trésor de la CEMAC, January 2026 (coût des ressources, BTA, Gabon)', 'https://www.beac.int/wp-content/uploads/2021/10/Statistiques-Mensuelles-du-March%C3%A9-des-valeurs-du-Tr%C3%A9sors-de-la-CEMAC-janvier-2026.pdf', '2026-01-31', 'Weighted average cost of Treasury bills (BTA, 13 to 52 weeks) issued by Gabon in January 2026 (6.80% in December 2025); no separate 13-week yield is published.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GA', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 10-year yield for Gabon is published in the BEAC Treasury market statistics, which give only an average cost for all bonds (OTA).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GA', 1, 'tbond_5y_rate', 0.0725, NULL, 'sourced', 'BEAC, Statistiques mensuelles du marché des valeurs du Trésor de la CEMAC, January 2026 (coût des ressources, OTA, Gabon)', 'https://www.beac.int/wp-content/uploads/2021/10/Statistiques-Mensuelles-du-March%C3%A9-des-valeurs-du-Tr%C3%A9sors-de-la-CEMAC-janvier-2026.pdf', '2026-01-31', 'Weighted average cost of Treasury bonds (OTA, 2 years and more) issued by Gabon in January 2026 (8.06% in December 2025); no yield for an exact 5-year maturity is published.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('GB', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"GB","iso3":"GBR","nameEn":"United Kingdom","nameNative":"United Kingdom","region":"europe_central_asia","languages":["en","cy","pl","pa","ur"],"currency":{"code":"GBP","symbol":"£","decimals":2,"compact":"intl","usdRate":{"value":0.7464,"status":"sourced","sourceName":"Bank of England, spot exchange rate US dollar into sterling (XUDLUSS)","sourceUrl":"https://www.bankofengland.co.uk/boeapps/database/_iadb-fromshowcolumns.asp?csv.x=yes&Datefrom=01/Jan/2026&Dateto=now&SeriesCodes=XUDLUSS&CSVF=TT&UsingCodes=Y&VPD=Y&VFD=N","asOf":"2026-10-30","note":"USD 1.3397 per pound on 30 October 2026, so about GBP 0.746 per US dollar; World Bank 2025 average 0.759."}},"instruments":{"savings_account":{"available":true,"localName":"Easy-access savings account","localNameEn":null,"note":"Interest is paid gross and taxed above the personal savings allowance; a cash ISA pays tax-free interest.","sourceUrl":"https://www.bankofengland.co.uk/boeapps/database/_iadb-fromshowcolumns.asp?csv.x=yes&Datefrom=01/Jan/2026&Dateto=now&SeriesCodes=IUMB6VJ&CSVF=TT&UsingCodes=Y&VPD=Y&VFD=N"},"fdr_3m":{"available":true,"localName":"Fixed-rate bond","localNameEn":"Fixed-term savings bond (3 months)","note":"Short fixed-rate bonds and notice accounts are sold by banks and building societies; terms of 1 year or more are more common."},"fdr_1y":{"available":true,"localName":"Fixed-rate bond","localNameEn":"Fixed-term savings bond (1 year)","sourceUrl":"https://www.bankofengland.co.uk/boeapps/database/_iadb-fromshowcolumns.asp?csv.x=yes&Datefrom=01/Jan/2026&Dateto=now&SeriesCodes=IUMWTFA&CSVF=TT&UsingCodes=Y&VPD=Y&VFD=N"},"dps":{"available":true,"localName":"Regular savings account","localNameEn":"Monthly regular saver","note":"Fixed monthly deposits, usually for 12 months, at a higher rate than easy-access accounts."},"sanchayapatra_5y":{"available":true,"localName":"NS&I Guaranteed Growth Bonds","localNameEn":"Government-backed fixed-rate savings bonds (1 to 5 years)","note":"Sold by National Savings and Investments, which is backed by HM Treasury, so savings are 100% protected; Premium Bonds (tax-free prizes) are the best-known NS&I product.","sourceUrl":"https://www.nsandi.com/products/guaranteed-growth-bonds"},"tbill_91d":{"available":true,"localName":"Treasury bills","localNameEn":null,"note":"Issued at weekly Debt Management Office tenders, mainly to banks and institutions; little retail access."},"tbond_5y":{"available":true,"localName":"Gilts","localNameEn":"UK government bonds","note":"Retail investors can buy gilts through a broker or the DMO''s purchase and sale service; gains on gilts are free of capital gains tax.","sourceUrl":"https://www.bankofengland.co.uk/boeapps/database/_iadb-fromshowcolumns.asp?csv.x=yes&Datefrom=01/Jan/2026&Dateto=now&SeriesCodes=IUDSNPY&CSVF=TT&UsingCodes=Y&VPD=Y&VFD=N"},"tbond_10y":{"available":true,"localName":"Gilts","localNameEn":"UK government bonds","sourceUrl":"https://www.bankofengland.co.uk/boeapps/database/_iadb-fromshowcolumns.asp?csv.x=yes&Datefrom=01/Jan/2026&Dateto=now&SeriesCodes=IUDMNPY&CSVF=TT&UsingCodes=Y&VPD=Y&VFD=N"},"equity_fund":{"available":true,"localName":null,"localNameEn":"Unit trusts, OEICs and index funds (ETFs)","note":"Usually held in a Stocks and Shares ISA or a pension, where gains and income are tax-free."},"gold":{"available":true,"localName":null,"localNameEn":"Gold bars and coins","note":"Legal to buy; investment gold is VAT-exempt and UK legal-tender gold coins (such as sovereigns and Britannias) are free of capital gains tax."}},"institutions":{"centralBank":{"name":"Bank of England","url":"https://www.bankofengland.co.uk/"},"insuranceRegulator":{"name":"Financial Conduct Authority (FCA); Prudential Regulation Authority (PRA)","url":"https://www.fca.org.uk/","note":"The FCA regulates how insurers treat customers; the PRA (part of the Bank of England) supervises their finances."},"insuranceComplaints":{"name":"Financial Ombudsman Service","url":"https://www.financial-ombudsman.org.uk/","note":"Free; complain to the insurer first and go to the ombudsman after 8 weeks or a final response."},"pensionScheme":{"name":"The new State Pension (Department for Work and Pensions)","url":"https://www.gov.uk/new-state-pension"},"oldAgeAllowance":{"name":"Pension Credit","url":"https://www.gov.uk/pension-credit","note":"Means-tested top-up for people over State Pension age on low incomes."},"publicHealthCover":{"name":"National Health Service (NHS)","url":"https://www.nhs.uk/","note":"Free at the point of use for residents; prescription and dental charges apply in England."},"depositInsurance":{"name":"Financial Services Compensation Scheme (FSCS)","url":"https://www.fscs.org.uk/"},"statistics":{"name":"Office for National Statistics (ONS)","url":"https://www.ons.gov.uk/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GB', 1, 'bank_deposit_avg_rate', 0.0344, NULL, 'sourced', 'Bank of England effective interest rates: household time deposits, stock outstanding (CFMHSCW)', 'https://www.bankofengland.co.uk/boeapps/database/_iadb-fromshowcolumns.asp?csv.x=yes&Datefrom=01/Jan/2026&Dateto=now&SeriesCodes=CFMHSCW&CSVF=TT&UsingCodes=Y&VPD=Y&VFD=N', '2026-09-30', 'Weighted average rate on all outstanding household time deposits in September 2026; interest-bearing sight deposits averaged 1.65% (CFMHSCV). World Bank FR.INR.DPST for the UK stops in 1998.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GB', 1, 'credit_card_rate_cap', 0.2471, NULL, 'sourced', 'Bank of England quoted household interest rates: representative credit card lending (IUMCCTL)', 'https://www.bankofengland.co.uk/boeapps/database/_iadb-fromshowcolumns.asp?csv.x=yes&Datefrom=01/Jan/2026&Dateto=now&SeriesCodes=IUMCCTL&CSVF=TT&UsingCodes=Y&VPD=Y&VFD=N', '2026-09-30', 'The UK has no legal cap on credit card interest; 24.71% is the representative quoted rate in September 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GB', 1, 'deposit_insurance_limit', 120000, NULL, 'sourced', 'Financial Services Compensation Scheme (FSCS), banks and building societies', 'https://www.fscs.org.uk/what-we-cover/banks-building-societies/', '2025-12-01', 'GBP 120,000 per eligible person per authorised bank, building society or credit union (banks sharing a licence count as one), from 1 December 2025; previously GBP 85,000.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GB', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Banks and building societies sell regular savings accounts (fixed monthly deposits, usually for 12 months), but neither the Bank of England nor the ONS publishes an average rate for them and no 5-year monthly scheme exists.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GB', 1, 'equity_return_base', 0.065, NULL, 'assumption', 'FTSE 100 near its July 2026 record (Trading Economics); after-tax safe rate about 3.5-4.4% (fixed bonds less 20% tax, cash ISAs)', 'https://tradingeconomics.com/united-kingdom/stock-market', '2026-10-31', 'Base case: about 2.5 points above the after-tax safe rate, in line with the UK market''s long-run total return of roughly 6-7% a year with dividends.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GB', 1, 'equity_return_high', 0.085, NULL, 'assumption', 'FTSE 100 (Trading Economics); long-run global equity returns', 'https://tradingeconomics.com/united-kingdom/stock-market', '2026-10-31', 'High case: a diversified global equity fund held in a Stocks and Shares ISA earns long-run equity returns of about 8-9% in pounds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GB', 1, 'equity_return_low', 0.04, NULL, 'assumption', 'FTSE 100 10,730 on 30 Oct 2026, +10.4% in a year (Trading Economics); 1-year fixed bonds 4.35% gross (Bank of England)', 'https://tradingeconomics.com/united-kingdom/stock-market', '2026-10-31', 'Low case: UK shares, a value-heavy market, repeat their weak 2000-2020 record and earn little more than cash in an ISA.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GB', 1, 'fdr_1y_rate', 0.0435, NULL, 'sourced', 'Bank of England quoted household interest rates: 1-year fixed-rate bond deposits including bonuses (IUMWTFA)', 'https://www.bankofengland.co.uk/boeapps/database/_iadb-fromshowcolumns.asp?csv.x=yes&Datefrom=01/Jan/2026&Dateto=now&SeriesCodes=IUMWTFA&CSVF=TT&UsingCodes=Y&VPD=Y&VFD=N', '2026-09-30', 'Representative quoted rate on 1-year fixed-rate savings bonds, up from 4.08% in August 2026; new 1-year-or-less fixed bonds averaged 4.34% (CFMZ6IP).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GB', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Bank of England publishes new fixed-rate bonds with a term up to 1 year as one bucket (4.34% in September 2026, CFMZ6IP) and a quoted 1-year bond rate, but no 3-month fixed-term deposit rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GB', 1, 'fixed_income_return_base', 0.035, NULL, 'assumption', '1-year fixed bonds 4.35% gross (Bank of England); 2-year fixed cash ISAs 4.53% tax-free (IUMZID2)', 'https://www.bankofengland.co.uk/boeapps/database/_iadb-fromshowcolumns.asp?csv.x=yes&Datefrom=01/Jan/2026&Dateto=now&SeriesCodes=IUMWTFA&CSVF=TT&UsingCodes=Y&VPD=Y&VFD=N', '2026-10-31', 'Base case: a mix of fixed-rate bonds after 20% tax (about 3.5%) and tax-free cash ISAs, assuming rates ease from today''s level.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GB', 1, 'fixed_income_return_high', 0.045, NULL, 'assumption', 'NS&I 5-year Guaranteed Growth Bonds 5.17% gross; 5-year gilt 4.91% (Bank of England)', 'https://www.nsandi.com/products/guaranteed-growth-bonds', '2026-10-31', 'High case: locking in today''s 5-year rates inside an ISA or within the personal savings allowance, so little tax is paid.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GB', 1, 'fixed_income_return_low', 0.025, NULL, 'assumption', '1-year fixed bonds 4.35% gross less 20% tax = 3.5% (Bank of England IUMWTFA)', 'https://www.bankofengland.co.uk/boeapps/database/_iadb-fromshowcolumns.asp?csv.x=yes&Datefrom=01/Jan/2026&Dateto=now&SeriesCodes=IUMWTFA&CSVF=TT&UsingCodes=Y&VPD=Y&VFD=N', '2026-10-31', 'Low case: savings rates fall back towards 3% as Bank Rate is cut, leaving about 2.5% after basic-rate tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GB', 1, 'goal_inflation_education', 0.05, NULL, 'assumption', 'ONS CPI September 2026: Education division +5.0% a year', 'https://www.ons.gov.uk/economy/inflationandpriceindices/bulletins/consumerpriceinflation/september2026', '2026-10-31', 'Education prices are rising faster than headline inflation, with university tuition fees now rising with inflation and private school fees subject to VAT since 2025, so 5% is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GB', 1, 'goal_inflation_health', 0.04, NULL, 'assumption', 'ONS CPI September 2026: Health division +3.5% a year', 'https://www.ons.gov.uk/economy/inflationandpriceindices/bulletins/consumerpriceinflation/september2026', '2026-10-31', 'Measured health prices rise with headline inflation, but private treatment, dental and prescription costs and care fees tend to rise faster, so 4% is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GB', 1, 'gold_return_base', 0.04, NULL, 'assumption', 'Gold price history (Trading Economics); Bank of England 2% target', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Base case: dollar gold rises roughly with world inflation plus a little, with mild long-run weakness in the pound.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GB', 1, 'gold_return_high', 0.07, NULL, 'assumption', 'Gold price history (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'High case: a repeat of gold''s strong 2005-2025 trend in pound terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GB', 1, 'gold_return_low', 0.01, NULL, 'assumption', 'Gold USD 3,876/oz on 30 Oct 2026, 31% below the January 2026 high (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Low case: gold barely keeps up after the 2025-26 spike and the pound holds its value against the dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GB', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'UK law has no statutory gratuity or end-of-service payment on resignation or retirement; the only statutory leaving payment is redundancy pay (half to one and a half weeks'' pay per year of service up to 20 years, weekly pay capped at GBP 751, maximum GBP 22,530 from 6 April 2026), payable only on redundancy after 2 years'' service (GOV.UK, Redundancy pay: https://www.gov.uk/redundant-your-rights/redundancy-pay).', 1);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GB', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'NHS hospital care is free at the point of use for UK residents, so the typical out-of-pocket cost of a major stay is nil; no official figure for the self-pay cost of a private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GB', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'UK private medical insurance is priced per plan (by age, postcode, excess and hospital list), not per sum insured, and no official premium table per GBP 100,000 of cover was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GB', 1, 'inflation_cpi', 0.035, NULL, 'sourced', 'Office for National Statistics (ONS), Consumer price inflation, UK: September 2026', 'https://www.ons.gov.uk/economy/inflationandpriceindices/bulletins/consumerpriceinflation/september2026', '2026-09-30', 'CPI rose 3.5% in the 12 months to September 2026 (3.1% in August); CPIH 3.6%. Released 21 October 2026. World Bank 2025 average 3.9%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GB', 1, 'inflation_projection', 0.025, NULL, 'assumption', 'Bank of England 2% CPI target; CPI 3.5% (Sep 2026, ONS), 3.9% in 2025 (World Bank)', 'https://www.bankofengland.co.uk/monetary-policy/inflation', '2026-10-31', 'The Bank of England''s 2% target is credible over the long run, but UK inflation has run above it in most years since 2021, so 2.5% is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GB', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life cover is widely sold in the UK, but no regulator or government source publishes indicative premiums per GBP 1,000 of cover by age; MoneyHelper gives no price table and insurer or broker quote tools were not used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GB', 1, 'life_claim_settlement_rate', 0.967, NULL, 'sourced', 'Insurance Business UK (news), reporting Association of British Insurers and GRiD protection claims data for 2025', 'https://www.insurancebusinessmag.com/uk/news/life-insurance/uk-protection-payouts-reach-7-84bn-as-musculoskeletal-claims-lead-income-protection-580599.aspx', '2025-12-31', 'Secondary source (the industry association''s own release returned 403): 96.7% of 48,055 new individual life insurance claims were paid in 2025; 97.9% of all individual protection claims were paid. Published 29 June 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GB', 1, 'life_expectancy', 81.7, NULL, 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/united-kingdom', '2026-07-01', 'Men 79.9, women 83.6 (UN WPP estimate for 2026). ONS national life tables 2022-2024: men 79.1, women 83.0; World Bank 2024 figure 81.4.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GB', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":24.5,"men":23.2,"women":25.8},{"age":65,"total":20.3,"men":19.1,"women":21.5},{"age":70,"total":16.3,"men":15.2,"women":17.3},{"age":80,"total":9.3,"men":8.6,"women":9.9}]}', 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/united-kingdom', '2026-07-01', 'Remaining years computed from georank''s expected age at death by current age (UN WPP 2026 estimate). ONS national life tables 2022-2024 give 18.7 (men) and 21.2 (women) at 65.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GB', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":66,"womenAge":66,"over90Monthly":null,"meansTested":true}', 'sourced', 'GOV.UK, Pension Credit eligibility', 'https://www.gov.uk/pension-credit/eligibility', '2026-10-31', 'Claimable from State Pension age (66 today, rising to 67 and then 68 for younger people); means-tested on income and savings over GBP 10,000; must live in Great Britain. A non-contributory over-80 pension (GBP 110.75 a week in 2026/27) is also paid to people aged 80+ with little or no basic State Pension (gov.uk/over-80-pension).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GB', 1, 'old_age_allowance_monthly', 1031, NULL, 'sourced', 'GOV.UK, Pension Credit: what you''ll get', 'https://www.gov.uk/pension-credit/what-youll-get', '2026-04-06', 'Means-tested Guarantee Credit tops weekly income up to GBP 238 for a single person (GBP 363.25 for a couple) in 2026/27; GBP 238 x 52 / 12 = GBP 1,031 a month for someone with no other income. A person with a full new State Pension (GBP 241.30 a week) gets no Guarantee Credit.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GB', 1, 'oop_health_share', 0.1456, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=GB', '2024-12-31', NULL, 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GB', 1, 'policy_rate', 0.0375, NULL, 'sourced', 'Bank of England, Bank Rate', 'https://www.bankofengland.co.uk/monetary-policy/the-interest-rate-bank-rate', '2026-09-17', 'Bank Rate 3.75%, held at the 18 June, 30 July and 17 September 2026 decisions; next decision 5 November 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GB', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":16,"entryAgeMax":null,"pensionFromAge":68,"nomineeUntilAge":null,"inflationLinked":true,"taxFree":false}', 'sourced', 'GOV.UK, The new State Pension', 'https://www.gov.uk/new-state-pension/what-youll-get', '2026-10-31', 'National Insurance-based new State Pension: full rate GBP 241.30 a week (about GBP 1,046 a month) in 2026/27 with 35 qualifying years, minimum 10 years; paid from State Pension age (68 for those born from 6 April 1978). Uprated each April by the triple lock (the highest of earnings growth, CPI inflation or 2.5%). Taxable income, paid without tax deducted. Workplace pension auto-enrolment applies to employees aged 22 to State Pension age earning over GBP 10,000.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GB', 1, 'retirement_accumulation_return_base', 0.05, NULL, 'assumption', 'Fixed income base 3.5%; equity base 6.5%', 'https://tradingeconomics.com/united-kingdom/stock-market', '2026-10-31', 'Base case: roughly half shares at 6.5% and half safe fixed income at about 3.5% after tax, largely sheltered in ISAs and pensions.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GB', 1, 'retirement_accumulation_return_high', 0.065, NULL, 'assumption', 'Fixed income high 4.5%; equity high 8.5%', 'https://tradingeconomics.com/united-kingdom/stock-market', '2026-10-31', 'High case for a growth-leaning balanced mix held in tax-free wrappers.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GB', 1, 'retirement_accumulation_return_low', 0.03, NULL, 'assumption', 'After-tax safe rate about 3.5%; FTSE 100 record (Trading Economics)', 'https://www.bankofengland.co.uk/boeapps/database/_iadb-fromshowcolumns.asp?csv.x=yes&Datefrom=01/Jan/2026&Dateto=now&SeriesCodes=IUMWTFA&CSVF=TT&UsingCodes=Y&VPD=Y&VFD=N', '2026-10-31', 'Low case for a balanced mix if shares lag.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GB', 1, 'retirement_age_default', 68, NULL, 'sourced', 'GOV.UK, State Pension age timetable (Pensions Acts 2007 and 2014)', 'https://www.gov.uk/government/publications/state-pension-age-timetable/state-pension-age-timetable', '2026-10-31', 'State Pension age is 68 for anyone born on or after 6 April 1978 (reached in stages for those born 6 April 1977 to 5 April 1978) and 67 for those born 6 April 1960 to 5 April 1977, so people born in 1976 and early 1977 have 67; 68 covers most people born after 1975. It is 66 today and the same for men and women. A third State Pension age review is under way. There is no compulsory retirement age for private employees.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GB', 1, 'retirement_age_government', 68, NULL, 'sourced', 'GOV.UK, State Pension age timetable; Civil Service alpha scheme normal pension age equals State Pension age', 'https://www.gov.uk/government/publications/state-pension-age-timetable/state-pension-age-timetable', '2026-10-31', 'Civil servants in the alpha scheme (since 2015) have a normal pension age equal to their State Pension age (68 for those born from 6 April 1978); there is no compulsory retirement age. Uniformed services (police, firefighters, armed forces) have earlier ages.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GB', 1, 'retirement_return_base', 0.034, NULL, 'assumption', '1-year fixed bonds 4.35% gross less 20% basic-rate tax = 3.48% (Bank of England IUMWTFA)', 'https://www.bankofengland.co.uk/boeapps/database/_iadb-fromshowcolumns.asp?csv.x=yes&Datefrom=01/Jan/2026&Dateto=now&SeriesCodes=IUMWTFA&CSVF=TT&UsingCodes=Y&VPD=Y&VFD=N', '2026-10-31', 'Base case capped at the after-tax 1-year fixed-rate bond rate for a basic-rate taxpayer.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GB', 1, 'retirement_return_high', 0.042, NULL, 'assumption', 'NS&I Guaranteed Growth Bonds 4.99-5.17%; 5-year gilt 4.91% (Bank of England)', 'https://www.nsandi.com/products/guaranteed-growth-bonds', '2026-10-31', 'High case: a retiree ladders gilts and fixed-rate bonds, partly inside ISAs, at about today''s rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GB', 1, 'retirement_return_low', 0.025, NULL, 'assumption', '1-year fixed bonds 4.35% gross less 20% tax = 3.5% (Bank of England IUMWTFA)', 'https://www.bankofengland.co.uk/boeapps/database/_iadb-fromshowcolumns.asp?csv.x=yes&Datefrom=01/Jan/2026&Dateto=now&SeriesCodes=IUMWTFA&CSVF=TT&UsingCodes=Y&VPD=Y&VFD=N', '2026-10-31', 'Low case: deposit rates fall back as Bank Rate is cut.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GB', 1, 'sanchayapatra_5y_rate', 0.0517, NULL, 'sourced', 'National Savings and Investments (NS&I, HM Treasury), Guaranteed Growth Bonds 5-year Issue 75', 'https://www.nsandi.com/products/guaranteed-growth-bonds', '2026-10-31', 'Government-backed 5-year fixed-rate bond, 5.17% gross/AER; 1-year 4.99%, 2-year 5.07%, 3-year 5.10%. Interest is taxable and paid at maturity; NS&I can withdraw an issue without notice.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GB', 1, 'savings_account_rate', 0.0206, NULL, 'sourced', 'Bank of England quoted household interest rates: instant access deposits including bonuses (IUMB6VJ)', 'https://www.bankofengland.co.uk/boeapps/database/_iadb-fromshowcolumns.asp?csv.x=yes&Datefrom=01/Jan/2026&Dateto=now&SeriesCodes=IUMB6VJ&CSVF=TT&UsingCodes=Y&VPD=Y&VFD=N', '2026-09-30', 'Representative quoted rate on easy-access savings accounts in September 2026 (1.90% excluding unconditional bonuses); interest is paid without tax deducted.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GB', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":3.21},{"year":2040,"value":2.64},{"year":2065,"value":2.2}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/united-kingdom/2040/', '2025-12-31', '100 / old-age dependency ratio: 31.1 (2025, World Bank), 37.9 (2040) and 45.5 (2065, populationpyramid.net/united-kingdom/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GB', 1, 'tax_bank_interest', 0.2, NULL, 'sourced', 'PwC Worldwide Tax Summaries, United Kingdom income determination', 'https://taxsummaries.pwc.com/united-kingdom/individual/income-determination', '2026-10-31', 'No withholding: banks pay interest gross and it is taxed at the saver''s marginal savings rate, 20% for a basic-rate taxpayer (40% higher, 45% additional), after the 0% starting rate (up to GBP 5,000) and the personal savings allowance (GBP 1,000 basic rate, GBP 500 higher rate). Savings rates rise to 22%/42%/47% from April 2027. Cash ISA interest is tax-free.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GB', 1, 'tax_sanchayapatra_profit', 0.2, NULL, 'sourced', 'NS&I Guaranteed Growth Bonds, tax information', 'https://www.nsandi.com/products/guaranteed-growth-bonds', '2026-10-31', 'NS&I fixed-term bond interest is paid without tax deducted but is taxable income in the year the bond matures, at the saver''s marginal savings rate (20% basic rate, after the personal savings allowance). Premium Bond prizes are tax-free.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GB', 1, 'tbill_91d_rate', 0.042, NULL, 'sourced', 'Trading Economics, United Kingdom 3-month bill yield', 'https://tradingeconomics.com/united-kingdom/3-month-bill-yield', '2026-10-30', 'Secondary source; the Debt Management Office tender reports could not be read and the Bank of England 3-month Treasury bill series (IUMAJNB) has no 2026 data. Trading Economics showed 4.20% (also 4.20% on 2 November 2026); this is above Bank Rate (3.75%) and SONIA (3.73% on 29 October 2026), reflecting market pricing.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GB', 1, 'tbond_10y_rate', 0.0526, NULL, 'sourced', 'Bank of England, 10-year nominal par yield on British government stock (IUDMNPY)', 'https://www.bankofengland.co.uk/boeapps/database/_iadb-fromshowcolumns.asp?csv.x=yes&Datefrom=01/Jan/2026&Dateto=now&SeriesCodes=IUDMNPY&CSVF=TT&UsingCodes=Y&VPD=Y&VFD=N', '2026-10-29', 'Daily yield 5.26% on 29 October 2026 (5.31% on 28 October).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GB', 1, 'tbond_5y_rate', 0.0491, NULL, 'sourced', 'Bank of England, 5-year nominal par yield on British government stock (IUDSNPY)', 'https://www.bankofengland.co.uk/boeapps/database/_iadb-fromshowcolumns.asp?csv.x=yes&Datefrom=01/Jan/2026&Dateto=now&SeriesCodes=IUDSNPY&CSVF=TT&UsingCodes=Y&VPD=Y&VFD=N', '2026-10-29', 'Daily yield 4.91% on 29 October 2026 (4.96% on 28 October).', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('GD', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"GD","iso3":"GRD","nameEn":"Grenada","nameNative":"Grenada","region":"latin_america_caribbean","languages":["en","gcl"],"currency":{"code":"XCD","symbol":"$","decimals":2,"compact":"intl","usdRate":{"value":2.7,"status":"sourced","sourceName":"ECCB Monetary Council, communique of the 113th meeting (10 July 2026), reported by Discover MNI","sourceUrl":"https://discovermni.com/2026/07/13/communique-of-the-113th-meeting-of-the-monetary-council-of-the-eastern-caribbean-central-bank/","asOf":"2026-07-10","note":"Fixed exchange rate of EC$2.70 per US dollar, in place for 50 years; World Bank PA.NUS.FCRF also gives 2.7 for 2025."}},"instruments":{"savings_account":{"available":true,"localName":"Savings account","note":"ECCB minimum savings rate 2%.","sourceUrl":"https://discovermni.com/2026/07/13/communique-of-the-113th-meeting-of-the-monetary-council-of-the-eastern-caribbean-central-bank/"},"fdr_3m":{"available":true,"localName":"Fixed deposit","localNameEn":"3-month fixed (time) deposit","note":"Offered by commercial banks and credit unions; no public rate table found."},"fdr_1y":{"available":true,"localName":"Fixed deposit","localNameEn":"12-month fixed (time) deposit","note":"Offered by commercial banks and credit unions; no public rate table found."},"dps":{"available":false,"localName":null,"note":"No standard monthly recurring deposit product with a published rate."},"sanchayapatra_5y":{"available":false,"localName":null,"note":"No government savings certificate or retail savings bond for individuals was found."},"tbill_91d":{"available":true,"localName":"Treasury bill","localNameEn":"Government of Grenada 91-day Treasury bill","note":"Auctioned on the Regional Government Securities Market through licensed intermediaries; mostly bought by institutions."},"tbond_5y":{"available":false,"localName":null,"note":"No regular 5-year government bond issue for retail found."},"tbond_10y":{"available":false,"localName":null,"note":"No regular 10-year government bond issue for retail found."},"equity_fund":{"available":false,"localName":null,"note":"No locally registered retail equity or index fund was identified; the regional share market is very small."},"gold":{"available":true,"localName":"Gold","localNameEn":"Gold jewellery and coins","note":"No legal restriction on buying gold; mostly sold as jewellery."}},"institutions":{"centralBank":{"name":"Eastern Caribbean Central Bank (ECCB)","url":"https://www.eccb-centralbank.org/","note":"Shared central bank of the Eastern Caribbean Currency Union."},"insuranceRegulator":{"name":"Grenada Authority for the Regulation of Financial Institutions (GARFIN)","url":"https://garfin.gd/"},"insuranceComplaints":{"name":"Grenada Authority for the Regulation of Financial Institutions (GARFIN)","url":"https://garfin.gd/","note":"No separate insurance ombudsman; complaints go to GARFIN."},"pensionScheme":{"name":"National Insurance Scheme (NIS) Grenada","url":"https://nisgrenada.org/"},"oldAgeAllowance":null,"publicHealthCover":{"name":"Ministry of Health (public hospitals and free district health centres)","url":"https://www.gov.gd/health"},"depositInsurance":null,"statistics":{"name":"Central Statistical Office, Ministry of Finance","url":"https://stats.gov.gd/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GD', 1, 'bank_deposit_avg_rate', 0.0095, NULL, 'sourced', 'World Bank WDI FR.INR.DPST', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=GD', '2025-12-31', 'Average rate paid by commercial banks on deposits, 2025 (ECCB data via IMF IFS).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GD', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched ECCB and GARFIN sources: no legal cap on credit card interest and no official typical rate published for Grenada.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GD', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'Grenada passed the Eastern Caribbean Deposit Insurance Corporation Agreement Bill 2025 (https://grenadaparliament.gd/wp-content/uploads/2025/05/Eastern-Caribbean-Deposit-Insurance-Corporation-Agreement-Bill-2025.pdf), but no evidence was found that the regional corporation is operating or that a coverage limit has been set.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GD', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched ECCB and Grenada sources: no monthly recurring deposit product rate is published.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GD', 1, 'equity_return_base', 0.06, NULL, 'assumption', 'ECCB Monetary Council (July 2026): discount rate 3%, minimum savings rate 2%, EC$2.70 per US$1 peg', 'https://discovermni.com/2026/07/13/communique-of-the-113th-meeting-of-the-monetary-council-of-the-eastern-caribbean-central-bank/', '2026-10-31', 'Base case uses a global equity index in EC-dollar terms (pegged to the US dollar), kept within 4 points of the tax-free 2% minimum savings rate because the local market has no usable 10-year record.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GD', 1, 'equity_return_high', 0.09, NULL, 'assumption', 'ECCB Monetary Council (July 2026): discount rate 3%, minimum savings rate 2%, EC$2.70 per US$1 peg', 'https://discovermni.com/2026/07/13/communique-of-the-113th-meeting-of-the-monetary-council-of-the-eastern-caribbean-central-bank/', '2026-10-31', 'High case if global equities repeat their strong long-run US-dollar returns.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GD', 1, 'equity_return_low', 0.02, NULL, 'assumption', 'ECCB Monetary Council (July 2026): discount rate 3%, minimum savings rate 2%, EC$2.70 per US$1 peg', 'https://discovermni.com/2026/07/13/communique-of-the-113th-meeting-of-the-monetary-council-of-the-eastern-caribbean-central-bank/', '2026-10-31', 'Low case: the regional share market is very small, so savers rely on global equity funds in pegged US-dollar terms, and a weak decade is possible.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GD', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched ECCB statistics and Grenada sources: no readable public figure for a 12-month time deposit rate in Grenada; the World Bank average deposit rate (all deposits) was 0.95% in 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GD', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched ECCB statistics and Grenada sources: the ECCB interest-rate tables by country could not be read (site blocks automated access) and no other public source gives a 3-month time deposit rate for Grenada.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GD', 1, 'fixed_income_return_base', 0.02, NULL, 'assumption', 'ECCB minimum savings rate 2% and discount rate 3% (July 2026); World Bank average deposit rate 0.95% (2025)', 'https://discovermni.com/2026/07/13/communique-of-the-113th-meeting-of-the-monetary-council-of-the-eastern-caribbean-central-bank/', '2026-10-31', 'Base case: tax-free deposits around the ECCB 2% minimum savings rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GD', 1, 'fixed_income_return_high', 0.03, NULL, 'assumption', 'ECCB minimum savings rate 2% and discount rate 3% (July 2026); World Bank average deposit rate 0.95% (2025)', 'https://discovermni.com/2026/07/13/communique-of-the-113th-meeting-of-the-monetary-council-of-the-eastern-caribbean-central-bank/', '2026-10-31', 'High case: longer deposits or government paper at about the 3% ECCB discount rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GD', 1, 'fixed_income_return_low', 0.01, NULL, 'assumption', 'ECCB minimum savings rate 2% and discount rate 3% (July 2026); World Bank average deposit rate 0.95% (2025)', 'https://discovermni.com/2026/07/13/communique-of-the-113th-meeting-of-the-monetary-council-of-the-eastern-caribbean-central-bank/', '2026-10-31', 'Low case: savings and short deposits near the 0.95% average deposit rate (2025), tax-free for residents.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GD', 1, 'goal_inflation_education', 0.035, NULL, 'assumption', 'Grenada CPI inflation 2.03% (June 2026); planning inflation 2%', 'https://tradingeconomics.com/grenada/inflation-cpi', '2026-10-31', 'No long-run education CPI series found; headline planning inflation plus 1.5 points.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GD', 1, 'goal_inflation_health', 0.04, NULL, 'assumption', 'Grenada CPI inflation 2.03% (June 2026); planning inflation 2%', 'https://tradingeconomics.com/grenada/inflation-cpi', '2026-10-31', 'No long-run medical CPI series found; headline planning inflation plus 2 points for private and overseas medical costs.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GD', 1, 'gold_return_base', 0.045, NULL, 'assumption', 'ECCB: EC$2.70 per US$1 fixed exchange rate (113th Monetary Council communique)', 'https://discovermni.com/2026/07/13/communique-of-the-113th-meeting-of-the-monetary-council-of-the-eastern-caribbean-central-bank/', '2026-10-31', 'Long-run dollar gold trend of about 4-5% a year, with no expected depreciation of the pegged EC dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GD', 1, 'gold_return_high', 0.08, NULL, 'assumption', 'ECCB: EC$2.70 per US$1 fixed exchange rate (113th Monetary Council communique)', 'https://discovermni.com/2026/07/13/communique-of-the-113th-meeting-of-the-monetary-council-of-the-eastern-caribbean-central-bank/', '2026-10-31', 'High case with strong dollar gold prices.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GD', 1, 'gold_return_low', 0.01, NULL, 'assumption', 'ECCB: EC$2.70 per US$1 fixed exchange rate (113th Monetary Council communique)', 'https://discovermni.com/2026/07/13/communique-of-the-113th-meeting-of-the-monetary-council-of-the-eastern-caribbean-central-bank/', '2026-10-31', 'Low case: weak dollar gold price; the 50-year peg means no currency boost.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GD', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No statutory retirement gratuity: severance under the Employment Act (s.84 of Cap. 89, https://grenadaparliament.gd/wp-content/uploads/2021/08/Cap89-EMPLOYMENT-ACT.pdf, and s.86 of the Employment Act 2016) is paid only on dismissal and not to an employee over the NIS pensionable age (as amended by the National Insurance (Amendment) (No. 2) Act 2023).', 1);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GD', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched Ministry of Health and news sources: public General Hospital fees are low and not published as a typical bill; no official figure for a major private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GD', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched GARFIN and public sources: no published individual health insurance premiums by age.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GD', 1, 'inflation_cpi', 0.0203, NULL, 'sourced', 'Trading Economics, Grenada inflation rate (Central Statistical Office CPI)', 'https://tradingeconomics.com/grenada/inflation-cpi', '2026-06-30', 'Secondary source: annual CPI inflation 2.0% in June 2026 (2.06% in May); the CSO and ECCB CPI pages could not be read (CSO site lists releases only to 2024, ECCB site blocks automated access).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GD', 1, 'inflation_projection', 0.02, NULL, 'assumption', 'IMF WEO (2026 forecast 1.3%, medium term about 2%); World Bank CPI 0.6% for 2025; EC dollar pegged at 2.70 per US dollar', 'https://tradingeconomics.com/grenada/inflation-cpi', '2026-10-31', 'The ECCB has no inflation target (the EC dollar is pegged to the US dollar), so we plan with about 2%, in line with US-dollar inflation and recent Grenada readings of 0.6-2%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GD', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life is sold in Grenada by regional insurers, but no regulator or public source publishes premium rates by age; only individual insurer quotes exist.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GD', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched GARFIN Supervisor of Insurance reports and news: only claim totals are published (latest found for 2018), no industry-wide life claim settlement ratio.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GD', 1, 'life_expectancy', 75.367, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=GD', '2024-12-31', 'UN WPP 2024 (via populationpyramid.net) gives 75.7 for 2026 (men 72.8, women 78.8).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GD', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":21.4,"men":19,"women":23.8},{"age":65,"total":17.8,"men":15.7,"women":19.9},{"age":70,"total":14.5,"men":12.5,"women":16.5},{"age":80,"total":8.8,"men":7.6,"women":9.9}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/grenada/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026; sex-specific values are for the 5-year age groups starting at each age; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GD', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension exists in Grenada (HelpAge Pension Watch, https://www.helpage.org/country_profile/grenada/).', 1);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GD', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'HelpAge Pension Watch (https://www.helpage.org/country_profile/grenada/) states that Grenada does not currently have a social pension (0% of people 60+ receive one); poor elderly people can only apply for means-tested Public Assistance.', 1);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GD', 1, 'oop_health_share', 0.4848, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=GD', '2023-12-31', 'Figure is for 2023 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GD', 1, 'policy_rate', 0.03, NULL, 'sourced', 'ECCB Monetary Council, communique of the 113th meeting (10 July 2026), reported by Discover MNI', 'https://discovermni.com/2026/07/13/communique-of-the-113th-meeting-of-the-monetary-council-of-the-eastern-caribbean-central-bank/', '2026-07-10', 'ECCB discount rate 3.0% for short-term credit (4.5% long-term), unchanged; applies to all ECCU members including Grenada. Secondary copy of the communique (the ECCB site blocks automated reading).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GD', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":16,"entryAgeMax":null,"pensionFromAge":65,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'National Insurance (Amendment) (No. 2) Bill 2023 (Parliament of Grenada), amending the National Insurance Act Cap. 205', 'https://grenadaparliament.gd/wp-content/uploads/2023/06/National-Insurance_Amendment-No.-2-Bill-2023.docx', '2024-01-01', 'Compulsory contributory NIS age pension for insured persons aged 16 up to the pensionable age (rising to 65 from 2028), per the National Insurance (Amendment) (No. 2) Act 2023. No automatic indexation was found; tax treatment not confirmed. Law from 2023 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GD', 1, 'retirement_accumulation_return_base', 0.04, NULL, 'assumption', 'ECCB minimum savings rate 2% (July 2026); global equity assumptions in pegged EC dollars', 'https://discovermni.com/2026/07/13/communique-of-the-113th-meeting-of-the-monetary-council-of-the-eastern-caribbean-central-bank/', '2026-10-31', 'Base case: half global equities at 6% and half tax-free deposits at about 2%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GD', 1, 'retirement_accumulation_return_high', 0.06, NULL, 'assumption', 'ECCB minimum savings rate 2% (July 2026); global equity assumptions in pegged EC dollars', 'https://discovermni.com/2026/07/13/communique-of-the-113th-meeting-of-the-monetary-council-of-the-eastern-caribbean-central-bank/', '2026-10-31', 'High case with stronger equity returns.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GD', 1, 'retirement_accumulation_return_low', 0.025, NULL, 'assumption', 'ECCB minimum savings rate 2% (July 2026); global equity assumptions in pegged EC dollars', 'https://discovermni.com/2026/07/13/communique-of-the-113th-meeting-of-the-monetary-council-of-the-eastern-caribbean-central-bank/', '2026-10-31', 'Low case for a balanced mix if global equities disappoint.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GD', 1, 'retirement_age_default', 65, NULL, 'sourced', 'National Insurance (Amendment) (No. 2) Bill 2023, Third Schedule (Parliament of Grenada)', 'https://grenadaparliament.gd/wp-content/uploads/2023/06/National-Insurance_Amendment-No.-2-Bill-2023.docx', '2024-01-01', 'National Insurance (Amendment) (No. 2) Act 2023, Third Schedule: pensionable age 61 in 2024, 62 in 2025, 63 in 2026, 64 in 2027 and 65 from 1 January 2028, so 65 applies to anyone born after 1975. In force 1 January 2024 (law from 2023, older than 2025; bill text read).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GD', 1, 'retirement_age_government', 60, NULL, 'sourced', 'Jamaica Observer, ''Grenada says new pension scheme favourable to civil servants'' (31 December 2024)', 'https://jamaicaobserver.com/2024/12/31/grenada-says-new-pension-scheme-favourable-civil-servants', '2024-12-31', 'Attorney General quoted: public officers work until 60 or 26 2/3 years of service; early retirement at 50 with 20 years. A new Public Sector Employees (Pension Fund) scheme was proposed in 2024. News source from 2024 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GD', 1, 'retirement_return_base', 0.02, NULL, 'assumption', 'ECCB minimum savings rate 2% and discount rate 3% (July 2026)', 'https://discovermni.com/2026/07/13/communique-of-the-113th-meeting-of-the-monetary-council-of-the-eastern-caribbean-central-bank/', '2026-10-31', 'Base case equal to the tax-free 2% minimum savings rate, the best confirmed safe rate, kept liquid in retirement.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GD', 1, 'retirement_return_high', 0.03, NULL, 'assumption', 'ECCB minimum savings rate 2% and discount rate 3% (July 2026)', 'https://discovermni.com/2026/07/13/communique-of-the-113th-meeting-of-the-monetary-council-of-the-eastern-caribbean-central-bank/', '2026-10-31', 'High case: longer deposits or government paper near the 3% ECCB discount rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GD', 1, 'retirement_return_low', 0.01, NULL, 'assumption', 'ECCB minimum savings rate 2% and discount rate 3% (July 2026)', 'https://discovermni.com/2026/07/13/communique-of-the-113th-meeting-of-the-monetary-council-of-the-eastern-caribbean-central-bank/', '2026-10-31', 'Low case: mostly tax-free savings deposits near the 0.95% average deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GD', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched Government of Grenada and ECCB/RGSM sources: no government savings certificate or retail savings bond for individuals was found; government borrowing is through Treasury bills on the Regional Government Securities Market.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GD', 1, 'savings_account_rate', 0.02, NULL, 'sourced', 'ECCB Monetary Council, communique of the 113th meeting (10 July 2026): Minimum Savings Rate', 'https://discovermni.com/2026/07/13/communique-of-the-113th-meeting-of-the-monetary-council-of-the-eastern-caribbean-central-bank/', '2026-07-10', 'The ECCB Minimum Savings Rate of 2.0% is the floor banks must pay on savings deposits; banks'' posted savings rates are generally at or near this floor.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GD', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":5.4},{"year":2040,"value":4.1},{"year":2065,"value":2}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/grenada/2040/', '2025-12-31', '100 / old-age dependency ratio: 18.5 (2025, World Bank), 24.2 (2040) and 50.7 (2065, populationpyramid.net/grenada/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GD', 1, 'tax_bank_interest', 0, NULL, 'sourced', 'Income Tax Act Cap. 149 (Grenada), s.25(1)(aa)', 'https://grenadaparliament.gd/wp-content/uploads/2021/08/Cap149-INCOME-TAX-ACT.pdf', '2021-08-01', 'Interest accruing from deposits to individuals resident in Grenada is exempt from income tax (since 31 March 1995); s.53 sets 0% withholding on deposit interest to non-residents. Consolidated text dated 2021 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GD', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate exists for individuals in Grenada (see sanchayapatra_5y_rate), so no tax rate applies; the Income Tax Act exempts only interest on government loans declared exempt by the Minister (s.25(1)(f)).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GD', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Government of Grenada sells 91-day Treasury bills on the Regional Government Securities Market (a June 2026 auction cleared near 3.5%), but the result is published only by the regional securities exchange company, which may not be cited; the ECCB site blocks automated access.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GD', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched RGSM and ECCB debt pages: no current 10-year Government of Grenada bond yield is published.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GD', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched RGSM and ECCB debt pages: no current 5-year Government of Grenada bond yield is published.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('GE', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"GE","iso3":"GEO","nameEn":"Georgia","nameNative":"საქართველო","region":"europe_central_asia","languages":["ka","ru","en","hy"],"currency":{"code":"GEL","symbol":"₾","decimals":2,"compact":"intl","usdRate":{"value":2.5992,"status":"sourced","sourceName":"National Bank of Georgia official exchange rate (USD)","sourceUrl":"https://nbg.gov.ge/gw/api/ct/monetarypolicy/currencies/en/json/?currencies=USD&date=2026-10-31","asOf":"2026-10-31","note":"GEL 2.5992 per US dollar, set on 30 October 2026 and valid from 31 October 2026; World Bank 2025 average 2.743."}},"instruments":{"savings_account":{"available":true,"localName":"შემნახველი ანგარიში","localNameEn":"Savings (demand deposit) account","note":"Offered in lari and in US dollars or euros; foreign-currency deposits pay much less.","sourceUrl":"https://nbg.gov.ge/en/effective-interest-rates-for-deposits"},"fdr_3m":{"available":true,"localName":"ვადიანი ანაბარი","localNameEn":"Term deposit (3 months)","sourceUrl":"https://nbg.gov.ge/en/effective-interest-rates-for-deposits"},"fdr_1y":{"available":true,"localName":"ვადიანი ანაბარი","localNameEn":"Term deposit (1 year)","sourceUrl":"https://nbg.gov.ge/en/effective-interest-rates-for-deposits"},"dps":{"available":true,"localName":"დაგროვებითი ანაბარი","localNameEn":"Accumulative savings deposit","note":"Deposit with regular top-ups; terms vary by bank."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate for individuals; interest on government securities is tax-exempt for individuals."},"tbill_91d":{"available":true,"localName":"სახაზინო ვალდებულება","localNameEn":"Treasury bill","note":"Discount bills with maturities up to one year, auctioned by the Ministry of Finance through the NBG mainly to banks.","sourceUrl":"https://nbg.gov.ge/en/page/government-securities"},"tbond_5y":{"available":true,"localName":"სახაზინო ობლიგაცია","localNameEn":"Treasury note","sourceUrl":"https://nbg.gov.ge/en/page/government-securities"},"tbond_10y":{"available":true,"localName":"სახაზინო ობლიგაცია","localNameEn":"Treasury bond","sourceUrl":"https://nbg.gov.ge/en/page/government-securities"},"equity_fund":{"available":true,"localName":"საინვესტიციო ფონდი","localNameEn":"Investment fund","note":"Few domestic funds; residents mainly reach diversified index funds abroad through brokerage accounts."},"gold":{"available":true,"localName":"ოქროს ზოდები და მონეტები","localNameEn":"Gold bars and coins","note":"Legal to buy and hold."}},"institutions":{"centralBank":{"name":"National Bank of Georgia","url":"https://nbg.gov.ge/en"},"insuranceRegulator":{"name":"Insurance State Supervision Service of Georgia","url":"https://insurance.gov.ge/en"},"insuranceComplaints":{"name":"Insurance State Supervision Service of Georgia, consumer page","url":"https://insurance.gov.ge/en","note":"The regulator handles consumer questions about insurers; disputes go to the courts."},"pensionScheme":{"name":"Pension Agency of Georgia (funded pension)","url":"https://www.pensions.ge/"},"oldAgeAllowance":{"name":"Social Service Agency (state pension)","url":"https://ssa.moh.gov.ge/"},"publicHealthCover":{"name":"Universal Healthcare Programme (Social Service Agency)","url":"https://ssa.moh.gov.ge/"},"depositInsurance":{"name":"Deposit Insurance Agency","url":"https://www.dia.ge/"},"statistics":{"name":"National Statistics Office of Georgia (Geostat)","url":"https://www.geostat.ge/en"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GE', 1, 'bank_deposit_avg_rate', 0.0909, NULL, 'sourced', 'Trading Economics (IMF), Georgia deposit interest rate', 'https://tradingeconomics.com/georgia/deposit-interest-rate', '2026-08-31', 'Average rate paid by commercial banks on deposits, August 2026 (9.30% in July); secondary source citing the IMF; World Bank FR.INR.DPST 2025 average 10.6%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GE', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No page stating a legal interest-rate cap or a typical credit card rate could be read; NBG loan-rate statistics load by script.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GE', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'Georgia has a deposit insurance scheme (Deposit Insurance Agency), but dia.ge refused the connection and no other official page stating the current limit per depositor could be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GE', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Banks offer accumulative savings deposits with regular top-ups, but the NBG comparison table does not list them and no published rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GE', 1, 'equity_return_base', 0.09, NULL, 'assumption', 'Global equity long-run return about 7% in USD; GEL per USD 2.60 (NBG); inflation gap with the US about 2 points', 'https://nbg.gov.ge/gw/api/ct/monetarypolicy/currencies/en/json/?currencies=USD', '2026-10-31', 'The Georgian Stock Exchange is tiny and illiquid, so the base is a global index fund in lari: about 7% in dollars plus about 2% a year of expected lari depreciation, within 4 points of the after-tax deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GE', 1, 'equity_return_high', 0.12, NULL, 'assumption', 'Global equity long-run returns; lari depreciation of 2005-2025', 'https://nbg.gov.ge/gw/api/ct/monetarypolicy/currencies/en/json/?currencies=USD', '2026-10-31', 'High case: strong global equity returns plus faster lari depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GE', 1, 'equity_return_low', 0.05, NULL, 'assumption', 'No meaningful local stock market (Trading Economics tracks no Georgian index); global equities in GEL; after-tax 1-year GEL deposit 9.05% less 5% = 8.6%', 'https://tradingeconomics.com/georgia/stock-market', '2026-10-31', 'Low case: global shares earn about 4% in dollars and the lari stays stable, well below safe lari deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GE', 1, 'fdr_1y_rate', 0.0905, NULL, 'sourced', 'National Bank of Georgia, effective interest rates on deposits (bank comparison table)', 'https://nbg.gov.ge/en/effective-interest-rates-for-deposits', '2026-10-31', 'Average effective rate on 12-month GEL term deposits at the two largest banks (8.85% and 9.25%); other banks 8-10.2%; USD 12-month deposits pay 1.4-4%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GE', 1, 'fdr_3m_rate', 0.086, NULL, 'sourced', 'National Bank of Georgia, effective interest rates on deposits (bank comparison table)', 'https://nbg.gov.ge/en/effective-interest-rates-for-deposits', '2026-10-31', 'Average effective rate on 3-month GEL term deposits at the two largest banks (8.40% and 8.83%); other banks 6.1-9.7%; USD 3-month deposits pay 1-2.6%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GE', 1, 'fixed_income_return_base', 0.08, NULL, 'assumption', '12-month GEL deposits 9.05% less 5% tax = 8.6% (NBG comparison table)', 'https://nbg.gov.ge/en/effective-interest-rates-for-deposits', '2026-10-31', 'Base case: a little below today''s after-tax 1-year lari deposit rate, allowing for some easing.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GE', 1, 'fixed_income_return_high', 0.09, NULL, 'assumption', 'Highest 12-month GEL deposit rates 9.6-10.2% (NBG comparison table) less 5% tax', 'https://nbg.gov.ge/en/effective-interest-rates-for-deposits', '2026-10-31', 'High case: rates stay high and savers use the better-paying banks or tax-free treasury securities.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GE', 1, 'fixed_income_return_low', 0.065, NULL, 'assumption', 'NBG policy rate 8.25%; GEL deposit rates (NBG comparison table)', 'https://nbg.gov.ge/en/effective-interest-rates-for-deposits', '2026-10-31', 'Low case: deposit rates fall as inflation returns to the 3% target, giving about 6.5% after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GE', 1, 'goal_inflation_education', 0.06, NULL, 'assumption', 'Geostat October 2026: school education prices up 6.6-8.8% year on year, tertiary down 32.9%; planning inflation 4.5%', 'https://geostat.ge/media/83801/Inflation-Rate-in-Georgia%2C-October-2026.pdf', '2026-10-31', 'Pre-primary, primary and secondary fees are rising well above headline inflation while the tertiary fall reflects a one-off policy change, so 6% is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GE', 1, 'goal_inflation_health', 0.06, NULL, 'assumption', 'Geostat: health prices up 8.4% year on year in October 2026 (out-patient services 11.7%); out-of-pocket share of health spending 59% (World Bank)', 'https://geostat.ge/media/83801/Inflation-Rate-in-Georgia%2C-October-2026.pdf', '2026-10-31', 'Medicine and private care are mostly paid out of pocket and health prices are rising faster than headline inflation, but 8.4% reflects the current spike, so 6% is used for the long run.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GE', 1, 'gold_return_base', 0.06, NULL, 'assumption', 'Gold price history (Trading Economics); NBG 3% target vs 2% US inflation', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Base case: dollar gold rises about 4% a year and the lari loses about 2% a year against the dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GE', 1, 'gold_return_high', 0.09, NULL, 'assumption', 'Gold price history (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'High case: a repeat of gold''s strong 2005-2025 trend plus lari depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GE', 1, 'gold_return_low', 0.02, NULL, 'assumption', 'Gold USD 3,876/oz on 30 Oct 2026, 31% below the January 2026 high (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Low case: gold barely keeps up after the 2025-26 spike and the lari stays stable.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GE', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No statutory gratuity or end-of-service payment per year of service was found; the Labour Code text could not be read to confirm severance rules on dismissal.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GE', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Universal Healthcare Programme pays part of hospital costs with patient co-payments; no official figure for a typical out-of-pocket cost of a major private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GE', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Private health insurance is sold as fixed packages, not per sum insured, and no published premium table per GEL 100,000 of cover was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GE', 1, 'inflation_cpi', 0.059, NULL, 'sourced', 'National Statistics Office of Georgia (Geostat), Inflation Rate in Georgia, October 2026', 'https://geostat.ge/media/83801/Inflation-Rate-in-Georgia%2C-October-2026.pdf', '2026-10-31', 'Annual CPI inflation 5.9% in October 2026 (5.6% in September; core 4.0%), published 3 November 2026. World Bank 2025 average 3.9%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GE', 1, 'inflation_projection', 0.045, NULL, 'assumption', 'National Bank of Georgia 3% inflation target; CPI 5.9% (Oct 2026, Geostat), 3.9% in 2025 (World Bank)', 'https://geostat.ge/media/83801/Inflation-Rate-in-Georgia%2C-October-2026.pdf', '2026-10-31', 'Inflation has averaged well above the 3% target over the last five years (including 10-12% in 2021-22), so 4.5% is used for planning.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GE', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life cover is sold mainly as credit-linked or group cover; no published premium table per GEL 1,000 of cover by age was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GE', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Insurance State Supervision Service publishes market statistics but no life claim settlement ratio could be found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GE', 1, 'life_expectancy', 75, NULL, 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/georgia', '2026-07-01', 'Men 70.1, women 79.5 (UN WPP estimate for 2026); World Bank 2024 figure 74.7.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GE', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":20,"men":16.8,"women":22.4},{"age":65,"total":16.3,"men":13.6,"women":18.3},{"age":70,"total":13,"men":10.6,"women":14.5},{"age":80,"total":7.5,"men":5.6,"women":8.4}]}', 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/georgia', '2026-07-01', 'Remaining years computed from georank''s expected age at death by current age (UN WPP 2026 estimate, mid-year).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GE', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'Georgia pays a flat state pension from age 65 (men) and 60 (women) (Trading Economics citing the Social Service Agency), but no readable source confirmed whether it is means-tested or its residence conditions: the Social Service Agency and Ministry of Health sites refused automated access.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GE', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'Georgia pays a flat non-contributory state pension, but the Social Service Agency, Ministry of Health and Ministry of Finance pages refused automated access and no source stating the 2026 amount could be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GE', 1, 'oop_health_share', 0.5876, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=GE', '2023-12-31', 'Latest World Bank figure is for 2023 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GE', 1, 'policy_rate', 0.0825, NULL, 'sourced', 'Trading Economics (National Bank of Georgia refinancing rate)', 'https://tradingeconomics.com/georgia/interest-rate', '2026-10-21', 'Monetary policy rate held at 8.25% on 21 October 2026; next decision 16 December 2026. Secondary source because nbg.gov.ge loads its rate by script.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GE', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":65,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'Law of Georgia on Funded Pension (matsne.gov.ge); retirement ages via Trading Economics', 'https://matsne.gov.ge/en/document/view/4280127', '2026-10-31', 'Mandatory funded pension (Pension Agency) since 2019 for employees: 2% of salary from the employee, 2% from the employer and 2% from the state (1% on income GEL 24,000-60,000, none above) (Art. 3(6)); savings can be drawn at the state pension age (Art. 2(q), 24), 65 for men and 60 for women; returns depend on investment, so payouts are not inflation-linked. Employees aged 40+ at launch could opt out (Art. 22).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GE', 1, 'retirement_accumulation_return_base', 0.085, NULL, 'assumption', 'After-tax GEL deposits 8.6%; global equity in GEL 9%', 'https://nbg.gov.ge/en/effective-interest-rates-for-deposits', '2026-10-31', 'Base case: roughly half lari deposits and half global shares in lari terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GE', 1, 'retirement_accumulation_return_high', 0.105, NULL, 'assumption', 'After-tax GEL deposits 8.6%; global equity high case 12%', 'https://nbg.gov.ge/en/effective-interest-rates-for-deposits', '2026-10-31', 'High case for a growth-leaning mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GE', 1, 'retirement_accumulation_return_low', 0.065, NULL, 'assumption', 'After-tax GEL deposits 8.6%; global equity low case 5%', 'https://nbg.gov.ge/en/effective-interest-rates-for-deposits', '2026-10-31', 'Low case for a balanced mix if global shares lag and deposit rates fall.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GE', 1, 'retirement_age_default', 65, NULL, 'sourced', 'Trading Economics (Social Service Agency of Georgia), retirement age men and women', 'https://tradingeconomics.com/georgia/retirement-age-men', '2026-10-31', 'State pension age 65 for men and 60 for women (Trading Economics citing the Social Service Agency, 2026); the Funded Pension Law (Art. 2(q)) uses the same age, defined by the Law on State Pensions.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GE', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'No official page stating the retirement or age limit for public servants could be read; the state pension age (65 men, 60 women) applies to all.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GE', 1, 'retirement_return_base', 0.08, NULL, 'assumption', '12-month GEL deposits 9.05% less 5% tax = 8.6% (NBG comparison table)', 'https://nbg.gov.ge/en/effective-interest-rates-for-deposits', '2026-10-31', 'Base case capped below the after-tax 1-year lari deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GE', 1, 'retirement_return_high', 0.086, NULL, 'assumption', '12-month GEL deposits 9.05% less 5% tax = 8.6%', 'https://nbg.gov.ge/en/effective-interest-rates-for-deposits', '2026-10-31', 'High case: today''s after-tax 1-year deposit rate holds for the long run.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GE', 1, 'retirement_return_low', 0.06, NULL, 'assumption', 'NBG policy rate 8.25%; GEL deposit rates (NBG comparison table)', 'https://nbg.gov.ge/en/effective-interest-rates-for-deposits', '2026-10-31', 'Low case: lari deposit rates fall toward 6-7% as inflation settles.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GE', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate or dedicated retail savings bond for individuals was found; treasury notes and bonds are auctioned by the Ministry of Finance mainly to banks.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GE', 1, 'savings_account_rate', 0.05, NULL, 'sourced', 'National Bank of Georgia, effective interest rates on deposits (bank comparison table)', 'https://nbg.gov.ge/en/effective-interest-rates-for-deposits', '2026-10-31', 'Median effective rate on GEL demand deposits (daily balance) among banks that list one, about 5%; the two largest banks'' demand entries are not usable, and USD demand deposits pay about 0.5-1%. Table date not shown; read 31 October 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GE', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":3.97},{"year":2040,"value":3.42},{"year":2065,"value":2.53}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/georgia/2040/', '2025-12-31', '100 / old-age dependency ratio: 25.2 (2025, World Bank), 29.2 (2040) and 39.5 (2065, populationpyramid.net/georgia/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GE', 1, 'tax_bank_interest', 0.05, NULL, 'sourced', 'Tax Code of Georgia, Article 131 (matsne.gov.ge)', 'https://matsne.gov.ge/en/document/view/1043717', '2026-10-31', 'Interest paid to an individual is taxed at source at 5% and is then final: it is not included in gross income or taxed further (Article 131(1) and (3)).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GE', 1, 'tax_sanchayapatra_profit', 0, NULL, 'sourced', 'Tax Code of Georgia, Article 82(1)(s) (matsne.gov.ge)', 'https://matsne.gov.ge/en/document/view/1043717', '2026-10-31', 'No government savings certificate exists; interest on government debt securities and NBG securities held by individuals is exempt from income tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GE', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Ministry of Finance treasury bill auctions (maturities up to one year) are published on mof.ge and nbg.gov.ge, but the result pages load by script and no yield could be read; a 91-day bill may not be issued.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GE', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', '10-year treasury bond yields appear in Ministry of Finance auction results, but the pages load by script and no figure could be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GE', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', '5-year treasury note yields appear in Ministry of Finance auction results and the NBG GEL yield curve, but both pages load by script and no figure could be read; Trading Economics shows no Georgia bond yield.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('GH', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"GH","iso3":"GHA","nameEn":"Ghana","nameNative":"Ghana","region":"sub_saharan_africa","languages":["ak","en","ee","gaa","ha"],"currency":{"code":"GHS","symbol":"GH₵","decimals":2,"compact":"intl","usdRate":{"value":11.62,"status":"sourced","sourceName":"Bank of Ghana, daily interbank FX rates, 30 October 2026 (USD/GHS mid rate)","sourceUrl":"https://www.bog.gov.gh/treasury-and-the-markets/daily-interbank-fx-rates/","asOf":"2026-10-30","note":"Mid rate 11.6200 (buying 11.6142, selling 11.6258); the World Bank 2025 average was 12.56."}},"instruments":{"savings_account":{"available":true,"localName":"Savings account","localNameEn":null,"note":"Average savings deposit rate 4.10% in August 2026 (Bank of Ghana).","sourceUrl":"https://www.bog.gov.gh/wp-content/uploads/2026/09/Summary-of-Economic-and-Financial-Data-September-2026.pdf"},"fdr_3m":{"available":true,"localName":"Fixed deposit (3 months)","localNameEn":"Time deposit (3 months)","note":"Average 3-month time deposit rate 8.68% in August 2026 (Bank of Ghana).","sourceUrl":"https://www.bog.gov.gh/wp-content/uploads/2026/09/Summary-of-Economic-and-Financial-Data-September-2026.pdf"},"fdr_1y":{"available":true,"localName":"Fixed deposit (1 year)","localNameEn":"Time deposit (1 year)","note":"Banks take 1-year deposits, but the Bank of Ghana publishes only 3- and 6-month averages."},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No standard monthly recurring deposit product with a published rate was found."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate for individuals was found; individuals buy Treasury bills and bonds instead."},"tbill_91d":{"available":true,"localName":"91-day Treasury bill","localNameEn":null,"note":"Auctioned weekly by the Bank of Ghana; individuals buy through banks and licensed dealers, and the interest is tax-exempt.","sourceUrl":"https://www.bog.gov.gh/treasury-and-the-markets/treasury-bill-rates/"},"tbond_5y":{"available":true,"localName":"Government of Ghana 5-year bond","localNameEn":null,"note":"Post-debt-exchange (DDEP) bonds trade on the Ghana Fixed Income Market.","sourceUrl":"https://www.bog.gov.gh/wp-content/uploads/2026/09/Summary-of-Economic-and-Financial-Data-September-2026.pdf"},"tbond_10y":{"available":true,"localName":"Government of Ghana 10-year bond","localNameEn":null,"note":"Post-debt-exchange (DDEP) bonds trade on the Ghana Fixed Income Market.","sourceUrl":"https://www.bog.gov.gh/wp-content/uploads/2026/09/Summary-of-Economic-and-Financial-Data-September-2026.pdf"},"equity_fund":{"available":true,"localName":"Mutual fund / unit trust","localNameEn":null,"note":"Collective investment schemes licensed by the Securities and Exchange Commission invest in Ghana Stock Exchange shares and fixed income."},"gold":{"available":true,"localName":"Gold","localNameEn":null,"note":"Gold bars and jewellery can be bought legally; Ghana is a major gold producer and the trade is regulated by the state."}},"institutions":{"centralBank":{"name":"Bank of Ghana","url":"https://www.bog.gov.gh/"},"insuranceRegulator":{"name":"National Insurance Commission (NIC)","url":"https://nic.gov.gh/"},"insuranceComplaints":{"name":"National Insurance Commission, file a complaint","url":"https://nic.gov.gh/consumers/complaints"},"pensionScheme":{"name":"Social Security and National Insurance Trust (SSNIT), old-age pension","url":"https://www.ssnit.org.gh/old-age-benefit/","note":"First tier of the three-tier pension system; the National Pensions Regulatory Authority (npra.gov.gh) supervises the second and third tiers."},"oldAgeAllowance":null,"publicHealthCover":{"name":"National Health Insurance Scheme (NHIS)","url":"https://www.nhis.gov.gh/"},"depositInsurance":{"name":"Ghana Deposit Protection Corporation (GDPC)","url":"https://gdpc.gov.gh/deposit-insurance/deposit-coverage"},"statistics":{"name":"Ghana Statistical Service","url":"https://statsghana.gov.gh/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GH', 1, 'bank_deposit_avg_rate', 0.105, NULL, 'sourced', 'World Bank WDI, deposit interest rate (FR.INR.DPST), Ghana', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=GH', '2025-12-31', '10.5% for 2025 (World Bank, from IMF data); it matches the Bank of Ghana 3-month time deposit rate through mid-2026, which has since fallen to 8.68% (August 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GH', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap or published typical credit card rate was found; the Bank of Ghana reports an average bank lending rate of 15.94% in August 2026 (Summary of Economic and Financial Data), which is not card-specific.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GH', 1, 'deposit_insurance_limit', 6250, NULL, 'sourced', 'Ghana Deposit Protection Corporation (GDPC), deposit coverage', 'https://gdpc.gov.gh/deposit-insurance/deposit-coverage', '2026-10-31', 'Up to GHS 6,250 per depositor per bank (GHS 1,250 at a specialised deposit-taking institution); a 2026 GDPC directive says these limits stay in force while the board reviews them under the Ghana Deposit Protection (Amendment) Act passed in March 2026 (gdpc.gov.gh/media-news/details/321).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GH', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published rate for a monthly recurring deposit product was found; the Bank of Ghana publishes demand, savings and 3- and 6-month time deposit rates only.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GH', 1, 'equity_return_base', 0.125, NULL, 'assumption', 'Bank of Ghana Summary of Economic and Financial Data, September 2026: GSE Composite Index and Treasury bill rates', 'https://www.bog.gov.gh/wp-content/uploads/2026/09/Summary-of-Economic-and-Financial-Data-September-2026.pdf', '2026-10-31', 'Base case: about 3 points above the tax-free 364-day bill rate (9.67%), within the 4-point cap; the GSE Composite Index rose 79% in 2025 and another 72% to August 2026, but its decade before that was weak and the market is small.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GH', 1, 'equity_return_high', 0.17, NULL, 'assumption', 'Bank of Ghana Summary of Economic and Financial Data, September 2026: GSE Composite Index and Treasury bill rates', 'https://www.bog.gov.gh/wp-content/uploads/2026/09/Summary-of-Economic-and-Financial-Data-September-2026.pdf', '2026-10-31', 'High case: the Ghana Stock Exchange keeps part of the momentum of its 2025-2026 rally.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GH', 1, 'equity_return_low', 0.08, NULL, 'assumption', 'Bank of Ghana Summary of Economic and Financial Data, September 2026: GSE Composite Index and Treasury bill rates', 'https://www.bog.gov.gh/wp-content/uploads/2026/09/Summary-of-Economic-and-Financial-Data-September-2026.pdf', '2026-10-31', 'Low case: Ghana Stock Exchange returns fall back to roughly the 91-day bill and savings rates for a long stretch, as in the weak 2017-2022 years.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GH', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Bank of Ghana''s Summary of Economic and Financial Data (September 2026) gives 3-month (8.68%) and 6-month (9.72%) time deposit rates only; no published 1-year average deposit rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GH', 1, 'fdr_3m_rate', 0.0868, NULL, 'sourced', 'Bank of Ghana, Summary of Economic and Financial Data, September 2026 (table 3a, 3-month time deposits)', 'https://www.bog.gov.gh/wp-content/uploads/2026/09/Summary-of-Economic-and-Financial-Data-September-2026.pdf', '2026-08-31', 'Average 3-month time deposit rate 8.68% in August 2026, down from 10.50% through June 2026; the 6-month rate was 9.72%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GH', 1, 'fixed_income_return_base', 0.08, NULL, 'assumption', 'Bank of Ghana: 3-month deposit 8.68%, 364-day bill 9.67%; interest tax-exempt for individuals (PwC)', 'https://www.bog.gov.gh/wp-content/uploads/2026/09/Summary-of-Economic-and-Financial-Data-September-2026.pdf', '2026-10-31', 'Base case: a mix of 3- to 6-month time deposits (8.7-9.7%) and 182- to 364-day bills (6.3-9.7%), all tax-exempt for individuals.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GH', 1, 'fixed_income_return_high', 0.11, NULL, 'assumption', 'Bank of Ghana: 364-day bill 9.67%; 5-year bond 12.73% (secondary market, August 2026)', 'https://www.bog.gov.gh/wp-content/uploads/2026/09/Summary-of-Economic-and-Financial-Data-September-2026.pdf', '2026-10-31', 'High case: part of the money in 364-day bills and Government of Ghana bonds, net of default and liquidity risk after the 2023 domestic debt exchange.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GH', 1, 'fixed_income_return_low', 0.05, NULL, 'assumption', 'Bank of Ghana: savings deposit rate 4.10%, 91-day bill 4.61%, 364-day bill 9.67%; interest tax-exempt for individuals (PwC)', 'https://www.bog.gov.gh/treasury-and-the-markets/treasury-bill-rates/', '2026-10-31', 'Low case: savings accounts and 91-day bills at about 4-5%, which are tax-exempt for individuals.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GH', 1, 'goal_inflation_education', 0.1, NULL, 'assumption', 'Bank of Ghana 8% ± 2% inflation target (MPC, September 2026)', 'https://www.bog.gov.gh/wp-content/uploads/2026/10/MPC-Decision-Statement-September-2026.pdf', '2026-10-31', 'No education CPI series was read; private school and university fees usually rise faster than general prices, so education goals use 2 points above the 8% planning inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GH', 1, 'goal_inflation_health', 0.1, NULL, 'assumption', 'Bank of Ghana 8% ± 2% inflation target (MPC, September 2026)', 'https://www.bog.gov.gh/wp-content/uploads/2026/10/MPC-Decision-Statement-September-2026.pdf', '2026-10-31', 'No health CPI series was read; private and imported medical costs usually rise faster than general prices, so health goals use 2 points above the 8% planning inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GH', 1, 'gold_return_base', 0.09, NULL, 'assumption', 'Bank of Ghana: international gold price (Summary of Economic and Financial Data) and USD/GHS interbank rate', 'https://www.bog.gov.gh/wp-content/uploads/2026/09/Summary-of-Economic-and-Financial-Data-September-2026.pdf', '2026-10-31', 'Base case: long-run dollar gold trend of about 4% a year plus about 5% a year cedi depreciation (the gap between the 8% target and dollar inflation).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GH', 1, 'gold_return_high', 0.16, NULL, 'assumption', 'Bank of Ghana: international gold price (Summary of Economic and Financial Data) and USD/GHS interbank rate', 'https://www.bog.gov.gh/wp-content/uploads/2026/09/Summary-of-Economic-and-Financial-Data-September-2026.pdf', '2026-10-31', 'High case: strong gold years combined with a cedi slide like 2022-2024.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GH', 1, 'gold_return_low', 0.03, NULL, 'assumption', 'Bank of Ghana: international gold price (Summary of Economic and Financial Data) and USD/GHS interbank rate', 'https://www.bog.gov.gh/wp-content/uploads/2026/09/Summary-of-Economic-and-Financial-Data-September-2026.pdf', '2026-10-31', 'Low case: flat dollar gold with modest cedi depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GH', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Labour Act, 2003 (Act 651, official text hosted by the Ghana Investment Promotion Centre at gipc.gov.gh/wp-content/uploads/2024/07/LABOUR-ACT-2003-Act-651.pdf) has no gratuity or end-of-service payment for private employees; section 65 only requires redundancy pay whose amount is negotiated, and gratuities exist only in contracts or collective agreements.', 1);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GH', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical out-of-pocket cost of a major private hospital stay in Ghana was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GH', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premiums by age were found from the National Insurance Commission or the National Health Insurance Authority.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GH', 1, 'inflation_cpi', 0.05, NULL, 'sourced', 'Bank of Ghana, Summary of Economic and Financial Data, September 2026 (table 1, year-on-year inflation, Ghana Statistical Service CPI)', 'https://www.bog.gov.gh/wp-content/uploads/2026/09/Summary-of-Economic-and-Financial-Data-September-2026.pdf', '2026-08-31', '5.0% year on year in August 2026 (4.6% in July, 5.4% in December 2025, 23.8% in December 2024). The Ghana Statistical Service home page shows 5.2% for September 2026, but no September release page could be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GH', 1, 'inflation_projection', 0.08, NULL, 'assumption', 'Bank of Ghana medium-term inflation target of 8% ± 2% (MPC, September 2026)', 'https://www.bog.gov.gh/wp-content/uploads/2026/10/MPC-Decision-Statement-September-2026.pdf', '2026-10-31', 'Inflation has fallen from over 20% in 2024 to about 5% in 2026, below the band, but the 5-year average is far higher, so the centre of the Bank of Ghana''s 8% ± 2% target is used for long-range plans.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GH', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life cover is sold by licensed life insurers, but no published premium rates per GHS 1,000 of cover by age were found from the National Insurance Commission or another public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GH', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The National Insurance Commission reports that insurers paid GHS 3.6 billion in claims in 2024 (nic.gov.gh), but no industry-wide life claim settlement ratio was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GH', 1, 'life_expectancy', 65.695, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN), Ghana', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=GH', '2024-12-31', '65.7 years in 2024 (men 63.3, women 68.2).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GH', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":17.5,"men":16.6,"women":18.4},{"age":65,"total":14.1,"men":13.3,"women":14.7},{"age":70,"total":10.9,"men":10.3,"women":11.5},{"age":80,"total":6.1,"men":5.7,"women":6.4}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/ghana/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GH', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension was found (see old_age_allowance_monthly).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GH', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'No universal non-contributory old-age pension was found; the LEAP cash transfer (Ministry of Gender, Children and Social Protection) reaches extremely poor households, including those with members aged 65+ without support, but it is a household benefit set by household size, not a per-person social pension.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GH', 1, 'oop_health_share', 0.2668, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), Ghana', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=GH', '2023-12-31', '26.7% in 2023 (WHO Global Health Expenditure Database via the World Bank), the latest available; older than 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GH', 1, 'policy_rate', 0.14, NULL, 'sourced', 'Bank of Ghana, MPC decision statement, September 2026', 'https://www.bog.gov.gh/wp-content/uploads/2026/10/MPC-Decision-Statement-September-2026.pdf', '2026-09-24', 'Monetary Policy Rate held at 14.0% at the 132nd MPC meeting (23-24 September 2026); it was cut from 18% to 14% between December 2025 and March 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GH', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":60,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":true}', 'sourced', 'SSNIT, Superannuation (old age) pension; Constitution of Ghana article 199(4) (pensions exempt from tax)', 'https://www.ssnit.org.gh/old-age-benefit/', '2026-10-31', 'Compulsory first-tier SSNIT pension under Act 766: 37.5% of the average of the best three years'' salaries after 180 months of contributions, plus 1.125% per extra year, up to 60% after 420 months; full pension at 60, reduced from 55, paid until death. Pensions are reviewed yearly by the SSNIT board rather than linked to the CPI by law; the Constitution exempts pensions from tax. The SSNIT page states no minimum entry age, so entryAgeMin is left empty.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GH', 1, 'retirement_accumulation_return_base', 0.1, NULL, 'assumption', 'Safe rate about 8%; equity base 12.5%; gold base 9% (our assumptions above)', 'https://www.bog.gov.gh/wp-content/uploads/2026/09/Summary-of-Economic-and-Financial-Data-September-2026.pdf', '2026-10-31', 'Base case: a balanced mix of bills and bonds, equity funds and some gold.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GH', 1, 'retirement_accumulation_return_high', 0.13, NULL, 'assumption', 'Safe rate about 8%; equity base 12.5%; gold base 9% (our assumptions above)', 'https://www.bog.gov.gh/wp-content/uploads/2026/09/Summary-of-Economic-and-Financial-Data-September-2026.pdf', '2026-10-31', 'High case: a growth-leaning mix with more equity.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GH', 1, 'retirement_accumulation_return_low', 0.07, NULL, 'assumption', 'Safe rate about 8%; equity base 12.5%; gold base 9% (our assumptions above)', 'https://www.bog.gov.gh/wp-content/uploads/2026/09/Summary-of-Economic-and-Financial-Data-September-2026.pdf', '2026-10-31', 'Low case: mostly deposits and bills with weak equity years.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GH', 1, 'retirement_age_default', 60, NULL, 'sourced', 'SSNIT, Superannuation (old age) pension', 'https://www.ssnit.org.gh/old-age-benefit/', '2026-10-31', 'Full SSNIT pension at 60 with at least 180 months of contributions; reduced pension from 55. Same for men and women.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GH', 1, 'retirement_age_government', 60, NULL, 'sourced', 'Constitution of Ghana, article 199 (Constitute Project text)', 'https://www.constituteproject.org/constitution/Ghana_1996?lang=en', '1996-12-31', 'A public officer retires from the public service at 60 (voluntary retirement possible from 45) under article 199 of the 1992 Constitution (text as amended in 1996); the rule predates 2025 but is still in force.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GH', 1, 'retirement_return_base', 0.08, NULL, 'assumption', 'Bank of Ghana: 3-month deposit 8.68%, 364-day bill 9.67% (tax-exempt for individuals)', 'https://www.bog.gov.gh/treasury-and-the-markets/treasury-bill-rates/', '2026-10-31', 'Base case: a ladder of time deposits and 182- to 364-day bills, below the tax-free 364-day bill rate of 9.67%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GH', 1, 'retirement_return_high', 0.1, NULL, 'assumption', 'Bank of Ghana: 364-day bill 9.67%; 5-year bond 12.73% (secondary market)', 'https://www.bog.gov.gh/wp-content/uploads/2026/09/Summary-of-Economic-and-Financial-Data-September-2026.pdf', '2026-10-31', 'High case: part of the money in Government of Ghana bonds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GH', 1, 'retirement_return_low', 0.05, NULL, 'assumption', 'Bank of Ghana: savings 4.10%, 91-day bill 4.61%, 364-day bill 9.67% (tax-exempt for individuals)', 'https://www.bog.gov.gh/treasury-and-the-markets/treasury-bill-rates/', '2026-10-31', 'Low case: savings accounts and short bills at about 4-5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GH', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate or retail savings bond for individuals was found; individuals buy Treasury bills and Government of Ghana bonds through banks and licensed dealers.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GH', 1, 'savings_account_rate', 0.041, NULL, 'sourced', 'Bank of Ghana, Summary of Economic and Financial Data, September 2026 (table 3a, savings deposits)', 'https://www.bog.gov.gh/wp-content/uploads/2026/09/Summary-of-Economic-and-Financial-Data-September-2026.pdf', '2026-08-31', 'Average savings deposit rate 4.10% in August 2026 (5.00% for most of 2025-2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GH', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":16.05},{"year":2040,"value":11.11},{"year":2065,"value":6.8}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://data.worldbank.org/indicator/SP.POP.DPND.OL?locations=GH', '2025-12-31', 'Working-age people per person 65+ = 100 / old-age dependency ratio. Old-age dependency ratios used: 6.23% in 2025 (World Bank), 9.0% in 2040 (populationpyramid.net/ghana/2040/) and 14.7% in 2065 (populationpyramid.net/ghana/2065/), giving 16.05, 11.11 and 6.8.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GH', 1, 'tax_bank_interest', 0, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Ghana, individual income determination (last reviewed 27 October 2026)', 'https://taxsummaries.pwc.com/ghana/individual/income-determination', '2026-10-27', 'Interest paid to individuals by a resident financial institution is exempt from income tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GH', 1, 'tax_sanchayapatra_profit', 0, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Ghana, individual income determination (last reviewed 27 October 2026)', 'https://taxsummaries.pwc.com/ghana/individual/income-determination', '2026-10-27', 'There is no savings certificate; interest paid to individuals on government bonds, including Treasury bills, is exempt from tax, so 0 is used for government securities.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GH', 1, 'tbill_91d_rate', 0.046135, NULL, 'sourced', 'Bank of Ghana, Treasury bill rates, tender 2030 (issue 26 October 2026)', 'https://www.bog.gov.gh/treasury-and-the-markets/treasury-bill-rates/', '2026-10-26', '91-day bill interest-equivalent rate 4.6135% (discount rate 4.5609%); 182-day 6.29% and 364-day 9.67% at the same tender.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GH', 1, 'tbond_10y_rate', 0.147, NULL, 'sourced', 'Bank of Ghana, Summary of Economic and Financial Data, September 2026 (table 3b, secondary market, post-DDEP 10-year bond)', 'https://www.bog.gov.gh/wp-content/uploads/2026/09/Summary-of-Economic-and-Financial-Data-September-2026.pdf', '2026-08-31', 'Secondary market yield of the post-debt-exchange (DDEP) 10-year bond, 14.70% in August 2026 (Ghana Fixed Income Market).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GH', 1, 'tbond_5y_rate', 0.1273, NULL, 'sourced', 'Bank of Ghana, Summary of Economic and Financial Data, September 2026 (table 3b, secondary market, post-DDEP 5-year bond)', 'https://www.bog.gov.gh/wp-content/uploads/2026/09/Summary-of-Economic-and-Financial-Data-September-2026.pdf', '2026-08-31', 'Secondary market yield of the post-debt-exchange (DDEP) 5-year bond, 12.73% in August 2026 (Ghana Fixed Income Market).', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('GM', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"GM","iso3":"GMB","nameEn":"Gambia","nameNative":"The Gambia","region":"sub_saharan_africa","languages":["mnk","wo","ff","en"],"currency":{"code":"GMD","symbol":"D","decimals":2,"compact":"intl","usdRate":{"value":72.92,"status":"sourced","sourceName":"Central Bank of The Gambia, official exchange rates for valuation purposes, 30 October 2026","sourceUrl":"https://www.cbg.gm/downloads-file/72f71090-d442-11f1-bfda-02ffeced4a91","asOf":"2026-10-30","note":"72.92 dalasi per US dollar on 30 October 2026; World Bank 2025 average 71.29. CLDR gives ''GMD'' as symbol; the dalasi is written ''D'' locally (e.g. D3.8 billion in CBG releases)."}},"instruments":{"savings_account":{"available":true,"localName":null,"localNameEn":"Savings account","note":"Banks paid 0.20-2.0% in December 2024 (CBG Annual Report 2024).","sourceUrl":"https://www.cbg.gm/downloads-file/4ddc97a8-fb6d-11f0-8725-02e599c15748"},"fdr_3m":{"available":true,"localName":null,"localNameEn":"Time deposit (3 months)","note":"Average 3-month deposit rate 3.3% at end-2024 (CBG).","sourceUrl":"https://www.cbg.gm/downloads-file/4ddc97a8-fb6d-11f0-8725-02e599c15748"},"fdr_1y":{"available":true,"localName":null,"localNameEn":"Time deposit (12 months)","note":"Banks quoted 0.20-9.26% for 12 months and over in December 2024 (CBG).","sourceUrl":"https://www.cbg.gm/downloads-file/4ddc97a8-fb6d-11f0-8725-02e599c15748"},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No standard monthly recurring deposit product with published rates was found."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate or retail savings bond; Treasury bills and bonds are sold by auction through the CBG."},"tbill_91d":{"available":true,"localName":null,"localNameEn":"Treasury bills (and Sukuk al-Salaam bills)","note":"Weekly CBG auctions of 91-, 182- and 364-day bills, plus Islamic Sukuk al-Salaam bills.","sourceUrl":"https://www.cbg.gm/auction-results"},"tbond_5y":{"available":true,"localName":null,"localNameEn":"Gambia Government Bonds","note":"2-, 3- and 5-year fixed-coupon bonds auctioned by the CBG; minimum bid GMD 200,000.","sourceUrl":"https://www.cbg.gm/bonds"},"tbond_10y":{"available":false,"localName":null,"localNameEn":null,"note":"No 10-year government bond is issued; the CBG lists only 2-, 3- and 5-year bonds.","sourceUrl":"https://www.cbg.gm/bonds"},"equity_fund":{"available":false,"localName":null,"localNameEn":null,"note":"The Gambia has no stock exchange and no locally licensed retail equity fund was found."},"gold":{"available":true,"localName":null,"localNameEn":"Gold","note":"No restriction on individuals owning gold was found; gold is mostly bought as jewellery and the CBG issues no bullion coins."}},"institutions":{"centralBank":{"name":"Central Bank of The Gambia (CBG)","url":"https://www.cbg.gm/"},"insuranceRegulator":{"name":"Central Bank of The Gambia, insurance supervision (Insurance Act 2003)","url":"https://www.cbg.gm/insurance"},"insuranceComplaints":{"name":"Central Bank of The Gambia, insurance supervision","url":"https://www.cbg.gm/insurance","note":"No dedicated insurance ombudsman or complaints page was found; the CBG regulates insurers and lists its contact details on this page."},"pensionScheme":{"name":"Social Security and Housing Finance Corporation (SSHFC), National Provident Fund","url":"https://www.sshfc.gm/national-provident-fund","note":"SSHFC also runs the Federated Pension Scheme for parastatal employees."},"oldAgeAllowance":null,"publicHealthCover":{"name":"National Health Insurance Authority (NHIA), National Health Insurance Scheme","url":"https://nhia.gm/membership/","note":"Residents without private cover must join under the NHIS Act 2021; people over 65, pensioners and children under five are exempt from contributions."},"depositInsurance":null,"statistics":{"name":"Gambia Bureau of Statistics (GBoS)","url":"https://www.gbosdata.org/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GM', 1, 'bank_deposit_avg_rate', 0.065, NULL, 'sourced', 'World Bank WDI, deposit interest rate (FR.INR.DPST), Gambia', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=GM', '2025-12-31', '6.5% in 2025 (IMF International Financial Statistics via the World Bank); the CBG''s own average 3-month deposit rate was 3.3% at end-2024, so this series likely reflects longer or larger deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GM', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap on card interest exists in CBG publications and no typical credit card rate is published; bank lending rates ranged 12-22% in December 2024 (CBG Annual Report 2024, Table 31).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GM', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Gambia has no deposit insurance scheme: the CBG Annual Report 2024 (section 4.2.2.1) says a Deposit Insurance Bill has been validated and banks will pay premiums only once it is passed into law; no enactment was found as of October 2026. Source: https://www.cbg.gm/downloads-file/4ddc97a8-fb6d-11f0-8725-02e599c15748', 1);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GM', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No standard monthly recurring deposit product or published rate was found in CBG statistics.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GM', 1, 'equity_return_base', 0.1, NULL, 'assumption', 'World Bank, official exchange rate GMD per USD (PA.NUS.FCRF)', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=GM', '2026-10-31', 'No local stock market: a global index at about 6% in dollars plus dalasi depreciation of about 4-5% a year (42.5 per dollar in 2015, 71.3 in 2025), capped at 3.5 points above the 6.5% safe-rate assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GM', 1, 'equity_return_high', 0.15, NULL, 'assumption', 'World Bank, official exchange rate GMD per USD (PA.NUS.FCRF)', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=GM', '2026-10-31', 'High case: strong global equities plus faster dalasi depreciation, as in 2022-2024.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GM', 1, 'equity_return_low', 0.04, NULL, 'assumption', 'World Bank, official exchange rate GMD per USD (PA.NUS.FCRF)', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=GM', '2026-10-31', 'The Gambia has no stock exchange, so equity means a global index fund in dalasi terms; the low case is a weak global decade with slow dalasi depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GM', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No average 1-year deposit rate was found; the CBG Annual Report 2024 (Table 31) gives only a range of 0.20-9.26% for time deposits of 12 months and over in December 2024, too wide to use.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GM', 1, 'fdr_3m_rate', 0.033, NULL, 'sourced', 'Central Bank of The Gambia, Annual Report 2024, key indicators: average 3-month deposit rate', 'https://www.cbg.gm/downloads-file/4ddc97a8-fb6d-11f0-8725-02e599c15748', '2024-12-31', 'Average 3-month deposit rate 3.3% at end-2024 (also 3.3% at end-2023); banks quoted 0.15-6.5% for 3-month time deposits. Older than 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GM', 1, 'fixed_income_return_base', 0.065, NULL, 'assumption', 'CBG Treasury bill auction 28 October 2026 (364 days 9.63%) and Annual Report 2024 deposit rates', 'https://www.cbg.gm/auction-results', '2026-10-31', 'Base case: a mix of 364-day Treasury bills (9.63%, but 7.6-14.8% over 2024-2026) and term deposits (3-6%); the tax on interest is unconfirmed, so the figure is kept conservative.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GM', 1, 'fixed_income_return_high', 0.09, NULL, 'assumption', 'CBG auction result, 5-year bond coupon 19.82% (14 October 2026)', 'https://www.cbg.gm/downloads-file/4bdcb0b4-c71a-11f1-945a-02e599c15748', '2026-10-31', 'High case: more in 364-day bills and 2-5 year government bonds (12-20% coupons in 2026), allowing for lower future yields and the GMD 200,000 minimum bond bid.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GM', 1, 'fixed_income_return_low', 0.03, NULL, 'assumption', 'Central Bank of The Gambia, Annual Report 2024: average 3-month deposit rate 3.3%', 'https://www.cbg.gm/downloads-file/4ddc97a8-fb6d-11f0-8725-02e599c15748', '2026-10-31', 'Low case: savings and short time deposits, which paid 0.2-3.3% at end-2024.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GM', 1, 'goal_inflation_education', 0.09, NULL, 'assumption', 'Central Bank of The Gambia CPI education index via Trading Economics', 'https://tradingeconomics.com/gambia/cpi-education', '2026-10-31', 'The education price index jumped to 509.64 (2020=100) by November 2023 and has not moved since, a one-off rise, so education goals use 1 point above the 8% planning inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GM', 1, 'goal_inflation_health', 0.09, NULL, 'assumption', 'Central Bank of The Gambia CPI health index via Trading Economics', 'https://tradingeconomics.com/gambia/cpi-health', '2026-10-31', 'The health price index rose from 100 (2020) to 159.05 by September 2025, about 8.4% a year, then held flat to September 2026, so health goals use 1 point above the 8% planning inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GM', 1, 'gold_return_base', 0.09, NULL, 'assumption', 'World Bank, official exchange rate GMD per USD (PA.NUS.FCRF)', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=GM', '2026-10-31', 'Base case: dollar gold trend of about 4% a year plus dalasi depreciation of about 5% a year, the 2015-2025 average.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GM', 1, 'gold_return_high', 0.16, NULL, 'assumption', 'World Bank, official exchange rate GMD per USD (PA.NUS.FCRF)', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=GM', '2026-10-31', 'High case: strong gold years with faster depreciation, as in 2022-2024 when the dalasi lost about 9% a year.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GM', 1, 'gold_return_low', 0.03, NULL, 'assumption', 'Central Bank of The Gambia, official exchange rates for valuation, 30 October 2026', 'https://www.cbg.gm/downloads-file/72f71090-d442-11f1-bfda-02ffeced4a91', '2026-10-31', 'Low case: flat dollar gold with slow dalasi depreciation (72.92 per dollar on 30 October 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GM', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No general retirement gratuity was found: the Labour Act 2023 s.104(6) gives severance of two months'' basic pay per year of service only on medical discharge, death in service, winding-up, business transfer and similar terminations (25% of basic pay on fixed-term contracts), and retirement at 60 (s.111) is not a listed case. Source: https://faolex.fao.org/docs/pdf/gam231810.pdf', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GM', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical out-of-pocket cost of a major hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GM', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premiums by age were found; the NHIA does not publish NHIS contribution amounts on its membership page.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GM', 1, 'inflation_cpi', 0.061, NULL, 'sourced', 'Gambia Bureau of Statistics, Consumer Price Index (all items), September 2026', 'https://www.gbosdata.org/data/720-consumer-price-index/1871-consumer-price-index-all-items', '2026-09-30', 'Year-on-year inflation 6.1% in September 2026 (CPI 186.21, January 2020=100); the Central Bank shows 6.5% for August and 7.0% for July 2026, after a 2026 peak of 7.6% in June.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GM', 1, 'inflation_projection', 0.08, NULL, 'assumption', 'Central Bank of The Gambia implicit inflation target 5%; World Bank CPI inflation 2016-2024', 'https://data.worldbank.org/indicator/FP.CPI.TOTL.ZG?locations=GM', '2026-10-31', 'Inflation has run above the CBG''s 5% implicit target for years (11.5% in 2022, 17.0% in 2023, 11.6% in 2024, 6-7.6% in 2026), so 8%, near the 10-year average, is used for long-run plans.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GM', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life policies are sold (listed on the CBG insurance products page) but no published premium rates per GMD 1,000 of cover were found from the regulator or a credible guide.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GM', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No industry-wide life insurance claim settlement ratio was found; the CBG, which supervises insurers under the Insurance Act 2003, publishes no claims statistics on its insurance pages.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GM', 1, 'life_expectancy', 66.057, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN)', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=GM', '2024-12-31', '66.1 years in 2024 (men 64.4, women 67.8).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GM', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":17.7,"men":17,"women":18.3},{"age":65,"total":14.2,"men":13.7,"women":14.7},{"age":70,"total":11,"men":10.6,"women":11.4},{"age":80,"total":6.1,"men":5.8,"women":6.3}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/gambia/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026; totals are the mean of men and women except at 65, where the page gives 14.2 for both sexes.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GM', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'No national non-contributory old-age pension was found; the only related transfer is the targeted Family Strengthening Program (persons 70+ among other groups, selected through the Gambia Social Registry), whose current rules were not found on an official site.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GM', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'No national non-contributory old-age pension was found. The Family Strengthening Program (Directorate of Social Welfare) paid GMD 1,000 a month in 2024 to about 2,000 social-registry households, including people aged 70+ (The Point, 29 May 2024), but it is a small targeted cash transfer and no 2026 amount was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GM', 1, 'oop_health_share', 0.3378, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=GM', '2023-12-31', '33.8% in 2023 (WHO Global Health Expenditure Database via the World Bank), the latest available; older than 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GM', 1, 'policy_rate', 0.14, NULL, 'sourced', 'Central Bank of The Gambia, Monetary Policy Committee press release, 20 August 2026', 'https://www.cbg.gm/downloads-file/7a57e5cf-9cba-11f1-8725-02e599c15748', '2026-08-20', 'The MPC kept the Monetary Policy Rate at 14% on 20 August 2026 (cut from 16% in February 2026); standing deposit facility 5%, lending facility 15%. Next meeting 25-26 November 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GM', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":18,"entryAgeMax":59,"pensionFromAge":60,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'Social Security and Housing Finance Corporation, National Provident Fund', 'https://www.sshfc.gm/national-provident-fund', '2026-10-31', 'Compulsory defined-contribution provident fund for private-sector employees aged 18-59 (SSHFC Act 2015): 15% of basic salary (5% employee, 10% employer), paid as a lump sum with interest at 60, partial withdrawal from 45; part may be converted to an annuity on request. Parastatal staff are in the Federated Pension Scheme (defined benefit, 15% employer-paid); civil servants under the Public Service Pensions Act 2022.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GM', 1, 'retirement_accumulation_return_base', 0.08, NULL, 'assumption', 'CBG Treasury bill auctions; World Bank GMD per USD exchange rate', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=GM', '2026-10-31', 'Base case: a balanced mix of Treasury bills and bonds, gold and global equity in dalasi terms, between the safe and equity base cases.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GM', 1, 'retirement_accumulation_return_high', 0.11, NULL, 'assumption', 'CBG 5-year bond result (19.82%, 14 October 2026); World Bank GMD per USD exchange rate', 'https://www.cbg.gm/downloads-file/4bdcb0b4-c71a-11f1-945a-02e599c15748', '2026-10-31', 'High case: a growth-leaning mix with more bonds at current yields and more global equity.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GM', 1, 'retirement_accumulation_return_low', 0.05, NULL, 'assumption', 'CBG Annual Report 2024 deposit rates and Treasury bill auctions', 'https://www.cbg.gm/auction-results', '2026-10-31', 'Low case: mostly deposits and bills with a small share of foreign equity.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GM', 1, 'retirement_age_default', 60, NULL, 'sourced', 'Labour Act 2023 (Act No. 6 of 2023), section 111; SSHFC National Provident Fund', 'https://faolex.fao.org/docs/pdf/gam231810.pdf', '2023-06-12', 'The retirement age for employees is 60 (s.111; contracts may fix a later age), and 60 is the normal retirement age of the National Provident Fund; the same for men and women. The Act dates from 2023 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GM', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Labour Act 2023 excludes the civil service (s.3) and the retirement age in the Public Service Pensions Act 2022 could not be read from an official source (60 is commonly cited, e.g. a State House statement of 2020, but no statute was found).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GM', 1, 'retirement_return_base', 0.06, NULL, 'assumption', 'CBG Treasury bill auction, 28 October 2026: 364-day yield 9.63%', 'https://www.cbg.gm/auction-results', '2026-10-31', 'Base case: a mix of time deposits and 364-day Treasury bills, kept well below the 9.63% one-year bill yield to allow for tax and lower future yields.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GM', 1, 'retirement_return_high', 0.085, NULL, 'assumption', 'CBG Treasury bill auction (28 October 2026) and 5-year bond result (14 October 2026)', 'https://www.cbg.gm/downloads-file/4bdcb0b4-c71a-11f1-945a-02e599c15748', '2026-10-31', 'High case: mostly one-year bills and government bonds at current high yields.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GM', 1, 'retirement_return_low', 0.03, NULL, 'assumption', 'Central Bank of The Gambia, Annual Report 2024: average 3-month deposit rate 3.3%', 'https://www.cbg.gm/downloads-file/4ddc97a8-fb6d-11f0-8725-02e599c15748', '2026-10-31', 'Low case: mostly savings and short time deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GM', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate or retail savings bond for individuals was found; the government borrows through Treasury and Sukuk al-Salaam bills and 2-5 year bonds auctioned by the CBG (minimum bid for bonds GMD 200,000).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GM', 1, 'savings_account_rate', 0.011, NULL, 'sourced', 'Central Bank of The Gambia, Annual Report 2024, Table 31: structure of interest rates (savings bank account)', 'https://www.cbg.gm/downloads-file/4ddc97a8-fb6d-11f0-8725-02e599c15748', '2024-12-31', 'Commercial banks paid 0.20-2.0% on savings accounts in December 2024; 1.1% is the midpoint of that published range. Older than 2025: no 2025 or 2026 table was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GM', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":17.9},{"year":2040,"value":13.7},{"year":2065,"value":7.8}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://data.worldbank.org/indicator/SP.POP.DPND.OL?locations=GM', '2025-12-31', '100 / old-age dependency ratio: 5.58 (2025, World Bank), 7.3 (2040, populationpyramid.net/gambia/2040/) and 12.8 (2065, populationpyramid.net/gambia/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GM', 1, 'tax_bank_interest', NULL, NULL, 'missing', '', '', '2026-10-31', 'The tax rate on bank interest for resident individuals could not be confirmed: PwC Worldwide Tax Summaries has no Gambia page and the GRA FAQs and brochures read cover only contract withholding (10%/15%) and dividends (15%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GM', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate exists for individuals, and the tax treatment of Treasury bill and bond income for individuals was not confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GM', 1, 'tbill_91d_rate', 0.0364, NULL, 'sourced', 'Central Bank of The Gambia, Treasury bill auction results, 28 October 2026', 'https://www.cbg.gm/auction-results', '2026-10-28', 'Weighted average yield on 91-day bills 3.64% (182 days 4.36%, 364 days 9.63%; Sukuk al-Salaam 91 days 3.03%). The 91-day yield was 4.0% in June 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GM', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 10-year Gambian government bond exists: the CBG bonds page lists only 2-, 3- and 5-year Gambia Government Bonds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GM', 1, 'tbond_5y_rate', 0.1982, NULL, 'sourced', 'Central Bank of The Gambia, auction result FXD 6/2026/5-year bond, 14 October 2026', 'https://www.cbg.gm/downloads-file/4bdcb0b4-c71a-11f1-945a-02e599c15748', '2026-10-14', 'Coupon set at 19.82%, the weighted average of accepted bids (19.00-20.25%); the previous 5-year issue on 21 September 2026 priced at 19.28%. Only 925 million of the 1.5 billion dalasi offered was taken up.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('GN', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"GN","iso3":"GIN","nameEn":"Guinea","nameNative":"Guinée","region":"sub_saharan_africa","languages":["fr","ff","emk","sus"],"currency":{"code":"GNF","symbol":"FG","decimals":0,"compact":"intl","usdRate":{"value":8822.6644,"status":"sourced","sourceName":"BCRG, reference rates of the main currencies against the GNF, 30 October 2026 (list 0206/2026)","sourceUrl":"https://www.bcrg-guinee.org/wp-content/uploads/2026/10/COURS-DE-REFERENCE-BCRG-DU-30-10-2026.pdf","asOf":"2026-10-30","note":"Official BCRG reference rate; the World Bank PA.NUS.FCRF series for Guinea stops in 2020."}},"instruments":{"savings_account":{"available":true,"localName":"Compte d''épargne","localNameEn":"Savings account","note":"Average rate 2.90% in 2025 (BCRG).","sourceUrl":"https://www.bcrg-guinee.org/wp-content/uploads/2026/10/RAPPORT-ANNUEL-BCRG-2025-VF2_20102026.pdf"},"fdr_3m":{"available":true,"localName":"Dépôt à terme (3 mois)","localNameEn":"Term deposit (3 months)","note":"Banks take term deposits at free rates; the average across maturities was 6.10% in 2025 (BCRG)."},"fdr_1y":{"available":true,"localName":"Dépôt à terme (1 an)","localNameEn":"Term deposit (1 year)","note":"Banks take term deposits at free rates; the average across maturities was 6.10% in 2025 (BCRG)."},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No standard monthly recurring deposit product was found."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No standing government savings certificate; the Treasury occasionally offers bonds to the public (appel public à l''épargne)."},"tbill_91d":{"available":false,"localName":"Bons du Trésor à 91 jours","localNameEn":"91-day Treasury bills","note":"Direct subscription to Treasury bills is reserved to primary banks and holders of a BCRG account.","sourceUrl":"https://www.bcrg-guinee.org/marches/marche-obligtaire/"},"tbond_5y":{"available":true,"localName":"Obligations du Trésor (appel public à l''épargne)","localNameEn":"Treasury bonds offered to the public","note":"A 5-year bond at 11% was offered to the public in 2025 (BCRG Annual Report 2025); such offers are occasional.","sourceUrl":"https://www.bcrg-guinee.org/wp-content/uploads/2026/10/RAPPORT-ANNUEL-BCRG-2025-VF2_20102026.pdf"},"tbond_10y":{"available":false,"localName":null,"localNameEn":null,"note":"No 10-year Treasury bond was found."},"equity_fund":{"available":false,"localName":null,"localNameEn":null,"note":"No stock exchange or locally sold diversified equity fund was found."},"gold":{"available":true,"localName":"Or","localNameEn":"Gold","note":"Gold is mined artisanally and industrially and sold locally as bars and jewellery; no official coin or bullion scheme was found."}},"institutions":{"centralBank":{"name":"Banque Centrale de la République de Guinée (BCRG)","url":"https://www.bcrg-guinee.org/"},"insuranceRegulator":{"name":"BCRG, insurance supervision","url":"https://www.bcrg-guinee.org/missions/supervision/assurances/","note":"The central bank licenses and supervises insurers under the Insurance Code (Law L/2016/034)."},"insuranceComplaints":null,"pensionScheme":{"name":"Caisse Nationale de Sécurité Sociale (CNSS), assurance vieillesse","url":"https://cnss.gov.gn/assurance-vieillesse/"},"oldAgeAllowance":null,"publicHealthCover":null,"depositInsurance":{"name":"Fonds de garantie des dépôts et de résolution des IFI (BCRG)","url":"https://www.bcrg-guinee.org/missions/supervision/institutions-de-microfinances/reglementations-des-imf/fonds-de-garantie-des-depots-et-de-resolution-des-ifi/","note":"Covers inclusive financial (microfinance) institutions only; no cover for commercial bank deposits was found."},"statistics":{"name":"Institut National de la Statistique (INS)","url":"https://www.stat-guinee.org/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GN', 1, 'bank_deposit_avg_rate', 0.061, NULL, 'sourced', 'BCRG Annual Report 2025, table 24 (structure des taux d''intérêt, taux DAT)', 'https://www.bcrg-guinee.org/wp-content/uploads/2026/10/RAPPORT-ANNUEL-BCRG-2025-VF2_20102026.pdf', '2025-12-31', 'Average term-deposit (DAT) rate 6.10% in 2025 (5.69% in 2024); the average savings-account rate was 2.90%. No weighted average of all deposits is published.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GN', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap or typical credit card rate was found; the BCRG reports an average bank lending rate of 13.2% in Q2 2026 (MPC communiqué, 18 September 2026), not card-specific.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GN', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No deposit guarantee for commercial banks was found; the BCRG''s deposit guarantee and resolution fund page covers only inclusive financial (microfinance) institutions and shows no coverage amount on the page that could be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GN', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No standard monthly recurring deposit product or published rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GN', 1, 'equity_return_base', 0.09, NULL, 'assumption', 'No stock exchange operates in Guinea; global equity in GNF terms; BCRG term-deposit rate 6.10% (2025)', 'https://www.bcrg-guinee.org/wp-content/uploads/2026/10/RAPPORT-ANNUEL-BCRG-2025-VF2_20102026.pdf', '2026-10-31', 'There is no local stock market, so equity means a global index fund in franc guinéen terms (about 7% in dollars plus about 2% a year of currency depreciation), kept within 4 points of an after-tax safe rate of about 5.5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GN', 1, 'equity_return_high', 0.12, NULL, 'assumption', 'No stock exchange operates in Guinea; global equity in GNF terms', 'https://www.bcrg-guinee.org/wp-content/uploads/2026/10/RAPPORT-ANNUEL-BCRG-2025-VF2_20102026.pdf', '2026-10-31', 'High case: global equities repeat their strong long-run dollar record with faster franc depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GN', 1, 'equity_return_low', 0.03, NULL, 'assumption', 'No local stock exchange found for Guinea; global equity in GNF terms; BCRG Annual Report 2025 (deposit and bill rates)', 'https://www.bcrg-guinee.org/wp-content/uploads/2026/10/RAPPORT-ANNUEL-BCRG-2025-VF2_20102026.pdf', '2026-10-31', 'Low case: a weak decade for global equities with a stable franc guinéen.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GN', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The BCRG publishes only an average term-deposit rate across maturities (6.10% in 2025, Annual Report 2025), not a 1-year rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GN', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The BCRG publishes only an average term-deposit rate (6.10% in 2025, Annual Report 2025), not a 3-month rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GN', 1, 'fixed_income_return_base', 0.05, NULL, 'assumption', 'BCRG Annual Report 2025: term deposits 6.10%; 364-day bill 7.74% (banks only)', 'https://www.bcrg-guinee.org/wp-content/uploads/2026/10/RAPPORT-ANNUEL-BCRG-2025-VF2_20102026.pdf', '2026-10-31', 'Base case: term deposits at about 6% less a possible tax on interest, which could not be confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GN', 1, 'fixed_income_return_high', 0.08, NULL, 'assumption', 'BCRG Annual Report 2025: 5-year public bond offer at 11%', 'https://www.bcrg-guinee.org/wp-content/uploads/2026/10/RAPPORT-ANNUEL-BCRG-2025-VF2_20102026.pdf', '2026-10-31', 'High case: part of savings in Treasury bonds offered to the public (11% in 2025), after default and liquidity risk.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GN', 1, 'fixed_income_return_low', 0.03, NULL, 'assumption', 'BCRG Annual Report 2025: savings rate 2.90%, term deposits 6.10%', 'https://www.bcrg-guinee.org/wp-content/uploads/2026/10/RAPPORT-ANNUEL-BCRG-2025-VF2_20102026.pdf', '2026-10-31', 'Low case: ordinary savings accounts at about 3%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GN', 1, 'goal_inflation_education', 0.08, NULL, 'assumption', 'INS INHPC September 2026: education prices +0.5% year on year; 7% planning inflation', 'https://www.stat-guinee.org/images/Documents/Publications/INS/infra_annuelles/IHPC/INHPC_2026/Note_INHPC_Sept_2026_Guinee_V1.pdf', '2026-10-31', 'The education price index rose only 0.5% in the year to September 2026, but private school fees rise in steps, so education goals use 1 point above the 7% planning inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GN', 1, 'goal_inflation_health', 0.08, NULL, 'assumption', 'INS INHPC September 2026: health prices -0.5% year on year; 7% planning inflation', 'https://www.stat-guinee.org/images/Documents/Publications/INS/infra_annuelles/IHPC/INHPC_2026/Note_INHPC_Sept_2026_Guinee_V1.pdf', '2026-10-31', 'The health price index has been flat (-0.5% in the year to September 2026), but it tracks public prices; private and imported care cost more over time, so health goals use 1 point above the 7% planning inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GN', 1, 'gold_return_base', 0.065, NULL, 'assumption', 'BCRG reference exchange rate (GNF 8,822.66 per dollar, 30 October 2026); dollar gold trend', 'https://www.bcrg-guinee.org/wp-content/uploads/2026/10/COURS-DE-REFERENCE-BCRG-DU-30-10-2026.pdf', '2026-10-31', 'Base case: long-run dollar gold trend of about 4% a year plus about 2.5% a year franc depreciation (the franc lost 0.9% to the dollar in the year to mid-2026, more in earlier years).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GN', 1, 'gold_return_high', 0.12, NULL, 'assumption', 'BCRG reference exchange rate (GNF 8,822.66 per dollar, 30 October 2026); dollar gold trend', 'https://www.bcrg-guinee.org/wp-content/uploads/2026/10/COURS-DE-REFERENCE-BCRG-DU-30-10-2026.pdf', '2026-10-31', 'High case: strong gold years with faster franc depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GN', 1, 'gold_return_low', 0.01, NULL, 'assumption', 'BCRG reference exchange rate (GNF 8,822.66 per dollar, 30 October 2026); dollar gold trend', 'https://www.bcrg-guinee.org/wp-content/uploads/2026/10/COURS-DE-REFERENCE-BCRG-DU-30-10-2026.pdf', '2026-10-31', 'Low case: flat dollar gold with a stable franc guinéen.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GN', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Labour Code provisions on a retirement or end-of-service indemnity for private employees could not be read from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GN', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical out-of-pocket cost of a major private hospital stay in Guinea was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GN', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premiums by age were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GN', 1, 'inflation_cpi', 0.059, NULL, 'sourced', 'Institut National de la Statistique (INS), Indice national harmonisé des prix à la consommation (INHPC), September 2026', 'https://www.stat-guinee.org/images/Documents/Publications/INS/infra_annuelles/IHPC/INHPC_2026/Note_INHPC_Sept_2026_Guinee_V1.pdf', '2026-09-30', 'National consumer prices up 5.9% year on year in September 2026 (Conakry 6.3%); the 12-month average was 5.2%. Food prices rose 12.4% while health (-0.5%) and education (+0.5%) were almost flat.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GN', 1, 'inflation_projection', 0.07, NULL, 'assumption', 'BCRG Monetary Policy Committee, 18 September 2026 (6.0% average inflation projected for 2026); INS INHPC (index 167.3 in September 2026, base 2019 = 100)', 'https://www.bcrg-guinee.org/wp-content/uploads/2026/09/22eme-Reunion-du-Comite-de-Politique-Monetaire-18-09-2026.pdf', '2026-10-31', 'The BCRG has no numerical target; it projects 6.0% average inflation for 2026, and the national index rose about 7.6% a year from 2019 to 2026, so a rounded 7% is used for long-range plans.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GN', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Life insurance is sold by a few licensed insurers, but no published term life premium rates per GNF 1,000 of cover by age were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GN', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The BCRG (insurance supervisor) reports claims paid by life and non-life insurers in its annual report, but no life claim settlement ratio was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GN', 1, 'life_expectancy', 60.904, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN), Guinea', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=GN', '2024-12-31', '60.9 years in 2024 (men 59.7, women 62.1).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GN', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":17.1,"men":16.6,"women":17.5},{"age":65,"total":13.7,"men":13.3,"women":14},{"age":70,"total":10.6,"men":10.3,"women":10.9},{"age":80,"total":5.9,"men":5.7,"women":6}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/guinea/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GN', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension was found (see old_age_allowance_monthly).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GN', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension was found; the CNSS ''allocation de vieillesse'' is a contributory lump sum for insured workers with under 15 years of contributions, not a social pension.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GN', 1, 'oop_health_share', 0.5442, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), Guinea', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=GN', '2023-12-31', '54.4% in 2023 (WHO Global Health Expenditure Database via the World Bank), the latest available; older than 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GN', 1, 'policy_rate', 0.095, NULL, 'sourced', 'BCRG, communiqué of the 22nd ordinary Monetary Policy Committee meeting, 18 September 2026', 'https://www.bcrg-guinee.org/wp-content/uploads/2026/09/22eme-Reunion-du-Comite-de-Politique-Monetaire-18-09-2026.pdf', '2026-09-18', 'Policy rate (taux directeur) held at 9.5% and reserve requirement at 11.5%; it was 9.75% at end-2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GN', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":60,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'Caisse Nationale de Sécurité Sociale (CNSS), assurance vieillesse', 'https://cnss.gov.gn/assurance-vieillesse/', '2026-10-31', 'Compulsory CNSS retirement pension for salaried workers after at least 180 months of contributions (careers counted up to 30 years), from 55, 60 or 65 by job category (60 used); with fewer than 15 years a lump-sum old-age allowance is paid. The page gives no benefit formula or indexation rule, so inflationLinked is set to false and tax treatment is unknown.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GN', 1, 'retirement_accumulation_return_base', 0.065, NULL, 'assumption', 'Safe rate about 5%; global equity base 9%; gold base 6.5% (our assumptions above)', 'https://www.bcrg-guinee.org/wp-content/uploads/2026/10/RAPPORT-ANNUEL-BCRG-2025-VF2_20102026.pdf', '2026-10-31', 'Base case: a balanced mix of term deposits, public bond offers, gold and some foreign equity.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GN', 1, 'retirement_accumulation_return_high', 0.09, NULL, 'assumption', 'Safe rate about 5%; global equity base 9%; gold base 6.5% (our assumptions above)', 'https://www.bcrg-guinee.org/wp-content/uploads/2026/10/RAPPORT-ANNUEL-BCRG-2025-VF2_20102026.pdf', '2026-10-31', 'High case: a growth-leaning mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GN', 1, 'retirement_accumulation_return_low', 0.04, NULL, 'assumption', 'Safe rate about 5%; global equity base 9%; gold base 6.5% (our assumptions above)', 'https://www.bcrg-guinee.org/wp-content/uploads/2026/10/RAPPORT-ANNUEL-BCRG-2025-VF2_20102026.pdf', '2026-10-31', 'Low case: mostly deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GN', 1, 'retirement_age_default', 60, NULL, 'sourced', 'Caisse Nationale de Sécurité Sociale (CNSS), assurance vieillesse', 'https://cnss.gov.gn/assurance-vieillesse/', '2026-10-31', 'Pension age by job category under decree 2009/185 of 5 September 2009: 55 for manual and heavy work, 60 for workers, employees, supervisors and foremen, 65 for managers and engineers; at least 15 years (180 months) of contributions. 60 is used; same for men and women. The decree dates from 2009 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GN', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'The retirement age under the Statut général des agents de l''État (law L/2019/027/AN of 7 June 2019) could not be read from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GN', 1, 'retirement_return_base', 0.045, NULL, 'assumption', 'BCRG Annual Report 2025: term deposits 6.10%', 'https://www.bcrg-guinee.org/wp-content/uploads/2026/10/RAPPORT-ANNUEL-BCRG-2025-VF2_20102026.pdf', '2026-10-31', 'Base case: term deposits at about 6% less a possible tax on interest; kept below the after-tax deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GN', 1, 'retirement_return_high', 0.06, NULL, 'assumption', 'BCRG Annual Report 2025: term deposits 6.10%; 5-year public bond offer at 11%', 'https://www.bcrg-guinee.org/wp-content/uploads/2026/10/RAPPORT-ANNUEL-BCRG-2025-VF2_20102026.pdf', '2026-10-31', 'High case: part of the money in Treasury bonds offered to the public.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GN', 1, 'retirement_return_low', 0.03, NULL, 'assumption', 'BCRG Annual Report 2025: savings rate 2.90%, term deposits 6.10%', 'https://www.bcrg-guinee.org/wp-content/uploads/2026/10/RAPPORT-ANNUEL-BCRG-2025-VF2_20102026.pdf', '2026-10-31', 'Low case: savings accounts at about 3%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GN', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No standing government savings certificate for individuals was found; the Treasury made one public bond offer (appel public à l''épargne) of GNF 1,500 billion for 5 years at 11% in 2025 (BCRG Annual Report 2025), reported under the 5-year bond.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GN', 1, 'savings_account_rate', 0.029, NULL, 'sourced', 'BCRG Annual Report 2025, table 24 (structure des taux d''intérêt, taux d''épargne)', 'https://www.bcrg-guinee.org/wp-content/uploads/2026/10/RAPPORT-ANNUEL-BCRG-2025-VF2_20102026.pdf', '2025-12-31', 'Average rate on savings accounts 2.90% in 2025 (3.06% in 2024); bank deposit rates are free (not regulated).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GN', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":16.12},{"year":2040,"value":15.63},{"year":2065,"value":8.93}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://data.worldbank.org/indicator/SP.POP.DPND.OL?locations=GN', '2025-12-31', 'Working-age people per person 65+ = 100 / old-age dependency ratio. Old-age dependency ratios used: 6.20% in 2025 (World Bank), 6.4% in 2040 (populationpyramid.net/guinea/2040/) and 11.2% in 2065 (populationpyramid.net/guinea/2065/), giving 16.12, 15.63 and 8.93.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GN', 1, 'tax_bank_interest', NULL, NULL, 'missing', '', '', '2026-10-31', 'The withholding tax on interest for individuals could not be confirmed: PwC Worldwide Tax Summaries has no Guinea page and the tax authority''s General Tax Code was not read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GN', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate exists, and the tax treatment of Treasury bond interest for individuals could not be confirmed from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GN', 1, 'tbill_91d_rate', 0.041, NULL, 'sourced', 'BCRG Annual Report 2025, table 24 and annex A8 (taux des bons du Trésor)', 'https://www.bcrg-guinee.org/wp-content/uploads/2026/10/RAPPORT-ANNUEL-BCRG-2025-VF2_20102026.pdf', '2025-12-31', '91-day Treasury bill rate 4.10% in December 2025, down from 14.35% in December 2024; 182-day 4.18%, 364-day 7.74%. Direct subscription is reserved to primary banks.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GN', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 10-year Treasury bond yield for Guinea was found in BCRG publications.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GN', 1, 'tbond_5y_rate', 0.11, NULL, 'sourced', 'BCRG Annual Report 2025, Treasury bond market (obligations du Trésor)', 'https://www.bcrg-guinee.org/wp-content/uploads/2026/10/RAPPORT-ANNUEL-BCRG-2025-VF2_20102026.pdf', '2025-12-31', 'Coupon of the 5-year Treasury bond offered to the public (appel public à l''épargne, GNF 1,500 billion) in 2025; no market yield for 5-year bonds is published.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('GQ', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"GQ","iso3":"GNQ","nameEn":"Equatorial Guinea","nameNative":"Guinea Ecuatorial","region":"sub_saharan_africa","languages":["es","fan","fr"],"currency":{"code":"XAF","symbol":"FCFA","decimals":0,"compact":"intl","usdRate":{"value":581.928,"status":"sourced","sourceName":"World Bank WDI, official exchange rate (PA.NUS.FCRF), Equatorial Guinea","sourceUrl":"https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=GQ","asOf":"2025-12-31","note":"2025 average. The franc CFA is fixed at 655.957 per euro, so the dollar rate moves with the euro."}},"instruments":{"savings_account":{"available":true,"localName":"Cuenta de ahorro","localNameEn":"Savings account","note":"Banks must pay at least the BEAC minimum savings rate (2.45%).","sourceUrl":"https://www.beac.int/wp-content/uploads/2018/11/Rapport-sur-La-Politique-Mon%C3%A9taire-de-la-BEAC_Sept-2026_vf_new2_Publiable.pdf"},"fdr_3m":{"available":true,"localName":"Depósito a plazo (3 meses)","localNameEn":"Term deposit (3 months)","note":"Banks take term deposits (the BEAC sets reserve requirements on them), but rates are not published."},"fdr_1y":{"available":true,"localName":"Depósito a plazo (1 año)","localNameEn":"Term deposit (1 year)","note":"Banks take term deposits, but rates are not published."},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No standard monthly recurring deposit product was found."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate for individuals was found."},"tbill_91d":{"available":true,"localName":"Bonos del Tesoro asimilables (BTA)","localNameEn":"Treasury bills","note":"Treasury bills (BTA, 13 to 52 weeks) are auctioned through the BEAC to primary dealers (SVT); individuals can buy through them or on the secondary market (2,219 individuals held CEMAC Treasury securities in January 2026, BEAC).","sourceUrl":"https://www.beac.int/wp-content/uploads/2021/10/Statistiques-Mensuelles-du-March%C3%A9-des-valeurs-du-Tr%C3%A9sors-de-la-CEMAC-janvier-2026.pdf"},"tbond_5y":{"available":true,"localName":"Obligaciones del Tesoro asimilables (OTA)","localNameEn":"Treasury bonds","note":"Treasury bonds (OTA) are auctioned through the BEAC to primary dealers and can be bought by individuals through them; Equatorial Guinea issues them irregularly (last in December 2025 as of the January 2026 statistics).","sourceUrl":"https://www.beac.int/wp-content/uploads/2021/10/Statistiques-Mensuelles-du-March%C3%A9-des-valeurs-du-Tr%C3%A9sors-de-la-CEMAC-janvier-2026.pdf"},"tbond_10y":{"available":false,"localName":null,"localNameEn":null,"note":"No 10-year Treasury bond yield or issue was found."},"equity_fund":{"available":false,"localName":null,"localNameEn":null,"note":"No locally sold diversified equity fund was found; the regional stock exchange lists very few companies."},"gold":{"available":true,"localName":"Oro","localNameEn":"Gold","note":"Gold is sold mainly as jewellery; no official bullion or coin scheme was found."}},"institutions":{"centralBank":{"name":"Bank of Central African States (Banco de los Estados de África Central, BEAC)","url":"https://www.beac.int/"},"insuranceRegulator":{"name":"Inter-African Conference on Insurance Markets (CIMA), regional insurance regulator, with the national insurance directorate","url":"https://cima-afrique.org/"},"insuranceComplaints":{"name":"CIMA policyholder requests and complaints form","url":"https://cima-afrique.org/faites-votre-requetes-ici-2/"},"pensionScheme":{"name":"National Social Security Institute (Instituto Nacional de Seguridad Social, INSESO)","url":"https://www.inseso.org/"},"depositInsurance":{"name":"Deposit Guarantee Fund of Central Africa (FOGADAC)","url":"https://www.fogadac.com/"},"statistics":{"name":"National Institute of Statistics of Equatorial Guinea (INEGE)","url":"https://inege.org/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GQ', 1, 'bank_deposit_avg_rate', 0.0245, NULL, 'sourced', 'World Bank WDI, deposit interest rate (FR.INR.DPST), Equatorial Guinea', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=GQ', '2017-12-31', '2.45% in 2017, the latest World Bank value (older than 2025); it equals the BEAC minimum savings rate (Taux Créditeur Minimum), still 2.45% in the BEAC September 2026 report.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GQ', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap or typical credit card rate was found; the BEAC reports an average effective lending rate (TEG) of 13.82% in Equatorial Guinea in Q2 2026, but not for cards.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GQ', 1, 'deposit_insurance_limit', 8000000, NULL, 'sourced', 'Deposit Guarantee Fund of Central Africa (FOGADAC), FAQ', 'https://www.fogadac.com/faq', '2026-10-31', 'FOGADAC covers deposits up to XAF 8 million per individual depositor (read 31 October 2026); covers banks in all CEMAC countries, including Equatorial Guinea.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GQ', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No standard monthly recurring deposit product or rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GQ', 1, 'equity_return_base', 0.06, NULL, 'assumption', 'BEAC: franc CFA fixed to the euro; the regional stock exchange lists very few companies and none of note from Equatorial Guinea', 'https://www.beac.int/wp-content/uploads/2021/10/Statistiques-Mensuelles-du-March%C3%A9-des-valeurs-du-Tr%C3%A9sors-de-la-CEMAC-janvier-2026.pdf', '2026-10-31', 'No local stock index record, so equity means a global index in euro (franc CFA) terms, held at no more than about 3.5 points above an after-tax safe saving rate of about 2.5-3% (BEAC minimum savings rate 2.45%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GQ', 1, 'equity_return_high', 0.1, NULL, 'assumption', 'BEAC: franc CFA fixed to the euro; the regional stock exchange lists very few companies and none of note from Equatorial Guinea', 'https://www.beac.int/wp-content/uploads/2021/10/Statistiques-Mensuelles-du-March%C3%A9-des-valeurs-du-Tr%C3%A9sors-de-la-CEMAC-janvier-2026.pdf', '2026-10-31', 'High case: global equities repeat their long-run euro-terms record.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GQ', 1, 'equity_return_low', 0.02, NULL, 'assumption', 'BEAC: franc CFA fixed to the euro; the regional stock exchange lists very few companies and none of note from Equatorial Guinea', 'https://www.beac.int/wp-content/uploads/2021/10/Statistiques-Mensuelles-du-March%C3%A9-des-valeurs-du-Tr%C3%A9sors-de-la-CEMAC-janvier-2026.pdf', '2026-10-31', 'Low case: a weak decade for global equities held in euro (franc CFA) terms; there is no usable local stock index.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GQ', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published 1-year term deposit rate was found; the BEAC publishes lending rates (TEG) by country but no term deposit rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GQ', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published 3-month term deposit rate was found; the BEAC publishes lending rates (TEG) by country but no deposit rates beyond the 2.45% savings floor.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GQ', 1, 'fixed_income_return_base', 0.03, NULL, 'assumption', 'BEAC Taux Créditeur Minimum 2.45%; BEAC Treasury market statistics January 2026', 'https://www.beac.int/wp-content/uploads/2018/11/Rapport-sur-La-Politique-Mon%C3%A9taire-de-la-BEAC_Sept-2026_vf_new2_Publiable.pdf', '2026-10-31', 'Base case: savings and term deposits a little above the 2.45% floor; Treasury yields are higher but mostly bought by banks and institutions.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GQ', 1, 'fixed_income_return_high', 0.06, NULL, 'assumption', 'BEAC Taux Créditeur Minimum 2.45%; BEAC Treasury market statistics January 2026', 'https://www.beac.int/wp-content/uploads/2021/10/Statistiques-Mensuelles-du-March%C3%A9-des-valeurs-du-Tr%C3%A9sors-de-la-CEMAC-janvier-2026.pdf', '2026-10-31', 'High case: part of savings in government securities, whose issue cost was 8-10% in 2025-2026, after default and liquidity risk.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GQ', 1, 'fixed_income_return_low', 0.02, NULL, 'assumption', 'BEAC Taux Créditeur Minimum 2.45%; BEAC Treasury market statistics January 2026', 'https://www.beac.int/wp-content/uploads/2018/11/Rapport-sur-La-Politique-Mon%C3%A9taire-de-la-BEAC_Sept-2026_vf_new2_Publiable.pdf', '2026-10-31', 'Low case: ordinary savings accounts at the 2.45% minimum rate, less any tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GQ', 1, 'goal_inflation_education', 0.04, NULL, 'assumption', 'BEAC note on CEMAC inflation Q2 2026: education prices +0.8% year on year in June 2026 (CEMAC)', 'https://www.beac.int/wp-content/uploads/2016/10/Note-sur-l%C3%A9volution-r%C3%A9cente-de-linflation-dans-la-CEMAC-2026Q2.pdf', '2026-10-31', 'CEMAC education prices rose 0.8% in June 2026, but private school fees rise faster, so education goals use 1 point above the 3% planning inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GQ', 1, 'goal_inflation_health', 0.045, NULL, 'assumption', 'INEGE, Tasa de inflación septiembre 2026: health goods and services +4.6%', 'https://inege.org/?p=18344', '2026-10-31', 'INEGE reported health prices up 4.6% in September 2026 and private and imported care costs tend to run above headline inflation, so health goals use 1.5 points above the 3% planning inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GQ', 1, 'gold_return_base', 0.045, NULL, 'assumption', 'Franc CFA fixed at 655.957 per euro (BEAC); dollar gold trend', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=GQ', '2026-10-31', 'Base case: the long-run gold trend of about 4-5% a year in euro terms, which the franc CFA follows.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GQ', 1, 'gold_return_high', 0.08, NULL, 'assumption', 'Franc CFA fixed at 655.957 per euro (BEAC); dollar gold trend', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=GQ', '2026-10-31', 'High case: strong gold years.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GQ', 1, 'gold_return_low', 0, NULL, 'assumption', 'Franc CFA fixed at 655.957 per euro (BEAC); dollar gold trend', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=GQ', '2026-10-31', 'Low case: flat gold prices with no currency loss under the euro peg.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GQ', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'The end-of-service or dismissal indemnity provisions of the General Labour Law could not be read from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GQ', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical out-of-pocket cost of a major hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GQ', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premiums by age were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GQ', 1, 'inflation_cpi', 0.059, NULL, 'sourced', 'National Institute of Statistics of Equatorial Guinea (INEGE), Tasa de inflación septiembre 2026', 'https://inege.org/?p=18344', '2026-09-30', 'Consumer prices up 5.9% year on year in September 2026 (INEGE, published 20 October 2026); the CEMAC surveillance measure (12-month average) was 3.0%, up from 2.8% in August. The BEAC Q2 2026 note gave 3.2% year on year for June 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GQ', 1, 'inflation_projection', 0.03, NULL, 'assumption', 'BEAC: CEMAC inflation convergence norm of 3%; franc CFA fixed to the euro', 'https://www.beac.int/wp-content/uploads/2016/10/COMMUNIQUE-DE-PRESSE-CPM-DU-28-SEPTEMBRE-2026.pdf', '2026-10-31', 'The franc CFA is fixed to the euro and the BEAC holds CEMAC inflation under a 3% norm; Equatorial Guinea''s annual average inflation was 3.4% in 2024 and 2.3% in 2025 (BEAC) and 3.0% in the 12 months to September 2026 (INEGE), and the BEAC projects 2.0-2.5% for 2027-2030, so the 3% norm is used despite the 2026 energy-price spike (5.9% year on year in September 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GQ', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published term life premium rates per XAF 1,000 of cover were found; the life insurance market is very small.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GQ', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No life insurance claim settlement ratio was found from CIMA (the regional insurance regulator) or the national insurance directorate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GQ', 1, 'life_expectancy', 63.906, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN), Equatorial Guinea', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=GQ', '2024-12-31', '63.9 years in 2024 (men 62.2, women 65.9); latest available, older than 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GQ', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":16.6,"men":15.9,"women":17.3},{"age":65,"total":13.3,"men":12.7,"women":13.8},{"age":70,"total":10.3,"men":9.9,"women":10.7},{"age":80,"total":5.8,"men":5.6,"women":6}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/equatorial-guinea/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026; totals at 60, 70 and 80 are the mean of men and women (the page gives a both-sexes figure only at 65).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GQ', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension was found; the INSESO social benefits page lists only contributory pensions (old age, invalidity, survivors).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GQ', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension was found; the INSESO social benefits page lists only contributory pensions (old age, invalidity, survivors).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GQ', 1, 'oop_health_share', 0.6598, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), Equatorial Guinea', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=GQ', '2023-12-31', '66.0% in 2023 (WHO Global Health Expenditure Database via the World Bank), the latest available; older than 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GQ', 1, 'policy_rate', 0.045, NULL, 'sourced', 'BEAC Monetary Policy Committee, press release of 28 September 2026 (Taux d''intérêt des appels d''offres)', 'https://www.beac.int/wp-content/uploads/2016/10/COMMUNIQUE-DE-PRESSE-CPM-DU-28-SEPTEMBRE-2026.pdf', '2026-09-28', 'BEAC tender rate (TIAO) held at 4.50% on 28 September 2026 (marginal lending facility 5.75%, deposit facility 0%); the rate is common to all six CEMAC countries.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GQ', 1, 'public_pension_scheme', NULL, NULL, 'missing', '', '', '2026-10-31', 'INSESO runs the compulsory contributory old-age pension (contributions 21.5% employer and 4.5% employee per PwC Worldwide Tax Summaries, reviewed 21 November 2025), but the pension age, qualifying period and indexation could not be confirmed from a readable source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GQ', 1, 'retirement_accumulation_return_base', 0.045, NULL, 'assumption', 'Safe rate about 3%; global equity base 6% in euro terms; gold base 4.5%', 'https://www.beac.int/wp-content/uploads/2021/10/Statistiques-Mensuelles-du-March%C3%A9-des-valeurs-du-Tr%C3%A9sors-de-la-CEMAC-janvier-2026.pdf', '2026-10-31', 'Base case: a balanced mix of deposits, government securities, gold and foreign equity funds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GQ', 1, 'retirement_accumulation_return_high', 0.065, NULL, 'assumption', 'Safe rate about 3%; global equity base 6% in euro terms; gold base 4.5%', 'https://www.beac.int/wp-content/uploads/2021/10/Statistiques-Mensuelles-du-March%C3%A9-des-valeurs-du-Tr%C3%A9sors-de-la-CEMAC-janvier-2026.pdf', '2026-10-31', 'High case: a growth-leaning mix with more equity.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GQ', 1, 'retirement_accumulation_return_low', 0.025, NULL, 'assumption', 'Safe rate about 3%; global equity base 6% in euro terms; gold base 4.5%', 'https://www.beac.int/wp-content/uploads/2018/11/Rapport-sur-La-Politique-Mon%C3%A9taire-de-la-BEAC_Sept-2026_vf_new2_Publiable.pdf', '2026-10-31', 'Low case: mostly bank savings.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GQ', 1, 'retirement_age_default', NULL, NULL, 'missing', '', '', '2026-10-31', 'The old-age pension age could not be confirmed: the INSESO old-age pension page (inseso.org/prestacion/pension-por-vejez) lists only documents required, and the ISSA and US SSA country profiles were not reachable.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GQ', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'The retirement age of civil servants could not be confirmed from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GQ', 1, 'retirement_return_base', 0.03, NULL, 'assumption', 'BEAC Taux Créditeur Minimum 2.45%; BEAC Treasury bill issue cost 8.18% (January 2026)', 'https://www.beac.int/wp-content/uploads/2018/11/Rapport-sur-La-Politique-Mon%C3%A9taire-de-la-BEAC_Sept-2026_vf_new2_Publiable.pdf', '2026-10-31', 'Base case: bank deposits close to the 2.45% floor; kept well below the Treasury bill rate, since term deposit rates are not published and individuals rarely hold Treasury securities.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GQ', 1, 'retirement_return_high', 0.045, NULL, 'assumption', 'BEAC Taux Créditeur Minimum 2.45%; BEAC Treasury bill issue cost 8.18% (January 2026)', 'https://www.beac.int/wp-content/uploads/2021/10/Statistiques-Mensuelles-du-March%C3%A9-des-valeurs-du-Tr%C3%A9sors-de-la-CEMAC-janvier-2026.pdf', '2026-10-31', 'High case: a larger share in government securities.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GQ', 1, 'retirement_return_low', 0.02, NULL, 'assumption', 'BEAC Taux Créditeur Minimum 2.45%; BEAC Treasury bill issue cost 8.18% (January 2026)', 'https://www.beac.int/wp-content/uploads/2018/11/Rapport-sur-La-Politique-Mon%C3%A9taire-de-la-BEAC_Sept-2026_vf_new2_Publiable.pdf', '2026-10-31', 'Low case: savings accounts at the 2.45% minimum rate, less any tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GQ', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate or retail savings bond for individuals was found; the Treasury borrows through BEAC-run auctions of bills and bonds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GQ', 1, 'savings_account_rate', 0.0245, NULL, 'sourced', 'BEAC Monetary Policy Report, September 2026, Annex 1 (Taux Créditeur Minimum)', 'https://www.beac.int/wp-content/uploads/2018/11/Rapport-sur-La-Politique-Mon%C3%A9taire-de-la-BEAC_Sept-2026_vf_new2_Publiable.pdf', '2026-09-30', 'Minimum rate banks must pay on savings accounts of individuals (Taux Créditeur Minimum), 2.45% unchanged since 8 July 2014; banks usually pay this floor.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GQ', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":15.7},{"year":2040,"value":12.2},{"year":2065,"value":9.2}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://data.worldbank.org/indicator/SP.POP.DPND.OL?locations=GQ', '2025-12-31', '100 / old-age dependency ratio: 6.36 (2025, World Bank), 8.2 (2040, populationpyramid.net/equatorial-guinea/2040/) and 10.9 (2065, populationpyramid.net/equatorial-guinea/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GQ', 1, 'tax_bank_interest', NULL, NULL, 'missing', '', '', '2026-10-31', 'The tax on bank interest received by resident individuals could not be confirmed; PwC Worldwide Tax Summaries (reviewed 21 November 2025) gives 15% withholding on interest paid to non-residents only.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GQ', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate for individuals exists, and the tax treatment of Treasury security income for individuals could not be confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GQ', 1, 'tbill_91d_rate', 0.0818, NULL, 'sourced', 'BEAC, Statistiques mensuelles du marché des valeurs du Trésor de la CEMAC, January 2026 (coût des ressources, BTA, Guinée Equatoriale)', 'https://www.beac.int/wp-content/uploads/2021/10/Statistiques-Mensuelles-du-March%C3%A9-des-valeurs-du-Tr%C3%A9sors-de-la-CEMAC-janvier-2026.pdf', '2026-01-31', 'Weighted average cost of Treasury bills (BTA, 13 to 52 weeks) issued by Equatorial Guinea in January 2026; no separate 13-week yield is published.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GQ', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 10-year Treasury bond yield for Equatorial Guinea was found; the BEAC yield curve chart in its January 2026 statistics covers only Cameroon, Congo and Gabon.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GQ', 1, 'tbond_5y_rate', 0.1012, NULL, 'sourced', 'BEAC, Statistiques mensuelles du marché des valeurs du Trésor de la CEMAC, January 2026 (coût des ressources, OTA, Guinée Equatoriale)', 'https://www.beac.int/wp-content/uploads/2021/10/Statistiques-Mensuelles-du-March%C3%A9-des-valeurs-du-Tr%C3%A9sors-de-la-CEMAC-janvier-2026.pdf', '2025-12-31', 'Weighted average cost of Treasury bonds (OTA, 2 years and more) issued by Equatorial Guinea in December 2025 (10.39% in January 2025); no OTA was issued in January 2026 and no yield for an exact 5-year maturity is published.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('GR', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"GR","iso3":"GRC","nameEn":"Greece","nameNative":"Ελλάδα","region":"europe_central_asia","languages":["el","en"],"currency":{"code":"EUR","symbol":"€","decimals":2,"compact":"intl","usdRate":{"value":0.8951,"status":"sourced","sourceName":"European Central Bank euro reference rate (USD)","sourceUrl":"https://www.ecb.europa.eu/stats/policy_and_exchange_rates/euro_reference_exchange_rates/html/eurofxref-graph-usd.en.html","asOf":"2026-10-30","note":"EUR 1 = USD 1.1172 on 30 October 2026 (ECB data portal EXR.D.USD.EUR.SP00.A), so about EUR 0.895 per US dollar; World Bank 2025 average 0.885."}},"instruments":{"savings_account":{"available":true,"localName":"Λογαριασμός ταμιευτηρίου","localNameEn":"Savings account","sourceUrl":"https://data-api.ecb.europa.eu/service/data/MIR/M.GR.B.L21.A.R.A.2250.EUR.N"},"fdr_3m":{"available":true,"localName":"Προθεσμιακή κατάθεση","localNameEn":"Term deposit (3 months)"},"fdr_1y":{"available":true,"localName":"Προθεσμιακή κατάθεση","localNameEn":"Term deposit (1 year)","sourceUrl":"https://data-api.ecb.europa.eu/service/data/MIR/M.GR.B.L22.F.R.A.2250.EUR.N"},"dps":{"available":false,"localName":null,"localNameEn":"Recurring deposit","note":"No standard monthly recurring-deposit product was found; regular saving usually goes into savings accounts or monthly mutual fund plans."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":"Government savings certificate","note":"Greece has no retail savings certificate; individuals can buy Greek government bonds and treasury bills through banks, with interest exempt from income tax."},"tbill_91d":{"available":true,"localName":"Έντοκα Γραμμάτια Ελληνικού Δημοσίου","localNameEn":"Greek Government Treasury Bills","note":"13-week bills auctioned by the Public Debt Management Agency; individuals buy through banks.","sourceUrl":"https://tradingeconomics.com/greece/government-bond-yield"},"tbond_5y":{"available":true,"localName":"Ομόλογα Ελληνικού Δημοσίου","localNameEn":"Greek Government Bonds"},"tbond_10y":{"available":true,"localName":"Ομόλογα Ελληνικού Δημοσίου","localNameEn":"Greek Government Bonds","sourceUrl":"https://tradingeconomics.com/greece/government-bond-yield"},"equity_fund":{"available":true,"localName":"Αμοιβαία κεφάλαια","localNameEn":"Mutual funds and index funds (ETFs)","note":"Retail mutual funds and exchange-traded index funds are widely available."},"gold":{"available":true,"localName":"Χρυσές λίρες και ράβδοι χρυσού","localNameEn":"Gold sovereigns and gold bars","note":"Buying physical gold is legal; gold sovereigns are a traditional savings form in Greece."}},"institutions":{"centralBank":{"name":"Bank of Greece","url":"https://www.bankofgreece.gr/","note":"Part of the Eurosystem; monetary policy set by the European Central Bank."},"insuranceRegulator":{"name":"Bank of Greece, Department of Private Insurance Supervision","url":"https://www.bankofgreece.gr/"},"insuranceComplaints":{"name":"Hellenic Consumer Ombudsman","url":"https://www.synigoroskatanaloti.gr/","note":"Independent authority for consumer disputes, including with insurers; complaints can also be sent to the Bank of Greece insurance supervision department."},"pensionScheme":{"name":"e-EFKA (Unified Social Security Fund)","url":"https://www.efka.gov.gr/"},"oldAgeAllowance":{"name":"OPEKA, social solidarity allowance for uninsured elderly","url":"https://opeka.gov.gr/anasfalistoi-yperilikes/epidoma-koinonikis-allilengyis-anasfaliston-yperilikon/"},"publicHealthCover":{"name":"EOPYY (National Organisation for the Provision of Health Services)","url":"https://www.eopyy.gov.gr/"},"depositInsurance":{"name":"Hellenic Deposit and Investment Guarantee Fund (TEKE)","url":"https://www.teke.gr/"},"statistics":{"name":"Hellenic Statistical Authority (ELSTAT)","url":"https://www.statistics.gr/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GR', 1, 'bank_deposit_avg_rate', 0.0122, NULL, 'sourced', 'ECB MFI interest rate statistics: Greek banks, household deposits with agreed maturity (outstanding amounts)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.GR.B.L22.A.R.A.2250.EUR.O', '2026-09-30', 'Average rate on all outstanding household term deposits in September 2026 (1.19% in August); overnight deposits paid 0.03%. World Bank FR.INR.DPST has no Greece figure.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GR', 1, 'credit_card_rate_cap', 0.1688, NULL, 'sourced', 'ECB MFI interest rate statistics: Greek banks, extended credit card credit to households (new business)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.GR.B.A2Z3.A.R.A.2250.EUR.N', '2026-09-30', 'Typical rate, not a legal cap: average 16.88% on extended credit card debt in September 2026 (16.87% in August).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GR', 1, 'deposit_insurance_limit', 100000, NULL, 'sourced', 'Hellenic Deposit and Investment Guarantee Fund (TEKE); European Commission, deposit guarantee schemes', 'https://finance.ec.europa.eu/banking/banking-regulation/deposit-guarantee-schemes_en', '2026-10-31', 'EUR 100,000 per depositor per bank under the EU Deposit Guarantee Schemes Directive, paid by TEKE in Greece; teke.gr did not show the figure to automated access.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GR', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No standard monthly recurring-deposit product with a published average rate was found for Greece.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GR', 1, 'equity_return_base', 0.055, NULL, 'assumption', 'Athens General index (Trading Economics); tax-free 3-month treasury bill 2.76%', 'https://tradingeconomics.com/greece/stock-market', '2026-10-31', 'Base case capped near the tax-free bill rate plus about 3 points because the Greek index has a weak 25-year record despite its strong recovery since 2016.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GR', 1, 'equity_return_high', 0.075, NULL, 'assumption', 'Athens General index (Trading Economics); global equity long-run returns', 'https://tradingeconomics.com/greece/stock-market', '2026-10-31', 'High case: a diversified euro equity fund matching long-run global equity returns of about 7-8% in euros.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GR', 1, 'equity_return_low', 0.03, NULL, 'assumption', 'Athens General index 2,619 on 30 Oct 2026, up about 30% in a year but still 60% below its 1999 high; after-tax 1-year deposit 1.1%', 'https://tradingeconomics.com/greece/stock-market', '2026-10-31', 'Low case: Greek shares repeat a long flat stretch like 2000-2020 and earn little more than safe instruments.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GR', 1, 'fdr_1y_rate', 0.0128, NULL, 'sourced', 'ECB MFI interest rate statistics: Greek banks, household deposits with agreed maturity up to 1 year (new business)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.GR.B.L22.F.R.A.2250.EUR.N', '2026-09-30', 'Bucket covers all fixed terms up to one year: 1.28% in September 2026 (1.17% in August).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GR', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'ECB/Bank of Greece MFI statistics publish household deposits with agreed maturity up to 1 year as one bucket (1.28% in September 2026); no separate 3-month rate found and bankofgreece.gr refused automated access.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GR', 1, 'fixed_income_return_base', 0.015, NULL, 'assumption', 'After-tax 1-year deposit 1.1%; tax-free 3-month treasury bill 2.76%', 'https://tradingeconomics.com/greece/government-bond-yield', '2026-10-31', 'Base case: a mix of after-tax term deposits and tax-exempt Greek treasury bills, kept below the bill rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GR', 1, 'fixed_income_return_high', 0.03, NULL, 'assumption', 'Greece 10-year government bond 4.32%, tax-exempt for individuals', 'https://tradingeconomics.com/greece/government-bond-yield', '2026-10-31', 'High case: holding Greek government bonds, whose interest is tax-free, with some price risk.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GR', 1, 'fixed_income_return_low', 0.01, NULL, 'assumption', 'Household deposits up to 1 year 1.28% (September 2026) less 15% withholding = 1.1% (ECB MFI statistics)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.GR.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Low case: after-tax term deposits only.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GR', 1, 'goal_inflation_education', 0.03, NULL, 'assumption', 'Eurostat/ECB HICP Greece, education: 2.8% year on year in December 2025', 'https://data-api.ecb.europa.eu/service/data/ICP/M.GR.N.100000.4.ANR', '2026-10-31', 'Education prices (mainly private tutoring and schools; public education is free) rose 2.8% in 2025; 3% is used for planning.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GR', 1, 'goal_inflation_health', 0.03, NULL, 'assumption', 'Eurostat/ECB HICP Greece, health: 0.4% year on year in December 2025', 'https://data-api.ecb.europa.eu/service/data/ICP/M.GR.N.060000.4.ANR', '2026-10-31', 'Measured health prices have been held down by regulated prices, but private care costs tend to rise faster than general prices, so 3% is used for planning.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GR', 1, 'gold_return_base', 0.04, NULL, 'assumption', 'Gold price history (Trading Economics); ECB 2% inflation target', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Base case: dollar gold rises roughly with world inflation plus a little, and the euro is assumed stable against the dollar over the long run.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GR', 1, 'gold_return_high', 0.07, NULL, 'assumption', 'Gold price history (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'High case: a repeat of gold''s strong 2005-2025 trend in euro terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GR', 1, 'gold_return_low', 0.01, NULL, 'assumption', 'Gold USD 3,876/oz on 30 Oct 2026, 31% below the January 2026 high', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Low case: gold barely keeps up after the 2025-26 spike, with no help from the euro.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GR', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'Greek law gives severance on dismissal (scaled by length of service) and a reduced retirement severance (40% of the dismissal amount) under Law 2112/1920 as amended, not a fixed days-per-year gratuity; no source stating the current scale was read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GR', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'Public hospital care is covered by EOPYY; no official figure for a typical out-of-pocket cost of a major private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GR', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Private health insurance is sold in Greece, but no published premium table per EUR 100,000 of cover was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GR', 1, 'inflation_cpi', 0.05, NULL, 'sourced', 'Trading Economics (ELSTAT CPI, September 2026)', 'https://tradingeconomics.com/greece/inflation-cpi', '2026-09-30', 'CPI 5.0% year on year in September 2026 (3.8% in August), released 9 October 2026; secondary source because statistics.gr was not reachable. HICP averaged 2.9% in 2025 (ECB).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GR', 1, 'inflation_projection', 0.025, NULL, 'assumption', 'ECB 2% medium-term target; Greek HICP 2021-2025 average 4.0% (ECB ICP); CPI 5.0% in September 2026', 'https://data-api.ecb.europa.eu/service/data/ICP/A.GR.N.000000.4.AVR', '2026-10-31', 'The ECB 2% target anchors euro-area inflation over the long run, but Greek inflation has run above the euro average (5.0% in September 2026), so 2.5% is used for planning.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GR', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life cover is sold in Greece, but no published premium table or regulator premium data per sum insured was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GR', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Neither the Bank of Greece insurance supervision department nor the Hellenic Association of Insurance Companies publishes an industry life claim settlement ratio that could be found; bankofgreece.gr refused automated access.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GR', 1, 'life_expectancy', 82.4, NULL, 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/greece', '2026-07-01', 'Men 79.9, women 84.7 (UN WPP estimate for 2026); World Bank 2024 figure 81.8.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GR', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":24.6,"men":22.8,"women":26.2},{"age":65,"total":20.4,"men":18.8,"women":21.7},{"age":70,"total":16.4,"men":15.2,"women":17.5},{"age":80,"total":9.5,"men":8.6,"women":10.2}]}', 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/greece', '2026-07-01', 'Remaining years computed from georank''s expected age at death by current age (UN WPP 2026 estimate).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GR', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":67,"womenAge":67,"over90Monthly":null,"meansTested":true}', 'sourced', 'OPEKA, social solidarity allowance for uninsured elderly', 'https://opeka.gov.gr/anasfalistoi-yperilikes/epidoma-koinonikis-allilengyis-anasfaliston-yperilikon/', '2026-10-31', 'Age 67, 20 years of permanent legal residence in Greece, no pension from Greece or abroad, and annual taxable income up to EUR 4,320 (single) or EUR 8,640 (couple).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GR', 1, 'old_age_allowance_monthly', 418.95, NULL, 'sourced', 'OPEKA, social solidarity allowance for uninsured elderly (FAQ)', 'https://opeka.gov.gr/anasfalistoi-yperilikes/epidoma-koinonikis-allilengyis-anasfaliston-yperilikon/sychnes-erotiseis/', '2026-10-31', 'EUR 418.95 a month (the eligibility section of the same page still shows the earlier EUR 409.13; the July 2026 EC guide gives EUR 399.54 and 418.95 in different places).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GR', 1, 'oop_health_share', 0.343, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=GR', '2023-12-31', 'Out-of-pocket spending was 34.3% of current health expenditure in 2023, among the highest in the EU (latest available; older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GR', 1, 'policy_rate', 0.025, NULL, 'sourced', 'European Central Bank, key ECB interest rates (deposit facility)', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.en.html', '2026-09-16', 'Greece uses the euro; ECB deposit facility rate 2.50% since 16 September 2026, still 2.50% on 31 October 2026 (ECB data portal FM.D.U2.EUR.4F.KR.DFR.LEV).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GR', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":67,"nomineeUntilAge":null,"inflationLinked":true,"taxFree":false}', 'sourced', 'European Commission, Your social security rights in Greece (July 2026)', 'https://employment-social-affairs.ec.europa.eu/document/download/f476ffdd-db90-48e3-8e1b-cd861a3f82e1_en', '2026-07-31', 'Compulsory e-EFKA pension: a tax-funded national pension (EUR 446.87 a month with 20 insurance years) plus a contributory part; pensions are taxed as income (only those of people with 80%+ disability are exempt). Yearly increases follow Law 4387/2016 (half GDP growth plus half CPI, at most CPI), which is not described in the guide.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GR', 1, 'retirement_accumulation_return_base', 0.035, NULL, 'assumption', 'Fixed income base 1.5%; equity base 5.5%', 'https://tradingeconomics.com/greece/stock-market', '2026-10-31', 'Base case: roughly half shares at 5.5% and half safe fixed income at about 1.5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GR', 1, 'retirement_accumulation_return_high', 0.05, NULL, 'assumption', 'Tax-free 10-year bond 4.32%; equity high 7.5%', 'https://tradingeconomics.com/greece/government-bond-yield', '2026-10-31', 'High case for a growth-leaning balanced mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GR', 1, 'retirement_accumulation_return_low', 0.02, NULL, 'assumption', 'After-tax 1-year deposit 1.1%; Athens General record (Trading Economics)', 'https://tradingeconomics.com/greece/stock-market', '2026-10-31', 'Low case for a balanced mix if shares lag.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GR', 1, 'retirement_age_default', 67, NULL, 'sourced', 'European Commission, Your social security rights in Greece (July 2026)', 'https://employment-social-affairs.ec.europa.eu/document/download/f476ffdd-db90-48e3-8e1b-cd861a3f82e1_en', '2026-07-31', 'General pension age 67 with at least 15 insurance years (4,500 days); a full pension is also payable from 62 with 40 insurance years. The July 2026 guide gives no later age for younger cohorts, so 67 is used for people born after 1975 (it may be raised in future if Greece applies its life-expectancy link).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GR', 1, 'retirement_age_government', 67, NULL, 'sourced', 'European Commission, Your social security rights in Greece (July 2026)', 'https://employment-social-affairs.ec.europa.eu/document/download/f476ffdd-db90-48e3-8e1b-cd861a3f82e1_en', '2026-07-31', 'Civil servants are insured with e-EFKA under the same unified rules since 2017, so the general age limit of 67 (62 with 40 years) applies.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GR', 1, 'retirement_return_base', 0.015, NULL, 'assumption', 'After-tax 1-year deposit 1.1%; tax-free 3-month treasury bill 2.76%', 'https://tradingeconomics.com/greece/government-bond-yield', '2026-10-31', 'Base case: a mix of term deposits and tax-exempt treasury bills, kept well below the bill rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GR', 1, 'retirement_return_high', 0.025, NULL, 'assumption', 'Greece 10-year government bond 4.32%, tax-exempt for individuals', 'https://tradingeconomics.com/greece/government-bond-yield', '2026-10-31', 'High case: a ladder of tax-exempt Greek government bonds, below the 10-year yield to allow for reinvestment risk.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GR', 1, 'retirement_return_low', 0.01, NULL, 'assumption', 'Household deposits up to 1 year 1.28% (September 2026) less 15% withholding = 1.1% (ECB MFI statistics)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.GR.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Low case: after-tax term deposits only.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GR', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Greece has no government savings certificate or retail savings bond for individuals; individuals buy ordinary Greek government bonds and treasury bills through banks.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GR', 1, 'savings_account_rate', 0.0003, NULL, 'sourced', 'ECB MFI interest rate statistics: Greek banks, overnight deposits from households (new business)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.GR.B.L21.A.R.A.2250.EUR.N', '2026-09-30', 'Average rate on household overnight deposits in Greece was 0.03% every month from April to September 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GR', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":2.57},{"year":2040,"value":1.87},{"year":2065,"value":1.67}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/greece/2040/', '2025-12-31', '100 / old-age dependency ratio: 38.9 (2025, World Bank), 53.5 (2040) and 59.8 (2065, populationpyramid.net/greece/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GR', 1, 'tax_bank_interest', 0.15, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Greece income determination', 'https://taxsummaries.pwc.com/greece/individual/income-determination', '2026-09-08', 'Interest is subject to 15% withholding tax, which fully settles the tax for individuals.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GR', 1, 'tax_sanchayapatra_profit', 0, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Greece income determination', 'https://taxsummaries.pwc.com/greece/individual/income-determination', '2026-09-08', 'No savings certificate exists; PwC states that interest on bond loans and promissory notes of the Greek State acquired by individuals is exempt from income tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GR', 1, 'tbill_91d_rate', 0.0276, NULL, 'sourced', 'Trading Economics, Greece 3-month government bill yield', 'https://tradingeconomics.com/greece/government-bond-yield', '2026-10-30', 'Secondary-market 3-month yield on the Greece bond page (1-month 2.68%, 6-month 2.82%); the Public Debt Management Agency auctions 13-week treasury bills.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GR', 1, 'tbond_10y_rate', 0.0432, NULL, 'sourced', 'Trading Economics, Greece 10-year government bond yield', 'https://tradingeconomics.com/greece/government-bond-yield', '2026-10-30', 'Page shows 4.32% (summary 4.35%); ECB long-term (10-year) convergence yield for Greece was 4.22% in September 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GR', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 5-year Greek government bond yield found: Trading Economics shows no 5-year series for Greece, worldgovernmentbonds.com loads by script and bankofgreece.gr refused automated access.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('GT', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"GT","iso3":"GTM","nameEn":"Guatemala","nameNative":"Guatemala","region":"latin_america_caribbean","languages":["es","quc","mam","cak","kek"],"currency":{"code":"GTQ","symbol":"Q","decimals":2,"compact":"intl","usdRate":{"value":7.6801,"status":"sourced","sourceName":"World Bank WDI PA.NUS.FCRF","sourceUrl":"https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=GT","asOf":"2025-12-31","note":"Official rate, 2025 average. Trading Economics shows 7.645 quetzales per dollar on 30 October 2026; the Banco de Guatemala site was unreachable (HTTP 522) during research."}},"instruments":{"savings_account":{"available":true,"localName":"Cuenta de ahorro","localNameEn":"Savings account"},"fdr_3m":{"available":true,"localName":"Depósito a plazo fijo","localNameEn":"3-month fixed-term deposit"},"fdr_1y":{"available":true,"localName":"Depósito a plazo fijo","localNameEn":"1-year fixed-term deposit"},"dps":{"available":false,"localName":null,"note":"No standard monthly recurring deposit product with a published rate was found."},"sanchayapatra_5y":{"available":false,"localName":null,"note":"No government savings certificate or retail savings bond for individuals was confirmed."},"tbill_91d":{"available":false,"localName":null,"note":"No regular 91-day government bill issue was confirmed; the government borrows mainly through Bonos del Tesoro."},"tbond_5y":{"available":true,"localName":"Bonos del Tesoro","localNameEn":"Government of Guatemala Treasury bonds (quetzales)","note":"Issued by the Ministry of Finance in several maturities; current yields could not be read."},"tbond_10y":{"available":true,"localName":"Bonos del Tesoro","localNameEn":"Government of Guatemala Treasury bonds (quetzales)","note":"Issued by the Ministry of Finance in long maturities; current yields could not be read."},"equity_fund":{"available":false,"localName":null,"note":"No retail equity or index fund registered locally was identified; local share trading is minimal."},"gold":{"available":true,"localName":"Oro","localNameEn":"Gold jewellery and coins","note":"No legal restriction on buying gold; mostly sold as jewellery."}},"institutions":{"centralBank":{"name":"Banco de Guatemala","url":"https://www.banguat.gob.gt/"},"insuranceRegulator":{"name":"Superintendencia de Bancos (SIB)","url":"https://www.sib.gob.gt/","note":"Supervises banks and insurers."},"insuranceComplaints":{"name":"Superintendencia de Bancos (SIB)","url":"https://www.sib.gob.gt/","note":"Complaints about insurers go to the SIB user service."},"pensionScheme":{"name":"Instituto Guatemalteco de Seguridad Social (IGSS), programa IVS","url":"https://www.igssgt.org/programa-de-invalidez-vejez-y-sobrevivencia/"},"oldAgeAllowance":{"name":"Programa de Aporte Económico del Adulto Mayor (PAM), Ministerio de Trabajo","url":"https://mintrabajo.gob.gt/programa-de-aporte-economico-del-adulto-mayor-pam/"},"publicHealthCover":{"name":"Ministerio de Salud Pública y Asistencia Social (free public hospitals and health centres)","url":"https://www.mspas.gob.gt/"},"depositInsurance":null,"statistics":{"name":"Instituto Nacional de Estadística (INE)","url":"https://www.ine.gob.gt/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GT', 1, 'bank_deposit_avg_rate', 0.0511, NULL, 'sourced', 'World Bank WDI FR.INR.DPST', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=GT', '2025-12-31', 'Average rate paid by commercial banks on deposits in 2025 (Banco de Guatemala data via IMF IFS), up from 4.93% in 2024.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GT', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched for an official cap or typical credit-card rate: Superintendencia de Bancos statistics were blocked; no figure confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GT', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'Guatemala has a deposit protection fund (Fondo para la Proteccion del Ahorro, FOPA), but the Superintendencia de Bancos and Banco de Guatemala pages stating the cover limit were blocked or unreachable during research, so the limit is not confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GT', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published rate for a monthly recurring (programmed) savings deposit was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GT', 1, 'equity_return_base', 0.07, NULL, 'assumption', 'World Bank average deposit rate 5.11% (2025), 10% tax on interest; Banco de Guatemala policy rate 3.5%', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=GT', '2026-10-31', 'Base case uses a global equity index in quetzal terms (the quetzal has been stable near 7.6-7.8 per dollar): the 4.6% after-tax deposit rate plus about 2.5 points.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GT', 1, 'equity_return_high', 0.1, NULL, 'assumption', 'World Bank average deposit rate 5.11% (2025); quetzal near 7.6-7.8 per US dollar', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=GT', '2026-10-31', 'High case if global equities repeat strong long-run dollar returns and the quetzal weakens slightly.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GT', 1, 'equity_return_low', 0.025, NULL, 'assumption', 'World Bank average deposit rate 5.11% (2025), 10% tax on interest; Banco de Guatemala policy rate 3.5%', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=GT', '2026-10-31', 'Low case: the local stock exchange has almost no equity trading, so savers rely on global funds in quetzal terms, and a weak decade is possible.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GT', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched for Superintendencia de Bancos and Banco de Guatemala term-deposit rate tables: sites blocked or unreachable; the World Bank average rate on all deposits was 5.11% in 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GT', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched for Superintendencia de Bancos and Banco de Guatemala term-deposit rate tables: sites blocked or unreachable; no other public source found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GT', 1, 'fixed_income_return_base', 0.04, NULL, 'assumption', 'World Bank average deposit rate 5.11% (2025); PwC: 10% withholding on interest', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=GT', '2026-10-31', 'Base case: term deposits near the 5.1% average deposit rate, about 4.6% after tax, with some cash.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GT', 1, 'fixed_income_return_high', 0.05, NULL, 'assumption', 'World Bank average deposit rate 5.11% (2025); PwC: 10% withholding on interest', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=GT', '2026-10-31', 'High case: longer term deposits or government bonds at 5.5-6% before tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GT', 1, 'fixed_income_return_low', 0.02, NULL, 'assumption', 'World Bank average deposit rate 5.11% (2025); PwC: 10% withholding on interest', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=GT', '2026-10-31', 'Low case: mostly savings deposits at low rates after the 10% tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GT', 1, 'goal_inflation_education', 0.05, NULL, 'assumption', 'Banco de Guatemala 4% inflation target; CPI 4.69% (September 2026)', 'https://tradingeconomics.com/guatemala/inflation-cpi', '2026-10-31', 'No long-run education CPI series could be read; planning inflation plus 1 point for private schooling.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GT', 1, 'goal_inflation_health', 0.06, NULL, 'assumption', 'Banco de Guatemala 4% inflation target; CPI 4.69% (September 2026)', 'https://tradingeconomics.com/guatemala/inflation-cpi', '2026-10-31', 'No long-run medical CPI series could be read; planning inflation plus 2 points for private medical costs.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GT', 1, 'gold_return_base', 0.05, NULL, 'assumption', 'World Bank PA.NUS.FCRF: 7.68 quetzales per US dollar (2025), little changed over a decade', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=GT', '2026-10-31', 'Dollar gold trend of about 4.5% a year plus a little expected quetzal depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GT', 1, 'gold_return_high', 0.085, NULL, 'assumption', 'World Bank PA.NUS.FCRF: 7.68 quetzales per US dollar (2025)', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=GT', '2026-10-31', 'High case with strong dollar gold and some quetzal weakening.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GT', 1, 'gold_return_low', 0.01, NULL, 'assumption', 'World Bank PA.NUS.FCRF: 7.68 quetzales per US dollar (2025), little changed over a decade', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=GT', '2026-10-31', 'Low case: weak dollar gold price with a stable quetzal.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GT', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Labour Code requires an indemnity of one month''s wages per year of service on unjustified dismissal, but whether any statutory payment applies on retirement could not be confirmed (Congress and Ministry sites with the Code text were blocked).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GT', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No official or public figure for a typical private hospital stay found (Ministry of Health site blocked).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GT', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No regulator or public source publishing private health insurance premiums by age was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GT', 1, 'inflation_cpi', 0.0469, NULL, 'sourced', 'Trading Economics, Guatemala inflation rate (INE consumer price index)', 'https://tradingeconomics.com/guatemala/inflation-cpi', '2026-09-30', 'Secondary source: year-on-year CPI inflation 4.69% in September 2026, up from 3.37% in August; the INE site blocks automated reading and the Banco de Guatemala site was unreachable (HTTP 522) during research.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GT', 1, 'inflation_projection', 0.04, NULL, 'assumption', 'Guatemala CPI history (Trading Economics: 4.69% in September 2026; World Bank 1.5% in 2025); Banco de Guatemala''s announced 4% +/- 1 point target', 'https://tradingeconomics.com/guatemala/inflation-cpi', '2026-10-31', 'We plan with the central bank''s 4% target (not shown on the linked page; the Banco de Guatemala site was unreachable), which recent inflation of 1.5-4.7% has mostly stayed within.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GT', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life is sold in Guatemala, but no regulator or public source publishing indicative premiums by age was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GT', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Superintendencia de Bancos insurance statistics were blocked; no industry-wide life claim settlement ratio found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GT', 1, 'life_expectancy', 72.746, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=GT', '2024-12-31', 'UN WPP 2024 (via populationpyramid.net) gives 73.0 for 2026 (men 70.7, women 75.4).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GT', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":20.2,"men":19.5,"women":20.9},{"age":65,"total":16.5,"men":15.8,"women":17.1},{"age":70,"total":13,"men":12.4,"women":13.5},{"age":80,"total":6.8,"men":6.4,"women":7.2}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/guatemala/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026; sex-specific values are for the 5-year age groups starting at each age; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GT', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":65,"womenAge":65,"over90Monthly":null,"meansTested":true}', 'sourced', 'Ministerio de Trabajo y Prevision Social, Programa de Aporte Economico del Adulto Mayor (PAM)', 'https://mintrabajo.gob.gt/programa-de-aporte-economico-del-adulto-mayor-pam/', '2026-10-31', 'Guatemalans aged 65 or more in extreme poverty or social vulnerability (shown by a socio-economic study), not receiving a pension and not employed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GT', 1, 'old_age_allowance_monthly', 500, NULL, 'sourced', 'Ministerio de Trabajo y Prevision Social, Condiciones de pobreza extrema en personas de 65 anos o mas (PAM 2026)', 'https://mintrabajo.gob.gt/wp-content/uploads/2026/06/Condiciones-de-Pobreza-Extrema-PAM-2026.pdf', '2026-06-30', 'The Programa de Aporte Economico del Adulto Mayor (Decreto 85-2005, reformed by Decreto 4-2022) currently pays Q500 a month (Q6,000 a year) to each beneficiary.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GT', 1, 'oop_health_share', 0.5718, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=GT', '2023-12-31', 'Figure is for 2023 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GT', 1, 'policy_rate', 0.035, NULL, 'sourced', 'Trading Economics, Guatemala interest rate (Banco de Guatemala tasa de interes lider)', 'https://tradingeconomics.com/guatemala/interest-rate', '2026-10-31', 'Secondary source: the monetary-policy leading rate (tasa lider) is 3.50% for October 2026, unchanged from the previous decision; the Banco de Guatemala site was unreachable (HTTP 522) during research.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GT', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":60,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'Instituto Guatemalteco de Seguridad Social (IGSS), Pension por riesgo de Vejez (IVS)', 'https://www.igssgt.org/pension-por-riesgo-de-vejez/', '2026-10-31', 'Compulsory contributory IGSS Invalidez, Vejez y Sobrevivencia programme for formal employees: pension from 60 with at least 240 months of contributions. No automatic indexation rule was found; tax treatment not confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GT', 1, 'retirement_accumulation_return_base', 0.055, NULL, 'assumption', 'Average deposit rate 5.11% (2025); global equity assumptions in quetzal terms', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=GT', '2026-10-31', 'Base case: half global equities at 7% and half term deposits at about 4%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GT', 1, 'retirement_accumulation_return_high', 0.075, NULL, 'assumption', 'Average deposit rate 5.11% (2025); global equity assumptions in quetzal terms', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=GT', '2026-10-31', 'High case with stronger equity returns.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GT', 1, 'retirement_accumulation_return_low', 0.035, NULL, 'assumption', 'Average deposit rate 5.11% (2025); global equity assumptions in quetzal terms', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=GT', '2026-10-31', 'Low case for a balanced mix if global equities disappoint.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GT', 1, 'retirement_age_default', 60, NULL, 'sourced', 'Instituto Guatemalteco de Seguridad Social (IGSS), Pension por riesgo de Vejez (IVS)', 'https://www.igssgt.org/pension-por-riesgo-de-vejez/', '2026-10-31', 'IGSS old-age pension requires age 60 and at least 240 months of contributions, the same for men and women; no scheduled increase found. The page carries no date.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GT', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'Could not confirm a compulsory retirement age for civil servants under the Regimen de Clases Pasivas Civiles del Estado (ONSEC and Congress sites blocked).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GT', 1, 'retirement_return_base', 0.04, NULL, 'assumption', 'World Bank average deposit rate 5.11% (2025); PwC: 10% withholding on interest', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=GT', '2026-10-31', 'Base case below the 4.6% after-tax average deposit rate, keeping part in liquid savings.', 0);
