INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GT', 1, 'retirement_return_low', 0.025, NULL, 'assumption', 'World Bank average deposit rate 5.11% (2025); PwC: 10% withholding on interest', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=GT', '2026-10-31', 'Low case: savings deposits and short term deposits after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GT', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched for a government savings certificate or retail savings bond for individuals: none confirmed; the Ministry of Finance and central bank sites were blocked or unreachable.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GT', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched for Superintendencia de Bancos and Banco de Guatemala interest-rate statistics: both sites blocked or unreachable during research; no other public source for a typical savings account rate found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GT', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":12.9},{"year":2040,"value":9.9},{"year":2065,"value":4.1}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/guatemala/2040/', '2025-12-31', '100 / old-age dependency ratio: 7.75 (2025, World Bank), 10.1 (2040) and 24.4 (2065, populationpyramid.net/guatemala/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GT', 1, 'tax_bank_interest', 0.1, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Guatemala: Individual - Income determination', 'https://taxsummaries.pwc.com/guatemala/individual/income-determination', '2026-06-09', 'Interest earned by domiciled individuals is subject to 10% income tax withholding (capital income); page last reviewed 9 June 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GT', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate for individuals was confirmed, and the tax treatment of interest on government securities could not be verified (PwC summary does not mention an exemption).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GT', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Guatemala finances itself mainly with medium and long Bonos del Tesoro; no current 91-day government bill yield could be found (the Banco de Guatemala site was unreachable (HTTP 522) during research, Ministry of Finance site blocked).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GT', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No readable current 10-year Bonos del Tesoro yield: Ministry of Finance and central bank sites were blocked or unreachable.', 0);
