INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('GW', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"GW","iso3":"GNB","nameEn":"Guinea-Bissau","nameNative":"Guiné-Bissau","region":"sub_saharan_africa","languages":["pov","pt","ff","bjt","mnk"],"currency":{"code":"XOF","symbol":"F CFA","decimals":0,"compact":"intl","usdRate":{"value":589,"status":"sourced","sourceName":"BCEAO, rates of foreign currencies against the CFA franc for transfers, 30 October 2026","sourceUrl":"https://www.bceao.int/fr/cours/cours-des-devises-contre-Franc-CFA-appliquer-aux-transferts","asOf":"2026-10-30","note":"Mid-point of the buying (585.50) and selling (592.50) rates for the US dollar; the CFA franc is pegged at 655.957 per euro. World Bank 2025 average 581.9."}},"instruments":{"savings_account":{"available":true,"localName":"Conta poupança","localNameEn":"Savings account","note":"Banks offer savings accounts; no average rate is published."},"fdr_3m":{"available":true,"localName":"Depósito a prazo (3 meses)","localNameEn":"Term deposit (3 months)","note":"Minimum term-deposit rates of 2.25-3.50% declared to the BCEAO (first half 2026).","sourceUrl":"https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf"},"fdr_1y":{"available":true,"localName":"Depósito a prazo (1 ano)","localNameEn":"Term deposit (1 year)","note":"Maximum term-deposit rates of 4.0-6.75% declared to the BCEAO (first half 2026); no 1-year average is published.","sourceUrl":"https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf"},"dps":{"available":true,"localName":"Poupança contratual","localNameEn":"Contractual savings plan","note":"Contractual savings at about 3.50% (BCEAO bank-conditions survey, first half 2026).","sourceUrl":"https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf"},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate for individuals was found."},"tbill_91d":{"available":true,"localName":"Bilhetes do Tesouro","localNameEn":"Treasury bills","note":"Auctioned through UMOA-Titres to banks and primary dealers; individuals buy through a bank or broker.","sourceUrl":"https://www.umoatitres.org/wp-content/uploads/2026/10/COURBES-DE-TAUX.au_.23.10.2026.xlsx"},"tbond_5y":{"available":true,"localName":"Obrigações do Tesouro","localNameEn":"Treasury bonds","note":"Auctioned through UMOA-Titres; individuals buy through a bank or broker.","sourceUrl":"https://www.umoatitres.org/wp-content/uploads/2026/10/COURBES-DE-TAUX.au_.23.10.2026.xlsx"},"tbond_10y":{"available":false,"localName":null,"localNameEn":null,"note":"Guinea-Bissau''s yield curve stops at 7 years; no 10-year bond was found."},"equity_fund":{"available":true,"localName":"Fundos comuns de investimento (BRVM)","localNameEn":"Regional mutual funds (BRVM)","note":"No local exchange; residents can buy regional mutual funds investing on the BRVM through approved intermediaries."},"gold":{"available":true,"localName":"Ouro","localNameEn":"Gold","note":"Gold is sold mainly as jewellery; no official bullion or coin scheme was found."}},"institutions":{"centralBank":{"name":"Banque Centrale des États de l''Afrique de l''Ouest (BCEAO)","url":"https://www.bceao.int/"},"insuranceRegulator":{"name":"Commission Régionale de Contrôle des Assurances (CIMA)","url":"https://cima-afrique.org/","note":"Regional insurance regulator for the CIMA member states, Guinea-Bissau included."},"insuranceComplaints":{"name":"CIMA policyholder requests and complaints form","url":"https://cima-afrique.org/faites-votre-requetes-ici-2/"},"pensionScheme":null,"oldAgeAllowance":null,"publicHealthCover":null,"depositInsurance":{"name":"Fonds de Garantie des Dépôts et de Résolution dans l''UMOA (FGDR-UMOA)","url":"https://www.fgd-umoa.org/"},"statistics":{"name":"Instituto Nacional de Estatística (INE)","url":"https://www.stat-guinebissau.com/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GW', 1, 'bank_deposit_avg_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No Guinea-Bissau average deposit rate was found: the BCEAO Note de conjoncture (September 2026) gives only the UMOA-wide average (5.15% in July 2026) and says Guinea-Bissau''s rate fell 1.46 points in the month without giving its level; the World Bank FR.INR.DPST series for Guinea-Bissau stops in 2016 (6.9%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GW', 1, 'credit_card_rate_cap', 0.14, NULL, 'sourced', 'BCEAO, conditions débitrices of UMOA credit institutions, first half 2026 (Guinea-Bissau)', 'https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf', '2026-06-30', 'Median maximum lending rate (taux débiteur maximum) declared by Guinea-Bissau''s 6 banks for the first half of 2026 (range 12-15%); it applies to all bank credit, including cards. No card-specific rate is published.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GW', 1, 'deposit_insurance_limit', 1400000, NULL, 'sourced', 'UMOA Council of Ministers, Decision of 30 June 2017 on FGD-UMOA contribution rates and compensation ceilings', 'https://www.fgd-umoa.org/wp-content/uploads/2024/10/Decision-du-CM-relative-aux-taux-de-contribution-et-aux-plafonds-d-indemnistation-2-1.pdf', '2017-06-30', 'Deposits are guaranteed up to 1,400,000 FCFA per depositor per bank (300,000 FCFA at a microfinance institution) by the regional deposit guarantee fund; the decision dates from 2017 (older than 2025), and no later change was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GW', 1, 'dps_rate', 0.035, NULL, 'sourced', 'BCEAO, conditions créditrices of UMOA credit institutions, first half 2026 (Guinea-Bissau, épargne contractuelle)', 'https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf', '2026-06-30', 'Median rate on contractual savings plans declared by Guinea-Bissau''s banks in the first half of 2026; five of six declare 3.50% (range 3.50-3.75%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GW', 1, 'equity_return_base', 0.08, NULL, 'assumption', 'BCEAO monthly economic note, September 2026 (regional stock exchange BRVM); UMOA-Titres Guinea-Bissau yield curve', 'https://www.umoatitres.org/wp-content/uploads/2026/10/COURBES-DE-TAUX.au_.23.10.2026.xlsx', '2026-10-31', 'Base case: about 3.5 points above after-tax term deposits and 1-year bills (about 4.5%), within the 4-point cap; Guinea-Bissau has no exchange of its own, so equity means regional BRVM funds, whose 10-year record is mixed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GW', 1, 'equity_return_high', 0.12, NULL, 'assumption', 'BCEAO monthly economic note, September 2026 (regional stock exchange BRVM)', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-10-31', 'High case: the BRVM repeats a strong decade like 2023-2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GW', 1, 'equity_return_low', 0.04, NULL, 'assumption', 'BCEAO monthly economic note, September 2026 (regional stock exchange BRVM); UMOA-Titres Guinea-Bissau yield curve', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-10-31', 'Low case: regional (BRVM) equities return about the bank deposit rate, as in their weak 2016-2020 years.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GW', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The BCEAO bank-conditions survey gives only minimum (median 3.25%) and maximum (median 6.4%, range 4.0-6.75%) term-deposit rates per bank in Guinea-Bissau for the first half of 2026, not a 1-year rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GW', 1, 'fdr_3m_rate', 0.0325, NULL, 'sourced', 'BCEAO, conditions créditrices of UMOA credit institutions, first half 2026 (Guinea-Bissau)', 'https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf', '2026-06-30', 'Median of the minimum term-deposit rates (taux DAT minimum) declared to the BCEAO by Guinea-Bissau''s 6 banks, range 2.25-3.50%; the minimum usually applies to small, short deposits. Not a tenor-specific average.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GW', 1, 'fixed_income_return_base', 0.045, NULL, 'assumption', 'BCEAO bank-conditions survey, first half 2026; UMOA-Titres Guinea-Bissau curve (1-year 5.61%)', 'https://www.umoatitres.org/wp-content/uploads/2026/10/COURBES-DE-TAUX.au_.23.10.2026.xlsx', '2026-10-31', 'Base case: larger term deposits (median maximum 6.4%) or 1-year Treasury bills (5.6%) through a bank, less tax on interest, rounded down because the tax rate is unconfirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GW', 1, 'fixed_income_return_high', 0.065, NULL, 'assumption', 'UMOA-Titres Guinea-Bissau yield curve (3-5 years 8.2-8.5%)', 'https://www.umoatitres.org/wp-content/uploads/2026/10/COURBES-DE-TAUX.au_.23.10.2026.xlsx', '2026-10-31', 'High case: 3-5 year Treasury bonds at about 8%, less a possible tax and an allowance for Guinea-Bissau''s higher credit risk.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GW', 1, 'fixed_income_return_low', 0.03, NULL, 'assumption', 'BCEAO bank-conditions survey, first half 2026 (Guinea-Bissau)', 'https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf', '2026-10-31', 'Low case: small term deposits or contractual savings at about 3.25-3.5%, less a possible tax on interest.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GW', 1, 'goal_inflation_education', 0.04, NULL, 'assumption', 'BCEAO 1-3% inflation target band; 2% planning inflation', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-10-31', 'No national education CPI series was read; private school fees usually rise faster than general prices, so 2 points above the 2% inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GW', 1, 'goal_inflation_health', 0.035, NULL, 'assumption', 'BCEAO 1-3% inflation target band; 2% planning inflation', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-10-31', 'No national medical CPI series was read; private and imported medical costs usually rise faster than general prices, so 1.5 points above the 2% inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GW', 1, 'gold_return_base', 0.045, NULL, 'assumption', 'BCEAO transfer rates (CFA franc pegged at 655.957 per euro); dollar gold trend', 'https://www.bceao.int/fr/cours/cours-des-devises-contre-Franc-CFA-appliquer-aux-transferts', '2026-10-31', 'Base case: the long-run dollar gold trend of about 4% a year plus a small allowance for the euro-pegged franc weakening against the dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GW', 1, 'gold_return_high', 0.08, NULL, 'assumption', 'BCEAO transfer rates (CFA franc pegged at 655.957 per euro); dollar gold trend', 'https://www.bceao.int/fr/cours/cours-des-devises-contre-Franc-CFA-appliquer-aux-transferts', '2026-10-31', 'High case: strong gold years such as 2024-2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GW', 1, 'gold_return_low', 0, NULL, 'assumption', 'BCEAO transfer rates (CFA franc pegged at 655.957 per euro); dollar gold trend', 'https://www.bceao.int/fr/cours/cours-des-devises-contre-Franc-CFA-appliquer-aux-transferts', '2026-10-31', 'Low case: flat gold in euro terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GW', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No official text on a statutory end-of-service indemnity for private employees in Guinea-Bissau could be read (the Labour Law was not reached).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GW', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a major private hospital stay in Guinea-Bissau was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GW', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premiums by age were found from a public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GW', 1, 'inflation_cpi', -0.005, NULL, 'sourced', 'BCEAO, Note de conjoncture économique des pays de l''UEMOA, September 2026 (national harmonised CPI, Guinea-Bissau)', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-08-31', 'Consumer prices fell 0.5% year on year in Guinea-Bissau in August 2026, after 0.0% in July (INE data via BCEAO); the 2025 average was +0.9% (World Bank).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GW', 1, 'inflation_projection', 0.02, NULL, 'assumption', 'BCEAO inflation target band of 1-3%; CFA franc pegged to the euro', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-10-31', 'Guinea-Bissau''s inflation has stayed low under the euro peg, so the 2% centre of the BCEAO''s 1-3% target band is used for long-range plans.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GW', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published term life premium rates per 1,000 FCFA of cover by age were found from a public source; the life insurance market is very small.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GW', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'CIMA (the regional insurance regulator) and Guinea-Bissau''s insurance directorate publish no industry-wide life claim settlement ratio that could be found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GW', 1, 'life_expectancy', 64.254, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN), Guinea-Bissau', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=GW', '2024-12-31', '64.3 years in 2024 (men 61.8, women 66.5).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GW', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":17,"men":15.9,"women":18},{"age":65,"total":13.7,"men":12.8,"women":14.4},{"age":70,"total":10.7,"men":10,"women":11.3},{"age":80,"total":6.1,"men":5.7,"women":6.4}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/guinea-bissau/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GW', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension was found (see old_age_allowance_monthly).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GW', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension for Guinea-Bissau was found; no source confirming that none exists could be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GW', 1, 'oop_health_share', 0.6156, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), Guinea-Bissau', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=GW', '2023-12-31', '61.6% in 2023 (WHO Global Health Expenditure Database via the World Bank), the latest available; older than 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GW', 1, 'policy_rate', 0.03, NULL, 'sourced', 'BCEAO, Note de conjoncture économique des pays de l''UEMOA, September 2026 (Monetary Policy Committee of 9 September 2026)', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-09-09', 'Main policy rate held at 3.00% (marginal lending facility 5.00%) by the Monetary Policy Committee on 9 September 2026; common to all eight UMOA countries.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GW', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":60,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'US Social Security Administration, Social Security Programs Throughout the World: Africa, 2019, Guinea-Bissau (archived copy)', 'https://web.archive.org/web/20251210050304/https://www.ssa.gov/policy/docs/progdesc/ssptw/2018-2019/africa/guinea-bissau.html', '2019-07-01', 'Compulsory INPS social insurance for private-sector employees (8% employee, 14% employer, also funding sickness benefits; laws of 1986 and 2007): pension from 60 after 10 years of contributions equal to 2% of average monthly earnings (best two of the last five years) per year of contributions, up to 80%; the source gives no automatic indexation of pensions and no tax rule. Civil servants have a separate scheme. 2019 edition, older than 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GW', 1, 'retirement_accumulation_return_base', 0.06, NULL, 'assumption', 'UMOA-Titres Guinea-Bissau yield curve; regional equity and gold assumptions above', 'https://www.umoatitres.org/wp-content/uploads/2026/10/COURBES-DE-TAUX.au_.23.10.2026.xlsx', '2026-10-31', 'Base case: a balanced mix of deposits or Treasury bonds, regional equity funds and some gold.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GW', 1, 'retirement_accumulation_return_high', 0.08, NULL, 'assumption', 'UMOA-Titres Guinea-Bissau yield curve; regional equity and gold assumptions above', 'https://www.umoatitres.org/wp-content/uploads/2026/10/COURBES-DE-TAUX.au_.23.10.2026.xlsx', '2026-10-31', 'High case: a growth-leaning mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GW', 1, 'retirement_accumulation_return_low', 0.035, NULL, 'assumption', 'BCEAO bank-conditions survey, first half 2026 (Guinea-Bissau)', 'https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf', '2026-10-31', 'Low case: a mix earning about after-tax deposit rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GW', 1, 'retirement_age_default', 60, NULL, 'sourced', 'US Social Security Administration, Social Security Programs Throughout the World: Africa, 2019, Guinea-Bissau (archived copy)', 'https://web.archive.org/web/20251210050304/https://www.ssa.gov/policy/docs/progdesc/ssptw/2018-2019/africa/guinea-bissau.html', '2019-07-01', 'Old-age pension (pensão de velhice) of the National Social Security Institute (INPS) at 60 with at least 10 years of contributions, same for men and women; a lump sum is paid with fewer than 10 years. Secondary source read through the Internet Archive because ssa.gov refused access and the INPS site was unreachable; the 2019 edition is older than 2025 and no later change was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GW', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'The retirement age of civil servants could not be confirmed from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GW', 1, 'retirement_return_base', 0.04, NULL, 'assumption', 'BCEAO bank-conditions survey, first half 2026; UMOA-Titres Guinea-Bissau curve (1-year 5.61%)', 'https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf', '2026-10-31', 'Base case: term deposits at 3.25-6.4% less a possible tax on interest, kept below the after-tax 1-year deposit and Treasury bill rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GW', 1, 'retirement_return_high', 0.055, NULL, 'assumption', 'UMOA-Titres Guinea-Bissau yield curve', 'https://www.umoatitres.org/wp-content/uploads/2026/10/COURBES-DE-TAUX.au_.23.10.2026.xlsx', '2026-10-31', 'High case: part of the money in short Treasury bonds bought through a bank.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GW', 1, 'retirement_return_low', 0.03, NULL, 'assumption', 'BCEAO bank-conditions survey, first half 2026 (Guinea-Bissau)', 'https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf', '2026-10-31', 'Low case: small term deposits or contractual savings at about 3.5%, less a possible tax on interest.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GW', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate sold to individuals was found; the Treasury borrows through UMOA-Titres auctions and regional public bond offers, open to individuals only through banks and brokers.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GW', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No average rate on ordinary savings accounts in Guinea-Bissau was found; the BCEAO bank-conditions survey (first half 2026) lists term-deposit and contractual-savings rates only.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GW', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":18.05},{"year":2040,"value":14.71},{"year":2065,"value":8.2}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://data.worldbank.org/indicator/SP.POP.DPND.OL?locations=GW', '2025-12-31', 'Working-age people per person 65+ = 100 / old-age dependency ratio. Old-age dependency ratios used: 5.54% in 2025 (World Bank), 6.8% in 2040 (populationpyramid.net/guinea-bissau/2040/) and 12.2% in 2065 (populationpyramid.net/guinea-bissau/2065/), giving 18.05, 14.71 and 8.2.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GW', 1, 'tax_bank_interest', NULL, NULL, 'missing', '', '', '2026-10-31', 'The withholding tax on bank interest for individuals in Guinea-Bissau could not be confirmed: PwC Worldwide Tax Summaries has no Guinea-Bissau page and the tax authority''s texts were not reached.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GW', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate exists, and the tax treatment of Treasury security interest for individuals could not be confirmed from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GW', 1, 'tbill_91d_rate', 0.0533, NULL, 'sourced', 'UMOA-Titres, Guinea-Bissau yield curve (zero coupon) at 23 October 2026', 'https://www.umoatitres.org/wp-content/uploads/2026/10/COURBES-DE-TAUX.au_.23.10.2026.xlsx', '2026-10-23', '3-month zero-coupon rate 5.33% (5.41% after smoothing); 1-year 5.61%. No recent Guinea-Bissau 3-month auction result page could be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GW', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The UMOA-Titres Guinea-Bissau yield curve (23 October 2026) stops at 7 years (7.04%); no 10-year rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GW', 1, 'tbond_5y_rate', 0.0851, NULL, 'sourced', 'UMOA-Titres, Guinea-Bissau yield curve (zero coupon) at 23 October 2026', 'https://www.umoatitres.org/wp-content/uploads/2026/10/COURBES-DE-TAUX.au_.23.10.2026.xlsx', '2026-10-23', '5-year zero-coupon rate 8.51% (8.10% after smoothing).', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('GY', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"GY","iso3":"GUY","nameEn":"Guyana","nameNative":"Guyana","region":"latin_america_caribbean","languages":["en","gyn"],"currency":{"code":"GYD","symbol":"$","decimals":2,"compact":"intl","usdRate":{"value":208.5,"status":"sourced","sourceName":"World Bank WDI PA.NUS.FCRF","sourceUrl":"https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=GY","asOf":"2025-12-31","note":"Official rate, 2025; the Budget Speech 2026 also uses GYD 208.50 per US dollar."}},"instruments":{"savings_account":{"available":true,"localName":"Savings account","note":"Small savings rate 0.81% (2025).","sourceUrl":"https://finance.gov.gy/wp-content/uploads/2026/01/Budget_Speech_2026.pdf"},"fdr_3m":{"available":true,"localName":"Fixed deposit","localNameEn":"3-month time deposit"},"fdr_1y":{"available":true,"localName":"Fixed deposit","localNameEn":"12-month time deposit"},"dps":{"available":false,"localName":null,"note":"No standard monthly recurring deposit product with a published rate."},"sanchayapatra_5y":{"available":false,"localName":null,"note":"No government savings certificate or retail savings bond for individuals was found."},"tbill_91d":{"available":true,"localName":"Treasury bill","localNameEn":"Government of Guyana 91-day Treasury bill","note":"Auctioned by the Bank of Guyana (91, 182 and 364 days); mostly bought by banks.","sourceUrl":"https://finance.gov.gy/wp-content/uploads/2026/01/Budget_Speech_2026.pdf"},"tbond_5y":{"available":false,"localName":null,"note":"No regular 5-year domestic government bond."},"tbond_10y":{"available":false,"localName":null,"note":"No regular 10-year domestic government bond."},"equity_fund":{"available":false,"localName":null,"note":"No locally registered retail equity or index fund was identified; the local stock exchange is small."},"gold":{"available":true,"localName":"Gold","localNameEn":"Gold jewellery, bars and coins","note":"Guyana is a gold producer; buying gold is legal."}},"institutions":{"centralBank":{"name":"Bank of Guyana","url":"https://bankofguyana.org.gy/"},"insuranceRegulator":{"name":"Bank of Guyana (insurance supervision)","url":"https://bankofguyana.org.gy/","note":"The Bank of Guyana supervises insurers under the Insurance Act 2016."},"insuranceComplaints":{"name":"Bank of Guyana (insurance supervision)","url":"https://bankofguyana.org.gy/"},"pensionScheme":{"name":"National Insurance Scheme (NIS)","url":"https://www.nis.org.gy/"},"oldAgeAllowance":{"name":"Old Age Pension (Ministry of Human Services and Social Security)","url":"https://dpi.gov.gy/category/news-bulletin/government/ministry-of-human-services-and-social-security/","note":"Universal pension from 65; link is the government information agency page for the ministry."},"publicHealthCover":{"name":"Ministry of Health (free care at public hospitals and health centres)","url":"https://health.gov.gy/"},"depositInsurance":null,"statistics":{"name":"Bureau of Statistics Guyana","url":"https://statisticsguyana.gov.gy/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GY', 1, 'bank_deposit_avg_rate', 0.00775, NULL, 'sourced', 'World Bank WDI FR.INR.DPST', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=GY', '2025-12-31', 'Average rate paid by commercial banks on deposits, 2025 (Bank of Guyana data via IMF IFS).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GY', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap on credit card interest and no official typical rate found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GY', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'Guyana has a Deposit Insurance Corporation (it appears in the Budget Speech 2026 debt tables), but no readable official page stating the cover per depositor was found (the Bank of Guyana site blocks automated reading behind a verification page).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GY', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published rate for a monthly recurring deposit product was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GY', 1, 'equity_return_base', 0.048, NULL, 'assumption', 'Budget Speech 2026: 91-day Treasury bill 1.10%, small savings rate 0.81%', 'https://finance.gov.gy/wp-content/uploads/2026/01/Budget_Speech_2026.pdf', '2026-10-31', 'Base case uses a global equity index in Guyana-dollar terms (the rate has held near 208.5 per dollar), kept within 4 points of the after-tax Treasury bill rate (about 0.9%) because there is no usable local index record.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GY', 1, 'equity_return_high', 0.08, NULL, 'assumption', 'Budget Speech 2026: 91-day Treasury bill 1.10%', 'https://finance.gov.gy/wp-content/uploads/2026/01/Budget_Speech_2026.pdf', '2026-10-31', 'High case if global equities repeat strong long-run dollar returns.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GY', 1, 'equity_return_low', 0.01, NULL, 'assumption', 'Budget Speech 2026: 91-day Treasury bill 1.10%, small savings rate 0.81%', 'https://finance.gov.gy/wp-content/uploads/2026/01/Budget_Speech_2026.pdf', '2026-10-31', 'Low case: the local stock exchange is small and thinly traded, so savers rely on global funds in Guyana dollars, and a weak decade is possible.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GY', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched Bank of Guyana statistics: the Bank of Guyana site blocks automated reading behind a verification page; no other public source for a 1-year time deposit rate found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GY', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched Bank of Guyana statistics: the Bank of Guyana site blocks automated reading behind a verification page; the Budget Speech 2026 gives only the small savings rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GY', 1, 'fixed_income_return_base', 0.0085, NULL, 'assumption', 'Budget Speech 2026: 91-day Treasury bill 1.10%, small savings rate 0.81%', 'https://finance.gov.gy/wp-content/uploads/2026/01/Budget_Speech_2026.pdf', '2026-10-31', 'Base case: a mix of savings deposits and Treasury bills, about 0.85% after the 20% withholding tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GY', 1, 'fixed_income_return_high', 0.015, NULL, 'assumption', 'Budget Speech 2026: 91-day Treasury bill 1.10%', 'https://finance.gov.gy/wp-content/uploads/2026/01/Budget_Speech_2026.pdf', '2026-10-31', 'High case: Treasury bills or longer time deposits slightly above the bill rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GY', 1, 'fixed_income_return_low', 0.006, NULL, 'assumption', 'Budget Speech 2026: small savings rate 0.81%; PwC: 20% withholding on bank interest', 'https://finance.gov.gy/wp-content/uploads/2026/01/Budget_Speech_2026.pdf', '2026-10-31', 'Low case: savings deposits at 0.81% less 20% tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GY', 1, 'goal_inflation_education', 0.05, NULL, 'assumption', 'Bureau of Statistics Guyana CPI September 2026: education, recreation and cultural services +4.5% over 12 months', 'https://statisticsguyana.gov.gy/subjects/price-indices/consumer-price-index-georgetown-guyana-september-2026/', '2026-10-31', 'The education group rose 4.5% in the latest year; we plan with 5% for private schooling costs.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GY', 1, 'goal_inflation_health', 0.045, NULL, 'assumption', 'Bureau of Statistics Guyana CPI September 2026: medical care and health services +2.4% over 12 months', 'https://statisticsguyana.gov.gy/subjects/price-indices/consumer-price-index-georgetown-guyana-september-2026/', '2026-10-31', 'Medical CPI rose 2.4% in the latest year; we plan with headline planning inflation plus 1 point for private care.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GY', 1, 'gold_return_base', 0.045, NULL, 'assumption', 'Budget Speech 2026 and World Bank: GYD 208.50 per US dollar, stable for years', 'https://finance.gov.gy/wp-content/uploads/2026/01/Budget_Speech_2026.pdf', '2026-10-31', 'Dollar gold trend of about 4-5% a year with no expected depreciation of the managed Guyana dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GY', 1, 'gold_return_high', 0.08, NULL, 'assumption', 'Budget Speech 2026 and World Bank: GYD 208.50 per US dollar', 'https://finance.gov.gy/wp-content/uploads/2026/01/Budget_Speech_2026.pdf', '2026-10-31', 'High case with strong dollar gold or a weaker Guyana dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GY', 1, 'gold_return_low', 0.01, NULL, 'assumption', 'Budget Speech 2026 and World Bank: GYD 208.50 per US dollar, stable for years', 'https://finance.gov.gy/wp-content/uploads/2026/01/Budget_Speech_2026.pdf', '2026-10-31', 'Low case: weak dollar gold price with a stable Guyana dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GY', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'Could not confirm whether the Termination of Employment and Severance Pay Act provides any payment on retirement (the Act text could not be read); severance is known to apply on redundancy.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GY', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No official figure for a typical private hospital stay found; public hospital care is free.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GY', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No regulator or public source publishing private health insurance premiums by age was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GY', 1, 'inflation_cpi', 0.034, NULL, 'sourced', 'Bureau of Statistics Guyana, Consumer Price Index (Georgetown) September 2026', 'https://statisticsguyana.gov.gy/subjects/price-indices/consumer-price-index-georgetown-guyana-september-2026/', '2026-09-30', '12-month inflation 3.4% (September 2025 to September 2026); the index fell 0.1% in the month.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GY', 1, 'inflation_projection', 0.035, NULL, 'assumption', 'Budget Speech 2026: inflation target 2.5% for 2026; CPI 2021-2025 of 5.7, 7.2, 2.0, 2.9, 2.5%', 'https://finance.gov.gy/wp-content/uploads/2026/01/Budget_Speech_2026.pdf', '2026-10-31', 'The 2.5% figure is a one-year government target, not a central bank target; the 2021-2025 average is about 4%, so we plan with 3.5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GY', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life is sold in Guyana, but no regulator or public source publishes indicative premiums by age.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GY', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No industry-wide life claim settlement ratio is published by the Bank of Guyana (insurance supervisor).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GY', 1, 'life_expectancy', 70.319, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=GY', '2024-12-31', 'UN WPP 2024 (via populationpyramid.net) gives 70.6 for 2026 (men 66.8, women 74.4).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GY', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":18.4,"men":16.3,"women":20.4},{"age":65,"total":15.3,"men":13.5,"women":16.9},{"age":70,"total":12.4,"men":11,"women":13.8},{"age":80,"total":7.6,"men":6.6,"women":8.5}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/guyana/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026; sex-specific values are for the 5-year age groups starting at each age; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GY', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":65,"womenAge":65,"over90Monthly":null,"meansTested":false}', 'sourced', 'HelpAge International, Pension Watch country profile: Guyana', 'https://www.helpage.org/country_profile/guyana/', '2026-10-31', 'Old Age Pension from 65 for men and women, universal (not means-tested).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GY', 1, 'old_age_allowance_monthly', 46000, NULL, 'sourced', 'Ministry of Finance, Budget Speech 2026 (para 6.28)', 'https://finance.gov.gy/wp-content/uploads/2026/01/Budget_Speech_2026.pdf', '2026-01-01', 'The universal Old Age Pension rose from G$41,000 to G$46,000 a month from 1 January 2026 (about 95,000 pensioners); HelpAge Pension Watch also lists G$46,000.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GY', 1, 'oop_health_share', 0.2633, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=GY', '2023-12-31', 'Figure is for 2023 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GY', 1, 'policy_rate', 0.05, NULL, 'sourced', 'Trading Economics, Guyana interest rate (Bank of Guyana bank rate)', 'https://tradingeconomics.com/guyana/interest-rate', '2026-09-30', 'Secondary source: the Bank of Guyana bank rate is 5.00% (September 2026), unchanged since March 2013; the Bank of Guyana site blocks automated reading behind a verification page.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GY', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":16,"entryAgeMax":60,"pensionFromAge":60,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'National Insurance Scheme Guyana, Old Age Benefit and Information on Contributions', 'https://www.nis.org.gy/oldage_benefit', '2026-10-31', 'Compulsory NIS for employed persons aged 16 to 60 (https://www.nis.org.gy/information_on_contributions: 14% of wages, 5.6% employee and 8.4% employer; self-employed 12.5%). Pension from 60 with 750 contributions (150 paid): 40% of average weekly insurable earnings plus 1% per 50 contributions above 750, up to 60%, and at least 50% of the public service minimum wage. No automatic indexation stated; tax treatment not confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GY', 1, 'retirement_accumulation_return_base', 0.028, NULL, 'assumption', '91-day Treasury bill 1.10%; global equity assumptions in Guyana dollars', 'https://finance.gov.gy/wp-content/uploads/2026/01/Budget_Speech_2026.pdf', '2026-10-31', 'Base case: half global equities at 4.8% and half deposits and bills near 0.85%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GY', 1, 'retirement_accumulation_return_high', 0.05, NULL, 'assumption', '91-day Treasury bill 1.10%; global equity assumptions in Guyana dollars', 'https://finance.gov.gy/wp-content/uploads/2026/01/Budget_Speech_2026.pdf', '2026-10-31', 'High case with stronger equity returns.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GY', 1, 'retirement_accumulation_return_low', 0.015, NULL, 'assumption', '91-day Treasury bill 1.10%; global equity assumptions in Guyana dollars', 'https://finance.gov.gy/wp-content/uploads/2026/01/Budget_Speech_2026.pdf', '2026-10-31', 'Low case for a balanced mix if global equities disappoint.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GY', 1, 'retirement_age_default', 60, NULL, 'sourced', 'National Insurance Scheme Guyana, Old Age Benefit', 'https://www.nis.org.gy/oldage_benefit', '2026-10-31', 'NIS old-age pension from age 60 with at least 750 contributions (150 paid); same for men and women, no scheduled increase found. The page carries no date.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GY', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'Could not confirm the statutory retirement age for public servants (Public Service Ministry and Pensions Act texts not reachable without search).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GY', 1, 'retirement_return_base', 0.0085, NULL, 'assumption', 'Budget Speech 2026: 91-day Treasury bill 1.10%', 'https://finance.gov.gy/wp-content/uploads/2026/01/Budget_Speech_2026.pdf', '2026-10-31', 'Base case at about the 1.10% Treasury bill rate less the 20% withholding tax, with part held in savings deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GY', 1, 'retirement_return_high', 0.015, NULL, 'assumption', 'Budget Speech 2026: 91-day Treasury bill 1.10%', 'https://finance.gov.gy/wp-content/uploads/2026/01/Budget_Speech_2026.pdf', '2026-10-31', 'High case: Treasury bills and longer time deposits a little above the bill rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GY', 1, 'retirement_return_low', 0.005, NULL, 'assumption', 'Budget Speech 2026: small savings rate 0.81%; PwC: 20% withholding on bank interest', 'https://finance.gov.gy/wp-content/uploads/2026/01/Budget_Speech_2026.pdf', '2026-10-31', 'Low case: savings deposits after the 20% tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GY', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate or retail savings bond for individuals was found; domestic government borrowing is mainly through Treasury bills (the Bank of Guyana site blocks automated reading behind a verification page).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GY', 1, 'savings_account_rate', 0.0081, NULL, 'sourced', 'Ministry of Finance, Budget Speech 2026 (para 3.36)', 'https://finance.gov.gy/wp-content/uploads/2026/01/Budget_Speech_2026.pdf', '2025-12-31', 'Commercial banks'' small savings rate stayed at 0.81% through 2025 (Bank of Guyana data). Figure is for 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GY', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":9.2},{"year":2040,"value":6.5},{"year":2065,"value":4.2}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/guyana/2040/', '2025-12-31', '100 / old-age dependency ratio: 10.9 (2025, World Bank), 15.4 (2040) and 23.6 (2065, populationpyramid.net/guyana/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GY', 1, 'tax_bank_interest', 0.2, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Guyana: Individual - Income determination', 'https://taxsummaries.pwc.com/guyana/individual/income-determination', '2026-06-02', 'Interest on savings and other accounts with banks and financial institutions is subject to a 20% final withholding tax, refundable if total income is below GYD 780,000 a year; page last reviewed 2 June 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GY', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate for individuals exists (see sanchayapatra_5y_rate), and the PwC summary does not address tax on government securities.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('GY', 1, 'tbill_91d_rate', 0.011, NULL, 'sourced', 'Ministry of Finance, Budget Speech 2026 (para 3.36)', 'https://finance.gov.gy/wp-content/uploads/2026/01/Budget_Speech_2026.pdf', '2025-12-31', 'The 91-day Treasury bill yield stayed at 1.10% through 2025 (364-day 1.09%, 182-day 0.99%); 2026 auction results could not be read (the Bank of Guyana site blocks automated reading). Figure is for 2025.', 0);
