INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('HN', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"HN","iso3":"HND","nameEn":"Honduras","nameNative":"Honduras","region":"latin_america_caribbean","languages":["es"],"currency":{"code":"HNL","symbol":"L","decimals":2,"compact":"intl","usdRate":{"value":25.9527,"status":"sourced","sourceName":"World Bank WDI PA.NUS.FCRF","sourceUrl":"https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=HN","asOf":"2025-12-31","note":"2025 average official rate. The Banco Central de Honduras site could not be read by machine; Trading Economics (secondary) showed about 26.88 lempiras per dollar in early November 2026, but the researcher''s 30 October figure could not be confirmed, so the World Bank figure is used."}},"instruments":{"savings_account":{"available":true,"localName":"Cuenta de ahorro","localNameEn":"Savings account"},"fdr_3m":{"available":true,"localName":"Depósito a plazo","localNameEn":"Term deposit (3 months)"},"fdr_1y":{"available":true,"localName":"Depósito a plazo","localNameEn":"Term deposit (1 year)"},"dps":{"available":false,"localName":null,"note":"No standard monthly recurring-deposit product with a published rate was found."},"sanchayapatra_5y":{"available":false,"localName":null,"note":"No government savings certificate or retail savings bond is sold directly to individuals."},"tbill_91d":{"available":false,"localName":null,"note":"No retail treasury bill programme was found."},"tbond_5y":{"available":false,"localName":null,"note":"No retail channel for 5-year government bonds was confirmed."},"tbond_10y":{"available":false,"localName":null,"note":"No retail channel for 10-year government bonds was confirmed."},"equity_fund":{"available":false,"localName":null,"note":"No diversified equity index fund for retail investors was found."},"gold":{"available":true,"localName":"Oro","localNameEn":"Gold","note":"Gold can be bought legally from jewellers."}},"institutions":{"centralBank":{"name":"Banco Central de Honduras (BCH)","url":"https://www.bch.hn/"},"insuranceRegulator":{"name":"Comisión Nacional de Bancos y Seguros (CNBS)","url":"https://www.cnbs.gob.hn/"},"insuranceComplaints":{"name":"CNBS: reclamos de usuarios financieros","url":"https://www.cnbs.gob.hn/reclamos"},"pensionScheme":{"name":"Instituto Hondureño de Seguridad Social (IHSS), régimen de invalidez, vejez y muerte","url":"https://www.ihss.hn/pension-por-vejez-2/"},"oldAgeAllowance":null,"publicHealthCover":{"name":"Secretaría de Salud (public health services)","url":"https://www.salud.gob.hn/","note":"Formal-sector workers are covered by the IHSS sickness and maternity scheme."},"depositInsurance":{"name":"Fondo de Seguro de Depósitos (FOSEDE)","url":"https://fosede.hn/cobertura-del-seguro/"},"statistics":{"name":"Instituto Nacional de Estadística (INE)","url":"https://www.ine.gob.hn/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HN', 1, 'bank_deposit_avg_rate', 0.1244, NULL, 'sourced', 'World Bank WDI FR.INR.DPST', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=HN', '2025-12-31', 'IMF IFS deposit rate via the World Bank; up from 8.91% in 2024, reflecting tight bank liquidity in 2025.', 0);
