INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HN', 1, 'deposit_insurance_limit', 245715, NULL, 'sourced', 'FOSEDE: Resolución No. 341/18-02-2025, suma máxima asegurada para el año 2025', 'https://fosede.hn/wp-content/uploads/2025/06/Resolucion-Suma-Maxima-Asugurada-para-el-ano-2025.pdf', '2025-02-18', 'L245,715 per depositor per institution for 2025 (Resolution 341/18-02-2025: the legal USD 9,632.92 base at the BCH selling rate of L25.5069). The amount is reset each year; the FOSEDE resolutions page lists no 2026 resolution, so this 2025 amount is the latest found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HN', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No official series for monthly recurring deposits was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HN', 1, 'equity_return_base', 0.09, NULL, 'assumption', 'Global equity index in lempira terms; lempira 26.88 per dollar (Oct 2026) vs about 24.6 in 2023', 'https://tradingeconomics.com/honduras/indicators', '2026-10-31', 'The local exchange lists few shares, so we use a global equity index (about 7% in dollars) plus about 2% a year of lempira depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HN', 1, 'equity_return_high', 0.12, NULL, 'assumption', 'Global equity index in lempira terms', 'https://tradingeconomics.com/honduras/indicators', '2026-10-31', 'High case: strong global equities and faster depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HN', 1, 'equity_return_low', 0.04, NULL, 'assumption', 'Global equity index in lempira terms', 'https://tradingeconomics.com/honduras/indicators', '2026-10-31', 'Low case: weak global equities and a stable lempira.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HN', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 1-year term deposit rate found; the BCH statistics pages could not be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HN', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 3-month term deposit rate found; the BCH statistics pages could not be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HN', 1, 'fixed_income_return_base', 0.07, NULL, 'assumption', 'World Bank FR.INR.DPST (12.44% in 2025, 8.91% in 2024)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=HN', '2026-10-31', 'Base case well below the 2025 peak average deposit rate, allowing for tax and normalising liquidity.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HN', 1, 'fixed_income_return_high', 0.09, NULL, 'assumption', 'World Bank FR.INR.DPST (12.44% in 2025, 8.91% in 2024)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=HN', '2026-10-31', 'High case if term deposit rates stay near 2024-2025 levels.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HN', 1, 'fixed_income_return_low', 0.05, NULL, 'assumption', 'World Bank FR.INR.DPST (12.44% in 2025, 8.91% in 2024)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=HN', '2026-10-31', 'Low case if deposit rates fall back with the 5.75% policy rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HN', 1, 'goal_inflation_education', 0.06, NULL, 'assumption', 'Trading Economics indicators: CPI education index', 'https://tradingeconomics.com/honduras/indicators', '2026-10-31', 'No education inflation rate was read; tuition usually rises faster than headline, so we plan with 6%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HN', 1, 'goal_inflation_health', 0.065, NULL, 'assumption', 'Trading Economics: Honduras inflation rate (6.28%, Sept 2026)', 'https://tradingeconomics.com/honduras/inflation-cpi', '2026-10-31', 'No health price index rate was read; private care tends to outpace headline, so we plan with 1.5 points above the 5% assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HN', 1, 'gold_return_base', 0.07, NULL, 'assumption', 'World Bank Commodity Markets (Pink Sheet) gold price; lempira exchange rate trend', 'https://www.worldbank.org/en/research/commodity-markets', '2026-10-31', 'Dollar gold trend of about 4.5% a year plus about 2.5% lempira depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HN', 1, 'gold_return_high', 0.1, NULL, 'assumption', 'World Bank Commodity Markets (Pink Sheet) gold price', 'https://www.worldbank.org/en/research/commodity-markets', '2026-10-31', 'High case: strong dollar gold.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HN', 1, 'gold_return_low', 0.03, NULL, 'assumption', 'World Bank Commodity Markets (Pink Sheet) gold price', 'https://www.worldbank.org/en/research/commodity-markets', '2026-10-31', 'Low case: flat dollar gold with mild lempira depreciation.', 0);
