INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HN', 1, 'inflation_projection', 0.05, NULL, 'assumption', 'Trading Economics indicators: inflation expectations 4.95% (Aug 2026); World Bank FP.CPI.TOTL.ZG 4.6% (2025)', 'https://tradingeconomics.com/honduras/indicators', '2026-10-31', 'Expected inflation near 5% and a recent average of about 5-6% (higher in 2022), so we plan with a rounded 5%.', 0);
