INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HN', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":19,"men":17.2,"women":20.7},{"age":65,"total":15.3,"men":13.8,"women":16.8},{"age":70,"total":12,"men":10.8,"women":13.2},{"age":80,"total":6.7,"men":6.1,"women":7.3}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/honduras/', '2026-07-01', 'Secondary source of UN WPP 2024 medium-variant projections for 2026; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
