INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HN', 1, 'retirement_age_government', 62, NULL, 'sourced', 'INJUPEMP: preguntas frecuentes (requisitos de jubilación voluntaria)', 'https://www.injupemp.gob.hn/preguntas-frecuentes-2/', '2026-10-31', 'Public employees'' fund: retirement at 62 with 15 years of service for those retiring from 2032 or aged 43 or less in 2013 (anyone born after 1975); 60 with 13 years for 2024-2027 and 61 with 14 years for 2028-2031.', 0);
