INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('HR', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"HR","iso3":"HRV","nameEn":"Croatia","nameNative":"Hrvatska","region":"europe_central_asia","languages":["hr","en","it"],"currency":{"code":"EUR","symbol":"€","decimals":2,"compact":"intl","usdRate":{"value":0.8951,"status":"sourced","sourceName":"European Central Bank euro reference rate (USD)","sourceUrl":"https://data-api.ecb.europa.eu/service/data/EXR/D.USD.EUR.SP00.A","asOf":"2026-10-30","note":"EUR 1 = USD 1.1172, so about EUR 0.895 per US dollar; Croatia adopted the euro on 1 January 2023. World Bank 2025 average 0.885."}},"instruments":{"savings_account":{"available":true,"localName":"Štedni račun (a vista štednja)","localNameEn":"Savings account","sourceUrl":"https://data-api.ecb.europa.eu/service/data/MIR/M.HR.B.L21.A.R.A.2250.EUR.N"},"fdr_3m":{"available":true,"localName":"Oročena štednja","localNameEn":"Fixed-term deposit (3 months)"},"fdr_1y":{"available":true,"localName":"Oročena štednja","localNameEn":"Fixed-term deposit (1 year)","sourceUrl":"https://data-api.ecb.europa.eu/service/data/MIR/M.HR.B.L22.F.R.A.2250.EUR.N"},"dps":{"available":true,"localName":"Stambena štednja","localNameEn":"Housing savings (building society)","note":"Regular saving with building societies, with a state incentive on yearly deposits."},"sanchayapatra_5y":{"available":false,"localName":"Narodna obveznica","localNameEn":"Retail government bond","note":"No standing 5-year savings bond for individuals; the government issues occasional retail bonds and sells 91-day treasury bills to citizens, with interest tax-free.","sourceUrl":"https://mfin.gov.hr/istaknute-teme/javni-dug/trezorski-zapisi-poziv-na-aukciju/191"},"tbill_91d":{"available":true,"localName":"Trezorski zapisi","localNameEn":"Treasury bills of the Ministry of Finance","note":"Citizens can subscribe in a non-competitive retail round.","sourceUrl":"https://mfin.gov.hr/istaknute-teme/javni-dug/trezorski-zapisi-poziv-na-aukciju/191"},"tbond_5y":{"available":true,"localName":"Obveznice Republike Hrvatske","localNameEn":"Republic of Croatia government bonds"},"tbond_10y":{"available":true,"localName":"Obveznice Republike Hrvatske","localNameEn":"Republic of Croatia government bonds","sourceUrl":"https://tradingeconomics.com/croatia/government-bond-yield"},"equity_fund":{"available":true,"localName":"Investicijski fond","localNameEn":"Investment fund (UCITS) / index fund","note":"Gains on financial assets held over two years are not taxed."},"gold":{"available":true,"localName":"Investicijsko zlato","localNameEn":"Investment gold bars and coins","note":"No restriction on buying physical gold."}},"institutions":{"centralBank":{"name":"Hrvatska narodna banka (Croatian National Bank)","url":"https://www.hnb.hr/","note":"Part of the Eurosystem since 2023; monetary policy set by the European Central Bank."},"insuranceRegulator":{"name":"Hrvatska agencija za nadzor financijskih usluga (HANFA)","url":"https://www.hanfa.hr/"},"insuranceComplaints":{"name":"HANFA, consumer complaints","url":"https://www.hanfa.hr/potrosaci/prituzbe-potrosaca/"},"pensionScheme":{"name":"Hrvatski zavod za mirovinsko osiguranje (HZMO)","url":"https://www.mirovinsko.hr/"},"oldAgeAllowance":{"name":"Nacionalna naknada za starije osobe (national benefit for older persons)","url":"https://www.mirovinsko.hr/hr/nacionalna-naknada-za-starije-osobe/1518"},"publicHealthCover":{"name":"Hrvatski zavod za zdravstveno osiguranje (HZZO)","url":"https://hzzo.hr/"},"depositInsurance":{"name":"Hrvatska agencija za osiguranje depozita (HAOD)","url":"https://www.haod.hr/"},"statistics":{"name":"Državni zavod za statistiku (Croatian Bureau of Statistics)","url":"https://podaci.dzs.hr/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HR', 1, 'bank_deposit_avg_rate', 0.0128, NULL, 'sourced', 'ECB MFI interest rate statistics: Croatian banks, household deposits with agreed maturity (outstanding amounts)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.HR.B.L22.A.R.A.2250.EUR.O', '2026-09-30', 'Average rate on all outstanding household term deposits, September 2026 (1.29% in August); World Bank FR.INR.DPST last reported 1.35% for 2014.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HR', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'Croatian consumer credit law sets a maximum contractual interest rate published by the HNB, but hnb.hr was unreachable and no current figure or typical card rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HR', 1, 'deposit_insurance_limit', 100000, NULL, 'sourced', 'Croatian Deposit Insurance Agency (HAOD), secured amount', 'https://www.haod.hr/en/deposit-insurance/-secured-amount', '2026-10-31', 'EUR 100,000 per depositor per credit institution, including accrued interest.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HR', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Croatia''s regular-deposit savings product is housing savings (stambena štednja) at building societies with a state premium; no current average rate was found from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HR', 1, 'equity_return_base', 0.06, NULL, 'assumption', 'CROBEX (Trading Economics); 91-day treasury bill 2.6% tax-free', 'https://tradingeconomics.com/croatia/stock-market', '2026-10-31', 'Base case: about 3.4 points over the tax-free treasury bill rate, kept modest because the CROBEX is small, illiquid and has not regained its 2007 high.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HR', 1, 'equity_return_high', 0.08, NULL, 'assumption', 'CROBEX (Trading Economics); global equity long-run returns', 'https://tradingeconomics.com/croatia/stock-market', '2026-10-31', 'High case: a diversified euro equity fund matching long-run global equity returns of about 8% in euros.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HR', 1, 'equity_return_low', 0.035, NULL, 'assumption', 'CROBEX 4,471 on 30 Oct 2026, up 17% in a year but still below its 2007 peak of 5,393', 'https://tradingeconomics.com/croatia/stock-market', '2026-10-31', 'Low case: Croatian shares earn little more than tax-free treasury bills over long periods, as in the 19 years since the 2007 peak.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HR', 1, 'fdr_1y_rate', 0.0155, NULL, 'sourced', 'ECB MFI interest rate statistics: Croatian banks, household deposits with agreed maturity up to 1 year (new business)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.HR.B.L22.F.R.A.2250.EUR.N', '2026-09-30', 'Bucket covers all fixed terms up to one year; 1.55% in September 2026 (1.29% in August). Re-checked against the ECB data API by the verifier.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HR', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'ECB/HNB MFI statistics publish household deposits with agreed maturity up to 1 year as one bucket (1.55% in September 2026); hnb.hr was unreachable and no separate 3-month rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HR', 1, 'fixed_income_return_base', 0.025, NULL, 'assumption', 'Ministry of Finance 91-day treasury bills 2.60-2.75%, tax-free', 'https://mfin.gov.hr/istaknute-teme/javni-dug/trezorski-zapisi-poziv-na-aukciju/191', '2026-10-31', 'Base case: rolling tax-free retail treasury bills, slightly below the September 2026 yield as ECB rates may ease.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HR', 1, 'fixed_income_return_high', 0.035, NULL, 'assumption', 'Croatia 10-year government bond 3.59% (ECB, September 2026), interest tax-free', 'https://data-api.ecb.europa.eu/service/data/IRS/M.HR.L.L40.CI.0000.EUR.N.Z', '2026-10-31', 'High case: holding longer Croatian government bonds, whose interest is untaxed, just below the current 10-year yield.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HR', 1, 'fixed_income_return_low', 0.011, NULL, 'assumption', 'Household deposits up to 1 year 1.55% (September 2026) less 12% tax = 1.36% (ECB MFI statistics)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.HR.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Low case: bank term deposits after the 12% interest tax, allowing for deposit rates to slip back.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HR', 1, 'goal_inflation_education', 0.035, NULL, 'assumption', 'Eurostat/ECB HICP Croatia, education: -1.0% year on year in December 2025', 'https://data-api.ecb.europa.eu/service/data/ICP/M.HR.N.100000.4.ANR', '2026-10-31', 'The education index fell in 2025 because public schooling and textbooks are free, so private education costs are assumed to rise a little above general inflation at 3.5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HR', 1, 'goal_inflation_health', 0.045, NULL, 'assumption', 'Eurostat/ECB HICP Croatia, health: 4.3% year on year in December 2025', 'https://data-api.ecb.europa.eu/service/data/ICP/M.HR.N.060000.4.ANR', '2026-10-31', 'Health prices rise about as fast as Croatia''s above-target headline inflation; 4.5% is used for planning.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HR', 1, 'gold_return_base', 0.04, NULL, 'assumption', 'Gold price history (Trading Economics); ECB 2% inflation target', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Base case: dollar gold rises roughly with world inflation plus a little, and the euro is assumed stable against the dollar over the long run.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HR', 1, 'gold_return_high', 0.07, NULL, 'assumption', 'Gold price history (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'High case: a repeat of gold''s strong 2005-2025 trend in euro terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HR', 1, 'gold_return_low', 0.01, NULL, 'assumption', 'Gold USD 3,876/oz on 30 Oct 2026, 31% below the January 2026 high', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Low case: gold barely keeps up after the 2025-26 spike, with no help from the euro.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HR', 1, 'gratuity_rule', NULL, '{"daysPerYear":10,"daysPerYearAfter":null,"afterYears":null,"daysPerMonth":30}', 'sourced', 'Labour Act (Zakon o radu), Article 126', 'https://www.zakon.hr/z/307/Zakon-o-radu', '2026-10-31', 'Severance (otpremnina) only on dismissal by the employer after 2 years'' continuous service: at least one third of average monthly pay per year of service (about 10 days), capped at 6 months'' pay; not paid on retirement at 65 with 15 years of pension service.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HR', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'Hospital care is covered by HZZO compulsory insurance, with co-payments covered by supplementary insurance (dopunsko osiguranje); no official figure for a typical out-of-pocket private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HR', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Supplementary and private health insurance are sold at flat premiums, not per sum insured, and no premium table per EUR 100,000 of cover was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HR', 1, 'inflation_cpi', 0.047, NULL, 'sourced', 'Trading Economics (Croatian Bureau of Statistics CPI, September 2026 final)', 'https://tradingeconomics.com/croatia/inflation-cpi', '2026-09-30', 'CPI 4.7% year on year in September 2026 (4.2% in August), final figure released 15 October 2026; secondary source because podaci.dzs.hr was not read directly. World Bank 2025 average 3.7%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HR', 1, 'inflation_projection', 0.03, NULL, 'assumption', 'ECB 2% medium-term target; Croatian CPI 4.7% (Sep 2026), 3.7% in 2025 (World Bank)', 'https://tradingeconomics.com/croatia/inflation-cpi', '2026-10-31', 'Croatia uses the euro and the ECB targets 2%, but Croatian inflation has run well above the euro-area average since euro adoption, so 3% is used for planning.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HR', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life (rizično životno osiguranje) is sold, but no published premium table or regulator data on term premiums per sum insured was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HR', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'HANFA and the Croatian Insurance Bureau publish premium and claims totals but no industry life claim settlement ratio could be found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HR', 1, 'life_expectancy', 79.1, NULL, 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/croatia', '2026-07-01', 'Men 76.0, women 82.1 (UN WPP estimate for 2026, mid-year); World Bank 2024 figure 78.9.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HR', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":22,"men":19.6,"women":24},{"age":65,"total":18,"men":15.9,"women":19.7},{"age":70,"total":14.3,"men":12.5,"women":15.6},{"age":80,"total":7.9,"men":6.7,"women":8.6}]}', 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/croatia', '2026-07-01', 'Remaining years computed from georank''s expected age at death by current age (UN WPP 2026 estimate).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HR', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":65,"womenAge":65,"over90Monthly":null,"meansTested":true}', 'sourced', 'HZMO, national benefit for older persons', 'https://www.mirovinsko.hr/hr/nacionalna-naknada-za-starije-osobe/1518', '2026-01-01', 'Croatian citizens aged 65+ with 10 years'' continuous residence, no pension, and household income per member below EUR 320.44 a month (twice the benefit).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HR', 1, 'old_age_allowance_monthly', 160.22, NULL, 'sourced', 'HZMO, national benefit for older persons (nacionalna naknada za starije osobe)', 'https://www.mirovinsko.hr/hr/nacionalna-naknada-za-starije-osobe/1518', '2026-01-01', 'EUR 160.22 a month from 1 January 2026 for people aged 65+ with no pension.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HR', 1, 'oop_health_share', 0.0938, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=HR', '2023-12-31', 'Latest World Bank/WHO figure is for 2023 (older than 2025); no newer official figure was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HR', 1, 'policy_rate', 0.025, NULL, 'sourced', 'European Central Bank, deposit facility rate', 'https://data-api.ecb.europa.eu/service/data/FM/B.U2.EUR.4F.KR.DFR.LEV', '2026-09-16', 'Croatia has used the euro since 2023; ECB deposit facility rate 2.50% (main refinancing rate 2.65%) from 16 September 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HR', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":65,"nomineeUntilAge":null,"inflationLinked":true,"taxFree":null}', 'sourced', 'Croatian Pension Insurance Institute (HZMO)', 'https://www.mirovinsko.hr/en/how-is-your-pension-determined/188', '2026-10-31', 'Compulsory pay-as-you-go first pillar plus a mandatory second-pillar fund; pensions are adjusted on 1 January and 1 July by a mix of consumer-price inflation and average gross wage growth. Women''s pension age reaches 65 in 2030.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HR', 1, 'retirement_accumulation_return_base', 0.045, NULL, 'assumption', 'Treasury bills 2.6% tax-free; equity base 6%', 'https://mfin.gov.hr/istaknute-teme/javni-dug/trezorski-zapisi-poziv-na-aukciju/191', '2026-10-31', 'Base case: roughly half shares at 6% and half tax-free government paper at about 2.5-3.5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HR', 1, 'retirement_accumulation_return_high', 0.06, NULL, 'assumption', '10-year government bond 3.59% tax-free (ECB); equity high 8%', 'https://data-api.ecb.europa.eu/service/data/IRS/M.HR.L.L40.CI.0000.EUR.N.Z', '2026-10-31', 'High case for a growth-leaning balanced mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HR', 1, 'retirement_accumulation_return_low', 0.03, NULL, 'assumption', 'Treasury bills 2.6% tax-free; CROBEX record', 'https://mfin.gov.hr/istaknute-teme/javni-dug/trezorski-zapisi-poziv-na-aukciju/191', '2026-10-31', 'Low case for a balanced mix if shares lag.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HR', 1, 'retirement_age_default', 65, NULL, 'sourced', 'Croatian Pension Insurance Institute (HZMO), old-age pension', 'https://www.mirovinsko.hr/hr/starosna-mirovina/166', '2026-10-31', '65 with at least 15 years of insurance for anyone born after 1975, men and women; women retiring in 2026 can go at 64 years 0 months, rising to 65 from 1 January 2030. The Labour Act also ends employment at 65 with 15 years of pension service unless agreed otherwise.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HR', 1, 'retirement_age_government', 65, NULL, 'sourced', 'Civil Servants Act (Zakon o državnim službenicima, NN 155/23, 85/24), Article 152', 'https://www.zakon.hr/z/108/zakon-o-drzavnim-sluzbenicima', '2026-10-31', 'Article 152: civil service ends at 65 with at least 15 years of pension service, extendable by agreement up to 67; consolidated text current to NN 119/26 (re-checked on zakon.hr).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HR', 1, 'retirement_return_base', 0.025, NULL, 'assumption', 'Ministry of Finance 91-day treasury bills 2.60-2.75%, tax-free', 'https://mfin.gov.hr/istaknute-teme/javni-dug/trezorski-zapisi-poziv-na-aukciju/191', '2026-10-31', 'Base case capped just below the tax-free retail treasury bill yield.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HR', 1, 'retirement_return_high', 0.033, NULL, 'assumption', 'Croatia 10-year government bond 3.59% (ECB, September 2026), interest tax-free', 'https://data-api.ecb.europa.eu/service/data/IRS/M.HR.L.L40.CI.0000.EUR.N.Z', '2026-10-31', 'High case: a ladder of tax-free Croatian government bonds, below the current 10-year yield.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HR', 1, 'retirement_return_low', 0.011, NULL, 'assumption', 'Household deposits up to 1 year 1.55% (September 2026) less 12% tax = 1.36% (ECB MFI statistics)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.HR.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Low case: bank term deposits after tax, allowing for deposit rates to slip back.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HR', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 5-year retail government savings bond rate found; the Ministry of Finance sells 91-day treasury bills to citizens (2.75% in September 2026) and has issued occasional retail ''narodna obveznica'' bonds, but no current issue or rate was read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HR', 1, 'savings_account_rate', 0.0002, NULL, 'sourced', 'ECB MFI interest rate statistics: Croatian banks, household overnight deposits (new business)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.HR.B.L21.A.R.A.2250.EUR.N', '2026-09-30', 'Average 0.02% on household sight (a vista) deposits in September 2026 (also 0.02% in August), ECB MFI interest rate statistics.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HR', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":2.66},{"year":2040,"value":2.12},{"year":2065,"value":1.71}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/croatia/2040/', '2025-12-31', '100 / old-age dependency ratio: 37.7 (2025, World Bank), 47.1 (2040) and 58.4 (2065, populationpyramid.net/croatia/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HR', 1, 'tax_bank_interest', 0.12, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Croatia income determination', 'https://taxsummaries.pwc.com/croatia/individual/income-determination', '2026-08-27', '12% final tax on interest; interest on current and sight accounts paying no more than 0.5% a year is exempt.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HR', 1, 'tax_sanchayapatra_profit', 0, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Croatia income determination', 'https://taxsummaries.pwc.com/croatia/individual/income-determination', '2026-08-27', 'Interest on bonds and on debt securities of the Republic of Croatia, including treasury bills, is excluded from taxable interest income.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HR', 1, 'tbill_91d_rate', 0.026, NULL, 'sourced', 'Ministry of Finance of Croatia, final terms of the 91-day treasury bill issue RHMF-T-651N', 'https://mfin.gov.hr/UserDocsImages/dokumenti/javni-dug/Ponuda%20trez%20zapisa/rujan%202026/Objava%20o%20kona%C4%8Dnim%20uvjetima%20izdanja_15.9.26.pdf', '2026-09-15', 'Competitive round annual yield 2.60%; the non-competitive retail round, taken up by about 37,000 investors, yielded 2.75%. Issued 17 September 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HR', 1, 'tbond_10y_rate', 0.0359, NULL, 'sourced', 'European Central Bank, long-term interest rate for convergence purposes (10-year government bond), Croatia', 'https://data-api.ecb.europa.eu/service/data/IRS/M.HR.L.L40.CI.0000.EUR.N.Z', '2026-09-30', 'Official monthly average for September 2026 (3.58% in July and August). Trading Economics shows a market quote of 4.14% on 30 October 2026, which could not be reconciled with the official series, so the ECB figure is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HR', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 5-year Croatian government bond yield found: Trading Economics shows only the 10-year yield and the Ministry of Finance bond pages read gave no secondary-market yields.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('HT', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"HT","iso3":"HTI","nameEn":"Haiti","nameNative":"Ayiti","region":"latin_america_caribbean","languages":["ht","fr"],"currency":{"code":"HTG","symbol":"G","decimals":2,"compact":"intl","usdRate":{"value":130.7348,"status":"sourced","sourceName":"Banque de la République d''Haïti (BRH): taux du jour (taux de référence)","sourceUrl":"https://www.brh.ht/taux-du-jour/","asOf":"2026-10-31","note":"Reference rate; bank buying 130.4580 and selling 131.6921 gourdes. Verifier re-read the BRH page on 2 November 2026 and it showed the same 130.7348 reference rate. The CLDR file lists USD for Haiti; the national currency is the gourde (HTG)."}},"instruments":{"savings_account":{"available":true,"localName":"Kont epay","localNameEn":"Savings account","note":"Gourde and US dollar savings accounts are offered; average gourde savings rate about 0.5%.","sourceUrl":"https://www.brh.ht/wp-content/uploads/tauxinteretgourdes.pdf"},"fdr_3m":{"available":true,"localName":"Depo a tèm","localNameEn":"Term deposit","note":"BRH publishes one average rate for all term deposits, not by maturity.","sourceUrl":"https://www.brh.ht/wp-content/uploads/tauxinteretgourdes.pdf"},"fdr_1y":{"available":true,"localName":"Depo a tèm","localNameEn":"Term deposit","note":"BRH publishes one average rate for all term deposits, not by maturity.","sourceUrl":"https://www.brh.ht/wp-content/uploads/tauxinteretgourdes.pdf"},"dps":{"available":false,"localName":null,"note":"No standard monthly recurring-deposit product with a published rate was found."},"sanchayapatra_5y":{"available":false,"localName":null,"note":"No government savings certificate or retail savings bond is sold to individuals."},"tbill_91d":{"available":false,"localName":null,"note":"The 91-day BRH bill is a central bank instrument sold to banks; no retail treasury bill programme was found.","sourceUrl":"https://www.brh.ht/wp-content/uploads/tableaubons.pdf"},"tbond_5y":{"available":false,"localName":null,"note":"No government bond for retail investors was found."},"tbond_10y":{"available":false,"localName":null,"note":"No government bond for retail investors was found."},"equity_fund":{"available":false,"localName":null,"note":"Haiti has no stock exchange and no retail equity fund was found."},"gold":{"available":true,"localName":"Lò","localNameEn":"Gold","note":"Gold jewellery and coins can be bought from jewellers."}},"institutions":{"centralBank":{"name":"Banque de la République d''Haïti (BRH)","url":"https://www.brh.ht/"},"insuranceRegulator":null,"insuranceComplaints":null,"pensionScheme":{"name":"Office National d''Assurance-Vieillesse (ONA)","url":"https://ona.ht/","note":"Contributory old-age insurance for private-sector employees."},"oldAgeAllowance":null,"publicHealthCover":{"name":"Ministère de la Santé Publique et de la Population (MSPP)","url":"https://www.mspp.gouv.ht/"},"depositInsurance":null,"statistics":{"name":"Institut Haïtien de Statistique et d''Informatique (IHSI)","url":"https://www.ihsi.gouv.ht/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HT', 1, 'bank_deposit_avg_rate', 0.0428, NULL, 'sourced', 'World Bank WDI FR.INR.DPST', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=HT', '2025-12-31', 'Average deposit rate from IMF IFS via the World Bank.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HT', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap or published typical credit card rate was found; BRH notes interest rate ceilings were abolished in 1989.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HT', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No deposit insurance scheme or coverage amount was found; BRH pages read do not mention one.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HT', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No official series or public product rate for monthly recurring deposits was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HT', 1, 'equity_return_base', 0.075, NULL, 'assumption', 'Global equity index in gourde terms; BRH average gourde term deposit rate 3.75% (Sept 2025)', 'https://www.brh.ht/wp-content/uploads/tauxinteretgourdes.pdf', '2026-10-31', 'Haiti has no stock exchange, so we use a global equity index in gourde terms, capped at the average term-deposit rate (3.75%) plus 4 points.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HT', 1, 'equity_return_high', 0.11, NULL, 'assumption', 'Global equity index in gourde terms', 'https://www.brh.ht/wp-content/uploads/tauxinteretgourdes.pdf', '2026-10-31', 'High case: strong global equities plus some gourde depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HT', 1, 'equity_return_low', 0.03, NULL, 'assumption', 'No local stock exchange; global equity index in gourde terms', 'https://www.brh.ht/wp-content/uploads/tauxinteretgourdes.pdf', '2026-10-31', 'Low case: weak global equities and a stable gourde.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HT', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The BRH gourde rate series gives one average for all term deposits (3.75%, range 1.5-6.0%, week of 28 September 2025) without a breakdown by maturity; no 1-year figure found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HT', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The BRH gourde rate series gives one average for all term deposits (3.75%, range 1.5-6.0%, week of 28 September 2025) without a breakdown by maturity; no 3-month figure found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HT', 1, 'fixed_income_return_base', 0.035, NULL, 'assumption', 'Banque de la République d''Haïti (BRH): taux d''intérêt sur les opérations en gourdes', 'https://www.brh.ht/wp-content/uploads/tauxinteretgourdes.pdf', '2026-10-31', 'Base case just below the 3.75% average gourde term-deposit rate, since the tax on interest is unknown.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HT', 1, 'fixed_income_return_high', 0.055, NULL, 'assumption', 'Banque de la République d''Haïti (BRH): taux d''intérêt sur les opérations en gourdes', 'https://www.brh.ht/wp-content/uploads/tauxinteretgourdes.pdf', '2026-10-31', 'High case near the top of the term-deposit range (6%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HT', 1, 'fixed_income_return_low', 0.02, NULL, 'assumption', 'Banque de la République d''Haïti (BRH): taux d''intérêt sur les opérations en gourdes', 'https://www.brh.ht/wp-content/uploads/tauxinteretgourdes.pdf', '2026-10-31', 'Low case near the bottom of the term-deposit range (1.5%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HT', 1, 'goal_inflation_education', 0.15, NULL, 'assumption', 'BRH CPI series (IHSI)', 'https://www.brh.ht/wp-content/uploads/ipc.pdf', '2026-10-31', 'No education price index was read; we plan with the 15% headline assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HT', 1, 'goal_inflation_health', 0.16, NULL, 'assumption', 'BRH CPI series (IHSI)', 'https://www.brh.ht/wp-content/uploads/ipc.pdf', '2026-10-31', 'No health price index was read; we plan with 1 point above the 15% headline assumption, as private care tends to rise faster.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HT', 1, 'gold_return_base', 0.08, NULL, 'assumption', 'World Bank Commodity Markets (Pink Sheet) gold price; BRH reference rate', 'https://www.worldbank.org/en/research/commodity-markets', '2026-10-31', 'Dollar gold trend of about 4-5% a year plus 3-4% expected gourde depreciation, as the gourde has been stable near 131 per dollar since 2023 but fell sharply before.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HT', 1, 'gold_return_high', 0.12, NULL, 'assumption', 'World Bank Commodity Markets (Pink Sheet) gold price; BRH reference rate', 'https://www.worldbank.org/en/research/commodity-markets', '2026-10-31', 'High case: strong dollar gold and renewed gourde depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HT', 1, 'gold_return_low', 0.03, NULL, 'assumption', 'World Bank Commodity Markets (Pink Sheet) gold price; BRH reference rate', 'https://www.worldbank.org/en/research/commodity-markets', '2026-10-31', 'Low case: flat dollar gold and a stable gourde.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HT', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No readable source on a statutory gratuity or end-of-service payment under the Haitian Labour Code was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HT', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a major private hospital stay was found.', 0);
