INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HT', 1, 'inflation_cpi', 0.164, NULL, 'sourced', 'BRH: Évolution de l''indice des prix à la consommation (IHSI data)', 'https://www.brh.ht/wp-content/uploads/ipc.pdf', '2026-09-30', 'CPI (base 2017-2018=100) 647.6 in September 2026, up 16.4% year on year; inflation has fallen from 31.9% in September 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HT', 1, 'inflation_projection', 0.15, NULL, 'assumption', 'BRH CPI series (IHSI): 16.4% in Sept 2026; Sept-on-Sept 38.7% (2022), 31.8% (2023), 27.9% (2024), 31.9% (2025)', 'https://www.brh.ht/wp-content/uploads/ipc.pdf', '2026-10-31', 'The BRH publishes no inflation target and the 5-year average is near 29%, but inflation has been falling steadily through 2026, so we plan with a rounded 15%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HT', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published term-life premium rates by age from a regulator or other permitted source were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HT', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No industry-wide life claim settlement ratio from an insurance supervisor was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HT', 1, 'life_expectancy', 65.119, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=HT', '2024-12-31', 'Men 61.9, women 68.5 (2024). UN WPP 2024 via populationpyramid.net gives 65.5 for 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HT', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":16.5,"men":15.2,"women":17.7},{"age":65,"total":13.2,"men":12.1,"women":14.1},{"age":70,"total":10.1,"men":9.4,"women":10.8},{"age":80,"total":5.6,"men":5.2,"women":5.9}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/haiti/', '2026-07-01', 'Secondary source of UN WPP 2024 medium-variant projections for 2026; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
