INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HT', 1, 'policy_rate', 0.115, NULL, 'sourced', 'Banque de la République d''Haïti (BRH): Bons BRH, nominal rates by auction', 'https://www.brh.ht/wp-content/uploads/tableaubons.pdf', '2026-10-07', 'The BRH announces no single policy rate; its 91-day BRH bill (Bon BRH) rate, which BRH describes as the reference for banks'' treasury operations, has stayed at 11.5% (7-day 6%, 28-day 8%) through the auction of 7 October 2026.', 0);
