INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HT', 1, 'retirement_accumulation_return_base', 0.055, NULL, 'assumption', 'BRH deposit rates; global equity index in gourde terms', 'https://www.brh.ht/wp-content/uploads/tauxinteretgourdes.pdf', '2026-10-31', 'Base case: roughly half global equities at 7.5% and half deposits at 3.5%.', 0);
