INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HT', 1, 'retirement_age_default', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Office National d''Assurance-Vieillesse (ONA) runs the private-sector pension, but its site and the international social-security databases (SSA, ISSA, ILO) could not be read, so the pension age is not confirmed.', 0);
