INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HT', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 5-year government bond yield was found.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('HU', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"HU","iso3":"HUN","nameEn":"Hungary","nameNative":"Magyarország","region":"europe_central_asia","languages":["hu","en","de"],"currency":{"code":"HUF","symbol":"Ft","decimals":2,"compact":"intl","usdRate":{"value":326.64,"status":"sourced","sourceName":"Magyar Nemzeti Bank official exchange rate (USD)","sourceUrl":"https://www.mnb.hu/arfolyamok","asOf":"2026-10-30","note":"HUF 326.64 per US dollar on 30 October 2026 (EUR 365.80); World Bank 2025 average 353.14."}},"instruments":{"savings_account":{"available":true,"localName":"Megtakarítási számla","localNameEn":"Savings account","sourceUrl":"https://data-api.ecb.europa.eu/service/data/MIR/M.HU.B.L21.A.R.A.2250.HUF.N"},"fdr_3m":{"available":true,"localName":"Lekötött betét (3 hónap)","localNameEn":"Term deposit (3 months)"},"fdr_1y":{"available":true,"localName":"Lekötött betét (1 év)","localNameEn":"Term deposit (1 year)","sourceUrl":"https://data-api.ecb.europa.eu/service/data/MIR/M.HU.B.L22.F.R.A.2250.HUF.N"},"dps":{"available":false,"localName":null,"localNameEn":"Recurring deposit","note":"No standard monthly recurring-deposit product; the subsidised home savings scheme (lakás-takarékpénztár) closed to new contracts in 2018."},"sanchayapatra_5y":{"available":true,"localName":"Magyar Állampapír Plusz (MÁP Plusz)","localNameEn":"Hungarian Government Security Plus","note":"5-year retail government security with a stepped fixed rate, free of interest tax; sold by the State Treasury, post offices and banks.","sourceUrl":"https://akk.hu/en/securities-issuance-and-trading/types-government-securities/hg-security-plus-map-plusz"},"tbill_91d":{"available":true,"localName":"Diszkont Kincstárjegy (DKJ)","localNameEn":"Discount Treasury Bill","note":"3-, 6- and 12-month bills auctioned by ÁKK; interest taxed at 28%.","sourceUrl":"https://www.akk.hu/hu/statisztika/hozamok-indexek-forgalmi-adatok/referenciahozamok"},"tbond_5y":{"available":true,"localName":"Magyar Államkötvény","localNameEn":"Hungarian Government Bond","sourceUrl":"https://www.akk.hu/hu/statisztika/hozamok-indexek-forgalmi-adatok/referenciahozamok"},"tbond_10y":{"available":true,"localName":"Magyar Államkötvény","localNameEn":"Hungarian Government Bond","sourceUrl":"https://www.akk.hu/hu/statisztika/hozamok-indexek-forgalmi-adatok/referenciahozamok"},"equity_fund":{"available":true,"localName":"Befektetési alap","localNameEn":"Investment funds and index funds (ETFs)","note":"Retail mutual funds and exchange-traded index funds are widely available; a long-term investment account (TBSZ) lowers the tax after 3-5 years."},"gold":{"available":true,"localName":"Befektetési arany","localNameEn":"Investment gold (bars and coins)","note":"Buying physical gold bars and coins is legal and VAT-exempt."}},"institutions":{"centralBank":{"name":"Magyar Nemzeti Bank (Central Bank of Hungary)","url":"https://www.mnb.hu/en"},"insuranceRegulator":{"name":"Magyar Nemzeti Bank (financial supervisor for insurers)","url":"https://www.mnb.hu/en/supervision"},"insuranceComplaints":{"name":"Financial Arbitration Board (Pénzügyi Békéltető Testület)","url":"https://www.mnb.hu/bekeltetes","note":"Out-of-court dispute body for consumers in disputes with insurers and banks, operated by the MNB."},"pensionScheme":{"name":"Hungarian State Treasury, pension insurance (Nyugdíjbiztosítás)","url":"https://www.allamkincstar.gov.hu/"},"oldAgeAllowance":{"name":"Old-age allowance (időskorúak járadéka), Act III of 1993 sections 32/B-32/C","url":"https://njt.jog.gov.hu/jogszabaly/1993-3-00-00","note":"Claimed at the district government office (járási hivatal)."},"publicHealthCover":{"name":"NEAK (National Health Insurance Fund of Hungary)","url":"https://www.neak.gov.hu/"},"depositInsurance":{"name":"National Deposit Insurance Fund of Hungary (OBA)","url":"https://www.oba.hu/en"},"statistics":{"name":"Hungarian Central Statistical Office (KSH)","url":"https://www.ksh.hu/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HU', 1, 'bank_deposit_avg_rate', 0.0395, NULL, 'sourced', 'Magyar Nemzeti Bank, interest rate statistics release, August 2026 (household forint term deposits, new contracts)', 'https://statisztika.mnb.hu/sw/static/file/Kamat_HU_202608.pdf', '2026-08-31', 'Average rate on new household forint term deposits of all maturities was 3.95% in August 2026, down 0.18 points from July (4.81% a year earlier); World Bank FR.INR.DPST gives 5.71% for 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HU', 1, 'credit_card_rate_cap', 0.2376, NULL, 'sourced', 'ECB MFI interest rate statistics (reported by the MNB): Hungarian banks, extended credit card credit to households', 'https://data-api.ecb.europa.eu/service/data/MIR/M.HU.B.A2Z3.A.R.A.2250.HUF.N', '2026-09-30', 'Typical rate, not a legal cap: average 23.76% on extended credit card credit to households in September 2026 (24.12% in August). A legal APR ceiling linked to the base rate exists but its current level was not read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HU', 1, 'deposit_insurance_limit', 36580000, NULL, 'sourced', 'National Deposit Insurance Fund of Hungary (OBA), amount of compensation', 'https://www.oba.hu/en/deposit-insurance/ammount-of-compensation/', '2026-10-30', 'EUR 100,000 per depositor per bank, paid in forints at the MNB rate of the day before payout; converted at EUR 1 = HUF 365.80 (MNB, 30 October 2026). An extra EUR 50,000 covers certain temporary high balances.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HU', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No standard monthly recurring-deposit product with a published average rate was found for Hungary; the state-subsidised home savings scheme closed to new contracts in 2018.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HU', 1, 'equity_return_base', 0.08, NULL, 'assumption', 'BUX index (Trading Economics); tax-free MÁP Plusz 5.48%', 'https://tradingeconomics.com/hungary/stock-market', '2026-10-31', 'Base case: about 2.5 points over the tax-free retail government bond rate, below the strong 10-year BUX record because the index is concentrated in a few large companies.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HU', 1, 'equity_return_high', 0.11, NULL, 'assumption', 'BUX index (Trading Economics), roughly 15% a year over 2016-2026', 'https://tradingeconomics.com/hungary/stock-market', '2026-10-31', 'High case: Hungarian and diversified equity funds keep close to their strong forint returns of the last decade.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HU', 1, 'equity_return_low', 0.045, NULL, 'assumption', 'BUX index 145,257 on 30 Oct 2026, up about 35% in a year (Trading Economics); after-tax 1-year deposit about 3.0%', 'https://tradingeconomics.com/hungary/stock-market', '2026-10-31', 'Low case: Hungarian shares give back recent gains and earn only a little more than tax-free government securities.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HU', 1, 'fdr_1y_rate', 0.0423, NULL, 'sourced', 'ECB MFI interest rate statistics (reported by the MNB): household forint deposits with agreed maturity up to 1 year, new business', 'https://data-api.ecb.europa.eu/service/data/MIR/M.HU.B.L22.F.R.A.2250.HUF.N', '2026-09-30', 'Bucket covers all fixed terms up to one year: 4.23% in September 2026 (4.41% in August, 4.67% in July). The earlier figure of 4.05% did not match the ECB series and was corrected.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HU', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The MNB and ECB publish household term deposits up to 1 year as one bucket (4.23% in September 2026); no separate 3-month average was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HU', 1, 'fixed_income_return_base', 0.04, NULL, 'assumption', 'After-tax 1-year deposit 3.0%; tax-free MÁP Plusz 5.48% average', 'https://www.economx.hu/befektetes/2026/07/14/allampapir-akk-kamatcsokkentes-befektetes/', '2026-10-31', 'Base case: a mix of tax-free retail government securities and after-tax deposits, allowing for further rate cuts.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HU', 1, 'fixed_income_return_high', 0.055, NULL, 'assumption', 'Tax-free MÁP Plusz 5.48%; 5-year benchmark yield 5.46% (ÁKK)', 'https://www.akk.hu/hu/statisztika/hozamok-indexek-forgalmi-adatok/referenciahozamok', '2026-10-31', 'High case: mostly tax-free retail government securities at today''s rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HU', 1, 'fixed_income_return_low', 0.03, NULL, 'assumption', 'Household deposits up to 1 year 4.23% (September 2026) less 28% tax = 3.0% (ECB MIR)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.HU.B.L22.F.R.A.2250.HUF.N', '2026-10-31', 'Low case: after-tax bank term deposits only.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HU', 1, 'goal_inflation_education', 0.05, NULL, 'assumption', 'Eurostat/ECB HICP Hungary, education: 6.6% year on year in December 2025', 'https://data-api.ecb.europa.eu/service/data/ICP/M.HU.N.100000.4.ANR', '2026-10-31', 'Education prices rose 6.6% in 2025, well above general inflation; planning uses 5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HU', 1, 'goal_inflation_health', 0.055, NULL, 'assumption', 'Eurostat/ECB HICP Hungary, health: 7.0% year on year in December 2025', 'https://data-api.ecb.europa.eu/service/data/ICP/M.HU.N.060000.4.ANR', '2026-10-31', 'Health prices have risen faster than general prices (7.0% vs 3.3% in December 2025), so planning uses 5.5%, two points above general inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HU', 1, 'gold_return_base', 0.055, NULL, 'assumption', 'Gold USD price history (Trading Economics); MNB 3% inflation target', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Base case: dollar gold rises with world inflation plus a little, and the forint loses about 1.5% a year against the dollar as it has over the long run.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HU', 1, 'gold_return_high', 0.09, NULL, 'assumption', 'Gold USD price history (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'High case: a repeat of gold''s strong 2005-2025 trend in forint terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HU', 1, 'gold_return_low', 0.02, NULL, 'assumption', 'Gold USD price history (Trading Economics); forint per dollar 326.64 (MNB, 30 Oct 2026)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Low case: gold stalls after the 2025-26 spike and the forint stays stable against the dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HU', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Labour Code gives severance pay (végkielégítés) only on dismissal, scaled in months of pay by length of service (1 month after 3 years up to 6 months after 25), not a days-per-year retirement gratuity; no source stating the current scale was read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HU', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'Hospital care is free under NEAK public health insurance; no official figure for the out-of-pocket cost of a major private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HU', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Private health insurance is sold in Hungary, but no published premium table per HUF 100,000 of cover from a regulator or public source was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HU', 1, 'inflation_cpi', 0.016, NULL, 'sourced', 'Hungarian Central Statistical Office (KSH), consumer price index flash release, September 2026', 'https://www.ksh.hu/gyorstajekoztatok/far/far2609.html', '2026-09-30', 'Consumer prices were 1.6% higher than a year earlier in September 2026 (up 0.2% on August), released 7 October 2026. HICP averaged 4.4% in 2025 (ECB).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HU', 1, 'inflation_projection', 0.035, NULL, 'assumption', 'MNB 3% inflation target (tolerance band 2-4%); Hungarian HICP 2021-2025 average 9.1% (ECB ICP)', 'https://data-api.ecb.europa.eu/service/data/ICP/A.HU.N.000000.4.AVR', '2026-10-31', 'The MNB targets 3% but Hungary has repeatedly overshot it (15-17% in 2022-23), so planning uses 3.5%, slightly above the target even though CPI is 1.6% now.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HU', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life cover is sold in Hungary, but no regulator or official premium table per sum insured was found; only individual company quotes exist.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HU', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The MNB (insurance supervisor) publishes insurance market statistics, but no industry-wide life claim settlement ratio was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HU', 1, 'life_expectancy', 77.5, NULL, 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/hungary', '2026-07-01', 'Men 74.3, women 80.6 (UN WPP estimate for 2026); World Bank 2024 figure 76.7.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HU', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":21.2,"men":18.7,"women":23.2},{"age":65,"total":17.6,"men":15.5,"women":19.2},{"age":70,"total":14.2,"men":12.6,"women":15.4},{"age":80,"total":8.1,"men":7.4,"women":8.5}]}', 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/hungary', '2026-07-01', 'Remaining years computed from georank''s expected age at death by current age (UN WPP 2026 estimate).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HU', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":65,"womenAge":65,"over90Monthly":null,"meansTested":true}', 'sourced', 'European Commission, Your social security rights in Hungary (July 2026): old-age allowance (időskorúak járadéka)', 'https://employment-social-affairs.ec.europa.eu/document/download/cda27b4f-ad1c-419d-b4c4-28222a5d2c34_en', '2026-07-31', 'Paid from legal retirement age (65) to residents whose monthly income is below HUF 43,700 (living alone, under 75), HUF 37,165 per person (couples) or HUF 58,990 (alone, 75+); not paid to people living abroad more than 3 months. Legal basis: Act III of 1993, sections 32/B-32/C.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HU', 1, 'old_age_allowance_monthly', 43700, NULL, 'sourced', 'European Commission, Your social security rights in Hungary (July 2026): old-age allowance (időskorúak járadéka)', 'https://employment-social-affairs.ec.europa.eu/document/download/cda27b4f-ad1c-419d-b4c4-28222a5d2c34_en', '2026-07-31', 'HUF 43,700 a month for a person living alone between pension age and 74 with no income (HUF 37,165 per person if living with a spouse or partner; HUF 58,990 alone at 75+, given as 58,900 in another paragraph of the guide); any income is deducted, so this is the maximum.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HU', 1, 'oop_health_share', 0.2306, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=HU', '2023-12-31', 'Out-of-pocket spending was 23.1% of current health expenditure in 2023 (latest available; older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HU', 1, 'policy_rate', 0.055, NULL, 'sourced', 'Magyar Nemzeti Bank, central bank base rate history', 'https://www.mnb.hu/Jegybanki_alapkamat_alakulasa', '2026-08-26', 'Base rate 5.50% since 26 August 2026, still in force at the start of November 2026 (MNB base-rate table).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HU', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":65,"nomineeUntilAge":null,"inflationLinked":true,"taxFree":null}', 'sourced', 'European Commission, Your social security rights in Hungary (July 2026)', 'https://employment-social-affairs.ec.europa.eu/document/download/cda27b4f-ad1c-419d-b4c4-28222a5d2c34_en', '2026-07-31', 'Compulsory earnings-related state pension: pension age 65 with at least 20 years of service (minimum pension HUF 28,500 a month); raised each January in line with forecast inflation. Pensions are widely reported as not subject to personal income tax, but no official page confirming this was read, so taxFree is left blank.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HU', 1, 'retirement_accumulation_return_base', 0.06, NULL, 'assumption', 'Fixed income base 4%; equity base 8%', 'https://tradingeconomics.com/hungary/stock-market', '2026-10-31', 'Base case: roughly half shares at 8% and half safe fixed income at about 4%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HU', 1, 'retirement_accumulation_return_high', 0.08, NULL, 'assumption', 'Equity high 11%; tax-free government securities 5.5%', 'https://tradingeconomics.com/hungary/stock-market', '2026-10-31', 'High case for a growth-leaning balanced mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HU', 1, 'retirement_accumulation_return_low', 0.035, NULL, 'assumption', 'After-tax deposits 3.0%; BUX record (Trading Economics)', 'https://tradingeconomics.com/hungary/stock-market', '2026-10-31', 'Low case for a balanced mix if shares lag.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HU', 1, 'retirement_age_default', 65, NULL, 'sourced', 'European Commission, Your social security rights in Hungary (July 2026)', 'https://employment-social-affairs.ec.europa.eu/document/download/cda27b4f-ad1c-419d-b4c4-28222a5d2c34_en', '2026-07-31', 'Old-age pension age is 65 for everyone born in 1957 or later, men and women; women with 40 years of eligibility can retire earlier at any age.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HU', 1, 'retirement_age_government', 65, NULL, 'sourced', 'European Commission, Your social security rights in Hungary (July 2026)', 'https://employment-social-affairs.ec.europa.eu/document/download/cda27b4f-ad1c-419d-b4c4-28222a5d2c34_en', '2026-07-31', 'Civil servants are covered by the same statutory pension insurance, so the general pension age of 65 applies.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HU', 1, 'retirement_return_base', 0.035, NULL, 'assumption', '3-month treasury bill 5.14% less 28% tax = 3.7% (ÁKK); after-tax 1-year deposit 3.0%', 'https://www.akk.hu/hu/statisztika/hozamok-indexek-forgalmi-adatok/referenciahozamok', '2026-10-31', 'Base case: kept below the after-tax treasury bill rate, with some tax-free retail government securities in the mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HU', 1, 'retirement_return_high', 0.05, NULL, 'assumption', 'Tax-free MÁP Plusz 5.48% average', 'https://www.economx.hu/befektetes/2026/07/14/allampapir-akk-kamatcsokkentes-befektetes/', '2026-10-31', 'High case: mostly tax-free retail government securities, held to maturity.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HU', 1, 'retirement_return_low', 0.025, NULL, 'assumption', 'After-tax 1-year deposit 3.0% (ECB MIR, September 2026)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.HU.B.L22.F.R.A.2250.HUF.N', '2026-10-31', 'Low case: after-tax deposits with some further rate cuts.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HU', 1, 'sanchayapatra_5y_rate', 0.0548, NULL, 'sourced', 'Government Debt Management Agency (ÁKK) retail bond MÁP Plusz series from 17 July 2026, as reported by economx.hu', 'https://www.economx.hu/befektetes/2026/07/14/allampapir-akk-kamatcsokkentes-befektetes/', '2026-07-17', 'The 5-year Hungarian Government Security Plus series sold from 17 July 2026 pays a fixed stepped rate rising from 5% to 6%, 5.48% a year on average; secondary source (news report on the ÁKK announcement) because the ÁKK offering page loads by script. The rate may have been changed again after the August base-rate cut; this could not be checked.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HU', 1, 'savings_account_rate', 0.0017, NULL, 'sourced', 'ECB MFI interest rate statistics (reported by the MNB): Hungarian banks, overnight forint deposits from households', 'https://data-api.ecb.europa.eu/service/data/MIR/M.HU.B.L21.A.R.A.2250.HUF.N', '2026-09-30', 'Average rate on household overnight (sight and savings) forint deposits was 0.17% in August and September 2026 (0.21% in July).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HU', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":3.05},{"year":2040,"value":2.53},{"year":2065,"value":2.1}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/hungary/2040/', '2025-12-31', '100 / old-age dependency ratio: 32.8 (2025, World Bank), 39.5 (2040) and 47.7 (2065, populationpyramid.net/hungary/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HU', 1, 'tax_bank_interest', 0.28, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Hungary income determination', 'https://taxsummaries.pwc.com/hungary/individual/income-determination', '2026-07-01', '15% personal income tax plus 13% social contribution tax on interest from instruments bought after 1 July 2023 (bank deposits, treasury bills, funds); 0% or 10% inside a long-term investment account held 5 or 3 years.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HU', 1, 'tax_sanchayapatra_profit', 0, NULL, 'sourced', 'Government Debt Management Agency (ÁKK), Hungarian Government Security Plus (MÁP Plusz)', 'https://akk.hu/en/securities-issuance-and-trading/types-government-securities/hg-security-plus-map-plusz', '2024-10-01', 'No interest tax is charged on MÁP Plusz, and series issued after 1 June 2019 are exempt from the social contribution tax; product rules page dated October 2024, still in force.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HU', 1, 'tbill_91d_rate', 0.0514, NULL, 'sourced', 'Government Debt Management Agency (ÁKK), benchmark yields, 3-month', 'https://www.akk.hu/hu/statisztika/hozamok-indexek-forgalmi-adatok/referenciahozamok', '2026-10-30', '3-month benchmark yield 5.14% on 30 October 2026 (6-month 5.12%, 12-month 5.05%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HU', 1, 'tbond_10y_rate', 0.0545, NULL, 'sourced', 'Government Debt Management Agency (ÁKK), benchmark yields, 10-year', 'https://www.akk.hu/hu/statisztika/hozamok-indexek-forgalmi-adatok/referenciahozamok', '2026-10-30', '10-year benchmark yield (2037/A bond) 5.45% on 30 October 2026; ECB long-term convergence yield for Hungary 5.69% in September 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('HU', 1, 'tbond_5y_rate', 0.0546, NULL, 'sourced', 'Government Debt Management Agency (ÁKK), benchmark yields, 5-year', 'https://www.akk.hu/hu/statisztika/hozamok-indexek-forgalmi-adatok/referenciahozamok', '2026-10-30', '5-year benchmark yield (2033/C bond) 5.46% on 30 October 2026.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('ID', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"ID","iso3":"IDN","nameEn":"Indonesia","nameNative":"Indonesia","region":"east_asia_pacific","languages":["id","jv","su","en"],"currency":{"code":"IDR","symbol":"Rp","decimals":2,"compact":"intl","usdRate":{"value":17985,"status":"sourced","sourceName":"Bank Indonesia Board of Governors press release, 21 October 2026","sourceUrl":"https://www.bi.go.id/en/publikasi/ruang-media/news-release/Pages/sp_2823326.aspx","asOf":"2026-10-20","note":"Rupiah at Rp 17,985 per US dollar on 20 October 2026."}},"instruments":{"savings_account":{"available":true,"localName":"Tabungan","localNameEn":"Savings account","sourceUrl":"https://www.industry.co.id/read/155665/bunga-tabungan-bank-2026-perbandingan-konvensional-vs-digital-mana-paling-untung"},"fdr_3m":{"available":true,"localName":"Deposito berjangka","localNameEn":"Time deposit (3 months)","sourceUrl":"https://www.fortuneidn.com/finance/bunga-deposito-bank-tertinggi-oktober-2026-d7w02-00-yyq45-pk2kcg"},"fdr_1y":{"available":true,"localName":"Deposito berjangka","localNameEn":"Time deposit (12 months)","sourceUrl":"https://www.fortuneidn.com/finance/bunga-deposito-bank-tertinggi-oktober-2026-d7w02-00-yyq45-pk2kcg"},"dps":{"available":true,"localName":"Tabungan berjangka","localNameEn":"Time-savings plan","note":"Fixed monthly deposits for a set term; offered by most banks."},"sanchayapatra_5y":{"available":true,"localName":"Obligasi Negara Ritel (ORI) / Sukuk Ritel (SR)","localNameEn":"Retail government bonds","note":"Sold online several times a year from Rp 1 million; ORI is tradable, SR is sharia-compliant; coupon tax 10%.","sourceUrl":"https://investasi.kontan.co.id/news/pemerintah-terbitkan-ori029-tawarkan-kupon-tetap-545-580-per-tahun"},"tbill_91d":{"available":true,"localName":"Surat Perbendaharaan Negara (SPN)","localNameEn":"Treasury bills","note":"Sold at auction; retail investors buy through brokers or bank secondary markets.","sourceUrl":"https://tradingeconomics.com/indonesia/3-month-bill-yield"},"tbond_5y":{"available":true,"localName":"Surat Utang Negara (SUN)","localNameEn":"Government bonds","sourceUrl":"https://tradingeconomics.com/indonesia/government-bond-yield"},"tbond_10y":{"available":true,"localName":"Surat Utang Negara (SUN)","localNameEn":"Government bonds","sourceUrl":"https://tradingeconomics.com/indonesia/government-bond-yield"},"equity_fund":{"available":true,"localName":"Reksa dana saham / reksa dana indeks","localNameEn":"Equity or index mutual fund","note":"Regulated by OJK; widely sold online from small amounts."},"gold":{"available":true,"localName":"Emas batangan","localNameEn":"Gold bars","note":"Gold bars and coins are freely bought; also sold in small gram amounts through gold savings accounts."}},"institutions":{"centralBank":{"name":"Bank Indonesia","url":"https://www.bi.go.id/"},"insuranceRegulator":{"name":"Otoritas Jasa Keuangan (OJK)","url":"https://www.ojk.go.id/"},"insuranceComplaints":{"name":"OJK consumer complaints (Kontak OJK 157)","url":"https://kontak157.ojk.go.id/"},"pensionScheme":{"name":"BPJS Ketenagakerjaan (Jaminan Pensiun and Jaminan Hari Tua)","url":"https://www.bpjsketenagakerjaan.go.id/"},"oldAgeAllowance":{"name":"Kementerian Sosial (elderly social assistance)","url":"https://kemensos.go.id/","note":"No universal social pension; means-tested aid only."},"publicHealthCover":{"name":"BPJS Kesehatan (Jaminan Kesehatan Nasional)","url":"https://www.bpjs-kesehatan.go.id/"},"depositInsurance":{"name":"Lembaga Penjamin Simpanan (LPS)","url":"https://www.lps.go.id/"},"statistics":{"name":"Badan Pusat Statistik (BPS)","url":"https://www.bps.go.id/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ID', 1, 'bank_deposit_avg_rate', 0.0266, NULL, 'sourced', 'OJK, weighted average rupiah third-party funds rate (via Infobank)', 'https://infobanknews.com/ojk-nilai-tren-penurunan-suku-bunga-kredit-bank-berlanjut', '2026-03-31', 'OJK weighted average across current, savings and time deposits, reported 8 May 2026 (Infobank). World Bank FR.INR.DPST (time deposits) was 5.41% for 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ID', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'A Bank Indonesia cap of 1.75% a month (about 21% a year) since July 2021 is widely reported, but the only page read was a company page, which this dataset does not cite; the Bank Indonesia page could not be found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ID', 1, 'deposit_insurance_limit', 2000000000, NULL, 'sourced', 'Lembaga Penjamin Simpanan (LPS), press release 23/GKLM/2026', 'https://lps.go.id/konten/unggahan/2026/06/Siaran-Pers-TBP-LPS-Okt-26.pdf', '2026-09-29', 'Under the LPS Law, deposits up to Rp 2 billion per depositor per bank are guaranteed, provided the rate paid does not exceed the LPS guarantee rate (3.75% for rupiah deposits at commercial banks, 1 October 2026 to 31 January 2027).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ID', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Banks sell monthly time-savings plans (tabungan berjangka), but no typical published rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ID', 1, 'equity_return_base', 0.085, NULL, 'assumption', 'Retail government bond ORI029 5.8% less 10% tax (5.2%); IDX record', 'https://investasi.kontan.co.id/news/pemerintah-terbitkan-ori029-tawarkan-kupon-tetap-545-580-per-tahun', '2026-10-31', 'After-tax safe rate of about 5.2% plus a 3.3-point premium, kept modest because the main index''s 10-year record is weak.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ID', 1, 'equity_return_high', 0.12, NULL, 'assumption', 'Retail government bond ORI029 5.8% less 10% tax (5.2%); IDX record', 'https://investasi.kontan.co.id/news/pemerintah-terbitkan-ori029-tawarkan-kupon-tetap-545-580-per-tahun', '2026-10-31', 'High case close to nominal GDP growth plus dividends.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ID', 1, 'equity_return_low', 0.03, NULL, 'assumption', 'Retail government bond ORI029 5.8% less 10% tax (5.2%); IDX record', 'https://investasi.kontan.co.id/news/pemerintah-terbitkan-ori029-tawarkan-kupon-tetap-545-580-per-tahun', '2026-10-31', 'Low case reflecting the IDX Composite''s weak decade in local currency.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ID', 1, 'fdr_1y_rate', 0.026, NULL, 'sourced', 'Fortune Indonesia survey of the four largest banks'' deposit rates', 'https://www.fortuneidn.com/finance/bunga-deposito-bank-tertinggi-oktober-2026-d7w02-00-yyq45-pk2kcg', '2026-10-27', '12-month rupiah deposit: 2.50-3.00% across the four largest banks (mean about 2.6%), 27 October 2026. Deposits paying more than the LPS guarantee rate (3.75%) are not guaranteed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ID', 1, 'fdr_3m_rate', 0.026, NULL, 'sourced', 'Fortune Indonesia survey of the four largest banks'' deposit rates', 'https://www.fortuneidn.com/finance/bunga-deposito-bank-tertinggi-oktober-2026-d7w02-00-yyq45-pk2kcg', '2026-10-27', '3-month rupiah deposit: 2.25-3.00% across the four largest banks (mean about 2.6%), 27 October 2026. Deposits paying more than the LPS guarantee rate (3.75%) are not guaranteed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ID', 1, 'fixed_income_return_base', 0.045, NULL, 'assumption', 'Mix of deposits and retail government bonds after tax', 'https://investasi.kontan.co.id/news/pemerintah-terbitkan-ori029-tawarkan-kupon-tetap-545-580-per-tahun', '2026-10-31', 'Base case: about two thirds retail government bonds (5.2% after tax) and one third deposits (2.1%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ID', 1, 'fixed_income_return_high', 0.06, NULL, 'assumption', 'Government bond yields 7.5-7.6% less 10% tax', 'https://tradingeconomics.com/indonesia/government-bond-yield', '2026-10-31', 'High case: locking in current government bond yields after the 10% final tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ID', 1, 'fixed_income_return_low', 0.021, NULL, 'assumption', 'Large-bank 1-year deposit 2.6% less 20% final tax', 'https://www.fortuneidn.com/finance/bunga-deposito-bank-tertinggi-oktober-2026-d7w02-00-yyq45-pk2kcg', '2026-10-31', 'Low case: bank deposits only, after the 20% final tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ID', 1, 'goal_inflation_education', 0.04, NULL, 'assumption', 'BPS CPI; Bank Indonesia inflation target 2.5% plus or minus 1%', 'https://www.bi.go.id/en/publikasi/ruang-media/news-release/Pages/sp_2823326.aspx', '2026-10-31', 'No education CPI figure was retrieved; we plan with headline plus 1 point for private school fees.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ID', 1, 'goal_inflation_health', 0.045, NULL, 'assumption', 'BPS CPI; Bank Indonesia inflation target 2.5% plus or minus 1%', 'https://www.bi.go.id/en/publikasi/ruang-media/news-release/Pages/sp_2823326.aspx', '2026-10-31', 'No medical CPI figure was retrieved; we plan with headline plus 1.5 points for private hospital and drug costs.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ID', 1, 'gold_return_base', 0.08, NULL, 'assumption', 'World Bank PA.NUS.FCRF (rupiah per USD, 2025 average 16,478; 17,985 on 20 Oct 2026)', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=ID', '2026-10-31', 'Dollar gold trend of about 4-5% plus about 3% a year of rupiah depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ID', 1, 'gold_return_high', 0.12, NULL, 'assumption', 'World Bank PA.NUS.FCRF (rupiah per USD, 2025 average 16,478; 17,985 on 20 Oct 2026)', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=ID', '2026-10-31', 'High case with strong dollar gold and faster rupiah depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ID', 1, 'gold_return_low', 0.03, NULL, 'assumption', 'World Bank PA.NUS.FCRF (rupiah per USD, 2025 average 16,478; 17,985 on 20 Oct 2026)', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=ID', '2026-10-31', 'Low case: flat dollar gold with modest rupiah weakening.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ID', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'Severance (pesangon) on retirement exists under Government Regulation 35/2021 (months of wages by years of service plus a long-service award), but no reachable source was read in this pass and the capped formula does not map cleanly to days per year.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ID', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical out-of-pocket cost of a major private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ID', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health premium table by age was found; most people are covered by JKN (BPJS Kesehatan).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ID', 1, 'inflation_cpi', 0.0328, NULL, 'sourced', 'Bank Indonesia Board of Governors press release (BPS CPI)', 'https://www.bi.go.id/en/publikasi/ruang-media/news-release/Pages/sp_2823326.aspx', '2026-09-30', 'CPI 3.28% year on year in September 2026 (core 2.84%), per BPS release of 1 October 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ID', 1, 'inflation_projection', 0.03, NULL, 'assumption', 'Bank Indonesia inflation target 2.5% plus or minus 1% (2026-2027); 2021-2025 CPI average about 2.7%', 'https://www.bi.go.id/en/publikasi/ruang-media/news-release/Pages/sp_2823326.aspx', '2026-10-31', 'Target midpoint is 2.5%, but the 5-year average and the weak rupiah argue for planning slightly above it at 3%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ID', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life is sold in Indonesia, but no published per-1,000-rupiah premium rates by age were found within this research pass.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ID', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'OJK insurance statistics were not reachable and no industry-wide life claim settlement ratio was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ID', 1, 'life_expectancy', 71.288, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=ID', '2024-12-31', 'UN WPP 2024 (via populationpyramid.net) gives 71.6 for 2026. World Bank figure is for 2024 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ID', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":18.1,"men":16.5,"women":19.6},{"age":65,"total":14.6,"men":13.2,"women":15.8},{"age":70,"total":11.3,"men":10.3,"women":12.3},{"age":80,"total":6.3,"men":5.8,"women":6.8}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/indonesia/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there). Values are the UN WPP 2024 estimates for calendar 2026 (mid-year date used).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ID', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'No universal social pension; eligibility rules for the PKH elderly component could not be confirmed from a reachable source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ID', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'Indonesia has no universal non-contributory old-age pension; poor elderly receive means-tested household aid (PKH elderly component, ATENSI), but current amounts could not be confirmed from a reachable source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ID', 1, 'oop_health_share', 0.3108, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=ID', '2023-12-31', 'Figure is for 2023 (older than 2025); latest World Bank value.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ID', 1, 'policy_rate', 0.0575, NULL, 'sourced', 'Bank Indonesia Board of Governors press release, 21 October 2026', 'https://www.bi.go.id/en/publikasi/ruang-media/news-release/Pages/sp_2823326.aspx', '2026-10-21', 'BI-Rate held at 5.75%; deposit facility raised to 5.00%, lending facility 6.50%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ID', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":65,"nomineeUntilAge":null,"inflationLinked":true,"taxFree":null}', 'sourced', 'BPJS Ketenagakerjaan, Jaminan Pensiun for wage earners', 'https://www.bpjsketenagakerjaan.go.id/penerima-upah.html', '2026-01-01', 'Jaminan Pensiun (BPJS Ketenagakerjaan): 2% employer plus 1% employee on wages up to Rp 10,547,400; monthly pension Rp 411,400 to 4,932,300 in 2026 (limits raised yearly, hence inflationLinked). Pension age is 59 in 2025-2027 and rises to 65 by 2043 (Government Regulation 45/2015), so 65 is used for people born after 1975. Separate JHT savings: 3.7% employer plus 2% employee.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ID', 1, 'retirement_accumulation_return_base', 0.07, NULL, 'assumption', 'Retail government bond ORI029 5.8% less 10% tax (5.2%); IDX record', 'https://investasi.kontan.co.id/news/pemerintah-terbitkan-ori029-tawarkan-kupon-tetap-545-580-per-tahun', '2026-10-31', 'Base case: roughly half equity at 8.5% and half fixed income at 5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ID', 1, 'retirement_accumulation_return_high', 0.09, NULL, 'assumption', 'Retail government bond ORI029 5.8% less 10% tax (5.2%); IDX record', 'https://investasi.kontan.co.id/news/pemerintah-terbitkan-ori029-tawarkan-kupon-tetap-545-580-per-tahun', '2026-10-31', 'High case with the equity high case.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ID', 1, 'retirement_accumulation_return_low', 0.05, NULL, 'assumption', 'Retail government bond ORI029 5.8% less 10% tax (5.2%); IDX record', 'https://investasi.kontan.co.id/news/pemerintah-terbitkan-ori029-tawarkan-kupon-tetap-545-580-per-tahun', '2026-10-31', 'Low case for a balanced mix if equities match bonds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ID', 1, 'retirement_age_default', 65, NULL, 'sourced', 'Wikipedia: Retirement age (Indonesia), citing Government Regulation 45/2015 Article 15 (secondary source)', 'https://en.wikipedia.org/wiki/Retirement_age', '2026-10-31', 'Jaminan Pensiun age was 56 at the start, 57 from 2019, then rises one year every three years to 65 in 2043 (59 in 2025-2027). Someone born after 1975 reaches pension age in 2040 or later, so 65 applies (64 for people born 1976-1978); same for men and women. The official regulation page (peraturan.bpk.go.id) returned 403.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ID', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'Civil servant (ASN) retirement ages could not be confirmed from a reachable official or secondary page in this pass.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ID', 1, 'retirement_return_base', 0.045, NULL, 'assumption', '3-month government bill 6.55% less 10% tax (5.9%); retail bonds 5.2% after tax', 'https://tradingeconomics.com/indonesia/3-month-bill-yield', '2026-10-31', 'Base case below the after-tax government bill rate, for a mix of retail government bonds and deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ID', 1, 'retirement_return_high', 0.055, NULL, 'assumption', 'Retail government bonds and bills after tax', 'https://tradingeconomics.com/indonesia/3-month-bill-yield', '2026-10-31', 'High case mostly in government bills and retail bonds after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ID', 1, 'retirement_return_low', 0.021, NULL, 'assumption', 'Large-bank 1-year deposit 2.6% less 20% final tax', 'https://www.fortuneidn.com/finance/bunga-deposito-bank-tertinggi-oktober-2026-d7w02-00-yyq45-pk2kcg', '2026-10-31', 'Low case: deposits only after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ID', 1, 'sanchayapatra_5y_rate', 0.058, NULL, 'sourced', 'Kontan: Government issues ORI029 retail bond', 'https://investasi.kontan.co.id/news/pemerintah-terbitkan-ori029-tawarkan-kupon-tetap-545-580-per-tahun', '2026-01-26', 'ORI029 retail government bond: 3-year 5.45%, 6-year 5.80% fixed; Rp 1 million minimum. The July 2026 ORI030 reportedly paid about 6.9-7.0% (not confirmed from the official notice).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ID', 1, 'savings_account_rate', 0.005, NULL, 'sourced', 'Industry.co.id survey of large-bank savings rates', 'https://www.industry.co.id/read/155665/bunga-tabungan-bank-2026-perbandingan-konvensional-vs-digital-mana-paling-untung', '2026-09-09', 'Regular savings accounts at large state and private banks pay about 0.5-1% a year, most at 0.5%; interest is taxed 20% at source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ID', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":9},{"year":2040,"value":5.6},{"year":2065,"value":3.5}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/indonesia/2040/', '2025-12-31', '100 / old-age dependency ratio: 11.06 (2025, World Bank), 18.0 (2040) and 28.6 (2065, populationpyramid.net/indonesia/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ID', 1, 'tax_bank_interest', 0.2, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Indonesia individual income determination', 'https://taxsummaries.pwc.com/indonesia/individual/income-determination', '2026-06-11', 'Final income tax of 20% on interest from savings and time deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ID', 1, 'tax_sanchayapatra_profit', 0.1, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Indonesia individual income determination', 'https://taxsummaries.pwc.com/indonesia/individual/income-determination', '2026-06-11', 'Interest on bonds, including retail government bonds (ORI/SR), is subject to 10% final income tax withheld by the payer.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ID', 1, 'tbill_91d_rate', 0.06555, NULL, 'sourced', 'Trading Economics, Indonesia 3-month bill yield (secondary source)', 'https://tradingeconomics.com/indonesia/3-month-bill-yield', '2026-10-30', 'Primary DJPPR auction results were not reachable.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ID', 1, 'tbond_10y_rate', 0.0764, NULL, 'sourced', 'Trading Economics, Indonesia 10-year government bond yield (secondary source)', 'https://tradingeconomics.com/indonesia/government-bond-yield', '2026-10-30', 'Secondary source; previous close 7.64% (30 October 2026), 7.71% on 2 November.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ID', 1, 'tbond_5y_rate', 0.0752, NULL, 'sourced', 'Trading Economics, Indonesia 5-year government bond yield (secondary source)', 'https://tradingeconomics.com/indonesia/government-bond-yield', '2026-10-30', 'Secondary source; Trading Economics showed 7.71% on 2 November 2026 after a 0.19-point rise, consistent with about 7.52% on 30 October.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('IE', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"IE","iso3":"IRL","nameEn":"Ireland","nameNative":"Éire","region":"europe_central_asia","languages":["en","ga"],"currency":{"code":"EUR","symbol":"€","decimals":2,"compact":"intl","usdRate":{"value":0.8951,"status":"sourced","sourceName":"European Central Bank euro reference rate (USD)","sourceUrl":"https://data-api.ecb.europa.eu/service/data/EXR/D.USD.EUR.SP00.A","asOf":"2026-10-30","note":"EUR 1 = USD 1.1172 on 30 October 2026, so about EUR 0.895 per US dollar; World Bank 2025 average 0.885."}},"instruments":{"savings_account":{"available":true,"localName":null,"localNameEn":null,"note":"Instant-access and notice savings accounts at banks and credit unions; interest taxed at 33% DIRT. State Savings also offers a Deposit Account."},"fdr_3m":{"available":true,"localName":null,"localNameEn":"Fixed-term deposit (3 months)"},"fdr_1y":{"available":true,"localName":null,"localNameEn":"Fixed-term deposit (1 year)","sourceUrl":"https://data-api.ecb.europa.eu/service/data/MIR/M.IE.B.L22.F.R.A.2250.EUR.N"},"dps":{"available":true,"localName":"Instalment Savings","localNameEn":"State Savings monthly savings plan","note":"Government-backed: monthly payments for 12 months, then held to 6 years for a tax-free return.","sourceUrl":"https://www.statesavings.ie/our-products/instalment-savings"},"sanchayapatra_5y":{"available":true,"localName":"Savings Certificates","localNameEn":"State Savings 5-year certificate","note":"Sold by the NTMA through State Savings; also 3-year Savings Bonds and 10-year National Solidarity Bonds, all tax-free.","sourceUrl":"https://www.statesavings.ie/our-products/5-year-savings-certificates"},"tbill_91d":{"available":true,"localName":"Irish Treasury Bills","localNameEn":null,"note":"Issued by the NTMA mainly to institutional investors."},"tbond_5y":{"available":true,"localName":"Irish Government Bonds","localNameEn":null,"note":"Bought through a stockbroker; interest is taxed as income."},"tbond_10y":{"available":true,"localName":"Irish Government Bonds","localNameEn":null,"sourceUrl":"https://tradingeconomics.com/ireland/government-bond-yield"},"equity_fund":{"available":true,"localName":null,"localNameEn":"Unit trusts, unit-linked funds and index funds (ETF)","note":"Gains on Irish and EU-domiciled funds and unit-linked life policies are taxed by an exit tax (38% in 2026, with a deemed disposal every 8 years) rather than capital gains tax."},"gold":{"available":true,"localName":null,"localNameEn":"Gold bars and coins","note":"Legal to buy; investment gold is exempt from VAT and gains are subject to capital gains tax."}},"institutions":{"centralBank":{"name":"Central Bank of Ireland","url":"https://www.centralbank.ie/","note":"Part of the Eurosystem; monetary policy set by the European Central Bank."},"insuranceRegulator":{"name":"Central Bank of Ireland","url":"https://www.centralbank.ie/"},"insuranceComplaints":{"name":"Financial Services and Pensions Ombudsman (FSPO)","url":"https://www.fspo.ie/","note":"Free once the insurer''s own complaints process has finished."},"pensionScheme":{"name":"State Pension (Contributory), Department of Social Protection","url":"https://www.citizensinformation.ie/en/social-welfare/older-and-retired-people/state-pension-contributory/"},"oldAgeAllowance":{"name":"State Pension (Non-Contributory)","url":"https://www.citizensinformation.ie/en/social-welfare/older-and-retired-people/state-pension-non-contributory/"},"publicHealthCover":{"name":"Health Service Executive (HSE)","url":"https://www.hse.ie/","note":"Public hospital care for all residents; medical cards and GP visit cards are means- or age-tested."},"depositInsurance":{"name":"Deposit Guarantee Scheme (Central Bank of Ireland)","url":"https://www.depositguarantee.ie/"},"statistics":{"name":"Central Statistics Office (CSO)","url":"https://www.cso.ie/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IE', 1, 'bank_deposit_avg_rate', 0.0219, NULL, 'sourced', 'ECB MFI interest rate statistics: Irish banks, household deposits with agreed maturity (outstanding amounts)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.IE.B.L22.A.R.A.2250.EUR.O', '2026-09-30', 'Average rate on all outstanding household term deposits, 2.19% in September 2026; World Bank FR.INR.DPST has no recent figure for Ireland.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IE', 1, 'credit_card_rate_cap', 0.0914, NULL, 'sourced', 'ECB MFI interest rate statistics: Irish banks, revolving loans, overdrafts and credit card credit to households', 'https://data-api.ecb.europa.eu/service/data/MIR/M.IE.B.A2Z.A.R.A.2250.EUR.N', '2026-09-30', 'Average rate on revolving loans, overdrafts and extended credit card credit combined, 9.14% in September 2026; Ireland has no legal cap on card rates and card APRs are typically higher.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IE', 1, 'deposit_insurance_limit', 100000, NULL, 'sourced', 'Deposit Guarantee Scheme (Central Bank of Ireland), What we cover', 'https://www.depositguarantee.ie/en/what-we-cover', '2026-10-31', 'EUR 100,000 for eligible deposits, paid automatically; the EU-wide limit applies per depositor per bank.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IE', 1, 'dps_rate', 0.0233, NULL, 'sourced', 'NTMA, State Savings rates from 30 August 2026 (6-year Instalment Savings)', 'https://www.ntma.ie/news/ntma-to-increase-ireland-state-savings-rates', '2026-08-30', 'Government-backed 6-year monthly savings plan: 13.5% total return, 2.33% AER (assumes an average term of 5.5 years), tax-free; new issues from 30 August 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IE', 1, 'equity_return_base', 0.055, NULL, 'assumption', 'ISEQ (Trading Economics); 5-year Savings Certificates 2.29% tax-free (State Savings)', 'https://tradingeconomics.com/ireland/stock-market', '2026-10-31', 'The ISEQ is at a record high after a strong decade, but the base is held to the tax-free 3-year State Savings rate of about 2% plus 3.5 points, as a diversified fund would earn.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IE', 1, 'equity_return_high', 0.075, NULL, 'assumption', 'ISEQ price index (Trading Economics); long-run global equity returns', 'https://tradingeconomics.com/ireland/stock-market', '2026-10-31', 'High case: a diversified global or euro equity fund matching long-run equity returns of about 7-8% in euros.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IE', 1, 'equity_return_low', 0.03, NULL, 'assumption', 'ISEQ 14,207 on 30 Oct 2026, up 19.6% in a year (Trading Economics); State Savings tax-free about 2%', 'https://tradingeconomics.com/ireland/stock-market', '2026-10-31', 'Low case: Irish shares, a small bank-heavy market, earn little more than tax-free State Savings over a long period, as after 2007.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IE', 1, 'fdr_1y_rate', 0.0199, NULL, 'sourced', 'ECB MFI interest rate statistics: Irish banks, household deposits with agreed maturity up to 1 year (new business)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.IE.B.L22.F.R.A.2250.EUR.N', '2026-09-30', '1.99% in September 2026 (1.81% in August); the bucket covers all fixed terms up to one year; interest is subject to 33% DIRT.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IE', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'ECB and Central Bank of Ireland MFI statistics publish household deposits with agreed maturity up to 1 year as one bucket (1.99% in September 2026); no 3-month fixed-term rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IE', 1, 'fixed_income_return_base', 0.018, NULL, 'assumption', 'State Savings 1.96-2.29% tax-free; 1-year deposits 1.99% less 33% DIRT = 1.3%', 'https://www.ntma.ie/news/ntma-to-increase-ireland-state-savings-rates', '2026-10-31', 'Base case: a mix of tax-free State Savings products and term deposits after DIRT.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IE', 1, 'fixed_income_return_high', 0.025, NULL, 'assumption', 'National Solidarity Bonds 2.66% tax-free over 10 years (State Savings)', 'https://www.ntma.ie/news/ntma-to-increase-ireland-state-savings-rates', '2026-10-31', 'High case: locking in 10-year tax-free National Solidarity Bonds at about today''s rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IE', 1, 'fixed_income_return_low', 0.011, NULL, 'assumption', '1-year deposits 1.99% less 33% DIRT = 1.3% (ECB MFI statistics, Sep 2026)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.IE.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Low case: deposit and State Savings rates drift lower if the ECB cuts again.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IE', 1, 'goal_inflation_education', 0.05, NULL, 'assumption', 'CSO CPI September 2026: Education Services division +8.9% a year', 'https://www.cso.ie/en/releasesandpublications/ep/p-cpi/consumerpriceindexseptember2026/', '2026-10-31', 'Education prices are rising far faster than headline inflation this year; 5% allows for continued fee and childcare-linked increases without assuming the current spike lasts.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IE', 1, 'goal_inflation_health', 0.03, NULL, 'assumption', 'CSO CPI September 2026: Health division +1.8% a year', 'https://www.cso.ie/en/releasesandpublications/ep/p-cpi/consumerpriceindexseptember2026/', '2026-10-31', 'Measured health prices are rising below headline inflation, but private fees and health insurance premiums tend to rise faster over time, so 3% is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IE', 1, 'gold_return_base', 0.04, NULL, 'assumption', 'Gold price history (Trading Economics); ECB 2% inflation target', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Base case: dollar gold rises roughly with world inflation plus a little, and the euro is assumed stable against the dollar over the long run.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IE', 1, 'gold_return_high', 0.07, NULL, 'assumption', 'Gold price history (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'High case: a repeat of gold''s strong 2005-2025 trend in euro terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IE', 1, 'gold_return_low', 0.01, NULL, 'assumption', 'Gold USD 3,876/oz on 30 Oct 2026, 31% below the January 2026 high (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Low case: gold barely keeps up after the 2025-26 spike, with no help from the euro.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IE', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'Ireland has no statutory gratuity paid on retirement or resignation; the only statutory lump sum is redundancy pay (2 weeks'' pay per year of service plus one week, weekly pay capped at EUR 600), paid only when a job is made redundant (Citizens Information, Redundancy payments).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IE', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'Public hospital in-patient care is largely free through the HSE and most private stays are paid by insurers; no official figure for a typical out-of-pocket cost of a major private stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IE', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Irish private health insurance is community-rated (same price for all ages, plus a lifetime community rating loading for late joiners) and priced per plan, not per sum insured, so no premium per EUR 100,000 of cover by age exists.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IE', 1, 'inflation_cpi', 0.041, NULL, 'sourced', 'Central Statistics Office (CSO), Consumer Price Index September 2026', 'https://www.cso.ie/en/releasesandpublications/ep/p-cpi/consumerpriceindexseptember2026/', '2026-09-30', 'CPI up 4.1% in the 12 months to September 2026 (HICP 3.8%); 3.7% in August 2026 (Trading Economics). World Bank 2025 average 2.2%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IE', 1, 'inflation_projection', 0.023, NULL, 'assumption', 'ECB 2% medium-term target; Irish CPI 4.1% (Sep 2026) after 2.2% in 2025 (World Bank)', 'https://www.cso.ie/en/releasesandpublications/ep/p-cpi/consumerpriceindexseptember2026/', '2026-10-31', 'Ireland uses the euro, so the ECB 2% target anchors long-run inflation, but Irish prices have run a little above the euro area, so 2.3% is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IE', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life (life assurance and mortgage protection) is widely sold, but no published premium table per EUR 1,000 of cover by age was found; broker quote tools were not used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IE', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Central Bank of Ireland and Insurance Ireland do not publish an industry-wide life claim settlement ratio that could be found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IE', 1, 'life_expectancy', 82.9, NULL, 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/ireland', '2026-07-01', 'Men 81.0, women 84.9 (UN WPP estimate for 2026); World Bank 2024 figure 83.0. UN WPP mid-year estimate for 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IE', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":25.1,"men":23.7,"women":26.6},{"age":65,"total":20.8,"men":19.5,"women":22.1},{"age":70,"total":16.7,"men":15.5,"women":17.9},{"age":80,"total":9.5,"men":8.7,"women":10.3}]}', 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/ireland', '2026-07-01', 'Remaining years computed from georank''s expected age at death by current age (UN WPP 2026 estimate). UN WPP mid-year estimate for 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IE', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":66,"womenAge":66,"over90Monthly":null,"meansTested":true}', 'sourced', 'Citizens Information, State Pension (Non-Contributory)', 'https://www.citizensinformation.ie/en/social-welfare/older-and-retired-people/state-pension-non-contributory/', '2026-10-31', 'From 66 for men and women; means-tested (income and capital above EUR 20,000), and the claimant must meet the habitual residence condition.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IE', 1, 'old_age_allowance_monthly', 1248, NULL, 'sourced', 'Citizens Information, State Pension (Non-Contributory) rates 2026', 'https://www.citizensinformation.ie/en/social-welfare/older-and-retired-people/state-pension-non-contributory/', '2026-01-01', 'Means-tested maximum personal rate EUR 288 a week for ages 66-79 in 2026 (EUR 288 x 52 / 12 = EUR 1,248 a month); EUR 10 a week more from January 2027 (Budget 2027).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IE', 1, 'oop_health_share', 0.1061, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=IE', '2024-12-31', NULL, 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IE', 1, 'policy_rate', 0.025, NULL, 'sourced', 'European Central Bank, key ECB interest rates (deposit facility)', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.en.html', '2026-09-16', 'Ireland uses the euro; ECB deposit facility rate 2.50% (main refinancing 2.65%) since 16 September 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IE', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":66,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":false}', 'sourced', 'Citizens Information, State Pension (Contributory); Taxation of pensions', 'https://www.citizensinformation.ie/en/social-welfare/older-and-retired-people/state-pension-contributory/', '2026-10-31', 'PRSI-based State Pension (Contributory) from 66, maximum EUR 299.30 a week in 2026 with 2,080 contributions (40 years), minimum 520 contributions; rates rise through the annual Budget, not by a statutory index; social welfare pensions are taxable income. MyFutureFund auto-enrolment (employees 23-60) started 1 January 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IE', 1, 'retirement_accumulation_return_base', 0.035, NULL, 'assumption', 'State Savings about 2% tax-free; equity base 5.5%', 'https://www.ntma.ie/news/ntma-to-increase-ireland-state-savings-rates', '2026-10-31', 'Base case: roughly half shares at 5.5% and half safe fixed income at about 1.8% after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IE', 1, 'retirement_accumulation_return_high', 0.05, NULL, 'assumption', 'National Solidarity Bonds 2.66%; equity high 7.5%', 'https://www.ntma.ie/news/ntma-to-increase-ireland-state-savings-rates', '2026-10-31', 'High case for a growth-leaning balanced mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IE', 1, 'retirement_accumulation_return_low', 0.02, NULL, 'assumption', 'State Savings about 2% tax-free; ISEQ record (Trading Economics)', 'https://www.ntma.ie/news/ntma-to-increase-ireland-state-savings-rates', '2026-10-31', 'Low case for a balanced mix if shares lag.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IE', 1, 'retirement_age_default', 66, NULL, 'sourced', 'Citizens Information, State Pension (Contributory)', 'https://www.citizensinformation.ie/en/social-welfare/older-and-retired-people/state-pension-contributory/', '2026-10-31', 'State Pension age is 66 for men and women; the pension can be deferred up to 70 for a higher rate. Ireland has no general statutory retirement age for private employees.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IE', 1, 'retirement_age_government', 66, NULL, 'sourced', 'Single Public Service Pension Scheme, scheme overview', 'https://singlepensionscheme.gov.ie/overview/', '2026-10-31', 'Normal retirement age for Single Scheme members (public servants recruited since 2013) equals the State Pension age, currently 66, with compulsory retirement at 70; older public servants have earlier pension ages.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IE', 1, 'retirement_return_base', 0.012, NULL, 'assumption', '1-year deposits 1.99% less 33% DIRT = 1.3% (ECB MFI statistics, Sep 2026)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.IE.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Base case kept just below the after-tax 1-year term deposit rate of about 1.3%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IE', 1, 'retirement_return_high', 0.022, NULL, 'assumption', 'State Savings Certificates 2.29% and National Solidarity Bonds 2.66%, tax-free', 'https://www.ntma.ie/news/ntma-to-increase-ireland-state-savings-rates', '2026-10-31', 'High case: a retiree ladders tax-free 5- and 10-year State Savings products.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IE', 1, 'retirement_return_low', 0.008, NULL, 'assumption', '1-year deposits 1.99% less 33% DIRT = 1.3% (ECB MFI statistics, Sep 2026)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.IE.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Low case: deposit rates fall back after ECB cuts.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IE', 1, 'sanchayapatra_5y_rate', 0.0229, NULL, 'sourced', 'NTMA, State Savings rates from 30 August 2026 (5-year Savings Certificate, Issue 26)', 'https://www.ntma.ie/news/ntma-to-increase-ireland-state-savings-rates', '2026-08-30', 'Government-backed 5-year certificate: 12% total return, 2.29% AER, tax-free if held to maturity; 3-year Savings Bonds pay 1.96% and 10-year National Solidarity Bonds 2.66% AER. Also shown on statesavings.ie/our-products/5-year-savings-certificates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IE', 1, 'savings_account_rate', 0.0023, NULL, 'sourced', 'ECB MFI interest rate statistics: Irish banks, household overnight deposits (new business)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.IE.B.L21.A.R.A.2250.EUR.N', '2026-09-30', 'Average rate on household overnight (instant-access) deposits at Irish banks, 0.23% in September 2026 (0.22% in August); notice and online savings accounts pay more.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IE', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":4.05},{"year":2040,"value":2.87},{"year":2065,"value":2.13}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/ireland/2040/', '2025-12-31', '100 / old-age dependency ratio: 24.7 (2025, World Bank), 34.8 (2040) and 47.0 (2065, populationpyramid.net/ireland/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IE', 1, 'tax_bank_interest', 0.33, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Ireland income determination', 'https://taxsummaries.pwc.com/ireland/individual/income-determination', '2026-10-31', 'Deposit Interest Retention Tax (DIRT) of 33% is deducted at source and settles the income tax due; certain people (for example some aged 65+ on low incomes) can claim exemption or repayment.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IE', 1, 'tax_sanchayapatra_profit', 0, NULL, 'sourced', 'NTMA, State Savings rates announcement (17 August 2026)', 'https://www.ntma.ie/news/ntma-to-increase-ireland-state-savings-rates', '2026-08-30', 'The NTMA states that returns on the fixed-term State Savings products are tax free (no DIRT); interest on the State Savings deposit account is subject to DIRT.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IE', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The NTMA issues Irish Treasury Bills to institutional investors, but no published 3-month yield could be read (NTMA auction pages not reachable; Trading Economics shows only the 10-year yield).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IE', 1, 'tbond_10y_rate', 0.0347, NULL, 'sourced', 'Trading Economics, Ireland 10-year government bond yield', 'https://tradingeconomics.com/ireland/government-bond-yield', '2026-10-30', 'Secondary source; Trading Economics showed 3.47% on 2 November 2026 after 3.48% in the previous session. The ECB long-term (10-year) convergence yield for Ireland was 3.59% in September 2026 (ECB IRS.M.IE.L.L40.CI.0000.EUR.N.Z).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IE', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 5-year Irish government bond yield could be read: Trading Economics and worldgovernmentbonds.com pages returned no 5-year figure.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('IL', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"IL","iso3":"ISR","nameEn":"Israel","nameNative":"ישראל","region":"middle_east_north_africa","languages":["he","ar","en","ru"],"currency":{"code":"ILS","symbol":"₪","decimals":2,"compact":"intl","usdRate":{"value":3.118,"status":"sourced","sourceName":"Bank of Israel statistics API, representative exchange rate USD/ILS (series RER_USD_ILS)","sourceUrl":"https://edge.boi.gov.il/FusionEdgeServer/sdmx/v2/data/dataflow/BOI.STATISTICS/EXR/1.0/RER_USD_ILS?lastNObservations=1&format=csv","asOf":"2026-10-30","note":"Representative rate of 3.118 shekels per US dollar on 30 October 2026; the World Bank 2025 average was 3.45."}},"instruments":{"savings_account":{"available":true,"localName":"פיקדון לזמן קצר","localNameEn":"Short-term deposit","note":"Current accounts usually pay no interest; savers use short or on-call deposits."},"fdr_3m":{"available":true,"localName":"פיקדון לזמן קצוב (3 חודשים)","localNameEn":"Fixed-term deposit (3 months)","note":"Shekel deposits can be unlinked or CPI-linked; interest on unlinked deposits is taxed at 15%."},"fdr_1y":{"available":true,"localName":"פיקדון לזמן קצוב (שנה)","localNameEn":"Fixed-term deposit (1 year)"},"dps":{"available":true,"localName":"תוכנית חיסכון","localNameEn":"Savings plan (monthly deposits)","note":"Banks offer savings plans with monthly deposits; no industry-wide rate was found."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate for individuals; retail savers buy tradable government bonds on the stock exchange."},"tbill_91d":{"available":true,"localName":"מק\"ם (מלווה קצר מועד)","localNameEn":"Makam (short-term Bank of Israel bills)","note":"Issued by the Bank of Israel and traded on the stock exchange, open to retail investors.","sourceUrl":"https://edge.boi.gov.il/FusionEdgeServer/sdmx/v2/data/dataflow/BOI.STATISTICS/SECDWH/1.0/DWH_SRC_0342?lastNObservations=1&format=csv"},"tbond_5y":{"available":true,"localName":"אגרות חוב ממשלתיות (שחר / גליל)","localNameEn":"Government bonds (unlinked Shahar / CPI-linked Galil)","note":"Traded on the stock exchange.","sourceUrl":"https://edge.boi.gov.il/FusionEdgeServer/sdmx/v2/data/dataflow/BOI.STATISTICS/ZCM/1.0/ZC_TSB_ZND_05Y_MA?lastNObservations=1&format=csv"},"tbond_10y":{"available":true,"localName":"אגרות חוב ממשלתיות (שחר / גליל)","localNameEn":"Government bonds (unlinked Shahar / CPI-linked Galil)","note":"Traded on the stock exchange.","sourceUrl":"https://edge.boi.gov.il/FusionEdgeServer/sdmx/v2/data/dataflow/BOI.STATISTICS/ZCM/1.0/ZC_TSB_ZND_10Y_MA?lastNObservations=1&format=csv"},"equity_fund":{"available":true,"localName":"קרנות נאמנות וקרנות סל","localNameEn":"Mutual funds and exchange-traded funds","note":"Index funds tracking Israeli and global share indices are widely available."},"gold":{"available":true,"localName":"זהב","localNameEn":"Gold","note":"Gold bars and coins can be bought freely."}},"institutions":{"centralBank":{"name":"Bank of Israel","url":"https://www.boi.org.il/en/"},"insuranceRegulator":{"name":"Capital Market, Insurance and Savings Authority (Ministry of Finance)","url":"https://mof.gov.il/hon/"},"insuranceComplaints":{"name":"Capital Market, Insurance and Savings Authority, public inquiries unit","url":"https://mof.gov.il/hon/"},"pensionScheme":{"name":"National Insurance Institute (Bituach Leumi), old-age insurance","url":"https://www.btl.gov.il/English%20Homepage/Benefits/Old%20Age%20Insurance/Pages/default.aspx"},"oldAgeAllowance":{"name":"National Insurance Institute (Bituach Leumi), old-age pension","url":"https://www.btl.gov.il/English%20Homepage/Benefits/Old%20Age%20Insurance/Pages/default.aspx"},"publicHealthCover":{"name":"National Health Insurance (health funds), Ministry of Health","url":"https://www.health.gov.il/"},"statistics":{"name":"Central Bureau of Statistics (CBS)","url":"https://www.cbs.gov.il/en/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IL', 1, 'bank_deposit_avg_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'World Bank FR.INR.DPST stops in 2022 (0.44%, before the 2022-2023 rate rises), so it is not used; the current Bank of Israel average deposit rate could not be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IL', 1, 'credit_card_rate_cap', 0.1825, NULL, 'sourced', 'Fair Credit Law (חוק אשראי הוגן), section 5 and First Schedule item 1: maximum credit cost = Bank of Israel rate + 15 points (text on Hebrew Wikisource); Bank of Israel rate 3.25%', 'https://he.wikisource.org/wiki/חוק_אשראי_הוגן', '2026-10-31', 'Legal cap on the actual cost of shekel credit for any lender, banks included: the Bank of Israel rate (3.25% on 31 October 2026) plus 15 percentage points = 18.25%; loans above about ILS 1 million are exempt. Typical card credit costs less than the cap.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IL', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No deposit insurance scheme for Israeli banks was found; an official source confirming its absence could not be read (Bank of Israel site refused access), so it is not marked absent.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IL', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Banks offer monthly-deposit savings plans, but no industry-wide rate was found; Bank of Israel deposit tables could not be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IL', 1, 'equity_return_base', 0.065, NULL, 'assumption', 'Bank of Israel Makam yield 3.04% (2.58% after 15% tax); Tel Aviv main share index record via Trading Economics', 'https://tradingeconomics.com/israel/stock-market', '2026-10-31', 'Base case: about 4 points above the after-tax Makam yield, in line with the cap; the Tel Aviv market has had a strong 10-year record.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IL', 1, 'equity_return_high', 0.09, NULL, 'assumption', 'Tel Aviv main share index record (Trading Economics); 10-year government yield 4.06%', 'https://tradingeconomics.com/israel/stock-market', '2026-10-31', 'High case: a fuller equity premium over the 4% long bond yield, as the main Tel Aviv index has delivered over the past decade.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IL', 1, 'equity_return_low', 0.035, NULL, 'assumption', 'Bank of Israel Makam 3-month yield 3.04%; 10-year nominal government yield 4.06% (September 2026)', 'https://edge.boi.gov.il/FusionEdgeServer/sdmx/v2/data/dataflow/BOI.STATISTICS/SECDWH/1.0/DWH_SRC_0342?lastNObservations=1&format=csv', '2026-10-31', 'Low case: equities return no more than a long government bond after tax, after a strong run (the main Tel Aviv index was up about 17% in the year to October 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IL', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Bank of Israel publishes deposit interest rates on its website, which refused access (bot check); no deposit-rate series could be located in its open data API.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IL', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Bank of Israel publishes deposit interest rates on its website, which refused access (bot check); no deposit-rate series could be located in its open data API.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IL', 1, 'fixed_income_return_base', 0.026, NULL, 'assumption', 'Bank of Israel Makam 3-month yield 3.04% (30 October 2026), less 15% tax', 'https://edge.boi.gov.il/FusionEdgeServer/sdmx/v2/data/dataflow/BOI.STATISTICS/SECDWH/1.0/DWH_SRC_0342?lastNObservations=1&format=csv', '2026-10-31', 'Base case: the 3-month Makam yield after the 15% tax on unlinked interest.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IL', 1, 'fixed_income_return_high', 0.034, NULL, 'assumption', 'Bank of Israel 10-year nominal government yield 4.06% (September 2026), less 15% tax', 'https://edge.boi.gov.il/FusionEdgeServer/sdmx/v2/data/dataflow/BOI.STATISTICS/ZCM/1.0/ZC_TSB_ZND_10Y_MA?lastNObservations=1&format=csv', '2026-10-31', 'High case: locking in long government bond yields, about 3.4% after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IL', 1, 'fixed_income_return_low', 0.015, NULL, 'assumption', 'Bank of Israel Makam yield 3.04%; 15% tax on unlinked interest (PwC)', 'https://edge.boi.gov.il/FusionEdgeServer/sdmx/v2/data/dataflow/BOI.STATISTICS/SECDWH/1.0/DWH_SRC_0342?lastNObservations=1&format=csv', '2026-10-31', 'Low case: short rates fall toward 2% as inflation stays low, giving about 1.5% after the 15% tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IL', 1, 'goal_inflation_education', 0.03, NULL, 'assumption', 'Bank of Israel statistics API, CPI education component up 0.95% and education services up 2.4% in the year to September 2026', 'https://edge.boi.gov.il/FusionEdgeServer/sdmx/v2/data/dataflow/BOI.STATISTICS/PRI/1.0/CP060000_PCHYTY?lastNObservations=1&format=csv', '2026-10-31', 'Education services prices rise a little faster than the CPI, so 1 point above the 2% inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IL', 1, 'goal_inflation_health', 0.03, NULL, 'assumption', 'Bank of Israel statistics API, CPI health component up 1.25% and medical services up 2.48% in the year to September 2026', 'https://edge.boi.gov.il/FusionEdgeServer/sdmx/v2/data/dataflow/BOI.STATISTICS/PRI/1.0/CP070000_PCHYTY?lastNObservations=1&format=csv', '2026-10-31', 'Health prices are rising about as fast as the CPI and medical services a little faster, so 1 point above the 2% inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IL', 1, 'gold_return_base', 0.04, NULL, 'assumption', 'Bank of Israel exchange rate 3.118 ILS per USD; inflation close to US inflation', 'https://edge.boi.gov.il/FusionEdgeServer/sdmx/v2/data/dataflow/BOI.STATISTICS/EXR/1.0/RER_USD_ILS?lastNObservations=1&format=csv', '2026-10-31', 'Base case: the long-run dollar gold trend of about 4% a year with no expected shekel depreciation, since Israeli inflation is close to US inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IL', 1, 'gold_return_high', 0.08, NULL, 'assumption', 'Bank of Israel exchange rate 3.118 ILS per USD', 'https://edge.boi.gov.il/FusionEdgeServer/sdmx/v2/data/dataflow/BOI.STATISTICS/EXR/1.0/RER_USD_ILS?lastNObservations=1&format=csv', '2026-10-31', 'High case: strong dollar gold years or a weaker shekel.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IL', 1, 'gold_return_low', 0, NULL, 'assumption', 'Bank of Israel exchange rate 3.118 ILS per USD (30 October 2026)', 'https://edge.boi.gov.il/FusionEdgeServer/sdmx/v2/data/dataflow/BOI.STATISTICS/EXR/1.0/RER_USD_ILS?lastNObservations=1&format=csv', '2026-10-31', 'Low case: flat dollar gold and a stable or stronger shekel.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IL', 1, 'gratuity_rule', NULL, '{"daysPerYear":30,"daysPerYearAfter":null,"afterYears":null,"daysPerMonth":30}', 'sourced', 'Severance Pay Law 1963 (חוק פיצויי פיטורים), section 12 (text on Hebrew Wikisource)', 'https://he.wikisource.org/wiki/חוק_פיצויי_פיטורים', '2026-10-31', 'One month''s salary for each year of work for monthly-paid employees (two weeks'' wages for wage earners), paid on dismissal; in practice employers deposit 8.33% (or 6%) of pay into the employee''s pension fund for severance.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IL', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'Hospital care is covered by National Health Insurance through the health funds; no published typical out-of-pocket cost of a major private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IL', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Supplementary and private health insurance is sold, but no public table of premiums by age per ILS 100,000 of cover was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IL', 1, 'inflation_cpi', 0.0164, NULL, 'sourced', 'Bank of Israel statistics API, CPI general index, change over 12 months (Central Bureau of Statistics data)', 'https://edge.boi.gov.il/FusionEdgeServer/sdmx/v2/data/dataflow/BOI.STATISTICS/PRI/1.0/CP_PCHYTY?lastNObservations=1&format=csv', '2026-09-30', 'Consumer prices rose 1.64% in the year to September 2026 (1.5% in August); CBS data served by the Bank of Israel series database. Trading Economics also reports 1.6%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IL', 1, 'inflation_projection', 0.02, NULL, 'assumption', 'Bank of Israel inflation target 1-3% (midpoint 2%); market 5-10 year forward inflation expectation 1.93% (September 2026)', 'https://edge.boi.gov.il/FusionEdgeServer/sdmx/v2/data/dataflow/BOI.STATISTICS/ZCM/1.0/EXP_EXB_FRW_ZD_05Y_10Y_MA?lastNObservations=1&format=csv', '2026-10-31', 'Inflation is inside the Bank of Israel''s 1-3% target band and bond markets expect about 1.9% a year for years 5-10, so the 2% midpoint is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IL', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life (risk) insurance is widely sold, but no regulator or other public table of premiums per ILS 1,000 of cover by age could be read; gov.il refused access.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IL', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Capital Market, Insurance and Savings Authority publishes service indices for insurers, but its site (gov.il) refused access, so no industry-wide life claim settlement ratio could be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IL', 1, 'life_expectancy', 82.9, NULL, 'sourced', 'UN World Population Prospects 2024 (medium variant) via populationpyramid.net, life expectancy at birth, Israel, 2026', 'https://www.populationpyramid.net/mortality/israel/', '2026-07-01', '82.9 years in 2026 (men 80.8, women 84.9), UN WPP 2024 medium variant via a secondary site; the World Bank gives 83.2 for 2024.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IL', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":25.1,"men":23.6,"women":26.6},{"age":65,"total":20.9,"men":19.6,"women":22.2},{"age":70,"total":16.8,"men":15.7,"women":17.9},{"age":80,"total":9.8,"men":9.2,"women":10.3}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/israel/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IL', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":67,"womenAge":65,"over90Monthly":null,"meansTested":false}', 'sourced', 'National Insurance Law, section 245 (entitlement), and Retirement Age Law 2004 (text on Hebrew Wikisource)', 'https://he.wikisource.org/wiki/חוק_הביטוח_הלאומי', '2026-10-31', 'Paid from the retirement age (67 for men, 65 for women born from 1970) subject to an earnings test until 70 for men (women until their entitlement age): work income above the threshold reduces the pension by 60% of the excess. There is no means test from 70.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IL', 1, 'old_age_allowance_monthly', 1838, NULL, 'sourced', 'National Insurance Law (חוק הביטוח הלאומי), section 244 (pension 17.7% of the basic amount) and section 1 (basic amount ILS 10,382 in 2026), text on Hebrew Wikisource', 'https://he.wikisource.org/wiki/חוק_הביטוח_הלאומי', '2026-01-01', '17.7% of the 2026 basic amount for benefits in paragraph (3) of section 1, ILS 10,382 = about ILS 1,838 a month for a single person, before the 2% a year seniority increment (up to 50%) and dependant supplements; it rises to 18.7% from age 80 (section 247A). It is the flat National Insurance old-age pension that nearly every resident receives after a qualifying period (residence-based contributions), not a means-tested allowance; its rules are also in public_pension_scheme.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IL', 1, 'oop_health_share', 0.2049, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), Israel', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=IL', '2023-12-31', '20.5% in 2023 (WHO Global Health Expenditure Database via the World Bank); older than 2025, the latest available.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IL', 1, 'policy_rate', 0.0325, NULL, 'sourced', 'Bank of Israel statistics API, Bank of Israel interest rate (series MNT_RIB_BOI_D)', 'https://edge.boi.gov.il/FusionEdgeServer/sdmx/v2/data/dataflow/BOI.STATISTICS/BR/1.0/MNT_RIB_BOI_D?lastNObservations=1&format=csv', '2026-10-31', 'The Bank of Israel kept its rate at 3.25% at the 21 October 2026 decision (Trading Economics also reports this).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IL', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":18,"entryAgeMax":null,"pensionFromAge":67,"nomineeUntilAge":null,"inflationLinked":true,"taxFree":null}', 'sourced', 'National Insurance Law (חוק הביטוח הלאומי), sections 1, 240, 244-246 (text on Hebrew Wikisource)', 'https://he.wikisource.org/wiki/חוק_הביטוח_הלאומי', '2026-10-31', 'National Insurance old-age pension: residents aged 18+ are insured; paid from 67 for men (65 for women born from 1970) after a qualifying period (generally 60 months in the last 10 years or 144 months in all); the basic amount is updated each January by the CPI. The amount is in old_age_allowance_monthly. Employees also have a mandatory occupational pension (pension funds), not included here.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IL', 1, 'retirement_accumulation_return_base', 0.05, NULL, 'assumption', 'Bank of Israel government yields; equity base 6.5%; gold base 4%', 'https://edge.boi.gov.il/FusionEdgeServer/sdmx/v2/data/dataflow/BOI.STATISTICS/ZCM/1.0/ZC_TSB_ZND_10Y_MA?lastNObservations=1&format=csv', '2026-10-31', 'Base case: a balanced mix of bonds, Israeli and global equities and some gold.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IL', 1, 'retirement_accumulation_return_high', 0.07, NULL, 'assumption', 'Bank of Israel government yields; equity high 9%', 'https://edge.boi.gov.il/FusionEdgeServer/sdmx/v2/data/dataflow/BOI.STATISTICS/ZCM/1.0/ZC_TSB_ZND_10Y_MA?lastNObservations=1&format=csv', '2026-10-31', 'High case: a growth-leaning mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IL', 1, 'retirement_accumulation_return_low', 0.03, NULL, 'assumption', 'Bank of Israel Makam and government bond yields (October 2026)', 'https://edge.boi.gov.il/FusionEdgeServer/sdmx/v2/data/dataflow/BOI.STATISTICS/SECDWH/1.0/DWH_SRC_0342?lastNObservations=1&format=csv', '2026-10-31', 'Low case: a balanced mix earning little more than government bonds after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IL', 1, 'retirement_age_default', 67, NULL, 'sourced', 'Retirement Age Law 2004 (חוק גיל פרישה), sections 3 and 6 (text on Hebrew Wikisource)', 'https://he.wikisource.org/wiki/חוק_גיל_פרישה', '2026-10-31', 'Retirement age is 67 for men and 65 for women born in 1970 or later (section 3; the transition schedule in section 6 ends with women born in December 1969), so 67 for men and 65 for women born after 1975. Early retirement age for occupational pensions is 60.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IL', 1, 'retirement_age_government', 67, NULL, 'sourced', 'Retirement Age Law 2004 (חוק גיל פרישה), section 4: mandatory retirement age (text on Hebrew Wikisource)', 'https://he.wikisource.org/wiki/חוק_גיל_פרישה', '2026-10-31', 'The law sets 67 as the age at which any employee, men and women, may be required to retire; it applies to civil servants as well.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IL', 1, 'retirement_return_base', 0.025, NULL, 'assumption', 'Bank of Israel Makam 3-month yield 3.04% (2.58% after 15% tax)', 'https://edge.boi.gov.il/FusionEdgeServer/sdmx/v2/data/dataflow/BOI.STATISTICS/SECDWH/1.0/DWH_SRC_0342?lastNObservations=1&format=csv', '2026-10-31', 'Base case: just below the after-tax 3-month Makam yield, so it does not exceed the after-tax safe rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IL', 1, 'retirement_return_high', 0.034, NULL, 'assumption', 'Bank of Israel 10-year nominal government yield 4.06%, less 15% tax', 'https://edge.boi.gov.il/FusionEdgeServer/sdmx/v2/data/dataflow/BOI.STATISTICS/ZCM/1.0/ZC_TSB_ZND_10Y_MA?lastNObservations=1&format=csv', '2026-10-31', 'High case: part of the money locked into long government bonds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IL', 1, 'retirement_return_low', 0.015, NULL, 'assumption', 'Bank of Israel Makam yield 3.04%; 15% tax on unlinked interest (PwC)', 'https://edge.boi.gov.il/FusionEdgeServer/sdmx/v2/data/dataflow/BOI.STATISTICS/SECDWH/1.0/DWH_SRC_0342?lastNObservations=1&format=csv', '2026-10-31', 'Low case: short rates fall toward 2%, about 1.5% after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IL', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Israel has no government savings certificate or retail savings bond for individuals; savers buy tradable government bonds and Makam bills on the stock exchange.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IL', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Israeli current accounts pay essentially no interest and money is saved in short deposits; no published average rate for a savings account was found. The Bank of Israel website (deposit rate tables) refused access and its open data API has no deposit-rate series that could be located.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IL', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":4.74},{"year":2040,"value":4.26},{"year":2065,"value":3.68}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/israel/2040/', '2025-12-31', '100 / old-age dependency ratio: 21.1 (2025, World Bank), 23.5 (2040) and 27.2 (2065, populationpyramid.net/israel/2065/); high fertility keeps Israel younger than other high-income countries.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IL', 1, 'tax_bank_interest', 0.15, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Israel, income determination (interest income)', 'https://taxsummaries.pwc.com/israel/individual/income-determination', '2026-10-31', '15% on interest that is not linked to the CPI (ordinary shekel deposits, per PwC ''may be eligible for a 15% rate''); the general rate on interest is 25%, which applies to CPI-linked interest. High earners pay a 3% surtax on income above ILS 721,560 (2026) plus a further 2% on capital income above that level.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IL', 1, 'tax_sanchayapatra_profit', 0.15, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Israel, income determination (interest income)', 'https://taxsummaries.pwc.com/israel/individual/income-determination', '2026-10-31', 'No retail savings certificate exists; interest on unlinked government bonds and Makam is taxed at 15% (CPI-linked bonds 25%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IL', 1, 'tbill_91d_rate', 0.0304, NULL, 'sourced', 'Bank of Israel statistics API, yield to maturity of Makam (short-term Bank of Israel bills) with 3 months to maturity (series DWH_SRC_0342)', 'https://edge.boi.gov.il/FusionEdgeServer/sdmx/v2/data/dataflow/BOI.STATISTICS/SECDWH/1.0/DWH_SRC_0342?lastNObservations=1&format=csv', '2026-10-30', 'Makam with three months to maturity yielded 3.04% on 30 October 2026; Israel''s 3-month bills are Makam issued by the Bank of Israel.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IL', 1, 'tbond_10y_rate', 0.0406, NULL, 'sourced', 'Bank of Israel statistics API, nominal (unlinked) government zero-coupon yield, 10 years, monthly average (series ZC_TSB_ZND_10Y_MA)', 'https://edge.boi.gov.il/FusionEdgeServer/sdmx/v2/data/dataflow/BOI.STATISTICS/ZCM/1.0/ZC_TSB_ZND_10Y_MA?lastNObservations=1&format=csv', '2026-09-30', 'Average nominal 10-year zero-coupon yield in September 2026; Trading Economics shows the 10-year benchmark at 4.16% on 30 October 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IL', 1, 'tbond_5y_rate', 0.0372, NULL, 'sourced', 'Bank of Israel statistics API, nominal (unlinked) government zero-coupon yield, 5 years, monthly average (series ZC_TSB_ZND_05Y_MA)', 'https://edge.boi.gov.il/FusionEdgeServer/sdmx/v2/data/dataflow/BOI.STATISTICS/ZCM/1.0/ZC_TSB_ZND_05Y_MA?lastNObservations=1&format=csv', '2026-09-30', 'Average nominal 5-year zero-coupon government yield in September 2026.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('IN', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"IN","iso3":"IND","nameEn":"India","nameNative":"भारत","region":"south_asia","languages":["hi","en","bn","te","mr"],"currency":{"code":"INR","symbol":"₹","decimals":2,"compact":"lakh_crore","usdRate":{"value":94.94,"status":"sourced","sourceName":"RBI Weekly Statistical Supplement, Ratios and Rates: INR-US$ spot rate (FBIL reference rate)","sourceUrl":"https://www.rbi.org.in/Scripts/WSSView.aspx?Id=28807","asOf":"2026-10-23","note":"Week ended 23 October 2026 (87.71 a year earlier). 2025 average 87.16 (World Bank PA.NUS.FCRF)."}},"instruments":{"savings_account":{"available":true,"localName":"बचत खाता","localNameEn":"Savings account","sourceUrl":"https://www.rbi.org.in/Scripts/WSSView.aspx?Id=28807"},"fdr_3m":{"available":true,"localName":"सावधि जमा","localNameEn":"Fixed deposit (FD)","note":"Banks offer terms from 7 days; Post Office time deposits start at 1 year.","sourceUrl":null},"fdr_1y":{"available":true,"localName":"सावधि जमा","localNameEn":"Fixed deposit (FD)","note":"Post Office Time Deposit (1-5 years) is the government equivalent.","sourceUrl":"https://www.businesstoday.in/personal-finance/story/small-savings-scheme-interest-rates-unchanged-for-q3-fy27-check-ppf-scss-ssy-rates-558892-2026-09-30"},"dps":{"available":true,"localName":"आवर्ती जमा","localNameEn":"Recurring deposit (RD)","note":"Banks and the Post Office (5-year RD, 6.7%).","sourceUrl":"https://www.businesstoday.in/personal-finance/story/small-savings-scheme-interest-rates-unchanged-for-q3-fy27-check-ppf-scss-ssy-rates-558892-2026-09-30"},"sanchayapatra_5y":{"available":true,"localName":"राष्ट्रीय बचत पत्र","localNameEn":"National Savings Certificate (NSC)","note":"5-year government certificate sold at post offices; also Kisan Vikas Patra, PPF and the Senior Citizens'' Savings Scheme.","sourceUrl":"https://www.businesstoday.in/personal-finance/story/small-savings-scheme-interest-rates-unchanged-for-q3-fy27-check-ppf-scss-ssy-rates-558892-2026-09-30"},"tbill_91d":{"available":true,"localName":"ट्रेज़री बिल","localNameEn":"Treasury bill","note":"Individuals can bid through the RBI Retail Direct portal.","sourceUrl":"https://rbiretaildirect.org.in/"},"tbond_5y":{"available":true,"localName":"सरकारी प्रतिभूति","localNameEn":"Government security (G-Sec)","note":"Through RBI Retail Direct or a broker.","sourceUrl":"https://rbiretaildirect.org.in/"},"tbond_10y":{"available":true,"localName":"सरकारी प्रतिभूति","localNameEn":"Government security (G-Sec)","note":"Through RBI Retail Direct or a broker.","sourceUrl":"https://rbiretaildirect.org.in/"},"equity_fund":{"available":true,"localName":"म्यूचुअल फंड","localNameEn":"Mutual fund / index fund","note":"SEBI-regulated; Nifty 50 index funds are widely available.","sourceUrl":"https://www.sebi.gov.in/"},"gold":{"available":true,"localName":"सोना","localNameEn":"Gold (coins and bars)","note":"Physical gold is legal and widely bought; BIS hallmarking applies. New Sovereign Gold Bond issues have stopped."}},"institutions":{"centralBank":{"name":"Reserve Bank of India","url":"https://www.rbi.org.in/"},"insuranceRegulator":{"name":"Insurance Regulatory and Development Authority of India (IRDAI)","url":"https://irdai.gov.in/"},"insuranceComplaints":{"name":"Council for Insurance Ombudsmen","url":"https://www.cioins.co.in/","note":"Complain to the insurer first; IRDAI''s Bima Bharosa portal also takes complaints."},"pensionScheme":{"name":"Atal Pension Yojana (PFRDA)","url":"https://www.pfrda.org.in/","note":"Formal-sector workers are covered by EPFO (https://www.epfindia.gov.in/); NPS is open to all."},"oldAgeAllowance":{"name":"National Social Assistance Programme (IGNOAPS)","url":"https://nsap.nic.in/"},"publicHealthCover":{"name":"Ayushman Bharat PM-JAY","url":"https://pmjay.gov.in/","note":"Rs 5 lakh a year per family for eligible poorer households and for everyone aged 70+."},"depositInsurance":{"name":"Deposit Insurance and Credit Guarantee Corporation (DICGC)","url":"https://www.dicgc.org.in/"},"statistics":{"name":"Ministry of Statistics and Programme Implementation (MoSPI)","url":"https://www.mospi.gov.in/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IN', 1, 'bank_deposit_avg_rate', 0.0655, NULL, 'sourced', 'RBI, Lending and Deposit Rates of Scheduled Commercial Banks, October 2026: weighted average domestic term deposit rate on outstanding deposits', 'https://rbi.org.in/scripts/BS_PressReleaseDisplay.aspx?prid=63894', '2026-09-30', 'September 2026 (August 6.56%). Fresh term deposits averaged 5.61%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IN', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap: the Supreme Court set aside a 30% consumer-forum cap in 2024 and the RBI leaves card rates to issuers. The typical rate (about 3-3.75% a month) was found only on issuer and card-comparison company pages, which we do not cite.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IN', 1, 'deposit_insurance_limit', 500000, NULL, 'sourced', 'Wikipedia, Deposit Insurance and Credit Guarantee Corporation (cites DICGC)', 'https://en.wikipedia.org/wiki/Deposit_Insurance_and_Credit_Guarantee_Corporation', '2026-09-30', 'Rs 5 lakh per depositor per bank, principal and interest together, in force since 4 February 2020 (older than 2025, but no change found; article edited September 2026). dicgc.org.in refused connections, so a secondary source is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IN', 1, 'dps_rate', 0.067, NULL, 'sourced', 'Ministry of Finance small savings rates for Oct-Dec 2026: Post Office 5-year recurring deposit, via Business Today', 'https://www.businesstoday.in/personal-finance/story/small-savings-scheme-interest-rates-unchanged-for-q3-fy27-check-ppf-scss-ssy-rates-558892-2026-09-30', '2026-10-01', 'Government-set rate for the 5-year Post Office recurring deposit; bank recurring deposits earn the bank''s term-deposit rate for the tenure.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IN', 1, 'equity_return_base', 0.1, NULL, 'assumption', 'Nifty 50 TRI CAGR (index data, Aug 2026): 1-year -0.35%, 3-year 8.99%, 5-year 8.3%, 10-year 12.0%; RBI 10-year G-sec 7.52%; NSC 7.7%', 'https://www.rbi.org.in/Scripts/WSSView.aspx?Id=28807', '2026-10-31', 'The index earned about 12% a year over 10 years but only 8.3% over 5, so we cap the base at the after-tax safe rate (about 6.8-6.9%) plus about 3 points.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IN', 1, 'equity_return_high', 0.13, NULL, 'assumption', 'Nifty 50 TRI CAGR (index data, Aug 2026): 1-year -0.35%, 3-year 8.99%, 5-year 8.3%, 10-year 12.0%; RBI 10-year G-sec 7.52%', 'https://www.rbi.org.in/Scripts/WSSView.aspx?Id=28807', '2026-10-31', 'A repeat of the 10-year index record plus a little.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IN', 1, 'equity_return_low', 0.06, NULL, 'assumption', 'Nifty 50 TRI CAGR (index data, Aug 2026): 1-year -0.35%, 3-year 8.99%, 5-year 8.3%, 10-year 12.0%; RBI 10-year G-sec 7.52%', 'https://www.rbi.org.in/Scripts/WSSView.aspx?Id=28807', '2026-10-31', 'Recent years were weak (5-year index return about 8.3%), so the low case is about the after-tax safe rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IN', 1, 'fdr_1y_rate', 0.0638, NULL, 'sourced', 'RBI Weekly Statistical Supplement, Ratios and Rates: term deposit rate over 1 year at major banks (6.00%-6.75%)', 'https://www.rbi.org.in/Scripts/WSSView.aspx?Id=28807', '2026-10-23', 'Midpoint of the RBI''s 6.00%-6.75% range for major banks'' term deposits of more than 1 year. The Post Office 1-year time deposit pays 6.9% (Oct-Dec 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IN', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'RBI and the Ministry of Finance publish no 3-month deposit rate (Post Office time deposits start at 1 year); the only 3-month figures found were individual banks'' card rates and broker pages, which we do not cite.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IN', 1, 'fixed_income_return_base', 0.06, NULL, 'assumption', 'Post Office 1-year TD 6.9%, NSC 7.7%, 364-day T-bill 6.69%, less tax', 'https://www.businesstoday.in/personal-finance/story/small-savings-scheme-interest-rates-unchanged-for-q3-fy27-check-ppf-scss-ssy-rates-558892-2026-09-30', '2026-10-31', 'A mix of bank deposits, government bills and small savings after tax at about 10%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IN', 1, 'fixed_income_return_high', 0.07, NULL, 'assumption', 'Senior Citizens'' Savings Scheme 8.2%, NSC 7.7%, less tax', 'https://www.businesstoday.in/personal-finance/story/small-savings-scheme-interest-rates-unchanged-for-q3-fy27-check-ppf-scss-ssy-rates-558892-2026-09-30', '2026-10-31', 'Best government savings schemes after tax at about 10%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IN', 1, 'fixed_income_return_low', 0.05, NULL, 'assumption', 'RBI: major banks'' term deposits over 1 year 6.00%-6.75%, less 10% tax', 'https://www.rbi.org.in/Scripts/WSSView.aspx?Id=28807', '2026-10-31', 'Bank deposits after 10% tax give about 5.4-6.1%; lower for people taxed at higher slabs.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IN', 1, 'goal_inflation_education', 0.07, NULL, 'assumption', 'MoSPI CPI education services 3.94% (Sep 2026)', 'https://ddindia.co.in/2026/10/retail-inflation-rises-to-5-54-in-september/', '2026-10-31', 'Private school and college fees rise faster than the education CPI, so we plan with 2 points above general inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IN', 1, 'goal_inflation_health', 0.08, NULL, 'assumption', 'MoSPI CPI health 1.40% (Sep 2026, new base); headline CPI plan 5%', 'https://ddindia.co.in/2026/10/retail-inflation-rises-to-5-54-in-september/', '2026-10-31', 'The new-series health CPI is unusually low; hospital and insurance costs have long risen faster than headline prices, so we plan with 3 points above general inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IN', 1, 'gold_return_base', 0.08, NULL, 'assumption', 'Dollar gold long-run trend about 4-5% plus rupee depreciation about 3% a year (World Bank PA.NUS.FCRF)', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=IN', '2026-10-31', 'Rupee gold rose far faster over 2016-2026 in an exceptional rally; long-run we expect dollar gold plus rupee depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IN', 1, 'gold_return_high', 0.12, NULL, 'assumption', 'INR per USD 87.71 (Oct 2025) to 94.94 (Oct 2026), RBI WSS; World Bank PA.NUS.FCRF', 'https://www.rbi.org.in/Scripts/WSSView.aspx?Id=28807', '2026-10-31', 'A strong gold decade plus faster rupee depreciation (the rupee fell about 8% against the dollar in the year to October 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IN', 1, 'gold_return_low', 0.03, NULL, 'assumption', 'INR per USD 87.71 (Oct 2025) to 94.94 (Oct 2026), RBI WSS; World Bank PA.NUS.FCRF', 'https://www.rbi.org.in/Scripts/WSSView.aspx?Id=28807', '2026-10-31', 'Gold can lose value in rupees for years after a strong run like 2016-2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IN', 1, 'gratuity_rule', NULL, '{"daysPerYear":15,"daysPerYearAfter":null,"afterYears":null,"daysPerMonth":26}', 'sourced', 'Payment of Gratuity Act 1972 rule, carried into the Code on Social Security 2020 (in force 21 November 2025), via Wikipedia', 'https://en.wikipedia.org/wiki/Payment_of_Gratuity_Act,_1972', '2025-11-21', '15 days'' wages per completed year of service (monthly wage / 26 x 15), after 5 years'' continuous service (waived on death or disablement; fixed-term employees qualify pro rata under the Code); capped at a ceiling notified by the government.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IN', 1, 'health_hospitalisation_cost', 50508, NULL, 'sourced', 'NSS 80th round (2025) health survey, average out-of-pocket spend per hospitalisation in private hospitals, via Counterview', 'https://www.counterview.in/2026/04/high-privatisation-in-gujarats.html', '2025-12-31', 'NSS 80th round (January-December 2025): average out-of-pocket spend per hospitalisation Rs 50,508 in private facilities and Rs 6,631 in public ones. A surgical stay in a private hospital usually costs more.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IN', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Indicative premiums for Rs 10 lakh cover were found only on insurer and insurance-intermediary pages, which we do not cite; no regulator or independent premium guide by age was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IN', 1, 'inflation_cpi', 0.0554, NULL, 'sourced', 'MoSPI All-India CPI (base 2024), provisional, via DD News', 'https://ddindia.co.in/2026/10/retail-inflation-rises-to-5-54-in-september/', '2026-09-30', 'September 2026 year-on-year, provisional (August final 4.83%). MoSPI PDF could not be opened (certificate error), so read via the public broadcaster''s report.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IN', 1, 'inflation_projection', 0.05, NULL, 'assumption', 'RBI target 4% (2-6% band); MPC projection for 2026-27 5.2% (October 2026); 5-year CPI average about 5%', 'https://www.rbi.org.in/scripts/BS_PressReleaseDisplay.aspx?prid=63742', '2026-10-31', 'CPI averaged about 5% over 2021-2025 and the RBI projects 5.2% for FY27, so we plan with 5% rather than the 4% target.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IN', 1, 'insurance_term_premium_table', NULL, '{"per":1000,"smokerMultiplier":1.7,"bands":[{"maxAge":30,"low":0.63,"high":0.78},{"maxAge":40,"low":1.04,"high":1.5},{"maxAge":50,"low":2.24,"high":3.28},{"maxAge":65,"low":4.83,"high":7.13}]}', 'sourced', 'StockCalc.in term-insurance premium estimates for Rs 1 crore cover, FY 2026-27 (independent calculator; sells no insurance)', 'https://stockcalc.in/calculator/term-insurance/1-crore-coverage', '2026-10-31', 'Rs 1 crore cover, 30-year term, non-smoker, yearly: Rs 6,325 (18-25), 7,820 (26-30), 10,350 (31-35), 14,950 (36-40), 22,425 (41-45), 32,775 (46-50), 48,300 (51-55), 71,300 (56-60); per 1,000 of cover divide by 10,000. Smokers pay about 1.7x. No quote is given above 60, so the 65 band''s upper end is the 56-60 quote and real premiums at 61-65 are higher.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IN', 1, 'life_claim_settlement_rate', 0.9832, NULL, 'sourced', 'IRDAI Handbook on Indian Insurance Statistics 2024-25, individual death claims by number, via Insurance Business Asia', 'https://www.insurancebusinessmag.com/asia/news/life-insurance/what-indias-claims-settlement-ratio-doesnt-tell-brokers-586054.aspx', '2025-03-31', 'By amount 97.18%. IRDAI site not read directly.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IN', 1, 'life_expectancy', 72.235, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN (UN WPP)', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=IN', '2024-12-31', 'Men 70.7, women 73.9. India''s own SRS 2020-24 life table gives 70.6 (pulled down by the 2020-21 pandemic years). Latest published figure is for 2024 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IN', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":18.6,"men":17.5,"women":19.8},{"age":65,"total":15.3,"men":14.5,"women":16.3},{"age":70,"total":12.5,"men":11.8,"women":13.2},{"age":80,"total":8.1,"men":7.8,"women":8.4}]}', 'sourced', 'Registrar General of India, SRS Abridged Life Tables 2020-24 (published May 2026)', 'https://censusindia.gov.in/nada/index.php/catalog/47148', '2022-07-01', 'Expectation of life at the start of each age interval, India, 2020-24 (asOf is the mid-period date; published May 2026, the latest official table).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IN', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":60,"womenAge":60,"over90Monthly":null,"meansTested":true}', 'sourced', 'PIB backgrounder on NSAP (IGNOAPS)', 'https://static.pib.gov.in/WriteReadData/specificdocs/documents/2025/nov/doc2025117686801.pdf', '2025-11-17', 'Age 60+ in below-poverty-line families; central amount rises to Rs 500 at 80 (not 90).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IN', 1, 'old_age_allowance_monthly', 1100, NULL, 'sourced', 'PIB backgrounder on the National Social Assistance Programme (IGNOAPS)', 'https://static.pib.gov.in/WriteReadData/specificdocs/documents/2025/nov/doc2025117686801.pdf', '2025-11-17', 'What a pensioner receives is the central share (Rs 200 a month at 60-79, Rs 500 at 80+) plus a state top-up of Rs 50 to Rs 5,700; PIB puts the average pension at around Rs 1,100 in many states. Only for people in below-poverty-line families.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IN', 1, 'oop_health_share', 0.4389, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS (WHO GHED)', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=IN', '2023-12-31', 'Latest published figure is for 2023 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IN', 1, 'policy_rate', 0.055, NULL, 'sourced', 'Reserve Bank of India, Resolution of the Monetary Policy Committee, 5-7 October 2026', 'https://www.rbi.org.in/scripts/BS_PressReleaseDisplay.aspx?prid=63742', '2026-10-07', 'Raised 25 bp to 5.50% (SDF 5.25%, MSF 5.75%); still 5.50% in the RBI Weekly Statistical Supplement for the week ended 23 October 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IN', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":18,"entryAgeMax":40,"pensionFromAge":60,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":false,"projections":[{"monthlyContribution":42,"years":42,"monthlyPension":1000},{"monthlyContribution":210,"years":42,"monthlyPension":5000},{"monthlyContribution":1454,"years":20,"monthlyPension":5000}]}', 'sourced', 'Atal Pension Yojana (PFRDA) contribution chart, via Indian Pay Calculator', 'https://www.indianpaycalculator.in/govt-news/atal-pension-yojana-apy-guaranteed-5000-pension-2026', '2026-06-26', 'Guaranteed fixed pension Rs 1,000-5,000 a month from 60, then to the spouse for life; the corpus (Rs 1.7-8.5 lakh) goes to the nominee after both die. Not open to income-tax payers since Oct 2022. Contributions deductible under the old regime; pension is taxable. Formal-sector workers are in EPF/EPS instead.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IN', 1, 'retirement_accumulation_return_base', 0.08, NULL, 'assumption', 'Mix of equity base 10% and fixed income base 6%', 'https://www.rbi.org.in/Scripts/WSSView.aspx?Id=28807', '2026-10-31', 'Roughly half equity and half safe fixed income over a working life.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IN', 1, 'retirement_accumulation_return_high', 0.1, NULL, 'assumption', 'Equity high 13%, fixed income high 7%', 'https://www.rbi.org.in/Scripts/WSSView.aspx?Id=28807', '2026-10-31', 'A growth-tilted mix in a good decade.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IN', 1, 'retirement_accumulation_return_low', 0.06, NULL, 'assumption', 'After-tax safe rate about 6%; Nifty 50 TRI 5-year CAGR 8.3% (Aug 2026)', 'https://www.rbi.org.in/Scripts/WSSView.aspx?Id=28807', '2026-10-31', 'A balanced mix earning little more than safe deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IN', 1, 'retirement_age_default', 58, NULL, 'sourced', 'Employees'' Pension Scheme 1995 (EPFO): pension age 58, via Wikipedia (Employees'' Provident Fund Organisation)', 'https://en.wikipedia.org/wiki/Employees%27_Provident_Fund_Organisation', '2026-10-31', 'Same for men and women and for anyone born after 1975; needs 10 years of service, reduced pension possible from 50. epfo.gov.in returned 403, so a secondary source is used. Many private employers retire staff at 58-60.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IN', 1, 'retirement_age_government', 60, NULL, 'sourced', 'Central government FR 56(a); Lok Sabha reply, via Gconnect', 'https://www.gconnect.in/orders-in-brief/retirement-benefits/centre-clarification-retirement-age.html', '2019-11-27', 'Central government employees retire at 60 (Lok Sabha reply, November 2019; older than 2025, no change found); some states and cadres differ (e.g. some teachers and doctors 62-65).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IN', 1, 'retirement_return_base', 0.06, NULL, 'assumption', 'Post Office 1-year TD 6.9% and 364-day T-bill 6.69%, less 10% tax', 'https://www.businesstoday.in/personal-finance/story/small-savings-scheme-interest-rates-unchanged-for-q3-fy27-check-ppf-scss-ssy-rates-558892-2026-09-30', '2026-10-31', 'Equal to the after-tax 1-year government deposit and bill rate (6.9% and 6.69% less 10% tax: about 6.0-6.2%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IN', 1, 'retirement_return_high', 0.07, NULL, 'assumption', 'Senior Citizens'' Savings Scheme 8.2% less tax', 'https://www.businesstoday.in/personal-finance/story/small-savings-scheme-interest-rates-unchanged-for-q3-fy27-check-ppf-scss-ssy-rates-558892-2026-09-30', '2026-10-31', 'Retirees who fill the SCSS limit earn about 7.4% after 10% tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IN', 1, 'retirement_return_low', 0.05, NULL, 'assumption', 'RBI: major banks'' term deposits over 1 year 6.00%-6.75%, less tax', 'https://www.rbi.org.in/Scripts/WSSView.aspx?Id=28807', '2026-10-31', 'Plain bank deposits after 10% tax, or higher slab tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IN', 1, 'sanchayapatra_5y_rate', 0.077, NULL, 'sourced', 'Ministry of Finance small savings rates for Oct-Dec 2026 (National Savings Certificate), via Business Today', 'https://www.businesstoday.in/personal-finance/story/small-savings-scheme-interest-rates-unchanged-for-q3-fy27-check-ppf-scss-ssy-rates-558892-2026-09-30', '2026-10-01', 'NSC, 5 years, compounded annually, paid at maturity. Senior Citizens'' Savings Scheme pays 8.2%, PPF 7.1%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IN', 1, 'savings_account_rate', 0.025, NULL, 'sourced', 'RBI Weekly Statistical Supplement, Ratios and Rates: savings deposit rate', 'https://www.rbi.org.in/Scripts/WSSView.aspx?Id=28807', '2026-10-23', 'Rate at major banks. Post Office savings accounts pay 4%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IN', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":9.3},{"year":2040,"value":6.1},{"year":2065,"value":3}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025: 10.8) and UN WPP 2024 medium variant via PopulationPyramid.net (2040: 16.3, 2065: 33.4)', 'https://www.populationpyramid.net/india/2040/', '2025-12-31', 'Working-age people per person 65+ = 100 / old-age dependency ratio.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IN', 1, 'tax_bank_interest', 0.1, NULL, 'sourced', 'PwC Worldwide Tax Summaries, India: withholding taxes (interest paid to residents)', 'https://taxsummaries.pwc.com/india/corporate/withholding-taxes', '2026-04-01', '10% withheld when interest from one bank, co-operative or post office deposit exceeds Rs 50,000 a year (Rs 100,000 for senior citizens); page reviewed 11 May 2026. Interest is finally taxed at the individual''s slab rate (0-30%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IN', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No flat or withholding rate: NSC interest is added to income and taxed at the individual''s slab rate (0-30%), with no TDS; under the old regime yearly interest is deemed reinvested and counts for the 80C deduction.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IN', 1, 'tbill_91d_rate', 0.059337, NULL, 'sourced', 'Reserve Bank of India, 91-Day, 182-Day and 364-Day T-Bill Auction Result: Cut-off', 'https://rbi.org.in/scripts/BS_PressReleaseDisplay.aspx?prid=63876', '2026-10-28', 'Implicit yield at cut-off. 182-day 6.5493%, 364-day 6.69%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IN', 1, 'tbond_10y_rate', 0.0752, NULL, 'sourced', 'RBI Weekly Statistical Supplement, Ratios and Rates: 10-year G-Sec par yield (FBIL)', 'https://www.rbi.org.in/Scripts/WSSView.aspx?Id=28807', '2026-10-23', 'Week ended 23 October 2026 (6.49% a year earlier). The 6.94% GS 2036 auction on 16 October 2026 cut off at 7.3955%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IN', 1, 'tbond_5y_rate', 0.073589, NULL, 'sourced', 'Reserve Bank of India, Government Stock auction results: cut-off yield of 6.53% GS 2031', 'https://rbi.org.in/scripts/BS_PressReleaseDisplay.aspx?prid=63852', '2026-10-23', 'About 5 years to maturity; auction cut-off yield.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('IQ', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"IQ","iso3":"IRQ","nameEn":"Iraq","nameNative":"العراق","region":"middle_east_north_africa","languages":["ar","ckb","en","az"],"currency":{"code":"IQD","symbol":"IQD","decimals":0,"compact":"intl","usdRate":{"value":1510,"status":"sourced","sourceName":"Central Bank of Iraq official rate (homepage converter; daily US dollar rate files on the exchange-rates page)","sourceUrl":"https://cbi.iq/page/144","asOf":"2026-10-31","note":"1,510 dinars per US dollar shown by the Central Bank of Iraq''s currency converter (undated; read on 31 October and again on 3 November 2026); the exchange-rates page links to the daily rate files. Trading Economics shows the market rate at 1,515.3 on 3 November 2026, the dinar having weakened about 15.7% over the past month; the World Bank 2025 average was 1,300."}},"instruments":{"savings_account":{"available":true,"localName":"حساب التوفير","localNameEn":"Savings account"},"fdr_3m":{"available":true,"localName":"وديعة ثابتة (3 أشهر)","localNameEn":"Fixed deposit (3 months)"},"fdr_1y":{"available":true,"localName":"وديعة ثابتة (سنة)","localNameEn":"Fixed deposit (1 year)"},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No standard monthly recurring deposit product was confirmed."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No continuously sold government savings certificate for individuals was confirmed."},"tbill_91d":{"available":true,"localName":"حوالات الخزينة","localNameEn":"Treasury bills","note":"Auctioned mainly to banks; access for individuals is limited."},"tbond_5y":{"available":true,"localName":"سندات الخزينة","localNameEn":"Treasury bonds","note":"Mainly held by banks; occasional public issues have been sold to individuals."},"tbond_10y":{"available":false,"localName":null,"localNameEn":null,"note":"No 10-year government bond was found."},"equity_fund":{"available":false,"localName":null,"localNameEn":null,"note":"No diversified equity or index fund sold to retail investors was found; the Iraq Stock Exchange is supervised by the Iraq Securities Commission."},"gold":{"available":true,"localName":"الذهب","localNameEn":"Gold","note":"Gold is bought mostly as jewellery; investment bars and coins are also sold."}},"institutions":{"centralBank":{"name":"Central Bank of Iraq","url":"https://cbi.iq/"},"insuranceRegulator":{"name":"Insurance Diwan (Insurance Regulatory Authority), Ministry of Finance","url":"https://mof.gov.iq/"},"insuranceComplaints":null,"pensionScheme":{"name":"Social security for workers, Ministry of Labour and Social Affairs","url":"https://molsa.gov.iq/"},"oldAgeAllowance":{"name":"Social Protection Network, Ministry of Labour and Social Affairs","url":"https://molsa.gov.iq/"},"publicHealthCover":{"name":"Ministry of Health (public hospitals and clinics)","url":"https://moh.gov.iq/"},"depositInsurance":null,"statistics":{"name":"Central Statistical Organization","url":"https://cosit.gov.iq/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IQ', 1, 'bank_deposit_avg_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No recent average deposit rate was found; the World Bank series (FR.INR.DPST) stops at 4.78% in 2016, too old to use.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IQ', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap or typical credit card rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IQ', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'A deposit insurance arrangement under the Central Bank of Iraq is reported, but its cover per depositor could not be read from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IQ', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No monthly recurring deposit product or rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IQ', 1, 'equity_return_base', 0.06, NULL, 'assumption', 'Central Bank of Iraq policy rate 5.5%; assumed after-tax deposit rate about 4%', 'https://tradingeconomics.com/iraq/interest-rate', '2026-10-31', 'Base case: about 2 points over the after-tax safe rate, below the 4-point cap, because the Iraq Stock Exchange is small with no strong 10-year record.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IQ', 1, 'equity_return_high', 0.1, NULL, 'assumption', 'Central Bank of Iraq policy rate 5.5%; inflation assumption 3.5%', 'https://tradingeconomics.com/iraq/interest-rate', '2026-10-31', 'High case: equities beat inflation by about 6 points a year.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IQ', 1, 'equity_return_low', 0.02, NULL, 'assumption', 'Central Bank of Iraq policy rate 5.5%; small, illiquid Iraq Stock Exchange', 'https://tradingeconomics.com/iraq/interest-rate', '2026-10-31', 'Low case: the thinly traded local market returns little in dinars.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IQ', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No current industry-wide 1-year fixed deposit rate could be read from the Central Bank of Iraq; its interest-rate page (https://cbi.iq/page/143) lists bank rate tables only up to 2024, in spreadsheet files.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IQ', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No current industry-wide 3-month fixed deposit rate could be read from the Central Bank of Iraq; its interest-rate page (https://cbi.iq/page/143) lists bank rate tables only up to 2024, in spreadsheet files.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IQ', 1, 'fixed_income_return_base', 0.04, NULL, 'assumption', 'Central Bank of Iraq policy rate 5.5%', 'https://tradingeconomics.com/iraq/interest-rate', '2026-10-31', 'Base case: term deposits a little below the policy rate, after any tax; bank rates were not published.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IQ', 1, 'fixed_income_return_high', 0.055, NULL, 'assumption', 'Central Bank of Iraq policy rate 5.5%', 'https://tradingeconomics.com/iraq/interest-rate', '2026-10-31', 'High case: longer deposits and government bonds at about the policy rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IQ', 1, 'fixed_income_return_low', 0.025, NULL, 'assumption', 'Central Bank of Iraq policy rate 5.5%', 'https://tradingeconomics.com/iraq/interest-rate', '2026-10-31', 'Low case: ordinary savings rates well below the policy rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IQ', 1, 'goal_inflation_education', 0.05, NULL, 'assumption', 'Inflation assumption 3.5%', 'https://tradingeconomics.com/iraq/inflation-cpi', '2026-10-31', 'Public education is free but private school and university fees rise faster than general prices, so 1.5 points above the general assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IQ', 1, 'goal_inflation_health', 0.06, NULL, 'assumption', 'Inflation assumption 3.5%; out-of-pocket share 54% (World Bank)', 'https://tradingeconomics.com/iraq/inflation-cpi', '2026-10-31', 'Private clinics and imported medicines drive health costs, so health goals are planned 2.5 points above the general assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IQ', 1, 'gold_return_base', 0.06, NULL, 'assumption', 'Central Bank of Iraq exchange rate; long-run dollar gold trend about 4%', 'https://cbi.iq/page/144', '2026-10-31', 'Base case: about 4% dollar gold trend plus about 2% a year of dinar depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IQ', 1, 'gold_return_high', 0.12, NULL, 'assumption', 'Central Bank of Iraq exchange rate history (1,300 to 1,510 per dollar)', 'https://cbi.iq/page/144', '2026-10-31', 'High case: strong dollar gold and further devaluations like the 2026 one.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IQ', 1, 'gold_return_low', 0.02, NULL, 'assumption', 'Central Bank of Iraq official rate 1,510 dinars per US dollar (October 2026) against 1,300 in 2025 (World Bank)', 'https://cbi.iq/page/144', '2026-10-31', 'Low case: flat dollar gold with a stable dinar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IQ', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No statutory end-of-service gratuity for private employees could be confirmed from the Labour Law (No. 37 of 2015).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IQ', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a major private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IQ', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premiums by age were found from the regulator or another public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IQ', 1, 'inflation_cpi', 0.038, NULL, 'sourced', 'Central Statistical Organization Iraq, inflation September 2026, via Trading Economics', 'https://tradingeconomics.com/iraq/inflation-cpi', '2026-09-30', '3.8% in September 2026 (3.3% in August); core 3.9%. Secondary source; the statistics office site was not read. World Bank 2025 average 0.3%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IQ', 1, 'inflation_projection', 0.035, NULL, 'assumption', 'Central Statistical Organization inflation 3.8% (September 2026); World Bank 2025 0.3%', 'https://tradingeconomics.com/iraq/inflation-cpi', '2026-10-31', 'The Central Bank of Iraq publishes no numeric target; inflation has mostly run between 0% and 5% recently, and the dinar''s move from about 1,300 to 1,510 per dollar adds import-price pressure, so a rounded 3.5% is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IQ', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Life insurance penetration is very low and no published term-life premium rates per 1,000 dinars of cover by age were found from the regulator or another public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IQ', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No industry-wide life claim settlement ratio could be read from the Insurance Diwan.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IQ', 1, 'life_expectancy', 72.424, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN), Iraq', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=IQ', '2024-12-31', '72.4 years in 2024 (men 70.5, women 74.2), the latest World Bank year, older than 2025; UN WPP 2024 gives 72.6 for 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IQ', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":18.3,"men":17.1,"women":19.5},{"age":65,"total":14.7,"men":13.6,"women":15.6},{"age":70,"total":11.3,"men":10.5,"women":12},{"age":80,"total":6.1,"men":5.7,"women":6.5}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/iraq/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IQ', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'Eligibility rules for social protection support to older people could not be read from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IQ', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Social Protection Network of the Ministry of Labour and Social Affairs pays means-tested cash support to poor households including older people, but the current monthly amount for an elderly person could not be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IQ', 1, 'oop_health_share', 0.54, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), Iraq', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=IQ', '2023-12-31', '54.0% in 2023 (WHO Global Health Expenditure Database via the World Bank); older than 2025, the latest available.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IQ', 1, 'policy_rate', 0.055, NULL, 'sourced', 'Central Bank of Iraq policy rate, via Trading Economics', 'https://tradingeconomics.com/iraq/interest-rate', '2026-10-31', '5.50% at the October 2026 reading, unchanged from the previous one; secondary source because the central bank homepage shows no policy rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IQ', 1, 'public_pension_scheme', NULL, NULL, 'missing', '', '', '2026-10-31', 'Private-sector workers are covered by the social security fund under the Ministry of Labour and Social Affairs (employee 5%, employer 12% of net salaries per PwC Worldwide Tax Summaries, Iraq, reviewed 24 June 2026), but its pension age and indexation rules could not be read from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IQ', 1, 'retirement_accumulation_return_base', 0.05, NULL, 'assumption', 'Fixed income base 4%; equity base 6%; gold base 6%', 'https://tradingeconomics.com/iraq/interest-rate', '2026-10-31', 'Base case: a balanced mix of deposits, gold and some equity in a shallow market.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IQ', 1, 'retirement_accumulation_return_high', 0.08, NULL, 'assumption', 'Equity high 10%; gold high 12%', 'https://tradingeconomics.com/iraq/interest-rate', '2026-10-31', 'High case: a growth-leaning mix with gold.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IQ', 1, 'retirement_accumulation_return_low', 0.03, NULL, 'assumption', 'Fixed income low 2.5%; equity low 2%', 'https://tradingeconomics.com/iraq/interest-rate', '2026-10-31', 'Low case: a mix earning about deposit rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IQ', 1, 'retirement_age_default', NULL, NULL, 'missing', '', '', '2026-10-31', 'The pension age for private-sector workers under the Social Security and Retirement Law for Workers (Law No. 18 of 2023) could not be read from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IQ', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'The civil-service retirement age under the Unified Retirement Law (No. 9 of 2014, as amended) is reported as 60 but could not be read from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IQ', 1, 'retirement_return_base', 0.035, NULL, 'assumption', 'Central Bank of Iraq policy rate 5.5%', 'https://tradingeconomics.com/iraq/interest-rate', '2026-10-31', 'Base case: below the assumed 4% after-tax term deposit rate, so not above the safe rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IQ', 1, 'retirement_return_high', 0.05, NULL, 'assumption', 'Central Bank of Iraq policy rate 5.5%', 'https://tradingeconomics.com/iraq/interest-rate', '2026-10-31', 'High case: long deposits and government bonds near the policy rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IQ', 1, 'retirement_return_low', 0.025, NULL, 'assumption', 'Central Bank of Iraq policy rate 5.5%', 'https://tradingeconomics.com/iraq/interest-rate', '2026-10-31', 'Low case: savings rates after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IQ', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No continuously sold government savings certificate for individuals was confirmed; the Ministry of Finance has sold occasional public bond issues.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IQ', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No current industry-wide savings account rate could be read from the Central Bank of Iraq; its interest-rate page (https://cbi.iq/page/143) lists bank rate tables only up to 2024, in spreadsheet files.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IQ', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":17.5},{"year":2040,"value":11.2},{"year":2065,"value":6.2}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/iraq/2040/', '2025-12-31', '100 / old-age dependency ratio: 5.70 (2025, World Bank), 8.9 (2040) and 16.2 (2065, populationpyramid.net/iraq/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IQ', 1, 'tax_bank_interest', NULL, NULL, 'missing', '', '', '2026-10-31', 'PwC Worldwide Tax Summaries (Iraq, last reviewed 24 June 2026) gives no specific rate or exemption for resident individuals'' bank interest; the Central Bank of Iraq interest-rate page publishes only bank rate tables.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IQ', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate for individuals was confirmed, and the tax on government bond income could not be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IQ', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Treasury bills are auctioned to banks; no current 91-day yield could be read from the Central Bank of Iraq; its interest-rate page (https://cbi.iq/page/143) lists bank rate tables only up to 2024, in spreadsheet files.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('IQ', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 10-year government bond yield was found.', 0);
