INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JM', 1, 'goal_inflation_education', 0.06, NULL, 'assumption', 'Bank of Jamaica: headline inflation (RS.INF.01)', 'https://boj.org.jm/wp-content/uploads/2020/10/RS.INF.01.xls', '2026-10-31', 'No education price index rate was read; tuition usually rises faster than headline, so we plan with 6%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JM', 1, 'goal_inflation_health', 0.065, NULL, 'assumption', 'Bank of Jamaica: headline inflation (RS.INF.01)', 'https://boj.org.jm/wp-content/uploads/2020/10/RS.INF.01.xls', '2026-10-31', 'No health price index rate was read; private care tends to outpace headline, so we plan with 1.5 points above the 5% target mid-point.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JM', 1, 'gold_return_base', 0.065, NULL, 'assumption', 'World Bank Commodity Markets (Pink Sheet) gold price; JMD exchange rate trend', 'https://www.worldbank.org/en/research/commodity-markets', '2026-10-31', 'Dollar gold trend of about 4.5% a year plus about 2% Jamaican dollar depreciation.', 0);
