INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JM', 1, 'gold_return_low', 0.03, NULL, 'assumption', 'World Bank Commodity Markets (Pink Sheet) gold price', 'https://www.worldbank.org/en/research/commodity-markets', '2026-10-31', 'Low case: flat dollar gold with mild depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JM', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'Redundancy pay exists under the Employment (Termination and Redundancy Payments) Act, but no readable official source giving the weeks-per-year formula was found; there is no general statutory gratuity on retirement or resignation in the sources read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JM', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a major private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JM', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No public premium table for private health insurance by age was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JM', 1, 'inflation_cpi', 0.0859, NULL, 'sourced', 'Bank of Jamaica: headline inflation (RS.INF.01, STATIN CPI)', 'https://boj.org.jm/wp-content/uploads/2020/10/RS.INF.01.xls', '2026-09-30', '12-month point-to-point inflation 8.59% in September 2026, up from 7.86% in August; above the 4-6% target range.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JM', 1, 'inflation_projection', 0.05, NULL, 'assumption', 'Bank of Jamaica: inflation target and outturn (RS.INF.00), target 4-6%', 'https://boj.org.jm/wp-content/uploads/2020/10/RS.INF.00.xls', '2026-10-31', 'The BOJ targets 4-6% and fiscal-year outturns were 4.3-6.2% in 2022/23-2025/26 apart from 2021/22, so we plan with the 5% mid-point despite the 2026 spike.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JM', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life is sold, but no published per-1,000 premium rates by age from the regulator or another permitted source were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JM', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No industry-wide life claim settlement ratio from the Financial Services Commission was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JM', 1, 'life_expectancy', 71.606, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=JM', '2024-12-31', 'Men 69.1, women 74.1 (2024). UN WPP 2024 via populationpyramid.net gives 71.9 for 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JM', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":18.1,"men":16.7,"women":19.4},{"age":65,"total":14.6,"men":13.5,"women":15.6},{"age":70,"total":11.4,"men":10.5,"women":12.2},{"age":80,"total":6.4,"men":6,"women":6.7}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/jamaica/', '2026-07-01', 'Secondary source of UN WPP 2024 medium-variant projections for 2026; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JM', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":75,"womenAge":75,"over90Monthly":null,"meansTested":true}', 'sourced', 'Jamaica Information Service: 16,000 Jamaicans now registered under Govt''s Social Pension Programme (22 September 2025)', 'https://jis.gov.jm/16000-jamaicans-now-registered-under-govts-social-pension-programme/', '2025-09-22', 'Citizens aged 75 and older who receive no pension (local or overseas), other retirement, disability or regular income support, are not on PATH and do not live in a government care facility.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JM', 1, 'old_age_allowance_monthly', 6000, NULL, 'sourced', 'Jamaica Information Service: Nearly 15,000 seniors registered on the Social Pension Programme (31 May 2024)', 'https://jis.gov.jm/nearly-15000-seniors-registered-on-the-social-pension-programme/', '2024-05-01', 'Social Pension paid every two months: J$12,000 per payment from May 2024 (up from J$6,800), i.e. J$6,000 a month; the article says ''bimonthly'' and the earlier J$6,800 equals two months of the original J$3,400. Older than 2025; no later amount found (the JIS article of September 2025 gives no amount).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JM', 1, 'oop_health_share', 0.2025, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=JM', '2023-12-31', NULL, 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JM', 1, 'policy_rate', 0.06, NULL, 'sourced', 'Bank of Jamaica: Monetary Policy Press Release, September 2026', 'https://boj.org.jm/monetary-policy-press-release-september-2026/', '2026-09-29', 'Raised by 50 basis points from 5.50% on 24-25 September 2026, effective 29 September 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JM', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":65,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'Ministry of Labour and Social Security: National Insurance Scheme', 'https://www.mlss.gov.jm/departments/national-insurance-scheme/', '2023-04-01', 'NIS: employee and employer each pay 3% of pay up to J$5 million a year (PwC, reviewed 29 Sept 2026); flat-rate old-age pension J$4,200 a week (full rate) from 1 April 2023, raised by periodic decisions rather than automatic indexation; a J$60,000 grant if contribution conditions are not met. Older than 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JM', 1, 'retirement_accumulation_return_base', 0.06, NULL, 'assumption', 'BOJ deposit and T-bill rates; Jamaica Stock Exchange record', 'https://boj.org.jm/wp-content/uploads/2020/10/IR.GOJ.00.xlsx', '2026-10-31', 'Base case: about half equities at 7.5% and half fixed income at 4%, rounded.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JM', 1, 'retirement_accumulation_return_high', 0.08, NULL, 'assumption', 'BOJ deposit and T-bill rates; Jamaica Stock Exchange record', 'https://boj.org.jm/wp-content/uploads/2020/10/IR.GOJ.00.xlsx', '2026-10-31', 'High case with strong equities.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JM', 1, 'retirement_accumulation_return_low', 0.045, NULL, 'assumption', 'BOJ deposit and T-bill rates; Jamaica Stock Exchange record', 'https://boj.org.jm/wp-content/uploads/2020/10/IR.GOJ.00.xlsx', '2026-10-31', 'Low case for a balanced mix of T-bills, deposits and shares.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JM', 1, 'retirement_age_default', 65, NULL, 'sourced', 'National Insurance Act (with amendments to 2016), section 3(2): retirement age', 'https://www.mlss.gov.jm/wp-content/uploads/2018/02/The-National-Insurance-Act-with-Ammendments-to-2016-April-2018.pdf', '2018-04-01', 'NIS retirement age 65 for men; for women it rose a year at a time from 60 (to March 2011) to 64 (April 2014 to March 2015) and then 65. Older than 2025: consolidated text of April 2018.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JM', 1, 'retirement_age_government', 65, NULL, 'sourced', 'Jamaica Information Service: House approves pension reform for public officers (8 May 2025)', 'https://jis.gov.jm/house-approves-pension-reform-grants-early-retirement-with-full-benefits-for-public-officers/', '2025-05-08', 'Under the Pensions (Public Service) Act the retirement age rose gradually from 60 to 65 between April 2018 and April 2023; public officers retire at 65 from April 2023.', 0);
