INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JM', 1, 'retirement_return_low', 0.025, NULL, 'assumption', 'Bank of Jamaica: commercial banks'' domestic currency deposit rates (IR.CB.00)', 'https://boj.org.jm/wp-content/uploads/2020/10/IR.CB.00.xls', '2026-10-31', 'Low case: short deposits after 25% tax.', 0);
