INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('JO', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"JO","iso3":"JOR","nameEn":"Jordan","nameNative":"الأردن","region":"middle_east_north_africa","languages":["ar","en"],"currency":{"code":"JOD","symbol":"JD","decimals":3,"compact":"intl","usdRate":{"value":0.71,"status":"sourced","sourceName":"Central Bank of Jordan statistical database, US dollar selling rate, end of period","sourceUrl":"https://statisticaldb.cbj.gov.jo/Browser/index","asOf":"2026-09-30","note":"710 fils per US dollar at the end of September 2026; the dinar is pegged at about 0.709 (World Bank 2025 average 0.71). CLDR gives no narrow symbol; ''JD'' is the usual local abbreviation."}},"instruments":{"savings_account":{"available":true,"localName":"حساب توفير","localNameEn":"Savings account","note":"Savings deposits pay very little (0.38% on average in August 2026).","sourceUrl":"https://statisticaldb.cbj.gov.jo/Browser/index"},"fdr_3m":{"available":true,"localName":"وديعة لأجل (3 أشهر)","localNameEn":"Time deposit (3 months)"},"fdr_1y":{"available":true,"localName":"وديعة لأجل (سنة)","localNameEn":"Time deposit (1 year)","note":"The average rate on time deposits was 4.90% in August 2026; 5% tax is withheld on interest.","sourceUrl":"https://statisticaldb.cbj.gov.jo/Browser/index"},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No standard monthly recurring deposit product was found."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate for individuals was found."},"tbill_91d":{"available":true,"localName":"أذونات الخزينة","localNameEn":"Treasury bills","note":"Issued by the Ministry of Finance through CBJ auctions, mainly bought by banks."},"tbond_5y":{"available":true,"localName":"سندات الخزينة","localNameEn":"Treasury bonds","note":"Issued through CBJ auctions, mainly bought by banks and institutions."},"tbond_10y":{"available":true,"localName":"سندات الخزينة","localNameEn":"Treasury bonds","note":"Issued through CBJ auctions, mainly bought by banks and institutions."},"equity_fund":{"available":true,"localName":"صناديق الاستثمار المشترك","localNameEn":"Mutual investment funds","note":"Few local funds exist; listed Jordanian shares can also be bought directly."},"gold":{"available":true,"localName":"الذهب","localNameEn":"Gold","note":"Gold bars, coins and jewellery are freely sold."}},"institutions":{"centralBank":{"name":"Central Bank of Jordan (CBJ)","url":"https://www.cbj.gov.jo/"},"insuranceRegulator":{"name":"Central Bank of Jordan, insurance supervision","url":"https://www.cbj.gov.jo/"},"insuranceComplaints":{"name":"Central Bank of Jordan, financial consumer protection","url":"https://www.cbj.gov.jo/"},"pensionScheme":{"name":"Social Security Corporation (SSC)","url":"https://www.ssc.gov.jo/"},"oldAgeAllowance":{"name":"National Aid Fund (means-tested cash assistance)","url":"https://naf.gov.jo/"},"publicHealthCover":{"name":"Ministry of Health, civil health insurance","url":"https://www.moh.gov.jo/"},"depositInsurance":{"name":"Jordan Deposit Insurance Corporation","url":"https://www.dic.gov.jo/"},"statistics":{"name":"Department of Statistics (DoS)","url":"https://dosweb.dos.gov.jo/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JO', 1, 'bank_deposit_avg_rate', 0.049, NULL, 'sourced', 'Central Bank of Jordan statistical database, weighted average interest rate on time deposits at licensed banks', 'https://statisticaldb.cbj.gov.jo/Browser/index', '2026-08-31', '4.90% in August 2026 (Trading Economics reports the same 4.90% as Jordan''s deposit interest rate); the World Bank FR.INR.DPST 2025 average was 5.47%.', 0);
