INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JO', 1, 'equity_return_base', 0.07, NULL, 'assumption', 'CBJ time-deposit rate 4.90% (4.66% after 5% withholding); Amman index record (Trading Economics)', 'https://tradingeconomics.com/jordan/stock-market', '2026-10-31', 'Base case: about 2.3 points above the after-tax deposit rate, kept modest because the index is still below its 2008 high despite a 24% gain in the past year.', 0);
