INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JO', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The CBJ publishes only the weighted average rate on all time deposits (4.90% in August 2026), not a 3-month rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JO', 1, 'fixed_income_return_base', 0.046, NULL, 'assumption', 'Central Bank of Jordan statistical database, time-deposit rate 4.90% (August 2026), less 5% withholding', 'https://statisticaldb.cbj.gov.jo/Browser/index', '2026-10-31', 'Base case: the average time-deposit rate after the 5% withholding tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JO', 1, 'fixed_income_return_high', 0.055, NULL, 'assumption', 'Central Bank of Jordan policy rate 6% (Trading Economics); time-deposit rate 4.90%', 'https://tradingeconomics.com/jordan/interest-rate', '2026-10-31', 'High case: savers who reach rates closer to the 6% policy rate through larger or longer deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JO', 1, 'fixed_income_return_low', 0.035, NULL, 'assumption', 'Central Bank of Jordan statistical database, time-deposit rates', 'https://statisticaldb.cbj.gov.jo/Browser/index', '2026-10-31', 'Low case: deposit rates fall further, as they have since 2025, to about 3.5% after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JO', 1, 'goal_inflation_education', 0.035, NULL, 'assumption', 'Central Bank of Jordan statistical database, CPI education group: up 3.3% in the year to September 2026, 1.9% a year over five years', 'https://statisticaldb.cbj.gov.jo/Browser/index', '2026-10-31', 'Education prices are now rising faster than the CPI (3.3%), so 1 point above the 2.5% inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JO', 1, 'goal_inflation_health', 0.035, NULL, 'assumption', 'Central Bank of Jordan statistical database, CPI health group: up 0.7% in the year to September 2026, 1.6% a year over five years', 'https://statisticaldb.cbj.gov.jo/Browser/index', '2026-10-31', 'Measured health prices have risen slower than the CPI, but private care costs usually rise faster, so 1 point above the 2.5% inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JO', 1, 'gold_return_base', 0.04, NULL, 'assumption', 'Dollar peg (0.709-0.710 JOD per USD); long-run dollar gold trend', 'https://statisticaldb.cbj.gov.jo/Browser/index', '2026-10-31', 'Base case: the long-run dollar gold trend of about 4% a year, with no depreciation gain under the peg.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JO', 1, 'gold_return_high', 0.08, NULL, 'assumption', 'Dollar peg; long-run dollar gold trend', 'https://statisticaldb.cbj.gov.jo/Browser/index', '2026-10-31', 'High case: strong dollar gold years.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JO', 1, 'gold_return_low', 0, NULL, 'assumption', 'Central Bank of Jordan statistical database: 0.710 JOD per USD (peg)', 'https://statisticaldb.cbj.gov.jo/Browser/index', '2026-10-31', 'Low case: flat dollar gold; the peg means no currency boost.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JO', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Labour Law provides end-of-service compensation for workers not covered by social security, but the law text and the Ministry of Labour site could not be read, so the days per year could not be confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JO', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a major private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JO', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No public table of private health insurance premiums by age was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JO', 1, 'inflation_cpi', 0.0273, NULL, 'sourced', 'Central Bank of Jordan statistical database, consumer price index (2018=100), Department of Statistics data', 'https://statisticaldb.cbj.gov.jo/Browser/index', '2026-09-30', 'CPI 115.816 in September 2026 against 112.739 a year earlier, up 2.73% (Trading Economics also reports 2.73%, from 2.66% in August).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JO', 1, 'inflation_projection', 0.025, NULL, 'assumption', 'Central Bank of Jordan statistical database, CPI: 2.4% a year on average September 2021 to September 2026; dinar pegged to the US dollar', 'https://statisticaldb.cbj.gov.jo/Browser/index', '2026-10-31', 'The dinar is pegged to the dollar and CPI inflation averaged 2.4% a year over the last five years (2.7% now), so 2.5% is used; the central bank has no numeric target.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JO', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life cover is sold, but no regulator or other public table of premiums per JOD 1,000 of cover by age was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JO', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The CBJ (insurance supervisor since 2021) publishes no industry-wide life claim settlement ratio that could be found; its site could not be reached.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JO', 1, 'life_expectancy', 78.3, NULL, 'sourced', 'UN World Population Prospects 2024 (medium variant) via populationpyramid.net, life expectancy at birth, Jordan, 2026', 'https://www.populationpyramid.net/mortality/jordan/', '2026-07-01', '78.3 years in 2026 (men 76.2, women 80.6), UN WPP 2024 medium variant via a secondary site; the World Bank gives 78.0 for 2024.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JO', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":21.8,"men":20,"women":23.6},{"age":65,"total":17.6,"men":16,"women":19.3},{"age":70,"total":13.9,"men":12.5,"women":15.2},{"age":80,"total":7.7,"men":6.8,"women":8.6}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/jordan/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JO', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'Eligibility rules for National Aid Fund support to older people could not be read from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JO', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'No dedicated non-contributory old-age pension was found; poor households, including older people, can get means-tested cash aid from the National Aid Fund, but its current amounts for an older person could not be read (site unreachable).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JO', 1, 'oop_health_share', 0.3447, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), Jordan', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=JO', '2023-12-31', '34.5% in 2023 (WHO Global Health Expenditure Database via the World Bank); older than 2025, the latest available.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JO', 1, 'policy_rate', 0.06, NULL, 'sourced', 'Trading Economics, citing the Central Bank of Jordan: main policy rate raised by 25 bps to 6% in September 2026', 'https://tradingeconomics.com/jordan/interest-rate', '2026-09-30', 'Secondary source; the CBJ website could not be reached. The CBJ statistical database shows the main rate at 5.75% through August 2026; the same Trading Economics page also carries an older headline about a cut to 6.25%, so the September 2026 rise to 6% should be re-checked against a CBJ release.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JO', 1, 'public_pension_scheme', NULL, NULL, 'missing', '', '', '2026-10-31', 'Compulsory social security through the Social Security Corporation covers private and newer public employees (PwC: contributions 7.5% employee, 14.25% employer, https://taxsummaries.pwc.com/jordan/individual/other-taxes), but the pension age and indexation rules could not be read because ssc.gov.jo refused connections.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JO', 1, 'retirement_accumulation_return_base', 0.055, NULL, 'assumption', 'CBJ deposit rates; equity base 7%; gold base 4%', 'https://statisticaldb.cbj.gov.jo/Browser/index', '2026-10-31', 'Base case: a balanced mix of deposits, equities and some gold.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JO', 1, 'retirement_accumulation_return_high', 0.07, NULL, 'assumption', 'CBJ deposit rates; equity high 9.5%', 'https://statisticaldb.cbj.gov.jo/Browser/index', '2026-10-31', 'High case: a growth-leaning mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JO', 1, 'retirement_accumulation_return_low', 0.04, NULL, 'assumption', 'Central Bank of Jordan statistical database, deposit rates', 'https://statisticaldb.cbj.gov.jo/Browser/index', '2026-10-31', 'Low case: a mix earning a little less than deposits after tax because equities lag.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JO', 1, 'retirement_age_default', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Social Security Corporation site (ssc.gov.jo) refused connections and no other official text of the Social Security Law could be read, so the old-age pension age could not be confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JO', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'New civil servants are covered by the Social Security Corporation; its pension age could not be confirmed because ssc.gov.jo refused connections.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JO', 1, 'retirement_return_base', 0.045, NULL, 'assumption', 'Central Bank of Jordan statistical database, time-deposit rate 4.90% (4.66% after 5% withholding)', 'https://statisticaldb.cbj.gov.jo/Browser/index', '2026-10-31', 'Base case: just below the after-tax time-deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JO', 1, 'retirement_return_high', 0.053, NULL, 'assumption', 'Central Bank of Jordan policy rate 6% (Trading Economics)', 'https://tradingeconomics.com/jordan/interest-rate', '2026-10-31', 'High case: larger or longer deposits near the policy rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JO', 1, 'retirement_return_low', 0.035, NULL, 'assumption', 'Central Bank of Jordan statistical database, time-deposit rates', 'https://statisticaldb.cbj.gov.jo/Browser/index', '2026-10-31', 'Low case: deposit rates keep falling, to about 3.5% after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JO', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate or retail savings bond for individuals was found; treasury bills and bonds are auctioned by the CBJ mainly to banks.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JO', 1, 'savings_account_rate', 0.0038, NULL, 'sourced', 'Central Bank of Jordan statistical database, weighted average interest rate on savings deposits at licensed banks', 'https://statisticaldb.cbj.gov.jo/Browser/index', '2026-08-31', '0.38% in August 2026 (demand deposits 0.75%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JO', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":13.68},{"year":2040,"value":7.14},{"year":2065,"value":3.98}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/jordan/2040/', '2025-12-31', '100 / old-age dependency ratio: 7.31 (2025, World Bank), 14.0 (2040) and 25.1 (2065, populationpyramid.net/jordan/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JO', 1, 'tax_bank_interest', 0.05, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Jordan, corporate withholding taxes (interest paid by banks)', 'https://taxsummaries.pwc.com/jordan/corporate/withholding-taxes', '2026-10-31', 'Interest and deposit profits paid by banks are subject to 5% withholding for individuals (7% for companies); interest is also taxable income for residents under the progressive 5-30% scale, so the 5% is a minimum.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JO', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No retail savings certificate exists; the tax treatment of treasury bond interest for individuals was not confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JO', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Treasury bill auction yields are published by the CBJ and Ministry of Finance, but neither site could be reached (connection refused) and the CBJ statistical database has no bill-yield series.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JO', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Treasury bond auction yields could not be read: the CBJ and Ministry of Finance sites refused connections.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JO', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Treasury bond auction yields could not be read: the CBJ and Ministry of Finance sites refused connections.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('JP', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"JP","iso3":"JPN","nameEn":"Japan","nameNative":"日本","region":"east_asia_pacific","languages":["ja"],"currency":{"code":"JPY","symbol":"¥","decimals":0,"compact":"intl","usdRate":{"value":158,"status":"sourced","sourceName":"Bank of Japan, USD/JPY spot rate at 9:00 JST, Tokyo market","sourceUrl":"https://www.stat-search.boj.or.jp/api/v1/getDataCode?format=json&lang=en&db=FM08&code=FXERD01&startDate=202610","asOf":"2026-10-28"}},"instruments":{"savings_account":{"available":true,"localName":"普通預金","localNameEn":"Ordinary deposit","sourceUrl":"https://www.stat-search.boj.or.jp/api/v1/getDataCode?format=json&lang=en&db=IR02&code=DLDR121N,DLDR43TL63MN,DLDR43TL61YN,DLDR43TL65YN&startDate=202606"},"fdr_3m":{"available":true,"localName":"定期預金","localNameEn":"Time deposit (3 months)","sourceUrl":"https://www.stat-search.boj.or.jp/api/v1/getDataCode?format=json&lang=en&db=IR02&code=DLDR121N,DLDR43TL63MN,DLDR43TL61YN,DLDR43TL65YN&startDate=202606"},"fdr_1y":{"available":true,"localName":"定期預金","localNameEn":"Time deposit (1 year)","sourceUrl":"https://www.stat-search.boj.or.jp/api/v1/getDataCode?format=json&lang=en&db=IR02&code=DLDR121N,DLDR43TL63MN,DLDR43TL61YN,DLDR43TL65YN&startDate=202606"},"dps":{"available":true,"localName":"積立定期預金","localNameEn":"Installment time deposit","note":"Fixed monthly transfers into a time deposit; offered by most banks."},"sanchayapatra_5y":{"available":true,"localName":"個人向け国債（固定5年）","localNameEn":"JGBs for individuals (fixed 5-year)","note":"Sold monthly from 10,000 yen; rate floor 0.05%; also fixed 3-year and floating 10-year types.","sourceUrl":"https://www.mof.go.jp/jgbs/individual/kojinmuke/recruitment/index.html"},"tbill_91d":{"available":false,"localName":"国庫短期証券","localNameEn":"Treasury discount bills","note":"Treasury discount bills are sold at auction to institutions and are not offered to individuals (holders are restricted to corporations; not confirmed from an official page in this pass).","sourceUrl":"https://tradingeconomics.com/japan/3-month-bill-yield"},"tbond_5y":{"available":true,"localName":"利付国債（5年）","localNameEn":"5-year JGB","note":"Individuals can buy newly issued JGBs at banks and brokers.","sourceUrl":"https://www.mof.go.jp/english/policy/jgbs/reference/interest_rate/jgbcme.csv"},"tbond_10y":{"available":true,"localName":"利付国債（10年）","localNameEn":"10-year JGB","sourceUrl":"https://www.mof.go.jp/english/policy/jgbs/reference/interest_rate/jgbcme.csv"},"equity_fund":{"available":true,"localName":"投資信託（インデックスファンド）","localNameEn":"Investment trust (index fund)","note":"Widely held through tax-free NISA accounts and iDeCo private pensions."},"gold":{"available":true,"localName":"金地金","localNameEn":"Gold bullion","note":"Gold bars and coins are freely bought; also gold accumulation plans."}},"institutions":{"centralBank":{"name":"Bank of Japan","url":"https://www.boj.or.jp/en/"},"insuranceRegulator":{"name":"Financial Services Agency (FSA)","url":"https://www.fsa.go.jp/en/"},"insuranceComplaints":{"name":"FSA Financial Services User Consultation Office","url":"https://www.fsa.go.jp/receipt/soudansitu/index.html","note":"Advice and referral; dispute resolution goes to the designated ADR body for life insurance."},"pensionScheme":{"name":"Japan Pension Service (National Pension and Employees'' Pension)","url":"https://www.nenkin.go.jp/"},"oldAgeAllowance":null,"publicHealthCover":{"name":"Ministry of Health, Labour and Welfare (public medical insurance)","url":"https://www.mhlw.go.jp/stf/seisakunitsuite/bunya/kenkou_iryou/iryouhoken/index.html"},"depositInsurance":{"name":"Deposit Insurance Corporation of Japan","url":"https://www.dic.go.jp/english/"},"statistics":{"name":"Statistics Bureau of Japan","url":"https://www.stat.go.jp/english/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JP', 1, 'bank_deposit_avg_rate', 0.00884, NULL, 'sourced', 'Bank of Japan, average interest rates on new time deposits (total)', 'https://www.stat-search.boj.or.jp/api/v1/getDataCode?format=json&lang=en&db=IR03&code=DLDRK_DLDR442DB&startDate=202604', '2026-08-31', 'Average on all new time deposits; ordinary deposits average 0.33%. World Bank FR.INR.DPST stops in 2017.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JP', 1, 'credit_card_rate_cap', 0.18, NULL, 'sourced', 'Interest Rate Restriction Act (Act No. 100 of 1954), Article 1, e-Gov law database', 'https://laws.e-gov.go.jp/law/329AC0000000100', '2026-10-31', 'Legal caps: 20% a year on principal under 100,000 yen, 18% from 100,000 to under 1 million yen, 15% from 1 million yen; 18% used for typical card balances.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JP', 1, 'deposit_insurance_limit', 10000000, NULL, 'sourced', 'Financial Services Agency, deposit insurance (payoff) page', 'https://www.fsa.go.jp/policy/payoff/index.html', '2026-10-31', 'Principal up to 10 million yen per depositor per institution plus interest; settlement deposits fully protected.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JP', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The BOJ stopped publishing installment savings rates in 2022; banks offer installment time deposits but no average rate is published. The 5-year time deposit posted average is 0.748% (October 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JP', 1, 'equity_return_base', 0.055, NULL, 'assumption', 'Retail fixed 5-year JGB 2.39% (1.90% after 20.315% tax), October 2026; 5-year JGB 2.24%', 'https://www.mof.go.jp/jgbs/individual/kojinmuke/recruitment/index.html', '2026-10-31', 'After-tax safe rate of about 1.9% plus a 3.6-point premium; TOPIX had a strong decade, but valuations are higher now.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JP', 1, 'equity_return_high', 0.09, NULL, 'assumption', 'Retail fixed 5-year JGB 2.39% (1.90% after 20.315% tax), October 2026; 5-year JGB 2.24%', 'https://www.mof.go.jp/jgbs/individual/kojinmuke/recruitment/index.html', '2026-10-31', 'High case near TOPIX''s 10-year total return.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JP', 1, 'equity_return_low', 0.02, NULL, 'assumption', 'Retail fixed 5-year JGB 2.39% (1.90% after 20.315% tax), October 2026; 5-year JGB 2.24%', 'https://www.mof.go.jp/jgbs/individual/kojinmuke/recruitment/index.html', '2026-10-31', 'Low case close to the after-tax safe rate of about 1.9%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JP', 1, 'fdr_1y_rate', 0.00486, NULL, 'sourced', 'Bank of Japan, average posted time deposit rates (under 3 million yen, 1 year)', 'https://www.stat-search.boj.or.jp/api/v1/getDataCode?format=json&lang=en&db=IR02&code=DLDR121N,DLDR43TL63MN,DLDR43TL61YN,DLDR43TL65YN&startDate=202606', '2026-10-31', NULL, 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JP', 1, 'fdr_3m_rate', 0.0044, NULL, 'sourced', 'Bank of Japan, average posted time deposit rates (under 3 million yen, 3 months)', 'https://www.stat-search.boj.or.jp/api/v1/getDataCode?format=json&lang=en&db=IR02&code=DLDR121N,DLDR43TL63MN,DLDR43TL61YN,DLDR43TL65YN&startDate=202606', '2026-10-31', NULL, 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JP', 1, 'fixed_income_return_base', 0.015, NULL, 'assumption', 'Retail fixed 5-year JGB 2.39% (1.90% after 20.315% tax), October 2026; 5-year JGB 2.24%', 'https://www.mof.go.jp/jgbs/individual/kojinmuke/recruitment/index.html', '2026-10-31', 'Base case: mix of retail JGBs (1.9% after tax) and deposits (0.4% after tax), about 1.5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JP', 1, 'fixed_income_return_high', 0.023, NULL, 'assumption', '10-year JGB 2.82% (30 October 2026) less 20.315% tax', 'https://www.mof.go.jp/english/policy/jgbs/reference/interest_rate/jgbcme.csv', '2026-10-31', 'High case: locking in 10-year JGB yields, about 2.2-2.3% after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JP', 1, 'fixed_income_return_low', 0.0039, NULL, 'assumption', 'BOJ posted 1-year time deposit 0.486% less 20.315% tax', 'https://www.stat-search.boj.or.jp/api/v1/getDataCode?format=json&lang=en&db=IR02&code=DLDR121N,DLDR43TL63MN,DLDR43TL61YN,DLDR43TL65YN&startDate=202606', '2026-10-31', 'Low case: bank time deposits only, after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JP', 1, 'goal_inflation_education', 0.015, NULL, 'assumption', 'Bank of Japan 2% target; tuition support for high school', 'https://www.boj.or.jp/en/mopo/mpmdeci/mpr_2026/k261030a.pdf', '2026-10-31', 'Public tuition support has held education prices down, so we plan slightly below the target.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JP', 1, 'goal_inflation_health', 0.02, NULL, 'assumption', 'Bank of Japan 2% target; national fee schedule for medical care', 'https://www.boj.or.jp/en/mopo/mpmdeci/mpr_2026/k261030a.pdf', '2026-10-31', 'Medical prices follow the regulated national fee schedule, so we plan with the 2% target.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JP', 1, 'gold_return_base', 0.04, NULL, 'assumption', 'Bank of Japan USD/JPY spot (158.00 on 28 Oct 2026); World Bank PA.NUS.FCRF', 'https://www.stat-search.boj.or.jp/api/v1/getDataCode?format=json&lang=en&db=FM08&code=FXERD01&startDate=202610', '2026-10-31', 'Dollar gold trend of about 4% with no further expected yen depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JP', 1, 'gold_return_high', 0.08, NULL, 'assumption', 'Bank of Japan USD/JPY spot (158.00 on 28 Oct 2026); World Bank PA.NUS.FCRF', 'https://www.stat-search.boj.or.jp/api/v1/getDataCode?format=json&lang=en&db=FM08&code=FXERD01&startDate=202610', '2026-10-31', 'High case with strong dollar gold and further yen weakness.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JP', 1, 'gold_return_low', 0, NULL, 'assumption', 'Bank of Japan USD/JPY spot (158.00 on 28 Oct 2026); World Bank PA.NUS.FCRF', 'https://www.stat-search.boj.or.jp/api/v1/getDataCode?format=json&lang=en&db=FM08&code=FXERD01&startDate=202610', '2026-10-31', 'Low case: flat dollar gold and some yen recovery from historically weak levels.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JP', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'Confirmed absent: Japan has no statutory gratuity. The Labor Standards Act, Article 89(iii-2), requires work rules to cover retirement allowances only where the employer establishes one (https://laws.e-gov.go.jp/law/322AC0000000049); amounts are set by each employer''s rules.', 1);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JP', 1, 'health_hospitalisation_cost', 187000, NULL, 'sourced', 'Japan Institute of Life Insurance, Survey on Life Security (FY2025)', 'https://www.jili.or.jp/lifeplan/lifesecurity/1210.html', '2025-12-31', 'Average total out-of-pocket cost of a hospital stay 187,000 yen (24,300 yen a day), after the high-cost medical expense benefit; includes meals and private-room charges.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JP', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Japanese private medical insurance pays daily and surgery benefits rather than a cover limit, so premiums per 100,000 yen of cover are not published.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JP', 1, 'inflation_cpi', 0.021, NULL, 'sourced', 'Trading Economics, citing Ministry of Internal Affairs and Communications CPI (secondary source)', 'https://tradingeconomics.com/japan/inflation-cpi', '2026-09-30', 'Headline CPI 2.1% year on year in September 2026 (1.9% in August); core CPI excluding fresh food also 2.1%. The Statistics Bureau page links only to e-Stat tables.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JP', 1, 'inflation_projection', 0.02, NULL, 'assumption', 'Bank of Japan 2% price stability target', 'https://www.boj.or.jp/en/mopo/mpmdeci/mpr_2026/k261030a.pdf', '2026-10-31', 'The BOJ targets 2% and is raising rates to hold inflation there, so we plan with 2%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JP', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life is widely sold, but no published per-1,000-yen premium rates by age were retrieved in this pass.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JP', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No industry-wide life claim settlement ratio was found from the FSA or the life insurance association within this pass.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JP', 1, 'life_expectancy', 84.04, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=JP', '2024-12-31', 'World Bank figure is for 2024 (older than 2025). MHLW 2025 abridged life table: men 81.35, women 87.33.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JP', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":26.5,"men":23.86,"women":29.07},{"age":65,"total":22.1,"men":19.68,"women":24.52},{"age":70,"total":17.94,"men":15.78,"women":20.1},{"age":80,"total":10.53,"men":9.1,"women":11.95}]}', 'sourced', 'Ministry of Health, Labour and Welfare, 2025 Abridged Life Table (Table 1, remaining life expectancy at main ages)', 'https://www.mhlw.go.jp/toukei/saikin/hw/life/life25/dl/life25-02.pdf', '2025-12-31', 'Official figures by sex for 2025; MHLW does not publish both sexes combined, so totals are the mean of men and women.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JP', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'Confirmed absent: no non-contributory old-age pension exists; the Old-age Basic Pension requires at least 10 years of contributions or exemptions (Japan Pension Service, https://www.nenkin.go.jp/service/jukyu/seido/roureinenkin/jukyu-yoken/20150401-01.html).', 1);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JP', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'Confirmed absent: Japan has no non-contributory old-age pension open to people planning today. The Japan Pension Service states the Old-age Basic Pension requires a qualifying period of at least 10 years of contributions or exemptions (https://www.nenkin.go.jp/service/jukyu/seido/roureinenkin/jukyu-yoken/20150401-01.html); people without a pension rely on means-tested public assistance, which is not an old-age pension.', 1);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JP', 1, 'oop_health_share', 0.1224, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=JP', '2023-12-31', 'Figure is for 2023 (older than 2025); latest World Bank value.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JP', 1, 'policy_rate', 0.0125, NULL, 'sourced', 'Bank of Japan, Statement on Monetary Policy, 30 October 2026', 'https://www.boj.or.jp/en/mopo/mpmdeci/mpr_2026/k261030a.pdf', '2026-10-30', 'Uncollateralized overnight call rate guided to remain at around 1.25% (8-1 vote).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JP', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":20,"entryAgeMax":59,"pensionFromAge":65,"nomineeUntilAge":null,"inflationLinked":true,"taxFree":false,"projections":[{"monthlyContribution":17920,"years":40,"monthlyPension":70608},{"monthlyContribution":17920,"years":10,"monthlyPension":17652}]}', 'sourced', 'Japan Pension Service, Old-age Basic Pension amount (FY2026) and National Pension premium', 'https://www.nenkin.go.jp/service/jukyu/seido/roureinenkin/jukyu-yoken/20150401-02.html', '2026-04-01', 'National Pension: residents join from 20 to under 60; FY2026 premium 17,920 yen a month (nenkin.go.jp premium page); full pension 847,300 yen a year (70,608 a month) after 40 years, pro rata, with 10 years minimum. Amounts are revised each April by price and wage indexation (with macro-economic slide); pensions are taxable. Employees also get the earnings-related Employees'' Pension.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JP', 1, 'retirement_accumulation_return_base', 0.04, NULL, 'assumption', 'Retail fixed 5-year JGB 2.39% (1.90% after 20.315% tax), October 2026; 5-year JGB 2.24%', 'https://www.mof.go.jp/jgbs/individual/kojinmuke/recruitment/index.html', '2026-10-31', 'Base case: roughly half equity at 5.5% and half bonds at 1.5-2.3%, held in tax-free NISA or iDeCo where possible.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JP', 1, 'retirement_accumulation_return_high', 0.06, NULL, 'assumption', 'Retail fixed 5-year JGB 2.39% (1.90% after 20.315% tax), October 2026; 5-year JGB 2.24%', 'https://www.mof.go.jp/jgbs/individual/kojinmuke/recruitment/index.html', '2026-10-31', 'High case with the equity high case.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JP', 1, 'retirement_accumulation_return_low', 0.02, NULL, 'assumption', 'Retail fixed 5-year JGB 2.39% (1.90% after 20.315% tax), October 2026; 5-year JGB 2.24%', 'https://www.mof.go.jp/jgbs/individual/kojinmuke/recruitment/index.html', '2026-10-31', 'Low case for a balanced mix if equities only match bonds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JP', 1, 'retirement_age_default', 65, NULL, 'sourced', 'Japan Pension Service, Old-age Basic Pension eligibility', 'https://www.nenkin.go.jp/service/jukyu/seido/roureinenkin/jukyu-yoken/20150401-01.html', '2026-10-31', 'Basic pension from 65 (early from 60, deferred to 75) for men and women. Employers must set any mandatory retirement age at 60 or above and keep staff employed to 65 if they wish.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JP', 1, 'retirement_age_government', 65, NULL, 'sourced', 'National Public Service Act, Article 81-6 and supplementary provisions (Act No. 61 of 2021), e-Gov law database', 'https://laws.e-gov.go.jp/law/322AC0000000120', '2026-10-31', 'National civil servants'' mandatory retirement age is 65 in the Act; transitional ages are 62 (April 2025 to March 2027), 63 (to March 2029), 64 (to March 2031) and 65 from April 2031, so 65 applies to anyone born after 1975.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JP', 1, 'retirement_return_base', 0.009, NULL, 'assumption', '1-year JGB 1.66% (30 October 2026) less 20.315% tax, about 1.3%; 3-month bill 1.21%', 'https://www.mof.go.jp/english/policy/jgbs/reference/interest_rate/jgbcme.csv', '2026-10-31', 'Base case below the after-tax 1-year government yield (about 1.3%), allowing for part held in deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JP', 1, 'retirement_return_high', 0.018, NULL, 'assumption', 'Retail fixed 5-year JGB 2.39% (1.90% after 20.315% tax), October 2026; 5-year JGB 2.24%', 'https://www.mof.go.jp/jgbs/individual/kojinmuke/recruitment/index.html', '2026-10-31', 'High case: laddered retail and 5-year JGBs, about 1.8-1.9% after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JP', 1, 'retirement_return_low', 0.004, NULL, 'assumption', 'BOJ posted 1-year time deposit 0.486% less tax', 'https://www.stat-search.boj.or.jp/api/v1/getDataCode?format=json&lang=en&db=IR02&code=DLDR121N,DLDR43TL63MN,DLDR43TL61YN,DLDR43TL65YN&startDate=202606', '2026-10-31', 'Low case: time deposits only after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JP', 1, 'sanchayapatra_5y_rate', 0.0239, NULL, 'sourced', 'Ministry of Finance, JGBs for individuals: October 2026 offering rates', 'https://www.mof.go.jp/jgbs/individual/kojinmuke/recruitment/index.html', '2026-10-08', 'Fixed 5-year retail JGB, October 2026 offering (subscriptions 8-30 October, issued 16 November): 2.39% a year before tax (1.9045% after 20.315% tax). Fixed 3-year 2.07%, floating 10-year 2.05% initial.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JP', 1, 'savings_account_rate', 0.00331, NULL, 'sourced', 'Bank of Japan, average interest rates posted by type of deposit (ordinary deposits)', 'https://www.stat-search.boj.or.jp/api/v1/getDataCode?format=json&lang=en&db=IR02&code=DLDR121N,DLDR43TL63MN,DLDR43TL61YN,DLDR43TL65YN&startDate=202606', '2026-10-31', 'Average posted ordinary deposit rate 0.331% in October 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JP', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":1.96},{"year":2040,"value":1.53},{"year":2065,"value":1.41}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/japan/2040/', '2025-12-31', '100 / old-age dependency ratio: 51.04 (2025, World Bank), 65.2 (2040) and 70.7 (2065, populationpyramid.net/japan/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JP', 1, 'tax_bank_interest', 0.20315, NULL, 'sourced', 'Ministry of Finance, JGBs for individuals (tax on interest)', 'https://www.mof.go.jp/jgbs/individual/kojinmuke/', '2026-10-31', 'Interest on deposits and bonds is taxed separately at 20.315% (15.315% national including reconstruction surtax plus 5% local), withheld at source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JP', 1, 'tax_sanchayapatra_profit', 0.20315, NULL, 'sourced', 'Ministry of Finance, JGBs for individuals (tax on interest)', 'https://www.mof.go.jp/jgbs/individual/kojinmuke/', '2026-10-31', 'Retail JGB interest is taxed at 20.315%; some holders (for example people with disabilities) can claim exemption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JP', 1, 'tbill_91d_rate', 0.0121, NULL, 'sourced', 'Trading Economics, Japan 3-month bill yield (secondary source)', 'https://tradingeconomics.com/japan/3-month-bill-yield', '2026-10-30', NULL, 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('JP', 1, 'tbond_10y_rate', 0.02817, NULL, 'sourced', 'Ministry of Finance, JGB interest rates (yield curve)', 'https://www.mof.go.jp/english/policy/jgbs/reference/interest_rate/jgbcme.csv', '2026-10-30', NULL, 0);
