INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('KE', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"KE","iso3":"KEN","nameEn":"Kenya","nameNative":"Kenya","region":"sub_saharan_africa","languages":["sw","en","ki"],"currency":{"code":"KES","symbol":"KSh","decimals":2,"compact":"intl","usdRate":{"value":129.95,"status":"sourced","sourceName":"Central Bank of Kenya mean rate, 30 October 2026, via Trading Economics","sourceUrl":"https://tradingeconomics.com/kenya/currency","asOf":"2026-10-30","note":"CBK posted a mean rate of 129.95 shillings per dollar on 30 October 2026 (shown on CBK pages); World Bank 2025 average 129.30. CLDR gives ''KES'' as symbol; ''KSh'' is the local abbreviation."}},"instruments":{"savings_account":{"available":true,"localName":"Akaunti ya akiba","localNameEn":"Savings account","note":"Weighted average 3.53% in September 2026 (CBK).","sourceUrl":"https://www.centralbank.go.ke/uploads/interest_rates/1654955992_Commercial%20banks%20Weighted%20Average%20Rates.csv"},"fdr_3m":{"available":true,"localName":"Amana ya muda maalum","localNameEn":"Fixed deposit","note":"CBK publishes one weighted average deposit rate (6.94%, September 2026).","sourceUrl":"https://www.centralbank.go.ke/uploads/interest_rates/1654955992_Commercial%20banks%20Weighted%20Average%20Rates.csv"},"fdr_1y":{"available":true,"localName":"Amana ya muda maalum (mwaka 1)","localNameEn":"Fixed deposit, 1 year","note":"No official 1-year rate; CBK publishes one weighted average deposit rate (6.94%, September 2026).","sourceUrl":"https://www.centralbank.go.ke/uploads/interest_rates/1654955992_Commercial%20banks%20Weighted%20Average%20Rates.csv"},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No standard monthly recurring deposit product with published rates was found in CBK statistics."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate on sale; no current M-Akiba retail bond issue was found. Individuals can buy Treasury bonds directly via DhowCSD."},"tbill_91d":{"available":true,"localName":null,"localNameEn":"Treasury bills","note":"Weekly CBK auctions (91, 182, 364 days); individuals bid through DhowCSD, non-competitive minimum KES 50,000.","sourceUrl":"https://www.centralbank.go.ke/uploads/91_day_historical_treasury_bill_results/872459219_RESULTS%202706-091%202680-182%202635-364%20DATED%2002-11-2026.pdf"},"tbond_5y":{"available":true,"localName":null,"localNameEn":"Treasury bonds","note":"Fixed-rate bonds of 2 to 30 years; no new 5-year issue in 2026, older 5-year bonds trade on the secondary market.","sourceUrl":"https://www.centralbank.go.ke/bills-bonds/treasury-bonds/"},"tbond_10y":{"available":true,"localName":null,"localNameEn":"Treasury bonds","note":"10-year bonds are reopened at auction and in switch auctions.","sourceUrl":"https://www.centralbank.go.ke/bills-bonds/treasury-bonds/"},"equity_fund":{"available":true,"localName":null,"localNameEn":"Unit trust (collective investment scheme)","note":"Unit trusts, including money market and equity funds, are licensed by the Capital Markets Authority.","sourceUrl":"https://www.cma.or.ke/"},"gold":{"available":false,"localName":null,"localNameEn":null,"note":"No retail market for investment gold bars or coins was found; the CBK does not issue gold coins."}},"institutions":{"centralBank":{"name":"Central Bank of Kenya","url":"https://www.centralbank.go.ke/"},"insuranceRegulator":{"name":"Insurance Regulatory Authority (IRA)","url":"https://www.ira.go.ke/"},"insuranceComplaints":{"name":"Insurance Regulatory Authority, consumer protection and complaints","url":"https://www.ira.go.ke/","note":"The IRA handles complaints against insurers; the site was behind a bot check on 31 October 2026."},"pensionScheme":{"name":"National Social Security Fund (NSSF)","url":"https://www.nssf.or.ke/","note":"Retirement Benefits Authority (https://www.rba.go.ke/) regulates occupational and individual pension schemes."},"oldAgeAllowance":{"name":"Inua Jamii older persons cash transfer, State Department for Social Protection","url":"https://www.socialprotection.go.ke/","note":"Site refused connections when checked on 31 October 2026."},"publicHealthCover":{"name":"Social Health Authority (SHA)","url":"https://www.sha.go.ke/","note":"Replaced NHIF from October 2024 under the Social Health Insurance Act 2023."},"depositInsurance":{"name":"Kenya Deposit Insurance Corporation (KDIC)","url":"https://kdic.go.ke/deposit-insurance"},"statistics":{"name":"Kenya National Bureau of Statistics (KNBS)","url":"https://www.knbs.or.ke/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KE', 1, 'bank_deposit_avg_rate', 0.0694, NULL, 'sourced', 'Central Bank of Kenya, commercial banks'' weighted average interest rates, deposit rate, September 2026', 'https://www.centralbank.go.ke/uploads/interest_rates/1654955992_Commercial%20banks%20Weighted%20Average%20Rates.csv', '2026-09-30', 'Weighted by each bank''s share of deposits; World Bank FR.INR.DPST gives 11.98% for 2024, before the 2025-2026 rate cuts.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KE', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'Kenya''s interest rate cap was repealed in 2019; no official industry figure for credit card rates was found (CBK average lending rate 14.40%, September 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KE', 1, 'deposit_insurance_limit', 500000, NULL, 'sourced', 'Kenya Deposit Insurance Corporation, deposit insurance cover', 'https://kdic.go.ke/deposit-insurance', '2026-10-31', 'KES 500,000 per depositor per member institution; the page does not state when this limit took effect.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KE', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No industry-wide rate for a monthly recurring deposit product was found in CBK statistics.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KE', 1, 'equity_return_base', 0.105, NULL, 'assumption', 'CBK 364-day Treasury bill 9.03% (29 October 2026), 7.7% after 15% withholding', 'https://www.centralbank.go.ke/uploads/91_day_historical_treasury_bill_results/872459219_RESULTS%202706-091%202680-182%202635-364%20DATED%2002-11-2026.pdf', '2026-10-31', 'Base case: held below the after-tax bill rate plus 4 points (11.7%) because the local index has a weak 10-year price record despite a 33% rise in the last year.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KE', 1, 'equity_return_high', 0.15, NULL, 'assumption', 'Trading Economics, NSE 20 index (+33% over the year to October 2026)', 'https://tradingeconomics.com/kenya/stock-market', '2026-10-31', 'High case: a sustained re-rating like 2025-2026 plus dividend yields of 5-7%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KE', 1, 'equity_return_low', 0.05, NULL, 'assumption', 'Trading Economics, Nairobi Securities Exchange NSE 20 index history', 'https://tradingeconomics.com/kenya/stock-market', '2026-10-31', 'Low case: the NSE 20 index stood near 4,100 in October 2026, close to its level a decade earlier, so a repeat of a flat-price decade with dividends gives about 5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KE', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'CBK publishes one weighted average deposit rate across all maturities (6.94%, September 2026, shown under bank_deposit_avg_rate), not a 1-year term-deposit rate; no official 1-year rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KE', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The CBK headline table gives one weighted average deposit rate (6.94%, September 2026), not a 3-month rate; no official 3-month term-deposit rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KE', 1, 'fixed_income_return_base', 0.065, NULL, 'assumption', 'CBK deposit rate 6.94% (September 2026) and 364-day bill 9.03% (October 2026), after 15% withholding', 'https://www.centralbank.go.ke/uploads/91_day_historical_treasury_bill_results/872459219_RESULTS%202706-091%202680-182%202635-364%20DATED%2002-11-2026.pdf', '2026-10-31', 'Base case: between term deposits (5.9% after tax) and one-year Treasury bills (7.7% after tax).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KE', 1, 'fixed_income_return_high', 0.09, NULL, 'assumption', 'Trading Economics, 10-year government bond yield 12.53% (30 October 2026)', 'https://tradingeconomics.com/kenya/government-bond-yield', '2026-10-31', 'High case: long Treasury bonds at about 12.5% less 10-15% withholding, allowing for lower future yields.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KE', 1, 'fixed_income_return_low', 0.03, NULL, 'assumption', 'CBK weighted average savings rate 3.53% (September 2026)', 'https://www.centralbank.go.ke/uploads/interest_rates/1654955992_Commercial%20banks%20Weighted%20Average%20Rates.csv', '2026-10-31', 'Low case: savings account rate after 15% withholding, about 3%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KE', 1, 'goal_inflation_education', 0.065, NULL, 'assumption', 'CBK inflation target 5% +/- 2.5; KNBS CPI (via Trading Economics)', 'https://tradingeconomics.com/kenya/inflation-cpi', '2026-10-31', 'No education CPI series could be read, so school fees are planned at one point above the 5.5% general assumption, as fees are usually raised yearly.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KE', 1, 'goal_inflation_health', 0.065, NULL, 'assumption', 'CBK inflation target 5% +/- 2.5; KNBS CPI (via Trading Economics)', 'https://tradingeconomics.com/kenya/inflation-cpi', '2026-10-31', 'No health CPI series could be read, so medical costs are planned at one point above the 5.5% general assumption, as private hospital and drug prices track imports and the exchange rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KE', 1, 'gold_return_base', 0.07, NULL, 'assumption', 'Trading Economics, USD/KES history; CBK inflation target 5%', 'https://tradingeconomics.com/kenya/currency', '2026-10-31', 'Base case: dollar gold trend of about 4-5% a year plus shilling depreciation of about 2-3% a year, in line with the inflation gap to the US.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KE', 1, 'gold_return_high', 0.12, NULL, 'assumption', 'Trading Economics, USD/KES history (peak 163 in January 2024)', 'https://tradingeconomics.com/kenya/currency', '2026-10-31', 'High case: strong dollar gold and a renewed depreciation episode like 2022-2023.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KE', 1, 'gold_return_low', 0.02, NULL, 'assumption', 'Trading Economics, USD/KES 129.95 (30 October 2026)', 'https://tradingeconomics.com/kenya/currency', '2026-10-31', 'Low case: flat dollar gold with a broadly stable shilling, as in 2024-2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KE', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Employment Act 2007 provides service pay on termination for employees who are not members of NSSF or a pension scheme (s.35(5)-(6)), but the official text could not be read (Kenya Law and ILO NATLEX did not serve the file).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KE', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No official typical cost of a major private hospital stay was found (SHA benefit tariffs cover reimbursement rates, not out-of-pocket totals).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KE', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premiums per 100,000 KES of cover from the regulator or another public source were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KE', 1, 'inflation_cpi', 0.073, NULL, 'sourced', 'Kenya National Bureau of Statistics (KNBS) CPI, October 2026, via Trading Economics', 'https://tradingeconomics.com/kenya/inflation-cpi', '2026-10-31', 'Secondary source (the KNBS site failed a TLS check). Annual inflation 7.3% in October 2026, up from 6.8% in September; the Central Bank of Kenya website also shows 7.3% for October 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KE', 1, 'inflation_projection', 0.055, NULL, 'assumption', 'Central Bank of Kenya inflation target (5% +/- 2.5 points); World Bank CPI inflation 2021-2025', 'https://data.worldbank.org/indicator/FP.CPI.TOTL.ZG?locations=KE', '2026-10-31', 'The CBK targets 5% within a 2.5-point band and inflation averaged about 6% over 2021-2025 (4.1% in 2025), so 5.5% is used for long-range plans.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KE', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published indicative term-life premium rates per 1,000 KES of cover from the regulator or another public source were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KE', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Insurance Regulatory Authority site was behind a bot check and no industry-wide life claim settlement ratio could be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KE', 1, 'life_expectancy', 63.8, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN)', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=KE', '2024-12-31', '63.8 years in 2024 (men 61.6, women 66.1).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KE', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":17,"men":15.7,"women":18.2},{"age":65,"total":14.1,"men":13,"women":15},{"age":70,"total":11.5,"men":10.6,"women":12.2},{"age":80,"total":6.9,"men":6.3,"women":7.4}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/kenya/', '2026-07-01', 'Secondary source of UN WPP 2024 (medium variant) for 2026; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KE', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":70,"womenAge":70,"over90Monthly":null,"meansTested":false}', 'sourced', 'Citizen Digital report of the Ministry of Labour and Social Protection statement on the June 2026 Inua Jamii payment cycle', 'https://citizen.digital/article/government-releases-ksh243-billion-for-june-inua-jamii-cash-transfers-n387738', '2026-06-30', 'Secondary source: Kenyan citizens aged 70 and above with a national ID; designed as a universal (not means-tested) social pension since 2017, but people already receiving a public service pension are excluded and new enrolment happens only in registration drives.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KE', 1, 'old_age_allowance_monthly', 2000, NULL, 'sourced', 'Citizen Digital report of the Ministry of Labour and Social Protection statement on the June 2026 Inua Jamii payment cycle', 'https://citizen.digital/article/government-releases-ksh243-billion-for-june-inua-jamii-cash-transfers-n387738', '2026-06-30', 'Secondary source dated 5 August 2026 (the State Department for Social Protection site refused connections): KES 2,000 per beneficiary for the June 2026 payment cycle, for persons aged 70 and above; a Treasury proposal to lower the age to 60 had not been enacted.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KE', 1, 'oop_health_share', 0.2425, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=KE', '2023-12-31', '24.2% in 2023 (latest year; older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KE', 1, 'policy_rate', 0.0875, NULL, 'sourced', 'Central Bank of Kenya, MPC press release: CBR retained at 8.75%', 'https://www.centralbank.go.ke/2026/10/07/mpc-retains-the-cbr-at-8-75-percent-3/', '2026-10-07', 'The Monetary Policy Committee kept the Central Bank Rate at 8.75% on 7 October 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KE', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":18,"entryAgeMax":null,"pensionFromAge":60,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'National Social Security Fund Act (Cap. 258), sections 19-20, 36 and Third Schedule', 'https://www.nssf.or.ke/download/download-the-nssf-act?wpdmdl=3590', '2026-10-31', 'Compulsory for employees aged 18 to pensionable age (60); employer and employee each pay 6% of pensionable earnings up to the Upper Earnings Limit; defined contribution, the fund credit buys a life pension (10-year guarantee), early retirement from 50. Pensions are not indexed by law; tax treatment not confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KE', 1, 'retirement_accumulation_return_base', 0.09, NULL, 'assumption', 'CBK Treasury auctions and Trading Economics NSE 20 index', 'https://tradingeconomics.com/kenya/stock-market', '2026-10-31', 'Base case: a balanced mix of Treasury bonds and local shares, between the safe and equity base cases.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KE', 1, 'retirement_accumulation_return_high', 0.115, NULL, 'assumption', 'Trading Economics, 10-year bond yield 12.53% and NSE 20 index', 'https://tradingeconomics.com/kenya/government-bond-yield', '2026-10-31', 'High case: more long bonds and shares, with yields staying near current levels.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KE', 1, 'retirement_accumulation_return_low', 0.065, NULL, 'assumption', 'CBK deposit rate 6.94% and 364-day bill 9.03%', 'https://www.centralbank.go.ke/uploads/91_day_historical_treasury_bill_results/872459219_RESULTS%202706-091%202680-182%202635-364%20DATED%2002-11-2026.pdf', '2026-10-31', 'Low case: mostly deposits and bills with a small, weak equity share.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KE', 1, 'retirement_age_default', 60, NULL, 'sourced', 'National Social Security Fund Act (Cap. 258), section 2: pensionable age', 'https://www.nssf.or.ke/download/download-the-nssf-act?wpdmdl=3590', '2026-10-31', 'Pensionable age is 60 for men and women; early retirement pension from 50 (section 36). The NSSF benefits page also mentions an age benefit at 55 under the old provident fund rules.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KE', 1, 'retirement_age_government', 60, NULL, 'sourced', 'Citizen Digital report of the High Court ruling upholding the public service retirement age (Public Service Commission Regulations 2020)', 'https://citizen.digital/article/high-court-dismisses-petition-to-scrap-mandatory-retirement-age-n367968', '2025-08-14', 'Secondary source: public officers retire at 60 (65 for registered persons with disabilities); a Public Service Commission (Amendment) Bill to put these ages in the Act was not found to be enacted.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KE', 1, 'retirement_return_base', 0.065, NULL, 'assumption', 'CBK 364-day Treasury bill 9.03% (29 October 2026), 7.7% after 15% withholding', 'https://www.centralbank.go.ke/uploads/91_day_historical_treasury_bill_results/872459219_RESULTS%202706-091%202680-182%202635-364%20DATED%2002-11-2026.pdf', '2026-10-31', 'Base case: a mix of term deposits and Treasury bills, below the 7.7% after-tax one-year bill rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KE', 1, 'retirement_return_high', 0.08, NULL, 'assumption', 'Trading Economics, 10-year government bond yield 12.53% (30 October 2026)', 'https://tradingeconomics.com/kenya/government-bond-yield', '2026-10-31', 'High case: part of the money in long Treasury or tax-exempt infrastructure bonds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KE', 1, 'retirement_return_low', 0.05, NULL, 'assumption', 'CBK deposit rate 6.94% (September 2026), 5.9% after 15% withholding', 'https://www.centralbank.go.ke/uploads/interest_rates/1654955992_Commercial%20banks%20Weighted%20Average%20Rates.csv', '2026-10-31', 'Low case: term deposits after tax, allowing for further rate cuts.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KE', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate is on sale; no current issue of the M-Akiba mobile retail bond was found. Individuals buy ordinary Treasury bills and bonds through the CBK DhowCSD platform.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KE', 1, 'savings_account_rate', 0.0353, NULL, 'sourced', 'Central Bank of Kenya, commercial banks'' weighted average interest rates, savings, September 2026', 'https://www.centralbank.go.ke/uploads/interest_rates/1654955992_Commercial%20banks%20Weighted%20Average%20Rates.csv', '2026-09-30', 'Weighted average savings rate across commercial banks, 3.53% in September 2026 (3.54% in August).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KE', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":20.1},{"year":2040,"value":14.7},{"year":2065,"value":8.1}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/kenya/2040/', '2025-12-31', '100 / old-age dependency ratio: 4.98 (2025, World Bank), 6.8 (2040) and 12.4 (2065, populationpyramid.net/kenya/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KE', 1, 'tax_bank_interest', 0.15, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Kenya, withholding taxes (other interest, resident)', 'https://taxsummaries.pwc.com/kenya/corporate/withholding-taxes', '2026-07-17', '15% withholding on interest paid to residents, final tax for individuals; page last reviewed 17 July 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KE', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate exists. For reference, PwC lists 15% withholding on government bonds of 2 years or more and 10% on bonds of 10 years or more (infrastructure bonds are exempt under the Income Tax Act).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KE', 1, 'tbill_91d_rate', 0.087498, NULL, 'sourced', 'Central Bank of Kenya, Treasury bill auction results, issue 2706/091 (auction of 29 October 2026, value date 2 November 2026)', 'https://www.centralbank.go.ke/uploads/91_day_historical_treasury_bill_results/872459219_RESULTS%202706-091%202680-182%202635-364%20DATED%2002-11-2026.pdf', '2026-10-29', 'Weighted average rate of accepted bids 8.7498% on the 91-day bill (182 days 8.8508%, 364 days 9.0288%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KE', 1, 'tbond_10y_rate', 0.1253, NULL, 'sourced', 'Trading Economics, Kenya 10-year government bond yield', 'https://tradingeconomics.com/kenya/government-bond-yield', '2026-10-30', 'Secondary source: 12.53% on 30 October 2026 (11.13% low in March 2026). The CBK last auctioned a 10-year bond (FXD1/2022/010) on 13 July 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KE', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 5-year primary auction was held in 2026 (CBK Treasury bond page) and no published 5-year secondary-market yield from an official source was found.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('KG', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"KG","iso3":"KGZ","nameEn":"Kyrgyzstan","nameNative":"Кыргызстан","region":"europe_central_asia","languages":["ky","ru","uz"],"currency":{"code":"KGS","symbol":"⃀","decimals":2,"compact":"intl","usdRate":{"value":87.4487,"status":"sourced","sourceName":"National Bank of the Kyrgyz Republic, official exchange rate of USD (daily file)","sourceUrl":"https://www.nbkr.kg/EXCEL/dailyeng.xls","asOf":"2026-10-31","note":"Official rate of 87.4487 som per US dollar for 31 October 2026 (87.4498 on 3 November); World Bank 2025 average 87.36."}},"instruments":{"savings_account":{"available":true,"localName":"Талап боюнча депозит","localNameEn":"Demand (savings) deposit","sourceUrl":"https://www.nbkr.kg/DOC/18092026/000000000067916.xls"},"fdr_3m":{"available":true,"localName":"Мөөнөттүү депозит","localNameEn":"Term deposit (3 months)","sourceUrl":"https://www.nbkr.kg/DOC/18092026/000000000067916.xls"},"fdr_1y":{"available":true,"localName":"Мөөнөттүү депозит","localNameEn":"Term deposit (1 year)","sourceUrl":"https://www.nbkr.kg/DOC/18092026/000000000067916.xls"},"dps":{"available":false,"localName":null,"localNameEn":"Recurring deposit scheme","note":"Some term deposits accept top-ups, but no standard monthly recurring deposit product with a published rate was confirmed."},"sanchayapatra_5y":{"available":true,"localName":"Калк үчүн мамлекеттик казыналык облигациялар","localNameEn":"Government treasury bonds for the population (pilot)","note":"2-year som treasury bonds sold to individuals from 1,000 som on the national stock exchange''s trading platform from mid-2026 (pilot issue of 500 million som, 17% coupon paid quarterly); term is 2 years, not 5.","sourceUrl":"https://24.kg/ekonomika/379655_gosudarstvennyie_obligatsii_kak_kyirgyzstantsyi_mogut_zarabotat_bez_lishnego_riska/"},"tbill_91d":{"available":false,"localName":"Мамлекеттик казыналык векселдер (МКВ)","localNameEn":"State treasury bills","note":"No 3-month bills have been auctioned since January 2020; only occasional 12-month bills.","sourceUrl":"https://www.nbkr.kg/EXCEL/gkv_auction_ats_eng.xls"},"tbond_5y":{"available":true,"localName":"Мамлекеттик казыналык облигациялар (МКО)","localNameEn":"State treasury bonds","note":"Auctioned regularly by the Ministry of Finance through the National Bank, mainly to banks and institutions.","sourceUrl":"https://www.nbkr.kg/EXCEL/gko_auction_ats_eng.xls"},"tbond_10y":{"available":true,"localName":"Мамлекеттик казыналык облигациялар (МКО)","localNameEn":"State treasury bonds","sourceUrl":"https://www.nbkr.kg/EXCEL/gko_auction_ats_eng.xls"},"equity_fund":{"available":false,"localName":null,"localNameEn":"Equity or index fund","note":"The local stock exchange is small and no diversified retail equity or index funds sold locally were confirmed."},"gold":{"available":true,"localName":"Алтын куймалар","localNameEn":"Gold bars","note":"The National Bank sells and buys back measured gold bars (1 g to 100 g) to the public.","sourceUrl":"https://www.nbkr.kg/index1.jsp?item=2747&lang=ENG"}},"institutions":{"centralBank":{"name":"Кыргыз Республикасынын Улуттук банкы (National Bank of the Kyrgyz Republic)","url":"https://www.nbkr.kg/"},"insuranceRegulator":{"name":"Финансы рыногун жөнгө салуу жана көзөмөлдөө кызматы (Finnadzor, Service for Financial Market Regulation and Supervision)","url":"https://fsa.gov.kg/","note":"Supervises insurers, securities and non-state pension funds."},"insuranceComplaints":{"name":"Finnadzor (Service for Financial Market Regulation and Supervision)","url":"https://fsa.gov.kg/"},"pensionScheme":{"name":"Кыргыз Республикасынын Социалдык фонду (Social Fund of the Kyrgyz Republic)","url":"https://socfond.kg/"},"oldAgeAllowance":{"name":"Ministry of Labour, Social Security and Migration (monthly social benefit)","url":"https://mlsp.gov.kg/","note":"Monthly social benefit of 2,000 som for elderly people without a pension (men 65+, women 60+)."},"publicHealthCover":{"name":"Милдеттүү медициналык камсыздандыруу фонду (Mandatory Health Insurance Fund)","url":"https://foms.kg/"},"depositInsurance":{"name":"Депозиттерди коргоо агенттиги (Deposit Protection Agency)","url":"https://deposit.kg/en/home/"},"statistics":{"name":"Улуттук статистика комитети (National Statistical Committee)","url":"https://www.stat.gov.kg/en/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KG', 1, 'bank_deposit_avg_rate', 0.0923, NULL, 'sourced', 'National Bank of the Kyrgyz Republic, newly accepted deposits (Table 6, all depositors, national currency, time deposits)', 'https://www.nbkr.kg/DOC/18092026/000000000067916.xls', '2026-07-31', 'Weighted average rate on all new som time deposits in July 2026 (preliminary); including demand deposits, which dominate new inflows, the overall average is 2.86% (World Bank FR.INR.DPST 2024: 1.67%, on the same all-inclusive basis).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KG', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap on credit card rates was found and the National Bank does not publish a separate credit card rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KG', 1, 'deposit_insurance_limit', 1000000, NULL, 'sourced', 'Deposit Protection Agency of the Kyrgyz Republic, FAQ', 'https://deposit.kg/en/frequently-asked-questions-faq/', '2026-10-31', 'Up to 1,000,000 som per depositor including accrued interest, per participating bank or microfinance company.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KG', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published average rate for monthly recurring (top-up) deposits; the National Bank reports deposits only by maturity.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KG', 1, 'equity_return_base', 0.11, NULL, 'assumption', 'Global equity index in som terms; NBKR 6-12 month deposit rate 11.98% (tax-free)', 'https://www.nbkr.kg/DOC/18092026/000000000067916.xls', '2026-10-31', 'The local stock exchange is too small and illiquid to base a forecast on, so the base case is a global index fund at about 7% in dollars plus about 4% a year of som depreciation, kept below the tax-free 1-year deposit rate plus 4 points.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KG', 1, 'equity_return_high', 0.14, NULL, 'assumption', 'Global equity long-run returns in som terms', 'https://tradingeconomics.com/united-states/stock-market', '2026-10-31', 'High case: global shares match their long-run dollar record of about 8-9% with faster som depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KG', 1, 'equity_return_low', 0.06, NULL, 'assumption', 'No developed local stock market; global equity index (S&P 500 +10.8% in a year to Oct 2026) in som terms; som about 87.4 per US dollar', 'https://tradingeconomics.com/united-states/stock-market', '2026-10-31', 'Low case: global shares bought from Kyrgyzstan return about 3% in dollars plus about 3% a year of som depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KG', 1, 'fdr_1y_rate', 0.1198, NULL, 'sourced', 'National Bank of the Kyrgyz Republic, newly accepted deposits by commercial banks (Table 7, individuals, national currency)', 'https://www.nbkr.kg/DOC/18092026/000000000067916.xls', '2026-07-31', 'New som time deposits of individuals with 6-12 month maturity, July 2026 (preliminary); 1-3 years: 12.85%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KG', 1, 'fdr_3m_rate', 0.0778, NULL, 'sourced', 'National Bank of the Kyrgyz Republic, newly accepted deposits by commercial banks (Table 7, individuals, national currency)', 'https://www.nbkr.kg/DOC/18092026/000000000067916.xls', '2026-07-31', 'New som time deposits of individuals with 1-3 month maturity, July 2026 (preliminary).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KG', 1, 'fixed_income_return_base', 0.1, NULL, 'assumption', 'NBKR 6-12 month som deposit rate 11.98% (July 2026), tax-exempt; policy rate 12%', 'https://www.nbkr.kg/DOC/18092026/000000000067916.xls', '2026-10-31', 'Base case: 1-year deposits and bonds pay about 12% today but are assumed to average about 10% as the policy rate eases over a long horizon.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KG', 1, 'fixed_income_return_high', 0.12, NULL, 'assumption', 'NBKR 1-3 year som deposit rate 12.85% (July 2026); 5-year treasury bond yield 15.32%', 'https://www.nbkr.kg/EXCEL/gko_auction_ats_eng.xls', '2026-10-31', 'High case: longer deposits and government bonds keep paying about current rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KG', 1, 'fixed_income_return_low', 0.08, NULL, 'assumption', 'NBKR new som deposit rates July 2026 (1-3 months 7.78%), interest tax-exempt', 'https://www.nbkr.kg/DOC/18092026/000000000067916.xls', '2026-10-31', 'Low case: short deposits around 8% and rates drifting down as inflation moves toward the 5-7% target.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KG', 1, 'goal_inflation_education', 0.1, NULL, 'assumption', 'Kyrgyz CPI education component +22.4% year on year in August 2026 (Trading Economics)', 'https://tradingeconomics.com/kyrgyzstan/inflation-cpi', '2026-10-31', 'Education fees have jumped recently; 10% is used for the long run, two points above the 8% general inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KG', 1, 'goal_inflation_health', 0.1, NULL, 'assumption', 'Kyrgyz CPI health component +15.3% year on year in August 2026 (Trading Economics)', 'https://tradingeconomics.com/kyrgyzstan/inflation-cpi', '2026-10-31', 'Health prices are rising faster than headline CPI; 10% is used for the long run, two points above the 8% general inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KG', 1, 'gold_return_base', 0.08, NULL, 'assumption', 'Gold price history (Trading Economics); som per US dollar (NBKR 87.45, World Bank 2025 average 87.36)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Base case: dollar gold rises about 4% a year and the som loses about 4% a year against the dollar, in line with inflation above US levels.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KG', 1, 'gold_return_high', 0.12, NULL, 'assumption', 'Gold price history (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'High case: a repeat of gold''s strong 2005-2025 trend plus faster som depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KG', 1, 'gold_return_low', 0.03, NULL, 'assumption', 'Gold USD 3,876/oz on 30 Oct 2026, 31% below the January 2026 high', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Low case: gold barely keeps up after the 2025-26 spike, with only modest som depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KG', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No statutory end-of-service gratuity for private employees was found in the sources reviewed (web search budget ran out before the Labour Code could be checked), so it is not marked absent.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KG', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published figure for the typical cost of a private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KG', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published voluntary health insurance premium table was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KG', 1, 'inflation_cpi', 0.122, NULL, 'sourced', 'Trading Economics (National Statistical Committee CPI, September 2026)', 'https://tradingeconomics.com/kyrgyzstan/inflation-cpi', '2026-09-30', '12.2% year on year in September 2026, highest since March 2023 (12.0% in August); secondary source because stat.gov.kg release pages could not be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KG', 1, 'inflation_projection', 0.08, NULL, 'assumption', 'NBKR medium-term inflation target 5-7%; CPI 12.2% (Sep 2026), 8.2% in 2025 (World Bank)', 'https://www.nbkr.kg/index1.jsp?item=2546&lang=ENG', '2026-10-31', 'Inflation has run well above the 5-7% target in most recent years (about 10% on average over five years), so 8% is used for planning rather than the target.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KG', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published term life premium quotes or regulator premium data were found; life insurance is a very small market in Kyrgyzstan.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KG', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The insurance regulator (Finnadzor) publishes no industry life claim settlement ratio that could be found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KG', 1, 'life_expectancy', 72.4, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=KG', '2024-12-31', 'Men 68.4, women 76.6 (World Bank 2024; older than 2025, latest World Bank year); UN WPP 2026 estimate 72.1.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KG', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":17.9,"men":15.9,"women":19.7},{"age":65,"total":14.4,"men":12.7,"women":15.8},{"age":70,"total":11.2,"men":9.9,"women":12.1},{"age":80,"total":6.1,"men":5.5,"women":6.6}]}', 'sourced', 'UN World Population Prospects 2026 life tables, via GeoRank', 'https://georank.org/life-expectancy/kyrgyzstan', '2026-07-01', 'Remaining years = GeoRank''s total life expectancy at each age minus the age (rounded to 0.1 year), from the UN WPP life tables for 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KG', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":65,"womenAge":60,"over90Monthly":null,"meansTested":false}', 'sourced', 'Economist.kg (news), who is entitled to social benefits in Kyrgyzstan', 'https://economist.kg/society/2025/02/28/komu-polozhieny-sotsialnyie-posobiia-v-kyrghyzstanie-i-kak-ikh-oformit/', '2025-02-28', 'Elderly citizens (men from 65, women from 60) who have no right to a contributory pension; the source mentions no income test, but the benefit is paid only to those without a pension. Secondary source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KG', 1, 'old_age_allowance_monthly', 2000, NULL, 'sourced', 'Economist.kg (news), Ministry of Labour draft on social benefits from 2027', 'https://economist.kg/society/2026/10/23/posobiya-kompensatsii-2027/', '2026-10-23', 'Monthly social benefit for elderly people without a right to a pension is 2,000 som; a draft decree would raise it to 3,000 som from 1 January 2027. Secondary source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KG', 1, 'oop_health_share', 0.4226, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS (WHO GHED)', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=KG', '2023-12-31', 'Out-of-pocket spending was 42.3% of current health expenditure in 2023 (older than 2025; latest available).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KG', 1, 'policy_rate', 0.12, NULL, 'sourced', 'National Bank of the Kyrgyz Republic, policy rate', 'https://www.nbkr.kg/index1.jsp?item=123&lang=ENG', '2026-10-27', 'Held at 12.00% on 27 October 2026 (raised from 11% in February 2026); next decision 30 November 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KG', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":63,"nomineeUntilAge":null,"inflationLinked":true,"taxFree":null}', 'sourced', '24.kg (news), citing the Social Fund on the autumn 2026 pension increase', 'https://24.kg/obschestvo/374575_povyishenie_pensii_jdet_kyirgyizstantsev_osenyu_2026_goda/', '2026-05-20', 'State pension social insurance run by the Social Fund (contributory, with a small funded part): pension at 63 for men and 58 for women after at least 6 years of service (economist.kg, January 2026); the Social Fund says pensions are indexed every year taking into account inflation and average wage growth, with the next rise planned for about October 2026; minimum pension 7,100 som and average about 11,300 som in May 2026. Secondary source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KG', 1, 'retirement_accumulation_return_base', 0.1, NULL, 'assumption', 'Equity base 11%; fixed income base 10%', 'https://www.nbkr.kg/DOC/18092026/000000000067916.xls', '2026-10-31', 'Base case: roughly half global shares and half som deposits and bonds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KG', 1, 'retirement_accumulation_return_high', 0.13, NULL, 'assumption', 'Equity high 14%; fixed income high 12%', 'https://www.nbkr.kg/EXCEL/gko_auction_ats_eng.xls', '2026-10-31', 'High case for a growth-leaning balanced mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KG', 1, 'retirement_accumulation_return_low', 0.07, NULL, 'assumption', 'Equity low 6%; fixed income low 8%', 'https://www.nbkr.kg/DOC/18092026/000000000067916.xls', '2026-10-31', 'Low case for a balanced mix of global shares and som deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KG', 1, 'retirement_age_default', 63, NULL, 'sourced', 'Economist.kg (news), citing the Social Fund', 'https://economist.kg/society/2026/01/28/minimalnyi-trudovoi-stazh-dlia-piensii-v-kr-vyros-do-6-liet/', '2026-01-28', 'General pension age is 63 for men and 58 for women; minimum insured service 6 years from 2026, rising to 20 by 2045; early retirement abolished from July 2024. Secondary source because socfond.kg did not respond.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KG', 1, 'retirement_age_government', 65, NULL, 'sourced', 'Kaktus.media (news), citing Article 37(2) of the Law on State Civil Service and Municipal Service', 'https://kaktus.media/doc/486913_mer_bishkeka_dostig_predelnogo_vozrasta_gosslyjashego._bydet_li_prezident_ego_meniat.html', '2023-09-13', '65 is the upper age limit for staying in the civil or municipal service; civil servants draw the state pension from 63 (men) or 58 (women) like other workers. Source is from 2023 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KG', 1, 'retirement_return_base', 0.09, NULL, 'assumption', 'NBKR 6-12 month som deposit rate 11.98% (July 2026), tax-exempt', 'https://www.nbkr.kg/DOC/18092026/000000000067916.xls', '2026-10-31', 'Base case kept well below today''s tax-free 1-year deposit rate of about 12%, since rates are expected to ease over a retirement.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KG', 1, 'retirement_return_high', 0.11, NULL, 'assumption', 'NBKR 1-3 year som deposit rate 12.85%; 5-year treasury bond yield 15.32%', 'https://www.nbkr.kg/EXCEL/gko_auction_ats_eng.xls', '2026-10-31', 'High case: a ladder of longer deposits and government bonds near current rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KG', 1, 'retirement_return_low', 0.07, NULL, 'assumption', 'NBKR new som deposit rates July 2026, interest tax-exempt', 'https://www.nbkr.kg/DOC/18092026/000000000067916.xls', '2026-10-31', 'Low case: short deposits after rates fall toward the inflation target.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KG', 1, 'sanchayapatra_5y_rate', 0.17, NULL, 'sourced', '24.kg (news), government bonds for the population pilot issue', 'https://24.kg/ekonomika/379655_gosudarstvennyie_obligatsii_kak_kyirgyzstantsyi_mogut_zarabotat_bez_lishnego_riska/', '2026-06-26', 'Pilot retail issue of 2-year som treasury bonds (GKO) for individuals ordered in June 2026: 100-som face value, from 1,000 som, fixed 17% coupon paid quarterly, traded on the national stock exchange; secondary source, term is 2 years not 5.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KG', 1, 'savings_account_rate', 0.0306, NULL, 'sourced', 'National Bank of the Kyrgyz Republic, newly accepted deposits by commercial banks (Table 7, individuals, national currency)', 'https://www.nbkr.kg/DOC/18092026/000000000067916.xls', '2026-07-31', 'Weighted average rate on new som demand deposits of individuals in July 2026 (preliminary); demand deposits include ordinary savings and card accounts.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KG', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":10.41}]}', 'sourced', 'World Bank WDI SP.POP.DPND.OL', 'https://data.worldbank.org/indicator/SP.POP.DPND.OL?locations=KG', '2025-12-31', '100 / old-age dependency ratio of 9.60 (2025). UN WPP projects the 65+ share rising from 6.0% to 8.7% in 2040 and 13.3% in 2065 (GeoRank), but no projected 15-64 share was found to compute future ratios.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KG', 1, 'tax_bank_interest', 0, NULL, 'sourced', 'Tax Code of the Kyrgyz Republic, Article 191(7)(1) (text as of 06.08.2026, via prg.kz)', 'https://prg.kz/m/amp/document/31756556/14/1980000', '2026-08-06', 'Interest on deposits and on balances of current, card and other bank accounts is exempt from personal income tax; secondary copy of the code because the official legal database (cbd.minjust.gov.kg) is script-only.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KG', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'Article 191(7)(2) of the Tax Code exempts interest on securities in the top listing categories of the national stock exchange, but whether the retail treasury bonds qualify could not be confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KG', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Ministry of Finance has not auctioned 3-month treasury bills since January 2020 (NBKR auction file https://www.nbkr.kg/EXCEL/gkv_auction_ats_eng.xls); the last 12-month bill auction in that file was in June 2024.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KG', 1, 'tbond_10y_rate', 0.16, NULL, 'sourced', 'National Bank of the Kyrgyz Republic, auctions of State Treasury Bonds (10-year)', 'https://www.nbkr.kg/EXCEL/gko_auction_ats_eng.xls', '2026-10-23', 'Yield at the 23 October 2026 auction of 10-year bonds (8% coupon); unchanged at 16% through September-October 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KG', 1, 'tbond_5y_rate', 0.1532, NULL, 'sourced', 'National Bank of the Kyrgyz Republic, auctions of State Treasury Bonds (5-year)', 'https://www.nbkr.kg/EXCEL/gko_auction_ats_eng.xls', '2026-10-16', 'Weighted average yield at the 16 October 2026 auction of 5-year bonds (6% coupon); 15.34-15.38% at the other October auctions.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('KH', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"KH","iso3":"KHM","nameEn":"Cambodia","nameNative":"កម្ពុជា","region":"east_asia_pacific","languages":["km","en"],"currency":{"code":"KHR","symbol":"៛","decimals":2,"compact":"intl","usdRate":{"value":4081,"status":"sourced","sourceName":"National Bank of Cambodia official exchange rate (published by the General Department of Taxation)","sourceUrl":"https://www.tax.gov.kh/en/exchange-rate","asOf":"2026-10-30","note":"The US dollar is widely used alongside the riel."}},"instruments":{"savings_account":{"available":true,"localName":"គណនីសន្សំ","localNameEn":"Savings account","sourceUrl":"https://tradingeconomics.com/cambodia/interest-rate"},"fdr_3m":{"available":true,"localName":"ប្រាក់បញ្ញើមានកាលកំណត់","localNameEn":"Fixed deposit","sourceUrl":null},"fdr_1y":{"available":true,"localName":"ប្រាក់បញ្ញើមានកាលកំណត់","localNameEn":"Fixed deposit","sourceUrl":null},"dps":{"available":true,"localName":"គណនីសន្សំប្រចាំខែ","localNameEn":"Monthly savings plan","note":"Offered by some banks in riel and dollars; no published average rate."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate or retail savings bond."},"tbill_91d":{"available":false,"localName":null,"localNameEn":null,"note":"No treasury bills; shortest government bond is 1 year."},"tbond_5y":{"available":true,"localName":"មូលបត្របំណុលរដ្ឋ","localNameEn":"Government bond","note":"Riel government bonds (1, 2, 3, 5, 10, 15 years) are auctioned by the Ministry of Economy and Finance on the NBC platform.","sourceUrl":"https://en.vietstock.vn/2026/01/nbc-supports-govt-bond-market-with-410b-riel-and-70m-52000-628833.htm"},"tbond_10y":{"available":true,"localName":"មូលបត្របំណុលរដ្ឋ","localNameEn":"Government bond","note":"Auctioned on the NBC platform; secondary market is thin.","sourceUrl":"https://en.vietstock.vn/2026/01/nbc-supports-govt-bond-market-with-410b-riel-and-70m-52000-628833.htm"},"equity_fund":{"available":true,"localName":"មូលនិធិវិនិយោគរួម","localNameEn":"Collective investment scheme","note":"Few licensed retail funds; the local stock exchange is small."},"gold":{"available":true,"localName":"មាស","localNameEn":"Gold","note":"Physical gold is widely bought at markets and gold shops."}},"institutions":{"centralBank":{"name":"National Bank of Cambodia (NBC)","url":"https://www.nbc.gov.kh/"},"insuranceRegulator":{"name":"Insurance Regulator of Cambodia (IRC)","url":"https://www.irc.gov.kh/"},"insuranceComplaints":{"name":"Insurance Regulator of Cambodia (IRC)","url":"https://www.irc.gov.kh/","note":"Complaints about insurers go to the regulator."},"pensionScheme":{"name":"National Social Security Fund (NSSF), pension scheme","url":"https://www.nssf.gov.kh/"},"oldAgeAllowance":null,"publicHealthCover":{"name":"Ministry of Health (Health Equity Fund for poor households; NSSF health care for workers)","url":"https://moh.gov.kh/"},"depositInsurance":null,"statistics":{"name":"National Institute of Statistics (NIS), Ministry of Planning","url":"https://nis.gov.kh/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KH', 1, 'bank_deposit_avg_rate', 0.0129, NULL, 'sourced', 'World Bank WDI, deposit interest rate (FR.INR.DPST)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=KH', '2025-12-31', '1.29% for 2025. Trading Economics reports a simple average riel savings deposit rate of the 10 largest banks of 1.21% for June 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KH', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'NBC''s 18% a year cap (Prakas B7-017-109, 2017) covers microfinance lenders only; we found no cap or published typical rate for bank credit cards.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KH', 1, 'deposit_insurance_limit', 0, NULL, 'sourced', 'Cambodia Investment Review, AMRO report on bank liquidity (July 2026)', 'https://cambodiainvestmentreview.com/2026/07/28/amro-warns-cambodia-banks-dollar-liquidity-buffers-have-fallen-to-record-low-in-2026-as-funds-shift-overseas/', '2026-07-28', 'No formal deposit insurance scheme exists in Cambodia (AMRO, as reported July 2026: ''no formal deposit insurance scheme currently exists''), so the limit is 0.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KH', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Banks sell monthly recurring savings plans in riel and dollars, but we could not read a current published rate page (bank pages blocked).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KH', 1, 'equity_return_base', 0.055, NULL, 'assumption', 'After-tax 1-year government bond yield (about 2.9%) plus a modest premium', 'https://en.vietstock.vn/2026/01/nbc-supports-govt-bond-market-with-410b-riel-and-70m-52000-628833.htm', '2026-10-31', 'Weak, thin local market: base set about 2.5 points above the after-tax 1-year government bond yield, under the 4-point limit.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KH', 1, 'equity_return_high', 0.09, NULL, 'assumption', 'After-tax safe rate plus a full equity premium', 'https://en.vietstock.vn/2026/01/nbc-supports-govt-bond-market-with-410b-riel-and-70m-52000-628833.htm', '2026-10-31', 'High case if listings deepen and regional equity returns are achieved.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KH', 1, 'equity_return_low', 0, NULL, 'assumption', 'Cambodia Securities Exchange record; government bond yields (NBC Annual Report 2025)', 'https://en.vietstock.vn/2026/01/nbc-supports-govt-bond-market-with-410b-riel-and-70m-52000-628833.htm', '2026-10-31', 'The local exchange is small and illiquid with a weak record since its 2018 high, so the low case is zero in riel terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KH', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'NBC tenor-level deposit rates were not reachable (nbc.gov.kh returned 403); the only published 12-month riel term deposit rates found were individual banks'' own pages (about 4.1% at a large bank, Oct 2026), which we do not cite.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KH', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'NBC tenor-level deposit rates were not reachable (nbc.gov.kh returned 403); the only published 3-month riel term deposit rates found were individual banks'' own pages (about 2.7% at a large bank, Oct 2026), which we do not cite.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KH', 1, 'fixed_income_return_base', 0.029, NULL, 'assumption', 'Government bond yields, NBC Annual Report 2025 (via Vietstock)', 'https://en.vietstock.vn/2026/01/nbc-supports-govt-bond-market-with-410b-riel-and-70m-52000-628833.htm', '2026-10-31', 'Base case at the 1-year government bond yield (3.15%) less withholding tax. Safe KHR rates: average deposit rate 1.29% (World Bank, 2025); government bonds, average winning yields in 2025: 1-year 3.15%, 3-year 3.99%, 5-year 4.50% (NBC Annual Report 2025); interest is subject to a withholding tax of a few percent.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KH', 1, 'fixed_income_return_high', 0.042, NULL, 'assumption', 'Government bond yields, NBC Annual Report 2025 (via Vietstock)', 'https://en.vietstock.vn/2026/01/nbc-supports-govt-bond-market-with-410b-riel-and-70m-52000-628833.htm', '2026-10-31', 'High case near the 5-year government bond yield (4.5%) less withholding tax. Safe KHR rates: average deposit rate 1.29% (World Bank, 2025); government bonds, average winning yields in 2025: 1-year 3.15%, 3-year 3.99%, 5-year 4.50% (NBC Annual Report 2025); interest is subject to a withholding tax of a few percent.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KH', 1, 'fixed_income_return_low', 0.012, NULL, 'assumption', 'Average bank deposit rate (World Bank FR.INR.DPST)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=KH', '2026-10-31', 'Low case near the average riel deposit rate. Safe KHR rates: average deposit rate 1.29% (World Bank, 2025); government bonds, average winning yields in 2025: 1-year 3.15%, 3-year 3.99%, 5-year 4.50% (NBC Annual Report 2025); interest is subject to a withholding tax of a few percent.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KH', 1, 'goal_inflation_education', 0.05, NULL, 'assumption', 'NBC CPI education sub-index (via Trading Economics)', 'https://tradingeconomics.com/cambodia/cpi-education', '2026-10-31', 'The education index (186.9, Sep 2026) has risen much faster than the headline CPI over time, so we plan 2 points above general inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KH', 1, 'goal_inflation_health', 0.05, NULL, 'assumption', 'NBC CPI health sub-index (via Trading Economics)', 'https://tradingeconomics.com/cambodia/cpi-health', '2026-10-31', 'Health CPI is flat in 2026, but with 61% of health spending out of pocket and private care growing, we plan 2 points above general inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KH', 1, 'gold_return_base', 0.05, NULL, 'assumption', 'US-dollar gold trend; managed KHR/USD rate (NBC official rate via GDT)', 'https://www.tax.gov.kh/en/exchange-rate', '2026-10-31', 'Long-run dollar gold trend of about 5% with little expected riel depreciation against the dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KH', 1, 'gold_return_high', 0.09, NULL, 'assumption', 'US-dollar gold trend; managed KHR/USD rate (NBC official rate via GDT)', 'https://www.tax.gov.kh/en/exchange-rate', '2026-10-31', 'High case for a strong gold cycle.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KH', 1, 'gold_return_low', 0.01, NULL, 'assumption', 'US-dollar gold trend; managed KHR/USD rate (NBC official rate via GDT)', 'https://www.tax.gov.kh/en/exchange-rate', '2026-10-31', 'Gold can stall for a decade; the riel is held near 4,000-4,100 per dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KH', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'A statutory seniority indemnity exists (Prakas 443 of 2018: 15 days of wages a year, paid half-yearly), but we found it only in law-firm summaries; the ILO EPLex page was blocked (403), so the rule is not cited.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KH', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a major private hospital stay found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KH', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premium rates or guides found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KH', 1, 'inflation_cpi', 0.053, NULL, 'sourced', 'National Bank of Cambodia CPI (via Trading Economics)', 'https://tradingeconomics.com/cambodia/inflation-cpi', '2026-09-30', '5.3% year on year in September 2026, up from 4.8% in August; NBC and NIS pages were not reachable, so a secondary source is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KH', 1, 'inflation_projection', 0.03, NULL, 'assumption', '5-year CPI average (World Bank FP.CPI.TOTL.ZG, Trading Economics); NBC has no inflation target', 'https://tradingeconomics.com/cambodia/inflation-cpi', '2026-10-31', 'CPI averaged about 2.7% over 2021-2025 but is above 5% in 2026, so we plan with a rounded 3%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KH', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life cover is sold, but we found no published premium rates or credible premium guide in riel.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KH', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Insurance Regulator of Cambodia publishes premiums and claims totals but we found no claim settlement ratio.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KH', 1, 'life_expectancy', 70.8, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN)', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=KH', '2024-12-31', 'Men 68.1, women 73.4 (2024). Figure refers to 2024, older than 2025; it is the latest available.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KH', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":19,"men":17.8,"women":19.9},{"age":65,"total":15.3,"men":14.3,"women":16},{"age":70,"total":12,"men":11.2,"women":12.5},{"age":80,"total":6.6,"men":6.2,"women":6.9}]}', 'sourced', 'UN World Population Prospects (via georank.org)', 'https://georank.org/life-expectancy/cambodia', '2026-07-08', 'Remaining years derived from expected age at death by current age; secondary source because the WHO GHO API was unavailable.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KH', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'Elderly cash transfer is part of the Family Package for IDPoor (means-tested) households; current age rules and amounts not found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KH', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'No universal social pension; poor elderly in IDPoor households get a cash transfer under the Family Package of social assistance, but we could not find the current amount.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KH', 1, 'oop_health_share', 0.606, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure, SH.XPD.OOPC.CH.ZS)', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=KH', '2023-12-31', 'Figure refers to 2023, older than 2025; it is the latest available.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KH', 1, 'policy_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The National Bank of Cambodia does not set an official policy rate (Trading Economics uses the average savings deposit rate as a benchmark instead).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KH', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":60,"nomineeUntilAge":null,"inflationLinked":true,"taxFree":null}', 'sourced', 'Sub-decree 32 on the Social Security Scheme on Pension (NSSF), unofficial translation', 'https://ibccambodia.com/wp-content/uploads/2021/05/Sub-decree-32-on-Social-Security-Scheme-on-Pension-Eng.pdf', '2021-03-01', 'NSSF pension for workers under the Labour Law (from Oct 2022): 2% employee plus 2% employer, rising to 5.37% each by 2041 (ISSA); accrual 1.75% a year for the first 15 years and 1.25% after, capped at 70%; benefits adjusted yearly by the official commodity price index (Sub-decree 32, ch. on benefit adjustment). Sub-decree dates from 2021, older than 2025, and is still in force.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KH', 1, 'retirement_accumulation_return_base', 0.042, NULL, 'assumption', 'Mix of riel deposits, government bonds and equity', 'https://en.vietstock.vn/2026/01/nbc-supports-govt-bond-market-with-410b-riel-and-70m-52000-628833.htm', '2026-10-31', 'About half equity at 5.5% and half bonds/deposits near 2.9%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KH', 1, 'retirement_accumulation_return_high', 0.065, NULL, 'assumption', 'Mix of riel deposits, government bonds and equity', 'https://en.vietstock.vn/2026/01/nbc-supports-govt-bond-market-with-410b-riel-and-70m-52000-628833.htm', '2026-10-31', 'About 60% equity at the high case and 40% bonds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KH', 1, 'retirement_accumulation_return_low', 0.02, NULL, 'assumption', 'Mix of riel deposits, government bonds and equity', 'https://en.vietstock.vn/2026/01/nbc-supports-govt-bond-market-with-410b-riel-and-70m-52000-628833.htm', '2026-10-31', 'About 40% equity at the low case and 60% deposits and bonds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KH', 1, 'retirement_age_default', 60, NULL, 'sourced', 'ISSA country profile Cambodia 2022: Old-age pension, Social Security (NSSF)', 'https://www.issa.int/sites/default/files/documents/2024-01/Cambodia%202022%20-%20ISSA%20country%20profile.pdf', '2022-12-31', 'Old-age pension from age 60 with at least 12 months of contributions, same for men and women; ISSA lists no legislated increase, so 60 also applies to people born after 1975 (Sub-decree 32 of 2021, Art. 13). Profile reflects 2022 policies, older than 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KH', 1, 'retirement_age_government', 60, NULL, 'sourced', 'Open Development Cambodia, Ministry of Civil Service Letter 5420 (25 Nov 2019)', 'https://opendevelopmentcambodia.net/news/government-raises-retirement-age-for-civil-servants-to-60/', '2019-11-25', 'All civil servants retire at 60 regardless of framework (previously 55, 58 or 60). Figure refers to 2019, older than 2025; it is the latest available.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KH', 1, 'retirement_return_base', 0.029, NULL, 'assumption', 'Government bond yields, NBC Annual Report 2025 (via Vietstock)', 'https://en.vietstock.vn/2026/01/nbc-supports-govt-bond-market-with-410b-riel-and-70m-52000-628833.htm', '2026-10-31', 'Base case at the after-tax 1-year government bond yield (3.15% less withholding), the safe rate a retiree can lock in. Safe KHR rates: average deposit rate 1.29% (World Bank, 2025); government bonds, average winning yields in 2025: 1-year 3.15%, 3-year 3.99%, 5-year 4.50% (NBC Annual Report 2025); interest is subject to a withholding tax of a few percent.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KH', 1, 'retirement_return_high', 0.042, NULL, 'assumption', 'Government bond yields, NBC Annual Report 2025 (via Vietstock)', 'https://en.vietstock.vn/2026/01/nbc-supports-govt-bond-market-with-410b-riel-and-70m-52000-628833.htm', '2026-10-31', 'High case near the after-tax 5-year government bond yield. Safe KHR rates: average deposit rate 1.29% (World Bank, 2025); government bonds, average winning yields in 2025: 1-year 3.15%, 3-year 3.99%, 5-year 4.50% (NBC Annual Report 2025); interest is subject to a withholding tax of a few percent.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KH', 1, 'retirement_return_low', 0.012, NULL, 'assumption', 'Average bank deposit rate (World Bank FR.INR.DPST)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=KH', '2026-10-31', 'Low case near the average riel deposit rate. Safe KHR rates: average deposit rate 1.29% (World Bank, 2025); government bonds, average winning yields in 2025: 1-year 3.15%, 3-year 3.99%, 5-year 4.50% (NBC Annual Report 2025); interest is subject to a withholding tax of a few percent.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KH', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Cambodia has no government savings certificate or retail savings bond; government bonds are auctioned on the NBC platform (see tbond rates).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KH', 1, 'savings_account_rate', 0.0041, NULL, 'sourced', 'National Bank of Cambodia average saving deposit rate (via Trading Economics)', 'https://tradingeconomics.com/cambodia/interest-rate', '2026-07-31', 'Average savings deposit rate, July 2026; secondary source because the NBC site was not reachable.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KH', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":10.1},{"year":2040,"value":7.5},{"year":2065,"value":4.2}]}', 'sourced', 'UN World Population Prospects 2024, medium variant (via populationpyramid.net); World Bank SP.POP.DPND.OL', 'https://www.populationpyramid.net/cambodia/2040/', '2024-07-31', '100 / old-age dependency ratio: 9.9 in 2025 (World Bank), 13.3 in 2040 and 24.0 in 2065 (UN WPP 2024). Figure refers to 2024, older than 2025; it is the latest available.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KH', 1, 'tax_bank_interest', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Law on Taxation sets a final withholding tax on bank interest paid to resident individuals (commonly reported as 6% on term deposits and 4% on savings accounts), but we found it only on bank and law-firm pages; PwC Tax Summaries for Cambodia does not state it.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KH', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate exists. MEF Notification 007 (21 Jul 2026) reportedly halves withholding on interest from 2026 government securities to 3% for residents, but only a law-firm summary was found, not the official text.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KH', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Cambodia issues no 91-day treasury bills; the shortest government bond is 1 year (2.75% average coupon in 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KH', 1, 'tbond_10y_rate', 0.046, NULL, 'sourced', 'National Bank of Cambodia Annual Report 2025, average coupon on 10-year government bonds (via Vietstock / Khmer Times)', 'https://en.vietstock.vn/2026/01/nbc-supports-govt-bond-market-with-410b-riel-and-70m-52000-628833.htm', '2025-12-31', 'Average coupon 4.60% in 2025; no yield published, coupons are set at auction.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KH', 1, 'tbond_5y_rate', 0.045, NULL, 'sourced', 'National Bank of Cambodia Annual Report 2025, average winning bid yield on 5-year government bonds (via Vietstock / Khmer Times)', 'https://en.vietstock.vn/2026/01/nbc-supports-govt-bond-market-with-410b-riel-and-70m-52000-628833.htm', '2025-12-31', 'Average coupon 4.21%, average winning yield 4.50% in 2025.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('KI', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"KI","iso3":"KIR","nameEn":"Kiribati","nameNative":"Kiribati","region":"east_asia_pacific","languages":["gil","en"],"currency":{"code":"AUD","symbol":"$","decimals":2,"compact":"intl","usdRate":{"value":1.4205,"status":"sourced","sourceName":"Reserve Bank of Australia, AUD/USD 0.7040 (Kiribati uses the Australian dollar)","sourceUrl":"https://www.rba.gov.au/statistics/frequency/exchange-rates.html","asOf":"2026-10-30","note":"1 / 0.7040 US dollars per Australian dollar."}},"instruments":{"savings_account":{"available":true,"localName":null,"localNameEn":"Savings account"},"fdr_3m":{"available":true,"localName":null,"localNameEn":"3-month term deposit"},"fdr_1y":{"available":true,"localName":null,"localNameEn":"1-year term deposit"},"dps":{"available":false,"localName":null,"note":"No recurring deposit scheme offered."},"sanchayapatra_5y":{"available":false,"localName":null,"note":"No government savings certificates or retail bonds."},"tbill_91d":{"available":false,"localName":null,"note":"No domestic treasury bill market."},"tbond_5y":{"available":false,"localName":null,"note":"No domestic government bond market."},"tbond_10y":{"available":false,"localName":null,"note":"No domestic government bond market."},"equity_fund":{"available":false,"localName":null,"note":"No stock exchange or locally sold retail funds; only foreign funds bought abroad."},"gold":{"available":false,"localName":null,"note":"No local bullion dealers; gold would have to be bought abroad."}},"institutions":{"centralBank":null,"insuranceRegulator":null,"insuranceComplaints":null,"pensionScheme":{"name":"Kiribati Provident Fund","url":"https://www.kpf.com.ki/","note":"Mandatory provident fund for employees; lump sum from age 50."},"oldAgeAllowance":{"name":"Ministry of Women, Youth, Sports and Social Affairs (Senior Citizens Allowance)","url":"https://www.kiribati.gov.ki/","note":"Universal allowance for citizens 60+; the ministry has no separate website, so this links to the government portal."},"publicHealthCover":{"name":"Ministry of Health and Medical Services","url":"https://www.mhms.gov.ki/","note":"Free public health care, with overseas referral."},"depositInsurance":null,"statistics":{"name":"Kiribati National Statistics Office","url":"https://nso.gov.ki/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KI', 1, 'bank_deposit_avg_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published weighted average deposit rate (no central bank; World Bank FR.INR.DPST has no Kiribati value).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KI', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap or published credit card rate found for Kiribati.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KI', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No deposit insurance scheme found for Kiribati (searched ADB Pacific finance sector brief, Ministry of Finance); likely none.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KI', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No monthly recurring deposit product found on Kiribati bank rate sheets.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KI', 1, 'equity_return_base', 0.05, NULL, 'assumption', 'Global equity in AUD, capped at the local safe rate (about 1% on 12-month deposits) plus 4 points', 'https://www.rba.gov.au/statistics/frequency/exchange-rates.html', '2026-10-31', 'Kiribati has no stock exchange, so equity means a global index held in AUD; the base is held to the roughly 1% safe rate plus about 4 points.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KI', 1, 'equity_return_high', 0.08, NULL, 'assumption', 'Long-run global equity return in AUD terms', 'https://www.rba.gov.au/statistics/frequency/exchange-rates.html', '2026-10-31', 'High case close to the long-run nominal return of global equities in Australian dollars.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KI', 1, 'equity_return_low', 0.02, NULL, 'assumption', 'No local stock market; global equity index in Australian dollar terms', 'https://www.rba.gov.au/statistics/frequency/exchange-rates.html', '2026-10-31', 'Low case for a global index fund held in AUD after weak decades and currency swings.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KI', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Only a commercial bank''s own rate sheet publishes this (about 1.15% for 12 months in Sep 2026); company pages are not used as sources and no official deposit rate series exists for Kiribati.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KI', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Only a commercial bank''s own rate sheet publishes this (about 0.60% for 90-179 days in Sep 2026); company pages are not used as sources and no official deposit rate series exists for Kiribati.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KI', 1, 'fixed_income_return_base', 0.01, NULL, 'assumption', 'Local 12-month term deposits pay about 1% (bank rate sheets, Sep 2026; not cited as they are company pages); no government bills or bonds (IMF 2026 Article IV)', 'https://www.imf.org/en/news/articles/2026/05/14/pr26153-kiribati-imf-executive-board-concludes-2026-article-iv-consultation', '2026-10-31', 'Base close to the roughly 1% 12-month deposit rate; the first A$250 of interest is tax-exempt, so tax drag is small for most savers.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KI', 1, 'fixed_income_return_high', 0.02, NULL, 'assumption', 'Local 12-month term deposits pay about 1% (bank rate sheets, Sep 2026; not cited as they are company pages); no government bills or bonds (IMF 2026 Article IV)', 'https://www.imf.org/en/news/articles/2026/05/14/pr26153-kiribati-imf-executive-board-concludes-2026-article-iv-consultation', '2026-10-31', 'High case if Australian-linked deposit rates rise.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KI', 1, 'fixed_income_return_low', 0.005, NULL, 'assumption', 'Local 12-month term deposits pay about 1% (bank rate sheets, Sep 2026; not cited as they are company pages); no government bills or bonds (IMF 2026 Article IV)', 'https://www.imf.org/en/news/articles/2026/05/14/pr26153-kiribati-imf-executive-board-concludes-2026-article-iv-consultation', '2026-10-31', 'Low case near current savings and short deposit rates (about 0.1-0.6%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KI', 1, 'goal_inflation_education', 0.04, NULL, 'assumption', 'Headline CPI planning rate; schooling is free and compulsory', 'https://www.un.org/development/desa/pd/sites/www.un.org.development.desa.pd/files/undesa_pd_2024_cpd57_statement_kiribati.pdf', '2026-10-31', 'No education CPI is published; education is free in public schools, so the headline 4% assumption is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KI', 1, 'goal_inflation_health', 0.04, NULL, 'assumption', 'Headline CPI planning rate; public health care is free', 'https://nso.gov.ki/economy/cpi/kiribati-consumer-price-index-for-2026-q1-released/', '2026-10-31', 'No medical CPI is published and public care is free, so health costs are planned at the headline 4% assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KI', 1, 'gold_return_base', 0.05, NULL, 'assumption', 'Gold in AUD; long-run USD gold trend about 5% plus little expected AUD depreciation', 'https://www.rba.gov.au/statistics/frequency/exchange-rates.html', '2026-10-31', 'Kiribati uses the Australian dollar, so gold return is the USD gold trend with no big local currency depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KI', 1, 'gold_return_high', 0.08, NULL, 'assumption', 'Gold in AUD; strong-decade case', 'https://www.rba.gov.au/statistics/frequency/exchange-rates.html', '2026-10-31', 'High case for a strong gold decade or AUD weakness.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KI', 1, 'gold_return_low', 0.01, NULL, 'assumption', 'Gold in AUD; long-run USD gold trend and AUD/USD rate', 'https://www.rba.gov.au/statistics/frequency/exchange-rates.html', '2026-10-31', 'Gold can stagnate for a decade in real terms; low case barely positive in AUD.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KI', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No general end-of-service gratuity law found; the Employment and Industrial Relations Code 2015 provides redundancy severance whose formula (s100) could not be verified.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KI', 1, 'health_hospitalisation_cost', 0, NULL, 'sourced', 'Government of Kiribati statement to UN Commission on Population and Development (2024)', 'https://www.un.org/development/desa/pd/sites/www.un.org.development.desa.pd/files/undesa_pd_2024_cpd57_statement_kiribati.pdf', '2024-04-30', 'Government statement: health care is free for all cases treatable locally, with overseas referral for non-terminal patients; out-of-pocket share is about 3% of health spending. Source dated 2024 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KI', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No private health insurance market found in Kiribati; public care is free.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KI', 1, 'inflation_cpi', 0.007, NULL, 'sourced', 'Kiribati National Statistics Office, CPI March 2026', 'https://nso.gov.ki/economy/cpi/kiribati-consumer-price-index-for-2026-q1-released/', '2026-03-31', 'All-items index 110.32 (Mar 2025) to 111.04 (Mar 2026). IMF puts 2025 average CPI at 6.5% and projects 4.5% for 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KI', 1, 'inflation_projection', 0.04, NULL, 'assumption', 'IMF 2026 Article IV (2024-26 CPI 2.5%, 6.5%, 4.5%); Australian dollar user', 'https://www.imf.org/en/news/articles/2026/05/14/pr26153-kiribati-imf-executive-board-concludes-2026-article-iv-consultation', '2026-10-31', 'Kiribati uses the Australian dollar (RBA target 2-3%) but imported food and fuel kept its CPI near 4-5% on average over the last five years, so 4% is a rounded planning figure.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KI', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published pure term life premium rates in Kiribati; the state insurer holds a statutory monopoly (Insurance Act 1981) and publishes no rate tables.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KI', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No insurance regulator statistics on claim settlement published for Kiribati.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KI', 1, 'life_expectancy', 66.6, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=KI', '2024-12-31', 'Men 64.7, women 68.3 (2024).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KI', 1, 'life_table_remaining', NULL, '{"rows":[{"age":65,"total":13.45},{"age":80,"total":5.68}]}', 'sourced', 'UN World Population Prospects 2024 via Measured World', 'https://measuredworld.com/countries/kiribati/mortality/life-expectancy-progression', '2024-12-31', 'Secondary source reproducing UN WPP 2024; ages 60 and 70 and sex breakdown not found (WHO GHO API unavailable).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KI', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":60,"womenAge":60,"over90Monthly":null,"meansTested":false}', 'sourced', 'Government of Kiribati statement to UN Commission on Population and Development (2024)', 'https://www.un.org/development/desa/pd/sites/www.un.org.development.desa.pd/files/undesa_pd_2024_cpd57_statement_kiribati.pdf', '2024-04-30', 'Statement: senior citizens aged 60 and over are entitled to the allowance; no means test is mentioned. ISSA 2022 still lists the older 2004 rule (age 65, A$50-60 a month), which the 2024 government statement supersedes. Source dated 2024 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KI', 1, 'old_age_allowance_monthly', 217, NULL, 'sourced', 'Government of Kiribati statement to UN Commission on Population and Development (2024)', 'https://www.un.org/development/desa/pd/sites/www.un.org.development.desa.pd/files/undesa_pd_2024_cpd57_statement_kiribati.pdf', '2024-04-30', 'The government''s 2024 statement says citizens aged 60 and over receive $100 a fortnight, i.e. about A$217 a month (100 x 26 / 12). Source dated 2024 (older than 2025); the 2020 Act and later budget figures could not be read directly.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KI', 1, 'oop_health_share', 0.029, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=KI', '2023-12-31', NULL, 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KI', 1, 'policy_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Kiribati has no central bank or monetary policy of its own; it uses the Australian dollar, so the Reserve Bank of Australia cash rate applies indirectly.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KI', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":50,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'ISSA country profile: Kiribati (policies as of 1 January 2022)', 'https://www.issa.int/sites/default/files/documents/2024-01/Kiribati%202022%20-%20ISSA%20country%20profile.pdf', '2022-01-01', 'Kiribati Provident Fund: employees and employers each pay 7.5% of gross wages; paid as a lump sum (not a pension) from age 50; interest set yearly by the board (5% in 2017 per ISSA; fund site shows 5.5% for FY2021-22). ISSA profile is as of 2022 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KI', 1, 'retirement_accumulation_return_base', 0.035, NULL, 'assumption', 'Kiribati Provident Fund crediting rate (ISSA 2022 profile: 5% in 2017, board reviews yearly, minimum 4%; fund site shows 5.5% for FY2021-22)', 'https://www.issa.int/sites/default/files/documents/2024-01/Kiribati%202022%20-%20ISSA%20country%20profile.pdf', '2026-10-31', 'A balanced mix of about 1% deposits and about 5% global equity in AUD gives roughly 3.5%, below the provident fund''s recent crediting rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KI', 1, 'retirement_accumulation_return_high', 0.05, NULL, 'assumption', 'Kiribati Provident Fund crediting rate (ISSA 2022 profile: 5% in 2017, board reviews yearly, minimum 4%; fund site shows 5.5% for FY2021-22)', 'https://www.issa.int/sites/default/files/documents/2024-01/Kiribati%202022%20-%20ISSA%20country%20profile.pdf', '2026-10-31', 'High case in line with the provident fund''s recent crediting rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KI', 1, 'retirement_accumulation_return_low', 0.02, NULL, 'assumption', 'Kiribati Provident Fund crediting rate (ISSA 2022 profile: 5% in 2017, board reviews yearly, minimum 4%; fund site shows 5.5% for FY2021-22)', 'https://www.issa.int/sites/default/files/documents/2024-01/Kiribati%202022%20-%20ISSA%20country%20profile.pdf', '2026-10-31', 'Low case for a mix of local deposits and global funds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KI', 1, 'retirement_age_default', 50, NULL, 'sourced', 'ISSA country profile: Kiribati (policies as of 1 January 2022)', 'https://www.issa.int/sites/default/files/documents/2024-01/Kiribati%202022%20-%20ISSA%20country%20profile.pdf', '2022-01-01', 'No statutory pension age; the Kiribati Provident Fund pays its old-age lump sum from age 50 (early withdrawal at 45 if retired). Policies as of 1 January 2022 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KI', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'A 2016 amendment reportedly raised the public-service retirement age from 50 to 55, but the act on PacLII returns 403 and no other source could be read to confirm it.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KI', 1, 'retirement_return_base', 0.01, NULL, 'assumption', 'Local 12-month term deposits pay about 1% (bank rate sheets, Sep 2026; not cited as they are company pages); no government bills or bonds (IMF 2026 Article IV)', 'https://www.imf.org/en/news/articles/2026/05/14/pr26153-kiribati-imf-executive-board-concludes-2026-article-iv-consultation', '2026-10-31', 'Held at about the 1% 12-month deposit rate, the best safe rate available locally.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KI', 1, 'retirement_return_high', 0.02, NULL, 'assumption', 'Local 12-month term deposits pay about 1% (bank rate sheets, Sep 2026; not cited as they are company pages); no government bills or bonds (IMF 2026 Article IV)', 'https://www.imf.org/en/news/articles/2026/05/14/pr26153-kiribati-imf-executive-board-concludes-2026-article-iv-consultation', '2026-10-31', 'High case if deposit rates rise or part is held in higher-yield deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KI', 1, 'retirement_return_low', 0.005, NULL, 'assumption', 'Local 12-month term deposits pay about 1% (bank rate sheets, Sep 2026; not cited as they are company pages); no government bills or bonds (IMF 2026 Article IV)', 'https://www.imf.org/en/news/articles/2026/05/14/pr26153-kiribati-imf-executive-board-concludes-2026-article-iv-consultation', '2026-10-31', 'Low case near short deposit rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KI', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Kiribati government does not sell savings certificates or retail bonds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KI', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Only a commercial bank''s own rate sheet publishes this (about 0.10% in Sep 2026); company pages are not used as sources and no central bank or statistics office publishes deposit rates for Kiribati.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KI', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":14},{"year":2040,"value":10.2},{"year":2065,"value":6.5}]}', 'sourced', 'UN WPP 2024 medium variant via PopulationPyramid.net; World Bank SP.POP.DPND.OL', 'https://www.populationpyramid.net/kiribati/2040/', '2025-12-31', '100 / old-age dependency ratio: 7.14 (2025, World Bank SP.POP.DPND.OL), 9.8 (2040) and 15.5 (2065, populationpyramid.net/kiribati/2065/).', 0);
