INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('KM', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"KM","iso3":"COM","nameEn":"Comoros","nameNative":"Komori","region":"sub_saharan_africa","languages":["zdj","wni","fr","ar"],"currency":{"code":"KMF","symbol":"CF","decimals":0,"compact":"intl","usdRate":{"value":435.376,"status":"sourced","sourceName":"World Bank WDI, official exchange rate (PA.NUS.FCRF), Comoros","sourceUrl":"https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=KM","asOf":"2025-12-31","note":"2025 average. The Comorian franc is fixed at 491.96775 per euro (BCC), so the dollar rate moves with the euro."}},"instruments":{"savings_account":{"available":true,"localName":"Compte d''épargne","localNameEn":"Savings account","note":"Banks must pay at least the BCC minimum rate of 2.5% on savings deposits.","sourceUrl":"https://banque-comores.km/page/show/taux-dinteret-de-la-bcc"},"fdr_3m":{"available":true,"localName":"Dépôt à terme (3 mois)","localNameEn":"Term deposit (3 months)","note":"Banks take term deposits (the BCC counts term savings in money supply), but rates are not published."},"fdr_1y":{"available":true,"localName":"Dépôt à terme (1 an)","localNameEn":"Term deposit (1 year)","note":"Banks take term deposits, but rates are not published."},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No standard monthly recurring deposit product was found."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate for individuals was found."},"tbill_91d":{"available":false,"localName":"Bons du Trésor","localNameEn":"Treasury bills","note":"Only 28-day Treasury bills are issued, by BCC auction to banks.","sourceUrl":"https://banque-comores.km/article/show/annonce-du-resultat-global-de-ladjudication-de-lappel-doffres-demission-de-bons-du-tresor-n00042026-du-31-aout-2026"},"tbond_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No domestic government bond market was found."},"tbond_10y":{"available":false,"localName":null,"localNameEn":null,"note":"No domestic government bond market was found."},"equity_fund":{"available":false,"localName":null,"localNameEn":null,"note":"There is no stock exchange in the Comoros and no locally sold equity fund was found; investors can only use foreign funds."},"gold":{"available":true,"localName":"Or","localNameEn":"Gold","note":"Gold is sold mainly as jewellery; the BCC publishes gold prices.","sourceUrl":"https://banque-comores.km/page/show/cours-de-lor"}},"institutions":{"centralBank":{"name":"Central Bank of the Comoros (Banque Centrale des Comores, BCC)","url":"https://banque-comores.km/"},"insuranceRegulator":null,"insuranceComplaints":null,"pensionScheme":null,"oldAgeAllowance":null,"publicHealthCover":null,"depositInsurance":null,"statistics":{"name":"National Institute of Statistics and Economic and Demographic Studies (INSEED)","url":"https://www.inseed.km/","note":"Linked from the BCC site; the site did not respond on 31 October 2026."}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KM', 1, 'bank_deposit_avg_rate', 0.0206, NULL, 'sourced', 'World Bank WDI, deposit interest rate (FR.INR.DPST), Comoros', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=KM', '2022-12-31', '2.06% in 2022, the latest World Bank value (older than 2025); the BCC raised the minimum savings rate from 1.75% to 2.5% in August 2022.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KM', 1, 'credit_card_rate_cap', 0.14, NULL, 'sourced', 'BCC, Taux d''intérêt de la BCC (range of lending rates, interest and fees)', 'https://banque-comores.km/page/show/taux-dinteret-de-la-bcc', '2023-08-15', 'Bank lending rates, interest and fees included, must lie between 2.5% and 14% a year since 1 August 2022; the 14% ceiling applies to all bank credit, cards included. The page dates from August 2023 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KM', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No deposit guarantee scheme or cover limit was found on the BCC site or in its quarterly bulletin.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KM', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No standard monthly recurring deposit product or rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KM', 1, 'equity_return_base', 0.06, NULL, 'assumption', 'No stock exchange in the Comoros; franc fixed to the euro (491.96775 per euro, BCC)', 'https://banque-comores.km/page/show/devises-taux-de-change-contre-franc', '2026-10-31', 'Global equities in euro terms, held to about 3.5 points above the 2.5% minimum savings rate, since access is only through foreign funds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KM', 1, 'equity_return_high', 0.095, NULL, 'assumption', 'No stock exchange in the Comoros; franc fixed to the euro (491.96775 per euro, BCC)', 'https://banque-comores.km/page/show/devises-taux-de-change-contre-franc', '2026-10-31', 'High case: global equities repeat their long-run euro-terms record.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KM', 1, 'equity_return_low', 0.02, NULL, 'assumption', 'No stock exchange in the Comoros; franc fixed to the euro (491.96775 per euro, BCC)', 'https://banque-comores.km/page/show/devises-taux-de-change-contre-franc', '2026-10-31', 'No local stock market exists, so equity means a global index in euro terms (equal to franc terms under the peg); low case is a weak decade.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KM', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published 1-year term deposit rate was found on the BCC site or in its quarterly bulletin.', 0);
