INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KM', 1, 'fixed_income_return_base', 0.025, NULL, 'assumption', 'BCC minimum savings rate 2.5%; 28-day Treasury bills at 4.73% (banks only)', 'https://banque-comores.km/page/show/taux-dinteret-de-la-bcc', '2026-10-31', 'Base case: savings and term deposits at about the 2.5% minimum; Treasury bills are sold only to banks.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KM', 1, 'fixed_income_return_high', 0.04, NULL, 'assumption', 'BCC minimum savings rate 2.5%; 28-day Treasury bills at 4.73% (banks only)', 'https://banque-comores.km/article/show/annonce-du-resultat-global-de-ladjudication-de-lappel-doffres-demission-de-bons-du-tresor-n00042026-du-31-aout-2026', '2026-10-31', 'High case: longer term deposits nearer the 4.73% Treasury bill rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KM', 1, 'fixed_income_return_low', 0.015, NULL, 'assumption', 'BCC minimum savings rate 2.5%; 28-day Treasury bills at 4.73% (banks only)', 'https://banque-comores.km/page/show/taux-dinteret-de-la-bcc', '2026-10-31', 'Low case: savings deposits at or below the 2.5% minimum after any tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KM', 1, 'goal_inflation_education', 0.04, NULL, 'assumption', 'Inflation assumption 3%; no education CPI found', 'https://banque-comores.km/uploads/Communiqu-CPM-10.26.pdf', '2026-10-31', 'No education price index was found; private school costs are planned 1 point above general inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KM', 1, 'goal_inflation_health', 0.045, NULL, 'assumption', 'Inflation assumption 3%; no medical CPI found', 'https://banque-comores.km/uploads/Communiqu-CPM-10.26.pdf', '2026-10-31', 'No medical price index was found; medical costs, much of them imported or paid abroad, are planned 1.5 points above general inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KM', 1, 'gold_return_base', 0.045, NULL, 'assumption', 'Franc fixed at 491.96775 per euro (BCC); gold trend in euro terms', 'https://banque-comores.km/page/show/devises-taux-de-change-contre-franc', '2026-10-31', 'Base case: the long-run gold trend of about 4-5% a year in euro terms, which the franc follows.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KM', 1, 'gold_return_high', 0.08, NULL, 'assumption', 'Franc fixed at 491.96775 per euro (BCC); gold trend in euro terms', 'https://banque-comores.km/page/show/devises-taux-de-change-contre-franc', '2026-10-31', 'High case: strong gold years.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KM', 1, 'gold_return_low', 0, NULL, 'assumption', 'Franc fixed at 491.96775 per euro (BCC); gold trend in euro terms', 'https://banque-comores.km/page/show/devises-taux-de-change-contre-franc', '2026-10-31', 'Low case: flat gold prices with no currency loss under the euro peg.', 0);
