INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KM', 1, 'inflation_cpi', 0.016, NULL, 'sourced', 'Central Bank of the Comoros (BCC), Monetary Policy Committee communiqué of 8 October 2026', 'https://banque-comores.km/uploads/Communiqu-CPM-10.26.pdf', '2026-06-30', 'Consumer prices up 1.6% year on year in the second quarter of 2026; the BCC expects 1.8% for 2026 after 3.3% in 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KM', 1, 'inflation_projection', 0.03, NULL, 'assumption', 'BCC: 3.3% inflation in 2025, 1.8% expected for 2026; franc fixed to the euro', 'https://banque-comores.km/uploads/Communiqu-CPM-10.26.pdf', '2026-10-31', 'The franc is fixed to the euro, which anchors inflation near euro-area levels, but food and fuel shocks pushed it far higher in 2022-2023, so a rounded 3% is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KM', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published term life premium rates per KMF 1,000 of cover were found; the life insurance market is very small.', 0);
