INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KM', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No domestic government bond market or 5-year yield was found; the Treasury issues only short-term bills.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('KN', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"KN","iso3":"KNA","nameEn":"Saint Kitts and Nevis","nameNative":"Saint Kitts and Nevis","region":"latin_america_caribbean","languages":["en"],"currency":{"code":"XCD","symbol":"$","decimals":2,"compact":"intl","usdRate":{"value":2.7,"status":"sourced","sourceName":"World Bank WDI PA.NUS.FCRF (official exchange rate)","sourceUrl":"https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=KN","asOf":"2025-12-31","note":"Fixed peg of EC$2.70 per US dollar since 1976; the ECCB Monetary Council''s 113th communique (July 2026) marked the peg''s 50th anniversary."}},"instruments":{"savings_account":{"available":true,"localName":"Savings account","note":"Weighted average 2.15% (June 2026); ECCB minimum savings rate 2%.","sourceUrl":"https://www.eccb-centralbank.org/statistics-category/mfs-interest-rates/interest-rates-and-weighted-averages-rates-on-deposits-and-loans/q?country_code%5B%5D=6"},"fdr_3m":{"available":true,"localName":"Fixed deposit","localNameEn":"3-month fixed (time) deposit","note":"Posted rate 2.00% (2026).","sourceUrl":"https://www.eccb-centralbank.org/statistics-category/mfs-interest-rates/interest-rates-on-deposits-and-loans/m?country_code%5B%5D=6"},"fdr_1y":{"available":true,"localName":"Fixed deposit","localNameEn":"12-month fixed (time) deposit","note":"Posted 12-month rates 0.10-4.25% (2026).","sourceUrl":"https://www.eccb-centralbank.org/statistics-category/mfs-interest-rates/interest-rates-on-deposits-and-loans/m?country_code%5B%5D=6"},"dps":{"available":false,"localName":null,"note":"No standard monthly recurring deposit product with a published rate."},"sanchayapatra_5y":{"available":true,"localName":"Household Savings Bond","localNameEn":"Government of St Kitts and Nevis Retail Bond (2 years)","note":"ECCU Retail Bond Programme: individuals and NGOs only, EC$500 minimum, 4.5% fixed, tax-free; first issued September-October 2026.","sourceUrl":"https://www.ecseonline.com/wp-content/uploads/2026/10/Government_of_St_Kitts_and_Nevis_Household_Savings_Bond-v2.cleaned.pdf"},"tbill_91d":{"available":true,"localName":"Treasury bill","localNameEn":"Government of St Kitts and Nevis 91-day Treasury bill","note":"Sold over the counter at set rates (3.75% for 91 days); mostly held by institutions.","sourceUrl":"https://www.ecseonline.com/wp-content/uploads/2026/10/Government_of_St_Kitts_and_Nevis_Household_Savings_Bond-v2.cleaned.pdf"},"tbond_5y":{"available":false,"localName":null,"note":"No regular 5-year government bond issue for retail found."},"tbond_10y":{"available":false,"localName":null,"note":"No regular 10-year government bond issue for retail found."},"equity_fund":{"available":false,"localName":null,"note":"No locally registered retail equity or index fund was identified; the regional share market is very small."},"gold":{"available":true,"localName":"Gold","localNameEn":"Gold jewellery and coins","note":"No legal restriction on buying gold; mostly sold as jewellery."}},"institutions":{"centralBank":{"name":"Eastern Caribbean Central Bank (ECCB)","url":"https://www.eccb-centralbank.org/","note":"Shared central bank of the Eastern Caribbean Currency Union, headquartered in Basseterre."},"insuranceRegulator":{"name":"Financial Services Regulatory Commission (FSRC), St Kitts and Nevis","url":"https://www.fsrc.kn/"},"insuranceComplaints":{"name":"Financial Services Regulatory Commission (FSRC), St Kitts and Nevis","url":"https://www.fsrc.kn/contact","note":"No separate insurance ombudsman or complaints form; contact the FSRC."},"pensionScheme":{"name":"St Christopher and Nevis Social Security Board","url":"https://socialsecurity.kn/age-benefit/"},"oldAgeAllowance":{"name":"Assistance Pension, Social Security Board","url":"https://socialsecurity.kn/non-contributory-pensions/"},"publicHealthCover":{"name":"Ministry of Health (public hospitals and community health services)","url":"https://www.gov.kn/prime-ministers-office-ministry-of-finance-national-security-citizenship-and-immigration-health-and-social-security/"},"depositInsurance":null,"statistics":{"name":"Department of Statistics, Ministry of Sustainable Development","url":"https://www.stats.gov.kn/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KN', 1, 'bank_deposit_avg_rate', 0.021, NULL, 'sourced', 'ECCB statistics: weighted average rate on total deposits, St Kitts and Nevis', 'https://www.eccb-centralbank.org/statistics-category/mfs-interest-rates/interest-rates-and-weighted-averages-rates-on-deposits-and-loans/q?country_code%5B%5D=6', '2026-06-30', 'Weighted average rate on total local-currency deposits, June 2026 (1.74% including foreign-currency deposits); World Bank FR.INR.DPST gives 2.15% for 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KN', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap on credit card interest was found; ECCB statistics show other lending rates up to 25% but no credit card series.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KN', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'ECCU members are setting up the Eastern Caribbean Deposit Insurance Corporation, but the 113th and 114th ECCB Monetary Council communiques (2026) do not mention it operating and no coverage limit for St Kitts and Nevis was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KN', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No standard monthly recurring deposit product with a published rate was found in the ECCB statistics or St Kitts and Nevis sources.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KN', 1, 'equity_return_base', 0.065, NULL, 'assumption', 'St Kitts and Nevis 91-day Treasury bill 3.75%; EC dollar pegged to the US dollar', 'https://www.ecseonline.com/wp-content/uploads/2026/10/Government_of_St_Kitts_and_Nevis_Household_Savings_Bond-v2.cleaned.pdf', '2026-10-31', 'No usable local index record, so the base uses a global equity index in EC-dollar terms: the tax-free 3.75% bill rate plus about 2.75 points.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KN', 1, 'equity_return_high', 0.09, NULL, 'assumption', 'St Kitts and Nevis 91-day Treasury bill 3.75%; EC dollar pegged to the US dollar', 'https://www.ecseonline.com/wp-content/uploads/2026/10/Government_of_St_Kitts_and_Nevis_Household_Savings_Bond-v2.cleaned.pdf', '2026-10-31', 'High case if global equities repeat their strong long-run US-dollar returns.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KN', 1, 'equity_return_low', 0.02, NULL, 'assumption', 'St Kitts and Nevis 91-day Treasury bill 3.75%; EC dollar pegged to the US dollar', 'https://www.ecseonline.com/wp-content/uploads/2026/10/Government_of_St_Kitts_and_Nevis_Household_Savings_Bond-v2.cleaned.pdf', '2026-10-31', 'Low case: the regional share market is very small, so savers rely on global equity funds in pegged US-dollar terms, and a weak decade is possible.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KN', 1, 'fdr_1y_rate', 0.0348, NULL, 'sourced', 'ECCB statistics: weighted average rate on time deposits, St Kitts and Nevis', 'https://www.eccb-centralbank.org/statistics-category/mfs-interest-rates/interest-rates-and-weighted-averages-rates-on-deposits-and-loans/q?country_code%5B%5D=6', '2026-06-30', 'Weighted average rate on all local-currency time deposits (3.48%, June 2026), used as the 1-year figure; posted 12-month rates range from 0.10% to 4.25% (August 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KN', 1, 'fdr_3m_rate', 0.02, NULL, 'sourced', 'ECCB statistics: interest rates on deposits and loans, St Kitts and Nevis (monthly)', 'https://www.eccb-centralbank.org/statistics-category/mfs-interest-rates/interest-rates-on-deposits-and-loans/m?country_code%5B%5D=6', '2026-08-31', '3-month time deposits in local currency: minimum and maximum posted rates both 2.00% (May-August 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KN', 1, 'fixed_income_return_base', 0.03, NULL, 'assumption', 'ECCB statistics: time deposits 3.48% (June 2026); 91-day T-bill 3.75%; retail bond 4.5% (tax-free)', 'https://www.eccb-centralbank.org/statistics-category/mfs-interest-rates/interest-rates-and-weighted-averages-rates-on-deposits-and-loans/q?country_code%5B%5D=6', '2026-10-31', 'Base case: a mix of savings and time deposits with some Treasury bills and the tax-free retail bond.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KN', 1, 'fixed_income_return_high', 0.0425, NULL, 'assumption', 'Household Savings Bond 4.50% (2-year, tax-free); 365-day T-bill 4.00%', 'https://www.ecseonline.com/wp-content/uploads/2026/10/Government_of_St_Kitts_and_Nevis_Household_Savings_Bond-v2.cleaned.pdf', '2026-10-31', 'High case: retail bonds and 1-year bills at about 4-4.5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KN', 1, 'fixed_income_return_low', 0.02, NULL, 'assumption', 'ECCB statistics: savings deposits 2.15%, 3-month deposits 2.00% (2026)', 'https://www.eccb-centralbank.org/statistics-category/mfs-interest-rates/interest-rates-and-weighted-averages-rates-on-deposits-and-loans/q?country_code%5B%5D=6', '2026-10-31', 'Low case: savings and short deposits at about 2%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KN', 1, 'goal_inflation_education', 0.04, NULL, 'assumption', 'St Kitts and Nevis CPI 4.6% (June 2026); planning inflation 2.5%', 'https://tradingeconomics.com/st-kitts-and-nevis/inflation-cpi', '2026-10-31', 'No education CPI series found; planning inflation plus 1.5 points.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KN', 1, 'goal_inflation_health', 0.045, NULL, 'assumption', 'St Kitts and Nevis CPI 4.6% (June 2026); planning inflation 2.5%', 'https://tradingeconomics.com/st-kitts-and-nevis/inflation-cpi', '2026-10-31', 'No medical CPI series found; planning inflation plus 2 points for private and overseas medical care.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KN', 1, 'gold_return_base', 0.045, NULL, 'assumption', 'World Bank PA.NUS.FCRF: EC$2.70 per US$1 (fixed peg)', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=KN', '2026-10-31', 'Long-run dollar gold trend of about 4-5% a year, with no expected depreciation of the pegged EC dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KN', 1, 'gold_return_high', 0.08, NULL, 'assumption', 'World Bank PA.NUS.FCRF: EC$2.70 per US$1 (fixed peg)', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=KN', '2026-10-31', 'High case with strong dollar gold prices.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KN', 1, 'gold_return_low', 0.01, NULL, 'assumption', 'World Bank PA.NUS.FCRF: EC$2.70 per US$1 (fixed peg)', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=KN', '2026-10-31', 'Low case: weak dollar gold price; the 50-year peg means no currency boost.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KN', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Protection of Employment Act 1986 pays severance from a government fund (1% employer levy) to workers made redundant (Social Security Board, https://socialsecurity.kn/protection-act/); no statutory gratuity at retirement was confirmed, but the Act text could not be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KN', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No official figure for a typical major hospital stay at a private or mid-range hospital in St Kitts and Nevis was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KN', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No regulator or public source publishes individual health insurance premiums by age for St Kitts and Nevis.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KN', 1, 'inflation_cpi', 0.046, NULL, 'sourced', 'Trading Economics, St Kitts and Nevis inflation rate (ECCB / Statistics Department CPI)', 'https://tradingeconomics.com/st-kitts-and-nevis/inflation-cpi', '2026-06-30', 'Secondary source: year-on-year CPI inflation 4.6% in June 2026 (5.1% in May); the Statistics Department site publishes CPI tables only up to 2024.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KN', 1, 'inflation_projection', 0.025, NULL, 'assumption', 'Government of St Kitts and Nevis, Household Savings Bond prospectus (2026): inflation forecast 2.5% for 2026, just below 2% in 2027; EC dollar pegged at 2.70', 'https://www.ecseonline.com/wp-content/uploads/2026/10/Government_of_St_Kitts_and_Nevis_Household_Savings_Bond-v2.cleaned.pdf', '2026-10-31', 'The EC dollar is pegged to the US dollar and the ECCB has no inflation target; the Ministry of Finance forecasts 2.5% for 2026 easing below 2%, so we plan with 2.5% given the recent 4-5% readings.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KN', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life is sold by regional insurers, but no regulator or public source publishes premium rates by age for St Kitts and Nevis.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KN', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched the Financial Services Regulatory Commission site: no industry-wide life claim settlement ratio is published.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KN', 1, 'life_expectancy', 72.281, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=KN', '2024-12-31', 'UN WPP (via georank.org) gives 72.6 for 2026 (men 69.0, women 76.4).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KN', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":18.6,"men":16.4,"women":20.8},{"age":65,"total":15.1,"men":13.2,"women":16.9},{"age":70,"total":11.8,"men":10.4,"women":13.2},{"age":80,"total":6.7,"men":6,"women":7.3}]}', 'sourced', 'UN World Population Prospects via georank.org (life expectancy by current age, 2026)', 'https://georank.org/life-expectancy/saint-kitts-and-nevis', '2026-12-31', 'Remaining years derived from the total expected age at death by current age for 2026 (e.g. 78.6 at age 60 means 18.6 years left).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KN', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":62,"womenAge":62,"over90Monthly":null,"meansTested":true}', 'sourced', 'St Christopher and Nevis Social Security Board: Non-Contributory Pensions', 'https://socialsecurity.kn/non-contributory-pensions/', '2026-10-31', 'Assistance Pension for people over 62 who do not qualify for the contributory age pension and are in need, with no secure income or other means of support.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KN', 1, 'old_age_allowance_monthly', 350, NULL, 'sourced', 'St Christopher and Nevis Social Security Board: increases to minimum age pension and assistance pension (press release, 29 December 2023)', 'https://socialsecurity.kn/press/press-releases-2023/increases-to-minimum-age-pension-assistance-pension-and-funeral-grant/', '2024-01-01', 'Assistance (non-contributory) Pension raised from EC$255 to EC$350 a month from 1 January 2024 (HelpAge Pension Watch also gives EC$350); the Board''s benefit page still shows the old EC$255. No later change found; source older than 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KN', 1, 'oop_health_share', 0.418, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=KN', '2023-12-31', 'Figure is for 2023 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KN', 1, 'policy_rate', 0.03, NULL, 'sourced', 'ECCB Monetary Council, communique of the 114th meeting (30 October 2026)', 'https://www.eccb-centralbank.org/news/communique-114th-meeting-of-the-monetary-council-of-the-eastern-caribbean-central-bank', '2026-10-30', 'ECCB discount rate kept at 3.0% for short-term credit (4.5% long-term), unchanged from the 113th meeting (July 2026); applies to all ECCU members including St Kitts and Nevis.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KN', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":62,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'St Christopher and Nevis Social Security Board: Age Benefit', 'https://socialsecurity.kn/age-benefit/', '2026-10-31', 'Compulsory social security age pension: from 62 with 500 contributions (150 paid), 16-60% of the average of the best three years'' insurable earnings, paid for life; otherwise a lump-sum age grant. Minimum age pension EC$500 a month from 2024. Increases are ad hoc (no automatic indexation found); tax treatment not confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KN', 1, 'retirement_accumulation_return_base', 0.0475, NULL, 'assumption', '91-day Treasury bill 3.75%; global equity in pegged EC dollars', 'https://www.ecseonline.com/wp-content/uploads/2026/10/Government_of_St_Kitts_and_Nevis_Household_Savings_Bond-v2.cleaned.pdf', '2026-10-31', 'Base case: half global equities at 6.5% and half deposits and bills around 3%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KN', 1, 'retirement_accumulation_return_high', 0.065, NULL, 'assumption', '91-day Treasury bill 3.75%; global equity in pegged EC dollars', 'https://www.ecseonline.com/wp-content/uploads/2026/10/Government_of_St_Kitts_and_Nevis_Household_Savings_Bond-v2.cleaned.pdf', '2026-10-31', 'High case with stronger equity returns.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KN', 1, 'retirement_accumulation_return_low', 0.03, NULL, 'assumption', '91-day Treasury bill 3.75%; global equity in pegged EC dollars', 'https://www.ecseonline.com/wp-content/uploads/2026/10/Government_of_St_Kitts_and_Nevis_Household_Savings_Bond-v2.cleaned.pdf', '2026-10-31', 'Low case for a balanced mix if global equities disappoint.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KN', 1, 'retirement_age_default', 62, NULL, 'sourced', 'St Christopher and Nevis Social Security Board: Age Benefit', 'https://socialsecurity.kn/age-benefit/', '2026-10-31', 'Age pension from 62 with at least 500 contributions (150 paid). A May 2026 actuarial reform proposal published by the Board would raise it to 65 by 2032, but it had not been enacted as of October 2026, so 62 applies today.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KN', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'The retirement age for public officers under the Pensions Act could not be confirmed (revised laws listing did not show the Act); government workers also draw the social security age pension at 62.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KN', 1, 'retirement_return_base', 0.03, NULL, 'assumption', '91-day Treasury bill 3.75%; time deposits 3.48% (June 2026)', 'https://www.eccb-centralbank.org/statistics-category/mfs-interest-rates/interest-rates-and-weighted-averages-rates-on-deposits-and-loans/q?country_code%5B%5D=6', '2026-10-31', 'Base case below the 3.48-3.75% deposit and bill rates (no tax on RGSM income): a liquid mix in retirement.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KN', 1, 'retirement_return_high', 0.0375, NULL, 'assumption', '91-day Treasury bill 3.75%; Household Savings Bond 4.5%', 'https://www.ecseonline.com/wp-content/uploads/2026/10/Government_of_St_Kitts_and_Nevis_Household_Savings_Bond-v2.cleaned.pdf', '2026-10-31', 'High case: rolling Treasury bills and retail bonds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KN', 1, 'retirement_return_low', 0.02, NULL, 'assumption', 'ECCB statistics: savings deposits 2.15% (June 2026)', 'https://www.eccb-centralbank.org/statistics-category/mfs-interest-rates/interest-rates-and-weighted-averages-rates-on-deposits-and-loans/q?country_code%5B%5D=6', '2026-10-31', 'Low case: mostly savings deposits at about 2%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KN', 1, 'sanchayapatra_5y_rate', 0.045, NULL, 'sourced', 'Government of St Kitts and Nevis Household Savings Bond (ECCU Retail Bond Programme), prospectus', 'https://www.ecseonline.com/wp-content/uploads/2026/10/Government_of_St_Kitts_and_Nevis_Household_Savings_Bond-v2.cleaned.pdf', '2026-10-23', 'Retail bond for individuals and NGOs only: 2-year term, fixed 4.50% a year paid half-yearly, EC$500 to EC$125,000 per investor, issued 23 October 2026 (shorter than 5 years); the inaugural issue raised EC$10 million (ECCB communique, 30 October 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KN', 1, 'savings_account_rate', 0.0215, NULL, 'sourced', 'ECCB statistics: interest rates and weighted average rates on deposits, St Kitts and Nevis', 'https://www.eccb-centralbank.org/statistics-category/mfs-interest-rates/interest-rates-and-weighted-averages-rates-on-deposits-and-loans/q?country_code%5B%5D=6', '2026-06-30', 'Weighted average rate on local-currency savings deposits, June 2026 (posted range 2.00-2.75%; ECCB minimum savings rate 2%). On re-check (November 2026) the ECCB statistics pages refused automated access; World Bank FR.INR.DPST gives 2.15% for 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KN', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":6}]}', 'sourced', 'World Bank WDI SP.POP.DPND.OL', 'https://data.worldbank.org/indicator/SP.POP.DPND.OL?locations=KN', '2025-12-31', '100 / old-age dependency ratio of 16.76 in 2025. No UN WPP projection for 2040 or 2065 could be read for St Kitts and Nevis.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KN', 1, 'tax_bank_interest', 0, NULL, 'sourced', 'St Kitts and Nevis Inland Revenue Department: Corporate Income Tax page', 'https://www.sknird.com/corporate-income-tax/', '2026-10-31', 'The Inland Revenue Department states that income tax on individuals was abolished in 1980, so resident individuals pay no income tax on bank interest; withholding tax rules for non-residents were not checked.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KN', 1, 'tax_sanchayapatra_profit', 0, NULL, 'sourced', 'Household Savings Bond prospectus (2026)', 'https://www.ecseonline.com/wp-content/uploads/2026/10/Government_of_St_Kitts_and_Nevis_Household_Savings_Bond-v2.cleaned.pdf', '2026-10-23', 'Income from the retail bond and all other instruments issued on the Regional Government Securities Market is not subject to any tax, duty or levy by ECCU governments.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KN', 1, 'tbill_91d_rate', 0.0375, NULL, 'sourced', 'Household Savings Bond prospectus, Appendix III: outstanding Government securities (91-day T-bill)', 'https://www.ecseonline.com/wp-content/uploads/2026/10/Government_of_St_Kitts_and_Nevis_Household_Savings_Bond-v2.cleaned.pdf', '2025-10-28', 'Government of St Kitts and Nevis 91-day over-the-counter Treasury bill at 3.75% (issued 28 October 2025); 182-day bills 3.85% and 365-day bills 4.00%. Bills are rolled over at set rates; no later 91-day rate was found (figure from 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KN', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No current 10-year Government of St Kitts and Nevis bond yield is published; the prospectus lists only a 20-year US-dollar bond (2032) and a 45-year bond (2057) from 2012.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KN', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No current 5-year Government of St Kitts and Nevis bond was found; outstanding listed bonds are long private placements (2032 and 2057) per the 2026 prospectus.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('KP', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"KP","iso3":"PRK","nameEn":"North Korea","nameNative":"조선민주주의인민공화국","region":"east_asia_pacific","languages":["ko"],"currency":{"code":"KPW","symbol":"₩","decimals":0,"compact":"intl","usdRate":{"value":69200,"status":"sourced","sourceName":"Daily NK market survey, Pyongyang (informal market rate)","sourceUrl":"https://www.dailynk.com/english/north-korea-rice-prices-record-50000-won/","asOf":"2026-10-25","note":"Informal market rate, down from 71,200 two weeks earlier; the official state rate is not published regularly and is far stronger. Used because prices and savings follow the market rate."}},"instruments":{"savings_account":{"available":true,"localName":"저금","localNameEn":"Savings deposit","note":"State and provincial bank savings accounts exist; trust and access are limited.","sourceUrl":"https://www.dailynk.com/english/kangwon-province-banks-offer-new-savings-products-promising-flexible-withdrawals/"},"fdr_3m":{"available":false,"localName":null,"note":"No short-term fixed deposit documented."},"fdr_1y":{"available":true,"localName":null,"localNameEn":"Fixed-term savings","note":"Provincial banks offer 1- to 10-year savings products (2023 report).","sourceUrl":"https://www.dailynk.com/english/kangwon-province-banks-offer-new-savings-products-promising-flexible-withdrawals/"},"dps":{"available":false,"localName":null},"sanchayapatra_5y":{"available":false,"localName":null,"note":"No retail government bonds on sale."},"tbill_91d":{"available":false,"localName":null},"tbond_5y":{"available":false,"localName":null},"tbond_10y":{"available":false,"localName":null},"equity_fund":{"available":false,"localName":null,"note":"No stock market or investment funds."},"gold":{"available":false,"localName":null,"note":"No legal retail market for gold bars or coins documented."}},"institutions":{"centralBank":null,"insuranceRegulator":null,"insuranceComplaints":null,"pensionScheme":null,"oldAgeAllowance":null,"publicHealthCover":null,"depositInsurance":null,"statistics":null},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KP', 1, 'bank_deposit_avg_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published average deposit rate; World Bank FR.INR.DPST has no value for North Korea.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KP', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No consumer credit card market; the domestic cash cards carry no credit.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KP', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No deposit insurance scheme found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KP', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No recurring deposit product documented.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KP', 1, 'equity_return_base', 0.08, NULL, 'assumption', 'No stock market; global equity in won terms capped at the reported 4% savings floor plus 4 points', 'https://www.dailynk.com/english/kangwon-province-banks-offer-new-savings-products-promising-flexible-withdrawals/', '2026-10-31', 'North Korea has no stock exchange; a global index in won would track currency depreciation, but the base is held to the safe-rate cap.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KP', 1, 'equity_return_high', 0.15, NULL, 'assumption', 'Global equity in won terms', 'https://www.dailynk.com/english/north-korea-rice-prices-record-50000-won/', '2026-10-31', 'High case reflecting continued won depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KP', 1, 'equity_return_low', 0.02, NULL, 'assumption', 'No stock market; capped by reported savings rates (4-9%, 2023)', 'https://www.dailynk.com/english/kangwon-province-banks-offer-new-savings-products-promising-flexible-withdrawals/', '2026-10-31', 'Low case; no local equity market exists and foreign investment is not open to residents.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KP', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published rate; Daily NK (Oct 2023) reported 1- to 10-year savings products at 4% to 9% by branch. The 2023 report is older than 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KP', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published 3-month deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KP', 1, 'fixed_income_return_base', 0.04, NULL, 'assumption', 'Reported provincial bank savings rates 4-9% (Daily NK, 2023); no tax on interest', 'https://www.dailynk.com/english/kangwon-province-banks-offer-new-savings-products-promising-flexible-withdrawals/', '2026-10-31', 'Base at the bottom of the reported 4-9% range, since rates vary by branch and access to deposits is unreliable.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KP', 1, 'fixed_income_return_high', 0.06, NULL, 'assumption', 'Reported provincial bank savings rates 4-9% (Daily NK, 2023)', 'https://www.dailynk.com/english/kangwon-province-banks-offer-new-savings-products-promising-flexible-withdrawals/', '2026-10-31', 'High case in the middle of the reported range.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KP', 1, 'fixed_income_return_low', 0, NULL, 'assumption', 'Reported provincial bank savings rates 4-9% (Daily NK, 2023)', 'https://www.dailynk.com/english/kangwon-province-banks-offer-new-savings-products-promising-flexible-withdrawals/', '2026-10-31', 'Low case allows for frozen or unpaid interest and withdrawal limits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KP', 1, 'goal_inflation_education', 0.25, NULL, 'assumption', 'Headline planning inflation (no education price index)', 'https://www.dailynk.com/english/north-korea-rice-prices-record-50000-won/', '2026-10-31', 'No education CPI exists, so education costs use the 25% headline planning rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KP', 1, 'goal_inflation_health', 0.25, NULL, 'assumption', 'Headline planning inflation (no medical price index)', 'https://www.dailynk.com/english/north-korea-rice-prices-record-50000-won/', '2026-10-31', 'No medical CPI exists, so health costs use the 25% headline planning rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KP', 1, 'gold_return_base', 0.25, NULL, 'assumption', 'Dollar gold trend about 5% plus expected won depreciation about 20%', 'https://www.dailynk.com/english/north-korea-rice-prices-record-50000-won/', '2026-10-31', 'Gold priced in won follows the dollar gold price plus the market won''s fall against the dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KP', 1, 'gold_return_high', 0.4, NULL, 'assumption', 'Gold in won terms; 2026 won depreciation', 'https://www.dailynk.com/english/north-korea-rice-prices-record-50000-won/', '2026-10-31', 'High case for a repeat of 2026, when the market won roughly halved against the dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KP', 1, 'gold_return_low', 0.05, NULL, 'assumption', 'Gold in won terms; Daily NK exchange-rate surveys', 'https://www.dailynk.com/english/north-korea-rice-prices-record-50000-won/', '2026-10-31', 'Low case if the market won stabilises as it did in 2019-2023.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KP', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No statutory end-of-service gratuity documented.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KP', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'Health care is officially free; no published figure for actual out-of-pocket costs, which defector surveys say are common.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KP', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No private health insurance market.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KP', 1, 'inflation_cpi', NULL, NULL, 'missing', '', '', '2026-10-31', 'North Korea publishes no consumer price index; Daily NK market surveys show rice in Pyongyang rising from about 18,000 to 51,700 won/kg between January and October 2026 and the won falling from about 35,000 to 69,200 per dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KP', 1, 'inflation_projection', 0.25, NULL, 'assumption', 'Daily NK market price and exchange-rate surveys (2026)', 'https://www.dailynk.com/english/north-korea-rice-prices-record-50000-won/', '2026-10-31', 'With no official CPI and the market won losing about half its value against the dollar in 2026 after years near 8,000 per dollar, 25% a year is a rounded planning figure between the calm and crisis periods.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KP', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Insurance is a state monopoly; no term life premium rates are published.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KP', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The state insurer publishes no claim statistics.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KP', 1, 'life_expectancy', 73.7, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN (UN WPP estimate)', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=KP', '2024-12-31', 'Men 71.6, women 75.9 (2024).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KP', 1, 'life_table_remaining', NULL, '{"rows":[{"age":65,"total":15.92},{"age":80,"total":6.7}]}', 'sourced', 'UN World Population Prospects 2024 via Measured World', 'https://measuredworld.com/countries/north-korea/mortality/life-expectancy-progression', '2024-12-31', 'Secondary source reproducing UN WPP 2024; ages 60 and 70 and sex breakdown not found (WHO GHO API unavailable).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KP', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension documented.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KP', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'No separate non-contributory social pension documented; the only old-age pension found is the work-linked state pension, whose amounts are not published.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KP', 1, 'oop_health_share', NULL, NULL, 'missing', '', '', '2026-10-31', 'World Bank SH.XPD.OOPC.CH.ZS and WHO GHED have no value for North Korea.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KP', 1, 'policy_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Central Bank of the DPRK publishes no policy rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KP', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":60,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":true}', 'sourced', 'Korea Times (13 May 2026) on North Korea''s Labour Law and its 2024 revision', 'https://www.koreatimes.co.kr/amp/foreignaffairs/northkorea/20260513/n-korea-extends-retirement-age-for-office-workers-by-3-years-amid-population-aging', '2026-05-13', 'State elderly pension for workers with enough years of work: men from 60 and women from 55 under the 1978 Labour Law, office workers 63/58 since the 2024 revision; amounts, funding and indexation are not published. taxFree because personal taxes were abolished in 1974.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KP', 1, 'retirement_accumulation_return_base', 0.06, NULL, 'assumption', 'Reported savings rates (4-9%) and won-priced gold', 'https://www.dailynk.com/english/kangwon-province-banks-offer-new-savings-products-promising-flexible-withdrawals/', '2026-10-31', 'Mix of 4% savings and some gold or foreign currency held as a hedge.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KP', 1, 'retirement_accumulation_return_high', 0.12, NULL, 'assumption', 'Won-priced gold and foreign currency', 'https://www.dailynk.com/english/north-korea-rice-prices-record-50000-won/', '2026-10-31', 'High case where savings are mostly held in gold or dollars as the won falls.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KP', 1, 'retirement_accumulation_return_low', 0.02, NULL, 'assumption', 'Reported savings rates and won-priced gold', 'https://www.dailynk.com/english/kangwon-province-banks-offer-new-savings-products-promising-flexible-withdrawals/', '2026-10-31', 'Low case for a mix of bank savings and hard assets.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KP', 1, 'retirement_age_default', 60, NULL, 'sourced', 'Korea Times (13 May 2026) on North Korea''s Labour Law and its 2024 revision', 'https://www.koreatimes.co.kr/amp/foreignaffairs/northkorea/20260513/n-korea-extends-retirement-age-for-office-workers-by-3-years-amid-population-aging', '2026-05-13', 'The 2024 revision raised office workers'' pension age to men 63, women 58 (from 60 and 55 under the 1978 Labour Law) and left manual workers and farmers unchanged, so they stay at men 60 (women 55).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KP', 1, 'retirement_age_government', 63, NULL, 'sourced', 'Korea Times (13 May 2026) on North Korea''s 2024 Labour Law revision', 'https://www.koreatimes.co.kr/amp/foreignaffairs/northkorea/20260513/n-korea-extends-retirement-age-for-office-workers-by-3-years-amid-population-aging', '2026-05-13', 'Office workers eligible for the state pension: men 63, women 58 (raised from 60 and 55 in 2024).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KP', 1, 'retirement_return_base', 0.04, NULL, 'assumption', 'Reported provincial bank savings rates 4-9% (Daily NK, 2023); no tax on interest', 'https://www.dailynk.com/english/kangwon-province-banks-offer-new-savings-products-promising-flexible-withdrawals/', '2026-10-31', 'Held at the bottom of the reported deposit range, the only safe instrument.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KP', 1, 'retirement_return_high', 0.06, NULL, 'assumption', 'Reported provincial bank savings rates 4-9% (Daily NK, 2023)', 'https://www.dailynk.com/english/kangwon-province-banks-offer-new-savings-products-promising-flexible-withdrawals/', '2026-10-31', 'High case in the middle of the reported range.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KP', 1, 'retirement_return_low', 0, NULL, 'assumption', 'Reported provincial bank savings rates 4-9% (Daily NK, 2023)', 'https://www.dailynk.com/english/kangwon-province-banks-offer-new-savings-products-promising-flexible-withdrawals/', '2026-10-31', 'Low case allows for unpaid interest or restricted withdrawals.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KP', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificates currently sold to individuals (the 2003 ''People''s Life Bonds'' were a one-off).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KP', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No current published rate; Daily NK (Oct 2023) reported provincial bank savings products paying 4% to 9% depending on branch. The 2023 report is older than 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KP', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":5.4},{"year":2040,"value":3.1},{"year":2065,"value":2.4}]}', 'sourced', 'UN WPP 2024 medium variant via PopulationPyramid.net; World Bank SP.POP.DPND.OL', 'https://www.populationpyramid.net/dem-peoples-republic-of-korea/2040/', '2025-12-31', '100 / old-age dependency ratio: 18.6 (2025, World Bank), 31.8 (2040) and 41.6 (2065, populationpyramid.net).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KP', 1, 'tax_bank_interest', 0, NULL, 'sourced', 'Taxation in North Korea (Wikipedia, citing the 1974 law ''On Abolishing the Tax System'')', 'https://en.wikipedia.org/wiki/Taxation_in_North_Korea', '1974-04-01', 'Personal income taxes were abolished in 1974 and no tax on interest is described; the state raises revenue through enterprise levies and fees. Legal basis dates from 1974 (older than 2025); secondary source.', 0);
