INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('KR', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"KR","iso3":"KOR","nameEn":"South Korea","nameNative":"대한민국","region":"east_asia_pacific","languages":["ko"],"currency":{"code":"KRW","symbol":"₩","decimals":0,"compact":"intl","usdRate":{"value":1335.3,"status":"sourced","sourceName":"Bank of Korea ECOS, KRW per USD (매매기준율)","sourceUrl":"https://ecos.bok.or.kr/api/StatisticSearch/sample/json/kr/1/10/731Y001/D/20261026/20261030/0000001","asOf":"2026-10-30","note":"World Bank 2025 average was 1,422.4."}},"instruments":{"savings_account":{"available":true,"localName":"보통예금","localNameEn":"Ordinary demand deposit","sourceUrl":"https://dealsite.co.kr/articles/131688"},"fdr_3m":{"available":true,"localName":"정기예금 (3개월)","localNameEn":"3-month time deposit","sourceUrl":"https://ecos.bok.or.kr/api/StatisticSearch/sample/json/kr/1/10/121Y002/M/202607/202609/BEABAA2111"},"fdr_1y":{"available":true,"localName":"정기예금","localNameEn":"Time deposit","sourceUrl":"https://ecos.bok.or.kr/api/StatisticSearch/sample/json/kr/1/10/121Y002/M/202607/202609/BEABAA2118"},"dps":{"available":true,"localName":"정기적금","localNameEn":"Installment savings","sourceUrl":"https://ecos.bok.or.kr/api/StatisticSearch/sample/json/kr/1/10/121Y002/M/202607/202609/BEABAA212"},"sanchayapatra_5y":{"available":true,"localName":"개인투자용 국채","localNameEn":"Retail government bonds for individuals","note":"Sold monthly in 3, 5, 10 and 20-year terms; interest compounds and is paid at maturity.","sourceUrl":"https://biz.sbs.co.kr/amp/article/20000337585"},"tbill_91d":{"available":true,"localName":"통화안정증권 (91일)","localNameEn":"Monetary Stabilization Bond (91-day)","note":"No regular 91-day treasury bill; central bank bonds trade through brokerages.","sourceUrl":"https://ecos.bok.or.kr/api/StatisticSearch/sample/json/kr/1/10/817Y002/D/20261026/20261030/010400000"},"tbond_5y":{"available":true,"localName":"국고채 (5년)","localNameEn":"Korea Treasury Bond (5-year)","sourceUrl":"https://ecos.bok.or.kr/api/StatisticSearch/sample/json/kr/1/10/817Y002/D/20261026/20261030/010200001"},"tbond_10y":{"available":true,"localName":"국고채 (10년)","localNameEn":"Korea Treasury Bond (10-year)","sourceUrl":"https://ecos.bok.or.kr/api/StatisticSearch/sample/json/kr/1/10/817Y002/D/20261026/20261030/010210000"},"equity_fund":{"available":true,"localName":"인덱스펀드·ETF","localNameEn":"Index funds and ETFs"},"gold":{"available":true,"localName":"금 (골드바)","localNameEn":"Gold bars","note":"Physical gold bars are sold to individuals; gold can also be traded on the exchange''s regulated gold market."}},"institutions":{"centralBank":{"name":"Bank of Korea","url":"https://www.bok.or.kr/"},"insuranceRegulator":{"name":"Financial Services Commission","url":"https://www.fsc.go.kr/","note":"Supervision is carried out by the Financial Supervisory Service."},"insuranceComplaints":{"name":"Financial Supervisory Service (complaints and dispute mediation)","url":"https://www.fss.or.kr/"},"pensionScheme":{"name":"National Pension Service","url":"https://www.nps.or.kr/"},"oldAgeAllowance":{"name":"Basic Pension (Ministry of Health and Welfare)","url":"https://basicpension.mohw.go.kr/"},"publicHealthCover":{"name":"National Health Insurance Service","url":"https://www.nhis.or.kr/"},"depositInsurance":{"name":"Korea Deposit Insurance Corporation","url":"https://www.kdic.or.kr/"},"statistics":{"name":"Ministry of Data and Statistics (formerly Statistics Korea)","url":"https://mods.go.kr/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KR', 1, 'bank_deposit_avg_rate', 0.0345, NULL, 'sourced', 'Bank of Korea ECOS, deposit banks'' savings-type deposits, new transactions (weighted average)', 'https://ecos.bok.or.kr/api/StatisticSearch/sample/json/kr/1/10/121Y002/M/202607/202609/BEABAA2', '2026-09-30', 'Balance-basis total deposit rate was 2.20% at end-August 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KR', 1, 'credit_card_rate_cap', 0.2, NULL, 'sourced', 'Regulation on the maximum interest rate under the Interest Limitation Act', 'https://www.law.go.kr/%EB%B2%95%EB%A0%B9/%EC%9D%B4%EC%9E%90%EC%A0%9C%ED%95%9C%EB%B2%95%EC%A0%9C2%EC%A1%B0%EC%A0%9C1%ED%95%AD%EC%9D%98%EC%B5%9C%EA%B3%A0%EC%9D%B4%EC%9E%90%EC%9C%A8%EC%97%90%EA%B4%80%ED%95%9C%EA%B7%9C%EC%A0%95', '2021-07-07', 'Legal maximum interest rate of 20% a year on loan contracts since 7 July 2021; card loans and revolving balances are held to the same statutory ceiling. Rule dates from 2021 (older than 2025) and is still in force.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KR', 1, 'deposit_insurance_limit', 100000000, NULL, 'sourced', 'Korea Deposit Insurance Corporation, protection limit page', 'https://www.kdic.or.kr/sp/dpstrprot/ProtSystProtLmts/selectScrn.do', '2025-09-01', 'KRW 100 million (principal plus interest) per depositor per financial institution; raised from KRW 50 million from 1 September 2025 (KDIC home page notice).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KR', 1, 'dps_rate', 0.0315, NULL, 'sourced', 'Bank of Korea ECOS, deposit banks'' new installment savings (정기적금, weighted average)', 'https://ecos.bok.or.kr/api/StatisticSearch/sample/json/kr/1/10/121Y002/M/202607/202609/BEABAA212', '2026-09-30', 'Volatile month to month (3.99% July, 3.72% August) because of promotional products.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KR', 1, 'equity_return_base', 0.07, NULL, 'assumption', 'Safe rate plus 4 points: 1-year time deposit 3.57% and 1-year government bond 3.59% before 15.4% tax (about 3.0% after tax)', 'https://ecos.bok.or.kr/api/StatisticSearch/sample/json/kr/1/10/817Y002/D/20261026/20261030/010190000', '2026-10-31', 'KOSPI''s 10-year price gain (about 11% a year to 5,731 in Oct 2026) comes mostly from a 2025-26 rally, so the base is capped at the after-tax safe rate plus 4 points.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KR', 1, 'equity_return_high', 0.11, NULL, 'assumption', 'KOSPI 2,008 (31 Oct 2016) to 5,731 (30 Oct 2026), about 11% a year price return (ECOS 802Y001)', 'https://ecos.bok.or.kr/api/StatisticSearch/sample/json/kr/1/10/802Y001/D/20261026/20261030/0001000', '2026-10-31', 'High case near the full 10-year KOSPI record including the recent rally.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KR', 1, 'equity_return_low', 0.03, NULL, 'assumption', 'KOSPI 2,008 (31 Oct 2016) to 2,399 (30 Dec 2024): about 2% a year price return before the 2025-26 rally (ECOS 802Y001)', 'https://ecos.bok.or.kr/api/StatisticSearch/sample/json/kr/1/10/802Y001/D/20241223/20241231/0001000', '2026-10-31', 'Low case matching KOSPI''s weak 2016-2024 record before the recent rally.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KR', 1, 'fdr_1y_rate', 0.0357, NULL, 'sourced', 'Bank of Korea ECOS, deposit banks'' new 1-year time deposits (weighted average)', 'https://ecos.bok.or.kr/api/StatisticSearch/sample/json/kr/1/10/121Y002/M/202607/202609/BEABAA2118', '2026-09-30', 'Major banks'' headline 1-year rates were 3.50-3.60% in October 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KR', 1, 'fdr_3m_rate', 0.0316, NULL, 'sourced', 'Bank of Korea ECOS, deposit banks'' new time deposits under 6 months (weighted average)', 'https://ecos.bok.or.kr/api/StatisticSearch/sample/json/kr/1/10/121Y002/M/202607/202609/BEABAA2111', '2026-09-30', 'Series covers all maturities under 6 months; 2.97% in August.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KR', 1, 'fixed_income_return_base', 0.03, NULL, 'assumption', '1-year time deposit 3.57% and 1-year government bond 3.59% before 15.4% tax (about 3.0% after tax)', 'https://ecos.bok.or.kr/api/StatisticSearch/sample/json/kr/1/10/121Y002/M/202607/202609/BEABAA2118', '2026-10-31', 'Base equal to the after-tax 1-year deposit rate (3.57% x 0.846).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KR', 1, 'fixed_income_return_high', 0.037, NULL, 'assumption', '5-year retail government bond 4.325% taxed at 15.4% (about 3.66%)', 'https://biz.sbs.co.kr/amp/article/20000337585', '2026-10-31', 'High case locking in retail government bonds or 5-10 year treasury yields after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KR', 1, 'fixed_income_return_low', 0.02, NULL, 'assumption', '1-year time deposit 3.57% and 1-year government bond 3.59% before 15.4% tax (about 3.0% after tax)', 'https://ecos.bok.or.kr/api/StatisticSearch/sample/json/kr/1/10/121Y002/M/202607/202609/BEABAA2118', '2026-10-31', 'Low case if the base rate falls back to 2% and deposit rates follow.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KR', 1, 'goal_inflation_education', 0.03, NULL, 'assumption', 'Education CPI rose about 1.6% a year 2020-2025 (ECOS 901Y009, item J)', 'https://ecos.bok.or.kr/api/StatisticSearch/sample/json/kr/1/10/901Y009/A/2020/2025/J', '2026-10-31', 'Education CPI is low, but private tutoring spending grows faster, so 3% is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KR', 1, 'goal_inflation_health', 0.025, NULL, 'assumption', 'Health CPI rose about 1.1% a year 2020-2025 (ECOS 901Y009, item F)', 'https://ecos.bok.or.kr/api/StatisticSearch/sample/json/kr/1/10/901Y009/A/2020/2025/F', '2026-10-31', 'Measured medical prices rise slowly under NHI fee controls, but non-covered care and ageing push spending faster, so health costs use the 2.5% headline planning rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KR', 1, 'gold_return_base', 0.06, NULL, 'assumption', 'Long-run USD gold trend about 5% plus about 1% expected won depreciation', 'https://ecos.bok.or.kr/api/StatisticSearch/sample/json/kr/1/10/731Y001/D/20261026/20261030/0000001', '2026-10-31', 'Gold in won follows the dollar gold price plus mild long-run won depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KR', 1, 'gold_return_high', 0.1, NULL, 'assumption', 'Gold in won; strong-decade case', 'https://ecos.bok.or.kr/api/StatisticSearch/sample/json/kr/1/10/731Y001/D/20261026/20261030/0000001', '2026-10-31', 'High case for a strong gold decade or a weaker won.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KR', 1, 'gold_return_low', 0.01, NULL, 'assumption', 'Gold in won; USD/KRW from Bank of Korea ECOS', 'https://ecos.bok.or.kr/api/StatisticSearch/sample/json/kr/1/10/731Y001/D/20261026/20261030/0000001', '2026-10-31', 'Low case if gold stalls and the won strengthens, as it did in 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KR', 1, 'gratuity_rule', NULL, '{"daysPerYear":30,"daysPerYearAfter":null,"afterYears":null,"daysPerMonth":30}', 'sourced', 'Employee Retirement Benefit Security Act, Article 8', 'https://www.law.go.kr/%EB%B2%95%EB%A0%B9/%EA%B7%BC%EB%A1%9C%EC%9E%90%ED%87%B4%EC%A7%81%EA%B8%89%EC%97%AC%EB%B3%B4%EC%9E%A5%EB%B2%95/%EC%A0%9C8%EC%A1%B0', '2026-10-31', 'Article 8(1): at least 30 days of average wages per year of continuous service (average wage = last 3 months'' pay / calendar days); many employers use a DB or DC retirement pension instead.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KR', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'Typical out-of-pocket cost of a major hospital stay not found from a published source in this research pass (National Health Insurance covers most costs with 20% inpatient coinsurance plus non-covered items).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KR', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Private indemnity health insurance (실손보험) is priced per policy, not per amount of cover; no published premium table per KRW 100,000 found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KR', 1, 'inflation_cpi', 0.029, NULL, 'sourced', 'Bank of Korea ECOS, consumer price index (all items, 2020=100), from Ministry of Data and Statistics', 'https://ecos.bok.or.kr/api/StatisticSearch/sample/json/kr/1/10/901Y009/M/202608/202609/0', '2026-09-30', 'Index 120.43 in Sep 2026 against 117.06 in Sep 2025 (same series, https://ecos.bok.or.kr/api/StatisticSearch/sample/json/kr/1/10/901Y009/M/202509/202509/0) = 2.9% year on year.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KR', 1, 'inflation_projection', 0.025, NULL, 'assumption', 'Bank of Korea 2% target; CPI averaged 3.1% a year 2021-2025 (ECOS annual index 100 to 116.61)', 'https://ecos.bok.or.kr/api/StatisticSearch/sample/json/kr/1/10/901Y009/A/2020/2025/0', '2026-10-31', 'The 2% target is credible but inflation has run near 3% and the bank is raising rates, so 2.5% is used for planning.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KR', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Indicative term life (정기보험) premium rates per KRW 1,000 of cover not found from a published source in this research pass.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KR', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Industry-wide life claim settlement ratio not found in this research pass (the Financial Supervisory Service publishes non-payment ratios by insurer).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KR', 1, 'life_expectancy', 83.6, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=KR', '2024-12-31', 'Men 80.8, women 86.6 (2024).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KR', 1, 'life_table_remaining', NULL, '{"rows":[{"age":65,"total":21.68},{"age":80,"total":10.59}]}', 'sourced', 'UN World Population Prospects 2024 via Measured World', 'https://measuredworld.com/countries/south-korea/mortality/life-expectancy-progression', '2024-12-31', 'Secondary source reproducing UN WPP 2024; ages 60 and 70 and sex breakdown not found in this pass.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KR', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":65,"womenAge":65,"over90Monthly":null,"meansTested":true}', 'sourced', 'Pensions in South Korea (Wikipedia); Ministry of Health and Welfare Basic Pension site', 'https://en.wikipedia.org/wiki/Pensions_in_South_Korea', '2026-01-01', 'Basic Pension goes to people aged 65+ in the bottom 70% by income and assets; 2026 selection threshold KRW 2.47 million a month for a single person and KRW 3.952 million for a couple (basicpension.mohw.go.kr notice of 23 January 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KR', 1, 'old_age_allowance_monthly', 349700, NULL, 'sourced', 'Ministry of Health and Welfare, Basic Pension (기초연금) 2026 standard amount', 'https://basicpension.mohw.go.kr/board.es?mid=a10401000000&bid=0002&list_no=21872&act=view', '2026-01-01', 'Notice of 23 January 2026: standard monthly amount KRW 349,700 for a single recipient in 2026; couples receive 20% less each.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KR', 1, 'oop_health_share', 0.337, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=KR', '2024-12-31', NULL, 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KR', 1, 'policy_rate', 0.03, NULL, 'sourced', 'Bank of Korea base rate (ECOS 722Y001)', 'https://ecos.bok.or.kr/api/StatisticSearch/sample/json/kr/1/10/722Y001/D/20261020/20261029/0101000', '2026-10-22', 'Raised to 2.75% in July and 3.00% in August 2026; held at 3.00% on 22 October 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KR', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":18,"entryAgeMax":59,"pensionFromAge":65,"nomineeUntilAge":null,"inflationLinked":true,"taxFree":false}', 'sourced', 'National Pension (Korean Wikipedia, National Pension of South Korea)', 'https://ko.wikipedia.org/wiki/%EB%8C%80%ED%95%9C%EB%AF%BC%EA%B5%AD%EC%9D%98_%EA%B5%AD%EB%AF%BC%EC%97%B0%EA%B8%88', '2026-10-31', 'Residents 18 to under 60 must join; pension age 65 for anyone born in 1969 or later (63 for 1961-64, 64 for 1965-68); National Pension Act Article 51(2) adjusts pension amounts by the national CPI change after committee review; benefits are taxed as pension income.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KR', 1, 'retirement_accumulation_return_base', 0.05, NULL, 'assumption', 'Mix of after-tax safe rate 3% and equity base 7%', 'https://ecos.bok.or.kr/api/StatisticSearch/sample/json/kr/1/10/121Y002/M/202607/202609/BEABAA2118', '2026-10-31', 'About half equity at 7% and half safe assets at 3%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KR', 1, 'retirement_accumulation_return_high', 0.075, NULL, 'assumption', 'Mix with equity at the high case 11%', 'https://ecos.bok.or.kr/api/StatisticSearch/sample/json/kr/1/10/802Y001/D/20261026/20261030/0001000', '2026-10-31', 'High case if equities repeat their recent 10-year record.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KR', 1, 'retirement_accumulation_return_low', 0.03, NULL, 'assumption', 'Mix of deposits (3.0% after tax) and equity low case (3%)', 'https://ecos.bok.or.kr/api/StatisticSearch/sample/json/kr/1/10/121Y002/M/202607/202609/BEABAA2118', '2026-10-31', 'Low case for a balanced mix in a weak decade.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KR', 1, 'retirement_age_default', 65, NULL, 'sourced', 'National Pension pension age schedule (Korean Wikipedia, National Pension of South Korea)', 'https://ko.wikipedia.org/wiki/%EB%8C%80%ED%95%9C%EB%AF%BC%EA%B5%AD%EC%9D%98_%EA%B5%AD%EB%AF%BC%EC%97%B0%EA%B8%88', '2026-10-31', 'National Pension old-age pension starts at 65 for anyone born in 1969 or later (63 for 1961-64, 64 for 1965-68); the legal minimum mandatory retirement age in firms is 60. Secondary source (Korean Wikipedia).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KR', 1, 'retirement_age_government', 60, NULL, 'sourced', 'State Public Officials Act, Article 74', 'https://www.law.go.kr/%EB%B2%95%EB%A0%B9/%EA%B5%AD%EA%B0%80%EA%B3%B5%EB%AC%B4%EC%9B%90%EB%B2%95/%EC%A0%9C74%EC%A1%B0', '2026-10-31', 'Article 74(1): public officials retire at 60 unless another law says otherwise, leaving on 30 June or 31 December of that year (current text).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KR', 1, 'retirement_return_base', 0.03, NULL, 'assumption', '1-year time deposit 3.57% and 1-year government bond 3.59% before 15.4% tax (about 3.0% after tax)', 'https://ecos.bok.or.kr/api/StatisticSearch/sample/json/kr/1/10/121Y002/M/202607/202609/BEABAA2118', '2026-10-31', 'Held at the after-tax 1-year deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KR', 1, 'retirement_return_high', 0.035, NULL, 'assumption', 'Retail government bonds and laddered treasury bonds after 15.4% tax', 'https://biz.sbs.co.kr/amp/article/20000337585', '2026-10-31', 'High case for locking in 5-10 year government bonds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KR', 1, 'retirement_return_low', 0.02, NULL, 'assumption', '1-year time deposit 3.57% and 1-year government bond 3.59% before 15.4% tax (about 3.0% after tax)', 'https://ecos.bok.or.kr/api/StatisticSearch/sample/json/kr/1/10/121Y002/M/202607/202609/BEABAA2118', '2026-10-31', 'Low case if deposit rates fall back with the base rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KR', 1, 'sanchayapatra_5y_rate', 0.04325, NULL, 'sourced', 'Ministry of Economy and Finance October 2026 retail government bond issue (via SBS Biz, 30 Sep 2026)', 'https://biz.sbs.co.kr/amp/article/20000337585', '2026-10-01', '5-year retail government bond: 4.275% coupon (September 5-year auction rate) plus 0.05 point bonus, compounded and paid at maturity; 10-year 4.79%, 20-year 4.95%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KR', 1, 'savings_account_rate', 0.001, NULL, 'sourced', 'Dealsite (Nov 2024): low-cost demand deposits pay about 0.1% a year', 'https://dealsite.co.kr/articles/131688', '2024-11-20', 'Article says low-cost deposits (ordinary demand and passbook deposits) pay about 0.1% a year; internet-bank parking accounts pay around 2% with conditions. Source dated November 2024 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KR', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":3.4},{"year":2040,"value":1.7},{"year":2065,"value":1}]}', 'sourced', 'UN WPP 2024 medium variant via PopulationPyramid.net; World Bank SP.POP.DPND.OL', 'https://www.populationpyramid.net/republic-of-korea/2040/', '2025-12-31', '100 / old-age dependency ratio: 29.3 (2025, World Bank), 57.9 (2040) and 97.6 (2065, populationpyramid.net/republic-of-korea/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KR', 1, 'tax_bank_interest', 0.154, NULL, 'sourced', 'PwC Worldwide Tax Summaries: Korea, individual income determination', 'https://taxsummaries.pwc.com/republic-of-korea/individual/income-determination', '2026-07-02', '15.4% withheld at source (14% national plus 1.4% local income tax); final unless interest and dividends exceed KRW 20 million a year. PwC page last reviewed 2 July 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KR', 1, 'tax_sanchayapatra_profit', 0.154, NULL, 'sourced', 'Newsis (Mar 2023) on retail government bond tax rules', 'https://www.newsis.com/view/NISX20230330_0002247546', '2023-03-30', 'Interest is taxed separately at 14% (plus 1.4% local tax) on up to KRW 200 million of purchases per person if held to maturity; early redemption loses the benefit. Source dated March 2023 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KR', 1, 'tbill_91d_rate', 0.0318, NULL, 'sourced', 'Bank of Korea ECOS, Monetary Stabilization Bond 91-day yield', 'https://ecos.bok.or.kr/api/StatisticSearch/sample/json/kr/1/10/817Y002/D/20261026/20261030/010400000', '2026-10-30', 'Korea issues no regular 91-day treasury bill; the central bank''s 91-day bond is the standard 3-month government rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KR', 1, 'tbond_10y_rate', 0.0401, NULL, 'sourced', 'Bank of Korea ECOS, 10-year Korea Treasury Bond yield', 'https://ecos.bok.or.kr/api/StatisticSearch/sample/json/kr/1/10/817Y002/D/20261026/20261030/010210000', '2026-10-30', '4.008% on 30 October 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KR', 1, 'tbond_5y_rate', 0.0387, NULL, 'sourced', 'Bank of Korea ECOS, 5-year Korea Treasury Bond yield', 'https://ecos.bok.or.kr/api/StatisticSearch/sample/json/kr/1/10/817Y002/D/20261026/20261030/010200001', '2026-10-30', '3.865% on 30 October 2026.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('KW', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"KW","iso3":"KWT","nameEn":"Kuwait","nameNative":"الكويت","region":"middle_east_north_africa","languages":["ar","en"],"currency":{"code":"KWD","symbol":"KD","decimals":3,"compact":"intl","usdRate":{"value":0.3082,"status":"sourced","sourceName":"Central Bank of Kuwait, Main Indicators: USD/KWD exchange rate","sourceUrl":"https://www.cbk.gov.kw/en/monetary-policy/market-operations/main-indicators","asOf":"2026-10-29","note":"0.30820/0.30830 dinar per US dollar (bid/ask) on 29 October 2026; the dinar is pegged to an undisclosed basket. World Bank 2025 average 0.3065. CLDR gives no narrow symbol; ''KD'' is the usual local abbreviation."}},"instruments":{"savings_account":{"available":true,"localName":"حساب توفير","localNameEn":"Savings account","note":"Savings accounts pay little; many offer prize draws instead of interest."},"fdr_3m":{"available":true,"localName":"وديعة لأجل (3 أشهر)","localNameEn":"Time deposit (3 months)","note":"Average counter rate 3.29% for KD deposits in September 2026.","sourceUrl":"https://www.cbk.gov.kw/en/redirects/download?compId=172793&esIndex=reports"},"fdr_1y":{"available":true,"localName":"وديعة لأجل (سنة)","localNameEn":"Time deposit (1 year)","note":"Average counter rate 3.60% for KD deposits in September 2026.","sourceUrl":"https://www.cbk.gov.kw/en/redirects/download?compId=172793&esIndex=reports"},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No standard monthly recurring deposit product was found."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate for individuals was found."},"tbill_91d":{"available":false,"localName":null,"localNameEn":null,"note":"No treasury bills are issued; the CBK''s own 3-month bonds and tawarruq are sold only to banks.","sourceUrl":"https://www.cbk.gov.kw/en/redirects/download?compId=172793&esIndex=reports"},"tbond_5y":{"available":false,"localName":"سندات الخزانة","localNameEn":"Treasury bonds","note":"Treasury bonds are issued through CBK auctions and held by local banks (all holdings in the CBK bulletin are banks); they are not sold to individuals.","sourceUrl":"https://www.cbk.gov.kw/en/redirects/download?compId=172793&esIndex=reports"},"tbond_10y":{"available":false,"localName":"سندات الخزانة","localNameEn":"Treasury bonds","note":"Treasury bonds are issued through CBK auctions and held by local banks (all holdings in the CBK bulletin are banks); they are not sold to individuals.","sourceUrl":"https://www.cbk.gov.kw/en/redirects/download?compId=172793&esIndex=reports"},"equity_fund":{"available":true,"localName":"صناديق الاستثمار","localNameEn":"Investment funds","note":"Local equity funds investing in Kuwaiti listed shares are available."},"gold":{"available":true,"localName":"الذهب","localNameEn":"Gold","note":"Gold bars, coins and jewellery are freely sold."}},"institutions":{"centralBank":{"name":"Central Bank of Kuwait (CBK)","url":"https://www.cbk.gov.kw/en"},"insuranceRegulator":{"name":"Insurance Regulatory Unit (IRU)","url":"https://www.iru.gov.kw/"},"insuranceComplaints":{"name":"Insurance Regulatory Unit (IRU), complaints","url":"https://www.iru.gov.kw/"},"pensionScheme":{"name":"Public Institution for Social Security (PIFSS)","url":"https://www.pifss.gov.kw/"},"publicHealthCover":{"name":"Ministry of Health (public health care for citizens)","url":"https://www.moh.gov.kw/"},"statistics":{"name":"Central Statistical Bureau (CSB)","url":"https://www.csb.gov.kw/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KW', 1, 'bank_deposit_avg_rate', 0.0257, NULL, 'sourced', 'Central Bank of Kuwait, Monthly Monetary Statistical Bulletin, September 2026, Table 16 (private-sector KD deposits by interest rate, weighted interest rate)', 'https://www.cbk.gov.kw/en/redirects/download?compId=172793&esIndex=reports', '2026-09-30', 'Weighted interest rate on all private-sector KD deposits at local banks, 2.57% in September 2026, including the 24% that pay no interest.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KW', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'The CBK caps consumer lending rates relative to the discount rate, but no current official page with the credit card rate or cap was read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KW', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'Deposits at local banks are guaranteed by the state under Law No. 30 of 2008, but no current CBK page stating the guarantee or a limit was read, so it is not recorded.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KW', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No industry-wide rate for a monthly recurring deposit product was found in the CBK statistics.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KW', 1, 'equity_return_base', 0.065, NULL, 'assumption', 'CBK 3-month deposit rate 3.29% (untaxed); Kuwait share market record (Trading Economics)', 'https://tradingeconomics.com/kuwait/stock-market', '2026-10-31', 'Base case: about 3 points above the untaxed deposit rate, within the 4-point cap, because the market has had a moderate, dividend-driven record.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KW', 1, 'equity_return_high', 0.09, NULL, 'assumption', 'Kuwait all-share index via Trading Economics', 'https://tradingeconomics.com/kuwait/stock-market', '2026-10-31', 'High case: a fuller equity premium, as in strong oil-price years.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KW', 1, 'equity_return_low', 0.03, NULL, 'assumption', 'Kuwait all-share index via Trading Economics (down 6.4% in the year to October 2026)', 'https://tradingeconomics.com/kuwait/stock-market', '2026-10-31', 'Low case: below the deposit rate, as in weak years for the oil-linked market.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KW', 1, 'fdr_1y_rate', 0.036, NULL, 'sourced', 'Central Bank of Kuwait, Monthly Monetary Statistical Bulletin, September 2026, Table 20 (average counter interest rates on customer KD time deposits, 12 months)', 'https://www.cbk.gov.kw/en/redirects/download?compId=172793&esIndex=reports', '2026-09-30', '3.602% on 12-month KD time deposits in September 2026; KD 25,000-50,000 deposits at conventional banks.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KW', 1, 'fdr_3m_rate', 0.0329, NULL, 'sourced', 'Central Bank of Kuwait, Monthly Monetary Statistical Bulletin, September 2026, Table 20 (average counter interest rates on customer KD time deposits, 3 months)', 'https://www.cbk.gov.kw/en/redirects/download?compId=172793&esIndex=reports', '2026-09-30', '3.294% on 3-month KD time deposits in September 2026; simple average of daily counter rates for KD 25,000-50,000 deposits at conventional banks (Islamic banks excluded).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KW', 1, 'fixed_income_return_base', 0.033, NULL, 'assumption', 'Central Bank of Kuwait, Monthly Monetary Statistical Bulletin, September 2026, Table 20 (3-month KD deposit 3.29%)', 'https://www.cbk.gov.kw/en/redirects/download?compId=172793&esIndex=reports', '2026-10-31', 'Base case: the untaxed 3-month KD deposit rate; government bonds are sold to banks, not to individuals.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KW', 1, 'fixed_income_return_high', 0.039, NULL, 'assumption', 'Central Bank of Kuwait, Monthly Monetary Statistical Bulletin, September 2026 (12-month deposit 3.60%; CBK 12-month bonds 3.875%)', 'https://www.cbk.gov.kw/en/redirects/download?compId=172793&esIndex=reports', '2026-10-31', 'High case: longer deposits or funds holding government bonds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KW', 1, 'fixed_income_return_low', 0.02, NULL, 'assumption', 'Central Bank of Kuwait, Monthly Monetary Statistical Bulletin, September 2026 (deposit rates)', 'https://www.cbk.gov.kw/en/redirects/download?compId=172793&esIndex=reports', '2026-10-31', 'Low case: deposit rates fall further if the discount rate is cut, untaxed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KW', 1, 'goal_inflation_education', 0.03, NULL, 'assumption', 'Trading Economics, Kuwait CPI education index 128.9 in July 2026 (2013=100), about 1.9% a year since 2013', 'https://tradingeconomics.com/kuwait/inflation-cpi', '2026-10-31', 'Education prices have risen about 1.9% a year since 2013; private school fees rise faster, so 0.5 points above the 2.5% assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KW', 1, 'goal_inflation_health', 0.03, NULL, 'assumption', 'Trading Economics, Kuwait CPI health index 127.5 in July 2026 (2013=100), about 1.8% a year since 2013', 'https://tradingeconomics.com/kuwait/inflation-cpi', '2026-10-31', 'Health prices have risen about 1.8% a year since 2013, a little below general inflation, but private care usually costs more over time, so 0.5 points above the 2.5% assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KW', 1, 'gold_return_base', 0.04, NULL, 'assumption', 'Central Bank of Kuwait exchange rate; long-run dollar gold trend', 'https://www.cbk.gov.kw/en/monetary-policy/market-operations/main-indicators', '2026-10-31', 'Base case: the long-run dollar gold trend of about 4% a year; the basket peg keeps the dinar close to the dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KW', 1, 'gold_return_high', 0.08, NULL, 'assumption', 'Central Bank of Kuwait exchange rate; long-run dollar gold trend', 'https://www.cbk.gov.kw/en/monetary-policy/market-operations/main-indicators', '2026-10-31', 'High case: strong dollar gold years.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KW', 1, 'gold_return_low', 0, NULL, 'assumption', 'Central Bank of Kuwait, USD/KWD 0.3082 (29 October 2026); dinar pegged to a basket', 'https://www.cbk.gov.kw/en/monetary-policy/market-operations/main-indicators', '2026-10-31', 'Low case: flat dollar gold and a stable dinar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KW', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'PwC (reviewed July 2026, https://taxsummaries.pwc.com/kuwait/individual/other-taxes) says 15 days'' pay a year for the first 3 years and 2/3 of a month after, but this conflicts with the widely cited Article 51 of the private-sector Labour Law (Law 6 of 2010: 15 days a year for the first 5 years, a month a year after, capped at 18 months'' pay); the law text (ILO NATLEX, Ministry sites) could not be read to settle it, so no rule is recorded. It mainly matters for expatriates, who are outside social security.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KW', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a major private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KW', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No public table of private health insurance premiums by age was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KW', 1, 'inflation_cpi', 0.0219, NULL, 'sourced', 'Trading Economics, citing the Central Statistical Bureau, CPI July 2026', 'https://tradingeconomics.com/kuwait/inflation-cpi', '2026-07-31', 'Consumer prices up 2.19% year on year in July 2026 (2.19% in June); secondary source because the CSB release was not read. World Bank 2025 average 2.36%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KW', 1, 'inflation_projection', 0.025, NULL, 'assumption', 'World Bank CPI inflation 2021-2025 (about 3% average, 2.4% in 2025); latest 2.19% (July 2026); dinar pegged to a currency basket', 'https://data.worldbank.org/indicator/FP.CPI.TOTL.ZG?locations=KW', '2026-10-31', 'Inflation has eased from 4% in 2022 to about 2.2-2.4%, with the dinar pegged to an undisclosed basket, so 2.5% a year is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KW', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life cover is sold, but no regulator or other public table of premiums per KD 1,000 of cover by age was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KW', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Insurance Regulatory Unit publishes no industry-wide life claim settlement ratio that could be found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KW', 1, 'life_expectancy', 81, NULL, 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net, life expectancy at birth, Kuwait, 2026', 'https://www.populationpyramid.net/mortality/kuwait/', '2026-07-01', '81.0 years (men 79.8, women 82.3), UN WPP 2024 medium variant; secondary source. The World Bank (SP.DYN.LE00.IN) gives 84.6 for 2024.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KW', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":23.2,"men":22.5,"women":23.9},{"age":65,"total":18.7,"men":18,"women":19.4},{"age":70,"total":14.5,"men":13.7,"women":15.2},{"age":80,"total":7.8,"men":7.2,"women":8.3}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/kuwait/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KW', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'Eligibility rules for social assistance to older people could not be read from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KW', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'Older Kuwaitis on low incomes can get means-tested social assistance from the Ministry of Social Affairs, but no current amount for an older person could be read from an official source; non-Kuwaitis are not covered.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KW', 1, 'oop_health_share', 0.1, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), Kuwait', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=KW', '2023-12-31', '10.0% in 2023 (WHO Global Health Expenditure Database via the World Bank); older than 2025, the latest available.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KW', 1, 'policy_rate', 0.035, NULL, 'sourced', 'Central Bank of Kuwait, Main Indicators: discount rate', 'https://www.cbk.gov.kw/en/monetary-policy/market-operations/main-indicators', '2026-10-29', 'Discount rate 3.50% (last changed 11 December 2025); overnight repo 3.125%, 1-week 3.375%, 1-month 3.625%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KW', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":18,"entryAgeMax":65,"pensionFromAge":55,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":true}', 'sourced', 'Public Institution for Social Security (PIFSS), Insurance guide (دليل التأمينات), edition 10; PwC Kuwait (no personal income tax)', 'https://www.pifss.gov.kw/Lists/BriefLegislationGuideList/Attachments/1/%d8%af%d9%84%d9%8a%d9%84%20%d8%a7%d9%84%d8%aa%d8%a7%d9%94%d9%85%d9%8a%d9%86%d8%a7%d8%aa-%20%d8%b9%d8%b1%d8%a8%d9%8a%2010.pdf', '2023-01-03', 'Compulsory social insurance for Kuwaiti nationals in government and private jobs (employee 10.5%, employer 11.5% per PwC); pension from 55 for men and 50 for women with 15+ years (best rate at 30 years); increases come from a separate pension-increase fund, not CPI indexation. Guide dated January 2023; non-Kuwaitis are not covered.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KW', 1, 'retirement_accumulation_return_base', 0.048, NULL, 'assumption', 'Central Bank of Kuwait, Monthly Monetary Statistical Bulletin, September 2026; equity base 6.5%; gold base 4%', 'https://www.cbk.gov.kw/en/redirects/download?compId=172793&esIndex=reports', '2026-10-31', 'Base case: a balanced mix of deposits, Gulf equities and some gold.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KW', 1, 'retirement_accumulation_return_high', 0.065, NULL, 'assumption', 'Central Bank of Kuwait, Monthly Monetary Statistical Bulletin, September 2026; equity high 9%', 'https://www.cbk.gov.kw/en/redirects/download?compId=172793&esIndex=reports', '2026-10-31', 'High case: a growth-leaning mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KW', 1, 'retirement_accumulation_return_low', 0.03, NULL, 'assumption', 'Central Bank of Kuwait, Monthly Monetary Statistical Bulletin, September 2026 (deposits and government bonds)', 'https://www.cbk.gov.kw/en/redirects/download?compId=172793&esIndex=reports', '2026-10-31', 'Low case: a mix earning about the deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KW', 1, 'retirement_age_default', 55, NULL, 'sourced', 'Public Institution for Social Security (PIFSS), Insurance guide (دليل التأمينات), edition 10', 'https://www.pifss.gov.kw/Lists/BriefLegislationGuideList/Attachments/1/%d8%af%d9%84%d9%8a%d9%84%20%d8%a7%d9%84%d8%aa%d8%a7%d9%94%d9%85%d9%8a%d9%86%d8%a7%d8%aa-%20%d8%b9%d8%b1%d8%a8%d9%8a%2010.pdf', '2023-01-03', 'Legal retirement age 55 for civilian men and 50 for civilian women (Kuwaiti nationals), with a full pension after 30 years of service and a 15-year minimum; early retirement up to 5 years before with a reduction. The guide dates from January 2023 (older than 2025) and no later amendment could be checked; this is taken as the age for people born after 1975.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KW', 1, 'retirement_age_government', 55, NULL, 'sourced', 'Public Institution for Social Security (PIFSS), Insurance guide (دليل التأمينات), edition 10', 'https://www.pifss.gov.kw/Lists/BriefLegislationGuideList/Attachments/1/%d8%af%d9%84%d9%8a%d9%84%20%d8%a7%d9%84%d8%aa%d8%a7%d9%94%d9%85%d9%8a%d9%86%d8%a7%d8%aa-%20%d8%b9%d8%b1%d8%a8%d9%8a%2010.pdf', '2023-01-03', 'Kuwaiti civil servants are insured with PIFSS under the same civilian rules: 55 for men, 50 for women (military 45); the guide dates from January 2023.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KW', 1, 'retirement_return_base', 0.033, NULL, 'assumption', 'Central Bank of Kuwait, Monthly Monetary Statistical Bulletin, September 2026, Table 20 (3-month KD deposit 3.29%; 12-month 3.60%)', 'https://www.cbk.gov.kw/en/redirects/download?compId=172793&esIndex=reports', '2026-10-31', 'Base case: the untaxed 3-month deposit rate, below the 1-year deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KW', 1, 'retirement_return_high', 0.038, NULL, 'assumption', 'Central Bank of Kuwait, Monthly Monetary Statistical Bulletin, September 2026 (12-month deposit 3.60%)', 'https://www.cbk.gov.kw/en/redirects/download?compId=172793&esIndex=reports', '2026-10-31', 'High case: longer deposits and bond funds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KW', 1, 'retirement_return_low', 0.02, NULL, 'assumption', 'Central Bank of Kuwait, Monthly Monetary Statistical Bulletin, September 2026 (deposit rates)', 'https://www.cbk.gov.kw/en/redirects/download?compId=172793&esIndex=reports', '2026-10-31', 'Low case: lower deposit rates after future rate cuts.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KW', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate or retail savings bond for individuals was found; treasury bonds and CBK bonds are sold to banks.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KW', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The CBK publishes counter rates on time deposits only; no average rate for savings accounts was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KW', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":24.84},{"year":2040,"value":15.15},{"year":2065,"value":10.87}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/kuwait/2040/', '2025-12-31', '100 / old-age dependency ratio: 4.03 (2025, World Bank), 6.6 (2040) and 9.2 (2065, populationpyramid.net/kuwait/2065/); the large young migrant workforce keeps the ratio very high.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KW', 1, 'tax_bank_interest', 0, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Kuwait, taxes on personal income', 'https://taxsummaries.pwc.com/kuwait/individual/taxes-on-personal-income', '2026-10-31', 'There is no personal income tax in Kuwait, so bank interest is untaxed for individuals.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KW', 1, 'tax_sanchayapatra_profit', 0, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Kuwait, taxes on personal income', 'https://taxsummaries.pwc.com/kuwait/individual/taxes-on-personal-income', '2026-10-31', 'No personal income tax, so returns on government securities are untaxed for individuals (no retail savings certificate exists).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KW', 1, 'tbill_91d_rate', 0.03625, NULL, 'sourced', 'Central Bank of Kuwait, Monthly Monetary Statistical Bulletin, September 2026, Table 8-1 (CBK bonds and related tawarruq, 3-month rate)', 'https://www.cbk.gov.kw/en/redirects/download?compId=172793&esIndex=reports', '2026-09-30', 'Rate on 3-month CBK bonds (a monetary instrument sold to banks) 3.625% since December 2025; no 3-month treasury bills are issued and no 3-month CBK bonds were outstanding in September 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KW', 1, 'tbond_10y_rate', 0.05125, NULL, 'sourced', 'Central Bank of Kuwait, Monthly Monetary Statistical Bulletin, September 2026, Table 8 (public debt instruments, interest rate on new issues, 10 years)', 'https://www.cbk.gov.kw/en/redirects/download?compId=172793&esIndex=reports', '2025-10-31', 'Latest 10-year issue was in October 2025 at 5.125%, before rates fell; no 10-year bond has been issued since and a 7-year bond was issued at 3.625% in September 2026, so the current 10-year yield is probably much lower. Treat as stale.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KW', 1, 'tbond_5y_rate', 0.03375, NULL, 'sourced', 'Central Bank of Kuwait, Monthly Monetary Statistical Bulletin, September 2026, Table 8 (public debt instruments, interest rate on new issues, 5 years)', 'https://www.cbk.gov.kw/en/redirects/download?compId=172793&esIndex=reports', '2026-08-31', '5-year treasury bonds issued in August 2026 at 3.375% (3.25% in June and July 2026); public debt issuance resumed in 2025.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('KZ', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"KZ","iso3":"KAZ","nameEn":"Kazakhstan","nameNative":"Қазақстан","region":"europe_central_asia","languages":["kk","ru","en","de"],"currency":{"code":"KZT","symbol":"₸","decimals":2,"compact":"intl","usdRate":{"value":453.87,"status":"sourced","sourceName":"National Bank of Kazakhstan, official exchange rates","sourceUrl":"https://nationalbank.kz/rss/get_rates.cfm?fdate=31.10.2026","asOf":"2026-10-31","note":"Official rate KZT 453.87 per US dollar on 31 October 2026; the tenge gained about 14% against the dollar over the past year. World Bank 2025 average 521.0."}},"instruments":{"savings_account":{"available":true,"localName":"Жинақ салымы","localNameEn":"Savings / demand deposit","note":"Demand and savings deposits pay high rates; interest is not taxed.","sourceUrl":"https://kdif.kz/ru/reward-rates"},"fdr_3m":{"available":true,"localName":"Мерзімді салым (3 ай)","localNameEn":"Term deposit (3 months)"},"fdr_1y":{"available":true,"localName":"Мерзімді салым (12 ай)","localNameEn":"Term deposit (1 year)","sourceUrl":"https://kdif.kz/ru/reward-rates"},"dps":{"available":true,"localName":"Толықтырылатын мерзімді салым","localNameEn":"Replenishable term deposit","note":"No standard monthly recurring-deposit product; replenishable term or savings deposits are used for regular saving.","sourceUrl":"https://kdif.kz/ru/reward-rates"},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate for individuals; Ministry of Finance bonds (MEUKAM) can be bought on the exchange through a broker."},"tbill_91d":{"available":true,"localName":"Ұлттық Банктің қысқа мерзімді ноталары","localNameEn":"National Bank short-term notes (91-day)","note":"Sold at NBK auctions to banks and professional investors; individuals buy through a broker.","sourceUrl":"https://www.nationalbank.kz/en/auction/aukcion-nbk-po-razmeshcheniyu-kratkosrochnyh-not"},"tbond_5y":{"available":true,"localName":"МЕУКАМ","localNameEn":"Ministry of Finance medium-term bonds (MEUKAM)","sourceUrl":"https://kase.kz/ru/information/news/show/1577327"},"tbond_10y":{"available":true,"localName":"МЕУКАМ","localNameEn":"Ministry of Finance long-term bonds (MEUKAM)","sourceUrl":"https://kase.kz/ru/information/news/show/1577329"},"equity_fund":{"available":true,"localName":"Инвестициялық пай қорлары","localNameEn":"Unit investment funds and ETFs","note":"Retail funds and exchange-traded funds are available through brokers; the local market is small."},"gold":{"available":true,"localName":"Аффинирленген алтын құймалары","localNameEn":"Refined gold bars","note":"Legal to buy and hold; refined gold bars produced for the National Bank are sold to the public (not re-checked against an official page in this verification)."}},"institutions":{"centralBank":{"name":"National Bank of Kazakhstan","url":"https://nationalbank.kz/"},"insuranceRegulator":{"name":"Agency for Regulation and Development of the Financial Market (ARDFM)","url":"https://www.gov.kz/memleket/entities/ardfm"},"insuranceComplaints":{"name":"Agency for Regulation and Development of the Financial Market (ARDFM), consumer rights protection","url":"https://www.gov.kz/org/ardfm/activities/1001","note":"Insurance disputes go first to the Insurance Ombudsman (mandatory pre-court step since 1 January 2024); its own website could not be reached from outside Kazakhstan, so the regulator''s consumer protection page is given."},"pensionScheme":{"name":"Unified Accumulative Pension Fund (ENPF)","url":"https://www.enpf.kz/"},"oldAgeAllowance":{"name":"Basic pension payment (Ministry of Labour and Social Protection)","url":"https://www.gov.kz/memleket/entities/social-musrepov/press/news/details/1124606?lang=ru"},"publicHealthCover":{"name":"Social Health Insurance Fund (compulsory social health insurance, OSMS)","url":"https://fms.kz/","note":"Guaranteed free medical care for all citizens plus OSMS cover for insured people."},"depositInsurance":{"name":"Kazakhstan Deposit Insurance Fund (KDIF)","url":"https://kdif.kz/ru/what-we-guarantee"},"statistics":{"name":"Bureau of National Statistics (ASPR)","url":"https://stat.gov.kz/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KZ', 1, 'bank_deposit_avg_rate', 0.147, NULL, 'sourced', 'Trend News Agency, citing the Agency for Regulation and Development of the Financial Market (ARDFM)', 'https://www.trend.az/casia/kazakhstan/4221527.html', '2026-07-31', 'Weighted average rate on individuals'' tenge term deposits in July 2026, unchanged from June; secondary source (news) relaying official statistics.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KZ', 1, 'credit_card_rate_cap', 0.46, NULL, 'sourced', 'National Bank of Kazakhstan, information message on maximum annual effective rates', 'https://nationalbank.kz/ru/news/informacionnye-soobshcheniya/19332', '2026-05-16', 'Legal maximum annual effective rate (GESV) of 46% on unsecured bank loans (35% secured), set jointly by ARDFM and the NBK from 16 May 2026; card credit is unsecured lending, though the message does not name cards.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KZ', 1, 'deposit_insurance_limit', 20000000, NULL, 'sourced', 'Kazakhstan Deposit Insurance Fund (KDIF), What we guarantee', 'https://kdif.kz/ru/what-we-guarantee', '2026-10-31', 'Up to KZT 20 million for tenge savings deposits, KZT 10 million for other tenge deposits and KZT 5 million for foreign-currency deposits, with a combined maximum of KZT 20 million per depositor per bank.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KZ', 1, 'dps_rate', 0.1266, NULL, 'sourced', 'Kazakhstan Deposit Insurance Fund (KDIF), market rates on new tenge deposits of individuals, September 2026', 'https://kdif.kz/ru/reward-rates', '2026-09-30', 'Rate on replenishable term and savings deposits over 24 months, the closest match to a monthly recurring deposit; banks do not sell a standard recurring-deposit scheme.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KZ', 1, 'equity_return_base', 0.13, NULL, 'assumption', 'KASE index (Trading Economics); 1-year deposits 15.26% tax-free (KDIF); MEUKAM 5-year 14.10%', 'https://tradingeconomics.com/kazakhstan/stock-market', '2026-10-31', 'The KASE index rose strongly over the past decade, but the base is set near the long-run safe rate expected once inflation falls (about 10-11%) plus 2-3 points, well below today''s deposit rate plus 4.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KZ', 1, 'equity_return_high', 0.17, NULL, 'assumption', 'KASE index 10-year record (Trading Economics)', 'https://tradingeconomics.com/kazakhstan/stock-market', '2026-10-31', 'High case: a repeat of the KASE index''s strong 2016-2026 run in tenge.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KZ', 1, 'equity_return_low', 0.08, NULL, 'assumption', 'KASE index 7,916 on 30 Oct 2026, up 11% in a year (Trading Economics); inflation projection 8%', 'https://tradingeconomics.com/kazakhstan/stock-market', '2026-10-31', 'Low case: Kazakh shares, a small market dominated by a few large issuers, only keep pace with inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KZ', 1, 'fdr_1y_rate', 0.1526, NULL, 'sourced', 'Kazakhstan Deposit Insurance Fund (KDIF), market rates on new tenge deposits of individuals, September 2026', 'https://kdif.kz/ru/reward-rates', '2026-09-30', 'Weighted average effective rate on new 12-month tenge term and savings deposits without top-up (15.13% with top-up). Interest on deposits is not taxed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KZ', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'KDIF publishes market rates for 1-, 6-, 12- and 24-month tenge term deposits (16.22% for 1 month and 17.95% for 6 months without top-up, September 2026), but no 3-month rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KZ', 1, 'fixed_income_return_base', 0.11, NULL, 'assumption', '1-year deposits 15.26% tax-free (KDIF, Sep 2026); base rate 15.75% falling', 'https://kdif.kz/ru/reward-rates', '2026-10-31', 'Base case: tax-free deposit rates settle about 3 points above the 8% long-run inflation assumption, below today''s 15%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KZ', 1, 'fixed_income_return_high', 0.145, NULL, 'assumption', '1-year deposits 15.26% and MEUKAM 14.1% (Sep-Oct 2026)', 'https://kdif.kz/ru/reward-rates', '2026-10-31', 'High case: today''s high tax-free deposit and bond rates persist.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KZ', 1, 'fixed_income_return_low', 0.08, NULL, 'assumption', 'Inflation projection 8%; NBK 5% target', 'https://kdif.kz/ru/reward-rates', '2026-10-31', 'Low case: deposit rates fall towards inflation as the NBK keeps cutting.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KZ', 1, 'goal_inflation_education', 0.1, NULL, 'assumption', 'BNS: paid services +8.9% year on year (Sep 2026); inflation projection 8%', 'https://stat.gov.kz/en/industries/economy/prices/publications/517844/', '2026-10-31', 'Private school and university fees have tended to rise faster than general prices, so 10% is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KZ', 1, 'goal_inflation_health', 0.09, NULL, 'assumption', 'BNS: paid services +8.9% year on year (Sep 2026); inflation projection 8%', 'https://stat.gov.kz/en/industries/economy/prices/publications/517844/', '2026-10-31', 'Medical services are paid services, which rose 8.9% in the year to September 2026; 9% assumes they stay slightly above general inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KZ', 1, 'gold_return_base', 0.09, NULL, 'assumption', 'Gold price history (Trading Economics); inflation gap between Kazakhstan (8% assumed) and the US (about 2-3%)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Base case: dollar gold rises about 4% a year and the tenge loses about 5% a year against the dollar, in line with the inflation gap.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KZ', 1, 'gold_return_high', 0.13, NULL, 'assumption', 'Gold price history (Trading Economics); tenge devaluations of 2014-2015 and 2022', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'High case: strong dollar gold plus a faster tenge depreciation, as in past devaluation periods.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KZ', 1, 'gold_return_low', 0.04, NULL, 'assumption', 'Gold USD 3,876/oz on 30 Oct 2026, down 3% on a year (Trading Economics); tenge 453.87 per USD (NBK)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Low case: flat dollar gold and a stable tenge, as in the past year when the tenge gained 14% against the dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KZ', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'Kazakhstan has no statutory gratuity paid on retirement or resignation; the Labour Code only gives severance (about one month''s average pay) when employment ends for reasons such as liquidation or staff reduction. No days-per-year rule exists to report; the severance rule was not read from the Labour Code text in this research.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KZ', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'Hospital care is covered by the state guaranteed package and compulsory social health insurance (OSMS); no official figure for the typical out-of-pocket cost of a major private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KZ', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Voluntary health insurance is mostly bought by employers; no age-banded premium table per KZT 100,000 of cover was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KZ', 1, 'inflation_cpi', 0.093, NULL, 'sourced', 'Bureau of National Statistics (ASPR), Inflation in September 2026', 'https://stat.gov.kz/en/industries/economy/prices/publications/517844/', '2026-09-30', 'Consumer prices up 9.3% year on year in September 2026 (9.8% in August); food 8.5%, non-food 11%, paid services 8.9%. October figure due 2 November 2026. World Bank 2025 average 11.4%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KZ', 1, 'inflation_projection', 0.08, NULL, 'assumption', 'National Bank of Kazakhstan 5% target (to be reached in 2028); CPI 9.3% (Sep 2026), 2021-2025 average about 12.7% (World Bank, BNS)', 'https://stat.gov.kz/en/industries/economy/prices/publications/517844/', '2026-10-31', 'The 5% target has not been met in recent years and inflation averaged about 12-13% in 2021-2025, so a long-run 8% is used, between the target and the record.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KZ', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life cover is sold by life insurers, but no published premium table per KZT 1,000 of cover by age from ARDFM or another public body was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KZ', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'ARDFM publishes monthly insurance sector statistics, but no industry-wide life claim settlement ratio was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KZ', 1, 'life_expectancy', 75.97, NULL, 'sourced', 'Bureau of National Statistics, demographic statistics (life expectancy 2025, released 27 March 2026)', 'https://stat.gov.kz/en/industries/socialtatistics/demography/publications/479793/', '2025-12-31', 'Men 72.19, women 79.80 in 2025 (75.44 in 2024). UN WPP gives 74.8 for 2026 and the World Bank 74.5 for 2024.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KZ', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":20.4,"men":17.7,"women":22.4},{"age":65,"total":16.7,"men":14.4,"women":18.3},{"age":70,"total":13.3,"men":11.4,"women":14.5},{"age":80,"total":7.6,"men":6.6,"women":8}]}', 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/kazakhstan', '2026-07-01', 'Remaining years computed from georank''s expected age at death by current age (UN WPP mid-year estimate for 2026); UN WPP life expectancy is lower than the national 2025 figure.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KZ', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":63,"womenAge":63,"over90Monthly":null,"meansTested":false}', 'sourced', 'eGov (gov.kz), Pension age; Ministry of Labour 2026 amounts', 'https://www.gov.kz/situations/5/25?lang=ru', '2026-10-31', 'Basic pension payment from pension age, not means-tested; the amount depends on years of pension-system service. Men 63; women 61 today, rising by half a year each January from 2028 to 63 in 2031, so 63 applies to women born after 1968 and to anyone planning today.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KZ', 1, 'old_age_allowance_monthly', 35596, NULL, 'sourced', 'Ministry of Labour and Social Protection, pension and benefit amounts for 2026', 'https://www.gov.kz/memleket/entities/social-musrepov/press/news/details/1124606?lang=ru', '2026-01-01', 'Minimum state basic pension payment in 2026: 70% of the KZT 50,851 subsistence minimum, paid from pension age to people with 10 years or less (or no) pension-system service; it rises 2% of the subsistence minimum per extra year of service, up to KZT 60,005. Budget-funded, not means-tested.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KZ', 1, 'oop_health_share', 0.2764, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=KZ', '2023-12-31', 'Latest available year is 2023 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KZ', 1, 'policy_rate', 0.1575, NULL, 'sourced', 'National Bank of Kazakhstan, base rate decisions schedule', 'https://nationalbank.kz/en/news/grafik-prinyatiya-resheniy-po-bazovoy-stavke/rubrics/2365', '2026-10-27', 'Base rate cut from 16.25% to 15.75% (corridor 14.75-16.75%) at the decision of 27 October 2026 shown on the NBK schedule page; next announcement 4 December 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KZ', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":63,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":true}', 'sourced', 'eGov (gov.kz), Pension age; ENPF and news reports on 2026 contribution rates', 'https://www.gov.kz/situations/5/25?lang=ru', '2026-10-31', 'Funded defined-contribution system: employees pay 10% of pay (OPV) and employers 3.5% in 2026 (OPVR, rising to 5% by 2028) into individual ENPF accounts, paid out from pension age (63; women 61 rising to 63 by 2031) on top of the budget-funded basic pension. Accumulation payments are not indexed to inflation (basic and solidarity pensions are indexed yearly); pension payments are exempt from personal income tax from 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KZ', 1, 'retirement_accumulation_return_base', 0.12, NULL, 'assumption', 'Fixed income base 11%; equity base 13%', 'https://tradingeconomics.com/kazakhstan/stock-market', '2026-10-31', 'Base case: roughly half shares at 13% and half deposits and bonds at about 11%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KZ', 1, 'retirement_accumulation_return_high', 0.155, NULL, 'assumption', 'Fixed income high 14.5%; equity high 17%', 'https://tradingeconomics.com/kazakhstan/stock-market', '2026-10-31', 'High case for a growth-leaning balanced mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KZ', 1, 'retirement_accumulation_return_low', 0.085, NULL, 'assumption', 'Fixed income low 8%; equity low 8%', 'https://kdif.kz/ru/reward-rates', '2026-10-31', 'Low case for a balanced mix if both shares and deposits only match inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KZ', 1, 'retirement_age_default', 63, NULL, 'sourced', 'eGov (gov.kz), Pension age', 'https://www.gov.kz/situations/5/25?lang=ru', '2026-10-31', 'Pension age is 63 for men; for women 61 until 2027, rising by half a year each January from 2028 to reach 63 in 2031, so 63 applies to everyone born after 1975. Mothers of 5 or more children can retire at 53.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KZ', 1, 'retirement_age_government', 63, NULL, 'sourced', 'eGov (gov.kz), Pension age', 'https://www.gov.kz/situations/5/25?lang=ru', '2026-10-31', 'The eGov page gives one general pension age (63; women 61 rising to 63 by 2031) with no separate age for civil servants; some uniformed services have their own service pensions.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KZ', 1, 'retirement_return_base', 0.105, NULL, 'assumption', '1-year deposits 15.26% tax-free (KDIF, Sep 2026); NBK 91-day notes 16.16%', 'https://kdif.kz/ru/reward-rates', '2026-10-31', 'Base case below today''s tax-free 1-year deposit rate, allowing for rates falling as inflation comes down.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KZ', 1, 'retirement_return_high', 0.13, NULL, 'assumption', '1-year deposits 15.26% and MEUKAM 14.1% (Sep-Oct 2026)', 'https://kdif.kz/ru/reward-rates', '2026-10-31', 'High case: a retiree keeps earning rates close to today''s.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KZ', 1, 'retirement_return_low', 0.08, NULL, 'assumption', 'Inflation projection 8%; deposit rates (KDIF)', 'https://kdif.kz/ru/reward-rates', '2026-10-31', 'Low case: tax-free deposits earn only about inflation as rates fall.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KZ', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Kazakhstan has no government savings certificate or retail savings bond sold to individuals; people can buy Ministry of Finance bonds (MEUKAM) on the exchange through a broker (5-year yield 14.10% in October 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KZ', 1, 'savings_account_rate', 0.1508, NULL, 'sourced', 'Kazakhstan Deposit Insurance Fund (KDIF), market rates on new tenge deposits of individuals, September 2026', 'https://kdif.kz/ru/reward-rates', '2026-09-30', 'Weighted average effective rate on new non-term (demand) tenge deposits; current accounts and cards pay far less.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KZ', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":6.87},{"year":2040,"value":5.13},{"year":2065,"value":4.1}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/kazakhstan/2040/', '2025-12-31', '100 / old-age dependency ratio: 14.6 (2025, World Bank), 19.5 (2040) and 24.4 (2065, populationpyramid.net/kazakhstan/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KZ', 1, 'tax_bank_interest', 0, NULL, 'sourced', 'Digital Business: deposit interest of individuals is not taxed (Article 430 of the Tax Code; Ministry of National Economy)', 'https://digitalbusiness.kz/2026-08-27/kazahstantsev-napugali-nalogom-na-depoziti-otkuda-vzyalsya-etot-sluh/', '2026-08-27', 'Interest on individuals'' deposits in Kazakh banks is excluded from personal income tax under Article 430 of the 2026 Tax Code; the ministry denied plans for a 5% tax in August 2026. Secondary source (news).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KZ', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No retail government savings certificate exists. Interest on government securities is reported to be excluded from personal income tax under Article 430 of the 2026 Tax Code, but the official text could not be read (adilet.zan.kz needs JavaScript).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KZ', 1, 'tbill_91d_rate', 0.1616, NULL, 'sourced', 'National Bank of Kazakhstan, auctions of short-term notes (91-day)', 'https://www.nationalbank.kz/en/auction/aukcion-nbk-po-razmeshcheniyu-kratkosrochnyh-not', '2026-10-19', 'Weighted average yield of 91-day NBK notes at the 19 October 2026 auction (16.25% on 14 September). The Ministry of Finance issues few 3-month bills.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KZ', 1, 'tbond_10y_rate', 0.1389, NULL, 'sourced', 'Ministry of Finance MEUKAM placement results published by KASE (MUM156_0008, 11.6 years to maturity)', 'https://kase.kz/ru/information/news/show/1577329', '2026-10-06', 'Yield to maturity for satisfied orders at the 6 October 2026 Ministry of Finance placement of a bond with 11.6 years left (bid average 13.93%); no exact 10-year benchmark is published.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('KZ', 1, 'tbond_5y_rate', 0.141, NULL, 'sourced', 'Ministry of Finance MEUKAM placement results published by KASE (MUM072_0016, 5.3 years to maturity)', 'https://kase.kz/ru/information/news/show/1577327', '2026-10-06', 'Clearing yield to maturity for buyers at the 6 October 2026 Ministry of Finance placement (weighted average of all bids 14.23%); results published by the exchange where the Ministry auctions its bonds.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('LA', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"LA","iso3":"LAO","nameEn":"Laos","nameNative":"ລາວ","region":"east_asia_pacific","languages":["lo"],"currency":{"code":"LAK","symbol":"₭","decimals":0,"compact":"intl","usdRate":{"value":22518,"status":"sourced","sourceName":"Trading Economics, USD/LAK market rate","sourceUrl":"https://tradingeconomics.com/laos/currency","asOf":"2026-10-30","note":"Bank of the Lao PDR reference rate page could not be read (certificate error); World Bank 2025 average was 20,444 (PA.NUS.FCRF)."}},"instruments":{"savings_account":{"available":true,"localName":"ເງິນຝາກປະຢັດ","localNameEn":"Savings deposit"},"fdr_3m":{"available":true,"localName":"ເງິນຝາກມີກຳນົດ","localNameEn":"Fixed-term deposit","note":"Banks offer kip fixed deposits from 3 to 60 months; current rates not published online."},"fdr_1y":{"available":true,"localName":"ເງິນຝາກມີກຳນົດ","localNameEn":"Fixed-term deposit"},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No common monthly recurring deposit product found."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No standing government savings certificate; occasional short-term savings bonds have been sold to residents.","sourceUrl":"https://laotiantimes.com/2023/09/06/bol-to-issue-third-phase-of-government-bonds-worth-lak-3-trillion/"},"tbill_91d":{"available":false,"localName":null,"localNameEn":null,"note":"No retail treasury bill market found."},"tbond_5y":{"available":false,"localName":"ພັນທະບັດລັດຖະບານ","localNameEn":"Government bond","note":"Government bonds are issued irregularly via the Lao Securities Exchange; no regular 5-year retail issue."},"tbond_10y":{"available":false,"localName":null,"localNameEn":null,"note":"No 10-year kip government bond for retail investors found."},"equity_fund":{"available":false,"localName":null,"localNameEn":null,"note":"No retail mutual or index funds found; the Lao Securities Exchange lists only a few companies."},"gold":{"available":true,"localName":"ຄຳ","localNameEn":"Gold","note":"Gold is widely bought from gold shops."}},"institutions":{"centralBank":{"name":"Bank of the Lao PDR (BOL)","url":"https://www.bol.gov.la/"},"insuranceRegulator":{"name":"Ministry of Finance (insurance supervision)","url":"https://www.mof.gov.la/"},"insuranceComplaints":{"name":"Ministry of Finance (insurance supervision)","url":"https://www.mof.gov.la/","note":"No separate insurance ombudsman found; complaints go to the Ministry of Finance."},"pensionScheme":{"name":"Lao Social Security Organization (LSSO)","url":"https://www.lsso.gov.la/"},"oldAgeAllowance":null,"publicHealthCover":{"name":"Ministry of Health (National Health Insurance)","url":"https://www.moh.gov.la/"},"depositInsurance":null,"statistics":{"name":"Lao Statistics Bureau (LSB)","url":"https://www.lsb.gov.la/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LA', 1, 'bank_deposit_avg_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'World Bank FR.INR.DPST for Laos stops at 2010 (3%), far too old; no recent weighted average deposit rate found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LA', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap or typical credit card rate found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LA', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'A Deposit Protection Fund exists in Laos, but its website was unreachable and no current cover limit per depositor could be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LA', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No monthly recurring deposit product or rate found; large banks list only savings and fixed deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LA', 1, 'equity_return_base', 0.08, NULL, 'assumption', 'Policy rate 7% plus a small premium; weak local index record', 'https://laotiantimes.com/2026/08/21/laos-cuts-7-day-base-interest-rate-to-7-as-economic-risks-persist/', '2026-10-31', 'With a weak, illiquid local market we set the base only about 1 point above the 7% policy rate, well within 4 points of the tax-free safe rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LA', 1, 'equity_return_high', 0.12, NULL, 'assumption', 'Policy rate plus a full equity premium', 'https://laotiantimes.com/2026/08/21/laos-cuts-7-day-base-interest-rate-to-7-as-economic-risks-persist/', '2026-10-31', 'High case if listings deepen and returns keep pace with kip inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LA', 1, 'equity_return_low', 0, NULL, 'assumption', 'Lao Securities Exchange record; Bank of the Lao PDR policy rate', 'https://laotiantimes.com/2026/08/21/laos-cuts-7-day-base-interest-rate-to-7-as-economic-risks-persist/', '2026-10-31', 'The Lao Securities Exchange is very small and its index has fallen over the past decade, so the low case is zero in kip terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LA', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No current published kip 1-year fixed deposit rate found; bank rate sheets online date from 2019-2021.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LA', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No current published kip 3-month fixed deposit rate found; bank rate sheets online date from 2019-2021, before the 2022-2024 inflation and rate rises.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LA', 1, 'fixed_income_return_base', 0.055, NULL, 'assumption', 'Bank of the Lao PDR policy rate (7%); tax-free deposit interest', 'https://laotiantimes.com/2026/08/21/laos-cuts-7-day-base-interest-rate-to-7-as-economic-risks-persist/', '2026-10-31', 'Base case below the 7% policy rate since no current bank deposit rates could be verified. Safe LAK rates: no current published bank deposit rates found; Bank of the Lao PDR 7-day base rate 7% (Aug 2026); interest on deposits and bonds is exempt from personal income tax; inflation 7.7% (Oct 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LA', 1, 'fixed_income_return_high', 0.07, NULL, 'assumption', 'Bank of the Lao PDR policy rate (7%); tax-free deposit and bond interest', 'https://laotiantimes.com/2026/08/21/laos-cuts-7-day-base-interest-rate-to-7-as-economic-risks-persist/', '2026-10-31', 'High case at the policy rate, reachable with longer fixed deposits or government bonds. Safe LAK rates: no current published bank deposit rates found; Bank of the Lao PDR 7-day base rate 7% (Aug 2026); interest on deposits and bonds is exempt from personal income tax; inflation 7.7% (Oct 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LA', 1, 'fixed_income_return_low', 0.04, NULL, 'assumption', 'Bank of the Lao PDR policy rate (7%); tax-free deposit interest', 'https://laotiantimes.com/2026/08/21/laos-cuts-7-day-base-interest-rate-to-7-as-economic-risks-persist/', '2026-10-31', 'Low case well below the policy rate, as banks pay less on short deposits. Safe LAK rates: no current published bank deposit rates found; Bank of the Lao PDR 7-day base rate 7% (Aug 2026); interest on deposits and bonds is exempt from personal income tax; inflation 7.7% (Oct 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LA', 1, 'goal_inflation_education', 0.1, NULL, 'assumption', 'Lao Statistics Bureau CPI education group, +18.8% year on year in Sep 2026 (Laotian Times)', 'https://laotiantimes.com/2026/09/29/laos-inflation-rises-to-7-8-percent-in-september-as-education-utility-costs-climb/', '2026-10-31', 'Education prices are rising far faster than the headline CPI, so we plan 4 points above the inflation projection.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LA', 1, 'goal_inflation_health', 0.08, NULL, 'assumption', 'Lao Statistics Bureau CPI; Laotian Times report that health and medicine prices rose in Sep 2026', 'https://laotiantimes.com/2026/09/29/laos-inflation-rises-to-7-8-percent-in-september-as-education-utility-costs-climb/', '2026-10-31', 'No health sub-index figure was published; with 45% of health spending out of pocket we plan 2 points above the 6% inflation projection.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LA', 1, 'gold_return_base', 0.09, NULL, 'assumption', 'US-dollar gold trend; kip exchange rate (22,518 per USD, Oct 2026, vs 20,444 average in 2025)', 'https://tradingeconomics.com/laos/currency', '2026-10-31', 'Long-run dollar gold trend of about 5% plus about 4% a year of expected kip depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LA', 1, 'gold_return_high', 0.15, NULL, 'assumption', 'US-dollar gold trend; kip exchange rate history', 'https://tradingeconomics.com/laos/currency', '2026-10-31', 'High case for a strong gold cycle combined with renewed kip weakness.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LA', 1, 'gold_return_low', 0.03, NULL, 'assumption', 'US-dollar gold trend; kip exchange rate (22,518 per USD, Oct 2026)', 'https://tradingeconomics.com/laos/currency', '2026-10-31', 'Low case: gold flat in dollars with mild kip depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LA', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Labour Law provides severance only when a contract is terminated; no statutory end-of-service gratuity on retirement found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LA', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a major private hospital stay found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LA', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premium rates found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LA', 1, 'inflation_cpi', 0.077, NULL, 'sourced', 'Lao Statistics Bureau CPI, October 2026 (via Laotian Times)', 'https://laotiantimes.com/2026/10/28/laos-inflation-eases-to-7-7-percent-as-electricity-costs-remain-high/', '2026-10-31', '7.7% year on year in October 2026 (CPI 279.5 vs 259.6 a year earlier), down from 7.8% in September; the Lao Statistics Bureau home page shows the same figures but its report page could not be reached.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LA', 1, 'inflation_projection', 0.06, NULL, 'assumption', 'ADB Asian Development Outlook September 2026 (8.0% 2026, 6.5% 2027); Bank of the Lao PDR 2027 aim of 5.5-5.8%', 'https://www.adb.org/where-we-work/lao-pdr/economy', '2026-10-31', 'Inflation was above 20% in 2022-2024 and is easing (7.7% in Oct 2026); with ADB at 6.5% and the central bank aiming for 5.5-5.8% in 2027, we plan with a rounded 6% rather than the distorted 5-year average.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LA', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published term life premium rates or credible premium guide in kip found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LA', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No industry claim settlement ratio published by the Ministry of Finance insurance supervisor was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LA', 1, 'life_expectancy', 69.2, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN)', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=LA', '2024-12-31', 'Men 67.0, women 71.5 (2024, older than 2025); UN WPP via georank gives 69.7 for 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LA', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":17.4,"men":16.3,"women":18.6},{"age":65,"total":13.9,"men":13,"women":14.8},{"age":70,"total":10.7,"men":10,"women":11.4},{"age":80,"total":5.8,"men":5.5,"women":6.1}]}', 'sourced', 'UN World Population Prospects (via georank.org)', 'https://georank.org/life-expectancy/laos', '2026-07-08', 'Remaining years derived from expected age at death by current age (2026); secondary source for UN WPP.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LA', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LA', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension found; the national social security scheme pays only contributory pensions and lump sums.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LA', 1, 'oop_health_share', 0.448, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure, SH.XPD.OOPC.CH.ZS)', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=LA', '2023-12-31', 'Latest World Bank (WHO GHED) value is for 2023, older than 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LA', 1, 'policy_rate', 0.07, NULL, 'sourced', 'Bank of the Lao PDR Monetary Policy Committee decision of 20 August 2026 (Laotian Times)', 'https://laotiantimes.com/2026/08/21/laos-cuts-7-day-base-interest-rate-to-7-as-economic-risks-persist/', '2026-08-20', '7-day base interest rate cut from 8% to 7%; secondary source because the BOL website certificate could not be verified.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LA', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":60,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'Lao pension rules effective 2 June 2025 (Laotian Times)', 'https://laotiantimes.com/2025/06/23/lao-pension-rules-updated-25-year-contribution-required/', '2025-06-02', 'National social security pension (LSSO): full pension at 60 with 25 years of contributions, 1% cut per missing year down to 23 years; otherwise a lump sum of 85% x 1.5 months of final salary per contribution year. inflationLinked is false because the source describes no automatic indexation; entry ages and tax treatment were not found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LA', 1, 'retirement_accumulation_return_base', 0.065, NULL, 'assumption', 'Mix of kip deposits and local equity', 'https://laotiantimes.com/2026/08/21/laos-cuts-7-day-base-interest-rate-to-7-as-economic-risks-persist/', '2026-10-31', 'About half equity at 8% and half deposits near 5.5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LA', 1, 'retirement_accumulation_return_high', 0.09, NULL, 'assumption', 'Mix of kip deposits and local equity', 'https://laotiantimes.com/2026/08/21/laos-cuts-7-day-base-interest-rate-to-7-as-economic-risks-persist/', '2026-10-31', 'About 60% equity at the high case and 40% deposits or bonds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LA', 1, 'retirement_accumulation_return_low', 0.04, NULL, 'assumption', 'Mix of kip deposits and local equity', 'https://laotiantimes.com/2026/08/21/laos-cuts-7-day-base-interest-rate-to-7-as-economic-risks-persist/', '2026-10-31', 'Low case: mostly deposits, equity flat.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LA', 1, 'retirement_age_default', 60, NULL, 'sourced', 'Lao pension rules effective 2 June 2025 (Laotian Times)', 'https://laotiantimes.com/2025/06/23/lao-pension-rules-updated-25-year-contribution-required/', '2025-06-02', 'Normal pension age 60 with 25 years of social security contributions (rules effective 2 June 2025); men may retire from 57 and women from 55 depending on circumstances, with a 1% cut per missing contribution year down to 23 years.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LA', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'The 2025 pension-rule article cited for the private-sector age does not address civil servants (only that military and police follow separate laws); no official civil-service retirement age could be confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LA', 1, 'retirement_return_base', 0.055, NULL, 'assumption', 'Bank of the Lao PDR policy rate (7%); tax-free deposit interest', 'https://laotiantimes.com/2026/08/21/laos-cuts-7-day-base-interest-rate-to-7-as-economic-risks-persist/', '2026-10-31', 'Base case below the policy rate, as a stand-in for the tax-free 1-year deposit rate that could not be verified. Safe LAK rates: no current published bank deposit rates found; Bank of the Lao PDR 7-day base rate 7% (Aug 2026); interest on deposits and bonds is exempt from personal income tax; inflation 7.7% (Oct 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LA', 1, 'retirement_return_high', 0.07, NULL, 'assumption', 'Bank of the Lao PDR policy rate (7%)', 'https://laotiantimes.com/2026/08/21/laos-cuts-7-day-base-interest-rate-to-7-as-economic-risks-persist/', '2026-10-31', 'High case at the policy rate. Safe LAK rates: no current published bank deposit rates found; Bank of the Lao PDR 7-day base rate 7% (Aug 2026); interest on deposits and bonds is exempt from personal income tax; inflation 7.7% (Oct 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LA', 1, 'retirement_return_low', 0.04, NULL, 'assumption', 'Bank of the Lao PDR policy rate (7%); tax-free deposit interest', 'https://laotiantimes.com/2026/08/21/laos-cuts-7-day-base-interest-rate-to-7-as-economic-risks-persist/', '2026-10-31', 'Low case for kip deposits in retirement. Safe LAK rates: no current published bank deposit rates found; Bank of the Lao PDR 7-day base rate 7% (Aug 2026); interest on deposits and bonds is exempt from personal income tax; inflation 7.7% (Oct 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LA', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No standing government savings certificate; the Bank of the Lao PDR and Ministry of Finance have sold occasional short-term savings bonds to residents (e.g. 6-month bonds at 15% in 2023), with no current issue found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LA', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched the Bank of the Lao PDR site (unreachable, certificate error) and large bank rate pages (only 2019 and 2021 PDF rate sheets found); no current kip savings rate found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LA', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":13.5},{"year":2040,"value":9.4},{"year":2065,"value":4.2}]}', 'sourced', 'UN World Population Prospects 2024, medium variant (via populationpyramid.net)', 'https://www.populationpyramid.net/lao-peoples-democratic-republic/2040/', '2024-07-31', '100 / old-age dependency ratio: 7.4 in 2025, 10.6 in 2040 and 23.6 in 2065.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LA', 1, 'tax_bank_interest', 0, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Lao PDR, income determination', 'https://taxsummaries.pwc.com/lao-pdr/individual/income-determination', '2026-08-07', 'PwC (last reviewed 7 Aug 2026): interest on bank deposits and bonds is not subject to personal income tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LA', 1, 'tax_sanchayapatra_profit', 0, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Lao PDR, income determination', 'https://taxsummaries.pwc.com/lao-pdr/individual/income-determination', '2026-08-07', 'No savings certificate exists; interest on bonds is not subject to personal income tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LA', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published 91-day treasury bill yield found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LA', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published 10-year kip government bond yield found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LA', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published 5-year kip government bond yield found; government bonds are issued irregularly via the Lao Securities Exchange.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('LB', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"LB","iso3":"LBN","nameEn":"Lebanon","nameNative":"لبنان","region":"middle_east_north_africa","languages":["ar","apc","fr","en","hy"],"currency":{"code":"LBP","symbol":"L£","decimals":0,"compact":"intl","usdRate":{"value":89500,"status":"sourced","sourceName":"World Bank WDI PA.NUS.FCRF (official exchange rate, 2025 average)","sourceUrl":"https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=LB","asOf":"2025-12-31","note":"Banque du Liban has held the rate at about LBP 89,500 per dollar since 2024; Trading Economics shows 89,560 on 30 October 2026. bdl.gov.lb refused automated access."}},"instruments":{"savings_account":{"available":true,"localName":"حساب توفير","localNameEn":"Savings account","note":"Most new savings are held in ''fresh'' US dollars; old pre-2019 deposits remain largely frozen."},"fdr_3m":{"available":true,"localName":"وديعة لأجل","localNameEn":"Term deposit (3 months)"},"fdr_1y":{"available":true,"localName":"وديعة لأجل","localNameEn":"Term deposit (1 year)","sourceUrl":"https://tradingeconomics.com/lebanon/deposit-interest-rate"},"dps":{"available":false,"localName":null,"localNameEn":"Recurring deposit","note":"No standard monthly recurring deposit scheme with published rates was found."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":"Government savings certificate","note":"No government savings certificate or retail savings bond for individuals was found."},"tbill_91d":{"available":true,"localName":"سندات الخزينة بالليرة اللبنانية","localNameEn":"Lebanese pound treasury bills","note":"Auctioned by Banque du Liban, mainly to banks."},"tbond_5y":{"available":true,"localName":"سندات الخزينة بالليرة اللبنانية","localNameEn":"Lebanese pound treasury bonds","note":"Mainly held by banks; no current yield found."},"tbond_10y":{"available":false,"localName":"سندات اليوروبوندز","localNameEn":"Eurobonds","note":"Lebanon''s dollar Eurobonds have been in default since March 2020; no 10-year bond is being issued."},"equity_fund":{"available":false,"localName":null,"localNameEn":"Mutual fund","note":"No diversified local retail mutual or index fund was confirmed; the Beirut Stock Exchange lists only a few shares."},"gold":{"available":true,"localName":"ذهب (سبائك وليرات)","localNameEn":"Gold bars and coins","note":"Physical gold is freely bought and sold."}},"institutions":{"centralBank":{"name":"مصرف لبنان (Banque du Liban)","url":"https://www.bdl.gov.lb/"},"insuranceRegulator":{"name":"Insurance Control Commission (Ministry of Economy and Trade)","url":"https://www.economy.gov.lb/","note":"The commission''s own website could not be reached during research."},"insuranceComplaints":{"name":"Insurance Control Commission (Ministry of Economy and Trade)","url":"https://www.economy.gov.lb/"},"pensionScheme":{"name":"الصندوق الوطني للضمان الاجتماعي (National Social Security Fund)","url":"https://www.cnss.gov.lb/","note":"Pays the end-of-service indemnity; Law 319 of 2023 introduces a pension system."},"oldAgeAllowance":null,"publicHealthCover":{"name":"Ministry of Public Health (hospital care for the uninsured)","url":"https://www.moph.gov.lb/"},"depositInsurance":null,"statistics":{"name":"إدارة الإحصاء المركزي (Central Administration of Statistics)","url":"https://www.cas.gov.lb/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LB', 1, 'bank_deposit_avg_rate', 0.0455, NULL, 'sourced', 'Trading Economics, Lebanon deposit interest rate (Banque du Liban data)', 'https://tradingeconomics.com/lebanon/deposit-interest-rate', '2026-07-31', 'Average rate paid by commercial banks on deposits, 4.55% in July 2026 (5.19% in June); secondary source because bdl.gov.lb refused access. The page does not say whether it covers pound or dollar deposits; far below the 25% policy rate because the central bank steers the currency through the exchange rate, not interest rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LB', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap or published typical credit card rate was found; Banque du Liban circulars could not be read (access refused).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LB', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'The National Institute for the Guarantee of Deposits covers bank deposits, but its website did not resolve and no official page with the current limit in pounds could be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LB', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No monthly recurring deposit product with a published rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LB', 1, 'equity_return_base', 0.06, NULL, 'assumption', 'Beirut Stock Exchange main index (Trading Economics); average deposit rate 4.55% less 10% tax = 4.1%', 'https://tradingeconomics.com/lebanon/stock-market', '2026-10-31', 'Base case kept within 2 points of the after-tax deposit rate because the local index is tiny, illiquid and has a weak record; shares there are priced in dollars.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LB', 1, 'equity_return_high', 0.09, NULL, 'assumption', 'Beirut Stock Exchange main index (Trading Economics); long-run global equity returns', 'https://tradingeconomics.com/lebanon/stock-market', '2026-10-31', 'High case: a diversified (largely foreign) equity holding earning global equity returns of about 8-9% with a stable pound.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LB', 1, 'equity_return_low', 0.02, NULL, 'assumption', 'Beirut Stock Exchange main index (Trading Economics): about 1,648 in early Nov 2026, down 18.6% in a year and about 40% below its January 2025 high', 'https://tradingeconomics.com/lebanon/stock-market', '2026-10-31', 'Low case: the small Beirut market (a handful of bank and property shares) keeps its weak record and earns about half the deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LB', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published 1-year term deposit rate was found; Banque du Liban statistics pages refused automated access.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LB', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published 3-month term deposit rate was found; Banque du Liban statistics pages refused automated access.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LB', 1, 'fixed_income_return_base', 0.035, NULL, 'assumption', 'Average deposit rate 4.55% less 10% tax = 4.1%', 'https://tradingeconomics.com/lebanon/deposit-interest-rate', '2026-10-31', 'Base case slightly below the current after-tax average deposit rate, which is trending down.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LB', 1, 'fixed_income_return_high', 0.045, NULL, 'assumption', 'Average deposit rate 5.19% (Jun 2026) less 10% tax = 4.7%', 'https://tradingeconomics.com/lebanon/deposit-interest-rate', '2026-10-31', 'High case: deposit rates return to their June 2026 level.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LB', 1, 'fixed_income_return_low', 0.02, NULL, 'assumption', 'Average deposit rate 4.55% (Jul 2026) less 10% tax, falling from 5.19% in June', 'https://tradingeconomics.com/lebanon/deposit-interest-rate', '2026-10-31', 'Low case: deposit rates keep falling as they did in mid-2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LB', 1, 'goal_inflation_education', 0.09, NULL, 'assumption', 'CAS CPI 17.5% (Sep 2026); private school and university fees largely in dollars', 'https://www.cas.gov.lb/new/consumer-prices-september-2026/', '2026-10-31', 'Education (mostly private schools and universities charging partly in dollars) is assumed to rise a little faster than the 8% headline planning rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LB', 1, 'goal_inflation_health', 0.1, NULL, 'assumption', 'CAS CPI 17.5% (Sep 2026); health prices repriced in dollars after the crisis', 'https://www.cas.gov.lb/new/consumer-prices-september-2026/', '2026-10-31', 'Health costs (hospitals and medicines largely priced in dollars) are assumed to rise faster than the 8% headline planning rate; CAS did not publish a health sub-index in its September release.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LB', 1, 'gold_return_base', 0.05, NULL, 'assumption', 'Gold price history (Trading Economics); pound stable since 2023', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Base case: dollar gold rises with world inflation plus a little, with some allowance for renewed pound weakness.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LB', 1, 'gold_return_high', 0.1, NULL, 'assumption', 'Gold price history (Trading Economics); history of pound devaluation', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'High case: strong dollar gold plus renewed pound depreciation; gold has protected Lebanese savers through past currency collapses.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LB', 1, 'gold_return_low', 0.01, NULL, 'assumption', 'Gold price history (Trading Economics); pound held near 89,500 per dollar', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Low case: gold barely gains after the 2025-26 spike and the pound stays fixed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LB', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'Private employees covered by the National Social Security Fund receive an end-of-service indemnity based on last wage and years of service (employer contribution 5% of earnings per PwC), but the formula could not be read from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LB', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No official figure for the typical out-of-pocket cost of a major private hospital stay was found; the Ministry of Public Health publishes hospital tariffs for the cases it covers, but no typical patient cost.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LB', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premium table per LBP 100,000 of cover was found; private health plans are sold in US dollars.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LB', 1, 'inflation_cpi', 0.1753, NULL, 'sourced', 'Central Administration of Statistics, Consumer Prices - September 2026', 'https://www.cas.gov.lb/new/consumer-prices-september-2026/', '2026-09-30', 'CPI up 17.53% on September 2025 (released 21 October 2026); 16.7% in August per Trading Economics. World Bank 2025 average 14.6%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LB', 1, 'inflation_projection', 0.08, NULL, 'assumption', 'CAS CPI 17.5% (Sep 2026); World Bank 2025 average 14.6%; exchange rate held near LBP 89,500 per dollar since 2023', 'https://www.cas.gov.lb/new/consumer-prices-september-2026/', '2026-10-31', 'With the pound held stable against the dollar since 2023, prices should drift toward dollar inflation over time, but double-digit inflation persists, so 8% (well below the current rate, well above dollar inflation) is used; the 5-year average (hyperinflation of 2021-2023) is not a usable guide.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LB', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life cover is sold, but no published premium rates per LBP 1,000 of cover by age were found from the regulator or another public source; most cover is priced in US dollars.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LB', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No industry life claim settlement ratio from the Insurance Control Commission was found; its website could not be reached.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LB', 1, 'life_expectancy', 78.2, NULL, 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/lebanon', '2026-07-01', 'Men 76.2, women 80.1 (UN WPP estimate for 2026, mid-year); World Bank 2024 figure 77.9. Re-checked on georank 2026-11-03.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LB', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":22,"men":20.3,"women":23.5},{"age":65,"total":17.8,"men":16.3,"women":19.2},{"age":70,"total":14.1,"men":12.7,"women":15.2},{"age":80,"total":7.9,"men":7,"women":8.5}]}', 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/lebanon', '2026-07-01', 'Remaining years computed from georank''s expected age at death by current age (UN WPP 2026 estimate).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LB', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension with published eligibility ages was confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LB', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension that a person can claim today was confirmed; means-tested cash assistance from the Ministry of Social Affairs exists, but no old-age amount could be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LB', 1, 'oop_health_share', 0.297, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=LB', '2023-12-31', 'Older than 2025; latest available.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LB', 1, 'policy_rate', 0.25, NULL, 'sourced', 'Trading Economics, Lebanon interest rate (Banque du Liban data)', 'https://tradingeconomics.com/lebanon/interest-rate', '2026-07-31', 'Benchmark rate 25% (latest reading July 2026); secondary source because bdl.gov.lb refused automated access. Banque du Liban manages the currency mainly through its exchange-rate policy, so this rate has little effect on deposit rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LB', 1, 'public_pension_scheme', NULL, NULL, 'missing', '', '', '2026-10-31', 'Law 319 of 2023 replaces the NSSF end-of-service indemnity with a pension system for private employees, but its pension age, indexation and start date could not be read from an official source; cnss.gov.lb did not show them.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LB', 1, 'retirement_accumulation_return_base', 0.05, NULL, 'assumption', 'After-tax deposits 3.5% base; equity base 6%; gold base 5%', 'https://tradingeconomics.com/lebanon/deposit-interest-rate', '2026-10-31', 'Base case: a mix of deposits, gold and shares at about 5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LB', 1, 'retirement_accumulation_return_high', 0.07, NULL, 'assumption', 'Equity high 9%; gold high 10%; deposits 4.5%', 'https://tradingeconomics.com/lebanon/stock-market', '2026-10-31', 'High case for a growth-leaning mix with foreign shares and gold.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LB', 1, 'retirement_accumulation_return_low', 0.025, NULL, 'assumption', 'After-tax deposits about 4.1%; weak record of the Beirut Stock Exchange index', 'https://tradingeconomics.com/lebanon/deposit-interest-rate', '2026-10-31', 'Low case for a balanced mix if shares and deposit rates both disappoint.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LB', 1, 'retirement_age_default', NULL, NULL, 'missing', '', '', '2026-10-31', 'Private employees receive a lump-sum end-of-service indemnity from the National Social Security Fund rather than a pension; Law 319 of 2023 creates a pension system, but no official page giving the pension age could be read (cnss.gov.lb did not show it).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LB', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'No official page stating the current retirement age for civil servants could be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LB', 1, 'retirement_return_base', 0.035, NULL, 'assumption', 'Average deposit rate 4.55% less 10% tax = 4.1%', 'https://tradingeconomics.com/lebanon/deposit-interest-rate', '2026-10-31', 'Base case kept below the after-tax average deposit rate, as no treasury bill yield was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LB', 1, 'retirement_return_high', 0.045, NULL, 'assumption', 'Average deposit rate 5.19% (Jun 2026) less 10% tax = 4.7%', 'https://tradingeconomics.com/lebanon/deposit-interest-rate', '2026-10-31', 'High case: deposit rates recover to their June 2026 level.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LB', 1, 'retirement_return_low', 0.02, NULL, 'assumption', 'Average deposit rate 4.55% (Jul 2026) less 10% tax, falling', 'https://tradingeconomics.com/lebanon/deposit-interest-rate', '2026-10-31', 'Low case: deposit rates keep falling.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LB', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate or retail savings bond sold to individuals was found in Lebanon; government debt is sold as treasury bills and bonds through Banque du Liban auctions, mainly to banks.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LB', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical savings account rate was found; Banque du Liban pages refused automated access. Since the 2019 crisis, old deposits are largely frozen and new (''fresh'') deposits earn little.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LB', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":6.13},{"year":2040,"value":4.37},{"year":2065,"value":3.38}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/lebanon/2040/', '2025-12-31', '100 / old-age dependency ratio: 16.3 (2025, World Bank), 22.9 (2040) and 29.6 (2065, populationpyramid.net/lebanon/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LB', 1, 'tax_bank_interest', 0.1, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Lebanon: income determination (reviewed 1 July 2026)', 'https://taxsummaries.pwc.com/lebanon/individual/income-determination', '2026-07-01', '10% withholding tax on income from movable capital, which includes interest; PwC''s personal income page says Law 144 (2019 budget) raised the interest tax from 7%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LB', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'Lebanon has no retail government savings certificate; PwC lists treasury bill and bond interest under movable capital income taxed at 10%, but no savings-certificate tax applies.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LB', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Lebanese pound treasury bills are auctioned by Banque du Liban for the Ministry of Finance, but bdl.gov.lb and finance.gov.lb refused automated access and no recent 3-month yield was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LB', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 10-year yield was found; Lebanon''s dollar Eurobonds have been in default since March 2020 and Trading Economics shows no Lebanon bond yield.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LB', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No current 5-year Lebanese pound bond yield was found; Banque du Liban pages refused automated access.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('LC', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"LC","iso3":"LCA","nameEn":"Saint Lucia","nameNative":"Saint Lucia","region":"latin_america_caribbean","languages":["en","acf"],"currency":{"code":"XCD","symbol":"$","decimals":2,"compact":"intl","usdRate":{"value":2.7,"status":"sourced","sourceName":"World Bank WDI PA.NUS.FCRF","sourceUrl":"https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=LC","asOf":"2025-12-31","note":"The EC dollar has been fixed at 2.70 per US dollar by the Eastern Caribbean Central Bank since 1976."}},"instruments":{"savings_account":{"available":true,"localName":"Savings account","note":"ECCB minimum savings rate 2%; weighted average 2.07% (June 2026).","sourceUrl":"https://www.eccb-centralbank.org/statistics-category/mfs-interest-rates/interest-rates-and-weighted-averages-rates-on-deposits-and-loans/q?country_code[]=7"},"fdr_3m":{"available":false,"localName":null,"note":"Banks in Saint Lucia report no 3-month time-deposit rate to the ECCB; the shortest quoted term is 6 months (1.30-2.50%).","sourceUrl":"https://www.eccb-centralbank.org/statistics-category/mfs-interest-rates/interest-rates-on-deposits-and-loans/m?country_code[]=7"},"fdr_1y":{"available":true,"localName":"Fixed deposit","localNameEn":"12-month fixed (time) deposit","note":"Posted 12-month rates 0.10-2.50% (2026).","sourceUrl":"https://www.eccb-centralbank.org/statistics-category/mfs-interest-rates/interest-rates-on-deposits-and-loans/m?country_code[]=7"},"dps":{"available":false,"localName":null,"note":"No standard monthly recurring deposit product with a published rate."},"sanchayapatra_5y":{"available":false,"localName":null,"note":"No government savings certificate or retail savings bond for individuals was found."},"tbill_91d":{"available":true,"localName":"Treasury bill","localNameEn":"Government of Saint Lucia 91-day Treasury bill","note":"Auctioned on the Regional Government Securities Market through licensed intermediaries; mostly bought by institutions.","sourceUrl":"https://www.eccb-centralbank.org/statistics-category/regional-government-securities-market/weighted-average-interest-rates-on-the-rgsm/m?country_code[]=7"},"tbond_5y":{"available":true,"localName":"Government bond","localNameEn":"Government of Saint Lucia 5-year bond","note":"Issued occasionally on the Regional Government Securities Market (2024 and 2025).","sourceUrl":"https://www.eccb-centralbank.org/statistics-category/regional-government-securities-market/weighted-average-interest-rates-on-the-rgsm/a?country_code[]=7"},"tbond_10y":{"available":true,"localName":"Government bond","localNameEn":"Government of Saint Lucia 10-year bond","note":"Issued occasionally on the Regional Government Securities Market (2022-2024; none since).","sourceUrl":"https://www.eccb-centralbank.org/statistics-category/regional-government-securities-market/weighted-average-interest-rates-on-the-rgsm/a?country_code[]=7"},"equity_fund":{"available":false,"localName":null,"note":"No locally registered retail equity or index fund was identified; the regional share market is very small."},"gold":{"available":true,"localName":"Gold","localNameEn":"Gold jewellery and coins","note":"No legal restriction on buying gold; mostly sold as jewellery."}},"institutions":{"centralBank":{"name":"Eastern Caribbean Central Bank (ECCB)","url":"https://www.eccb-centralbank.org/","note":"Shared central bank of the Eastern Caribbean Currency Union."},"insuranceRegulator":{"name":"Financial Services Regulatory Authority (FSRA)","url":"https://www.fsrastlucia.org/index.php/insurance-pensions/insurance-companies/overview"},"insuranceComplaints":{"name":"Financial Services Regulatory Authority (FSRA), complaints","url":"https://www.fsrastlucia.org/index.php/complaints","note":"No separate insurance ombudsman; complaints about regulated insurers go to the FSRA."},"pensionScheme":{"name":"National Insurance Corporation (NIC), retirement benefit","url":"https://www.stlucianic.org/retirement-benefit"},"oldAgeAllowance":null,"publicHealthCover":{"name":"Ministry of Health, Wellness and Nutrition (public hospitals and wellness centres)","url":"https://health.govt.lc/","note":"No national health insurance yet; a draft Universal Health Coverage Bill was published for consultation in October 2026."},"depositInsurance":null,"statistics":{"name":"Central Statistical Office of Saint Lucia","url":"https://www.stats.gov.lc/subjects/economy/prices-and-price-indices/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LC', 1, 'bank_deposit_avg_rate', 0.0119, NULL, 'sourced', 'ECCB, Interest Rates and Weighted Average Rates on Deposits and Loans: Saint Lucia', 'https://www.eccb-centralbank.org/statistics-category/mfs-interest-rates/interest-rates-and-weighted-averages-rates-on-deposits-and-loans/q?country_code[]=7', '2026-06-30', 'Weighted average rate on all EC-dollar deposits 1.19% in June 2026 (1.08% including foreign-currency deposits); World Bank deposit rate 1.18% (2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LC', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap on credit card interest was found; the ECCB publishes only an ''other lending rates'' range of 3.50-25.00% for Saint Lucia (August 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LC', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched ECCB sources: the regional Eastern Caribbean deposit insurance arrangement is not shown as operating, and no deposit insurance cover limit for Saint Lucia was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LC', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched the ECCB interest rate tables for Saint Lucia: no monthly recurring deposit product rate is published.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LC', 1, 'equity_return_base', 0.065, NULL, 'assumption', 'ECCB RGSM: Saint Lucia 91-day Treasury bill 2.95% (September 2026)', 'https://www.eccb-centralbank.org/statistics-category/regional-government-securities-market/weighted-average-interest-rates-on-the-rgsm/m?country_code[]=7', '2026-10-31', 'Base case uses a global equity index in EC-dollar terms (pegged to the US dollar): about the 3% tax-free safe rate plus a 3.5-point premium, as the local market is too thin to have a usable 10-year record.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LC', 1, 'equity_return_high', 0.09, NULL, 'assumption', 'ECCB RGSM: Saint Lucia 91-day Treasury bill 2.95% (September 2026)', 'https://www.eccb-centralbank.org/statistics-category/regional-government-securities-market/weighted-average-interest-rates-on-the-rgsm/m?country_code[]=7', '2026-10-31', 'High case if global equities repeat their strong long-run US-dollar returns.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LC', 1, 'equity_return_low', 0.02, NULL, 'assumption', 'ECCB RGSM: Saint Lucia 91-day Treasury bill 2.95% (September 2026)', 'https://www.eccb-centralbank.org/statistics-category/regional-government-securities-market/weighted-average-interest-rates-on-the-rgsm/m?country_code[]=7', '2026-10-31', 'Low case: the regional share market is very small, so savers rely mostly on global equity funds in pegged US-dollar terms, and a weak decade is possible.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LC', 1, 'fdr_1y_rate', 0.0164, NULL, 'sourced', 'ECCB, Interest Rates and Weighted Average Rates on Deposits and Loans: Saint Lucia', 'https://www.eccb-centralbank.org/statistics-category/mfs-interest-rates/interest-rates-and-weighted-averages-rates-on-deposits-and-loans/q?country_code[]=7', '2026-06-30', 'Posted 12-month EC-dollar time-deposit rates ranged 0.10-2.50% (May-August 2026); the weighted average on all EC-dollar time deposits was 1.64% in June 2026, used here as the typical rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LC', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The ECCB interest rate table for Saint Lucia shows no 3-month time-deposit rate (''---'' through August 2026); 6-month deposits were quoted at 1.30-2.50%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LC', 1, 'fixed_income_return_base', 0.025, NULL, 'assumption', 'ECCB Saint Lucia: savings rate 2.07% (June 2026); 91-day Treasury bill 2.95% (September 2026)', 'https://www.eccb-centralbank.org/statistics-category/regional-government-securities-market/weighted-average-interest-rates-on-the-rgsm/m?country_code[]=7', '2026-10-31', 'Base case: a mix of tax-free savings deposits around 2% and Treasury bills near 3%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LC', 1, 'fixed_income_return_high', 0.035, NULL, 'assumption', 'ECCB RGSM Saint Lucia: 91-day bill 2.95%, 180-day bill 3.00-4.00% (2026)', 'https://www.eccb-centralbank.org/statistics-category/regional-government-securities-market/weighted-average-interest-rates-on-the-rgsm/m?country_code[]=7', '2026-10-31', 'High case: rolling 91- and 180-day Treasury bills at 3-4%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LC', 1, 'fixed_income_return_low', 0.015, NULL, 'assumption', 'ECCB Saint Lucia: weighted average time-deposit rate 1.64% and savings rate 2.07% (June 2026)', 'https://www.eccb-centralbank.org/statistics-category/mfs-interest-rates/interest-rates-and-weighted-averages-rates-on-deposits-and-loans/q?country_code[]=7', '2026-10-31', 'Low case: savings and time deposits at about 1.5-2%, tax-free for residents.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LC', 1, 'goal_inflation_education', 0.03, NULL, 'assumption', 'ECCB CPI Saint Lucia: education index 98.30 (2021) to 88.80 (2025)', 'https://www.eccb-centralbank.org/statistics-category/other-real-sector/consumer-price-index-saint-lucia/a', '2026-10-31', 'The CPI education index fell in 2021-2025 (public schooling is largely free), but private and overseas tertiary costs rise faster, so we plan with planning inflation plus half a point.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LC', 1, 'goal_inflation_health', 0.04, NULL, 'assumption', 'ECCB CPI Saint Lucia: health index 110.25 (2021) to 127.26 (2025), about 3.7% a year', 'https://www.eccb-centralbank.org/statistics-category/other-real-sector/consumer-price-index-saint-lucia/a', '2026-10-31', 'Health prices rose about 3.7% a year in 2021-2025, above headline; we plan with 4% to allow for private and overseas treatment costs.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LC', 1, 'gold_return_base', 0.045, NULL, 'assumption', 'ECCB: EC dollar fixed at 2.70 per US dollar; World Bank PA.NUS.FCRF 2.70 (2025)', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=LC', '2026-10-31', 'Long-run dollar gold trend of about 4-5% a year, with no expected depreciation of the pegged EC dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LC', 1, 'gold_return_high', 0.08, NULL, 'assumption', 'ECCB: EC dollar fixed at 2.70 per US dollar; World Bank PA.NUS.FCRF 2.70 (2025)', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=LC', '2026-10-31', 'High case with strong dollar gold prices.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LC', 1, 'gold_return_low', 0.01, NULL, 'assumption', 'ECCB: EC dollar fixed at 2.70 per US dollar; World Bank PA.NUS.FCRF 2.70 (2025)', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=LC', '2026-10-31', 'Low case: weak dollar gold price, and the long-standing peg gives no currency boost.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LC', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No statutory retirement gratuity: Division 11 (Termination Benefits) of the Labour Code 2006 (https://www.govt.lc/media.govt.lc/www/resources/legislation/SaintLuciaLabourCode2006.pdf) provides only redundancy pay on termination due to redundancy (s.160) and leaves severance to Regulations not yet made and to existing collective agreements (s.161); s.159 sets retirement at the NIC pensionable age with no payment on retirement.', 1);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LC', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched Ministry of Health and statistics sources: no published typical cost of a major private hospital stay in Saint Lucia was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LC', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No regulator or other non-company source publishing private health insurance premiums by age was found for Saint Lucia.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LC', 1, 'inflation_cpi', 0.0536, NULL, 'sourced', 'ECCB, Consumer Price Index Saint Lucia (Central Statistical Office data)', 'https://www.eccb-centralbank.org/statistics-category/other-real-sector/consumer-price-index-saint-lucia/m?start_date=31/05/2025&end_date=30/09/2026', '2026-06-30', 'All-items index 125.25 in June 2026 against 118.88 in June 2025 (computed year on year; the table''s monthly ''inflation rate'' column is month on month). The jump is driven by housing and utilities; December-to-December inflation was 0.33% in 2025 and the 2025 average 2.03%. June 2026 is the latest month published.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LC', 1, 'inflation_projection', 0.025, NULL, 'assumption', 'ECCB CPI Saint Lucia: period-average inflation 2021-2025 of 2.4%, 9.7%, 3.8%, -0.7% and 2.0%; EC dollar pegged at 2.70 per US dollar', 'https://www.eccb-centralbank.org/statistics-category/other-real-sector/consumer-price-index-saint-lucia/a', '2026-10-31', 'The ECCB has no inflation target (the EC dollar is pegged to the US dollar), so we plan with 2.5%: close to US-dollar inflation, nudged up for the volatile, import-driven Saint Lucia CPI (5-year average about 3.4% including the 2022 shock).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LC', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life cover is sold in Saint Lucia by regional insurers, but no regulator or other non-company source publishes premium rates by age.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LC', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched the Financial Services Regulatory Authority statistics: it publishes long-term insurance income and expense statements (2011-2022) but no claim settlement ratio.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LC', 1, 'life_expectancy', 72.846, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=LC', '2024-12-31', 'Men 69.5, women 76.5 (2024). UN WPP 2024 via populationpyramid.net gives 73.2 for 2026 (men 69.7, women 76.7). The World Bank figure is for 2024, older than 2025 (latest published).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LC', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":18.8,"men":16.7,"women":20.8},{"age":65,"total":15.2,"men":13.4,"women":16.8},{"age":70,"total":11.8,"men":10.5,"women":13.1},{"age":80,"total":6.6,"men":5.9,"women":7.2}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/saint-lucia/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for the year 2026 (asOf set to mid-year); sex-specific values are for the 5-year age groups starting at each age; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LC', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension exists in Saint Lucia (HelpAge Pension Watch, https://www.helpage.org/country_profile/saint-lucia/).', 1);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LC', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'HelpAge Pension Watch (https://www.helpage.org/country_profile/saint-lucia/) states that Saint Lucia does not currently have a social pension (0% of people 60+ receive one); poor older people can only apply for means-tested public assistance.', 1);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LC', 1, 'oop_health_share', 0.3714, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=LC', '2023-12-31', 'Out-of-pocket spending was 37.1% of current health expenditure in 2023 (latest available; older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LC', 1, 'policy_rate', 0.03, NULL, 'sourced', 'ECCB, Interest Rates on Deposits and Loans: Saint Lucia (discount rate)', 'https://www.eccb-centralbank.org/statistics-category/mfs-interest-rates/interest-rates-on-deposits-and-loans/m?country_code[]=7', '2026-08-31', 'ECCB discount rate 3.00% (May-August 2026), the same for all ECCU members; with the peg it is a backstop rate rather than an active policy tool.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LC', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":16,"entryAgeMax":65,"pensionFromAge":65,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'National Insurance Corporation Saint Lucia, Retirement Benefit and FAQ', 'https://www.stlucianic.org/retirement-benefit', '2026-10-31', 'Compulsory NIC for employed and self-employed people aged 16 to 65 (10% of insurable earnings up to EC$5,000 a month, split equally). Age pension from 65 with 180 months of contributions: 40% of average pensionable earnings in the best 5 years plus 0.1% per month beyond 180; minimum EC$500 a month; fewer contributions give a lump-sum grant. No automatic indexation is stated; tax treatment not confirmed. Pages carry no date.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LC', 1, 'retirement_accumulation_return_base', 0.045, NULL, 'assumption', '91-day Treasury bill 2.95%; global equity assumptions in pegged EC dollars', 'https://www.eccb-centralbank.org/statistics-category/regional-government-securities-market/weighted-average-interest-rates-on-the-rgsm/m?country_code[]=7', '2026-10-31', 'Base case: half global equities at 6.5% and half deposits and bills around 2.5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LC', 1, 'retirement_accumulation_return_high', 0.065, NULL, 'assumption', '91-day Treasury bill 2.95%; global equity assumptions in pegged EC dollars', 'https://www.eccb-centralbank.org/statistics-category/regional-government-securities-market/weighted-average-interest-rates-on-the-rgsm/m?country_code[]=7', '2026-10-31', 'High case with stronger equity returns.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LC', 1, 'retirement_accumulation_return_low', 0.03, NULL, 'assumption', '91-day Treasury bill 2.95%; global equity assumptions in pegged EC dollars', 'https://www.eccb-centralbank.org/statistics-category/regional-government-securities-market/weighted-average-interest-rates-on-the-rgsm/m?country_code[]=7', '2026-10-31', 'Low case for a balanced mix if global equities disappoint.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LC', 1, 'retirement_age_default', 65, NULL, 'sourced', 'National Insurance Corporation Saint Lucia, Retirement Benefit', 'https://www.stlucianic.org/retirement-benefit', '2026-10-31', 'Age pension from 65 with at least 180 months of contributions; the Labour Code 2006 s.159 sets the retirement age of all employees at the NIC pensionable age. Same for men and women. The page carries no date (read October 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LC', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched Government of Saint Lucia sources: the statutory retirement age for public officers under the Pensions Act could not be confirmed from a readable official page.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LC', 1, 'retirement_return_base', 0.025, NULL, 'assumption', 'ECCB Saint Lucia: savings rate 2.07% (June 2026); 91-day Treasury bill 2.95% (September 2026)', 'https://www.eccb-centralbank.org/statistics-category/regional-government-securities-market/weighted-average-interest-rates-on-the-rgsm/m?country_code[]=7', '2026-10-31', 'Base case below the 2.95% tax-free Treasury bill rate: a mix of savings deposits and bills, kept liquid in retirement.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LC', 1, 'retirement_return_high', 0.03, NULL, 'assumption', 'ECCB RGSM: Saint Lucia 91-day Treasury bill 2.95% (September 2026)', 'https://www.eccb-centralbank.org/statistics-category/regional-government-securities-market/weighted-average-interest-rates-on-the-rgsm/m?country_code[]=7', '2026-10-31', 'High case: rolling Treasury bills at about the latest auction rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LC', 1, 'retirement_return_low', 0.015, NULL, 'assumption', 'ECCB Saint Lucia: weighted average time-deposit rate 1.64% (June 2026)', 'https://www.eccb-centralbank.org/statistics-category/mfs-interest-rates/interest-rates-and-weighted-averages-rates-on-deposits-and-loans/q?country_code[]=7', '2026-10-31', 'Low case: mostly tax-free savings and time deposits at about 1.5-2%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LC', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate or retail savings bond for individuals was found; the Government of Saint Lucia borrows through Treasury bills and bonds auctioned on the Regional Government Securities Market.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LC', 1, 'savings_account_rate', 0.0207, NULL, 'sourced', 'ECCB, Interest Rates and Weighted Average Rates on Deposits and Loans: Saint Lucia', 'https://www.eccb-centralbank.org/statistics-category/mfs-interest-rates/interest-rates-and-weighted-averages-rates-on-deposits-and-loans/q?country_code[]=7', '2026-06-30', 'Weighted average rate on EC-dollar savings deposits 2.07% in June 2026; posted savings rates 2.00-3.00%, with the ECCB 2% minimum savings rate as the floor.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LC', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":7.3},{"year":2040,"value":4.2},{"year":2065,"value":2}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/saint-lucia/2040/', '2025-12-31', '100 / old-age dependency ratio: 13.7 (2025, World Bank), 23.8 (2040) and 48.8 (2065, populationpyramid.net/saint-lucia/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LC', 1, 'tax_bank_interest', 0, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Saint Lucia: Individual - Income determination', 'https://taxsummaries.pwc.com/saint-lucia/individual/income-determination', '2026-10-12', 'Interest from banks in Saint Lucia is exempt from income tax (page last reviewed 12 October 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LC', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate for individuals exists in Saint Lucia (see sanchayapatra_5y_rate), so no tax rate applies.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LC', 1, 'tbill_91d_rate', 0.0295, NULL, 'sourced', 'ECCB, Weighted Average Interest Rates on the RGSM: Saint Lucia', 'https://www.eccb-centralbank.org/statistics-category/regional-government-securities-market/weighted-average-interest-rates-on-the-rgsm/m?country_code[]=7', '2026-09-30', '91-day Treasury bill weighted average 2.95% at the September 2026 auction (3.00% in June 2026; 2.71% average in 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LC', 1, 'tbond_10y_rate', 0.0715, NULL, 'sourced', 'ECCB, Weighted Average Interest Rates on the RGSM: Saint Lucia (annual)', 'https://www.eccb-centralbank.org/statistics-category/regional-government-securities-market/weighted-average-interest-rates-on-the-rgsm/a?country_code[]=7', '2024-12-31', 'Weighted average yield on 10-year Government of Saint Lucia bonds issued in 2024 was 7.15% (6.99% in 2023); none was issued in 2025 or May-September 2026, so the figure is older than 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LC', 1, 'tbond_5y_rate', 0.0567, NULL, 'sourced', 'ECCB, Weighted Average Interest Rates on the RGSM: Saint Lucia (annual)', 'https://www.eccb-centralbank.org/statistics-category/regional-government-securities-market/weighted-average-interest-rates-on-the-rgsm/a?country_code[]=7', '2025-12-31', 'Weighted average yield on 5-year Government of Saint Lucia bonds issued in 2025 was 5.67% (5.75% in 2024); no 5-year bond was auctioned in May-September 2026.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('LI', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"LI","iso3":"LIE","nameEn":"Liechtenstein","nameNative":"Liechtenstein","region":"europe_central_asia","languages":["de","gsw","en"],"currency":{"code":"CHF","symbol":"CHF","decimals":2,"compact":"intl","usdRate":{"value":0.8285,"status":"sourced","sourceName":"Swiss National Bank, monthly average foreign exchange rates (devkum), USD 1, October 2026","sourceUrl":"https://data.snb.ch/en/topics/ziredev/cube/devkum","asOf":"2026-10-31","note":"Liechtenstein uses the Swiss franc under its currency treaty with Switzerland. October 2026 monthly average CHF 0.82854 per US dollar (SNB devkum, published 2 Nov 2026); September 2026 average 0.8193; World Bank 2025 average 0.831."}},"instruments":{"savings_account":{"available":true,"localName":"Sparkonto","localNameEn":"Savings account","sourceUrl":"https://data.snb.ch/en/topics/ziredev/cube/zikrepro"},"fdr_3m":{"available":true,"localName":"Festgeld","localNameEn":"Fixed-term deposit (3 months)"},"fdr_1y":{"available":true,"localName":"Festgeld","localNameEn":"Fixed-term deposit (1 year)","sourceUrl":"https://data.snb.ch/en/topics/ziredev/cube/zikrepro"},"dps":{"available":false,"localName":null,"localNameEn":"Recurring deposit","note":"No fixed-rate monthly recurring deposit product found; regular saving goes into savings accounts or fund savings plans."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":"Government savings bond","note":"The State of Liechtenstein sells no savings certificates or retail bonds."},"tbill_91d":{"available":false,"localName":null,"localNameEn":"Treasury bills","note":"No Liechtenstein treasury bills; Swiss Confederation money-market claims are the franc benchmark."},"tbond_5y":{"available":false,"localName":null,"localNameEn":"Government bonds","note":"No Liechtenstein government bonds; residents can buy Swiss Confederation bonds in francs."},"tbond_10y":{"available":false,"localName":null,"localNameEn":"Government bonds","note":"No Liechtenstein government bonds; the 10-year Swiss Confederation bond yielded 0.47% on 30 Oct 2026.","sourceUrl":"https://tradingeconomics.com/switzerland/government-bond-yield"},"equity_fund":{"available":true,"localName":"Anlagefonds","localNameEn":"Investment funds / index funds (ETF)","note":"No local stock exchange; Swiss and international funds are widely available."},"gold":{"available":true,"localName":"Gold (Barren und Münzen)","localNameEn":"Gold bars and coins","note":"No restriction on buying physical gold; held gold counts towards taxable wealth."}},"institutions":{"centralBank":{"name":"Swiss National Bank (Schweizerische Nationalbank)","url":"https://www.snb.ch/en/","note":"Liechtenstein has no central bank of its own and uses the Swiss franc under the 1980 currency treaty with Switzerland."},"insuranceRegulator":{"name":"Finanzmarktaufsicht Liechtenstein (FMA)","url":"https://www.fma-li.li/en/"},"insuranceComplaints":{"name":"Schlichtungsstelle im Finanzdienstleistungsbereich (out-of-court conciliation board, covers insurers since 2024)","url":"https://www.schlichtungsstelle.li/"},"pensionScheme":{"name":"AHV-IV-FAK Liechtenstein (state old-age and survivors'' insurance)","url":"https://www.ahv.li/leistungen/ahv/rentenalter"},"oldAgeAllowance":null,"publicHealthCover":{"name":"Obligatorische Krankenpflegeversicherung (compulsory health insurance), Amt für Gesundheit","url":"https://www.llv.li/en/individuals/health-care-and-care/insurance/health-insurance/mandatory-health-insurance"},"depositInsurance":{"name":"Einlagensicherungs- und Anlegerentschädigungs-Stiftung (EAS)","url":"https://www.eas-liechtenstein.li/"},"statistics":{"name":"Amt für Statistik (Office of Statistics)","url":"https://www.statistikportal.li/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LI', 1, 'bank_deposit_avg_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No weighted average deposit rate for Liechtenstein banks is published (World Bank FR.INR.DPST has no Liechtenstein figure; FMA statistics give volumes, not rates).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LI', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap or official average credit card rate for Liechtenstein was found; the FMA publishes no lending-rate statistics and the SNB figures cover banks in Switzerland only.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LI', 1, 'deposit_insurance_limit', 100000, NULL, 'sourced', 'Einlagensicherungs- und Anlegerentschädigungsverordnung (EAV), LGBl. 2019 Nr. 144, depositor information sheet', 'https://www.gesetze.li/konso/pdf/2019144000', '2026-10-31', 'CHF 100,000 per depositor per bank, paid by the EAS deposit guarantee foundation; consolidated text unchanged since 1 June 2019 (older than 2025 but still in force).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LI', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No monthly recurring deposit product with a published or average rate was found for Liechtenstein; regular saving is done through ordinary savings accounts or fund savings plans.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LI', 1, 'equity_return_base', 0.04, NULL, 'assumption', 'SMI (Trading Economics); 1-year franc deposit 0.15% (SNB, Sep 2026), not income-taxed', 'https://tradingeconomics.com/switzerland/stock-market', '2026-10-31', 'No local market exists, so the base uses a diversified Swiss/global equity fund in francs, capped at the near-zero safe franc rate plus about 4 points.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LI', 1, 'equity_return_high', 0.06, NULL, 'assumption', 'SMI long-run record: price index from 1,500 (1988) to 14,811 (2026), about 6% a year before dividends', 'https://tradingeconomics.com/switzerland/stock-market', '2026-10-31', 'High case: Swiss equities repeat their long-run record of about 6% a year in francs.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LI', 1, 'equity_return_low', 0.02, NULL, 'assumption', 'Swiss Market Index (SMI) 14,811 on 30 Oct 2026, up 21% in a year; Swiss 10-year yield 0.47%', 'https://tradingeconomics.com/switzerland/stock-market', '2026-10-31', 'Liechtenstein has no stock exchange, so returns are based on Swiss and global equity funds in francs; the low case allows for a long flat spell from today''s record highs.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LI', 1, 'fdr_1y_rate', 0.0015, NULL, 'sourced', 'Swiss National Bank, interest rates on new business (zikrepro): term deposits of CHF 100,000 or more, 12 months, mean', 'https://data.snb.ch/en/topics/ziredev/cube/zikrepro', '2026-09-30', 'Mean 0.152% in September 2026 (0.117% in August) at banks in Switzerland (Swiss-franc market; no Liechtenstein-only statistic); 2-year cash bonds (Kassenobligationen) averaged 0.49%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LI', 1, 'fdr_3m_rate', 0.0003, NULL, 'sourced', 'Swiss National Bank, interest rates on new business (zikrepro): term deposits of CHF 100,000 or more, 3 months, mean', 'https://data.snb.ch/en/topics/ziredev/cube/zikrepro', '2026-09-30', 'Mean 0.029% in September 2026 (0.026% in August) at banks in Switzerland (Swiss-franc market; no Liechtenstein-only statistic). Covers deposits from CHF 100,000.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LI', 1, 'fixed_income_return_base', 0.002, NULL, 'assumption', 'SNB: 1-year term deposits 0.15%, 2-year cash bonds 0.49% (Sep 2026); interest not income-taxed under SteG Art. 15', 'https://data.snb.ch/en/topics/ziredev/cube/zikrepro', '2026-10-31', 'Base case: a mix of 1-year franc term deposits and 2-year cash bonds; actual interest is not taxed as income (the 4% deemed-return wealth tax still applies).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LI', 1, 'fixed_income_return_high', 0.005, NULL, 'assumption', 'Swiss 10-year Confederation bond 0.47% (Trading Economics); SNB 2-year cash bonds 0.49%', 'https://tradingeconomics.com/switzerland/government-bond-yield', '2026-10-31', 'High case: locking in longer franc deposits or Confederation bonds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LI', 1, 'fixed_income_return_low', 0, NULL, 'assumption', 'SNB: 3-month term deposits 0.03% (Sep 2026), 3-month Confederation claims -0.11% (Oct 2026)', 'https://data.snb.ch/en/topics/ziredev/cube/zikrepro', '2026-10-31', 'Low case: franc deposit rates stay at about zero (interest is not income-taxed, but the 4% deemed-return wealth tax still applies).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LI', 1, 'goal_inflation_education', 0.02, NULL, 'assumption', 'Swiss CPI +1.0% (Sep 2026); Swiss CPI education +2.6% in July 2026 (Trading Economics)', 'https://tradingeconomics.com/switzerland/inflation-cpi/news/588599', '2026-10-31', 'Education costs are assumed to rise about a point above the 1% planning inflation, in line with recent education price growth.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LI', 1, 'goal_inflation_health', 0.03, NULL, 'assumption', 'Swiss CPI +1.0% (Sep 2026); compulsory health insurance premiums rising faster than prices', 'https://www.admin.ch/de/newnsb/wNfni1DvzKuQ', '2026-10-31', 'Health costs and insurance premiums in Liechtenstein and Switzerland have risen well above general inflation for years, so 3% (two points above the planning inflation) is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LI', 1, 'gold_return_base', 0.03, NULL, 'assumption', 'Gold price history (Trading Economics); SNB inflation forecast under 1%', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Base case: dollar gold rises with world inflation plus a little, partly offset by the franc''s long-run tendency to appreciate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LI', 1, 'gold_return_high', 0.06, NULL, 'assumption', 'Gold price history (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'High case: a repeat of gold''s strong 2005-2025 trend in franc terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LI', 1, 'gold_return_low', 0, NULL, 'assumption', 'Gold price history (Trading Economics); Swiss franc tends to rise against the dollar', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Low case: gold stalls after the 2025-26 spike and a firmer franc erases its dollar gains.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LI', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No statutory days-per-year gratuity was found in a readable official source; occupational pensions (compulsory second pillar, BPVG) provide the employer-funded retirement benefit.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LI', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'Hospital care is covered by the compulsory health insurance (OKP) with a CHF 500 deductible plus 20% co-payment up to an annual cap; the 2026 cap could not be confirmed because the Office of Public Health premium overview could not be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LI', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Compulsory health insurance premiums are flat per adult (not per amount of cover), and no premium table for private cover per CHF 100,000 was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LI', 1, 'inflation_cpi', 0.01, NULL, 'sourced', 'Swiss Federal Statistical Office, Swiss consumer price index (LIK) September 2026, adopted monthly by the Liechtenstein Office of Statistics', 'https://www.admin.ch/de/newnsb/wNfni1DvzKuQ', '2026-09-30', 'Annual CPI inflation +1.0% in September 2026 (0.8% in August). Liechtenstein has no CPI of its own: its Office of Statistics takes over the Swiss national consumer price index each month.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LI', 1, 'inflation_projection', 0.01, NULL, 'assumption', 'SNB price stability range 0-2% and conditional forecast 0.7% (2026), 0.8% (2027-2028); Swiss CPI averaged about 1.4% a year in 2021-2025', 'https://www.snb.ch/en/publications/communication/press-releases-restricted/pre_20260924', '2026-10-31', 'The SNB has kept Swiss-franc inflation inside its 0-2% range almost every year, so 1% is used for long-run planning.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LI', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life cover (Todesfallrisikoversicherung) is available, but no regulator or other non-company published premium table per CHF 1,000 of cover was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LI', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The FMA (insurance supervisor) publishes no industry-wide life claim settlement ratio that could be found; Liechtenstein insurers mainly sell cross-border unit-linked policies.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LI', 1, 'life_expectancy', 84.2, NULL, 'sourced', 'Eurostat demo_mlexpec, life expectancy at birth, Liechtenstein', 'https://ec.europa.eu/eurostat/databrowser/view/demo_mlexpec/default/table?lang=en', '2024-12-31', '2024 figure (latest published; older than 2025): men 82.2, women 86.3; same as World Bank 2024. Small population, so figures move a lot from year to year (83.8 in 2023).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LI', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":25.9,"men":24,"women":27.9},{"age":65,"total":21.5,"men":19.9,"women":23.1},{"age":70,"total":17.3,"men":16.1,"women":18.5},{"age":80,"total":10.4,"men":9.6,"women":11.2}]}', 'sourced', 'Eurostat demo_mlexpec, life expectancy by age and sex, Liechtenstein', 'https://ec.europa.eu/eurostat/databrowser/view/demo_mlexpec/default/table?lang=en', '2024-12-31', '2024 period life table (latest published; older than 2025); small population, so values swing by up to a year between years.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LI', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension found; Ergänzungsleistungen are means-tested (income and assets) supplements for AHV/IV pensioners.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LI', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'No flat non-contributory old-age pension was found: the AHV pension (minimum CHF 1,225, maximum CHF 2,450 a month from 2025) depends on contributions, and supplementary benefits (Ergänzungsleistungen, ahv.li) are means-tested top-ups to AHV/IV pensions rather than a fixed benefit.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LI', 1, 'oop_health_share', 0.1972, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=LI', '2023-12-31', 'Latest available year is 2023 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LI', 1, 'policy_rate', 0, NULL, 'sourced', 'Swiss National Bank, monetary policy assessment of 24 September 2026', 'https://www.snb.ch/en/publications/communication/press-releases-restricted/pre_20260924', '2026-09-24', 'Liechtenstein has no central bank; the Swiss National Bank sets the policy rate for the Swiss franc, unchanged at 0% in September 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LI', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":65,"nomineeUntilAge":null,"inflationLinked":true,"taxFree":false}', 'sourced', 'AHV-IV-FAK Liechtenstein, Teuerungsanpassung (pension adjustment) and Rentenalter', 'https://www.ahv.li/leistungen/ahv/teuerungsanpassung', '2025-01-01', 'Compulsory state old-age insurance (AHV) for everyone working or living in Liechtenstein; pension from 65 (born 1958 or later). Pensions are adjusted to a mixed wage-price index: +2.9% from 1 January 2025 (minimum CHF 1,225, maximum CHF 2,450 a month). AHV pensions are taxable income (SteG Art. 14(2)(e)).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LI', 1, 'retirement_accumulation_return_base', 0.02, NULL, 'assumption', 'Franc deposits about 0.2%; equity base 4%', 'https://data.snb.ch/en/topics/ziredev/cube/zikrepro', '2026-10-31', 'Base case: roughly half equity funds at 4% and half franc deposits or bonds at about 0.2%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LI', 1, 'retirement_accumulation_return_high', 0.032, NULL, 'assumption', 'Swiss 10-year bond 0.47%; equity high 6%', 'https://tradingeconomics.com/switzerland/government-bond-yield', '2026-10-31', 'High case for a growth-leaning balanced mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LI', 1, 'retirement_accumulation_return_low', 0.01, NULL, 'assumption', 'Franc deposits about 0.15%; equity low 2%', 'https://data.snb.ch/en/topics/ziredev/cube/zikrepro', '2026-10-31', 'Low case for a balanced mix if shares lag.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LI', 1, 'retirement_age_default', 65, NULL, 'sourced', 'AHV-IV-FAK Liechtenstein, Rentenalter (ordinary pension age)', 'https://www.ahv.li/leistungen/ahv/rentenalter', '2026-10-31', 'Ordinary AHV pension age is 65 for women and men born in 1958 or later (64 for those born 1946-1957); flexible early or deferred pension is possible with reductions or supplements.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LI', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'State staff are insured with the Stiftung Personalvorsorge Liechtenstein under the State Personnel Act, but no readable official source giving their normal retirement age was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LI', 1, 'retirement_return_base', 0.001, NULL, 'assumption', 'SNB: 1-year term deposits 0.15% (Sep 2026), not income-taxed under SteG Art. 15', 'https://data.snb.ch/en/topics/ziredev/cube/zikrepro', '2026-10-31', 'Base case capped at the 1-year franc term deposit rate, which is not income-taxed (the deemed-return wealth tax still applies).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LI', 1, 'retirement_return_high', 0.004, NULL, 'assumption', 'SNB: 2-year cash bonds (Kassenobligationen) 0.49% (Sep 2026)', 'https://data.snb.ch/en/topics/ziredev/cube/zikrepro', '2026-10-31', 'High case: a ladder of 2-year franc cash bonds and longer deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LI', 1, 'retirement_return_low', 0, NULL, 'assumption', 'SNB: 3-month term deposits 0.03% (Sep 2026)', 'https://data.snb.ch/en/topics/ziredev/cube/zikrepro', '2026-10-31', 'Low case: franc deposit rates stay at zero.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LI', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate or retail savings bond issued by the State of Liechtenstein was found; residents can buy Swiss Confederation bonds in Swiss francs.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LI', 1, 'savings_account_rate', 0.0007, NULL, 'sourced', 'Swiss National Bank, interest rates on new business (zikrepro): savings deposits of private clients, mean', 'https://data.snb.ch/en/topics/ziredev/cube/zikrepro', '2026-09-30', 'Mean savings deposit rate 0.069% in September 2026 (same in August) at banks in Switzerland; no separate statistic exists for Liechtenstein banks, which work in the same Swiss-franc market.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LI', 1, 'support_ratio', NULL, '{"points":[{"year":2026,"value":2.95},{"year":2040,"value":1.99},{"year":2065,"value":1.93}]}', 'sourced', 'UN World Population Prospects (via GeoRank): population shares aged 15-64 and 65+', 'https://georank.org/demographics/liechtenstein/switzerland', '2026-07-01', 'Share aged 15-64 divided by share aged 65+: 64.0/21.7 in 2026, 57.4/28.9 in 2040, 56.8/29.4 in 2065 (UN projections). World Bank 2025 old-age dependency 33.2 gives 3.0.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LI', 1, 'tax_bank_interest', 0, NULL, 'sourced', 'Liechtenstein Tax Act (Steuergesetz, SteG) Art. 15(1)(a) and Art. 56, consolidated version of 1 July 2026', 'https://gesetze.li/konso/pdf/2010340000?version=38', '2026-07-01', 'Actual interest is not taxed as income: income from wealth that bears wealth tax is exempt from the income (Erwerb) tax. Instead 4% of net taxable wealth (the Sollertrag, a deemed return) is added to taxable income each year, so savers pay tax on wealth whatever the interest earned.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LI', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate exists; any bond interest would be exempt from income tax under SteG Art. 15(1)(a), with the bond taxed through the 4% deemed return on wealth.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LI', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The State of Liechtenstein issues no treasury bills. For reference, 3-month Swiss Confederation money-market debt register claims yielded -0.111% in October 2026 (SNB zimoma).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LI', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No Liechtenstein government bonds were found. For reference, the 10-year Swiss Confederation bond yielded 0.47% on 30 October 2026 (Trading Economics).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LI', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No Liechtenstein government bonds were found; Swiss Confederation bonds are the Swiss-franc benchmark.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('LK', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"LK","iso3":"LKA","nameEn":"Sri Lanka","nameNative":"ශ්‍රී ලංකාව","region":"south_asia","languages":["si","ta","en"],"currency":{"code":"LKR","symbol":"Rs","decimals":2,"compact":"intl","usdRate":{"value":332.59,"status":"sourced","sourceName":"CBSL Weekly Economic Indicators, 30 Oct 2026: US dollar average rate (commercial bank buying 328.04, selling 337.14)","sourceUrl":"https://www.cbsl.gov.lk/sites/default/files/cbslweb_documents/statistics/wei/WEI_20261030_e.pdf","asOf":"2026-10-30","note":"Week ago 332.35, year ago 304.45; the rupee depreciated 6.8% against the dollar in 2026 to 30 October. 2025 average 300.85 (World Bank PA.NUS.FCRF)."}},"instruments":{"savings_account":{"available":true,"localName":"ඉතිරි කිරීමේ ගිණුම","localNameEn":"Savings account","sourceUrl":"https://www.cbsl.gov.lk/sites/default/files/cbslweb_documents/statistics/wei/WEI_20261030_e.pdf"},"fdr_3m":{"available":true,"localName":"ස්ථාවර තැන්පතු","localNameEn":"Fixed deposit","sourceUrl":"https://www.cbsl.gov.lk/sites/default/files/cbslweb_documents/statistics/wei/WEI_20261030_e.pdf"},"fdr_1y":{"available":true,"localName":"ස්ථාවර තැන්පතු","localNameEn":"Fixed deposit","sourceUrl":"https://www.cbsl.gov.lk/sites/default/files/cbslweb_documents/statistics/wei/WEI_20261030_e.pdf"},"dps":{"available":false,"localName":null,"localNameEn":"Recurring deposit","note":"No standard recurring-deposit product or rate found."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":"Government savings certificate","note":"No retail government savings certificate; individuals buy Treasury bills and bonds instead."},"tbill_91d":{"available":true,"localName":"භාණ්ඩාගාර බිල්පත්","localNameEn":"Treasury bill","note":"Individuals buy through primary dealers.","sourceUrl":"https://www.cbsl.gov.lk/sites/default/files/cbslweb_documents/statistics/wei/WEI_20261030_e.pdf"},"tbond_5y":{"available":true,"localName":"භාණ්ඩාගාර බැඳුම්කර","localNameEn":"Treasury bond","note":"Individuals buy through primary dealers.","sourceUrl":"https://www.cbsl.gov.lk/sites/default/files/cbslweb_documents/statistics/wei/WEI_20261030_e.pdf"},"tbond_10y":{"available":true,"localName":"භාණ්ඩාගාර බැඳුම්කර","localNameEn":"Treasury bond","note":"Individuals buy through primary dealers.","sourceUrl":"https://www.cbsl.gov.lk/sites/default/files/cbslweb_documents/statistics/wei/WEI_20261030_e.pdf"},"equity_fund":{"available":true,"localName":"ඒකක භාර","localNameEn":"Unit trust","note":"Regulated by the Securities and Exchange Commission of Sri Lanka.","sourceUrl":"https://www.sec.gov.lk/"},"gold":{"available":true,"localName":"රත්‍රන්","localNameEn":"Gold (jewellery, coins and bars)"}},"institutions":{"centralBank":{"name":"Central Bank of Sri Lanka","url":"https://www.cbsl.gov.lk/"},"insuranceRegulator":{"name":"Insurance Regulatory Commission of Sri Lanka","url":"https://ircsl.gov.lk/"},"insuranceComplaints":{"name":"Insurance Ombudsman of Sri Lanka","url":"https://www.insuranceombudsman.lk/","note":"Free; complain to the insurer first."},"pensionScheme":{"name":"Sri Lanka Social Security Board (Surekuma pension scheme)","url":"https://www.ssb.gov.lk/surekuma.html","note":"Formal-sector workers: Employees'' Provident Fund (https://epf.lk/)."},"oldAgeAllowance":{"name":"Welfare Benefits Board (Aswesuma)","url":"https://www.wbb.gov.lk/"},"publicHealthCover":{"name":"Ministry of Health (free public hospital care)","url":"https://www.health.gov.lk/"},"depositInsurance":{"name":"Sri Lanka Deposit Insurance Scheme (CBSL)","url":"https://www.cbsl.gov.lk/sri-lanka-deposit-insurance-scheme"},"statistics":{"name":"Department of Census and Statistics","url":"https://www.statistics.gov.lk/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LK', 1, 'bank_deposit_avg_rate', 0.0762, NULL, 'sourced', 'CBSL Weekly Economic Indicators: Average Weighted Deposit Rate (AWDR)', 'https://www.cbsl.gov.lk/sites/default/files/cbslweb_documents/statistics/wei/WEI_20261030_e.pdf', '2026-09-30', 'AWFDR (fixed deposits) 9.40%; AWNDR (new deposits) 7.79%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LK', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No current CBSL cap or typical card rate found on CBSL pages reachable by direct link. Web search budget ran out during research; only official sites reachable by direct link were checked.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LK', 1, 'deposit_insurance_limit', 1100000, NULL, 'sourced', 'Central Bank of Sri Lanka, Sri Lanka Deposit Insurance Scheme: current coverage', 'https://www.cbsl.gov.lk/sri-lanka-deposit-insurance-scheme', '2026-10-31', 'Rs 1.1 million per depositor per institution; the page gives no effective date.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LK', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No standard monthly recurring-deposit rate is published by CBSL. Web search budget ran out during research; only official sites reachable by direct link were checked.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LK', 1, 'equity_return_base', 0.11, NULL, 'assumption', 'After-tax 364-day T-bill about 9% (9.95% less 10% WHT); ASPI record', 'https://www.cbsl.gov.lk/sites/default/files/cbslweb_documents/statistics/wei/WEI_20261030_e.pdf', '2026-10-31', 'About 2 points above the after-tax safe rate, as the market is small and volatile.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LK', 1, 'equity_return_high', 0.15, NULL, 'assumption', 'ASPI rally 2024-2026; Treasury bond yields about 12-13%', 'https://www.cbsl.gov.lk/sites/default/files/cbslweb_documents/statistics/wei/WEI_20261030_e.pdf', '2026-10-31', 'A strong decade for Colombo shares, still near local bond yields plus a premium.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LK', 1, 'equity_return_low', 0.05, NULL, 'assumption', 'CBSL Weekly Economic Indicators: ASPI 22,840 (Oct 2025) to 20,142 (Oct 2026)', 'https://www.cbsl.gov.lk/sites/default/files/cbslweb_documents/statistics/wei/WEI_20261030_e.pdf', '2026-10-31', 'The index fell 12% in the past year and is volatile, so the low case is below the after-tax deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LK', 1, 'fdr_1y_rate', 0.0725, NULL, 'sourced', 'CBSL Weekly Economic Indicators: state savings bank 1-year fixed deposit rate', 'https://www.cbsl.gov.lk/sites/default/files/cbslweb_documents/statistics/wei/WEI_20261030_e.pdf', '2026-09-30', 'Commercial banks'' 1-year FD range 2.50%-12.50%; average weighted new fixed deposit rate (AWNFDR) 8.52% in September 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LK', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'CBSL weekly indicators publish only 1-year fixed deposit rates and averages; no typical 3-month rate found. Web search budget ran out during research; only official sites reachable by direct link were checked.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LK', 1, 'fixed_income_return_base', 0.075, NULL, 'assumption', 'AWNFDR 8.52% and 364-day T-bill 9.95%, less 10% WHT', 'https://www.cbsl.gov.lk/sites/default/files/cbslweb_documents/statistics/wei/WEI_20261030_e.pdf', '2026-10-31', 'A mix of fixed deposits and Treasury bills after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LK', 1, 'fixed_income_return_high', 0.09, NULL, 'assumption', '364-day T-bill 9.95% and bonds 11-13%, less 10% WHT', 'https://www.cbsl.gov.lk/sites/default/files/cbslweb_documents/statistics/wei/WEI_20261030_e.pdf', '2026-10-31', 'Treasury bills and short bonds after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LK', 1, 'fixed_income_return_low', 0.06, NULL, 'assumption', 'State savings bank 1-year FD 7.25% less 10% WHT', 'https://www.cbsl.gov.lk/sites/default/files/cbslweb_documents/statistics/wei/WEI_20261030_e.pdf', '2026-10-31', 'Ordinary bank deposits after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LK', 1, 'goal_inflation_education', 0.08, NULL, 'assumption', 'DCS CCPI (2021=100); headline 8.3%', 'https://www.statistics.gov.lk/WebReleases/CCPI_20261030E', '2026-10-31', 'No separate education series in the release; private tuition and school fees usually rise faster than headline prices.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LK', 1, 'goal_inflation_health', 0.08, NULL, 'assumption', 'DCS CCPI (2021=100) October 2026 release; headline 8.3%', 'https://www.statistics.gov.lk/WebReleases/CCPI_20261030E', '2026-10-31', 'Health prices rose much faster than average through the 2022 crisis; we plan with 2 points above our 6% general inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LK', 1, 'gold_return_base', 0.09, NULL, 'assumption', 'Dollar gold long-run trend about 4-5% plus rupee depreciation about 4-5% a year', 'https://www.cbsl.gov.lk/sites/default/files/cbslweb_documents/statistics/wei/WEI_20261030_e.pdf', '2026-10-31', 'The rupee has lost value against the dollar most years, which lifts gold in rupees.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LK', 1, 'gold_return_high', 0.14, NULL, 'assumption', 'Rupee depreciation episodes (2022, 2026)', 'https://www.cbsl.gov.lk/sites/default/files/cbslweb_documents/statistics/wei/WEI_20261030_e.pdf', '2026-10-31', 'A currency crisis like 2022 sends rupee gold up sharply.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LK', 1, 'gold_return_low', 0.03, NULL, 'assumption', 'CBSL: rupee depreciation 6.8% year to date (Oct 2026)', 'https://www.cbsl.gov.lk/sites/default/files/cbslweb_documents/statistics/wei/WEI_20261030_e.pdf', '2026-10-31', 'Gold can stall in dollars while the rupee is stable.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LK', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'Sri Lanka has a Payment of Gratuity Act (No. 12 of 1983), but the Department of Labour site was down for maintenance and the rule could not be read. Web search budget ran out during research; only official sites reachable by direct link were checked.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LK', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical private hospital stay cost found. Web search budget ran out during research; only official sites reachable by direct link were checked.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LK', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premium guide found. Web search budget ran out during research; only official sites reachable by direct link were checked.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LK', 1, 'inflation_cpi', 0.083, NULL, 'sourced', 'Department of Census and Statistics, CCPI (2021=100) year-on-year', 'https://www.statistics.gov.lk/WebReleases/CCPI_20261030E', '2026-10-31', 'October 2026 (September 8.0%), confirmed in the CBSL Weekly Economic Indicators of 30 October 2026; core 5.6%. Above the CBSL 5% target.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LK', 1, 'inflation_projection', 0.06, NULL, 'assumption', 'CBSL inflation target 5% (band 3-7%); CCPI 8.3% in Oct 2026', 'https://www.cbsl.gov.lk/sites/default/files/cbslweb_documents/press/pr/press_20260526_Monetary_Policy_Review_No_3_2026_e_Hi7x2.pdf', '2026-10-31', 'The CBSL targets 5% but inflation swung from 70% (2022) to deflation (2025) and is now 8.3%, so we plan with 6%, a point above the target.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LK', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life is sold, but no published premium guide or regulator data was found. Web search budget ran out during research; only official sites reachable by direct link were checked.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LK', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'IRCSL publishes market statistics but no industry claim settlement ratio was found on reachable pages. Web search budget ran out during research; only official sites reachable by direct link were checked.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LK', 1, 'life_expectancy', 77.672, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN (UN WPP)', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=LK', '2024-12-31', 'Men 74.4, women 80.7. Latest published figure is for 2024 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LK', 1, 'life_table_remaining', NULL, NULL, 'missing', '', '', '2026-10-31', 'DCS life tables (2011-2013) pages returned no data and the WHO GHO API was down (HTTP 500). Web search budget ran out during research; only official sites reachable by direct link were checked.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LK', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'Welfare Benefits Board pages give no eligibility ages for the elderly allowance. Web search budget ran out during research; only official sites reachable by direct link were checked.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LK', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'The elderly allowance is paid through the Aswesuma programme (Welfare Benefits Board), but the reachable WBB pages give no current amount. Web search budget ran out during research; only official sites reachable by direct link were checked.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LK', 1, 'oop_health_share', 0.5481, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS (WHO GHED)', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=LK', '2023-12-31', 'Latest published figure is for 2023 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LK', 1, 'policy_rate', 0.0875, NULL, 'sourced', 'Central Bank of Sri Lanka, Overnight Policy Rate (Monetary Policy Review No. 3 of 2026)', 'https://www.cbsl.gov.lk/sites/default/files/cbslweb_documents/press/pr/press_20260526_Monetary_Policy_Review_No_3_2026_e_Hi7x2.pdf', '2026-05-26', 'Raised 100 bp to 8.75% on 25 May 2026 and held on 30 September 2026 (CBSL Weekly Economic Indicators, 30 Oct 2026). SDFR 8.25%, SLFR 9.25%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LK', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":18,"entryAgeMax":59,"pensionFromAge":60,"nomineeUntilAge":80,"inflationLinked":false,"taxFree":null}', 'sourced', 'Sri Lanka Social Security Board, Surekuma pension scheme', 'https://www.ssb.gov.lk/surekuma.html', '2026-10-31', 'Voluntary contributory pension for people aged 18-59 without a government pension; full pension monthly from 60 for life if contributions are complete; if the member dies, the spouse or nominee gets the pension until the member would have been 80. No indexation, contribution amounts, tax treatment or pension examples are stated. Formal-sector workers get a lump sum from EPF instead.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LK', 1, 'retirement_accumulation_return_base', 0.09, NULL, 'assumption', 'Mix of equity base 11% and fixed income base 7.5%', 'https://www.cbsl.gov.lk/sites/default/files/cbslweb_documents/statistics/wei/WEI_20261030_e.pdf', '2026-10-31', 'Roughly half equity and half safe fixed income over a working life.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LK', 1, 'retirement_accumulation_return_high', 0.11, NULL, 'assumption', 'Equity high 15%, fixed income high 9%', 'https://www.cbsl.gov.lk/sites/default/files/cbslweb_documents/statistics/wei/WEI_20261030_e.pdf', '2026-10-31', 'A growth-tilted mix in a good decade.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LK', 1, 'retirement_accumulation_return_low', 0.065, NULL, 'assumption', 'After-tax deposit rates; volatile ASPI', 'https://www.cbsl.gov.lk/sites/default/files/cbslweb_documents/statistics/wei/WEI_20261030_e.pdf', '2026-10-31', 'A balanced mix that earns little more than deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LK', 1, 'retirement_age_default', 55, NULL, 'sourced', 'Central Bank of Sri Lanka, Employees'' Provident Fund: retirement benefit age', 'https://www.cbsl.gov.lk/en/employees-provident-fund', '2026-10-31', 'EPF benefits can be claimed at 55 (men) and 50 (women); EPF pays a lump sum, not a pension. Private employers'' retirement age is commonly 60.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LK', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'Department of Pensions site refused connections; no official statement of the public-service retirement age read. Web search budget ran out during research; only official sites reachable by direct link were checked.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LK', 1, 'retirement_return_base', 0.075, NULL, 'assumption', '364-day T-bill 9.95% and AWNFDR 8.52%, less 10% WHT', 'https://www.cbsl.gov.lk/sites/default/files/cbslweb_documents/statistics/wei/WEI_20261030_e.pdf', '2026-10-31', 'Below the after-tax 1-year bill rate of about 9%, allowing for rates falling back.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LK', 1, 'retirement_return_high', 0.085, NULL, 'assumption', '364-day T-bill 9.95% less 10% WHT', 'https://www.cbsl.gov.lk/sites/default/files/cbslweb_documents/statistics/wei/WEI_20261030_e.pdf', '2026-10-31', 'Roughly the current after-tax 1-year Treasury bill rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LK', 1, 'retirement_return_low', 0.06, NULL, 'assumption', 'State savings bank 1-year FD 7.25% less 10% WHT', 'https://www.cbsl.gov.lk/sites/default/files/cbslweb_documents/statistics/wei/WEI_20261030_e.pdf', '2026-10-31', 'Plain deposits after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LK', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate or retail savings bond for individuals found; individuals buy Treasury bills and bonds through primary dealers. Web search budget ran out during research; only official sites reachable by direct link were checked.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LK', 1, 'savings_account_rate', 0.03, NULL, 'sourced', 'CBSL Weekly Economic Indicators: state savings bank savings deposit rate', 'https://www.cbsl.gov.lk/sites/default/files/cbslweb_documents/statistics/wei/WEI_20261030_e.pdf', '2026-09-30', 'Commercial bank savings rates range 0.10%-9.00% (September 2026); the state savings bank''s 3.00% is a typical ordinary rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LK', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":5.3},{"year":2040,"value":3.8},{"year":2065,"value":2.5}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025: 19.0) and UN WPP 2024 medium variant via PopulationPyramid.net (2040: 26.2, 2065: 40.0)', 'https://www.populationpyramid.net/sri-lanka/2040/', '2025-12-31', 'Working-age people per person 65+ = 100 / old-age dependency ratio.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LK', 1, 'tax_bank_interest', 0.1, NULL, 'sourced', 'Inland Revenue Department tax chart 2025/26: WHT/AIT on interest to resident individuals', 'https://www.ird.gov.lk/en/publications/SitePages/tax_chart_2526.aspx?menuid=140408', '2025-04-01', '10% withheld from 1 April 2025; interest is part of taxable income (6%-36% slabs) and the WHT is creditable. The IRD site returned HTTP 503 when this was re-checked on 3 Nov 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LK', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate exists for this slot. Web search budget ran out during research; only official sites reachable by direct link were checked.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LK', 1, 'tbill_91d_rate', 0.0934, NULL, 'sourced', 'CBSL Weekly Economic Indicators (PDMO): 91-day Treasury bill primary market yield', 'https://www.cbsl.gov.lk/sites/default/files/cbslweb_documents/statistics/wei/WEI_20261030_e.pdf', '2026-10-28', '182-day 9.44%, 364-day 9.95%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LK', 1, 'tbond_10y_rate', 0.1285, NULL, 'sourced', 'CBSL Weekly Economic Indicators (PDMO): Treasury bond auction weighted average yield, 15-Aug-2036 (9 years 9 months)', 'https://www.cbsl.gov.lk/sites/default/files/cbslweb_documents/statistics/wei/WEI_20261030_e.pdf', '2026-10-29', 'Secondary market 8-10 year average 12.31%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LK', 1, 'tbond_5y_rate', 0.1182, NULL, 'sourced', 'CBSL Weekly Economic Indicators (PDMO): Treasury bond secondary market average yield, 5-6 years', 'https://www.cbsl.gov.lk/sites/default/files/cbslweb_documents/statistics/wei/WEI_20261030_e.pdf', '2026-10-29', 'Under-5-year bucket 11.61%.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('LR', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"LR","iso3":"LBR","nameEn":"Liberia","nameNative":"Liberia","region":"sub_saharan_africa","languages":["en","kpe","vai"],"currency":{"code":"LRD","symbol":"L$","decimals":2,"compact":"intl","usdRate":{"value":170.47,"status":"sourced","sourceName":"Central Bank of Liberia, daily buying and selling rates, 31 October 2026","sourceUrl":"https://www.cbl.org.lr/research/buying-selling-rates","asOf":"2026-10-31","note":"Mid-point of the CBL buying (169.4404) and selling (171.4896) rates for 31 October 2026; World Bank 2024 average 191.3. CLDR gives ''$''; ''L$'' is used to tell it apart from the US dollar, which also circulates widely."}},"instruments":{"savings_account":{"available":true,"localName":null,"localNameEn":"Savings account","note":"Offered in Liberian and US dollars; no official average rate published recently."},"fdr_3m":{"available":true,"localName":null,"localNameEn":"Time deposit","note":"Banks take time deposits; no official rate by maturity was found."},"fdr_1y":{"available":true,"localName":null,"localNameEn":"Time deposit, 1 year","note":"No official rate by maturity was found."},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No standard monthly recurring deposit product with published rates was found."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate or retail savings bond with a published rate was found."},"tbill_91d":{"available":true,"localName":null,"localNameEn":"Treasury bills","note":"Government of Liberia Treasury bill auctions are open only to commercial banks, which may hold bills for clients (2010 CBL guidelines, minimum non-competitive bid L$50,000); recent auctions are mainly central bank bills.","sourceUrl":"https://www.cbl.org.lr/sites/default/files/documents/guidelinesGoLTBill.pdf"},"tbond_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No domestic 5-year government bond open to individuals was found."},"tbond_10y":{"available":false,"localName":null,"localNameEn":null,"note":"No domestic 10-year government bond was found."},"equity_fund":{"available":false,"localName":null,"localNameEn":null,"note":"Liberia has no stock exchange and no locally regulated retail investment funds were found."},"gold":{"available":false,"localName":null,"localNameEn":null,"note":"No retail market for investment gold bars or coins was found."}},"institutions":{"centralBank":{"name":"Central Bank of Liberia","url":"https://www.cbl.org.lr/"},"insuranceRegulator":{"name":"Central Bank of Liberia (insurance supervision under the Insurance Act 2013)","url":"https://www.cbl.org.lr/publications/document-type/insurance"},"insuranceComplaints":{"name":"Central Bank of Liberia, insurance supervision","url":"https://www.cbl.org.lr/","note":"No separate insurance ombudsman was found; complaints go to the Central Bank as insurance supervisor."},"pensionScheme":{"name":"National Social Security and Welfare Corporation (NASSCORP)","url":"https://www.nasscorp.org.lr/"},"oldAgeAllowance":null,"publicHealthCover":{"name":"Ministry of Health (free primary care at public facilities)","url":"https://moh.gov.lr/","note":"No national health insurance scheme in operation was found."},"depositInsurance":null,"statistics":{"name":"Liberia Institute of Statistics and Geo-Information Services (LISGIS)","url":"https://lisgis.gov.lr/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LR', 1, 'bank_deposit_avg_rate', 0.038, NULL, 'sourced', 'World Bank WDI, deposit interest rate (FR.INR.DPST)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=LR', '2025-12-31', '3.80% for 2025: average paid by commercial banks on demand, time and savings deposits; most deposits in Liberia are in US dollars.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LR', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap or official average credit card rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LR', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No operating deposit insurance scheme was found; the Central Bank of Liberia has spoken of plans for a Deposit Insurance Scheme, but no law or cover limit was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LR', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No industry-wide rate for a monthly recurring deposit product was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LR', 1, 'equity_return_base', 0.07, NULL, 'assumption', 'World Bank WDI deposit rate 3.80% (2025), 3.2% after 15% tax; no stock exchange in Liberia', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=LR', '2026-10-31', 'Base case: a global equity index in Liberian-dollar terms, held to the after-tax average deposit rate (3.2%) plus 4 points because there is no local index record and individuals cannot buy central bank bills.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LR', 1, 'equity_return_high', 0.12, NULL, 'assumption', 'World Bank WDI, official exchange rate LRD per USD (191 in 2024, 170 in October 2026)', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=LR', '2026-10-31', 'High case: strong global equity returns plus a renewed depreciation episode like 2018-2020.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LR', 1, 'equity_return_low', 0.03, NULL, 'assumption', 'World Bank WDI deposit rate 3.80% (2025); no stock exchange in Liberia', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=LR', '2026-10-31', 'Low case: Liberia has no stock exchange, so equity means a global index fund in Liberian-dollar terms; a weak decade abroad with a stable currency gives about the after-tax deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LR', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No official 1-year time deposit rate was found in Central Bank of Liberia publications.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LR', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No official 3-month time deposit rate was found in Central Bank of Liberia publications.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LR', 1, 'fixed_income_return_base', 0.035, NULL, 'assumption', 'World Bank WDI deposit rate 3.80% (2025), 3.2% after 15% withholding', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=LR', '2026-10-31', 'Base case: about the average deposit rate after tax (3.2%), slightly higher for Liberian-dollar time deposits; individuals cannot buy central bank bills directly.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LR', 1, 'fixed_income_return_high', 0.06, NULL, 'assumption', 'Central Bank of Liberia bills report, 3-month bill 15.12% (24 September 2026)', 'https://cbl.org.lr/sites/default/files/documents/CBL%20Bills%20Issuance%20Report%20for%20the%20Week%20Ending%2025%20September%202026.pdf', '2026-10-31', 'High case: Liberian-dollar time deposits priced partly off the 15-16% money market rates, after 15% tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LR', 1, 'fixed_income_return_low', 0.025, NULL, 'assumption', 'World Bank WDI deposit rate 3.80% (2025), 3.2% after 15% withholding', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=LR', '2026-10-31', 'Low case: average deposits after 15% tax, allowing for lower rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LR', 1, 'goal_inflation_education', 0.075, NULL, 'assumption', 'World Bank CPI inflation for Liberia; CBL MPC Communique No. 28', 'https://data.worldbank.org/indicator/FP.CPI.TOTL.ZG?locations=LR', '2026-10-31', 'No education CPI series could be read, so school fees are planned at one point above the 6.5% general assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LR', 1, 'goal_inflation_health', 0.075, NULL, 'assumption', 'World Bank CPI inflation for Liberia; CBL MPC Communique No. 28', 'https://data.worldbank.org/indicator/FP.CPI.TOTL.ZG?locations=LR', '2026-10-31', 'No health CPI series could be read, so medical costs are planned at one point above the 6.5% general assumption, as drugs and supplies are imported.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LR', 1, 'gold_return_base', 0.06, NULL, 'assumption', 'World Bank WDI, official exchange rate LRD per USD', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=LR', '2026-10-31', 'Base case: dollar gold trend of about 4% a year plus Liberian-dollar depreciation of about 2% a year.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LR', 1, 'gold_return_high', 0.12, NULL, 'assumption', 'World Bank WDI, official exchange rate LRD per USD', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=LR', '2026-10-31', 'High case: strong dollar gold and a depreciation episode like 2018-2020, when the Liberian dollar lost about a quarter of its value.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LR', 1, 'gold_return_low', 0.02, NULL, 'assumption', 'Central Bank of Liberia buying and selling rates (L$169-171 per US$, October 2026)', 'https://www.cbl.org.lr/research/buying-selling-rates', '2026-10-31', 'Low case: flat dollar gold with a stable Liberian dollar, as in 2025-2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LR', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Decent Work Act 2015 (s.14.5, s.18.4) gives severance of 4 weeks'' pay per completed year of service when employment ends for economic reasons (redundancy, closure), per WageIndicator; no general end-of-service or retirement gratuity was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LR', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No official typical cost of a major private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LR', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premiums per 100,000 Liberian dollars of cover from the regulator or another public source were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LR', 1, 'inflation_cpi', 0.045, NULL, 'sourced', 'Central Bank of Liberia, Monetary Policy Committee Communique No. 28, 6 October 2026', 'https://cbl.org.lr/sites/default/files/documents/COMMUNIQUE%20NO.28_20261007_0001.pdf', '2026-09-30', 'Headline inflation moderated to an estimated 4.5% in the third quarter of 2026 from 5.4% in the second quarter; the CBL expects about 4.6% in the fourth quarter. Trading Economics shows the LISGIS figure at 5.0% for June 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LR', 1, 'inflation_projection', 0.065, NULL, 'assumption', 'World Bank CPI inflation for Liberia (8.3% in 2025); CBL MPC Communique No. 28 (4.5% in Q3 2026)', 'https://data.worldbank.org/indicator/FP.CPI.TOTL.ZG?locations=LR', '2026-10-31', 'Inflation has fallen to about 4.5% with a stronger Liberian dollar, but averaged 7-10% over 2021-2025, so 6.5% is used for long plans.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LR', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published indicative term-life premium rates per 1,000 Liberian dollars of cover from the regulator or another public source were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LR', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Central Bank of Liberia supervises insurers but no industry-wide life claim settlement ratio was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LR', 1, 'life_expectancy', 62.3, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN)', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=LR', '2024-12-31', '62.3 years in 2024 (men 61.0, women 63.6); UN WPP 2024 gives 62.6 for 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LR', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":15.6,"men":15.2,"women":16},{"age":65,"total":12.4,"men":12.2,"women":12.7},{"age":70,"total":9.6,"men":9.5,"women":9.7},{"age":80,"total":5.4,"men":5.4,"women":5.4}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/liberia/', '2026-07-01', 'Secondary source of UN WPP 2024 (medium variant) for 2026; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LR', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension was found (see old_age_allowance_monthly).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LR', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension with a fixed monthly amount was found; the social cash transfer programme targets poor households, not older people as such, and the social protection ministry pages could not be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LR', 1, 'oop_health_share', 0.6324, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=LR', '2023-12-31', '63.2% in 2023 (latest year; older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LR', 1, 'policy_rate', 0.16, NULL, 'sourced', 'Central Bank of Liberia, Monetary Policy Committee Communique No. 28, 6 October 2026', 'https://cbl.org.lr/sites/default/files/documents/COMMUNIQUE%20NO.28_20261007_0001.pdf', '2026-10-06', 'Monetary Policy Rate kept at 16.0% (cut from 16.25% in July 2026); the reserve requirement on US dollar deposits was raised from 10% to 12%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LR', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":60,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'NASSCORP General Regulations 2023 (Schedule I, contribution rates); WageIndicator summary of the Social Security Law 2017', 'https://liblaw.org/wp-content/uploads/2025/06/NASSCORP-General-Regulations-2023.pdf', '2023-12-31', 'National Pension Fund run by NASSCORP: employer and employee each pay 4% of earnings (since 13 February 2017); pension at 60 with 144 months of contributions, 25% of average monthly earnings plus 1% per extra 10 months up to 40% (WageIndicator, updated March 2026). No automatic indexation or tax rule was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LR', 1, 'retirement_accumulation_return_base', 0.05, NULL, 'assumption', 'World Bank WDI deposit rate; CBL bills report (September 2026)', 'https://cbl.org.lr/sites/default/files/documents/CBL%20Bills%20Issuance%20Report%20for%20the%20Week%20Ending%2025%20September%202026.pdf', '2026-10-31', 'Base case: a mix of time deposits and foreign equity funds, between the safe and equity base cases.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LR', 1, 'retirement_accumulation_return_high', 0.08, NULL, 'assumption', 'Central Bank of Liberia bills report (3-month 15.12%); World Bank exchange rate history', 'https://cbl.org.lr/sites/default/files/documents/CBL%20Bills%20Issuance%20Report%20for%20the%20Week%20Ending%2025%20September%202026.pdf', '2026-10-31', 'High case: higher-yield Liberian-dollar deposits and more foreign equity.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LR', 1, 'retirement_accumulation_return_low', 0.03, NULL, 'assumption', 'World Bank WDI deposit rate 3.80% (2025)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=LR', '2026-10-31', 'Low case: mostly deposits with little growth exposure.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LR', 1, 'retirement_age_default', 60, NULL, 'sourced', 'WageIndicator Foundation summary of the NASSCORP Social Security Law 2017 (s.89) and Decent Work Act 2015', 'https://wageindicator.org/en-lr/work-in-liberia/labour-law/social-security', '2026-03-19', 'Old-age pension at 60 for men and women with at least 144 months of contributions; a lump sum at 60 with 12 or more months; retirement deemed at 65. Page updated 19 March 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LR', 1, 'retirement_age_government', 65, NULL, 'sourced', 'Ministry of Foreign Affairs of Liberia news item citing Civil Service Agency standing orders and the Government Employees Pension Act', 'https://mofa.gov.lr/index.php/node/5093', '2017-01-31', 'Civil servants retire at 65 or after 25 years of service (Civil Service Agency standing orders); the item is from 2017 (older than 2025) and no later change was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LR', 1, 'retirement_return_base', 0.03, NULL, 'assumption', 'World Bank WDI deposit rate 3.80% (2025), 3.2% after 15% withholding', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=LR', '2026-10-31', 'Base case: savings and time deposits at about the 3.2% after-tax average deposit rate; individuals cannot buy central bank bills directly.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LR', 1, 'retirement_return_high', 0.05, NULL, 'assumption', 'Central Bank of Liberia bills report, 3-month bill 15.12% (24 September 2026)', 'https://cbl.org.lr/sites/default/files/documents/CBL%20Bills%20Issuance%20Report%20for%20the%20Week%20Ending%2025%20September%202026.pdf', '2026-10-31', 'High case: more Liberian-dollar time deposits at rates linked to the 15-16% money market.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LR', 1, 'retirement_return_low', 0.025, NULL, 'assumption', 'World Bank WDI deposit rate 3.80% (2025), 3.2% after 15% withholding', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=LR', '2026-10-31', 'Low case: average deposits after tax, allowing for lower rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LR', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate or retail savings bond with a published rate was found; a central bank savings programme for citizens has been reported but its details could not be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LR', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No official current savings account rate was found; the Central Bank of Liberia publishes no recent table of commercial bank deposit rates that could be read (World Bank average deposit rate 3.80% for 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LR', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":17.3},{"year":2040,"value":15.6},{"year":2065,"value":10.2}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/liberia/2040/', '2025-12-31', '100 / old-age dependency ratio: 5.79 (2025, World Bank), 6.4 (2040) and 9.8 (2065, populationpyramid.net/liberia/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LR', 1, 'tax_bank_interest', 0.15, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Liberia, individual income determination and withholding taxes', 'https://taxsummaries.pwc.com/republic-of-liberia/individual/income-determination', '2026-09-24', 'Non-exempt interest is taxed at 15% and interest paid to residents is subject to 15% withholding (PwC corporate withholding page); interest under LRD 200 a year is excluded. Page last reviewed 24 September 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LR', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate exists; interest is generally taxed at 15% (PwC Tax Summaries).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LR', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No recent Government of Liberia 91-day Treasury bill result was found. For reference, the 3-month Central Bank of Liberia bill (a central bank instrument bid by banks, not a Treasury bill and not open to individuals) cleared at 15.12% on 24 September 2026 (CBL bills issuance report).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LR', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No Government of Liberia 10-year bond yield was found; Liberia has no domestic long-term government bond market with published yields.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LR', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No Government of Liberia 5-year bond yield was found in Central Bank of Liberia publications.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('LS', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"LS","iso3":"LSO","nameEn":"Lesotho","nameNative":"Lesotho","region":"sub_saharan_africa","languages":["st","en","zu"],"currency":{"code":"LSL","symbol":"M","decimals":2,"compact":"intl","usdRate":{"value":17.889,"status":"sourced","sourceName":"World Bank WDI, official exchange rate (PA.NUS.FCRF), Lesotho","sourceUrl":"https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=LS","asOf":"2025-12-31","note":"2025 average. The loti is pegged one to one to the South African rand, which is also legal tender; the rate was about 16.6 per dollar in late October 2026 (Trading Economics). CLDR lists the rand for this territory; the loti (plural maloti, symbol M) is the national currency."}},"instruments":{"savings_account":{"available":true,"localName":null,"localNameEn":"Savings account","note":"Savings deposit rate 1.55% (CBL, December 2024).","sourceUrl":"https://centralbank.org.ls/financial-stability-indicators/"},"fdr_3m":{"available":true,"localName":null,"localNameEn":"Fixed (time) deposit","note":"Banks take time deposits; the CBL publishes only the 12-month rate.","sourceUrl":"https://centralbank.org.ls/financial-stability-indicators/"},"fdr_1y":{"available":true,"localName":null,"localNameEn":"Fixed (time) deposit, 12 months","note":"12-month time deposit rate 4.72% (CBL, December 2024); 4.96% in July 2026 via Trading Economics.","sourceUrl":"https://centralbank.org.ls/financial-stability-indicators/"},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No standard monthly recurring deposit product with published rates was found."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate or retail savings bond; individuals can buy Treasury bills and bonds at CBL auctions."},"tbill_91d":{"available":true,"localName":null,"localNameEn":"Treasury bills","note":"91, 182, 273 and 364-day bills auctioned twice a month; individuals can bid with an ID and a local bank account, minimum M20,000.","sourceUrl":"https://centralbank.org.ls/wp-content/uploads/Investment-Opprtunities-Brochure_2025.pdf"},"tbond_5y":{"available":true,"localName":null,"localNameEn":"Treasury bonds","note":"Fixed-rate bonds auctioned about every three months, minimum M50,000; no new 5-year issue in 2026 up to October.","sourceUrl":"https://centralbank.org.ls/tbonds-results/"},"tbond_10y":{"available":true,"localName":null,"localNameEn":"Treasury bonds","note":"Bonds of up to about 20 years; recent issues mature in 2033 and 2041.","sourceUrl":"https://centralbank.org.ls/tbonds-results/"},"equity_fund":{"available":true,"localName":null,"localNameEn":"Collective investment scheme (unit trust)","note":"Licensed under the Central Bank of Lesotho (Collective Investment Schemes) Regulations 2018; few local schemes, most marketed schemes are registered abroad.","sourceUrl":"https://centralbank.org.ls/legislations/"},"gold":{"available":false,"localName":null,"localNameEn":null,"note":"No local retail market for investment gold bars or coins was found."}},"institutions":{"centralBank":{"name":"Central Bank of Lesotho","url":"https://centralbank.org.ls/"},"insuranceRegulator":{"name":"Central Bank of Lesotho (insurance supervision under the Insurance Act 2014)","url":"https://centralbank.org.ls/legislations/"},"insuranceComplaints":{"name":"Central Bank of Lesotho, insurance supervision","url":"https://centralbank.org.ls/","note":"No separate insurance ombudsman was found; complaints go to the Central Bank as insurance supervisor."},"pensionScheme":null,"oldAgeAllowance":{"name":"Old Age Pension, Ministry of Finance and Development Planning","url":"https://finance.gov.ls/","note":"Universal pension for citizens aged 70 and above. Government of Lesotho (.gov.ls) sites did not resolve when checked on 3 November 2026."},"publicHealthCover":{"name":"Ministry of Health (subsidised public and church-run health facilities)","url":"https://www.gov.ls/health/","note":"No national health insurance scheme was found; link is the Government of Lesotho portal page for health."},"depositInsurance":null,"statistics":{"name":"Bureau of Statistics Lesotho","url":"https://www.bos.gov.ls/","note":"The site did not resolve when checked on 31 October 2026."}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LS', 1, 'bank_deposit_avg_rate', 0.0246, NULL, 'sourced', 'World Bank WDI, deposit interest rate (FR.INR.DPST)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=LS', '2024-12-31', '2.46% for 2024 (older than 2025); a blend of savings, call and term deposit rates, so lower than the 12-month rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LS', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap on credit card rates was found; the CBL homepage shows a prime lending rate of 10.5% (24 September 2026), but no credit card rate statistic was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LS', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No deposit insurance scheme or limit was found in Central Bank of Lesotho legislation or its 2024 Financial Stability Report; a scheme has been discussed since the 2000s.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LS', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No industry-wide rate for a monthly recurring deposit product was found in Central Bank of Lesotho statistics.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LS', 1, 'equity_return_base', 0.09, NULL, 'assumption', 'CBL Treasury bill auction no. 642 (364-day yield 7.15%, 6.4% after 10% withholding)', 'https://centralbank.org.ls/wp-content/uploads/Treasury-Bills-Results-642_-21-October-2026.pdf', '2026-10-31', 'Base case: a global index in loti (rand) terms, held below the after-tax bill rate plus 4 points (10.4%) because there is no local equity record to rely on.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LS', 1, 'equity_return_high', 0.12, NULL, 'assumption', 'CBL Treasury bill auction no. 642; World Bank official exchange rate history', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=LS', '2026-10-31', 'High case: strong global equity returns plus rand weakness lifting returns in loti terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LS', 1, 'equity_return_low', 0.05, NULL, 'assumption', 'CBL Treasury bill auction no. 642 (364-day cut-off yield 7.15%, 21 October 2026)', 'https://centralbank.org.ls/wp-content/uploads/Treasury-Bills-Results-642_-21-October-2026.pdf', '2026-10-31', 'Low case: Lesotho has no meaningful local stock market, so equity means global or South African funds in loti terms; a weak decade for these markets gives about the safe rate less a point.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LS', 1, 'fdr_1y_rate', 0.0496, NULL, 'sourced', 'Central Bank of Lesotho deposit interest rate (12-month time deposits), July 2026, via Trading Economics', 'https://tradingeconomics.com/lesotho/deposit-interest-rate', '2026-07-31', 'Secondary source of a Central Bank of Lesotho series: 4.96% in July 2026 (the CBL indicators page shows the 12-month time deposit rate at 4.72% in December 2024, and the World Bank blended deposit rate is far lower at 2.46%, so this series matches the 12-month rate).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LS', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Central Bank of Lesotho indicators page shows savings, call and 12-month time deposit rates only; no official 3-month deposit rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LS', 1, 'fixed_income_return_base', 0.05, NULL, 'assumption', 'CBL 12-month deposit rate 4.96% (July 2026) and 364-day bill 7.15% (October 2026), after 10% withholding', 'https://centralbank.org.ls/wp-content/uploads/Treasury-Bills-Results-642_-21-October-2026.pdf', '2026-10-31', 'Base case: between term deposits (4.5% after tax) and one-year Treasury bills (6.4% after tax).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LS', 1, 'fixed_income_return_high', 0.07, NULL, 'assumption', 'CBL Treasury bond auction no. 64 (2033 bond, 9.75%, June 2026)', 'https://centralbank.org.ls/wp-content/uploads/Treasury-Bonds-Auction-Results_64_17062026.pdf', '2026-10-31', 'High case: medium-term government bonds at about 9.75% less 10% withholding, allowing for lower future yields.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LS', 1, 'fixed_income_return_low', 0.035, NULL, 'assumption', 'CBL 12-month time deposit rate 4.96% (July 2026), after 10% withholding', 'https://tradingeconomics.com/lesotho/deposit-interest-rate', '2026-10-31', 'Low case: a mix of savings and term deposits after tax, allowing for rate cuts.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LS', 1, 'goal_inflation_education', 0.055, NULL, 'assumption', 'Central Bank of Lesotho MPC statement, 24 September 2026 (CPI 2.6%, 4.7% projected for 2027)', 'https://centralbank.org.ls/wp-content/uploads/MPC_Statement_24_September_2026-Final.pdf', '2026-10-31', 'No education CPI series could be read, so school fees are planned at one point above the 4.5% general assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LS', 1, 'goal_inflation_health', 0.055, NULL, 'assumption', 'Central Bank of Lesotho MPC statement, 24 September 2026 (CPI 2.6%, 4.7% projected for 2027)', 'https://centralbank.org.ls/wp-content/uploads/MPC_Statement_24_September_2026-Final.pdf', '2026-10-31', 'No health CPI series could be read, so medical costs are planned at one point above the 4.5% general assumption, as much private care is bought in South Africa.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LS', 1, 'gold_return_base', 0.06, NULL, 'assumption', 'World Bank WDI, official exchange rate LSL per USD; SARB 3% inflation target', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=LS', '2026-10-31', 'Base case: dollar gold trend of about 4% a year plus loti depreciation of about 2% a year, in line with the inflation gap to the US.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LS', 1, 'gold_return_high', 0.11, NULL, 'assumption', 'World Bank WDI, official exchange rate LSL per USD', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=LS', '2026-10-31', 'High case: strong dollar gold and a rand depreciation episode like 2015-2016 or 2020.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LS', 1, 'gold_return_low', 0.02, NULL, 'assumption', 'World Bank WDI, official exchange rate LSL per USD (17.89 in 2025)', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=LS', '2026-10-31', 'Low case: flat dollar gold with a stable rand-loti.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LS', 1, 'gratuity_rule', NULL, '{"daysPerYear":14,"daysPerYearAfter":null,"afterYears":null,"daysPerMonth":30}', 'sourced', 'WageIndicator Foundation summary of the Labour Act 2024 (Act No. 3 of 2024), sections 136-137', 'https://wageindicator.org/en-ls/ai/work-in-lesotho/labour-law/contracts-and-dismissals/notice-and-severance/', '2026-03-18', 'Severance pay of two weeks'' wages for each completed year of service, for employees with more than one year of continuous service with the same employer, except when dismissed for misconduct (Labour Act 2024 ss.136-137, WageIndicator updated 18 March 2026); modelled as 14 days of a 30-day month.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LS', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No official typical cost of a major private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LS', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premiums per 100,000 maloti of cover from the regulator or another public source were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LS', 1, 'inflation_cpi', 0.026, NULL, 'sourced', 'Central Bank of Lesotho, Statement of the Monetary Policy Committee, 24 September 2026', 'https://centralbank.org.ls/wp-content/uploads/MPC_Statement_24_September_2026-Final.pdf', '2026-08-31', 'Annual consumer inflation 2.6% in August 2026, down from 2.9% in July (Bureau of Statistics CPI as reported by the central bank).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LS', 1, 'inflation_projection', 0.045, NULL, 'assumption', 'Central Bank of Lesotho MPC statement (inflation projected at 4.7% in 2027); South African Reserve Bank 3% target (loti pegged to the rand)', 'https://centralbank.org.ls/wp-content/uploads/MPC_Statement_24_September_2026-Final.pdf', '2026-10-31', 'Lesotho imports South African inflation through the one-to-one rand peg; between the 3% SARB target, the CBL 4.7% projection for 2027 and the World Bank 2025 figure of 4.3%, 4.5% is used for long plans.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LS', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published indicative term-life premium rates per 1,000 maloti of cover from the regulator or another public source were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LS', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Central Bank of Lesotho (insurance supervisor) publishes claims ratios (claims to premiums), not a share of claims paid; no settlement rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LS', 1, 'life_expectancy', 57.8, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN)', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=LS', '2024-12-31', '57.8 years in 2024 (men 55.0, women 60.4); UN WPP 2024 gives 58.6 for 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LS', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":15.3,"men":13.8,"women":16.8},{"age":65,"total":13,"men":11.5,"women":14},{"age":70,"total":10.5,"men":9.4,"women":11.6},{"age":80,"total":6.4,"men":5.7,"women":7}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/lesotho/', '2026-07-01', 'Secondary source of UN WPP 2024 (medium variant) for 2026; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LS', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":70,"womenAge":70,"over90Monthly":null,"meansTested":false}', 'sourced', 'WageIndicator Foundation summary of the Old Age Pensions Act 2005 and Old Age Monthly Pension Notice 2023', 'https://wageindicator.org/en-ls/work-in-lesotho/labour-law/social-security', '2026-03-18', 'Government-funded universal pension for citizens aged 70 and above, with no means test mentioned (WageIndicator, updated 18 March 2026; legal basis Old Age Pensions Act 2005 and 2023 notice, older than 2025). Older sources say retired public officers on a public service pension are excluded; not confirmed on this page.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LS', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'Not confirmed: WageIndicator (updated 18 March 2026, https://wageindicator.org/en-ls/work-in-lesotho/labour-law/social-security) still shows M900 a month from the 2023 notice, while a government news-agency report of an increase to M1,000 for 2026/27 could not be opened (Lesotho government sites did not resolve), so the amount payable today could not be verified.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LS', 1, 'oop_health_share', 0.132, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=LS', '2023-12-31', '13.2% in 2023 (latest year; older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LS', 1, 'policy_rate', 0.07, NULL, 'sourced', 'Central Bank of Lesotho, Statement of the Monetary Policy Committee, 24 September 2026', 'https://centralbank.org.ls/wp-content/uploads/MPC_Statement_24_September_2026-Final.pdf', '2026-09-24', 'The CBL Rate was raised by 25 basis points to 7.00%, 25 points below the South African Reserve Bank rate of 7.25%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LS', 1, 'public_pension_scheme', NULL, NULL, 'missing', '', '', '2026-10-31', 'No national contributory pension for private-sector workers was found: the National Social Security Bill was described as in its final stages in the 2025/26 budget, but its enactment could not be confirmed. Public officers have their own pension fund and everyone aged 70+ gets the universal old age pension.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LS', 1, 'retirement_accumulation_return_base', 0.075, NULL, 'assumption', 'CBL Treasury bond auction no. 64 (9.75%) and Treasury bill auction no. 642 (7.15%)', 'https://centralbank.org.ls/wp-content/uploads/Treasury-Bonds-Auction-Results_64_17062026.pdf', '2026-10-31', 'Base case: a balanced mix of government bonds and global or South African equity funds, between the safe and equity base cases.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LS', 1, 'retirement_accumulation_return_high', 0.1, NULL, 'assumption', 'CBL Treasury bond auction no. 65 (2041 bond, 10.75%, September 2026)', 'https://centralbank.org.ls/wp-content/uploads/Treasury-Bonds-Auction-Results_65_16092026.pdf', '2026-10-31', 'High case: more long bonds and equity funds, with yields staying near current levels.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LS', 1, 'retirement_accumulation_return_low', 0.05, NULL, 'assumption', 'CBL Treasury bill auction no. 642 (364-day 7.15%)', 'https://centralbank.org.ls/wp-content/uploads/Treasury-Bills-Results-642_-21-October-2026.pdf', '2026-10-31', 'Low case: mostly deposits and bills with a small, weak equity share.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LS', 1, 'retirement_age_default', 60, NULL, 'sourced', 'WageIndicator Foundation summary of the Labour Act 2024 (Act No. 3 of 2024)', 'https://wageindicator.org/en-ls/ai/work-in-lesotho/labour-law/contracts-and-dismissals/notice-and-severance/', '2026-03-18', 'There is no national contributory pension and no statutory pension age for private workers; the Labour Act 2024 lets employers set a retirement age of at least 60 (WageIndicator, updated 18 March 2026). The universal old age pension starts at 70.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LS', 1, 'retirement_age_government', 60, NULL, 'sourced', 'Lesotho Times report citing section 26(1) of the Public Service Act No. 1 of 2005', 'https://lestimes.com/?p=16860', '2014-06-27', 'Secondary source from 2014 (older than 2025): the Public Service Act 2005 fixes the retirement age of public officers at 60; no later change was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LS', 1, 'retirement_return_base', 0.05, NULL, 'assumption', 'CBL 364-day Treasury bill cut-off yield 7.15% (21 October 2026), 6.4% after withholding; 12-month deposit 4.5% after tax', 'https://centralbank.org.ls/wp-content/uploads/Treasury-Bills-Results-642_-21-October-2026.pdf', '2026-10-31', 'Base case: a mix of term deposits and Treasury bills, below the 6.4% after-tax one-year bill rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LS', 1, 'retirement_return_high', 0.065, NULL, 'assumption', 'CBL Treasury bond auction no. 64 (2033 bond, 9.75%, June 2026)', 'https://centralbank.org.ls/wp-content/uploads/Treasury-Bonds-Auction-Results_64_17062026.pdf', '2026-10-31', 'High case: part of the money in government bonds at about 8.8% after withholding.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LS', 1, 'retirement_return_low', 0.04, NULL, 'assumption', 'CBL 12-month time deposit rate 4.96% (July 2026), 4.5% after 10% withholding', 'https://tradingeconomics.com/lesotho/deposit-interest-rate', '2026-10-31', 'Low case: term deposits after tax, allowing for rate cuts.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LS', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate or retail savings bond was found; individuals can buy ordinary Treasury bills (minimum M20,000) and bonds (minimum M50,000) at Central Bank of Lesotho auctions.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LS', 1, 'savings_account_rate', 0.0155, NULL, 'sourced', 'Central Bank of Lesotho, Monetary and Financial Stability Indicators: savings deposit rate', 'https://centralbank.org.ls/financial-stability-indicators/', '2024-12-31', '1.55% in December 2024, the latest month the page shows (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LS', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":16},{"year":2040,"value":16.9},{"year":2065,"value":7}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/lesotho/2040/', '2025-12-31', '100 / old-age dependency ratio: 6.26 (2025, World Bank), 5.9 (2040) and 14.3 (2065, populationpyramid.net/lesotho/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LS', 1, 'tax_bank_interest', 0.1, NULL, 'sourced', 'ACCA Foundations in Taxation, Lesotho tax tables (Income Tax Act 1993): withholding on interest paid by a resident to a resident', 'https://www.accaglobal.com/content/dam/acca/global/PDF-students/fia/ftx/examdocs/FTX-LSO%20tax%20tables%202023.pdf', '2023-04-01', '10% withholding on interest paid to residents (tables for 2023 exams, older than 2025); the CBL 2025 investment brochure confirms 10% for residents on government securities. The Income Tax Act exempts the first M500 of interest from one nominated savings account.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LS', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate exists. For reference, the Central Bank of Lesotho 2025 investment brochure states 10% withholding for residents on Treasury bill and bond interest.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LS', 1, 'tbill_91d_rate', 0.071, NULL, 'sourced', 'Central Bank of Lesotho, Treasury bill auction no. 642, 21 October 2026', 'https://centralbank.org.ls/wp-content/uploads/Treasury-Bills-Results-642_-21-October-2026.pdf', '2026-10-21', 'Cut-off yield 7.10% on the 91-day bill (average discount rate 6.98%); 364-day cut-off yield 7.15%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LS', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No bond near 10 years was auctioned in 2025-2026: the June 2026 auction of a 2033 bond (7 years) cleared at 9.75% and the September 2026 reopening of a 2041 bond (about 15 years) at 10.75% (CBL auction results).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LS', 1, 'tbond_5y_rate', 0.0839, NULL, 'sourced', 'Central Bank of Lesotho, Treasury bond auction no. 62 (LSO GB 9.25 2030 reopening), 17 December 2025', 'https://centralbank.org.ls/wp-content/uploads/Treasury-Bonds-Auction-Results_62_17122025.pdf', '2025-12-17', 'Cut-off yield 8.39% on a bond maturing June 2030 (about 4.5 years); no 5-year bond was auctioned in 2026 up to October.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('LT', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"LT","iso3":"LTU","nameEn":"Lithuania","nameNative":"Lietuva","region":"europe_central_asia","languages":["lt","ru","en","pl"],"currency":{"code":"EUR","symbol":"€","decimals":2,"compact":"intl","usdRate":{"value":0.8951,"status":"sourced","sourceName":"European Central Bank euro reference rate (USD)","sourceUrl":"https://www.ecb.europa.eu/stats/policy_and_exchange_rates/euro_reference_exchange_rates/html/eurofxref-graph-usd.en.html","asOf":"2026-10-30","note":"EUR 1 = USD 1.1172 on 30 October 2026 (ECB EXR dataset), so about EUR 0.895 per US dollar; World Bank 2025 average 0.885."}},"instruments":{"savings_account":{"available":true,"localName":"Taupomoji sąskaita","localNameEn":"Savings account","sourceUrl":"https://data-api.ecb.europa.eu/service/data/MIR/M.LT.B.L21.A.R.A.2250.EUR.N"},"fdr_3m":{"available":true,"localName":"Terminuotasis indėlis","localNameEn":"Term deposit (3 months)"},"fdr_1y":{"available":true,"localName":"Terminuotasis indėlis","localNameEn":"Term deposit (1 year)","sourceUrl":"https://data-api.ecb.europa.eu/service/data/MIR/M.LT.B.L22.F.R.A.2250.EUR.N"},"dps":{"available":true,"localName":"Kaupiamasis indėlis","localNameEn":"Regular savings deposit","note":"Monthly top-up savings deposits are offered by banks; no average rate is published."},"sanchayapatra_5y":{"available":true,"localName":"Vyriausybės taupymo lakštai (gynybos obligacijos)","localNameEn":"Government savings notes (defence bonds)","note":"Sold to individuals in two-week issues with terms of up to 3 years (no 5-year term); the current rate could not be read from the Ministry of Finance site.","sourceUrl":"https://finmin.lrv.lt/lt/veiklos-sritys/valstybes-skolos-valdymas/vyriausybes-vertybiniai-popieriai/gynybos-obligacijos/"},"tbill_91d":{"available":false,"localName":"Vyriausybės iždo vekseliai","localNameEn":"Treasury bills","note":"No regular 3-month bill for retail investors was found."},"tbond_5y":{"available":true,"localName":"Vyriausybės obligacijos","localNameEn":"Government bonds","note":"Domestic government bonds trade on the Vilnius exchange; no 5-year yield found."},"tbond_10y":{"available":true,"localName":"Vyriausybės obligacijos","localNameEn":"Government bonds","sourceUrl":"https://tradingeconomics.com/lithuania/government-bond-yield"},"equity_fund":{"available":true,"localName":"Investiciniai fondai","localNameEn":"Investment funds / index funds (ETF)","note":"Retail funds widely available; an investment account (investicinė sąskaita) defers tax on gains."},"gold":{"available":true,"localName":"Investicinis auksas","localNameEn":"Investment gold (bars and coins)","note":"No restriction on buying physical gold; investment gold is VAT-exempt under EU rules."}},"institutions":{"centralBank":{"name":"Lietuvos bankas (Bank of Lithuania)","url":"https://www.lb.lt/en/","note":"Part of the Eurosystem; monetary policy set by the European Central Bank."},"insuranceRegulator":{"name":"Lietuvos bankas (Bank of Lithuania), financial market supervision","url":"https://www.lb.lt/en/"},"insuranceComplaints":{"name":"Bank of Lithuania, disputes between consumers and financial market participants","url":"https://www.lb.lt/en/disputes-between-consumers-and-financial-market-participants"},"pensionScheme":{"name":"Sodra (State Social Insurance Fund Board), old-age pension","url":"https://www.sodra.lt/en"},"oldAgeAllowance":{"name":"Šalpos senatvės pensija (social assistance old-age pension), paid through Sodra","url":"https://www.sodra.lt/en"},"publicHealthCover":{"name":"Valstybinė ligonių kasa (National Health Insurance Fund), compulsory health insurance","url":"https://ligoniukasa.lrv.lt/en/"},"depositInsurance":{"name":"Indėlių ir investicijų draudimas (Deposit and Investment Insurance)","url":"https://www.iidraudimas.lt/en/deposit-insurance/"},"statistics":{"name":"Valstybės duomenų agentūra (State Data Agency)","url":"https://osp.stat.gov.lt/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LT', 1, 'bank_deposit_avg_rate', 0.0218, NULL, 'sourced', 'ECB MFI interest rate statistics: Lithuanian banks, household deposits with agreed maturity (outstanding amounts)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.LT.B.L22.A.R.A.2250.EUR.O', '2026-09-30', 'Average rate on all outstanding household term deposits, September 2026 (2.12% in August); household overnight deposits paid 0.26%. World Bank FR.INR.DPST has no Lithuania figure.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LT', 1, 'credit_card_rate_cap', 0.1025, NULL, 'sourced', 'ECB MFI interest rate statistics: Lithuanian banks, revolving loans, overdrafts and credit card credit to households', 'https://data-api.ecb.europa.eu/service/data/MIR/M.LT.B.A2Z.A.R.A.2250.EUR.N', '2026-09-30', 'Typical rate, not a cap: average rate on household revolving loans, overdrafts and credit card credit, September 2026 (9.91% in August).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LT', 1, 'deposit_insurance_limit', 100000, NULL, 'sourced', 'Indėlių ir investicijų draudimas (Deposit and Investment Insurance), deposit insurance', 'https://www.iidraudimas.lt/en/deposit-insurance/', '2026-10-31', 'EUR 100,000 per depositor per credit institution, all eligible deposits at one bank added together.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LT', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Lithuanian banks offer regular savings deposits (kaupiamasis indėlis), but no average or official rate for them was found in Bank of Lithuania or ECB statistics.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LT', 1, 'equity_return_base', 0.058, NULL, 'assumption', 'OMX Vilnius (Trading Economics); 1-year deposit 2.34% less 20% tax = 1.87% (ECB MFI, Sep 2026)', 'https://tradingeconomics.com/lithuania/stock-market', '2026-10-31', 'OMX Vilnius has compounded about 10% a year since 2000, but the market is small and illiquid, so the base uses a diversified euro equity fund and is held at the after-tax 1-year deposit rate plus about 4 points.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LT', 1, 'equity_return_high', 0.08, NULL, 'assumption', 'OMX Vilnius long-run record; long-run global equity returns', 'https://tradingeconomics.com/lithuania/stock-market', '2026-10-31', 'High case: a diversified euro equity fund matching long-run global equity returns of about 8% in euros.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LT', 1, 'equity_return_low', 0.035, NULL, 'assumption', 'OMX Vilnius gross index 1,490 on 30 Oct 2026 (base 100 at end-1999), up 18.6% in a year', 'https://tradingeconomics.com/lithuania/stock-market', '2026-10-31', 'Low case: the small, concentrated Vilnius market returns only a little more than safe savings over a long period.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LT', 1, 'fdr_1y_rate', 0.0234, NULL, 'sourced', 'ECB MFI interest rate statistics: Lithuanian banks, household deposits with agreed maturity up to 1 year (new business)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.LT.B.L22.F.R.A.2250.EUR.N', '2026-09-30', 'Bucket covers all fixed terms up to one year (2.43% in August, 2.07% in July); deposits of over 1 and up to 2 years paid 3.60% in September 2026 (ECB MIR M.LT.B.L22.G).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LT', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'ECB/Bank of Lithuania MFI statistics publish household deposits with agreed maturity up to 1 year as one bucket (2.34% in September 2026); no separate 3-month term deposit rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LT', 1, 'fixed_income_return_base', 0.021, NULL, 'assumption', '1-year deposit 2.34% and 1-2 year deposit 3.60% less 20% tax = 1.9-2.9% (ECB MFI, Sep 2026)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.LT.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Base case: a mix of term deposits up to 2 years after the 20% tax (the EUR 500 interest exemption makes small balances effectively tax-free).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LT', 1, 'fixed_income_return_high', 0.027, NULL, 'assumption', 'Household deposits over 1 and up to 2 years 3.60% less 20% tax = 2.9% (ECB MFI, Sep 2026)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.LT.B.L22.G.R.A.2250.EUR.N', '2026-10-31', 'High case: locking in 1-2 year deposits or Government savings notes after tax, allowing for some fall in rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LT', 1, 'fixed_income_return_low', 0.013, NULL, 'assumption', 'Household deposits up to 1 year 2.34% (ECB MFI statistics, Sep 2026), assuming rates fall, less 20% tax', 'https://data-api.ecb.europa.eu/service/data/MIR/M.LT.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Low case: term deposit and savings-note rates drift down towards 1.6% before the 20% tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LT', 1, 'goal_inflation_education', 0.045, NULL, 'assumption', 'Lithuania CPI, education: +3.8% year on year in September 2026 (5.2% in August) (Trading Economics, from State Data Agency)', 'https://tradingeconomics.com/lithuania/inflation-cpi/news/590410', '2026-10-31', 'Education costs are assumed to rise about 1.5 points above the 3% planning inflation, in line with recent education price growth.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LT', 1, 'goal_inflation_health', 0.05, NULL, 'assumption', 'Lithuania CPI, health: +5.7% year on year in September 2026 (Trading Economics, from State Data Agency); HICP health +3.8% in Dec 2025 (ECB)', 'https://tradingeconomics.com/lithuania/inflation-cpi/news/590410', '2026-10-31', 'Health prices have been rising about as fast as or faster than headline prices, so 5% (two points above the 3% planning inflation) is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LT', 1, 'gold_return_base', 0.04, NULL, 'assumption', 'Gold price history (Trading Economics); ECB 2% inflation target', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Base case: dollar gold rises roughly with world inflation plus a little, and the euro is assumed stable against the dollar over the long run.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LT', 1, 'gold_return_high', 0.07, NULL, 'assumption', 'Gold price history (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'High case: a repeat of gold''s strong 2005-2025 trend in euro terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LT', 1, 'gold_return_low', 0.01, NULL, 'assumption', 'Gold price history (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Low case: gold barely keeps up after the 2025-26 spike, with no help from the euro.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LT', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No per-year gratuity: under the Labour Code an employer pays severance of about two months'' average wage on dismissal without the employee''s fault (one year of service or more), with extra long-service benefits from the Long-term Employment Benefit Fund, which does not fit a days-per-year rule; the Labour Code text could not be read on e-seimas.lrs.lt.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LT', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'Hospital care for people covered by compulsory health insurance (PSD) is paid by the National Health Insurance Fund; no official figure for the out-of-pocket cost of a major private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LT', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Private health insurance is mostly employer-paid group cover; no published premium table per EUR 100,000 of cover was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LT', 1, 'inflation_cpi', 0.067, NULL, 'sourced', 'LRT, reporting the State Data Agency (Valstybės duomenų agentūra) September 2026 CPI release', 'https://www.lrt.lt/naujienos/verslas/4/3077070/rugseji-suderinta-6-1-proc-metine-ir-4-5-proc-vidutine-metine-infliacija', '2026-09-30', 'National CPI up 6.7% year on year in September 2026 (HICP 6.1%; 12-month average CPI 4.9%). Secondary source: the official statistics portal could not be read; Trading Economics reports the same 6.7%. World Bank 2025 average 3.8%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LT', 1, 'inflation_projection', 0.03, NULL, 'assumption', 'ECB 2% medium-term target; Lithuanian CPI averaged about 7% a year in 2021-2025 (18.9% in 2022) and 6.7% in Sep 2026', 'https://data.worldbank.org/indicator/FP.CPI.TOTL.ZG?locations=LT', '2026-10-31', 'Lithuania shares the ECB 2% target but its prices and wages keep converging towards richer euro members and inflation is running well above target in 2026, so 3% is used for long-run planning.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LT', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life cover (rizikos gyvybės draudimas) is sold, but no regulator or other non-company published premium table per EUR 1,000 of cover was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LT', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Bank of Lithuania (insurance supervisor) publishes market statistics but no industry-wide life claim settlement ratio could be found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LT', 1, 'life_expectancy', 77.5, NULL, 'sourced', 'Eurostat demo_mlexpec, life expectancy at birth, Lithuania', 'https://ec.europa.eu/eurostat/databrowser/view/demo_mlexpec/default/table?lang=en', '2024-12-31', '2024 figure (latest published; older than 2025): men 73.0, women 81.6. World Bank 2024 figure 77.2.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LT', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":21.9,"men":18.6,"women":24.5},{"age":65,"total":18.3,"men":15.4,"women":20.3},{"age":70,"total":14.9,"men":12.5,"women":16.4},{"age":80,"total":8.8,"men":7.6,"women":9.3}]}', 'sourced', 'Eurostat demo_mlexpec, life expectancy by age and sex, Lithuania', 'https://ec.europa.eu/eurostat/databrowser/view/demo_mlexpec/default/table?lang=en', '2024-12-31', '2024 period life table (latest published; older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LT', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":65,"womenAge":65,"over90Monthly":null,"meansTested":false}', 'sourced', 'TV3, pension guide (Sodra rules), updated 17 September 2026', 'https://www.tv3.lt/pensija', '2026-09-17', 'Paid from the old-age pension age (65 for men and women in 2026) to people without the minimum 15-year insurance record; it is not income-tested, but it is only paid when no equal or larger state social insurance pension is due (Law on Social Assistance Pensions, art. 7).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LT', 1, 'old_age_allowance_monthly', 261, NULL, 'sourced', 'TV3, pension guide: šalpos senatvės pensija (social assistance old-age pension) 2026', 'https://www.tv3.lt/pensija', '2026-09-17', 'Secondary source (Sodra and ministry pages could not be read): EUR 261 a month in 2026, paid from the state budget to people of pension age who lack the 15-year minimum record and get no equal or larger social insurance pension.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LT', 1, 'oop_health_share', 0.3143, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=LT', '2024-12-31', NULL, 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LT', 1, 'policy_rate', 0.025, NULL, 'sourced', 'European Central Bank, key ECB interest rates (deposit facility)', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.en.html', '2026-09-16', 'Lithuania uses the euro; ECB deposit facility rate 2.50% since 16 September 2026 (2.25% from June 2026), confirmed in the ECB FM dataset on 31 October 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LT', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":65,"nomineeUntilAge":null,"inflationLinked":true,"taxFree":null}', 'sourced', 'TV3, pension guide (Sodra rules), updated 17 September 2026', 'https://www.tv3.lt/pensija', '2026-09-17', 'Sodra state social insurance old-age pension (general part plus individual part from points), payable from 65 with a 15-year minimum record; early pension up to 5 years sooner, cut 0.32% a month. Pensions are indexed each year in line with the growth of the wage bill rather than CPI. Tax treatment could not be confirmed from a readable official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LT', 1, 'retirement_accumulation_return_base', 0.04, NULL, 'assumption', 'After-tax safe rate about 2.1%; equity base 5.8%', 'https://data-api.ecb.europa.eu/service/data/MIR/M.LT.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Base case: roughly half shares at 5.8% and half safe fixed income at about 2.1% after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LT', 1, 'retirement_accumulation_return_high', 0.055, NULL, 'assumption', 'After-tax 1-2 year deposit 2.9%; equity high 8%', 'https://data-api.ecb.europa.eu/service/data/MIR/M.LT.B.L22.G.R.A.2250.EUR.N', '2026-10-31', 'High case for a growth-leaning balanced mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LT', 1, 'retirement_accumulation_return_low', 0.025, NULL, 'assumption', 'After-tax 1-year deposit 1.87%; equity low 3.5%', 'https://data-api.ecb.europa.eu/service/data/MIR/M.LT.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Low case for a balanced mix if shares lag.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LT', 1, 'retirement_age_default', 65, NULL, 'sourced', 'TV3, pension guide (Sodra rules), updated 17 September 2026', 'https://www.tv3.lt/pensija', '2026-09-17', 'Secondary source (Sodra pages could not be read): from 2026 men and women both reach old-age pension age at 65, the end of the phased rise; no further rise is legislated, so 65 applies to people born after 1975. A 15-year minimum record is needed and the full required record is 34.5 years in 2026 (35 from 2027).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LT', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'Civil servants draw the general Sodra pension; the Civil Service Law sets an upper age limit for career civil servants (about 65), but the current consolidated text could not be read on e-seimas.lrs.lt.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LT', 1, 'retirement_return_base', 0.018, NULL, 'assumption', 'Household deposits up to 1 year 2.34% less 20% tax = 1.87% (ECB MFI, Sep 2026)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.LT.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Base case capped at the after-tax 1-year term deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LT', 1, 'retirement_return_high', 0.026, NULL, 'assumption', 'Household deposits over 1 and up to 2 years 3.60% less 20% tax = 2.9% (ECB MFI, Sep 2026)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.LT.B.L22.G.R.A.2250.EUR.N', '2026-10-31', 'High case: a ladder of 1-2 year deposits or Government savings notes after tax, allowing for some fall in rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LT', 1, 'retirement_return_low', 0.013, NULL, 'assumption', 'Household deposits up to 1 year 2.34% (ECB MFI, Sep 2026), assuming rates fall, less 20% tax', 'https://data-api.ecb.europa.eu/service/data/MIR/M.LT.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Low case: term deposit and savings-note rates drift lower.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LT', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Lithuania sells Government savings notes / defence bonds to individuals (terms up to 3 years, no 5-year note), but the current rate could not be confirmed: the Ministry of Finance pages return 403 to automated reading and the researcher''s 3.4% (3-year, 27 Oct-9 Nov 2026 issue) came only from a search-result snippet.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LT', 1, 'savings_account_rate', 0.0026, NULL, 'sourced', 'ECB MFI interest rate statistics: Lithuanian banks, overnight deposits from households (new business)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.LT.B.L21.A.R.A.2250.EUR.N', '2026-09-30', 'Average rate on household overnight deposits in Lithuania, September 2026 (0.25% in August and July).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LT', 1, 'support_ratio', NULL, '{"points":[{"year":2026,"value":2.99},{"year":2040,"value":2.16},{"year":2065,"value":1.47}]}', 'sourced', 'Eurostat EUROPOP2023 population projections, proj_23ndbi old-age dependency ratio (65+ to 15-64), baseline', 'https://ec.europa.eu/eurostat/databrowser/view/proj_23ndbi/default/table?lang=en', '2026-01-01', '100 divided by the projected old-age dependency ratio: 33.4 in 2026, 46.3 in 2040, 67.8 in 2065. World Bank 2025 ratio 32.0 gives 3.1.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LT', 1, 'tax_bank_interest', 0.2, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Lithuania significant developments and taxes on personal income', 'https://taxsummaries.pwc.com/lithuania/individual/significant-developments', '2026-10-01', 'From 1 January 2026 almost all individual income is taxed at progressive 20%/25%/32% rates; the reduced 15% list (dividends, some pension and share income) does not include interest, so the 20% first band is used. The first EUR 500 of interest a year on deposits and securities is exempt (PwC income determination page). Some secondary sources still quote 15% for interest, so check before relying on it.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LT', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No readable official source on how interest on Government savings notes (defence bonds) is taxed was found; it is believed to follow the general interest rules (EUR 500 annual exemption), but the State Tax Inspectorate pages could not be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LT', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 3-month Lithuanian treasury bill yield was found; the Ministry of Finance''s securities pages could not be read and the ECB publishes no Lithuanian money-market yield.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LT', 1, 'tbond_10y_rate', 0.0443, NULL, 'sourced', 'Trading Economics, Lithuania 10-year government bond yield', 'https://tradingeconomics.com/lithuania/government-bond-yield', '2026-10-30', 'Secondary source. The ECB long-term convergence rate for Lithuania shows 2.88% for July-September 2026 but has been flat for months, so the market yield is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LT', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No current 5-year government bond yield from an official or allowed secondary source was found; a 5-year Eurobond tranche was issued in January 2026 but the Ministry of Finance release with its yield could not be read.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('LU', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"LU","iso3":"LUX","nameEn":"Luxembourg","nameNative":"Lëtzebuerg","region":"europe_central_asia","languages":["lb","fr","de","en","pt"],"currency":{"code":"EUR","symbol":"€","decimals":2,"compact":"intl","usdRate":{"value":0.8951,"status":"sourced","sourceName":"European Central Bank euro reference rate (USD)","sourceUrl":"https://www.ecb.europa.eu/stats/policy_and_exchange_rates/euro_reference_exchange_rates/html/eurofxref-graph-usd.en.html","asOf":"2026-10-30","note":"EUR 1 = USD 1.1172 on 30 October 2026 (ECB EXR dataset), so about EUR 0.895 per US dollar; World Bank 2025 average 0.885."}},"instruments":{"savings_account":{"available":true,"localName":"Compte d''épargne","localNameEn":"Savings account","sourceUrl":"https://data-api.ecb.europa.eu/service/data/MIR/M.LU.B.L21.A.R.A.2250.EUR.N"},"fdr_3m":{"available":true,"localName":"Dépôt à terme","localNameEn":"Term deposit (3 months)"},"fdr_1y":{"available":true,"localName":"Dépôt à terme","localNameEn":"Term deposit (1 year)","sourceUrl":"https://data-api.ecb.europa.eu/service/data/MIR/M.LU.B.L22.F.R.A.2250.EUR.N"},"dps":{"available":true,"localName":"Plan d''épargne","localNameEn":"Monthly savings plan","note":"Banks offer regular monthly savings plans; no average rate is published."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":"Government savings bond","note":"No retail government savings bond for individuals was found."},"tbill_91d":{"available":false,"localName":null,"localNameEn":"Treasury bills","note":"No 3-month treasury bill for retail investors was found."},"tbond_5y":{"available":true,"localName":"Obligations de l''État","localNameEn":"Government bonds","note":"Few lines outstanding, bought on the secondary market; no 5-year yield found."},"tbond_10y":{"available":true,"localName":"Obligations de l''État","localNameEn":"Government bonds","sourceUrl":"https://data-api.ecb.europa.eu/service/data/IRS/M.LU.L.L40.CI.0000.EUR.N.Z"},"equity_fund":{"available":true,"localName":"Fonds d''investissement","localNameEn":"Investment funds / index funds (ETF)","note":"Retail funds widely available; Luxembourg is Europe''s largest fund domicile."},"gold":{"available":true,"localName":"Or d''investissement","localNameEn":"Investment gold (bars and coins)","note":"No restriction on buying physical gold; investment gold is VAT-exempt under EU rules."}},"institutions":{"centralBank":{"name":"Banque centrale du Luxembourg (BCL)","url":"https://www.bcl.lu/en/","note":"Part of the Eurosystem; monetary policy set by the European Central Bank."},"insuranceRegulator":{"name":"Commissariat aux Assurances (CAA)","url":"https://www.caa.lu/en"},"insuranceComplaints":{"name":"Commissariat aux Assurances, out-of-court settlement of disputes","url":"https://www.caa.lu/en/consumers/out-of-court-settlement-of-disputes"},"pensionScheme":{"name":"Caisse nationale d''assurance pension (CNAP)","url":"https://cnap.public.lu/en.html"},"oldAgeAllowance":null,"publicHealthCover":{"name":"Caisse nationale de santé (CNS)","url":"https://cns.public.lu/en.html"},"depositInsurance":{"name":"Fonds de garantie des dépôts Luxembourg (FGDL)","url":"https://www.fgdl.lu/en/deposit-guarantee/"},"statistics":{"name":"STATEC (National Institute of Statistics and Economic Studies)","url":"https://statistiques.public.lu/en.html"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LU', 1, 'bank_deposit_avg_rate', 0.0206, NULL, 'sourced', 'ECB MFI interest rate statistics: Luxembourg banks, household deposits with agreed maturity (outstanding amounts)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.LU.B.L22.A.R.A.2250.EUR.O', '2026-09-30', 'Average rate on all outstanding household term deposits, September 2026 (1.94% in August); household overnight deposits paid 0.62%. World Bank FR.INR.DPST has no Luxembourg figure.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LU', 1, 'credit_card_rate_cap', 0.1033, NULL, 'sourced', 'ECB MFI interest rate statistics: Luxembourg banks, revolving loans, overdrafts and credit card credit to households', 'https://data-api.ecb.europa.eu/service/data/MIR/M.LU.B.A2Z.A.R.A.2250.EUR.N', '2026-09-30', 'Typical rate, not a cap: average rate on household revolving loans, overdrafts and credit card credit, September 2026 (10.17% in August).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LU', 1, 'deposit_insurance_limit', 100000, NULL, 'sourced', 'Fonds de garantie des dépôts Luxembourg (FGDL), deposit guarantee', 'https://www.fgdl.lu/en/deposit-guarantee/', '2026-10-31', 'EUR 100,000 per person per bank; certain temporary high balances (property sales, life events) are protected up to EUR 2,500,000.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LU', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Banks sell monthly savings plans, but no average or official rate for them was found in BCL or ECB statistics.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LU', 1, 'equity_return_base', 0.055, NULL, 'assumption', '1-year deposit 2.20% less 20% tax = 1.76% (ECB MFI, Sep 2026) plus an equity premium of under 4 points', 'https://data-api.ecb.europa.eu/service/data/MIR/M.LU.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'The local LuxX index is tiny and concentrated, so the base uses a diversified euro/global equity fund in euros, capped at the after-tax safe rate plus about 4 points.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LU', 1, 'equity_return_high', 0.075, NULL, 'assumption', 'Long-run global equity returns in euros', 'https://data-api.ecb.europa.eu/service/data/MIR/M.LU.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'High case: a diversified equity fund matching long-run global equity returns of about 7-8% in euros.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LU', 1, 'equity_return_low', 0.03, NULL, 'assumption', '1-year deposit 2.20% less 20% tax = 1.76% (ECB MFI, Sep 2026); long-run euro-area equity returns', 'https://data-api.ecb.europa.eu/service/data/MIR/M.LU.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Low case: a diversified euro equity fund earns little more than safe savings over a long period.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LU', 1, 'fdr_1y_rate', 0.022, NULL, 'sourced', 'ECB MFI interest rate statistics: Luxembourg banks, household deposits with agreed maturity up to 1 year (new business)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.LU.B.L22.F.R.A.2250.EUR.N', '2026-09-30', 'Bucket covers all fixed terms up to one year (2.00% in August); deposits of over 1 and up to 2 years paid 2.68% in September 2026 (ECB MIR M.LU.B.L22.G).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LU', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'ECB/BCL MFI statistics publish household deposits with agreed maturity up to 1 year as one bucket (2.20% in September 2026); no separate 3-month term deposit rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LU', 1, 'fixed_income_return_base', 0.017, NULL, 'assumption', 'Household deposits up to 1 year 2.20% less 20% withholding = 1.76% (ECB MFI, Sep 2026)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.LU.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Base case: after-tax 1-year term deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LU', 1, 'fixed_income_return_high', 0.021, NULL, 'assumption', 'Household deposits over 1 and up to 2 years 2.68% less 20% withholding = 2.1% (ECB MFI, Sep 2026)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.LU.B.L22.G.R.A.2250.EUR.N', '2026-10-31', 'High case: locking in longer term deposits after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LU', 1, 'fixed_income_return_low', 0.01, NULL, 'assumption', 'Household deposits up to 1 year 2.20% (ECB MFI statistics, Sep 2026), assuming rates fall, less 20% withholding', 'https://data-api.ecb.europa.eu/service/data/MIR/M.LU.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Low case: term deposit rates drift down towards 1.25% before the 20% withholding.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LU', 1, 'goal_inflation_education', 0.035, NULL, 'assumption', 'Luxembourg CPI, education: +0.6% year on year in September 2026 (6.2% in August) (Trading Economics, from STATEC)', 'https://tradingeconomics.com/luxembourg/inflation-cpi/news/590178', '2026-10-31', 'Education price growth swings with fee changes; over the long run it is assumed to run about a point above the 2.5% planning inflation, in line with wage indexation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LU', 1, 'goal_inflation_health', 0.035, NULL, 'assumption', 'Luxembourg CPI, health: +1.7% year on year in September 2026 (Trading Economics, from STATEC); HICP health +2.5% in Dec 2025 (ECB)', 'https://tradingeconomics.com/luxembourg/inflation-cpi/news/590178', '2026-10-31', 'Measured health prices rise slowly because most care is CNS-reimbursed, but the cost of uncovered care is assumed to rise about a point above the 2.5% planning inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LU', 1, 'gold_return_base', 0.04, NULL, 'assumption', 'Gold price history (Trading Economics); ECB 2% inflation target', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Base case: dollar gold rises roughly with world inflation plus a little, and the euro is assumed stable against the dollar over the long run.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LU', 1, 'gold_return_high', 0.07, NULL, 'assumption', 'Gold price history (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'High case: a repeat of gold''s strong 2005-2025 trend in euro terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LU', 1, 'gold_return_low', 0.01, NULL, 'assumption', 'Gold price history (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Low case: gold barely keeps up after the 2025-26 spike, with no help from the euro.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LU', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No per-year gratuity: the Labour Code gives a severance allowance on dismissal by the employer in steps of 1 to 12 months'' wages after 5 to 30 years of service, which does not fit a days-per-year rule; no readable official page with the table was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LU', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'Hospital care for people insured with the CNS is largely covered, with a small daily patient contribution; no official figure for the out-of-pocket cost of a major hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LU', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Complementary health cover is sold by mutual societies and insurers, but no published premium table per EUR 100,000 of cover was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LU', 1, 'inflation_cpi', 0.029, NULL, 'sourced', 'Trading Economics, reporting the STATEC national consumer price index for September 2026', 'https://tradingeconomics.com/luxembourg/inflation-cpi/news/590178', '2026-09-30', 'Annual CPI inflation 2.9% in September 2026 (2.2% in August, highest since April). Secondary source: the STATEC release itself could not be found; World Bank 2025 average 2.3%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LU', 1, 'inflation_projection', 0.025, NULL, 'assumption', 'ECB 2% medium-term target; Luxembourg CPI averaged about 3.4% a year in 2021-2025 (6.3% in 2022); STATEC 2026 forecast 1.8-2.9%', 'https://data.worldbank.org/indicator/FP.CPI.TOTL.ZG?locations=LU', '2026-10-31', 'Luxembourg shares the ECB 2% target but has run slightly above it, so 2.5% is used for long-run planning.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LU', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life cover (assurance temporaire décès) is sold, but no regulator or other non-company published premium table per EUR 1,000 of cover was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LU', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Commissariat aux Assurances publishes market statistics but no industry-wide life claim settlement ratio could be found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LU', 1, 'life_expectancy', 83.2, NULL, 'sourced', 'Eurostat demo_mlexpec, life expectancy at birth, Luxembourg', 'https://ec.europa.eu/eurostat/databrowser/view/demo_mlexpec/default/table?lang=en', '2024-12-31', '2024 figure (latest published; older than 2025): men 81.0, women 85.5. World Bank 2024 figure 83.2.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LU', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":25.3,"men":23.7,"women":26.9},{"age":65,"total":21.1,"men":19.5,"women":22.5},{"age":70,"total":17,"men":15.6,"women":18.3},{"age":80,"total":9.8,"men":8.7,"women":10.6}]}', 'sourced', 'Eurostat demo_mlexpec, life expectancy by age and sex, Luxembourg', 'https://ec.europa.eu/eurostat/databrowser/view/demo_mlexpec/default/table?lang=en', '2024-12-31', '2024 period life table (latest published; older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LU', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'No dedicated non-contributory old-age pension found; REVIS (means-tested minimum income) is open to residents of any age from 25, including pensioners.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LU', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'No dedicated non-contributory old-age pension was found: the minimum pension needs 20 years of insurance (CNAP), and older people without enough record rely on the means-tested social inclusion income (REVIS, Fonds national de solidarité), which is a top-up to an income threshold rather than a fixed benefit.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LU', 1, 'oop_health_share', 0.085, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=LU', '2024-12-31', NULL, 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LU', 1, 'policy_rate', 0.025, NULL, 'sourced', 'European Central Bank, key ECB interest rates (deposit facility)', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.en.html', '2026-09-16', 'Luxembourg uses the euro; ECB deposit facility rate 2.50% since 16 September 2026 (2.25% from June 2026), confirmed in the ECB FM dataset on 31 October 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LU', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":65,"nomineeUntilAge":null,"inflationLinked":true,"taxFree":false}', 'sourced', 'CNAP, 2026 pension scheme changes; IGSS Aperçu no. 16 (indexation)', 'https://cnap.public.lu/en/actualites/2026/informationsreforme202601.html', '2026-02-25', 'General pension insurance scheme run by the CNAP: pension from 65 after 10 years of insurance; minimum pension after 20 years. Pensions are indexed to the cost of living and adjusted to real wage growth (IGSS). Contribution rate rose from 24% to 25.5% in 2026, shared by employer, employee and state. Pensions are taxed as ordinary income.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LU', 1, 'retirement_accumulation_return_base', 0.035, NULL, 'assumption', 'After-tax 1-year deposit 1.76%; equity base 5.5%', 'https://data-api.ecb.europa.eu/service/data/MIR/M.LU.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Base case: roughly half shares at 5.5% and half safe fixed income at about 1.7-2.1% after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LU', 1, 'retirement_accumulation_return_high', 0.048, NULL, 'assumption', 'After-tax 1-2 year deposit 2.1%; equity high 7.5%', 'https://data-api.ecb.europa.eu/service/data/MIR/M.LU.B.L22.G.R.A.2250.EUR.N', '2026-10-31', 'High case for a growth-leaning balanced mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LU', 1, 'retirement_accumulation_return_low', 0.022, NULL, 'assumption', 'After-tax 1-year deposit 1.76%; equity low 3%', 'https://data-api.ecb.europa.eu/service/data/MIR/M.LU.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Low case for a balanced mix if shares lag.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LU', 1, 'retirement_age_default', 65, NULL, 'sourced', 'CNAP (Caisse nationale d''assurance pension), information about the pension scheme changes in 2026', 'https://cnap.public.lu/en/actualites/2026/informationsreforme202601.html', '2026-02-25', 'The 2026 reform keeps the legal pension age at 65 (10 years of insurance needed), same for men and women; early pension from 57 (40 years of compulsory insurance) or 60 (40 years incl. credited periods), with the required career for early pensions rising gradually from 1 July 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LU', 1, 'retirement_age_government', 65, NULL, 'sourced', 'IGSS (Inspection générale de la sécurité sociale), Aperçu no. 16: long-term sustainability of public pension schemes', 'https://igss.gouvernement.lu/dam-assets/publications/aper%C3%A7us-et-cahiers/aper%C3%A7us/apercu-no16.pdf', '2022-03-31', 'Older than 2025: civil servants are covered by the special schemes (régimes spéciaux), which follow the same age rules as the general scheme: old-age pension at 65, early pension from 57 or 60 after 40 years.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LU', 1, 'retirement_return_base', 0.017, NULL, 'assumption', 'Household deposits up to 1 year 2.20% less 20% withholding = 1.76% (ECB MFI, Sep 2026)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.LU.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Base case capped at the after-tax 1-year term deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LU', 1, 'retirement_return_high', 0.021, NULL, 'assumption', 'Household deposits over 1 and up to 2 years 2.68% less 20% withholding = 2.1% (ECB MFI, Sep 2026)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.LU.B.L22.G.R.A.2250.EUR.N', '2026-10-31', 'High case: a ladder of longer term deposits after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LU', 1, 'retirement_return_low', 0.01, NULL, 'assumption', 'Household deposits up to 1 year 2.20% (ECB MFI, Sep 2026), assuming rates fall, less 20% withholding', 'https://data-api.ecb.europa.eu/service/data/MIR/M.LU.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Low case: term deposit rates drift lower.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LU', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No retail government savings certificate or savings bond for individuals was found; Luxembourg government bonds are syndicated to institutional investors and only traded on the secondary market.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LU', 1, 'savings_account_rate', 0.0062, NULL, 'sourced', 'ECB MFI interest rate statistics: Luxembourg banks, overnight deposits from households (new business)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.LU.B.L21.A.R.A.2250.EUR.N', '2026-09-30', 'Average rate on household overnight deposits in Luxembourg, September 2026 (0.60% in August).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LU', 1, 'support_ratio', NULL, '{"points":[{"year":2026,"value":4.42},{"year":2040,"value":3.27},{"year":2065,"value":2.09}]}', 'sourced', 'Eurostat EUROPOP2023 population projections, proj_23ndbi old-age dependency ratio (65+ to 15-64), baseline', 'https://ec.europa.eu/eurostat/databrowser/view/proj_23ndbi/default/table?lang=en', '2026-01-01', '100 divided by the projected old-age dependency ratio: 22.6 in 2026, 30.6 in 2040, 47.9 in 2065. World Bank 2025 ratio 23.1 gives 4.3.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LU', 1, 'tax_bank_interest', 0.2, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Luxembourg income determination (investment income)', 'https://taxsummaries.pwc.com/luxembourg/individual/income-determination', '2026-08-03', 'Savings interest paid to resident individuals bears a 20% withholding tax in full discharge of income tax (Relibi); interest not covered by it is taxed at progressive rates after a EUR 1,500 investment-income allowance.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LU', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No retail government savings certificate exists; interest on government bonds is ordinary savings interest under the 20% final withholding.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LU', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 3-month Luxembourg treasury bill yield was found; the state funds itself mainly with medium- and long-term bonds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LU', 1, 'tbond_10y_rate', 0.037, NULL, 'sourced', 'ECB long-term interest rate for convergence purposes, Luxembourg', 'https://data-api.ecb.europa.eu/service/data/IRS/M.LU.L.L40.CI.0000.EUR.N.Z', '2026-09-30', 'Monthly average 3.697% for September 2026 (3.40% in August, 3.30% in July); Luxembourg has few bonds outstanding, so the figure is indicative.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LU', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published 5-year Luxembourg government bond yield was found from the BCL, ECB or an allowed secondary source.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('LV', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"LV","iso3":"LVA","nameEn":"Latvia","nameNative":"Latvija","region":"europe_central_asia","languages":["lv","ru","en","ltg"],"currency":{"code":"EUR","symbol":"€","decimals":2,"compact":"intl","usdRate":{"value":0.8951,"status":"sourced","sourceName":"European Central Bank euro reference rate (USD)","sourceUrl":"https://data-api.ecb.europa.eu/service/data/EXR/D.USD.EUR.SP00.A","asOf":"2026-10-30","note":"EUR 1 = USD 1.1172, so about EUR 0.895 per US dollar; World Bank 2025 average 0.885."}},"instruments":{"savings_account":{"available":true,"localName":"Krājkonts","localNameEn":"Savings account","sourceUrl":"https://data-api.ecb.europa.eu/service/data/MIR/M.LV.B.L21.A.R.A.2250.EUR.N"},"fdr_3m":{"available":true,"localName":"Termiņnoguldījums","localNameEn":"Term deposit (3 months)"},"fdr_1y":{"available":true,"localName":"Termiņnoguldījums","localNameEn":"Term deposit (1 year)","sourceUrl":"https://data-api.ecb.europa.eu/service/data/MIR/M.LV.B.L22.F.R.A.2250.EUR.N"},"dps":{"available":false,"localName":null,"localNameEn":"Recurring deposit scheme","note":"No standard monthly recurring deposit product with a published rate was confirmed."},"sanchayapatra_5y":{"available":true,"localName":"Krājobligācijas","localNameEn":"State Treasury savings bonds","note":"Sold by the State Treasury to individuals for 6 months, 12 months, 5 and 10 years; interest tax-free; EUR 503 million held at end-September 2026.","sourceUrl":"https://www.krajobligacijas.lv/"},"tbill_91d":{"available":false,"localName":"Valsts parādzīmes","localNameEn":"Treasury bills","note":"Short-term bills are not regularly offered to retail investors; 6- and 12-month savings bonds fill that role."},"tbond_5y":{"available":true,"localName":"Valsts obligācijas","localNameEn":"Government bonds","note":"Auctioned by the State Treasury on the domestic market, mainly to banks and institutions."},"tbond_10y":{"available":true,"localName":"Valsts obligācijas","localNameEn":"Government bonds","sourceUrl":"https://data-api.ecb.europa.eu/service/data/IRS/M.LV.L.L40.CI.0000.EUR.N.Z"},"equity_fund":{"available":true,"localName":"Ieguldījumu fondi","localNameEn":"Investment funds and index funds (ETF)","note":"EU-wide funds and ETFs are sold to retail investors; Latvia''s own exchange is small."},"gold":{"available":true,"localName":"Investīciju zelts","localNameEn":"Investment gold bars and coins","note":"No restriction on buying physical gold; investment gold is VAT-exempt under EU rules."}},"institutions":{"centralBank":{"name":"Latvijas Banka","url":"https://www.bank.lv/en/","note":"Part of the Eurosystem; monetary policy is set by the European Central Bank."},"insuranceRegulator":{"name":"Latvijas Banka (financial market supervision)","url":"https://www.bank.lv/en/operational-areas/supervision"},"insuranceComplaints":{"name":"Latvijas Banka, customer protection","url":"https://www.bank.lv/en/operational-areas/customer-protection"},"pensionScheme":{"name":"Valsts sociālās apdrošināšanas aģentūra (State Social Insurance Agency), old-age pension","url":"https://www.vsaa.gov.lv/en/services/granting-and-payment-old-age-pension"},"oldAgeAllowance":{"name":"Valsts sociālā nodrošinājuma pabalsts (state social security benefit)","url":"https://www.vsaa.gov.lv/en/services/granting-and-disbursement-state-social-security-benefit"},"publicHealthCover":{"name":"Nacionālais veselības dienests (National Health Service)","url":"https://www.vmnvd.gov.lv/en"},"depositInsurance":{"name":"Latvijas Banka, Deposit Guarantee Fund","url":"https://www.bank.lv/en/operational-areas/customer-protection/operation-of-guarantee-funds/deposit-guarantee-fund"},"statistics":{"name":"Centrālā statistikas pārvalde (Central Statistical Bureau)","url":"https://stat.gov.lv/en"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LV', 1, 'bank_deposit_avg_rate', 0.0257, NULL, 'sourced', 'ECB MFI interest rate statistics, Latvia, household deposits with agreed maturity (outstanding amounts)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.LV.B.L22.A.R.A.2250.EUR.O', '2026-09-30', 'Average rate on the stock of household deposits with agreed maturity (outstanding amounts), September 2026 (2.48% in August).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LV', 1, 'credit_card_rate_cap', 0.1758, NULL, 'sourced', 'ECB MFI interest rate statistics, Latvia, revolving loans, overdrafts and credit card credit to households', 'https://data-api.ecb.europa.eu/service/data/MIR/M.LV.B.A2Z.A.R.A.2250.EUR.N', '2026-09-30', 'No specific card-rate cap found; this is the average rate on household revolving loans, overdrafts and extended credit card credit in September 2026 (17.51% in August).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LV', 1, 'deposit_insurance_limit', 100000, NULL, 'sourced', 'Latvijas Banka, Deposit Guarantee Fund', 'https://www.bank.lv/en/operational-areas/customer-protection/operation-of-guarantee-funds/deposit-guarantee-fund', '2025-06-03', 'Up to EUR 100,000 per depositor per bank or credit union (page updated 3 June 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LV', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published average rate for monthly recurring deposits in Latvia.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LV', 1, 'equity_return_base', 0.055, NULL, 'assumption', 'Global equity index in euro terms; savings bond 12-month rate 3.30% tax-free', 'https://ifinanses.lv/zinas/actual-ieguldijumi-krajobligacijas-sasniedz-rekordu/31765', '2026-10-31', 'The local Riga market is too small to rely on, so the base case is a global index fund in euros about 2 points over the tax-free savings bond rate, within 4 points of the after-tax safe return.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LV', 1, 'equity_return_high', 0.075, NULL, 'assumption', 'Global equity long-run returns in euro terms', 'https://tradingeconomics.com/united-states/stock-market', '2026-10-31', 'High case: global equities match their long-run record of about 7-8% a year in euros.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LV', 1, 'equity_return_low', 0.03, NULL, 'assumption', 'Global equity index in euro terms (S&P 500 +10.8% in a year to Oct 2026); Latvia''s own stock exchange is very small', 'https://tradingeconomics.com/united-states/stock-market', '2026-10-31', 'Low case: a global index fund in euros delivers little more than safe euro rates over a long stretch, as after 2000 and 2008.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LV', 1, 'fdr_1y_rate', 0.0275, NULL, 'sourced', 'ECB MFI interest rate statistics, Latvia, household deposits with agreed maturity up to 1 year (new business)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.LV.B.L22.F.R.A.2250.EUR.N', '2026-09-30', 'New household term deposits with agreed maturity up to 1 year, September 2026 (2.52% in August, 2.31% in July).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LV', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Latvijas Banka and the ECB publish household term-deposit rates only for the up-to-1-year bucket (2.75% in September 2026), not 3 months separately.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LV', 1, 'fixed_income_return_base', 0.028, NULL, 'assumption', 'State Treasury savings bonds 3.30% (12 months) to 3.85% (5 years), tax-free', 'https://ifinanses.lv/zinas/actual-ieguldijumi-krajobligacijas-sasniedz-rekordu/31765', '2026-10-31', 'Base case: a mix of tax-free savings bonds and taxed term deposits, a little below today''s savings bond rates because euro rates may drift lower.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LV', 1, 'fixed_income_return_high', 0.038, NULL, 'assumption', 'State Treasury savings bonds 5-year 3.85%, 10-year 4.30%, tax-free', 'https://ifinanses.lv/zinas/actual-ieguldijumi-krajobligacijas-sasniedz-rekordu/31765', '2026-10-31', 'High case: locking in longer tax-free savings bonds near current rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LV', 1, 'fixed_income_return_low', 0.018, NULL, 'assumption', 'ECB MIR Latvia: household deposits up to 1 year 2.75% (Sep 2026) less 25.5% tax', 'https://data-api.ecb.europa.eu/service/data/MIR/M.LV.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Low case: bank term deposits after the 25.5% tax on interest (about 2.0%), with some time in near-zero overnight deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LV', 1, 'goal_inflation_education', 0.035, NULL, 'assumption', 'Latvian CPI 3.2% (Sep 2026), with higher education fees reviewed upward in September 2026', 'https://lvportals.lv/dienaskartiba/395581-septembri-cenu-kapumu-galvenokart-noteica-dargaka-degviela-2026', '2026-10-31', 'Private and higher education fees are assumed to rise about one point faster than general inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LV', 1, 'goal_inflation_health', 0.04, NULL, 'assumption', 'Latvian CPI 3.2% (Sep 2026); 2.5% long-run inflation assumption', 'https://lvportals.lv/dienaskartiba/395581-septembri-cenu-kapumu-galvenokart-noteica-dargaka-degviela-2026', '2026-10-31', 'Medical costs are assumed to rise about 1.5 points faster than general inflation, as wages in health care catch up with the EU.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LV', 1, 'gold_return_base', 0.04, NULL, 'assumption', 'Gold price history (Trading Economics); ECB 2% inflation target', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Base case: dollar gold rises with world inflation plus a little, and the euro is assumed stable against the dollar over the long run.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LV', 1, 'gold_return_high', 0.07, NULL, 'assumption', 'Gold price history (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'High case: a repeat of gold''s strong 2005-2025 trend in euro terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LV', 1, 'gold_return_low', 0.01, NULL, 'assumption', 'Gold USD 3,876/oz on 30 Oct 2026, 31% below the January 2026 high', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Low case: gold barely keeps up after the 2025-26 spike, with no help from the euro.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LV', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No statutory end-of-service gratuity for private employees was found in the sources reviewed (web search budget ran out before the Labour Law could be checked), so it is not marked absent.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LV', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published figure for the typical out-of-pocket cost of a private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LV', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No regulator or official published voluntary health insurance premium table was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LV', 1, 'inflation_cpi', 0.032, NULL, 'sourced', 'Latvijas Vēstnesis portal (lvportals.lv), citing the Central Statistical Bureau, September 2026 CPI', 'https://lvportals.lv/dienaskartiba/395581-septembri-cenu-kapumu-galvenokart-noteica-dargaka-degviela-2026', '2026-09-30', 'Consumer prices rose 3.2% in September 2026 compared with September 2025; read on the state legal information portal (lvportals.lv) reporting the Central Statistical Bureau release, because the CSB release page was not found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LV', 1, 'inflation_projection', 0.025, NULL, 'assumption', 'ECB 2% inflation target; Latvian CPI 3.2% (Sep 2026), 3.7% in 2025 (World Bank)', 'https://lvportals.lv/dienaskartiba/395581-septembri-cenu-kapumu-galvenokart-noteica-dargaka-degviela-2026', '2026-10-31', 'Latvia uses the euro, so long-run inflation should converge toward the ECB 2% target, but Baltic price catch-up keeps it somewhat higher, so 2.5% is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LV', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No regulator or official published term life premium data was found; only insurer quotes exist, which may not be cited.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LV', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Latvijas Banka (insurance supervisor) publishes no industry life claim settlement ratio that could be found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LV', 1, 'life_expectancy', 76.4, NULL, 'sourced', 'Eurostat, life expectancy by age and sex (demo_mlexpec)', 'https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/demo_mlexpec?geo=LV&age=Y60&age=Y65&age=Y70&age=Y80&age=Y_LT1&sex=T&sex=M&sex=F&lastTimePeriod=1', '2024-12-31', 'Men 71.4, women 81.2 in 2024 (latest Eurostat year; older than 2025). World Bank 2024 also 76.4.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LV', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":21.5,"men":18.1,"women":24},{"age":65,"total":17.8,"men":14.9,"women":19.8},{"age":70,"total":14.4,"men":12,"women":15.9},{"age":80,"total":8.5,"men":7.2,"women":9}]}', 'sourced', 'Eurostat, life expectancy by age and sex (demo_mlexpec)', 'https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/demo_mlexpec?geo=LV&age=Y60&age=Y65&age=Y70&age=Y80&age=Y_LT1&sex=T&sex=M&sex=F&lastTimePeriod=1', '2024-12-31', 'Remaining life expectancy at each age in 2024, the latest year Eurostat publishes (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LV', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":65,"womenAge":65,"over90Monthly":null,"meansTested":false}', 'sourced', 'State Social Insurance Agency (VSAA), state social security benefit', 'https://www.vsaa.gov.lv/en/services/granting-and-disbursement-state-social-security-benefit', '2025-01-01', 'Paid from the state pension age (65) to permanent residents with at least 60 months of residence (the last 12 continuous) who do not qualify for an old-age, disability or survivor''s pension; no income or asset test, but a foreign pension reduces it.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LV', 1, 'old_age_allowance_monthly', 187, NULL, 'sourced', 'State Social Insurance Agency (VSAA), state social security benefit', 'https://www.vsaa.gov.lv/lv/pakalpojumi/valsts-sociala-nodrosinajuma-pabalsta-pieskirsana-un-izmaksasana', '2026-01-01', 'For people of pension age with no pension of their own: 22% of the income median (VSAA English page); from 1 January 2026 the income median used is EUR 850.02 a month (VSAA Latvian page), so the benefit is about EUR 187.00 a month (EUR 166.04 in 2025). The euro amount is calculated from these two official figures.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LV', 1, 'oop_health_share', 0.3506, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS (WHO GHED)', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=LV', '2023-12-31', 'Out-of-pocket spending was 35.1% of current health expenditure in 2023 (older than 2025; latest available).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LV', 1, 'policy_rate', 0.025, NULL, 'sourced', 'European Central Bank, deposit facility rate', 'https://data-api.ecb.europa.eu/service/data/FM/B.U2.EUR.4F.KR.DFR.LEV', '2026-09-16', 'Latvia is in the euro area; the ECB deposit facility rate is 2.50% from 16 September 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LV', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":65,"nomineeUntilAge":null,"inflationLinked":true,"taxFree":false}', 'sourced', 'Law on State Pensions (Sections 11 and 26), likumi.lv; VSAA old-age pension page for tax', 'https://likumi.lv/ta/en/en/id/38048-on-state-pensions', '2025-01-01', 'Mandatory notional-account state pension (1st tier) plus funded 2nd tier: pension from 65 with at least 20 insurance years (Section 11; 65 from 1 January 2025). Pensions are reviewed every 1 October by the actual CPI plus 50-80% of contribution wage growth depending on insurance years (Section 26). VSAA: pensions above the EUR 1,000 monthly non-taxable minimum are taxed at 25.5%. The English translation read is the 2024 consolidated version.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LV', 1, 'retirement_accumulation_return_base', 0.042, NULL, 'assumption', 'Global equity base 5.5%; fixed income base 2.8%', 'https://ifinanses.lv/zinas/actual-ieguldijumi-krajobligacijas-sasniedz-rekordu/31765', '2026-10-31', 'Base case: roughly half global shares and half savings bonds and deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LV', 1, 'retirement_accumulation_return_high', 0.055, NULL, 'assumption', 'Global equity high 7.5%; fixed income high 3.8%', 'https://ifinanses.lv/zinas/actual-ieguldijumi-krajobligacijas-sasniedz-rekordu/31765', '2026-10-31', 'High case for a growth-leaning balanced mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LV', 1, 'retirement_accumulation_return_low', 0.025, NULL, 'assumption', 'Global equity low case 3%; fixed income low case 1.8%', 'https://ifinanses.lv/zinas/actual-ieguldijumi-krajobligacijas-sasniedz-rekordu/31765', '2026-10-31', 'Low case for a balanced mix if global shares lag.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LV', 1, 'retirement_age_default', 65, NULL, 'sourced', 'State Social Insurance Agency (VSAA), granting and payment of the old-age pension', 'https://www.vsaa.gov.lv/en/services/granting-and-payment-old-age-pension', '2025-01-01', 'Retirement age is 65 for men and women from 2025 (Law on State Pensions, transitional provisions), with at least 20 years of insurance; no further increase is legislated, so it applies to people born after 1975.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LV', 1, 'retirement_age_government', 65, NULL, 'sourced', 'State Social Insurance Agency (VSAA), granting and payment of the old-age pension', 'https://www.vsaa.gov.lv/en/services/granting-and-payment-old-age-pension', '2025-01-01', 'Civil servants receive the general state old-age pension at 65; separate service pensions apply only to specific groups such as police and military.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LV', 1, 'retirement_return_base', 0.025, NULL, 'assumption', 'State Treasury 12-month savings bonds 3.30%, tax-free', 'https://ifinanses.lv/zinas/actual-ieguldijumi-krajobligacijas-sasniedz-rekordu/31765', '2026-10-31', 'Base case kept below the tax-free 12-month savings bond rate of 3.3%, the best safe 1-year option.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LV', 1, 'retirement_return_high', 0.033, NULL, 'assumption', 'State Treasury savings bonds 5-year 3.85%, tax-free', 'https://ifinanses.lv/zinas/actual-ieguldijumi-krajobligacijas-sasniedz-rekordu/31765', '2026-10-31', 'High case: a ladder of longer tax-free savings bonds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LV', 1, 'retirement_return_low', 0.015, NULL, 'assumption', 'ECB MIR Latvia: household deposits up to 1 year 2.75% (Sep 2026) less 25.5% tax', 'https://data-api.ecb.europa.eu/service/data/MIR/M.LV.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Low case: a retiree holding mostly bank deposits after the 25.5% interest tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LV', 1, 'sanchayapatra_5y_rate', 0.0385, NULL, 'sourced', 'iFinanses (news), State Treasury savings bonds rates', 'https://ifinanses.lv/zinas/actual-ieguldijumi-krajobligacijas-sasniedz-rekordu/31765', '2026-10-05', 'State Treasury savings bonds (krājobligācijas) for individuals pay 3.85% a year for 5 years (6 months 3.00%, 12 months 3.30%, 10 years 4.30%) in early October 2026; secondary source because the savings bond site is script-only.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LV', 1, 'savings_account_rate', 0.0042, NULL, 'sourced', 'ECB MFI interest rate statistics, Latvia, overnight deposits from households', 'https://data-api.ecb.europa.eu/service/data/MIR/M.LV.B.L21.A.R.A.2250.EUR.N', '2026-09-30', 'Average rate on household overnight (demand) deposits, new business, September 2026 (0.42% also in August); includes ordinary savings accounts.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LV', 1, 'support_ratio', NULL, '{"points":[{"year":2026,"value":2.82},{"year":2040,"value":2.21},{"year":2065,"value":1.7}]}', 'sourced', 'Eurostat EUROPOP2023 population projections, old-age dependency ratio (proj_23ndbi, baseline)', 'https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/proj_23ndbi?geo=LV&projection=BSL&indic_de=OLDDEP1&time=2026&time=2040&time=2065', '2026-01-01', '100 / projected old-age dependency ratio of 35.5 (2026), 45.3 (2040) and 58.8 (2065); the observed ratio was 34.7 in 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LV', 1, 'tax_bank_interest', 0.255, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Latvia, income determination', 'https://taxsummaries.pwc.com/latvia/individual/income-determination', '2026-06-30', 'Interest income of individuals is taxed at 25.5%, usually withheld by Latvian payers.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LV', 1, 'tax_sanchayapatra_profit', 0, NULL, 'sourced', 'iFinanses (news), State Treasury savings bonds', 'https://ifinanses.lv/zinas/actual-ieguldijumi-krajobligacijas-sasniedz-rekordu/31765', '2026-10-05', 'Interest on State Treasury savings bonds is not taxed, unlike bank deposit interest; secondary source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LV', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The State Treasury does not regularly issue 3-month bills to the public; its monthly bulletin for September 2026 lists only medium-term GMTN auctions.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LV', 1, 'tbond_10y_rate', 0.0415, NULL, 'sourced', 'ECB long-term interest rate for convergence purposes, Latvia (10-year government bond yield)', 'https://data-api.ecb.europa.eu/service/data/IRS/M.LV.L.L40.CI.0000.EUR.N.Z', '2026-09-30', 'Monthly average 10-year Latvian government bond yield, September 2026 (3.82% in August).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LV', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published 5-year Latvian government bond yield could be read (auction rates appear only as charts in the State Treasury bulletin).', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('LY', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"LY","iso3":"LBY","nameEn":"Libya","nameNative":"ليبيا","region":"middle_east_north_africa","languages":["ar","ayl","en"],"currency":{"code":"LYD","symbol":"LD","decimals":3,"compact":"intl","usdRate":{"value":6.4304,"status":"sourced","sourceName":"Central Bank of Libya, currency exchange rates (US dollar average)","sourceUrl":"https://cbl.gov.ly/en/currency-exchange-rates/","asOf":"2026-10-29","note":"Buy 6.4143, sell 6.4465 dinars per dollar on 29 October 2026 (the page showed an average of 6.4173 on 3 November 2026); World Bank 2025 average 5.30, so the dinar has been devalued since."}},"instruments":{"savings_account":{"available":true,"localName":"حساب توفير","localNameEn":"Savings account","note":"No published interest rate; banks are understood to avoid interest-based products (Law No. 1 of 2013, not confirmed from an official page)."},"fdr_3m":{"available":false,"localName":null,"localNameEn":"Term deposit (3 months)","note":"No interest-bearing term deposit with a published rate was found; any investment deposits work on profit-sharing without a published rate."},"fdr_1y":{"available":false,"localName":null,"localNameEn":"Term deposit (1 year)","note":"No interest-bearing term deposit with a published rate was found; any investment deposits work on profit-sharing without a published rate."},"dps":{"available":false,"localName":null,"localNameEn":"Recurring deposit","note":"No monthly recurring deposit scheme with published rates was found."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":"Government savings certificate","note":"No government savings certificate or retail savings bond for individuals was found."},"tbill_91d":{"available":false,"localName":null,"localNameEn":"Treasury bills","note":"No treasury bill market was found."},"tbond_5y":{"available":false,"localName":null,"localNameEn":"Government bonds","note":"No government bond market was found."},"tbond_10y":{"available":false,"localName":null,"localNameEn":"Government bonds","note":"No government bond market was found."},"equity_fund":{"available":false,"localName":null,"localNameEn":"Mutual fund","note":"No active local stock market or retail index fund was found; buying foreign funds is restricted by currency controls."},"gold":{"available":true,"localName":"ذهب (سبائك وجنيهات)","localNameEn":"Gold bars and coins","note":"Physical gold is widely bought as a store of value."}},"institutions":{"centralBank":{"name":"مصرف ليبيا المركزي (Central Bank of Libya)","url":"https://cbl.gov.ly/en/"},"insuranceRegulator":{"name":"هيئة الإشراف على التأمين (Insurance Supervisory Authority)","url":"https://isa.gov.ly/","note":"Website refused automated access during research."},"insuranceComplaints":{"name":"هيئة الإشراف على التأمين (Insurance Supervisory Authority)","url":"https://isa.gov.ly/"},"pensionScheme":{"name":"صندوق الضمان الاجتماعي (Social Security Fund)","url":"https://ssf.gov.ly/?page_id=20544"},"oldAgeAllowance":null,"publicHealthCover":null,"depositInsurance":null,"statistics":{"name":"مصلحة الإحصاء والتعداد (Bureau of Statistics and Census)","url":"https://bsc.ly/","note":"The site showed only 2023 CPI data and some injected third-party content during research."}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LY', 1, 'bank_deposit_avg_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The latest World Bank deposit rate (FR.INR.DPST) for Libya is 2.5% for 2014, before interest was banned in banking; the Central Bank of Libya''s monetary statistics publish no deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LY', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap or typical credit card rate was found. Libyan banks publish no interest rates; Law No. 1 of 2013 against interest-based (riba) transactions is the usual reason given, but no official page stating it was read during research or review.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LY', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No deposit insurance scheme or coverage limit was found on the Central Bank of Libya''s website.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LY', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No monthly recurring deposit product with a published rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LY', 1, 'equity_return_base', 0.05, NULL, 'assumption', 'Global equity long-run return; dinar fell about 18% against the dollar in the year to Oct 2026', 'https://tradingeconomics.com/libya/currency', '2026-10-31', 'No working local stock market, so the base is a global index in dinar terms, capped at the safe rate (about 1%) plus 4 points; access to foreign funds is also restricted.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LY', 1, 'equity_return_high', 0.1, NULL, 'assumption', 'Global equity long-run return plus dinar depreciation (Trading Economics USD/LYD)', 'https://tradingeconomics.com/libya/currency', '2026-10-31', 'High case: global equities earn about 7% in dollars and the dinar keeps losing about 3% a year.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LY', 1, 'equity_return_low', 0.02, NULL, 'assumption', 'No active local stock market; global equities in dinar terms; LYD per USD 6.43 (Oct 2026)', 'https://cbl.gov.ly/en/currency-exchange-rates/', '2026-10-31', 'Low case: global equities disappoint and the dinar stays stable from here.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LY', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published 1-year term deposit rate was found. Libyan banks publish no interest rates; Law No. 1 of 2013 against interest-based (riba) transactions is the usual reason given, but no official page stating it was read during research or review.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LY', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published 3-month term deposit rate was found. Libyan banks publish no interest rates; Law No. 1 of 2013 against interest-based (riba) transactions is the usual reason given, but no official page stating it was read during research or review.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LY', 1, 'fixed_income_return_base', 0.01, NULL, 'assumption', 'No interest-bearing deposits or treasury bills available to individuals', 'https://tradingeconomics.com/libya/interest-rate', '2026-10-31', 'Base case: a small profit share on Islamic investment deposits at most; no published rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LY', 1, 'fixed_income_return_high', 0.03, NULL, 'assumption', 'Central Bank of Libya rediscount rate 3%', 'https://tradingeconomics.com/libya/interest-rate', '2026-10-31', 'High case: profit-sharing deposits paying around the central bank''s 3% rediscount rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LY', 1, 'fixed_income_return_low', 0, NULL, 'assumption', 'No published deposit or treasury bill rates in Libya; Central Bank of Libya rate 3% (Trading Economics)', 'https://tradingeconomics.com/libya/interest-rate', '2026-10-31', 'Low case: cash and current deposits earn nothing.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LY', 1, 'goal_inflation_education', 0.07, NULL, 'assumption', 'Trading Economics CPI 16.6% (Sep 2026)', 'https://tradingeconomics.com/libya/inflation-cpi', '2026-10-31', 'Public education is free, but private school fees are assumed to rise a little faster than the 6% headline planning rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LY', 1, 'goal_inflation_health', 0.08, NULL, 'assumption', 'Trading Economics CPI 16.6% (Sep 2026); medicines and private care largely imported', 'https://tradingeconomics.com/libya/inflation-cpi', '2026-10-31', 'Health costs depend on imported medicines and private clinics priced off the dollar, so they are assumed to rise faster than the 6% headline planning rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LY', 1, 'gold_return_base', 0.07, NULL, 'assumption', 'Gold price history (Trading Economics); dinar devalued in 2025 and 2026', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Base case: dollar gold rises with world inflation plus a little, and the dinar loses about 3% a year.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LY', 1, 'gold_return_high', 0.12, NULL, 'assumption', 'Gold price history (Trading Economics); USD/LYD up about 18% in the year to Oct 2026', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'High case: strong dollar gold plus further devaluations like 2025-26.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LY', 1, 'gold_return_low', 0.02, NULL, 'assumption', 'Gold price history (Trading Economics); dinar stable after the 2026 devaluation', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Low case: gold barely gains after the 2025-26 spike and the dinar holds its new rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LY', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No statutory end-of-service gratuity for private employees could be confirmed; the Labour Relations Law (No. 12 of 2010) could not be checked.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LY', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'Public hospital care is free, but no figure for the typical out-of-pocket cost of a major private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LY', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premium table per LYD 100,000 of cover was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LY', 1, 'inflation_cpi', 0.166, NULL, 'sourced', 'Trading Economics (Bureau of Statistics and Census Libya CPI, September 2026)', 'https://tradingeconomics.com/libya/inflation-cpi', '2026-09-30', 'CPI up 16.6% year on year in September 2026 (14.3% in August), the highest since March 2023, after the dinar''s devaluation; secondary source because the bureau''s site (bsc.ly) shows only 2023 data. World Bank 2025 average 1.8%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LY', 1, 'inflation_projection', 0.06, NULL, 'assumption', 'World Bank CPI 2021-2025 (about 2-5% a year); Trading Economics CPI 16.6% (Sep 2026) and its 7% forecast for 2028', 'https://data.worldbank.org/indicator/FP.CPI.TOTL.ZG?locations=LY', '2026-10-31', 'Inflation was low for years under subsidised prices but jumped after the 2025-26 devaluations, so 6% (between the pre-devaluation average and the current rate) is used for planning.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LY', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published term-life premium rates per LYD 1,000 of cover by age were found; life insurance is a very small market in Libya.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LY', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No industry life claim settlement ratio was found; the Insurance Supervisory Authority''s website refused automated access.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LY', 1, 'life_expectancy', 75.2, NULL, 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/libya', '2026-07-01', 'Men 72.7, women 77.8 (UN WPP estimate for 2026, mid-year); World Bank 2024 figure 71.1. Re-checked on georank 2026-11-03.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LY', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":20.2,"men":18.6,"women":21.9},{"age":65,"total":16.4,"men":15,"women":17.8},{"age":70,"total":13,"men":11.8,"women":14.1},{"age":80,"total":7.3,"men":6.7,"women":7.8}]}', 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/libya', '2026-07-01', 'Remaining years computed from georank''s expected age at death by current age (UN WPP 2026 estimate).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LY', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'Eligibility ages and means test for the basic pension could not be read from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LY', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'Libya has a basic pension (al-ma''ash al-asasi) for people without other income, mentioned on the Social Security Fund''s pensions page, but its current monthly amount could not be read from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LY', 1, 'oop_health_share', 0.1918, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=LY', '2023-12-31', 'Older than 2025; latest available.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LY', 1, 'policy_rate', 0.03, NULL, 'sourced', 'Trading Economics, Libya interest rate (Central Bank of Libya rediscount rate)', 'https://tradingeconomics.com/libya/interest-rate', '2026-10-31', 'Central Bank of Libya rate 3% (latest reading October 2026, same as the previous reading); secondary source because the Central Bank publishes no policy-rate page. It has little practical effect, as banks publish no deposit or lending rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LY', 1, 'public_pension_scheme', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Social Security Fund runs the compulsory pension; its pensions page says the pension is based on years of service and the average of the last 36 months'' pay, with a minimum of 80% of the national minimum wage, but gives no pension age or indexation rule.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LY', 1, 'retirement_accumulation_return_base', 0.04, NULL, 'assumption', 'Gold base 7%, global equity base 5%, cash 1%', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Base case: a mix of cash, gold and (where accessible) global shares.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LY', 1, 'retirement_accumulation_return_high', 0.07, NULL, 'assumption', 'Gold high 12%, global equity high 10%', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'High case for a gold- and equity-heavy mix with further dinar depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LY', 1, 'retirement_accumulation_return_low', 0.01, NULL, 'assumption', 'Cash earns nothing; gold and global equity low cases 2%', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Low case for a mix of cash, gold and foreign shares.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LY', 1, 'retirement_age_default', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Social Security Fund''s pensions page says the old-age pension age depends on the labour law, type of work and sex, without giving figures (it mentions early retirement for men at 60); no official statutory pension age could be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LY', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'No official page stating the retirement age for civil servants could be read; the Social Security Fund page mentions early retirement after 20 years of service under Law No. 8 of 1985 but no normal age.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LY', 1, 'retirement_return_base', 0.01, NULL, 'assumption', 'No interest-bearing deposit or treasury bill available to individuals', 'https://tradingeconomics.com/libya/interest-rate', '2026-10-31', 'Base case kept near zero because there is no after-tax deposit or bill rate to rely on.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LY', 1, 'retirement_return_high', 0.03, NULL, 'assumption', 'Central Bank of Libya rediscount rate 3%', 'https://tradingeconomics.com/libya/interest-rate', '2026-10-31', 'High case: Islamic profit-sharing deposits paying around 3%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LY', 1, 'retirement_return_low', 0, NULL, 'assumption', 'No published deposit or treasury bill rates in Libya; Central Bank of Libya rate 3% (Trading Economics)', 'https://tradingeconomics.com/libya/interest-rate', '2026-10-31', 'Low case: savings held as cash or current deposits earn nothing.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LY', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate or retail savings bond for individuals was found in Libya.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LY', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published savings account rate was found. Libyan banks publish no interest rates; Law No. 1 of 2013 against interest-based (riba) transactions is the usual reason given, but no official page stating it was read during research or review.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LY', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":13.09},{"year":2040,"value":6.02},{"year":2065,"value":3.39}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/libya/2040/', '2025-12-31', '100 / old-age dependency ratio: 7.6 (2025, World Bank), 16.6 (2040) and 29.5 (2065, populationpyramid.net/libya/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LY', 1, 'tax_bank_interest', 0, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Libya: taxes on personal income (reviewed 31 May 2026)', 'https://taxsummaries.pwc.com/libya/individual/taxes-on-personal-income', '2026-05-31', 'PwC says individuals are only taxed on employment income earned in Libya; in practice banks pay no interest.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LY', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'Libya has no government savings certificate, so no tax rate applies.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LY', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No Libyan treasury bill market was found; the Central Bank of Libya''s monetary and banking statistics list no bill yields.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LY', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No Libyan government bond market was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('LY', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No Libyan government bond market was found.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('MA', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"MA","iso3":"MAR","nameEn":"Morocco","nameNative":"المغرب","region":"middle_east_north_africa","languages":["ar","ary","zgh","fr","en"],"currency":{"code":"MAD","symbol":"DH","decimals":2,"compact":"intl","usdRate":{"value":9.8138,"status":"sourced","sourceName":"Bank Al-Maghrib, reference exchange rates, US dollar, 30 October 2026","sourceUrl":"https://www.bkam.ma/Marches/Principaux-indicateurs/Marche-des-changes/Cours-de-change/Cours-de-reference","asOf":"2026-10-30","note":"9.8138 dirhams per US dollar (9.8393 the day before); World Bank 2025 average 9.35. CLDR gives no narrow symbol; ''DH'' is the usual local abbreviation."}},"instruments":{"savings_account":{"available":true,"localName":"حساب على دفتر","localNameEn":"Passbook savings account (compte sur carnet)","note":"Rate regulated by Bank Al-Maghrib every six months (1.82% for H2 2026).","sourceUrl":"https://www.bkam.ma/Marches/Taux-d-interet/Taux-des-comptes-sur-carnet"},"fdr_3m":{"available":true,"localName":"وديعة لأجل","localNameEn":"Term deposit (dépôt à terme)","note":"Bank Al-Maghrib publishes average rates only for 6 and 12 months.","sourceUrl":"https://www.bkam.ma/Marches/Taux-d-interet/Taux-des-depots-a-terme"},"fdr_1y":{"available":true,"localName":"وديعة لأجل (سنة)","localNameEn":"Term deposit, 12 months (dépôt à terme)","sourceUrl":"https://www.bkam.ma/Marches/Taux-d-interet/Taux-des-depots-a-terme"},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No standard monthly recurring deposit product was found; banks offer housing and education savings plans."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate for individuals was found."},"tbill_91d":{"available":true,"localName":"سندات الخزينة","localNameEn":"Treasury bills (bons du Trésor)","note":"Auctioned by the Treasury to banks and institutions; individuals reach them mainly through banks or money-market funds.","sourceUrl":"https://www.bkam.ma/Marches/Principaux-indicateurs/Marche-obligataire/Marche-des-bons-de-tresor/Marche-secondaire/Taux-de-reference-des-bons-du-tresor"},"tbond_5y":{"available":true,"localName":"سندات الخزينة","localNameEn":"Treasury bonds (bons du Trésor)","note":"Mostly held by banks, insurers and funds.","sourceUrl":"https://www.bkam.ma/Marches/Principaux-indicateurs/Marche-obligataire/Marche-des-bons-de-tresor/Marche-secondaire/Taux-de-reference-des-bons-du-tresor"},"tbond_10y":{"available":true,"localName":"سندات الخزينة","localNameEn":"Treasury bonds (bons du Trésor)","note":"Mostly held by banks, insurers and funds.","sourceUrl":"https://www.bkam.ma/Marches/Principaux-indicateurs/Marche-obligataire/Marche-des-bons-de-tresor/Marche-secondaire/Taux-de-reference-des-bons-du-tresor"},"equity_fund":{"available":true,"localName":"هيئات التوظيف الجماعي للقيم المنقولة","localNameEn":"Collective investment funds (OPCVM)","note":"Supervised by the capital-market authority (AMMC); equity funds track or invest in the Casablanca market (MASI)."},"gold":{"available":true,"localName":"الذهب","localNameEn":"Gold","note":"Gold is mainly bought as jewellery; bars and coins are less common."}},"institutions":{"centralBank":{"name":"Bank Al-Maghrib","url":"https://www.bkam.ma/"},"insuranceRegulator":{"name":"Autorité de Contrôle des Assurances et de la Prévoyance Sociale (ACAPS)","url":"https://www.acaps.ma/"},"insuranceComplaints":{"name":"ACAPS online insurance complaints","url":"https://www.acaps.ma/fr/e-services"},"pensionScheme":{"name":"Caisse Nationale de Sécurité Sociale (CNSS), old-age pension","url":"https://www.cnss.ma/"},"oldAgeAllowance":null,"publicHealthCover":{"name":"Compulsory health insurance (AMO), regulated by the Agence Nationale de l''Assurance Maladie (ANAM)","url":"https://www.anam.ma/"},"depositInsurance":{"name":"Fonds collectif de garantie des dépôts, managed by SGFG","url":"https://www.sgfg.ma/"},"statistics":{"name":"Haut-Commissariat au Plan (HCP)","url":"https://www.hcp.ma/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MA', 1, 'bank_deposit_avg_rate', 0.0268, NULL, 'sourced', 'World Bank WDI, deposit interest rate (FR.INR.DPST), Morocco', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=MA', '2025-12-31', '2.68% average for 2025; Bank Al-Maghrib''s 12-month term-deposit average was 2.56% in September 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MA', 1, 'credit_card_rate_cap', 0.1321, NULL, 'sourced', 'Bank Al-Maghrib, maximum conventional interest rate (TMIC), 1 April 2026-31 March 2027', 'https://www.bkam.ma/Marches/Taux-d-interet/Taux-maximum-des-interets-conventionnels', '2026-04-01', 'Legal ceiling on conventional lending rates, including credit cards, for April 2026 to March 2027 (13.36% the year before).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MA', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'Bank Al-Maghrib''s customer-protection page confirms a collective deposit guarantee fund (managed by SGFG) with a maximum per depositor, but gives no amount, and the SGFG site refused access.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MA', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No industry-wide rate for a monthly recurring deposit product was found in Bank Al-Maghrib statistics; banks offer housing and education savings plans instead.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MA', 1, 'equity_return_base', 0.065, NULL, 'assumption', 'Bank Al-Maghrib Treasury reference curve (10-year 3.68%, about 2.6% after the 30% tax)', 'https://www.bkam.ma/Marches/Principaux-indicateurs/Marche-obligataire/Marche-des-bons-de-tresor/Marche-secondaire/Taux-de-reference-des-bons-du-tresor', '2026-10-31', 'Base case: about 4 points above the after-tax 10-year Treasury yield, the cap for this premium; the MASI has a moderate 10-year record with strong gains only since 2024.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MA', 1, 'equity_return_high', 0.1, NULL, 'assumption', 'Bank Al-Maghrib Treasury reference curve', 'https://www.bkam.ma/Marches/Principaux-indicateurs/Marche-obligataire/Marche-des-bons-de-tresor/Marche-secondaire/Taux-de-reference-des-bons-du-tresor', '2026-10-31', 'High case: the MASI repeats a strong decade similar to 2024-2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MA', 1, 'equity_return_low', 0.03, NULL, 'assumption', 'Bank Al-Maghrib Treasury reference curve (10-year about 3.7%)', 'https://www.bkam.ma/Marches/Principaux-indicateurs/Marche-obligataire/Marche-des-bons-de-tresor/Marche-secondaire/Taux-de-reference-des-bons-du-tresor', '2026-10-31', 'Low case: equities return about the Treasury bond yield, as in the weak MASI years of 2018-2022.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MA', 1, 'fdr_1y_rate', 0.0256, NULL, 'sourced', 'Bank Al-Maghrib, weighted average rates on term deposits, 12 months, September 2026', 'https://www.bkam.ma/Marches/Taux-d-interet/Taux-des-depots-a-terme', '2026-09-30', 'Weighted average rate on 12-month term deposits and certificates of deposit, 2.56% in September 2026 (2.65% in August); 6-month 2.21%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MA', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Bank Al-Maghrib publishes average term-deposit rates only for 6 and 12 months (6-month: 2.21% in September 2026); no 3-month figure was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MA', 1, 'fixed_income_return_base', 0.0175, NULL, 'assumption', 'Bank Al-Maghrib, 12-month term deposits 2.56% (September 2026), taxed at 30%', 'https://www.bkam.ma/Marches/Taux-d-interet/Taux-des-depots-a-terme', '2026-10-31', 'Base case: the 12-month deposit rate after the 30% tax on interest (2.56% x 0.7 = 1.79%), rounded down.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MA', 1, 'fixed_income_return_high', 0.026, NULL, 'assumption', 'Bank Al-Maghrib Treasury reference curve (10-year 3.68%), taxed at 30%', 'https://www.bkam.ma/Marches/Principaux-indicateurs/Marche-obligataire/Marche-des-bons-de-tresor/Marche-secondaire/Taux-de-reference-des-bons-du-tresor', '2026-10-31', 'High case: longer Treasury bonds or bond funds after the 30% tax (3.68% x 0.7 = 2.6%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MA', 1, 'fixed_income_return_low', 0.012, NULL, 'assumption', 'Bank Al-Maghrib, passbook savings rate 1.82% (H2 2026), taxed at 30%', 'https://www.bkam.ma/Marches/Taux-d-interet/Taux-des-comptes-sur-carnet', '2026-10-31', 'Low case: the passbook savings rate after the 30% tax on interest (1.82% x 0.7 = 1.3%), rounded down.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MA', 1, 'goal_inflation_education', 0.04, NULL, 'assumption', 'Bank Al-Maghrib inflation data (0.5% September 2026); inflation assumption 2%', 'https://www.bkam.ma/Statistiques/Prix/Inflation-et-inflation-sous-jacente', '2026-10-31', 'No education CPI was read; private school fees usually rise faster than general prices, so 2 points above the 2% inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MA', 1, 'goal_inflation_health', 0.035, NULL, 'assumption', 'Bank Al-Maghrib inflation data (0.5% September 2026); inflation assumption 2%', 'https://www.bkam.ma/Statistiques/Prix/Inflation-et-inflation-sous-jacente', '2026-10-31', 'No medical CPI was read; private medical costs usually rise faster than general prices, so 1.5 points above the 2% inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MA', 1, 'gold_return_base', 0.045, NULL, 'assumption', 'Bank Al-Maghrib reference exchange rate; World Bank official exchange rate history', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=MA', '2026-10-31', 'Base case: the long-run dollar gold trend of about 4% a year plus a little dirham weakness, since the dirham is managed against a euro-dollar basket within a narrow band.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MA', 1, 'gold_return_high', 0.08, NULL, 'assumption', 'Bank Al-Maghrib reference exchange rate; World Bank official exchange rate history', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=MA', '2026-10-31', 'High case: strong dollar gold years.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MA', 1, 'gold_return_low', 0, NULL, 'assumption', 'Bank Al-Maghrib reference exchange rate (9.81 MAD per USD)', 'https://www.bkam.ma/Marches/Principaux-indicateurs/Marche-des-changes/Cours-de-change/Cours-de-reference', '2026-10-31', 'Low case: flat dollar gold and a stable dirham.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MA', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Labour Code provides a severance indemnity on dismissal, but no official text giving an end-of-service benefit on retirement or resignation could be read; the Labour Ministry and CNSS sites could not be reached.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MA', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a major private hospital stay was found; AMO reimburses 70-90% of the national reference tariff (CLEISS 2024).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MA', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premiums by age were found from a public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MA', 1, 'inflation_cpi', 0.005, NULL, 'sourced', 'Bank Al-Maghrib, inflation and core inflation (HCP consumer price index), September 2026', 'https://www.bkam.ma/Statistiques/Prix/Inflation-et-inflation-sous-jacente', '2026-09-30', 'Consumer prices up 0.5% year on year in September 2026 (-0.3% in August); average 0.3% over the first nine months of 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MA', 1, 'inflation_projection', 0.02, NULL, 'assumption', 'Bank Al-Maghrib inflation data; World Bank CPI inflation 2021-2025', 'https://www.bkam.ma/Statistiques/Prix/Inflation-et-inflation-sous-jacente', '2026-10-31', 'Inflation averaged about 3% over 2021-2025 (two high years in 2022-2023, below 1% in 2024-2026) and the central bank steers toward about 2%, so 2% a year is used for long-range plans.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MA', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Temporary death cover (assurance temporaire décès) is sold, but no published premium rates per 1,000 MAD of cover by age were found from ACAPS or another public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MA', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'ACAPS (the insurance regulator) publishes sector statistics (first half 2026) but no industry-wide life claim settlement ratio was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MA', 1, 'life_expectancy', 75.493, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN), Morocco', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=MA', '2024-12-31', '75.5 years in 2024 (men 73.3, women 77.8).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MA', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":20.2,"men":18.5,"women":21.9},{"age":65,"total":16.2,"men":14.8,"women":17.7},{"age":70,"total":12.7,"men":11.4,"women":13.9},{"age":80,"total":6.9,"men":6.2,"women":7.6}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/morocco/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MA', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'Eligibility rules of the direct social aid programme for older people could not be read from an official source (asd.ma not reachable).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MA', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'The direct social aid programme (ASD, since December 2023) supports poor households including older members, but its site could not be reached and no official current amount for an older person could be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MA', 1, 'oop_health_share', 0.3725, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), Morocco', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=MA', '2023-12-31', '37.3% in 2023 (WHO Global Health Expenditure Database via the World Bank); older than 2025, the latest available, and before compulsory health insurance (AMO) was fully generalised.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MA', 1, 'policy_rate', 0.0225, NULL, 'sourced', 'Trading Economics, citing Bank Al-Maghrib monetary policy decision of 22 September 2026', 'https://tradingeconomics.com/morocco/interest-rate', '2026-09-22', 'Key rate held at 2.25% for the sixth meeting in a row; Bank Al-Maghrib''s decision history (bkam.ma) shows 2.25% since March 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MA', 1, 'public_pension_scheme', NULL, '{"pensionFromAge":60,"entryAgeMin":null,"entryAgeMax":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'CLEISS (French social security liaison body), the Moroccan social security system: CNSS old-age pension', 'https://www.cleiss.fr/docs/regimes/regime_maroc.html', '2024-09-09', 'Compulsory CNSS pension for private employees: 50% of the average capped wage of the last 96 months after 3,240 insured days, plus 1% per extra 216 days up to 70%; wage ceiling 6,000 MAD a month (maximum pension 4,200), minimum pension 1,000 MAD. No automatic indexation is described. Source is 2024 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MA', 1, 'retirement_accumulation_return_base', 0.045, NULL, 'assumption', 'Bank Al-Maghrib Treasury reference curve; equity base 6.5%; gold base 4.5%', 'https://www.bkam.ma/Marches/Principaux-indicateurs/Marche-obligataire/Marche-des-bons-de-tresor/Marche-secondaire/Taux-de-reference-des-bons-du-tresor', '2026-10-31', 'Base case: a balanced mix of deposits or bond funds, equity funds and some gold.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MA', 1, 'retirement_accumulation_return_high', 0.065, NULL, 'assumption', 'Bank Al-Maghrib Treasury reference curve; equity high 10%', 'https://www.bkam.ma/Marches/Principaux-indicateurs/Marche-obligataire/Marche-des-bons-de-tresor/Marche-secondaire/Taux-de-reference-des-bons-du-tresor', '2026-10-31', 'High case: a growth-leaning mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MA', 1, 'retirement_accumulation_return_low', 0.025, NULL, 'assumption', 'Bank Al-Maghrib deposit and Treasury rates', 'https://www.bkam.ma/Marches/Taux-d-interet/Taux-des-depots-a-terme', '2026-10-31', 'Low case: a mix earning a little above after-tax deposit rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MA', 1, 'retirement_age_default', 60, NULL, 'sourced', 'CLEISS (French social security liaison body), the Moroccan social security system: CNSS old-age pension', 'https://www.cleiss.fr/docs/regimes/regime_maroc.html', '2024-09-09', 'CNSS old-age pension at 60 with at least 3,240 insured days (55 for miners); a 2026 reform that might raise ages is stalled. Source is 2024 (older than 2025); the CNSS site could not be reached.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MA', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'The civil-service pension fund (CMR) and Finance Ministry pages could not be reached, so the current age limit for civil servants could not be confirmed; an April 2026 press review (le360.ma) says raising it to 65 is one option of a stalled reform.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MA', 1, 'retirement_return_base', 0.0175, NULL, 'assumption', 'Bank Al-Maghrib, 12-month term deposits 2.56% (September 2026), taxed at 30%', 'https://www.bkam.ma/Marches/Taux-d-interet/Taux-des-depots-a-terme', '2026-10-31', 'Base case: the after-tax 12-month deposit rate (2.56% x 0.7 = 1.79%), rounded down so it stays at or below the after-tax safe rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MA', 1, 'retirement_return_high', 0.025, NULL, 'assumption', 'Bank Al-Maghrib Treasury reference curve, taxed at 30%', 'https://www.bkam.ma/Marches/Principaux-indicateurs/Marche-obligataire/Marche-des-bons-de-tresor/Marche-secondaire/Taux-de-reference-des-bons-du-tresor', '2026-10-31', 'High case: part of the money in longer Treasury bonds or bond funds after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MA', 1, 'retirement_return_low', 0.012, NULL, 'assumption', 'Bank Al-Maghrib, passbook savings rate 1.82%, taxed at 30%', 'https://www.bkam.ma/Marches/Taux-d-interet/Taux-des-comptes-sur-carnet', '2026-10-31', 'Low case: savings accounts after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MA', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate or retail savings bond for individuals was found; Treasury bonds are auctioned by the Treasury through Bank Al-Maghrib to banks and institutions.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MA', 1, 'savings_account_rate', 0.0182, NULL, 'sourced', 'Bank Al-Maghrib, rate on savings passbook accounts (comptes sur carnet), 1 July-31 December 2026', 'https://www.bkam.ma/Marches/Taux-d-interet/Taux-des-comptes-sur-carnet', '2026-07-01', 'Regulated rate for passbook savings accounts for the second half of 2026 (1.61% in the first half); set every six months by Bank Al-Maghrib.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MA', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":7.85},{"year":2040,"value":5.18},{"year":2065,"value":2.92}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/morocco/2040/', '2025-12-31', '100 / old-age dependency ratio: 12.74 (2025, World Bank), 19.3 (2040) and 34.3 (2065, populationpyramid.net/morocco/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MA', 1, 'tax_bank_interest', 0.3, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Morocco, individual income determination (investment income)', 'https://taxsummaries.pwc.com/morocco/individual/income-determination', '2025-12-31', 'Interest earned by individuals (other than those taxed under the real or simplified business regime) is taxed at 30%; PwC shows the 2025 rate, no 2026 change was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MA', 1, 'tax_sanchayapatra_profit', 0.3, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Morocco, individual income determination (investment income)', 'https://taxsummaries.pwc.com/morocco/individual/income-determination', '2025-12-31', 'No savings certificate exists; interest on fixed-income instruments such as Treasury bonds is taxed at 30% for individuals (2025 rate).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MA', 1, 'tbill_91d_rate', 0.0217, NULL, 'sourced', 'Bank Al-Maghrib, reference rates of Treasury bonds (secondary market), 30 October 2026', 'https://www.bkam.ma/Marches/Principaux-indicateurs/Marche-obligataire/Marche-des-bons-de-tresor/Marche-secondaire/Taux-de-reference-des-bons-du-tresor', '2026-10-30', 'Weighted average rate of the Treasury line maturing 18 January 2027 (about 11 weeks to run), the shortest line in the reference curve.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MA', 1, 'tbond_10y_rate', 0.0368, NULL, 'sourced', 'Bank Al-Maghrib, reference rates of Treasury bonds (secondary market), 30 October 2026', 'https://www.bkam.ma/Marches/Principaux-indicateurs/Marche-obligataire/Marche-des-bons-de-tresor/Marche-secondaire/Taux-de-reference-des-bons-du-tresor', '2026-10-30', 'Interpolated between the lines maturing June 2035 (3.52%) and July 2039 (4.01%); the curve is published by maturity date, not by tenor.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MA', 1, 'tbond_5y_rate', 0.0309, NULL, 'sourced', 'Bank Al-Maghrib, reference rates of Treasury bonds (secondary market), 30 October 2026', 'https://www.bkam.ma/Marches/Principaux-indicateurs/Marche-obligataire/Marche-des-bons-de-tresor/Marche-secondaire/Taux-de-reference-des-bons-du-tresor', '2026-10-30', 'Interpolated between the lines maturing April 2030 (2.88%) and April 2032 (3.15%); the curve is published by maturity date, not by tenor.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('MC', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"MC","iso3":"MCO","nameEn":"Monaco","nameNative":"Monaco","region":"europe_central_asia","languages":["fr","it","en"],"currency":{"code":"EUR","symbol":"€","decimals":2,"compact":"intl","usdRate":{"value":0.8951,"status":"sourced","sourceName":"European Central Bank euro reference rate (USD)","sourceUrl":"https://www.ecb.europa.eu/stats/policy_and_exchange_rates/euro_reference_exchange_rates/html/eurofxref-graph-usd.en.html","asOf":"2026-10-30","note":"USD 1.1172 per euro on 30 October 2026, i.e. EUR 0.8951 per US dollar; World Bank 2025 average 0.885."}},"instruments":{"savings_account":{"available":true,"localName":"Compte sur livret","localNameEn":"Savings account","note":"Rates are set by each bank; no published average for Monaco."},"fdr_3m":{"available":true,"localName":"Compte à terme","localNameEn":"Term deposit (3 months)"},"fdr_1y":{"available":true,"localName":"Compte à terme","localNameEn":"Term deposit (1 year)"},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No standard recurring-deposit product was identified."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"Monaco has no public debt and sells no savings certificates.","sourceUrl":"https://www.gouv.mc/en/policy-practice/ensuring-economic-policy-is-fit-for-the-challenges-ahead/defining-and-managing-the-national-budget-strategy"},"tbill_91d":{"available":false,"localName":null,"localNameEn":null,"note":"Monaco issues no treasury bills (no public debt).","sourceUrl":"https://www.gouv.mc/en/policy-practice/ensuring-economic-policy-is-fit-for-the-challenges-ahead/defining-and-managing-the-national-budget-strategy"},"tbond_5y":{"available":false,"localName":null,"localNameEn":null,"note":"Monaco issues no government bonds (no public debt); residents can buy euro-area government bonds.","sourceUrl":"https://www.gouv.mc/en/policy-practice/ensuring-economic-policy-is-fit-for-the-challenges-ahead/defining-and-managing-the-national-budget-strategy"},"tbond_10y":{"available":false,"localName":null,"localNameEn":null,"note":"Monaco issues no government bonds (no public debt).","sourceUrl":"https://www.gouv.mc/en/policy-practice/ensuring-economic-policy-is-fit-for-the-challenges-ahead/defining-and-managing-the-national-budget-strategy"},"equity_fund":{"available":true,"localName":"OPCVM / fonds d''investissement","localNameEn":"Investment funds (UCITS)","note":"No local stock exchange; diversified euro and global funds are available through banks."},"gold":{"available":true,"localName":"Lingots et pièces d''or","localNameEn":"Gold bars and coins","note":"Legal to buy and hold."}},"institutions":{"centralBank":{"name":"European Central Bank (Monaco uses the euro)","url":"https://www.ecb.europa.eu/"},"insuranceRegulator":{"name":"Government of Monaco, insurance approvals (Business Development Agency)","url":"https://monentreprise.gouv.mc/en/themes/sector-specific-or-regulated-activities/regulations-approvals-and-declarations/approvals/how-to-obtain-approval-for-an-insurance-business","note":"Insurers need Monaco government approval to extend their French (ACPR) licence to the Principality."},"insuranceComplaints":null,"pensionScheme":{"name":"Caisses Sociales de Monaco, Caisse Autonome des Retraites (CAR)","url":"https://www.caisses-sociales.mc/accueil/retraite-car"},"oldAgeAllowance":{"name":"Department of Social Welfare (DASO), monthly retirement allowance","url":"https://monservicepublic.gouv.mc/en/themes/social-health-and-families/aid/retired-and-elderly-people/how-to-apply-for-a-monthly-retirement-allowance"},"publicHealthCover":{"name":"Caisses Sociales de Monaco, Caisse de Compensation des Services Sociaux (CCSS)","url":"https://www.caisses-sociales.mc/"},"depositInsurance":{"name":"Fonds de Garantie des Dépôts et de Résolution (FGDR), covering banks headquartered in Monaco","url":"https://www.garantiedesdepots.fr/en/check-if-my-bank-protected"},"statistics":{"name":"Monaco Statistics (IMSEE)","url":"https://imsee.mc/en"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MC', 1, 'bank_deposit_avg_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Monaco has no central bank or deposit-rate statistics of its own; banks follow French banking law but no published average rate for Monaco-based banks was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MC', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No source stating a legal cap or typical credit card rate for Monaco was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MC', 1, 'deposit_insurance_limit', 100000, NULL, 'sourced', 'French Deposit Guarantee and Resolution Fund (FGDR), which covers banks headquartered in Monaco', 'https://www.garantiedesdepots.fr/en/check-if-my-bank-protected', '2026-10-31', 'EUR 100,000 per customer per bank; the FGDR covers banks whose head office is in the Principality of Monaco.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MC', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No recurring-deposit product or published rate was found for Monaco.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MC', 1, 'equity_return_base', 0.06, NULL, 'assumption', 'Global equity long-run return about 6-7% in EUR; ECB deposit rate 2.5% (no tax on interest for residents)', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.en.html', '2026-10-31', 'Monaco has no stock exchange, so the base is a global index fund in euros, kept within about 3.5 points of the 2.5% euro safe rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MC', 1, 'equity_return_high', 0.085, NULL, 'assumption', 'Global equity long-run returns in EUR', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.en.html', '2026-10-31', 'High case: strong global equity returns over the long run.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MC', 1, 'equity_return_low', 0.03, NULL, 'assumption', 'No local stock market; global equities in EUR; ECB deposit rate 2.5%', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.en.html', '2026-10-31', 'Low case: global shares return only a little above euro deposits over the long run.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MC', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No official statistics on 1-year term deposit rates in Monaco were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MC', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No official statistics on 3-month term deposit rates in Monaco were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MC', 1, 'fixed_income_return_base', 0.025, NULL, 'assumption', 'ECB deposit facility rate 2.5% (Sep 2026); no tax on interest', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.en.html', '2026-10-31', 'Base case: euro deposits and money funds earn about the ECB deposit rate, untaxed in Monaco.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MC', 1, 'fixed_income_return_high', 0.035, NULL, 'assumption', 'ECB deposit facility rate 2.5%; euro-area bond yields', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.en.html', '2026-10-31', 'High case: euro rates stay higher and savers lock in longer euro-area government bonds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MC', 1, 'fixed_income_return_low', 0.015, NULL, 'assumption', 'ECB deposit facility rate 2.5% (Sep 2026); no tax on interest for non-French residents', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.en.html', '2026-10-31', 'Low case: euro rates fall back toward 1.5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MC', 1, 'goal_inflation_education', 0.035, NULL, 'assumption', 'ECB 2% target; private and international school fees', 'https://www.insee.fr/fr/statistiques/9080209', '2026-10-31', 'No education price index exists for Monaco; private and international school fees usually rise faster than general prices, so 3.5% is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MC', 1, 'goal_inflation_health', 0.03, NULL, 'assumption', 'INSEE CPI Sep 2026: health services +0.8%, health products -2.3% year on year; ECB 2% target', 'https://www.insee.fr/fr/statistiques/9080209', '2026-10-31', 'Private medical costs in Monaco tend to rise faster than the 2% target, so 3% is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MC', 1, 'gold_return_base', 0.045, NULL, 'assumption', 'Gold price history (Trading Economics); ECB 2% target', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Base case: gold rises about 4.5% a year in euros, a little above inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MC', 1, 'gold_return_high', 0.08, NULL, 'assumption', 'Gold price history (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'High case: a repeat of gold''s strong 2005-2025 trend in euros.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MC', 1, 'gold_return_low', 0.01, NULL, 'assumption', 'Gold price history (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Low case: gold roughly flat after the 2025-26 spike, with a stable euro.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MC', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No statutory end-of-service gratuity per year of service was found; Monaco labour law provides dismissal indemnities, but the text could not be read to confirm other rules.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MC', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'Employees are covered by the CCSS health insurance fund; no official figure for the out-of-pocket cost of a major hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MC', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published table of private (top-up) health insurance premiums per EUR 100,000 of cover was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MC', 1, 'inflation_cpi', 0.031, NULL, 'sourced', 'INSEE consumer price index for France, September 2026 (French indices are the ones used in Monaco, per IMSEE)', 'https://www.insee.fr/fr/statistiques/9080209', '2026-09-30', 'Monaco publishes no consumer price index of its own; IMSEE''s ''Monaco en Chiffres'' lists the INSEE French CPI among the main French indices used in the Principality. French CPI +3.1% year on year (final, published 15 October 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MC', 1, 'inflation_projection', 0.02, NULL, 'assumption', 'European Central Bank 2% inflation target (Monaco uses the euro)', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.en.html', '2026-10-31', 'Monaco uses the euro under an agreement with the EU, so the ECB''s credible 2% medium-term target is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MC', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life cover is sold in Monaco (mainly by insurers approved under French rules), but no published premium table per EUR 1,000 of cover by age was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MC', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Insurers in Monaco are mostly French insurers approved by the Monaco government; no Monaco life claim settlement ratio is published.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MC', 1, 'life_expectancy', 86.7, NULL, 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/monaco', '2026-07-01', 'Men 84.8, women 88.8 (UN WPP estimate for the year 2026, dated mid-year); World Bank 2024 figure 86.5.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MC', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":28.1,"men":26.3,"women":30},{"age":65,"total":23.5,"men":21.8,"women":25.3},{"age":70,"total":19.1,"men":17.6,"women":20.8},{"age":80,"total":11.5,"men":10.3,"women":12.7}]}', 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/monaco', '2026-07-01', 'Remaining years computed from georank''s expected age at death by current age (UN WPP 2026 estimate).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MC', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":65,"womenAge":65,"over90Monthly":null,"meansTested":true}', 'sourced', 'Monaco public service portal: how to apply for a monthly retirement allowance (updated 11 November 2025)', 'https://monservicepublic.gouv.mc/en/themes/social-health-and-families/aid/retired-and-elderly-people/how-to-apply-for-a-monthly-retirement-allowance', '2025-11-11', 'Monthly retirement allowance (AMR) for non-Monegasques aged over 65 (60 if unfit for work) with at least 5 years'' continuous residence and household income below a yearly threshold; Monegasque nationals over 60 on a low income get the national old-age allowance from the Town Hall social services.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MC', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'Monaco pays a means-tested monthly retirement allowance (AMR) to non-Monegasque residents aged 65+ and a national old-age allowance to low-income Monegasques aged 60+, but the 2026 amounts (set by ministerial decree) could not be found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MC', 1, 'oop_health_share', 0.0845, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=MC', '2023-12-31', 'Latest available year is 2023 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MC', 1, 'policy_rate', 0.025, NULL, 'sourced', 'European Central Bank key interest rates (deposit facility rate)', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.en.html', '2026-09-16', 'Monaco uses the euro; the ECB deposit facility rate has been 2.50% since 16 September 2026 (main refinancing 2.65%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MC', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":65,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":true}', 'sourced', 'Caisses Sociales de Monaco, CAR direct pension; Monaco public service portal (tax)', 'https://www.caisses-sociales.mc/accueil/retraite-car/retraite-car/pension-car/pension-directe', '2026-10-01', 'Mandatory points-based basic pension (CAR) for private-sector employees plus the supplementary CMRC scheme; monthly pension = points x annual point value (EUR 22.27 from 1 October 2026) / 12, revalued by ministerial order rather than automatic indexation; +1.5% per quarter deferred after 65 (max 30%). Residents other than French nationals pay no income tax on it.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MC', 1, 'retirement_accumulation_return_base', 0.045, NULL, 'assumption', 'Euro safe rate 2.5%; global equity in EUR 6%', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.en.html', '2026-10-31', 'Base case: roughly half euro fixed income and half global shares.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MC', 1, 'retirement_accumulation_return_high', 0.06, NULL, 'assumption', 'Euro bonds 3.5%; global equity high case 8.5%', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.en.html', '2026-10-31', 'High case for a growth-leaning mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MC', 1, 'retirement_accumulation_return_low', 0.025, NULL, 'assumption', 'Euro safe rate 2.5%; global equity low case 3%', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.en.html', '2026-10-31', 'Low case for a balanced mix if shares and rates both disappoint.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MC', 1, 'retirement_age_default', 65, NULL, 'sourced', 'Caisses Sociales de Monaco, CAR direct pension', 'https://www.caisses-sociales.mc/accueil/retraite-car/retraite-car/pension-car/pension-directe', '2026-10-31', 'Legal retirement age 65; a CAR pension can be taken from 60 without reduction once all work has stopped, and from 55 for mothers who raised three children; at least 10 years of activity are required.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MC', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'Civil service pensions are governed by Law 1.049 of 1982 and Law 975 of 1975, but no current text stating the retirement age limit for State employees could be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MC', 1, 'retirement_return_base', 0.02, NULL, 'assumption', 'ECB deposit facility rate 2.5% (Sep 2026); no tax on interest for residents', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.en.html', '2026-10-31', 'Base case kept below the 2.5% euro safe rate, since Monaco has no government bills and banks pay less than the ECB rate on many deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MC', 1, 'retirement_return_high', 0.03, NULL, 'assumption', 'ECB deposit facility rate 2.5%; euro-area bond yields', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.en.html', '2026-10-31', 'High case: savers hold longer euro-area government bonds at about 3%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MC', 1, 'retirement_return_low', 0.01, NULL, 'assumption', 'ECB deposit facility rate 2.5% (Sep 2026)', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.en.html', '2026-10-31', 'Low case: euro deposit rates fall back toward 1%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MC', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Monaco has no public debt, so the State sells no savings certificates or retail bonds (Government of Monaco, national budget strategy page: https://www.gouv.mc/en/policy-practice/ensuring-economic-policy-is-fit-for-the-challenges-ahead/defining-and-managing-the-national-budget-strategy).', 1);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MC', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Monaco has no national statistics on bank deposit rates and banks there are mostly private banks; no official average savings rate for Monaco was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MC', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":1.39}]}', 'sourced', 'World Bank SP.POP.DPND.OL', 'https://data.worldbank.org/indicator/SP.POP.DPND.OL?locations=MC', '2025-12-31', '100 / old-age dependency ratio 71.7 (2025); no UN WPP projection for 2040 or 2065 could be read (populationpyramid.net has no Monaco page).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MC', 1, 'tax_bank_interest', 0, NULL, 'sourced', 'Monaco public service portal: tax in Monaco', 'https://monservicepublic.gouv.mc/en/themes/tax/information/general-information/tax-in-monaco', '2026-10-31', 'Residents genuinely established in Monaco pay no personal income tax, so bank interest is untaxed; French nationals resident in Monaco remain taxable in France under the 1963 convention.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MC', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'Not applicable: Monaco has no public debt and issues no government savings certificates (gouv.mc national budget strategy page: https://www.gouv.mc/en/policy-practice/ensuring-economic-policy-is-fit-for-the-challenges-ahead/defining-and-managing-the-national-budget-strategy); residents other than French nationals pay no income tax in any case.', 1);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MC', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Monaco has no public debt and issues no treasury bills (Government of Monaco, national budget strategy page).', 1);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MC', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Monaco has no public debt and issues no government bonds (Government of Monaco, national budget strategy page).', 1);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MC', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Monaco has no public debt and issues no government bonds (Government of Monaco, national budget strategy page).', 1);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('MD', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"MD","iso3":"MDA","nameEn":"Moldova","nameNative":"Republica Moldova","region":"europe_central_asia","languages":["ro","ru","uk","bg","gag"],"currency":{"code":"MDL","symbol":"L","decimals":2,"compact":"intl","usdRate":{"value":18.0365,"status":"sourced","sourceName":"National Bank of Moldova official exchange rate","sourceUrl":"https://www.bnm.md/en/official_exchange_rates?get_xml=1&date=31.10.2026","asOf":"2026-10-31","note":"MDL 18.0365 per US dollar on 31 October 2026 (EUR 20.0954); World Bank 2025 average 17.38."}},"instruments":{"savings_account":{"available":true,"localName":"Depozit la vedere / cont de economii","localNameEn":"Demand (savings) deposit","note":"Interest-bearing demand deposits pay under 1%.","sourceUrl":"https://www.bnm.md/ro/print/content/evolutia-pietei-depozitelor-bancare-luna-septembrie-2026"},"fdr_3m":{"available":true,"localName":"Depozit la termen","localNameEn":"Term deposit (1-3 months)","sourceUrl":"https://www.bnm.md/bdi/pages/reports/dpmc/DPMC9.xhtml"},"fdr_1y":{"available":true,"localName":"Depozit la termen","localNameEn":"Term deposit (6-12 months)","sourceUrl":"https://www.bnm.md/bdi/pages/reports/dpmc/DPMC9.xhtml"},"dps":{"available":true,"localName":"Depozit cu posibilitate de completare","localNameEn":"Term deposit with regular top-ups","note":"Terms vary by bank; no published average rate."},"sanchayapatra_5y":{"available":true,"localName":"Obligațiuni de stat pentru persoane fizice (eVMS)","localNameEn":"Government bonds for individuals (eVMS platform)","note":"Fixed-rate bonds of 1-4 years sold directly to individuals by the Ministry of Finance every two weeks through the eVMS platform; interest is tax-exempt.","sourceUrl":"https://mf.gov.md/sites/default/files/Comunicat%20spre%20plasare%20a%20VMS%20prin%20subscriere%2019.10.2026-02.11.2026.pdf"},"tbill_91d":{"available":true,"localName":"Bonuri de trezorerie","localNameEn":"Treasury bills","note":"91-, 182- and 364-day bills auctioned by the Ministry of Finance through the National Bank.","sourceUrl":"https://mf.gov.md/sites/default/files/Rezultatele%20licitatie%2013-10-2026%20-%20rom.pdf"},"tbond_5y":{"available":true,"localName":"Obligațiuni de stat","localNameEn":"Government bonds (5 years)","sourceUrl":"https://mf.gov.md/sites/default/files/Rezultatele%20licitatie%2012-08-2026%20-%20rom.pdf"},"tbond_10y":{"available":true,"localName":"Obligațiuni de stat","localNameEn":"Government bonds (10 years)","note":"Issued rarely; reopened in June 2026.","sourceUrl":"https://mf.gov.md/sites/default/files/Rezultatele%20licitatie%2010-06-2026%20-%20rom.pdf"},"equity_fund":{"available":false,"localName":null,"localNameEn":null,"note":"No domestic diversified retail mutual or index funds were found; the local stock exchange is very small."},"gold":{"available":true,"localName":"Lingouri și monede din aur","localNameEn":"Gold bars and coins","note":"Legal to buy and hold."}},"institutions":{"centralBank":{"name":"National Bank of Moldova","url":"https://www.bnm.md/en"},"insuranceRegulator":{"name":"National Bank of Moldova (insurance supervision since 1 July 2023)","url":"https://www.bnm.md/en/content/international-association-insurance-supervisors-iais"},"insuranceComplaints":{"name":"National Commission for Financial Markets (CNPF), consumer complaints about insurers (explained on the National Bank of Moldova page)","url":"https://www.bnm.md/ro/content/unde-te-adresezi-cand-ti-se-incalca-dreptul-de-consumator-al-serviciilor-financiare","note":"The National Bank supervises insurers since July 2023, but consumer complaints about insurers and insurance intermediaries go to the CNPF."},"pensionScheme":{"name":"National Social Insurance House (CNAS)","url":"https://cnas.gov.md/"},"oldAgeAllowance":{"name":"National Social Insurance House (CNAS), state social allowances","url":"https://cnas.gov.md/"},"publicHealthCover":{"name":"National Health Insurance Company (CNAM), mandatory health insurance","url":"https://cnam.md/"},"depositInsurance":{"name":"Deposit Guarantee Fund in the Banking System (FGDSB)","url":"https://fgdsb.md/pentru-deponenti/"},"statistics":{"name":"National Bureau of Statistics of the Republic of Moldova","url":"https://statistica.gov.md/en"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MD', 1, 'bank_deposit_avg_rate', 0.0611, NULL, 'sourced', 'National Bank of Moldova, bank deposit market in September 2026 (average rate on new term deposits of individuals, MDL)', 'https://www.bnm.md/ro/print/content/evolutia-pietei-depozitelor-bancare-luna-septembrie-2026', '2026-09-30', 'Weighted average on all new lei term deposits of individuals 6.11% in September 2026 (also in BNM report DPMC9); World Bank FR.INR.DPST 2025 average 4.76%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MD', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'Reports describe a draft law capping consumer-credit interest at 50% a year in lei, but it could not be confirmed as in force and no typical credit card rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MD', 1, 'deposit_insurance_limit', 200000, NULL, 'sourced', 'Deposit Guarantee Fund in the Banking System (FGDSB), information for depositors', 'https://fgdsb.md/pentru-deponenti/', '2026-10-31', 'MDL 200,000 per depositor per bank since 1 January 2025 (Law 160/2023), regardless of currency.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MD', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Banks offer term deposits that accept regular top-ups, but BNM does not publish a rate for monthly recurring deposits and no official figure was found; lei term deposits of 2-5 years averaged 6.26% in September 2026 (BNM).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MD', 1, 'equity_return_base', 0.085, NULL, 'assumption', 'Global equity long-run return about 7% in USD; MDL 18.04 per USD (BNM); inflation target 5% vs 2% in the US', 'https://www.bnm.md/en/official_exchange_rates?get_xml=1&date=31.10.2026', '2026-10-31', 'No local market to invest in, so the base is a global index fund in lei: about 7% in dollars plus about 1.5% a year of expected leu depreciation, within 4 points of the tax-free 1-year retail bond (7.65%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MD', 1, 'equity_return_high', 0.115, NULL, 'assumption', 'Global equity long-run returns; leu depreciation of 2005-2025', 'https://www.bnm.md/en/official_exchange_rates?get_xml=1&date=31.10.2026', '2026-10-31', 'High case: strong global equity returns plus faster leu depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MD', 1, 'equity_return_low', 0.04, NULL, 'assumption', 'No usable local stock index (Moldova Stock Exchange is tiny and illiquid); global equities in MDL', 'https://www.bnm.md/en/official_exchange_rates?get_xml=1&date=31.10.2026', '2026-10-31', 'Low case: global shares earn about 4% in dollars and the leu stays stable against the dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MD', 1, 'fdr_1y_rate', 0.0593, NULL, 'sourced', 'National Bank of Moldova, interactive database: weighted average rates on new deposits (individuals, MDL, 6 to 12 months), September 2026', 'https://www.bnm.md/bdi/pages/reports/dpmc/DPMC9.xhtml', '2026-09-30', 'Average rate on new lei term deposits of individuals with maturity of 6 to 12 months 5.93% in September 2026; 1-2 years 6.50% (BNM report DPMC9).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MD', 1, 'fdr_3m_rate', 0.0442, NULL, 'sourced', 'National Bank of Moldova, interactive database: weighted average rates on new deposits (individuals, MDL, 1 to 3 months), September 2026', 'https://www.bnm.md/bdi/pages/reports/dpmc/DPMC9.xhtml', '2026-09-30', 'Average rate on new lei term deposits of individuals with maturity of 1 to 3 months 4.42% in September 2026 (3-6 months 6.04%); figures shown after selecting monthly data, MDL, individuals in the BNM report DPMC9.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MD', 1, 'fixed_income_return_base', 0.065, NULL, 'assumption', 'Tax-free retail government bonds 7.65-8.05% (eVMS, Oct 2026); 1-year lei deposits 5.93% less 6% tax = 5.6%', 'https://mf.gov.md/sites/default/files/Comunicat%20spre%20plasare%20a%20VMS%20prin%20subscriere%2019.10.2026-02.11.2026.pdf', '2026-10-31', 'Base case: a mix of tax-free retail government bonds and deposits, allowing for some easing of rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MD', 1, 'fixed_income_return_high', 0.08, NULL, 'assumption', 'Tax-free retail government bonds 7.65-8.05% (eVMS, Oct 2026)', 'https://mf.gov.md/sites/default/files/Comunicat%20spre%20plasare%20a%20VMS%20prin%20subscriere%2019.10.2026-02.11.2026.pdf', '2026-10-31', 'High case: today''s tax-free retail bond rates hold.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MD', 1, 'fixed_income_return_low', 0.045, NULL, 'assumption', 'Lei deposits 5.4-5.9% less 6% tax (BNM, Sep 2026); BNM base rate 9%', 'https://www.bnm.md/ro/print/content/evolutia-pietei-depozitelor-bancare-luna-septembrie-2026', '2026-10-31', 'Low case: rates fall as inflation returns to the 5% target, leaving about 4.5% after tax on deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MD', 1, 'goal_inflation_education', 0.07, NULL, 'assumption', 'BNS CPI September 2026: education division +8.4% year on year', 'https://statistica.gov.md/en/consumer-price-indices-in-the-republic-of-moldova-in-september-9485_62673.html', '2026-10-31', 'Education prices are rising faster than headline inflation, so 7% is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MD', 1, 'goal_inflation_health', 0.055, NULL, 'assumption', 'BNS CPI September 2026: health division +3.2%, medicines +4.1%, medical services +2.0% year on year', 'https://statistica.gov.md/en/consumer-price-indices-in-the-republic-of-moldova-in-september-9485_62673.html', '2026-10-31', 'Health prices have recently risen slower than headline inflation, so the planning inflation rate of 5.5% is used rather than a premium.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MD', 1, 'gold_return_base', 0.055, NULL, 'assumption', 'Gold price history (Trading Economics); BNM 5% target vs 2% US inflation', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Base case: dollar gold rises about 4% a year and the leu loses about 1.5% a year against the dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MD', 1, 'gold_return_high', 0.09, NULL, 'assumption', 'Gold price history (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'High case: a repeat of gold''s strong 2005-2025 trend plus faster leu depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MD', 1, 'gold_return_low', 0.02, NULL, 'assumption', 'Gold price history (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Low case: gold barely keeps up after the 2025-26 spike and the leu stays stable.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MD', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No statutory end-of-service gratuity per year of service was found; the Labour Code provides severance pay only on dismissal for liquidation or redundancy, and the consolidated text could not be read to confirm other rules.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MD', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'Mandatory health insurance (CNAM) covers hospital care for the insured; no official figure for the out-of-pocket cost of a major private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MD', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Voluntary health insurance is sold as fixed packages; no published premium table per MDL 100,000 of cover by age was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MD', 1, 'inflation_cpi', 0.086, NULL, 'sourced', 'National Bureau of Statistics of Moldova, consumer price indices September 2026', 'https://statistica.gov.md/en/consumer-price-indices-in-the-republic-of-moldova-in-september-9485_62673.html', '2026-09-30', 'Consumer prices 8.6% higher than in September 2025 (index 108.60); World Bank 2025 average 7.8%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MD', 1, 'inflation_projection', 0.055, NULL, 'assumption', 'National Bank of Moldova inflation target 5% +/-1.5 points; CPI 8.6% (Sep 2026)', 'https://www.bnm.md/en/content/monetary-policy-decision-17092026', '2026-10-31', 'The target is 5%, but inflation has run above it in most recent years (very high in 2022 and 8.6% now), so 5.5% is used for planning.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MD', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Life insurance is a small market in Moldova (mostly credit-linked cover); no published premium table per MDL 1,000 of term cover by age was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MD', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The National Bank of Moldova (insurance supervisor since July 2023) publishes insurance market statistics, but no life claim settlement ratio was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MD', 1, 'life_expectancy', 71.6, NULL, 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/moldova', '2026-07-01', 'Men 67.0, women 75.9 (UN WPP estimate for the year 2026, dated mid-year); World Bank 2024 figure 71.3.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MD', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":18.1,"men":15.2,"women":20.2},{"age":65,"total":14.8,"men":12.4,"women":16.4},{"age":70,"total":11.7,"men":9.7,"women":12.9},{"age":80,"total":7,"men":5.4,"women":7.6}]}', 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/moldova', '2026-07-01', 'Remaining years computed from georank''s expected age at death by current age (UN WPP 2026 estimate).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MD', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":63,"womenAge":63,"over90Monthly":null,"meansTested":false}', 'sourced', 'CNAS state social allowances; CNAS old-age pension conditions (retirement ages)', 'https://cnas.gov.md/ro/servicii/servicii/alocatii/alocatii-sociale-de-stat', '2026-07-01', 'Paid from the standard retirement age to Moldovan citizens and legal residents who do not meet the conditions for a contributory pension; no income test is mentioned. Women''s age is 62 in 2026 and reaches 63 from July 2028, so 63 is used for anyone planning today.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MD', 1, 'old_age_allowance_monthly', 1632.33, NULL, 'sourced', 'CNAS state social allowances (50% of the minimum old-age pension); Moldpres: minimum old-age pension MDL 3,264.66 from 1 April 2026', 'https://cnas.gov.md/ro/servicii/servicii/alocatii/alocatii-sociale-de-stat', '2026-04-01', 'The state social allowance for elderly people who do not qualify for a contributory pension is 50% of the indexed minimum old-age pension (CNAS); the minimum is MDL 3,264.66 from 1 April 2026 (moldpres.md), giving MDL 1,632.33; it was MDL 1,527.83 at 1 January 2026 (CNAS beneficiaries report, 25,205 recipients).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MD', 1, 'oop_health_share', 0.2747, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=MD', '2023-12-31', 'Latest available year is 2023 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MD', 1, 'policy_rate', 0.09, NULL, 'sourced', 'National Bank of Moldova, monetary policy decision of 17 September 2026', 'https://www.bnm.md/en/content/monetary-policy-decision-17092026', '2026-09-17', 'Base rate raised from 7.5% to 9.00%; overnight deposit 7%, overnight loan 11%; next decision 5 November 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MD', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":63,"nomineeUntilAge":null,"inflationLinked":true,"taxFree":null}', 'sourced', 'Moldpres: pensions and social benefits indexed by 6.84% from 1 April 2026; CNAS', 'https://moldpres.md/eng/official/pensiile-si-prestatiile-sociale-vor-fi-indexate-cu-684-de-la-1-aprilie-2026-eng', '2026-04-01', 'Mandatory pay-as-you-go state social insurance pension (CNAS) from age 63 (women 62 in 2026, 63 from July 2028), indexed every 1 April (6.84% in 2026); minimum old-age pension MDL 3,264.66 from 1 April 2026 (MDL 3,525.72 with at least 40 years of contributions).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MD', 1, 'retirement_accumulation_return_base', 0.075, NULL, 'assumption', 'Tax-free retail government bonds about 7.7%; global equity in MDL 8.5%', 'https://mf.gov.md/sites/default/files/Comunicat%20spre%20plasare%20a%20VMS%20prin%20subscriere%2019.10.2026-02.11.2026.pdf', '2026-10-31', 'Base case: roughly half lei government bonds and deposits and half global shares in lei terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MD', 1, 'retirement_accumulation_return_high', 0.095, NULL, 'assumption', 'Retail government bonds 8%; global equity high case 11.5%', 'https://mf.gov.md/sites/default/files/Comunicat%20spre%20plasare%20a%20VMS%20prin%20subscriere%2019.10.2026-02.11.2026.pdf', '2026-10-31', 'High case for a growth-leaning mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MD', 1, 'retirement_accumulation_return_low', 0.05, NULL, 'assumption', 'After-tax lei fixed income 4.5-6.5%; global equity low case 4%', 'https://mf.gov.md/sites/default/files/Comunicat%20spre%20plasare%20a%20VMS%20prin%20subscriere%2019.10.2026-02.11.2026.pdf', '2026-10-31', 'Low case for a balanced mix if global shares lag and rates fall.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MD', 1, 'retirement_age_default', 63, NULL, 'sourced', 'National Social Insurance House (CNAS), old-age pension conditions', 'https://cnas.gov.md/ro/servicii/servicii/pensii/pensie-pentru-limita-de-varsta', '2026-07-01', 'Standard retirement age 63 for men; women 62 from 1 July 2026, 62 years 6 months from July 2027 and 63 from 1 July 2028, so 63 applies to everyone born after 1975; at least 15 years of contributions for a partial pension.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MD', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'Law 158/2008 on public office ends service on reaching the pension age, but court rulings and local decisions also cite ages 63 and 65 for continued service; no single official figure could be confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MD', 1, 'retirement_return_base', 0.06, NULL, 'assumption', '1-year lei deposits 5.93% less 6% tax = 5.6%; tax-free 1-year retail government bond 7.65% (eVMS)', 'https://mf.gov.md/sites/default/files/Comunicat%20spre%20plasare%20a%20VMS%20prin%20subscriere%2019.10.2026-02.11.2026.pdf', '2026-10-31', 'Base case kept below the tax-free 1-year retail government bond rate, assuming a mix with deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MD', 1, 'retirement_return_high', 0.075, NULL, 'assumption', 'Tax-free retail government bonds 7.65-8.05% (eVMS, Oct 2026)', 'https://mf.gov.md/sites/default/files/Comunicat%20spre%20plasare%20a%20VMS%20prin%20subscriere%2019.10.2026-02.11.2026.pdf', '2026-10-31', 'High case: today''s tax-free retail bond rates hold for the long run.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MD', 1, 'retirement_return_low', 0.045, NULL, 'assumption', 'Lei deposits 5.4-5.9% less 6% tax (BNM, Sep 2026)', 'https://www.bnm.md/ro/print/content/evolutia-pietei-depozitelor-bancare-luna-septembrie-2026', '2026-10-31', 'Low case: deposit and bond rates fall as inflation settles at the 5% target.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MD', 1, 'sanchayapatra_5y_rate', 0.0805, NULL, 'sourced', 'Ministry of Finance of Moldova, placement of government securities by subscription to individuals (eVMS), 19 Oct - 2 Nov 2026', 'https://mf.gov.md/sites/default/files/Comunicat%20spre%20plasare%20a%20VMS%20prin%20subscriere%2019.10.2026-02.11.2026.pdf', '2026-10-19', 'Longest retail bond offered is 4 years at a fixed 8.05% (1 year 7.65%, 2 years 7.75%, 3 years 7.85%), interest paid every six months; no 5-year retail bond is offered.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MD', 1, 'savings_account_rate', 0.009, NULL, 'sourced', 'National Bank of Moldova, bank deposit market in September 2026 (new interest-bearing demand deposits of individuals, MDL)', 'https://www.bnm.md/ro/print/content/evolutia-pietei-depozitelor-bancare-luna-septembrie-2026', '2026-09-30', 'Average nominal rate on new interest-bearing demand (sight) deposits of individuals in lei 0.90%; foreign currency 0.83%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MD', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":3.77},{"year":2040,"value":3.33},{"year":2065,"value":2.59}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/republic-of-moldova/2040/', '2025-12-31', '100 / old-age dependency ratio: 26.5 (2025, World Bank), 30.0 (2040) and 38.6 (2065, populationpyramid.net/republic-of-moldova/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MD', 1, 'tax_bank_interest', 0.06, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Moldova withholding taxes (reviewed 24 June 2026)', 'https://taxsummaries.pwc.com/moldova/corporate/withholding-taxes', '2026-06-24', '6% final withholding on interest paid to resident individuals by banks and savings and loan associations.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MD', 1, 'tax_sanchayapatra_profit', 0, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Moldova income determination (reviewed 24 June 2026)', 'https://taxsummaries.pwc.com/moldova/individual/income-determination', '2026-06-24', 'Interest on state securities and local government bonds earned by resident individuals is tax-exempt.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MD', 1, 'tbill_91d_rate', 0.0307, NULL, 'sourced', 'Ministry of Finance of Moldova, results of the government securities auction of 13 October 2026', 'https://mf.gov.md/sites/default/files/Rezultatele%20licitatie%2013-10-2026%20-%20rom.pdf', '2026-10-13', 'Weighted average 3.07% on a small 91-day issue (MDL 31 million), far below the 182-day (11.07%) and 364-day (11.70%) bills sold the same day, so it is not representative of short-term yields.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MD', 1, 'tbond_10y_rate', 0.08, NULL, 'sourced', 'Ministry of Finance of Moldova, results of the government securities auction of 10 June 2026', 'https://mf.gov.md/sites/default/files/Rezultatele%20licitatie%2010-06-2026%20-%20rom.pdf', '2026-06-10', 'Reopening of a 10-year bond (8.5 years left, maturing 13 December 2034) at 8.00%; no newer long-bond auction found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MD', 1, 'tbond_5y_rate', 0.0795, NULL, 'sourced', 'Ministry of Finance of Moldova, results of the government securities auction of 12 August 2026', 'https://mf.gov.md/sites/default/files/Rezultatele%20licitatie%2012-08-2026%20-%20rom.pdf', '2026-08-12', 'Fixed-rate 5-year bond maturing 14 August 2031 placed at 7.95%.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('ME', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"ME","iso3":"MNE","nameEn":"Montenegro","nameNative":"Crna Gora","region":"europe_central_asia","languages":["cnr","sr","bs","sq","en"],"currency":{"code":"EUR","symbol":"€","decimals":2,"compact":"intl","usdRate":{"value":0.8951,"status":"sourced","sourceName":"European Central Bank euro reference rate (USD)","sourceUrl":"https://www.ecb.europa.eu/stats/policy_and_exchange_rates/euro_reference_exchange_rates/html/eurofxref-graph-usd.en.html","asOf":"2026-10-30","note":"Montenegro uses the euro; USD 1.1172 per euro on 30 October 2026, i.e. EUR 0.8951 per US dollar; World Bank 2025 average 0.887."}},"instruments":{"savings_account":{"available":true,"localName":"Štedni račun / depozit po viđenju","localNameEn":"Savings (sight) deposit","note":"Sight deposits pay almost nothing (0.005% on average).","sourceUrl":"https://www.cbcg.me/en/statistics/statistical-data/interest-rates"},"fdr_3m":{"available":true,"localName":"Oročeni depozit","localNameEn":"Term deposit (up to 3 months)","sourceUrl":"https://www.cbcg.me/en/statistics/statistical-data/interest-rates"},"fdr_1y":{"available":true,"localName":"Oročeni depozit","localNameEn":"Term deposit (3 months to 1 year)","sourceUrl":"https://www.cbcg.me/en/statistics/statistical-data/interest-rates"},"dps":{"available":true,"localName":"Namjenska štednja","localNameEn":"Savings plan with regular deposits","note":"Terms vary by bank; no published average rate."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate or retail savings bond for individuals was found."},"tbill_91d":{"available":false,"localName":"Državni zapisi","localNameEn":"Treasury bills","note":"Treasury bills (28-273 days) exist in law, but no auctions were held in 2024-2026.","sourceUrl":"https://cbcg.me/en/statistics/statistical-data/tbills-statistics"},"tbond_5y":{"available":false,"localName":"Državne obveznice","localNameEn":"Government bonds","note":"The State borrows mainly through Eurobonds sold to institutional investors; no regular domestic retail bond issues were found."},"tbond_10y":{"available":false,"localName":"Državne obveznice","localNameEn":"Government bonds","note":"No regular domestic 10-year bond issues were found."},"equity_fund":{"available":true,"localName":"Otvoreni investicioni fond","localNameEn":"Open-ended investment fund","note":"A few local funds exist; residents also reach euro and global funds through brokers."},"gold":{"available":true,"localName":"Zlatne poluge i kovanice","localNameEn":"Gold bars and coins","note":"Legal to buy and hold."}},"institutions":{"centralBank":{"name":"Central Bank of Montenegro","url":"https://www.cbcg.me/en"},"insuranceRegulator":{"name":"Insurance Supervision Agency (ANO)","url":"https://ano.me/"},"insuranceComplaints":{"name":"Insurance Supervision Agency, complaints and consumer protection","url":"https://ano.me/prigovori-i-zastita-potrosaca/"},"pensionScheme":{"name":"Pension and Disability Insurance Fund of Montenegro (Fond PIO)","url":"https://www.fondpio.me/"},"oldAgeAllowance":null,"publicHealthCover":{"name":"Health Insurance Fund of Montenegro (FZO), compulsory health insurance","url":"https://fzocg.me/"},"depositInsurance":{"name":"Deposit Protection Fund of Montenegro","url":"https://fzdcg.org/informacija-za-deponente/"},"statistics":{"name":"Statistical Office of Montenegro (Monstat)","url":"https://www.monstat.org/eng/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ME', 1, 'bank_deposit_avg_rate', 0.0029, NULL, 'sourced', 'Central Bank of Montenegro, bank interest rate statistics (table 2.1.10, total household deposits), September 2026', 'https://www.cbcg.me/slike_i_fajlovi/fajlovi/fajlovi_publikacije/statistika/statistika_kamatnih_stopa_banaka_sep_2026.zip', '2026-09-30', 'Weighted average effective rate on all household deposits 0.293% (most deposits are sight deposits paying almost nothing); all deposits 0.276%; World Bank FR.INR.DPST 2025 average 0.27%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ME', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Central Bank of Montenegro publishes a maximum allowed effective rate for consumer loans, but no figure for credit cards could be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ME', 1, 'deposit_insurance_limit', 50000, NULL, 'sourced', 'Deposit Protection Fund of Montenegro, information for depositors', 'https://fzdcg.org/informacija-za-deponente/', '2026-10-31', 'Up to EUR 50,000 per depositor per credit institution (Law on Deposit Protection, Official Gazette 72/19, 70/26).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ME', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No recurring monthly savings deposit rate is published by the Central Bank of Montenegro; households'' deposits of 3-5 years averaged 0.96% in September 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ME', 1, 'equity_return_base', 0.05, NULL, 'assumption', 'Global equity long-run return in EUR; after-tax 1-year household deposit rate 1.3% (CBCG); ECB deposit rate 2.5%', 'https://www.cbcg.me/en/statistics/statistical-data/interest-rates', '2026-10-31', 'The local market is too small to rely on, so the base is a global index fund in euros, capped at about 4 points above the after-tax local deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ME', 1, 'equity_return_high', 0.08, NULL, 'assumption', 'Global equity long-run returns in EUR', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.en.html', '2026-10-31', 'High case: strong global equity returns over the long run.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ME', 1, 'equity_return_low', 0.025, NULL, 'assumption', 'Montenegro Stock Exchange is small and illiquid; global equities in EUR; 1-year deposits 1.5% less 15% tax', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.en.html', '2026-10-31', 'Low case: global shares return little more than euro deposits over the long run.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ME', 1, 'fdr_1y_rate', 0.015, NULL, 'sourced', 'Central Bank of Montenegro, bank interest rate statistics (table 2.1.10, households, deposits 3 months to 1 year), September 2026', 'https://www.cbcg.me/slike_i_fajlovi/fajlovi/fajlovi_publikacije/statistika/statistika_kamatnih_stopa_banaka_sep_2026.zip', '2026-09-30', 'Weighted average effective rate on households'' deposits of 3 months to 1 year 1.50%; 1-3 years 1.92%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ME', 1, 'fdr_3m_rate', 0.0106, NULL, 'sourced', 'Central Bank of Montenegro, bank interest rate statistics (table 2.1.10, households, deposits up to 3 months), September 2026', 'https://www.cbcg.me/slike_i_fajlovi/fajlovi/fajlovi_publikacije/statistika/statistika_kamatnih_stopa_banaka_sep_2026.zip', '2026-09-30', 'Weighted average effective rate on households'' deposits with maturity up to 3 months 1.06%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ME', 1, 'fixed_income_return_base', 0.013, NULL, 'assumption', 'CBCG: 1-year household deposits 1.50% less 15% tax = 1.3% (Sep 2026)', 'https://www.cbcg.me/en/statistics/statistical-data/interest-rates', '2026-10-31', 'Base case: today''s after-tax 1-year local deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ME', 1, 'fixed_income_return_high', 0.022, NULL, 'assumption', 'CBCG: 1-3 year household deposits 1.92%; ECB deposit rate 2.5%', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.en.html', '2026-10-31', 'High case: savers use 1-3 year deposits or euro-area government bonds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ME', 1, 'fixed_income_return_low', 0.008, NULL, 'assumption', 'CBCG household deposit rates: 3-12 months 1.50%, up to 3 months 1.06% (Sep 2026), less 15% tax', 'https://www.cbcg.me/en/statistics/statistical-data/interest-rates', '2026-10-31', 'Low case: local deposit rates stay near 1%, leaving under 1% after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ME', 1, 'goal_inflation_education', 0.03, NULL, 'assumption', 'Monstat CPI September 2026: education services +0.1% year on year', 'https://monstat.org/uploads/files/cijene/CPI/2026/9/CPI_EN_Septembar_2026.pdf', '2026-10-31', 'Education prices have barely moved recently, so the planning inflation rate of 3% is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ME', 1, 'goal_inflation_health', 0.045, NULL, 'assumption', 'Monstat CPI September 2026: health division +4.4% year on year', 'https://monstat.org/uploads/files/cijene/CPI/2026/9/CPI_EN_Septembar_2026.pdf', '2026-10-31', 'Health prices are rising at about the headline rate, above the 3% planning inflation, so 4.5% is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ME', 1, 'gold_return_base', 0.045, NULL, 'assumption', 'Gold price history (Trading Economics); euro-area inflation target 2%', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Base case: gold rises about 4.5% a year in euros, a little above inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ME', 1, 'gold_return_high', 0.08, NULL, 'assumption', 'Gold price history (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'High case: a repeat of gold''s strong 2005-2025 trend in euros.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ME', 1, 'gold_return_low', 0.01, NULL, 'assumption', 'Gold price history (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Low case: gold roughly flat after the 2025-26 spike, with a stable euro.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ME', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'Montenegrin labour law provides a severance payment on retirement, but no official text giving it as days of wages per year of service could be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ME', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'Compulsory health insurance (FZO) covers public hospital care; no official figure for the out-of-pocket cost of a major private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ME', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Voluntary health insurance is sold as packages; no published premium table per EUR 100,000 of cover was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ME', 1, 'inflation_cpi', 0.052, NULL, 'sourced', 'Statistical Office of Montenegro (Monstat), consumer price indices September 2026', 'https://monstat.org/uploads/files/cijene/CPI/2026/9/CPI_EN_Septembar_2026.pdf', '2026-09-30', 'Consumer prices 5.2% higher than in September 2025 (release of 13 October 2026); January-September average 3.7%; World Bank 2025 average 3.9%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ME', 1, 'inflation_projection', 0.03, NULL, 'assumption', 'Montenegro uses the euro (ECB 2% target); Monstat CPI 2025 4.0% (Dec), 5.2% (Sep 2026)', 'https://monstat.org/uploads/files/cijene/CPI/2026/9/CPI_EN_Septembar_2026.pdf', '2026-10-31', 'Montenegro uses the euro unilaterally, but its inflation has run above the euro area for years (about 13% in 2022, 4-5% in 2025-26), so 3% is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ME', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life cover is sold in Montenegro, but no published premium table per EUR 1,000 of cover by age was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ME', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Insurance Supervision Agency publishes market reports, but no life claim settlement ratio was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ME', 1, 'life_expectancy', 77.6, NULL, 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/montenegro', '2026-07-01', 'Men 74.3, women 80.7 (UN WPP estimate for the year 2026, dated mid-year); World Bank 2024 figure 77.9.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ME', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":21,"men":18.4,"women":23.3},{"age":65,"total":17.2,"men":14.9,"women":19.1},{"age":70,"total":13.7,"men":11.6,"women":15.2},{"age":80,"total":7.9,"men":6.4,"women":8.8}]}', 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/montenegro', '2026-07-01', 'Remaining years computed from georank''s expected age at death by current age (UN WPP 2026 estimate).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ME', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'Eligibility rules for a non-contributory old-age benefit in Montenegro could not be confirmed from an official page.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ME', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'No source stating a non-contributory old-age (social) pension amount for Montenegro could be read; means-tested social assistance exists, but its rules were not confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ME', 1, 'oop_health_share', 0.2633, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=ME', '2023-12-31', 'Latest available year is 2023 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ME', 1, 'policy_rate', 0.025, NULL, 'sourced', 'European Central Bank key interest rates (deposit facility rate)', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.en.html', '2026-09-16', 'Montenegro uses the euro unilaterally and the Central Bank of Montenegro sets no policy rate; the ECB deposit facility rate has been 2.50% since 16 September 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ME', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":65,"nomineeUntilAge":null,"inflationLinked":true,"taxFree":null}', 'sourced', 'Pension and Disability Insurance Fund of Montenegro (Fond PIO): old-age pension conditions; indexation decision of 2 October 2026', 'https://www.fondpio.me/2026/10/02/upravni-odbor-usvojio-odluke-o-uskladjivanju-penzija-4/', '2026-09-01', 'Mandatory pay-as-you-go points-based pension (Fond PIO) from 65 with at least 15 years of insurance (women 63y3m in 2026, rising to 64y9m by 2032); pensions are indexed periodically (+2.48% from 1 September 2026; one personal point worth EUR 12.36).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ME', 1, 'retirement_accumulation_return_base', 0.03, NULL, 'assumption', 'After-tax local deposits 1.3%; global equity in EUR 5%', 'https://www.cbcg.me/en/statistics/statistical-data/interest-rates', '2026-10-31', 'Base case: roughly half euro deposits and half global shares.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ME', 1, 'retirement_accumulation_return_high', 0.05, NULL, 'assumption', 'Euro bonds 2-2.5%; global equity high case 8%', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.en.html', '2026-10-31', 'High case for a growth-leaning mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ME', 1, 'retirement_accumulation_return_low', 0.015, NULL, 'assumption', 'After-tax local deposits 1.3%; global equity low case 2.5%', 'https://www.cbcg.me/en/statistics/statistical-data/interest-rates', '2026-10-31', 'Low case for a balanced mix if shares lag and deposit rates stay low.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ME', 1, 'retirement_age_default', 65, NULL, 'sourced', 'Pension and Disability Insurance Fund of Montenegro (Fond PIO), old-age pension', 'https://www.fondpio.me/starosna-penzija/', '2026-10-31', 'Old-age pension at 65 with at least 15 years of insurance (or at 61 with 40 years); women 63 years 3 months in 2026, rising to 64 years 9 months by 2032.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ME', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'Civil servants come under the same pension law (Fond PIO), but no official page stating a separate retirement age or age limit for public employees could be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ME', 1, 'retirement_return_base', 0.012, NULL, 'assumption', 'CBCG: 1-year household deposits 1.50% less 15% tax = 1.3% (Sep 2026)', 'https://www.cbcg.me/en/statistics/statistical-data/interest-rates', '2026-10-31', 'Base case kept just below the after-tax 1-year local deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ME', 1, 'retirement_return_high', 0.02, NULL, 'assumption', 'CBCG: 1-3 year deposits 1.92%; ECB deposit rate 2.5%', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.en.html', '2026-10-31', 'High case: longer deposits or euro-area government bonds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ME', 1, 'retirement_return_low', 0.006, NULL, 'assumption', 'CBCG household deposit rates 1.06-1.50% (Sep 2026) less 15% tax', 'https://www.cbcg.me/en/statistics/statistical-data/interest-rates', '2026-10-31', 'Low case: short local deposits only, under 1% after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ME', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate or retail savings bond for individuals was found; the State borrows through Eurobonds and loans.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ME', 1, 'savings_account_rate', 0.00005, NULL, 'sourced', 'Central Bank of Montenegro, bank interest rate statistics (table 2.1.10, households, sight deposits), September 2026', 'https://www.cbcg.me/slike_i_fajlovi/fajlovi/fajlovi_publikacije/statistika/statistika_kamatnih_stopa_banaka_sep_2026.zip', '2026-09-30', 'Weighted average effective rate on households'' sight deposits 0.005% (September 2026); listed on the CBCG interest-rate statistics page https://www.cbcg.me/en/statistics/statistical-data/interest-rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ME', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":3.49},{"year":2040,"value":2.67},{"year":2065,"value":1.94}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/montenegro/2040/', '2025-12-31', '100 / old-age dependency ratio: 28.7 (2025, World Bank), 37.5 (2040) and 51.5 (2065, populationpyramid.net/montenegro/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ME', 1, 'tax_bank_interest', 0.15, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Montenegro individual income determination (reviewed 7 August 2026)', 'https://taxsummaries.pwc.com/montenegro/individual/income-determination', '2026-08-07', 'Interest income is capital income taxed at a flat 15% personal income tax; the page does not list an exemption for bank deposit interest.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ME', 1, 'tax_sanchayapatra_profit', 0, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Montenegro individual income determination (reviewed 7 August 2026)', 'https://taxsummaries.pwc.com/montenegro/individual/income-determination', '2026-08-07', 'No government savings certificate exists; interest on debt securities issued by the State, the Central Bank or local governments is not treated as taxable capital income.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ME', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Central Bank of Montenegro''s treasury bill statistics (updated 20 October 2026) show no T-bill auctions in 2024, 2025 or 2026, so there is no current yield.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ME', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No official page with a current 10-year Montenegro government bond yield could be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ME', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Montenegro borrows mainly through Eurobonds; no official page with a current 5-year yield could be read.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('MG', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"MG","iso3":"MDG","nameEn":"Madagascar","nameNative":"Madagasikara","region":"sub_saharan_africa","languages":["mg","fr","en"],"currency":{"code":"MGA","symbol":"Ar","decimals":0,"compact":"intl","usdRate":{"value":4571.5,"status":"sourced","sourceName":"Banky Foiben''i Madagasikara, interbank foreign exchange market (MID rate), 30 October 2026","sourceUrl":"https://www.banky-foibe.mg/marche_marche-de-change/","asOf":"2026-10-30","note":"US dollar MID rate on the interbank market; 4,572.79 on 2 November 2026. World Bank 2025 average 4,529.8."}},"instruments":{"savings_account":{"available":true,"localName":"Compte d''épargne","localNameEn":"Savings account","note":"Banking products are sold in French; interest is subject to 20% IRCM except on demand deposits."},"fdr_3m":{"available":true,"localName":"Dépôt à terme","localNameEn":"Term deposit (DAT)"},"fdr_1y":{"available":true,"localName":"Dépôt à terme","localNameEn":"Term deposit (DAT), 1 year"},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No standard monthly recurring deposit product with published rates was found."},"sanchayapatra_5y":{"available":true,"localName":"Bons du Trésor Fihary","localNameEn":"Fihary Treasury bonds (BTF)","note":"Issued monthly by the Treasury for 1, 2 and 3 years from 1 million ariary; bought at Treasury offices in Antananarivo and the regions.","sourceUrl":"http://www.tresorpublic.mg/tresorpublic/wp-content/themes/tresor-public/statik-content/tresor-public/service/fihary.php"},"tbill_91d":{"available":true,"localName":"Bons du Trésor par Adjudication","localNameEn":"Treasury bills (BTA), 12 weeks","note":"Auctioned every two weeks at the central bank for 4-52 weeks; minimum bid 20 million ariary, open to individuals.","sourceUrl":"https://www.banky-foibe.mg/admin/wp-content/uploads/2026/10/RESULTAT-5-D.-SEANCES_2026-10-09-002.pdf"},"tbond_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No 5-year government bond on the domestic market; the longest retail security is the 3-year BTF."},"tbond_10y":{"available":false,"localName":null,"localNameEn":null,"note":"No 10-year government bond on the domestic market."},"equity_fund":{"available":false,"localName":null,"localNameEn":null,"note":"Madagascar has no stock exchange and no retail equity funds were found."},"gold":{"available":true,"localName":"Volamena","localNameEn":"Gold","note":"Gold is mainly bought as jewellery; the central bank describes its gold operations at https://www.banky-foibe.mg/operations-sur-lor/."}},"institutions":{"centralBank":{"name":"Banky Foiben''i Madagasikara (BFM)","url":"https://www.banky-foibe.mg/"},"insuranceRegulator":{"name":"Commission de Supervision Bancaire et Financière (CSBF)","url":"https://www.banky-foibe.mg/autorite-de-supervision-la-csbf/","note":"Supervises insurers under the insurance law 2020-005; housed at the central bank."},"insuranceComplaints":null,"pensionScheme":{"name":"Caisse Nationale de Prévoyance Sociale (CNaPS)","url":"https://www.cnaps.mg/"},"oldAgeAllowance":null,"publicHealthCover":null,"depositInsurance":null,"statistics":{"name":"Institut National de la Statistique (INSTAT)","url":"https://www.instat.mg/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MG', 1, 'bank_deposit_avg_rate', 0.0399, NULL, 'sourced', 'BFM, key indicators (weighted average deposit rate of banks, taux créditeur des banques), August 2026', 'https://www.banky-foibe.mg/admin/wp-content/uploads/2026/10/Indicateurs-cles.pdf', '2026-08-31', 'Weighted average rate banks pay on deposits; average lending rate 13.34% in the same month. The World Bank''s 2025 deposit-rate figure (12.1%) is not used because it disagrees with the central bank''s series.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MG', 1, 'credit_card_rate_cap', 0.1334, NULL, 'sourced', 'BFM, key indicators (weighted average lending rate of banks, taux débiteur des banques), August 2026', 'https://www.banky-foibe.mg/admin/wp-content/uploads/2026/10/Indicateurs-cles.pdf', '2026-08-31', 'Average rate across all bank lending, not card-specific; no legal cap or card rate is published.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MG', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No operating deposit guarantee scheme or cover limit was found on the central bank''s banking-supervision pages (banking law 2020-011).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MG', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No standard monthly recurring deposit product with a published rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MG', 1, 'equity_return_base', 0.095, NULL, 'assumption', 'No stock exchange in Madagascar; global equities in ariary terms; BTF 1-year 7.3% (5.8% after IRCM)', 'https://www.banky-foibe.mg/marche_marche-de-change/', '2026-10-31', 'Madagascar has no stock market, so the base uses a global index in ariary terms (about 7% in dollars plus 3-4% ariary depreciation), capped at the 5.8% after-tax 1-year Treasury rate plus 4 points.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MG', 1, 'equity_return_high', 0.13, NULL, 'assumption', 'Global equities in ariary terms (BFM exchange rates)', 'https://www.banky-foibe.mg/marche_marche-de-change/', '2026-10-31', 'High case: strong global equities and faster ariary depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MG', 1, 'equity_return_low', 0.04, NULL, 'assumption', 'No stock exchange in Madagascar; global equities in ariary terms (BFM exchange rates)', 'https://www.banky-foibe.mg/marche_marche-de-change/', '2026-10-31', 'Low case: a weak decade for global equities with a stable ariary.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MG', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical 1-year term deposit rate was found; BFM''s interest-rate structure tables could not be opened.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MG', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical 3-month term deposit rate was found; BFM''s interest-rate structure tables (Structure des taux d''intérêts 2026) could not be opened.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MG', 1, 'fixed_income_return_base', 0.055, NULL, 'assumption', 'Treasury BTF October 2026 (1 year 7.30%); BFM BTA 52-week 7.23%; IRCM 20%', 'http://www.tresorpublic.mg/tresorpublic/download.php?path=wp-content%2Fthemes%2Ftresor-public%2Fstatik-content%2Ftresor-public%2Fservice%2Fpdf%2F&file=BTF_10_2026.pdf', '2026-10-31', 'Base case: 1-year BTF or 52-week bills at about 7.3% less 20% IRCM (about 5.8%), rounded down.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MG', 1, 'fixed_income_return_high', 0.075, NULL, 'assumption', 'Treasury BTF October 2026 (3 years 10.00%); IRCM 20%', 'http://www.tresorpublic.mg/tresorpublic/download.php?path=wp-content%2Fthemes%2Ftresor-public%2Fstatik-content%2Ftresor-public%2Fservice%2Fpdf%2F&file=BTF_10_2026.pdf', '2026-10-31', 'High case: 3-year BTF at 10% less 20% IRCM (8%), rounded down.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MG', 1, 'fixed_income_return_low', 0.035, NULL, 'assumption', 'BFM key indicators (average deposit rate 3.99%, August 2026); IRCM 20%', 'https://www.banky-foibe.mg/admin/wp-content/uploads/2026/10/Indicateurs-cles.pdf', '2026-10-31', 'Low case: ordinary bank deposits at about 4% less 20% IRCM.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MG', 1, 'goal_inflation_education', 0.09, NULL, 'assumption', 'BFM inflation (8.6%, August 2026); inflation assumption 7%', 'https://www.banky-foibe.mg/origine_indices-des-prix-par-origine-des-produits/', '2026-10-31', 'No education CPI series was read; private school fees usually rise faster than general prices, so 2 points above the 7% inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MG', 1, 'goal_inflation_health', 0.09, NULL, 'assumption', 'BFM inflation (8.6%, August 2026); inflation assumption 7%', 'https://www.banky-foibe.mg/origine_indices-des-prix-par-origine-des-produits/', '2026-10-31', 'No medical CPI series was read; private medical costs usually rise faster than general prices, so 2 points above the 7% inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MG', 1, 'gold_return_base', 0.08, NULL, 'assumption', 'BFM exchange rates (about 4,570 ariary per dollar in October 2026, against about 4,530 on average in 2025 and 3,300 in 2016)', 'https://www.banky-foibe.mg/marche_marche-de-change/', '2026-10-31', 'Base case: the long-run dollar gold trend of about 4% a year plus about 4% a year ariary depreciation against the dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MG', 1, 'gold_return_high', 0.13, NULL, 'assumption', 'BFM exchange rates', 'https://www.banky-foibe.mg/marche_marche-de-change/', '2026-10-31', 'High case: strong gold years and faster ariary depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MG', 1, 'gold_return_low', 0.02, NULL, 'assumption', 'BFM exchange rates (ariary per US dollar)', 'https://www.banky-foibe.mg/marche_marche-de-change/', '2026-10-31', 'Low case: flat dollar gold with slow ariary depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MG', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Labour Code''s rules on a retirement or end-of-service indemnity for private employees could not be read from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MG', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a major private hospital stay in Madagascar was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MG', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premiums by age were found from a public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MG', 1, 'inflation_cpi', 0.086, NULL, 'sourced', 'Banky Foiben''i Madagasikara (BFM), inflation rate (year-on-year change of the consumer price index, base 2016), August 2026', 'https://www.banky-foibe.mg/origine_indices-des-prix-par-origine-des-produits/', '2026-08-31', '8.6% year on year in August 2026 (INSTAT index, shown by the central bank); World Bank 2025 average 8.05%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MG', 1, 'inflation_projection', 0.07, NULL, 'assumption', 'BFM medium-term inflation objective (5%); World Bank CPI 2021-2025 (about 6-10% a year)', 'https://data.worldbank.org/indicator/FP.CPI.TOTL.ZG?locations=MG', '2026-10-31', 'Inflation has run at 7-10% a year since 2022 (8.05% in 2025, 8.6% in August 2026) against the central bank''s 5% medium-term aim, so a rounded 7% is used for long-range plans.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MG', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published indicative term-life premium rates per 1,000 ariary of cover were found from the supervisor or another public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MG', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The insurance supervisor (CSBF at the central bank) publishes no industry-wide life claim settlement ratio that could be found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MG', 1, 'life_expectancy', 63.835, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN), Madagascar', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=MG', '2024-12-31', '63.8 years in 2024 (men 62.1, women 65.6); UN WPP 2024 gives 64.3 for 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MG', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":17.5,"men":16.8,"women":18.1},{"age":65,"total":14,"men":13.4,"women":14.5},{"age":70,"total":10.8,"men":10.4,"women":11.2},{"age":80,"total":6,"men":5.8,"women":6.2}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/madagascar/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026; by-sex values are the 5-year age-band figures; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MG', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension was found (see old_age_allowance_monthly).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MG', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension open to people planning today was found; the CNaPS ''allocation de solidarité'' is a closed legacy benefit for people employed in 1964-1968 (CLEISS 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MG', 1, 'oop_health_share', 0.2742, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), Madagascar', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=MG', '2023-12-31', '27.4% in 2023 (WHO Global Health Expenditure Database); older than 2025, the latest available.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MG', 1, 'policy_rate', 0.125, NULL, 'sourced', 'BFM, key indicators (taux directeur), valid from 5 August 2026', 'https://www.banky-foibe.mg/admin/wp-content/uploads/2026/10/Indicateurs-cles.pdf', '2026-08-05', 'Raised from 12.00% to 12.50% by the Monetary Committee on 4 August 2026, effective 5 August 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MG', 1, 'public_pension_scheme', NULL, '{"pensionFromAge":60,"entryAgeMin":null,"entryAgeMax":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'CLEISS, Madagascar social security scheme (CNaPS old-age pension), 2026', 'https://www.cleiss.fr/docs/regimes/regime_madagascar.html', '2026-01-08', 'Compulsory CNaPS pension for private employees from 60: 30% of the annual minimum wage plus 20% of revalued average pay of the last 10 years plus 1% per extra 4 quarters, floor 60% of the minimum wage, cap 75% of average pay. Past wages are revalued but no automatic indexation of pensions is described, so inflationLinked is false; tax treatment not stated.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MG', 1, 'retirement_accumulation_return_base', 0.075, NULL, 'assumption', 'Treasury BTF October 2026; equity base 9.5%; gold base 8%', 'http://www.tresorpublic.mg/tresorpublic/download.php?path=wp-content%2Fthemes%2Ftresor-public%2Fstatik-content%2Ftresor-public%2Fservice%2Fpdf%2F&file=BTF_10_2026.pdf', '2026-10-31', 'Base case: a balanced mix of BTF, global equities held in ariary terms and some gold.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MG', 1, 'retirement_accumulation_return_high', 0.1, NULL, 'assumption', 'Treasury BTF October 2026; equity high 13%', 'http://www.tresorpublic.mg/tresorpublic/download.php?path=wp-content%2Fthemes%2Ftresor-public%2Fstatik-content%2Ftresor-public%2Fservice%2Fpdf%2F&file=BTF_10_2026.pdf', '2026-10-31', 'High case: a growth-leaning mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MG', 1, 'retirement_accumulation_return_low', 0.05, NULL, 'assumption', 'Treasury BTF and BFM deposit rates; IRCM 20%', 'http://www.tresorpublic.mg/tresorpublic/download.php?path=wp-content%2Fthemes%2Ftresor-public%2Fstatik-content%2Ftresor-public%2Fservice%2Fpdf%2F&file=BTF_10_2026.pdf', '2026-10-31', 'Low case: a mix earning about after-tax Treasury and deposit rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MG', 1, 'retirement_age_default', 60, NULL, 'sourced', 'CLEISS (French social security liaison body), Madagascar social security scheme, 2026', 'https://www.cleiss.fr/docs/regimes/regime_madagascar.html', '2026-01-08', 'CNaPS old-age pension at 60 for men and women, with 15 years of affiliation and 28 quarters of contributions in the last 10 years; up to 5 years earlier for 60%+ incapacity. No different rule for people born after 1975 was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MG', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'The current retirement age for civil servants (Caisse de Retraite Civile et Militaire) could not be confirmed from an official source; a 2016 press report of a rise to 65 was not verified.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MG', 1, 'retirement_return_base', 0.055, NULL, 'assumption', 'Treasury BTF October 2026 (1 year 7.30%); IRCM 20%', 'http://www.tresorpublic.mg/tresorpublic/download.php?path=wp-content%2Fthemes%2Ftresor-public%2Fstatik-content%2Ftresor-public%2Fservice%2Fpdf%2F&file=BTF_10_2026.pdf', '2026-10-31', 'Base case: about the 1-year BTF or 52-week bill yield after 20% IRCM (5.8%), rounded down; not above the after-tax safe rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MG', 1, 'retirement_return_high', 0.07, NULL, 'assumption', 'Treasury BTF October 2026 (2 years 8.80%, 3 years 10.00%); IRCM 20%', 'http://www.tresorpublic.mg/tresorpublic/download.php?path=wp-content%2Fthemes%2Ftresor-public%2Fstatik-content%2Ftresor-public%2Fservice%2Fpdf%2F&file=BTF_10_2026.pdf', '2026-10-31', 'High case: part of the money in 2-3 year BTF at 7-8% after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MG', 1, 'retirement_return_low', 0.035, NULL, 'assumption', 'BFM key indicators (average deposit rate 3.99%, August 2026); IRCM 20%', 'https://www.banky-foibe.mg/admin/wp-content/uploads/2026/10/Indicateurs-cles.pdf', '2026-10-31', 'Low case: ordinary bank deposits less 20% IRCM.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MG', 1, 'sanchayapatra_5y_rate', 0.1, NULL, 'sourced', 'Direction Générale du Trésor, Bons du Trésor Fihary (BTF) issue of 1-15 October 2026', 'http://www.tresorpublic.mg/tresorpublic/download.php?path=wp-content%2Fthemes%2Ftresor-public%2Fstatik-content%2Ftresor-public%2Fservice%2Fpdf%2F&file=BTF_10_2026.pdf', '2026-10-01', '3-year BTF at 10.00% (1 year 7.30%, 2 years 8.80%); BTF are sold to individuals from 1 million ariary at Treasury offices and are the longest retail government security (no 5-year issue). The November 2026 issue keeps the same rates. Treasury site is served over http only.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MG', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical rate on ordinary savings accounts was found; BFM publishes only an average bank deposit rate (3.99% in August 2026) and per-bank minimum/maximum tables that could not be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MG', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":16.58},{"year":2040,"value":13.7},{"year":2065,"value":8.7}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/madagascar/2040/', '2025-12-31', '100 / old-age dependency ratio: 6.03 (2025, World Bank), 7.3 (2040) and 11.5 (2065, populationpyramid.net/madagascar/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MG', 1, 'tax_bank_interest', 0.2, NULL, 'sourced', 'Code Général des Impôts 2026 (Loi de finances 2026), articles 01.04.03, 01.04.04 and 01.04.10 (IRCM)', 'https://www.impots.mg/explorer?path=/legislation/Codes%20et%20Manuels/CDI-LFI%202026.pdf', '2026-01-01', 'Interest on bank placements is subject to the tax on income from movable capital (IRCM) at 20%, withheld by the payer and final; interest on demand (current) deposits is exempt.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MG', 1, 'tax_sanchayapatra_profit', 0.2, NULL, 'sourced', 'Code Général des Impôts 2026, article 01.04.03 (IRCM on Bons du Trésor Fihary and BTA)', 'https://www.impots.mg/explorer?path=/legislation/Codes%20et%20Manuels/CDI-LFI%202026.pdf', '2026-01-01', 'Income from BTA and BTF is expressly subject to IRCM at 20%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MG', 1, 'tbill_91d_rate', 0.0285, NULL, 'sourced', 'BFM, results of the last 5 Treasury bill (BTA) auctions, 12-week bill on 9 October 2026', 'https://www.banky-foibe.mg/admin/wp-content/uploads/2026/10/RESULTAT-5-D.-SEANCES_2026-10-09-002.pdf', '2026-10-09', 'Weighted average rate on the 12-week (84-day) BTA; 3.05% on 28 September 2026. The 52-week BTA yielded 7.23% on 9 October 2026. Short bill yields sit far below the 12.5% policy rate because the Treasury allots little at short tenors; the BFM key-indicators sheet gives 5.13% as the average Treasury bill rate on 21 October 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MG', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 10-year government bond is issued on the domestic market; the Treasury issues bills (BTA, up to 52 weeks) and BTF of 1-3 years only.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MG', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 5-year government bond is issued on the domestic market; the Treasury issues bills (BTA, up to 52 weeks) and BTF of 1-3 years only.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('MH', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"MH","iso3":"MHL","nameEn":"Marshall Islands","nameNative":"Aolepān Aorōkin M̧ajeļ","region":"east_asia_pacific","languages":["mh","en"],"currency":{"code":"USD","symbol":"$","decimals":2,"compact":"intl","usdRate":{"value":1,"status":"sourced","sourceName":"World Bank WDI, official exchange rate (PA.NUS.FCRF)","sourceUrl":"https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=MH","asOf":"2025-12-31","note":"The US dollar is the official currency."}},"instruments":{"savings_account":{"available":true,"localName":null,"localNameEn":"Savings account","note":"Offered by the banks operating in the RMI; rates not published."},"fdr_3m":{"available":true,"localName":null,"localNameEn":"Time deposit","note":"Rates not published."},"fdr_1y":{"available":true,"localName":null,"localNameEn":"Time deposit","note":"Rates not published."},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No monthly recurring deposit product found."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate or retail bond."},"tbill_91d":{"available":false,"localName":null,"localNameEn":null,"note":"The government issues no treasury bills."},"tbond_5y":{"available":false,"localName":null,"localNameEn":null,"note":"The government issues no domestic bonds."},"tbond_10y":{"available":false,"localName":null,"localNameEn":null,"note":"The government issues no domestic bonds."},"equity_fund":{"available":true,"localName":null,"localNameEn":"Global index fund (US dollars)","note":"No local stock market or funds; residents can only invest in US-listed index funds through foreign brokers."},"gold":{"available":true,"localName":null,"localNameEn":"Gold","note":"No local gold dealers; gold must be bought from abroad."}},"institutions":{"centralBank":null,"insuranceRegulator":null,"insuranceComplaints":null,"pensionScheme":{"name":"Marshall Islands Social Security Administration (MISSA)","url":"https://www.rmissa.net/"},"oldAgeAllowance":{"name":"MISSA Social Support Scheme","url":"https://www.rmissa.net/2025/08/27/social-support-scheme-faqs/"},"publicHealthCover":{"name":"Ministry of Health and Human Services (MOHHS)","url":"https://www.rmihealth.org/"},"depositInsurance":null,"statistics":{"name":"Economic Policy, Planning and Statistics Office (EPPSO)","url":"https://rmieppso.org/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MH', 1, 'bank_deposit_avg_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'World Bank FR.INR.DPST has no value for the Marshall Islands; no average deposit rate published.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MH', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No credit card rate cap or typical rate found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MH', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No national deposit insurance scheme found; a US bank branch operating in the RMI may carry US FDIC cover, but we could not confirm it.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MH', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No monthly recurring deposit product found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MH', 1, 'equity_return_base', 0.07, NULL, 'assumption', 'Global equity index in US dollars; US 3-month Treasury bill 4.09%', 'https://tradingeconomics.com/united-states/3-month-bill-yield', '2026-10-31', 'No local stock market, so the base is a global index in dollars at about 3 points over US bills, within the 4-point limit.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MH', 1, 'equity_return_high', 0.09, NULL, 'assumption', 'Global equity index in US dollars', 'https://tradingeconomics.com/united-states/3-month-bill-yield', '2026-10-31', 'High case with a full equity premium.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MH', 1, 'equity_return_low', 0.03, NULL, 'assumption', 'Global equity index in US dollars; US 3-month Treasury bill 4.09%', 'https://tradingeconomics.com/united-states/3-month-bill-yield', '2026-10-31', 'No local stock market; low case for a global index fund in dollars over a weak decade.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MH', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published 1-year time deposit rates found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MH', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published 3-month time deposit rates found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MH', 1, 'fixed_income_return_base', 0.03, NULL, 'assumption', 'Local bank deposits (no published rates); US Treasury bills', 'https://tradingeconomics.com/united-states/3-month-bill-yield', '2026-10-31', 'Base case below the US bill rate because local deposits pay less and US bills need a foreign broker. Safe USD rates: no published local deposit rates found; the RMI has no central bank or government securities and uses the US dollar; US 3-month Treasury bill 4.09% (30 Oct 2026), reachable only through foreign brokers.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MH', 1, 'fixed_income_return_high', 0.04, NULL, 'assumption', 'US 3-month Treasury bill 4.09%', 'https://tradingeconomics.com/united-states/3-month-bill-yield', '2026-10-31', 'High case near US Treasury bill yields. Safe USD rates: no published local deposit rates found; the RMI has no central bank or government securities and uses the US dollar; US 3-month Treasury bill 4.09% (30 Oct 2026), reachable only through foreign brokers.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MH', 1, 'fixed_income_return_low', 0.015, NULL, 'assumption', 'Local bank deposits (no published rates); US Treasury bills', 'https://tradingeconomics.com/united-states/3-month-bill-yield', '2026-10-31', 'Low case for local savings and time deposits. Safe USD rates: no published local deposit rates found; the RMI has no central bank or government securities and uses the US dollar; US 3-month Treasury bill 4.09% (30 Oct 2026), reachable only through foreign brokers.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MH', 1, 'goal_inflation_education', 0.04, NULL, 'assumption', 'Inflation projection (ADB forecasts)', 'https://www.adb.org/where-we-work/marshall-islands/economy', '2026-10-31', 'No education CPI published; we plan 1 point above general inflation for fees and study abroad.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MH', 1, 'goal_inflation_health', 0.04, NULL, 'assumption', 'Inflation projection; very low out-of-pocket share (World Bank)', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=MH', '2026-10-31', 'Households pay little directly, so we plan 1 point above general inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MH', 1, 'gold_return_base', 0.05, NULL, 'assumption', 'US-dollar gold trend', 'https://tradingeconomics.com/united-states/3-month-bill-yield', '2026-10-31', 'Long-run dollar gold trend of about 5% with no currency effect.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MH', 1, 'gold_return_high', 0.09, NULL, 'assumption', 'US-dollar gold trend', 'https://tradingeconomics.com/united-states/3-month-bill-yield', '2026-10-31', 'High case for a strong gold cycle.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MH', 1, 'gold_return_low', 0.01, NULL, 'assumption', 'US-dollar gold trend', 'https://tradingeconomics.com/united-states/3-month-bill-yield', '2026-10-31', 'Gold can stall for a decade; the US dollar is the local currency.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MH', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No statutory end-of-service gratuity found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MH', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical hospital stay cost found; most care is public and serious cases are referred abroad.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MH', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premium rates found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MH', 1, 'inflation_cpi', 0.057, NULL, 'sourced', 'Asian Development Bank, Asian Development Outlook September 2026 (Marshall Islands economy page)', 'https://www.adb.org/where-we-work/marshall-islands/economy', '2026-09-30', 'ADB Asian Development Outlook (Sep 2026) estimate for calendar 2026, not a measured CPI reading (ADB forecasts 4.7% for 2027); the statistics office (EPPSO) has published no recent CPI report, so this published estimate is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MH', 1, 'inflation_projection', 0.03, NULL, 'assumption', 'ADB 2027 forecast 4.7%; US-dollar economy with US inflation near 2-3%', 'https://www.adb.org/where-we-work/marshall-islands/economy', '2026-10-31', 'Prices follow US and import costs and the IMF expects inflation to stay above its historical average for a while, so we plan with 3%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MH', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No locally published term life premium rates found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MH', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No insurance regulator statistics on life claim settlement found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MH', 1, 'life_expectancy', 67.1, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN)', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=MH', '2024-12-31', 'Men 65.0, women 69.5 (2024, older than 2025); UN WPP via georank gives 67.3 for 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MH', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":16.4,"men":15,"women":18.1},{"age":65,"total":13.2,"men":12,"women":14.5},{"age":70,"total":10.3,"men":9.4,"women":11.3},{"age":80,"total":5.9,"men":5.4,"women":6.3}]}', 'sourced', 'UN World Population Prospects (via georank.org)', 'https://georank.org/life-expectancy/marshall-islands', '2026-07-08', 'Remaining years derived from expected age at death by current age; secondary source for UN WPP.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MH', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":60,"womenAge":60,"over90Monthly":null,"meansTested":false}', 'sourced', 'MISSA, Social Support Scheme FAQs', 'https://www.rmissa.net/2025/08/27/social-support-scheme-faqs/', '2025-10-01', 'Age 60+, RMI citizenship, one year''s residence; no income test is described, but anyone receiving a MISSA or other retirement pension is excluded. Three-year pilot from October 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MH', 1, 'old_age_allowance_monthly', 100, NULL, 'sourced', 'MISSA, Social Support Scheme FAQs', 'https://www.rmissa.net/2025/08/27/social-support-scheme-faqs/', '2025-10-01', 'Non-contributory Social Support Scheme pension of $100 a month for citizens aged 60+ who receive no MISSA or other retirement pension, paid since October 2025 as a three-year pilot, so it may change or end after FY2028.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MH', 1, 'oop_health_share', 0.011, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure, SH.XPD.OOPC.CH.ZS)', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=MH', '2023-12-31', 'About 1.1%: public and donor funding cover almost all health spending. Latest World Bank (WHO GHED) value is for 2023, older than 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MH', 1, 'policy_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Marshall Islands has no central bank and uses the US dollar, so there is no national policy rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MH', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":63,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'Marshall Islands Social Security Administration (MISSA), Retirement and General Provisions', 'https://www.rmissa.net/retirement/', '2026-10-31', 'Contributory MISSA retirement pension from 63 (fully insured: 12 to 38 quarters of coverage); monthly benefit = 1/12 of (2% of indexed covered earnings + a social element of 14.5% of the first $11,000 and 0.7% of cumulative earnings from $11,000 to $44,000), minimum $128.99, with cuts above $299.99 since 2017. No cost-of-living adjustment is described, so inflationLinked is false; contribution rates and tax treatment were not stated.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MH', 1, 'retirement_accumulation_return_base', 0.05, NULL, 'assumption', 'Mix of dollar deposits and a global equity index', 'https://tradingeconomics.com/united-states/3-month-bill-yield', '2026-10-31', 'Half global equity at 7% and half safe assets near 3%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MH', 1, 'retirement_accumulation_return_high', 0.065, NULL, 'assumption', 'Mix of dollar deposits and a global equity index', 'https://tradingeconomics.com/united-states/3-month-bill-yield', '2026-10-31', 'High case with about 60% equity.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MH', 1, 'retirement_accumulation_return_low', 0.025, NULL, 'assumption', 'Mix of dollar deposits and a global equity index', 'https://tradingeconomics.com/united-states/3-month-bill-yield', '2026-10-31', 'Low case for a balanced mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MH', 1, 'retirement_age_default', 63, NULL, 'sourced', 'Marshall Islands Social Security Administration (MISSA), Retirement benefits', 'https://www.rmissa.net/retirement/', '2026-10-31', 'Normal retirement age 63 with at least 12 quarters of coverage (P.L. 2021-36 capped the normal retirement age at 63); early and deferred retirement were abolished in March 2017. MISSA also lists a Bill No. 45 on changing the retirement age whose content could not be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MH', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'Could not find the public service retirement age.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MH', 1, 'retirement_return_base', 0.03, NULL, 'assumption', 'Local bank deposits; US 3-month Treasury bill 4.09%', 'https://tradingeconomics.com/united-states/3-month-bill-yield', '2026-10-31', 'Base case below the US bill rate, the only verifiable safe dollar rate. Safe USD rates: no published local deposit rates found; the RMI has no central bank or government securities and uses the US dollar; US 3-month Treasury bill 4.09% (30 Oct 2026), reachable only through foreign brokers.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MH', 1, 'retirement_return_high', 0.04, NULL, 'assumption', 'US 3-month Treasury bill 4.09%', 'https://tradingeconomics.com/united-states/3-month-bill-yield', '2026-10-31', 'High case near US bill yields. Safe USD rates: no published local deposit rates found; the RMI has no central bank or government securities and uses the US dollar; US 3-month Treasury bill 4.09% (30 Oct 2026), reachable only through foreign brokers.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MH', 1, 'retirement_return_low', 0.015, NULL, 'assumption', 'Local bank deposits (no published rates)', 'https://tradingeconomics.com/united-states/3-month-bill-yield', '2026-10-31', 'Low case for local deposits. Safe USD rates: no published local deposit rates found; the RMI has no central bank or government securities and uses the US dollar; US 3-month Treasury bill 4.09% (30 Oct 2026), reachable only through foreign brokers.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MH', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate or retail savings bond.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MH', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published savings account rates of banks in the Marshall Islands found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MH', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":12.6}]}', 'sourced', 'World Bank WDI, age dependency ratio, old (SP.POP.DPND.OL)', 'https://data.worldbank.org/indicator/SP.POP.DPND.OL?locations=MH', '2025-12-31', '100 / 7.96 old-age dependency ratio (2025); populationpyramid.net has no Marshall Islands pages, so no 2040 or 2065 projection could be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MH', 1, 'tax_bank_interest', NULL, NULL, 'missing', '', '', '2026-10-31', 'Could not confirm how bank interest is taxed for residents (the income tax is mainly a wages and salary tax); no official tax page reached.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MH', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate exists.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MH', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The government issues no treasury bills.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MH', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The government issues no domestic bonds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MH', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The government issues no domestic bonds.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('MK', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"MK","iso3":"MKD","nameEn":"North Macedonia","nameNative":"Северна Македонија","region":"europe_central_asia","languages":["mk","sq","tr","en"],"currency":{"code":"MKD","symbol":"ден.","decimals":2,"compact":"intl","usdRate":{"value":55.215,"status":"sourced","sourceName":"Trading Economics, USD/MKD exchange rate","sourceUrl":"https://tradingeconomics.com/macedonia/currency","asOf":"2026-10-30","note":"EUR/MKD 61.51 (the denar is pegged to the euro). Secondary source because nbrm.mk served a bot check; World Bank 2025 average 54.65."}},"instruments":{"savings_account":{"available":true,"localName":"Штедна сметка","localNameEn":"Savings account"},"fdr_3m":{"available":true,"localName":"Орочен депозит","localNameEn":"Term deposit (3 months)"},"fdr_1y":{"available":true,"localName":"Орочен депозит","localNameEn":"Term deposit (1 year)"},"dps":{"available":false,"localName":null,"localNameEn":"Monthly recurring deposit","note":"No standard fixed-rate recurring deposit product with a published rate was found."},"sanchayapatra_5y":{"available":true,"localName":"Граѓанска обврзница","localNameEn":"Citizen bond (government bond for individuals)","note":"2-year denar bonds sold to individuals through banks in occasional issues (2023, 2025); interest tax-exempt.","sourceUrl":"https://biznis.rs/novac/severna-makedonija-izdaje-trecu-gradjansku-obveznicu-u-ukupnom-iznosu-od-100-miliona-denara/"},"tbill_91d":{"available":true,"localName":"Државни записи","localNameEn":"Treasury bills","note":"Auctioned by the Ministry of Finance through the National Bank; recent issues are mostly 1-year bills."},"tbond_5y":{"available":true,"localName":"Државни обврзници","localNameEn":"Government bonds"},"tbond_10y":{"available":true,"localName":"Државни обврзници","localNameEn":"Government bonds"},"equity_fund":{"available":true,"localName":"Инвестициски фондови","localNameEn":"Investment funds","note":"Open-end investment funds are supervised by the Securities and Exchange Commission."},"gold":{"available":true,"localName":"Злато (прачки и монети)","localNameEn":"Gold bars and coins","note":"No restriction on buying physical gold found."}},"institutions":{"centralBank":{"name":"National Bank of the Republic of North Macedonia","url":"https://www.nbrm.mk/"},"insuranceRegulator":{"name":"Insurance Supervision Agency (ASO)","url":"https://aso.mk/"},"insuranceComplaints":{"name":"Insurance Supervision Agency (ASO), consumer complaints","url":"https://aso.mk/","note":"The agency handles complaints against insurers."},"pensionScheme":{"name":"Pension and Disability Insurance Fund of North Macedonia (FPIOM)","url":"https://www.piom.com.mk/"},"oldAgeAllowance":{"name":"Social security for the elderly (Ministry of Social Policy, Demography and Youth)","url":"https://portal.mdt.gov.mk/post-body-files/regulativa-od-oblasta-na-socijalnata-zastita-file-HrXI.pdf"},"publicHealthCover":{"name":"Health Insurance Fund of North Macedonia (FZOM)","url":"https://fzo.org.mk/"},"depositInsurance":{"name":"Deposit Insurance Fund","url":"https://www.fod.gov.mk/"},"statistics":{"name":"State Statistical Office","url":"https://www.stat.gov.mk/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MK', 1, 'bank_deposit_avg_rate', 0.0272, NULL, 'sourced', 'World Bank WDI FR.INR.DPST', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=MK', '2025-12-31', 'Deposit interest rate 2.72% for 2025 (National Bank data via IMF).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MK', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'The consumer credit law caps the annual cost at five times the statutory penalty interest rate (2019 amendment, reported secondarily), but the current reference rate on nbrm.mk could not be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MK', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Deposit Insurance Fund''s site (fod.gov.mk) and the National Bank''s site could not be reached; older reports give EUR 30,000 per depositor per bank (2019), but the current limit could not be confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MK', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No standard monthly recurring deposit product with a published rate was found; the National Bank''s statistics could not be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MK', 1, 'equity_return_base', 0.06, NULL, 'assumption', 'Average deposit rate 2.72% in 2025 (World Bank FR.INR.DPST, tax-free) plus a 3.3-point equity premium', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=MK', '2026-10-31', 'North Macedonia''s stock market is thin, so the base is a diversified global or regional index in denar terms (pegged to the euro), kept within 4 points of the tax-free deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MK', 1, 'equity_return_high', 0.085, NULL, 'assumption', 'Long-run global equity returns; denar pegged to the euro', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=MK', '2026-10-31', 'High case near long-run global equity returns with a stable denar-euro peg.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MK', 1, 'equity_return_low', 0.03, NULL, 'assumption', 'Denar pegged to the euro; World Bank exchange rate PA.NUS.FCRF', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=MK', '2026-10-31', 'Low case for a global index fund in denar terms if world shares are weak; the local exchange (MBI10) is small and illiquid.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MK', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The researcher''s figure (2.62% for June 2026 from TheGlobalEconomy.com, quoting National Bank data) could not be re-confirmed: that page returned HTTP 429 on every retry and nbrm.mk returned 403. The World Bank average deposit rate was 2.72% in 2025 (bank_deposit_avg_rate).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MK', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 3-month denar term deposit rate could be read: the National Bank''s interest-rate statistics (nbrm.mk) served a bot check.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MK', 1, 'fixed_income_return_base', 0.026, NULL, 'assumption', 'Average deposit rate 2.72% in 2025 (World Bank FR.INR.DPST); interest on deposits currently untaxed', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=MK', '2026-10-31', 'Base case: rolling denar term deposits at about the 2025 average deposit rate, untaxed while the 10% tax on savings interest is postponed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MK', 1, 'fixed_income_return_high', 0.04, NULL, 'assumption', 'Citizen bond 4.5% coupon (Dec 2025), interest tax-exempt', 'https://biznis.rs/novac/severna-makedonija-izdaje-trecu-gradjansku-obveznicu-u-ukupnom-iznosu-od-100-miliona-denara/', '2026-10-31', 'High case: buying government citizen bonds and longer deposits when offered.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MK', 1, 'fixed_income_return_low', 0.015, NULL, 'assumption', 'Average deposit rate 2.72% in 2025 (World Bank), falling in 2026', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=MK', '2026-10-31', 'Low case: a mix of sight and short term deposits as rates drift lower.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MK', 1, 'goal_inflation_education', 0.05, NULL, 'assumption', 'Education CPI +5.4% year on year in September 2026 (Trading Economics, State Statistical Office data)', 'https://tradingeconomics.com/macedonia/inflation-cpi/news/590167', '2026-10-31', 'Education prices are rising about 5% a year, which is used for planning.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MK', 1, 'goal_inflation_health', 0.04, NULL, 'assumption', 'Health CPI +1.3% year on year in September 2026 (Trading Economics, State Statistical Office data)', 'https://tradingeconomics.com/macedonia/inflation-cpi/news/590167', '2026-10-31', 'Measured health prices are rising slowly, but with about 40% of health spending paid out of pocket we plan with the 3% projection plus one point.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MK', 1, 'gold_return_base', 0.05, NULL, 'assumption', 'World Bank official exchange rate (denar per USD); long-run dollar gold trend', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=MK', '2026-10-31', 'Long-run dollar gold trend of about 4-5%, with the denar following the euro and no expected trend against the dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MK', 1, 'gold_return_high', 0.085, NULL, 'assumption', 'World Bank official exchange rate (denar per USD)', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=MK', '2026-10-31', 'High case with strong dollar gold and a weaker euro and denar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MK', 1, 'gold_return_low', 0.015, NULL, 'assumption', 'World Bank official exchange rate (denar per USD)', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=MK', '2026-10-31', 'Low case: weak dollar gold price and a stronger euro (and denar).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MK', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Labour Relations Law provides a one-off payment on retirement rather than a days-per-year gratuity, but its current text could not be read from an official source, so no figure is given.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MK', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No official figure for the typical out-of-pocket cost of a major private hospital stay was found; public hospital care under the Health Insurance Fund carries co-payments.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MK', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Voluntary private health insurance is small and no published premium table per MKD 100,000 of cover by age was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MK', 1, 'inflation_cpi', 0.027, NULL, 'sourced', 'Trading Economics, North Macedonia inflation (State Statistical Office data)', 'https://tradingeconomics.com/macedonia/inflation-cpi/news/590167', '2026-09-30', 'Annual CPI 2.7% in September 2026 (2.6% in August, 2.3% in July), published 7 October 2026. Secondary source: stat.gov.mk could not be reached. World Bank 2025 average 4.1%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MK', 1, 'inflation_projection', 0.03, NULL, 'assumption', 'Denar pegged to the euro (ECB 2% target); CPI 2.3-2.7% in mid-2026, 4.1% in 2025 (World Bank)', 'https://data.worldbank.org/indicator/FP.CPI.TOTL.ZG?locations=MK', '2026-10-31', 'The National Bank keeps the denar stable against the euro, so long-run inflation should be close to the euro area''s plus a catch-up margin; 3% is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MK', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life cover is sold, mostly with bank loans, but no regulator or official premium table per MKD 1,000 of cover by age was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MK', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Insurance Supervision Agency (ASO) publishes market reports, but no industry-wide life claim settlement ratio was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MK', 1, 'life_expectancy', 77.8, NULL, 'sourced', 'UN WPP 2024 medium variant via populationpyramid.net (mortality, 2026)', 'https://www.populationpyramid.net/mortality/tfyr-macedonia/', '2026-01-01', 'Secondary source of UN WPP 2024 for 2026: men 75.6, women 80.0; same source as life_table_remaining. World Bank 2024 estimate 76.6 (men 74.5, women 78.9).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MK', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":20.7,"men":19.1,"women":22.3},{"age":65,"total":16.9,"men":15.4,"women":18.1},{"age":70,"total":13.1,"men":12,"women":14.2},{"age":80,"total":7.2,"men":6.4,"women":7.9}]}', 'sourced', 'UN WPP 2024 medium variant via populationpyramid.net (mortality, 2026)', 'https://www.populationpyramid.net/mortality/tfyr-macedonia/', '2026-01-01', 'Secondary source of UN WPP 2024 for 2026, five-year age groups; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MK', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":65,"womenAge":65,"over90Monthly":null,"meansTested":true}', 'sourced', 'Law on Social Security for the Elderly (Official Gazette 104/2019), Ministry of Social Policy, Demography and Youth', 'https://portal.mdt.gov.mk/post-body-files/regulativa-od-oblasta-na-socijalnata-zastita-file-HrXI.pdf', '2019-05-23', 'Law on Social Security for the Elderly (Gazette 104/2019), arts. 3-4: from age 65 for citizens with permanent residence for the last 15 years, no property to live from, no domestic or foreign pension and no income in the last 3 months (conditions also apply to the spouse); only one member of a couple can claim. The law text is from 2019 (older than 2025); later amendments were not re-checked.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MK', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'Law on Social Security for the Elderly (Gazette 104/2019), art. 6: MKD 6,000 a month, raised each January by the previous year''s cost-of-living increase (plus MKD 1,000 a month for energy from October to March, art. 7); the 2026 amount could not be found on a readable official page.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MK', 1, 'oop_health_share', 0.3957, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=MK', '2023-12-31', 'Latest available year is 2023 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MK', 1, 'policy_rate', 0.0425, NULL, 'sourced', 'Trading Economics, North Macedonia interest rate (National Bank CB bills rate)', 'https://tradingeconomics.com/macedonia/interest-rate', '2026-09-15', 'Raised 25 bp to 4.25% in June 2026 and held in July and September 2026. Secondary source: nbrm.mk served a bot check.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MK', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":64,"nomineeUntilAge":null,"inflationLinked":true,"taxFree":null}', 'sourced', 'Assembly bill amending the Law on Pension and Disability Insurance (March 2026), citing Gazette 154/2025', 'https://www.mchamber.mk/Upload/Documents/Предлог на закон за изменување и дополнување на Законот за пензиското и инвалидското осигурување, по скратена постапка.pdf', '2026-03-31', 'Compulsory pay-as-you-go pension (Pension and Disability Insurance Fund), plus a mandatory funded second pillar for younger workers. The cited March 2026 bill shows pensions adjusted on 1 September 2025 and 1 March 2026 using 50% of CPI growth and 50% of average wage growth (Gazette 154/25, replacing art. 37 for that period) and proposes a flat MKD 1,000 increase from 1 March 2026. The pension age (64 men, 62 women with 15 years of service) is not in this bill; it comes from the retirement_age_default source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MK', 1, 'retirement_accumulation_return_base', 0.045, NULL, 'assumption', 'Average deposit rate 2.72% in 2025 (World Bank); equity base 6%', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=MK', '2026-10-31', 'Base case: roughly half global equity at 6% and half deposits and citizen bonds at about 3%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MK', 1, 'retirement_accumulation_return_high', 0.06, NULL, 'assumption', 'Citizen bond 4.5%; equity high 8.5%', 'https://biznis.rs/novac/severna-makedonija-izdaje-trecu-gradjansku-obveznicu-u-ukupnom-iznosu-od-100-miliona-denara/', '2026-10-31', 'High case for a growth-leaning balanced mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MK', 1, 'retirement_accumulation_return_low', 0.03, NULL, 'assumption', 'Average deposit rate 2.72% in 2025 (World Bank); global equity in denar terms', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=MK', '2026-10-31', 'Low case for a balanced mix if shares lag.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MK', 1, 'retirement_age_default', 64, NULL, 'sourced', 'Wikipedia, Retirement age (country table, North Macedonia 2026)', 'https://en.wikipedia.org/wiki/Retirement_age', '2026-10-31', 'Men 64, women 62, with at least 15 years of pension service; secondary source because the Pension and Disability Insurance Fund (piom.com.mk) site could not be reached. No legislated increase for later cohorts was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MK', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'No separate retirement age for public employees could be confirmed from a readable official source; public servants are generally covered by the same pension insurance (men 64, women 62).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MK', 1, 'retirement_return_base', 0.026, NULL, 'assumption', 'Average deposit rate 2.72% in 2025 (World Bank FR.INR.DPST), interest tax-free', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=MK', '2026-10-31', 'Base case kept just below the tax-free average deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MK', 1, 'retirement_return_high', 0.035, NULL, 'assumption', 'Citizen bond 4.5% coupon (Dec 2025), tax-exempt', 'https://biznis.rs/novac/severna-makedonija-izdaje-trecu-gradjansku-obveznicu-u-ukupnom-iznosu-od-100-miliona-denara/', '2026-10-31', 'High case: a mix of citizen bonds and term deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MK', 1, 'retirement_return_low', 0.015, NULL, 'assumption', 'Average deposit rate 2.72% in 2025 (World Bank), falling in 2026', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=MK', '2026-10-31', 'Low case: mostly sight and short deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MK', 1, 'sanchayapatra_5y_rate', 0.045, NULL, 'sourced', 'biznis.rs news report on the third citizen bond (gradjanska obveznica) issue of North Macedonia', 'https://biznis.rs/novac/severna-makedonija-izdaje-trecu-gradjansku-obveznicu-u-ukupnom-iznosu-od-100-miliona-denara/', '2025-12-12', '2-year denar citizen bond sold to individuals through banks (auction 12 Dec 2025, matures 19 Dec 2027), 4.5% annual coupon, minimum MKD 10,000; the second issue (Nov 2023) paid 5%. No 5-year retail bond exists.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MK', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No current rate for ordinary denar savings or sight deposits could be read: the National Bank''s interest-rate statistics (nbrm.mk) served a bot check.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MK', 1, 'support_ratio', NULL, '{"points":[{"year":2026,"value":3.41},{"year":2040,"value":2.59},{"year":2065,"value":1.77}]}', 'sourced', 'UN WPP 2024 medium variant via populationpyramid.net (old-age dependency ratio)', 'https://www.populationpyramid.net/tfyr-macedonia/2040/', '2026-01-01', '100 / old-age dependency ratio: 29.3 (2026), 38.6 (2040) and 56.4 (2065, populationpyramid.net/tfyr-macedonia/2065/). World Bank 2025: 28.5.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MK', 1, 'tax_bank_interest', 0, NULL, 'sourced', 'PwC Worldwide Tax Summaries, North Macedonia income determination', 'https://taxsummaries.pwc.com/north-macedonia/individual/income-determination', '2026-07-23', 'Interest on time savings is in principle taxed at 10%, but taxation is postponed until EU accession; interest on call deposits is exempt.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MK', 1, 'tax_sanchayapatra_profit', 0, NULL, 'sourced', 'PwC Worldwide Tax Summaries, North Macedonia income determination', 'https://taxsummaries.pwc.com/north-macedonia/individual/income-determination', '2026-07-23', 'Interest on bonds issued by the state and local government units and on public loans is exempt.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MK', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No current 3-month treasury bill yield was found: recent Ministry of Finance auctions reported in the news are 1-year bills, and the National Bank''s auction pages served a bot check.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MK', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No current 10-year government bond yield could be read (National Bank auction pages blocked, no market quote on Trading Economics).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MK', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No current 5-year government bond yield could be read (National Bank auction pages blocked, no market quote on Trading Economics).', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('ML', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"ML","iso3":"MLI","nameEn":"Mali","nameNative":"Mali","region":"sub_saharan_africa","languages":["bm","fr","ff","snk","ses"],"currency":{"code":"XOF","symbol":"F CFA","decimals":0,"compact":"intl","usdRate":{"value":589,"status":"sourced","sourceName":"BCEAO, rates of foreign currencies against the CFA franc for transfers, 30 October 2026","sourceUrl":"https://www.bceao.int/fr/cours/cours-des-devises-contre-Franc-CFA-appliquer-aux-transferts","asOf":"2026-10-30","note":"Mid-point of the buying (585.50) and selling (592.50) rates for the US dollar; the CFA franc is pegged at 655.957 per euro. World Bank 2025 average 581.9. The same page showed 582.50 / 589.50 (mid 586) on 2 November 2026."}},"instruments":{"savings_account":{"available":true,"localName":"Compte d''épargne","localNameEn":"Savings account"},"fdr_3m":{"available":true,"localName":"Dépôt à terme","localNameEn":"Term deposit (DAT)","note":"Banks declare minimum and maximum term-deposit rates to the BCEAO twice a year.","sourceUrl":"https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf"},"fdr_1y":{"available":true,"localName":"Dépôt à terme","localNameEn":"Term deposit (DAT), 1 year","note":"Banks declare minimum and maximum term-deposit rates to the BCEAO twice a year.","sourceUrl":"https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf"},"dps":{"available":true,"localName":"Épargne contractuelle","localNameEn":"Contractual savings plan","note":"Monthly savings plans (housing or project savings) offered by banks.","sourceUrl":"https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf"},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate for individuals was found."},"tbill_91d":{"available":false,"localName":null,"localNameEn":null,"note":"Mali''s Treasury issued only 6-month and 12-month bills (bons assimilables du Trésor) on the regional market in 2026.","sourceUrl":"https://www.umoatitres.org/fr/pays/mali/"},"tbond_5y":{"available":true,"localName":"Obligations assimilables du Trésor","localNameEn":"Treasury bonds (OAT)","note":"Auctioned every two weeks by UMOA-Titres in 3 and 5-year lines; individuals buy through banks or licensed brokers (SGI).","sourceUrl":"https://www.umoatitres.org/fr/emission/emission-simultanee-de-bons-et-dobligations-du-tresor-du-mali-du-28-10-2026/"},"tbond_10y":{"available":false,"localName":null,"localNameEn":null,"note":"No bond longer than 7 years was auctioned in 2026.","sourceUrl":"https://www.umoatitres.org/fr/pays/mali/"},"equity_fund":{"available":true,"localName":"OPCVM (FCP, SICAV)","localNameEn":"Collective investment funds","note":"Supervised by the regional financial market authority (AMF-UMOA); equity funds invest on the regional exchange (BRVM)."},"gold":{"available":true,"localName":"Sanu","localNameEn":"Gold","note":"Mali is a major gold producer; gold is mainly bought as jewellery, bars and coins are uncommon for savers."}},"institutions":{"centralBank":{"name":"Banque Centrale des États de l''Afrique de l''Ouest (BCEAO)","url":"https://www.bceao.int/"},"insuranceRegulator":{"name":"Commission Régionale de Contrôle des Assurances (CIMA)","url":"https://cima-afrique.org/","note":"Regional insurance regulator for the CIMA member states; national supervision sits with the Treasury in the Ministry of Economy and Finance."},"insuranceComplaints":null,"pensionScheme":{"name":"Institut National de Prévoyance Sociale (INPS), old-age pension","url":"https://www.inps.ml/","note":"Private-sector pension fund; its site did not respond during research (31 October 2026). Civil servants are covered by the Caisse Malienne de Sécurité Sociale (https://cmss.ml/fonctionnaire/)."},"oldAgeAllowance":null,"publicHealthCover":{"name":"Caisse Nationale d''Assurance Maladie (CANAM), compulsory health insurance (AMO)","url":"https://www.canam.ml/index.php/accueil/amo"},"depositInsurance":{"name":"Fonds de Garantie des Dépôts et de Résolution dans l''UMOA (FGDR-UMOA)","url":"https://www.fgd-umoa.org/a-propos/missions/"},"statistics":{"name":"Institut National de la Statistique (INSTAT)","url":"https://www.instat-mali.org/fr"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ML', 1, 'bank_deposit_avg_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No Mali-level average deposit rate was found: the BCEAO September 2026 economic note gives only the UMOA-wide average (5.15% in July 2026) and says Mali''s rate fell 0.19 points in the month without giving its level; the World Bank''s last Mali figure (6.9%) is for 2016.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ML', 1, 'credit_card_rate_cap', 0.14, NULL, 'sourced', 'BCEAO, conditions débitrices of UMOA credit institutions, first half 2026 (Mali)', 'https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf', '2026-06-30', 'Maximum lending rate (taux débiteur maximum) declared by most Mali banks for the first half of 2026 (range 12-14% at banks); it applies to all bank credit, including cards. No card-specific rate is published.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ML', 1, 'deposit_insurance_limit', 1400000, NULL, 'sourced', 'UMOA Council of Ministers, Decision of 30 June 2017 on FGD-UMOA contribution rates and compensation ceilings (Article 2)', 'https://www.fgd-umoa.org/wp-content/uploads/2024/10/Decision-du-CM-relative-aux-taux-de-contribution-et-aux-plafonds-d-indemnistation-2-1.pdf', '2017-06-30', 'Deposits are guaranteed up to 1,400,000 FCFA per depositor per bank (300,000 FCFA at a microfinance institution) by the regional deposit guarantee fund; the decision dates from 2017 (older than 2025) and is still the one the fund publishes.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ML', 1, 'dps_rate', 0.035, NULL, 'sourced', 'BCEAO, conditions créditrices of UMOA credit institutions, first half 2026 (Mali)', 'https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf', '2026-06-30', 'Median rate on contractual savings plans (épargne contractuelle) declared by Mali''s banks in the first half of 2026; most declare 3.50% (range 3.25-4.0%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ML', 1, 'equity_return_base', 0.075, NULL, 'assumption', 'BCEAO monthly economic note, September 2026; UMOA-Titres Mali auction of 28 October 2026', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-10-31', 'Base case: about 3 points above 1-year Treasury bills (4.5%) and term deposits, within the 4-point cap; the BRVM composite rose 60.7% in the year to August 2026 but its 10-year record is uneven.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ML', 1, 'equity_return_high', 0.12, NULL, 'assumption', 'BCEAO monthly economic note, September 2026 (BRVM indices)', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-10-31', 'High case: the BRVM repeats a strong decade like 2023-2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ML', 1, 'equity_return_low', 0.04, NULL, 'assumption', 'BCEAO monthly economic note, September 2026 (regional stock exchange BRVM, deposit rates)', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-10-31', 'Low case: regional (BRVM) equities, where Mali investors buy shares, return about the bank deposit rate, as in their weak 2016-2020 years.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ML', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The BCEAO bank-conditions survey gives only minimum (median 3.5%) and maximum (median 6.2%, range 5.65-7.0%) term-deposit rates per bank in Mali for the first half of 2026, not a 1-year rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ML', 1, 'fdr_3m_rate', 0.035, NULL, 'sourced', 'BCEAO, conditions créditrices of UMOA credit institutions, first half 2026 (Mali)', 'https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf', '2026-06-30', 'Median of the minimum term-deposit rates (taux DAT minimum) declared by Mali''s 14 banks to the BCEAO, range 2.0-4.0%; the minimum usually applies to small, short deposits. Not a tenor-specific average.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ML', 1, 'fixed_income_return_base', 0.045, NULL, 'assumption', 'BCEAO bank conditions, first half 2026 (Mali); UMOA-Titres Mali auction of 28 October 2026 (1-year bill 4.51%)', 'https://www.umoatitres.org/fr/emission/emission-simultanee-de-bons-et-dobligations-du-tresor-du-mali-du-28-10-2026/', '2026-10-31', 'Base case: 1-year Treasury bills (4.5%) or larger term deposits (median maximum 6.2%) through a bank, rounded down because the tax on interest is unconfirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ML', 1, 'fixed_income_return_high', 0.065, NULL, 'assumption', 'UMOA-Titres, Mali auction of 28 October 2026 (3-year 7.67%, 5-year 7.58%)', 'https://www.umoatitres.org/fr/emission/emission-simultanee-de-bons-et-dobligations-du-tresor-du-mali-du-28-10-2026/', '2026-10-31', 'High case: 3-5 year Treasury bonds at about 7.6%, less a possible tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ML', 1, 'fixed_income_return_low', 0.03, NULL, 'assumption', 'BCEAO, conditions créditrices of UMOA credit institutions, first half 2026 (Mali)', 'https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf', '2026-10-31', 'Low case: small term deposits or contractual savings at the 3.5% floor rate, less a possible tax on interest.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ML', 1, 'goal_inflation_education', 0.045, NULL, 'assumption', 'BCEAO monthly economic note, September 2026; inflation assumption 2.5%', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-10-31', 'No national education CPI series was read; private school fees usually rise faster than general prices, so 2 points above the 2.5% inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ML', 1, 'goal_inflation_health', 0.04, NULL, 'assumption', 'BCEAO monthly economic note, September 2026; inflation assumption 2.5%', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-10-31', 'No national medical CPI series was read; private medical costs usually rise faster than general prices, so 1.5 points above the 2.5% inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ML', 1, 'gold_return_base', 0.045, NULL, 'assumption', 'BCEAO exchange rates (CFA franc pegged at 655.957 per euro)', 'https://www.bceao.int/fr/cours/cours-des-devises-contre-Franc-CFA-appliquer-aux-transferts', '2026-10-31', 'Base case: the long-run dollar gold trend of about 4% a year plus a small allowance for the euro-pegged franc weakening against the dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ML', 1, 'gold_return_high', 0.08, NULL, 'assumption', 'BCEAO exchange rates', 'https://www.bceao.int/fr/cours/cours-des-devises-contre-Franc-CFA-appliquer-aux-transferts', '2026-10-31', 'High case: strong gold years such as 2024-2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ML', 1, 'gold_return_low', 0, NULL, 'assumption', 'BCEAO exchange rates (CFA franc pegged to the euro)', 'https://www.bceao.int/fr/cours/cours-des-devises-contre-Franc-CFA-appliquer-aux-transferts', '2026-10-31', 'Low case: flat gold in euro terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ML', 1, 'gratuity_rule', NULL, '{"daysPerYear":6,"daysPerYearAfter":7.5,"afterYears":10,"daysPerMonth":30}', 'sourced', 'WageIndicator, Mali notice and severance (Labour Code 1992, Law 92-020, articles 53-55)', 'https://wageindicator.org/fr-ml/travail-au-mali/droit-du-travail/contrats-et-licenciements/preavis-et-indemnite-de-depart/', '2026-03-30', 'Secondary source. On retirement the worker gets a retirement indemnity on the severance basis: average monthly pay of the last 12 months x 20% per year for years 1-5, 25% for years 6-10 and 30% beyond 10 (6, 7.5 and 9 days a year). Approximated as 6 days a year, 7.5 for all years once service exceeds 10, which is close to the law at 11-20 years.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ML', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a major private hospital stay in Mali was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ML', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premiums by age were found from a public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ML', 1, 'inflation_cpi', 0.033, NULL, 'sourced', 'BCEAO, monthly economic note for UMOA countries, September 2026 (harmonised consumer prices, August 2026)', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-08-31', 'Consumer prices up 3.3% year on year in Mali in August 2026 after 2.8% in July (INSTAT data via BCEAO); 2025 average 3.3% (World Bank).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ML', 1, 'inflation_projection', 0.025, NULL, 'assumption', 'BCEAO inflation target (1-3% band, centre 2%); Mali CPI 3.3% in August 2026 and 3.3% in 2025', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-10-31', 'The CFA franc is pegged to the euro and the BCEAO targets 1-3%, but Mali''s inflation has run slightly above the centre (3.3% in 2025 and August 2026), so 2.5% is used for long-range plans.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ML', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Temporary death cover is sold under the CIMA code, but no published premium rates per 1,000 FCFA of cover by age were found from a public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ML', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'CIMA (the regional insurance regulator) and Mali''s Treasury insurance division publish no industry-wide life claim settlement ratio that could be found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ML', 1, 'life_expectancy', 60.675, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN), Mali', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=ML', '2024-12-31', '60.7 years in 2024 (men 59.3, women 62.2); UN WPP 2024 gives 61.1 for 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ML', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":15.8,"men":15.2,"women":16.3},{"age":65,"total":12.4,"men":11.9,"women":12.8},{"age":70,"total":9.3,"men":9,"women":9.6},{"age":80,"total":4.8,"men":4.6,"women":4.9}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/mali/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ML', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension was found (see old_age_allowance_monthly).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ML', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension for Mali was found; the INPS ''allocation de vieillesse'' (52% of the minimum wage from 53 with at least 6 years of insurance) is contributory, not a social pension.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ML', 1, 'oop_health_share', 0.4723, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), Mali', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=ML', '2023-12-31', '47.2% in 2023 (WHO Global Health Expenditure Database); older than 2025, the latest available.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ML', 1, 'policy_rate', 0.03, NULL, 'sourced', 'BCEAO, monthly economic note for UMOA countries, September 2026 (Monetary Policy Committee of 9 September 2026)', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-09-09', 'Main policy rate (refinancing rate) 3.00%, held on 9 September 2026; the marginal lending facility rate is 5.00%. Common to all eight UMOA countries.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ML', 1, 'public_pension_scheme', NULL, '{"pensionFromAge":58,"entryAgeMin":null,"entryAgeMax":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'WageIndicator, Mali social security (Social Security Code 1999, articles 142-162)', 'https://wageindicator.org/fr-ml/travail-au-mali/droit-du-travail/securite-sociale/', '2026-03-30', 'Compulsory INPS pension for private employees from 58 with at least 13 years of contributions: 26% of average pay over the last 8 years plus 2% per year beyond 10 years, up to 80%; paid quarterly. No automatic indexation rule was found, so inflationLinked is false. Secondary source; the INPS site was unreachable.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ML', 1, 'retirement_accumulation_return_base', 0.06, NULL, 'assumption', 'UMOA-Titres Mali auction results; equity base 7.5%; gold base 4.5%', 'https://www.umoatitres.org/fr/emission/emission-simultanee-de-bons-et-dobligations-du-tresor-du-mali-du-28-10-2026/', '2026-10-31', 'Base case: a balanced mix of deposits or Treasury bonds, regional equity funds and some gold.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ML', 1, 'retirement_accumulation_return_high', 0.08, NULL, 'assumption', 'UMOA-Titres Mali auction results; equity high 12%', 'https://www.umoatitres.org/fr/emission/emission-simultanee-de-bons-et-dobligations-du-tresor-du-mali-du-28-10-2026/', '2026-10-31', 'High case: a growth-leaning mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ML', 1, 'retirement_accumulation_return_low', 0.035, NULL, 'assumption', 'BCEAO, conditions créditrices of UMOA credit institutions, first half 2026 (Mali)', 'https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf', '2026-10-31', 'Low case: a mix earning about after-tax deposit rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ML', 1, 'retirement_age_default', 58, NULL, 'sourced', 'WageIndicator, Mali social security (Social Security Code 1999 art. 142-162; Labour Code art. 60; Law 2019-025)', 'https://wageindicator.org/fr-ml/travail-au-mali/droit-du-travail/securite-sociale/', '2026-03-30', 'Secondary source (INPS site unreachable): old-age pension at 58 with at least 13 years of contributions, early from 53; a woman''s age is reduced one year per child. Law 2019-025 lets category A staff work on to 62 and B-D to 60 by agreement. No newer rule for people born after 1975 was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ML', 1, 'retirement_age_government', 62, NULL, 'sourced', 'Caisse Malienne de Sécurité Sociale (CMSS), civil servants'' pension', 'https://cmss.ml/fonctionnaire/', '2026-10-31', 'Pension (liquidation) age by grade: 58 for category C, 61 for B1, 62 for B2 and 65 for A, after 15-40 years of contributions; 62 (B2, the middle grade) is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ML', 1, 'retirement_return_base', 0.04, NULL, 'assumption', 'UMOA-Titres, Mali auction of 28 October 2026 (364-day bill 4.51%)', 'https://www.umoatitres.org/fr/emission/emission-simultanee-de-bons-et-dobligations-du-tresor-du-mali-du-28-10-2026/', '2026-10-31', 'Base case: below the 1-year Treasury bill yield (4.51%) to allow for a possible tax; not above the safe rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ML', 1, 'retirement_return_high', 0.055, NULL, 'assumption', 'UMOA-Titres, Mali auction of 28 October 2026 (3-year bond 7.67%)', 'https://www.umoatitres.org/fr/emission/emission-simultanee-de-bons-et-dobligations-du-tresor-du-mali-du-28-10-2026/', '2026-10-31', 'High case: part of the money in larger term deposits or short Treasury bonds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ML', 1, 'retirement_return_low', 0.03, NULL, 'assumption', 'BCEAO, conditions créditrices of UMOA credit institutions, first half 2026 (Mali)', 'https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf', '2026-10-31', 'Low case: small term deposits or contractual savings at about 3.5%, less a possible tax on interest.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ML', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate sold to individuals was found; the Treasury borrows through UMOA-Titres auctions of 1-year bills and 3-5 year bonds, which individuals can buy through banks and licensed brokers (SGI).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ML', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No average rate on ordinary savings accounts in Mali was found; the BCEAO bank-conditions survey (first half 2026) lists term-deposit and contractual-savings rates only.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ML', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":21.94},{"year":2040,"value":21.28},{"year":2065,"value":14.08}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/mali/2040/', '2025-12-31', '100 / old-age dependency ratio: 4.56 (2025, World Bank), 4.7 (2040) and 7.1 (2065, populationpyramid.net/mali/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ML', 1, 'tax_bank_interest', NULL, NULL, 'missing', '', '', '2026-10-31', 'The tax authority (DGI) lists deposit interest as taxable under the tax on securities income (IRVM) but its page gives no rate, the online tax code could not be read, and PwC Tax Summaries has no Mali page.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ML', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate exists, and the auction notices for Mali Treasury securities state no tax regime for individuals.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ML', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Mali''s Treasury issued 6-month and 12-month bills on the regional market in 2026 (last: 364-day bill at a 4.51% average yield on 28 October 2026); no 3-month bill rate exists.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ML', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Mali auctioned no bond longer than 7 years in 2026 (longest line matures April 2033), so no 10-year yield exists.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ML', 1, 'tbond_5y_rate', 0.0758, NULL, 'sourced', 'UMOA-Titres, Mali Treasury auction of 28 October 2026 (5-year bond)', 'https://www.umoatitres.org/fr/emission/emission-simultanee-de-bons-et-dobligations-du-tresor-du-mali-du-28-10-2026/', '2026-10-28', 'Weighted average yield 7.58% on the 6.20% bond maturing 29 October 2031; the 3-year bond in the same auction yielded 7.67%.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('MM', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"MM","iso3":"MMR","nameEn":"Myanmar","nameNative":"မြန်မာ","region":"east_asia_pacific","languages":["my","en"],"currency":{"code":"MMK","symbol":"K","decimals":0,"compact":"intl","usdRate":{"value":3782.65,"status":"sourced","sourceName":"Central Bank of Myanmar, Activities of Interbank Foreign Exchange Market for 30.10.2026 (bank-customer dealing, day weighted average rate)","sourceUrl":"https://www.cbm.gov.mm/sites/default/files/inline-files/Activities%20of%20Interbank%20%20for-%2030.10.2026_0.pdf","asOf":"2026-10-30","note":"Day weighted average of bank-customer USD trades (traded range 2,106-3,995); the CBM reference rate is fixed at 2,100 but most transactions use the market rate (CSO lists a money-changer rate of 3,670)."}},"instruments":{"savings_account":{"available":true,"localName":"ငွေစုစာရင်း","localNameEn":"Savings account","sourceUrl":"https://www.cbm.gov.mm/"},"fdr_3m":{"available":true,"localName":"ပုံသေငွေအပ်စာရင်း","localNameEn":"Fixed deposit","note":"Banks must pay at least the 7% CBM minimum deposit rate.","sourceUrl":"https://www.cbm.gov.mm/"},"fdr_1y":{"available":true,"localName":"ပုံသေငွေအပ်စာရင်း","localNameEn":"Fixed deposit","note":"Banks must pay at least the 7% CBM minimum deposit rate.","sourceUrl":"https://www.cbm.gov.mm/"},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No monthly recurring deposit scheme found."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No current government savings certificate or retail savings bond found."},"tbill_91d":{"available":true,"localName":"ငွေတိုက်လက်မှတ်","localNameEn":"Treasury bill","note":"Auctioned by the CBM, mainly to banks.","sourceUrl":"https://www.cbm.gov.mm/sites/default/files/inline-files/T-Bill%20List%20%26%20Graph%20%2814.6.23%29_1.pdf"},"tbond_5y":{"available":true,"localName":"ငွေတိုက်စာချုပ်","localNameEn":"Treasury bond","note":"2- to 5-year bonds auctioned by the CBM.","sourceUrl":"https://www.cbm.gov.mm/sites/default/files/inline-files/T-Bond%20List%20%26%20Graph%20%2814.6.23%29_2.pdf"},"tbond_10y":{"available":false,"localName":null,"localNameEn":null,"note":"No 10-year government bond issued."},"equity_fund":{"available":false,"localName":null,"localNameEn":null,"note":"No retail mutual or index funds; the Yangon Stock Exchange has only a few listed shares."},"gold":{"available":true,"localName":"ရွှေ","localNameEn":"Gold","note":"Gold is widely bought at gold shops; the CSO publishes the 24-carat price per tikal.","sourceUrl":"https://www.csostat.gov.mm/Statistics/MarketPrice"}},"institutions":{"centralBank":{"name":"Central Bank of Myanmar (CBM)","url":"https://www.cbm.gov.mm/"},"insuranceRegulator":null,"insuranceComplaints":null,"pensionScheme":{"name":"Social Security Board, Ministry of Labour","url":"https://www.ssb.gov.mm/"},"oldAgeAllowance":null,"publicHealthCover":{"name":"Ministry of Health (public hospitals)","url":"https://www.mohs.gov.mm/"},"depositInsurance":null,"statistics":{"name":"Central Statistical Organization (CSO)","url":"https://www.csostat.gov.mm/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MM', 1, 'bank_deposit_avg_rate', 0.0583, NULL, 'sourced', 'World Bank WDI, deposit interest rate (FR.INR.DPST)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=MM', '2020-12-31', '5.83% for 2020, the latest World Bank figure (older than 2025); the CBM minimum deposit rate has since risen from 5% to 7%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MM', 1, 'credit_card_rate_cap', 0.15, NULL, 'sourced', 'Central Bank of Myanmar, maximum bank lending rate (home page)', 'https://www.cbm.gov.mm/', '2026-10-31', 'CBM caps bank lending rates at 15% a year (home page rates panel); we treat this general cap as the ceiling on bank card credit, as no card-specific rule was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MM', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'We could not find an official page describing a deposit insurance scheme or limit for Myanmar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MM', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No monthly recurring deposit scheme or published rate found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MM', 1, 'equity_return_base', 0.09, NULL, 'assumption', 'CBM minimum deposit rate 7% (untaxed) plus a small premium', 'https://www.cbm.gov.mm/', '2026-10-31', 'Thin market with a weak 10-year record, so base set only 2 points above the 7% safe deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MM', 1, 'equity_return_high', 0.14, NULL, 'assumption', 'CBM minimum deposit rate plus a full equity premium', 'https://www.cbm.gov.mm/', '2026-10-31', 'High case if listings deepen and returns keep pace with inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MM', 1, 'equity_return_low', 0.03, NULL, 'assumption', 'Yangon Stock Exchange record; CBM deposit floor', 'https://www.cbm.gov.mm/', '2026-10-31', 'The Yangon Stock Exchange has very few listings and a weak record, so the low case is far below deposit rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MM', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Bank fixed deposit rate pages could not be read; the CBM minimum deposit rate is 7%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MM', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Bank fixed deposit rate pages could not be read; the CBM minimum deposit rate is 7%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MM', 1, 'fixed_income_return_base', 0.07, NULL, 'assumption', 'CBM minimum deposit rate (7%, untaxed for residents)', 'https://www.cbm.gov.mm/', '2026-10-31', 'Base case at the 7% deposit floor. Safe MMK rates: CBM minimum bank deposit rate 7% (central bank rate 9%); last published auction yields 6.0% for 3-month bills and 8.5% for 3.5-5.5-year bonds (May 2023); no withholding tax on interest for residents.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MM', 1, 'fixed_income_return_high', 0.085, NULL, 'assumption', 'Treasury bond auction yields (CBM)', 'https://www.cbm.gov.mm/sites/default/files/inline-files/T-Bond%20List%20%26%20Graph%20%2814.6.23%29_2.pdf', '2026-10-31', 'High case near the last published 5-year bond yield. Safe MMK rates: CBM minimum bank deposit rate 7% (central bank rate 9%); last published auction yields 6.0% for 3-month bills and 8.5% for 3.5-5.5-year bonds (May 2023); no withholding tax on interest for residents.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MM', 1, 'fixed_income_return_low', 0.06, NULL, 'assumption', 'Treasury bill auction yields (CBM)', 'https://www.cbm.gov.mm/sites/default/files/inline-files/T-Bill%20List%20%26%20Graph%20%2814.6.23%29_1.pdf', '2026-10-31', 'Low case near the last published 3-month bill yield. Safe MMK rates: CBM minimum bank deposit rate 7% (central bank rate 9%); last published auction yields 6.0% for 3-month bills and 8.5% for 3.5-5.5-year bonds (May 2023); no withholding tax on interest for residents.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MM', 1, 'goal_inflation_education', 0.13, NULL, 'assumption', 'IMF WEO CPI projections; no education CPI read', 'https://www.imf.org/external/datamapper/PCPIPCH@WEO/MMR', '2026-10-31', 'We plan 1 point above long-run inflation for private school and tuition fees.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MM', 1, 'goal_inflation_health', 0.14, NULL, 'assumption', 'IMF WEO CPI projections; no medical CPI read', 'https://www.imf.org/external/datamapper/PCPIPCH@WEO/MMR', '2026-10-31', 'With 71% of health spending out of pocket and many medicines imported, we plan 2 points above long-run inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MM', 1, 'gold_return_base', 0.13, NULL, 'assumption', 'US-dollar gold trend plus expected kyat depreciation; CSO market prices (24-carat gold about MMK 7 million per tikal, kyat about 3,600-3,800 per dollar)', 'https://www.csostat.gov.mm/Statistics/MarketPrice', '2026-10-31', 'About 4% dollar gold trend plus about 9% a year kyat depreciation from the inflation gap with the US.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MM', 1, 'gold_return_high', 0.2, NULL, 'assumption', 'US-dollar gold trend plus expected kyat depreciation', 'https://www.csostat.gov.mm/Statistics/MarketPrice', '2026-10-31', 'High case for a strong gold cycle with fast kyat depreciation, as in 2021-2024.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MM', 1, 'gold_return_low', 0.06, NULL, 'assumption', 'US-dollar gold trend; kyat market rate (CSO statistics overview)', 'https://www.csostat.gov.mm/Statistics/MarketPrice', '2026-10-31', 'Low case if gold stalls in dollars and the kyat holds near its current market rate of about 3,700-3,800 per dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MM', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No statutory gratuity per year of service for private employees found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MM', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a major private hospital stay found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MM', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premiums by age found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MM', 1, 'inflation_cpi', 0.246, NULL, 'sourced', 'World Bank Myanmar Economic Monitor press release (16 June 2026)', 'https://www.worldbank.org/en/news/press-release/2026/06/16/myanmar-s-economy-shows-tentative-stabilization-but-fuel-shock-intensifies-pressures', '2026-04-30', '24.6% year on year in April 2026 after a fuel-price shock; the CSO''s own series (via Trading Economics) stops at Q2 2023. IMF WEO: 21.1% for 2025, 20% forecast for 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MM', 1, 'inflation_projection', 0.12, NULL, 'assumption', 'IMF WEO projections (16% in 2027, 10% in 2028, 7.8% from 2029); no credible inflation target', 'https://www.imf.org/external/datamapper/PCPIPCH@WEO/MMR', '2026-10-31', 'CPI averaged over 20% in 2022-2025 and the IMF expects a slow decline, so we plan with 12% as a long-run average.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MM', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published term life premium rates in kyat found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MM', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No claim settlement ratio published by the insurance supervisor found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MM', 1, 'life_expectancy', 67.1, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN)', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=MM', '2024-12-31', 'Men 64.0, women 70.4 (2024); UN WPP 2026 gives 67.5.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MM', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":16.9,"men":15.5,"women":18.1},{"age":65,"total":13.5,"men":12.3,"women":14.4},{"age":70,"total":10.4,"men":9.5,"women":11.1},{"age":80,"total":5.7,"men":5.3,"women":6}]}', 'sourced', 'UN World Population Prospects (via georank.org)', 'https://georank.org/life-expectancy/myanmar', '2026-07-08', 'Remaining years derived from expected age at death by current age; secondary source because the WHO GHO API was unavailable.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MM', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'Current age rules for the social pension could not be confirmed from an official page.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MM', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Department of Social Welfare site refused access, so we could not confirm whether a social pension is paid or its amount.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MM', 1, 'oop_health_share', 0.711, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure, SH.XPD.OOPC.CH.ZS)', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=MM', '2023-12-31', NULL, 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MM', 1, 'policy_rate', 0.09, NULL, 'sourced', 'Central Bank of Myanmar, Central Bank Rate (home page)', 'https://www.cbm.gov.mm/', '2026-10-31', '9% a year, shown in the rates panel of the CBM home page (the only official page we found that shows the current rate; the CBM interest-rate statistics file stops in January 2023 at 7%). CBM also sets a 7% minimum deposit rate and a 15% maximum lending rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MM', 1, 'public_pension_scheme', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Social Security Board site was not reachable; we could not confirm the terms or operation of the old-age pension under the Social Security Law 2012.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MM', 1, 'retirement_accumulation_return_base', 0.08, NULL, 'assumption', 'Mix of kyat deposits, gold and local equity', 'https://www.cbm.gov.mm/', '2026-10-31', 'About half growth assets at 9% and half deposits at 7%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MM', 1, 'retirement_accumulation_return_high', 0.11, NULL, 'assumption', 'Mix of kyat deposits, gold and local equity', 'https://www.cbm.gov.mm/', '2026-10-31', 'About 60% growth assets at the high case and 40% bonds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MM', 1, 'retirement_accumulation_return_low', 0.05, NULL, 'assumption', 'Mix of kyat deposits, gold and local equity', 'https://www.cbm.gov.mm/', '2026-10-31', 'About 40% growth assets at the low case, 60% deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MM', 1, 'retirement_age_default', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Social Security Board site was not reachable; the old-age pension under the Social Security Law 2012 has not been confirmed as in operation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MM', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'No reachable official page with the civil-service retirement age found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MM', 1, 'retirement_return_base', 0.07, NULL, 'assumption', 'CBM minimum deposit rate (7%, untaxed for residents)', 'https://www.cbm.gov.mm/', '2026-10-31', 'Base case at the 7% deposit floor, the after-tax safe rate. Safe MMK rates: CBM minimum bank deposit rate 7% (central bank rate 9%); last published auction yields 6.0% for 3-month bills and 8.5% for 3.5-5.5-year bonds (May 2023); no withholding tax on interest for residents.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MM', 1, 'retirement_return_high', 0.08, NULL, 'assumption', 'Treasury bond auction yields (CBM)', 'https://www.cbm.gov.mm/sites/default/files/inline-files/T-Bond%20List%20%26%20Graph%20%2814.6.23%29_2.pdf', '2026-10-31', 'High case between the deposit floor and bond yields. Safe MMK rates: CBM minimum bank deposit rate 7% (central bank rate 9%); last published auction yields 6.0% for 3-month bills and 8.5% for 3.5-5.5-year bonds (May 2023); no withholding tax on interest for residents.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MM', 1, 'retirement_return_low', 0.06, NULL, 'assumption', 'Treasury bill auction yields (CBM)', 'https://www.cbm.gov.mm/sites/default/files/inline-files/T-Bill%20List%20%26%20Graph%20%2814.6.23%29_1.pdf', '2026-10-31', 'Low case near the last published 3-month bill yield. Safe MMK rates: CBM minimum bank deposit rate 7% (central bank rate 9%); last published auction yields 6.0% for 3-month bills and 8.5% for 3.5-5.5-year bonds (May 2023); no withholding tax on interest for residents.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MM', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No current government savings certificate or retail savings bond for individuals found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MM', 1, 'savings_account_rate', 0.07, NULL, 'sourced', 'Central Bank of Myanmar, minimum bank deposit rate (home page)', 'https://www.cbm.gov.mm/', '2026-10-31', 'CBM sets a 7% floor on bank deposit rates; savings accounts at large banks typically pay at or near the floor.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MM', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":9.1},{"year":2040,"value":6.2},{"year":2065,"value":3.8}]}', 'sourced', 'UN World Population Prospects 2024, medium variant (via populationpyramid.net); World Bank SP.POP.DPND.OL', 'https://www.populationpyramid.net/myanmar/2040/', '2024-07-31', '100 / old-age dependency ratio: OADR 11.0 in 2025 (World Bank SP.POP.DPND.OL), 16.1 in 2040 and 26.0 in 2065 (UN WPP 2024 medium variant via populationpyramid.net).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MM', 1, 'tax_bank_interest', 0, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Myanmar, withholding taxes (reviewed 9 September 2026)', 'https://taxsummaries.pwc.com/myanmar/corporate/withholding-taxes', '2026-09-09', '0% withholding on interest paid to residents (15% for non-residents). Interest counts as business income for resident individuals and is taxed at progressive rates when non-employment income exceeds MMK 4.8 million a year (PwC, income determination).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MM', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate exists.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MM', 1, 'tbill_91d_rate', 0.0599, NULL, 'sourced', 'Central Bank of Myanmar, market weighted average accepted rates at the treasury bill auction (3-month)', 'https://www.cbm.gov.mm/sites/default/files/inline-files/T-Bill%20List%20%26%20Graph%20%2814.6.23%29_1.pdf', '2023-05-31', '5.993% at the second May 2023 auction, the latest figure published on the CBM site (older than 2025; 6-month 6.539%, 12-month 7.315%). The central bank rate has since risen from 7% to 9%, so current yields are likely higher.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MM', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Myanmar issues treasury bonds of up to about 5 years; no 10-year bond found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MM', 1, 'tbond_5y_rate', 0.0849, NULL, 'sourced', 'Central Bank of Myanmar, market weighted average accepted yields at the treasury bond auction (3.5-5.5 years, 7.5% coupon)', 'https://www.cbm.gov.mm/sites/default/files/inline-files/T-Bond%20List%20%26%20Graph%20%2814.6.23%29_2.pdf', '2023-04-30', '8.493% in April 2023 for the 3.5-5.5-year band (7.5% coupon), the latest 5-year-band figure on the CBM site (older than 2025); the central bank rate has since risen from 7% to 9%.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('MN', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"MN","iso3":"MNG","nameEn":"Mongolia","nameNative":"Монгол Улс","region":"east_asia_pacific","languages":["mn","kk","ru","en"],"currency":{"code":"MNT","symbol":"₮","decimals":2,"compact":"intl","usdRate":{"value":3602,"status":"sourced","sourceName":"Bank of Mongolia rate (via Trading Economics)","sourceUrl":"https://tradingeconomics.com/mongolia/currency","asOf":"2026-10-30","note":"Secondary source (Trading Economics, Bank of Mongolia rate) because the Bank of Mongolia rate page renders by script; the Bank of Mongolia home page showed 3,598.99 on 2 November 2026; World Bank average for 2025 was 3,545."}},"instruments":{"savings_account":{"available":true,"localName":"Хугацаагүй хадгаламж","localNameEn":"Demand savings deposit"},"fdr_3m":{"available":true,"localName":"Хугацаатай хадгаламж","localNameEn":"Term deposit","sourceUrl":"https://tradingeconomics.com/mongolia/deposit-interest-rate"},"fdr_1y":{"available":true,"localName":"Хугацаатай хадгаламж","localNameEn":"Term deposit","sourceUrl":"https://tradingeconomics.com/mongolia/deposit-interest-rate"},"dps":{"available":true,"localName":"Хуримтлалын хадгаламж","localNameEn":"Accumulating savings deposit","note":"Banks offer savings plans with regular top-ups; no published average rate."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate or retail savings bond for individuals found."},"tbill_91d":{"available":false,"localName":null,"localNameEn":null,"note":"No current retail treasury bill found."},"tbond_5y":{"available":false,"localName":"Засгийн газрын бонд","localNameEn":"Government bond","note":"No current domestic issue found for individuals."},"tbond_10y":{"available":false,"localName":"Засгийн газрын бонд","localNameEn":"Government bond","note":"No current domestic issue found for individuals."},"equity_fund":{"available":true,"localName":"Хөрөнгө оруулалтын сан","localNameEn":"Investment fund","note":"A few licensed funds and shares trade on the Mongolian Stock Exchange.","sourceUrl":"https://tradingeconomics.com/mongolia/stock-market"},"gold":{"available":true,"localName":"Алт","localNameEn":"Gold","note":"Gold bars are sold by banks and dealers."}},"institutions":{"centralBank":{"name":"Bank of Mongolia (Mongolbank)","url":"https://www.mongolbank.mn/"},"insuranceRegulator":{"name":"Financial Regulatory Commission (FRC)","url":"https://www.frc.mn/"},"insuranceComplaints":{"name":"Financial Regulatory Commission (FRC)","url":"https://www.frc.mn/","note":"Complaints about insurers go to the regulator."},"pensionScheme":{"name":"General Office of Social Insurance","url":"https://www.ndaatgal.mn/"},"oldAgeAllowance":null,"publicHealthCover":{"name":"Health Insurance General Authority","url":"https://emd.gov.mn/"},"depositInsurance":{"name":"Deposit Insurance Corporation of Mongolia","url":"https://www.dicom.mn/"},"statistics":{"name":"National Statistics Office of Mongolia","url":"https://www.1212.mn/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MN', 1, 'bank_deposit_avg_rate', 0.1204, NULL, 'sourced', 'Bank of Mongolia average deposit interest rate (via Trading Economics)', 'https://tradingeconomics.com/mongolia/deposit-interest-rate', '2026-09-30', '12.04% in September 2026 (12.02% in August); World Bank FR.INR.DPST shows 6.6% for 2021.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MN', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap or published typical credit card rate found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MN', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'A mandatory deposit insurance scheme exists (Law on Insurance of Bank Deposits, 2013; Deposit Insurance Corporation of Mongolia), but its website renders by script and we could not read the current limit.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MN', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published rate for monthly recurring deposits found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MN', 1, 'equity_return_base', 0.13, NULL, 'assumption', 'After-tax average deposit rate 10.8% plus a modest premium; MSE TOP-20 record', 'https://tradingeconomics.com/mongolia/stock-market', '2026-10-31', 'Base set about 2 points above the after-tax deposit rate, under the 4-point limit, because the market is small and concentrated despite a strong 10-year run.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MN', 1, 'equity_return_high', 0.18, NULL, 'assumption', 'MSE TOP-20 index record (via Trading Economics)', 'https://tradingeconomics.com/mongolia/stock-market', '2026-10-31', 'High case closer to the index''s strong record of the past decade (+34% in the year to October 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MN', 1, 'equity_return_low', 0.08, NULL, 'assumption', 'MSE TOP-20 index record (via Trading Economics)', 'https://tradingeconomics.com/mongolia/stock-market', '2026-10-31', 'The index rose from a 10,486 low to about 66,800 (Oct 2026) but is volatile and concentrated, so the low case is below the deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MN', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Bank term deposit rate pages could not be read; see bank_deposit_avg_rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MN', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Bank term deposit rate pages could not be read; see bank_deposit_avg_rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MN', 1, 'fixed_income_return_base', 0.105, NULL, 'assumption', 'Bank of Mongolia average deposit rate after 10% tax', 'https://tradingeconomics.com/mongolia/deposit-interest-rate', '2026-10-31', 'Base case just under the after-tax average deposit rate (12.04% x 0.9 = 10.8%). Safe MNT rates: average bank deposit rate 12.04% (Sep 2026, Bank of Mongolia), 10% tax on interest, policy rate 12.5%; no retail treasury bills or savings bonds found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MN', 1, 'fixed_income_return_high', 0.115, NULL, 'assumption', 'Bank of Mongolia average deposit rate and policy rate', 'https://tradingeconomics.com/mongolia/deposit-interest-rate', '2026-10-31', 'High case for longer term deposits above the average rate. Safe MNT rates: average bank deposit rate 12.04% (Sep 2026, Bank of Mongolia), 10% tax on interest, policy rate 12.5%; no retail treasury bills or savings bonds found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MN', 1, 'fixed_income_return_low', 0.08, NULL, 'assumption', 'Bank of Mongolia average deposit rate after 10% tax', 'https://tradingeconomics.com/mongolia/deposit-interest-rate', '2026-10-31', 'Low case if rates fall back as inflation eases. Safe MNT rates: average bank deposit rate 12.04% (Sep 2026, Bank of Mongolia), 10% tax on interest, policy rate 12.5%; no retail treasury bills or savings bonds found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MN', 1, 'goal_inflation_education', 0.08, NULL, 'assumption', 'NSO CPI (via Trading Economics); no education CPI read', 'https://tradingeconomics.com/mongolia/inflation-cpi', '2026-10-31', 'We plan 1 point above long-run inflation for school and university fees.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MN', 1, 'goal_inflation_health', 0.09, NULL, 'assumption', 'NSO CPI (via Trading Economics); no medical CPI read', 'https://tradingeconomics.com/mongolia/inflation-cpi', '2026-10-31', 'With about half of health spending out of pocket, we plan 2 points above long-run inflation for medical costs.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MN', 1, 'gold_return_base', 0.09, NULL, 'assumption', 'US-dollar gold trend plus expected tugrik depreciation', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=MN', '2026-10-31', 'About 4% dollar gold trend plus about 5% a year tugrik depreciation from the inflation gap with the US.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MN', 1, 'gold_return_high', 0.14, NULL, 'assumption', 'US-dollar gold trend plus expected tugrik depreciation', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=MN', '2026-10-31', 'High case for a strong gold cycle with faster depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MN', 1, 'gold_return_low', 0.04, NULL, 'assumption', 'US-dollar gold trend; tugrik depreciation (World Bank PA.NUS.FCRF)', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=MN', '2026-10-31', 'Gold can stall for years; low case assumes little tugrik depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MN', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No statutory gratuity per year of service found; the Labour Law provides severance on dismissal, but we could not read its current terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MN', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a major private hospital stay found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MN', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premiums by age found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MN', 1, 'inflation_cpi', 0.129, NULL, 'sourced', 'National Statistics Office of Mongolia CPI (via Trading Economics)', 'https://tradingeconomics.com/mongolia/inflation-cpi', '2026-09-30', '12.9% year on year in September 2026 (12.5% in August, 13.0% in July); secondary source because the NSO site renders by script.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MN', 1, 'inflation_projection', 0.07, NULL, 'assumption', 'Bank of Mongolia 6% (+/-2) target; IMF WEO projections (6.6-8.2% for 2028-2031)', 'https://www.imf.org/external/datamapper/PCPIPCH@WEO/MNG', '2026-10-31', 'CPI averaged about 9.5% over 2021-2025 and the 6% target is rarely met, so we plan with 7%, in line with IMF medium-term projections.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MN', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published term life premium rates or premium guides in tugrik found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MN', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Financial Regulatory Commission site renders by script; no claim settlement ratio found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MN', 1, 'life_expectancy', 72.4, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN)', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=MN', '2024-12-31', 'Men 67.9, women 77.1 (2024).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MN', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":18.9,"men":16.2,"women":21.1},{"age":65,"total":15.4,"men":13.2,"women":17.2},{"age":70,"total":12.3,"men":10.5,"women":13.6},{"age":80,"total":7,"men":6.1,"women":7.6}]}', 'sourced', 'UN World Population Prospects (via georank.org)', 'https://georank.org/life-expectancy/mongolia', '2026-07-08', 'Remaining years derived from expected age at death by current age; secondary source because the WHO GHO API was unavailable.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MN', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'Eligibility ages for the social welfare pension could not be confirmed from an official page.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MN', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'The social welfare agency site was not reachable, so the amount of any non-contributory pension for elderly people without a social insurance pension could not be confirmed. Minimum contributory old-age pension is MNT 769,000 a month (Social Insurance General Office).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MN', 1, 'oop_health_share', 0.488, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure, SH.XPD.OOPC.CH.ZS)', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=MN', '2023-12-31', NULL, 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MN', 1, 'policy_rate', 0.125, NULL, 'sourced', 'Bank of Mongolia policy rate (via Trading Economics)', 'https://tradingeconomics.com/mongolia/interest-rate', '2026-09-17', 'Raised from 12% to 12.5% in August 2026 and held on 17 September 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MN', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":65,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'General Office of Social Insurance, old-age pension insurance', 'https://www.ndaatgal.mn/daatgal/%d1%82%d1%8d%d1%82%d0%b3%d1%8d%d0%b2%d1%80%d0%b8%d0%b9%d0%bd-%d0%b4%d0%b0%d0%b0%d1%82%d0%b3%d0%b0%d0%bb/', '2026-10-31', 'Social insurance pension: 8.5% employee + 8.5% employer (11.5% for voluntary contributors); pension age rising to 65 for both sexes; full pension needs 22 years 3 months of contributions in 2026, rising to 25 years by 2037 (10-19 years gives a partial pension of 0.1875% of average wage per contribution month); full pension = average wage of the best 60 months in the last 20 years x (45% + 0.125% per month beyond 20 years; 0.167% from 2029); minimum full pension MNT 769,000 a month (partial MNT 652,400). The page describes no automatic inflation indexation, so inflationLinked is false; tax treatment not stated.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MN', 1, 'retirement_accumulation_return_base', 0.115, NULL, 'assumption', 'Mix of tugrik deposits and local equity', 'https://tradingeconomics.com/mongolia/deposit-interest-rate', '2026-10-31', 'About half equity at 13% and half deposits near 10.5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MN', 1, 'retirement_accumulation_return_high', 0.15, NULL, 'assumption', 'Mix of tugrik deposits and local equity', 'https://tradingeconomics.com/mongolia/deposit-interest-rate', '2026-10-31', 'About 60% equity at the high case and 40% deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MN', 1, 'retirement_accumulation_return_low', 0.08, NULL, 'assumption', 'Mix of tugrik deposits and local equity', 'https://tradingeconomics.com/mongolia/deposit-interest-rate', '2026-10-31', 'About 40% equity at the low case, 60% deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MN', 1, 'retirement_age_default', 65, NULL, 'sourced', 'General Office of Social Insurance, old-age pension insurance', 'https://www.ndaatgal.mn/daatgal/%d1%82%d1%8d%d1%82%d0%b3%d1%8d%d0%b2%d1%80%d0%b8%d0%b9%d0%bd-%d0%b4%d0%b0%d0%b0%d1%82%d0%b3%d0%b0%d0%bb/', '2026-10-31', 'Pension age rises with birth year: men from 60 (born 1957 or earlier) to 65 (born 1977 or later); women from 55 (born 1962 or earlier) to 60 for those born 1982, 62 for 1990 and 65 for 2002 or later. 65 applies to men born after 1976; women born 1976-2001 have a lower age (about 58.5-64.75). Early pension on request at 60 (men) or 55 (women) with enough contribution years.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MN', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'No official page with the current civil-service retirement age was readable; civil servants draw the same social insurance pension.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MN', 1, 'retirement_return_base', 0.1, NULL, 'assumption', 'Bank of Mongolia average deposit rate after 10% tax', 'https://tradingeconomics.com/mongolia/deposit-interest-rate', '2026-10-31', 'Base case below the after-tax average deposit rate (10.8%). Safe MNT rates: average bank deposit rate 12.04% (Sep 2026, Bank of Mongolia), 10% tax on interest, policy rate 12.5%; no retail treasury bills or savings bonds found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MN', 1, 'retirement_return_high', 0.11, NULL, 'assumption', 'Bank of Mongolia average deposit rate after 10% tax', 'https://tradingeconomics.com/mongolia/deposit-interest-rate', '2026-10-31', 'High case near the after-tax deposit rate on longer terms. Safe MNT rates: average bank deposit rate 12.04% (Sep 2026, Bank of Mongolia), 10% tax on interest, policy rate 12.5%; no retail treasury bills or savings bonds found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MN', 1, 'retirement_return_low', 0.08, NULL, 'assumption', 'Bank of Mongolia average deposit rate after 10% tax', 'https://tradingeconomics.com/mongolia/deposit-interest-rate', '2026-10-31', 'Low case if deposit rates fall as inflation eases. Safe MNT rates: average bank deposit rate 12.04% (Sep 2026, Bank of Mongolia), 10% tax on interest, policy rate 12.5%; no retail treasury bills or savings bonds found.', 0);
