INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MN', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":11.6},{"year":2040,"value":6.8},{"year":2065,"value":4.4}]}', 'sourced', 'UN World Population Prospects 2024, medium variant (via populationpyramid.net); World Bank SP.POP.DPND.OL', 'https://www.populationpyramid.net/mongolia/2040/', '2024-07-31', '100 / old-age dependency ratio: OADR 8.6 in 2025 (World Bank SP.POP.DPND.OL), 14.8 in 2040 and 22.8 in 2065 (UN WPP 2024 medium variant via populationpyramid.net).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MN', 1, 'tax_bank_interest', 0.1, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Mongolia, taxes on personal income (reviewed 8 June 2026)', 'https://taxsummaries.pwc.com/mongolia/individual/taxes-on-personal-income', '2026-06-08', 'Interest is property income taxed at 10% for residents (withheld at source); 20% for non-residents; a special 5% rate applies to interest on purchased debt instruments.', 0);
