INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('MR', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"MR","iso3":"MRT","nameEn":"Mauritania","nameNative":"موريتانيا","region":"sub_saharan_africa","languages":["ar","mey","fr","ff","wo"],"currency":{"code":"MRU","symbol":"UM","decimals":2,"compact":"intl","usdRate":{"value":40.37,"status":"sourced","sourceName":"Banque Centrale de Mauritanie, reference exchange rate USD/MRU (cours de change de référence)","sourceUrl":"https://connect.bcm.mr/api/cours_change_reference?from=2026-10-29&to=2026-10-29&currency=USD","asOf":"2026-10-29","note":"BCM reference rate of 40.37 ouguiya per dollar on 29 October 2026 (40.07-40.41 during 20-29 October), read from the BCM website data feed; the 2025 average was 39.75."}},"instruments":{"savings_account":{"available":true,"localName":"حساب ادخار","localNameEn":"Savings account","note":"Banks offer savings accounts; interest is taxed at 10%."},"fdr_3m":{"available":true,"localName":"وديعة لأجل (3 أشهر)","localNameEn":"Term deposit (3 months)","note":"Banks take term deposits, but rates are not published."},"fdr_1y":{"available":true,"localName":"وديعة لأجل (سنة)","localNameEn":"Term deposit (1 year)","note":"Banks take term deposits, but rates are not published."},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No standard monthly recurring deposit product was found."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate for individuals was found."},"tbill_91d":{"available":false,"localName":"أذونات الخزينة","localNameEn":"Treasury bills (13 weeks)","note":"13-week bills are auctioned by the BCM; no retail subscription channel for individuals was found.","sourceUrl":"https://bo.bcm.mr/fr/api/valeurs_tresor"},"tbond_5y":{"available":false,"localName":"سندات الخزينة (5 سنوات)","localNameEn":"Treasury bonds (5 years)","note":"Bonds are auctioned by the BCM; no retail subscription channel for individuals was found.","sourceUrl":"https://bo.bcm.mr/fr/api/valeurs_tresor"},"tbond_10y":{"available":false,"localName":"سندات الخزينة (10 سنوات)","localNameEn":"Treasury bonds (10 years)","note":"Bonds are auctioned by the BCM; no retail subscription channel for individuals was found.","sourceUrl":"https://bo.bcm.mr/fr/api/valeurs_tresor"},"equity_fund":{"available":false,"localName":null,"localNameEn":null,"note":"There is no stock exchange in Mauritania and no locally sold equity fund was found."},"gold":{"available":true,"localName":"الذهب","localNameEn":"Gold","note":"Gold is mined in Mauritania and sold mainly as jewellery; the BCM buys artisanal gold."}},"institutions":{"centralBank":{"name":"Banque Centrale de Mauritanie (BCM)","url":"https://www.bcm.mr/"},"insuranceRegulator":{"name":"Banque Centrale de Mauritanie (BCM), insurance supervision","url":"https://www.bcm.mr/","note":"The BCM took over supervision of insurers from the Ministry of Finance''s Direction du Contrôle des Assurances in September 2025 (press reports); no dedicated BCM insurance page was found."},"insuranceComplaints":null,"pensionScheme":{"name":"Caisse Nationale de Sécurité Sociale (CNSS)","url":"https://www.cnss.mr/fr/services","note":"Old-age pensions for private-sector employees."},"oldAgeAllowance":null,"publicHealthCover":{"name":"Caisse Nationale d''Assurance Maladie (CNAM)","url":"https://www.cnam.mr/fr/","note":"Health insurance for insured workers and their dependants."},"depositInsurance":null,"statistics":{"name":"Agence Nationale de la Statistique et de la Démographie (ANSADE)","url":"https://ansade.mr/fr/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
