INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MR', 1, 'equity_return_base', 0.075, NULL, 'assumption', 'No stock exchange in Mauritania; global equities in ouguiya terms', 'https://bo.bcm.mr/fr/api/valeurs_tresor', '2026-10-31', 'Global equities in ouguiya terms, held about 3.4 points above the 4.1% after-tax 13-week bill rate, since access is only through foreign funds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MR', 1, 'equity_return_high', 0.1, NULL, 'assumption', 'No stock exchange in Mauritania; global equities in ouguiya terms', 'https://bo.bcm.mr/fr/api/valeurs_tresor', '2026-10-31', 'High case: global equities repeat their long-run record plus mild ouguiya depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MR', 1, 'equity_return_low', 0.03, NULL, 'assumption', 'No stock exchange in Mauritania; global equities in ouguiya terms', 'https://www.imf.org/external/datamapper/PCPIPCH@WEO/MRT', '2026-10-31', 'No local stock market exists, so equity means a global index in ouguiya terms; low case is a weak decade for global shares.', 0);
