INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MR', 1, 'fixed_income_return_base', 0.04, NULL, 'assumption', 'BCM Treasury auctions: 13-week bill 4.58% (29 Oct 2026); 10% tax on interest (PwC)', 'https://bo.bcm.mr/fr/api/valeurs_tresor', '2026-10-31', 'Base case: the 13-week bill rate of 4.58% less 10% tax (4.1%), rounded down.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MR', 1, 'fixed_income_return_high', 0.05, NULL, 'assumption', 'BCM Treasury auctions: 13-week bill 4.58% (29 Oct 2026); 10% tax on interest (PwC)', 'https://bo.bcm.mr/fr/api/valeurs_tresor', '2026-10-31', 'High case: longer Treasury bonds (5-year 4.82%, 15-year 5.99%) after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MR', 1, 'fixed_income_return_low', 0.03, NULL, 'assumption', 'BCM Treasury auctions: 13-week bill 4.58% (29 Oct 2026); 10% tax on interest (PwC)', 'https://bo.bcm.mr/fr/api/valeurs_tresor', '2026-10-31', 'Low case: shorter bills or deposits after the 10% interest tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MR', 1, 'goal_inflation_education', 0.055, NULL, 'assumption', 'Inflation assumption 4.5%; no education CPI found', 'https://www.imf.org/external/datamapper/PCPIPCH@WEO/MRT', '2026-10-31', 'No education price index was found; private school costs are planned 1 point above general inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MR', 1, 'goal_inflation_health', 0.06, NULL, 'assumption', 'Inflation assumption 4.5%; no medical CPI found', 'https://www.imf.org/external/datamapper/PCPIPCH@WEO/MRT', '2026-10-31', 'No medical price index was found; medical costs, many imported, are planned 1.5 points above general inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MR', 1, 'gold_return_base', 0.06, NULL, 'assumption', 'BCM ouguiya/dollar reference rates 2025 (about 39.6-39.8 per dollar); gold trend in dollars', 'https://bo.bcm.mr/sites/default/files/2026-02/Taux%20de%20change%20journalier%202008%20au%202025%20.xlsx', '2026-10-31', 'Base case: the long-run dollar gold trend of about 5% plus about 1% a year of ouguiya depreciation (about 39.6-39.8 per dollar in 2025, 40.4 in October 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MR', 1, 'gold_return_high', 0.1, NULL, 'assumption', 'BCM ouguiya/dollar reference rates 2025 (about 39.6-39.8 per dollar); gold trend in dollars', 'https://bo.bcm.mr/sites/default/files/2026-02/Taux%20de%20change%20journalier%202008%20au%202025%20.xlsx', '2026-10-31', 'High case: strong gold years with faster depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MR', 1, 'gold_return_low', 0, NULL, 'assumption', 'BCM ouguiya/dollar reference rates 2025 (about 39.6-39.8 per dollar); gold trend in dollars', 'https://bo.bcm.mr/sites/default/files/2026-02/Taux%20de%20change%20journalier%202008%20au%202025%20.xlsx', '2026-10-31', 'Low case: flat gold prices and a stable ouguiya.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MR', 1, 'gratuity_rule', NULL, '{"daysPerYear":7.5,"daysPerYearAfter":9,"afterYears":5,"daysPerMonth":30}', 'sourced', 'Convention collective générale du travail, article 31 (Ministère des Finances, recueil des textes)', 'https://finances.gov.mr/Recueil_des_textes_relatifs_a_la_mission_du_Ministere/TEXTES/EMPLOI/Convention%20collective.pdf', '2026-10-31', 'Dismissal indemnity per year of service: 25% of average monthly wage for years 1-5 (7.5 days), 30% for years 6-10 (9 days), 35% beyond 10 years (10.5 days, not representable here); on retirement with a CNSS pension the employer pays a retirement indemnity of 30% (1-5 years) to 100% (20+ years) of that amount. The agreement dates from 1974 and remains in force until replaced.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MR', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical out-of-pocket cost of a major hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MR', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premiums by age were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MR', 1, 'inflation_cpi', 0.093, NULL, 'sourced', 'Banque Centrale de Mauritanie (BCM), daily key rates feed (taux d''inflation)', 'https://bo.bcm.mr/fr/api/taux_journalier', '2026-10-29', '9.3% as displayed by the BCM on 29 October 2026 (latest month not stated); consistent with the IMF WEO projection of 8.0% average and 9.0% end-2026 inflation, after 1.6% in 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MR', 1, 'inflation_projection', 0.045, NULL, 'assumption', 'IMF WEO: 4.0% inflation by 2030; 2021-2025 average 4.4%', 'https://www.imf.org/external/datamapper/PCPIPCH@WEO/MRT', '2026-10-31', 'No published inflation target; the 2021-2025 average (4.4%) and the IMF medium-term 4% are rounded to 4.5% given the 2026 spike.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MR', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published term life premium rates per MRU 1,000 of cover were found; the life insurance market is very small.', 0);
