INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MR', 1, 'life_expectancy', 68.713, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN), Mauritania', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=MR', '2024-12-31', '68.7 years in 2024 (men 66.7, women 70.7).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MR', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":17.2,"men":15.9,"women":18.4},{"age":65,"total":13.7,"men":12.6,"women":14.7},{"age":70,"total":10.6,"men":9.8,"women":11.3},{"age":80,"total":5.9,"men":5.5,"women":6.2}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/mauritania/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026; totals are the mean of men and women except at 65, where the page gives 13.7 for both sexes.', 0);
