INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MR', 1, 'oop_health_share', 0.4377, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), Mauritania', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=MR', '2023-12-31', '43.8% in 2023 (WHO Global Health Expenditure Database via the World Bank), the latest available; older than 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MR', 1, 'policy_rate', 0.0675, NULL, 'sourced', 'BCM daily key rates feed (taux directeur)', 'https://bo.bcm.mr/fr/api/taux_journalier', '2026-10-29', 'Policy rate 6.75% (BCM feed of 29 October 2026), after a rise from 6% to 6.5% on 18 May 2026 and a further step since; overnight deposit facility 2%, repo (lending facility) 7%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MR', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":63,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'CLEISS, Le régime mauritanien de sécurité sociale (2025 edition)', 'https://www.cleiss.fr/docs/regimes/regime_mauritanie.html', '2025-04-14', 'CNSS (salaried private-sector workers, compulsory): pension from 63 after 20 years of registration; 20% of the average wage of the best of the last 3 or 5 years plus 1.33% per 12 months of insurance beyond 180 months, capped at 80% of average pay, floor 60% of the minimum wage. No automatic indexation rule was found (the US SSA profile describes periodic ad hoc revaluation), so inflationLinked is false; tax treatment not found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MR', 1, 'retirement_accumulation_return_base', 0.055, NULL, 'assumption', 'Safe rate 4.1% after tax; global equity base 7.5%; gold base 6%', 'https://bo.bcm.mr/fr/api/valeurs_tresor', '2026-10-31', 'Base case: bills and deposits with some gold and foreign equity funds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MR', 1, 'retirement_accumulation_return_high', 0.075, NULL, 'assumption', 'Safe rate 4.1% after tax; global equity base 7.5%; gold base 6%', 'https://bo.bcm.mr/fr/api/valeurs_tresor', '2026-10-31', 'High case: a growth-leaning mix with foreign equity funds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MR', 1, 'retirement_accumulation_return_low', 0.035, NULL, 'assumption', 'Safe rate 4.1% after tax; global equity base 7.5%; gold base 6%', 'https://bo.bcm.mr/fr/api/valeurs_tresor', '2026-10-31', 'Low case: mostly deposits and bills.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MR', 1, 'retirement_age_default', 63, NULL, 'sourced', 'CLEISS, Le régime mauritanien de sécurité sociale (2025 edition); CNSS FAQ', 'https://www.cleiss.fr/docs/regimes/regime_mauritanie.html', '2025-04-14', 'CNSS old-age pension at 63 (58 for premature wear or arduous work) with at least 20 years of registration and 60 months of insurance in the last 10 years; same age for men and women (CLEISS 2025, consistent with the CNSS site FAQ).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MR', 1, 'retirement_age_government', 63, NULL, 'sourced', 'Loi n° 2020-020 modifiant la loi 93-009 portant statut général des fonctionnaires (Ministère des Finances, recueil des textes)', 'https://finances.gov.mr/Recueil_des_textes_relatifs_a_la_mission_du_Ministere/TEXTES/EMPLOI/Loi%202020-020%20modif%20loi%2093-009%20SGFP%20fr.pdf', '2020-09-30', 'Article 72 (new): civil servants retire automatically at the age limit of 63; a special corps statute may set a lower limit. Law from 2020, still the latest text found (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MR', 1, 'retirement_return_base', 0.04, NULL, 'assumption', 'BCM Treasury auctions: 13-week bill 4.58% (29 Oct 2026); 10% tax on interest (PwC)', 'https://bo.bcm.mr/fr/api/valeurs_tresor', '2026-10-31', 'Base case: kept below the 4.1% after-tax 13-week bill rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MR', 1, 'retirement_return_high', 0.045, NULL, 'assumption', 'BCM Treasury auctions: 13-week bill 4.58% (29 Oct 2026); 10% tax on interest (PwC)', 'https://bo.bcm.mr/fr/api/valeurs_tresor', '2026-10-31', 'High case: a ladder of Treasury bonds after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MR', 1, 'retirement_return_low', 0.03, NULL, 'assumption', 'BCM Treasury auctions: 13-week bill 4.58% (29 Oct 2026); 10% tax on interest (PwC)', 'https://bo.bcm.mr/fr/api/valeurs_tresor', '2026-10-31', 'Low case: deposits and short bills after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MR', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate or retail savings bond for individuals was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MR', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical savings account rate was found; the BCM site is a JavaScript app with no rates table reachable, and web search was unavailable during this run.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MR', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":16.7},{"year":2040,"value":15.2},{"year":2065,"value":9.6}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://data.worldbank.org/indicator/SP.POP.DPND.OL?locations=MR', '2025-12-31', 'Working-age people per person 65+, computed as 100 / old-age dependency ratio: ratio 5.97 in 2025 (World Bank) gives 16.7; ratios 6.6 in 2040 and 10.4 in 2065 (UN WPP 2024 via populationpyramid.net/mauritania/2040/ and /2065/) give 15.2 and 9.6.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MR', 1, 'tax_bank_interest', 0.1, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Mauritania, individual income determination', 'https://taxsummaries.pwc.com/mauritania/individual/income-determination', '2026-10-31', 'Interest on deposits with a Mauritanian bank is taxed at 10%, withheld by the bank (secondary source).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MR', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate exists for individuals, so no tax rule for one was found; bond interest is taxed at 10% (PwC).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MR', 1, 'tbill_91d_rate', 0.0458, NULL, 'sourced', 'BCM, Treasury securities auction rates (bons du Trésor 13 semaines)', 'https://bo.bcm.mr/fr/api/valeurs_tresor', '2026-10-29', '13-week Treasury bill rate 4.58% at the auction of 29 October 2026 (26-week 4.09%, 52-week 4.26%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MR', 1, 'tbond_10y_rate', 0.043, NULL, 'sourced', 'BCM, Treasury securities auction rates (obligations du Trésor 10 ans)', 'https://bo.bcm.mr/fr/api/valeurs_tresor', '2026-10-29', '10-year Treasury bond rate 4.30% as of 29 October 2026 (15-year 5.99%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MR', 1, 'tbond_5y_rate', 0.0482, NULL, 'sourced', 'BCM, Treasury securities auction rates (obligations du Trésor 5 ans)', 'https://bo.bcm.mr/fr/api/valeurs_tresor', '2026-10-29', '5-year Treasury bond rate 4.82% as of 29 October 2026.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('MT', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"MT","iso3":"MLT","nameEn":"Malta","nameNative":"Malta","region":"middle_east_north_africa","languages":["mt","en","it"],"currency":{"code":"EUR","symbol":"€","decimals":2,"compact":"intl","usdRate":{"value":0.8951,"status":"sourced","sourceName":"European Central Bank euro reference rate (USD)","sourceUrl":"https://data-api.ecb.europa.eu/service/data/EXR/D.USD.EUR.SP00.A","asOf":"2026-10-30","note":"EUR 1 = USD 1.1172, so about EUR 0.895 per US dollar; World Bank 2025 average 0.885."}},"instruments":{"savings_account":{"available":true,"localName":"Kont tat-tfaddil","localNameEn":"Savings account","sourceUrl":"https://data-api.ecb.europa.eu/service/data/MIR/M.MT.B.L21.A.R.A.2250.EUR.N"},"fdr_3m":{"available":true,"localName":"Depożitu fiss","localNameEn":"Fixed-term deposit (3 months)"},"fdr_1y":{"available":true,"localName":"Depożitu fiss","localNameEn":"Fixed-term deposit (1 year)","sourceUrl":"https://data-api.ecb.europa.eu/service/data/MIR/M.MT.B.L22.F.R.A.2250.EUR.N"},"dps":{"available":false,"localName":null,"localNameEn":"Recurring deposit","note":"No standard monthly recurring deposit scheme with published rates was found."},"sanchayapatra_5y":{"available":true,"localName":null,"localNameEn":"Malta Government savings bonds (62+ Savings Bond for people aged 62 and over)","note":"Sold to individuals by the Treasury; current rate and general eligibility not confirmed."},"tbill_91d":{"available":true,"localName":"Treasury Bills","localNameEn":"Malta Government Treasury Bills (3 months)","note":"Auctioned by the Treasury; individuals can bid."},"tbond_5y":{"available":true,"localName":"Malta Government Stocks","localNameEn":"Malta Government Stocks"},"tbond_10y":{"available":true,"localName":"Malta Government Stocks","localNameEn":"Malta Government Stocks","sourceUrl":"https://data-api.ecb.europa.eu/service/data/IRS/M.MT.L.L40.CI.0000.EUR.N.Z"},"equity_fund":{"available":true,"localName":"Skema ta'' investiment kollettiv (UCITS)","localNameEn":"Mutual fund (UCITS) / index fund","note":"EU UCITS funds and ETFs are sold to retail investors."},"gold":{"available":true,"localName":"Deheb tal-investiment","localNameEn":"Investment gold bars and coins","note":"No restriction on buying physical gold."}},"institutions":{"centralBank":{"name":"Bank Ċentrali ta'' Malta (Central Bank of Malta)","url":"https://www.centralbankmalta.org/","note":"Part of the Eurosystem; monetary policy set by the European Central Bank."},"insuranceRegulator":{"name":"Malta Financial Services Authority (MFSA)","url":"https://www.mfsa.mt/"},"insuranceComplaints":{"name":"Office of the Arbiter for Financial Services","url":"https://financialarbiter.org.mt/"},"pensionScheme":{"name":"Department of Social Security (Contributory Retirement Pension)","url":"https://socialsecurity.gov.mt/"},"oldAgeAllowance":{"name":"Age Pension (Department of Social Security)","url":"https://socialsecurity.gov.mt/"},"publicHealthCover":{"name":"Ministry for Health and Active Ageing (free public health care)","url":"https://health.gov.mt/"},"depositInsurance":{"name":"Depositor Compensation Scheme","url":"https://compensationschemes.org.mt/"},"statistics":{"name":"National Statistics Office (NSO)","url":"https://nso.gov.mt/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MT', 1, 'bank_deposit_avg_rate', 0.0208, NULL, 'sourced', 'ECB MFI interest rate statistics: Maltese banks, household deposits with agreed maturity (outstanding amounts)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.MT.B.L22.A.R.A.2250.EUR.O', '2026-09-30', 'Average rate on all outstanding household term deposits, 2.08% in September 2026 (2.05% in August); World Bank FR.INR.DPST has no Malta figure.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MT', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap or published average credit card rate for Malta was found; the Central Bank of Malta site refused automated access.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MT', 1, 'deposit_insurance_limit', 100000, NULL, 'sourced', 'Depositor Compensation Scheme (Malta), payment limits', 'https://compensationschemes.org.mt/claims/payment-limits-under-the-depositor-compensation-scheme/', '2026-10-31', 'EUR 100,000 per depositor per bank; up to EUR 500,000 extra for temporary high balances from certain life events credited within six months before a default.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MT', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No monthly recurring deposit product with a published average rate was found for Malta.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MT', 1, 'equity_return_base', 0.05, NULL, 'assumption', 'MSE Share Index (Trading Economics); 1-year deposit 2.39% less 15-25% tax = about 1.8-2.0%', 'https://tradingeconomics.com/malta/stock-market', '2026-10-31', 'Base case about 3 points above the after-tax safe rate because the local index has a weak 10-year record (still far below its 2020 high); most savers would use a diversified euro equity fund.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MT', 1, 'equity_return_high', 0.075, NULL, 'assumption', 'Global equity long-run returns in euros; MSE Share Index (Trading Economics)', 'https://tradingeconomics.com/malta/stock-market', '2026-10-31', 'High case: a diversified euro equity fund matching long-run global equity returns of about 7-8% in euros.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MT', 1, 'equity_return_low', 0.02, NULL, 'assumption', 'MSE Share Index about 4,278 on 30 Oct 2026; its September 2026 peak of 4,404 was only the highest since July 2024', 'https://tradingeconomics.com/malta/stock-market', '2026-10-31', 'Low case: the small Maltese market keeps its weak decade-long record.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MT', 1, 'fdr_1y_rate', 0.0239, NULL, 'sourced', 'ECB MFI interest rate statistics: Maltese banks, household deposits with agreed maturity up to 1 year (new business)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.MT.B.L22.F.R.A.2250.EUR.N', '2026-09-30', 'Bucket covers all fixed terms up to one year: 2.39% in September 2026 (2.13% in July, 2.24% in August).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MT', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'ECB/Central Bank of Malta MFI statistics publish household deposits with agreed maturity up to 1 year as one bucket (2.39% in September 2026); no separate 3-month rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MT', 1, 'fixed_income_return_base', 0.022, NULL, 'assumption', 'Deposits up to 1 year 2.39% and 10-year government bond 4.19%, both less 15-25% tax', 'https://data-api.ecb.europa.eu/service/data/MIR/M.MT.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Base case: mostly term deposits at about 1.8-2.0% after tax, with some Malta Government Stocks at about 3.1-3.6% after tax; the tax on interest is unconfirmed (PwC''s withholding table shows 25%, the usual final withholding is 15%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MT', 1, 'fixed_income_return_high', 0.035, NULL, 'assumption', 'Malta 10-year government bond 4.19% (Sep 2026) less 15-25% tax = 3.1-3.6%', 'https://data-api.ecb.europa.eu/service/data/IRS/M.MT.L.L40.CI.0000.EUR.N.Z', '2026-10-31', 'High case: holding long Malta Government Stocks.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MT', 1, 'fixed_income_return_low', 0.012, NULL, 'assumption', 'Household deposits up to 1 year 2.39% (Sep 2026) less 15-25% tax, with ECB rates able to fall', 'https://data-api.ecb.europa.eu/service/data/MIR/M.MT.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Low case: term deposits after tax if rates fall back.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MT', 1, 'goal_inflation_education', 0.04, NULL, 'assumption', 'Trading Economics (NSO Malta): education inflation 3.2% in September 2026; ECB HICP Malta education 4.3% in December 2025', 'https://tradingeconomics.com/malta/inflation-cpi', '2026-10-31', 'Education prices (largely private and church schools and tuition) rise faster than headline inflation; 4% is used for planning.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MT', 1, 'goal_inflation_health', 0.035, NULL, 'assumption', 'Trading Economics (NSO Malta): health inflation 2.9% in September 2026', 'https://tradingeconomics.com/malta/inflation-cpi', '2026-10-31', 'Health prices rise a little faster than headline inflation and medical costs usually outrun it over decades, so 3.5% is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MT', 1, 'gold_return_base', 0.04, NULL, 'assumption', 'Gold price history (Trading Economics); ECB 2% inflation target', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Base case: dollar gold rises roughly with world inflation plus a little, and the euro is assumed stable against the dollar over the long run.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MT', 1, 'gold_return_high', 0.07, NULL, 'assumption', 'Gold price history (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'High case: a repeat of gold''s strong 2005-2025 trend in euro terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MT', 1, 'gold_return_low', 0.01, NULL, 'assumption', 'Gold price history (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Low case: gold barely keeps up after the 2025-26 spike, with no help from the euro.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MT', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No statutory end-of-service gratuity for private employees was found in the European Commission guide or other sources read; Maltese employment law pages (gov.mt) could not be checked.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MT', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'Planned and emergency care in public hospitals is free for insured residents (European Commission guide, July 2026); no official figure for a typical out-of-pocket private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MT', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No private health insurance premium table per EUR 100,000 of cover was found from the regulator or another public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MT', 1, 'inflation_cpi', 0.024, NULL, 'sourced', 'Trading Economics (National Statistics Office Malta, September 2026)', 'https://tradingeconomics.com/malta/inflation-cpi', '2026-09-30', 'Annual inflation 2.4% in September 2026 (2.0% in August), released 16 October 2026; secondary source because nso.gov.mt refused automated access. World Bank 2025 average 2.4%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MT', 1, 'inflation_projection', 0.025, NULL, 'assumption', 'ECB 2% medium-term target; Malta inflation 2.4% (Sep 2026) and 2.4% (2025)', 'https://tradingeconomics.com/malta/inflation-cpi', '2026-10-31', 'Malta''s inflation has run slightly above the euro-area target in recent years, so 2.5% is used for planning.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MT', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life is sold, but no published premium table or regulator data on term premiums per sum insured was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MT', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Malta Financial Services Authority does not publish an industry life claim settlement ratio that could be found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MT', 1, 'life_expectancy', 83.8, NULL, 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/malta', '2026-07-01', 'Men 81.9, women 85.6 (UN WPP estimate for 2026, mid-year); World Bank 2024 figure 83.0. Re-checked on georank 2026-11-03.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MT', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":26.1,"men":24.3,"women":27.7},{"age":65,"total":21.8,"men":20.1,"women":23.3},{"age":70,"total":17.7,"men":16.1,"women":19},{"age":80,"total":10.6,"men":9.3,"women":11.5}]}', 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/malta', '2026-07-01', 'Remaining years computed from georank''s expected age at death by current age (UN WPP 2026 estimate).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MT', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":60,"womenAge":60,"over90Monthly":null,"meansTested":true}', 'sourced', 'European Commission, Your social security rights in Malta (July 2026)', 'https://employment-social-affairs.ec.europa.eu/document/download/b920adf8-38c1-4a1c-9579-7f8a62bc6ef6_en', '2026-07-31', 'Paid from 60 to people who do not qualify for a contributory pension and pass income and capital tests (capital below EUR 16,000 single, EUR 26,000 couple).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MT', 1, 'old_age_allowance_monthly', 723, NULL, 'sourced', 'European Commission, Your social security rights in Malta (July 2026)', 'https://employment-social-affairs.ec.europa.eu/document/download/b920adf8-38c1-4a1c-9579-7f8a62bc6ef6_en', '2026-07-31', 'Age Pension (means-tested, for residents 60+ without a contributory pension): highest rate EUR 166.79 a week for a single person (EUR 199.56 for a couple), converted at 52/12 weeks a month.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MT', 1, 'oop_health_share', 0.3093, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=MT', '2023-12-31', 'Older than 2025; latest available.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MT', 1, 'policy_rate', 0.025, NULL, 'sourced', 'European Central Bank, deposit facility rate', 'https://data-api.ecb.europa.eu/service/data/FM/B.U2.EUR.4F.KR.DFR.LEV', '2026-09-16', 'Malta uses the euro; ECB deposit facility rate 2.50% (main refinancing rate 2.65%) from 16 September 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MT', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":65,"nomineeUntilAge":null,"inflationLinked":true,"taxFree":null}', 'sourced', 'European Commission, Your social security rights in Malta (July 2026)', 'https://employment-social-affairs.ec.europa.eu/document/download/b920adf8-38c1-4a1c-9579-7f8a62bc6ef6_en', '2026-07-31', 'Contributory two-thirds Retirement Pension under the Social Security Act (employee and employer 10% each in 2026 per PwC), from age 65 for those born from 1962, based on the best 10 of the last 41-42 years. Inflation-linked is inferred: the guide states yearly cost-of-living increases for survivors'' pensions (two-thirds of the retirement pension) and invalidity pensions, but does not say so for the retirement pension in words.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MT', 1, 'retirement_accumulation_return_base', 0.035, NULL, 'assumption', 'After-tax deposits about 1.8-2.0%, government bonds 3.1-3.6%; equity base 5%', 'https://data-api.ecb.europa.eu/service/data/MIR/M.MT.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Base case: roughly half shares at 5% and half deposits and bonds at about 2-3.5% after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MT', 1, 'retirement_accumulation_return_high', 0.05, NULL, 'assumption', '10-year bond 3.1-3.6% after tax; equity high 7.5%', 'https://data-api.ecb.europa.eu/service/data/IRS/M.MT.L.L40.CI.0000.EUR.N.Z', '2026-10-31', 'High case for a growth-leaning balanced mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MT', 1, 'retirement_accumulation_return_low', 0.02, NULL, 'assumption', 'After-tax 1-year deposit about 1.8-2.0%; MSE index weak record', 'https://data-api.ecb.europa.eu/service/data/MIR/M.MT.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Low case for a balanced mix if shares lag.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MT', 1, 'retirement_age_default', 65, NULL, 'sourced', 'European Commission, Your social security rights in Malta (July 2026)', 'https://employment-social-affairs.ec.europa.eu/document/download/b920adf8-38c1-4a1c-9579-7f8a62bc6ef6_en', '2026-07-31', 'Pensionable age is 65 for everyone born on or after 1 January 1962, men and women (so 65 for anyone born after 1975); early pension from 61 needs 42 years of contributions (35 paid) for those born from 1976.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MT', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'The European Commission guide gives no separate retirement age for public employees (it mentions Service Pensions only in passing); no official public-service retirement rule could be read (gov.mt pages refused automated access). Public employees in the Social Security Act scheme reach pensionable age at 65 like everyone else.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MT', 1, 'retirement_return_base', 0.018, NULL, 'assumption', 'Household deposits up to 1 year 2.39% (Sep 2026) less 15-25% tax = 1.8-2.0%', 'https://data-api.ecb.europa.eu/service/data/MIR/M.MT.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Base case capped at the after-tax 1-year term deposit rate under the higher 25% tax reading, as no treasury bill yield was found and the tax on interest is unconfirmed (PwC''s withholding table shows 25%, the usual final withholding is 15%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MT', 1, 'retirement_return_high', 0.032, NULL, 'assumption', 'Malta 10-year government bond 4.19% less 15-25% tax = 3.1-3.6%', 'https://data-api.ecb.europa.eu/service/data/IRS/M.MT.L.L40.CI.0000.EUR.N.Z', '2026-10-31', 'High case: a ladder of Malta Government Stocks and retail savings bonds, below the current after-tax 10-year yield.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MT', 1, 'retirement_return_low', 0.012, NULL, 'assumption', 'Household deposits up to 1 year 2.39% less 15-25% tax, with rates able to fall', 'https://data-api.ecb.europa.eu/service/data/MIR/M.MT.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Low case: bank deposits after tax if ECB rates fall.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MT', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Treasury sells retail government savings bonds (including the 62+ Savings Bond for older people), but treasury.gov.mt refused automated access and no current rate was read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MT', 1, 'savings_account_rate', 0.0007, NULL, 'sourced', 'ECB MFI interest rate statistics: Maltese banks, household overnight deposits (new business)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.MT.B.L21.A.R.A.2250.EUR.N', '2026-09-30', 'Average 0.07% on household overnight deposits in September 2026 (also 0.07% in July and August).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MT', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":3.24},{"year":2040,"value":2.61},{"year":2065,"value":1.24}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/malta/2040/', '2025-12-31', '100 / old-age dependency ratio: 30.9 (2025, World Bank), 38.3 (2040) and 80.9 (2065, populationpyramid.net/malta/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MT', 1, 'tax_bank_interest', NULL, NULL, 'missing', '', '', '2026-10-31', 'Not confirmed: PwC''s Malta corporate withholding table (reviewed 30 Sep 2026) shows 25% on interest to resident individuals, while its individual pages mention an optional final withholding tax on investment income without a rate; the Tax and Customs Administration pages refused automated access.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MT', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'The tax rate on interest from Malta government savings bonds could not be confirmed on an official page (Treasury and tax administration pages refused automated access).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MT', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Malta auctions 3-month treasury bills, but the Treasury and Central Bank of Malta pages refused automated access and no recent auction yield was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MT', 1, 'tbond_10y_rate', 0.0419, NULL, 'sourced', 'ECB long-term interest rate for convergence purposes (10-year government bond), Malta', 'https://data-api.ecb.europa.eu/service/data/IRS/M.MT.L.L40.CI.0000.EUR.N.Z', '2026-09-30', 'Monthly average for September 2026 (3.90% in August).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MT', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No current 5-year Malta Government Stock yield was found; the Central Bank of Malta site refused automated access and only the ECB 10-year convergence yield was available.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('MU', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"MU","iso3":"MUS","nameEn":"Mauritius","nameNative":"Moris","region":"sub_saharan_africa","languages":["mfe","en","fr","bho"],"currency":{"code":"MUR","symbol":"Rs","decimals":2,"compact":"intl","usdRate":{"value":47.2,"status":"sourced","sourceName":"Bank of Mauritius, consolidated indicative exchange rates","sourceUrl":"https://www.bom.mu/markets/foreign-exchange/consolidated-indicative-exchange-rates","asOf":"2026-10-30","note":"Mid-point of the consolidated indicative USD buying (46.41, notes) and selling (47.99) rates on 30 October 2026; the BoM page showed 46.42/47.99 again on 3 November 2026."}},"instruments":{"savings_account":{"available":true,"localName":null,"localNameEn":"Savings account","note":"Banks pay 3.15-3.65% (July 2026); interest is tax-exempt for individuals.","sourceUrl":"https://www.bom.mu/sites/default/files/pdf/Research_and_Publications/Monthly_Statistical_Bulletin/msb_aug_2026.pdf"},"fdr_3m":{"available":true,"localName":null,"localNameEn":"Fixed deposit (3 months)","note":"Short fixed deposits are offered; the BoM only publishes rate ranges.","sourceUrl":"https://www.bom.mu/sites/default/files/pdf/Research_and_Publications/Monthly_Statistical_Bulletin/msb_aug_2026.pdf"},"fdr_1y":{"available":true,"localName":null,"localNameEn":"Fixed deposit (1 year)","note":"One-year fixed deposits are offered, up to about 4.7% in July 2026.","sourceUrl":"https://www.bom.mu/sites/default/files/pdf/Research_and_Publications/Monthly_Statistical_Bulletin/msb_aug_2026.pdf"},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No standard monthly recurring deposit product with published rates was found."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":"Government of Mauritius Savings Bond","note":"Retail savings bonds are issued from time to time through banks; the last (3.5%, four years) closed in February 2025.","sourceUrl":"https://bom.mu/sites/default/files/prospectus_-_4y_gom_savings_bond_0.pdf"},"tbill_91d":{"available":true,"localName":null,"localNameEn":"Treasury bills / Bank of Mauritius bills (91 days)","note":"Auctioned weekly by the BoM; individuals can buy through banks and primary dealers.","sourceUrl":"https://www.bom.mu/sites/default/files/results_-_91d_bom_bills_22_oct_2026.pdf"},"tbond_5y":{"available":true,"localName":null,"localNameEn":"Five-Year Government of Mauritius Bonds","note":"Auctioned by the BoM; individuals can buy through banks and primary dealers or on the stock exchange.","sourceUrl":"https://www.bom.mu/sites/default/files/pdf/Research_and_Publications/Monthly_Statistical_Bulletin/msb_aug_2026.pdf"},"tbond_10y":{"available":true,"localName":null,"localNameEn":"Ten-Year Government of Mauritius Bonds","note":"Auctioned by the BoM; individuals can buy through banks and primary dealers or on the stock exchange.","sourceUrl":"https://www.bom.mu/sites/default/files/pdf/Research_and_Publications/Monthly_Statistical_Bulletin/msb_aug_2026.pdf"},"equity_fund":{"available":true,"localName":null,"localNameEn":"Collective investment scheme (unit trust)","note":"Collective investment schemes are licensed by the Financial Services Commission."},"gold":{"available":true,"localName":null,"localNameEn":"Gold coins and bars","note":"The Bank of Mauritius sells gold coins to the public; gold bars are also sold."}},"institutions":{"centralBank":{"name":"Bank of Mauritius","url":"https://www.bom.mu/"},"insuranceRegulator":{"name":"Financial Services Commission (FSC)","url":"https://www.fscmauritius.org/en"},"insuranceComplaints":{"name":"Office of the Ombudsperson for Financial Services","url":"https://ofsmauritius.govmu.org/ofsmauritius/","note":"Complaints about insurers go here after the insurer''s own process; the FSC also explains complaints handling at fscmauritius.org/en/consumer-protection/complaints-handling."},"pensionScheme":{"name":"Ministry of Social Security (National Pensions Fund and CSG retirement benefits)","url":"https://socialsecurity.govmu.org/socialsecurity/","note":"A new defined-contribution National Pensions Fund is due from July 2027."},"oldAgeAllowance":{"name":"Basic Retirement Pension (Ministry of Social Security)","url":"https://socialsecurity.govmu.org/socialsecurity/?page_id=5209","note":"Universal pension; age rising from 60 to 65 by 2034; to be renamed State Age Pension from 2027."},"publicHealthCover":{"name":"Ministry of Health and Wellness (free public health care)","url":"https://health.govmu.org/health/"},"depositInsurance":{"name":"Mauritius Deposit Insurance Corporation (via Bank of Mauritius)","url":"https://www.bom.mu/sites/default/files/Frequently%20Asked%20Questions%20-%20MDIC.pdf"},"statistics":{"name":"Statistics Mauritius","url":"https://statsmauritius.govmu.org/SitePages/Index.aspx"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MU', 1, 'bank_deposit_avg_rate', 0.0267, NULL, 'sourced', 'Bank of Mauritius, Monthly Statistical Bulletin August 2026, Table 18 (weighted average rupee deposits rate of banks)', 'https://www.bom.mu/sites/default/files/pdf/Research_and_Publications/Monthly_Statistical_Bulletin/msb_aug_2026.pdf', '2026-07-31', 'Weighted average rate on all rupee deposits of banks, 2.67% in July 2026 (includes low-rate savings and demand deposits). World Bank FR.INR.DPST gives 4.54% for 2025 on a different basis.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MU', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap was found; the BoM bulletin publishes card volumes but no credit card interest rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MU', 1, 'deposit_insurance_limit', 300000, NULL, 'sourced', 'Bank of Mauritius, Mauritius Deposit Insurance Corporation FAQ', 'https://www.bom.mu/sites/default/files/Frequently%20Asked%20Questions%20-%20MDIC.pdf', '2024-06-14', 'Rs 300,000 per depositor per Scheme member, under the Mauritius Deposit Insurance Scheme Act 2019 operative from 14 June 2024; confirmed in the MDIC Annual Report 2024-2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MU', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published rate for a standard monthly recurring deposit product was found in BoM statistics.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MU', 1, 'equity_return_base', 0.065, NULL, 'assumption', 'SEMDEX 10-year record weak; safe after-tax rate about 4%', 'https://tradingeconomics.com/mauritius/stock-market', '2026-10-31', 'Held 2.5 points above the roughly 4% tax-free deposit and bill rate because the SEMDEX price index has gained little in ten years and returns come mostly from dividends.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MU', 1, 'equity_return_high', 0.095, NULL, 'assumption', 'SEMDEX record high 2,530 (February 2025); global equity history', 'https://tradingeconomics.com/mauritius/stock-market', '2026-10-31', 'High case: a diversified local and global equity fund with rupee depreciation lifting foreign returns.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MU', 1, 'equity_return_low', 0.035, NULL, 'assumption', 'SEMDEX near 2,266 in July 2026, about 2,000-2,500 for most of the past decade', 'https://tradingeconomics.com/mauritius/stock-market', '2026-10-31', 'Low case: the local market keeps its flat price record and investors earn mostly dividends.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MU', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The BoM only publishes ranges: new rupee time deposits of 6-12 months ranged 0.55-4.70% and 12-24 months 3.25-4.70% in July 2026 (MSB August 2026, Table 17a); no typical 1-year rate is published.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MU', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The BoM only publishes ranges by term band: new rupee time deposits up to 6 months ranged 1.25-4.35% in July 2026 (MSB August 2026, Table 17a), too wide to give a typical 3-month rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MU', 1, 'fixed_income_return_base', 0.04, NULL, 'assumption', 'BoM: 91-day bill 4.30% (22 Oct 2026), 364-day bill 4.32% and 10-year bond 5.60% (Aug 2026); bank 1-year deposits up to about 4.7%, interest on individuals'' bank deposits tax-exempt (MRA)', 'https://www.bom.mu/sites/default/files/results_-_91d_bom_bills_22_oct_2026.pdf', '2026-10-31', 'Base case: tax-free 1-year bank deposits and bills of about 4.0-4.3%, rounded down.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MU', 1, 'fixed_income_return_high', 0.05, NULL, 'assumption', 'BoM: 91-day bill 4.30% (22 Oct 2026), 364-day bill 4.32% and 10-year bond 5.60% (Aug 2026); bank 1-year deposits up to about 4.7%, interest on individuals'' bank deposits tax-exempt (MRA)', 'https://www.bom.mu/sites/default/files/pdf/Research_and_Publications/Monthly_Statistical_Bulletin/msb_aug_2026.pdf', '2026-10-31', 'High case: 5- to 10-year Government bonds at 5.3-5.6%, taxed at a low marginal rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MU', 1, 'fixed_income_return_low', 0.03, NULL, 'assumption', 'BoM: 91-day bill 4.30% (22 Oct 2026), 364-day bill 4.32% and 10-year bond 5.60% (Aug 2026); bank 1-year deposits up to about 4.7%, interest on individuals'' bank deposits tax-exempt (MRA)', 'https://www.bom.mu/sites/default/files/results_-_91d_bom_bills_22_oct_2026.pdf', '2026-10-31', 'Low case: savings accounts (about 3.4%) and short deposits after rate cuts.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MU', 1, 'goal_inflation_education', 0.055, NULL, 'assumption', 'Inflation assumption 4.5%; education CPI up 6.3% year on year in September 2026 (Statistics Mauritius via Trading Economics)', 'https://tradingeconomics.com/mauritius/inflation-cpi/news/590162', '2026-10-31', 'Public schooling is free, but education prices rose 6.3% in the year to September 2026, faster than the CPI, so education is planned 1 point above general inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MU', 1, 'goal_inflation_health', 0.06, NULL, 'assumption', 'Inflation assumption 4.5%; private health costs largely imported', 'https://www.bom.mu/sites/default/files/media_release_mpc_decision_12_august_2026.pdf', '2026-10-31', 'No separate medical price projection was found; private medical costs are planned 1.5 points above general inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MU', 1, 'gold_return_base', 0.075, NULL, 'assumption', 'Gold trend in dollars; rupee about 35 per dollar in 2016 and 47.2 in October 2026 (BoM)', 'https://www.bom.mu/markets/foreign-exchange/indicative-exchange-rate', '2026-10-31', 'Base case: a long-run dollar gold trend of about 5% plus about 2.5% a year of rupee depreciation, its pace over the last decade.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MU', 1, 'gold_return_high', 0.11, NULL, 'assumption', 'Gold trend in dollars; rupee about 35 per dollar in 2016 and 47.2 in October 2026 (BoM)', 'https://www.bom.mu/markets/foreign-exchange/indicative-exchange-rate', '2026-10-31', 'High case: strong gold years and faster rupee depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MU', 1, 'gold_return_low', 0.01, NULL, 'assumption', 'Gold trend in dollars; rupee about 35 per dollar in 2016 and 47.2 in October 2026 (BoM)', 'https://www.bom.mu/markets/foreign-exchange/indicative-exchange-rate', '2026-10-31', 'Low case: flat dollar gold prices with mild rupee depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MU', 1, 'gratuity_rule', NULL, '{"daysPerYear":15,"daysPerYearAfter":null,"afterYears":null,"daysPerMonth":26}', 'sourced', 'Workers'' Rights Act 2019 (consolidated to Act 13 of 2026), section 109, MRA', 'https://www.mra.mu/download/WorkersRightsAct2019.pdf', '2026-08-13', 'Gratuity on retirement after 12 months'' service: 15 days'' remuneration per year of continuous employment, daily rate on 26 days a month; paid through the Portable Retirement Gratuity Fund for service since 2020, and the employer may offset part of an employer-funded pension.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MU', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'Public hospital care is free; no official figure for the out-of-pocket cost of a private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MU', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No regulator or official source publishing private health insurance premiums by age was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MU', 1, 'inflation_cpi', 0.057, NULL, 'sourced', 'Statistics Mauritius CPI, September 2026, via Trading Economics', 'https://tradingeconomics.com/mauritius/inflation-cpi/news/590162', '2026-09-30', 'Year-on-year inflation 5.7% in September 2026 (4.9% in August), released by Statistics Mauritius on 7 October 2026; secondary source as the official release page was not reachable. The 12-month average headline rate was about 4.1%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MU', 1, 'inflation_projection', 0.045, NULL, 'assumption', 'Bank of Mauritius inflation objective range 2-5%; 2026 forecast about 5%', 'https://www.bom.mu/sites/default/files/media_release_mpc_decision_12_august_2026.pdf', '2026-10-31', 'Planned at 4.5%, near the top of the central bank''s 2-5% range, because the 2021-2025 average (about 5.8%) and the 2026 forecast (about 5%) sit above its midpoint.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MU', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life cover is sold, but no regulator or official source publishes indicative premiums per Rs 1,000 of cover; only company quotes exist.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MU', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Financial Services Commission publishes long-term claims amounts by insurer but no industry claim settlement ratio was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MU', 1, 'life_expectancy', 73.79, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN), Mauritius', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=MU', '2024-12-31', '73.8 years in 2024 (men 70.4, women 77.4), from Statistics Mauritius via the World Bank.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MU', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":21.1,"men":19.3,"women":22.9},{"age":65,"total":17.4,"men":15.9,"women":18.9},{"age":70,"total":14.1,"men":12.9,"women":15.3},{"age":80,"total":8.4,"men":7.7,"women":9.1}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/mauritius/', '2026-07-01', 'Secondary source of UN WPP 2024 (medium variant) for 2026; totals are the mean of men and women except at 65, where the page gives 17.4. The Statistics Mauritius 2021-2023 life table gives similar values (men 17.9, women 21.7 at 60-64).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MU', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":65,"womenAge":65,"over90Monthly":null,"meansTested":false}', 'sourced', 'Ministry of Social Security, Basic Retirement Pension; Finance Act 2025 age schedule (L''Express via AllAfrica)', 'https://socialsecurity.govmu.org/socialsecurity/?page_id=5209', '2026-01-09', 'BRP is paid to residents meeting residence rules (citizens under 70: 12 years since age 18) without a means test; its age rises from 60 to 65 in steps, reaching 65 for anyone turning 60 from 1 September 2029 (fr.allafrica.com/stories/202601090287.html), so 65 applies to anyone planning today. Ages 90-99 receive a higher rate (Rs 22,710 from January 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MU', 1, 'old_age_allowance_monthly', 15000, NULL, 'sourced', 'Ministry of Social Integration, Social Security and National Solidarity, Basic Retirement Pension', 'https://socialsecurity.govmu.org/socialsecurity/?page_id=5209', '2025-01-01', 'Basic Retirement Pension of Rs 15,000 a month for ages 60-89 from January 2025, still the amount on the ministry page last updated February 2026; a Rs 15,555 figure in a July 2026 press article is only a reference pension used in projections, so no 2026 increase could be confirmed. Universal, no means test (the minister said the means test was abandoned, L''Express July 2026); to become the State Age Pension from 2027.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MU', 1, 'oop_health_share', 0.4524, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), Mauritius', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=MU', '2023-12-31', '45.2% in 2023 (WHO Global Health Expenditure Database), the latest available; older than 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MU', 1, 'policy_rate', 0.0475, NULL, 'sourced', 'Bank of Mauritius, MPC media release 12 August 2026', 'https://www.bom.mu/sites/default/files/media_release_mpc_decision_12_august_2026.pdf', '2026-08-12', 'Key Rate kept at 4.75% after a 25 bp rise on 20 May 2026; still shown as current on the BoM site on 30 October 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MU', 1, 'public_pension_scheme', NULL, NULL, 'missing', '', '', '2026-10-31', 'The contributory layer is in transition: National Pensions Fund contributions were replaced by the CSG in 2020, and Budget 2026-27 announced a new defined-contribution National Pensions Fund from 1 July 2027; its rules were not yet published. The universal Basic Retirement Pension is reported under old_age_allowance.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MU', 1, 'retirement_accumulation_return_base', 0.055, NULL, 'assumption', 'Safe rate about 4%; equity base 6.5%; gold base 7.5%', 'https://www.bom.mu/sites/default/files/pdf/Research_and_Publications/Monthly_Statistical_Bulletin/msb_aug_2026.pdf', '2026-10-31', 'Base case: a balanced mix of bonds, deposits and equity funds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MU', 1, 'retirement_accumulation_return_high', 0.07, NULL, 'assumption', 'Safe rate about 4%; equity base 6.5%; gold base 7.5%', 'https://www.bom.mu/sites/default/files/pdf/Research_and_Publications/Monthly_Statistical_Bulletin/msb_aug_2026.pdf', '2026-10-31', 'High case: a growth-leaning mix with local and global equity funds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MU', 1, 'retirement_accumulation_return_low', 0.04, NULL, 'assumption', 'Safe rate about 4%; equity base 6.5%; gold base 7.5%', 'https://www.bom.mu/sites/default/files/pdf/Research_and_Publications/Monthly_Statistical_Bulletin/msb_aug_2026.pdf', '2026-10-31', 'Low case: mostly deposits and Government bonds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MU', 1, 'retirement_age_default', 65, NULL, 'sourced', 'Workers'' Rights Act 2019 (consolidated to Act 13 of 2026), section 2 and section 109, MRA', 'https://www.mra.mu/download/WorkersRightsAct2019.pdf', '2026-08-13', 'The Act defines retirement age as 65 and bars employers from requiring retirement earlier; the Basic Retirement Pension age is also rising to 65 for everyone turning 60 from 1 September 2029 (Finance Act 2025), so 65 applies to anyone born after 1975.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MU', 1, 'retirement_age_government', 65, NULL, 'sourced', 'News on Sunday (defimedia.info), Pension reforms: a bitter necessity', 'https://defimedia.info/pension-reforms-bitter-necessity', '2017-01-24', 'Secondary source: the civil service retirement age was raised gradually from 60 to 65; no official Pensions Act text was reachable. Older than 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MU', 1, 'retirement_return_base', 0.0375, NULL, 'assumption', 'BoM: 91-day bill 4.30% (22 Oct 2026), 364-day bill 4.32% and 10-year bond 5.60% (Aug 2026); bank 1-year deposits up to about 4.7%, interest on individuals'' bank deposits tax-exempt (MRA)', 'https://www.bom.mu/sites/default/files/results_-_91d_bom_bills_22_oct_2026.pdf', '2026-10-31', 'Base case: kept below the roughly 4% tax-free 1-year deposit and 364-day bill rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MU', 1, 'retirement_return_high', 0.045, NULL, 'assumption', 'BoM: 91-day bill 4.30% (22 Oct 2026), 364-day bill 4.32% and 10-year bond 5.60% (Aug 2026); bank 1-year deposits up to about 4.7%, interest on individuals'' bank deposits tax-exempt (MRA)', 'https://www.bom.mu/sites/default/files/pdf/Research_and_Publications/Monthly_Statistical_Bulletin/msb_aug_2026.pdf', '2026-10-31', 'High case: a ladder of 5- to 10-year Government bonds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MU', 1, 'retirement_return_low', 0.03, NULL, 'assumption', 'BoM: 91-day bill 4.30% (22 Oct 2026), 364-day bill 4.32% and 10-year bond 5.60% (Aug 2026); bank 1-year deposits up to about 4.7%, interest on individuals'' bank deposits tax-exempt (MRA)', 'https://www.bom.mu/sites/default/files/results_-_91d_bom_bills_22_oct_2026.pdf', '2026-10-31', 'Low case: savings accounts and short deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MU', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No retail Government savings bond is on sale: the last, the 3.5% Four-Year Government of Mauritius Savings Bond (prospectus at bom.mu), closed on 14 February 2025, and no 2026 issue was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MU', 1, 'savings_account_rate', 0.034, NULL, 'sourced', 'Bank of Mauritius, Monthly Statistical Bulletin August 2026, Table 17a (banks'' interest rates on new rupee deposits)', 'https://www.bom.mu/sites/default/files/pdf/Research_and_Publications/Monthly_Statistical_Bulletin/msb_aug_2026.pdf', '2026-07-31', 'Savings deposit rates ranged 3.15-3.65% in June and July 2026 (raised from 2.95-3.40% in May 2026 after the Key Rate rise); midpoint used. Interest on an individual''s savings or fixed deposit is tax-exempt.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MU', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":5.1},{"year":2040,"value":3.1},{"year":2065,"value":1.6}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://data.worldbank.org/indicator/SP.POP.DPND.OL?locations=MU', '2025-12-31', 'Working-age people per person 65+, computed as 100 / old-age dependency ratio: 19.8 in 2025 (World Bank) gives 5.1; 32.0 in 2040 and 63.3 in 2065 (populationpyramid.net/mauritius/2040/ and /2065/) give 3.1 and 1.6.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MU', 1, 'tax_bank_interest', 0, NULL, 'sourced', 'Mauritius Revenue Authority, Exempt income (individuals)', 'https://www.mra.mu/index.php/individuals/exempt-income', '2026-10-31', 'Interest on a savings or fixed deposit account held by an individual with a bank or non-bank deposit-taking institution is exempt income (Income Tax Act, Second Schedule, Part II); other interest is taxed in income at 0%, 10% or 20%. The MRA page was unreachable on 3 November 2026 for re-checking; PwC Tax Summaries (deductions) lists this interest separately in the housing-relief income test, consistent with its exempt status.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MU', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No retail savings bond is currently on sale and the tax treatment of savings-bond interest is not stated in the last prospectus or on the MRA exempt-income page.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MU', 1, 'tbill_91d_rate', 0.043, NULL, 'sourced', 'Bank of Mauritius, auction results of 91-day BOM Bills, 22 October 2026', 'https://www.bom.mu/sites/default/files/results_-_91d_bom_bills_22_oct_2026.pdf', '2026-10-22', 'Weighted average yield 4.30% (range 4.24-4.44%). These are Bank of Mauritius bills; Government Treasury bill yields were similar (91-day about 4.0% in August 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MU', 1, 'tbond_10y_rate', 0.056, NULL, 'sourced', 'Bank of Mauritius, Monthly Statistical Bulletin August 2026, Table 40a (Ten-Year Government of Mauritius Bonds)', 'https://www.bom.mu/sites/default/files/pdf/Research_and_Publications/Monthly_Statistical_Bulletin/msb_aug_2026.pdf', '2026-08-14', 'Weighted yield 5.60% at the 14 August 2026 auction of the 5.55% ten-year bond (5.62% in April 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MU', 1, 'tbond_5y_rate', 0.0535, NULL, 'sourced', 'Bank of Mauritius, Monthly Statistical Bulletin August 2026, Table 40c (switch auction into the new 5.35% Five-Year Government of Mauritius Bonds)', 'https://www.bom.mu/sites/default/files/pdf/Research_and_Publications/Monthly_Statistical_Bulletin/msb_aug_2026.pdf', '2026-08-19', 'Weighted yield 5.35% at the 19 August 2026 switch auction into the new 5.35% five-year benchmark bond; the 7 August 2026 switch into the 5.15% bond yielded 5.32%, and the last regular 5-year auction (20 May 2026) 4.99%.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('MV', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"MV","iso3":"MDV","nameEn":"Maldives","nameNative":"ދިވެހިރާއްޖެ","region":"south_asia","languages":["dv","en"],"currency":{"code":"MVR","symbol":"MVR","decimals":2,"compact":"intl","usdRate":{"value":15.42,"status":"sourced","sourceName":"Maldives Monetary Authority, Table 1 Selected Economic Indicators: MVR per USD","sourceUrl":"https://database.mma.gov.mv/mosac/latest/1.xlsx","asOf":"2026-09-30","note":"Managed peg at 15.42 per US dollar (2025 average 15.42)."}},"instruments":{"savings_account":{"available":true,"localName":null,"localNameEn":"Savings account","sourceUrl":"https://database.mma.gov.mv/mosac/latest/8.xlsx"},"fdr_3m":{"available":true,"localName":null,"localNameEn":"Time deposit","sourceUrl":"https://database.mma.gov.mv/mosac/latest/8.xlsx"},"fdr_1y":{"available":true,"localName":null,"localNameEn":"Time deposit","note":"Banks offer terms up to 3 years.","sourceUrl":"https://database.mma.gov.mv/mosac/latest/8.xlsx"},"dps":{"available":false,"localName":null,"localNameEn":"Recurring deposit","note":"No standard recurring-deposit product found."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":"Government savings certificate","note":"No retail government savings certificate found."},"tbill_91d":{"available":false,"localName":null,"localNameEn":"Treasury bill","note":"Bills are sold on tap at fixed rates, mainly to banks; no retail channel confirmed.","sourceUrl":"https://database.mma.gov.mv/mosac/latest/8.xlsx"},"tbond_5y":{"available":false,"localName":null,"localNameEn":"Treasury bond","note":"No retail government bond found."},"tbond_10y":{"available":false,"localName":null,"localNameEn":"Treasury bond","note":"No retail government bond found."},"equity_fund":{"available":false,"localName":null,"localNameEn":"Mutual fund","note":"No local retail mutual fund confirmed; a few shares trade on the Maldives Stock Exchange (regulator: CMDA).","sourceUrl":"https://www.cmda.gov.mv/"},"gold":{"available":true,"localName":null,"localNameEn":"Gold (jewellery and coins)"}},"institutions":{"centralBank":{"name":"Maldives Monetary Authority","url":"https://www.mma.gov.mv/"},"insuranceRegulator":{"name":"Maldives Monetary Authority (insurance supervision)","url":"https://www.mma.gov.mv/"},"insuranceComplaints":{"name":"Maldives Monetary Authority","url":"https://www.mma.gov.mv/","note":"Complain to the insurer first, then to the MMA as supervisor."},"pensionScheme":{"name":"Maldives Pension Administration Office (MRPS)","url":"https://www.pension.gov.mv/"},"oldAgeAllowance":{"name":"Old Age Basic Pension (Maldives Pension Administration Office)","url":"https://www.pension.gov.mv/basic-pension"},"publicHealthCover":{"name":"Aasandha universal health insurance (National Social Protection Agency)","url":"https://www.nspa.gov.mv/"},"statistics":{"name":"Maldives Bureau of Statistics","url":"https://statisticsmaldives.gov.mv/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MV', 1, 'bank_deposit_avg_rate', 0.0355, NULL, 'sourced', 'World Bank WDI FR.INR.DPST (deposit interest rate)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=MV', '2025-12-31', NULL, 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MV', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published cap or typical card rate found. Web search budget ran out during research; only official sites reachable by direct link were checked.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MV', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No deposit insurance scheme found on MMA pages. Web search budget ran out during research; only official sites reachable by direct link were checked.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MV', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No monthly recurring-deposit product or rate found. Web search budget ran out during research; only official sites reachable by direct link were checked.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MV', 1, 'equity_return_base', 0.07, NULL, 'assumption', '364-day T-bill 4.6%; global equity in US dollars (rufiyaa pegged to USD)', 'https://database.mma.gov.mv/mosac/latest/8.xlsx', '2026-10-31', 'Most equity exposure has to be global; with the peg we use a dollar equity return capped at the safe rate plus about 2.5 points.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MV', 1, 'equity_return_high', 0.1, NULL, 'assumption', 'MASIX rose from about 197 (2020) to 490 (Sep 2026); global equity record', 'https://database.mma.gov.mv/mosac/latest/8.xlsx', '2026-10-31', 'A strong decade for global and local shares.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MV', 1, 'equity_return_low', 0.02, NULL, 'assumption', 'MMA Table 8: MASIX index; 364-day T-bill 4.6%', 'https://database.mma.gov.mv/mosac/latest/8.xlsx', '2026-10-31', 'The local stock exchange is tiny and illiquid, so the low case is below the safe rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MV', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'MMA publishes time-deposit averages for up to 3 months (2.98%), 3-6 months (3.12%) and 2-3 years (5.44%), not 1 year. Web search budget ran out during research; only official sites reachable by direct link were checked.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MV', 1, 'fdr_3m_rate', 0.0298, NULL, 'sourced', 'Maldives Monetary Authority, Table 8 Interest Rates: time deposits up to 3 months (MVR, weighted average)', 'https://database.mma.gov.mv/mosac/latest/8.xlsx', '2026-09-30', '3-6 months 3.12%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MV', 1, 'fixed_income_return_base', 0.04, NULL, 'assumption', 'MMA: Treasury bills 3.87%-4.6%, 3-6 month deposits 3.12%', 'https://database.mma.gov.mv/mosac/latest/8.xlsx', '2026-10-31', 'A mix of deposits and bills; tax on interest assumed nil pending confirmation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MV', 1, 'fixed_income_return_high', 0.05, NULL, 'assumption', 'MMA: 2-3 year time deposits 5.44%', 'https://database.mma.gov.mv/mosac/latest/8.xlsx', '2026-10-31', 'Longer bank time deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MV', 1, 'fixed_income_return_low', 0.03, NULL, 'assumption', 'MMA: time deposits up to 3 months 2.98%', 'https://database.mma.gov.mv/mosac/latest/8.xlsx', '2026-10-31', 'Short bank deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MV', 1, 'goal_inflation_education', 0.04, NULL, 'assumption', 'MBS CPI September 2026: education services +0.27% year-on-year', 'https://statisticsmaldives.gov.mv/mbs/wp-content/uploads/2026/10/CPI-September-2026.pdf', '2026-10-31', 'Public schooling is free; we plan with general inflation plus 1.5 points for private and overseas study.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MV', 1, 'goal_inflation_health', 0.04, NULL, 'assumption', 'MBS CPI September 2026: health +0.74% year-on-year', 'https://statisticsmaldives.gov.mv/mbs/wp-content/uploads/2026/10/CPI-September-2026.pdf', '2026-10-31', 'Measured health prices barely move because Aasandha covers most care; we plan with general inflation plus 1.5 points for private and overseas treatment.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MV', 1, 'gold_return_base', 0.05, NULL, 'assumption', 'Long-run dollar gold trend; MVR pegged at 15.42 per USD', 'https://database.mma.gov.mv/mosac/latest/1.xlsx', '2026-10-31', 'No expected currency depreciation while the peg holds, so gold earns roughly the dollar gold trend.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MV', 1, 'gold_return_high', 0.09, NULL, 'assumption', 'Dollar gold in strong decades', 'https://database.mma.gov.mv/mosac/latest/1.xlsx', '2026-10-31', 'A strong gold decade or a devaluation of the rufiyaa.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MV', 1, 'gold_return_low', 0, NULL, 'assumption', 'MVR per USD fixed at 15.42 (MMA)', 'https://database.mma.gov.mv/mosac/latest/1.xlsx', '2026-10-31', 'With the peg, rufiyaa gold equals dollar gold, which can stall for a decade.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MV', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No statutory end-of-service gratuity rule found for private employees. Web search budget ran out during research; only official sites reachable by direct link were checked.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MV', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private hospital stay cost found; most care is financed by the Aasandha scheme. Web search budget ran out during research; only official sites reachable by direct link were checked.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MV', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premium guide found. Web search budget ran out during research; only official sites reachable by direct link were checked.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MV', 1, 'inflation_cpi', 0.0117, NULL, 'sourced', 'Maldives Bureau of Statistics, CPI September 2026 release, year-on-year (all groups, Republic)', 'https://statisticsmaldives.gov.mv/mbs/wp-content/uploads/2026/10/CPI-September-2026.pdf', '2026-09-30', 'Also shown in MMA Table 1 (1.17%). Food and beverages +8.59%, tobacco -29.11% year-on-year.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MV', 1, 'inflation_projection', 0.025, NULL, 'assumption', 'MBS/MMA national inflation 2021-2025: 0.5%, 2.3%, 2.9%, 1.4%, 4.0% (average about 2.2%)', 'https://database.mma.gov.mv/mosac/latest/1.xlsx', '2026-10-31', 'The rufiyaa is pegged to the US dollar and there is no inflation target, so we plan with a rounded 5-year average.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MV', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published term-life premium guide or regulator data found. Web search budget ran out during research; only official sites reachable by direct link were checked.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MV', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No industry claim settlement ratio published by the MMA (insurance supervisor) found. Web search budget ran out during research; only official sites reachable by direct link were checked.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MV', 1, 'life_expectancy', 81.285, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN (UN WPP)', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=MV', '2024-12-31', 'Men 79.9, women 83.0. Latest published figure is for 2024 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MV', 1, 'life_table_remaining', NULL, NULL, 'missing', '', '', '2026-10-31', 'WHO GHO API was down (HTTP 500) and MBS publishes no life table on its site. Web search budget ran out during research; only official sites reachable by direct link were checked.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MV', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":65,"womenAge":65,"over90Monthly":null,"meansTested":false}', 'sourced', 'Maldives Pension Administration Office: Basic Pension', 'https://www.pension.gov.mv/basic-pension', '2026-10-31', 'All Maldivian citizens aged 65+, under the Maldives Pension Act; not means-tested, but offset against other state pensions.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MV', 1, 'old_age_allowance_monthly', 5000, NULL, 'sourced', 'Maldives Pension Administration Office, Pension System leaflet: Old Age Basic Pension', 'https://storage.googleapis.com/staging.mpao-1327.appspot.com/strapi/Pension_System_5621c2df3d/Pension_System_5621c2df3d.pdf', '2019-03-01', 'MVR 5,000 a month since March 2019 for citizens aged 65+ (older than 2025: the leaflet is undated and no later change was found); reduced by other state pension income, so total pension income is at least MVR 5,000.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MV', 1, 'oop_health_share', 0.1805, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS (WHO GHED)', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=MV', '2023-12-31', 'Latest published figure is for 2023 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MV', 1, 'policy_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The MMA sets no single policy rate; its Standing Deposit Facility pays 0.25% and the Standing Lending Facility charges 7% (MMA Table 8, September 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MV', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":16,"entryAgeMax":65,"pensionFromAge":65,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'Maldives Pension Administration Office, Pension System leaflet: Maldives Retirement Pension Scheme (MRPS)', 'https://storage.googleapis.com/staging.mpao-1327.appspot.com/strapi/Pension_System_5621c2df3d/Pension_System_5621c2df3d.pdf', '2026-10-31', 'Defined-contribution scheme: employer and employee each pay 7% of basic salary (14% in all); employees aged 16-65 and the self-employed can join. Pension from 65 (55 under conditions), paid as the account balance spread over 168 months (14 years); the basic pension tops low payouts up to MVR 5,000.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MV', 1, 'retirement_accumulation_return_base', 0.055, NULL, 'assumption', 'Mix of equity base 7% and fixed income base 4%', 'https://database.mma.gov.mv/mosac/latest/8.xlsx', '2026-10-31', 'Roughly half equity and half safe fixed income over a working life.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MV', 1, 'retirement_accumulation_return_high', 0.075, NULL, 'assumption', 'Equity high 10%, fixed income high 5%', 'https://database.mma.gov.mv/mosac/latest/8.xlsx', '2026-10-31', 'A growth-tilted mix in a good decade.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MV', 1, 'retirement_accumulation_return_low', 0.035, NULL, 'assumption', 'Deposits and bills 3-4.6%', 'https://database.mma.gov.mv/mosac/latest/8.xlsx', '2026-10-31', 'A balanced mix that earns little more than deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MV', 1, 'retirement_age_default', 65, NULL, 'sourced', 'Maldives Pension Administration Office, Pension System leaflet: MRPS retirement pension age', 'https://storage.googleapis.com/staging.mpao-1327.appspot.com/strapi/Pension_System_5621c2df3d/Pension_System_5621c2df3d.pdf', '2026-10-31', 'Same for men and women, including anyone born after 1975; members who meet the conditions can draw a pension from 55.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MV', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'No official statement of the civil service retirement age read. Web search budget ran out during research; only official sites reachable by direct link were checked.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MV', 1, 'retirement_return_base', 0.04, NULL, 'assumption', 'MMA: 91-364 day Treasury bills 3.87%-4.6%', 'https://database.mma.gov.mv/mosac/latest/8.xlsx', '2026-10-31', 'Below the 1-year bill rate of 4.6%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MV', 1, 'retirement_return_high', 0.045, NULL, 'assumption', 'MMA: 364-day Treasury bill 4.6%', 'https://database.mma.gov.mv/mosac/latest/8.xlsx', '2026-10-31', 'Equal to the 1-year bill rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MV', 1, 'retirement_return_low', 0.03, NULL, 'assumption', 'MMA: short time deposits 2.98%', 'https://database.mma.gov.mv/mosac/latest/8.xlsx', '2026-10-31', 'Short bank deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MV', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate or retail savings bond for individuals found. Web search budget ran out during research; only official sites reachable by direct link were checked.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MV', 1, 'savings_account_rate', 0.0136, NULL, 'sourced', 'Maldives Monetary Authority, Table 8 Interest Rates: commercial bank saving deposits (MVR, weighted average)', 'https://database.mma.gov.mv/mosac/latest/8.xlsx', '2026-09-30', NULL, 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MV', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":15.3},{"year":2040,"value":6.5},{"year":2065,"value":1.3}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025: 6.5) and UN WPP 2024 medium variant via PopulationPyramid.net (2040: 15.4, 2065: 77.7)', 'https://www.populationpyramid.net/maldives/2065/', '2025-12-31', 'Working-age people per person 65+ = 100 / old-age dependency ratio; UN projects very fast ageing after 2040.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MV', 1, 'tax_bank_interest', NULL, NULL, 'missing', '', '', '2026-10-31', 'Maldives Inland Revenue Authority site returned HTTP 403 and PwC Tax Summaries has no Maldives page; tax treatment of deposit interest not confirmed. Web search budget ran out during research; only official sites reachable by direct link were checked.', 0);
