INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MV', 1, 'tbill_91d_rate', 0.0387, NULL, 'sourced', 'Maldives Monetary Authority, Table 8 Interest Rates: 91-day Treasury bill', 'https://database.mma.gov.mv/mosac/latest/8.xlsx', '2026-09-30', 'Bills are sold on tap at fixed rates (unchanged since 2015): 28-day 3.5%, 182-day 4.23%, 364-day 4.6%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MV', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published 10-year government bond yield found on MMA tables. Web search budget ran out during research; only official sites reachable by direct link were checked.', 0);
