INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('MW', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"MW","iso3":"MWI","nameEn":"Malawi","nameNative":"Malaŵi","region":"sub_saharan_africa","languages":["ny","en","tum","yao"],"currency":{"code":"MWK","symbol":"K","decimals":2,"compact":"intl","usdRate":{"value":1734.0118,"status":"sourced","sourceName":"Reserve Bank of Malawi, major foreign exchange rates (US dollar middle rate), 30 October 2026","sourceUrl":"https://www.rbm.mw/Statistics/MajorRates/","asOf":"2026-10-30","note":"Official middle rate (buying 1,717.02, selling 1,751.00), unchanged through late October 2026; parallel-market rates are much higher. World Bank''s last annual figure is 1,161.1 for 2023."}},"instruments":{"savings_account":{"available":true,"localName":"Savings account","localNameEn":null,"note":"Average savings rate last published by the central bank: 4.27% (October 2023).","sourceUrl":"https://www.rbm.mw/Statistics/BankRates/"},"fdr_3m":{"available":true,"localName":"Fixed deposit","localNameEn":null,"note":"3-month fixed deposits average 6.03% (June 2026).","sourceUrl":"https://www.rbm.mw/Statistics/BankRates/"},"fdr_1y":{"available":true,"localName":"Fixed deposit","localNameEn":null,"note":"The central bank publishes 3- and 6-month fixed deposit rates only.","sourceUrl":"https://www.rbm.mw/Statistics/BankRates/"},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No standard monthly recurring deposit product with published rates was found."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate for individuals was found."},"tbill_91d":{"available":true,"localName":"Treasury bill","localNameEn":null,"note":"91, 182 and 364-day bills auctioned by the Reserve Bank; open to individuals through banks.","sourceUrl":"https://www.rbm.mw/FinancialMarkets/TreasuryBills/"},"tbond_5y":{"available":true,"localName":"Treasury note","localNameEn":null,"note":"2, 3, 5, 7 and 10-year notes auctioned by the Reserve Bank; only 2-year notes were auctioned in 2026 up to October.","sourceUrl":"https://www.rbm.mw/FinancialMarkets/TreasuryNotes/"},"tbond_10y":{"available":true,"localName":"Treasury note","localNameEn":null,"note":"Last 10-year auction in 2025.","sourceUrl":"https://www.rbm.mw/FinancialMarkets/TreasuryNotes/"},"equity_fund":{"available":true,"localName":"Unit trust","localNameEn":null,"note":"Collective investment schemes are licensed and supervised by the Reserve Bank as capital-markets regulator; shares trade on the Malawi Stock Exchange.","sourceUrl":"https://www.rbm.mw/Supervision/MicrofinanceandCapitalMarkets/?activeTab=MCSUCapitalMarkets"},"gold":{"available":false,"localName":null,"localNameEn":null,"note":"No retail market in gold bars or coins for savers was found; gold is mainly bought as jewellery."}},"institutions":{"centralBank":{"name":"Reserve Bank of Malawi","url":"https://www.rbm.mw/"},"insuranceRegulator":{"name":"Reserve Bank of Malawi, Pensions and Insurance Supervision (Registrar of Financial Institutions)","url":"https://www.rbm.mw/Supervision/PensionsandInsurance/?activeTab=PISUInsurance"},"insuranceComplaints":{"name":"Reserve Bank of Malawi, consumer protection and complaints handling","url":"https://www.rbm.mw/FinancialSectorRegulation/Consumer/"},"pensionScheme":{"name":"Mandatory pension under the Pension Act 2023 (supervised by the Reserve Bank of Malawi)","url":"https://www.rbm.mw/Supervision/PensionsandInsurance/?activeTab=PISUPensions","note":"Employer-provided pension funds, not a state-run scheme."},"oldAgeAllowance":null,"publicHealthCover":{"name":"Ministry of Health (free care at public health facilities)","url":"https://www.health.gov.mw/"},"depositInsurance":null,"statistics":{"name":"National Statistical Office of Malawi","url":"https://www.nsomalawi.mw/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MW', 1, 'bank_deposit_avg_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No weighted average deposit rate across banks was found; the central bank lists separate savings, call and fixed deposit rates, and the World Bank series has no recent Malawi value.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MW', 1, 'credit_card_rate_cap', 0.318, NULL, 'sourced', 'Reserve Bank of Malawi, commercial bank rates (maximum lending rate), August 2026', 'https://www.rbm.mw/Statistics/BankRates/', '2026-08-31', 'Highest lending rate charged by banks (minimum 20.8%, equal to the reference rate); not card-specific and not a legal cap.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MW', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No deposit insurance scheme or cover limit was found on the central bank''s website.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MW', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No standard monthly recurring deposit product with a published rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MW', 1, 'equity_return_base', 0.15, NULL, 'assumption', 'RBM Treasury bill auction of 27 October 2026 (364-day 16%); inflation assumption 15%', 'https://www.rbm.mw/Home/GetContentFile/?ContentID=63839', '2026-10-31', 'Base case: about the inflation assumption and below the 364-day bill yield plus 4 points, because the local index''s strong nominal record mostly reflects inflation and currency depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MW', 1, 'equity_return_high', 0.22, NULL, 'assumption', 'RBM inflation series and Treasury yields', 'https://www.rbm.mw/Statistics/InflationRates/', '2026-10-31', 'High case: equities beat inflation by several points, as in 2023-2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MW', 1, 'equity_return_low', 0.08, NULL, 'assumption', 'Reserve Bank of Malawi, Treasury bill auction of 27 October 2026; inflation series', 'https://www.rbm.mw/Home/GetContentFile/?ContentID=63839', '2026-10-31', 'Low case: Malawi Stock Exchange shares lag inflation for a long stretch, as after its 2023-2025 boom.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MW', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The central bank publishes 3- and 6-month fixed deposit rates only (6.03% in June 2026); no 1-year rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MW', 1, 'fdr_3m_rate', 0.0603, NULL, 'sourced', 'Reserve Bank of Malawi, commercial bank rates (3-month fixed deposit rate), June 2026', 'https://www.rbm.mw/Statistics/BankRates/', '2026-06-30', 'Average 3-month fixed deposit rate 6.03% (6-month also 6.03%, 30-day call 5.88%), far below inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MW', 1, 'fixed_income_return_base', 0.12, NULL, 'assumption', 'Reserve Bank of Malawi, Treasury bill auction of 27 October 2026 (91-day 12%, 364-day 16%)', 'https://www.rbm.mw/Home/GetContentFile/?ContentID=63839', '2026-10-31', 'Base case: Treasury bills between the 91-day (12%) and 364-day (16%) yields, less a possible withholding tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MW', 1, 'fixed_income_return_high', 0.16, NULL, 'assumption', 'Reserve Bank of Malawi, Treasury bill and note auctions (364-day 16%, 2-year 18% in October 2026)', 'https://www.rbm.mw/Home/GetContentFile/?ContentID=63839', '2026-10-31', 'High case: 364-day bills or 2-year notes at 16-18%, less a possible tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MW', 1, 'fixed_income_return_low', 0.06, NULL, 'assumption', 'Reserve Bank of Malawi commercial bank rates (3-month fixed deposits 6.03%, June 2026)', 'https://www.rbm.mw/Statistics/BankRates/', '2026-10-31', 'Low case: fixed deposits at about 6% (tax on interest unconfirmed).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MW', 1, 'goal_inflation_education', 0.17, NULL, 'assumption', 'RBM inflation series; inflation assumption 15%', 'https://www.rbm.mw/Statistics/InflationRates/', '2026-10-31', 'No education CPI series was read; private school fees usually rise faster than general prices, so 2 points above the 15% inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MW', 1, 'goal_inflation_health', 0.17, NULL, 'assumption', 'RBM inflation (non-food 31.5%, September 2026); inflation assumption 15%', 'https://www.rbm.mw/Statistics/InflationRates/', '2026-10-31', 'No medical CPI series was read; non-food prices, including imported medicines, rise faster than food, so 2 points above the 15% inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MW', 1, 'gold_return_base', 0.14, NULL, 'assumption', 'Reserve Bank of Malawi exchange rates (about 1,734 kwacha per dollar in October 2026 against about 730 in 2016)', 'https://www.rbm.mw/Statistics/MajorRates/', '2026-10-31', 'Base case: the long-run dollar gold trend of about 4% a year plus about 10% a year kwacha depreciation against the dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MW', 1, 'gold_return_high', 0.22, NULL, 'assumption', 'Reserve Bank of Malawi exchange rates', 'https://www.rbm.mw/Statistics/MajorRates/', '2026-10-31', 'High case: strong gold years and a sharp kwacha devaluation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MW', 1, 'gold_return_low', 0.06, NULL, 'assumption', 'Reserve Bank of Malawi exchange rates (about 1,734 kwacha per dollar in October 2026)', 'https://www.rbm.mw/Statistics/MajorRates/', '2026-10-31', 'Low case: flat dollar gold with slow kwacha depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MW', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Employment Act''s severance or end-of-service rules as they apply on retirement (alongside the mandatory pension) could not be read from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MW', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a major private hospital stay in Malawi was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MW', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premiums by age were found from a public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MW', 1, 'inflation_cpi', 0.194, NULL, 'sourced', 'Reserve Bank of Malawi, inflation rates (National Statistical Office CPI), September 2026', 'https://www.rbm.mw/Statistics/InflationRates/', '2026-09-30', 'Headline inflation 19.4% year on year in September 2026 (food 12.5%, non-food 31.5%), down from 28.4% average in 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MW', 1, 'inflation_projection', 0.15, NULL, 'assumption', 'RBM Monetary Policy Committee, 28 October 2026 (5% medium-term objective; 22% projected for 2026, 20% for 2027); RBM inflation series', 'https://www.rbm.mw/Home/GetContentFile/?ContentID=63843', '2026-10-31', 'Inflation has averaged over 20% since 2022 and the central bank projects 20% for 2027 against a 5% objective, so 15% is used as a long-run planning rate that assumes partial disinflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MW', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published indicative term-life premium rates per 1,000 kwacha of cover were found from the regulator or another public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MW', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Registrar of Financial Institutions (Reserve Bank of Malawi) publishes no industry-wide life claim settlement ratio that could be found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MW', 1, 'life_expectancy', 67.561, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN), Malawi', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=MW', '2024-12-31', '67.6 years in 2024 (men 64.3, women 70.8); UN WPP 2024 gives 67.9 for 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MW', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":17.4,"men":15.8,"women":18.9},{"age":65,"total":14.2,"men":12.7,"women":15.4},{"age":70,"total":11.1,"men":10,"women":12.1},{"age":80,"total":6.4,"men":5.8,"women":7}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/malawi/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MW', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension was found (see old_age_allowance_monthly).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MW', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension was found; the Social Cash Transfer Programme targets poor households, not older people by age, and no official source on a social pension was read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MW', 1, 'oop_health_share', 0.12, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), Malawi', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=MW', '2023-12-31', '12.0% in 2023 (WHO Global Health Expenditure Database); older than 2025, the latest available. Low because public facilities are free and donors fund much of health spending.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MW', 1, 'policy_rate', 0.24, NULL, 'sourced', 'Reserve Bank of Malawi, Monetary Policy Committee statement, fourth meeting of 2026', 'https://www.rbm.mw/Home/GetContentFile/?ContentID=63843', '2026-10-28', 'Policy rate held at 24.0% on 28 October 2026; the Lombard rate was raised to 26.0%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MW', 1, 'public_pension_scheme', NULL, NULL, 'missing', '', '', '2026-10-31', 'There is no state-run contributory pension for private-sector workers: the Pension Act 2023 makes employers enrol staff in licensed pension funds (minimum 10% employer, 5% employee) supervised by the Reserve Bank, and civil servants are in the Government Public Pension Scheme; no official scheme rules (pension age, indexation) could be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MW', 1, 'retirement_accumulation_return_base', 0.13, NULL, 'assumption', 'RBM Treasury auctions; equity base 15%; gold base 14%', 'https://www.rbm.mw/Home/GetContentFile/?ContentID=63839', '2026-10-31', 'Base case: a balanced mix of Treasury bills and notes, local equities and some foreign-linked assets.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MW', 1, 'retirement_accumulation_return_high', 0.17, NULL, 'assumption', 'RBM Treasury auctions; equity high 22%', 'https://www.rbm.mw/Home/GetContentFile/?ContentID=63839', '2026-10-31', 'High case: a growth-leaning mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MW', 1, 'retirement_accumulation_return_low', 0.09, NULL, 'assumption', 'RBM Treasury and deposit rates', 'https://www.rbm.mw/Home/GetContentFile/?ContentID=63839', '2026-10-31', 'Low case: a mix earning about deposit and short bill rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MW', 1, 'retirement_age_default', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Pension Act 2023 lets members retire between 50 and 70 under fund rules (WageIndicator, updated March 2026); no single statutory pension age for private-sector workers was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MW', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'The retirement age for civil servants under the Government Public Pension Scheme could not be confirmed from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MW', 1, 'retirement_return_base', 0.11, NULL, 'assumption', 'Reserve Bank of Malawi, Treasury bill auction of 27 October 2026 (91-day 12%, 364-day 16%)', 'https://www.rbm.mw/Home/GetContentFile/?ContentID=63839', '2026-10-31', 'Base case: Treasury bills after a possible 20% withholding tax (about 12.8% on 364-day bills), rounded down; not above the after-tax safe rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MW', 1, 'retirement_return_high', 0.14, NULL, 'assumption', 'Reserve Bank of Malawi, Treasury bill and note auctions (364-day 16%, 2-year 18%)', 'https://www.rbm.mw/Home/GetContentFile/?ContentID=63839', '2026-10-31', 'High case: longer bills and short notes.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MW', 1, 'retirement_return_low', 0.06, NULL, 'assumption', 'Reserve Bank of Malawi commercial bank rates (fixed deposits 6.03%)', 'https://www.rbm.mw/Statistics/BankRates/', '2026-10-31', 'Low case: fixed deposits at about 6%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MW', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate or retail savings bond for individuals was found; the government borrows through Treasury bill and note auctions run by the central bank.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MW', 1, 'savings_account_rate', 0.0427, NULL, 'sourced', 'Reserve Bank of Malawi, commercial bank rates (savings deposit rate)', 'https://www.rbm.mw/Statistics/BankRates/', '2023-10-31', 'Latest savings deposit rate the central bank publishes is 4.27% for October 2023 (older than 2025; no newer figure).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MW', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":22.13},{"year":2040,"value":19.23},{"year":2065,"value":8.55}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/malawi/2040/', '2025-12-31', '100 / old-age dependency ratio: 4.52 (2025, World Bank), 5.2 (2040) and 11.7 (2065, populationpyramid.net/malawi/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MW', 1, 'tax_bank_interest', NULL, NULL, 'missing', '', '', '2026-10-31', 'The tax authority''s website content could not be read and PwC Tax Summaries has no Malawi page, so the withholding rate on bank interest could not be confirmed from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MW', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate exists, and the tax on interest from Treasury securities for individuals could not be confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MW', 1, 'tbill_91d_rate', 0.12, NULL, 'sourced', 'Reserve Bank of Malawi, results of Treasury bills auction held on 27 October 2026', 'https://www.rbm.mw/Home/GetContentFile/?ContentID=63839', '2026-10-27', 'Average yield on the 91-day bill 12.00% (182-day 14.50% at the previous auction, 364-day 16.00%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MW', 1, 'tbond_10y_rate', 0.35, NULL, 'sourced', 'Reserve Bank of Malawi, results of 2, 3, 5, 7 and 10-year Treasury notes reopening auction, 18 December 2025', 'https://www.rbm.mw/Home/GetContentFile/?ContentID=62152', '2025-12-18', 'Yield 35.00% on the 10-year note (coupon 15.00%); no 10-year auction was held in 2026 up to October, and shorter yields have since fallen, so this figure is likely stale.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MW', 1, 'tbond_5y_rate', 0.32, NULL, 'sourced', 'Reserve Bank of Malawi, results of 2, 3, 5, 7 and 10-year Treasury notes reopening auction, 18 December 2025', 'https://www.rbm.mw/Home/GetContentFile/?ContentID=62152', '2025-12-18', 'Yield 32.00% on the 5-year note (coupon 12.50%); no 5-year auction was held in 2026 up to October, and shorter yields have since fallen (2-year from 28.75% to 18.00% by October 2026), so this figure is likely stale.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('MX', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"MX","iso3":"MEX","nameEn":"Mexico","nameNative":"México","region":"latin_america_caribbean","languages":["es","en","nhe","yua"],"currency":{"code":"MXN","symbol":"$","decimals":2,"compact":"intl","usdRate":{"value":18.7962,"status":"sourced","sourceName":"Banco de México (SIE) CF102, tipo de cambio FIX","sourceUrl":"https://www.banxico.org.mx/SieInternet/consultarDirectorioInternetAction.do?sector=6&accion=consultarCuadro&idCuadro=CF102&locale=es","asOf":"2026-10-30","note":"FIX rate MXN 18.7962 per US dollar on 30 October 2026; World Bank 2025 average 19.24."}},"instruments":{"savings_account":{"available":true,"localName":"Cuenta de ahorro","localNameEn":"Savings account","sourceUrl":"https://www.banxico.org.mx/SieInternet/consultarDirectorioInternetAction.do?sector=18&accion=consultarCuadro&idCuadro=CF117&locale=es"},"fdr_3m":{"available":true,"localName":"Depósito a plazo fijo a 3 meses","localNameEn":"3-month fixed-term deposit","sourceUrl":"https://www.banxico.org.mx/SieInternet/consultarDirectorioInternetAction.do?sector=18&accion=consultarCuadro&idCuadro=CF117&locale=es"},"fdr_1y":{"available":true,"localName":"Depósito a plazo fijo a 1 año","localNameEn":"1-year fixed-term deposit","note":"Banks offer 1-year term deposits and pagarés, but Banxico publishes average rates only up to 6 months."},"dps":{"available":false,"localName":null,"localNameEn":"Monthly recurring deposit","note":"No standard recurring-deposit product with a published rate; regular savers use savings accounts or scheduled purchases of CETES through Cetesdirecto."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":"Government savings certificate","note":"No separate retail savings certificate; individuals buy ordinary federal government securities through the government''s Cetesdirecto programme."},"tbill_91d":{"available":true,"localName":"CETES (Certificados de la Tesorería de la Federación)","localNameEn":"Federal Treasury Certificates","sourceUrl":"https://www.banxico.org.mx/SieInternet/consultarDirectorioInternetAction.do?sector=22&accion=consultarCuadro&idCuadro=CF107&locale=es"},"tbond_5y":{"available":true,"localName":"Bonos de Desarrollo a tasa fija (Bonos M)","localNameEn":"Fixed-rate federal government bonds","sourceUrl":"https://www.banxico.org.mx/SieInternet/consultarDirectorioInternetAction.do?sector=22&accion=consultarCuadro&idCuadro=CF107&locale=es"},"tbond_10y":{"available":true,"localName":"Bonos de Desarrollo a tasa fija (Bonos M)","localNameEn":"Fixed-rate federal government bonds","sourceUrl":"https://www.banxico.org.mx/SieInternet/consultarDirectorioInternetAction.do?sector=22&accion=consultarCuadro&idCuadro=CF107&locale=es"},"equity_fund":{"available":true,"localName":"Fondos de inversión de renta variable","localNameEn":"Equity investment funds","note":"Equity funds and index-tracking exchange-traded funds are sold to retail investors through regulated intermediaries."},"gold":{"available":true,"localName":"Monedas de oro (Centenario, Libertad)","localNameEn":"Gold coins (Centenario, Libertad)","note":"Banco de México''s gold bullion coins are legal tender and can be bought and sold by individuals."}},"institutions":{"centralBank":{"name":"Banco de México (Banxico)","url":"https://www.banxico.org.mx/"},"insuranceRegulator":{"name":"Comisión Nacional de Seguros y Fianzas (CNSF)","url":"https://www.gob.mx/cnsf"},"insuranceComplaints":{"name":"Comisión Nacional para la Protección y Defensa de los Usuarios de Servicios Financieros (CONDUSEF)","url":"https://www.condusef.gob.mx/"},"pensionScheme":{"name":"Instituto Mexicano del Seguro Social (IMSS) pensions, with individual accounts supervised by CONSAR","url":"https://www.gob.mx/consar"},"oldAgeAllowance":{"name":"Pensión para el Bienestar de las Personas Adultas Mayores","url":"https://www.programasparaelbienestar.gob.mx/programas/adultos-mayores/pension-para-personas-adultas-mayores/"},"publicHealthCover":{"name":"IMSS-Bienestar (free public health care for people without social security)","url":"https://www.gob.mx/imssbienestar"},"depositInsurance":{"name":"Instituto para la Protección al Ahorro Bancario (IPAB)","url":"https://www.gob.mx/ipab/que-hacemos"},"statistics":{"name":"Instituto Nacional de Estadística y Geografía (INEGI)","url":"https://www.inegi.org.mx/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MX', 1, 'bank_deposit_avg_rate', 0.0522, NULL, 'sourced', 'Banco de México (SIE) CF112, Costo porcentual promedio de captación (CPP)', 'https://www.banxico.org.mx/SieInternet/consultarDirectorioInternetAction.do?sector=18&accion=consultarCuadro&idCuadro=CF112&locale=es', '2026-10-31', 'Average cost of peso deposits (CPP) 5.22% in October 2026; the cost of term deposits at commercial banks (CCP) was 6.10%. World Bank deposit rate 2.55% (2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MX', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap on credit card interest was confirmed and Banxico''s household credit table (CF303) shows no recent credit card figure (N/E for July-September 2026); Banxico''s credit card indicators report could not be reached.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MX', 1, 'deposit_insurance_limit', 3555000, NULL, 'sourced', 'IPAB, ¿Qué hacemos? (400,000 UDIs); UDI value from Banco de México SIE CP150', 'https://www.gob.mx/ipab/que-hacemos', '2026-10-31', 'IPAB''s bank deposit insurance covers up to 400,000 UDIs (per person per bank); the UDI was about 8.89 pesos at the end of October 2026 (8.8977 on 10 November 2026, Banxico SIE CP150), so the cover is about MXN 3.555 million.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MX', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No monthly recurring deposit product with a published average rate was found in Banxico''s deposit-rate tables.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MX', 1, 'equity_return_base', 0.085, NULL, 'assumption', 'After-tax 1-year CETES 7.12% less 0.90% withholding = 6.2% (Banxico CF107); Banxico 3% inflation target', 'https://www.banxico.org.mx/SieInternet/consultarDirectorioInternetAction.do?sector=22&accion=consultarCuadro&idCuadro=CF107&locale=es', '2026-10-31', 'Base case: about 2.3 points over the after-tax safe rate, kept modest because the Mexican index has lagged over the past ten years.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MX', 1, 'equity_return_high', 0.11, NULL, 'assumption', 'Long-run emerging-market equity returns in local currency; Banxico CF107 yields', 'https://www.banxico.org.mx/SieInternet/consultarDirectorioInternetAction.do?sector=22&accion=consultarCuadro&idCuadro=CF107&locale=es', '2026-10-31', 'High case: Mexican and global shares recover their long-run record in peso terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MX', 1, 'equity_return_low', 0.04, NULL, 'assumption', 'Mexican stock exchange main index (IPC), weak 10-year record; CETES 364-day 7.12% gross (Banxico CF107)', 'https://www.banxico.org.mx/SieInternet/consultarDirectorioInternetAction.do?sector=22&accion=consultarCuadro&idCuadro=CF107&locale=es', '2026-10-31', 'Low case: the local index repeats its weak decade, leaving equities below after-tax government bills.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MX', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Banxico''s CF117 table publishes counter and weighted rates for terms up to 6 months (6-month fixed deposits 4.57% gross, September 2026) but no 1-year deposit rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MX', 1, 'fdr_3m_rate', 0.0567, NULL, 'sourced', 'Banco de México (SIE) CF117, ventanilla rate at opening, depósitos a plazo fijo 3 meses, gross', 'https://www.banxico.org.mx/SieInternet/consultarDirectorioInternetAction.do?sector=18&accion=consultarCuadro&idCuadro=CF117&locale=es', '2026-09-30', 'Average counter (posted) gross rate on 3-month fixed deposits, September 2026 (4.31% net); the weighted gross rate actually paid on 90-day deposits was 6.34%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MX', 1, 'fixed_income_return_base', 0.062, NULL, 'assumption', 'CETES 364 days 7.12% (Banxico CF107) less 0.90% withholding', 'https://www.banxico.org.mx/SieInternet/consultarDirectorioInternetAction.do?sector=22&accion=consultarCuadro&idCuadro=CF107&locale=es', '2026-10-31', 'Base case: one-year government bills (CETES) after withholding.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MX', 1, 'fixed_income_return_high', 0.078, NULL, 'assumption', 'Bono M 5 years 8.78% (Banxico CF107) less 0.90% withholding', 'https://www.banxico.org.mx/SieInternet/consultarDirectorioInternetAction.do?sector=22&accion=consultarCuadro&idCuadro=CF107&locale=es', '2026-10-31', 'High case: locking in five-year fixed-rate government bonds at today''s yield.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MX', 1, 'fixed_income_return_low', 0.048, NULL, 'assumption', '3-month fixed deposit 5.67% gross (Banxico CF117) less 0.90% withholding', 'https://www.banxico.org.mx/SieInternet/consultarDirectorioInternetAction.do?sector=18&accion=consultarCuadro&idCuadro=CF117&locale=es', '2026-10-31', 'Low case: rolling short bank deposits after the withholding tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MX', 1, 'goal_inflation_education', 0.055, NULL, 'assumption', 'Banxico SIE CP154: education (colegiaturas) index 149.1 in September 2026 vs 145.5 for headline CPI (base 2Q July 2018 = 100)', 'https://www.banxico.org.mx/SieInternet/consultarDirectorioInternetAction.do?sector=8&accion=consultarCuadro&idCuadro=CP154&locale=es', '2026-10-31', 'School fees have risen faster than general prices since 2018 and step up each school year; planning uses 5.5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MX', 1, 'goal_inflation_health', 0.05, NULL, 'assumption', 'Banxico CPI tables (INPC, INEGI); headline 3.45%, core 3.75% (September 2026)', 'https://www.banxico.org.mx/SieInternet/consultarDirectorioInternetAction.do?sector=8&accion=consultarCuadro&idCuadro=CP151&locale=es', '2026-10-31', 'Medical prices in Mexico usually rise faster than general prices; planning uses 5%, about 1 point above projected inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MX', 1, 'gold_return_base', 0.055, NULL, 'assumption', 'Gold USD price trend (Trading Economics); expected peso depreciation of about 1-2 points a year (inflation gap with the US)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Base case: gold tracks long-run dollar inflation plus a little, with the peso weakening slowly in line with the inflation gap.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MX', 1, 'gold_return_high', 0.1, NULL, 'assumption', 'Gold USD price history (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'High case: gold resumes its 2020s uptrend and the peso weakens.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MX', 1, 'gold_return_low', 0, NULL, 'assumption', 'Gold USD 3,876/oz on 30 Oct 2026, 3% lower in a year and far below the January 2026 peak (Trading Economics); FIX MXN 18.80 per dollar', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Low case: gold flat in dollars and the peso stable.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MX', 1, 'gratuity_rule', NULL, '{"daysPerYear":12,"daysPerYearAfter":null,"afterYears":null,"daysPerMonth":30}', 'sourced', 'Ley Federal del Trabajo, articles 162 and 486 (Chamber of Deputies text, last reform 12 June 2015, hosted on gob.mx)', 'https://www.gob.mx/cms/uploads/attachment/file/156203/1044_Ley_Federal_del_Trabajo.pdf', '2015-06-12', 'Prima de antigüedad (LFT art. 162): 12 days'' wages per year of service for permanent workers, paid on dismissal (justified or not), on justified separation, and on voluntary resignation after at least 15 years; under art. 486 the daily wage counted is capped at twice the minimum wage. Text read is the consolidated version last reformed 12 June 2015 (older than 2025); later amendments could not be checked because the Chamber of Deputies law library could not be reached. Separate severance (3 months plus 20 days per year) applies to unjustified dismissal.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MX', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No regulator or statistics-office figure for the typical cost of a private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MX', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No regulator or other non-company source of private health insurance premiums by age was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MX', 1, 'inflation_cpi', 0.0345, NULL, 'sourced', 'Banco de México (SIE), Inflación, cuadro CP151 (INPC, INEGI)', 'https://www.banxico.org.mx/SieInternet/consultarDirectorioInternetAction.do?sector=8&accion=consultarCuadro&idCuadro=CP151&locale=es', '2026-09-30', 'Headline CPI (INPC) rose 3.45% in the 12 months to September 2026; core 3.75%. World Bank 2025 average 3.81%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MX', 1, 'inflation_projection', 0.04, NULL, 'assumption', 'Banxico inflation target 3% ±1 point; 5-year CPI average about 5% (2021-2025, World Bank)', 'https://www.banxico.org.mx/SieInternet/consultarDirectorioInternetAction.do?sector=8&accion=consultarCuadro&idCuadro=CP151&locale=es', '2026-10-31', 'Inflation has been back near 3.5% in 2026 but averaged well above the 3% target over five years, so planning uses 4%, the top of Banxico''s tolerance range.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MX', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life cover is sold in Mexico, but no regulator or other non-company source with indicative premiums by age was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MX', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The CNSF publishes insurance market statistics, but no industry-wide life claim settlement ratio was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MX', 1, 'life_expectancy', 75.264, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=MX', '2024-12-31', 'Men 72.4, women 78.0 (2024; latest World Bank figure, older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MX', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":21.7,"men":20.7,"women":22.5},{"age":65,"total":17.9,"men":17.2,"women":18.5},{"age":70,"total":14.4,"men":13.9,"women":14.8},{"age":80,"total":8.3,"men":8.4,"women":8.3}]}', 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/mexico', '2026-07-01', 'Remaining years derived from the ''life expectancy by current age'' table for 2026 (UN WPP).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MX', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":65,"womenAge":65,"over90Monthly":null,"meansTested":false}', 'sourced', 'Programas para el Bienestar, Pensión para el Bienestar de las Personas Adultas Mayores', 'https://www.programasparaelbienestar.gob.mx/programas/adultos-mayores/pension-para-personas-adultas-mayores/', '2026-10-31', 'Universal: Mexican by birth or naturalisation, living in Mexico, aged 65 or over, regardless of income; registration at a Bienestar module during open registration periods.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MX', 1, 'old_age_allowance_monthly', 3200, NULL, 'sourced', 'Programas para el Bienestar, Pensión para el Bienestar de las Personas Adultas Mayores', 'https://www.programasparaelbienestar.gob.mx/programas/adultos-mayores/pension-para-personas-adultas-mayores/', '2026-10-31', 'MXN 6,400 paid every two months (MXN 3,200 a month) to everyone 65 or over; the page does not state the year, and 6,400 is the 2026 amount (6,200 in 2025). Women aged 60-64 can receive a separate Pensión Mujeres Bienestar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MX', 1, 'oop_health_share', 0.4124, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=MX', '2023-12-31', 'Out-of-pocket spending was 41.2% of current health expenditure in 2023 (latest available; older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MX', 1, 'policy_rate', 0.065, NULL, 'sourced', 'Banco de México, tasa objetivo (anuncios de política monetaria 2026)', 'https://www.banxico.org.mx/publicaciones-y-prensa/anuncios-de-las-decisiones-de-politica-monetaria/anuncios-politica-monetaria-t.html', '2026-09-24', 'Target overnight interbank rate 6.50%, cut 25 bp on 26 March and 7 May 2026 and held on 25 June, 6 August and 24 September 2026 (still 6.50% on 1 November, SIE CF101).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MX', 1, 'public_pension_scheme', NULL, NULL, 'missing', '', '', '2026-10-31', 'The IMSS contributory pension (individual AFORE accounts under the 1997 law, with a guaranteed minimum pension) could not be documented from an official source that could be reached (IMSS refused access; the Chamber of Deputies law library was down).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MX', 1, 'retirement_accumulation_return_base', 0.072, NULL, 'assumption', 'Fixed income base 6.2%; equity base 8.5%', 'https://www.banxico.org.mx/SieInternet/consultarDirectorioInternetAction.do?sector=22&accion=consultarCuadro&idCuadro=CF107&locale=es', '2026-10-31', 'Base case: roughly half peso government securities and half equity.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MX', 1, 'retirement_accumulation_return_high', 0.09, NULL, 'assumption', 'Equity high 11%; Bono M 5 years 8.8% (Banxico CF107)', 'https://www.banxico.org.mx/SieInternet/consultarDirectorioInternetAction.do?sector=22&accion=consultarCuadro&idCuadro=CF107&locale=es', '2026-10-31', 'High case: equities do well and bond yields stay high.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MX', 1, 'retirement_accumulation_return_low', 0.05, NULL, 'assumption', 'After-tax bills and deposits 4.8-6.2%; equity low case 4% (Banxico CF107, CF117)', 'https://www.banxico.org.mx/SieInternet/consultarDirectorioInternetAction.do?sector=22&accion=consultarCuadro&idCuadro=CF107&locale=es', '2026-10-31', 'Low case for a balanced mix of government securities and equity.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MX', 1, 'retirement_age_default', NULL, NULL, 'missing', '', '', '2026-10-31', 'The IMSS pension age under the 1997 Social Security Law (old-age pension at 65, reduced ''cesantía'' pension from 60) could not be confirmed: the IMSS site refused access and the Chamber of Deputies law library (Ley del Seguro Social) could not be reached.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MX', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'The ISSSTE retirement age for federal employees under the 2007 ISSSTE Law could not be confirmed from an official source that could be reached.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MX', 1, 'retirement_return_base', 0.055, NULL, 'assumption', 'CETES 364 days 7.12% less 0.90% withholding = 6.2% (Banxico CF107)', 'https://www.banxico.org.mx/SieInternet/consultarDirectorioInternetAction.do?sector=22&accion=consultarCuadro&idCuadro=CF107&locale=es', '2026-10-31', 'Base case: mostly CETES and short government bonds, kept below the 6.2% after-tax one-year bill rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MX', 1, 'retirement_return_high', 0.07, NULL, 'assumption', 'Bono M 5 years 8.78% less 0.90% withholding (Banxico CF107)', 'https://www.banxico.org.mx/SieInternet/consultarDirectorioInternetAction.do?sector=22&accion=consultarCuadro&idCuadro=CF107&locale=es', '2026-10-31', 'High case: a ladder of medium-term fixed-rate government bonds at today''s yields.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MX', 1, 'retirement_return_low', 0.045, NULL, 'assumption', '3-month fixed deposit 5.67% gross (Banxico CF117) less 0.90% withholding', 'https://www.banxico.org.mx/SieInternet/consultarDirectorioInternetAction.do?sector=18&accion=consultarCuadro&idCuadro=CF117&locale=es', '2026-10-31', 'Low case: rolling short deposits after withholding, allowing for lower rates as Banxico eases.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MX', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Mexico has no separate government savings certificate; individuals buy ordinary federal government securities (CETES, Bonos, Udibonos) directly through the government''s Cetesdirecto programme (see the bill and bond slots).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MX', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Banxico''s weighted gross rate on savings deposits (CF117) was 9.53% in September 2026, but it is pulled up by high-yield digital accounts and is not typical of ordinary accounts at large banks; no typical large-bank savings rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MX', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":7.91},{"year":2040,"value":4.95},{"year":2065,"value":2.72}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/mexico/2065/', '2025-12-31', '100 / old-age dependency ratio: 12.6 in 2025 (World Bank), 20.2 in 2040 and 36.7 in 2065 (UN WPP medium variant).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MX', 1, 'tax_bank_interest', 0.145, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Mexico, withholding taxes (0.90% of invested capital)', 'https://taxsummaries.pwc.com/mexico/corporate/withholding-taxes', '2026-08-06', 'Financial institutions withhold income tax at 0.90% a year of the capital invested, not of the interest; at about a 6.2% yield that is roughly 14.5% of the interest (about 12.6% at the 7.12% one-year CETES yield). The final tax is on real (inflation-adjusted) interest at the saver''s marginal rate in the annual return. PwC page last reviewed 6 August 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MX', 1, 'tax_sanchayapatra_profit', 0.145, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Mexico, withholding taxes (0.90% of invested capital)', 'https://taxsummaries.pwc.com/mexico/corporate/withholding-taxes', '2026-08-06', 'No separate savings certificate; interest on government securities bought by individuals is subject to the same 0.90%-of-capital withholding (about 14.5% of a 6.2% yield), with final tax on real interest in the annual return.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MX', 1, 'tbill_91d_rate', 0.0669, NULL, 'sourced', 'Banco de México (SIE) CF107, Valores gubernamentales, CETES 91 días, primary auction yield', 'https://www.banxico.org.mx/SieInternet/consultarDirectorioInternetAction.do?sector=22&accion=consultarCuadro&idCuadro=CF107&locale=es', '2026-10-29', '91-day CETES 6.69% at the auction of 29 October 2026 (6.75% on 22 October); 28-day 6.22%, 364-day 7.12%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MX', 1, 'tbond_10y_rate', 0.0925, NULL, 'sourced', 'Banco de México (SIE) CF107, Bonos de desarrollo a tasa fija 10 años, primary auction yield', 'https://www.banxico.org.mx/SieInternet/consultarDirectorioInternetAction.do?sector=22&accion=consultarCuadro&idCuadro=CF107&locale=es', '2026-10-22', '10-year fixed-rate government bond 9.25% at the auction of 22 October 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MX', 1, 'tbond_5y_rate', 0.0878, NULL, 'sourced', 'Banco de México (SIE) CF107, Bonos de desarrollo a tasa fija 5 años, primary auction yield', 'https://www.banxico.org.mx/SieInternet/consultarDirectorioInternetAction.do?sector=22&accion=consultarCuadro&idCuadro=CF107&locale=es', '2026-10-29', '5-year fixed-rate government bond (Bono M) 8.78% at the auction of 29 October 2026.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('MY', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"MY","iso3":"MYS","nameEn":"Malaysia","nameNative":"Malaysia","region":"east_asia_pacific","languages":["ms","en","zh","ta"],"currency":{"code":"MYR","symbol":"RM","decimals":2,"compact":"intl","usdRate":{"value":4.0635,"status":"sourced","sourceName":"Bank Negara Malaysia, exchange rates (USD middle rate, noon)","sourceUrl":"https://www.bnm.gov.my/exchange-rates","asOf":"2026-10-30","note":"4.0635 ringgit per US dollar on 30 Oct 2026 as read by the researcher; when re-checked on 3 Nov the same BNM page showed 4.0665 (2 Nov) and 4.0750 (3 Nov), consistent with this level."}},"instruments":{"savings_account":{"available":true,"localName":"Akaun simpanan","localNameEn":"Savings account"},"fdr_3m":{"available":true,"localName":"Simpanan tetap","localNameEn":"Fixed deposit","sourceUrl":"https://www.bnm.gov.my/documents/20124/23499006/2.1.xlsx"},"fdr_1y":{"available":true,"localName":"Simpanan tetap","localNameEn":"Fixed deposit","sourceUrl":"https://www.bnm.gov.my/documents/20124/23499006/2.1.xlsx"},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No common monthly recurring deposit product."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No standing government savings certificate for individuals."},"tbill_91d":{"available":false,"localName":"Bil Perbendaharaan Malaysia","localNameEn":"Malaysian Treasury Bill","note":"Sold at auction to institutions; individuals reach them only through money market funds.","sourceUrl":"https://www.bnm.gov.my/government-securities-yield"},"tbond_5y":{"available":true,"localName":"Sekuriti Kerajaan Malaysia","localNameEn":"Malaysian Government Securities","note":"Individuals can buy MGS through some banks'' bond counters or bond funds.","sourceUrl":"https://www.bnm.gov.my/government-securities-yield"},"tbond_10y":{"available":true,"localName":"Sekuriti Kerajaan Malaysia","localNameEn":"Malaysian Government Securities","sourceUrl":"https://www.bnm.gov.my/government-securities-yield"},"equity_fund":{"available":true,"localName":"Dana unit amanah","localNameEn":"Unit trust fund","note":"Unit trusts and exchange-traded funds are widely sold to retail investors."},"gold":{"available":true,"localName":"Emas","localNameEn":"Gold","note":"Gold bars and coins are sold by jewellers and banks."}},"institutions":{"centralBank":{"name":"Bank Negara Malaysia (BNM)","url":"https://www.bnm.gov.my/"},"insuranceRegulator":{"name":"Bank Negara Malaysia (BNM)","url":"https://www.bnm.gov.my/"},"insuranceComplaints":{"name":"Financial Markets Ombudsman Service (FMOS)","url":"https://www.fmos.org.my/","note":"Formed by consolidating the Ombudsman for Financial Services (OFS) and SIDREC; covers insurance and takaful disputes."},"pensionScheme":{"name":"Employees Provident Fund (EPF / KWSP)","url":"https://www.kwsp.gov.my/"},"oldAgeAllowance":{"name":"Social Welfare Department (JKM), Bantuan Warga Emas","url":"https://www.jkm.gov.my/"},"publicHealthCover":{"name":"Ministry of Health Malaysia (subsidised public hospitals and clinics)","url":"https://www.moh.gov.my/"},"depositInsurance":{"name":"Perbadanan Insurans Deposit Malaysia (PIDM)","url":"https://www.pidm.gov.my/"},"statistics":{"name":"Department of Statistics Malaysia (DOSM)","url":"https://www.dosm.gov.my/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MY', 1, 'bank_deposit_avg_rate', 0.0242, NULL, 'sourced', 'World Bank WDI, deposit interest rate (FR.INR.DPST)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=MY', '2025-12-31', '2.42% average for 2025 (World Bank). BNM Table 2.1 shows the weighted average 12-month fixed deposit rate at 1.92% in September 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MY', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'BNM sets a maximum credit card finance charge in its credit card policy document, but we could not reach the document or a page stating the current figure.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MY', 1, 'deposit_insurance_limit', 250000, NULL, 'sourced', 'Perbadanan Insurans Deposit Malaysia (PIDM), Deposit Insurance System', 'https://www.pidm.gov.my/general/how-we-protect-you/dis', '2026-10-31', 'RM250,000 per depositor per member bank; Islamic and conventional deposits are protected separately.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MY', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No common monthly recurring deposit product with a published rate found; Malaysians save monthly through fixed deposits, unit trusts or EPF voluntary contributions.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MY', 1, 'equity_return_base', 0.065, NULL, 'assumption', '5-year MGS 3.68% plus a modest premium; weak KLCI 10-year record', 'https://www.bnm.gov.my/government-securities-yield', '2026-10-31', 'Base set about 3.7 points above the tax-free safe rate (about 2.8%), below the 4-point limit, because the KLCI''s 10-year record is weak.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MY', 1, 'equity_return_high', 0.09, NULL, 'assumption', 'Long-run Malaysian and regional equity returns', 'https://www.bnm.gov.my/government-securities-yield', '2026-10-31', 'High case with a full equity premium over government bonds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MY', 1, 'equity_return_low', 0.03, NULL, 'assumption', 'FBM KLCI 10-year record; 5-year MGS 3.68%', 'https://www.bnm.gov.my/government-securities-yield', '2026-10-31', 'The KLCI has made little price progress over the past decade, so the low case is a dividend-like 3%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MY', 1, 'fdr_1y_rate', 0.0219, NULL, 'sourced', 'Bank Negara Malaysia, Monthly Highlights & Statistics September 2026, Table 2.1 Interest Rates: Banking Institutions (commercial banks)', 'https://www.bnm.gov.my/documents/20124/23499006/2.1.xlsx', '2026-09-30', 'Average 12-month fixed deposit rate of commercial banks 2.19% in September 2026 (weighted average 1.92%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MY', 1, 'fdr_3m_rate', 0.0215, NULL, 'sourced', 'Bank Negara Malaysia, Monthly Highlights & Statistics September 2026, Table 2.1 Interest Rates: Banking Institutions (commercial banks)', 'https://www.bnm.gov.my/documents/20124/23499006/2.1.xlsx', '2026-09-30', 'Average 3-month fixed deposit rate of commercial banks 2.15% in September 2026 (weighted average 1.80%); promotional rates can be higher.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MY', 1, 'fixed_income_return_base', 0.028, NULL, 'assumption', 'Treasury bill and MGS yields (BNM)', 'https://www.bnm.gov.my/government-securities-yield', '2026-10-31', 'Base case between the 12-month fixed deposit average and the 3-month treasury bill yield, reachable through deposit promotions and money market funds. Safe MYR rates: commercial-bank average fixed deposit 3-month 2.15%, 12-month 2.19% (BNM, Sep 2026); 3-month treasury bill 2.98%, 5-year MGS 3.68%, 10-year MGS 3.89% (BNM, 30 Oct 2026); OPR 2.75%; interest on bank deposits is tax-exempt for individuals.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MY', 1, 'fixed_income_return_high', 0.037, NULL, 'assumption', '5-year MGS yield (BNM)', 'https://www.bnm.gov.my/government-securities-yield', '2026-10-31', 'High case at the 5-year government bond yield. Safe MYR rates: commercial-bank average fixed deposit 3-month 2.15%, 12-month 2.19% (BNM, Sep 2026); 3-month treasury bill 2.98%, 5-year MGS 3.68%, 10-year MGS 3.89% (BNM, 30 Oct 2026); OPR 2.75%; interest on bank deposits is tax-exempt for individuals.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MY', 1, 'fixed_income_return_low', 0.02, NULL, 'assumption', 'BNM average fixed deposit rates (tax-free)', 'https://www.bnm.gov.my/documents/20124/23499006/2.1.xlsx', '2026-10-31', 'Low case just below the 12-month average fixed deposit rate. Safe MYR rates: commercial-bank average fixed deposit 3-month 2.15%, 12-month 2.19% (BNM, Sep 2026); 3-month treasury bill 2.98%, 5-year MGS 3.68%, 10-year MGS 3.89% (BNM, 30 Oct 2026); OPR 2.75%; interest on bank deposits is tax-exempt for individuals.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MY', 1, 'goal_inflation_education', 0.035, NULL, 'assumption', 'Headline CPI (DOSM via Trading Economics)', 'https://tradingeconomics.com/malaysia/inflation-cpi', '2026-10-31', 'Public schooling is largely free while private and tertiary fees rise faster, so we plan 1 point above general inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MY', 1, 'goal_inflation_health', 0.06, NULL, 'assumption', 'Headline CPI (DOSM via Trading Economics); private medical cost trend', 'https://tradingeconomics.com/malaysia/inflation-cpi', '2026-10-31', 'The health CPI covers subsidised public care, but private hospital and insurance costs have risen much faster, so we plan about 3.5 points above general inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MY', 1, 'gold_return_base', 0.055, NULL, 'assumption', 'US-dollar gold trend; ringgit exchange rate (BNM midrate 4.06 per USD)', 'https://www.bnm.gov.my/', '2026-10-31', 'Long-run dollar gold trend of about 5% plus about 0.5% a year of ringgit depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MY', 1, 'gold_return_high', 0.1, NULL, 'assumption', 'US-dollar gold trend; ringgit exchange rate (BNM)', 'https://www.bnm.gov.my/', '2026-10-31', 'High case for a strong gold cycle.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MY', 1, 'gold_return_low', 0.01, NULL, 'assumption', 'US-dollar gold trend; ringgit exchange rate (BNM)', 'https://www.bnm.gov.my/', '2026-10-31', 'Gold can stall for a decade, and the ringgit has strengthened in 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MY', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Employment Act 1955 gives termination and lay-off benefits only when employment is ended by the employer; there is no statutory end-of-service gratuity on retirement.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MY', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a major private hospital stay found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MY', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published medical insurance premium rates by age found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MY', 1, 'inflation_cpi', 0.018, NULL, 'sourced', 'Department of Statistics Malaysia CPI (via Trading Economics)', 'https://tradingeconomics.com/malaysia/inflation-cpi', '2026-09-30', '1.8% year on year in September 2026, down from 1.9% in August; core 1.7%. DOSM release page returned an error, so a secondary source is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MY', 1, 'inflation_projection', 0.025, NULL, 'assumption', '5-year CPI average (2021-2025 about 2.3%); Bank Negara Malaysia has no numeric target', 'https://tradingeconomics.com/malaysia/inflation-cpi', '2026-10-31', 'CPI averaged about 2.3% over 2021-2025 and BNM expects prices to stay elevated on energy costs, so we plan with a rounded 2.5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MY', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life is widely sold, but we could not read published premium rates or a credible premium guide in ringgit.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MY', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No industry-wide life claim settlement ratio published by Bank Negara Malaysia or the life insurance association was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MY', 1, 'life_expectancy', 76.8, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN)', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=MY', '2024-12-31', 'Men 74.4, women 79.5 (2024, older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MY', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":21.5,"men":20.1,"women":23},{"age":65,"total":17.7,"men":16.5,"women":18.9},{"age":70,"total":14.2,"men":13.2,"women":15.2},{"age":80,"total":8.7,"men":8,"women":9.2}]}', 'sourced', 'UN World Population Prospects (via georank.org)', 'https://georank.org/life-expectancy/malaysia', '2026-07-08', 'Remaining years derived from expected age at death by current age; secondary source for UN WPP.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MY', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'Bantuan Warga Emas is means-tested and for older people (60+); could not read the official criteria page (JKM site unreachable).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MY', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'Bantuan Warga Emas (Social Welfare Department) pays a monthly allowance to poor elderly people, but the JKM website was unreachable and we could not read the current amount.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MY', 1, 'oop_health_share', 0.371, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure, SH.XPD.OOPC.CH.ZS)', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=MY', '2023-12-31', 'Latest World Bank (WHO GHED) value is for 2023, older than 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MY', 1, 'policy_rate', 0.0275, NULL, 'sourced', 'Bank Negara Malaysia Monetary Policy Statement, 3 September 2026', 'https://www.bnm.gov.my/-/monetary-policy-statement-03092026', '2026-09-03', 'Overnight Policy Rate held at 2.75%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MY', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":55,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'Employees Provident Fund (Malaysia), Wikipedia', 'https://en.wikipedia.org/wiki/Employees_Provident_Fund_(Malaysia)', '2025-12-31', 'EPF is a provident fund, not a pension: employees pay 11% and employers 12-13% of wages (rates as of 2012 per source); the retirement account can be withdrawn in full from 55. Dividends 6.15% for 2025, 6.30% for 2024; legal minimum 2.5%. inflationLinked false because benefits are a lump sum.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MY', 1, 'retirement_accumulation_return_base', 0.05, NULL, 'assumption', 'EPF dividend record (5.35%-6.30% in 2021-2025, 6.15% for 2025; via Wikipedia); MGS yields', 'https://en.wikipedia.org/wiki/Employees_Provident_Fund_(Malaysia)', '2026-10-31', 'Half equity at 6.5% and half bonds near 3.5%, a little below EPF''s recent dividends.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MY', 1, 'retirement_accumulation_return_high', 0.065, NULL, 'assumption', 'EPF dividend record (5.35%-6.30% in 2021-2025, 6.15% for 2025; via Wikipedia); MGS yields', 'https://en.wikipedia.org/wiki/Employees_Provident_Fund_(Malaysia)', '2026-10-31', 'High case slightly above EPF''s recent dividend rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MY', 1, 'retirement_accumulation_return_low', 0.035, NULL, 'assumption', 'EPF dividend record (5.35%-6.30% in 2021-2025, 6.15% for 2025; via Wikipedia); MGS yields', 'https://en.wikipedia.org/wiki/Employees_Provident_Fund_(Malaysia)', '2026-10-31', 'Low case for a balanced mix with weak equity.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MY', 1, 'retirement_age_default', 60, NULL, 'sourced', 'Wikipedia, Retirement age (Malaysia row); secondary source', 'https://en.wikipedia.org/wiki/Retirement_age', '2026-10-31', 'Retirement age 60 for private employees (raised from 55 in 2013); EPF savings can be fully withdrawn from 55. Secondary source because official Act and labour ministry pages could not be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MY', 1, 'retirement_age_government', 60, NULL, 'sourced', 'Wikipedia, Retirement age (Malaysia note on civil servants); secondary source', 'https://en.wikipedia.org/wiki/Retirement_age', '2026-10-31', 'Civil servants retire at 60; the public-sector union has asked for 62 but the government has no immediate plan to raise it. Official public service department site failed TLS verification.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MY', 1, 'retirement_return_base', 0.027, NULL, 'assumption', 'BNM OPR 2.75%, average 12-month fixed deposit 2.19%, 3-month treasury bill 2.98%', 'https://www.bnm.gov.my/government-securities-yield', '2026-10-31', 'Base case at about the policy rate, below the tax-free treasury bill yield and above the average 1-year deposit rate. Safe MYR rates: commercial-bank average fixed deposit 3-month 2.15%, 12-month 2.19% (BNM, Sep 2026); 3-month treasury bill 2.98%, 5-year MGS 3.68%, 10-year MGS 3.89% (BNM, 30 Oct 2026); OPR 2.75%; interest on bank deposits is tax-exempt for individuals.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MY', 1, 'retirement_return_high', 0.037, NULL, 'assumption', '5-year MGS yield (BNM)', 'https://www.bnm.gov.my/government-securities-yield', '2026-10-31', 'High case at the 5-year government bond yield. Safe MYR rates: commercial-bank average fixed deposit 3-month 2.15%, 12-month 2.19% (BNM, Sep 2026); 3-month treasury bill 2.98%, 5-year MGS 3.68%, 10-year MGS 3.89% (BNM, 30 Oct 2026); OPR 2.75%; interest on bank deposits is tax-exempt for individuals.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MY', 1, 'retirement_return_low', 0.02, NULL, 'assumption', 'BNM average fixed deposit rates (tax-free)', 'https://www.bnm.gov.my/documents/20124/23499006/2.1.xlsx', '2026-10-31', 'Low case just below the 12-month average fixed deposit rate. Safe MYR rates: commercial-bank average fixed deposit 3-month 2.15%, 12-month 2.19% (BNM, Sep 2026); 3-month treasury bill 2.98%, 5-year MGS 3.68%, 10-year MGS 3.89% (BNM, 30 Oct 2026); OPR 2.75%; interest on bank deposits is tax-exempt for individuals.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MY', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Malaysia has no standing government savings certificate for individuals; the last retail government sukuk (Sukuk Prihatin) was a one-off 2020 issue.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MY', 1, 'savings_account_rate', 0.0064, NULL, 'sourced', 'Bank Negara Malaysia, Monthly Highlights & Statistics September 2026, Table 2.1 Interest Rates: Banking Institutions (commercial banks)', 'https://www.bnm.gov.my/documents/20124/23499006/2.1.xlsx', '2026-09-30', 'Average savings deposit rate of commercial banks 0.64% in September 2026 (weighted average 0.32%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MY', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":8.8},{"year":2040,"value":5.7},{"year":2065,"value":2.6}]}', 'sourced', 'UN World Population Prospects 2024, medium variant (via populationpyramid.net)', 'https://www.populationpyramid.net/malaysia/2040/', '2024-07-31', '100 / old-age dependency ratio: 11.4 in 2025, 17.6 in 2040 and 38.7 in 2065 (populationpyramid.net year pages).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MY', 1, 'tax_bank_interest', 0, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Malaysia, income determination', 'https://taxsummaries.pwc.com/malaysia/individual/income-determination', '2026-06-16', 'PwC (last reviewed 16 Jun 2026): interest received by individuals on money deposited in approved institutions (licensed banks and financial institutions) is tax-exempt.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MY', 1, 'tax_sanchayapatra_profit', 0, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Malaysia, income determination', 'https://taxsummaries.pwc.com/malaysia/individual/income-determination', '2026-06-16', 'No savings certificate exists; interest from certain bonds and securities (including government securities) is exempt.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MY', 1, 'tbill_91d_rate', 0.0298, NULL, 'sourced', 'Bank Negara Malaysia, government securities yield (Malaysian Treasury Bills, up to 3 months)', 'https://www.bnm.gov.my/government-securities-yield', '2026-10-30', 'Up to 3-month Malaysian Treasury Bill yield 2.98% on the BNM page; still 2.98% when re-checked on 2 Nov 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MY', 1, 'tbond_10y_rate', 0.0389, NULL, 'sourced', 'Bank Negara Malaysia, MGS benchmark yields (conventional, Oct-2036)', 'https://www.bnm.gov.my/government-securities-yield', '2026-10-30', NULL, 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MY', 1, 'tbond_5y_rate', 0.0368, NULL, 'sourced', 'Bank Negara Malaysia, MGS benchmark yields (conventional, Jun-2031)', 'https://www.bnm.gov.my/government-securities-yield', '2026-10-30', NULL, 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('MZ', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"MZ","iso3":"MOZ","nameEn":"Mozambique","nameNative":"Moçambique","region":"sub_saharan_africa","languages":["pt","vmw","ndc","ts","seh"],"currency":{"code":"MZN","symbol":"MT","decimals":2,"compact":"intl","usdRate":{"value":63.91,"status":"sourced","sourceName":"Banco de Moçambique, reference exchange rates bulletin 170/02/26 (4 September 2026)","sourceUrl":"https://bancomoc.mz/media/1ltp4ejr/taxas-de-c%C3%A2mbio-de-refer%C3%AAncia-09h30_04092026.pdf","asOf":"2026-09-04","note":"Mid rate 63.91 meticais per dollar (buy 63.27, sell 64.54); the latest official bulletin that could be read."}},"instruments":{"savings_account":{"available":true,"localName":"Conta poupança","localNameEn":"Savings account","note":"Offered by banks; interest is withheld at 10%."},"fdr_3m":{"available":true,"localName":"Depósito a prazo (3 meses)","localNameEn":"Term deposit (3 months)","note":"Offered by banks; no published average rate."},"fdr_1y":{"available":true,"localName":"Depósito a prazo (1 ano)","localNameEn":"Term deposit (1 year)","note":"Average 4.34% in May 2026 (Banco de Moçambique).","sourceUrl":"https://www.bancomoc.mz/media/athimwmy/resumo-mensal-de-informa%C3%A7%C3%A3o-estat%C3%ADstica-junho2026.pdf"},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No standard monthly recurring deposit product was found."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate for individuals; retail investors can buy Treasury bonds instead."},"tbill_91d":{"available":true,"localName":"Bilhetes do Tesouro (91 dias)","localNameEn":"Treasury bills (91 days)","note":"Auctioned by the Banco de Moçambique; companies and individuals held about MT 10.9 billion of bills on 26 August 2026.","sourceUrl":"https://bancomoc.mz/media/yardn043/di%C3%A1rio-dos-mercados-26-08-2026.pdf"},"tbond_5y":{"available":true,"localName":"Obrigações do Tesouro","localNameEn":"Treasury bonds","note":"Treasury bonds are issued and listed through the stock exchange (BVM); recent issues run 3 to 6 years at 13.25%. Retail access is through banks and brokers registered with the BVM.","sourceUrl":"https://forbesafricalusofona.com/?p=178111"},"tbond_10y":{"available":false,"localName":null,"localNameEn":null,"note":"No 10-year domestic Treasury bond issue was found for 2025-2026."},"equity_fund":{"available":false,"localName":null,"localNameEn":null,"note":"The stock exchange is small and no diversified retail equity fund was found."},"gold":{"available":false,"localName":null,"localNameEn":null,"note":"No retail channel for investment gold bars or coins was found; gold is bought mainly as jewellery."}},"institutions":{"centralBank":{"name":"Banco de Moçambique","url":"https://www.bancomoc.mz/"},"insuranceRegulator":{"name":"Instituto de Supervisão de Seguros de Moçambique (ISSM)","url":"https://www.issm.gov.mz/"},"insuranceComplaints":{"name":"ISSM consumer service portal (Portal de Atendimento ao Consumidor)","url":"https://www.bsa.issm.gov.mz/cps"},"pensionScheme":{"name":"Instituto Nacional de Segurança Social (INSS)","url":"https://www.inss.gov.mz/"},"oldAgeAllowance":{"name":"Instituto Nacional de Acção Social (INAS), Programa Subsídio Social Básico","url":"https://www.inas.gov.mz/","note":"Poverty-targeted transfer for older people and others unable to work."},"publicHealthCover":{"name":"Ministério da Saúde (national health service)","url":"https://misau.gov.mz/","note":"Public care is free or charged at nominal fees."},"depositInsurance":null,"statistics":{"name":"Instituto Nacional de Estatística (INE)","url":"https://www.ine.gov.mz/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MZ', 1, 'bank_deposit_avg_rate', 0.0577, NULL, 'sourced', 'World Bank WDI, deposit interest rate (FR.INR.DPST), Mozambique', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=MZ', '2025-12-31', 'Average for 2025 (5.77%); the Banco de Moçambique 1-year deposit rate fell to 4.34% by May 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MZ', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap was found; credit is priced off the prime rate (15.50% in May 2026, BdM Resumo Mensal June 2026) plus a bank spread.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MZ', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'A deposit guarantee fund (Fundo de Garantia de Depósitos) exists, but its cover limit per depositor could not be read from an official source; its website was unreachable and the search budget ran out.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MZ', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No standard monthly recurring deposit product or rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MZ', 1, 'equity_return_base', 0.09, NULL, 'assumption', 'No liquid local equity index (Bolsa de Valores de Moçambique is small); global equities in metical terms', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=MZ', '2026-10-31', 'With no liquid local index, equity means global shares in metical terms: about 7% in dollars plus about 2% a year of metical depreciation, below the roughly 11% after-tax bill rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MZ', 1, 'equity_return_high', 0.12, NULL, 'assumption', 'No liquid local equity index (Bolsa de Valores de Moçambique is small); global equities in metical terms', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=MZ', '2026-10-31', 'High case: strong global markets plus faster metical depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MZ', 1, 'equity_return_low', 0.04, NULL, 'assumption', 'No liquid local equity index (Bolsa de Valores de Moçambique is small); global equities in metical terms', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=MZ', '2026-10-31', 'Low case: a weak decade for global shares with a stable metical.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MZ', 1, 'fdr_1y_rate', 0.0434, NULL, 'sourced', 'Banco de Moçambique, Resumo Mensal de Informação Estatística (June 2026 issue), Quadro 4 (average nominal 1-year deposit rate on balances)', 'https://www.bancomoc.mz/media/athimwmy/resumo-mensal-de-informa%C3%A7%C3%A3o-estat%C3%ADstica-junho2026.pdf', '2026-05-31', 'Average 1-year deposit rate 4.34% in May 2026, down from 6.60% a year earlier as the policy rate was cut.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MZ', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published 3-month term deposit rate was found in Banco de Moçambique statistics.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MZ', 1, 'fixed_income_return_base', 0.07, NULL, 'assumption', 'BdM: 1-year deposits 4.34% (May 2026), 91-day and 364-day bills about 12.2% (Aug 2026); 10% tax on deposit and bond interest (PwC)', 'https://bancomoc.mz/media/yardn043/di%C3%A1rio-dos-mercados-26-08-2026.pdf', '2026-10-31', 'Base case: a mix of tax-paid deposits (3.9%) and Treasury bills and bonds (11-12% after tax), allowing for bill rates falling with the policy rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MZ', 1, 'fixed_income_return_high', 0.105, NULL, 'assumption', 'BdM: 1-year deposits 4.34% (May 2026), 91-day and 364-day bills about 12.2% (Aug 2026); 10% tax on deposit and bond interest (PwC)', 'https://forbesafricalusofona.com/?p=178111', '2026-10-31', 'High case: Treasury bonds at 13.25% held to maturity, after the 10% tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MZ', 1, 'fixed_income_return_low', 0.04, NULL, 'assumption', 'BdM: 1-year deposits 4.34% (May 2026), 91-day and 364-day bills about 12.2% (Aug 2026); 10% tax on deposit and bond interest (PwC)', 'https://www.bancomoc.mz/media/athimwmy/resumo-mensal-de-informa%C3%A7%C3%A3o-estat%C3%ADstica-junho2026.pdf', '2026-10-31', 'Low case: bank deposits only, at about 4.3% before the 10% tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MZ', 1, 'goal_inflation_education', 0.07, NULL, 'assumption', 'Inflation assumption 6%; no education CPI projection found', 'https://data.worldbank.org/indicator/FP.CPI.TOTL.ZG?locations=MZ', '2026-10-31', 'Private school and university fees are planned 1 point above general inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MZ', 1, 'goal_inflation_health', 0.075, NULL, 'assumption', 'Inflation assumption 6%; private care and medicines largely imported', 'https://data.worldbank.org/indicator/FP.CPI.TOTL.ZG?locations=MZ', '2026-10-31', 'No medical price projection was found; private medical costs are planned 1.5 points above general inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MZ', 1, 'gold_return_base', 0.08, NULL, 'assumption', 'Gold trend in dollars; metical about 63.9 per dollar (BdM, September 2026), stable since 2021 after large falls in 2016-2017', 'https://bancomoc.mz/media/1ltp4ejr/taxas-de-c%C3%A2mbio-de-refer%C3%AAncia-09h30_04092026.pdf', '2026-10-31', 'Base case: a long-run dollar gold trend of about 5% plus about 3% a year of metical depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MZ', 1, 'gold_return_high', 0.13, NULL, 'assumption', 'Gold trend in dollars; metical about 63.9 per dollar (BdM, September 2026), stable since 2021 after large falls in 2016-2017', 'https://bancomoc.mz/media/1ltp4ejr/taxas-de-c%C3%A2mbio-de-refer%C3%AAncia-09h30_04092026.pdf', '2026-10-31', 'High case: strong gold years and a renewed metical slide.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MZ', 1, 'gold_return_low', 0.02, NULL, 'assumption', 'Gold trend in dollars; metical about 63.9 per dollar (BdM, September 2026), stable since 2021 after large falls in 2016-2017', 'https://bancomoc.mz/media/1ltp4ejr/taxas-de-c%C3%A2mbio-de-refer%C3%AAncia-09h30_04092026.pdf', '2026-10-31', 'Low case: flat dollar gold prices with a stable metical.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MZ', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No statutory retirement gratuity was found; Labour Law 13/2023 (art. 141) gives dismissal compensation in days of pay per year of service by salary band (30 days up to 7 minimum wages per secondary sources), which is not paid on retirement.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MZ', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical out-of-pocket cost of a private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MZ', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No regulator or official source publishing private health insurance premiums by age was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MZ', 1, 'inflation_cpi', 0.0631, NULL, 'sourced', 'INE Moçambique CPI, September 2026, via Trading Economics', 'https://tradingeconomics.com/mozambique/inflation-cpi/news/590844', '2026-09-30', 'Year-on-year inflation 6.31% in September 2026, down from 6.45% in August and 7.51% in June (fuel price shock in May); secondary source as the INE release was not reachable.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MZ', 1, 'inflation_projection', 0.06, NULL, 'assumption', 'Banco de Moçambique aims for single-digit inflation; 2021-2025 CPI average about 6%', 'https://data.worldbank.org/indicator/FP.CPI.TOTL.ZG?locations=MZ', '2026-10-31', 'No numeric target is published; the 2021-2025 average of about 6% (World Bank) matches the 2026 level, so 6% is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MZ', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No regulator or official source publishing term life premiums per MT 1,000 of cover was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MZ', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The insurance supervisor ISSM publishes market bulletins, but no industry life claim settlement ratio was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MZ', 1, 'life_expectancy', 63.797, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN), Mozambique', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=MZ', '2024-12-31', '63.8 years in 2024 (men 60.5, women 66.7).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MZ', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":15.8,"men":14.7,"women":16.9},{"age":65,"total":12.7,"men":11.7,"women":13.2},{"age":70,"total":9.5,"men":9,"women":9.9},{"age":80,"total":5.2,"men":5,"women":5.4}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/mozambique/', '2026-07-01', 'Secondary source of UN WPP 2024 (medium variant) for 2026; totals are the mean of men and women except at 65, where the page gives 12.7.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MZ', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'PSSB eligibility is poverty-targeted; the 2004 regulation set 55 for women and 60 for men, while later studies describe 60 for both, so current official ages could not be confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MZ', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Programa Subsídio Social Básico (INAS) is a poverty-targeted household transfer for older people unable to work, not a pension anyone can plan on: amounts (reported at 540 MT for a one-person household since 2018) are not published officially and only about 5% of its 2024 budget was paid (CIP report, July 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MZ', 1, 'oop_health_share', 0.1037, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), Mozambique', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=MZ', '2023-12-31', '10.4% in 2023 (WHO Global Health Expenditure Database), the latest available; low because public care is nearly free and donors fund much of health spending. Older than 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MZ', 1, 'policy_rate', 0.0925, NULL, 'sourced', 'Banco de Moçambique, MIMO policy rate unchanged at 9.25% (30 September 2026)', 'https://www.bancomoc.mz/en/media/highlights/mimo-policy-rate-unchanged-at-9-25-30-09-26/', '2026-09-30', 'MIMO rate held at 9.25% since the cut from 9.50% on 28 January 2026; standing deposit facility 6.25%, lending facility 12.25% (Diário dos Mercados, July 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MZ', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":60,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'WageIndicator Mozambique, Segurança Social (Decree 51/2017)', 'https://wageindicator.org/pt-mz/trabalho-em-mocambique/lei-do-trabalho/seguranca-social', '2026-10-31', 'INSS compulsory scheme for employees (voluntary for the self-employed): pension from 60 (men) or 55 (women) after 240 months of contributions, floor 90% of the lowest minimum wage. No automatic indexation was found (pensioners were demanding adjustments in December 2025, AIM), so inflationLinked is false; tax treatment not found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MZ', 1, 'retirement_accumulation_return_base', 0.075, NULL, 'assumption', 'Safe mix about 7%; global equity base 9%; gold base 8%', 'https://bancomoc.mz/media/yardn043/di%C3%A1rio-dos-mercados-26-08-2026.pdf', '2026-10-31', 'Base case: Treasury securities and deposits with some foreign equity and gold.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MZ', 1, 'retirement_accumulation_return_high', 0.1, NULL, 'assumption', 'Safe mix about 7%; global equity base 9%; gold base 8%', 'https://bancomoc.mz/media/yardn043/di%C3%A1rio-dos-mercados-26-08-2026.pdf', '2026-10-31', 'High case: a growth-leaning mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MZ', 1, 'retirement_accumulation_return_low', 0.05, NULL, 'assumption', 'Safe mix about 7%; global equity base 9%; gold base 8%', 'https://bancomoc.mz/media/yardn043/di%C3%A1rio-dos-mercados-26-08-2026.pdf', '2026-10-31', 'Low case: mostly deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MZ', 1, 'retirement_age_default', 60, NULL, 'sourced', 'WageIndicator Mozambique, Segurança Social (Decree 51/2017, articles 29-35)', 'https://wageindicator.org/pt-mz/trabalho-em-mocambique/lei-do-trabalho/seguranca-social', '2026-10-31', 'INSS old-age pension at 60 for men and 55 for women with 240 months of contributions (or any age with 420 months); 50% reduced pension with 120 months; no change for later birth cohorts was found. Secondary source summarising Decree 51/2017.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MZ', 1, 'retirement_age_government', 65, NULL, 'sourced', 'AIM (Agência de Informação de Moçambique), parliament approves mandatory retirement at 65 in the civil service', 'https://aimnews.org/2026/04/29/parlamento-aprova-reforma-obrigatoria-aos-65-anos-na-funcao-publica/', '2026-04-29', 'Revision of the civil service statute (EGFAE) raising mandatory retirement from 60 to 65 for men and women, extendable to 70 for strategic careers (diplomats, lecturers, doctors, researchers); approved in general by parliament on 29 April 2026 per AIM. Final promulgation (reported as Law 10/2026) could not be confirmed from an official text. Secondary source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MZ', 1, 'retirement_return_base', 0.065, NULL, 'assumption', 'BdM: 1-year deposits 4.34% (May 2026), 91-day and 364-day bills about 12.2% (Aug 2026); 10% tax on deposit and bond interest (PwC)', 'https://bancomoc.mz/media/yardn043/di%C3%A1rio-dos-mercados-26-08-2026.pdf', '2026-10-31', 'Base case: a mix of deposits and Treasury bills after tax, kept well below the roughly 11% after-tax bill rate because bill rates are expected to fall.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MZ', 1, 'retirement_return_high', 0.09, NULL, 'assumption', 'BdM: 1-year deposits 4.34% (May 2026), 91-day and 364-day bills about 12.2% (Aug 2026); 10% tax on deposit and bond interest (PwC)', 'https://forbesafricalusofona.com/?p=178111', '2026-10-31', 'High case: mostly Treasury bills and bonds after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MZ', 1, 'retirement_return_low', 0.04, NULL, 'assumption', 'BdM: 1-year deposits 4.34% (May 2026), 91-day and 364-day bills about 12.2% (Aug 2026); 10% tax on deposit and bond interest (PwC)', 'https://www.bancomoc.mz/media/athimwmy/resumo-mensal-de-informa%C3%A7%C3%A3o-estat%C3%ADstica-junho2026.pdf', '2026-10-31', 'Low case: bank deposits after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MZ', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate for individuals was found; individuals can subscribe to Treasury bonds (Obrigações do Tesouro) through the stock exchange.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MZ', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Banco de Moçambique publishes only the 1-year deposit and loan rates on balances; no savings account rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MZ', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":19.4},{"year":2040,"value":20.4},{"year":2065,"value":12.2}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://data.worldbank.org/indicator/SP.POP.DPND.OL?locations=MZ', '2025-12-31', 'Working-age people per person 65+, computed as 100 / old-age dependency ratio: 5.15 in 2025 (World Bank) gives 19.4; 4.9 in 2040 and 8.2 in 2065 (populationpyramid.net/mozambique/2040/ and /2065/) give 20.4 and 12.2.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MZ', 1, 'tax_bank_interest', 0.1, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Mozambique, individual income determination', 'https://taxsummaries.pwc.com/mozambique/individual/income-determination', '2026-08-11', 'Interest from bank deposits and income from debt bonds is withheld at 10% (other capital income 20%); secondary source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MZ', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'There is no government savings certificate; income from debt bonds is withheld at 10% (PwC).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MZ', 1, 'tbill_91d_rate', 0.1215, NULL, 'sourced', 'Banco de Moçambique, Diário dos Mercados, 26 August 2026, type A Treasury bill auctions', 'https://bancomoc.mz/media/yardn043/di%C3%A1rio-dos-mercados-26-08-2026.pdf', '2026-08-26', '91-day weighted average 12.15% (182-day 12.22%, 364-day 12.15%); the latest daily bulletin that could be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MZ', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 10-year domestic Treasury bond issue or yield was found for 2025-2026; recent issues run 3 to 6 years.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('MZ', 1, 'tbond_5y_rate', 0.1325, NULL, 'sourced', 'Forbes Africa Lusófona (Lusa), Treasury bond exchange operations 2026', 'https://forbesafricalusofona.com/?p=178111', '2026-09-30', 'Secondary source: the latest Treasury bonds (OT 2026 series, maturing September 2032, about 6 years) carry a fixed 13.25% coupon, as did the 3-year OT-2026-S2 (April 2026); no exact 5-year yield was published.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('NA', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"NA","iso3":"NAM","nameEn":"Namibia","nameNative":"Namibia","region":"sub_saharan_africa","languages":["af","kj","ng","naq","en"],"currency":{"code":"NAD","symbol":"N$","decimals":2,"compact":"intl","usdRate":{"value":16.71,"status":"sourced","sourceName":"Federal Reserve H.10 (FRED DEXSFUS), South African rand per US dollar, 30 October 2026","sourceUrl":"https://fred.stlouisfed.org/series/DEXSFUS","asOf":"2026-10-30","note":"The Namibia dollar is pegged one to one to the South African rand; R16.7055 per dollar on 30 October 2026 (World Bank 2025 average 17.89). The Bank of Namibia daily rates page could not be read."}},"instruments":{"savings_account":{"available":true,"localName":null,"localNameEn":"Savings account"},"fdr_3m":{"available":true,"localName":null,"localNameEn":"Fixed deposit","note":"Banks offer fixed and notice deposits; the Bank of Namibia publishes only an overall average deposit rate."},"fdr_1y":{"available":true,"localName":null,"localNameEn":"Fixed deposit, 12 months"},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No standard monthly recurring deposit product was found."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate or retail savings bond for individuals was found."},"tbill_91d":{"available":true,"localName":null,"localNameEn":"Treasury bill","note":"91, 182, 273 and 364-day bills auctioned by the Bank of Namibia for the government; interest is tax-free for individuals.","sourceUrl":"https://www.bon.com.na/getattachment/f049b13a-3399-44e8-8284-1cd683606a4d/.aspx"},"tbond_5y":{"available":true,"localName":"Internal registered stock","localNameEn":"Government bond (internal registered stock)","note":"Fixed-rate GC bonds auctioned by the Bank of Namibia and listed on the Namibian Stock Exchange.","sourceUrl":"https://www.bon.com.na/CMSTemplates/Bon/Files/bon.com.na/c1/c1ed9c78-8610-492e-99ea-650bc925323b.pdf"},"tbond_10y":{"available":true,"localName":"Internal registered stock","localNameEn":"Government bond (internal registered stock)","note":"Lines maturing 2035, 2037, 2040 and later are on issue (GC35, GC37, GC40).","sourceUrl":"https://www.bon.com.na/CMSTemplates/Bon/Files/bon.com.na/ed/ed0a9410-ee67-4185-b96c-68a7ea79cec8.pdf"},"equity_fund":{"available":true,"localName":"Unit trust","localNameEn":"Unit trusts (collective investment schemes)","note":"Supervised by NAMFISA; interest earned in unit trusts carries the 10% withholding tax."},"gold":{"available":true,"localName":null,"localNameEn":"Gold","note":"Gold is mostly bought as jewellery or imported bullion coins."}},"institutions":{"centralBank":{"name":"Bank of Namibia","url":"https://www.bon.com.na/"},"insuranceRegulator":{"name":"Namibia Financial Institutions Supervisory Authority (NAMFISA)","url":"https://www.namfisa.com.na/"},"insuranceComplaints":{"name":"NAMFISA consumer complaints","url":"https://www.namfisa.com.na/consumer-complaints/"},"pensionScheme":null,"oldAgeAllowance":{"name":"Old Age Grant (Ministry of Gender Equality)","url":"https://mgecw.gov.na/old-age-grants-"},"publicHealthCover":{"name":"Ministry of Health and Social Services (public health facilities)","url":"https://mhss.gov.na/"},"depositInsurance":{"name":"Namibia Deposit Guarantee Authority (NDGA)","url":"https://www.ndga.com.na/"},"statistics":{"name":"Namibia Statistics Agency","url":"https://nsa.org.na/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NA', 1, 'bank_deposit_avg_rate', 0.0419, NULL, 'sourced', 'Bank of Namibia, Quarterly Bulletin June 2026, table II.9 selected interest rates (average deposit rate)', 'https://www.bon.com.na/getattachment/ddae85e6-f701-4c46-8ada-bacf584a1a2e/.aspx', '2026-03-31', 'Weighted average deposit rate of banks 4.19% at the end of March 2026 (4.16% in December 2025); later monthly figures were not found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NA', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap specific to credit cards or official typical credit card rate was found; the prime lending rate was 10.50% after the October 2026 repo increase.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NA', 1, 'deposit_insurance_limit', 50000, NULL, 'sourced', 'Government Gazette No. 8842, GN 13 of 2026: Regulations relating to maximum coverage limits for guaranteed deposits (Deposit Guarantee Act, 2018)', 'https://www.lac.org.na/laws/2026/8842.pdf', '2026-02-10', 'Maximum coverage N$50,000 per depositor per member institution, up from N$25,000 (GN 24 of 2020, repealed).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NA', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No monthly recurring deposit product or published rate was found in Bank of Namibia statistics.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NA', 1, 'equity_return_base', 0.1, NULL, 'assumption', 'Bank of Namibia, Quarterly Bulletin June 2026, table 3.3 NSX summary statistics; treasury bill auction results', 'https://www.bon.com.na/getattachment/ddae85e6-f701-4c46-8ada-bacf584a1a2e/.aspx', '2026-10-31', 'Base case: the NSX Local Index rose from about 511 (March 2022) to 819 (March 2026) but had a flat decade before that and the market is small and dominated by dual-listed South African shares, so equities are put about 3 points above the tax-free 1-year bill yield (7.6%), within the 4-point cap.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NA', 1, 'equity_return_high', 0.13, NULL, 'assumption', 'Bank of Namibia, Quarterly Bulletin June 2026, table 3.3 NSX summary statistics', 'https://www.bon.com.na/getattachment/ddae85e6-f701-4c46-8ada-bacf584a1a2e/.aspx', '2026-10-31', 'High case: a strong decade for local and dual-listed shares or a global index fund in Namibia dollar terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NA', 1, 'equity_return_low', 0.06, NULL, 'assumption', 'Bank of Namibia, Quarterly Bulletin June 2026, table 3.3 NSX summary statistics', 'https://www.bon.com.na/getattachment/ddae85e6-f701-4c46-8ada-bacf584a1a2e/.aspx', '2026-10-31', 'Low case: a weak decade for the local market, with returns near the tax-free treasury bill yield less a little.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NA', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No official 1-year fixed deposit rate could be read; an aggregator citing the Bank of Namibia lists about 4.15% for household 1-year term deposits in May 2026 but its page could not be loaded.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NA', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No official 3-month fixed deposit rate was found; the Bank of Namibia publishes only the weighted average deposit rate (4.19% in March 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NA', 1, 'fixed_income_return_base', 0.055, NULL, 'assumption', 'Bank of Namibia, Treasury bills auction results, 3 September 2026; PwC Tax Summaries (government interest exempt for individuals)', 'https://www.bon.com.na/getattachment/f049b13a-3399-44e8-8284-1cd683606a4d/.aspx', '2026-10-31', 'Base case: a mix of fixed deposits (about 3.8% after tax) and tax-free treasury bills (7.2-7.6%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NA', 1, 'fixed_income_return_high', 0.075, NULL, 'assumption', 'Bank of Namibia, Treasury bills auction results, 3 September 2026', 'https://www.bon.com.na/getattachment/f049b13a-3399-44e8-8284-1cd683606a4d/.aspx', '2026-10-31', 'High case: 12-month treasury bills (7.65%) or short government bonds, tax-free for individuals.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NA', 1, 'fixed_income_return_low', 0.035, NULL, 'assumption', 'Bank of Namibia, Quarterly Bulletin June 2026, table II.9 (average deposit rate 4.19%)', 'https://www.bon.com.na/getattachment/ddae85e6-f701-4c46-8ada-bacf584a1a2e/.aspx', '2026-10-31', 'Low case: bank deposits at about 4% less the 10% final withholding tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NA', 1, 'goal_inflation_education', 0.05, NULL, 'assumption', 'Bank of Namibia, Quarterly Bulletin June 2026, table I.16(a) national CPI by group (education)', 'https://www.bon.com.na/getattachment/ddae85e6-f701-4c46-8ada-bacf584a1a2e/.aspx', '2026-10-31', 'The education price index rose about 3.1% a year from 2020 to March 2026 (fees reset each January); private school fees are assumed to rise slightly faster than the 4.5% inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NA', 1, 'goal_inflation_health', 0.06, NULL, 'assumption', 'Bank of Namibia, Quarterly Bulletin June 2026, table I.16(a) national CPI by group (health)', 'https://www.bon.com.na/getattachment/ddae85e6-f701-4c46-8ada-bacf584a1a2e/.aspx', '2026-10-31', 'The health price index rose about 3.9% a year from 2020 to March 2026 and 5.3% in the year to September 2026, but private medical costs rise faster than the subsidised public part of the index, so 1.5 points above the 4.5% inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NA', 1, 'gold_return_base', 0.07, NULL, 'assumption', 'Federal Reserve H.10 rand per US dollar; World Bank official exchange rate history', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=NA', '2026-10-31', 'Base case: the long-run dollar gold trend of about 4% a year plus about 3% a year of rand (and Namibia dollar) depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NA', 1, 'gold_return_high', 0.11, NULL, 'assumption', 'Federal Reserve H.10 rand per US dollar', 'https://fred.stlouisfed.org/series/DEXSFUS', '2026-10-31', 'High case: strong gold years and a weaker rand.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NA', 1, 'gold_return_low', 0.02, NULL, 'assumption', 'Federal Reserve H.10 rand per US dollar (Namibia dollar at par)', 'https://fred.stlouisfed.org/series/DEXSFUS', '2026-10-31', 'Low case: flat dollar gold and a small depreciation of the rand-pegged Namibia dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NA', 1, 'gratuity_rule', NULL, '{"daysPerYear":7,"daysPerYearAfter":null,"afterYears":null,"daysPerMonth":30.33}', 'sourced', 'Labour Act 11 of 2007, section 35 (severance pay), Legal Assistance Centre annotated statute', 'https://www.lac.org.na/laws/annoSTAT/Labour%20Act%2011%20of%202007.pdf', '2008-11-01', 'At least one week''s remuneration per year of continuous service after 12 months, paid on dismissal (not for misconduct or poor performance), death, or resignation or retirement at 65; one week = 7/30.33 of a month. Law in force since 2008 (older than 2025, still current).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NA', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a major private hospital stay in Namibia was found from an official or international source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NA', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Private health cover is provided by medical aid funds, but no published contribution rates by age per 100,000 Namibia dollars of cover were found from a public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NA', 1, 'inflation_cpi', 0.054, NULL, 'sourced', 'Namibia Statistics Agency CPI, September 2026, via Trading Economics', 'https://tradingeconomics.com/namibia/inflation-cpi/news/590579', '2026-09-30', 'Secondary source: annual inflation 5.4% in September 2026 (5.0% in August), the highest in over two years, driven by transport; the NSA site shows 5.4% as its latest rate but its bulletin could not be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NA', 1, 'inflation_projection', 0.045, NULL, 'assumption', 'Bank of Namibia inflation projections (4.2% for 2026, 4.0% for 2027); NSA CPI averaged about 4.7% a year over 2021-2025', 'https://tradingeconomics.com/namibia/interest-rate/news/595772', '2026-10-31', 'The Namibia dollar is pegged to the rand and inflation averaged about 4.7% over 2021-2025, while the Bank of Namibia projects 4.2% for 2026 and 4.0% for 2027 (revised up in October 2026), so 4.5% is used for long-range plans.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NA', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life cover is sold, but no published premium rates per 1,000 Namibia dollars of cover by age were found from the regulator or another public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NA', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'NAMFISA (the insurance regulator) publishes no industry-wide life claim settlement ratio that could be found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NA', 1, 'life_expectancy', 67.516, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN), Namibia', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=NA', '2024-12-31', '67.5 years in 2024 (men 63.5, women 71.5); UN WPP 2024 gives 67.8 for 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NA', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":17.9,"men":15.7,"women":20},{"age":65,"total":14.9,"men":12.7,"women":16.6},{"age":70,"total":11.8,"men":10,"women":13.5},{"age":80,"total":7,"men":5.7,"women":8.2}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/namibia/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NA', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":60,"womenAge":60,"over90Monthly":null,"meansTested":false}', 'sourced', 'New Era, ''Old-age pension breathes life into Gibeon''; Ministry of Gender Equality old age grant page', 'https://neweralive.na/?p=384459', '2026-04-10', 'Paid to citizens and permanent residents aged 60 and older living in Namibia, without a means test (non-contributory); the ministry page could not be loaded (certificate error).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NA', 1, 'old_age_allowance_monthly', 1700, NULL, 'sourced', 'New Era, ''Old-age pension breathes life into Gibeon'' (2026/27 Budget)', 'https://neweralive.na/?p=384459', '2026-04-01', 'The universal old-age grant was raised by N$100 to N$1,700 a month in the 2026/27 financial year (from April 2026), per New Era, 10 April 2026 (the same article also repeats the earlier N$1,600 level, which applied from April 2024).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NA', 1, 'oop_health_share', 0.0749, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), Namibia', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=NA', '2023-12-31', '7.5% in 2023 (WHO Global Health Expenditure Database); older than 2025, the latest available.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NA', 1, 'policy_rate', 0.07, NULL, 'sourced', 'Bank of Namibia Monetary Policy Committee, October 2026 decision, via Trading Economics', 'https://tradingeconomics.com/namibia/interest-rate/news/595772', '2026-10-28', 'Repo rate raised 25 basis points to 7.00% at the October 2026 meeting (6.75% since June 2026; 6.75% also shown for Q1 2026 in the Bank of Namibia Quarterly Bulletin June 2026). Secondary source; the October statement itself was not read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NA', 1, 'public_pension_scheme', NULL, NULL, 'missing', '', '', '2026-10-31', 'Namibia has no public contributory old-age pension: the National Pension Fund planned under the Social Security Act has still not been implemented (The Brief and New Era, 2026; ILO actuarial review call); the Social Security Commission covers maternity, sick leave and death benefits only, and civil servants have their own fund (GIPF).', 1);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NA', 1, 'retirement_accumulation_return_base', 0.08, NULL, 'assumption', 'Bank of Namibia, Quarterly Bulletin June 2026; equity base 10%; gold base 7%', 'https://www.bon.com.na/getattachment/ddae85e6-f701-4c46-8ada-bacf584a1a2e/.aspx', '2026-10-31', 'Base case: a balanced mix of government bonds (9-10%), equity (local and global) unit trusts and some gold.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NA', 1, 'retirement_accumulation_return_high', 0.1, NULL, 'assumption', 'Bank of Namibia, Quarterly Bulletin June 2026; equity high 13%', 'https://www.bon.com.na/getattachment/ddae85e6-f701-4c46-8ada-bacf584a1a2e/.aspx', '2026-10-31', 'High case: a growth-leaning mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NA', 1, 'retirement_accumulation_return_low', 0.05, NULL, 'assumption', 'Bank of Namibia, Quarterly Bulletin June 2026', 'https://www.bon.com.na/getattachment/ddae85e6-f701-4c46-8ada-bacf584a1a2e/.aspx', '2026-10-31', 'Low case: a cautious mix earning a little above after-tax deposit rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NA', 1, 'retirement_age_default', NULL, NULL, 'missing', '', '', '2026-10-31', 'Namibia has no statutory retirement or pension age for private-sector workers: the Labour Act sets none and employers choose (often 60 or 65), per The Namibian, 28 July 2025; there is no public contributory pension.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NA', 1, 'retirement_age_government', 60, NULL, 'sourced', 'The Namibian, ''Labour Act silent on retirement age'' (Public Service Act 1995)', 'https://www.namibian.com.na/labour-actsilent-on-retirement-age', '2025-07-28', 'Public servants retire at 60 under the Public Service Act 1995; early retirement from 55 with approval. Secondary source (the Act on NamibLII could not be loaded); older than 2025 rule still current.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NA', 1, 'retirement_return_base', 0.055, NULL, 'assumption', 'Bank of Namibia, Treasury bills auction results, 3 September 2026; PwC Tax Summaries', 'https://www.bon.com.na/getattachment/f049b13a-3399-44e8-8284-1cd683606a4d/.aspx', '2026-10-31', 'Base case: a mix of fixed deposits and tax-free treasury bills, below the 1-year bill yield of 7.65% (tax-free for individuals).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NA', 1, 'retirement_return_high', 0.07, NULL, 'assumption', 'Bank of Namibia, Treasury bills auction results, 3 September 2026', 'https://www.bon.com.na/getattachment/f049b13a-3399-44e8-8284-1cd683606a4d/.aspx', '2026-10-31', 'High case: most of the money in treasury bills and short government bonds, tax-free for individuals.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NA', 1, 'retirement_return_low', 0.035, NULL, 'assumption', 'Bank of Namibia, Quarterly Bulletin June 2026, table II.9 (average deposit rate)', 'https://www.bon.com.na/getattachment/ddae85e6-f701-4c46-8ada-bacf584a1a2e/.aspx', '2026-10-31', 'Low case: bank deposits after the 10% withholding tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NA', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate or retail savings bond for individuals was found; government bonds and treasury bills are sold by Bank of Namibia auction.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NA', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Bank of Namibia publishes only the weighted average deposit rate (4.19% in March 2026); no official savings-account rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NA', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":15.7},{"year":2040,"value":12.05},{"year":2065,"value":6.21}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/namibia/2040/', '2025-12-31', 'Working-age people per person aged 65+ = 100 / old-age dependency ratio: ratio 6.37 in 2025 (World Bank) gives 15.7; 8.3 in 2040 (populationpyramid.net/namibia/2040/) gives 12.05; 16.1 in 2065 (populationpyramid.net/namibia/2065/) gives 6.21.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NA', 1, 'tax_bank_interest', 0.1, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Namibia, individual taxes on personal income (withholding taxes)', 'https://taxsummaries.pwc.com/republic-of-namibia/individual/taxes-on-personal-income', '2026-07-16', '10% withholding tax on gross interest from a Namibian bank or unit trust paid to anyone other than a Namibian company; it is a final tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NA', 1, 'tax_sanchayapatra_profit', 0, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Namibia, individual income determination (interest income)', 'https://taxsummaries.pwc.com/republic-of-namibia/individual/income-determination', '2026-07-16', 'There is no savings certificate, but interest on stock or securities issued by the government, including treasury bills, is exempt for natural persons.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NA', 1, 'tbill_91d_rate', 0.0716, NULL, 'sourced', 'Bank of Namibia, Treasury bills auction results, 3 September 2026 (91-day bill maturing 4 December 2026)', 'https://www.bon.com.na/getattachment/f049b13a-3399-44e8-8284-1cd683606a4d/.aspx', '2026-09-03', 'Weighted average yield 7.163% on the 91-day bill; the 364-day bill averaged 7.649% at the same auction. Later results were not found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NA', 1, 'tbond_10y_rate', 0.1022, NULL, 'sourced', 'Bank of Namibia, Quarterly Bulletin June 2026, table III.2(a) internal registered stock auctions (GC35, maturing 15 July 2035)', 'https://www.bon.com.na/getattachment/ddae85e6-f701-4c46-8ada-bacf584a1a2e/.aspx', '2026-03-31', 'Weighted yield to maturity 10.22% at the second March 2026 auction of the 9.50% GC35 (about 9.3 years); the bulletin''s average 10-year government bond yield was 10.08% in the first quarter of 2026. Later bond auction results were not found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NA', 1, 'tbond_5y_rate', 0.0946, NULL, 'sourced', 'Bank of Namibia, Quarterly Bulletin June 2026, table III.2(a) internal registered stock auctions (GC32, maturing 15 April 2032)', 'https://www.bon.com.na/getattachment/ddae85e6-f701-4c46-8ada-bacf584a1a2e/.aspx', '2026-03-31', 'Weighted yield to maturity 9.46% at a March 2026 auction of the 9.00% GC32 (about 6 years to maturity); later bond auction results were not found.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('NE', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"NE","iso3":"NER","nameEn":"Niger","nameNative":"Nijar","region":"sub_saharan_africa","languages":["ha","fr","dje","ff","tmh"],"currency":{"code":"XOF","symbol":"F CFA","decimals":0,"compact":"intl","usdRate":{"value":581.93,"status":"sourced","sourceName":"World Bank WDI, official exchange rate (PA.NUS.FCRF), Niger","sourceUrl":"https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=NE","asOf":"2025-12-31","note":"581.9 CFA francs per US dollar, 2025 average; the CFA franc is pegged at 655.957 per euro. The BCEAO transfer rates page showed 582.50 buying and 589.50 selling on 2 November 2026 (mid 586.0); its 30 October rates could no longer be read."}},"instruments":{"savings_account":{"available":true,"localName":"Compte d''épargne","localNameEn":"Savings account"},"fdr_3m":{"available":true,"localName":"Dépôt à terme","localNameEn":"Term deposit (DAT)","note":"Banks declare minimum and maximum term-deposit rates to the BCEAO twice a year.","sourceUrl":"https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf"},"fdr_1y":{"available":true,"localName":"Dépôt à terme","localNameEn":"Term deposit (DAT), 1 year","note":"Banks declare minimum and maximum term-deposit rates to the BCEAO twice a year.","sourceUrl":"https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf"},"dps":{"available":true,"localName":"Épargne contractuelle","localNameEn":"Contractual savings plan","note":"Monthly savings plans offered by banks.","sourceUrl":"https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf"},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate for individuals was found."},"tbill_91d":{"available":false,"localName":null,"localNameEn":null,"note":"Niger''s Treasury issued only 12-month bills (bons assimilables du Trésor) on the regional market in 2026.","sourceUrl":"https://www.umoatitres.org/fr/pays/niger/"},"tbond_5y":{"available":true,"localName":"Obligations assimilables du Trésor","localNameEn":"Treasury bonds (OAT)","note":"Auctioned by UMOA-Titres in 2 to 5-year lines; individuals buy through banks or licensed brokers (SGI).","sourceUrl":"https://www.umoatitres.org/fr/emission/emission-simultanee-dobligations-du-tresor-du-niger-du-01-10-2026/"},"tbond_10y":{"available":false,"localName":null,"localNameEn":null,"note":"No bond longer than 5 years was issued in 2026.","sourceUrl":"https://www.umoatitres.org/fr/pays/niger/"},"equity_fund":{"available":true,"localName":"OPCVM (FCP, SICAV)","localNameEn":"Collective investment funds","note":"Supervised by the regional financial market authority (AMF-UMOA); funds invest on the regional exchange (BRVM)."},"gold":{"available":true,"localName":"Zinariya","localNameEn":"Gold","note":"Niger produces gold; savers mainly buy it as jewellery."}},"institutions":{"centralBank":{"name":"Banque Centrale des États de l''Afrique de l''Ouest (BCEAO)","url":"https://www.bceao.int/"},"insuranceRegulator":{"name":"Commission Régionale de Contrôle des Assurances (CIMA)","url":"https://cima-afrique.org/","note":"Regional insurance regulator for the CIMA member states; national supervision sits with the Ministry of Finance."},"insuranceComplaints":null,"pensionScheme":{"name":"Caisse Nationale de Sécurité Sociale (CNSS), old-age pension","url":"https://www.cnss.ne/"},"oldAgeAllowance":null,"publicHealthCover":null,"depositInsurance":{"name":"Fonds de Garantie des Dépôts et de Résolution dans l''UMOA (FGDR-UMOA)","url":"https://www.fgd-umoa.org/a-propos/missions/"},"statistics":{"name":"Institut National de la Statistique (INS)","url":"https://www.stat-niger.org/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NE', 1, 'bank_deposit_avg_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No Niger-level average deposit rate was found: the BCEAO note gives only the UMOA average (5.15% in July 2026, Niger down 0.32 points in the month), and the World Bank''s last Niger figure is 6.9% for 2016.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NE', 1, 'credit_card_rate_cap', 0.125, NULL, 'sourced', 'BCEAO, banking conditions of UMOA credit institutions, first half 2026 (Niger), conditions débitrices (taux débiteur maximum)', 'https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf', '2026-06-30', 'Median maximum lending rate declared by 13 Niger banks for the first half of 2026 (range 9-14%); it applies to all bank credit, including cards. No card-specific rate is published.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NE', 1, 'deposit_insurance_limit', 1400000, NULL, 'sourced', 'UMOA Council of Ministers, Decision of 30 June 2017 on FGDR-UMOA contribution rates and compensation ceilings (Article 2)', 'https://www.fgd-umoa.org/wp-content/uploads/2024/10/Decision-du-CM-relative-aux-taux-de-contribution-et-aux-plafonds-d-indemnistation-2-1.pdf', '2017-06-30', 'Deposits are guaranteed up to 1,400,000 FCFA per depositor per bank (300,000 FCFA at a microfinance institution) by the regional deposit guarantee fund; decision from 2017 (older than 2025), still the one the fund publishes.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NE', 1, 'dps_rate', 0.035, NULL, 'sourced', 'BCEAO, banking conditions of UMOA credit institutions, first half 2026 (Niger), conditions créditrices (épargne contractuelle)', 'https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf', '2026-06-30', 'Median rate on contractual savings plans declared by 14 Niger banks for the first half of 2026; most declare 3.50% (range 2.7-5.0%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NE', 1, 'equity_return_base', 0.075, NULL, 'assumption', 'BCEAO, monthly economic note for UMOA countries, September 2026; BCEAO, banking conditions of UMOA credit institutions, first half 2026 (Niger)', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-10-31', 'Base case: about 1.5 points above after-tax large term deposits (median maximum 6.5% less 10% tax, about 5.9%), within the 4-point cap; the BRVM rose strongly in 2023-2026 but its 10-year record is uneven.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NE', 1, 'equity_return_high', 0.12, NULL, 'assumption', 'BCEAO, monthly economic note for UMOA countries, September 2026 (BRVM indices)', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-10-31', 'High case: the BRVM repeats a strong decade like 2023-2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NE', 1, 'equity_return_low', 0.04, NULL, 'assumption', 'BCEAO, monthly economic note for UMOA countries, September 2026 (regional stock exchange BRVM, deposit rates)', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-10-31', 'Low case: regional (BRVM) equities, where Niger investors buy shares, return about the bank deposit rate, as in their weak 2016-2020 years.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NE', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The BCEAO publishes only each bank''s minimum and maximum term-deposit rates (Niger medians 3.75% and 6.5%, first half 2026), not a 1-year rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NE', 1, 'fdr_3m_rate', 0.0375, NULL, 'sourced', 'BCEAO, banking conditions of UMOA credit institutions, first half 2026 (Niger), conditions créditrices', 'https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf', '2026-06-30', 'Median of the minimum term-deposit rates (taux DAT minimum) declared by 13 Niger banks, range 2.0-4.5%; the minimum usually applies to small, short deposits. Not a tenor-specific average.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NE', 1, 'fixed_income_return_base', 0.045, NULL, 'assumption', 'BCEAO, banking conditions of UMOA credit institutions, first half 2026 (Niger); UMOA-Titres, Niger Treasury auction of 1 October 2026', 'https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf', '2026-10-31', 'Base case: larger term deposits (median maximum 6.5%) less 10% tax, rounded down for the minimum amounts that the higher rates require.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NE', 1, 'fixed_income_return_high', 0.065, NULL, 'assumption', 'UMOA-Titres, Niger Treasury auction of 1 October 2026 (12-month bill 8.70%, 5-year bond 8.62%)', 'https://www.umoatitres.org/fr/emission/emission-simultanee-dobligations-du-tresor-du-niger-du-01-10-2026/', '2026-10-31', 'High case: Niger Treasury bills and bonds at 8.6-8.7%, discounted for a possible tax and for payment delays after the 2024 sanctions period.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NE', 1, 'fixed_income_return_low', 0.03, NULL, 'assumption', 'BCEAO, banking conditions of UMOA credit institutions, first half 2026 (Niger), conditions créditrices', 'https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf', '2026-10-31', 'Low case: small term deposits or contractual savings at 3.5-3.75% less the 10% tax on bank interest.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NE', 1, 'goal_inflation_education', 0.045, NULL, 'assumption', 'BCEAO, monthly economic note for UMOA countries, September 2026; inflation assumption 2.5%', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-10-31', 'No national education CPI series was read; private school fees usually rise faster than general prices, so 2 points above the 2.5% inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NE', 1, 'goal_inflation_health', 0.04, NULL, 'assumption', 'BCEAO, monthly economic note for UMOA countries, September 2026; inflation assumption 2.5%', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-10-31', 'No national medical CPI series was read; private medical costs usually rise faster than general prices, so 1.5 points above the 2.5% inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NE', 1, 'gold_return_base', 0.045, NULL, 'assumption', 'BCEAO exchange rates (CFA franc pegged at 655.957 per euro)', 'https://www.bceao.int/fr/cours/cours-des-devises-contre-Franc-CFA-appliquer-aux-transferts', '2026-10-31', 'Base case: the long-run dollar gold trend of about 4% a year plus a small allowance for the euro-pegged franc weakening against the dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NE', 1, 'gold_return_high', 0.08, NULL, 'assumption', 'BCEAO exchange rates', 'https://www.bceao.int/fr/cours/cours-des-devises-contre-Franc-CFA-appliquer-aux-transferts', '2026-10-31', 'High case: strong gold years such as 2024-2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NE', 1, 'gold_return_low', 0, NULL, 'assumption', 'BCEAO exchange rates (CFA franc pegged to the euro)', 'https://www.bceao.int/fr/cours/cours-des-devises-contre-Franc-CFA-appliquer-aux-transferts', '2026-10-31', 'Low case: flat gold in euro terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NE', 1, 'gratuity_rule', NULL, '{"daysPerYear":6,"daysPerYearAfter":9.5,"afterYears":10,"daysPerMonth":30}', 'sourced', 'WageIndicator, Niger interprofessional collective agreement of 15 December 1972, article 34 (retirement indemnity)', 'https://wageindicator.org/fr-ne/travail-au-niger/convention-collective/niger---convention-collective-interprofessionnelle', '2026-04-20', 'On retirement the worker gets a retirement indemnity on the severance basis: average monthly pay of the last 12 months x 20% per year for years 1-5, 30% for years 6-10 and 35% beyond 10 (6, 9 and 10.5 days a year). Approximated as 6 days a year, 9.5 for all years once service exceeds 10, which matches the agreement at 30 years of service.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NE', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a major private hospital stay in Niger was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NE', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premiums by age per 100,000 FCFA of cover were found from a public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NE', 1, 'inflation_cpi', -0.01, NULL, 'sourced', 'BCEAO, monthly economic note for UMOA countries, September 2026 (harmonised consumer prices, August 2026)', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-08-31', 'Consumer prices fell 1.0% year on year in Niger in August 2026 after -2.0% in July (INS data via BCEAO); prices fell 4.5% on average in 2025 (World Bank) after a 9.1% jump in 2024.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NE', 1, 'inflation_projection', 0.025, NULL, 'assumption', 'BCEAO inflation target (1-3% band, centre 2%); Niger CPI averaged about 3.3% a year over 2021-2025 with large swings', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-10-31', 'The CFA franc is pegged to the euro and the BCEAO targets 1-3%, but Niger''s food-driven inflation swings widely (9.1% in 2024, -4.5% in 2025), so 2.5% is used for long-range plans.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NE', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Life insurers operate under the CIMA code, but no published term-life premium rates per 1,000 FCFA of cover by age were found from a public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NE', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No industry-wide life claim settlement ratio for Niger was found from CIMA or the Ministry of Finance.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NE', 1, 'life_expectancy', 61.433, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN), Niger', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=NE', '2024-12-31', '61.4 years in 2024 (men 60.5, women 62.4); UN WPP 2024 gives 61.9 for 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NE', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":16.6,"men":16,"women":17.1},{"age":65,"total":13,"men":12.6,"women":13.4},{"age":70,"total":9.8,"men":9.5,"women":10.1},{"age":80,"total":5,"men":4.8,"women":5.1}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/niger/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NE', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension for Niger was found (CLEISS describes only contributory CNSS benefits).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NE', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension for Niger was found; the CNSS ''allocation de vieillesse'' is a contributory lump sum for insured people with 12-179 months of contributions (CLEISS).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NE', 1, 'oop_health_share', 0.5148, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), Niger', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=NE', '2023-12-31', '51.5% in 2023 (WHO Global Health Expenditure Database); older than 2025, the latest available.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NE', 1, 'policy_rate', 0.03, NULL, 'sourced', 'BCEAO, monthly economic note for UMOA countries, September 2026 (Monetary Policy Committee of 9 September 2026)', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-09-09', 'Main policy rate (refinancing rate) 3.00%, held on 9 September 2026; the marginal lending facility rate is 5.00%. Common to all eight UMOA countries.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NE', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":60,"inflationLinked":false,"taxFree":null}', 'sourced', 'CLEISS, Niger social security regime (CNSS old-age pension)', 'https://www.cleiss.fr/docs/regimes/regime_niger.html', '2024-01-01', 'Compulsory CNSS pension for private employees from 60 after at least 180 months of contributions: since 2012, 20% of capped average pay plus 1.33% per year beyond 15 years, at least 60% of the minimum wage and at most 80% of pay; earnings capped at 500,000 FCFA a month. No indexation rule was found, so inflationLinked is false. Page dated 2024 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NE', 1, 'retirement_accumulation_return_base', 0.06, NULL, 'assumption', 'UMOA-Titres, Niger Treasury auction of 1 October 2026; equity base 7.5%; gold base 4.5%', 'https://www.umoatitres.org/fr/emission/emission-simultanee-dobligations-du-tresor-du-niger-du-01-10-2026/', '2026-10-31', 'Base case: a balanced mix of deposits or Treasury bonds, regional equity funds and some gold.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NE', 1, 'retirement_accumulation_return_high', 0.08, NULL, 'assumption', 'UMOA-Titres, Niger Treasury auction of 1 October 2026; equity high 12%', 'https://www.umoatitres.org/fr/emission/emission-simultanee-dobligations-du-tresor-du-niger-du-01-10-2026/', '2026-10-31', 'High case: a growth-leaning mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NE', 1, 'retirement_accumulation_return_low', 0.035, NULL, 'assumption', 'BCEAO, banking conditions of UMOA credit institutions, first half 2026 (Niger)', 'https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf', '2026-10-31', 'Low case: a mix earning about after-tax deposit rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NE', 1, 'retirement_age_default', 60, NULL, 'sourced', 'WageIndicator, Niger social security (Decree 67-25 of 2 February 1967); CLEISS, Niger social security regime', 'https://wageindicator.org/fr-ne/travail-au-niger/droit-du-travail/securite-sociale', '2026-04-20', 'Secondary sources: CNSS old-age pension at 60 for men and women with at least 180 months of contributions (CLEISS 2024), early at 55 for working women or workers unfit for work. No newer rule for people born after 1975 was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NE', 1, 'retirement_age_government', 62, NULL, 'sourced', 'Le360 Afrique, ''Niger: l''âge de la retraite des fonctionnaires passe à 62 ans'' (new general civil service statute)', 'https://afrique.le360.ma/societe/niger-lage-de-la-retraite-des-fonctionnaires-passe-a-62-ans-les-jeunes-deplorent_W4X5WAWCVFCVVOIELBRMB76QEU/', '2023-05-18', 'The new general statute of the civil service raised the retirement age from 60 to 62 (May 2023, older than 2025); a January 2026 Council of Ministers decree extends 62 to auxiliary staff (APA, not read).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NE', 1, 'retirement_return_base', 0.04, NULL, 'assumption', 'BCEAO, banking conditions of UMOA credit institutions, first half 2026 (Niger), conditions créditrices', 'https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf', '2026-10-31', 'Base case: below after-tax large term deposits (about 5.9%) and the 1-year bill yield (8.7%), allowing for smaller balances and sovereign payment risk; not above the safe rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NE', 1, 'retirement_return_high', 0.055, NULL, 'assumption', 'UMOA-Titres, Niger Treasury auction of 1 October 2026', 'https://www.umoatitres.org/fr/emission/emission-simultanee-dobligations-du-tresor-du-niger-du-01-10-2026/', '2026-10-31', 'High case: part of the money in larger term deposits or Treasury bonds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NE', 1, 'retirement_return_low', 0.03, NULL, 'assumption', 'BCEAO, banking conditions of UMOA credit institutions, first half 2026 (Niger), conditions créditrices', 'https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf', '2026-10-31', 'Low case: small term deposits or contractual savings less the 10% tax on bank interest.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NE', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate sold to individuals was found; the Treasury borrows through UMOA-Titres auctions of 1-year bills and 2-5 year bonds, open to individuals through banks and licensed brokers (SGI).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NE', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No savings-account (livret) rate for Niger banks was found in BCEAO publications; banks declare term-deposit and contractual-savings rates only.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NE', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":19.54},{"year":2040,"value":19.23},{"year":2065,"value":13.16}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/niger/2040/', '2025-12-31', 'Working-age people per person aged 65+ = 100 / old-age dependency ratio: ratio 5.12 in 2025 (World Bank) gives 19.54; 5.2 in 2040 gives 19.23; 7.6 in 2065 (populationpyramid.net/niger/2065/) gives 13.16.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NE', 1, 'tax_bank_interest', 0.1, NULL, 'sourced', 'Niger General Tax Code, article 80 (tax on income from claims, deposits and guarantees), eRegulations Niger', 'https://niger.eregulations.org/media/code%20g%C3%A9n%C3%A9rale%20des%20imp%C3%B4ts.pdf', '2012-08-27', '10% on interest from deposit and current accounts at banks (20% on other claims). The code version read is dated 2012 (older than 2025); later finance laws were not checked for changes to this rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NE', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate exists; the tax treatment of Treasury securities for individuals is set in each auction notice and was not confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NE', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Niger''s Treasury issued only 12-month bills on the regional market in 2026 (last: 8.70% average yield on 1 October 2026); no 3-month bill rate exists.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NE', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No Niger Treasury bond longer than 5 years was issued on the regional market in 2026 (UMOA-Titres Niger issue list).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NE', 1, 'tbond_5y_rate', 0.0862, NULL, 'sourced', 'UMOA-Titres, Niger Treasury auction of 1 October 2026 (bond maturing 3 July 2031)', 'https://www.umoatitres.org/fr/emission/emission-simultanee-dobligations-du-tresor-du-niger-du-01-10-2026/', '2026-10-01', 'Weighted average yield 8.62% on the 6.50% bond maturing 3 July 2031 (57 months); the 12-month bill in the same auction yielded 8.70%.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('NG', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"NG","iso3":"NGA","nameEn":"Nigeria","nameNative":"Najeriya","region":"sub_saharan_africa","languages":["ha","en","pcm","yo","ig"],"currency":{"code":"NGN","symbol":"₦","decimals":2,"compact":"intl","usdRate":{"value":1345.76,"status":"sourced","sourceName":"Central Bank of Nigeria, exchange rates by currency (US dollar central rate), 30 October 2026","sourceUrl":"https://www.cbn.gov.ng/rates/ExchRateByCurrency.html","asOf":"2026-10-30","note":"Central rate N1,345.7565 per US dollar (buying 1,345.2565, selling 1,346.2565); World Bank 2025 average 1,518.4."}},"instruments":{"savings_account":{"available":true,"localName":null,"localNameEn":"Savings account","sourceUrl":"https://www.cbn.gov.ng/rates/mnymktind.html"},"fdr_3m":{"available":true,"localName":null,"localNameEn":"Fixed (term) deposit, 3 months","sourceUrl":"https://www.cbn.gov.ng/rates/mnymktind.html"},"fdr_1y":{"available":true,"localName":null,"localNameEn":"Fixed (term) deposit, 12 months","sourceUrl":"https://www.cbn.gov.ng/rates/mnymktind.html"},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No standard monthly recurring deposit product with a published rate was found."},"sanchayapatra_5y":{"available":true,"localName":"FGN Savings Bond","localNameEn":"Federal Government of Nigeria Savings Bond","note":"Retail bond offered monthly by the Debt Management Office from N5,000 (maximum N50 million), in 2 and 3-year tenors with quarterly interest; sold through appointed distribution agents.","sourceUrl":"https://www.dmo.gov.ng/6092-fgn-savings-bond-offer-for-subscription-october-2026/file"},"tbill_91d":{"available":true,"localName":"Nigerian Treasury Bill","localNameEn":"Nigerian Treasury Bill (NTB)","note":"91, 182 and 364-day bills auctioned by the Central Bank of Nigeria; individuals buy through banks and brokers.","sourceUrl":"https://www.cbn.gov.ng/rates/govtsecurities.html"},"tbond_5y":{"available":true,"localName":"FGN Bond","localNameEn":"Federal Government of Nigeria bond","note":"Bonds of several maturities trade on the secondary market; 2026 auctions offered 2034-2038 maturities only.","sourceUrl":"https://www.dmo.gov.ng/fgn-bonds/auction"},"tbond_10y":{"available":true,"localName":"FGN Bond","localNameEn":"Federal Government of Nigeria bond","note":"Auctioned monthly by the Debt Management Office (FGN SEP 2036 reopened in October 2026).","sourceUrl":"https://www.dmo.gov.ng/6122-summary-of-fgn-bond-auction-results-for-october-2026/file"},"equity_fund":{"available":true,"localName":null,"localNameEn":"Mutual funds (collective investment schemes)","note":"Registered with the Securities and Exchange Commission; equity and index funds invest on the Nigerian Exchange."},"gold":{"available":true,"localName":null,"localNameEn":"Gold","note":"Gold is mainly bought as jewellery; bullion bars and coins are uncommon for retail savers."}},"institutions":{"centralBank":{"name":"Central Bank of Nigeria","url":"https://www.cbn.gov.ng/"},"insuranceRegulator":{"name":"National Insurance Commission (NAICOM)","url":"https://naicom.gov.ng/"},"insuranceComplaints":{"name":"NAICOM complaints portal","url":"https://complaints.naicom.gov.ng/"},"pensionScheme":{"name":"Contributory Pension Scheme (National Pension Commission, PenCom)","url":"https://www.pencom.gov.ng/"},"oldAgeAllowance":null,"publicHealthCover":{"name":"National Health Insurance Authority (NHIA)","url":"https://www.nhia.gov.ng/"},"depositInsurance":{"name":"Nigeria Deposit Insurance Corporation (NDIC)","url":"https://ndic.gov.ng/"},"statistics":{"name":"National Bureau of Statistics","url":"https://nigerianstat.gov.ng/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NG', 1, 'bank_deposit_avg_rate', 0.1127, NULL, 'sourced', 'World Bank WDI, deposit interest rate (FR.INR.DPST), Nigeria', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=NG', '2025-12-31', '11.27% average for 2025; CBN monthly averages by term in September 2026 were 5.36% (savings) to 12.20% (1 month).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NG', 1, 'credit_card_rate_cap', 0.3262, NULL, 'sourced', 'Central Bank of Nigeria, money market indicators, September 2026 (maximum lending rate)', 'https://www.cbn.gov.ng/rates/mnymktind.html', '2026-09-30', 'Average maximum lending rate of banks 32.62% in September 2026 (prime lending 19.04%); no card-specific cap or rate is published.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NG', 1, 'deposit_insurance_limit', 5000000, NULL, 'sourced', 'Nigeria Deposit Insurance Corporation, frequently asked questions (insured limits)', 'https://ndic.gov.ng/faq/', '2026-10-31', 'Current insured limits: N5,000,000 per depositor in deposit money banks (including non-interest banks) and primary mortgage banks, N2,000,000 in microfinance banks; the same N5,000,000 applies per subscriber per bank under pass-through cover. The page is undated, so asOf is the research date.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NG', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No monthly recurring deposit product with a published rate was found in Central Bank of Nigeria statistics.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NG', 1, 'equity_return_base', 0.16, NULL, 'assumption', 'Central Bank of Nigeria, money market indicators, September 2026; CBN treasury bill auctions (91-day 15.40%, 364-day 15.80% discount)', 'https://www.cbn.gov.ng/rates/govtsecurities.html', '2026-10-31', 'Base case: about 2 points above the 14% inflation assumption and below the tax-exempt treasury bill yield (16-19%), well within the 4-point cap; the 10-year index record was not read and the market swings with the naira.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NG', 1, 'equity_return_high', 0.22, NULL, 'assumption', 'Central Bank of Nigeria, money market indicators, September 2026', 'https://www.cbn.gov.ng/rates/mnymktind.html', '2026-10-31', 'High case: a strong decade for Nigerian shares in naira terms, as in 2023-2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NG', 1, 'equity_return_low', 0.1, NULL, 'assumption', 'Central Bank of Nigeria, money market indicators, September 2026; NGN per US dollar (CBN)', 'https://www.cbn.gov.ng/rates/mnymktind.html', '2026-10-31', 'Low case: Nigerian shares lag inflation, as they did in naira-weak years, returning about the after-tax deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NG', 1, 'fdr_1y_rate', 0.105, NULL, 'sourced', 'Central Bank of Nigeria, money market indicators, September 2026 (12-month deposit rate)', 'https://www.cbn.gov.ng/rates/mnymktind.html', '2026-09-30', 'Average 12-month deposit rate 10.50% in September 2026 (10.30% in August).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NG', 1, 'fdr_3m_rate', 0.1033, NULL, 'sourced', 'Central Bank of Nigeria, money market indicators, September 2026 (3-month deposit rate)', 'https://www.cbn.gov.ng/rates/mnymktind.html', '2026-09-30', 'Average 3-month deposit rate 10.33% in September 2026 (10.34% in August).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NG', 1, 'fixed_income_return_base', 0.12, NULL, 'assumption', 'Central Bank of Nigeria, money market indicators, September 2026; DMO FGN Savings Bond offer, October 2026 (14.071%)', 'https://www.dmo.gov.ng/6092-fgn-savings-bond-offer-for-subscription-october-2026/file', '2026-10-31', 'Base case: a mix of term deposits (about 9.5% after tax), FGN Savings Bonds (13-14%) and treasury bills (16-19% yield).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NG', 1, 'fixed_income_return_high', 0.16, NULL, 'assumption', 'CBN treasury bill auction of 28 October 2026; DMO October 2026 bond auction', 'https://www.cbn.gov.ng/rates/govtsecurities.html', '2026-10-31', 'High case: treasury bills and FGN bonds at 16-17% less possible tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NG', 1, 'fixed_income_return_low', 0.09, NULL, 'assumption', 'Central Bank of Nigeria, money market indicators, September 2026 (12-month deposit 10.50%)', 'https://www.cbn.gov.ng/rates/mnymktind.html', '2026-10-31', 'Low case: 12-month deposits at about 10.5% less 10% withholding tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NG', 1, 'goal_inflation_education', 0.15, NULL, 'assumption', 'NBS CPI via Voice of Nigeria; inflation assumption 14%', 'https://von.gov.ng/nigerias-headline-inflation-drops-to-14-63-per-cent/', '2026-10-31', 'No national education CPI figure was read; private school fees usually rise faster than general prices, so 1 point above the 14% inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NG', 1, 'goal_inflation_health', 0.155, NULL, 'assumption', 'NBS CPI via Voice of Nigeria; inflation assumption 14%', 'https://von.gov.ng/nigerias-headline-inflation-drops-to-14-63-per-cent/', '2026-10-31', 'No national health CPI figure was read; imported drugs and equipment follow the naira, so 1.5 points above the 14% inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NG', 1, 'gold_return_base', 0.13, NULL, 'assumption', 'Central Bank of Nigeria exchange rates; World Bank official exchange rate history', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=NG', '2026-10-31', 'Base case: the long-run dollar gold trend of about 4% a year plus about 9% a year of naira depreciation, roughly the gap between Nigerian and US inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NG', 1, 'gold_return_high', 0.2, NULL, 'assumption', 'Central Bank of Nigeria exchange rates', 'https://www.cbn.gov.ng/rates/ExchRateByCurrency.html', '2026-10-31', 'High case: strong gold years and a sharp naira devaluation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NG', 1, 'gold_return_low', 0.06, NULL, 'assumption', 'Central Bank of Nigeria exchange rates (NGN per US dollar)', 'https://www.cbn.gov.ng/rates/ExchRateByCurrency.html', '2026-10-31', 'Low case: flat dollar gold and slower naira depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NG', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No statutory gratuity or end-of-service rate for private employees was found: the Pension Reform Act 2014 only lets employers agree additional benefits on retirement (section 4(4)); the Labour Act text was not read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NG', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a major private hospital stay in Nigeria was found from an official or international source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NG', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premiums by age per 100,000 naira of cover were found from NHIA or another public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NG', 1, 'inflation_cpi', 0.1463, NULL, 'sourced', 'National Bureau of Statistics CPI, September 2026, via Voice of Nigeria', 'https://von.gov.ng/nigerias-headline-inflation-drops-to-14-63-per-cent/', '2026-09-30', 'Headline inflation 14.63% year on year in September 2026 (15.39% in August; 20.98% in September 2025); food inflation 19.59%. NBS report released 15 October 2026, read through the state broadcaster.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NG', 1, 'inflation_projection', 0.14, NULL, 'assumption', 'NBS CPI via Voice of Nigeria (14.63% in September 2026); World Bank CPI inflation 2021-2025', 'https://data.worldbank.org/indicator/FP.CPI.TOTL.ZG?locations=NG', '2026-10-31', 'Inflation ran between about 15% and 33% a year over 2021-2025 (23.0% in 2025) and has fallen to 14.6%, while the central bank''s 6-9% target band (as listed by the BCEAO, September 2026) has not been reached in recent years, so 14% is used for long-range plans.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NG', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life and group life cover are sold, but no published premium rates per 1,000 naira of cover by age were found from NAICOM or another public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NG', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'NAICOM (the insurance regulator) publishes no industry-wide life claim settlement ratio that could be found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NG', 1, 'life_expectancy', 54.635, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN), Nigeria', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=NG', '2024-12-31', '54.6 years in 2024 (men 54.3, women 54.9); UN WPP 2024 gives 55.0 for 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NG', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":15.3,"men":15.1,"women":15.5},{"age":65,"total":12.2,"men":12,"women":12.4},{"age":70,"total":9.5,"men":9.3,"women":9.6},{"age":80,"total":5.3,"men":5.1,"women":5.4}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/nigeria/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NG', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'No federal non-contributory old-age pension was found in the sources read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NG', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'No federal non-contributory old-age pension a person could claim was found in the sources read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NG', 1, 'oop_health_share', 0.719, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), Nigeria', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=NG', '2023-12-31', '71.9% in 2023 (WHO Global Health Expenditure Database); older than 2025, the latest available.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NG', 1, 'policy_rate', 0.23, NULL, 'sourced', 'Central Bank of Nigeria, key decisions of the Monetary Policy Committee, 21-22 September 2026', 'https://www.cbn.gov.ng/MonetaryPolicy/Decisions.html', '2026-09-22', 'MPR reset to 23% from 26.5% at the 307th MPC meeting; standing facilities corridor +50/-300 basis points around the MPR.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NG', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":50,"inflationLinked":false,"taxFree":true}', 'sourced', 'Pension Reform Act 2014 (National Pension Commission), sections 4, 7 and 10', 'https://www.pencom.gov.ng/wp-content/uploads/2018/01/PRA_2014.pdf', '2014-07-01', 'Contributory Pension Scheme for public and private employees: at least 10% of monthly emoluments from the employer and 8% from the employee into a retirement savings account; benefits (lump sum plus programmed withdrawal or annuity) on retirement or at 50, whichever is later. Contributions are tax-deductible and retirement benefits are not taxable. Benefits depend on fund returns, so not inflation-linked. Law from 2014 (older than 2025), still in force.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NG', 1, 'retirement_accumulation_return_base', 0.14, NULL, 'assumption', 'Debt Management Office, October 2026 FGN bond auction result; equity base 16%; gold base 13%', 'https://www.dmo.gov.ng/6122-summary-of-fgn-bond-auction-results-for-october-2026/file', '2026-10-31', 'Base case: a balanced mix of FGN bonds (about 17%), Nigerian equity funds and some gold, similar to a retirement savings account fund.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NG', 1, 'retirement_accumulation_return_high', 0.18, NULL, 'assumption', 'Debt Management Office, October 2026 FGN bond auction result; equity high 22%', 'https://www.dmo.gov.ng/6122-summary-of-fgn-bond-auction-results-for-october-2026/file', '2026-10-31', 'High case: a growth-leaning mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NG', 1, 'retirement_accumulation_return_low', 0.1, NULL, 'assumption', 'Central Bank of Nigeria, money market indicators, September 2026', 'https://www.cbn.gov.ng/rates/mnymktind.html', '2026-10-31', 'Low case: a cautious mix earning about after-tax deposit and savings bond rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NG', 1, 'retirement_age_default', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Pension Reform Act 2014 (section 7) sets no retirement age: savings in the retirement savings account become payable on retirement under the terms of employment or at 50, whichever is later; employers set their own retirement ages.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NG', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'The federal public service retirement age (commonly cited as 60, or 35 years of service) could not be read from an official text.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NG', 1, 'retirement_return_base', 0.12, NULL, 'assumption', 'Central Bank of Nigeria, money market indicators, September 2026; DMO FGN Savings Bond offer, October 2026', 'https://www.dmo.gov.ng/6092-fgn-savings-bond-offer-for-subscription-october-2026/file', '2026-10-31', 'Base case: a mix of term deposits (about 9.5% after tax) and tax-exempt FGN Savings Bonds (13-14%), below the 1-year treasury bill yield (about 18.8%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NG', 1, 'retirement_return_high', 0.15, NULL, 'assumption', 'CBN treasury bill auction of 28 October 2026', 'https://www.cbn.gov.ng/rates/govtsecurities.html', '2026-10-31', 'High case: most of the money in treasury bills and savings bonds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NG', 1, 'retirement_return_low', 0.09, NULL, 'assumption', 'Central Bank of Nigeria, money market indicators, September 2026 (12-month deposit 10.50%)', 'https://www.cbn.gov.ng/rates/mnymktind.html', '2026-10-31', 'Low case: term deposits after the 10% withholding tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NG', 1, 'sanchayapatra_5y_rate', 0.1407, NULL, 'sourced', 'Debt Management Office, FGN Savings Bond offer for subscription, October 2026 (3-year bond due 14 October 2029)', 'https://www.dmo.gov.ng/6092-fgn-savings-bond-offer-for-subscription-october-2026/file', '2026-10-05', 'Retail FGN Savings Bonds are offered monthly from N5,000 (maximum N50 million) with quarterly interest: 14.071% for 3 years and 13.071% for 2 years in the October 2026 offer (opened 5 October, settled 14 October). No 5-year tenor is offered, so the 3-year rate is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NG', 1, 'savings_account_rate', 0.0536, NULL, 'sourced', 'Central Bank of Nigeria, money market indicators, September 2026 (savings deposit rate)', 'https://www.cbn.gov.ng/rates/mnymktind.html', '2026-09-30', 'Average savings deposit rate 5.36% in September 2026 (7.46% in August).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NG', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":18.38},{"year":2040,"value":16.67},{"year":2065,"value":11.9}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/nigeria/2040/', '2025-12-31', 'Working-age people per person aged 65+ = 100 / old-age dependency ratio: ratio 5.44 in 2025 (World Bank) gives 18.38; 6.0 in 2040 gives 16.67; 8.4 in 2065 (populationpyramid.net/nigeria/2065/) gives 11.9.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NG', 1, 'tax_bank_interest', 0.1, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Nigeria, corporate withholding taxes', 'https://taxsummaries.pwc.com/nigeria/corporate/withholding-taxes', '2026-05-29', 'Interest paid to resident individuals and companies is subject to 10% withholding tax; the page does not say whether it is a final tax for individuals.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NG', 1, 'tax_sanchayapatra_profit', 0, NULL, 'sourced', 'Debt Management Office, FGN Savings Bond offer for subscription, October 2026 (status of the bond)', 'https://www.dmo.gov.ng/6092-fgn-savings-bond-offer-for-subscription-october-2026/file', '2026-10-05', 'The offer states the bond qualifies as a government security under the Companies Income Tax Act and Personal Income Tax Act for tax exemption; individual holders are therefore treated as exempt. The offer still cites the pre-2026 acts, so confirm under the Nigeria Tax Act in force from 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NG', 1, 'tbill_91d_rate', 0.154, NULL, 'sourced', 'Central Bank of Nigeria, government securities: Nigerian Treasury Bills primary auction of 28 October 2026 (91 days)', 'https://www.cbn.gov.ng/rates/govtsecurities.html', '2026-10-28', 'Stop (discount) rate 15.40% on the 91-day bill, about a 16.0% yield; the 364-day bill stopped at 15.80% (about 18.8% yield).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NG', 1, 'tbond_10y_rate', 0.1729, NULL, 'sourced', 'Debt Management Office, October 2026 FGN bond auction result (16.79% FGN SEP 2036)', 'https://www.dmo.gov.ng/6122-summary-of-fgn-bond-auction-results-for-october-2026/file', '2026-10-19', 'Marginal rate 17.29% on the 16.79% FGN September 2036 bond (9 years 10 months to maturity); the 2034 and 2038 bonds cleared at 16.99% and 17.19%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NG', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No FGN bond with about 5 years to maturity was auctioned in 2026 that could be read: DMO auctions from July to October 2026 offered only 2034-2038 maturities.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('NI', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"NI","iso3":"NIC","nameEn":"Nicaragua","nameNative":"Nicaragua","region":"latin_america_caribbean","languages":["es","miq","en"],"currency":{"code":"NIO","symbol":"C$","decimals":2,"compact":"intl","usdRate":{"value":36.6243,"status":"sourced","sourceName":"World Bank WDI PA.NUS.FCRF","sourceUrl":"https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=NI","asOf":"2025-12-31","note":"Official rate 36.6243 córdobas per US dollar (2025 average). Trading Economics quoted 36.80 on 30 October 2026; the BCN site refused access, so its daily official rate could not be read."}},"instruments":{"savings_account":{"available":true,"localName":"Cuenta de ahorro","localNameEn":"Savings account"},"fdr_3m":{"available":true,"localName":"Depósito a plazo fijo a 3 meses","localNameEn":"3-month fixed-term deposit"},"fdr_1y":{"available":true,"localName":"Depósito a plazo fijo a 1 año","localNameEn":"1-year fixed-term deposit"},"dps":{"available":false,"localName":null,"localNameEn":"Monthly recurring deposit","note":"No standard monthly recurring deposit product with a published rate was found."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":"Government savings certificate","note":"No retail government savings certificate was found."},"tbill_91d":{"available":true,"localName":"Letras del Banco Central de Nicaragua","localNameEn":"Central Bank of Nicaragua bills","note":"Short-term bills are issued by the central bank and traded through the stock exchange; yields could not be sourced."},"tbond_5y":{"available":true,"localName":"Bonos de la República de Nicaragua","localNameEn":"Republic of Nicaragua bonds","note":"Ministry of Finance bonds are traded through the stock exchange; yields could not be sourced."},"tbond_10y":{"available":false,"localName":null,"localNameEn":"10-year government bond","note":"A regular 10-year domestic government bond could not be confirmed."},"equity_fund":{"available":false,"localName":null,"localNameEn":"Equity investment fund","note":"No diversified equity fund sold to retail savers in Nicaragua was confirmed; the local exchange trades mainly fixed income."},"gold":{"available":true,"localName":"Oro (lingotes y monedas)","localNameEn":"Gold bars and coins"}},"institutions":{"centralBank":{"name":"Banco Central de Nicaragua (BCN)","url":"https://www.bcn.gob.ni/"},"insuranceRegulator":{"name":"Superintendencia de Bancos y de Otras Instituciones Financieras (SIBOIF)","url":"https://www.siboif.gob.ni/"},"insuranceComplaints":{"name":"SIBOIF, attention to financial users","url":"https://www.siboif.gob.ni/","note":"Complaints about insurers go first to the insurer and then to SIBOIF; a dedicated complaints page could not be reached."},"pensionScheme":{"name":"Instituto Nicaragüense de Seguridad Social (INSS)","url":"https://www.inss.gob.ni/"},"oldAgeAllowance":null,"publicHealthCover":{"name":"Ministerio de Salud (MINSA), free public health care","url":"https://www.minsa.gob.ni/"},"depositInsurance":{"name":"Fondo de Garantía de Depósitos (FOGADE)","url":"https://fogade.gob.ni/preguntas-frecuentes/"},"statistics":{"name":"Instituto Nacional de Información de Desarrollo (INIDE)","url":"https://www.inide.gob.ni/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NI', 1, 'bank_deposit_avg_rate', 0.0227, NULL, 'sourced', 'World Bank WDI FR.INR.DPST', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=NI', '2025-12-31', 'Average rate paid by commercial banks on deposits, 2.27% in 2025 (2.25% in 2024); BCN''s own weighted rates could not be reached. Most deposits in Nicaragua are in US dollars.', 0);
