INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NI', 1, 'deposit_insurance_limit', 439492, NULL, 'sourced', 'FOGADE, preguntas frecuentes (US$12,000 per depositor)', 'https://fogade.gob.ni/preguntas-frecuentes/', '2026-10-31', 'FOGADE covers up to US$12,000 per depositor per member institution, principal plus interest, in córdobas or foreign currency; converted at 36.6243 córdobas per dollar (World Bank 2025).', 0);
