INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NI', 1, 'equity_return_base', 0.055, NULL, 'assumption', 'Global equity index in dollar terms; after-tax average deposit 2.27% x 0.85 = 1.9% (World Bank FR.INR.DPST)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=NI', '2026-10-31', 'Nicaragua''s exchange trades mainly bonds, so equity is a global index fund in dollar terms; kept within 4 points of the after-tax safe rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NI', 1, 'equity_return_high', 0.09, NULL, 'assumption', 'Global equity long-run record in US dollars', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=NI', '2026-10-31', 'High case: global shares repeat their long-run record.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NI', 1, 'equity_return_low', 0.02, NULL, 'assumption', 'No active local stock market; global equities in córdoba terms (córdoba closely tied to the US dollar: 36.62 in 2025, 36.80 in October 2026)', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=NI', '2026-10-31', 'Low case: global shares disappoint, leaving equities near after-tax deposit rates.', 0);
