INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NI', 1, 'goal_inflation_education', 0.05, NULL, 'assumption', 'INIDE CPI July 2026: education division unchanged in the month, headline 4.0% year on year', 'https://www.inide.gob.ni/docs/ipc/ipc_2026/ipc_jul26/Nota_de_Prensa_de_Inflaci%c3%b3n_julio_2026.pdf', '2026-10-31', 'School fees step up once a year, usually faster than general prices; planning uses 5%.', 0);
