INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NI', 1, 'inflation_cpi', 0.04, NULL, 'sourced', 'INIDE, Nota de prensa: Índice de Precios al Consumidor, julio 2026', 'https://www.inide.gob.ni/docs/ipc/ipc_2026/ipc_jul26/Nota_de_Prensa_de_Inflaci%c3%b3n_julio_2026.pdf', '2026-07-31', 'Year-on-year CPI inflation 4.0% in July 2026 (0.64% a year earlier); core 2.84% (INIDE press note of 13 August 2026). The August and September notes were not found at INIDE; Trading Economics also shows July 2026 (4.0%) as the latest. World Bank 2025 average 2.08%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NI', 1, 'inflation_projection', 0.04, NULL, 'assumption', 'INIDE CPI July 2026 4.0%; World Bank 2025 average 2.1% and higher rates in 2022-2023', 'https://www.inide.gob.ni/docs/ipc/ipc_2026/ipc_jul26/Nota_de_Prensa_de_Inflaci%c3%b3n_julio_2026.pdf', '2026-10-31', 'The córdoba moves little against the dollar and recent inflation has ranged from 2% to 4%, so planning uses 4%, close to the current rate.', 0);
