INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('NL', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"NL","iso3":"NLD","nameEn":"Netherlands","nameNative":"Nederland","region":"europe_central_asia","languages":["nl","en","de","fy"],"currency":{"code":"EUR","symbol":"€","decimals":2,"compact":"intl","usdRate":{"value":0.8951,"status":"sourced","sourceName":"European Central Bank euro reference rate (USD)","sourceUrl":"https://data.ecb.europa.eu/data/datasets/EXR/EXR.D.USD.EUR.SP00.A","asOf":"2026-10-30","note":"USD 1.1172 per euro on 30 October 2026, i.e. EUR 0.8951 per USD; World Bank 2025 average 0.885."}},"instruments":{"savings_account":{"available":true,"localName":"Spaarrekening","localNameEn":"Savings account","sourceUrl":"https://data.ecb.europa.eu/data/datasets/MIR/MIR.M.NL.B.L23.D.R.A.2250.EUR.N"},"fdr_3m":{"available":true,"localName":"Deposito","localNameEn":"Term deposit (3 months)","sourceUrl":"https://data.ecb.europa.eu/data/datasets/MIR/MIR.M.NL.B.L22.F.R.A.2250.EUR.N"},"fdr_1y":{"available":true,"localName":"Deposito","localNameEn":"Term deposit (1 year)","sourceUrl":"https://data.ecb.europa.eu/data/datasets/MIR/MIR.M.NL.B.L22.F.R.A.2250.EUR.N"},"dps":{"available":false,"localName":null,"localNameEn":"Monthly recurring deposit","note":"No fixed-rate recurring deposit product; regular saving goes into savings accounts."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":"Government savings certificate","note":"The State does not sell savings certificates or retail savings bonds to individuals."},"tbill_91d":{"available":true,"localName":"Dutch Treasury Certificate (DTC)","localNameEn":"Treasury bills","note":"Auctioned by the Dutch State Treasury Agency, mainly to institutions."},"tbond_5y":{"available":true,"localName":"Staatsobligaties (DSL)","localNameEn":"Dutch State Loans"},"tbond_10y":{"available":true,"localName":"Staatsobligaties (DSL)","localNameEn":"Dutch State Loans","sourceUrl":"https://tradingeconomics.com/netherlands/government-bond-yield"},"equity_fund":{"available":true,"localName":"Beleggingsfonds / indexfonds","localNameEn":"Investment fund / index fund (ETF)","note":"Widely available; holdings are taxed in Box 3 on a deemed return of 6% (2026)."},"gold":{"available":true,"localName":"Goudbaren en gouden munten","localNameEn":"Gold bars and coins","note":"No restriction on buying physical gold; investment gold is VAT-exempt."}},"institutions":{"centralBank":{"name":"De Nederlandsche Bank (DNB)","url":"https://www.dnb.nl/en/"},"insuranceRegulator":{"name":"De Nederlandsche Bank (prudential) and Autoriteit Financiële Markten (conduct)","url":"https://www.afm.nl/en"},"insuranceComplaints":{"name":"Kifid (Financial Services Complaints Tribunal)","url":"https://www.kifid.nl/"},"pensionScheme":{"name":"AOW state pension (Sociale Verzekeringsbank)","url":"https://www.svb.nl/nl/aow"},"oldAgeAllowance":{"name":"AOW and AIO supplement (Sociale Verzekeringsbank)","url":"https://www.svb.nl/nl/aow/bedragen-aow/aow-bedragen"},"publicHealthCover":{"name":"Zorgverzekeringswet (compulsory basic health insurance)","url":"https://www.rijksoverheid.nl/onderwerpen/zorgverzekering"},"depositInsurance":{"name":"Dutch deposit guarantee scheme (DNB)","url":"https://www.dnb.nl/en/reliable-financial-sector/dutch-deposit-guarantee/"},"statistics":{"name":"CBS (Statistics Netherlands)","url":"https://www.cbs.nl/en-gb"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NL', 1, 'bank_deposit_avg_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No weighted average across all household deposits was found (World Bank FR.INR.DPST stops in 2013). ECB MIR series for August 2026: overnight 0.14%, notice (savings) 1.26%, outstanding fixed-term household deposits 2.45%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NL', 1, 'credit_card_rate_cap', 0.12, NULL, 'sourced', 'Rijksoverheid, maximale kredietvergoeding', 'https://www.rijksoverheid.nl/vraag-en-antwoord/bescherming-van-consumenten/wat-is-kredietvergoeding-en-wat-is-het-maximale-kredietvergoedingspercentage', '2026-01-01', 'Legal maximum annual rate on consumer credit is the statutory interest rate (4%) plus 8 points = 12% from 1 January 2026 (14% before). ECB MIR: revolving loans and card credit to households averaged 4.38% in August 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NL', 1, 'deposit_insurance_limit', 100000, NULL, 'sourced', 'De Nederlandsche Bank, Dutch deposit guarantee scheme', 'https://www.dnb.nl/en/reliable-financial-sector/dutch-deposit-guarantee/up-to-what-amount-is-my-money-protected/', '2026-10-31', 'EUR 100,000 per person per bank; a joint account is covered up to EUR 200,000.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NL', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Dutch banks do not offer a fixed-rate monthly recurring deposit product with a published rate; regular saving goes into ordinary savings accounts.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NL', 1, 'equity_return_base', 0.06, NULL, 'assumption', 'AEX index (Trading Economics); 1-year deposit 2.65% (Sep 2026) less Box 3 tax of about 0.46% = 2.2% after tax', 'https://tradingeconomics.com/netherlands/stock-market', '2026-10-31', 'The AEX has risen from about 450 in 2016 to 1,134 (a strong record), but the base case is kept at the after-tax safe rate plus about 4 points, before the yearly Box 3 tax on investments.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NL', 1, 'equity_return_high', 0.085, NULL, 'assumption', 'AEX index 10-year record (Trading Economics)', 'https://tradingeconomics.com/netherlands/stock-market', '2026-10-31', 'High case near the AEX''s long-run total return of roughly 8-9% a year including dividends.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NL', 1, 'equity_return_low', 0.035, NULL, 'assumption', 'AEX index 1,134 on 30 Oct 2026 (Trading Economics); 1-year deposit 2.65% (Sep 2026)', 'https://tradingeconomics.com/netherlands/stock-market', '2026-10-31', 'Low case: a decade of weak European share returns, a little above safe deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NL', 1, 'fdr_1y_rate', 0.0265, NULL, 'sourced', 'ECB MFI interest rate statistics: Netherlands, new household deposits with agreed maturity up to 1 year', 'https://data.ecb.europa.eu/data/datasets/MIR/MIR.M.NL.B.L22.F.R.A.2250.EUR.N', '2026-09-30', 'New-business household deposits with agreed maturity up to 1 year: 2.65% in September 2026 (2.54% in August). Read via the ECB data API.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NL', 1, 'fdr_3m_rate', 0.0265, NULL, 'sourced', 'ECB MFI interest rate statistics: Netherlands, new household deposits with agreed maturity up to 1 year', 'https://data.ecb.europa.eu/data/datasets/MIR/MIR.M.NL.B.L22.F.R.A.2250.EUR.N', '2026-09-30', 'No separate 3-month series is published; the new-business household deposits with agreed maturity up to 1 year bucket (2.65% in September 2026, 2.54% in August) is used. Read via the ECB data API.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NL', 1, 'fixed_income_return_base', 0.02, NULL, 'assumption', 'ECB MIR: Dutch household deposits up to 1 year 2.65% (Sep 2026), less Box 3 tax of about 0.46%', 'https://data.ecb.europa.eu/data/datasets/MIR/MIR.M.NL.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Base case: rolling 1-year term deposits after the Box 3 charge (36% of the 1.28% deemed return).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NL', 1, 'fixed_income_return_high', 0.03, NULL, 'assumption', 'Netherlands 10-year government bond 3.42% (Trading Economics), less Box 3 tax', 'https://tradingeconomics.com/netherlands/government-bond-yield', '2026-10-31', 'High case: locking in long Dutch State Loans after the Box 3 charge.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NL', 1, 'fixed_income_return_low', 0.01, NULL, 'assumption', 'ECB MIR: Dutch household savings (notice) deposits 1.26%, less Box 3 tax', 'https://data.ecb.europa.eu/data/datasets/MIR/MIR.M.NL.B.L23.D.R.A.2250.EUR.N', '2026-10-31', 'Low case: easy-access savings after the Box 3 tax on the deemed savings return.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NL', 1, 'goal_inflation_education', 0.035, NULL, 'assumption', 'CBS CPI education (COICOP 10): +3.4% year on year in September 2026, +8.8% in 2025 (StatLine 86141NED)', 'https://opendata.cbs.nl/statline/#/CBS/nl/dataset/86141NED/table', '2026-10-31', 'Education prices swing with tuition-fee policy (cut in 2023, then raised), so 3.5% is used as a smoothed planning rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NL', 1, 'goal_inflation_health', 0.035, NULL, 'assumption', 'CBS CPI health (COICOP 06): +3.7% in 2025, +6.1% in 2024, +1.3% year on year in September 2026 (StatLine 86141NED)', 'https://opendata.cbs.nl/statline/#/CBS/nl/dataset/86141NED/table', '2026-10-31', 'Health prices rose 4-6% a year in 2023-2025 and health insurance premiums keep rising, so 3.5% (a point above the 2.5% projection) is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NL', 1, 'gold_return_base', 0.05, NULL, 'assumption', 'ECB euro reference rate against the US dollar; long-run dollar gold trend', 'https://data.ecb.europa.eu/data/datasets/EXR/EXR.D.USD.EUR.SP00.A', '2026-10-31', 'Long-run dollar gold trend of about 4-5% with no expected trend in the euro against the dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NL', 1, 'gold_return_high', 0.085, NULL, 'assumption', 'ECB euro reference rate against the US dollar', 'https://data.ecb.europa.eu/data/datasets/EXR/EXR.D.USD.EUR.SP00.A', '2026-10-31', 'High case with strong dollar gold and a weaker euro.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NL', 1, 'gold_return_low', 0.015, NULL, 'assumption', 'ECB euro reference rate against the US dollar', 'https://data.ecb.europa.eu/data/datasets/EXR/EXR.D.USD.EUR.SP00.A', '2026-10-31', 'Low case: weak dollar gold price and a stronger euro.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NL', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No gratuity is paid on retirement: the statutory transition payment (transitievergoeding, one-third of a month''s pay per year of service, Civil Code art. 7:673) applies only when the employer ends or does not renew the contract, and not when employment ends at AOW age (rijksoverheid.nl, ontslag).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NL', 1, 'health_hospitalisation_cost', 385, NULL, 'sourced', 'Rijksoverheid, eigen risico zorgverzekering', 'https://www.rijksoverheid.nl/documenten/vraag-en-antwoord/zorgverzekering/eigen-risico-zorgverzekering', '2026-01-01', 'Everyone must hold basic health insurance, which covers hospital stays and operations; the patient pays at most the compulsory yearly deductible of EUR 385 (2026 and 2027), or up to EUR 885 with the highest voluntary deductible.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NL', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Dutch basic health insurance is community-rated (one premium per policy regardless of age, about EUR 150-170 a month) and supplementary cover is priced per package, so no premium per EUR 100,000 of cover by age exists.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NL', 1, 'inflation_cpi', 0.034, NULL, 'sourced', 'CBS (Statistics Netherlands), CPI September 2026', 'https://www.cbs.nl/en-gb/news/2026/42/inflation-increases-to-3-4-percent-in-september', '2026-09-30', 'CPI up 3.4% year on year in September 2026 (3.3% in August), published 13 October 2026; HICP 3.0%. World Bank 2025 average 3.2%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NL', 1, 'inflation_projection', 0.025, NULL, 'assumption', 'ECB 2% inflation target; CBS CPI 2021-2025 average 4.6%, 3.2% in 2025 (StatLine 86141NED)', 'https://opendata.cbs.nl/statline/#/CBS/nl/dataset/86141NED/table', '2026-10-31', 'The ECB target anchors euro prices, but Dutch inflation has run above the euro-area average for years (3.2-3.4% in 2025-26), so 2.5% is used for planning.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NL', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life cover (overlijdensrisicoverzekering) is widely sold, but no regulator or official premium table per EUR 1,000 of cover by age was found; only company quotes exist.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NL', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Neither DNB, the AFM nor Kifid publishes an industry-wide life insurance claim settlement ratio that could be found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NL', 1, 'life_expectancy', 82.08, NULL, 'sourced', 'CBS StatLine 37360ned, life table 2025 (levensverwachting at birth)', 'https://opendata.cbs.nl/statline/#/CBS/nl/dataset/37360ned/table', '2025-12-31', 'Men 80.67, women 83.46 in 2025; World Bank 2024 value 81.97.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NL', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":24.78,"men":23.69,"women":25.8},{"age":65,"total":20.47,"men":19.46,"women":21.42},{"age":70,"total":16.42,"men":15.49,"women":17.26},{"age":80,"total":9.29,"men":8.64,"women":9.81}]}', 'sourced', 'CBS StatLine 37360ned, life table 2025', 'https://opendata.cbs.nl/statline/#/CBS/nl/dataset/37360ned/table', '2025-12-31', 'Official period life table for 2025, both sexes and by sex (read via the CBS OData API).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NL', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":67,"womenAge":67,"over90Monthly":null,"meansTested":false}', 'sourced', 'Rijksoverheid, AOW-leeftijd; SZW Rekenregels per 1 juli 2026', 'https://www.rijksoverheid.nl/onderwerpen/algemene-ouderdomswet-aow/aow-leeftijd', '2026-10-31', 'Paid from the AOW age (67 in 2026, 67 years 3 months from 2028) to residents and former residents, with no means test; only the AIO top-up for incomplete AOW is means-tested.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NL', 1, 'old_age_allowance_monthly', 1662.16, NULL, 'sourced', 'Ministry of Social Affairs and Employment (SZW), Bijlagen Rekenregels per 1 juli 2026, Bijlage 3 (AOW amounts)', 'https://open.overheid.nl/documenten/abc6961b-4af1-4405-853d-f2a9d13e3321/file', '2026-07-01', 'Full AOW for a person living alone (70% of the reference minimum wage), EUR 1,662.16 gross a month from 1 July 2026 (EUR 1,139.39 each for a couple), plus EUR 104.78 holiday pay a month paid in May (official SZW calculation rules; the SVB amounts page blocked automated reading). AOW is residence-based: 2% of the full amount accrues for each year lived in the Netherlands in the 50 years before AOW age; a means-tested AIO supplement tops up an incomplete AOW.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NL', 1, 'oop_health_share', 0.1179, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=NL', '2024-12-31', 'Latest available year is 2024 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NL', 1, 'policy_rate', 0.025, NULL, 'sourced', 'European Central Bank deposit facility rate (series FM.D.U2.EUR.4F.KR.DFR.LEV)', 'https://data.ecb.europa.eu/data/datasets/FM/FM.D.U2.EUR.4F.KR.DFR.LEV', '2026-10-30', 'The Netherlands uses the euro; ECB deposit facility rate 2.50% (read via the ECB data API).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NL', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":17,"entryAgeMax":null,"pensionFromAge":67,"nomineeUntilAge":null,"inflationLinked":true,"taxFree":false}', 'sourced', 'Rijksoverheid, AOW-leeftijd; SVB AOW amounts', 'https://www.rijksoverheid.nl/onderwerpen/algemene-ouderdomswet-aow/aow-leeftijd', '2026-10-31', 'The AOW state pension is financed by payroll premiums but accrues by residence (2% a year over the 50 years before AOW age, starting at about 17); paid from 67 (67y3m from 2028), indexed twice a year with the net minimum wage, and taxed as income. Most employees also build an occupational pension in a sector or company fund.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NL', 1, 'retirement_accumulation_return_base', 0.04, NULL, 'assumption', 'AEX index record; after-tax 1-year deposit about 2.2%', 'https://tradingeconomics.com/netherlands/stock-market', '2026-10-31', 'Base case: roughly half shares at 6% and half fixed income at about 2-2.5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NL', 1, 'retirement_accumulation_return_high', 0.055, NULL, 'assumption', 'AEX index record; 10-year government bond 3.42%', 'https://tradingeconomics.com/netherlands/stock-market', '2026-10-31', 'High case for a growth-leaning balanced mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NL', 1, 'retirement_accumulation_return_low', 0.025, NULL, 'assumption', 'AEX index record; after-tax 1-year deposit about 2.2%', 'https://tradingeconomics.com/netherlands/stock-market', '2026-10-31', 'Low case for a balanced mix if shares lag.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NL', 1, 'retirement_age_default', 67, NULL, 'sourced', 'Rijksoverheid, AOW-leeftijd 2025-2031', 'https://www.rijksoverheid.nl/onderwerpen/algemene-ouderdomswet-aow/aow-leeftijd', '2026-10-31', 'AOW age is 67 in 2026-2027 and 67 years 3 months in 2028-2031; it is then set each year, 5 years ahead, from CBS life expectancy (two-thirds of gains), so people born after 1975 (AOW from 2043 or later) should expect at least 67 years 3 months and probably more. Same for men and women.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NL', 1, 'retirement_age_government', 67, NULL, 'sourced', 'P-Direkt (central government HR service), end of employment at AOW age', 'https://www.p-direkt.nl/informatie-rijkspersoneel-2020/mijn-werk/einde-dienstverband/einde-dienstverband-bij-aow-leeftijd', '2026-10-31', 'Central government employment ends automatically at the AOW age (P-Direkt: ''stopt je dienstverband automatisch van rechtswege''), 67 in 2026 and rising with the AOW age; the page belongs to the 2020 information set, so the source is older than 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NL', 1, 'retirement_return_base', 0.02, NULL, 'assumption', 'ECB MIR: Dutch household deposits up to 1 year 2.65% (Sep 2026), less Box 3 tax of about 0.46%', 'https://data.ecb.europa.eu/data/datasets/MIR/MIR.M.NL.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Base case capped at the after-tax 1-year term deposit rate (about 2.2%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NL', 1, 'retirement_return_high', 0.028, NULL, 'assumption', 'Netherlands 10-year government bond 3.42% (Trading Economics), less Box 3 tax', 'https://tradingeconomics.com/netherlands/government-bond-yield', '2026-10-31', 'High case: a ladder of longer Dutch State Loans and deposits after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NL', 1, 'retirement_return_low', 0.01, NULL, 'assumption', 'ECB MIR: Dutch household savings deposits 1.26%, less Box 3 tax', 'https://data.ecb.europa.eu/data/datasets/MIR/MIR.M.NL.B.L23.D.R.A.2250.EUR.N', '2026-10-31', 'Low case: mostly easy-access savings after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NL', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Dutch State Treasury Agency (DSTA) sells no retail savings certificate or savings bond to individuals; Dutch State Loans are bought through banks or brokers on the market.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NL', 1, 'savings_account_rate', 0.0126, NULL, 'sourced', 'ECB MFI interest rate statistics: Netherlands, household deposits redeemable at notice up to 3 months', 'https://data.ecb.europa.eu/data/datasets/MIR/MIR.M.NL.B.L23.D.R.A.2250.EUR.N', '2026-09-30', 'Dutch savings accounts (spaarrekeningen) are reported as household deposits redeemable at notice; 1.26% in September 2026 (also 1.26% in August), read via the ECB data API.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NL', 1, 'support_ratio', NULL, '{"points":[{"year":2026,"value":3},{"year":2040,"value":2.31},{"year":2065,"value":1.99}]}', 'sourced', 'UN WPP 2024 medium variant via populationpyramid.net (old-age dependency ratio)', 'https://www.populationpyramid.net/netherlands/2040/', '2026-01-01', '100 / old-age dependency ratio: 33.3 (2026), 43.2 (2040) and 50.3 (2065, populationpyramid.net/netherlands/2065/). World Bank 2025: 32.5.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NL', 1, 'tax_bank_interest', 0.36, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Netherlands income determination (Box 3)', 'https://taxsummaries.pwc.com/netherlands/individual/income-determination', '2026-05-29', 'No withholding tax on interest (PwC): savings are taxed in Box 3 at 36% on a deemed return rather than on actual interest, on assets above EUR 59,357 per person (2026); taxpayers may instead declare their actual return if it is lower. The provisional 2026 deemed return on bank balances (about 1.28%) is not shown on the PwC page. Effective tax on actual interest is therefore usually well under 36%, and zero below the exemption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NL', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No retail government savings certificate exists; Dutch State Loans held by individuals fall in Box 3 (36% on a deemed return for other assets).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NL', 1, 'tbill_91d_rate', 0.0253, NULL, 'sourced', 'Trading Economics, Netherlands 3-month bill yield (bond table)', 'https://tradingeconomics.com/netherlands/government-bond-yield', '2026-10-30', 'Secondary source: Dutch Treasury Certificates (DTC) are auctioned by the DSTA; the page showed 2.64% on 2 November 2026 when re-checked, consistent with the 30 October figure; ECB deposit facility rate 2.50%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NL', 1, 'tbond_10y_rate', 0.0342, NULL, 'sourced', 'Trading Economics, Netherlands 10-year government bond yield', 'https://tradingeconomics.com/netherlands/government-bond-yield', '2026-10-30', 'Secondary source; re-checked 3.39% on 3 November 2026. The ECB long-term convergence yield for the Netherlands (monthly average, primary) was 3.56% in September 2026 (IRS.M.NL.L.L40.CI.0000.EUR.N.Z); 2-year 3.07-3.08%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NL', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No current 5-year Dutch State Loan yield was found on readable pages: Trading Economics lists 3-month, 6-month, 2-year and 10-year yields only, and worldgovernmentbonds.com loads data by script.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('NO', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"NO","iso3":"NOR","nameEn":"Norway","nameNative":"Norge","region":"europe_central_asia","languages":["nb","nn","en","se"],"currency":{"code":"NOK","symbol":"kr","decimals":2,"compact":"intl","usdRate":{"value":9.2302,"status":"sourced","sourceName":"Norges Bank exchange rates (USD/NOK)","sourceUrl":"https://data.norges-bank.no/api/data/EXR/B.USD.NOK.SP?startPeriod=2026-10-30&endPeriod=2026-10-30&format=csv","asOf":"2026-10-30","note":"NOK 9.2302 per US dollar on 30 October 2026 (read via the Norges Bank data API); World Bank 2025 average 10.40."}},"instruments":{"savings_account":{"available":true,"localName":"Sparekonto","localNameEn":"Savings account","sourceUrl":"https://www.ssb.no/en/statbank/table/11018"},"fdr_3m":{"available":true,"localName":"Fastrenteinnskudd","localNameEn":"Fixed-rate term deposit (3 months)","sourceUrl":"https://www.ssb.no/en/statbank/table/11018"},"fdr_1y":{"available":true,"localName":"Fastrenteinnskudd","localNameEn":"Fixed-rate term deposit (1 year)","sourceUrl":"https://www.ssb.no/en/statbank/table/11018"},"dps":{"available":false,"localName":null,"localNameEn":"Monthly recurring deposit","note":"No fixed-rate recurring deposit product; BSU is a tax-favoured housing savings account for people under 34."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":"Government savings certificate","note":"No retail government savings certificate or savings bond."},"tbill_91d":{"available":true,"localName":"Statskasseveksler","localNameEn":"Treasury bills","note":"Issued by Norges Bank for the state, mainly to institutions.","sourceUrl":"https://data.norges-bank.no/api/data/GOVT_GENERIC_RATES/B.3M+12M+5Y+10Y.TBIL+GBON?startPeriod=2026-10-30&endPeriod=2026-10-30&format=csv"},"tbond_5y":{"available":true,"localName":"Statsobligasjoner","localNameEn":"Norwegian government bonds","sourceUrl":"https://data.norges-bank.no/api/data/GOVT_GENERIC_RATES/B.3M+12M+5Y+10Y.TBIL+GBON?startPeriod=2026-10-30&endPeriod=2026-10-30&format=csv"},"tbond_10y":{"available":true,"localName":"Statsobligasjoner","localNameEn":"Norwegian government bonds","sourceUrl":"https://data.norges-bank.no/api/data/GOVT_GENERIC_RATES/B.3M+12M+5Y+10Y.TBIL+GBON?startPeriod=2026-10-30&endPeriod=2026-10-30&format=csv"},"equity_fund":{"available":true,"localName":"Aksjefond / indeksfond","localNameEn":"Equity fund / index fund","note":"Widely available; an equity savings account (aksjesparekonto) defers tax on gains until withdrawal."},"gold":{"available":true,"localName":"Gullbarrer og gullmynter","localNameEn":"Gold bars and coins","note":"No restriction on buying physical gold; investment gold is VAT-exempt."}},"institutions":{"centralBank":{"name":"Norges Bank","url":"https://www.norges-bank.no/en/"},"insuranceRegulator":{"name":"Finanstilsynet (Financial Supervisory Authority of Norway)","url":"https://www.finanstilsynet.no/en/"},"insuranceComplaints":{"name":"Finansklagenemnda (Norwegian Financial Services Complaints Board)","url":"https://www.finkn.no/"},"pensionScheme":{"name":"Folketrygden old-age pension (NAV)","url":"https://www.nav.no/alderspensjon"},"oldAgeAllowance":{"name":"Garantipensjon / minimum pension (NAV)","url":"https://www.nav.no/alderspensjon#minstepensjon"},"publicHealthCover":{"name":"National Insurance Scheme health services (helsenorge.no)","url":"https://www.helsenorge.no/"},"depositInsurance":{"name":"Bankenes sikringsfond (Norwegian Banks'' Guarantee Fund)","url":"https://www.bankenessikringsfond.no/"},"statistics":{"name":"Statistics Norway (SSB)","url":"https://www.ssb.no/en"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NO', 1, 'bank_deposit_avg_rate', 0.0316, NULL, 'sourced', 'SSB table 11018: interest rates on total household deposits (sample of banks)', 'https://www.ssb.no/en/statbank/table/11018', '2026-09-30', 'Average rate on all household deposits 3.16% in September 2026 (3.14% in August); World Bank FR.INR.DPST 2025: 3.21%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NO', 1, 'credit_card_rate_cap', 0.227, NULL, 'sourced', 'SSB table 12844: credit card interest rates, households (interest-bearing balances)', 'https://www.ssb.no/en/statbank/table/12844', '2026-09-30', 'No legal rate cap was found; the average rate on interest-bearing credit card balances was 22.7% in Q3 2026 (10.9% across all balances, including interest-free ones).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NO', 1, 'deposit_insurance_limit', 2000000, NULL, 'sourced', 'Financial Institutions Act (finansforetaksloven) section 19-4, Lovdata', 'https://lovdata.no/dokument/NL/lov/2015-04-10-17/KAPITTEL_19', '2026-10-31', 'Guaranteed deposits up to NOK 2 million per depositor per member bank (Bankenes sikringsfond); some deposits (e.g. from a home sale) are fully covered for a limited period.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NO', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Norwegian banks do not offer a fixed-rate monthly recurring deposit product with a published rate; the closest scheme is BSU, a tax-favoured housing savings account for people under 34, not a general recurring deposit.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NO', 1, 'equity_return_base', 0.07, NULL, 'assumption', 'OSEAX total-return index (Trading Economics); after-tax 1-year deposit about 3.6%', 'https://tradingeconomics.com/norway/stock-market', '2026-10-31', 'The Oslo index has a strong 10-year record (about 14% a year), but the base case is kept at the after-tax safe rate plus about 3.5 points, before the 37.84% tax on realised gains and dividends (deferred inside an equity savings account).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NO', 1, 'equity_return_high', 0.095, NULL, 'assumption', 'OSEAX 10-year record (Trading Economics)', 'https://tradingeconomics.com/norway/stock-market', '2026-10-31', 'High case near the Oslo market''s long-run total return of about 9-10% a year.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NO', 1, 'equity_return_low', 0.04, NULL, 'assumption', 'Oslo Bors All-Share (OSEAX) 2,575 on 30 Oct 2026 (Trading Economics); 1-year deposits 4.6% less 22% tax = 3.6%', 'https://tradingeconomics.com/norway/stock-market', '2026-10-31', 'Low case: share returns barely above safe after-tax deposits, as oil-heavy Oslo shares follow a weak energy cycle.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NO', 1, 'fdr_1y_rate', 0.046, NULL, 'sourced', 'SSB table 11018: interest rates on household deposits with conditions (fixed-term and notice)', 'https://www.ssb.no/en/statbank/table/11018', '2026-09-30', '4.60% in September 2026 for fixed-term and notice deposits (no maturity breakdown); the 12-month treasury bill yielded 4.80% on 30 October 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NO', 1, 'fdr_3m_rate', 0.046, NULL, 'sourced', 'SSB table 11018: interest rates on household deposits with conditions (fixed-term and notice)', 'https://www.ssb.no/en/statbank/table/11018', '2026-09-30', 'No breakdown by maturity is published; deposits with conditions (fixed-term and notice accounts) averaged 4.60% in September 2026. The 3-month treasury bill yielded 4.72% on 30 October 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NO', 1, 'fixed_income_return_base', 0.035, NULL, 'assumption', 'SSB: household fixed-term/notice deposits 4.60% less 22% tax = 3.6%', 'https://www.ssb.no/en/statbank/table/11018', '2026-10-31', 'Base case: fixed-term deposits after the 22% tax on capital income.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NO', 1, 'fixed_income_return_high', 0.0375, NULL, 'assumption', 'Norges Bank: 12-month treasury bill 4.80% less 22% tax = 3.75%', 'https://data.norges-bank.no/api/data/GOVT_GENERIC_RATES/B.3M+12M+5Y+10Y.TBIL+GBON?startPeriod=2026-10-30&endPeriod=2026-10-30&format=csv', '2026-10-31', 'High case: short government paper and the best deposit rates after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NO', 1, 'fixed_income_return_low', 0.022, NULL, 'assumption', 'SSB: household demand deposits 2.88% less 22% tax', 'https://www.ssb.no/en/statbank/table/11018', '2026-10-31', 'Low case: easy-access savings after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NO', 1, 'goal_inflation_education', 0.04, NULL, 'assumption', 'SSB CPI education services (COICOP 10): +4.3% year on year in September 2026, +4.2% in 2025, +5.4% in 2024', 'https://www.ssb.no/en/statbank/table/14700', '2026-10-31', 'Public education is free; fees that families do pay (private schools, courses) have risen 4-5% a year, so 4% is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NO', 1, 'goal_inflation_health', 0.04, NULL, 'assumption', 'SSB CPI health (COICOP 06): +4.9% year on year in September 2026, +4.0% in 2025, +4.6% in 2024', 'https://www.ssb.no/en/statbank/table/14700', '2026-10-31', 'Health prices have risen about 4-5% a year since 2024, so 4% is used, above the 2.5% general projection.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NO', 1, 'gold_return_base', 0.05, NULL, 'assumption', 'Norges Bank USD/NOK exchange rate; long-run dollar gold trend', 'https://data.norges-bank.no/api/data/EXR/B.USD.NOK.SP?startPeriod=2026-10-30&endPeriod=2026-10-30&format=csv', '2026-10-31', 'Long-run dollar gold trend of about 4-5% with no expected trend in the krone against the dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NO', 1, 'gold_return_high', 0.09, NULL, 'assumption', 'Norges Bank USD/NOK exchange rate', 'https://data.norges-bank.no/api/data/EXR/B.USD.NOK.SP?startPeriod=2026-10-30&endPeriod=2026-10-30&format=csv', '2026-10-31', 'High case with strong dollar gold and a weaker krone, as in 2013-2023.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NO', 1, 'gold_return_low', 0.015, NULL, 'assumption', 'Norges Bank USD/NOK exchange rate', 'https://data.norges-bank.no/api/data/EXR/B.USD.NOK.SP?startPeriod=2026-10-30&endPeriod=2026-10-30&format=csv', '2026-10-31', 'Low case: weak dollar gold price and a stronger krone.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NO', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'Norwegian employment law gives notice periods on dismissal; no statutory gratuity or end-of-service payment per year of service was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NO', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'Inpatient treatment in public hospitals is covered by the national insurance scheme, with yearly caps on patient charges for outpatient care, but helsenorge.no pages could not be read to confirm the figures; no official cost of a private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NO', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Private health insurance (behandlingsforsikring) is mostly an employer benefit priced per plan, not per NOK 100,000 of cover; no published age-banded premium table was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NO', 1, 'inflation_cpi', 0.034, NULL, 'sourced', 'Statistics Norway (SSB), CPI table 14700, 12-month rate', 'https://www.ssb.no/en/statbank/table/14700', '2026-09-30', 'CPI up 3.4% year on year in September 2026 (3.3% in August), published 9 October 2026. World Bank 2025 average 3.0%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NO', 1, 'inflation_projection', 0.025, NULL, 'assumption', 'Norges Bank 2% inflation target; SSB CPI 2021-2025 average 4.2%, 3.0% in 2025 (table 14701)', 'https://www.ssb.no/en/statbank/table/14701', '2026-10-31', 'Norges Bank targets 2%, but inflation has stayed at 3-3.4% since 2024, so 2.5% is used for planning.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NO', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life cover (livsforsikring/dødsfallsforsikring) is widely sold, but no regulator or official premium table per NOK 1,000 of cover by age was found; only company quotes exist.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NO', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Finanstilsynet and Finans Norge do not publish an industry-wide life insurance claim settlement ratio that could be found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NO', 1, 'life_expectancy', 83.23, NULL, 'sourced', 'SSB table 07902, life tables 2025', 'https://www.ssb.no/en/statbank/table/07902', '2025-12-31', 'Men 81.61, women 84.85 in 2025; World Bank 2024 value 83.16.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NO', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":25.22,"men":24.02,"women":26.37},{"age":65,"total":20.85,"men":19.73,"women":21.91},{"age":70,"total":16.72,"men":15.7,"women":17.65},{"age":80,"total":9.48,"men":8.75,"women":10.08}]}', 'sourced', 'SSB table 07902, life tables 2025', 'https://www.ssb.no/en/statbank/table/07902', '2025-12-31', 'Official period life table for 2025, both sexes and by sex (read via the SSB API).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NO', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":67,"womenAge":67,"over90Monthly":null,"meansTested":false}', 'sourced', 'NAV, alderspensjon (garantipensjon)', 'https://www.nav.no/alderspensjon', '2026-10-31', 'Residence-based minimum pension from 67 for people born 1963 or later; no means test on assets or other income, but it is reduced by 80% of the person''s own earnings-related pension.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NO', 1, 'old_age_allowance_monthly', 21149, NULL, 'sourced', 'NAV, alderspensjon: garantipensjon rates from 1 May 2026', 'https://www.nav.no/alderspensjon', '2026-05-01', 'Guarantee pension (garantipensjon) at the high rate for a single person, NOK 253,787 a year (about NOK 21,149 a month); NOK 234,765 a year at the ordinary rate for people living with a pensioner or a partner earning over 2G. Full rate needs 40 years of residence (trygdetid) from 16 to 66, at least 5 years; it is reduced by 80% of any earnings-related pension.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NO', 1, 'oop_health_share', 0.1369, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=NO', '2023-12-31', 'Latest available year is 2023 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NO', 1, 'policy_rate', 0.045, NULL, 'sourced', 'Norges Bank key policy rate (data.norges-bank.no, series IR B.KPRA.SD.R)', 'https://data.norges-bank.no/api/data/IR/B.KPRA.SD.R?startPeriod=2026-10-30&endPeriod=2026-10-30&format=csv', '2026-10-30', 'Policy rate 4.50% on 30 October 2026 (read via the Norges Bank data API).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NO', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":67,"nomineeUntilAge":null,"inflationLinked":true,"taxFree":false}', 'sourced', 'NAV, alderspensjon (folketrygden)', 'https://www.nav.no/alderspensjon', '2026-10-31', 'National insurance old-age pension: 18.1% of pensionable income up to 7.1G (G = NOK 136,549 from May 2026) is added to a pension account each year; it can be drawn from 62 to 75 (usually 67), is adjusted each year by the average of price and wage growth, and is taxed as income. Most employees also have a mandatory occupational pension.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NO', 1, 'retirement_accumulation_return_base', 0.05, NULL, 'assumption', 'After-tax term deposits about 3.6%; equity base 7%', 'https://tradingeconomics.com/norway/stock-market', '2026-10-31', 'Base case: roughly half shares at 7% and half safe fixed income at about 3.5% after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NO', 1, 'retirement_accumulation_return_high', 0.065, NULL, 'assumption', 'Equity high 9.5%; after-tax 12-month bill 3.75%', 'https://tradingeconomics.com/norway/stock-market', '2026-10-31', 'High case for a growth-leaning balanced mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NO', 1, 'retirement_accumulation_return_low', 0.035, NULL, 'assumption', 'After-tax term deposits about 3.6%; OSEAX record', 'https://www.ssb.no/en/statbank/table/11018', '2026-10-31', 'Low case for a balanced mix if shares lag.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NO', 1, 'retirement_age_default', 67, NULL, 'sourced', 'NAV, alderspensjon (old-age pension)', 'https://www.nav.no/alderspensjon', '2026-10-31', 'Old-age pension can be drawn flexibly from 62 (with enough accrual) to 75; the usual age is 67 and the guarantee pension starts at 67. Parliament has agreed to replace it with a ''normert pensjonsalder'' that rises with life expectancy (each cohort working 1-2 months longer), so people born after 1975 should expect a higher age, but timing is not yet decided.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NO', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'State employees draw the same national old-age pension (from 62-75, usually 67) plus a public-service pension; the upper age limit for remaining in state service could not be confirmed from a readable official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NO', 1, 'retirement_return_base', 0.035, NULL, 'assumption', 'SSB: household fixed-term/notice deposits 4.60% less 22% tax = 3.6%', 'https://www.ssb.no/en/statbank/table/11018', '2026-10-31', 'Base case capped at the after-tax term deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NO', 1, 'retirement_return_high', 0.0375, NULL, 'assumption', 'Norges Bank: 12-month treasury bill 4.80% less 22% tax', 'https://data.norges-bank.no/api/data/GOVT_GENERIC_RATES/B.3M+12M+5Y+10Y.TBIL+GBON?startPeriod=2026-10-30&endPeriod=2026-10-30&format=csv', '2026-10-31', 'High case: short government paper and best deposit rates after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NO', 1, 'retirement_return_low', 0.022, NULL, 'assumption', 'SSB: household demand deposits 2.88% less 22% tax', 'https://www.ssb.no/en/statbank/table/11018', '2026-10-31', 'Low case: mostly easy-access savings after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NO', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Norway has no government savings certificate or retail savings bond sold to individuals; government bonds and bills trade through banks and brokers.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NO', 1, 'savings_account_rate', 0.0288, NULL, 'sourced', 'SSB table 11018: interest rates on household deposits on demand (sample of banks)', 'https://www.ssb.no/en/statbank/table/11018', '2026-09-30', 'Average rate on households'' demand deposits 2.88% in September 2026; all household deposits 3.16%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NO', 1, 'support_ratio', NULL, '{"points":[{"year":2026,"value":3.37},{"year":2040,"value":2.59},{"year":2065,"value":2.01}]}', 'sourced', 'SSB table 14740, population projections 2026, main alternative (MMM)', 'https://www.ssb.no/en/statbank/table/14740', '2026-01-01', 'People aged 15-64 divided by people 65+ in the official 2026 projection: 3.37 (2026), 2.59 (2040), 2.01 (2065); old-age dependency 29.7, 38.6 and 49.7.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NO', 1, 'tax_bank_interest', 0.22, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Norway income determination', 'https://taxsummaries.pwc.com/norway/individual/income-determination', '2026-09-03', 'No withholding: net positive capital income, including interest, is taxed at 22% in the annual assessment (PwC states the 22% rate for net capital income); net wealth tax may also apply to large deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NO', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No retail government savings certificate exists; interest on government bonds is ordinary capital income taxed at 22%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NO', 1, 'tbill_91d_rate', 0.04723, NULL, 'sourced', 'Norges Bank, generic government interest rates (3-month treasury bill)', 'https://data.norges-bank.no/api/data/GOVT_GENERIC_RATES/B.3M+12M+5Y+10Y.TBIL+GBON?startPeriod=2026-10-30&endPeriod=2026-10-30&format=csv', '2026-10-30', '4.723% on 30 October 2026 (4.731% on 29 October; 12-month 4.804%); read via the Norges Bank data API.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NO', 1, 'tbond_10y_rate', 0.04435, NULL, 'sourced', 'Norges Bank, generic government interest rates (10-year government bond)', 'https://data.norges-bank.no/api/data/GOVT_GENERIC_RATES/B.3M+12M+5Y+10Y.TBIL+GBON?startPeriod=2026-10-30&endPeriod=2026-10-30&format=csv', '2026-10-30', '4.435% on 30 October 2026 (4.444% on 29 October); read via the Norges Bank data API.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NO', 1, 'tbond_5y_rate', 0.04597, NULL, 'sourced', 'Norges Bank, generic government interest rates (5-year government bond)', 'https://data.norges-bank.no/api/data/GOVT_GENERIC_RATES/B.3M+12M+5Y+10Y.TBIL+GBON?startPeriod=2026-10-30&endPeriod=2026-10-30&format=csv', '2026-10-30', '4.597% on 30 October 2026 (4.603% on 29 October); read via the Norges Bank data API.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('NP', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"NP","iso3":"NPL","nameEn":"Nepal","nameNative":"नेपाल","region":"south_asia","languages":["ne","mai","bho","en","hi"],"currency":{"code":"NPR","symbol":"Rs","decimals":2,"compact":"lakh_crore","usdRate":{"value":153.24,"status":"sourced","sourceName":"Nepal Rastra Bank, Current Macroeconomic and Financial Situation (two months of 2026/27)","sourceUrl":"https://www.nrb.org.np/contents/uploads/2026/10/Current-Macroeconomic-and-Financial-Situation-English-Based-on-Two-Months-data-of-2026.27.pdf","asOf":"2026-09-16","note":"Buying rate per US dollar, mid-September 2026; rupee pegged to the Indian rupee at 1.6"}},"instruments":{"savings_account":{"available":true,"localName":"बचत खाता","localNameEn":"Savings account","sourceUrl":"https://www.nrb.org.np/cmfm_rates/lending_rates"},"fdr_3m":{"available":true,"localName":"मुद्दती निक्षेप","localNameEn":"Fixed deposit","sourceUrl":"https://www.nrb.org.np/cmfm_rates/lending_rates"},"fdr_1y":{"available":true,"localName":"मुद्दती निक्षेप","localNameEn":"Fixed deposit","sourceUrl":"https://www.nrb.org.np/cmfm_rates/lending_rates"},"dps":{"available":true,"localName":"आवधिक बचत","localNameEn":"Recurring deposit","note":"Recurring deposits are offered for terms of about 1 to 5 years"},"sanchayapatra_5y":{"available":true,"localName":"नागरिक बचतपत्र","localNameEn":"Citizen Savings Bond","note":"Issued by Nepal Rastra Bank in tranches for Nepali citizens; Foreign Employment Savings Bond for migrant workers","sourceUrl":"https://risingnepaldaily.com/news/71169"},"tbill_91d":{"available":true,"localName":"ट्रेजरी बिल","localNameEn":"Treasury bill","note":"Auctioned by Nepal Rastra Bank; bought mostly by banks and financial institutions","sourceUrl":"https://www.nrb.org.np/contents/uploads/2026/10/Current-Macroeconomic-and-Financial-Situation-English-Based-on-Two-Months-data-of-2026.27.pdf"},"tbond_5y":{"available":true,"localName":"विकास ऋणपत्र","localNameEn":"Development bond","note":"Government development bonds, auctioned and listed on NEPSE"},"tbond_10y":{"available":true,"localName":"विकास ऋणपत्र","localNameEn":"Development bond"},"equity_fund":{"available":true,"localName":"म्युचुअल फण्ड","localNameEn":"Mutual fund","note":"Closed-end and open-end mutual funds regulated by the Securities Board of Nepal"},"gold":{"available":true,"localName":"सुन","localNameEn":"Gold","note":"Gold is sold mainly as jewellery and tola-weight pieces"}},"institutions":{"centralBank":{"name":"Nepal Rastra Bank","url":"https://www.nrb.org.np/"},"insuranceRegulator":{"name":"Nepal Insurance Authority","url":"https://nia.gov.np/"},"insuranceComplaints":{"name":"Nepal Insurance Authority (grievance handling)","url":"https://nia.gov.np/"},"pensionScheme":{"name":"Social Security Fund","url":"https://ssf.gov.np/"},"oldAgeAllowance":{"name":"Department of National ID and Civil Registration (social security allowance)","url":"https://donidcr.gov.np/"},"publicHealthCover":{"name":"Health Insurance Board","url":"https://hib.gov.np/"},"depositInsurance":{"name":"Deposit and Credit Guarantee Fund","url":"https://dcgf.gov.np/"},"statistics":{"name":"National Statistics Office","url":"https://nsonepal.gov.np/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NP', 1, 'bank_deposit_avg_rate', 0.0311, NULL, 'sourced', 'Nepal Rastra Bank, Current Macroeconomic and Financial Situation (two months of 2026/27)', 'https://www.nrb.org.np/contents/uploads/2026/10/Current-Macroeconomic-and-Financial-Situation-English-Based-on-Two-Months-data-of-2026.27.pdf', '2026-09-16', 'Weighted average deposit rate of commercial banks; development banks 3.48%, finance companies 4.04%', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NP', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No Nepal Rastra Bank cap or regulator statistic on credit card rates found; only individual banks'' card terms publish a rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NP', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Deposit and Credit Guarantee Fund site (dcgf.gov.np) refused connections and the NRB Financial Stability Report 2024/25 does not state the per-depositor limit; only a non-official directory page gives Rs 500,000.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NP', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Recurring deposit rates appear only in individual banks'' rate notices; no regulator or statistics-office figure found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NP', 1, 'equity_return_base', 0.06, NULL, 'assumption', 'Nepal Rastra Bank, Current Macroeconomic and Financial Situation (two months of 2026/27): NEPSE index; after-tax weighted average deposit rate about 2.9%', 'https://www.nrb.org.np/contents/uploads/2026/10/Current-Macroeconomic-and-Financial-Situation-English-Based-on-Two-Months-data-of-2026.27.pdf', '2026-10-31', 'Set below the after-tax safe rate plus 4 points because the NEPSE 10-year record (about 3% a year in price plus dividends) is weak.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NP', 1, 'equity_return_high', 0.1, NULL, 'assumption', 'Nepal Rastra Bank, Current Macroeconomic and Financial Situation (two months of 2026/27): NEPSE index; nominal GDP growth', 'https://www.nrb.org.np/contents/uploads/2026/10/Current-Macroeconomic-and-Financial-Situation-English-Based-on-Two-Months-data-of-2026.27.pdf', '2026-10-31', 'Upper case if earnings follow nominal GDP growth of around 9 to 10%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NP', 1, 'equity_return_low', 0.02, NULL, 'assumption', 'Nepal Rastra Bank, Current Macroeconomic and Financial Situation (two months of 2026/27): NEPSE index 2,612 in mid-September 2026 versus 2,672 a year earlier', 'https://www.nrb.org.np/contents/uploads/2026/10/Current-Macroeconomic-and-Financial-Situation-English-Based-on-Two-Months-data-of-2026.27.pdf', '2026-10-31', 'NEPSE was about 1,800 to 1,900 in 2016 and 2,612 in September 2026, roughly 3% a year in price with large swings, so the low case is near zero real return.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NP', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Only individual banks'' published rate notices give 1-year fixed deposit rates (about 3.0% to 3.2% in Bhadra 2083); Nepal Rastra Bank publishes only a weighted average on all outstanding fixed deposits (5.11%, April 2026), which is not term-specific.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NP', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Only individual banks'' published rate notices give 3-month fixed deposit rates (about 2.8% to 2.9% in Bhadra to Ashwin 2083); Nepal Rastra Bank publishes only a weighted average on all outstanding fixed deposits (5.11%, April 2026), which is not term-specific.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NP', 1, 'fixed_income_return_base', 0.035, NULL, 'assumption', 'Commercial bank deposit rates (weighted average 3.11%, outstanding fixed deposits 5.11%) and Citizen Savings Bond 6.5%, after 6% tax', 'https://www.nrb.org.np/cmfm_rates/lending_rates', '2026-10-31', 'Base case: a ladder of term deposits with some savings bonds when issued.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NP', 1, 'fixed_income_return_high', 0.055, NULL, 'assumption', 'Citizen Savings Bond 6.5% less 6% tax', 'https://risingnepaldaily.com/news/71169', '2026-10-31', 'High case: mostly savings bonds and long deposits bought at current rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NP', 1, 'fixed_income_return_low', 0.025, NULL, 'assumption', 'Weighted average deposit rate of commercial banks 3.11% (mid-September 2026) less 6% withholding', 'https://www.nrb.org.np/contents/uploads/2026/10/Current-Macroeconomic-and-Financial-Situation-English-Based-on-Two-Months-data-of-2026.27.pdf', '2026-10-31', 'Low case: short deposits after 6% tax, about 2.5% to 2.9%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NP', 1, 'goal_inflation_education', 0.08, NULL, 'assumption', 'Nepal CPI and 5.5% inflation target', 'https://www.nrb.org.np/contents/uploads/2026/10/Current-Macroeconomic-and-Financial-Situation-English-Based-on-Two-Months-data-of-2026.27.pdf', '2026-10-31', 'Private school and college fees have risen faster than headline CPI, so we add 2.5 points to the target.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NP', 1, 'goal_inflation_health', 0.07, NULL, 'assumption', 'Nepal CPI (non-food and services 5.7%) and 5.5% inflation target', 'https://www.nrb.org.np/contents/uploads/2026/10/Current-Macroeconomic-and-Financial-Situation-English-Based-on-Two-Months-data-of-2026.27.pdf', '2026-10-31', 'Medical costs usually rise faster than headline CPI, so we add 1.5 points to the target.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NP', 1, 'gold_return_base', 0.07, NULL, 'assumption', 'Dollar gold long-run trend plus rupee depreciation through the INR peg', 'https://www.nrb.org.np/contents/uploads/2026/10/Current-Macroeconomic-and-Financial-Situation-English-Based-on-Two-Months-data-of-2026.27.pdf', '2026-10-31', 'About 4% dollar gold trend plus about 3% expected rupee depreciation against the dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NP', 1, 'gold_return_high', 0.11, NULL, 'assumption', 'Dollar gold long-run trend plus rupee depreciation', 'https://www.nrb.org.np/contents/uploads/2026/10/Current-Macroeconomic-and-Financial-Situation-English-Based-on-Two-Months-data-of-2026.27.pdf', '2026-10-31', 'High case with strong dollar gold and faster rupee depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NP', 1, 'gold_return_low', 0.02, NULL, 'assumption', 'Rupee pegged to the Indian rupee; dollar gold long-run trend', 'https://www.nrb.org.np/contents/uploads/2026/10/Current-Macroeconomic-and-Financial-Situation-English-Based-on-Two-Months-data-of-2026.27.pdf', '2026-10-31', 'Low case: flat dollar gold with mild rupee depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NP', 1, 'gratuity_rule', NULL, '{"daysPerYear":30,"daysPerYearAfter":null,"afterYears":null,"daysPerMonth":30}', 'sourced', 'Labour Act 2074, section 53 (copy published by the Social Security Fund)', 'https://ssf.gov.np/images/news/16430171669623_labor-act-2074.pdf', '2017-09-04', 'Employers must deposit 8.33% of basic remuneration every month as gratuity, which is one month (30 days) per year of service; for enrolled employees it goes into the Social Security Fund. Act of 2017, older than 2025 but still in force.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NP', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched for published typical private hospital stay costs in Nepal; none found from a credible source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NP', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched for published private health insurance premiums by age; none found. The public Health Insurance Board scheme charges a family premium instead.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NP', 1, 'inflation_cpi', 0.0634, NULL, 'sourced', 'Nepal Rastra Bank, Current Macroeconomic and Financial Situation (two months of 2026/27)', 'https://www.nrb.org.np/contents/uploads/2026/10/Current-Macroeconomic-and-Financial-Situation-English-Based-on-Two-Months-data-of-2026.27.pdf', '2026-09-16', 'Year-on-year CPI, mid-September 2026; food 7.54%, non-food and services 5.69%', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NP', 1, 'inflation_projection', 0.055, NULL, 'assumption', 'Nepal Rastra Bank inflation target for 2026/27 (around 5.5%); recent CPI 1.9% to 6.3%', 'https://risingnepaldaily.com/news/83134', '2026-10-31', 'The central bank''s 5.5% target sits close to the 5-year CPI average, so we plan with it.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NP', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life plans are sold in Nepal but no published premium rates or regulator premium data were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NP', 1, 'life_claim_settlement_rate', 0.81, NULL, 'sourced', 'Beema Post (Nepal Insurance Authority data, first 11 months of FY 2082/83)', 'https://en.beemapost.com/?p=13949', '2026-06-15', 'Life insurers paid 265,204 claims (Rs 66.42 bn) with 60,954 pending (Rs 0.55 bn): 81% by number, 99% by amount', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NP', 1, 'life_expectancy', 70.6, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN (UN WPP)', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=NP', '2024-12-31', 'Men 69.1, women 72.1', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NP', 1, 'life_table_remaining', NULL, '{"rows":[{"age":65,"total":14,"men":13.2,"women":14.7,"projected":16.3},{"age":80,"total":5.9,"men":5.6,"women":6.1,"projected":7}]}', 'sourced', 'UN World Population Prospects 2024 (via Our World in Data)', 'https://ourworldindata.org/grapher/remaining-life-expectancy-at-different-ages?country=~NPL', '2025-07-01', '2025 estimates; projected = 2050 medium variant; ages 60 and 70 not published in this series', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NP', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":70,"womenAge":70,"over90Monthly":null,"meansTested":false}', 'sourced', 'The Rising Nepal (senior citizens'' allowance)', 'https://risingnepaldaily.com/news/78466', '2026-04-09', 'Age 60 for Dalits and residents of the Karnali region; categorical, no means test', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NP', 1, 'old_age_allowance_monthly', 4000, NULL, 'sourced', 'The Rising Nepal (senior citizens'' allowance)', 'https://risingnepaldaily.com/news/78466', '2026-04-09', 'Social security allowance for senior citizens; universal, not means-tested', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NP', 1, 'oop_health_share', 0.594, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=NP', '2023-12-31', NULL, 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NP', 1, 'policy_rate', 0.0425, NULL, 'sourced', 'Nepal Rastra Bank, NRB Policy Rates', 'https://www.nrb.org.np/cmfm_rates/policy_rates', '2025-12-02', 'Policy (overnight repo) rate 4.25% since 2 December 2025, still shown as current on the NRB page in November 2026; standing deposit facility 2.75%, standing liquidity facility 5.75%. A Rising Nepal report on the 2026/27 monetary policy says 4.50%, which does not match the NRB page.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NP', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":60,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'Social Security Fund, Social Security Operation Procedure 2075 (5th amendment 2081)', 'https://ssf.gov.np/list/act_regulation/social-security-operation-procedure-2075-with-5th-ammendment', '2024-12-25', 'Contribution-based: employee 11% plus employer 20% of basic salary (31%), of which 28.33% goes to the old-age protection scheme; pension from 60 after 180 months of contributions. Procedure amended December 2024, older than 2025 but still in force.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NP', 1, 'retirement_accumulation_return_base', 0.045, NULL, 'assumption', 'Balanced mix: half safe fixed income (3.5%), half equity (6%)', 'https://www.nrb.org.np/contents/uploads/2026/10/Current-Macroeconomic-and-Financial-Situation-English-Based-on-Two-Months-data-of-2026.27.pdf', '2026-10-31', 'Average of the base fixed-income and equity cases.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NP', 1, 'retirement_accumulation_return_high', 0.07, NULL, 'assumption', 'Balanced mix with higher equity returns', 'https://www.nrb.org.np/contents/uploads/2026/10/Current-Macroeconomic-and-Financial-Situation-English-Based-on-Two-Months-data-of-2026.27.pdf', '2026-10-31', 'High case for a balanced mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NP', 1, 'retirement_accumulation_return_low', 0.03, NULL, 'assumption', 'Balanced mix of deposits and NEPSE equity', 'https://www.nrb.org.np/contents/uploads/2026/10/Current-Macroeconomic-and-Financial-Situation-English-Based-on-Two-Months-data-of-2026.27.pdf', '2026-10-31', 'Low case for a balanced mix while rates stay low.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NP', 1, 'retirement_age_default', 60, NULL, 'sourced', 'Social Security Fund, Social Security Operation Procedure 2075 (5th amendment 2081)', 'https://ssf.gov.np/list/act_regulation/social-security-operation-procedure-2075-with-5th-ammendment', '2024-12-25', 'Old-age pension from age 60 after at least 180 months of contributions, same for men and women; procedure amended 2081/09/10 (25 December 2024), older than 2025 but still in force.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NP', 1, 'retirement_age_government', 58, NULL, 'sourced', 'The Kathmandu Post (Civil Service Act 2049, section 33)', 'https://kathmandupost.com/national/2026/10/02/federal-civil-service-bill-reaches-parliament-ten-years-after-federalism', '2026-10-02', 'Federal Civil Service Bill before parliament would raise it to 60', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NP', 1, 'retirement_return_base', 0.029, NULL, 'assumption', 'Weighted average deposit rate of commercial banks 3.11% (mid-September 2026) less 6% withholding = 2.92%', 'https://www.nrb.org.np/contents/uploads/2026/10/Current-Macroeconomic-and-Financial-Situation-English-Based-on-Two-Months-data-of-2026.27.pdf', '2026-10-31', 'Kept at about the after-tax average deposit rate; the 91-day treasury bill (1.35%) is lower but is bought mostly by banks.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NP', 1, 'retirement_return_high', 0.045, NULL, 'assumption', 'Outstanding fixed deposits (5.11% weighted average) and Citizen Savings Bond 6.5%, after 6% tax', 'https://www.nrb.org.np/cmfm_rates/lending_rates', '2026-10-31', 'High case using longer deposits and savings bonds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NP', 1, 'retirement_return_low', 0.025, NULL, 'assumption', 'Weighted average deposit rate 3.11% less 6% withholding', 'https://www.nrb.org.np/contents/uploads/2026/10/Current-Macroeconomic-and-Financial-Situation-English-Based-on-Two-Months-data-of-2026.27.pdf', '2026-10-31', 'Low case: short deposits only.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NP', 1, 'sanchayapatra_5y_rate', 0.065, NULL, 'sourced', 'The Rising Nepal (Citizen Savings Bond 2087 issue by Nepal Rastra Bank)', 'https://risingnepaldaily.com/news/71169', '2025-11-15', 'Citizen Savings Bond 2087, 5 years, interest paid half-yearly, minimum Rs 10,000; Foreign Employment Savings Bond 7.5%. Issued in tranches, not on tap', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NP', 1, 'savings_account_rate', 0.0292, NULL, 'sourced', 'Nepal Rastra Bank, Deposit/Lending Rates (weighted average saving deposit rate)', 'https://www.nrb.org.np/cmfm_rates/lending_rates', '2026-04-06', 'Weighted average rate on saving deposits, last updated 6 April 2026; the overall weighted average deposit rate of commercial banks fell from 3.45% to 3.11% by mid-September 2026, so current savings rates may be slightly lower.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NP', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":9.9},{"year":2040,"value":8},{"year":2065,"value":3.9}]}', 'sourced', 'UN World Population Prospects 2024 old-age dependency ratio (via Our World in Data)', 'https://ourworldindata.org/grapher/age-dependency-ratio-old?country=~NPL', '2025-07-01', '100 / old-age dependency ratio (10.1 in 2025, 12.5 in 2040, 25.5 in 2065, medium variant)', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NP', 1, 'tax_bank_interest', 0.06, NULL, 'sourced', 'Income Tax Act 2058, section 88(3) (via nepallaws.com)', 'https://nepallaws.com/Laws/income-tax-act-2058-2002/chapter-17-withholding-on-payment/section-88-withholding-of-tax-in-making-payment-for-investment-return-and-service-charge/', '2025-05-05', '6% withholding on interest paid to natural persons on deposits, not related to business; final withholding', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NP', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched issue notices for Citizen Savings Bonds 2086 and 2087; they do not state the tax on the interest.', 0);
