INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('NR', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"NR","iso3":"NRU","nameEn":"Nauru","nameNative":"Naoero","region":"east_asia_pacific","languages":["na","en"],"currency":{"code":"AUD","symbol":"$","decimals":2,"compact":"intl","usdRate":{"value":1.4223,"status":"sourced","sourceName":"Trading Economics, AUD/USD exchange rate","sourceUrl":"https://tradingeconomics.com/australia/currency","asOf":"2026-10-30","note":"AUD 1 = USD 0.7031, so about AUD 1.42 per US dollar; World Bank 2025 average 1.552. Nauru uses the Australian dollar."}},"instruments":{"savings_account":{"available":true,"localName":null,"localNameEn":"Savings account","note":"Basic and saver accounts offered through the single bank agency that opened in August 2025."},"fdr_3m":{"available":false,"localName":null,"note":"No term deposits were found to be offered to Nauru customers."},"fdr_1y":{"available":false,"localName":null,"note":"No term deposits were found to be offered to Nauru customers."},"dps":{"available":false,"localName":null},"sanchayapatra_5y":{"available":false,"localName":null,"note":"No government savings certificates or retail bonds."},"tbill_91d":{"available":false,"localName":null,"note":"The government issues no domestic securities.","sourceUrl":"https://naurufinance.info/wp-content/uploads/2026/08/BP1_Final_Jul_26_22.07_Website-1.pdf"},"tbond_5y":{"available":false,"localName":null,"sourceUrl":"https://naurufinance.info/wp-content/uploads/2026/08/BP1_Final_Jul_26_22.07_Website-1.pdf"},"tbond_10y":{"available":false,"localName":null,"sourceUrl":"https://naurufinance.info/wp-content/uploads/2026/08/BP1_Final_Jul_26_22.07_Website-1.pdf"},"equity_fund":{"available":false,"localName":null,"note":"No local stock exchange or locally sold funds; residents would have to invest abroad."},"gold":{"available":false,"localName":null,"note":"No local gold bullion dealer was found; no legal restriction is known."}},"institutions":{"centralBank":{"name":"Reserve Bank of Australia (Nauru uses the Australian dollar and has no central bank)","url":"https://www.rba.gov.au/"},"insuranceRegulator":null,"insuranceComplaints":null,"pensionScheme":{"name":"Nauru Superannuation Scheme (Ministry of Finance)","url":"https://naurufinance.info/superannuation-arrangements/"},"oldAgeAllowance":{"name":"Aged Pension, Social Welfare Division (Ministry of Finance)","url":"https://naurufinance.info/social-welfare-division/"},"publicHealthCover":null,"depositInsurance":null,"statistics":{"name":"Nauru Bureau of Statistics","url":"https://stats.gov.nr/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NR', 1, 'bank_deposit_avg_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No deposit rate statistics are published for Nauru (no central bank; World Bank FR.INR.DPST has no Nauru data).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NR', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No credit card products or rate cap for Nauru were found; the bank agency on the island lists only debit cards.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NR', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No Nauru deposit insurance scheme was found; whether Australia''s Financial Claims Scheme covers deposits taken through the Australian bank''s Nauru agency is not stated by APRA or the Ministry of Finance pages read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NR', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No monthly recurring deposit product exists in Nauru.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NR', 1, 'equity_return_base', 0.045, NULL, 'assumption', 'No local stock market; global equity index in AUD terms, capped at the assumed local safe rate (about 0.5%) plus 4 points; RBA cash rate 4.60%', 'https://tradingeconomics.com/australia/interest-rate', '2026-10-31', 'No local exchange exists, so base equity is a global index in AUD, held to the safe rate (about 0.5%) plus 4 points.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NR', 1, 'equity_return_high', 0.08, NULL, 'assumption', 'No local stock market; global equity index in AUD terms, capped at the assumed local safe rate (about 0.5%) plus 4 points; RBA cash rate 4.60%', 'https://tradingeconomics.com/australia/interest-rate', '2026-10-31', 'High case near the long-run return of global shares in Australian dollars.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NR', 1, 'equity_return_low', 0.02, NULL, 'assumption', 'No local stock market; global equity index in AUD terms, capped at the assumed local safe rate (about 0.5%) plus 4 points; RBA cash rate 4.60%', 'https://tradingeconomics.com/australia/interest-rate', '2026-10-31', 'Low case for a global index fund held from Nauru in Australian dollars after a weak decade.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NR', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No term deposits were found to be offered to Nauru customers by the single bank agency on the island; no rate is published.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NR', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No term deposits were found to be offered to Nauru customers by the single bank agency on the island; no rate is published.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NR', 1, 'fixed_income_return_base', 0.005, NULL, 'assumption', 'RBA cash rate 4.60% (AUD ceiling); no local term deposits or government securities, so local savings are assumed to earn little', 'https://tradingeconomics.com/australia/interest-rate', '2026-10-31', 'Base case: a saver account at a low rate; no term deposits or government paper are sold locally.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NR', 1, 'fixed_income_return_high', 0.02, NULL, 'assumption', 'RBA cash rate 4.60% (AUD ceiling); no local term deposits or government securities, so local savings are assumed to earn little', 'https://tradingeconomics.com/australia/interest-rate', '2026-10-31', 'High case: a saver account with bonus interest, if available to Nauru customers.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NR', 1, 'fixed_income_return_low', 0, NULL, 'assumption', 'RBA cash rate 4.60% (AUD ceiling); no local term deposits or government securities, so local savings are assumed to earn little', 'https://tradingeconomics.com/australia/interest-rate', '2026-10-31', 'Low case: cash held in a basic account earning nothing.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NR', 1, 'goal_inflation_education', 0.035, NULL, 'assumption', 'Nauru Bureau of Statistics CPI (4.4% to March 2025)', 'https://stats.gov.nr/2026/06/10/consumer-price-index-march-2025/', '2026-10-31', 'No education price index is published; the headline projection is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NR', 1, 'goal_inflation_health', 0.035, NULL, 'assumption', 'Nauru Bureau of Statistics CPI (4.4% to March 2025); free public health care', 'https://stats.gov.nr/2026/06/10/consumer-price-index-march-2025/', '2026-10-31', 'Care is free for citizens, so health costs to plan for move with general prices; the headline projection is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NR', 1, 'gold_return_base', 0.05, NULL, 'assumption', 'AUD/USD 0.703 (30 Oct 2026); World Bank AUD per USD 1.55 in 2025', 'https://tradingeconomics.com/australia/currency', '2026-10-31', 'Long-run dollar gold trend of about 4-5% plus little expected AUD depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NR', 1, 'gold_return_high', 0.08, NULL, 'assumption', 'AUD/USD 0.703 (30 Oct 2026); World Bank AUD per USD 1.55 in 2025', 'https://tradingeconomics.com/australia/currency', '2026-10-31', 'High case with strong dollar gold and a weaker Australian dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NR', 1, 'gold_return_low', 0.02, NULL, 'assumption', 'AUD/USD 0.703 (30 Oct 2026); World Bank AUD per USD 1.55 in 2025', 'https://tradingeconomics.com/australia/currency', '2026-10-31', 'Low case: weak dollar gold price and a stronger Australian dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NR', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No statutory gratuity or end-of-service benefit for private employees was found for Nauru.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NR', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'Public health care is free for citizens at the Republic of Nauru Hospital, with referral to Australia; no private hospital cost data exists.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NR', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No private health insurance market was found in Nauru.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NR', 1, 'inflation_cpi', 0.044, NULL, 'sourced', 'Nauru Bureau of Statistics, CPI March 2025 quarter', 'https://stats.gov.nr/2026/06/10/consumer-price-index-march-2025/', '2025-03-31', 'CPI up 4.4% in the year to March 2025 (latest release, published June 2026; the figure is 19 months old). The 2026-27 Budget Paper 1 (IMF WEO April 2026) gives period-average inflation of 6.1% for 2024-25 and 5.5% for 2025-26.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NR', 1, 'inflation_projection', 0.035, NULL, 'assumption', '2026-27 Budget Paper 1 (IMF WEO April 2026): CPI 4.2% for 2026-27; IMF WEO path 5.7% (2026) to 2.5% by 2030', 'https://naurufinance.info/wp-content/uploads/2026/08/BP1_Final_Jul_26_22.07_Website-1.pdf', '2026-10-31', 'IMF WEO projects 5.7% (2026), 4.3% (2027), then 3.4%, 2.7% and 2.5% by 2030; as an AUD user that imports almost everything, Nauru should settle toward Australia''s 2-3% band plus import-cost shocks, so 3.5% is used for long-run planning.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NR', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No local term life insurance market was found in Nauru.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NR', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No insurance regulator or published life insurance claims data exists for Nauru.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NR', 1, 'life_expectancy', 62.279, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=NR', '2024-12-31', '2024 figure, the latest World Bank year (older than 2025). Men 60.4, women 64.2.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NR', 1, 'life_table_remaining', NULL, NULL, 'missing', '', '', '2026-10-31', 'UN WPP life tables are not published on the secondary sites read for Nauru (populationpyramid.net has no Nauru page) and WHO GHO does not cover it.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NR', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":60,"womenAge":60,"over90Monthly":null,"meansTested":false}', 'sourced', 'Nauru Ministry of Finance, Social Welfare Division (Aged Pension)', 'https://naurufinance.info/social-welfare-division/', '2026-10-31', 'Residents over 60, living in Nauru; not means tested, but people with another regular income such as a job are not eligible. Higher rates from 70 and 75.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NR', 1, 'old_age_allowance_monthly', 867, NULL, 'sourced', 'Government of Naoero, 2026-27 Budget Speech (revised aged pension rates)', 'https://naurufinance.info/wp-content/uploads/2026/07/APPROPRIATION-BILL-2026-SRS_V07.pdf', '2026-07-20', 'Aged pension AUD 400 at 60-69, 500 at 70-74 and 600 at 75+ (revised in 2025, confirmed for 2026-27 in the Budget Speech; Budget Paper 1 also lists $400-$600 by age). The speech does not give the period; the Social Welfare Division page lists the earlier rates (250/300) as fortnightly and payments are made fortnightly, so 400 a fortnight x 26 / 12 = about 867 a month for age 60-69. Not paid to people with a job or other regular income.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NR', 1, 'oop_health_share', 0.0073, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=NR', '2023-12-31', '2023 figure, the latest World Bank year (older than 2025). Out-of-pocket spending is 0.73% of current health expenditure; care is free for citizens.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NR', 1, 'policy_rate', 0.046, NULL, 'sourced', 'Trading Economics (Reserve Bank of Australia cash rate target)', 'https://tradingeconomics.com/australia/interest-rate', '2026-09-29', 'Nauru has no central bank and uses the Australian dollar; the RBA cash rate target (raised to 4.60% on 29 September 2026) is the policy rate for its currency. It was raised again to 4.85% on 3 November 2026, after this date.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NR', 1, 'public_pension_scheme', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Nauru Superannuation Scheme is a mandatory defined-contribution fund (employer 10% from 1 February 2026, employee 5%), not a pension; the Ministry of Finance page does not state its withdrawal age or payout rules.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NR', 1, 'retirement_accumulation_return_base', 0.03, NULL, 'assumption', 'No local market; balanced mix of a global equity index in AUD and local cash; RBA cash rate 4.60%', 'https://tradingeconomics.com/australia/interest-rate', '2026-10-31', 'Base case: half global shares at 4.5% and half cash at 0.5-1%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NR', 1, 'retirement_accumulation_return_high', 0.05, NULL, 'assumption', 'No local market; balanced mix of a global equity index in AUD and local cash; RBA cash rate 4.60%', 'https://tradingeconomics.com/australia/interest-rate', '2026-10-31', 'High case for a growth-leaning global mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NR', 1, 'retirement_accumulation_return_low', 0.02, NULL, 'assumption', 'No local market; balanced mix of a global equity index in AUD and local cash; RBA cash rate 4.60%', 'https://tradingeconomics.com/australia/interest-rate', '2026-10-31', 'Low case for a balanced mix of global shares and cash.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NR', 1, 'retirement_age_default', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Nauru Superannuation Scheme page does not state a withdrawal or retirement age, and no statutory retirement age was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NR', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'No public service retirement age for Nauru was found on the Ministry of Finance site.', 0);
