INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('NZ', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"NZ","iso3":"NZL","nameEn":"New Zealand","nameNative":"New Zealand","region":"east_asia_pacific","languages":["en","mi"],"currency":{"code":"NZD","symbol":"$","decimals":2,"compact":"intl","usdRate":{"value":1.7765,"status":"sourced","sourceName":"Trading Economics, NZD/USD exchange rate","sourceUrl":"https://tradingeconomics.com/new-zealand/currency","asOf":"2026-10-30","note":"NZD 1 = USD 0.5629, so about NZD 1.78 per US dollar; World Bank 2025 average 1.72."}},"instruments":{"savings_account":{"available":true,"localName":"Savings account","localNameEn":"Savings (call) account"},"fdr_3m":{"available":true,"localName":"Term deposit","localNameEn":"3-month term deposit"},"fdr_1y":{"available":true,"localName":"Term deposit","localNameEn":"1-year term deposit"},"dps":{"available":false,"localName":null,"note":"No monthly recurring deposit product; KiwiSaver and savings accounts fill this role."},"sanchayapatra_5y":{"available":true,"localName":"Kiwi Bonds","localNameEn":"Kiwi Bonds (retail government bonds)","note":"Sold to individuals by New Zealand Debt Management for 6 months to 4 years; interest taxable."},"tbill_91d":{"available":true,"localName":"Treasury bill","localNameEn":"New Zealand Government Treasury bill","note":"Sold by tender, mainly to institutions.","sourceUrl":"https://tradingeconomics.com/new-zealand/3-month-bill-yield"},"tbond_5y":{"available":true,"localName":"New Zealand Government Bond","localNameEn":"Nominal government bond"},"tbond_10y":{"available":true,"localName":"New Zealand Government Bond","localNameEn":"Nominal government bond","sourceUrl":"https://tradingeconomics.com/new-zealand/government-bond-yield"},"equity_fund":{"available":true,"localName":"Managed fund","localNameEn":"Managed fund / KiwiSaver fund / index fund","note":"Retail index and managed funds (many as PIEs taxed at 10.5-28%) are widely available."},"gold":{"available":true,"localName":"Gold bullion","localNameEn":"Gold bars and coins","note":"No restriction on buying physical gold."}},"institutions":{"centralBank":{"name":"Reserve Bank of New Zealand – Te Pūtea Matua","url":"https://www.rbnz.govt.nz/"},"insuranceRegulator":{"name":"Reserve Bank of New Zealand (insurer prudential supervision); Financial Markets Authority (conduct)","url":"https://www.rbnz.govt.nz/regulation-and-supervision/insurers"},"insuranceComplaints":{"name":"Insurance & Financial Services Ombudsman","url":"https://www.ifso.nz/"},"pensionScheme":{"name":"NZ Superannuation (Work and Income)","url":"https://www.workandincome.govt.nz/products/a-z-benefits/nz-superannuation.html"},"oldAgeAllowance":{"name":"NZ Superannuation (universal, non-contributory)","url":"https://www.workandincome.govt.nz/products/a-z-benefits/nz-superannuation.html"},"publicHealthCover":{"name":"Health New Zealand – Te Whatu Ora (free public hospital care)","url":"https://www.healthnz.govt.nz/"},"depositInsurance":{"name":"Depositor Compensation Scheme (Reserve Bank of New Zealand)","url":"https://www.rbnz.govt.nz/regulation-and-supervision/depositor-compensation-scheme"},"statistics":{"name":"Stats NZ – Tatauranga Aotearoa","url":"https://www.stats.govt.nz/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NZ', 1, 'bank_deposit_avg_rate', 0.03945, NULL, 'sourced', 'World Bank WDI FR.INR.DPST (deposit interest rate)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=NZ', '2025-12-31', 'Trading Economics shows an RBNZ deposit rate series at 4.79% for September 2026, which looks like a term-deposit series rather than an all-deposit average.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NZ', 1, 'credit_card_rate_cap', 0.2095, NULL, 'sourced', 'interest.co.nz (financial news site) credit card rate table', 'https://www.interest.co.nz/borrowing/credit-cards', '2026-10-31', 'No legal cap; 20.95% is the most common standard purchase rate at major banks (low-rate cards 12.9-13.9%). Source is a financial news site''s rate table (RBNZ retail rate tables refused automated access).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NZ', 1, 'deposit_insurance_limit', 100000, NULL, 'sourced', 'Wikipedia, Deposit insurance (New Zealand Depositor Compensation Scheme)', 'https://en.wikipedia.org/wiki/Deposit_insurance', '2025-07-01', 'Depositor Compensation Scheme under the Deposit Takers Act 2023: NZD 100,000 per depositor per licensed deposit taker from 1 July 2025; secondary source because rbnz.govt.nz refused automated access.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NZ', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'New Zealand banks do not offer a monthly recurring deposit (DPS-style) product; regular saving is done through savings accounts and KiwiSaver.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NZ', 1, 'equity_return_base', 0.065, NULL, 'assumption', 'Major-bank 1-year term deposit 4.0% less 30% RWT = 2.8%; NZX 50 gross index', 'https://www.interest.co.nz/saving/term-deposits-1-to-5-years', '2026-10-31', 'After-tax safe rate of 2.8% plus a 3.7-point premium, kept under 4 points because the NZX 50 has been flat recently.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NZ', 1, 'equity_return_high', 0.085, NULL, 'assumption', 'NZX 50 gross index long-run record (base 1,880.85 in Dec 2000 to 13,797 in Oct 2026)', 'https://tradingeconomics.com/new-zealand/stock-market', '2026-10-31', 'High case near the NZX 50 gross index''s roughly 8% a year since 2000.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NZ', 1, 'equity_return_low', 0.035, NULL, 'assumption', 'NZX 50 gross index 13,797 (30 Oct 2026), up 1.8% in a year', 'https://tradingeconomics.com/new-zealand/stock-market', '2026-10-31', 'Low case after a weak few years for the NZX 50, roughly the after-tax term deposit rate plus a small premium.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NZ', 1, 'fdr_1y_rate', 0.0403, NULL, 'sourced', 'interest.co.nz (financial news site) term deposit rate table (1-5 years)', 'https://www.interest.co.nz/saving/term-deposits-1-to-5-years', '2026-10-31', 'Major banks'' 1-year rates 4.00-4.05%; 5-year 4.70-5.00%. Table date not shown; read 31 October 2026. Source is a financial news site''s rate table (RBNZ retail rate tables refused automated access).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NZ', 1, 'fdr_3m_rate', 0.0295, NULL, 'sourced', 'interest.co.nz (financial news site) term deposit rate table (under 1 year)', 'https://www.interest.co.nz/saving/term-deposits-1-to-9-months', '2026-10-31', 'Major banks'' 3-month rates 2.85-3.05%; midpoint used. Table date not shown; read 31 October 2026. Source is a financial news site''s rate table (RBNZ retail rate tables refused automated access).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NZ', 1, 'fixed_income_return_base', 0.028, NULL, 'assumption', 'Major-bank 1-year term deposit 4.0% less 30% RWT = 2.8%', 'https://www.interest.co.nz/saving/term-deposits-1-to-5-years', '2026-10-31', 'Base case: 1-year term deposits after 30% resident withholding tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NZ', 1, 'fixed_income_return_high', 0.034, NULL, 'assumption', 'Major-bank 5-year term deposit 4.70-5.00% less 30% RWT', 'https://www.interest.co.nz/saving/term-deposits-1-to-5-years', '2026-10-31', 'High case: locking in 5-year term deposits after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NZ', 1, 'fixed_income_return_low', 0.02, NULL, 'assumption', 'Major-bank 3-month term deposit 2.95% less 30% RWT', 'https://www.interest.co.nz/saving/term-deposits-1-to-9-months', '2026-10-31', 'Low case: rolling short term deposits after 30% tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NZ', 1, 'goal_inflation_education', 0.035, NULL, 'assumption', 'RBNZ 1-3% target; headline CPI 3.7% (Q3 2026)', 'https://tradingeconomics.com/new-zealand/inflation-cpi', '2026-10-31', 'The Stats NZ education group figure could not be read, so we plan with the headline projection plus one point for fees.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NZ', 1, 'goal_inflation_health', 0.035, NULL, 'assumption', 'RBNZ 1-3% target; headline CPI 3.7% (Q3 2026)', 'https://tradingeconomics.com/new-zealand/inflation-cpi', '2026-10-31', 'The Stats NZ health group figure could not be read, so we plan with the headline projection plus one point for private medical costs.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NZ', 1, 'gold_return_base', 0.055, NULL, 'assumption', 'World Bank PA.NUS.FCRF (NZD per USD 1.72 in 2025); NZD/USD 0.563 on 30 Oct 2026', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=NZ', '2026-10-31', 'Long-run dollar gold trend of about 4-5% plus about 1% a year of NZD weakness against the dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NZ', 1, 'gold_return_high', 0.09, NULL, 'assumption', 'World Bank PA.NUS.FCRF (NZD per USD 1.72 in 2025); NZD/USD 0.563 on 30 Oct 2026', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=NZ', '2026-10-31', 'High case with strong dollar gold and a weaker NZD.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NZ', 1, 'gold_return_low', 0.02, NULL, 'assumption', 'World Bank PA.NUS.FCRF (NZD per USD 1.72 in 2025); NZD/USD 0.563 on 30 Oct 2026', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=NZ', '2026-10-31', 'Low case: weak dollar gold price and a stable or stronger New Zealand dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NZ', 1, 'gratuity_rule', NULL, NULL, 'missing', 'Employment New Zealand (MBIE), Redundancy', 'https://www.employment.govt.nz/ending-employment/redundancy', '2026-10-31', 'Confirmed absent: Employment New Zealand states an employer does not have to provide redundancy compensation unless it is in the employment agreement or policy; no statutory gratuity or end-of-service payment exists.', 1);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NZ', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical private hospital bill was found; public hospital care is free for residents.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NZ', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'NZ private health insurance is priced per plan with annual limits rather than per sum insured, and no age-banded premium table was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NZ', 1, 'inflation_cpi', 0.037, NULL, 'sourced', 'Trading Economics (Stats NZ CPI, September 2026 quarter)', 'https://tradingeconomics.com/new-zealand/inflation-cpi', '2026-09-30', 'Annual CPI 3.7% to the September 2026 quarter (4.1% to June); secondary source because the Stats NZ release page renders without figures.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NZ', 1, 'inflation_projection', 0.025, NULL, 'assumption', 'RBNZ 1-3% target (2% midpoint); CPI 3.7% in Q3 2026, 2.8% in 2025 (World Bank)', 'https://tradingeconomics.com/new-zealand/inflation-cpi', '2026-10-31', 'The 1-3% target is credible over the long run but inflation has run above the midpoint, so 2.5% is used for planning.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NZ', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life is widely sold in New Zealand, but no published per-1,000 premium table by age was found; insurers quote individually.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NZ', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No industry-wide life claim settlement ratio published by the RBNZ, FMA or the Financial Services Council was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NZ', 1, 'life_expectancy', 82.01, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=NZ', '2024-12-31', '2024 figure, the latest World Bank year (older than 2025). Men 80.4, women 83.7; UN WPP 2024 (via populationpyramid.net) gives 82.5 for 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NZ', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":25.2,"men":24.1,"women":26.3},{"age":65,"total":20.9,"men":19.9,"women":21.9},{"age":70,"total":16.8,"men":15.9,"women":17.7},{"age":80,"total":9.5,"men":8.9,"women":10.1}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/new-zealand/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant projection for 2026 (mid-year); totals at 60, 70 and 80 are the mean of men and women (the page publishes a total only at 65).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NZ', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":65,"womenAge":65,"over90Monthly":null,"meansTested":false}', 'sourced', 'Work and Income, NZ Super eligibility', 'https://www.workandincome.govt.nz/eligibility/seniors/superannuation', '2026-10-31', 'Universal from 65; the page says it does not depend on income or assets (the amount is taxable). Residence: citizen or permanent resident; the required years in NZ after age 20 are rising from 10 to 20 for people turning 65 from 1 July 2024 (Fair Residency amendment, phased in by birth year).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NZ', 1, 'old_age_allowance_monthly', 2805, NULL, 'sourced', 'Work and Income, benefit rates from 1 April 2026 (NZ Superannuation)', 'https://www.workandincome.govt.nz/products/benefit-rates/benefit-rates-april-2026.html', '2026-04-01', 'NZ Super, single living alone, NZD 647.37 a week gross (555.15 net at tax code M) = about 2,805 a month gross (x52/12); people in a couple get 492.14 a week each gross. Paid fortnightly.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NZ', 1, 'oop_health_share', 0.1269, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=NZ', '2024-12-31', '2024 figure, the latest World Bank year (older than 2025); public hospital care is free for residents.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NZ', 1, 'policy_rate', 0.0275, NULL, 'sourced', 'Trading Economics (RBNZ Official Cash Rate decision)', 'https://tradingeconomics.com/new-zealand/interest-rate', '2026-10-28', 'OCR held at 2.75% on 28 October 2026 (4-3 vote); secondary source because rbnz.govt.nz refused automated access. The market expects a hike at the next meeting.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NZ', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":65,"nomineeUntilAge":null,"inflationLinked":true,"taxFree":false}', 'sourced', 'Wikipedia, Superannuation in New Zealand; Work and Income NZ Super page', 'https://en.wikipedia.org/wiki/Superannuation_in_New_Zealand', '2026-07-13', 'NZ Super is the universal, tax-funded flat pension from 65 (no contributions, so no entry ages); it is the same benefit as old_age_allowance_monthly, so do not count it twice. Adjusted yearly with prices and held at 65-66% of the net average wage for a couple; taxable. KiwiSaver is the voluntary contributory savings scheme (lump sum from 65), not a pension. Secondary source for the indexation rule.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NZ', 1, 'retirement_accumulation_return_base', 0.05, NULL, 'assumption', 'Major-bank 1-year term deposit 4.0% less 30% RWT = 2.8%; NZX 50 gross index', 'https://www.interest.co.nz/saving/term-deposits-1-to-5-years', '2026-10-31', 'Base case: roughly half shares at 6.5% and half fixed income at about 3.5% pre-tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NZ', 1, 'retirement_accumulation_return_high', 0.065, NULL, 'assumption', 'Major-bank 1-year term deposit 4.0% less 30% RWT = 2.8%; NZX 50 gross index', 'https://www.interest.co.nz/saving/term-deposits-1-to-5-years', '2026-10-31', 'High case for a growth-leaning balanced mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NZ', 1, 'retirement_accumulation_return_low', 0.035, NULL, 'assumption', 'Major-bank 1-year term deposit 4.0% less 30% RWT = 2.8%; NZX 50 gross index', 'https://www.interest.co.nz/saving/term-deposits-1-to-5-years', '2026-10-31', 'Low case for a balanced KiwiSaver-style mix if shares lag.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NZ', 1, 'retirement_age_default', 65, NULL, 'sourced', 'Work and Income, NZ Super eligibility', 'https://www.workandincome.govt.nz/eligibility/seniors/superannuation', '2026-10-31', 'NZ Super is paid from 65 to men and women, including people born after 1975 under current law (the Work and Income eligibility page shows no legislated change to the age); there is no compulsory retirement age.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NZ', 1, 'retirement_age_government', 65, NULL, 'sourced', 'Wikipedia, Mandatory retirement (New Zealand)', 'https://en.wikipedia.org/wiki/Mandatory_retirement', '2026-10-31', 'No compulsory retirement age for public servants (only judges retire at 70); 65 is the normal retirement age because NZ Super starts then. Secondary source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NZ', 1, 'retirement_return_base', 0.028, NULL, 'assumption', 'Major-bank 1-year term deposit 4.0% less 30% RWT = 2.8%', 'https://www.interest.co.nz/saving/term-deposits-1-to-5-years', '2026-10-31', 'Base case capped at the after-tax 1-year term deposit rate.', 0);
