INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NZ', 1, 'retirement_return_low', 0.02, NULL, 'assumption', 'Major-bank 3-month term deposit 2.95% less 30% RWT', 'https://www.interest.co.nz/saving/term-deposits-1-to-9-months', '2026-10-31', 'Low case: short term deposits after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NZ', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Kiwi Bonds (retail government bonds, 6 months to 4 years) exist, but the Debt Management site refused automated access and no current rate was found elsewhere.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NZ', 1, 'savings_account_rate', 0.0015, NULL, 'sourced', 'interest.co.nz (financial news site) savings (call) account rate table', 'https://www.interest.co.nz/saving/call-account', '2026-10-31', 'Ordinary savings/call accounts at the large banks pay about 0.05-0.25% (online and bonus saver accounts 0.5-2.2%); 0.15% used. Read 31 October 2026. Source is a financial news site''s rate table (RBNZ retail rate tables refused automated access).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NZ', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":3.66},{"year":2040,"value":2.72},{"year":2065,"value":2.17}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/new-zealand/2040/', '2025-12-31', '100 / old-age dependency ratio: 27.3 (2025, World Bank), 36.7 (2040) and 46.0 (2065, populationpyramid.net/new-zealand/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NZ', 1, 'tax_bank_interest', 0.3, NULL, 'sourced', 'PwC Worldwide Tax Summaries, New Zealand personal income tax rates', 'https://taxsummaries.pwc.com/new-zealand/individual/taxes-on-personal-income', '2026-07-06', 'Interest is taxed at the saver''s marginal rate (10.5%, 17.5%, 30%, 33% or 39%) through resident withholding tax; 30% (income NZD 53,501-78,100) used as the typical earner rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NZ', 1, 'tax_sanchayapatra_profit', 0.3, NULL, 'sourced', 'PwC Worldwide Tax Summaries, New Zealand personal income tax rates', 'https://taxsummaries.pwc.com/new-zealand/individual/taxes-on-personal-income', '2026-07-06', 'Kiwi Bond interest is ordinary taxable interest at the marginal rate; 30% used as the typical rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NZ', 1, 'tbill_91d_rate', 0.032, NULL, 'sourced', 'Trading Economics, New Zealand 3-month bill yield', 'https://tradingeconomics.com/new-zealand/3-month-bill-yield', '2026-10-30', 'Secondary source; RBNZ wholesale rate tables refused automated access. 3.18% on 3 November 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NZ', 1, 'tbond_10y_rate', 0.0482, NULL, 'sourced', 'Trading Economics, New Zealand 10-year government bond yield', 'https://tradingeconomics.com/new-zealand/government-bond-yield', '2026-10-30', '2-year yield 3.75% the same day.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('NZ', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'RBNZ table B2 and the NZDM site refused automated access and no 5-year government bond yield was found on secondary sources read (the 2-year was 3.75% and the 10-year 4.82% on 30 Oct 2026).', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('OM', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"OM","iso3":"OMN","nameEn":"Oman","nameNative":"عُمان","region":"middle_east_north_africa","languages":["ar","en","bal","fa"],"currency":{"code":"OMR","symbol":"RO","decimals":3,"compact":"intl","usdRate":{"value":0.3845,"status":"sourced","sourceName":"World Bank WDI, official exchange rate (PA.NUS.FCRF), Oman","sourceUrl":"https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=OM","asOf":"2025-12-31","note":"The rial is pegged at 0.3845 per US dollar. CLDR gives no narrow symbol; ''RO'' (rial Omani) is the usual local abbreviation."}},"instruments":{"savings_account":{"available":true,"localName":"حساب التوفير","localNameEn":"Savings account"},"fdr_3m":{"available":true,"localName":"وديعة لأجل (3 أشهر)","localNameEn":"Time deposit (3 months)"},"fdr_1y":{"available":true,"localName":"وديعة لأجل (سنة)","localNameEn":"Time deposit (1 year)"},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No standard monthly recurring deposit product was found."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate for individuals was found."},"tbill_91d":{"available":true,"localName":"أذون الخزانة","localNameEn":"Treasury bills","note":"Issued by the Central Bank of Oman for the government, mainly to banks."},"tbond_5y":{"available":true,"localName":"سندات التنمية الحكومية","localNameEn":"Government development bonds","note":"Issued through the Central Bank of Oman and listed on the stock exchange; government sukuk are also issued."},"tbond_10y":{"available":true,"localName":"سندات التنمية الحكومية","localNameEn":"Government development bonds","note":"Long maturities are issued less often; mainly held by institutions."},"equity_fund":{"available":true,"localName":"صناديق الاستثمار","localNameEn":"Investment funds","note":"Supervised by the Financial Services Authority.","sourceUrl":"https://fsa.gov.om/"},"gold":{"available":true,"localName":"الذهب","localNameEn":"Gold","note":"Gold bars, coins and jewellery are freely sold."}},"institutions":{"centralBank":{"name":"Central Bank of Oman (CBO)","url":"https://cbo.gov.om/"},"insuranceRegulator":{"name":"Financial Services Authority (FSA), insurance sector","url":"https://fsa.gov.om/Sector/Index/2"},"insuranceComplaints":{"name":"Financial Services Authority, insurance complaint form","url":"https://e.fsa.gov.om/ServiceInsuranceComplaint?lang=en"},"pensionScheme":{"name":"Social Protection Fund, old-age pension","url":"https://gov.om/w/-get-old-age-pension"},"oldAgeAllowance":{"name":"Social Protection Fund, elderly benefit (منفعة كبار السن)","url":"https://gov.om/w/get-old-age-benefit"},"publicHealthCover":{"name":"Ministry of Health (public health care for citizens)","url":"https://www.moh.gov.om/"},"depositInsurance":{"name":"Bank Deposit Insurance Scheme, Central Bank of Oman","url":"https://cbo.gov.om/"},"statistics":{"name":"National Centre for Statistics and Information (NCSI)","url":"https://www.ncsi.gov.om/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('OM', 1, 'bank_deposit_avg_rate', 0.0415, NULL, 'sourced', 'World Bank WDI, deposit interest rate (FR.INR.DPST), Oman', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=OM', '2021-12-31', '4.15% for 2021, the latest year in the World Bank series (IMF data); older than 2025 and likely different now. The Central Bank of Oman website rejected automated access, so its statistical bulletin could not be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('OM', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap or average credit card rate could be read; the NCSI bulletin shows only the average rate on all bank credit (5.32% in August 2026). The Central Bank of Oman website rejected automated access, so its statistical bulletin could not be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('OM', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'Oman has a bank deposit insurance scheme run by the Central Bank of Oman, but its cover per depositor could not be read. The Central Bank of Oman website rejected automated access, so its statistical bulletin could not be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('OM', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No industry-wide rate for a monthly recurring deposit product was found. The Central Bank of Oman website rejected automated access, so its statistical bulletin could not be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('OM', 1, 'equity_return_base', 0.065, NULL, 'assumption', 'NCSI Monthly Statistical Bulletin, October 2026 (MSX 30 up 46% in a year); World Bank deposit rate 4.15%', 'https://api.ncsi.gov.om/uploads/pdfs/monthly_statistical_bulletin__october_2026_1792489912.pdf', '2026-10-31', 'Base case: about 3 points above the untaxed deposit rate, within the 4-point cap, because the MSX 30 had a weak 10-year record before its 2025-2026 rally.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('OM', 1, 'equity_return_high', 0.1, NULL, 'assumption', 'NCSI Monthly Statistical Bulletin, October 2026 (MSX 30 index)', 'https://api.ncsi.gov.om/uploads/pdfs/monthly_statistical_bulletin__october_2026_1792489912.pdf', '2026-10-31', 'High case: a stronger equity premium similar to other Gulf markets.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('OM', 1, 'equity_return_low', 0.03, NULL, 'assumption', 'NCSI Monthly Statistical Bulletin, October 2026 (MSX 30 index 7,566.8, end of September 2026)', 'https://api.ncsi.gov.om/uploads/pdfs/monthly_statistical_bulletin__october_2026_1792489912.pdf', '2026-10-31', 'Low case: the local market repeats its weak 2015-2023 decade and returns less than deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('OM', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No current industry-wide 1-year term deposit rate could be read. The Central Bank of Oman website rejected automated access, so its statistical bulletin could not be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('OM', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No current industry-wide 3-month term deposit rate could be read. The Central Bank of Oman website rejected automated access, so its statistical bulletin could not be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('OM', 1, 'fixed_income_return_base', 0.035, NULL, 'assumption', 'World Bank deposit rate (4.15%, 2021); repo rate 4.50% (September 2026)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=OM', '2026-10-31', 'Base case: a little below the last published average deposit rate, untaxed, because current term-deposit rates could not be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('OM', 1, 'fixed_income_return_high', 0.045, NULL, 'assumption', 'Repo rate 4.50% (September 2026)', 'https://tradingeconomics.com/oman/interest-rate', '2026-10-31', 'High case: savers who reach Treasury bill, development bond or sukuk returns near the policy rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('OM', 1, 'fixed_income_return_low', 0.025, NULL, 'assumption', 'World Bank deposit rate (4.15%, 2021); repo rate 4.50% (September 2026)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=OM', '2026-10-31', 'Low case: deposit rates fall with lower dollar rates; untaxed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('OM', 1, 'goal_inflation_education', 0.035, NULL, 'assumption', 'NCSI CPI September 2026: education group 2.2% year on year', 'https://api.ncsi.gov.om/uploads/pdfs/consumer_price_inflation__september_2026_1791889556.pdf', '2026-10-31', 'Education CPI is 2.2% now; private school fees usually rise faster than general prices, so 1.5 points above the 2% inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('OM', 1, 'goal_inflation_health', 0.035, NULL, 'assumption', 'NCSI CPI September 2026: health group 1.7% year on year', 'https://api.ncsi.gov.om/uploads/pdfs/consumer_price_inflation__september_2026_1791889556.pdf', '2026-10-31', 'Health CPI is 1.7% now, but private medical costs usually rise faster than general prices over time, so 1.5 points above the 2% inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('OM', 1, 'gold_return_base', 0.04, NULL, 'assumption', 'Dollar peg (0.3845 OMR per USD); long-run dollar gold trend', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=OM', '2026-10-31', 'Base case: the long-run dollar gold trend of about 4% a year, with no depreciation gain under the peg.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('OM', 1, 'gold_return_high', 0.08, NULL, 'assumption', 'Dollar peg (0.3845 OMR per USD); long-run dollar gold trend', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=OM', '2026-10-31', 'High case: strong dollar gold years.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('OM', 1, 'gold_return_low', 0, NULL, 'assumption', 'Dollar peg (0.3845 OMR per USD); World Bank exchange rate', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=OM', '2026-10-31', 'Low case: flat dollar gold; the peg means no currency boost.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('OM', 1, 'gratuity_rule', NULL, '{"daysPerYear":30,"daysPerYearAfter":null,"afterYears":null,"daysPerMonth":30}', 'sourced', 'Labour Law (Royal Decree 53/2023), Article 61, text on qanoon.om', 'https://qanoon.om/p/2023/rd2023053/', '2023-07-25', 'At least one month''s basic wage for each year of service, part years pro rata, on the last basic wage; it applies only to workers not covered by the Social Protection Law, which in practice means non-Omani employees (Omanis get the Social Protection Fund pension instead). Article 48 lets an employer savings plan of equal value replace it. Law from 2023 (older than 2025) but in force.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('OM', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a major private hospital stay was found; Omani citizens are treated free in Ministry of Health facilities.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('OM', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premiums by age were found from a public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('OM', 1, 'inflation_cpi', 0.032, NULL, 'sourced', 'National Centre for Statistics and Information (NCSI), Consumer Price Inflation, September 2026', 'https://api.ncsi.gov.om/uploads/pdfs/consumer_price_inflation__september_2026_1791889556.pdf', '2026-09-30', 'Consumer prices up 3.2% year on year in September 2026 (base 2018); food 8.4%, average 3.0% over January-September 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('OM', 1, 'inflation_projection', 0.02, NULL, 'assumption', 'NCSI CPI (3.2% September 2026); World Bank CPI inflation 2021-2025 (about 1.4% average); dollar peg', 'https://data.worldbank.org/indicator/FP.CPI.TOTL.ZG?locations=OM', '2026-10-31', 'With the rial pegged to the dollar, inflation averaged about 1.4% over 2021-2025 and is 3.2% now, so 2% a year is used for long-range plans.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('OM', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life cover is sold, but no published premium rates per OMR 1,000 of cover by age were found from the regulator or another public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('OM', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Financial Services Authority (insurance regulator) publishes market reviews and customer-protection statistics, but no industry-wide life claim settlement ratio was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('OM', 1, 'life_expectancy', 80.246, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN), Oman', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=OM', '2024-12-31', '80.2 years in 2024 (men 78.7, women 82.0); the population includes many younger migrant workers.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('OM', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":23.6,"men":22.4,"women":24.8},{"age":65,"total":19.3,"men":18.2,"women":20.5},{"age":70,"total":15.3,"men":14.3,"women":16.3},{"age":80,"total":8.7,"men":8.1,"women":9.3}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/oman/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('OM', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":63,"womenAge":63,"over90Monthly":null,"meansTested":false}', 'sourced', 'Social Protection Law (Royal Decree 52/2023), text on qanoon.om, Articles 6 and 29; gov.om elderly benefit service', 'https://qanoon.om/p/2023/rd2023052/', '2024-01-01', 'Article 29: Omani, resident in Oman, and of elderly age; no income test. The elderly age is 60 now (gov.om) and rises one year every seven years to 65 by 2059 (Article 6); 63 is used to match the pension age for people born about 1982-1988. Law from 2023 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('OM', 1, 'old_age_allowance_monthly', 115, NULL, 'sourced', 'Social Protection Law (Royal Decree 52/2023), text on qanoon.om, Article 29 (elderly benefit)', 'https://qanoon.om/p/2023/rd2023052/', '2024-01-01', 'OMR 115 a month for every Omani resident in Oman who has reached the elderly age; gov.om (2026) confirms the benefit is open for applications. Article 24 lets the amount be reviewed every two years; no change was found. Law from 2023 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('OM', 1, 'oop_health_share', 0.0631, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), Oman', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=OM', '2023-12-31', '6.3% in 2023 (WHO Global Health Expenditure Database via the World Bank); older than 2025, the latest available.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('OM', 1, 'policy_rate', 0.045, NULL, 'sourced', 'Trading Economics, citing the Central Bank of Oman repo rate decision of 16 September 2026', 'https://tradingeconomics.com/oman/interest-rate', '2026-09-16', 'Repo rate raised by 25 basis points to 4.50%; secondary source. The Central Bank of Oman website rejected automated access, so its statistical bulletin could not be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('OM', 1, 'public_pension_scheme', NULL, '{"pensionFromAge":63,"entryAgeMin":null,"entryAgeMax":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'Social Protection Law (Royal Decree 52/2023), text on qanoon.om, Articles 6, 61, 70 and 72', 'https://qanoon.om/p/2023/rd2023052/', '2024-01-01', 'Compulsory Social Protection Fund pension for Omani employees (Article 70: 11% employer and 7.5% employee contributions; wage ceiling OMR 3,000 a month), paid at the elderly age, 60 now and rising to 65 by 2059 (63 for people born about 1982-1988). Article 61 allows yearly increases set by the Fund''s board on actuarial advice, not automatic indexation, so it is treated as not inflation-linked. Pensions will count as income under the personal income tax from 2028. Law from 2023 (older than 2025) but in force.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('OM', 1, 'retirement_accumulation_return_base', 0.05, NULL, 'assumption', 'World Bank deposit rate; equity base 6.5%; gold base 4%', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=OM', '2026-10-31', 'Base case: a balanced mix of deposits or sukuk, equities and some gold.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('OM', 1, 'retirement_accumulation_return_high', 0.07, NULL, 'assumption', 'NCSI bulletin (MSX 30); equity high 10%', 'https://api.ncsi.gov.om/uploads/pdfs/monthly_statistical_bulletin__october_2026_1792489912.pdf', '2026-10-31', 'High case: a growth-leaning mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('OM', 1, 'retirement_accumulation_return_low', 0.035, NULL, 'assumption', 'World Bank deposit rate (4.15%, 2021)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=OM', '2026-10-31', 'Low case: a mix earning about deposit rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('OM', 1, 'retirement_age_default', 63, NULL, 'sourced', 'Social Protection Law (Royal Decree 52/2023), text on qanoon.om, Articles 6 and 72', 'https://qanoon.om/p/2023/rd2023052/', '2024-01-01', 'Under Articles 6 and 72 of the Social Protection Law the old-age pension is paid at the ''elderly age'', 60 from 1 January 2024 (confirmed on gov.om, 21 September 2026), rising by one year every seven years until 65 (61 from 2031, 62 from 2038, 63 from 2045, 64 from 2052, 65 from 2059). For people born after 1975 this means 61 to 65; 63 applies to those born about 1982-1988 and is used here. Women have the same age. Law text from 2023 (older than 2025) but in force.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('OM', 1, 'retirement_age_government', 63, NULL, 'sourced', 'Social Protection Law (Royal Decree 52/2023), text on qanoon.om, Articles 6 and 72', 'https://qanoon.om/p/2023/rd2023052/', '2024-01-01', 'Since 2024 the Social Protection Fund runs one old-age pension for civil and private-sector Omanis, so the same rising elderly age applies (60 now, 63 for people born about 1982-1988, 65 from 2059); transitional rights of members of the former government pension funds were not checked.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('OM', 1, 'retirement_return_base', 0.035, NULL, 'assumption', 'World Bank deposit rate (4.15%, 2021); repo rate 4.50%', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=OM', '2026-10-31', 'Base case: below the last published untaxed average deposit rate, because current 1-year deposit rates could not be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('OM', 1, 'retirement_return_high', 0.04, NULL, 'assumption', 'Repo rate 4.50% (September 2026)', 'https://tradingeconomics.com/oman/interest-rate', '2026-10-31', 'High case: part of the money earns Treasury bill, development bond or sukuk returns.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('OM', 1, 'retirement_return_low', 0.025, NULL, 'assumption', 'World Bank deposit rate (4.15%, 2021); repo rate 4.50%', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=OM', '2026-10-31', 'Low case: deposit rates fall with lower dollar rates; untaxed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('OM', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate or retail savings bond for individuals was found; government development bonds and sukuk are issued through the Central Bank of Oman and listed on the stock exchange.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('OM', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No current industry-wide savings account rate could be read. The Central Bank of Oman website rejected automated access, so its statistical bulletin could not be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('OM', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":27.2},{"year":2040,"value":19.2},{"year":2065,"value":7.1}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/oman/2040/', '2025-12-31', '100 / old-age dependency ratio: 3.68 (2025, World Bank), 5.2 (2040) and 14.0 (2065, populationpyramid.net/oman/2065/); the large migrant workforce keeps the ratio high.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('OM', 1, 'tax_bank_interest', 0, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Oman, taxes on personal income', 'https://taxsummaries.pwc.com/oman/individual/taxes-on-personal-income', '2026-10-31', 'There is no personal income tax in 2026; a 5% tax on income above OMR 42,000 a year (which will include interest) starts on 1 January 2028.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('OM', 1, 'tax_sanchayapatra_profit', 0, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Oman, taxes on personal income', 'https://taxsummaries.pwc.com/oman/individual/taxes-on-personal-income', '2026-10-31', 'No personal income tax until 2028, so returns on government securities are untaxed for individuals (no retail savings certificate exists).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('OM', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No recent 91-day Treasury bill auction result could be read. The Central Bank of Oman website rejected automated access, so its statistical bulletin could not be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('OM', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 10-year government bond yield could be read. The Central Bank of Oman website rejected automated access, so its statistical bulletin could not be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('OM', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 5-year government development bond yield could be read. The Central Bank of Oman website rejected automated access, so its statistical bulletin could not be read.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('PA', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"PA","iso3":"PAN","nameEn":"Panama","nameNative":"Panamá","region":"latin_america_caribbean","languages":["es","en","gym"],"currency":{"code":"USD","symbol":"$","decimals":2,"compact":"intl","usdRate":{"value":1,"status":"sourced","sourceName":"World Bank WDI PA.NUS.FCRF","sourceUrl":"https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=PA","asOf":"2025-12-31","note":"The US dollar circulates as legal tender; the balboa (PAB) is fixed at par and issued only as coins."}},"instruments":{"savings_account":{"available":true,"localName":"Cuenta de ahorro","localNameEn":"Savings account","sourceUrl":"https://www.superbancos.gob.pa/documentos/financiera_y_estadistica/tarifario/2026/Septiembre.xlsx"},"fdr_3m":{"available":true,"localName":"Depósito a plazo fijo a 3 meses","localNameEn":"3-month fixed-term deposit","note":"Short fixed deposits are offered; the regulator''s rate table groups all terms up to 1 year."},"fdr_1y":{"available":true,"localName":"Depósito a plazo fijo a 1 año","localNameEn":"1-year fixed-term deposit","sourceUrl":"https://www.superbancos.gob.pa/documentos/financiera_y_estadistica/tarifario/2026/Septiembre.xlsx"},"dps":{"available":false,"localName":null,"localNameEn":"Monthly recurring deposit","note":"No standard monthly recurring deposit product with a published rate was found."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":"Government savings certificate","note":"No retail government savings certificate was found."},"tbill_91d":{"available":false,"localName":null,"localNameEn":"3-month treasury bill","note":"Letras del Tesoro are short-term bills sold at periodic auctions, generally with a 12-month term (Ministry of Economy and Finance announcement, October 2026); a regular 3-month bill was not found.","sourceUrl":null},"tbond_5y":{"available":true,"localName":"Notas del Tesoro","localNameEn":"Treasury notes (medium term)","note":"Notas del Tesoro are medium-term notes sold at auction with the term and coupon set each time (Ministry of Economy and Finance, October 2026); yields could not be sourced.","sourceUrl":null},"tbond_10y":{"available":true,"localName":"Bonos de la República de Panamá","localNameEn":"Republic of Panama bonds","note":"Long-term dollar bonds trade through securities brokers; yields could not be sourced."},"equity_fund":{"available":true,"localName":"Fondos de inversión","localNameEn":"Investment funds","note":"Funds are regulated by the Superintendencia del Mercado de Valores; global equity funds and ETFs are bought through securities brokers."},"gold":{"available":true,"localName":"Oro (lingotes y monedas)","localNameEn":"Gold bars and coins"}},"institutions":{"centralBank":null,"insuranceRegulator":{"name":"Superintendencia de Seguros y Reaseguros de Panamá","url":"https://www.superseguros.gob.pa/"},"insuranceComplaints":{"name":"Superintendencia de Seguros y Reaseguros de Panamá, consumer complaints","url":"https://www.superseguros.gob.pa/","note":"A dedicated complaints page could not be confirmed; complaints go to the Superintendencia."},"pensionScheme":{"name":"Caja de Seguro Social (CSS), Invalidez, Vejez y Muerte","url":"https://www.css.gob.pa/"},"oldAgeAllowance":{"name":"Programa Especial de Transferencia Económica a los Adultos Mayores (120 a los 65), MIDES","url":"https://www.mides.gob.pa/programas/120-a-los-65/"},"publicHealthCover":{"name":"Ministerio de Salud (MINSA) and Caja de Seguro Social public health services","url":"https://www.minsa.gob.pa/"},"statistics":{"name":"Instituto Nacional de Estadística y Censo (INEC), Contraloría General","url":"https://www.inec.gob.pa/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PA', 1, 'bank_deposit_avg_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No weighted average deposit rate for Panama was found; the World Bank''s last FR.INR.DPST value is from 2006. Posted rates are in the Superintendencia de Bancos tarifario (see the savings and 1-year slots).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PA', 1, 'credit_card_rate_cap', 0.1958, NULL, 'sourced', 'Superintendencia de Bancos de Panamá, Tarifario de tasas nominales, tarjetas de crédito, septiembre 2026', 'https://www.superbancos.gob.pa/documentos/financiera_y_estadistica/tarifario/2026/Septiembre.xlsx', '2026-09-30', 'Median nominal annual credit card rate across 24 banks in September 2026 (range 9%-26.5%); a typical rate, not a legal cap.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PA', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No deposit insurance scheme was found: the Superintendencia de Bancos consumer and FAQ pages do not mention deposit insurance or a guarantee, but no source confirming that none exists could be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PA', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No monthly recurring deposit product with a published average rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PA', 1, 'equity_return_base', 0.07, NULL, 'assumption', 'Global equity index in US dollars; tax-free 1-year deposit 3.75% (SBP tarifario)', 'https://www.superbancos.gob.pa/documentos/financiera_y_estadistica/tarifario/2026/Septiembre.xlsx', '2026-10-31', 'Panama''s exchange lists few shares, so equity is a global index fund in US dollars (the local currency): about 3.25 points over tax-free one-year deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PA', 1, 'equity_return_high', 0.095, NULL, 'assumption', 'Global equity long-run record in US dollars', 'https://www.superbancos.gob.pa/documentos/financiera_y_estadistica/tarifario/2026/Septiembre.xlsx', '2026-10-31', 'High case: global shares repeat their long-run record.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PA', 1, 'equity_return_low', 0.02, NULL, 'assumption', 'Few shares trade locally; global equities in US dollars; 1-year deposit 3.75% tax-free (SBP tarifario)', 'https://www.superbancos.gob.pa/documentos/financiera_y_estadistica/tarifario/2026/Septiembre.xlsx', '2026-10-31', 'Low case: global shares disappoint and return less than tax-free deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PA', 1, 'fdr_1y_rate', 0.0375, NULL, 'sourced', 'Superintendencia de Bancos de Panamá, Tarifario de tasas nominales, depósitos a plazo fijo con vencimiento hasta 1 año, septiembre 2026', 'https://www.superbancos.gob.pa/documentos/financiera_y_estadistica/tarifario/2026/Septiembre.xlsx', '2026-09-30', 'Median nominal rate on fixed-term deposits of up to 1 year across 29 banks in September 2026 (range 1.25%-5.25%, mean 3.66%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PA', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Superintendencia de Bancos tarifario reports term-deposit rates only as a single ''up to 1 year'' figure per bank; no separate 3-month rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PA', 1, 'fixed_income_return_base', 0.0375, NULL, 'assumption', '1-year fixed deposit median 3.75%, tax-exempt (SBP tarifario; PwC)', 'https://www.superbancos.gob.pa/documentos/financiera_y_estadistica/tarifario/2026/Septiembre.xlsx', '2026-10-31', 'Base case: one-year fixed deposits, with no tax on the interest.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PA', 1, 'fixed_income_return_high', 0.05, NULL, 'assumption', 'Top 1-year deposit rates 5-5.25% (SBP tarifario); government notes', 'https://www.superbancos.gob.pa/documentos/financiera_y_estadistica/tarifario/2026/Septiembre.xlsx', '2026-10-31', 'High case: the better-paying deposits or medium-term government notes.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PA', 1, 'fixed_income_return_low', 0.02, NULL, 'assumption', 'Savings accounts 1%, 1-year deposits 3.75% (SBP tarifario), interest tax-exempt', 'https://www.superbancos.gob.pa/documentos/financiera_y_estadistica/tarifario/2026/Septiembre.xlsx', '2026-10-31', 'Low case: a mix of savings accounts and short deposits after rates fall.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PA', 1, 'goal_inflation_education', 0.03, NULL, 'assumption', 'INEC CPI (Trading Economics): 2.8% in September 2026', 'https://tradingeconomics.com/panama/inflation-cpi', '2026-10-31', 'School fees usually rise a little faster than general prices; planning uses 3%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PA', 1, 'goal_inflation_health', 0.035, NULL, 'assumption', 'INEC CPI (Trading Economics): 2.8% in September 2026', 'https://tradingeconomics.com/panama/inflation-cpi', '2026-10-31', 'Medical costs usually rise faster than general prices; planning uses 3.5%, 1.5 points above projected inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PA', 1, 'gold_return_base', 0.045, NULL, 'assumption', 'Gold USD price trend (Trading Economics); US dollar is the currency', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Base case: gold tracks long-run dollar inflation plus a little.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PA', 1, 'gold_return_high', 0.09, NULL, 'assumption', 'Gold USD price history (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'High case: gold resumes its 2020s uptrend.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PA', 1, 'gold_return_low', 0, NULL, 'assumption', 'Gold USD 3,876/oz on 30 Oct 2026, 3% lower in a year (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Low case: gold stays flat in dollars.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PA', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Labour Code provides a seniority premium (prima de antigüedad) on the end of an indefinite contract, but the Ministry of Labour site refused access, so the days-per-year rule could not be confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PA', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a private hospital stay was found.', 0);
