INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PA', 1, 'inflation_cpi', 0.028, NULL, 'sourced', 'INEC Panamá, Índice de Precios al Consumidor, as reported by Trading Economics', 'https://tradingeconomics.com/panama/inflation-cpi', '2026-09-30', 'Year-on-year CPI inflation 2.8% in September 2026 (2.2% in August), from INEC via Trading Economics (secondary source). World Bank 2025 average -0.19%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PA', 1, 'inflation_projection', 0.02, NULL, 'assumption', 'INEC CPI: -0.1% in 2025, 2.8% in September 2026; US dollar is the currency (Trading Economics)', 'https://tradingeconomics.com/panama/inflation-cpi', '2026-10-31', 'Panama uses the US dollar and has no central bank, so its inflation tracks US inflation over time; planning uses 2%, close to the long-run average.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PA', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life cover is sold in Panama, but no regulator or other non-company source with indicative premiums by age was found.', 0);
