INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PA', 1, 'retirement_return_high', 0.045, NULL, 'assumption', 'Top 1-year deposit rates 5-5.25% (SBP tarifario); government notes', 'https://www.superbancos.gob.pa/documentos/financiera_y_estadistica/tarifario/2026/Septiembre.xlsx', '2026-10-31', 'High case: better-paying deposits and medium-term government notes.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PA', 1, 'retirement_return_low', 0.02, NULL, 'assumption', 'Savings 1%, 1-year deposits 3.75% (SBP tarifario), tax-exempt', 'https://www.superbancos.gob.pa/documentos/financiera_y_estadistica/tarifario/2026/Septiembre.xlsx', '2026-10-31', 'Low case: deposit rates fall with US rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PA', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate for individuals was found; the Ministry of Economy and Finance issues Letras and Notas del Tesoro to the market.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PA', 1, 'savings_account_rate', 0.01, NULL, 'sourced', 'Superintendencia de Bancos de Panamá, Tarifario de tasas nominales, cuentas de ahorro básicas, septiembre 2026', 'https://www.superbancos.gob.pa/documentos/financiera_y_estadistica/tarifario/2026/Septiembre.xlsx', '2026-09-30', 'Median nominal rate on basic savings accounts across 29 banks in September 2026 (range 0.05%-2.5%); figures are informative and not binding on banks.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PA', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":6.82},{"year":2040,"value":4.27},{"year":2065,"value":2.62}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/panama/2065/', '2025-12-31', '100 / old-age dependency ratio: 14.7 in 2025 (World Bank), 23.4 in 2040 and 38.2 in 2065 (UN WPP medium variant).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PA', 1, 'tax_bank_interest', 0, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Panama, corporate income determination', 'https://taxsummaries.pwc.com/panama/corporate/income-determination', '2026-08-04', 'Interest on bank accounts in Panama and earnings on government securities are exempt income, as the page notes for the dividend rule (page reviewed 4 August 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PA', 1, 'tax_sanchayapatra_profit', 0, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Panama, corporate income determination', 'https://taxsummaries.pwc.com/panama/corporate/income-determination', '2026-08-04', 'No separate savings certificate exists; interest and earnings on securities issued by the government are exempt income.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PA', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Treasury bills (Letras del Tesoro) are generally 12-month instruments sold at periodic auctions (Ministry of Economy and Finance, October 2026); no 3-month yield was found, and the MEF yield-curve page did not show figures.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PA', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No reachable source for the 10-year government bond yield was found; the MEF yield-curve page did not show figures.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PA', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The MEF public debt yield-curve page could not be read (figures load dynamically), and no other source for a 5-year yield was found.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('PE', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"PE","iso3":"PER","nameEn":"Peru","nameNative":"Perú","region":"latin_america_caribbean","languages":["es","qu","ay"],"currency":{"code":"PEN","symbol":"S/","decimals":2,"compact":"intl","usdRate":{"value":3.4625,"status":"sourced","sourceName":"Banco Central de Reserva del Peru (BCRP) statistics: banking system exchange rate (SBS), buy and sell, 30 October 2026","sourceUrl":"https://estadisticas.bcrp.gob.pe/estadisticas/series/diarias/resultados/PD04639PD-PD04640PD-PD12301MD/html/2026-10-26/2026-10-31/","asOf":"2026-10-30","note":"Mid of buy 3.458 and sell 3.467 soles per dollar on 30 October 2026 (BCRP series PD04639PD and PD04640PD); World Bank average 3.567 for 2025."}},"instruments":{"savings_account":{"available":true,"localName":"Cuenta de ahorros","localNameEn":"Savings account","note":"Interest exempt from income tax until 31 December 2026; deposits covered by the FSD.","sourceUrl":"https://fsd.org.pe/cobertura/"},"fdr_3m":{"available":true,"localName":"Depósito a plazo fijo","localNameEn":"Fixed-term deposit (90 days)","note":"Offered by banks, finance companies and municipal savings banks; average 3.89% for 31-180 days (BCRP, September 2026).","sourceUrl":"https://estadisticas.bcrp.gob.pe/estadisticas/series/mensuales/resultados/PN07807NM-PN07810NM-PN07811NM-PN07813NM-PN07814NM-PN07815NM-PN07816NM-PN07845NM-PD31895MM/html/2026-6/2026-10/"},"fdr_1y":{"available":true,"localName":"Depósito a plazo fijo","localNameEn":"Fixed-term deposit (360 days)","note":"Offered by banks, finance companies and municipal savings banks; average 4.29% for 181-360 days (BCRP, September 2026).","sourceUrl":"https://estadisticas.bcrp.gob.pe/estadisticas/series/mensuales/resultados/PN07807NM-PN07810NM-PN07811NM-PN07813NM-PN07814NM-PN07815NM-PN07816NM-PN07845NM-PD31895MM/html/2026-6/2026-10/"},"dps":{"available":false,"localName":null,"note":"No standard monthly recurring deposit product with a published industry rate."},"sanchayapatra_5y":{"available":false,"localName":null,"note":"No government savings certificate for individuals."},"tbill_91d":{"available":true,"localName":"Letras del Tesoro","localNameEn":"Treasury bills","note":"Issued by the Ministry of Economy and Finance; mostly bought by institutions; interest tax-exempt (article 19 h).","sourceUrl":"https://www.sunat.gob.pe/legislacion/renta/ley/capiv.pdf"},"tbond_5y":{"available":true,"localName":"Bonos Soberanos","localNameEn":"Sovereign bonds","note":"Soles bonds issued by the Republic; bought through brokers; interest tax-exempt (article 19 h).","sourceUrl":"https://www.sunat.gob.pe/legislacion/renta/ley/capiv.pdf"},"tbond_10y":{"available":true,"localName":"Bonos Soberanos","localNameEn":"Sovereign bonds (10 years)","note":"Soles bonds issued by the Republic.","sourceUrl":"https://estadisticas.bcrp.gob.pe/estadisticas/series/mensuales/resultados/PN07807NM-PN07810NM-PN07811NM-PN07813NM-PN07814NM-PN07815NM-PN07816NM-PN07845NM-PD31895MM/html/2026-6/2026-10/"},"equity_fund":{"available":true,"localName":"Fondos mutuos","localNameEn":"Mutual funds","note":"Regulated by the Superintendencia del Mercado de Valores (SMV); equity and mixed funds are available to retail investors."},"gold":{"available":true,"localName":"Oro","localNameEn":"Gold bars, coins and jewellery","note":"No legal restriction on buying gold."}},"institutions":{"centralBank":{"name":"Banco Central de Reserva del Perú (BCRP)","url":"https://www.bcrp.gob.pe/"},"insuranceRegulator":{"name":"Superintendencia de Banca, Seguros y AFP (SBS)","url":"https://www.sbs.gob.pe/"},"insuranceComplaints":{"name":"Superintendencia de Banca, Seguros y AFP (SBS), user services","url":"https://www.gob.pe/sbs","note":"Complaints go first to the insurer, then to the SBS."},"pensionScheme":{"name":"Oficina de Normalización Previsional (ONP), Sistema Nacional de Pensiones","url":"https://www.gob.pe/onp"},"oldAgeAllowance":{"name":"Programa Nacional de Asistencia Solidaria Pensión 65","url":"https://www.gob.pe/pension65"},"publicHealthCover":{"name":"Seguro Integral de Salud (SIS)","url":"https://www.gob.pe/sis","note":"State-subsidised health insurance for people without other cover; formal employees are covered by EsSalud."},"depositInsurance":{"name":"Fondo de Seguro de Depósitos (FSD)","url":"https://fsd.org.pe/cobertura/"},"statistics":{"name":"Instituto Nacional de Estadística e Informática (INEI)","url":"https://www.inei.gob.pe/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PE', 1, 'bank_deposit_avg_rate', 0.0201, NULL, 'sourced', 'BCRP statistics: average interest rates of banks in soles, TIPMN average deposit rate (series PN07816NM)', 'https://estadisticas.bcrp.gob.pe/estadisticas/series/mensuales/resultados/PN07807NM-PN07810NM-PN07811NM-PN07813NM-PN07814NM-PN07815NM-PN07816NM-PN07845NM-PD31895MM/html/2026-6/2026-10/', '2026-09-30', 'Average rate on all deposits in soles (TIPMN), September 2026 (2.01%); World Bank FR.INR.DPST gives 4.82% for 2022.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PE', 1, 'credit_card_rate_cap', 0.6477, NULL, 'sourced', 'BCRP statistics: average interest rates of banks in soles, consumer credit cards (series PN07845NM)', 'https://estadisticas.bcrp.gob.pe/estadisticas/series/mensuales/resultados/PN07807NM-PN07810NM-PN07811NM-PN07813NM-PN07814NM-PN07815NM-PN07816NM-PN07845NM-PD31895MM/html/2026-6/2026-10/', '2026-09-30', 'Typical rate: average effective annual rate on consumer credit card balances in soles at banks, September 2026 (64.77%); the BCRP also sets a half-yearly legal cap that was not checked.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PE', 1, 'deposit_insurance_limit', 123000, NULL, 'sourced', 'Fondo de Seguro de Depositos (FSD): maximum coverage September-November 2026', 'https://fsd.org.pe/cobertura/', '2026-09-01', 'S/ 123,000 per depositor per member institution (banks, finance companies, municipal and rural savings banks), updated quarterly.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PE', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No standard monthly recurring deposit product with a published industry rate was found in Peru.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PE', 1, 'equity_return_base', 0.085, NULL, 'assumption', 'Peru 10-year sovereign yield 6.52% (BCRP, September 2026), tax-exempt', 'https://estadisticas.bcrp.gob.pe/estadisticas/series/mensuales/resultados/PN07807NM-PN07810NM-PN07811NM-PN07813NM-PN07814NM-PN07815NM-PN07816NM-PN07845NM-PD31895MM/html/2026-6/2026-10/', '2026-10-31', 'Base case: the tax-free 6.5% sovereign yield plus about 2 points of equity premium, held well below safe rate plus 4 because the local index is narrow and volatile.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PE', 1, 'equity_return_high', 0.11, NULL, 'assumption', 'Peru 10-year sovereign yield 6.52% (BCRP, September 2026)', 'https://estadisticas.bcrp.gob.pe/estadisticas/series/mensuales/resultados/PN07807NM-PN07810NM-PN07811NM-PN07813NM-PN07814NM-PN07815NM-PN07816NM-PN07845NM-PD31895MM/html/2026-6/2026-10/', '2026-10-31', 'High case if metal prices and local shares repeat a strong decade.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PE', 1, 'equity_return_low', 0.04, NULL, 'assumption', 'Peru 10-year sovereign yield 6.52% (BCRP, September 2026)', 'https://estadisticas.bcrp.gob.pe/estadisticas/series/mensuales/resultados/PN07807NM-PN07810NM-PN07811NM-PN07813NM-PN07814NM-PN07815NM-PN07816NM-PN07845NM-PD31895MM/html/2026-6/2026-10/', '2026-10-31', 'Low case: the Lima stock exchange is concentrated in mining shares and can have weak decades.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PE', 1, 'fdr_1y_rate', 0.0429, NULL, 'sourced', 'BCRP statistics: average interest rates of banks in soles, term deposits 181-360 days (series PN07814NM)', 'https://estadisticas.bcrp.gob.pe/estadisticas/series/mensuales/resultados/PN07807NM-PN07810NM-PN07811NM-PN07813NM-PN07814NM-PN07815NM-PN07816NM-PN07845NM-PD31895MM/html/2026-6/2026-10/', '2026-09-30', 'Average rate on term deposits of 181-360 days in soles at banks, September 2026 (4.29%); deposits of 360 days or more averaged 4.63%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PE', 1, 'fdr_3m_rate', 0.0389, NULL, 'sourced', 'BCRP statistics: average interest rates of banks in soles, term deposits 31-180 days (series PN07813NM)', 'https://estadisticas.bcrp.gob.pe/estadisticas/series/mensuales/resultados/PN07807NM-PN07810NM-PN07811NM-PN07813NM-PN07814NM-PN07815NM-PN07816NM-PN07845NM-PD31895MM/html/2026-6/2026-10/', '2026-09-30', 'Average rate on term deposits of 31-180 days in soles at banks, September 2026 (3.89%); the BCRP does not publish a separate 90-day bucket.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PE', 1, 'fixed_income_return_base', 0.045, NULL, 'assumption', 'BCRP: term deposits 3.89-4.63%, 10-year sovereign 6.52% (September 2026); interest tax-exempt until 31 December 2026', 'https://estadisticas.bcrp.gob.pe/estadisticas/series/mensuales/resultados/PN07807NM-PN07810NM-PN07811NM-PN07813NM-PN07814NM-PN07815NM-PN07816NM-PN07845NM-PD31895MM/html/2026-6/2026-10/', '2026-10-31', 'Base case: a mix of term deposits around 4-4.6% and sovereign bonds, both tax-free today (a 5% tax would apply if the exemption lapses).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PE', 1, 'fixed_income_return_high', 0.06, NULL, 'assumption', 'Peru 10-year sovereign yield 6.52% (BCRP, September 2026), tax-exempt', 'https://estadisticas.bcrp.gob.pe/estadisticas/series/mensuales/resultados/PN07807NM-PN07810NM-PN07811NM-PN07813NM-PN07814NM-PN07815NM-PN07816NM-PN07845NM-PD31895MM/html/2026-6/2026-10/', '2026-10-31', 'High case: holding sovereign bonds to maturity at about 6%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PE', 1, 'fixed_income_return_low', 0.03, NULL, 'assumption', 'BCRP: savings 0.86%, term deposits 31-180 days 3.89% (September 2026)', 'https://estadisticas.bcrp.gob.pe/estadisticas/series/mensuales/resultados/PN07807NM-PN07810NM-PN07811NM-PN07813NM-PN07814NM-PN07815NM-PN07816NM-PN07845NM-PD31895MM/html/2026-6/2026-10/', '2026-10-31', 'Low case: a mix of savings accounts and short term deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PE', 1, 'goal_inflation_education', 0.04, NULL, 'assumption', 'Peru CPI education component +3.54% year on year (October 2026, Trading Economics)', 'https://tradingeconomics.com/peru/inflation-cpi', '2026-10-31', 'Education prices rose about 3.5% in the latest year; we plan with 4%, planning inflation plus 1 point for private schooling and university.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PE', 1, 'goal_inflation_health', 0.045, NULL, 'assumption', 'Peru CPI 5.25% (October 2026); BCRP target 2% (range 1-3%)', 'https://tradingeconomics.com/peru/inflation-cpi', '2026-10-31', 'No long-run health CPI series could be read; planning inflation (3%) plus 1.5 points for private clinic costs.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PE', 1, 'gold_return_base', 0.05, NULL, 'assumption', 'BCRP: about 3.46 soles per dollar (30 October 2026); World Bank average 3.57 for 2025', 'https://estadisticas.bcrp.gob.pe/estadisticas/series/diarias/resultados/PD04639PD-PD04640PD-PD12301MD/html/2026-10-26/2026-10-31/', '2026-10-31', 'Long-run dollar gold trend of about 4.5% plus a little sol depreciation; the sol has been one of the most stable currencies in the region.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PE', 1, 'gold_return_high', 0.085, NULL, 'assumption', 'BCRP: about 3.46 soles per dollar (30 October 2026); World Bank average 3.57 for 2025', 'https://estadisticas.bcrp.gob.pe/estadisticas/series/diarias/resultados/PD04639PD-PD04640PD-PD12301MD/html/2026-10-26/2026-10-31/', '2026-10-31', 'High case with strong dollar gold prices.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PE', 1, 'gold_return_low', 0.015, NULL, 'assumption', 'BCRP: about 3.46 soles per dollar (30 October 2026); World Bank average 3.57 for 2025', 'https://estadisticas.bcrp.gob.pe/estadisticas/series/diarias/resultados/PD04639PD-PD04640PD-PD12301MD/html/2026-10-26/2026-10-31/', '2026-10-31', 'Low case: weak dollar gold price while the sol stays strong.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PE', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'Peru has a statutory length-of-service compensation (CTS) deposited by employers twice a year, but no readable official page with the rule was found (Labour Ministry and SUNAFIL pages unreachable), so the days per year were not recorded.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PE', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No official figure for a typical major private clinic stay in Peru was found (SUSALUD and Ministry of Health sources not reachable).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PE', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No regulator or public source publishing private health insurance premiums by age was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PE', 1, 'inflation_cpi', 0.0525, NULL, 'sourced', 'Trading Economics, Peru inflation rate (INEI, Lima Metropolitan CPI)', 'https://tradingeconomics.com/peru/inflation-cpi', '2026-10-31', 'Secondary source: year-on-year CPI inflation 5.25% in October 2026 (4.55% in September, confirmed by BCRP series PN01273PM), above the BCRP 1-3% target range.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PE', 1, 'inflation_projection', 0.03, NULL, 'assumption', 'BCRP inflation target 2% (range 1-3%); CPI 5.25% in October 2026 (Trading Economics)', 'https://tradingeconomics.com/peru/inflation-cpi', '2026-10-31', 'The 2% target has been credible over the long run, but inflation has been above the range for most of 2026, so we plan with 3%, the top of the band.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PE', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life (seguro de vida temporal) is sold in Peru, but no regulator or public source publishing premium rates by age was found; only individual insurer quotes exist.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PE', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The SBS publishes insurance statistics, but its pages block automated reading; no industry-wide life claim settlement ratio found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PE', 1, 'life_expectancy', 77.941, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=PE', '2024-12-31', 'UN WPP 2024 (via populationpyramid.net) gives 78.3 for 2026 (men 76.0, women 80.6).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PE', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":23.5,"men":22.1,"women":24.9},{"age":65,"total":19.6,"men":18.3,"women":20.9},{"age":70,"total":15.9,"men":14.7,"women":17.1},{"age":80,"total":9.6,"men":8.7,"women":10.5}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/peru/', '2026-12-31', 'Secondary source of UN WPP 2024 medium variant for 2026; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PE', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":65,"womenAge":65,"over90Monthly":null,"meansTested":true}', 'sourced', 'Programa Nacional de Asistencia Solidaria Pension 65 (gob.pe)', 'https://www.gob.pe/pension65', '2026-01-01', 'For people 65 and over in extreme poverty (household targeting system SISFOH) without another pension; HelpAge Pension Watch also gives age 65, poverty targeted.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PE', 1, 'old_age_allowance_monthly', 175, NULL, 'sourced', 'Programa Nacional de Asistencia Solidaria Pension 65 (gob.pe)', 'https://www.gob.pe/pension65', '2026-01-01', 'Pension 65 is paid every two months: S/ 250 plus a S/ 100 increase approved for 2025-2026, i.e. S/ 350 every two months (S/ 175 a month), per gob.pe as read by the researcher. HelpAge Pension Watch lists the S/ 350 payment (https://www.helpage.org/country_profile/peru/); gob.pe blocked automated reading on re-check.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PE', 1, 'oop_health_share', 0.2698, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=PE', '2023-12-31', 'Figure is for 2023 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PE', 1, 'policy_rate', 0.0425, NULL, 'sourced', 'BCRP statistics: monetary policy reference rate (series PD12301MD)', 'https://estadisticas.bcrp.gob.pe/estadisticas/series/diarias/resultados/PD04639PD-PD04640PD-PD12301MD/html/2026-10-26/2026-10-31/', '2026-10-30', 'Reference rate 4.25% through 30 October 2026; held at the October 2026 meeting (Trading Economics: 13th straight hold).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PE', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":65,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'ONP (gob.pe): pension de jubilacion segun D.L. 19990', 'https://www.gob.pe/9239-solicitar-pension-de-jubilacion-segun-d-l-n-19990', '2026-07-17', 'National Pension System (SNP, run by ONP): pension at 65 after 20 years of contributions, minimum S/ 600 and maximum S/ 1,000 a month (4% health contribution deducted). Workers may instead join a private AFP. No automatic indexation; tax treatment not confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PE', 1, 'retirement_accumulation_return_base', 0.06, NULL, 'assumption', 'Peru 10-year sovereign 6.52% (BCRP, September 2026); equity assumptions', 'https://estadisticas.bcrp.gob.pe/estadisticas/series/mensuales/resultados/PN07807NM-PN07810NM-PN07811NM-PN07813NM-PN07814NM-PN07815NM-PN07816NM-PN07845NM-PD31895MM/html/2026-6/2026-10/', '2026-10-31', 'Base case: half equities at 8.5% and half deposits and bonds around 4.5%, after the 5% tax on share gains.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PE', 1, 'retirement_accumulation_return_high', 0.08, NULL, 'assumption', 'Peru 10-year sovereign 6.52% (BCRP, September 2026); equity assumptions', 'https://estadisticas.bcrp.gob.pe/estadisticas/series/mensuales/resultados/PN07807NM-PN07810NM-PN07811NM-PN07813NM-PN07814NM-PN07815NM-PN07816NM-PN07845NM-PD31895MM/html/2026-6/2026-10/', '2026-10-31', 'High case with stronger equity returns.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PE', 1, 'retirement_accumulation_return_low', 0.04, NULL, 'assumption', 'Peru 10-year sovereign 6.52% (BCRP, September 2026); equity assumptions', 'https://estadisticas.bcrp.gob.pe/estadisticas/series/mensuales/resultados/PN07807NM-PN07810NM-PN07811NM-PN07813NM-PN07814NM-PN07815NM-PN07816NM-PN07845NM-PD31895MM/html/2026-6/2026-10/', '2026-10-31', 'Low case for a balanced mix if equities disappoint.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PE', 1, 'retirement_age_default', 65, NULL, 'sourced', 'ONP (gob.pe): Solicitar pension de jubilacion segun D.L. 19990', 'https://www.gob.pe/9239-solicitar-pension-de-jubilacion-segun-d-l-n-19990', '2026-07-17', 'National Pension System (SNP): pension at 65 with at least 20 years (240 contribution units); the private AFP system (SPP) also uses 65 as the legal retirement age.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PE', 1, 'retirement_age_government', 65, NULL, 'sourced', 'ONP (gob.pe): Solicitar pension de jubilacion segun D.L. 19990', 'https://www.gob.pe/9239-solicitar-pension-de-jubilacion-segun-d-l-n-19990', '2026-07-17', 'Public servants hired today join the SNP or the AFP system, both with pension age 65; the compulsory end-of-service age in the civil service (reported as 70) could not be confirmed from a readable official page.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PE', 1, 'retirement_return_base', 0.04, NULL, 'assumption', 'BCRP: term deposits 181-360 days 4.29% (September 2026); deposit interest tax-exempt until 31 December 2026', 'https://estadisticas.bcrp.gob.pe/estadisticas/series/mensuales/resultados/PN07807NM-PN07810NM-PN07811NM-PN07813NM-PN07814NM-PN07815NM-PN07816NM-PN07845NM-PD31895MM/html/2026-6/2026-10/', '2026-10-31', 'Base case at or below the 1-year deposit rate after tax (4.29% exempt today, about 4.1% if the 5% tax returned): rolling term deposits in retirement.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PE', 1, 'retirement_return_high', 0.05, NULL, 'assumption', 'Peru 10-year sovereign yield 6.52% (BCRP, September 2026)', 'https://estadisticas.bcrp.gob.pe/estadisticas/series/mensuales/resultados/PN07807NM-PN07810NM-PN07811NM-PN07813NM-PN07814NM-PN07815NM-PN07816NM-PN07845NM-PD31895MM/html/2026-6/2026-10/', '2026-10-31', 'High case: part of savings in tax-free sovereign bonds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PE', 1, 'retirement_return_low', 0.03, NULL, 'assumption', 'BCRP: savings 0.86%, term deposits 31-180 days 3.89% (September 2026)', 'https://estadisticas.bcrp.gob.pe/estadisticas/series/mensuales/resultados/PN07807NM-PN07810NM-PN07811NM-PN07813NM-PN07814NM-PN07815NM-PN07816NM-PN07845NM-PD31895MM/html/2026-6/2026-10/', '2026-10-31', 'Low case: mostly savings and short deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PE', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate for individuals was found; the Republic issues Letras del Tesoro and Bonos Soberanos, which are market securities, not fixed-rate retail certificates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PE', 1, 'savings_account_rate', 0.0086, NULL, 'sourced', 'BCRP statistics: average interest rates of banks in soles, savings deposits (series PN07811NM)', 'https://estadisticas.bcrp.gob.pe/estadisticas/series/mensuales/resultados/PN07807NM-PN07810NM-PN07811NM-PN07813NM-PN07814NM-PN07815NM-PN07816NM-PN07845NM-PD31895MM/html/2026-6/2026-10/', '2026-09-30', 'Average effective annual rate on savings deposits in soles at banks, September 2026 (0.86%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PE', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":7.1},{"year":2040,"value":4.8},{"year":2065,"value":2.5}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/peru/2040/', '2025-12-31', '100 / old-age dependency ratio: 14.15 (2025, World Bank), 21.0 (2040) and 39.4 (2065, https://www.populationpyramid.net/peru/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PE', 1, 'tax_bank_interest', 0, NULL, 'sourced', 'SUNAT, Texto Unico Ordenado de la Ley del Impuesto a la Renta, chapter IV, article 19 inciso i)', 'https://www.sunat.gob.pe/legislacion/renta/ley/capiv.pdf', '2024-01-01', 'Article 19 i) exempts interest on deposits under the Banking Law (Ley 26702) for individuals; the article 19 exemptions are extended to 31 December 2026, so a 5% tax on capital income could apply from 2027 unless extended again.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PE', 1, 'tax_sanchayapatra_profit', 0, NULL, 'sourced', 'SUNAT, Ley del Impuesto a la Renta, article 19 inciso h)', 'https://www.sunat.gob.pe/legislacion/renta/ley/capiv.pdf', '2024-01-01', 'No retail savings certificate exists; interest and gains on Letras del Tesoro and Bonos Soberanos issued by the Republic are exempt (article 19 h), also extended to 31 December 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PE', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'BCRP publishes Letras del Tesoro yields, but its statistics site blocks automated reading; no other public 3-month figure found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PE', 1, 'tbond_10y_rate', 0.0652, NULL, 'sourced', 'BCRP statistics: yield of the 10-year Peruvian government bond in soles (series PD31895MM)', 'https://estadisticas.bcrp.gob.pe/estadisticas/series/mensuales/resultados/PN07807NM-PN07810NM-PN07811NM-PN07813NM-PN07814NM-PN07815NM-PN07816NM-PN07845NM-PD31895MM/html/2026-6/2026-10/', '2026-09-30', 'Monthly average yield 6.52% in September 2026; Trading Economics shows about 6.30-6.32% in late October and early November 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PE', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'BCRP publishes the sovereign yield curve, but its statistics site blocks automated reading; Trading Economics shows only the 10-year yield.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('PG', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"PG","iso3":"PNG","nameEn":"Papua New Guinea","nameNative":"Papua Niugini","region":"east_asia_pacific","languages":["tpi","en","ho"],"currency":{"code":"PGK","symbol":"K","decimals":2,"compact":"intl","usdRate":{"value":4.1227,"status":"sourced","sourceName":"World Bank WDI PA.NUS.FCRF (official exchange rate, period average)","sourceUrl":"https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=PG","asOf":"2025-12-31","note":"2025 average 4.12 kina per US dollar (World Bank). The kina has weakened since: Trading Economics shows USD/PGK at 4.48 on 3 November 2026 and a high of 4.58 in October 2026. The Bank of PNG site could not be reached (HTTP 403), so no official 2026 rate is used."}},"instruments":{"savings_account":{"available":true,"localName":"Savings account","note":"Ordinary kina savings accounts are offered by all commercial banks."},"fdr_3m":{"available":true,"localName":"Term deposit","localNameEn":"3-month term deposit"},"fdr_1y":{"available":true,"localName":"Term deposit","localNameEn":"1-year term deposit"},"dps":{"available":false,"localName":null,"note":"No standard monthly recurring deposit product is published by PNG banks."},"sanchayapatra_5y":{"available":false,"localName":null,"note":"No government retail savings bond for individuals found; Treasury bills and Inscribed Stock are sold by Bank of PNG tender."},"tbill_91d":{"available":true,"localName":"Treasury bill","localNameEn":"Government Treasury bill","note":"Sold by Bank of PNG tender, mainly to institutions; 91-day bills are not always on offer."},"tbond_5y":{"available":true,"localName":"Inscribed Stock","localNameEn":"Government Inscribed Stock (bond)","note":"Sold by Bank of PNG tender, mainly to institutions."},"tbond_10y":{"available":true,"localName":"Inscribed Stock","localNameEn":"Government Inscribed Stock (bond)","note":"Sold by Bank of PNG tender, mainly to institutions."},"equity_fund":{"available":true,"localName":"Unit trust","localNameEn":"Unit trust (managed fund)","note":"A few locally managed unit trusts invest in shares on the small PNGX exchange and fixed income."},"gold":{"available":true,"localName":"Gold","note":"PNG is a gold producer; buying gold is legal, mainly as jewellery or from licensed dealers."}},"institutions":{"centralBank":{"name":"Bank of Papua New Guinea","url":"https://www.bankpng.gov.pg/","note":"Also supervises superannuation funds."},"insuranceRegulator":{"name":"Office of the Insurance Commissioner","url":"https://www.oic.gov.pg/"},"insuranceComplaints":{"name":"Office of the Insurance Commissioner","url":"https://www.oic.gov.pg/","note":"No separate insurance ombudsman found; complaints go to the insurer, then the Commissioner."},"pensionScheme":{"name":"Compulsory superannuation (Superannuation (General Provisions) Act 2000), supervised by the Bank of PNG","url":"https://www.bankpng.gov.pg/","note":"No public pension; compulsory superannuation is run by licensed private funds."},"oldAgeAllowance":null,"publicHealthCover":{"name":"National Department of Health (public hospitals and health centres)","url":"https://www.health.gov.pg/"},"depositInsurance":null,"statistics":{"name":"National Statistical Office of Papua New Guinea","url":"https://www.nso.gov.pg/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PG', 1, 'bank_deposit_avg_rate', 0.002625, NULL, 'sourced', 'World Bank WDI FR.INR.DPST (deposit interest rate)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=PG', '2024-12-31', '0.26% in 2024 (figure older than 2025); Bank of PNG statistical tables could not be reached for a fresher figure.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PG', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap found; large banks do not publish card interest rates on their card pages (rates are in fee schedules we could not read).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PG', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched for a PNG deposit insurance or deposit protection scheme: none in operation was found, and no source stating its absence was reachable.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PG', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched bank savings and term deposit pages: no monthly recurring deposit (DPS-style) product with a published rate was found in PNG.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PG', 1, 'equity_return_base', 0.045, NULL, 'assumption', 'World Bank FR.INR.DPST (PNG average deposit rate 0.26% in 2024); PwC: 15% interest withholding tax', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=PG', '2026-10-31', 'After-tax safe rate of about 0.8% (12-month bank deposits near 1% posted in late 2026, less 15% withholding) plus a premium kept under 4 points, since the local market is small, illiquid and has no long index record.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PG', 1, 'equity_return_high', 0.07, NULL, 'assumption', 'World Bank FR.INR.DPST (PNG average deposit rate 0.26% in 2024); PwC: 15% interest withholding tax', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=PG', '2026-10-31', 'High case if dividend-paying resource and bank shares keep their recent record, still well below double digits given the thin market.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PG', 1, 'equity_return_low', 0.02, NULL, 'assumption', 'World Bank FR.INR.DPST (PNG average deposit rate 0.26% in 2024); PwC: 15% interest withholding tax', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=PG', '2026-10-31', 'Low case near the after-tax deposit rate (about 1% or less after the 15% withholding tax), because the local exchange (PNGX) has only a handful of thinly traded listings.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PG', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Only individual commercial banks'' posted rate sheets showed a figure (about 0.9-1.2% for 12 months in late October 2026), and company pages are not used as sources; Bank of PNG interest rate statistics could not be reached (HTTP 403).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PG', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Only an individual commercial bank''s posted rate sheet showed a figure (about 0.6% for 3 months in late October 2026), and company pages are not used as sources; Bank of PNG interest rate statistics could not be reached (HTTP 403).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PG', 1, 'fixed_income_return_base', 0.008, NULL, 'assumption', 'World Bank FR.INR.DPST (PNG average deposit rate 0.26% in 2024); PwC: 15% interest withholding tax', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=PG', '2026-10-31', 'Base case: 12-month bank term deposits at about 0.9-1.0% (posted rates, late 2026) less the 15% withholding tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PG', 1, 'fixed_income_return_high', 0.0125, NULL, 'assumption', 'World Bank FR.INR.DPST (PNG average deposit rate 0.26% in 2024); PwC: 15% interest withholding tax', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=PG', '2026-10-31', 'High case: longer term deposits or Treasury bills at about 1.5% after withholding tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PG', 1, 'fixed_income_return_low', 0.005, NULL, 'assumption', 'World Bank FR.INR.DPST (PNG average deposit rate 0.26% in 2024); PwC: 15% interest withholding tax', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=PG', '2026-10-31', 'Low case: short bank term deposits (posted rates well under 1% in late 2026) after the 15% interest withholding tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PG', 1, 'goal_inflation_education', 0.05, NULL, 'assumption', 'World Bank FP.CPI.TOTL.ZG; NSO quarterly CPI', 'https://data.worldbank.org/indicator/FP.CPI.TOTL.ZG?locations=PG', '2026-10-31', 'No education CPI series found, so we plan with the headline projection plus half a point for school fees.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PG', 1, 'goal_inflation_health', 0.055, NULL, 'assumption', 'World Bank FP.CPI.TOTL.ZG; NSO quarterly CPI', 'https://data.worldbank.org/indicator/FP.CPI.TOTL.ZG?locations=PG', '2026-10-31', 'No medical CPI series found, so we plan with the 4.5% headline projection plus one point for private and imported medical costs.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PG', 1, 'gold_return_base', 0.07, NULL, 'assumption', 'World Bank PA.NUS.FCRF (kina per USD rose from about 3.3 in 2016 to 4.1 in 2025)', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=PG', '2026-10-31', 'Long-run dollar gold trend of about 4-5% plus kina depreciation of about 2-3% a year under the managed crawl.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PG', 1, 'gold_return_high', 0.1, NULL, 'assumption', 'World Bank PA.NUS.FCRF (kina per USD rose from about 3.3 in 2016 to 4.1 in 2025)', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=PG', '2026-10-31', 'High case with strong dollar gold and faster kina depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PG', 1, 'gold_return_low', 0.03, NULL, 'assumption', 'World Bank PA.NUS.FCRF (kina per USD rose from about 3.3 in 2016 to 4.1 in 2025)', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=PG', '2026-10-31', 'Low case: weak dollar gold price with slower kina depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PG', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No statutory gratuity or end-of-service payment for private employees found in PNG employment law; retirement savings run through compulsory superannuation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PG', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched for private hospital surgery or stay costs in Port Moresby: no published typical bill found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PG', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premium table for PNG was found; plans are mainly sold to employer groups.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PG', 1, 'inflation_cpi', 0.022, NULL, 'sourced', 'Trading Economics (PNG National Statistical Office quarterly CPI)', 'https://tradingeconomics.com/papua-new-guinea/inflation-cpi', '2026-06-30', 'Secondary source: headline CPI up 2.2% year on year in the June quarter 2026 (2.2% in the March quarter). The NSO home page shows 3.5% for the September 2026 quarter without saying whether it is annual; the Bank of PNG site could not be reached (HTTP 403).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PG', 1, 'inflation_projection', 0.045, NULL, 'assumption', 'World Bank FP.CPI.TOTL.ZG (PNG CPI 4.4% in 2025); NSO/Trading Economics 2.2% in mid-2026', 'https://data.worldbank.org/indicator/FP.CPI.TOTL.ZG?locations=PG', '2026-10-31', 'The Bank of PNG has no numeric inflation target, and CPI has averaged roughly 4-5% over the last five years with a gradually weakening kina, so we plan with 4.5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PG', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life is sold in PNG, but no published per-1,000 premium rates by age were found; insurers quote individually.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PG', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Office of the Insurance Commissioner site has an expired certificate and no industry-wide life claim settlement ratio was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PG', 1, 'life_expectancy', 66.256, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=PG', '2024-12-31', '2024 figure (older than 2025). UN WPP 2024 (via populationpyramid.net) gives 66.5 for 2026 (men 64.0, women 69.5).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PG', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":16.3,"men":14.8,"women":17.8},{"age":65,"total":12.9,"men":11.8,"women":14.2},{"age":70,"total":10.1,"men":9.2,"women":11},{"age":80,"total":5.7,"men":5.3,"women":6.1}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/papua-new-guinea/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026 (mid-year reference); totals at 60, 70 and 80 are the mean of men and women (the page gives a total only at 65, 12.9).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PG', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'No national non-contributory old-age pension: PwC Worldwide Tax Summaries states that Papua New Guinea does not have a social security system (https://taxsummaries.pwc.com/papua-new-guinea/individual/other-taxes).', 1);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PG', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'PwC Worldwide Tax Summaries states that Papua New Guinea does not have a social security system (https://taxsummaries.pwc.com/papua-new-guinea/individual/other-taxes, reviewed 23 September 2026); no national non-contributory old-age pension exists (some provinces have run their own small schemes).', 1);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PG', 1, 'oop_health_share', 0.0855, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=PG', '2023-12-31', '2023 figure (older than 2025), latest available in World Bank WDI.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PG', 1, 'policy_rate', 0.05, NULL, 'sourced', 'Trading Economics (Bank of PNG Kina Facility Rate)', 'https://tradingeconomics.com/papua-new-guinea/interest-rate', '2026-10-31', 'Secondary source: Kina Facility Rate last recorded at 5.00% (October 2026 reference); the Bank of PNG site returned HTTP 403.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PG', 1, 'public_pension_scheme', NULL, NULL, 'missing', '', '', '2026-10-31', 'PNG has compulsory defined-contribution superannuation through licensed private funds (employee 6%, employer 8.4% for employers with 15 or more staff, PwC Worldwide Tax Summaries, https://taxsummaries.pwc.com/papua-new-guinea/individual/other-taxes, reviewed 23 September 2026), but no public pension; the access age could only be found on fund (company) pages, so the scheme rules are left missing.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PG', 1, 'retirement_accumulation_return_base', 0.03, NULL, 'assumption', 'Taka Plan mix of the PNG equity and fixed-income assumptions; World Bank FR.INR.DPST', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=PG', '2026-10-31', 'Base case: roughly 60% local equity at the 4.5% base and 40% after-tax deposits at 0.8%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PG', 1, 'retirement_accumulation_return_high', 0.05, NULL, 'assumption', 'Taka Plan mix of the PNG equity and fixed-income assumptions; World Bank FR.INR.DPST', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=PG', '2026-10-31', 'High case: mostly equity at the upper end of its range.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PG', 1, 'retirement_accumulation_return_low', 0.02, NULL, 'assumption', 'Taka Plan mix of the PNG equity and fixed-income assumptions; World Bank FR.INR.DPST', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=PG', '2026-10-31', 'Low case for a balanced mix: mostly deposits after tax with some local equity.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PG', 1, 'retirement_age_default', NULL, NULL, 'missing', '', '', '2026-10-31', 'Superannuation preservation age of 55 (with 65 as an alternative) is stated only on superannuation fund (company) pages, which are not used as sources; the Bank of PNG (superannuation regulator) and PacLII statute pages could not be reached (HTTP 403). PwC says PNG has no statutory social security system.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PG', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched for the PNG public service retirement age: no reachable official source (Department of Personnel Management) was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PG', 1, 'retirement_return_base', 0.0075, NULL, 'assumption', 'World Bank FR.INR.DPST (PNG average deposit rate 0.26% in 2024); PwC: 15% interest withholding tax', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=PG', '2026-10-31', 'Base case capped at the after-tax 12-month deposit rate (about 0.9% posted in late 2026 less 15% withholding), the best documented safe 1-year rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PG', 1, 'retirement_return_high', 0.012, NULL, 'assumption', 'World Bank FR.INR.DPST (PNG average deposit rate 0.26% in 2024); PwC: 15% interest withholding tax', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=PG', '2026-10-31', 'High case: laddered longer deposits or Treasury bills after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PG', 1, 'retirement_return_low', 0.004, NULL, 'assumption', 'World Bank FR.INR.DPST (PNG average deposit rate 0.26% in 2024); PwC: 15% interest withholding tax', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=PG', '2026-10-31', 'Low case: short deposits after withholding tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PG', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched for a PNG government retail savings bond for individuals: none found; government securities are sold by Bank of PNG tender, mainly to institutions. Bank of PNG site unreachable (HTTP 403).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PG', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched Bank of PNG (site blocked, HTTP 403) and large bank pages: savings rates are only published in a schedule we could not read; one bank advertises tiered savings ''up to 1.25%'' plus bonus, which is not a typical rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PG', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":17.6},{"year":2040,"value":11.4},{"year":2065,"value":6.8}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/papua-new-guinea/2040/', '2025-12-31', '100 / old-age dependency ratio: 5.67 (2025, World Bank), 8.8 (2040) and 14.6 (2065, populationpyramid.net/papua-new-guinea/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PG', 1, 'tax_bank_interest', 0.15, NULL, 'sourced', 'PwC Worldwide Tax Summaries: Papua New Guinea, individual income determination', 'https://taxsummaries.pwc.com/papua-new-guinea/individual/income-determination', '2026-09-23', 'Interest withholding tax of 15% on interest paid by financial institutions and the Central Bank; for residents it is creditable against final tax (residents pay 0% on the first PGK 20,000 of taxable income). Page last reviewed 23 September 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PG', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government retail savings bond for individuals found, so no specific tax rule applies.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PG', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Bank of PNG auction results could not be reached (HTTP 403) and no secondary source with a current Treasury bill yield was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PG', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Bank of PNG Inscribed Stock tender results could not be reached (HTTP 403); no secondary source found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PG', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Bank of PNG Inscribed Stock tender results could not be reached (HTTP 403); no secondary source found.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('PH', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"PH","iso3":"PHL","nameEn":"Philippines","nameNative":"Pilipinas","region":"east_asia_pacific","languages":["fil","en","ceb","ilo","hil"],"currency":{"code":"PHP","symbol":"₱","decimals":2,"compact":"intl","usdRate":{"value":64.061,"status":"sourced","sourceName":"BSP Selected Economic and Financial Indicators (30 October 2026)","sourceUrl":"https://www.bsp.gov.ph/Statistics/keystat/sefi.pdf","asOf":"2026-10-29","note":"Peso per US dollar, closing rate on 29 October 2026 (October 1-29 average 63.06)."}},"instruments":{"savings_account":{"available":true,"localName":"Savings account","note":"Peso savings accounts are standard; balances up to PHP 1 million per bank are insured by PDIC."},"fdr_3m":{"available":true,"localName":"Time deposit","localNameEn":"3-month time deposit"},"fdr_1y":{"available":true,"localName":"Time deposit","localNameEn":"1-year time deposit"},"dps":{"available":true,"localName":"Pag-IBIG MP2","localNameEn":"Modified Pag-IBIG 2 (government voluntary 5-year savings)","note":"Government (Pag-IBIG Fund) voluntary savings scheme with a 5-year term and flexible monthly payments; dividends declared yearly; not a bank product."},"sanchayapatra_5y":{"available":true,"localName":"Retail Treasury Bond","localNameEn":"Retail Treasury Bond (RTB)","note":"Sold by the Bureau of the Treasury to individuals in periodic offerings through banks; coupon set at each issue."},"tbill_91d":{"available":true,"localName":"Treasury bill","localNameEn":"Government Treasury bill","note":"Auctioned weekly by the Bureau of the Treasury; individuals usually buy through banks.","sourceUrl":"https://www.bsp.gov.ph/Statistics/keystat/sefi.pdf"},"tbond_5y":{"available":true,"localName":"Fixed Rate Treasury Note","localNameEn":"Fixed Rate Treasury Note (FXTN)"},"tbond_10y":{"available":true,"localName":"Fixed Rate Treasury Note","localNameEn":"Fixed Rate Treasury Note (FXTN)","sourceUrl":"https://tradingeconomics.com/philippines/government-bond-yield"},"equity_fund":{"available":true,"localName":"Unit Investment Trust Fund","localNameEn":"UITF or mutual fund (equity index fund)","note":"Bank-run UITFs and SEC-registered mutual funds, including PSEi index funds, are sold to retail investors."},"gold":{"available":true,"localName":"Ginto","localNameEn":"Gold","note":"Gold jewellery and bullion can be bought legally from dealers."}},"institutions":{"centralBank":{"name":"Bangko Sentral ng Pilipinas","url":"https://www.bsp.gov.ph/"},"insuranceRegulator":{"name":"Insurance Commission","url":"https://www.insurance.gov.ph/"},"insuranceComplaints":{"name":"Insurance Commission (public assistance and complaints)","url":"https://www.insurance.gov.ph/","note":"No separate insurance ombudsman; the Commission handles policyholder complaints."},"pensionScheme":{"name":"Social Security System (SSS)","url":"https://www.sss.gov.ph/","note":"Government employees are covered by GSIS (https://www.gsis.gov.ph/)."},"oldAgeAllowance":{"name":"Social Pension for Indigent Senior Citizens, Department of Social Welfare and Development","url":"https://www.dswd.gov.ph/"},"publicHealthCover":{"name":"PhilHealth (Philippine Health Insurance Corporation)","url":"https://www.philhealth.gov.ph/"},"depositInsurance":{"name":"Philippine Deposit Insurance Corporation","url":"https://www.pdic.gov.ph/"},"statistics":{"name":"Philippine Statistics Authority","url":"https://psa.gov.ph/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PH', 1, 'bank_deposit_avg_rate', 0.0434, NULL, 'sourced', 'BSP Selected Economic and Financial Indicators (30 October 2026)', 'https://www.bsp.gov.ph/Statistics/keystat/sefi.pdf', '2026-10-07', 'Average bank interest rate on time deposits, all maturities, for the week ending 7 October 2026 (January-September 2026 average 3.72%). Savings deposits pay much less.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PH', 1, 'credit_card_rate_cap', 0.24, NULL, 'sourced', 'BSP Circular No. 1098, Series of 2020 (ceiling on credit card interest)', 'https://www.bsp.gov.ph/Regulations/Issuances/2020/c1098.pdf', '2020-11-03', 'Annual cap of 24% on credit card interest (installment loans: 1% a month add-on), effective 3 November 2020 and subject to BSP review every six months; figure older than 2025 and later revisions could not be checked.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PH', 1, 'deposit_insurance_limit', 1000000, NULL, 'sourced', 'Philippine Deposit Insurance Corporation', 'https://www.pdic.gov.ph/mdic', '2025-03-15', 'Maximum deposit insurance coverage raised from PHP 500,000 to PHP 1 million per depositor per bank, effective 15 March 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PH', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Pag-IBIG MP2 (government 5-year voluntary savings with flexible monthly payments) declares a yearly dividend, but the Pag-IBIG site blocked access (verification screen) so the latest rate could not be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PH', 1, 'equity_return_base', 0.07, NULL, 'assumption', 'BSP indicators: PSE composite index 5,706 on 29 Oct 2026 vs 6,854 average in 2021; 364-day T-bill 6.58% (5.3% after 20% tax)', 'https://www.bsp.gov.ph/Statistics/keystat/sefi.pdf', '2026-10-31', 'After-tax 1-year bill rate of about 5.3% plus a premium under 2 points, kept low because the local index has a negative 10-year price record.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PH', 1, 'equity_return_high', 0.1, NULL, 'assumption', 'BSP indicators: PSE composite index and price-earnings ratio 9.9 in 2026', 'https://www.bsp.gov.ph/Statistics/keystat/sefi.pdf', '2026-10-31', 'High case if valuations (P/E near 10, a decade low) recover toward their long-run level.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PH', 1, 'equity_return_low', 0.03, NULL, 'assumption', 'BSP indicators: PSE composite index 5,706 on 29 Oct 2026 vs 6,854 average in 2021; 364-day T-bill 6.58%', 'https://www.bsp.gov.ph/Statistics/keystat/sefi.pdf', '2026-10-31', 'Low case below the after-tax bill rate, since the PSE index is lower now than five and ten years ago.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PH', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'BSP time deposit rates by tenor could not be retrieved (data files blocked, HTTP 403) and bank rate pages were not reachable; the BSP average for all time deposit maturities is in bank_deposit_avg_rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PH', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'BSP time deposit rates by tenor could not be retrieved (data files blocked, HTTP 403) and bank rate pages were not reachable; the BSP average for all time deposit maturities is in bank_deposit_avg_rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PH', 1, 'fixed_income_return_base', 0.045, NULL, 'assumption', 'BSP indicators: 91-day to 364-day T-bills 6.26-6.58%; time deposits 4.34%; 20% final tax', 'https://www.bsp.gov.ph/Statistics/keystat/sefi.pdf', '2026-10-31', 'Base case: a mix of time deposits and Treasury bills or Retail Treasury Bonds after the 20% final tax, allowing for rates falling back from 2026 highs.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PH', 1, 'fixed_income_return_high', 0.06, NULL, 'assumption', '10-year government bond yield 8.21% (27 Oct 2026) less 20% final tax', 'https://tradingeconomics.com/philippines/government-bond-yield', '2026-10-31', 'High case: locking in long government bonds at about 8.2% (6.6% after tax), allowing for some reinvestment at lower rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PH', 1, 'fixed_income_return_low', 0.035, NULL, 'assumption', 'BSP indicators: average time deposit rate 4.34% less 20% final tax', 'https://www.bsp.gov.ph/Statistics/keystat/sefi.pdf', '2026-10-31', 'Low case: bank time deposits at about 4.3% less the 20% final tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PH', 1, 'goal_inflation_education', 0.05, NULL, 'assumption', 'Trading Economics (PSA CPI): education inflation 4.0% in June and 1.9% in July 2026', 'https://tradingeconomics.com/philippines/inflation-cpi', '2026-10-31', 'Education CPI runs near headline, but private tuition rises faster, so we plan with 5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PH', 1, 'goal_inflation_health', 0.06, NULL, 'assumption', 'Trading Economics (PSA CPI): health inflation 5.0% in August 2026', 'https://tradingeconomics.com/philippines/inflation-cpi', '2026-10-31', 'Health prices rose about 5% a year in 2026; we plan with 6% for private hospital and medicine costs above headline.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PH', 1, 'gold_return_base', 0.07, NULL, 'assumption', 'BSP indicators: peso per US dollar averaged 49.3 in 2021 and 63.1 in October 2026', 'https://www.bsp.gov.ph/Statistics/keystat/sefi.pdf', '2026-10-31', 'Long-run dollar gold trend of about 4-5% plus peso depreciation of about 2-3% a year.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PH', 1, 'gold_return_high', 0.1, NULL, 'assumption', 'BSP indicators: peso per US dollar averaged 49.3 in 2021 and 63.1 in October 2026', 'https://www.bsp.gov.ph/Statistics/keystat/sefi.pdf', '2026-10-31', 'High case with strong dollar gold and faster peso depreciation, as in 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PH', 1, 'gold_return_low', 0.03, NULL, 'assumption', 'BSP indicators: peso per US dollar averaged 49.3 in 2021 and 63.1 in October 2026', 'https://www.bsp.gov.ph/Statistics/keystat/sefi.pdf', '2026-10-31', 'Low case: weak dollar gold and a stable peso.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PH', 1, 'gratuity_rule', NULL, '{"daysPerYear":22.5,"daysPerYearAfter":null,"afterYears":null,"daysPerMonth":26}', 'sourced', 'Republic Act No. 7641 (Retirement Pay Law, Labor Code Art. 302) via Lawphil', 'https://lawphil.net/statutes/repacts/ra1992/ra_7641_1992.html', '1992-12-09', 'Where no company plan exists, employees aged 60-65 with at least 5 years'' service get half a month''s salary per year: 15 days plus 1/12 of the 13th-month pay plus up to 5 days'' service incentive leave = 22.5 days (law of 1992, older than 2025, still in force; retail, service and agricultural firms with 10 or fewer workers are exempt). Daily rate taken as monthly salary / 26 working days (common practice for a six-day week).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PH', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched for typical private hospital bills: no reachable published figure (PhilHealth case-rate pages were not accessible).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PH', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published HMO or health insurance premium table by age could be reached.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PH', 1, 'inflation_cpi', 0.072, NULL, 'sourced', 'Trading Economics (Philippine Statistics Authority CPI)', 'https://tradingeconomics.com/philippines/inflation-cpi', '2026-09-30', 'Secondary source: headline inflation 7.2% year on year in September 2026 (6.1% in August); PSA site returned HTTP 403. The BSP indicators sheet gives a January-September 2026 average of 5.4%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PH', 1, 'inflation_projection', 0.04, NULL, 'assumption', 'BSP inflation target 2-4%; CPI 2021-2025 average about 4.1% (BSP indicators sheet)', 'https://www.bsp.gov.ph/Statistics/keystat/sefi.pdf', '2026-10-31', 'The BSP targets 3% plus or minus one point, but inflation averaged about 4.1% in 2021-2025 and is running above target in 2026, so we plan with the top of the band, 4%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PH', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life is sold in the Philippines, but no published per-1,000 premium rates by age could be reached; insurers quote individually.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PH', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Insurance Commission site returned HTTP 403; no industry-wide life claim settlement ratio found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PH', 1, 'life_expectancy', 69.946, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=PH', '2024-12-31', '2024 figure (older than 2025). UN WPP 2024 (via populationpyramid.net) gives 70.2 for 2026 (men 67.2, women 73.2).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PH', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":17.6,"men":15.9,"women":19.3},{"age":65,"total":14.2,"men":12.7,"women":15.4},{"age":70,"total":11,"men":9.9,"women":12},{"age":80,"total":6.1,"men":5.6,"women":6.5}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/philippines/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026 (mid-year reference); totals at 60, 70 and 80 are the mean of men and women (the page gives a total only at 65, 14.2).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PH', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":60,"womenAge":60,"over90Monthly":null,"meansTested":true}', 'sourced', 'Republic Act No. 11916 (Social Pension for Indigent Senior Citizens) via Lawphil', 'https://lawphil.net/statutes/repacts/ra2022/ra_11916_2022.html', '2022-07-30', 'Senior citizens are people aged 60 and over (RA 7432 as amended); the stipend is only for seniors who qualify as indigent under DSWD''s means test. Law dates from 2022 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PH', 1, 'old_age_allowance_monthly', 1000, NULL, 'sourced', 'Republic Act No. 11916 (Social Pension for Indigent Senior Citizens) via Lawphil', 'https://lawphil.net/statutes/repacts/ra2022/ra_11916_2022.html', '2022-07-30', 'Indigent senior citizens (60 and over) receive a monthly stipend of not less than PHP 1,000 (doubled from PHP 500), paid through DSWD; the law dates from 2022 (older than 2025) and no later change to the amount was found. Only for seniors who pass the DSWD indigency test.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PH', 1, 'oop_health_share', 0.4436, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=PH', '2023-12-31', '2023 figure (older than 2025), latest available in World Bank WDI.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PH', 1, 'policy_rate', 0.055, NULL, 'sourced', 'BSP Selected Economic and Financial Indicators (30 October 2026)', 'https://www.bsp.gov.ph/Statistics/keystat/sefi.pdf', '2026-10-23', 'Monetary Board raised the Target RRP rate by 50 basis points to 5.50% effective 23 October 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PH', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":60,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'Social Security System: retirement benefit', 'https://www.sss.gov.ph/retirement-benefit/', '2026-10-31', 'SSS is a defined-benefit pension for private, self-employed and OFW members: from 60 (separated) or 65, with 120 monthly contributions; minimum pension PHP 1,200 (10 years'' credited service) or 2,400 (20 years); 13th-month pension each December; the SSS page describes no automatic inflation indexing.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PH', 1, 'retirement_accumulation_return_base', 0.06, NULL, 'assumption', 'BSP indicators: T-bill rates, PSE index record', 'https://www.bsp.gov.ph/Statistics/keystat/sefi.pdf', '2026-10-31', 'Base case: about half equity at 7% and half safe fixed income at 4.5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PH', 1, 'retirement_accumulation_return_high', 0.08, NULL, 'assumption', 'BSP indicators: T-bill rates, PSE index record', 'https://www.bsp.gov.ph/Statistics/keystat/sefi.pdf', '2026-10-31', 'High case if equities recover from decade-low valuations.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PH', 1, 'retirement_accumulation_return_low', 0.04, NULL, 'assumption', 'BSP indicators: T-bill rates, PSE index record', 'https://www.bsp.gov.ph/Statistics/keystat/sefi.pdf', '2026-10-31', 'Low case for a balanced mix given the weak local equity record.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PH', 1, 'retirement_age_default', 60, NULL, 'sourced', 'Social Security System: retirement benefit', 'https://www.sss.gov.ph/retirement-benefit/', '2026-10-31', 'SSS pension from 60 if separated from work (optional), or at 65 regardless (technical retirement), with at least 120 monthly contributions. Labor Code (RA 7641): optional retirement at 60, compulsory at 65. Same for men and women.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PH', 1, 'retirement_age_government', 65, NULL, 'sourced', 'Republic Act No. 8291 (GSIS Act of 1997), Section 13 (via Lawphil)', 'https://lawphil.net/statutes/repacts/ra1997/ra_8291_1997.html', '1997-05-30', 'Compulsory retirement at 65 with at least 15 years of service; optional retirement from 60 with at least 15 years of service. The law dates from 1997 (older than 2025) and still applies.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PH', 1, 'retirement_return_base', 0.045, NULL, 'assumption', 'BSP indicators: 364-day T-bill 6.58% (5.26% after 20% final tax)', 'https://www.bsp.gov.ph/Statistics/keystat/sefi.pdf', '2026-10-31', 'Base case below the after-tax 1-year T-bill rate of about 5.3%, allowing for rates easing from 2026 highs.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PH', 1, 'retirement_return_high', 0.055, NULL, 'assumption', '10-year government bond yield 8.21% (27 Oct 2026) less 20% final tax', 'https://tradingeconomics.com/philippines/government-bond-yield', '2026-10-31', 'High case: laddered Retail Treasury Bonds and long government bonds after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PH', 1, 'retirement_return_low', 0.035, NULL, 'assumption', 'BSP indicators: average time deposit rate 4.34% less 20% final tax', 'https://www.bsp.gov.ph/Statistics/keystat/sefi.pdf', '2026-10-31', 'Low case: time deposits after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PH', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Retail Treasury Bonds (RTBs) are sold to individuals by the Bureau of the Treasury, but the Treasury site returned empty pages and no current RTB coupon could be confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PH', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched BSP statistics (deposit rate tables blocked) and large bank rate pages (not reachable): no current typical savings rate found; large banks have historically paid well under 1% on regular savings.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PH', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":11.7},{"year":2040,"value":7.9},{"year":2065,"value":4}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/philippines/2040/', '2025-12-31', '100 / old-age dependency ratio: 8.53 (2025, World Bank), 12.6 (2040) and 25.3 (2065, populationpyramid.net/philippines/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PH', 1, 'tax_bank_interest', 0.2, NULL, 'sourced', 'PwC Worldwide Tax Summaries: Philippines, individual income determination', 'https://taxsummaries.pwc.com/philippines/individual/income-determination', '2026-07-02', 'Philippine-source interest is subject to a 20% final tax; long-term deposits and investments evidenced by certificates can be exempt under conditions; foreign currency deposit interest is taxed at 15%. Page last reviewed 2 July 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PH', 1, 'tax_sanchayapatra_profit', 0.2, NULL, 'sourced', 'PwC Worldwide Tax Summaries: Philippines, individual income determination', 'https://taxsummaries.pwc.com/philippines/individual/income-determination', '2026-07-02', 'Retail Treasury Bond interest is Philippine-source interest, taxed at the 20% final tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PH', 1, 'tbill_91d_rate', 0.0626, NULL, 'sourced', 'BSP Selected Economic and Financial Indicators (30 October 2026)', 'https://www.bsp.gov.ph/Statistics/keystat/sefi.pdf', '2026-10-26', '91-day T-bill auction rate 6.26% on 26 October 2026 (182-day 6.43%, 364-day 6.58%), up from a 5.08% January-October average after the October policy rate rise.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PH', 1, 'tbond_10y_rate', 0.0821, NULL, 'sourced', 'Trading Economics (Philippines 10-year government bond yield)', 'https://tradingeconomics.com/philippines/government-bond-yield', '2026-10-27', 'Secondary source: 10-year yield 8.21% on 27 October 2026, the highest since May 2010 (8.10% on 22 October); the page shows 8.15% on 3 November 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PH', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No source for the current 5-year benchmark yield was reachable (BVAL and Bureau of the Treasury pages blocked or empty).', 0);
