INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PK', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":60,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'Employees'' Old-Age Benefits Institution, Benefits/Pension and contribution rates', 'http://www.eobi.gov.pk/introduction/Pension.html', '2026-10-31', 'EOBI: employer 5% plus employee 1% of the minimum wage; pension = average minimum monthly wage x years of insurable employment / 50 (2% a year) after 15 years; minimum Rs 10,000 a month per the EOBI page (a later increase may apply); women from 55; raised by government decision, not indexed. EOBI''s site serves this page over http only.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PK', 1, 'retirement_accumulation_return_base', 0.11, NULL, 'assumption', 'Balanced mix: half fixed income (10%), half equity (13%)', 'https://savings.gov.pk/regular-income-certificates/', '2026-10-31', 'Close to the average of the base fixed-income and equity cases, rounded down.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PK', 1, 'retirement_accumulation_return_high', 0.14, NULL, 'assumption', 'Balanced mix with high-case equity', 'https://tradingeconomics.com/pakistan/stock-market', '2026-10-31', 'High case for a balanced mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PK', 1, 'retirement_accumulation_return_low', 0.08, NULL, 'assumption', 'Balanced mix of savings certificates and KSE-100 equity', 'https://savings.gov.pk/regular-income-certificates/', '2026-10-31', 'Low case for a balanced mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PK', 1, 'retirement_age_default', 60, NULL, 'sourced', 'Employees'' Old-Age Benefits Act 1976, section 22 (EOBI)', 'http://www.eobi.gov.pk/rules/eobilaw.html', '2026-10-31', 'Old-age pension over age 60 for men and 55 for women, with at least 15 years of contributions; EOBI''s site serves this page over http only.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PK', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'Could not reach a primary or secondary page stating the civil servants'' superannuation age (Civil Servants Act 1973).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PK', 1, 'retirement_return_base', 0.095, NULL, 'assumption', 'National Savings 1-year short-term certificate 11.72% less 15% tax (9.96%)', 'https://savings.gov.pk/regular-income-certificates/', '2026-10-31', 'Kept below the after-tax 1-year government savings rate because bill and deposit rates were not reachable.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PK', 1, 'retirement_return_high', 0.11, NULL, 'assumption', 'Behbood and Pensioners'' Benefit accounts 12.96% less 15% tax', 'https://savings.gov.pk/regular-income-certificates/', '2026-10-31', 'High case using the scheme reserved for seniors and pensioners.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PK', 1, 'retirement_return_low', 0.08, NULL, 'assumption', 'National Savings short-term certificates after 15% tax', 'https://savings.gov.pk/regular-income-certificates/', '2026-10-31', 'Low case if savings rates fall toward the inflation target.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PK', 1, 'sanchayapatra_5y_rate', 0.1212, NULL, 'sourced', 'National Savings Pakistan, Regular Income Certificates (profit rates w.e.f. 21 October 2026)', 'https://savings.gov.pk/regular-income-certificates/', '2026-10-21', 'Regular Income Certificate (5 years, monthly profit); Behbood and Pensioners'' Benefit accounts 12.96%; Special Savings Certificates (3 years) 12% to 12.8%', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PK', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'sbp.org.pk (minimum savings deposit rate rule and deposit rate statistics) blocked automated access; no other current source found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PK', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":13.6},{"year":2040,"value":11.8},{"year":2065,"value":7.4}]}', 'sourced', 'UN World Population Prospects 2024 old-age dependency ratio (via Our World in Data)', 'https://ourworldindata.org/grapher/age-dependency-ratio-old?country=~PAK', '2025-07-01', '100 / old-age dependency ratio (7.3 in 2025, 8.5 in 2040, 13.4 in 2065, medium variant)', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PK', 1, 'tax_bank_interest', 0.2, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Pakistan, Individual income determination', 'https://taxsummaries.pwc.com/pakistan/individual/income-determination', '2026-08-24', 'Final tax 20% on bank deposit interest for individuals with total income up to PKR 5 million; doubled for inactive taxpayers', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PK', 1, 'tax_sanchayapatra_profit', 0.15, NULL, 'sourced', 'National Savings Pakistan, Regular Income Certificates (Tax & Zakat)', 'https://savings.gov.pk/regular-income-certificates/', '2026-10-21', '15% withholding for persons on the Active Taxpayer List, 30% for others, irrespective of amount; RIC is exempt from zakat. PwC also lists 15% final tax on interest from non-bank sources', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PK', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'State Bank of Pakistan auction results blocked automated access; secondary sources showed only stale 3-month yields.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PK', 1, 'tbond_10y_rate', 0.1279, NULL, 'sourced', 'Trading Economics, Pakistan 10-year government bond yield', 'https://tradingeconomics.com/pakistan/government-bond-yield', '2026-10-30', 'Secondary market yield; secondary source because sbp.org.pk blocked automated access (12.82% on 2 November 2026 after +0.03 points)', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PK', 1, 'tbond_5y_rate', 0.1267, NULL, 'sourced', 'Investing.com Pakistan government bond yields', 'https://www.investing.com/rates-bonds/pakistan-government-bonds', '2026-10-30', 'Secondary market yield from a market-data publisher; secondary source because sbp.org.pk blocked automated access (12.68% on 3 November 2026)', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('PL', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"PL","iso3":"POL","nameEn":"Poland","nameNative":"Polska","region":"europe_central_asia","languages":["pl","en","uk","de","ru"],"currency":{"code":"PLN","symbol":"zł","decimals":2,"compact":"intl","usdRate":{"value":3.9251,"status":"sourced","sourceName":"Narodowy Bank Polski, average exchange rate table A (USD)","sourceUrl":"https://api.nbp.pl/api/exchangerates/rates/a/usd/2026-10-30/?format=json","asOf":"2026-10-30","note":"PLN 3.9251 per US dollar on 30 October 2026 (table 212/A/NBP/2026); World Bank 2025 average 3.76."}},"instruments":{"savings_account":{"available":true,"localName":"Konto oszczędnościowe","localNameEn":"Savings account","sourceUrl":"https://data-api.ecb.europa.eu/service/data/MIR/M.PL.B.L21.A.R.A.2250.PLN.N"},"fdr_3m":{"available":true,"localName":"Lokata terminowa (3 miesiące)","localNameEn":"Term deposit (3 months)"},"fdr_1y":{"available":true,"localName":"Lokata terminowa (12 miesięcy)","localNameEn":"Term deposit (12 months)","sourceUrl":"https://data-api.ecb.europa.eu/service/data/MIR/M.PL.B.L22.F.R.A.2250.PLN.N"},"dps":{"available":false,"localName":null,"localNameEn":"Recurring deposit","note":"No standard monthly recurring-deposit product; regular saving is usually done through savings accounts or retail treasury bonds."},"sanchayapatra_5y":{"available":true,"localName":"Obligacje skarbowe oszczędnościowe (COI, 4-letnie)","localNameEn":"Retail treasury savings bonds (4-year indexed, COI)","note":"Sold monthly by the Ministry of Finance from PLN 100 per bond; year 1 fixed, later years CPI plus a margin. 1-, 2-, 3-, 6-, 10- and 12-year series also exist.","sourceUrl":"https://www.obligacjeskarbowe.pl/oferta-obligacji/obligacje-4-letnie-coi/"},"tbill_91d":{"available":false,"localName":"Bony skarbowe","localNameEn":"Treasury bills","note":"Treasury bills are sold only at wholesale auctions; individuals can buy the 3-month retail OTS savings bond instead."},"tbond_5y":{"available":true,"localName":"Obligacje skarbowe","localNameEn":"Treasury bonds","note":"Marketable treasury bonds trade on the exchange and through brokerage accounts."},"tbond_10y":{"available":true,"localName":"Obligacje skarbowe","localNameEn":"Treasury bonds","sourceUrl":"https://tradingeconomics.com/poland/government-bond-yield"},"equity_fund":{"available":true,"localName":"Fundusz inwestycyjny","localNameEn":"Investment funds and index funds (ETFs)","note":"Retail mutual funds and exchange-traded index funds are widely available; IKE and IKZE retirement accounts give tax relief."},"gold":{"available":true,"localName":"Złoto inwestycyjne","localNameEn":"Investment gold (bars and coins)","note":"Buying physical investment gold is legal and VAT-exempt under EU rules."}},"institutions":{"centralBank":{"name":"Narodowy Bank Polski (National Bank of Poland)","url":"https://nbp.pl/en/"},"insuranceRegulator":{"name":"Polish Financial Supervision Authority (KNF)","url":"https://www.knf.gov.pl/en/"},"insuranceComplaints":{"name":"Financial Ombudsman (Rzecznik Finansowy)","url":"https://rf.gov.pl/en/","note":"Handles complaints and out-of-court disputes between customers and insurers or banks."},"pensionScheme":{"name":"Social Insurance Institution (ZUS), old-age pensions","url":"https://www.zus.pl/en/"},"oldAgeAllowance":{"name":"Permanent allowance (zasiłek stały), Ministry of Family, Labour and Social Policy","url":"https://www.gov.pl/web/rodzina/zasilek-staly","note":"Means-tested social assistance paid by the municipal social assistance centre (OPS)."},"publicHealthCover":{"name":"National Health Fund (NFZ)","url":"https://www.nfz.gov.pl/"},"depositInsurance":{"name":"Bank Guarantee Fund (BFG)","url":"https://bfg.pl/en/"},"statistics":{"name":"Statistics Poland (GUS)","url":"https://stat.gov.pl/en/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PL', 1, 'bank_deposit_avg_rate', 0.0295, NULL, 'sourced', 'ECB MFI interest rate statistics (reported by NBP): household zloty deposits with agreed maturity up to 1 year, new business', 'https://data-api.ecb.europa.eu/service/data/MIR/M.PL.B.L22.F.R.A.2250.PLN.N', '2026-09-30', 'No all-maturity new-business average is published for Poland in the ECB dataset; deposits up to 1 year were PLN 92.6 billion of new household term deposits in September 2026 against PLN 0.5 billion for 1-2 years, so their weighted average (2.95%) is used. The rate on all outstanding household term deposits up to 2 years was 2.74% (ECB MIR). The World Bank has no FR.INR.DPST figure for Poland.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PL', 1, 'credit_card_rate_cap', 0.1543, NULL, 'sourced', 'ECB MFI interest rate statistics (reported by NBP): Polish banks, extended credit card credit to households', 'https://data-api.ecb.europa.eu/service/data/MIR/M.PL.B.A2Z3.A.R.A.2250.PLN.N', '2026-09-30', 'Typical rate: average 15.43% in September 2026 (15.18% in August). The Civil Code caps contractual interest at twice the sum of the NBP reference rate and 3.5 points, 14.5% a year with the reference rate at 3.75%; the ECB series is an annualised (compounded) rate, so it can sit slightly above the nominal cap.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PL', 1, 'deposit_insurance_limit', 439550, NULL, 'sourced', 'Bank Guarantee Fund (BFG), amount of the guarantee', 'https://bfg.pl/gwarantowanie-depozytow/zasady-gwarantowania-depozytow/wysokosc-gwarancji-bfg/', '2026-10-30', 'Zloty equivalent of EUR 100,000 per depositor per bank, converted at the NBP mid rate EUR 1 = PLN 4.3955 (30 October 2026). Up to EUR 200,000 for some temporary high balances (home sale, inheritance, insurance payouts).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PL', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No standard monthly recurring-deposit product with a published average rate was found for Poland.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PL', 1, 'equity_return_base', 0.07, NULL, 'assumption', 'WIG total-return index (Trading Economics); after-tax 1-year retail bond ROR 3.24%', 'https://tradingeconomics.com/poland/stock-market', '2026-10-31', 'Base case: about 3.75 points over the after-tax 1-year government savings bond, below the WIG''s strong recent record because that run was driven by a few years of re-rating.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PL', 1, 'equity_return_high', 0.1, NULL, 'assumption', 'WIG total-return index (Trading Economics), roughly 12% a year since 2016', 'https://tradingeconomics.com/poland/stock-market', '2026-10-31', 'High case: Polish and diversified equity funds keep close to the WIG''s record of the last decade.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PL', 1, 'equity_return_low', 0.04, NULL, 'assumption', 'WIG index 157,676 on 30 Oct 2026, up 41% in a year (Trading Economics); after-tax 1-year deposit 2.4%', 'https://tradingeconomics.com/poland/stock-market', '2026-10-31', 'Low case: Polish shares give back part of the 2025-26 rally and earn only a little more than after-tax savings bonds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PL', 1, 'fdr_1y_rate', 0.0295, NULL, 'sourced', 'ECB MFI interest rate statistics (reported by NBP): household zloty deposits with agreed maturity up to 1 year, new business', 'https://data-api.ecb.europa.eu/service/data/MIR/M.PL.B.L22.F.R.A.2250.PLN.N', '2026-09-30', 'Bucket covers all fixed terms up to one year (2.94% in August 2026); 1-2 year deposits paid 1.91% in September 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PL', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'NBP and the ECB publish household term deposits up to 1 year as one bucket (2.95% in September 2026); no separate 3-month average was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PL', 1, 'fixed_income_return_base', 0.032, NULL, 'assumption', '1-year retail bond ROR 4.00% and 4-year COI 4.75% less 19% tax (Ministry of Finance)', 'https://www.obligacjeskarbowe.pl/oferta-obligacji/obligacje-4-letnie-coi/', '2026-10-31', 'Base case: mostly retail treasury savings bonds after the 19% tax, allowing for lower rates later.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PL', 1, 'fixed_income_return_high', 0.043, NULL, 'assumption', '10-year retail bond EDO 5.35% less 19% tax = 4.3% (Ministry of Finance)', 'https://www.obligacjeskarbowe.pl/oferta-obligacji/obligacje-4-letnie-coi/', '2026-10-31', 'High case: long inflation-indexed retail treasury bonds at today''s margins, or the same bonds held tax-free in an IKE account.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PL', 1, 'fixed_income_return_low', 0.024, NULL, 'assumption', 'Household deposits up to 1 year 2.95% less 19% tax = 2.4% (ECB MIR, September 2026)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.PL.B.L22.F.R.A.2250.PLN.N', '2026-10-31', 'Low case: after-tax bank term deposits only.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PL', 1, 'goal_inflation_education', 0.055, NULL, 'assumption', 'Eurostat/ECB HICP Poland, education: 6.7% year on year in December 2025', 'https://data-api.ecb.europa.eu/service/data/ICP/M.PL.N.100000.4.ANR', '2026-10-31', 'Education prices rose 6.7% in 2025, well above general inflation; planning uses 5.5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PL', 1, 'goal_inflation_health', 0.05, NULL, 'assumption', 'Eurostat/ECB HICP Poland, health: 5.0% year on year in December 2025', 'https://data-api.ecb.europa.eu/service/data/ICP/M.PL.N.060000.4.ANR', '2026-10-31', 'Health prices rose 5.0% in 2025, double general HICP inflation (2.5%), so planning uses 5%, 1.5 points above general inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PL', 1, 'gold_return_base', 0.05, NULL, 'assumption', 'Gold USD price history (Trading Economics); NBP 2.5% inflation target', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Base case: dollar gold rises with world inflation plus a little, and the zloty loses about 1% a year against the dollar over the long run.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PL', 1, 'gold_return_high', 0.09, NULL, 'assumption', 'Gold USD price history (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'High case: a repeat of gold''s strong 2005-2025 trend in zloty terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PL', 1, 'gold_return_low', 0.02, NULL, 'assumption', 'Gold USD price history (Trading Economics); zloty per dollar 3.93 (NBP, 30 Oct 2026)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Low case: gold stalls after the 2025-26 spike and the zloty stays firm against the dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PL', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Labour Code gives a one-off retirement severance (odprawa emerytalna) of one month''s pay on retiring, and severance on collective dismissal of 1-3 months'' pay by length of service; neither is a days-per-year gratuity, and no source stating it was read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PL', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'Hospital care is free under the National Health Fund (NFZ); no official figure for the out-of-pocket cost of a major private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PL', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Private health insurance is sold in Poland, but no published premium table per PLN 100,000 of cover from a regulator or public source was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PL', 1, 'inflation_cpi', 0.035, NULL, 'sourced', 'Statistics Poland (GUS), flash estimate of the consumer price index in October 2026', 'https://stat.gov.pl/en/topics/prices-trade/price-indices/flash-estimate-of-the-consumer-price-index-in-october-2026,21,46.html', '2026-10-31', 'Consumer prices were 3.5% higher than in October 2025 (flash estimate released 30 October 2026; -0.4% on the month). World Bank 2025 average 3.8%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PL', 1, 'inflation_projection', 0.035, NULL, 'assumption', 'NBP inflation target 2.5% +/- 1 point; Polish HICP 2021-2025 average 7.3% (ECB ICP)', 'https://data-api.ecb.europa.eu/service/data/ICP/A.PL.N.000000.4.AVR', '2026-10-31', 'The NBP targets 2.5% but inflation has run above the target for most of the last five years (13.2% in 2022) and is 3.5% now, so planning uses 3.5%, at the top of the tolerance band.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PL', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life cover is sold in Poland, but no regulator or official premium table per sum insured was found; only individual company quotes exist.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PL', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Polish Financial Supervision Authority (KNF) publishes insurance market statistics, but no industry-wide life claim settlement ratio was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PL', 1, 'life_expectancy', 79.2, NULL, 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/poland', '2026-07-01', 'Men 75.5, women 82.7 (UN WPP estimate for 2026); World Bank 2024 figure 78.4.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PL', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":22.8,"men":20.2,"women":25},{"age":65,"total":19,"men":16.8,"women":20.8},{"age":70,"total":15.5,"men":13.6,"women":16.8},{"age":80,"total":9,"men":8.1,"women":9.6}]}', 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/poland', '2026-07-01', 'Remaining years from georank''s expected age at death by current age (UN WPP 2026 estimate).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PL', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":65,"womenAge":60,"over90Monthly":null,"meansTested":true}', 'sourced', 'Ministry of Family, Labour and Social Policy, permanent allowance (zasiłek stały); European Commission, Your social security rights in Poland (July 2026)', 'https://www.gov.pl/web/rodzina/zasilek-staly', '2026-07-31', 'Adults unable to work because of age (pension age: 65 men, 60 women) whose income is below the social assistance threshold (PLN 1,010 a month for a single person, PLN 823 per person in a family).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PL', 1, 'old_age_allowance_monthly', 1229, NULL, 'sourced', 'Ministry of Family, Labour and Social Policy, permanent allowance (zasiłek stały)', 'https://www.gov.pl/web/rodzina/zasilek-staly', '2025-01-01', 'Maximum for a single person: 130% of the single-person income threshold minus own income, capped at PLN 1,229 a month (minimum PLN 100); the cap set from 1 January 2025 is still the one shown by the ministry in 2026 (thresholds are reviewed every three years). Paid by the municipal social assistance centre to people unable to work because of age (pension age) or disability. Poland has no universal social pension.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PL', 1, 'oop_health_share', 0.1621, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=PL', '2024-12-31', 'Out-of-pocket spending was 16.2% of current health expenditure in 2024 (latest available; older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PL', 1, 'policy_rate', 0.0375, NULL, 'sourced', 'Narodowy Bank Polski, NBP base rates (reference rate)', 'https://static.nbp.pl/dane/stopy/stopy_procentowe.xml', '2026-03-05', 'Reference rate 3.75% in force since 5 March 2026 (lombard 4.25%, deposit 3.25%); the NBP rates feed still showed it unchanged at end-October 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PL', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":65,"nomineeUntilAge":null,"inflationLinked":true,"taxFree":false}', 'sourced', 'European Commission, Your social security rights in Poland (July 2026)', 'https://employment-social-affairs.ec.europa.eu/document/download/281c2e4d-bbb3-4a73-93b6-ff3368cb15c6_en', '2026-07-31', 'Compulsory notional-account pension run by ZUS: pension age 65 men and 60 women; the pension equals contributions plus initial capital divided by life expectancy, with a minimum pension of PLN 1,878.91 gross (from 1 March 2025). Pensions are adjusted each 1 March by CPI plus at least 20% of real wage growth, and are taxed as income.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PL', 1, 'retirement_accumulation_return_base', 0.05, NULL, 'assumption', 'Fixed income base 3.2%; equity base 7%', 'https://tradingeconomics.com/poland/stock-market', '2026-10-31', 'Base case: roughly half shares at 7% and half safe fixed income at about 3.2%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PL', 1, 'retirement_accumulation_return_high', 0.07, NULL, 'assumption', 'Equity high 10%; after-tax indexed retail bonds 4.3%', 'https://tradingeconomics.com/poland/stock-market', '2026-10-31', 'High case for a growth-leaning balanced mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PL', 1, 'retirement_accumulation_return_low', 0.035, NULL, 'assumption', 'After-tax deposits 2.4%; WIG record (Trading Economics)', 'https://tradingeconomics.com/poland/stock-market', '2026-10-31', 'Low case for a balanced mix if shares lag.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PL', 1, 'retirement_age_default', 65, NULL, 'sourced', 'European Commission, Your social security rights in Poland (July 2026)', 'https://employment-social-affairs.ec.europa.eu/document/download/281c2e4d-bbb3-4a73-93b6-ff3368cb15c6_en', '2026-07-31', 'Statutory pension age is 65 for men and 60 for women, irrespective of date of birth, since 1 October 2017; the figure shown is the men''s age.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PL', 1, 'retirement_age_government', 65, NULL, 'sourced', 'European Commission, Your social security rights in Poland (July 2026)', 'https://employment-social-affairs.ec.europa.eu/document/download/281c2e4d-bbb3-4a73-93b6-ff3368cb15c6_en', '2026-07-31', 'Civil servants are insured in the general ZUS scheme, so the same pension ages apply (65 men, 60 women); uniformed services and some other groups have separate rules.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PL', 1, 'retirement_return_base', 0.03, NULL, 'assumption', '1-year retail treasury bond ROR 4.00% less 19% tax = 3.24% (Ministry of Finance)', 'https://www.obligacjeskarbowe.pl/oferta-obligacji/obligacje-4-letnie-coi/', '2026-10-31', 'Base case: kept below the after-tax 1-year government savings bond rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PL', 1, 'retirement_return_high', 0.04, NULL, 'assumption', '4-year COI 4.75% and 10-year EDO 5.35% less 19% tax (Ministry of Finance)', 'https://www.obligacjeskarbowe.pl/oferta-obligacji/obligacje-4-letnie-coi/', '2026-10-31', 'High case: mostly inflation-indexed retail treasury bonds held to maturity.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PL', 1, 'retirement_return_low', 0.02, NULL, 'assumption', 'After-tax 1-year deposit 2.4% (ECB MIR, September 2026)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.PL.B.L22.F.R.A.2250.PLN.N', '2026-10-31', 'Low case: after-tax deposits with some further rate cuts.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PL', 1, 'sanchayapatra_5y_rate', 0.0475, NULL, 'sourced', 'Ministry of Finance, Polish retail treasury savings bonds: 4-year indexed bonds COI1030', 'https://www.obligacjeskarbowe.pl/oferta-obligacji/obligacje-4-letnie-coi/', '2026-10-01', '4-year COI series sold 1-31 October 2026: 4.75% in year 1, then CPI + 1.50% (interest paid yearly); the November series COI1130 keeps the same terms. Same offer: 6-year ROS 5.00% (family bond), 10-year EDO 5.35%, 3-year fixed TOS 4.40%, 2-year DOR 4.15%, 1-year ROR 4.00%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PL', 1, 'savings_account_rate', 0.0049, NULL, 'sourced', 'ECB MFI interest rate statistics (reported by NBP): Polish banks, overnight zloty deposits from households', 'https://data-api.ecb.europa.eu/service/data/MIR/M.PL.B.L21.A.R.A.2250.PLN.N', '2026-09-30', 'Average rate on household overnight (current and savings) zloty deposits was 0.49% in September 2026 (0.48% in August). Promotional savings accounts pay more for new money.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PL', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":3.12},{"year":2040,"value":2.47},{"year":2065,"value":1.42}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/poland/2040/', '2025-12-31', '100 / old-age dependency ratio: 32.0 (2025, World Bank), 40.5 (2040) and 70.5 (2065, populationpyramid.net/poland/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PL', 1, 'tax_bank_interest', 0.19, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Poland income determination', 'https://taxsummaries.pwc.com/poland/individual/income-determination', '2026-08-11', 'Flat 19% tax on interest from savings and deposits, withheld by the bank (page reviewed 11 August 2026). Interest inside IKE/IKZE retirement accounts can be tax-free.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PL', 1, 'tax_sanchayapatra_profit', 0.19, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Poland income determination', 'https://taxsummaries.pwc.com/poland/individual/income-determination', '2026-08-11', 'Interest on retail treasury savings bonds is taxed at the same flat 19% as other interest, unless the bonds are held in an IKE or IKZE retirement account.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PL', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No current 3-month treasury bill yield was found; the Ministry of Finance funds itself mainly with bonds and treasury bills are not sold to individuals. The retail 3-month OTS savings bond paid a fixed 2.00% in October 2026 (obligacjeskarbowe.pl).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PL', 1, 'tbond_10y_rate', 0.0638, NULL, 'sourced', 'Trading Economics, Poland 10-year government bond yield (secondary source)', 'https://tradingeconomics.com/poland/government-bond-yield', '2026-10-30', '10-year yield 6.38% on 30 October 2026; the ECB long-term convergence yield for Poland was 6.23% in September 2026 (ECB IRS dataset). Secondary source because the Ministry of Finance and NBP pages did not load.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PL', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 5-year Polish government bond yield could be read from an official or reachable secondary page on 31 October 2026.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('PS', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"PS","iso3":"PSE","nameEn":"Palestine","nameNative":"فلسطين","region":"middle_east_north_africa","languages":["ar","apc","en","he"],"currency":{"code":"ILS","symbol":"₪","decimals":2,"compact":"intl","usdRate":{"value":3.118,"status":"sourced","sourceName":"Bank of Israel statistics API, representative exchange rate USD/ILS (series RER_USD_ILS)","sourceUrl":"https://edge.boi.gov.il/FusionEdgeServer/sdmx/v2/data/dataflow/BOI.STATISTICS/EXR/1.0/RER_USD_ILS?lastNObservations=1&format=csv","asOf":"2026-10-30","note":"Palestine has no currency of its own; the Israeli shekel is used for wages and prices (PCBS measures prices in shekels), while US dollars and Jordanian dinars are used for savings, loans and property. CLDR lists the dinar; the shekel is used here as the everyday currency. 3.118 shekels per US dollar on 30 October 2026."}},"instruments":{"savings_account":{"available":true,"localName":"حساب توفير","localNameEn":"Savings account","note":"Accounts are held in shekels, US dollars or Jordanian dinars."},"fdr_3m":{"available":true,"localName":"وديعة لأجل (3 أشهر)","localNameEn":"Time deposit (3 months)","note":"Deposits are guaranteed up to USD 20,000 per depositor per bank.","sourceUrl":"https://www.pdic.ps/calculator"},"fdr_1y":{"available":true,"localName":"وديعة لأجل (سنة)","localNameEn":"Time deposit (1 year)"},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No standard monthly recurring deposit product was found."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate for individuals was found."},"tbill_91d":{"available":false,"localName":null,"localNameEn":null,"note":"No Palestinian Treasury bills were found."},"tbond_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No Palestinian government bonds were found."},"tbond_10y":{"available":false,"localName":null,"localNameEn":null,"note":"No Palestinian government bonds were found."},"equity_fund":{"available":false,"localName":null,"localNameEn":null,"note":"No locally registered retail equity mutual funds were found; shares are traded on the local stock exchange through licensed brokers."},"gold":{"available":true,"localName":"الذهب","localNameEn":"Gold","note":"Gold is mainly bought as jewellery and small bars from goldsmiths."}},"institutions":{"centralBank":{"name":"Palestine Monetary Authority (PMA)","url":"https://www.pma.ps/"},"insuranceRegulator":{"name":"Palestine Capital Market Authority, insurance directorate","url":"https://www.pcma.ps/insurance/"},"insuranceComplaints":{"name":"Palestine Capital Market Authority, complaints","url":"https://www.pcma.ps/%d8%b4%d9%83%d8%a7%d9%88%d9%89/"},"pensionScheme":null,"oldAgeAllowance":null,"publicHealthCover":{"name":"Ministry of Health, government health insurance","url":"https://www.moh.ps/"},"depositInsurance":{"name":"Palestine Deposit Insurance Corporation (PDIC)","url":"https://www.pdic.ps/"},"statistics":{"name":"Palestinian Central Bureau of Statistics (PCBS)","url":"https://www.pcbs.gov.ps/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PS', 1, 'bank_deposit_avg_rate', 0.0224, NULL, 'sourced', 'World Bank WDI, deposit interest rate (FR.INR.DPST), West Bank and Gaza', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=PS', '2021-12-31', '2.24% for 2021, the latest year in the World Bank series (IMF data); older than 2025, mainly reflects dollar deposits, and is likely different now. The Palestine Monetary Authority website loads its statistics only through scripts, so its interest-rate tables could not be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PS', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap or average credit card rate could be read. The Palestine Monetary Authority website loads its statistics only through scripts, so its interest-rate tables could not be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PS', 1, 'deposit_insurance_limit', 62360, NULL, 'sourced', 'Palestine Deposit Insurance Corporation, deposit guarantee calculator', 'https://www.pdic.ps/calculator', '2026-10-31', 'The calculator caps compensation at USD 20,000 per depositor per member bank (deposits plus cash collateral less loans); converted at 3.118 shekels per dollar (Bank of Israel, 30 October 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PS', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No industry-wide rate for a monthly recurring deposit product was found. The Palestine Monetary Authority website loads its statistics only through scripts, so its interest-rate tables could not be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PS', 1, 'equity_return_base', 0.05, NULL, 'assumption', 'World Bank deposit rate (2.24%, 2021); Bank of Israel rate 3.25%', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=PS', '2026-10-31', 'Base case: under 3 points above the deposit rate, well within the 4-point cap, because the local index has a weak 10-year record and few retail equity funds exist.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PS', 1, 'equity_return_high', 0.08, NULL, 'assumption', 'World Bank deposit rate (2.24%, 2021)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=PS', '2026-10-31', 'High case: a recovery with stronger dividends, or global equity held from abroad.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PS', 1, 'equity_return_low', 0, NULL, 'assumption', 'World Bank deposit rate (2.24%, 2021)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=PS', '2026-10-31', 'Low case: the small local stock market stays flat, as over much of the past decade.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PS', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No current industry-wide 1-year term deposit rate could be read. The Palestine Monetary Authority website loads its statistics only through scripts, so its interest-rate tables could not be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PS', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No current industry-wide 3-month term deposit rate could be read. The Palestine Monetary Authority website loads its statistics only through scripts, so its interest-rate tables could not be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PS', 1, 'fixed_income_return_base', 0.02, NULL, 'assumption', 'World Bank deposit rate (2.24%, 2021); Bank of Israel rate 3.25%', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=PS', '2026-10-31', 'Base case: slightly below the last published average deposit rate, since current rates and the tax on interest could not be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PS', 1, 'fixed_income_return_high', 0.03, NULL, 'assumption', 'Bank of Israel rate 3.25% (October 2026)', 'https://edge.boi.gov.il/FusionEdgeServer/sdmx/v2/data/dataflow/BOI.STATISTICS/EXR/1.0/RER_USD_ILS?lastNObservations=1&format=csv', '2026-10-31', 'High case: longer shekel or dollar deposits near the policy rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PS', 1, 'fixed_income_return_low', 0.01, NULL, 'assumption', 'World Bank deposit rate (2.24%, 2021)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=PS', '2026-10-31', 'Low case: savings and short deposits paying about 1%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PS', 1, 'goal_inflation_education', 0.035, NULL, 'assumption', 'PCBS consumer price index (education group index 108.4 in September 2026, base 2018); inflation assumption 2.5%', 'https://www.pcbs.gov.ps/en/reference/cpi-dashboard/', '2026-10-31', 'Education prices have risen about 1% a year since 2018, but private school and university fees can jump, so 1 point above the 2.5% inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PS', 1, 'goal_inflation_health', 0.035, NULL, 'assumption', 'PCBS consumer price index (health group index 114.9 in September 2026, base 2018); inflation assumption 2.5%', 'https://www.pcbs.gov.ps/en/reference/cpi-dashboard/', '2026-10-31', 'Health prices have risen about 1.6% a year since 2018; 1 point above the 2.5% inflation assumption allows for private care costs rising faster.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PS', 1, 'gold_return_base', 0.035, NULL, 'assumption', 'Bank of Israel representative rate; long-run dollar gold trend', 'https://edge.boi.gov.il/FusionEdgeServer/sdmx/v2/data/dataflow/BOI.STATISTICS/EXR/1.0/RER_USD_ILS?lastNObservations=1&format=csv', '2026-10-31', 'Base case: the long-run dollar gold trend of about 4% a year, slightly reduced because the shekel has tended to strengthen against the dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PS', 1, 'gold_return_high', 0.075, NULL, 'assumption', 'Bank of Israel representative rate; long-run dollar gold trend', 'https://edge.boi.gov.il/FusionEdgeServer/sdmx/v2/data/dataflow/BOI.STATISTICS/EXR/1.0/RER_USD_ILS?lastNObservations=1&format=csv', '2026-10-31', 'High case: strong dollar gold years and a weaker shekel.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PS', 1, 'gold_return_low', 0, NULL, 'assumption', 'Bank of Israel representative rate (3.118 ILS per USD, 30 October 2026; 3.45 in 2025)', 'https://edge.boi.gov.il/FusionEdgeServer/sdmx/v2/data/dataflow/BOI.STATISTICS/EXR/1.0/RER_USD_ILS?lastNObservations=1&format=csv', '2026-10-31', 'Low case: flat dollar gold with a firm shekel.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PS', 1, 'gratuity_rule', NULL, '{"daysPerYear":30,"daysPerYearAfter":null,"afterYears":null,"daysPerMonth":30}', 'sourced', 'Labour Law No. 7 of 2000, Article 45 (Ministry of Labour, Palestinian Gazette text)', 'https://www.mol.pna.ps/uploads/LAWS/15497845920.pdf', '2001-11-30', 'A worker with at least one year of service gets one month''s wage for each year, on the last wage without overtime, with part years counted. Article 42(2): on resignation only one third in the first five years and two thirds in the next five; full after ten years. Law text from 2000, still the labour law in force.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PS', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a major private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PS', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premiums by age were found from a public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PS', 1, 'inflation_cpi', 0.0981, NULL, 'sourced', 'World Bank WDI, inflation, consumer prices (FP.CPI.TOTL.ZG), West Bank and Gaza', 'https://data.worldbank.org/indicator/FP.CPI.TOTL.ZG?locations=PS', '2025-12-31', '9.8% for 2025, the latest full year, used because the latest monthly figure is outside the range this field accepts: Trading Economics, citing PCBS, reports -25.2% year on year for Palestine in September 2026 as Gaza prices fell back from wartime peaks, while West Bank prices rose 3.3%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PS', 1, 'inflation_projection', 0.025, NULL, 'assumption', 'PCBS consumer price index, West Bank annual changes 2019-2025 (about 1.9% average); Bank of Israel shekel inflation target 1-3%', 'https://www.pcbs.gov.ps/en/reference/cpi-dashboard/', '2026-10-31', 'Prices are set mostly in shekels and West Bank inflation averaged about 2% over 2019-2025, but Gaza and supply shocks add risk, so 2.5% a year is used for long-range plans.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PS', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published term life premium rates per 1,000 of cover by age were found from the regulator or another public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PS', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Capital Market Authority (insurance regulator) publishes annual reports, but no industry-wide life claim settlement ratio was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PS', 1, 'life_expectancy', 69.213, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN), West Bank and Gaza', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=PS', '2024-12-31', '69.2 years in 2024 (men 65.2, women 74.3), lowered by the war in Gaza.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PS', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":21,"men":19.1,"women":22.9},{"age":65,"total":17.1,"men":15.3,"women":18.7},{"age":70,"total":13.3,"men":11.9,"women":14.7},{"age":80,"total":7.4,"men":6.5,"women":8.2}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/state-of-palestine/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PS', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension was found and the Ministry of Social Development site could not be reached.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PS', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension was found; the Ministry of Social Development''s cash transfer programme targets poor households, and its rules could not be read (site not reachable).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PS', 1, 'oop_health_share', 0.4207, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), West Bank and Gaza', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=PS', '2023-12-31', '42.1% in 2023 (WHO Global Health Expenditure Database via the World Bank); older than 2025, the latest available.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PS', 1, 'policy_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Palestine Monetary Authority has no national currency and sets no policy rate; shekel interest rates follow the Bank of Israel (3.25% in October 2026), dollar and dinar rates follow the Federal Reserve and the Central Bank of Jordan.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PS', 1, 'public_pension_scheme', NULL, NULL, 'missing', '', '', '2026-10-31', 'Only public servants have a contributory pension (General Pension Authority), whose rules could not be read; private-sector social security exists only as a draft law presented by the Ministry of Labour.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PS', 1, 'retirement_accumulation_return_base', 0.035, NULL, 'assumption', 'World Bank deposit rate; equity base 5%; gold base 3.5%', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=PS', '2026-10-31', 'Base case: a balanced mix of deposits, some equities and gold.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PS', 1, 'retirement_accumulation_return_high', 0.055, NULL, 'assumption', 'World Bank deposit rate; equity high 8%', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=PS', '2026-10-31', 'High case: a growth-leaning mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PS', 1, 'retirement_accumulation_return_low', 0.02, NULL, 'assumption', 'World Bank deposit rate (2.24%, 2021)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=PS', '2026-10-31', 'Low case: a mix earning about deposit rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PS', 1, 'retirement_age_default', NULL, NULL, 'missing', '', '', '2026-10-31', 'No private-sector pension is in force: the Ministry of Labour presents only a draft social security law (the 2016 decree-law, which set 60, is not applied), so private employees rely on the end-of-service gratuity. No current statutory pension age could be confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PS', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'The civil-service pension age under the General Pension Authority could not be confirmed (its site could not be reached).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PS', 1, 'retirement_return_base', 0.02, NULL, 'assumption', 'World Bank deposit rate (2.24%, 2021)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=PS', '2026-10-31', 'Base case: below the last published average deposit rate, since current rates and the tax on interest could not be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PS', 1, 'retirement_return_high', 0.03, NULL, 'assumption', 'Bank of Israel rate 3.25% (October 2026)', 'https://edge.boi.gov.il/FusionEdgeServer/sdmx/v2/data/dataflow/BOI.STATISTICS/EXR/1.0/RER_USD_ILS?lastNObservations=1&format=csv', '2026-10-31', 'High case: longer shekel or dollar deposits near the policy rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PS', 1, 'retirement_return_low', 0.01, NULL, 'assumption', 'World Bank deposit rate (2.24%, 2021)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=PS', '2026-10-31', 'Low case: savings and short deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PS', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate or retail savings bond for individuals was found; the Palestinian Authority has no domestic government securities market that could be found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PS', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No current industry-wide savings account rate could be read. The Palestine Monetary Authority website loads its statistics only through scripts, so its interest-rate tables could not be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PS', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":15.2},{"year":2040,"value":10.9},{"year":2065,"value":5.08}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/state-of-palestine/2040/', '2025-12-31', '100 / old-age dependency ratio: 6.58 (2025, World Bank), 9.2 (2040) and 19.7 (2065, populationpyramid.net/state-of-palestine/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PS', 1, 'tax_bank_interest', NULL, NULL, 'missing', '', '', '2026-10-31', 'The income tax treatment of bank interest for individuals could not be confirmed from the Ministry of Finance (site not reachable); PwC Tax Summaries does not cover Palestine.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PS', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate exists and no tax rule for such returns was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PS', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No Palestinian Treasury bills were found; the Palestinian Authority does not issue government securities in a domestic market that could be found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PS', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No Palestinian government bonds were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PS', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No Palestinian government bonds were found.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('PT', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"PT","iso3":"PRT","nameEn":"Portugal","nameNative":"Portugal","region":"europe_central_asia","languages":["pt","en","fr","es"],"currency":{"code":"EUR","symbol":"€","decimals":2,"compact":"intl","usdRate":{"value":0.8951,"status":"sourced","sourceName":"European Central Bank euro reference rate (USD)","sourceUrl":"https://data-api.ecb.europa.eu/service/data/EXR/D.USD.EUR.SP00.A","asOf":"2026-10-30","note":"EUR 1 = USD 1.1172 on 30 October 2026, so about EUR 0.895 per US dollar; World Bank 2025 average 0.885."}},"instruments":{"savings_account":{"available":true,"localName":"Conta poupança","localNameEn":"Savings account","sourceUrl":"https://data-api.ecb.europa.eu/service/data/MIR/M.PT.B.L21.A.R.A.2250.EUR.N"},"fdr_3m":{"available":true,"localName":"Depósito a prazo (3 meses)","localNameEn":"Term deposit (3 months)"},"fdr_1y":{"available":true,"localName":"Depósito a prazo (1 ano)","localNameEn":"Term deposit (1 year)","sourceUrl":"https://data-api.ecb.europa.eu/service/data/MIR/M.PT.B.L22.F.R.A.2250.EUR.N"},"dps":{"available":false,"localName":null,"localNameEn":"Recurring deposit","note":"No standard monthly recurring-deposit product; regular saving is usually done through savings accounts or savings certificates."},"sanchayapatra_5y":{"available":true,"localName":"Certificados de Aforro (Série F)","localNameEn":"Savings certificates (Series F)","note":"Government savings certificates sold by the IGCP through post offices, citizen shops and online (AforroNet); variable capped rate with loyalty premiums. Certificados do Tesouro are a 7-year alternative.","sourceUrl":"https://www.igcp.pt/pt/noticias/taxas-de-juro-dos-certificados-de-aforro-das-series-b-d-e-e-f-em-novembro-de-2026"},"tbill_91d":{"available":true,"localName":"Bilhetes do Tesouro","localNameEn":"Treasury bills","note":"Auctioned by the IGCP in 3- to 12-month lines; individuals buy them through a bank or broker.","sourceUrl":"https://tradingeconomics.com/portugal/government-bond-yield"},"tbond_5y":{"available":true,"localName":"Obrigações do Tesouro","localNameEn":"Treasury bonds","sourceUrl":"https://tradingeconomics.com/portugal/government-bond-yield"},"tbond_10y":{"available":true,"localName":"Obrigações do Tesouro","localNameEn":"Treasury bonds","sourceUrl":"https://www.igcp.pt/pt/noticias/resultado-do-leilao-de-obrigacoes-do-tesouro-ot-do-dia-14-de-outubro-de-2026"},"equity_fund":{"available":true,"localName":"Fundo de investimento","localNameEn":"Investment funds and index funds (ETFs)","note":"Retail mutual funds and exchange-traded index funds are widely available; retirement savings plans (PPR) carry tax relief."},"gold":{"available":true,"localName":"Ouro de investimento","localNameEn":"Investment gold (bars and coins)","note":"Buying physical investment gold is legal and VAT-exempt under EU rules."}},"institutions":{"centralBank":{"name":"Banco de Portugal","url":"https://www.bportugal.pt/en","note":"Part of the Eurosystem; monetary policy set by the European Central Bank."},"insuranceRegulator":{"name":"Autoridade de Supervisão de Seguros e Fundos de Pensões (ASF)","url":"https://www.asf.com.pt/en"},"insuranceComplaints":{"name":"ASF consumer area (complaints about insurers)","url":"https://www.asf.com.pt/consumidor","note":"Complain to the insurer first; then to the ASF or a consumer arbitration centre."},"pensionScheme":{"name":"Segurança Social (Social Security Institute), old-age pension","url":"https://www.seg-social.pt/pensao-de-velhice"},"oldAgeAllowance":{"name":"Pensão social de velhice and Complemento Solidário para Idosos (Segurança Social)","url":"https://www.seg-social.pt/pensao-social-de-velhice","note":"Means-tested non-contributory pension and supplement, claimed from Social Security."},"publicHealthCover":{"name":"Serviço Nacional de Saúde (SNS)","url":"https://www.sns.gov.pt/"},"depositInsurance":{"name":"Fundo de Garantia de Depósitos","url":"https://www.fgd.pt/"},"statistics":{"name":"Statistics Portugal (INE)","url":"https://www.ine.pt/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PT', 1, 'bank_deposit_avg_rate', 0.0182, NULL, 'sourced', 'ECB MFI interest rate statistics (reported by Banco de Portugal): household deposits with agreed maturity, all maturities, new business', 'https://data-api.ecb.europa.eu/service/data/MIR/M.PT.B.L22.A.R.A.2250.EUR.N', '2026-09-30', 'Weighted average rate on new household term deposits of all maturities was 1.82% in September 2026 (1.63% in August); the average on all outstanding household term deposits was 1.17%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PT', 1, 'credit_card_rate_cap', 0.1604, NULL, 'sourced', 'ECB MFI interest rate statistics (reported by Banco de Portugal): Portuguese banks, extended credit card credit to households', 'https://data-api.ecb.europa.eu/service/data/MIR/M.PT.B.A2Z3.A.R.A.2250.EUR.N', '2026-09-30', 'Typical rate, not the legal cap: average 16.04% in September 2026 (16.07% in August). Banco de Portugal also sets a quarterly maximum APR (TAEG) for credit cards, which could not be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PT', 1, 'deposit_insurance_limit', 100000, NULL, 'sourced', 'European Commission, deposit guarantee schemes (EU rules)', 'https://finance.ec.europa.eu/banking/banking-regulation/deposit-guarantee-schemes_en', '2026-07-17', 'EU rules guarantee deposits up to EUR 100,000 per depositor per bank; in Portugal the cover is paid by the Fundo de Garantia de Depósitos (its own site could not be read).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PT', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No standard monthly recurring-deposit product with a published average rate was found for Portugal.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PT', 1, 'equity_return_base', 0.055, NULL, 'assumption', 'PSI index history (Trading Economics); after-tax 3-month bill 2.65% x 0.72 = 1.9%', 'https://tradingeconomics.com/portugal/stock-market', '2026-10-31', 'Base case: about 3.6 points over the after-tax safe rate; Portuguese savers mostly hold diversified European and global funds, and the PSI''s long record is weak (still below its 2000 peak).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PT', 1, 'equity_return_high', 0.08, NULL, 'assumption', 'PSI index history (Trading Economics), near its highest level since 2008', 'https://tradingeconomics.com/portugal/stock-market', '2026-10-31', 'High case: diversified euro equity funds keep close to their strong 2016-2026 returns.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PT', 1, 'equity_return_low', 0.03, NULL, 'assumption', 'PSI index 9,276 on 30 Oct 2026, up 10% in a year and still below its 2000 peak (Trading Economics); after-tax 3-month bill 1.9%', 'https://tradingeconomics.com/portugal/stock-market', '2026-10-31', 'Low case: European shares disappoint and earn only a little more than after-tax government bills.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PT', 1, 'fdr_1y_rate', 0.0183, NULL, 'sourced', 'ECB MFI interest rate statistics (reported by Banco de Portugal): household euro deposits with agreed maturity up to 1 year, new business', 'https://data-api.ecb.europa.eu/service/data/MIR/M.PT.B.L22.F.R.A.2250.EUR.N', '2026-09-30', 'Bucket covers all fixed terms up to one year (1.62% in August 2026). Taxed at 28%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PT', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Banco de Portugal and the ECB publish household term deposits up to 1 year as one bucket (1.83% in September 2026); no separate 3-month average was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PT', 1, 'fixed_income_return_base', 0.018, NULL, 'assumption', 'Certificados de Aforro Série F 2.50% less 28% tax = 1.8% (IGCP)', 'https://www.igcp.pt/pt/noticias/taxas-de-juro-dos-certificados-de-aforro-das-series-b-d-e-e-f-em-novembro-de-2026', '2026-10-31', 'Base case: savings certificates and government bills after the 28% tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PT', 1, 'fixed_income_return_high', 0.027, NULL, 'assumption', '10-year government bond 3.78% less 28% tax = 2.7% (Trading Economics)', 'https://tradingeconomics.com/portugal/government-bond-yield', '2026-10-31', 'High case: locking in medium and long government bonds at today''s yields.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PT', 1, 'fixed_income_return_low', 0.012, NULL, 'assumption', 'Household deposits up to 1 year 1.83% less 28% tax = 1.3% (ECB MIR, September 2026)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.PT.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Low case: after-tax bank term deposits only, allowing for some rate cuts.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PT', 1, 'goal_inflation_education', 0.04, NULL, 'assumption', 'Eurostat/ECB HICP Portugal, education: 4.2% year on year in December 2025', 'https://data-api.ecb.europa.eu/service/data/ICP/M.PT.N.100000.4.ANR', '2026-10-31', 'Education prices rose 4.2% in 2025, well above general inflation; planning uses 4%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PT', 1, 'goal_inflation_health', 0.035, NULL, 'assumption', 'Eurostat/ECB HICP Portugal, health: 2.8% year on year in December 2025', 'https://data-api.ecb.europa.eu/service/data/ICP/M.PT.N.060000.4.ANR', '2026-10-31', 'Health prices rose 2.8% in 2025, a little above general HICP (2.4%); planning uses 3.5%, one point above general inflation, because medical costs rise faster over long periods.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PT', 1, 'gold_return_base', 0.04, NULL, 'assumption', 'Gold USD price history (Trading Economics); ECB 2% target', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Base case: gold roughly keeps up with world inflation plus a little, with no trend in the euro-dollar rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PT', 1, 'gold_return_high', 0.08, NULL, 'assumption', 'Gold USD price history (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'High case: a repeat of gold''s strong 2005-2025 trend in euro terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PT', 1, 'gold_return_low', 0.015, NULL, 'assumption', 'Gold USD price history (Trading Economics); EUR 1 = USD 1.1172 (ECB, 30 Oct 2026)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Low case: gold stalls after the 2025-26 spike and the euro firms against the dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PT', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Labour Code gives compensation only when the employer ends the contract (dismissal for economic reasons or expiry of a fixed-term contract), not on retirement or resignation; no official page stating the current days-per-year scale could be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PT', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'Hospital care in the National Health Service (SNS) is free or nearly free; no official figure for the out-of-pocket cost of a major private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PT', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Private health insurance is widely sold in Portugal, but no published premium table per EUR 100,000 of cover from a regulator or public source was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PT', 1, 'inflation_cpi', 0.038, NULL, 'sourced', 'Statistics Portugal (INE), CPI flash estimate, October 2026', 'https://www.ine.pt/xportal/xmain?xpid=INE&xpgid=ine_destaques&DESTAQUESdest_boui=770567799&DESTAQUESmodo=2&xlang=en', '2026-10-31', 'CPI annual rate estimated at 3.8% in October 2026 (3.6% in September), released 30 October 2026; core inflation 2.8%, energy 17.4%. World Bank 2025 average 2.3%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PT', 1, 'inflation_projection', 0.025, NULL, 'assumption', 'ECB 2% inflation target; Portuguese HICP 2021-2025 average 3.8% (ECB ICP)', 'https://data-api.ecb.europa.eu/service/data/ICP/A.PT.N.000000.4.AVR', '2026-10-31', 'Portugal shares the ECB''s 2% target, but inflation averaged 3.8% over 2021-2025 and is 3.8% now on an energy shock, so planning uses 2.5%, a little above the target.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PT', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life cover (often tied to mortgages) is sold in Portugal, but no regulator or official premium table per sum insured was found; only individual company quotes exist.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PT', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The insurance supervisor (ASF) publishes market statistics, but no industry-wide life claim settlement ratio was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PT', 1, 'life_expectancy', 81.85, NULL, 'sourced', 'Statistics Portugal (INE), Portuguese life tables 2023-2025', 'https://www.ine.pt/xportal/xmain?xpid=INE&xpgid=ine_destaques&DESTAQUESdest_boui=771181662&DESTAQUESmodo=2&xlang=en', '2025-12-31', 'Life expectancy at birth 81.85 years for 2023-2025 (men 79.22, women 84.26), released 30 October 2026. UN WPP via georank gives 82.9 for 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PT', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":25.4,"men":23.3,"women":27.2},{"age":65,"total":21.2,"men":19.4,"women":22.7},{"age":70,"total":17.1,"men":15.6,"women":18.3},{"age":80,"total":9.7,"men":8.8,"women":10.4}]}', 'sourced', 'UN World Population Prospects via georank.org; Statistics Portugal (INE) life tables 2023-2025', 'https://georank.org/life-expectancy/portugal', '2026-07-01', 'Remaining years from georank''s expected age at death by current age (UN WPP 2026 estimate). INE''s own 2023-2025 table gives 20.19 years at 65 (men 18.49, women 21.55).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PT', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":66.75,"womenAge":66.75,"over90Monthly":null,"meansTested":true}', 'sourced', 'European Commission, Your social security rights in Portugal (July 2026)', 'https://employment-social-affairs.ec.europa.eu/document/download/7bb82c27-9a98-4ab5-948c-e875d1d18f02_en', '2026-07-31', 'Residents at the normal pension age (66 years 9 months in 2026, men and women) without a contributory pension or with one below the social pension, and with gross income of at most EUR 214.85 a month (single) or EUR 322.28 (couple), 40% and 60% of the IAS.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PT', 1, 'old_age_allowance_monthly', 262.4, NULL, 'sourced', 'European Commission, Your social security rights in Portugal (July 2026)', 'https://employment-social-affairs.ec.europa.eu/document/download/7bb82c27-9a98-4ab5-948c-e875d1d18f02_en', '2026-07-31', 'Social old-age pension (pensão social de velhice): the guide gives the social pension amount as EUR 262.40 a month. Means-tested; pensioners with low resources at pension age can also claim the Solidarity Supplement for the Elderly (CSI) on top.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PT', 1, 'oop_health_share', 0.2819, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=PT', '2024-12-31', 'Out-of-pocket spending was 28.2% of current health expenditure in 2024 (latest available; older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PT', 1, 'policy_rate', 0.025, NULL, 'sourced', 'European Central Bank, key ECB interest rates (deposit facility)', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.en.html', '2026-09-16', 'Portugal uses the euro; ECB deposit facility rate 2.50% (main refinancing 2.65%) since 16 September 2026, unchanged on 31 October 2026 (ECB data portal FM.D.U2.EUR.4F.KR.DFR.LEV).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PT', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":66.75,"nomineeUntilAge":null,"inflationLinked":true,"taxFree":false}', 'sourced', 'European Commission, Your social security rights in Portugal (July 2026)', 'https://employment-social-affairs.ec.europa.eu/document/download/7bb82c27-9a98-4ab5-948c-e875d1d18f02_en', '2026-07-31', 'Compulsory earnings-related general social security pension: normal pension age 66 years 9 months in 2026, at least 15 years of registered earnings; pensions are updated each 1 January by a formula based on GDP growth and average CPI (excluding housing), and are taxed as income.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PT', 1, 'retirement_accumulation_return_base', 0.037, NULL, 'assumption', 'Fixed income base 1.8%; equity base 5.5%', 'https://tradingeconomics.com/portugal/stock-market', '2026-10-31', 'Base case: roughly half shares at 5.5% and half safe fixed income at about 1.8%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PT', 1, 'retirement_accumulation_return_high', 0.055, NULL, 'assumption', 'Equity high 8%; after-tax long government bonds 2.7%', 'https://tradingeconomics.com/portugal/stock-market', '2026-10-31', 'High case for a growth-leaning balanced mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PT', 1, 'retirement_accumulation_return_low', 0.025, NULL, 'assumption', 'After-tax deposits 1.2%; PSI and euro equity record (Trading Economics)', 'https://tradingeconomics.com/portugal/stock-market', '2026-10-31', 'Low case for a balanced mix if shares lag.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PT', 1, 'retirement_age_default', 66.75, NULL, 'sourced', 'European Commission, Your social security rights in Portugal (July 2026)', 'https://employment-social-affairs.ec.europa.eu/document/download/7bb82c27-9a98-4ab5-948c-e875d1d18f02_en', '2026-07-31', 'Normal pension age is 66 years and 9 months in 2026 (66 years 7 months in 2025), the same for men and women. It is reset each year in line with life expectancy at 65, so someone born after 1975 will likely face a higher age; it is lowered by 4 months for each year of contributions beyond 40.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PT', 1, 'retirement_age_government', 66.75, NULL, 'sourced', 'European Commission, Your social security rights in Portugal (July 2026)', 'https://employment-social-affairs.ec.europa.eu/document/download/7bb82c27-9a98-4ab5-948c-e875d1d18f02_en', '2026-07-31', 'Civil servants (CGA scheme, and the general scheme for those hired since 2006) follow the same normal pension age, 66 years and 9 months in 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PT', 1, 'retirement_return_base', 0.018, NULL, 'assumption', '3-month government bill 2.65% less 28% tax = 1.9% (Trading Economics); Certificados de Aforro 2.5% less tax = 1.8%', 'https://tradingeconomics.com/portugal/government-bond-yield', '2026-10-31', 'Base case: kept at the after-tax rate on savings certificates, just below the after-tax government bill rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PT', 1, 'retirement_return_high', 0.025, NULL, 'assumption', '5-10 year government bonds 3.4-3.8% less 28% tax (Trading Economics)', 'https://tradingeconomics.com/portugal/government-bond-yield', '2026-10-31', 'High case: medium and long government bonds bought at today''s yields and held to maturity.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PT', 1, 'retirement_return_low', 0.01, NULL, 'assumption', 'After-tax 1-year deposit 1.3% (ECB MIR, September 2026)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.PT.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Low case: after-tax deposits with some rate cuts.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PT', 1, 'sanchayapatra_5y_rate', 0.025, NULL, 'sourced', 'IGCP (Portuguese Treasury and Debt Management Agency), Certificados de Aforro interest rates for November 2026', 'https://www.igcp.pt/pt/noticias/taxas-de-juro-dos-certificados-de-aforro-das-series-b-d-e-e-f-em-novembro-de-2026', '2026-10-30', 'Gross rate for new subscriptions of savings certificates Série F fixed at 2.500% for November 2026 (published 30 October 2026); the rate follows money-market rates and is capped, with loyalty premiums in later years. Certificados do Tesouro (7-year stepped-rate treasury certificates) are also sold to individuals.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PT', 1, 'savings_account_rate', 0.0003, NULL, 'sourced', 'ECB MFI interest rate statistics (reported by Banco de Portugal): Portuguese banks, overnight euro deposits from households', 'https://data-api.ecb.europa.eu/service/data/MIR/M.PT.B.L21.A.R.A.2250.EUR.N', '2026-09-30', 'Average rate on household overnight (current and savings) deposits was 0.03% in September 2026 (0.04% in August).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PT', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":2.5},{"year":2040,"value":1.82},{"year":2065,"value":1.79}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/portugal/2040/', '2025-12-31', '100 / old-age dependency ratio: 40.0 (2025, World Bank), 55.0 (2040) and 56.0 (2065, populationpyramid.net/portugal/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PT', 1, 'tax_bank_interest', 0.28, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Portugal income determination', 'https://taxsummaries.pwc.com/portugal/individual/income-determination', '2026-10-03', 'Interest on Portuguese bank current and savings accounts is taxed at a flat 28% for residents, withheld at source (page reviewed 3 October 2026); residents may opt to add it to income taxed at 12.5-48%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PT', 1, 'tax_sanchayapatra_profit', 0.28, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Portugal income determination', 'https://taxsummaries.pwc.com/portugal/individual/income-determination', '2026-10-03', 'PwC gives the flat 28% rate for interest on bank accounts and does not name savings certificates; Certificados de Aforro interest is capital income withheld at the same 28% rate (the IGCP simulator applies the withholding rate chosen by the saver), so 28% is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PT', 1, 'tbill_91d_rate', 0.0265, NULL, 'sourced', 'Trading Economics, Portugal 3-month bill yield (secondary source)', 'https://tradingeconomics.com/portugal/government-bond-yield', '2026-10-30', '3-month yield 2.65% on 30 October 2026. Secondary source: the IGCP publishes auction amounts but its September 2026 bill auction was for a 12-month line only.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PT', 1, 'tbond_10y_rate', 0.0378, NULL, 'sourced', 'Trading Economics, Portugal 10-year government bond yield (secondary source)', 'https://tradingeconomics.com/portugal/government-bond-yield', '2026-10-30', '10-year yield about 3.78% at the 30 October 2026 close (Trading Economics shows 3.74% on 2 November, down 0.04 points); the ECB long-term convergence yield for Portugal was 3.85% in September 2026 (ECB IRS dataset).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PT', 1, 'tbond_5y_rate', 0.0339, NULL, 'sourced', 'Trading Economics, Portugal 5-year note yield (secondary source)', 'https://tradingeconomics.com/portugal/government-bond-yield', '2026-10-30', '5-year yield 3.39% on 30 October 2026.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('PW', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"PW","iso3":"PLW","nameEn":"Palau","nameNative":"Belau","region":"east_asia_pacific","languages":["pau","en"],"currency":{"code":"USD","symbol":"$","decimals":2,"compact":"intl","usdRate":{"value":1,"status":"sourced","sourceName":"World Bank WDI PA.NUS.FCRF","sourceUrl":"https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=PW","asOf":"2025-12-31","note":"Palau uses the US dollar."}},"instruments":{"savings_account":{"available":true,"localName":"Savings account","note":"Offered by the commercial banks licensed in Palau; rates not published."},"fdr_3m":{"available":true,"localName":"Time deposit","localNameEn":"3-month time deposit (CD)","note":"Banks in Palau offer time deposits; rates not published."},"fdr_1y":{"available":true,"localName":"Time deposit","localNameEn":"1-year time deposit (CD)","note":"Banks in Palau offer time deposits; rates not published."},"dps":{"available":false,"localName":null},"sanchayapatra_5y":{"available":false,"localName":null,"note":"No government savings certificates or retail bonds."},"tbill_91d":{"available":false,"localName":null,"note":"Palau issues no treasury bills; it uses the US dollar."},"tbond_5y":{"available":false,"localName":null},"tbond_10y":{"available":false,"localName":null},"equity_fund":{"available":false,"localName":null,"note":"No local stock exchange or locally sold funds; residents would have to invest abroad."},"gold":{"available":false,"localName":null,"note":"No local gold bullion dealer was found; no legal restriction is known."}},"institutions":{"centralBank":{"name":"US Federal Reserve (Palau uses the US dollar and has no central bank)","url":"https://www.federalreserve.gov/"},"insuranceRegulator":null,"insuranceComplaints":null,"pensionScheme":null,"oldAgeAllowance":null,"publicHealthCover":{"name":"Ministry of Health and Human Services (Belau National Hospital, Medical Referral Program)","url":"https://www.palaugov.pw/executive-branch/ministries/health/"},"depositInsurance":null,"statistics":{"name":"Bureau of Budget and Planning, Ministry of Finance (statistics: CPI, national accounts, census)","url":"https://www.palaugov.pw/executive-branch/ministries/finance/budgetandplanning/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PW', 1, 'bank_deposit_avg_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'World Bank FR.INR.DPST has no Palau data and the Ministry of Finance quarterly indicators do not report deposit rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PW', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap or published typical credit card rate for Palau was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PW', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No Palau deposit insurance scheme was found; whether US FDIC cover extends to branches of US-chartered banks in Palau was not confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PW', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No monthly recurring deposit product is known in Palau.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PW', 1, 'equity_return_base', 0.055, NULL, 'assumption', 'No local stock market; global equity in USD terms. US 3-month Treasury bill 4.09% (30 Oct 2026) as the dollar ceiling; local bank deposit rates are not published', 'https://tradingeconomics.com/united-states/3-month-bill-yield', '2026-10-31', 'No local exchange exists, so base equity is a global index in US dollars, set at the local safe-rate assumption of 1.5% plus 4 points.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PW', 1, 'equity_return_high', 0.08, NULL, 'assumption', 'No local stock market; global equity in USD terms. US 3-month Treasury bill 4.09% (30 Oct 2026) as the dollar ceiling; local bank deposit rates are not published', 'https://tradingeconomics.com/united-states/3-month-bill-yield', '2026-10-31', 'High case near the long-run return of global shares in US dollars.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PW', 1, 'equity_return_low', 0.03, NULL, 'assumption', 'No local stock market; global equity in USD terms. US 3-month Treasury bill 4.09% (30 Oct 2026) as the dollar ceiling; local bank deposit rates are not published', 'https://tradingeconomics.com/united-states/3-month-bill-yield', '2026-10-31', 'Low case for a global index fund held in US dollars after a weak decade.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PW', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published term deposit (CD) rates for banks in Palau were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PW', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published term deposit (CD) rates for banks in Palau were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PW', 1, 'fixed_income_return_base', 0.015, NULL, 'assumption', 'US 3-month Treasury bill 4.09% (30 Oct 2026) as the dollar ceiling; local bank deposit rates are not published', 'https://tradingeconomics.com/united-states/3-month-bill-yield', '2026-10-31', 'Base case: local term deposits, assumed well below US bill yields because local banks have few lending outlets.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PW', 1, 'fixed_income_return_high', 0.035, NULL, 'assumption', 'US 3-month Treasury bill 4.09% (30 Oct 2026) as the dollar ceiling; local bank deposit rates are not published', 'https://tradingeconomics.com/united-states/3-month-bill-yield', '2026-10-31', 'High case: dollar term deposits or bills near US short rates, less tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PW', 1, 'fixed_income_return_low', 0.005, NULL, 'assumption', 'US 3-month Treasury bill 4.09% (30 Oct 2026) as the dollar ceiling; local bank deposit rates are not published', 'https://tradingeconomics.com/united-states/3-month-bill-yield', '2026-10-31', 'Low case: local savings accounts at low rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PW', 1, 'goal_inflation_education', 0.03, NULL, 'assumption', 'Palau CPI 2026 Q2: education group 0.0% year on year, all items 3.0%', 'https://www.palaugov.pw/consumer-price-index-cpi/', '2026-10-31', 'The education group has been flat recently; we plan with headline plus half a point for study abroad costs.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PW', 1, 'goal_inflation_health', 0.035, NULL, 'assumption', 'Palau CPI 2026 Q2: health group 0.0% year on year, all items 3.0%', 'https://www.palaugov.pw/consumer-price-index-cpi/', '2026-10-31', 'The health group has been flat recently, but referral care abroad is priced in US medical costs, so we plan with headline plus one point.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PW', 1, 'gold_return_base', 0.045, NULL, 'assumption', 'Palau uses the US dollar (World Bank PA.NUS.FCRF = 1)', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=PW', '2026-10-31', 'Long-run dollar gold trend of about 4-5% with no currency depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PW', 1, 'gold_return_high', 0.07, NULL, 'assumption', 'Palau uses the US dollar (World Bank PA.NUS.FCRF = 1)', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=PW', '2026-10-31', 'High case with strong dollar gold.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PW', 1, 'gold_return_low', 0.02, NULL, 'assumption', 'Palau uses the US dollar (World Bank PA.NUS.FCRF = 1)', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=PW', '2026-10-31', 'Low case: weak dollar gold price; no currency effect.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PW', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No statutory gratuity or end-of-service benefit for private employees was found for Palau.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PW', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical hospital bill was found; Belau National Hospital is public and complex cases go through the Medical Referral Program.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PW', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No private health insurance premium table for Palau was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PW', 1, 'inflation_cpi', 0.03, NULL, 'sourced', 'Bureau of Budget and Planning (Ministry of Finance), CPI 2026 Q2 key figures', 'https://www.palaugov.pw/consumer-price-index-cpi/', '2026-06-30', 'All-groups CPI up 3.0% year on year in the June 2026 quarter (2.2% on the quarter). World Bank gives -0.4% for 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PW', 1, 'inflation_projection', 0.025, NULL, 'assumption', 'IMF WEO CPI projections for Palau (1.7% 2026, 3.7% 2027, 2.1-2.5% 2028-2030); dollar economy', 'https://www.imf.org/external/datamapper/api/v1/PCPIPCH/PLW', '2026-10-31', 'Palau uses the US dollar and imports most goods, so we plan with 2.5%, a little above the Federal Reserve''s 2% goal, in line with the IMF medium-term path.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PW', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published term life premium rates for Palau were found.', 0);
