INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PW', 1, 'life_expectancy', 69.383, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=PW', '2024-12-31', '2024 figure, the latest World Bank year (older than 2025). Men 67.3, women 71.9.', 0);
