INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('PY', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"PY","iso3":"PRY","nameEn":"Paraguay","nameNative":"Paraguay","region":"latin_america_caribbean","languages":["es","gn"],"currency":{"code":"PYG","symbol":"₲","decimals":0,"compact":"intl","usdRate":{"value":5919.69,"status":"sourced","sourceName":"Banco Central del Paraguay, reference exchange rate (non-financial clients market), close 30 October 2026","sourceUrl":"https://www.bcp.gov.py/webapps/web/cotizacion/referencial-fluctuante","asOf":"2026-10-30","note":"Mid of the closing buy 5,910.01 and sell 5,929.37 guaranies per dollar on 30 October 2026. On re-check (3 November 2026) the BCP page only showed the 2 November close (about 5,965-5,981) and Trading Economics gave 5,917 on 3 November, consistent with this level; the guarani appreciated sharply in 2026 (World Bank average 7,545 for 2025)."}},"instruments":{"savings_account":{"available":true,"localName":"Caja de ahorro","localNameEn":"Savings account","note":"Offered by banks and finance companies; no public 2026 rate could be read."},"fdr_3m":{"available":true,"localName":"Depósito a plazo fijo","localNameEn":"Fixed-term deposit","note":"Short fixed-term deposits are offered by banks; no public 2026 rate could be read."},"fdr_1y":{"available":true,"localName":"Certificado de Depósito de Ahorro (CDA)","localNameEn":"Savings deposit certificate","note":"The usual term deposit product for 1 year or more; no public 2026 rate could be read."},"dps":{"available":false,"localName":null,"note":"No standard monthly recurring deposit product with a published rate."},"sanchayapatra_5y":{"available":false,"localName":null,"note":"No government savings certificate or retail savings bond for individuals was found."},"tbill_91d":{"available":false,"localName":null,"note":"No regular 91-day Treasury bill auction was found; the BCP''s short-term monetary regulation instruments are for banks."},"tbond_5y":{"available":true,"localName":"Bonos del Tesoro Público","localNameEn":"Treasury bonds (maturing 2030)","note":"Auctioned by the Ministry of Economy and Finance through the Asuncion stock exchange; individuals buy through licensed brokers.","sourceUrl":"https://www.mef.gov.py/es/institucional/sala-de-prensa/noticias/mef-adjudico-230527-millones-bonos-del-tesoro-tasas"},"tbond_10y":{"available":true,"localName":"Bonos del Tesoro Público","localNameEn":"Treasury bonds (maturing 2035)","note":"Auctioned by the Ministry of Economy and Finance through the Asuncion stock exchange.","sourceUrl":"https://www.mef.gov.py/es/institucional/sala-de-prensa/noticias/mef-adjudico-230527-millones-bonos-del-tesoro-tasas"},"equity_fund":{"available":false,"localName":null,"note":"Local investment funds are mostly money-market and fixed-income; no diversified local equity or index fund for retail was confirmed."},"gold":{"available":true,"localName":"Oro","localNameEn":"Gold jewellery and coins","note":"No legal restriction on buying gold; mostly sold as jewellery."}},"institutions":{"centralBank":{"name":"Banco Central del Paraguay (BCP)","url":"https://www.bcp.gov.py/"},"insuranceRegulator":{"name":"Superintendencia de Seguros, Banco Central del Paraguay","url":"https://www.bcp.gov.py/superintendencia-de-seguros-i9"},"insuranceComplaints":{"name":"Superintendencia de Seguros, Banco Central del Paraguay","url":"https://www.bcp.gov.py/superintendencia-de-seguros-i9","note":"No separate insurance ombudsman; complaints go to the Superintendencia de Seguros."},"pensionScheme":{"name":"Instituto de Previsión Social (IPS)","url":"https://portal.ips.gov.py/"},"oldAgeAllowance":{"name":"Pensión Alimentaria para Adultos Mayores, Ministerio de Desarrollo Social","url":"https://www.mds.gov.py/"},"publicHealthCover":{"name":"Ministerio de Salud Pública y Bienestar Social (free public health services)","url":"https://www.mspbs.gov.py/"},"depositInsurance":{"name":"Fondo de Garantía de Depósitos (Banco Central del Paraguay)","url":"https://www.bcp.gov.py/"},"statistics":{"name":"Instituto Nacional de Estadística (INE)","url":"https://www.ine.gov.py/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
