INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PY', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'Paraguay has a Deposit Guarantee Fund (Fondo de Garantia de Depositos) run by the BCP, but its page and the law text could not be read (sites block automated access or were unreachable), so the coverage amount was not confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PY', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No standard monthly recurring deposit product with a published rate was found in Paraguay.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PY', 1, 'equity_return_base', 0.085, NULL, 'assumption', 'Paraguay Treasury bond yields 8.26-8.70% (MEF, September 2026); global equity in guarani terms', 'https://www.mef.gov.py/es/institucional/sala-de-prensa/noticias/mef-adjudico-230527-millones-bonos-del-tesoro-tasas', '2026-10-31', 'No local equity index with a 10-year record exists, so the base uses global equities in guarani terms (about 7% in dollars plus slight guarani depreciation), below the 7.6% after-tax bond yield plus 4 points.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PY', 1, 'equity_return_high', 0.11, NULL, 'assumption', 'Paraguay Treasury bond yields 8.26-8.70% (MEF, September 2026); global equity in guarani terms', 'https://www.mef.gov.py/es/institucional/sala-de-prensa/noticias/mef-adjudico-230527-millones-bonos-del-tesoro-tasas', '2026-10-31', 'High case if global equities repeat strong dollar returns and the guarani weakens.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PY', 1, 'equity_return_low', 0.04, NULL, 'assumption', 'Paraguay Treasury bond yields 8.26-8.70% (MEF, September 2026); no usable local equity index', 'https://www.mef.gov.py/es/institucional/sala-de-prensa/noticias/mef-adjudico-230527-millones-bonos-del-tesoro-tasas', '2026-10-31', 'Low case: the Asuncion stock exchange trades few shares, so savers rely on global equity in guarani terms, and a weak decade is possible.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PY', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'BCP average rates for 1-year savings certificates (CDA) could not be read (site blocks automated access); no other public 2026 figure found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PY', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'BCP average rates for short fixed-term deposits could not be read (site blocks automated access); no other public 2026 figure found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PY', 1, 'fixed_income_return_base', 0.05, NULL, 'assumption', 'BCP policy rate 5.50%; Treasury bond yields 8.26-8.70% (September 2026); 8% tax on interest', 'https://www.mef.gov.py/es/institucional/sala-de-prensa/noticias/mef-adjudico-230527-millones-bonos-del-tesoro-tasas', '2026-10-31', 'Base case: a mix of term deposits near the policy rate and Treasury bonds, after 8% personal income tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PY', 1, 'fixed_income_return_high', 0.07, NULL, 'assumption', 'Treasury bond yields 8.26-8.70% (MEF, September 2026); 8% tax on interest', 'https://www.mef.gov.py/es/institucional/sala-de-prensa/noticias/mef-adjudico-230527-millones-bonos-del-tesoro-tasas', '2026-10-31', 'High case: holding Treasury bonds at about 7.6-8% after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PY', 1, 'fixed_income_return_low', 0.035, NULL, 'assumption', 'BCP policy rate 5.50% (October 2026); 8% personal income tax on interest', 'https://tradingeconomics.com/paraguay/interest-rate', '2026-10-31', 'Low case: savings and short deposits below the policy rate, after 8% tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PY', 1, 'goal_inflation_education', 0.05, NULL, 'assumption', 'BCP inflation target 3.5%; CPI inflation 1.7% (September 2026)', 'https://tradingeconomics.com/paraguay/inflation-cpi', '2026-10-31', 'No long-run education CPI series could be read; planning inflation plus 1.5 points for private school and university fees.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PY', 1, 'goal_inflation_health', 0.05, NULL, 'assumption', 'BCP inflation target 3.5%; CPI inflation 1.7% (September 2026)', 'https://tradingeconomics.com/paraguay/inflation-cpi', '2026-10-31', 'No long-run medical CPI series could be read; planning inflation plus 1.5 points for private medical costs.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PY', 1, 'gold_return_base', 0.055, NULL, 'assumption', 'BCP reference exchange rate (about 5,920 guaranies per dollar, October 2026); World Bank average 7,545 for 2025', 'https://www.bcp.gov.py/webapps/web/cotizacion/referencial-fluctuante', '2026-10-31', 'Long-run dollar gold trend of about 4.5% plus about 1 point of guarani depreciation a year over the long run.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PY', 1, 'gold_return_high', 0.09, NULL, 'assumption', 'BCP reference exchange rate (about 5,920 guaranies per dollar, October 2026)', 'https://www.bcp.gov.py/webapps/web/cotizacion/referencial-fluctuante', '2026-10-31', 'High case with strong dollar gold prices and a weaker guarani.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PY', 1, 'gold_return_low', 0.015, NULL, 'assumption', 'BCP reference exchange rate (about 5,920 guaranies per dollar, October 2026, after strong appreciation from 7,545 in 2025)', 'https://www.bcp.gov.py/webapps/web/cotizacion/referencial-fluctuante', '2026-10-31', 'Low case: weak dollar gold price while the guarani stays strong.', 0);
