INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PY', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health plan (medicina prepaga) premiums by age from a regulator or public source were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PY', 1, 'inflation_cpi', 0.017, NULL, 'sourced', 'Trading Economics, Paraguay inflation rate (Banco Central del Paraguay CPI)', 'https://tradingeconomics.com/paraguay/inflation-cpi', '2026-09-30', 'Secondary source: year-on-year CPI inflation 1.7% in September 2026 (1.5% in August); the BCP site blocks automated reading. World Bank gives 4.0% for 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PY', 1, 'inflation_projection', 0.035, NULL, 'assumption', 'Banco Central del Paraguay inflation target 3.5% (reported by Trading Economics, October 2026 decision)', 'https://tradingeconomics.com/paraguay/interest-rate', '2026-10-31', 'The BCP targets 3.5% and expectations are anchored there, so we plan with the target although current inflation (1.7%) is lower.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PY', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life cover is sold in Paraguay, but no regulator or public source publishing premium rates by age was found; only individual insurer quotes exist.', 0);
