INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PY', 1, 'life_expectancy', 73.982, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=PY', '2024-12-31', 'UN WPP 2024 (via populationpyramid.net) gives 74.2 for 2026 (men 71.3, women 77.4).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PY', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":20.2,"men":18.5,"women":21.9},{"age":65,"total":16.6,"men":15.1,"women":18},{"age":70,"total":13.2,"men":11.9,"women":14.4},{"age":80,"total":7.5,"men":6.7,"women":8.2}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/paraguay/', '2026-12-31', 'Secondary source of UN WPP 2024 medium variant for 2026; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PY', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":65,"womenAge":65,"over90Monthly":null,"meansTested":true}', 'sourced', 'HelpAge International, Pension Watch: Paraguay', 'https://www.helpage.org/country_profile/paraguay/', '2025-07-01', 'Pension Alimentaria para Adultos Mayores: age 65 for men and women, targeted at people in poverty; covers about 61% of people 60+.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PY', 1, 'old_age_allowance_monthly', 724762, NULL, 'sourced', 'HelpAge International, Pension Watch: Paraguay (Pension Alimentaria para Adultos Mayores)', 'https://www.helpage.org/country_profile/paraguay/', '2025-07-01', 'Poverty-targeted social pension from age 65 paid to over 375,000 people (MEF, August 2026); 724,762 guaranies is 25% of the 2025 minimum wage (2,899,048), so it likely rose in July 2026 with the new minimum wage (about 3,044,000); paid by the Ministry of Social Development.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PY', 1, 'oop_health_share', 0.3632, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=PY', '2023-12-31', 'Figure is for 2023 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PY', 1, 'policy_rate', 0.055, NULL, 'sourced', 'Trading Economics, Paraguay interest rate (BCP monetary policy committee, 23 October 2026)', 'https://tradingeconomics.com/paraguay/interest-rate', '2026-10-23', 'Secondary source: BCP policy rate (TPM) held at 5.50% at the October 2026 meeting; the BCP site blocks automated reading.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PY', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":60,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'Ministerio de Economia y Finanzas, Caja Fiscal reform presentation (14 January 2026): IPS parameters', 'https://www.mef.gov.py/sites/default/files/2026-01/14-01-2026%20-%20Pres%20Reforma%20Caja%20Fiscal.pdf', '2026-01-14', 'IPS compulsory contributory scheme for private employees: ordinary pension at 60 with 25 years of contributions (100% of the reference wage); early pension from 55 with 30 years. Automatic indexation and tax treatment could not be confirmed (IPS site unreachable), so inflationLinked is set false; a 2026 reform bill proposes indexing public-sector pensions to the minimum wage.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PY', 1, 'retirement_accumulation_return_base', 0.065, NULL, 'assumption', 'Treasury bond yields 8.26-8.70%; global equity in guarani terms', 'https://www.mef.gov.py/es/institucional/sala-de-prensa/noticias/mef-adjudico-230527-millones-bonos-del-tesoro-tasas', '2026-10-31', 'Base case: half equities at 8.5% and half deposits and bonds around 5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PY', 1, 'retirement_accumulation_return_high', 0.085, NULL, 'assumption', 'Treasury bond yields 8.26-8.70%; global equity in guarani terms', 'https://www.mef.gov.py/es/institucional/sala-de-prensa/noticias/mef-adjudico-230527-millones-bonos-del-tesoro-tasas', '2026-10-31', 'High case with stronger equity returns and bonds held to maturity.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PY', 1, 'retirement_accumulation_return_low', 0.04, NULL, 'assumption', 'Treasury bond yields 8.26-8.70%; global equity in guarani terms', 'https://www.mef.gov.py/es/institucional/sala-de-prensa/noticias/mef-adjudico-230527-millones-bonos-del-tesoro-tasas', '2026-10-31', 'Low case for a balanced mix if equities disappoint.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PY', 1, 'retirement_age_default', 60, NULL, 'sourced', 'Ministerio de Economia y Finanzas, presentation on the Caja Fiscal reform (14 January 2026): comparison with IPS parameters', 'https://www.mef.gov.py/sites/default/files/2026-01/14-01-2026%20-%20Pres%20Reforma%20Caja%20Fiscal.pdf', '2026-01-14', 'IPS (Instituto de Prevision Social) ordinary retirement: minimum age 60 with 25 years of contributions, 100% replacement rate; early (extraordinary) retirement from 55 with 30 years.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PY', 1, 'retirement_age_government', 62, NULL, 'sourced', 'Ministerio de Economia y Finanzas, Caja Fiscal presentation (January 2026): ordinary retirement parameters by sector', 'https://www.mef.gov.py/sites/default/files/2026-01/PresCajaFiscal.pdf', '2026-01-01', 'General public administration (Caja Fiscal): minimum ordinary retirement age 62 with 20-40 years of contributions (47-100% replacement). A January 2026 reform bill proposes uniform rules (62 with 30 years); whether it has been enacted was not confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PY', 1, 'retirement_return_base', 0.045, NULL, 'assumption', 'BCP policy rate 5.50% (October 2026); 8% tax on interest', 'https://tradingeconomics.com/paraguay/interest-rate', '2026-10-31', 'Base case kept below the policy rate after tax (about 5.1%), as 1-year deposit rates could not be read; liquid deposits in retirement.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PY', 1, 'retirement_return_high', 0.06, NULL, 'assumption', 'Treasury bond yields 8.26-8.70% (MEF, September 2026); 8% tax', 'https://www.mef.gov.py/es/institucional/sala-de-prensa/noticias/mef-adjudico-230527-millones-bonos-del-tesoro-tasas', '2026-10-31', 'High case: part of savings in Treasury bonds at about 7.6% after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PY', 1, 'retirement_return_low', 0.035, NULL, 'assumption', 'BCP policy rate 5.50% (October 2026); 8% tax on interest', 'https://tradingeconomics.com/paraguay/interest-rate', '2026-10-31', 'Low case: mostly savings and short deposits after 8% tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PY', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate or retail savings bond for individuals was found; the Ministry of Economy and Finance sells Treasury bonds through the stock exchange (see tbond rows).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PY', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The BCP publishes average deposit rates by type, but its pages block automated reading (Cloudflare challenge) and no other public source with a 2026 savings account rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PY', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":9.7},{"year":2040,"value":6.8},{"year":2065,"value":3.5}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/paraguay/2040/', '2025-12-31', '100 / old-age dependency ratio: 10.35 (2025, World Bank), 14.7 (2040) and 28.2 (2065, https://www.populationpyramid.net/paraguay/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PY', 1, 'tax_bank_interest', 0.08, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Paraguay individual taxes on personal income (reviewed 19 October 2026)', 'https://taxsummaries.pwc.com/paraguay/individual/taxes-on-personal-income', '2026-10-19', 'PwC lists interest on money deposits among capital income (rentas del capital), whose personal income tax (IRP) rate is 8%; exemptions in Law 6380/2019 (e.g. for some securities) could not be checked because the tax authority site was unreachable.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PY', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate for individuals exists in Paraguay (see sanchayapatra_5y_rate), so no tax rate applies.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PY', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No regular 91-day Treasury bill auction by the Ministry of Economy and Finance was found in its 2026 news; short-term central bank paper (IRM) is sold to banks, not individuals.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PY', 1, 'tbond_10y_rate', 0.087, NULL, 'sourced', 'Ministerio de Economia y Finanzas: Treasury bond auction, bond maturing 2035', 'https://www.mef.gov.py/es/institucional/sala-de-prensa/noticias/mef-adjudico-230527-millones-bonos-del-tesoro-tasas', '2026-09-23', 'MEF auction of 23 September 2026 (reopening, via the Asuncion stock exchange): allotment yield 8.70% on the bond maturing in 2035 (about 9 years remaining), 30 basis points below July.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('PY', 1, 'tbond_5y_rate', 0.0826, NULL, 'sourced', 'Ministerio de Economia y Finanzas: Treasury bond auction, bond maturing 2030', 'https://www.mef.gov.py/es/institucional/sala-de-prensa/noticias/mef-adjudico-230527-millones-bonos-del-tesoro-tasas', '2026-09-23', 'MEF auction of 23 September 2026 (reopening, via the Asuncion stock exchange): allotment yield 8.26% on the bond maturing in 2030 (about 4 years remaining), 24 basis points below July.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('QA', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"QA","iso3":"QAT","nameEn":"Qatar","nameNative":"قطر","region":"middle_east_north_africa","languages":["ar","en","fa","ml"],"currency":{"code":"QAR","symbol":"ر.ق","decimals":2,"compact":"intl","usdRate":{"value":3.64,"status":"sourced","sourceName":"World Bank WDI, official exchange rate (PA.NUS.FCRF), Qatar","sourceUrl":"https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=QA","asOf":"2025-12-31","note":"The riyal is pegged at 3.64 per US dollar. CLDR gives no narrow symbol (only ''QAR''); the Arabic abbreviation ر.ق is used locally."}},"instruments":{"savings_account":{"available":true,"localName":"حساب توفير","localNameEn":"Savings account"},"fdr_3m":{"available":true,"localName":"وديعة لأجل (3 أشهر)","localNameEn":"Time deposit (3 months)"},"fdr_1y":{"available":true,"localName":"وديعة لأجل (سنة)","localNameEn":"Time deposit (1 year)"},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No standard monthly recurring deposit product was found."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate for individuals was found."},"tbill_91d":{"available":true,"localName":"أذونات الخزينة","localNameEn":"Treasury bills","note":"Issued monthly by the QCB for 3, 6 and 9 months and bought by banks; individuals reach them only through banks or funds."},"tbond_5y":{"available":true,"localName":"سندات حكومية","localNameEn":"Government bonds","note":"Government bonds and sukuk are auctioned to banks."},"tbond_10y":{"available":true,"localName":"سندات حكومية","localNameEn":"Government bonds","note":"Government bonds and sukuk are auctioned to banks."},"equity_fund":{"available":true,"localName":"صناديق الاستثمار","localNameEn":"Investment funds","note":"Funds investing in Qatari and Gulf shares are offered to retail investors."},"gold":{"available":true,"localName":"الذهب","localNameEn":"Gold","note":"Gold bars, coins and jewellery are freely sold."}},"institutions":{"centralBank":{"name":"Qatar Central Bank (QCB)","url":"https://www.qcb.gov.qa/"},"insuranceRegulator":{"name":"Qatar Central Bank, insurance supervision","url":"https://www.qcb.gov.qa/"},"insuranceComplaints":{"name":"Qatar Central Bank, consumer protection","url":"https://www.qcb.gov.qa/","note":"Complaints about insurers go to the QCB consumer protection function."},"pensionScheme":{"name":"General Retirement and Social Insurance Authority","url":"https://www.daman.gov.qa/"},"oldAgeAllowance":null,"publicHealthCover":{"name":"Ministry of Public Health (public health care)","url":"https://www.moph.gov.qa/"},"depositInsurance":null,"statistics":{"name":"National Planning Council","url":"https://www.npc.qa/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('QA', 1, 'bank_deposit_avg_rate', 0.0468, NULL, 'sourced', 'World Bank WDI, deposit interest rate (FR.INR.DPST), Qatar', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=QA', '2025-12-31', '4.68% in 2025 (IMF International Financial Statistics via the World Bank); the fresher QCB statistics could not be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('QA', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap or published average credit card rate could be read; the QCB site could not be read (certificate error).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('QA', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No deposit insurance scheme or cover limit could be confirmed; the QCB site could not be read (certificate error).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('QA', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No industry-wide rate for a monthly recurring deposit product was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('QA', 1, 'equity_return_base', 0.065, NULL, 'assumption', 'QCB deposit rate 4.10%; World Bank deposit rate 4.68% (2025)', 'https://tradingeconomics.com/qatar/interest-rate', '2026-10-31', 'Base case: about 2.5 points above the safe deposit rate, below the 4-point cap, because the main Qatari index has had a weak, dividend-driven 10-year record.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('QA', 1, 'equity_return_high', 0.09, NULL, 'assumption', 'QCB deposit rate 4.10%; Gulf equity premium', 'https://tradingeconomics.com/qatar/interest-rate', '2026-10-31', 'High case: a fuller equity premium if Gulf markets re-rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('QA', 1, 'equity_return_low', 0.03, NULL, 'assumption', 'QCB deposit rate 4.10% (September 2026); weak 10-year record of Qatar''s main index', 'https://tradingeconomics.com/qatar/interest-rate', '2026-10-31', 'Low case: the local index, which ended the last decade close to where it started, returns less than deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('QA', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Average 1-year time-deposit rates are in QCB statistics, which could not be read (certificate error).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('QA', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Average 3-month time-deposit rates are in QCB statistics, which could not be read (certificate error).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('QA', 1, 'fixed_income_return_base', 0.0375, NULL, 'assumption', 'QCB deposit rate 4.10% (September 2026); World Bank deposit rate 4.68% (2025)', 'https://tradingeconomics.com/qatar/interest-rate', '2026-10-31', 'Base case: a little below today''s untaxed deposit rates, allowing for rate cuts over a long plan.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('QA', 1, 'fixed_income_return_high', 0.045, NULL, 'assumption', 'World Bank deposit rate 4.68% (2025); QCB lending rate 4.60%', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=QA', '2026-10-31', 'High case: deposit rates stay near their 2025 level.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('QA', 1, 'fixed_income_return_low', 0.025, NULL, 'assumption', 'QCB deposit rate 4.10% (September 2026); World Bank deposit rate 4.68% (2025)', 'https://tradingeconomics.com/qatar/interest-rate', '2026-10-31', 'Low case: deposit rates fall with US rates, untaxed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('QA', 1, 'goal_inflation_education', 0.035, NULL, 'assumption', 'Inflation assumption 2%; education CPI 2.1% (January 2026, Trading Economics citing NPC)', 'https://tradingeconomics.com/qatar/inflation-cpi', '2026-10-31', 'Education prices rose about 2% a year recently; private school fees tend to rise faster, so 1.5 points above the inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('QA', 1, 'goal_inflation_health', 0.035, NULL, 'assumption', 'Inflation assumption 2%; health CPI about 0% (May 2026, Trading Economics citing NPC)', 'https://tradingeconomics.com/qatar/inflation-cpi', '2026-10-31', 'Public care keeps the health CPI near zero, but private treatment costs usually rise faster than prices, so 1.5 points above the inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('QA', 1, 'gold_return_base', 0.04, NULL, 'assumption', 'Dollar peg (3.64 QAR per USD); long-run dollar gold trend', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=QA', '2026-10-31', 'Base case: the long-run dollar gold trend of about 4% a year, with no depreciation gain under the peg.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('QA', 1, 'gold_return_high', 0.08, NULL, 'assumption', 'Dollar peg (3.64 QAR per USD); long-run dollar gold trend', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=QA', '2026-10-31', 'High case: strong dollar gold years.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('QA', 1, 'gold_return_low', 0, NULL, 'assumption', 'Dollar peg (3.64 QAR per USD); World Bank exchange rate', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=QA', '2026-10-31', 'Low case: flat dollar gold; the peg means no currency boost.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('QA', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Labour Law (No. 14 of 2004) provides an end-of-service gratuity for workers, but the article giving the weeks of wages per year could not be opened on the Al Meezan legal portal or ILO NATLEX (access refused).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('QA', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a major private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('QA', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premiums by age were found from a public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('QA', 1, 'inflation_cpi', 0.0409, NULL, 'sourced', 'Trading Economics, citing the National Planning Council (NPC), CPI August 2026', 'https://tradingeconomics.com/qatar/inflation-cpi', '2026-08-31', 'Consumer prices up 4.09% year on year in August 2026 (3.98% in July), the highest reading since March; secondary source because the NPC site could not be read (certificate error). World Bank 2024 average 1.3%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('QA', 1, 'inflation_projection', 0.02, NULL, 'assumption', 'Dollar peg; 2005-2026 average CPI inflation of about 2.1% (Trading Economics, citing NPC)', 'https://tradingeconomics.com/qatar/inflation-cpi', '2026-10-31', 'With the riyal pegged to the dollar, inflation has averaged about 2% over two decades, so 2% a year is used for long-range plans.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('QA', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life cover is sold, but no published premium rates per QAR 1,000 of cover by age were found from the regulator or another public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('QA', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The QCB (the insurance regulator) publishes no industry-wide life claim settlement ratio that could be found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('QA', 1, 'life_expectancy', 82.522, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN), Qatar', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=QA', '2024-12-31', '82.5 years in 2024 (men 81.8, women 83.5); the population is mostly younger migrant workers.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('QA', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":24.9,"men":24.3,"women":25.4},{"age":65,"total":20.4,"men":19.8,"women":21.1},{"age":70,"total":16.3,"men":15.6,"women":17},{"age":80,"total":9.3,"men":8.7,"women":9.9}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/qatar/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('QA', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'Eligibility rules for social security assistance to older people could not be read from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('QA', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'Social security assistance for older Qatari nationals exists through the Ministry of Social Development and Family, but no current monthly amount could be read from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('QA', 1, 'oop_health_share', 0.0743, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), Qatar', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=QA', '2023-12-31', '7.4% in 2023 (WHO Global Health Expenditure Database via the World Bank); older than 2025, the latest available.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('QA', 1, 'policy_rate', 0.041, NULL, 'sourced', 'Trading Economics, Qatar Central Bank decision of 16 September 2026', 'https://tradingeconomics.com/qatar/interest-rate', '2026-09-16', 'The QCB raised its deposit rate (QCBDR) by 25 bps to 4.10%, with the lending rate at 4.60% and the repo rate at 4.35%; secondary source because the QCB site could not be read (certificate error). The deposit rate is used as the policy rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('QA', 1, 'public_pension_scheme', NULL, NULL, 'missing', '', '', '2026-10-31', 'The General Retirement and Social Insurance Authority says Social Insurance Law No. 1 of 2022 (issued 19 April 2022) covers Qatari government and private-sector employees and self-employed Qataris, but the pension age and indexation rules could not be read; expatriates are not covered.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('QA', 1, 'retirement_accumulation_return_base', 0.05, NULL, 'assumption', 'QCB deposit rate 4.10%; equity base 6.5%; gold base 4%', 'https://tradingeconomics.com/qatar/interest-rate', '2026-10-31', 'Base case: a balanced mix of deposits or sukuk, equities and some gold.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('QA', 1, 'retirement_accumulation_return_high', 0.07, NULL, 'assumption', 'Equity high case 9%; deposit rate 4.68% (2025)', 'https://tradingeconomics.com/qatar/interest-rate', '2026-10-31', 'High case: a growth-leaning mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('QA', 1, 'retirement_accumulation_return_low', 0.035, NULL, 'assumption', 'QCB deposit rate 4.10%; equity low case 3%', 'https://tradingeconomics.com/qatar/interest-rate', '2026-10-31', 'Low case: a mix earning about deposit rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('QA', 1, 'retirement_age_default', NULL, NULL, 'missing', '', '', '2026-10-31', 'Social Insurance Law No. 1 of 2022 (General Retirement and Social Insurance Authority) covers Qatari private-sector workers, but the pension age could not be read from the authority''s pages (content not loaded) or the law text.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('QA', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'The civil retirement rules under Law No. 1 of 2022 could not be read from the General Retirement and Social Insurance Authority site.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('QA', 1, 'retirement_return_base', 0.035, NULL, 'assumption', 'QCB deposit rate 4.10%; World Bank deposit rate 4.68% (2025)', 'https://tradingeconomics.com/qatar/interest-rate', '2026-10-31', 'Base case: below today''s untaxed deposit rates (no 1-year rate could be read), so it does not exceed the safe rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('QA', 1, 'retirement_return_high', 0.045, NULL, 'assumption', 'World Bank deposit rate 4.68% (2025)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=QA', '2026-10-31', 'High case: deposit rates stay near their 2025 level.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('QA', 1, 'retirement_return_low', 0.025, NULL, 'assumption', 'QCB deposit rate 4.10% (September 2026)', 'https://tradingeconomics.com/qatar/interest-rate', '2026-10-31', 'Low case: deposit rates fall with US rates, untaxed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('QA', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate or retail savings bond for individuals was found; QCB treasury bills and government bonds are auctioned to banks.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('QA', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Average savings-account rates are published in QCB statistics, but the QCB site could not be read (certificate error) and no other official source was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('QA', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":49},{"year":2040,"value":41.7},{"year":2065,"value":22.2}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/qatar/2040/', '2025-12-31', '100 / old-age dependency ratio: 2.04 (2025, World Bank), 2.4 (2040) and 4.5 (2065, populationpyramid.net/qatar/2065/); the very large migrant workforce keeps the ratio high.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('QA', 1, 'tax_bank_interest', 0, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Qatar, individual income determination', 'https://taxsummaries.pwc.com/qatar/individual/income-determination', '2026-10-31', 'Bank interest and returns due to individuals not carrying on a taxable activity are not subject to income tax, and salaries are untaxed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('QA', 1, 'tax_sanchayapatra_profit', 0, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Qatar, individual income determination', 'https://taxsummaries.pwc.com/qatar/individual/income-determination', '2026-10-31', 'Capital gains on securities are exempt for individuals and there is no tax on bank interest or returns; no retail savings certificate exists.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('QA', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The QCB auctions 3-, 6- and 9-month treasury bills to banks each month, but the auction results on the QCB site could not be read (certificate error).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('QA', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The only 10-year yield found (Trading Economics) dates from February 2023, too old to use; the QCB site could not be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('QA', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No current 5-year government bond yield was found from an official or allowed secondary source.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('RO', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"RO","iso3":"ROU","nameEn":"Romania","nameNative":"România","region":"europe_central_asia","languages":["ro","en","hu","fr"],"currency":{"code":"RON","symbol":"lei","decimals":2,"compact":"intl","usdRate":{"value":4.7698,"status":"sourced","sourceName":"National Bank of Romania reference exchange rate (USD)","sourceUrl":"https://curs.bnr.ro/files/xml/years/nbrfxrates2026.xml","asOf":"2026-10-30","note":"RON 4.7698 per US dollar on 30 October 2026 (EUR 5.3426); World Bank 2025 average 4.47."}},"instruments":{"savings_account":{"available":true,"localName":"Cont de economii","localNameEn":"Savings account","sourceUrl":"https://data-api.ecb.europa.eu/service/data/MIR/M.RO.B.L21.A.R.A.2250.RON.N"},"fdr_3m":{"available":true,"localName":"Depozit la termen (3 luni)","localNameEn":"Term deposit (3 months)"},"fdr_1y":{"available":true,"localName":"Depozit la termen (12 luni)","localNameEn":"Term deposit (12 months)","sourceUrl":"https://data-api.ecb.europa.eu/service/data/MIR/M.RO.B.L22.F.R.A.2250.RON.N"},"dps":{"available":false,"localName":null,"localNameEn":"Recurring deposit","note":"No standard monthly recurring-deposit product; regular saving is usually done through savings accounts or retail government bonds."},"sanchayapatra_5y":{"available":true,"localName":"Titluri de stat TEZAUR / FIDELIS","localNameEn":"Retail government bonds (TEZAUR, FIDELIS)","note":"Sold by the Ministry of Finance to individuals: TEZAUR through the State Treasury, post offices and online, FIDELIS listed on the stock exchange; maturities of 1 to about 10 years."},"tbill_91d":{"available":false,"localName":"Certificate de trezorerie","localNameEn":"Treasury certificates","note":"Discount treasury certificates are auctioned by the Ministry of Finance to primary dealers; individuals buy the retail TEZAUR or FIDELIS bonds instead."},"tbond_5y":{"available":true,"localName":"Obligațiuni de stat","localNameEn":"Government bonds","note":"FIDELIS retail bonds and benchmark bonds can be bought through brokers."},"tbond_10y":{"available":true,"localName":"Obligațiuni de stat","localNameEn":"Government bonds","sourceUrl":"https://tradingeconomics.com/romania/government-bond-yield"},"equity_fund":{"available":true,"localName":"Fond de investiții","localNameEn":"Investment funds and index funds (ETFs)","note":"Retail mutual funds and exchange-traded index funds, including funds tracking the BET index, are available."},"gold":{"available":true,"localName":"Aur de investiții","localNameEn":"Investment gold (bars and coins)","note":"Buying physical investment gold is legal and VAT-exempt under EU rules; the BNR publishes a daily gold reference price."}},"institutions":{"centralBank":{"name":"Banca Națională a României (National Bank of Romania)","url":"https://www.bnr.ro/en/"},"insuranceRegulator":{"name":"Financial Supervisory Authority (ASF)","url":"https://asfromania.ro/en"},"insuranceComplaints":{"name":"SAL-FIN (Alternative Dispute Resolution Entity in the Non-Banking Financial Area)","url":"https://www.salfin.ro/","note":"Out-of-court dispute body for consumers in disputes with insurers, set up by the ASF; complaints can also be filed with the ASF."},"pensionScheme":{"name":"National Public Pension House (CNPP)","url":"https://www.cnpp.ro/"},"oldAgeAllowance":{"name":"Minimum inclusion income (venitul minim de incluziune), National Agency for Payments and Social Inspection (ANPIS)","url":"https://www.mmanpis.ro/","note":"Means-tested aid with a higher threshold for single people over 65; claimed at the town hall''s social assistance service."},"publicHealthCover":{"name":"National Health Insurance House (CNAS)","url":"https://cnas.ro/"},"depositInsurance":{"name":"Bank Deposit Guarantee Fund (FGDB)","url":"https://www.fgdb.ro/"},"statistics":{"name":"National Institute of Statistics (INS)","url":"https://insse.ro/cms/en"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RO', 1, 'bank_deposit_avg_rate', 0.0508, NULL, 'sourced', 'ECB MFI interest rate statistics (reported by the BNR): household leu deposits with agreed maturity up to 1 year, new business', 'https://data-api.ecb.europa.eu/service/data/MIR/M.RO.B.L22.F.R.A.2250.RON.N', '2026-09-30', 'No all-maturity average is published for Romania in the ECB dataset; deposits up to 1 year were RON 20.7 billion of new household term deposits in September 2026 against RON 0.2 billion for 1-2 years, so their weighted average (5.08%) is used. World Bank FR.INR.DPST gives 5.23% for 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RO', 1, 'credit_card_rate_cap', 0.2757, NULL, 'sourced', 'ECB MFI interest rate statistics (reported by the BNR): Romanian banks, extended credit card credit to households', 'https://data-api.ecb.europa.eu/service/data/MIR/M.RO.B.A2Z3.A.R.A.2250.RON.N', '2026-09-30', 'Typical rate, not a legal cap: average 27.57% in September 2026 (27.73% in August).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RO', 1, 'deposit_insurance_limit', 534260, NULL, 'sourced', 'European Commission, deposit guarantee schemes (EU rules); BNR reference rate EUR 1 = RON 5.3426 (30 October 2026)', 'https://finance.ec.europa.eu/banking/banking-regulation/deposit-guarantee-schemes_en', '2026-10-30', 'EU rules guarantee deposits up to EUR 100,000 per depositor per bank, paid in lei by the Bank Deposit Guarantee Fund (FGDB, whose site could not be read); converted at the BNR rate of 30 October 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RO', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No standard monthly recurring-deposit product with a published average rate was found for Romania.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RO', 1, 'equity_return_base', 0.08, NULL, 'assumption', 'BET index (Trading Economics); after-tax 1-year deposit 5.08% x 0.9 = 4.6%', 'https://tradingeconomics.com/romania/stock-market', '2026-10-31', 'Base case: about 3.4 points over the after-tax deposit rate, well below the BET''s strong recent record because the index is concentrated in a few stocks, mostly energy and banks.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RO', 1, 'equity_return_high', 0.11, NULL, 'assumption', 'BET index (Trading Economics), roughly 17% a year in price terms since 2016', 'https://tradingeconomics.com/romania/stock-market', '2026-10-31', 'High case: Romanian and diversified equity funds keep close to their strong leu returns of the last decade.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RO', 1, 'equity_return_low', 0.05, NULL, 'assumption', 'BET index (Trading Economics); after-tax 1-year deposit 5.08% x 0.9 = 4.6%', 'https://tradingeconomics.com/romania/stock-market', '2026-10-31', 'Low case: Romanian shares give back much of the 2025-26 rally and earn only a little more than after-tax deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RO', 1, 'fdr_1y_rate', 0.0508, NULL, 'sourced', 'ECB MFI interest rate statistics (reported by the BNR): household leu deposits with agreed maturity up to 1 year, new business', 'https://data-api.ecb.europa.eu/service/data/MIR/M.RO.B.L22.F.R.A.2250.RON.N', '2026-09-30', 'Bucket covers all fixed terms up to one year (5.04% in August 2026); 1-2 year deposits paid 5.95% in September 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RO', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The BNR and ECB publish household term deposits up to 1 year as one bucket (5.08% in September 2026); no separate 3-month average was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RO', 1, 'fixed_income_return_base', 0.045, NULL, 'assumption', 'After-tax 1-year deposit 4.6% (ECB MIR); 1-2 year deposits 5.95% (September 2026)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.RO.B.L22.G.R.A.2250.RON.N', '2026-10-31', 'Base case: a mix of term deposits and retail government bonds, allowing for policy-rate cuts.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RO', 1, 'fixed_income_return_high', 0.06, NULL, 'assumption', '10-year government bond 7.20% (Trading Economics)', 'https://tradingeconomics.com/romania/government-bond-yield', '2026-10-31', 'High case: locking in medium and long government bonds at today''s yields.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RO', 1, 'fixed_income_return_low', 0.04, NULL, 'assumption', 'Household deposits up to 1 year 5.08% less 10% tax = 4.6% (ECB MIR, September 2026)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.RO.B.L22.F.R.A.2250.RON.N', '2026-10-31', 'Low case: after-tax bank term deposits, with rates falling as inflation eases.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RO', 1, 'goal_inflation_education', 0.06, NULL, 'assumption', 'Eurostat/ECB HICP Romania, education: 8.5% year on year in December 2025', 'https://data-api.ecb.europa.eu/service/data/ICP/M.RO.N.100000.4.ANR', '2026-10-31', 'Education prices rose 8.5% in 2025, in line with high general inflation; planning uses 6%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RO', 1, 'goal_inflation_health', 0.06, NULL, 'assumption', 'Eurostat/ECB HICP Romania, health: 8.9% year on year in December 2025', 'https://data-api.ecb.europa.eu/service/data/ICP/M.RO.N.060000.4.ANR', '2026-10-31', 'Health prices rose 8.9% in 2025, slightly above general HICP (8.6%); planning uses 6%, 1.5 points above general planning inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RO', 1, 'gold_return_base', 0.06, NULL, 'assumption', 'Gold USD price history (Trading Economics); BNR 2.5% inflation target', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Base case: dollar gold rises with world inflation plus a little, and the leu loses about 2% a year against the dollar as inflation stays above the euro area''s.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RO', 1, 'gold_return_high', 0.1, NULL, 'assumption', 'Gold USD price history (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'High case: a repeat of gold''s strong 2005-2025 trend in leu terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RO', 1, 'gold_return_low', 0.025, NULL, 'assumption', 'Gold USD price history (Trading Economics); BNR gold price RON 609.57 per gram (30 Oct 2026)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Low case: gold stalls after the 2025-26 spike and the leu stays stable.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RO', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No statutory days-per-year end-of-service payment was found; severance on collective dismissal is set by collective agreements, and no official page stating the Labour Code rule could be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RO', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'Hospital care is covered by the National Health Insurance House (CNAS) for insured people; no official figure for the out-of-pocket cost of a major private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RO', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Private health insurance and subscriptions are sold in Romania, but no published premium table per RON 100,000 of cover from a regulator or public source was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RO', 1, 'inflation_cpi', 0.066, NULL, 'sourced', 'National Institute of Statistics (INS) consumer price index, September 2026, as reported by Trading Economics (secondary source)', 'https://tradingeconomics.com/romania/inflation-cpi', '2026-09-30', 'Annual CPI inflation 6.6% in September 2026 (6.2% in August; 10.85% peak in May 2026), released 13 October 2026. Secondary source because the INS site could not be reached. World Bank 2025 average 7.2%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RO', 1, 'inflation_projection', 0.045, NULL, 'assumption', 'BNR inflation target 2.5% +/- 1 point; Romanian HICP 2021-2025 average 7.7% (ECB ICP)', 'https://data-api.ecb.europa.eu/service/data/ICP/A.RO.N.000000.4.AVR', '2026-10-31', 'The BNR targets 2.5% but inflation averaged 7.7% over 2021-2025 and is 6.6% now, so planning uses 4.5%, above the target band.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RO', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life cover is sold in Romania, but no regulator or official premium table per sum insured was found; only individual company quotes exist.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RO', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Financial Supervisory Authority (ASF) publishes insurance market reports, but no industry-wide life claim settlement ratio was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RO', 1, 'life_expectancy', 76.4, NULL, 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/romania', '2026-07-01', 'Men 72.9, women 79.9 (UN WPP estimate for 2026); World Bank 2024 figure 76.5.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RO', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":20.7,"men":18.4,"women":22.8},{"age":65,"total":17.1,"men":15.2,"women":18.6},{"age":70,"total":13.6,"men":12.2,"women":14.7},{"age":80,"total":7.5,"men":7,"women":7.8}]}', 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/romania', '2026-07-01', 'Remaining years from georank''s expected age at death by current age (UN WPP 2026 estimate).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RO', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":65,"womenAge":65,"over90Monthly":null,"meansTested":true}', 'sourced', 'European Commission, Your social security rights in Romania (July 2026): minimum inclusion income', 'https://employment-social-affairs.ec.europa.eu/document/download/9b140205-9066-4a16-876f-eb7643365cc9_en', '2026-07-31', 'Inclusion aid at the higher RON 533 threshold for single persons aged over 65; means-tested on household income and assets (no second home, car or large land holdings), legal residence in Romania.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RO', 1, 'old_age_allowance_monthly', 533, NULL, 'sourced', 'European Commission, Your social security rights in Romania (July 2026): minimum inclusion income', 'https://employment-social-affairs.ec.europa.eu/document/download/9b140205-9066-4a16-876f-eb7643365cc9_en', '2026-07-31', 'Romania has no separate social pension; a single person aged over 65 with no income can get the inclusion aid (ajutor de incluziune) of up to RON 533 a month (threshold RON 533 minus equivalised income; RON 366 for younger people), since March 2025. Pensioners with low contributory pensions get the social indemnity top-up instead.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RO', 1, 'oop_health_share', 0.2296, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=RO', '2023-12-31', 'Out-of-pocket spending was 23.0% of current health expenditure in 2023 (latest available; older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RO', 1, 'policy_rate', 0.065, NULL, 'sourced', 'National Bank of Romania monetary policy rate, as reported by Trading Economics (secondary source)', 'https://tradingeconomics.com/romania/interest-rate', '2026-10-08', 'Policy rate held at 6.50% at the 8 October 2026 board meeting, unchanged since August 2024; next decision 12 November 2026. Secondary source because the BNR pages load their figures by script.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RO', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":65,"nomineeUntilAge":null,"inflationLinked":true,"taxFree":false}', 'sourced', 'European Commission, Your social security rights in Romania (July 2026)', 'https://employment-social-affairs.ec.europa.eu/document/download/9b140205-9066-4a16-876f-eb7643365cc9_en', '2026-07-31', 'Compulsory points-based public pension (CNPP): standard age 65 for men and rising to 65 for women by 2035, at least 15 years of contributions; pension point value RON 81 from January 2026. By law the point is indexed yearly to inflation plus half of real wage growth, though it was frozen in 2025-2026. Pensions above RON 3,000 a month are taxed on the excess. Workers born after 1 July 1971 also pay into a mandatory private pension fund (Pillar II).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RO', 1, 'retirement_accumulation_return_base', 0.06, NULL, 'assumption', 'Fixed income base 4.5%; equity base 8%', 'https://tradingeconomics.com/romania/stock-market', '2026-10-31', 'Base case: roughly half shares at 8% and half safe fixed income at about 4.5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RO', 1, 'retirement_accumulation_return_high', 0.08, NULL, 'assumption', 'Equity high 11%; government bonds 7.2%', 'https://tradingeconomics.com/romania/stock-market', '2026-10-31', 'High case for a growth-leaning balanced mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RO', 1, 'retirement_accumulation_return_low', 0.04, NULL, 'assumption', 'After-tax deposits 4.5%; BET record (Trading Economics)', 'https://tradingeconomics.com/romania/stock-market', '2026-10-31', 'Low case for a balanced mix if shares lag.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RO', 1, 'retirement_age_default', 65, NULL, 'sourced', 'European Commission, Your social security rights in Romania (July 2026)', 'https://employment-social-affairs.ec.europa.eu/document/download/9b140205-9066-4a16-876f-eb7643365cc9_en', '2026-07-31', 'Standard retirement age is 65 for men; for women it is 62 years 6 months in 2026 and rises to 65 by January 2035, so 65 applies to everyone born after 1975. Minimum contribution period 15 years.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RO', 1, 'retirement_age_government', 65, NULL, 'sourced', 'European Commission, Your social security rights in Romania (July 2026)', 'https://employment-social-affairs.ec.europa.eu/document/download/9b140205-9066-4a16-876f-eb7643365cc9_en', '2026-07-31', 'Civil servants are covered by the public pension system with the same standard ages (65 for men, rising to 65 for women by 2035); magistrates, military and police have special schemes.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RO', 1, 'retirement_return_base', 0.0425, NULL, 'assumption', 'Household deposits up to 1 year 5.08% less 10% tax = 4.6% (ECB MIR, September 2026)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.RO.B.L22.F.R.A.2250.RON.N', '2026-10-31', 'Base case: kept below the after-tax 1-year deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RO', 1, 'retirement_return_high', 0.055, NULL, 'assumption', '1-2 year deposits 5.95% (ECB MIR) and 10-year government bond 7.20% (Trading Economics)', 'https://tradingeconomics.com/romania/government-bond-yield', '2026-10-31', 'High case: medium-term deposits and government bonds bought at today''s yields and held to maturity.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RO', 1, 'retirement_return_low', 0.03, NULL, 'assumption', 'After-tax 1-year deposit 4.6% (ECB MIR, September 2026)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.RO.B.L22.F.R.A.2250.RON.N', '2026-10-31', 'Low case: after-tax deposits after the policy rate is cut as inflation falls.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RO', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Ministry of Finance sells retail government bonds (TEZAUR at the Treasury and post offices, FIDELIS on the stock exchange), but its pages could not be reached on 31 October 2026, so the current 5-year rate was not read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RO', 1, 'savings_account_rate', 0.0052, NULL, 'sourced', 'ECB MFI interest rate statistics (reported by the BNR): Romanian banks, overnight leu deposits from households', 'https://data-api.ecb.europa.eu/service/data/MIR/M.RO.B.L21.A.R.A.2250.RON.N', '2026-09-30', 'Average rate on household overnight (current and savings) leu deposits was 0.52% in September 2026 (0.51% in August).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RO', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":3.19},{"year":2040,"value":2.44},{"year":2065,"value":1.98}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/romania/2040/', '2025-12-31', '100 / old-age dependency ratio: 31.3 (2025, World Bank), 40.9 (2040) and 50.4 (2065, populationpyramid.net/romania/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RO', 1, 'tax_bank_interest', 0.1, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Romania income determination', 'https://taxsummaries.pwc.com/romania/individual/income-determination', '2026-09-25', 'Interest income is taxed at a flat 10%, withheld by the payer as a final tax (page reviewed 25 September 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RO', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'The PwC summary does not say whether interest on retail government bonds (TEZAUR, FIDELIS) is taxed, and the Ministry of Finance pages could not be reached to confirm their tax exemption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RO', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No current 3-month treasury certificate yield could be read; the Ministry of Finance auction results pages could not be reached and no secondary source listed one.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RO', 1, 'tbond_10y_rate', 0.072, NULL, 'sourced', 'Trading Economics, Romania 10-year government bond yield (secondary source)', 'https://tradingeconomics.com/romania/government-bond-yield', '2026-10-30', '10-year yield 7.20% on 30 October 2026; the ECB long-term convergence yield for Romania was 6.71% in September 2026 (ECB IRS dataset).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RO', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 5-year Romanian government bond yield could be read from an official or reachable secondary page on 31 October 2026.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('RS', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"RS","iso3":"SRB","nameEn":"Serbia","nameNative":"Србија","region":"europe_central_asia","languages":["sr","hu","sq","ro","en"],"currency":{"code":"RSD","symbol":"дин.","decimals":2,"compact":"intl","usdRate":{"value":105.056,"status":"sourced","sourceName":"National Bank of Serbia, official middle exchange rate (list no. 208)","sourceUrl":"https://webappcenter.nbs.rs/ExchangeRateWebApp/ExchangeRate/CurrentMiddleRate?","asOf":"2026-10-30","note":"105.0560 dinars per US dollar and 117.5367 per euro on 30 October 2026. World Bank 2025 average 103.98."}},"instruments":{"savings_account":{"available":true,"localName":"Штедни рачун","localNameEn":"Savings account","note":"Interest on dinar savings is tax-free; interest on foreign-currency savings is taxed at 15%."},"fdr_3m":{"available":true,"localName":"Орочена штедња","localNameEn":"Term deposit (3 months)"},"fdr_1y":{"available":true,"localName":"Орочена штедња","localNameEn":"Term deposit (1 year)","sourceUrl":"https://www.nbs.rs/export/sites/NBS_site/documents/statistika/monetarni_sektor/SBMS23.xls"},"dps":{"available":false,"localName":null,"localNameEn":"Monthly recurring deposit","note":"No standard fixed-installment recurring deposit with a published rate was found."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":"Government savings bond for individuals","note":"No standing retail government savings programme was found; individuals can hold dinar government bonds, whose interest is tax-free."},"tbill_91d":{"available":false,"localName":"Државни записи","localNameEn":"Treasury bills","note":"No 3-month treasury bill auctions were recorded in 2024-2026."},"tbond_5y":{"available":true,"localName":"Државне обвезнице","localNameEn":"Government bonds (dinar)","sourceUrl":"https://www.nbs.rs/export/sites/NBS_site/documents/statistika/monetarni_sektor/SBMS19.xls"},"tbond_10y":{"available":true,"localName":"Државне обвезнице","localNameEn":"Government bonds (dinar, about 10 years)","sourceUrl":"https://www.nbs.rs/export/sites/NBS_site/documents/statistika/monetarni_sektor/SBMS19.xls"},"equity_fund":{"available":true,"localName":"Инвестициони фондови","localNameEn":"Investment funds","note":"Open-end investment funds are supervised by the Securities Commission; the local stock market is small."},"gold":{"available":true,"localName":"Злато (полуге и дукати)","localNameEn":"Gold bars and coins","note":"No restriction on buying physical gold was found."}},"institutions":{"centralBank":{"name":"National Bank of Serbia","url":"https://www.nbs.rs/en/"},"insuranceRegulator":{"name":"National Bank of Serbia, insurance supervision","url":"https://www.nbs.rs/en/finansijske-institucije/osiguranje/"},"insuranceComplaints":{"name":"National Bank of Serbia, Financial Consumer Protection","url":"https://www.nbs.rs/en/","note":"The National Bank handles complaints and out-of-court mediation with banks and insurers."},"pensionScheme":{"name":"Republic Pension and Disability Insurance Fund (PIO Fund)","url":"https://www.pio.rs/en/old-age-pension"},"publicHealthCover":{"name":"Republic Health Insurance Fund (RFZO)","url":"https://www.rfzo.rs/"},"depositInsurance":{"name":"Deposit Insurance Agency","url":"https://www.aod.rs/clan/osigdepoz/deponenti"},"statistics":{"name":"Statistical Office of the Republic of Serbia","url":"https://www.stat.gov.rs/en-us/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RS', 1, 'bank_deposit_avg_rate', 0.0388, NULL, 'sourced', 'National Bank of Serbia, Table 1.3.5 interest rates on household deposits by maturity, new business (total term, all currencies)', 'https://www.nbs.rs/export/sites/NBS_site/documents/statistika/monetarni_sektor/SBMS23.xls', '2026-09-30', 'All new household term deposits, September 2026: dinar 5.07%, euro and other foreign currency 3.41% (most household savings are in euros).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RS', 1, 'credit_card_rate_cap', 0.1775, NULL, 'sourced', 'National Bank of Serbia, maximum effective interest rates under the consumer protection law (credit card debt, dinars)', 'https://webappcenter.nbs.rs/webapp/CultureInfo/OpenPage?culture=en-Us&&pageUrl=/WebApp/FinInstBank/EffectiveInterestRateLimit/Index?', '2026-09-15', 'Legal maximum effective rate on dinar credit card debt (key rate 5.75% plus 12 points); 14.65% for euro, 19.75% on dinar current-account overdrafts.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RS', 1, 'deposit_insurance_limit', 5876835, NULL, 'sourced', 'Deposit Insurance Agency of Serbia, depositors', 'https://www.aod.rs/clan/osigdepoz/deponenti', '2026-10-30', 'Up to EUR 50,000 per depositor per bank, dinar and foreign-currency deposits combined; converted at the NBS middle rate of 117.5367 dinars per euro (30 October 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RS', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No standard monthly recurring deposit product with a published market rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RS', 1, 'equity_return_base', 0.07, NULL, 'assumption', 'Household dinar 1-year deposit 5.09% (tax-free, NBS) plus an equity premium', 'https://www.nbs.rs/export/sites/NBS_site/documents/statistika/monetarni_sektor/SBMS23.xls', '2026-10-31', 'The local exchange (BELEX) is small and illiquid, so the base is a diversified index fund in dinar terms, about 2 points over the tax-free dinar deposit rate and within the 4-point limit.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RS', 1, 'equity_return_high', 0.095, NULL, 'assumption', 'Long-run global equity returns; dinar managed against the euro', 'https://webappcenter.nbs.rs/ExchangeRateWebApp/ExchangeRate/CurrentMiddleRate?', '2026-10-31', 'High case near long-run world equity returns plus slow dinar depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RS', 1, 'equity_return_low', 0.035, NULL, 'assumption', 'Small, illiquid Belgrade Stock Exchange; global equity in dinar terms; NBS middle exchange rate', 'https://webappcenter.nbs.rs/ExchangeRateWebApp/ExchangeRate/CurrentMiddleRate?', '2026-10-31', 'Low case for a global or regional index fund in dinar terms in a weak decade for shares.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RS', 1, 'fdr_1y_rate', 0.0509, NULL, 'sourced', 'National Bank of Serbia, Table 1.3.5 interest rates on household deposits by maturity, new business (dinar, up to 1 year)', 'https://www.nbs.rs/export/sites/NBS_site/documents/statistika/monetarni_sektor/SBMS23.xls', '2026-09-30', 'Household dinar term deposits up to 1 year, September 2026 (updated 28 October 2026); over 1 to 2 years 4.99%. Euro deposits up to 1 year pay 3.42%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RS', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The National Bank reports term deposits only as ''up to 1 year'' (5.09% for household dinar deposits, September 2026), with no 3-month split.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RS', 1, 'fixed_income_return_base', 0.045, NULL, 'assumption', 'Household dinar term deposit up to 1 year 5.09% (tax-free); 5-year dinar bond 5.00% (tax-free)', 'https://www.nbs.rs/export/sites/NBS_site/documents/statistika/monetarni_sektor/SBMS23.xls', '2026-10-31', 'Base case: tax-free dinar term deposits and bonds at about 5% today, trimmed for lower rates over the long run.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RS', 1, 'fixed_income_return_high', 0.055, NULL, 'assumption', 'Dinar government bonds 5.00-5.07% and 1-year dinar deposits 5.09% (NBS)', 'https://www.nbs.rs/export/sites/NBS_site/documents/statistika/monetarni_sektor/SBMS19.xls', '2026-10-31', 'High case: rates stay at or above today''s level.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RS', 1, 'fixed_income_return_low', 0.03, NULL, 'assumption', 'Household euro term deposits 3.41% and dinar 5.07% (NBS, Sep 2026)', 'https://www.nbs.rs/export/sites/NBS_site/documents/statistika/monetarni_sektor/SBMS23.xls', '2026-10-31', 'Low case: rates fall as the key rate is cut, or savings are kept in sight accounts.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RS', 1, 'goal_inflation_education', 0.035, NULL, 'assumption', 'Education CPI +1.2% year on year in September 2026 (Trading Economics, Statistical Office data)', 'https://tradingeconomics.com/serbia/inflation-cpi', '2026-10-31', 'Education prices are rising slowly, so we plan with the general 3.5% projection.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RS', 1, 'goal_inflation_health', 0.055, NULL, 'assumption', 'Health CPI +7.7% year on year in September 2026 (Trading Economics, Statistical Office data)', 'https://tradingeconomics.com/serbia/inflation-cpi', '2026-10-31', 'Health prices are rising about twice as fast as the overall CPI, so we plan with 2 points over the 3.5% projection.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RS', 1, 'gold_return_base', 0.055, NULL, 'assumption', 'NBS official middle exchange rate; long-run dollar gold trend', 'https://webappcenter.nbs.rs/ExchangeRateWebApp/ExchangeRate/CurrentMiddleRate?', '2026-10-31', 'Long-run dollar gold trend of about 4-5% plus about 1% a year of dinar depreciation (3.5% planned inflation against about 2% abroad).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RS', 1, 'gold_return_high', 0.09, NULL, 'assumption', 'NBS official middle exchange rate (dinars per USD)', 'https://webappcenter.nbs.rs/ExchangeRateWebApp/ExchangeRate/CurrentMiddleRate?', '2026-10-31', 'High case: strong dollar gold and a weaker euro and dinar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RS', 1, 'gold_return_low', 0.015, NULL, 'assumption', 'NBS official middle exchange rate (dinars per USD)', 'https://webappcenter.nbs.rs/ExchangeRateWebApp/ExchangeRate/CurrentMiddleRate?', '2026-10-31', 'Low case: flat dollar gold and a stable dinar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RS', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Labour Law (Art. 119) requires a retirement severance of at least two average salaries, a flat amount rather than days per year of service; Art. 158 gives at least one third of monthly salary per year of service only on redundancy. Neither fits a days-per-year gratuity rule.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RS', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'Hospital care is covered by the Republic Health Insurance Fund (RFZO) with co-payments; no official figure for the cost of a major private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RS', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Voluntary health insurance exists but no published premium table per 100,000 dinars of cover by age was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RS', 1, 'inflation_cpi', 0.041, NULL, 'sourced', 'National Bank of Serbia (home page, inflation release of 12 October 2026); Statistical Office data', 'https://www.nbs.rs/en/indeks/', '2026-09-30', 'Annual CPI 4.1% in September 2026, up from 2.2% in August (Trading Economics confirms). Target 3% +/-1.5 points. World Bank 2025 average 3.9%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RS', 1, 'inflation_projection', 0.035, NULL, 'assumption', 'NBS inflation target 3% +/-1.5 points (2026-2028); CPI 4.1% (Sep 2026)', 'https://www.nbs.rs/en/ciljevi-i-funkcije/monetarna-politika/inflacija/', '2026-10-31', 'Inflation has been inside the target band since 2025 but spiked above 12% in 2022-2023, so we plan with 3.5%, a little above the 3% target.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RS', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Risk life cover is sold (often with loans), but no regulator or official premium table per 1,000 dinars of cover by age was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RS', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The National Bank supervises insurers and publishes sector reports, but no industry-wide life claim settlement ratio was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RS', 1, 'life_expectancy', 75.97, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=RS', '2024-12-31', 'Men 73.7, women 78.4 (2024, older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RS', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":20.7,"men":18.3,"women":23.1},{"age":65,"total":17,"men":14.8,"women":19},{"age":70,"total":13.4,"men":11.6,"women":15.1},{"age":80,"total":7.8,"men":6.6,"women":9}]}', 'sourced', 'UN WPP 2024 medium variant via populationpyramid.net (mortality, 2026)', 'https://www.populationpyramid.net/mortality/serbia/', '2026-01-01', 'Secondary source of UN WPP 2024 for 2026, five-year age groups; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RS', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension scheme with age-based eligibility was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RS', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age (social) pension was found in the pension law or on the Pension Fund''s site; older people without a pension can apply for means-tested financial social assistance, which is not an old-age benefit. Not confirmed as absent from an official statement.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RS', 1, 'oop_health_share', 0.3214, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=RS', '2023-12-31', 'Latest available year is 2023 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RS', 1, 'policy_rate', 0.0575, NULL, 'sourced', 'National Bank of Serbia, key policy rate', 'https://www.nbs.rs/en/indeks/', '2026-10-08', 'Kept at 5.75% on 8 October 2026; unchanged since September 2024.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RS', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":65,"nomineeUntilAge":null,"inflationLinked":true,"taxFree":true}', 'sourced', 'Law on Pension and Disability Insurance, Articles 19, 19a and 80 (Pension and Disability Insurance Fund); PwC Tax Summaries (pensions exempt)', 'https://www.pio.rs/sites/default/files/Zakoni/Zakon_o_PIO-2024.pdf', '2026-10-31', 'Compulsory pay-as-you-go pension (PIO Fund) from 65 with 15 years of insurance (women 64 in 2026). From each December pensions are adjusted by wage growth, CPI, or half of each, depending on pension spending as a share of GDP (Art. 80). Pensions are exempt from income tax (PwC).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RS', 1, 'retirement_accumulation_return_base', 0.055, NULL, 'assumption', 'Fixed income base 4.5%; equity base 7%', 'https://www.nbs.rs/export/sites/NBS_site/documents/statistika/monetarni_sektor/SBMS23.xls', '2026-10-31', 'Base case: roughly half equity funds at 7% and half dinar deposits and bonds at 4.5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RS', 1, 'retirement_accumulation_return_high', 0.075, NULL, 'assumption', 'Fixed income high 5.5%; equity high 9.5%', 'https://www.nbs.rs/export/sites/NBS_site/documents/statistika/monetarni_sektor/SBMS19.xls', '2026-10-31', 'High case for a growth-leaning balanced mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RS', 1, 'retirement_accumulation_return_low', 0.035, NULL, 'assumption', 'Fixed income low 3%; equity low 3.5%', 'https://www.nbs.rs/export/sites/NBS_site/documents/statistika/monetarni_sektor/SBMS23.xls', '2026-10-31', 'Low case for a balanced mix if shares lag.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RS', 1, 'retirement_age_default', 65, NULL, 'sourced', 'Law on Pension and Disability Insurance, Articles 19 and 19a (consolidated text, Pension and Disability Insurance Fund)', 'https://www.pio.rs/sites/default/files/Zakoni/Zakon_o_PIO-2024.pdf', '2026-10-31', 'Old-age pension at 65 with at least 15 years of insurance (or 45 years at any age). Women: 64 in 2026, rising by 2 months a year to 65 from 2032. Early pension from 60 with 40 years, reduced 0.34% per month.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RS', 1, 'retirement_age_government', 65, NULL, 'sourced', 'Law on Pension and Disability Insurance, Article 19 (consolidated text, Pension and Disability Insurance Fund)', 'https://www.pio.rs/sites/default/files/Zakoni/Zakon_o_PIO-2024.pdf', '2026-10-31', 'Public employees are insured in the same compulsory scheme as private employees; same pension ages (women 64 in 2026, 65 from 2032).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RS', 1, 'retirement_return_base', 0.04, NULL, 'assumption', 'Household dinar term deposit up to 1 year 5.09%, interest tax-free (NBS, PwC)', 'https://www.nbs.rs/export/sites/NBS_site/documents/statistika/monetarni_sektor/SBMS23.xls', '2026-10-31', 'Base case below today''s tax-free 1-year dinar deposit rate, allowing for rate cuts over a long retirement.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RS', 1, 'retirement_return_high', 0.05, NULL, 'assumption', 'Dinar government bonds 5.00-5.07%, tax-free (NBS)', 'https://www.nbs.rs/export/sites/NBS_site/documents/statistika/monetarni_sektor/SBMS19.xls', '2026-10-31', 'High case: locking in dinar bond and deposit rates near 5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RS', 1, 'retirement_return_low', 0.025, NULL, 'assumption', 'Household euro term deposits 3.41% (NBS, Sep 2026)', 'https://www.nbs.rs/export/sites/NBS_site/documents/statistika/monetarni_sektor/SBMS23.xls', '2026-10-31', 'Low case: lower deposit rates and some savings in sight accounts.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RS', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No standing government savings certificate or retail bond programme for individuals was found; dinar government bonds are sold at Ministry of Finance auctions.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RS', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The National Bank publishes household term deposit rates by maturity but no average rate on sight or savings accounts was found in its tables.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RS', 1, 'support_ratio', NULL, '{"points":[{"year":2026,"value":2.67},{"year":2040,"value":2.31},{"year":2065,"value":1.77}]}', 'sourced', 'UN WPP 2024 medium variant via populationpyramid.net (old-age dependency ratio)', 'https://www.populationpyramid.net/serbia/2040/', '2026-01-01', '100 / old-age dependency ratio: 37.5 (2026, /serbia/2026/), 43.2 (2040) and 56.6 (2065, /serbia/2065/). World Bank 2025: 36.8.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RS', 1, 'tax_bank_interest', 0, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Serbia income determination', 'https://taxsummaries.pwc.com/serbia/individual/income-determination', '2026-08-07', 'PwC: ''tax is not payable on the interest accrued from savings in Serbian dinars''; other interest on savings and deposits (including foreign-currency savings) is investment income taxed at 15% of the gross amount.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RS', 1, 'tax_sanchayapatra_profit', 0, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Serbia income determination', 'https://taxsummaries.pwc.com/serbia/individual/income-determination', '2026-08-07', 'Interest on government bonds is exempt from tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RS', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 3-month dinar treasury bill auction is recorded in the National Bank''s table of government securities rates (SBMS19) for 2024-2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RS', 1, 'tbond_10y_rate', 0.0507, NULL, 'sourced', 'National Bank of Serbia, Table 1.3.12 interest rates on securities (dinar government securities, 10.5 years)', 'https://www.nbs.rs/export/sites/NBS_site/documents/statistika/monetarni_sektor/SBMS19.xls', '2026-01-31', 'Weighted average rate at the January 2026 auction of 10.5-year dinar bonds; no exact 10-year auction was held in 2025-2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RS', 1, 'tbond_5y_rate', 0.05, NULL, 'sourced', 'National Bank of Serbia, Table 1.3.12 interest rates on securities (dinar government securities, 5 years)', 'https://www.nbs.rs/export/sites/NBS_site/documents/statistika/monetarni_sektor/SBMS19.xls', '2026-06-30', 'Weighted average rate at the June 2026 auction of 5-year dinar bonds (4.59% in May 2026).', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('RU', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"RU","iso3":"RUS","nameEn":"Russia","nameNative":"Россия","region":"europe_central_asia","languages":["ru","tt","ba","cv","ce"],"currency":{"code":"RUB","symbol":"₽","decimals":2,"compact":"intl","usdRate":{"value":80.5573,"status":"sourced","sourceName":"Bank of Russia, official exchange rates","sourceUrl":"https://www.cbr.ru/eng/currency_base/daily/","asOf":"2026-10-31","note":"Official rate set for 31 October 2026 (EUR 89.6603). World Bank 2025 average 83.65."}},"instruments":{"savings_account":{"available":true,"localName":"Накопительный счёт","localNameEn":"Savings account","note":"The bank can change the rate at any time; interest is usually paid on the minimum monthly balance.","sourceUrl":"https://fincult.info/article/kak-vybrat-vklad/"},"fdr_3m":{"available":true,"localName":"Срочный вклад","localNameEn":"Term deposit (3 months)","sourceUrl":"https://www.cbr.ru/eng/statistics/bank_sector/int_rat/"},"fdr_1y":{"available":true,"localName":"Срочный вклад","localNameEn":"Term deposit (1 year)","sourceUrl":"https://www.cbr.ru/eng/statistics/bank_sector/int_rat/"},"dps":{"available":false,"localName":null,"localNameEn":"Monthly recurring deposit","note":"No standard fixed-installment recurring deposit was found; term deposits that allow top-ups (popolnyaemy vklad) are the nearest product."},"sanchayapatra_5y":{"available":false,"localName":"ОФЗ-н","localNameEn":"Federal loan bonds for individuals (OFZ-n)","note":"Discontinued: issuance stopped in 2022 and the last issue was redeemed in February 2025.","sourceUrl":"https://ru.wikipedia.org/wiki/ОФЗ-н"},"tbill_91d":{"available":true,"localName":"ОФЗ с коротким сроком до погашения","localNameEn":"Short-dated federal loan bonds (OFZ)","note":"No treasury bills are sold; the 3-month rate is the short end of the OFZ curve, bought through a brokerage account on the exchange.","sourceUrl":"https://www.cbr.ru/eng/hd_base/zcyc_params/"},"tbond_5y":{"available":true,"localName":"Облигации федерального займа (ОФЗ)","localNameEn":"Federal loan bonds (OFZ)","sourceUrl":"https://www.cbr.ru/eng/hd_base/zcyc_params/"},"tbond_10y":{"available":true,"localName":"Облигации федерального займа (ОФЗ)","localNameEn":"Federal loan bonds (OFZ)","sourceUrl":"https://www.cbr.ru/eng/hd_base/zcyc_params/"},"equity_fund":{"available":true,"localName":"Паевой инвестиционный фонд (ПИФ) или биржевой фонд (БПИФ)","localNameEn":"Unit investment fund or exchange-traded fund","note":"Funds holding Russian shares are widely available; foreign index funds are largely inaccessible since 2022."},"gold":{"available":true,"localName":"Золото в слитках и монетах","localNameEn":"Gold bars and coins","note":"Individuals can buy bars and investment coins from banks; VAT on gold bars for individuals was removed in 2022."}},"institutions":{"centralBank":{"name":"Bank of Russia","url":"https://www.cbr.ru/eng/"},"insuranceRegulator":{"name":"Bank of Russia (insurance market supervision)","url":"https://www.cbr.ru/eng/insurance/"},"insuranceComplaints":{"name":"Financial Ombudsman (Service of the Financial Consumer Ombudsman)","url":"https://finombudsman.ru/","note":"Statutory pre-court route for disputes with insurers; complaints can also be sent to the Bank of Russia''s internet reception."},"pensionScheme":{"name":"Social Fund of Russia, old-age insurance pension","url":"https://sfr.gov.ru/grazhdanam/pensionnoe_obespechenie/strahovaya_pensiya_po_starosti/"},"oldAgeAllowance":{"name":"Social Fund of Russia, social old-age pension","url":"https://sfr.gov.ru/grazhdanam/pensionnoe_obespechenie/socialnaya_pensiya/"},"publicHealthCover":{"name":"Federal Compulsory Medical Insurance Fund (OMS)","url":"https://www.ffoms.gov.ru/"},"depositInsurance":{"name":"Deposit Insurance Agency","url":"https://www.asv.org.ru/"},"statistics":{"name":"Federal State Statistics Service (Rosstat)","url":"https://rosstat.gov.ru/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RU', 1, 'bank_deposit_avg_rate', 0.1284, NULL, 'sourced', 'Bank of Russia, weighted average interest rates on deposits of individuals in rubles (up to 1 year, including demand deposits)', 'https://www.cbr.ru/eng/statistics/bank_sector/int_rat/', '2026-08-31', 'August 2026 (file deposits_e.xlsx); deposits over 1 year averaged 11.08%. World Bank FR.INR.DPST 2024: 14.6%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RU', 1, 'credit_card_rate_cap', 0.728, NULL, 'sourced', 'Bank of Russia, average market and maximum values of the full cost of consumer credit (credit institutions, Q4 2026)', 'https://www.cbr.ru/statistics/bank_sector/psk/', '2026-08-14', 'Legal maximum full cost of credit for loans via a payment card up to 100,000 rubles used cashless, for contracts signed in Q4 2026 (file 14082026_ko.xlsx); the market average was 54.6% (April-June 2026). Over 100,000 rubles: average 54.2%, cap 72.3%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RU', 1, 'deposit_insurance_limit', 1400000, NULL, 'sourced', 'Bank of Russia financial literacy portal (fincult.info), how to choose a deposit', 'https://fincult.info/article/kak-vybrat-vklad/', '2026-10-31', 'Up to 1.4 million rubles per depositor per bank, all accounts and deposits at that bank combined, including accrued interest (page read October 2026; the Deposit Insurance Agency site asv.org.ru refused connections). Higher cover applies in special life situations.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RU', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No standard fixed-installment recurring deposit with a published market rate was found; banks offer term deposits that can be topped up, which the Bank of Russia does not report separately.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RU', 1, 'equity_return_base', 0.1, NULL, 'assumption', '1-year deposit 13.27% (Aug 2026), 6% long-run inflation assumption', 'https://www.cbr.ru/eng/statistics/bank_sector/int_rat/', '2026-10-31', 'Base case of about 4 points over planned inflation, kept below today''s after-tax deposit rate plus 4 points because the Russian index has a weak 10-year record and high political risk.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RU', 1, 'equity_return_high', 0.14, NULL, 'assumption', 'OFZ 10-year yield 16.56% (Bank of Russia zero-coupon curve)', 'https://www.cbr.ru/eng/hd_base/zcyc_params/', '2026-10-31', 'High case: a re-rating of Russian shares with high dividends while rates fall.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RU', 1, 'equity_return_low', 0.04, NULL, 'assumption', 'Bank of Russia key rate 14%; weak 5-year MOEX index record', 'https://www.cbr.ru/eng/hd_base/KeyRate/', '2026-10-31', 'Low case: the local market is isolated from foreign investors since 2022 and its price index has gone sideways for years, so a long stretch of returns below inflation is plausible.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RU', 1, 'fdr_1y_rate', 0.1327, NULL, 'sourced', 'Bank of Russia, weighted average interest rates on deposits of individuals in rubles (181 days to 1 year)', 'https://www.cbr.ru/eng/statistics/bank_sector/int_rat/', '2026-08-31', 'Deposits of 181 days to 1 year opened in August 2026 (file deposits_e.xlsx). The Bank of Russia''s average maximum rate of the ten largest deposit-taking banks was 13.06% in mid-October 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RU', 1, 'fdr_3m_rate', 0.1244, NULL, 'sourced', 'Bank of Russia, weighted average interest rates on deposits of individuals in rubles (31 to 90 days)', 'https://www.cbr.ru/eng/statistics/bank_sector/int_rat/', '2026-08-31', 'Deposits of 31 to 90 days opened in August 2026 (file deposits_e.xlsx); 12.39% in July 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RU', 1, 'fixed_income_return_base', 0.09, NULL, 'assumption', '1-year deposit 13.27% and 3-month OFZ 13.28% today; 6% long-run inflation assumption', 'https://www.cbr.ru/eng/statistics/bank_sector/int_rat/', '2026-10-31', 'Base case over the long run: today''s 13% deposit rates should fall as inflation comes down, so we use about 3 points over planned inflation; most savers stay inside the tax-free interest allowance.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RU', 1, 'fixed_income_return_high', 0.12, NULL, 'assumption', '1-year deposit 13.27% (Aug 2026) less 13% tax above the allowance', 'https://www.cbr.ru/eng/statistics/bank_sector/int_rat/', '2026-10-31', 'High case: rates stay near today''s level for many years.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RU', 1, 'fixed_income_return_low', 0.065, NULL, 'assumption', 'Bank of Russia 4% inflation target; demand deposits 5.47% (Aug 2026)', 'https://www.cbr.ru/eng/statistics/bank_sector/int_rat/', '2026-10-31', 'Low case: deposit rates fall towards a 4% inflation target plus a small real return.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RU', 1, 'goal_inflation_education', 0.075, NULL, 'assumption', 'Services inflation 7.97% year on year in September 2026 (Trading Economics, Rosstat data)', 'https://tradingeconomics.com/russia/inflation-cpi', '2026-10-31', 'No separate education CPI was read; paid education is a service, so we use the 6% projection plus 1.5 points.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RU', 1, 'goal_inflation_health', 0.075, NULL, 'assumption', 'Services inflation 7.97% year on year in September 2026 (Trading Economics, Rosstat data)', 'https://tradingeconomics.com/russia/inflation-cpi', '2026-10-31', 'No separate medical CPI was read; services prices are rising faster than the overall CPI, so we plan health costs at 1.5 points over the 6% projection.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RU', 1, 'gold_return_base', 0.085, NULL, 'assumption', 'Bank of Russia official exchange rate; long-run dollar gold trend', 'https://www.cbr.ru/eng/currency_base/daily/', '2026-10-31', 'Long-run dollar gold trend of about 4-5% plus about 4% a year of ruble depreciation (6% planned inflation against about 2% in the US).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RU', 1, 'gold_return_high', 0.13, NULL, 'assumption', 'Bank of Russia official exchange rate', 'https://www.cbr.ru/eng/currency_base/daily/', '2026-10-31', 'High case: strong dollar gold and a sharp ruble devaluation, as in 2014-2015 and 2022-2023.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RU', 1, 'gold_return_low', 0.03, NULL, 'assumption', 'Bank of Russia official exchange rate (80.56 rubles per USD)', 'https://www.cbr.ru/eng/currency_base/daily/', '2026-10-31', 'Low case: flat dollar gold prices with a stable ruble.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RU', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No statutory retirement gratuity per year of service was found; the Labour Code provides severance pay only on dismissal for redundancy or liquidation. Not confirmed from an official text, so not marked absent.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RU', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'Hospital care is free under compulsory medical insurance (OMS); no official figure for the typical cost of a major private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RU', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Voluntary medical insurance (DMS) is mostly bought by employers; no published premium table per 100,000 rubles of cover by age was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RU', 1, 'inflation_cpi', 0.0635, NULL, 'sourced', 'Bank of Russia, key rate, inflation and inflation target table', 'https://www.cbr.ru/hd_base/infl/', '2026-09-30', 'Annual CPI 6.35% in September 2026 (6.33% in August, 5.98% in July). The Bank of Russia estimated about 6.8% in mid-October 2026. World Bank 2025 average 8.7%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RU', 1, 'inflation_projection', 0.06, NULL, 'assumption', 'Bank of Russia 4% target; CPI 6.35% (Sep 2026); World Bank 2025 average 8.7%', 'https://www.cbr.ru/hd_base/infl/', '2026-10-31', 'Inflation has run well above the 4% target for five years (roughly 7-12% a year since 2021), so we plan with 6%, between the target and the recent average.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RU', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life (risk) cover is sold, often with loans, but no regulator or official premium table per 1,000 rubles of cover by age was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RU', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Bank of Russia supervises insurers but no industry-wide life claim settlement ratio was found in its published statistics.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RU', 1, 'life_expectancy', 73.44, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=RU', '2024-12-31', 'Men 68.3, women 78.9 (2024, older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RU', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":20.1,"men":17,"women":23.1},{"age":65,"total":17.1,"men":14.1,"women":19},{"age":70,"total":13.4,"men":11.5,"women":15.2},{"age":80,"total":7.9,"men":7.1,"women":8.7}]}', 'sourced', 'UN WPP 2024 medium variant via populationpyramid.net (mortality, 2026)', 'https://www.populationpyramid.net/mortality/russian-federation/', '2026-01-01', 'Secondary source of UN WPP 2024 for 2026, five-year age groups; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there), so they overstate slightly because women outnumber men at these ages.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RU', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":70,"womenAge":65,"over90Monthly":null,"meansTested":false}', 'sourced', 'Social Fund of Russia, right to the social old-age pension', 'https://sfr.gov.ru/grazhdanam/pensionnoe_obespechenie/socialnaya_pensiya/pravo', '2026-10-31', 'For residents without the right to an insurance pension (under 15 years of record or 30 points): 69 for men and 64 for women in 2026-2027, 70 and 65 from 2028; foreigners need 15 years of residence. No income test.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RU', 1, 'old_age_allowance_monthly', 9424.12, NULL, 'sourced', 'Social Fund of Russia, amount of the social pension', 'https://sfr.gov.ru/grazhdanam/pensionnoe_obespechenie/socialnaya_pensiya/razmer/', '2026-04-01', 'Base social old-age pension from 1 April 2026, indexed every 1 April; higher with the northern district coefficient, and topped up to the regional pensioner subsistence minimum for non-working pensioners.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RU', 1, 'oop_health_share', 0.2839, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=RU', '2023-12-31', 'Latest available year is 2023 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RU', 1, 'policy_rate', 0.14, NULL, 'sourced', 'Bank of Russia, key rate', 'https://www.cbr.ru/eng/hd_base/KeyRate/', '2026-10-30', 'Held at 14% at the 23 October 2026 board meeting (14.25% in June 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RU', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":65,"nomineeUntilAge":null,"inflationLinked":true,"taxFree":null}', 'sourced', 'Social Fund of Russia, old-age insurance pension: conditions, amount and indexation', 'https://sfr.gov.ru/grazhdanam/pensionnoe_obespechenie/indeksacia_strahovth_pensij/', '2026-01-01', 'Compulsory points-based insurance pension (Federal Law 400-FZ): pension = points x 156.76 rubles plus a fixed payment of 9,584.69 rubles (2026), from 65 for men and 60 for women. Indexed 7.6% in January 2026; from 2027 indexed twice a year, once to inflation and once for budget revenue growth.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RU', 1, 'retirement_accumulation_return_base', 0.095, NULL, 'assumption', 'Fixed-income base 9%; equity base 10%', 'https://www.cbr.ru/eng/statistics/bank_sector/int_rat/', '2026-10-31', 'Base case: roughly half shares at 10% and half deposits and OFZ at 9%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RU', 1, 'retirement_accumulation_return_high', 0.125, NULL, 'assumption', 'Fixed-income high 12%; equity high 14%', 'https://www.cbr.ru/eng/hd_base/zcyc_params/', '2026-10-31', 'High case for a growth-leaning balanced mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RU', 1, 'retirement_accumulation_return_low', 0.06, NULL, 'assumption', 'Fixed-income low 6.5%; equity low 4%', 'https://www.cbr.ru/eng/statistics/bank_sector/int_rat/', '2026-10-31', 'Low case for a balanced mix if both rates and shares disappoint.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RU', 1, 'retirement_age_default', 65, NULL, 'sourced', 'Social Fund of Russia, conditions for the old-age insurance pension (Federal Law 350-FZ)', 'https://sfr.gov.ru/grazhdanam/pensionnoe_obespechenie/strahovaya_pensiya_po_starosti/usloviya_naznacheniya/', '2026-10-31', 'Men born in 1963 or later retire at 65 and women born in 1968 or later at 60 (from 2028); 2026 is a transition year (men 64, women 59). Requires 15 years of insurance record and 30 pension points.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RU', 1, 'retirement_age_government', 65, NULL, 'sourced', 'Social Fund of Russia, conditions for the old-age insurance pension (state and municipal employees)', 'https://sfr.gov.ru/grazhdanam/pensionnoe_obespechenie/strahovaya_pensiya_po_starosti/usloviya_naznacheniya/', '2026-10-31', 'Pension age for state civil and municipal servants rises on a separate schedule to 65 for men and 63 for women by 2034.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RU', 1, 'retirement_return_base', 0.085, NULL, 'assumption', '1-year deposit 13.27% (Aug 2026), mostly within the tax-free interest allowance', 'https://www.cbr.ru/eng/statistics/bank_sector/int_rat/', '2026-10-31', 'Base case well below today''s after-tax 1-year deposit rate, since rates are expected to fall with inflation over a long retirement.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RU', 1, 'retirement_return_high', 0.11, NULL, 'assumption', '1-year deposit 13.27%; 5-year OFZ 16.05% (Bank of Russia)', 'https://www.cbr.ru/eng/hd_base/zcyc_params/', '2026-10-31', 'High case: locking in today''s high deposit and OFZ yields for longer.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RU', 1, 'retirement_return_low', 0.06, NULL, 'assumption', 'Bank of Russia 4% inflation target; demand deposits 5.47% (Aug 2026)', 'https://www.cbr.ru/eng/statistics/bank_sector/int_rat/', '2026-10-31', 'Low case: deposit rates fall close to target inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RU', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The retail federal loan bonds for individuals (OFZ-n, 3-year) were suspended in March 2022; in December 2022 the Ministry of Finance announced it would stop issuing them and the last issue was redeemed on 12 February 2025 (ru.wikipedia.org/wiki/ОФЗ-н, citing the Ministry). Individuals now buy exchange-traded OFZ instead.', 1);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RU', 1, 'savings_account_rate', 0.0547, NULL, 'sourced', 'Bank of Russia, weighted average interest rates on deposits of individuals in rubles (demand deposits)', 'https://www.cbr.ru/eng/statistics/bank_sector/int_rat/', '2026-08-31', 'Demand deposits of individuals, August 2026 (file deposits_e.xlsx). Includes current and savings (nakopitelny) accounts; savings accounts alone usually pay more, and banks can change their rate at any time.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RU', 1, 'support_ratio', NULL, '{"points":[{"year":2026,"value":3.53},{"year":2040,"value":3.05},{"year":2065,"value":2.5}]}', 'sourced', 'UN WPP 2024 medium variant via populationpyramid.net (old-age dependency ratio)', 'https://www.populationpyramid.net/russian-federation/2040/', '2026-01-01', '100 / old-age dependency ratio: 28.3 (2026, /russian-federation/2026/), 32.8 (2040) and 40.0 (2065, /russian-federation/2065/). World Bank 2025: 27.3.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RU', 1, 'tax_bank_interest', 0.13, NULL, 'sourced', 'Bank of Russia financial literacy portal (fincult.info), taxes an investor pays', 'https://fincult.info/article/kakie-nalogi-platit-investor/', '2024-12-28', 'Deposit interest up to 1 million rubles times the highest key rate of the year (on the 1st of any month) is tax-free; interest above that is taxed with investment income at 13% up to 2.4 million rubles a year and 15% above (from 2025). Page updated December 2024 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RU', 1, 'tax_sanchayapatra_profit', 0.13, NULL, 'sourced', 'Bank of Russia financial literacy portal (fincult.info), taxes an investor pays', 'https://fincult.info/article/kakie-nalogi-platit-investor/', '2024-12-28', 'Bond coupon income is always subject to personal income tax: 13% on investment income up to 2.4 million rubles a year, 15% above (from 2025). Applies to OFZ, as the retail OFZ-n no longer exist. Page updated December 2024 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RU', 1, 'tbill_91d_rate', 0.1328, NULL, 'sourced', 'Bank of Russia, zero-coupon yield curve of federal loan bonds (0.25 years)', 'https://www.cbr.ru/eng/hd_base/zcyc_params/', '2026-10-30', 'The government finances itself with OFZ bonds rather than treasury bills; this is the 3-month point of the OFZ zero-coupon curve (13.56% at 6 months, 14.06% at 1 year).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RU', 1, 'tbond_10y_rate', 0.1656, NULL, 'sourced', 'Bank of Russia, zero-coupon yield curve of federal loan bonds (10 years)', 'https://www.cbr.ru/eng/hd_base/zcyc_params/', '2026-10-30', 'Zero-coupon OFZ yield for 10 years on 30 October 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RU', 1, 'tbond_5y_rate', 0.1605, NULL, 'sourced', 'Bank of Russia, zero-coupon yield curve of federal loan bonds (5 years)', 'https://www.cbr.ru/eng/hd_base/zcyc_params/', '2026-10-30', 'Zero-coupon OFZ yield for 5 years on 30 October 2026.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('RW', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"RW","iso3":"RWA","nameEn":"Rwanda","nameNative":"Rwanda","region":"sub_saharan_africa","languages":["rw","en","fr","sw"],"currency":{"code":"RWF","symbol":"RF","decimals":0,"compact":"intl","usdRate":{"value":1428.48,"status":"sourced","sourceName":"World Bank WDI, official exchange rate (PA.NUS.FCRF), Rwanda, 2025 average","sourceUrl":"https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=RW","asOf":"2025-12-31","note":"1,428.48 francs per dollar on average in 2025; market quotes in October 2026 were about 1,473-1,476. The BNR''s daily rates could not be read (its rate service needs an API key)."}},"instruments":{"savings_account":{"available":true,"localName":"Konti yo kuzigama","localNameEn":"Savings account","note":"Offered by banks and microfinance institutions; no average rate is published that could be read."},"fdr_3m":{"available":true,"localName":null,"localNameEn":"Term deposit (3 months)","note":"Interest on deposits held under one year is taxed at 15%."},"fdr_1y":{"available":true,"localName":null,"localNameEn":"Term deposit (1 year)","note":"Interest on deposits held for at least one year is exempt from withholding tax.","sourceUrl":"https://taxsummaries.pwc.com/rwanda/corporate/withholding-taxes"},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No standard monthly recurring deposit product with a published rate was found."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate exists; individuals buy Treasury bonds instead."},"tbill_91d":{"available":true,"localName":null,"localNameEn":"Treasury bill (91 days)","note":"Auctioned weekly by the BNR for 28, 91, 182 and 364 days; individuals bid through a bank or broker.","sourceUrl":"https://www.ktpress.rw/2026/06/investors-rush-to-lend-rwanda-govt-money-as-demand-for-treasury-bills-hits-440/"},"tbond_5y":{"available":true,"localName":null,"localNameEn":"Treasury bond (5 years)","note":"5-year bonds are issued from time to time (last found June 2025, maturing 2030); minimum FRW 100,000 for non-competitive bids.","sourceUrl":"https://www.ktpress.rw/2025/06/rwanda-issues-rwf-10-billion-5-year-bond-good-fo-first-time-investors/"},"tbond_10y":{"available":true,"localName":null,"localNameEn":"Treasury bond (10 years)","note":"Issued January 2026 and reopened June 2026; minimum FRW 100,000 for non-competitive bids, listed on the Rwanda Stock Exchange, 5% tax on interest.","sourceUrl":"https://www.bnr.rw/documents/PROSPECTUS_OF_10-YEAR_BOND_ISSUANCE_ON_JANUARY_12th_2026.pdf"},"equity_fund":{"available":true,"localName":null,"localNameEn":"Collective investment scheme (unit trust)","note":"Unit trusts licensed by the Capital Market Authority invest in local shares and bonds."},"gold":{"available":true,"localName":"Zahabu","localNameEn":"Gold","note":"Gold is sold mainly as jewellery; no official bullion or coin scheme was found."}},"institutions":{"centralBank":{"name":"National Bank of Rwanda (Banki Nkuru y''u Rwanda, BNR)","url":"https://www.bnr.rw/"},"insuranceRegulator":{"name":"National Bank of Rwanda (BNR), insurance supervision","url":"https://www.bnr.rw/","note":"The BNR licenses and supervises insurers."},"insuranceComplaints":{"name":"National Bank of Rwanda, e-correspondence service for complaints","url":"https://e-correspondence.bnr.rw/services","note":"Complain to the insurer first; unresolved complaints go to the BNR''s financial consumer protection unit."},"pensionScheme":{"name":"Rwanda Social Security Board (RSSB), pension scheme","url":"https://rssb.rw/schemes/pension-scheme"},"oldAgeAllowance":null,"publicHealthCover":{"name":"Community-Based Health Insurance (Mutuelle de Santé), managed by RSSB","url":"https://rssb.rw/schemes/cbhi-scheme"},"depositInsurance":{"name":"Deposit Guarantee Fund (managed by the National Bank of Rwanda)","url":"https://www.bnr.rw/","note":"Covers the first FRW 1,000,000 per depositor per institution (Regulation No. 93/2025)."},"statistics":{"name":"National Institute of Statistics of Rwanda (NISR)","url":"https://statistics.gov.rw/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RW', 1, 'bank_deposit_avg_rate', 0.1033, NULL, 'sourced', 'World Bank WDI, deposit interest rate (FR.INR.DPST), Rwanda, from IMF International Financial Statistics', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=RW', '2024-12-31', 'Average deposit rate 10.33% in 2024 (9.65% in 2023); older than 2025, because no 2026 figure could be read from the BNR. Rates have probably risen since, as the policy rate went from 6.5% to 8.75%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RW', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'Rwanda has no legal cap on card interest and no published typical card rate was found; the average bank lending rate was about 16% (World Bank, 2024).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RW', 1, 'deposit_insurance_limit', 1000000, NULL, 'sourced', 'KT Press on BNR Regulation No. 93/2025 on the operations of the Deposit Guarantee Fund', 'https://www.ktpress.rw/2025/12/central-bank-moves-to-protect-small-bank-depositors-with-guarantee-fund/', '2025-12-01', 'Deposits are covered for the first FRW 1,000,000 per depositor in each licensed institution under BNR Regulation No. 93/2025; the report says the 2016 system had no fixed ceiling. Secondary source because the BNR text could not be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RW', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No standard monthly recurring deposit rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RW', 1, 'equity_return_base', 0.1, NULL, 'assumption', 'After-tax safe rate about 8.5% (1-year deposits tax-exempt, Treasury bills 8.2-9% less 15%, bonds 11-12% less 5%)', 'https://www.ktpress.rw/2026/06/investors-rush-to-lend-rwanda-govt-money-as-demand-for-treasury-bills-hits-440/', '2026-10-31', 'Base case kept about 1.5 points above the after-tax safe rate, well under the 4-point cap, because the local stock market is thin and its 10-year record is weak.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RW', 1, 'equity_return_high', 0.14, NULL, 'assumption', 'Treasury bond yields of 11-13% (BNR, KT Press)', 'https://www.ktpress.rw/2026/05/government-opens-another-high-yield-treasury-bond-offering-with-12-interest-rate/', '2026-10-31', 'High case: equities beat long government bonds after their 5% tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RW', 1, 'equity_return_low', 0.05, NULL, 'assumption', 'Rwanda Stock Exchange, a small market with few listed shares; BNR bond yields 11-12%', 'https://www.bnr.rw/documents/Reopen_Treasury_Bond_Issuance_FXD3-2025-7YR_-_SUMMARY_MARKET_RESULTS_11_FEBRUARY_2026.pdf', '2026-10-31', 'Low case: a weak decade for the small local market, earning less than safe bonds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RW', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published 1-year term deposit rate for Rwanda was found; the World Bank''s average deposit rate (10.33% in 2024) is not split by term.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RW', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published 3-month term deposit rate for Rwanda was found from the BNR or another official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RW', 1, 'fixed_income_return_base', 0.085, NULL, 'assumption', 'Average deposit rate 10.3% (2024; 1-year deposits tax-exempt); 1-year bills 8.96% less 15% tax', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=RW', '2026-10-31', 'Base case: a mix of tax-exempt 1-year deposits and Treasury bills, kept below the average deposit rate because small depositors earn less.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RW', 1, 'fixed_income_return_high', 0.105, NULL, 'assumption', '10-year Treasury bond coupon 12% less 5% withholding tax (BNR prospectus)', 'https://www.bnr.rw/documents/PROSPECTUS_OF_10-YEAR_BOND_ISSUANCE_ON_JANUARY_12th_2026.pdf', '2026-10-31', 'High case: long Treasury bonds held to maturity, about 11.4% after tax, less an allowance for reinvestment at lower rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RW', 1, 'fixed_income_return_low', 0.07, NULL, 'assumption', 'Treasury bills 8.1-9.0% (June 2026) less 15% withholding tax', 'https://www.ktpress.rw/2026/06/investors-rush-to-lend-rwanda-govt-money-as-demand-for-treasury-bills-hits-440/', '2026-10-31', 'Low case: short Treasury bills or shorter deposits after the 15% tax, about 7%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RW', 1, 'goal_inflation_education', 0.08, NULL, 'assumption', 'NISR CPI September 2026: urban education prices +8.6% a year', 'https://statistics.gov.rw/sites/default/files/documents/2026-10/SEPTEMBER%202026%20CPI%20Report%20English.pdf', '2026-10-31', 'Education prices rose 8.6% in the past year, so school goals are planned 2 points above the 6% inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RW', 1, 'goal_inflation_health', 0.07, NULL, 'assumption', 'NISR CPI September 2026: urban health prices +1.3% a year; inflation assumption 6%', 'https://statistics.gov.rw/sites/default/files/documents/2026-10/SEPTEMBER%202026%20CPI%20Report%20English.pdf', '2026-10-31', 'Health prices are largely set by public insurance tariffs and rose only 1.3% in the past year, so medical goals are planned 1 point above the 6% inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RW', 1, 'gold_return_base', 0.08, NULL, 'assumption', 'World Bank official exchange rate series; long-run dollar gold trend about 4%', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=RW', '2026-10-31', 'Base case: the dollar gold trend of about 4% a year plus franc depreciation of about 4% a year, as in 2025-2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RW', 1, 'gold_return_high', 0.13, NULL, 'assumption', 'World Bank official exchange rate series', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=RW', '2026-10-31', 'High case: strong gold years with faster franc depreciation, as in 2023 when the franc fell about 18%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RW', 1, 'gold_return_low', 0.03, NULL, 'assumption', 'World Bank official exchange rate series (franc about 1,428 per dollar in 2025, after steady depreciation)', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=RW', '2026-10-31', 'Low case: flat dollar gold with slow franc depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RW', 1, 'gratuity_rule', NULL, '{"daysPerYear":7,"daysPerYearAfter":null,"afterYears":null,"daysPerMonth":30}', 'sourced', 'Law No. 66/2018 regulating labour in Rwanda, articles 31-32 (Official Gazette special of 6 September 2018)', 'https://www.minijust.gov.rw/fileadmin/user_upload/Minijust/Publications/Laws/Labour_law_2018.pdf', '2018-09-06', 'A retiring employee gets a lump sum calculated like terminal benefits (art. 32): 2 months'' average salary under 5 years with the employer, then 3, 4, 5 and 6 months for each further 5-year band, and 7 months after 25 years. 7 days a year approximates this for 25-30 year careers (7 months at 30 years); law from 2018, older than 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RW', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a major private hospital stay in Rwanda was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RW', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premiums by age were found from a public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RW', 1, 'inflation_cpi', 0.172, NULL, 'sourced', 'National Institute of Statistics of Rwanda (NISR), Consumer Price Index, September 2026 (urban CPI, the headline index)', 'https://statistics.gov.rw/sites/default/files/documents/2026-10/SEPTEMBER%202026%20CPI%20Report%20English.pdf', '2026-09-30', 'Urban consumer prices up 17.2% year on year in September 2026 (15.7% in August); rural CPI +22.0% and all-Rwanda CPI +20.0%. The 12-month average urban inflation rate was 11.5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RW', 1, 'inflation_projection', 0.06, NULL, 'assumption', 'National Bank of Rwanda medium-term inflation objective of 5% within a 2-8% target range (MPC statement of 27 August 2026, as reported by The New Times)', 'https://www.newtimes.co.rw/article/38480/news/finance/how-875-central-bank-interest-rate-will-influence-household-business-decisions', '2026-10-31', 'Inflation is far above the band in 2026 and the BNR itself expects it to return inside the band only in the second half of 2027, so planning uses 6%, a little above the 5% objective.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RW', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life cover is sold in Rwanda, but no published premium rates per FRW 1,000 of cover by age were found from the BNR or another public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RW', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The BNR, which supervises insurers, publishes no industry-wide life claim settlement ratio that could be found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RW', 1, 'life_expectancy', 68.017, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN), Rwanda', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=RW', '2024-12-31', '68.0 years in 2024 (men 65.7, women 70.1).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RW', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":17.3,"men":16.3,"women":18.3},{"age":65,"total":14.1,"men":13.2,"women":14.8},{"age":70,"total":10.9,"men":10.3,"women":11.5},{"age":80,"total":6.3,"men":6,"women":6.5}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/rwanda/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026; the both-sexes figure at 65 is published, the others are the mean of men and women.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RW', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension with its own age rule was found (see old_age_allowance_monthly).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RW', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension was found: the main cash transfer, VUP direct support, goes to extremely poor households without labour capacity, not to older people as such, and its current amount could not be confirmed from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RW', 1, 'oop_health_share', 0.041, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), Rwanda', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=RW', '2023-12-31', '4.1% in 2023 (WHO Global Health Expenditure Database via the World Bank), low because most people are covered by community-based health insurance; older than 2025, the latest available.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RW', 1, 'policy_rate', 0.0875, NULL, 'sourced', 'National Bank of Rwanda Monetary Policy Committee decision of 27 August 2026, as reported by The New Times', 'https://www.newtimes.co.rw/article/38480/news/finance/how-875-central-bank-interest-rate-will-influence-household-business-decisions', '2026-08-27', 'Central Bank Rate raised by 50 basis points from 8.25% to 8.75% on 27 August 2026; the BNR expects inflation to return to its 2-8% range in the second half of 2027. Secondary source because the BNR site could not be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RW', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":60,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'Rwanda Social Security Board (RSSB), pension scheme FAQ', 'https://rssb.rw/schemes/pension-scheme', '2026-10-31', 'Compulsory RSSB pension for employees (the RSSB page gives 7.5% employee plus 7.5% employer); old-age pension from 60 after the minimum contribution period set by law. The RSSB page says nothing about indexation and no automatic indexation was confirmed, so inflationLinked is false. Ejo Heza is a separate voluntary long-term savings scheme.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RW', 1, 'retirement_accumulation_return_base', 0.09, NULL, 'assumption', 'Safe rate after tax 8.5%, equity base 10%, gold base 8%, bonds 11.4% after tax', 'https://www.ktpress.rw/2026/05/government-opens-another-high-yield-treasury-bond-offering-with-12-interest-rate/', '2026-10-31', 'Base case: a balanced mix of deposits, Treasury bonds, local equity funds and some gold.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RW', 1, 'retirement_accumulation_return_high', 0.115, NULL, 'assumption', 'Equity high 14%; bonds 11.4% after tax', 'https://www.ktpress.rw/2026/05/government-opens-another-high-yield-treasury-bond-offering-with-12-interest-rate/', '2026-10-31', 'High case: a growth-leaning mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RW', 1, 'retirement_accumulation_return_low', 0.07, NULL, 'assumption', 'Safe rate after tax about 7-8.5%; equity low 5%', 'https://www.ktpress.rw/2026/06/investors-rush-to-lend-rwanda-govt-money-as-demand-for-treasury-bills-hits-440/', '2026-10-31', 'Low case: mostly deposits and bills, with weak equity and gold years.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RW', 1, 'retirement_age_default', 60, NULL, 'sourced', 'Rwanda Social Security Board (RSSB), pension scheme FAQ', 'https://rssb.rw/schemes/pension-scheme', '2026-10-31', 'RSSB states 60 as the statutory age for an old-age pension with sufficient contributions (15 years under the 2015 pension law), the same for men and women; no change for younger cohorts was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RW', 1, 'retirement_age_government', 65, NULL, 'sourced', 'The New Times on Law No. 017/2020 establishing the general statute governing public servants (article 85)', 'https://www.newtimes.co.rw/article/179078/News/lawmakers-propose-early-access-to-pension-benefits', '2020-10-07', 'Public servants retire at 65 and may ask for early retirement from 60; secondary source from 2020 (older than 2025), and no later change was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RW', 1, 'retirement_return_base', 0.075, NULL, 'assumption', '1-year Treasury bills 8.96% less 15% tax = about 7.6% (June 2026)', 'https://www.ktpress.rw/2026/06/investors-rush-to-lend-rwanda-govt-money-as-demand-for-treasury-bills-hits-440/', '2026-10-31', 'Base case kept just under the after-tax 1-year bill rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RW', 1, 'retirement_return_high', 0.09, NULL, 'assumption', 'Tax-exempt 1-year deposits (average deposit rate 10.3%, 2024) and long bonds at 12% less 5% tax', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=RW', '2026-10-31', 'High case: tax-exempt 1-year deposits and long Treasury bonds held to maturity.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RW', 1, 'retirement_return_low', 0.065, NULL, 'assumption', 'Treasury bills 8.1-9.0% (June 2026) less 15% tax', 'https://www.ktpress.rw/2026/06/investors-rush-to-lend-rwanda-govt-money-as-demand-for-treasury-bills-hits-440/', '2026-10-31', 'Low case: short bills and deposits after tax, with rates falling back as inflation eases.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RW', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Rwanda has no separate government savings certificate; individuals buy ordinary Treasury bonds through banks or brokers from FRW 100,000 (see tbond_5y and tbond_10y).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RW', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical savings-account rate for Rwanda was found; the BNR interest-rate statistics could not be read (the site loads only through a script).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RW', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":14.65},{"year":2040,"value":14.08},{"year":2065,"value":7.41}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://data.worldbank.org/indicator/SP.POP.DPND.OL?locations=RW', '2025-12-31', 'Working-age people per person 65+ = 100 / old-age dependency ratio. Dependency ratios used: 6.83 per 100 in 2025 (World Bank), 7.1 in 2040 (populationpyramid.net/rwanda/2040/) and 13.5 in 2065 (populationpyramid.net/rwanda/2065/, UN WPP 2024 medium variant).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RW', 1, 'tax_bank_interest', 0.15, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Rwanda, corporate withholding taxes (reviewed 23 September 2026)', 'https://taxsummaries.pwc.com/rwanda/corporate/withholding-taxes', '2026-09-23', '15% final withholding tax on interest; interest on deposits held in a financial institution for at least one year is exempt, and interest on Treasury bonds of 3 years or more and on listed securities is taxed at 5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RW', 1, 'tax_sanchayapatra_profit', 0.05, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Rwanda, corporate withholding taxes (reviewed 23 September 2026)', 'https://taxsummaries.pwc.com/rwanda/corporate/withholding-taxes', '2026-09-23', 'There is no savings certificate; this is the 5% withholding tax on interest from Treasury bonds of at least 3 years, the government security individuals can buy (also stated in the BNR 10-year bond prospectus).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RW', 1, 'tbill_91d_rate', 0.0823, NULL, 'sourced', 'KT Press, citing the National Bank of Rwanda Weekly Bulletin of 8 June 2026 (Treasury bill auction of 4 June 2026)', 'https://www.ktpress.rw/2026/06/investors-rush-to-lend-rwanda-govt-money-as-demand-for-treasury-bills-hits-440/', '2026-06-04', 'Average 91-day bill rate 8.23% (28-day 8.10%, 182-day 8.37%, 364-day 8.96%); secondary source, and no later auction result could be read. The policy rate has risen 50 basis points since, so current yields are probably higher.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RW', 1, 'tbond_10y_rate', 0.12, NULL, 'sourced', 'KT Press on the June 2026 reopening of the 10-year Treasury bond FXD1/2026/10Yrs (maturing 4 January 2036); BNR prospectus of 12 January 2026', 'https://www.ktpress.rw/2026/05/government-opens-another-high-yield-treasury-bond-offering-with-12-interest-rate/', '2026-06-19', 'Coupon 12% a year paid twice yearly, offered again in June 2026 (settlement 19 June 2026); this is the coupon set at the January 2026 book building, not a market yield. For comparison, a 6.42-year bond reopened on 11 February 2026 cleared at a yield of 11.30% (BNR results). Secondary source for the coupon.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('RW', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 5-year bond was auctioned in 2026 that could be found; the nearest, a 6.4-year reopening on 11 February 2026, cleared at 11.30% (coupon 11.50%, BNR results).', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('SA', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"SA","iso3":"SAU","nameEn":"Saudi Arabia","nameNative":"المملكة العربية السعودية","region":"middle_east_north_africa","languages":["ar","en"],"currency":{"code":"SAR","symbol":"ر.س","decimals":2,"compact":"intl","usdRate":{"value":3.75,"status":"sourced","sourceName":"World Bank WDI, official exchange rate (PA.NUS.FCRF), Saudi Arabia","sourceUrl":"https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=SA","asOf":"2025-12-31","note":"The riyal is pegged at 3.75 per US dollar. CLDR gives no narrow symbol (only ''SAR''); the Arabic abbreviation ر.س is used here because the new riyal sign is not yet supported by most fonts."}},"instruments":{"savings_account":{"available":true,"localName":"حساب توفير","localNameEn":"Savings account","note":"Many accounts are Islamic and pay little or no return."},"fdr_3m":{"available":true,"localName":"وديعة لأجل (3 أشهر)","localNameEn":"Time deposit (3 months)","note":"Often offered as Islamic murabaha deposits."},"fdr_1y":{"available":true,"localName":"وديعة لأجل (سنة)","localNameEn":"Time deposit (1 year)","note":"Often offered as Islamic murabaha deposits."},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No standard monthly recurring deposit product was found."},"sanchayapatra_5y":{"available":true,"localName":"صح","localNameEn":"Sah government savings sukuk","note":"A 1-year government savings sukuk with a fixed return set for each monthly issue, from SAR 1,000 up to SAR 200,000 per person, profit paid at maturity; Saudi citizens aged 18 and over only; shorter than 5 years.","sourceUrl":"https://sukuk.ndmc.gov.sa/"},"tbill_91d":{"available":true,"localName":"أذونات الخزينة","localNameEn":"Treasury bills","note":"Issued for banks and primary dealers; individuals reach them through funds."},"tbond_5y":{"available":true,"localName":"صكوك حكومية بالريال","localNameEn":"Government riyal sukuk","note":"Monthly riyal sukuk issues with 5- to 13-year maturities, sold through primary dealers.","sourceUrl":"https://www.ndmc.gov.sa/en/e/news-details/30151/1048534"},"tbond_10y":{"available":true,"localName":"صكوك حكومية بالريال","localNameEn":"Government riyal sukuk","note":"Monthly riyal sukuk issues with 5- to 13-year maturities, sold through primary dealers.","sourceUrl":"https://www.ndmc.gov.sa/en/e/news-details/30151/1048534"},"equity_fund":{"available":true,"localName":"صناديق الاستثمار","localNameEn":"Investment funds","note":"Funds investing in Saudi shares are offered to retail investors under Capital Market Authority rules."},"gold":{"available":true,"localName":"الذهب","localNameEn":"Gold","note":"Gold bars, coins and jewellery are freely sold."}},"institutions":{"centralBank":{"name":"Saudi Central Bank (SAMA)","url":"https://www.sama.gov.sa/"},"insuranceRegulator":{"name":"Insurance Authority","url":"https://www.ia.gov.sa/"},"insuranceComplaints":{"name":"Insurance Authority, complaints portal","url":"https://icare.ia.gov.sa/","note":"Complaints about insurers go to the Insurance Authority (linked from its Help and Support menu)."},"pensionScheme":{"name":"General Organization for Social Insurance (GOSI)","url":"https://www.gosi.gov.sa/"},"oldAgeAllowance":null,"publicHealthCover":{"name":"Ministry of Health (free public care for citizens)","url":"https://www.moh.gov.sa/"},"depositInsurance":{"name":"Deposit Protection Fund, Saudi Central Bank","url":"https://www.sama.gov.sa/"},"statistics":{"name":"General Authority for Statistics (GASTAT)","url":"https://www.stats.gov.sa/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SA', 1, 'bank_deposit_avg_rate', 0.0519, NULL, 'sourced', 'Trading Economics, citing the Saudi Central Bank: 1-year riyal deposit rate, September 2026', 'https://tradingeconomics.com/saudi-arabia/deposit-interest-rate', '2026-09-30', 'SAMA''s 1-year cash deposit rate rose to 5.19% in September 2026 (5.00% in August); it is a money-market rate, so retail time deposits usually pay less. Secondary source; World Bank FR.INR.DPST has no Saudi data.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SA', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap or published average credit card rate could be read; SAMA site unreachable.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SA', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'A deposit protection fund run by SAMA exists, but its cover limit could not be read (SAMA site certificate error and connection refused).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SA', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No industry-wide rate for a monthly recurring deposit product was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SA', 1, 'equity_return_base', 0.075, NULL, 'assumption', 'SAMA 1-year deposit rate 5.19%; repo rate 4.50%', 'https://tradingeconomics.com/saudi-arabia/deposit-interest-rate', '2026-10-31', 'Base case: about 2.5 points above the safe deposit rate, under the 4-point cap, because the main Saudi index has had only a moderate 10-year record.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SA', 1, 'equity_return_high', 0.1, NULL, 'assumption', 'SAMA 1-year deposit rate 5.19%; Gulf equity premium', 'https://tradingeconomics.com/saudi-arabia/deposit-interest-rate', '2026-10-31', 'High case: a fuller equity premium with strong earnings growth.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SA', 1, 'equity_return_low', 0.035, NULL, 'assumption', 'SAMA 1-year deposit rate 5.19% (September 2026)', 'https://tradingeconomics.com/saudi-arabia/deposit-interest-rate', '2026-10-31', 'Low case: oil-driven swings leave the local index returning less than deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SA', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No average retail 1-year time-deposit rate was found; SAMA''s 1-year riyal deposit rate (5.19%) is a money-market rate, used for bank_deposit_avg_rate instead.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SA', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No average retail 3-month time-deposit rate was found; the 3-month interbank rate (SAIBOR, 5.01% in September 2026) is a wholesale rate, and SAMA statistics could not be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SA', 1, 'fixed_income_return_base', 0.04, NULL, 'assumption', 'SAMA 1-year deposit rate 5.19%; repo rate 4.50% (September 2026)', 'https://tradingeconomics.com/saudi-arabia/deposit-interest-rate', '2026-10-31', 'Base case: below the money-market deposit rate because retail deposits pay less and rates may fall over a long plan.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SA', 1, 'fixed_income_return_high', 0.05, NULL, 'assumption', 'SAMA 1-year deposit rate 5.19% (September 2026)', 'https://tradingeconomics.com/saudi-arabia/deposit-interest-rate', '2026-10-31', 'High case: retail savers get close to money-market rates, for example through Sah savings sukuk.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SA', 1, 'fixed_income_return_low', 0.025, NULL, 'assumption', 'SAMA 1-year deposit rate 5.19%; repo rate 4.50% (September 2026)', 'https://tradingeconomics.com/saudi-arabia/deposit-interest-rate', '2026-10-31', 'Low case: retail deposit and Sah returns fall with US rates, untaxed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SA', 1, 'goal_inflation_education', 0.035, NULL, 'assumption', 'Inflation assumption 2%; education CPI index 103.7 (September 2026, Trading Economics citing GASTAT)', 'https://tradingeconomics.com/saudi-arabia/inflation-cpi', '2026-10-31', 'No education inflation rate was read; private school fees tend to rise faster than prices, so 1.5 points above the inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SA', 1, 'goal_inflation_health', 0.035, NULL, 'assumption', 'Inflation assumption 2%; health CPI 0.3% (July 2026, Trading Economics citing GASTAT)', 'https://tradingeconomics.com/saudi-arabia/inflation-cpi', '2026-10-31', 'The health CPI is nearly flat because public care is free, but private treatment costs rise faster, so 1.5 points above the inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SA', 1, 'gold_return_base', 0.04, NULL, 'assumption', 'Dollar peg (3.75 SAR per USD); long-run dollar gold trend', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=SA', '2026-10-31', 'Base case: the long-run dollar gold trend of about 4% a year, with no depreciation gain under the peg.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SA', 1, 'gold_return_high', 0.08, NULL, 'assumption', 'Dollar peg (3.75 SAR per USD); long-run dollar gold trend', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=SA', '2026-10-31', 'High case: strong dollar gold years.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SA', 1, 'gold_return_low', 0, NULL, 'assumption', 'Dollar peg (3.75 SAR per USD); World Bank exchange rate', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=SA', '2026-10-31', 'Low case: flat dollar gold; the peg means no currency boost.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SA', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Labour Law provides an end-of-service award for private-sector workers, but the law text could not be opened (the Bureau of Experts portal refused the connection and the ministry page was not found), so the days per year could not be confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SA', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a major private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SA', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premiums by age were found from a public source; employer cover is compulsory for private-sector staff.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SA', 1, 'inflation_cpi', 0.019, NULL, 'sourced', 'Trading Economics, citing the General Authority for Statistics (GASTAT), CPI September 2026', 'https://tradingeconomics.com/saudi-arabia/inflation-cpi', '2026-09-30', 'Consumer prices up 1.9% year on year in September 2026 (1.8% in August); the GASTAT home page shows the same 1.9% for September 2026 under its main indicators. World Bank 2025 average 2.0%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SA', 1, 'inflation_projection', 0.02, NULL, 'assumption', 'Dollar peg; 2000-2026 average CPI inflation of 2.0% (Trading Economics, citing GASTAT)', 'https://tradingeconomics.com/saudi-arabia/inflation-cpi', '2026-10-31', 'With the riyal pegged to the dollar, inflation has averaged about 2% since 2000 and is 1.9% now, so 2% a year is used for long-range plans.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SA', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life (protection) cover is sold, but no published premium rates per SAR 1,000 of cover by age were found from the regulator or another public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SA', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Insurance Authority publishes no industry-wide life claim settlement ratio that could be found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SA', 1, 'life_expectancy', 78.982, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN), Saudi Arabia', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=SA', '2024-12-31', '79.0 years in 2024 (men 77.3, women 81.3).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SA', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":22.9,"men":21.7,"women":24.1},{"age":65,"total":18.6,"men":17.6,"women":19.9},{"age":70,"total":14.9,"men":13.9,"women":15.9},{"age":80,"total":8.6,"men":8,"women":9.1}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/saudi-arabia/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SA', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'Eligibility rules of the Developed Social Security programme for older people could not be read from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SA', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'Means-tested Developed Social Security support from the Ministry of Human Resources and Social Development covers some older people, but no old-age amount could be read from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SA', 1, 'oop_health_share', 0.1412, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), Saudi Arabia', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=SA', '2023-12-31', '14.1% in 2023 (WHO Global Health Expenditure Database via the World Bank); older than 2025, the latest available.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SA', 1, 'policy_rate', 0.045, NULL, 'sourced', 'Trading Economics, Saudi Central Bank (SAMA) decision of 16 September 2026', 'https://tradingeconomics.com/saudi-arabia/interest-rate', '2026-09-16', 'SAMA raised its repo rate by 25 bps to 4.50% (reverse repo 4.00%); secondary source because the SAMA site could not be read (certificate error).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SA', 1, 'public_pension_scheme', NULL, NULL, 'missing', '', '', '2026-10-31', 'Saudi nationals are covered by compulsory social insurance through GOSI (employee 9.75% and employer 11.75% of basic pay plus housing, capped at SAR 45,000, per PwC), but entry ages and indexation rules could not be read; GOSI pages did not load.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SA', 1, 'retirement_accumulation_return_base', 0.055, NULL, 'assumption', 'SAMA 1-year deposit rate 5.19%; equity base 7.5%; gold base 4%', 'https://tradingeconomics.com/saudi-arabia/deposit-interest-rate', '2026-10-31', 'Base case: a balanced mix of deposits or sukuk, Saudi equities and some gold.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SA', 1, 'retirement_accumulation_return_high', 0.075, NULL, 'assumption', 'Equity high case 10%; SAMA 1-year deposit rate 5.19%', 'https://tradingeconomics.com/saudi-arabia/deposit-interest-rate', '2026-10-31', 'High case: a growth-leaning mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SA', 1, 'retirement_accumulation_return_low', 0.035, NULL, 'assumption', 'SAMA 1-year deposit rate 5.19%; equity low case 3.5%', 'https://tradingeconomics.com/saudi-arabia/deposit-interest-rate', '2026-10-31', 'Low case: a mix earning about deposit rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SA', 1, 'retirement_age_default', 65, NULL, 'sourced', 'Trading Economics, retirement age for men, Saudi Arabia (citing the Ministry of Labour)', 'https://tradingeconomics.com/saudi-arabia/retirement-age-men', '2026-10-31', 'Trading Economics gives 65 for 2026 (unchanged from 2025), citing the Ministry of Labour; the same age applies to women. Secondary source because GOSI pages load only with JavaScript, so the transition rules for people insured before the Social Insurance Law of July 2024 could not be checked; 65 is used for someone born after 1975.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SA', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'The retirement age for civil servants under the unified social insurance law could not be confirmed from an official page (GOSI pages did not load).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SA', 1, 'retirement_return_base', 0.04, NULL, 'assumption', 'SAMA 1-year deposit rate 5.19%; repo rate 4.50%', 'https://tradingeconomics.com/saudi-arabia/deposit-interest-rate', '2026-10-31', 'Base case: below the untaxed 1-year deposit rate, allowing for lower retail rates and future cuts.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SA', 1, 'retirement_return_high', 0.05, NULL, 'assumption', 'SAMA 1-year deposit rate 5.19%', 'https://tradingeconomics.com/saudi-arabia/deposit-interest-rate', '2026-10-31', 'High case: money-market-like returns through Sah sukuk or term deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SA', 1, 'retirement_return_low', 0.025, NULL, 'assumption', 'SAMA 1-year deposit rate 5.19% (September 2026)', 'https://tradingeconomics.com/saudi-arabia/deposit-interest-rate', '2026-10-31', 'Low case: retail deposit rates fall with US rates, untaxed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SA', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Ministry of Finance''s Sah savings sukuk for individuals (1-year, fixed return, from SAR 1,000) sets its return each monthly issue; the portal does not show the current rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SA', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No average savings-account rate was found; many accounts are Islamic current or savings accounts paying little or nothing, and SAMA statistics could not be read (certificate error).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SA', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":24},{"year":2040,"value":13.7},{"year":2065,"value":6.3}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/saudi-arabia/2040/', '2025-12-31', '100 / old-age dependency ratio: 4.17 (2025, World Bank), 7.3 (2040) and 15.8 (2065, populationpyramid.net/saudi-arabia/2065/); a large migrant workforce keeps the ratio high today.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SA', 1, 'tax_bank_interest', 0, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Saudi Arabia, taxes on personal income', 'https://taxsummaries.pwc.com/saudi-arabia/individual/taxes-on-personal-income', '2026-10-31', 'There is no individual income tax scheme in Saudi Arabia, so bank returns of individuals are untaxed (non-employment business income is taxed as an entity).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SA', 1, 'tax_sanchayapatra_profit', 0, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Saudi Arabia, taxes on personal income', 'https://taxsummaries.pwc.com/saudi-arabia/individual/taxes-on-personal-income', '2026-10-31', 'No individual income tax, so returns on the Sah savings sukuk are untaxed for individuals.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SA', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published 3-month treasury bill yield was found; the 3-month interbank rate (SAIBOR) was 5.01% in September 2026 (Trading Economics, citing SAMA).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SA', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 10-year government yield could be read; the National Debt Management Center reports amounts only, and the secondary source did not show a Saudi yield.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SA', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The National Debt Management Center publishes amounts but not yields for its monthly riyal sukuk issues; no 5-year yield was found.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('SB', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"SB","iso3":"SLB","nameEn":"Solomon Islands","nameNative":"Solomon Aelan","region":"east_asia_pacific","languages":["pis","en"],"currency":{"code":"SBD","symbol":"$","decimals":2,"compact":"intl","usdRate":{"value":8.06,"status":"sourced","sourceName":"Central Bank of Solomon Islands, Today''s exchange rates (indicative)","sourceUrl":"https://www.cbsi.com.sb/data-statistics/exchange-rates/todays-exchange-rates","asOf":"2026-10-30","note":"Published as USD 0.1240 per SBD 1 (about 8.06 SBD per USD); the September 2026 monthly average was 8.03 (CBSI Monthly Economic Bulletin)."}},"instruments":{"savings_account":{"available":true,"localName":"Savings account","sourceUrl":"https://www.cbsi.com.sb/sites/default/files/2026-07/Money-and-Banking-Statistics.xlsx"},"fdr_3m":{"available":true,"localName":"Time deposit (1-3 months)","sourceUrl":"https://www.cbsi.com.sb/sites/default/files/2026-07/Money-and-Banking-Statistics.xlsx"},"fdr_1y":{"available":true,"localName":"Time deposit (1-2 years)","sourceUrl":"https://www.cbsi.com.sb/sites/default/files/2026-07/Money-and-Banking-Statistics.xlsx"},"dps":{"available":false,"localName":null,"localNameEn":"Recurring deposit","note":"No bank recurring-deposit product was identified. Informal workers can save monthly through the SINPF youSave scheme.","sourceUrl":"https://www.sinpf.org.sb/members/yousave/"},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":"Government savings bond","note":"No retail government savings bond exists."},"tbill_91d":{"available":true,"localName":"Treasury bills","note":"Issued by tender through CBSI; mostly held by banks and institutions.","sourceUrl":"https://www.cbsi.com.sb/monetary-policy/market-operations/treasury-bills"},"tbond_5y":{"available":false,"localName":null,"localNameEn":"5-year government bond","note":"No 5-year government bond is listed."},"tbond_10y":{"available":true,"localName":"Development Bonds","note":"Government Development Bonds are auctioned through CBSI, mainly to institutions.","sourceUrl":"https://www.cbsi.com.sb/monetary-policy/market-operations/development-bonds"},"equity_fund":{"available":false,"localName":null,"localNameEn":"Equity fund","note":"There is no local stock exchange or retail equity fund; foreign investment is subject to exchange control."},"gold":{"available":false,"localName":null,"localNameEn":"Gold bullion","note":"No retail gold bullion market was identified."}},"institutions":{"centralBank":{"name":"Central Bank of Solomon Islands","url":"https://www.cbsi.com.sb/"},"insuranceRegulator":{"name":"Central Bank of Solomon Islands","url":"https://www.cbsi.com.sb/financial-system","note":"CBSI is the financial-sector supervisor; its site does not describe insurance supervision in detail."},"insuranceComplaints":{"name":"Central Bank of Solomon Islands (contact)","url":"https://www.cbsi.com.sb/about-us/contact-locations/contact-us","note":"No dedicated insurance ombudsman was found."},"pensionScheme":{"name":"Solomon Islands National Provident Fund","url":"https://www.sinpf.org.sb/"},"oldAgeAllowance":null,"publicHealthCover":null,"depositInsurance":null,"statistics":{"name":"Solomon Islands National Statistics Office","url":"https://statistics.gov.sb/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SB', 1, 'bank_deposit_avg_rate', 0.005, NULL, 'sourced', 'Central Bank of Solomon Islands, Key indicators: Interest rates (July 2026)', 'https://www.cbsi.com.sb/data-statistics/key-indicators/interest-rates', '2026-07-31', 'Deposit rate 0.50% and lending rate 8.60%; the Money and Banking Statistics give an all-deposits weighted average of 0.47% for March 2026. World Bank FR.INR.DPST: 0.41% (2023).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SB', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No credit card rate cap or published typical card rate was found; CBSI reports personal loans at 10.1% weighted average (March 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SB', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No deposit insurance scheme was found; CBSI''s regulatory framework page describes depositor protection under the Financial Institutions Act but no insurance scheme.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SB', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No bank recurring-deposit product or published rate was found; CBSI publishes only savings and time-deposit rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SB', 1, 'equity_return_base', 0.05, NULL, 'assumption', 'CBSI: 1-2 year time deposits 1.51% and 182-day T-bill 2.33%, less 10% resident withholding tax on interest', 'https://www.cbsi.com.sb/sites/default/files/2026-07/Money-and-Banking-Statistics.xlsx', '2026-10-31', 'No local stock market, so the base case is a global index in Solomon dollar terms, held to about 3.6 points over the after-tax safe rate of about 1.4%; exchange controls limit access.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SB', 1, 'equity_return_high', 0.08, NULL, 'assumption', 'CBSI: 1-2 year time deposits 1.51% and 182-day T-bill 2.33%, less 10% resident withholding tax on interest', 'https://www.cbsi.com.sb/sites/default/files/2026-07/Money-and-Banking-Statistics.xlsx', '2026-10-31', 'High case for global equities in Solomon dollar terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SB', 1, 'equity_return_low', 0.015, NULL, 'assumption', 'CBSI: 1-2 year time deposits 1.51% and 182-day T-bill 2.33%, less 10% resident withholding tax on interest', 'https://www.cbsi.com.sb/sites/default/files/2026-07/Money-and-Banking-Statistics.xlsx', '2026-10-31', 'No local stock exchange; low case close to the after-tax deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SB', 1, 'fdr_1y_rate', 0.0151, NULL, 'sourced', 'CBSI Money and Banking Statistics, Table 1.7 Interest Rates (commercial banks)', 'https://www.cbsi.com.sb/sites/default/files/2026-07/Money-and-Banking-Statistics.xlsx', '2026-03-31', 'Time deposits 1-2 years weighted average 1.51% (6-12 months 1.53%) in March 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SB', 1, 'fdr_3m_rate', 0.012, NULL, 'sourced', 'CBSI Money and Banking Statistics, Table 1.7 Interest Rates (commercial banks)', 'https://www.cbsi.com.sb/sites/default/files/2026-07/Money-and-Banking-Statistics.xlsx', '2026-03-31', 'Time deposits 1-3 months weighted average 1.20% (3-6 months 1.05%) in March 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SB', 1, 'fixed_income_return_base', 0.0136, NULL, 'assumption', 'CBSI: 1-2 year time deposits 1.51% and 182-day T-bill 2.33%, less 10% resident withholding tax on interest', 'https://www.cbsi.com.sb/sites/default/files/2026-07/Money-and-Banking-Statistics.xlsx', '2026-10-31', 'Base case: 1-2 year time deposits after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SB', 1, 'fixed_income_return_high', 0.021, NULL, 'assumption', 'CBSI: 1-2 year time deposits 1.51% and 182-day T-bill 2.33%, less 10% resident withholding tax on interest', 'https://www.cbsi.com.sb/sites/default/files/2026-10/MEB-September%202026.pdf', '2026-10-31', 'High case: 182-day T-bills after tax, where accessible.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SB', 1, 'fixed_income_return_low', 0.007, NULL, 'assumption', 'CBSI savings deposits 0.79% less 10% withholding tax', 'https://www.cbsi.com.sb/sites/default/files/2026-07/Money-and-Banking-Statistics.xlsx', '2026-10-31', 'Low case: savings deposits only, after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SB', 1, 'goal_inflation_education', 0.045, NULL, 'assumption', 'CBSI desired inflation range 2-5%; no education CPI published', 'https://www.cbsi.com.sb/monetary-policy/current-monetary-policy/monetary-policy-stance', '2026-10-31', 'No education price series was found, so we plan slightly above general inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SB', 1, 'goal_inflation_health', 0.045, NULL, 'assumption', 'CBSI desired inflation range 2-5%; no medical CPI published', 'https://www.cbsi.com.sb/monetary-policy/current-monetary-policy/monetary-policy-stance', '2026-10-31', 'Public care is mostly free but imported medicines and overseas referrals track import prices, so we plan slightly above general inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SB', 1, 'gold_return_base', 0.045, NULL, 'assumption', 'CBSI: SBD 8.03 per USD (September 2026 average), 8.06 in March 2026', 'https://www.cbsi.com.sb/sites/default/files/2026-10/MEB-September%202026.pdf', '2026-10-31', 'Dollar gold trend of about 4% plus slight Solomon dollar depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SB', 1, 'gold_return_high', 0.08, NULL, 'assumption', 'CBSI: SBD 8.03 per USD (September 2026 average), 8.06 in March 2026', 'https://www.cbsi.com.sb/sites/default/files/2026-10/MEB-September%202026.pdf', '2026-10-31', 'High case with strong dollar gold.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SB', 1, 'gold_return_low', 0, NULL, 'assumption', 'CBSI: SBD 8.03 per USD (September 2026 average), 8.06 in March 2026', 'https://www.cbsi.com.sb/sites/default/files/2026-10/MEB-September%202026.pdf', '2026-10-31', 'Low case: flat dollar gold and a stable basket-managed currency.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SB', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Employment/Labour Act text on end-of-service or long-service benefits could not be reached (PacLII returned an error), so the rule is not reported.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SB', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published figure for the cost of a major hospital stay was found; public hospital care is largely government-funded.', 0);
