INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SB', 1, 'inflation_cpi', 0.037, NULL, 'sourced', 'Central Bank of Solomon Islands, Monthly Economic Bulletin September 2026', 'https://www.cbsi.com.sb/sites/default/files/2026-10/MEB-September%202026.pdf', '2026-08-31', 'Headline inflation (year on year, 3-month moving average) 3.7% in August 2026, from 4.3% in July; core 3.3%. Based on SINSO national CPI.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SB', 1, 'inflation_projection', 0.04, NULL, 'assumption', 'CBSI monetary policy stance (August 2026): desired inflation range 2-5%; World Bank CPI 3.4% in 2025', 'https://www.cbsi.com.sb/monetary-policy/current-monetary-policy/monetary-policy-stance', '2026-10-31', 'CBSI aims for inflation within 2-5% and expects about 4.4% in 2027, so we plan with 4%.', 0);
