INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SB', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":17.4,"men":16.5,"women":18.3},{"age":65,"total":13.8,"men":13.1,"women":14.6},{"age":70,"total":10.7,"men":10.2,"women":11.2},{"age":80,"total":5.8,"men":5.5,"women":6}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/solomon-islands/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
