INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SB', 1, 'policy_rate', 0.015, NULL, 'sourced', 'Central Bank of Solomon Islands, Monetary Policy Stance', 'https://www.cbsi.com.sb/monetary-policy/current-monetary-policy/monetary-policy-stance', '2026-08-28', 'The Board kept the policy rate at 1.5% for the next six months at its 28 August 2026 meeting. The 28-day Bokolo Bill rate is 0.40%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SB', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":50,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'Solomon Islands National Provident Fund, Benefits and withdrawals and Contribution rates', 'https://www.sinpf.org.sb/members/benefits-and-withdrawals/', '2026-10-31', 'SINPF is a mandatory provident fund (employee 5%, employer 7.5% of wages), credited 5.5% for 2026; it pays a lump sum, with withdrawal from age 50, not a lifetime pension. youSave is the voluntary scheme for informal workers.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SB', 1, 'retirement_accumulation_return_base', 0.045, NULL, 'assumption', 'SINPF crediting rates 2017-2026: 2.65% to 8.5%, 10-year average 5.6%', 'https://www.sinpf.org.sb/investments/crediting-rate/', '2026-10-31', 'Base case somewhat below the SINPF 10-year average, since few other long-term assets are available.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SB', 1, 'retirement_accumulation_return_high', 0.056, NULL, 'assumption', 'SINPF crediting rates 2017-2026: 2.65% to 8.5%, 10-year average 5.6%', 'https://www.sinpf.org.sb/investments/crediting-rate/', '2026-10-31', 'High case at the SINPF 10-year average.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SB', 1, 'retirement_accumulation_return_low', 0.025, NULL, 'assumption', 'SINPF crediting rates 2017-2026: 2.65% to 8.5%, 10-year average 5.6%', 'https://www.sinpf.org.sb/investments/crediting-rate/', '2026-10-31', 'Low case near the weaker SINPF crediting years.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SB', 1, 'retirement_age_default', 50, NULL, 'sourced', 'Solomon Islands National Provident Fund, Benefits and withdrawals', 'https://www.sinpf.org.sb/members/benefits-and-withdrawals/', '2026-10-31', 'Normal retirement withdrawal from age 50; members who keep working can delay withdrawal.', 0);
