INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SB', 1, 'retirement_return_base', 0.013, NULL, 'assumption', 'CBSI: 1-2 year time deposits 1.51% and 182-day T-bill 2.33%, less 10% resident withholding tax on interest', 'https://www.cbsi.com.sb/sites/default/files/2026-07/Money-and-Banking-Statistics.xlsx', '2026-10-31', 'Base case at the after-tax 1-2 year time deposit rate (1.51% less 10%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SB', 1, 'retirement_return_high', 0.021, NULL, 'assumption', 'CBSI: 1-2 year time deposits 1.51% and 182-day T-bill 2.33%, less 10% resident withholding tax on interest', 'https://www.cbsi.com.sb/sites/default/files/2026-10/MEB-September%202026.pdf', '2026-10-31', 'High case: 182-day T-bills after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SB', 1, 'retirement_return_low', 0.007, NULL, 'assumption', 'CBSI savings deposits 0.79% less 10% withholding tax', 'https://www.cbsi.com.sb/sites/default/files/2026-07/Money-and-Banking-Statistics.xlsx', '2026-10-31', 'Low case: savings deposits only, after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SB', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings bond or certificate for individuals was found; government Development Bonds are sold by auction mainly to institutions.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SB', 1, 'savings_account_rate', 0.0079, NULL, 'sourced', 'CBSI Money and Banking Statistics, Table 1.7 Interest Rates (commercial banks)', 'https://www.cbsi.com.sb/sites/default/files/2026-07/Money-and-Banking-Statistics.xlsx', '2026-03-31', 'Savings deposits weighted average 0.79% (range 0.60-1.39%) in March 2026, the latest clearly dated month in the workbook.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SB', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":16.29},{"year":2040,"value":11.76},{"year":2065,"value":6.9}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/solomon-islands/2040/', '2025-12-31', '100 / old-age dependency ratio: 6.14 (2025, World Bank), 8.5 (2040) and 14.5 (2065, populationpyramid.net/solomon-islands/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SB', 1, 'tax_bank_interest', 0.1, NULL, 'sourced', 'Inland Revenue Division, Withholding tax', 'https://www.ird.gov.sb/withholding-tax/', '2026-10-31', 'Interest paid to residents is subject to 10% withholding tax (15% for non-residents).', 0);
