INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('SC', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"SC","iso3":"SYC","nameEn":"Seychelles","nameNative":"Sesel","region":"sub_saharan_africa","languages":["crs","en","fr"],"currency":{"code":"SCR","symbol":"SR","decimals":2,"compact":"intl","usdRate":{"value":14.6681,"status":"sourced","sourceName":"Central Bank of Seychelles, consolidated average exchange rates of authorised dealers","sourceUrl":"https://www.cbs.sc/marketinfo/CAR.html","asOf":"2026-10-30","note":"Consolidated average USD mid rate SR 14.6681 on 30 October 2026 (buy 14.5286, sell 14.8347); the World Bank 2025 average was 14.73."}},"instruments":{"savings_account":{"available":true,"localName":null,"localNameEn":"Savings account","note":"Banks pay about 1.15-1.60% (October 2026); savings interest carries no withholding tax.","sourceUrl":"https://www.cbs.sc/Downloads/publications/interestrate/Banks''%20Interest%20Rates%20Web_26%20October,%202026%20-%2031%20October,%202026.pdf"},"fdr_3m":{"available":true,"localName":null,"localNameEn":"Fixed-term deposit (3 months)","note":"About 1.10-1.75% in October 2026; 5% withholding tax on interest.","sourceUrl":"https://www.cbs.sc/Downloads/publications/interestrate/Banks''%20Interest%20Rates%20Web_26%20October,%202026%20-%2031%20October,%202026.pdf"},"fdr_1y":{"available":true,"localName":null,"localNameEn":"Fixed-term deposit (12 months)","note":"About 1.25-2.25% in October 2026; 5% withholding tax on interest.","sourceUrl":"https://www.cbs.sc/Downloads/publications/interestrate/Banks''%20Interest%20Rates%20Web_26%20October,%202026%20-%2031%20October,%202026.pdf"},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No monthly recurring deposit product with published rates was found."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No retail government savings certificate; individuals can bid non-competitively for Treasury bills and bonds."},"tbill_91d":{"available":true,"localName":null,"localNameEn":"Treasury bills (91 days)","note":"Auctioned weekly by the CBS for the Government; individuals with a rupee account can apply.","sourceUrl":"https://www.cbs.sc/GovernmentDebt/treasurybills.html"},"tbond_5y":{"available":true,"localName":null,"localNameEn":"Treasury bond (5 years)","note":"Issued a few times a year in multiples of SR 1,000; individuals bid non-competitively.","sourceUrl":"https://www.finance.gov.sc/wp-content/uploads/2026/08/260825-Press-Release-September-2026-T-Bond-Issuance.pdf"},"tbond_10y":{"available":false,"localName":null,"localNameEn":null,"note":"No 10-year Treasury bond was issued in 2026; the longest was 7 years."},"equity_fund":{"available":false,"localName":null,"localNameEn":null,"note":"No locally marketed diversified equity fund for residents was confirmed; investors mainly use foreign funds."},"gold":{"available":true,"localName":null,"localNameEn":"Gold","note":"Gold is sold mainly as jewellery; no official bullion or coin scheme was found."}},"institutions":{"centralBank":{"name":"Central Bank of Seychelles","url":"https://www.cbs.sc/"},"insuranceRegulator":{"name":"Financial Services Authority (FSA)","url":"https://fsaseychelles.sc/regulated-entities/insurance"},"insuranceComplaints":{"name":"Financial Services Authority, complaint handling","url":"https://fsaseychelles.sc/complaint-handling"},"pensionScheme":{"name":"Seychelles Pension Fund","url":"https://pensionfund.sc/pensions-refunds/retirement-pension/"},"oldAgeAllowance":{"name":"Social Security retirement benefit (Agency for Social Protection)","url":"https://www.socialaffairs.gov.sc/","note":"Paid from age 63 since January 2026."},"publicHealthCover":{"name":"Ministry of Health (free public health care)","url":"https://www.health.gov.sc/"},"depositInsurance":null,"statistics":{"name":"National Bureau of Statistics","url":"https://www.nbs.gov.sc/statistics/consumer-price-indices"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SC', 1, 'bank_deposit_avg_rate', 0.0247, NULL, 'sourced', 'World Bank WDI, deposit interest rate (FR.INR.DPST), Seychelles', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=SC', '2025-12-31', '2.47% for 2025 (IMF IFS via World Bank). The 2026 Budget Speech gives average savings and fixed-term rates of 1.39% and 3.0% in December 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SC', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap or published typical credit card rate was found; the CBS weekly sheet shows unsecured personal lending at 14.5-21.75% (October 2026) but no card rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SC', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No deposit insurance scheme or cover limit was found on the Central Bank of Seychelles website (legislation, financial stability and consumer pages).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SC', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The CBS weekly indicative rate sheet lists savings, call and fixed-term deposits only; no monthly recurring deposit product with a published rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SC', 1, 'equity_return_base', 0.055, NULL, 'assumption', 'Global equity in rupee terms; after-tax safe rate about 2%', 'https://www.cbs.sc/Downloads/publications/interestrate/Banks''%20Interest%20Rates%20Web_26%20October,%202026%20-%2031%20October,%202026.pdf', '2026-10-31', 'Seychelles has no local stock index with a usable record, so equity means a global index fund in rupee terms, held about 3.5 points above the roughly 2% after-tax safe rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SC', 1, 'equity_return_high', 0.08, NULL, 'assumption', 'Global equity history in rupee terms', 'https://www.cbs.sc/marketinfo/CAR.html', '2026-10-31', 'High case: strong global equity returns plus some rupee depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SC', 1, 'equity_return_low', 0.03, NULL, 'assumption', 'No usable local equity index; global equity in rupee terms', 'https://www.cbs.sc/Downloads/publications/interestrate/Banks''%20Interest%20Rates%20Web_26%20October,%202026%20-%2031%20October,%202026.pdf', '2026-10-31', 'Low case: weak global equity decade with a stable rupee.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SC', 1, 'fdr_1y_rate', 0.02, NULL, 'sourced', 'Central Bank of Seychelles, indicative rates on deposits and lending, week of 26-31 October 2026', 'https://www.cbs.sc/Downloads/publications/interestrate/Banks''%20Interest%20Rates%20Web_26%20October,%202026%20-%2031%20October,%202026.pdf', '2026-10-26', '12-month fixed-term rates ranged 1.25-2.25% across seven institutions; median 2.00%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SC', 1, 'fdr_3m_rate', 0.015, NULL, 'sourced', 'Central Bank of Seychelles, indicative rates on deposits and lending, week of 26-31 October 2026', 'https://www.cbs.sc/Downloads/publications/interestrate/Banks''%20Interest%20Rates%20Web_26%20October,%202026%20-%2031%20October,%202026.pdf', '2026-10-26', '3-month fixed-term rates ranged 1.10-1.75% across seven institutions; median 1.50%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SC', 1, 'fixed_income_return_base', 0.019, NULL, 'assumption', 'CBS: 1-year deposits about 2.0% (Oct 2026, 5% withholding), 365-day bill 2.50% (30 Oct 2026, 15% withholding), 5-year bond 3.8% (Sep 2026)', 'https://www.cbs.sc/Downloads/publications/interestrate/Banks''%20Interest%20Rates%20Web_26%20October,%202026%20-%2031%20October,%202026.pdf', '2026-10-31', 'Base case: 1-year fixed deposits at about 2.0% after the 5% withholding tax, close to the 365-day bill after its 15% withholding.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SC', 1, 'fixed_income_return_high', 0.03, NULL, 'assumption', 'CBS: 1-year deposits about 2.0% (Oct 2026, 5% withholding), 365-day bill 2.50% (30 Oct 2026, 15% withholding), 5-year bond 3.8% (Sep 2026)', 'https://www.finance.gov.sc/wp-content/uploads/2026/08/260825-Press-Release-September-2026-T-Bond-Issuance.pdf', '2026-10-31', 'High case: 5- to 7-year Treasury bonds at 3.8-4.8% coupons.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SC', 1, 'fixed_income_return_low', 0.013, NULL, 'assumption', 'CBS: 1-year deposits about 2.0% (Oct 2026, 5% withholding), 365-day bill 2.50% (30 Oct 2026, 15% withholding), 5-year bond 3.8% (Sep 2026)', 'https://www.cbs.sc/Downloads/publications/interestrate/Banks''%20Interest%20Rates%20Web_26%20October,%202026%20-%2031%20October,%202026.pdf', '2026-10-31', 'Low case: mostly savings accounts (about 1.4%, untaxed) and short deposits, allowing for rates to drift lower.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SC', 1, 'goal_inflation_education', 0.035, NULL, 'assumption', 'NBS education CPI up 2.49% year on year in September 2026 (via Trading Economics)', 'https://tradingeconomics.com/seychelles/inflation-cpi/news/590098', '2026-10-31', 'Education prices rose about twice as fast as the CPI in 2026, so education is planned 1 point above general inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SC', 1, 'goal_inflation_health', 0.04, NULL, 'assumption', 'Inflation assumption 2.5%; NBS health CPI (health prices fell 3.2% year on year in July 2026, via Trading Economics)', 'https://tradingeconomics.com/seychelles/inflation-cpi/news/590098', '2026-10-31', 'Public care is free, but private and imported medical costs are planned 1.5 points above general inflation as the recent health CPI is too volatile to use.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SC', 1, 'gold_return_base', 0.055, NULL, 'assumption', 'Gold trend in dollars; rupee about 14.7 per US dollar in October 2026 (CBS)', 'https://www.cbs.sc/marketinfo/CAR.html', '2026-10-31', 'Base case: a long-run dollar gold trend of about 4.5% plus about 1% a year of rupee depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SC', 1, 'gold_return_high', 0.09, NULL, 'assumption', 'Gold trend in dollars; rupee about 14.7 per US dollar in October 2026 (CBS)', 'https://www.cbs.sc/marketinfo/CAR.html', '2026-10-31', 'High case: strong gold years and faster rupee depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SC', 1, 'gold_return_low', 0.005, NULL, 'assumption', 'Gold trend in dollars; rupee about 14.7 per US dollar in October 2026 (CBS)', 'https://www.cbs.sc/marketinfo/CAR.html', '2026-10-31', 'Low case: flat dollar gold prices and a stable rupee.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SC', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'The 2026 Budget Speech covers public-sector service gratuities only; the private-sector rule in the Employment Act (compensation for length of service) could not be read from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SC', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'Public hospital care is free at the point of use; no official figure for the cost of a private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SC', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No regulator or official source publishing private health insurance premiums by age was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SC', 1, 'inflation_cpi', 0.0122, NULL, 'sourced', 'Central Bank of Seychelles, inflation (NBS CPI), September 2026', 'https://www.cbs.sc/marketinfo/Inflation.html', '2026-09-30', 'Year-on-year CPI inflation 1.22% in September 2026 (0.93% in August); the 12-month average was 0.36%. Figures are the National Bureau of Statistics CPI as republished by the CBS.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SC', 1, 'inflation_projection', 0.025, NULL, 'assumption', 'CBS inflation series: 12-month average 9.8% (2021), 2.6% (2022), -1.0% (2023), 0.3% (2024), 0.3% (2025)', 'https://www.cbs.sc/marketinfo/Inflation.html', '2026-10-31', 'No published numeric inflation target was found, so we plan with 2.5%, close to the 2021-2025 average of about 2.4%, as the CBS expects inflation to rise from its current low level with higher fuel and food prices.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SC', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No regulator or official source publishing indicative term-life premiums per SR 1,000 of cover was found; only company quotes exist.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SC', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Financial Services Authority publishes insurance statistics but no industry-wide life claim settlement ratio was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SC', 1, 'life_expectancy', 76.3, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN), Seychelles', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=SC', '2024-12-31', '76.3 years in 2024 (men 72.1, women 80.7). UN WPP 2024 projects a lower 73.3 years for 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SC', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":19.3,"men":17.2,"women":21.3},{"age":65,"total":15.6,"men":13.9,"women":17.3},{"age":70,"total":12.3,"men":11,"women":13.6},{"age":80,"total":6.9,"men":6.3,"women":7.5}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/seychelles/', '2026-07-01', 'Secondary source of UN WPP 2024 (medium variant) for 2026; totals are the mean of men and women except at 65, where the page gives 15.6.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SC', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":63,"womenAge":63,"over90Monthly":null,"meansTested":false}', 'sourced', 'Ministry of Finance, Budget Speech 2026 (age of eligibility for Social Security retirement benefit)', 'https://www.finance.gov.sc/wp-content/uploads/2026/02/2026-Budget-Speech-English-Version.pdf', '2026-01-01', 'The age of eligibility was lowered from 65 to 63 on 1 January 2026; the benefit is paid to all eligible residents at three levels depending on their SPF pension (Budget Speech 2025), not by a means test.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SC', 1, 'old_age_allowance_monthly', 6950, NULL, 'sourced', 'Ministry of Finance, Budget Speech 2025 (benefit levels from April 2025) and Budget Speech 2026 (SR 800 increase from 1 January 2026)', 'https://www.finance.gov.sc/wp-content/uploads/2026/02/2026-Budget-Speech-English-Version.pdf', '2026-01-01', 'Social Security retirement benefit (Agency for Social Protection) for someone who also gets an SPF pension above SR 3,250: SR 6,150 from April 2025 (2025 Budget Speech, https://www.finance.gov.sc/wp-content/uploads/2025/08/2025-Budget-Speech.pdf) plus the SR 800 rise from 1 January 2026 (2026 Budget Speech) gives SR 6,950. With an SPF pension below SR 3,250 it is SR 7,200, and with no SPF pension SR 7,450; the Government aims for SR 10,000 by 2029.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SC', 1, 'oop_health_share', 0.2796, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), Seychelles', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=SC', '2023-12-31', '28.0% in 2023 (WHO Global Health Expenditure Database), the latest available; older than 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SC', 1, 'policy_rate', 0.0175, NULL, 'sourced', 'Central Bank of Seychelles, press release 30 September 2026 (monetary policy rate for Q4 2026)', 'https://www.cbs.sc/Downloads/Pressrelease/To%20Lentere%20Polisi%20Moneter%20i%20reste%201.75%20poursan%20pour%20katriyenm%20kar%202026.pdf', '2026-09-24', 'The Board kept the monetary policy rate at 1.75% for the fourth quarter of 2026 at its 24 September 2026 meeting (release in Seychellois Creole); standing deposit facility 0.25%, standing credit facility 3.25%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SC', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":65,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":true}', 'sourced', 'Seychelles Pension Fund, Age pension and FAQ', 'https://pensionfund.sc/pensions-refunds/retirement-pension/', '2025-01-01', 'Mandatory for employees (5% employee plus 5% employer contribution, per the SPF FAQ); pension = average adjusted wage x accrual rate (1.21% in 2026) x years of contribution, payable from 65 after 20 years of contributions or the last 10 years continuously; withdrawals carry no tax or fees (SPF FAQ). No automatic indexation of pensions in payment is stated.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SC', 1, 'retirement_accumulation_return_base', 0.04, NULL, 'assumption', 'Safe rate about 2%; equity base 5.5%; gold base 5.5%', 'https://www.cbs.sc/Downloads/publications/interestrate/Banks''%20Interest%20Rates%20Web_26%20October,%202026%20-%2031%20October,%202026.pdf', '2026-10-31', 'Base case: a balanced mix of bonds, deposits and global equity funds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SC', 1, 'retirement_accumulation_return_high', 0.055, NULL, 'assumption', 'Safe rate about 2%; equity base 5.5%; gold base 5.5%', 'https://www.cbs.sc/Downloads/publications/interestrate/Banks''%20Interest%20Rates%20Web_26%20October,%202026%20-%2031%20October,%202026.pdf', '2026-10-31', 'High case: a growth-leaning mix with global equity funds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SC', 1, 'retirement_accumulation_return_low', 0.025, NULL, 'assumption', 'Safe rate about 2%; equity base 5.5%; gold base 5.5%', 'https://www.cbs.sc/Downloads/publications/interestrate/Banks''%20Interest%20Rates%20Web_26%20October,%202026%20-%2031%20October,%202026.pdf', '2026-10-31', 'Low case: mostly deposits and Treasury bonds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SC', 1, 'retirement_age_default', 65, NULL, 'sourced', 'Seychelles Pension Fund, Age pension (effective 1 January 2025)', 'https://pensionfund.sc/pensions-refunds/retirement-pension/', '2025-01-01', 'The SPF age pension is payable from 65, with a reduced early pension from 60 if the member stops working. The non-contributory Social Security retirement benefit starts at 63 from 1 January 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SC', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'No official statement of the public service retirement age was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SC', 1, 'retirement_return_base', 0.019, NULL, 'assumption', 'CBS: 1-year deposits about 2.0% (Oct 2026, 5% withholding), 365-day bill 2.50% (30 Oct 2026, 15% withholding), 5-year bond 3.8% (Sep 2026)', 'https://www.cbs.sc/Downloads/publications/interestrate/Banks''%20Interest%20Rates%20Web_26%20October,%202026%20-%2031%20October,%202026.pdf', '2026-10-31', 'Base case: kept at the after-tax 1-year deposit rate of about 1.9%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SC', 1, 'retirement_return_high', 0.03, NULL, 'assumption', 'CBS: 1-year deposits about 2.0% (Oct 2026, 5% withholding), 365-day bill 2.50% (30 Oct 2026, 15% withholding), 5-year bond 3.8% (Sep 2026)', 'https://www.finance.gov.sc/wp-content/uploads/2026/08/260825-Press-Release-September-2026-T-Bond-Issuance.pdf', '2026-10-31', 'High case: a ladder of 5- to 7-year Treasury bonds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SC', 1, 'retirement_return_low', 0.013, NULL, 'assumption', 'CBS: 1-year deposits about 2.0% (Oct 2026, 5% withholding), 365-day bill 2.50% (30 Oct 2026, 15% withholding), 5-year bond 3.8% (Sep 2026)', 'https://www.cbs.sc/Downloads/publications/interestrate/Banks''%20Interest%20Rates%20Web_26%20October,%202026%20-%2031%20October,%202026.pdf', '2026-10-31', 'Low case: savings accounts and short deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SC', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No retail government savings certificate was found; individuals can buy Treasury bills and bonds through the non-competitive part of CBS auctions instead.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SC', 1, 'savings_account_rate', 0.014, NULL, 'sourced', 'Central Bank of Seychelles, indicative rates on deposits and lending, week of 26-31 October 2026', 'https://www.cbs.sc/Downloads/publications/interestrate/Banks''%20Interest%20Rates%20Web_26%20October,%202026%20-%2031%20October,%202026.pdf', '2026-10-26', 'Savings rates of the eight listed banks and deposit-taking institutions ranged 1.15-1.60%; median 1.40%. The 2026 Budget Speech gave an average savings rate of 1.39% in December 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SC', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":8.2},{"year":2040,"value":4.8},{"year":2065,"value":2.3}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://data.worldbank.org/indicator/SP.POP.DPND.OL?locations=SC', '2025-12-31', 'Working-age people per person 65+, computed as 100 / old-age dependency ratio: 12.2 in 2025 (World Bank) gives 8.2; 21.0 in 2040 and 44.3 in 2065 (populationpyramid.net/seychelles/2040/ and /2065/) give 4.8 and 2.3.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SC', 1, 'tax_bank_interest', 0.05, NULL, 'sourced', 'Seychelles Revenue Commission, Seychelles tax system: withholding tax rates', 'https://src.gov.sc/seychelles-tax-system/', '2026-10-31', 'Withholding tax is 5% on interest on current, fixed and call deposits of residents and 0% on savings account interest; withholding tax is a final tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SC', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No retail government savings certificate exists. For reference, the SRC withholding table taxes Treasury bill interest at 15% for recipients other than financial institutions and insurers; the treatment of Treasury bond coupons was not stated.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SC', 1, 'tbill_91d_rate', 0.023, NULL, 'sourced', 'Central Bank of Seychelles, Treasury bill rates, 30 October 2026', 'https://www.cbs.sc/marketinfo/TBILL.html', '2026-10-30', '91-day bill 2.30%, 182-day 2.48% and 365-day 2.50% as published by the CBS for 30 October 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SC', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 10-year Treasury bond was issued in 2026; the longest 2026 issue found was a 7-year bond at a 4.8% fixed coupon (Ministry of Finance, March 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SC', 1, 'tbond_5y_rate', 0.038, NULL, 'sourced', 'Ministry of Finance, press release: issuance of a 5-year Treasury bond, September 2026', 'https://www.finance.gov.sc/wp-content/uploads/2026/08/260825-Press-Release-September-2026-T-Bond-Issuance.pdf', '2026-09-07', 'Fixed coupon of 3.8% on the 5-year bond auctioned on 7 September 2026 (the June 2026 5-year bond also paid 3.8%); the auction yield was not published.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('SD', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"SD","iso3":"SDN","nameEn":"Sudan","nameNative":"السودان","region":"sub_saharan_africa","languages":["ar","en","bej","fvr"],"currency":{"code":"SDG","symbol":"SDG","decimals":2,"compact":"intl","usdRate":{"value":3743.23,"status":"sourced","sourceName":"Central Bank of Sudan, Economic and Financial Statistics Review Jan-Jun 2026 (weighted average US dollar buying rate at banks and exchange bureaus)","sourceUrl":"https://cbos.gov.sd/sites/default/files/Econ_stat_rview_%28Jan.-Jun.%292026.pdf","asOf":"2026-06-30","note":"SDG 3,743.23 per US dollar at the end of June 2026 (3,222.8 in March 2026, 2,230.74 in June 2025); commercial bank buying rates ranged 2,250-4,481 and bureau rates 3,330-4,985. Trading Economics still shows an old official rate of about 601, which is not the market rate."}},"instruments":{"savings_account":{"available":true,"localName":"حساب ادخار","localNameEn":"Savings account","note":"Banks in Sudan work on Islamic principles: deposits earn a share of profits rather than fixed interest; no average return is published.","sourceUrl":"https://cbos.gov.sd/sites/default/files/Econ_stat_rview_%28Jan.-Jun.%292026.pdf"},"fdr_3m":{"available":true,"localName":"وديعة استثمارية","localNameEn":"Investment deposit","note":"Islamic term (investment) deposits share bank profits; no published return."},"fdr_1y":{"available":true,"localName":"وديعة استثمارية","localNameEn":"Investment deposit, 12 months","note":"Islamic term (investment) deposits share bank profits; no published return."},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No monthly recurring deposit scheme was found."},"sanchayapatra_5y":{"available":false,"localName":"شهادات مشاركة الحكومة (شهامة)","localNameEn":"Government Musharaka Certificates (Shahama)","note":"Sold to the public in the past, but no current issue or return could be confirmed since the 2023 war."},"tbill_91d":{"available":false,"localName":null,"localNameEn":null,"note":"No interest-bearing treasury bills (Islamic finance)."},"tbond_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No 5-year government bond or sukuk available to individuals was found."},"tbond_10y":{"available":false,"localName":null,"localNameEn":null,"note":"No 10-year government bond or sukuk available to individuals was found."},"equity_fund":{"available":false,"localName":null,"localNameEn":null,"note":"The Khartoum Stock Exchange has been disrupted by the war and no retail investment fund open to savers was found."},"gold":{"available":true,"localName":"ذهب","localNameEn":"Gold","note":"Sudan is a large gold producer and gold is widely bought as jewellery and bars."}},"institutions":{"centralBank":{"name":"Central Bank of Sudan","url":"https://cbos.gov.sd/en"},"insuranceRegulator":null,"insuranceComplaints":null,"pensionScheme":null,"oldAgeAllowance":null,"publicHealthCover":null,"depositInsurance":{"name":"Deposit Guarantee Fund (Central Bank of Sudan)","url":"https://cbos.gov.sd/en/content/deposit-guarantee-fund-act"},"statistics":null},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SD', 1, 'bank_deposit_avg_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Neither the Central Bank of Sudan nor the World Bank (FR.INR.DPST has no Sudan value) publishes an average deposit return.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SD', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No credit card rate cap or typical rate was found; Islamic banking uses profit margins (murabaha average 30.7% in June 2026) rather than interest.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SD', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'A Deposit Guarantee Fund exists under its own Act (Central Bank of Sudan page), but the cover limit per depositor could not be found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SD', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No monthly recurring deposit scheme or published return was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SD', 1, 'equity_return_base', 0.12, NULL, 'assumption', 'Central Bank of Sudan Economic and Financial Statistics Review Jan-Jun 2026 (murabaha margins, exchange rates)', 'https://cbos.gov.sd/sites/default/files/Econ_stat_rview_%28Jan.-Jun.%292026.pdf', '2026-10-31', 'The Khartoum Stock Exchange has a weak, war-disrupted record and no current index was found, so the base case is a global index in pound terms capped at 4 points above the assumed 8% safe return, far below what a global index would earn if the pound keeps falling.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SD', 1, 'equity_return_high', 0.3, NULL, 'assumption', 'Central Bank of Sudan Economic and Financial Statistics Review Jan-Jun 2026 (dollar rate up from SDG 2,231 to 3,743 in the year to June 2026)', 'https://cbos.gov.sd/sites/default/files/Econ_stat_rview_%28Jan.-Jun.%292026.pdf', '2026-10-31', 'High case: a global index (about 7% a year in dollars) plus pound depreciation of 20-25% a year.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SD', 1, 'equity_return_low', 0.03, NULL, 'assumption', 'IMF World Economic Outlook, Sudan inflation; Central Bank of Sudan Economic and Financial Statistics Review', 'https://www.imf.org/external/datamapper/api/v1/PCPIPCH/SSD/SDN', '2026-10-31', 'Low case: the Khartoum market stays disrupted by the war and a global fund bought abroad meets a steadier pound.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SD', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Banks in Sudan work on Islamic principles: deposits earn a share of profits rather than fixed interest; no published average return on 1-year investment deposits was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SD', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Banks in Sudan work on Islamic principles: deposits earn a share of profits rather than fixed interest; no published average return on 3-month investment deposits was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SD', 1, 'fixed_income_return_base', 0.08, NULL, 'assumption', 'Central Bank of Sudan Economic and Financial Statistics Review Jan-Jun 2026, table 22 (murabaha margins about 30%)', 'https://cbos.gov.sd/sites/default/files/Econ_stat_rview_%28Jan.-Jun.%292026.pdf', '2026-10-31', 'No published deposit return was found; investment deposits share bank profits, which are earned at murabaha margins near 30%, but depositors get far less, so 8% is a cautious planning figure.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SD', 1, 'fixed_income_return_high', 0.15, NULL, 'assumption', 'Central Bank of Sudan Economic and Financial Statistics Review Jan-Jun 2026, table 22', 'https://cbos.gov.sd/sites/default/files/Econ_stat_rview_%28Jan.-Jun.%292026.pdf', '2026-10-31', 'High case: longer investment deposits receiving a larger share of bank profits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SD', 1, 'fixed_income_return_low', 0.02, NULL, 'assumption', 'Central Bank of Sudan Economic and Financial Statistics Review Jan-Jun 2026', 'https://cbos.gov.sd/sites/default/files/Econ_stat_rview_%28Jan.-Jun.%292026.pdf', '2026-10-31', 'Low case: current and savings accounts that share little or no profit.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SD', 1, 'goal_inflation_education', 0.25, NULL, 'assumption', 'Central Bank of Sudan CPI table (Central Bureau of Statistics); IMF inflation projections', 'https://cbos.gov.sd/sites/default/files/Econ_stat_rview_%28Jan.-Jun.%292026.pdf', '2026-10-31', 'No education price index was found, so education costs are assumed to rise with the 25% inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SD', 1, 'goal_inflation_health', 0.28, NULL, 'assumption', 'Central Bank of Sudan CPI table (Central Bureau of Statistics); IMF inflation projections', 'https://cbos.gov.sd/sites/default/files/Econ_stat_rview_%28Jan.-Jun.%292026.pdf', '2026-10-31', 'No medical price index was found; medicines are largely imported and priced off the dollar and the war has damaged hospitals, so 3 points above the 25% inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SD', 1, 'gold_return_base', 0.28, NULL, 'assumption', 'Central Bank of Sudan Economic and Financial Statistics Review Jan-Jun 2026, table 11; IMF inflation projections', 'https://cbos.gov.sd/sites/default/files/Econ_stat_rview_%28Jan.-Jun.%292026.pdf', '2026-10-31', 'Base case: the long-run dollar gold trend of about 4% a year plus pound depreciation of about 23% a year, close to the gap between the 25% inflation assumption and dollar inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SD', 1, 'gold_return_high', 0.45, NULL, 'assumption', 'Central Bank of Sudan Economic and Financial Statistics Review Jan-Jun 2026, table 11', 'https://cbos.gov.sd/sites/default/files/Econ_stat_rview_%28Jan.-Jun.%292026.pdf', '2026-10-31', 'High case: strong gold years and a pound that keeps falling as fast as in the year to June 2026 (about 68% more pounds per dollar).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SD', 1, 'gold_return_low', 0.08, NULL, 'assumption', 'Central Bank of Sudan Economic and Financial Statistics Review Jan-Jun 2026, table 11 exchange rates', 'https://cbos.gov.sd/sites/default/files/Econ_stat_rview_%28Jan.-Jun.%292026.pdf', '2026-10-31', 'Low case: flat dollar gold and a much slower fall in the pound.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SD', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'The end-of-service benefit rules of the Labour Act could not be read from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SD', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a major private hospital stay was found from an official or international source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SD', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premium rates were found; the National Health Insurance Fund covers members by contribution.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SD', 1, 'inflation_cpi', 0.261, NULL, 'sourced', 'Central Bureau of Statistics CPI, August 2026, via Trading Economics', 'https://tradingeconomics.com/sudan/inflation-cpi', '2026-08-31', 'Secondary source (Trading Economics, citing the Central Bureau of Statistics): annual inflation 26.1% in August 2026, down from 41.6% in July; the Central Bank of Sudan Economic and Financial Statistics Review Jan-Jun 2026 gives 51.3% for June 2026 (40.2% in March, 70.4% in December 2025). The Central Bureau of Statistics site could not be reached.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SD', 1, 'inflation_projection', 0.25, NULL, 'assumption', 'IMF World Economic Outlook, Sudan inflation (41.3% projected for 2026, 50.9% for 2027, about 12% from 2029); Central Bank of Sudan CPI table', 'https://www.imf.org/external/datamapper/api/v1/PCPIPCH/SSD/SDN', '2026-10-31', 'There is no inflation target and inflation has been above 40% in most years since 2018, so plans use 25%, below recent rates but well above the IMF''s hoped-for 12%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SD', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published term life or family takaful premium rates were found from a regulator or other public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SD', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No industry-wide life (takaful) claim settlement ratio from the insurance supervisor was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SD', 1, 'life_expectancy', 66.521, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN), Sudan', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=SD', '2024-12-31', '66.5 years in 2024 (men 63.4, women 69.8); UN WPP 2024 via populationpyramid.net gives 66.9 for 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SD', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":18.1,"men":17,"women":19.2},{"age":65,"total":14.4,"men":13.6,"women":15.4},{"age":70,"total":11.3,"men":10.6,"women":12},{"age":80,"total":6.2,"men":5.8,"women":6.6}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/sudan/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SD', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'No national non-contributory old-age (social) pension was found; not confirmed absent.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SD', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'No national non-contributory old-age (social) pension was found; not confirmed absent.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SD', 1, 'oop_health_share', 0.5737, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), Sudan', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=SD', '2023-12-31', '57.4% in 2023 (WHO Global Health Expenditure Database); older than 2025, the latest available.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SD', 1, 'policy_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Sudan has no interest-based central bank policy rate: banking follows Islamic principles and the central bank steers lending through murabaha profit margins (weighted average 30.7% in June 2026, Economic and Financial Statistics Review table 22; Trading Economics notes there is no official policy rate).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SD', 1, 'public_pension_scheme', NULL, NULL, 'missing', '', '', '2026-10-31', 'Private-sector workers are covered by the National Fund for Social Insurance and civil servants by the National Pension Fund, but entry and pension ages and indexation could not be confirmed from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SD', 1, 'retirement_accumulation_return_base', 0.14, NULL, 'assumption', 'Central Bank of Sudan Economic and Financial Statistics Review; gold base 28%; equity base 12%', 'https://cbos.gov.sd/sites/default/files/Econ_stat_rview_%28Jan.-Jun.%292026.pdf', '2026-10-31', 'Base case: a mix of investment deposits, gold and a global fund; gold has kept its value far better than pound deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SD', 1, 'retirement_accumulation_return_high', 0.25, NULL, 'assumption', 'Central Bank of Sudan Economic and Financial Statistics Review; gold high 45%', 'https://cbos.gov.sd/sites/default/files/Econ_stat_rview_%28Jan.-Jun.%292026.pdf', '2026-10-31', 'High case: a larger share in gold and foreign assets while the pound keeps falling.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SD', 1, 'retirement_accumulation_return_low', 0.05, NULL, 'assumption', 'Central Bank of Sudan Economic and Financial Statistics Review Jan-Jun 2026', 'https://cbos.gov.sd/sites/default/files/Econ_stat_rview_%28Jan.-Jun.%292026.pdf', '2026-10-31', 'Low case: mostly pound deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SD', 1, 'retirement_age_default', NULL, NULL, 'missing', '', '', '2026-10-31', 'The pension age under the National Fund for Social Insurance (private sector) could not be confirmed from an official source; its site and the Social Insurance Act could not be loaded.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SD', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'The civil service retirement age could not be confirmed from an official source (the National Pension Fund rules could not be loaded).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SD', 1, 'retirement_return_base', 0.06, NULL, 'assumption', 'Central Bank of Sudan Economic and Financial Statistics Review Jan-Jun 2026, table 22', 'https://cbos.gov.sd/sites/default/files/Econ_stat_rview_%28Jan.-Jun.%292026.pdf', '2026-10-31', 'Base case: kept below the 8% assumed return on investment deposits, as no published deposit return or government certificate yield was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SD', 1, 'retirement_return_high', 0.12, NULL, 'assumption', 'Central Bank of Sudan Economic and Financial Statistics Review Jan-Jun 2026, table 22', 'https://cbos.gov.sd/sites/default/files/Econ_stat_rview_%28Jan.-Jun.%292026.pdf', '2026-10-31', 'High case: longer investment deposits with a larger profit share.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SD', 1, 'retirement_return_low', 0.02, NULL, 'assumption', 'Central Bank of Sudan Economic and Financial Statistics Review Jan-Jun 2026', 'https://cbos.gov.sd/sites/default/files/Econ_stat_rview_%28Jan.-Jun.%292026.pdf', '2026-10-31', 'Low case: savings accounts sharing little profit.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SD', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No current return on government savings certificates was found; Government Musharaka Certificates (Shahama) have been sold to the public in the past, but no 2025-2026 issue or return could be confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SD', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Banks in Sudan work on Islamic principles: deposits earn a share of profits rather than fixed interest; the Central Bank of Sudan publishes deposit balances but no average return on savings accounts, and none was found elsewhere.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SD', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":16.65},{"year":2040,"value":13.51},{"year":2065,"value":7.94}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/sudan/2040/', '2025-12-31', '100 / old-age dependency ratio: 6.0 (2025, World Bank), 7.4 (2040) and 12.6 (2065, populationpyramid.net/sudan/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SD', 1, 'tax_bank_interest', NULL, NULL, 'missing', '', '', '2026-10-31', 'The tax treatment of profits on bank deposits could not be confirmed: PwC Tax Summaries does not cover Sudan and no tax authority schedule could be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SD', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'The tax treatment of returns on government certificates could not be confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SD', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Sudan issues no interest-bearing treasury bills (Islamic finance); no short-term government certificate yield was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SD', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 10-year government bond or sukuk yield was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SD', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 5-year government bond or sukuk yield was found.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('SE', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"SE","iso3":"SWE","nameEn":"Sweden","nameNative":"Sverige","region":"europe_central_asia","languages":["sv","en","fi"],"currency":{"code":"SEK","symbol":"kr","decimals":2,"compact":"intl","usdRate":{"value":9.8264,"status":"sourced","sourceName":"Sveriges Riksbank, SEK per USD (SWEA series SEKUSDPMI)","sourceUrl":"https://api.riksbank.se/swea/v1/Observations/Latest/SEKUSDPMI","asOf":"2026-10-30","note":"World Bank 2025 average 9.82."}},"instruments":{"savings_account":{"available":true,"localName":"Sparkonto","localNameEn":"Savings account"},"fdr_3m":{"available":true,"localName":"Fasträntekonto","localNameEn":"Fixed-rate deposit account (3 months)"},"fdr_1y":{"available":true,"localName":"Fasträntekonto","localNameEn":"Fixed-rate deposit account (1 year)"},"dps":{"available":false,"localName":null,"localNameEn":"Monthly recurring deposit","note":"No standard recurring-deposit product; regular saving goes into savings accounts or an investment savings account (ISK)."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":"Government savings certificate","note":"No retail government savings certificate or bond is sold directly to individuals."},"tbill_91d":{"available":true,"localName":"Statsskuldväxlar","localNameEn":"Treasury bills","note":"Traded in large lots, mainly by institutions; individuals reach them through funds.","sourceUrl":"https://api.riksbank.se/swea/v1/Observations/Latest/SETB3MBENCH"},"tbond_5y":{"available":true,"localName":"Statsobligationer","localNameEn":"Government bonds","sourceUrl":"https://api.riksbank.se/swea/v1/Observations/Latest/SEGVB5YC"},"tbond_10y":{"available":true,"localName":"Statsobligationer","localNameEn":"Government bonds","sourceUrl":"https://api.riksbank.se/swea/v1/Observations/Latest/SEGVB10YC"},"equity_fund":{"available":true,"localName":"Aktiefonder och indexfonder","localNameEn":"Equity and index funds","note":"Widely available, often held in an investment savings account (ISK) taxed by a yearly standard levy; the state default premium-pension fund is a global equity fund."},"gold":{"available":true,"localName":"Guldtackor och guldmynt","localNameEn":"Gold bars and coins","note":"Investment gold is exempt from VAT and freely bought."}},"institutions":{"centralBank":{"name":"Sveriges Riksbank","url":"https://www.riksbank.se/en-gb/"},"insuranceRegulator":{"name":"Finansinspektionen (Swedish Financial Supervisory Authority)","url":"https://www.fi.se/en/"},"insuranceComplaints":{"name":"Allmänna reklamationsnämnden (National Board for Consumer Disputes)","url":"https://www.arn.se/"},"pensionScheme":{"name":"Allmän pension (national public pension), Pensionsmyndigheten","url":"https://www.pensionsmyndigheten.se/other-languages/english-engelska/english-engelska/pension-system-in-sweden"},"oldAgeAllowance":{"name":"Garantipension (guarantee pension), Pensionsmyndigheten","url":"https://www.pensionsmyndigheten.se/other-languages/english-engelska/english-engelska/guaranteed-pension-for-those-with-low-income"},"publicHealthCover":{"name":"Regional public health care (1177)","url":"https://www.1177.se/"},"depositInsurance":{"name":"Insättningsgarantin, Riksgälden (Swedish National Debt Office)","url":"https://riksgalden.se/en/our-operations/deposit-insurance/how-the-deposit-insurance-works/"},"statistics":{"name":"Statistiska centralbyrån (Statistics Sweden)","url":"https://www.scb.se/en/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SE', 1, 'bank_deposit_avg_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'World Bank FR.INR.DPST for Sweden stops in 2006. Statistics Sweden (SCB), which publishes bank interest rates on household deposits for the Riksbank, could not be reached (connection refused on scb.se and api.scb.se).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SE', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'Sweden caps interest on high-cost credit (reference rate plus 40 percentage points) but no readable official page confirming a cap or typical rate for credit cards could be reached (Konsumentverket page moved).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SE', 1, 'deposit_insurance_limit', 1150000, NULL, 'sourced', 'Riksgälden (Swedish National Debt Office), how the deposit insurance works', 'https://riksgalden.se/en/our-operations/deposit-insurance/how-the-deposit-insurance-works/', '2026-10-06', 'SEK 1,150,000 per person per institution (changed from SEK 1,050,000 in 2025); up to SEK 5 million extra for deposits from specified life events such as a home sale.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SE', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Swedish banks do not sell a standard monthly recurring deposit product with a published rate; regular saving goes into ordinary savings accounts or an investment savings account (ISK).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SE', 1, 'equity_return_base', 0.054, NULL, 'assumption', 'OMX Stockholm 30 (Trading Economics); 3-month Treasury bill 2.10% less 30% tax = 1.47%', 'https://tradingeconomics.com/sweden/stock-market', '2026-10-31', 'Base set at the after-tax bill rate plus about 4 points, the cap; the Stockholm index has a strong 10-year record, so the full premium is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SE', 1, 'equity_return_high', 0.08, NULL, 'assumption', 'OMX Stockholm 30 long-run record; long-run global equity returns', 'https://tradingeconomics.com/sweden/stock-market', '2026-10-31', 'High case: diversified Swedish and global equity funds matching their long-run record of about 8% in kronor.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SE', 1, 'equity_return_low', 0.03, NULL, 'assumption', 'OMX Stockholm 30 at 3,271 on 30 Oct 2026, +18% over the year (Trading Economics)', 'https://tradingeconomics.com/sweden/stock-market', '2026-10-31', 'Low case: after the 2025-26 rally Swedish shares return only a little more than safe bills.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SE', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No typical 1-year fixed-term deposit (fasträntekonto) rate could be read. Statistics Sweden (SCB), which publishes bank interest rates on household deposits for the Riksbank, could not be reached (connection refused on scb.se and api.scb.se).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SE', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No typical 3-month fixed-term deposit (fasträntekonto) rate could be read. Statistics Sweden (SCB), which publishes bank interest rates on household deposits for the Riksbank, could not be reached (connection refused on scb.se and api.scb.se).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SE', 1, 'fixed_income_return_base', 0.0147, NULL, 'assumption', '3-month Treasury bill 2.10% less 30% capital income tax = 1.47% (Riksbank SETB3MBENCH)', 'https://api.riksbank.se/swea/v1/Observations/Latest/SETB3MBENCH', '2026-10-31', 'Base case: the after-tax Treasury bill rate, a proxy for fixed-term deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SE', 1, 'fixed_income_return_high', 0.022, NULL, 'assumption', '10-year government bond 3.142% less 30% tax = 2.2% (Riksbank SEGVB10YC)', 'https://api.riksbank.se/swea/v1/Observations/Latest/SEGVB10YC', '2026-10-31', 'High case: holding longer government bonds after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SE', 1, 'fixed_income_return_low', 0.01, NULL, 'assumption', 'Riksbank policy rate 1.75% less 30% tax = 1.2%', 'https://api.riksbank.se/swea/v1/Observations/Latest/SECBREPOEFF', '2026-10-31', 'Low case: easy-access savings after tax, below the policy rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SE', 1, 'goal_inflation_education', 0.03, NULL, 'assumption', 'Eurostat HICP Sweden, education (CP10): -15.2% year on year in September 2026', 'https://ec.europa.eu/eurostat/databrowser/view/prc_hicp_minr/default/table?lang=en', '2026-10-31', 'Schooling and university are free for residents and the measured index is volatile; the fees people do pay (courses, private pre-school, materials) are planned at 3%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SE', 1, 'goal_inflation_health', 0.03, NULL, 'assumption', 'Eurostat HICP Sweden, health (ECOICOP 2 CP06): -5.9% year on year in September 2026', 'https://ec.europa.eu/eurostat/databrowser/view/prc_hicp_minr/default/table?lang=en', '2026-10-31', 'The recent fall reflects policy changes to patient and medicine fees; over the long run health costs are planned at 3%, a point above the 2% target.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SE', 1, 'gold_return_base', 0.04, NULL, 'assumption', 'Gold price history (Trading Economics); Riksbank 2% inflation target', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Base case: dollar gold rises with world inflation plus a little, with the krona assumed stable against the dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SE', 1, 'gold_return_high', 0.07, NULL, 'assumption', 'Gold price history (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'High case: a repeat of gold''s strong 2005-2025 trend in krona terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SE', 1, 'gold_return_low', 0.01, NULL, 'assumption', 'Gold price history (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Low case: gold barely keeps pace after the 2025-26 spike, and a firmer krona trims returns.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SE', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'Swedish law (LAS) sets notice periods but no statutory gratuity or severance per year of service could be confirmed from a readable official source; severance (avgångsvederlag) comes only from collective agreements.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SE', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'Hospital care is provided by the regions with a small daily inpatient fee and a yearly high-cost cap; the 1177 regional fee pages could not be read, and no figure for a private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SE', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Private health insurance (sjukvårdsförsäkring) is mostly an employer benefit priced per person, not per SEK 100,000 of cover; no published premium table was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SE', 1, 'inflation_cpi', 0.011, NULL, 'sourced', 'Trading Economics, Sweden inflation rate (SCB CPI, secondary source)', 'https://tradingeconomics.com/sweden/inflation-cpi', '2026-09-30', 'CPI up 1.1% year on year in September 2026 (0.3% in August); CPIF, the Riksbank target measure, 1.5%. SCB''s own site could not be reached. Eurostat HICP for Sweden: 1.0%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SE', 1, 'inflation_projection', 0.02, NULL, 'assumption', 'Riksbank inflation target (2% CPIF); CPI 1.1% in September 2026', 'https://tradingeconomics.com/sweden/inflation-cpi', '2026-10-31', 'The Riksbank targets 2% CPIF inflation and has kept inflation near target outside the 2022-23 spike, so 2% is used for planning.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SE', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life cover (livförsäkring/risklivförsäkring) is sold, often through employers and unions, but no regulator or official premium table per SEK 1,000 of cover was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SE', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Finansinspektionen does not publish an industry-wide life insurance claim settlement ratio that could be found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SE', 1, 'life_expectancy', 83.8, NULL, 'sourced', 'Eurostat, life expectancy by age and sex (demo_mlexpec), Sweden', 'https://ec.europa.eu/eurostat/databrowser/view/demo_mlexpec/default/table?lang=en', '2024-12-31', 'Men 82.3, women 85.3 in 2024; World Bank 2024 total 84.06.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SE', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":25.7,"men":24.5,"women":26.8},{"age":65,"total":21.3,"men":20.2,"women":22.4},{"age":70,"total":17.2,"men":16.1,"women":18.1},{"age":80,"total":9.9,"men":9.1,"women":10.5}]}', 'sourced', 'Eurostat, life expectancy by age and sex (demo_mlexpec), Sweden 2024', 'https://ec.europa.eu/eurostat/databrowser/view/demo_mlexpec/default/table?lang=en', '2024-12-31', 'Latest year published is 2024 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SE', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":68,"womenAge":68,"over90Monthly":null,"meansTested":true}', 'sourced', 'Pensionsmyndigheten, pensionsåldrar och riktålder; garantipension', 'https://www.pensionsmyndigheten.se/ga-i-pension/planera-din-pension/pensionsaldrar-och-riktalder', '2026-10-31', 'Guarantee pension is paid from the riktålder: 67 for people born 1960-1966, forecast 68 for those born 1970-1981 and 69 for 1982-1997 (recalculated yearly), so 68 is used for a planner born after 1975. Needs at least 3 years'' residence, full amount after 40 years from age 16; not asset-tested but reduced against the person''s own income-based pension.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SE', 1, 'old_age_allowance_monthly', 11988, NULL, 'sourced', 'Pensionsmyndigheten, garantipension', 'https://www.pensionsmyndigheten.se/forsta-din-pension/sa-fungerar-pensionen/garantipension', '2026-01-01', 'Maximum guarantee pension SEK 11,988 a month before tax for a single person and SEK 10,853 for a married person (2026; 2.43 and 2.20 price base amounts of SEK 59,200 divided by 12), for 40 years'' residence; it is reduced as income-based pension rises, so it is an income-tested top-up rather than a flat pension.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SE', 1, 'oop_health_share', 0.1338, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=SE', '2024-12-31', NULL, 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SE', 1, 'policy_rate', 0.0175, NULL, 'sourced', 'Sveriges Riksbank, policy rate (SWEA series SECBREPOEFF)', 'https://api.riksbank.se/swea/v1/Observations/Latest/SECBREPOEFF', '2026-10-30', 'Policy rate 1.75% on 30 October 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SE', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":16,"entryAgeMax":null,"pensionFromAge":68,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":false}', 'sourced', 'Pensionsmyndigheten, the Swedish pension system and riktålder', 'https://www.pensionsmyndigheten.se/other-languages/english-engelska/english-engelska/pension-system-in-sweden', '2026-10-31', 'Allmän pension: 16% of pensionable income to the notional income pension and 2.5% to the funded premium pension (18.5% in all). Pension from the riktålder, projected at 68 for people born 1970-81 (earliest 65). Pensions in payment follow wage growth less 1.6% rather than prices; taxed as income.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SE', 1, 'retirement_accumulation_return_base', 0.035, NULL, 'assumption', 'After-tax bill rate 1.47%; equity base 5.4%', 'https://api.riksbank.se/swea/v1/Observations/Latest/SETB3MBENCH', '2026-10-31', 'Base case: roughly half shares at 5.4% and half safe fixed income at about 1.5-2% after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SE', 1, 'retirement_accumulation_return_high', 0.05, NULL, 'assumption', 'After-tax 10-year bond 2.2%; equity high 8%', 'https://api.riksbank.se/swea/v1/Observations/Latest/SEGVB10YC', '2026-10-31', 'High case for a growth-leaning balanced mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SE', 1, 'retirement_accumulation_return_low', 0.025, NULL, 'assumption', 'After-tax bill rate 1.47%; equity low 3%', 'https://api.riksbank.se/swea/v1/Observations/Latest/SETB3MBENCH', '2026-10-31', 'Low case for a balanced mix if shares lag.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SE', 1, 'retirement_age_default', 68, NULL, 'sourced', 'Pensionsmyndigheten, pensionsåldrar och riktålder', 'https://www.pensionsmyndigheten.se/ga-i-pension/planera-din-pension/pensionsaldrar-och-riktalder', '2026-10-31', 'Riktålder (target pension age) is 67 for people born 1960-1966 and projected at 68 for those born 1970-1981, 69 for 1982-1997 and 70 for 1998-2014; earliest public pension withdrawal 64-65 for the 1970s cohorts. Same for men and women.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SE', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'Swedish public employees follow the same public pension ages and employment-protection rules as private employees; no separate statutory retirement age for government service could be confirmed from a readable official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SE', 1, 'retirement_return_base', 0.014, NULL, 'assumption', '3-month Treasury bill 2.10% less 30% tax = 1.47%', 'https://api.riksbank.se/swea/v1/Observations/Latest/SETB3MBENCH', '2026-10-31', 'Base case kept just under the after-tax Treasury bill rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SE', 1, 'retirement_return_high', 0.02, NULL, 'assumption', '10-year government bond 3.142% less 30% tax = 2.2%', 'https://api.riksbank.se/swea/v1/Observations/Latest/SEGVB10YC', '2026-10-31', 'High case: a ladder of longer government bonds after tax, a little under the 10-year yield.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SE', 1, 'retirement_return_low', 0.01, NULL, 'assumption', 'Policy rate 1.75% less 30% tax', 'https://api.riksbank.se/swea/v1/Observations/Latest/SECBREPOEFF', '2026-10-31', 'Low case: easy-access savings after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SE', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No retail government savings certificate or savings bond is sold to individuals in Sweden today; the Debt Office (Riksgälden) ended its retail savings products, and government securities are bought through banks on the market.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SE', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No typical savings-account rate could be read. Statistics Sweden (SCB), which publishes bank interest rates on household deposits for the Riksbank, could not be reached (connection refused on scb.se and api.scb.se).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SE', 1, 'support_ratio', NULL, '{"points":[{"year":2026,"value":3.01},{"year":2040,"value":2.71},{"year":2065,"value":2.23}]}', 'sourced', 'Eurostat EUROPOP2023 projections, old-age dependency ratio (proj_23ndbi, baseline)', 'https://ec.europa.eu/eurostat/databrowser/view/proj_23ndbi/default/table?lang=en', '2026-01-01', '100 divided by the projected old-age dependency ratio (65+ per 100 aged 15-64): 33.2 in 2026, 36.9 in 2040, 44.8 in 2065. World Bank 2025: 33.5.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SE', 1, 'tax_bank_interest', 0.3, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Sweden taxes on personal income', 'https://taxsummaries.pwc.com/sweden/individual/taxes-on-personal-income', '2026-08-11', 'Capital income, including bank interest, is taxed at a flat 30%; banks report interest to the tax agency rather than withholding a final tax. Savings inside an investment savings account (ISK) are taxed instead by a yearly standard levy.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SE', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No retail government savings certificate exists; interest on government securities is ordinary capital income taxed at 30%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SE', 1, 'tbill_91d_rate', 0.021, NULL, 'sourced', 'Sveriges Riksbank, Swedish Treasury bill 3 months (SWEA series SETB3MBENCH)', 'https://api.riksbank.se/swea/v1/Observations/Latest/SETB3MBENCH', '2026-10-30', '3-month Treasury bill (statsskuldväxel) yield 2.10%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SE', 1, 'tbond_10y_rate', 0.0314, NULL, 'sourced', 'Sveriges Riksbank, Swedish government bond 10 years (SWEA series SEGVB10YC)', 'https://api.riksbank.se/swea/v1/Observations/Latest/SEGVB10YC', '2026-10-30', '10-year government bond yield 3.142%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SE', 1, 'tbond_5y_rate', 0.0295, NULL, 'sourced', 'Sveriges Riksbank, Swedish government bond 5 years (SWEA series SEGVB5YC)', 'https://api.riksbank.se/swea/v1/Observations/Latest/SEGVB5YC', '2026-10-30', '5-year government bond yield 2.947%.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('SG', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"SG","iso3":"SGP","nameEn":"Singapore","nameNative":"Singapore","region":"east_asia_pacific","languages":["en","zh","ms","ta"],"currency":{"code":"SGD","symbol":"$","decimals":2,"compact":"intl","usdRate":{"value":1.278,"status":"sourced","sourceName":"Trading Economics, USD/SGD (secondary source)","sourceUrl":"https://tradingeconomics.com/singapore/currency","asOf":"2026-10-30","note":"1.27808 SGD per USD; the MAS exchange-rate page links only to an interactive tool. World Bank PA.NUS.FCRF gives 1.307 for 2025."}},"instruments":{"savings_account":{"available":true,"localName":"Savings account","note":"Bank savings deposits; MAS stopped publishing average rates in 2021."},"fdr_3m":{"available":true,"localName":"Fixed deposit (3 months)"},"fdr_1y":{"available":true,"localName":"Fixed deposit (12 months)"},"dps":{"available":false,"localName":null,"localNameEn":"Recurring deposit","note":"No standard bank recurring-deposit product was identified; monthly savings plans are usually investment plans."},"sanchayapatra_5y":{"available":true,"localName":"Singapore Savings Bonds","note":"10-year government bond for individuals with step-up interest; buy from S$500 monthly, redeem any month without penalty; tax-exempt.","sourceUrl":"https://www.mas.gov.sg/bonds-and-bills/singapore-savings-bonds"},"tbill_91d":{"available":true,"localName":"Singapore Government T-bills","note":"Individuals can buy 6-month and 1-year T-bills at auction from S$1,000; 3-month bills are not offered to individuals.","sourceUrl":"https://www.mas.gov.sg/bonds-and-bills/singapore-government-t-bills-information-for-individuals"},"tbond_5y":{"available":true,"localName":"Singapore Government Securities (5-year bond)","note":"Individuals can bid at SGS bond auctions.","sourceUrl":"https://www.mas.gov.sg/bonds-and-bills/investing-in-singapore-government-securities"},"tbond_10y":{"available":true,"localName":"Singapore Government Securities (10-year bond)","sourceUrl":"https://www.mas.gov.sg/bonds-and-bills/investing-in-singapore-government-securities"},"equity_fund":{"available":true,"localName":"Unit trust or index ETF","note":"Diversified unit trusts and exchange-traded index funds are widely available to retail investors."},"gold":{"available":true,"localName":"Gold bullion","note":"Gold bars and coins can be bought freely."}},"institutions":{"centralBank":{"name":"Monetary Authority of Singapore","url":"https://www.mas.gov.sg/"},"insuranceRegulator":{"name":"Monetary Authority of Singapore","url":"https://www.mas.gov.sg/","note":"MAS is the integrated regulator for banks and insurers."},"insuranceComplaints":{"name":"Financial Industry Disputes Resolution Centre (FIDReC)","url":"https://www.fidrec.com.sg/"},"pensionScheme":{"name":"Central Provident Fund Board (CPF LIFE)","url":"https://www.cpf.gov.sg/"},"oldAgeAllowance":{"name":"Silver Support Scheme","url":"https://www.cpf.gov.sg/member/retirement-income/government-support/silver-support-scheme"},"publicHealthCover":{"name":"Ministry of Health (MediShield Life)","url":"https://www.moh.gov.sg/","note":"MediShield Life, the universal basic health insurance run with the CPF Board."},"depositInsurance":{"name":"Singapore Deposit Insurance Corporation","url":"https://www.sdic.org.sg/"},"statistics":{"name":"Singapore Department of Statistics","url":"https://www.singstat.gov.sg/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SG', 1, 'bank_deposit_avg_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'World Bank FR.INR.DPST stops in 2021 (0.12%), when the MAS bank rate series ended; that figure is far below current rates, so it is not used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SG', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap; the typical effective rate on card balances could not be confirmed from an official page in this pass.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SG', 1, 'deposit_insurance_limit', 100000, NULL, 'sourced', 'Singapore Deposit Insurance Corporation, Deposit Insurance FAQ', 'https://www.sdic.org.sg/di_faq/', '2026-10-31', 'Insured deposits with each scheme member are aggregated and covered up to S$100,000 per depositor.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SG', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No standard bank recurring-deposit product or published rate was found for Singapore.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SG', 1, 'equity_return_base', 0.055, NULL, 'assumption', '1-year SGS T-bill 1.73% (end-Sep 2026), tax-exempt for individuals', 'https://tablebuilder.singstat.gov.sg/table/TS/M700071', '2026-10-31', 'Tax-free safe rate of about 1.7-1.9% plus a 3.6-point premium; the local index has a modest long-run record, so the premium is kept below 4 points.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SG', 1, 'equity_return_high', 0.08, NULL, 'assumption', '1-year SGS T-bill 1.73% (end-Sep 2026), tax-exempt for individuals', 'https://tablebuilder.singstat.gov.sg/table/TS/M700071', '2026-10-31', 'High case for a diversified Singapore and global equity mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SG', 1, 'equity_return_low', 0.025, NULL, 'assumption', '1-year SGS T-bill 1.73% (end-Sep 2026), tax-exempt for individuals', 'https://tablebuilder.singstat.gov.sg/table/TS/M700071', '2026-10-31', 'Low case close to the tax-free safe rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SG', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'MAS''s average 12-month bank fixed deposit series ends in June 2021 (0.24%); no current official average was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SG', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'MAS''s average 3-month bank fixed deposit series ends in June 2021 (0.12%); no current official average was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SG', 1, 'fixed_income_return_base', 0.02, NULL, 'assumption', '1-year T-bill 1.73%, 5-year SGS 2.24%, Savings Bond 10-year average 2.45%, all tax-exempt', 'https://eservices.mas.gov.sg/ssb/public/api/v1/bonds/GX26110X', '2026-10-31', 'Base case: a mix of T-bills and Savings Bonds, tax-free.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SG', 1, 'fixed_income_return_high', 0.0245, NULL, 'assumption', 'MAS Singapore Savings Bonds November 2026: 2.45% average over 10 years, tax-exempt', 'https://eservices.mas.gov.sg/ssb/public/api/v1/bonds/GX26110X', '2026-10-31', 'High case: locking in Savings Bonds or 10-year SGS.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SG', 1, 'fixed_income_return_low', 0.015, NULL, 'assumption', '1-year SGS T-bill 1.73% (end-Sep 2026), tax-exempt for individuals', 'https://tablebuilder.singstat.gov.sg/table/TS/M700071', '2026-10-31', 'Low case: bank fixed deposits and T-bills if short rates fall, tax-free.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SG', 1, 'goal_inflation_education', 0.025, NULL, 'assumption', 'SingStat CPI Education: 0.7% (2025), 3.2% (2024), 2.7% (2023); private tuition 5-6% in 2023-24', 'https://tablebuilder.singstat.gov.sg/table/TS/M213811', '2026-10-31', 'Education CPI averaged about 2% over ten years with private tuition rising faster, so we plan with 2.5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SG', 1, 'goal_inflation_health', 0.03, NULL, 'assumption', 'SingStat CPI Health: 2.7% (2025), 3.9% (2024), 4.5% (2023); 10-year average about 2%', 'https://tablebuilder.singstat.gov.sg/table/TS/M213811', '2026-10-31', 'Health CPI ran near 3-4% in recent years with health insurance premiums rising faster, so we plan with 3%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SG', 1, 'gold_return_base', 0.035, NULL, 'assumption', 'Trading Economics USD/SGD 1.278 (30 Oct 2026), down 1.8% on the year', 'https://tradingeconomics.com/singapore/currency', '2026-10-31', 'Dollar gold trend of about 4% less slow Singapore dollar appreciation under the MAS exchange-rate policy.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SG', 1, 'gold_return_high', 0.07, NULL, 'assumption', 'Trading Economics USD/SGD 1.278 (30 Oct 2026), down 1.8% on the year', 'https://tradingeconomics.com/singapore/currency', '2026-10-31', 'High case with strong dollar gold.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SG', 1, 'gold_return_low', 0, NULL, 'assumption', 'Trading Economics USD/SGD 1.278 (30 Oct 2026), down 1.8% on the year', 'https://tradingeconomics.com/singapore/currency', '2026-10-31', 'Low case: flat dollar gold and a firming Singapore dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SG', 1, 'gratuity_rule', NULL, NULL, 'missing', 'Ministry of Manpower, Responsible retrenchment', 'https://www.mom.gov.sg/employment-practices/retrenchment/responsible-retrenchment', '2026-10-31', 'No statutory gratuity or end-of-service benefit: MOM''s Responsible retrenchment guidance says the retrenchment benefit depends on the employment contract or collective agreement, or must be negotiated (norm 2 weeks to 1 month''s salary per year of service for 2+ years'' service); no law sets one.', 1);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SG', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'MOH publishes bill amounts by procedure through a search tool and fee benchmarks for private single rooms, but no single typical out-of-pocket figure for a major stay was retrieved.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SG', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'MediShield Life premiums are set per person by age, not per S$100,000 of cover, and Integrated Shield Plan premiums by cover were not retrieved.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SG', 1, 'inflation_cpi', 0.022, NULL, 'sourced', 'MAS, Consumer Price Developments in September 2026', 'https://www.mas.gov.sg/news/consumer-price-developments/2026/consumer-price-developments-in-september-2026', '2026-09-30', 'CPI-All Items 2.2% y-o-y in September 2026 (2.3% in August); MAS Core 2.0%. SingStat table M213781 shows the same.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SG', 1, 'inflation_projection', 0.02, NULL, 'assumption', 'MAS inflation forecasts (CPI-All Items about 2.0% in 2026, 1.5-2.5% in 2027); SingStat CPI 2016-2025 average 1.7%', 'https://www.mas.gov.sg/news/consumer-price-developments/2026/consumer-price-developments-in-september-2026', '2026-10-31', 'MAS has no numeric target but treats core inflation just under 2% as consistent with price stability, and forecasts about 2%, so we plan with 2%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SG', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life is widely sold, but no published per-S$1,000 premium rates by age were retrieved in this pass.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SG', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No industry-wide life claim settlement ratio was found from MAS or the life insurance association.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SG', 1, 'life_expectancy', 83.9, NULL, 'sourced', 'SingStat Table M810501, Life Expectancy at Birth (Residents), preliminary', 'https://tablebuilder.singstat.gov.sg/table/TS/M810501', '2025-12-31', 'Residents: men 81.8, women 86.0. World Bank SP.DYN.LE00.IN gives 83.3 for 2024 (total population).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SG', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":26,"men":24,"women":28},{"age":65,"total":21.7,"men":19.8,"women":23.5},{"age":70,"total":17.6,"men":15.9,"women":19.2},{"age":80,"total":10.4,"men":9.3,"women":11.4}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/singapore/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026; totals at 60, 70 and 80 are the mean of men and women. SingStat gives 21.6 years at 65 for residents in 2025 (men 19.9, women 23.1).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SG', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":65,"womenAge":65,"over90Monthly":null,"meansTested":true}', 'sourced', 'CPF Board, Silver Support Scheme', 'https://www.cpf.gov.sg/member/retirement-income/government-support/silver-support-scheme', '2026-10-31', 'Singapore Citizens 65 and above; lifetime CPF contributions by 55 up to S$140,000, 1- to 5-room HDB flat, per capita household income up to S$2,300 a month. No application needed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SG', 1, 'old_age_allowance_monthly', 360, NULL, 'sourced', 'CPF Board, Silver Support Scheme', 'https://www.cpf.gov.sg/member/retirement-income/government-support/silver-support-scheme', '2026-10-31', 'Silver Support Scheme, means-tested quarterly payouts (raised in 2025): up to S$1,080 a quarter (S$360 a month) for 1- and 2-room HDB flat dwellers with per capita household income up to S$1,500, down to S$215 a quarter for 5-room flats with income S$1,500-2,300. Paid automatically to eligible citizens from 65.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SG', 1, 'oop_health_share', 0.2542, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=SG', '2023-12-31', 'Latest World Bank figure is for 2023 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SG', 1, 'policy_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'MAS runs monetary policy through the exchange rate (S$NEER policy band), not a policy interest rate. The market benchmark SORA averaged 1.40% at end-September 2026 (SingStat M700071).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SG', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":65,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":true}', 'sourced', 'CPF Board, CPF LIFE; PwC Worldwide Tax Summaries (CPF benefits excluded from taxable retirement benefits)', 'https://www.cpf.gov.sg/member/retirement-income/monthly-payouts/cpf-life', '2026-10-31', 'CPF is a mandatory contributory scheme for citizen and PR employees; CPF LIFE pays a monthly annuity for life from 65 (Standard plan level; Escalating plan rises 2% a year; neither is indexed to inflation). PwC: ''All retirement benefits other than CPF benefits ... are generally taxable'' (https://taxsummaries.pwc.com/singapore/individual/income-determination). Official payout examples were not retrieved.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SG', 1, 'retirement_accumulation_return_base', 0.04, NULL, 'assumption', 'Equity base 5.5% and SGS/Savings Bonds about 2-2.5%; CPF LIFE savings earn at least 4%', 'https://www.cpf.gov.sg/member/retirement-income/monthly-payouts/cpf-life', '2026-10-31', 'Base case: roughly half equity and half safe bonds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SG', 1, 'retirement_accumulation_return_high', 0.06, NULL, 'assumption', '1-year SGS T-bill 1.73% (end-Sep 2026), tax-exempt for individuals', 'https://tablebuilder.singstat.gov.sg/table/TS/M700071', '2026-10-31', 'High case with the equity high case.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SG', 1, 'retirement_accumulation_return_low', 0.025, NULL, 'assumption', '1-year SGS T-bill 1.73% (end-Sep 2026), tax-exempt for individuals', 'https://tablebuilder.singstat.gov.sg/table/TS/M700071', '2026-10-31', 'Low case for a balanced mix if equities only match bonds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SG', 1, 'retirement_age_default', 65, NULL, 'sourced', 'CPF Board, CPF LIFE (payouts from age 65)', 'https://www.cpf.gov.sg/member/retirement-income/monthly-payouts/cpf-life', '2026-10-31', 'CPF LIFE payouts start from 65 (deferrable to 70), which applies to members born after 1975. The statutory minimum retirement age under the Retirement and Re-employment Act is 64 from 1 July 2026 (MOM), with re-employment beyond it.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SG', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'No separate civil-service retirement age was confirmed from an official page; the statutory minimum retirement age for employees is 64 from 1 July 2026 (MOM, https://www.mom.gov.sg/employment-practices/retirement), which public officers are believed to follow.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SG', 1, 'retirement_return_base', 0.017, NULL, 'assumption', '1-year SGS T-bill 1.73% (end-Sep 2026), tax-exempt for individuals', 'https://tablebuilder.singstat.gov.sg/table/TS/M700071', '2026-10-31', 'Base case at the tax-free 1-year T-bill rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SG', 1, 'retirement_return_high', 0.0245, NULL, 'assumption', 'MAS Singapore Savings Bonds November 2026: 2.45% average over 10 years, tax-exempt', 'https://eservices.mas.gov.sg/ssb/public/api/v1/bonds/GX26110X', '2026-10-31', 'High case: laddered Savings Bonds and SGS.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SG', 1, 'retirement_return_low', 0.012, NULL, 'assumption', '1-year SGS T-bill 1.73% (end-Sep 2026), tax-exempt for individuals', 'https://tablebuilder.singstat.gov.sg/table/TS/M700071', '2026-10-31', 'Low case if short-term rates fall back, tax-free.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SG', 1, 'sanchayapatra_5y_rate', 0.0245, NULL, 'sourced', 'MAS Singapore Savings Bonds, November 2026 issue (GX26110X)', 'https://eservices.mas.gov.sg/ssb/public/api/v1/bonds/GX26110X', '2026-10-31', 'November 2026 issue (issued 2 November 2026, rates set in October): average return 2.45% a year if held 10 years (1.67% in year 1, stepping up); the 5-year average is not shown by this endpoint. Redeemable any month without penalty; tax-exempt.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SG', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'MAS stopped publishing average bank savings deposit rates after June 2021 (0.07% then, MAS Interest Rates of Banks and Finance Companies); no official current average was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SG', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":5.21},{"year":2040,"value":3.13},{"year":2065,"value":1.28}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/singapore/2040/', '2025-12-31', '100 / old-age dependency ratio: 19.18 (2025, World Bank), 32.0 (2040) and 78.4 (2065, populationpyramid.net/singapore/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SG', 1, 'tax_bank_interest', 0, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Singapore individual income determination (secondary source)', 'https://taxsummaries.pwc.com/singapore/individual/income-determination', '2026-10-31', 'Interest from Singapore-approved banks and licensed finance companies is generally not taxable for individuals; no withholding.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SG', 1, 'tax_sanchayapatra_profit', 0, NULL, 'sourced', 'MAS, Singapore Government T-bills: information for individuals', 'https://www.mas.gov.sg/bonds-and-bills/singapore-government-t-bills-information-for-individuals', '2026-10-31', 'For individuals, interest income earned on SGS (including Savings Bonds) is tax exempt.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SG', 1, 'tbill_91d_rate', 0.0187, NULL, 'sourced', 'Trading Economics, Singapore 3-month yield (secondary source)', 'https://tradingeconomics.com/singapore/government-bond-yield', '2026-10-30', '3-month SGS/MAS bill yield 1.87% (Trading Economics, 30 Oct 2026; secondary source, no official 3-month series found on SingStat). Individuals can buy only 6-month and 1-year T-bills; SingStat M700071 shows the 1-year T-bill at 1.73% and 3-month compounded SORA at 1.23% at end-September 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SG', 1, 'tbond_10y_rate', 0.0247, NULL, 'sourced', 'SingStat Table M700071, Government Securities 10-Year Bond Yield (MAS data)', 'https://tablebuilder.singstat.gov.sg/table/TS/M700071', '2026-09-30', 'End-September 2026; Trading Economics shows 2.24% on 30 October 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SG', 1, 'tbond_5y_rate', 0.0224, NULL, 'sourced', 'SingStat Table M700071, Government Securities 5-Year Bond Yield (MAS data)', 'https://tablebuilder.singstat.gov.sg/table/TS/M700071', '2026-09-30', 'End-September 2026; Trading Economics shows 2.03% on 30 October 2026.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('SI', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"SI","iso3":"SVN","nameEn":"Slovenia","nameNative":"Slovenija","region":"europe_central_asia","languages":["sl","hr","en","de","it"],"currency":{"code":"EUR","symbol":"€","decimals":2,"compact":"intl","usdRate":{"value":0.8951,"status":"sourced","sourceName":"European Central Bank euro reference rate (USD)","sourceUrl":"https://data-api.ecb.europa.eu/service/data/EXR/D.USD.EUR.SP00.A","asOf":"2026-10-30","note":"EUR 1 = USD 1.1172 on 30 October 2026, so about EUR 0.895 per US dollar; World Bank 2025 average 0.885."}},"instruments":{"savings_account":{"available":true,"localName":"Varčevalni račun","localNameEn":"Savings account","sourceUrl":"https://data-api.ecb.europa.eu/service/data/MIR/M.SI.B.L21.A.R.A.2250.EUR.N"},"fdr_3m":{"available":true,"localName":"Vezana vloga","localNameEn":"Fixed-term deposit (3 months)"},"fdr_1y":{"available":true,"localName":"Vezana vloga","localNameEn":"Fixed-term deposit (1 year)","sourceUrl":"https://data-api.ecb.europa.eu/service/data/MIR/M.SI.B.L22.F.R.A.2250.EUR.N"},"dps":{"available":true,"localName":"Obročno varčevanje","localNameEn":"Instalment savings","note":"Monthly instalment savings plans offered by banks."},"sanchayapatra_5y":{"available":true,"localName":"Ljudske obveznice","localNameEn":"People''s bonds (government bonds for individuals)","note":"Yearly 3-year fixed-rate issues sold only to individuals resident in Slovenia (2024, 2025, 2026); can be sold early on the Ljubljana Stock Exchange.","sourceUrl":"https://www.gov.si/novice/2026-03-23-dvig-obrestne-mere-za-ljudske-obveznice-na-tri-odstotke/"},"tbill_91d":{"available":true,"localName":"Zakladne menice","localNameEn":"Treasury bills","note":"Auctioned by the Ministry of Finance in EUR 1,000 units; no 3-month bill since September 2025, only 12- and 18-month bills in 2026.","sourceUrl":"https://www.gov.si/assets/ministrstva/MF/Zakladnistvo/Dolg-RS/Obvestila-ZM-slo/Rezultati-avkcije-zakladnih-menic-DZ125-1.-izdaja.pdf"},"tbond_5y":{"available":true,"localName":"Državne obveznice","localNameEn":"Slovenian government bonds"},"tbond_10y":{"available":true,"localName":"Državne obveznice","localNameEn":"Slovenian government bonds","sourceUrl":"https://data-api.ecb.europa.eu/service/data/IRS/M.SI.L.L40.CI.0000.EUR.N.Z"},"equity_fund":{"available":true,"localName":"Vzajemni sklad","localNameEn":"Mutual fund / index fund (ETF)"},"gold":{"available":true,"localName":"Naložbeno zlato","localNameEn":"Investment gold bars and coins","note":"No restriction on buying physical gold; investment gold is VAT-exempt in the EU."}},"institutions":{"centralBank":{"name":"Banka Slovenije (Bank of Slovenia)","url":"https://www.bsi.si/en","note":"Part of the Eurosystem; monetary policy set by the European Central Bank."},"insuranceRegulator":{"name":"Agencija za zavarovalni nadzor (Insurance Supervision Agency)","url":"https://www.a-zn.si/"},"insuranceComplaints":{"name":"Agencija za zavarovalni nadzor, complaints","url":"https://www.a-zn.si/potrosniki/pritozbe/","note":"Complain to the insurer first, then to the agency."},"pensionScheme":{"name":"Zavod za pokojninsko in invalidsko zavarovanje Slovenije (ZPIZ, Pension and Disability Insurance Institute)","url":"https://www.zpiz.si/"},"oldAgeAllowance":{"name":"Varstveni dodatek (supplementary allowance), Centres for Social Work","url":"https://www.gov.si/teme/varstveni-dodatek/","note":"Means-tested; not a universal social pension."},"publicHealthCover":{"name":"Zavod za zdravstveno zavarovanje Slovenije (ZZZS, Health Insurance Institute)","url":"https://www.zzzs.si/"},"depositInsurance":{"name":"Banka Slovenije, deposit guarantee scheme","url":"https://www.bsi.si/en/financial-stability/deposit-guarantee-scheme"},"statistics":{"name":"Statistični urad Republike Slovenije (Statistical Office, SURS)","url":"https://www.stat.si/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SI', 1, 'bank_deposit_avg_rate', 0.0149, NULL, 'sourced', 'ECB MFI interest rate statistics: Slovenian banks, household deposits with agreed maturity (outstanding amounts)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.SI.B.L22.A.R.A.2250.EUR.O', '2026-09-30', 'Average rate on all outstanding household term deposits in September 2026; overnight deposits pay 0.10%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SI', 1, 'credit_card_rate_cap', 0.1055, NULL, 'sourced', 'ECB MFI interest rate statistics: Slovenian banks, extended credit card credit to households (new business)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.SI.B.A2Z3.A.R.A.2250.EUR.N', '2026-09-30', 'Average 10.55% on extended credit card credit in September 2026; this is the typical rate, not a legal cap.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SI', 1, 'deposit_insurance_limit', 100000, NULL, 'sourced', 'Banka Slovenije, deposit guarantee scheme', 'https://www.bsi.si/en/financial-stability/deposit-guarantee-scheme', '2026-10-31', 'EUR 100,000 per eligible depositor per bank.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SI', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Banks offer instalment savings (obročno varčevanje), but no official average rate for them was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SI', 1, 'equity_return_base', 0.055, NULL, 'assumption', 'SBITOP (Trading Economics); 12-month treasury bill 2.85% less 25% tax = 2.1%; 1-2 year deposits 1.75%', 'https://tradingeconomics.com/slovenia/stock-market', '2026-10-31', 'Base case: about 3.5 points over the after-tax safe rate of roughly 2%, within the 4-point limit, for a diversified equity fund in euros.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SI', 1, 'equity_return_high', 0.08, NULL, 'assumption', 'SBITOP (Trading Economics); long-run global equity returns', 'https://tradingeconomics.com/slovenia/stock-market', '2026-10-31', 'High case: a diversified equity fund repeating long-run global equity returns in euro terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SI', 1, 'equity_return_low', 0.03, NULL, 'assumption', 'SBITOP 2,987 on 30 Oct 2026, up 21% in a year, near its August 2026 high of 3,274 (Trading Economics)', 'https://tradingeconomics.com/slovenia/stock-market', '2026-10-31', 'Low case: after a strong run the small Ljubljana market only matches safe bonds for a long spell.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SI', 1, 'fdr_1y_rate', 0.0077, NULL, 'sourced', 'ECB MFI interest rate statistics: Slovenian banks, household deposits with agreed maturity up to 1 year (new business)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.SI.B.L22.F.R.A.2250.EUR.N', '2026-09-30', 'Bucket covers all fixed terms up to one year (0.75% in August, 0.77% in September 2026); deposits of 1-2 years paid 1.75% in September 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SI', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'ECB/Banka Slovenije MFI statistics publish household deposits with agreed maturity up to 1 year as one bucket (0.77% in September 2026); no separate 3-month rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SI', 1, 'fixed_income_return_base', 0.015, NULL, 'assumption', 'Household deposits of 1-2 years 1.75% (ECB MFI, September 2026); people''s bonds 3.0% and 12-month treasury bills 2.85%, tax-free up to EUR 1,000 of interest', 'https://data-api.ecb.europa.eu/service/data/MIR/M.SI.B.L22.G.R.A.2250.EUR.N', '2026-10-31', 'Base case: rolling 1-2 year term deposits with occasional people''s bonds, kept below current rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SI', 1, 'fixed_income_return_high', 0.029, NULL, 'assumption', 'Slovenia 10-year bond 3.86% less 25% tax = 2.9% (ECB convergence yield, September 2026)', 'https://data-api.ecb.europa.eu/service/data/IRS/M.SI.L.L40.CI.0000.EUR.N.Z', '2026-10-31', 'High case: holding long government bonds after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SI', 1, 'fixed_income_return_low', 0.007, NULL, 'assumption', 'Household deposits up to 1 year 0.77% (ECB MFI statistics, September 2026), tax-free up to EUR 1,000 of interest', 'https://data-api.ecb.europa.eu/service/data/MIR/M.SI.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Low case: short bank deposits, which pay very little in Slovenia.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SI', 1, 'goal_inflation_education', 0.035, NULL, 'assumption', 'Eurostat/ECB HICP Slovenia, education: 4.0% year on year in December 2025', 'https://data-api.ecb.europa.eu/service/data/ICP/M.SI.N.100000.4.ANR', '2026-10-31', 'Public education is largely free; paid education rose about 4% in 2025, so 3.5% is used for planning.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SI', 1, 'goal_inflation_health', 0.04, NULL, 'assumption', 'Eurostat/ECB HICP Slovenia, health: 5.8% year on year in December 2025', 'https://data-api.ecb.europa.eu/service/data/ICP/M.SI.N.060000.4.ANR', '2026-10-31', 'Health prices have run well above headline inflation; 4% is used as a long-run planning figure rather than the 2025 spike.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SI', 1, 'gold_return_base', 0.04, NULL, 'assumption', 'Gold price history (Trading Economics); ECB 2% inflation target', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Base case: dollar gold rises a little faster than world inflation and the euro is assumed stable against the dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SI', 1, 'gold_return_high', 0.07, NULL, 'assumption', 'Gold price history (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'High case: a repeat of gold''s strong 2005-2025 trend in euro terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SI', 1, 'gold_return_low', 0.01, NULL, 'assumption', 'Gold USD 3,876/oz on 30 Oct 2026, 31% below the January 2026 high (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Low case: gold barely keeps its value after the 2025-26 spike while the euro holds steady against the dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SI', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Employment Relationships Act (ZDR-1) provides severance pay on dismissal for business reasons and a retirement severance payment, but its text could not be read (pisrs.si needs JavaScript), so the rule is not recorded.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SI', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'Hospital care is covered by compulsory health insurance (ZZZS) with complementary insurance for co-payments; no official figure for a typical out-of-pocket private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SI', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Private health insurance in Slovenia is mainly complementary or supplementary cover at flat premiums, not priced per sum insured; no premium table per EUR 100,000 of cover was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SI', 1, 'inflation_cpi', 0.033, NULL, 'sourced', 'Trading Economics (Statistical Office of the Republic of Slovenia CPI, October 2026)', 'https://tradingeconomics.com/slovenia/inflation-cpi', '2026-10-31', 'CPI 3.3% year on year in October 2026, unchanged from September (released 30 October 2026); secondary source because stat.si was not read directly. World Bank 2025 average 2.4%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SI', 1, 'inflation_projection', 0.025, NULL, 'assumption', 'ECB 2% medium-term target; Slovenian HICP 2021-2025 average 4.6% (ECB ICP); CPI 3.3% in October 2026', 'https://data-api.ecb.europa.eu/service/data/ICP/A.SI.N.000000.4.AVR', '2026-10-31', 'Slovenia shares the ECB''s 2% target; inflation has run a little above it (2.5% in 2025, 3.3% in October 2026), so 2.5% is used for planning.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SI', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life cover (riziko življenjsko zavarovanje) is sold, but no regulator or official premium table per EUR 1,000 of cover was found; insurer quotes cannot be used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SI', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Insurance Supervision Agency (AZN) publishes market statistics but no industry-wide life claim settlement ratio was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SI', 1, 'life_expectancy', 82.1, NULL, 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/slovenia', '2026-07-01', 'Men 79.5, women 84.7 (UN WPP estimate for 2026); World Bank 2024 figure 82.3.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SI', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":24.2,"men":22.2,"women":26.2},{"age":65,"total":20.1,"men":18.3,"women":21.8},{"age":70,"total":16.2,"men":14.6,"women":17.5},{"age":80,"total":9.3,"men":8.3,"women":10}]}', 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/slovenia', '2026-07-01', 'Remaining years computed from georank''s expected age at death by current age (UN WPP 2026 estimate).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SI', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":65,"womenAge":63,"over90Monthly":null,"meansTested":true}', 'sourced', 'Government of Slovenia, varstveni dodatek (supplementary allowance)', 'https://www.gov.si/teme/varstveni-dodatek/', '2026-06-04', 'Unemployed or permanently unable-to-work women over 63 and men over 65 qualify; pensioners on low pensions qualify at any age. Means-tested on household income and savings; since 1 January 2026 adult children''s duty of support is no longer checked.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SI', 1, 'old_age_allowance_monthly', 238.49, NULL, 'sourced', 'Government of Slovenia, varstveni dodatek (supplementary allowance)', 'https://www.gov.si/teme/varstveni-dodatek/', '2026-06-04', 'Maximum supplementary allowance for a single person living alone; it is means-tested (income threshold EUR 745.92 from 1 April 2026), tops up low pensions or no income, and is paid by the Centres for Social Work. Slovenia has no universal social pension.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SI', 1, 'oop_health_share', 0.1174, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=SI', '2024-12-31', '2024 is the latest year published (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SI', 1, 'policy_rate', 0.025, NULL, 'sourced', 'European Central Bank, key ECB interest rates (deposit facility)', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.en.html', '2026-09-16', 'Slovenia uses the euro; ECB deposit facility rate raised from 2.25% to 2.50% with effect from 16 September 2026 (main refinancing rate 2.65%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SI', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":67,"nomineeUntilAge":null,"inflationLinked":true,"taxFree":null}', 'sourced', 'Government of Slovenia, pension system reform', 'https://www.gov.si/zbirke/projekti-in-programi/reforma-pokojninskega-sistema/', '2026-10-31', 'Compulsory pension and disability insurance run by ZPIZ, at least 15 years of insurance. Pension age 65 now, 67 from 2035 (62 with 40 years of service). Pensions are indexed 50% to wages and 50% to prices in 2026-2034, moving to 20/80 by 2045; accrual for 40 years rises from 63.5% to 70% by 2035.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SI', 1, 'retirement_accumulation_return_base', 0.035, NULL, 'assumption', 'Fixed income base 1.5%; equity base 5.5%', 'https://tradingeconomics.com/slovenia/stock-market', '2026-10-31', 'Base case: roughly half shares at 5.5% and half safe fixed income at about 1.5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SI', 1, 'retirement_accumulation_return_high', 0.055, NULL, 'assumption', '10-year bond 2.9% after tax; equity high 8%', 'https://data-api.ecb.europa.eu/service/data/IRS/M.SI.L.L40.CI.0000.EUR.N.Z', '2026-10-31', 'High case for a growth-leaning balanced mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SI', 1, 'retirement_accumulation_return_low', 0.02, NULL, 'assumption', '1-2 year deposits 1.75%; SBITOP record (Trading Economics)', 'https://tradingeconomics.com/slovenia/stock-market', '2026-10-31', 'Low case for a balanced mix if shares lag.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SI', 1, 'retirement_age_default', 67, NULL, 'sourced', 'Government of Slovenia, pension system reform', 'https://www.gov.si/zbirke/projekti-in-programi/reforma-pokojninskega-sistema/', '2026-10-31', 'Under the 2025 reform the pension age with 15 years of insurance rises from 65 (until 2027) by 3 months a year from 2028 to 67 in 2035; with 40 years of service it rises from 60 to 62. Same for men and women; applies to anyone born after 1975.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SI', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'Public employees are in the same compulsory pension insurance (ZPIZ); no source read stated a separate mandatory retirement age for government employees.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SI', 1, 'retirement_return_base', 0.015, NULL, 'assumption', '12-month treasury bill 2.85% less 25% tax = 2.1% (Ministry of Finance, DZ125, 8 September 2026); 1-2 year deposits 1.75% (ECB MFI)', 'https://www.gov.si/assets/ministrstva/MF/Zakladnistvo/Dolg-RS/Obvestila-ZM-slo/Rezultati-avkcije-zakladnih-menic-DZ125-1.-izdaja.pdf', '2026-10-31', 'Base case kept below the after-tax 12-month treasury bill rate and the 1-2 year deposit rate, because deposits of up to 1 year pay only 0.77%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SI', 1, 'retirement_return_high', 0.025, NULL, 'assumption', 'Slovenia 10-year bond 3.86% less 25% tax = 2.9% (ECB convergence yield, September 2026)', 'https://data-api.ecb.europa.eu/service/data/IRS/M.SI.L.L40.CI.0000.EUR.N.Z', '2026-10-31', 'High case: a ladder of government bonds held to maturity, below the current after-tax 10-year yield.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SI', 1, 'retirement_return_low', 0.007, NULL, 'assumption', 'Household deposits up to 1 year 0.77% (ECB MFI statistics, September 2026), tax-free up to EUR 1,000 of interest', 'https://data-api.ecb.europa.eu/service/data/MIR/M.SI.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Low case: short deposits only.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SI', 1, 'sanchayapatra_5y_rate', 0.03, NULL, 'sourced', 'Ministry of Finance of Slovenia: people''s bonds RS99, interest rate raised to 3% (news, 23 March 2026)', 'https://www.gov.si/novice/2026-03-23-dvig-obrestne-mere-za-ljudske-obveznice-na-tri-odstotke/', '2026-04-02', 'Third issue of people''s bonds (ljudske obveznice) RS99: fixed 3.0% a year for 3 years (2 April 2026 to 2 April 2029), sold only to individuals resident in Slovenia, EUR 1,000 to EUR 250,000, raised from 2.6% before the offer closed on 27 March 2026. Issues are yearly (2024, 2025, 2026); none is on sale now.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SI', 1, 'savings_account_rate', 0.001, NULL, 'sourced', 'ECB MFI interest rate statistics: Slovenian banks, household overnight deposits (new business)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.SI.B.L21.A.R.A.2250.EUR.N', '2026-09-30', 'Average 0.10% on household overnight deposits (current and most savings accounts) in September 2026, the same as in August.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SI', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":2.85},{"year":2040,"value":2.08},{"year":2065,"value":1.79}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/slovenia/2040/', '2025-12-31', '100 / old-age dependency ratio: 35.1 (2025, World Bank), 48.1 (2040) and 56.0 (2065, populationpyramid.net/slovenia/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SI', 1, 'tax_bank_interest', 0.25, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Slovenia income determination', 'https://taxsummaries.pwc.com/slovenia/individual/income-determination', '2026-07-15', 'Interest is taxed at a flat 25%, but interest on bank deposits in Slovenia or elsewhere in the EU is not taxed up to EUR 1,000, so most savers pay nothing.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SI', 1, 'tax_sanchayapatra_profit', 0.25, NULL, 'sourced', 'Ministry of Finance of Slovenia: additional explanations on bonds for individuals RS99 (24 March 2026)', 'https://www.gov.si/assets/ministrstva/MF/Zakladnistvo/Dolg-RS/3-obveznica-za-fizicne-osebe-RS99-2026/Dodatna-pojasnila-o-obveznicah-za-fizicne-osebe-visji-kupon-24.3.2026.pdf', '2026-03-24', 'Interest on people''s bonds issued in 2024-2026 and on bank deposits is tax-free up to EUR 1,000 a year combined; the excess is taxed at 25%. Held in an individual investment account (INR), the yield is taxed at 15%, or nothing on the first withdrawal after 15 years.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SI', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Ministry of Finance has not auctioned 3-month treasury bills (TZ) since TZ225 on 9 September 2025 (1.90%, before two ECB hikes); in 2026 it issues 12-month bills (DZ125: 2.85% on 8 September 2026) and 18-month bills (OZ25: 3.35% on 6 October 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SI', 1, 'tbond_10y_rate', 0.0386, NULL, 'sourced', 'ECB long-term interest rate for convergence purposes, Slovenia (10-year government bond yield, monthly average)', 'https://data-api.ecb.europa.eu/service/data/IRS/M.SI.L.L40.CI.0000.EUR.N.Z', '2026-09-30', '3.86% average for September 2026 (3.54% in August); Trading Economics showed about 3.9% at the start of November 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SI', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 5-year Slovenian government bond yield was found; Trading Economics shows only the 10-year yield.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('SK', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"SK","iso3":"SVK","nameEn":"Slovakia","nameNative":"Slovensko","region":"europe_central_asia","languages":["sk","cs","en","de","hu"],"currency":{"code":"EUR","symbol":"€","decimals":2,"compact":"intl","usdRate":{"value":0.8951,"status":"sourced","sourceName":"European Central Bank euro reference rate (USD)","sourceUrl":"https://data-api.ecb.europa.eu/service/data/EXR/D.USD.EUR.SP00.A","asOf":"2026-10-30","note":"EUR 1 = USD 1.1172 on 30 October 2026, so about EUR 0.895 per US dollar; World Bank 2025 average 0.885."}},"instruments":{"savings_account":{"available":true,"localName":"Sporiaci účet","localNameEn":"Savings account","sourceUrl":"https://data-api.ecb.europa.eu/service/data/MIR/M.SK.B.L21.A.R.A.2250.EUR.N"},"fdr_3m":{"available":true,"localName":"Termínovaný vklad","localNameEn":"Fixed-term deposit (3 months)"},"fdr_1y":{"available":true,"localName":"Termínovaný vklad","localNameEn":"Fixed-term deposit (1 year)","sourceUrl":"https://data-api.ecb.europa.eu/service/data/MIR/M.SK.B.L22.F.R.A.2250.EUR.N"},"dps":{"available":true,"localName":"Stavebné sporenie","localNameEn":"Building savings","note":"Regular saving with building societies, with a yearly state premium; there is no generic monthly recurring deposit."},"sanchayapatra_5y":{"available":true,"localName":"Dlhopisy pre ľudí (štátne dlhopisy pre občanov)","localNameEn":"State bonds for citizens","note":"Sold by the Debt and Liquidity Management Agency to individuals only, in occasional issues (March 2025, March 2026) of 2- and 4-year fixed-rate bonds; interest tax-free; can be sold early on the stock exchange.","sourceUrl":"https://dlhopisypreludi.ardal.sk/fileadmin/2026/SD_259_Prehlad.pdf"},"tbill_91d":{"available":false,"localName":"Štátne pokladničné poukážky","localNameEn":"State treasury bills","note":"Issued only occasionally to primary dealers; not offered to individuals."},"tbond_5y":{"available":true,"localName":"Štátne dlhopisy","localNameEn":"Slovak government bonds","sourceUrl":"https://www.ardal.sk/sk/statne-cenne-papiere/statne-dlhopisy/vysledky-aukcii-sd"},"tbond_10y":{"available":true,"localName":"Štátne dlhopisy","localNameEn":"Slovak government bonds","sourceUrl":"https://www.ardal.sk/_img/Documents/Vysledky_aukcie/VA_SD_260_20261019.pdf"},"equity_fund":{"available":true,"localName":"Podielový fond","localNameEn":"Mutual fund / index fund (ETF)"},"gold":{"available":true,"localName":"Investičné zlato","localNameEn":"Investment gold bars and coins","note":"No restriction on buying physical gold; investment gold is VAT-exempt in the EU."}},"institutions":{"centralBank":{"name":"Národná banka Slovenska (National Bank of Slovakia)","url":"https://nbs.sk/en/","note":"Part of the Eurosystem; monetary policy set by the European Central Bank."},"insuranceRegulator":{"name":"Národná banka Slovenska, financial market supervision","url":"https://nbs.sk/en/financial-market-supervision1/","note":"The NBS supervises insurers as well as banks."},"insuranceComplaints":{"name":"Národná banka Slovenska, financial consumer protection","url":"https://nbs.sk/en/financial-market-supervision1/fcp/how-to-proceed-if-you-are-dissatisfied-with-the-conduct-of-a-financial-institution/","note":"Complain to the insurer first, then to the NBS."},"pensionScheme":{"name":"Sociálna poisťovňa (Social Insurance Agency)","url":"https://www.socpoist.sk/"},"oldAgeAllowance":null,"publicHealthCover":{"name":"Úrad pre dohľad nad zdravotnou starostlivosťou (Health Care Surveillance Authority)","url":"https://www.udzs-sk.sk/","note":"Supervises the compulsory public health insurance that covers all residents."},"depositInsurance":{"name":"Fond ochrany vkladov (Deposit Protection Fund)","url":"https://www.fovsr.sk/"},"statistics":{"name":"Štatistický úrad Slovenskej republiky (Statistical Office of the Slovak Republic)","url":"https://slovak.statistics.sk/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SK', 1, 'bank_deposit_avg_rate', 0.019, NULL, 'sourced', 'ECB MFI interest rate statistics: Slovak banks, household deposits with agreed maturity (outstanding amounts)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.SK.B.L22.A.R.A.2250.EUR.O', '2026-09-30', 'Average rate on all outstanding household term deposits in September 2026; overnight deposits pay 0.07%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SK', 1, 'credit_card_rate_cap', 0.1893, NULL, 'sourced', 'ECB MFI interest rate statistics: Slovak banks, extended credit card credit to households (new business)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.SK.B.A2Z3.A.R.A.2250.EUR.N', '2026-09-30', 'Average 18.93% on extended credit card credit in September 2026; this is the typical rate, not a legal cap.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SK', 1, 'deposit_insurance_limit', 100000, NULL, 'sourced', 'Fond ochrany vkladov (Deposit Protection Fund), frequently asked questions', 'https://fovsr.sk/caste-otazky/', '2026-10-31', 'EUR 100,000 per depositor per bank; some deposits (inheritance, severance pay, sale of a home and similar) are protected in full for one year.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SK', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Slovakia''s regular-saving product is building savings (stavebné sporenie) with a state premium; no official average rate for it was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SK', 1, 'equity_return_base', 0.055, NULL, 'assumption', 'SAX index (Trading Economics); retail state bond 3.0% tax-free (ARDAL); 1-year deposit 2.43% less 19% tax (ECB MFI)', 'https://tradingeconomics.com/slovakia/stock-market', '2026-10-31', 'The SAX has a weak long-run record and few listed firms, so the base case assumes a diversified global equity fund in euros earning about 3.5 points over the after-tax safe rate of roughly 2.0% (1-year deposits 2.43% less 19% tax).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SK', 1, 'equity_return_high', 0.08, NULL, 'assumption', 'SAX index (Trading Economics); long-run global equity returns', 'https://tradingeconomics.com/slovakia/stock-market', '2026-10-31', 'High case: a global equity fund repeating its long-run record in euro terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SK', 1, 'equity_return_low', 0.03, NULL, 'assumption', 'SAX index 320 on 29 Oct 2026, still about 38% below its 2005 high of 513 (Trading Economics)', 'https://tradingeconomics.com/slovakia/stock-market', '2026-10-31', 'Low case: shares barely beat tax-free state bonds, as the small Slovak market has done for twenty years.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SK', 1, 'fdr_1y_rate', 0.0243, NULL, 'sourced', 'ECB MFI interest rate statistics: Slovak banks, household deposits with agreed maturity up to 1 year (new business)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.SK.B.L22.F.R.A.2250.EUR.N', '2026-09-30', 'Bucket covers all fixed terms up to one year (2.18% in August, 2.43% in September 2026); 1-2 years paid 2.98% in September 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SK', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'ECB/NBS MFI statistics publish household deposits with agreed maturity up to 1 year as one bucket (2.43% in September 2026); no separate 3-month rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SK', 1, 'fixed_income_return_base', 0.022, NULL, 'assumption', '1-year deposits 2.0% after tax; retail state bonds 2.7-3.0% tax-free (ARDAL)', 'https://dlhopisypreludi.ardal.sk/fileadmin/2026/SD_259_Prehlad.pdf', '2026-10-31', 'Base case: a mix of term deposits and the occasional tax-free retail state bond.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SK', 1, 'fixed_income_return_high', 0.032, NULL, 'assumption', '10-year state bond 4.36% less 19% tax = 3.5% (ARDAL auction 19 Oct 2026)', 'https://www.ardal.sk/_img/Documents/Vysledky_aukcie/VA_SD_260_20261019.pdf', '2026-10-31', 'High case: holding longer state bonds after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SK', 1, 'fixed_income_return_low', 0.015, NULL, 'assumption', 'Household deposits up to 1 year 2.43% less 19% tax = 2.0% (ECB MFI statistics, September 2026)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.SK.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Low case: bank term deposits after tax if ECB rates fall back.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SK', 1, 'goal_inflation_education', 0.045, NULL, 'assumption', 'Eurostat/ECB HICP Slovakia, education: 8.8% year on year in December 2025', 'https://data-api.ecb.europa.eu/service/data/ICP/M.SK.N.100000.4.ANR', '2026-10-31', 'Public schooling is free but paid education (private schools, courses) has risen fast; 4.5% is used for planning rather than the 2025 spike.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SK', 1, 'goal_inflation_health', 0.035, NULL, 'assumption', 'Eurostat/ECB HICP Slovakia, health: 2.6% year on year in December 2025', 'https://data-api.ecb.europa.eu/service/data/ICP/M.SK.N.060000.4.ANR', '2026-10-31', 'Health prices rose a little below headline inflation in 2025; 3.5%, slightly above the planning inflation rate, is used for long-run medical costs.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SK', 1, 'gold_return_base', 0.04, NULL, 'assumption', 'Gold price history (Trading Economics); ECB 2% inflation target', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Base case: dollar gold rises a little faster than world inflation and the euro is assumed stable against the dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SK', 1, 'gold_return_high', 0.07, NULL, 'assumption', 'Gold price history (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'High case: a repeat of gold''s strong 2005-2025 trend in euro terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SK', 1, 'gold_return_low', 0.01, NULL, 'assumption', 'Gold USD 3,876/oz on 30 Oct 2026, 31% below the January 2026 high (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Low case: gold barely keeps its value after the 2025-26 spike while the euro holds steady against the dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SK', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Labour Code provides a retirement allowance (odchodné) on first retirement and redundancy severance (odstupné), both set in months of average earnings rather than days per year of service; the Labour Code text itself was not read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SK', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'Hospital care is covered by compulsory public health insurance; no official figure for a typical out-of-pocket private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SK', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Private health insurance is a small supplementary market not priced per sum insured; no premium table per EUR 100,000 of cover was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SK', 1, 'inflation_cpi', 0.031, NULL, 'sourced', 'Trading Economics (Statistical Office of the Slovak Republic CPI, September 2026)', 'https://tradingeconomics.com/slovakia/inflation-cpi', '2026-09-30', 'CPI 3.1% year on year in September 2026, unchanged from August (released 15 October 2026); secondary source because slovak.statistics.sk blocked automated reading. World Bank 2025 average 4.0%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SK', 1, 'inflation_projection', 0.03, NULL, 'assumption', 'ECB 2% medium-term target; Slovak HICP 2021-2025 average 6.6% (ECB ICP); CPI 3.1% in September 2026', 'https://data-api.ecb.europa.eu/service/data/ICP/A.SK.N.000000.4.AVR', '2026-10-31', 'Slovakia shares the ECB''s 2% target but its inflation has run well above the euro area (4.2% in 2025, 3.1% in September 2026), so 3% is used for planning.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SK', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life cover (rizikové životné poistenie) is sold, but no regulator or official premium table per EUR 1,000 of cover was found; insurer quotes cannot be used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SK', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'NBS publishes insurance market totals but no industry-wide life claim settlement ratio was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SK', 1, 'life_expectancy', 78.8, NULL, 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/slovakia', '2026-07-01', 'Men 75.6, women 82.0 (UN WPP estimate for 2026); World Bank 2024 figure 78.4.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SK', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":22.2,"men":19.9,"women":24.2},{"age":65,"total":18.4,"men":16.4,"women":20},{"age":70,"total":14.7,"men":13.1,"women":15.9},{"age":80,"total":8.4,"men":7.6,"women":8.8}]}', 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/slovakia', '2026-07-01', 'Remaining years computed from georank''s expected age at death by current age (UN WPP 2026 estimate).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SK', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension exists in Slovakia (European Commission guide, July 2026), so there are no eligibility ages.', 1);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SK', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'The European Commission guide Your social security rights in Slovakia (July 2026) lists only contributory old-age pensions (the minimum pension needs 30 insurance years); there is no non-contributory social pension, and low-income older people rely on means-tested assistance in material need.', 1);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SK', 1, 'oop_health_share', 0.2015, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=SK', '2023-12-31', '2023 is the latest year published (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SK', 1, 'policy_rate', 0.025, NULL, 'sourced', 'European Central Bank, key ECB interest rates (deposit facility)', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.en.html', '2026-09-16', 'Slovakia uses the euro; ECB deposit facility rate raised from 2.25% to 2.50% with effect from 16 September 2026 (main refinancing rate 2.65%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SK', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":64,"nomineeUntilAge":null,"inflationLinked":true,"taxFree":null}', 'sourced', 'Sociálna poisťovňa (Social Insurance Agency): retirement age; pension valorisation from 1 January 2027', 'https://www.socpoist.sk/socialne-poistenie/dochodkove-poistenie/vseobecne-informacie/dochodkovy-vek', '2026-10-28', 'Compulsory pay-as-you-go pension insurance (1st pillar) plus the funded old-age saving pillar; 15 insurance years needed. Pension age 64 years 2 months for the 1968 cohort and rising with life expectancy for later cohorts. Pensions rise every January by pensioner-household inflation: 3.4% from 1 January 2027 per the agency notice of 28 October 2026 (https://www.socpoist.sk/news/socialna-poistovna-od-1-januara-2027-zvysi-dochodky-o-34-automaticky-dochodcovia-nemusia-o-nic).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SK', 1, 'retirement_accumulation_return_base', 0.04, NULL, 'assumption', 'Fixed income base 2.2%; equity base 5.5%', 'https://dlhopisypreludi.ardal.sk/fileadmin/2026/SD_259_Prehlad.pdf', '2026-10-31', 'Base case: roughly half shares at 5.5% and half safe fixed income at about 2.2% after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SK', 1, 'retirement_accumulation_return_high', 0.055, NULL, 'assumption', '10-year state bond 3.5% after tax; equity high 8%', 'https://www.ardal.sk/_img/Documents/Vysledky_aukcie/VA_SD_260_20261019.pdf', '2026-10-31', 'High case for a growth-leaning balanced mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SK', 1, 'retirement_accumulation_return_low', 0.025, NULL, 'assumption', '1-year deposit 2.0% after tax; SAX record (Trading Economics)', 'https://tradingeconomics.com/slovakia/stock-market', '2026-10-31', 'Low case for a balanced mix if shares lag.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SK', 1, 'retirement_age_default', 64.17, NULL, 'sourced', 'Sociálna poisťovňa (Social Insurance Agency), retirement age', 'https://www.socpoist.sk/socialne-poistenie/dochodkove-poistenie/vseobecne-informacie/dochodkovy-vek', '2026-07-01', '64 years 2 months for men and childless women born in 1968, the latest cohort set by decree (women with children retire 6 months earlier per child, up to 18 months). For people born after 1966 the age rises with life expectancy and is set only a few years ahead, so the age for people born after 1975 is not yet fixed and will be higher; 64.17 is the floor.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SK', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'Civil servants are in the general Social Insurance Agency pension scheme; no source read stated a separate mandatory retirement age for government employees.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SK', 1, 'retirement_return_base', 0.017, NULL, 'assumption', 'Household deposits up to 1 year 2.43% less 19% tax = 2.0% (ECB MFI statistics, September 2026)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.SK.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Base case kept just below the after-tax 1-year deposit rate, since tax-free retail state bonds are sold only occasionally.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SK', 1, 'retirement_return_high', 0.028, NULL, 'assumption', 'Retail state bonds 2.7-3.0% tax-free (ARDAL); 10-year state bond 3.5% after tax', 'https://dlhopisypreludi.ardal.sk/fileadmin/2026/SD_259_Prehlad.pdf', '2026-10-31', 'High case: a ladder of retail and longer state bonds held to maturity.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SK', 1, 'retirement_return_low', 0.012, NULL, 'assumption', 'Household deposits up to 1 year 2.43% less 19% tax = 2.0% (ECB MFI statistics, September 2026)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.SK.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Low case: term deposits after tax if ECB rates fall.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SK', 1, 'sanchayapatra_5y_rate', 0.03, NULL, 'sourced', 'Debt and Liquidity Management Agency (ARDAL): issue summary of state bond 259 PATRIOT II (bonds for citizens)', 'https://dlhopisypreludi.ardal.sk/fileadmin/2026/SD_259_Prehlad.pdf', '2026-03-27', 'Fixed 3.000% a year for 4 years (27 March 2026 to 27 March 2030), sold only to individuals 2-20 March 2026 in EUR 1,000 units; the 2-year INVESTOR II paid 2.70%. Issues are occasional and none is on sale now.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SK', 1, 'savings_account_rate', 0.0007, NULL, 'sourced', 'ECB MFI interest rate statistics: Slovak banks, household overnight deposits (new business)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.SK.B.L21.A.R.A.2250.EUR.N', '2026-09-30', 'Average 0.07% on household overnight deposits (current and most savings accounts) in September 2026, the same as in August.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SK', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":3.44},{"year":2040,"value":2.52},{"year":2065,"value":1.63}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/slovakia/2040/', '2025-12-31', '100 / old-age dependency ratio: 29.1 (2025, World Bank), 39.7 (2040) and 61.2 (2065, populationpyramid.net/slovakia/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SK', 1, 'tax_bank_interest', 0.19, NULL, 'sourced', 'ARDAL, Dlhopisy pre ľudí: yields and risks (model comparison of term deposit and state bond)', 'https://dlhopisypreludi.ardal.sk/vynosy-a-rizika', '2026-10-31', 'The agency''s model example taxes EUR 30 of deposit interest at EUR 5.70, i.e. the 19% withholding tax on bank interest for individuals; the page does not state the rate itself.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SK', 1, 'tax_sanchayapatra_profit', 0, NULL, 'sourced', 'ARDAL, Dlhopisy pre ľudí: yields and risks', 'https://dlhopisypreludi.ardal.sk/vynosy-a-rizika', '2026-10-31', 'Interest on the state bonds for citizens is shown as exempt from tax (oslobodené od dane), against taxed interest on term deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SK', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Slovakia issues state treasury bills (ŠPP) only occasionally and to primary dealers; no recent 3-month yield was found on ARDAL''s pages.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SK', 1, 'tbond_10y_rate', 0.0436, NULL, 'sourced', 'ARDAL, auction results for state bond ŠD 260 A (maturing 30 September 2036)', 'https://www.ardal.sk/_img/Documents/Vysledky_aukcie/VA_SD_260_20261019.pdf', '2026-10-19', 'Average accepted yield 4.3603% on 19 October 2026; Trading Economics showed 4.33% on 30 October 2026 and the ECB convergence yield was 4.16% for September 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SK', 1, 'tbond_5y_rate', 0.0326, NULL, 'sourced', 'ARDAL, auction results for state bond ŠD 251 H (maturing 6 November 2031)', 'https://www.ardal.sk/_img/Documents/Vysledky_aukcie/VA_SD_251_20260518.pdf', '2026-05-18', 'Average accepted yield 3.2634% on 18 May 2026, the latest auction of a bond with about 5 years to run; it predates the ECB hikes of June and September 2026. More recent ARDAL auctions bracket the current 5-year yield: ŠD 255 (June 2029) at 3.5875% on 19 October 2026 and ŠD 247 (June 2033) at 3.9048% on 21 September 2026.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('SL', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"SL","iso3":"SLE","nameEn":"Sierra Leone","nameNative":"Salone","region":"sub_saharan_africa","languages":["kri","en","men","tem"],"currency":{"code":"SLE","symbol":"Le","decimals":2,"compact":"intl","usdRate":{"value":22.8065,"status":"sourced","sourceName":"Bank of Sierra Leone, reference rates as at 30 October 2026","sourceUrl":"https://bsl.gov.sl/Indicative%20Exchange%20Rates%2030-10-2026.pdf","asOf":"2026-10-30","note":"New leone (SLE) per US dollar; the World Bank series (21.30 for 2023) is older."}},"instruments":{"savings_account":{"available":true,"localName":null,"localNameEn":"Savings account","note":"Average savings rate 1.79% (July 2026); 15% withholding tax on interest.","sourceUrl":"https://bsl.gov.sl/MPR_Current.pdf"},"fdr_3m":{"available":true,"localName":null,"localNameEn":"Fixed (time) deposit (3 months)","note":"Offered by banks; no published average rate."},"fdr_1y":{"available":true,"localName":null,"localNameEn":"Fixed (time) deposit (1 year)","note":"Offered by banks; no published average rate."},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No monthly recurring deposit product with published rates was found."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No retail government savings certificate was found."},"tbill_91d":{"available":false,"localName":null,"localNameEn":"Treasury bills (91 days)","note":"Not issued since 2025; 182-day and 364-day bills are auctioned weekly and the public can apply through banks from NLe 5,000.","sourceUrl":"https://bsl.gov.sl/Announcement%20%2029%2010%202026.pdf"},"tbond_5y":{"available":false,"localName":null,"localNameEn":null,"note":"Domestic bonds are mostly 2- to 3-year issues."},"tbond_10y":{"available":false,"localName":null,"localNameEn":null,"note":"No 10-year domestic government bond."},"equity_fund":{"available":false,"localName":null,"localNameEn":null,"note":"No locally sold diversified equity fund was confirmed; the local exchange lists very few companies."},"gold":{"available":true,"localName":null,"localNameEn":"Gold","note":"Gold is sold mainly as jewellery and from artisanal mining; no official bullion or coin scheme was found."}},"institutions":{"centralBank":{"name":"Bank of Sierra Leone","url":"https://bsl.gov.sl/"},"insuranceRegulator":{"name":"Sierra Leone Insurance Commission (SLICOM)","url":"https://slicom.org.sl/"},"insuranceComplaints":{"name":"Sierra Leone Insurance Commission (SLICOM), contact","url":"https://slicom.org.sl/contact-us-v-2/","note":"No dedicated complaints page was found; complaints go to the Commission."},"pensionScheme":{"name":"National Social Security and Insurance Trust (NASSIT)","url":"https://nassit.org.sl/our-services/benefits"},"oldAgeAllowance":null,"publicHealthCover":null,"depositInsurance":null,"statistics":{"name":"Statistics Sierra Leone","url":"https://www.statistics.sl/index.php/cpi.html"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SL', 1, 'bank_deposit_avg_rate', 0.0704, NULL, 'sourced', 'World Bank WDI, deposit interest rate (FR.INR.DPST), Sierra Leone', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=SL', '2025-12-31', '7.04% for 2025 (IMF IFS via World Bank); the BSL reports a savings rate of 1.79% in mid-2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SL', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap or published credit card rate was found; the BSL reports an average lending rate of 22.75% (June 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SL', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'A Deposit Protection Fund Act exists, but the BSL 2025 Financial Stability Report says the Fund awaits enactment of a revised Act; no cover limit was published.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SL', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published rate for a monthly recurring deposit product was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SL', 1, 'equity_return_base', 0.14, NULL, 'assumption', 'Global equity in leone terms; after-tax 364-day bill about 14.4%', 'https://bsl.gov.sl/Announcement%20%2029%2010%202026.pdf', '2026-10-31', 'Sierra Leone''s exchange lists very few companies, so equity means a global index in leone terms (about 7% in dollars plus expected depreciation), kept close to the after-tax bill rate rather than above it by a full premium.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SL', 1, 'equity_return_high', 0.19, NULL, 'assumption', 'Global equity in leone terms', 'https://bsl.gov.sl/Indicative%20Exchange%20Rates%2030-10-2026.pdf', '2026-10-31', 'High case: strong global equities and faster leone depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SL', 1, 'equity_return_low', 0.08, NULL, 'assumption', 'No usable local equity index; global equity in leone terms', 'https://bsl.gov.sl/Indicative%20Exchange%20Rates%2030-10-2026.pdf', '2026-10-31', 'Low case: weak global equity returns with slower leone depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SL', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The BSL Monetary Policy Report and interest rate file publish savings and lending rates only; no 1-year time deposit rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SL', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The BSL Monetary Policy Report and interest rate file publish savings and lending rates only; no 3-month time deposit rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SL', 1, 'fixed_income_return_base', 0.13, NULL, 'assumption', 'BSL: 364-day T-bill yield 16.96% (29 Oct 2026); savings deposits 1.79% (Jul 2026); 15% withholding tax on interest (NRA)', 'https://bsl.gov.sl/Announcement%20%2029%2010%202026.pdf', '2026-10-31', 'Base case: 364-day Treasury bills (about 14.4% after 15% tax), rounded down for reinvestment risk.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SL', 1, 'fixed_income_return_high', 0.16, NULL, 'assumption', 'BSL: 364-day T-bill yield 16.96% (29 Oct 2026); savings deposits 1.79% (Jul 2026); 15% withholding tax on interest (NRA)', 'https://bsl.gov.sl/Announcement%20%2029%2010%202026.pdf', '2026-10-31', 'High case: 2- to 3-year Treasury bonds at about 18% before tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SL', 1, 'fixed_income_return_low', 0.08, NULL, 'assumption', 'BSL: 364-day T-bill yield 16.96% (29 Oct 2026); savings deposits 1.79% (Jul 2026); 15% withholding tax on interest (NRA)', 'https://bsl.gov.sl/Announcement%20%2029%2010%202026.pdf', '2026-10-31', 'Low case: bill yields fall back as inflation is brought down, and savers mix bills with low-paying deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SL', 1, 'goal_inflation_education', 0.15, NULL, 'assumption', 'Statistics Sierra Leone: education services CPI up 8.59% year on year (August 2026); inflation assumption 15%', 'https://www.statistics.sl/images/StatisticsSL/Documents/cpi/2026/August-2026-CPI_Press_Release.pdf', '2026-10-31', 'Education fees have risen more slowly than prices lately, so they are planned at the general inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SL', 1, 'goal_inflation_health', 0.165, NULL, 'assumption', 'Statistics Sierra Leone: health CPI up 11.75% year on year (August 2026); inflation assumption 15%', 'https://www.statistics.sl/images/StatisticsSL/Documents/cpi/2026/August-2026-CPI_Press_Release.pdf', '2026-10-31', 'Health costs are planned 1.5 points above general inflation, as most care is paid out of pocket and medicines are imported.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SL', 1, 'gold_return_base', 0.13, NULL, 'assumption', 'Gold trend in dollars; leone 22.81 per US dollar on 30 October 2026 (BSL)', 'https://bsl.gov.sl/Indicative%20Exchange%20Rates%2030-10-2026.pdf', '2026-10-31', 'Base case: about 4.5% dollar gold trend plus about 8% a year of leone depreciation, in line with an inflation gap of roughly 10-12 points.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SL', 1, 'gold_return_high', 0.2, NULL, 'assumption', 'Gold trend in dollars; leone 22.81 per US dollar on 30 October 2026 (BSL)', 'https://bsl.gov.sl/Indicative%20Exchange%20Rates%2030-10-2026.pdf', '2026-10-31', 'High case: strong gold years and a repeat of the sharp depreciation of 2022-2023.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SL', 1, 'gold_return_low', 0.05, NULL, 'assumption', 'Gold trend in dollars; leone 22.81 per US dollar on 30 October 2026 (BSL)', 'https://bsl.gov.sl/Indicative%20Exchange%20Rates%2030-10-2026.pdf', '2026-10-31', 'Low case: flat dollar gold with a stable leone, as in 2025-2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SL', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'The private-sector end-of-service benefit rule in the Employment Act could not be read from an official source; NASSIT pays a separate retirement gratuity of 12 months of initial pension.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SL', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No official figure for the cost of a private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SL', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No regulator or official source publishing private health insurance premiums by age was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SL', 1, 'inflation_cpi', 0.1566, NULL, 'sourced', 'Statistics Sierra Leone, CPI press release August 2026', 'https://www.statistics.sl/images/StatisticsSL/Documents/cpi/2026/August-2026-CPI_Press_Release.pdf', '2026-08-31', 'Year-on-year national CPI inflation 15.66% in August 2026 (14.89% in July), up from 4.35% in December 2025; non-food inflation 23.54%, food 5.82%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SL', 1, 'inflation_projection', 0.15, NULL, 'assumption', 'Bank of Sierra Leone Monetary Policy Report, September 2026 (inflation expected to rise toward the low 20s by end-2026); CPI 2021-2025', 'https://bsl.gov.sl/MPR_Current.pdf', '2026-10-31', 'The 2021-2025 average (about 24%) is inflated by the 2022-2023 currency crisis and no credible numeric target exists, so we plan with 15%, near current inflation, between the BSL''s near-term outlook and its single-digit medium-term objective under the IMF programme.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SL', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No regulator or official source publishing indicative term-life premiums was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SL', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No industry-wide life claim settlement ratio from the Sierra Leone Insurance Commission was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SL', 1, 'life_expectancy', 61.96, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN), Sierra Leone', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=SL', '2024-12-31', '62.0 years in 2024 (men 60.2, women 63.7); UN WPP 2024 projects 62.3 for 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SL', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":16,"men":15.2,"women":16.8},{"age":65,"total":12.7,"men":12,"women":13.3},{"age":70,"total":9.7,"men":9.2,"women":10.1},{"age":80,"total":5.4,"men":5.1,"women":5.6}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/sierra-leone/', '2026-07-01', 'Secondary source of UN WPP 2024 (medium variant) for 2026; totals are the mean of men and women except at 65, where the page gives 12.7.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SL', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age (social) pension was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SL', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age (social) pension was found; NASSIT benefits require 15 years of contributions.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SL', 1, 'oop_health_share', 0.5447, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), Sierra Leone', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=SL', '2023-12-31', '54.5% in 2023 (WHO Global Health Expenditure Database), the latest available; older than 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SL', 1, 'policy_rate', 0.1725, NULL, 'sourced', 'Bank of Sierra Leone, Monetary Policy Report September 2026 (MPC decision)', 'https://bsl.gov.sl/MPR_Current.pdf', '2026-09-24', 'The MPC raised the Monetary Policy Rate by 0.25 points to 17.25% (SLF 21.25%, SDF 11.75%) at its Q3 2026 meeting (24 September 2026 per the BSL MPC calendar), after a rise to 17% in June 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SL', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":60,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'NASSIT, Benefits and Contributions pages', 'https://nassit.org.sl/our-services/benefits', '2026-10-31', 'Mandatory for formal employees: 5% employee plus 10% employer contributions (https://nassit.org.sl/our-services/contributions). Full pension from 60 after 180 months of contributions, reduced pension at 55-59: 30% of the best 60 months'' average earnings plus 2% per extra 12 months, up to 80%, plus a retirement gratuity of 12 months'' initial pension. No automatic indexation is stated.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SL', 1, 'retirement_accumulation_return_base', 0.13, NULL, 'assumption', 'Safe rate about 13%; equity base 14%; gold base 13%', 'https://bsl.gov.sl/Announcement%20%2029%2010%202026.pdf', '2026-10-31', 'Base case: a balanced mix of Treasury bills, bonds, gold and global equity.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SL', 1, 'retirement_accumulation_return_high', 0.16, NULL, 'assumption', 'Safe rate about 13%; equity base 14%; gold base 13%', 'https://bsl.gov.sl/Announcement%20%2029%2010%202026.pdf', '2026-10-31', 'High case: a growth-leaning mix with more global equity and gold.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SL', 1, 'retirement_accumulation_return_low', 0.09, NULL, 'assumption', 'Safe rate about 13%; equity base 14%; gold base 13%', 'https://bsl.gov.sl/Announcement%20%2029%2010%202026.pdf', '2026-10-31', 'Low case: mostly bills and deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SL', 1, 'retirement_age_default', 60, NULL, 'sourced', 'NASSIT, FAQs and Benefits (old-age pension qualifying conditions)', 'https://nassit.org.sl/faqs', '2026-10-31', 'Full NASSIT old-age pension at 60, described as the National Retirement Age, after at least 180 months of contributions; a reduced pension is possible from 55.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SL', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'No official statement of the civil service retirement age was found; NASSIT''s National Retirement Age of 60 applies to its pension, not necessarily to the end of public service.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SL', 1, 'retirement_return_base', 0.12, NULL, 'assumption', 'BSL: 364-day T-bill yield 16.96% (29 Oct 2026); savings deposits 1.79% (Jul 2026); 15% withholding tax on interest (NRA)', 'https://bsl.gov.sl/Announcement%20%2029%2010%202026.pdf', '2026-10-31', 'Base case: kept below the 364-day bill yield after 15% tax (about 14.4%), allowing for yields to fall as inflation eases.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SL', 1, 'retirement_return_high', 0.15, NULL, 'assumption', 'BSL: 364-day T-bill yield 16.96% (29 Oct 2026); savings deposits 1.79% (Jul 2026); 15% withholding tax on interest (NRA)', 'https://bsl.gov.sl/Announcement%20%2029%2010%202026.pdf', '2026-10-31', 'High case: rolling 2- to 3-year Treasury bonds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SL', 1, 'retirement_return_low', 0.07, NULL, 'assumption', 'BSL: 364-day T-bill yield 16.96% (29 Oct 2026); savings deposits 1.79% (Jul 2026); 15% withholding tax on interest (NRA)', 'https://bsl.gov.sl/Announcement%20%2029%2010%202026.pdf', '2026-10-31', 'Low case: falling bill yields and low-paying deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SL', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No retail government savings certificate was found; individuals can buy Treasury bills and short bonds through commercial banks at BSL auctions.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SL', 1, 'savings_account_rate', 0.0179, NULL, 'sourced', 'Bank of Sierra Leone, Monetary Policy Report September 2026, Table 3 (interest rates)', 'https://bsl.gov.sl/MPR_Current.pdf', '2026-07-31', 'Average savings deposit rate 1.79% in July 2026, unchanged since January 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SL', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":18},{"year":2040,"value":14.7},{"year":2065,"value":8.3}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://data.worldbank.org/indicator/SP.POP.DPND.OL?locations=SL', '2025-12-31', 'Working-age people per person 65+, computed as 100 / old-age dependency ratio: 5.6 in 2025 (World Bank) gives 18.0; 6.8 in 2040 and 12.1 in 2065 (populationpyramid.net/sierra-leone/2040/ and /2065/) give 14.7 and 8.3.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SL', 1, 'tax_bank_interest', 0.15, NULL, 'sourced', 'National Revenue Authority, NRA Tax Guide 2022 (withholding tax on interest, Income Tax Act 2000 s.119)', 'https://webtestcms.nra.gov.sl/uploads/2022_NRA_TAX_GUIDE_83dc12b316.pdf', '2022-12-31', 'The NRA guide lists a 15% withholding tax on interest payments (Income Tax Act 2000, s.119). The guide is from 2022, older than 2025, and is hosted on an NRA content server; no newer official rate table was reachable, and whether the tax is final for resident individuals is not stated.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SL', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No retail government savings certificate exists. The Income Tax Act 2000 s.119(2) exempts interest on Government Development Stocks from withholding; the treatment of Treasury bill discounts for individuals was not confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SL', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The 91-day Treasury bill has not been issued since 2025 (BSL Monetary Policy Report September 2026, Table 3 shows 0). Latest auction (29 October 2026): 182-day 13.21%, 364-day 16.96%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SL', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 10-year government bond is issued in the domestic market; issuance is concentrated at 2-3 years (BSL Monetary Policy Report September 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SL', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 5-year bond auction was found; 2026 bond issues were mostly 2- to 3-year bonds priced at 18% (weighted average cost 17.69%, BSL Monetary Policy Report September 2026).', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('SM', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"SM","iso3":"SMR","nameEn":"San Marino","nameNative":"San Marino","region":"europe_central_asia","languages":["it"],"currency":{"code":"EUR","symbol":"€","decimals":2,"compact":"intl","usdRate":{"value":0.8951,"status":"sourced","sourceName":"European Central Bank, euro reference exchange rate (USD)","sourceUrl":"https://www.ecb.europa.eu/stats/policy_and_exchange_rates/euro_reference_exchange_rates/html/eurofxref-graph-usd.en.html","asOf":"2026-10-30","note":"1 euro = 1.1172 US dollars on 30 October 2026, so 0.8951 euro per dollar. San Marino uses the euro under a monetary agreement with the EU. World Bank 2025 average 0.887."}},"instruments":{"savings_account":{"available":true,"localName":"Deposito a risparmio","localNameEn":"Savings deposit","note":"No published average rate was found."},"fdr_3m":{"available":true,"localName":"Certificato di deposito","localNameEn":"Certificate of deposit (3 months)","note":"Certificates of deposit hold about a third of bank customer funding (Central Bank bulletin, June 2026).","sourceUrl":"https://www.bcsm.sm/pubblicazioni-e-statistiche/sistema-finanziario-e-dati-statistici"},"fdr_1y":{"available":true,"localName":"Certificato di deposito","localNameEn":"Certificate of deposit (1 year)","sourceUrl":"https://www.bcsm.sm/pubblicazioni-e-statistiche/sistema-finanziario-e-dati-statistici"},"dps":{"available":false,"localName":null,"localNameEn":"Monthly recurring deposit","note":"No standard recurring deposit product was found."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":"Government savings bond for individuals","note":"No standing retail government savings product was found."},"tbill_91d":{"available":false,"localName":null,"localNameEn":"Treasury bill","note":"No regular San Marino treasury bill issuance was found."},"tbond_5y":{"available":false,"localName":null,"localNameEn":"Government bond (5 years)","note":"No regular San Marino benchmark bond programme was found."},"tbond_10y":{"available":false,"localName":null,"localNameEn":"Government bond (10 years)","note":"No regular San Marino benchmark bond programme was found."},"equity_fund":{"available":true,"localName":"Fondi comuni di investimento","localNameEn":"Investment funds","note":"No local stock exchange; residents invest in euro-denominated funds through authorised banks and investment firms supervised by the Central Bank."},"gold":{"available":true,"localName":"Oro fisico (lingotti e monete)","localNameEn":"Gold bars and coins","note":"San Marino also mints its own gold coins; no restriction on buying physical gold was found."}},"institutions":{"centralBank":{"name":"Central Bank of the Republic of San Marino (BCSM)","url":"https://www.bcsm.sm/"},"insuranceRegulator":{"name":"Central Bank of the Republic of San Marino (supervision of insurers)","url":"https://www.bcsm.sm/"},"insuranceComplaints":{"name":"Central Bank of the Republic of San Marino (supervisory authority)","url":"https://www.bcsm.sm/","note":"No separate insurance ombudsman was found; complaints go first to the insurer, then to the supervisor."},"pensionScheme":{"name":"Social Security Institute (ISS), Pensions Office","url":"https://www.iss.sm/on-line/home/menudestra/come-fare-per.html"},"publicHealthCover":{"name":"Social Security Institute (ISS), national health service","url":"https://www.iss.sm/"},"depositInsurance":{"name":"Depositor Guarantee Fund (Fondo di Garanzia dei Depositanti)","url":"https://www.bcsm.sm/funzioni/altre-funzioni/fondo-di-garanzia-dei-depositanti"},"statistics":{"name":"National Statistics Office (Ufficio Nazionale di Statistica)","url":"https://www.statistica.sm/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SM', 1, 'bank_deposit_avg_rate', 0.0155, NULL, 'sourced', 'World Bank WDI FR.INR.DPST', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=SM', '2025-12-31', 'Deposit interest rate 1.55% for 2025 (IMF International Financial Statistics, Central Bank data).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SM', 1, 'credit_card_rate_cap', 0.2191, NULL, 'sourced', 'Central Bank of San Marino, anti-usury threshold rates, Circular 2026-TS4 (revolving credit and credit cards)', 'https://www.bcsm.sm/hubfs/Tassi%20Soglia%20TS/260929_Circolare_2026-TS4_con%20dicitura%20FIRMATO.pdf', '2026-10-01', 'Usury ceiling for revolving credit and credit-card credit, 1 October to 31 December 2026, for all amounts; the average effective rate is 14.33% (taken from the Italian system because San Marino has too few reports).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SM', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Depositor Guarantee Fund (Fondo di Garanzia dei Depositanti, managed at the Central Bank) guarantees depositors of banks in compulsory liquidation ''within the limits of its assets''; the Central Bank''s page gives no per-depositor amount.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SM', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No standard monthly recurring deposit product with a published rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SM', 1, 'equity_return_base', 0.055, NULL, 'assumption', 'Average deposit rate 1.55% (World Bank 2025) and ECB deposit rate 2.5%, plus an equity premium', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=SM', '2026-10-31', 'Base case for a diversified global index fund in euros, kept within 4 points of the safe euro rate (about 1.5-2.5%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SM', 1, 'equity_return_high', 0.08, NULL, 'assumption', 'Long-run global equity returns in euro terms', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/euro_reference_exchange_rates/html/eurofxref-graph-usd.en.html', '2026-10-31', 'High case near the long-run return of world shares with a stable or weaker euro.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SM', 1, 'equity_return_low', 0.025, NULL, 'assumption', 'No local stock exchange; global equity in euro terms; ECB euro reference rate', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/euro_reference_exchange_rates/html/eurofxref-graph-usd.en.html', '2026-10-31', 'San Marino has no stock market, so returns are for a global index fund in euro terms; low case for a weak decade or a strong euro.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SM', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published average rate for 1-year certificates of deposit was found in the Central Bank''s statistics; the World Bank all-deposit average for 2025 is 1.55%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SM', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published average rate for 3-month certificates of deposit or term deposits was found in the Central Bank''s statistics.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SM', 1, 'fixed_income_return_base', 0.018, NULL, 'assumption', 'Average deposit rate 1.55% (World Bank 2025); ECB deposit rate 2.5% (Sep 2026)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=SM', '2026-10-31', 'Base case: certificates of deposit and euro short-term bonds after tax, a little above the 2025 average deposit rate now that ECB rates have risen to 2.5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SM', 1, 'fixed_income_return_high', 0.03, NULL, 'assumption', 'ECB key rates (deposit facility 2.5%, Sep 2026)', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.en.html', '2026-10-31', 'High case: longer certificates of deposit and euro government bonds if rates keep rising.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SM', 1, 'fixed_income_return_low', 0.01, NULL, 'assumption', 'Average deposit rate 1.55% (World Bank 2025)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=SM', '2026-10-31', 'Low case: mostly sight deposits after tax if euro rates fall again.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SM', 1, 'goal_inflation_education', 0.025, NULL, 'assumption', 'Ufficio Nazionale di Statistica, CPI by group: education services 0% year on year (2026)', 'https://www.statistica.sm/pub1/StatisticaSM/Dati-statistici/Prezzi-e-retribuzioni/Prezzi.html', '2026-10-31', 'Local education prices were flat in 2026, but university study is mostly abroad (Italy), so we plan with the 2% projection plus half a point.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SM', 1, 'goal_inflation_health', 0.03, NULL, 'assumption', 'Ufficio Nazionale di Statistica, CPI by group: health +1.31% year on year (July 2026)', 'https://www.statistica.sm/pub1/StatisticaSM/Dati-statistici/Prezzi-e-retribuzioni/Prezzi.html', '2026-10-31', 'Measured health prices rise slowly because the ISS covers most care, but private medical costs usually outpace the 2% projection, so one point is added.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SM', 1, 'gold_return_base', 0.045, NULL, 'assumption', 'ECB euro reference exchange rate; long-run dollar gold trend', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/euro_reference_exchange_rates/html/eurofxref-graph-usd.en.html', '2026-10-31', 'Long-run dollar gold trend of about 4-5% with no expected trend in the euro against the dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SM', 1, 'gold_return_high', 0.08, NULL, 'assumption', 'ECB euro reference exchange rate (USD)', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/euro_reference_exchange_rates/html/eurofxref-graph-usd.en.html', '2026-10-31', 'High case: strong dollar gold and a weaker euro.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SM', 1, 'gold_return_low', 0.01, NULL, 'assumption', 'ECB euro reference exchange rate (USD)', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/euro_reference_exchange_rates/html/eurofxref-graph-usd.en.html', '2026-10-31', 'Low case: weak dollar gold price and a stronger euro.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SM', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No statutory end-of-service payment rule for private employees could be read from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SM', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'Hospital care for residents is provided by the Social Security Institute (ISS) State Hospital; no figure for the out-of-pocket cost of a private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SM', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premium table per 100,000 euro of cover was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SM', 1, 'inflation_cpi', 0.0202, NULL, 'sourced', 'Ufficio Nazionale di Statistica, consumer price index (FOI), year-on-year change', 'https://www.statistica.sm/pub1/StatisticaSM/Dati-statistici/Prezzi-e-retribuzioni/Prezzi.html', '2026-07-31', '2.02% in July 2026 (1.11% in June, 1.73% in May), from the file ''Variazione Tendenziale dal 2026 Ecoicop2''. World Bank 2025 average 2.3%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SM', 1, 'inflation_projection', 0.02, NULL, 'assumption', 'ECB 2% inflation target; San Marino CPI 0.8-2.3% in 2026, 2.3% in 2025 (World Bank)', 'https://www.statistica.sm/pub1/StatisticaSM/Dati-statistici/Prezzi-e-retribuzioni/Prezzi.html', '2026-10-31', 'San Marino uses the euro and its inflation tracks the euro area (and Italy), so the ECB''s 2% target is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SM', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No regulator or official term-life premium table per 1,000 euro of cover was found for San Marino.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SM', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Central Bank supervises insurers but publishes no industry-wide life claim settlement ratio.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SM', 1, 'life_expectancy', 85.82, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=SM', '2024-12-31', 'Men 84.3, women 87.2 (2024, older than 2025); UN WPP via georank.org gives 86.0 for 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SM', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":27.4,"men":26,"women":28.7},{"age":65,"total":22.9,"men":21.5,"women":24.2},{"age":70,"total":18.5,"men":17.2,"women":19.7},{"age":80,"total":10.7,"men":9.7,"women":11.5}]}', 'sourced', 'UN World Population Prospects via georank.org (life expectancy by current age, 2026)', 'https://georank.org/life-expectancy/san-marino', '2026-01-01', 'Secondary source of UN WPP figures for 2026; remaining years are the published expected age at death minus current age. The UN estimates for a population of about 34,000 are modelled and uncertain. Data retrieved by georank.org on 8 July 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SM', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'No eligibility rules for a non-contributory old-age pension could be confirmed from ISS or government pages.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SM', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'No current amount of a non-contributory old-age (social) pension could be read; the ISS pages found describe only social invalidity pensions and contributory pensions.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SM', 1, 'oop_health_share', 0.1309, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=SM', '2023-12-31', 'Latest available year is 2023 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SM', 1, 'policy_rate', 0.025, NULL, 'sourced', 'European Central Bank, key ECB interest rates (deposit facility)', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.en.html', '2026-09-16', 'San Marino has no monetary policy of its own; it uses the euro, so the ECB deposit facility rate (2.50% from 16 September 2026; main refinancing rate 2.65%) applies.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SM', 1, 'public_pension_scheme', NULL, NULL, 'missing', '', '', '2026-10-31', 'The compulsory ISS pension pays an old-age pension from 66 with 20 years of contributions (iss.sm, ''come fare per''), plus the FondISS supplementary pension fund since 2011, but its indexation and tax treatment could not be confirmed, so the scheme is not filled in.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SM', 1, 'retirement_accumulation_return_base', 0.037, NULL, 'assumption', 'Fixed income base 1.8%; global equity base 5.5%', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=SM', '2026-10-31', 'Base case: roughly half global equity in euros and half deposits and certificates of deposit.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SM', 1, 'retirement_accumulation_return_high', 0.055, NULL, 'assumption', 'Fixed income high 3%; global equity high 8%', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.en.html', '2026-10-31', 'High case for a growth-leaning balanced mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SM', 1, 'retirement_accumulation_return_low', 0.02, NULL, 'assumption', 'Fixed income low 1%; global equity low 2.5%', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=SM', '2026-10-31', 'Low case for a balanced mix if world shares lag.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SM', 1, 'retirement_age_default', 66, NULL, 'sourced', 'Social Security Institute (ISS), how to apply for the old-age and seniority pension', 'https://www.iss.sm/on-line/home/menudestra/come-fare-per.html', '2026-10-31', 'Old-age pension from 66 (since 1 January 2021) with at least 20 years of contributions, same for men and women; seniority pension from 60 with 40 years. Page read October 2026; no later reform was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SM', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'No separate retirement age for public employees was found; they appear to be covered by the same ISS pension rules (old-age pension at 66).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SM', 1, 'retirement_return_base', 0.015, NULL, 'assumption', 'Average deposit rate 1.55% (World Bank 2025)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=SM', '2026-10-31', 'Base case at the average deposit rate, since no published 1-year deposit or bill rate could be found to set a higher cap.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SM', 1, 'retirement_return_high', 0.025, NULL, 'assumption', 'ECB deposit facility rate 2.5% (Sep 2026)', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.en.html', '2026-10-31', 'High case: longer certificates of deposit and euro bonds near the ECB rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SM', 1, 'retirement_return_low', 0.008, NULL, 'assumption', 'Average deposit rate 1.55% (World Bank 2025)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=SM', '2026-10-31', 'Low case: mostly sight deposits after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SM', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate or retail savings bond for individuals was found; San Marino borrows through occasional public debt issues rather than a standing retail programme.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SM', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Central Bank (BCSM) publishes deposit volumes in its quarterly bulletin but no average rate on savings accounts was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SM', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":2.81},{"year":2040,"value":1.59},{"year":2065,"value":1.7}]}', 'sourced', 'UN World Population Prospects via georank.org (demographics: old-age dependency and age-group forecasts)', 'https://georank.org/demographics/san-marino', '2025-12-31', '2025: 100 / old-age dependency ratio 35.6 (also World Bank 2025). 2040 and 2065 are computed from the page''s UN forecast shares of 15-64 and 65+ (55.0% / 34.7% and 55.8% / 32.9%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SM', 1, 'tax_bank_interest', NULL, NULL, 'missing', '', '', '2026-10-31', 'The withholding rate on bank interest under the general income tax (IGR) law could not be read from an official source; PwC Tax Summaries does not cover San Marino.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SM', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No retail government savings product was found, and the tax treatment of government bond interest could not be read from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SM', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No regular treasury bill issuance or published 3-month yield for San Marino was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SM', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'San Marino has no regular benchmark bond programme; no published 10-year government yield was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SM', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'San Marino has no regular benchmark bond programme; no published 5-year government yield was found.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('SN', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"SN","iso3":"SEN","nameEn":"Senegal","nameNative":"Senegaal","region":"sub_saharan_africa","languages":["wo","fr","ff","srr"],"currency":{"code":"XOF","symbol":"F CFA","decimals":0,"compact":"intl","usdRate":{"value":581.93,"status":"sourced","sourceName":"World Bank WDI, official exchange rate (PA.NUS.FCRF), Senegal, 2025 average","sourceUrl":"https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=SN","asOf":"2025-12-31","note":"581.93 CFA francs per dollar on average in 2025; the BCEAO reference rate was 584.84 on 2 November 2026. The franc is fixed at 655.957 per euro."}},"instruments":{"savings_account":{"available":true,"localName":"Compte d''épargne","localNameEn":"Savings account","note":"Banks offer savings accounts; no average rate is published."},"fdr_3m":{"available":true,"localName":"Dépôt à terme (3 mois)","localNameEn":"Term deposit (3 months)","note":"Minimum term-deposit rates of 0-5% declared to the BCEAO (first half 2026, median 3.5%).","sourceUrl":"https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf"},"fdr_1y":{"available":true,"localName":"Dépôt à terme (1 an)","localNameEn":"Term deposit (1 year)","note":"Maximum term-deposit rates of 3.5-7.51% declared to the BCEAO (first half 2026); no 1-year average is published.","sourceUrl":"https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf"},"dps":{"available":true,"localName":"Épargne contractuelle","localNameEn":"Contractual savings plan","note":"Contractual savings at about 3.50% (BCEAO bank-conditions survey, first half 2026).","sourceUrl":"https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf"},"sanchayapatra_5y":{"available":true,"localName":"Emprunt obligataire de l''État par appel public à l''épargne","localNameEn":"Government bond sold to the public","note":"State bonds offered to individuals through licensed brokers and banks; the rate of a current issue could not be confirmed."},"tbill_91d":{"available":true,"localName":"Bon assimilable du Trésor (BAT)","localNameEn":"Treasury bill","note":"Auctioned through UMOA-Titres to banks and primary dealers; individuals buy through a bank or broker.","sourceUrl":"https://www.umoatitres.org/wp-content/uploads/2026/10/COURBES-DE-TAUX.au_.23.10.2026.xlsx"},"tbond_5y":{"available":true,"localName":"Obligation assimilable du Trésor (OAT, 5 ans)","localNameEn":"Treasury bond (5 years)","note":"Auctioned through UMOA-Titres; individuals buy through a bank or broker.","sourceUrl":"https://www.umoatitres.org/wp-content/uploads/2026/10/COURBES-DE-TAUX.au_.23.10.2026.xlsx"},"tbond_10y":{"available":true,"localName":"Obligation assimilable du Trésor (OAT, 10 ans)","localNameEn":"Treasury bond (10 years)","note":"Senegal''s yield curve extends to 15 years; individuals buy through a bank or broker.","sourceUrl":"https://www.umoatitres.org/wp-content/uploads/2026/10/COURBES-DE-TAUX.au_.23.10.2026.xlsx"},"equity_fund":{"available":true,"localName":"OPCVM (FCP ou SICAV)","localNameEn":"Mutual fund","note":"Funds regulated by the regional financial markets authority invest in shares listed on the regional exchange (BRVM)."},"gold":{"available":true,"localName":"Or","localNameEn":"Gold","note":"Gold is sold mainly as jewellery; no official bullion or coin scheme was found."}},"institutions":{"centralBank":{"name":"Banque Centrale des États de l''Afrique de l''Ouest (BCEAO)","url":"https://www.bceao.int/"},"insuranceRegulator":{"name":"Commission Régionale de Contrôle des Assurances (CIMA)","url":"https://cima-afrique.org/","note":"Regional insurance regulator for the CIMA member states, Senegal included."},"insuranceComplaints":{"name":"CIMA policyholder requests and complaints form","url":"https://cima-afrique.org/faites-votre-requetes-ici-2/"},"pensionScheme":{"name":"Institution de Prévoyance Retraite du Sénégal (IPRES)","url":"https://www.ipres.sn/","note":"The site could not be reached when checked."},"oldAgeAllowance":null,"publicHealthCover":{"name":"Agence de la Couverture Maladie Universelle (CMU), including Plan Sésame for people aged 60 and over","url":"https://www.agencecmu.sn/","note":"The site could not be reached when checked."},"depositInsurance":{"name":"Fonds de Garantie des Dépôts et de Résolution dans l''UMOA (FGDR-UMOA)","url":"https://www.fgd-umoa.org/"},"statistics":{"name":"Agence nationale de la Statistique et de la Démographie (ANSD)","url":"https://www.ansd.sn/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SN', 1, 'bank_deposit_avg_rate', 0.0515, NULL, 'sourced', 'BCEAO, Note de conjoncture économique des pays de l''UEMOA, September 2026 (bank deposit rates, July 2026)', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-07-31', 'Average deposit rate across UMOA banks, 5.15% in July 2026; Senegal''s rose 0.26 points in the month, but the BCEAO does not publish the country level in this note. The World Bank series for Senegal stops in 2016 (6.9%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SN', 1, 'credit_card_rate_cap', 0.14, NULL, 'sourced', 'BCEAO, conditions débitrices of UMOA credit institutions, first half 2026 (Senegal)', 'https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf', '2026-06-30', 'Median maximum lending rate (taux débiteur maximum) declared by Senegal''s 27 banks for the first half of 2026 (range 7-14%); it applies to all bank credit, including cards. No card-specific rate is published.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SN', 1, 'deposit_insurance_limit', 1400000, NULL, 'sourced', 'UMOA Council of Ministers, Decision of 30 June 2017 on FGD-UMOA contribution rates and compensation ceilings', 'https://www.fgd-umoa.org/wp-content/uploads/2024/10/Decision-du-CM-relative-aux-taux-de-contribution-et-aux-plafonds-d-indemnistation-2-1.pdf', '2017-06-30', 'Deposits are guaranteed up to 1,400,000 FCFA per depositor per bank (300,000 FCFA at a microfinance institution) by the regional deposit guarantee fund; the decision dates from 2017 (older than 2025), and no later change was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SN', 1, 'dps_rate', 0.035, NULL, 'sourced', 'BCEAO, conditions créditrices of UMOA credit institutions, first half 2026 (Senegal) (épargne contractuelle)', 'https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf', '2026-06-30', 'Median rate on contractual savings plans declared by Senegalese credit institutions in the first half of 2026; most declare 3.50% (range about 3.5-4.75%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SN', 1, 'equity_return_base', 0.08, NULL, 'assumption', 'BCEAO monthly economic note, September 2026; after-tax deposit rate about 4.7% (5.15% less 8% tax)', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-10-31', 'Base case: about 3.3 points above the after-tax deposit rate, within the 4-point cap; Senegal shares trade on the regional BRVM, whose 10-year record is mixed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SN', 1, 'equity_return_high', 0.12, NULL, 'assumption', 'BCEAO monthly economic note, September 2026 (regional stock exchange BRVM)', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-10-31', 'High case: the BRVM repeats a strong decade like 2023-2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SN', 1, 'equity_return_low', 0.04, NULL, 'assumption', 'BCEAO monthly economic note, September 2026 (regional stock exchange BRVM); UMOA-Titres Senegal yield curve', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-10-31', 'Low case: regional (BRVM) equities return about the bank deposit rate, as in their weak 2016-2020 years.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SN', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The BCEAO bank-conditions survey gives only minimum (median 3.5%) and maximum (median about 6.5%, range 3.5-7.51%) term-deposit rates per institution in Senegal for the first half of 2026, not a 1-year rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SN', 1, 'fdr_3m_rate', 0.035, NULL, 'sourced', 'BCEAO, conditions créditrices of UMOA credit institutions, first half 2026 (Senegal)', 'https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf', '2026-06-30', 'Median of the minimum term-deposit rates (taux DAT minimum) declared to the BCEAO by the 29 Senegalese credit institutions that reported one, range 0-5%; the minimum usually applies to small, short deposits. Not a tenor-specific average.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SN', 1, 'fixed_income_return_base', 0.045, NULL, 'assumption', 'BCEAO: UMOA average deposit rate 5.15% (July 2026) less 8% tax; Senegal 1-year bill 8.15%', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-10-31', 'Base case: term deposits at about the Union average rate after tax (about 4.7%), rounded down.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SN', 1, 'fixed_income_return_high', 0.065, NULL, 'assumption', 'UMOA-Titres (UEMOA public securities agency), Senegal yield curve (zero coupon) at 23 October 2026', 'https://www.umoatitres.org/wp-content/uploads/2026/10/COURBES-DE-TAUX.au_.23.10.2026.xlsx', '2026-10-31', 'High case: 3-5 year Treasury bonds at about 8%, less 6-13% tax and an allowance for Senegal''s higher credit risk.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SN', 1, 'fixed_income_return_low', 0.03, NULL, 'assumption', 'BCEAO, conditions créditrices of UMOA credit institutions, first half 2026 (Senegal)', 'https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf', '2026-10-31', 'Low case: small term deposits or contractual savings at about 3.5%, less the 8% tax on interest.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SN', 1, 'goal_inflation_education', 0.04, NULL, 'assumption', 'ANSD IHPC; 2% planning inflation', 'https://www.ansd.sn/sites/default/files/2026-10/IHPC_base2023_Sept%2026_VF_Rev.pdf', '2026-10-31', 'No education price trend was read beyond the monthly note; private school fees usually rise faster than general prices, so 2 points above the 2% inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SN', 1, 'goal_inflation_health', 0.035, NULL, 'assumption', 'ANSD IHPC September 2026: health prices +2.0% a year; 2% planning inflation', 'https://www.ansd.sn/sites/default/files/2026-10/IHPC_base2023_Sept%2026_VF_Rev.pdf', '2026-10-31', 'Health prices rose 2.0% in the past year, but private and imported care tends to rise faster, so 1.5 points above the 2% inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SN', 1, 'gold_return_base', 0.045, NULL, 'assumption', 'BCEAO reference rates (CFA franc pegged at 655.957 per euro); dollar gold trend', 'https://www.bceao.int/fr/cours/cours-de-reference-des-principales-devises-contre-Franc-CFA', '2026-10-31', 'Base case: the long-run dollar gold trend of about 4% a year plus a small allowance for the euro-pegged franc weakening against the dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SN', 1, 'gold_return_high', 0.08, NULL, 'assumption', 'BCEAO reference rates (CFA franc pegged at 655.957 per euro)', 'https://www.bceao.int/fr/cours/cours-de-reference-des-principales-devises-contre-Franc-CFA', '2026-10-31', 'High case: strong gold years such as 2024-2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SN', 1, 'gold_return_low', 0, NULL, 'assumption', 'BCEAO reference rates (CFA franc pegged at 655.957 per euro); dollar gold trend', 'https://www.bceao.int/fr/cours/cours-de-reference-des-principales-devises-contre-Franc-CFA', '2026-10-31', 'Low case: flat gold in euro terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SN', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No official text on a statutory end-of-service or retirement indemnity for private employees could be read (the Labour Code and the interprofessional collective agreement were not reached), so the rule is unconfirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SN', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a major private hospital stay in Senegal was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SN', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premiums by age were found from a public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SN', 1, 'inflation_cpi', 0.01, NULL, 'sourced', 'Agence nationale de la Statistique et de la Démographie (ANSD), Indice harmonisé des prix à la consommation, September 2026', 'https://www.ansd.sn/sites/default/files/2026-10/IHPC_base2023_Sept%2026_VF_Rev.pdf', '2026-09-30', 'Consumer prices up 1.0% year on year in September 2026 (1.2% in August per the BCEAO); core inflation also 1.0%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SN', 1, 'inflation_projection', 0.02, NULL, 'assumption', 'BCEAO inflation target band of 1-3%; CFA franc pegged to the euro', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-10-31', 'Senegal''s inflation has stayed low under the euro peg (1.0% in September 2026), so the 2% centre of the BCEAO''s 1-3% target band is used for long-range plans.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SN', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Temporary death cover is sold under the CIMA code, but no published premium rates per 1,000 FCFA of cover by age were found from a public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SN', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'CIMA (the regional insurance regulator) and Senegal''s insurance directorate publish no industry-wide life claim settlement ratio that could be found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SN', 1, 'life_expectancy', 68.924, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN), Senegal', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=SN', '2024-12-31', '68.9 years in 2024 (men 67.0, women 71.0).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SN', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":17.4,"men":16.4,"women":18.3},{"age":65,"total":13.7,"men":12.9,"women":14.4},{"age":70,"total":10.4,"men":9.8,"women":10.9},{"age":80,"total":5.3,"men":5,"women":5.5}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/senegal/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026; the both-sexes figure at 65 is published, the others are the mean of men and women.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SN', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age cash pension was found (see old_age_allowance_monthly).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SN', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age cash pension was found; people aged 60 and over get free care in public health facilities under Plan Sésame (US SSA 2019), which is not a cash benefit, and family security grants go to poor households, not to older people as such.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SN', 1, 'oop_health_share', 0.4433, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), Senegal', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=SN', '2023-12-31', '44.3% in 2023 (WHO Global Health Expenditure Database via the World Bank), the latest available; older than 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SN', 1, 'policy_rate', 0.03, NULL, 'sourced', 'BCEAO, Note de conjoncture économique des pays de l''UEMOA, September 2026 (Monetary Policy Committee of 9 September 2026)', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-09-09', 'Main policy rate held at 3.00% (marginal lending facility 5.00%) by the Monetary Policy Committee on 9 September 2026; common to all eight UMOA countries.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SN', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":60,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'US Social Security Administration, Social Security Programs Throughout the World: Africa, 2019, Senegal (archived copy)', 'https://web.archive.org/web/20260607223054/https://www.ssa.gov/policy/docs/progdesc/ssptw/2018-2019/africa/senegal.html', '2019-07-01', 'Compulsory IPRES points scheme for private-sector employees and non-civil-servant public employees: pension = points x point value set each year by IPRES, payable at 55-60 depending on employment, with at least 400 points (early from 53); a lump sum below 400 points. Point values are set by IPRES rather than indexed automatically, so inflationLinked is false. Civil servants have a separate scheme. 2019 edition, older than 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SN', 1, 'retirement_accumulation_return_base', 0.06, NULL, 'assumption', 'UMOA-Titres Senegal yield curve; regional equity and gold assumptions above', 'https://www.umoatitres.org/wp-content/uploads/2026/10/COURBES-DE-TAUX.au_.23.10.2026.xlsx', '2026-10-31', 'Base case: a balanced mix of deposits or Treasury bonds, regional equity funds and some gold.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SN', 1, 'retirement_accumulation_return_high', 0.08, NULL, 'assumption', 'UMOA-Titres Senegal yield curve; regional equity and gold assumptions above', 'https://www.umoatitres.org/wp-content/uploads/2026/10/COURBES-DE-TAUX.au_.23.10.2026.xlsx', '2026-10-31', 'High case: a growth-leaning mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SN', 1, 'retirement_accumulation_return_low', 0.035, NULL, 'assumption', 'BCEAO, conditions créditrices of UMOA credit institutions, first half 2026 (Senegal)', 'https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf', '2026-10-31', 'Low case: a mix earning about after-tax deposit rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SN', 1, 'retirement_age_default', 60, NULL, 'sourced', 'US Social Security Administration, Social Security Programs Throughout the World: Africa, 2019, Senegal (archived copy)', 'https://web.archive.org/web/20260607223054/https://www.ssa.gov/policy/docs/progdesc/ssptw/2018-2019/africa/senegal.html', '2019-07-01', 'IPRES general-scheme pension at 55 to 60 depending on the type of employment (55 for arduous work), with at least 400 points; 60 is the normal age for most employees, early pension from 53 with a 5% cut per year. Secondary source read through the Internet Archive (ssa.gov and the IPRES site could not be reached); 2019 edition, older than 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SN', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'Civil servants have a separate scheme (Fonds National de Retraite); their retirement age could not be confirmed from an official source (the fund''s site could not be reached).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SN', 1, 'retirement_return_base', 0.04, NULL, 'assumption', 'BCEAO: UMOA average deposit rate 5.15% (July 2026) less 8% tax = about 4.7%', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-10-31', 'Base case kept below the after-tax deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SN', 1, 'retirement_return_high', 0.055, NULL, 'assumption', 'UMOA-Titres (UEMOA public securities agency), Senegal yield curve (zero coupon) at 23 October 2026', 'https://www.umoatitres.org/wp-content/uploads/2026/10/COURBES-DE-TAUX.au_.23.10.2026.xlsx', '2026-10-31', 'High case: part of the money in Treasury bonds or public bond offers held to maturity.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SN', 1, 'retirement_return_low', 0.03, NULL, 'assumption', 'BCEAO, conditions créditrices of UMOA credit institutions, first half 2026 (Senegal)', 'https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf', '2026-10-31', 'Low case: small term deposits or contractual savings at about 3.5%, less the 8% tax on interest.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SN', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The State sells bonds to the public by public offering (appel public à l''épargne), but the rate of a current issue could not be confirmed from an official page.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SN', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No average rate on ordinary savings accounts in Senegal was found; the BCEAO bank-conditions survey (first half 2026) lists term-deposit and contractual-savings rates only.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SN', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":16.07},{"year":2040,"value":13.51},{"year":2065,"value":6.85}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://data.worldbank.org/indicator/SP.POP.DPND.OL?locations=SN', '2025-12-31', 'Working-age people per person 65+ = 100 / old-age dependency ratio. Dependency ratios used: 6.22 per 100 in 2025 (World Bank), 7.4 in 2040 (populationpyramid.net/senegal/2040/) and 14.6 in 2065 (populationpyramid.net/senegal/2065/, UN WPP 2024 medium variant).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SN', 1, 'tax_bank_interest', 0.08, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Senegal, corporate withholding taxes (reviewed 7 August 2026)', 'https://taxsummaries.pwc.com/senegal/corporate/withholding-taxes', '2026-08-07', '8% withholding on interest from deposits and bank accounts; 16% on other interest such as loans.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SN', 1, 'tax_sanchayapatra_profit', 0.06, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Senegal, corporate withholding taxes (reviewed 7 August 2026)', 'https://taxsummaries.pwc.com/senegal/corporate/withholding-taxes', '2026-08-07', 'Bond interest is taxed at 6% for bonds of 5 years or more and 13% under 5 years; individual public bond issues may carry their own exemptions, which were not checked.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SN', 1, 'tbill_91d_rate', 0.0627, NULL, 'sourced', 'UMOA-Titres (UEMOA public securities agency), Senegal yield curve (zero coupon) at 23 October 2026', 'https://www.umoatitres.org/wp-content/uploads/2026/10/COURBES-DE-TAUX.au_.23.10.2026.xlsx', '2026-10-23', '3-month zero-coupon rate 6.27% (6.95% after smoothing); 1-year 8.15%. Yields are high because of Senegal''s debt difficulties since 2024.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SN', 1, 'tbond_10y_rate', 0.0775, NULL, 'sourced', 'UMOA-Titres (UEMOA public securities agency), Senegal yield curve (zero coupon) at 23 October 2026', 'https://www.umoatitres.org/wp-content/uploads/2026/10/COURBES-DE-TAUX.au_.23.10.2026.xlsx', '2026-10-23', '10-year zero-coupon rate 7.75% (7.27% after smoothing).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SN', 1, 'tbond_5y_rate', 0.0829, NULL, 'sourced', 'UMOA-Titres (UEMOA public securities agency), Senegal yield curve (zero coupon) at 23 October 2026', 'https://www.umoatitres.org/wp-content/uploads/2026/10/COURBES-DE-TAUX.au_.23.10.2026.xlsx', '2026-10-23', '5-year zero-coupon rate 8.29% (8.23% after smoothing).', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('SO', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"SO","iso3":"SOM","nameEn":"Somalia","nameNative":"Soomaaliya","region":"sub_saharan_africa","languages":["so","ar","en"],"currency":{"code":"USD","symbol":"$","decimals":2,"compact":"intl","usdRate":{"value":1,"status":"sourced","sourceName":"Central Bank of Somalia, Spillover Effects of Foreign Aid Reductions on Somalia''s Macro-Financial Stability (October 2026)","sourceUrl":"https://centralbank.gov.so/wp-content/uploads/2026/10/Spillover-Effects-of-Foreign-Aid-Reductions-on-Somalias-Macro-Financial-Stability.pdf","asOf":"2026-10-05","note":"Somalia is fully dollarized: the US dollar is the medium of exchange, unit of account and store of value for all formal transactions, bank deposits and credit, while the Somali shilling (SOS) survives only for small informal payments. Plans are therefore made in US dollars."}},"instruments":{"savings_account":{"available":true,"localName":null,"localNameEn":"Savings account (Islamic, in US dollars)","note":"Banks offer Shariah-compliant dollar savings accounts; returns are not published."},"fdr_3m":{"available":false,"localName":null,"localNameEn":null,"note":"No standard 3-month term deposit with published returns was found."},"fdr_1y":{"available":false,"localName":null,"localNameEn":null,"note":"No standard 1-year term deposit with published returns was found."},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No monthly recurring deposit product was found."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate."},"tbill_91d":{"available":false,"localName":null,"localNameEn":null,"note":"No Treasury bills are issued."},"tbond_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No domestic government bonds."},"tbond_10y":{"available":false,"localName":null,"localNameEn":null,"note":"No domestic government bonds."},"equity_fund":{"available":false,"localName":null,"localNameEn":null,"note":"No locally sold diversified equity fund was found; investors can only use foreign funds."},"gold":{"available":true,"localName":"Dahab","localNameEn":"Gold","note":"Gold is sold mainly as jewellery; no official bullion or coin scheme was found."}},"institutions":{"centralBank":{"name":"Central Bank of Somalia","url":"https://centralbank.gov.so/"},"insuranceRegulator":{"name":"Central Bank of Somalia (takaful regulator under the Takaful Act, Law No. 39 of 2025)","url":"https://centralbank.gov.so/wp-content/uploads/2026/10/Takaful-Act.-Law-No-39_2025.pdf"},"insuranceComplaints":null,"pensionScheme":null,"oldAgeAllowance":null,"publicHealthCover":null,"depositInsurance":null,"statistics":{"name":"Somalia National Bureau of Statistics","url":"https://nbs.gov.so/consumer-price-index-cpi-sept-2026/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SO', 1, 'bank_deposit_avg_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No recent average deposit return is published; the World Bank FR.INR.DPST series for Somalia ends in 1989.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SO', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No credit card rate cap or published card rate was found; Islamic banks do not charge interest.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SO', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No deposit insurance scheme or cover limit was found in Central Bank of Somalia publications.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SO', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No monthly recurring deposit product with a published return was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SO', 1, 'equity_return_base', 0.06, NULL, 'assumption', 'Global equity in US dollars; assumed safe dollar return about 2.5%', 'https://centralbank.gov.so/wp-content/uploads/2026/10/Spillover-Effects-of-Foreign-Aid-Reductions-on-Somalias-Macro-Financial-Stability.pdf', '2026-10-31', 'No local index with a record exists, so equity means a global index fund in dollars, held 3.5 points above the assumed safe dollar return.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SO', 1, 'equity_return_high', 0.085, NULL, 'assumption', 'Global equity history in US dollars', 'https://centralbank.gov.so/wp-content/uploads/2026/10/Spillover-Effects-of-Foreign-Aid-Reductions-on-Somalias-Macro-Financial-Stability.pdf', '2026-10-31', 'High case: global equities repeat their long-run dollar returns.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SO', 1, 'equity_return_low', 0.03, NULL, 'assumption', 'No local stock index with a usable record; global equity in US dollars', 'https://centralbank.gov.so/wp-content/uploads/2026/10/Spillover-Effects-of-Foreign-Aid-Reductions-on-Somalias-Macro-Financial-Stability.pdf', '2026-10-31', 'Low case: a weak decade for global equities, earned in dollars.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SO', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published return on 1-year Islamic investment deposits was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SO', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published return on 3-month Islamic investment deposits was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SO', 1, 'fixed_income_return_base', 0.025, NULL, 'assumption', 'No published local deposit returns; dollarized economy', 'https://centralbank.gov.so/wp-content/uploads/2026/10/Spillover-Effects-of-Foreign-Aid-Reductions-on-Somalias-Macro-Financial-Stability.pdf', '2026-10-31', 'Base case: a modest dollar return on profit-sharing deposits. Somalia is fully dollarized and has no government securities market, so safe returns are dollar returns on bank deposits held abroad or in local Islamic accounts.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SO', 1, 'fixed_income_return_high', 0.04, NULL, 'assumption', 'No published local deposit returns; dollarized economy', 'https://centralbank.gov.so/wp-content/uploads/2026/10/Spillover-Effects-of-Foreign-Aid-Reductions-on-Somalias-Macro-Financial-Stability.pdf', '2026-10-31', 'High case: dollar term investment accounts or short dollar bonds held abroad.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SO', 1, 'fixed_income_return_low', 0.01, NULL, 'assumption', 'No published local deposit returns; dollarized economy', 'https://centralbank.gov.so/wp-content/uploads/2026/10/Spillover-Effects-of-Foreign-Aid-Reductions-on-Somalias-Macro-Financial-Stability.pdf', '2026-10-31', 'Low case: dollar savings earning little. Somalia is fully dollarized and has no government securities market, so safe returns are dollar returns on bank deposits held abroad or in local Islamic accounts.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SO', 1, 'goal_inflation_education', 0.065, NULL, 'assumption', 'SNBS CPI September 2026: education services up 11.5% over twelve months; inflation assumption 5%', 'https://nbs.gov.so/wp-content/uploads/2026/10/CPI-2026_September.pdf', '2026-10-31', 'Education costs are planned 1.5 points above general inflation as school fees have recently risen much faster than the CPI.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SO', 1, 'goal_inflation_health', 0.065, NULL, 'assumption', 'SNBS CPI September 2026: health prices up 9.6% over twelve months; inflation assumption 5%', 'https://nbs.gov.so/wp-content/uploads/2026/10/CPI-2026_September.pdf', '2026-10-31', 'Health costs are planned 1.5 points above general inflation as they have recently risen faster than the CPI.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SO', 1, 'gold_return_base', 0.045, NULL, 'assumption', 'Gold trend in US dollars; economy fully dollarized', 'https://centralbank.gov.so/wp-content/uploads/2026/10/Spillover-Effects-of-Foreign-Aid-Reductions-on-Somalias-Macro-Financial-Stability.pdf', '2026-10-31', 'Base case: the long-run dollar gold trend of about 4.5%, with no currency effect because savings are held in dollars.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SO', 1, 'gold_return_high', 0.08, NULL, 'assumption', 'Gold trend in US dollars; economy fully dollarized', 'https://centralbank.gov.so/wp-content/uploads/2026/10/Spillover-Effects-of-Foreign-Aid-Reductions-on-Somalias-Macro-Financial-Stability.pdf', '2026-10-31', 'High case: strong gold years.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SO', 1, 'gold_return_low', 0, NULL, 'assumption', 'Gold trend in US dollars; economy fully dollarized', 'https://centralbank.gov.so/wp-content/uploads/2026/10/Spillover-Effects-of-Foreign-Aid-Reductions-on-Somalias-Macro-Financial-Stability.pdf', '2026-10-31', 'Low case: flat dollar gold prices.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SO', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'The private-sector end-of-service rule in the Labour Code could not be read from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SO', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No official figure for the cost of a private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SO', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published health takaful premium data was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SO', 1, 'inflation_cpi', 0.068, NULL, 'sourced', 'Somalia National Bureau of Statistics, Consumer Price Index September 2026', 'https://nbs.gov.so/wp-content/uploads/2026/10/CPI-2026_September.pdf', '2026-09-30', 'Prices rose 6.8% over the twelve months to September 2026 (6.9% in August, 6.7% in July); the CPI tracks prices in a dollarized economy.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SO', 1, 'inflation_projection', 0.05, NULL, 'assumption', 'SNBS CPI (6.7-6.9% in mid-2026); full dollarization (Central Bank of Somalia, October 2026)', 'https://nbs.gov.so/wp-content/uploads/2026/10/CPI-2026_September.pdf', '2026-10-31', 'With no inflation target and prices set in US dollars, we plan with 5%, below the current oil- and import-driven rate but above US inflation to allow for import costs and supply shocks.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SO', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published term life or family takaful premium data was found; the takaful market is nascent.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SO', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Takaful is nascent (Central Bank of Somalia, October 2026) and no claim settlement ratio is published.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SO', 1, 'life_expectancy', 58.97, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN), Somalia', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=SO', '2024-12-31', '59.0 years in 2024 (men 56.5, women 61.6), UN WPP estimates via the World Bank; UN WPP 2024 projects 59.3 for 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SO', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":16.9,"men":16.1,"women":17.6},{"age":65,"total":13.5,"men":12.9,"women":14},{"age":70,"total":10.5,"men":10,"women":10.9},{"age":80,"total":5.9,"men":5.6,"women":6.1}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/somalia/', '2026-07-01', 'Secondary source of UN WPP 2024 (medium variant) for 2026; totals are the mean of men and women except at 65, where the page gives 13.5.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SO', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SO', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension was found; national cash transfers target poor and vulnerable households rather than older people by age.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SO', 1, 'oop_health_share', 0.3078, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), Somalia', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=SO', '2023-12-31', '30.8% in 2023 (WHO Global Health Expenditure Database), the latest available; older than 2025. Much of the rest is donor-funded.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SO', 1, 'policy_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Central Bank of Somalia does not set a policy interest rate; its October 2026 paper says the economy is fully dollarized and the shilling carries no monetary policy relevance.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SO', 1, 'public_pension_scheme', NULL, NULL, 'missing', '', '', '2026-10-31', 'No national contributory pension scheme for private-sector workers was found in official sources.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SO', 1, 'retirement_accumulation_return_base', 0.04, NULL, 'assumption', 'Safe dollar return about 2.5%; equity base 6%; gold base 4.5%', 'https://centralbank.gov.so/wp-content/uploads/2026/10/Spillover-Effects-of-Foreign-Aid-Reductions-on-Somalias-Macro-Financial-Stability.pdf', '2026-10-31', 'Base case: a balanced mix of dollar deposits, gold and global equity funds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SO', 1, 'retirement_accumulation_return_high', 0.06, NULL, 'assumption', 'Safe dollar return about 2.5%; equity base 6%; gold base 4.5%', 'https://centralbank.gov.so/wp-content/uploads/2026/10/Spillover-Effects-of-Foreign-Aid-Reductions-on-Somalias-Macro-Financial-Stability.pdf', '2026-10-31', 'High case: a growth-leaning mix with more global equity.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SO', 1, 'retirement_accumulation_return_low', 0.02, NULL, 'assumption', 'Safe dollar return about 2.5%; equity base 6%; gold base 4.5%', 'https://centralbank.gov.so/wp-content/uploads/2026/10/Spillover-Effects-of-Foreign-Aid-Reductions-on-Somalias-Macro-Financial-Stability.pdf', '2026-10-31', 'Low case: mostly dollar deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SO', 1, 'retirement_age_default', NULL, NULL, 'missing', '', '', '2026-10-31', 'No national contributory pension with a pension age covers private-sector workers, and no statutory private-sector retirement age was found in official sources.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SO', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'The civil service retirement age could not be confirmed from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SO', 1, 'retirement_return_base', 0.025, NULL, 'assumption', 'No published local deposit returns; dollarized economy', 'https://centralbank.gov.so/wp-content/uploads/2026/10/Spillover-Effects-of-Foreign-Aid-Reductions-on-Somalias-Macro-Financial-Stability.pdf', '2026-10-31', 'Base case: kept at the assumed safe dollar return of about 2.5%. Somalia is fully dollarized and has no government securities market, so safe returns are dollar returns on bank deposits held abroad or in local Islamic accounts.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SO', 1, 'retirement_return_high', 0.04, NULL, 'assumption', 'No published local deposit returns; dollarized economy', 'https://centralbank.gov.so/wp-content/uploads/2026/10/Spillover-Effects-of-Foreign-Aid-Reductions-on-Somalias-Macro-Financial-Stability.pdf', '2026-10-31', 'High case: dollar term investments.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SO', 1, 'retirement_return_low', 0.01, NULL, 'assumption', 'No published local deposit returns; dollarized economy', 'https://centralbank.gov.so/wp-content/uploads/2026/10/Spillover-Effects-of-Foreign-Aid-Reductions-on-Somalias-Macro-Financial-Stability.pdf', '2026-10-31', 'Low case: dollar savings earning little.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SO', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate or retail bond is issued; Somalia has no domestic government securities market.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SO', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Banks operate under Islamic finance with profit-sharing accounts; no published average return on savings accounts was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SO', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":19.4},{"year":2040,"value":18.9},{"year":2065,"value":12.7}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://data.worldbank.org/indicator/SP.POP.DPND.OL?locations=SO', '2025-12-31', 'Working-age people per person 65+, computed as 100 / old-age dependency ratio: 5.1 in 2025 (World Bank) gives 19.4; 5.3 in 2040 and 7.9 in 2065 (populationpyramid.net/somalia/2040/ and /2065/) give 18.9 and 12.7.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SO', 1, 'tax_bank_interest', NULL, NULL, 'missing', '', '', '2026-10-31', 'Banks pay profit shares rather than interest, and no withholding tax rule on deposit returns for individuals was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SO', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate exists.', 0);
