INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('SR', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"SR","iso3":"SUR","nameEn":"Suriname","nameNative":"Suriname","region":"latin_america_caribbean","languages":["nl","srn","hns","jv","en"],"currency":{"code":"SRD","symbol":"$","decimals":2,"compact":"intl","usdRate":{"value":37.444,"status":"sourced","sourceName":"Trading Economics, USD/SRD exchange rate","sourceUrl":"https://tradingeconomics.com/suriname/currency","asOf":"2026-10-29","note":"Secondary source because the Central Bank of Suriname website blocks automated reading behind a verification page; the World Bank official rate PA.NUS.FCRF averaged 37.26 in 2025. The Suriname dollar floats."}},"instruments":{"savings_account":{"available":true,"localName":"Spaarrekening","localNameEn":"Savings account","note":"Offered by commercial banks; rates could not be read from central bank statistics."},"fdr_3m":{"available":true,"localName":"Termijndeposito","localNameEn":"3-month term deposit","note":"Offered by commercial banks; no public rate table was readable."},"fdr_1y":{"available":true,"localName":"Termijndeposito","localNameEn":"1-year term deposit","note":"Offered by commercial banks; no public rate table was readable."},"dps":{"available":false,"localName":null,"note":"No standard monthly recurring deposit product with a published rate."},"sanchayapatra_5y":{"available":false,"localName":null,"note":"No government savings certificate or retail savings bond; central bank certificates have occasionally been sold to retail investors, which the IMF recommends stopping.","sourceUrl":"https://www.imf.org/en/publications/cr/issues/2026/02/11/suriname-2025-article-iv-consultation-press-release-staff-report-and-statement-by-the-573924"},"tbill_91d":{"available":false,"localName":null,"note":"Treasury bill auctions are not yet operational (IMF 2025 Article IV, February 2026).","sourceUrl":"https://www.imf.org/en/publications/cr/issues/2026/02/11/suriname-2025-article-iv-consultation-press-release-staff-report-and-statement-by-the-573924"},"tbond_5y":{"available":false,"localName":null,"note":"No domestic government bond market open to individuals was found."},"tbond_10y":{"available":false,"localName":null,"note":"No domestic government bond market open to individuals was found."},"equity_fund":{"available":false,"localName":null,"note":"No locally registered retail equity or index fund was identified; the local stock market is very small."},"gold":{"available":true,"localName":"Goud","localNameEn":"Gold","note":"Suriname is a gold producer and buying gold is legal; mostly sold as jewellery and small bars."}},"institutions":{"centralBank":{"name":"Centrale Bank van Suriname (CBvS)","url":"https://www.cbvs.sr/"},"insuranceRegulator":{"name":"Centrale Bank van Suriname (CBvS), supervision of insurers and pension funds","url":"https://www.cbvs.sr/","note":"A new Insurance Act was submitted to Parliament in June 2024 (IMF 2025 Article IV)."},"insuranceComplaints":null,"pensionScheme":{"name":"Algemeen Pensioenfonds (APF), Wet Algemeen Pensioen 2014","url":"https://gov.sr/thema/pensioen/"},"oldAgeAllowance":{"name":"Algemene Oudedagsvoorziening (AOV), Ministry of Social Affairs and Housing","url":"https://gov.sr/aov/","note":"Universal pension from age 60, paid by the AOV Fund."},"publicHealthCover":{"name":"Staatsziekenfonds (SZF) and the national basic health insurance (Basiszorgverzekering)","url":"https://www.szf.sr/","note":"Basic health insurance is compulsory; the government pays the premium for Surinamese children up to 16 and people 60 and older (https://gov.sr/thema/basiszorgverzekering/)."},"depositInsurance":null,"statistics":{"name":"Algemeen Bureau voor de Statistiek (ABS)","url":"https://statistics-suriname.org/consumenten-prijs-index-cpi/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SR', 1, 'bank_deposit_avg_rate', 0.07, NULL, 'sourced', 'Trading Economics, Suriname deposit interest rate (Central Bank of Suriname data)', 'https://tradingeconomics.com/suriname/deposit-interest-rate', '2026-08-31', 'Secondary source because the Central Bank of Suriname website blocks automated reading behind a verification page: average deposit rate 7% in August 2026, unchanged from July; World Bank FR.INR.DPST gives 6.69% for 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SR', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap on credit card interest and no official typical rate were found; the average bank lending rate was 13.7% in August 2026 (Trading Economics, central bank data).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SR', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched Government of Suriname and IMF sources: no operating deposit insurance scheme or cover limit was found (the Central Bank of Suriname website blocks automated reading behind a verification page).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SR', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published rate for a monthly recurring deposit product was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SR', 1, 'equity_return_base', 0.1, NULL, 'assumption', 'Average bank deposit rate 7.0% (August 2026, Central Bank of Suriname via Trading Economics); inflation 7.3% (September 2026)', 'https://tradingeconomics.com/suriname/deposit-interest-rate', '2026-10-31', 'Base case: global equities (about 6.5% in US dollars) plus some expected depreciation of the Suriname dollar, capped at the 7% deposit rate plus 3 points because there is no usable local index record.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SR', 1, 'equity_return_high', 0.14, NULL, 'assumption', 'Average bank deposit rate 7.0% (August 2026, Central Bank of Suriname via Trading Economics); inflation 7.3% (September 2026)', 'https://tradingeconomics.com/suriname/deposit-interest-rate', '2026-10-31', 'High case: strong global equities and faster depreciation of the Suriname dollar, which has lost most of its value since 2020.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SR', 1, 'equity_return_low', 0.05, NULL, 'assumption', 'Average bank deposit rate 7.0% (August 2026, Central Bank of Suriname via Trading Economics); inflation 7.3% (September 2026)', 'https://tradingeconomics.com/suriname/deposit-interest-rate', '2026-10-31', 'Low case: the local stock market is tiny and illiquid, so we use a global equity index in Suriname-dollar terms, with a weak global decade and a stable currency.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SR', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched for 1-year term deposit rates: the Central Bank of Suriname website blocks automated reading behind a verification page, and no other public source was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SR', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched for 3-month term deposit rates: the Central Bank of Suriname website blocks automated reading behind a verification page, and no other public source was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SR', 1, 'fixed_income_return_base', 0.06, NULL, 'assumption', 'Average bank deposit rate 7.0% (August 2026, Central Bank of Suriname via Trading Economics); inflation 7.3% (September 2026)', 'https://tradingeconomics.com/suriname/deposit-interest-rate', '2026-10-31', 'Base case: term deposits around the 7% average deposit rate, less possible tax on interest (not confirmed).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SR', 1, 'fixed_income_return_high', 0.075, NULL, 'assumption', 'Average bank deposit rate 7.0% (August 2026, Central Bank of Suriname via Trading Economics); inflation 7.3% (September 2026)', 'https://tradingeconomics.com/suriname/deposit-interest-rate', '2026-10-31', 'High case: longer term deposits slightly above the average deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SR', 1, 'fixed_income_return_low', 0.04, NULL, 'assumption', 'Average bank deposit rate 7.0% (August 2026, Central Bank of Suriname via Trading Economics); inflation 7.3% (September 2026)', 'https://tradingeconomics.com/suriname/deposit-interest-rate', '2026-10-31', 'Low case: savings accounts and short deposits pay well below the 7% average deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SR', 1, 'goal_inflation_education', 0.08, NULL, 'assumption', 'ABS CPI 7.3% (September 2026); planning inflation 7%', 'https://statistics-suriname.org/infographic-consumentenprijsindex-en-inflatiecijfers-september-2026/', '2026-10-31', 'No long-run education CPI series was found; we plan with headline planning inflation plus 1 point.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SR', 1, 'goal_inflation_health', 0.09, NULL, 'assumption', 'ABS CPI 7.3% (September 2026); planning inflation 7%', 'https://statistics-suriname.org/infographic-consumentenprijsindex-en-inflatiecijfers-september-2026/', '2026-10-31', 'No long-run medical CPI series was found; we plan with headline planning inflation plus 2 points for private and imported medical costs.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SR', 1, 'gold_return_base', 0.09, NULL, 'assumption', 'World Bank PA.NUS.FCRF: SRD 37.26 per US dollar (2025 average); IMF medium-term inflation 5%', 'https://tradingeconomics.com/suriname/currency', '2026-10-31', 'Dollar gold trend of about 4.5% a year plus about 4.5% a year of expected Suriname-dollar depreciation (inflation gap with the US).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SR', 1, 'gold_return_high', 0.14, NULL, 'assumption', 'World Bank PA.NUS.FCRF: SRD 37.26 per US dollar (2025 average)', 'https://tradingeconomics.com/suriname/currency', '2026-10-31', 'High case: strong dollar gold prices and renewed currency depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SR', 1, 'gold_return_low', 0.04, NULL, 'assumption', 'World Bank PA.NUS.FCRF: SRD 37.26 per US dollar (2025 average); SRD 37.44 (October 2026)', 'https://tradingeconomics.com/suriname/currency', '2026-10-31', 'Low case: weak dollar gold price and a stable Suriname dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SR', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched Government of Suriname sources: whether labour law provides any statutory payment on retirement could not be confirmed (no readable text of the labour laws was found).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SR', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a major private hospital stay was found for Suriname.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SR', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Health cover is mainly the compulsory national basic health insurance, priced as a flat monthly premium by age (SRD 55-240 a month on the government page https://gov.sr/thema/basiszorgverzekering/, older than 2025), not per 100,000 of cover; no source of private top-up premiums by age was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SR', 1, 'inflation_cpi', 0.073, NULL, 'sourced', 'Algemeen Bureau voor de Statistiek (ABS), CPI Suriname September 2026', 'https://statistics-suriname.org/infographic-consumentenprijsindex-en-inflatiecijfers-september-2026/', '2026-09-30', 'Prices in September 2026 were 7.3% higher than in September 2025 (index 979.7, April-June 2016 = 100; monthly change 0.1%); provisional figure.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SR', 1, 'inflation_projection', 0.07, NULL, 'assumption', 'IMF 2025 Article IV (February 2026): CPI end-2026 9.7%, 2027 6.1%, 5.0% from 2028; ABS CPI 7.3% (September 2026)', 'https://www.imf.org/en/publications/cr/issues/2026/02/11/suriname-2025-article-iv-consultation-press-release-staff-report-and-statement-by-the-573924', '2026-10-31', 'Suriname has no inflation target and a history of very high inflation (over 50% in 2023), so we plan with 7%, above the IMF''s 5% medium-term projection.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SR', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life cover is sold in Suriname, but no regulator or other non-company source publishes premium rates by age.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SR', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No industry-wide life claim settlement ratio is published; insurance supervision rules are still being developed (the Insurance Act was submitted to Parliament in June 2024, IMF 2025 Article IV).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SR', 1, 'life_expectancy', 73.757, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=SR', '2024-12-31', 'Men 70.6, women 77.0 (2024). UN WPP 2024 via populationpyramid.net gives 74.0 for 2026 (men 70.9, women 77.3). The World Bank figure is for 2024, older than 2025 (latest published).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SR', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":20.3,"men":18,"women":22.5},{"age":65,"total":16.8,"men":14.6,"women":18.5},{"age":70,"total":13.3,"men":11.6,"women":15},{"age":80,"total":7.7,"men":6.5,"women":8.9}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/suriname/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for the year 2026 (asOf set to mid-year); sex-specific values are for the 5-year age groups starting at each age; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SR', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":60,"womenAge":60,"over90Monthly":null,"meansTested":false}', 'sourced', 'UN ECLAC non-contributory pensions database: Universal Old Age Pension (AOV), Suriname', 'https://dds.cepal.org/bpsnc/programme?id=270', '2025-03-31', 'AOV from age 60 for Surinamese citizens and for foreign nationals resident in Suriname for at least 10 years; universal, not means-tested; financed from general revenue and a 4% levy on the taxable income of residents under 60.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SR', 1, 'old_age_allowance_monthly', 2250, NULL, 'sourced', 'UN ECLAC non-contributory pensions database: Universal Old Age Pension (AOV), Suriname; Ministry of Finance and Planning (31 May 2026)', 'https://dds.cepal.org/bpsnc/programme?id=270', '2026-05-31', 'The universal AOV (Algemene Oudedagsvoorziening) is SRD 2,250 a month since March 2025 (ECLAC). The Ministry of Finance and Planning confirmed on 31 May 2026 that AOV was not increased in 2026 (https://gov.sr/ministerie-verduidelijkt-uitbetaling-sociale-uitkeringen/); a separate temporary supplement of SRD 1,000 was paid in some months of 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SR', 1, 'oop_health_share', 0.1972, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=SR', '2023-12-31', 'Out-of-pocket spending was 19.7% of current health expenditure in 2023 (latest available; older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SR', 1, 'policy_rate', 0.1, NULL, 'sourced', 'Trading Economics, Suriname interest rate (Central Bank of Suriname discount rate)', 'https://tradingeconomics.com/suriname/interest-rate', '2026-10-31', 'Secondary source because the Central Bank of Suriname website blocks automated reading behind a verification page: the discount rate at which the central bank lends to banks is 10% (October 2026). The central bank steers reserve money through open market operations rather than a point policy rate (IMF 2025 Article IV).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SR', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":60,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'Government of Suriname, ''Pensioen'' (Wet Algemeen Pensioen 2014)', 'https://gov.sr/thema/pensioen/', '2022-04-01', 'Compulsory general pension for all working residents (in force 8 December 2014), run by the Algemeen Pensioenfonds: premium example 3% of wages, at least half paid by the employer; pension from 60 after at least 5 years of premiums, separate from the AOV (the page also cites a minimum of SRD 825 a month including an AOV of SRD 525, an outdated AOV level). No indexation is stated; tax treatment not confirmed. Page dated April 2022 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SR', 1, 'retirement_accumulation_return_base', 0.08, NULL, 'assumption', 'Average bank deposit rate 7.0% (August 2026, Central Bank of Suriname via Trading Economics); inflation 7.3% (September 2026); global equity assumptions in SRD', 'https://tradingeconomics.com/suriname/deposit-interest-rate', '2026-10-31', 'Base case: half global equities at 10% and half deposits around 6% in Suriname-dollar terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SR', 1, 'retirement_accumulation_return_high', 0.105, NULL, 'assumption', 'Average bank deposit rate 7.0% (August 2026, Central Bank of Suriname via Trading Economics); inflation 7.3% (September 2026); global equity assumptions in SRD', 'https://tradingeconomics.com/suriname/deposit-interest-rate', '2026-10-31', 'High case with stronger equity returns and currency depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SR', 1, 'retirement_accumulation_return_low', 0.055, NULL, 'assumption', 'Average bank deposit rate 7.0% (August 2026, Central Bank of Suriname via Trading Economics); inflation 7.3% (September 2026); global equity assumptions in SRD', 'https://tradingeconomics.com/suriname/deposit-interest-rate', '2026-10-31', 'Low case for a balanced mix of deposits and global equities.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SR', 1, 'retirement_age_default', 60, NULL, 'sourced', 'Government of Suriname, ''Pensioen'' (Wet Algemeen Pensioen 2014)', 'https://gov.sr/thema/pensioen/', '2022-04-01', 'The pension age in Suriname is 60 under the Wet Algemeen Pensioen 2014, the same for men and women; the AOV also starts at 60. Page dated April 2022 (older than 2025); no change found since.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SR', 1, 'retirement_age_government', 60, NULL, 'sourced', 'Ministry of Home Affairs (Binnenlandse Zaken), Government of Suriname', 'https://gov.sr/minister-marinus-bee-ontvangt-religieuze-organisaties/', '2025-12-11', 'The statutory pension age for civil servants is 60, with extension by employment contract for up to five years.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SR', 1, 'retirement_return_base', 0.055, NULL, 'assumption', 'Average bank deposit rate 7.0% (August 2026, Central Bank of Suriname via Trading Economics); inflation 7.3% (September 2026)', 'https://tradingeconomics.com/suriname/deposit-interest-rate', '2026-10-31', 'Base case below the 7% average deposit rate, allowing for lower rates on liquid deposits and possible tax on interest.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SR', 1, 'retirement_return_high', 0.07, NULL, 'assumption', 'Average bank deposit rate 7.0% (August 2026, Central Bank of Suriname via Trading Economics); inflation 7.3% (September 2026)', 'https://tradingeconomics.com/suriname/deposit-interest-rate', '2026-10-31', 'High case: term deposits at about the average deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SR', 1, 'retirement_return_low', 0.04, NULL, 'assumption', 'Average bank deposit rate 7.0% (August 2026, Central Bank of Suriname via Trading Economics); inflation 7.3% (September 2026)', 'https://tradingeconomics.com/suriname/deposit-interest-rate', '2026-10-31', 'Low case: mostly savings and short deposits paying well below the average deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SR', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate or retail savings bond was found. The central bank has sold its own certificates to retail investors at times in 2023-2025, which the IMF (2025 Article IV) recommends stopping; their rates could not be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SR', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched for bank savings rates: the Central Bank of Suriname website blocks automated reading behind a verification page, and no other public source of savings account rates was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SR', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":8.1},{"year":2040,"value":5.1},{"year":2065,"value":3.4}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/suriname/2040/', '2025-12-31', '100 / old-age dependency ratio: 12.3 (2025, World Bank), 19.7 (2040) and 29.3 (2065, populationpyramid.net/suriname/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SR', 1, 'tax_bank_interest', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched the Belastingdienst Suriname site (income tax pages and laws list) and PwC Tax Summaries (no Suriname page): no readable statement of how interest on bank deposits is taxed for residents was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SR', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate exists for individuals in Suriname (see sanchayapatra_5y_rate), so no tax rate applies.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SR', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No current Treasury bill yield is published: the IMF 2025 Article IV (February 2026) reports that the operationalisation of Treasury bill auctions is still pending.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SR', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published 10-year domestic government bond yield was found; domestic debt markets are undeveloped (IMF 2025 Article IV).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SR', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published 5-year domestic government bond yield was found; domestic debt markets are undeveloped (IMF 2025 Article IV).', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('SS', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"SS","iso3":"SSD","nameEn":"South Sudan","nameNative":"South Sudan","region":"sub_saharan_africa","languages":["en","ar","din","nus"],"currency":{"code":"SSP","symbol":"£","decimals":2,"compact":"intl","usdRate":{"value":5660.2,"status":"sourced","sourceName":"Trading Economics, USD/SSP, 29 October 2026","sourceUrl":"https://tradingeconomics.com/south-sudan/currency","asOf":"2026-10-29","note":"Secondary source: 5,660.196 pounds per US dollar on 29 October 2026 (down 25% in a year). The Bank of South Sudan home page showed undated buying and selling rates of 5,690.49 and 5,863.81 when read on 3 November 2026; the World Bank 2024 average was 2,163."}},"instruments":{"savings_account":{"available":true,"localName":null,"localNameEn":"Savings account","note":"Banks pay about 2% on savings deposits (Bank of South Sudan, October 2024).","sourceUrl":"https://boss.gov.ss/wp-content/uploads/2024/12/10.Statistical-bulletin-table-October-2024-1.pdf"},"fdr_3m":{"available":true,"localName":null,"localNameEn":"Time deposit, up to 3 months","note":"Average rate 0.02% (October 2024).","sourceUrl":"https://boss.gov.ss/wp-content/uploads/2024/12/10.Statistical-bulletin-table-October-2024-1.pdf"},"fdr_1y":{"available":true,"localName":null,"localNameEn":"Time deposit, over 3 months","note":"Average rate 0.46% (October 2024).","sourceUrl":"https://boss.gov.ss/wp-content/uploads/2024/12/10.Statistical-bulletin-table-October-2024-1.pdf"},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No monthly recurring deposit scheme was found."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate or retail savings bond for individuals was found."},"tbill_91d":{"available":false,"localName":null,"localNameEn":"Treasury bill","note":"The Bank of South Sudan treasury bills page shows no auctions or results; no retail access was found.","sourceUrl":"https://boss.gov.ss/treasury-bills/"},"tbond_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government bond market was found."},"tbond_10y":{"available":false,"localName":null,"localNameEn":null,"note":"No government bond market was found."},"equity_fund":{"available":false,"localName":null,"localNameEn":null,"note":"No stock exchange or locally offered retail investment fund was found in South Sudan."},"gold":{"available":true,"localName":null,"localNameEn":"Gold","note":"Gold is mined artisanally and sold locally, mostly as jewellery and raw gold; no official bullion product was found."}},"institutions":{"centralBank":{"name":"Bank of South Sudan","url":"https://boss.gov.ss/"},"insuranceRegulator":null,"insuranceComplaints":null,"pensionScheme":null,"oldAgeAllowance":null,"publicHealthCover":null,"depositInsurance":null,"statistics":{"name":"National Bureau of Statistics","url":"https://www.nbs.gov.ss/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SS', 1, 'bank_deposit_avg_rate', 0.00083, NULL, 'sourced', 'World Bank WDI, deposit interest rate (FR.INR.DPST), South Sudan', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=SS', '2025-12-31', '0.08% average for 2025 (IMF International Financial Statistics); the Bank of South Sudan bulletin gave 0.13% for October 2024.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SS', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No credit card interest cap or typical rate was found; the Bank of South Sudan bulletin gives average lending rates only.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SS', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No deposit insurance scheme or cover limit was found on the Bank of South Sudan site; not confirmed absent.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SS', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No monthly recurring deposit scheme or published rate was found in Bank of South Sudan statistics.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SS', 1, 'equity_return_base', 0.045, NULL, 'assumption', 'Bank of South Sudan, Statistical Bulletin October 2024 (term deposits over 3 months 0.46%)', 'https://boss.gov.ss/wp-content/uploads/2024/12/10.Statistical-bulletin-table-October-2024-1.pdf', '2026-10-31', 'No stock exchange or locally offered retail investment fund was found in South Sudan, so equity means a global index fund in pound terms; the base case is capped at about 4 points above the near-zero term deposit rate, far below what a global index would earn if the pound keeps falling.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SS', 1, 'equity_return_high', 0.25, NULL, 'assumption', 'IMF World Economic Outlook, South Sudan inflation; Trading Economics USD/SSP', 'https://www.imf.org/external/datamapper/api/v1/PCPIPCH/SSD', '2026-10-31', 'High case: a global index (about 7% a year in dollars) plus continued pound depreciation of 15-20% a year.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SS', 1, 'equity_return_low', 0, NULL, 'assumption', 'IMF World Economic Outlook, South Sudan inflation; Bank of South Sudan deposit rates', 'https://www.imf.org/external/datamapper/api/v1/PCPIPCH/SSD', '2026-10-31', 'Low case: No stock exchange or locally offered retail investment fund was found in South Sudan; a global fund bought abroad in a bad decade with a steadier pound returns little in pound terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SS', 1, 'fdr_1y_rate', 0.0046, NULL, 'sourced', 'Bank of South Sudan, Statistical Bulletin October 2024, table 1.7 (deposits over 3 months)', 'https://boss.gov.ss/wp-content/uploads/2024/12/10.Statistical-bulletin-table-October-2024-1.pdf', '2024-10-31', 'Average rate on deposits of over 3 months 0.46% at the end of October 2024 (no separate 1-year rate is published); older than 2025, the latest published.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SS', 1, 'fdr_3m_rate', 0.0002, NULL, 'sourced', 'Bank of South Sudan, Statistical Bulletin October 2024, table 1.7 (deposits 0-3 months)', 'https://boss.gov.ss/wp-content/uploads/2024/12/10.Statistical-bulletin-table-October-2024-1.pdf', '2024-10-31', 'Average rate on deposits of up to 3 months 0.02% at the end of October 2024; older than 2025, the latest published.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SS', 1, 'fixed_income_return_base', 0.01, NULL, 'assumption', 'Bank of South Sudan, Statistical Bulletin October 2024, table 1.7', 'https://boss.gov.ss/wp-content/uploads/2024/12/10.Statistical-bulletin-table-October-2024-1.pdf', '2026-10-31', 'Base case: a mix of savings deposits (2.02%) and term deposits (0.46%), with no tax assumed because none could be confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SS', 1, 'fixed_income_return_high', 0.02, NULL, 'assumption', 'Bank of South Sudan, Statistical Bulletin October 2024, table 1.7', 'https://boss.gov.ss/wp-content/uploads/2024/12/10.Statistical-bulletin-table-October-2024-1.pdf', '2026-10-31', 'High case: savings deposits at about 2%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SS', 1, 'fixed_income_return_low', 0, NULL, 'assumption', 'Bank of South Sudan, Statistical Bulletin October 2024, table 1.7', 'https://boss.gov.ss/wp-content/uploads/2024/12/10.Statistical-bulletin-table-October-2024-1.pdf', '2026-10-31', 'Low case: short deposits, which pay almost nothing (0.02% up to 3 months).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SS', 1, 'goal_inflation_education', 0.2, NULL, 'assumption', 'IMF World Economic Outlook, South Sudan inflation', 'https://www.imf.org/external/datamapper/api/v1/PCPIPCH/SSD', '2026-10-31', 'No education price index was found; private school fees are often set in dollars, so they are assumed to rise with the 20% inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SS', 1, 'goal_inflation_health', 0.2, NULL, 'assumption', 'IMF World Economic Outlook, South Sudan inflation', 'https://www.imf.org/external/datamapper/api/v1/PCPIPCH/SSD', '2026-10-31', 'No medical price index was found, and most medicines and equipment are imported and priced off the dollar, so health costs are assumed to rise with the 20% inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SS', 1, 'gold_return_base', 0.22, NULL, 'assumption', 'IMF World Economic Outlook, South Sudan inflation; Trading Economics USD/SSP', 'https://www.imf.org/external/datamapper/api/v1/PCPIPCH/SSD', '2026-10-31', 'Base case: the long-run dollar gold trend of about 4% a year plus pound depreciation of about 18% a year, close to the gap between the 20% inflation assumption and dollar inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SS', 1, 'gold_return_high', 0.35, NULL, 'assumption', 'Trading Economics USD/SSP', 'https://tradingeconomics.com/south-sudan/currency', '2026-10-31', 'High case: strong gold years and a pound that keeps falling as fast as in the past year (about 25%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SS', 1, 'gold_return_low', 0.05, NULL, 'assumption', 'Trading Economics USD/SSP (pound down 25% in the year to October 2026)', 'https://tradingeconomics.com/south-sudan/currency', '2026-10-31', 'Low case: flat dollar gold and a much slower fall in the pound.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SS', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'The end-of-service rules in the Labour Act 2017 could not be read from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SS', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a major private hospital stay was found from an official or international source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SS', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premium rates were found from a public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SS', 1, 'inflation_cpi', 0.5821, NULL, 'sourced', 'National Bureau of Statistics, Consumer Price Index releases (annual inflation, May 2025)', 'https://www.nbs.gov.ss/statistics/Consumer_Price_Index.php', '2025-05-31', '58.21% year on year in May 2025, the latest release the NBS lists (none for 2026; Trading Economics also shows 58.21%). The IMF estimates 97.6% for the 2025 average and projects 27.6% for 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SS', 1, 'inflation_projection', 0.2, NULL, 'assumption', 'IMF World Economic Outlook, South Sudan inflation (27.6% projected for 2026, 28.3% for 2027, about 5-8% from 2028)', 'https://www.imf.org/external/datamapper/api/v1/PCPIPCH/SSD', '2026-10-31', 'There is no credible inflation target and inflation averaged over 50% a year in 2021-2025, so plans use 20%, below current rates but well above the IMF''s hoped-for single digits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SS', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published term life premium rates were found from a regulator or other public source; whether term life is sold locally could not be confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SS', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No insurance regulator statistics on life claim settlement were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SS', 1, 'life_expectancy', 57.738, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN), South Sudan', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=SS', '2024-12-31', '57.7 years in 2024 (men 54.8, women 60.7); UN WPP 2024 via populationpyramid.net gives 58.0 for 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SS', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":16.2,"men":15.2,"women":17.2},{"age":65,"total":13,"men":12.1,"women":13.7},{"age":70,"total":10,"men":9.3,"women":10.7},{"age":80,"total":5.5,"men":5.1,"women":5.9}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/south-sudan/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SS', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age (social) pension paid nationally was found; not confirmed absent.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SS', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age (social) pension paid nationally was found; not confirmed absent.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SS', 1, 'oop_health_share', 0.2714, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), South Sudan', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=SS', '2023-12-31', '27.1% in 2023 (WHO Global Health Expenditure Database); older than 2025, the latest available. Donors fund much of the rest.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SS', 1, 'policy_rate', 0.13, NULL, 'sourced', 'Bank of South Sudan central bank rate, via Trading Economics', 'https://tradingeconomics.com/south-sudan/interest-rate', '2026-09-30', 'Secondary source: Trading Economics records the central bank rate at 13% for September 2026 (unchanged from the previous reading). The Bank of South Sudan monetary policy page states no rate and says it targets reserve money, so the rate is of limited importance for deposit pricing.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SS', 1, 'public_pension_scheme', NULL, NULL, 'missing', '', '', '2026-10-31', 'No public contributory pension for private-sector workers could be confirmed; civil servants have a separate pension fund whose rules could not be loaded.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SS', 1, 'retirement_accumulation_return_base', 0.08, NULL, 'assumption', 'Bank of South Sudan deposit rates; gold base 22%; equity base 4.5%', 'https://boss.gov.ss/wp-content/uploads/2024/12/10.Statistical-bulletin-table-October-2024-1.pdf', '2026-10-31', 'Base case: a mix of deposits, a global fund and some gold, which has kept value far better than pound deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SS', 1, 'retirement_accumulation_return_high', 0.15, NULL, 'assumption', 'IMF World Economic Outlook, South Sudan inflation; gold high 35%', 'https://www.imf.org/external/datamapper/api/v1/PCPIPCH/SSD', '2026-10-31', 'High case: a larger share in gold and foreign assets while the pound keeps falling.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SS', 1, 'retirement_accumulation_return_low', 0.01, NULL, 'assumption', 'Bank of South Sudan, Statistical Bulletin October 2024', 'https://boss.gov.ss/wp-content/uploads/2024/12/10.Statistical-bulletin-table-October-2024-1.pdf', '2026-10-31', 'Low case: mostly pound deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SS', 1, 'retirement_age_default', NULL, NULL, 'missing', '', '', '2026-10-31', 'No statutory pension age for private-sector workers and no public contributory pension scheme could be confirmed from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SS', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'The civil service retirement age could not be confirmed from an official source (the Civil Service and Pensions Fund Acts could not be loaded).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SS', 1, 'retirement_return_base', 0.004, NULL, 'assumption', 'Bank of South Sudan, Statistical Bulletin October 2024, table 1.7 (deposits over 3 months 0.46%)', 'https://boss.gov.ss/wp-content/uploads/2024/12/10.Statistical-bulletin-table-October-2024-1.pdf', '2026-10-31', 'Base case: kept just below the 0.46% average rate on term deposits, the safest pound investment found; real returns are deeply negative.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SS', 1, 'retirement_return_high', 0.02, NULL, 'assumption', 'Bank of South Sudan, Statistical Bulletin October 2024, table 1.7 (savings 2.02%)', 'https://boss.gov.ss/wp-content/uploads/2024/12/10.Statistical-bulletin-table-October-2024-1.pdf', '2026-10-31', 'High case: savings deposits at about 2%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SS', 1, 'retirement_return_low', 0, NULL, 'assumption', 'Bank of South Sudan, Statistical Bulletin October 2024, table 1.7', 'https://boss.gov.ss/wp-content/uploads/2024/12/10.Statistical-bulletin-table-October-2024-1.pdf', '2026-10-31', 'Low case: short deposits paying almost nothing.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SS', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate or retail savings bond for individuals was found; the Bank of South Sudan treasury bills page shows no products or results.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SS', 1, 'savings_account_rate', 0.0202, NULL, 'sourced', 'Bank of South Sudan, Statistical Bulletin October 2024, table 1.7 deposit and lending interest rates (savings)', 'https://boss.gov.ss/wp-content/uploads/2024/12/10.Statistical-bulletin-table-October-2024-1.pdf', '2024-10-31', 'Average commercial bank savings deposit rate 2.02% at the end of October 2024; older than 2025 and the latest bulletin published.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SS', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":19.16},{"year":2040,"value":12.82},{"year":2065,"value":11.36}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/south-sudan/2040/', '2025-12-31', '100 / old-age dependency ratio: 5.2 (2025, World Bank), 7.8 (2040) and 8.8 (2065, populationpyramid.net/south-sudan/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SS', 1, 'tax_bank_interest', NULL, NULL, 'missing', '', '', '2026-10-31', 'The withholding or income tax rate on bank interest for residents could not be confirmed: PwC Tax Summaries does not cover South Sudan and the National Revenue Authority site shows no tax schedules.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SS', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'There is no government savings certificate, and the tax treatment of government securities could not be confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SS', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Bank of South Sudan treasury bills page (https://boss.gov.ss/treasury-bills/) has only a heading and no auction results, rates or tenors, and no yield was found elsewhere.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SS', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 10-year government bond issue or yield was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SS', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 5-year government bond issue or yield was found.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('ST', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"ST","iso3":"STP","nameEn":"São Tomé and Príncipe","nameNative":"São Tomé e Príncipe","region":"sub_saharan_africa","languages":["pt","cri"],"currency":{"code":"STN","symbol":"Db","decimals":2,"compact":"intl","usdRate":{"value":21.63,"status":"sourced","sourceName":"Banco Central de São Tomé e Príncipe, official exchange rates (monthly average), July 2026","sourceUrl":"https://www.bcstp.st/Upload/New_DOC/ES/Taxa%20de%20C%C3%A2mbio%20do%20Banco%20Central_2019-2026.xlsx","asOf":"2026-07-31","note":"21.634 dobras per US dollar on average in July 2026 (21.349 at end-July); the dobra is pegged at 24.5 per euro. World Bank 2025 average 21.75."}},"instruments":{"savings_account":{"available":true,"localName":"Conta poupança","localNameEn":"Savings account","note":"Average 2.5% a year (BCSTP, July 2026).","sourceUrl":"https://www.bcstp.st/Upload/New_DOC/ES/Taxas%20de%20Juro_Moeda%20Nacional_2013-2026.xlsx"},"fdr_3m":{"available":true,"localName":"Depósito a prazo (91 a 180 dias)","localNameEn":"Term deposit (91-180 days)","note":"Average 2.38% a year (BCSTP, July 2026).","sourceUrl":"https://www.bcstp.st/Upload/New_DOC/ES/Taxas%20de%20Juro_Moeda%20Nacional_2013-2026.xlsx"},"fdr_1y":{"available":true,"localName":"Depósito a prazo (181 dias a 1 ano)","localNameEn":"Term deposit (181 days to 1 year)","note":"Average 2.53% a year (BCSTP, July 2026).","sourceUrl":"https://www.bcstp.st/Upload/New_DOC/ES/Taxas%20de%20Juro_Moeda%20Nacional_2013-2026.xlsx"},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No monthly recurring deposit product was found."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate for individuals was found."},"tbill_91d":{"available":false,"localName":"Bilhetes do Tesouro","localNameEn":"Treasury bills","note":"Issued irregularly (30 days to 1 year) to a handful of institutional bidders (BCSTP issue list); no channel for individuals was found.","sourceUrl":"https://www.bcstp.st/Upload/New_DOC/ME/BT%20total%20resumo_26.pdf"},"tbond_5y":{"available":false,"localName":"Obrigações do Tesouro","localNameEn":"Treasury bonds","note":"No 5-year bond issue was found."},"tbond_10y":{"available":false,"localName":null,"localNameEn":null,"note":"No 10-year bond issue was found."},"equity_fund":{"available":false,"localName":null,"localNameEn":null,"note":"There is no stock exchange or locally sold mutual fund; global funds would have to be bought abroad."},"gold":{"available":true,"localName":"Ouro","localNameEn":"Gold","note":"Gold is sold mainly as jewellery; no official bullion or coin scheme was found."}},"institutions":{"centralBank":{"name":"Banco Central de São Tomé e Príncipe (BCSTP)","url":"https://www.bcstp.st/"},"insuranceRegulator":{"name":"Banco Central de São Tomé e Príncipe (BCSTP), insurance supervision","url":"https://www.bcstp.st/","note":"The BCSTP licenses and supervises insurance companies."},"insuranceComplaints":{"name":"BCSTP complaints form (Ficha de Reclamação)","url":"https://www.bcstp.st/Reclamacoes"},"pensionScheme":{"name":"Instituto Nacional de Segurança Social (INSS)","url":"https://www.seg-social-stp.net/"},"oldAgeAllowance":null,"publicHealthCover":null,"depositInsurance":null,"statistics":{"name":"Instituto Nacional de Estatística (INE)","url":"https://www.ine.st/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ST', 1, 'bank_deposit_avg_rate', 0.0254, NULL, 'sourced', 'Banco Central de São Tomé e Príncipe (BCSTP), interest rate statistics in national currency, monthly series (average of all maturities, deposits)', 'https://www.bcstp.st/Upload/New_DOC/ES/Taxas%20de%20Juro_Moeda%20Nacional_2013-2026.xlsx', '2026-07-31', 'Average rate on deposits (operações passivas) across maturities, 2.54% in July 2026 (term deposits 2.45%, savings 2.63%). World Bank gives 2.37% for 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ST', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No card-specific rate or legal cap was found; bank overdraft rates were 21-24.5% in July 2026 (BCSTP interest rate statistics).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ST', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No deposit guarantee scheme in operation was found; a 2022 bill revising the central bank''s organic law gave the BCSTP the task of promoting a deposit guarantee fund, but its creation could not be confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ST', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No monthly recurring deposit product or rate was found; the BCSTP publishes only savings and term deposit rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ST', 1, 'equity_return_base', 0.06, NULL, 'assumption', 'Global equity index in euro terms; dobra pegged to the euro; after-tax safe rate about 2.5% (BCSTP)', 'https://www.bcstp.st/Upload/New_DOC/ES/Taxa%20de%20C%C3%A2mbio%20do%20Banco%20Central_2019-2026.xlsx', '2026-10-31', 'There is no local market, so base is a global index fund in local-currency terms (the peg makes this euro terms), capped at about 4 points above the 2.5% deposit rate even though global shares have done better.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ST', 1, 'equity_return_high', 0.09, NULL, 'assumption', 'Global equity index in euro terms', 'https://www.bcstp.st/Upload/New_DOC/ES/Taxa%20de%20C%C3%A2mbio%20do%20Banco%20Central_2019-2026.xlsx', '2026-10-31', 'High case: a strong decade for global shares.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ST', 1, 'equity_return_low', 0.02, NULL, 'assumption', 'No stock exchange in São Tomé and Príncipe; global equities in euro terms (dobra pegged at 24.5 per euro, BCSTP)', 'https://www.bcstp.st/Upload/New_DOC/ES/Taxa%20de%20C%C3%A2mbio%20do%20Banco%20Central_2019-2026.xlsx', '2026-10-31', 'Low case: a weak decade for global shares in euro terms, after fund costs.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ST', 1, 'fdr_1y_rate', 0.0253, NULL, 'sourced', 'Banco Central de São Tomé e Príncipe (BCSTP), interest rate statistics in national currency, monthly series (term deposits, 181 days to 1 year)', 'https://www.bcstp.st/Upload/New_DOC/ES/Taxas%20de%20Juro_Moeda%20Nacional_2013-2026.xlsx', '2026-07-31', 'Average rate on term deposits of 181 days to 1 year, 2.53% in July 2026; over one year 3.06%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ST', 1, 'fdr_3m_rate', 0.02375, NULL, 'sourced', 'Banco Central de São Tomé e Príncipe (BCSTP), interest rate statistics in national currency, monthly series (term deposits, 91 to 180 days)', 'https://www.bcstp.st/Upload/New_DOC/ES/Taxas%20de%20Juro_Moeda%20Nacional_2013-2026.xlsx', '2026-07-31', 'Average rate on term deposits of 91-180 days, 2.38% in July 2026; the shortest band published.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ST', 1, 'fixed_income_return_base', 0.025, NULL, 'assumption', 'Banco Central de São Tomé e Príncipe (BCSTP), interest rate statistics in national currency, monthly series', 'https://www.bcstp.st/Upload/New_DOC/ES/Taxas%20de%20Juro_Moeda%20Nacional_2013-2026.xlsx', '2026-10-31', 'Base case: term deposits of up to a year at about 2.5%; the tax on interest is unconfirmed, so this may be slightly high.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ST', 1, 'fixed_income_return_high', 0.035, NULL, 'assumption', 'Banco Central de São Tomé e Príncipe (BCSTP), interest rate statistics in national currency, monthly series', 'https://www.bcstp.st/Upload/New_DOC/ES/Taxas%20de%20Juro_Moeda%20Nacional_2013-2026.xlsx', '2026-10-31', 'High case: term deposits of over one year (3.06%) or negotiated rates on larger deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ST', 1, 'fixed_income_return_low', 0.015, NULL, 'assumption', 'Banco Central de São Tomé e Príncipe (BCSTP), interest rate statistics in national currency, monthly series', 'https://www.bcstp.st/Upload/New_DOC/ES/Taxas%20de%20Juro_Moeda%20Nacional_2013-2026.xlsx', '2026-10-31', 'Low case: short deposits at about 2.4% less a possible tax on interest.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ST', 1, 'goal_inflation_education', 0.08, NULL, 'assumption', 'INE CPI; inflation assumption 7%', 'https://www.ine.st/phocadownload/userupload/Documentos/IPC_Ano/Ano_2026/Setembro/Nota_Explicativa_IPC_Setembro.pdf', '2026-10-31', 'No education price index series was read; school goals are planned 1 point above the 7% inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ST', 1, 'goal_inflation_health', 0.08, NULL, 'assumption', 'INE CPI (health among the faster-rising classes in 2026); inflation assumption 7%', 'https://www.ine.st/phocadownload/userupload/Documentos/IPC_Ano/Ano_2026/Setembro/Nota_Explicativa_IPC_Setembro.pdf', '2026-10-31', 'No health price index series was read beyond monthly notes; medical goals are planned 1 point above the 7% inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ST', 1, 'gold_return_base', 0.04, NULL, 'assumption', 'BCSTP official rates: dobra fixed at 24.5 per euro; long-run gold trend', 'https://www.bcstp.st/Upload/New_DOC/ES/Taxa%20de%20C%C3%A2mbio%20do%20Banco%20Central_2019-2026.xlsx', '2026-10-31', 'Base case: the long-run gold trend of about 4% a year with no currency gain under the euro peg.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ST', 1, 'gold_return_high', 0.08, NULL, 'assumption', 'BCSTP official rates: dobra fixed at 24.5 per euro', 'https://www.bcstp.st/Upload/New_DOC/ES/Taxa%20de%20C%C3%A2mbio%20do%20Banco%20Central_2019-2026.xlsx', '2026-10-31', 'High case: strong gold years.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ST', 1, 'gold_return_low', 0, NULL, 'assumption', 'BCSTP official rates: dobra fixed at 24.5 per euro', 'https://www.bcstp.st/Upload/New_DOC/ES/Taxa%20de%20C%C3%A2mbio%20do%20Banco%20Central_2019-2026.xlsx', '2026-10-31', 'Low case: flat gold in euro terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ST', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No statutory end-of-service payment on retirement was found; the 2019 Labour Code gives severance of one month''s pay per year of service (minimum three months) only on dismissal for economic reasons or without just cause (US SSA 2019).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ST', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a major hospital stay in São Tomé and Príncipe was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ST', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premiums by age were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ST', 1, 'inflation_cpi', 0.083, NULL, 'sourced', 'Instituto Nacional de Estatística (INE), Índice de Preços no Consumidor, September 2026 (published 12 October 2026)', 'https://www.ine.st/phocadownload/userupload/Documentos/IPC_Ano/Ano_2026/Setembro/Nota_Explicativa_IPC_Setembro.pdf', '2026-09-30', 'Consumer prices in the city of São Tomé rose 8.3% year on year in September 2026 (9.5% in July; 12.8% in September 2025); monthly change 0.2%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ST', 1, 'inflation_projection', 0.07, NULL, 'assumption', 'IMF second ECF review (December 2025): inflation 7.8% in 2025, programme projections 12.2% for 2026, 6.1% for 2027 and 9.7% for 2028; dobra pegged to the euro', 'https://www.imf.org/en/news/articles/2025/12/19/pr-25438-dem-rep-of-stp-imf-completes-2nd-rev-under-ecf-arrange-appr-req-ext-and-aug-of-arrange', '2026-10-31', 'The euro peg should pull inflation down over time, but it has run at 8-13% in recent years and the IMF projects 6-10% ahead, so 7% is used for planning.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ST', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published term life premium rates per 1,000 dobras of cover were found; the life insurance market is very small.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ST', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The BCSTP, which supervises insurers, publishes no life claim settlement ratio that could be found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ST', 1, 'life_expectancy', 69.905, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN), São Tomé and Príncipe', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=ST', '2024-12-31', '69.9 years in 2024 (men 66.4, women 73.9).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ST', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":17.8,"men":15.6,"women":20},{"age":65,"total":14.5,"men":12.7,"women":16.3},{"age":70,"total":11.5,"men":10.1,"women":12.8},{"age":80,"total":6.6,"men":5.9,"women":7.2}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/sao-tome-and-principe/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026; the both-sexes figure at 65 is published, the others are the mean of men and women.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ST', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension rules were found (see old_age_allowance_monthly).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ST', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension with a confirmed amount was found: the non-contributory programmes run by the Directorate of Social Protection focus mostly on children, and the minimum pension raised to 1,400 dobras in July 2026 (news report) could not be tied to a non-contributory scheme.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ST', 1, 'oop_health_share', 0.1666, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), São Tomé and Príncipe', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=ST', '2023-12-31', '16.7% in 2023 (WHO Global Health Expenditure Database via the World Bank), the latest available; older than 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ST', 1, 'policy_rate', 0.1, NULL, 'sourced', 'Banco Central de São Tomé e Príncipe (BCSTP), interest rate statistics in national currency, monthly series (reference rate of the central bank)', 'https://www.bcstp.st/Upload/New_DOC/ES/Taxas%20de%20Juro_Moeda%20Nacional_2013-2026.xlsx', '2026-07-31', 'Taxa de juro de referência of 10% in every month from December 2025 to July 2026, the latest in the series published by the BCSTP.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ST', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":62,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'US Social Security Administration, Social Security Programs Throughout the World: Africa, 2019, São Tomé and Príncipe (archived copy)', 'https://web.archive.org/web/20260209210807/https://www.ssa.gov/policy/docs/progdesc/ssptw/2018-2019/africa/sao-tome-and-principe.html', '2019-07-01', 'Compulsory INSS social insurance for employees, civil servants included (4% employee and 6% employer in the 2019 source): pension from 62 after 180 months of contributions, equal to 2.5% of average earnings in the best 10 of the last 15 years per year of contributions, up to 80%; minimum 40% of the civil-service minimum wage. Benefits are adjusted with reference to the CPI or other indicators, not automatically, so inflationLinked is false. 2019 edition, older than 2025; later contribution changes were not confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ST', 1, 'retirement_accumulation_return_base', 0.04, NULL, 'assumption', 'Deposit rates about 2.5% (BCSTP); global equity base 6%; gold base 4%', 'https://www.bcstp.st/Upload/New_DOC/ES/Taxa%20de%20C%C3%A2mbio%20do%20Banco%20Central_2019-2026.xlsx', '2026-10-31', 'Base case: a mix of local deposits, gold and, where it can be bought, a global equity fund.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ST', 1, 'retirement_accumulation_return_high', 0.06, NULL, 'assumption', 'Global equity high 9%; gold high 8%', 'https://www.bcstp.st/Upload/New_DOC/ES/Taxa%20de%20C%C3%A2mbio%20do%20Banco%20Central_2019-2026.xlsx', '2026-10-31', 'High case: a growth-leaning mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ST', 1, 'retirement_accumulation_return_low', 0.02, NULL, 'assumption', 'Deposit rates about 2.5% (BCSTP); equity low 2%', 'https://www.bcstp.st/Upload/New_DOC/ES/Taxas%20de%20Juro_Moeda%20Nacional_2013-2026.xlsx', '2026-10-31', 'Low case: mostly deposits, with weak equity and gold years.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ST', 1, 'retirement_age_default', 62, NULL, 'sourced', 'US Social Security Administration, Social Security Programs Throughout the World: Africa, 2019, São Tomé and Príncipe (archived copy)', 'https://web.archive.org/web/20260209210807/https://www.ssa.gov/policy/docs/progdesc/ssptw/2018-2019/africa/sao-tome-and-principe.html', '2019-07-01', 'Old-age pension (pensão de velhice) of the INSS at 62 with at least 180 months of contributions and 240 months of enrolment; women may retire early from 57. Secondary source read through the Internet Archive (ssa.gov refused access); the 2019 edition is older than 2025, and no later change to the age was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ST', 1, 'retirement_age_government', 62, NULL, 'sourced', 'US Social Security Administration, Social Security Programs Throughout the World: Africa, 2019, São Tomé and Príncipe (archived copy)', 'https://web.archive.org/web/20260209210807/https://www.ssa.gov/policy/docs/progdesc/ssptw/2018-2019/africa/sao-tome-and-principe.html', '2019-07-01', 'Civil servants are covered by the same INSS old-age pension, payable at 62; no separate civil-service retirement age was found. 2019 edition, older than 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ST', 1, 'retirement_return_base', 0.02, NULL, 'assumption', 'Banco Central de São Tomé e Príncipe (BCSTP), interest rate statistics in national currency, monthly series', 'https://www.bcstp.st/Upload/New_DOC/ES/Taxas%20de%20Juro_Moeda%20Nacional_2013-2026.xlsx', '2026-10-31', 'Base case kept below the 1-year term deposit rate of 2.53% (July 2026) to allow for a possible tax on interest.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ST', 1, 'retirement_return_high', 0.03, NULL, 'assumption', 'Banco Central de São Tomé e Príncipe (BCSTP), interest rate statistics in national currency, monthly series', 'https://www.bcstp.st/Upload/New_DOC/ES/Taxas%20de%20Juro_Moeda%20Nacional_2013-2026.xlsx', '2026-10-31', 'High case: deposits of over one year at about 3%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ST', 1, 'retirement_return_low', 0.015, NULL, 'assumption', 'Banco Central de São Tomé e Príncipe (BCSTP), interest rate statistics in national currency, monthly series', 'https://www.bcstp.st/Upload/New_DOC/ES/Taxas%20de%20Juro_Moeda%20Nacional_2013-2026.xlsx', '2026-10-31', 'Low case: savings and short deposits at about 2.4-2.5%, less a possible tax on interest.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ST', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate or retail savings bond for individuals was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ST', 1, 'savings_account_rate', 0.025, NULL, 'sourced', 'Banco Central de São Tomé e Príncipe (BCSTP), interest rate statistics in national currency, monthly series (savings deposits, 1 to 180 days)', 'https://www.bcstp.st/Upload/New_DOC/ES/Taxas%20de%20Juro_Moeda%20Nacional_2013-2026.xlsx', '2026-07-31', 'Average rate on savings deposits (poupança) of 1-180 days, 2.50% in July 2026; 2.63% for savings over one year.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ST', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":14.86},{"year":2040,"value":12.05},{"year":2065,"value":7.87}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://data.worldbank.org/indicator/SP.POP.DPND.OL?locations=ST', '2025-12-31', 'Working-age people per person 65+ = 100 / old-age dependency ratio. Dependency ratios used: 6.73 per 100 in 2025 (World Bank), 8.3 in 2040 (populationpyramid.net/sao-tome-and-principe/2040/) and 12.7 in 2065 (populationpyramid.net/sao-tome-and-principe/2065/, UN WPP 2024 medium variant).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ST', 1, 'tax_bank_interest', NULL, NULL, 'missing', '', '', '2026-10-31', 'The tax on bank interest for resident individuals could not be confirmed from an official source: PwC Worldwide Tax Summaries has no São Tomé page and the tax authority''s IRS code was not reached.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ST', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate exists, and the tax on government security income for individuals could not be confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ST', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 91-day bill was issued in 2025-2026: the BCSTP issue list shows irregular bills of 30 days to 1 year with one to five bidders each (40-day bill at 6.0% in July 2026, 1-year bill at 5.00% in May 2026); no channel for individuals was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ST', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 10-year Treasury bond issue was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ST', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 5-year Treasury bond issue was found.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('SV', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"SV","iso3":"SLV","nameEn":"El Salvador","nameNative":"El Salvador","region":"latin_america_caribbean","languages":["es"],"currency":{"code":"USD","symbol":"$","decimals":2,"compact":"intl","usdRate":{"value":1,"status":"sourced","sourceName":"World Bank WDI PA.NUS.FCRF","sourceUrl":"https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=SV","asOf":"2025-12-31","note":"El Salvador has used the US dollar as its currency since 2001."}},"instruments":{"savings_account":{"available":true,"localName":"Cuenta de ahorro","localNameEn":"Savings account","note":"Deposit interest is not taxed for individuals."},"fdr_3m":{"available":true,"localName":"Depósito a plazo","localNameEn":"Term deposit (90 days)","sourceUrl":"https://estadisticas.bcr.gob.sv/serie/5-1-1-2-mensual-promedio-ponderado-metodologia-2022"},"fdr_1y":{"available":true,"localName":"Depósito a plazo","localNameEn":"Term deposit (360 days)","sourceUrl":"https://estadisticas.bcr.gob.sv/serie/5-1-1-2-mensual-promedio-ponderado-metodologia-2022"},"dps":{"available":false,"localName":null,"note":"No standard monthly recurring-deposit product with a published rate was found."},"sanchayapatra_5y":{"available":false,"localName":null,"note":"No government savings certificate or retail savings bond is sold directly to individuals."},"tbill_91d":{"available":true,"localName":"Letras del Tesoro (LETES)","localNameEn":"Treasury bills","note":"Short-term Treasury bills auctioned by the Ministry of Finance."},"tbond_5y":{"available":false,"localName":null,"note":"No local-currency 5-year government bond for retail investors was found; long government debt is mainly international dollar bonds."},"tbond_10y":{"available":false,"localName":null,"note":"No retail 10-year government bond was found; long government debt is mainly international dollar bonds."},"equity_fund":{"available":false,"localName":null,"note":"No diversified local equity index fund for retail investors was found."},"gold":{"available":true,"localName":"Oro","localNameEn":"Gold","note":"Gold can be bought legally from jewellers and dealers."}},"institutions":{"centralBank":{"name":"Banco Central de Reserva de El Salvador","url":"https://www.bcr.gob.sv/"},"insuranceRegulator":{"name":"Superintendencia del Sistema Financiero (SSF)","url":"https://ssf.gob.sv/"},"insuranceComplaints":{"name":"Superintendencia del Sistema Financiero (user complaints)","url":"https://ssf.gob.sv/","note":"No separate insurance ombudsman; the SSF handles complaints about supervised insurers."},"pensionScheme":{"name":"Sistema de Ahorro para Pensiones, supervised by the Superintendencia del Sistema Financiero","url":"https://ssf.gob.sv/"},"publicHealthCover":{"name":"Ministerio de Salud (public health services)","url":"https://www.salud.gob.sv/","note":"Formal-sector workers are covered by the Instituto Salvadoreño del Seguro Social (https://www.isss.gob.sv/)."},"depositInsurance":{"name":"Instituto de Garantía de Depósitos (IGD)","url":"https://www.igd.gob.sv/"},"statistics":{"name":"Banco Central de Reserva: statistics portal","url":"https://estadisticas.bcr.gob.sv/","note":"The BCR publishes the official CPI and economic statistics."}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SV', 1, 'bank_deposit_avg_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The BCR series read gives rates by term only (180-day reference 4.67% in September 2026), not an average across all deposits; the World Bank series for El Salvador ended in 2000.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SV', 1, 'credit_card_rate_cap', 0.5608, NULL, 'sourced', 'Banco Central de Reserva: maximum legal interest rates, July-December 2026 (Ley contra la Usura)', 'https://www.bcr.gob.sv/2026/06/12/tasas-de-interes-maximas-semestre-i-2026-vigentes-de-julio-a-diciembre-de-2026/', '2026-07-01', 'Maximum effective annual rate on credit cards for credit lines above 5 minimum wages (USD 2,044); 64.43% for lines of 3-5 minimum wages and 71.73% up to 3 (USD 1,226).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SV', 1, 'deposit_insurance_limit', 12054, NULL, 'sourced', 'Instituto de Garantía de Depósitos (IGD): new deposit guarantee amount', 'https://igd.gob.sv/nuevo-monto-de-la-garantia-de-depositos-en-el-salvador/', '2026-01-01', 'USD 12,054 per person per member institution, valid 1 January 2026 to 31 December 2027.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SV', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No official series for monthly recurring deposits was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SV', 1, 'equity_return_base', 0.075, NULL, 'assumption', 'Banco Central de Reserva de El Salvador: tasas de interés, promedio ponderado mensual; 360-day deposits 5.06%, tax-free', 'https://estadisticas.bcr.gob.sv/serie/5-1-1-2-mensual-promedio-ponderado-metodologia-2022', '2026-10-31', 'The local stock market trades few shares, so we use a global equity index of about 7-8% a year in US dollars (El Salvador''s currency), within the tax-free 1-year deposit rate plus 4 points.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SV', 1, 'equity_return_high', 0.1, NULL, 'assumption', 'Banco Central de Reserva de El Salvador: tasas de interés, promedio ponderado mensual', 'https://estadisticas.bcr.gob.sv/serie/5-1-1-2-mensual-promedio-ponderado-metodologia-2022', '2026-10-31', 'High case: strong global equities in dollars.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SV', 1, 'equity_return_low', 0.04, NULL, 'assumption', 'Banco Central de Reserva de El Salvador: tasas de interés, promedio ponderado mensual', 'https://estadisticas.bcr.gob.sv/serie/5-1-1-2-mensual-promedio-ponderado-metodologia-2022', '2026-10-31', 'Low case: weak global equities in dollars.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SV', 1, 'fdr_1y_rate', 0.0506, NULL, 'sourced', 'Banco Central de Reserva de El Salvador: tasas de interés, promedio ponderado mensual', 'https://estadisticas.bcr.gob.sv/serie/5-1-1-2-mensual-promedio-ponderado-metodologia-2022', '2026-09-30', 'Weighted average rate on 360-day deposits, September 2026 (preliminary).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SV', 1, 'fdr_3m_rate', 0.0381, NULL, 'sourced', 'Banco Central de Reserva de El Salvador: tasas de interés, promedio ponderado mensual', 'https://estadisticas.bcr.gob.sv/serie/5-1-1-2-mensual-promedio-ponderado-metodologia-2022', '2026-09-30', 'Weighted average rate on 90-day deposits, September 2026 (preliminary); 30 days 3.38%, 180 days 4.67%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SV', 1, 'fixed_income_return_base', 0.045, NULL, 'assumption', 'Banco Central de Reserva de El Salvador: tasas de interés, promedio ponderado mensual', 'https://estadisticas.bcr.gob.sv/serie/5-1-1-2-mensual-promedio-ponderado-metodologia-2022', '2026-10-31', 'Base case: 180-360 day deposits at 4.7-5.1%, tax-free.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SV', 1, 'fixed_income_return_high', 0.055, NULL, 'assumption', 'Banco Central de Reserva de El Salvador: tasas de interés, promedio ponderado mensual', 'https://estadisticas.bcr.gob.sv/serie/5-1-1-2-mensual-promedio-ponderado-metodologia-2022', '2026-10-31', 'High case: 1-year deposits if rates rise with 2026 inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SV', 1, 'fixed_income_return_low', 0.035, NULL, 'assumption', 'Banco Central de Reserva de El Salvador: tasas de interés, promedio ponderado mensual', 'https://estadisticas.bcr.gob.sv/serie/5-1-1-2-mensual-promedio-ponderado-metodologia-2022', '2026-10-31', 'Low case: 30-90 day deposits at about 3.4-3.8%, tax-free.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SV', 1, 'goal_inflation_education', 0.035, NULL, 'assumption', 'Banco Central de Reserva de El Salvador: índice de precios al consumidor: education index up about 0.8% in the year to September 2026', 'https://estadisticas.bcr.gob.sv/serie/indice-de-precios-al-consumidor-ipc', '2026-10-31', 'Education prices rose little in the past year, but private tuition usually rises faster than a 2.5% headline, so we plan with 3.5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SV', 1, 'goal_inflation_health', 0.04, NULL, 'assumption', 'Banco Central de Reserva de El Salvador: índice de precios al consumidor (health index 118.44 in September 2026 vs 115.12 a year earlier, +2.9%)', 'https://estadisticas.bcr.gob.sv/serie/indice-de-precios-al-consumidor-ipc', '2026-10-31', 'Health prices rose about 2.9% in the past year; private care tends to outpace headline, so we plan with 4%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SV', 1, 'gold_return_base', 0.045, NULL, 'assumption', 'World Bank Commodity Markets (Pink Sheet) gold price', 'https://www.worldbank.org/en/research/commodity-markets', '2026-10-31', 'Long-run dollar gold trend of about 4-5% a year; no currency effect in a dollarised economy.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SV', 1, 'gold_return_high', 0.07, NULL, 'assumption', 'World Bank Commodity Markets (Pink Sheet) gold price', 'https://www.worldbank.org/en/research/commodity-markets', '2026-10-31', 'High case: strong dollar gold.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SV', 1, 'gold_return_low', 0.01, NULL, 'assumption', 'World Bank Commodity Markets (Pink Sheet) gold price', 'https://www.worldbank.org/en/research/commodity-markets', '2026-10-31', 'Low case: flat dollar gold; no currency effect since El Salvador uses the dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SV', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'A statutory payment on voluntary resignation (Ley Reguladora de la Prestación Económica por Renuncia Voluntaria) and severance on unjustified dismissal exist, but no official text could be reached to confirm the days-per-year rules.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SV', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a major private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SV', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No public premium table for private health insurance by age was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SV', 1, 'inflation_cpi', 0.036, NULL, 'sourced', 'Banco Central de Reserva de El Salvador: índice de precios al consumidor', 'https://estadisticas.bcr.gob.sv/serie/indice-de-precios-al-consumidor-ipc', '2026-09-30', 'CPI 135.60 in September 2026 vs 130.89 a year earlier: 3.6% year on year, the highest since mid-2023 (3.19% in August).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SV', 1, 'inflation_projection', 0.025, NULL, 'assumption', 'World Bank FP.CPI.TOTL.ZG (0.3% in 2025); BCR CPI 3.6% in September 2026', 'https://data.worldbank.org/indicator/FP.CPI.TOTL.ZG?locations=SV', '2026-10-31', 'El Salvador uses the US dollar and has no inflation target; inflation ranged from 0.3% (2025) to 7% (2022) in recent years, so we plan with a rounded 2.5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SV', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life is sold, but no published per-1,000 premium rates by age from the regulator or another public source were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SV', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No industry-wide life claim settlement ratio found from the Superintendencia del Sistema Financiero.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SV', 1, 'life_expectancy', 72.302, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=SV', '2024-12-31', '2024 World Bank value (older than 2025); UN WPP 2024 (via populationpyramid.net) gives 72.7 for 2026 (men 68.2, women 76.9).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SV', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":20.2,"men":18.7,"women":21.6},{"age":65,"total":16.7,"men":15.3,"women":17.7},{"age":70,"total":13,"men":12,"women":14},{"age":80,"total":7.1,"men":6.5,"women":7.6}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/el-salvador/', '2026-07-01', 'Secondary source of UN WPP 2024 medium-variant projections for 2026; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
