INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SV', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'A non-contributory basic pension for poor older people has existed, but no official source on its current amount or availability could be reached.', 0);
