INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SV', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":60,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'PwC Worldwide Tax Summaries: El Salvador, other taxes (pension system)', 'https://taxsummaries.pwc.com/el-salvador/individual/other-taxes', '2026-09-27', 'Mandatory pension savings in individual accounts at private pension fund administrators (AFPs): employee 7.25% plus employer 8.75% of salary; pension from 60 (men) or 55 (women), or after 30 years of service; the source read does not describe inflation indexing.', 0);
