INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SV', 1, 'retirement_accumulation_return_high', 0.075, NULL, 'assumption', 'Banco Central de Reserva de El Salvador: tasas de interés, promedio ponderado mensual', 'https://estadisticas.bcr.gob.sv/serie/5-1-1-2-mensual-promedio-ponderado-metodologia-2022', '2026-10-31', 'High case with strong equities.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SV', 1, 'retirement_accumulation_return_low', 0.04, NULL, 'assumption', 'Banco Central de Reserva de El Salvador: tasas de interés, promedio ponderado mensual', 'https://estadisticas.bcr.gob.sv/serie/5-1-1-2-mensual-promedio-ponderado-metodologia-2022', '2026-10-31', 'Low case for a balanced mix of deposits and global equities.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SV', 1, 'retirement_age_default', 60, NULL, 'sourced', 'PwC Worldwide Tax Summaries: El Salvador, other taxes (pension system)', 'https://taxsummaries.pwc.com/el-salvador/individual/other-taxes', '2026-09-27', 'Pension age 60 for men and 55 for women, or after 30 years of service regardless of age.', 0);
