INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('SY', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"SY","iso3":"SYR","nameEn":"Syria","nameNative":"سوريا","region":"middle_east_north_africa","languages":["ar","ku","en","fr","hy"],"currency":{"code":"SYP","symbol":"ل.س","decimals":0,"compact":"intl","usdRate":{"value":122,"status":"sourced","sourceName":"Central Bank of Syria, official exchange-rate bulletin (new pound)","sourceUrl":"https://cb.gov.sy/fx","asOf":"2026-10-29","note":"122.00 new Syrian pounds per US dollar in the official bulletin of 29 October 2026 (Trading Economics shows 122.02 on 30 October); rates are quoted in the new pound, so all money figures here are in new pounds. The bank''s site carries a demo-version banner. CLDR''s ''£'' is replaced by the local abbreviation ل.س."}},"instruments":{"savings_account":{"available":true,"localName":"حساب توفير","localNameEn":"Savings account"},"fdr_3m":{"available":true,"localName":"وديعة لأجل (3 أشهر)","localNameEn":"Time deposit (3 months)"},"fdr_1y":{"available":true,"localName":"وديعة لأجل (سنة)","localNameEn":"Time deposit (1 year)","note":"The latest published average rate on 1-year pound deposits is 8.07% (March 2022).","sourceUrl":"https://cb.gov.sy/statistics/4"},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No standard monthly recurring deposit product was found."},"sanchayapatra_5y":{"available":true,"localName":"شهادات الاستثمار","localNameEn":"Investment certificates","note":"Government-backed investment certificates were sold to the public; the Central Bank of Syria series of amounts outstanding ends in June 2022 and current terms were not found.","sourceUrl":"https://cb.gov.sy/statistics/26"},"tbill_91d":{"available":true,"localName":"أذون الخزينة","localNameEn":"Treasury bills","note":"Bills under one year are auctioned to banks; the latest listed issue is from 2024.","sourceUrl":"https://cb.gov.sy/pages/587"},"tbond_5y":{"available":true,"localName":"سندات الخزينة","localNameEn":"Treasury bonds","note":"Bonds of 1 to 30 years are auctioned to banks; the latest listed issue is from 2024.","sourceUrl":"https://cb.gov.sy/pages/587"},"tbond_10y":{"available":true,"localName":"سندات الخزينة","localNameEn":"Treasury bonds","note":"Bonds of 1 to 30 years are auctioned to banks; the latest listed issue is from 2024.","sourceUrl":"https://cb.gov.sy/pages/587"},"equity_fund":{"available":false,"localName":null,"localNameEn":null,"note":"No diversified mutual or index fund for retail investors was found; only individual shares trade on the local exchange."},"gold":{"available":true,"localName":"الذهب","localNameEn":"Gold","note":"Gold coins, small bars and jewellery are widely bought as savings."}},"institutions":{"centralBank":{"name":"Central Bank of Syria","url":"https://cb.gov.sy/"},"insuranceRegulator":null,"insuranceComplaints":null,"pensionScheme":null,"oldAgeAllowance":null,"publicHealthCover":null,"depositInsurance":null,"statistics":null},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
