INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SY', 1, 'equity_return_base', 0.11, NULL, 'assumption', 'Central Bank of Syria 1-year deposit rate 8.07% (2022); market lending rate 16.23% (June 2026)', 'https://cb.gov.sy/statistics/4', '2026-10-31', 'Base case: about 3 points above the deposit rate, within the 4-point cap, because the local index has a weak, war-distorted 10-year record.', 0);
