INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SY', 1, 'fdr_1y_rate', 0.0807, NULL, 'sourced', 'Central Bank of Syria, weighted average market interest rate on 1-year customer deposits in Syrian pounds', 'https://cb.gov.sy/statistics/4', '2022-03-31', '8.07% in March 2022, the latest value published; older than 2025 and far below current inflation, so treat it as indicative only.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SY', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 3-month deposit rate is published by the Central Bank of Syria.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SY', 1, 'fixed_income_return_base', 0.07, NULL, 'assumption', 'Central Bank of Syria 1-year deposit rate 8.07% (2022)', 'https://cb.gov.sy/statistics/4', '2026-10-31', 'Base case: a little below the last published 1-year deposit rate to allow for tax on interest, which could not be confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SY', 1, 'fixed_income_return_high', 0.1, NULL, 'assumption', 'Central Bank of Syria 1-year deposit rate 8.07% (2022); market lending rate 16.23% (June 2026)', 'https://cb.gov.sy/statistics/4', '2026-10-31', 'High case: deposit rates rise toward inflation as monetary policy normalises.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SY', 1, 'fixed_income_return_low', 0.05, NULL, 'assumption', 'Central Bank of Syria 1-year deposit rate 8.07% (2022)', 'https://cb.gov.sy/statistics/4', '2026-10-31', 'Low case: deposit rates below the last published level, before any tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SY', 1, 'goal_inflation_education', 0.17, NULL, 'assumption', 'Inflation assumption 15%; latest CPI 24.8% (July 2026)', 'https://tradingeconomics.com/syria/inflation-cpi', '2026-10-31', 'No education CPI was found; private schooling costs tend to rise faster than prices, so 2 points above the inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SY', 1, 'goal_inflation_health', 0.17, NULL, 'assumption', 'Inflation assumption 15%; latest CPI 24.8% (July 2026)', 'https://tradingeconomics.com/syria/inflation-cpi', '2026-10-31', 'No medical CPI was found; with most health spending paid out of pocket and many imported medicines, 2 points above the inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SY', 1, 'gold_return_base', 0.14, NULL, 'assumption', 'Official rate 122 new pounds per USD (October 2026); inflation assumption 15%; long-run dollar gold trend', 'https://cb.gov.sy/fx', '2026-10-31', 'Base case: dollar gold up about 4% a year plus about 10% a year of pound depreciation, in line with the inflation gap to the dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SY', 1, 'gold_return_high', 0.25, NULL, 'assumption', 'Official rate 122 new pounds per USD (October 2026); latest inflation 24.8%', 'https://cb.gov.sy/fx', '2026-10-31', 'High case: renewed pound weakness at today''s inflation rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SY', 1, 'gold_return_low', 0.06, NULL, 'assumption', 'Official rate 122 new pounds per USD (October 2026); inflation assumption 15%', 'https://cb.gov.sy/fx', '2026-10-31', 'Low case: flat dollar gold with modest pound depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SY', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No statutory end-of-service gratuity rule for private employees could be confirmed; the labour law text could not be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SY', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a major private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SY', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premiums by age were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SY', 1, 'inflation_cpi', 0.248, NULL, 'sourced', 'Trading Economics, citing the Syrian Center for Policy Research, CPI July 2026', 'https://tradingeconomics.com/syria/inflation-cpi', '2026-07-31', 'Consumer prices up 24.8% year on year in July 2026 (40.5% in June); secondary source because no official 2026 CPI was found (the Central Bank of Syria price-index series stops in 2020). World Bank data stops in 2019.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SY', 1, 'inflation_projection', 0.15, NULL, 'assumption', 'Latest CPI 24.8% (July 2026) after 40.5% in June; exchange rate stable near 122 new pounds per dollar', 'https://tradingeconomics.com/syria/inflation-cpi', '2026-10-31', 'There is no credible inflation target and inflation is falling fast from very high levels with a steadier pound, so a rounded 15% a year is used, well below today''s rate but far above stable economies.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SY', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published term-life premium rates per 1,000 pounds of cover were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SY', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No industry-wide life claim settlement ratio was found from the insurance supervisor.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SY', 1, 'life_expectancy', 72.56, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN), Syria', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=SY', '2024-12-31', '72.6 years in 2024 (men 70.2, women 74.9).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SY', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":19.2,"men":17.7,"women":20.7},{"age":65,"total":15.4,"men":14.1,"women":16.6},{"age":70,"total":11.9,"men":10.9,"women":12.9},{"age":80,"total":6.5,"men":5.9,"women":7}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/syrian-arab-republic/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SY', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension eligibility rules could be confirmed from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SY', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age (social) pension and amount could be confirmed from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SY', 1, 'oop_health_share', 0.724, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), Syria', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=SY', '2023-12-31', '72.4% in 2023 (WHO Global Health Expenditure Database via the World Bank); older than 2025, the latest available.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SY', 1, 'policy_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Central Bank of Syria site shows no policy rate; only the weighted average market lending rate (16.23% in June 2026) is published.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SY', 1, 'public_pension_scheme', NULL, NULL, 'missing', '', '', '2026-10-31', 'A contributory social insurance scheme covers public and private employees, but its pension age, indexation and tax rules could not be read from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SY', 1, 'retirement_accumulation_return_base', 0.1, NULL, 'assumption', 'Deposit rate 8.07% (2022); equity base 11%; gold base 14%', 'https://cb.gov.sy/statistics/4', '2026-10-31', 'Base case: a mix of deposits, some local shares and a larger gold share, as is common where the currency is weak.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SY', 1, 'retirement_accumulation_return_high', 0.15, NULL, 'assumption', 'Equity high 18%; gold high 25%; inflation 24.8% (July 2026)', 'https://tradingeconomics.com/syria/inflation-cpi', '2026-10-31', 'High case: a growth and gold-leaning mix that keeps pace with high inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SY', 1, 'retirement_accumulation_return_low', 0.06, NULL, 'assumption', 'Central Bank of Syria 1-year deposit rate 8.07% (2022); equity low case 5%; gold low case 6%', 'https://cb.gov.sy/statistics/4', '2026-10-31', 'Low case: a mix earning about deposit rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SY', 1, 'retirement_age_default', NULL, NULL, 'missing', '', '', '2026-10-31', 'The private-sector pension age under the social insurance law could not be confirmed from an official or allowed secondary source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SY', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'The retirement age for government employees could not be confirmed from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SY', 1, 'retirement_return_base', 0.07, NULL, 'assumption', 'Central Bank of Syria 1-year deposit rate 8.07% (2022)', 'https://cb.gov.sy/statistics/4', '2026-10-31', 'Base case: below the last published 1-year deposit rate, allowing for tax on interest that could not be confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SY', 1, 'retirement_return_high', 0.09, NULL, 'assumption', 'Central Bank of Syria 1-year deposit rate 8.07% (2022); market lending rate 16.23% (June 2026)', 'https://cb.gov.sy/statistics/4', '2026-10-31', 'High case: deposit rates rise somewhat as policy normalises.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SY', 1, 'retirement_return_low', 0.05, NULL, 'assumption', 'Central Bank of Syria 1-year deposit rate 8.07% (2022)', 'https://cb.gov.sy/statistics/4', '2026-10-31', 'Low case: deposit rates below the last published level.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SY', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Investment certificates (شهادات الاستثمار) were sold to the public (Central Bank of Syria series of amounts outstanding, to June 2022), but no current rate or terms were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SY', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No savings-account rate is published; the Central Bank of Syria deposit-rate series covers only 1-year deposits and stops in March 2022.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SY', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":13.8},{"year":2040,"value":9.1},{"year":2065,"value":4.5}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/syrian-arab-republic/2040/', '2025-12-31', '100 / old-age dependency ratio: 7.25 (2025, World Bank), 11.0 (2040) and 22.0 (2065, populationpyramid.net/syrian-arab-republic/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SY', 1, 'tax_bank_interest', NULL, NULL, 'missing', '', '', '2026-10-31', 'The tax rate on bank interest for individuals could not be confirmed from an official source; no PwC Tax Summary covers Syria.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SY', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'The tax treatment of investment-certificate returns could not be confirmed from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SY', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Central Bank of Syria lists treasury bill and bond auction results up to issue 6 of 2024 only as PDF titles; no yield could be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SY', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Treasury bonds of 1 to 30 years are auctioned (latest listed issue 6 of 2024), but no 10-year yield could be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SY', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Treasury bonds of 1 to 30 years are auctioned (latest listed issue 6 of 2024), but no yield could be read.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('SZ', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"SZ","iso3":"SWZ","nameEn":"Eswatini","nameNative":"eSwatini","region":"sub_saharan_africa","languages":["ss","en","zu","ts"],"currency":{"code":"SZL","symbol":"E","decimals":2,"compact":"intl","usdRate":{"value":16.23,"status":"sourced","sourceName":"Central Bank of Eswatini, Recent Economic Developments August/September 2026 (exchange rate section)","sourceUrl":"https://www.centralbank.org.sz/wp-content/uploads/2021/04/RED-August_September-2026.pdf","asOf":"2026-09-30","note":"Average of E16.23 per US dollar in September 2026 (World Bank 2025 average 17.89). The lilangeni is pegged one to one to the South African rand, which also circulates as legal tender."}},"instruments":{"savings_account":{"available":true,"localName":null,"localNameEn":"Savings account","note":"Rates of about 2-4% on ordinary balances at end June 2026 (Central Bank of Eswatini).","sourceUrl":"https://www.centralbank.org.sz/wp-content/uploads/2026/09/CBE-Quarterly-Review_June-2026-Online.pdf"},"fdr_3m":{"available":true,"localName":null,"localNameEn":"Fixed deposit (88 days / 3 months)","note":"Short fixed deposits are offered; 88-day rates were about 1-3.35% at end June 2026.","sourceUrl":"https://www.centralbank.org.sz/wp-content/uploads/2026/09/CBE-Quarterly-Review_June-2026-Online.pdf"},"fdr_1y":{"available":true,"localName":null,"localNameEn":"Fixed deposit (12 months)","note":"Average 12-month deposit rate 5.03% in August 2026.","sourceUrl":"https://www.centralbank.org.sz/wp-content/uploads/2021/04/RED-August_September-2026.pdf"},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No standard monthly recurring deposit product was found in the central bank''s rate tables."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate or retail savings bond for individuals was found."},"tbill_91d":{"available":true,"localName":null,"localNameEn":"Treasury bills","note":"Treasury bills are auctioned by the central bank; holders include individuals and other investors (Quarterly Review June 2026).","sourceUrl":"https://www.centralbank.org.sz/wp-content/uploads/2026/09/CBE-Quarterly-Review_June-2026-Online.pdf"},"tbond_5y":{"available":true,"localName":null,"localNameEn":"Government bonds","note":"Bond auctions are open to individuals through primary dealers, minimum E10,000 for non-competitive bids.","sourceUrl":"https://www.centralbank.org.sz/wp-content/uploads/2026/10/Bond-Advert-Oct-2026.pdf"},"tbond_10y":{"available":true,"localName":null,"localNameEn":"Government bonds (10 years)","note":"10-year benchmark bonds are reopened at regular auctions open to individuals.","sourceUrl":"https://www.centralbank.org.sz/wp-content/uploads/2026/10/Bond-Advert-Oct-2026.pdf"},"equity_fund":{"available":true,"localName":null,"localNameEn":"Unit trusts (collective investment schemes)","note":"Collective investment schemes are licensed by the Financial Services Regulatory Authority; most invest in South African and global markets.","sourceUrl":"https://www.fsra.co.sz/capital-markets/"},"gold":{"available":true,"localName":null,"localNameEn":"Gold","note":"Gold jewellery and coins can be bought; no official local bullion scheme was found."}},"institutions":{"centralBank":{"name":"Central Bank of Eswatini","url":"https://www.centralbank.org.sz/"},"insuranceRegulator":{"name":"Financial Services Regulatory Authority (FSRA)","url":"https://www.fsra.co.sz/"},"insuranceComplaints":{"name":"FSRA complaints handling","url":"https://www.fsra.co.sz/complaints-handling/"},"pensionScheme":{"name":"Eswatini National Provident Fund (ENPF)","url":"https://enpf.co.sz/","note":"A lump-sum provident fund for private-sector workers; civil servants belong to the Public Service Pensions Fund (pspf.co.sz)."}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SZ', 1, 'bank_deposit_avg_rate', 0.039, NULL, 'sourced', 'World Bank WDI, deposit interest rate (FR.INR.DPST), Eswatini', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=SZ', '2024-12-31', '3.90% average for 2024 (older than 2025); the central bank''s August 2026 averages were 2.31% for 31 days and 5.03% for 12 months.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SZ', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap or typical credit card rate was found; banks'' prime lending rate was 10.50% from September 2026 (Central Bank of Eswatini).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SZ', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'The deposit insurance cover per depositor could not be confirmed; the deposit insurance fund''s website was not reachable and the central bank reports read do not state it.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SZ', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No standard monthly recurring deposit product or published rate was found in the central bank''s interest rate tables.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SZ', 1, 'equity_return_base', 0.085, NULL, 'assumption', 'Central Bank of Eswatini: very small local stock exchange; retail unit trusts invest mostly in South African and global markets; lilangeni pegged to the rand', 'https://www.centralbank.org.sz/wp-content/uploads/2021/04/Annual-Economic-Review-Report-1.pdf', '2026-10-31', 'The local exchange is too small to guide, so equity means rand-based unit trusts tracking South African and global shares; held at about 4 points above the after-tax 12-month deposit rate (5.03% less 10% withholding, about 4.5%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SZ', 1, 'equity_return_high', 0.12, NULL, 'assumption', 'Central Bank of Eswatini: very small local stock exchange; retail unit trusts invest mostly in South African and global markets; lilangeni pegged to the rand', 'https://www.centralbank.org.sz/wp-content/uploads/2021/04/Annual-Economic-Review-Report-1.pdf', '2026-10-31', 'High case: South African and global equities repeat their long-run record in rand terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SZ', 1, 'equity_return_low', 0.05, NULL, 'assumption', 'Central Bank of Eswatini: very small local stock exchange; retail unit trusts invest mostly in South African and global markets; lilangeni pegged to the rand', 'https://www.centralbank.org.sz/wp-content/uploads/2021/04/Annual-Economic-Review-Report-1.pdf', '2026-10-31', 'Low case: a weak decade for South African and global equities in rand terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SZ', 1, 'fdr_1y_rate', 0.0503, NULL, 'sourced', 'Central Bank of Eswatini, Recent Economic Developments August/September 2026 (economic indicators: deposit rate 12 months)', 'https://www.centralbank.org.sz/wp-content/uploads/2021/04/RED-August_September-2026.pdf', '2026-08-31', 'Average 12-month deposit rate 5.03% in August 2026, unchanged since February 2026; the 31-day rate averaged 2.31%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SZ', 1, 'fdr_3m_rate', 0.03, NULL, 'sourced', 'Central Bank of Eswatini, Quarterly Review June 2026, Table 2 (comparative interest rates, 88-day deposits)', 'https://www.centralbank.org.sz/wp-content/uploads/2026/09/CBE-Quarterly-Review_June-2026-Online.pdf', '2026-06-30', '88-day term deposit rates at end June 2026 ranged from about 1.1% to 3.35% across banks (6-month rates 3.2-6.45%); 3% is the typical rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SZ', 1, 'fixed_income_return_base', 0.05, NULL, 'assumption', 'Central Bank of Eswatini deposit and treasury bill rates (August 2026); 10% withholding on interest (Eswatini Revenue Service)', 'https://www.centralbank.org.sz/wp-content/uploads/2021/04/RED-August_September-2026.pdf', '2026-10-31', 'Base case: a mix of 12-month deposits (5.03%, 4.5% after tax) and treasury bills or bonds (7.9-10%), net of tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SZ', 1, 'fixed_income_return_high', 0.07, NULL, 'assumption', 'Central Bank of Eswatini deposit and treasury bill rates (August 2026); 10% withholding on interest (Eswatini Revenue Service)', 'https://www.centralbank.org.sz/wp-content/uploads/2026/10/Bond-Advert-Oct-2026.pdf', '2026-10-31', 'High case: mostly government bonds bought through primary dealers (coupons 10-11%), net of tax and price risk.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SZ', 1, 'fixed_income_return_low', 0.03, NULL, 'assumption', 'Central Bank of Eswatini deposit and treasury bill rates (August 2026); 10% withholding on interest (Eswatini Revenue Service)', 'https://www.centralbank.org.sz/wp-content/uploads/2021/04/RED-August_September-2026.pdf', '2026-10-31', 'Low case: savings accounts and short deposits around 3%, less 10% withholding.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SZ', 1, 'goal_inflation_education', 0.06, NULL, 'assumption', 'Central Bank of Eswatini Annual Economic Review 2025/26 (CPI by COICOP category); planning inflation 4%', 'https://www.centralbank.org.sz/wp-content/uploads/2021/04/Annual-Economic-Review-Report-1.pdf', '2026-10-31', 'No separate education price series was readable; school and tertiary fees in the region rise about 2 points above headline inflation, so 6% is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SZ', 1, 'goal_inflation_health', 0.06, NULL, 'assumption', 'Central Bank of Eswatini Annual Economic Review 2025/26 (CPI by COICOP category); planning inflation 4%', 'https://www.centralbank.org.sz/wp-content/uploads/2021/04/Annual-Economic-Review-Report-1.pdf', '2026-10-31', 'No separate health price series was readable; private medical costs and medical aid contributions in the region rise about 2 points above headline inflation, so 6% is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SZ', 1, 'gold_return_base', 0.065, NULL, 'assumption', 'Lilangeni pegged to the South African rand; dollar gold trend plus long-run rand depreciation', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=SZ', '2026-10-31', 'Base case: about 4% dollar gold trend plus 2-3% a year of rand depreciation against the dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SZ', 1, 'gold_return_high', 0.1, NULL, 'assumption', 'Lilangeni pegged to the South African rand; dollar gold trend plus long-run rand depreciation', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=SZ', '2026-10-31', 'High case: strong gold years with a weaker rand.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SZ', 1, 'gold_return_low', 0.01, NULL, 'assumption', 'Lilangeni pegged to the South African rand; dollar gold trend plus long-run rand depreciation', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=SZ', '2026-10-31', 'Low case: flat dollar gold with a slightly firmer rand.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SZ', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Employment Act provisions on severance or end-of-service pay could not be read from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SZ', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a major private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SZ', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private medical aid premiums by age were found from a public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SZ', 1, 'inflation_cpi', 0.028, NULL, 'sourced', 'Central Bank of Eswatini, Monetary Policy Statement of 25 September 2026', 'https://www.centralbank.org.sz/wp-content/uploads/2021/04/Monetary-Policy-Statement-Sept.pdf', '2026-08-31', 'Headline consumer inflation 2.8% year on year in August 2026 (2.5% in July); Central Statistical Office data reported by the central bank, whose site showed 2.9% for September 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SZ', 1, 'inflation_projection', 0.04, NULL, 'assumption', 'Central Bank of Eswatini forecasts (3.86% for 2027, 3.45% for 2028); IMF WEO average 2021-2025 about 4.1%', 'https://www.centralbank.org.sz/wp-content/uploads/2021/04/Monetary-Policy-Statement-Sept.pdf', '2026-10-31', 'The lilangeni is pegged one to one to the South African rand, so inflation tracks South Africa''s; the central bank''s medium-term forecasts of 3.5-3.9% and the 5-year average of about 4.1% round to 4%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SZ', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published indicative term life premium rates per E1,000 of cover were found from the regulator or a public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SZ', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No industry-wide life claim settlement ratio was found from the Financial Services Regulatory Authority.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SZ', 1, 'life_expectancy', 64.264, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN), Eswatini', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=SZ', '2024-12-31', '64.3 years in 2024 (men 61.3, women 67.1); latest available, older than 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SZ', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":17.1,"men":15.8,"women":18.3},{"age":65,"total":14.3,"men":13.1,"women":15.1},{"age":70,"total":11.5,"men":10.8,"women":12.2},{"age":80,"total":6.9,"men":6.6,"women":7.2}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/swaziland/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026; totals at 60, 70 and 80 are the mean of men and women (the page gives a both-sexes figure only at 65).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SZ', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'The eligibility rules of the non-contributory Old Age Grant could not be confirmed from an official source; the government portal (gov.sz) was not reachable.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SZ', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'The amount of the non-contributory Old Age Grant could not be confirmed from an official source; the government portal (gov.sz) was not reachable and the central bank reports read do not state it.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SZ', 1, 'oop_health_share', 0.1102, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), Eswatini', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=SZ', '2023-12-31', '11.0% in 2023 (WHO Global Health Expenditure Database via the World Bank), the latest available; older than 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SZ', 1, 'policy_rate', 0.07, NULL, 'sourced', 'Central Bank of Eswatini, Monetary Policy Statement of 25 September 2026 (discount rate)', 'https://www.centralbank.org.sz/wp-content/uploads/2021/04/Monetary-Policy-Statement-Sept.pdf', '2026-09-26', 'Discount rate raised by 25 basis points to 7.00% effective 26 September 2026; banks'' prime lending rate moved to 10.50%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SZ', 1, 'public_pension_scheme', NULL, NULL, 'missing', '', '', '2026-10-31', 'No public lifetime pension for private-sector workers was confirmed: the Eswatini National Provident Fund pays a lump-sum age benefit from 50 (enpf.co.sz/age-benefits/), and PwC Worldwide Tax Summaries (reviewed 30 March 2026) says there are no social security contributions. Civil servants have a defined-benefit pension (PSPF, 2% of final salary per year of service from 60).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SZ', 1, 'retirement_accumulation_return_base', 0.07, NULL, 'assumption', 'Safe rate about 4.5-5%; rand-based equity base 8.5%; gold base 6.5%', 'https://www.centralbank.org.sz/wp-content/uploads/2021/04/Annual-Economic-Review-Report-1.pdf', '2026-10-31', 'Base case: a balanced mix of government bonds, deposits and rand-based equity unit trusts.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SZ', 1, 'retirement_accumulation_return_high', 0.09, NULL, 'assumption', 'Safe rate about 4.5-5%; rand-based equity base 8.5%; gold base 6.5%', 'https://www.centralbank.org.sz/wp-content/uploads/2021/04/Annual-Economic-Review-Report-1.pdf', '2026-10-31', 'High case: a growth-leaning mix with more equity.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SZ', 1, 'retirement_accumulation_return_low', 0.045, NULL, 'assumption', 'Safe rate about 4.5-5%; rand-based equity base 8.5%; gold base 6.5%', 'https://www.centralbank.org.sz/wp-content/uploads/2021/04/RED-August_September-2026.pdf', '2026-10-31', 'Low case: mostly deposits and bills.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SZ', 1, 'retirement_age_default', 50, NULL, 'sourced', 'Eswatini National Provident Fund (ENPF), age benefit', 'https://enpf.co.sz/age-benefits/', '2026-10-31', 'Private-sector workers belong to the ENPF, a provident fund that pays a lump-sum age benefit from 50 (or from 45 on retirement from regular employment); there is no statutory lifetime pension age for the private sector. Same for men and women.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SZ', 1, 'retirement_age_government', 60, NULL, 'sourced', 'Public Service Pensions Fund (PSPF), retirement benefits', 'https://pspf.co.sz/retirement-benefits/', '2026-10-31', 'Compulsory retirement at 60 for civil servants (judges at 75); early retirement from 45 with at least 10 years of service.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SZ', 1, 'retirement_return_base', 0.045, NULL, 'assumption', 'Central Bank of Eswatini: 12-month deposit rate 5.03% and treasury bill rate 7.93% (August 2026); 10% withholding on interest', 'https://www.centralbank.org.sz/wp-content/uploads/2021/04/RED-August_September-2026.pdf', '2026-10-31', 'Base case: equal to the 12-month deposit rate after 10% withholding (5.03% x 0.9), below the after-tax treasury bill rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SZ', 1, 'retirement_return_high', 0.065, NULL, 'assumption', 'Central Bank of Eswatini: 12-month deposit rate 5.03% and treasury bill rate 7.93% (August 2026); 10% withholding on interest', 'https://www.centralbank.org.sz/wp-content/uploads/2026/10/Bond-Advert-Oct-2026.pdf', '2026-10-31', 'High case: more in treasury bills and government bonds, after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SZ', 1, 'retirement_return_low', 0.03, NULL, 'assumption', 'Central Bank of Eswatini: 12-month deposit rate 5.03% and treasury bill rate 7.93% (August 2026); 10% withholding on interest', 'https://www.centralbank.org.sz/wp-content/uploads/2021/04/RED-August_September-2026.pdf', '2026-10-31', 'Low case: savings and short deposits after 10% withholding.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SZ', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate or retail savings bond for individuals was found; individuals can buy ordinary government bonds through primary dealers (minimum E10,000).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SZ', 1, 'savings_account_rate', 0.03, NULL, 'sourced', 'Central Bank of Eswatini, Quarterly Review June 2026, Table 3 (savings deposit rates for banks and building society)', 'https://www.centralbank.org.sz/wp-content/uploads/2026/09/CBE-Quarterly-Review_June-2026-Online.pdf', '2026-06-30', 'Ordinary savings balances earned about 2.2-4.0% at end June 2026 depending on the bank and balance (higher balances up to about 6%); 3% is the typical rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SZ', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":14.4},{"year":2040,"value":12.5},{"year":2065,"value":6.1}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://data.worldbank.org/indicator/SP.POP.DPND.OL?locations=SZ', '2025-12-31', '100 / old-age dependency ratio: 6.94 (2025, World Bank), 8.0 (2040, populationpyramid.net/swaziland/2040/) and 16.5 (2065, populationpyramid.net/swaziland/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SZ', 1, 'tax_bank_interest', 0.1, NULL, 'sourced', 'Eswatini Revenue Service, Rates and Thresholds (withholding tax on interest paid to residents)', 'https://www.ers.org.sz/IncomeTax/RatesandThres', '2026-10-31', 'Withholding tax of 10% on interest paid to residents, due by the 15th of the following month (ERS Rates and Thresholds, re-read on verification).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SZ', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate for individuals exists; the tax treatment of government bond interest for individuals was not confirmed separately from the 10% withholding on interest.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SZ', 1, 'tbill_91d_rate', 0.0793, NULL, 'sourced', 'Central Bank of Eswatini, Recent Economic Developments August/September 2026 (economic indicators: T. bill rate)', 'https://www.centralbank.org.sz/wp-content/uploads/2021/04/RED-August_September-2026.pdf', '2026-08-31', 'Treasury bill rate 7.93% in August 2026 (7.88-7.98% since February); the central bank does not split it by tenor in this table. The June 2026 Quarterly Review gives an average yield of 8.35%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SZ', 1, 'tbond_10y_rate', 0.11, NULL, 'sourced', 'Central Bank of Eswatini, Government Bonds advert October 2026 (SG147, maturing 31 March 2036)', 'https://www.centralbank.org.sz/wp-content/uploads/2026/10/Bond-Advert-Oct-2026.pdf', '2026-10-28', 'Fixed coupon of the 10-year benchmark bond SG147 reopened at the 28 October 2026 auction; this is the coupon, not the auction yield, and recent issues sold at a premium (yield below coupon).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('SZ', 1, 'tbond_5y_rate', 0.1025, NULL, 'sourced', 'Central Bank of Eswatini, Government Bonds advert October 2026 (SG145, maturing 31 March 2031)', 'https://www.centralbank.org.sz/wp-content/uploads/2026/10/Bond-Advert-Oct-2026.pdf', '2026-10-28', 'Fixed coupon of the 5-year benchmark bond SG145 reopened at the 28 October 2026 auction; this is the coupon, not the auction yield, and recent issues sold at a premium (yield below coupon).', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('TD', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"TD","iso3":"TCD","nameEn":"Chad","nameNative":"Tchad","region":"sub_saharan_africa","languages":["shu","fr","ar"],"currency":{"code":"XAF","symbol":"FCFA","decimals":0,"compact":"intl","usdRate":{"value":581.928,"status":"sourced","sourceName":"World Bank WDI, official exchange rate (PA.NUS.FCRF), Chad","sourceUrl":"https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=TD","asOf":"2025-12-31","note":"2025 average. The franc CFA is fixed at 655.957 per euro, so the dollar rate moves with the euro; the BEAC indicative rate on 30 October 2026 was about 586-591 per dollar (buy/sell)."}},"instruments":{"savings_account":{"available":true,"localName":"Compte d''épargne","localNameEn":"Savings account","note":"Banks must pay at least the BEAC minimum savings rate (2.45%).","sourceUrl":"https://www.beac.int/wp-content/uploads/2018/11/Rapport-sur-La-Politique-Mon%C3%A9taire-de-la-BEAC_Sept-2026_vf_new2_Publiable.pdf"},"fdr_3m":{"available":true,"localName":"Dépôt à terme (3 mois)","localNameEn":"Term deposit (3 months)","note":"Banks take term deposits (the BEAC sets reserve requirements on them), but rates are not published."},"fdr_1y":{"available":true,"localName":"Dépôt à terme (1 an)","localNameEn":"Term deposit (1 year)","note":"Banks take term deposits, but rates are not published."},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No standard monthly recurring deposit product was found."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate for individuals was found; individuals hold Chad Treasury bonds (see the 5-year slot) instead."},"tbill_91d":{"available":false,"localName":"Bons du Trésor assimilables (BTA)","localNameEn":"Treasury bills","note":"Treasury bills are auctioned to banks and primary dealers; individuals held almost none (XAF 0.01 billion) in January 2026 (BEAC).","sourceUrl":"https://www.beac.int/wp-content/uploads/2021/10/Statistiques-Mensuelles-du-March%C3%A9-des-valeurs-du-Tr%C3%A9sors-de-la-CEMAC-janvier-2026.pdf"},"tbond_5y":{"available":true,"localName":"Obligations du Trésor assimilables (OTA)","localNameEn":"Treasury bonds","note":"Treasury bonds are auctioned or offered to the public; individuals held about XAF 108.6 billion of Chad bonds in January 2026 (BEAC).","sourceUrl":"https://www.beac.int/wp-content/uploads/2021/10/Statistiques-Mensuelles-du-March%C3%A9-des-valeurs-du-Tr%C3%A9sors-de-la-CEMAC-janvier-2026.pdf"},"tbond_10y":{"available":false,"localName":null,"localNameEn":null,"note":"No 10-year Treasury bond for Chad was found in the BEAC statistics."},"equity_fund":{"available":false,"localName":null,"localNameEn":null,"note":"No locally sold diversified equity fund was found; the regional exchange (BVMAC) lists very few companies."},"gold":{"available":true,"localName":"Or","localNameEn":"Gold","note":"Gold is sold mainly as jewellery and from artisanal mining; no official bullion or coin scheme was found."}},"institutions":{"centralBank":{"name":"Bank of Central African States (Banque des États de l''Afrique Centrale, BEAC)","url":"https://www.beac.int/"},"insuranceRegulator":{"name":"Inter-African Conference on Insurance Markets (CIMA), regional insurance regulator, with the national insurance directorate","url":"https://cima-afrique.org/"},"insuranceComplaints":{"name":"CIMA policyholder requests and complaints form","url":"https://cima-afrique.org/faites-votre-requetes-ici-2/"},"pensionScheme":{"name":"National Social Welfare Fund (Caisse Nationale de Prévoyance Sociale, CNPS)","url":"https://cnps-tchad.org/"},"oldAgeAllowance":null,"publicHealthCover":{"name":"Ministry of Public Health (public health services)","url":"https://sante.gouv.td/"},"depositInsurance":{"name":"Deposit Guarantee Fund of Central Africa (Fonds de Garantie des Dépôts en Afrique Centrale, FOGADAC)","url":"https://www.fogadac.com/"},"statistics":{"name":"National Institute of Statistics, Economic and Demographic Studies (INSEED)","url":"https://inseed.td/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TD', 1, 'bank_deposit_avg_rate', 0.0245, NULL, 'sourced', 'World Bank WDI, deposit interest rate (FR.INR.DPST), Chad', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=TD', '2016-12-31', '2.45% in 2016, the latest World Bank value (older than 2025); it equals the BEAC minimum savings rate (Taux Créditeur Minimum), which is unchanged at 2.45% in the BEAC September 2026 report.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TD', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap or typical credit card rate was found; the BEAC reports an average effective lending rate (TEG) of 8.47% in Chad in Q2 2026, but not for cards.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TD', 1, 'deposit_insurance_limit', 8000000, NULL, 'sourced', 'Deposit Guarantee Fund of Central Africa (FOGADAC), FAQ', 'https://www.fogadac.com/faq', '2026-10-31', 'FOGADAC covers deposits up to XAF 8 million for individuals (XAF 15 million for legal persons) per the FAQ read on 31 October 2026; older FOGADAC pages still show the earlier XAF 5 million per depositor per bank. Covers all CEMAC banks.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TD', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No standard monthly recurring deposit product or rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TD', 1, 'equity_return_base', 0.065, NULL, 'assumption', 'BEAC: franc CFA fixed to the euro; CEMAC regional exchange (BVMAC) with very small market capitalisation', 'https://www.beac.int/wp-content/uploads/2021/10/Statistiques-Mensuelles-du-March%C3%A9-des-valeurs-du-Tr%C3%A9sors-de-la-CEMAC-janvier-2026.pdf', '2026-10-31', 'No usable local index record (BVMAC equity capitalisation was only about XAF 295 billion in January 2026), so equity means a global index in euro terms, held about 4 points above an after-tax safe saving rate of about 2.5-3%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TD', 1, 'equity_return_high', 0.1, NULL, 'assumption', 'BEAC: franc CFA fixed to the euro; CEMAC regional exchange (BVMAC) with very small market capitalisation', 'https://www.beac.int/wp-content/uploads/2021/10/Statistiques-Mensuelles-du-March%C3%A9-des-valeurs-du-Tr%C3%A9sors-de-la-CEMAC-janvier-2026.pdf', '2026-10-31', 'High case: global equities repeat their long-run euro-terms record.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TD', 1, 'equity_return_low', 0.02, NULL, 'assumption', 'BEAC: franc CFA fixed to the euro; CEMAC regional exchange (BVMAC) with very small market capitalisation', 'https://www.beac.int/wp-content/uploads/2021/10/Statistiques-Mensuelles-du-March%C3%A9-des-valeurs-du-Tr%C3%A9sors-de-la-CEMAC-janvier-2026.pdf', '2026-10-31', 'Low case: a weak decade for global equities held in euro (franc CFA) terms; the regional exchange is too small and illiquid to serve as a guide.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TD', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published 1-year term deposit rate was found; the BEAC publishes lending rates (TEG) by country but no term deposit rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TD', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published 3-month term deposit rate was found; the BEAC publishes lending rates (TEG) by country but no deposit rates beyond the 2.45% savings floor.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TD', 1, 'fixed_income_return_base', 0.03, NULL, 'assumption', 'BEAC Taux Créditeur Minimum 2.45%; BEAC Treasury market statistics (individuals hold Treasury bonds)', 'https://www.beac.int/wp-content/uploads/2018/11/Rapport-sur-La-Politique-Mon%C3%A9taire-de-la-BEAC_Sept-2026_vf_new2_Publiable.pdf', '2026-10-31', 'Base case: savings and term deposits a little above the 2.45% floor; government bond yields are much higher but mostly bought by banks and institutions.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TD', 1, 'fixed_income_return_high', 0.06, NULL, 'assumption', 'BEAC Taux Créditeur Minimum 2.45%; BEAC Treasury market statistics (individuals hold Treasury bonds)', 'https://www.beac.int/wp-content/uploads/2021/10/Statistiques-Mensuelles-du-March%C3%A9-des-valeurs-du-Tr%C3%A9sors-de-la-CEMAC-janvier-2026.pdf', '2026-10-31', 'High case: part of savings in government bonds offered to the public, whose issue cost averaged 11.03% in January 2026, after some default and liquidity risk.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TD', 1, 'fixed_income_return_low', 0.02, NULL, 'assumption', 'BEAC Taux Créditeur Minimum 2.45%; BEAC Treasury market statistics (individuals hold Treasury bonds)', 'https://www.beac.int/wp-content/uploads/2018/11/Rapport-sur-La-Politique-Mon%C3%A9taire-de-la-BEAC_Sept-2026_vf_new2_Publiable.pdf', '2026-10-31', 'Low case: ordinary savings accounts at the 2.45% minimum rate, less any tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TD', 1, 'goal_inflation_education', 0.04, NULL, 'assumption', 'BEAC note on CEMAC inflation Q2 2026: education prices +0.8% year on year in June 2026', 'https://www.beac.int/wp-content/uploads/2016/10/Note-sur-l%C3%A9volution-r%C3%A9cente-de-linflation-dans-la-CEMAC-2026Q2.pdf', '2026-10-31', 'Education prices in the CEMAC index rose 0.8% in June 2026, but private school fees rise faster, so education goals use 1 point above the 3% planning inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TD', 1, 'goal_inflation_health', 0.045, NULL, 'assumption', 'BEAC note on CEMAC inflation Q2 2026: health prices +1.5% year on year in June 2026', 'https://www.beac.int/wp-content/uploads/2016/10/Note-sur-l%C3%A9volution-r%C3%A9cente-de-linflation-dans-la-CEMAC-2026Q2.pdf', '2026-10-31', 'Health prices in the CEMAC index rose 1.5% in June 2026, but private and imported care costs run faster, so health goals use 1.5 points above the 3% planning inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TD', 1, 'gold_return_base', 0.045, NULL, 'assumption', 'Franc CFA fixed at 655.957 per euro (BEAC); dollar gold trend', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=TD', '2026-10-31', 'Base case: the long-run gold trend of about 4-5% a year in euro terms, which the franc CFA follows.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TD', 1, 'gold_return_high', 0.08, NULL, 'assumption', 'Franc CFA fixed at 655.957 per euro (BEAC); dollar gold trend', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=TD', '2026-10-31', 'High case: strong gold years.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TD', 1, 'gold_return_low', 0, NULL, 'assumption', 'Franc CFA fixed at 655.957 per euro (BEAC); dollar gold trend', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=TD', '2026-10-31', 'Low case: flat gold prices with no currency loss under the euro peg.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TD', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Labour Code provisions on dismissal or end-of-service indemnity could not be read from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TD', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical out-of-pocket cost of a major hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TD', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premiums by age were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TD', 1, 'inflation_cpi', -0.02, NULL, 'sourced', 'Bank of Central African States (BEAC), note on CEMAC inflation, Q2 2026 (national CPI, Chad)', 'https://www.beac.int/wp-content/uploads/2016/10/Note-sur-l%C3%A9volution-r%C3%A9cente-de-linflation-dans-la-CEMAC-2026Q2.pdf', '2026-06-30', 'Consumer prices fell 2.0% year on year in June 2026 in Chad (BEAC table of national CPIs), after falling since mid-2025 because of good harvests and cheaper imports from Libya; the annual average was -3.6% in June 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TD', 1, 'inflation_projection', 0.03, NULL, 'assumption', 'BEAC: CEMAC inflation convergence norm of 3%; franc CFA fixed to the euro', 'https://www.beac.int/wp-content/uploads/2016/10/COMMUNIQUE-DE-PRESSE-CPM-DU-28-SEPTEMBRE-2026.pdf', '2026-10-31', 'The franc CFA is fixed to the euro and the BEAC holds CEMAC inflation under a 3% norm; Chad swung from 5.7% average inflation in 2024 to -2.6% in 2025 (BEAC), so the 3% norm is used rather than recent deflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TD', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published term life premium rates per XAF 1,000 of cover were found; the life insurance market is very small.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TD', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No life insurance claim settlement ratio was found from CIMA (the regional insurance regulator) or the national insurance directorate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TD', 1, 'life_expectancy', 55.238, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN), Chad', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=TD', '2024-12-31', '55.2 years in 2024 (men 53.4, women 57.2); latest World Bank value, older than 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TD', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":15.5,"men":14.8,"women":16.1},{"age":65,"total":12.3,"men":11.7,"women":12.8},{"age":70,"total":9.5,"men":9.1,"women":9.9},{"age":80,"total":5.3,"men":5,"women":5.6}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/chad/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026; totals are the mean of men and women where the page gives no both-sexes figure (it gives 65 only).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TD', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension or official programme page for one was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TD', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension or official programme page for one was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TD', 1, 'oop_health_share', 0.5168, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), Chad', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=TD', '2023-12-31', '51.7% in 2023 (WHO Global Health Expenditure Database via the World Bank), the latest available; older than 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TD', 1, 'policy_rate', 0.045, NULL, 'sourced', 'BEAC Monetary Policy Committee, press release of 28 September 2026 (Taux d''intérêt des appels d''offres)', 'https://www.beac.int/wp-content/uploads/2016/10/COMMUNIQUE-DE-PRESSE-CPM-DU-28-SEPTEMBRE-2026.pdf', '2026-09-28', 'BEAC tender rate (TIAO) held at 4.50% on 28 September 2026 (marginal lending facility 5.75%, deposit facility 0%); the rate is common to all six CEMAC countries.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TD', 1, 'public_pension_scheme', NULL, NULL, 'missing', '', '', '2026-10-31', 'A compulsory pension for salaried workers is run by the National Social Welfare Fund (CNPS), financed by 5% employer and 3.5% employee contributions (PwC, reviewed 2024), but its pension age and indexation rules could not be read from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TD', 1, 'retirement_accumulation_return_base', 0.045, NULL, 'assumption', 'Safe rate about 3%; global equity base 6.5% in euro terms; gold base 4.5%', 'https://www.beac.int/wp-content/uploads/2021/10/Statistiques-Mensuelles-du-March%C3%A9-des-valeurs-du-Tr%C3%A9sors-de-la-CEMAC-janvier-2026.pdf', '2026-10-31', 'Base case: a balanced mix of deposits, public bond offers, gold and foreign equity funds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TD', 1, 'retirement_accumulation_return_high', 0.065, NULL, 'assumption', 'Safe rate about 3%; global equity base 6.5% in euro terms; gold base 4.5%', 'https://www.beac.int/wp-content/uploads/2021/10/Statistiques-Mensuelles-du-March%C3%A9-des-valeurs-du-Tr%C3%A9sors-de-la-CEMAC-janvier-2026.pdf', '2026-10-31', 'High case: a growth-leaning mix with more equity.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TD', 1, 'retirement_accumulation_return_low', 0.025, NULL, 'assumption', 'Safe rate about 3%; global equity base 6.5% in euro terms; gold base 4.5%', 'https://www.beac.int/wp-content/uploads/2018/11/Rapport-sur-La-Politique-Mon%C3%A9taire-de-la-BEAC_Sept-2026_vf_new2_Publiable.pdf', '2026-10-31', 'Low case: mostly bank savings.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TD', 1, 'retirement_age_default', NULL, NULL, 'missing', '', '', '2026-10-31', 'The pension age of the National Social Welfare Fund (CNPS) could not be confirmed: its website has no pension rules and the ILO, ISSA and US SSA country pages were not reachable.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TD', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'The retirement age of civil servants could not be confirmed from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TD', 1, 'retirement_return_base', 0.03, NULL, 'assumption', 'BEAC Taux Créditeur Minimum 2.45%; BEAC Treasury bill issue cost 6.96% (January 2026)', 'https://www.beac.int/wp-content/uploads/2018/11/Rapport-sur-La-Politique-Mon%C3%A9taire-de-la-BEAC_Sept-2026_vf_new2_Publiable.pdf', '2026-10-31', 'Base case: deposits and some public bond offers; kept below the Treasury bill rate and close to the deposit floor, since term deposit rates are not published.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TD', 1, 'retirement_return_high', 0.045, NULL, 'assumption', 'BEAC Taux Créditeur Minimum 2.45%; BEAC Treasury bill issue cost 6.96% (January 2026)', 'https://www.beac.int/wp-content/uploads/2021/10/Statistiques-Mensuelles-du-March%C3%A9-des-valeurs-du-Tr%C3%A9sors-de-la-CEMAC-janvier-2026.pdf', '2026-10-31', 'High case: a larger share in government bonds offered to the public.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TD', 1, 'retirement_return_low', 0.02, NULL, 'assumption', 'BEAC Taux Créditeur Minimum 2.45%; BEAC Treasury bill issue cost 6.96% (January 2026)', 'https://www.beac.int/wp-content/uploads/2018/11/Rapport-sur-La-Politique-Mon%C3%A9taire-de-la-BEAC_Sept-2026_vf_new2_Publiable.pdf', '2026-10-31', 'Low case: savings accounts at the 2.45% minimum rate, less any tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TD', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate for individuals was found; Chad sells Treasury bonds through BEAC-run auctions and public bond offers, and the yield of the bonds bought by individuals is not published separately.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TD', 1, 'savings_account_rate', 0.0245, NULL, 'sourced', 'BEAC Monetary Policy Report, September 2026, Annex 1 (Taux Créditeur Minimum)', 'https://www.beac.int/wp-content/uploads/2018/11/Rapport-sur-La-Politique-Mon%C3%A9taire-de-la-BEAC_Sept-2026_vf_new2_Publiable.pdf', '2026-09-30', 'Minimum rate banks must pay on savings accounts of individuals (Taux Créditeur Minimum), 2.45% unchanged since 8 July 2014; banks usually pay this floor.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TD', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":24.5},{"year":2040,"value":20},{"year":2065,"value":13.5}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://data.worldbank.org/indicator/SP.POP.DPND.OL?locations=TD', '2025-12-31', '100 / old-age dependency ratio: 4.08 (2025, World Bank), 5.0 (2040, populationpyramid.net/chad/2040/) and 7.4 (2065, populationpyramid.net/chad/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TD', 1, 'tax_bank_interest', NULL, NULL, 'missing', '', '', '2026-10-31', 'PwC Worldwide Tax Summaries (last reviewed 12 August 2024) says interest income of individuals is added to other income and taxed at the progressive personal income tax rates, and that no withholding tax applies to interest paid to residents, so no single flat rate can be given.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TD', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate for individuals exists, and the tax treatment of Treasury security income for individuals could not be confirmed from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TD', 1, 'tbill_91d_rate', 0.0696, NULL, 'sourced', 'BEAC, Statistiques mensuelles du marché des valeurs du Trésor de la CEMAC, January 2026 (coût des ressources, BTA)', 'https://www.beac.int/wp-content/uploads/2021/10/Statistiques-Mensuelles-du-March%C3%A9-des-valeurs-du-Tr%C3%A9sors-de-la-CEMAC-janvier-2026.pdf', '2026-01-31', 'Weighted average cost of Treasury bills (BTA, 13 to 52 weeks) issued by Chad in January 2026; no separate 13-week yield is published.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TD', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 10-year Treasury bond yield for Chad is published in the BEAC Treasury market statistics (January 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TD', 1, 'tbond_5y_rate', 0.1103, NULL, 'sourced', 'BEAC, Statistiques mensuelles du marché des valeurs du Trésor de la CEMAC, January 2026 (coût des ressources, OTA)', 'https://www.beac.int/wp-content/uploads/2021/10/Statistiques-Mensuelles-du-March%C3%A9-des-valeurs-du-Tr%C3%A9sors-de-la-CEMAC-janvier-2026.pdf', '2026-01-31', 'Weighted average cost of Treasury bonds (OTA, 2 to 7 years) issued by Chad in January 2026; no yield for an exact 5-year maturity is published.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('TG', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"TG","iso3":"TGO","nameEn":"Togo","nameNative":"Togo","region":"sub_saharan_africa","languages":["fr","ee","kbp"],"currency":{"code":"XOF","symbol":"F CFA","decimals":0,"compact":"intl","usdRate":{"value":581.928,"status":"sourced","sourceName":"World Bank WDI, official exchange rate (PA.NUS.FCRF), Togo, 2025 average","sourceUrl":"https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=TG","asOf":"2025-12-31","note":"581.9 CFA francs per dollar on average in 2025; the BCEAO reference rate was 584.84 on 2 November 2026 (just after the research date). The franc is fixed at 655.957 per euro."}},"instruments":{"savings_account":{"available":true,"localName":"Compte d''épargne","localNameEn":"Savings account"},"fdr_3m":{"available":true,"localName":"Dépôt à terme","localNameEn":"Term deposit (DAT)","note":"Banks declare minimum and maximum term-deposit rates to the BCEAO twice a year.","sourceUrl":"https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf"},"fdr_1y":{"available":true,"localName":"Dépôt à terme","localNameEn":"Term deposit (DAT), 1 year","note":"Banks declare minimum and maximum term-deposit rates to the BCEAO twice a year.","sourceUrl":"https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf"},"dps":{"available":true,"localName":"Épargne contractuelle","localNameEn":"Contractual savings plan","note":"Monthly savings plans offered by most Togo banks at about 3.5-5%.","sourceUrl":"https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf"},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate for individuals was found."},"tbill_91d":{"available":true,"localName":"Bons assimilables du Trésor","localNameEn":"Treasury bills (BAT)","note":"Auctioned through UMOA-Titres; individuals buy through banks or licensed brokers (SGI).","sourceUrl":"https://www.umoatitres.org/fr/pays/togo/"},"tbond_5y":{"available":true,"localName":"Obligations assimilables du Trésor","localNameEn":"Treasury bonds (OAT)","note":"Auctioned through UMOA-Titres; individuals buy through banks or licensed brokers (SGI).","sourceUrl":"https://www.umoatitres.org/fr/pays/togo/"},"tbond_10y":{"available":true,"localName":"Obligations assimilables du Trésor","localNameEn":"Treasury bonds (OAT)","note":"Togo''s yield curve runs to 15 years; long bonds are issued less often.","sourceUrl":"https://www.umoatitres.org/wp-content/uploads/2026/10/COURBES-DE-TAUX.au_.23.10.2026.xlsx"},"equity_fund":{"available":true,"localName":"OPCVM (FCP, SICAV)","localNameEn":"Collective investment funds","note":"Supervised by the regional financial market authority (AMF-UMOA); equity funds invest on the regional exchange (BRVM)."},"gold":{"available":true,"localName":"Or","localNameEn":"Gold","note":"Gold is mainly bought as jewellery; bars and coins are uncommon."}},"institutions":{"centralBank":{"name":"Banque Centrale des États de l''Afrique de l''Ouest (BCEAO)","url":"https://www.bceao.int/"},"insuranceRegulator":{"name":"Commission Régionale de Contrôle des Assurances (CIMA)","url":"https://cima-afrique.org/","note":"Regional insurance regulator for the CIMA member states; Togo''s insurance directorate is in the Ministry of Economy and Finance."},"insuranceComplaints":{"name":"CIMA, policyholder requests and complaints","url":"https://cima-afrique.org/faites-votre-requetes-ici-2/"},"pensionScheme":{"name":"Caisse Nationale de Sécurité Sociale (CNSS), old-age pension","url":"https://www.cnss.tg/","note":"Civil servants'' pensions are paid by the Caisse de Retraites du Togo (https://www.crt.tg/)."},"oldAgeAllowance":null,"publicHealthCover":{"name":"Assurance Maladie Universelle (AMU), Institut National d''Assurance Maladie (INAM)","url":"https://amu.inam.tg/"},"depositInsurance":{"name":"Fonds de Garantie des Dépôts et de Résolution dans l''UMOA (FGDR-UMOA)","url":"https://www.fgd-umoa.org/"},"statistics":{"name":"Institut National de la Statistique et des Études Économiques et Démographiques (INSEED)","url":"https://inseed.tg/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TG', 1, 'bank_deposit_avg_rate', 0.0515, NULL, 'sourced', 'BCEAO economic note for UEMOA countries, September 2026 (bank deposit rates, July 2026)', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-07-31', 'Average deposit rate across all UMOA banks (the eight-country union, not Togo alone), 5.15% in July 2026 (5.12% in June); the note says only that Togo''s rate fell 1 basis point in the month. Togo banks'' declared term-deposit rates run from a median minimum of 3.5% to a median maximum of about 6.45% (BCEAO bank-conditions survey, first half 2026). World Bank FR.INR.DPST for Togo dates from 2016.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TG', 1, 'credit_card_rate_cap', 0.1375, NULL, 'sourced', 'BCEAO, conditions débitrices of UMOA credit institutions, first half 2026 (Togo)', 'https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf', '2026-06-30', 'Median of the maximum lending rates (taux débiteur maximum) declared by the 16 credit institutions in Togo for the first half of 2026 (13.5% and 14% either side of the middle; range 9-18%); it applies to all bank credit, including cards. No card-specific rate or legal usury rate was read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TG', 1, 'deposit_insurance_limit', 1400000, NULL, 'sourced', 'UMOA Council of Ministers, Decision No. 009 of 30 June 2017 (FGD-UMOA contribution rates and compensation limits), article 2', 'https://www.fgd-umoa.org/wp-content/uploads/2024/10/Decision-du-CM-relative-aux-taux-de-contribution-et-aux-plafonds-d-indemnistation-2-1.pdf', '2017-06-30', 'Deposits are guaranteed up to 1,400,000 FCFA per depositor per bank (300,000 FCFA at a microfinance institution) by the regional deposit guarantee fund; the decision dates from 2017 (older than 2025) and is still the one the fund publishes.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TG', 1, 'dps_rate', 0.035, NULL, 'sourced', 'BCEAO, conditions créditrices of UMOA credit institutions, first half 2026 (Togo)', 'https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf', '2026-06-30', 'Contractual savings plans (épargne contractuelle): most Togo banks declare a range starting at 3.5% (ranges between 2.0% and 5.0%); the median lower bound is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TG', 1, 'equity_return_base', 0.08, NULL, 'assumption', 'BCEAO economic note, September 2026; UMOA-Titres Togo yield curve', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-10-31', 'Base case: about 3.5 points above after-tax term deposits and one-year government bills (about 4.5-5%), within the 4-point cap, because the BRVM''s 10-year record is uneven despite a 60.7% rise in the composite index in the year to August 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TG', 1, 'equity_return_high', 0.12, NULL, 'assumption', 'BCEAO economic note, September 2026 (BRVM indices and capitalisation)', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-10-31', 'High case: the BRVM repeats a strong decade like 2023-2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TG', 1, 'equity_return_low', 0.04, NULL, 'assumption', 'BCEAO economic note, September 2026 (regional stock exchange BRVM, deposit rates)', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-10-31', 'Low case: regional (BRVM) equities return about the bank deposit rate, as in their weak 2016-2020 years.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TG', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The BCEAO bank-conditions survey gives only minimum (median 3.5%) and maximum (median about 6.45%, range 4.2-7.0%) term-deposit rates per bank in Togo for the first half of 2026, not a 1-year rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TG', 1, 'fdr_3m_rate', 0.035, NULL, 'sourced', 'BCEAO, conditions créditrices of UMOA credit institutions, first half 2026 (Togo)', 'https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf', '2026-06-30', 'Median of the minimum term-deposit rates (taux DAT minimum) that Togo''s 16 banks and the postal bank declare to the BCEAO (range 2.5-4.25%); the minimum usually applies to small, short deposits. Not a tenor-specific average.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TG', 1, 'fixed_income_return_base', 0.045, NULL, 'assumption', 'BCEAO bank conditions (Togo term deposits 3.5-6.45%); UMOA-Titres Togo yield curve (1 year 5.2%)', 'https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf', '2026-10-31', 'Base case: larger term deposits (median maximum about 6.45%) or 1-year Treasury bills (5.2%) through a bank, less tax on interest, rounded down because the tax rate is unconfirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TG', 1, 'fixed_income_return_high', 0.06, NULL, 'assumption', 'UMOA-Titres Togo yield curve (5-year 7.0%)', 'https://www.umoatitres.org/wp-content/uploads/2026/10/COURBES-DE-TAUX.au_.23.10.2026.xlsx', '2026-10-31', 'High case: 3-5 year Treasury bonds or regional public bond issues at 6-7%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TG', 1, 'fixed_income_return_low', 0.03, NULL, 'assumption', 'BCEAO, conditions créditrices, first half 2026 (Togo)', 'https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf', '2026-10-31', 'Low case: small term deposits or contractual savings at the 3.5% floor rate, less a possible tax on interest.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TG', 1, 'goal_inflation_education', 0.04, NULL, 'assumption', 'BCEAO economic note, September 2026; inflation assumption 2%', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-10-31', 'No national education CPI series was read; private school fees usually rise faster than general prices, so 2 points above the 2% inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TG', 1, 'goal_inflation_health', 0.035, NULL, 'assumption', 'BCEAO economic note, September 2026; inflation assumption 2%', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-10-31', 'No national medical CPI series was read; private medical costs usually rise faster than general prices, so 1.5 points above the 2% inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TG', 1, 'gold_return_base', 0.045, NULL, 'assumption', 'BCEAO reference exchange rates (CFA franc pegged at 655.957 per euro)', 'https://www.bceao.int/fr/cours/cours-de-reference-des-principales-devises-contre-Franc-CFA', '2026-10-31', 'Base case: the long-run dollar gold trend of about 4% a year plus a small allowance for the euro-pegged franc weakening against the dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TG', 1, 'gold_return_high', 0.08, NULL, 'assumption', 'BCEAO reference exchange rates', 'https://www.bceao.int/fr/cours/cours-de-reference-des-principales-devises-contre-Franc-CFA', '2026-10-31', 'High case: strong gold years such as 2024-2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TG', 1, 'gold_return_low', 0, NULL, 'assumption', 'BCEAO reference exchange rates (CFA franc pegged at 655.957 per euro)', 'https://www.bceao.int/fr/cours/cours-de-reference-des-principales-devises-contre-Franc-CFA', '2026-10-31', 'Low case: flat gold in euro terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TG', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No official text on a statutory end-of-service or retirement indemnity for private employees in Togo could be read (the Labour Code and the inter-professional collective agreement were not reached).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TG', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a major private hospital stay in Togo was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TG', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premiums by age were found from a public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TG', 1, 'inflation_cpi', 0.024, NULL, 'sourced', 'Trading Economics, citing the national statistics office (INSEED/DGSCN) consumer price index, September 2026', 'https://tradingeconomics.com/togo/inflation-cpi', '2026-09-30', 'Secondary source: consumer prices up 2.4% year on year in September 2026 after 0.7% in August; the BCEAO economic note of September 2026 confirms 0.7% for August (1.6% in July). Fuel prices were raised in May and September 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TG', 1, 'inflation_projection', 0.02, NULL, 'assumption', 'BCEAO inflation target (1-3% band, centre 2%); World Bank CPI inflation 2025 (0.4%)', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-10-31', 'The CFA franc is pegged to the euro and the BCEAO aims at 1-3%; Togo''s inflation has mostly stayed in or below that band, so its 2% centre is used for long-range plans.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TG', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Temporary death cover is sold under the CIMA code, but no published premium rates per 1,000 FCFA of cover by age were found from a public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TG', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'CIMA (the regional insurance regulator) and Togo''s insurance directorate publish no industry-wide life claim settlement ratio that could be found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TG', 1, 'life_expectancy', 62.935, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN), Togo', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=TG', '2024-12-31', '62.9 years in 2024 (men 62.7, women 63.2), the latest World Bank year (older than 2025); UN WPP 2024 gives 63.3 for 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TG', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":15.8,"men":15.5,"women":16},{"age":65,"total":12.4,"men":12.2,"women":12.5},{"age":70,"total":9.3,"men":9.2,"women":9.4},{"age":80,"total":4.8,"men":4.7,"women":4.8}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/togo/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TG', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension was found (see old_age_allowance_monthly).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TG', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension for Togo was found; the CLEISS summary of Togo social security describes contributory CNSS benefits only, but no source confirming that none exists was read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TG', 1, 'oop_health_share', 0.6434, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), Togo', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=TG', '2023-12-31', '64.3% in 2023 (WHO Global Health Expenditure Database), the latest available and older than 2025; universal health insurance (AMU) has been extended since 2024.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TG', 1, 'policy_rate', 0.03, NULL, 'sourced', 'BCEAO economic note for UEMOA countries, September 2026: Monetary Policy Committee of 9 September 2026', 'https://www.bceao.int/sites/default/files/2026-10/Note%20de%20conjoncture%20%C3%A9conomique%20des%20pays%20de%20l%27UEMOA_Septembre%202026.pdf', '2026-09-09', 'Main policy rate (minimum bid rate for liquidity tenders) kept at 3.00%; marginal lending facility 5.00%. Common to all eight UMOA countries.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TG', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":60,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'CLEISS (French social security liaison body), the Togo social security system: CNSS old-age insurance', 'https://www.cleiss.fr/docs/regimes/regime_togo.html', '2026-01-01', 'Compulsory CNSS pension for private employees: 20% of the average uncapped wage of the last 5 years after 180 months of insurance, plus 1.33% per extra 12 months; at least 60% of the minimum wage (52,500 FCFA) and at most 80% of the average wage; a lump sum of one month''s wage per year of insurance for 12-179 months. Revaluation and tax treatment not stated. Civil servants belong to the Caisse de Retraites du Togo.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TG', 1, 'retirement_accumulation_return_base', 0.06, NULL, 'assumption', 'UMOA-Titres Togo yield curve; equity base 8%; gold base 4.5%', 'https://www.umoatitres.org/wp-content/uploads/2026/10/COURBES-DE-TAUX.au_.23.10.2026.xlsx', '2026-10-31', 'Base case: a balanced mix of deposits or Treasury bonds, regional equity funds and some gold.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TG', 1, 'retirement_accumulation_return_high', 0.08, NULL, 'assumption', 'UMOA-Titres Togo yield curve; equity high 12%', 'https://www.umoatitres.org/wp-content/uploads/2026/10/COURBES-DE-TAUX.au_.23.10.2026.xlsx', '2026-10-31', 'High case: a growth-leaning mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TG', 1, 'retirement_accumulation_return_low', 0.035, NULL, 'assumption', 'BCEAO, conditions créditrices, first half 2026 (Togo)', 'https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf', '2026-10-31', 'Low case: a mix earning about after-tax deposit rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TG', 1, 'retirement_age_default', 60, NULL, 'sourced', 'CLEISS (French social security liaison body), the Togo social security system: CNSS old-age insurance', 'https://www.cleiss.fr/docs/regimes/regime_togo.html', '2026-01-01', 'CNSS old-age pension at 60 with 180 months of insurance (55 for premature wear); voluntary early pension from 55, reduced 5% a year. The page is dated 2026 without a precise day.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TG', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'The civil-service retirement age could not be confirmed from an official source; the civil servants'' pension fund (Caisse de Retraites du Togo) site does not state it.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TG', 1, 'retirement_return_base', 0.04, NULL, 'assumption', 'BCEAO, conditions créditrices, first half 2026 (Togo); UMOA-Titres Togo 1-year rate 5.2%', 'https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf', '2026-10-31', 'Base case: term deposits at 3.5-6.45% less tax on interest; below the after-tax one-year deposit and Treasury bill rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TG', 1, 'retirement_return_high', 0.055, NULL, 'assumption', 'UMOA-Titres Togo yield curve (2-5 years 6.1-7.4%)', 'https://www.umoatitres.org/wp-content/uploads/2026/10/COURBES-DE-TAUX.au_.23.10.2026.xlsx', '2026-10-31', 'High case: part of the money in short Treasury bonds bought through a bank.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TG', 1, 'retirement_return_low', 0.03, NULL, 'assumption', 'BCEAO, conditions créditrices, first half 2026 (Togo)', 'https://www.bceao.int/sites/default/files/2026-10/Conditions%20de%20banque%20premi%C3%A8re%20semestre%202026.pdf', '2026-10-31', 'Low case: small term deposits or contractual savings at about 3.5%, less a possible tax on interest.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TG', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate sold to individuals was found; the Treasury borrows through UMOA-Titres auctions of bills and bonds, open to individuals only through banks and licensed brokers.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TG', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No average rate on ordinary savings accounts in Togo was found; the BCEAO bank-conditions survey (first half 2026) lists term-deposit and contractual-savings rates only.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TG', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":16.13},{"year":2040,"value":14.08},{"year":2065,"value":9.9}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/togo/2040/', '2025-12-31', '100 / old-age dependency ratio: 6.20 (2025, World Bank), 7.1 (2040) and 10.1 (2065, populationpyramid.net/togo/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TG', 1, 'tax_bank_interest', NULL, NULL, 'missing', '', '', '2026-10-31', 'The tax on interest from bank deposits for individuals could not be confirmed: PwC Tax Summaries has no Togo page and the 2026 fiscal handbook of the Office Togolais des Recettes is a scanned image without the rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TG', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate exists, and the tax treatment of interest on Togo Treasury securities for individuals could not be confirmed from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TG', 1, 'tbill_91d_rate', 0.0586, NULL, 'sourced', 'UMOA-Titres, Togo yield curve (zero coupon) at 23 October 2026', 'https://www.umoatitres.org/wp-content/uploads/2026/10/COURBES-DE-TAUX.au_.23.10.2026.xlsx', '2026-10-23', '3-month zero-coupon rate 5.86% (5.97% after smoothing); 1-year 5.17%. The results of Togo''s October 2026 auctions were not published on the UMOA-Titres pages.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TG', 1, 'tbond_10y_rate', 0.063, NULL, 'sourced', 'UMOA-Titres, Togo yield curve (rate after smoothing) at 23 October 2026', 'https://www.umoatitres.org/wp-content/uploads/2026/10/COURBES-DE-TAUX.au_.23.10.2026.xlsx', '2026-10-23', '10-year smoothed rate 6.30%; the raw zero-coupon point is 5.48%, out of line with the 7-8 year points (6.9-7.6%), so the smoothed curve is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TG', 1, 'tbond_5y_rate', 0.0699, NULL, 'sourced', 'UMOA-Titres, Togo yield curve (zero coupon) at 23 October 2026', 'https://www.umoatitres.org/wp-content/uploads/2026/10/COURBES-DE-TAUX.au_.23.10.2026.xlsx', '2026-10-23', '5-year zero-coupon rate 6.99% (7.05% after smoothing).', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('TH', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"TH","iso3":"THA","nameEn":"Thailand","nameNative":"ประเทศไทย","region":"east_asia_pacific","languages":["th","en","tts"],"currency":{"code":"THB","symbol":"฿","decimals":2,"compact":"intl","usdRate":{"value":33.765,"status":"sourced","sourceName":"Trading Economics, USD/THB (secondary source)","sourceUrl":"https://tradingeconomics.com/thailand/currency","asOf":"2026-10-30","note":"World Bank PA.NUS.FCRF gives 32.88 for 2025."}},"instruments":{"savings_account":{"available":true,"localName":"บัญชีเงินฝากออมทรัพย์","localNameEn":"Savings account","sourceUrl":"https://app.bot.or.th/BTWS_STAT/statistics/BOTWEBSTAT.aspx?reportID=1033&language=ENG"},"fdr_3m":{"available":true,"localName":"เงินฝากประจำ 3 เดือน","localNameEn":"3-month fixed deposit","sourceUrl":"https://app.bot.or.th/BTWS_STAT/statistics/BOTWEBSTAT.aspx?reportID=1033&language=ENG"},"fdr_1y":{"available":true,"localName":"เงินฝากประจำ 12 เดือน","localNameEn":"12-month fixed deposit","sourceUrl":"https://app.bot.or.th/BTWS_STAT/statistics/BOTWEBSTAT.aspx?reportID=1033&language=ENG"},"dps":{"available":true,"localName":"เงินฝากประจำปลอดภาษี","localNameEn":"Tax-free monthly fixed deposit","note":"Monthly fixed-deposit plans offered by many banks; terms and tax-free limits vary and were not confirmed in this pass."},"sanchayapatra_5y":{"available":true,"localName":"พันธบัตรออมทรัพย์","localNameEn":"Government savings bond","note":"Issued periodically by the Public Debt Management Office for individuals, in several tenors."},"tbill_91d":{"available":false,"localName":"ตั๋วเงินคลัง","localNameEn":"Treasury bill","note":"Treasury bills are auctioned to institutions; individuals rarely have access.","sourceUrl":"https://app.bot.or.th/BTWS_STAT/statistics/BOTWEBSTAT.aspx?reportID=1033&language=ENG"},"tbond_5y":{"available":true,"localName":"พันธบัตรรัฐบาล 5 ปี","localNameEn":"5-year government bond","note":"Individuals can buy government bonds through banks in the secondary market.","sourceUrl":"https://app.bot.or.th/BTWS_STAT/statistics/BOTWEBSTAT.aspx?reportID=1033&language=ENG"},"tbond_10y":{"available":true,"localName":"พันธบัตรรัฐบาล 10 ปี","localNameEn":"10-year government bond","sourceUrl":"https://app.bot.or.th/BTWS_STAT/statistics/BOTWEBSTAT.aspx?reportID=1033&language=ENG"},"equity_fund":{"available":true,"localName":"กองทุนรวมดัชนี","localNameEn":"Index mutual fund","note":"Diversified equity and index mutual funds are widely sold, including tax-advantaged retirement and ESG funds."},"gold":{"available":true,"localName":"ทองคำแท่ง","localNameEn":"Gold bar","note":"Gold bars and ornaments are freely bought at gold shops."}},"institutions":{"centralBank":{"name":"Bank of Thailand","url":"https://www.bot.or.th/"},"insuranceRegulator":{"name":"Office of Insurance Commission (OIC)","url":"https://www.oic.or.th/"},"insuranceComplaints":{"name":"Office of Insurance Commission (complaints)","url":"https://www.oic.or.th/"},"pensionScheme":{"name":"Social Security Office","url":"https://www.sso.go.th/"},"oldAgeAllowance":{"name":"Department of Older Persons","url":"https://www.dop.go.th/th","note":"The allowance is paid through local administrative organisations."},"publicHealthCover":{"name":"National Health Security Office (Universal Coverage Scheme)","url":"https://www.nhso.go.th/"},"depositInsurance":{"name":"Deposit Protection Agency","url":"https://www.dpa.or.th/"},"statistics":{"name":"National Statistical Office","url":"https://www.nso.go.th/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TH', 1, 'bank_deposit_avg_rate', 0.0077, NULL, 'sourced', 'Bank of Thailand, FM_RT_001_S4 Interest Rates in Financial Market (time deposits weighted average)', 'https://app.bot.or.th/BTWS_STAT/statistics/BOTWEBSTAT.aspx?reportID=1033&language=ENG', '2026-08-31', 'Weighted average time deposit rate 0.77% in August 2026; World Bank FR.INR.DPST gives 1.15% for 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TH', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'The BOT credit card interest ceiling could not be confirmed from a reachable official page in this pass.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TH', 1, 'deposit_insurance_limit', 1000000, NULL, 'sourced', 'Deposit Protection Agency, coverage limit', 'https://www.dpa.or.th/coverage-limit', '2026-10-31', '1 million baht per depositor per financial institution, all accounts and branches combined.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TH', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Banks offer tax-free monthly fixed deposits (24-36 months), but no average or range is published by the BOT.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TH', 1, 'equity_return_base', 0.04, NULL, 'assumption', 'BOT: 12-month time deposits 0.75-1.40% and 1-year government yield 1.00% (Sep 2026), less 15% withholding tax', 'https://app.bot.or.th/BTWS_STAT/statistics/BOTWEBSTAT.aspx?reportID=1033&language=ENG', '2026-10-31', 'After-tax safe rate of about 0.9% plus a 3.1-point premium, kept low because the SET index has gone nowhere over ten years.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TH', 1, 'equity_return_high', 0.075, NULL, 'assumption', 'BOT: 12-month time deposits 0.75-1.40% and 1-year government yield 1.00% (Sep 2026), less 15% withholding tax', 'https://app.bot.or.th/BTWS_STAT/statistics/BOTWEBSTAT.aspx?reportID=1033&language=ENG', '2026-10-31', 'High case for a diversified Thai and global equity mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TH', 1, 'equity_return_low', 0.01, NULL, 'assumption', 'BOT: 12-month time deposits 0.75-1.40% and 1-year government yield 1.00% (Sep 2026), less 15% withholding tax', 'https://app.bot.or.th/BTWS_STAT/statistics/BOTWEBSTAT.aspx?reportID=1033&language=ENG', '2026-10-31', 'Low case near the after-tax safe rate; the SET index has a weak 10-year record.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TH', 1, 'fdr_1y_rate', 0.0108, NULL, 'sourced', 'Bank of Thailand, FM_RT_001_S4 Interest Rates in Financial Market (commercial bank deposit rates)', 'https://app.bot.or.th/BTWS_STAT/statistics/BOTWEBSTAT.aspx?reportID=1033&language=ENG', '2026-09-30', '12-month time deposits 0.75-1.40% in September 2026; midpoint used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TH', 1, 'fdr_3m_rate', 0.007, NULL, 'sourced', 'Bank of Thailand, FM_RT_001_S4 Interest Rates in Financial Market (commercial bank deposit rates)', 'https://app.bot.or.th/BTWS_STAT/statistics/BOTWEBSTAT.aspx?reportID=1033&language=ENG', '2026-09-30', '3-month time deposits 0.50-0.90% in September 2026; midpoint used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TH', 1, 'fixed_income_return_base', 0.009, NULL, 'assumption', 'BOT: 12-month time deposits 0.75-1.40% and 1-year government yield 1.00% (Sep 2026), less 15% withholding tax', 'https://app.bot.or.th/BTWS_STAT/statistics/BOTWEBSTAT.aspx?reportID=1033&language=ENG', '2026-10-31', 'Base case: 12-month deposits and 1-year government paper after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TH', 1, 'fixed_income_return_high', 0.0147, NULL, 'assumption', 'BOT 5-year government yield 1.73% (Sep 2026) less 15% tax', 'https://app.bot.or.th/BTWS_STAT/statistics/BOTWEBSTAT.aspx?reportID=1033&language=ENG', '2026-10-31', 'High case: locking in 5-year government bonds after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TH', 1, 'fixed_income_return_low', 0.006, NULL, 'assumption', 'BOT 3-month time deposits 0.50-0.90% less 15% tax', 'https://app.bot.or.th/BTWS_STAT/statistics/BOTWEBSTAT.aspx?reportID=1033&language=ENG', '2026-10-31', 'Low case: short time deposits after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TH', 1, 'goal_inflation_education', 0.025, NULL, 'assumption', 'Bank of Thailand target 1-3%; no education CPI retrieved', 'https://www.bot.or.th/en/our-roles/monetary-policy/mpc-publication/policy-interest-rate.html', '2026-10-31', 'Public schooling is free to grade 12, so we plan slightly above the 2% target midpoint for private and tertiary costs.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TH', 1, 'goal_inflation_health', 0.04, NULL, 'assumption', 'Bank of Thailand target 1-3%; no medical CPI retrieved', 'https://www.bot.or.th/en/our-roles/monetary-policy/mpc-publication/policy-interest-rate.html', '2026-10-31', 'Private medical costs usually rise faster than general prices, so we plan 2 points above the 2% target midpoint.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TH', 1, 'gold_return_base', 0.045, NULL, 'assumption', 'Trading Economics USD/THB 33.77 (30 Oct 2026), baht down 4.3% on the year', 'https://tradingeconomics.com/thailand/currency', '2026-10-31', 'Dollar gold trend of about 4% plus slight baht depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TH', 1, 'gold_return_high', 0.08, NULL, 'assumption', 'Trading Economics USD/THB 33.77 (30 Oct 2026), baht down 4.3% on the year', 'https://tradingeconomics.com/thailand/currency', '2026-10-31', 'High case with strong dollar gold and a weaker baht.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TH', 1, 'gold_return_low', 0, NULL, 'assumption', 'Trading Economics USD/THB 33.77 (30 Oct 2026), baht down 4.3% on the year', 'https://tradingeconomics.com/thailand/currency', '2026-10-31', 'Low case: flat dollar gold and a stable baht.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TH', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Labour Protection Act sets severance pay (also due on retirement) as a lump sum in tiers by length of service rather than days of wages per year of service, so it does not fit this rule''s shape; the tier amounts were not confirmed from a reachable official page in this pass.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TH', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical out-of-pocket cost of a major private hospital stay was retrieved; most people are covered by the Universal Coverage Scheme, Social Security or the civil servant scheme.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TH', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premium rates per 100,000 baht of cover were retrieved in this pass.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TH', 1, 'inflation_cpi', 0.0282, NULL, 'sourced', 'Trading Economics, citing Ministry of Commerce headline CPI (secondary source)', 'https://tradingeconomics.com/thailand/inflation-cpi', '2026-09-30', 'Headline CPI 2.82% year on year in September 2026 (2.53% in August); core 1.50%. The Commerce Ministry expects 1.8-2.2% for 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TH', 1, 'inflation_projection', 0.02, NULL, 'assumption', 'Bank of Thailand inflation target range 1-3%', 'https://www.bot.or.th/en/our-roles/monetary-policy/mpc-publication/policy-interest-rate.html', '2026-10-31', 'We plan with the midpoint of the BOT''s 1-3% target range, close to recent averages.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TH', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life is sold, but no published per-1,000-baht premium rates by age were retrieved in this pass.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TH', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No industry-wide life claim settlement ratio was found from the Office of Insurance Commission in this pass.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TH', 1, 'life_expectancy', 76.56, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=TH', '2024-12-31', 'Men 72.3, women 81.0. Latest World Bank figure is for 2024 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TH', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":23.6,"men":21.4,"women":25.7},{"age":65,"total":19.8,"men":17.8,"women":21.5},{"age":70,"total":16,"men":14.5,"women":17.4},{"age":80,"total":9.7,"men":8.9,"women":10.4}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/thailand/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TH', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'Eligibility for the old-age allowance could not be confirmed from a reachable official page in this pass.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TH', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'Thailand pays a monthly old-age allowance (เบี้ยยังชีพผู้สูงอายุ) through local governments under a 2009 Interior Ministry regulation, but the current amounts could not be confirmed from a reachable official page in this pass.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TH', 1, 'oop_health_share', 0.0993, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=TH', '2023-12-31', 'Latest World Bank figure is for 2023 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TH', 1, 'policy_rate', 0.01, NULL, 'sourced', 'Bank of Thailand, MPC decisions table (MPC 5/2026)', 'https://www.bot.or.th/content/dam/bot/documents/en/our-roles/monetary-policy/mpc-publication/policy-interest-rate/table-mpc-2026-5-5FWvBPSf.xlsx', '2026-10-28', 'The MPC held the 1-day bilateral repurchase rate at 1.00% on 28 October 2026 (cut from 1.25% to 1.00% on 25 February 2026; held in April, June and August).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TH', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":55,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'Social Security Office, old-age benefit conditions', 'https://www.sso.go.th/wpr/main/privilege/%E0%B8%81%E0%B8%AD%E0%B8%87%E0%B8%97%E0%B8%B8%E0%B8%99%E0%B8%9B%E0%B8%A3%E0%B8%B0%E0%B8%81%E0%B8%B1%E0%B8%99%E0%B8%AA%E0%B8%B1%E0%B8%87%E0%B8%84%E0%B8%A1_sub_category_list-text-photo_1_125_695', '2026-10-31', 'Social Security Fund (Section 33 employees): pension from 55 with at least 180 months of contributions and insured employment ended; fewer months give a lump sum. No automatic indexation was found; pension formula and tax treatment not confirmed in this pass.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TH', 1, 'retirement_accumulation_return_base', 0.028, NULL, 'assumption', 'BOT: 12-month time deposits 0.75-1.40% and 1-year government yield 1.00% (Sep 2026), less 15% withholding tax', 'https://app.bot.or.th/BTWS_STAT/statistics/BOTWEBSTAT.aspx?reportID=1033&language=ENG', '2026-10-31', 'Base case: roughly half equity at 4% and half bonds at 1-1.7% after tax, with some uplift from tax-advantaged funds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TH', 1, 'retirement_accumulation_return_high', 0.05, NULL, 'assumption', 'BOT: 12-month time deposits 0.75-1.40% and 1-year government yield 1.00% (Sep 2026), less 15% withholding tax', 'https://app.bot.or.th/BTWS_STAT/statistics/BOTWEBSTAT.aspx?reportID=1033&language=ENG', '2026-10-31', 'High case with the equity high case.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TH', 1, 'retirement_accumulation_return_low', 0.015, NULL, 'assumption', 'BOT: 12-month time deposits 0.75-1.40% and 1-year government yield 1.00% (Sep 2026), less 15% withholding tax', 'https://app.bot.or.th/BTWS_STAT/statistics/BOTWEBSTAT.aspx?reportID=1033&language=ENG', '2026-10-31', 'Low case for a balanced mix if equities only match bonds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TH', 1, 'retirement_age_default', 55, NULL, 'sourced', 'Social Security Office, old-age benefit conditions', 'https://www.sso.go.th/wpr/main/privilege/%E0%B8%81%E0%B8%AD%E0%B8%87%E0%B8%97%E0%B8%B8%E0%B8%99%E0%B8%9B%E0%B8%A3%E0%B8%B0%E0%B8%81%E0%B8%B1%E0%B8%99%E0%B8%AA%E0%B8%B1%E0%B8%87%E0%B8%84%E0%B8%A1_sub_category_list-text-photo_1_125_695', '2026-10-31', 'Social Security old-age pension from age 55 after at least 180 months of contributions, once insured employment ends; men and women alike. No enacted increase was found, so 55 also applies to people born after 1975.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TH', 1, 'retirement_age_government', 60, NULL, 'sourced', 'Wikipedia, Retirement age (secondary source)', 'https://en.wikipedia.org/wiki/Retirement_age', '2026-10-31', 'Thai civil servants retire at 60 (university presidents may work beyond 60); secondary source only, the Office of the Civil Service Commission page was not checked.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TH', 1, 'retirement_return_base', 0.009, NULL, 'assumption', 'BOT: 12-month time deposits 0.75-1.40% and 1-year government yield 1.00% (Sep 2026), less 15% withholding tax', 'https://app.bot.or.th/BTWS_STAT/statistics/BOTWEBSTAT.aspx?reportID=1033&language=ENG', '2026-10-31', 'Base case at the after-tax 12-month deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TH', 1, 'retirement_return_high', 0.0147, NULL, 'assumption', 'BOT 5-year government yield 1.73% (Sep 2026) less 15% tax', 'https://app.bot.or.th/BTWS_STAT/statistics/BOTWEBSTAT.aspx?reportID=1033&language=ENG', '2026-10-31', 'High case: laddered 5-year government bonds after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TH', 1, 'retirement_return_low', 0.006, NULL, 'assumption', 'BOT 3-month time deposits 0.50-0.90% less 15% tax', 'https://app.bot.or.th/BTWS_STAT/statistics/BOTWEBSTAT.aspx?reportID=1033&language=ENG', '2026-10-31', 'Low case: short time deposits after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TH', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Public Debt Management Office sells government savings bonds to individuals in periodic issues, but its site could not be reached in this pass, so the current rate is not reported.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TH', 1, 'savings_account_rate', 0.001, NULL, 'sourced', 'Bank of Thailand, FM_RT_001_S4 Interest Rates in Financial Market (commercial bank deposit rates)', 'https://app.bot.or.th/BTWS_STAT/statistics/BOTWEBSTAT.aspx?reportID=1033&language=ENG', '2026-09-30', 'Savings deposit rates range 0.10% (minimum, typical at large banks) to 1.75% (maximum) in September 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TH', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":4.34},{"year":2040,"value":2.45},{"year":2065,"value":1.7}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/thailand/2040/', '2025-12-31', '100 / old-age dependency ratio: 23.02 (2025, World Bank), 40.8 (2040) and 58.7 (2065, populationpyramid.net/thailand/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TH', 1, 'tax_bank_interest', 0.15, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Thailand individual income determination (secondary source)', 'https://taxsummaries.pwc.com/thailand/individual/income-determination', '2026-10-31', 'Interest from bank deposits is subject to 15% withholding tax, which residents may treat as final or credit against progressive tax. Some savings-account interest is exempt up to a yearly limit (not confirmed in this pass).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TH', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'The tax treatment of government savings bond interest was not confirmed from a reachable official page in this pass.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TH', 1, 'tbill_91d_rate', 0.0097, NULL, 'sourced', 'Bank of Thailand, FM_RT_001_S4 Interest Rates in Financial Market (T-bill and government bond yield)', 'https://app.bot.or.th/BTWS_STAT/statistics/BOTWEBSTAT.aspx?reportID=1033&language=ENG', '2026-09-30', '3-month government yield 0.97% in September 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TH', 1, 'tbond_10y_rate', 0.0231, NULL, 'sourced', 'Bank of Thailand, FM_RT_001_S4 Interest Rates in Financial Market (T-bill and government bond yield)', 'https://app.bot.or.th/BTWS_STAT/statistics/BOTWEBSTAT.aspx?reportID=1033&language=ENG', '2026-09-30', 'Trading Economics shows 2.09% on 30 October 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TH', 1, 'tbond_5y_rate', 0.0173, NULL, 'sourced', 'Bank of Thailand, FM_RT_001_S4 Interest Rates in Financial Market (T-bill and government bond yield)', 'https://app.bot.or.th/BTWS_STAT/statistics/BOTWEBSTAT.aspx?reportID=1033&language=ENG', '2026-09-30', NULL, 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('TJ', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"TJ","iso3":"TJK","nameEn":"Tajikistan","nameNative":"Тоҷикистон","region":"europe_central_asia","languages":["tg","ru","uz"],"currency":{"code":"TJS","symbol":"TJS","decimals":2,"compact":"intl","usdRate":{"value":9.2057,"status":"sourced","sourceName":"Trading Economics, USD/TJS (secondary source)","sourceUrl":"https://tradingeconomics.com/tajikistan/currency","asOf":"2026-10-30","note":"The NBT official-rate page was unreachable; World Bank 2025 average 10.02."}},"instruments":{"savings_account":{"available":true,"localName":"Амонати ба талаб","localNameEn":"Demand / savings deposit"},"fdr_3m":{"available":true,"localName":"Амонати мӯҳлатнок","localNameEn":"Term deposit (3 months)"},"fdr_1y":{"available":true,"localName":"Амонати мӯҳлатнок","localNameEn":"Term deposit (1 year)"},"dps":{"available":false,"localName":null,"localNameEn":"Monthly recurring deposit","note":"No standard recurring-deposit product with a published rate was found."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":"Government savings certificate","note":"No retail government savings certificate or bond for individuals was found."},"tbill_91d":{"available":false,"localName":null,"localNameEn":"Treasury bills","note":"Government securities are auctioned to banks and institutions since 2024; not offered to individuals.","sourceUrl":"https://www.imf.org/en/publications/cr/issues/2025/07/08/republic-of-tajikistan-2025-article-iv-consultation-and-second-review-under-the-policy-568379"},"tbond_5y":{"available":false,"localName":null,"localNameEn":"Government bonds","note":"No retail access or secondary market yet (IMF 2025 Article IV).","sourceUrl":"https://www.imf.org/en/publications/cr/issues/2025/07/08/republic-of-tajikistan-2025-article-iv-consultation-and-second-review-under-the-policy-568379"},"tbond_10y":{"available":false,"localName":null,"localNameEn":"Government bonds","note":"No 10-year bonds are issued to the market.","sourceUrl":"https://www.imf.org/en/publications/cr/issues/2025/07/08/republic-of-tajikistan-2025-article-iv-consultation-and-second-review-under-the-policy-568379"},"equity_fund":{"available":false,"localName":null,"localNameEn":"Equity fund","note":"No retail mutual or index funds were found; the local stock exchange has very little trading."},"gold":{"available":true,"localName":"Тилло","localNameEn":"Gold","note":"Gold jewellery and bars can be bought legally; availability of standard investment bars was not confirmed."}},"institutions":{"centralBank":{"name":"National Bank of Tajikistan (Бонки миллии Тоҷикистон)","url":"https://nbt.tj/en/"},"insuranceRegulator":{"name":"National Bank of Tajikistan (insurance supervision)","url":"https://nbt.tj/en/","note":"Insurance supervision was not confirmed from a reachable page."},"insuranceComplaints":null,"pensionScheme":null,"oldAgeAllowance":null,"publicHealthCover":{"name":"Ministry of Health and Social Protection of the Population (state-guaranteed basic health services)","url":"https://moh.tj/"},"depositInsurance":{"name":"Deposit Insurance Fund of Tajikistan (Хазинаи суғуртаи амонату пасандозҳо)","url":"https://dif.tj/andozai-ubronpulii-su-urta/"},"statistics":{"name":"Agency on Statistics under the President of the Republic of Tajikistan","url":"https://www.stat.tj/en/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TJ', 1, 'bank_deposit_avg_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The National Bank of Tajikistan site (nbt.tj), which publishes bank interest-rate statistics, refused connections; World Bank FR.INR.DPST stops in 2019 (5.2%), too old to use.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TJ', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap or published typical rate for credit-card balances could be found; card credit is little used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TJ', 1, 'deposit_insurance_limit', 35000, NULL, 'sourced', 'Deposit Insurance Fund of Tajikistan (Хазинаи суғуртаи амонату пасандозҳо), compensation amount', 'https://dif.tj/andozai-ubronpulii-su-urta/', '2026-10-31', 'Up to 35,000 somoni per depositor per institution; foreign-currency deposits are compensated in somoni at the NBT rate; interest is not compensated.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TJ', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published rate for monthly recurring deposits could be found. The National Bank of Tajikistan site (nbt.tj), which publishes bank interest-rate statistics, refused connections.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TJ', 1, 'equity_return_base', 0.09, NULL, 'assumption', 'Global equity index in somoni terms (no liquid local market); NBT refinancing rate 7% as safe-rate proxy', 'https://tradingeconomics.com/tajikistan/interest-rate', '2026-10-31', 'Base case uses global equities (about 7% in dollars) plus about 2% a year somoni depreciation, kept within 4 points of the refinancing-rate proxy for the safe rate; the local exchange has almost no trading.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TJ', 1, 'equity_return_high', 0.12, NULL, 'assumption', 'Global equity index in somoni terms', 'https://tradingeconomics.com/tajikistan/interest-rate', '2026-10-31', 'High case: strong global markets and faster somoni depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TJ', 1, 'equity_return_low', 0.05, NULL, 'assumption', 'No functioning local stock market; global equities in somoni terms. NBT refinancing rate 7%', 'https://tradingeconomics.com/tajikistan/interest-rate', '2026-10-31', 'Low case: a global equity fund returning about 5% in somoni if the somoni stays firm against the dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TJ', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No typical 1-year term deposit rate could be read. The National Bank of Tajikistan site (nbt.tj), which publishes bank interest-rate statistics, refused connections.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TJ', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No typical 3-month term deposit rate could be read. The National Bank of Tajikistan site (nbt.tj), which publishes bank interest-rate statistics, refused connections.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TJ', 1, 'fixed_income_return_base', 0.06, NULL, 'assumption', 'NBT refinancing rate 7% (Trading Economics)', 'https://tradingeconomics.com/tajikistan/interest-rate', '2026-10-31', 'Base case: somoni term deposits assumed a little below the policy rate after any tax; no published deposit rate could be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TJ', 1, 'fixed_income_return_high', 0.08, NULL, 'assumption', 'NBT refinancing rate 7% (Trading Economics)', 'https://tradingeconomics.com/tajikistan/interest-rate', '2026-10-31', 'High case: longer somoni term deposits, which usually pay above the policy rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TJ', 1, 'fixed_income_return_low', 0.04, NULL, 'assumption', 'NBT refinancing rate 7% (Trading Economics); deposit rates unpublished in reachable sources', 'https://tradingeconomics.com/tajikistan/interest-rate', '2026-10-31', 'Low case: easy-access somoni savings well below the policy rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TJ', 1, 'goal_inflation_education', 0.06, NULL, 'assumption', 'NBT inflation target 5% ± 2', 'https://www.imf.org/en/publications/cr/issues/2025/07/08/republic-of-tajikistan-2025-article-iv-consultation-and-second-review-under-the-policy-568379', '2026-10-31', 'Private tuition and university contract fees are planned at a point above the inflation target.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TJ', 1, 'goal_inflation_health', 0.07, NULL, 'assumption', 'NBT inflation target 5% ± 2; out-of-pocket share of health spending 62% (World Bank)', 'https://www.imf.org/en/publications/cr/issues/2025/07/08/republic-of-tajikistan-2025-article-iv-consultation-and-second-review-under-the-policy-568379', '2026-10-31', 'Most health spending is paid out of pocket for medicines and informal fees, which tend to rise faster than the CPI, so 2 points above the inflation target is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TJ', 1, 'gold_return_base', 0.06, NULL, 'assumption', 'Gold price history (Trading Economics); NBT 5% inflation target', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Base case: dollar gold rises with world inflation plus a little, and the somoni loses about 2% a year against the dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TJ', 1, 'gold_return_high', 0.1, NULL, 'assumption', 'Gold price history (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'High case: a repeat of gold''s 2005-2025 trend plus faster somoni depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TJ', 1, 'gold_return_low', 0.02, NULL, 'assumption', 'Gold price history (Trading Economics); somoni at 9.21 per dollar, firmer than the 2025 average of 10.02', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Low case: dollar gold flat after the 2025-26 spike while the somoni holds its value.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TJ', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No statutory days-per-year gratuity for private employees was found; the Labour Code''s severance on dismissal (redundancy, liquidation) is a lump sum of average monthly pay, not a gratuity. The legal database could not be reached to confirm, so not marked absent.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TJ', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical out-of-pocket cost of a major hospital stay could be found; the Ministry of Health site has no such figure.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TJ', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premium table could be found; voluntary health insurance is rare.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TJ', 1, 'inflation_cpi', 0.041, NULL, 'sourced', 'Trading Economics, Tajikistan inflation rate (National Bank of Tajikistan data, secondary source)', 'https://tradingeconomics.com/tajikistan/inflation-cpi', '2026-09-30', 'CPI up 4.1% year on year in September 2026 (unchanged from August). The National Bank of Tajikistan site (nbt.tj), which publishes bank interest-rate statistics, refused connections; the Statistics Agency gives 3.5% for 2025 and the World Bank 3.4%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TJ', 1, 'inflation_projection', 0.05, NULL, 'assumption', 'National Bank of Tajikistan inflation target 5% ± 2 points since 2025 (IMF 2025 Article IV)', 'https://www.imf.org/en/publications/cr/issues/2025/07/08/republic-of-tajikistan-2025-article-iv-consultation-and-second-review-under-the-policy-568379', '2026-10-31', 'The NBT lowered its medium-term target from 6% to 5% ± 2 in 2025 and inflation has stayed inside the band, so the 5% centre is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TJ', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published term-life premium rates could be found; the life insurance market is very small. Not confirmed absent.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TJ', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No industry-wide life insurance claim settlement ratio is published by the insurance supervisor that could be found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TJ', 1, 'life_expectancy', 72.2, NULL, 'sourced', 'GeoRank, Tajikistan life expectancy (UN World Population Prospects, 2026 estimate)', 'https://georank.org/life-expectancy/tajikistan', '2026-07-01', 'Men 69.9, women 74.5; World Bank 2024: 71.9.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TJ', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":18,"men":16.6,"women":19.3},{"age":65,"total":14.4,"men":13.2,"women":15.5},{"age":70,"total":11.2,"men":10.2,"women":12},{"age":80,"total":6.2,"men":5.7,"women":6.5}]}', 'sourced', 'GeoRank, Tajikistan life expectancy by age (UN World Population Prospects, 2026)', 'https://georank.org/life-expectancy/tajikistan', '2026-07-01', 'Remaining years = expected age at death at each age minus the age.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TJ', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'Eligibility ages for the social pension could not be confirmed from a reachable official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TJ', 1, 'old_age_allowance_monthly', 412.6, NULL, 'sourced', 'Asia-Plus (news, secondary source), citing the Agency for Social Insurance and Pensions', 'https://asiaplus.news/en/2026/10/21/adb-proposes-tajikistan-consider-raising-retirement-age/', '2026-09-01', 'Average social pension 412.60 somoni a month after the 1 September 2026 indexation (at least +15%); social pensions go to people who do not qualify for an insurance pension. This is an average across social pensions, not a fixed old-age rate; the agency site could not be reached.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TJ', 1, 'oop_health_share', 0.6236, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=TJ', '2023-12-31', 'Latest year 2023 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TJ', 1, 'policy_rate', 0.07, NULL, 'sourced', 'Asia-Plus (news, secondary source): National Bank of Tajikistan keeps refinancing rate at 7%', 'https://asiaplus.news/en/2026/11/02/tajikistans-national-bank-keeps-interest-rate-at-7/', '2026-10-29', 'The NBT Monetary Policy Committee kept the refinancing rate at 7.0% on 29 October 2026, unchanged since February 2026; Trading Economics also shows 7%. The NBT site (nbt.tj) refused connections.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TJ', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":63,"nomineeUntilAge":null,"inflationLinked":true,"taxFree":null}', 'sourced', 'Asia-Plus (news, secondary source), citing the Agency for Social Insurance and Pensions and an ADB report', 'https://asiaplus.news/en/2026/10/21/adb-proposes-tajikistan-consider-raising-retirement-age/', '2026-10-21', 'State insurance pension financed by the social tax on employers, employees and the self-employed; paid from 63 (men) and 58 (women) with a minimum record of 25 and 20 years. Pensions are indexed by presidential decree: on 1 September 2026 at the 2025 inflation rate but not less than 15% (Asia-Plus, 1 Sep 2026); 2025 indexation was 10%. Average insurance pension 591.06 somoni after indexation. Entry ages and tax treatment not confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TJ', 1, 'retirement_accumulation_return_base', 0.075, NULL, 'assumption', 'Fixed income base 6%; equity base 9%', 'https://tradingeconomics.com/tajikistan/interest-rate', '2026-10-31', 'Base case: half somoni deposits, half global equity in somoni terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TJ', 1, 'retirement_accumulation_return_high', 0.1, NULL, 'assumption', 'Fixed income high 8%; equity high 12%', 'https://tradingeconomics.com/tajikistan/interest-rate', '2026-10-31', 'High case for a growth-leaning mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TJ', 1, 'retirement_accumulation_return_low', 0.05, NULL, 'assumption', 'Fixed income low 4%; equity low 5%', 'https://tradingeconomics.com/tajikistan/interest-rate', '2026-10-31', 'Low case for a balanced mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TJ', 1, 'retirement_age_default', 63, NULL, 'sourced', 'Asia-Plus (news, secondary source), citing the Agency for Social Insurance and Pensions', 'https://asiaplus.news/en/2026/10/23/tajik-authorities-comment-on-adb-proposal-to-raise-retirement-age/', '2026-10-23', 'Pension age 63 for men and 58 for women under current law; on 22 October 2026 the Agency for Social Insurance and Pensions said an ADB proposal to raise it (women to 63, or 65 for all) is advisory and changes nothing until legislated. Minimum insurance record 25 years (men) and 20 years (women).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TJ', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'No separate retirement age for government employees could be confirmed from a reachable source; civil servants are believed to follow the general pension ages.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TJ', 1, 'retirement_return_base', 0.06, NULL, 'assumption', 'NBT refinancing rate 7% as a proxy for the 1-year somoni deposit rate', 'https://tradingeconomics.com/tajikistan/interest-rate', '2026-10-31', 'Base case kept below the policy rate because no after-tax 1-year deposit or bill rate could be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TJ', 1, 'retirement_return_high', 0.075, NULL, 'assumption', 'NBT refinancing rate 7%', 'https://tradingeconomics.com/tajikistan/interest-rate', '2026-10-31', 'High case: longer somoni term deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TJ', 1, 'retirement_return_low', 0.04, NULL, 'assumption', 'NBT refinancing rate 7%', 'https://tradingeconomics.com/tajikistan/interest-rate', '2026-10-31', 'Low case: easy-access somoni savings.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TJ', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No retail government savings certificate or savings bond for individuals could be found; the Ministry of Finance started market auctions of government securities in 2024, bought by banks and the Deposit Insurance Fund (IMF 2025 Article IV).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TJ', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No typical savings-account rate could be read. The National Bank of Tajikistan site (nbt.tj), which publishes bank interest-rate statistics, refused connections.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TJ', 1, 'support_ratio', NULL, '{"points":[{"year":2026,"value":14.08},{"year":2040,"value":10},{"year":2065,"value":5.62}]}', 'sourced', 'PopulationPyramid.net, Tajikistan (UN World Population Prospects)', 'https://www.populationpyramid.net/tajikistan/2040/', '2026-07-01', '100 divided by the old-age dependency ratio: 7.1 in 2026, 10.0 in 2040 and 17.8 in 2065 (pages /tajikistan/2026/ and /tajikistan/2065/). World Bank 2025: 6.8.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TJ', 1, 'tax_bank_interest', NULL, NULL, 'missing', '', '', '2026-10-31', 'The tax treatment of individuals'' bank interest under the 2021 Tax Code could not be confirmed: the Tax Committee site (andoz.tj) failed its certificate check and PwC Tax Summaries does not cover Tajikistan.', 0);
