INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TJ', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Ministry of Finance has auctioned government securities since 2024 (IMF 2025 Article IV), but no current 91-day yield could be read; the Ministry of Finance and NBT sites were unreachable.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TJ', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 10-year government bond yield exists in a readable source; domestic public debt is mainly legacy bonds held by the NBT (IMF 2025 Article IV).', 0);
