INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('TL', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"TL","iso3":"TLS","nameEn":"Timor-Leste","nameNative":"Timór-Leste","region":"east_asia_pacific","languages":["tet","pt","id","en"],"currency":{"code":"USD","symbol":"$","decimals":2,"compact":"intl","usdRate":{"value":1,"status":"sourced","sourceName":"World Bank WDI PA.NUS.FCRF (Timor-Leste uses the US dollar)","sourceUrl":"https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=TL","asOf":"2025-12-31","note":"The US dollar is legal tender; BCTL issues only centavo coins."}},"instruments":{"savings_account":{"available":true,"localName":"Conta poupança","localNameEn":"Savings account","note":"Portuguese name; Tetum: konta poupansa.","sourceUrl":"https://www.bancocentral.tl/stats/interestratedoc/download/c4ca4238a0b923820dcc509a6f75849b/"},"fdr_3m":{"available":true,"localName":"Depósito a prazo","localNameEn":"3-month time deposit","sourceUrl":"https://www.bancocentral.tl/stats/interestratedoc/download/c4ca4238a0b923820dcc509a6f75849b/"},"fdr_1y":{"available":true,"localName":"Depósito a prazo","localNameEn":"12-month time deposit","sourceUrl":"https://www.bancocentral.tl/stats/interestratedoc/download/c4ca4238a0b923820dcc509a6f75849b/"},"dps":{"available":false,"localName":null,"note":"No monthly recurring deposit product found in BCTL publications."},"sanchayapatra_5y":{"available":false,"localName":null,"note":"No government savings certificate or retail bond found."},"tbill_91d":{"available":false,"localName":null,"note":"No domestic treasury bills found."},"tbond_5y":{"available":false,"localName":null,"note":"No domestic government bonds found."},"tbond_10y":{"available":false,"localName":null,"note":"No domestic government bonds found."},"equity_fund":{"available":false,"localName":null,"note":"No local stock exchange or locally offered mutual funds found."},"gold":{"available":true,"localName":"Ouro","localNameEn":"Gold","note":"No legal restriction on buying gold was found; mainly sold as jewellery."}},"institutions":{"centralBank":{"name":"Banco Central de Timor-Leste","url":"https://www.bancocentral.tl/"},"insuranceRegulator":{"name":"Banco Central de Timor-Leste (licenses and supervises insurers)","url":"https://www.bancocentral.tl/stats/insurance/"},"insuranceComplaints":{"name":"Banco Central de Timor-Leste consumer protection","url":"https://www.bancocentral.tl/stats/con_protect/"},"pensionScheme":{"name":"Instituto Nacional de Segurança Social (INSS), under the Ministry of Social Solidarity and Inclusion","url":"https://mssi.gov.tl/","note":"The INSS website (segurancasocial.gov.tl) showed only a placeholder page in October 2026."},"oldAgeAllowance":{"name":"Social pension for the elderly and disabled (paid by INSS)","url":"https://mssi.gov.tl/"},"publicHealthCover":{"name":"Ministério da Saúde (public health services, free at the point of care)","url":"https://ms.gov.tl/","note":"The ministry site returned HTTP 502 when checked on 3 November 2026."},"depositInsurance":null,"statistics":{"name":"Instituto Nacional de Estatística Timor-Leste (INETL)","url":"https://inetl-ip.gov.tl/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TL', 1, 'bank_deposit_avg_rate', 0.0046, NULL, 'sourced', 'World Bank WDI FR.INR.DPST (deposit interest rate)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=TL', '2025-12-31', 'BCTL Table 10 has no single weighted average across all deposits; time deposit rates were 0.42-0.46% in August 2026.', 0);
