INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TL', 1, 'equity_return_base', 0.04, NULL, 'assumption', 'No local stock exchange; global equity index in US dollars; BCTL Table 10, commercial bank 12-month time deposit rate 0.46% (August 2026)', 'https://www.bancocentral.tl/stats/interestratedoc/download/c4ca4238a0b923820dcc509a6f75849b/', '2026-10-31', 'There is no local stock market, so the base is a global index in US dollars, capped at the 0.46% safe deposit rate plus under 4 points.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TL', 1, 'equity_return_high', 0.07, NULL, 'assumption', 'No local stock exchange; global equity index in US dollars; BCTL Table 10, commercial bank 12-month time deposit rate 0.46% (August 2026)', 'https://www.bancocentral.tl/stats/interestratedoc/download/c4ca4238a0b923820dcc509a6f75849b/', '2026-10-31', 'High case near the long-run nominal return of world equities in US dollars.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TL', 1, 'equity_return_low', 0.02, NULL, 'assumption', 'No local stock exchange; global equity index in US dollars; BCTL Table 10, commercial bank 12-month time deposit rate 0.46% (August 2026)', 'https://www.bancocentral.tl/stats/interestratedoc/download/c4ca4238a0b923820dcc509a6f75849b/', '2026-10-31', 'Low case for a global index fund held in US dollars after weak decades for world shares.', 0);
