INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TL', 1, 'fdr_3m_rate', 0.0042, NULL, 'sourced', 'Banco Central de Timor-Leste, Table 10 Commercial Bank Interest Rate (3-month time deposit)', 'https://www.bancocentral.tl/stats/interestratedoc/download/c4ca4238a0b923820dcc509a6f75849b/', '2026-08-26', 'Average 3-month time deposit rate 0.42% in August 2026 (0.54% in June).', 0);
