INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TL', 1, 'fixed_income_return_high', 0.006, NULL, 'assumption', 'BCTL Table 10, commercial bank 12-month time deposit rate 0.46% (August 2026)', 'https://www.bancocentral.tl/stats/interestratedoc/download/c4ca4238a0b923820dcc509a6f75849b/', '2026-10-31', 'High case: 6-12 month deposits back at the 2024-25 level of about 0.6-0.7%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TL', 1, 'fixed_income_return_low', 0.002, NULL, 'assumption', 'BCTL Table 10, commercial bank 12-month time deposit rate 0.46% (August 2026)', 'https://www.bancocentral.tl/stats/interestratedoc/download/c4ca4238a0b923820dcc509a6f75849b/', '2026-10-31', 'Low case: savings or short deposits if rates keep falling (the 12-month rate fell from 0.68% to 0.46% in mid-2026).', 0);
