INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TL', 1, 'inflation_cpi', -0.0008, NULL, 'sourced', 'Banco Central de Timor-Leste inflation report (national CPI compiled by the statistics office)', 'https://www.bancocentral.tl/stats/inflationdoc/download/c4ca4238a0b923820dcc509a6f75849b/', '2026-08-31', 'Timor-Leste CPI year-on-year -0.08% in August 2026 (index 125.5); 0.48% in July. Dili CPI was +0.41%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TL', 1, 'inflation_projection', 0.03, NULL, 'assumption', 'BCTL CPI history: 5.3% (Dec 2021), 6.9% (2022), 8.7% (2023), -0.4% (2024), 1.0% (2025); US dollar is the legal currency', 'https://www.bancocentral.tl/stats/inflationdoc/download/c4ca4238a0b923820dcc509a6f75849b/', '2026-10-31', 'Timor-Leste uses the US dollar, so long-run inflation should track US inflation plus import costs; the 2021-2025 average (about 4%) is inflated by the 2022-23 shock, so we plan with 3%.', 0);
