INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TL', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":17.1,"men":16.2,"women":18},{"age":65,"total":13.6,"men":12.9,"women":14.4},{"age":70,"total":10.6,"men":10,"women":11.1},{"age":80,"total":5.8,"men":5.5,"women":6}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/timor-leste/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026 (rows 60-64, 65-69, 70-74, 80-84); totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TL', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":60,"womenAge":60,"over90Monthly":null,"meansTested":true}', 'sourced', 'Tatoli (national news agency): Government adjusts the social pension for the disabled and elderly', 'https://tatoli.tl/2024/01/10/governu-halo-ajustamentu-rejime-juridiku-pensaun-sosial-invalides-no-ferik-katuas/', '2024-01-10', 'Non-contributory social pension from 60, with higher rates at 70 and 80; since the 2024 amendment it cannot be combined with income from work (Tatoli 10 January 2024). Figure dates from 2024 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TL', 1, 'old_age_allowance_monthly', 60, NULL, 'sourced', 'Tatoli (national news agency): INSS plans monthly payments for elderly and disabled', 'https://tatoli.tl/2024/02/22/inss-planeia-halo-pagamentu-ba-idozu-no-invalidez-kada-fulan/', '2024-02-22', 'Social pension US$60 a month from 60 (US$80 at 70-79, US$100 at 80+), per Tatoli 10 January and 22 February 2024; figure dates from 2024 (older than 2025) and no 2025-2026 update was found. Not payable alongside income from work.', 0);
