INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TL', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":60,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'Tatoli (national news agency): social security old-age rights from 60; contributions per Tatoli 14 May 2026', 'https://tatoli.tl/2026/07/20/kfp-esklarese-regra-no-prosedimentu-reforma-ba-funsionariu-publiku-iha-raeoa/', '2026-07-20', 'Contributory INSS scheme under Law 12/2016: old-age pension from 60 (Tatoli 20 July 2026); 4% employee plus 6% employer contributions (Tatoli 14 May 2026). No automatic indexation rule was confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TL', 1, 'retirement_accumulation_return_base', 0.022, NULL, 'assumption', 'Mix of local deposits (0.46%) and global equity in US dollars', 'https://www.bancocentral.tl/stats/interestratedoc/download/c4ca4238a0b923820dcc509a6f75849b/', '2026-10-31', 'Base case: half local deposits at about 0.4% and half a global equity fund at 4%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TL', 1, 'retirement_accumulation_return_high', 0.04, NULL, 'assumption', 'Mix of local deposits (0.46%) and global equity in US dollars', 'https://www.bancocentral.tl/stats/interestratedoc/download/c4ca4238a0b923820dcc509a6f75849b/', '2026-10-31', 'High case with a larger, well-performing global equity share.', 0);
