INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TL', 1, 'retirement_age_default', 60, NULL, 'sourced', 'Tatoli (national news agency): Civil Service Commission explains retirement rules', 'https://tatoli.tl/2026/07/20/kfp-esklarese-regra-no-prosedimentu-reforma-ba-funsionariu-publiku-iha-raeoa/', '2026-07-20', 'The social security regime (Law 12/2016) gives old-age rights from age 60, the same for men and women.', 0);
