INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TL', 1, 'savings_account_rate', 0.0047, NULL, 'sourced', 'Banco Central de Timor-Leste, Table 10 Commercial Bank Interest Rate (saving deposit)', 'https://www.bancocentral.tl/stats/interestratedoc/download/c4ca4238a0b923820dcc509a6f75849b/', '2026-08-26', 'Average commercial bank savings deposit rate 0.47% in August 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TL', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":11.8},{"year":2040,"value":11.4},{"year":2065,"value":5.7}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/timor-leste/2040/', '2025-12-31', '100 / old-age dependency ratio: 8.48 (2025, World Bank) gives 11.8; populationpyramid.net (UN WPP 2024) gives 8.8 for 2040 (11.4) and 17.4 for 2065 (5.7, populationpyramid.net/timor-leste/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TL', 1, 'tax_bank_interest', NULL, NULL, 'missing', '', '', '2026-10-31', 'The tax authority and Ministry of Finance tax pages could not be read (site unreachable or script-only); no withholding rate on bank interest was confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TL', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate exists, so no tax rule applies; searched BCTL and Ministry of Finance pages.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TL', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No domestic treasury bill market was found in BCTL statistics; the state finances itself mainly from the Petroleum Fund.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TL', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No domestic government bond market was found in BCTL statistics.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TL', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No domestic government bond market was found in BCTL statistics.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('TM', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"TM","iso3":"TKM","nameEn":"Turkmenistan","nameNative":"Türkmenistan","region":"europe_central_asia","languages":["tk","ru","uz"],"currency":{"code":"TMT","symbol":"TMT","decimals":2,"compact":"intl","usdRate":{"value":3.5,"status":"sourced","sourceName":"Central Bank of Turkmenistan, official exchange rates","sourceUrl":"https://www.cbt.tm/kurs/kurs_today_en.html","asOf":"2026-10-31","note":"Official rate fixed at TMT 3.50 per US dollar (the list valid from 2 November 2026 is unchanged). Access to foreign currency at this rate is restricted and an unofficial market rate several times higher is widely reported, so dollar conversions are only indicative. The World Bank has no recent figure (its PA.NUS.FCRF series ends in 2001)."}},"instruments":{"savings_account":{"available":true,"localName":"Talap edilýänçä goýum","localNameEn":"Demand deposit","note":"Deposits are taken by the state and joint-stock banks listed by the central bank; rates are not published centrally.","sourceUrl":"https://www.cbt.tm/en/hyzmatlar.html"},"fdr_3m":{"available":true,"localName":"Möhletleýin goýum (3 aý)","localNameEn":"Term deposit (3 months)","sourceUrl":"https://www.cbt.tm/en/hyzmatlar.html"},"fdr_1y":{"available":true,"localName":"Möhletleýin goýum (1 ýyl)","localNameEn":"Term deposit (1 year)","sourceUrl":"https://www.cbt.tm/en/hyzmatlar.html"},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No monthly recurring-deposit scheme was confirmed."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate or retail savings bond for individuals was found."},"tbill_91d":{"available":false,"localName":null,"localNameEn":null,"note":"No treasury bill market open to individuals was found."},"tbond_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government bond market open to individuals was found."},"tbond_10y":{"available":false,"localName":null,"localNameEn":null,"note":"No government bond market open to individuals was found."},"equity_fund":{"available":false,"localName":null,"localNameEn":null,"note":"No retail mutual or index funds were found, and currency controls make foreign funds very hard to buy."},"gold":{"available":false,"localName":null,"localNameEn":null,"note":"The central bank publishes a manat gold price, but retail sale of investment gold bars or coins was not confirmed; jewellery is the usual form of gold saving."}},"institutions":{"centralBank":{"name":"Central Bank of Turkmenistan","url":"https://www.cbt.tm/en/"},"insuranceRegulator":{"name":"Ministry of Finance and Economy of Turkmenistan","url":"https://fineconomic.gov.tm/","note":"Insurance supervision sits with the finance ministry (not re-checked in this research)."},"pensionScheme":{"name":"Pension Fund of Turkmenistan (Ministry of Labour and Social Protection of Population)","url":"https://mlsp.gov.tm/pensia_gaznasy"},"oldAgeAllowance":{"name":"State social allowance (döwlet durmuş kömek puly), Ministry of Labour and Social Protection of Population","url":"https://mlsp.gov.tm/faq"},"publicHealthCover":{"name":"Ministry of Health and Medical Industry of Turkmenistan","url":"https://saglykhm.gov.tm/","note":"Public clinics and hospitals with a voluntary state health insurance scheme; most costs are paid out of pocket."},"statistics":{"name":"State Committee of Turkmenistan on Statistics","url":"https://www.stat.gov.tm/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TM', 1, 'bank_deposit_avg_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No weighted average deposit rate is published; the World Bank has no FR.INR.DPST figure for Turkmenistan.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TM', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap or published typical rate for card credit was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TM', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No deposit insurance scheme or published cover limit was found; most deposit-taking banks are state-owned.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TM', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No official information on recurring deposit products was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TM', 1, 'equity_return_base', 0.065, NULL, 'assumption', 'Global equities about 6.5% a year in dollars; manat fixed to the dollar (Central Bank of Turkmenistan)', 'https://www.cbt.tm/kurs/kurs_today_en.html', '2026-10-31', 'Base case: a global index earning about 6.5% a year in dollars with the official peg held, about 1.5 points above the assumed safe rate; buying foreign funds is in practice very hard for residents.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TM', 1, 'equity_return_high', 0.1, NULL, 'assumption', 'Global equity record; risk of a manat devaluation from the fixed official rate', 'https://www.cbt.tm/kurs/kurs_today_en.html', '2026-10-31', 'High case: strong global shares, or a devaluation that raises the manat value of foreign assets.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TM', 1, 'equity_return_low', 0.03, NULL, 'assumption', 'No functioning local stock market; global equities in manat (fixed at TMT 3.50 per USD, Central Bank of Turkmenistan)', 'https://www.cbt.tm/kurs/kurs_today_en.html', '2026-10-31', 'Equity returns are based on a global index in manat terms because there is no liquid local market; low case is a weak decade for global shares at a fixed exchange rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TM', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No official term deposit rate statistics were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TM', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No official term deposit rate statistics were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TM', 1, 'fixed_income_return_base', 0.05, NULL, 'assumption', 'IMF WEO inflation projections for Turkmenistan; inflation projection 5%', 'https://www.imf.org/external/datamapper/api/v1/PCPIPCH/TKM', '2026-10-31', 'No deposit rate statistics are published, so the base case assumes manat deposits roughly keep pace with the 5% inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TM', 1, 'fixed_income_return_high', 0.07, NULL, 'assumption', 'IMF WEO inflation projections for Turkmenistan; inflation projection 5%', 'https://www.imf.org/external/datamapper/api/v1/PCPIPCH/TKM', '2026-10-31', 'High case: deposits earn about 2 points above inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TM', 1, 'fixed_income_return_low', 0.03, NULL, 'assumption', 'IMF WEO inflation projections for Turkmenistan (4.1-4.6% in 2027-2030)', 'https://www.imf.org/external/datamapper/api/v1/PCPIPCH/TKM', '2026-10-31', 'Low case: bank deposits pay below inflation, as is common under administered interest rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TM', 1, 'goal_inflation_education', 0.06, NULL, 'assumption', 'IMF WEO inflation projections for Turkmenistan', 'https://www.imf.org/external/datamapper/api/v1/PCPIPCH/TKM', '2026-10-31', 'No education price index is published; tuition and study costs (often abroad) are assumed to rise 1 point faster than general inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TM', 1, 'goal_inflation_health', 0.06, NULL, 'assumption', 'IMF WEO inflation projections; World Bank out-of-pocket share 77%', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=TM', '2026-10-31', 'No health price index is published; medical costs, largely paid out of pocket and often imported, are assumed to rise 1 point faster than the 5% general inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TM', 1, 'gold_return_base', 0.045, NULL, 'assumption', 'Gold price history (Trading Economics); manat fixed at TMT 3.50 per USD', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Base case: dollar gold rises about 4-5% a year, in line with its long-run trend, with no change in the official rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TM', 1, 'gold_return_high', 0.12, NULL, 'assumption', 'Gold price history (Trading Economics); devaluation risk of the fixed official rate', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'High case: strong dollar gold plus a devaluation of the official manat rate toward the unofficial market rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TM', 1, 'gold_return_low', 0, NULL, 'assumption', 'Gold USD 3,876/oz on 30 Oct 2026, down 3% on a year (Trading Economics); manat fixed to the dollar', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Low case: flat dollar gold with the peg held.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TM', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'Labour Code of Turkmenistan (No. 30-IV, as amended to 22 November 2025), Article 54: severance is two weeks'' or one month''s average pay on specific dismissal grounds (liquidation, staff cuts, call-up, refused transfer), not tied to years of service and not paid on retirement; no statutory gratuity exists (prg.kz/m/amp/document/31348675/4/540000).', 1);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TM', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No official figure for the cost of a major hospital stay was found; out-of-pocket payments are about 77% of health spending (World Bank).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TM', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'A voluntary state health insurance scheme exists, but no premium table by age was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TM', 1, 'inflation_cpi', 0.027, NULL, 'sourced', 'IMF World Economic Outlook, inflation (average consumer prices), Turkmenistan', 'https://www.imf.org/external/datamapper/api/v1/PCPIPCH/TKM', '2025-12-31', 'IMF estimate for 2025 (projection 5.6% for 2026); Turkmenistan does not publish a regular CPI. SESRIC, via Trading Economics, gives 8.0% for 2025, so the figure is uncertain. Latest year 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TM', 1, 'inflation_projection', 0.05, NULL, 'assumption', 'IMF WEO projections for Turkmenistan (4.1-4.6% in 2027-2030); 2021-2025 average about 7%', 'https://www.imf.org/external/datamapper/api/v1/PCPIPCH/TKM', '2026-10-31', 'There is no published inflation target; 5% sits between the IMF''s medium-term projections and the higher 2021-2025 record, allowing for poor price data.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TM', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'The insurance market is small and dominated by the state; no term life premium information from a public source was found, and whether pure term cover is sold was not confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TM', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No insurance market statistics or claim settlement ratio were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TM', 1, 'life_expectancy', 70.2, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=TM', '2024-12-31', '2024 (older than 2025): men 67.0, women 73.0. UN WPP gives 70.5 for 2026 (georank.org).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TM', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":17.7,"men":15.9,"women":19},{"age":65,"total":14.2,"men":12.6,"women":15.1},{"age":70,"total":11,"men":9.8,"women":11.6},{"age":80,"total":6.1,"men":5.5,"women":6.3}]}', 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/turkmenistan', '2026-07-01', 'Remaining years computed from georank''s expected age at death by current age (UN WPP estimate for 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TM', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":62,"womenAge":57,"over90Monthly":null,"meansTested":false}', 'sourced', 'Ministry of Labour and Social Protection of Population of Turkmenistan, frequently asked questions', 'https://mlsp.gov.tm/faq', '2026-10-31', 'Men from 62 and women from 57 who have no pension right (less than 5 years of compulsory pension insurance or no work record) are entitled to the state social allowance. The FAQ sets no income test, only the lack of a pension right.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TM', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'The state social allowance (döwlet durmuş kömek puly) for people of pension age without pension rights exists (Ministry of Labour FAQ), but its current monthly amount was not found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TM', 1, 'oop_health_share', 0.7739, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=TM', '2023-12-31', 'Latest available year is 2023 (older than 2025); one of the highest out-of-pocket shares in the world.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TM', 1, 'policy_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Central Bank of Turkmenistan website shows no current refinancing or policy rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TM', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":62,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'Ministry of Labour and Social Protection of Population of Turkmenistan, Pension Fund and FAQ', 'https://mlsp.gov.tm/faq', '2026-10-31', 'Compulsory state pension insurance with individual (named) pension accounts run by the Pension Fund of Turkmenistan, plus voluntary insurance of at least 2% of pay; pension from 62 (men) and 57 (women) with 5+ years of insurance. No automatic price indexation was found in the sources read (pensions are raised by decree); tax treatment not checked.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TM', 1, 'retirement_accumulation_return_base', 0.055, NULL, 'assumption', 'Fixed income base 5%; equity base 6.5%', 'https://www.imf.org/external/datamapper/api/v1/PCPIPCH/TKM', '2026-10-31', 'Base case: mostly manat deposits with some global shares, since local investment options are very limited.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TM', 1, 'retirement_accumulation_return_high', 0.085, NULL, 'assumption', 'Fixed income high 7%; equity high 10%', 'https://www.cbt.tm/kurs/kurs_today_en.html', '2026-10-31', 'High case for a growth-leaning balanced mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TM', 1, 'retirement_accumulation_return_low', 0.03, NULL, 'assumption', 'Fixed income low 3%; equity low 3%', 'https://www.imf.org/external/datamapper/api/v1/PCPIPCH/TKM', '2026-10-31', 'Low case for a balanced mix if both deposits and shares lag inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TM', 1, 'retirement_age_default', 62, NULL, 'sourced', 'Ministry of Labour and Social Protection of Population of Turkmenistan, frequently asked questions', 'https://mlsp.gov.tm/faq', '2026-10-31', 'Old-age pension from 62 for men and 57 for women with at least 5 years of compulsory pension insurance; mothers of three or more children can retire earlier (56 with 20 years of insurance for three children). No scheduled increase was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TM', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'The ministry FAQ gives only the general pension age (men 62, women 57); a separate retirement or service age limit for civil servants was not found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TM', 1, 'retirement_return_base', 0.045, NULL, 'assumption', 'IMF WEO inflation projections; fixed income base 5%', 'https://www.imf.org/external/datamapper/api/v1/PCPIPCH/TKM', '2026-10-31', 'Base case slightly below the assumed safe deposit return, since no deposit or bill rate is published to check against.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TM', 1, 'retirement_return_high', 0.065, NULL, 'assumption', 'Fixed income high 7%', 'https://www.imf.org/external/datamapper/api/v1/PCPIPCH/TKM', '2026-10-31', 'High case: deposits keep earning a little above inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TM', 1, 'retirement_return_low', 0.03, NULL, 'assumption', 'IMF WEO inflation projections for Turkmenistan', 'https://www.imf.org/external/datamapper/api/v1/PCPIPCH/TKM', '2026-10-31', 'Low case: a retiree''s manat deposits earn below inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TM', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate or retail savings bond for individuals was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TM', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No official or industry-wide deposit rate statistics were found; the central bank only lists the banks that take deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TM', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":13.31},{"year":2040,"value":7.58},{"year":2065,"value":4.12}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/turkmenistan/2040/', '2025-12-31', '100 / old-age dependency ratio: 7.52 (2025, World Bank), 13.2 (2040) and 24.3 (2065, populationpyramid.net/turkmenistan/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TM', 1, 'tax_bank_interest', 0, NULL, 'sourced', 'Tax Code of Turkmenistan, Article 187(1)(t) (income not included in the tax base), as amended to 12 April 2025', 'https://prg.kz/m/amp/document/30415652/11/1870000', '2025-04-12', 'Interest on bank deposits and deposit certificates of individuals is excluded from personal income tax. Read from a legal database copy of the Tax Code (amendments to April 2025).', 0);
