INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TM', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No regular treasury bill market or published yields were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TM', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published government bond yields were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TM', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published government bond yields were found.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('TN', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"TN","iso3":"TUN","nameEn":"Tunisia","nameNative":"تونس","region":"middle_east_north_africa","languages":["ar","aeb","fr"],"currency":{"code":"TND","symbol":"DT","decimals":3,"compact":"intl","usdRate":{"value":2.9974,"status":"sourced","sourceName":"World Bank WDI, official exchange rate (PA.NUS.FCRF), Tunisia, 2025 average","sourceUrl":"https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=TN","asOf":"2025-12-31","note":"3.00 dinars per US dollar, 2025 average. The Banque Centrale de Tunisie rate page returned server errors; Trading Economics showed 2.99 on 3 November 2026, so the 2025 average is still current."}},"instruments":{"savings_account":{"available":true,"localName":"حساب ادخار","localNameEn":"Savings account (compte spécial d''épargne)","note":"Pays at least the central bank''s savings remuneration rate (TRE)."},"fdr_3m":{"available":true,"localName":"إيداع لأجل (3 أشهر)","localNameEn":"Term deposit (3 months)"},"fdr_1y":{"available":true,"localName":"إيداع لأجل (سنة)","localNameEn":"Term deposit (1 year)"},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No standard monthly recurring deposit was confirmed; housing savings contracts (épargne logement) with monthly payments are the closest product, and their interest is tax-exempt.","sourceUrl":"https://taxsummaries.pwc.com/tunisia/individual/deductions"},"sanchayapatra_5y":{"available":true,"localName":"القرض الرقاعي الوطني","localNameEn":"National bond loan (emprunt obligataire national)","note":"The state has issued national bond loans open to individuals in several tranches, with 5 to 10 year categories; availability depends on a current issue."},"tbill_91d":{"available":true,"localName":"رقاع الخزينة قصيرة المدى","localNameEn":"Short-term treasury bills (BTCT)","note":"Sold at central bank auctions; individuals usually buy through banks or brokers."},"tbond_5y":{"available":true,"localName":"رقاع الخزينة القابلة للتنظير","localNameEn":"Treasury bonds (BTA)"},"tbond_10y":{"available":true,"localName":"رقاع الخزينة القابلة للتنظير (10 سنوات)","localNameEn":"Treasury bonds (BTA, 10 years)"},"equity_fund":{"available":true,"localName":"مؤسسات التوظيف الجماعي في الأوراق المالية","localNameEn":"Collective investment funds (OPCVM: SICAV and FCP)","note":"Supervised by the Conseil du Marché Financier."},"gold":{"available":true,"localName":"الذهب","localNameEn":"Gold","note":"Gold is mostly bought as jewellery; the trade in precious metals is regulated."}},"institutions":{"centralBank":{"name":"Banque Centrale de Tunisie","url":"https://www.bct.gov.tn/"},"insuranceRegulator":{"name":"Comité Général des Assurances (CGA)","url":"https://www.cga.gov.tn/"},"insuranceComplaints":{"name":"Comité Général des Assurances, petitions and complaints","url":"https://www.cga.gov.tn/index.php?id=83&L=1"},"pensionScheme":{"name":"Caisse Nationale de Sécurité Sociale (CNSS), private sector pensions","url":"https://www.cnss.tn/","note":"Public-sector employees are covered by the CNRPS (https://www.cnrps.nat.tn/)."},"oldAgeAllowance":null,"publicHealthCover":{"name":"Caisse Nationale d''Assurance Maladie (CNAM)","url":"https://www.cnam.nat.tn/"},"depositInsurance":{"name":"Fonds de Garantie des Dépôts Bancaires (FGDB), set up under the banking law of 2016","url":"https://www.bct.gov.tn/","note":"The fund''s own site could not be reached; linked to the central bank."},"statistics":{"name":"Institut National de la Statistique (INS)","url":"https://www.ins.tn/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TN', 1, 'bank_deposit_avg_rate', 0.0863, NULL, 'sourced', 'World Bank deposit interest rate, Tunisia, via Trading Economics', 'https://tradingeconomics.com/tunisia/deposit-interest-rate', '2024-12-31', '8.63%, latest World Bank value shown by Trading Economics (series ends 2024); older than 2025 and from before the key rate was cut to 7%, so today''s average is likely lower.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TN', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'Lending rates are capped by the central bank''s usury rate (taux effectif global maximum), but the current figure could not be read from the Banque Centrale de Tunisie.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TN', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'Tunisia has a deposit guarantee fund (Fonds de Garantie des Dépôts Bancaires), but its cover per depositor could not be read: the fund''s site did not resolve and web search was unavailable.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TN', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No standard monthly recurring deposit product or published rate was found; housing savings contracts are the closest product.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TN', 1, 'equity_return_base', 0.095, NULL, 'assumption', 'TUNINDEX 18,623 on 30 October 2026, up 48% in a year (Trading Economics); after-tax safe rate about 6%', 'https://tradingeconomics.com/tunisia/stock-market', '2026-10-31', 'Base case: 4 points over the roughly 5.5% after-tax deposit rate, the cap, as the index has a strong 10-year record but a small, illiquid market.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TN', 1, 'equity_return_high', 0.14, NULL, 'assumption', 'TUNINDEX record (Trading Economics)', 'https://tradingeconomics.com/tunisia/stock-market', '2026-10-31', 'High case: close to the index''s price growth since 2016 (about 5,500 to 18,600 points).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TN', 1, 'equity_return_low', 0.06, NULL, 'assumption', 'TUNINDEX 18,623 on 30 October 2026, 14% below its July 2026 peak (Trading Economics)', 'https://tradingeconomics.com/tunisia/stock-market', '2026-10-31', 'Low case: equities earn about the after-tax deposit rate after the 2025-2026 rally cools.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TN', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published industry-wide 1-year term deposit rate could be read; the Banque Centrale de Tunisie statistics pages returned server errors.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TN', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published industry-wide 3-month term deposit rate could be read; the Banque Centrale de Tunisie statistics pages returned server errors.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TN', 1, 'fixed_income_return_base', 0.055, NULL, 'assumption', 'Policy rate 7% (July 2026); 20% withholding on interest (PwC)', 'https://tradingeconomics.com/tunisia/interest-rate', '2026-10-31', 'Base case: term deposits near the 7% policy rate, less 20% withholding, rounded down.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TN', 1, 'fixed_income_return_high', 0.07, NULL, 'assumption', 'Policy rate 7%; 20% withholding on interest (PwC)', 'https://tradingeconomics.com/tunisia/interest-rate', '2026-10-31', 'High case: longer treasury bonds or national bond loans at about 9% before tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TN', 1, 'fixed_income_return_low', 0.045, NULL, 'assumption', 'Policy rate 7% (July 2026); 20% withholding on interest (PwC)', 'https://tradingeconomics.com/tunisia/interest-rate', '2026-10-31', 'Low case: deposit rates fall with further policy cuts and savings balances earn less than term deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TN', 1, 'goal_inflation_education', 0.065, NULL, 'assumption', 'INS education price index 5.5% year on year (September 2026)', 'https://www.ins.tn/statistiques/90', '2026-10-31', 'Private school and university fees have tracked or exceeded general inflation, so education goals are planned half a point above it.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TN', 1, 'goal_inflation_health', 0.06, NULL, 'assumption', 'INS health price index 3.3% year on year (September 2026); inflation assumption 6%', 'https://www.ins.tn/statistiques/90', '2026-10-31', 'Regulated public prices keep measured health inflation low, but private clinic costs follow general prices, so health goals use the general assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TN', 1, 'gold_return_base', 0.06, NULL, 'assumption', 'USD/TND 2.99 (October 2026); inflation assumption 6%; long-run dollar gold trend about 4%', 'https://tradingeconomics.com/tunisia/currency', '2026-10-31', 'Base case: about 4% dollar gold trend plus about 2% a year of dinar depreciation, a little below the 2016-2026 pace.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TN', 1, 'gold_return_high', 0.12, NULL, 'assumption', 'USD/TND history (World Bank PA.NUS.FCRF); dollar gold trend', 'https://tradingeconomics.com/tunisia/currency', '2026-10-31', 'High case: strong dollar gold and faster dinar depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TN', 1, 'gold_return_low', 0.02, NULL, 'assumption', 'USD/TND 2.99 on 30 October 2026 (Trading Economics)', 'https://tradingeconomics.com/tunisia/currency', '2026-10-31', 'Low case: flat dollar gold with a stable dinar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TN', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No statutory end-of-service gratuity for private employees was confirmed; the Labour Code provides severance on dismissal, and retirement bonuses depend on sector collective agreements, which could not be checked.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TN', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a major private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TN', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premiums by age were found from the regulator or another public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TN', 1, 'inflation_cpi', 0.056, NULL, 'sourced', 'Institut National de la Statistique, consumer price index press release, September 2026', 'https://www.ins.tn/statistiques/90', '2026-09-30', '5.6% year on year in September 2026 (INS release of 5 October 2026); health 3.3%, education 5.5%. World Bank 2025 average 5.2%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TN', 1, 'inflation_projection', 0.06, NULL, 'assumption', 'INS CPI 5.6% (September 2026); World Bank CPI inflation 5.2% (2025); about 7% average 2021 to 2025', 'https://www.ins.tn/statistiques/90', '2026-10-31', 'The central bank has no numeric target and inflation averaged about 7% over five years before easing to 5 to 6%, so 6% is a rounded middle value.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TN', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life (assurance temporaire décès) is sold, often with loans, but no published premium rates per TND 1,000 by age were found from the regulator or another public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TN', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No industry-wide life claim settlement ratio was found in the Comité Général des Assurances statistics or annual report summaries.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TN', 1, 'life_expectancy', 76.711, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN), Tunisia', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=TN', '2024-12-31', '76.7 years in 2024 (men 74.1, women 79.3).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TN', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":20.8,"men":19.1,"women":22.4},{"age":65,"total":16.7,"men":15.3,"women":18.1},{"age":70,"total":13,"men":11.9,"women":14.1},{"age":80,"total":7.2,"men":6.6,"women":7.7}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/tunisia/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026; totals are the mean of men and women.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TN', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'No age-based non-contributory pension was confirmed; the means-tested Amen social cash transfer targets poor households, not an age group.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TN', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'No age-based social pension was confirmed; poor households, including elderly people, receive the means-tested family cash transfer of the Amen social programme, whose current amount could not be read (the Ministry of Social Affairs site failed certificate checks). Not marked absent because no source confirming the absence of a social pension could be read..', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TN', 1, 'oop_health_share', 0.379, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), Tunisia', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=TN', '2023-12-31', '37.9% in 2023 (WHO Global Health Expenditure Database via the World Bank); older than 2025, the latest available.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TN', 1, 'policy_rate', 0.07, NULL, 'sourced', 'Banque Centrale de Tunisie key rate, board meeting of 29 July 2026, via Trading Economics', 'https://tradingeconomics.com/tunisia/interest-rate', '2026-07-29', 'Held at 7.00% on 29 July 2026; secondary source because the Banque Centrale de Tunisie site returned server errors.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TN', 1, 'public_pension_scheme', NULL, NULL, 'missing', '', '', '2026-10-31', 'The CNSS (private sector) and CNRPS (public sector) run compulsory pensions (employee CNSS contribution 9.68% from 2025 per PwC), but the pension age schedule and indexation rule could not be read from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TN', 1, 'retirement_accumulation_return_base', 0.075, NULL, 'assumption', 'Fixed income base 5.5%; equity base 9.5%; gold base 6%', 'https://tradingeconomics.com/tunisia/stock-market', '2026-10-31', 'Base case: a balanced mix of deposits, Tunisian equities and gold.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TN', 1, 'retirement_accumulation_return_high', 0.1, NULL, 'assumption', 'Equity high 14%; gold high 12%', 'https://tradingeconomics.com/tunisia/stock-market', '2026-10-31', 'High case: a growth-leaning mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TN', 1, 'retirement_accumulation_return_low', 0.05, NULL, 'assumption', 'Fixed income low 4.5%; equity low 6%', 'https://tradingeconomics.com/tunisia/stock-market', '2026-10-31', 'Low case: a balanced mix earning about the after-tax deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TN', 1, 'retirement_age_default', NULL, NULL, 'missing', '', '', '2026-10-31', 'The pension age for private-sector workers insured with the CNSS (60, with reforms raising ages since 2019) could not be confirmed from an official source; the CNSS site failed certificate checks and the US SSA country page refused requests.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TN', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'Not confirmed: the only source found was an unreferenced Wikipedia table row (''62–65'', sector not stated); the CNRPS site refused connections and the US SSA and ISSA country profiles returned 403.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TN', 1, 'retirement_return_base', 0.055, NULL, 'assumption', 'Policy rate 7%; 20% withholding on interest (PwC)', 'https://taxsummaries.pwc.com/tunisia/corporate/withholding-taxes', '2026-10-31', 'Base case: term deposits near 7% less 20% withholding, so not above the after-tax safe rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TN', 1, 'retirement_return_high', 0.065, NULL, 'assumption', 'Policy rate 7%; 20% withholding on interest (PwC)', 'https://taxsummaries.pwc.com/tunisia/corporate/withholding-taxes', '2026-10-31', 'High case: a ladder of treasury bonds and national bond loans at about 8 to 9% before tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TN', 1, 'retirement_return_low', 0.045, NULL, 'assumption', 'Policy rate 7%; 20% withholding on interest (PwC)', 'https://taxsummaries.pwc.com/tunisia/corporate/withholding-taxes', '2026-10-31', 'Low case: deposit rates fall with further policy cuts.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TN', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The state periodically issues national bond loans open to individuals, but the rate of a current issue could not be read from the Ministry of Finance or the central bank.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TN', 1, 'savings_account_rate', 0.06, NULL, 'sourced', 'Banque Centrale de Tunisie board decision of 30 December 2025 (minimum savings remuneration rate, TRE), via Trading Economics', 'https://tradingeconomics.com/tunisia/interest-rate', '2025-12-30', 'The central bank lowered the minimum rate banks must pay on savings accounts (TRE) to 6%, in force with the 7% key rate from January 2026; no later change was reported up to the 29 July 2026 meeting. Secondary source because the BCT site returned server errors.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TN', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":6.7},{"year":2040,"value":4.2},{"year":2065,"value":2.3}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/tunisia/2040/', '2025-12-31', '100 / old-age dependency ratio: 14.9 (2025, World Bank), 23.9 (2040) and 42.6 (2065, populationpyramid.net/tunisia/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TN', 1, 'tax_bank_interest', 0.2, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Tunisia, withholding taxes (last reviewed 29 June 2026)', 'https://taxsummaries.pwc.com/tunisia/corporate/withholding-taxes', '2026-06-29', '20% withholding on interest (PwC corporate withholding page); interest on deposits in foreign currency or convertible dinars is exempt. PwC''s individual page says interest otherwise forms part of total taxable income, so the final charge can differ; interest on housing savings contracts is exempt.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TN', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'The tax on national bond loan interest for individuals could not be confirmed; ordinary interest bears 20% withholding (PwC Worldwide Tax Summaries).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TN', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No current short-term treasury bill (BTCT) auction yield could be read; the Banque Centrale de Tunisie site returned server errors and Trading Economics shows no figure.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TN', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No current 10-year treasury bond (BTA) yield could be read; Trading Economics shows no Tunisia bond yield.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TN', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No current 5-year treasury bond (BTA) yield could be read from an official or secondary source.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('TO', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"TO","iso3":"TON","nameEn":"Tonga","nameNative":"Tonga","region":"east_asia_pacific","languages":["to","en"],"currency":{"code":"TOP","symbol":"T$","decimals":2,"compact":"intl","usdRate":{"value":2.3952,"status":"sourced","sourceName":"National Reserve Bank of Tonga daily exchange rates (USD/TOP mid 0.4175)","sourceUrl":"https://www.reservebank.to/index.php/financial-system/financial-markets/exchange-rates","asOf":"2026-10-30","note":"TOP 1 = USD 0.4175 on 30 October 2026, so TOP 2.40 per US dollar; the same page showed 0.4170 on 1 November 2026 and NRBT Monetary Policy Data gives 0.4185 for July 2026."}},"instruments":{"savings_account":{"available":true,"localName":null,"localNameEn":"Savings account","sourceUrl":"https://www.reservebank.to/data/docs/fsystems/banks_feeschargesinterestrates_comparisons_feb24.pdf"},"fdr_3m":{"available":true,"localName":null,"localNameEn":"3-month term deposit","sourceUrl":"https://www.reservebank.to/data/docs/fsystems/banks_feeschargesinterestrates_comparisons_feb24.pdf"},"fdr_1y":{"available":true,"localName":null,"localNameEn":"12-month term deposit","sourceUrl":"https://www.reservebank.to/data/docs/fsystems/banks_feeschargesinterestrates_comparisons_feb24.pdf"},"dps":{"available":false,"localName":null,"note":"No monthly recurring deposit product listed in the NRBT bank comparison."},"sanchayapatra_5y":{"available":false,"localName":null,"note":"No separate retail savings bond; government bonds are listed by NRBT (see tbond_5y).","sourceUrl":"https://www.reservebank.to/index.php/financial-system/financial-markets/government-bonds"},"tbill_91d":{"available":false,"localName":null,"note":"No treasury bills on issue; NRBT Notes are for banks."},"tbond_5y":{"available":true,"localName":null,"localNameEn":"Government of Tonga bond","note":"Issued through the NRBT in 2- to 7-year series; 5-year coupons 2.5-3.0%.","sourceUrl":"https://www.reservebank.to/index.php/financial-system/financial-markets/government-bonds"},"tbond_10y":{"available":false,"localName":null,"note":"No 10-year series on issue; longest is 7 years.","sourceUrl":"https://www.reservebank.to/index.php/financial-system/financial-markets/government-bonds"},"equity_fund":{"available":false,"localName":null,"note":"No local stock exchange or locally offered mutual funds found."},"gold":{"available":true,"localName":null,"localNameEn":"Gold","note":"No legal restriction on buying gold was found; mainly sold as jewellery."}},"institutions":{"centralBank":{"name":"National Reserve Bank of Tonga","url":"https://www.reservebank.to/"},"insuranceRegulator":null,"insuranceComplaints":null,"pensionScheme":{"name":"National Retirement Benefits Fund (NRBF)","url":"https://www.nrbf.to/"},"oldAgeAllowance":{"name":"Social Welfare Scheme (Government of Tonga, administered by NRBF)","url":"https://www.nrbf.to/services.php"},"publicHealthCover":{"name":"Ministry of Health (public hospitals)","url":"https://www.health.gov.to/"},"depositInsurance":null,"statistics":{"name":"Tonga Statistics Department","url":"https://tongastats.gov.to/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
