INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TO', 1, 'equity_return_base', 0.065, NULL, 'assumption', 'No local stock exchange; global equity index in pa''anga terms; NRBT Monetary Policy Data July 2026: 12-month term deposit 3.32%; 5-year government bond coupon 3.00%', 'https://www.reservebank.to/data/docs/fmarkets/mpd/mpd_jul2026.pdf', '2026-10-31', 'There is no local stock market, so the base is a global index in pa''anga, capped at the after-tax 12-month deposit (about 3%) plus under 4 points.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TO', 1, 'equity_return_high', 0.09, NULL, 'assumption', 'No local stock exchange; global equity index in pa''anga terms; NRBT Monetary Policy Data July 2026: 12-month term deposit 3.32%; 5-year government bond coupon 3.00%', 'https://www.reservebank.to/data/docs/fmarkets/mpd/mpd_jul2026.pdf', '2026-10-31', 'High case near long-run world equity returns plus mild pa''anga weakening.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TO', 1, 'equity_return_low', 0.03, NULL, 'assumption', 'No local stock exchange; global equity index in pa''anga terms; NRBT Monetary Policy Data July 2026: 12-month term deposit 3.32%; 5-year government bond coupon 3.00%', 'https://www.reservebank.to/data/docs/fmarkets/mpd/mpd_jul2026.pdf', '2026-10-31', 'Low case for a global index fund in pa''anga after a weak decade for world shares.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TO', 1, 'fdr_1y_rate', 0.0332, NULL, 'sourced', 'National Reserve Bank of Tonga, Monetary Policy Data July 2026 (12-month term deposit rate)', 'https://www.reservebank.to/data/docs/fmarkets/mpd/mpd_jul2026.pdf', '2026-07-31', 'Weighted average 12-month term deposit rate 3.32%; posted 1-year rates range 0.50% to 4.00% across banks (May 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TO', 1, 'fdr_3m_rate', 0.01, NULL, 'sourced', 'National Reserve Bank of Tonga, comparison of banks'' interest rates (as of May 2026)', 'https://www.reservebank.to/data/docs/fsystems/banks_feeschargesinterestrates_comparisons_feb24.pdf', '2026-05-31', 'Posted 3-month rates for deposits under TOP 100,000 at the four banks: 0.35%, 0.75%, 1.25% and 3.50%; median 1.0%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TO', 1, 'fixed_income_return_base', 0.028, NULL, 'assumption', 'NRBT Monetary Policy Data July 2026: 12-month term deposit 3.32%; 5-year government bond coupon 3.00%', 'https://www.reservebank.to/data/docs/fmarkets/mpd/mpd_jul2026.pdf', '2026-10-31', 'Base case: 12-month deposits (3.32%) after 10% withholding and 5-year government bonds at 2.5-3.0%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TO', 1, 'fixed_income_return_high', 0.033, NULL, 'assumption', 'NRBT Monetary Policy Data July 2026: 12-month term deposit 3.32%; 5-year government bond coupon 3.00%', 'https://www.reservebank.to/data/docs/fmarkets/mpd/mpd_jul2026.pdf', '2026-10-31', 'High case: the better posted 1-year deposit rates and 6-year government bonds at 3.5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TO', 1, 'fixed_income_return_low', 0.02, NULL, 'assumption', 'NRBT savings deposit rate 2.49% less 10% withholding', 'https://www.reservebank.to/data/docs/fmarkets/mpd/mpd_jul2026.pdf', '2026-10-31', 'Low case: savings deposits at about 2.5% before a 10% withholding tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TO', 1, 'goal_inflation_education', 0.055, NULL, 'assumption', 'NRBT 5% inflation reference rate; Tonga CPI September 2026 (education group +4.0% y/y)', 'https://tongastats.gov.to/download/498/2026/13851/cpi-report-september-2026.pdf', '2026-10-31', 'Education prices rose 4.0% year on year in the September 2026 CPI; we plan with the 5% headline projection plus half a point.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TO', 1, 'goal_inflation_health', 0.06, NULL, 'assumption', 'NRBT 5% inflation reference rate; Tonga CPI September 2026 (health group 0.0% y/y)', 'https://tongastats.gov.to/download/498/2026/13851/cpi-report-september-2026.pdf', '2026-10-31', 'The September 2026 CPI health group was flat year on year (weight 0.2%) but that index is too small to plan with, so we use the 5% headline projection plus one point.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TO', 1, 'gold_return_base', 0.05, NULL, 'assumption', 'NRBT exchange rate (USD/TOP about 0.42, stable over 2025-2026 under a basket peg)', 'https://www.reservebank.to/index.php/financial-system/financial-markets/exchange-rates', '2026-10-31', 'Long-run dollar gold trend of about 4-5% plus slight expected pa''anga depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TO', 1, 'gold_return_high', 0.08, NULL, 'assumption', 'NRBT exchange rate (USD/TOP about 0.42, stable over 2025-2026 under a basket peg)', 'https://www.reservebank.to/index.php/financial-system/financial-markets/exchange-rates', '2026-10-31', 'High case with strong dollar gold and some pa''anga weakening.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TO', 1, 'gold_return_low', 0.02, NULL, 'assumption', 'NRBT exchange rate (USD/TOP about 0.42, stable over 2025-2026 under a basket peg)', 'https://www.reservebank.to/index.php/financial-system/financial-markets/exchange-rates', '2026-10-31', 'Low case for gold in pa''anga: weak dollar gold price and a stable basket-pegged currency.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TO', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No statutory gratuity or end-of-service payment for private employees was found; retirement savings run through NRBF.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TO', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical private hospital bill for Tonga was found; most care is at public hospitals.', 0);
