INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TO', 1, 'inflation_cpi', 0.121, NULL, 'sourced', 'Tonga Statistics Department, Statistical Bulletin: Consumer Price Index September 2026', 'https://tongastats.gov.to/download/498/2026/13851/cpi-report-september-2026.pdf', '2026-09-30', 'All-items CPI 146.3 in September 2026 vs 130.6 a year earlier: 12.1% annual inflation (12.0% in August, 9.3% in July), led by food, transport, housing and restaurants.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TO', 1, 'inflation_projection', 0.05, NULL, 'assumption', 'NRBT 5% inflation reference rate (press release 27 August 2026)', 'https://www.reservebank.to/index.php/news/public-notice-tonga-maintains-neutral-stance-while-strengthening-monetary-policy-transmission', '2026-10-31', 'The NRBT steers by a 5% inflation reference rate; annual inflation ran 2-5.5% in 2025 before a fuel and food spike to 12.1% in September 2026, so we plan with the 5% reference.', 0);
