INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TO', 1, 'life_expectancy', 73.07, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=TO', '2024-12-31', 'UN WPP 2024 (via populationpyramid.net) gives 73.4 for 2026 (men 69.8, women 76.8).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TO', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":19.1,"men":16.9,"women":21.3},{"age":65,"total":15.6,"men":13.7,"women":17.4},{"age":70,"total":12.3,"men":10.8,"women":13.7},{"age":80,"total":7,"men":6.2,"women":7.7}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/tonga/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026 (rows 60-64, 65-69, 70-74, 80-84); totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TO', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":67,"womenAge":67,"over90Monthly":null,"meansTested":false}', 'sourced', 'National Retirement Benefits Fund (administers the Government Social Welfare Scheme), Our Services', 'https://www.nrbf.to/services.php', '2026-10-31', 'From 1 July 2024 every Tongan citizen aged 67+ may register regardless of work income or other pensions (not means-tested); higher rate of TOP 110 from age 80, no separate over-90 rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TO', 1, 'old_age_allowance_monthly', 90, NULL, 'sourced', 'National Retirement Benefits Fund (administers the Government Social Welfare Scheme), Our Services', 'https://www.nrbf.to/services.php', '2026-10-31', 'Social Welfare Scheme pays TOP 90 a month at ages 67-79 and TOP 110 from 80, to Tongan citizens living in Tonga (registered after 3 months'' residence); paid monthly until death. Eligibility rule effective 1 July 2024.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TO', 1, 'oop_health_share', 0.0586, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=TO', '2023-12-31', NULL, 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TO', 1, 'policy_rate', 0.02, NULL, 'sourced', 'National Reserve Bank of Tonga, monetary policy press release', 'https://www.reservebank.to/index.php/news/public-notice-tonga-maintains-neutral-stance-while-strengthening-monetary-policy-transmission', '2026-08-27', 'Policy rate held at 2% within a 0-4% interest rate corridor; statutory reserve deposit ratio 15%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TO', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":18,"entryAgeMax":70,"pensionFromAge":60,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'National Retirement Benefits Fund (NRBF), Our Services', 'https://www.nrbf.to/services.php', '2026-10-31', 'Defined-contribution fund for private-sector employees: 5% employee plus at least 7.5% employer; normal retirement benefit from 60 once employment ends; voluntary contributors allowed. Membership ages 18-70 per the NRBF information guide on nrbf.to.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TO', 1, 'retirement_accumulation_return_base', 0.045, NULL, 'assumption', 'Mix of local deposits/bonds (about 3%) and global equity', 'https://www.reservebank.to/data/docs/fmarkets/mpd/mpd_jul2026.pdf', '2026-10-31', 'Base case: half local fixed income at about 2.8% and half global equity at 6.5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TO', 1, 'retirement_accumulation_return_high', 0.065, NULL, 'assumption', 'Mix of local deposits/bonds (about 3%) and global equity', 'https://www.reservebank.to/data/docs/fmarkets/mpd/mpd_jul2026.pdf', '2026-10-31', 'High case with a larger, well-performing global equity share.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TO', 1, 'retirement_accumulation_return_low', 0.03, NULL, 'assumption', 'Mix of local deposits/bonds (about 3%) and global equity', 'https://www.reservebank.to/data/docs/fmarkets/mpd/mpd_jul2026.pdf', '2026-10-31', 'Low case for a balanced mix mostly in local deposits and bonds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TO', 1, 'retirement_age_default', 60, NULL, 'sourced', 'National Retirement Benefits Fund (NRBF), Our Services', 'https://www.nrbf.to/services.php', '2026-10-31', 'NRBF normal retirement: member must be 60 and no longer employed (benefit available between 60 and 70); no separate statutory private-sector retirement age was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TO', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'No official source for the civil service retirement age was readable; government staff are covered by a separate Retirement Fund.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TO', 1, 'retirement_return_base', 0.028, NULL, 'assumption', 'NRBT Monetary Policy Data July 2026: 12-month term deposit 3.32%; 5-year government bond coupon 3.00%', 'https://www.reservebank.to/data/docs/fmarkets/mpd/mpd_jul2026.pdf', '2026-10-31', 'Base case kept below the after-tax 12-month deposit rate (3.32% less 10% = 2.99%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TO', 1, 'retirement_return_high', 0.032, NULL, 'assumption', 'NRBT Monetary Policy Data July 2026: 12-month term deposit 3.32%; 5-year government bond coupon 3.00%', 'https://www.reservebank.to/data/docs/fmarkets/mpd/mpd_jul2026.pdf', '2026-10-31', 'High case: laddered 5-6 year government bonds at 3.0-3.5% and better bank rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TO', 1, 'retirement_return_low', 0.02, NULL, 'assumption', 'NRBT savings deposit rate 2.49% less 10% withholding', 'https://www.reservebank.to/data/docs/fmarkets/mpd/mpd_jul2026.pdf', '2026-10-31', 'Low case: savings deposits after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TO', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched NRBT pages: government bonds are listed by series, but no separate retail savings bond or certificate for individuals was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TO', 1, 'savings_account_rate', 0.0249, NULL, 'sourced', 'National Reserve Bank of Tonga, Monetary Policy Data July 2026 (savings deposit rate)', 'https://www.reservebank.to/data/docs/fmarkets/mpd/mpd_jul2026.pdf', '2026-07-31', 'Weighted average savings deposit rate 2.49%; posted rates vary from 0.2% to 5% by bank and balance (NRBT bank comparison, May 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TO', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":8.5},{"year":2040,"value":6.2},{"year":2065,"value":7.1}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/tonga/2040/', '2025-12-31', '100 / old-age dependency ratio: 11.76 (2025, World Bank) gives 8.5; populationpyramid.net (UN WPP 2024) gives 16.1 for 2040 (6.2) and 14.1 for 2065 (7.1, populationpyramid.net/tonga/2065/).', 0);
