INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TO', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'NRBT government bonds page lists no 10-year series; the longest tenor on issue is 7 years (2.50%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TO', 1, 'tbond_5y_rate', 0.03, NULL, 'sourced', 'National Reserve Bank of Tonga, government bonds on issue (Series No.6 2026/2031)', 'https://www.reservebank.to/index.php/financial-system/financial-markets/government-bonds', '2026-09-18', 'Most 5-year government bonds issued in 2025-2026 carry 2.50-3.00% coupons; the latest 5-year series (18 September 2026) pays 3.00%.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('TR', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"TR","iso3":"TUR","nameEn":"Turkey","nameNative":"Türkiye","region":"europe_central_asia","languages":["tr","en","ku"],"currency":{"code":"TRY","symbol":"₺","decimals":2,"compact":"intl","usdRate":{"value":49.82,"status":"sourced","sourceName":"Central Bank of the Republic of Türkiye (CBRT), indicative exchange rates of 30 October 2026","sourceUrl":"https://www.tcmb.gov.tr/kurlar/202610/30102026.xml","asOf":"2026-10-30","note":"Mid of the CBRT forex buying (49.7747) and selling (49.8644) rates for the US dollar announced on 30 October 2026; the lira lost about 19% against the dollar over the past year (Trading Economics). World Bank 2025 average 39.45."}},"instruments":{"savings_account":{"available":true,"localName":"Vadesiz mevduat hesabı","localNameEn":"Demand deposit account","note":"Demand accounts pay little or no interest and their interest is taxed at 17.5%; most savers use short term deposits."},"fdr_3m":{"available":true,"localName":"Vadeli mevduat (3 ay)","localNameEn":"Term deposit (3 months)","note":"TL deposits are insured by TMSF up to TRY 1.2 million per person per bank in 2026."},"fdr_1y":{"available":true,"localName":"Vadeli mevduat (1 yıl)","localNameEn":"Term deposit (1 year)"},"dps":{"available":true,"localName":"Birikimli vadeli hesap","localNameEn":"Accumulating savings deposit","note":"Some banks offer accumulating deposit accounts with regular top-ups; there is no standard national scheme."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate for individuals; Treasury bonds and lease certificates can be bought through banks."},"tbill_91d":{"available":true,"localName":"Hazine bonosu","localNameEn":"Treasury bill","note":"Treasury bills (up to 1 year) can be bought through banks, but 3-month bills are rarely issued."},"tbond_5y":{"available":true,"localName":"Devlet tahvili","localNameEn":"Government bond"},"tbond_10y":{"available":true,"localName":"Devlet tahvili (10 yıl)","localNameEn":"Government bond (10 years)","sourceUrl":"https://tradingeconomics.com/turkey/government-bond-yield"},"equity_fund":{"available":true,"localName":"Yatırım fonu / Borsa yatırım fonu","localNameEn":"Mutual fund / exchange-traded fund","note":"Equity and index funds are widely sold to retail investors."},"gold":{"available":true,"localName":"Gram altın / Cumhuriyet altını","localNameEn":"Gold bars and Republic gold coins","note":"Physical gold is legal and widely bought; banks also offer gold deposit accounts."}},"institutions":{"centralBank":{"name":"Central Bank of the Republic of Türkiye (TCMB)","url":"https://www.tcmb.gov.tr/"},"insuranceRegulator":{"name":"Insurance and Private Pension Regulation and Supervision Agency (SEDDK)","url":"https://www.seddk.gov.tr/"},"insuranceComplaints":{"name":"Insurance Arbitration Commission (Sigorta Tahkim Komisyonu)","url":"https://www.sigortatahkim.org.tr/"},"pensionScheme":{"name":"Social Security Institution (SGK)","url":"https://www.sgk.gov.tr/"},"oldAgeAllowance":{"name":"Ministry of Family and Social Services (needs-based old-age pension, 65 yaş aylığı)","url":"https://www.aile.gov.tr/"},"publicHealthCover":{"name":"General Health Insurance (GSS), Social Security Institution","url":"https://www.sgk.gov.tr/"},"depositInsurance":{"name":"Savings Deposit Insurance Fund (TMSF)","url":"https://www.tmsf.org.tr/tr/Tmsf/Finansman/mevduat.sss.guncel"},"statistics":{"name":"Turkish Statistical Institute (TurkStat)","url":"https://www.tuik.gov.tr/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TR', 1, 'bank_deposit_avg_rate', 0.4288, NULL, 'sourced', 'Endeks24, citing CBRT weekly weighted average TL deposit rate (week of 16 October 2026)', 'https://www.endeks24.com/tl-mevduat-faizi-yuzde-4288e-indi-dusus-12-haftaya-uzandi', '2026-10-16', 'Weighted average rate on all new TL deposits, 42.88% in the week of 16 October 2026, down 0.06 points on the week and falling for 12 weeks; secondary source because CBRT EVDS could not be read. World Bank 2025 annual average (FR.INR.DPST) 57.6%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TR', 1, 'credit_card_rate_cap', 0.45, NULL, 'sourced', 'CBRT, maximum interest rates for credit card transactions', 'https://www.tcmb.gov.tr/wps/wcm/connect/TR/TCMB+TR/Main+Menu/Istatistikler/Bankacilik+Verileri/Kredi_Karti_Islemlerinde_Uygulanacak_Azami_Faiz_Oranlari', '2026-10-01', 'Legal maximum monthly contractual rate on TL card balances of TRY 30,000-180,000 is 3.75% (45% a year, simple); 3.25% below TRY 30,000 and 4.25% above TRY 180,000 or for cash advances; unchanged since January 2026 and announced for November 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TR', 1, 'deposit_insurance_limit', 1200000, NULL, 'sourced', 'Savings Deposit Insurance Fund (TMSF), deposit insurance FAQ', 'https://www.tmsf.org.tr/tr/Tmsf/Finansman/mevduat.sss.guncel', '2026-01-01', 'TRY 1,200,000 per person per credit institution in 2026 (950,000 in 2025), covering TL, foreign-currency and precious-metal deposits and participation funds; raised each year by the revaluation rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TR', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Some banks sell accumulating (birikimli) deposit accounts, but no official or industry-wide rate for a monthly recurring deposit was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TR', 1, 'equity_return_base', 0.2, NULL, 'assumption', 'BIST 100 record (Trading Economics); inflation projection 18%; 10-year bond yield 35.9%', 'https://tradingeconomics.com/turkey/stock-market', '2026-10-31', 'Base case: a small real return above the 18% inflation assumption, since the BIST 100 has been volatile and weak in dollar terms; far below today''s after-tax safe rates of over 30%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TR', 1, 'equity_return_high', 0.28, NULL, 'assumption', 'BIST 100 record (Trading Economics)', 'https://tradingeconomics.com/turkey/stock-market', '2026-10-31', 'High case: a strong nominal run like 2020-2024, when lira share prices rose much faster than inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TR', 1, 'equity_return_low', 0.12, NULL, 'assumption', 'BIST 100 at 10,760 on 30 Oct 2026, down 1.9% on a year (Trading Economics)', 'https://tradingeconomics.com/turkey/stock-market', '2026-10-31', 'Low case: Turkish shares lag the 18% inflation assumption, as in the past year when the BIST 100 fell while prices rose about 30%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TR', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Same as the 3-month rate: CBRT weekly deposit rates by maturity could not be read from EVDS.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TR', 1, 'fdr_3m_rate', 0.4322, NULL, 'sourced', 'Endeks24, citing CBRT weekly deposit rate statistics (TL deposits up to 3 months, week of 16 October 2026)', 'https://www.endeks24.com/tl-mevduat-faizi-yuzde-4288e-indi-dusus-12-haftaya-uzandi', '2026-10-16', 'Weighted average rate on new TL deposits with maturity up to 3 months, 43.22% in the week of 16 October 2026 (43.20% a week earlier); secondary source (news report of 22 October 2026) because the CBRT EVDS tables could not be read. The 22 October policy cut to 36% is not yet reflected.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TR', 1, 'fixed_income_return_base', 0.19, NULL, 'assumption', 'CBRT policy rate 36%; 10-year bond 35.9%; inflation projection 18%', 'https://www.tcmb.gov.tr/wps/wcm/connect/EN/TCMB+EN/Main+Menu/Core+Functions/Monetary+Policy/Central+Bank+Interest+Rates/1+Week+Repo', '2026-10-31', 'Base case: after-tax safe rates settle about 1 point above the 18% long-run inflation assumption, far below today''s after-tax 3-month deposit rate of about 35.7% (43.2% less 17.5% withholding) as disinflation continues.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TR', 1, 'fixed_income_return_high', 0.25, NULL, 'assumption', 'CBRT policy rate 36%; 10-year bond 35.9%', 'https://tradingeconomics.com/turkey/government-bond-yield', '2026-10-31', 'High case: tight monetary policy keeps real after-tax deposit and bond returns high for longer.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TR', 1, 'fixed_income_return_low', 0.16, NULL, 'assumption', 'Inflation projection 18%; IMF path to 15% inflation by 2030', 'https://www.imf.org/external/datamapper/api/v1/PCPIPCH/TUR', '2026-10-31', 'Low case: after the 15-17.5% withholding, deposits and bonds earn slightly less than inflation, as often happened in 2021-2023.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TR', 1, 'goal_inflation_education', 0.23, NULL, 'assumption', 'TurkStat education CPI +48.6% year on year in September 2026 (Finance Minister statement via Forbes Türkiye); inflation projection 18%', 'https://www.forbes.com.tr/ekonomi/tuik-eylul-enflasyonunu-acikladi-eylul-2026-tuketici-fiyat-endeksi-tuik', '2026-10-31', 'Education prices rose 48.6% in the year to September 2026, far above headline CPI of 29.7%, so education costs are planned 5 points above the 18% general inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TR', 1, 'goal_inflation_health', 0.19, NULL, 'assumption', 'Inflation projection 18%; TurkStat headline CPI 29.7% (Sep 2026, via Trading Economics)', 'https://tradingeconomics.com/turkey/inflation-cpi', '2026-10-31', 'No health CPI figure could be read; private medical costs are set slightly above the 18% general inflation assumption because they track imported equipment and the exchange rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TR', 1, 'gold_return_base', 0.19, NULL, 'assumption', 'Gold price history (Trading Economics); inflation gap between Türkiye (18% assumed) and the US (about 2-3%)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Base case: dollar gold rises about 4% a year and the lira loses about 15% a year against the dollar, in line with the inflation gap.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TR', 1, 'gold_return_high', 0.28, NULL, 'assumption', 'Gold price history (Trading Economics); lira depreciation of 2018-2023', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'High case: strong dollar gold plus faster lira depreciation, as in past currency crises.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TR', 1, 'gold_return_low', 0.12, NULL, 'assumption', 'Gold USD 3,876/oz on 30 Oct 2026, down 3% on a year (Trading Economics); CBRT USD rate 49.82', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Low case: flat dollar gold with the lira losing about 12% a year, below the inflation gap.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TR', 1, 'gratuity_rule', NULL, '{"daysPerYear":30,"daysPerYearAfter":null,"afterYears":null,"daysPerMonth":30}', 'sourced', 'Labour Law No. 1475, Article 14 (severance pay, kıdem tazminatı)', 'https://www.mevzuat.gov.tr/mevzuatmetin/1.5.1475.pdf', '2026-10-31', '30 days'' gross wage for each full year of service (pro rata for part years) after at least one year with the employer, paid on retirement, dismissal other than for misconduct, military service, a woman leaving within a year of marriage, or death; capped per year at the maximum civil-servant retirement bonus.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TR', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'General Health Insurance (GSS) covers care in public hospitals; no official figure for the typical out-of-pocket cost of a major private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TR', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Private and complementary (tamamlayıcı) health insurance is sold, but no age-banded premium table per TRY 100,000 of cover from a public source was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TR', 1, 'inflation_cpi', 0.2977, NULL, 'sourced', 'Trading Economics, citing the Turkish Statistical Institute (TurkStat), CPI October 2026', 'https://tradingeconomics.com/turkey/inflation-cpi', '2026-10-31', 'Consumer prices up 29.77% year on year in October 2026 (29.73% in September), released 3 November 2026; secondary source because the TurkStat bulletin could not be opened. World Bank 2025 average 34.9%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TR', 1, 'inflation_projection', 0.18, NULL, 'assumption', 'IMF World Economic Outlook inflation path for Türkiye (31.2% 2026, 15.0% 2030); CBRT 5% medium-term target; 2021-2025 average about 48%', 'https://www.imf.org/external/datamapper/api/v1/PCPIPCH/TUR', '2026-10-31', 'The IMF expects disinflation to about 15% by 2030 but Türkiye has missed its 5% target for many years and inflation averaged about 48% in 2021-2025, so 18% a year is used for long-range plans.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TR', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life cover is sold, often tied to loans, but no published premium table per TRY 1,000 of cover by age from a regulator or other public source was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TR', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No industry-wide life claim settlement ratio from the insurance regulator (SEDDK) or the insurers'' association was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TR', 1, 'life_expectancy', 77.42, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=TR', '2024-12-31', '2024 (older than 2025): men 74.6, women 80.3. UN WPP gives 78.4 for 2026 (georank.org).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TR', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":21.6,"men":19.3,"women":23.7},{"age":65,"total":17.6,"men":15.7,"women":19.4},{"age":70,"total":14,"men":12.3,"women":15.4},{"age":80,"total":7.7,"men":6.3,"women":8.7}]}', 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/turkey', '2026-07-01', 'Remaining years computed from georank''s expected age at death by current age (UN WPP estimate for 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TR', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":65,"womenAge":65,"over90Monthly":null,"meansTested":true}', 'sourced', 'Law No. 2022 on monthly payments to needy, disabled and destitute citizens over 65, Article 1', 'https://www.mevzuat.gov.tr/mevzuatmetin/1.5.2022.pdf', '2026-10-31', 'Paid to Turkish citizens aged 65+ found needy by the social assistance foundations, with no other pension or income; not payable when household income per person exceeds one third of the net minimum wage.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TR', 1, 'old_age_allowance_monthly', 7257, NULL, 'sourced', 'Habertürk, 65 yaş aylığı (needs-based old-age pension) from July 2026', 'https://www.haberturk.com/65-yas-ayligi-2026-temmuz-zammi-yaslilik-maasi-ne-kadar-kac-tl-oldu-3895827', '2026-07-01', 'About TRY 7,257 a month for July-December 2026 (6,393 in January-June), raised 13.52% with the civil-servant salary coefficient under Law No. 2022; means-tested, paid by the Ministry of Family and Social Services. Secondary source (news report of 4 July 2026); other reports give 7,256.71.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TR', 1, 'oop_health_share', 0.1905, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=TR', '2023-12-31', 'Latest available year is 2023 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TR', 1, 'policy_rate', 0.36, NULL, 'sourced', 'Central Bank of the Republic of Türkiye, one-week repo rate history', 'https://www.tcmb.gov.tr/wps/wcm/connect/EN/TCMB+EN/Main+Menu/Core+Functions/Monetary+Policy/Central+Bank+Interest+Rates/1+Week+Repo', '2026-10-23', 'One-week repo rate cut from 37% to 36% at the 22 October 2026 decision, effective 23 October; overnight lending 39% and borrowing 34.5% (Trading Economics).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TR', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":65,"nomineeUntilAge":null,"inflationLinked":true,"taxFree":null}', 'sourced', 'Law No. 5510, Articles 28 (pension age) and 55 (indexation)', 'https://www.mevzuat.gov.tr/mevzuatmetin/1.5.5510.pdf', '2026-10-31', 'Compulsory pay-as-you-go old-age insurance run by SGK (employee 14% and employer about 20.75% of pay for all SGK branches, PwC 2026). Pensions rise every January and July by the previous six months'' CPI change (Article 55). Pension age rises to 65 for those first insured after 2008; tax treatment of pensions was not checked.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TR', 1, 'retirement_accumulation_return_base', 0.195, NULL, 'assumption', 'Fixed income base 19%; equity base 20%', 'https://tradingeconomics.com/turkey/stock-market', '2026-10-31', 'Base case: roughly half shares at 20% and half deposits and bonds at 19%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TR', 1, 'retirement_accumulation_return_high', 0.265, NULL, 'assumption', 'Fixed income high 25%; equity high 28%', 'https://tradingeconomics.com/turkey/stock-market', '2026-10-31', 'High case for a growth-leaning balanced mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TR', 1, 'retirement_accumulation_return_low', 0.14, NULL, 'assumption', 'Fixed income low 16%; equity low 12%', 'https://tradingeconomics.com/turkey/stock-market', '2026-10-31', 'Low case for a balanced mix if both shares and deposits lag inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TR', 1, 'retirement_age_default', 65, NULL, 'sourced', 'Social Insurance and General Health Insurance Law No. 5510, Article 28', 'https://www.mevzuat.gov.tr/mevzuatmetin/1.5.5510.pdf', '2026-10-31', 'For people first insured after the law (2008): women 58 and men 60 until 2035, then rising two years at a time to men 65 from 2044 and women 65 from 2048, using the age in force when the premium-day requirement (7,200 days for employees) is met; so 65 applies to most people born after 1975 who started work after 2008. Earlier entrants retire under transitional rules (in practice 58-62 today).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TR', 1, 'retirement_age_government', 65, NULL, 'sourced', 'Social Insurance and General Health Insurance Law No. 5510, Article 28', 'https://www.mevzuat.gov.tr/mevzuatmetin/1.5.5510.pdf', '2026-10-31', 'Civil servants first covered after 2008 fall under the same Article 28 age schedule (rising to 65), with a 9,000 premium-day requirement instead of 7,200.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TR', 1, 'retirement_return_base', 0.18, NULL, 'assumption', 'CBRT weekly 3-month TL deposit rate 43.2% (about 35.7% after 17.5% withholding); 10-year bond 35.9%; inflation projection 18%', 'https://www.endeks24.com/tl-mevduat-faizi-yuzde-4288e-indi-dusus-12-haftaya-uzandi', '2026-10-31', 'Base case: safe after-tax returns about equal to long-run inflation, well below today''s after-tax deposit and bond rates as rates fall with inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TR', 1, 'retirement_return_high', 0.23, NULL, 'assumption', 'CBRT policy rate 36%; 10-year bond 35.9%', 'https://tradingeconomics.com/turkey/government-bond-yield', '2026-10-31', 'High case: real rates stay high for longer.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TR', 1, 'retirement_return_low', 0.15, NULL, 'assumption', 'Inflation projection 18%; 17.5% withholding on short TL deposit interest (Official Gazette, Decision 10041)', 'https://www.resmigazete.gov.tr/eskiler/2025/07/20250709-6.pdf', '2026-10-31', 'Low case: a retiree''s deposits earn less than inflation after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TR', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate for individuals was found; individuals can buy Treasury bonds and lease certificates through banks.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TR', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No official figure for ordinary (demand) savings account interest was found; the CBRT weekly deposit rate statistics load only in its EVDS data system, which could not be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TR', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":6.47},{"year":2040,"value":4.03},{"year":2065,"value":1.95}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/turkey/2040/', '2025-12-31', '100 / old-age dependency ratio: 15.45 (2025, World Bank), 24.8 (2040) and 51.2 (2065, populationpyramid.net/turkey/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TR', 1, 'tax_bank_interest', 0.175, NULL, 'sourced', 'Official Gazette (Resmî Gazete) No. 32951 of 9 July 2025, Presidential Decision 10041 amending Decision 2006/10731 (withholding under Income Tax Law provisional article 67)', 'https://www.resmigazete.gov.tr/eskiler/2025/07/20250709-6.pdf', '2025-07-09', 'Decision 10041 raised the final withholding on TL demand deposits and deposits of up to 6 months from 15% to 17.5% and on deposits of up to 1 year from 12% to 15% (over 1 year stays 10%), for deposits opened or renewed from 9 July 2025; read from the gazette page image. No later change was found up to October 2026 (Decision 11444 of June 2026 only extends a temporary rate for government bonds and lease certificates). PwC Tax Summaries still shows the pre-2023 10%/7.5%/5% rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TR', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate exists. PwC lists 10% withholding on local government bonds issued after 2006; the rate for Treasury bonds held by individuals was not stated.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TR', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No current 3-month Treasury bill yield was found; the Treasury issues few bills that short. The 2-year benchmark yield was 39.77% on 30 October 2026 (Trading Economics).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TR', 1, 'tbond_10y_rate', 0.3587, NULL, 'sourced', 'Trading Economics, Turkey 10-year government bond yield', 'https://tradingeconomics.com/turkey/government-bond-yield', '2026-10-30', 'Market yield on 30 October 2026 (up about 2.8 points that session); secondary source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TR', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 5-year benchmark yield could be read (the bond yield pages tried showed only 2- and 10-year yields).', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('TT', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"TT","iso3":"TTO","nameEn":"Trinidad and Tobago","nameNative":"Trinidad and Tobago","region":"latin_america_caribbean","languages":["en","trf"],"currency":{"code":"TTD","symbol":"$","decimals":2,"compact":"intl","usdRate":{"value":6.7701,"status":"sourced","sourceName":"Central Bank of Trinidad and Tobago, Economic DataPack September 2026, exchange rates: US dollar selling rate (monthly average)","sourceUrl":"https://www.central-bank.org.tt/wp-content/uploads/2026/10/economic-datapack-september-2026.pdf","asOf":"2026-08-31","note":"TT$6.7701 per US dollar, August 2026 average selling rate (6.7786 in August 2025); the rate has been managed near 6.77 for years. The Central Bank''s daily selling rate was 6.7749 on 3 November 2026. World Bank 2025 average 6.75."}},"instruments":{"savings_account":{"available":true,"localName":"Savings account","note":"Banks pay low rates; the weighted average deposit rate was 0.92% in June 2026. Interest is tax-free for residents."},"fdr_3m":{"available":true,"localName":"Fixed deposit (3 months)","note":"Time deposits are offered by banks; no average rate by term is published.","sourceUrl":"https://www.central-bank.org.tt/wp-content/uploads/2026/10/economic-datapack-september-2026.pdf"},"fdr_1y":{"available":true,"localName":"Fixed deposit (1 year)","note":"Time deposits are offered by banks; no average rate by term is published.","sourceUrl":"https://www.central-bank.org.tt/wp-content/uploads/2026/10/economic-datapack-september-2026.pdf"},"dps":{"available":false,"localName":null,"localNameEn":"Recurring deposit","note":"No standard monthly recurring deposit product was found in Central Bank data."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":"Government savings certificate","note":"No separate retail savings certificate; individuals can buy ordinary government bonds at auction.","sourceUrl":"https://www.central-bank.org.tt/core-functions/market-operations/bonds/"},"tbill_91d":{"available":true,"localName":"Treasury bill","localNameEn":"Treasury bill","note":"Issued by the Central Bank for the government, mostly bought by institutions.","sourceUrl":"https://www.central-bank.org.tt/core-functions/market-operations/treasury-bills/"},"tbond_5y":{"available":true,"localName":"Government bond","localNameEn":"Government bond","note":"The public can buy at auction, competitively or non-competitively, through Government Securities Intermediaries.","sourceUrl":"https://www.central-bank.org.tt/core-functions/market-operations/bonds/"},"tbond_10y":{"available":true,"localName":"Government bond","localNameEn":"Government bond","note":"The public can buy at auction through Government Securities Intermediaries.","sourceUrl":"https://www.central-bank.org.tt/core-functions/market-operations/bonds/"},"equity_fund":{"available":true,"localName":"Equity mutual fund (unit trust)","note":"Equity funds held TT$8.1 billion in June 2026 (CBTT DataPack).","sourceUrl":"https://www.central-bank.org.tt/wp-content/uploads/2026/10/economic-datapack-september-2026.pdf"},"gold":{"available":true,"localName":"Gold bullion (bars and coins)","note":"No legal restriction on owning gold was found; there is no local exchange-traded gold market."}},"institutions":{"centralBank":{"name":"Central Bank of Trinidad and Tobago","url":"https://www.central-bank.org.tt/"},"insuranceRegulator":{"name":"Central Bank of Trinidad and Tobago, insurance sector supervision","url":"https://www.central-bank.org.tt/core-functions/financial-stability/insurance-sector/"},"insuranceComplaints":{"name":"Office of the Financial Services Ombudsman (OFSO)","url":"https://www.ofso.org.tt/"},"pensionScheme":{"name":"National Insurance Board of Trinidad and Tobago (NIBTT), retirement pension","url":"https://www.nibtt.net/benefits_09/ben_retirement.html"},"oldAgeAllowance":{"name":"Senior Citizens'' Pension (Ministry of Social Development and Family Services)","url":"https://ttconnect.gov.tt/senior-citizens-pension"},"publicHealthCover":{"name":"Ministry of Health, accessing public healthcare (Regional Health Authorities)","url":"https://health.gov.tt/accessing-public-healthcare"},"depositInsurance":{"name":"Deposit Insurance Corporation of Trinidad and Tobago","url":"https://dictt.org/deposit-insurance/deposit-insurance-coverage/"},"statistics":{"name":"Central Statistical Office (CSO)","url":"https://cso.gov.tt/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TT', 1, 'bank_deposit_avg_rate', 0.0092, NULL, 'sourced', 'Central Bank of Trinidad and Tobago, Economic DataPack September 2026, Selected Interest Rates: commercial banks'' weighted average deposit rate', 'https://www.central-bank.org.tt/wp-content/uploads/2026/10/economic-datapack-september-2026.pdf', '2026-06-30', '0.92% in June 2026 (0.92% in March 2026, 0.80% in June 2025). World Bank deposit rate 1.5% (2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TT', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap on credit card interest was found; the Central Bank''s October 2026 comparative schedule for credit cards lists fees only, not interest rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TT', 1, 'deposit_insurance_limit', 200000, NULL, 'sourced', 'Deposit Insurance Corporation of Trinidad and Tobago, deposit insurance coverage', 'https://dictt.org/deposit-insurance/deposit-insurance-coverage/', '2026-10-31', 'TT$200,000 per depositor per member institution in each right and capacity, Trinidad and Tobago dollar deposits only.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TT', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No monthly recurring deposit product or published rate was found in Central Bank data.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TT', 1, 'equity_return_base', 0.055, NULL, 'assumption', 'Weak local index record; 3-month Treasury 3.01% and 1-year Treasury 4.59% (CBTT DataPack); bank interest tax-free', 'https://www.central-bank.org.tt/wp-content/uploads/2026/10/economic-datapack-september-2026.pdf', '2026-10-31', 'The T&T Composite Index is lower than five years ago, so the base case is only about 2.5 points over the 3% Treasury bill rate, below the safe rate plus 4 points.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TT', 1, 'equity_return_high', 0.09, NULL, 'assumption', 'Local dividend yields plus recovery, or global equities in TT dollar terms (TT dollar near 6.77 per US dollar since 2017)', 'https://www.central-bank.org.tt/wp-content/uploads/2026/10/economic-datapack-september-2026.pdf', '2026-10-31', 'High case: local shares recover or savers hold global equity funds, which in TT dollars track US dollar returns because the exchange rate is managed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TT', 1, 'equity_return_low', 0.01, NULL, 'assumption', 'CBTT Economic DataPack: T&T Composite Index 1,016.7 in August 2026, up only 1.6% in a year', 'https://www.central-bank.org.tt/wp-content/uploads/2026/10/economic-datapack-september-2026.pdf', '2026-10-31', 'Low case: the local index keeps drifting as it has since its 2020 peak, leaving only dividends.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TT', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published average rate for 1-year time deposits was found; the Central Bank''s Economic DataPack gives only the overall weighted average deposit rate (0.92%, June 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TT', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published average rate for 3-month time deposits was found; the Central Bank''s Economic DataPack gives only the overall weighted average deposit rate (0.92%, June 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TT', 1, 'fixed_income_return_base', 0.03, NULL, 'assumption', '3-month Treasury 3.01%, 1-year 4.59% (CBTT yield curve August 2026)', 'https://www.central-bank.org.tt/wp-content/uploads/2026/10/economic-datapack-september-2026.pdf', '2026-10-31', 'Base case: a mix of short government securities and higher-paying deposits; tax on government security interest for individuals is not confirmed, so the figure stays near the bill rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TT', 1, 'fixed_income_return_high', 0.05, NULL, 'assumption', '5-year government bond 5.48% (CBTT yield curve August 2026)', 'https://www.central-bank.org.tt/wp-content/uploads/2026/10/economic-datapack-september-2026.pdf', '2026-10-31', 'High case: locking in five-year government bonds bought at auction through a securities intermediary.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TT', 1, 'fixed_income_return_low', 0.01, NULL, 'assumption', 'Commercial banks'' weighted average deposit rate 0.92%, tax-free (CBTT DataPack June 2026)', 'https://www.central-bank.org.tt/wp-content/uploads/2026/10/economic-datapack-september-2026.pdf', '2026-10-31', 'Low case: money left in bank deposits, which pay under 1% but are tax-free.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TT', 1, 'goal_inflation_education', 0.03, NULL, 'assumption', 'CBTT Economic DataPack September 2026: CPI education sub-index unchanged at 102.5 (0.0% year on year)', 'https://www.central-bank.org.tt/wp-content/uploads/2026/10/economic-datapack-september-2026.pdf', '2026-10-31', 'The CPI education index has been flat (public education is largely free), but private school and tertiary fees rise over time, so planning uses 3%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TT', 1, 'goal_inflation_health', 0.03, NULL, 'assumption', 'CBTT Economic DataPack September 2026: CPI health sub-index +0.9% year on year (July 2026)', 'https://www.central-bank.org.tt/wp-content/uploads/2026/10/economic-datapack-september-2026.pdf', '2026-10-31', 'Measured health prices rose under 1% in the last year, but private medical costs and imported drugs tend to rise faster than the CPI, so planning uses 3%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TT', 1, 'gold_return_base', 0.04, NULL, 'assumption', 'Gold USD price trend (Trading Economics); TT dollar managed near 6.77 per US dollar (CBTT DataPack)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Base case: gold tracks long-run dollar inflation plus a little, with the TT dollar broadly stable against the dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TT', 1, 'gold_return_high', 0.08, NULL, 'assumption', 'Gold USD price history (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'High case: gold resumes its 2020s uptrend or the TT dollar is devalued.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TT', 1, 'gold_return_low', 0, NULL, 'assumption', 'Gold about USD 3,900/oz at the start of November 2026, little changed in a year and well below its January 2026 peak of USD 5,608 (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Low case: gold stays flat in dollars and the managed TT dollar does not weaken.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TT', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Retrenchment and Severance Benefits Act provides severance on retrenchment (redundancy), but its text could not be read from an official source and no statutory gratuity on retirement was confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TT', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a private hospital stay was found; public hospitals under the Regional Health Authorities provide care at little or no charge.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TT', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No regulator or other non-company source of private health insurance premiums by age was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TT', 1, 'inflation_cpi', 0.006, NULL, 'sourced', 'Central Bank of Trinidad and Tobago, Monetary Policy Announcement 30 September 2026 (CSO Consumer Price Index)', 'https://www.central-bank.org.tt/wp-content/uploads/2026/09/monetary-policy-announcement-2026-09-30-september-2026-1.pdf', '2026-07-31', 'Headline CPI inflation 0.6% year on year in July 2026 (food 1.7%, core 0.2%), the latest CSO figure cited by the Central Bank; the CSO page itself showed 0.3% for June 2026. World Bank 2025 average 1.0%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TT', 1, 'inflation_projection', 0.025, NULL, 'assumption', 'CBTT Economic DataPack September 2026 (headline inflation 0.3-1.5% in 2024-2026); no formal inflation target', 'https://www.central-bank.org.tt/wp-content/uploads/2026/10/economic-datapack-september-2026.pdf', '2026-10-31', 'The Central Bank does not target inflation; recent inflation is about 1% but the five-year average (2021-2025, including the 2022-2023 food-price spike) is near 2.5-3%, so planning uses 2.5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TT', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life cover is sold in Trinidad and Tobago, but no regulator or other non-company source with indicative premiums by age was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TT', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Central Bank supervises insurers under the Insurance Act 2018 but no industry-wide life claim settlement ratio was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TT', 1, 'life_expectancy', 73.617, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=TT', '2024-12-31', 'Men 70.5, women 76.8 (2024). UN WPP gives 73.9 for 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TT', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":20,"men":18.1,"women":21.7},{"age":65,"total":16.2,"men":14.6,"women":17.6},{"age":70,"total":12.6,"men":11.3,"women":13.7},{"age":80,"total":6.9,"men":6.2,"women":7.4}]}', 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/trinidad-and-tobago', '2026-07-01', 'Remaining years derived from the ''life expectancy by current age'' table for 2026 (UN WPP): total age reached minus current age.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TT', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":65,"womenAge":65,"over90Monthly":null,"meansTested":true}', 'sourced', 'ttconnect (Government of Trinidad and Tobago), Senior Citizens'' Pension', 'https://ttconnect.gov.tt/senior-citizens-pension', '2026-10-31', 'Age 65 or over, resident 20 consecutive years before applying (or 50 years in total), with monthly income not above TT$5,500.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TT', 1, 'old_age_allowance_monthly', 3500, NULL, 'sourced', 'ttconnect (Government of Trinidad and Tobago), Senior Citizens'' Pension', 'https://ttconnect.gov.tt/senior-citizens-pension', '2026-10-31', 'Maximum TT$3,500 a month for people whose own monthly income is up to TT$2,500; it falls to TT$2,500, 1,500 and 500 for incomes up to TT$5,500, above which nothing is paid.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TT', 1, 'oop_health_share', 0.4527, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=TT', '2023-12-31', 'Out-of-pocket spending was 45.3% of current health expenditure in 2023 (latest available; older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TT', 1, 'policy_rate', 0.035, NULL, 'sourced', 'Central Bank of Trinidad and Tobago, Monetary Policy Announcement: repo rate maintained at 3.50%', 'https://www.central-bank.org.tt/wp-content/uploads/2026/09/monetary-policy-announcement-2026-09-30-september-2026-1.pdf', '2026-09-30', 'Repo rate held at 3.50% on 30 September 2026; it has been 3.50% since March 2020.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TT', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":60,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'National Insurance Board of Trinidad and Tobago, Retirement (Grant/Pension)', 'https://www.nibtt.net/benefits_09/ben_retirement.html', '2026-10-31', 'National Insurance is compulsory for employees. Pension from 60 (if retired from insurable employment) or 65 whether retired or not, with at least 750 weekly contributions; fewer contributions give a one-off retirement grant (minimum TT$3,000). The NIB page states no automatic indexation, so the pension is treated as not inflation-linked; tax treatment is not stated.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TT', 1, 'retirement_accumulation_return_base', 0.045, NULL, 'assumption', 'Fixed income base 3%; equity base 5.5%', 'https://www.central-bank.org.tt/wp-content/uploads/2026/10/economic-datapack-september-2026.pdf', '2026-10-31', 'Base case: roughly half safe TT dollar fixed income and half equity funds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TT', 1, 'retirement_accumulation_return_high', 0.07, NULL, 'assumption', 'Equity high 9%; 5-year government bond 5.48%', 'https://www.central-bank.org.tt/wp-content/uploads/2026/10/economic-datapack-september-2026.pdf', '2026-10-31', 'High case: equities do well and long bond yields stay near 5-6%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TT', 1, 'retirement_accumulation_return_low', 0.02, NULL, 'assumption', 'Fixed income low 1%; equity low 1%; bonds 3-5%', 'https://www.central-bank.org.tt/wp-content/uploads/2026/10/economic-datapack-september-2026.pdf', '2026-10-31', 'Low case for a balanced mix of deposits, government bonds and equity funds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TT', 1, 'retirement_age_default', 60, NULL, 'sourced', 'National Insurance Board of Trinidad and Tobago, Retirement (Grant/Pension)', 'https://www.nibtt.net/benefits_09/ben_retirement.html', '2026-10-31', 'The NIS retirement pension can be claimed from 60 if retired from insurable employment, or at 65 whether retired or not, with at least 750 weekly contributions; the same rule applies to people born after 1975.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TT', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'The compulsory retirement age for public servants could not be confirmed from an official page that could be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TT', 1, 'retirement_return_base', 0.03, NULL, 'assumption', '3-month Treasury 3.01% (CBTT yield curve August 2026)', 'https://www.central-bank.org.tt/wp-content/uploads/2026/10/economic-datapack-september-2026.pdf', '2026-10-31', 'Base case: short government securities and term deposits, kept at the 3% Treasury bill rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TT', 1, 'retirement_return_high', 0.045, NULL, 'assumption', '1-year Treasury 4.59%, 5-year 5.48% (CBTT yield curve August 2026)', 'https://www.central-bank.org.tt/wp-content/uploads/2026/10/economic-datapack-september-2026.pdf', '2026-10-31', 'High case: a ladder of one- to five-year government bonds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TT', 1, 'retirement_return_low', 0.015, NULL, 'assumption', 'Commercial banks'' weighted average deposit rate 0.92%, tax-free; 3-month Treasury 3.01% (CBTT DataPack)', 'https://www.central-bank.org.tt/wp-content/uploads/2026/10/economic-datapack-september-2026.pdf', '2026-10-31', 'Low case: mostly bank deposits with some Treasury bills.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TT', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No separate government savings certificate or retail savings bond for individuals was found; the Central Bank says the public can buy ordinary government bonds at auction through Government Securities Intermediaries.', 0);
