INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TT', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":5.38},{"year":2040,"value":3.61},{"year":2065,"value":2.02}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/trinidad-and-tobago/2065/', '2025-12-31', '100 / old-age dependency ratio: 18.6 in 2025 (World Bank), 27.7 in 2040 and 49.5 in 2065 (UN WPP medium variant).', 0);
