INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TW', 1, 'bank_deposit_avg_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The CBC weighted average deposit rate of domestic banks was not read; only five-bank posted rates were (see fdr rates).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TW', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'Banking Act caps credit card revolving rates, but the law database (law.moj.gov.tw) was unreachable, so the cap is not confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TW', 1, 'deposit_insurance_limit', 3000000, NULL, 'sourced', 'Central Deposit Insurance Corporation (CDIC), Deposit Insurance System overview', 'https://www.cdic.gov.tw/main_en/List.aspx?uid=243&pid=83', '2011-01-01', 'Maximum coverage NT$3 million per depositor per insured institution, unchanged since 1 Jan 2011 and still shown as current on the CDIC page (read Oct 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TW', 1, 'dps_rate', 0.0176, NULL, 'sourced', 'Central Bank, five major banks'' deposit rates, monthly history (3-year time savings deposit, fixed)', 'https://www.cbc.gov.tw/tw/np-1166-1.html', '2026-09-30', 'Average 3-year fixed rate on time savings deposits (定期儲蓄存款), the account type used for monthly installment savings (零存整付); range 1.745-1.785%, September 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TW', 1, 'equity_return_base', 0.057, NULL, 'assumption', 'Five-bank 1-year deposit rate 1.70% plus 4 points', 'https://www.cbc.gov.tw/tw/np-371-1.html', '2026-10-31', 'The 10-year index record is very strong, but the base is capped at the tax-free 1-year deposit rate plus 4 points.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TW', 1, 'equity_return_high', 0.09, NULL, 'assumption', 'TAIEX long-run record (Trading Economics)', 'https://tradingeconomics.com/taiwan/stock-market', '2026-10-31', 'High case if technology earnings keep growing near their long-run pace.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TW', 1, 'equity_return_low', 0, NULL, 'assumption', 'TAIEX record (Trading Economics); five-bank 1-year deposit rate', 'https://tradingeconomics.com/taiwan/stock-market', '2026-10-31', 'The TAIEX rose 60% in the year to 30 Oct 2026 and is concentrated in technology, so a flat decade from today''s level is the low case.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TW', 1, 'fdr_1y_rate', 0.017, NULL, 'sourced', 'Central Bank, five major banks'' average deposit rates (1-year fixed time deposit)', 'https://www.cbc.gov.tw/tw/np-371-1.html', '2026-10-30', 'All five banks quote 1.70% on 30 Oct 2026; 2-year 1.70-1.73%, 3-year 1.705-1.745%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TW', 1, 'fdr_3m_rate', 0.0129, NULL, 'sourced', 'Central Bank, five major banks'' average deposit rates (3-month fixed time deposit)', 'https://www.cbc.gov.tw/tw/np-371-1.html', '2026-10-30', 'Five-bank rates 1.285-1.29% on 30 Oct 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TW', 1, 'fixed_income_return_base', 0.017, NULL, 'assumption', 'Central Bank, five major banks'' average deposit rates', 'https://www.cbc.gov.tw/tw/np-371-1.html', '2026-10-31', 'Base case at the 1-year time deposit rate. Safe TWD rates: five-bank average fixed time deposit 1.29% (3 months) and 1.70% (1 year) on 30 Oct 2026; 10-year government bond 1.99%; deposit interest up to NT$270,000 a year per household is deductible, so most savers pay no tax on it.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TW', 1, 'fixed_income_return_high', 0.02, NULL, 'assumption', 'Trading Economics, Taiwan 10-year government bond yield', 'https://tradingeconomics.com/taiwan/government-bond-yield', '2026-10-31', 'High case near the 10-year government bond yield. Safe TWD rates: five-bank average fixed time deposit 1.29% (3 months) and 1.70% (1 year) on 30 Oct 2026; 10-year government bond 1.99%; deposit interest up to NT$270,000 a year per household is deductible, so most savers pay no tax on it.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TW', 1, 'fixed_income_return_low', 0.0129, NULL, 'assumption', 'Central Bank, five major banks'' average deposit rates', 'https://www.cbc.gov.tw/tw/np-371-1.html', '2026-10-31', 'Low case at the 3-month time deposit rate. Safe TWD rates: five-bank average fixed time deposit 1.29% (3 months) and 1.70% (1 year) on 30 Oct 2026; 10-year government bond 1.99%; deposit interest up to NT$270,000 a year per household is deductible, so most savers pay no tax on it.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TW', 1, 'goal_inflation_education', 0.03, NULL, 'assumption', 'DGBAS CPI education and entertainment sub-index (via Trading Economics)', 'https://tradingeconomics.com/taiwan/inflation-cpi', '2026-10-31', 'Education and entertainment CPI rose 3.15% in the year to September 2026, so we plan 1 point above general inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TW', 1, 'goal_inflation_health', 0.03, NULL, 'assumption', 'DGBAS CPI healthcare sub-index (via Trading Economics)', 'https://tradingeconomics.com/taiwan/inflation-cpi', '2026-10-31', 'Healthcare CPI rose 0.7% in the year to September 2026 because National Health Insurance fees are regulated; we plan 1 point above general inflation for private costs.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TW', 1, 'gold_return_base', 0.05, NULL, 'assumption', 'US-dollar gold trend; CBC NT$/US$ closing rate', 'https://www.cbc.gov.tw/tw/lp-645-1.html', '2026-10-31', 'Long-run dollar gold trend of about 5% with no expected NT dollar depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TW', 1, 'gold_return_high', 0.09, NULL, 'assumption', 'US-dollar gold trend; CBC NT$/US$ closing rate', 'https://www.cbc.gov.tw/tw/lp-645-1.html', '2026-10-31', 'High case for a strong gold cycle.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TW', 1, 'gold_return_low', 0.01, NULL, 'assumption', 'US-dollar gold trend; CBC NT$/US$ closing rate', 'https://www.cbc.gov.tw/tw/lp-645-1.html', '2026-10-31', 'Gold can stall for a decade, and the NT dollar can strengthen against the US dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TW', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'Taiwan has no gratuity in the Bangladesh sense: under the Labor Pension Act employers pay at least 6% of wages a month into the worker''s individual pension account (not read), and the old Labor Standards Act retirement pay only covers service before July 2005.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TW', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical out-of-pocket cost of a major hospital stay found; National Health Insurance covers most of the bill.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TW', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premium rates found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TW', 1, 'inflation_cpi', 0.0273, NULL, 'sourced', 'DGBAS consumer price index, September 2026 (via Trading Economics)', 'https://tradingeconomics.com/taiwan/inflation-cpi', '2026-09-30', '2.73% year on year in September 2026, up from 2.05% in August; secondary source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TW', 1, 'inflation_projection', 0.02, NULL, 'assumption', 'Central bank aim of CPI near 2%; recent CPI (DGBAS via Trading Economics)', 'https://tradingeconomics.com/taiwan/inflation-cpi', '2026-10-31', 'Taiwan CPI has stayed close to 2% over the past five years, so we plan with 2% despite the 2.7% reading in September 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TW', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life cover is sold, but we found no published premium rates or credible premium guide we could read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TW', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No industry-wide life insurance claim settlement ratio found on readable regulator pages.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TW', 1, 'life_expectancy', 81.1, NULL, 'sourced', 'UN World Population Prospects (via georank.org)', 'https://georank.org/life-expectancy/taiwan', '2026-07-08', 'Men 78.3, women 84.0 (2026 estimate); Taiwan is not in World Bank data; secondary source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TW', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":24.5,"men":22.6,"women":26.3},{"age":65,"total":20.4,"men":18.7,"women":21.9},{"age":70,"total":16.4,"men":15,"women":17.8},{"age":80,"total":9.6,"men":8.5,"women":10.5}]}', 'sourced', 'UN World Population Prospects (via georank.org)', 'https://georank.org/life-expectancy/taiwan', '2026-07-08', 'Remaining years derived from expected age at death by current age (2026); secondary source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TW', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'No open universal non-contributory pension; the Old-age Basic Guaranteed Pension only covers people aged 65 by 1 Oct 2008 (BLI). The low-income senior living allowance rules could not be read (sfaa.gov.tw unreachable).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TW', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Old-age Basic Guaranteed Pension (NT$4,049, BLI) is closed: only people already 65 on 1 Oct 2008 qualify, so someone planning today cannot receive it. A means-tested living allowance for low-income seniors exists, but its official page (sfaa.gov.tw) was unreachable, so no amount is given.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TW', 1, 'oop_health_share', NULL, NULL, 'missing', '', '', '2026-10-31', 'Taiwan is not in World Bank or WHO health expenditure data; the Ministry of Health and Welfare national health expenditure tables were not read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TW', 1, 'policy_rate', 0.02, NULL, 'sourced', 'Central Bank of the Republic of China (Taiwan) discount rate (via Trading Economics)', 'https://tradingeconomics.com/taiwan/interest-rate', '2026-09-17', 'Discount rate held at 2% at the 17 Sep 2026 meeting; the CBC discount rate page did not render.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TW', 1, 'public_pension_scheme', NULL, NULL, 'missing', '', '', '2026-10-31', 'Labor Insurance old-age pension from 65 (BLI) with at least 15 insured years and benefit of 1.55% of average insured salary per year; whether it is indexed to CPI and its tax treatment could not be confirmed from readable pages.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TW', 1, 'retirement_accumulation_return_base', 0.037, NULL, 'assumption', 'Mix of TWD deposits, bonds and equity funds', 'https://www.cbc.gov.tw/tw/np-371-1.html', '2026-10-31', 'About half equity at 5.7% and half deposits near 1.7%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TW', 1, 'retirement_accumulation_return_high', 0.06, NULL, 'assumption', 'Mix of TWD deposits, bonds and equity funds', 'https://www.cbc.gov.tw/tw/np-371-1.html', '2026-10-31', 'About 60% equity at the high case and 40% deposits and bonds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TW', 1, 'retirement_accumulation_return_low', 0.01, NULL, 'assumption', 'Mix of TWD deposits, bonds and equity funds', 'https://www.cbc.gov.tw/tw/np-371-1.html', '2026-10-31', 'About 40% equity at the low case and 60% deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TW', 1, 'retirement_age_default', 65, NULL, 'sourced', 'Bureau of Labor Insurance, Labor Insurance old-age benefits', 'https://www.bli.gov.tw/en/0007461.html', '2020-12-22', 'Labor Insurance old-age pension age is 65 for people born in 1962 or later (so 65 for anyone born after 1975); at least 15 insured years; claim up to 5 years early at -4% a year or defer at +4% a year. Page last updated 2020, rule still in force.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TW', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'Civil service retirement rules could not be read (Ministry of Civil Service and law database pages unreachable).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TW', 1, 'retirement_return_base', 0.017, NULL, 'assumption', 'Central Bank, five major banks'' average deposit rates', 'https://www.cbc.gov.tw/tw/np-371-1.html', '2026-10-31', 'Base case at the 1-year time deposit rate (tax-free for most savers). Safe TWD rates: five-bank average fixed time deposit 1.29% (3 months) and 1.70% (1 year) on 30 Oct 2026; 10-year government bond 1.99%; deposit interest up to NT$270,000 a year per household is deductible, so most savers pay no tax on it.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TW', 1, 'retirement_return_high', 0.02, NULL, 'assumption', 'Trading Economics, Taiwan 10-year government bond yield', 'https://tradingeconomics.com/taiwan/government-bond-yield', '2026-10-31', 'High case near the 10-year government bond yield. Safe TWD rates: five-bank average fixed time deposit 1.29% (3 months) and 1.70% (1 year) on 30 Oct 2026; 10-year government bond 1.99%; deposit interest up to NT$270,000 a year per household is deductible, so most savers pay no tax on it.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TW', 1, 'retirement_return_low', 0.0129, NULL, 'assumption', 'Central Bank, five major banks'' average deposit rates', 'https://www.cbc.gov.tw/tw/np-371-1.html', '2026-10-31', 'Low case at the 3-month time deposit rate. Safe TWD rates: five-bank average fixed time deposit 1.29% (3 months) and 1.70% (1 year) on 30 Oct 2026; 10-year government bond 1.99%; deposit interest up to NT$270,000 a year per household is deductible, so most savers pay no tax on it.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TW', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Taiwan has no government savings certificate or retail savings bond for individuals.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TW', 1, 'savings_account_rate', 0.0084, NULL, 'sourced', 'Central Bank, five major banks'' deposit rates, monthly history (demand savings deposit)', 'https://www.cbc.gov.tw/tw/np-1166-1.html', '2026-09-30', 'Floating rate on demand savings deposits 0.825-0.855% at the five largest banks, September 2026 (average 0.84%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TW', 1, 'support_ratio', NULL, NULL, 'missing', '', '', '2026-10-31', 'Taiwan is not in World Bank data; the National Development Council population projections site and UN WPP mirror pages for Taiwan were not reachable.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TW', 1, 'tax_bank_interest', 0, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Taiwan individual deductions', 'https://taxsummaries.pwc.com/taiwan/individual/deductions', '2026-10-31', 'No flat tax: bank deposit interest is part of consolidated income, but a special deduction of up to NT$270,000 per tax filing unit means most savers pay none; interest above that is taxed at the household''s marginal rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TW', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate exists in Taiwan.', 0);
