INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TW', 1, 'tbond_10y_rate', 0.0199, NULL, 'sourced', 'Trading Economics, Taiwan 10-year government bond yield', 'https://tradingeconomics.com/taiwan/government-bond-yield', '2026-10-30', '1.99% on 30 Oct 2026, about 0.72 points higher than a year earlier; secondary source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TW', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No readable published 5-year government bond yield found.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('TZ', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"TZ","iso3":"TZA","nameEn":"Tanzania","nameNative":"Tanzania","region":"sub_saharan_africa","languages":["sw","en","suk"],"currency":{"code":"TZS","symbol":"TSh","decimals":2,"compact":"intl","usdRate":{"value":2642.3,"status":"sourced","sourceName":"Bank of Tanzania, Monthly Economic Review October 2026 (end-of-period exchange rate, September 2026)","sourceUrl":"https://www.bot.go.tz/Publications/Regular/Monthly%20Economic%20Review/en/2026102918183001.pdf","asOf":"2026-09-30","note":"TZS 2,642.3 per dollar at the end of September 2026 (monthly average 2,654.91); World Bank 2024 average 2,597.9. CLDR gives ''TZS'' as symbol; ''TSh'' is the local abbreviation."}},"instruments":{"savings_account":{"available":true,"localName":"Akaunti ya akiba","localNameEn":"Savings account","note":"Average savings deposit rate 2.95% in September 2026 (Bank of Tanzania).","sourceUrl":"https://www.bot.go.tz/Publications/Regular/Monthly%20Economic%20Review/en/2026102918183001.pdf"},"fdr_3m":{"available":true,"localName":"Amana ya muda maalum (miezi 3)","localNameEn":"Fixed deposit, 3 months","note":"Average 3-month rate 10.19% in September 2026 (Bank of Tanzania).","sourceUrl":"https://www.bot.go.tz/Publications/Regular/Monthly%20Economic%20Review/en/2026102918183001.pdf"},"fdr_1y":{"available":true,"localName":"Amana ya muda maalum (mwaka 1)","localNameEn":"Fixed deposit, 12 months","note":"Average 12-month rate 9.59% in September 2026 (Bank of Tanzania).","sourceUrl":"https://www.bot.go.tz/Publications/Regular/Monthly%20Economic%20Review/en/2026102918183001.pdf"},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No standard monthly recurring deposit product with published rates was found."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate for individuals; individuals can bid for ordinary Treasury bills and bonds."},"tbill_91d":{"available":true,"localName":"Dhamana za Serikali za muda mfupi","localNameEn":"Treasury bills","note":"Bank of Tanzania auctions every two weeks (35, 91, 182 and 364 days); individuals can bid through banks and brokers.","sourceUrl":"https://www.bot.go.tz/TBills"},"tbond_5y":{"available":true,"localName":"Hatifungani za Serikali","localNameEn":"Treasury bonds","note":"2 to 25 year bonds auctioned by the Bank of Tanzania; the 5-year bond was reopened on 16 September 2026.","sourceUrl":"https://www.bot.go.tz/TBonds"},"tbond_10y":{"available":true,"localName":"Hatifungani za Serikali","localNameEn":"Treasury bonds","note":"The 10-year bond was reopened on 2 September 2026.","sourceUrl":"https://www.bot.go.tz/TBonds"},"equity_fund":{"available":true,"localName":"Mifuko ya uwekezaji wa pamoja","localNameEn":"Collective investment schemes (unit trusts)","note":"Unit trusts are licensed by the Capital Markets and Securities Authority."},"gold":{"available":true,"localName":"Dhahabu","localNameEn":"Gold","note":"Gold is mainly bought as jewellery; no official retail market for investment bars or coins was confirmed."}},"institutions":{"centralBank":{"name":"Bank of Tanzania (Benki Kuu ya Tanzania)","url":"https://www.bot.go.tz/"},"insuranceRegulator":{"name":"Tanzania Insurance Regulatory Authority (TIRA)","url":"https://www.tira.go.tz/"},"insuranceComplaints":{"name":"Tanzania Insurance Ombudsman, under TIRA","url":"https://www.tira.go.tz/contacts","note":"The Insurance Ombudsman (Insurance Ombudsman Regulations, 2013) handles complaints against insurers; TIRA''s site has no separate ombudsman page."},"pensionScheme":{"name":"National Social Security Fund (NSSF)","url":"https://www.nssf.go.tz/benefits/old-age-pension","note":"Public servants belong to the Public Service Social Security Fund (https://www.psssf.go.tz/)."},"oldAgeAllowance":null,"publicHealthCover":{"name":"National Health Insurance Fund (NHIF)","url":"https://www.nhif.or.tz/"},"depositInsurance":{"name":"Deposit Insurance Board (DIB)","url":"https://www.dib.go.tz/","note":"The site is a JavaScript application; its pages could not be read as text on 3 November 2026."},"statistics":{"name":"National Bureau of Statistics (NBS)","url":"https://www.nbs.go.tz/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TZ', 1, 'bank_deposit_avg_rate', 0.0903, NULL, 'sourced', 'Bank of Tanzania, Monthly Economic Review October 2026, Table A4 (overall time deposits rate)', 'https://www.bot.go.tz/Publications/Regular/Monthly%20Economic%20Review/en/2026102918183001.pdf', '2026-09-30', 'Overall shilling time deposit rate 9.03% in September 2026 (the text rounds it to 9.02%); the savings deposit rate is much lower at 2.95%. World Bank FR.INR.DPST is 2020 only (6.68%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TZ', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'Tanzania has no legal cap on lending rates and no official credit card rate was found; for reference the Bank of Tanzania overall lending rate was 15.54% in September 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TZ', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Deposit Insurance Board website is a JavaScript application whose cover limit could not be read, and no other official page stating the current limit per depositor was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TZ', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Bank of Tanzania interest rate table has no rate for a monthly recurring deposit product, and no industry-wide figure was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TZ', 1, 'equity_return_base', 0.1, NULL, 'assumption', 'Bank of Tanzania 12-month deposit rate 9.59% (September 2026), 8.6% after 10% withholding; DSEI history', 'https://www.bot.go.tz/Publications/Regular/Monthly%20Economic%20Review/en/2026102918183001.pdf', '2026-10-31', 'Base case: about 1.5 points above the after-tax one-year deposit rate, well inside the 4-point cap, because the index''s 10-year record is weak despite a 76% rise in the year to November 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TZ', 1, 'equity_return_high', 0.14, NULL, 'assumption', 'Trading Economics, DSEI (+76% over the year to 2 November 2026)', 'https://tradingeconomics.com/tanzania/stock-market', '2026-10-31', 'High case: the recent re-rating continues alongside dividend yields of several percent.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TZ', 1, 'equity_return_low', 0.05, NULL, 'assumption', 'Trading Economics, Dar es Salaam Stock Exchange All Share Index (DSEI)', 'https://tradingeconomics.com/tanzania/stock-market', '2026-10-31', 'Low case: the DSEI moved little for most of the decade before 2024, so a repeat of a flat-price decade plus dividends gives about 5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TZ', 1, 'fdr_1y_rate', 0.0959, NULL, 'sourced', 'Bank of Tanzania, Monthly Economic Review October 2026, Table A4 (12-month deposit rate)', 'https://www.bot.go.tz/Publications/Regular/Monthly%20Economic%20Review/en/2026102918183001.pdf', '2026-09-30', 'Average 12-month shilling time deposit rate, 9.59% in September 2026 (9.36% in August); negotiated deposits for large sums averaged 11.00%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TZ', 1, 'fdr_3m_rate', 0.1019, NULL, 'sourced', 'Bank of Tanzania, Monthly Economic Review October 2026, Table A4 (3-month time deposit rate)', 'https://www.bot.go.tz/Publications/Regular/Monthly%20Economic%20Review/en/2026102918183001.pdf', '2026-09-30', 'Average 3-month shilling time deposit rate across banks, 10.19% in September 2026 (9.74% in August); the 1-month rate was 9.71%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TZ', 1, 'fixed_income_return_base', 0.07, NULL, 'assumption', 'Bank of Tanzania 12-month deposit rate 9.59% and 364-day bill 6.13%, after 10% withholding', 'https://www.bot.go.tz/Publications/Regular/Monthly%20Economic%20Review/en/2026102918183001.pdf', '2026-10-31', 'Base case: between one-year bills (5.5% after tax) and one-year bank deposits (8.6% after tax).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TZ', 1, 'fixed_income_return_high', 0.09, NULL, 'assumption', 'Bank of Tanzania 5-year and 10-year bond auctions (9.53% and 10.69%, 2026)', 'https://www.bot.go.tz/TBonds', '2026-10-31', 'High case: 5-10 year Treasury bonds held to maturity, less withholding, allowing for lower future yields.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TZ', 1, 'fixed_income_return_low', 0.03, NULL, 'assumption', 'Bank of Tanzania savings deposit rate 2.95% and 91-day bill 3.64% (2026)', 'https://www.bot.go.tz/Publications/Regular/Monthly%20Economic%20Review/en/2026102918183001.pdf', '2026-10-31', 'Low case: savings accounts or short bills after 10% withholding, about 3%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TZ', 1, 'goal_inflation_education', 0.05, NULL, 'assumption', 'Bank of Tanzania Monthly Economic Review October 2026, Table A9 (education services CPI); inflation assumption 4%', 'https://www.bot.go.tz/Publications/Regular/Monthly%20Economic%20Review/en/2026102918183001.pdf', '2026-10-31', 'Education services CPI rose about 3% a year in 2024-2025 with yearly fee increases each January, so private school costs are planned one point above the 4% inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TZ', 1, 'goal_inflation_health', 0.05, NULL, 'assumption', 'Bank of Tanzania Monthly Economic Review October 2026, Table A9 (health CPI); inflation assumption 4%', 'https://www.bot.go.tz/Publications/Regular/Monthly%20Economic%20Review/en/2026102918183001.pdf', '2026-10-31', 'Health CPI rose only 1-2% a year in 2025-2026, but private hospital and drug costs follow imports and the exchange rate, so one point above the 4% inflation assumption is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TZ', 1, 'gold_return_base', 0.065, NULL, 'assumption', 'Bank of Tanzania exchange rate data; inflation target 3-5%', 'https://www.bot.go.tz/Publications/Regular/Monthly%20Economic%20Review/en/2026102918183001.pdf', '2026-10-31', 'Base case: a dollar gold trend of about 4% a year plus shilling depreciation of 2-3% a year, in line with the inflation gap to the US.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TZ', 1, 'gold_return_high', 0.11, NULL, 'assumption', 'Bank of Tanzania exchange rate data (shilling down 7.4% in the year to September 2026)', 'https://www.bot.go.tz/Publications/Regular/Monthly%20Economic%20Review/en/2026102918183001.pdf', '2026-10-31', 'High case: strong dollar gold years combined with faster depreciation like 2023-2024 (annual average 2,382 to 2,597 per dollar).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TZ', 1, 'gold_return_low', 0.02, NULL, 'assumption', 'Bank of Tanzania, Monthly Economic Review October 2026 (TZS per USD, end of period)', 'https://www.bot.go.tz/Publications/Regular/Monthly%20Economic%20Review/en/2026102918183001.pdf', '2026-10-31', 'Low case: flat dollar gold with the shilling weakening about 2% a year, as over 2018-2026 (annual average 2,264 in 2018 to 2,642 at the end of September 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TZ', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Employment and Labour Relations Act 2004 provides severance pay on termination, but the official text could not be read (TanzLII and ILO NATLEX refused access), so the rule and whether it applies at retirement are not confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TZ', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No official typical cost of a major private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TZ', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premiums per 100,000 TZS of cover by age were found from the regulator or another public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TZ', 1, 'inflation_cpi', 0.043, NULL, 'sourced', 'National Bureau of Statistics (NBS), Consumer Price Index, September 2026', 'https://www.nbs.go.tz/statistics/topic/consumer-price-index-2026', '2026-09-30', 'Annual headline inflation unchanged at 4.3% in September 2026 (August 4.3%); the Bank of Tanzania Monthly Economic Review of October 2026 gives the same figure. Mainland Tanzania series.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TZ', 1, 'inflation_projection', 0.04, NULL, 'assumption', 'Bank of Tanzania inflation target 3-5% (Monetary Policy Report, October 2026); World Bank CPI inflation 2021-2025', 'https://www.bot.go.tz/Publications/Regular/Monetary%20policy%20report/en/2026101312511941.pdf', '2026-10-31', 'The Bank of Tanzania targets 3-5% and inflation stayed between about 3% and 4.4% over 2021-2026, so the 4% centre of the band is used for long-range plans.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TZ', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Individual term assurance is sold (TIRA reports term assurance claims in 2025), but no published premium rates per 1,000 TZS of cover by age were found from the regulator or another public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TZ', 1, 'life_claim_settlement_rate', 0.863, NULL, 'sourced', 'Tanzania Insurance Regulatory Authority (TIRA), Annual Insurance Market Performance Report 2025, Table 3.11', 'https://www.tira.go.tz/uploads/documents/en-Annual%20Insurance%20Market%20Performance%20Report%202025.pdf', '2025-12-31', 'Life insurers paid TZS 100.3 billion of TZS 116.3 billion claims reported in 2025 (86.3%; 85.8% in 2024); individual life 99.9%, group life 83.6%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TZ', 1, 'life_expectancy', 67.212, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN)', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=TZ', '2024-12-31', '67.2 years in 2024 (men 64.4, women 70.0), the latest World Bank year (older than 2025); UN WPP 2024 gives 67.6 for 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TZ', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":17.9,"men":16.1,"women":19.7},{"age":65,"total":14.9,"men":13.1,"women":16.4},{"age":70,"total":11.9,"men":10.4,"women":13.4},{"age":80,"total":7.2,"men":6,"women":8.3}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/united-republic-of-tanzania/', '2026-07-01', 'Secondary source of UN WPP 2024 (medium variant) for 2026; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TZ', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'See old_age_allowance_monthly: no Mainland scheme was found and the Zanzibar scheme''s rules could not be read from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TZ', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension for Mainland Tanzania was found; Zanzibar has its own universal pension for older residents, but its current amount could not be read from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TZ', 1, 'oop_health_share', 0.2793, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=TZ', '2023-12-31', '27.9% in 2023, the latest year (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TZ', 1, 'policy_rate', 0.0625, NULL, 'sourced', 'Bank of Tanzania, Monetary Policy Report October 2026: MPC decision of 7 October 2026', 'https://www.bot.go.tz/Publications/Regular/Monetary%20policy%20report/en/2026101312511941.pdf', '2026-10-07', 'The MPC kept the Central Bank Rate at 6.25% for the quarter ending December 2026, after raising it from 5.75% in July 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TZ', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":60,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'National Social Security Fund Act (Cap. 50 R.E. 2023) and NSSF old-age pension page', 'https://www.nssf.go.tz/benefits/old-age-pension', '2026-10-31', 'Compulsory for private employees: 20% of wages (employee up to 10%). Pension at 60 (early from 55) after 180 monthly contributions: 1/580 x months x average of best 3 of last 10 years'' pay, 33% commuted as a lump sum (x12.5) and 67% paid monthly; minimum 40% of the minimum wage, maximum 72.5%. Benefits are adjusted after actuarial valuations (Act s.50), not indexed by law; tax on pensions not confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TZ', 1, 'retirement_accumulation_return_base', 0.085, NULL, 'assumption', 'Bank of Tanzania Treasury bond auctions (9.5-10.7%) and equity base 10%', 'https://www.bot.go.tz/TBonds', '2026-10-31', 'Base case: a balanced mix of Treasury bonds, deposits and local shares, between the safe and equity base cases.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TZ', 1, 'retirement_accumulation_return_high', 0.11, NULL, 'assumption', 'Bank of Tanzania 10-year bond 10.69% and DSEI (Trading Economics)', 'https://tradingeconomics.com/tanzania/stock-market', '2026-10-31', 'High case: more long bonds and shares with yields staying near current levels.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TZ', 1, 'retirement_accumulation_return_low', 0.06, NULL, 'assumption', 'Bank of Tanzania deposit and bill rates (2026)', 'https://www.bot.go.tz/Publications/Regular/Monthly%20Economic%20Review/en/2026102918183001.pdf', '2026-10-31', 'Low case: mostly deposits and bills with a small, weak equity share.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TZ', 1, 'retirement_age_default', 60, NULL, 'sourced', 'National Social Security Fund Act (Cap. 50 R.E. 2023), section 2: pensionable age', 'https://www.nssf.go.tz/uploads/publications/en-1771921274-NSSF%20ACT%20CAP%2050%20RE.%202023.pdf', '2026-10-31', 'Pensionable age is 60 for men and women; early retirement pension from 55 with at least 180 monthly contributions (NSSF old-age pension page).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TZ', 1, 'retirement_age_government', 60, NULL, 'sourced', 'Public Service Social Security Fund (PSSSF), retirement benefit page (PSSSF Act No. 2 of 2018, section 25)', 'https://www.psssf.go.tz/benefits/retirement-benefit', '2026-10-31', 'Compulsory retirement at 60, voluntary from 55, unless the terms of employment set another age.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TZ', 1, 'retirement_return_base', 0.055, NULL, 'assumption', 'Bank of Tanzania 364-day Treasury bill 6.13% (21 October 2026), 5.5% after 10% withholding', 'https://www.bot.go.tz/TBills', '2026-10-31', 'Base case: kept at the after-tax one-year bill rate, the lower of the two safe one-year rates (one-year deposits give 8.6% after tax).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TZ', 1, 'retirement_return_high', 0.08, NULL, 'assumption', 'Bank of Tanzania 12-month deposit rate 9.59% (September 2026) and 5-year bond 9.53%', 'https://www.bot.go.tz/Publications/Regular/Monthly%20Economic%20Review/en/2026102918183001.pdf', '2026-10-31', 'High case: one-year deposits and medium Treasury bonds after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TZ', 1, 'retirement_return_low', 0.04, NULL, 'assumption', 'Bank of Tanzania 364-day bill 6.13% (21 October 2026) and savings rates, after 10% withholding', 'https://www.bot.go.tz/TBills', '2026-10-31', 'Low case: short bills and deposits after tax if yields stay low.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TZ', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate or retail savings bond for individuals was found; individuals buy ordinary Treasury bills and bonds at Bank of Tanzania auctions.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TZ', 1, 'savings_account_rate', 0.0295, NULL, 'sourced', 'Bank of Tanzania, Monthly Economic Review October 2026, Table A4 (savings deposit rate)', 'https://www.bot.go.tz/Publications/Regular/Monthly%20Economic%20Review/en/2026102918183001.pdf', '2026-09-30', 'Average savings deposit rate in shillings, 2.95% in September 2026 (2.77% in August).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TZ', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":17.96},{"year":2040,"value":16.39},{"year":2065,"value":10.1}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/united-republic-of-tanzania/2040/', '2025-12-31', '100 / old-age dependency ratio: 5.57 (2025, World Bank), 6.1 (2040) and 9.9 (2065, populationpyramid.net/united-republic-of-tanzania/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TZ', 1, 'tax_bank_interest', 0.1, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Tanzania, withholding taxes (interest, residents)', 'https://taxsummaries.pwc.com/tanzania/corporate/withholding-taxes', '2026-09-09', '10% withholding on interest paid to residents; for individuals it is a final tax unless the interest is business income (PwC individual income determination page). Page last reviewed 9 September 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TZ', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate exists. The tax treatment of interest on Treasury bonds for individuals could not be confirmed from an official source; PwC mentions relief only for listed corporate, municipal and exchange-listed bonds of 3 years or more.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TZ', 1, 'tbill_91d_rate', 0.036357, NULL, 'sourced', 'Bank of Tanzania, Treasury bills auction No. 1209 held on 21 October 2026 (auction summary)', 'https://www.bot.go.tz/TBills', '2026-10-21', 'Weighted average yield 3.6357% on 91-day bills; 35 days 3.54%, 182 days 5.57%, 364 days 6.13%. Short bill yields fell from about 6.8% in September 2025 as liquidity rose.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TZ', 1, 'tbond_10y_rate', 0.106924, NULL, 'sourced', 'Bank of Tanzania, 11.25% 10-year Treasury bond, auction No. 711 reopened on 2 September 2026 (auction summary)', 'https://www.bot.go.tz/TBonds', '2026-09-02', 'Weighted average yield to maturity 10.6924% (coupon 11.25%, matures 23 July 2036); the Monthly Economic Review gives 10.69% for September 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('TZ', 1, 'tbond_5y_rate', 0.095275, NULL, 'sourced', 'Bank of Tanzania, 10.25% 5-year Treasury bond, auction No. 700 reopened on 16 September 2026 (auction summary)', 'https://www.bot.go.tz/TBonds', '2026-09-16', 'Weighted average yield to maturity 9.5275% (coupon 10.25%, matures 30 April 2031).', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('UA', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"UA","iso3":"UKR","nameEn":"Ukraine","nameNative":"Україна","region":"europe_central_asia","languages":["uk","ru","en"],"currency":{"code":"UAH","symbol":"₴","decimals":2,"compact":"intl","usdRate":{"value":45.5293,"status":"sourced","sourceName":"National Bank of Ukraine (NBU), official hryvnia exchange rate (open data API)","sourceUrl":"https://bank.gov.ua/NBUStatService/v1/statdirectory/exchange?valcode=USD&date=20261030&json","asOf":"2026-10-30","note":"Official rate UAH 45.5293 per US dollar for 30 October 2026 (45.3526 set for 2 November). World Bank 2025 average 41.69."}},"instruments":{"savings_account":{"available":true,"localName":"Вклад на вимогу","localNameEn":"Demand deposit","sourceUrl":"https://bank.gov.ua/NBUStatService/v1/statdirectory/mir?date=20261001&json"},"fdr_3m":{"available":true,"localName":"Строковий депозит (3 місяці)","localNameEn":"Term deposit (3 months)"},"fdr_1y":{"available":true,"localName":"Строковий депозит (12 місяців)","localNameEn":"Term deposit (1 year)","sourceUrl":"https://bank.gov.ua/NBUStatService/v1/statdirectory/mir?date=20261001&json"},"dps":{"available":true,"localName":"Депозит з поповненням","localNameEn":"Term deposit with top-ups","note":"No standard monthly recurring-deposit scheme; term deposits that accept top-ups are used for regular saving."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate; individuals buy ordinary government bonds (OVDP) through banks, brokers or the Diia app."},"tbill_91d":{"available":true,"localName":"Короткострокові ОВДП","localNameEn":"Short-term domestic government bonds (OVDP)","note":"Recent auctions offered bills of about 11 months rather than 3 months.","sourceUrl":"https://bank.gov.ua/NBU_ovdp?json"},"tbond_5y":{"available":true,"localName":"ОВДП","localNameEn":"Domestic government bonds (OVDP)","note":"The longest hryvnia bonds placed in October 2026 had about 3.3 years to maturity.","sourceUrl":"https://bank.gov.ua/NBU_ovdp?json"},"tbond_10y":{"available":false,"localName":null,"localNameEn":null,"note":"No 10-year hryvnia government bond is currently issued."},"equity_fund":{"available":true,"localName":"Інститути спільного інвестування","localNameEn":"Collective investment funds","note":"Local funds exist but the domestic stock market is very small; diversified global funds are hard to reach under wartime currency controls."},"gold":{"available":true,"localName":"Банківські метали (золоті злитки)","localNameEn":"Bank gold bars","note":"Legal to buy; banks sell gold bars (not re-checked in this research)."}},"institutions":{"centralBank":{"name":"National Bank of Ukraine (NBU)","url":"https://bank.gov.ua/en/"},"insuranceRegulator":{"name":"National Bank of Ukraine (insurance supervision since 2020)","url":"https://bank.gov.ua/en/"},"insuranceComplaints":{"name":"National Bank of Ukraine, financial consumer protection","url":"https://bank.gov.ua/en/consumer-protection"},"pensionScheme":{"name":"Pension Fund of Ukraine","url":"https://www.pfu.gov.ua/"},"oldAgeAllowance":{"name":"Pension Fund of Ukraine (state social assistance to persons without pension rights, Law No. 1727-IV)","url":"https://www.pfu.gov.ua/"},"publicHealthCover":{"name":"National Health Service of Ukraine (Programme of Medical Guarantees)","url":"https://nhsu.gov.ua/"},"depositInsurance":{"name":"Deposit Guarantee Fund","url":"https://www.fg.gov.ua/","note":"Full cover during martial law and three months after; UAH 600,000 per depositor per bank afterwards."},"statistics":{"name":"State Statistics Service of Ukraine","url":"https://www.ukrstat.gov.ua/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UA', 1, 'bank_deposit_avg_rate', 0.1031, NULL, 'sourced', 'National Bank of Ukraine open data, interest rates on new deposits of households (hryvnia, all maturities)', 'https://bank.gov.ua/NBUStatService/v1/statdirectory/mir?date=20261001&json', '2026-09-30', 'Weighted average on all new hryvnia household deposits including demand deposits, September 2026. The IMF-based series on Trading Economics gives 10.32% for July 2026; World Bank 2025 average 9.95%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UA', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap on credit card interest was found; NBU statistics report rates on new consumer loans to households but not a separate card rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UA', 1, 'deposit_insurance_limit', 600000, NULL, 'sourced', 'Minfin.com.ua news on the Deposit Guarantee Fund guarantee (deposit data at 1 April 2026)', 'https://minfin.com.ua/ua/2026/04/23/172505366/', '2026-04-01', 'Individuals'' deposits (including sole proprietors) are guaranteed in full while martial law lasts (extended again from 31 October 2026) and for three months after it ends; after that the cover per depositor per bank is UAH 600,000. Secondary source because fg.gov.ua refused the connection.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UA', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Banks offer term deposits that accept top-ups, but no official rate for a monthly recurring deposit was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UA', 1, 'equity_return_base', 0.11, NULL, 'assumption', 'Global equities about 7% a year in dollars plus expected hryvnia depreciation; 1-year OVDP 14.95% (NBU auction results)', 'https://bank.gov.ua/NBU_ovdp?json', '2026-10-31', 'Base case: a global index earning about 7% in dollars plus about 4% a year of hryvnia depreciation (inflation gap), below the tax-exempt 1-year OVDP yield plus 4 points.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UA', 1, 'equity_return_high', 0.16, NULL, 'assumption', 'Global equity record plus hryvnia depreciation', 'https://bank.gov.ua/NBUStatService/v1/statdirectory/exchange?valcode=USD&date=20261030&json', '2026-10-31', 'High case: strong global shares and a faster hryvnia depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UA', 1, 'equity_return_low', 0.05, NULL, 'assumption', 'No liquid local stock market; global equities in hryvnia terms (NBU USD rate 45.53)', 'https://bank.gov.ua/NBUStatService/v1/statdirectory/exchange?valcode=USD&date=20261030&json', '2026-10-31', 'The local exchange is tiny and illiquid, so equity returns are based on a global index in hryvnia; low case is weak global shares and a stable hryvnia.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UA', 1, 'fdr_1y_rate', 0.1183, NULL, 'sourced', 'National Bank of Ukraine open data, interest rates on new deposits of households (hryvnia, up to 1 year)', 'https://bank.gov.ua/NBUStatService/v1/statdirectory/mir?date=20261001&json', '2026-09-30', 'Weighted average rate on new hryvnia household deposits with original maturity up to 1 year in September 2026; 1-2 years 13.38%, over 2 years 14.86%. Interest is taxed at 23% (see tax_bank_interest).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UA', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'NBU statistics group new household term deposits only as up to 1 year, 1-2 years and over 2 years; no separate 3-month rate is published (up to 1 year: 11.83% in September 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UA', 1, 'fixed_income_return_base', 0.1, NULL, 'assumption', '1-year OVDP 14.95% (NBU auction 27 Oct 2026); 1-year deposits 9.1% after tax (NBU)', 'https://bank.gov.ua/NBU_ovdp?json', '2026-10-31', 'Base case: a mix of taxed deposits and tax-exempt OVDP earning about 2 points above the 8% inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UA', 1, 'fixed_income_return_high', 0.14, NULL, 'assumption', '1-year OVDP 14.95% and 3-year OVDP 16.5% (NBU auction results, Oct 2026)', 'https://bank.gov.ua/NBU_ovdp?json', '2026-10-31', 'High case: today''s high government bond yields persist.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UA', 1, 'fixed_income_return_low', 0.07, NULL, 'assumption', '1-year deposits 11.83% (9.1% after 23% tax, NBU, Sep 2026); inflation projection 8%', 'https://bank.gov.ua/NBUStatService/v1/statdirectory/mir?date=20261001&json', '2026-10-31', 'Low case: after-tax deposit returns fall slightly below inflation as rates come down.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UA', 1, 'goal_inflation_education', 0.12, NULL, 'assumption', 'NBU/State Statistics Service CPI: education +19.6% year on year (Sep 2026); inflation projection 8%', 'https://bank.gov.ua/NBUStatService/v1/statdirectory/inflation?period=m&date=202610&json', '2026-10-31', 'Education prices jumped 19.6% in the year to September 2026 (14.5% average over the year), so 12% is used, well above general inflation but below the latest spike.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UA', 1, 'goal_inflation_health', 0.08, NULL, 'assumption', 'NBU/State Statistics Service CPI: health +3.3% year on year (Sep 2026); inflation projection 8%', 'https://bank.gov.ua/NBUStatService/v1/statdirectory/inflation?period=m&date=202610&json', '2026-10-31', 'Health prices rose only 3.3% in the year to September 2026, below headline inflation, so medical costs are planned at the 8% general inflation assumption rather than above it.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UA', 1, 'gold_return_base', 0.08, NULL, 'assumption', 'Gold price history (Trading Economics); inflation gap between Ukraine (8% assumed) and the US (about 2-3%)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Base case: dollar gold rises about 4% a year and the hryvnia loses about 4% a year against the dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UA', 1, 'gold_return_high', 0.14, NULL, 'assumption', 'Gold price history (Trading Economics); hryvnia devaluations of 2014-2015 and 2022', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'High case: strong dollar gold plus a sharp hryvnia devaluation, as in 2014-2015 and 2022.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UA', 1, 'gold_return_low', 0.02, NULL, 'assumption', 'Gold USD 3,876/oz on 30 Oct 2026, down 3% on a year (Trading Economics); NBU USD rate 45.53', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Low case: flat dollar gold and only slight hryvnia depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UA', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'Labour Code of Ukraine, Article 44: severance pay (at least one month''s average earnings, more on some grounds) is due only on specific dismissal grounds, is not tied to years of service and is not paid on retirement; no statutory gratuity for private employees exists (protocol.ua/ua/kodeks_zakoniv_pro_pratsyu_ukraini_stattya_44/).', 1);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UA', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Programme of Medical Guarantees (NHSU) pays for listed hospital care; no official figure for the typical out-of-pocket cost of a major private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UA', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Voluntary health insurance is mostly bought by employers; no age-banded premium table per UAH 100,000 of cover was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UA', 1, 'inflation_cpi', 0.1, NULL, 'sourced', 'National Bank of Ukraine open data, consumer price indices (State Statistics Service data)', 'https://bank.gov.ua/NBUStatService/v1/statdirectory/inflation?period=m&date=202610&json', '2026-09-30', 'Consumer prices up 10.0% year on year in September 2026 (8.1% in August), released 9 October 2026; October figure due 10 November. World Bank 2025 average 12.7%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UA', 1, 'inflation_projection', 0.08, NULL, 'assumption', 'NBU 5% inflation target; IMF WEO path for Ukraine (8.9% 2026, 5.0% 2030); 2021-2025 average about 12%', 'https://www.imf.org/external/datamapper/api/v1/PCPIPCH/UKR', '2026-10-31', 'The NBU targets 5% and the IMF projects a return to 5% by 2030, but wartime inflation averaged about 12% in 2021-2025 and is 10% now, so 8% is used between the target and the record.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UA', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life cover is sold, but no published premium table per UAH 1,000 of cover by age from the NBU or another public source was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UA', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The NBU (insurance supervisor since 2020) publishes insurance market statistics, but no industry-wide life claim settlement ratio was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UA', 1, 'life_expectancy', 74.69, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=UA', '2024-12-31', '2024 (older than 2025): men 69.8, women 79.4. UN WPP gives 75.0 for 2026 (georank.org); wartime deaths make all figures uncertain.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UA', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":20.7,"men":17.6,"women":23},{"age":65,"total":17.2,"men":14.6,"women":18.9},{"age":70,"total":14,"men":12,"women":15.2},{"age":80,"total":8.8,"men":7.6,"women":9.3}]}', 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/ukraine', '2026-07-01', 'Remaining years computed from georank''s expected age at death by current age (UN WPP estimate for 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UA', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":65,"womenAge":65,"over90Monthly":null,"meansTested":true}', 'sourced', 'Ministry of Social Policy, standard information card for the state social assistance to persons without pension rights (Order No. 413-N of 30 October 2023)', 'https://center.diia.gov.ua/uploads/0/1777-priznacennna_derzavnoi_social_noi_dopomogi_osobam_aki_ne_maut_prava_na_pensiyu_ta_osobam_z_invalidnistu_docx.pdf', '2023-10-30', 'Paid to people who reached 65 (women born 1960 and earlier from a lower transitional age) who have no right to a pension, receive no pension, and are low-income (malozabezpecheni); the rule card is from 2023 (older than 2025) but the law is unchanged.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UA', 1, 'old_age_allowance_monthly', 778.5, NULL, 'sourced', 'Law of Ukraine No. 1727-IV on state social assistance to persons without pension rights, Article 6 (30% of the subsistence minimum for persons unable to work, UAH 2,595 in 2026)', 'https://protocol.ua/ua/pro_dergavnu_sotsialnu_dopomogu_osobam_yaki_ne_mayut_prava_na_pensiyu_ta_osobam_z_invalidnistyu_stattya_6/', '2026-01-01', 'For people who reached 65 without a pension right (and without disability) the assistance is 30% of the subsistence minimum for persons unable to work, which is UAH 2,595 in 2026, so UAH 778.50 a month; news reports (Novyny.LIVE, citing the Pension Fund) give the same 778.50. Some reports describe a top-up to the subsistence minimum for families with very low income, which was not confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UA', 1, 'oop_health_share', 0.4529, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=UA', '2021-12-31', 'Latest available year is 2021, before the full-scale invasion (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UA', 1, 'policy_rate', 0.165, NULL, 'sourced', 'National Bank of Ukraine open data, NBU key policy rate', 'https://bank.gov.ua/NBUStatService/v1/statdirectory/key?date=20261030&json', '2026-10-30', 'Key policy rate raised from 16% to 16.5% at the 29 October 2026 decision (Trading Economics); overnight loans 20.5%, overnight certificates of deposit 16.5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UA', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":60,"nomineeUntilAge":null,"inflationLinked":true,"taxFree":null}', 'sourced', 'Pension Fund of Ukraine, conditions for an old-age pension and pension indexation', 'https://www.pfu.gov.ua/33642-umovy-pryznachennya/', '2026-01-01', 'Compulsory pay-as-you-go solidarity pension funded by the unified social contribution. Pension from 60 with 33 years of record in 2026 (35 from 2028), 63 or 65 with less. Pensions are indexed each year by a coefficient of half the previous year''s CPI growth plus half the 3-year wage growth (pfu.gov.ua/34730-indeksatsiya-pensij-3/). Tax treatment not checked.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UA', 1, 'retirement_accumulation_return_base', 0.105, NULL, 'assumption', 'Fixed income base 10%; equity base 11%', 'https://bank.gov.ua/NBU_ovdp?json', '2026-10-31', 'Base case: roughly half global shares at 11% and half deposits and OVDP at 10%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UA', 1, 'retirement_accumulation_return_high', 0.15, NULL, 'assumption', 'Fixed income high 14%; equity high 16%', 'https://bank.gov.ua/NBU_ovdp?json', '2026-10-31', 'High case for a growth-leaning balanced mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UA', 1, 'retirement_accumulation_return_low', 0.06, NULL, 'assumption', 'Fixed income low 7%; equity low 5%', 'https://bank.gov.ua/NBU_ovdp?json', '2026-10-31', 'Low case for a balanced mix if both shares and deposits lag inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UA', 1, 'retirement_age_default', 60, NULL, 'sourced', 'Pension Fund of Ukraine, conditions for an old-age pension', 'https://www.pfu.gov.ua/33642-umovy-pryznachennya/', '2026-01-01', 'Pension at 60 with at least 33 years of insurance record in 2026, rising one year each year to 35 years from 2028 (Law 1058-IV, Article 26); otherwise at 63 with at least 23 years in 2026 (25 from 2028) or at 65 with at least 15 years. Same ages for men and women; someone born after 1975 reaches 60 after 2028 and needs 35 years for a pension at 60.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UA', 1, 'retirement_age_government', 65, NULL, 'sourced', 'Law of Ukraine No. 889-VIII on Civil Service, Article 83(1)(7)', 'https://protocol.ua/ua/pro_dergavnu_slugbu_vid_10_12_2015_889_viii_stattya_83/', '2026-10-31', 'Civil service ends on retirement or on reaching 65 unless a law provides otherwise; service may be extended yearly with consent up to 70. The pension itself follows the general rules (from 60 with the required insurance record). Read from a legal database copy because zakon.rada.gov.ua refused the connection.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UA', 1, 'retirement_return_base', 0.095, NULL, 'assumption', '1-year deposits 11.83% (9.1% after 23% tax, NBU); 1-year OVDP 14.95% tax-exempt (NBU auction, 27 Oct 2026)', 'https://bank.gov.ua/NBU_ovdp?json', '2026-10-31', 'Base case below the tax-exempt 1-year OVDP yield and close to today''s after-tax deposit rate, allowing for rates falling as inflation comes down.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UA', 1, 'retirement_return_high', 0.13, NULL, 'assumption', 'OVDP 14.95-16.5% (NBU auction results, Oct 2026)', 'https://bank.gov.ua/NBU_ovdp?json', '2026-10-31', 'High case: a retiree keeps earning rates close to today''s government bond yields.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UA', 1, 'retirement_return_low', 0.07, NULL, 'assumption', '1-year deposits 9.1% after tax (NBU, Sep 2026); inflation projection 8%', 'https://bank.gov.ua/NBUStatService/v1/statdirectory/mir?date=20261001&json', '2026-10-31', 'Low case: a retiree''s deposits earn slightly less than inflation after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UA', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Ukraine has no separate government savings certificate; individuals buy ordinary domestic government bonds (OVDP) through banks, brokers or the Diia app (1-year OVDP 14.95% at the 27 October 2026 auction).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UA', 1, 'savings_account_rate', 0.0277, NULL, 'sourced', 'National Bank of Ukraine open data, interest rates on new deposits of households (hryvnia, demand)', 'https://bank.gov.ua/NBUStatService/v1/statdirectory/mir?date=20261001&json', '2026-09-30', 'Weighted average rate on new hryvnia demand deposits of households in September 2026 (reporting date 1 October).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UA', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":3.55},{"year":2040,"value":2.73},{"year":2065,"value":1.52}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/ukraine/2040/', '2025-12-31', '100 / old-age dependency ratio: 28.18 (2025, World Bank), 36.6 (2040) and 65.9 (2065, populationpyramid.net/ukraine/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UA', 1, 'tax_bank_interest', 0.23, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Ukraine, Individual, Income determination (last reviewed 30 June 2026)', 'https://taxsummaries.pwc.com/ukraine/individual/income-determination', '2026-06-30', 'Bank interest is subject to 18% personal income tax plus the 5% military tax, withheld by the bank.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UA', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate exists. PwC lists an exemption for interest from securities issued by certain state bodies, which is understood to cover OVDP, but the exact Tax Code provision was not read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UA', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 3-month OVDP was placed at the September-October 2026 auctions (NBU auction results); the shortest regular paper was about 11 months at 14.95-15.18%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UA', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 10-year hryvnia government bond is issued or quoted.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UA', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 5-year OVDP was placed recently; the longest hryvnia bonds at the October 2026 auctions matured in 2029-2030 (about 3.3 years) at 16.4-16.5% (NBU auction results, bank.gov.ua/NBU_ovdp).', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('UG', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"UG","iso3":"UGA","nameEn":"Uganda","nameNative":"Uganda","region":"sub_saharan_africa","languages":["lg","en","sw","nyn"],"currency":{"code":"UGX","symbol":"USh","decimals":0,"compact":"intl","usdRate":{"value":4259.05,"status":"sourced","sourceName":"Bank of Uganda, opening indicative exchange rates (interbank middle rate, US dollar)","sourceUrl":"https://bou.or.ug/uploads/OPENING_RATES_13106e5bea.xlsx","asOf":"2026-10-30","note":"UGX 4,259.05 per dollar (interbank middle rate). The Bank of Uganda file is headed as the opening rates for Monday 2 November 2026, published after the last trading day of October (Friday 30 October), so asOf is 30 October; the file is overwritten daily. The shilling fell about 15% from the World Bank 2025 average of 3,603. CLDR gives ''UGX'' as symbol; ''USh'' is the local abbreviation."}},"instruments":{"savings_account":{"available":true,"localName":null,"localNameEn":"Savings account","note":"No dated official average rate was found."},"fdr_3m":{"available":true,"localName":null,"localNameEn":"Fixed deposit","note":"No official tenor-specific average rate was found."},"fdr_1y":{"available":true,"localName":null,"localNameEn":"Fixed deposit, 1 year","note":"No official tenor-specific average rate was found."},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No standard monthly recurring deposit product with published rates was found."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate for individuals; individuals can bid non-competitively for Treasury bills and bonds."},"tbill_91d":{"available":true,"localName":null,"localNameEn":"Treasury bills","note":"Bank of Uganda auctions 91, 182 and 364-day bills about every two weeks; non-competitive bids from individuals are accepted.","sourceUrl":"https://bou.or.ug/uploads/Press_Release_Report_for_the_91_Days_182_Days_364_Days_T_Bills_Auction_21_OCT_2026_c8a80b0a6b.pdf"},"tbond_5y":{"available":true,"localName":null,"localNameEn":"Treasury bonds","note":"2 to 25 year bonds re-opened at Bank of Uganda auctions.","sourceUrl":"https://bou.or.ug/uploads/PRESS_RELEASE_RESULTS_OF_TREASURY_BOND_AUCTION_Wednesday_28_October_2026_5792fc8721.pdf"},"tbond_10y":{"available":true,"localName":null,"localNameEn":"Treasury bonds","note":"The 10-year benchmark (due May 2037) was re-opened on 7 October 2026.","sourceUrl":"https://bou.or.ug/uploads/Press_Release_Report_for_the_3_YR_10_YR_20_YR_T_Bonds_07_OCT_2026_2456c7d1cb.pdf"},"equity_fund":{"available":true,"localName":null,"localNameEn":"Collective investment schemes (unit trusts)","note":"Unit trusts are licensed by the Capital Markets Authority."},"gold":{"available":true,"localName":null,"localNameEn":"Gold","note":"Gold is mainly bought as jewellery; no official retail market for investment bars or coins was confirmed."}},"institutions":{"centralBank":{"name":"Bank of Uganda","url":"https://www.bou.or.ug/"},"insuranceRegulator":{"name":"Insurance Regulatory Authority of Uganda (IRA)","url":"https://ira.go.ug/"},"insuranceComplaints":{"name":"Insurance Regulatory Authority of Uganda, complaints portal","url":"https://iracomplaints.go.ug/"},"pensionScheme":{"name":"National Social Security Fund (NSSF Uganda)","url":"https://www.nssfug.org/benefits-products/benefits/benefits-age/","note":"Retirement schemes are supervised by the Uganda Retirement Benefits Regulatory Authority; public servants have a separate government pension."},"oldAgeAllowance":{"name":"Senior Citizens'' Grant, Expanded Social Protection programme (Ministry of Gender, Labour and Social Development)","url":"https://socialprotection.go.ug/"},"publicHealthCover":null,"depositInsurance":{"name":"Deposit Protection Fund of Uganda (DPF)","url":"https://dpf.or.ug/faqs/"},"statistics":{"name":"Uganda Bureau of Statistics (UBOS)","url":"https://www.ubos.org/","note":"The site failed a security certificate check on 3 November 2026."}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UG', 1, 'bank_deposit_avg_rate', 0.1024, NULL, 'sourced', 'Trading Economics, Uganda deposit interest rate, citing the Bank of Uganda, August 2026', 'https://tradingeconomics.com/uganda/deposit-interest-rate', '2026-08-31', 'Secondary source: 10.24% in August 2026, down from 10.82% in July (before the October 2026 rate rise); World Bank FR.INR.DPST gives 9.38% for 2018.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UG', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'Uganda has no legal cap on bank lending rates and no official credit card rate was found; the Bank of Uganda website shows an undated average lending rate of 18.3%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UG', 1, 'deposit_insurance_limit', 10000000, NULL, 'sourced', 'Deposit Protection Fund of Uganda, FAQs', 'https://dpf.or.ug/faqs/', '2026-10-31', 'UGX 10 million per depositor per institution (per depositor, not per account); the limit was raised from UGX 3 million in 2019 and a review is targeted for 1 January 2027 (DPF news, 28 August 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UG', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No industry-wide rate for a monthly recurring deposit product was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UG', 1, 'equity_return_base', 0.12, NULL, 'assumption', 'Bank of Uganda 364-day bill 14.50% (21 October 2026), about 11.6% after 20% withholding; ALSI history', 'https://bou.or.ug/uploads/Press_Release_Report_for_the_91_Days_182_Days_364_Days_T_Bills_Auction_21_OCT_2026_c8a80b0a6b.pdf', '2026-10-31', 'Base case: held near the after-tax one-year bill rate rather than 4 points above it, because the local index has a weak 10-year record despite a 74.6% rise in the year to 29 October 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UG', 1, 'equity_return_high', 0.17, NULL, 'assumption', 'Trading Economics, ALSI 2,594.93 on 29 October 2026 (+74.6% over the year)', 'https://tradingeconomics.com/uganda/stock-market', '2026-10-31', 'High case: the 2025-2026 re-rating continues with dividend yields of several percent.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UG', 1, 'equity_return_low', 0.06, NULL, 'assumption', 'Trading Economics, Uganda Securities Exchange All Share Index (ALSI)', 'https://tradingeconomics.com/uganda/stock-market', '2026-10-31', 'Low case: the local index was weak for most of the decade before 2025, so a flat-price decade plus dividends gives about 6%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UG', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No official average 1-year term deposit rate was found (the Bank of Uganda''s interest rate statistics are published through an interactive portal that could not be read).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UG', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No official average 3-month term deposit rate was found (the Bank of Uganda''s interest rate statistics are published through an interactive portal that could not be read).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UG', 1, 'fixed_income_return_base', 0.09, NULL, 'assumption', 'Trading Economics deposit rate 10.24% (8.7% after tax); Bank of Uganda 364-day bill 14.50% (11.6% after 20% withholding)', 'https://bou.or.ug/uploads/Press_Release_Report_for_the_91_Days_182_Days_364_Days_T_Bills_Auction_21_OCT_2026_c8a80b0a6b.pdf', '2026-10-31', 'Base case: between term deposits and one-year Treasury bills after tax, allowing for yields to fall back after the 2026 rate rise.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UG', 1, 'fixed_income_return_high', 0.12, NULL, 'assumption', 'Bank of Uganda bond auctions (10-year 16.85%, 15-25 years 17.9-18.5%; 10% withholding on 10+ year bonds)', 'https://bou.or.ug/uploads/Press_Release_Report_for_the_3_YR_10_YR_20_YR_T_Bonds_07_OCT_2026_2456c7d1cb.pdf', '2026-10-31', 'High case: long Treasury bonds held to maturity after 10% withholding, allowing for lower future yields.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UG', 1, 'fixed_income_return_low', 0.04, NULL, 'assumption', 'Bank of Uganda undated domestic deposit rate 2.83%; Trading Economics deposit rate 10.24% (August 2026)', 'https://tradingeconomics.com/uganda/deposit-interest-rate', '2026-10-31', 'Low case: a mix of low-paying savings accounts and term deposits after 15% withholding.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UG', 1, 'goal_inflation_education', 0.07, NULL, 'assumption', 'UBOS CPI via Trading Economics (education CPI index 161.58 in September to 164.32 in October 2026); inflation assumption 5.5%', 'https://tradingeconomics.com/uganda/inflation-cpi', '2026-10-31', 'No current education inflation rate could be read, but the education price index rose about 1.7% in October 2026 alone and school fees are raised regularly, so 1.5 points above the 5.5% inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UG', 1, 'goal_inflation_health', 0.065, NULL, 'assumption', 'UBOS CPI via Trading Economics (health CPI index 140.59 in October 2026); inflation assumption 5.5%', 'https://tradingeconomics.com/uganda/inflation-cpi', '2026-10-31', 'No current health inflation rate could be read, so medical costs are planned one point above the 5.5% inflation assumption, since private care and drug prices follow imports and the exchange rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UG', 1, 'gold_return_base', 0.075, NULL, 'assumption', 'Bank of Uganda exchange rates; inflation target 5%', 'https://bou.or.ug/uploads/OPENING_RATES_13106e5bea.xlsx', '2026-10-31', 'Base case: a dollar gold trend of about 4% a year plus shilling depreciation of about 3-4% a year, in line with the inflation gap to the US.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UG', 1, 'gold_return_high', 0.14, NULL, 'assumption', 'Trading Economics, USD/UGX (shilling down 22.7% in the year to November 2026)', 'https://tradingeconomics.com/uganda/currency', '2026-10-31', 'High case: strong dollar gold together with further depreciation episodes like 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UG', 1, 'gold_return_low', 0.02, NULL, 'assumption', 'Bank of Uganda opening exchange rates (UGX 4,259 per dollar, 30 October 2026 close); World Bank 2025 average 3,603', 'https://bou.or.ug/uploads/OPENING_RATES_13106e5bea.xlsx', '2026-10-31', 'Low case: flat dollar gold with the shilling recovering part of its 2026 fall.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UG', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Employment Act 2006 provides severance allowance on termination, but no official text with a fixed number of days per year of service was read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UG', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No official typical cost of a major private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UG', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premiums per 100,000 UGX of cover by age were found from the regulator or another public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UG', 1, 'inflation_cpi', 0.058, NULL, 'sourced', 'Trading Economics, citing the Uganda Bureau of Statistics (UBOS) consumer price index, October 2026', 'https://tradingeconomics.com/uganda/inflation-cpi', '2026-10-31', 'Secondary source (the UBOS site failed a security certificate check): annual headline inflation 5.8% in October 2026, up from 4.6% in September (the Bank of Uganda MPS FAQ of October 2026 confirms 4.6% for September); core 4.4%, food 7.5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UG', 1, 'inflation_projection', 0.055, NULL, 'assumption', 'Bank of Uganda core inflation target 5%; Monetary Policy Statement October 2026 (headline projected at 7.0-7.5% over the next 12 months)', 'https://bou.or.ug/uploads/FA_Qs_October_2026_49a1f5323d.pdf', '2026-10-31', 'The Bank of Uganda targets 5% core inflation and inflation averaged about 4.3% in 2021-2025, but the 2026 shilling depreciation and fuel prices push the next year to 7%+, so 5.5% is used for long-range plans.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UG', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published indicative term-life premium rates per 1,000 UGX of cover from the regulator or another public source were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UG', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Insurance Regulatory Authority of Uganda market report could not be downloaded and no industry-wide life claim settlement ratio was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UG', 1, 'life_expectancy', 68.487, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN)', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=UG', '2024-12-31', '68.5 years in 2024 (men 65.5, women 71.4), the latest World Bank year (older than 2025); UN WPP 2024 gives 68.9 for 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UG', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":19,"men":17.2,"women":20.8},{"age":65,"total":16.1,"men":14.3,"women":17.6},{"age":70,"total":13.2,"men":11.7,"women":14.7},{"age":80,"total":8.3,"men":7.1,"women":9.4}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/uganda/', '2026-07-01', 'Secondary source of UN WPP 2024 (medium variant) for 2026; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there); figures are for the 5-year bands starting at each age.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UG', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Expanded Social Protection programme site says the Senior Citizens'' Grant starts with people aged 80 and above, but does not say whether it is means-tested or give current rules in full, so the eligibility row is left missing.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UG', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'Uganda pays a Senior Citizens'' Grant to older persons (starting at age 80, to be lowered towards 65, 60 in Karamoja, per the Expanded Social Protection programme), but its current monthly amount could not be read from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UG', 1, 'oop_health_share', 0.3217, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=UG', '2023-12-31', '32.2% in 2023, the latest year (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UG', 1, 'policy_rate', 0.12, NULL, 'sourced', 'Bank of Uganda, Monetary Policy Statement FAQs October 2026; money market report of 29 October 2026 (CBR 12.00%, effective 14 October 2026)', 'https://bou.or.ug/uploads/MM_29_October_2026_f010b202a0.pdf', '2026-10-14', 'A special MPC meeting raised the Central Bank Rate from 9.75% to 12.0% with effect from 14 October 2026; the cash reserve requirement rose from 11% to 13.5% on 24 September 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UG', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":55,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'National Social Security Fund (NSSF Uganda), age benefit; PwC Tax Summaries (contribution rates)', 'https://www.nssfug.org/benefits-products/benefits/benefits-age/', '2026-10-31', 'Compulsory provident fund for private employees: 5% of gross pay from the employee and 10% from the employer (PwC, reviewed 22 October 2026). The age benefit is paid at 55 as savings plus credited interest (13.5% for FY 2024/25), not as an indexed pension; tax treatment not confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UG', 1, 'retirement_accumulation_return_base', 0.105, NULL, 'assumption', 'Bank of Uganda bond auctions; NSSF declared 13.5% interest for FY 2024/25', 'https://www.nssfug.org/benefits-products/benefits/benefits-age/', '2026-10-31', 'Base case: a balanced mix of Treasury bonds, deposits and local shares, below NSSF''s recent credited rates because yields and the shilling were unusually volatile in 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UG', 1, 'retirement_accumulation_return_high', 0.14, NULL, 'assumption', 'Bank of Uganda 15-25 year bond auctions (17.9-18.5%, 28 October 2026)', 'https://bou.or.ug/uploads/PRESS_RELEASE_RESULTS_OF_TREASURY_BOND_AUCTION_Wednesday_28_October_2026_5792fc8721.pdf', '2026-10-31', 'High case: more long bonds and shares with yields staying near current levels.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UG', 1, 'retirement_accumulation_return_low', 0.07, NULL, 'assumption', 'Bank of Uganda bill and bond auctions (October 2026); NSSF interest 13.5% for FY 2024/25', 'https://www.nssfug.org/benefits-products/benefits/benefits-age/', '2026-10-31', 'Low case: mostly deposits and bills with a small, weak equity share.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UG', 1, 'retirement_age_default', 55, NULL, 'sourced', 'National Social Security Fund (NSSF Uganda), age benefit', 'https://www.nssfug.org/benefits-products/benefits/benefits-age/', '2026-10-31', 'The NSSF age benefit is paid to members who reach the retirement age of 55, whether or not still employed; a withdrawal benefit is available from 50 after a year out of work. NSSF is a provident fund, not an annuity.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UG', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'The public service retirement age could not be confirmed from an official source (the Public Service Pensions Act and Standing Orders were not read).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UG', 1, 'retirement_return_base', 0.08, NULL, 'assumption', 'Trading Economics deposit rate 10.24% (August 2026), 8.7% after 15% withholding; 364-day bill 11.6% after tax', 'https://tradingeconomics.com/uganda/deposit-interest-rate', '2026-10-31', 'Base case: kept below the after-tax deposit rate (8.7%), the lower of the two safe one-year rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UG', 1, 'retirement_return_high', 0.11, NULL, 'assumption', 'Bank of Uganda 364-day bill 14.50% and 10-year bond 16.85% (October 2026)', 'https://bou.or.ug/uploads/Press_Release_Report_for_the_91_Days_182_Days_364_Days_T_Bills_Auction_21_OCT_2026_c8a80b0a6b.pdf', '2026-10-31', 'High case: Treasury bills and long bonds bought directly at auction, after withholding.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UG', 1, 'retirement_return_low', 0.06, NULL, 'assumption', 'Trading Economics deposit rate 10.24% (August 2026), 8.7% after 15% withholding', 'https://tradingeconomics.com/uganda/deposit-interest-rate', '2026-10-31', 'Low case: term deposits after tax with lower rates in future.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UG', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate or retail savings bond for individuals was found; individuals can bid non-competitively in the Bank of Uganda Treasury bill and bond auctions.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UG', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No dated official average savings-account rate was found; the Bank of Uganda website shows an undated ''domestic deposit rate'' of 2.83% without saying which deposits it covers.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UG', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":24.53},{"year":2040,"value":18.87},{"year":2065,"value":8.13}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/uganda/2040/', '2025-12-31', '100 / old-age dependency ratio: 4.08 (2025, World Bank), 5.3 (2040) and 12.3 (2065, populationpyramid.net/uganda/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UG', 1, 'tax_bank_interest', 0.15, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Uganda, withholding taxes (interest paid to residents)', 'https://taxsummaries.pwc.com/uganda/corporate/withholding-taxes', '2026-10-22', '15% withholding on interest paid to residents (bank interest is not among the exceptions); government securities carry 20% (under 10 years) or 10% (10 years or more). Page last reviewed 22 October 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UG', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate exists; for reference, PwC lists 20% withholding on interest from government securities of under 10 years and 10% for 10 years or more.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UG', 1, 'tbill_91d_rate', 0.11733, NULL, 'sourced', 'Bank of Uganda, results of Treasury bills auction No. 1236, 21 October 2026', 'https://bou.or.ug/uploads/Press_Release_Report_for_the_91_Days_182_Days_364_Days_T_Bills_Auction_21_OCT_2026_c8a80b0a6b.pdf', '2026-10-21', 'Effective yield 11.733% on 91-day bills (money market yield 11.249%, discount rate 10.942%); 182 days 13.850%, 364 days 14.502%. Yields jumped after the October 2026 policy rate rise (91 days 10.06% on 14 October).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UG', 1, 'tbond_10y_rate', 0.1685, NULL, 'sourced', 'Bank of Uganda, results of Treasury bond auction of 7 October 2026 (10-year re-opening, 16.000% due 14 May 2037)', 'https://bou.or.ug/uploads/Press_Release_Report_for_the_3_YR_10_YR_20_YR_T_Bonds_07_OCT_2026_2456c7d1cb.pdf', '2026-10-07', 'Yield at cut-off price 16.850%; secondary-market bid/ask for 10 years averaged 17.19/16.59% in the week to 21 October 2026 (Bank of Uganda financial news report).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UG', 1, 'tbond_5y_rate', 0.168, NULL, 'sourced', 'Bank of Uganda, results of Treasury bond auction of 28 October 2026 (5-year re-opening, 15.000% due 20 May 2032)', 'https://bou.or.ug/uploads/PRESS_RELEASE_RESULTS_OF_TREASURY_BOND_AUCTION_Wednesday_28_October_2026_5792fc8721.pdf', '2026-10-28', 'Yield at cut-off price 16.800% for the 5-year benchmark; 2-year 16.000%, 15-year 17.925%, 25-year 18.475%.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('US', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"US","iso3":"USA","nameEn":"United States","nameNative":"United States","region":"north_america","languages":["en","es","zh","fr","vi"],"currency":{"code":"USD","symbol":"$","decimals":2,"compact":"intl","usdRate":{"value":1,"status":"sourced","sourceName":"World Bank WDI PA.NUS.FCRF","sourceUrl":"https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=US","asOf":"2025-12-31","note":"The US dollar is the reference currency: 1 by definition."}},"instruments":{"savings_account":{"available":true,"localName":"Savings account","note":"National average rates are low; online high-yield savings and money market accounts pay close to Treasury bill rates. FDIC-insured to USD 250,000.","sourceUrl":"https://www.fdic.gov/national-rates-and-rate-caps"},"fdr_3m":{"available":true,"localName":"Certificate of deposit (CD)","localNameEn":"Certificate of deposit (3 months)","sourceUrl":"https://www.fdic.gov/national-rates-and-rate-caps"},"fdr_1y":{"available":true,"localName":"Certificate of deposit (CD)","localNameEn":"Certificate of deposit (12 months)","sourceUrl":"https://www.fdic.gov/national-rates-and-rate-caps"},"dps":{"available":false,"localName":null,"note":"No standard monthly recurring-deposit product; savers use automatic transfers into savings accounts or brokerage and retirement accounts."},"sanchayapatra_5y":{"available":true,"localName":"Series I savings bonds","localNameEn":"Inflation-protected U.S. savings bonds (I bonds)","note":"Bought from the Treasury at TreasuryDirect, up to USD 10,000 a year per person; Series EE bonds are also sold (doubling guaranteed in 20 years).","sourceUrl":"https://www.treasurydirect.gov/savings-bonds/i-bonds/i-bonds-interest-rates/"},"tbill_91d":{"available":true,"localName":"Treasury bills","localNameEn":"U.S. Treasury bills","note":"Individuals can buy at auction through TreasuryDirect or a broker; interest is exempt from state and local tax.","sourceUrl":"https://www.treasurydirect.gov/marketable-securities/treasury-bills/"},"tbond_5y":{"available":true,"localName":"Treasury notes","localNameEn":"U.S. Treasury notes (2 to 10 years)","sourceUrl":"https://home.treasury.gov/resource-center/data-chart-center/interest-rates/TextView?type=daily_treasury_yield_curve&field_tdr_date_value=2026"},"tbond_10y":{"available":true,"localName":"Treasury notes","localNameEn":"U.S. Treasury notes (10 years)","sourceUrl":"https://home.treasury.gov/resource-center/data-chart-center/interest-rates/TextView?type=daily_treasury_yield_curve&field_tdr_date_value=2026"},"equity_fund":{"available":true,"localName":null,"localNameEn":"Mutual funds and index ETFs","note":"Usually held in a 401(k), IRA or Roth IRA for tax advantages."},"gold":{"available":true,"localName":null,"localNameEn":"Gold bars and coins","note":"Legal to buy; the U.S. Mint issues gold bullion coins. Gains on physical gold are taxed as collectibles (up to 28% federal)."}},"institutions":{"centralBank":{"name":"Board of Governors of the Federal Reserve System","url":"https://www.federalreserve.gov/"},"insuranceRegulator":{"name":"State insurance departments (coordinated through the National Association of Insurance Commissioners, NAIC)","url":"https://content.naic.org/state-insurance-departments","note":"Insurance is regulated by each state; the NAIC is the states'' standard-setting body."},"insuranceComplaints":{"name":"Your state insurance department (NAIC directory)","url":"https://content.naic.org/state-insurance-departments","note":"Find your state insurance department and file a complaint there."},"pensionScheme":{"name":"Social Security (Social Security Administration)","url":"https://www.ssa.gov/benefits/retirement/"},"oldAgeAllowance":{"name":"Supplemental Security Income (SSI)","url":"https://www.ssa.gov/ssi/","note":"Means-tested monthly payment for people 65+ or disabled with little income and resources."},"publicHealthCover":{"name":"Medicare (65+), Medicaid and the Health Insurance Marketplace","url":"https://www.medicare.gov/","note":"Medicare covers people 65+; Medicaid covers low-income people; others buy cover through employers or HealthCare.gov (https://www.healthcare.gov/)."},"depositInsurance":{"name":"Federal Deposit Insurance Corporation (FDIC)","url":"https://www.fdic.gov/resources/deposit-insurance","note":"Credit union deposits are insured by the NCUA."},"statistics":{"name":"U.S. Census Bureau","url":"https://www.census.gov/","note":"Consumer prices are published by the Bureau of Labor Statistics (https://www.bls.gov/cpi/)."}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('US', 1, 'bank_deposit_avg_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No weighted average deposit rate across banks is published by the Federal Reserve or FDIC in this form; World Bank FR.INR.DPST has no US series. FDIC national averages (October 2026): savings 0.38%, 12-month CD 1.76%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('US', 1, 'credit_card_rate_cap', 0.2119, NULL, 'sourced', 'Federal Reserve G.19 Consumer Credit: commercial bank interest rate on credit card plans, all accounts', 'https://www.federalreserve.gov/releases/g19/current/default.htm', '2026-08-31', '21.19% APR on all accounts in August 2026 (22.36% on accounts assessed interest), released 7 October 2026. There is no general federal cap on credit card interest.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('US', 1, 'deposit_insurance_limit', 250000, NULL, 'sourced', 'Federal Deposit Insurance Corporation (FDIC), deposit insurance', 'https://www.fdic.gov/resources/deposit-insurance', '2026-10-31', 'At least USD 250,000 per depositor, per FDIC-insured bank, per ownership category. Credit unions are insured to the same limit by the NCUA.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('US', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'US banks do not commonly sell monthly recurring-deposit products and the FDIC national rates cover only savings, checking, money market and CDs; no published rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('US', 1, 'equity_return_base', 0.07, NULL, 'assumption', 'S&P 500 (Trading Economics); after-tax safe rate about 3.2% (3-month bill 4.16% less 22% federal tax, US Treasury)', 'https://tradingeconomics.com/united-states/stock-market', '2026-10-31', 'Base case: about 3.5-4 points above the after-tax Treasury bill rate, below the S&P 500''s strong 10-year record because valuations are high.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('US', 1, 'equity_return_high', 0.09, NULL, 'assumption', 'S&P 500 long-run total return (Trading Economics)', 'https://tradingeconomics.com/united-states/stock-market', '2026-10-31', 'High case: US shares continue close to their long-run total return of about 9-10% a year with dividends.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('US', 1, 'equity_return_low', 0.04, NULL, 'assumption', 'S&P 500 7,580 on 30 Oct 2026, +10.8% in a year, near its October 2026 record (Trading Economics)', 'https://tradingeconomics.com/united-states/stock-market', '2026-10-31', 'Low case: from high valuations US shares deliver well below their 10-year record, only a little above Treasuries.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('US', 1, 'fdr_1y_rate', 0.0176, NULL, 'sourced', 'FDIC, National Rates and Rate Caps, October 2026: 12-month CD', 'https://www.fdic.gov/national-rates-and-rate-caps', '2026-10-19', 'National average 12-month CD rate 1.76% (24-month 1.55%, 60-month 1.41%). Many banks pay far more than the deposit-weighted average; 1-year Treasury yield was 4.36% on 30 Oct 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('US', 1, 'fdr_3m_rate', 0.0114, NULL, 'sourced', 'FDIC, National Rates and Rate Caps, October 2026: 3-month CD', 'https://www.fdic.gov/national-rates-and-rate-caps', '2026-10-19', 'National average 3-month certificate of deposit rate 1.14% (6-month 1.39%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('US', 1, 'fixed_income_return_base', 0.03, NULL, 'assumption', '3-month bill 4.16% and 1-year Treasury 4.36% less 22% federal tax = 3.2-3.4% (US Treasury)', 'https://home.treasury.gov/resource-center/data-chart-center/interest-rates/TextView?type=daily_treasury_yield_curve&field_tdr_date_value=2026', '2026-10-31', 'Base case: Treasury bills, notes and competitive CDs after 22% federal tax, assuming rates ease a little.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('US', 1, 'fixed_income_return_high', 0.038, NULL, 'assumption', '5-year Treasury 4.71% (US Treasury); I bonds 5.51% from November 2026 (TreasuryDirect)', 'https://home.treasury.gov/resource-center/data-chart-center/interest-rates/TextView?type=daily_treasury_yield_curve&field_tdr_date_value=2026', '2026-10-31', 'High case: locking in today''s 5-year Treasury or I bond rates, partly inside tax-advantaged accounts.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('US', 1, 'fixed_income_return_low', 0.02, NULL, 'assumption', '3-month Treasury bill 4.16%, 12-month CD 1.76% national average (US Treasury; FDIC)', 'https://home.treasury.gov/resource-center/data-chart-center/interest-rates/TextView?type=daily_treasury_yield_curve&field_tdr_date_value=2026', '2026-10-31', 'Low case: short rates fall back towards 3% and are taxed at about 22%, or savings sit in low-rate bank accounts.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('US', 1, 'goal_inflation_education', 0.04, NULL, 'assumption', 'BLS CPI September 2026: education index +3.8% over 12 months', 'https://www.bls.gov/news.release/cpi.nr0.htm', '2026-10-31', 'Education prices are rising faster than general inflation, and college costs have a long record of doing so, so 4% is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('US', 1, 'goal_inflation_health', 0.04, NULL, 'assumption', 'BLS CPI September 2026: medical care +1.5%, medical care services +2.5% over 12 months', 'https://www.bls.gov/news.release/cpi.nr0.htm', '2026-10-31', 'Measured medical CPI is low this year, but US health costs and premiums have long risen faster than general prices, so 4% is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('US', 1, 'gold_return_base', 0.035, NULL, 'assumption', 'Gold price history (Trading Economics); Fed 2% goal', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Base case: dollar gold rises roughly with inflation plus a little over the long run.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('US', 1, 'gold_return_high', 0.06, NULL, 'assumption', 'Gold price history (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'High case: a repeat of part of gold''s strong 2005-2025 trend in dollars.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('US', 1, 'gold_return_low', 0.01, NULL, 'assumption', 'Gold USD 3,876/oz on 30 Oct 2026, 31% below the January 2026 high (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Low case: gold drifts after the 2025-26 spike and lags inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('US', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'US federal law (Fair Labor Standards Act) requires no severance or end-of-service payment; any severance or retirement payment is at the employer''s discretion or set by contract (U.S. Department of Labor, severance pay: https://www.dol.gov/general/topic/wages/severancepay).', 1);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('US', 1, 'health_hospitalisation_cost', 10600, NULL, 'sourced', 'HealthCare.gov, out-of-pocket maximum/limit (2026)', 'https://www.healthcare.gov/glossary/out-of-pocket-maximum-limit/', '2026-01-01', 'Indicative only: USD 10,600 is the 2026 legal maximum an individual on a Marketplace (ACA-compliant) plan pays out of pocket in a year for in-network care (USD 21,200 for a family); one major hospital stay with surgery often reaches the plan''s deductible or this limit. Uninsured patients face the full bill.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('US', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'US health insurance is priced per plan (by age, location, metal tier and tobacco use), not per sum insured; no official premium table per USD 100,000 of cover exists.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('US', 1, 'inflation_cpi', 0.037, NULL, 'sourced', 'U.S. Bureau of Labor Statistics, Consumer Price Index news release, September 2026', 'https://www.bls.gov/news.release/cpi.nr0.htm', '2026-09-30', 'CPI-U rose 3.7% in the 12 months to September 2026 (not seasonally adjusted); released 14 October 2026. World Bank 2024 average 2.9%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('US', 1, 'inflation_projection', 0.027, NULL, 'assumption', 'Federal Reserve 2% longer-run goal for PCE inflation; CPI-U 3.7% (Sep 2026, BLS)', 'https://www.federalreserve.gov/monetarypolicy/openmarket.htm', '2026-10-31', 'The Fed''s 2% goal is for PCE prices, which run a few tenths below CPI, and inflation has stayed above goal since 2021, so 2.7% CPI inflation is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('US', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life insurance is widely sold in the US, but no regulator or government body publishes indicative premiums per USD 1,000 of cover by age; insurer and broker quote tools were not used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('US', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Neither the NAIC nor state insurance departments publish an industry-wide life insurance claim settlement ratio; no official figure was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('US', 1, 'life_expectancy', 79.8, NULL, 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/united-states', '2026-07-01', 'Men 77.4, women 82.2 (UN WPP estimate for 2026). World Bank 2024: 78.9 (men 76.5, women 81.4).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('US', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":24.1,"men":22.6,"women":25.5},{"age":65,"total":20.2,"men":18.9,"women":21.4},{"age":70,"total":16.4,"men":15.3,"women":17.4},{"age":80,"total":9.7,"men":8.9,"women":10.2}]}', 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/united-states', '2026-07-01', 'Remaining years from georank''s expected age at death by current age (UN WPP 2026 estimate).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('US', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":65,"womenAge":65,"over90Monthly":null,"meansTested":true}', 'sourced', '42 U.S.C. 1382c(a)(1)(A), definition of aged individual for SSI (Cornell LII)', 'https://www.law.cornell.edu/uscode/text/42/1382c', '2026-10-31', 'SSI is paid from 65 regardless of work history, but is means-tested on income and resources (countable resources up to USD 2,000 for an individual, USD 3,000 for a couple) and requires US citizenship or qualifying immigration status.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('US', 1, 'old_age_allowance_monthly', 994, NULL, 'sourced', 'Social Security Administration, Cost-of-Living Increase and Other Determinations for 2026 (Federal Register)', 'https://www.federalregister.gov/documents/2025/11/03/2025-19763/cost-of-living-increase-and-other-determinations-for-2026', '2026-01-01', 'Supplemental Security Income (SSI) federal payment standard USD 994 a month for an individual (USD 1,491 for a couple) in 2026; many states add a supplement. Paid to people 65+ (or disabled) with very low income and resources.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('US', 1, 'oop_health_share', 0.1093, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=US', '2023-12-31', '2023 figure (older than 2025; latest available).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('US', 1, 'policy_rate', 0.04, NULL, 'sourced', 'Board of Governors of the Federal Reserve System, open market operations: federal funds target range', 'https://www.federalreserve.gov/monetarypolicy/openmarket.htm', '2026-09-17', 'Target range 3.75-4.00% (upper bound shown) after a 25 basis point rise on 17 September 2026; the range was unchanged through 31 October 2026 (FRED DFEDTARU).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('US', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":67,"nomineeUntilAge":null,"inflationLinked":true,"taxFree":false}', 'sourced', 'Social Security Administration, Cost-of-Living Increase and Other Determinations for 2026 (Federal Register); 42 U.S.C. 416(l)', 'https://www.federalregister.gov/documents/2025/11/03/2025-19763/cost-of-living-increase-and-other-determinations-for-2026', '2026-01-01', 'Social Security (Old-Age, Survivors and Disability Insurance): earnings-related, funded by payroll tax (6.2% employee plus 6.2% employer) on earnings up to USD 184,500 in 2026; 40 quarters of coverage (about 10 years) needed. Full benefit at 67 for those born 1960 or later, reduced from 62, larger to 70. Benefits rose 2.8% in January 2026 under the automatic CPI-W cost-of-living adjustment; up to 85% of benefits can be federally taxable.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('US', 1, 'retirement_accumulation_return_base', 0.05, NULL, 'assumption', 'Fixed income base 3%; equity base 7%', 'https://tradingeconomics.com/united-states/stock-market', '2026-10-31', 'Base case: roughly half shares at 7% and half bonds and bills at about 3%, in tax-advantaged accounts.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('US', 1, 'retirement_accumulation_return_high', 0.065, NULL, 'assumption', 'Fixed income high 3.8%; equity high 9%', 'https://tradingeconomics.com/united-states/stock-market', '2026-10-31', 'High case for a growth-leaning balanced mix in tax-advantaged accounts.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('US', 1, 'retirement_accumulation_return_low', 0.035, NULL, 'assumption', 'After-tax safe rate about 3.2%; S&P 500 valuations (Trading Economics)', 'https://tradingeconomics.com/united-states/stock-market', '2026-10-31', 'Low case for a balanced mix if shares lag, held mostly in 401(k)s and IRAs.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('US', 1, 'retirement_age_default', 67, NULL, 'sourced', 'Social Security Act section 216(l), 42 U.S.C. 416(l) (Cornell LII)', 'https://www.law.cornell.edu/uscode/text/42/416', '2026-10-31', 'Full retirement age is 67 for anyone reaching 62 after 2021 (born 1960 or later), men and women alike; reduced benefits from 62, delayed credits to 70. There is no mandatory retirement age for most private employees.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('US', 1, 'retirement_age_government', 62, NULL, 'sourced', 'U.S. Office of Personnel Management, FERS retirement eligibility', 'https://www.opm.gov/retirement-center/fers-information/eligibility/', '2026-10-31', 'Federal employees under FERS can retire on an immediate unreduced annuity at 62 with 5 years'' service, 60 with 20 years, or the minimum retirement age (57 for those born 1970 or later) with 30 years; there is no mandatory retirement age for most federal jobs.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('US', 1, 'retirement_return_base', 0.03, NULL, 'assumption', '3-month bill 4.16% less 22% federal tax = 3.24% (US Treasury)', 'https://home.treasury.gov/resource-center/data-chart-center/interest-rates/TextView?type=daily_treasury_yield_curve&field_tdr_date_value=2026', '2026-10-31', 'Base case capped at the after-tax 3-month Treasury bill rate for a middle-income retiree.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('US', 1, 'retirement_return_high', 0.037, NULL, 'assumption', '5-year Treasury 4.71%; I bonds 5.51% from November 2026 (TreasuryDirect)', 'https://home.treasury.gov/resource-center/data-chart-center/interest-rates/TextView?type=daily_treasury_yield_curve&field_tdr_date_value=2026', '2026-10-31', 'High case: a retiree ladders Treasuries, I bonds and competitive CDs at about today''s rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('US', 1, 'retirement_return_low', 0.02, NULL, 'assumption', '3-month Treasury bill 4.16% (US Treasury); FDIC national CD averages', 'https://home.treasury.gov/resource-center/data-chart-center/interest-rates/TextView?type=daily_treasury_yield_curve&field_tdr_date_value=2026', '2026-10-31', 'Low case: short rates fall back and savings earn less after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('US', 1, 'sanchayapatra_5y_rate', 0.0426, NULL, 'sourced', 'U.S. Treasury (TreasuryDirect), Series I savings bonds: interest rates', 'https://www.treasurydirect.gov/savings-bonds/i-bonds/i-bonds-interest-rates/', '2026-05-01', 'Composite rate 4.26% for I bonds issued May-October 2026 (fixed 0.90% plus inflation 1.67% a half-year); bonds issued November 2026-April 2027 earn 5.51% (fixed 1.40%). Rate resets every 6 months with CPI; cashing in before 5 years forfeits the last 3 months'' interest; USD 10,000 a year limit per person electronically.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('US', 1, 'savings_account_rate', 0.0038, NULL, 'sourced', 'FDIC, National Rates and Rate Caps, October 2026: savings', 'https://www.fdic.gov/national-rates-and-rate-caps', '2026-10-19', 'National average savings rate 0.38% (money market 0.63%, interest checking 0.07%); online high-yield savings accounts pay much more. Interest is taxable.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('US', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":3.51},{"year":2040,"value":2.82},{"year":2065,"value":2.4}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/united-states-of-america/2040/', '2025-12-31', '100 / old-age dependency ratio: 28.5 (2025, World Bank), 35.5 (2040) and 41.6 (2065, populationpyramid.net/united-states-of-america/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('US', 1, 'tax_bank_interest', 0.22, NULL, 'sourced', 'Internal Revenue Service, tax inflation adjustments for tax year 2026', 'https://www.irs.gov/newsroom/irs-releases-tax-inflation-adjustments-for-tax-year-2026-including-amendments-from-the-one-big-beautiful-bill', '2026-01-01', 'No withholding on interest for residents; interest is ordinary income. 22% is the federal marginal rate for a single filer with taxable income USD 50,401-105,700 in 2026 (12% below that); most states add their own income tax (eight have none). Interest in IRAs and 401(k)s is tax-deferred or tax-free (Roth).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('US', 1, 'tax_sanchayapatra_profit', 0.22, NULL, 'sourced', 'TreasuryDirect, I bonds; IRS 2026 federal brackets', 'https://www.treasurydirect.gov/savings-bonds/i-bonds/i-bonds-interest-rates/', '2026-10-31', 'I bond interest is subject to federal income tax at the marginal rate (22% for a middle earner) but exempt from state and local tax; tax can be deferred until the bond is cashed and may be excluded if used for qualified higher education. Treasury bill and bond interest is also state-tax-free.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('US', 1, 'tbill_91d_rate', 0.0416, NULL, 'sourced', 'U.S. Department of the Treasury, daily Treasury par yield curve rates: 3-month', 'https://home.treasury.gov/resource-center/data-chart-center/interest-rates/TextView?type=daily_treasury_yield_curve&field_tdr_date_value=2026', '2026-10-30', '3-month bill 4.16% on 30 October 2026 (1-year 4.36%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('US', 1, 'tbond_10y_rate', 0.0494, NULL, 'sourced', 'U.S. Department of the Treasury, daily Treasury par yield curve rates: 10-year', 'https://home.treasury.gov/resource-center/data-chart-center/interest-rates/TextView?type=daily_treasury_yield_curve&field_tdr_date_value=2026', '2026-10-30', NULL, 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('US', 1, 'tbond_5y_rate', 0.0471, NULL, 'sourced', 'U.S. Department of the Treasury, daily Treasury par yield curve rates: 5-year', 'https://home.treasury.gov/resource-center/data-chart-center/interest-rates/TextView?type=daily_treasury_yield_curve&field_tdr_date_value=2026', '2026-10-30', NULL, 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('UY', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"UY","iso3":"URY","nameEn":"Uruguay","nameNative":"Uruguay","region":"latin_america_caribbean","languages":["es"],"currency":{"code":"UYU","symbol":"$","decimals":2,"compact":"intl","usdRate":{"value":40.188,"status":"sourced","sourceName":"Banco Central del Uruguay, cotizaciones: Dólar USA billete","sourceUrl":"https://www.bcu.gub.uy/Estadisticas-e-Indicadores/Paginas/Cotizaciones.aspx","asOf":"2026-10-30","note":"UYU 40.188 per US dollar on 30 October 2026 (BCU official quote); World Bank 2025 average 41.19."}},"instruments":{"savings_account":{"available":true,"localName":"Caja de ahorro","localNameEn":"Savings account"},"fdr_3m":{"available":true,"localName":"Depósito a plazo fijo (3 meses)","localNameEn":"Fixed-term deposit (3 months)"},"fdr_1y":{"available":true,"localName":"Depósito a plazo fijo (1 año)","localNameEn":"Fixed-term deposit (1 year)"},"dps":{"available":false,"localName":null,"localNameEn":"Recurring deposit","note":"No standard monthly recurring deposit product was found."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":"Government savings certificate","note":"No retail savings certificate; individuals buy government notes through banks and brokers."},"tbill_91d":{"available":true,"localName":"Letras de Regulación Monetaria","localNameEn":"Central bank monetary regulation bills","note":"Short-term peso bills are issued by the Banco Central del Uruguay; the Treasury itself issues notes of two years and longer."},"tbond_5y":{"available":true,"localName":"Notas del Tesoro en pesos","localNameEn":"Treasury notes in pesos","note":"Auctioned by the Ministry of Economy and Finance in nominal pesos, UI and UP.","sourceUrl":"https://deuda.mef.gub.uy/29186/14/areas/notas-del-tesoro.html"},"tbond_10y":{"available":true,"localName":"Notas del Tesoro y Bonos Globales","localNameEn":"Treasury notes and global bonds","note":"Long maturities are issued mainly in inflation-indexed units (UI) and wage-indexed units (UP).","sourceUrl":"https://deuda.mef.gub.uy/29186/14/areas/notas-del-tesoro.html"},"equity_fund":{"available":true,"localName":"Fondos de inversión","localNameEn":"Investment funds","note":"The local stock market is very small; equity exposure is mostly through foreign funds bought via securities brokers."},"gold":{"available":true,"localName":"Oro (lingotes y monedas)","localNameEn":"Gold (bars and coins)","note":"No legal restriction on owning gold was found."}},"institutions":{"centralBank":{"name":"Banco Central del Uruguay (BCU)","url":"https://www.bcu.gub.uy/"},"insuranceRegulator":{"name":"Banco Central del Uruguay, Superintendencia de Servicios Financieros (insurance)","url":"https://www.bcu.gub.uy/Servicios-Financieros-SSF/Paginas/empresas_Seguros.aspx"},"insuranceComplaints":{"name":"Banco Central del Uruguay, Superintendencia de Servicios Financieros (consumer complaints)","url":"https://www.bcu.gub.uy/Servicios-Financieros-SSF/Paginas/empresas_Seguros.aspx","note":"Complaints about insurers go first to the insurer and then to the BCU''s Financial Services Superintendency."},"pensionScheme":{"name":"Banco de Previsión Social (BPS), jubilación","url":"https://www.bps.gub.uy/3498/jubilaciones.html"},"oldAgeAllowance":{"name":"Banco de Previsión Social (BPS), Pensión por vejez","url":"https://www.bps.gub.uy/20540/pension-por-vejez.html"},"publicHealthCover":{"name":"Ministerio de Salud Pública, Sistema Nacional Integrado de Salud (FONASA)","url":"https://www.gub.uy/ministerio-salud-publica/"},"depositInsurance":{"name":"Corporación de Protección del Ahorro Bancario (COPAB)","url":"https://www.copab.org.uy/innovaportal/v/308/1/web/cobertura.html"},"statistics":{"name":"Instituto Nacional de Estadística (INE)","url":"https://www.gub.uy/instituto-nacional-estadistica/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UY', 1, 'bank_deposit_avg_rate', 0.0506, NULL, 'sourced', 'Banco Central del Uruguay, Series estadísticas de tasas de interés, ''Pasivas $'' sheet: average rate on peso fixed-term deposits, total banking system', 'https://www.bcu.gub.uy/Servicios-Financieros-SSF/Series%20IF/tasas.xls', '2026-09-30', '5.06% effective annual in September 2026, down from 6.86% in December 2025 after policy rate cuts; World Bank 2025 average 7.30%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UY', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'Uruguay''s usury law sets ceilings linked to BCU average lending rates, but a current ceiling for credit cards was not confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UY', 1, 'deposit_insurance_limit', 1670950, NULL, 'sourced', 'Corporación de Protección del Ahorro Bancario (COPAB), cobertura; Unidad Indexada value from Banco Central del Uruguay', 'https://www.copab.org.uy/innovaportal/v/308/1/web/cobertura.html', '2026-10-31', 'Cover is UI 250,000 per person per institution for peso deposits (USD 10,000 for foreign-currency deposits); at the BCU''s UI value of 6.6838 on 31 October 2026 that is about UYU 1,670,950.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UY', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No monthly recurring deposit product or published rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UY', 1, 'equity_return_base', 0.08, NULL, 'assumption', 'Global equity index in peso terms; peso note due 2030 at 7.18% (MEF, September 2026) and 1-year peso deposits 5.20% (BCU), 12% tax on interest', 'https://deuda.mef.gub.uy/innovaportal/file/32414/1/reporte-mensual-de-emisiones-de-notas-de-tesoreria-domesticas---setiembre-2026.pdf', '2026-10-31', 'Uruguay''s exchange lists very few shares, so equity is a global index fund in pesos: about 3.5 points over the after-tax 1-year deposit rate (4.6%), within the safe rate plus 4 points.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UY', 1, 'equity_return_high', 0.11, NULL, 'assumption', 'Global equity long-run record plus modest peso depreciation (BCU exchange rates)', 'https://www.bcu.gub.uy/Estadisticas-e-Indicadores/Paginas/Cotizaciones.aspx', '2026-10-31', 'High case: global shares repeat their long-run record and the peso weakens gradually.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UY', 1, 'equity_return_low', 0.03, NULL, 'assumption', 'No meaningful local stock market; global equities in peso terms; peso 40.19 per US dollar on 30 October 2026 against a 41.19 average in 2025 (BCU, World Bank)', 'https://www.bcu.gub.uy/Estadisticas-e-Indicadores/Paginas/Cotizaciones.aspx', '2026-10-31', 'Low case: weak global shares and a stable or stronger peso leave equities below peso fixed income.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UY', 1, 'fdr_1y_rate', 0.052, NULL, 'sourced', 'Banco Central del Uruguay, Series estadísticas de tasas de interés, ''Pasivas $'' sheet: peso fixed-term deposits of individuals (persona física), 181 to 366 days', 'https://www.bcu.gub.uy/Servicios-Financieros-SSF/Series%20IF/tasas.xls', '2026-09-30', '5.20% effective annual, monthly weighted average for September 2026; the BCU series stops at 366 days.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UY', 1, 'fdr_3m_rate', 0.0504, NULL, 'sourced', 'Banco Central del Uruguay, Series estadísticas de tasas de interés, ''Pasivas $'' sheet: peso fixed-term deposits of individuals (persona física), 61 to 90 days', 'https://www.bcu.gub.uy/Servicios-Financieros-SSF/Series%20IF/tasas.xls', '2026-09-30', '5.04% effective annual, monthly weighted average for September 2026 (5.52% across all depositors for the same term).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UY', 1, 'fixed_income_return_base', 0.05, NULL, 'assumption', 'BCU 1-year peso deposits 5.20% (September 2026); peso note due 2030 at 7.18% (MEF); 12% tax', 'https://www.bcu.gub.uy/Servicios-Financieros-SSF/Series%20IF/tasas.xls', '2026-10-31', 'Base case: a mix of 1-year deposits (4.6% after tax) and government peso notes (about 6.3% after tax), so 5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UY', 1, 'fixed_income_return_high', 0.06, NULL, 'assumption', 'Government peso note due 2030 at 7.18% (MEF auction September 2026); 12% tax', 'https://deuda.mef.gub.uy/innovaportal/file/32414/1/reporte-mensual-de-emisiones-de-notas-de-tesoreria-domesticas---setiembre-2026.pdf', '2026-10-31', 'High case: locking in four-year government peso notes at today''s yield, about 6.3% after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UY', 1, 'fixed_income_return_low', 0.04, NULL, 'assumption', 'BCU peso term deposits of individuals 4.1-5.2% (September 2026); 12% tax on interest (PwC)', 'https://www.bcu.gub.uy/Servicios-Financieros-SSF/Series%20IF/tasas.xls', '2026-10-31', 'Low case: short peso deposits after 12% tax, about 4%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UY', 1, 'goal_inflation_education', 0.065, NULL, 'assumption', 'INE CPI September 2026: education division +7.29% year on year (as reported by Trading Economics)', 'https://tradingeconomics.com/uruguay/inflation-cpi', '2026-10-31', 'Education was the fastest-rising CPI division in the year to September 2026 (7.3%), so planning uses 6.5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UY', 1, 'goal_inflation_health', 0.06, NULL, 'assumption', 'INE CPI September 2026: health division +6.72% year on year (as reported by Trading Economics)', 'https://tradingeconomics.com/uruguay/inflation-cpi', '2026-10-31', 'Health prices are rising about 2 points faster than the 4.68% CPI, so planning uses 6%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UY', 1, 'gold_return_base', 0.055, NULL, 'assumption', 'Gold USD price trend (Trading Economics); BCU 4.5% inflation target implies slow peso depreciation', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Base case: gold tracks long-run dollar inflation plus a little, and the peso loses about 1.5-2% a year against the dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UY', 1, 'gold_return_high', 0.1, NULL, 'assumption', 'Gold USD price history (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'High case: gold resumes its 2020s uptrend and the peso weakens.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UY', 1, 'gold_return_low', 0, NULL, 'assumption', 'Gold about USD 3,900/oz at the start of November 2026, little changed in a year and well below its January 2026 peak of USD 5,608 (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Low case: gold stays flat in dollars and the peso holds steady.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UY', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'Dismissal severance (indemnización por despido) exists for private employees, but the current legal text could not be confirmed (IMPO shows the 1944 Ley 10.489 rule of one month''s pay per year, up to six, as amended later); no gratuity on retirement was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UY', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical out-of-pocket cost of a hospital stay was found; most people are covered through FONASA in the National Integrated Health System, with copayments set by each provider.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UY', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No regulator or other non-company source of private health insurance premiums by age was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UY', 1, 'inflation_cpi', 0.0468, NULL, 'sourced', 'Instituto Nacional de Estadística (INE), Índice de Precios del Consumo, variación 12 meses, September 2026', 'https://www5.ine.gub.uy/documents/Estad%C3%ADsticasecon%C3%B3micas/SERIES%20Y%20OTROS/IPC/Base%20Octubre%202022=100/IPC%20gral%20y%20variaciones_base%202022.xlsx', '2026-09-30', 'CPI rose 4.68% in the 12 months to September 2026 (4.55% in August), shown on the INE home page with this data file; October CPI is due on 5 November 2026. World Bank 2025 average 4.65%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UY', 1, 'inflation_projection', 0.045, NULL, 'assumption', 'Banco Central del Uruguay inflation target 4.5% (range plus or minus 1.5 points); CPI 4.68% in September 2026 (INE)', 'https://www.bcu.gub.uy/Politica-Economica-y-Mercados/Paginas/Copom.aspx', '2026-10-31', 'The BCU targets 4.5% and inflation has stayed close to it since 2024, so planning uses the target.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UY', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life cover is sold in Uruguay, but no regulator or other non-company source with indicative premiums by age was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UY', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No industry-wide life claim settlement ratio was found in the insurance statistics of the Banco Central del Uruguay''s Superintendencia de Servicios Financieros.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UY', 1, 'life_expectancy', 78.287, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=UY', '2024-12-31', 'Men 74.4, women 82.0 (2024). UN WPP gives 78.6 for 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UY', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":22.9,"men":19.9,"women":25.6},{"age":65,"total":19.2,"men":16.3,"women":21.5},{"age":70,"total":15.7,"men":13.1,"women":17.6},{"age":80,"total":9.7,"men":7.7,"women":10.9}]}', 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/uruguay', '2026-07-01', 'Remaining years derived from the ''life expectancy by current age'' table for 2026 (UN WPP): total age reached minus current age.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UY', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":70,"womenAge":70,"over90Monthly":null,"meansTested":true}', 'sourced', 'Banco de Previsión Social (BPS), Pensión por vejez', 'https://www.bps.gub.uy/20540/pension-por-vejez.html', '2025-12-03', 'Age 70 or over (65 with at least 7 years of unpaid family care), 10 years'' residence in the last 20, no other retirement pension, and lacking resources: own income and that of legally obligated relatives is tested. People aged 65-69 in extreme poverty may get Asistencia a la Vejez first.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UY', 1, 'old_age_allowance_monthly', 18575, NULL, 'sourced', 'Banco de Previsión Social (BPS), montos y aumentos de pasividades: Pensión por vejez e invalidez', 'https://www.bps.gub.uy/6182/montos-y-aumentos-de-pasividades.html', '2026-01-01', 'UYU 18,575 a month in 2026 (pensions rose 5.97% in the 2026 general increase); reduced by half of the person''s own income and by part of relatives'' income above set limits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UY', 1, 'oop_health_share', 0.171, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=UY', '2023-12-31', 'Out-of-pocket spending was 17.1% of current health expenditure in 2023 (latest available; older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UY', 1, 'policy_rate', 0.06, NULL, 'sourced', 'Banco Central del Uruguay, Comité de Política Monetaria communiqué of 8 October 2026', 'https://www.bcu.gub.uy/Politica-Economica-y-Mercados/Paginas/Copom.aspx', '2026-10-08', 'Raised 25 basis points to 6.00% on 8 October 2026, from 5.75% held since early 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UY', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":65,"nomineeUntilAge":null,"inflationLinked":true,"taxFree":null}', 'sourced', 'Banco de Previsión Social (BPS), Jubilación normal por el Nuevo Sistema Previsional Común (Ley 20.130)', 'https://www.bps.gub.uy/20533/jubilacion-normal-por-el-nuevo-sistema-previsional-comun.html', '2026-10-31', 'Compulsory for private and public employees; pension from 65 (born 1977 or later) with 30 years, based on the best 20 years'' wages; pay-as-you-go BPS pension plus a mandatory individual account (AFAP). Pensions in payment get a general increase each year (5.97% in 2026, BPS). Normal pensions under the new system start in 2033.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UY', 1, 'retirement_accumulation_return_base', 0.065, NULL, 'assumption', 'Fixed income base 5%; equity base 8%', 'https://deuda.mef.gub.uy/innovaportal/file/32414/1/reporte-mensual-de-emisiones-de-notas-de-tesoreria-domesticas---setiembre-2026.pdf', '2026-10-31', 'Base case: roughly half safe peso fixed income and half global equity.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UY', 1, 'retirement_accumulation_return_high', 0.085, NULL, 'assumption', 'Equity high 11%; peso notes 7.18%', 'https://deuda.mef.gub.uy/innovaportal/file/32414/1/reporte-mensual-de-emisiones-de-notas-de-tesoreria-domesticas---setiembre-2026.pdf', '2026-10-31', 'High case: equities do well and peso yields stay near 7%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UY', 1, 'retirement_accumulation_return_low', 0.04, NULL, 'assumption', 'Fixed income low 4%; equity low 3%', 'https://www.bcu.gub.uy/Servicios-Financieros-SSF/Series%20IF/tasas.xls', '2026-10-31', 'Low case for a balanced mix of peso fixed income and global equity.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UY', 1, 'retirement_age_default', 65, NULL, 'sourced', 'Banco de Previsión Social (BPS), Jubilación normal por el Nuevo Sistema Previsional Común (Ley 20.130)', 'https://www.bps.gub.uy/20533/jubilacion-normal-por-el-nuevo-sistema-previsional-comun.html', '2026-10-31', 'Under the 2023 reform (Ley 20.130) the minimum age with 30 years of work is 64 for people born in 1976 and 65 for those born in 1977 or later; with fewer years, retirement is possible from 65 with 25 years up to 70 with 15 years. The old regime allowed 60.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UY', 1, 'retirement_age_government', 65, NULL, 'sourced', 'Banco de Previsión Social (BPS), Jubilación normal por el Nuevo Sistema Previsional Común (Ley 20.130)', 'https://www.bps.gub.uy/20533/jubilacion-normal-por-el-nuevo-sistema-previsional-comun.html', '2026-10-31', 'Public employees in the civil affiliation are in the same common system, so the same 65 applies to those born in 1977 or later; military, police, bank and professional schemes have their own funds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UY', 1, 'retirement_return_base', 0.045, NULL, 'assumption', 'BCU 1-year peso deposits of individuals 5.20% (September 2026) less 12% tax = 4.58%', 'https://www.bcu.gub.uy/Servicios-Financieros-SSF/Series%20IF/tasas.xls', '2026-10-31', 'Base case: mostly peso term deposits and short government notes, kept just below the 4.58% after-tax 1-year deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UY', 1, 'retirement_return_high', 0.06, NULL, 'assumption', 'Government peso note due 2030 at 7.18% (MEF auction September 2026); 12% tax', 'https://deuda.mef.gub.uy/innovaportal/file/32414/1/reporte-mensual-de-emisiones-de-notas-de-tesoreria-domesticas---setiembre-2026.pdf', '2026-10-31', 'High case: a ladder of medium-term government peso notes.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UY', 1, 'retirement_return_low', 0.04, NULL, 'assumption', 'BCU peso term deposits of individuals 4.1-5.2% (September 2026); 12% tax on interest', 'https://www.bcu.gub.uy/Servicios-Financieros-SSF/Series%20IF/tasas.xls', '2026-10-31', 'Low case: short peso deposits after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UY', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Uruguay has no separate government savings certificate for individuals; government peso notes (Notas del Tesoro) are sold at auction to institutions and reach individuals through banks and brokers.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UY', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical savings-account (caja de ahorro) rate was found; the BCU deposit-rate series cover fixed-term deposits only.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UY', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":4.04},{"year":2040,"value":3.18},{"year":2065,"value":1.94}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/uruguay/2065/', '2025-12-31', '100 / old-age dependency ratio: 24.7 in 2025 (World Bank), 31.4 in 2040 and 51.6 in 2065 (UN WPP medium variant).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UY', 1, 'tax_bank_interest', 0.12, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Uruguay, Individual, taxes on personal income', 'https://taxsummaries.pwc.com/uruguay/individual/taxes-on-personal-income', '2026-09-02', 'Capital investment income, including interest, is taxed at a flat 12% (IRPF); PwC notes some exceptions that it does not list (page reviewed 2 September 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UY', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate exists; the tax treatment of interest on public debt held by individuals could not be confirmed from PwC Tax Summaries.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UY', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Short-term peso bills are Banco Central del Uruguay monetary regulation bills (Letras de Regulación Monetaria); their auction results page is behind a browser check and could not be read, so no yield is recorded.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UY', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 10-year nominal peso government yield was found; recent domestic auctions in nominal pesos were for notes due 2029-2030, and longer issues are in indexed units (UI, UP).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UY', 1, 'tbond_5y_rate', 0.0718, NULL, 'sourced', 'Ministerio de Economía y Finanzas, Unidad de Gestión de Deuda, monthly report of domestic Treasury note issues, September 2026: Serie 13 nominal peso note maturing 2030', 'https://deuda.mef.gub.uy/innovaportal/file/32414/1/reporte-mensual-de-emisiones-de-notas-de-tesoreria-domesticas---setiembre-2026.pdf', '2026-09-30', 'Cut-off yield 7.18% (coupon 8.125%) at the September 2026 auction of the nominal peso note due 2030, about 4 years to maturity; no exact 5-year nominal peso yield is published.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('UZ', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"UZ","iso3":"UZB","nameEn":"Uzbekistan","nameNative":"Oʻzbekiston","region":"europe_central_asia","languages":["uz","ru","kaa","tg"],"currency":{"code":"UZS","symbol":"soʻm","decimals":2,"compact":"intl","usdRate":{"value":11995.5,"status":"sourced","sourceName":"Trading Economics, USD/UZS exchange rate","sourceUrl":"https://tradingeconomics.com/uzbekistan/currency","asOf":"2026-10-30","note":"Secondary source: the Central Bank of Uzbekistan site (cbu.uz) refused connections. The page showed 11,944.72 on 3 November 2026 (11,925 on 2 November); the 30 October reading could not be re-read on the page. World Bank official rate 2025 average 12,579 som per dollar (PA.NUS.FCRF)."}},"instruments":{"savings_account":{"available":true,"localName":"Jamgʻarma omonati","localNameEn":"Savings deposit","note":"Interest on bank deposits is exempt from personal income tax."},"fdr_3m":{"available":true,"localName":"Muddatli omonat","localNameEn":"Term deposit (3 months)"},"fdr_1y":{"available":true,"localName":"Muddatli omonat","localNameEn":"Term deposit (1 year)","sourceUrl":"https://tradingeconomics.com/uzbekistan/deposit-interest-rate"},"dps":{"available":true,"localName":null,"localNameEn":"Top-up savings deposit","note":"Many som deposits allow regular top-ups; no standard monthly recurring scheme with a published rate was found."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate or retail savings bond for individuals was found; government bonds are sold at auctions."},"tbill_91d":{"available":true,"localName":"Davlat qisqa muddatli obligatsiyalari","localNameEn":"Short-term government bonds","note":"Issued by the Ministry of Economy and Finance at auctions on the Republican Currency Exchange, mainly to banks; interest is tax-free for individuals."},"tbond_5y":{"available":true,"localName":"Davlat oʻrta muddatli obligatsiyalari","localNameEn":"Medium-term government bonds","note":"Bonds of about 3 years (1,074 days) were placed in October 2026; no 5-year yield was found.","sourceUrl":"https://www.uzrvb.uz/rynki-i-torgi/rynok-gosudarstvennyh-tsennyh-bumag/"},"tbond_10y":{"available":false,"localName":null,"localNameEn":null,"note":"No 10-year domestic government bond was found."},"equity_fund":{"available":false,"localName":null,"localNameEn":null,"note":"No widely available retail diversified mutual or index fund was found; the Tashkent stock exchange is small and illiquid."},"gold":{"available":true,"localName":"Oʻlchovli oltin quymalari","localNameEn":"Measured gold bars","note":"Gold bars refined in Uzbekistan are sold to the public through banks under Central Bank of Uzbekistan arrangements."}},"institutions":{"centralBank":{"name":"Central Bank of the Republic of Uzbekistan","url":"https://cbu.uz/en/"},"insuranceRegulator":{"name":"National Agency for Prospective Projects (NAPP)","url":"https://napp.uz/en","note":"Regulates and licenses insurance, the capital market and crypto-assets."},"insuranceComplaints":{"name":"National Agency for Prospective Projects, appeals","url":"https://napp.uz/appeal"},"pensionScheme":{"name":"Pension Fund under the Ministry of Economy and Finance","url":"https://gov.uz/uz/pj"},"oldAgeAllowance":{"name":"Allowance for elderly citizens without the required work record (Presidential Decree UP-115, 2026)","url":"https://lex.uz/ru/docs/8283680"},"publicHealthCover":{"name":"Ministry of Health of the Republic of Uzbekistan","url":"https://gov.uz/ssv","note":"Basic care in public facilities is state-funded; a State Health Insurance Fund is being rolled out region by region."},"depositInsurance":{"name":"Deposit Guarantee Agency (Law ZRU-1031 ''On guarantees of protection of deposits in banks'')","url":"https://lex.uz/ru/docs/7389439","note":"Successor to the Fund for Guaranteeing Citizens'' Deposits in Banks; its own site could not be reached."},"statistics":{"name":"Statistics Agency under the President of the Republic of Uzbekistan","url":"https://stat.uz/en/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UZ', 1, 'bank_deposit_avg_rate', 0.139, NULL, 'sourced', 'Trading Economics, Uzbekistan deposit interest rate (Central Bank of Uzbekistan data)', 'https://tradingeconomics.com/uzbekistan/deposit-interest-rate', '2026-08-31', 'Secondary source: 13.9% in August 2026, down from 14.7% in July; World Bank FR.INR.DPST 18.1% for 2024. The series is not described on the page and appears to blend all deposits; the Central Bank reported an average of 17.6% on som term deposits in June 2026 (Kursiv Uzbekistan, https://uz.kursiv.media/?p=2076055).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UZ', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap or published typical annual rate on credit card balances was found; cbu.uz lending-rate statistics could not be reached.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UZ', 1, 'deposit_insurance_limit', 200000000, NULL, 'sourced', 'Law of the Republic of Uzbekistan No. ZRU-1031 of 18 February 2025 ''On guarantees of protection of deposits in banks'', Article 26', 'https://lex.uz/ru/docs/7389439', '2025-02-19', 'Compensation per depositor per bank is the full balance up to 200 million som, all deposits and currencies combined (Article 26). The law took effect on official publication (19 February 2025, Article 52); under Article 51 the cap does not apply to citizens'' deposits made before that date. Paid by the Deposit Guarantee Agency. Amendments by Law ZRU-1126 of 27 March 2026 took effect on 29 June 2026 but did not change the cap.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UZ', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Banks offer som deposits that can be topped up, but no published rate for a monthly recurring deposit scheme was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UZ', 1, 'equity_return_base', 0.12, NULL, 'assumption', 'Global equity returns plus expected som depreciation; average deposit rate 13.9% tax-free', 'https://tradingeconomics.com/uzbekistan/deposit-interest-rate', '2026-10-31', 'The local stock market is too thin to have a usable 10-year record, so the base uses a global index in som terms (about 7% in dollars plus about 4-5% depreciation), below the tax-free deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UZ', 1, 'equity_return_high', 0.16, NULL, 'assumption', 'Global equity returns plus faster som depreciation', 'https://tradingeconomics.com/uzbekistan/deposit-interest-rate', '2026-10-31', 'High case: strong global equity returns and som depreciation similar to the 2017-2023 period.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UZ', 1, 'equity_return_low', 0.07, NULL, 'assumption', 'Global equities in som terms; Tashkent stock market is small and illiquid; deposits 13.9% tax-free (Trading Economics)', 'https://tradingeconomics.com/uzbekistan/deposit-interest-rate', '2026-10-31', 'Low case: a global equity index in dollars earns about 4% and the som weakens about 3% a year.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UZ', 1, 'fdr_1y_rate', 0.154, NULL, 'sourced', 'Kursiv Uzbekistan (news), reporting Central Bank of Uzbekistan deposit statistics for June 2026', 'https://uz.kursiv.media/?p=2076055', '2026-06-30', 'Secondary source (cbu.uz could not be reached): the average rate on som term deposits of up to one year was 15.4% in June 2026 (14.7% in May); deposits over one year paid 18.1%. The bucket covers all terms up to one year, for individuals and companies; bank interest is tax-free for individuals.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UZ', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published 3-month term deposit rate was found; cbu.uz deposit-rate statistics could not be reached.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UZ', 1, 'fixed_income_return_base', 0.12, NULL, 'assumption', 'Average deposit rate 13.9% (Aug 2026), tax-free (Tax Code Art. 378)', 'https://tradingeconomics.com/uzbekistan/deposit-interest-rate', '2026-10-31', 'Base case: tax-free som deposits a little below today''s average rate, as policy is eased over time.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UZ', 1, 'fixed_income_return_high', 0.15, NULL, 'assumption', 'Average deposit rate 14.7% in July 2026; policy rate 14% (Trading Economics)', 'https://tradingeconomics.com/uzbekistan/deposit-interest-rate', '2026-10-31', 'High case: locking in today''s higher term-deposit rates for several years.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UZ', 1, 'fixed_income_return_low', 0.09, NULL, 'assumption', 'Average deposit rate 13.9% (Aug 2026), tax-free; policy rate 14% (Trading Economics)', 'https://tradingeconomics.com/uzbekistan/deposit-interest-rate', '2026-10-31', 'Low case: deposit rates fall as the central bank cuts towards a 5% inflation target.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UZ', 1, 'goal_inflation_education', 0.08, NULL, 'assumption', 'Headline CPI 6.4% (Sep 2026, Trading Economics)', 'https://tradingeconomics.com/uzbekistan/inflation-cpi', '2026-10-31', 'No education CPI was found; private schooling and university contract fees have risen faster than headline inflation, so 8% is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UZ', 1, 'goal_inflation_health', 0.08, NULL, 'assumption', 'Headline CPI 6.4% (Sep 2026, Trading Economics); out-of-pocket share 64% of health spending (World Bank)', 'https://tradingeconomics.com/uzbekistan/inflation-cpi', '2026-10-31', 'No medical CPI was found; with most health spending paid privately and services prices rising faster than goods, 8% is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UZ', 1, 'gold_return_base', 0.075, NULL, 'assumption', 'Gold price history (Trading Economics); USD/UZS 11,996 (Oct 2026) vs 12,579 average in 2025 (World Bank)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Base case: dollar gold rises about 3.5% a year and the som loses about 4% a year against the dollar over the long run, as inflation stays above US levels.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UZ', 1, 'gold_return_high', 0.12, NULL, 'assumption', 'Gold price history (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'High case: a repeat of gold''s strong 2005-2025 dollar trend plus som depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UZ', 1, 'gold_return_low', 0.03, NULL, 'assumption', 'Gold USD 3,876/oz on 30 Oct 2026, 31% below the January 2026 high (Trading Economics); som roughly stable in 2026', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Low case: dollar gold stagnates after the 2025-26 spike and the som stays stable.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UZ', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No statutory gratuity or end-of-service payment for private employees on resignation or retirement was found; the Labour Code text was not checked in full.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UZ', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No official or survey figure for the typical out-of-pocket cost of a major private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UZ', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No regulator or government source with indicative private health insurance premiums by age was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UZ', 1, 'inflation_cpi', 0.064, NULL, 'sourced', 'Trading Economics, Uzbekistan inflation rate (Statistics Agency data)', 'https://tradingeconomics.com/uzbekistan/inflation-cpi', '2026-09-30', 'Secondary source: annual CPI inflation 6.4% in September 2026 (6.2% in August); the Statistics Agency (stat.uz) publishes the CPI only as downloadable tables. World Bank 2025 average 8.8%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UZ', 1, 'inflation_projection', 0.065, NULL, 'assumption', 'Central Bank of Uzbekistan 5% target; CPI 6.4% (Sep 2026), 8.8% in 2025 (World Bank), 2006-2026 average about 9.8% (Trading Economics)', 'https://tradingeconomics.com/uzbekistan/inflation-cpi', '2026-10-31', 'Inflation has fallen towards the central bank''s 5% target but has not yet reached it and averaged near 10% for two decades, so 6.5% is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UZ', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No regulator or government source with indicative term-life premiums by age was found; the life insurance market is small and quotes come only from insurers.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UZ', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The insurance regulator (National Agency for Prospective Projects) publishes market statistics, but no industry-wide life claim settlement ratio was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UZ', 1, 'life_expectancy', 72.8, NULL, 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/uzbekistan', '2026-07-01', 'Men 69.8, women 75.8 (UN WPP estimate for 2026); World Bank 2024 figure 72.5.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UZ', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":18.7,"men":16.7,"women":20.6},{"age":65,"total":15.2,"men":13.4,"women":16.7},{"age":70,"total":12,"men":10.5,"women":13.1},{"age":80,"total":6.8,"men":6,"women":7.2}]}', 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/uzbekistan', '2026-07-01', 'Remaining years computed from georank''s expected age at death by current age (UN WPP 2026 estimate).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UZ', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":65,"womenAge":60,"over90Monthly":null,"meansTested":true}', 'sourced', 'Unified portal of interactive public services (gov.uz), allowances to elderly and disabled citizens without work record', 'https://gov.uz/en/advice/64/document/1884', '2026-10-31', 'Paid to men from 65 and women from 60 who have no work record or too short a record for a pension (mothers of children disabled from childhood from 55); payment stops if the person has paid work or another income, so it is treated as income-tested. Rules from Presidential Decree UP-6241 (2021) and Cabinet Resolution No. 119 (2023), still in force.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UZ', 1, 'old_age_allowance_monthly', 878000, NULL, 'sourced', 'Presidential Decree No. UP-115 of 23 June 2026 ''On increasing wages, pensions, stipends and allowances''', 'https://lex.uz/ru/docs/8283680', '2026-07-01', 'Allowance for elderly citizens without the required work record: 878,000 som a month from 1 July 2026 (pensions and allowances raised 7%). The minimum old-age pension is 983,000 som. Paid from 65 (men) or 60 (women) to people without the work record needed for a pension (gov.uz).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UZ', 1, 'oop_health_share', 0.6406, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=UZ', '2023-12-31', 'Latest year available is 2023 (older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UZ', 1, 'policy_rate', 0.14, NULL, 'sourced', 'Trading Economics, Uzbekistan interest rate (Central Bank of Uzbekistan policy rate)', 'https://tradingeconomics.com/uzbekistan/interest-rate', '2026-09-16', 'Secondary source (cbu.uz unreachable): the central bank kept its key rate at 14% on 16 September 2026, as at the June and July meetings; the next scheduled meeting shown is 16 December 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UZ', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":60,"nomineeUntilAge":null,"inflationLinked":true,"taxFree":true}', 'sourced', 'Law ''On state pension provision of citizens'' No. 938-XII (Articles 7, 8, 49 and 67)', 'https://lex.uz/ru/docs/112312', '2026-10-31', 'State old-age pension funded by social tax: from 60 for men (25 years'' work) and 55 for women (20 years), 55% of average monthly earnings plus increments, not less than the minimum pension (983,000 som a month from 1 July 2026, Decree UP-115). Pensions are indexed by presidential acts taking account of the year''s consumer price inflation (Art. 49, as amended in 2024; 7% from 1 July 2026) and are exempt from tax (Art. 67). A draft decree (September 2026, not found adopted) would raise pension ages gradually from 2028 to 63 (men) and 58 (women).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UZ', 1, 'retirement_accumulation_return_base', 0.115, NULL, 'assumption', 'Fixed income base 12%; equity base 12%', 'https://tradingeconomics.com/uzbekistan/deposit-interest-rate', '2026-10-31', 'Base case: a mix of tax-free som deposits and global equity, both near 12% in som terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UZ', 1, 'retirement_accumulation_return_high', 0.15, NULL, 'assumption', 'Fixed income high 15%; equity high 16%', 'https://tradingeconomics.com/uzbekistan/deposit-interest-rate', '2026-10-31', 'High case for a growth-leaning balanced mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UZ', 1, 'retirement_accumulation_return_low', 0.08, NULL, 'assumption', 'Fixed income low 9%; equity low 7%', 'https://tradingeconomics.com/uzbekistan/deposit-interest-rate', '2026-10-31', 'Low case for a balanced mix if deposit rates fall and global shares lag.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UZ', 1, 'retirement_age_default', 60, NULL, 'sourced', 'Law ''On state pension provision of citizens'' No. 938-XII, Article 7', 'https://lex.uz/ru/docs/112312', '2026-10-31', 'Old-age pension from 60 for men with at least 25 years of work and 55 for women with at least 20 years; with 7 or more years a proportional pension is paid (Article 8, as amended in 2024). These ages apply to people born after 1975 under current law. A draft presidential decree put to public discussion in September 2026 would end early retirement from 2027 and raise the age by 3 months a year from 2028 to 63 (men) and 58 (women) by 2039; no adoption was found by 31 October 2026 (Spot, https://www.spot.uz/en/2026/09/15/pension-age/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UZ', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'No separate retirement age for government employees was found; civil servants receive the general state pension from 60 (men) or 55 (women) under the same law.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UZ', 1, 'retirement_return_base', 0.11, NULL, 'assumption', 'Average deposit rate 13.9% (Aug 2026), tax-free (Trading Economics)', 'https://tradingeconomics.com/uzbekistan/deposit-interest-rate', '2026-10-31', 'Base case kept below today''s tax-free average deposit rate, allowing for rate cuts over a long retirement.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UZ', 1, 'retirement_return_high', 0.13, NULL, 'assumption', 'Average deposit rate 13.9% (Aug 2026), tax-free (Trading Economics)', 'https://tradingeconomics.com/uzbekistan/deposit-interest-rate', '2026-10-31', 'High case: a retiree keeps most savings in multi-year term deposits near today''s rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UZ', 1, 'retirement_return_low', 0.08, NULL, 'assumption', 'Average deposit rate 13.9% (Aug 2026), tax-free (Trading Economics)', 'https://tradingeconomics.com/uzbekistan/deposit-interest-rate', '2026-10-31', 'Low case: deposit rates fall sharply as inflation reaches the 5% target.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UZ', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate or retail savings bond sold to individuals at a fixed rate was found; the Ministry of Economy and Finance sells government bonds through auctions on the Republican Currency Exchange.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UZ', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical rate for ordinary savings (demand) deposits was found; the Central Bank of Uzbekistan site (cbu.uz), which publishes deposit-rate statistics, could not be reached.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UZ', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":10.32},{"year":2040,"value":7.25},{"year":2065,"value":4.78}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/uzbekistan/2040/', '2025-12-31', '100 / old-age dependency ratio: 9.69 (2025, World Bank), 13.8 (2040) and 20.9 (2065, populationpyramid.net/uzbekistan/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UZ', 1, 'tax_bank_interest', 0, NULL, 'sourced', 'Tax Code of the Republic of Uzbekistan, Article 378 (income not subject to tax), item 13', 'https://lex.uz/ru/docs/4674893', '2026-10-31', 'Income on savings certificates and government securities, and interest and winnings on bank deposits, are exempt from personal income tax (Art. 378, item 13; item 12 also exempts interest on government securities). Other interest and dividends are taxed at 5% (Art. 381).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UZ', 1, 'tax_sanchayapatra_profit', 0, NULL, 'sourced', 'Tax Code of the Republic of Uzbekistan, Article 378, items 12 and 13', 'https://lex.uz/ru/docs/4674893', '2026-10-31', 'Interest on government securities of Uzbekistan and income on savings certificates are exempt from personal income tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UZ', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Short-term government bond auction results are published by the Republican Currency Exchange as images or attachments that could not be read, and the Ministry of Economy and Finance site gave no yields.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UZ', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 10-year domestic government bond yield was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('UZ', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 5-year government bond yield could be read; the latest auctions seen were additional placements of 1,074-day (about 3-year) bonds on 27 and 29 October 2026 whose yields were not shown in text.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('VA', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"VA","iso3":"VAT","nameEn":"Holy See","nameNative":"Santa Sede","region":"europe_central_asia","languages":["it","la"],"currency":{"code":"EUR","symbol":"€","decimals":2,"compact":"intl","usdRate":{"value":0.8951,"status":"sourced","sourceName":"European Central Bank euro reference rate (USD)","sourceUrl":"https://data-api.ecb.europa.eu/service/data/EXR/D.USD.EUR.SP00.A","asOf":"2026-10-30","note":"Vatican City uses the euro under its monetary convention with the EU; EUR 1 = USD 1.1172 on 30 October 2026, so about EUR 0.895 per US dollar."}},"instruments":{"savings_account":{"available":true,"localName":"Conto corrente","localNameEn":"Bank account","note":"A single Vatican financial institution, supervised by the Supervisory and Financial Information Authority (ASIF), holds accounts for eligible clergy, employees and Church bodies."},"fdr_3m":{"available":false,"localName":null,"localNameEn":null,"note":"No domestic term deposit market with published terms was found."},"fdr_1y":{"available":false,"localName":null,"localNameEn":null,"note":"No domestic term deposit market with published terms was found."},"dps":{"available":false,"localName":null,"localNameEn":null},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No savings certificates issued by the Holy See were found."},"tbill_91d":{"available":false,"localName":null,"localNameEn":null,"note":"No treasury bills issued by the Holy See were found."},"tbond_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government bonds issued by the Holy See were found."},"tbond_10y":{"available":false,"localName":null,"localNameEn":null},"equity_fund":{"available":false,"localName":null,"localNameEn":null,"note":"No domestic investment fund market was found."},"gold":{"available":true,"localName":"Monete d''oro","localNameEn":"Gold coins","note":"Vatican City State issues one gold coin a year (collector coins, not legal tender); gold bars and coins can also be bought in Italy.","sourceUrl":"https://www.vaticanstate.va/it/stato-e-governo/note-generali/monete-e-francobolli.html"}},"institutions":{"centralBank":null,"insuranceRegulator":null,"insuranceComplaints":null,"pensionScheme":{"name":"Fondo Pensioni (Vatican Pension Fund)","url":"https://www.vatican.va/roman_curia/labour_office/docs/documents/ulsa_b17_2_it.html","note":"Pension fund for employees of the Holy See and Vatican City State; the link is the Labour Office of the Apostolic See bulletin on voluntary contributions to the fund."},"oldAgeAllowance":null,"publicHealthCover":{"name":"Fondo Assistenza Sanitaria (FAS), Holy See health assistance fund","url":"https://www.vatican.va/content/romancuria/it/fas/fondo-assistenza-sanitaria.index.html","note":"Health assistance fund of the Holy See (listed among bodies linked to the Roman Curia); details are at fas.va."},"depositInsurance":null,"statistics":null},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VA', 1, 'bank_deposit_avg_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Vatican City has no national statistics office, banking-statistics series or securities market of its own; World Bank FR.INR.DPST has no figure for the Holy See.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VA', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap or typical credit card rate for Vatican City was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VA', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No deposit guarantee scheme for Vatican City was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VA', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No monthly recurring deposit scheme was found in Vatican City.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VA', 1, 'equity_return_base', 0.055, NULL, 'assumption', 'Euro-area household deposits up to 1 year 2.33% (ECB, Sep 2026); global equity in euros', 'https://data-api.ecb.europa.eu/service/data/MIR/M.U2.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Vatican City has no stock market, so the base uses a diversified global equity index in euro terms, held to the euro safe rate plus about 3.5 points.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VA', 1, 'equity_return_high', 0.075, NULL, 'assumption', 'Long-run global equity returns in euros', 'https://data-api.ecb.europa.eu/service/data/MIR/M.U2.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'High case: a diversified global equity fund matches long-run equity returns of about 7-8% in euros.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VA', 1, 'equity_return_low', 0.03, NULL, 'assumption', 'Euro-area household deposits up to 1 year 2.33% (ECB, Sep 2026); global equity in euros', 'https://data-api.ecb.europa.eu/service/data/MIR/M.U2.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'With no local stock market, the low case assumes a global equity fund in euros earns only about 1 point more than euro deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VA', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Vatican City has no national statistics office, banking-statistics series or securities market of its own; no 1-year term deposit rate was found. Euro-area banks paid households 2.33% on new deposits fixed up to 1 year in September 2026 (ECB MIR).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VA', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Vatican City has no national statistics office, banking-statistics series or securities market of its own; no 3-month term deposit rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VA', 1, 'fixed_income_return_base', 0.018, NULL, 'assumption', 'Euro-area household deposits up to 1 year 2.33% (ECB MFI statistics, Sep 2026); ECB deposit rate 2.50%', 'https://data-api.ecb.europa.eu/service/data/MIR/M.U2.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Base case: euro term deposits a little below today''s rate, as no local safe instrument or tax rule was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VA', 1, 'fixed_income_return_high', 0.025, NULL, 'assumption', 'ECB deposit facility rate 2.50% (Sep 2026)', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.en.html', '2026-10-31', 'High case: euro safe assets keep paying about today''s ECB deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VA', 1, 'fixed_income_return_low', 0.012, NULL, 'assumption', 'Euro-area household deposits up to 1 year 2.33% (ECB MFI statistics, Sep 2026)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.U2.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Low case: euro deposit rates drift lower if the ECB cuts again.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VA', 1, 'goal_inflation_education', 0.03, NULL, 'assumption', 'ECB 2% inflation target; education services costs rise faster than average', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.en.html', '2026-10-31', 'No education price index exists for Vatican City; euro-area school and university fees tend to rise about 1 point faster than the 2% target.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VA', 1, 'goal_inflation_health', 0.03, NULL, 'assumption', 'ECB 2% inflation target; health services costs rise faster than average', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.en.html', '2026-10-31', 'No medical price index exists for Vatican City; euro-area health costs tend to rise about 1 point faster than the 2% target.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VA', 1, 'gold_return_base', 0.04, NULL, 'assumption', 'Gold price history (Trading Economics); ECB 2% inflation target', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Base case: dollar gold rises roughly with world inflation plus a little, and the euro is assumed stable against the dollar over the long run.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VA', 1, 'gold_return_high', 0.07, NULL, 'assumption', 'Gold price history (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'High case: a repeat of gold''s strong 2005-2025 trend in euro terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VA', 1, 'gold_return_low', 0.01, NULL, 'assumption', 'Gold USD 3,876/oz on 30 Oct 2026, 31% below the January 2026 high (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Low case: gold barely keeps up after the 2025-26 spike, with no help from the euro.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VA', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'Holy See staff are reported to receive an end-of-service payment (liquidazione) under the Curia staff regulations, but no official text with the formula could be read, so it is left missing.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VA', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No figure for hospital costs in Vatican City was found; the Holy See runs a health assistance fund (FAS) for its staff.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VA', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No private health insurance premiums for Vatican City were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VA', 1, 'inflation_cpi', NULL, NULL, 'missing', '', '', '2026-10-31', 'Vatican City has no national statistics office, banking-statistics series or securities market of its own; no consumer price index for Vatican City was found. Prices follow the euro area and Rome (Italian ISTAT CPI).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VA', 1, 'inflation_projection', 0.02, NULL, 'assumption', 'European Central Bank 2% inflation target (Vatican City uses the euro)', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.en.html', '2026-10-31', 'Vatican City uses the euro under a monetary convention with the EU, so the ECB''s credible 2% medium-term target is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VA', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No term life insurance market in Vatican City and no published premiums were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VA', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Vatican City has no domestic life insurance market or published claim statistics.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VA', 1, 'life_expectancy', NULL, NULL, 'missing', '', '', '2026-10-31', 'The UN World Population Prospects, World Bank and WHO do not publish life expectancy for the Holy See, whose few hundred residents are mostly adult clergy, Swiss Guards and staff.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VA', 1, 'life_table_remaining', NULL, NULL, 'missing', '', '', '2026-10-31', 'No life table for the Holy See is published by the UN, WHO or World Bank.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VA', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension for Vatican City was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VA', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension for Vatican City was found; pensions are paid to former staff by the Vatican Pension Fund.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VA', 1, 'oop_health_share', NULL, NULL, 'missing', '', '', '2026-10-31', 'World Bank and WHO health expenditure data do not cover the Holy See.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VA', 1, 'policy_rate', 0.025, NULL, 'sourced', 'European Central Bank key interest rates (deposit facility rate)', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.en.html', '2026-09-16', 'Vatican City uses the euro and has no central bank of its own (Governorate, Monete e francobolli); the ECB deposit facility rate has been 2.50% since 16 September 2026 (main refinancing 2.65%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VA', 1, 'public_pension_scheme', NULL, NULL, 'missing', '', '', '2026-10-31', 'Staff of the Holy See and Vatican City State are covered by the Vatican Pension Fund (Fondo Pensioni): lay staff retire at 67 (Avvenire, 5 August 2009), a pension needs at least 20 years'' service (Secretariat of State rescript of 16 January 2010, https://www.vatican.va/roman_curia/labour_office/docs/documents/ulsa_b17_2_it.html) and the ordinary contribution rate rose from 25% to 26% of pay in 2010 (Avvenire); the benefit formula and whether pensions are indexed to prices were not found, so the scheme is not filled in.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VA', 1, 'retirement_accumulation_return_base', 0.035, NULL, 'assumption', 'Euro fixed income base 1.8%; global equity base 5.5%', 'https://data-api.ecb.europa.eu/service/data/MIR/M.U2.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Base case: roughly half global shares and half euro safe assets.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VA', 1, 'retirement_accumulation_return_high', 0.05, NULL, 'assumption', 'Euro fixed income high 2.5%; global equity high 7.5%', 'https://data-api.ecb.europa.eu/service/data/MIR/M.U2.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'High case for a growth-leaning balanced mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VA', 1, 'retirement_accumulation_return_low', 0.02, NULL, 'assumption', 'Euro deposits about 2%; global equity low 3%', 'https://data-api.ecb.europa.eu/service/data/MIR/M.U2.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Low case for a balanced mix if shares lag.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VA', 1, 'retirement_age_default', 67, NULL, 'sourced', 'Avvenire (news), ''Il Vaticano alza l''età e i contributi'' (Vatican Pension Fund reform in force 1 January 2010)', 'https://www.avvenire.it/rubriche/pensioni-e-previdenza/il-vaticano-alza-leta-e-i-contributi_5232', '2010-01-01', 'Secondary source, older than 2025 (article of 5 August 2009): since 1 January 2010 lay staff of the Holy See and Vatican City State hired from 2010 retire at 67 (clergy and religious not before 72); there is no private-sector labour market, the Holy See and the State being the employers. No later change to the general age was confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VA', 1, 'retirement_age_government', 67, NULL, 'sourced', 'Avvenire (news), ''Il Vaticano alza l''età e i contributi'' (Vatican Pension Fund reform in force 1 January 2010)', 'https://www.avvenire.it/rubriche/pensioni-e-previdenza/il-vaticano-alza-leta-e-i-contributi_5232', '2010-01-01', 'Secondary source, older than 2025: under the reform in force from 1 January 2010, lay employees hired from 2010 retire at 67 and clergy and religious not before 72; cardinals and bishops heading Curia dicasteries keep the age limit of 75. No later change to the general age was confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VA', 1, 'retirement_return_base', 0.018, NULL, 'assumption', 'Euro-area household deposits up to 1 year 2.33% (ECB MFI statistics, Sep 2026)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.U2.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Base case kept below the euro-area 1-year deposit rate, as no local safe instrument exists.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VA', 1, 'retirement_return_high', 0.025, NULL, 'assumption', 'ECB deposit facility rate 2.50% (Sep 2026)', 'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.en.html', '2026-10-31', 'High case: a retiree holds euro safe assets paying about today''s ECB deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VA', 1, 'retirement_return_low', 0.01, NULL, 'assumption', 'Euro-area household deposits up to 1 year 2.33% (ECB MFI statistics, Sep 2026)', 'https://data-api.ecb.europa.eu/service/data/MIR/M.U2.B.L22.F.R.A.2250.EUR.N', '2026-10-31', 'Low case: euro deposit rates fall back after ECB cuts.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VA', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate or retail bond issued by the Holy See or Vatican City State was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VA', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Vatican City has no national statistics office, banking-statistics series or securities market of its own; a single Vatican financial institution serves clergy, employees and Church bodies and publishes no account rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VA', 1, 'support_ratio', NULL, NULL, 'missing', '', '', '2026-10-31', 'The UN World Population Prospects do not publish population projections or dependency ratios for the Holy See; World Bank SP.POP.DPND.OL has no figure.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VA', 1, 'tax_bank_interest', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published rule on the taxation of bank interest for Vatican residents was found; PwC Tax Summaries does not cover the Holy See.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VA', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate exists to tax, and no tax rule was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VA', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No treasury bills issued by the Holy See or Vatican City State were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VA', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government bonds issued by the Holy See or Vatican City State were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VA', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government bonds issued by the Holy See or Vatican City State were found.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('VC', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"VC","iso3":"VCT","nameEn":"Saint Vincent and the Grenadines","nameNative":"Saint Vincent and the Grenadines","region":"latin_america_caribbean","languages":["en","svc"],"currency":{"code":"XCD","symbol":"$","decimals":2,"compact":"intl","usdRate":{"value":2.7,"status":"sourced","sourceName":"World Bank WDI PA.NUS.FCRF","sourceUrl":"https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=VC","asOf":"2025-12-31","note":"The EC dollar has been fixed at 2.70 per US dollar by the Eastern Caribbean Central Bank since 1976."}},"instruments":{"savings_account":{"available":true,"localName":"Savings account","note":"ECCB minimum savings rate 2%.","sourceUrl":"https://www.eccb-centralbank.org/statistics-category/mfs-interest-rates/interest-rates-on-deposits-and-loans/m?country_code[]=8"},"fdr_3m":{"available":true,"localName":"Fixed deposit","localNameEn":"3-month fixed (time) deposit","note":"Posted rates 0.10-1.50% (2026).","sourceUrl":"https://www.eccb-centralbank.org/statistics-category/mfs-interest-rates/interest-rates-on-deposits-and-loans/m?country_code[]=8"},"fdr_1y":{"available":true,"localName":"Fixed deposit","localNameEn":"12-month fixed (time) deposit","note":"Posted rates 0.10-4.00% (2026).","sourceUrl":"https://www.eccb-centralbank.org/statistics-category/mfs-interest-rates/interest-rates-on-deposits-and-loans/m?country_code[]=8"},"dps":{"available":false,"localName":null,"note":"No standard monthly recurring deposit product with a published rate."},"sanchayapatra_5y":{"available":false,"localName":null,"note":"No government savings certificate or retail savings bond for individuals was found."},"tbill_91d":{"available":true,"localName":"Treasury bill","localNameEn":"Government of Saint Vincent and the Grenadines 91-day Treasury bill","note":"Auctioned on the Regional Government Securities Market through licensed intermediaries; mostly bought by institutions.","sourceUrl":"https://www.eccb-centralbank.org/statistics-category/regional-government-securities-market/weighted-average-interest-rates-on-the-rgsm/m?country_code[]=8"},"tbond_5y":{"available":false,"localName":null,"note":"No government bonds were auctioned on the regional market in 2021-2026.","sourceUrl":"https://www.eccb-centralbank.org/statistics-category/regional-government-securities-market/weighted-average-interest-rates-on-the-rgsm/a?country_code[]=8"},"tbond_10y":{"available":false,"localName":null,"note":"No government bonds were auctioned on the regional market in 2021-2026.","sourceUrl":"https://www.eccb-centralbank.org/statistics-category/regional-government-securities-market/weighted-average-interest-rates-on-the-rgsm/a?country_code[]=8"},"equity_fund":{"available":false,"localName":null,"note":"No locally registered retail equity or index fund was identified; the regional share market is very small."},"gold":{"available":true,"localName":"Gold","localNameEn":"Gold jewellery and coins","note":"No legal restriction on buying gold; mostly sold as jewellery."}},"institutions":{"centralBank":{"name":"Eastern Caribbean Central Bank (ECCB)","url":"https://www.eccb-centralbank.org/","note":"Shared central bank of the Eastern Caribbean Currency Union."},"insuranceRegulator":{"name":"Financial Services Authority (FSA) Saint Vincent and the Grenadines","url":"https://fsasvg.com/licensed-insurance-and-pension-plans-2/"},"insuranceComplaints":{"name":"Financial Services Authority (FSA), file a complaint","url":"https://fsasvg.com/file-complaint/","note":"No separate insurance ombudsman; complaints about regulated insurers go to the FSA."},"pensionScheme":{"name":"National Insurance Services (NIS)","url":"https://www.nissvg.org/"},"oldAgeAllowance":null,"publicHealthCover":{"name":"Ministry of Health, Wellness and the Environment (public hospitals and district clinics)","url":"https://health.gov.vc/health/"},"depositInsurance":null,"statistics":{"name":"Statistical Office, Saint Vincent and the Grenadines","url":"https://stats.gov.vc/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VC', 1, 'bank_deposit_avg_rate', 0.0123, NULL, 'sourced', 'ECCB, Interest Rates and Weighted Average Rates on Deposits and Loans: Saint Vincent and the Grenadines', 'https://www.eccb-centralbank.org/statistics-category/mfs-interest-rates/interest-rates-and-weighted-averages-rates-on-deposits-and-loans/q?country_code[]=8', '2026-06-30', 'Weighted average rate on all EC-dollar deposits 1.23% in June 2026 (1.17% including foreign-currency deposits); World Bank deposit rate 1.24% (2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VC', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap on credit card interest was found; the ECCB publishes only an ''other lending rates'' range of 3.50-22.00% for Saint Vincent and the Grenadines (August 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VC', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched ECCB sources: the regional Eastern Caribbean deposit insurance arrangement is not shown as operating, and no deposit insurance cover limit for Saint Vincent and the Grenadines was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VC', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched the ECCB interest rate tables for Saint Vincent and the Grenadines: no monthly recurring deposit product rate is published.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VC', 1, 'equity_return_base', 0.065, NULL, 'assumption', 'ECCB RGSM: Saint Vincent and the Grenadines 91-day Treasury bill 3.50% (September 2026)', 'https://www.eccb-centralbank.org/statistics-category/regional-government-securities-market/weighted-average-interest-rates-on-the-rgsm/m?country_code[]=8', '2026-10-31', 'Base case uses a global equity index in EC-dollar terms (pegged to the US dollar): the 3.5% tax-free safe rate plus a 3-point premium, as the local market is too thin to have a usable 10-year record.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VC', 1, 'equity_return_high', 0.09, NULL, 'assumption', 'ECCB RGSM: Saint Vincent and the Grenadines 91-day Treasury bill 3.50% (September 2026)', 'https://www.eccb-centralbank.org/statistics-category/regional-government-securities-market/weighted-average-interest-rates-on-the-rgsm/m?country_code[]=8', '2026-10-31', 'High case if global equities repeat their strong long-run US-dollar returns.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VC', 1, 'equity_return_low', 0.02, NULL, 'assumption', 'ECCB RGSM: Saint Vincent and the Grenadines 91-day Treasury bill 3.50% (September 2026)', 'https://www.eccb-centralbank.org/statistics-category/regional-government-securities-market/weighted-average-interest-rates-on-the-rgsm/m?country_code[]=8', '2026-10-31', 'Low case: the regional share market is very small, so savers rely mostly on global equity funds in pegged US-dollar terms, and a weak decade is possible.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VC', 1, 'fdr_1y_rate', 0.0187, NULL, 'sourced', 'ECCB, Interest Rates and Weighted Average Rates on Deposits and Loans: Saint Vincent and the Grenadines', 'https://www.eccb-centralbank.org/statistics-category/mfs-interest-rates/interest-rates-and-weighted-averages-rates-on-deposits-and-loans/q?country_code[]=8', '2026-06-30', 'Posted 12-month EC-dollar time-deposit rates ranged 0.10-4.00% (May-August 2026); the weighted average on all EC-dollar time deposits was 1.87% in June 2026, used here as the typical rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VC', 1, 'fdr_3m_rate', 0.015, NULL, 'sourced', 'ECCB, Interest Rates on Deposits and Loans: Saint Vincent and the Grenadines', 'https://www.eccb-centralbank.org/statistics-category/mfs-interest-rates/interest-rates-on-deposits-and-loans/m?country_code[]=8', '2026-08-31', 'Posted 3-month EC-dollar time-deposit rates ranged 0.10-1.50% (May-August 2026); the top of the range is used as the rate a saver can get.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VC', 1, 'fixed_income_return_base', 0.025, NULL, 'assumption', 'ECCB: savings rate 2.00% (2026); 91-day Treasury bill 3.50% (September 2026)', 'https://www.eccb-centralbank.org/statistics-category/regional-government-securities-market/weighted-average-interest-rates-on-the-rgsm/m?country_code[]=8', '2026-10-31', 'Base case: a mix of tax-free savings deposits at 2% and Treasury bills near 3.5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VC', 1, 'fixed_income_return_high', 0.035, NULL, 'assumption', 'ECCB RGSM: Saint Vincent and the Grenadines 91-day Treasury bill 3.50% (September 2026)', 'https://www.eccb-centralbank.org/statistics-category/regional-government-securities-market/weighted-average-interest-rates-on-the-rgsm/m?country_code[]=8', '2026-10-31', 'High case: rolling 91-day Treasury bills at about 3.5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VC', 1, 'fixed_income_return_low', 0.015, NULL, 'assumption', 'ECCB Saint Vincent and the Grenadines: posted 3-month deposits up to 1.50%, weighted time-deposit rate 1.87% (2026)', 'https://www.eccb-centralbank.org/statistics-category/mfs-interest-rates/interest-rates-and-weighted-averages-rates-on-deposits-and-loans/q?country_code[]=8', '2026-10-31', 'Low case: savings and short deposits at about 1.5-2%, tax-free for residents.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VC', 1, 'goal_inflation_education', 0.035, NULL, 'assumption', 'ECCB CPI Saint Vincent and the Grenadines: education index 109.1 (2021) to 120.4 (2025), about 2.5% a year', 'https://www.eccb-centralbank.org/statistics-category/other-real-sector/consumer-price-index-saint-vincent-and-the-grenadines/a', '2026-10-31', 'Education prices rose about 2.5% a year in 2021-2025; we plan with 3.5% to allow for overseas tertiary study, which most students need.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VC', 1, 'goal_inflation_health', 0.04, NULL, 'assumption', 'ECCB CPI Saint Vincent and the Grenadines: health index 115.8 (2021) to 128.8 (2025), about 2.7% a year', 'https://www.eccb-centralbank.org/statistics-category/other-real-sector/consumer-price-index-saint-vincent-and-the-grenadines/a', '2026-10-31', 'Health prices rose about 2.7% a year in 2021-2025; we plan with 4% to allow for private and overseas treatment costs, which the CPI barely covers.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VC', 1, 'gold_return_base', 0.045, NULL, 'assumption', 'ECCB: EC dollar fixed at 2.70 per US dollar; World Bank PA.NUS.FCRF 2.70 (2025)', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=VC', '2026-10-31', 'Long-run dollar gold trend of about 4-5% a year, with no expected depreciation of the pegged EC dollar.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VC', 1, 'gold_return_high', 0.08, NULL, 'assumption', 'ECCB: EC dollar fixed at 2.70 per US dollar; World Bank PA.NUS.FCRF 2.70 (2025)', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=VC', '2026-10-31', 'High case with strong dollar gold prices.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VC', 1, 'gold_return_low', 0.01, NULL, 'assumption', 'ECCB: EC dollar fixed at 2.70 per US dollar; World Bank PA.NUS.FCRF 2.70 (2025)', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=VC', '2026-10-31', 'Low case: weak dollar gold price, and the long-standing peg gives no currency boost.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VC', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'Could not confirm whether the Protection of Employment Act provides any payment on retirement (the Act text could not be read); severance is known to apply on redundancy and dismissal.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VC', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a major private hospital stay was found; the Ministry of Health website was unavailable during this research.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VC', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No regulator or other non-company source publishing private health insurance premiums by age was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VC', 1, 'inflation_cpi', 0.02, NULL, 'sourced', 'ECCB, Consumer Price Index Saint Vincent and the Grenadines (Statistical Office data)', 'https://www.eccb-centralbank.org/statistics-category/other-real-sector/consumer-price-index-saint-vincent-and-the-grenadines/m?start_date=31/05/2025&end_date=30/09/2026', '2026-06-30', 'All-items index 132.6 in June 2026 against 130.0 in June 2025, a 2.0% year-on-year rise (computed; the table''s monthly ''inflation rate'' column is month on month). 2025 average inflation was 0.91%. June 2026 is the latest month published.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VC', 1, 'inflation_projection', 0.025, NULL, 'assumption', 'ECCB CPI Saint Vincent and the Grenadines: period-average inflation 2021-2025 of 1.6%, 5.7%, 4.6%, 3.6% and 0.9%; EC dollar pegged at 2.70 per US dollar', 'https://www.eccb-centralbank.org/statistics-category/other-real-sector/consumer-price-index-saint-vincent-and-the-grenadines/a', '2026-10-31', 'The ECCB has no inflation target (the EC dollar is pegged to the US dollar), so we plan with 2.5%: close to US-dollar inflation, a little below the 3.3% 5-year average that includes the 2022-2023 import-price shock.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VC', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life cover is sold in Saint Vincent and the Grenadines by regional insurers, but no regulator or other non-company source publishes premium rates by age.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VC', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched the Financial Services Authority site (statistics page): no industry-wide life claim settlement ratio is published.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VC', 1, 'life_expectancy', 71.382, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=VC', '2024-12-31', 'Men 68.8, women 74.5 (2024). UN WPP 2024 via populationpyramid.net gives 71.7 for 2026 (men 69.0, women 74.8). The World Bank figure is for 2024, older than 2025 (latest published).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VC', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":18.5,"men":16.6,"women":20.3},{"age":65,"total":14.9,"men":13.4,"women":16.5},{"age":70,"total":11.8,"men":10.6,"women":12.9},{"age":80,"total":6.6,"men":6,"women":7.1}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/saint-vincent-and-the-grenadines/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for the year 2026 (asOf set to mid-year); sex-specific values are for the 5-year age groups starting at each age; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VC', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'No non-contributory old-age pension open to new claimants: eligibility is tied to age on 5 January 1987 (UN ECLAC non-contributory pensions database, https://dds.cepal.org/bpsnc/programa?id=150); poor older people rely on public assistance.', 1);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VC', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'The only non-contributory old-age pension, the Non-contributory Assistance Age Pension (EC$75 every two weeks), is limited to people who were over 57 (over 47 for the elderly support component; the page states both) on 5 January 1987, i.e. about 75 or older by 2017, so no one planning today can receive it (UN ECLAC non-contributory pensions database, https://dds.cepal.org/bpsnc/programa?id=150).', 1);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VC', 1, 'oop_health_share', 0.2657, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=VC', '2023-12-31', 'Out-of-pocket spending was 26.6% of current health expenditure in 2023 (latest available; older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VC', 1, 'policy_rate', 0.03, NULL, 'sourced', 'ECCB, Interest Rates on Deposits and Loans: Saint Vincent and the Grenadines (discount rate)', 'https://www.eccb-centralbank.org/statistics-category/mfs-interest-rates/interest-rates-on-deposits-and-loans/m?country_code[]=8', '2026-08-31', 'ECCB discount rate 3.00% (May-August 2026), the same for all ECCU members; with the peg it is a backstop rate rather than an active policy tool.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VC', 1, 'public_pension_scheme', NULL, NULL, 'missing', '', '', '2026-10-31', 'A compulsory contributory National Insurance Services age pension exists (NIS benefits are tax-exempt under Income Tax Act s.25(1)(w)), but its pensionable age and indexation rules could not be confirmed: the National Insurance Services website (nissvg.org) blocked automated reading during this research.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VC', 1, 'retirement_accumulation_return_base', 0.045, NULL, 'assumption', '91-day Treasury bill 3.50%; global equity assumptions in pegged EC dollars', 'https://www.eccb-centralbank.org/statistics-category/regional-government-securities-market/weighted-average-interest-rates-on-the-rgsm/m?country_code[]=8', '2026-10-31', 'Base case: half global equities at 6.5% and half deposits and bills around 2.5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VC', 1, 'retirement_accumulation_return_high', 0.065, NULL, 'assumption', '91-day Treasury bill 3.50%; global equity assumptions in pegged EC dollars', 'https://www.eccb-centralbank.org/statistics-category/regional-government-securities-market/weighted-average-interest-rates-on-the-rgsm/m?country_code[]=8', '2026-10-31', 'High case with stronger equity returns.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VC', 1, 'retirement_accumulation_return_low', 0.03, NULL, 'assumption', '91-day Treasury bill 3.50%; global equity assumptions in pegged EC dollars', 'https://www.eccb-centralbank.org/statistics-category/regional-government-securities-market/weighted-average-interest-rates-on-the-rgsm/m?country_code[]=8', '2026-10-31', 'Low case for a balanced mix if global equities disappoint.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VC', 1, 'retirement_age_default', NULL, NULL, 'missing', '', '', '2026-10-31', 'Could not confirm the current National Insurance Services pensionable age or any scheduled increase: the National Insurance Services website (nissvg.org) blocked automated reading during this research, and no other official or secondary source could be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VC', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'Could not confirm the statutory retirement age for public officers from a readable official source (government ministry sites were down during this research).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VC', 1, 'retirement_return_base', 0.025, NULL, 'assumption', 'ECCB: savings rate 2.00% (2026); 91-day Treasury bill 3.50% (September 2026)', 'https://www.eccb-centralbank.org/statistics-category/regional-government-securities-market/weighted-average-interest-rates-on-the-rgsm/m?country_code[]=8', '2026-10-31', 'Base case below the 3.5% tax-free Treasury bill rate: a mix of savings deposits and bills, kept liquid in retirement.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VC', 1, 'retirement_return_high', 0.034, NULL, 'assumption', 'ECCB RGSM: Saint Vincent and the Grenadines 91-day Treasury bill 3.50% (September 2026)', 'https://www.eccb-centralbank.org/statistics-category/regional-government-securities-market/weighted-average-interest-rates-on-the-rgsm/m?country_code[]=8', '2026-10-31', 'High case: rolling Treasury bills at about the latest auction rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VC', 1, 'retirement_return_low', 0.015, NULL, 'assumption', 'ECCB Saint Vincent and the Grenadines: posted 3-month deposits up to 1.50% (2026)', 'https://www.eccb-centralbank.org/statistics-category/mfs-interest-rates/interest-rates-on-deposits-and-loans/m?country_code[]=8', '2026-10-31', 'Low case: mostly tax-free savings and short deposits at about 1.5-2%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VC', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate or retail savings bond for individuals was found; the government borrows on the Regional Government Securities Market, where it issued only 91-day Treasury bills in 2021-2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VC', 1, 'savings_account_rate', 0.02, NULL, 'sourced', 'ECCB, Interest Rates on Deposits and Loans: Saint Vincent and the Grenadines', 'https://www.eccb-centralbank.org/statistics-category/mfs-interest-rates/interest-rates-on-deposits-and-loans/m?country_code[]=8', '2026-08-31', 'Posted EC-dollar savings rates were 2.00% (minimum and maximum) in May-August 2026, the ECCB 2% minimum savings rate; the weighted average on savings deposits was 1.89% in June 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VC', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":5.5},{"year":2040,"value":3.8},{"year":2065,"value":2.9}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/saint-vincent-and-the-grenadines/2040/', '2025-12-31', '100 / old-age dependency ratio: 18.3 (2025, World Bank), 26.0 (2040) and 34.3 (2065, populationpyramid.net/saint-vincent-and-the-grenadines/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VC', 1, 'tax_bank_interest', 0, NULL, 'sourced', 'Income Tax Act Cap. 435 (Saint Vincent and the Grenadines), s.25(1)(g)', 'https://ird.gov.vc/images/pdf/Cap435.pdf', '2009-12-31', 'Income accruing to any individual by way of interest on a deposit in any bank or building society in Saint Vincent and the Grenadines is exempt from income tax. Consolidated text amended to 2009 (older than 2025), published by the Inland Revenue Department; no later repeal found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VC', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate for individuals exists (see sanchayapatra_5y_rate), so no tax rate applies; the Income Tax Act s.25(1)(f) exempts only interest on government loans the Minister declares exempt.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VC', 1, 'tbill_91d_rate', 0.035, NULL, 'sourced', 'ECCB, Weighted Average Interest Rates on the RGSM: Saint Vincent and the Grenadines', 'https://www.eccb-centralbank.org/statistics-category/regional-government-securities-market/weighted-average-interest-rates-on-the-rgsm/m?country_code[]=8', '2026-09-30', '91-day Treasury bill weighted average 3.50% at the July, August and September 2026 auctions (2.86% average in 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VC', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 10-year government bond was auctioned on the Regional Government Securities Market in 2021-2026 (ECCB RGSM tables); no other published 10-year yield was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VC', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Government of Saint Vincent and the Grenadines auctioned no bonds of any tenor on the Regional Government Securities Market in 2021-2025 or May-September 2026 (ECCB RGSM annual and monthly tables); no other published 5-year yield was found.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('VE', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"VE","iso3":"VEN","nameEn":"Venezuela","nameNative":"Venezuela","region":"latin_america_caribbean","languages":["es"],"currency":{"code":"VES","symbol":"Bs.","decimals":2,"compact":"intl","usdRate":{"value":889.5754,"status":"sourced","sourceName":"Banco Central de Venezuela, tipo de cambio de referencia (SMC), US dollar selling rate, operation date 30 October 2026","sourceUrl":"https://www.bcv.org.ve/estadisticas/tipo-cambio-de-referencia-smc","asOf":"2026-10-30","note":"Bs. 889.5754 per US dollar (buying 887.3515) on 30 October 2026, against 223.96 on 31 October 2025, so the bolívar lost about three-quarters of its dollar value in a year. World Bank series stops in 2017."}},"instruments":{"savings_account":{"available":true,"localName":"Cuenta de ahorro","localNameEn":"Savings account","note":"Interest on savings deposits is tax-exempt (PwC)."},"fdr_3m":{"available":true,"localName":"Depósito a plazo fijo (90 días)","localNameEn":"Fixed-term deposit (90 days)"},"fdr_1y":{"available":true,"localName":"Depósito a plazo fijo (1 año)","localNameEn":"Fixed-term deposit (1 year)","note":"Long bolívar term deposits are rare because of high inflation."},"dps":{"available":false,"localName":null,"localNameEn":"Recurring deposit","note":"No standard monthly recurring deposit product was found."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":"Government savings certificate","note":"No retail government savings certificate was found."},"tbill_91d":{"available":false,"localName":"Letras del Tesoro","localNameEn":"Treasury bills","note":"No active public market or published yields were found."},"tbond_5y":{"available":false,"localName":"Bonos de la Deuda Pública Nacional","localNameEn":"Government bonds","note":"Domestic bolívar bonds are not actively traded; external dollar bonds have been in default since 2017."},"tbond_10y":{"available":false,"localName":"Bonos de la Deuda Pública Nacional","localNameEn":"Government bonds","note":"Domestic bolívar bonds are not actively traded; external dollar bonds have been in default since 2017."},"equity_fund":{"available":false,"localName":"Fondos mutuales","localNameEn":"Mutual funds","note":"Shares can be bought directly on the Caracas stock exchange, but no diversified retail index fund was found."},"gold":{"available":true,"localName":"Oro (lingotes y monedas)","localNameEn":"Gold (bars and coins)","note":"No legal restriction on individuals owning gold was found."}},"institutions":{"centralBank":{"name":"Banco Central de Venezuela (BCV)","url":"https://www.bcv.org.ve/"},"insuranceRegulator":{"name":"Superintendencia de la Actividad Aseguradora (SUDEASEG)","url":"https://www.sudeaseg.gob.ve/"},"insuranceComplaints":{"name":"SUDEASEG, Defensoría del Asegurado","url":"https://www.sudeaseg.gob.ve/defensor-del-asegurado","note":"Free line 0800 7832734."},"pensionScheme":{"name":"Instituto Venezolano de los Seguros Sociales (IVSS), pensión por vejez","url":"https://www.ivss.gob.ve/pensionado/tipos-pensiones"},"oldAgeAllowance":null,"publicHealthCover":{"name":"Ministerio del Poder Popular para la Salud (MPPS), public health system","url":"https://mpps.gob.ve/"},"depositInsurance":{"name":"Fondo de Protección Social de los Depósitos Bancarios (FOGADE)","url":"https://www.fogade.gob.ve/"},"statistics":{"name":"Instituto Nacional de Estadística (INE)","url":"https://www.ine.gob.ve/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VE', 1, 'bank_deposit_avg_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The BCV publishes weighted averages by product (September 2026: savings 37.9%, all term deposits 60.4%, nominative sight deposits 60.2%) but no single average across all deposits; the World Bank series stops in 2017 (14.7%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VE', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'The BCV sets maximum lending and credit card rates by resolution, but the current credit card cap was not confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VE', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'FOGADE guarantees bank deposits, but no current cover limit per depositor was found on its website (home and legal-framework pages read).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VE', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No monthly recurring deposit product or published rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VE', 1, 'equity_return_base', 0.5, NULL, 'assumption', 'BCV weighted average rates, September 2026: savings deposits 37.9%, term deposits 60.4% (90-day 46%); interest tax-exempt (PwC)', 'https://www.bcv.org.ve/estadisticas/tasas-de-interes', '2026-10-31', 'The Caracas stock exchange is small and illiquid with no long reliable record, so the base case stays at the 50% planning safe rate, well below the 100% inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VE', 1, 'equity_return_high', 1, NULL, 'assumption', 'Dollar-linked share prices rising with bolívar depreciation (BCV reference rate 223.96 to 889.58 per US dollar, October 2025 to October 2026)', 'https://www.bcv.org.ve/estadisticas/tipo-cambio-de-referencia-smc', '2026-10-31', 'High case: share prices keep pace with the dollar, so returns roughly match inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VE', 1, 'equity_return_low', 0.2, NULL, 'assumption', 'BCV weighted average rates, September 2026: savings deposits 37.9%, term deposits 60.4% (90-day 46%); interest tax-exempt (PwC)', 'https://www.bcv.org.ve/estadisticas/tasas-de-interes', '2026-10-31', 'Low case: Caracas-listed shares lose heavily in real terms, as bolívar assets usually have.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VE', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The BCV publishes term-deposit rates up to ''more than 90 days'', and no rate was reported in that bucket for September 2026; no 1-year rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VE', 1, 'fdr_3m_rate', 0.46, NULL, 'sourced', 'Banco Central de Venezuela, tasas de interés pasivas anuales nominales promedio ponderadas, bancos universales: depósitos a plazo, 90 días', 'https://www.bcv.org.ve/estadisticas/tasas-de-interes', '2026-09-30', '46% nominal a year in September 2026 (provisional); the 90-day market is thin and no rate was reported in several recent months; all term deposits averaged 60.4%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VE', 1, 'fixed_income_return_base', 0.5, NULL, 'assumption', 'BCV weighted average rates, September 2026: savings deposits 37.9%, term deposits 60.4% (90-day 46%); interest tax-exempt (PwC)', 'https://www.bcv.org.ve/estadisticas/tasas-de-interes', '2026-10-31', 'Base case: bolívar deposits keep paying well below inflation, as under the BCV''s controls for years; 50%, between the savings and term-deposit averages.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VE', 1, 'fixed_income_return_high', 0.6, NULL, 'assumption', 'BCV weighted average rates, September 2026: savings deposits 37.9%, term deposits 60.4% (90-day 46%); interest tax-exempt (PwC)', 'https://www.bcv.org.ve/estadisticas/tasas-de-interes', '2026-10-31', 'High case: term deposits near the current 60% average.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VE', 1, 'fixed_income_return_low', 0.3, NULL, 'assumption', 'BCV weighted average rates, September 2026: savings deposits 37.9%, term deposits 60.4% (90-day 46%); interest tax-exempt (PwC)', 'https://www.bcv.org.ve/estadisticas/tasas-de-interes', '2026-10-31', 'Low case: ordinary savings accounts (37.9% in September 2026, 32% for most of the past two years) pay far less than inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VE', 1, 'goal_inflation_education', 1, NULL, 'assumption', 'BCV INPC +465.6% year on year (September 2026)', 'https://www.bcv.org.ve/estadisticas/consumidor', '2026-10-31', 'No separate education price index was used, so education goals use the 100% general inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VE', 1, 'goal_inflation_health', 1, NULL, 'assumption', 'BCV INPC +465.6% year on year (September 2026)', 'https://www.bcv.org.ve/estadisticas/consumidor', '2026-10-31', 'No separate health price index was used, so health goals use the 100% general inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VE', 1, 'gold_return_base', 1, NULL, 'assumption', 'Gold USD price trend plus bolívar depreciation in line with the 100% inflation assumption (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Base case: gold holds its dollar value and gains about 4% a year, and the bolívar falls roughly in line with inflation, so gold about doubles in bolívares each year.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VE', 1, 'gold_return_high', 1.6, NULL, 'assumption', 'Bolívar depreciation of about 75% in the year to October 2026 (BCV reference rate)', 'https://www.bcv.org.ve/estadisticas/tipo-cambio-de-referencia-smc', '2026-10-31', 'High case: the bolívar keeps falling at recent speed and gold rises in dollars.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VE', 1, 'gold_return_low', 0.6, NULL, 'assumption', 'BCV reference rate 889.58 per US dollar on 30 October 2026, up from 223.96 a year earlier; gold about USD 3,900/oz', 'https://www.bcv.org.ve/estadisticas/tipo-cambio-de-referencia-smc', '2026-10-31', 'Low case: gold is flat in dollars and the bolívar loses about 40% of its value a year.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VE', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'The labour law (LOTTT) provides end-of-service social benefits (prestaciones sociales) for private employees, but the legal text could not be read from an official source, so the rule is not recorded.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VE', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical out-of-pocket cost of a private hospital stay was found; private clinics price mostly in US dollars.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VE', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No regulator or other non-company source of private health insurance premiums by age was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VE', 1, 'inflation_cpi', 4.656, NULL, 'sourced', 'Banco Central de Venezuela, Índice Nacional de Precios al Consumidor (INPC), monthly series base December 2007', 'https://www.bcv.org.ve/estadisticas/consumidor', '2026-09-30', 'The INPC rose 465.6% in the 12 months to September 2026 (index 690,967,674,312,665 against 122,169,616,603,139 in September 2025); 8.4% in the month, 534.2% year on year in August. World Bank has no figure after 2016.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VE', 1, 'inflation_projection', 1, NULL, 'assumption', 'BCV INPC +465.6% year on year (September 2026); annual inflation was about 475% in 2025 (BCV)', 'https://www.bcv.org.ve/estadisticas/consumidor', '2026-10-31', 'Venezuela has had double- or triple-digit inflation almost every year for a decade and has no inflation target, so planning uses 100% a year, well below today''s rate but far above any stable economy.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VE', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No regulator or other non-company source with indicative term-life premiums by age was found; life cover in Venezuela is mostly sold as group cover and in dollars.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VE', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'SUDEASEG publishes a monthly statistical bulletin (Boletín en Cifras) but no industry-wide life claim settlement ratio was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VE', 1, 'life_expectancy', 72.673, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=VE', '2024-12-31', 'Men 68.9, women 76.7 (2024). UN WPP gives 73.0 for 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VE', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":20.5,"men":18.7,"women":22.1},{"age":65,"total":16.7,"men":15.2,"women":18.1},{"age":70,"total":13.3,"men":12,"women":14.3},{"age":80,"total":7,"men":6.3,"women":7.4}]}', 'sourced', 'UN World Population Prospects via georank.org', 'https://georank.org/life-expectancy/venezuela', '2026-07-01', 'Remaining years derived from the ''life expectancy by current age'' table for 2026 (UN WPP): total age reached minus current age.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VE', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'Eligibility rules for the Gran Misión en Amor Mayor pension could not be confirmed from a source that could be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VE', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'A non-contributory old-age pension (Gran Misión en Amor Mayor) exists, but its current amount could not be confirmed from an official or secondary source that could be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VE', 1, 'oop_health_share', 0.2969, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=VE', '2023-12-31', 'Out-of-pocket spending was 29.7% of current health expenditure in 2023 (latest available; older than 2025).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VE', 1, 'policy_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Venezuela has no single conventional policy rate; the BCV manages money mainly through reserve requirements, open-market instruments and exchange-market sales.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VE', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":60,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'Instituto Venezolano de los Seguros Sociales (IVSS), tipos de pensiones: Pensión por Vejez', 'https://www.ivss.gob.ve/pensionado/tipos-pensiones', '2026-10-31', 'Compulsory social insurance for employees; old-age pension from 60 (men) or 55 (women) with at least 750 weekly contributions, otherwise a one-off payment of 10% of the wages on which contributions were paid. The IVSS page states no automatic indexation, so the pension is treated as not inflation-linked; tax treatment is not stated.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VE', 1, 'retirement_accumulation_return_base', 0.5, NULL, 'assumption', 'Fixed income base 50%; equity base 50%', 'https://www.bcv.org.ve/estadisticas/tasas-de-interes', '2026-10-31', 'Base case: a mix of bolívar deposits and shares, well below the 100% inflation assumption (many Venezuelans save in dollars instead).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VE', 1, 'retirement_accumulation_return_high', 0.9, NULL, 'assumption', 'Equity high 100%; gold base 100%', 'https://www.bcv.org.ve/estadisticas/tipo-cambio-de-referencia-smc', '2026-10-31', 'High case: dollar-linked assets such as shares and gold keep pace with bolívar depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VE', 1, 'retirement_accumulation_return_low', 0.3, NULL, 'assumption', 'Fixed income low 30%; equity low 20%', 'https://www.bcv.org.ve/estadisticas/tasas-de-interes', '2026-10-31', 'Low case for a mix of bolívar deposits and local shares.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VE', 1, 'retirement_age_default', 60, NULL, 'sourced', 'Instituto Venezolano de los Seguros Sociales (IVSS), tipos de pensiones: Pensión por Vejez', 'https://www.ivss.gob.ve/pensionado/tipos-pensiones', '2026-10-31', 'IVSS old-age pension from 60 for men and 55 for women with at least 750 weekly contributions; the same rule applies to people born after 1975.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VE', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'The retirement age for public employees (Ley del Estatuto sobre el Régimen de Jubilaciones y Pensiones) could not be confirmed from a source that could be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VE', 1, 'retirement_return_base', 0.45, NULL, 'assumption', 'BCV weighted average rates, September 2026: savings deposits 37.9%, term deposits 60.4% (90-day 46%); interest tax-exempt (PwC)', 'https://www.bcv.org.ve/estadisticas/tasas-de-interes', '2026-10-31', 'Base case: bolívar savings and term deposits, kept below the 46% 90-day deposit rate and the 50% planning safe rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VE', 1, 'retirement_return_high', 0.6, NULL, 'assumption', 'BCV weighted average rates, September 2026: savings deposits 37.9%, term deposits 60.4% (90-day 46%); interest tax-exempt (PwC)', 'https://www.bcv.org.ve/estadisticas/tasas-de-interes', '2026-10-31', 'High case: term deposits at the current average rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VE', 1, 'retirement_return_low', 0.3, NULL, 'assumption', 'BCV weighted average rates, September 2026: savings deposits 37.9%, term deposits 60.4% (90-day 46%); interest tax-exempt (PwC)', 'https://www.bcv.org.ve/estadisticas/tasas-de-interes', '2026-10-31', 'Low case: mostly savings accounts paying well below term deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VE', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate or retail savings bond for individuals was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VE', 1, 'savings_account_rate', 0.379, NULL, 'sourced', 'Banco Central de Venezuela, tasas de interés pasivas anuales nominales promedio ponderadas, bancos universales: depósitos de ahorro', 'https://www.bcv.org.ve/estadisticas/tasas-de-interes', '2026-09-30', '37.9% nominal a year in September 2026 (provisional), up from 32% in most earlier months; far below inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VE', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":6.49},{"year":2040,"value":4.5},{"year":2065,"value":3.66}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/venezuela-bolivarian-republic-of/2065/', '2025-12-31', '100 / old-age dependency ratio: 15.4 in 2025 (World Bank), 22.2 in 2040 and 27.3 in 2065 (UN WPP medium variant).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VE', 1, 'tax_bank_interest', 0, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Venezuela, Individual, income determination', 'https://taxsummaries.pwc.com/venezuela/individual/income-determination', '2026-09-30', 'Interest from Venezuelan savings deposits or savings funds is tax-exempt, and so are interest on fixed deposits, mortgage certificates and savings certificates under the banking law (page reviewed 30 September 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VE', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate exists; PwC Tax Summaries does not address interest on government bonds held by individuals.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VE', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published Treasury bill (Letras del Tesoro) yield was found; there is no active public market for them.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VE', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published 10-year government bond yield was found; domestic bolívar bonds are not actively traded and the external dollar bonds have been in default since 2017.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VE', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published 5-year government bond yield was found; domestic bolívar bonds are not actively traded and the external dollar bonds have been in default since 2017.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('VN', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"VN","iso3":"VNM","nameEn":"Vietnam","nameNative":"Việt Nam","region":"east_asia_pacific","languages":["vi","en"],"currency":{"code":"VND","symbol":"₫","decimals":0,"compact":"intl","usdRate":{"value":25803.5,"status":"sourced","sourceName":"Trading Economics, USD/VND interbank rate","sourceUrl":"https://tradingeconomics.com/vietnam/currency","asOf":"2026-10-30","note":"Market rate on 30 Oct 2026; the World Bank 2024 average was 24,165. SBV central rate page is script-rendered."}},"instruments":{"savings_account":{"available":true,"localName":"Tiền gửi không kỳ hạn","localNameEn":"Demand savings deposit"},"fdr_3m":{"available":true,"localName":"Tiền gửi tiết kiệm có kỳ hạn","localNameEn":"Term savings deposit"},"fdr_1y":{"available":true,"localName":"Tiền gửi tiết kiệm có kỳ hạn","localNameEn":"Term savings deposit"},"dps":{"available":true,"localName":"Tiết kiệm tích lũy","localNameEn":"Accumulative savings (monthly deposits)","note":"Offered by many banks; no published average rate."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate or retail savings bond."},"tbill_91d":{"available":false,"localName":null,"localNameEn":null,"note":"Treasury bills are rarely issued and not sold to individuals."},"tbond_5y":{"available":true,"localName":"Trái phiếu Chính phủ","localNameEn":"Government bond","note":"Auctioned to institutions; individuals can buy on the secondary market through securities firms."},"tbond_10y":{"available":true,"localName":"Trái phiếu Chính phủ","localNameEn":"Government bond","note":"Auctioned to institutions; individuals can buy on the secondary market through securities firms.","sourceUrl":"https://tradingeconomics.com/vietnam/government-bond-yield"},"equity_fund":{"available":true,"localName":"Quỹ mở","localNameEn":"Open-ended fund","note":"Open-ended funds and ETFs tracking the VN-Index are sold to retail investors.","sourceUrl":"https://tradingeconomics.com/vietnam/stock-market"},"gold":{"available":true,"localName":"Vàng miếng","localNameEn":"Gold bars","note":"Gold bars and rings are widely bought from licensed gold traders and banks."}},"institutions":{"centralBank":{"name":"State Bank of Vietnam (SBV)","url":"https://www.sbv.gov.vn/"},"insuranceRegulator":{"name":"Ministry of Finance, Insurance Supervisory Authority","url":"https://www.mof.gov.vn/"},"insuranceComplaints":{"name":"Ministry of Finance, Insurance Supervisory Authority","url":"https://www.mof.gov.vn/","note":"No insurance ombudsman; complaints go to the insurer, then the Ministry of Finance."},"pensionScheme":{"name":"Vietnam Social Security (social insurance pension)","url":"https://baohiemxahoi.gov.vn/"},"oldAgeAllowance":null,"publicHealthCover":{"name":"Vietnam Social Security (social health insurance)","url":"https://baohiemxahoi.gov.vn/"},"depositInsurance":{"name":"Deposit Insurance of Vietnam (DIV)","url":"https://div.gov.vn/"},"statistics":{"name":"General Statistics Office (National Statistics Office), Ministry of Finance","url":"https://www.nso.gov.vn/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VN', 1, 'bank_deposit_avg_rate', 0.0478, NULL, 'sourced', 'World Bank WDI, deposit interest rate (FR.INR.DPST)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=VN', '2023-12-31', '4.78% for 2023, the latest World Bank value; older than 2025, so treat as dated.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VN', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap on credit card rates and no published typical rate found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VN', 1, 'deposit_insurance_limit', 350000000, NULL, 'sourced', 'Deposit Insurance of Vietnam (DIV), article on the Deposit Insurance Law 2025', 'https://div.gov.vn/luat-bao-hiem-tien-gui-nam-2025-tam-la-chan-moi-cho-nguoi-gui-tien-va-he-thong-to-chuc-tin-dung', '2026-10-31', 'VND 350 million per depositor per insured institution, principal and interest, raised from VND 125 million alongside the Deposit Insurance Law 2025 (in force 1 May 2026); the article does not give the exact start date of the new limit.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VN', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Banks sell accumulative savings plans with monthly deposits (tiết kiệm tích lũy), but we could not read a published rate (bank pages are script-rendered).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VN', 1, 'equity_return_base', 0.085, NULL, 'assumption', 'Safe rate about 4.5% (SBV refinancing rate, 10-year bond 4.58%) plus an equity premium', 'https://tradingeconomics.com/vietnam/stock-market', '2026-10-31', 'Base case 4 points above the 4.5% safe rate, the most allowed, given a strong but volatile 10-year index record.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VN', 1, 'equity_return_high', 0.12, NULL, 'assumption', 'VN-Index long-run record (Trading Economics)', 'https://tradingeconomics.com/vietnam/stock-market', '2026-10-31', 'High case if the market keeps its long-run growth and earns an emerging-market upgrade.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VN', 1, 'equity_return_low', 0.04, NULL, 'assumption', 'VN-Index record (Trading Economics); safe rate about 4.5%', 'https://tradingeconomics.com/vietnam/stock-market', '2026-10-31', 'The VN-Index is volatile, so the low case is just under the safe rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VN', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Rate removed: the only readable figure was one bank''s own rate sheet, which we do not cite; SBV publishes no readable average for this term (its site is script-rendered).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VN', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Rate removed: the only readable figure was one bank''s own rate sheet, which we do not cite; SBV publishes no readable average for this term (its site is script-rendered).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VN', 1, 'fixed_income_return_base', 0.045, NULL, 'assumption', 'SBV refinancing rate 4.5%; 10-year government bond yield 4.58%', 'https://tradingeconomics.com/vietnam/government-bond-yield', '2026-10-31', 'Base case at the policy rate and just under the 10-year bond yield. Safe VND rates: SBV refinancing rate 4.5%; 10-year government bond 4.58% (30 Oct 2026); World Bank average deposit rate 4.78% (2023); deposit interest is tax-exempt; current bank deposit rates are not cited (only bank rate sheets were readable).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VN', 1, 'fixed_income_return_high', 0.055, NULL, 'assumption', 'World Bank average deposit rate (FR.INR.DPST); 10-year government bond yield', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=VN', '2026-10-31', 'High case for longer deposits at smaller banks, about a point above the policy rate. Safe VND rates: SBV refinancing rate 4.5%; 10-year government bond 4.58% (30 Oct 2026); World Bank average deposit rate 4.78% (2023); deposit interest is tax-exempt; current bank deposit rates are not cited (only bank rate sheets were readable).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VN', 1, 'fixed_income_return_low', 0.03, NULL, 'assumption', 'SBV refinancing rate; short-term deposit rates below the policy rate', 'https://tradingeconomics.com/vietnam/interest-rate', '2026-10-31', 'Low case for short deposits paying below the 4.5% policy rate. Safe VND rates: SBV refinancing rate 4.5%; 10-year government bond 4.58% (30 Oct 2026); World Bank average deposit rate 4.78% (2023); deposit interest is tax-exempt; current bank deposit rates are not cited (only bank rate sheets were readable).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VN', 1, 'goal_inflation_education', 0.05, NULL, 'assumption', 'NSO CPI education sub-index (via Trading Economics)', 'https://tradingeconomics.com/vietnam/inflation-cpi', '2026-10-31', 'Education CPI rose 2.74% in the year to October 2026 after public school tuition waivers; private school fees rise faster, so we plan half a point above the 4.5% general inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VN', 1, 'goal_inflation_health', 0.06, NULL, 'assumption', 'NSO CPI health sub-index (via Trading Economics)', 'https://tradingeconomics.com/vietnam/inflation-cpi', '2026-10-31', 'Health CPI rose 1.75% in the year to October 2026 because public fees are state-set, but private care costs rise faster, so we plan 1.5 points above the 4.5% general inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VN', 1, 'gold_return_base', 0.07, NULL, 'assumption', 'US-dollar gold trend; USD/VND trend (Trading Economics)', 'https://tradingeconomics.com/vietnam/currency', '2026-10-31', 'Long-run dollar gold trend of about 5% plus about 2% a year of dong depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VN', 1, 'gold_return_high', 0.11, NULL, 'assumption', 'US-dollar gold trend; USD/VND trend (Trading Economics)', 'https://tradingeconomics.com/vietnam/currency', '2026-10-31', 'High case for a strong gold cycle and faster dong depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VN', 1, 'gold_return_low', 0.02, NULL, 'assumption', 'US-dollar gold trend; USD/VND trend (Trading Economics)', 'https://tradingeconomics.com/vietnam/currency', '2026-10-31', 'Gold can stall for a decade, and local gold bar prices carry a premium that can shrink.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VN', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Labour Code 2019 provides a severance allowance for years not covered by unemployment insurance, but we could not read the legal text to confirm the days per year.', 0);
