INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VN', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premium rates found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VN', 1, 'inflation_cpi', 0.0509, NULL, 'sourced', 'National Statistics Office (Ministry of Finance), CPI October 2026', 'https://www.nso.gov.vn/du-lieu-va-so-lieu-thong-ke/2026/11/chi-so-gia-tieu-dung-chi-so-gia-vang-va-chi-so-gia-do-la-my-thang-muoi-va-muoi-thang-nam-2026/', '2026-10-31', 'CPI up 5.09% on October 2025; 10-month average 4.57%, core inflation 4.24%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VN', 1, 'inflation_projection', 0.045, NULL, 'assumption', 'NSO CPI October 2026 (10-month average 4.57%, core 4.24%); World Bank FP.CPI.TOTL.ZG (3.3% in 2025)', 'https://www.nso.gov.vn/du-lieu-va-so-lieu-thong-ke/2026/11/chi-so-gia-tieu-dung-chi-so-gia-vang-va-chi-so-gia-do-la-my-thang-muoi-va-muoi-thang-nam-2026/', '2026-10-31', 'We plan with 4.5%, between the 3.3% of 2025 and the 4.6% 10-month average of 2026, close to core inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VN', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Pure term life cover is sold, but we found no published premium rates or credible premium guide in dong.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VN', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No industry-wide life insurance claim settlement ratio published by the Ministry of Finance insurance supervisor was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VN', 1, 'life_expectancy', 75, NULL, 'sourced', 'UN World Population Prospects (via georank.org)', 'https://georank.org/life-expectancy/vietnam', '2026-07-08', 'Men 70.4, women 79.6 (2026 estimate); secondary source. World Bank gives 74.7 for 2024.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VN', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":21.5,"men":18.6,"women":23.8},{"age":65,"total":17.6,"men":15,"women":19.6},{"age":70,"total":14,"men":11.7,"women":15.6},{"age":80,"total":8.1,"men":6.4,"women":9}]}', 'sourced', 'UN World Population Prospects (via georank.org)', 'https://georank.org/life-expectancy/vietnam', '2026-07-08', 'Remaining years derived from expected age at death by current age (2026); secondary source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VN', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'Eligibility ages and means test for the social pension allowance could not be confirmed from a readable official page.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VN', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'The 2024 Social Insurance Law added a social pension allowance for older people without a pension, but we could not read an official page giving the current monthly amount.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VN', 1, 'oop_health_share', 0.392, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure, SH.XPD.OOPC.CH.ZS)', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=VN', '2023-12-31', '39.2% for 2023, the latest World Bank value; older than 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VN', 1, 'policy_rate', 0.045, NULL, 'sourced', 'State Bank of Vietnam refinancing rate (via Trading Economics)', 'https://tradingeconomics.com/vietnam/interest-rate', '2026-10-31', 'Refinancing rate 4.50% (reference period October 2026, unchanged); SBV site is script-rendered, so a secondary source is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VN', 1, 'public_pension_scheme', NULL, NULL, 'missing', '', '', '2026-10-31', 'Vietnam Social Security runs compulsory and voluntary social insurance (pension age 61.5 for men and 57 for women in 2026), but the entry age, indexation and minimum years under the 2024 law could not be confirmed from a readable page.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VN', 1, 'retirement_accumulation_return_base', 0.065, NULL, 'assumption', 'Mix of VND deposits, bonds and equity funds', 'https://tradingeconomics.com/vietnam/government-bond-yield', '2026-10-31', 'About half equity at 8.5% and half deposits and bonds near 4.5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VN', 1, 'retirement_accumulation_return_high', 0.09, NULL, 'assumption', 'Mix of VND deposits, bonds and equity funds', 'https://tradingeconomics.com/vietnam/stock-market', '2026-10-31', 'About 60% equity at the high case and 40% deposits and bonds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VN', 1, 'retirement_accumulation_return_low', 0.035, NULL, 'assumption', 'Mix of VND deposits, bonds and equity funds', 'https://tradingeconomics.com/vietnam/government-bond-yield', '2026-10-31', 'About 40% equity at the low case and 60% deposits and bonds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VN', 1, 'retirement_age_default', NULL, NULL, 'missing', '', '', '2026-10-31', 'Men 61.5 and women 57 in 2026 (Trading Economics, citing the labour ministry); under the Labour Code 2019 roadmap people born after 1975 should retire at 62 (men) and 60 (women), but no readable official page confirming the final ages was found (law databases are script-rendered).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VN', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'Public employees follow the same Labour Code roadmap: Men 61.5 and women 57 in 2026 (Trading Economics, citing the labour ministry); under the Labour Code 2019 roadmap people born after 1975 should retire at 62 (men) and 60 (women), but no readable official page confirming the final ages was found (law databases are script-rendered).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VN', 1, 'retirement_return_base', 0.043, NULL, 'assumption', 'SBV refinancing rate 4.5%; 10-year government bond yield 4.58%', 'https://tradingeconomics.com/vietnam/government-bond-yield', '2026-10-31', 'Base case just under the 4.5% policy rate and the 4.58% 10-year yield, so it stays below the safe rate after tax. Safe VND rates: SBV refinancing rate 4.5%; 10-year government bond 4.58% (30 Oct 2026); World Bank average deposit rate 4.78% (2023); deposit interest is tax-exempt; current bank deposit rates are not cited (only bank rate sheets were readable).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VN', 1, 'retirement_return_high', 0.05, NULL, 'assumption', '10-year government bond yield; World Bank average deposit rate', 'https://tradingeconomics.com/vietnam/government-bond-yield', '2026-10-31', 'High case for longer deposits a little above the bond yield. Safe VND rates: SBV refinancing rate 4.5%; 10-year government bond 4.58% (30 Oct 2026); World Bank average deposit rate 4.78% (2023); deposit interest is tax-exempt; current bank deposit rates are not cited (only bank rate sheets were readable).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VN', 1, 'retirement_return_low', 0.03, NULL, 'assumption', 'SBV refinancing rate; short-term deposit rates', 'https://tradingeconomics.com/vietnam/interest-rate', '2026-10-31', 'Low case for short deposits. Safe VND rates: SBV refinancing rate 4.5%; 10-year government bond 4.58% (30 Oct 2026); World Bank average deposit rate 4.78% (2023); deposit interest is tax-exempt; current bank deposit rates are not cited (only bank rate sheets were readable).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VN', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Vietnam has no government savings certificate or retail savings bond for individuals.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VN', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Rate removed: the only readable figure was one bank''s own rate sheet, which we do not cite; SBV publishes no readable average for demand deposits (its site is script-rendered).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VN', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":7.1},{"year":2040,"value":4.2},{"year":2065,"value":2.4}]}', 'sourced', 'World Bank SP.POP.DPND.OL; UN WPP 2024 medium variant (via populationpyramid.net)', 'https://www.populationpyramid.net/viet-nam/2040/', '2024-07-31', '100 / old-age dependency ratio: 14.0 in 2025 (World Bank), 23.6 in 2040 and 41.3 in 2065 (UN WPP 2024).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VN', 1, 'tax_bank_interest', 0, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Vietnam individual income determination', 'https://taxsummaries.pwc.com/vietnam/individual/income-determination', '2026-10-31', 'Interest on deposits with credit institutions and banks is non-taxable income.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VN', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No savings certificate exists; PwC lists investment income (interest) as taxable but does not say how government bond interest is treated.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VN', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The State Treasury rarely issues treasury bills and no current 91-day yield is published.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VN', 1, 'tbond_10y_rate', 0.0458, NULL, 'sourced', 'Trading Economics, Vietnam 10-year government bond yield', 'https://tradingeconomics.com/vietnam/government-bond-yield', '2026-10-30', '4.58% on 30 Oct 2026; secondary source.', 0);
