INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('VU', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"VU","iso3":"VUT","nameEn":"Vanuatu","nameNative":"Vanuatu","region":"east_asia_pacific","languages":["bi","en","fr"],"currency":{"code":"VUV","symbol":"VT","decimals":0,"compact":"intl","usdRate":{"value":120.32,"status":"sourced","sourceName":"World Bank WDI, official exchange rate (PA.NUS.FCRF)","sourceUrl":"https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=VU","asOf":"2025-12-31","note":"2025 average; the IMF 2025 Article IV quotes VT 121.95 per dollar on 12 Aug 2025. RBV site unreachable."}},"instruments":{"savings_account":{"available":true,"localName":null,"localNameEn":"Savings account"},"fdr_3m":{"available":true,"localName":null,"localNameEn":"Term deposit","note":"Banks offer terms from one month to one year."},"fdr_1y":{"available":true,"localName":null,"localNameEn":"Term deposit","note":"Banks offer terms from one month to one year."},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No monthly recurring deposit scheme found."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate or retail savings bond."},"tbill_91d":{"available":false,"localName":null,"localNameEn":null,"note":"No treasury bills yet; first issue planned (IMF 2025 Article IV).","sourceUrl":"https://www.imf.org/-/media/files/publications/cr/2025/english/1vutea2025001-source-pdf.pdf.md"},"tbond_5y":{"available":true,"localName":null,"localNameEn":"Government bond","note":"Domestic bonds are issued in large lots and held mainly by the provident fund and RBV; smaller lots are planned.","sourceUrl":"https://www.imf.org/-/media/files/publications/cr/2025/english/1vutea2025001-source-pdf.pdf.md"},"tbond_10y":{"available":true,"localName":null,"localNameEn":"Government bond","note":"Domestic bonds are issued in large lots and held mainly by the provident fund and RBV.","sourceUrl":"https://www.imf.org/-/media/files/publications/cr/2025/english/1vutea2025001-source-pdf.pdf.md"},"equity_fund":{"available":false,"localName":null,"localNameEn":null,"note":"No stock exchange or locally sold retail funds; only foreign funds bought abroad."},"gold":{"available":false,"localName":null,"localNameEn":null,"note":"No local bullion dealers found; gold would have to be bought abroad."}},"institutions":{"centralBank":{"name":"Reserve Bank of Vanuatu (RBV)","url":"https://www.rbv.gov.vu/"},"insuranceRegulator":{"name":"Reserve Bank of Vanuatu (insurance supervision)","url":"https://www.rbv.gov.vu/","note":"RBV supervises insurers under the Insurance Act; site could not be read during research."},"insuranceComplaints":{"name":"Reserve Bank of Vanuatu","url":"https://www.rbv.gov.vu/","note":"No insurance ombudsman found; complaints go to the insurer, then the regulator."},"pensionScheme":{"name":"Vanuatu National Provident Fund (VNPF)","url":"https://www.vnpf.com.vu/","note":"Mandatory provident fund for employees; lump sum from age 55."},"oldAgeAllowance":null,"publicHealthCover":{"name":"Ministry of Health (public hospitals and health centres)","url":"https://moh.gov.vu/"},"depositInsurance":null,"statistics":{"name":"Vanuatu Bureau of Statistics (VBOS)","url":"https://vbos.gov.vu/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VU', 1, 'bank_deposit_avg_rate', 0.0031, NULL, 'sourced', 'World Bank WDI, deposit interest rate (FR.INR.DPST)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=VU', '2025-12-31', '0.31% for 2025, down from 0.62% in 2024.', 0);
