INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VU', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'We found no deposit insurance scheme in Vanuatu, but could not confirm it from an official page (RBV site unreachable).', 0);
