INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VU', 1, 'equity_return_base', 0.05, NULL, 'assumption', 'Global equity index in vatu terms, capped at the safe rate plus 4 points', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=VU', '2026-10-31', 'No local market, so base is a global index in vatu terms, held to the assumed 1% safe rate plus 4 points.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VU', 1, 'equity_return_high', 0.08, NULL, 'assumption', 'Global equity index long-run return in vatu terms', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=VU', '2026-10-31', 'High case near the long-run global equity return with a stable basket-pegged vatu.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VU', 1, 'equity_return_low', 0, NULL, 'assumption', 'No local stock exchange; global equity index in vatu terms', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=VU', '2026-10-31', 'Vanuatu has no stock exchange, so equity means foreign funds; a lost decade for global shares in vatu terms is the low case.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VU', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term deposits (1 month to 1 year) are sold, but no published rate could be read; RBV statistics unreachable.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VU', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term deposits (1 month to 1 year) are sold, but no published rate could be read; RBV statistics unreachable.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VU', 1, 'fixed_income_return_base', 0.01, NULL, 'assumption', 'World Bank average deposit rate; RBV policy rate (IMF 2025 Article IV)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=VU', '2026-10-31', 'Base case of 1%, between the 0.31% average deposit rate and the 2.75% policy rate, since term deposits pay more than the average. Safe vatu rates: World Bank average deposit rate 0.31% (2025), RBV policy rate 2.75%, no tax on interest; published bank term-deposit rates could not be read; government bonds yield 7-9% but are sold in large lots and held mostly by the provident fund and RBV.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VU', 1, 'fixed_income_return_high', 0.03, NULL, 'assumption', 'RBV policy rate (IMF 2025 Article IV)', 'https://www.imf.org/-/media/files/publications/cr/2025/english/1vutea2025001-source-pdf.pdf.md', '2026-10-31', 'High case near the policy rate, for savers who reach better term deposit rates. Safe vatu rates: World Bank average deposit rate 0.31% (2025), RBV policy rate 2.75%, no tax on interest; published bank term-deposit rates could not be read; government bonds yield 7-9% but are sold in large lots and held mostly by the provident fund and RBV.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VU', 1, 'fixed_income_return_low', 0.003, NULL, 'assumption', 'World Bank average deposit rate (FR.INR.DPST)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=VU', '2026-10-31', 'Low case at the average deposit rate of 0.31%. Safe vatu rates: World Bank average deposit rate 0.31% (2025), RBV policy rate 2.75%, no tax on interest; published bank term-deposit rates could not be read; government bonds yield 7-9% but are sold in large lots and held mostly by the provident fund and RBV.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VU', 1, 'goal_inflation_education', 0.05, NULL, 'assumption', 'VBOS CPI education sub-index, June quarter 2026', 'https://vbos.gov.vu/index.php/en/statistics/economic-statistics/consumer-price-index', '2026-10-31', 'Education CPI rose 7.8% in the year to June 2026 (school fees), so we plan 2 points above general inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VU', 1, 'goal_inflation_health', 0.05, NULL, 'assumption', 'VBOS CPI health sub-index, June quarter 2026', 'https://vbos.gov.vu/index.php/en/statistics/economic-statistics/consumer-price-index', '2026-10-31', 'Health CPI rose 11.1% in the year to June 2026 (private consultation and check-up fees), so we plan 2 points above general inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VU', 1, 'gold_return_base', 0.05, NULL, 'assumption', 'US-dollar gold trend; basket-managed vatu (IMF 2025 Article IV)', 'https://www.imf.org/-/media/files/publications/cr/2025/english/1vutea2025001-source-pdf.pdf.md', '2026-10-31', 'Long-run dollar gold trend of about 5% with little expected vatu depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VU', 1, 'gold_return_high', 0.09, NULL, 'assumption', 'US-dollar gold trend; basket-managed vatu (IMF 2025 Article IV)', 'https://www.imf.org/-/media/files/publications/cr/2025/english/1vutea2025001-source-pdf.pdf.md', '2026-10-31', 'High case for a strong gold cycle.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VU', 1, 'gold_return_low', 0.01, NULL, 'assumption', 'US-dollar gold trend; basket-managed vatu (IMF 2025 Article IV)', 'https://www.imf.org/-/media/files/publications/cr/2025/english/1vutea2025001-source-pdf.pdf.md', '2026-10-31', 'Gold can stall for a decade; the vatu is managed against a currency basket.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VU', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Employment Act [Cap 160] provides a severance allowance, but we could not read the current text (PacLII blocked), so the days per year are not confirmed.', 0);
