INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VU', 1, 'inflation_cpi', 0.012, NULL, 'sourced', 'Vanuatu Bureau of Statistics, Consumer Price Index June quarter 2026', 'https://vbos.gov.vu/index.php/en/statistics/economic-statistics/consumer-price-index', '2026-06-30', 'National CPI up 1.2% on the June quarter of 2025 (1.4% on the quarter).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VU', 1, 'inflation_projection', 0.03, NULL, 'assumption', 'RBV inflation target range 0-4% (IMF 2025 Article IV); VBOS CPI history', 'https://www.imf.org/-/media/files/publications/cr/2025/english/1vutea2025001-source-pdf.pdf.md', '2026-10-31', 'We plan with 3%, inside the RBV 0-4% target range and above recent 1% readings, because Vanuatu CPI has swung widely after cyclones and in 2022-2023.', 0);
