INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VU', 1, 'oop_health_share', 0.084, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure, SH.XPD.OOPC.CH.ZS)', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=VU', '2023-12-31', '8.4% for 2023, the latest World Bank value; older than 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VU', 1, 'policy_rate', 0.0275, NULL, 'sourced', 'IMF 2025 Article IV staff report (RBV policy rate)', 'https://www.imf.org/-/media/files/publications/cr/2025/english/1vutea2025001-source-pdf.pdf.md', '2025-08-12', 'RBV policy rate unchanged at 2.75% since tightening in 2024Q3 (IMF, data to August 2025); RBV site was not reachable (certificate error), so a later change cannot be ruled out.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VU', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":10,"entryAgeMax":null,"pensionFromAge":55,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'Vanuatu National Provident Fund, Withdrawals and Voluntary Membership pages', 'https://www.vnpf.com.vu/withdrawals.html', '2026-10-31', 'VNPF is a provident fund: members withdraw their savings at 55 (up to 50% at 47); no annuity is described. Voluntary members can join from age 10 with VT 1,000 a month; interest is declared yearly.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VU', 1, 'retirement_accumulation_return_base', 0.03, NULL, 'assumption', 'Mix of vatu deposits and global equity funds', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=VU', '2026-10-31', 'About half global equity at 5% and half deposits near 1%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VU', 1, 'retirement_accumulation_return_high', 0.055, NULL, 'assumption', 'Mix of vatu deposits, global equity and VNPF-style returns', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=VU', '2026-10-31', 'About 60% equity at the high case and 40% higher-yield fixed income.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VU', 1, 'retirement_accumulation_return_low', 0.01, NULL, 'assumption', 'Mix of vatu deposits and global equity funds', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=VU', '2026-10-31', 'About 40% equity at the low case and 60% deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VU', 1, 'retirement_age_default', 55, NULL, 'sourced', 'Vanuatu National Provident Fund, Withdrawals (VNPF Act Cap 189)', 'https://www.vnpf.com.vu/withdrawals.html', '2026-10-31', 'Members can withdraw their savings at 55 (up to 50% at 47); there is no statutory pension age beyond this.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VU', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'Public Service Act retirement age could not be read (PacLII blocked); not confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VU', 1, 'retirement_return_base', 0.01, NULL, 'assumption', 'World Bank average deposit rate; RBV policy rate', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=VU', '2026-10-31', 'Base case of 1%, kept modest because no 1-year deposit or bill rate could be confirmed. Safe vatu rates: World Bank average deposit rate 0.31% (2025), RBV policy rate 2.75%, no tax on interest; published bank term-deposit rates could not be read; government bonds yield 7-9% but are sold in large lots and held mostly by the provident fund and RBV.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VU', 1, 'retirement_return_high', 0.03, NULL, 'assumption', 'RBV policy rate (IMF 2025 Article IV)', 'https://www.imf.org/-/media/files/publications/cr/2025/english/1vutea2025001-source-pdf.pdf.md', '2026-10-31', 'High case near the policy rate. Safe vatu rates: World Bank average deposit rate 0.31% (2025), RBV policy rate 2.75%, no tax on interest; published bank term-deposit rates could not be read; government bonds yield 7-9% but are sold in large lots and held mostly by the provident fund and RBV.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VU', 1, 'retirement_return_low', 0.003, NULL, 'assumption', 'World Bank average deposit rate (FR.INR.DPST)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=VU', '2026-10-31', 'Low case at the average deposit rate. Safe vatu rates: World Bank average deposit rate 0.31% (2025), RBV policy rate 2.75%, no tax on interest; published bank term-deposit rates could not be read; government bonds yield 7-9% but are sold in large lots and held mostly by the provident fund and RBV.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VU', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Vanuatu has no government savings certificate or retail savings bond.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VU', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Bank savings rates are not published on the bank pages we could read, and RBV interest rate statistics were unreachable (certificate error).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VU', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":13.2},{"year":2040,"value":10.5},{"year":2065,"value":6.7}]}', 'sourced', 'World Bank SP.POP.DPND.OL; UN WPP 2024 medium variant (via populationpyramid.net)', 'https://www.populationpyramid.net/vanuatu/2040/', '2024-07-31', '100 / old-age dependency ratio: 7.6 in 2025 (World Bank), 9.5 in 2040 and 14.9 in 2065 (UN WPP 2024).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VU', 1, 'tax_bank_interest', 0, NULL, 'sourced', 'Vanuatu Foreign Investment Promotion Agency, Low Tax Jurisdiction', 'https://investvanuatu.vu/untapped-potential/low-tax-jurisdiction/', '2026-10-31', 'No personal income tax and no withholding taxes, so bank interest is untaxed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VU', 1, 'tax_sanchayapatra_profit', 0, NULL, 'sourced', 'Vanuatu Foreign Investment Promotion Agency, Low Tax Jurisdiction', 'https://investvanuatu.vu/untapped-potential/low-tax-jurisdiction/', '2026-10-31', 'No savings certificate exists; with no personal income tax, interest on government bonds is also untaxed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VU', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No treasury bills issued yet; the IMF 2025 Article IV says the government plans to issue T-bills for the first time.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VU', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Domestic government bonds exist (IMF: longer-term bonds yield 7-9%), but we found no published 10-year yield.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('VU', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Domestic government bonds exist (IMF: longer-term bonds yield 7-9%), but we found no published 5-year yield.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('WS', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"WS","iso3":"WSM","nameEn":"Samoa","nameNative":"Sāmoa","region":"east_asia_pacific","languages":["sm","en"],"currency":{"code":"WST","symbol":"$","decimals":2,"compact":"intl","usdRate":{"value":2.7646,"status":"sourced","sourceName":"Central Bank of Samoa daily exchange rates","sourceUrl":"https://www.cbs.gov.ws/daily-exchange-rates","asOf":"2026-10-30","note":"WST 1 = USD 0.36171 on 30 October 2026 in the CBS historical daily rates file linked from this page, so 2.76 tala per US dollar."}},"instruments":{"savings_account":{"available":true,"localName":"Savings account","sourceUrl":"https://cbs.gov.ws/media/A14-Interest-Rates-8.xlsx"},"fdr_3m":{"available":true,"localName":"Term deposit","localNameEn":"3-month term deposit","sourceUrl":"https://cbs.gov.ws/media/A14-Interest-Rates-8.xlsx"},"fdr_1y":{"available":true,"localName":"Term deposit","localNameEn":"1-year term deposit","sourceUrl":"https://cbs.gov.ws/media/A14-Interest-Rates-8.xlsx"},"dps":{"available":false,"localName":null,"note":"No standard monthly recurring deposit product is published by Samoa banks."},"sanchayapatra_5y":{"available":false,"localName":null,"note":"No government savings certificate or retail savings bond for individuals found."},"tbill_91d":{"available":true,"localName":"CBS Securities","localNameEn":"Central Bank of Samoa Securities (14 to 365 days)","note":"Central bank bills sold by fortnightly tender; open to registered members of the public from SAT 1,000; used here in place of government Treasury bills.","sourceUrl":"https://cbs.gov.ws/media/CBS-Securities-Prospectus.pdf"},"tbond_5y":{"available":false,"localName":null,"note":"No regular government bond issues to the public found."},"tbond_10y":{"available":false,"localName":null,"note":"No regular government bond issues to the public found."},"equity_fund":{"available":true,"localName":"Unit trust","localNameEn":"Unit trust (managed fund)","note":"Samoa has no stock exchange; a locally managed unit trust and offshore funds are the main pooled options."},"gold":{"available":true,"localName":"Gold","note":"No legal restriction on buying gold; mainly sold as jewellery."}},"institutions":{"centralBank":{"name":"Central Bank of Samoa","url":"https://www.cbs.gov.ws/"},"insuranceRegulator":{"name":"Central Bank of Samoa (insurance supervision)","url":"https://www.cbs.gov.ws/"},"insuranceComplaints":{"name":"Central Bank of Samoa","url":"https://www.cbs.gov.ws/","note":"No separate insurance ombudsman found; complaints go to the insurer, then the Central Bank."},"pensionScheme":{"name":"Samoa National Provident Fund (SNPF)","url":"https://www.npf.ws/"},"oldAgeAllowance":{"name":"Senior Citizens Benefit Fund (administered by SNPF)","url":"https://www.npf.ws/scbf"},"publicHealthCover":{"name":"Ministry of Health (government hospitals; free consultations for seniors)","url":"https://www.health.gov.ws/"},"depositInsurance":null,"statistics":{"name":"Samoa Bureau of Statistics","url":"https://www.sbs.gov.ws/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
