INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('WS', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap or published typical credit card rate found in CBS tables (only overall lending rates, about 8.4% weighted average).', 0);
