INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('WS', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched CBS rate tables and bank pages: no monthly recurring deposit (DPS-style) product rate is published in Samoa.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('WS', 1, 'equity_return_base', 0.06, NULL, 'assumption', 'No local stock market; CBS 182-day securities 3.69% and 12-month deposits 2.75-3.00%', 'https://cbs.gov.ws/media/A14-Interest-Rates-8.xlsx', '2026-10-31', 'Samoa has no stock exchange, so equity is a global index fund in tala terms: about 6%, within 4 points of the roughly 2.5-3% after-tax safe rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('WS', 1, 'equity_return_high', 0.09, NULL, 'assumption', 'No local stock market; global equities in tala terms', 'https://cbs.gov.ws/media/A14-Interest-Rates-8.xlsx', '2026-10-31', 'High case if global equities repeat their long-run record of about 9% with a stable tala.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('WS', 1, 'equity_return_low', 0.03, NULL, 'assumption', 'No local stock market; CBS 182-day securities 3.69% and 12-month deposits 2.75-3.00%', 'https://cbs.gov.ws/media/A14-Interest-Rates-8.xlsx', '2026-10-31', 'Low case for a global equity fund in tala, near the safe rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('WS', 1, 'fdr_1y_rate', 0.02875, NULL, 'sourced', 'Central Bank of Samoa statistics table A14 (interest rates)', 'https://cbs.gov.ws/media/A14-Interest-Rates-8.xlsx', '2026-06-30', '12-month time deposit rates range 2.75-3.00% across banks; midpoint used (24 months 3.5%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('WS', 1, 'fdr_3m_rate', 0.01875, NULL, 'sourced', 'Central Bank of Samoa statistics table A14 (interest rates)', 'https://cbs.gov.ws/media/A14-Interest-Rates-8.xlsx', '2026-06-30', '3-month time deposit rates range 1.50-2.25% across banks; midpoint used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('WS', 1, 'fixed_income_return_base', 0.025, NULL, 'assumption', 'CBS table A14: 12-month deposits 2.75-3.00%; CBS 91-day securities 3.30%', 'https://cbs.gov.ws/media/A14-Interest-Rates-8.xlsx', '2026-10-31', 'Base case: 1-year deposits and short CBS Securities, less withholding tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('WS', 1, 'fixed_income_return_high', 0.03, NULL, 'assumption', 'CBS table A14: 24-month deposits 3.5%; CBS 182-day securities 3.69%', 'https://cbs.gov.ws/media/A14-Interest-Rates-8.xlsx', '2026-10-31', 'High case: 2-year deposits or 182-day CBS Securities, less withholding tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('WS', 1, 'fixed_income_return_low', 0.015, NULL, 'assumption', 'CBS table A14: 3-month deposits 1.50-2.25%', 'https://cbs.gov.ws/media/A14-Interest-Rates-8.xlsx', '2026-10-31', 'Low case: short time deposits, allowing for the withholding tax on resident interest.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('WS', 1, 'goal_inflation_education', 0.04, NULL, 'assumption', 'CBS headline CPI table (no education sub-index published there)', 'https://cbs.gov.ws/media/T2---Headline---CPI---August---2026.xlsx', '2026-10-31', 'No education CPI found, so we plan with the headline projection plus half a point.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('WS', 1, 'goal_inflation_health', 0.045, NULL, 'assumption', 'CBS headline CPI table (no health sub-index published there)', 'https://cbs.gov.ws/media/T2---Headline---CPI---August---2026.xlsx', '2026-10-31', 'No medical CPI found, so we plan with the 3.5% headline projection plus one point for imported medical costs.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('WS', 1, 'gold_return_base', 0.05, NULL, 'assumption', 'CBS daily exchange rates (tala per US dollar about 2.6 in 2016 and 2.76 in October 2026)', 'https://www.cbs.gov.ws/daily-exchange-rates', '2026-10-31', 'Long-run dollar gold trend of about 4-5% plus little expected tala depreciation under the basket peg.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('WS', 1, 'gold_return_high', 0.08, NULL, 'assumption', 'CBS daily exchange rates (tala per US dollar about 2.6 in 2016 and 2.76 in October 2026)', 'https://www.cbs.gov.ws/daily-exchange-rates', '2026-10-31', 'High case with strong dollar gold and some tala weakening.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('WS', 1, 'gold_return_low', 0.02, NULL, 'assumption', 'CBS daily exchange rates (tala per US dollar about 2.6 in 2016 and 2.76 in October 2026)', 'https://www.cbs.gov.ws/daily-exchange-rates', '2026-10-31', 'Low case: weak dollar gold under a stable basket-pegged tala.', 0);
