INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('WS', 1, 'inflation_cpi', 0.036, NULL, 'sourced', 'Central Bank of Samoa statistics table 2 (Samoa Bureau of Statistics headline CPI)', 'https://cbs.gov.ws/media/T2---Headline---CPI---August---2026.xlsx', '2026-08-31', 'Headline CPI up 3.6% on a year earlier in August 2026 (5.7% in June); the 12-month annual-average rate was 1.2% in August, and the CBS home page shows 1.2% for September 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('WS', 1, 'inflation_projection', 0.035, NULL, 'assumption', 'Central Bank of Samoa Monetary Policy Statement 2026/2027 (inflation reference around 3%)', 'https://cbs.gov.ws/media/MPS-2026-2027.pdf', '2026-10-31', 'The CBS aims for annual average inflation around 3% in line with trading partners, and recent prices have swung from -2% to +6%, so we plan with 3.5%.', 0);
