INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('WS', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":18.5,"men":16.9,"women":20},{"age":65,"total":14.9,"men":13.5,"women":16.2},{"age":70,"total":11.7,"men":10.6,"women":12.7},{"age":80,"total":6.6,"men":6,"women":7.1}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/samoa/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026 (mid-year reference); totals at 60, 70 and 80 are the mean of men and women (the page gives a total only at 65, 14.9).', 0);
