INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('WS', 1, 'old_age_allowance_monthly', 300, NULL, 'sourced', 'Samoa National Provident Fund: Senior Citizens Benefit Fund', 'https://www.npf.ws/scbf', '2026-10-31', 'Monthly pension of WST 300 for life, plus free inter-island ferry travel, free consultations and medicines at government hospitals and pharmacies.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('WS', 1, 'oop_health_share', 0.1342, NULL, 'sourced', 'World Bank WDI SH.XPD.OOPC.CH.ZS', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=WS', '2023-12-31', '2023 figure (older than 2025), latest available in World Bank WDI.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('WS', 1, 'policy_rate', 0.0342, NULL, 'sourced', 'Central Bank of Samoa Monetary Policy Statement 2026/2027 (Table 1A)', 'https://cbs.gov.ws/media/MPS-2026-2027.pdf', '2026-04-30', 'CBS official interest rate (weighted average yield on CBS securities) 3.42% at end April 2026, above the 2-3% neutral target range; the CBS home page shows 3.18% for August 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('WS', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":55,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":null}', 'sourced', 'Samoa National Provident Fund: members guide', 'https://www.npf.ws/members-guide', '2026-10-31', 'Compulsory provident fund: 10% employee plus 10% employer; at 55 members take a lump sum or a fortnightly lifetime pension funded from 75% of net contributions (spouse receives half for up to 10 years); interest credited at no less than 4% a year.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('WS', 1, 'retirement_accumulation_return_base', 0.055, NULL, 'assumption', 'SNPF: interest credited not less than 4% a year; 7-year average 7%', 'https://www.npf.ws/member-faqs', '2026-10-31', 'Base case between SNPF''s 4% floor and its 7% average of the last seven years.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('WS', 1, 'retirement_accumulation_return_high', 0.07, NULL, 'assumption', 'SNPF: interest credited not less than 4% a year; 7-year average 7%', 'https://www.npf.ws/member-faqs', '2026-10-31', 'High case at SNPF''s recent 7% average crediting rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('WS', 1, 'retirement_accumulation_return_low', 0.04, NULL, 'assumption', 'SNPF: interest credited not less than 4% a year; 7-year average 7%', 'https://www.npf.ws/member-faqs', '2026-10-31', 'Low case at SNPF''s statutory minimum crediting rate of 4%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('WS', 1, 'retirement_age_default', 55, NULL, 'sourced', 'Samoa National Provident Fund: members guide', 'https://www.npf.ws/members-guide', '2026-10-31', 'SNPF members can take their savings as a lump sum or a lifetime pension at 55; no statutory private-sector retirement age found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('WS', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'Searched for the Samoa public service retirement age: no reachable official source found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('WS', 1, 'retirement_return_base', 0.025, NULL, 'assumption', 'CBS table A14: 12-month deposits 2.75-3.00%', 'https://cbs.gov.ws/media/A14-Interest-Rates-8.xlsx', '2026-10-31', 'Base case kept below the 1-year deposit rate to allow for withholding tax on interest.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('WS', 1, 'retirement_return_high', 0.03, NULL, 'assumption', 'CBS table A14: 24-month deposits 3.5%; SNPF lifetime pension option', 'https://cbs.gov.ws/media/A14-Interest-Rates-8.xlsx', '2026-10-31', 'High case: 2-year deposits after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('WS', 1, 'retirement_return_low', 0.015, NULL, 'assumption', 'CBS table A14: 3-month deposits 1.50-2.25%', 'https://cbs.gov.ws/media/A14-Interest-Rates-8.xlsx', '2026-10-31', 'Low case: short deposits after withholding tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('WS', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate or retail savings bond for individuals found in Samoa.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('WS', 1, 'savings_account_rate', 0.01, NULL, 'sourced', 'Central Bank of Samoa statistics table A14 (interest rates)', 'https://cbs.gov.ws/media/A14-Interest-Rates-8.xlsx', '2026-06-30', 'Commercial bank savings deposit rates range 0-2.00%; midpoint used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('WS', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":9.2},{"year":2040,"value":7.2},{"year":2065,"value":8.4}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/samoa/2040/', '2025-12-31', '100 / old-age dependency ratio: 10.86 (2025, World Bank), 13.8 (2040) and 11.9 (2065, populationpyramid.net/samoa/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('WS', 1, 'tax_bank_interest', NULL, NULL, 'missing', '', '', '2026-10-31', 'Ministry of Revenue information sheet IS01 (2026) lists a withholding tax on interest income of resident individuals but does not state the rate; the Income Tax Act schedule was not reachable.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('WS', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government retail savings bond for individuals found, so no specific tax rule applies.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('WS', 1, 'tbill_91d_rate', 0.033, NULL, 'sourced', 'Central Bank of Samoa, tender results T-17/2026 (CBS Securities)', 'https://cbs.gov.ws/media/Results-------------T17-------26-----------22-------October-----------2026.pdf', '2026-10-22', '91-day CBS Securities weighted average yield 3.30% (182-day 3.69%). Samoa has no regular government Treasury bills; CBS Securities, open to registered members of the public, stand in for them.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('WS', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No regular Samoa Government bond issues or published yields found.', 0);
