INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('XK', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"XK","iso3":"XKX","nameEn":"Kosovo","nameNative":"Kosova","region":"europe_central_asia","languages":["sq","sr","en"],"currency":{"code":"EUR","symbol":"€","decimals":2,"compact":"intl","usdRate":{"value":0.8951,"status":"sourced","sourceName":"European Central Bank euro reference rate (USD)","sourceUrl":"https://data-api.ecb.europa.eu/service/data/EXR/D.USD.EUR.SP00.A","asOf":"2026-10-30","note":"EUR 1 = USD 1.1172, so about EUR 0.895 per US dollar; Kosovo uses the euro unilaterally. World Bank 2025 average 0.887."}},"instruments":{"savings_account":{"available":true,"localName":"Llogari kursimi","localNameEn":"Savings account","sourceUrl":"https://bqk-kos.org/wp-content/uploads/2026/07/CBK_MSB_297_En.pdf"},"fdr_3m":{"available":true,"localName":"Depozitë me afat","localNameEn":"Term deposit (3 months)"},"fdr_1y":{"available":true,"localName":"Depozitë me afat","localNameEn":"Term deposit (1 year)","sourceUrl":"https://bqk-kos.org/wp-content/uploads/2026/07/CBK_MSB_297_En.pdf"},"dps":{"available":false,"localName":null,"localNameEn":"Recurring deposit scheme","note":"No standard monthly recurring deposit product was confirmed."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":"Government savings certificate","note":"No retail government savings bond for individuals."},"tbill_91d":{"available":true,"localName":"Letra me vlerë të Qeverisë","localNameEn":"Government treasury bills","note":"Auctioned by the Ministry of Finance through the Central Bank; interest exempt from personal income tax.","sourceUrl":"https://taxsummaries.pwc.com/kosovo/individual/income-determination"},"tbond_5y":{"available":true,"localName":"Obligacione të Qeverisë","localNameEn":"Government bonds","note":"Auctioned by the Ministry of Finance through the Central Bank, mainly to banks and the pension fund."},"tbond_10y":{"available":true,"localName":"Obligacione të Qeverisë","localNameEn":"Government bonds","note":"Long maturities are issued occasionally; mainly institutional buyers."},"equity_fund":{"available":false,"localName":null,"localNameEn":"Equity or index fund","note":"Kosovo has no stock exchange and no locally sold retail equity funds were confirmed; residents would need a foreign platform."},"gold":{"available":true,"localName":"Ar investues","localNameEn":"Investment gold bars and coins","note":"No restriction on buying physical gold; Kosovo uses the euro."}},"institutions":{"centralBank":{"name":"Banka Qendrore e Republikës së Kosovës (Central Bank of the Republic of Kosovo)","url":"https://bqk-kos.org/","note":"Kosovo uses the euro; the CBK supervises banks, insurers and pension funds but sets no interest rate."},"insuranceRegulator":{"name":"Banka Qendrore e Republikës së Kosovës (insurance supervision)","url":"https://bqk-kos.org/"},"insuranceComplaints":{"name":"Central Bank of the Republic of Kosovo, consumer complaints","url":"https://bqk-kos.org/"},"pensionScheme":{"name":"Trusti i Kursimeve Pensionale të Kosovës (Kosovo Pension Savings Trust)","url":"https://trusti.org/en/"},"oldAgeAllowance":{"name":"Ministria e Financave, Punës dhe Transfereve (basic age pension)","url":"https://mf.rks-gov.net/","note":"The basic age pension (EUR 150 a month since November 2025) is paid by the Pension Administration of Kosovo within this ministry."},"publicHealthCover":{"name":"Ministria e Shëndetësisë (Ministry of Health)","url":"https://msh.rks-gov.net/","note":"Public health care is budget-funded with co-payments; the Health Insurance Fund set up by law is not yet fully operational."},"depositInsurance":{"name":"Fondi për Sigurimin e Depozitave të Kosovës (FSDK)","url":"https://fsdk.org/en/"},"statistics":{"name":"Agjencia e Statistikave të Kosovës (Kosovo Agency of Statistics)","url":"https://ask.rks-gov.net/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('XK', 1, 'bank_deposit_avg_rate', 0.0326, NULL, 'sourced', 'Central Bank of the Republic of Kosovo, Monthly Statistics Bulletin May 2026 (Table 15.1, new deposits of households and nonfinancial corporations)', 'https://bqk-kos.org/wp-content/uploads/2026/07/CBK_MSB_297_En.pdf', '2026-05-31', 'Weighted average rate on all new deposits in May 2026; households alone 3.00%. The CBK Monthly Report of Financial System for May 2026 rounds it to 3.3%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('XK', 1, 'credit_card_rate_cap', 0.1231, NULL, 'sourced', 'Central Bank of the Republic of Kosovo, Monthly Statistics Bulletin May 2026 (Table 15.2.2, household overdrafts)', 'https://bqk-kos.org/wp-content/uploads/2026/07/CBK_MSB_297_En.pdf', '2026-05-31', 'No legal cap found; the CBK publishes no separate credit card rate, so this is the average rate on household overdrafts in May 2026 (Table 15.2.2), the closest revolving-credit series.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('XK', 1, 'deposit_insurance_limit', 5000, NULL, 'sourced', 'Deposit Insurance Fund of Kosovo (FSDK), what is insured', 'https://fsdk.org/en/deposit-insurance/whats-covered/', '2026-10-31', 'EUR 5,000 per depositor per member bank.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('XK', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No recurring-deposit product rate found from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('XK', 1, 'equity_return_base', 0.055, NULL, 'assumption', 'No Kosovo stock exchange; global equity index in euro terms; ECB deposit rate 2.5%', 'https://data-api.ecb.europa.eu/service/data/FM/B.U2.EUR.4F.KR.DFR.LEV', '2026-10-31', 'Kosovo has no stock market, so the base case is a global index fund in euros at about 3 points over the euro safe rate, kept within 4 points of the after-tax safe return.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('XK', 1, 'equity_return_high', 0.075, NULL, 'assumption', 'Global equity long-run returns in euro terms', 'https://tradingeconomics.com/united-states/stock-market', '2026-10-31', 'High case: global equities match their long-run record of about 7-8% a year in euros.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('XK', 1, 'equity_return_low', 0.03, NULL, 'assumption', 'No Kosovo stock exchange; global equity index (US500 7,580 on 30 Oct 2026, +10.8% in a year) in euro terms', 'https://tradingeconomics.com/united-states/stock-market', '2026-10-31', 'Low case: a global index fund bought in euros delivers little more than euro-area safe rates over a long stretch, as after 2000 and 2008.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('XK', 1, 'fdr_1y_rate', 0.0302, NULL, 'sourced', 'Central Bank of the Republic of Kosovo, Monthly Statistics Bulletin May 2026 (Table 15.1.2, household new deposits)', 'https://bqk-kos.org/wp-content/uploads/2026/07/CBK_MSB_297_En.pdf', '2026-05-31', 'Household new time deposits over 6 months and up to 1 year, May 2026 (over 1 up to 2 years: 3.21%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('XK', 1, 'fdr_3m_rate', 0.0271, NULL, 'sourced', 'Central Bank of the Republic of Kosovo, Monthly Statistics Bulletin May 2026 (Table 15.1.2, household new deposits)', 'https://bqk-kos.org/wp-content/uploads/2026/07/CBK_MSB_297_En.pdf', '2026-05-31', 'Household new time deposits over 3 and up to 6 months, May 2026; the 1-3 month bucket is suppressed for confidentiality in 2026 (up to 1 month: 2.14%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('XK', 1, 'fixed_income_return_base', 0.025, NULL, 'assumption', 'CBK household 6-12 month deposit rate 3.02% (May 2026) less 10% withholding; ECB deposit rate 2.5%', 'https://bqk-kos.org/wp-content/uploads/2026/07/CBK_MSB_297_En.pdf', '2026-10-31', 'Base case: 1-year deposits after the 10% tax (about 2.7%), rounded down because euro rates may drift lower over a long horizon.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('XK', 1, 'fixed_income_return_high', 0.03, NULL, 'assumption', 'CBK household 1-2 year deposit rate 3.21% (May 2026); Kosovo government securities tax-exempt (PwC)', 'https://taxsummaries.pwc.com/kosovo/individual/income-determination', '2026-10-31', 'High case: longer deposits or tax-exempt Kosovo government bonds, which pay a premium over euro-area rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('XK', 1, 'fixed_income_return_low', 0.02, NULL, 'assumption', 'CBK household 3-6 month deposit rate 2.71% (May 2026) less 10% withholding', 'https://bqk-kos.org/wp-content/uploads/2026/07/CBK_MSB_297_En.pdf', '2026-10-31', 'Low case: short term deposits at about 2.7% minus the 10% interest tax, with some time in near-zero savings accounts.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('XK', 1, 'goal_inflation_education', 0.035, NULL, 'assumption', 'Kosovo CPI education index ~100 points in Sep 2026 (Trading Economics)', 'https://tradingeconomics.com/kosovo/indicators', '2026-10-31', 'Public schooling is largely free and the education CPI has barely moved, so private education costs are assumed to rise a little above general inflation at 3.5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('XK', 1, 'goal_inflation_health', 0.04, NULL, 'assumption', 'Kosovo CPI (Trading Economics); headline 7.8% Sep 2026, 3.9% in 2025', 'https://tradingeconomics.com/kosovo/inflation-cpi', '2026-10-31', 'Health costs are assumed to rise about one point faster than the 3% long-run headline assumption, as private clinics and imported medicines track euro-area medical inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('XK', 1, 'gold_return_base', 0.04, NULL, 'assumption', 'Gold price history (Trading Economics); ECB 2% inflation target', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Base case: dollar gold rises with world inflation plus a little, and the euro is assumed stable against the dollar over the long run.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('XK', 1, 'gold_return_high', 0.07, NULL, 'assumption', 'Gold price history (Trading Economics)', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'High case: a repeat of gold''s strong 2005-2025 trend in euro terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('XK', 1, 'gold_return_low', 0.01, NULL, 'assumption', 'Gold USD 3,876/oz on 30 Oct 2026, 31% below the January 2026 high of USD 5,608', 'https://tradingeconomics.com/commodity/gold', '2026-10-31', 'Low case: gold barely keeps up after the 2025-26 spike, with no help from the euro.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('XK', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No statutory end-of-service gratuity for private employees in Kosovo could be confirmed from the Labour Law text.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('XK', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published figure for a typical private hospital stay cost in Kosovo was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('XK', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Voluntary private health insurance is sold but no premium table per EUR 100,000 of cover was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('XK', 1, 'inflation_cpi', 0.078, NULL, 'sourced', 'Trading Economics (Kosovo Agency of Statistics CPI, September 2026)', 'https://tradingeconomics.com/kosovo/inflation-cpi', '2026-09-30', 'CPI 7.8% year on year in September 2026 (7.3% in August), highest since February 2023, driven by transport prices (+23.9%); secondary source because ask.rks-gov.net release pages did not render. World Bank 2025 average 3.9%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('XK', 1, 'inflation_projection', 0.03, NULL, 'assumption', 'ECB 2% target (Kosovo uses the euro); Kosovo CPI 7.8% (Sep 2026), 3.9% in 2025 (World Bank)', 'https://tradingeconomics.com/kosovo/inflation-cpi', '2026-10-31', 'Kosovo uses the euro unilaterally, so long-run inflation should drift toward euro-area levels, but it has run above the ECB''s 2% target, so 3% is used for planning.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('XK', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Life insurance in Kosovo is a very small market and no published term premium quotes or regulator premium data could be found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('XK', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The CBK supervises insurers but publishes no life claim settlement ratio; life insurance is tiny (EUR 4.1 million of written premiums by May 2026 per the CBK Monthly Report of Financial System).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('XK', 1, 'life_expectancy', 78.2, NULL, 'sourced', 'World Bank WDI SP.DYN.LE00.IN', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=XK', '2024-12-31', 'Men 76.0, women 80.3 (World Bank 2024; older than 2025, latest available); UN WPP includes Kosovo within Serbia, so no UN estimate is available separately.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('XK', 1, 'life_table_remaining', NULL, NULL, 'missing', '', '', '2026-10-31', 'UN WPP does not publish Kosovo separately (georank.org has no Kosovo page) and no Kosovo Agency of Statistics life table could be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('XK', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":65,"womenAge":65,"over90Monthly":null,"meansTested":false}', 'sourced', 'Kosovo 2.0 (news magazine), "Invisible in old age"', 'https://archive.kosovotwopointzero.com/en/?p=95845', '2023-12-05', 'Secondary source from 2023 (older than 2025): the basic pension is a universal, budget-funded benefit for Kosovo citizens aged 65 and over, paid regardless of work history and not means-tested.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('XK', 1, 'old_age_allowance_monthly', 150, NULL, 'sourced', 'Telegrafi (news), basic pension paid with the 30-euro increase, 14 November 2025', 'https://telegrafi.com/cmimet-e-larta-na-detyrojne-te-punojme-edhe-ne-pleqeri-pensionistet-te-pakenaqur-me-rritjen-prej-30-eurosh/', '2025-11-14', 'Secondary source (the Government and Ministry of Finance, Labour and Transfers sites did not resolve): the state-funded basic age pension rose from EUR 120 to EUR 150 a month from the November 2025 payment; no further 2026 change was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('XK', 1, 'oop_health_share', NULL, NULL, 'missing', '', '', '2026-10-31', 'World Bank SH.XPD.OOPC.CH.ZS and WHO GHED do not report Kosovo separately; no other figure found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('XK', 1, 'policy_rate', 0.025, NULL, 'sourced', 'European Central Bank, deposit facility rate', 'https://data-api.ecb.europa.eu/service/data/FM/B.U2.EUR.4F.KR.DFR.LEV', '2026-09-16', 'Kosovo has no monetary policy of its own: it uses the euro unilaterally, so the ECB deposit facility rate (2.50% from 16 September 2026) is the reference rate for the currency.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('XK', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":null,"entryAgeMax":null,"pensionFromAge":65,"nomineeUntilAge":null,"inflationLinked":false,"taxFree":false}', 'sourced', 'Kosovo Pension Savings Trust (KPST), withdrawal of savings', 'https://trusti.org/en/contributors/withdrawal-of-savings/', '2026-10-31', 'Mandatory funded individual accounts: 5% employee plus 5% employer contributions (PwC), voluntary up to 15% each; from 65 balances of EUR 3,000+ are paid as phased withdrawals of at least EUR 200 or 1% of the balance a month, not indexed, and withdrawals are subject to personal income tax. A separate state basic pension is paid from the budget.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('XK', 1, 'retirement_accumulation_return_base', 0.04, NULL, 'assumption', 'Global equity base 5.5%; Kosovo fixed income base 2.5%', 'https://bqk-kos.org/wp-content/uploads/2026/07/CBK_MSB_297_En.pdf', '2026-10-31', 'Base case: roughly half global shares at 5.5% and half deposits and government paper at about 2.5%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('XK', 1, 'retirement_accumulation_return_high', 0.055, NULL, 'assumption', 'Global equity high 7.5%; fixed income high 3%', 'https://taxsummaries.pwc.com/kosovo/individual/income-determination', '2026-10-31', 'High case for a growth-leaning balanced mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('XK', 1, 'retirement_accumulation_return_low', 0.025, NULL, 'assumption', 'Global equity low case 3%; Kosovo fixed income low case 2%', 'https://bqk-kos.org/wp-content/uploads/2026/07/CBK_MSB_297_En.pdf', '2026-10-31', 'Low case for a balanced mix if global shares lag.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('XK', 1, 'retirement_age_default', 65, NULL, 'sourced', 'Kosovo Pension Savings Trust (KPST), FAQ', 'https://trusti.org/en/contributors/faq/', '2026-10-31', 'Retirement age ''currently set at 65'' for withdrawing pension savings; the same age applies to the state basic pension.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('XK', 1, 'retirement_age_government', 65, NULL, 'sourced', 'Kosovo Pension Savings Trust (KPST), FAQ', 'https://trusti.org/en/contributors/faq/', '2026-10-31', 'Civil servants are in the same KPST and state pension system with retirement at 65; no separate civil service retirement age was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('XK', 1, 'retirement_return_base', 0.025, NULL, 'assumption', 'CBK household 6-12 month deposit rate 3.02% (May 2026), 2.72% after 10% withholding', 'https://bqk-kos.org/wp-content/uploads/2026/07/CBK_MSB_297_En.pdf', '2026-10-31', 'Base case kept below the after-tax 1-year deposit rate of about 2.7%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('XK', 1, 'retirement_return_high', 0.03, NULL, 'assumption', 'Kosovo government securities, interest tax-exempt (PwC); CBK 1-2 year deposit rate 3.21%', 'https://taxsummaries.pwc.com/kosovo/individual/income-determination', '2026-10-31', 'High case: a ladder of tax-exempt Kosovo government bonds and longer deposits.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('XK', 1, 'retirement_return_low', 0.018, NULL, 'assumption', 'CBK household deposit rates May 2026 less 10% withholding', 'https://bqk-kos.org/wp-content/uploads/2026/07/CBK_MSB_297_En.pdf', '2026-10-31', 'Low case: a retiree keeps much of the money in short deposits and savings accounts, after the 10% interest tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('XK', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Kosovo has no retail government savings certificate or savings bond for individuals that could be found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('XK', 1, 'savings_account_rate', 0.0028, NULL, 'sourced', 'Central Bank of the Republic of Kosovo, Monthly Statistics Bulletin May 2026 (Table 15.1.2, household new deposits)', 'https://bqk-kos.org/wp-content/uploads/2026/07/CBK_MSB_297_En.pdf', '2026-05-31', 'Weighted average rate on new household savings deposits, May 2026 (0.30-0.32% earlier in 2026); transferable deposits pay about 0%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('XK', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":6.61}]}', 'sourced', 'World Bank WDI SP.POP.DPND.OL', 'https://data.worldbank.org/indicator/SP.POP.DPND.OL?locations=XK', '2025-12-31', '100 / old-age dependency ratio of 15.1 (2025). No UN projections for Kosovo alone were found for 2040 or 2065.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('XK', 1, 'tax_bank_interest', 0.1, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Kosovo withholding taxes', 'https://taxsummaries.pwc.com/kosovo/corporate/withholding-taxes', '2026-08-07', '10% withholding on interest; PwC''s individual section says tax on savings-account interest is usually withheld by banks.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('XK', 1, 'tax_sanchayapatra_profit', 0, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Kosovo income determination', 'https://taxsummaries.pwc.com/kosovo/individual/income-determination', '2026-08-07', 'Interest on financial instruments issued or guaranteed by a Kosovo public authority is exempt from personal income tax; Kosovo has no retail savings certificate, so this applies to treasury bills and bonds.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('XK', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Ministry of Finance auctions government securities through the CBK, but no 2026 bill auction yield could be read (auction results pages and the Ministry of Finance site did not render; news reports found were from 2024).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('XK', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Kosovo rarely issues 10-year paper and no recent auction yield could be found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('XK', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 2026 5-year government bond auction yield could be read (auction results not found; news reports found were from 2024).', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('YE', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"YE","iso3":"YEM","nameEn":"Yemen","nameNative":"اليمن","region":"middle_east_north_africa","languages":["ar","en"],"currency":{"code":"YER","symbol":"ر.ي","decimals":0,"compact":"intl","usdRate":{"value":1562.49,"status":"sourced","sourceName":"Central Bank of Yemen (Aden), Monetary and financial developments, May 2026","sourceUrl":"https://www.cby-ye.com/files/6a5a2d18db074.pdf","asOf":"2026-05-31","note":"Average market rate of 1,562.49 rials per US dollar in May 2026 (1,562.93 in April). Figures are for the central bank in Aden; areas run by the Sanaa authorities use older banknotes at a different exchange rate and restrict interest. Trading Economics still shows an outdated official rate of about 236."}},"instruments":{"savings_account":{"available":true,"localName":"حساب توفير","localNameEn":"Savings account","note":"The central bank sets 18% a year on new rial savings deposits (May 2026).","sourceUrl":"https://www.cby-ye.com/files/6a5a2d18db074.pdf"},"fdr_3m":{"available":true,"localName":"وديعة لأجل (3 أشهر)","localNameEn":"Term deposit (3 months)","note":"Rates are set by banks."},"fdr_1y":{"available":true,"localName":"وديعة لأجل (سنة)","localNameEn":"Term deposit (1 year)","note":"Rates are set by banks."},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No standard monthly recurring deposit was confirmed."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate for individuals was confirmed."},"tbill_91d":{"available":false,"localName":"أذون الخزانة","localNameEn":"Treasury bills","note":"The central bank auctions one-year bills to banks with a 50 million rial minimum bid; no 3-month bills for individuals.","sourceUrl":"https://www.cby-ye.com/news/981"},"tbond_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No retail government bonds were found."},"tbond_10y":{"available":false,"localName":null,"localNameEn":null,"note":"No retail government bonds were found."},"equity_fund":{"available":false,"localName":null,"localNameEn":null,"note":"Yemen has no stock exchange or regulated retail mutual funds."},"gold":{"available":true,"localName":"الذهب","localNameEn":"Gold","note":"Gold jewellery and coins are widely bought as savings."}},"institutions":{"centralBank":{"name":"Central Bank of Yemen (head office, Aden)","url":"https://www.cby-ye.com/"},"statistics":{"name":"Central Statistical Organization","url":"https://www.cso-yemen.com/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('YE', 1, 'bank_deposit_avg_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No current weighted average deposit rate was found; the World Bank''s latest value is 15.25% for 2013, too old to use.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('YE', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap or typical credit card rate was found; lending rates are set freely by banks (Central Bank of Yemen, May 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('YE', 1, 'deposit_insurance_limit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No deposit insurance scheme or cover amount was found for Yemeni banks.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('YE', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No monthly recurring deposit product or published rate was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('YE', 1, 'equity_return_base', 0.15, NULL, 'assumption', 'No stock exchange in Yemen; global equity index about 7% a year in dollars; rial depreciation assumed about 8% a year', 'https://www.cby-ye.com/files/6a5a2d18db074.pdf', '2026-10-31', 'Yemen has no stock market, so the base case is a global index in rial terms (about 7% in dollars plus about 8% a year of depreciation), below the 18% savings rate plus 4 points.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('YE', 1, 'equity_return_high', 0.24, NULL, 'assumption', 'Global equity index in rial terms; rial history (about 250 per dollar in 2014 to 1,562 in May 2026)', 'https://www.cby-ye.com/files/6a5a2d18db074.pdf', '2026-10-31', 'High case: strong global markets and a renewed sharp rial depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('YE', 1, 'equity_return_low', 0.06, NULL, 'assumption', 'No stock exchange in Yemen; global equities in rial terms; rial 1,562 per dollar (May 2026)', 'https://www.cby-ye.com/files/6a5a2d18db074.pdf', '2026-10-31', 'Low case: global equities earn little in dollars while the rial holds steady.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('YE', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Banks set term deposit rates freely (Central Bank of Yemen, May 2026) and no industry-wide 1-year rate is published.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('YE', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'Banks set term deposit rates freely (Central Bank of Yemen, May 2026) and no industry-wide 3-month rate is published.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('YE', 1, 'fixed_income_return_base', 0.12, NULL, 'assumption', 'Central Bank of Yemen: 18% on new rial savings deposits (May 2026); one-year treasury bills at 20%', 'https://www.cby-ye.com/files/6a5a2d18db074.pdf', '2026-10-31', 'Base case: well below the posted 18% savings rate because tax treatment is unconfirmed and bank liquidity and cash-withdrawal limits make the posted rate hard to earn in full.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('YE', 1, 'fixed_income_return_high', 0.18, NULL, 'assumption', 'Central Bank of Yemen: 18% on new rial savings deposits; one-year treasury bills at 20% (November 2026 auction)', 'https://www.cby-ye.com/news/981', '2026-10-31', 'High case: the full posted savings rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('YE', 1, 'fixed_income_return_low', 0.08, NULL, 'assumption', 'Central Bank of Yemen: 18% on new rial savings deposits (May 2026)', 'https://www.cby-ye.com/files/6a5a2d18db074.pdf', '2026-10-31', 'Low case: deposit rates fall as the rial stabilises, and liquidity limits at banks reduce what savers actually earn.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('YE', 1, 'goal_inflation_education', 0.15, NULL, 'assumption', 'Inflation assumption 15%', 'https://www.cby-ye.com/files/6a5a2d18db074.pdf', '2026-10-31', 'No education price index could be read, so education goals use the general assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('YE', 1, 'goal_inflation_health', 0.17, NULL, 'assumption', 'Inflation assumption 15%; imported medicines priced in dollars', 'https://www.cby-ye.com/files/6a5a2d18db074.pdf', '2026-10-31', 'Medicines and private care are largely imported and priced off the dollar, so health goals are planned 2 points above the general assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('YE', 1, 'gold_return_base', 0.13, NULL, 'assumption', 'Rial 1,562 per dollar (May 2026); inflation assumption 15%; long-run dollar gold trend about 4%', 'https://www.cby-ye.com/files/6a5a2d18db074.pdf', '2026-10-31', 'Base case: about 4% dollar gold trend plus about 9% a year of rial depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('YE', 1, 'gold_return_high', 0.25, NULL, 'assumption', 'Rial history: 1,756 per dollar in May 2024, 2,534 in May 2025, 1,562 in May 2026 (Central Bank of Yemen)', 'https://www.cby-ye.com/files/6a5a2d18db074.pdf', '2026-10-31', 'High case: strong dollar gold and a renewed collapse of the rial like 2021-2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('YE', 1, 'gold_return_low', 0.04, NULL, 'assumption', 'Rial 1,562 per dollar (May 2026), stable since August 2025', 'https://www.cby-ye.com/files/6a5a2d18db074.pdf', '2026-10-31', 'Low case: flat dollar gold and a stable rial.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('YE', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Labour Code (Law No. 5 of 1995) is reported to provide an end-of-service award for workers not covered by social insurance, but its terms could not be read from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('YE', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a major private hospital stay was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('YE', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premiums by age were found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('YE', 1, 'inflation_cpi', NULL, NULL, 'missing', '', '', '2026-10-31', 'No year-on-year inflation rate could be read: the Central Bank of Yemen''s May 2026 report gives only the monthly CPI change (index 98.19 to 100.05, +1.89% in May 2026, from the Central Statistical Organization), the statistics office site refused requests, and the World Bank''s latest figure is from 2014.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('YE', 1, 'inflation_projection', 0.15, NULL, 'assumption', 'Central Bank of Yemen (Aden): monthly CPI +1.89% in May 2026; rial 1,562 per dollar after a 2025 peak near 2,900', 'https://www.cby-ye.com/files/6a5a2d18db074.pdf', '2026-10-31', 'Inflation in government areas ran at 20 to 30% a year during the currency collapse before the 2025-2026 stabilisation, so a planning rate of 15% allows for renewed depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('YE', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published term life premium rates per YER 1,000 by age were found; the life insurance market is very small.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('YE', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No industry-wide life claim settlement ratio was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('YE', 1, 'life_expectancy', 69.439, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN), Yemen', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=YE', '2024-12-31', '69.4 years in 2024 (men 67.4, women 71.5).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('YE', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":17.6,"men":16.5,"women":18.6},{"age":65,"total":14,"men":13.1,"women":14.8},{"age":70,"total":10.8,"men":10.1,"women":11.4},{"age":80,"total":5.8,"men":5.5,"women":6.1}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/yemen/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026; the 65 total is published there, the other totals are the mean of men and women.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('YE', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'Social Welfare Fund cash transfers target poor households rather than an age group; no age-based eligibility rule was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('YE', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Social Welfare Fund pays means-tested cash transfers to poor households, including elderly people, but its current amount and whether payments are regular could not be confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('YE', 1, 'oop_health_share', 0.691, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), Yemen', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=YE', '2023-12-31', '69.1% in 2023 (WHO Global Health Expenditure Database via the World Bank); older than 2025, the latest available.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('YE', 1, 'policy_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Central Bank of Yemen (Aden) sets a minimum rate on rial savings deposits (18%) and a 20% coupon on one-year treasury bills, but publishes no single policy rate; Trading Economics'' 27% is from 2022. Figures are for the central bank in Aden; areas run by the Sanaa authorities use older banknotes at a different exchange rate and restrict interest.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('YE', 1, 'public_pension_scheme', NULL, NULL, 'missing', '', '', '2026-10-31', 'Public-sector employees are insured by the General Authority for Social Insurance and Pensions and private-sector employees by the General Corporation for Social Security, but pension ages and indexation could not be read from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('YE', 1, 'retirement_accumulation_return_base', 0.13, NULL, 'assumption', 'Fixed income base 12%; global equity base 15%; gold base 13%', 'https://www.cby-ye.com/files/6a5a2d18db074.pdf', '2026-10-31', 'Base case: a balanced mix of rial deposits, gold and global equities.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('YE', 1, 'retirement_accumulation_return_high', 0.2, NULL, 'assumption', 'Equity high 24%; gold high 25%', 'https://www.cby-ye.com/files/6a5a2d18db074.pdf', '2026-10-31', 'High case: a growth-leaning mix with rial depreciation boosting foreign assets.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('YE', 1, 'retirement_accumulation_return_low', 0.07, NULL, 'assumption', 'Fixed income low 8%; equity low 6%; gold low 4%', 'https://www.cby-ye.com/files/6a5a2d18db074.pdf', '2026-10-31', 'Low case: a mix of rial deposits, gold and foreign assets earning little.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('YE', 1, 'retirement_age_default', NULL, NULL, 'missing', '', '', '2026-10-31', 'The pension age under the Social Insurance Law for private-sector workers could not be read from an official source; the social security corporation''s site could not be found and the US SSA country pages refused requests.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('YE', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'The retirement age for civil servants could not be read from an official source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('YE', 1, 'retirement_return_base', 0.11, NULL, 'assumption', 'Central Bank of Yemen: 18% on new rial savings deposits (May 2026)', 'https://www.cby-ye.com/files/6a5a2d18db074.pdf', '2026-10-31', 'Base case: below the posted savings rate, allowing for unconfirmed tax and bank liquidity limits, so not above the after-tax safe rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('YE', 1, 'retirement_return_high', 0.16, NULL, 'assumption', 'Central Bank of Yemen: 18% on new rial savings deposits; one-year treasury bills at 20%', 'https://www.cby-ye.com/news/981', '2026-10-31', 'High case: near the posted savings rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('YE', 1, 'retirement_return_low', 0.08, NULL, 'assumption', 'Central Bank of Yemen: 18% on new rial savings deposits (May 2026)', 'https://www.cby-ye.com/files/6a5a2d18db074.pdf', '2026-10-31', 'Low case: deposit rates fall and access to deposits stays limited.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('YE', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate sold to individuals was confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('YE', 1, 'savings_account_rate', 0.18, NULL, 'sourced', 'Central Bank of Yemen (Aden), Monetary and financial developments, May 2026', 'https://www.cby-ye.com/files/6a5a2d18db074.pdf', '2026-05-31', 'The central bank set the interest rate on new rial savings deposits at commercial banks at 18% a year and leaves term deposit rates to banks. Figures are for the central bank in Aden; areas run by the Sanaa authorities use older banknotes at a different exchange rate and restrict interest.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('YE', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":22.2},{"year":2040,"value":16.9},{"year":2065,"value":8.2}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/yemen/2040/', '2025-12-31', '100 / old-age dependency ratio: 4.51 (2025, World Bank), 5.9 (2040) and 12.2 (2065, populationpyramid.net/yemen/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('YE', 1, 'tax_bank_interest', NULL, NULL, 'missing', '', '', '2026-10-31', 'The tax treatment of bank interest for individuals could not be confirmed; PwC Worldwide Tax Summaries does not cover Yemen and the Tax Authority site could not be found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('YE', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'There is no government savings certificate for individuals, and the tax on government security interest could not be confirmed.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('YE', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Central Bank of Yemen (Aden) currently auctions one-year treasury bills at a 20% coupon (auction of 4 November 2026, minimum bid 50 million rials) to banks; no 3-month yield is published.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('YE', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 10-year government bond yield is published.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('YE', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No 5-year government bond yield is published.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('ZA', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"ZA","iso3":"ZAF","nameEn":"South Africa","nameNative":"iNingizimu Afrika","region":"sub_saharan_africa","languages":["zu","xh","af","en","nso"],"currency":{"code":"ZAR","symbol":"R","decimals":2,"compact":"intl","usdRate":{"value":16.71,"status":"sourced","sourceName":"Federal Reserve H.10 (FRED DEXSFUS), South African rand per US dollar, 30 October 2026","sourceUrl":"https://fred.stlouisfed.org/series/DEXSFUS","asOf":"2026-10-30","note":"R16.7055 per dollar on 30 October 2026; the SARB shows R16.6795 on 2 November 2026 (World Bank 2025 average 17.89)."}},"instruments":{"savings_account":{"available":true,"localName":null,"localNameEn":"Savings account"},"fdr_3m":{"available":true,"localName":null,"localNameEn":"Fixed deposit, 3 months","note":"Banks offer fixed and notice deposits; no official typical rate is published."},"fdr_1y":{"available":true,"localName":null,"localNameEn":"Fixed deposit, 12 months"},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No standard monthly recurring deposit scheme was found; the RSA Top Up Retail Savings Bond accepts additions from R100."},"sanchayapatra_5y":{"available":true,"localName":"RSA Retail Savings Bond","localNameEn":"RSA Retail Savings Bond (fixed rate, 5 years)","note":"Sold by National Treasury to South African citizens with an ID number and a local bank account; 2, 3 and 5-year fixed rate, 3, 5 and 10-year inflation-linked, and a Top Up bond; early withdrawal after 12 months with a penalty.","sourceUrl":"https://www.rsaretailbonds.gov.za/rates.aspx"},"tbill_91d":{"available":true,"localName":null,"localNameEn":"Treasury bill","note":"91, 182, 273 and 364-day bills auctioned weekly by the SARB for National Treasury; mostly bought by institutions.","sourceUrl":"https://custom.resbank.co.za/SarbWebApi/WebIndicators/CurrentMarketRates"},"tbond_5y":{"available":true,"localName":null,"localNameEn":"RSA government bond (fixed rate)","note":"Fixed-rate bonds such as the R2030 are traded on the JSE.","sourceUrl":"https://custom.resbank.co.za/SarbWebApi/WebIndicators/CurrentMarketRates"},"tbond_10y":{"available":true,"localName":null,"localNameEn":"RSA government bond","note":"Benchmarks include the R209 (2036).","sourceUrl":"https://custom.resbank.co.za/SarbWebApi/WebIndicators/CurrentMarketRates"},"equity_fund":{"available":true,"localName":"Unit trust","localNameEn":"Unit trusts (collective investment schemes) and exchange-traded funds","note":"Regulated by the FSCA; can be held in a tax-free savings account."},"gold":{"available":true,"localName":null,"localNameEn":"Gold coins and bars","note":"Gold bullion coins and bars are legally bought and held by individuals."}},"institutions":{"centralBank":{"name":"South African Reserve Bank","url":"https://www.resbank.co.za/"},"insuranceRegulator":{"name":"Financial Sector Conduct Authority (FSCA)","url":"https://www.fsca.co.za/","note":"Insurers are also prudentially supervised by the Prudential Authority within the SARB."},"insuranceComplaints":{"name":"FSCA complaints and enquiries","url":"https://www2.fsca.co.za/CRM_Web_Extentions/enquiry.aspx","note":"Disputes with an insurer usually go first to the National Financial Ombud Scheme."},"pensionScheme":null,"oldAgeAllowance":{"name":"Older Persons Grant (SASSA)","url":"https://www.gov.za/services/social-benefits-retirement-and-old-age/old-age-pension"},"publicHealthCover":{"name":"National Department of Health (public hospitals and clinics)","url":"https://www.health.gov.za/"},"depositInsurance":{"name":"Corporation for Deposit Insurance (CODI)","url":"https://www.codi.co.za/"},"statistics":{"name":"Statistics South Africa","url":"https://www.statssa.gov.za/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZA', 1, 'bank_deposit_avg_rate', 0.0748, NULL, 'sourced', 'World Bank WDI, deposit interest rate (FR.INR.DPST), South Africa', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=ZA', '2025-12-31', '7.48% average for 2025 (IMF International Financial Statistics via World Bank); no fresher official average deposit rate was found. The repo rate is 7.25% in October 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZA', 1, 'credit_card_rate_cap', 0.2125, NULL, 'sourced', 'Department of Trade and Industry, Review of Limitations on Fees and Interest Rates Regulations (National Credit Act), Government Gazette 39379, 6 November 2015', 'https://www.ncr.org.za/documents/pages/Acts/SKM_C284e15110908440.compressed.pdf', '2026-09-23', 'Table A of the 2015 regulations sets the maximum prescribed rate for credit facilities (credit cards, overdrafts) at the repo rate plus 14% a year: 7.25% + 14% = 21.25% since the 23 September 2026 repo change; the regulations date from 2015 (older than 2025) and remain the published cap.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZA', 1, 'deposit_insurance_limit', 100000, NULL, 'sourced', 'Wikipedia, Deposit insurance (Corporation for Deposit Insurance, South Africa)', 'https://en.wikipedia.org/wiki/Deposit_insurance', '2024-04-01', 'Secondary source: the Corporation for Deposit Insurance (CODI), a SARB subsidiary launched in April 2024, covers up to R100,000 per depositor per bank (Wikipedia, citing EWN 25 April 2024); the limit dates from 2024 (older than 2025) and no later change was found; the SARB and CODI pages could not be loaded.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZA', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No standard monthly recurring deposit scheme with a published rate was found; the nearest public product is the RSA Top Up Retail Savings Bond (8.50%, interest capitalised, see sanchayapatra_5y).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZA', 1, 'equity_return_base', 0.1, NULL, 'assumption', 'South African Reserve Bank current market rates; RSA Retail Savings Bond 5-year 9.00%', 'https://custom.resbank.co.za/SarbWebApi/WebIndicators/CurrentMarketRates', '2026-10-31', 'Base case: the JSE has a long record of returns above inflation but a patchy last decade, so equities are put about 3.3 points above the after-tax 5-year retail bond yield (9.00% less 26% tax = 6.7%), inside the 4-point cap.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZA', 1, 'equity_return_high', 0.13, NULL, 'assumption', 'South African Reserve Bank current market rates', 'https://custom.resbank.co.za/SarbWebApi/WebIndicators/CurrentMarketRates', '2026-10-31', 'High case: a strong decade for local shares or a global index fund in rand terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZA', 1, 'equity_return_low', 0.07, NULL, 'assumption', 'South African Reserve Bank current market rates (government bond yields as the safe-rate reference)', 'https://custom.resbank.co.za/SarbWebApi/WebIndicators/CurrentMarketRates', '2026-10-31', 'Low case: a weak decade for JSE shares, about level with pre-tax government bond yields.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZA', 1, 'fdr_1y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No official typical 1-year retail fixed deposit rate was found; the SARB publishes only the wholesale 12-month NCD rate (8.03% on 30 October 2026), which is not a retail rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZA', 1, 'fdr_3m_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No official typical 3-month retail fixed deposit rate was found; the SARB publishes only the wholesale 3-month NCD rate (7.25% on 30 October 2026), which is not a retail rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZA', 1, 'fixed_income_return_base', 0.06, NULL, 'assumption', 'RSA Retail Savings Bonds rates (8.25-9.00%); SARB treasury bill tender rates (7.16-7.46%)', 'https://www.rsaretailbonds.gov.za/rates.aspx', '2026-10-31', 'Base case: retail savings bonds and treasury bills at 7.5-9% less 26% tax on interest above the exemption, about 5.5-6.7% after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZA', 1, 'fixed_income_return_high', 0.075, NULL, 'assumption', 'RSA Retail Savings Bonds rates (5-year fixed 9.00%)', 'https://www.rsaretailbonds.gov.za/rates.aspx', '2026-10-31', 'High case: savers whose interest stays within the R23,800 exemption (R34,500 from 65) and so pay no tax on 7.5-9% yields.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZA', 1, 'fixed_income_return_low', 0.045, NULL, 'assumption', 'World Bank deposit interest rate 2025 (7.48%); PwC Tax Summaries (26% marginal band)', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=ZA', '2026-10-31', 'Low case: ordinary bank deposits at about 6% less 26% tax on interest above the yearly exemption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZA', 1, 'goal_inflation_education', 0.06, NULL, 'assumption', 'Stats SA CPI via SARB key indicators (education fees reset each year)', 'https://custom.resbank.co.za/SarbWebApi/WebIndicators/HomePageRates', '2026-10-31', 'School and university fees have risen faster than headline CPI, so 1.5 points above the 4.5% inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZA', 1, 'goal_inflation_health', 0.07, NULL, 'assumption', 'Stats SA CPI via SARB key indicators; medical scheme contributions usually rise faster than CPI', 'https://custom.resbank.co.za/SarbWebApi/WebIndicators/HomePageRates', '2026-10-31', 'Medical scheme contributions and private hospital tariffs have risen several points faster than headline CPI for many years, so 2.5 points above the 4.5% inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZA', 1, 'gold_return_base', 0.07, NULL, 'assumption', 'World Bank official exchange rate history (rand per US dollar); SARB London gold price in rand', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=ZA', '2026-10-31', 'Base case: the long-run dollar gold trend of about 4% a year plus about 3% a year of rand depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZA', 1, 'gold_return_high', 0.11, NULL, 'assumption', 'Federal Reserve H.10, South African rand per US dollar', 'https://fred.stlouisfed.org/series/DEXSFUS', '2026-10-31', 'High case: strong gold years and a weaker rand.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZA', 1, 'gold_return_low', 0.02, NULL, 'assumption', 'Federal Reserve H.10, South African rand per US dollar', 'https://fred.stlouisfed.org/series/DEXSFUS', '2026-10-31', 'Low case: flat dollar gold and a small rand depreciation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZA', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'South Africa has no statutory gratuity or end-of-service benefit on retirement or resignation: the Basic Conditions of Employment Act section 41 only requires severance pay of one week''s remuneration per completed year of service when an employee is dismissed for operational requirements (retrenchment) (https://www.labour.gov.za/DocumentCenter/Acts/Basic%20Conditions%20of%20Employment/Amended%20Act%20-%20Basic%20Conditions%20of%20Employment.pdf).', 1);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZA', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a major private hospital stay was found from an official or international source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZA', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Private health cover is provided by medical schemes with community-rated contributions (not priced per 100,000 rand of cover by age); no usable published table was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZA', 1, 'inflation_cpi', 0.045, NULL, 'sourced', 'South African Reserve Bank, key indicators (Stats SA headline CPI, year on year), September 2026', 'https://custom.resbank.co.za/SarbWebApi/WebIndicators/HomePageRates', '2026-09-30', 'Headline consumer inflation 4.5% in September 2026 (4.4% in August, per Trading Economics); the Stats SA release page itself could not be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZA', 1, 'inflation_projection', 0.045, NULL, 'assumption', 'SARB inflation target (3-6% range, now steering towards 3%) as reported by Trading Economics; SARB key indicators CPI 4.5% (September 2026)', 'https://tradingeconomics.com/south-africa/interest-rate', '2026-10-31', 'The SARB is steering towards the low end of its 3-6% range but CPI is 4.5% today and has averaged about 5% in recent years, so 4.5% is used for long-range plans.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZA', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life cover is sold, but no published premium rates per 1,000 rand of cover by age were found from the regulator or another public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZA', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The FSCA and Prudential Authority publish no industry-wide life claim settlement ratio that could be found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZA', 1, 'life_expectancy', 66.312, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN), South Africa', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=ZA', '2024-12-31', '66.3 years in 2024 (men 62.8, women 69.8); UN WPP 2024 via populationpyramid.net gives 66.7 for 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZA', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":18.5,"men":16.5,"women":20.4},{"age":65,"total":15.7,"men":13.9,"women":17.1},{"age":70,"total":12.9,"men":11.7,"women":14.1},{"age":80,"total":8.6,"men":8,"women":9.1}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/south-africa/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZA', 1, 'old_age_allowance_eligibility', NULL, '{"menAge":60,"womenAge":60,"over90Monthly":null,"meansTested":true}', 'sourced', 'South African Government, Old age pension (Older Persons Grant) service page', 'https://www.gov.za/services/social-benefits-retirement-and-old-age/old-age-pension', '2026-10-31', 'Citizens, permanent residents and refugees aged 60 and over; means-tested (income up to R86,280 a year single or R172,560 married; assets up to R1,227,600 single or R2,455,200 married). Over-75s get R20 more.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZA', 1, 'old_age_allowance_monthly', 2400, NULL, 'sourced', 'National Treasury, 2026 Budget Speech (social grants)', 'https://archive.treasury.gov.za/documents/national%20budget/2026/speech/speech.pdf', '2026-04-01', 'The old age grant rose by R80 to R2,400 a month in April 2026; people aged 75 and over get R2,420 (gov.za old age pension page).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZA', 1, 'oop_health_share', 0.0669, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), South Africa', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=ZA', '2023-12-31', '6.7% in 2023 (WHO Global Health Expenditure Database); older than 2025, the latest available.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZA', 1, 'policy_rate', 0.0725, NULL, 'sourced', 'South African Reserve Bank, current market rates (SARB policy rate)', 'https://custom.resbank.co.za/SarbWebApi/WebIndicators/CurrentMarketRates', '2026-09-23', 'SARB policy (repo) rate 7.25% on the SARB current market rates page; it was raised by 25 basis points from 7.00% on 23 September 2026 (Trading Economics, secondary, for the date). Prime lending rate 10.75%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZA', 1, 'public_pension_scheme', NULL, NULL, 'missing', '', '', '2026-10-31', 'No public contributory old-age pension was found: the state provides the tax-funded, means-tested Older Persons Grant, retirement savings are through employer and private funds (the two-pot system), and the Unemployment Insurance Fund pays no old-age benefit; a source stating outright that no such scheme exists could not be loaded, so this is not marked absent.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZA', 1, 'retirement_accumulation_return_base', 0.085, NULL, 'assumption', 'SARB current market rates; equity base 10%; gold base 7%', 'https://custom.resbank.co.za/SarbWebApi/WebIndicators/CurrentMarketRates', '2026-10-31', 'Base case: a balanced mix of government bonds (8-9%), local and global equity funds and a little gold, as in a typical retirement annuity or tax-free savings account.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZA', 1, 'retirement_accumulation_return_high', 0.105, NULL, 'assumption', 'SARB current market rates; equity high 13%', 'https://custom.resbank.co.za/SarbWebApi/WebIndicators/CurrentMarketRates', '2026-10-31', 'High case: a growth-leaning mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZA', 1, 'retirement_accumulation_return_low', 0.06, NULL, 'assumption', 'SARB current market rates (bond yields 8.0-8.7%)', 'https://custom.resbank.co.za/SarbWebApi/WebIndicators/CurrentMarketRates', '2026-10-31', 'Low case: a cautious mix earning a little above after-tax bond yields.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZA', 1, 'retirement_age_default', 60, NULL, 'sourced', 'South African Government, Old age pension (Older Persons Grant) service page', 'https://www.gov.za/services/social-benefits-retirement-and-old-age/old-age-pension', '2026-10-31', 'There is no statutory retirement age for private-sector workers (employers and their retirement funds set it, often 60-65) and no public contributory pension; the state Older Persons Grant is payable from 60 for men and women, so 60 is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZA', 1, 'retirement_age_government', 60, NULL, 'sourced', 'Government Employees Pension Fund, Retiring from the public service', 'https://www.gepf.co.za/retiring-from-the-public-service/', '2026-10-31', 'Normal retirement age for public servants in the GEPF is 60; early retirement from 55 with the employer''s permission. Public servants may usually stay on to 65, which the page does not state.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZA', 1, 'retirement_return_base', 0.055, NULL, 'assumption', 'SARB treasury bill tender rates (364-day 7.46%); PwC Tax Summaries (26% marginal band)', 'https://custom.resbank.co.za/SarbWebApi/WebIndicators/CurrentMarketRates', '2026-10-31', 'Base case: equal to the 1-year treasury bill yield after 26% tax (7.46% x 0.74 = 5.5%); retirees whose interest stays under the R34,500 exemption can do better.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZA', 1, 'retirement_return_high', 0.07, NULL, 'assumption', 'RSA Retail Savings Bonds rates (2-year 8.25%, 5-year 9.00%)', 'https://www.rsaretailbonds.gov.za/rates.aspx', '2026-10-31', 'High case: retail savings bonds with interest mostly inside the over-65 exemption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZA', 1, 'retirement_return_low', 0.045, NULL, 'assumption', 'World Bank deposit interest rate 2025; PwC Tax Summaries', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=ZA', '2026-10-31', 'Low case: bank deposits after tax above the R34,500 over-65 interest exemption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZA', 1, 'sanchayapatra_5y_rate', 0.09, NULL, 'sourced', 'National Treasury, RSA Retail Savings Bonds rates page (5-year fixed rate bond)', 'https://www.rsaretailbonds.gov.za/rates.aspx', '2026-10-31', '5-year fixed rate retail savings bond pays 9.00% for bonds bought 1-30 November 2026 (2-year 8.25%, 3-year 8.50%); inflation-linked 5-year bond 4.50% above CPI (1 June-30 November 2026); Top Up bond 8.50% (1 October-31 December 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZA', 1, 'savings_account_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The SARB current market rates and key indicators publish no retail savings-account rate, and no other official figure was found; only bank-specific rate sheets exist, which cannot be used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZA', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":9.79},{"year":2040,"value":7.58},{"year":2065,"value":4.59}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/south-africa/2040/', '2025-12-31', '100 / old-age dependency ratio: 10.2 (2025, World Bank), 13.2 (2040) and 21.8 (2065, populationpyramid.net/south-africa/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZA', 1, 'tax_bank_interest', 0.26, NULL, 'sourced', 'PwC Worldwide Tax Summaries, South Africa, income determination and taxes on personal income (2026/27)', 'https://taxsummaries.pwc.com/south-africa/individual/income-determination', '2026-05-29', 'No withholding tax for residents: interest above the yearly exemption (R23,800 under 65, R34,500 from 65) is taxed at the marginal rate, 26% in the R245,101-R383,100 band used here (18% to 45% overall, see https://taxsummaries.pwc.com/south-africa/individual/taxes-on-personal-income).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZA', 1, 'tax_sanchayapatra_profit', 0.26, NULL, 'sourced', 'PwC Worldwide Tax Summaries, South Africa, income determination', 'https://taxsummaries.pwc.com/south-africa/individual/income-determination', '2026-05-29', 'RSA Retail Savings Bond interest is ordinary interest: it shares the R23,800 (R34,500 from 65) yearly interest exemption and the excess is taxed at the marginal rate (26% band used here); government bond interest is not on PwC''s list of exempt income.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZA', 1, 'tbill_91d_rate', 0.0716, NULL, 'sourced', 'South African Reserve Bank, current market rates (Treasury bills 91-day tender rate)', 'https://custom.resbank.co.za/SarbWebApi/WebIndicators/CurrentMarketRates', '2026-10-30', '91-day tender rate 7.16% on 30 October 2026; 182-day 7.40%, 364-day 7.46%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZA', 1, 'tbond_10y_rate', 0.0871, NULL, 'sourced', 'South African Reserve Bank, current market rates (6.25% 2036 R209 closing yield)', 'https://custom.resbank.co.za/SarbWebApi/WebIndicators/CurrentMarketRates', '2026-10-30', 'Closing yield on the R209 bond (matures March 2036, about 9.4 years) 8.71% on 30 October 2026; average yield on bonds of 10 years and longer 8.74%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZA', 1, 'tbond_5y_rate', 0.08005, NULL, 'sourced', 'South African Reserve Bank, current market rates (8.00% 2030 R2030 closing yield)', 'https://custom.resbank.co.za/SarbWebApi/WebIndicators/CurrentMarketRates', '2026-10-30', 'Closing yield on the R2030 bond (matures January 2030, about 3.3 years) 8.005% on 30 October 2026, the closest benchmark the SARB publishes; the 5-10 year average bond yield was 8.54%. Trading Economics shows a 5-year yield of 8.13% on 2 November 2026.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('ZM', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"ZM","iso3":"ZMB","nameEn":"Zambia","nameNative":"Zambia","region":"sub_saharan_africa","languages":["bem","en","ny","loz"],"currency":{"code":"ZMW","symbol":"K","decimals":2,"compact":"intl","usdRate":{"value":20.2297,"status":"sourced","sourceName":"Bank of Zambia, daily ZMW/USD rates feed (Bank of Zambia Exchange Rates page), 30 October 2026, 15:30","sourceUrl":"https://www.boz.zm/api/v1/views/boz_zmw_usd_daily_exchange_rates","asOf":"2026-10-30","note":"Mid rate K20.2297 per US dollar on 30 October 2026 (buying 20.2047, selling 20.2547), from the Bank of Zambia''s daily rate feed behind its exchange-rate page (https://www.boz.zm/markets-securities/boz-exchange-rates, which shows only the latest day). The World Bank 2025 average was 25.28."}},"instruments":{"savings_account":{"available":true,"localName":null,"localNameEn":"Savings account","sourceUrl":"https://www.boz.zm/sites/default/files/2026-10/StatisticsFortnightly2026Vol33IssueNo_21.pdf"},"fdr_3m":{"available":true,"localName":"Time deposit","localNameEn":"Time deposit, 3 months","note":"The Bank of Zambia publishes average retail and non-retail rates for 1, 3, 6, 9 and 12-month time deposits.","sourceUrl":"https://www.boz.zm/sites/default/files/2026-10/StatisticsFortnightly2026Vol33IssueNo_21.pdf"},"fdr_1y":{"available":true,"localName":"Time deposit","localNameEn":"Time deposit, 12 months","sourceUrl":"https://www.boz.zm/sites/default/files/2026-10/StatisticsFortnightly2026Vol33IssueNo_21.pdf"},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No standard monthly recurring deposit product was found."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate or retail savings bond for individuals was found; individuals can buy treasury bills and bonds at Bank of Zambia auctions."},"tbill_91d":{"available":true,"localName":"Treasury bill","localNameEn":"Treasury bill","note":"91, 182, 273 and 364-day bills auctioned fortnightly by the Bank of Zambia for the government.","sourceUrl":"https://www.boz.zm/sites/default/files/2026-10/Treasury-Bills-Results-Tender-No-22-2026-29-10-2026.pdf"},"tbond_5y":{"available":true,"localName":"GRZ bond","localNameEn":"Government bond","note":"The 5-year tenor was last offered in February 2026; 2, 3, 7, 10 and 15-year bonds are auctioned regularly.","sourceUrl":"https://www.boz.zm/sites/default/files/2026-09/Bonds-Press-Results-07-2026-BA.pdf"},"tbond_10y":{"available":true,"localName":"GRZ bond","localNameEn":"Government bond","sourceUrl":"https://www.boz.zm/sites/default/files/2026-09/Bonds-Press-Results-07-2026-BA.pdf"},"equity_fund":{"available":true,"localName":"Collective investment scheme","localNameEn":"Collective investment schemes (unit trusts)","note":"Supervised by the Securities and Exchange Commission of Zambia."},"gold":{"available":true,"localName":null,"localNameEn":"Gold","note":"No official retail bullion product was found; gold is mostly bought as jewellery."}},"institutions":{"centralBank":{"name":"Bank of Zambia","url":"https://www.boz.zm/"},"insuranceRegulator":{"name":"Pensions and Insurance Authority (PIA)","url":"https://www.pia.org.zm/"},"insuranceComplaints":{"name":"Pensions and Insurance Authority, complaints procedure","url":"https://www.pia.org.zm/?page_id=9647"},"pensionScheme":{"name":"National Pension Scheme Authority (NAPSA)","url":"https://www.napsa.co.zm/","note":"Site behind a bot check on 31 October 2026; the scheme is governed by the National Pension Scheme Act No. 72 of 2026."},"oldAgeAllowance":null,"publicHealthCover":{"name":"National Health Insurance Management Authority (NHIMA)","url":"https://www.nhima.co.zm/"},"depositInsurance":{"name":"Deposit Insurance Scheme (Bank of Zambia)","url":"https://www.boz.zm/financial-stability/what-is-the-deposit-insurance-scheme"},"statistics":{"name":"Zambia Statistics Agency (ZamStats)","url":"https://www.zamstats.gov.zm/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZM', 1, 'bank_deposit_avg_rate', 0.0872, NULL, 'sourced', 'World Bank WDI, deposit interest rate (FR.INR.DPST), Zambia', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=ZM', '2020-12-31', '8.72% for 2020, the latest World Bank figure (older than 2025); the Bank of Zambia publishes only simple averages by product (retail savings 2.83%, 12-month retail 10.17% in October 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZM', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap or published typical credit card rate was found; the Bank of Zambia publishes only the average retail lending rate (27.3% in the week ending 9 October 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZM', 1, 'deposit_insurance_limit', 250000, NULL, 'sourced', 'Bank of Zambia, Deposit Insurance Scheme: What is the Deposit Insurance Scheme? (coverage limit)', 'https://www.boz.zm/financial-stability/what-is-the-deposit-insurance-scheme', '2026-10-31', 'Coverage limit K250,000 per depositor per member institution, with all accounts at one institution added together (interest included). Foreign currency deposits are covered but paid out in kwacha. The page gives no date for the limit, so asOf is the research date.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZM', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No monthly recurring deposit product or published rate was found in Bank of Zambia statistics.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZM', 1, 'equity_return_base', 0.13, NULL, 'assumption', 'Bank of Zambia, Monetary Policy Report August 2026 (LuSE All-Share Index 27,328 in June 2026); 12-month deposit rate 10.17% (tax free)', 'https://www.boz.zm/sites/default/files/2026-10/Monetary%20Policy%20Report%202026%20%28August%20Edition%29.pdf', '2026-10-31', 'Base case: about 3 points above the tax-free 1-year deposit rate (10.2%), under the 4-point cap, because the strong 2021-2026 rally came after a flat 2015-2020 and the market is small and illiquid.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZM', 1, 'equity_return_high', 0.17, NULL, 'assumption', 'Bank of Zambia, Monetary Policy Report August 2026 (LuSE All-Share Index)', 'https://www.boz.zm/sites/default/files/2026-10/Monetary%20Policy%20Report%202026%20%28August%20Edition%29.pdf', '2026-10-31', 'High case: a repeat of the strong mining-led gains of 2021-2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZM', 1, 'equity_return_low', 0.08, NULL, 'assumption', 'Bank of Zambia, Monetary Policy Report August 2026 (LuSE All-Share Index)', 'https://www.boz.zm/sites/default/files/2026-10/Monetary%20Policy%20Report%202026%20%28August%20Edition%29.pdf', '2026-10-31', 'Low case: the small, concentrated local market goes through a flat decade like 2015-2020 and returns little more than inflation.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZM', 1, 'fdr_1y_rate', 0.1017, NULL, 'sourced', 'Bank of Zambia, Fortnightly Statistics Vol. 33 No. 21 (27 October 2026), table 07 commercial banks'' interest rates', 'https://www.boz.zm/sites/default/files/2026-10/StatisticsFortnightly2026Vol33IssueNo_21.pdf', '2026-10-09', 'Average retail 12-month time deposit rate 10.17% in the week ending 9 October 2026 (non-retail 9.72%); 6-month 7.14%, 9-month 8.74%. Rates may fall after the September 2026 policy rate cut.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZM', 1, 'fdr_3m_rate', 0.0547, NULL, 'sourced', 'Bank of Zambia, Fortnightly Statistics Vol. 33 No. 21 (27 October 2026), table 07 commercial banks'' interest rates', 'https://www.boz.zm/sites/default/files/2026-10/StatisticsFortnightly2026Vol33IssueNo_21.pdf', '2026-10-09', 'Average retail 3-month time deposit rate 5.47% in the week ending 9 October 2026 (non-retail 6.75%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZM', 1, 'fixed_income_return_base', 0.095, NULL, 'assumption', 'Bank of Zambia, Fortnightly Statistics Vol. 33 No. 21 (27 October 2026), table 07 commercial banks'' interest rates; treasury bill auction 29 October 2026', 'https://www.boz.zm/sites/default/files/2026-10/StatisticsFortnightly2026Vol33IssueNo_21.pdf', '2026-10-31', 'Base case: 12-month retail deposits at 10.17% (interest tax free) and 364-day bills at 10.00% (8.5% after 15% withholding if it applies), trimmed for the falling rate cycle.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZM', 1, 'fixed_income_return_high', 0.12, NULL, 'assumption', 'Bank of Zambia, GRZ bond auction results, tender 07/2026/BA (25 September 2026)', 'https://www.boz.zm/sites/default/files/2026-09/Bonds-Press-Results-07-2026-BA.pdf', '2026-10-31', 'High case: 10-year government bonds at 14.50% less 15% withholding tax on coupons (about 12.3%).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZM', 1, 'fixed_income_return_low', 0.055, NULL, 'assumption', 'Bank of Zambia, Fortnightly Statistics Vol. 33 No. 21 (27 October 2026), table 07 commercial banks'' interest rates', 'https://www.boz.zm/sites/default/files/2026-10/StatisticsFortnightly2026Vol33IssueNo_21.pdf', '2026-10-31', 'Low case: 3-month time deposits (5.47%) and retail savings accounts (2.83%), tax free for individuals.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZM', 1, 'goal_inflation_education', 0.08, NULL, 'assumption', 'Zambia Statistics Agency, The Monthly, October 2026, education CPI (table 1.2)', 'https://www.zamstats.gov.zm/wp-content/uploads/2026/10/Vol-283-of-2026-The-Monthly-October.pdf', '2026-10-31', 'Education prices rose 4.6% in the year to October 2026 and about 5.8% a year since January 2023, below general inflation; fees jump each January, so the 8% inflation assumption is used.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZM', 1, 'goal_inflation_health', 0.095, NULL, 'assumption', 'Zambia Statistics Agency, The Monthly, October 2026, health CPI (table 1.2)', 'https://www.zamstats.gov.zm/wp-content/uploads/2026/10/Vol-283-of-2026-The-Monthly-October.pdf', '2026-10-31', 'Health prices rose 8.9% in the year to October 2026 and about 9.3% a year since January 2023 (index 286.2 to 400.0), so 1.5 points above the 8% inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZM', 1, 'gold_return_base', 0.08, NULL, 'assumption', 'World Bank official exchange rate, Zambia (PA.NUS.FCRF): about K10 per dollar in 2016, K25.3 in 2025 average, K20.2 in October 2026', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=ZM', '2026-10-31', 'Base case: the long-run dollar gold trend of about 4% a year plus about 4% a year of kwacha depreciation (the kwacha lost about 7% a year over 2016-2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZM', 1, 'gold_return_high', 0.14, NULL, 'assumption', 'World Bank official exchange rate, Zambia (PA.NUS.FCRF)', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=ZM', '2026-10-31', 'High case: strong gold years and a renewed fall in the kwacha.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZM', 1, 'gold_return_low', 0.02, NULL, 'assumption', 'World Bank official exchange rate, Zambia (PA.NUS.FCRF); Bank of Zambia exchange rates', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=ZM', '2026-10-31', 'Low case: flat dollar gold and a kwacha that stays near its 2026 level.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZM', 1, 'gratuity_rule', NULL, '{"daysPerYear":91.25,"daysPerYearAfter":null,"afterYears":null,"daysPerMonth":30.42}', 'sourced', 'Employment Code Act No. 3 of 2019, sections 54 and 73', 'https://www.parliament.gov.zm/sites/default/files/documents/acts/The%20Employment%20Code%20Act%20No.%203%20of%202019.pdf', '2019-04-11', 'Section 73: at the end of a long-term (fixed-term) contract, the employer pays a gratuity of at least 25% of the basic pay earned during the contract. That is 3 months'' pay per year, or 91.25 days counted at 30.42 days a month. Section 54: redundancy pays 2 months'' basic pay per year served. The law dates from 2019 (older than 2025); later amendments were not checked.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZM', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a major private hospital stay in Zambia was found from an official or international source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZM', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published private health insurance premiums by age were found from a public source; the National Health Insurance Scheme (NHIMA) is funded by a 1% employer and 1% employee contribution, not an age-rated premium.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZM', 1, 'inflation_cpi', 0.063, NULL, 'sourced', 'Bank of Zambia, inflation rates (Zambia Statistics Agency CPI), October 2026', 'https://www.boz.zm/monetary-policy/inflation', '2026-10-31', 'Annual CPI inflation 6.3% in October 2026 (BoZ page updated 29 October 2026), up from 6.1% in September (ZamStats, The Monthly, October 2026). It has been inside the Bank of Zambia''s 6-8% target band since February 2026 (7.5%), after 11.2% in December 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZM', 1, 'inflation_projection', 0.08, NULL, 'assumption', 'Bank of Zambia 6-8% inflation target band (MPC statement, September 2026); CPI averaged about 14% a year over 2021-2025', 'https://www.boz.zm/monetary-policy/monetary-policy-rate', '2026-10-31', 'Inflation only came back into the 6-8% band in 2026 after averaging roughly 14% a year in 2021-2025, so the top of the band (8%) is used for long-range plans.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZM', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'Term life cover is sold, but no published premium rates per K1,000 of cover by age were found from the regulator or another public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZM', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Pensions and Insurance Authority publishes no industry-wide life claim settlement ratio that could be found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZM', 1, 'life_expectancy', 66.528, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN), Zambia', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=ZM', '2024-12-31', '66.5 years in 2024 (men 64.1, women 68.9).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZM', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":16.4,"men":15.4,"women":17.4},{"age":65,"total":12.9,"men":12,"women":13.6},{"age":70,"total":9.7,"men":9,"women":10.3},{"age":80,"total":5.3,"men":4.9,"women":5.6}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/zambia/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZM', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Social Cash Transfer is targeted at poor households (including those with older members) rather than paid at a fixed age, and its current eligibility rules were not found on an official page.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZM', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'Zambia has no universal non-contributory old-age pension; the Social Cash Transfer (Ministry of Community Development and Social Services) is a poverty-targeted household transfer that includes elderly-headed households, and its current amount was not found on an official page.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZM', 1, 'oop_health_share', 0.1029, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), Zambia', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=ZM', '2023-12-31', '10.3% in 2023 (WHO Global Health Expenditure Database), the latest available; older than 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZM', 1, 'policy_rate', 0.1075, NULL, 'sourced', 'Bank of Zambia, Monetary Policy Rate (decision announced 30 September 2026)', 'https://www.boz.zm/monetary-policy/monetary-policy-rate', '2026-09-30', 'Cut by 250 basis points to 10.75%, effective 30 September 2026 (13.25% since May 2026). Next decision due 27 November 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZM', 1, 'public_pension_scheme', NULL, '{"entryAgeMin":16,"entryAgeMax":null,"pensionFromAge":60,"nomineeUntilAge":null,"inflationLinked":true,"taxFree":null}', 'sourced', 'National Pension Scheme Act No. 72 of 2026 (sections 2, 16, 29, 30, 48)', 'https://www.parliament.gov.zm/sites/default/files/documents/acts/Act%20No.%2072%2C%20The%20National%20Pension%20Scheme%20Act%20%281%29.pdf', '2026-06-04', 'NAPSA is compulsory social insurance for employees from age 16. The pension starts at 60 (early 55, late 65) after 180 monthly contributions. The minimum pension is 25% of national average earnings (s.30). Pensions are adjusted every year by an index based on national average earnings (s.48), which is set to inflationLinked true as the closest match. The Act does not state the tax treatment.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZM', 1, 'retirement_accumulation_return_base', 0.11, NULL, 'assumption', 'Bank of Zambia, GRZ bond auction results 25 September 2026; equity base 13%; gold base 8%', 'https://www.boz.zm/sites/default/files/2026-09/Bonds-Press-Results-07-2026-BA.pdf', '2026-10-31', 'Base case: a balanced mix of government bonds, local equity funds and some gold.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZM', 1, 'retirement_accumulation_return_high', 0.14, NULL, 'assumption', 'Bank of Zambia, GRZ bond auction results 25 September 2026; equity high 17%', 'https://www.boz.zm/sites/default/files/2026-09/Bonds-Press-Results-07-2026-BA.pdf', '2026-10-31', 'High case: a growth-leaning mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZM', 1, 'retirement_accumulation_return_low', 0.07, NULL, 'assumption', 'Bank of Zambia, Fortnightly Statistics Vol. 33 No. 21 (27 October 2026), table 07 commercial banks'' interest rates', 'https://www.boz.zm/sites/default/files/2026-10/StatisticsFortnightly2026Vol33IssueNo_21.pdf', '2026-10-31', 'Low case: a mix earning about after-tax deposit rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZM', 1, 'retirement_age_default', 60, NULL, 'sourced', 'National Pension Scheme Act No. 72 of 2026, sections 2 and 29', 'https://www.parliament.gov.zm/sites/default/files/documents/acts/Act%20No.%2072%2C%20The%20National%20Pension%20Scheme%20Act%20%281%29.pdf', '2026-06-04', 'Pensionable age is 60 for men and women; early retirement at 55 and late retirement at 65 with 12 months'' notice; a pension needs at least 180 monthly contributions. Act assented 4 June 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZM', 1, 'retirement_age_government', 60, NULL, 'sourced', 'Public Service Pensions Act No. 73 of 2026, sections 2 and 26', 'https://www.parliament.gov.zm/sites/default/files/documents/acts/Act%20No.%2073%20of%202026%2C%20Public%20Service%20Pensions.pdf', '2026-06-04', 'Public servants retire at the pensionable age of 60; early pensionable age 55 and late pensionable age 65 with notice and consent.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZM', 1, 'retirement_return_base', 0.09, NULL, 'assumption', 'Bank of Zambia, Fortnightly Statistics Vol. 33 No. 21 (27 October 2026), table 07 commercial banks'' interest rates; treasury bill auction 29 October 2026', 'https://www.boz.zm/sites/default/files/2026-10/StatisticsFortnightly2026Vol33IssueNo_21.pdf', '2026-10-31', 'Base case: mostly 12-month deposits (10.17%, tax free) and treasury bills, trimmed for the falling rate cycle; below the after-tax 1-year deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZM', 1, 'retirement_return_high', 0.11, NULL, 'assumption', 'Bank of Zambia, GRZ bond auction results, tender 07/2026/BA (25 September 2026)', 'https://www.boz.zm/sites/default/files/2026-09/Bonds-Press-Results-07-2026-BA.pdf', '2026-10-31', 'High case: part of the money in 2- to 3-year government bonds (12.0-12.6%, about 10.2-10.7% after 15% withholding tax) and some 10-year bonds (14.5%, about 12.3% after tax).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZM', 1, 'retirement_return_low', 0.06, NULL, 'assumption', 'Bank of Zambia, Fortnightly Statistics Vol. 33 No. 21 (27 October 2026), table 07 commercial banks'' interest rates', 'https://www.boz.zm/sites/default/files/2026-10/StatisticsFortnightly2026Vol33IssueNo_21.pdf', '2026-10-31', 'Low case: 3- to 6-month deposits (5.5-7.1%), tax free.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZM', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate or retail savings bond for individuals was found; individuals can bid for treasury bills and government bonds at Bank of Zambia auctions.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZM', 1, 'savings_account_rate', 0.0283, NULL, 'sourced', 'Bank of Zambia, Fortnightly Statistics Vol. 33 No. 21 (27 October 2026), table 07 commercial banks'' interest rates', 'https://www.boz.zm/sites/default/files/2026-10/StatisticsFortnightly2026Vol33IssueNo_21.pdf', '2026-10-09', 'Average retail savings-account rate 2.83% in the week ending 9 October 2026 (non-retail 3.48%). September 2026 retail average 2.81%. Current accounts pay 1.75%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZM', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":28.51},{"year":2040,"value":18.18},{"year":2065,"value":9.35}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/zambia/2040/', '2025-12-31', '100 / old-age dependency ratio: 3.51 (2025, World Bank), 5.5 (2040) and 10.7 (2065, populationpyramid.net/zambia/2065/).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZM', 1, 'tax_bank_interest', 0, NULL, 'sourced', 'PwC Worldwide Tax Summaries, Zambia, individual income determination', 'https://taxsummaries.pwc.com/zambia/individual/income-determination', '2026-07-24', 'Since 1 January 2022 interest earned by individuals on interest-earning accounts at banks and financial institutions licensed under the Banking and Financial Services Act is exempt (page reviewed 24 July 2026); other interest bears 15% final withholding tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZM', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate exists; for reference, coupon interest on government bonds bears 15% withholding tax (PwC Tax Summaries, reviewed 24 July 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZM', 1, 'tbill_91d_rate', 0.085, NULL, 'sourced', 'Bank of Zambia, Treasury bill auction results, tender 22/2026 (29 October 2026)', 'https://www.boz.zm/sites/default/files/2026-10/Treasury-Bills-Results-Tender-No-22-2026-29-10-2026.pdf', '2026-10-29', 'Cut-off yield 8.50% on the 91-day bill (9.00% in September); 182-day 9.10%, 273-day 9.50%, 364-day 10.00%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZM', 1, 'tbond_10y_rate', 0.145, NULL, 'sourced', 'Bank of Zambia, GRZ bond auction results, tender 07/2026/BA (25 September 2026)', 'https://www.boz.zm/sites/default/files/2026-09/Bonds-Press-Results-07-2026-BA.pdf', '2026-09-25', 'Cut-off yield 14.50% on the 10-year bond (16.60% coupon), down from 15.50% in August 2026; 15-year 15.45%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZM', 1, 'tbond_5y_rate', 0.1498, NULL, 'sourced', 'Bank of Zambia, Fortnightly Statistics Vol. 33 No. 21, table 06 GRZ bond yield rates (February 2026 auction)', 'https://www.boz.zm/sites/default/files/2026-10/StatisticsFortnightly2026Vol33IssueNo_21.pdf', '2026-02-28', 'The 5-year bond was last auctioned in February 2026 at 14.98% and has not been offered since; at the September 2026 auction the 3-year yielded 12.59% and the 7-year 13.75%, so current 5-year yields are likely near 13%.', 0);
INSERT INTO country_versions (country, version, status, created_at, published_at, published_by, note, meta) VALUES ('ZW', 1, 'published', '2026-10-31', '2026-10-31', 'seed', 'Research workflow, verified', '{"schemaVersion":1,"code":"ZW","iso3":"ZWE","nameEn":"Zimbabwe","nameNative":"Zimbabwe","region":"sub_saharan_africa","languages":["sn","en","nd"],"currency":{"code":"ZWG","symbol":"ZiG","decimals":2,"compact":"intl","usdRate":{"value":26.7965,"status":"sourced","sourceName":"Reserve Bank of Zimbabwe, Snapshot on monetary, currency, price and financial developments, Q3 2026 (key rates as at 30 September 2026), interbank exchange rate end-September 2026","sourceUrl":"https://www.rbz.co.zw/documents/press/2026/October/Snapshot_Q3_2026_vFinal_.pdf","asOf":"2026-09-30","note":"ZiG26.80 per US dollar at end-September 2026 (Q3 average 26.70; World Bank 2025 average 26.60). Most deposits, prices and wages in Zimbabwe are in US dollars alongside the ZiG."}},"instruments":{"savings_account":{"available":true,"localName":null,"localNameEn":"Savings account","note":"Offered in ZiG and US dollars; the Reserve Bank sets minimum rates.","sourceUrl":"https://www.rbz.co.zw/documents/press/2026/October/Snapshot_Q3_2026_vFinal_.pdf"},"fdr_3m":{"available":true,"localName":"Time deposit","localNameEn":"Time deposit","note":"Offered in ZiG and US dollars; the Reserve Bank sets a minimum time deposit rate.","sourceUrl":"https://www.rbz.co.zw/documents/press/2026/October/Snapshot_Q3_2026_vFinal_.pdf"},"fdr_1y":{"available":true,"localName":"Time deposit","localNameEn":"Time deposit, 12 months","sourceUrl":"https://www.rbz.co.zw/documents/press/2026/October/Snapshot_Q3_2026_vFinal_.pdf"},"dps":{"available":false,"localName":null,"localNameEn":null,"note":"No standard monthly recurring deposit product was found."},"sanchayapatra_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No government savings certificate or retail savings bond for individuals was found."},"tbill_91d":{"available":false,"localName":null,"localNameEn":null,"note":"No regular retail treasury bill auction was found; the Reserve Bank''s ZiG-Denominated Term Deposit Facility (30 and 90 days) is taken up mainly by banks and corporates.","sourceUrl":"https://www.rbz.co.zw/documents/press/2026/October/Snapshot_Q3_2026_vFinal_.pdf"},"tbond_5y":{"available":false,"localName":null,"localNameEn":null,"note":"No traded government bond market for individuals was found."},"tbond_10y":{"available":false,"localName":null,"localNameEn":null,"note":"No traded government bond market for individuals was found."},"equity_fund":{"available":true,"localName":"Unit trust","localNameEn":"Unit trusts (collective investment schemes)","note":"Supervised by the Securities and Exchange Commission of Zimbabwe."},"gold":{"available":true,"localName":"Mosi-oa-Tunya gold coin","localNameEn":"Gold coins issued by the Reserve Bank of Zimbabwe","note":"The Reserve Bank introduced Mosi-oa-Tunya gold coins for public sale in 2022; their 2026 availability could not be checked (RBZ site behind a bot check). Gold also backs the ZiG."}},"institutions":{"centralBank":{"name":"Reserve Bank of Zimbabwe","url":"https://www.rbz.co.zw/"},"insuranceRegulator":{"name":"Insurance and Pensions Commission (IPEC)","url":"https://ipec.co.zw/"},"insuranceComplaints":{"name":"IPEC consumer complaints procedure","url":"https://ipec.co.zw/consumer-complaints-procedure/"},"pensionScheme":{"name":"National Social Security Authority (NSSA), Pensions and Other Benefits Scheme","url":"https://www.nssa.org.zw/","note":"Site behind a bot check on 31 October 2026."},"oldAgeAllowance":null,"publicHealthCover":{"name":"Ministry of Health and Child Care (public health facilities)","url":"https://www.mohcc.gov.zw/","note":"No national health insurance scheme; site did not respond on 31 October 2026."},"depositInsurance":{"name":"Deposit Protection Corporation (DPC)","url":"https://dpcorp.co.zw/what-is-deposit-protection/"},"statistics":{"name":"Zimbabwe National Statistics Agency (ZIMSTAT)","url":"https://zimstat.co.zw/"}},"researchedAt":"2026-10-31","reviewedBy":"research-workflow"}');
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZW', 1, 'bank_deposit_avg_rate', 0.0624, NULL, 'sourced', 'World Bank WDI, deposit interest rate (FR.INR.DPST), Zimbabwe', 'https://data.worldbank.org/indicator/FR.INR.DPST?locations=ZW', '2025-12-31', '6.24% for 2025; the Reserve Bank''s statistics pages could not be read (bot check).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZW', 1, 'credit_card_rate_cap', NULL, NULL, 'missing', '', '', '2026-10-31', 'No legal cap or typical credit card rate was found; the Reserve Bank caps banks'' all-inclusive on-lending rate under the Targeted Finance Facility at 22.5%, which is not a card rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZW', 1, 'deposit_insurance_limit', 80390, NULL, 'sourced', 'Deposit Protection Corporation, what is deposit protection (cover limit)', 'https://dpcorp.co.zw/what-is-deposit-protection/', '2026-09-30', 'ZiG deposits are covered up to the ZiG equivalent of US$3,000 per deposit class per bank (US$2,000 at deposit-taking microfinance institutions); US$3,000 x ZiG26.7965 (end-September 2026 interbank rate) = about ZiG80,390.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZW', 1, 'dps_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No monthly recurring deposit product or published rate was found in Reserve Bank of Zimbabwe statistics.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZW', 1, 'equity_return_base', 0.1, NULL, 'assumption', 'Reserve Bank of Zimbabwe Q3 2026 snapshot (ZiG minimum time deposit rate 7.18%)', 'https://www.rbz.co.zw/documents/press/2026/October/Snapshot_Q3_2026_vFinal_.pdf', '2026-10-31', 'Base case: about 3 points above the ZiG time deposit floor, below the 4-point cap, because the local index has no meaningful 10-year record in today''s currency (the ZiG only began in April 2024).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZW', 1, 'equity_return_high', 0.16, NULL, 'assumption', 'Reserve Bank of Zimbabwe Q3 2026 snapshot', 'https://www.rbz.co.zw/documents/press/2026/October/Snapshot_Q3_2026_vFinal_.pdf', '2026-10-31', 'High case: a strong decade for local shares or a global index fund in ZiG terms.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZW', 1, 'equity_return_low', 0.03, NULL, 'assumption', 'Reserve Bank of Zimbabwe Q3 2026 snapshot; ZiG minimum time deposit rate 7.18%', 'https://www.rbz.co.zw/documents/press/2026/October/Snapshot_Q3_2026_vFinal_.pdf', '2026-10-31', 'Low case: local shares lose value in real terms, as they repeatedly did in earlier currency crises.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZW', 1, 'fdr_1y_rate', 0.0718, NULL, 'sourced', 'Reserve Bank of Zimbabwe, Snapshot on monetary, currency, price and financial developments, Q3 2026 (key rates as at 30 September 2026)', 'https://www.rbz.co.zw/documents/press/2026/October/Snapshot_Q3_2026_vFinal_.pdf', '2026-09-30', 'Same Reserve Bank minimum time deposit rate (ZiG 7.18%, US dollar 4.41%); no separate 1-year average is published.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZW', 1, 'fdr_3m_rate', 0.0718, NULL, 'sourced', 'Reserve Bank of Zimbabwe, Snapshot on monetary, currency, price and financial developments, Q3 2026 (key rates as at 30 September 2026)', 'https://www.rbz.co.zw/documents/press/2026/October/Snapshot_Q3_2026_vFinal_.pdf', '2026-09-30', 'Minimum time deposit rate set by the Reserve Bank: ZiG 7.18% (US dollar 4.41%), maintained by the MPC on 28 September 2026; no published average by term.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZW', 1, 'fixed_income_return_base', 0.065, NULL, 'assumption', 'Reserve Bank of Zimbabwe, Snapshot on monetary, currency, price and financial developments, Q3 2026 (key rates as at 30 September 2026)', 'https://www.rbz.co.zw/documents/press/2026/October/Snapshot_Q3_2026_vFinal_.pdf', '2026-10-31', 'Base case: ZiG time deposits at about the 7.18% minimum, less some withholding tax on interest.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZW', 1, 'fixed_income_return_high', 0.09, NULL, 'assumption', 'Reserve Bank of Zimbabwe, Snapshot on monetary, currency, price and financial developments, Q3 2026 (key rates as at 30 September 2026)', 'https://www.rbz.co.zw/documents/press/2026/October/Snapshot_Q3_2026_vFinal_.pdf', '2026-10-31', 'High case: ZiG term deposit facility bills (11% for 90 days) for savers with access, after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZW', 1, 'fixed_income_return_low', 0.04, NULL, 'assumption', 'Reserve Bank of Zimbabwe, Snapshot on monetary, currency, price and financial developments, Q3 2026 (key rates as at 30 September 2026)', 'https://www.rbz.co.zw/documents/press/2026/October/Snapshot_Q3_2026_vFinal_.pdf', '2026-10-31', 'Low case: ZiG savings accounts at about the 4.35% minimum.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZW', 1, 'goal_inflation_education', 0.09, NULL, 'assumption', 'ZIMSTAT, Price statistics August 2026', 'https://zimstat.co.zw/price-statistics-august-2026/', '2026-10-31', 'No education price index by division could be read, so school fees are assumed to rise with the 9% ZiG inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZW', 1, 'goal_inflation_health', 0.1, NULL, 'assumption', 'ZIMSTAT, Price statistics August 2026', 'https://zimstat.co.zw/price-statistics-august-2026/', '2026-10-31', 'No health price index by division could be read, so private medical costs, which are largely priced in US dollars, are assumed to rise 1 point faster than the 9% ZiG inflation assumption.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZW', 1, 'gold_return_base', 0.09, NULL, 'assumption', 'World Bank official exchange rate, Zimbabwe (PA.NUS.FCRF); RBZ Q3 2026 snapshot', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=ZW', '2026-10-31', 'Base case: the long-run dollar gold trend of about 4% a year plus about 5% a year of ZiG depreciation (inflation differential with the US dollar).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZW', 1, 'gold_return_high', 0.18, NULL, 'assumption', 'World Bank official exchange rate, Zimbabwe (PA.NUS.FCRF)', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=ZW', '2026-10-31', 'High case: strong gold years and another sharp ZiG devaluation like September 2024.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZW', 1, 'gold_return_low', 0.03, NULL, 'assumption', 'World Bank official exchange rate, Zimbabwe (PA.NUS.FCRF); RBZ interbank rate ZiG26.80 per US dollar (September 2026)', 'https://data.worldbank.org/indicator/PA.NUS.FCRF?locations=ZW', '2026-10-31', 'Low case: flat dollar gold and a stable ZiG.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZW', 1, 'gratuity_rule', NULL, NULL, 'missing', '', '', '2026-10-31', 'No statutory retirement gratuity could be confirmed: the Labour Act text could not be read from an official source (law repositories blocked access on 31 October 2026).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZW', 1, 'health_hospitalisation_cost', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published typical cost of a major private hospital stay in Zimbabwe was found from an official or international source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZW', 1, 'health_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published medical aid premiums by age were found from a public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZW', 1, 'inflation_cpi', 0.037, NULL, 'sourced', 'Reserve Bank of Zimbabwe, Snapshot on monetary, currency, price and financial developments, Q3 2026 (key rates as at 30 September 2026) (ZIMSTAT ZiG CPI)', 'https://www.rbz.co.zw/documents/press/2026/October/Snapshot_Q3_2026_vFinal_.pdf', '2026-09-30', 'Annual ZiG CPI inflation 3.7% in September 2026, up from 2.9% in August, the lowest since 1980. The Monetary Policy Committee expects it to end 2026 below 7%.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZW', 1, 'inflation_projection', 0.09, NULL, 'assumption', 'SADC 3-7% inflation benchmark cited by the Reserve Bank (Q3 2026 snapshot); history of currency collapses (World Bank CPI inflation 104.7% in 2022)', 'https://www.rbz.co.zw/documents/press/2026/October/Snapshot_Q3_2026_vFinal_.pdf', '2026-10-31', 'ZiG inflation is low in 2026, but the ZiG was devalued in September 2024 and earlier Zimbabwean currencies collapsed, so 9% (2 points above the top of the 3-7% band) is used for long-range ZiG plans.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZW', 1, 'insurance_term_premium_table', NULL, NULL, 'missing', '', '', '2026-10-31', 'No published term-life premium rates per ZiG 1,000 of cover by age were found from the regulator or another public source.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZW', 1, 'life_claim_settlement_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'The Insurance and Pensions Commission (IPEC) publishes no industry-wide life claim settlement ratio that could be found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZW', 1, 'life_expectancy', 63.064, NULL, 'sourced', 'World Bank WDI, life expectancy at birth, total (SP.DYN.LE00.IN), Zimbabwe', 'https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=ZW', '2024-12-31', '63.1 years in 2024 (men 60.5, women 65.3).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZW', 1, 'life_table_remaining', NULL, '{"rows":[{"age":60,"total":16.2,"men":14.8,"women":17.5},{"age":65,"total":13.3,"men":12,"women":14.4},{"age":70,"total":10.6,"men":9.5,"women":11.6},{"age":80,"total":6.3,"men":5.6,"women":6.9}]}', 'sourced', 'UN World Population Prospects 2024 via populationpyramid.net', 'https://www.populationpyramid.net/mortality/zimbabwe/', '2026-07-01', 'Secondary source of UN WPP 2024 medium variant for 2026; totals at 60, 70 and 80 are the mean of men and women (only the 65 total is published there).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZW', 1, 'old_age_allowance_eligibility', NULL, NULL, 'missing', '', '', '2026-10-31', 'No universal non-contributory old-age pension with a fixed eligibility age was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZW', 1, 'old_age_allowance_monthly', NULL, NULL, 'missing', '', '', '2026-10-31', 'No universal non-contributory old-age pension was found; support for poor older people comes through poverty-targeted programmes of the Ministry of Public Service, Labour and Social Welfare, whose current amounts could not be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZW', 1, 'oop_health_share', 0.1063, NULL, 'sourced', 'World Bank WDI, out-of-pocket expenditure (% of current health expenditure), Zimbabwe', 'https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS?locations=ZW', '2023-12-31', '10.6% in 2023 (WHO Global Health Expenditure Database), the latest available; older than 2025.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZW', 1, 'policy_rate', 0.275, NULL, 'sourced', 'Reserve Bank of Zimbabwe, Resolutions of the Monetary Policy Committee meeting held on 28 September 2026', 'https://www.rbz.co.zw/documents/mps/2026/PRESS_STATEMENT-28_SEPTEMBER_2026_.pdf', '2026-09-28', 'Cut from 30% to 27.5% with immediate effect, a total cut of 7.5 points since June 2026 (it was 35% before). Minimum savings and time deposit rates were left unchanged.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZW', 1, 'public_pension_scheme', NULL, NULL, 'missing', '', '', '2026-10-31', 'The NSSA Pensions and Other Benefits Scheme (compulsory for employees) exists, but its current rules could not be read: the NSSA website and law repositories blocked access on 31 October 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZW', 1, 'retirement_accumulation_return_base', 0.08, NULL, 'assumption', 'Reserve Bank of Zimbabwe, Snapshot on monetary, currency, price and financial developments, Q3 2026 (key rates as at 30 September 2026); equity base 10%; gold base 9%', 'https://www.rbz.co.zw/documents/press/2026/October/Snapshot_Q3_2026_vFinal_.pdf', '2026-10-31', 'Base case: a balanced mix of ZiG deposits, equity funds and some gold.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZW', 1, 'retirement_accumulation_return_high', 0.12, NULL, 'assumption', 'Reserve Bank of Zimbabwe, Snapshot on monetary, currency, price and financial developments, Q3 2026 (key rates as at 30 September 2026); equity high 16%', 'https://www.rbz.co.zw/documents/press/2026/October/Snapshot_Q3_2026_vFinal_.pdf', '2026-10-31', 'High case: a growth-leaning mix.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZW', 1, 'retirement_accumulation_return_low', 0.05, NULL, 'assumption', 'Reserve Bank of Zimbabwe, Snapshot on monetary, currency, price and financial developments, Q3 2026 (key rates as at 30 September 2026)', 'https://www.rbz.co.zw/documents/press/2026/October/Snapshot_Q3_2026_vFinal_.pdf', '2026-10-31', 'Low case: a mix earning about ZiG deposit rates.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZW', 1, 'retirement_age_default', NULL, NULL, 'missing', '', '', '2026-10-31', 'The NSSA Pensions and Other Benefits Scheme sets the pension age for private-sector workers, but its rules could not be read: the NSSA website and the law repositories (ZimLII, Veritas, ILO NATLEX) blocked access on 31 October 2026.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZW', 1, 'retirement_age_government', NULL, NULL, 'missing', '', '', '2026-10-31', 'The public service retirement age could not be confirmed from an official source that could be read.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZW', 1, 'retirement_return_base', 0.06, NULL, 'assumption', 'Reserve Bank of Zimbabwe, Snapshot on monetary, currency, price and financial developments, Q3 2026 (key rates as at 30 September 2026)', 'https://www.rbz.co.zw/documents/press/2026/October/Snapshot_Q3_2026_vFinal_.pdf', '2026-10-31', 'Base case: ZiG time deposits at about the 7.18% minimum less withholding tax on interest; not above the after-tax deposit rate.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZW', 1, 'retirement_return_high', 0.075, NULL, 'assumption', 'Reserve Bank of Zimbabwe, Snapshot on monetary, currency, price and financial developments, Q3 2026 (key rates as at 30 September 2026)', 'https://www.rbz.co.zw/documents/press/2026/October/Snapshot_Q3_2026_vFinal_.pdf', '2026-10-31', 'High case: part of the money in ZiG term deposit facility bills (8-11%) after tax.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZW', 1, 'retirement_return_low', 0.04, NULL, 'assumption', 'Reserve Bank of Zimbabwe, Snapshot on monetary, currency, price and financial developments, Q3 2026 (key rates as at 30 September 2026)', 'https://www.rbz.co.zw/documents/press/2026/October/Snapshot_Q3_2026_vFinal_.pdf', '2026-10-31', 'Low case: ZiG savings accounts at about the 4.35% minimum.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZW', 1, 'sanchayapatra_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate or retail savings bond for individuals was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZW', 1, 'savings_account_rate', 0.0435, NULL, 'sourced', 'Reserve Bank of Zimbabwe, Snapshot on monetary, currency, price and financial developments, Q3 2026 (key rates as at 30 September 2026)', 'https://www.rbz.co.zw/documents/press/2026/October/Snapshot_Q3_2026_vFinal_.pdf', '2026-09-30', 'Minimum savings deposit rate set by the Reserve Bank: ZiG 4.35% (US dollar deposits 2.15%); banks may pay more, but no average actual rate is published.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZW', 1, 'support_ratio', NULL, '{"points":[{"year":2025,"value":15.77},{"year":2040,"value":18.87},{"year":2065,"value":10.42}]}', 'sourced', 'World Bank SP.POP.DPND.OL (2025); UN WPP 2024 via populationpyramid.net (2040, 2065)', 'https://www.populationpyramid.net/zimbabwe/2040/', '2025-12-31', '100 / old-age dependency ratio. 6.34 for 2025 (World Bank; populationpyramid.net also shows 6.3), 5.3 for 2040 and 9.6 for 2065 (populationpyramid.net/zimbabwe/2065/). The ratio rises to 2040 because the working-age population grows faster than the 65+ population.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZW', 1, 'tax_bank_interest', NULL, NULL, 'missing', '', '', '2026-10-31', 'The withholding tax rate on bank interest could not be read from ZIMRA''s tax-rates page; ZIMRA does state that persons aged 55 or more get an annual exemption on interest from deposits with financial institutions.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZW', 1, 'tax_sanchayapatra_profit', NULL, NULL, 'missing', '', '', '2026-10-31', 'No government savings certificate exists.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZW', 1, 'tbill_91d_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No regular treasury bill auction yield was found; the Reserve Bank''s ZiG-Denominated Term Deposit Facility pays 8% (30 days) and 11% (90 days) but is taken up mainly by banks and corporates (Q3 2026 snapshot).', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZW', 1, 'tbond_10y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No market yield for a 10-year government bond was found.', 0);
INSERT INTO country_fields (country, version, field, value, value_json, status, source_name, source_url, as_of, note, absent) VALUES ('ZW', 1, 'tbond_5y_rate', NULL, NULL, 'missing', '', '', '2026-10-31', 'No market yield for a 5-year government bond was found.', 0);
